--
-- Name: apply_before_committed_replay_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_committed_replay_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;captured gridex_received_sources.sources%rowtype;
 canonical gridex_received_sources.validation_assessments%rowtype;prior gridex_ack_authority.source_correlations%rowtype;
 a jsonb;s jsonb;family text;outcome text;scope text;refs jsonb;results jsonb;result jsonb;expected jsonb;ids uuid[];all_positive boolean;all_answered boolean;whole_negative boolean;source_accepted boolean;
 contrl text;aperak text;utilts_err text;final_ack boolean;failure text;existing_status text;
BEGIN
 IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production') OR p_ack_message_id IS NULL
  OR p_source_message_id IS NULL OR p_actor_user_id IS NULL OR p_ack_message_id=p_source_message_id THEN RAISE EXCEPTION 'ack_execution_scope_required' USING ERRCODE='22023'; END IF;
 -- Prevent concurrent insertion/send/seal from changing the global candidate
 -- universe during qualification. This is intentionally conservative; a future
 -- equivalent namespace index may reduce locking without relaxing uniqueness.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active' FOR SHARE;
 IF NOT FOUND OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501'; END IF;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id
  AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501'; END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment AND direction='outbound' FOR UPDATE;
 SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment AND direction='inbound' FOR UPDATE;
 IF ack.id IS NULL OR source.id IS NULL OR source.message_sent_at IS NULL OR source.immutable_rendered_at IS NULL
  OR source.requires_contrl IS NULL OR source.requires_aperak IS NULL OR source.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ack_sealed_sent_original_required' USING ERRCODE='23514'; END IF;
 SELECT * INTO captured FROM gridex_received_sources.sources WHERE source_message_id=ack.id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
 IF captured.source_message_id IS NULL OR captured.raw_payload IS DISTINCT FROM ack.raw_payload OR captured.payload_hash IS DISTINCT FROM ack.immutable_payload_hash
  OR captured.payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') OR captured.received_context IS NULL
  OR captured.source_received_at IS NULL OR source.message_sent_at>captured.source_received_at THEN RAISE EXCEPTION 'ack_authentic_received_source_required' USING ERRCODE='23514'; END IF;
 SELECT * INTO prior FROM gridex_ack_authority.source_correlations WHERE ack_message_id=ack.id;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=ack.id AND v.company_id=p_company_id AND v.environment=p_environment
  AND v.source_payload_hash=captured.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted'
  AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted'
  AND ((prior.ack_message_id IS NOT NULL AND v.id=prior.canonical_assessment_id) OR (prior.ack_message_id IS NULL AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id))) FOR SHARE;
 IF canonical.id IS NULL THEN RAISE EXCEPTION 'ack_current_canonical_acceptance_required' USING ERRCODE='23514'; END IF;
 a:=gridex_ack_authority.wire_v1(ack.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 IF a IS NULL OR s IS NULL OR a->>'environment' IS DISTINCT FROM p_environment OR s->>'environment' IS DISTINCT FROM p_environment
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ack_physical_original_scope_mismatch' USING ERRCODE='23514'; END IF;
 SELECT array_agg(m.id ORDER BY m.id) INTO ids FROM public.ediel_messages m WHERE m.direction='outbound' AND m.message_sent_at IS NOT NULL AND m.immutable_rendered_at IS NOT NULL
  AND m.immutable_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND gridex_ack_authority.source_match_v1(a,gridex_ack_authority.wire_v1(m.raw_payload));
 IF cardinality(ids) IS DISTINCT FROM 1 OR ids[1] IS DISTINCT FROM source.id THEN RAISE EXCEPTION 'ack_physical_original_ambiguous' USING ERRCODE='23514'; END IF;
 IF a->>'family'='CONTRL' THEN
  family:='CONTRL';scope:='interchange';refs:=jsonb_build_array(a->>'uciRef');outcome:=CASE a->>'uciAction' WHEN '1' THEN 'positive' WHEN '4' THEN 'negative' END;
 ELSIF a->>'family'='UTILTS' AND a->>'code'='ERR' AND a->'errStatus'='true'::jsonb THEN
  family:='UTILTS_ERR';scope:='transaction';refs:=a#>'{refs,TN}';outcome:='negative';
 ELSIF a->>'family'='APERAK' AND a#>>'{type,2}'='04A' AND a#>>'{type,4}'='E5SE5A' THEN
  family:='APERAK';refs:=coalesce(a#>'{refs,ACW}','[]');scope:=CASE WHEN jsonb_array_length(refs)>0 THEN 'transaction' ELSE 'message' END;
  outcome:=CASE a->>'code' WHEN '312' THEN 'positive' WHEN '313' THEN 'negative' END;
  IF outcome='positive' AND scope<>'transaction' THEN RAISE EXCEPTION 'ack_positive_own_transaction_required'; END IF;
 ELSIF a->>'family'='APERAK' AND a#>>'{type,2}'='96A' AND a#>>'{type,4}'='E2SE6A' THEN
  family:='APERAK';refs:=coalesce(a#>'{refs,LI}','[]');scope:=CASE WHEN a->>'function'='34' THEN 'object' ELSE 'message' END;
  IF a->>'function'='27' AND NOT coalesce(a->'erc','[]') ? '100' THEN outcome:='negative';
  ELSIF a->>'function'='34' AND jsonb_array_length(coalesce(a->'erc','[]'))>0 THEN outcome:=CASE WHEN EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc') x WHERE x<>'100') THEN 'negative' ELSE 'positive' END; END IF;
  IF outcome='negative' AND a->>'function'='34' AND scope<>'object' THEN RAISE EXCEPTION 'ack_processed_negative_scope_unavailable'; END IF;
 ELSE RAISE EXCEPTION 'ack_canonical_family_unavailable'; END IF;
 IF family IS DISTINCT FROM ack.message_family OR outcome IS NULL OR (scope IN ('transaction','object') AND jsonb_array_length(coalesce(refs,'[]'))=0 AND NOT(family='APERAK' AND a#>>'{type,2}'='96A' AND a->>'function'='34')) THEN RAISE EXCEPTION 'ack_canonical_outcome_unavailable'; END IF;
 IF scope='object' THEN
  results:=gridex_ack_authority.prodat_physical_outcomes_v1(ack.raw_payload,source.raw_payload,source.id);
  IF EXISTS(SELECT FROM jsonb_array_elements_text(refs) ref WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(results) x WHERE x->>'reference'=ref)) THEN RAISE EXCEPTION 'ack_object_outcome_scope_unavailable'; END IF;
 ELSE SELECT coalesce(jsonb_agg(jsonb_build_object('reference',ref,'outcome',outcome)),'[]') INTO results
  FROM jsonb_array_elements_text(CASE WHEN scope='message' THEN jsonb_build_array(s->>'document') ELSE refs END) ref; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(results) x JOIN jsonb_array_elements(results) y ON x->>'reference'=y->>'reference' AND x->>'outcome'<>y->>'outcome') THEN RAISE EXCEPTION 'ack_scope_outcome_conflict'; END IF;
 SELECT * INTO prior FROM gridex_ack_authority.source_correlations WHERE ack_message_id=ack.id;
 IF prior.ack_message_id IS NOT NULL THEN
  IF ROW(prior.source_message_id,prior.company_id,prior.environment,prior.ack_payload_hash,prior.source_payload_hash,prior.ack_family,prior.ack_outcome,prior.ack_scope,prior.scope_outcomes)
   IS DISTINCT FROM ROW(source.id,p_company_id,p_environment,captured.payload_hash,source.immutable_payload_hash,family,outcome,scope,results) THEN RAISE EXCEPTION 'ack_immutable_correlation_conflict'; END IF;
 ELSE
  PERFORM gridex_ediel_inbound_context.require_ack_v1(ack,source);
  IF EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes old JOIN jsonb_array_elements(results) x ON
     (old.ack_scope='message' OR scope='message' OR old.source_reference=x->>'reference') AND old.outcome<>x->>'outcome'
     WHERE old.source_message_id=source.id AND old.ack_family=family) THEN RAISE EXCEPTION 'ack_immutable_scope_outcome_conflict'; END IF;
  existing_status:=CASE family WHEN 'CONTRL' THEN source.contrl_status WHEN 'APERAK' THEN source.aperak_status ELSE source.utilts_err_status END;
  IF existing_status IN ('received','failed') AND NOT EXISTS(SELECT FROM gridex_ack_authority.source_correlations old WHERE old.source_message_id=source.id AND old.ack_family=family) THEN RAISE EXCEPTION 'ack_legacy_outcome_requires_original_evidence'; END IF;
  INSERT INTO gridex_ack_authority.source_correlations(ack_message_id,source_message_id,company_id,environment,ack_payload_hash,source_payload_hash,canonical_assessment_id,ack_family,ack_outcome,ack_scope,acknowledged_references,scope_outcomes,actor_user_id)
   VALUES(ack.id,source.id,p_company_id,p_environment,captured.payload_hash,source.immutable_payload_hash,canonical.id,family,outcome,scope,coalesce(refs,'[]'),results,p_actor_user_id);
  FOR result IN SELECT DISTINCT x FROM jsonb_array_elements(results) x LOOP
   INSERT INTO gridex_ack_authority.scope_outcomes(source_message_id,ack_family,ack_scope,source_reference,ack_message_id,outcome)
    VALUES(source.id,family,scope,result->>'reference',ack.id,result->>'outcome') ON CONFLICT DO NOTHING;
   IF NOT EXISTS(SELECT FROM public.ediel_ack_chains c WHERE c.company_id=p_company_id AND c.source_message_id=source.id AND c.ack_family=family AND c.ack_scope=scope AND c.transaction_reference IS NOT DISTINCT FROM CASE WHEN scope IN ('transaction','object') THEN result->>'reference' ELSE NULL END AND c.outcome=result->>'outcome') THEN
    INSERT INTO public.ediel_ack_chains(company_id,source_message_id,ack_message_id,ack_family,ack_scope,transaction_reference,outcome)
     VALUES(p_company_id,source.id,ack.id,family,scope,CASE WHEN scope IN ('transaction','object') THEN result->>'reference' ELSE NULL END,result->>'outcome');
   END IF;
  END LOOP;
 END IF;
 expected:=CASE WHEN s->>'family'='UTILTS' THEN coalesce(s->'ide','[]') ELSE gridex_ack_authority.prodat_expected_physical_scope_keys_v1(source.raw_payload,source.id) END;
 whole_negative:=EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.ack_family=family AND x.ack_scope IN ('message','interchange') AND x.outcome='negative');
 all_positive:=EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.ack_family=family AND x.ack_scope IN ('message','interchange') AND x.outcome='positive')
  OR (jsonb_array_length(expected)>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(expected) ref WHERE NOT EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.ack_family=family AND x.source_reference=ref AND x.outcome='positive')));
 all_answered:=whole_negative OR EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.ack_family=family AND x.ack_scope IN ('message','interchange'))
  OR (jsonb_array_length(expected)>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(expected) ref WHERE NOT EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.ack_family=family AND x.source_reference=ref)));
 contrl:=source.contrl_status;aperak:=source.aperak_status;utilts_err:=source.utilts_err_status;
 IF family='CONTRL' THEN contrl:=CASE WHEN whole_negative THEN 'failed' WHEN all_answered THEN 'received' ELSE contrl END;
 ELSIF family='APERAK' THEN aperak:=CASE WHEN whole_negative THEN 'failed' WHEN all_answered THEN 'received' ELSE aperak END;
 ELSE utilts_err:=CASE WHEN whole_negative THEN 'failed' ELSE 'received' END; END IF;
 final_ack:=all_answered AND (NOT source.requires_contrl OR coalesce(contrl IN ('received','sent','not_required'),false)) AND (NOT source.requires_aperak OR coalesce(aperak IN ('received','sent','not_required'),false))
  AND coalesce(utilts_err<>'pending',true);
 source_accepted:=final_ack AND (family<>'APERAK' OR all_positive) AND NOT EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=source.id AND x.outcome='negative');
 failure:=CASE WHEN whole_negative THEN family||' negative whole-source acknowledgement' ELSE source.failure_reason END;
 UPDATE public.ediel_messages SET contrl_status=contrl,aperak_status=aperak,utilts_err_status=utilts_err,
  status=CASE WHEN whole_negative THEN 'failed' WHEN source_accepted THEN 'acknowledged' ELSE status END,
  failure_reason=failure,failed_at=CASE WHEN whole_negative THEN coalesce(failed_at,now()) ELSE failed_at END,
  acknowledged_at=CASE WHEN source_accepted THEN coalesce(acknowledged_at,now()) ELSE acknowledged_at END,
  ack_due_at=CASE WHEN whole_negative OR final_ack THEN NULL ELSE ack_due_at END,updated_by=p_actor_user_id,updated_at=now()
  WHERE id=source.id AND company_id=p_company_id RETURNING * INTO source;
 UPDATE public.ediel_messages SET related_message_id=source.id,updated_by=p_actor_user_id,updated_at=now() WHERE id=ack.id AND company_id=p_company_id;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source),'outcome',outcome,'scope',scope,'scopeOutcomes',results,'finalAckReached',final_ack,'wholeSourceRejected',whole_negative,'sourceAccepted',source_accepted,'failureReason',failure,'idempotent',prior.ack_message_id IS NOT NULL);
END $$;

--
-- Name: apply_before_physical_outcomes_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_physical_outcomes_v1(c uuid, e text, aid uuid, o uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior jsonb;m public.ediel_messages%rowtype;BEGIN
 prior:=gridex_ack_authority.read_committed_v1(c,e,aid,actor);IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_unused_unh_v1(c,e,aid,o,actor);END IF;
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 prior:=gridex_ack_authority.read_committed_v1(c,e,aid,actor);IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_unused_unh_v1(c,e,aid,o,actor);END IF;
 PERFORM s.id FROM public.ediel_messages s WHERE s.id=o AND s.company_id=c AND s.environment=e AND direction='outbound' FOR UPDATE;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=aid AND company_id=c AND environment=e AND direction='inbound' FOR UPDATE;
 PERFORM gridex_ediel_ack_guide.require_unused_unh_v1(m.raw_payload,'inbound');
 RETURN gridex_ack_authority.apply_before_unused_unh_v1(c,e,aid,o,actor);END $$;

--
-- Name: apply_before_prodat_unused_document_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company uuid, p_environment text, p_ack uuid, p_original uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;prior boolean;m public.ediel_messages%rowtype;
BEGIN
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 prior:=EXISTS(SELECT FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_ack);
 result:=gridex_ack_authority.apply_before_received_err_response_v1(p_company,p_environment,p_ack,p_original,p_actor);
 IF NOT prior THEN
  SELECT * INTO m FROM public.ediel_messages WHERE id=p_ack;
  IF m.message_family='UTILTS_ERR' THEN PERFORM gridex_received_err_response.capture_v1(p_company,p_environment,p_ack);END IF;
 END IF;
 RETURN result;
END $$;

--
-- Name: apply_before_received_err_response_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_received_err_response_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior jsonb;result jsonb;
BEGIN
 -- Serialize with the existing actual apply candidate/row lock before the
 -- replay read, so concurrent same ACK callbacks cannot reapply a receipt.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 prior:=gridex_ack_authority.read_committed_v1(p_company_id,p_environment,p_ack_message_id,p_actor_user_id);
 IF prior IS NOT NULL THEN
  IF prior->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text THEN RAISE EXCEPTION 'ack_immutable_correlation_conflict';END IF;
  IF prior->>'kind'='exact_receipt' THEN RETURN prior->'result'||jsonb_build_object('idempotent',true);END IF;
  RETURN prior;
 END IF;
 result:=gridex_ack_authority.apply_before_committed_replay_v1(p_company_id,p_environment,p_ack_message_id,p_source_message_id,p_actor_user_id);
 INSERT INTO gridex_ack_authority.applied_receipts(ack_message_id,result) VALUES(p_ack_message_id,result);
 RETURN result;
END $$;

--
-- Name: apply_before_reference_profile_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_reference_profile_v1(p_company uuid, p_environment text, p_ack uuid, p_original uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior jsonb;m public.ediel_messages%rowtype;
BEGIN
 -- Unchanged actual committed reader verifies current actor, own source/hash
 -- and frozen outcomes before contemporary validation. The delegate retains
 -- its exact source argument and immutable-replay checks.
 prior:=gridex_ack_authority.read_committed_v1(p_company,p_environment,p_ack,p_actor);
 IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);END IF;
 -- Preserve the existing apply source->ACK lock order and candidate mutex.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 -- A concurrent first application may have committed while obtaining the
 -- existing mutex. Re-read the immutable owner before any fresh guard.
 prior:=gridex_ack_authority.read_committed_v1(p_company,p_environment,p_ack,p_actor);
 IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);END IF;
 PERFORM id FROM public.ediel_messages WHERE id=p_original AND company_id=p_company AND environment=p_environment AND direction='outbound' FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_ack AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR UPDATE;
 IF m.id IS NOT NULL THEN PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(m.raw_payload);END IF;
 RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);
END$$;

--
-- Name: apply_before_unused_unh_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_before_unused_unh_v1(c uuid, e text, aid uuid, o uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior jsonb;m public.ediel_messages%rowtype;BEGIN
 prior:=gridex_ack_authority.read_committed_v1(c,e,aid,actor);IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_reference_profile_v1(c,e,aid,o,actor);END IF;
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 prior:=gridex_ack_authority.read_committed_v1(c,e,aid,actor);IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_reference_profile_v1(c,e,aid,o,actor);END IF;
 PERFORM s.id FROM public.ediel_messages s WHERE s.id=o AND s.company_id=c AND s.environment=e AND direction='outbound' FOR UPDATE;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=aid AND company_id=c AND environment=e AND direction='inbound' FOR UPDATE;
 PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(m.raw_payload);
 RETURN gridex_ack_authority.apply_before_reference_profile_v1(c,e,aid,o,actor);END $$;

--
-- Name: apply_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.apply_v1(c uuid, env text, ack_id uuid, source_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;prior boolean;a jsonb;ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;correlation gridex_ack_authority.source_correlations%rowtype;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 prior:=EXISTS(SELECT FROM gridex_ack_authority.source_correlations WHERE ack_message_id=ack_id);
 PERFORM gridex_ack_authority.require_physical_actor_v1(c,actor,NOT prior);
 result:=gridex_ack_authority.apply_before_physical_outcomes_v1(c,env,ack_id,source_id,actor);
 IF NOT prior THEN
  SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=env;
  a:=gridex_ack_authority.wire_v1(ack.raw_payload);
  IF ack.message_family='APERAK' AND a#>>'{type,2}'='96A' AND a#>>'{type,4}'='E2SE6A' AND a->>'function'='34' THEN
   SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c AND environment=env;
   SELECT * INTO STRICT correlation FROM gridex_ack_authority.source_correlations WHERE ack_message_id=ack_id AND source_message_id=source_id AND company_id=c AND environment=env;
   INSERT INTO gridex_ack_authority.prodat_physical_receipts(ack_message_id,source_message_id,company_id,environment,ack_payload_hash,source_payload_hash,scopes,source_projection_version)
    VALUES(ack_id,source_id,c,env,correlation.ack_payload_hash,correlation.source_payload_hash,gridex_ack_authority.prodat_physical_outcomes_v1(ack.raw_payload,source.raw_payload,source_id),gridex_ack_authority.prodat_physical_source_projection_version_v1());
  END IF;
 END IF;
 IF prior THEN PERFORM gridex_ack_authority.read_committed_v1(c,env,ack_id,actor);END IF;
 PERFORM gridex_ack_authority.require_physical_actor_v1(c,actor,NOT prior);
 RETURN result;
END$$;

--
-- Name: capture_received_ack_v1(); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.capture_received_ack_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.direction='inbound' AND NEW.message_family IN ('CONTRL','APERAK','UTILTS_ERR') AND NEW.message_standard='edifact'
  AND NEW.execution_context_snapshot ? 'receivedAckContext' THEN
  INSERT INTO gridex_received_sources.sources(source_message_id,company_id,environment,origin,message_code,source_received_at,captured_at,raw_payload,payload_hash,received_context)
   VALUES(NEW.id,NEW.company_id,NEW.environment,'database_insert',NEW.message_code,NEW.message_received_at,clock_timestamp(),NEW.raw_payload,
     NEW.immutable_payload_hash,NEW.execution_context_snapshot->'receivedAckContext');
 END IF;
 RETURN NEW;
END $$;

--
-- Name: prodat_correction_objects_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_correction_objects_v1(c uuid, env text, ack_id uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;source public.ediel_messages%rowtype;objects jsonb;scopes jsonb;scope jsonb;own jsonb;lin jsonb;obj jsonb;result jsonb:='[]';tokens jsonb;BEGIN
 receipt:=gridex_ack_authority.prodat_physical_receipt_v1(c,env,ack_id,source_id);IF receipt IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id;
 objects:=gridex_ack_authority.prodat_physical_recovery_wire_v1(source.raw_payload)->'objects';tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 scopes:=gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload);
 FOR scope IN SELECT x FROM jsonb_array_elements(receipt->'physicalOutcomes')x WHERE x->>'outcome'='negative' LOOP
  SELECT x INTO STRICT own FROM jsonb_array_elements(scopes)x WHERE x->'lineIndex'=scope#>'{physicalReference,firstLineIndex}' AND x->>'id' IS NOT DISTINCT FROM scope#>>'{physicalReference,objectId}' AND x->>'identityAgency' IS NOT DISTINCT FROM scope#>>'{physicalReference,identityAgency}' AND x->>'li' IS NOT DISTINCT FROM scope#>>'{physicalReference,lineItemReference}';
  FOR lin IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND own->'registerLineIndices' @> jsonb_build_array(x->'index') ORDER BY(x->>'index')::int LOOP
   SELECT x INTO STRICT obj FROM jsonb_array_elements(objects)x WHERE x->'physicalLineIndex'=lin->'index';
   IF obj IS NULL OR obj->>'point' IS DISTINCT FROM nullif(lin#>>'{elements,3,0}','') OR obj->>'identityAgency' IS DISTINCT FROM lin#>>'{elements,3,3}' THEN RAISE EXCEPTION 'ack_prodat_negative_correction_scope_ambiguous';END IF;
   result:=result||jsonb_build_array(obj-'physicalLineIndex');
  END LOOP;
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO result FROM jsonb_array_elements(result)x;RETURN result;
END$$;

--
-- Name: prodat_expected_physical_scope_keys_v1(text, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_expected_physical_scope_keys_v1(raw text, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE own jsonb;result jsonb:='[]';BEGIN
 FOR own IN SELECT x FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_source_objects_v1(raw))x LOOP
  result:=result||jsonb_build_array(gridex_ack_authority.prodat_physical_scope_key_v1(source_id,(own->>'lineIndex')::int,own->>'li'));
 END LOOP;RETURN result;
END$$;

--
-- Name: prodat_physical_outcomes_v1(text, text, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_outcomes_v1(raw text, source_raw text, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE scopes jsonb;scope jsonb;tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(source_raw);lin jsonb;result jsonb:='[]';li text;BEGIN
 -- Reuse the actual native raw-scope projection, after the incoming owner has
 -- qualified canonical acceptance, retained ingress and unique sent original.
 scopes:=gridex_ack_authority.prodat_physical_scoped_outcomes_v1(raw,source_raw);
 FOR scope IN SELECT x FROM jsonb_array_elements(scopes)x LOOP
  IF scope->>'scope' IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ack_prodat_physical_object_scope_required';END IF;
  SELECT x INTO STRICT lin FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x->>'index'=scope#>>'{physicalReference,lineIndex}';
  li:=nullif(scope#>>'{physicalReference,li}','');
  IF li IS NULL AND scope->>'outcome'<>'negative' THEN RAISE EXCEPTION 'ack_prodat_missing_li_positive_forbidden';END IF;
  result:=result||jsonb_build_array(jsonb_build_object('reference',gridex_ack_authority.prodat_physical_scope_key_v1(source_id,(lin->>'index')::int,li),'outcome',scope->>'outcome',
   'physicalReference',jsonb_build_object('firstLineIndex',(lin->>'index')::int,'objectId',nullif(lin#>>'{elements,3,0}',''),'identityAgency',nullif(lin#>>'{elements,3,3}',''),'lineItemReference',li)));
 END LOOP;
 RETURN result;
END$$;

--
-- Name: prodat_physical_receipt_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_receipt_v1(c uuid, env text, ack_id uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_ack_authority.prodat_physical_receipts%rowtype;correlation gridex_ack_authority.source_correlations%rowtype;ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;BEGIN
 SELECT * INTO r FROM gridex_ack_authority.prodat_physical_receipts WHERE ack_message_id=ack_id FOR SHARE;
 IF r.ack_message_id IS NULL THEN RETURN NULL;END IF;
 IF r.source_projection_version IS DISTINCT FROM gridex_ack_authority.prodat_physical_source_projection_version_v1() THEN RAISE EXCEPTION 'ack_prodat_physical_projection_version_unavailable';END IF;
 SELECT * INTO correlation FROM gridex_ack_authority.source_correlations WHERE ack_message_id=ack_id FOR SHARE;
 SELECT * INTO source FROM public.ediel_messages WHERE id=source_id FOR SHARE;
 SELECT * INTO ack FROM public.ediel_messages WHERE id=ack_id FOR SHARE;
 IF r.company_id IS DISTINCT FROM c OR r.environment IS DISTINCT FROM env OR r.source_message_id IS DISTINCT FROM source_id
  OR correlation.source_message_id IS DISTINCT FROM source_id OR correlation.company_id IS DISTINCT FROM c OR correlation.environment IS DISTINCT FROM env OR correlation.ack_scope IS DISTINCT FROM 'object'
  OR correlation.ack_payload_hash IS DISTINCT FROM r.ack_payload_hash OR correlation.source_payload_hash IS DISTINCT FROM r.source_payload_hash OR correlation.scope_outcomes IS DISTINCT FROM r.scopes
  OR ack.company_id IS DISTINCT FROM c OR ack.environment IS DISTINCT FROM env OR ack.direction IS DISTINCT FROM 'inbound' OR ack.message_family IS DISTINCT FROM 'APERAK'
  OR source.company_id IS DISTINCT FROM c OR source.environment IS DISTINCT FROM env OR source.direction IS DISTINCT FROM 'outbound' OR source.message_family IS DISTINCT FROM 'PRODAT'
  OR source.message_sent_at IS NULL OR source.immutable_payload_hash IS DISTINCT FROM r.source_payload_hash
  OR r.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') OR r.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex')
  OR NOT EXISTS(SELECT FROM gridex_ack_authority.applied_receipts a WHERE a.ack_message_id=ack_id AND a.result->'scopeOutcomes'=r.scopes)
  OR r.scopes IS DISTINCT FROM gridex_ack_authority.prodat_physical_outcomes_v1(ack.raw_payload,source.raw_payload,source_id) THEN RAISE EXCEPTION 'ack_prodat_physical_receipt_changed';END IF;
 RETURN jsonb_build_object('version',1,'companyId',c,'environment',env,'ackMessageId',ack_id,'sourceMessageId',source_id,'ackPayloadHash',r.ack_payload_hash,'sourcePayloadHash',r.source_payload_hash,'sourceProjectionVersion',r.source_projection_version,'physicalOutcomes',r.scopes);
END$$;

--
-- Name: prodat_physical_recovery_wire_v1(text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_recovery_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNT')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNZ')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='UNB' THEN out:=out||jsonb_build_object('interchange',e#>>'{5,0}','transportSender',e#>'{2}','transportReceiver',e#>'{3}');END IF;
  IF t->>'tag'='UNH' THEN out:=out||jsonb_build_object('family',e#>>'{2,0}','messageReference',e#>>'{1,0}','version',e#>'{2}');END IF;
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}','function',e#>>'{3,0}');END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'legalSender' ELSE 'legalReceiver' END;IF out ? key THEN RETURN NULL;END IF;out:=out||jsonb_build_object(key,e#>>'{2,0}');END IF;
  IF t->>'tag'='LIN' THEN IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;obj:=jsonb_build_object('point',nullif(e#>>'{3,0}', ''),'identityAgency',e#>>'{3,3}','physicalLineIndex',(t->>'index')::int);characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}'='LI' THEN key:='li';value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' AND characteristic='Z13' THEN key:='reason';value:=e#>>'{1,0}';END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL;END IF;obj:=obj||jsonb_build_object(key,value);END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]'::jsonb) INTO objects FROM jsonb_array_elements(objects) x;
 RETURN out||jsonb_build_object('objects',objects,'tokens',tokens);
END $$;

--
-- Name: prodat_physical_scope_key_v1(uuid, integer, text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_scope_key_v1(source_id uuid, line_index integer, li text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(li,'@prodat-physical-source:'||source_id::text||':lin:'||line_index::text)
$$;

--
-- Name: prodat_physical_scoped_outcomes_v1(text, text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_scoped_outcomes_v1(raw text, source_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb:=gridex_ack_authority.wire_v1(raw);s jsonb:=gridex_ack_authority.wire_v1(source_raw);tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);original jsonb:=gridex_utilts_binding.wire_tokens_v1(source_raw);t jsonb;g jsonb;source_objects jsonb;matches jsonb;result jsonb:='[]';group_end integer;own_li text;own_object text;erc_index integer:=0;outcome text;
BEGIN
 IF a IS NULL OR s IS NULL OR a->>'family'<>'APERAK' OR a#>>'{type,2}'<>'96A' OR a#>>'{type,4}'<>'E2SE6A' OR s->>'family'<>'PRODAT' OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 IF a->>'function'='27' THEN
  IF jsonb_array_length(coalesce(a->'erc','[]'))=0 OR EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc')e WHERE e='100') THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  RETURN jsonb_build_array(jsonb_build_object('scope','message','reference',coalesce(s->>'document',''),'physicalReference',jsonb_build_object('documentId',s->>'document'),'outcome','negative'));
 END IF;
 IF a->>'function' IS DISTINCT FROM '34' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 source_objects:=gridex_ack_authority.prodat_physical_source_objects_v1(source_raw);
 IF EXISTS(SELECT FROM jsonb_array_elements(original)lin WHERE lin->>'tag'='LIN' AND (SELECT count(*) FROM jsonb_array_elements(original)r WHERE r->>'tag'='RFF' AND r#>>'{elements,1,0}'='LI' AND(r->>'index')::int>(lin->>'index')::int AND(r->>'index')::int<coalesce((SELECT min((n->>'index')::int) FROM jsonb_array_elements(original)n WHERE n->>'tag' IN('LIN','UNT') AND(n->>'index')::int>(lin->>'index')::int),2147483647))>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::int LOOP
  SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>(t->>'index')::int AND x->>'tag' IN('ERC','UNT','UNZ');
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' IN('LI','Z07') AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end GROUP BY x#>>'{elements,1,0}' HAVING count(*)>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  SELECT min(x#>>'{elements,1,1}') INTO own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT min(x#>>'{elements,1,1}') INTO own_object FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT jsonb_agg(x) INTO matches FROM jsonb_array_elements(source_objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_object END AND(own_object IS NULL OR x->>'id'=own_object);
  IF jsonb_array_length(coalesce(matches,'[]'))<>1 THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  -- Outcome is the existing native wire owner's own ERC ordinal projection.
  -- No national error code or field label is selected or inferred here.
  IF a->'erc'->>erc_index IS DISTINCT FROM t#>>'{elements,1,0}' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  outcome:=CASE WHEN a->'erc'->>erc_index='100' THEN 'positive' ELSE 'negative' END;erc_index:=erc_index+1;
  g:=jsonb_build_object('scope','object','reference',matches#>>'{0,lineIndex}','physicalReference',matches->0,'outcome',outcome);result:=result||jsonb_build_array(g);
 END LOOP;
 IF jsonb_array_length(result)=0 OR EXISTS(SELECT FROM jsonb_array_elements(result)x GROUP BY x->>'scope',x->>'reference' HAVING count(DISTINCT x->>'outcome')<>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_contradictory_own_outcome';END IF;
 SELECT jsonb_agg(x ORDER BY x->>'reference') INTO result FROM(SELECT DISTINCT x FROM jsonb_array_elements(result)x)unique_scopes;RETURN result;
END $$;

--
-- Name: prodat_physical_source_objects_v1(text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_source_objects_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);source jsonb:=gridex_ack_authority.wire_v1(raw);lines jsonb:='[]';lin jsonb;own jsonb;siblings jsonb;result jsonb:='[]';e jsonb;stop int;li text;ordinal int:=0;multi boolean;valid boolean;count_li int;BEGIN
 IF tokens IS NULL OR source->>'family' IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'ack_prodat_physical_source_required';END IF;
 FOR lin IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' ORDER BY(x->>'index')::int LOOP
  e:=lin->'elements';ordinal:=ordinal+1;
  SELECT min((x->>'index')::int) INTO stop FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>(lin->>'index')::int AND x->>'tag' IN('NAD','LIN','UNT');
  SELECT count(*),min(nullif(x#>>'{elements,1,1}','')) INTO count_li,li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::int>(lin->>'index')::int AND(x->>'index')::int<stop;
  IF count_li>1 THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  lines:=lines||jsonb_build_array(jsonb_build_object('lineIndex',(lin->>'index')::int,'id',nullif(e#>>'{3,0}',''),'identityAgency',nullif(e#>>'{3,3}',''),'li',li,
   'sequenceValid',coalesce(jsonb_array_length(e->1)=1 AND CASE WHEN(e#>>'{1,0}')~'^[0-9]{1,6}$' THEN(e#>>'{1,0}')::int=ordinal ELSE false END,false),
   'identityValid',coalesce(jsonb_array_length(e->3)=4 AND length(e#>>'{3,0}') BETWEEN 1 AND 25 AND e#>>'{3,1}'='' AND e#>>'{3,2}'='' AND e#>>'{3,3}' IN('9','89'),false),
   'hasRegister',jsonb_array_length(e)>=5,'registerIndex',nullif(e#>>'{4,1}',''),
   'registerShapeValid',coalesce(jsonb_array_length(e)=5 AND jsonb_array_length(e->4)=2 AND e#>>'{4,0}'='1' AND CASE WHEN(e#>>'{4,1}')~'^[0-9]{1,6}$' THEN(e#>>'{4,1}')::int>0 ELSE false END,false)));
 END LOOP;
 FOR own IN SELECT x FROM jsonb_array_elements(lines)x LOOP
  SELECT jsonb_agg(x ORDER BY(x->>'lineIndex')::int) INTO siblings FROM jsonb_array_elements(lines)x WHERE CASE WHEN own->>'id' IS NULL THEN x->'lineIndex'=own->'lineIndex' ELSE x->'id'=own->'id' AND x->'identityAgency' IS NOT DISTINCT FROM own->'identityAgency' END;
  multi:=jsonb_array_length(siblings)>1;
  valid:=NOT EXISTS(SELECT FROM jsonb_array_elements(siblings) WITH ORDINALITY v(x,pos) WHERE x->>'sequenceValid'<>'true'
   OR(x->>'hasRegister'='true' AND x->>'registerShapeValid'<>'true')
   OR(x->>'hasRegister'='true' AND(NOT multi OR coalesce(source->>'code','') NOT IN('Z04','Z06','Z10')))
   OR(multi AND(coalesce(source->>'code','') NOT IN('Z04','Z06','Z10') OR x->>'hasRegister'<>'true' OR CASE WHEN(x->>'registerIndex')~'^[0-9]{1,6}$' THEN(x->>'registerIndex')::int<>pos ELSE true END))
   OR((multi OR x->>'hasRegister'='true') AND x->>'identityValid'<>'true'));
  IF valid AND multi AND own->'lineIndex' IS DISTINCT FROM siblings#>'{0,lineIndex}' THEN CONTINUE;END IF;
  result:=result||jsonb_build_array(jsonb_build_object('lineIndex',own->'lineIndex','id',own->'id','identityAgency',own->'identityAgency','li',own->'li','validRegisterChain',valid,
   'registerLineIndices',CASE WHEN valid THEN(SELECT jsonb_agg(x->'lineIndex' ORDER BY pos) FROM jsonb_array_elements(siblings) WITH ORDINALITY v(x,pos)) ELSE jsonb_build_array(own->'lineIndex') END));
 END LOOP;
 RETURN result;
END$_$;

--
-- Name: prodat_physical_source_projection_version_v1(); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.prodat_physical_source_projection_version_v1() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT '{"lib/ediel/prodat/prodatRegisterGroups.ts":"142e9e441e6a94708841dec9aaddb9656b091aa04536c00ec358a6b59bcfe291","lib/ediel/prodat/prodatRegisterFields.ts":"1d171216b8fd8be093a4b6d5e0d9e04cf969468ba342dfcde4771b46fe5df09c","lib/ediel/prodat/prodat26AFieldMatrix.ts":"a96b7dcddb564aad04d3be6ee7aef1117601eccd893b47869a8ddc60b3794382","lib/ediel/rulebook/prodatRegisterPolicy.ts":"72ab4f6836154c74a4dcd8e3fefec92fc31bb5da6800318707b591f51f44bf0e"}'::jsonb$$;

--
-- Name: read_committed_by_source_v2(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.read_committed_by_source_v2(p_company uuid, p_environment text, p_ack uuid, p_actor uuid, p_ack_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c gridex_ack_authority.source_correlations%rowtype;
BEGIN
 IF p_environment IS NULL OR p_environment NOT IN('test','production') OR p_ack IS NULL OR p_actor IS NULL
  OR p_ack_payload_hash IS NULL OR (p_ack_payload_hash~'^[a-f0-9]{64}$') IS NOT TRUE
 THEN RAISE EXCEPTION 'ack_execution_scope_required' USING ERRCODE='22023';END IF;
 -- An absent proof discloses no tenant/source facts, but still requires a
 -- genuine current active actor. A present proof additionally requires its
 -- own accepted membership and communication READ/WRITE in the frozen reader.
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor AND u.user_status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_ack;
 IF c.ack_message_id IS NULL THEN RETURN NULL;END IF;
 IF c.company_id IS NULL OR c.environment IS DISTINCT FROM p_environment
  OR c.ack_payload_hash IS DISTINCT FROM p_ack_payload_hash
  OR (p_company IS NOT NULL AND c.company_id IS DISTINCT FROM p_company)
 THEN RAISE EXCEPTION 'ack_immutable_correlation_conflict' USING ERRCODE='23514';END IF;
 -- This existing source->ACK reader independently validates the immutable
 -- received raw/context/canonical leaf, exact sealed sent original, and any
 -- stored partial result. No current guide or public status is reselected.
 RETURN gridex_ack_authority.read_committed_v1(c.company_id,p_environment,p_ack,p_actor);
END$_$;

--
-- Name: read_committed_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.read_committed_v1(p_company uuid, p_environment text, p_ack uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c gridex_ack_authority.source_correlations%rowtype;ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;captured gridex_received_sources.sources%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;r gridex_ack_authority.applied_receipts%rowtype;
BEGIN
 IF p_company IS NULL OR p_environment IS NULL OR p_environment NOT IN('test','production') OR p_ack IS NULL OR p_actor IS NULL THEN RAISE EXCEPTION 'ack_execution_scope_required' USING ERRCODE='22023';END IF;
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_ack;
 IF c.ack_message_id IS NULL THEN RETURN NULL;END IF;
 IF c.company_id IS DISTINCT FROM p_company OR c.environment IS DISTINCT FROM p_environment THEN RAISE EXCEPTION 'ack_immutable_correlation_conflict' USING ERRCODE='23514';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor AND u.user_status='active' FOR SHARE;
 IF NOT FOUND OR NOT (coalesce(public.gridex_actor_has_company_permission(p_actor,p_company,'communication.read'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor,p_company,'communication.write'),false)) THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company AND cm.user_id=p_actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 -- Same source→ACK order as actual apply/recovery. Existing receipt never
 -- reselects today's role, guide, tenant or global candidate universe.
 SELECT * INTO source FROM public.ediel_messages WHERE id=c.source_message_id FOR SHARE;
 SELECT * INTO ack FROM public.ediel_messages WHERE id=c.ack_message_id FOR SHARE;
 SELECT * INTO captured FROM gridex_received_sources.sources WHERE source_message_id=c.ack_message_id;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments WHERE id=c.canonical_assessment_id;
 IF source.id IS NULL OR ack.id IS NULL OR source.company_id IS DISTINCT FROM c.company_id OR source.environment IS DISTINCT FROM c.environment OR source.direction IS DISTINCT FROM 'outbound'
  OR source.immutable_rendered_at IS NULL OR source.message_sent_at IS NULL OR c.source_payload_hash IS DISTINCT FROM source.immutable_payload_hash OR c.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex')
  OR ack.company_id IS DISTINCT FROM c.company_id OR ack.environment IS DISTINCT FROM c.environment OR ack.direction IS DISTINCT FROM 'inbound' OR ack.message_family IS DISTINCT FROM c.ack_family
  OR c.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') OR captured.company_id IS DISTINCT FROM c.company_id OR captured.environment IS DISTINCT FROM c.environment
  OR captured.payload_hash IS DISTINCT FROM c.ack_payload_hash OR captured.raw_payload IS DISTINCT FROM ack.raw_payload OR captured.received_context IS NULL
  OR canonical.id IS NULL OR canonical.company_id IS DISTINCT FROM c.company_id OR canonical.environment IS DISTINCT FROM c.environment OR canonical.source_message_id IS DISTINCT FROM ack.id OR canonical.source_payload_hash IS DISTINCT FROM c.ack_payload_hash
  OR canonical.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR canonical.facts_hash IS DISTINCT FROM encode(sha256(convert_to(canonical.facts_text,'UTF8')),'hex')
  OR canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
 THEN RAISE EXCEPTION 'ack_immutable_correlation_conflict' USING ERRCODE='23514';END IF;
 SELECT * INTO r FROM gridex_ack_authority.applied_receipts WHERE ack_message_id=c.ack_message_id;
 IF r.ack_message_id IS NOT NULL THEN
  IF r.result#>>'{sourceMessage,id}' IS DISTINCT FROM c.source_message_id::text OR r.result#>>'{sourceMessage,company_id}' IS DISTINCT FROM c.company_id::text OR r.result#>>'{sourceMessage,environment}' IS DISTINCT FROM c.environment
   OR r.result#>>'{sourceMessage,raw_payload}' IS DISTINCT FROM source.raw_payload OR r.result->>'outcome' IS DISTINCT FROM c.ack_outcome OR r.result->>'scope' IS DISTINCT FROM c.ack_scope OR r.result->'scopeOutcomes' IS DISTINCT FROM c.scope_outcomes THEN RAISE EXCEPTION 'ack_immutable_receipt_conflict';END IF;
  RETURN jsonb_build_object('kind','exact_receipt','ackPayloadHash',c.ack_payload_hash,'ackFamily',c.ack_family,'ackMessageId',ack.id,'sourceMessageId',source.id,'companyId',c.company_id,'environment',c.environment,'result',r.result);
 END IF;
 -- Historic ownscope proof is genuine, but the historic aggregate result was
 -- not recorded. Do not backfill an invented summary from current statuses.
 RETURN jsonb_build_object('kind','legacy_diagnostic','ackPayloadHash',c.ack_payload_hash,'ackFamily',c.ack_family,'ackMessageId',ack.id,'sourceMessageId',source.id,'companyId',c.company_id,'environment',c.environment,'outcome',c.ack_outcome,'scope',c.ack_scope,'scopeOutcomes',c.scope_outcomes,'summaryUnavailable',true);
END $$;

--
-- Name: read_outbound_originals_v1(uuid, text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.read_outbound_originals_v1(p_source uuid, p_family text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;a jsonb;s jsonb;h jsonb;items jsonb:='[]';source_hash text;ack_hash text;qualified boolean;matched boolean;company uuid;technical gridex_ediel_technical_ack.sources%rowtype;reply gridex_ediel_technical_ack.replies%rowtype;common gridex_ediel_common_header.sources%rowtype;
BEGIN
 IF p_source IS NULL OR p_family IS NULL OR p_family NOT IN('CONTRL','APERAK','UTILTS_ERR') THEN RAISE EXCEPTION 'ack_original_read_scope_required' USING ERRCODE='22023';END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source AND direction='inbound';
 IF source.id IS NULL THEN RAISE EXCEPTION 'ack_original_inbound_source_required' USING ERRCODE='23514';END IF;
 source_hash:=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex');s:=gridex_ack_authority.wire_v1(source.raw_payload);
 SELECT * INTO technical FROM gridex_ediel_technical_ack.sources WHERE source_message_id=source.id AND environment=source.environment AND payload_sha256=source_hash AND status='ready';
 SELECT * INTO common FROM gridex_ediel_common_header.sources WHERE source_message_id=source.id AND environment=source.environment AND payload_sha256=source_hash AND status='ready';
 IF source.company_id IS NULL AND technical.company_id IS NOT NULL AND common.company_id IS NOT NULL AND technical.company_id<>common.company_id THEN RAISE EXCEPTION 'ack_original_tenant_basis_ambiguous';END IF;
 company:=coalesce(source.company_id,technical.company_id,common.company_id);
 IF company IS NULL THEN RETURN jsonb_build_object('version',1,'sourceMessageId',source.id,'sourcePayloadHash',source_hash,'environment',source.environment,'companyId',NULL,'originals','[]'::jsonb);END IF;
 FOR ack IN SELECT m.* FROM public.ediel_messages m WHERE m.direction='outbound' AND m.company_id=company AND m.environment=source.environment AND m.message_family=p_family
  AND (m.related_message_id=source.id OR EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses w ON w.id=c.witness_id WHERE c.source_message_id=m.id AND w.related_message_id=source.id)
   OR EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions c JOIN gridex_ediel_common_header.negative_witnesses w ON w.id=c.witness_id WHERE c.ack_message_id=m.id AND w.source_message_id=source.id) OR EXISTS(SELECT FROM gridex_ediel_ack_replay.creation_receipts r WHERE r.ack_message_id=m.id AND r.source_message_id=source.id AND r.company_id=company AND r.environment=source.environment AND r.source_payload_hash=source_hash AND r.ack_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) OR (p_family='CONTRL' AND gridex_ediel_technical_ack.retained_source_v1(m,false)=source.id)) ORDER BY m.created_at,m.id LOOP
  IF gridex_ediel_duplicate_responses.is_duplicate_ack_v1(ack.id) THEN CONTINUE;END IF;
  ack_hash:=encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex');a:=gridex_ack_authority.wire_v1(ack.raw_payload);qualified:=false;matched:=false;
  IF p_family='CONTRL' THEN
   h:=gridex_ediel_technical_ack.envelope(source.raw_payload);
   matched:=a IS NOT NULL AND h IS NOT NULL AND a->>'family'='CONTRL' AND a->'sender'=h->'receiver' AND a->'receiver'=h->'sender'
    AND a->>'environment'=h->>'environment' AND a->>'app'=h->>'applicationReference' AND a->>'uciRef'=h->>'uciReference' AND a->'uciSender'=h->'sender' AND a->'uciReceiver'=h->'receiver';
   IF NOT coalesce(matched,false) THEN CONTINUE;END IF;
   SELECT * INTO reply FROM gridex_ediel_technical_ack.replies WHERE source_message_id=source.id AND company_id=company AND environment=source.environment AND payload_sha256=source_hash;
   qualified:=gridex_ediel_technical_ack.retained_source_v1(ack,true)=source.id AND technical.company_id IS NOT DISTINCT FROM company AND reply.source_message_id IS NOT NULL AND reply.evidence->'originalUNB'=h
    AND reply.evidence->>'syntaxDecision' IN('accepted','rejected') AND a->>'uciAction'=CASE reply.evidence->>'syntaxDecision' WHEN 'accepted' THEN '1' ELSE '4' END
    AND ack.immutable_rendered_at IS NOT NULL AND ack.immutable_payload_hash=ack_hash;
  ELSE
   matched:=gridex_ediel_header_negative_birth.source_matches_v1(a,s,source);
   IF NOT coalesce(matched,false) THEN CONTINUE;END IF;
   qualified:=EXISTS(SELECT FROM gridex_received_sources.sources r WHERE r.source_message_id=source.id AND r.company_id=company AND r.environment=source.environment AND r.payload_hash=source_hash AND r.raw_payload=source.raw_payload)
    AND EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses w ON w.id=c.witness_id
    WHERE c.source_message_id=ack.id AND c.company_id=company AND c.environment=source.environment AND c.payload_sha256=ack_hash
     AND w.company_id=company AND w.environment=source.environment AND w.payload_sha256=ack_hash AND w.related_message_id=source.id AND w.family=p_family AND w.code=ack.message_code)
    OR EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions c JOIN gridex_ediel_common_header.negative_witnesses w ON w.id=c.witness_id
     WHERE common.source_message_id=source.id AND common.company_id=company AND common.payload_sha256=source_hash
      AND c.ack_message_id=ack.id AND c.company_id=company AND c.environment=source.environment AND c.payload_sha256=ack_hash
      AND w.company_id=company AND w.environment=source.environment AND w.source_message_id=source.id AND w.payload_sha256=ack_hash);
  END IF;
  -- Failed/cancelled is only an operational projection. A genuine born ACK
  -- remains its own original; missing historical basis is an explicit hold.
  items:=items||jsonb_build_array(jsonb_build_object('status',CASE WHEN coalesce(qualified,false) THEN 'qualified' ELSE 'held' END,'message',to_jsonb(ack),'payloadHash',ack_hash));
 END LOOP;
 RETURN jsonb_build_object('version',1,'sourceMessageId',source.id,'sourcePayloadHash',source_hash,'environment',source.environment,'companyId',company,'originals',items);
END $$;

--
-- Name: require_physical_actor_v1(uuid, uuid, boolean); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.require_physical_actor_v1(c uuid, actor uuid, write_required boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF c IS NULL OR actor IS NULL THEN RAISE EXCEPTION 'ack_execution_scope_required' USING ERRCODE='22023';END IF;
 IF NOT EXISTS(SELECT FROM public.companies WHERE id=c AND is_active AND status='active') THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active' FOR SHARE;
 IF NOT FOUND OR NOT(coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.write'),false) OR(NOT write_required AND coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.read'),false))) THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ack_execution_actor_unqualified' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: seal_received_ack_v1(); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.seal_received_ack_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.execution_context_snapshot ? 'receivedAckContext' THEN
   IF NEW.execution_context_snapshot->'receivedAckContext' IS DISTINCT FROM OLD.execution_context_snapshot->'receivedAckContext'
    OR NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.immutable_payload_hash IS DISTINCT FROM OLD.immutable_payload_hash
    OR ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_family,NEW.message_standard,NEW.message_code,NEW.message_received_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_family,OLD.message_standard,OLD.message_code,OLD.message_received_at)
   THEN RAISE EXCEPTION 'immutable_received_ack_source_cannot_change' USING ERRCODE='23514'; END IF;
  ELSIF NEW.execution_context_snapshot ? 'receivedAckContext' THEN RAISE EXCEPTION 'received_ack_context_cannot_be_backfilled' USING ERRCODE='23514'; END IF;
 ELSIF TG_OP='INSERT' THEN
  IF jsonb_typeof(NEW.execution_context_snapshot) IN ('object','array') THEN NEW.execution_context_snapshot:=NEW.execution_context_snapshot-'receivedAckContext'; END IF;
  IF NEW.direction='inbound' AND NEW.message_family IN ('CONTRL','APERAK','UTILTS_ERR') AND NEW.message_standard='edifact'
   AND NEW.id IS NOT NULL AND NEW.company_id IS NOT NULL AND NEW.environment IN ('test','production')
   AND NEW.message_code IS NOT NULL AND NEW.message_received_at IS NOT NULL AND NEW.raw_payload IS NOT NULL THEN
   NEW.immutable_payload_hash:=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex');
   NEW.execution_context_snapshot:=(CASE WHEN jsonb_typeof(NEW.execution_context_snapshot)='object' THEN NEW.execution_context_snapshot ELSE '{}'::jsonb END)
     || jsonb_build_object('receivedAckContext',jsonb_build_object('version',1,'contextOrigin','database_insert','sourceMessageId',NEW.id,
       'companyId',NEW.company_id,'environment',NEW.environment,'messageCode',NEW.message_code,'payloadHash',NEW.immutable_payload_hash,
       'sourceReceivedAt',NEW.message_received_at,'capturedAt',clock_timestamp()));
  END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: source_match_v1(jsonb, jsonb); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.source_match_v1(a jsonb, s jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF a IS NULL OR s IS NULL OR a->'sender' IS DISTINCT FROM s->'receiver' OR a->'receiver' IS DISTINCT FROM s->'sender'
  OR a->>'environment' IS DISTINCT FROM s->>'environment' OR a->>'app' IS DISTINCT FROM s->>'app' THEN RETURN false; END IF;
 IF a->>'family'='CONTRL' THEN
  RETURN s->>'family'<>'CONTRL' AND a->>'uciRef'=left(s->>'interchange',14) AND a->'uciSender'=s->'sender' AND a->'uciReceiver'=s->'receiver'
   AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(a->'ucm','[]')) x WHERE x<>s->>'unhRef');
 END IF;
 IF nullif(a->>'legalSender','') IS NULL OR nullif(a->>'legalReceiver','') IS NULL
  OR a->>'legalSender' IS DISTINCT FROM s->>'legalReceiver' OR a->>'legalReceiver' IS DISTINCT FROM s->>'legalSender' THEN RETURN false; END IF;
 IF a->>'family'='APERAK' AND a#>>'{type,2}'='96A' AND a#>>'{type,4}'='E2SE6A' THEN
  RETURN s->>'family'='PRODAT' AND jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))=1 AND a#>>'{refs,ACW,0}'=s->>'document'
   AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(a#>'{refs,LI}','[]')) x WHERE NOT coalesce(s#>'{refs,LI}','[]') ? x);
 ELSIF (a->>'family'='APERAK' AND a#>>'{type,2}'='04A' AND a#>>'{type,4}'='E5SE5A') OR (a->>'family'='UTILTS' AND a->>'code'='ERR') THEN
  IF (s->>'family'='UTILTS' AND (s->>'code'<>'ERR' OR a->>'family'='APERAK')) IS NOT TRUE THEN RETURN false; END IF;
  IF a->>'family'='APERAK' THEN
   RETURN a->>'docCode'=s->>'code' AND a->>'docRef'=s->>'document'
    AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(a#>'{refs,ACW}','[]')) x WHERE NOT coalesce(s->'ide','[]') ? x);
  ELSE RETURN coalesce(a#>ARRAY['refs',s->>'code'],'[]') ? (s->>'document')
    AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(a#>'{refs,TN}','[]')) x WHERE NOT coalesce(s->'ide','[]') ? x); END IF;
 END IF;
 RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: wire_v1(text); Type: FUNCTION; Schema: gridex_ack_authority; Owner: -
--

CREATE FUNCTION gridex_ack_authority.wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(p_raw);t jsonb;e jsonb;out jsonb:=jsonb_build_object('refs','{}'::jsonb);first_detail integer;family text;legal_sender text;legal_receiver text;erc text;group_index integer:=-1;group_key text;
BEGIN
 IF tokens IS NULL OR EXISTS(SELECT FROM unnest(ARRAY['UNB','UNH','UNT','UNZ']) tag WHERE (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'=tag)<>1) THEN RETURN NULL; END IF;
 SELECT min((x->>'index')::integer) INTO first_detail FROM jsonb_array_elements(tokens) x WHERE x->>'tag' IN ('IDE','LIN');
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::integer LOOP
  e:=t->'elements';
  IF t->>'tag'='UNB' THEN out:=out||jsonb_build_object('sender',e->2,'receiver',e->3,'interchange',e#>>'{5,0}','app',e#>>'{7,0}','environment',CASE e#>>'{11,0}' WHEN '1' THEN 'test' ELSE 'production' END);
  ELSIF t->>'tag'='UNH' THEN family:=e#>>'{2,0}';out:=out||jsonb_build_object('family',family,'type',e->2,'unhRef',e#>>'{1,0}','unhIndex',t->'index');
  ELSIF t->>'tag'='UNT' THEN out:=out||jsonb_build_object('untRef',e#>>'{2,0}','untCount',e#>>'{1,0}','untIndex',t->'index');
  ELSIF t->>'tag'='BGM' THEN IF out ? 'code' THEN RETURN NULL; END IF;out:=out||jsonb_build_object('code',e#>>'{1,0}','document',e#>>'{2,0}','function',e#>>'{3,0}');
  ELSIF t->>'tag'='DOC' THEN IF out ? 'docRef' THEN RETURN NULL; END IF;out:=out||jsonb_build_object('docCode',e#>>'{1,0}','docRef',e#>>'{2,0}');
  ELSIF t->>'tag'='UCI' THEN IF out ? 'uciRef' THEN RETURN NULL; END IF;out:=out||jsonb_build_object('uciRef',e#>>'{1,0}','uciSender',e->2,'uciReceiver',e->3,'uciAction',e#>>'{4,0}');
  ELSIF t->>'tag'='UCM' THEN out:=jsonb_set(out,'{ucm}',coalesce(out->'ucm','[]')||jsonb_build_array(e#>>'{1,0}'));
  ELSIF t->>'tag'='IDE' THEN IF e#>>'{1,0}' IS DISTINCT FROM '24' THEN out:=out||jsonb_build_object('ideQualifierInvalid',true); END IF;out:=jsonb_set(out,'{ide}',coalesce(out->'ide','[]')||jsonb_build_array(e#>>'{2,0}'));
  ELSIF t->>'tag'='RFF' THEN out:=jsonb_set(out,ARRAY['refs',e#>>'{1,0}'],coalesce(out#>ARRAY['refs',e#>>'{1,0}'],'[]')||jsonb_build_array(e#>>'{1,1}'));
   IF group_index>=0 AND e#>>'{1,0}' IN ('DM','ACW') THEN
    group_key:=lower(e#>>'{1,0}');out:=jsonb_set(out,ARRAY['ercGroups',group_index::text,group_key],coalesce(out#>ARRAY['ercGroups',group_index::text,group_key],'[]')||jsonb_build_array(e#>>'{1,1}'));END IF;
   IF e#>>'{1,0}' IN ('LI','ACW') AND erc IS NOT NULL THEN out:=jsonb_set(out,'{scopeResults}',coalesce(out->'scopeResults','[]')||jsonb_build_array(jsonb_build_object('qualifier',e#>>'{1,0}','reference',e#>>'{1,1}','outcome',CASE erc WHEN '100' THEN 'positive' ELSE 'negative' END))); END IF;
  ELSIF t->>'tag'='FTX' AND group_index>=0 THEN out:=jsonb_set(out,ARRAY['ercGroups',group_index::text,'texts'],coalesce(out#>ARRAY['ercGroups',group_index::text,'texts'],'[]')||jsonb_build_array(e));
  ELSIF t->>'tag'='NAD' AND (first_detail IS NULL OR (t->>'index')::integer<first_detail) THEN
   legal_sender:=CASE family WHEN 'PRODAT' THEN 'FR' WHEN 'APERAK' THEN CASE out#>>'{type,2}' WHEN '96A' THEN 'FR' ELSE 'MS' END ELSE 'MS' END;
   legal_receiver:=CASE family WHEN 'PRODAT' THEN 'DO' WHEN 'APERAK' THEN CASE out#>>'{type,2}' WHEN '96A' THEN 'DO' ELSE 'MR' END ELSE 'MR' END;
   IF e#>>'{1,0}'=legal_sender THEN IF out ? 'legalSender' THEN RETURN NULL; END IF;out:=out||jsonb_build_object('legalSender',e#>>'{2,0}');
   ELSIF e#>>'{1,0}'=legal_receiver THEN IF out ? 'legalReceiver' THEN RETURN NULL; END IF;out:=out||jsonb_build_object('legalReceiver',e#>>'{2,0}'); END IF;
  ELSIF t->>'tag'='ERC' THEN erc:=e#>>'{1,0}';group_index:=group_index+1;out:=jsonb_set(out,'{ercGroups}',coalesce(out->'ercGroups','[]')||jsonb_build_array(jsonb_build_object('code',erc,'acw','[]'::jsonb,'dm','[]'::jsonb)));out:=jsonb_set(out,'{erc}',coalesce(out->'erc','[]')||jsonb_build_array(e#>>'{1,0}'));
  ELSIF t->>'tag'='STS' AND e#>>'{1,0}'='E01' AND e#>>'{2,0}'='41' THEN out:=out||jsonb_build_object('errStatus',true);
  END IF;
 END LOOP;
 IF out->>'unhRef' IS DISTINCT FROM out->>'untRef' OR out->>'untCount' !~ '^[0-9]+$'
  OR (out->>'untCount')::integer<>(out->>'untIndex')::integer-(out->>'unhIndex')::integer+1
  OR (nullif(out->>'app','') IS NULL AND out->>'family'<>'CONTRL') OR nullif(out#>>'{sender,0}','') IS NULL OR nullif(out#>>'{receiver,0}','') IS NULL THEN RETURN NULL; END IF;
 RETURN out;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $_$;

--
-- Name: authorize_original_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.authorize_original_actor_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF c IS NULL OR actor IS NULL THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM x.id FROM auth.users x WHERE x.id=actor FOR SHARE;PERFORM x.id FROM public.companies x WHERE x.id=c FOR SHARE;
 PERFORM x.user_id FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor FOR SHARE;PERFORM x.id FROM public.user_profiles x WHERE x.id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM auth.users x WHERE x.id=actor AND x.deleted_at IS NULL AND (x.banned_until IS NULL OR x.banned_until<=clock_timestamp()))
  OR NOT EXISTS(SELECT FROM public.companies x WHERE x.id=c AND x.status='active' AND x.is_active)
  OR NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active') THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: authorize_original_read_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.authorize_original_read_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ai_processing.authorize_original_actor_v1(c,actor);
 IF NOT(coalesce(gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.read'),false) OR coalesce(gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'metering.read'),false)) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: authorize_purpose_phase_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.authorize_purpose_phase_v1(c uuid, actor uuid, phase text, qualified_environment text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF phase IS NULL OR phase NOT IN ('origination','send') OR c IS NULL OR actor IS NULL OR (qualified_environment IS NOT NULL AND qualified_environment NOT IN ('test','production')) THEN RAISE EXCEPTION 'ai_bi_processing_scope_required'; END IF;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 PERFORM p.id FROM public.user_profiles p WHERE p.id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles p WHERE p.id=actor AND p.user_status='active')
 OR NOT(CASE WHEN phase='send' THEN coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false)
 ELSE coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.write'),false) OR (coalesce(qualified_environment='test',false) AND coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel_testing.write'),false)) END) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
END $$;

--
-- Name: bind_original_message_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.bind_original_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m jsonb:=to_jsonb(NEW);d jsonb;proof jsonb;BEGIN
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_standard IS DISTINCT FROM 'ai_list' THEN RETURN NEW; END IF;
 d:=jsonb_build_object('actorUserId',NEW.created_by,'companyId',NEW.company_id,'intentId',NEW.intent_id,'sourceOperationId',m->'source_operation_id',
  'direction',NEW.direction,'messageStandard',NEW.message_standard,'messageFamily',NEW.message_family,'messageCode',NEW.message_code,'messageVersion',NEW.message_version,'environment',NEW.environment,
  'processType',m->'process_type','rawPayload',NEW.raw_payload,'fileName',NEW.file_name,'mimeType',NEW.mime_type,'senderEdielId',NEW.sender_ediel_id,'receiverEdielId',NEW.receiver_ediel_id,
  'customerId',NEW.customer_id,'siteId',NEW.site_id,'meteringPointId',m->'metering_point_id','communicationRouteId',NEW.communication_route_id,'routeProfileId',NEW.route_profile_id,
  'applicationReference',m->'application_reference','interchangeReference',m->'interchange_reference','externalReference',m->'external_reference','correlationReference',m->'correlation_reference','transactionReference',m->'transaction_reference',
  'originalMessageId',m->'original_message_id','originalTransactionId',m->'original_transaction_id','originalMessageCode',m->'original_message_code','relatedMessageId',m->'related_message_id','switchRequestId',m->'switch_request_id',
  'gridOwnerDataRequestId',m->'grid_owner_data_request_id','outboundRequestId',m->'outbound_request_id','partnerExportId',m->'partner_export_id','canonicalRulePackId',m->'canonical_rule_pack_id',
  'ruleProfileKey',m->'rule_profile_key','ruleProfileVersionId',m->'rule_profile_version_id','ruleProfileVersion',m->'rule_profile_version','rulePackChecksum',m->'rule_pack_checksum','rulePackSnapshot',m->'rule_pack_snapshot');
 proof:=gridex_ai_processing.require_original_draft_v1(NEW.company_id,NEW.created_by,NEW.intent_id,d);
 INSERT INTO gridex_ai_processing.outbound_origin_bindings(intent_id,message_id,company_id,payload_hash) VALUES(NEW.intent_id,NEW.id,NEW.company_id,proof->>'sourceHash');
 RETURN NEW;
END $$;

--
-- Name: capture_origin_operation_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.capture_origin_operation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE i public.ediel_message_intents%rowtype;BEGIN
 i:=gridex_ai_processing.intent_request_v1(NEW.company_id,NEW.intent_id);
 NEW.operation_id:=i.operation_id;NEW.intent_basis:=gridex_ai_processing.intent_basis_v1(i);
 RETURN NEW;
END $$;

