SET default_table_access_method = heap;

--
-- Name: ediel_message_intents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_message_intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text DEFAULT 'test'::text NOT NULL,
    market text DEFAULT 'electricity'::text NOT NULL,
    message_family text NOT NULL,
    message_code text NOT NULL,
    business_process text NOT NULL,
    direction text DEFAULT 'outbound'::text NOT NULL,
    sender_ediel_id text NOT NULL,
    sender_subaddress text,
    receiver_ediel_id text NOT NULL,
    receiver_subaddress text,
    application_reference text NOT NULL,
    route_profile_id uuid,
    communication_route_id uuid,
    certificate_profile_id uuid,
    customer_id uuid,
    customer_site_id uuid,
    grid_owner_information_request_id uuid,
    supplier_switch_request_id uuid,
    customer_info_request_id uuid,
    operation_id uuid,
    facility_id text,
    metering_point_id text,
    grid_area_code text,
    requested_effective_date date,
    send_not_before timestamp with time zone,
    send_window_opens_at timestamp with time zone,
    send_window_closes_at timestamp with time zone,
    interchange_reference text NOT NULL,
    message_reference text NOT NULL,
    transaction_reference text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    validation_result jsonb DEFAULT '{}'::jsonb NOT NULL,
    blocking_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    idempotency_key text NOT NULL,
    expected_rule_version text,
    expected_field_matrix_version text,
    ediel_message_id uuid,
    outbound_request_id uuid,
    validation_status text DEFAULT 'draft'::text NOT NULL,
    render_status text DEFAULT 'not_rendered'::text NOT NULL,
    outbox_status text DEFAULT 'not_queued'::text NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ediel_message_intents_direction_chk CHECK ((direction = ANY (ARRAY['outbound'::text, 'inbound_response'::text]))),
    CONSTRAINT ediel_message_intents_outbox_status_chk CHECK ((outbox_status = ANY (ARRAY['not_queued'::text, 'queued'::text, 'sent'::text, 'failed'::text]))),
    CONSTRAINT ediel_message_intents_render_status_chk CHECK ((render_status = ANY (ARRAY['not_rendered'::text, 'rendered'::text, 'failed'::text]))),
    CONSTRAINT ediel_message_intents_validation_status_chk CHECK ((validation_status = ANY (ARRAY['draft'::text, 'blocked'::text, 'validated'::text])))
);

--
-- Name: TABLE ediel_message_intents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ediel_message_intents IS 'Mandatory pre-render object for outbound Ediel. Business processes create intents only; RenderGateway validates and renders.';

--
-- Name: COLUMN ediel_message_intents.application_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_message_intents.application_reference IS 'Policy-driven Application Reference. Route profile may declare an expected value but must not override policy.';

--
-- Name: COLUMN ediel_message_intents.blocking_reasons; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_message_intents.blocking_reasons IS 'Structured list of blocking reason codes/messages that prevented validation/render/queue.';

--
-- Name: COLUMN ediel_message_intents.idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_message_intents.idempotency_key IS 'Deterministic key; unique per (company_id, environment) to prevent duplicate intents/outbox.';

--
-- Name: COLUMN ediel_message_intents.created_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_message_intents.created_by IS 'Optional real user UUID. Null means the intent was created by an automated system process; system provenance belongs in payload/validation metadata.';

--
-- Name: COLUMN ediel_message_intents.updated_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_message_intents.updated_by IS 'Optional real user UUID. Null means the latest transition was performed by an automated system process; never store text sentinels in this UUID column.';

--
-- Name: customer_history_before_composed_scope_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_history_before_composed_scope_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE refs jsonb;ref jsonb;basis jsonb;records text[];cols text[];normalized text;row integer;first_at timestamptz;candidate_at timestamptz;history jsonb;BEGIN
 IF claims IS NULL OR octet_length(claims)>262144 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;refs:=claims::jsonb;
 IF jsonb_typeof(refs) IS DISTINCT FROM 'array' OR jsonb_array_length(refs)>1000 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;
 IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;records:=string_to_array(normalized,E'\n');
 IF jsonb_array_length(refs)=0 THEN RETURN jsonb_build_object('status','authorized','companyId',i.company_id,'customerId',i.customer_id,'cutoff',cutoff,'authorizesInitialCustomer',false,'patches','[]'::jsonb);END IF;
 -- Range discovery uses qualified actual baseline bytes, not portal start dates.
 -- The complete row owner still validates every claimed baseline/period below.
 FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
  FOR row IN 2..cardinality(records) LOOP
   cols:=string_to_array(records[row],';');basis:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
   IF basis#>>'{business,wire,businessCase}' IS DISTINCT FROM 'supply_baseline' OR basis#>>'{business,supplyPeriodId}' IS DISTINCT FROM ref->>'supplyPeriodId' THEN CONTINUE;END IF;
   candidate_at:=gridex_received_sources.permission_time_v1(basis#>>'{business,wire,effectiveFrom,marketMinute}');
   IF first_at IS NULL OR candidate_at<first_at THEN first_at:=candidate_at;END IF;
  END LOOP;
 END LOOP;
 IF first_at IS NULL THEN RAISE EXCEPTION 'ai_list_original_row_source_mismatch';END IF;
 history:=gridex_customer_life_events.qualified_patches_v1(i.company_id,i.customer_id,first_at,gridex_received_sources.permission_time_v1(split_part(records[1],';',9)||'0000'),cutoff);
 IF history->>'status' IS DISTINCT FROM 'authorized' OR history->>'authorizesInitialCustomer' IS DISTINCT FROM 'false' OR jsonb_array_length(history->'patches')>1000 THEN RAISE EXCEPTION 'ai_list_original_customer_patch_owner_required';END IF;
 RETURN history;
END$$;

--
-- Name: customer_history_for_rows_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_history_for_rows_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE history jsonb;p jsonb;source jsonb;refs jsonb:=claims::jsonb;records text[];cols text[];ref jsonb;base jsonb;filtered jsonb:='[]';normalized text;row int;n int;matched boolean;BEGIN
 i:=gridex_ai_processing.legal_history_intent_v1(i,raw);
 history:=gridex_ai_processing.customer_history_before_composed_scope_v1(body,cutoff,i,raw,claims);
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;records:=string_to_array(normalized,E'\n');
 FOR p IN SELECT value FROM jsonb_array_elements(history->'patches') LOOP
  SELECT count(*),jsonb_agg(x)->0 INTO n,source FROM jsonb_array_elements(body->'sources') x WHERE x->>'sourceMessageId'=p->>'sourceMessageId' AND x->>'payloadHash'=p->>'sourcePayloadHash';
  IF n<>1 THEN CONTINUE;END IF;matched:=false;
  FOR row IN 2..cardinality(records) LOOP
   cols:=string_to_array(records[row],';');
   IF gridex_ai_processing.customer_only_patch_object_v1(i,history,source,cols[2],cols[3]) IS NOT TRUE OR gridex_ai_processing.customer_source_object_composed_v1(body,cutoff,i,history,source,cols[2],cols[3]) IS NOT TRUE THEN CONTINUE;END IF;
   FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
    base:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
    IF base#>>'{business,wire,businessCase}'='supply_baseline' AND base#>>'{business,supplyPeriodId}'=ref->>'supplyPeriodId' AND (p->>'effectiveAt')::timestamptz>=gridex_received_sources.permission_time_v1(base#>>'{business,wire,effectiveFrom,marketMinute}') AND EXISTS(SELECT FROM public.customer_supply_periods period WHERE period.id::text=ref->>'supplyPeriodId' AND period.company_id=i.company_id AND period.customer_id=i.customer_id AND (p->>'effectiveAt')::timestamptz<gridex_received_sources.permission_time_v1(least(split_part(records[1],';',9),coalesce(to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD'),split_part(records[1],';',9)))||'0000')) THEN matched:=true;EXIT;END IF;
   END LOOP;
   IF matched THEN EXIT;END IF;
  END LOOP;
  IF matched THEN filtered:=filtered||jsonb_build_array(p);END IF;
 END LOOP;
 RETURN jsonb_set(history,'{patches}',filtered);
END$$;

--
-- Name: customer_only_patch_object_v1(public.ediel_message_intents, jsonb, jsonb, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_only_patch_object_v1(i public.ediel_message_intents, history jsonb, source jsonb, object_id text, agency text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wire jsonb:=gridex_customer_life_events.wire_partition_v1(source->>'rawPayload');own jsonb;p jsonb;a gridex_received_sources.object_assessments%rowtype;entry jsonb;BEGIN
 IF wire->>'family' IS DISTINCT FROM 'PRODAT' OR wire->>'code' IS DISTINCT FROM 'Z06'
  OR source->>'payloadHash' IS DISTINCT FROM encode(sha256(convert_to(source->>'rawPayload','UTF8')),'hex') THEN RETURN false;END IF;
 SELECT x INTO own FROM jsonb_array_elements(wire->'objects') x WHERE x->>'point'=object_id AND x->>'identityAgency'=agency;
 IF own IS NULL OR own->>'projectionHeld'='true' OR own->>'reason' IS DISTINCT FROM 'E34' OR nullif(own->>'li','') IS NULL OR own->>'effectiveAt' IS NULL OR (own#>>'{customerParty,1}' IN('SE1','SE2')) IS NOT TRUE OR own#>>'{customerParty,2}' IS DISTINCT FROM '260' THEN RETURN false;END IF;
 FOR p IN SELECT x FROM jsonb_array_elements(history->'patches')x WHERE x->>'sourceMessageId'=source->>'sourceMessageId' AND x->>'sourcePayloadHash'=source->>'payloadHash' LOOP
  SELECT * INTO a FROM gridex_received_sources.object_assessments x WHERE x.id=(p->>'primaryAssessmentId')::uuid AND x.company_id=i.company_id AND x.source_message_id=(source->>'sourceMessageId')::uuid AND x.source_payload_hash=source->>'payloadHash' AND x.facts_hash=p->>'primaryFactsHash' AND x.facts_hash=encode(sha256(convert_to(x.facts_text,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=x.id);
  IF a.id IS NULL THEN CONTINUE;END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(a.facts_text::jsonb->'objects')x WHERE x#>>'{object,objectId}'=object_id AND x#>>'{object,identityAgency}'=agency)<>1 THEN CONTINUE;END IF;
  SELECT x INTO entry FROM jsonb_array_elements(a.facts_text::jsonb->'objects')x WHERE x#>>'{object,objectId}'=object_id AND x#>>'{object,identityAgency}'=agency;
  IF entry->>'disposition'='accepted' AND entry#>>'{business,customerId}'=i.customer_id::text AND gridex_customer_life_events.owner_proof_consistent_v1(entry->'party',entry->'business',(source->>'sourceMessageId')::uuid) IS TRUE THEN RETURN true;END IF;
 END LOOP;RETURN false;
END$$;

--
-- Name: customer_row_epoch_composed_v1(jsonb, timestamp with time zone, public.ediel_message_intents, jsonb, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_row_epoch_composed_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, baseline_ud jsonb, object_id text, agency text, period_id text, period_start text, requested_day text, search_end text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE history jsonb;source jsonb;p jsonb;facet jsonb;event jsonb;events jsonb:='[]';customer_id text:=baseline_ud#>>'{elements,2,0}';customer_name text:=gridex_ai_processing.party_text_v1(baseline_ud,4,2);start_day text:=period_start;next_day text;day text;at timestamptz;name jsonb;customer_source text;n int;BEGIN
 IF jsonb_typeof(body->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(body->'sources')>1000 THEN RAISE EXCEPTION 'ai_list_customer_source_window_incomplete';END IF;
 history:=gridex_customer_life_events.qualified_patches_v1(i.company_id,i.customer_id,gridex_received_sources.permission_time_v1(period_start||'0000'),gridex_received_sources.permission_time_v1(search_end||'0000'),cutoff);
 IF history->>'status' IS DISTINCT FROM 'authorized' OR history->>'authorizesInitialCustomer' IS DISTINCT FROM 'false' OR jsonb_array_length(history->'patches')>1000 THEN RAISE EXCEPTION 'ai_list_original_customer_patch_owner_required';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(body->'sources') ORDER BY value->>'sourceMessageId' LOOP
  facet:=gridex_requested_changes.customer_facet_basis_v1(body,cutoff,i.company_id,i.environment,i.customer_id,i.customer_site_id,source->>'sourceMessageId',object_id,agency);
  IF facet IS NOT NULL AND facet->>'supplyPeriodId'=period_id AND facet->>'legalSender'=i.receiver_ediel_id AND facet->>'legalReceiver'=i.sender_ediel_id AND facet->>'marketMinute'>=period_start||'0000' AND facet->>'marketMinute'<search_end||'0000' THEN
   IF facet->>'payloadHash' IS DISTINCT FROM source->>'payloadHash' OR gridex_ai_processing.customer_source_object_composed_v1(body,cutoff,i,history,source,object_id,agency) IS NOT TRUE THEN RAISE EXCEPTION 'ai_list_customer_facet_physical_scope_invalid';END IF;
   IF facet#>>'{party,id}' IS DISTINCT FROM baseline_ud#>>'{elements,2,0}' AND NOT coalesce(facet->>'authorityKind'='bilateral' AND facet->>'identityChangeAuthorized'='true',false) THEN RAISE EXCEPTION 'ai_list_customer_identity_transition_unqualified';END IF;
   events:=events||jsonb_build_array(jsonb_build_object('kind','facet','basis',facet,'effectiveAt',facet->>'effectiveAt','sourceMessageId',facet->>'sourceMessageId'));
  END IF;
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements(history->'patches') LOOP
  IF NOT ((p->'customerFields') ?| ARRAY['org_number','personal_number']) AND NOT ((p->'endUserMasterdata') ? 'name') THEN CONTINUE;END IF;
  SELECT count(*),jsonb_agg(x)->0 INTO n,source FROM jsonb_array_elements(body->'sources') x WHERE x->>'sourceMessageId'=p->>'sourceMessageId' AND x->>'payloadHash'=p->>'sourcePayloadHash';
  IF n<>1 OR gridex_ai_processing.customer_only_patch_object_v1(i,history,source,object_id,agency) IS NOT TRUE THEN CONTINUE;END IF;
  at:=(p->>'effectiveAt')::timestamptz;day:=to_char(at AT TIME ZONE 'Etc/GMT-1','YYYYMMDD');
  IF at IS DISTINCT FROM gridex_received_sources.permission_time_v1(day||'0000') THEN RAISE EXCEPTION 'ai_list_date_only_customer_boundary_unrepresentable';END IF;
  IF gridex_ai_processing.customer_source_object_composed_v1(body,cutoff,i,history,source,object_id,agency) IS NOT TRUE THEN RAISE EXCEPTION 'ai_list_customer_patch_physical_time_invalid';END IF;
  -- A full facet for the SAME source supersedes its delta, not another source.
  IF EXISTS(SELECT FROM jsonb_array_elements(events) x WHERE x->>'sourceMessageId'=p->>'sourceMessageId' AND (x->>'effectiveAt')::timestamptz=(p->>'effectiveAt')::timestamptz) THEN CONTINUE;END IF;
  events:=events||jsonb_build_array(jsonb_build_object('kind','patch','basis',p,'effectiveAt',p->>'effectiveAt','sourceMessageId',p->>'sourceMessageId'));
 END LOOP;
 IF jsonb_array_length(events)>1000 OR EXISTS(SELECT FROM jsonb_array_elements(events) x GROUP BY (x->>'effectiveAt')::timestamptz HAVING count(*)>1) THEN RAISE EXCEPTION 'ai_list_customer_epoch_ambiguous';END IF;
 FOR event IN SELECT value FROM jsonb_array_elements(events) ORDER BY (value->>'effectiveAt')::timestamptz LOOP
  at:=(event->>'effectiveAt')::timestamptz;day:=to_char(at AT TIME ZONE 'Etc/GMT-1','YYYYMMDD');
  IF at IS DISTINCT FROM gridex_received_sources.permission_time_v1(day||'0000') THEN RAISE EXCEPTION 'ai_list_date_only_customer_boundary_unrepresentable';END IF;
  IF day>requested_day THEN next_day:=day;EXIT;END IF;start_day:=day;
  p:=event->'basis';
  IF event->>'kind'='facet' THEN customer_id:=p#>>'{party,id}';customer_name:=p#>>'{party,name}';customer_source:=p->>'sourceMessageId';
  ELSE
   IF (p->'customerFields') ? 'org_number' AND (p->'customerFields') ? 'personal_number' THEN RAISE EXCEPTION 'ai_list_customer_identity_patch_ambiguous';END IF;
   IF (p->'customerFields') ? 'org_number' THEN customer_id:=p#>>'{customerFields,org_number}';ELSIF (p->'customerFields') ? 'personal_number' THEN customer_id:=p#>>'{customerFields,personal_number}';END IF;
   IF (p->'endUserMasterdata') ? 'name' THEN
    name:=p#>'{endUserMasterdata,name}';IF jsonb_typeof(name) IS DISTINCT FROM 'array' OR jsonb_array_length(name) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'ai_list_customer_name_patch_invalid';END IF;
    customer_name:=gridex_ai_processing.party_text_v1(jsonb_build_object('elements',jsonb_build_array(jsonb_build_array('NAD'),jsonb_build_array('UD'),'null'::jsonb,'null'::jsonb,name)),4,2);
   END IF;
  END IF;
  IF nullif(customer_id,'') IS NULL OR customer_id<>btrim(customer_id) OR length(customer_id)>35 OR customer_id~'[[:cntrl:];]' OR nullif(customer_name,'') IS NULL OR customer_name<>btrim(customer_name) OR customer_name~'[[:cntrl:];]' THEN RAISE EXCEPTION 'ai_list_customer_identity_patch_invalid';END IF;
 END LOOP;
 RETURN jsonb_build_object('customerId',customer_id,'customerName',customer_name,'startDay',start_day,'nextDay',next_day,'customerSourceMessageId',customer_source);
END$$;

--
-- Name: customer_row_epoch_v1(public.ediel_message_intents, timestamp with time zone, jsonb, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_row_epoch_v1(i public.ediel_message_intents, cutoff timestamp with time zone, baseline_ud jsonb, period_start text, requested_day text, search_end text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE history jsonb;p jsonb;customer_id text:=baseline_ud#>>'{elements,2,0}';customer_name text:=gridex_ai_processing.party_text_v1(baseline_ud,4,2);start_day text:=period_start;next_day text;day text;at timestamptz;name jsonb;BEGIN
 history:=gridex_customer_life_events.qualified_patches_v1(i.company_id,i.customer_id,gridex_received_sources.permission_time_v1(period_start||'0000'),gridex_received_sources.permission_time_v1(search_end||'0000'),cutoff);
 IF history->>'status' IS DISTINCT FROM 'authorized' OR history->>'authorizesInitialCustomer' IS DISTINCT FROM 'false' OR jsonb_array_length(history->'patches')>1000 THEN RAISE EXCEPTION 'ai_list_original_customer_patch_owner_required';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(history->'patches') LOOP
  IF NOT ((p->'customerFields') ?| ARRAY['org_number','personal_number']) AND NOT ((p->'endUserMasterdata') ? 'name') THEN CONTINUE;END IF;
  at:=(p->>'effectiveAt')::timestamptz;day:=to_char(at AT TIME ZONE 'Etc/GMT-1','YYYYMMDD');
  IF at IS DISTINCT FROM gridex_received_sources.permission_time_v1(day||'0000') THEN RAISE EXCEPTION 'ai_list_date_only_customer_boundary_unrepresentable';END IF;
  IF day>requested_day THEN next_day:=day;EXIT;END IF;start_day:=day;
  IF (p->'customerFields') ? 'org_number' AND (p->'customerFields') ? 'personal_number' THEN RAISE EXCEPTION 'ai_list_customer_identity_patch_ambiguous';END IF;
  IF (p->'customerFields') ? 'org_number' THEN customer_id:=p#>>'{customerFields,org_number}';ELSIF (p->'customerFields') ? 'personal_number' THEN customer_id:=p#>>'{customerFields,personal_number}';END IF;
  IF (p->'endUserMasterdata') ? 'name' THEN
   name:=p#>'{endUserMasterdata,name}';IF jsonb_typeof(name) IS DISTINCT FROM 'array' OR jsonb_array_length(name) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'ai_list_customer_name_patch_invalid';END IF;
   customer_name:=gridex_ai_processing.party_text_v1(jsonb_build_object('elements',jsonb_build_array(jsonb_build_array('NAD'),jsonb_build_array('UD'),'null'::jsonb,'null'::jsonb,name)),4,2);
  END IF;
  IF nullif(customer_id,'') IS NULL OR customer_id<>btrim(customer_id) OR length(customer_id)>35 OR customer_id~'[[:cntrl:];]' OR nullif(customer_name,'') IS NULL THEN RAISE EXCEPTION 'ai_list_customer_identity_patch_invalid';END IF;
 END LOOP;
 RETURN jsonb_build_object('customerId',customer_id,'customerName',customer_name,'startDay',start_day,'nextDay',next_day);
END$$;

--
-- Name: customer_source_object_composed_v1(jsonb, timestamp with time zone, public.ediel_message_intents, jsonb, jsonb, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.customer_source_object_composed_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, history jsonb, source jsonb, object_id text, agency text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE facet jsonb;wire jsonb;own jsonb;BEGIN
 IF NOT EXISTS(SELECT FROM public.ediel_messages m WHERE m.id::text=source->>'sourceMessageId' AND m.company_id=i.company_id AND m.environment=i.environment AND m.direction='inbound' AND m.message_family='PRODAT' AND m.raw_payload=source->>'rawPayload') THEN RETURN false;END IF;
 wire:=gridex_customer_life_events.wire_partition_v1(source->>'rawPayload');
 IF wire->>'family' IS DISTINCT FROM 'PRODAT' OR wire->>'code' IS DISTINCT FROM 'Z06' OR source->>'payloadHash' IS DISTINCT FROM encode(sha256(convert_to(source->>'rawPayload','UTF8')),'hex') THEN RETURN false;END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(wire->'objects') x WHERE x->>'point'=object_id AND x->>'identityAgency'=agency)<>1 THEN RETURN false;END IF;
 SELECT x INTO own FROM jsonb_array_elements(wire->'objects') x WHERE x->>'point'=object_id AND x->>'identityAgency'=agency;
 IF gridex_ai_processing.customer_only_patch_object_v1(i,history,source,object_id,agency) AND EXISTS(SELECT FROM jsonb_array_elements(history->'patches') p WHERE p->>'sourceMessageId'=source->>'sourceMessageId' AND p->>'sourcePayloadHash'=source->>'payloadHash' AND (p->>'effectiveAt')::timestamptz=(own->>'effectiveAt')::timestamptz) THEN RETURN true;END IF;
 facet:=gridex_requested_changes.customer_facet_basis_v1(body,cutoff,i.company_id,i.environment,i.customer_id,i.customer_site_id,source->>'sourceMessageId',object_id,agency);
 IF facet IS NULL OR facet->>'payloadHash' IS DISTINCT FROM source->>'payloadHash' OR facet->>'legalSender' IS DISTINCT FROM i.receiver_ediel_id OR facet->>'legalReceiver' IS DISTINCT FROM i.sender_ediel_id THEN RETURN false;END IF;
 RETURN own->>'projectionHeld' IS DISTINCT FROM 'true' AND own->>'reason'='E34' AND nullif(own->>'li','') IS NOT NULL AND (own->>'effectiveAt')::timestamptz=(facet->>'effectiveAt')::timestamptz AND (own#>>'{customerParty,1}' IN('SE1','SE2')) IS TRUE AND own#>>'{customerParty,2}'='260';
END$$;

--
-- Name: guard_attachment_storage_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_attachment_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE parent public.inbound_email_messages%rowtype;basis jsonb;
BEGIN
 IF TG_OP='UPDATE' AND (OLD.raw_text ~ '(^|\n)[\t ]*(AI|BI);' OR OLD.raw_text LIKE chr(65279)||'AI;%' OR OLD.raw_text LIKE chr(65279)||'BI;%')
  AND (NEW.raw_text IS DISTINCT FROM OLD.raw_text OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.inbound_email_message_id IS DISTINCT FROM OLD.inbound_email_message_id) THEN RAISE EXCEPTION 'ai_bi_personal_source_immutable'; END IF;
 IF NEW.raw_text IS NULL OR NOT (NEW.raw_text ~ '(^|\n)[\t ]*(AI|BI);' OR NEW.raw_text LIKE chr(65279)||'AI;%' OR NEW.raw_text LIKE chr(65279)||'BI;%') THEN RETURN NEW; END IF;
 SELECT * INTO parent FROM public.inbound_email_messages m WHERE m.id=NEW.inbound_email_message_id AND m.company_id=NEW.company_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ai_bi_personal_storage_parent_required'; END IF;
 basis:=gridex_ai_processing.personal_storage_basis_v1(NEW.company_id,parent.ai_processing_actor_user_id,parent.environment,NEW.raw_text);
 IF basis IS NULL OR parent.ai_processing_decision_id IS NULL OR parent.ai_processing_decision_id::text IS DISTINCT FROM basis->>'decisionId' THEN RAISE EXCEPTION 'ai_bi_processing_decision_mismatch'; END IF;
 RETURN NEW;
END $$;

--
-- Name: guard_import_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_import_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE assessment jsonb;
BEGIN
 assessment:=gridex_ai_processing.current_decision_v1(NEW.company_id,NEW.created_by,NEW.list_type);
 IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',assessment->>'blocker' USING ERRCODE='42501'; END IF;
 IF NEW.source_ediel_message_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.ediel_messages m WHERE m.id=NEW.source_ediel_message_id AND m.company_id=NEW.company_id AND m.direction='inbound'
  AND m.message_standard='ai_list' AND m.message_family='AI_LIST' AND m.message_code=NEW.list_type AND m.raw_payload=NEW.raw_payload AND m.immutable_rendered_at IS NOT NULL
  AND m.immutable_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'ai_bi_reconciliation_sealed_source_required' USING ERRCODE='42501'; END IF;
 IF NEW.processing_decision_id IS NULL OR NEW.processing_decision_id::text IS DISTINCT FROM assessment#>>'{decision,id}'
  OR NEW.gdpr_basis IS DISTINCT FROM assessment#>>'{decision,gdprBasis}' OR NEW.retention_until IS DISTINCT FROM (assessment#>>'{decision,retentionUntil}')::date THEN RAISE EXCEPTION 'ai_bi_processing_decision_mismatch' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;

--
-- Name: guard_mail_storage_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_mail_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE raw text;basis jsonb;candidate jsonb;old_ai boolean:=false;
BEGIN
 IF TG_OP='UPDATE' THEN
  FOREACH raw IN ARRAY ARRAY[OLD.raw_email,OLD.raw_edifact_payload,OLD.body_text,OLD.body_html] LOOP
   IF raw ~ '(^|\n)[\t ]*(AI|BI);' OR raw LIKE chr(65279)||'AI;%' OR raw LIKE chr(65279)||'BI;%' THEN old_ai:=true; END IF;
  END LOOP;
 END IF;
 IF TG_OP='UPDATE' AND (OLD.ai_processing_decision_id IS NOT NULL OR old_ai) AND (
  NEW.raw_email IS DISTINCT FROM OLD.raw_email OR NEW.raw_edifact_payload IS DISTINCT FROM OLD.raw_edifact_payload
  OR NEW.body_text IS DISTINCT FROM OLD.body_text OR NEW.body_html IS DISTINCT FROM OLD.body_html
  OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.ai_processing_actor_user_id IS DISTINCT FROM OLD.ai_processing_actor_user_id
  OR NEW.ai_processing_decision_id IS DISTINCT FROM OLD.ai_processing_decision_id) THEN RAISE EXCEPTION 'ai_bi_personal_source_immutable'; END IF;
 FOREACH raw IN ARRAY ARRAY[NEW.raw_email,NEW.raw_edifact_payload,NEW.body_text,NEW.body_html] LOOP
  candidate:=gridex_ai_processing.personal_storage_basis_v1(NEW.company_id,NEW.ai_processing_actor_user_id,NEW.environment,raw);
  IF candidate IS NOT NULL THEN
   IF basis IS NOT NULL AND basis IS DISTINCT FROM candidate THEN RAISE EXCEPTION 'ai_bi_personal_storage_mixed_scope'; END IF;
   basis:=candidate;
  END IF;
 END LOOP;
 IF basis IS NULL THEN
  IF NEW.ai_processing_decision_id IS NOT NULL OR NEW.message_family IN ('AI_LIST','BI_LIST') THEN RAISE EXCEPTION 'ai_bi_personal_storage_complete_source_required'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.ai_processing_decision_id IS NULL OR NEW.ai_processing_decision_id::text IS DISTINCT FROM basis->>'decisionId' THEN RAISE EXCEPTION 'ai_bi_processing_decision_mismatch'; END IF;
 RETURN NEW;
END $$;

--
-- Name: guard_message_storage_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_message_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE header text;h text[];basis jsonb;old_ai boolean:=false;new_ai boolean;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' THEN
  old_ai:=OLD.message_standard='ai_list' OR OLD.message_family IN ('AI_LIST','BI_LIST')
   OR OLD.raw_payload ~ '(^|\n)[\t ]*(AI|BI);' OR OLD.raw_payload LIKE chr(65279)||'AI;%' OR OLD.raw_payload LIKE chr(65279)||'BI;%';
  IF old_ai THEN
   IF NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.company_id IS DISTINCT FROM OLD.company_id
    OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.direction IS DISTINCT FROM OLD.direction
    OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.sender_ediel_id IS DISTINCT FROM OLD.sender_ediel_id
    OR NEW.receiver_ediel_id IS DISTINCT FROM OLD.receiver_ediel_id OR NEW.message_standard IS DISTINCT FROM OLD.message_standard
    OR NEW.message_family IS DISTINCT FROM OLD.message_family OR NEW.message_code IS DISTINCT FROM OLD.message_code
    OR NEW.immutable_payload_hash IS DISTINCT FROM OLD.immutable_payload_hash OR NEW.immutable_rendered_at IS DISTINCT FROM OLD.immutable_rendered_at
    THEN RAISE EXCEPTION 'ai_bi_personal_source_immutable'; END IF;
   -- A no-op write stores no new personal source and grants no new approval.
   -- Replay authority still comes only from the private immutable receipt.
   RETURN NEW;
  END IF;
 END IF;
 new_ai:=NEW.message_standard='ai_list' OR NEW.message_family IN ('AI_LIST','BI_LIST')
  OR NEW.raw_payload ~ '(^|\n)[\t ]*(AI|BI);' OR NEW.raw_payload LIKE chr(65279)||'AI;%' OR NEW.raw_payload LIKE chr(65279)||'BI;%';
 IF NOT coalesce(new_ai,false) THEN RETURN NEW; END IF;
 header:=split_part(replace(NEW.raw_payload,E'\r\n',E'\n'),E'\n',1);
 IF left(header,1)=chr(65279) THEN header:=substring(header FROM 2); END IF;
 h:=string_to_array(header,';');
 IF h IS NULL OR cardinality(h)<>10 OR h[1] NOT IN ('AI','BI') THEN RAISE EXCEPTION 'ai_bi_personal_storage_header_required'; END IF;
 IF NEW.message_standard IS DISTINCT FROM 'ai_list' OR NEW.message_family IS DISTINCT FROM 'AI_LIST'
  OR NEW.message_code IS DISTINCT FROM h[1] OR NEW.direction IS NULL OR NEW.direction NOT IN ('inbound','outbound')
  OR (NEW.direction='inbound' AND (NEW.sender_ediel_id IS DISTINCT FROM h[2] OR NEW.receiver_ediel_id IS DISTINCT FROM h[4]))
  THEN RAISE EXCEPTION 'ai_bi_personal_storage_source_context_mismatch'; END IF;
 IF NEW.direction='outbound' THEN
  PERFORM gridex_ai_processing.require_export_decision_for_intent_v1(NEW.company_id,NEW.created_by,NEW.intent_id);
  basis:=gridex_ai_processing.party_source_v1(NEW.company_id,NEW.intent_id);PERFORM gridex_ai_processing.require_party_wire_v1(NEW.raw_payload,basis);
  IF NEW.environment IS DISTINCT FROM basis->>'environment' OR NEW.sender_ediel_id IS DISTINCT FROM basis->>'technicalSender' OR NEW.receiver_ediel_id IS DISTINCT FROM basis->>'technicalReceiver' THEN RAISE EXCEPTION 'ai_bi_personal_storage_source_context_mismatch';END IF;
 ELSE
  basis:=gridex_ai_processing.personal_storage_basis_for_purpose_v1(NEW.company_id,NEW.created_by,NEW.environment,NEW.raw_payload,'ediel_list_reconciliation');
 END IF;
 IF basis IS NULL THEN RAISE EXCEPTION 'ai_bi_personal_storage_header_required'; END IF;
 NEW.immutable_payload_hash:=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex');
 NEW.immutable_rendered_at:=clock_timestamp();
 RETURN NEW;
END $$;

--
-- Name: guard_outbound_purpose_storage_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_outbound_purpose_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE decision jsonb;BEGIN
 IF NEW.direction='outbound' AND (NEW.message_standard='ai_list' OR NEW.message_family IN ('AI_LIST','BI_LIST') OR NEW.raw_payload ~ '(^|\n)[\t ]*(AI|BI);' OR NEW.raw_payload LIKE chr(65279)||'AI;%' OR NEW.raw_payload LIKE chr(65279)||'BI;%') THEN
  IF TG_OP='INSERT' THEN
   IF NEW.message_code IS DISTINCT FROM 'AI' THEN RAISE EXCEPTION 'ai_list_outbound_header_required'; END IF;
   PERFORM gridex_ai_processing.outbound_wire_v1(NEW.raw_payload);
   PERFORM gridex_ai_purpose_sources.consumer_v1(NEW.company_id,NEW.created_by,'origination',NEW.environment);decision:=gridex_ai_purpose_sources.current_for_scope_v1(NEW.company_id,'AI','ediel_list_export',NEW.environment);IF decision->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ai_purpose_actual_row_environment_required';END IF;
  ELSIF NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.direction IS DISTINCT FROM OLD.direction OR NEW.environment IS DISTINCT FROM OLD.environment THEN
   PERFORM gridex_ai_purpose_sources.consumer_v1(NEW.company_id,NEW.created_by,'origination',NEW.environment);decision:=gridex_ai_purpose_sources.current_for_scope_v1(NEW.company_id,'AI','ediel_list_export',NEW.environment);IF decision->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ai_purpose_actual_row_environment_required';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: guard_payload_storage_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.guard_payload_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE env text;basis jsonb;
BEGIN
 IF TG_OP='UPDATE' AND (OLD.raw_payload ~ '(^|\n)[\t ]*(AI|BI);' OR OLD.raw_payload LIKE chr(65279)||'AI;%' OR OLD.raw_payload LIKE chr(65279)||'BI;%')
  AND (NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.created_by IS DISTINCT FROM OLD.created_by
  OR NEW.ediel_message_id IS DISTINCT FROM OLD.ediel_message_id OR NEW.inbound_email_message_id IS DISTINCT FROM OLD.inbound_email_message_id) THEN RAISE EXCEPTION 'ai_bi_personal_source_immutable'; END IF;
 IF NEW.raw_payload IS NULL OR NOT (NEW.raw_payload ~ '(^|\n)[\t ]*(AI|BI);' OR NEW.raw_payload LIKE chr(65279)||'AI;%' OR NEW.raw_payload LIKE chr(65279)||'BI;%') THEN RETURN NEW; END IF;
 IF NEW.ediel_message_id IS NOT NULL THEN
  SELECT m.environment INTO env FROM public.ediel_messages m WHERE m.id=NEW.ediel_message_id AND m.company_id=NEW.company_id AND m.immutable_rendered_at IS NOT NULL FOR SHARE;
 ELSIF NEW.inbound_email_message_id IS NOT NULL THEN
  SELECT m.environment INTO env FROM public.inbound_email_messages m WHERE m.id=NEW.inbound_email_message_id AND m.company_id=NEW.company_id AND m.ai_processing_actor_user_id=NEW.created_by AND m.ai_processing_decision_id IS NOT NULL FOR SHARE;
 END IF;
 IF env IS NULL THEN RAISE EXCEPTION 'ai_bi_personal_storage_parent_required'; END IF;
 basis:=gridex_ai_processing.personal_storage_basis_v1(NEW.company_id,NEW.created_by,env,NEW.raw_payload);
 IF basis IS NULL THEN RAISE EXCEPTION 'ai_bi_personal_storage_header_required'; END IF;
 RETURN NEW;
END $$;

--
-- Name: header_company_basis_v1(uuid, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.header_company_basis_v1(c uuid, env text, supplier_id text, network_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor_count bigint;id_count bigint; legal_actor uuid;legal_id text;network_basis jsonb;
BEGIN
 IF c IS NULL OR env IS NULL OR env NOT IN ('test','production') OR supplier_id IS NULL OR network_id IS NULL THEN RAISE EXCEPTION 'ai_bi_header_tenant_context_required'; END IF;
 -- Native consistency guard of the canonicalTenantEdielIdentity owner inputs,
 -- with the same unique legal actor/ID, supplier role and half-open intervals.
 -- Technical transport identity and mailbox owner never supply legal parties.
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=env ORDER BY p.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=env ORDER BY r.id FOR SHARE;
 SELECT count(DISTINCT i.actor_id),count(DISTINCT nullif(btrim(i.identifier_value),'')),min(i.actor_id::text)::uuid,min(nullif(btrim(i.identifier_value),''))
 INTO actor_count,id_count,legal_actor,legal_id FROM public.tenant_actor_identifiers i
 WHERE i.company_id=c AND i.environment=env AND i.identifier_type='EdielId' AND i.valid_from<=statement_timestamp() AND (i.valid_to IS NULL OR statement_timestamp()<i.valid_to);
 IF actor_count<>1 OR id_count<>1 OR legal_id IS DISTINCT FROM supplier_id
 OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=env AND p.market='electricity' AND p.is_enabled AND p.valid_from<=statement_timestamp() AND (p.valid_to IS NULL OR statement_timestamp()<p.valid_to))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=env AND r.actor_id=legal_actor AND btrim(r.role_code)='electricity_supplier' AND r.valid_from<=statement_timestamp() AND (r.valid_to IS NULL OR statement_timestamp()<r.valid_to)) THEN RAISE EXCEPTION 'ai_bi_header_supplier_tenant_mismatch'; END IF;
 network_basis:=gridex_network_registry_sources.network_for_company_v1(c,network_id,env);
 IF network_basis->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(network_basis->>'blocker','ai_bi_network_registry_version_unqualified'); END IF;
 RETURN jsonb_build_object('legalActorId',legal_actor,'legalSupplier',legal_id,'companyId',c,'environment',env,'network',network_basis);
END $$;

--
-- Name: intent_basis_v1(public.ediel_message_intents); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.intent_basis_v1(i public.ediel_message_intents) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT jsonb_build_object('companyId',i.company_id,'environment',i.environment,'operationId',i.operation_id,
 'customerId',i.customer_id,'siteId',i.customer_site_id,'meteringPointId',nullif(i.metering_point_id,''),'routeId',i.communication_route_id,'routeProfileId',i.route_profile_id,
 'supplier',i.sender_ediel_id,'network',i.receiver_ediel_id,'payload',i.payload)$$;

--
-- Name: intent_request_before_operation_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.intent_request_before_operation_v1(c uuid, intent uuid) RETURNS public.ediel_message_intents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;profile jsonb:=gridex_ai_processing.native_profile_v1();
BEGIN
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=intent AND company_id=c FOR UPDATE;
 IF NOT FOUND OR i.environment NOT IN ('test','production') OR i.message_family IS DISTINCT FROM 'AI_LIST' OR i.message_code IS DISTINCT FROM 'AI'
  OR i.direction IS DISTINCT FROM 'outbound' OR i.business_process IS DISTINCT FROM 'reconciliation' OR i.validation_status IS DISTINCT FROM 'validated'
  OR i.customer_id IS NULL OR i.customer_site_id IS NULL OR i.communication_route_id IS NULL OR i.route_profile_id IS NULL
  OR i.application_reference IS DISTINCT FROM '' OR i.interchange_reference IS DISTINCT FROM '' OR i.message_reference IS DISTINCT FROM '' OR nullif(i.transaction_reference,'') IS NOT NULL
  OR i.payload->>'owner' IS DISTINCT FROM 'ai-list-export-request-v1' OR i.payload->>'sourceSha256' IS DISTINCT FROM profile->>'sourceSha256'
  OR i.payload->>'technicalVersion' IS DISTINCT FROM profile->>'technicalVersion' OR nullif(i.payload->>'requestId','') IS NULL THEN RAISE EXCEPTION 'ai_list_validated_technical_intent_required'; END IF;
 IF gridex_ai_processing.technical_date_v1(replace(i.payload->>'fromDate','-',''))>=gridex_ai_processing.technical_date_v1(replace(i.payload->>'toDate','-','')) THEN RAISE EXCEPTION 'ai_list_search_period_invalid'; END IF;
 RETURN i;
END $$;

--
-- Name: intent_request_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.intent_request_v1(c uuid, intent uuid) RETURNS public.ediel_message_intents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;BEGIN
 i:=gridex_ai_processing.intent_request_before_operation_v1(c,intent);
 IF i.market IS DISTINCT FROM 'electricity' OR i.operation_id IS NULL OR i.payload->>'requestId' IS DISTINCT FROM i.operation_id::text
  OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb
  OR i.supplier_switch_request_id IS NOT NULL OR i.customer_info_request_id IS NOT NULL OR i.grid_owner_information_request_id IS NOT NULL THEN
  RAISE EXCEPTION 'ai_list_validated_technical_operation_required';
 END IF;
 RETURN i;
END $$;

--
-- Name: legal_history_intent_v1(public.ediel_message_intents, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.legal_history_intent_v1(i public.ediel_message_intents, raw text) RETURNS public.ediel_message_intents
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE wire jsonb;BEGIN
 wire:=gridex_ai_processing.outbound_wire_v1(raw);
 i.sender_ediel_id:=wire->>'supplierEdielId';i.receiver_ediel_id:=wire->>'networkEdielId';RETURN i;
END$$;

