-- Name: native_profile_v1(); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.native_profile_v1() RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
-- BEGIN CANONICAL AI PROFILE PROJECTION
 SELECT '{"sourceId":"AI","guideRevision":"14.A.3","technicalVersion":"Ver20140401","sourceSha256":"c5815bacbc40beb1ee1b36cb03c71a089fbc18cda3368811afadcdca78899351","format":"CSV","provenance":"frozen_masterplan_projection"}'::jsonb
-- END CANONICAL AI PROFILE PROJECTION
$$;

--
-- Name: network_registry_basis_v1(text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.network_registry_basis_v1(network_id text, env text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('status','held','blocker','ai_bi_network_registry_version_unqualified')
$$;

--
-- Name: outbound_wire_v1(text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.outbound_wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE profile jsonb:=gridex_ai_processing.native_profile_v1();normalized text;records text[];h text[];cols text[];i integer;
 from_date date;to_date date;start_date date;end_date date;
BEGIN
 IF raw IS NULL OR octet_length(raw)>10485760 THEN RAISE EXCEPTION 'ai_list_resource_bound'; END IF;
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2); END IF;
 IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1); END IF;
 IF replace(normalized,E'\n','') ~ '[\r\x01-\x1f\x7f]' THEN RAISE EXCEPTION 'ai_list_cell_separator_invalid'; END IF;
 records:=string_to_array(normalized,E'\n');IF cardinality(records)>100001 OR cardinality(records)<1 OR ''=ANY(records) THEN RAISE EXCEPTION 'ai_list_record_empty'; END IF;
 h:=string_to_array(records[1],';');
 IF cardinality(h)<>10 OR h[1] IS DISTINCT FROM 'AI' THEN RAISE EXCEPTION 'ai_list_outbound_header_required'; END IF;
 IF h[10] IS DISTINCT FROM profile->>'technicalVersion' THEN RAISE EXCEPTION 'ai_list_version_unsupported'; END IF;
 IF h[2]!~ '^[0-9]{5}$' OR h[4]!~ '^[0-9]{5}$' OR btrim(h[3])='' OR btrim(h[5])='' THEN RAISE EXCEPTION 'ai_list_header_parties_required'; END IF;
 IF h[6]!~ '^[0-9]{12}$' OR substring(h[6],9,2)::integer>23 OR substring(h[6],11,2)::integer>59 THEN RAISE EXCEPTION 'ai_list_creation_date_invalid'; END IF;
 PERFORM gridex_ai_processing.technical_date_v1(substring(h[6],1,8));
 from_date:=gridex_ai_processing.technical_date_v1(h[8]);to_date:=gridex_ai_processing.technical_date_v1(h[9]);
 IF h[7]<>'' OR from_date>=to_date THEN RAISE EXCEPTION 'ai_list_search_period_invalid'; END IF;
 FOR i IN 2..cardinality(records) LOOP
  cols:=string_to_array(records[i],';');
  IF cardinality(cols)<>22 OR cols[22]<>'' OR cols[1]='' OR cols[2]='' OR cols[3] NOT IN ('9','89') OR cols[3]='9' AND cols[2]!~ '^[0-9]{18}$' THEN RAISE EXCEPTION 'ai_list_detail_object_invalid'; END IF;
  IF cols[4:7]<>ARRAY['','','',''] OR cols[11]='' OR cols[18]='' OR cols[19]='' THEN RAISE EXCEPTION 'ai_list_detail_required_fields_missing'; END IF;
  IF cols[12:17]<>ARRAY['','','','','',''] THEN RAISE EXCEPTION 'ai_list_supplier_network_fields_present'; END IF;
  start_date:=NULL;end_date:=NULL;
  IF cols[20]<>'' THEN start_date:=gridex_ai_processing.technical_date_v1(cols[20]);IF start_date<from_date OR start_date>=to_date THEN RAISE EXCEPTION 'ai_list_detail_period_invalid'; END IF; END IF;
  IF cols[21]<>'' THEN end_date:=gridex_ai_processing.technical_date_v1(cols[21]);IF end_date<from_date OR end_date>=to_date THEN RAISE EXCEPTION 'ai_list_detail_period_invalid'; END IF; END IF;
  IF start_date IS NOT NULL AND end_date IS NOT NULL AND start_date>=end_date THEN RAISE EXCEPTION 'ai_list_detail_period_invalid'; END IF;
 END LOOP;
 RETURN jsonb_build_object('networkEdielId',h[2],'supplierEdielId',h[4],'rowCount',greatest(cardinality(records)-1,0),'profile',profile);
END $_$;

--
-- Name: party_source_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.party_source_v1(c uuid, intent uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;q jsonb;supplier jsonb;header jsonb;mandate jsonb;legal_actor uuid;legal_id text;
 relation public.tenant_counterparty_relations%rowtype;transport_actor uuid;transport_id text;n integer;facts jsonb;
BEGIN
 i:=gridex_ai_processing.intent_request_v1(c,intent);
 -- Actual current profile and SMTP tuple, separately from legal network ID.
 q:=gridex_registry_import.dispatch_source_v1(c,i.communication_route_id,i.route_profile_id,i.environment,'AI_LIST',NULL);
 IF q IS NULL OR q->>'status' IS DISTINCT FROM 'source_qualified' OR q->>'market' IS DISTINCT FROM 'EL' OR q#>>'{wire,family}' IS DISTINCT FROM 'AI'
  OR q#>>'{wire,applicationReference}' IS NOT NULL OR q->>'legalName' IS NULL OR btrim(q->>'legalName')='' THEN RAISE EXCEPTION 'ai_list_actual_network_dispatch_source_required';END IF;
 PERFORM x.id FROM public.tenant_actor_identifiers x WHERE x.company_id=c AND x.environment=i.environment ORDER BY x.id FOR SHARE;
 SELECT count(DISTINCT(x.actor_id,btrim(x.identifier_value))) INTO n FROM public.tenant_actor_identifiers x WHERE x.company_id=c AND x.environment=i.environment AND x.identifier_type='EdielId' AND x.valid_from<=statement_timestamp() AND(x.valid_to IS NULL OR statement_timestamp()<x.valid_to);
 IF n<>1 THEN RAISE EXCEPTION 'ai_list_unique_legal_supplier_required';END IF;
 SELECT x.actor_id,btrim(x.identifier_value) INTO legal_actor,legal_id FROM public.tenant_actor_identifiers x WHERE x.company_id=c AND x.environment=i.environment AND x.identifier_type='EdielId' AND x.valid_from<=statement_timestamp() AND(x.valid_to IS NULL OR statement_timestamp()<x.valid_to);
 -- This SAME private owner requires current unique supplier role/profile and
 -- authenticated versioned network-owner evidence. Its external hold remains.
 header:=gridex_ai_processing.header_company_basis_v1(c,i.environment,legal_id,q->>'legalEdielId');
 IF header->>'legalActorId' IS DISTINCT FROM legal_actor::text OR header->>'legalSupplier' IS DISTINCT FROM legal_id THEN RAISE EXCEPTION 'ai_list_legal_supplier_source_changed';END IF;
 supplier:=gridex_registry_import.current_el_tenant_actor_source_v1(c,legal_actor,i.environment);
 IF supplier->>'status' IS DISTINCT FROM 'source_qualified' OR supplier->>'legalEdielId' IS DISTINCT FROM legal_id OR supplier->>'legalName' IS NULL OR btrim(supplier->>'legalName')='' THEN RAISE EXCEPTION 'ai_list_supplier_original_name_source_required';END IF;
 PERFORM x.id FROM public.tenant_counterparty_relations x WHERE x.company_id=c AND x.environment=i.environment AND x.relation_type='ediel_transport_agent' ORDER BY x.id FOR SHARE;
 SELECT count(*) INTO n FROM public.tenant_counterparty_relations x WHERE x.company_id=c AND x.environment=i.environment AND x.relation_type='ediel_transport_agent' AND x.is_enabled AND x.valid_from<=statement_timestamp() AND(x.valid_to IS NULL OR statement_timestamp()<x.valid_to);
 IF n>1 THEN RAISE EXCEPTION 'ai_list_current_transport_ambiguous';END IF;
 transport_actor:=legal_actor;transport_id:=legal_id;
 IF n=1 THEN
  SELECT * INTO relation FROM public.tenant_counterparty_relations x WHERE x.company_id=c AND x.environment=i.environment AND x.relation_type='ediel_transport_agent' AND x.is_enabled AND x.valid_from<=statement_timestamp() AND(x.valid_to IS NULL OR statement_timestamp()<x.valid_to);
  transport_actor:=relation.counterparty_actor_id;
  PERFORM x.id FROM public.platform_actor_identifiers x WHERE x.actor_id=transport_actor ORDER BY x.id FOR SHARE;
  SELECT count(DISTINCT btrim(x.identifier_value)),min(btrim(x.identifier_value)) INTO n,transport_id FROM public.platform_actor_identifiers x WHERE x.actor_id=transport_actor AND x.identifier_type='EdielId' AND(x.valid_from IS NULL OR x.valid_from<=statement_timestamp()::date) AND(x.valid_to IS NULL OR statement_timestamp()::date<=x.valid_to);
  IF transport_actor=legal_actor OR n<>1 OR nullif(transport_id,'') IS NULL OR transport_id=legal_id THEN RAISE EXCEPTION 'ai_list_current_transport_identity_unqualified';END IF;
  mandate:=gridex_ai_processing.transport_mandate_basis_v1(c,i.environment,legal_actor,transport_actor,relation.id);
  IF mandate->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(mandate->>'blocker','ai_list_transport_mandate_source_unqualified');END IF;
 END IF;
 IF NOT EXISTS(SELECT FROM public.ediel_route_profiles p WHERE p.id=i.route_profile_id AND p.company_id=c AND p.sender_ediel_id=transport_id) THEN RAISE EXCEPTION 'ai_list_current_profile_technical_sender_mismatch';END IF;
 IF (nullif(i.payload->>'expectedLegalSupplier','') IS NOT NULL AND i.payload->>'expectedLegalSupplier' IS DISTINCT FROM legal_id) OR (nullif(i.payload->>'expectedLegalNetwork','') IS NOT NULL AND i.payload->>'expectedLegalNetwork' IS DISTINCT FROM q->>'legalEdielId') THEN RAISE EXCEPTION 'ai_list_expected_legal_party_mismatch';END IF;
 IF i.sender_ediel_id IS DISTINCT FROM transport_id OR i.receiver_ediel_id IS DISTINCT FROM q#>>'{wire,interchangePartyId}' THEN RAISE EXCEPTION 'ai_list_technical_intent_party_source_mismatch';END IF;
 facts:=jsonb_build_object('supplier',supplier,'networkDispatch',q,'tenantHeader',header,'networkOwner',header->'network','transportRelation',CASE WHEN relation.id IS NULL THEN NULL ELSE to_jsonb(relation) END,
  'transportIdentifiers',CASE WHEN relation.id IS NULL THEN NULL ELSE(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.platform_actor_identifiers x WHERE x.actor_id=transport_actor AND x.identifier_type='EdielId' AND(x.valid_from IS NULL OR x.valid_from<=statement_timestamp()::date) AND(x.valid_to IS NULL OR statement_timestamp()::date<=x.valid_to)) END,'transportMandate',mandate);
 RETURN jsonb_build_object('status','source_qualified','companyId',c,'environment',i.environment,'intentId',i.id,'communicationRouteId',i.communication_route_id,'routeProfileId',i.route_profile_id,
  'legalActorId',legal_actor,'transportActorId',transport_actor,'legalSupplier',legal_id,'legalSupplierName',supplier->'legalName','legalNetwork',q->'legalEdielId','legalNetworkName',q->'legalName',
  'technicalSender',transport_id,'technicalReceiver',q#>'{wire,interchangePartyId}','sourceBasis',facts);
END$$;

--
-- Name: party_text_v1(jsonb, integer, integer); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.party_text_v1(token jsonb, element integer, capacity integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE values text[];last integer;
BEGIN
 SELECT array_agg(btrim(value) ORDER BY ordinal) INTO values FROM jsonb_array_elements_text(token#>ARRAY['elements',element::text]) WITH ORDINALITY v(value,ordinal) WHERE ordinal<=capacity;
 last:=cardinality(values);WHILE last>0 AND values[last]='' LOOP last:=last-1;END LOOP;
 RETURN coalesce(array_to_string(values[1:last],E'\n'),'');
END $$;

--
-- Name: personal_storage_basis_for_purpose_v1(uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.personal_storage_basis_for_purpose_v1(c uuid, actor uuid, env text, raw text, purpose text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE line text;h text[];assessment jsonb;basis jsonb;previous jsonb;
BEGIN
 FOR line IN SELECT l FROM regexp_split_to_table(replace(raw,E'\r\n',E'\n'),E'\n') l WHERE l ~ '^[\t ]*(AI|BI);' OR l LIKE chr(65279)||'AI;%' OR l LIKE chr(65279)||'BI;%' LOOP
  IF left(line,1)=chr(65279) THEN line:=substring(line FROM 2); END IF;
  h:=string_to_array(line,';');
  IF cardinality(h)<>10 OR h[1] NOT IN ('AI','BI') THEN RAISE EXCEPTION 'ai_bi_personal_storage_header_required'; END IF;
  PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
  PERFORM p.id FROM public.user_profiles p WHERE p.id=actor FOR SHARE;
  PERFORM gridex_ai_purpose_sources.consumer_v1(c,actor,'origination',env);assessment:=gridex_ai_purpose_sources.current_for_scope_v1(c,h[1],purpose,env);
  IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(assessment->>'blocker','ai_bi_processing_decision_invalid') USING ERRCODE='42501'; END IF;
  basis:=jsonb_build_object('listType',h[1],'decisionId',assessment#>>'{decision,id}','headerBasis',gridex_ai_processing.header_company_basis_v1(c,env,h[4],h[2]));
  IF previous IS NOT NULL AND previous IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ai_bi_personal_storage_mixed_scope'; END IF;
  previous:=basis;
 END LOOP;
 RETURN previous;
END $$;

--
-- Name: personal_storage_basis_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.personal_storage_basis_v1(c uuid, actor uuid, env text, raw text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ SELECT gridex_ai_processing.personal_storage_basis_for_purpose_v1(c,actor,env,raw,'ediel_list_reconciliation') $$;

--
-- Name: purpose_decision_after_actor_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.purpose_decision_after_actor_v1(c uuid, list_type text, purpose text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ai_purpose_sources.current_for_scope_v1(c,list_type,purpose,NULL)$$;

--
-- Name: reconcile_source_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.reconcile_source_v1(c uuid, actor uuid, source_id uuid, expected_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
<<reconciliation>>
DECLARE m public.ediel_messages%rowtype; receipt gridex_ai_processing.reconciliation_receipts%rowtype;
 assessment jsonb; header_basis jsonb;import_id uuid; import_row_id uuid; result jsonb; records text[]; head text[]; cols text[];
 raw_columns jsonb; current_values jsonb; reasons text[]; matching integer; matched_rows jsonb; point public.metering_points%rowtype;
 i integer; row_count integer:=0; discrepancy_count integer:=0; normalized text; source_type text;
BEGIN
 IF c IS NULL OR actor IS NULL OR source_id IS NULL OR expected_hash IS NULL OR expected_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'ai_bi_reconciliation_scope_required'; END IF;
 PERFORM a.user_id FROM public.company_memberships a WHERE a.company_id=c AND a.user_id=actor FOR SHARE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships a WHERE a.company_id=c AND a.user_id=actor AND a.status='active' AND a.is_active AND a.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
 OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.write'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel_testing.write'),false)) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.ediel_messages s WHERE s.id=source_id AND s.company_id=c FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'ai_list' OR m.message_family IS DISTINCT FROM 'AI_LIST'
  OR m.message_code IS NULL OR m.message_code NOT IN ('AI','BI') OR m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM expected_hash
  OR expected_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ai_bi_reconciliation_sealed_source_required'; END IF;
 IF gridex_requested_changes.actor_v1(c,actor,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'ai_bi_current_scoped_read_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO receipt FROM gridex_ai_processing.reconciliation_receipts r WHERE r.source_message_id=source_id;
 IF FOUND THEN
  IF receipt.company_id<>c OR receipt.source_payload_hash<>expected_hash THEN RAISE EXCEPTION 'ai_bi_reconciliation_source_conflict'; END IF;
  RETURN receipt.result;
 END IF;
 -- A prior partial legacy import is not evidence of a whole atomic result.
 IF EXISTS(SELECT FROM public.ai_list_imports x WHERE x.source_ediel_message_id=source_id) THEN RAISE EXCEPTION 'ai_bi_legacy_reconciliation_requires_review'; END IF;
 PERFORM gridex_ai_purpose_sources.consumer_v1(c,actor,'origination',m.environment);assessment:=gridex_ai_purpose_sources.current_for_scope_v1(c,m.message_code,'ediel_list_reconciliation',m.environment);
 IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(assessment->>'blocker','ai_bi_processing_decision_invalid') USING ERRCODE='42501'; END IF;
 IF assessment#>>'{decision,companyId}' IS DISTINCT FROM c::text OR assessment#>>'{decision,listType}' IS DISTINCT FROM m.message_code THEN RAISE EXCEPTION 'ai_bi_processing_decision_mismatch'; END IF;
 -- Bounded physical records, not a second guide-version selector. The actual
 -- native source supplies every column; no caller matching/projection is used.
 IF octet_length(m.raw_payload)>10485760 THEN RAISE EXCEPTION 'ai_bi_reconciliation_resource_bound'; END IF;
 normalized:=replace(m.raw_payload,E'\r\n',E'\n');
 IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2); END IF;
 IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1); END IF;
 IF replace(normalized,E'\n','') ~ '[\r\x01-\x1f\x7f]' THEN RAISE EXCEPTION 'ai_bi_reconciliation_source_records_invalid'; END IF;
 records:=string_to_array(normalized,E'\n');
 IF cardinality(records)>100001 THEN RAISE EXCEPTION 'ai_bi_reconciliation_resource_bound'; END IF;
 head:=string_to_array(records[1],';');source_type:=head[1];
 IF cardinality(head)<>10 OR source_type IS DISTINCT FROM m.message_code OR source_type NOT IN ('AI','BI') OR head[2]!~ '^[0-9]{5}$' OR head[4]!~ '^[0-9]{5}$' THEN RAISE EXCEPTION 'ai_bi_reconciliation_source_records_invalid'; END IF;
 IF m.sender_ediel_id IS DISTINCT FROM head[2] OR m.receiver_ediel_id IS DISTINCT FROM head[4] THEN RAISE EXCEPTION 'ai_bi_reconciliation_source_party_mismatch'; END IF;
 header_basis:=gridex_ai_processing.header_company_basis_v1(c,m.environment,head[4],head[2]);
 FOR i IN 2..cardinality(records) LOOP
  cols:=string_to_array(records[i],';');
  IF cardinality(cols)<>22 OR cols[22]<>'' OR cols[1]='' OR cols[2]='' OR cols[3] NOT IN ('9','89') OR cols[3]='9' AND cols[2]!~ '^[0-9]{18}$' THEN RAISE EXCEPTION 'ai_bi_reconciliation_source_records_invalid'; END IF;
 END LOOP;
 INSERT INTO public.ai_list_imports(company_id,list_type,filename,grid_owner_id,status,row_count,raw_payload,metadata,retention_until,gdpr_basis,created_by,processing_decision_id,source_ediel_message_id)
 VALUES(c,source_type,m.file_name,m.grid_owner_id,'parsed',greatest(cardinality(records)-1,0),m.raw_payload,
  jsonb_build_object('reconciliationOnly',true,'masterdataAutoOverwrite',false,'rawColumnsFormat','physical_columns_v1','processingDecision',assessment->'decision','headerBasis',header_basis),
  (assessment#>>'{decision,retentionUntil}')::date,assessment#>>'{decision,gdprBasis}',actor,(assessment#>>'{decision,id}')::uuid,source_id) RETURNING id INTO import_id;
 FOR i IN 2..cardinality(records) LOOP
  cols:=string_to_array(records[i],';'); reasons:=ARRAY[]::text[];current_values:='{}'::jsonb;point:=NULL;matching:=0;
  raw_columns:=jsonb_build_object('physical_columns',to_jsonb(cols[1:21]),'source_row_number',i);
  IF cols[3]='9' THEN
   SELECT count(*),jsonb_agg(to_jsonb(candidate)) INTO matching,matched_rows FROM (
    SELECT p.* FROM public.metering_points p WHERE p.company_id=c AND cols[2] IN (p.metering_point_id,p.meter_point_id,p.ediel_reference,p.site_facility_id) FOR SHARE
   ) candidate;
   IF matching=1 THEN
    point:=jsonb_populate_record(NULL::public.metering_points,matched_rows->0);
    IF point.customer_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=c)
     OR coalesce(point.customer_site_id,point.site_id) IS NOT NULL AND NOT EXISTS(SELECT FROM public.customer_sites s WHERE s.id=coalesce(point.customer_site_id,point.site_id) AND s.company_id=c) THEN point:=NULL;matching:=0; END IF;
   END IF;
  END IF;
  IF cols[3]<>'9' THEN reasons:=array_append(reasons,'object_identity_agency_unqualified');
  ELSIF matching>1 THEN reasons:=array_append(reasons,'metering_point_ambiguous');
  ELSIF point.id IS NULL THEN reasons:=array_append(reasons,'metering_point_not_found'); END IF;
  IF point.id IS NOT NULL THEN
   current_values:=jsonb_build_object('id',point.id,'company_id',point.company_id,'customer_id',point.customer_id,'site_id',coalesce(point.customer_site_id,point.site_id),'grid_area_code',point.grid_area_code,'grid_owner_ediel_id',point.grid_owner_ediel_id);
   IF nullif(btrim(point.grid_area_code),'') IS NOT NULL AND upper(regexp_replace(point.grid_area_code,'\s','','g')) IS DISTINCT FROM upper(regexp_replace(cols[1],'\s','','g')) THEN reasons:=array_append(reasons,'grid_area_mismatch'); END IF;
   IF nullif(btrim(point.grid_owner_ediel_id),'') IS NOT NULL AND point.grid_owner_ediel_id IS DISTINCT FROM head[2] THEN reasons:=array_append(reasons,'grid_owner_mismatch'); END IF;
  END IF;
  INSERT INTO public.ai_list_import_rows(company_id,import_id,row_number,raw_columns,metering_point_external_id,matched_metering_point_id,matched_customer_id,matched_customer_site_id,match_status,discrepancy_reasons)
  VALUES(c,import_id,i,raw_columns,cols[2],point.id,point.customer_id,coalesce(point.customer_site_id,point.site_id),CASE WHEN point.id IS NULL THEN 'unmatched' WHEN cardinality(reasons)>0 THEN 'discrepancy' ELSE 'matched' END,reasons) RETURNING id INTO import_row_id;
  IF cardinality(reasons)>0 THEN
   discrepancy_count:=discrepancy_count+1;
   INSERT INTO public.ai_list_discrepancies(company_id,import_id,import_row_id,discrepancy_type,severity,current_values,imported_values,status)
   VALUES(c,import_id,import_row_id,reasons[1],CASE WHEN point.id IS NULL THEN 'warning' ELSE 'info' END,current_values,raw_columns,'open');
  END IF;
  row_count:=row_count+1;
 END LOOP;
 UPDATE public.ai_list_imports x SET status=CASE WHEN reconciliation.discrepancy_count>0 THEN 'review_required' ELSE 'matched' END,discrepancy_count=reconciliation.discrepancy_count WHERE x.id=reconciliation.import_id AND x.company_id=c;
 result:=jsonb_build_object('status','applied','importId',import_id,'rowCount',row_count,'discrepancyCount',discrepancy_count);
 INSERT INTO gridex_ai_processing.reconciliation_receipts(source_message_id,company_id,source_payload_hash,import_id,processing_decision_id,actor_user_id,header_basis,result)
 VALUES(source_id,c,expected_hash,import_id,(assessment#>>'{decision,id}')::uuid,actor,header_basis,result);
 RETURN result;
END $_$;

--
-- Name: require_ai_origin_before_customer_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_origin_before_customer_v1(c uuid, message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE proof jsonb;m public.ediel_messages%rowtype;i public.ediel_message_intents%rowtype;o gridex_ai_processing.outbound_origins%rowtype;BEGIN
 proof:=gridex_ai_processing.require_ai_outbound_origin_before_operation_v1(c,message_id);
 SELECT * INTO m FROM public.ediel_messages WHERE id=message_id AND company_id=c FOR SHARE;
 i:=gridex_ai_processing.intent_request_v1(c,m.intent_id);
 SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=i.id AND company_id=c FOR SHARE;
 IF o.operation_id IS DISTINCT FROM i.operation_id OR o.intent_basis IS DISTINCT FROM gridex_ai_processing.intent_basis_v1(i) OR to_jsonb(m)->>'source_operation_id' IS DISTINCT FROM i.operation_id::text THEN RAISE EXCEPTION 'ai_list_private_original_conflict'; END IF;
 RETURN proof||jsonb_build_object('operationId',i.operation_id);
END $$;

--
-- Name: require_ai_outbound_origin_before_operation_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_outbound_origin_before_operation_v1(c uuid, message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_ai_processing.outbound_origins%rowtype;b gridex_ai_processing.outbound_origin_bindings%rowtype;i public.ediel_message_intents%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message_id AND company_id=c FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_private_original_required'; END IF;
 SELECT * INTO b FROM gridex_ai_processing.outbound_origin_bindings binding WHERE binding.message_id=m.id AND binding.company_id=c FOR SHARE;
 IF NOT FOUND OR b.payload_hash IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'ai_list_private_original_required'; END IF;
 SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=b.intent_id AND company_id=c FOR SHARE;
 i:=gridex_ai_processing.intent_request_v1(c,b.intent_id);
 IF o.payload_hash IS DISTINCT FROM m.immutable_payload_hash OR o.raw_payload IS DISTINCT FROM m.raw_payload OR o.environment IS DISTINCT FROM m.environment OR m.intent_id IS DISTINCT FROM i.id
  OR m.communication_route_id IS DISTINCT FROM i.communication_route_id OR m.route_profile_id IS DISTINCT FROM i.route_profile_id OR m.customer_id IS DISTINCT FROM i.customer_id OR m.site_id IS DISTINCT FROM i.customer_site_id THEN RAISE EXCEPTION 'ai_list_private_original_conflict'; END IF;
 RETURN jsonb_build_object('intentId',i.id,'snapshotId',o.snapshot_id,'readsetHash',o.readset_hash,'sourceHash',o.payload_hash,'sourceIds',o.source_ids);
END $$;

--
-- Name: require_ai_outbound_origin_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_outbound_origin_v1(c uuid, message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;o gridex_ai_processing.outbound_origins%rowtype;snap gridex_received_sources.object_selection_snapshots%rowtype;i public.ediel_message_intents%rowtype;
BEGIN
 result:=gridex_ai_processing.require_ai_origin_before_customer_v1(c,message_id);
 SELECT * INTO o FROM gridex_ai_processing.outbound_origins x WHERE x.intent_id=(result->>'intentId')::uuid AND x.company_id=c FOR SHARE;
 IF EXISTS(SELECT FROM jsonb_array_elements(o.row_sources) x WHERE x ? 'customerSourceMessageId') THEN
  SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots x WHERE x.id=o.snapshot_id AND x.company_id=c AND x.environment=o.environment AND x.readset_hash=o.readset_hash FOR SHARE;
  SELECT * INTO i FROM public.ediel_message_intents x WHERE x.id=o.intent_id AND x.company_id=c FOR SHARE;
  IF snap.id IS NULL OR i.id IS NULL THEN RAISE EXCEPTION 'ai_list_customer_original_source_required';END IF;
  PERFORM gridex_ai_processing.require_original_row_sources_v1(snap.readset_text::jsonb,snap.cutoff_at,i,o.raw_payload,o.row_sources::text);
 END IF;
 RETURN result;
END$$;

--
-- Name: require_ai_outbound_source_before_origin_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_outbound_source_before_origin_v1(c uuid, message_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;wire jsonb;decision jsonb;basis jsonb;profile jsonb;q jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages s WHERE s.id=message_id AND s.company_id=c FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'ai_list' OR m.message_family IS DISTINCT FROM 'AI_LIST'
  OR m.message_code IS DISTINCT FROM 'AI' OR m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL
  OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ai_list_sealed_outbound_source_required'; END IF;
 basis:=gridex_ai_processing.party_source_v1(c,m.intent_id);wire:=gridex_ai_processing.require_party_wire_v1(m.raw_payload,basis);profile:=wire->'profile';
 IF m.sender_ediel_id IS DISTINCT FROM basis->>'technicalSender' OR m.receiver_ediel_id IS DISTINCT FROM basis->>'technicalReceiver'
  OR m.environment IS DISTINCT FROM basis->>'environment' OR m.communication_route_id::text IS DISTINCT FROM basis->>'communicationRouteId' OR m.route_profile_id::text IS DISTINCT FROM basis->>'routeProfileId'
  OR m.message_version IS DISTINCT FROM profile->>'technicalVersion' THEN RAISE EXCEPTION 'ai_list_outbound_party_profile_scope_mismatch'; END IF;
 IF m.file_name IS NULL OR lower(m.file_name) NOT LIKE '%.csv' OR m.mime_type IS NULL
  OR m.mime_type!~* '^text/csv([ \t]*;[ \t]*charset[ \t]*=[ \t]*(utf-8|"utf-8"))?[ \t]*$' THEN RAISE EXCEPTION 'ai_list_csv_file_type_required'; END IF;
 PERFORM gridex_ai_purpose_sources.consumer_v1(c,actor,'send',m.environment);decision:=gridex_ai_purpose_sources.current_for_scope_v1(c,'AI','ediel_list_export',m.environment);IF decision->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ai_purpose_actual_outbound_environment_required';END IF;
 q:=gridex_registry_import.require_message_market_v1(c,m.id);
 IF q->>'status' IS DISTINCT FROM 'source_qualified' OR q->>'legalEdielId' IS DISTINCT FROM basis->>'legalNetwork' THEN RAISE EXCEPTION 'ai_list_actual_message_dispatch_source_required';END IF;
 PERFORM public.ediel_require_scoped_capability_for_message_v1(c,m.id);
 IF m.environment='production' AND NOT EXISTS(SELECT FROM gridex_ediel_readiness.evidence e WHERE e.company_id=c AND e.scope->>'family'='AI_LIST'
  AND e.scope->>'code'='AI' AND e.expires_at>statement_timestamp() AND e.dependencies->>'rulepackHash'=profile->>'sourceSha256'
  AND e.dependencies->>'technicalFormatVersion'=profile->>'technicalVersion') THEN RAISE EXCEPTION 'ai_list_scoped_profile_dependency_required'; END IF;
 RETURN jsonb_build_object('sourceHash',m.immutable_payload_hash,'profile',profile,'headerBasis',basis,'decisionId',decision#>>'{decision,id}','rowCount',wire->'rowCount');
END $_$;

--
-- Name: require_ai_outbound_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_outbound_source_v1(c uuid, message_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;o gridex_ai_processing.outbound_origins%rowtype;decision jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT * INTO m FROM public.ediel_messages WHERE id=message_id AND company_id=c FOR SHARE;
 PERFORM gridex_ai_purpose_sources.consumer_v1(c,actor,'send',m.environment);decision:=gridex_ai_purpose_sources.current_for_scope_v1(c,'AI','ediel_list_export',m.environment);SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=m.intent_id AND company_id=c FOR SHARE;
 IF decision->>'status' IS DISTINCT FROM 'authorized' OR o.processing_decision_id::text IS DISTINCT FROM decision#>>'{decision,id}' THEN RAISE EXCEPTION 'ai_purpose_frozen_original_current_decision_required';END IF;
 result:=gridex_ai_processing.require_ai_source_before_purpose_owner_v1(c,message_id,actor);RETURN result;
END$$;

--
-- Name: require_ai_source_before_purpose_owner_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_ai_source_before_purpose_owner_v1(c uuid, message_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source jsonb;origin jsonb;BEGIN
 origin:=gridex_ai_processing.require_ai_outbound_origin_v1(c,message_id);
 source:=gridex_ai_processing.require_ai_outbound_source_before_origin_v1(c,message_id,actor);
 RETURN source||jsonb_build_object('origin',origin);
END $$;

--
-- Name: require_export_decision_for_intent_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_export_decision_for_intent_v1(c uuid, actor uuid, intent uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;decision jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();i:=gridex_ai_processing.intent_request_v1(c,intent);PERFORM gridex_ai_purpose_sources.consumer_v1(c,actor,'origination',i.environment);
 decision:=gridex_ai_purpose_sources.current_for_scope_v1(c,'AI','ediel_list_export',i.environment);IF decision->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(decision->>'blocker','ai_bi_processing_decision_invalid') USING ERRCODE='42501';END IF;RETURN decision;
END$$;

--
-- Name: require_export_decision_for_phase_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_export_decision_for_phase_v1(c uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE decision jsonb;BEGIN
 decision:=gridex_ai_processing.current_purpose_decision_for_phase_v1(c,actor,'AI','ediel_list_export',phase);
 IF decision->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION '%',coalesce(decision->>'blocker','ai_bi_processing_decision_invalid') USING ERRCODE='42501'; END IF;
 IF decision#>>'{decision,companyId}' IS DISTINCT FROM c::text OR decision#>>'{decision,listType}' IS DISTINCT FROM 'AI' OR decision#>>'{decision,purpose}' IS DISTINCT FROM 'ediel_list_export' THEN RAISE EXCEPTION 'ai_list_export_decision_scope_mismatch'; END IF;
 RETURN decision;
END $$;

--
-- Name: require_export_decision_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_export_decision_v1(c uuid, actor uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ai_processing.require_export_decision_for_phase_v1(c,actor,'origination')$$;

--
-- Name: require_original_before_purpose_owner_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_before_purpose_owner_v1(c uuid, actor uuid, intent uuid, d jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;o gridex_ai_processing.outbound_origins%rowtype;decision jsonb;header jsonb;profile jsonb:=gridex_ai_processing.native_profile_v1();k text;
BEGIN
 decision:=gridex_ai_processing.require_export_decision_for_intent_v1(c,actor,intent);
 i:=gridex_ai_processing.intent_request_v1(c,intent);
 SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=i.id AND company_id=c FOR SHARE;
 IF NOT FOUND OR o.operation_id IS DISTINCT FROM i.operation_id OR o.intent_basis IS DISTINCT FROM gridex_ai_processing.intent_basis_v1(i) OR jsonb_typeof(d) IS DISTINCT FROM 'object' OR d->>'actorUserId' IS DISTINCT FROM actor::text
  OR d->>'companyId' IS DISTINCT FROM c::text OR d->>'intentId' IS DISTINCT FROM i.id::text OR d->>'sourceOperationId' IS DISTINCT FROM i.operation_id::text
  OR d->>'direction' IS DISTINCT FROM 'outbound' OR d->>'messageStandard' IS DISTINCT FROM 'ai_list' OR d->>'messageFamily' IS DISTINCT FROM 'AI_LIST'
  OR d->>'messageCode' IS DISTINCT FROM 'AI' OR d->>'messageVersion' IS DISTINCT FROM profile->>'technicalVersion' OR d->>'environment' IS DISTINCT FROM o.environment
  OR d->>'processType' IS DISTINCT FROM 'ai_list_export' OR d->>'rawPayload' IS DISTINCT FROM o.raw_payload
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex') OR d->>'fileName' IS DISTINCT FROM o.file_name OR d->>'mimeType' IS DISTINCT FROM o.mime_type
  OR d->>'senderEdielId' IS DISTINCT FROM i.sender_ediel_id OR d->>'receiverEdielId' IS DISTINCT FROM i.receiver_ediel_id
  OR d->>'customerId' IS DISTINCT FROM i.customer_id::text OR d->>'siteId' IS DISTINCT FROM i.customer_site_id::text
  OR nullif(d->>'meteringPointId','') IS DISTINCT FROM nullif(i.metering_point_id,'')
  OR d->>'communicationRouteId' IS DISTINCT FROM i.communication_route_id::text OR d->>'routeProfileId' IS DISTINCT FROM i.route_profile_id::text THEN RAISE EXCEPTION 'ai_list_private_original_required'; END IF;
 FOREACH k IN ARRAY ARRAY['applicationReference','interchangeReference','externalReference','correlationReference','transactionReference',
  'originalMessageId','originalTransactionId','originalMessageCode','relatedMessageId','switchRequestId','gridOwnerDataRequestId','outboundRequestId','partnerExportId',
  'canonicalRulePackId','ruleProfileKey','ruleProfileVersionId','ruleProfileVersion','rulePackChecksum'] LOOP
  IF nullif(d->>k,'') IS NOT NULL THEN RAISE EXCEPTION 'ai_list_edifact_or_foreign_link_forbidden'; END IF;
 END LOOP;
 IF coalesce(d->'rulePackSnapshot','null'::jsonb) NOT IN ('null'::jsonb,'{}'::jsonb) THEN RAISE EXCEPTION 'ai_list_edifact_or_foreign_link_forbidden'; END IF;
 PERFORM gridex_ai_processing.outbound_wire_v1(o.raw_payload);
 header:=gridex_ai_processing.party_source_v1(c,i.id);
 PERFORM gridex_ai_processing.require_party_wire_v1(o.raw_payload,header);
 IF o.header_basis->>'legalSupplier' IS DISTINCT FROM header->>'legalSupplier' OR o.header_basis->>'legalNetwork' IS DISTINCT FROM header->>'legalNetwork' OR (o.header_basis ? 'technicalSender' AND (o.header_basis->>'technicalSender' IS DISTINCT FROM header->>'technicalSender' OR o.header_basis->>'technicalReceiver' IS DISTINCT FROM header->>'technicalReceiver')) THEN RAISE EXCEPTION 'ai_list_private_original_party_source_changed';END IF;
 RETURN jsonb_build_object('owner','ai-list-private-original-v1','companyId',c,'environment',o.environment,'intentId',i.id,'operationId',i.operation_id,
  'sourceHash',o.payload_hash,'snapshotId',o.snapshot_id,'readsetHash',o.readset_hash,'sourceSha256',profile->>'sourceSha256','technicalVersion',profile->>'technicalVersion',
  'processingDecisionId',decision#>>'{decision,id}','headerBasis',header);
END $$;

--
-- Name: require_original_draft_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_draft_v1(c uuid, actor uuid, intent uuid, d jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_ai_processing.outbound_origins%rowtype;decision jsonb;BEGIN
 decision:=gridex_ai_processing.require_export_decision_for_intent_v1(c,actor,intent);SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=intent AND company_id=c FOR SHARE;
 IF o.processing_decision_id::text IS DISTINCT FROM decision#>>'{decision,id}' THEN RAISE EXCEPTION 'ai_purpose_frozen_original_current_decision_required';END IF;
 RETURN gridex_ai_processing.require_original_before_purpose_owner_v1(c,actor,intent,d);
END$$;

--
-- Name: require_original_row_sources_before_applied_structure_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_row_sources_before_applied_structure_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE refs jsonb;ref jsonb;state jsonb;base jsonb;address jsonb;cols text[];records text[];h text[];normalized text;
 matched integer;expected text[];baseline_ud jsonb;address_it jsonb;brp jsonb;grid jsonb;period public.customer_supply_periods%rowtype;
 cover jsonb;epoch jsonb;customer_epoch jsonb;intervals jsonb:='[]';span jsonb;cursor_date text;required_end text;period_count integer:=0;covered_periods uuid[]:=ARRAY[]::uuid[];start_date text;end_date text;state_date text;period_from text;period_to text;seen text[]:=ARRAY[]::text[];row integer;n integer;
BEGIN
 i:=gridex_ai_processing.legal_history_intent_v1(i,raw);
 IF claims IS NULL OR octet_length(claims)>262144 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;refs:=claims::jsonb;
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;
 records:=string_to_array(normalized,E'\n');h:=string_to_array(records[1],';');
 IF jsonb_typeof(refs)<>'array' OR jsonb_array_length(refs)<>cardinality(records)-1 OR jsonb_array_length(refs)>1000 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
  IF jsonb_typeof(ref)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(ref))<>4 OR NOT(ref ?& ARRAY['sourceMessageId','baselineSourceMessageId','addressSourceMessageId','supplyPeriodId']) THEN RAISE EXCEPTION 'ai_list_original_row_source_scope_invalid';END IF;
  SELECT * INTO period FROM public.customer_supply_periods p WHERE p.id=(ref->>'supplyPeriodId')::uuid AND p.company_id=i.company_id AND p.customer_id=i.customer_id ;
  IF NOT FOUND OR nullif(i.metering_point_id,'') IS NOT NULL AND period.metering_point_id::text IS DISTINCT FROM i.metering_point_id THEN RAISE EXCEPTION 'ai_list_original_row_supply_scope_invalid';END IF;
  -- Match by actual original object, never by mutable portal point/name fields.
  matched:=0;
  FOR row IN 2..cardinality(records) LOOP
   IF row::text=ANY(seen) THEN CONTINUE;END IF;cols:=string_to_array(records[row],';');
   state:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'sourceMessageId',i,cols[2],cols[3]);
   IF state IS NULL THEN CONTINUE;END IF;
   base:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
   address:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'addressSourceMessageId',i,cols[2],cols[3]);
   IF base IS NULL OR address IS NULL OR base#>>'{business,wire,businessCase}'<>'supply_baseline'
    OR state#>>'{business,coverageWindow,baselineSourceMessageId}' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR address#>>'{business,coverageWindow,baselineSourceMessageId}' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR state#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text OR base#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text
    OR address#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text OR address#>>'{business,wire,messageCode}'='Z10'
    OR address#>>'{business,wire,effectiveFrom,marketMinute}'>state#>>'{business,wire,effectiveFrom,marketMinute}' THEN CONTINUE;END IF;
   SELECT t INTO baseline_ud FROM jsonb_array_elements(base->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO address_it FROM jsonb_array_elements(address->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IT' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO brp FROM jsonb_array_elements(state->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO grid FROM jsonb_array_elements(state->'ownTokens') t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='Z05' ORDER BY (t->>'index')::integer LIMIT 1;
   IF baseline_ud#>>'{elements,2,1}' NOT IN ('SE1','SE2') OR baseline_ud#>>'{elements,2,2}' IS DISTINCT FROM '260'
    OR nullif(baseline_ud#>>'{elements,2,0}','') IS NULL OR nullif(brp#>>'{elements,2,0}','') IS NULL OR nullif(grid#>>'{elements,1,1}','') IS NULL THEN CONTINUE;END IF;
   state_date:=state#>>'{business,wire,effectiveFrom,marketMinute}';IF right(state_date,4)<>'0000' THEN CONTINUE;END IF;state_date:=left(state_date,8);
   period_from:=to_char(coalesce(period.actual_start_date,period.start_date),'YYYYMMDD');period_to:=to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD');
   IF base#>>'{business,wire,effectiveFrom,marketMinute}' IS DISTINCT FROM period_from||'0000' THEN CONTINUE;END IF;
   cover:=gridex_received_sources.supply_period_source_basis_v1(i.company_id,period.id,gridex_received_sources.permission_time_v1(greatest(h[8],period_from)||'0000'),gridex_received_sources.permission_time_v1(least(h[9],coalesce(period_to,h[9]))||'0000'));
   IF cover->>'qualified' IS DISTINCT FROM 'true' OR cover->>'customerId' IS DISTINCT FROM i.customer_id::text
    OR cover->>'siteId' IS DISTINCT FROM i.customer_site_id::text OR cover->>'initialSourceMessageId' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR (cover->>'marketStartAt')::timestamptz IS DISTINCT FROM gridex_received_sources.permission_time_v1(period_from||'0000')
    OR (cover->>'marketEndAt')::timestamptz IS DISTINCT FROM gridex_received_sources.permission_time_v1(period_to||'0000') THEN CONTINUE;END IF;
   -- The shared lifecycle owner locks original/source before period; re-read
   -- that exact period only after its source-owned lock order is established.
   PERFORM p.id FROM public.customer_supply_periods p WHERE p.id=period.id AND p.company_id=i.company_id AND to_jsonb(p)=to_jsonb(period) FOR SHARE;
   IF NOT FOUND THEN CONTINUE;END IF;
   start_date:=greatest(h[8],period_from,state_date);end_date:=least(h[9],coalesce(period_to,h[9]));
   epoch:=gridex_ai_processing.row_epoch_matches_v1(body,cutoff,i,cols[2],cols[3],period.id::text,ref->>'sourceMessageId',ref->>'addressSourceMessageId',period_from,h[8],least(h[9],coalesce(period_to,h[9])));
   IF epoch->>'nextMinute' IS NOT NULL THEN end_date:=least(end_date,left(epoch->>'nextMinute',8));END IF;
   customer_epoch:=gridex_ai_processing.customer_row_epoch_composed_v1(body,cutoff,i,baseline_ud,cols[2],cols[3],period.id::text,period_from,coalesce(nullif(cols[20],''),h[8]),least(h[9],coalesce(period_to,h[9])));
   start_date:=greatest(start_date,customer_epoch->>'startDay');
   IF customer_epoch->>'nextDay' IS NOT NULL THEN end_date:=least(end_date,customer_epoch->>'nextDay');END IF;
   IF start_date>=end_date THEN CONTINUE;END IF;
   expected:=ARRAY[grid#>>'{elements,1,1}',cols[2],cols[3],'','','','',gridex_ai_processing.party_text_v1(address_it,5,3),coalesce(address_it#>>'{elements,8,0}',''),coalesce(address_it#>>'{elements,6,0}',''),brp#>>'{elements,2,0}','','','','','','',customer_epoch->>'customerId',customer_epoch->>'customerName',CASE WHEN start_date=h[8] THEN '' ELSE start_date END,CASE WHEN end_date=h[9] THEN '' ELSE end_date END,''];
   IF cols IS DISTINCT FROM expected THEN CONTINUE;END IF;
   seen:=array_append(seen,row::text);covered_periods:=array_append(covered_periods,period.id);matched:=matched+1;
   intervals:=intervals||jsonb_build_array(jsonb_build_object('periodId',period.id,'start',start_date,'end',end_date));
   -- Customer epochs can repeat the same structural source claim. Consume
   -- exactly one already-qualified physical row per occurrence; every row is
   -- still required by equal cardinality/seen and exact contiguous coverage.
   EXIT;
  END LOOP;
  IF matched<>1 THEN RAISE EXCEPTION 'ai_list_original_row_source_mismatch';END IF;
 END LOOP;
 -- An empty or partial CSV cannot omit an owned overlapping supply period.
 -- No current-row status is treated as historical ownership.
 FOR period IN SELECT p.* FROM public.customer_supply_periods p WHERE p.company_id=i.company_id AND p.customer_id=i.customer_id
  AND (nullif(i.metering_point_id,'') IS NULL OR p.metering_point_id::text=i.metering_point_id)
  AND to_char(coalesce(p.actual_start_date,p.start_date),'YYYYMMDD')<h[9]
  AND (coalesce(p.actual_end_date,p.end_date) IS NULL OR to_char(coalesce(p.actual_end_date,p.end_date),'YYYYMMDD')>h[8]) ORDER BY p.id LOOP
  period_count:=period_count+1;IF period_count>1000 THEN RAISE EXCEPTION 'ai_list_supply_history_read_incomplete';END IF;
  period_from:=to_char(coalesce(period.actual_start_date,period.start_date),'YYYYMMDD');period_to:=to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD');
  cover:=gridex_received_sources.supply_period_source_basis_v1(i.company_id,period.id,gridex_received_sources.permission_time_v1(greatest(h[8],period_from)||'0000'),gridex_received_sources.permission_time_v1(least(h[9],coalesce(period_to,h[9]))||'0000'));
  IF cover->>'qualified' IS DISTINCT FROM 'true' OR cover->>'customerId' IS DISTINCT FROM i.customer_id::text THEN RAISE EXCEPTION 'ai_list_original_dated_supply_owner_required';END IF;
  IF cover->>'siteId'=i.customer_site_id::text AND NOT(period.id=ANY(covered_periods)) THEN RAISE EXCEPTION 'ai_list_original_supply_period_omitted';END IF;
  IF cover->>'siteId'=i.customer_site_id::text THEN
   cursor_date:=greatest(h[8],period_from);required_end:=least(h[9],coalesce(period_to,h[9]));
   FOR span IN SELECT value FROM jsonb_array_elements(intervals) WHERE value->>'periodId'=period.id::text ORDER BY value->>'start' LOOP
    IF span->>'start' IS DISTINCT FROM cursor_date OR span->>'end'>required_end OR span->>'end'<=span->>'start' THEN RAISE EXCEPTION 'ai_list_original_supply_epoch_omitted';END IF;
    cursor_date:=span->>'end';
   END LOOP;
   IF cursor_date IS DISTINCT FROM required_end THEN RAISE EXCEPTION 'ai_list_original_supply_epoch_omitted';END IF;
  END IF;
 END LOOP;
 RETURN refs;
END $$;

--
-- Name: require_original_row_sources_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_row_sources_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE refs jsonb;ref jsonb;clean jsonb:='[]';records text[];h text[];cols text[];normalized text;row int;period public.customer_supply_periods%rowtype;baseline jsonb;ud jsonb;epoch jsonb;BEGIN
 i:=gridex_ai_processing.legal_history_intent_v1(i,raw);
 IF claims IS NULL OR octet_length(claims)>262144 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;refs:=claims::jsonb;
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;
 records:=string_to_array(normalized,E'\n');h:=string_to_array(records[1],';');
 IF jsonb_typeof(refs) IS DISTINCT FROM 'array' OR jsonb_array_length(refs)<>cardinality(records)-1 OR jsonb_array_length(refs)>1000 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;
 FOR row IN 2..cardinality(records) LOOP
  ref:=refs->(row-2);cols:=string_to_array(records[row],';');
  IF jsonb_typeof(ref) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(ref-'customerSourceMessageId'))<>4 OR NOT((ref-'customerSourceMessageId') ?& ARRAY['sourceMessageId','baselineSourceMessageId','addressSourceMessageId','supplyPeriodId']) OR cardinality(cols)<>22 OR ref ? 'customerSourceMessageId' AND nullif(ref->>'customerSourceMessageId','') IS NULL THEN RAISE EXCEPTION 'ai_list_customer_row_scope_invalid';END IF;
  SELECT * INTO period FROM public.customer_supply_periods p WHERE p.id=(ref->>'supplyPeriodId')::uuid AND p.company_id=i.company_id AND p.customer_id=i.customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_original_row_supply_scope_invalid';END IF;
  baseline:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
  IF baseline IS NULL OR baseline#>>'{business,wire,businessCase}' IS DISTINCT FROM 'supply_baseline' OR baseline#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text THEN RAISE EXCEPTION 'ai_list_original_row_source_mismatch';END IF;
  SELECT t INTO ud FROM jsonb_array_elements(baseline->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' ORDER BY (t->>'index')::integer LIMIT 1;
  epoch:=gridex_ai_processing.customer_row_epoch_composed_v1(body,cutoff,i,ud,cols[2],cols[3],period.id::text,to_char(coalesce(period.actual_start_date,period.start_date),'YYYYMMDD'),coalesce(nullif(cols[20],''),h[8]),least(h[9],coalesce(to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD'),h[9])));
  IF ref->>'customerSourceMessageId' IS DISTINCT FROM epoch->>'customerSourceMessageId' THEN RAISE EXCEPTION 'ai_list_customer_epoch_source_mismatch';END IF;
  clean:=clean||jsonb_build_array(ref-'customerSourceMessageId');
 END LOOP;
 PERFORM gridex_ai_processing.require_original_rows_before_composed_customer_v1(body,cutoff,i,raw,clean::text);
 RETURN refs;
END$$;

--
-- Name: require_original_rows_before_composed_customer_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_rows_before_composed_customer_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE refs jsonb;ref jsonb;basis jsonb;state jsonb;base jsonb;address jsonb;source_id text;records text[];cols text[];normalized text;row integer;matched boolean;
BEGIN
 PERFORM gridex_ai_processing.customer_history_for_rows_v1(body,cutoff,i,raw,claims);
 -- Full physical CSV/source/supply/epoch equality remains the existing owner.
 refs:=gridex_ai_processing.require_original_row_sources_before_applied_structure_v1(body,cutoff,i,raw,claims);
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;
 IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;records:=string_to_array(normalized,E'\n');
 FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
  matched:=false;
  FOR row IN 2..cardinality(records) LOOP
   cols:=string_to_array(records[row],';');
   state:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'sourceMessageId',i,cols[2],cols[3]);
   base:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
   address:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'addressSourceMessageId',i,cols[2],cols[3]);
   IF state IS NULL OR base IS NULL OR address IS NULL
    OR state#>>'{business,supplyPeriodId}' IS DISTINCT FROM ref->>'supplyPeriodId'
    OR base#>>'{business,supplyPeriodId}' IS DISTINCT FROM ref->>'supplyPeriodId'
    OR address#>>'{business,supplyPeriodId}' IS DISTINCT FROM ref->>'supplyPeriodId' THEN CONTINUE;END IF;
   matched:=true;
   FOR source_id,basis IN SELECT DISTINCT x.id,x.basis FROM (VALUES(ref->>'sourceMessageId',state),(ref->>'baselineSourceMessageId',base),(ref->>'addressSourceMessageId',address)) x(id,basis) LOOP
    -- Z04 is qualified by the sole current normal-supply owner in the full
    -- row binder. Other structural states require their own immutable effect.
    IF basis#>>'{business,wire,messageCode}'='Z04' THEN CONTINUE;END IF;
    IF nullif(basis#>>'{business,meteringPointId}','') IS NULL OR gridex_received_sources.structural_effect_matches_v1(
     i.company_id,i.environment,source_id::uuid,(basis->>'assessmentId')::uuid,i.customer_id,i.customer_site_id,
     (basis#>>'{business,meteringPointId}')::uuid,(ref->>'supplyPeriodId')::uuid,cols[2],cols[3],cutoff) IS NOT TRUE
     THEN RAISE EXCEPTION 'ai_list_applied_structural_source_unconfirmed';END IF;
   END LOOP;
  END LOOP;
  IF NOT matched THEN RAISE EXCEPTION 'ai_list_applied_history_own_scope_unconfirmed';END IF;
 END LOOP;
 RETURN refs;
END $$;

--
-- Name: require_original_rows_before_customer_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_original_rows_before_customer_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, raw text, claims text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE refs jsonb;ref jsonb;state jsonb;base jsonb;address jsonb;cols text[];records text[];h text[];normalized text;
 matched integer;expected text[];baseline_ud jsonb;address_it jsonb;brp jsonb;grid jsonb;period public.customer_supply_periods%rowtype;
 cover jsonb;epoch jsonb;intervals jsonb:='[]';span jsonb;cursor_date text;required_end text;period_count integer:=0;covered_periods uuid[]:=ARRAY[]::uuid[];start_date text;end_date text;state_date text;period_from text;period_to text;seen text[]:=ARRAY[]::text[];row integer;n integer;
BEGIN
 IF claims IS NULL OR octet_length(claims)>262144 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;refs:=claims::jsonb;
 normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;IF right(normalized,1)=E'\n' THEN normalized:=left(normalized,length(normalized)-1);END IF;
 records:=string_to_array(normalized,E'\n');h:=string_to_array(records[1],';');
 IF jsonb_typeof(refs)<>'array' OR jsonb_array_length(refs)<>cardinality(records)-1 OR jsonb_array_length(refs)>1000 THEN RAISE EXCEPTION 'ai_list_original_row_sources_required';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
  IF jsonb_typeof(ref)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(ref))<>4 OR NOT(ref ?& ARRAY['sourceMessageId','baselineSourceMessageId','addressSourceMessageId','supplyPeriodId']) THEN RAISE EXCEPTION 'ai_list_original_row_source_scope_invalid';END IF;
  SELECT * INTO period FROM public.customer_supply_periods p WHERE p.id=(ref->>'supplyPeriodId')::uuid AND p.company_id=i.company_id AND p.customer_id=i.customer_id ;
  IF NOT FOUND OR nullif(i.metering_point_id,'') IS NOT NULL AND period.metering_point_id::text IS DISTINCT FROM i.metering_point_id THEN RAISE EXCEPTION 'ai_list_original_row_supply_scope_invalid';END IF;
  -- Match by actual original object, never by mutable portal point/name fields.
  matched:=0;
  FOR row IN 2..cardinality(records) LOOP
   IF row::text=ANY(seen) THEN CONTINUE;END IF;cols:=string_to_array(records[row],';');
   state:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'sourceMessageId',i,cols[2],cols[3]);
   IF state IS NULL THEN CONTINUE;END IF;
   base:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'baselineSourceMessageId',i,cols[2],cols[3]);
   address:=gridex_ai_processing.source_row_basis_v1(body,cutoff,ref->>'addressSourceMessageId',i,cols[2],cols[3]);
   IF base IS NULL OR address IS NULL OR base#>>'{business,wire,businessCase}'<>'supply_baseline'
    OR state#>>'{business,coverageWindow,baselineSourceMessageId}' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR address#>>'{business,coverageWindow,baselineSourceMessageId}' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR state#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text OR base#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text
    OR address#>>'{business,supplyPeriodId}' IS DISTINCT FROM period.id::text OR address#>>'{business,wire,messageCode}'='Z10'
    OR address#>>'{business,wire,effectiveFrom,marketMinute}'>state#>>'{business,wire,effectiveFrom,marketMinute}' THEN CONTINUE;END IF;
   SELECT t INTO baseline_ud FROM jsonb_array_elements(base->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO address_it FROM jsonb_array_elements(address->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IT' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO brp FROM jsonb_array_elements(state->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' ORDER BY (t->>'index')::integer LIMIT 1;
   SELECT t INTO grid FROM jsonb_array_elements(state->'ownTokens') t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='Z05' ORDER BY (t->>'index')::integer LIMIT 1;
   IF baseline_ud#>>'{elements,2,1}' NOT IN ('SE1','SE2') OR baseline_ud#>>'{elements,2,2}' IS DISTINCT FROM '260'
    OR nullif(baseline_ud#>>'{elements,2,0}','') IS NULL OR nullif(brp#>>'{elements,2,0}','') IS NULL OR nullif(grid#>>'{elements,1,1}','') IS NULL THEN CONTINUE;END IF;
   state_date:=state#>>'{business,wire,effectiveFrom,marketMinute}';IF right(state_date,4)<>'0000' THEN CONTINUE;END IF;state_date:=left(state_date,8);
   period_from:=to_char(coalesce(period.actual_start_date,period.start_date),'YYYYMMDD');period_to:=to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD');
   IF base#>>'{business,wire,effectiveFrom,marketMinute}' IS DISTINCT FROM period_from||'0000' THEN CONTINUE;END IF;
   cover:=gridex_received_sources.supply_period_source_basis_v1(i.company_id,period.id,gridex_received_sources.permission_time_v1(greatest(h[8],period_from)||'0000'),gridex_received_sources.permission_time_v1(least(h[9],coalesce(period_to,h[9]))||'0000'));
   IF cover->>'qualified' IS DISTINCT FROM 'true' OR cover->>'customerId' IS DISTINCT FROM i.customer_id::text
    OR cover->>'siteId' IS DISTINCT FROM i.customer_site_id::text OR cover->>'initialSourceMessageId' IS DISTINCT FROM ref->>'baselineSourceMessageId'
    OR (cover->>'marketStartAt')::timestamptz IS DISTINCT FROM gridex_received_sources.permission_time_v1(period_from||'0000')
    OR (cover->>'marketEndAt')::timestamptz IS DISTINCT FROM gridex_received_sources.permission_time_v1(period_to||'0000') THEN CONTINUE;END IF;
   -- The shared lifecycle owner locks original/source before period; re-read
   -- that exact period only after its source-owned lock order is established.
   PERFORM p.id FROM public.customer_supply_periods p WHERE p.id=period.id AND p.company_id=i.company_id AND to_jsonb(p)=to_jsonb(period) FOR SHARE;
   IF NOT FOUND THEN CONTINUE;END IF;
   start_date:=greatest(h[8],period_from,state_date);end_date:=least(h[9],coalesce(period_to,h[9]));
   epoch:=gridex_ai_processing.row_epoch_matches_v1(body,cutoff,i,cols[2],cols[3],period.id::text,ref->>'sourceMessageId',ref->>'addressSourceMessageId',period_from,h[8],least(h[9],coalesce(period_to,h[9])));
   IF epoch->>'nextMinute' IS NOT NULL THEN end_date:=least(end_date,left(epoch->>'nextMinute',8));END IF;
   IF start_date>=end_date THEN CONTINUE;END IF;
   expected:=ARRAY[grid#>>'{elements,1,1}',cols[2],cols[3],'','','','',gridex_ai_processing.party_text_v1(address_it,5,3),coalesce(address_it#>>'{elements,8,0}',''),coalesce(address_it#>>'{elements,6,0}',''),brp#>>'{elements,2,0}','','','','','','',baseline_ud#>>'{elements,2,0}',gridex_ai_processing.party_text_v1(baseline_ud,4,2),CASE WHEN start_date=h[8] THEN '' ELSE start_date END,CASE WHEN end_date=h[9] THEN '' ELSE end_date END,''];
   IF cols IS DISTINCT FROM expected THEN CONTINUE;END IF;
   seen:=array_append(seen,row::text);covered_periods:=array_append(covered_periods,period.id);matched:=matched+1;
   intervals:=intervals||jsonb_build_array(jsonb_build_object('periodId',period.id,'start',start_date,'end',end_date));
  END LOOP;
  IF matched<>1 THEN RAISE EXCEPTION 'ai_list_original_row_source_mismatch';END IF;
 END LOOP;
 -- An empty or partial CSV cannot omit an owned overlapping supply period.
 -- No current-row status is treated as historical ownership.
 FOR period IN SELECT p.* FROM public.customer_supply_periods p WHERE p.company_id=i.company_id AND p.customer_id=i.customer_id
  AND (nullif(i.metering_point_id,'') IS NULL OR p.metering_point_id::text=i.metering_point_id)
  AND to_char(coalesce(p.actual_start_date,p.start_date),'YYYYMMDD')<h[9]
  AND (coalesce(p.actual_end_date,p.end_date) IS NULL OR to_char(coalesce(p.actual_end_date,p.end_date),'YYYYMMDD')>h[8]) ORDER BY p.id LOOP
  period_count:=period_count+1;IF period_count>1000 THEN RAISE EXCEPTION 'ai_list_supply_history_read_incomplete';END IF;
  period_from:=to_char(coalesce(period.actual_start_date,period.start_date),'YYYYMMDD');period_to:=to_char(coalesce(period.actual_end_date,period.end_date),'YYYYMMDD');
  cover:=gridex_received_sources.supply_period_source_basis_v1(i.company_id,period.id,gridex_received_sources.permission_time_v1(greatest(h[8],period_from)||'0000'),gridex_received_sources.permission_time_v1(least(h[9],coalesce(period_to,h[9]))||'0000'));
  IF cover->>'qualified' IS DISTINCT FROM 'true' OR cover->>'customerId' IS DISTINCT FROM i.customer_id::text THEN RAISE EXCEPTION 'ai_list_original_dated_supply_owner_required';END IF;
  IF cover->>'siteId'=i.customer_site_id::text AND NOT(period.id=ANY(covered_periods)) THEN RAISE EXCEPTION 'ai_list_original_supply_period_omitted';END IF;
  IF cover->>'siteId'=i.customer_site_id::text THEN
   cursor_date:=greatest(h[8],period_from);required_end:=least(h[9],coalesce(period_to,h[9]));
   FOR span IN SELECT value FROM jsonb_array_elements(intervals) WHERE value->>'periodId'=period.id::text ORDER BY value->>'start' LOOP
    IF span->>'start' IS DISTINCT FROM cursor_date OR span->>'end'>required_end OR span->>'end'<=span->>'start' THEN RAISE EXCEPTION 'ai_list_original_supply_epoch_omitted';END IF;
    cursor_date:=span->>'end';
   END LOOP;
   IF cursor_date IS DISTINCT FROM required_end THEN RAISE EXCEPTION 'ai_list_original_supply_epoch_omitted';END IF;
  END IF;
 END LOOP;
 RETURN refs;
END $$;

--
-- Name: require_party_wire_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.require_party_wire_v1(raw text, parties jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE wire jsonb;h text[];normalized text;BEGIN
 wire:=gridex_ai_processing.outbound_wire_v1(raw);normalized:=replace(raw,E'\r\n',E'\n');IF left(normalized,1)=chr(65279) THEN normalized:=substring(normalized FROM 2);END IF;h:=string_to_array(split_part(normalized,E'\n',1),';');
 IF wire->>'supplierEdielId' IS DISTINCT FROM parties->>'legalSupplier' OR wire->>'networkEdielId' IS DISTINCT FROM parties->>'legalNetwork'
  OR h[5] IS DISTINCT FROM parties->>'legalSupplierName' OR h[3] IS DISTINCT FROM parties->>'legalNetworkName' THEN RAISE EXCEPTION 'ai_list_original_legal_party_source_mismatch';END IF;RETURN wire;
END$$;

--
-- Name: row_epoch_before_customer_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.row_epoch_before_customer_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, object_id text, agency text, period_id text, state_id text, address_id text, period_start text, search_start text, search_end text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source jsonb;candidate jsonb;other jsonb;basis jsonb;active jsonb:='[]';all_owned jsonb:='[]';replaced text[]:=ARRAY[]::text[];id text;at text;state_at text;next_at text;address_at text;latest_address text;n integer;cursor_id text;ancestors text[];tokens jsonb;code text;first_lin integer;own_start integer;own_end integer;physical_at text;latest jsonb;own_entry jsonb;
BEGIN
 FOR source IN SELECT value FROM jsonb_array_elements(body->'sources') LOOP
  id:=source->>'sourceMessageId';basis:=gridex_ai_processing.source_row_basis_v1(body,cutoff,id,i,object_id,agency);
  IF basis IS NULL THEN
   -- Missing own approval cannot disappear from an otherwise complete source
   -- universe. Independently identify only its physical scope/time; no new
   -- positive business fact or event time is manufactured here.
   tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');
   IF tokens IS NULL THEN RAISE EXCEPTION 'ai_list_original_source_universe_unqualified';END IF;
   SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' ORDER BY (t->>'index')::integer LIMIT 1;
   IF code NOT IN ('Z04','Z06','Z10') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO first_lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_lin AND t#>>'{elements,1,0}'='FR' AND t#>>'{elements,2,0}'=i.receiver_ediel_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK')
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_lin AND t#>>'{elements,1,0}'='DO' AND t#>>'{elements,2,0}'=i.sender_ediel_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO own_start FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=object_id AND t#>>'{elements,3,3}'=agency;
   IF own_start IS NULL THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO own_end FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (t->>'index')::integer>own_start;
   SELECT t#>>'{elements,1,1}' INTO physical_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND (t->>'index')::integer>own_start AND (own_end IS NULL OR (t->>'index')::integer<own_end)
    AND t#>>'{elements,1,0}'=CASE WHEN code='Z04' THEN '92' ELSE '157' END ORDER BY (t->>'index')::integer LIMIT 1;
   IF physical_at IS NOT NULL AND (physical_at<period_start||'0000' OR physical_at>=search_end||'0000') THEN CONTINUE;END IF;
   SELECT x INTO latest FROM jsonb_array_elements(source->'assessments') x WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(source->'assessments') child WHERE child->>'previousAssessmentId'=x->>'id');
   SELECT x INTO own_entry FROM jsonb_array_elements((latest->>'factsText')::jsonb->'objects') x WHERE x#>>'{object,objectId}'=object_id AND x#>>'{object,identityAgency}'=agency;
   IF own_entry->>'disposition'='rejected' THEN CONTINUE;END IF;
   RAISE EXCEPTION 'ai_list_original_dated_source_owner_missing';
  END IF;
  IF basis#>>'{business,supplyPeriodId}' IS DISTINCT FROM period_id THEN CONTINUE;END IF;
  IF basis#>>'{business,wire,businessCase}'='customer_only' THEN RAISE EXCEPTION 'ai_list_dated_customer_change_owner_required';END IF;
  all_owned:=all_owned||jsonb_build_array(jsonb_build_object('id',id,'basis',basis));
 END LOOP;
 -- Only already-qualified exact replacement edges from the same original
 -- object/period may remove a prior event. A claim cannot create an edge.
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  basis:=candidate->'basis';
  IF basis#>>'{business,wire,functionCode}'='5' THEN
   id:=basis#>>'{business,replaces,sourceMessageId}';
   SELECT count(*) INTO n FROM jsonb_array_elements(all_owned) old WHERE old->>'id'=id
    AND old#>>'{basis,business,sourcePayloadHash}'=basis#>>'{business,replaces,payloadHash}'
    AND old#>>'{basis,assessmentId}'=basis#>>'{business,replaces,assessmentId}';
   IF n<>1 OR id=ANY(replaced) OR id=candidate->>'id' THEN RAISE EXCEPTION 'ai_list_original_correction_source_unqualified';END IF;
   replaced:=array_append(replaced,id);
  ELSIF basis#>'{business,replaces}' IS NOT NULL AND basis#>'{business,replaces}'<>'null'::jsonb THEN RAISE EXCEPTION 'ai_list_original_correction_source_unqualified';END IF;
 END LOOP;
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  cursor_id:=candidate->>'id';ancestors:=ARRAY[]::text[];
  WHILE cursor_id IS NOT NULL LOOP
   IF cursor_id=ANY(ancestors) OR cardinality(ancestors)>1000 THEN RAISE EXCEPTION 'ai_list_original_correction_cycle';END IF;
   ancestors:=array_append(ancestors,cursor_id);
   SELECT x#>>'{basis,business,replaces,sourceMessageId}' INTO cursor_id FROM jsonb_array_elements(all_owned) x WHERE x->>'id'=cursor_id;
  END LOOP;
 END LOOP;
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  IF NOT(candidate->>'id'=ANY(replaced)) THEN active:=active||jsonb_build_array(candidate);END IF;
 END LOOP;
 SELECT count(*),max(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO n,state_at FROM jsonb_array_elements(active) x WHERE x->>'id'=state_id;
 IF n<>1 OR state_at IS NULL OR state_at<period_start||'0000' OR state_at>=search_end||'0000' THEN RAISE EXCEPTION 'ai_list_original_row_epoch_mismatch';END IF;
 -- No omitted own source may split or precede this emitted epoch. This binds
 -- the row's end to the full immutable source universe, not the next claim.
 SELECT min(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO next_at FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>state_at AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<search_end||'0000';
 IF EXISTS(SELECT FROM jsonb_array_elements(active) x WHERE x->>'id'<>state_id
   AND (x#>>'{basis,business,wire,effectiveFrom,marketMinute}'=state_at
    OR state_at<search_start||'0000' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>state_at AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<=search_start||'0000')) THEN RAISE EXCEPTION 'ai_list_original_row_epoch_mismatch';END IF;
 SELECT max(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO address_at FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,messageCode}'<>'Z10' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<=state_at
  AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>=period_start||'0000';
 SELECT count(*),max(x->>'id') INTO n,latest_address FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,messageCode}'<>'Z10' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'=address_at;
 IF n<>1 OR latest_address IS DISTINCT FROM address_id OR right(state_at,4)<>'0000' OR next_at IS NOT NULL AND right(next_at,4)<>'0000' THEN RAISE EXCEPTION 'ai_list_original_row_address_epoch_mismatch';END IF;
 RETURN jsonb_build_object('stateMinute',state_at,'nextMinute',next_at);
END $$;

--
-- Name: row_epoch_matches_v1(jsonb, timestamp with time zone, public.ediel_message_intents, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.row_epoch_matches_v1(body jsonb, cutoff timestamp with time zone, i public.ediel_message_intents, object_id text, agency text, period_id text, state_id text, address_id text, period_start text, search_start text, search_end text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source jsonb;candidate jsonb;other jsonb;basis jsonb;active jsonb:='[]';all_owned jsonb:='[]';replaced text[]:=ARRAY[]::text[];id text;at text;state_at text;next_at text;address_at text;latest_address text;n integer;cursor_id text;ancestors text[];tokens jsonb;code text;first_lin integer;own_start integer;own_end integer;physical_at text;latest jsonb;own_entry jsonb;customer_history jsonb;
BEGIN
 customer_history:=gridex_customer_life_events.qualified_patches_v1(i.company_id,i.customer_id,gridex_received_sources.permission_time_v1(period_start||'0000'),gridex_received_sources.permission_time_v1(search_end||'0000'),cutoff);
 IF customer_history->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ai_list_original_customer_patch_owner_required';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(body->'sources') LOOP
  id:=source->>'sourceMessageId';basis:=gridex_ai_processing.source_row_basis_v1(body,cutoff,id,i,object_id,agency);
  IF basis IS NULL THEN
   -- Missing own approval cannot disappear from an otherwise complete source
   -- universe. Independently identify only its physical scope/time; no new
   -- positive business fact or event time is manufactured here.
   tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');
   IF tokens IS NULL THEN RAISE EXCEPTION 'ai_list_original_source_universe_unqualified';END IF;
   SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' ORDER BY (t->>'index')::integer LIMIT 1;
   IF code NOT IN ('Z04','Z06','Z10') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO first_lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_lin AND t#>>'{elements,1,0}'='FR' AND t#>>'{elements,2,0}'=i.receiver_ediel_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK')
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_lin AND t#>>'{elements,1,0}'='DO' AND t#>>'{elements,2,0}'=i.sender_ediel_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO own_start FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=object_id AND t#>>'{elements,3,3}'=agency;
   IF own_start IS NULL THEN CONTINUE;END IF;
   -- A source-wide customer patch is not structural acceptance for another
   -- own object. The SAME E owner parser must prove this exact physical own
   -- event is customer-only; unknown F/G scopes remain independently held.
   IF gridex_ai_processing.customer_source_object_composed_v1(body,cutoff,i,customer_history,source,object_id,agency) THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO own_end FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (t->>'index')::integer>own_start;
   SELECT t#>>'{elements,1,1}' INTO physical_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND (t->>'index')::integer>own_start AND (own_end IS NULL OR (t->>'index')::integer<own_end)
    AND t#>>'{elements,1,0}'=CASE WHEN code='Z04' THEN '92' ELSE '157' END ORDER BY (t->>'index')::integer LIMIT 1;
   IF physical_at IS NOT NULL AND (physical_at<period_start||'0000' OR physical_at>=search_end||'0000') THEN CONTINUE;END IF;
   SELECT x INTO latest FROM jsonb_array_elements(source->'assessments') x WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(source->'assessments') child WHERE child->>'previousAssessmentId'=x->>'id');
   SELECT x INTO own_entry FROM jsonb_array_elements((latest->>'factsText')::jsonb->'objects') x WHERE x#>>'{object,objectId}'=object_id AND x#>>'{object,identityAgency}'=agency;
   IF own_entry->>'disposition'='rejected' THEN CONTINUE;END IF;
   RAISE EXCEPTION 'ai_list_original_dated_source_owner_missing';
  END IF;
  IF basis#>>'{business,supplyPeriodId}' IS DISTINCT FROM period_id THEN CONTINUE;END IF;
  IF basis#>>'{business,wire,businessCase}'='customer_only' THEN
   IF gridex_ai_processing.customer_source_object_composed_v1(body,cutoff,i,customer_history,source,object_id,agency)  THEN CONTINUE;END IF;
   RAISE EXCEPTION 'ai_list_dated_customer_change_owner_required';
  END IF;
  all_owned:=all_owned||jsonb_build_array(jsonb_build_object('id',id,'basis',basis));
 END LOOP;
 -- Only already-qualified exact replacement edges from the same original
 -- object/period may remove a prior event. A claim cannot create an edge.
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  basis:=candidate->'basis';
  IF basis#>>'{business,wire,functionCode}'='5' THEN
   id:=basis#>>'{business,replaces,sourceMessageId}';
   SELECT count(*) INTO n FROM jsonb_array_elements(all_owned) old WHERE old->>'id'=id
    AND old#>>'{basis,business,sourcePayloadHash}'=basis#>>'{business,replaces,payloadHash}'
    AND old#>>'{basis,assessmentId}'=basis#>>'{business,replaces,assessmentId}';
   IF n<>1 OR id=ANY(replaced) OR id=candidate->>'id' THEN RAISE EXCEPTION 'ai_list_original_correction_source_unqualified';END IF;
   replaced:=array_append(replaced,id);
  ELSIF basis#>'{business,replaces}' IS NOT NULL AND basis#>'{business,replaces}'<>'null'::jsonb THEN RAISE EXCEPTION 'ai_list_original_correction_source_unqualified';END IF;
 END LOOP;
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  cursor_id:=candidate->>'id';ancestors:=ARRAY[]::text[];
  WHILE cursor_id IS NOT NULL LOOP
   IF cursor_id=ANY(ancestors) OR cardinality(ancestors)>1000 THEN RAISE EXCEPTION 'ai_list_original_correction_cycle';END IF;
   ancestors:=array_append(ancestors,cursor_id);
   SELECT x#>>'{basis,business,replaces,sourceMessageId}' INTO cursor_id FROM jsonb_array_elements(all_owned) x WHERE x->>'id'=cursor_id;
  END LOOP;
 END LOOP;
 FOR candidate IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  IF NOT(candidate->>'id'=ANY(replaced)) THEN active:=active||jsonb_build_array(candidate);END IF;
 END LOOP;
 SELECT count(*),max(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO n,state_at FROM jsonb_array_elements(active) x WHERE x->>'id'=state_id;
 IF n<>1 OR state_at IS NULL OR state_at<period_start||'0000' OR state_at>=search_end||'0000' THEN RAISE EXCEPTION 'ai_list_original_row_epoch_mismatch';END IF;
 -- No omitted own source may split or precede this emitted epoch. This binds
 -- the row's end to the full immutable source universe, not the next claim.
 SELECT min(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO next_at FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>state_at AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<search_end||'0000';
 IF EXISTS(SELECT FROM jsonb_array_elements(active) x WHERE x->>'id'<>state_id
   AND (x#>>'{basis,business,wire,effectiveFrom,marketMinute}'=state_at
    OR state_at<search_start||'0000' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>state_at AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<=search_start||'0000')) THEN RAISE EXCEPTION 'ai_list_original_row_epoch_mismatch';END IF;
 SELECT max(x#>>'{basis,business,wire,effectiveFrom,marketMinute}') INTO address_at FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,messageCode}'<>'Z10' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'<=state_at
  AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'>=period_start||'0000';
 SELECT count(*),max(x->>'id') INTO n,latest_address FROM jsonb_array_elements(active) x
 WHERE x#>>'{basis,business,wire,messageCode}'<>'Z10' AND x#>>'{basis,business,wire,effectiveFrom,marketMinute}'=address_at;
 IF n<>1 OR latest_address IS DISTINCT FROM address_id OR right(state_at,4)<>'0000' OR next_at IS NOT NULL AND right(next_at,4)<>'0000' THEN RAISE EXCEPTION 'ai_list_original_row_address_epoch_mismatch';END IF;
 RETURN jsonb_build_object('stateMinute',state_at,'nextMinute',next_at);
END $$;

--
-- Name: source_row_basis_v1(jsonb, timestamp with time zone, text, public.ediel_message_intents, text, text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.source_row_basis_v1(body jsonb, cutoff timestamp with time zone, source_id text, i public.ediel_message_intents, object_id text, agency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src jsonb;a jsonb;o jsonb;b jsonb;tokens jsonb;own_tokens jsonb;start_index integer;end_index integer;n integer;
BEGIN
 SELECT count(*),jsonb_agg(s)->0 INTO n,src FROM jsonb_array_elements(body->'sources') s WHERE s->>'sourceMessageId'=source_id;
 IF n<>1 OR src->>'rawPayload' IS NULL OR src->>'payloadHash' IS DISTINCT FROM encode(sha256(convert_to(src->>'rawPayload','UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(x)->0 INTO n,a FROM jsonb_array_elements(src->'assessments') x WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(src->'assessments') child WHERE child->>'previousAssessmentId'=x->>'id');
 IF n<>1 OR a->>'availabilityWitnessId' IS NULL OR a->>'availableAt' IS NULL OR (a->>'availableAt')::timestamptz>cutoff
  OR a->>'factsHash' IS DISTINCT FROM encode(sha256(convert_to(a->>'factsText','UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(x)->0 INTO n,o FROM jsonb_array_elements((a->>'factsText')::jsonb->'objects') x
 WHERE x->>'disposition'='accepted' AND x#>>'{object,objectId}'=object_id AND x#>>'{object,identityAgency}'=agency
  AND x#>>'{business,owner}'='reviewed-received-structure-v1' AND x#>>'{business,companyId}'=i.company_id::text
  AND x#>>'{business,environment}'=i.environment AND x#>>'{business,customerId}'=i.customer_id::text AND x#>>'{business,siteId}'=i.customer_site_id::text
  AND (nullif(i.metering_point_id,'') IS NULL OR x#>>'{business,meteringPointId}'=i.metering_point_id);
 IF n<>1 THEN RETURN NULL;END IF;b:=o->'business';
 IF b->>'sourceMessageId' IS DISTINCT FROM source_id OR b->>'sourcePayloadHash' IS DISTINCT FROM src->>'payloadHash'
  OR b#>>'{wire,legalSender}' IS DISTINCT FROM i.receiver_ediel_id OR b#>>'{wire,legalReceiver}' IS DISTINCT FROM i.sender_ediel_id THEN RETURN NULL;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(src->>'rawPayload');IF tokens IS NULL THEN RETURN NULL;END IF;
 start_index:=(o#>>'{object,registers,0,segmentIndex}')::integer;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer=start_index AND t->>'tag'='LIN'
  AND t#>>'{elements,3,0}'=object_id AND t#>>'{elements,3,3}'=agency) THEN RETURN NULL;END IF;
 SELECT min((t->>'index')::integer) INTO end_index FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (t->>'index')::integer>start_index;
 SELECT jsonb_agg(t ORDER BY (t->>'index')::integer) INTO own_tokens FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>=start_index AND (end_index IS NULL OR (t->>'index')::integer<end_index);
 RETURN jsonb_build_object('business',b,'ownTokens',own_tokens,'assessmentId',a->>'id');
END $$;

--
-- Name: technical_date_v1(text); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.technical_date_v1(value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result date;
BEGIN
 IF value IS NULL OR value !~ '^[0-9]{8}$' OR substring(value,1,4)::integer<1000 THEN RAISE EXCEPTION 'ai_list_date_invalid'; END IF;
 result:=make_date(substring(value,1,4)::integer,substring(value,5,2)::integer,substring(value,7,2)::integer);
 RETURN result;
EXCEPTION WHEN datetime_field_overflow THEN RAISE EXCEPTION 'ai_list_date_invalid';
END $_$;

--
-- Name: transport_mandate_basis_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ai_processing; Owner: -
--

CREATE FUNCTION gridex_ai_processing.transport_mandate_basis_v1(c uuid, env text, legal_actor uuid, transport_actor uuid, relation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('status','held','blocker','ai_list_transport_mandate_source_unqualified')
$$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.actor_v1(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 RETURN mode IN('archive','read','review') AND gridex_requested_changes.actor_v1(c,actor,CASE WHEN mode='review' THEN 'archive' ELSE mode END,'method_contract') IS TRUE
 AND (mode<>'review' OR gridex_requested_changes.scoped_permission_v1(c,actor,'ediel.ai_purpose.review') IS TRUE);
END$$;

--
-- Name: claims_v1(uuid, jsonb); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.claims_v1(c uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result jsonb;from_at timestamptz;until_at timestamptz;retention_until date;days int;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (p->>'listType' IN('AI','BI')) IS NOT TRUE OR (p->>'purpose' IN('ediel_list_export','ediel_list_reconciliation')) IS NOT TRUE OR p->>'purpose'='ediel_list_export' AND p->>'listType'<>'AI' OR length(coalesce(btrim(p->>'gdprBasis'),'')) NOT BETWEEN 1 AND 2000 OR coalesce(p->>'retentionDays','')!~'^[0-9]{1,8}$' OR coalesce(p->>'retentionUntil','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'ai_purpose_claims_required';END IF;
 from_at:=(p->>'validFrom')::timestamptz;until_at:=(p->>'validUntil')::timestamptz;retention_until:=(p->>'retentionUntil')::date;days:=(p->>'retentionDays')::integer;
 IF from_at IS NULL OR until_at IS NULL OR NOT isfinite(from_at) OR NOT isfinite(until_at) OR from_at>=until_at OR until_at<=now() OR days<1 OR retention_until<current_date OR retention_until<(until_at AT TIME ZONE 'UTC')::date THEN RAISE EXCEPTION 'ai_purpose_validity_retention_required';END IF;
 result:=gridex_ai_purpose_sources.legal_scope_v1(c,p->>'environment');
 RETURN result||jsonb_build_object('listType',p->>'listType','purpose',p->>'purpose','gdprBasis',p->>'gdprBasis','retentionDays',days,'retentionUntil',retention_until,'validFrom',from_at,'validUntil',until_at,'retentionClass','ai_bi_personal_source_for_exact_purpose');
END$_$;

--
-- Name: consumer_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.consumer_v1(c uuid, actor uuid, phase text, env text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_ai_processing.authorize_original_actor_v1(c,actor);
 IF (phase IN('origination','send')) IS NOT TRUE OR (env IN('test','production')) IS NOT TRUE OR (CASE WHEN phase='send' THEN gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'ediel.send') IS TRUE OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.send') IS TRUE ELSE gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.write') IS TRUE END) IS NOT TRUE THEN RAISE EXCEPTION 'ai_purpose_current_consumer_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_ai_purpose_sources.legal_scope_v1(c,env);
 PERFORM gridex_ai_processing.authorize_original_actor_v1(c,actor);
 IF (phase IN('origination','send')) IS NOT TRUE OR (env IN('test','production')) IS NOT TRUE OR (CASE WHEN phase='send' THEN gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'ediel.send') IS TRUE OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.send') IS TRUE ELSE gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.write') IS TRUE END) IS NOT TRUE THEN RAISE EXCEPTION 'ai_purpose_current_consumer_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: current_for_scope_v1(uuid, text, text, text); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.current_for_scope_v1(c uuid, list_type text, purpose text, env text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ai_processing.decisions%rowtype;a gridex_ai_purpose_sources.artifacts%rowtype;result jsonb;n int;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF list_type IS NULL OR list_type NOT IN('AI','BI') OR purpose IS NULL OR purpose NOT IN('ediel_list_export','ediel_list_reconciliation') OR purpose='ediel_list_export' AND list_type<>'AI' THEN RETURN jsonb_build_object('status','held','blocker','ai_bi_purpose_not_allowed');END IF;
 SELECT count(*) INTO n FROM gridex_ai_processing.decisions x WHERE company_id=c AND x.list_type=current_for_scope_v1.list_type AND x.purpose=current_for_scope_v1.purpose AND EXISTS(SELECT FROM gridex_ai_purpose_sources.origins origin_candidate JOIN gridex_ai_purpose_sources.artifacts candidate ON candidate.id=origin_candidate.artifact_id WHERE origin_candidate.decision_id=x.id AND (env IS NULL OR candidate.environment=env)) AND NOT EXISTS(SELECT FROM gridex_ai_processing.decisions child WHERE child.previous_decision_id=x.id);
 IF n<>1 THEN RETURN jsonb_build_object('status','held','blocker',CASE WHEN n=0 THEN 'ai_bi_processing_decision_missing' ELSE 'ai_bi_processing_decision_ambiguous' END);END IF;
 SELECT * INTO d FROM gridex_ai_processing.decisions x WHERE company_id=c AND x.list_type=current_for_scope_v1.list_type AND x.purpose=current_for_scope_v1.purpose AND EXISTS(SELECT FROM gridex_ai_purpose_sources.origins origin_candidate JOIN gridex_ai_purpose_sources.artifacts candidate ON candidate.id=origin_candidate.artifact_id WHERE origin_candidate.decision_id=x.id AND (env IS NULL OR candidate.environment=env)) AND NOT EXISTS(SELECT FROM gridex_ai_processing.decisions child WHERE child.previous_decision_id=x.id) FOR SHARE;
 SELECT artifact.* INTO a FROM gridex_ai_purpose_sources.origins o JOIN gridex_ai_purpose_sources.artifacts artifact ON artifact.id=o.artifact_id AND artifact.company_id=o.company_id WHERE o.decision_id=d.id AND o.company_id=c FOR SHARE OF artifact;
 IF a.id IS NULL OR env IS NOT NULL AND a.environment IS DISTINCT FROM env THEN RETURN jsonb_build_object('status','held','blocker','ai_bi_processing_decision_owner_scope_unqualified');END IF;
 result:=gridex_ai_purpose_sources.current_v1(a);IF result IS NULL THEN RETURN jsonb_build_object('status','held','blocker','ai_bi_processing_decision_owner_registry_unqualified');END IF;RETURN jsonb_build_object('status','authorized','decision',result);
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE TABLE gridex_ai_purpose_sources.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_claims_hash_check CHECK ((claims_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ai_purpose_sources.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: current_v1(gridex_ai_purpose_sources.artifacts); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.current_v1(a gridex_ai_purpose_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_ai_purpose_sources.origins%rowtype;r gridex_ai_purpose_sources.reviews%rowtype;d gridex_ai_processing.decisions%rowtype;receipt jsonb;actual jsonb;
BEGIN
 SELECT * INTO o FROM gridex_ai_purpose_sources.origins WHERE artifact_id=a.id AND company_id=a.company_id FOR SHARE;SELECT * INTO r FROM gridex_ai_purpose_sources.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=a.company_id FOR SHARE;SELECT * INTO d FROM gridex_ai_processing.decisions WHERE id=o.decision_id AND company_id=a.company_id FOR SHARE;
 IF d.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_ai_purpose_sources.actor_v1(a.company_id,r.reviewer_user_id,'review') IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash OR EXISTS(SELECT FROM gridex_ai_processing.decisions next WHERE next.previous_decision_id=d.id) THEN RETURN NULL;END IF;
 actual:=gridex_ai_purpose_sources.claims_v1(a.company_id,a.claims);receipt:=gridex_ai_purpose_sources.receipt_current_v1(a);
 IF actual IS DISTINCT FROM a.claims OR receipt IS NULL OR r.clause IS DISTINCT FROM receipt->'clause' OR now()<(a.claims->>'validFrom')::timestamptz OR now()>=(a.claims->>'validUntil')::timestamptz OR d.list_type IS DISTINCT FROM a.claims->>'listType' OR d.purpose IS DISTINCT FROM a.claims->>'purpose' OR d.gdpr_basis IS DISTINCT FROM a.claims->>'gdprBasis' OR d.retention_days IS DISTINCT FROM (a.claims->>'retentionDays')::integer OR d.valid_from IS DISTINCT FROM (a.claims->>'validFrom')::timestamptz OR d.valid_until IS DISTINCT FROM (a.claims->>'validUntil')::timestamptz OR d.source_sha256 IS DISTINCT FROM a.source_hash OR d.source_reference IS DISTINCT FROM a.source_reference OR d.decision_owner_registry_id::text IS DISTINCT FROM receipt->>'ownerRegistryId' OR d.decision_owner_registry_version IS DISTINCT FROM receipt->>'ownerRegistryVersion' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('id',d.id,'revision',d.revision,'companyId',a.company_id,'environment',a.environment,'listType',d.list_type,'purpose',d.purpose,'gdprBasis',d.gdpr_basis,'retentionDays',d.retention_days,'retentionUntil',a.claims->>'retentionUntil','sourceReference',a.source_reference,'sourceSha256',a.source_hash,'ownerRegistryId',d.decision_owner_registry_id,'ownerRegistryVersion',d.decision_owner_registry_version,'artifactId',a.id);
EXCEPTION WHEN raise_exception THEN RETURN NULL;
END$$;

--
-- Name: legal_scope_v1(uuid, text); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.legal_scope_v1(c uuid, env text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE company public.companies%rowtype;actor uuid;identifier text;n int;
BEGIN
 IF env IS NULL OR env NOT IN('test','production') THEN RAISE EXCEPTION 'ai_purpose_environment_required';END IF;
 SELECT * INTO company FROM public.companies WHERE id=c FOR SHARE;
 IF NOT FOUND OR coalesce(to_jsonb(company)->>'status','') IN('archived','suspended','deleted','pending_deletion') OR coalesce(to_jsonb(company)->>'is_active','true')<>'true' OR nullif(to_jsonb(company)->>'legal_name','') IS NULL OR nullif(to_jsonb(company)->>'org_number','') IS NULL THEN RAISE EXCEPTION 'ai_purpose_current_legal_company_required';END IF;
 PERFORM id FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;PERFORM id FROM public.tenant_actor_roles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;PERFORM id FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 SELECT count(*) INTO n FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now());
 SELECT actor_id,identifier_value INTO actor,identifier FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()) ORDER BY id LIMIT 1;
 IF n<>1 OR identifier!~'^[0-9]{5}$' OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=env AND actor_id=actor AND role_code='electricity_supplier' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) THEN RAISE EXCEPTION 'ai_purpose_current_own_supplier_required';END IF;
 RETURN jsonb_build_object('companyId',c,'environment',env,'legalActorId',actor,'legalSupplierEdielId',identifier,'legalCompany',jsonb_build_object('name',to_jsonb(company)->>'legal_name','organizationNumber',to_jsonb(company)->>'org_number'),'sourceProfile',gridex_ai_processing.native_profile_v1());
END$_$;

--
-- Name: receipt_current_v1(gridex_ai_purpose_sources.artifacts); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.receipt_current_v1(a gridex_ai_purpose_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_ai_purpose_sources.issuer_keys%rowtype;g gridex_ai_purpose_sources.representations%rowtype;r jsonb:=a.issuer_receipt;raw bytea;p jsonb;issued timestamptz;expires timestamptz;
BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 65536 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_ai_purpose_sources.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment AND list_type=a.claims->>'listType' AND purpose=a.claims->>'purpose' FOR SHARE;
 SELECT * INTO g FROM gridex_ai_purpose_sources.representations WHERE id=(r->>'representationId')::uuid AND company_id=a.company_id AND environment=a.environment AND issuer_key_id=k.id AND legal_actor_id=(a.claims->>'legalActorId')::uuid AND list_type=a.claims->>'listType' AND purpose=a.claims->>'purpose' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR EXISTS(SELECT FROM gridex_ai_purpose_sources.revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id OR target_kind='artifact' AND target_id=a.id) THEN RETURN NULL;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN NULL;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_ai_purpose_receipt_v1' OR nullif(p->>'receiptId','') IS NULL OR p->'claims' IS DISTINCT FROM a.claims OR p->>'sourceHash' IS DISTINCT FROM a.source_hash OR p->>'sourceReference' IS DISTINCT FROM a.source_reference OR p->>'sourceVersion' IS DISTINCT FROM a.source_version OR p->>'registryVersion' IS DISTINCT FROM k.registry_version OR jsonb_typeof(p->'clause') IS DISTINCT FROM 'object' OR nullif(p#>>'{clause,locator}','') IS NULL OR nullif(p#>>'{clause,quote}','') IS NULL OR position(convert_to(p#>>'{clause,quote}','UTF8') IN a.source_bytes)=0 OR issued IS NULL OR expires IS NULL OR NOT isfinite(issued) OR NOT isfinite(expires) OR issued>now() OR expires<=now() OR issued<greatest(k.valid_from,g.valid_from) OR expires>least(k.valid_to,g.valid_to) OR expires<(a.claims->>'validUntil')::timestamptz THEN RETURN NULL;END IF;
 RETURN p||jsonb_build_object('ownerRegistryId',k.id,'ownerRegistryVersion',k.registry_version);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: revoke_lock_v1(); Type: FUNCTION; Schema: gridex_ai_purpose_sources; Owner: -
--

CREATE FUNCTION gridex_ai_purpose_sources.revoke_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_ai_purpose_sources.issuer_keys WHERE id=NEW.target_id FOR UPDATE;ELSIF NEW.target_kind='representation' THEN PERFORM id FROM gridex_ai_purpose_sources.representations WHERE id=NEW.target_id FOR UPDATE;ELSE PERFORM id FROM gridex_ai_purpose_sources.artifacts WHERE id=NEW.target_id FOR UPDATE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'ai_purpose_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: classification_chain_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classification_chain_v1(c uuid, mid uuid, origin_id uuid, cutoff timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a gridex_received_sources.validation_assessments%rowtype;sf gridex_received_sources.prodat_source_function_facets%rowtype;ctx gridex_customer_life_events.inbound_context_receipts%rowtype;leaf uuid;depth int:=0;seen uuid[]:=ARRAY[]::uuid[];last_clock timestamptz;facts jsonb;
BEGIN
 IF cutoff IS NULL OR NOT isfinite(cutoff) OR cutoff>clock_timestamp() THEN RETURN false;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' THEN RETURN false;END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=mid AND x.company_id=c AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id))<>1 THEN RETURN false;END IF;
 SELECT x.id INTO leaf FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=mid AND x.company_id=c AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id);
 last_clock:=cutoff;
 LOOP
  IF leaf IS NULL OR leaf=ANY(seen) OR depth>=256 THEN RETURN false;END IF;seen:=array_append(seen,leaf);depth:=depth+1;
  SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=leaf FOR SHARE;
  IF a.id IS NULL OR a.company_id IS DISTINCT FROM c OR a.environment IS DISTINCT FROM m.environment OR a.source_message_id IS DISTINCT FROM mid OR a.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR a.assessed_at IS NULL OR a.assessed_at>last_clock THEN RETURN false;END IF;
  facts:=a.facts_text::jsonb;
  IF facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR facts->>'applicationDecision' IS DISTINCT FROM 'accepted' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN RETURN false;END IF;
  -- The originally signed assessment is preserved. A later assessment must
  -- independently carry the protected native customer-function facet.
  IF a.id<>origin_id THEN
   SELECT * INTO sf FROM gridex_received_sources.prodat_source_function_facets WHERE assessment_id=a.id AND company_id=c AND environment=m.environment AND source_message_id=mid FOR SHARE;
   IF sf.assessment_id IS NULL OR sf.source_payload_hash IS DISTINCT FROM a.source_payload_hash OR sf.function_facts_hash IS DISTINCT FROM encode(sha256(convert_to(sf.function_facts_text,'UTF8')),'hex') OR gridex_received_sources.validate_prodat_source_function_v1(c,mid,m.raw_payload,facts,sf.function_facts_text::jsonb) IS NOT TRUE THEN RETURN false;END IF;
   SELECT * INTO ctx FROM gridex_customer_life_events.inbound_context_receipts WHERE id=(sf.function_facts_text::jsonb->>'sourceContextReceiptId')::uuid AND company_id=c AND environment=m.environment AND source_message_id=mid FOR SHARE;
   IF ctx.id IS NULL OR ctx.recorded_at>a.assessed_at OR ctx.recorded_at>cutoff OR ctx.payload_hash IS DISTINCT FROM a.source_payload_hash OR ctx.context_facts_hash IS DISTINCT FROM sf.function_facts_text::jsonb->>'sourceContextFactsHash' THEN RETURN false;END IF;
  END IF;
  IF a.id=origin_id THEN RETURN true;END IF;
  last_clock:=a.assessed_at;leaf:=a.previous_assessment_id;
 END LOOP;
EXCEPTION WHEN invalid_text_representation OR data_exception THEN RETURN false;
END$$;

--
-- Name: classification_current_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classification_current_v1(c uuid, mid uuid, cutoff timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_bilateral_customer_sources.artifacts%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;o gridex_bilateral_customer_sources.life_event_classification_origins%rowtype;q gridex_customer_life_events.inbound_classifications%rowtype;g gridex_customer_life_events.inbound_grounds%rowtype;receipt jsonb;actual jsonb;canonical gridex_received_sources.validation_assessments%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 -- Source-first order is also used by public review and classification revoke.
 PERFORM id FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_bilateral_customer_sources.life_event_classification_origins WHERE source_message_id=mid AND company_id=c FOR SHARE;
 IF o.source_message_id IS NULL OR o.recorded_at>cutoff THEN RETURN NULL;END IF;
 SELECT * INTO a FROM gridex_bilateral_customer_sources.artifacts WHERE id=o.artifact_id AND company_id=c AND environment=o.environment AND source_message_id=mid FOR SHARE;
 SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 SELECT * INTO q FROM gridex_customer_life_events.inbound_classifications WHERE id=o.classification_id AND company_id=c AND source_message_id=mid FOR SHARE;
 SELECT * INTO g FROM gridex_customer_life_events.inbound_grounds WHERE source_message_id=mid AND company_id=c FOR SHARE;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments WHERE id=o.canonical_assessment_id;
 IF a.id IS NULL OR r.id IS NULL OR q.id IS NULL OR g.source_message_id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_bilateral_customer_sources.classified_actor_wallclock_v1(c,r.reviewer_user_id,'review','method_contract') IS NOT TRUE
  OR a.claims_hash IS DISTINCT FROM o.claims_hash OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.claims_hash IS DISTINCT FROM encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') OR a.claims->>'payloadHash' IS DISTINCT FROM o.payload_hash
  OR q.source_payload_hash IS DISTINCT FROM o.payload_hash OR g.source_payload_hash IS DISTINCT FROM o.payload_hash OR encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex') IS DISTINCT FROM o.classification_row_hash OR encode(sha256(convert_to(to_jsonb(g)::text,'UTF8')),'hex') IS DISTINCT FROM o.ground_row_hash
  OR canonical.assessed_at>a.created_at OR a.created_at>r.reviewed_at OR r.reviewed_at>q.approved_at OR q.approved_at>q.recorded_at OR q.recorded_at>o.recorded_at OR r.reviewed_at>cutoff OR q.recorded_at>cutoff
  OR EXISTS(SELECT FROM gridex_customer_life_events.classification_revocations WHERE classification_id=q.id)
  OR gridex_bilateral_customer_sources.classification_chain_v1(c,mid,o.canonical_assessment_id,cutoff) IS NOT TRUE THEN RETURN NULL;END IF;
 receipt:=gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a);
 IF receipt IS NULL OR receipt->'clause' IS DISTINCT FROM r.clause OR position(convert_to(r.clause->>'quote','UTF8') IN a.source_bytes)=0 OR (receipt->>'issuedAt')::timestamptz>a.created_at OR encode(sha256(decode(a.issuer_receipt->>'payloadBase64','base64')),'hex') IS DISTINCT FROM o.receipt_hash THEN RETURN NULL;END IF;
 actual:=gridex_bilateral_customer_sources.classified_source_claims_wallclock_v1(c,mid,a.agreement_id,a.supply_period_id,a.contract_id);
 -- Native lineage, not a caller canonical UUID, authorizes the single changing
 -- assessment key. Every other supply/contract/point/customer/party cell matches.
 IF actual-'canonicalAssessmentId' IS DISTINCT FROM a.claims-'canonicalAssessmentId' OR a.claims->>'canonicalAssessmentId' IS DISTINCT FROM o.canonical_assessment_id::text THEN RETURN NULL;END IF;
 
 IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(c,r.reviewer_user_id,'review','method_contract') IS NOT TRUE THEN RETURN NULL;END IF;
 receipt:=gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a);
 RETURN receipt;

EXCEPTION WHEN raise_exception OR data_exception THEN RETURN NULL;
END$$;

--
-- Name: classification_origin_publish_v1(); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classification_origin_publish_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM gridex_bilateral_customer_sources.publish_life_event_classification_v1(NEW.company_id,NEW.artifact_id);RETURN NEW;END$$;

--
-- Name: classified_actor_wallclock_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classified_actor_wallclock_v1(c uuid, actor uuid, mode text, kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM auth.users WHERE id=actor FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 RETURN actor IS NOT NULL AND mode IN('archive','read','review') AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=clock_timestamp()))
 AND gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,CASE mode WHEN 'read' THEN 'customers.read' ELSE 'customers.write' END) IS TRUE
 AND (kind='death' OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,CASE mode WHEN 'read' THEN 'contracts.read' ELSE 'contracts.write' END) IS TRUE)
 AND (mode<>'review' OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'ediel.source.review') IS TRUE);
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE TABLE gridex_bilateral_customer_sources.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    source_message_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    supply_period_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_claims_hash_check CHECK ((claims_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_bilateral_customer_sources.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: classified_independent_wallclock_v1(gridex_bilateral_customer_sources.artifacts); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a gridex_bilateral_customer_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual jsonb;receipt jsonb;o gridex_bilateral_customer_sources.origins%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_bilateral_customer_sources.origins WHERE artifact_id=a.id AND company_id=a.company_id AND source_message_id=a.source_message_id FOR SHARE;SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=a.company_id FOR SHARE;
 IF r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_bilateral_customer_sources.classified_actor_wallclock_v1(a.company_id,r.reviewer_user_id,'review','method_contract') IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN RETURN NULL;END IF;
 actual:=gridex_bilateral_customer_sources.classified_source_claims_wallclock_v1(a.company_id,a.source_message_id,a.agreement_id,a.supply_period_id,a.contract_id);IF actual IS DISTINCT FROM a.claims THEN RETURN NULL;END IF;
 receipt:=gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a);IF receipt IS NULL OR receipt->'clause' IS DISTINCT FROM r.clause OR position(convert_to(r.clause->>'quote','UTF8') IN a.source_bytes)=0 THEN RETURN NULL;END IF;
 
 IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(a.company_id,r.reviewer_user_id,'review','method_contract') IS NOT TRUE THEN RETURN NULL;END IF;
 RETURN gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a);

EXCEPTION WHEN raise_exception THEN RETURN NULL;
END$$;

--
-- Name: classified_receipt_wallclock_v1(gridex_bilateral_customer_sources.artifacts); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a gridex_bilateral_customer_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r jsonb:=a.issuer_receipt;k gridex_bilateral_customer_sources.issuer_keys%rowtype;g gridex_bilateral_customer_sources.representations%rowtype;raw bytea;p jsonb;issued timestamptz;expires timestamptz;
BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 65536 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_bilateral_customer_sources.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment AND counterparty_actor_id=(a.claims->>'counterpartyActorId')::uuid FOR SHARE;
 SELECT * INTO g FROM gridex_bilateral_customer_sources.representations WHERE id=(r->>'representationId')::uuid AND company_id=a.company_id AND environment=a.environment AND issuer_key_id=k.id AND legal_actor_id=(a.claims->>'legalActorId')::uuid AND agreement_id=a.agreement_id AND purpose='prodat_z06e_customer_change' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR clock_timestamp()<k.valid_from OR clock_timestamp()>=k.valid_to OR clock_timestamp()<g.valid_from OR clock_timestamp()>=g.valid_to OR EXISTS(SELECT FROM gridex_bilateral_customer_sources.revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id OR target_kind='artifact' AND target_id=a.id) THEN RETURN NULL;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN NULL;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz; IF issued IS NULL OR expires IS NULL OR NOT isfinite(issued) OR NOT isfinite(expires) OR expires<=issued OR issued>a.created_at THEN RETURN NULL;END IF;
 IF p->>'format' IS DISTINCT FROM 'ediel_bilateral_customer_source_receipt_v1' OR nullif(p->>'receiptId','') IS NULL OR (p->>'lifeEventKind' IN('customer_change','bankruptcy')) IS NOT TRUE OR p->'claims' IS DISTINCT FROM a.claims OR p->>'sourceHash' IS DISTINCT FROM a.source_hash OR p->>'sourceReference' IS DISTINCT FROM a.source_reference OR p->>'sourceVersion' IS DISTINCT FROM a.source_version OR jsonb_typeof(p->'authorizedFields') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'authorizedFields')=0 OR EXISTS(SELECT FROM jsonb_array_elements_text(p->'authorizedFields') x WHERE x NOT IN('227','228','229','231','232','249','250','251','252','253','316','317','318')) OR (p->'authorizedFields' @> '["227","228","229","231","232","316"]'::jsonb) IS NOT TRUE OR a.claims#>'{party,invoicee}' IS NOT NULL AND a.claims#>'{party,invoicee}'<>'null'::jsonb AND (p->'authorizedFields' @> '["250","251","252","253","317","318"]'::jsonb) IS NOT TRUE OR EXISTS(SELECT FROM jsonb_array_elements(a.claims->'customerTokens') t WHERE t->>'tag'='DTM') AND (p->'authorizedFields' @> '["249"]'::jsonb) IS NOT TRUE OR NOT isfinite(issued) OR NOT isfinite(expires) OR issued>clock_timestamp() OR expires<=clock_timestamp() OR issued<greatest(k.valid_from,g.valid_from) OR expires>least(k.valid_to,g.valid_to) THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: classified_scoped_permission_wallclock_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c uuid, actor uuid, wanted text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM p.id FROM public.permissions p WHERE p.key=wanted ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_permissions p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_roles p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.roles p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.id) ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.role_permissions p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.role_id) ORDER BY p.id FOR SHARE;
 RETURN NOT EXISTS(SELECT FROM public.user_permission_overrides d WHERE d.user_id=actor AND (d.company_id IS NULL OR d.company_id=c) AND d.is_active AND d.effect='deny' AND d.permission_key=wanted AND (d.valid_from IS NULL OR d.valid_from<=clock_timestamp()) AND (d.valid_to IS NULL OR clock_timestamp()<d.valid_to))
 AND NOT EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id IS NULL OR u.company_id=c) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.is_active AND p.key=wanted)
 AND NOT EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.is_active AND p.key=wanted)
 AND (EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted));
END$$;

--
-- Name: classified_source_claims_wallclock_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.classified_source_claims_wallclock_v1(c uuid, source_id uuid, agreement uuid, supply_id uuid, contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;ba public.tenant_bilateral_agreements%rowtype;sp public.customer_supply_periods%rowtype;cc public.customer_contracts%rowtype;mp public.metering_points%rowtype;
 tokens jsonb;own_tokens jsonb;lin jsonb;ud jsonb;iv jsonb;dtm jsonb;supply jsonb;at timestamptz;first_lin int;last_lin int;n int;sender text;legal_actor uuid;counterparty uuid;customer_tokens jsonb;party jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' THEN RAISE EXCEPTION 'bilateral_customer_source_original_required';END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(c,m.id);PERFORM gridex_ediel_source_rules.require_v1(c,m.id);
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=c AND environment=m.environment FOR SHARE;
 IF NOT FOUND OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR s.source_received_at IS NULL OR s.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'bilateral_customer_source_immutable_received_original_required';END IF;
 SELECT count(*) INTO n FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=m.id AND x.company_id=c AND x.environment=m.environment AND x.source_payload_hash=s.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id);
 IF n<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_unique_canonical_required';END IF;
 SELECT * INTO a FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=m.id AND x.company_id=c AND x.environment=m.environment AND x.source_payload_hash=s.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id) FOR SHARE;
 IF a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'bilateral_customer_source_canonical_accepted_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(s.raw_payload);
 IF (SELECT count(DISTINCT jsonb_build_array(t#>>'{elements,3,0}',t#>>'{elements,3,3}')) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z06' AND coalesce(t#>>'{elements,3,0}','9')='9')<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_whole_original_required';END IF;
 SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' ORDER BY (t->>'index')::integer LIMIT 1;first_lin:=(lin->>'index')::int;
 SELECT min((t->>'index')::int) INTO last_lin FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int>first_lin AND t->>'tag' IN('UNT','UNZ','UNH','LIN');
 SELECT jsonb_agg(t ORDER BY (t->>'index')::int) INTO own_tokens FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int>first_lin AND (last_lin IS NULL OR (t->>'index')::int<last_lin);
 IF (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='E34' AND (SELECT p#>>'{elements,2,0}' FROM jsonb_array_elements(own_tokens) p WHERE p->>'tag'='CCI' AND (p->>'index')::int<(t->>'index')::int ORDER BY (p->>'index')::int DESC LIMIT 1)='Z13')<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_z06e_required';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z41') THEN RAISE EXCEPTION 'bilateral_customer_source_cannot_mint_death_fact';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV')>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157' AND t#>>'{elements,1,2}'='203')<>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND nullif(t#>>'{elements,1,1}','') IS NOT NULL)<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_own_parties_clock_reference_required';END IF;
 SELECT t INTO ud FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD';SELECT t INTO iv FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV';SELECT t INTO dtm FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157';at:=gridex_received_sources.permission_time_v1(dtm#>>'{elements,1,1}');
 IF at IS NULL OR nullif(ud#>>'{elements,2,0}','') IS NULL OR nullif(gridex_ai_processing.party_text_v1(ud,4,2),'') IS NULL THEN RAISE EXCEPTION 'bilateral_customer_source_actual_party_minute_required';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=supply_id AND company_id=c FOR SHARE;SELECT * INTO cc FROM public.customer_contracts WHERE id=contract_id AND company_id=c FOR SHARE;SELECT * INTO mp FROM public.metering_points WHERE id=sp.metering_point_id AND company_id=c FOR SHARE;
 supply:=gridex_received_sources.supply_period_source_basis_v1(c,sp.id,at,at+interval '1 minute');legal_actor:=(supply->>'legalActorId')::uuid;
 IF sp.id IS NULL OR cc.id IS NULL OR mp.id IS NULL OR cc.customer_id IS DISTINCT FROM sp.customer_id OR cc.metering_point_id IS DISTINCT FROM mp.id OR mp.customer_id IS DISTINCT FROM sp.customer_id OR (cc.status IN('signed','active')) IS NOT TRUE OR cc.signed_at IS NULL OR nullif(cc.signed_version,'') IS NULL OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM sp.customer_id::text OR supply->>'meteringPointId' IS DISTINCT FROM mp.id::text OR mp.ediel_metering_point_id IS DISTINCT FROM lin#>>'{elements,3,0}' OR (lin#>>'{elements,3,3}' IN('9','89')) IS NOT TRUE OR supply->>'dsoEdielId' IS DISTINCT FROM m.sender_ediel_id OR mp.grid_owner_ediel_id IS DISTINCT FROM m.sender_ediel_id OR mp.product_direction IS DISTINCT FROM 'consumption' THEN RAISE EXCEPTION 'bilateral_customer_source_current_owned_supply_contract_point_required';END IF;
 PERFORM cs.id FROM public.customer_sites cs WHERE cs.id=coalesce(mp.customer_site_id,mp.site_id) AND cs.company_id=c AND cs.customer_id=sp.customer_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'bilateral_customer_source_current_owned_site_required';END IF;
 PERFORM t.id FROM public.tenant_actor_identifiers t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;PERFORM t.id FROM public.tenant_actor_roles t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;PERFORM t.id FROM public.tenant_ediel_profiles t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;
 SELECT min(identifier_value) INTO sender FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=m.environment AND actor_id=legal_actor AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp());
 IF sender IS DISTINCT FROM m.receiver_ediel_id OR (SELECT count(DISTINCT(actor_id,identifier_value)) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=m.environment AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp()))<>1 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=m.environment AND actor_id=legal_actor AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp())) OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=m.environment AND market='electricity' AND is_enabled AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp())) OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::int<first_lin AND t#>>'{elements,1,0}'='FR' AND t#>'{elements,2}'=jsonb_build_array(m.sender_ediel_id,'160','SVK'))<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::int<first_lin AND t#>>'{elements,1,0}'='DO' AND t#>'{elements,2}'=jsonb_build_array(sender,'160','SVK'))<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_exact_current_legal_supplier_required';END IF;
 SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=agreement AND company_id=c AND environment=m.environment FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id ORDER BY i.id FOR SHARE;PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id=ba.counterparty_actor_id ORDER BY r.id FOR SHARE;
 IF ba.id IS NULL OR ba.capability_code IS DISTINCT FROM 'prodat_z06e_customer_change' OR ba.is_enabled IS NOT TRUE OR ba.valid_from>clock_timestamp() OR ba.valid_to<=clock_timestamp() OR nullif(ba.source_reference,'') IS NULL OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=(clock_timestamp()::date)) AND (i.valid_to IS NULL OR i.valid_to>=(clock_timestamp()::date)))<>1 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified AND i.identifier_value=m.sender_ediel_id AND (i.valid_from IS NULL OR i.valid_from<=(clock_timestamp()::date)) AND (i.valid_to IS NULL OR i.valid_to>=(clock_timestamp()::date))) OR NOT EXISTS(SELECT FROM public.platform_actor_roles r WHERE r.actor_id=ba.counterparty_actor_id AND r.actor_role='grid_owner' AND r.is_active) THEN RAISE EXCEPTION 'bilateral_customer_source_current_exact_dso_agreement_required';END IF;
 SELECT jsonb_agg(jsonb_build_object('tag',t->>'tag','elements',t->'elements') ORDER BY (t->>'index')::int) INTO customer_tokens FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag' IN('NAD','DTM') AND (t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN('UD','IV') OR t->>'tag'='DTM' AND t#>>'{elements,1,0}'='329');
 party:=jsonb_build_object('id',ud#>>'{elements,2,0}','qualifier',ud#>>'{elements,2,1}','agency',ud#>>'{elements,2,2}','name',gridex_ai_processing.party_text_v1(ud,4,2),'nameLines',ud#>'{elements,4}','addressLines',ud#>'{elements,5}','city',ud#>>'{elements,6,0}','postalCode',ud#>>'{elements,8,0}','country',ud#>>'{elements,9,0}','invoicee',CASE WHEN iv IS NULL THEN NULL ELSE iv->'elements' END,'birthDate',(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='329' LIMIT 1));
 RETURN jsonb_build_object('sourceMessageId',m.id,'payloadHash',s.payload_hash,'canonicalAssessmentId',a.id,'companyId',c,'environment',m.environment,'agreementId',ba.id,'agreementHash',encode(sha256(convert_to((to_jsonb(ba)-ARRAY['updated_at','created_at'])::text,'UTF8')),'hex'),'counterpartyActorId',ba.counterparty_actor_id,'supplyPeriodId',sp.id,'supplySourceMessageId',supply->>'sourceMessageId','supplyStateVersion',supply->'marketStateVersion','contractId',cc.id,'contractHash',gridex_received_sources.production_contract_hash_v1(cc),'customerId',sp.customer_id,'meteringPointId',mp.id,'siteId',coalesce(mp.customer_site_id,mp.site_id),'objectId',lin#>>'{elements,3,0}','identityAgency',lin#>>'{elements,3,3}','legalActorId',legal_actor,'legalSender',m.sender_ediel_id,'legalReceiver',m.receiver_ediel_id,'effectiveAt',at,'sourceReceivedAt',s.source_received_at,'party',party,'customerTokens',customer_tokens);
END$$;

--
-- Name: current_v1(gridex_bilateral_customer_sources.artifacts); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.current_v1(a gridex_bilateral_customer_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual jsonb;receipt jsonb;o gridex_bilateral_customer_sources.origins%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_bilateral_customer_sources.origins WHERE artifact_id=a.id AND company_id=a.company_id AND source_message_id=a.source_message_id FOR SHARE;SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=a.company_id FOR SHARE;
 IF r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_requested_changes.actor_v1(a.company_id,r.reviewer_user_id,'review','method_contract') IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN RETURN NULL;END IF;
 actual:=gridex_bilateral_customer_sources.source_claims_v1(a.company_id,a.source_message_id,a.agreement_id,a.supply_period_id,a.contract_id);IF actual IS DISTINCT FROM a.claims THEN RETURN NULL;END IF;
 receipt:=gridex_bilateral_customer_sources.receipt_current_v1(a);IF receipt IS NULL OR receipt->'clause' IS DISTINCT FROM r.clause OR position(convert_to(r.clause->>'quote','UTF8') IN a.source_bytes)=0 THEN RETURN NULL;END IF;
 RETURN receipt;
EXCEPTION WHEN raise_exception THEN RETURN NULL;
END$$;

--
-- Name: publish_life_event_classification_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.publish_life_event_classification_v1(c uuid, artifact uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_bilateral_customer_sources.artifacts%rowtype;origin gridex_bilateral_customer_sources.origins%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;existing gridex_bilateral_customer_sources.life_event_classification_origins%rowtype;
 q gridex_customer_life_events.inbound_classifications%rowtype;g gridex_customer_life_events.inbound_grounds%rowtype;ba public.tenant_bilateral_agreements%rowtype;receipt jsonb;basis jsonb;wire jsonb;own jsonb;scope jsonb;fields text[];kind text;stamp timestamptz;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO a FROM gridex_bilateral_customer_sources.artifacts WHERE id=artifact AND company_id=c;
 IF a.id IS NULL THEN RAISE EXCEPTION 'classified_customer_actual_artifact_required';END IF;
 PERFORM id FROM public.ediel_messages WHERE id=a.source_message_id AND company_id=c FOR UPDATE;
 SELECT * INTO a FROM gridex_bilateral_customer_sources.artifacts WHERE id=artifact AND company_id=c FOR SHARE;
 SELECT * INTO existing FROM gridex_bilateral_customer_sources.life_event_classification_origins WHERE source_message_id=a.source_message_id FOR SHARE;
 IF existing.source_message_id IS NOT NULL THEN
  IF existing.artifact_id IS DISTINCT FROM a.id OR existing.company_id IS DISTINCT FROM c THEN RAISE EXCEPTION 'classified_customer_origin_conflict';END IF;RETURN existing.classification_id;
 END IF;
 SELECT * INTO origin FROM gridex_bilateral_customer_sources.origins WHERE artifact_id=a.id AND company_id=c FOR SHARE;
 SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE id=origin.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 receipt:=gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a);
 IF receipt IS NULL OR origin.artifact_id IS NULL OR r.id IS NULL OR (receipt->>'issuedAt')::timestamptz>a.created_at OR a.created_at>r.reviewed_at THEN RAISE EXCEPTION 'classified_customer_actual_independent_current_review_required';END IF;
 wire:=gridex_customer_life_events.wire_partition_v1((SELECT raw_payload FROM public.ediel_messages WHERE id=a.source_message_id AND company_id=c));
 IF wire IS NULL OR wire->>'code' IS DISTINCT FROM 'Z06' OR jsonb_array_length(wire->'objects')<>1 THEN RAISE EXCEPTION 'classified_customer_whole_physical_owner_scope_required';END IF;own:=wire->'objects'->0;
 basis:=gridex_received_sources.supply_period_source_at_v1(c,a.supply_period_id,(own->>'effectiveAt')::timestamptz);
 IF basis->>'qualified' IS DISTINCT FROM 'true' OR basis->>'customerId' IS DISTINCT FROM a.claims->>'customerId' OR basis->>'siteId' IS DISTINCT FROM a.claims->>'siteId' OR basis->>'meteringPointId' IS DISTINCT FROM a.claims->>'meteringPointId' OR basis->>'sourceMessageId' IS DISTINCT FROM a.claims->>'supplySourceMessageId' OR basis->>'marketStateVersion' IS DISTINCT FROM a.claims->>'supplyStateVersion' OR own->>'point' IS DISTINCT FROM a.claims->>'objectId' OR own->>'identityAgency' IS DISTINCT FROM a.claims->>'identityAgency' OR own->>'effectiveAt' IS DISTINCT FROM a.claims->>'effectiveAt' OR own->>'reason' IS DISTINCT FROM 'E34' OR own ? 'customerStatus' OR own->>'projectionHeld'='true' THEN RAISE EXCEPTION 'classified_customer_same_owned_native_tuple_required';END IF;
 SELECT array_agg(f ORDER BY f) INTO fields FROM jsonb_array_elements_text(receipt->'authorizedFields') f WHERE f IN('227','228','229','231','232','316');
 IF fields IS NULL OR NOT(ARRAY['227','228','231','232','316']::text[]<@fields) THEN RAISE EXCEPTION 'classified_customer_exact_owner_fields_required';END IF;
 kind:=CASE receipt->>'lifeEventKind' WHEN 'bankruptcy' THEN 'bankruptcy' WHEN 'customer_change' THEN 'other_masterdata' END;
 IF kind IS NULL THEN RAISE EXCEPTION 'classified_customer_non_death_kind_required';END IF;
 scope:=jsonb_build_array(jsonb_build_object('periodId',basis->>'periodId','customerId',basis->>'customerId','siteId',basis->>'siteId','meteringPointId',basis->>'meteringPointId','pointId',own->>'point','identityAgency',own->>'identityAgency','gridArea',own->>'gridArea','sourceMessageId',basis->>'sourceMessageId','sourcePayloadHash',basis->>'payloadHash','marketStateVersion',basis->>'marketStateVersion','effectiveAt',own->>'effectiveAt','lineItemReference',own->>'li','classification',kind,'targetCustomerIdentity',own#>>'{customerParty,0}','targetCustomerQualifier',own#>>'{customerParty,1}'));
 SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=a.agreement_id AND company_id=c AND environment=a.environment FOR SHARE;
 
 receipt:=gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a);
 IF receipt IS NULL THEN RAISE EXCEPTION 'classified_customer_post_wait_source_authority_required';END IF;
 stamp:=clock_timestamp();

 INSERT INTO gridex_customer_life_events.inbound_classifications(company_id,source_message_id,source_payload_hash,classification,approved_scope,allowed_customer_fields,source_reference,source_version,source_original,source_sha256,classification_original,classification_sha256,owner_decision_reference,approved_by,approved_at)
 VALUES(c,a.source_message_id,a.claims->>'payloadHash',kind,scope,fields,a.source_reference,a.source_version,a.source_bytes,a.source_hash,decode(a.issuer_receipt->>'payloadBase64','base64'),encode(sha256(decode(a.issuer_receipt->>'payloadBase64','base64')),'hex'),r.id::text,r.reviewer_user_id,stamp) RETURNING * INTO q;
 INSERT INTO gridex_customer_life_events.inbound_grounds(source_message_id,company_id,source_payload_hash,classification,bilateral_agreement_id,bilateral_capability_code,bilateral_source_reference,bilateral_terms_sha256,legal_decision_reference,source_reference,source_sha256,approved_scope,allowed_customer_fields,approved_by,approved_at)
 VALUES(a.source_message_id,c,a.claims->>'payloadHash',kind,ba.id,ba.capability_code,ba.source_reference,encode(sha256(convert_to(ba.terms::text,'UTF8')),'hex'),r.id::text,a.source_reference,a.source_hash,scope,fields,r.reviewer_user_id,stamp) RETURNING * INTO g;
 INSERT INTO gridex_bilateral_customer_sources.life_event_classification_origins(source_message_id,company_id,environment,artifact_id,review_id,classification_id,canonical_assessment_id,payload_hash,claims_hash,receipt_hash,classification_row_hash,ground_row_hash)
 VALUES(a.source_message_id,c,a.environment,a.id,r.id,q.id,(a.claims->>'canonicalAssessmentId')::uuid,a.claims->>'payloadHash',a.claims_hash,q.classification_sha256,encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex'),encode(sha256(convert_to(to_jsonb(g)::text,'UTF8')),'hex'));
 RETURN q.id;
END$$;

--
-- Name: receipt_current_v1(gridex_bilateral_customer_sources.artifacts); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.receipt_current_v1(a gridex_bilateral_customer_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r jsonb:=a.issuer_receipt;k gridex_bilateral_customer_sources.issuer_keys%rowtype;g gridex_bilateral_customer_sources.representations%rowtype;raw bytea;p jsonb;issued timestamptz;expires timestamptz;
BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 65536 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_bilateral_customer_sources.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment AND counterparty_actor_id=(a.claims->>'counterpartyActorId')::uuid FOR SHARE;
 SELECT * INTO g FROM gridex_bilateral_customer_sources.representations WHERE id=(r->>'representationId')::uuid AND company_id=a.company_id AND environment=a.environment AND issuer_key_id=k.id AND legal_actor_id=(a.claims->>'legalActorId')::uuid AND agreement_id=a.agreement_id AND purpose='prodat_z06e_customer_change' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR EXISTS(SELECT FROM gridex_bilateral_customer_sources.revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id OR target_kind='artifact' AND target_id=a.id) THEN RETURN NULL;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN NULL;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_bilateral_customer_source_receipt_v1' OR nullif(p->>'receiptId','') IS NULL OR (p->>'lifeEventKind' IN('customer_change','bankruptcy')) IS NOT TRUE OR p->'claims' IS DISTINCT FROM a.claims OR p->>'sourceHash' IS DISTINCT FROM a.source_hash OR p->>'sourceReference' IS DISTINCT FROM a.source_reference OR p->>'sourceVersion' IS DISTINCT FROM a.source_version OR jsonb_typeof(p->'authorizedFields') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'authorizedFields')=0 OR EXISTS(SELECT FROM jsonb_array_elements_text(p->'authorizedFields') x WHERE x NOT IN('227','228','229','231','232','249','250','251','252','253','316','317','318')) OR (p->'authorizedFields' @> '["227","228","229","231","232","316"]'::jsonb) IS NOT TRUE OR a.claims#>'{party,invoicee}' IS NOT NULL AND a.claims#>'{party,invoicee}'<>'null'::jsonb AND (p->'authorizedFields' @> '["250","251","252","253","317","318"]'::jsonb) IS NOT TRUE OR EXISTS(SELECT FROM jsonb_array_elements(a.claims->'customerTokens') t WHERE t->>'tag'='DTM') AND (p->'authorizedFields' @> '["249"]'::jsonb) IS NOT TRUE OR NOT isfinite(issued) OR NOT isfinite(expires) OR issued>now() OR expires<=now() OR issued<greatest(k.valid_from,g.valid_from) OR expires>least(k.valid_to,g.valid_to) THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: revoke_lock_v1(); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.revoke_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_bilateral_customer_sources.issuer_keys WHERE id=NEW.target_id FOR UPDATE;
 ELSIF NEW.target_kind='representation' THEN PERFORM id FROM gridex_bilateral_customer_sources.representations WHERE id=NEW.target_id FOR UPDATE;
 ELSE PERFORM id FROM gridex_bilateral_customer_sources.artifacts WHERE id=NEW.target_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'bilateral_customer_source_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: source_claims_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_customer_sources; Owner: -
--

CREATE FUNCTION gridex_bilateral_customer_sources.source_claims_v1(c uuid, source_id uuid, agreement uuid, supply_id uuid, contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;ba public.tenant_bilateral_agreements%rowtype;sp public.customer_supply_periods%rowtype;cc public.customer_contracts%rowtype;mp public.metering_points%rowtype;
 tokens jsonb;own_tokens jsonb;lin jsonb;ud jsonb;iv jsonb;dtm jsonb;supply jsonb;at timestamptz;first_lin int;last_lin int;n int;sender text;legal_actor uuid;counterparty uuid;customer_tokens jsonb;party jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' THEN RAISE EXCEPTION 'bilateral_customer_source_original_required';END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(c,m.id);PERFORM gridex_ediel_source_rules.require_v1(c,m.id);
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=c AND environment=m.environment FOR SHARE;
 IF NOT FOUND OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR s.source_received_at IS NULL OR s.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'bilateral_customer_source_immutable_received_original_required';END IF;
 SELECT count(*) INTO n FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=m.id AND x.company_id=c AND x.environment=m.environment AND x.source_payload_hash=s.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id);
 IF n<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_unique_canonical_required';END IF;
 SELECT * INTO a FROM gridex_received_sources.validation_assessments x WHERE x.source_message_id=m.id AND x.company_id=c AND x.environment=m.environment AND x.source_payload_hash=s.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=x.id) FOR SHARE;
 IF a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'bilateral_customer_source_canonical_accepted_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(s.raw_payload);
 IF (SELECT count(DISTINCT jsonb_build_array(t#>>'{elements,3,0}',t#>>'{elements,3,3}')) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z06' AND coalesce(t#>>'{elements,3,0}','9')='9')<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_whole_original_required';END IF;
 SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' ORDER BY (t->>'index')::integer LIMIT 1;first_lin:=(lin->>'index')::int;
 SELECT min((t->>'index')::int) INTO last_lin FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int>first_lin AND t->>'tag' IN('UNT','UNZ','UNH','LIN');
 SELECT jsonb_agg(t ORDER BY (t->>'index')::int) INTO own_tokens FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int>first_lin AND (last_lin IS NULL OR (t->>'index')::int<last_lin);
 IF (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='E34' AND (SELECT p#>>'{elements,2,0}' FROM jsonb_array_elements(own_tokens) p WHERE p->>'tag'='CCI' AND (p->>'index')::int<(t->>'index')::int ORDER BY (p->>'index')::int DESC LIMIT 1)='Z13')<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_z06e_required';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z41') THEN RAISE EXCEPTION 'bilateral_customer_source_cannot_mint_death_fact';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV')>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157' AND t#>>'{elements,1,2}'='203')<>1 OR (SELECT count(*) FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND nullif(t#>>'{elements,1,1}','') IS NOT NULL)<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_own_parties_clock_reference_required';END IF;
 SELECT t INTO ud FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD';SELECT t INTO iv FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV';SELECT t INTO dtm FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157';at:=gridex_received_sources.permission_time_v1(dtm#>>'{elements,1,1}');
 IF at IS NULL OR nullif(ud#>>'{elements,2,0}','') IS NULL OR nullif(gridex_ai_processing.party_text_v1(ud,4,2),'') IS NULL THEN RAISE EXCEPTION 'bilateral_customer_source_actual_party_minute_required';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=supply_id AND company_id=c FOR SHARE;SELECT * INTO cc FROM public.customer_contracts WHERE id=contract_id AND company_id=c FOR SHARE;SELECT * INTO mp FROM public.metering_points WHERE id=sp.metering_point_id AND company_id=c FOR SHARE;
 supply:=gridex_received_sources.supply_period_source_basis_v1(c,sp.id,at,at+interval '1 minute');legal_actor:=(supply->>'legalActorId')::uuid;
 IF sp.id IS NULL OR cc.id IS NULL OR mp.id IS NULL OR cc.customer_id IS DISTINCT FROM sp.customer_id OR cc.metering_point_id IS DISTINCT FROM mp.id OR mp.customer_id IS DISTINCT FROM sp.customer_id OR (cc.status IN('signed','active')) IS NOT TRUE OR cc.signed_at IS NULL OR nullif(cc.signed_version,'') IS NULL OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM sp.customer_id::text OR supply->>'meteringPointId' IS DISTINCT FROM mp.id::text OR mp.ediel_metering_point_id IS DISTINCT FROM lin#>>'{elements,3,0}' OR (lin#>>'{elements,3,3}' IN('9','89')) IS NOT TRUE OR supply->>'dsoEdielId' IS DISTINCT FROM m.sender_ediel_id OR mp.grid_owner_ediel_id IS DISTINCT FROM m.sender_ediel_id OR mp.product_direction IS DISTINCT FROM 'consumption' THEN RAISE EXCEPTION 'bilateral_customer_source_current_owned_supply_contract_point_required';END IF;
 PERFORM cs.id FROM public.customer_sites cs WHERE cs.id=coalesce(mp.customer_site_id,mp.site_id) AND cs.company_id=c AND cs.customer_id=sp.customer_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'bilateral_customer_source_current_owned_site_required';END IF;
 PERFORM t.id FROM public.tenant_actor_identifiers t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;PERFORM t.id FROM public.tenant_actor_roles t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;PERFORM t.id FROM public.tenant_ediel_profiles t WHERE t.company_id=c AND t.environment=m.environment ORDER BY t.id FOR SHARE;
 SELECT min(identifier_value) INTO sender FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=m.environment AND actor_id=legal_actor AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now());
 IF sender IS DISTINCT FROM m.receiver_ediel_id OR (SELECT count(DISTINCT(actor_id,identifier_value)) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=m.environment AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()))<>1 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=m.environment AND actor_id=legal_actor AND role_code='electricity_supplier' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=m.environment AND market='electricity' AND is_enabled AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::int<first_lin AND t#>>'{elements,1,0}'='FR' AND t#>'{elements,2}'=jsonb_build_array(m.sender_ediel_id,'160','SVK'))<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::int<first_lin AND t#>>'{elements,1,0}'='DO' AND t#>'{elements,2}'=jsonb_build_array(sender,'160','SVK'))<>1 THEN RAISE EXCEPTION 'bilateral_customer_source_exact_current_legal_supplier_required';END IF;
 SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=agreement AND company_id=c AND environment=m.environment FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id ORDER BY i.id FOR SHARE;PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id=ba.counterparty_actor_id ORDER BY r.id FOR SHARE;
 IF ba.id IS NULL OR ba.capability_code IS DISTINCT FROM 'prodat_z06e_customer_change' OR ba.is_enabled IS NOT TRUE OR ba.valid_from>now() OR ba.valid_to<=now() OR nullif(ba.source_reference,'') IS NULL OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=ba.counterparty_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified AND i.identifier_value=m.sender_ediel_id AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date)) OR NOT EXISTS(SELECT FROM public.platform_actor_roles r WHERE r.actor_id=ba.counterparty_actor_id AND r.actor_role='grid_owner' AND r.is_active) THEN RAISE EXCEPTION 'bilateral_customer_source_current_exact_dso_agreement_required';END IF;
 SELECT jsonb_agg(jsonb_build_object('tag',t->>'tag','elements',t->'elements') ORDER BY (t->>'index')::int) INTO customer_tokens FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag' IN('NAD','DTM') AND (t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN('UD','IV') OR t->>'tag'='DTM' AND t#>>'{elements,1,0}'='329');
 party:=jsonb_build_object('id',ud#>>'{elements,2,0}','qualifier',ud#>>'{elements,2,1}','agency',ud#>>'{elements,2,2}','name',gridex_ai_processing.party_text_v1(ud,4,2),'nameLines',ud#>'{elements,4}','addressLines',ud#>'{elements,5}','city',ud#>>'{elements,6,0}','postalCode',ud#>>'{elements,8,0}','country',ud#>>'{elements,9,0}','invoicee',CASE WHEN iv IS NULL THEN NULL ELSE iv->'elements' END,'birthDate',(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(own_tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='329' LIMIT 1));
 RETURN jsonb_build_object('sourceMessageId',m.id,'payloadHash',s.payload_hash,'canonicalAssessmentId',a.id,'companyId',c,'environment',m.environment,'agreementId',ba.id,'agreementHash',encode(sha256(convert_to((to_jsonb(ba)-ARRAY['updated_at','created_at'])::text,'UTF8')),'hex'),'counterpartyActorId',ba.counterparty_actor_id,'supplyPeriodId',sp.id,'supplySourceMessageId',supply->>'sourceMessageId','supplyStateVersion',supply->'marketStateVersion','contractId',cc.id,'contractHash',gridex_received_sources.production_contract_hash_v1(cc),'customerId',sp.customer_id,'meteringPointId',mp.id,'siteId',coalesce(mp.customer_site_id,mp.site_id),'objectId',lin#>>'{elements,3,0}','identityAgency',lin#>>'{elements,3,3}','legalActorId',legal_actor,'legalSender',m.sender_ediel_id,'legalReceiver',m.receiver_ediel_id,'effectiveAt',at,'sourceReceivedAt',s.source_received_at,'party',party,'customerTokens',customer_tokens);
END$$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.actor_v1(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_bilateral_prodat.lock_graph_v1();
 RETURN mode IN('archive','read','review') AND EXISTS(SELECT FROM public.companies WHERE id=c AND status='active')
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now()))
 AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND public.gridex_actor_has_company_permission(actor,c,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND public.gridex_actor_has_company_permission(actor,c,'contracts.read') IS TRUE
 AND public.gridex_actor_has_company_permission(actor,c,CASE mode WHEN 'read' THEN 'metering.read' ELSE 'metering.write' END) IS TRUE
 AND (mode<>'review' OR public.gridex_actor_has_company_permission(actor,c,'ediel.bilateral_profile.review') IS TRUE AND (
 EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key='ediel.bilateral_profile.review')
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key='ediel.bilateral_profile.review')));
END$$;

--
-- Name: apply_supply_before_closure_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.apply_supply_before_closure_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;w jsonb;v_own jsonb;r jsonb;prior boolean;BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NOT NULL THEN PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);END IF;
 w:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF m.direction='inbound' AND m.message_family='PRODAT' AND EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason'='Z25') THEN
  prior:=EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id AND company_id=m.company_id);
  IF prior AND gridex_bilateral_prodat.recorded_supply_current_v1(m.company_id,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_supply_recorded_current_profile_required';END IF;
  IF w->>'code'='Z05' THEN
   IF EXISTS(SELECT FROM jsonb_array_elements(w->'objects') own WHERE(own->>'reason' IN('Z22','Z23','Z25')) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','bilateral_h_end_whole_scope_required');END IF;
   IF NOT prior THEN FOR v_own IN SELECT own FROM jsonb_array_elements(w->'objects') own WHERE own->>'reason'='Z25' LOOP PERFORM gridex_bilateral_prodat.require_own_end_v1(m,w,v_own);END LOOP;END IF;
   r:=gridex_bilateral_prodat.confirm_h_end_v1(p_company_id,p_source_message_id,p_actor_user_id);
   IF r->>'applied'='true' AND NOT prior THEN PERFORM gridex_bilateral_prodat.record_supply_effect_v1(m);END IF;RETURN r;
  END IF;
 END IF;
 RETURN gridex_bilateral_prodat.apply_supply_before_h_end_v1(p_company_id,p_source_message_id,p_actor_user_id);
END$$;

--
-- Name: apply_supply_before_h_end_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.apply_supply_before_h_end_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;wire jsonb;result jsonb;assessment gridex_received_sources.validation_assessments%rowtype;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NOT NULL THEN PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF m.direction='inbound' AND m.message_family='PRODAT' AND wire->>'code'='Z04'
  AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'reason'='Z25') THEN
  PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
  SELECT * INTO assessment FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment
   AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
  IF assessment.facts_text::jsonb->>'applicationDecision'='rejected' THEN result:=gridex_bilateral_prodat.confirm_h_start_mixed_v1(p_company_id,p_source_message_id,p_actor_user_id);
  ELSE result:=gridex_bilateral_prodat.confirm_h_start_v1(p_company_id,p_source_message_id,p_actor_user_id);END IF;
  IF result->>'applied'='true' THEN PERFORM gridex_bilateral_prodat.record_supply_effect_v1(m);END IF;
  RETURN result;
 END IF;
 RETURN gridex_bilateral_prodat.apply_supply_before_h_v1(p_company_id,p_source_message_id,p_actor_user_id);
END$$;

--
-- Name: apply_supply_before_h_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.apply_supply_before_h_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;old_partition gridex_received_sources.supply_object_partitions%rowtype;application jsonb;canonical uuid;context jsonb;scope jsonb;entry jsonb;wire jsonb;own jsonb;
 result jsonb;partition jsonb:='[]';periods jsonb:='[]';previous_states jsonb:='[]';source_objects jsonb:='[]';switch_ids uuid[]:=ARRAY[]::uuid[];source_ids uuid[];
 effect jsonb;effect_id uuid;effect_hash text;old_state jsonb;plan jsonb;raw_hash text;register_indices integer[];all_indices integer[];receipt_ids uuid[]:=ARRAY[]::uuid[];outcome jsonb;applied_count integer:=0;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'supply_service_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z04','Z05')) IS NOT TRUE THEN RETURN gridex_received_sources.apply_supply_before_own_partition_v1(p_company_id,p_source_message_id,p_actor_user_id);END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 raw_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 -- Established first outcomes precede today's source selection. Historical
 -- global receipts remain their own truth, never prospectively backfilled.
 SELECT * INTO old_partition FROM gridex_received_sources.supply_object_partitions WHERE source_message_id=m.id;
 IF old_partition.source_message_id IS NOT NULL THEN
  IF old_partition.company_id IS DISTINCT FROM m.company_id OR old_partition.environment IS DISTINCT FROM m.environment OR old_partition.payload_hash IS DISTINCT FROM raw_hash THEN RAISE EXCEPTION 'supply_partition_replay_conflict';END IF;
  RETURN old_partition.result||jsonb_build_object('idempotent',true);
 END IF;
 IF EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id) THEN RETURN gridex_received_sources.apply_supply_before_own_partition_v1(p_company_id,p_source_message_id,p_actor_user_id);END IF;
 context:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF context->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR context->>'family' IS DISTINCT FROM 'PRODAT' OR context->>'code' IS DISTINCT FROM m.message_code THEN RETURN jsonb_build_object('applied',false,'reason','supply_frozen_legal_context_required');END IF;
 application:=gridex_received_sources.require_prodat_application_objects_v1(m.company_id,m.id);
 canonical:=(application->>'assessmentId')::uuid;
 IF application->>'headerDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(application->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(application->'objects') NOT BETWEEN 1 AND 8192
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a WHERE a.id=canonical AND a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=raw_hash AND a.facts_text::jsonb->>'syntaxDecision'='accepted' AND a.facts_text::jsonb->>'functionalDecision'='accepted') THEN RETURN jsonb_build_object('applied',false,'reason','supply_complete_own_application_and_function_required');END IF;
 SELECT array_agg((r->>'segmentIndex')::integer ORDER BY(r->>'segmentIndex')::integer) INTO register_indices FROM jsonb_array_elements(application->'objects')o CROSS JOIN LATERAL jsonb_array_elements(o->'registers')r;
 SELECT array_agg((t->>'index')::integer ORDER BY(t->>'index')::integer) INTO all_indices FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(m.raw_payload))t WHERE t->>'tag'='LIN';
 IF register_indices IS DISTINCT FROM all_indices OR cardinality(register_indices)<>(SELECT count(DISTINCT r) FROM unnest(register_indices)r) THEN RETURN jsonb_build_object('applied',false,'reason','supply_complete_physical_partition_required');END IF;
 -- Lock the whole discoverable source cohort before switch/period/point rows.
 -- A later baseline revision fails exact owner checks rather than acquiring a
 -- newly selected source after its dependent period has already been locked.
 SELECT array_agg(DISTINCT id ORDER BY id) INTO source_ids FROM(
  SELECT s.outbound_z03_message_id id FROM public.supplier_switch_requests s WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(application->'objects')o WHERE o->>'objectId'=(SELECT p.ediel_metering_point_id FROM public.metering_points p WHERE p.id=s.metering_point_id AND p.company_id=s.company_id))
  UNION SELECT p.source_message_id FROM public.customer_supply_periods p JOIN public.metering_points mp ON mp.id=p.metering_point_id AND mp.company_id=p.company_id WHERE p.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(application->'objects')o WHERE o->>'objectId'=mp.ediel_metering_point_id)
  UNION SELECT p.source_end_message_id FROM public.customer_supply_periods p JOIN public.metering_points mp ON mp.id=p.metering_point_id AND mp.company_id=p.company_id WHERE p.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(application->'objects')o WHERE o->>'objectId'=mp.ediel_metering_point_id))discovered WHERE id IS NOT NULL;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(source_ids) ORDER BY z.id FOR UPDATE;
 FOR entry IN SELECT o FROM jsonb_array_elements(application->'objects')o ORDER BY(o#>>'{registers,0,segmentIndex}')::integer LOOP
  scope:=entry-'applicationDecision'-'reasonCodes';result:=NULL;wire:=NULL;own:=NULL;effect_id:=NULL;
  IF gridex_received_sources.prodat_application_object_accepted_v1(m.company_id,m.id,canonical,scope) IS NOT TRUE THEN
   partition:=partition||jsonb_build_array(jsonb_build_object('object',scope,'disposition','held','reason','own_application_not_accepted'));CONTINUE;
  END IF;
  -- Two separately represented scopes for the same physical point cannot
  -- compete for one relationship. All remain held, including the first one.
  IF(SELECT count(*) FROM jsonb_array_elements(application->'objects')o WHERE o->>'objectId'=scope->>'objectId')<>1 THEN
   partition:=partition||jsonb_build_array(jsonb_build_object('object',scope,'disposition','held','reason','ambiguous_physical_supply_scope'));CONTINUE;
  END IF;
  wire:=gridex_received_sources.supply_wire_for_scope_v1(m.raw_payload,scope);own:=wire#>'{objects,0}';
  IF wire IS NULL OR wire->>'code' IS DISTINCT FROM m.message_code OR wire->>'receiver' IS DISTINCT FROM context->>'legalEdielId' THEN
   partition:=partition||jsonb_build_array(jsonb_build_object('object',scope,'disposition','held','reason','own_supply_wire_or_legal_scope_unavailable'));CONTINUE;
  END IF;
  -- Each private adapter has no effect until its original complete business
  -- checks pass. A failed returned qualification has performed no writes.
  IF m.message_code='Z04' AND own->>'reason' IN('Z22','Z23') THEN
   result:=gridex_received_sources.normal_switch_scope_effect_v1(m.company_id,m.id,p_actor_user_id,scope,coalesce(source_ids,ARRAY[]::uuid[]),canonical);
  ELSE result:=gridex_received_sources.other_supply_scope_effect_v1(m.company_id,m.id,p_actor_user_id,scope,coalesce(source_ids,ARRAY[]::uuid[]),canonical);END IF;
  IF result->>'applied' IS DISTINCT FROM 'true' THEN
   partition:=partition||jsonb_build_array(jsonb_build_object('object',scope,'disposition','held','reason',coalesce(result->>'reason','own_supply_business_unqualified')));CONTINUE;
  END IF;
  IF jsonb_typeof(result->'plans') IS DISTINCT FROM 'array' OR jsonb_array_length(result->'plans')<>1 OR jsonb_typeof(result->'periods') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'supply_scoped_business_receipt_required';END IF;
  plan:=result#>'{plans,0}';
  -- Exact effects are frozen in the same transaction as the actual source write.
  effect:=jsonb_build_object('version',1,'owner','inbound-supply-object-v1','sourceMessageId',m.id,'sourcePayloadHash',raw_hash,'companyId',m.company_id,'environment',m.environment,'canonicalAssessmentId',canonical,'object',scope,'wire',own,'legalContext',context,'plan',plan,'previousStates',coalesce(result->'previousStates','[]'::jsonb),'resultingStates',result->'periods','previousSwitches',coalesce(result->'previousSwitches','[]'::jsonb),'resultingSwitches',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.supplier_switch_requests s WHERE s.company_id=m.company_id AND s.id=(plan->>'switchId')::uuid),'[]'::jsonb));
  effect_hash:=encode(sha256(convert_to(effect::text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.supply_object_effect_receipts(source_message_id,company_id,environment,payload_hash,canonical_assessment_id,first_line_index,object_scope,effect_text,effect_hash)
   VALUES(m.id,m.company_id,m.environment,raw_hash,canonical,(scope#>>'{registers,0,segmentIndex}')::integer,scope,effect::text,effect_hash) RETURNING id INTO effect_id;
  receipt_ids:=array_append(receipt_ids,effect_id);applied_count:=applied_count+1;periods:=periods||(result->'periods');previous_states:=previous_states||coalesce(result->'previousStates','[]'::jsonb);source_objects:=source_objects||jsonb_build_array(own);
  IF plan->>'switchId' IS NOT NULL THEN switch_ids:=array_append(switch_ids,(plan->>'switchId')::uuid);END IF;
  partition:=partition||jsonb_build_array(jsonb_build_object('object',scope,'disposition','applied','effectReceiptId',effect_id,'effectFactsHash',effect_hash));
 END LOOP;
 -- No object was applied: preserve the source as held without minting an effect
 -- or preventing a later independently qualified source review.
 IF applied_count=0 THEN RETURN jsonb_build_object('applied',false,'reason','no_qualified_supply_objects','partition',partition,'periods','[]'::jsonb,'commits','[]'::jsonb);END IF;
 outcome:=jsonb_build_object('applied',true,'idempotent',false,'periods',periods,'partition',partition,'effectReceiptIds',to_jsonb(receipt_ids),'switchIds',to_jsonb(switch_ids),'commits',
  coalesce((SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id),'[]'::jsonb));
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,raw_hash,m.message_code,source_objects,previous_states,periods,switch_ids,p_actor_user_id);
 INSERT INTO gridex_received_sources.supply_object_partitions(source_message_id,company_id,environment,payload_hash,canonical_assessment_id,partition_text,partition_hash,result,actor_user_id) VALUES(m.id,m.company_id,m.environment,raw_hash,canonical,partition::text,encode(sha256(convert_to(partition::text,'UTF8')),'hex'),outcome,p_actor_user_id);
 RETURN outcome;
END$$;

--
-- Name: bind_switch_before_bilateral_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.bind_switch_before_bilateral_v1(p_company_id uuid, p_switch_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
  result:=public.ediel_bind_switch_original_before_brp_source_v1(p_company_id,p_switch_id,p_message_id,p_actor_user_id);
  IF result->>'status'='bound' AND result->>'idempotent' IS DISTINCT FROM 'true' THEN PERFORM gridex_received_sources.bind_switch_brp_source_v1(p_company_id,p_message_id,p_actor_user_id);END IF;RETURN result;
 END$$;

--
-- Name: bind_switch_h_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.bind_switch_h_v1(p_company_id uuid, p_switch_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s public.supplier_switch_requests%rowtype;c public.customer_contracts%rowtype;
 r public.outbound_requests%rowtype;mp public.metering_points%rowtype;prior gridex_received_sources.switch_originals%rowtype;
 w jsonb;own jsonb;before_state jsonb;identity text;identity_qualifier text;expected_reason text;i public.ediel_message_intents%rowtype;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_outbound_v1();
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'switch_original_execution_actor_required';END IF;
 PERFORM gridex_bilateral_prodat.require_recorded_outbound_v1(m,p_actor_user_id);
 SELECT * INTO prior FROM gridex_received_sources.switch_originals WHERE message_id=m.id;
 IF FOUND THEN IF prior.company_id IS DISTINCT FROM p_company_id OR prior.switch_id IS DISTINCT FROM p_switch_id OR prior.intent_id IS DISTINCT FROM m.intent_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_original_replay_conflict';END IF;RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',true);END IF;
 PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id FOR SHARE;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=p_switch_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=coalesce(s.customer_contract_id,s.contract_id) AND company_id=p_company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=m.outbound_request_id AND company_id=p_company_id FOR SHARE;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id FOR SHARE;
 SELECT coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),'')),CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1' ELSE 'SE2' END INTO identity,identity_qualifier FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);own:=w#>'{objects,0}';
 expected_reason:='Z25';
 IF s.prodat_variant IS DISTINCT FROM 'H' OR s.prodat_reason IS DISTINCT FROM 'Z25' THEN RAISE EXCEPTION 'bilateral_prodat_switch_actual_h_operation_required';END IF;
 IF i.id IS NULL OR i.operation_id IS DISTINCT FROM s.id OR s.id IS NULL OR c.id IS NULL OR mp.id IS NULL OR r.id IS NULL OR w IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' OR m.status IS DISTINCT FROM 'draft'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.switch_request_id IS DISTINCT FROM s.id OR m.source_operation_id IS DISTINCT FROM s.id::text OR m.customer_id IS DISTINCT FROM s.customer_id OR m.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id) OR m.metering_point_id IS DISTINCT FROM s.metering_point_id
  OR (s.site_id IS NOT NULL AND s.site_id IS DISTINCT FROM m.site_id) OR (s.customer_site_id IS NOT NULL AND s.customer_site_id IS DISTINCT FROM m.site_id) OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM c.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM c.id)
  OR s.outbound_z03_message_id IS NOT NULL OR s.inbound_z04_message_id IS NOT NULL OR s.lifecycle_blocked IS DISTINCT FROM false OR (s.status IN('draft','ready','ready_for_switch','ready_for_z03','z03_ready','prepared','queued','waiting')) IS NOT TRUE
  OR (r.payload->>'environment') IS DISTINCT FROM m.environment OR r.source_type IS DISTINCT FROM 'supplier_switch_request' OR r.source_id IS DISTINCT FROM s.id OR r.operation_id IS DISTINCT FROM s.id OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.customer_id IS DISTINCT FROM s.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM mp.id
  OR c.customer_id IS DISTINCT FROM s.customer_id OR c.metering_point_id IS DISTINCT FROM mp.id OR (c.status IN('signed','active')) IS NOT TRUE OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL
  OR mp.customer_id IS DISTINCT FROM s.customer_id OR mp.site_id IS DISTINCT FROM m.site_id OR own->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,'')) OR own->>'installationAgency' IS DISTINCT FROM '9'
  OR own->>'customerQualifier' IS DISTINCT FROM identity_qualifier OR own->>'customerAgency' IS DISTINCT FROM '260' OR own->>'reason' IS DISTINCT FROM expected_reason OR own->>'customerIdentity' IS DISTINCT FROM identity OR nullif(own->>'li','') IS NULL
  OR gridex_received_sources.permission_date_v1(own->>'start') IS DISTINCT FROM s.requested_start_date THEN RAISE EXCEPTION 'switch_original_owned_source_required';END IF;
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,c.id);
 before_state:=to_jsonb(s);
 UPDATE public.supplier_switch_requests SET outbound_z03_message_id=m.id,rff_li_reference=own->>'li',status='prepared',updated_by=p_actor_user_id,updated_at=now() WHERE id=s.id AND company_id=p_company_id RETURNING * INTO s;
 INSERT INTO gridex_received_sources.switch_originals(message_id,company_id,switch_id,intent_id,outbound_request_id,payload_hash,contract_id,contract_hash,original_object,previous_switch,resulting_switch,actor_user_id)
 VALUES(m.id,p_company_id,s.id,m.intent_id,m.outbound_request_id,m.immutable_payload_hash,c.id,gridex_received_sources.production_contract_hash_v1(c),own,before_state,to_jsonb(s),p_actor_user_id);
 RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',false);
END $$;

--
-- Name: closure_operation_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.closure_operation_current_v1(c uuid, actor uuid, operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$DECLARE o gridex_bilateral_prodat.closure_operations%rowtype;scope jsonb;brp text;brp_count integer;BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();SELECT * INTO o FROM gridex_bilateral_prodat.closure_operations WHERE company_id=c AND id=operation;
 IF o.id IS NULL OR o.actor_user_id IS DISTINCT FROM actor THEN RETURN NULL;END IF;
 scope:=gridex_bilateral_prodat.closure_scope_v1(c,actor,o.period_id,o.effective_at);
 IF scope IS NULL OR scope->>'profileId' IS DISTINCT FROM o.profile_id::text OR scope->'profileBinding' IS DISTINCT FROM o.profile_binding
  OR ((scope->'periodBinding')-ARRAY['updated_at','status','actual_start_date']) IS DISTINCT FROM (o.period_binding-ARRAY['updated_at','status','actual_start_date'])
  OR scope#>>'{supplyBasis,initialSourceMessageId}' IS DISTINCT FROM o.supply_basis->>'initialSourceMessageId' OR scope#>>'{supplyBasis,originalPayloadHash}' IS DISTINCT FROM o.supply_basis->>'originalPayloadHash' THEN RETURN NULL;END IF;
 SELECT count(DISTINCT t#>>'{elements,2,0}'),min(t#>>'{elements,2,0}') INTO brp_count,brp
  FROM public.ediel_messages src CROSS JOIN LATERAL jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(src.raw_payload,10000)) t
  WHERE src.id=(scope#>>'{supplyBasis,initialSourceMessageId}')::uuid AND src.company_id=c AND src.direction='inbound'
   AND t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' AND nullif(t#>>'{elements,2,0}','') IS NOT NULL;
 IF brp_count IS DISTINCT FROM 1 OR brp IS NULL THEN RETURN NULL;END IF;
 RETURN scope||jsonb_build_object('balanceResponsibleId',brp,'status','authorized','version',1,'owner','immutable-bilateral-prodat-closure-operation-v1','actorUserId',actor,'operationId',o.id,'lineItemReference','LK'||replace(o.id::text,'-',''),'documentReference','LK'||replace(o.id::text,'-',''));
END$$;

--
-- Name: closure_scope_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.closure_scope_v1(c uuid, actor uuid, period uuid, effective timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE p public.customer_supply_periods%rowtype;mp public.metering_points%rowtype;customer public.customers%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 g gridex_bilateral_prodat.profile_versions%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;basis jsonb;ids uuid[];identity text;BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();
 IF gridex_bilateral_prodat.actor_v1(c,actor,'archive') IS NOT TRUE OR public.gridex_actor_has_company_permission(actor,c,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_closure_actor_forbidden' USING ERRCODE='42501';END IF;
 IF effective IS NULL OR NOT isfinite(effective) OR date_trunc('minute',effective) IS DISTINCT FROM effective THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=period AND company_id=c;
 IF p.id IS NULL OR p.source_end_message_id IS NOT NULL OR p.market_end_at IS NOT NULL OR p.market_start_at>=effective OR (p.status IN('active','confirmed_by_grid_owner')) IS NOT TRUE THEN RETURN NULL;END IF;
 basis:=gridex_received_sources.supply_period_source_basis_v1(c,p.id,effective-interval '1 minute',effective);IF basis IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO mp FROM public.metering_points WHERE id=p.metering_point_id AND company_id=c;
 SELECT * INTO customer FROM public.customers WHERE id=p.customer_id AND company_id=c;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(mp.customer_site_id,mp.site_id) AND company_id=c AND customer_id=p.customer_id;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(p.contract_id,p.customer_contract_id) AND company_id=c AND customer_id=p.customer_id AND metering_point_id=p.metering_point_id;
 identity:=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''));
 IF mp.id IS NULL OR customer.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR mp.customer_id IS DISTINCT FROM p.customer_id OR nullif(mp.ediel_metering_point_id,'') IS NULL OR nullif(mp.grid_area_code,'') IS NULL OR nullif(mp.grid_owner_ediel_id,'') IS NULL OR nullif(identity,'') IS NULL THEN RETURN NULL;END IF;
 SELECT array_agg(v.id ORDER BY v.id) INTO ids FROM gridex_bilateral_prodat.profile_versions v JOIN gridex_bilateral_prodat.origins o ON o.ground_id=v.id AND o.company_id=v.company_id JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=o.artifact_id AND archived.company_id=v.company_id
 WHERE v.company_id=c AND v.environment=(SELECT environment FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=c) AND v.process='closure_request_lk' AND v.legal_actor_id::text=basis->>'legalActorId' AND v.grid_area_code=mp.grid_area_code AND archived.scope->>'legalReceiverId'=mp.grid_owner_ediel_id AND gridex_bilateral_prodat.ground_current_v1(v.id,c,effective) IS TRUE;
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO g FROM gridex_bilateral_prodat.profile_versions WHERE id=ids[1];SELECT archived.* INTO a FROM gridex_bilateral_prodat.origins o JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=o.artifact_id AND archived.company_id=o.company_id WHERE o.ground_id=g.id AND o.company_id=c;
 RETURN jsonb_build_object('companyId',c,'environment',g.environment,'periodId',p.id,'periodBinding',to_jsonb(p),'supplyBasis',basis,'profileId',g.id,'profileBinding',to_jsonb(g)-'revoked_at','effectiveAt',effective,
 'customerId',customer.id,'siteId',site.id,'pointId',mp.id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'externalPoint',mp.ediel_metering_point_id,'identityAgency','9','gridArea',mp.grid_area_code,'legalActorId',g.legal_actor_id,'legalSenderId',a.scope->>'legalSenderId','legalReceiverId',a.scope->>'legalReceiverId','sourceHash',a.source_hash,'sourceGrammarHash',a.scope->>'sourceGrammarHash','customerIdentity',jsonb_build_object('id',identity,'qualifier',CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1' ELSE 'SE2' END,'agency','260'));
END$$;

--
-- Name: committed_h_start_effects_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.committed_h_start_effects_v1(c uuid, source_id uuid, requested integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;application jsonb;effects jsonb:='[]';o jsonb;scope jsonb;first_line integer;raw_hash text;
 receipts integer;b_company uuid;b_environment text;b_hash text;b_transition text;b_recorded timestamptz;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z04','Z05')) IS NOT TRUE THEN RETURN NULL;END IF;
 WITH committed AS(
  SELECT r.company_id,r.environment,r.payload_hash hash,r.transition_hash,r.recorded_at FROM gridex_bilateral_prodat.supply_effect_receipts r
   WHERE r.source_message_id=m.id AND r.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  UNION ALL
  SELECT r.company_id,r.environment,r.source_payload_hash,r.transition_hash,r.recorded_at FROM gridex_bilateral_prodat.closure_end_receipts r
   WHERE m.message_code='Z05' AND r.source_message_id=m.id AND r.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  UNION ALL
  SELECT r.company_id,r.environment,r.source_payload_hash,r.transition_hash,r.recorded_at FROM gridex_supply_rescission.end_receipts r
   WHERE m.message_code='Z05' AND r.source_message_id=m.id AND r.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296))
 SELECT count(*),min(company_id::text)::uuid,min(environment),min(hash),min(transition_hash),min(recorded_at) INTO receipts,b_company,b_environment,b_hash,b_transition,b_recorded FROM committed;
 IF receipts=0 THEN RETURN NULL;END IF;
 IF receipts<>1 THEN RAISE EXCEPTION 'supply_final_response_source_changed';END IF;
 raw_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 IF b_company IS DISTINCT FROM c OR b_environment IS DISTINCT FROM m.environment OR b_hash IS DISTINCT FROM raw_hash
  OR b_transition IS NULL OR b_transition!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'supply_final_response_source_changed';END IF;
 application:=gridex_received_sources.require_prodat_application_objects_v1(c,m.id);
 IF application->>'headerDecision' IS DISTINCT FROM 'accepted' OR application->>'sourcePayloadHash' IS DISTINCT FROM raw_hash THEN RETURN NULL;END IF;
 FOR o IN SELECT e FROM jsonb_array_elements(application->'objects')e ORDER BY(e#>>'{registers,0,segmentIndex}')::integer LOOP
  IF o->>'applicationDecision' IS DISTINCT FROM 'accepted' THEN CONTINUE;END IF;
  scope:=o-'applicationDecision'-'reasonCodes';first_line:=(scope#>>'{registers,0,segmentIndex}')::integer;
  IF requested IS NOT NULL AND NOT(first_line=ANY(requested)) THEN CONTINUE;END IF;
  effects:=effects||jsonb_build_array(jsonb_build_object('receiptId',m.id,'canonicalAssessmentId',application->>'assessmentId','sourcePayloadHash',b_hash,
   'objectScope',scope,'appliedAt',b_recorded,'effectKind','supply','effectFactsHash',b_transition));
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(effects) THEN RAISE EXCEPTION 'supply_final_response_own_effect_uncommitted';END IF;
 RETURN effects;
END $_$;

--
-- Name: confirm_closure_end_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.confirm_closure_end_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);
 END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  reason:=own->>'reason';
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.supply_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'sender' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'receiver'
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23','Z25') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations confirmation WHERE confirmation.period_id=p.id AND confirmation.company_id=p.company_id AND confirmation.source_message_id=p.source_message_id AND confirmation.source_object->>'point'=own->>'point' AND confirmation.source_object->>'identityAgency'=own->>'identityAgency' AND confirmation.source_object->>'customerIdentity'=own->>'customerIdentity' AND confirmation.source_object->>'gridArea'=own->>'gridArea' AND confirmation.market_start_at<event_at AND gridex_received_sources.supply_period_source_basis_v1(p.company_id,p.id,event_at-interval '1 minute',event_at) IS NOT NULL) OR
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text)
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND object->>'reason' IN ('Z26','Z70')))
    );
   IF own->>'reason'='Z23' THEN PERFORM gridex_bilateral_prodat.require_matched_closure_v1(m,wire,own);ids:=ARRAY[(gridex_bilateral_prodat.matched_closure_operation_v1(m,wire,own)->>'periodId')::uuid];END IF;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (planned->>'periodId')::uuid FROM jsonb_array_elements(plans) planned);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),wire->>'code',wire->'objects',before_states,after_states,ARRAY(SELECT (planned->>'switchId')::uuid FROM jsonb_array_elements(plans) planned WHERE planned->>'kind'='cancel_start'),p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'periods',after_states,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;

--
-- Name: confirm_h_end_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.confirm_h_end_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);
 END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  reason:=own->>'reason';
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.supply_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'sender' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'receiver'
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23','Z25') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations confirmation WHERE confirmation.period_id=p.id AND confirmation.company_id=p.company_id AND confirmation.source_message_id=p.source_message_id AND confirmation.source_object->>'point'=own->>'point' AND confirmation.source_object->>'identityAgency'=own->>'identityAgency' AND confirmation.source_object->>'customerIdentity'=own->>'customerIdentity' AND confirmation.source_object->>'gridArea'=own->>'gridArea' AND confirmation.market_start_at<event_at AND gridex_received_sources.supply_period_source_basis_v1(p.company_id,p.id,event_at-interval '1 minute',event_at) IS NOT NULL) OR
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text)
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND object->>'reason' IN ('Z26','Z70')))
    );
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (planned->>'periodId')::uuid FROM jsonb_array_elements(plans) planned);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),wire->>'code',wire->'objects',before_states,after_states,ARRAY(SELECT (planned->>'switchId')::uuid FROM jsonb_array_elements(plans) planned WHERE planned->>'kind'='cancel_start'),p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'periods',after_states,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;

--
-- Name: confirm_h_start_mixed_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.confirm_h_start_mixed_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 guide gridex_received_sources.prodat_object_validation_facets%rowtype;mixed_receipt gridex_received_sources.prodat_mixed_object_receipts%rowtype;whole_wire jsonb;guides jsonb;result jsonb;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 PERFORM gridex_received_sources.lock_prodat_execution_actor_graph_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(m.company_id,m.id);PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 SELECT * INTO mixed_receipt FROM gridex_received_sources.prodat_mixed_object_receipts WHERE source_message_id=m.id FOR SHARE;
 IF FOUND THEN
  IF mixed_receipt.company_id IS DISTINCT FROM m.company_id OR mixed_receipt.environment IS DISTINCT FROM m.environment OR mixed_receipt.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_mixed_replay_conflict';END IF;
  IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=a.id AND f.source_payload_hash=a.source_payload_hash AND f.facts_hash=mixed_receipt.object_facts_hash AND a.facts_hash=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=mixed_receipt.assessment_id)
   WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=mixed_receipt.source_payload_hash
   AND a.facts_text::jsonb->>'syntaxDecision'='accepted' AND a.facts_text::jsonb->>'applicationDecision'='rejected' AND a.facts_text::jsonb->>'functionalDecision'='accepted'
   AND f.facts_text::jsonb->>'sharedAccepted'='true' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)) THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_current_guide_changed');END IF;
  RETURN mixed_receipt.result||jsonb_build_object('idempotent',true);
 END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_existing_other_source_transition');END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'rejected' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 SELECT * INTO guide FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=canonical.id AND company_id=m.company_id AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE;
 IF NOT FOUND OR guide.facts_text::jsonb->>'sharedAccepted' IS DISTINCT FROM 'true' OR EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='unavailable') OR NOT EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='accepted') OR NOT EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='rejected') THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_full_own_guides_required');END IF;
 guides:=guide.facts_text::jsonb->'objects';whole_wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF whole_wire IS NULL OR jsonb_array_length(whole_wire->'objects') IS DISTINCT FROM jsonb_array_length(guides) OR EXISTS(SELECT FROM jsonb_array_elements(guides) g WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(whole_wire->'objects') o WHERE o->>'point'=g->>'objectId' AND o->>'identityAgency'=g->>'identityAgency' AND o->>'li'=g->>'lineItemReference')) THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_whole_physical_scope_required');END IF;
 wire:=whole_wire||jsonb_build_object('objects',(SELECT jsonb_agg(o ORDER BY o->>'point') FROM jsonb_array_elements(whole_wire->'objects') o WHERE EXISTS(SELECT FROM jsonb_array_elements(guides) g WHERE g->>'objectId'=o->>'point' AND g->>'identityAgency'=o->>'identityAgency' AND g->>'disposition'='accepted')));

 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23','Z25')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  OR jsonb_array_length(canonical.facts_text::jsonb#>'{registerValidation,objects}')<>jsonb_array_length(whole_wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason'='Z25' LOOP PERFORM gridex_bilateral_prodat.require_own_start_v1(m,whole_wire,own);END LOOP;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'Z04',wire->'objects','[]',after_states,switch_ids,p_actor_user_id);
 result:=jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
 result:=result||jsonb_build_object('processedObjects',guides,'sourceMessageId',m.id,'sourcePayloadHash',guide.source_payload_hash,'companyId',m.company_id,'environment',m.environment,'objectFactsHash',guide.facts_hash);
 INSERT INTO gridex_received_sources.prodat_mixed_object_receipts(source_message_id,company_id,environment,source_payload_hash,assessment_id,object_facts_hash,processed_objects,result,actor_user_id) VALUES(m.id,m.company_id,m.environment,guide.source_payload_hash,canonical.id,guide.facts_hash,guides,result,p_actor_user_id);
 INSERT INTO gridex_received_sources.prodat_mixed_reply_outbox(source_message_id,company_id,environment,source_payload_hash,object_facts_hash,own_outcomes) VALUES(m.id,m.company_id,m.environment,guide.source_payload_hash,guide.facts_hash,guides);
 RETURN result;
END $$;

--
-- Name: confirm_h_start_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.confirm_h_start_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'normal_z04_replay_conflict';END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states,'switchIds',prior.qualified_switch_ids);
 END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23','Z25')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  OR jsonb_array_length(canonical.facts_text::jsonb#>'{registerValidation,objects}')<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason'='Z25' LOOP PERFORM gridex_bilateral_prodat.require_own_start_v1(m,wire,own);END LOOP;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'Z04',wire->'objects','[]',after_states,switch_ids,p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
END $$;

--
-- Name: dispatch_mixed_start_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.dispatch_mixed_start_v1(c uuid, source_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;wire jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'reason'='Z25') THEN RETURN public.ediel_apply_supply_source_v1(c,source_id,actor);END IF;
 RETURN gridex_received_sources.normal_switch_confirm_mixed_v1(c,source_id,actor);
END$$;

--
-- Name: draft_wire_v1(text); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.draft_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}'); END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF out ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   out:=out||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   obj:=jsonb_build_object('point',nullif(e#>>'{3,0}',''),'line',e#>>'{1,0}');characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN ('92','93') THEN
    key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
    IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL; END IF;
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 IF (out->>'code' IN ('Z03','Z08')) IS NOT TRUE OR nullif(out->>'sender','') IS NULL OR nullif(out->>'receiver','') IS NULL OR jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN out||jsonb_build_object('objects',objects);
END $$;

--
-- Name: first_line_index_v1(text, jsonb); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.first_line_index_v1(raw text, own jsonb) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT min(index)::integer FROM(SELECT t,row_number() OVER(ORDER BY ord)-1 index FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000)) WITH ORDINALITY source(t,ord) WHERE t->>'tag'='LIN') l WHERE t#>>'{elements,3,0}'=own->>'point' AND t#>>'{elements,3,3}'=own->>'identityAgency'
$$;

--
-- Name: ground_current_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.ground_current_v1(ground uuid, company uuid, effective timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE o gridex_bilateral_prodat.origins%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;r gridex_bilateral_prodat.reviews%rowtype;g gridex_bilateral_prodat.profile_versions%rowtype;scope jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_graph_v1();SELECT * INTO o FROM gridex_bilateral_prodat.origins WHERE ground_id=ground AND company_id=company;SELECT * INTO a FROM gridex_bilateral_prodat.artifacts WHERE id=o.artifact_id AND company_id=company;SELECT * INTO r FROM gridex_bilateral_prodat.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=company;SELECT * INTO g FROM gridex_bilateral_prodat.profile_versions WHERE id=ground AND company_id=company;
 IF o.ground_id IS NULL OR a.id IS NULL OR r.id IS NULL OR g.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR g.revoked_at IS NOT NULL OR effective<g.valid_from OR effective>=g.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR o.ground_binding IS DISTINCT FROM to_jsonb(g)-'revoked_at' OR gridex_bilateral_prodat.actor_v1(company,r.reviewer_user_id,'review') IS NOT TRUE OR gridex_bilateral_prodat.receipt_current_v1(a) IS NOT TRUE THEN RETURN false;END IF;
 scope:=gridex_bilateral_prodat.scope_v1(company,a.selector);RETURN scope IS NOT NULL AND scope=a.scope;
END$$;

