--
-- Name: lock_closure_v1(); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.lock_closure_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE gridex_bilateral_prodat.closure_operations,gridex_bilateral_prodat.closure_end_receipts IN SHARE ROW EXCLUSIVE MODE;
END$$;

--
-- Name: lock_graph_v1(); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.lock_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 -- Write-compatible serialization precedes every source/market row. Readers
 -- use the same order; no SHARE-to-writer upgrade or grant-revocation race.
 LOCK TABLE gridex_bilateral_prodat.artifacts,gridex_bilateral_prodat.issuer_keys,gridex_bilateral_prodat.issuer_representations,
 gridex_bilateral_prodat.issuer_revocations,gridex_bilateral_prodat.reviews,gridex_bilateral_prodat.origins,
 gridex_bilateral_prodat.profile_versions IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.customer_contracts,public.customer_contract_documents,public.customers,public.customer_sites,public.metering_points,public.grid_owners,public.tenant_bilateral_agreements,public.ediel_rule_packs,public.ediel_message_profiles,public.ediel_segment_rules,public.ediel_field_rules,public.ediel_rule_pack_sources,public.ediel_ack_rules IN SHARE MODE;
END$$;

--
-- Name: lock_outbound_v1(); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.lock_outbound_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE gridex_bilateral_prodat.outbound_operations,gridex_bilateral_prodat.outbound_receipts IN SHARE ROW EXCLUSIVE MODE;
 -- Public original epoch is acquired only after actual authorization/profile
 -- locks, matching atomic ACK/source owners and excluding insertion races.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
END$$;

--
-- Name: lock_source_receipts_v1(); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.lock_source_receipts_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();PERFORM gridex_bilateral_prodat.lock_graph_v1();
 LOCK TABLE gridex_bilateral_prodat.source_capability_receipts IN SHARE ROW EXCLUSIVE MODE;
END$$;

--
-- Name: lock_supply_v1(); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.lock_supply_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE gridex_bilateral_prodat.supply_effect_receipts IN SHARE ROW EXCLUSIVE MODE;
END$$;

