COMMENT ON COLUMN public.outbound_requests.grid_owner_information_request_id IS 'Facility lookup business request linked to this outbound dispatch.';

--
-- Name: request_binding_v1(public.outbound_requests, gridex_brp_changes.origins); Type: FUNCTION; Schema: gridex_brp_changes; Owner: -
--

CREATE FUNCTION gridex_brp_changes.request_binding_v1(r public.outbound_requests, o gridex_brp_changes.origins) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$SELECT
 r.id IS NOT DISTINCT FROM o.outbound_request_id
  AND r.company_id IS NOT DISTINCT FROM o.company_id
  AND r.source_id::text IS NOT DISTINCT FROM o.intent_id::text
  AND r.source_type IS NOT DISTINCT FROM 'manual'
  AND r.payload->>'environment' IS NOT DISTINCT FROM o.basis->>'environment'
  AND r.request_type IS NOT DISTINCT FROM 'customer_masterdata'
  AND r.customer_id IS NOT DISTINCT FROM (o.basis->>'customerId')::uuid
  AND r.site_id IS NOT DISTINCT FROM (o.basis->>'siteId')::uuid
  AND r.metering_point_id IS NOT DISTINCT FROM (o.basis->>'meteringPointId')::uuid
  AND r.operation_id IS NOT DISTINCT FROM o.event_id
  AND r.communication_route_id IS NOT DISTINCT FROM (o.intent_binding->>'route')::uuid$$;

--
-- Name: require_current_before_positive_test_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_brp_changes; Owner: -
--

CREATE FUNCTION gridex_brp_changes.require_current_before_positive_test_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE m public.ediel_messages%rowtype;
o gridex_brp_changes.origins%rowtype;
b jsonb;
w jsonb;
tokens jsonb;
r public.outbound_requests%rowtype;

BEGIN SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id
  AND id=p_message_id FOR SHARE;
tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
w:=gridex_brp_changes.wire_v1(m.raw_payload);
IF w IS NULL
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM'
  AND t#>>'{elements,1,0}'='Z09')
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV'
  AND t#>>'{elements,1,0}'='Z27') THEN RAISE EXCEPTION 'brp_change_physical_scope_required';
END IF;
IF w IS NULL
  OR w->>'code' IS DISTINCT FROM 'Z09'
  OR w#>>'{object,reason}' IS DISTINCT FROM 'Z27' THEN RETURN;
END IF;

 SELECT * INTO o FROM gridex_brp_changes.origins WHERE company_id=p_company_id
  AND message_id=p_message_id;

 IF NOT FOUND THEN RAISE EXCEPTION 'authentic_brp_change_origin_required';
END IF;

 b:=gridex_brp_changes.context_v1(o.company_id,o.event_id,o.actor_user_id);
SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id
  AND company_id=o.company_id FOR SHARE;
IF gridex_brp_changes.request_binding_v1(r,o) IS NOT TRUE
  OR b IS DISTINCT FROM o.basis
  OR b->>'status' IS DISTINCT FROM 'authorized'
  OR gridex_brp_changes.message_binding_v1(m,o) IS NOT TRUE THEN RAISE EXCEPTION 'brp_change_current_source_held';
END IF;
END$$;

--
-- Name: revocation_lock_v1(); Type: FUNCTION; Schema: gridex_brp_changes; Owner: -
--

CREATE FUNCTION gridex_brp_changes.revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$BEGIN IF NEW.target_kind='event' THEN PERFORM id FROM gridex_brp_changes.events WHERE id=NEW.target_id FOR UPDATE;
ELSE PERFORM id FROM gridex_brp_changes.registry_grounds WHERE id=NEW.target_id FOR UPDATE;
END IF;
IF NOT FOUND THEN RAISE EXCEPTION 'brp_revocation_target_unavailable';
END IF;
RETURN NEW;
END$$;

--
-- Name: wire_v1(text); Type: FUNCTION; Schema: gridex_brp_changes; Owner: -
--

CREATE FUNCTION gridex_brp_changes.wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);
v_token jsonb;
obj jsonb:='{}';
head jsonb:='{}';
characteristic text;
key text;

BEGIN IF tokens IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='UNB')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='BGM')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='UNH')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='LIN')<>1 THEN RETURN NULL;
END IF;

 FOR v_token IN SELECT j.value FROM jsonb_array_elements(tokens) AS j(value) LOOP
 IF v_token->>'tag'='BGM' THEN head:=head||jsonb_build_object('code',v_token#>>'{elements,1,0}');
ELSIF v_token->>'tag'='UNB' THEN head:=head||jsonb_build_object('application',v_token#>>'{elements,7,0}','interchange',v_token#>>'{elements,5,0}','transportSender',v_token#>>'{elements,2,0}','transportReceiver',v_token#>>'{elements,3,0}','senderSubaddress',nullif(v_token#>>'{elements,2,2}',''),'receiverSubaddress',nullif(v_token#>>'{elements,3,2}',''));
ELSIF v_token->>'tag'='UNH' THEN head:=head||jsonb_build_object('message',v_token#>>'{elements,1,0}');
ELSIF v_token->>'tag'='NAD'
  AND v_token#>>'{elements,1,0}' IN('FR','DO') THEN key:=CASE v_token#>>'{elements,1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
IF head?key
  OR v_token#>>'{elements,2,1}' IS DISTINCT FROM '160'
  OR v_token#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;
END IF;
head:=head||jsonb_build_object(key,v_token#>>'{elements,2,0}');

 ELSIF v_token->>'tag'='LIN' THEN obj:=obj||jsonb_build_object('point',v_token#>>'{elements,3,0}','agency',v_token#>>'{elements,3,3}');

 ELSIF v_token->>'tag'='CCI' THEN characteristic:=v_token#>>'{elements,2,0}';

 ELSIF v_token->>'tag'='CAV'
  AND characteristic='Z13' THEN IF obj?'reason' THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object('reason',v_token#>>'{elements,1,0}');

 ELSIF v_token->>'tag'='RFF'
  AND v_token#>>'{elements,1,0}' IN('LI','Z05') THEN key:=CASE v_token#>>'{elements,1,0}' WHEN 'LI' THEN 'li' ELSE 'gridArea' END;
IF obj?key THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object(key,v_token#>>'{elements,1,1}');

 ELSIF v_token->>'tag'='DTM'
  AND v_token#>>'{elements,1,0}'='157' THEN IF obj?'effective'
  OR v_token#>>'{elements,1,2}' IS DISTINCT FROM '203' THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object('effective',v_token#>>'{elements,1,1}');

 ELSIF v_token->>'tag'='NAD'
  AND v_token#>>'{elements,1,0}'='Z02' THEN IF obj?'brp'
  OR v_token#>>'{elements,2,1}' IS DISTINCT FROM '160'
  OR v_token#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object('brp',v_token#>>'{elements,2,0}');
END IF;
END LOOP;

 RETURN head||jsonb_build_object('object',obj);
END$$;

--
-- Name: actor_v1(uuid, uuid, text, boolean); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.actor_v1(c uuid, actor uuid, mode text, require_session boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE wanted text;at timestamptz;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF (mode IN('archive','read','review','revoke')) IS NOT TRUE OR require_session AND public.ediel_retention_session_actor_v1() IS DISTINCT FROM actor OR public.ediel_retention_lock_auth_actor_v1(actor) IS NOT TRUE THEN RETURN false;END IF;
 PERFORM id FROM public.companies WHERE id=c FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL) THEN RETURN false;END IF;
 PERFORM id FROM public.user_permission_overrides WHERE user_id=actor AND(company_id IS NULL OR company_id=c) ORDER BY id FOR SHARE;
 FOREACH wanted IN ARRAY CASE WHEN mode='read' THEN ARRAY['communication.read','customers.read','contracts.read'] WHEN mode='review' THEN ARRAY['communication.write','customers.write','contracts.write','ediel.source.review'] ELSE ARRAY['communication.write','customers.write','contracts.write'] END LOOP
  IF gridex_requested_changes.scoped_permission_v1(c,actor,wanted) IS NOT TRUE THEN RETURN false;END IF;
  at:=clock_timestamp();IF EXISTS(SELECT FROM public.user_permission_overrides WHERE user_id=actor AND(company_id IS NULL OR company_id=c) AND permission_key=wanted AND is_active AND effect='deny' AND(valid_from IS NULL OR valid_from<=at) AND(valid_to IS NULL OR at<valid_to)) THEN RETURN false;END IF;
 END LOOP;RETURN true;
END$$;

--
-- Name: origin_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.origin_current_v1(c uuid, declaration uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_brp_sources.contract_declarations%rowtype;a gridex_brp_declaration_intake.artifacts%rowtype;o gridex_brp_declaration_intake.origins%rowtype;r gridex_brp_declaration_intake.reviews%rowtype;claims jsonb;terminal_current boolean;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT contract_id INTO d.contract_id FROM gridex_brp_sources.contract_declarations WHERE id=declaration AND company_id=c;PERFORM id FROM public.customer_contracts WHERE id=d.contract_id AND company_id=c FOR SHARE;PERFORM pg_advisory_xact_lock_shared(hashtextextended('contract-brp:'||c::text||':'||d.contract_id::text,0));
 SELECT * INTO d FROM gridex_brp_sources.contract_declarations WHERE id=declaration AND company_id=c FOR SHARE;SELECT * INTO o FROM gridex_brp_declaration_intake.origins WHERE declaration_id=declaration AND company_id=c;SELECT * INTO a FROM gridex_brp_declaration_intake.artifacts WHERE id=o.artifact_id AND company_id=c FOR SHARE;SELECT * INTO r FROM gridex_brp_declaration_intake.reviews WHERE id=o.review_id AND company_id=c FOR SHARE;
 IF a.id IS NULL OR gridex_ediel_retention.protected_copy_current_v1(c,a.id) IS NOT TRUE OR d.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR r.artifact_id IS DISTINCT FROM a.id OR EXISTS(SELECT FROM gridex_brp_declaration_intake.artifact_revocations WHERE artifact_id=a.id) OR a.agreement_original IS NULL OR a.source_original IS NULL OR d.agreement_original IS DISTINCT FROM a.agreement_original OR d.source_original IS DISTINCT FROM a.source_original OR d.source_reference IS DISTINCT FROM a.source_reference OR d.source_version IS DISTINCT FROM a.source_version OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN RETURN false;END IF;
 claims:=gridex_brp_declaration_intake.scope_v1(c,a.environment,a.contract_id,(a.claims->>'registryGroundId')::uuid,a.agreement_sha256,a.claims->>'identityAgency');
 terminal_current:=claims=a.claims AND gridex_brp_declaration_intake.receipt_current_v1(a) IS TRUE AND gridex_brp_declaration_intake.actor_v1(c,r.reviewer_user_id,'review',false) IS TRUE AND gridex_brp_declaration_intake.receipt_current_v1(a) IS TRUE; RETURN terminal_current IS TRUE AND gridex_brp_declaration_intake.actor_v1(c,r.reviewer_user_id,'review',false) IS TRUE;
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE TABLE gridex_brp_declaration_intake.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    contract_id uuid NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    agreement_original bytea,
    agreement_sha256 text NOT NULL,
    source_original bytea,
    source_sha256 text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_agreement_original_check CHECK (((octet_length(agreement_original) >= 1) AND (octet_length(agreement_original) <= 10485760))),
    CONSTRAINT artifacts_check CHECK ((agreement_sha256 = encode(sha256(agreement_original), 'hex'::text))),
    CONSTRAINT artifacts_check1 CHECK ((source_sha256 = encode(sha256(source_original), 'hex'::text))),
    CONSTRAINT artifacts_claims_hash_check CHECK ((claims_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_source_original_check CHECK (((octet_length(source_original) >= 1) AND (octet_length(source_original) <= 10485760))),
    CONSTRAINT artifacts_source_reference_check CHECK (((length(btrim(source_reference)) >= 1) AND (length(btrim(source_reference)) <= 2000))),
    CONSTRAINT artifacts_source_version_check CHECK (((length(btrim(source_version)) >= 1) AND (length(btrim(source_version)) <= 200)))
);

ALTER TABLE ONLY gridex_brp_declaration_intake.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_brp_declaration_intake.artifacts); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.receipt_current_v1(a gridex_brp_declaration_intake.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k gridex_brp_declaration_intake.issuer_keys%rowtype;g gridex_brp_declaration_intake.issuer_representations%rowtype;raw bytea;p jsonb;r jsonb:=a.issuer_receipt;issued timestamptz;expires timestamptz;at timestamptz;BEGIN
 IF a.agreement_original IS NULL OR a.source_original IS NULL OR encode(sha256(a.agreement_original),'hex') IS DISTINCT FROM a.agreement_sha256 OR encode(sha256(a.source_original),'hex') IS DISTINCT FROM a.source_sha256 OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash OR r IS NULL THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_brp_declaration_intake.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment FOR SHARE;
 SELECT * INTO g FROM gridex_brp_declaration_intake.issuer_representations WHERE id=(r->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment AND legal_actor_id=(a.claims->>'legalActorId')::uuid AND purpose='signed_contract_brp_declaration' FOR SHARE;
 at:=clock_timestamp();IF k.id IS NULL OR g.id IS NULL OR at<k.valid_from OR at>=k.valid_to OR at<g.valid_from OR at>=g.valid_to OR EXISTS(SELECT FROM gridex_brp_declaration_intake.issuer_revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id) THEN RETURN false;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF octet_length(raw) NOT BETWEEN 1 AND 65536 OR sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN false;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;at:=clock_timestamp();
 RETURN(p->>'format'='ediel_signed_brp_declaration_receipt_v1' AND p->>'purpose'='signed_contract_brp_declaration' AND p->>'companyId'=a.company_id::text AND p->>'environment'=a.environment AND p->>'issuerCode'=k.issuer_code AND nullif(p->>'receiptId','') IS NOT NULL AND p->>'issuerLegalReference'=k.legal_source_reference AND p->>'representationLegalReference'=g.legal_source_reference AND p->>'claimsHash'=a.claims_hash AND p->>'agreementHash'=a.agreement_sha256 AND p->>'sourceHash'=a.source_sha256 AND p->>'sourceReference'=a.source_reference AND p->>'sourceVersion'=a.source_version AND issued IS NOT NULL AND expires IS NOT NULL AND isfinite(issued) AND isfinite(expires) AND at>=greatest(k.valid_from,g.valid_from) AND at<least(k.valid_to,g.valid_to) AND issued<=at AND expires>at AND issued>=greatest(k.valid_from,g.valid_from) AND expires<=least(k.valid_to,g.valid_to)) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END$$;

--
-- Name: revocation_lock_v1(); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE ct uuid;c uuid;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF TG_TABLE_NAME='issuer_revocations' THEN IF NEW.target_kind='key' THEN PERFORM id FROM gridex_brp_declaration_intake.issuer_keys WHERE id=NEW.target_id FOR UPDATE;ELSE PERFORM id FROM gridex_brp_declaration_intake.issuer_representations WHERE id=NEW.target_id FOR UPDATE;END IF;
 ELSE SELECT contract_id,company_id INTO ct,c FROM gridex_brp_declaration_intake.artifacts WHERE id=NEW.artifact_id;PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||c::text||':'||ct::text,0));PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id IN(SELECT declaration_id FROM gridex_brp_declaration_intake.origins WHERE artifact_id=NEW.artifact_id) FOR UPDATE;PERFORM id FROM gridex_brp_declaration_intake.artifacts WHERE id=NEW.artifact_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'signed_brp_revocation_target_required';END IF;RETURN NEW;
END$$;

--
-- Name: scope_v1(uuid, text, uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.scope_v1(c uuid, env text, ct uuid, ground uuid, agreement_hash text, agency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE contract public.customer_contracts%rowtype;point public.metering_points%rowtype;site public.customer_sites%rowtype;document public.customer_contract_documents%rowtype;g gridex_brp_changes.registry_grounds%rowtype;sender text;header jsonb;registry jsonb;signature text;n integer;at timestamptz;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO contract FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=contract.metering_point_id AND company_id=c FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(contract.customer_site_id,contract.site_id) AND company_id=c FOR SHARE;
 SELECT * INTO document FROM public.customer_contract_documents WHERE company_id=c AND customer_contract_id=ct AND document_type='signed_contract_pdf' AND document_sha256=agreement_hash AND verified_at IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
 signature:=encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex');
 IF (env IN('test','production')) IS NOT TRUE OR (agency IN('9','89')) IS NOT TRUE OR contract.id IS NULL OR point.id IS NULL OR site.id IS NULL OR document.id IS NULL OR contract.customer_id IS DISTINCT FROM point.customer_id OR site.customer_id IS DISTINCT FROM contract.customer_id OR coalesce(point.customer_site_id,point.site_id) IS DISTINCT FROM site.id OR contract.site_id IS NOT NULL AND contract.site_id IS DISTINCT FROM site.id OR contract.customer_site_id IS NOT NULL AND contract.customer_site_id IS DISTINCT FROM site.id OR point.site_id IS NOT NULL AND point.site_id IS DISTINCT FROM site.id OR point.customer_site_id IS NOT NULL AND point.customer_site_id IS DISTINCT FROM site.id
 OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR contract.signed_version IS DISTINCT FROM contract.contract_version OR contract.document_sha256 IS DISTINCT FROM agreement_hash OR signature IS DISTINCT FROM contract.signature_snapshot_sha256 OR contract.signature_snapshot->>'company_id' IS DISTINCT FROM c::text OR contract.signature_snapshot->>'customer_id' IS DISTINCT FROM contract.customer_id::text OR contract.signature_snapshot->>'contract_id' IS DISTINCT FROM ct::text THEN RETURN NULL;END IF;
 PERFORM id FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 at:=clock_timestamp();SELECT count(DISTINCT actor_id),min(identifier_value) INTO n,sender FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=at AND(valid_to IS NULL OR at<valid_to);
 IF n<>1 OR nullif(sender,'') IS NULL OR(SELECT count(DISTINCT identifier_value) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=at AND(valid_to IS NULL OR at<valid_to))<>1 THEN RETURN NULL;END IF;
 SELECT * INTO g FROM gridex_brp_changes.registry_grounds WHERE id=ground AND company_id=c AND environment=env AND dso_ediel_id=point.grid_owner_ediel_id AND grid_area_code=point.grid_area_code FOR SHARE;IF g.id IS NULL THEN RETURN NULL;END IF;
 registry:=gridex_brp_sources.registry_basis_v1(c,env,point.grid_owner_ediel_id,point.grid_area_code,g.brp_ediel_id,at,g.id);IF registry IS NULL THEN RETURN NULL;END IF;
 BEGIN header:=gridex_ai_processing.header_company_basis_v1(c,env,sender,point.grid_owner_ediel_id);EXCEPTION WHEN raise_exception THEN RETURN NULL;END;
 IF header->>'legalActorId' IS NULL OR header->>'legalSupplier' IS DISTINCT FROM sender THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('purpose','signed_contract_brp_declaration','companyId',c,'environment',env,'contractId',ct,'contractRevision',contract.signed_version,'protectedContractHash',gridex_received_sources.production_contract_hash_v1(contract),'customerId',contract.customer_id,'siteId',site.id,'meteringPointId',point.id,'pointId',coalesce(nullif(point.ediel_metering_point_id,''),nullif(point.meter_point_id,'')),'identityAgency',agency,'legalActorId',header->>'legalActorId','legalSenderId',sender,'legalReceiverId',point.grid_owner_ediel_id,'gridAreaCode',point.grid_area_code,'registryGroundId',g.id,'brpEdielId',g.brp_ediel_id,'agreementHash',agreement_hash,'contractDocumentId',document.id,'contractDocumentHash',encode(sha256(convert_to(to_jsonb(document)::text,'UTF8')),'hex'),'signatureHash',signature,'registryBasis',registry);
END$$;

--
-- Name: terminal_archive_body_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.terminal_archive_body_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE claims jsonb;ah text;sh text;ch text;agreement bytea;source bytea;a gridex_brp_declaration_intake.artifacts%rowtype;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission) k WHERE k NOT IN('environment','contractId','registryGroundId','identityAgency','agreementBase64','sourceBase64','sourceReference','sourceVersion','issuerReceipt')) THEN RAISE EXCEPTION 'signed_brp_archive_shape_required';END IF;
 agreement:=decode(p_submission->>'agreementBase64','base64');source:=decode(p_submission->>'sourceBase64','base64');IF octet_length(agreement) NOT BETWEEN 1 AND 10485760 OR octet_length(source) NOT BETWEEN 1 AND 10485760 OR substr(agreement,1,5)<>convert_to('%PDF-','UTF8') THEN RAISE EXCEPTION 'signed_brp_actual_pdf_and_source_required';END IF;
 ah:=encode(sha256(agreement),'hex');sh:=encode(sha256(source),'hex');claims:=gridex_brp_declaration_intake.scope_v1(p_company_id,p_submission->>'environment',(p_submission->>'contractId')::uuid,(p_submission->>'registryGroundId')::uuid,ah,p_submission->>'identityAgency');IF claims IS NULL THEN RAISE EXCEPTION 'signed_brp_actual_current_contract_document_registry_scope_required';END IF;ch:=encode(sha256(convert_to(claims::text,'UTF8')),'hex');
 SELECT * INTO a FROM gridex_brp_declaration_intake.artifacts WHERE company_id=p_company_id AND environment=p_submission->>'environment' AND contract_id=(p_submission->>'contractId')::uuid AND claims_hash=ch AND agreement_sha256=ah AND source_sha256=sh AND source_reference=p_submission->>'sourceReference' AND source_version=p_submission->>'sourceVersion' FOR SHARE;
 IF FOUND THEN IF a.issuer_receipt IS DISTINCT FROM p_submission->'issuerReceipt' THEN RAISE EXCEPTION 'signed_brp_archive_immutable_receipt_conflict';END IF;ELSE
  IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_archive_actor_revoked' USING ERRCODE='42501';END IF;
  INSERT INTO gridex_brp_declaration_intake.artifacts(company_id,environment,contract_id,claims,claims_hash,agreement_original,agreement_sha256,source_original,source_sha256,source_reference,source_version,issuer_receipt,submitted_by) VALUES(p_company_id,p_submission->>'environment',(p_submission->>'contractId')::uuid,claims,ch,agreement,ah,source,sh,p_submission->>'sourceReference',p_submission->>'sourceVersion',p_submission->'issuerReceipt',p_actor_user_id) RETURNING * INTO a;
 END IF;RETURN jsonb_build_object('status','archived','artifactId',a.id,'agreementHash',ah,'sourceHash',sh,'claimsHash',ch,'issuerQualified',gridex_brp_declaration_intake.receipt_current_v1(a),'authority','none');
END$$;

--
-- Name: terminal_read_body_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.terminal_read_body_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a gridex_brp_declaration_intake.artifacts%rowtype;r gridex_brp_declaration_intake.reviews%rowtype;declaration uuid;result jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_read_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_brp_declaration_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 PERFORM id FROM public.customer_contracts WHERE id=a.contract_id AND company_id=p_company_id FOR SHARE;PERFORM pg_advisory_xact_lock_shared(hashtextextended('contract-brp:'||p_company_id::text||':'||a.contract_id::text,0));SELECT declaration_id INTO declaration FROM gridex_brp_declaration_intake.origins WHERE artifact_id=a.id;PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id=declaration FOR SHARE;SELECT * INTO STRICT a FROM gridex_brp_declaration_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM gridex_brp_declaration_intake.reviews WHERE artifact_id=a.id ORDER BY created_at DESC,id DESC LIMIT 1;
 result:=jsonb_build_object('artifactId',a.id,'companyId',a.company_id,'environment',a.environment,'contractId',a.contract_id,'claims',a.claims,'claimsHash',a.claims_hash,'agreementHash',a.agreement_sha256,'sourceHash',a.source_sha256,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'agreementByteLength',octet_length(a.agreement_original),'sourceByteLength',octet_length(a.source_original),'bytesAvailable',a.agreement_original IS NOT NULL AND a.source_original IS NOT NULL,'issuerQualified',gridex_brp_declaration_intake.receipt_current_v1(a),'status',CASE WHEN declaration IS NOT NULL AND gridex_brp_declaration_intake.origin_current_v1(p_company_id,declaration) IS TRUE THEN 'authorized' WHEN r.decision='rejected' THEN 'rejected' ELSE 'held' END,'declarationId',declaration,'missing',coalesce(r.missing,'["separate_current_source_review"]'::jsonb),'authority','none');
 IF p_include_bytes THEN IF a.agreement_original IS NULL OR a.source_original IS NULL THEN RAISE EXCEPTION 'signed_brp_archived_original_retention_tombstone';END IF;result:=result||jsonb_build_object('agreementBase64',replace(encode(a.agreement_original,'base64'),E'\n',''),'sourceBase64',replace(encode(a.source_original,'base64'),E'\n',''));END IF;
 IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_read_actor_revoked' USING ERRCODE='42501';END IF;RETURN result;
END$$;

--
-- Name: terminal_review_body_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.terminal_review_body_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a gridex_brp_declaration_intake.artifacts%rowtype;r gridex_brp_declaration_intake.reviews%rowtype;o gridex_brp_declaration_intake.origins%rowtype;d gridex_brp_sources.contract_declarations%rowtype;claims jsonb;missing jsonb:='[]';decision text;ct uuid;prior uuid;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_review_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('agreementHash','sourceHash','claimsHash','decision','reason','clause','previousDeclarationId')) OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR (length(btrim(p_review->>'reason')) BETWEEN 1 AND 4000) IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_review_shape_required';END IF;
 SELECT contract_id INTO STRICT ct FROM gridex_brp_declaration_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=p_company_id FOR SHARE;PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||p_company_id::text||':'||ct::text,0));SELECT * INTO o FROM gridex_brp_declaration_intake.origins WHERE artifact_id=p_artifact_id;prior:=nullif(p_review->>'previousDeclarationId','')::uuid;PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id IN(o.declaration_id,prior) FOR SHARE;SELECT * INTO STRICT a FROM gridex_brp_declaration_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF a.submitted_by=p_actor_user_id OR a.agreement_sha256 IS DISTINCT FROM p_review->>'agreementHash' OR a.source_sha256 IS DISTINCT FROM p_review->>'sourceHash' OR a.claims_hash IS DISTINCT FROM p_review->>'claimsHash' THEN RAISE EXCEPTION 'signed_brp_separate_exact_original_review_required';END IF;
 IF o.declaration_id IS NOT NULL THEN IF gridex_brp_declaration_intake.origin_current_v1(p_company_id,o.declaration_id) IS TRUE THEN RETURN jsonb_build_object('status','authorized','artifactId',a.id,'declarationId',o.declaration_id,'replay',true);END IF;RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',ARRAY['existing_brp_source_current_authority']);END IF;
 claims:=gridex_brp_declaration_intake.scope_v1(p_company_id,a.environment,a.contract_id,(a.claims->>'registryGroundId')::uuid,a.agreement_sha256,a.claims->>'identityAgency');
 IF claims IS DISTINCT FROM a.claims OR a.agreement_original IS NULL OR a.source_original IS NULL OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN missing:=missing||'"same_current_signed_contract_document_registry_scope"'::jsonb;END IF;
 IF gridex_brp_declaration_intake.receipt_current_v1(a) IS NOT TRUE THEN missing:=missing||'"authentic_current_brp_purpose_issuer_representation_receipt"'::jsonb;END IF;
 IF EXISTS(SELECT FROM gridex_brp_declaration_intake.artifact_revocations WHERE artifact_id=a.id) THEN missing:=missing||'"archived_source_revoked"'::jsonb;END IF;
 IF p_review->>'decision'='hold' THEN missing:=missing||'"explicit_source_review_hold"'::jsonb;END IF;
 IF jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review->'clause') k WHERE k NOT IN('locator','quote')) OR (length(btrim(p_review#>>'{clause,locator}')) BETWEEN 1 AND 1000) IS NOT TRUE OR (length(btrim(p_review#>>'{clause,quote}')) BETWEEN 1 AND 10000) IS NOT TRUE THEN missing:=missing||'"verbatim_signed_agreement_brp_clause_review"'::jsonb;END IF;
 IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_review_actor_revoked' USING ERRCODE='42501';END IF;
 decision:=CASE WHEN p_review->>'decision'='reject' THEN 'rejected' WHEN jsonb_array_length(missing)>0 THEN 'held' ELSE 'approved' END;
 INSERT INTO gridex_brp_declaration_intake.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,missing,clause) VALUES(a.id,p_company_id,p_actor_user_id,decision,p_review->>'reason',missing,p_review->'clause') RETURNING * INTO r;
 IF decision<>'approved' THEN RETURN jsonb_build_object('status',CASE decision WHEN 'rejected' THEN 'rejected' ELSE 'held' END,'artifactId',a.id,'missing',missing);END IF;
 IF gridex_brp_declaration_intake.receipt_current_v1(a) IS NOT TRUE OR gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_current_source_authority_expired' USING ERRCODE='42501';END IF;
 INSERT INTO gridex_brp_sources.contract_declarations(previous_declaration_id,company_id,environment,contract_id,contract_revision,protected_contract_hash,customer_id,site_id,metering_point_id,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,registry_ground_id,brp_ediel_id,agreement_original,agreement_sha256,source_reference,source_version,source_original,source_sha256,approved_by,approved_at)
 VALUES(prior,a.company_id,a.environment,a.contract_id,a.claims->>'contractRevision',a.claims->>'protectedContractHash',(a.claims->>'customerId')::uuid,(a.claims->>'siteId')::uuid,(a.claims->>'meteringPointId')::uuid,(a.claims->>'legalActorId')::uuid,a.claims->>'legalSenderId',a.claims->>'legalReceiverId',a.claims->>'pointId',a.claims->>'identityAgency',a.claims->>'gridAreaCode',(a.claims->>'registryGroundId')::uuid,a.claims->>'brpEdielId',a.agreement_original,a.agreement_sha256,a.source_reference,a.source_version,a.source_original,a.source_sha256,p_actor_user_id,clock_timestamp()) RETURNING * INTO d;
 INSERT INTO gridex_brp_declaration_intake.origins(declaration_id,artifact_id,review_id,company_id) VALUES(d.id,a.id,r.id,a.company_id);RETURN jsonb_build_object('status','authorized','artifactId',a.id,'declarationId',d.id,'replay',false);
END$$;

--
-- Name: terminal_revoke_body_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.terminal_revoke_body_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a gridex_brp_declaration_intake.artifacts%rowtype;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'revoke') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_revoke_actor_forbidden' USING ERRCODE='42501';END IF;IF (length(btrim(p_reason)) BETWEEN 1 AND 4000) IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_revoke_reason_required';END IF;
 SELECT * INTO STRICT a FROM gridex_brp_declaration_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 INSERT INTO gridex_brp_declaration_intake.artifact_revocations(artifact_id,actor_user_id,reason) VALUES(a.id,p_actor_user_id,p_reason) ON CONFLICT DO NOTHING;RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',ARRAY['archived_source_revoked']);
END$$;

--
-- Name: terminal_scope_body_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_brp_declaration_intake; Owner: -
--

CREATE FUNCTION gridex_brp_declaration_intake.terminal_scope_body_v1(p_company_id uuid, p_actor_user_id uuid, p_selector jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE claims jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_scope_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_selector) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_selector) k WHERE k NOT IN('environment','contractId','registryGroundId','identityAgency','agreementHash')) OR (p_selector->>'agreementHash'~'^[a-f0-9]{64}$') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_scope_shape_required';END IF;
 claims:=gridex_brp_declaration_intake.scope_v1(p_company_id,p_selector->>'environment',(p_selector->>'contractId')::uuid,(p_selector->>'registryGroundId')::uuid,p_selector->>'agreementHash',p_selector->>'identityAgency');
 IF claims IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['actual_current_signed_contract_document_registry_scope'],'authority','none');END IF;
 RETURN jsonb_build_object('status','scope_available','claims',claims,'claimsHash',encode(sha256(convert_to(claims::text,'UTF8')),'hex'),'authority','none');
END$_$;

--
-- Name: candidate_v1(jsonb, timestamp with time zone, uuid, text, uuid, uuid, uuid, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: gridex_brp_sources; Owner: -
--

CREATE FUNCTION gridex_brp_sources.candidate_v1(body jsonb, cutoff timestamp with time zone, c uuid, env text, customer uuid, site uuid, point uuid, at timestamp with time zone, supply jsonb, state_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE scope public.ediel_message_intents%rowtype;own jsonb;source jsonb;b jsonb;candidate_item jsonb;all_owned jsonb:='[]';active jsonb:='[]';replaced text[]:=ARRAY[]::text[];id text;n integer;cursor_id text;ancestors text[];target jsonb;tokens jsonb;first_line integer;next_line integer;physical_line integer;code text;unknown_entry jsonb;state_at timestamptz;registry jsonb;header jsonb;physical jsonb;network text;supplier text;brp text;field jsonb;
BEGIN
 IF body->>'complete' IS DISTINCT FROM 'true' OR body->>'companyId' IS DISTINCT FROM c::text OR body->>'environment' IS DISTINCT FROM env OR jsonb_typeof(body->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(body->'sources')>1000 OR supply->>'qualified' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 SELECT value INTO own FROM jsonb_array_elements(supply->'sourceObjects');IF jsonb_array_length(supply->'sourceObjects')<>1 OR (own->>'identityAgency' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
 network:=supply->>'dsoEdielId';
 SELECT value INTO source FROM jsonb_array_elements(body->'sources') WHERE value->>'sourceMessageId'=supply->>'initialSourceMessageId';tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');
 SELECT t#>>'{elements,2,0}' INTO supplier FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='DO';IF nullif(supplier,'') IS NULL THEN RETURN NULL;END IF;
 scope.company_id:=c;scope.environment:=env;scope.customer_id:=customer;scope.customer_site_id:=site;scope.metering_point_id:=point::text;scope.sender_ediel_id:=supplier;scope.receiver_ediel_id:=network;
 FOR source IN SELECT value FROM jsonb_array_elements(body->'sources') LOOP
  b:=gridex_ai_processing.source_row_basis_v1(body,cutoff,source->>'sourceMessageId',scope,own->>'point',own->>'identityAgency');
  IF b IS NULL THEN
   tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');IF tokens IS NULL THEN RETURN NULL;END IF;
   SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';IF code NOT IN('Z04','Z06','Z10') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO first_line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_line AND t#>>'{elements,1,0}'='FR' AND t#>>'{elements,2,0}'=network AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK') OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND (t->>'index')::integer<first_line AND t#>>'{elements,1,0}'='DO' AND t#>>'{elements,2,0}'=supplier AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK') THEN CONTINUE;END IF;
   SELECT min((t->>'index')::integer) INTO physical_line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' AND t#>>'{elements,3,3}'=own->>'identityAgency';IF physical_line IS NULL THEN CONTINUE;END IF;
   SELECT value INTO unknown_entry FROM jsonb_array_elements(source->'assessments') value WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(source->'assessments') child WHERE child->>'previousAssessmentId'=value->>'id');
   IF EXISTS(SELECT FROM jsonb_array_elements((unknown_entry->>'factsText')::jsonb->'objects') o WHERE o->>'disposition'='rejected' AND o#>>'{object,objectId}'=own->>'point' AND o#>>'{object,identityAgency}'=own->>'identityAgency') THEN CONTINUE;END IF;
   RETURN NULL;
  END IF;
  IF b#>>'{business,supplyPeriodId}' IS DISTINCT FROM supply->>'periodId' THEN CONTINUE;END IF;
  IF NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.validation_assessments v ON v.id=a.canonical_assessment_id WHERE a.id=(b->>'assessmentId')::uuid AND a.company_id=c AND a.environment=env AND a.source_message_id::text=source->>'sourceMessageId' AND v.source_payload_hash=source->>'payloadHash' AND v.facts_text::jsonb->>'syntaxDecision'='accepted'
 AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
 AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments other WHERE other.company_id=v.company_id AND other.environment=v.environment AND other.source_message_id=v.source_message_id AND other.source_payload_hash=v.source_payload_hash AND other.id<>v.id AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments next WHERE next.previous_assessment_id=other.id))
 AND (
  (v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted')
  OR EXISTS(SELECT FROM jsonb_array_elements(a.facts_text::jsonb->'objects') accepted_own
   WHERE accepted_own->>'disposition'='accepted' AND accepted_own->'business'=b->'business'
    AND accepted_own#>>'{object,objectId}'=own->>'point' AND accepted_own#>>'{object,identityAgency}'=own->>'identityAgency'
    AND CASE WHEN EXISTS(SELECT FROM gridex_received_sources.prodat_application_facets facet WHERE facet.assessment_id=v.id AND facet.company_id=c AND facet.environment=env AND facet.source_message_id=a.source_message_id AND facet.source_payload_hash=v.source_payload_hash)
      THEN coalesce(gridex_received_sources.prodat_application_object_accepted_v1(c,a.source_message_id,v.id,accepted_own->'object'),false) ELSE false END
    AND gridex_received_sources.structural_effect_matches_v1(c,env,a.source_message_id,a.id,customer,site,point,(supply->>'periodId')::uuid,own->>'point',own->>'identityAgency',cutoff) IS TRUE
  )
 )) THEN RETURN NULL;END IF;
  IF b#>>'{business,coverageWindow,baselineSourceMessageId}' IS DISTINCT FROM supply->>'initialSourceMessageId' THEN RETURN NULL;END IF;
  all_owned:=all_owned||jsonb_build_array(jsonb_build_object('id',source->>'sourceMessageId','basis',b));
 END LOOP;
 FOR candidate_item IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  b:=candidate_item->'basis';IF b#>>'{business,wire,functionCode}'='5' THEN
   id:=b#>>'{business,replaces,sourceMessageId}';SELECT count(*) INTO n FROM jsonb_array_elements(all_owned) old WHERE old->>'id'=id AND old#>>'{basis,business,sourcePayloadHash}'=b#>>'{business,replaces,payloadHash}' AND old#>>'{basis,assessmentId}'=b#>>'{business,replaces,assessmentId}' AND old#>>'{basis,business,wire,messageCode}'=b#>>'{business,wire,messageCode}' AND old#>>'{basis,business,wire,businessCase}'=b#>>'{business,wire,businessCase}' AND old#>>'{basis,business,wire,caseReference}'=b#>>'{business,wire,caseReference}';
   IF n<>1 OR id=ANY(replaced) OR id=candidate_item->>'id' THEN RETURN NULL;END IF;replaced:=array_append(replaced,id);
  ELSIF b#>'{business,replaces}' IS NOT NULL AND b#>'{business,replaces}'<>'null'::jsonb THEN RETURN NULL;END IF;
 END LOOP;
 FOR candidate_item IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  cursor_id:=candidate_item->>'id';ancestors:=ARRAY[]::text[];WHILE cursor_id IS NOT NULL LOOP IF cursor_id=ANY(ancestors) OR cardinality(ancestors)>1000 THEN RETURN NULL;END IF;ancestors:=array_append(ancestors,cursor_id);SELECT value#>>'{basis,business,replaces,sourceMessageId}' INTO cursor_id FROM jsonb_array_elements(all_owned) value WHERE value->>'id'=cursor_id;END LOOP;
  IF NOT(candidate_item->>'id'=ANY(replaced)) AND candidate_item#>>'{basis,business,wire,businessCase}'<>'customer_only' THEN active:=active||jsonb_build_array(candidate_item);END IF;
 END LOOP;
 -- Preserve the existing structural owner's same-time ambiguity rule even
 -- when a later object contributes no usable value for this individual field.
 IF EXISTS(SELECT FROM jsonb_array_elements(active) x WHERE (x#>>'{basis,business,wire,effectiveFrom,utc}')::timestamptz<=at GROUP BY x#>>'{basis,business,wire,effectiveFrom,utc}' HAVING count(*)>1) THEN RETURN NULL;END IF;
 all_owned:=active;active:='[]'::jsonb;
 FOR candidate_item IN SELECT value FROM jsonb_array_elements(all_owned) LOOP
  b:=candidate_item->'basis';
  SELECT f.fields_text::jsonb INTO field FROM gridex_received_sources.prodat_ignored_field_facets f JOIN gridex_received_sources.object_assessments a ON a.canonical_assessment_id=f.canonical_assessment_id WHERE a.id=(b->>'assessmentId')::uuid AND a.source_message_id::text=candidate_item->>'id' AND a.company_id=c AND a.environment=env AND f.source_payload_hash=b#>>'{business,sourcePayloadHash}' AND f.fields_hash=encode(sha256(convert_to(f.fields_text,'UTF8')),'hex');
  IF field IS NULL THEN RETURN NULL;END IF;
  SELECT value INTO source FROM jsonb_array_elements(body->'sources') WHERE value->>'sourceMessageId'=candidate_item->>'id';tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');
  SELECT min((t->>'index')::integer) INTO first_line FROM jsonb_array_elements(b->'ownTokens')t WHERE t->>'tag'='LIN';
  SELECT count(*) INTO physical_line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND (t->>'index')::integer<first_line;
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(field) f WHERE f->>'fieldNumber'='262' AND f#>>'{occurrence,objectId}'=own->>'point' AND f#>>'{occurrence,identityAgency}'=own->>'identityAgency' AND (f#>>'{occurrence,lineIndex}')::integer=physical_line) THEN active:=active||jsonb_build_array(candidate_item);END IF;
 END LOOP;
 SELECT count(*),jsonb_agg(x)->0 INTO n,target FROM jsonb_array_elements(active) x WHERE x->>'id'=state_id::text;IF n<>1 THEN RETURN NULL;END IF;
 b:=target->'basis';state_at:=(b#>>'{business,wire,effectiveFrom,utc}')::timestamptz;
 IF state_at IS NULL OR state_at>at OR state_at<(supply->>'marketStartAt')::timestamptz OR EXISTS(SELECT FROM jsonb_array_elements(active) x WHERE x->>'id'<>state_id::text AND (x#>>'{basis,business,wire,effectiveFrom,utc}')::timestamptz>=state_at AND (x#>>'{basis,business,wire,effectiveFrom,utc}')::timestamptz<=at) THEN RETURN NULL;END IF;
 IF b#>>'{business,wire,messageCode}'<>'Z04' AND gridex_received_sources.structural_effect_matches_v1(c,env,state_id,(b->>'assessmentId')::uuid,customer,site,point,(supply->>'periodId')::uuid,own->>'point',own->>'identityAgency',cutoff) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(t)->0 INTO n,physical FROM jsonb_array_elements(b->'ownTokens') t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02';
 IF n<>1 OR physical#>>'{elements,2,1}' IS DISTINCT FROM '160' OR physical#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' OR jsonb_array_length(physical#>'{elements,2}')<>3 THEN RETURN NULL;END IF;brp:=physical#>>'{elements,2,0}';IF nullif(brp,'') IS NULL OR brp<>btrim(brp) OR length(brp)>35 THEN RETURN NULL;END IF;
 -- Same accepted canonical invocation's P119 mask, never current rule reselect.
 SELECT f.fields_text::jsonb INTO field FROM gridex_received_sources.prodat_ignored_field_facets f JOIN gridex_received_sources.object_assessments a ON a.canonical_assessment_id=f.canonical_assessment_id WHERE a.id=(b->>'assessmentId')::uuid AND a.source_message_id=state_id AND a.company_id=c AND a.environment=env AND f.source_payload_hash=b#>>'{business,sourcePayloadHash}' AND f.fields_hash=encode(sha256(convert_to(f.fields_text,'UTF8')),'hex');
 SELECT value INTO source FROM jsonb_array_elements(body->'sources') WHERE value->>'sourceMessageId'=state_id::text;tokens:=gridex_received_sources.closure_wire_tokens_v2(source->>'rawPayload');
 SELECT min((t->>'index')::integer) INTO first_line FROM jsonb_array_elements(b->'ownTokens')t WHERE t->>'tag'='LIN';
 SELECT count(*) INTO physical_line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND (t->>'index')::integer<first_line;
 IF field IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(field) f WHERE f->>'fieldNumber'='262' AND f#>>'{occurrence,objectId}'=own->>'point' AND f#>>'{occurrence,identityAgency}'=own->>'identityAgency' AND (f#>>'{occurrence,lineIndex}')::integer=physical_line) THEN RETURN NULL;END IF;
 registry:=gridex_brp_sources.registry_basis_v1(c,env,network,own->>'gridArea',brp,at);IF registry IS NULL THEN RETURN NULL;END IF;
 header:=gridex_ai_processing.header_company_basis_v1(c,env,supplier,network);IF header->>'legalActorId' IS DISTINCT FROM supply->>'legalActorId' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('status','authorized','sourceKind','accepted_supply_brp','companyId',c,'environment',env,'customerId',customer,'siteId',site,'meteringPointId',point,'at',at,'supplyPeriodId',supply->>'periodId','brpEdielId',brp,'pointId',own->>'point','identityAgency',own->>'identityAgency','legalActorId',supply->>'legalActorId','legalSenderId',supplier,'legalReceiverId',network,'gridArea',own->>'gridArea','sourceMessageId',state_id,'sourcePayloadHash',b#>>'{business,sourcePayloadHash}','assessmentId',b->>'assessmentId','registryBasis',registry);
END$$;

--
-- Name: declaration_scope_v1(); Type: FUNCTION; Schema: gridex_brp_sources; Owner: -
--

CREATE FUNCTION gridex_brp_sources.declaration_scope_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior gridex_brp_sources.contract_declarations%rowtype;BEGIN
 IF TG_TABLE_NAME='contract_revocations' THEN SELECT * INTO prior FROM gridex_brp_sources.contract_declarations WHERE id=NEW.declaration_id;IF prior.id IS NULL THEN RAISE EXCEPTION 'brp_declaration_original_required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||prior.company_id::text||':'||prior.contract_id::text,0));PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id=prior.id FOR UPDATE;
 ELSE PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||NEW.company_id::text||':'||NEW.contract_id::text,0));IF NEW.previous_declaration_id IS NOT NULL THEN SELECT * INTO prior FROM gridex_brp_sources.contract_declarations WHERE id=NEW.previous_declaration_id FOR UPDATE;IF prior.company_id IS DISTINCT FROM NEW.company_id OR prior.contract_id IS DISTINCT FROM NEW.contract_id OR prior.environment IS DISTINCT FROM NEW.environment OR NEW.approved_at<prior.approved_at THEN RAISE EXCEPTION 'brp_declaration_own_version_required';END IF;END IF;END IF;RETURN NEW;
END$$;

--
-- Name: registry_basis_v1(uuid, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: gridex_brp_sources; Owner: -
--

CREATE FUNCTION gridex_brp_sources.registry_basis_v1(c uuid, env text, network text, grid text, brp text, at timestamp with time zone, ground uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g gridex_brp_changes.registry_grounds%rowtype;n integer;BEGIN
 SELECT count(*) INTO n FROM gridex_brp_changes.registry_grounds x WHERE x.company_id=c AND x.environment=env AND x.dso_ediel_id=network AND x.grid_area_code=grid AND x.brp_ediel_id=brp AND (ground IS NULL OR x.id=ground) AND x.approved_at<=statement_timestamp() AND x.valid_from<=at AND (x.valid_to IS NULL OR at<x.valid_to) AND NOT EXISTS(SELECT FROM gridex_brp_changes.revocations r WHERE r.target_kind='registry' AND r.target_id=x.id);
 IF n<>1 THEN RETURN NULL;END IF;
 SELECT * INTO g FROM gridex_brp_changes.registry_grounds x WHERE x.company_id=c AND x.environment=env AND x.dso_ediel_id=network AND x.grid_area_code=grid AND x.brp_ediel_id=brp AND (ground IS NULL OR x.id=ground) AND x.approved_at<=statement_timestamp() AND x.valid_from<=at AND (x.valid_to IS NULL OR at<x.valid_to) AND NOT EXISTS(SELECT FROM gridex_brp_changes.revocations r WHERE r.target_kind='registry' AND r.target_id=x.id) FOR SHARE;
 -- The revoker locks the parent without changing it. Recheck after SHARE so
 -- a committed revocation observed while waiting cannot escape this phase.
 IF g.id IS NULL OR EXISTS(SELECT FROM gridex_brp_changes.revocations r WHERE r.target_kind='registry' AND r.target_id=g.id) THEN RETURN NULL;END IF;
 PERFORM a.id FROM public.platform_market_actors a WHERE a.id IN(g.dso_actor_id,g.brp_actor_id) ORDER BY a.id FOR SHARE;PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id IN(g.dso_actor_id,g.brp_actor_id) ORDER BY i.id FOR SHARE;PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id IN(g.dso_actor_id,g.brp_actor_id) ORDER BY r.id FOR SHARE;
 IF g.registry_snapshot IS DISTINCT FROM gridex_brp_changes.registry_snapshot_v1(g.dso_actor_id,g.brp_actor_id)
 OR NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=g.dso_actor_id AND status='active' AND match_status='verified') OR NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=g.brp_actor_id AND status='active' AND match_status='verified')
 OR NOT EXISTS(SELECT FROM public.platform_actor_roles WHERE actor_id=g.dso_actor_id AND actor_role='grid_owner' AND is_active) OR NOT EXISTS(SELECT FROM public.platform_actor_roles WHERE actor_id=g.brp_actor_id AND actor_role='balance_responsible' AND is_active)
 OR (SELECT count(DISTINCT actor_id) FROM public.platform_actor_identifiers WHERE lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=network AND is_verified AND (valid_from IS NULL OR valid_from<=current_date) AND (valid_to IS NULL OR valid_to>=current_date))<>1
 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers WHERE actor_id=g.dso_actor_id AND lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=network AND is_verified AND (valid_from IS NULL OR valid_from<=current_date) AND (valid_to IS NULL OR valid_to>=current_date))
 OR (SELECT count(DISTINCT actor_id) FROM public.platform_actor_identifiers WHERE lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=brp AND is_verified AND (valid_from IS NULL OR valid_from<=(at AT TIME ZONE 'Etc/GMT-1')::date) AND (valid_to IS NULL OR valid_to>=(at AT TIME ZONE 'Etc/GMT-1')::date))<>1
 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers WHERE actor_id=g.brp_actor_id AND lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=brp AND is_verified AND (valid_from IS NULL OR valid_from<=(at AT TIME ZONE 'Etc/GMT-1')::date) AND (valid_to IS NULL OR valid_to>=(at AT TIME ZONE 'Etc/GMT-1')::date)) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('registryGroundId',g.id,'registryVersion',g.registry_version,'registrySha256',g.source_sha256,'brpActorId',g.brp_actor_id);
END$$;

--
-- Name: require_source_v1(uuid, uuid, uuid, text, text, uuid, uuid, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: gridex_brp_sources; Owner: -
--

CREATE FUNCTION gridex_brp_sources.require_source_v1(c uuid, ct uuid, actor uuid, phase text, env text, customer uuid, site uuid, point uuid, p_at timestamp with time zone, period uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE supply jsonb;receipt jsonb;body jsonb;candidate jsonb;answer jsonb;seen text[]:=ARRAY[]::text[];prepared gridex_brp_sources.qualified_candidates%rowtype;contract public.customer_contracts%rowtype;mp public.metering_points%rowtype;cs public.customer_sites%rowtype;d gridex_brp_sources.contract_declarations%rowtype;network jsonb;header jsonb;registry jsonb;n integer;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF (phase IN('prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'brp_source_phase_required';END IF;
 PERFORM gridex_ai_processing.authorize_purpose_phase_v1(c,actor,CASE phase WHEN 'send' THEN 'send' ELSE 'origination' END,NULL);
 IF c IS NULL OR customer IS NULL OR site IS NULL OR point IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR (env IN('test','production')) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_brp_scope']);END IF;
 IF period IS NOT NULL THEN
  supply:=gridex_received_sources.supply_period_source_at_v1(c,period,p_at);
  IF supply IS NULL OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM customer::text OR supply->>'siteId' IS DISTINCT FROM site::text OR supply->>'meteringPointId' IS DISTINCT FROM point::text OR NOT EXISTS(SELECT FROM gridex_received_sources.sources s WHERE s.source_message_id=(supply->>'initialSourceMessageId')::uuid AND s.company_id=c AND s.environment=env) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_current_source_owned_supply_relation']);END IF;
  receipt:=gridex_received_sources.open_object_selection_snapshot(c,env,clock_timestamp());body:=(receipt->>'readsetText')::jsonb;
  -- The initial original is an explicit candidate only; this fence cannot
  -- approve it when a later own source changes or makes its epoch ambiguous.
  answer:=gridex_brp_sources.candidate_v1(body,(body->>'cutoffAt')::timestamptz,c,env,customer,site,point,p_at,supply,(supply->>'initialSourceMessageId')::uuid);
  IF answer IS NOT NULL THEN seen:=array_append(seen,answer->>'sourceMessageId');END IF;
  FOR prepared IN SELECT * FROM gridex_brp_sources.qualified_candidates q WHERE q.company_id=c AND q.environment=env AND q.customer_id=customer AND q.site_id=site AND q.metering_point_id=point AND q.supply_period_id=period AND q.at=p_at LOOP
   candidate:=gridex_brp_sources.candidate_v1(body,(body->>'cutoffAt')::timestamptz,c,env,customer,site,point,p_at,supply,prepared.source_message_id);
   IF candidate IS NULL OR candidate IS DISTINCT FROM prepared.basis THEN CONTINUE;END IF;
   IF NOT(candidate->>'sourceMessageId'=ANY(seen)) THEN seen:=array_append(seen,candidate->>'sourceMessageId');answer:=candidate;END IF;
  END LOOP;
  IF cardinality(seen)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_dated_structural_owner_brp_candidate']);END IF;RETURN answer;
 END IF;
 -- A first production/ordinary supply has no earlier DSO relation. Only an
 -- explicit authenticated same-agreement declaration can supply field262.
 SELECT * INTO contract FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;
 IF contract.id IS NULL OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR (contract.status IN('signed','active')) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_signed_brp_agreement']);END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('contract-brp:'||c::text||':'||ct::text,0));
 SELECT count(*) INTO n FROM gridex_brp_sources.contract_declarations x WHERE x.company_id=c AND x.environment=env AND x.contract_id=ct AND x.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_brp_sources.contract_declarations child WHERE child.previous_declaration_id=x.id AND child.approved_at<=statement_timestamp()) AND NOT EXISTS(SELECT FROM gridex_brp_sources.contract_revocations r WHERE r.declaration_id=x.id);
 IF n<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['unique_authentic_signed_contract_brp_declaration']);END IF;
 SELECT * INTO d FROM gridex_brp_sources.contract_declarations x WHERE x.company_id=c AND x.environment=env AND x.contract_id=ct AND x.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_brp_sources.contract_declarations child WHERE child.previous_declaration_id=x.id AND child.approved_at<=statement_timestamp()) AND NOT EXISTS(SELECT FROM gridex_brp_sources.contract_revocations r WHERE r.declaration_id=x.id) FOR SHARE; IF d.agreement_original IS NULL OR d.source_original IS NULL OR encode(sha256(d.agreement_original),'hex') IS DISTINCT FROM d.agreement_sha256 OR encode(sha256(d.source_original),'hex') IS DISTINCT FROM d.source_sha256 OR gridex_ediel_retention.protected_copy_current_v1(c,d.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['actual_retained_brp_declaration_originals']);END IF;
 IF gridex_brp_declaration_intake.origin_current_v1(c,d.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_authenticated_signed_brp_source_origin']);END IF; SELECT * INTO mp FROM public.metering_points WHERE id=point AND company_id=c FOR SHARE;SELECT * INTO cs FROM public.customer_sites WHERE id=site AND company_id=c FOR SHARE;
 IF d.customer_id IS DISTINCT FROM customer OR d.site_id IS DISTINCT FROM site OR d.metering_point_id IS DISTINCT FROM point OR contract.customer_id IS DISTINCT FROM customer OR contract.metering_point_id IS DISTINCT FROM point OR coalesce(contract.customer_site_id,contract.site_id) IS DISTINCT FROM site OR contract.customer_site_id IS NOT NULL AND contract.customer_site_id IS DISTINCT FROM site OR contract.site_id IS NOT NULL AND contract.site_id IS DISTINCT FROM site
 OR mp.id IS NULL OR cs.id IS NULL OR mp.customer_id IS DISTINCT FROM customer OR cs.customer_id IS DISTINCT FROM customer OR coalesce(mp.customer_site_id,mp.site_id) IS DISTINCT FROM site OR mp.customer_site_id IS NOT NULL AND mp.customer_site_id IS DISTINCT FROM site OR mp.site_id IS NOT NULL AND mp.site_id IS DISTINCT FROM site OR coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,'')) IS DISTINCT FROM d.point_id OR mp.grid_owner_ediel_id IS DISTINCT FROM d.legal_receiver_id OR mp.grid_area_code IS DISTINCT FROM d.grid_area_code
 OR contract.signed_version IS DISTINCT FROM d.contract_revision OR gridex_received_sources.production_contract_hash_v1(contract) IS DISTINCT FROM d.protected_contract_hash OR contract.document_sha256 IS DISTINCT FROM d.agreement_sha256 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_current_signed_brp_agreement_original_and_scope']);END IF;
 network:=gridex_network_registry_sources.network_for_company_v1(c,d.legal_receiver_id,env);registry:=gridex_brp_sources.registry_basis_v1(c,env,d.legal_receiver_id,d.grid_area_code,d.brp_ediel_id,p_at,d.registry_ground_id);
 IF network->>'status' IS DISTINCT FROM 'authorized' OR registry IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authenticated_current_brp_and_network_registry']);END IF;
 header:=gridex_ai_processing.header_company_basis_v1(c,env,d.legal_sender_id,d.legal_receiver_id);IF header->>'legalActorId' IS DISTINCT FROM d.legal_actor_id::text THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_current_legal_supplier_brp_agreement']);END IF;
 RETURN jsonb_build_object('status','authorized','sourceKind','signed_contract_brp_declaration','companyId',c,'environment',env,'contractId',ct,'customerId',customer,'siteId',site,'meteringPointId',point,'at',p_at,'supplyPeriodId',NULL,'brpEdielId',d.brp_ediel_id,'pointId',d.point_id,'identityAgency',d.identity_agency,'legalActorId',d.legal_actor_id,'legalSenderId',d.legal_sender_id,'legalReceiverId',d.legal_receiver_id,'gridArea',d.grid_area_code,'declarationId',d.id,'sourceReference',d.source_reference,'sourceVersion',d.source_version,'sourceDigest',d.source_sha256,'registryBasis',registry);
END$$;

--
-- Name: applied_source_v1(); Type: FUNCTION; Schema: gridex_business_expectations; Owner: -
--

CREATE FUNCTION gridex_business_expectations.applied_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e uuid; original_id uuid; source_environment text;
BEGIN
 IF TG_TABLE_NAME='z02_core_applications' THEN
  original_id:=NEW.originating_z01_message_id;source_environment:=NEW.environment;
 ELSE
  original_id:=NEW.qualified_original_message_id;
  SELECT m.environment INTO source_environment FROM public.ediel_messages m WHERE m.id=NEW.source_message_id AND m.company_id=NEW.company_id;
 END IF;
 IF original_id IS NULL OR source_environment IS NULL THEN RETURN NEW; END IF;
 FOR e IN SELECT b.expectation_id FROM gridex_business_expectations.bindings b
  WHERE b.company_id=NEW.company_id AND b.environment=source_environment AND b.source_message_id=original_id
  ORDER BY b.expectation_id LOOP
  PERFORM gridex_business_expectations.reconcile_v1(e);
 END LOOP;
 RETURN NEW;
END $$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_business_expectations; Owner: -
--

CREATE FUNCTION gridex_business_expectations.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_business_expectation_binding_immutable'; END $$;

--
-- Name: mutate_v1(jsonb); Type: FUNCTION; Schema: gridex_business_expectations; Owner: -
--

CREATE FUNCTION gridex_business_expectations.mutate_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(p_input->>'companyId')::uuid; env text:=p_input->>'environment'; actor uuid:=(p_input->>'actorUserId')::uuid;
 action text:=p_input->>'action'; mid uuid:=(p_input->>'messageId')::uuid; lim integer:=greatest(1,least(coalesce((p_input->>'limit')::integer,100),500));
 m public.ediel_messages%rowtype; a gridex_ediel_transport.attempts%rowtype; b gridex_business_expectations.bindings%rowtype;
 tokens jsonb; plan jsonb; code text; due timestamptz; expected_id uuid; e uuid; offset_value integer; result jsonb;sealed jsonb;sealed_attempt uuid;
BEGIN
 IF c IS NULL OR actor IS NULL OR env IS NULL OR env NOT IN ('test','production') OR action IS NULL OR action NOT IN ('register','read','expire') THEN RAISE EXCEPTION 'ediel_expectation_scope_required'; END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active')
 OR (CASE WHEN action='read' THEN public.gridex_actor_has_company_permission(actor,c,'communication.read') ELSE public.gridex_actor_has_company_permission(actor,c,'ediel.send') OR public.gridex_actor_has_company_permission(actor,c,'communication.send') END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_expectation_actor_not_authorized' USING ERRCODE='42501'; END IF;
 IF action='register' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=env FOR UPDATE;
  IF m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.immutable_rendered_at IS NULL
   OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_expectation_sealed_source_required'; END IF;
  tokens:=gridex_received_sources.wire_tokens_bounded_v1(m.raw_payload,999999);
  IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')
   OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_expectation_physical_source_required'; END IF;
  SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  IF code NOT IN ('Z01','Z13','Z18','Z08') THEN RETURN '[]'::jsonb; END IF;
  IF code='Z08' THEN
   IF gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN RETURN '[]'::jsonb;END IF;
   PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(m);
   IF gridex_supply_rescission.sender_v1(c,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_expectation_h_sender_required' USING ERRCODE='42501';END IF;
  END IF;
  SELECT * INTO b FROM gridex_business_expectations.bindings WHERE source_message_id=mid;
  IF FOUND THEN
   IF b.company_id<>c OR b.environment<>env OR b.source_payload_hash IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'ediel_expectation_source_changed'; END IF;
   PERFORM gridex_business_expectations.reconcile_v1(b.expectation_id);
   IF code='Z08' AND gridex_supply_rescission.sender_v1(c,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_expectation_h_terminal_sender_required' USING ERRCODE='42501';END IF;
   RETURN jsonb_build_array((SELECT to_jsonb(x) FROM public.ediel_business_expectations x WHERE x.id=b.expectation_id));
  END IF;
  SELECT * INTO a FROM gridex_ediel_transport.attempts WHERE message_id=mid AND company_id=c AND environment=env AND classification='accepted' AND observed_at IS NOT NULL AND entered_at IS NOT NULL ORDER BY observed_at,id LIMIT 1;
  IF NOT FOUND AND code='Z08' THEN
   -- The sealed Z08 lane: exactly one accepted, entered provider result.
   sealed:=gridex_ediel_transport.accepted_source_basis_v1(m);
   -- accepted_source_basis_v1 has already verified entry, provider receipt and plan.
   IF sealed->>'status'='accepted_projection' AND sealed->>'lane'='sealed_z08' AND sealed->>'messageId'=mid::text AND sealed->>'observedAt' IS NOT NULL THEN
    sealed_attempt:=(sealed->>'attemptId')::uuid;
    a.id:=NULL;a.observed_at:=(sealed->>'observedAt')::timestamptz;
    a.binding:=jsonb_build_object('originalHash',sealed->>'originalHash','businessExpectationPlan',sealed->'businessExpectationPlan');
   END IF;
  END IF;
  IF a.id IS NULL AND sealed_attempt IS NULL THEN RAISE EXCEPTION 'ediel_expectation_actual_smtp_acceptance_required'; END IF;
  plan:=a.binding->'businessExpectationPlan';
  IF a.binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash OR jsonb_typeof(plan) IS DISTINCT FROM 'object'
   OR plan->>'sourceCode' IS DISTINCT FROM code OR plan->>'version' IS DISTINCT FROM '1' OR plan->>'expectedFamily' IS DISTINCT FROM 'PRODAT'
   OR plan->>'expectedCode' IS DISTINCT FROM (CASE code WHEN 'Z01' THEN 'Z02' WHEN 'Z13' THEN 'Z14' WHEN 'Z18' THEN 'Z15' WHEN 'Z08' THEN 'Z05' END)
   OR plan->>'anchor' IS DISTINCT FROM 'actual_accepted_smtp_observed_at' OR plan->'remoteReceiptKnown' IS DISTINCT FROM 'false'::jsonb
   OR jsonb_typeof(plan#>'{policy,sourceTrace}') IS DISTINCT FROM 'array' OR nullif(plan#>>'{policy,guideRevision}','') IS NULL
   OR nullif(plan#>>'{policy,referenceDate}','') IS NULL THEN RAISE EXCEPTION 'ediel_expectation_prepared_policy_missing'; END IF;
  IF code='Z08' AND plan->'expectedSubtypes' IS DISTINCT FROM '["L"]'::jsonb THEN RAISE EXCEPTION 'ediel_expectation_h_exact_response_required';END IF;
  due:=NULL;
  IF code IN('Z18','Z08') THEN
   IF plan->'offset' IS DISTINCT FROM 'null'::jsonb OR plan->'unit' IS DISTINCT FROM 'null'::jsonb OR plan->>'timerKind' IS DISTINCT FROM 'untimed_business_response' THEN RAISE EXCEPTION 'ediel_expectation_unsupported_timer'; END IF;
  ELSE
   offset_value:=(plan->>'offset')::integer;
   IF offset_value IS NULL OR offset_value<=0 OR plan->>'timerKind' IS DISTINCT FROM 'internal_sender_watch'
    OR jsonb_typeof(plan->'deadlineSource') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_expectation_deadline_authority_missing'; END IF;
   IF plan->>'unit'='minutes' THEN due:=a.observed_at+make_interval(mins=>offset_value);
   ELSIF plan->>'unit'='calendar_days' THEN due:=((a.observed_at AT TIME ZONE 'Europe/Stockholm')+make_interval(days=>offset_value)) AT TIME ZONE 'Europe/Stockholm';
   ELSE RAISE EXCEPTION 'ediel_expectation_timer_unit_invalid'; END IF;
  END IF;
  INSERT INTO public.ediel_business_expectations(company_id,environment,source_message_id,source_operation_id,expected_family,expected_code,expected_subtype,due_at,metadata)
   VALUES(c,env,mid,coalesce(nullif(m.source_operation_id,''),m.operation_id::text,'source_message:'||mid::text),'PRODAT',plan->>'expectedCode',CASE code WHEN 'Z08' THEN 'L' ELSE NULL END,due,
    jsonb_build_object('timerKind',plan->>'timerKind','timerRuleId',plan->'timerRuleId','anchorType','actual_accepted_smtp_observed_at','anchorAt',a.observed_at,
     'remoteReceiptKnown',false,'automaticResendAllowed',false,'preparedPolicy',plan->'policy','transportAttemptId',coalesce(a.id,sealed_attempt))) RETURNING id INTO expected_id;
  INSERT INTO gridex_business_expectations.bindings(expectation_id,company_id,environment,source_message_id,transport_attempt_id,dispatch_attempt_id,source_payload_hash,observed_at,plan)
   VALUES(expected_id,c,env,mid,a.id,sealed_attempt,m.immutable_payload_hash,a.observed_at,plan);
  -- Reconcile after insertion too: a genuine response may have won the race.
  PERFORM gridex_business_expectations.reconcile_v1(expected_id);
  IF code='Z08' AND gridex_supply_rescission.sender_v1(c,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_expectation_h_terminal_sender_required' USING ERRCODE='42501';END IF;
   RETURN jsonb_build_array((SELECT to_jsonb(x) FROM public.ediel_business_expectations x WHERE x.id=expected_id));
 END IF;
 FOR e IN SELECT x.id FROM public.ediel_business_expectations x JOIN gridex_business_expectations.bindings owned ON owned.expectation_id=x.id
  WHERE x.company_id=c AND x.environment=env AND (mid IS NULL OR x.source_message_id=mid)
   AND (action='read' OR x.status='pending' AND x.due_at IS NOT NULL AND x.due_at<=now()) ORDER BY x.created_at,x.id LIMIT lim LOOP
  PERFORM gridex_business_expectations.reconcile_v1(e);
  IF action='expire' THEN UPDATE public.ediel_business_expectations SET status='manual_review',updated_at=now(),metadata=metadata||jsonb_build_object('expiredAt',now(),'remoteReceiptKnown',false,'automaticResendAllowed',false)
   WHERE id=e AND status='pending' AND due_at IS NOT NULL AND due_at<=now(); END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at,x.id),'[]') INTO result FROM
  (SELECT x.* FROM public.ediel_business_expectations x JOIN gridex_business_expectations.bindings owned ON owned.expectation_id=x.id WHERE x.company_id=c AND x.environment=env AND (mid IS NULL OR x.source_message_id=mid) ORDER BY x.created_at,x.id LIMIT lim) x;
 RETURN result;
END $$;

--
-- Name: reconcile_before_supply_rescission_v1(uuid); Type: FUNCTION; Schema: gridex_business_expectations; Owner: -
--

CREATE FUNCTION gridex_business_expectations.reconcile_before_supply_rescission_v1(p_expectation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_business_expectations.bindings%rowtype; e public.ediel_business_expectations%rowtype;
 resolved uuid; decision text; original public.ediel_messages%rowtype; original_wire jsonb;
BEGIN
 SELECT * INTO b FROM gridex_business_expectations.bindings WHERE expectation_id=p_expectation;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO e FROM public.ediel_business_expectations WHERE id=p_expectation AND company_id=b.company_id AND environment=b.environment FOR UPDATE;
 IF NOT FOUND OR e.status NOT IN ('pending','timeout','manual_review') THEN RETURN; END IF;
 IF e.expected_code='Z02' THEN
  SELECT * INTO original FROM public.ediel_messages WHERE id=b.source_message_id AND company_id=b.company_id AND environment=b.environment;
  IF NOT FOUND OR original.immutable_payload_hash IS DISTINCT FROM b.source_payload_hash OR b.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex') THEN RETURN; END IF;
  original_wire:=gridex_received_sources.z02_core_wire_v1(original.raw_payload);
  IF original_wire IS NULL OR jsonb_array_length(original_wire->'objects')=0 OR EXISTS(
   SELECT FROM jsonb_array_elements(original_wire->'objects') own WHERE NOT EXISTS(
    SELECT FROM gridex_received_sources.z02_core_applications tr JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id AND m.environment=tr.environment
    WHERE tr.company_id=b.company_id AND tr.environment=b.environment AND tr.originating_z01_message_id=b.source_message_id
     AND tr.object_id=own->>'objectId' AND tr.identity_agency=own->>'identityAgency'
     AND tr.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'))) THEN RETURN; END IF;
  SELECT tr.source_message_id,'fulfilled' INTO resolved,decision
   FROM gridex_received_sources.z02_core_applications tr JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id AND m.environment=tr.environment
   WHERE tr.company_id=b.company_id AND tr.environment=b.environment AND tr.originating_z01_message_id=b.source_message_id
    AND tr.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND m.direction='inbound'
   ORDER BY tr.applied_at DESC,tr.source_message_id LIMIT 1;
 ELSIF e.expected_code='Z14' THEN
  SELECT tr.source_message_id,CASE WHEN tr.resulting_state->>'status' IN ('rejected_active','rejected_passive_timeout') THEN 'rejected' ELSE 'fulfilled' END INTO resolved,decision
   FROM gridex_received_sources.permission_transitions tr JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id AND m.environment=b.environment
   WHERE tr.company_id=b.company_id AND tr.qualified_original_message_id=b.source_message_id AND tr.qualified_expected_message_code='Z14'
    AND tr.resulting_state->>'inbound_z14_message_id'=tr.source_message_id::text
    AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND m.direction='inbound'
   ORDER BY tr.applied_at,tr.source_message_id LIMIT 1;
 ELSIF e.expected_code='Z15' THEN
  -- The permission source owner supplies exact physical request/result
  -- correlation; a last-outbound pointer alone never qualifies a notice.
  SELECT tr.source_message_id,'fulfilled' INTO resolved,decision
   FROM gridex_received_sources.permission_transitions tr JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id AND m.environment=b.environment
   WHERE tr.company_id=b.company_id AND tr.qualified_original_message_id=b.source_message_id AND tr.qualified_expected_message_code='Z15'
    AND tr.resulting_state->>'inbound_z15_message_id'=tr.source_message_id::text
    AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND m.direction='inbound'
   ORDER BY tr.applied_at,tr.source_message_id LIMIT 1;
 END IF;
 IF resolved IS NOT NULL THEN
  UPDATE public.ediel_business_expectations SET status=decision,fulfilled_by_message_id=resolved,updated_at=now(),
   metadata=metadata||jsonb_build_object('resolvedBy','immutable_applied_business_source','resolvedAt',now()) WHERE id=e.id;
 END IF;
END $$;

--
-- Name: reconcile_v1(uuid); Type: FUNCTION; Schema: gridex_business_expectations; Owner: -
--

CREATE FUNCTION gridex_business_expectations.reconcile_v1(p_expectation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE b gridex_business_expectations.bindings%rowtype;e public.ediel_business_expectations%rowtype;r gridex_supply_rescission.end_receipts%rowtype;original public.ediel_messages%rowtype;BEGIN
 SELECT * INTO b FROM gridex_business_expectations.bindings WHERE expectation_id=p_expectation;
 SELECT * INTO e FROM public.ediel_business_expectations WHERE id=p_expectation AND company_id=b.company_id AND environment=b.environment FOR UPDATE;
 IF e.id IS NULL OR e.expected_code IS DISTINCT FROM 'Z05' OR b.plan->>'sourceCode' IS DISTINCT FROM 'Z08' THEN PERFORM gridex_business_expectations.reconcile_before_supply_rescission_v1(p_expectation);RETURN;END IF;
 IF e.status NOT IN('pending','timeout','manual_review') THEN RETURN;END IF;
 SELECT * INTO original FROM public.ediel_messages WHERE id=b.source_message_id AND company_id=b.company_id AND environment=b.environment;
 IF original.id IS NULL OR b.source_payload_hash IS DISTINCT FROM original.immutable_payload_hash OR b.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex') OR e.expected_subtype IS DISTINCT FROM 'L' OR b.plan->'expectedSubtypes' IS DISTINCT FROM '["L"]'::jsonb THEN RAISE EXCEPTION 'ediel_expectation_h_original_changed';END IF;
 PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(original);
 SELECT receipt.* INTO r FROM gridex_supply_rescission.end_receipts receipt JOIN public.ediel_messages source ON source.id=receipt.source_message_id AND source.company_id=receipt.company_id AND source.environment=receipt.environment
 WHERE receipt.company_id=b.company_id AND receipt.environment=b.environment AND receipt.original_message_id=b.source_message_id AND receipt.original_payload_hash=b.source_payload_hash
 AND receipt.source_payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') AND source.direction='inbound' AND gridex_supply_rescission.recorded_end_current_v1(b.company_id,receipt.source_message_id) IS TRUE;
 IF r.source_message_id IS NULL THEN RETURN;END IF;
 UPDATE public.ediel_business_expectations SET status='fulfilled',fulfilled_by_message_id=r.source_message_id,updated_at=clock_timestamp(),metadata=metadata||jsonb_build_object('resolvedBy','immutable_matched_national_h_end','resolvedAt',clock_timestamp(),'mandateId',r.mandate_id,'sourcePayloadHash',r.source_payload_hash,'originalPayloadHash',r.original_payload_hash,'transitionHash',r.transition_hash) WHERE id=e.id;
END$$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_certificate_trust; Owner: -
--

CREATE FUNCTION gridex_certificate_trust.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_certificate_trust_authority_immutable'; END $$;

--
-- Name: publish_v1(jsonb, bytea, jsonb, text); Type: FUNCTION; Schema: gridex_certificate_trust; Owner: -
--

CREATE FUNCTION gridex_certificate_trust.publish_v1(p_scope jsonb, p_original_register bytea, p_materials jsonb, p_publisher text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result uuid; hash text; actor uuid:=(p_scope->>'actorUserId')::uuid; prior gridex_certificate_trust.authority_versions%rowtype;
BEGIN
 IF p_publisher IS DISTINCT FROM 'gridex_ediel_certificate_authority_owner' OR p_original_register IS NULL OR octet_length(p_original_register)=0 OR octet_length(p_original_register)>16777216
  OR octet_length(p_materials::text)>50331648 THEN RAISE EXCEPTION 'ediel_certificate_trust_qualified_external_owner_required'; END IF;
 IF p_materials IS NULL OR jsonb_typeof(p_materials->'anchors') IS DISTINCT FROM 'array' OR jsonb_typeof(p_materials->'intermediates') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_materials->'crls') IS DISTINCT FROM 'array' OR jsonb_typeof(p_materials->'recipientFingerprints') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'ediel_certificate_trust_public_originals_invalid'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(p_materials->'recipientFingerprints') material WHERE jsonb_typeof(material)<>'string' OR material#>>'{}' !~ '^[a-f0-9]{64}$')
 OR EXISTS(SELECT FROM jsonb_array_elements(p_materials->'anchors'||p_materials->'intermediates'||p_materials->'crls') material
  WHERE jsonb_typeof(material)<>'string' OR length(material#>>'{}') NOT BETWEEN 1 AND 1048576) THEN RAISE EXCEPTION 'ediel_certificate_trust_public_originals_invalid'; END IF;
 IF actor IS NULL OR NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=(p_scope->>'companyId')::uuid AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active')
 OR NOT coalesce(public.gridex_actor_has_company_permission(actor,(p_scope->>'companyId')::uuid,'communication.write'),false) THEN RAISE EXCEPTION 'ediel_certificate_trust_config_actor_not_authorized' USING ERRCODE='42501'; END IF;
 hash:=encode(sha256(p_original_register),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended((p_scope->>'companyId')||'|'||(p_scope->>'environment')||'|'||(p_scope->>'receiverEdielId')||'|'||(p_scope->>'registerVersion'),0));
 SELECT * INTO prior FROM gridex_certificate_trust.authority_versions WHERE company_id=(p_scope->>'companyId')::uuid AND environment=p_scope->>'environment'
  AND receiver_ediel_id=p_scope->>'receiverEdielId' AND register_version=p_scope->>'registerVersion';
 IF FOUND THEN
  IF prior.original_sha256<>hash OR prior.recipient_fingerprints IS DISTINCT FROM p_materials->'recipientFingerprints' OR prior.anchors IS DISTINCT FROM p_materials->'anchors' OR prior.intermediates IS DISTINCT FROM p_materials->'intermediates' OR prior.crls IS DISTINCT FROM p_materials->'crls'
   OR prior.original_reference IS DISTINCT FROM p_scope->>'originalReference' OR prior.legal_authority_reference IS DISTINCT FROM p_scope->>'legalAuthorityReference'
   OR prior.process_authority_reference IS DISTINCT FROM p_scope->>'processAuthorityReference' OR prior.owner_register_reference IS DISTINCT FROM p_scope->>'ownerRegisterReference'
   OR prior.valid_from IS DISTINCT FROM (p_scope->>'validFrom')::timestamptz OR prior.valid_to IS DISTINCT FROM (p_scope->>'validTo')::timestamptz THEN RAISE EXCEPTION 'ediel_certificate_trust_version_conflict'; END IF;
  RETURN prior.id;
 END IF;
 INSERT INTO gridex_certificate_trust.authority_versions(company_id,environment,receiver_ediel_id,register_version,original_reference,original_sha256,
  legal_authority_reference,process_authority_reference,owner_register_reference,valid_from,valid_to,recipient_fingerprints,anchors,intermediates,crls,publisher_role)
 VALUES((p_scope->>'companyId')::uuid,p_scope->>'environment',p_scope->>'receiverEdielId',p_scope->>'registerVersion',p_scope->>'originalReference',hash,
  p_scope->>'legalAuthorityReference',p_scope->>'processAuthorityReference',p_scope->>'ownerRegisterReference',(p_scope->>'validFrom')::timestamptz,(p_scope->>'validTo')::timestamptz,
  p_materials->'recipientFingerprints',p_materials->'anchors',p_materials->'intermediates',p_materials->'crls',p_publisher) RETURNING id INTO result;
 RETURN result;
END $_$;

--
-- Name: read_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_certificate_trust; Owner: -
--

CREATE FUNCTION gridex_certificate_trust.read_v1(p_company_id uuid, p_environment text, p_receiver_ediel_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_certificate_trust.authority_versions%rowtype; count_versions integer;
BEGIN
 IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production') OR nullif(btrim(p_receiver_ediel_id),'') IS NULL THEN RAISE EXCEPTION 'ediel_certificate_trust_scope_required'; END IF;
 SELECT count(*) INTO count_versions FROM gridex_certificate_trust.authority_versions WHERE company_id=p_company_id AND environment=p_environment
  AND receiver_ediel_id=p_receiver_ediel_id AND valid_from<=now() AND valid_to>now();
 IF count_versions=0 THEN RETURN NULL; END IF;
 IF count_versions<>1 THEN RAISE EXCEPTION 'ediel_certificate_trust_authority_versions_overlap'; END IF;
 SELECT * INTO STRICT a FROM gridex_certificate_trust.authority_versions WHERE company_id=p_company_id AND environment=p_environment AND receiver_ediel_id=p_receiver_ediel_id AND valid_from<=now() AND valid_to>now();
 RETURN jsonb_build_object('registrationId',a.id,'companyId',a.company_id,'environment',a.environment,'receiverEdielId',a.receiver_ediel_id,
  'registerVersion',a.register_version,'originalReference',a.original_reference,'originalSha256',a.original_sha256,
  'authorizationReference',a.legal_authority_reference||'|'||a.process_authority_reference||'|'||a.owner_register_reference,
  'validFrom',a.valid_from,'validTo',a.valid_to,'recipientFingerprints',a.recipient_fingerprints,'anchors',a.anchors,'intermediates',a.intermediates,'crls',a.crls);
END $$;

--
-- Name: actor_v1(uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.actor_v1(c uuid, a uuid, mode text, k text, session_bound boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE wanted text;
BEGIN
 PERFORM gridex_contract_source_intake.lock_graph_v1();PERFORM id FROM auth.users WHERE id=a FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=a FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=a FOR SHARE;
 IF (session_bound AND auth.uid() IS DISTINCT FROM a) OR mode NOT IN('archive','read','review') OR NOT EXISTS(SELECT FROM gridex_contract_source_intake.kinds WHERE kind=k)
 OR NOT EXISTS(SELECT FROM auth.users WHERE id=a AND deleted_at IS NULL AND(banned_until IS NULL OR banned_until<=clock_timestamp())) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=a AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=a AND status='active' AND is_active AND accepted_at IS NOT NULL) OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active') THEN RAISE EXCEPTION 'contract_intake_current_actor_required' USING ERRCODE='42501';END IF;
 FOREACH wanted IN ARRAY CASE WHEN mode='read' THEN ARRAY['communication.read','customers.read','contracts.read'] ELSE ARRAY['communication.write','customers.write','contracts.write'] END LOOP
  IF public.gridex_actor_has_company_permission(a,c,wanted) IS NOT TRUE OR gridex_requested_changes.scoped_permission_v1(c,a,wanted) IS NOT TRUE THEN RAISE EXCEPTION 'contract_intake_current_explicit_permission_required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF k IN('contract_requested_method','metering_method_event') THEN
  wanted:=CASE mode WHEN 'read' THEN 'metering.read' ELSE 'metering.write' END;
  IF public.gridex_actor_has_company_permission(a,c,wanted) IS NOT TRUE OR gridex_requested_changes.scoped_permission_v1(c,a,wanted) IS NOT TRUE THEN RAISE EXCEPTION 'contract_intake_current_metering_permission_required' USING ERRCODE='42501';END IF;
 END IF;
 IF mode='review' AND(public.gridex_actor_has_company_permission(a,c,'ediel.source.review') IS NOT TRUE OR gridex_requested_changes.scoped_permission_v1(c,a,'ediel.source.review') IS NOT TRUE) THEN RAISE EXCEPTION 'contract_intake_current_reviewer_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_contract_source_intake; Owner: -
--

CREATE TABLE gridex_contract_source_intake.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    kind text NOT NULL,
    target_id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_id uuid NOT NULL,
    contract_document_id uuid NOT NULL,
    native_scope jsonb NOT NULL,
    claims jsonb NOT NULL,
    agreement_original bytea,
    agreement_sha256 text NOT NULL,
    source_original bytea,
    source_sha256 text NOT NULL,
    claims_hash text NOT NULL,
    issuer_key_id uuid,
    representation_id uuid,
    signature_hex text,
    submitted_by uuid NOT NULL,
    captured_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_agreement_sha256_check CHECK ((agreement_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_check CHECK ((claims_hash = encode(sha256(convert_to((claims)::text, 'UTF8'::name)), 'hex'::text))),
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_signature_hex_check CHECK ((signature_hex ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_source_sha256_check CHECK ((source_sha256 ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_contract_source_intake.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: claims_valid_v1(gridex_contract_source_intake.artifacts); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.claims_valid_v1(a gridex_contract_source_intake.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE p jsonb:=a.claims;s jsonb;previous uuid;boundary timestamptz;kind text;tuple jsonb;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR nullif(p->>'sourceReference','') IS NULL OR nullif(p->>'sourceVersion','') IS NULL THEN RETURN false;END IF;
 IF a.kind='masterdata_declaration' THEN
  RETURN (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p)x)=ARRAY['customerIdentity','endUserMasterdata','sourceReference','sourceVersion','validFrom','validTo']::text[]
  AND gridex_customer_masterdata.identity_v1(p->'customerIdentity') IS TRUE AND gridex_customer_masterdata.literal_masterdata_v1(p->'endUserMasterdata') IS TRUE
  AND isfinite((p->>'validFrom')::timestamptz) AND (p->>'validFrom')::timestamptz<=clock_timestamp() AND (p->>'validTo' IS NULL OR isfinite((p->>'validTo')::timestamptz) AND(p->>'validTo')::timestamptz>(p->>'validFrom')::timestamptz);
 ELSIF a.kind='contract_requested_method' THEN
  previous:=(p->>'previousDeclarationId')::uuid;
  RETURN (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p)x)=ARRAY['previousDeclarationId','requestedMethod','sourceReference','sourceVersion']::text[]
  AND gridex_metering_method_changes.requested_method_supported_v1(p->>'requestedMethod') IS TRUE
  AND(previous IS NULL OR EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_declarations d WHERE id=previous AND company_id=a.company_id AND environment=a.environment AND contract_id=a.contract_id AND gridex_ediel_retention.contract_copy_source_current_v1(a.company_id,'gridex_metering_method_changes','contract_request_declarations',d.id) IS TRUE));
 ELSIF a.kind='metering_method_event' THEN
  boundary:=(p->>'effectiveAt')::timestamptz;tuple:=gridex_metering_method_changes.canonical_tuple_projection_v1()->(p->>'subtype');
  s:=gridex_received_sources.supply_period_source_at_v1(a.company_id,(p->>'supplyPeriodId')::uuid,boundary);
  RETURN (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p)x)=ARRAY['effectiveAt','requestedMethodDeclarationId','sourceReference','sourceVersion','subtype','supplyPeriodId']::text[]
  AND isfinite(boundary) AND extract(second FROM boundary)=0 AND tuple IS NOT NULL AND s->>'qualified'='true'
  AND s->>'customerId'=a.native_scope->>'customerId' AND s->>'meteringPointId'=a.native_scope->>'meteringPointId' AND s->>'siteId'=a.native_scope->>'siteId' AND s->>'legalActorId'=a.native_scope->>'legalActorId' AND s->>'dsoEdielId'=a.native_scope->>'legalReceiverId'
  AND(SELECT count(*) FROM jsonb_array_elements(s->'sourceObjects') own WHERE own->>'point'=a.native_scope->>'pointId' AND own->>'identityAgency'=a.native_scope->>'identityAgency' AND own->>'gridArea'=a.native_scope->>'gridArea')=1
  AND EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_declarations d WHERE id=(p->>'requestedMethodDeclarationId')::uuid AND company_id=a.company_id AND environment=a.environment AND contract_id=a.contract_id AND requested_method=tuple->>'method' AND gridex_ediel_retention.contract_copy_source_current_v1(a.company_id,'gridex_metering_method_changes','contract_request_declarations',d.id) IS TRUE);
 ELSIF a.kind='production_contract_event' THEN
  boundary:=(p->>'boundaryAt')::timestamptz;kind:=p->>'eventKind';previous:=(p->>'startEventId')::uuid;
  RETURN (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p)x)=ARRAY['boundaryAt','contractReference','eventKind','sourceReference','sourceVersion','startEventId']::text[]
  AND isfinite(boundary) AND extract(second FROM boundary)=0 AND nullif(p->>'contractReference','') IS NOT NULL
  AND(kind='signed' AND previous IS NULL OR kind='ceased' AND EXISTS(SELECT FROM gridex_received_sources.production_contract_events e WHERE id=previous AND company_id=a.company_id AND environment=a.environment AND contract_id=a.contract_id AND customer_id=(a.native_scope->>'customerId')::uuid AND metering_point_id=(a.native_scope->>'meteringPointId')::uuid AND legal_actor_id=(a.native_scope->>'legalActorId')::uuid AND legal_receiver_id=a.native_scope->>'legalReceiverId' AND event_kind='signed' AND boundary_at<boundary AND NOT EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations WHERE event_id=e.id)));
 END IF;RETURN false;
 EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END$$;

--
-- Name: current_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.current_v1(c uuid, k text, target uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE terminal_current boolean;a gridex_contract_source_intake.artifacts%rowtype;q gridex_contract_source_intake.qualifications%rowtype;r gridex_contract_source_intake.reviews%rowtype;scope jsonb;source jsonb;spec gridex_contract_source_intake.kinds%rowtype;
BEGIN
 PERFORM gridex_contract_source_intake.lock_graph_v1();SELECT * INTO q FROM gridex_contract_source_intake.qualifications WHERE target_id=target AND company_id=c AND kind=k FOR SHARE;
 IF q.artifact_id IS NULL THEN RETURN false;END IF;
 SELECT * INTO a FROM gridex_contract_source_intake.artifacts WHERE id=q.artifact_id AND company_id=c;IF a.id IS NULL THEN RETURN false;END IF;
 PERFORM id FROM public.customer_contracts WHERE id=a.contract_id AND company_id=c FOR SHARE;
 SELECT * INTO STRICT a FROM gridex_contract_source_intake.artifacts WHERE id=q.artifact_id AND company_id=c FOR SHARE;
 SELECT * INTO r FROM gridex_contract_source_intake.reviews WHERE id=q.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 IF r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id IS DISTINCT FROM q.approved_by OR r.actor_user_id=a.submitted_by OR q.approved_at>clock_timestamp() THEN RETURN false;END IF;
 BEGIN
  PERFORM gridex_contract_source_intake.actor_v1(c,r.actor_user_id,'review',k,false);
  scope:=gridex_contract_source_intake.scope_v1(c,a.contract_id,a.environment,k);
 EXCEPTION WHEN insufficient_privilege OR raise_exception THEN RETURN false;END;
 IF scope IS DISTINCT FROM a.native_scope OR gridex_contract_source_intake.receipt_v1(a) IS NULL OR gridex_contract_source_intake.claims_valid_v1(a) IS NOT TRUE OR gridex_ediel_retention.protected_copy_current_v1(c,a.id) IS NOT TRUE THEN RETURN false;END IF;
 SELECT * INTO STRICT spec FROM gridex_contract_source_intake.kinds WHERE kind=k;
 EXECUTE format('SELECT to_jsonb(r) FROM %I.%I r WHERE id=$1 AND company_id=$2 FOR SHARE',spec.source_schema,spec.source_table) INTO source USING target,c;
 terminal_current:=source IS NOT NULL AND encode(sha256(convert_to(source::text,'UTF8')),'hex')=q.row_hash; IF terminal_current THEN BEGIN PERFORM gridex_contract_source_intake.actor_v1(c,r.actor_user_id,'review',k,false); EXCEPTION WHEN insufficient_privilege OR raise_exception THEN RETURN false;END;END IF; RETURN terminal_current;
END$_$;

--
-- Name: lock_graph_v1(); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.lock_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE gridex_contract_source_intake.issuer_keys,gridex_contract_source_intake.representations,gridex_contract_source_intake.revocations IN SHARE MODE;
END$$;

--
-- Name: lock_target_contract_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.lock_target_contract_v1(c uuid, k text, target uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_contract_source_intake.lock_graph_v1();
 -- Qualification links are immutable. No source-row lock is taken to discover
 -- its contract; another transaction can only publish a new qualification.
 PERFORM ct.id FROM public.customer_contracts ct JOIN gridex_contract_source_intake.artifacts a ON a.contract_id=ct.id AND a.company_id=ct.company_id
 JOIN gridex_contract_source_intake.qualifications q ON q.artifact_id=a.id AND q.company_id=a.company_id AND q.kind=a.kind
 WHERE q.company_id=c AND q.kind=k AND q.target_id=target ORDER BY ct.id FOR SHARE OF ct;
END$$;

--
-- Name: materialize_v1(gridex_contract_source_intake.artifacts, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.materialize_v1(a gridex_contract_source_intake.artifacts, actor uuid, at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE p jsonb:=a.claims;s jsonb:=a.native_scope;supply jsonb;row jsonb;k gridex_contract_source_intake.kinds%rowtype;
BEGIN
 IF a.kind='masterdata_declaration' THEN
  INSERT INTO gridex_customer_masterdata.signed_declarations(id,company_id,customer_id,environment,contract_id,contract_revision,contract_hash,agreement_original,agreement_sha256,valid_from,valid_to,customer_identity,end_user_masterdata,source_reference,source_version,source_original,source_sha256,approved_by,approved_at)
  VALUES(a.target_id,a.company_id,(s->>'customerId')::uuid,a.environment,a.contract_id,s->>'contractRevision',s->>'protectedContractHash',a.agreement_original,a.agreement_sha256,(p->>'validFrom')::timestamptz,(p->>'validTo')::timestamptz,p->'customerIdentity',p->'endUserMasterdata',p->>'sourceReference',p->>'sourceVersion',a.source_original,a.source_sha256,actor,at);
 ELSIF a.kind='contract_requested_method' THEN
  INSERT INTO gridex_metering_method_changes.contract_request_declarations(id,previous_declaration_id,company_id,environment,contract_id,contract_revision,protected_contract_hash,customer_id,site_id,metering_point_id,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,requested_method,agreement_original,agreement_sha256,source_reference,source_version,source_original,source_sha256,approved_by,approved_at)
  VALUES(a.target_id,(p->>'previousDeclarationId')::uuid,a.company_id,a.environment,a.contract_id,s->>'contractRevision',s->>'protectedContractHash',(s->>'customerId')::uuid,(s->>'siteId')::uuid,(s->>'meteringPointId')::uuid,(s->>'legalActorId')::uuid,s->>'legalSenderId',s->>'legalReceiverId',s->>'pointId',s->>'identityAgency',s->>'gridArea',p->>'requestedMethod',a.agreement_original,a.agreement_sha256,p->>'sourceReference',p->>'sourceVersion',a.source_original,a.source_sha256,actor,at);
 ELSIF a.kind='metering_method_event' THEN
  supply:=gridex_received_sources.supply_period_source_at_v1(a.company_id,(p->>'supplyPeriodId')::uuid,(p->>'effectiveAt')::timestamptz);
  INSERT INTO gridex_metering_method_changes.events(id,company_id,environment,supply_period_id,customer_id,metering_point_id,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,supply_source_message_id,supply_state_version,subtype,effective_at,contract_id,contract_revision,protected_contract_hash,agreement_original,agreement_sha256,source_reference,source_original,source_sha256,source_version,approved_by,approved_at,requested_method_declaration_id)
  VALUES(a.target_id,a.company_id,a.environment,(p->>'supplyPeriodId')::uuid,(s->>'customerId')::uuid,(s->>'meteringPointId')::uuid,(s->>'legalActorId')::uuid,s->>'legalSenderId',s->>'legalReceiverId',s->>'pointId',s->>'identityAgency',s->>'gridArea',(supply->>'sourceMessageId')::uuid,(supply->>'marketStateVersion')::bigint,p->>'subtype',(p->>'effectiveAt')::timestamptz,a.contract_id,s->>'contractRevision',s->>'protectedContractHash',a.agreement_original,a.agreement_sha256,p->>'sourceReference',a.source_original,a.source_sha256,p->>'sourceVersion',actor,at,(p->>'requestedMethodDeclarationId')::uuid);
 ELSIF a.kind='production_contract_event' THEN
  INSERT INTO gridex_received_sources.production_contract_events(id,company_id,environment,contract_id,customer_id,metering_point_id,legal_actor_id,dso_actor_id,dso_registry_version,dso_registry_sha256,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,event_kind,boundary_at,start_event_id,contract_reference,contract_revision,protected_contract_hash,source_reference,source_sha256,source_version,approved_by,approved_at)
  VALUES(a.target_id,a.company_id,a.environment,a.contract_id,(s->>'customerId')::uuid,(s->>'meteringPointId')::uuid,(s->>'legalActorId')::uuid,(s->'networkBasis'->>'networkActorId')::uuid,s->'networkBasis'->>'registryVersion',s->'networkBasis'->>'sourceSha256',s->>'legalSenderId',s->>'legalReceiverId',s->>'pointId',s->>'identityAgency',s->>'gridArea',p->>'eventKind',(p->>'boundaryAt')::timestamptz,(p->>'startEventId')::uuid,p->>'contractReference',s->>'contractRevision',s->>'protectedContractHash',p->>'sourceReference',a.source_sha256,p->>'sourceVersion',actor,at);
 ELSE RAISE EXCEPTION 'contract_intake_exact_native_kind_required';END IF;
 SELECT * INTO STRICT k FROM gridex_contract_source_intake.kinds WHERE kind=a.kind;
 EXECUTE format('SELECT to_jsonb(r) FROM %I.%I r WHERE id=$1 AND company_id=$2',k.source_schema,k.source_table) INTO STRICT row USING a.target_id,a.company_id;
 RETURN encode(sha256(convert_to(row::text,'UTF8')),'hex');
END$_$;

--
-- Name: original_guard_v1(); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 IF TG_OP='UPDATE' AND(gridex_ediel_retention.protected_copy_transition_v1('contract_intake_agreement_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE OR gridex_ediel_retention.protected_copy_transition_v1('contract_intake_source_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE) THEN RETURN NEW;END IF;RAISE EXCEPTION 'contract_intake_original_is_immutable';END$$;

--
-- Name: receipt_v1(gridex_contract_source_intake.artifacts); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.receipt_v1(a gridex_contract_source_intake.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE key gridex_contract_source_intake.issuer_keys%rowtype;rep gridex_contract_source_intake.representations%rowtype;p jsonb;at timestamptz;issued timestamptz;expires timestamptz;purpose text;
BEGIN
 IF a.source_original IS NULL OR a.agreement_original IS NULL OR encode(sha256(a.source_original),'hex') IS DISTINCT FROM a.source_sha256 OR encode(sha256(a.agreement_original),'hex') IS DISTINCT FROM a.agreement_sha256 OR a.signature_hex IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO key FROM gridex_contract_source_intake.issuer_keys WHERE id=a.issuer_key_id AND company_id=a.company_id AND environment=a.environment FOR SHARE;
 SELECT * INTO rep FROM gridex_contract_source_intake.representations WHERE id=a.representation_id AND issuer_key_id=key.id AND company_id=a.company_id AND environment=a.environment AND kind=a.kind AND legal_actor_id=(a.native_scope->>'legalActorId')::uuid FOR SHARE;at:=clock_timestamp();
 IF key.id IS NULL OR rep.id IS NULL OR key.valid_from>at OR key.valid_to<=at OR rep.valid_from>at OR rep.valid_to<=at
 OR EXISTS(SELECT FROM gridex_contract_source_intake.revocations WHERE target_kind='key' AND target_id=key.id OR target_kind='representation' AND target_id=rep.id OR target_kind='artifact' AND target_id=a.id)
 OR encode(gridex_requested_changes.receipt_hmac_sha256_v1(a.source_original,key.signing_key),'hex') IS DISTINCT FROM a.signature_hex THEN RETURN NULL;END IF;
 p:=convert_from(a.source_original,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;SELECT kinds.purpose INTO STRICT purpose FROM gridex_contract_source_intake.kinds WHERE kind=a.kind;
 IF (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p)x) IS DISTINCT FROM ARRAY['agreementHash','claims','expiresAt','format','issuedAt','issuerCode','legalAuthorityReference','nativeScope','purpose','receiptId','representationReference']::text[]
 OR p->>'format' IS DISTINCT FROM 'ediel_contract_original_source_v1' OR p->>'purpose' IS DISTINCT FROM purpose OR p->>'issuerCode' IS DISTINCT FROM key.issuer_code OR p->>'legalAuthorityReference' IS DISTINCT FROM key.legal_authority_reference OR p->>'representationReference' IS DISTINCT FROM rep.legal_representation_reference
 OR p->'nativeScope' IS DISTINCT FROM a.native_scope OR p->>'agreementHash' IS DISTINCT FROM a.agreement_sha256 OR p->'claims' IS DISTINCT FROM a.claims OR nullif(p->>'receiptId','') IS NULL
 OR isfinite(issued) IS NOT TRUE OR isfinite(expires) IS NOT TRUE OR expires<=issued OR issued>a.captured_at OR issued>at OR expires<=at OR issued<greatest(key.valid_from,rep.valid_from) OR expires>least(key.valid_to,rep.valid_to) THEN RETURN NULL;END IF;
 RETURN p;
 EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$$;

--
-- Name: scope_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.scope_v1(c uuid, ct uuid, env text, k text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE contract public.customer_contracts%rowtype;doc public.customer_contract_documents%rowtype;point public.metering_points%rowtype;site public.customer_sites%rowtype;header jsonb;network jsonb;legal_id text;id_count bigint;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF (env IN('test','production')) IS NOT TRUE OR NOT EXISTS(SELECT FROM gridex_contract_source_intake.kinds WHERE kind=k) THEN RAISE EXCEPTION 'contract_intake_scope_kind_environment_required';END IF;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=contract.metering_point_id AND company_id=c FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(contract.customer_site_id,contract.site_id) AND company_id=c FOR SHARE;
 IF contract.id IS NULL OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR contract.signed_at>clock_timestamp() OR nullif(contract.signed_version,'') IS NULL OR contract.signature_snapshot IS NULL
 OR contract.signature_snapshot->>'company_id' IS DISTINCT FROM c::text OR contract.signature_snapshot->>'customer_id' IS DISTINCT FROM contract.customer_id::text OR contract.signature_snapshot->>'contract_id' IS DISTINCT FROM contract.id::text
 OR contract.signature_snapshot_sha256 IS DISTINCT FROM encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex') OR point.id IS NULL OR site.id IS NULL OR point.customer_id IS DISTINCT FROM contract.customer_id OR site.customer_id IS DISTINCT FROM contract.customer_id
 OR coalesce(point.customer_site_id,point.site_id) IS DISTINCT FROM site.id OR(contract.customer_site_id IS NOT NULL AND contract.customer_site_id<>site.id) OR(contract.site_id IS NOT NULL AND contract.site_id<>site.id)
 OR NOT EXISTS(SELECT FROM public.customers WHERE id=contract.customer_id AND company_id=c) THEN RAISE EXCEPTION 'contract_intake_actual_signed_contract_tuple_required';END IF;
 PERFORM public.ediel_require_contract_records_available_v1(c,contract.id);
 SELECT * INTO doc FROM public.customer_contract_documents WHERE company_id=c AND customer_contract_id=ct AND document_type='signed_contract_pdf' AND document_sha256=contract.document_sha256 AND verified_at IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
 IF doc.id IS NULL OR doc.mime_type IS DISTINCT FROM 'application/pdf' OR doc.verified_at>clock_timestamp() OR doc.storage_bucket IS DISTINCT FROM 'customer-contract-documents' OR nullif(doc.storage_path,'') IS NULL OR NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id=doc.storage_bucket AND name=doc.storage_path) THEN RAISE EXCEPTION 'contract_intake_actual_signed_pdf_custody_required';END IF;
 network:=gridex_network_registry_sources.network_for_company_v1(c,point.grid_owner_ediel_id,env);
 IF coalesce(nullif(point.ediel_metering_point_id,''),nullif(point.meter_point_id,'')) !~ '^[0-9]{18}$' OR nullif(point.grid_area_code,'') IS NULL OR network->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'contract_intake_current_company_network_source_required';END IF;
 SELECT count(DISTINCT (actor_id,identifier_value)),min(identifier_value) INTO id_count,legal_id FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR valid_to>clock_timestamp());
 IF id_count<>1 THEN RAISE EXCEPTION 'contract_intake_unique_legal_supplier_required';END IF;
 header:=gridex_ai_processing.header_company_basis_v1(c,env,legal_id,point.grid_owner_ediel_id);
 IF nullif(header->>'legalActorId','') IS NULL OR header->>'legalSupplier' IS DISTINCT FROM legal_id OR header->>'companyId' IS DISTINCT FROM c::text OR header->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'contract_intake_current_legal_supplier_required';END IF;
 IF k='production_contract_event' AND point.product_direction IS DISTINCT FROM 'production' THEN RAISE EXCEPTION 'contract_intake_actual_production_point_required';END IF;
 RETURN jsonb_build_object('companyId',c,'environment',env,'kind',k,'contractId',ct,'contractRevision',contract.signed_version,'protectedContractHash',gridex_received_sources.production_contract_hash_v1(contract),'signatureHash',contract.signature_snapshot_sha256,
 'contractDocumentId',doc.id,'agreementHash',doc.document_sha256,'storageBucket',doc.storage_bucket,'storagePath',doc.storage_path,'customerId',contract.customer_id,'siteId',site.id,'meteringPointId',point.id,'pointId',coalesce(nullif(point.ediel_metering_point_id,''),nullif(point.meter_point_id,'')),
 'identityAgency','9','gridArea',point.grid_area_code,'legalActorId',header->>'legalActorId','legalSenderId',legal_id,'legalReceiverId',point.grid_owner_ediel_id,'networkBasis',network->'basis');
END$_$;

--
-- Name: terminal_archive_body_v1(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.terminal_archive_body_v1(p_company_id uuid, p_actor_user_id uuid, p_contract_id uuid, p_environment text, p_kind text, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE scope jsonb;pdf bytea;original bytea;packet jsonb;artifact gridex_contract_source_intake.artifacts%rowtype;missing text[]:=ARRAY[]::text[];
BEGIN
 PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'archive',p_kind);
 scope:=gridex_contract_source_intake.scope_v1(p_company_id,p_contract_id,p_environment,p_kind);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-original-intake:'||p_company_id::text||':'||p_contract_id::text,0));
 IF (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p_submission)x) IS DISTINCT FROM ARRAY['agreementBase64','issuerKeyId','representationId','signatureHex','sourceBase64']::text[] THEN RAISE EXCEPTION 'contract_intake_exact_submission_required';END IF;
 pdf:=decode(p_submission->>'agreementBase64','base64');original:=decode(p_submission->>'sourceBase64','base64');packet:=convert_from(original,'UTF8')::jsonb;
 IF octet_length(pdf) NOT BETWEEN 1 AND 10485760 OR octet_length(original) NOT BETWEEN 1 AND 10485760 OR encode(sha256(pdf),'hex') IS DISTINCT FROM scope->>'agreementHash' OR jsonb_typeof(packet->'claims') IS DISTINCT FROM 'object'
 OR replace(encode(pdf,'base64'),E'\n','') IS DISTINCT FROM p_submission->>'agreementBase64' OR replace(encode(original,'base64'),E'\n','') IS DISTINCT FROM p_submission->>'sourceBase64' THEN RAISE EXCEPTION 'contract_intake_actual_immutable_original_bytes_required';END IF;
 SELECT * INTO artifact FROM gridex_contract_source_intake.artifacts WHERE company_id=p_company_id AND environment=p_environment AND kind=p_kind AND contract_id=p_contract_id AND source_sha256=encode(sha256(original),'hex') FOR UPDATE;
 IF artifact.id IS NULL THEN
  INSERT INTO gridex_contract_source_intake.artifacts(company_id,environment,kind,contract_id,contract_document_id,native_scope,claims,agreement_original,agreement_sha256,source_original,source_sha256,claims_hash,issuer_key_id,representation_id,signature_hex,submitted_by)
  VALUES(p_company_id,p_environment,p_kind,p_contract_id,(scope->>'contractDocumentId')::uuid,scope,packet->'claims',pdf,encode(sha256(pdf),'hex'),original,encode(sha256(original),'hex'),encode(sha256(convert_to((packet->'claims')::text,'UTF8')),'hex'),(p_submission->>'issuerKeyId')::uuid,(p_submission->>'representationId')::uuid,p_submission->>'signatureHex',p_actor_user_id) RETURNING * INTO artifact;
  INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_contract_source',artifact.id,'ediel.contract_original.archived',jsonb_build_object('kind',p_kind,'contractId',p_contract_id,'sourceHash',artifact.source_sha256,'agreementHash',artifact.agreement_sha256,'claimsHash',artifact.claims_hash));
 ELSE
  IF artifact.native_scope IS DISTINCT FROM scope OR artifact.agreement_sha256 IS DISTINCT FROM encode(sha256(pdf),'hex') OR artifact.issuer_key_id IS DISTINCT FROM(p_submission->>'issuerKeyId')::uuid OR artifact.representation_id IS DISTINCT FROM(p_submission->>'representationId')::uuid OR artifact.signature_hex IS DISTINCT FROM p_submission->>'signatureHex' THEN RAISE EXCEPTION 'contract_intake_idempotency_scope_conflict';END IF;
 END IF;
 IF gridex_contract_source_intake.receipt_v1(artifact) IS NULL THEN missing:=array_append(missing,'current_authentic_issuer_receipt_and_legal_representation');END IF;
 IF gridex_contract_source_intake.claims_valid_v1(artifact) IS NOT TRUE THEN missing:=array_append(missing,'exact_signed_native_domain_claims');END IF;
 PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'archive',p_kind);
 RETURN jsonb_build_object('status','archived','artifactId',artifact.id,'kind',artifact.kind,'sourceHash',artifact.source_sha256,'agreementHash',artifact.agreement_sha256,'claimsHash',artifact.claims_hash,'missing',missing||ARRAY['independent_current_source_review']);
END$$;

--
-- Name: terminal_list_body_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.terminal_list_body_v1(p_company_id uuid, p_actor_user_id uuid, p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$DECLARE row record;items jsonb:='[]'::jsonb;BEGIN
 -- Authorize even an empty list; selectors are never an authorization assertion.
 PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'read','masterdata_declaration');
 IF NOT EXISTS(SELECT FROM public.customer_contracts WHERE id=p_contract_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'contract_intake_contract_scope_required';END IF;
 FOR row IN SELECT id FROM gridex_contract_source_intake.artifacts WHERE company_id=p_company_id AND contract_id=p_contract_id ORDER BY captured_at DESC,id DESC LIMIT 100 LOOP items:=items||jsonb_build_array(public.ediel_read_contract_original_source_v1(p_company_id,p_actor_user_id,row.id));END LOOP;RETURN items;
END$$;

--
-- Name: terminal_read_body_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.terminal_read_body_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_contract_source_intake.artifacts%rowtype;q gridex_contract_source_intake.qualifications%rowtype;r gridex_contract_source_intake.reviews%rowtype;current boolean:=false;
BEGIN
 SELECT * INTO a FROM gridex_contract_source_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;IF a.id IS NULL THEN RAISE EXCEPTION 'contract_intake_artifact_scope_required';END IF;
 PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'read',a.kind);
 SELECT * INTO q FROM gridex_contract_source_intake.qualifications WHERE artifact_id=a.id;
 SELECT * INTO r FROM gridex_contract_source_intake.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;
 IF q.artifact_id IS NOT NULL THEN current:=gridex_contract_source_intake.current_v1(p_company_id,a.kind,q.target_id);END IF;
 RETURN jsonb_build_object('status',CASE WHEN current THEN 'authorized' WHEN q.artifact_id IS NOT NULL THEN 'held' WHEN r.outcome='rejected' THEN 'rejected' WHEN r.id IS NOT NULL THEN 'held' ELSE 'archived' END,'artifactId',a.id,'kind',a.kind,'contractId',a.contract_id,'environment',a.environment,'sourceHash',a.source_sha256,'agreementHash',a.agreement_sha256,'claimsHash',a.claims_hash,'nativeScope',a.native_scope,'claims',a.claims,'submittedBy',a.submitted_by,'capturedAt',a.captured_at,'sourceId',CASE WHEN current THEN q.target_id ELSE NULL END,'missing',CASE WHEN current THEN '[]'::jsonb WHEN q.artifact_id IS NOT NULL THEN '["current_qualified_contract_original"]'::jsonb ELSE coalesce(r.missing,'["independent_current_source_review"]'::jsonb) END);
END$$;

--
-- Name: terminal_review_body_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.terminal_review_body_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_contract_source_intake.artifacts%rowtype;r gridex_contract_source_intake.reviews%rowtype;q gridex_contract_source_intake.qualifications%rowtype;missing text[]:=ARRAY[]::text[];outcome text;row_hash text;scope jsonb;at timestamptz;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO a FROM gridex_contract_source_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 IF a.id IS NULL THEN RAISE EXCEPTION 'contract_intake_artifact_scope_required';END IF;
 PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'review',a.kind);
 PERFORM id FROM public.customer_contracts WHERE id=a.contract_id AND company_id=p_company_id FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-original-intake:'||p_company_id::text||':'||a.contract_id::text,0));
 SELECT * INTO STRICT a FROM gridex_contract_source_intake.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF p_actor_user_id=a.submitted_by OR (SELECT array_agg(x ORDER BY x) FROM jsonb_object_keys(p_review)x) IS DISTINCT FROM ARRAY['agreementHash','claimsHash','decision','reason','sourceHash']::text[] OR p_review->>'sourceHash' IS DISTINCT FROM a.source_sha256 OR p_review->>'agreementHash' IS DISTINCT FROM a.agreement_sha256 OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR length(p_review->>'reason') NOT BETWEEN 1 AND 4000 OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE THEN RAISE EXCEPTION 'contract_intake_independent_exact_hash_bound_review_required';END IF;
 SELECT * INTO q FROM gridex_contract_source_intake.qualifications WHERE artifact_id=a.id;
 IF q.artifact_id IS NOT NULL THEN
  IF p_review->>'decision'<>'approve' THEN RAISE EXCEPTION 'contract_intake_qualified_original_requires_explicit_revocation';END IF;
  IF gridex_contract_source_intake.current_v1(p_company_id,a.kind,a.target_id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'kind',a.kind,'missing',ARRAY['current_qualified_contract_original']);END IF;
  RETURN jsonb_build_object('status','authorized','artifactId',a.id,'kind',a.kind,'sourceId',a.target_id,'replay',true);
 END IF;
 IF p_review->>'decision'='reject' THEN outcome:='rejected';missing:=ARRAY['independent_source_review_rejected'];
 ELSIF p_review->>'decision'='hold' THEN outcome:='held';missing:=ARRAY['independent_source_review_held'];
 ELSE
  BEGIN
   scope:=gridex_contract_source_intake.scope_v1(p_company_id,a.contract_id,a.environment,a.kind);
   IF scope IS DISTINCT FROM a.native_scope THEN missing:=array_append(missing,'current_exact_signed_contract_actor_network_scope');END IF;
   IF gridex_contract_source_intake.receipt_v1(a) IS NULL THEN missing:=array_append(missing,'current_authentic_issuer_receipt_and_legal_representation');END IF;
   IF gridex_contract_source_intake.claims_valid_v1(a) IS NOT TRUE THEN missing:=array_append(missing,'exact_signed_native_domain_claims');END IF;
   IF cardinality(missing)=0 THEN at:=clock_timestamp();row_hash:=gridex_contract_source_intake.materialize_v1(a,p_actor_user_id,at);END IF;
  EXCEPTION WHEN check_violation OR foreign_key_violation OR unique_violation OR invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN missing:=array_append(missing,'current_exact_native_domain_relation');END;
  outcome:=CASE WHEN cardinality(missing)=0 THEN 'approved' ELSE 'held' END;
 END IF;
 INSERT INTO gridex_contract_source_intake.reviews(artifact_id,company_id,actor_user_id,outcome,reason,missing) VALUES(a.id,p_company_id,p_actor_user_id,outcome,p_review->>'reason',to_jsonb(missing)) RETURNING * INTO r;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_contract_source',a.id,'ediel.contract_original.reviewed',jsonb_build_object('kind',a.kind,'sourceHash',a.source_sha256,'agreementHash',a.agreement_sha256,'claimsHash',a.claims_hash,'reviewId',r.id,'outcome',outcome,'missing',missing));
 IF outcome='approved' THEN
  INSERT INTO gridex_contract_source_intake.qualifications(artifact_id,target_id,review_id,company_id,kind,row_hash,approved_by,approved_at) VALUES(a.id,a.target_id,r.id,p_company_id,a.kind,row_hash,p_actor_user_id,at);
  IF gridex_contract_source_intake.current_v1(p_company_id,a.kind,a.target_id) IS NOT TRUE THEN RAISE EXCEPTION 'contract_intake_policy_changed_at_native_approval';END IF;
  RETURN jsonb_build_object('status','authorized','artifactId',a.id,'kind',a.kind,'sourceId',a.target_id,'replay',false);
 END IF;
 RETURN jsonb_build_object('status',outcome,'artifactId',a.id,'kind',a.kind,'missing',missing);
END$$;

--
-- Name: terminal_scope_body_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_contract_source_intake; Owner: -
--

CREATE FUNCTION gridex_contract_source_intake.terminal_scope_body_v1(p_company_id uuid, p_actor_user_id uuid, p_contract_id uuid, p_environment text, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,'archive',p_kind);RETURN gridex_contract_source_intake.scope_v1(p_company_id,p_contract_id,p_environment,p_kind);END$$;

--
-- Name: bind_switch_event_owner_v1(); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.bind_switch_event_owner_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_id uuid;
BEGIN
 IF NEW.switch_request_id IS NULL THEN RETURN NEW; END IF;
 SELECT r.company_id INTO owner_id FROM public.supplier_switch_requests r
  WHERE r.id=NEW.switch_request_id;
 IF owner_id IS NULL THEN
  RAISE EXCEPTION 'switch_event_request_owner_missing' USING ERRCODE='23514';
 END IF;
 IF NEW.company_id IS NOT NULL AND NEW.company_id<>owner_id THEN
  RAISE EXCEPTION 'switch_event_company_mismatch' USING ERRCODE='23514';
 END IF;
 NEW.company_id:=owner_id;
 RETURN NEW;
END $$;

--
-- Name: capture_v1(); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.capture_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
 old_row jsonb; new_row jsonb; old_fact jsonb; new_fact jsonb;
 old_company text; new_company text; selected_company uuid; fact_id bigint;
 fields text[]:=ARRAY[
  'id','company_id','customer_id','customer_contract_id','contract_id','site_id','customer_site_id',
  'metering_point_id','meter_point_id','normalized_metering_point_id','facility_id',
  'normalized_facility_id','site_facility_id','ediel_metering_point_id','ediel_reference',
  'grid_owner_id','grid_owner_ediel_id','switch_request_id','supplier_switch_request_id',
  'customer_case_id','customer_operation_job_id','operation_id','outbound_request_id',
  'cancellation_ediel_message_id','source_message_id','source_switch_request_id',
  'outbound_z03_message_id','inbound_z04_message_id','rff_li_reference',
  'event_type','event_status','event_code','case_type','job_type','task_type',
  'request_type','process_type','source_process','source','status','start_status',
  'cancellation_status','withdrawal_scenario','withdrawal_possible','switch_can_be_stopped',
  'cancellation_required','billing_blocked','billing_manual_review','lifecycle_blocked',
  'start_date','end_date','actual_start_date','actual_end_date','starts_at','ends_at',
  'ended_at','signed_at','termination_notice_date','withdrawal_requested_at',
  'requested_start_date','confirmed_start_date','completed_at','failed_at',
  'submitted_at','resolved_at','closed_at','move_in_date','move_out_date',
  'happened_at','occurred_at','created_at','updated_at','archived_at','source_type','operation_id',
  'idempotency_key','actual_start_at','delivery_start_at','withdrawal_deadline_at'
 ];
BEGIN IF TG_OP='UPDATE' AND public.ediel_capture_customer_record_retention_origin_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 IF TG_TABLE_SCHEMA<>'public' OR NOT EXISTS
  (SELECT FROM gridex_correction_process.epochs e WHERE e.table_name=TG_TABLE_NAME) THEN
  RAISE EXCEPTION 'correction_process_unregistered_producer' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
 IF coalesce(octet_length(old_row::text),0)+coalesce(octet_length(new_row::text),0)>6291456 THEN
  RAISE EXCEPTION 'correction_process_transition_too_large' USING ERRCODE='22001';
 END IF;
 SELECT jsonb_object_agg(key,value) INTO old_fact FROM jsonb_each(old_row) WHERE key=ANY(fields);
 SELECT jsonb_object_agg(key,value) INTO new_fact FROM jsonb_each(new_row) WHERE key=ANY(fields);
 IF coalesce(octet_length(old_fact::text),0)>65536 OR coalesce(octet_length(new_fact::text),0)>65536 THEN
  RAISE EXCEPTION 'correction_process_fact_too_large' USING ERRCODE='22001';
 END IF;
 old_company:=old_row->>'company_id'; new_company:=new_row->>'company_id';
 selected_company:=coalesce(old_company,new_company)::uuid;
 INSERT INTO gridex_correction_process.facts(table_name,row_id,operation,company_id,old_fact,new_fact,facts_hash)
 VALUES (TG_TABLE_NAME,(coalesce(old_row,new_row)->>'id')::uuid,TG_OP,selected_company,old_fact,new_fact,
  encode(sha256(convert_to(jsonb_build_object('table',TG_TABLE_NAME,'rowId',coalesce(old_row,new_row)->>'id',
   'operation',TG_OP,'old',old_fact,'new',new_fact)::text,'UTF8')),'hex')) RETURNING id INTO fact_id;
 IF selected_company IS NULL OR (TG_OP='UPDATE' AND old_company IS DISTINCT FROM new_company) THEN
  INSERT INTO gridex_correction_process.gaps(fact_id,reason,old_scope,new_scope)
  VALUES(fact_id,CASE WHEN old_company IS NULL OR new_company IS NULL THEN 'unbound_company' ELSE 'company_changed' END,
   old_fact,new_fact);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;

--
-- Name: combined_document_body_v1(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_document_body_v1(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH scoped AS MATERIALIZED (
  SELECT a.* FROM gridex_received_sources.document_reference_attempts a
  WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.recorded_at<=p_cutoff
   AND EXISTS(SELECT FROM gridex_received_sources.correction_concerns c
    WHERE c.source_message_id=a.source_message_id AND c.company_id=a.company_id
      AND c.environment=a.environment AND c.captured_at<=p_cutoff
      AND c.source_received_at<=p_cutoff)
  ORDER BY a.recorded_at,a.id
 ), totals AS (SELECT count(*) AS n,coalesce(sum(octet_length(facts::text)),0) AS bytes FROM scoped)
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','reason',
  CASE WHEN t.n>1000 THEN 'document_count_overflow'
   WHEN t.bytes>6291456 THEN 'document_bytes_overflow' ELSE 'prospective_history_only' END,
  'attemptCount',t.n,'visibilitySnapshot',pg_current_snapshot()::text,
  'epoch',(SELECT to_jsonb(e) FROM gridex_received_sources.document_reference_epoch e),
  'attempts',CASE WHEN t.n<=1000 AND t.bytes<=6291456 THEN
   (SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'sourceMessageId',a.source_message_id,
    'documentId',a.document_id,'predecessorId',a.predecessor_id,'facts',a.facts,
    'factsHash',a.facts_hash,'recordedAt',a.recorded_at,
    'outcome',CASE WHEN o.id IS NULL THEN NULL ELSE jsonb_build_object('id',o.id,
      'status',o.status,'observation',o.observation,'factsHash',o.facts_hash,
      'recordedAt',o.recorded_at,'witnessId',w.id,'witnessAt',w.observed_at) END)
    ORDER BY a.recorded_at,a.id),'[]'::jsonb)
    FROM scoped a LEFT JOIN gridex_received_sources.document_reference_outcomes o
      ON o.attempt_id=a.id AND o.company_id=p_company_id AND o.environment=p_environment
      AND o.recorded_at<=p_cutoff
    LEFT JOIN gridex_received_sources.document_reference_witnesses w
      ON w.outcome_id=o.id AND w.company_id=p_company_id AND w.environment=p_environment
      AND w.observed_at<=p_cutoff)
   ELSE '[]'::jsonb END) FROM totals t;
$$;

--
-- Name: combined_document_body_v2(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_document_body_v2(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone, p_point_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH scoped AS MATERIALIZED (
  SELECT a.* FROM gridex_received_sources.document_reference_attempts a
  WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.recorded_at<=p_cutoff
   AND EXISTS(SELECT FROM gridex_received_sources.correction_concerns c
    WHERE c.source_message_id=a.source_message_id AND c.company_id=a.company_id
      AND c.environment=a.environment AND c.captured_at<=p_cutoff
      AND c.source_received_at<=p_cutoff
      AND (p_point_id IS NULL OR c.facts->'scope'->>'objectId' IS NULL
       OR c.facts->'scope'->>'objectId'=p_point_id))
  ORDER BY a.recorded_at,a.id
 ), totals AS (SELECT count(*) AS n,coalesce(sum(octet_length(facts::text)),0) AS bytes FROM scoped)
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','reason',
  CASE WHEN t.n>1000 THEN 'document_count_overflow'
   WHEN t.bytes>6291456 THEN 'document_bytes_overflow' ELSE 'prospective_history_only' END,
  'attemptCount',t.n,'visibilitySnapshot',pg_current_snapshot()::text,
  'epoch',(SELECT to_jsonb(e) FROM gridex_received_sources.document_reference_epoch e),
  'attempts',CASE WHEN t.n<=1000 AND t.bytes<=6291456 THEN
   (SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'sourceMessageId',a.source_message_id,
    'documentId',a.document_id,'predecessorId',a.predecessor_id,'facts',a.facts,
    'factsHash',a.facts_hash,'recordedAt',a.recorded_at,
    'outcome',CASE WHEN o.id IS NULL THEN NULL ELSE jsonb_build_object('id',o.id,
      'status',o.status,'observation',o.observation,'factsHash',o.facts_hash,
      'recordedAt',o.recorded_at,'witnessId',w.id,'witnessAt',w.observed_at) END)
    ORDER BY a.recorded_at,a.id),'[]'::jsonb)
    FROM scoped a LEFT JOIN gridex_received_sources.document_reference_outcomes o
      ON o.attempt_id=a.id AND o.company_id=p_company_id AND o.environment=p_environment
      AND o.recorded_at<=p_cutoff
    LEFT JOIN gridex_received_sources.document_reference_witnesses w
      ON w.outcome_id=o.id AND w.company_id=p_company_id AND w.environment=p_environment
      AND w.observed_at<=p_cutoff)
   ELSE '[]'::jsonb END) FROM totals t;
$$;

--
-- Name: combined_document_body_v3(uuid, text, timestamp with time zone, text[]); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_document_body_v3(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone, p_point_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH scoped AS MATERIALIZED (
  SELECT a.* FROM gridex_received_sources.document_reference_attempts a
  WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.recorded_at<=p_cutoff
   AND EXISTS(SELECT FROM gridex_received_sources.correction_concerns c
    WHERE c.source_message_id=a.source_message_id AND c.company_id=a.company_id
      AND c.environment=a.environment AND c.captured_at<=p_cutoff
      AND c.source_received_at<=p_cutoff
      AND (p_point_ids IS NULL OR c.facts->'scope'->>'objectId' IS NULL
       OR c.facts->'scope'->>'objectId'=ANY(p_point_ids)))
  ORDER BY a.recorded_at,a.id
 ), totals AS (SELECT count(*) AS n,coalesce(sum(octet_length(facts::text)),0) AS bytes FROM scoped)
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','reason',
  CASE WHEN t.n>1000 THEN 'document_count_overflow'
   WHEN t.bytes>6291456 THEN 'document_bytes_overflow' ELSE 'prospective_history_only' END,
  'attemptCount',t.n,'visibilitySnapshot',pg_current_snapshot()::text,
  'epoch',(SELECT to_jsonb(e) FROM gridex_received_sources.document_reference_epoch e),
  'attempts',CASE WHEN t.n<=1000 AND t.bytes<=6291456 THEN
   (SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'sourceMessageId',a.source_message_id,
    'documentId',a.document_id,'predecessorId',a.predecessor_id,'facts',a.facts,
    'factsHash',a.facts_hash,'recordedAt',a.recorded_at,
    'outcome',CASE WHEN o.id IS NULL THEN NULL ELSE jsonb_build_object('id',o.id,
      'status',o.status,'observation',o.observation,'factsHash',o.facts_hash,
      'recordedAt',o.recorded_at,'witnessId',w.id,'witnessAt',w.observed_at) END)
    ORDER BY a.recorded_at,a.id),'[]'::jsonb)
    FROM scoped a LEFT JOIN gridex_received_sources.document_reference_outcomes o
      ON o.attempt_id=a.id AND o.company_id=p_company_id AND o.environment=p_environment
      AND o.recorded_at<=p_cutoff
    LEFT JOIN gridex_received_sources.document_reference_witnesses w
      ON w.outcome_id=o.id AND w.company_id=p_company_id AND w.environment=p_environment
      AND w.observed_at<=p_cutoff)
   ELSE '[]'::jsonb END) FROM totals t;
$$;

--
-- Name: combined_outbound_body_v1(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_outbound_body_v1(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH concerns AS MATERIALIZED (
  SELECT c.facts->'scope' AS scope FROM gridex_received_sources.correction_concerns c
  WHERE c.company_id=p_company_id AND c.environment=p_environment
   AND c.captured_at<=p_cutoff AND c.source_received_at<=p_cutoff
 ), candidates AS MATERIALIZED (
  SELECT m.id,o.message_id IS NOT NULL AS instrumented,
   coalesce(o.raw_payload,m.raw_payload) AS raw_payload,
   coalesce(o.payload_hash,m.immutable_payload_hash) AS payload_hash,
   gridex_outbound_dispatch.scope_v1(coalesce(o.raw_payload,m.raw_payload)) AS wire_scope
  FROM public.ediel_messages m
  LEFT JOIN gridex_outbound_dispatch.originals o ON o.message_id=m.id
   AND o.company_id=p_company_id AND o.environment=p_environment AND o.captured_at<=p_cutoff
  WHERE m.company_id=p_company_id AND m.environment=p_environment
   AND m.direction='outbound' AND m.created_at<=p_cutoff
   AND (m.message_code='Z08' OR m.rule_profile_key='PRODAT:Z08:H:26.A:r3' OR o.message_id IS NOT NULL)
 ), scoped AS MATERIALIZED (
  SELECT c.* FROM candidates c WHERE EXISTS(SELECT FROM concerns concern
    WHERE (concern.scope->>'objectId' IS NULL OR c.wire_scope->>'point' IS NULL
      OR concern.scope->>'objectId'=c.wire_scope->>'point')
     AND (concern.scope->>'legalSender' IS NULL OR c.wire_scope->>'outboundReceiver' IS NULL
      OR concern.scope->>'legalSender'=c.wire_scope->>'outboundReceiver')
     AND (concern.scope->>'legalReceiver' IS NULL OR c.wire_scope->>'outboundSender' IS NULL
      OR concern.scope->>'legalReceiver'=c.wire_scope->>'outboundSender'))
 ), totals AS (
  SELECT count(*) AS n,coalesce(sum(octet_length(raw_payload)),0) AS bytes FROM scoped
 )
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','reason',
  CASE WHEN t.n>1000 THEN 'outbound_count_overflow'
   WHEN t.bytes>6291456 THEN 'outbound_bytes_overflow' ELSE 'prospective_history_only' END,
  'originalCount',t.n,'visibilitySnapshot',pg_current_snapshot()::text,
  'epoch',(SELECT to_jsonb(e) FROM gridex_outbound_dispatch.epoch e),
  'originals',CASE WHEN t.n<=1000 AND t.bytes<=6291456 THEN
   (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'messageId',s.id,'instrumented',s.instrumented,'rawPayload',s.raw_payload,
    'payloadHash',s.payload_hash,'scope',s.wire_scope,
    'attempts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'owner',a.owner,
      'binding',a.binding,'createdAt',a.created_at) ORDER BY a.id),'[]'::jsonb)
     FROM gridex_outbound_dispatch.attempts a WHERE a.message_id=s.id AND a.created_at<=p_cutoff),
    'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'attemptId',e.attempt_id,
      'kind',e.kind,'facts',e.facts,'observedAt',e.observed_at,
      'witnessId',w.event_id,'witnessAt',w.available_at) ORDER BY e.observed_at,e.id),'[]'::jsonb)
     FROM gridex_outbound_dispatch.events e LEFT JOIN gridex_outbound_dispatch.witnesses w
       ON w.event_id=e.id AND w.company_id=p_company_id AND w.environment=p_environment
       AND w.available_at<=p_cutoff
     WHERE e.message_id=s.id AND e.company_id=p_company_id AND e.environment=p_environment
      AND e.observed_at<=p_cutoff)) ORDER BY s.id),'[]'::jsonb) FROM scoped s)
   ELSE '[]'::jsonb END) FROM totals t;
$$;

