--
-- Name: combined_outbound_body_v3(uuid, text, timestamp with time zone, text[]); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_outbound_body_v3(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone, p_point_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH concerns AS MATERIALIZED (
  SELECT c.facts->'scope' AS scope FROM gridex_received_sources.correction_concerns c
  WHERE c.company_id=p_company_id AND c.environment=p_environment
   AND c.captured_at<=p_cutoff AND c.source_received_at<=p_cutoff
   AND (p_point_ids IS NULL OR c.facts->'scope'->>'objectId' IS NULL
    OR c.facts->'scope'->>'objectId'=ANY(p_point_ids))
 ), candidates AS MATERIALIZED (
  SELECT m.id,o.message_id IS NOT NULL AS instrumented,
   coalesce(o.raw_payload,m.raw_payload) AS raw_payload,
   coalesce(o.payload_hash,m.immutable_payload_hash) AS payload_hash,
   gridex_outbound_dispatch.scope_v1(CASE
    WHEN o.message_id IS NOT NULL AND o.payload_hash=encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex')
     THEN o.raw_payload
    WHEN o.message_id IS NULL AND m.immutable_rendered_at IS NOT NULL
     AND m.immutable_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
     THEN m.raw_payload
    ELSE NULL END) AS wire_scope
  FROM public.ediel_messages m
  LEFT JOIN gridex_outbound_dispatch.originals o ON o.message_id=m.id
   AND o.company_id=p_company_id AND o.environment=p_environment AND o.captured_at<=p_cutoff
  WHERE m.company_id=p_company_id AND m.environment=p_environment
   AND m.direction='outbound' AND m.created_at<=p_cutoff
   AND (m.message_code='Z08' OR m.rule_profile_key='PRODAT:Z08:H:26.A:r3' OR o.message_id IS NOT NULL
    OR (m.message_family='PRODAT' AND (gridex_received_sources.closure_wire_tokens_v1(m.raw_payload) IS NULL
     OR EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v1(m.raw_payload)) t
      WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z08'))))
 ), scoped AS MATERIALIZED (
  SELECT c.* FROM candidates c WHERE EXISTS(SELECT FROM concerns concern
    WHERE (concern.scope->>'objectId' IS NULL OR c.wire_scope->>'point' IS NULL
      OR concern.scope->>'objectId'=c.wire_scope->>'point'
      OR (concern.scope->>'objectId'=ANY(p_point_ids)
       AND c.wire_scope->>'point'=ANY(p_point_ids)))
     AND (concern.scope->>'legalSender' IS NULL OR c.wire_scope->>'outboundReceiver' IS NULL
      OR concern.scope->>'legalSender'=c.wire_scope->>'outboundReceiver')
     AND (concern.scope->>'legalReceiver' IS NULL OR c.wire_scope->>'outboundSender' IS NULL
      OR concern.scope->>'legalReceiver'=c.wire_scope->>'outboundSender'))
 ), totals AS (
  SELECT count(*) AS n,coalesce(sum(octet_length(raw_payload)),0) AS bytes FROM scoped
 )
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','reason',
  CASE WHEN t.n>1000 THEN 'outbound_count_overflow'
   WHEN t.bytes>6291456 THEN 'outbound_bytes_overflow' ELSE 'prospective_history_only' END,
  'originalCount',t.n,'visibilitySnapshot',pg_current_snapshot()::text,
  'epoch',(SELECT to_jsonb(e) FROM gridex_outbound_dispatch.epoch e),
  'originals',CASE WHEN t.n<=1000 AND t.bytes<=6291456 THEN
   (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'messageId',s.id,'instrumented',s.instrumented,'rawPayload',s.raw_payload,
    'payloadHash',s.payload_hash,'scope',s.wire_scope,
    'attempts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'owner',a.owner,
      'binding',a.binding,'createdAt',a.created_at) ORDER BY a.id),'[]'::jsonb)
     FROM gridex_outbound_dispatch.attempts a WHERE a.message_id=s.id AND a.created_at<=p_cutoff),
    'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'attemptId',e.attempt_id,
      'kind',e.kind,'facts',e.facts,'observedAt',e.observed_at,
      'witnessId',w.event_id,'witnessAt',w.available_at) ORDER BY e.observed_at,e.id),'[]'::jsonb)
     FROM gridex_outbound_dispatch.events e LEFT JOIN gridex_outbound_dispatch.witnesses w
       ON w.event_id=e.id AND w.company_id=p_company_id AND w.environment=p_environment
       AND w.available_at<=p_cutoff
     WHERE e.message_id=s.id AND e.company_id=p_company_id AND e.environment=p_environment
      AND e.observed_at<=p_cutoff)) ORDER BY s.id),'[]'::jsonb) FROM scoped s)
   ELSE '[]'::jsonb END) FROM totals t;
$$;

--
-- Name: combined_process_body_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_process_body_v1(p_company_id uuid, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH scoped AS MATERIALIZED (
  SELECT f.id,g.fact_id IS NOT NULL AS has_gap,w.fact_id IS NOT NULL AS has_witness
  FROM gridex_correction_process.facts f
  LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
  LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
  WHERE f.captured_at<=p_cutoff
   AND (f.company_id=p_company_id OR f.old_fact->>'company_id'=p_company_id::text
    OR f.new_fact->>'company_id'=p_company_id::text)
 ), totals AS (
  SELECT count(*) AS n,
   count(*) FILTER (WHERE has_gap) AS gaps,
   count(*) FILTER (WHERE has_witness) AS witnesses FROM scoped
 )
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','factCount',t.n,'gapCount',t.gaps,
  'witnessCount',t.witnesses,'reason',CASE WHEN t.n>1000 THEN 'process_count_overflow' ELSE 'before_epoch_unknown' END,
  'facts',CASE WHEN t.n<=1000 THEN (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',f.id,'table',f.table_name,'rowId',f.row_id,'operation',f.operation,
    'old',f.old_fact,'new',f.new_fact,'factsHash',f.facts_hash,'capturedAt',f.captured_at,
    'gapReason',g.reason,'witnessId',w.id,'witnessAt',w.observed_at) ORDER BY f.id),'[]'::jsonb)
    FROM scoped s JOIN gridex_correction_process.facts f ON f.id=s.id
    LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
    LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
    WHERE g.fact_id IS NULL
     AND (f.old_fact->>'company_id' IS NULL OR f.old_fact->>'company_id'=p_company_id::text)
     AND (f.new_fact->>'company_id' IS NULL OR f.new_fact->>'company_id'=p_company_id::text))
   ELSE '[]'::jsonb END,
  'epochs',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.table_name),'[]'::jsonb)
    FROM gridex_correction_process.epochs e)) FROM totals t;
$$;

--
-- Name: combined_process_body_v2(uuid, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_process_body_v2(p_company_id uuid, p_cutoff timestamp with time zone, p_customer_id uuid, p_point_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
 WITH scoped AS MATERIALIZED (
  SELECT f.id,g.fact_id IS NOT NULL AS has_gap,w.fact_id IS NOT NULL AS has_witness
  FROM gridex_correction_process.facts f
  LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
  LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
  WHERE f.captured_at<=p_cutoff
   AND (f.company_id=p_company_id OR f.old_fact->>'company_id'=p_company_id::text
    OR f.new_fact->>'company_id'=p_company_id::text)
   AND (p_customer_id IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
     AND (nullif(side.v->>'customer_id','') IS NULL OR side.v->>'customer_id'=p_customer_id::text)))
   AND (p_point_id IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
     AND (coalesce(nullif(side.v->>'metering_point_id',''),nullif(side.v->>'meter_point_id',''),
       nullif(side.v->>'normalized_metering_point_id',''),nullif(side.v->>'ediel_metering_point_id',''),nullif(side.v->>'facility_id',''),
       nullif(side.v->>'normalized_facility_id',''),nullif(side.v->>'site_facility_id','')) IS NULL
      OR p_point_id IN (side.v->>'metering_point_id',side.v->>'meter_point_id',
       side.v->>'normalized_metering_point_id',side.v->>'ediel_metering_point_id',
       side.v->>'facility_id',side.v->>'normalized_facility_id',side.v->>'site_facility_id')
      -- These producers can retain a point row UUID after the current graph is
      -- deleted. Resolve against immutable point history as of the transition.
      -- Missing history is unknown and must stay in the subject's budget.
      OR (f.table_name IN ('customer_supply_periods','customer_contracts',
        'customer_cases','customer_operation_jobs','customer_operation_events',
        'supplier_switch_requests')
       AND side.v->>'metering_point_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND coalesce((SELECT CASE
        WHEN coalesce(nullif(coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',''),
         nullif(coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',''),
         nullif(coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id','')) IS NULL THEN true
        ELSE coalesce(p_point_id IN (coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'site_facility_id'),false) END
        FROM gridex_correction_process.facts pf
        WHERE pf.table_name='metering_points' AND pf.row_id=(side.v->>'metering_point_id')::uuid
         AND pf.captured_at<=f.captured_at AND pf.company_id=p_company_id
        ORDER BY pf.id DESC LIMIT 1),true)))))
 ), totals AS (
  SELECT count(*) AS n,count(*) FILTER (WHERE has_gap) AS gaps,
   count(*) FILTER (WHERE has_witness) AS witnesses FROM scoped
 )
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','factCount',t.n,'gapCount',t.gaps,
  'witnessCount',t.witnesses,'reason',CASE WHEN t.n>1000 THEN 'scoped_process_count_overflow'
   ELSE 'before_epoch_unknown' END,
  'facts',CASE WHEN t.n<=1000 THEN (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',f.id,'table',f.table_name,'rowId',f.row_id,'operation',f.operation,
    'old',f.old_fact,'new',f.new_fact,'factsHash',f.facts_hash,'capturedAt',f.captured_at,
    'gapReason',g.reason,'witnessId',w.id,'witnessAt',w.observed_at) ORDER BY f.id),'[]'::jsonb)
    FROM scoped s JOIN gridex_correction_process.facts f ON f.id=s.id
    LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
    LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
    WHERE g.fact_id IS NULL
     AND (f.old_fact->>'company_id' IS NULL OR f.old_fact->>'company_id'=p_company_id::text)
     AND (f.new_fact->>'company_id' IS NULL OR f.new_fact->>'company_id'=p_company_id::text))
   ELSE '[]'::jsonb END,
  'epochs',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.table_name),'[]'::jsonb)
    FROM gridex_correction_process.epochs e)) FROM totals t;
$_$;

--
-- Name: combined_process_body_v3(uuid, timestamp with time zone, uuid[], text[]); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.combined_process_body_v3(p_company_id uuid, p_cutoff timestamp with time zone, p_customer_ids uuid[], p_point_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
 WITH scoped AS MATERIALIZED (
  SELECT f.id,g.fact_id IS NOT NULL AS has_gap,w.fact_id IS NOT NULL AS has_witness
  FROM gridex_correction_process.facts f
  LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
  LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
  WHERE f.captured_at<=p_cutoff
   AND (f.company_id=p_company_id OR f.old_fact->>'company_id'=p_company_id::text
    OR f.new_fact->>'company_id'=p_company_id::text)
   AND (f.table_name<>'supplier_switch_events' OR
    gridex_correction_process.switch_event_subject_v1(p_company_id,f.old_fact,f.new_fact,
     f.captured_at,p_customer_ids,p_point_ids))
   AND (f.table_name='supplier_switch_events' OR p_customer_ids IS NULL
    OR (f.table_name='supplier_switch_requests' AND p_point_ids IS NOT NULL AND EXISTS (
     SELECT FROM (VALUES(f.old_fact),(f.new_fact)) request_side(v)
     WHERE nullif(request_side.v->>'metering_point_id','') IS NOT NULL)) OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
     AND (nullif(side.v->>'customer_id','') IS NULL OR side.v->>'customer_id'=ANY(ARRAY(SELECT id::text FROM unnest(p_customer_ids) AS customer_scope(id))))))
   AND (f.table_name='supplier_switch_events' OR p_point_ids IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
     AND ((coalesce(nullif(side.v->>'metering_point_id',''),nullif(side.v->>'meter_point_id',''),
       nullif(side.v->>'normalized_metering_point_id',''),nullif(side.v->>'ediel_metering_point_id',''),nullif(side.v->>'facility_id',''),
       nullif(side.v->>'normalized_facility_id',''),nullif(side.v->>'site_facility_id','')) IS NULL
       AND (f.table_name<>'supplier_switch_requests' OR p_customer_ids IS NULL
        OR nullif(side.v->>'customer_id','') IS NULL OR side.v->>'customer_id'=ANY(ARRAY(
         SELECT id::text FROM unnest(p_customer_ids) AS customer_scope(id)))))
      OR EXISTS(SELECT FROM unnest(p_point_ids) AS point_scope(point_id) WHERE point_id IN (side.v->>'metering_point_id',side.v->>'meter_point_id',
       side.v->>'normalized_metering_point_id',side.v->>'ediel_metering_point_id',
       side.v->>'facility_id',side.v->>'normalized_facility_id',side.v->>'site_facility_id'))
      -- These producers can retain a point row UUID after the current graph is
      -- deleted. Resolve against immutable point history as of the transition.
      -- Missing history is unknown and must stay in the subject's budget.
      OR (f.table_name IN ('customer_supply_periods','customer_contracts',
        'customer_cases','customer_operation_jobs','customer_operation_events',
        'supplier_switch_requests')
       AND side.v->>'metering_point_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND coalesce((SELECT CASE
        WHEN coalesce(nullif(coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',''),
         nullif(coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',''),
         nullif(coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id','')) IS NULL THEN true
        ELSE coalesce(EXISTS(SELECT FROM unnest(p_point_ids) AS point_scope(point_id) WHERE point_id IN (coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id',
         coalesce(pf.new_fact,pf.old_fact)->>'site_facility_id')),false) END
        FROM gridex_correction_process.facts pf
        WHERE pf.table_name='metering_points' AND pf.row_id=(side.v->>'metering_point_id')::uuid
         AND pf.captured_at<=f.captured_at AND pf.company_id=p_company_id
        ORDER BY pf.id DESC LIMIT 1),true)))))
 ), totals AS (
  SELECT count(*) AS n,count(*) FILTER (WHERE has_gap) AS gaps,
   count(*) FILTER (WHERE has_witness) AS witnesses FROM scoped
 )
 SELECT jsonb_build_object('complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','factCount',t.n,'gapCount',t.gaps,
  'witnessCount',t.witnesses,'reason',CASE WHEN t.n>1000 THEN 'scoped_process_count_overflow'
   ELSE 'before_epoch_unknown' END,
  'facts',CASE WHEN t.n<=1000 THEN (SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',f.id,'table',f.table_name,'rowId',f.row_id,'operation',f.operation,
    'old',f.old_fact,'new',f.new_fact,'factsHash',f.facts_hash,'capturedAt',f.captured_at,
    'gapReason',g.reason,'witnessId',w.id,'witnessAt',w.observed_at) ORDER BY f.id),'[]'::jsonb)
    FROM scoped s JOIN gridex_correction_process.facts f ON f.id=s.id
    LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
    LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff
    WHERE g.fact_id IS NULL
     AND (f.old_fact->>'company_id' IS NULL OR f.old_fact->>'company_id'=p_company_id::text)
     AND (f.new_fact->>'company_id' IS NULL OR f.new_fact->>'company_id'=p_company_id::text))
   ELSE '[]'::jsonb END,
  'epochs',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.table_name),'[]'::jsonb)
    FROM gridex_correction_process.epochs e)) FROM totals t;
$_$;

--
-- Name: customer_retention_tombstoned_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.customer_retention_tombstoned_v1(p_company_id uuid, p_customer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_ediel_retention.customer_tombstones t WHERE t.customer_id=p_customer_id AND t.company_id=p_company_id)
$$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 RAISE EXCEPTION 'correction_process_append_only' USING ERRCODE='55000';
END $$;

--
-- Name: open_combined_v1(uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.open_combined_v1(p_company_id uuid, p_environment text, p_message_id uuid, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE observed timestamptz:=clock_timestamp(); source_body jsonb; process_body jsonb;
 concern_body jsonb; outbound_body jsonb; document_body jsonb;
 snap text; body jsonb; bytes text; source_text text;
 saved gridex_correction_process.combined_snapshots%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_environment IS NULL
 OR p_message_id IS NULL OR p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff>observed
 OR NOT EXISTS(SELECT FROM public.ediel_messages m WHERE m.id=p_message_id
  AND m.company_id=p_company_id AND m.environment=p_environment AND m.direction='inbound')
 THEN RAISE EXCEPTION 'combined_snapshot_scope_unavailable' USING ERRCODE='42501'; END IF;

 -- The subject linkage and all five STABLE owners use this SELECT's MVCC
 -- visibility. No second read can silently change the selected population.
 SELECT gridex_received_sources.selection_body_v5(p_company_id,p_environment,p_cutoff,observed,aliases.points),
  gridex_correction_process.combined_process_body_v3(p_company_id,p_cutoff,aliases.customers,aliases.points),
  gridex_received_sources.combined_concern_body_v3(p_company_id,p_environment,p_cutoff,aliases.points),
  gridex_correction_process.combined_outbound_body_v3(p_company_id,p_environment,p_cutoff,aliases.points),
  gridex_correction_process.combined_document_body_v3(p_company_id,p_environment,p_cutoff,aliases.points),
  pg_current_snapshot()::text
 INTO source_body,process_body,concern_body,outbound_body,document_body,snap
 FROM public.ediel_messages m LEFT JOIN public.metering_points mp
  ON mp.id=m.metering_point_id AND mp.company_id=m.company_id
 CROSS JOIN LATERAL (SELECT gridex_correction_process.subject_wire_point_v1(
  m.raw_payload,m.immutable_payload_hash) AS point_id) subject
 CROSS JOIN LATERAL (SELECT gridex_correction_process.point_aliases_v1(
  p_company_id,m.metering_point_id,subject.point_id,mp.metering_point_id,p_cutoff) AS points,
  gridex_correction_process.point_customers_v1(
  p_company_id,m.metering_point_id,m.customer_id,p_cutoff) AS customers) aliases
 WHERE m.id=p_message_id AND m.company_id=p_company_id AND m.environment=p_environment
  AND m.direction='inbound';
 IF snap IS NULL THEN RAISE EXCEPTION 'combined_snapshot_scope_unavailable' USING ERRCODE='42501'; END IF;
 source_text:=source_body::text;
 body:=jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,
  'subjectMessageId',p_message_id,'cutoffAt',p_cutoff,'visibilitySnapshot',snap,
  'source',jsonb_build_object('readsetText',source_text,
    'readsetHash',encode(sha256(convert_to(source_text,'UTF8')),'hex'),'visibilitySnapshot',snap),
  'process',process_body||jsonb_build_object('visibilitySnapshot',snap),
  'correction',concern_body||jsonb_build_object('visibilitySnapshot',snap),
  'outbound',outbound_body||jsonb_build_object('visibilitySnapshot',snap),
  'document',document_body||jsonb_build_object('visibilitySnapshot',snap));
 bytes:=body::text;
 INSERT INTO gridex_correction_process.combined_snapshots(company_id,environment,subject_message_id,
  cutoff_at,visibility_snapshot,readset_text,readset_hash)
 VALUES(p_company_id,p_environment,p_message_id,p_cutoff,snap,bytes,
  encode(sha256(convert_to(bytes,'UTF8')),'hex')) RETURNING * INTO saved;
 RETURN jsonb_build_object('snapshotId',saved.id,'readsetText',saved.readset_text,
  'readsetHash',saved.readset_hash);
END $$;

--
-- Name: open_readset_v1(uuid, text, uuid, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.open_readset_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_cutoff_at timestamp with time zone, p_customer_id uuid, p_point_id text, p_supply_period_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
 ids bigint[]; witness_ids uuid[]; n bigint; input_bytes bigint; gap_count bigint; witness_count bigint;
 facts_body jsonb; gaps_body jsonb; witnesses_body jsonb; epochs_body jsonb;
 body jsonb; serialized text; stored gridex_correction_process.readsets%rowtype;
 reason text := NULL;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_environment IS NULL
 OR p_cutoff_at IS NULL OR NOT isfinite(p_cutoff_at) OR p_cutoff_at>clock_timestamp()
 OR p_actor_user_id IS NULL
 OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'customers.read'),false)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id
  AND is_active AND status='active' AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.companies WHERE id=p_company_id AND coalesce(is_active,true)
  AND coalesce(status,'active') NOT IN ('archived','suspended','pending_deletion','deleted','deleted_test_only','inactive','paused','closed'))
 THEN RAISE EXCEPTION 'process_reader_unavailable' USING ERRCODE='42501'; END IF;

 -- Scope before limiting; a known unrelated dimension excludes a transition,
 -- while a missing dimension is conservatively relevant. Both OLD and NEW
 -- scopes are considered for moves. Opaque gaps never disclose cross-tenant facts.
 WITH scoped AS (
  SELECT f.id,f.old_fact,f.new_fact, g.fact_id IS NOT NULL AS has_gap,
   w.fact_id IS NOT NULL AS has_witness,w.id AS witness_id
  FROM gridex_correction_process.facts f
  LEFT JOIN gridex_correction_process.gaps g ON g.fact_id=f.id
  LEFT JOIN gridex_correction_process.witnesses w ON w.fact_id=f.id AND w.observed_at<=p_cutoff_at
  WHERE f.captured_at<=p_cutoff_at
   AND (f.company_id=p_company_id OR f.old_fact->>'company_id'=p_company_id::text
    OR f.new_fact->>'company_id'=p_company_id::text)
   AND (p_customer_id IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
    AND (nullif(side.v->>'customer_id','') IS NULL OR side.v->>'customer_id'=p_customer_id::text)))
   AND (p_point_id IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
    AND (coalesce(nullif(side.v->>'metering_point_id',''),nullif(side.v->>'meter_point_id',''),
      nullif(side.v->>'normalized_metering_point_id',''),nullif(side.v->>'ediel_metering_point_id',''),
      nullif(side.v->>'facility_id',''),nullif(side.v->>'normalized_facility_id',''),
      nullif(side.v->>'site_facility_id','')) IS NULL
     OR p_point_id IN (side.v->>'metering_point_id',side.v->>'meter_point_id',
      side.v->>'normalized_metering_point_id',side.v->>'ediel_metering_point_id',
      side.v->>'facility_id',side.v->>'normalized_facility_id',side.v->>'site_facility_id')
     -- Supply periods store the row UUID, not the physical EDIEL identity.
     -- Resolve it against the latest immutable point fact at this transition;
     -- an absent/unknown alias remains a wildcard, never a false exclusion.
     OR (f.table_name IN ('customer_supply_periods','customer_contracts',
      'customer_cases','customer_operation_jobs','customer_operation_events',
      'supplier_switch_requests')
      AND nullif(side.v->>'metering_point_id','') IS NOT NULL
      AND side.v->>'metering_point_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND coalesce((SELECT CASE
       WHEN coalesce(nullif(coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',''),
        nullif(coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',''),
        nullif(coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id','')) IS NULL THEN true
       ELSE coalesce(p_point_id IN (coalesce(pf.new_fact,pf.old_fact)->>'normalized_metering_point_id',
        coalesce(pf.new_fact,pf.old_fact)->>'metering_point_id',
        coalesce(pf.new_fact,pf.old_fact)->>'meter_point_id',
        coalesce(pf.new_fact,pf.old_fact)->>'site_facility_id'),false) END
       FROM gridex_correction_process.facts pf
       WHERE pf.table_name='metering_points' AND pf.row_id=(side.v->>'metering_point_id')::uuid
        AND pf.captured_at<=f.captured_at AND pf.company_id=p_company_id
       ORDER BY pf.id DESC LIMIT 1),true)))))
   AND (p_supply_period_id IS NULL OR EXISTS (
    SELECT FROM (VALUES (f.old_fact),(f.new_fact)) side(v) WHERE side.v IS NOT NULL
    AND (CASE WHEN f.table_name='customer_supply_periods' THEN f.row_id=p_supply_period_id
     ELSE nullif(side.v->>'supply_period_id','') IS NULL
       OR side.v->>'supply_period_id'=p_supply_period_id::text END)))
 ) SELECT count(*),coalesce(sum(coalesce(octet_length(old_fact::text),0)
      +coalesce(octet_length(new_fact::text),0)),0),
   count(*) FILTER (WHERE has_gap),count(*) FILTER (WHERE has_witness),
   CASE WHEN count(*)<=1000 THEN array_agg(id ORDER BY id) ELSE NULL END,
   CASE WHEN count(*)<=1000 THEN array_agg(witness_id ORDER BY id)
    FILTER (WHERE has_witness) ELSE NULL END
  INTO n,input_bytes,gap_count,witness_count,ids,witness_ids FROM scoped;
 IF n>1000 THEN reason:='scoped_process_count_overflow';
 ELSIF input_bytes>6291456 THEN reason:='scoped_process_bytes_overflow'; END IF;
 IF reason IS NULL THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'table',f.table_name,'rowId',f.row_id,
    'operation',f.operation,'old',f.old_fact,'new',f.new_fact,'factsHash',f.facts_hash,
    'capturedAt',f.captured_at) ORDER BY f.id),'[]'::jsonb)
   INTO facts_body FROM gridex_correction_process.facts f WHERE f.id=ANY(ids)
   AND NOT EXISTS(SELECT FROM gridex_correction_process.gaps g WHERE g.fact_id=f.id);
  SELECT coalesce(jsonb_agg(jsonb_build_object('factId',g.fact_id,'reason',g.reason) ORDER BY g.fact_id),'[]'::jsonb)
   INTO gaps_body FROM gridex_correction_process.gaps g WHERE g.fact_id=ANY(ids);
  SELECT coalesce(jsonb_agg(jsonb_build_object('factId',w.fact_id,'id',w.id,
     'factsHash',w.facts_hash,'observedAt',w.observed_at) ORDER BY w.fact_id),'[]'::jsonb)
   INTO witnesses_body FROM gridex_correction_process.witnesses w
   WHERE w.id=ANY(witness_ids) AND w.observed_at<=p_cutoff_at;
 ELSE
  facts_body:='[]'::jsonb;gaps_body:='[]'::jsonb;witnesses_body:='[]'::jsonb;
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.table_name),'[]'::jsonb)
  INTO epochs_body FROM gridex_correction_process.epochs e;
 body:=jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,
  'cutoffAt',p_cutoff_at,'scope',jsonb_build_object('customerId',p_customer_id,'pointId',p_point_id,
   'supplyPeriodId',p_supply_period_id),'complete',false,'authority','none',
  'historyCoverage','before_epoch_unknown','factCount',n,'gapCount',gap_count,
  'witnessCount',witness_count,'reason',reason,'facts',facts_body,'gaps',gaps_body,
  'witnesses',witnesses_body,'epochs',epochs_body,'visibilitySnapshot',pg_current_snapshot()::text);
 serialized:=body::text;
 IF octet_length(serialized)>6291456 THEN
  body:=jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,
   'cutoffAt',p_cutoff_at,'complete',false,'authority','none','historyCoverage','before_epoch_unknown',
   'scope',jsonb_build_object('customerId',p_customer_id,'pointId',p_point_id,
    'supplyPeriodId',p_supply_period_id),
   'factCount',n,'gapCount',gap_count,'witnessCount',witness_count,
   'reason','scoped_process_output_overflow','facts','[]'::jsonb,'gaps','[]'::jsonb,
   'witnesses','[]'::jsonb,'epochs',epochs_body,'visibilitySnapshot',pg_current_snapshot()::text);
  serialized:=body::text;
 END IF;
 INSERT INTO gridex_correction_process.readsets(company_id,environment,cutoff_at,customer_id,point_id,
  supply_period_id,readset_text,readset_hash)
 VALUES(p_company_id,p_environment,p_cutoff_at,p_customer_id,p_point_id,p_supply_period_id,
  serialized,encode(sha256(convert_to(serialized,'UTF8')),'hex')) RETURNING * INTO stored;
 RETURN jsonb_build_object('snapshotId',stored.id,'readsetText',stored.readset_text,
  'readsetHash',stored.readset_hash);
END $_$;

--
-- Name: point_aliases_v1(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.point_aliases_v1(p_company_id uuid, p_point_row uuid, p_subject_wire text, p_current text, p_cutoff timestamp with time zone) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT array_agg(DISTINCT v.alias ORDER BY v.alias) FROM (
  SELECT nullif(p_subject_wire,'') AS alias UNION ALL SELECT nullif(p_current,'')
  UNION ALL
  SELECT nullif(side.fact->>key.name,'')
  FROM gridex_correction_process.facts f
  CROSS JOIN LATERAL (VALUES(f.old_fact),(f.new_fact)) side(fact)
  CROSS JOIN LATERAL (VALUES('metering_point_id'),('meter_point_id'),
   ('normalized_metering_point_id'),('ediel_metering_point_id'),
   ('facility_id'),('normalized_facility_id'),('site_facility_id')) key(name)
  WHERE p_point_row IS NOT NULL AND f.company_id=p_company_id
   AND f.table_name='metering_points' AND f.row_id=p_point_row AND f.captured_at<=p_cutoff
 ) v WHERE v.alias IS NOT NULL;
$$;

--
-- Name: point_customers_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.point_customers_v1(p_company_id uuid, p_point_row uuid, p_current uuid, p_cutoff timestamp with time zone) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT array_agg(DISTINCT v.id ORDER BY v.id) FROM (
  SELECT p_current AS id UNION ALL
  SELECT (side.fact->>'customer_id')::uuid
  FROM gridex_correction_process.facts f
  CROSS JOIN LATERAL (VALUES(f.old_fact),(f.new_fact)) side(fact)
  WHERE p_point_row IS NOT NULL AND f.company_id=p_company_id
   AND f.table_name='metering_points' AND f.row_id=p_point_row AND f.captured_at<=p_cutoff
   AND side.fact->>'customer_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 ) v WHERE v.id IS NOT NULL;
$_$;

--
-- Name: subject_wire_point_v1(text, text); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.subject_wire_point_v1(p_raw text, p_hash text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb; n integer; valid_n integer; point text;
BEGIN
 IF p_raw IS NULL OR p_hash IS NULL OR p_hash<>encode(sha256(convert_to(p_raw,'UTF8')),'hex')
 THEN RETURN NULL; END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v1(p_raw);
 IF tokens IS NULL THEN RETURN NULL; END IF;
 SELECT count(*),count(*) FILTER (WHERE t#>>'{elements,2,2}'='9'
  AND nullif(t#>>'{elements,2,0}','') IS NOT NULL),max(t#>>'{elements,2,0}')
 INTO n,valid_n,point FROM jsonb_array_elements(tokens) t
 WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172';
 IF n=1 AND valid_n=1 AND length(point)<=128 THEN RETURN point; END IF;
 RETURN NULL;
END $$;

--
-- Name: switch_event_subject_v1(uuid, jsonb, jsonb, timestamp with time zone, uuid[], text[]); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.switch_event_subject_v1(p_company_id uuid, p_old jsonb, p_new jsonb, p_captured_at timestamp with time zone, p_customer_ids uuid[], p_point_ids text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE event_side jsonb; request_id text; request_fact record; request_side jsonb;
 point_id text; point_fact record; point_side jsonb;
 seen_request boolean; seen_point boolean;
BEGIN
 FOR event_side IN SELECT v FROM (VALUES(p_old),(p_new)) AS sides(v) WHERE v IS NOT NULL LOOP
  request_id:=event_side->>'switch_request_id';
  IF request_id IS NULL OR request_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN RETURN true; END IF;
  seen_request:=false;
  FOR request_fact IN SELECT f.company_id,f.operation,f.old_fact,f.new_fact
   FROM gridex_correction_process.facts f
   WHERE f.table_name='supplier_switch_requests' AND f.row_id=request_id::uuid
    AND f.captured_at<=p_captured_at ORDER BY f.captured_at,f.id LOOP
   IF NOT seen_request AND request_fact.operation<>'INSERT' THEN RETURN true; END IF;
   seen_request:=true;
   IF request_fact.company_id IS DISTINCT FROM p_company_id
    OR (request_fact.old_fact IS NOT NULL AND
     request_fact.old_fact->>'company_id' IS DISTINCT FROM p_company_id::text)
    OR (request_fact.new_fact IS NOT NULL AND
     request_fact.new_fact->>'company_id' IS DISTINCT FROM p_company_id::text)
   THEN RETURN true; END IF;
   FOR request_side IN SELECT v FROM (VALUES(request_fact.old_fact),(request_fact.new_fact)) AS sides(v)
    WHERE v IS NOT NULL LOOP
    IF (p_point_ids IS NULL OR nullif(request_side->>'metering_point_id','') IS NULL)
     AND p_customer_ids IS NOT NULL AND nullif(request_side->>'customer_id','') IS NOT NULL
     AND NOT (request_side->>'customer_id'=ANY(ARRAY(
      SELECT id::text FROM unnest(p_customer_ids) AS customer_scope(id))))
    THEN CONTINUE; END IF;
    point_id:=request_side->>'metering_point_id';
    IF p_point_ids IS NOT NULL AND nullif(point_id,'') IS NOT NULL THEN
     IF point_id=ANY(p_point_ids) THEN RETURN true; END IF;
     IF point_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     THEN RETURN true; END IF;
     seen_point:=false;
     FOR point_fact IN SELECT f.company_id,f.operation,f.old_fact,f.new_fact
      FROM gridex_correction_process.facts f
      WHERE f.table_name='metering_points' AND f.row_id=point_id::uuid
       AND f.captured_at<=p_captured_at ORDER BY f.captured_at,f.id LOOP
      IF NOT seen_point AND point_fact.operation<>'INSERT' THEN RETURN true; END IF;
      seen_point:=true;
      IF point_fact.company_id IS DISTINCT FROM p_company_id
       OR (point_fact.old_fact IS NOT NULL AND
        point_fact.old_fact->>'company_id' IS DISTINCT FROM p_company_id::text)
       OR (point_fact.new_fact IS NOT NULL AND
        point_fact.new_fact->>'company_id' IS DISTINCT FROM p_company_id::text)
      THEN RETURN true; END IF;
      FOR point_side IN SELECT v FROM (VALUES(point_fact.old_fact),(point_fact.new_fact)) AS sides(v)
       WHERE v IS NOT NULL LOOP
       IF coalesce(nullif(point_side->>'normalized_metering_point_id',''),
        nullif(point_side->>'metering_point_id',''),nullif(point_side->>'meter_point_id','')) IS NULL
       THEN RETURN true; END IF;
       IF EXISTS(SELECT FROM unnest(p_point_ids) AS point_scope(id)
        WHERE id IN (point_side->>'normalized_metering_point_id',point_side->>'metering_point_id',
         point_side->>'meter_point_id',point_side->>'site_facility_id'))
       THEN RETURN true; END IF;
      END LOOP;
     END LOOP;
     IF NOT seen_point THEN RETURN true; END IF;
     CONTINUE;
    END IF;
    RETURN true;
   END LOOP;
  END LOOP;
  IF NOT seen_request THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
END $_$;

--
-- Name: witness_v1(uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_correction_process; Owner: -
--

CREATE FUNCTION gridex_correction_process.witness_v1(p_company_id uuid, p_fact_id bigint, p_facts_hash text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE f gridex_correction_process.facts%rowtype; w gridex_correction_process.witnesses%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL
 OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'customers.read'),false)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id
  AND is_active AND status='active' AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.companies WHERE id=p_company_id AND coalesce(is_active,true)
  AND coalesce(status,'active') NOT IN ('archived','suspended','pending_deletion','deleted','deleted_test_only','inactive','paused','closed'))
 THEN RAISE EXCEPTION 'process_actor_unavailable' USING ERRCODE='42501'; END IF;
 IF public.ediel_process_journal_tombstoned_v1(p_company_id,'correction_process_fact_body',p_fact_id::text,p_facts_hash) THEN SELECT * INTO w FROM gridex_correction_process.witnesses WHERE fact_id=p_fact_id AND company_id=p_company_id AND facts_hash=p_facts_hash;IF NOT FOUND THEN RAISE EXCEPTION 'process_journal_retention_tombstoned';END IF;RETURN jsonb_build_object('factId',p_fact_id,'factsHash',p_facts_hash,'witnessId',w.id,'availableAt',w.observed_at,'coverage','incomplete','authority','none','retentionUnavailable',true,'bytesAvailable',false);END IF; SELECT * INTO f FROM gridex_correction_process.facts
 WHERE id=p_fact_id AND company_id=p_company_id AND facts_hash=p_facts_hash;
 IF f.id IS NULL OR EXISTS(SELECT FROM gridex_correction_process.gaps WHERE fact_id=f.id)
 THEN RAISE EXCEPTION 'process_fact_unavailable' USING ERRCODE='42501'; END IF;
 IF f.created_xid=pg_current_xact_id()
 THEN RAISE EXCEPTION 'process_fact_not_committed' USING ERRCODE='23514'; END IF;
 INSERT INTO gridex_correction_process.witnesses(fact_id,company_id,facts_hash)
 VALUES(f.id,p_company_id,f.facts_hash) ON CONFLICT(fact_id) DO NOTHING;
 SELECT * INTO STRICT w FROM gridex_correction_process.witnesses WHERE fact_id=f.id;
 RETURN jsonb_build_object('factId',f.id,'factsHash',f.facts_hash,'witnessId',w.id,
  'availableAt',w.observed_at,'coverage','incomplete','authority','none');
END $$;

--
-- Name: bind_original_v1(); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.bind_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_customer_life_events.origins%rowtype;b jsonb;i public.ediel_message_intents%rowtype;reservation jsonb;task_id uuid;BEGIN
 SELECT * INTO o FROM gridex_customer_life_events.origins WHERE company_id=NEW.company_id AND intent_id=NEW.intent_id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 b:=gridex_customer_life_events.source_v1(o.company_id,o.event_id,o.actor_user_id,'prepare');
 reservation:=public.ediel_reserve_customer_life_event_v1(o.company_id,o.event_id,o.actor_user_id,o.intent_id,o.outbound_request_id);
 IF reservation->>'status' IS DISTINCT FROM 'reserved' OR reservation->>'outboundRequestId' IS DISTINCT FROM o.outbound_request_id::text THEN RAISE EXCEPTION 'customer_life_event_first_current_intent_request_required';END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=o.company_id FOR SHARE;
 IF b->>'status' IS DISTINCT FROM 'authorized' OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_standard IS DISTINCT FROM 'edifact' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM 'Z09' OR NEW.environment IS DISTINCT FROM b->>'environment' OR NEW.source_operation_id IS DISTINCT FROM o.event_id::text OR NEW.raw_payload IS DISTINCT FROM b->>'rawPayload' OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id
  OR NEW.customer_id::text IS DISTINCT FROM b->>'customerId' OR NEW.site_id::text IS DISTINCT FROM b->>'siteId' OR NEW.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId' OR NEW.communication_route_id IS DISTINCT FROM i.communication_route_id OR NEW.route_profile_id IS DISTINCT FROM i.route_profile_id OR NEW.status IS DISTINCT FROM 'draft' OR NEW.immutable_rendered_at IS NULL OR NEW.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') OR i.validation_status IS DISTINCT FROM 'validated' THEN RAISE EXCEPTION 'customer_life_event_original_source_binding_required';END IF;
 INSERT INTO gridex_customer_life_events.originals(message_id,event_id,company_id,payload_hash,source_snapshot,intent_binding) VALUES(NEW.id,o.event_id,o.company_id,NEW.immutable_payload_hash,b,jsonb_build_object('intentId',i.id,'operationId',i.operation_id,'requestId',o.outbound_request_id,'routeId',i.communication_route_id,'routeProfileId',i.route_profile_id));
 INSERT INTO gridex_customer_life_events.desired_changes(event_id,company_id,message_id,classification,source_scope,information_known_at,actor_user_id) SELECT o.event_id,o.company_id,NEW.id,e.classification,e.approved_scope,e.information_known_at,o.actor_user_id FROM gridex_customer_life_events.events e WHERE e.id=o.event_id;
 INSERT INTO public.customer_operation_tasks(company_id,customer_id,site_id,metering_point_id,task_type,status,priority,title,description,assigned_to,due_at,metadata,created_by,updated_by)
 VALUES(o.company_id,(b->>'customerId')::uuid,(b->>'siteId')::uuid,(b->>'meteringPointId')::uuid,'ediel_customer_life_event','open','normal','Anmäld kundlivshändelse behöver följas upp','Önskad förändring har registrerats. Mottagen Z06 får en egen källbunden kundversion.',o.actor_user_id,NULL,jsonb_build_object('sourceMessageId',NEW.id,'ruleId','TM-Z09-E','sourceKind','desired_customer_change','informationKnownAt',b->>'informationKnownAt','classification',b->>'classification'),o.actor_user_id,o.actor_user_id) RETURNING id INTO task_id;
 INSERT INTO gridex_customer_life_events.tasks(source_message_id,customer_id,operation_task_id,company_id,rule_id,information_known_at,responsible_user_id,source_kind) VALUES(NEW.id,(b->>'customerId')::uuid,task_id,o.company_id,'TM-Z09-E',(b->>'informationKnownAt')::timestamptz,o.actor_user_id,'desired_customer_change');
 RETURN NEW;
END $$;

--
-- Name: brp_objects_v1(text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.brp_objects_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE token jsonb;current_object jsonb;fragments jsonb:='[]';objects jsonb:='[]';fragment jsonb;first_object jsonb;brp text;BEGIN
 FOR token IN SELECT item FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(raw)) item LOOP
  IF token->>'tag'='LIN' THEN
   IF current_object IS NOT NULL THEN fragments:=fragments||jsonb_build_array(current_object);END IF;
   current_object:=jsonb_build_object('point',token#>>'{elements,3,0}','identityAgency',token#>>'{elements,3,3}');
  ELSIF token->>'tag'='UNT' THEN
   IF current_object IS NOT NULL THEN fragments:=fragments||jsonb_build_array(current_object);current_object:=NULL;END IF;
  ELSIF current_object IS NOT NULL AND token->>'tag'='NAD' AND token#>>'{elements,1,0}'='Z02' THEN
   IF current_object ? 'brp' OR token#>>'{elements,2,1}' IS DISTINCT FROM '160' OR token#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' OR jsonb_array_length(token#>'{elements,2}') IS DISTINCT FROM 3 THEN RETURN NULL;END IF;
   brp:=token#>>'{elements,2,0}';IF nullif(brp,'') IS NULL OR brp<>btrim(brp) OR length(brp)>35 OR brp~'[[:cntrl:]]' THEN RETURN NULL;END IF;
   current_object:=current_object||jsonb_build_object('brp',brp);
  END IF;
 END LOOP;
 IF current_object IS NOT NULL THEN fragments:=fragments||jsonb_build_array(current_object);END IF;
 FOR fragment IN SELECT item FROM jsonb_array_elements(fragments)item LOOP
  IF nullif(fragment->>'point','') IS NULL OR (fragment->>'identityAgency' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  SELECT item INTO first_object FROM jsonb_array_elements(objects)item WHERE item->>'point'=fragment->>'point' AND item->>'identityAgency'=fragment->>'identityAgency';
  IF first_object IS NOT NULL THEN
   IF fragment ? 'brp' AND fragment->>'brp' IS DISTINCT FROM first_object->>'brp' THEN RETURN NULL;END IF;
  ELSE
   IF nullif(fragment->>'brp','') IS NULL THEN RETURN NULL;END IF;
   objects:=objects||jsonb_build_array(fragment);
  END IF;
 END LOOP;
 IF jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;RETURN objects;
END$$;

--
-- Name: certification_basis_before_case_tuple_v1(jsonb, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.certification_basis_before_case_tuple_v1(q jsonb, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_customer_life_events.certification_classifications%rowtype;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF q IS NULL OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR(q->>'expectedOutcome' IN('positive','negative')) IS NOT TRUE THEN RETURN NULL;END IF;
 IF(SELECT count(*) FROM gridex_customer_life_events.certification_classifications x WHERE x.company_id::text=q->>'companyId' AND x.registration_id::text=q->>'registrationId' AND x.expected_outcome=q->>'expectedOutcome'
  AND x.valid_until>clock_timestamp() AND NOT EXISTS(SELECT FROM gridex_customer_life_events.certification_classification_revocations r WHERE r.declaration_id=x.id))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['independent_authentic_certification_customer_event_classification']);END IF;
 SELECT * INTO d FROM gridex_customer_life_events.certification_classifications x WHERE x.company_id::text=q->>'companyId' AND x.registration_id::text=q->>'registrationId' AND x.expected_outcome=q->>'expectedOutcome'
  AND x.valid_until>clock_timestamp() AND NOT EXISTS(SELECT FROM gridex_customer_life_events.certification_classification_revocations r WHERE r.declaration_id=x.id) FOR SHARE;
 IF d.workbook_original IS NULL OR d.classification_original IS NULL OR encode(sha256(d.workbook_original),'hex') IS DISTINCT FROM d.workbook_sha256 OR encode(sha256(d.classification_original),'hex') IS DISTINCT FROM d.classification_sha256 OR gridex_ediel_retention.protected_copy_current_v1(d.company_id,d.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['actual_retained_certification_classification_originals']);END IF; IF EXISTS(SELECT FROM gridex_customer_life_events.certification_classification_revocations r WHERE r.declaration_id=d.id) OR d.run_id::text IS DISTINCT FROM q->>'runId' OR d.role_code IS DISTINCT FROM q->>'roleCode' OR d.case_code IS DISTINCT FROM q->>'caseCode' OR d.suite IS DISTINCT FROM q->>'suite' OR d.revision IS DISTINCT FROM q->>'revision' OR d.step_no::text IS DISTINCT FROM q->>'stepNo'
  OR d.wire_sha256 IS DISTINCT FROM q->>'wireSha256' OR d.original_file_sha256 IS DISTINCT FROM q->>'originalFileSha256' OR d.valid_until>(q->>'validUntil')::timestamptz
  OR gridex_customer_life_events.certification_selection_v1(d.classification,d.selection,raw,d.workbook_sha256,d.classification_sha256) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_registered_original_classification_workbook_and_whole_object_scope']);END IF;
 RETURN jsonb_build_object('status','authorized','sourceKind','independently_classified_fixture','authorizesBusinessEffect',false,'companyId',d.company_id,'environment','test','code','Z09','rawPayload',raw,
  'declarationId',d.id,'sourceVersion',d.source_version,'sourceDigest',d.classification_sha256,'sourceReference',d.source_reference,'classification',d.classification,'selection',d.selection,
  'fixtureRegistrationId',d.registration_id,'runId',d.run_id,'expectedOutcome',d.expected_outcome,'expectedDiagnosticCodes',q->'expectedDiagnosticCodes');
END$$;

--
-- Name: certification_basis_v1(jsonb, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.certification_basis_v1(q jsonb, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE b jsonb;BEGIN
 b:=gridex_customer_life_events.certification_basis_before_case_tuple_v1(q,raw);
 IF b->>'status'='authorized' THEN RETURN b||jsonb_build_object('registeredCase',jsonb_build_object('roleCode',q->>'roleCode','caseCode',q->>'caseCode','suite',q->>'suite','revision',q->>'revision','stepNo',(q->>'stepNo')::integer));END IF;RETURN b;
END$$;

--
-- Name: certification_selection_v1(text, jsonb, text, text, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.certification_selection_v1(classification text, selection jsonb, raw text, workbook_hash text, decision_hash text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wire jsonb;own jsonb;fact jsonb;seen jsonb:='[]';BEGIN
 wire:=gridex_customer_life_events.wire_partition_v1(raw);
 IF wire IS NULL OR wire->>'family' IS DISTINCT FROM 'PRODAT' OR wire->>'code' IS DISTINCT FROM 'Z09' OR jsonb_typeof(selection) IS DISTINCT FROM 'object' OR selection#>>'{source,kind}' IS DISTINCT FROM 'caller_selection'
  OR jsonb_typeof(selection->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(selection->'objects') IS DISTINCT FROM jsonb_array_length(wire->'objects') OR(classification IN('death','bankruptcy','other_masterdata')) IS NOT TRUE THEN RETURN false;END IF;
 FOR own IN SELECT item FROM jsonb_array_elements(wire->'objects')item LOOP
  IF nullif(own->>'point','') IS NULL OR(own->>'identityAgency' IN('9','89')) IS NOT TRUE OR own->>'reason' IS DISTINCT FROM 'E34' OR nullif(own->>'li','') IS NULL THEN RETURN false;END IF;
  IF(SELECT count(*) FROM jsonb_array_elements(selection->'objects')f WHERE f#>>'{installation,id}'=own->>'point' AND f#>>'{installation,agency}'=own->>'identityAgency')<>1 THEN RETURN false;END IF;
  SELECT f INTO fact FROM jsonb_array_elements(selection->'objects')f WHERE f#>>'{installation,id}'=own->>'point' AND f#>>'{installation,agency}'=own->>'identityAgency';
  IF seen@>jsonb_build_array(fact->'objectKey') OR nullif(fact->>'objectKey','') IS NULL OR fact#>>'{process,code}' IS DISTINCT FROM 'Z09' OR fact#>>'{process,reason}' IS DISTINCT FROM 'E34' OR fact->>'lineItemReference' IS DISTINCT FROM own->>'li'
   OR fact#>>'{customer,kind}' IS DISTINCT FROM 'test_customer' OR fact#>>'{customer,workbookSha256}' IS DISTINCT FROM workbook_hash OR nullif(fact#>>'{customer,sheet}','') IS NULL OR nullif(fact#>>'{customer,entityLabel}','') IS NULL
   OR fact#>>'{legalSupplier,id}' IS DISTINCT FROM wire->>'legalSender' OR fact#>>'{legalSupplier,qualifier}' IS DISTINCT FROM '160' OR fact#>>'{legalSupplier,agency}' IS DISTINCT FROM 'SVK'
   OR fact#>>'{legalGridOwner,id}' IS DISTINCT FROM wire->>'legalReceiver' OR fact#>>'{legalGridOwner,qualifier}' IS DISTINCT FROM '160' OR fact#>>'{legalGridOwner,agency}' IS DISTINCT FROM 'SVK'
   OR fact#>>'{event,key}' IS DISTINCT FROM fact#>>'{event,eventKey}' OR nullif(fact#>>'{event,key}','') IS NULL OR fact#>>'{event,revision}' IS DISTINCT FROM decision_hash
   OR fact#>>'{assessment,kind}' IS DISTINCT FROM 'known' OR fact#>>'{assessment,value}' IS DISTINCT FROM (CASE classification WHEN 'death' THEN 'death' ELSE 'not_death' END)
   OR fact#>>'{assessment,evidence,eventKey}' IS DISTINCT FROM fact#>>'{event,eventKey}' OR fact#>>'{assessment,evidence,revision}' IS DISTINCT FROM decision_hash THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(fact->'objectKey');
 END LOOP;RETURN true;
EXCEPTION WHEN data_exception THEN RETURN false;END$$;

--
-- Name: classification_scope_v1(); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.classification_scope_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE source uuid;BEGIN
 IF TG_TABLE_NAME='classification_revocations' THEN SELECT source_message_id INTO source FROM gridex_customer_life_events.inbound_classifications WHERE id=NEW.classification_id;ELSE source:=NEW.source_message_id;END IF;
 PERFORM id FROM public.ediel_messages WHERE id=source FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'customer_event_classification_source_required';END IF;RETURN NEW;END$$;

--
-- Name: inbound_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.inbound_basis_v1(c uuid, mid uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;g gridex_customer_life_events.inbound_grounds%rowtype;ba public.tenant_bilateral_agreements%rowtype;
 classification_record gridex_customer_life_events.inbound_classifications%rowtype;classification_scope jsonb;local_legal jsonb;wire jsonb;own jsonb;scope jsonb;basis jsonb;scopes jsonb:='[]';facts jsonb:='[]';plans jsonb:='[]';ids uuid[];periods uuid[];period_manifest jsonb;classes text[]:=ARRAY[]::text[];
 held_objects jsonb:='[]';missing text;point public.metering_points%rowtype;period public.customer_supply_periods%rowtype;kind text;fields text[];matches uuid[];
BEGIN IF gridex_ediel_retention.classification_copy_source_current_v1(c,mid) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','companyId',c,'messageId',mid,'missing',ARRAY['classification_original_copy_retained_history_only']);END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR UPDATE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' THEN RETURN NULL;END IF;
 wire:=gridex_customer_life_events.wire_partition_v1(m.raw_payload);
 IF wire IS NULL THEN RETURN NULL;END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(c,actor,'prepare');
 local_legal:=gridex_ediel_inbound_context.require_v1(c,mid);
 IF local_legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR local_legal->>'legalEdielId' IS DISTINCT FROM wire->>'legalReceiver' OR local_legal->>'family' IS DISTINCT FROM 'PRODAT' OR local_legal->>'code' IS DISTINCT FROM 'Z06' THEN RAISE EXCEPTION 'customer_life_event_frozen_receiver_required';END IF;
 IF EXISTS(SELECT FROM gridex_bilateral_customer_sources.life_event_classification_origins WHERE company_id=c AND source_message_id=mid) AND gridex_bilateral_customer_sources.classification_current_v1(c,mid) IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_independent_classified_customer_source']);END IF;
 SELECT * INTO g FROM gridex_customer_life_events.inbound_grounds WHERE source_message_id=mid AND company_id=c FOR SHARE;
 IF g.source_message_id IS NOT NULL THEN
  IF g.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR g.approved_at>clock_timestamp() OR jsonb_typeof(g.approved_scope) IS DISTINCT FROM 'array' OR jsonb_array_length(g.approved_scope) IS DISTINCT FROM jsonb_array_length(wire->'objects') THEN RAISE EXCEPTION 'customer_life_event_exact_bilateral_source_scope_required';END IF;
  SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=g.bilateral_agreement_id AND company_id=c AND environment=m.environment FOR SHARE;
  PERFORM pi.id FROM public.platform_actor_identifiers pi WHERE pi.actor_id=ba.counterparty_actor_id FOR SHARE;
  IF ba.id IS NULL OR ba.is_enabled IS DISTINCT FROM true OR ba.valid_from IS NULL OR ba.valid_from>clock_timestamp() OR ba.valid_to IS NOT NULL AND ba.valid_to<clock_timestamp()
   OR ba.capability_code IS DISTINCT FROM g.bilateral_capability_code OR ba.source_reference IS DISTINCT FROM g.bilateral_source_reference OR encode(sha256(convert_to(ba.terms::text,'UTF8')),'hex') IS DISTINCT FROM g.bilateral_terms_sha256
   OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers pi WHERE pi.actor_id=ba.counterparty_actor_id AND pi.identifier_type='EdielId' AND pi.identifier_value=wire->>'legalSender' AND pi.is_verified AND (pi.valid_from IS NULL OR pi.valid_from<=current_date) AND (pi.valid_to IS NULL OR current_date<=pi.valid_to)) THEN RAISE EXCEPTION 'customer_life_event_current_bilateral_source_required';END IF;
 END IF;
 -- Discover every own source before locking any point/period/customer. All
 -- selectors are subsequently requalified by the single immutable supply owner.
 SELECT array_agg(DISTINCT p.id) INTO periods FROM public.customer_supply_periods p JOIN public.metering_points mp ON mp.id=p.metering_point_id AND mp.company_id=c
 WHERE p.company_id=c AND mp.grid_owner_ediel_id=wire->>'legalSender' AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''))=o->>'point' AND mp.grid_area_code=o->>'gridArea');
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO period_manifest FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(periods);
 SELECT array_agg(DISTINCT source_id) INTO ids FROM (
  SELECT p.source_message_id source_id FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(periods)
  UNION SELECT tr.source_message_id FROM gridex_received_sources.supply_source_transitions tr,public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(periods) AND tr.company_id=c AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'market_state_version'=p.market_state_version::text)
  UNION SELECT proof.source_message_id FROM gridex_received_sources.normal_switch_confirmations proof WHERE proof.company_id=c AND proof.period_id=ANY(periods)
  UNION SELECT proof.original_message_id FROM gridex_received_sources.normal_switch_confirmations proof WHERE proof.company_id=c AND proof.period_id=ANY(periods)
 ) sources;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=c AND z.id=ANY(ids) ORDER BY z.id FOR UPDATE;
 PERFORM p.id FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(periods) ORDER BY p.id FOR SHARE;
 IF (SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(periods)) IS DISTINCT FROM period_manifest THEN RAISE EXCEPTION 'customer_life_event_source_discovery_changed' USING ERRCODE='40001';END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(wire->'objects') ORDER BY value->>'point' LOOP
  IF own->>'projectionHeld'='true' OR own->>'reason' IS DISTINCT FROM 'E34' OR nullif(own->>'point','') IS NULL OR(own->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(own->>'li','') IS NULL OR own->>'effectiveAt' IS NULL OR(own#>>'{customerParty,1}' IN('SE1','SE2')) IS NOT TRUE OR own#>>'{customerParty,2}' IS DISTINCT FROM '260' THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['own_complete_customer_event_projection']));CONTINUE;END IF;
  matches:=ARRAY[]::uuid[];
  FOR period IN SELECT p.* FROM public.customer_supply_periods p JOIN public.metering_points mp ON mp.id=p.metering_point_id AND mp.company_id=c WHERE p.company_id=c AND p.id=ANY(periods) AND coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''))=own->>'point' AND mp.grid_area_code=own->>'gridArea' ORDER BY p.id LOOP
   basis:=gridex_received_sources.supply_period_source_at_v1(c,period.id,(own->>'effectiveAt')::timestamptz);
   IF basis->>'qualified'='true' AND basis->>'legalActorId'=local_legal->>'legalActorId' AND basis->>'dsoEdielId'=wire->>'legalSender' AND EXISTS(SELECT FROM jsonb_array_elements(basis->'sourceObjects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'gridArea'=own->>'gridArea') THEN matches:=array_append(matches,period.id);END IF;
  END LOOP;
  IF cardinality(matches)<>1 THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['unique_current_owned_source_period']));CONTINUE;END IF;
  basis:=gridex_received_sources.supply_period_source_at_v1(c,matches[1],(own->>'effectiveAt')::timestamptz);
  scope:=NULL;classification_scope:=NULL;classification_record:=NULL;
  IF (SELECT count(*) FROM gridex_customer_life_events.inbound_classifications q WHERE q.company_id=c AND q.source_message_id=mid AND q.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND q.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_customer_life_events.classification_revocations r WHERE r.classification_id=q.id) AND EXISTS(SELECT FROM jsonb_array_elements(q.approved_scope)sc WHERE sc->>'pointId'=own->>'point' AND sc->>'identityAgency'=own->>'identityAgency'))<>1 THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['independent_original_customer_event_classification']));CONTINUE;END IF;
  SELECT q.* INTO classification_record FROM gridex_customer_life_events.inbound_classifications q WHERE q.company_id=c AND q.source_message_id=mid AND q.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND q.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_customer_life_events.classification_revocations r WHERE r.classification_id=q.id) AND EXISTS(SELECT FROM jsonb_array_elements(q.approved_scope)sc WHERE sc->>'pointId'=own->>'point' AND sc->>'identityAgency'=own->>'identityAgency') FOR SHARE;
  IF (SELECT count(*) FROM jsonb_array_elements(classification_record.approved_scope)sc WHERE sc->>'pointId'=own->>'point' AND sc->>'identityAgency'=own->>'identityAgency')<>1 THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['unique_independent_classified_object_scope']));CONTINUE;END IF;
  SELECT sc INTO classification_scope FROM jsonb_array_elements(classification_record.approved_scope)sc WHERE sc->>'pointId'=own->>'point' AND sc->>'identityAgency'=own->>'identityAgency';
  IF classification_scope->>'customerId' IS DISTINCT FROM basis->>'customerId' OR classification_scope->>'siteId' IS DISTINCT FROM basis->>'siteId' OR classification_scope->>'meteringPointId' IS DISTINCT FROM basis->>'meteringPointId' OR classification_scope->>'periodId' IS DISTINCT FROM basis->>'periodId' OR classification_scope->>'sourceMessageId' IS DISTINCT FROM basis->>'sourceMessageId' OR classification_scope->>'sourcePayloadHash' IS DISTINCT FROM basis->>'payloadHash' OR classification_scope->>'marketStateVersion' IS DISTINCT FROM basis->>'marketStateVersion' OR classification_scope->>'effectiveAt' IS DISTINCT FROM own->>'effectiveAt' OR classification_scope->>'lineItemReference' IS DISTINCT FROM own->>'li' THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['independent_classification_same_owned_source_tuple']));CONTINUE;END IF;
  IF g.source_message_id IS NOT NULL THEN
   IF (SELECT count(*) FROM jsonb_array_elements(g.approved_scope) approved WHERE approved->>'pointId'=own->>'point' AND approved->>'identityAgency'=own->>'identityAgency')<>1 THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['own_bilateral_source_scope']));CONTINUE;END IF;
   SELECT approved INTO scope FROM jsonb_array_elements(g.approved_scope) approved WHERE approved->>'pointId'=own->>'point' AND approved->>'identityAgency'=own->>'identityAgency';
   IF scope->>'periodId' IS DISTINCT FROM basis->>'periodId' OR scope->>'customerId' IS DISTINCT FROM basis->>'customerId' OR scope->>'siteId' IS DISTINCT FROM basis->>'siteId' OR scope->>'meteringPointId' IS DISTINCT FROM basis->>'meteringPointId' OR scope->>'sourceMessageId' IS DISTINCT FROM basis->>'sourceMessageId' OR scope->>'sourcePayloadHash' IS DISTINCT FROM basis->>'payloadHash' OR scope->>'marketStateVersion' IS DISTINCT FROM basis->>'marketStateVersion' THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['own_bilateral_period_version']));CONTINUE;END IF;
   kind:=coalesce(scope->>'classification',g.classification);fields:=g.allowed_customer_fields;
   IF kind IS DISTINCT FROM classification_record.classification OR NOT(fields<@classification_record.allowed_customer_fields) THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['same_independent_bilateral_classification']));CONTINUE;END IF;
  ELSE kind:=classification_record.classification;fields:=classification_record.allowed_customer_fields;
   IF kind IS DISTINCT FROM 'death' OR NOT(fields<@ARRAY['228','229','231','232','310','316']::text[]) THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['separate_bilateral_non_death_ground']));CONTINUE;END IF;
  END IF;
  IF (kind IN('death','bankruptcy','other_masterdata')) IS NOT TRUE THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['independent_event_classification']));CONTINUE;END IF;
  IF NOT('227'=ANY(fields)) AND NOT EXISTS(SELECT FROM jsonb_array_elements(basis->'sourceObjects') o WHERE o->>'customerIdentity'=own#>>'{customerParty,0}') OR '227'=ANY(fields) AND (scope->>'targetCustomerIdentity' IS DISTINCT FROM own#>>'{customerParty,0}' OR scope->>'targetCustomerQualifier' IS DISTINCT FROM own#>>'{customerParty,1}') THEN held_objects:=held_objects||jsonb_build_array(jsonb_build_object('object',own,'missing',ARRAY['owned_end_user_identity']));CONTINUE;END IF;
  scope:=jsonb_build_object('periodId',basis->>'periodId','customerId',basis->>'customerId','siteId',basis->>'siteId','meteringPointId',basis->>'meteringPointId','pointId',own->>'point','identityAgency',own->>'identityAgency','gridArea',own->>'gridArea','sourceMessageId',basis->>'sourceMessageId','sourcePayloadHash',basis->>'payloadHash','marketStateVersion',basis->>'marketStateVersion','classification',kind,'classificationRecordId',classification_record.id,'classificationSourceHash',classification_record.classification_sha256,'allowedFields',to_jsonb(fields),'effectiveAt',own->>'effectiveAt');
  scopes:=scopes||jsonb_build_array(scope);plans:=plans||jsonb_build_array(jsonb_build_object('scope',scope,'object',own));classes:=array_append(classes,kind);
  facts:=facts||jsonb_build_array(jsonb_build_object('objectKey',scope->>'meteringPointId','installation',jsonb_build_object('id',own->>'point','agency',own->>'identityAgency'),
   'customer',jsonb_build_object('kind','domain_customer','key',scope->>'customerId','revision',scope->>'marketStateVersion','id',own#>>'{customerParty,0}','qualifier',own#>>'{customerParty,1}','agency',own#>>'{customerParty,2}'),
   'legalSupplier',jsonb_build_object('id',wire->>'legalReceiver','qualifier','160','agency','SVK'),'legalGridOwner',jsonb_build_object('id',wire->>'legalSender','qualifier','160','agency','SVK'),'process',jsonb_build_object('code','Z06','reason','E34'),
   'event',jsonb_build_object('key',m.id,'eventKey',m.id,'revision',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'reference',m.id),
   'assessment',jsonb_build_object('kind','known','value',CASE kind WHEN 'death' THEN 'death' ELSE 'not_death' END,'evidence',jsonb_build_object('key',coalesce(g.source_message_id,m.id),'eventKey',m.id,'revision',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'reference',classification_record.owner_decision_reference)),'lineItemReference',own->>'li'));
 END LOOP;
 IF jsonb_array_length(plans)=0 THEN RETURN jsonb_build_object('status','held','companyId',c,'environment',m.environment,'messageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'rawPayload',m.raw_payload,'heldObjects',held_objects,'missing',ARRAY['source_qualified_customer_event_object']);END IF;
 RETURN jsonb_build_object('status','authorized','companyId',c,'environment',m.environment,'messageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'rawPayload',m.raw_payload,'legalContext',local_legal,'classification',CASE WHEN (SELECT count(DISTINCT x) FROM unnest(classes) x)=1 THEN classes[1] ELSE 'other_masterdata' END,'bilateralCapabilityVerified',g.source_message_id IS NOT NULL,'scopes',scopes,'plans',plans,'physicalObjects',wire->'objects','heldObjects',held_objects,'selection',jsonb_build_object('source',jsonb_build_object('kind','caller_selection','reference',coalesce(g.source_reference,m.id::text)),'objects',facts));
END$$;

--
-- Name: inbound_context_object_is_qualified_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.inbound_context_object_is_qualified_v1(c uuid, source_id uuid, receipt_id uuid, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_customer_life_events.inbound_context_receipts%rowtype;m public.ediel_messages%rowtype;own jsonb;BEGIN
 SELECT * INTO r FROM gridex_customer_life_events.inbound_context_receipts WHERE id=receipt_id AND company_id=c AND source_message_id=source_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 IF r.id IS NULL OR m.id IS NULL OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR r.context_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.context_facts::text,'UTF8')),'hex') OR r.context_facts->>'rawPayload' IS DISTINCT FROM m.raw_payload OR r.context_facts#>>'{legalContext,actorRole}' IS DISTINCT FROM 'electricity_supplier' OR r.context_facts#>>'{legalContext,legalEdielId}' IS DISTINCT FROM gridex_customer_life_events.wire_partition_v1(m.raw_payload)->>'legalReceiver' OR object_scope->>'messageIndex' IS DISTINCT FROM '0' OR object_scope->>'messageReference' IS DISTINCT FROM gridex_customer_life_events.wire_partition_v1(m.raw_payload)->>'unh' THEN RETURN false;END IF;
 SELECT p->'object' INTO own FROM jsonb_array_elements(r.context_facts->'plans')p WHERE p#>>'{object,point}'=object_scope->>'objectId' AND p#>>'{object,identityAgency}'=object_scope->>'identityAgency' AND p#>>'{object,firstLineIndex}'=object_scope#>>'{registers,0,segmentIndex}';
 RETURN own IS NOT NULL AND(SELECT jsonb_agg((reg->>'segmentIndex')::integer ORDER BY(reg->>'segmentIndex')::integer) FROM jsonb_array_elements(object_scope->'registers')reg)=(SELECT jsonb_agg(value ORDER BY(value#>>'{}')::integer) FROM jsonb_array_elements(own->'lineIndexes')value);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END$$;

--
-- Name: lock_certification_revocation_v1(); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.lock_certification_revocation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM gridex_customer_life_events.certification_classifications WHERE id=NEW.declaration_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'customer_event_certification_declaration_required';END IF;RETURN NEW;END$$;

--
-- Name: owner_proof_consistent_v1(jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.owner_proof_consistent_v1(party jsonb, business jsonb, mid uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tr gridex_customer_life_events.transitions%rowtype;m public.ediel_messages%rowtype;scope jsonb;version_row gridex_customer_life_events.customer_versions%rowtype;BEGIN IF gridex_ediel_retention.classification_copy_source_current_v1(NULL,mid) IS NOT TRUE THEN RETURN false;END IF;
 IF EXISTS(SELECT FROM gridex_bilateral_customer_sources.life_event_classification_origins WHERE source_message_id=mid) AND gridex_bilateral_customer_sources.classification_current_v1((SELECT company_id FROM public.ediel_messages WHERE id=mid),mid) IS NULL THEN RETURN false;END IF;

 SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=mid;
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=tr.company_id;
 SELECT s INTO scope FROM jsonb_array_elements(tr.approved_scope) s WHERE s->>'pointId'=business#>>'{object,objectId}' AND s->>'identityAgency'=business#>>'{object,identityAgency}';
 SELECT * INTO version_row FROM gridex_customer_life_events.customer_versions WHERE source_message_id=mid AND company_id=tr.company_id AND customer_id=(scope->>'customerId')::uuid;
 IF tr.source_message_id IS NULL OR m.id IS NULL OR scope IS NULL OR version_row.customer_id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR business->>'owner' IS DISTINCT FROM 'inbound-customer-life-event-v1' OR business->>'businessDisposition' IS DISTINCT FROM 'committed' OR business->>'coverage' IS DISTINCT FROM 'committed_customer_version_only' OR business->>'graphNamespace' IS DISTINCT FROM 'source_bound_customer_history' OR business->>'sourceDisposition' IS DISTINCT FROM 'not_established'
  OR business->>'companyId' IS DISTINCT FROM tr.company_id::text OR business->>'environment' IS DISTINCT FROM m.environment OR business->>'sourceMessageId' IS DISTINCT FROM mid::text OR business->>'sourcePayloadHash' IS DISTINCT FROM tr.payload_hash OR business->>'customerId' IS DISTINCT FROM scope->>'customerId' OR business->>'siteId' IS DISTINCT FROM scope->>'siteId' OR business->>'meteringPointId' IS DISTINCT FROM scope->>'meteringPointId' OR business->>'classification' IS DISTINCT FROM scope->>'classification' OR business->>'customerVersion' IS DISTINCT FROM version_row.version::text OR (business->>'effectiveAt')::timestamptz IS DISTINCT FROM version_row.effective_at OR (scope->>'effectiveAt')::timestamptz IS DISTINCT FROM version_row.effective_at
  OR party->'frozenLegalContext' IS DISTINCT FROM tr.legal_context OR party->'object' IS DISTINCT FROM business->'object' OR party->>'owner' IS DISTINCT FROM 'received-source-party-binding-v1' OR party->>'ruleVersion' IS DISTINCT FROM '1' OR party->>'disposition' IS DISTINCT FROM 'accepted' OR party->'reasons' IS DISTINCT FROM '[]'::jsonb
  OR party#>>'{source,companyId}' IS DISTINCT FROM tr.company_id::text OR party#>>'{source,environment}' IS DISTINCT FROM m.environment OR party#>>'{source,sourceMessageId}' IS DISTINCT FROM mid::text OR party#>>'{source,sourcePayloadHash}' IS DISTINCT FROM tr.payload_hash
  OR tr.legal_context->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR tr.legal_context->>'legalEdielId' IS DISTINCT FROM gridex_customer_life_events.wire_partition_v1(m.raw_payload)->>'legalReceiver'
  OR NOT EXISTS(SELECT FROM gridex_customer_life_events.inbound_classifications q WHERE q.company_id=tr.company_id AND q.source_message_id=mid AND q.id::text=scope->>'classificationRecordId' AND q.classification=scope->>'classification' AND q.classification_sha256=scope->>'classificationSourceHash' AND q.source_payload_hash=tr.payload_hash AND q.recorded_at<=tr.recorded_at)
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_customers) result WHERE result=version_row.resulting_customer) OR NOT EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) own WHERE own->>'point'=scope->>'pointId' AND own->>'identityAgency'=scope->>'identityAgency') THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END$$;

--
-- Name: prelock_recovery_lineage_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.prelock_recovery_lineage_v1(c uuid, mid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE operation uuid;lineage jsonb;
BEGIN
 SELECT op.id INTO operation FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations op ON op.id=link.operation_id WHERE link.message_id=mid AND op.company_id=c;
 IF operation IS NULL THEN RETURN;END IF;
 lineage:=gridex_customer_life_events.recovery_lineage_v1(c,operation);
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND (m.id=mid OR m.id IN(SELECT value::uuid FROM jsonb_array_elements_text(lineage->'sourceIds'))) ORDER BY m.id FOR UPDATE;
END$$;

--
-- Name: publish_certification_v1(jsonb, bytea, bytea, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.publish_certification_v1(context jsonb, workbook bytea, decision bytea, publisher text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;raw text;reg jsonb;result uuid;prior gridex_customer_life_events.certification_classifications%rowtype;BEGIN
 IF publisher IS DISTINCT FROM 'gridex_ediel_fixture_authority_owner' OR workbook IS NULL OR decision IS NULL OR octet_length(workbook) NOT BETWEEN 1 AND 10485760 OR octet_length(decision) NOT BETWEEN 1 AND 10485760
  OR nullif(context->>'sourceReference','') IS NULL OR nullif(context->>'sourceVersion','') IS NULL OR nullif(context->>'ownerDecisionReference','') IS NULL OR(context->>'expectedOutcome' IN('positive','negative')) IS NOT TRUE THEN RAISE EXCEPTION 'customer_event_independent_certification_originals_required';END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1((context->>'actorUserId')::uuid,(context->>'companyId')::uuid);
 IF context->>'expectedOutcome'='positive' THEN SELECT to_jsonb(f) INTO reg FROM gridex_negative_fixtures.positive_originals f WHERE id=(context->>'registrationId')::uuid AND company_id=(context->>'companyId')::uuid FOR SHARE;
 ELSE SELECT to_jsonb(f) INTO reg FROM gridex_negative_fixtures.originals f WHERE id=(context->>'registrationId')::uuid AND company_id=(context->>'companyId')::uuid FOR SHARE;END IF;
 IF reg IS NULL THEN RAISE EXCEPTION 'customer_event_genuine_certification_registration_required';END IF;raw:=reg->>'original_wire';
 IF context->>'expectedOutcome'='positive' THEN q:=gridex_negative_fixtures.read_positive_v1(jsonb_build_object('companyId',context->>'companyId','runId',reg->>'run_id','stepNo',reg->>'step_no','actorUserId',context->>'actorUserId','rawPayload',raw));
 ELSE q:=gridex_negative_fixtures.read_negative_preparation_v1(jsonb_build_object('companyId',context->>'companyId','runId',reg->>'run_id','stepNo',reg->>'step_no','actorUserId',context->>'actorUserId','rawPayload',raw));END IF;
 IF q->>'registrationId' IS DISTINCT FROM context->>'registrationId' OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' OR(context->>'validUntil')::timestamptz<=clock_timestamp() OR(context->>'validUntil')::timestamptz>(q->>'validUntil')::timestamptz
  OR gridex_customer_life_events.certification_selection_v1(context->>'classification',context->'selection',raw,encode(sha256(workbook),'hex'),encode(sha256(decision),'hex')) IS NOT TRUE THEN RAISE EXCEPTION 'customer_event_same_registered_independent_classification_required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('customer-event-certification|'||(context->>'companyId')||'|'||(context->>'registrationId'),0));
 SELECT * INTO prior FROM gridex_customer_life_events.certification_classifications WHERE company_id=(context->>'companyId')::uuid AND registration_id=(context->>'registrationId')::uuid AND expected_outcome=context->>'expectedOutcome' AND source_reference=context->>'sourceReference' AND source_version=context->>'sourceVersion' FOR SHARE;
 IF FOUND THEN
  IF prior.classification IS DISTINCT FROM context->>'classification' OR prior.selection IS DISTINCT FROM context->'selection' OR prior.workbook_original IS DISTINCT FROM workbook OR prior.classification_original IS DISTINCT FROM decision OR prior.owner_decision_reference IS DISTINCT FROM context->>'ownerDecisionReference' OR prior.valid_until IS DISTINCT FROM(context->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'customer_event_certification_immutable_source_conflict';END IF;RETURN prior.id;
 END IF;
 IF EXISTS(SELECT FROM gridex_customer_life_events.certification_classifications d WHERE d.company_id=(context->>'companyId')::uuid AND d.registration_id=(context->>'registrationId')::uuid AND d.expected_outcome=context->>'expectedOutcome' AND NOT EXISTS(SELECT FROM gridex_customer_life_events.certification_classification_revocations r WHERE r.declaration_id=d.id)) THEN RAISE EXCEPTION 'customer_event_certification_classification_already_published';END IF;
 INSERT INTO gridex_customer_life_events.certification_classifications(company_id,registration_id,expected_outcome,run_id,role_code,case_code,suite,revision,step_no,wire_sha256,original_file_sha256,classification,selection,workbook_original,workbook_sha256,classification_original,classification_sha256,source_reference,source_version,owner_decision_reference,valid_until,published_by)
 VALUES((q->>'companyId')::uuid,(q->>'registrationId')::uuid,q->>'expectedOutcome',(q->>'runId')::uuid,q->>'roleCode',q->>'caseCode',q->>'suite',q->>'revision',(q->>'stepNo')::integer,q->>'wireSha256',q->>'originalFileSha256',context->>'classification',context->'selection',workbook,encode(sha256(workbook),'hex'),decision,encode(sha256(decision),'hex'),context->>'sourceReference',context->>'sourceVersion',context->>'ownerDecisionReference',(context->>'validUntil')::timestamptz,(context->>'actorUserId')::uuid) RETURNING id INTO result;RETURN result;
END$$;

--
-- Name: qualified_patches_v1(uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.qualified_patches_v1(c uuid, customer uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_cutoff timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_customer_life_events.customer_versions%rowtype;tr gridex_customer_life_events.transitions%rowtype;a gridex_received_sources.object_assessments%rowtype;scope jsonb;entry jsonb;own jsonb;fields text[];patch jsonb;address jsonb;n text;patches jsonb:='[]';available_at timestamptz;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff>statement_timestamp() THEN RAISE EXCEPTION 'customer_life_event_patch_cutoff_required';END IF;
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to THEN RAISE EXCEPTION 'customer_life_event_boundary_period_required';END IF;
 IF NOT EXISTS(SELECT FROM public.customers WHERE id=customer AND company_id=c) THEN RAISE EXCEPTION 'customer_life_event_projection_tenant_scope_required';END IF;
 IF (SELECT count(*) FROM gridex_customer_life_events.customer_versions WHERE company_id=c AND customer_id=customer AND effective_at>=p_from AND effective_at<p_to)>1000 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_customer_event_patch_window_capacity']);END IF;
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(SELECT source_message_id FROM gridex_customer_life_events.customer_versions WHERE company_id=c AND customer_id=customer AND effective_at>=p_from AND effective_at<p_to) ORDER BY m.id FOR UPDATE;
 FOR v IN SELECT * FROM gridex_customer_life_events.customer_versions WHERE company_id=c AND customer_id=customer AND effective_at>=p_from AND effective_at<p_to ORDER BY effective_at,version LOOP
  SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=v.source_message_id AND company_id=c;
  IF (SELECT count(*) FROM gridex_received_sources.object_assessments x WHERE x.company_id=c AND x.source_message_id=v.source_message_id AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=x.id))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_primary_customer_event_owner']);END IF;
  SELECT x.* INTO a FROM gridex_received_sources.object_assessments x JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=x.id AND w.company_id=x.company_id AND w.environment=x.environment AND w.source_message_id=x.source_message_id AND w.facts_hash=x.facts_hash WHERE x.company_id=c AND x.source_message_id=v.source_message_id AND x.source_payload_hash=tr.payload_hash AND x.facts_hash=encode(sha256(convert_to(x.facts_text,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=x.id);
  SELECT observed_at INTO available_at FROM gridex_received_sources.object_availability_witnesses WHERE assessment_id=a.id;
  IF tr.recorded_at>p_cutoff OR a.assessed_at>p_cutoff OR available_at>p_cutoff THEN RETURN jsonb_build_object('status','held','missing',ARRAY['customer_event_available_at_same_export_cutoff']);END IF;
  IF a.id IS NULL OR jsonb_typeof(a.facts_text::jsonb->'objects') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['committed_primary_customer_event_availability']);END IF;
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(tr.approved_scope) sc WHERE sc->>'customerId'=customer::text AND (sc->>'effectiveAt')::timestamptz=v.effective_at) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_customer_event_version_effect']);END IF;
  FOR scope IN SELECT item FROM jsonb_array_elements(tr.approved_scope)item WHERE item->>'customerId'=customer::text LOOP
   IF (SELECT count(*) FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=scope->>'pointId' AND obj#>>'{object,identityAgency}'=scope->>'identityAgency')<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_customer_event_primary_scope']);END IF;
   SELECT obj INTO entry FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=scope->>'pointId' AND obj#>>'{object,identityAgency}'=scope->>'identityAgency';
   IF entry->>'disposition' IS DISTINCT FROM 'accepted' OR gridex_customer_life_events.owner_proof_consistent_v1(entry->'party',entry->'business',v.source_message_id) IS DISTINCT FROM true THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_qualified_customer_event_projection']);END IF;
  END LOOP;
  -- SAME first-effect owner already required identical changed tuples for all
  -- physical objects of this customer. Selecting that immutable tuple is not a
  -- conflict-resolution or chronology decision in this projection.
  SELECT item INTO scope FROM jsonb_array_elements(tr.approved_scope)item WHERE item->>'customerId'=customer::text LIMIT 1;
  SELECT item INTO own FROM jsonb_array_elements(tr.source_objects)item WHERE item->>'point'=scope->>'pointId' AND item->>'identityAgency'=scope->>'identityAgency';
  SELECT array_agg(f) INTO fields FROM jsonb_array_elements_text(scope->'allowedFields')f;patch:='{}';address:='{}';
  IF '228'=ANY(fields) AND jsonb_typeof(own->'name')='array' THEN SELECT string_agg(part,' ' ORDER BY ord) INTO n FROM jsonb_array_elements_text(own->'name') WITH ORDINALITY x(part,ord);patch:=patch||jsonb_build_object('name',n,'full_name',n);IF own#>>'{customerParty,1}'='SE1' THEN patch:=patch||jsonb_build_object('company_name',n);END IF;address:=address||jsonb_build_object('name',own->'name');END IF;
  IF '227'=ANY(fields) THEN patch:=patch||jsonb_build_object(CASE own#>>'{customerParty,1}' WHEN 'SE1' THEN 'org_number' ELSE 'personal_number' END,own#>>'{customerParty,0}');END IF;
  IF '229'=ANY(fields) AND jsonb_typeof(own->'street')='array' THEN address:=address||jsonb_build_object('street',own->'street');END IF;
  IF '231'=ANY(fields) AND own->>'postCode' IS NOT NULL THEN address:=address||jsonb_build_object('postCode',own->>'postCode');END IF;
  IF '232'=ANY(fields) AND own->>'city' IS NOT NULL THEN address:=address||jsonb_build_object('city',own->>'city');END IF;
  IF '316'=ANY(fields) AND own->>'country' IS NOT NULL THEN address:=address||jsonb_build_object('country',own->>'country');END IF;
  patches:=patches||jsonb_build_array(jsonb_build_object('effectiveAt',v.effective_at,'sourceMessageId',v.source_message_id,'sourcePayloadHash',tr.payload_hash,'customerVersion',v.version,'primaryAssessmentId',a.id,'primaryFactsHash',a.facts_hash,'appliedAt',tr.recorded_at,'availableAt',greatest(a.assessed_at,available_at),'customerFields',patch,'endUserMasterdata',address));
 END LOOP;
 RETURN jsonb_build_object('status','authorized','companyId',c,'customerId',customer,'from',p_from,'to',p_to,'cutoff',p_cutoff,'authorizesInitialCustomer',false,'patches',patches);
END$$;

--
-- Name: recovery_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.recovery_basis_v1(c uuid, operation uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;qualified jsonb;op gridex_received_sources.prodat_recovery_operations%rowtype;lineage jsonb;step jsonb;original gridex_customer_life_events.originals%rowtype;
 base public.ediel_messages%rowtype;immediate public.ediel_messages%rowtype;alias_message public.ediel_messages%rowtype;previous public.ediel_messages%rowtype;
 b jsonb;corrected jsonb;source_wire jsonb;alias_wire jsonb;previous_wire jsonb;obj jsonb;facts jsonb:='[]';
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 IF(phase IN('prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'customer_life_event_recovery_phase_required';END IF;
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=operation AND company_id=c;
 lineage:=gridex_customer_life_events.recovery_lineage_v1(c,operation);IF lineage IS NULL THEN RETURN NULL;END IF;
 -- Immutable links discover the entire source/negative-ACK cohort before any
 -- current classified event/customer/contract qualification or dependent lock.
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(SELECT value::uuid FROM jsonb_array_elements_text(lineage->'sourceIds')) ORDER BY m.id FOR UPDATE;
 IF gridex_customer_life_events.recovery_lineage_v1(c,operation) IS DISTINCT FROM lineage THEN RAISE EXCEPTION 'customer_life_event_recovery_lineage_changed';END IF;
 q:=public.ediel_prodat_recovery_operation_basis_v1(c,operation,actor);
 IF q IS NULL OR q->>'operationId' IS DISTINCT FROM op.id::text OR q->>'originalMessageId' IS DISTINCT FROM op.original_message_id::text OR q->>'correctedPayloadHash' IS DISTINCT FROM op.corrected_payload_hash THEN RAISE EXCEPTION 'customer_life_event_recovery_operation_required';END IF;
 SELECT * INTO original FROM gridex_customer_life_events.originals WHERE message_id=(lineage->>'classifiedOriginalMessageId')::uuid AND company_id=c;
 SELECT * INTO base FROM public.ediel_messages WHERE id=original.message_id AND company_id=c;
 SELECT * INTO immediate FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=c;
 IF base.id IS NULL OR immediate.id IS NULL OR base.environment IS DISTINCT FROM op.environment OR immediate.environment IS DISTINCT FROM op.environment
  OR base.direction IS DISTINCT FROM 'outbound' OR base.message_family IS DISTINCT FROM 'PRODAT' OR base.message_code IS DISTINCT FROM 'Z09'
  OR immediate.direction IS DISTINCT FROM 'outbound' OR immediate.message_family IS DISTINCT FROM 'PRODAT' OR immediate.message_code IS DISTINCT FROM 'Z09'
  OR original.payload_hash IS DISTINCT FROM encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex') OR base.immutable_payload_hash IS DISTINCT FROM original.payload_hash OR base.immutable_rendered_at IS NULL
  OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(immediate.raw_payload,'UTF8')),'hex') OR immediate.immutable_payload_hash IS DISTINCT FROM op.original_payload_hash OR immediate.immutable_rendered_at IS NULL THEN RAISE EXCEPTION 'customer_life_event_recovery_original_source_changed';END IF;
 FOR step IN SELECT value FROM jsonb_array_elements(lineage->'steps') LOOP
  qualified:=public.ediel_prodat_recovery_original_basis_v1(c,(step->>'messageId')::uuid,actor);
  SELECT * INTO alias_message FROM public.ediel_messages WHERE id=(step->>'messageId')::uuid AND company_id=c;
  SELECT * INTO previous FROM public.ediel_messages WHERE id=(step->>'originalMessageId')::uuid AND company_id=c;
  alias_wire:=gridex_customer_life_events.wire_v1(alias_message.raw_payload);previous_wire:=gridex_customer_life_events.wire_v1(previous.raw_payload);
  IF qualified IS NULL OR qualified->>'operationId' IS DISTINCT FROM step->>'operationId' OR qualified->>'originalMessageId' IS DISTINCT FROM step->>'originalMessageId' OR qualified->>'correctedPayloadHash' IS DISTINCT FROM step->>'payloadHash'
   OR alias_message.environment IS DISTINCT FROM op.environment OR previous.environment IS DISTINCT FROM op.environment
   OR alias_message.original_message_id IS DISTINCT FROM previous.id::text OR alias_message.source_operation_id IS DISTINCT FROM step->>'operationId'
   OR alias_message.raw_payload IS NULL OR alias_message.immutable_rendered_at IS NULL OR alias_message.immutable_payload_hash IS DISTINCT FROM step->>'payloadHash' OR alias_message.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(alias_message.raw_payload,'UTF8')),'hex')
   OR alias_wire IS NULL OR previous_wire IS NULL OR alias_wire->>'code' IS DISTINCT FROM 'Z09' OR alias_wire->>'legalSender' IS DISTINCT FROM previous_wire->>'legalSender' OR alias_wire->>'legalReceiver' IS DISTINCT FROM previous_wire->>'legalReceiver'
   OR EXISTS(SELECT FROM jsonb_array_elements(alias_wire->'objects')own WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(previous_wire->'objects')approved WHERE approved=own)) THEN RAISE EXCEPTION 'customer_life_event_recovery_alias_source_changed';END IF;
 END LOOP;
 -- Today's independent classified-event source remains the SAME original owner.
 b:=gridex_customer_life_events.require_current_v1(c,base.id,actor,phase)->'basis';
 corrected:=gridex_customer_life_events.wire_v1(op.corrected_raw_payload);source_wire:=gridex_customer_life_events.wire_v1(immediate.raw_payload);
 IF b->>'status' IS DISTINCT FROM 'authorized' OR corrected IS NULL OR source_wire IS NULL OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(op.corrected_raw_payload,'UTF8')),'hex')
  OR corrected->>'code' IS DISTINCT FROM 'Z09' OR corrected->>'legalSender' IS DISTINCT FROM source_wire->>'legalSender' OR corrected->>'legalReceiver' IS DISTINCT FROM source_wire->>'legalReceiver' THEN RAISE EXCEPTION 'customer_life_event_recovery_current_source_required';END IF;
 FOR obj IN SELECT value FROM jsonb_array_elements(corrected->'objects') LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(source_wire->'objects')own WHERE own=obj) THEN RAISE EXCEPTION 'customer_life_event_recovery_approved_tuple_changed';END IF;
  facts:=facts||(SELECT coalesce(jsonb_agg(f),'[]') FROM jsonb_array_elements(b#>'{selection,objects}')f WHERE f#>>'{installation,id}'=obj->>'point' AND f#>>'{installation,agency}'=obj->>'identityAgency' AND f->>'lineItemReference'=obj->>'li');
 END LOOP;
 IF jsonb_array_length(facts) IS DISTINCT FROM jsonb_array_length(corrected->'objects') THEN RAISE EXCEPTION 'customer_life_event_recovery_whole_scope_required';END IF;
 RETURN b||jsonb_build_object('rawPayload',op.corrected_raw_payload,'recoveryOperationId',op.id,'originalMessageId',immediate.id,'classifiedOriginalMessageId',base.id,'selection',jsonb_set(b->'selection','{objects}',facts));
END$$;

--
-- Name: recovery_lineage_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.recovery_lineage_v1(c uuid, operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;prior gridex_received_sources.prodat_recovery_operations%rowtype;
 own gridex_customer_life_events.originals%rowtype;mid uuid;seen uuid[]:=ARRAY[]::uuid[];source_ids uuid[];steps jsonb:='[]';depth integer;
BEGIN
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=operation AND company_id=c;
 IF op.id IS NULL OR(op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE THEN RETURN NULL;END IF;
 mid:=op.original_message_id;source_ids:=ARRAY[mid,op.source_ack_message_id];
 FOR depth IN 1..32 LOOP
  IF mid IS NULL OR mid=ANY(seen) THEN RAISE EXCEPTION 'customer_life_event_recovery_lineage_cycle';END IF;
  seen:=array_append(seen,mid);
  SELECT * INTO own FROM gridex_customer_life_events.originals WHERE message_id=mid AND company_id=c;
  IF own.message_id IS NOT NULL THEN
   RETURN jsonb_build_object('classifiedOriginalMessageId',mid,'immediateOriginalMessageId',op.original_message_id,'steps',steps,'sourceIds',
    (SELECT jsonb_agg(x ORDER BY x) FROM(SELECT DISTINCT x FROM unnest(source_ids)x WHERE x IS NOT NULL)cohort));
  END IF;
  SELECT previous.* INTO prior FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations previous ON previous.id=link.operation_id
   WHERE link.message_id=mid AND previous.company_id=c;
  IF prior.id IS NULL THEN RETURN NULL;END IF;
  IF(prior.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR prior.original_message_id IS NULL OR prior.corrected_payload_hash IS NULL OR prior.source_ack_message_id IS NULL THEN RAISE EXCEPTION 'customer_life_event_recovery_lineage_unqualified';END IF;
  steps:=steps||jsonb_build_array(jsonb_build_object('messageId',mid,'operationId',prior.id,'originalMessageId',prior.original_message_id,'payloadHash',prior.corrected_payload_hash));
  source_ids:=source_ids||ARRAY[prior.original_message_id,prior.source_ack_message_id];mid:=prior.original_message_id;
 END LOOP;
 RAISE EXCEPTION 'customer_life_event_recovery_lineage_bound_exceeded';
END$$;

--
-- Name: require_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.require_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF (phase IN('prepare','send','read')) IS NOT TRUE OR c IS NULL OR actor IS NULL THEN RAISE EXCEPTION 'customer_life_event_execution_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT (CASE phase WHEN 'send' THEN coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false) WHEN 'read' THEN coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.read'),false) ELSE coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.write'),false) END) THEN RAISE EXCEPTION 'customer_life_event_actor_forbidden' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: require_before_certification_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.require_before_certification_v1(c uuid, mid uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_customer_life_events.originals%rowtype;origin gridex_customer_life_events.origins%rowtype;b jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;w jsonb;q jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;IF m.id IS NULL THEN RAISE EXCEPTION 'customer_life_event_message_scope_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' THEN RETURN NULL;END IF;
 w:=gridex_customer_life_events.wire_v1(m.raw_payload);SELECT * INTO o FROM gridex_customer_life_events.originals WHERE message_id=m.id AND company_id=c;
 IF NOT FOUND THEN
  q:=public.ediel_prodat_recovery_original_basis_v1(c,m.id,actor);
  IF q IS NOT NULL THEN
   b:=gridex_customer_life_events.recovery_basis_v1(c,(q->>'operationId')::uuid,actor,phase);
   IF b IS NOT NULL THEN
    IF m.raw_payload IS DISTINCT FROM b->>'rawPayload' OR m.original_message_id::text IS DISTINCT FROM b->>'originalMessageId' OR m.source_operation_id IS DISTINCT FROM q->>'operationId' OR m.immutable_payload_hash IS DISTINCT FROM q->>'correctedPayloadHash' OR m.immutable_rendered_at IS NULL OR m.environment IS DISTINCT FROM b->>'environment' OR m.customer_id::text IS DISTINCT FROM b->>'customerId' THEN RAISE EXCEPTION 'customer_life_event_recovery_original_alias_changed';END IF;
    PERFORM gridex_ediel_transport.require_message_intent_v1(m);RETURN jsonb_build_object('basis',b,'intentId',m.intent_id);
   END IF;
  END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.prodat_recovery_wire_v1(m.raw_payload)->'objects') own WHERE own->>'reason'='E34') THEN RAISE EXCEPTION 'customer_life_event_historical_source_unavailable';END IF;RETURN NULL;
 END IF;
 b:=gridex_customer_life_events.source_v1(c,o.event_id,actor,phase);SELECT * INTO origin FROM gridex_customer_life_events.origins WHERE event_id=o.event_id AND company_id=c;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=origin.intent_id AND company_id=c FOR SHARE;SELECT * INTO r FROM public.outbound_requests WHERE id=origin.outbound_request_id AND company_id=c FOR SHARE;
 IF b->>'status' IS DISTINCT FROM 'authorized' OR m.raw_payload IS DISTINCT FROM b->>'rawPayload' OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_rendered_at IS NULL
  OR m.intent_id IS DISTINCT FROM origin.intent_id OR m.outbound_request_id IS DISTINCT FROM origin.outbound_request_id OR m.source_operation_id IS DISTINCT FROM o.event_id::text OR m.environment IS DISTINCT FROM b->>'environment' OR m.customer_id::text IS DISTINCT FROM b->>'customerId' OR m.site_id::text IS DISTINCT FROM b->>'siteId' OR m.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId'
  OR i.id IS NULL OR i.ediel_message_id IS DISTINCT FROM m.id OR i.operation_id IS DISTINCT FROM o.event_id OR i.validation_status IS DISTINCT FROM 'validated' OR i.outbound_request_id IS DISTINCT FROM r.id OR i.communication_route_id::text IS DISTINCT FROM o.intent_binding->>'routeId' OR i.route_profile_id::text IS DISTINCT FROM o.intent_binding->>'routeProfileId'
  OR r.id IS NULL OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM o.event_id OR r.payload->>'environment' IS DISTINCT FROM m.environment OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'customer_life_event_current_original_scope_changed';END IF;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);RETURN jsonb_build_object('basis',b,'intentId',i.id);
END $$;

--
-- Name: require_current_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.require_current_v1(c uuid, mid uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;q jsonb;b jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;IF m.id IS NULL THEN RAISE EXCEPTION 'customer_life_event_message_scope_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' OR EXISTS(SELECT FROM gridex_customer_life_events.originals WHERE message_id=mid AND company_id=c) OR EXISTS(SELECT FROM gridex_received_sources.prodat_recovery_messages WHERE message_id=mid) THEN RETURN gridex_customer_life_events.require_before_certification_v1(c,mid,actor,phase);END IF;

 IF EXISTS(SELECT FROM gridex_requested_changes.origins generic_origin
   LEFT JOIN gridex_requested_changes.events generic_event ON generic_event.id=generic_origin.event_id
   WHERE (generic_origin.message_id=m.id OR generic_origin.intent_id=m.intent_id)
   AND (generic_event.variant='E' OR generic_origin.basis->>'variant'='E')) THEN
  IF phase IS NULL OR phase NOT IN('prepare','send') THEN
   RAISE EXCEPTION 'requested_change_execution_phase_required';
  END IF;
  IF (SELECT count(*) FROM gridex_requested_changes.origins generic_origin
    JOIN gridex_requested_changes.events generic_event ON generic_event.id=generic_origin.event_id
    WHERE generic_origin.company_id=c AND generic_origin.message_id=m.id AND generic_origin.intent_id=m.intent_id
    AND generic_event.company_id=c AND generic_event.id::text=m.source_operation_id::text
    AND generic_event.variant='E' AND generic_event.event_kind='death') IS DISTINCT FROM 1 THEN
   RAISE EXCEPTION 'requested_change_original_generic_binding_required';
  END IF;
  PERFORM gridex_requested_changes.require_message_v1(m,actor,
    CASE phase WHEN 'send' THEN 'communication.send' ELSE 'communication.write' END);
  IF m.immutable_rendered_at IS NULL
   OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
   OR (SELECT generic_origin.payload_hash FROM gridex_requested_changes.origins generic_origin
     WHERE generic_origin.company_id=c AND generic_origin.message_id=m.id AND generic_origin.intent_id=m.intent_id)
     IS DISTINCT FROM m.immutable_payload_hash THEN
   RAISE EXCEPTION 'requested_change_original_generic_payload_required';
  END IF;
  PERFORM gridex_ediel_transport.require_message_intent_v1(m);
  RETURN NULL;
 END IF;
 IF m.environment='test' AND m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NOT NULL AND m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NULL THEN q:=gridex_negative_fixtures.require_positive_message_v1(c,mid,'Z09');
 ELSIF m.environment='test' AND m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL AND m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN q:=gridex_negative_fixtures.require_negative_message_v1(c,mid,'Z09');END IF;
 IF q IS NOT NULL THEN
  IF phase='send' THEN PERFORM gridex_customer_life_events.require_actor_v1(c,actor,'send');ELSE PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(actor,c);END IF;
  b:=gridex_customer_life_events.certification_basis_v1(q,m.raw_payload);
  IF b->>'status' IS DISTINCT FROM 'authorized' OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'customer_event_independent_certification_classification_required';END IF;
  RETURN jsonb_build_object('certification',true,'basis',b,'intentId',m.intent_id);
 END IF;RETURN gridex_customer_life_events.require_before_certification_v1(c,mid,actor,phase);
END$$;

--
-- Name: revoke_certification_v1(uuid, uuid, text, bytea, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.revoke_certification_v1(declaration uuid, actor uuid, reference text, original bytea, publisher text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_customer_life_events.certification_classifications%rowtype;r gridex_customer_life_events.certification_classification_revocations%rowtype;BEGIN
 IF publisher IS DISTINCT FROM 'gridex_ediel_fixture_authority_owner' OR nullif(btrim(reference),'') IS NULL OR original IS NULL OR octet_length(original) NOT BETWEEN 1 AND 10485760 THEN RAISE EXCEPTION 'customer_event_certification_revocation_original_required';END IF;
 SELECT * INTO d FROM gridex_customer_life_events.certification_classifications WHERE id=declaration FOR UPDATE;IF d.id IS NULL THEN RAISE EXCEPTION 'customer_event_certification_declaration_required';END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(actor,d.company_id);
 SELECT * INTO r FROM gridex_customer_life_events.certification_classification_revocations WHERE declaration_id=d.id;
 IF FOUND THEN IF r.source_reference IS DISTINCT FROM reference OR r.source_original IS DISTINCT FROM original THEN RAISE EXCEPTION 'customer_event_certification_revocation_conflict';END IF;RETURN;END IF;
 INSERT INTO gridex_customer_life_events.certification_classification_revocations(declaration_id,source_reference,source_original,source_sha256) VALUES(d.id,reference,original,encode(sha256(original),'hex'));
END$$;

--
-- Name: source_before_dated_brp_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.source_before_dated_brp_v1(c uuid, event uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE ev gridex_customer_life_events.events%rowtype;probe public.ediel_messages%rowtype;w jsonb;local_legal jsonb;scope jsonb;own jsonb;basis jsonb;objects jsonb:='[]';ids uuid[];period_ids uuid[];period_manifest jsonb;ba public.tenant_bilateral_agreements%rowtype;BEGIN
 PERFORM gridex_customer_life_events.require_actor_v1(c,actor,phase);
 SELECT * INTO ev FROM gridex_customer_life_events.events WHERE id=event AND company_id=c FOR UPDATE;
 IF ev.id IS NULL OR ev.approved_at>clock_timestamp() OR ev.information_known_at>clock_timestamp() OR EXISTS(SELECT FROM gridex_customer_life_events.revocations r WHERE r.event_id=ev.id) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_approved_customer_life_event']);END IF;
 w:=gridex_customer_life_events.wire_v1(ev.approved_raw_payload);
 IF w IS NULL OR w->>'code' IS DISTINCT FROM 'Z09' OR w->>'legalSender' IS DISTINCT FROM ev.legal_sender_id OR w->>'legalReceiver' IS DISTINCT FROM ev.legal_receiver_id OR ev.approved_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ev.approved_raw_payload,'UTF8')),'hex') OR jsonb_array_length(w->'objects') IS DISTINCT FROM jsonb_array_length(ev.approved_scope) OR (SELECT count(DISTINCT jsonb_build_array(sc->>'pointId',sc->>'identityAgency')) FROM jsonb_array_elements(ev.approved_scope) sc) IS DISTINCT FROM jsonb_array_length(ev.approved_scope)::bigint THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_source_approved_customer_event_wire']);END IF;
 probe.company_id:=c;probe.environment:=ev.environment;probe.direction:='outbound';probe.message_standard:='edifact';probe.message_family:='PRODAT';probe.message_code:='Z09';probe.raw_payload:=ev.approved_raw_payload;
 local_legal:=gridex_ediel_inbound_context.derive(probe,clock_timestamp());
 IF local_legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR local_legal->>'legalActorId' IS DISTINCT FROM ev.legal_actor_id::text OR local_legal->>'legalEdielId' IS DISTINCT FROM ev.legal_sender_id THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_customer_event_same_legal_supplier']);END IF;
 -- Lock the complete source union before any owned point/period. Discovery
 -- is rechecked by the sole supply owner for every approved physical object.
 SELECT array_agg(DISTINCT source_id) INTO ids FROM (
  SELECT p.source_message_id source_id FROM public.customer_supply_periods p,jsonb_array_elements(ev.approved_scope)s WHERE p.company_id=c AND p.id=(s->>'periodId')::uuid
  UNION SELECT t.source_message_id FROM gridex_received_sources.supply_source_transitions t,public.customer_supply_periods p,jsonb_array_elements(ev.approved_scope)s WHERE p.company_id=c AND p.id=(s->>'periodId')::uuid AND t.company_id=c AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states)state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version)
  UNION SELECT proof.original_message_id FROM gridex_received_sources.normal_switch_confirmations proof,jsonb_array_elements(ev.approved_scope)s WHERE proof.company_id=c AND proof.period_id=(s->>'periodId')::uuid
 ) all_sources;
 SELECT array_agg((sc->>'periodId')::uuid) INTO period_ids FROM jsonb_array_elements(ev.approved_scope) sc;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO period_manifest FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(period_ids);
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id=ANY(ids) ORDER BY m.id FOR UPDATE;
 PERFORM p.id FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(period_ids) ORDER BY p.id FOR SHARE;
 IF (SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.customer_supply_periods p WHERE p.company_id=c AND p.id=ANY(period_ids)) IS DISTINCT FROM period_manifest THEN RAISE EXCEPTION 'customer_life_event_source_discovery_changed' USING ERRCODE='40001';END IF;
 IF ev.classification<>'death' THEN
  SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=ev.bilateral_agreement_id AND company_id=c AND environment=ev.environment FOR SHARE;
  PERFORM pi.id FROM public.platform_actor_identifiers pi WHERE pi.actor_id=ba.counterparty_actor_id FOR SHARE;
  IF ba.id IS NULL OR ba.is_enabled IS DISTINCT FROM true OR ba.valid_from IS NULL OR ba.valid_from>clock_timestamp() OR ba.valid_to IS NOT NULL AND ba.valid_to<clock_timestamp() OR ba.capability_code IS DISTINCT FROM ev.bilateral_capability_code OR ba.source_reference IS DISTINCT FROM ev.bilateral_source_reference OR encode(sha256(convert_to(ba.terms::text,'UTF8')),'hex') IS DISTINCT FROM ev.bilateral_terms_sha256 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_bilateral_customer_event_process']);END IF;
 END IF;
 FOR scope IN SELECT value FROM jsonb_array_elements(ev.approved_scope) ORDER BY value->>'periodId' LOOP
  SELECT x INTO own FROM jsonb_array_elements(w->'objects')x WHERE x->>'point'=scope->>'pointId' AND x->>'identityAgency'=scope->>'identityAgency';
  basis:=gridex_received_sources.supply_period_source_at_v1(c,(scope->>'periodId')::uuid,(own->>'effectiveAt')::timestamptz);
  IF own IS NULL OR basis IS NULL OR basis->>'qualified' IS DISTINCT FROM 'true' OR basis->>'companyId' IS DISTINCT FROM c::text OR basis->>'customerId' IS DISTINCT FROM ev.customer_id::text OR basis->>'customerId' IS DISTINCT FROM scope->>'customerId' OR basis->>'siteId' IS DISTINCT FROM scope->>'siteId' OR basis->>'meteringPointId' IS DISTINCT FROM scope->>'meteringPointId'
   OR basis->>'sourceMessageId' IS DISTINCT FROM scope->>'sourceMessageId' OR basis->>'payloadHash' IS DISTINCT FROM scope->>'sourcePayloadHash' OR basis->>'marketStateVersion' IS DISTINCT FROM scope->>'marketStateVersion' OR basis->>'legalActorId' IS DISTINCT FROM ev.legal_actor_id::text OR basis->>'dsoEdielId' IS DISTINCT FROM ev.legal_receiver_id
   OR own->>'gridArea' IS DISTINCT FROM scope->>'gridArea' OR NOT EXISTS(SELECT FROM jsonb_array_elements(basis->'sourceObjects') old WHERE old->>'point'=own->>'point' AND old->>'identityAgency'=own->>'identityAgency' AND old->>'gridArea'=own->>'gridArea')
   OR ev.classification='death' AND own->>'customerStatus' IS DISTINCT FROM 'Z41' OR ev.classification<>'death' AND own ? 'customerStatus'
   OR NOT('227'=ANY(ev.allowed_customer_fields)) AND NOT EXISTS(SELECT FROM jsonb_array_elements(basis->'sourceObjects') old WHERE old->>'customerIdentity'=own#>>'{customerParty,0}')
   THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_customer_event_current_source_object_scope']);END IF;
  IF ev.classification<>'death' AND NOT EXISTS(SELECT FROM public.platform_actor_identifiers pi WHERE pi.actor_id=ba.counterparty_actor_id AND pi.identifier_type='EdielId' AND pi.identifier_value=ev.legal_receiver_id AND pi.is_verified AND (pi.valid_from IS NULL OR pi.valid_from<=current_date) AND (pi.valid_to IS NULL OR current_date<=pi.valid_to)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_bilateral_customer_event_counterparty']);END IF;
  objects:=objects||jsonb_build_array(jsonb_build_object('objectKey',scope->>'meteringPointId','installation',jsonb_build_object('id',own->>'point','agency',own->>'identityAgency'),
   'customer',jsonb_build_object('kind','domain_customer','key',ev.customer_id,'revision',ev.source_version,'id',own#>>'{customerParty,0}','qualifier',own#>>'{customerParty,1}','agency',own#>>'{customerParty,2}'),
   'legalSupplier',jsonb_build_object('id',ev.legal_sender_id,'qualifier','160','agency','SVK'),'legalGridOwner',jsonb_build_object('id',ev.legal_receiver_id,'qualifier','160','agency','SVK'),'process',jsonb_build_object('code','Z09','reason','E34'),
   'event',jsonb_build_object('key',ev.id,'eventKey',ev.id,'revision',ev.source_version,'reference',ev.source_reference),'assessment',jsonb_build_object('kind','known','value',CASE ev.classification WHEN 'death' THEN 'death' ELSE 'not_death' END,'evidence',jsonb_build_object('key',ev.id,'eventKey',ev.id,'revision',ev.source_version,'reference',ev.legal_decision_reference)),'lineItemReference',own->>'li'));
 END LOOP;
 RETURN jsonb_build_object('status','authorized','companyId',c,'environment',ev.environment,'eventId',ev.id,'sourceVersion',ev.source_version,'sourceDigest',ev.source_sha256,'sourceReference',ev.source_reference,'classification',ev.classification,'bilateralCapabilityVerified',ev.classification<>'death','legalActorId',ev.legal_actor_id,'legalSenderId',ev.legal_sender_id,'legalReceiverId',ev.legal_receiver_id,
  'customerId',ev.customer_id,'siteId',CASE WHEN jsonb_array_length(ev.approved_scope)=1 THEN ev.approved_scope#>>'{0,siteId}' END,'meteringPointId',CASE WHEN jsonb_array_length(ev.approved_scope)=1 THEN ev.approved_scope#>>'{0,meteringPointId}' END,'pointId',CASE WHEN jsonb_array_length(ev.approved_scope)=1 THEN ev.approved_scope#>>'{0,pointId}' END,'gridArea',CASE WHEN jsonb_array_length(ev.approved_scope)=1 THEN ev.approved_scope#>>'{0,gridArea}' END,'rawPayload',ev.approved_raw_payload,'selection',jsonb_build_object('source',jsonb_build_object('kind','caller_selection','reference',ev.source_reference),'objects',objects),
  'interchangeReference',w->>'interchange','messageReference',w->>'messageReference','documentReference',w->>'bgmId','transactionReference',w#>>'{objects,0,li}','informationKnownAt',ev.information_known_at);
END $$;

--
-- Name: source_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.source_v1(c uuid, event uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;ev gridex_customer_life_events.events%rowtype;wire jsonb;brps jsonb;scope jsonb;own jsonb;physical jsonb;brp jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF EXISTS(SELECT FROM gridex_requested_customer_changes.origins WHERE company_id=c AND event_id=event) THEN
  IF gridex_requested_customer_changes.actor_v1(c,actor,CASE WHEN phase='read' THEN 'read' ELSE 'archive' END,'method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_current_execution_actor_forbidden' USING ERRCODE='42501';END IF;
  IF gridex_requested_customer_changes.current_v1((SELECT artifact_id FROM gridex_requested_customer_changes.origins WHERE company_id=c AND event_id=event),c) IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_outgoing_customer_mandate_unavailable']);END IF;
 END IF;

 basis:=gridex_customer_life_events.source_before_dated_brp_v1(c,event,actor,phase);
 IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;END IF;
 SELECT * INTO STRICT ev FROM gridex_customer_life_events.events WHERE id=event AND company_id=c;
 wire:=gridex_customer_life_events.wire_v1(basis->>'rawPayload');brps:=gridex_customer_life_events.brp_objects_v1(basis->>'rawPayload');
 IF brps IS NULL OR jsonb_array_length(brps) IS DISTINCT FROM jsonb_array_length(ev.approved_scope) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_customer_event_physical_brp_scope']);END IF;
 FOR scope IN SELECT item FROM jsonb_array_elements(ev.approved_scope)item LOOP
  SELECT item INTO own FROM jsonb_array_elements(wire->'objects')item WHERE item->>'point'=scope->>'pointId' AND item->>'identityAgency'=scope->>'identityAgency';
  SELECT item INTO physical FROM jsonb_array_elements(brps)item WHERE item->>'point'=scope->>'pointId' AND item->>'identityAgency'=scope->>'identityAgency';
  brp:=gridex_brp_sources.require_source_v1(c,NULL,actor,phase,ev.environment,ev.customer_id,(scope->>'siteId')::uuid,(scope->>'meteringPointId')::uuid,(own->>'effectiveAt')::timestamptz,(scope->>'periodId')::uuid);
  IF brp->>'status' IS DISTINCT FROM 'authorized' THEN RETURN coalesce(brp,jsonb_build_object('status','held','missing',ARRAY['own_dated_customer_event_brp_source']));END IF;
  IF brp->>'sourceKind' IS DISTINCT FROM 'accepted_supply_brp' OR brp->>'companyId' IS DISTINCT FROM c::text OR brp->>'environment' IS DISTINCT FROM ev.environment OR brp->>'customerId' IS DISTINCT FROM ev.customer_id::text
   OR brp->>'siteId' IS DISTINCT FROM scope->>'siteId' OR brp->>'meteringPointId' IS DISTINCT FROM scope->>'meteringPointId' OR brp->>'supplyPeriodId' IS DISTINCT FROM scope->>'periodId' OR (brp->>'at')::timestamptz IS DISTINCT FROM (own->>'effectiveAt')::timestamptz
   OR brp->>'pointId' IS DISTINCT FROM scope->>'pointId' OR brp->>'identityAgency' IS DISTINCT FROM scope->>'identityAgency' OR brp->>'gridArea' IS DISTINCT FROM scope->>'gridArea'
   OR brp->>'legalActorId' IS DISTINCT FROM ev.legal_actor_id::text OR brp->>'legalSenderId' IS DISTINCT FROM ev.legal_sender_id OR brp->>'legalReceiverId' IS DISTINCT FROM ev.legal_receiver_id OR physical->>'brp' IS DISTINCT FROM brp->>'brpEdielId' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['customer_event_same_dated_brp_object']);END IF;
 END LOOP;RETURN basis;
END$$;

--
-- Name: wire_partition_v1(text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.wire_partition_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE w jsonb:='{}';tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;e jsonb;obj jsonb;objects jsonb:='[]';characteristic text;common boolean:=false;seen text[]:=ARRAY[]::text[];key text;physical jsonb:='[]';minute text;instant timestamptz;first_fragment jsonb;field text;BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x LOOP
  IF t->>'tag'='UNB' THEN w:=w||jsonb_build_object('interchange',t#>>'{elements,5,0}');END IF;
  IF t->>'tag'='UNH' THEN w:=w||jsonb_build_object('family',t#>>'{elements,2,0}','unh',t#>>'{elements,1,0}','messageReference',t#>>'{elements,1,0}');END IF;
  IF t->>'tag'='BGM' THEN w:=w||jsonb_build_object('code',t#>>'{elements,1,0}','bgmId',t#>>'{elements,2,0}');END IF;
  EXIT WHEN t->>'tag'='LIN';
  IF t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN('FR','DO') THEN field:=CASE t#>>'{elements,1,0}' WHEN 'FR' THEN 'legalSender' ELSE 'legalReceiver' END;IF w ? field THEN RETURN NULL;END IF;w:=w||jsonb_build_object(field,t#>>'{elements,2,0}');END IF;
 END LOOP;
 IF w->>'family' IS DISTINCT FROM 'PRODAT' OR (w->>'code' IN('Z06','Z09')) IS NOT TRUE THEN RETURN NULL;END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(tokens) ORDER BY (value->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
   obj:=jsonb_build_object('point',e#>>'{3,0}','identityAgency',e#>>'{3,3}','line',e#>>'{1,0}','firstLineIndex',t->'index','lineIndexes',jsonb_build_array(t->'index'),'body','[]'::jsonb);characteristic:=NULL;common:=true;
  ELSIF obj IS NOT NULL AND t->>'tag' NOT IN('UNT','UNZ') THEN
   obj:=jsonb_set(obj,'{body}',obj->'body'||jsonb_build_array(t-'index'-'raw'));
   IF t->>'tag' IN('RFF','NAD','DTM') THEN common:=false;END IF;
   IF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' AND characteristic='Z13' THEN IF obj ? 'reason' THEN obj:=obj||'{"projectionHeld":true}';END IF;obj:=obj||jsonb_build_object('reason',e#>>'{1,0}');
   ELSIF t->>'tag'='CAV' AND characteristic='Z17' AND common THEN IF obj ? 'customerStatus' THEN obj:=obj||'{"projectionHeld":true}';END IF;obj:=obj||jsonb_build_object('customerStatus',e#>>'{1,0}');
   ELSIF t->>'tag'='RFF' AND e#>>'{1,0}' IN('LI','Z05') THEN
    IF obj ? (CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' ELSE 'gridArea' END) THEN obj:=obj||'{"projectionHeld":true}';END IF;
    obj:=obj||jsonb_build_object(CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' ELSE 'gridArea' END,e#>>'{1,1}');
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}'='157' THEN
    IF obj ? 'effectiveAt' OR e#>>'{1,2}' IS DISTINCT FROM '203' THEN obj:=obj||'{"projectionHeld":true}';CONTINUE;END IF;
    minute:=e#>>'{1,1}';IF minute IS NULL OR minute !~ '^[0-9]{12}$' THEN obj:=obj||'{"projectionHeld":true}';CONTINUE;END IF;
    -- 216 is a physical EDIFACT minute; national P time is fixed UTC+1.
    -- No DATE, receipt clock or local midnight is substituted for it.
    BEGIN instant:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0) AT TIME ZONE 'Etc/GMT-1';
    EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN obj:=obj||'{"projectionHeld":true}';CONTINUE;END;
    obj:=obj||jsonb_build_object('effectiveAt',instant,'validityMinute',minute);
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN
    IF obj ? 'customerParty' THEN obj:=obj||'{"projectionHeld":true}';END IF;
    obj:=obj||jsonb_build_object('customerParty',e->2,'name',e->4,'street',e->5,'city',e#>>'{6,0}','postCode',e#>>'{8,0}','country',e#>>'{9,0}');
   END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 FOR obj IN SELECT value FROM jsonb_array_elements(objects) LOOP
  key:=jsonb_build_array(obj->>'point',obj->>'identityAgency')::text;
  IF key=ANY(seen) THEN
   SELECT item INTO first_fragment FROM jsonb_array_elements(physical) item WHERE item->>'point'=obj->>'point' AND item->>'identityAgency'=obj->>'identityAgency';
   -- A register fragment may omit common fields. Repeated common values must
   -- be identical; it can never override or add a second customer/event tuple.
   FOREACH field IN ARRAY ARRAY['reason','customerStatus','li','gridArea','customerParty','name','street','city','postCode','country','effectiveAt','validityMinute'] LOOP
    IF obj ? field AND obj->field IS DISTINCT FROM first_fragment->field THEN first_fragment:=first_fragment||'{"projectionHeld":true}';END IF;
   END LOOP;
   first_fragment:=first_fragment||jsonb_build_object('lineIndexes',(first_fragment->'lineIndexes')||(obj->'lineIndexes'),'body',(first_fragment->'body')||(obj->'body'));
   IF obj->>'projectionHeld'='true' THEN first_fragment:=first_fragment||'{"projectionHeld":true}';END IF;
   SELECT jsonb_agg(CASE WHEN item->>'firstLineIndex'=first_fragment->>'firstLineIndex' THEN first_fragment ELSE item END ORDER BY ord) INTO physical FROM jsonb_array_elements(physical) WITH ORDINALITY x(item,ord);
  ELSE seen:=array_append(seen,key);physical:=physical||jsonb_build_array(obj);END IF;
 END LOOP;objects:=physical;
 IF jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN w||jsonb_build_object('objects',objects);
END $_$;

--
-- Name: wire_v1(text); Type: FUNCTION; Schema: gridex_customer_life_events; Owner: -
--

CREATE FUNCTION gridex_customer_life_events.wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w jsonb:=gridex_customer_life_events.wire_partition_v1(raw);BEGIN
 IF w IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(w->'objects')x WHERE x->>'projectionHeld'='true' OR x->>'reason' IS DISTINCT FROM 'E34' OR nullif(x->>'point','') IS NULL OR(x->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(x->>'li','') IS NULL OR x->>'effectiveAt' IS NULL OR(x#>>'{customerParty,1}' IN('SE1','SE2')) IS NOT TRUE OR x#>>'{customerParty,2}' IS DISTINCT FROM '260') THEN RETURN NULL;END IF;RETURN w;END$$;

--
-- Name: basis_v1(uuid, uuid, uuid, timestamp with time zone, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.basis_v1(c uuid, customer uuid, actor uuid, at timestamp with time zone, env text, phase text, observed timestamp with time zone DEFAULT statement_timestamp(), expected_sources jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE person public.customers%rowtype;address public.customer_addresses%rowtype;declaration gridex_customer_masterdata.signed_declarations%rowtype;contract public.customer_contracts%rowtype;identity jsonb;masterdata jsonb;life jsonb;source_kind text;source_reference text;source_digest text;source jsonb;day date;name text;source_ids jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_customer_life_events.require_actor_v1(c,actor,phase);
 IF at IS NULL OR observed IS NULL OR NOT isfinite(at) OR NOT isfinite(observed) OR observed>statement_timestamp() OR (env IS NOT NULL AND (env IN('test','production')) IS NOT TRUE) THEN RAISE EXCEPTION 'customer_masterdata_scope_required';END IF;
 -- All immutable customer-event sources precede mutable customer/address locks.
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO source_ids FROM(SELECT DISTINCT source_message_id id FROM gridex_customer_life_events.customer_versions WHERE company_id=c AND customer_id=customer) ids;
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(SELECT value::uuid FROM jsonb_array_elements_text(coalesce(expected_sources,source_ids))) ORDER BY m.id FOR UPDATE;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('customer-masterdata:'||c::text||':'||customer::text,0));
 PERFORM ct.id FROM public.customer_contracts ct WHERE ct.company_id=c AND ct.id IN(SELECT d.contract_id FROM gridex_customer_masterdata.signed_declarations d WHERE d.company_id=c AND d.customer_id=customer AND (env IS NULL OR d.environment=env)) ORDER BY ct.id FOR SHARE;
 SELECT * INTO person FROM public.customers WHERE id=customer AND company_id=c FOR UPDATE;
 IF coalesce(expected_sources,source_ids) IS DISTINCT FROM(SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') FROM(SELECT DISTINCT source_message_id id FROM gridex_customer_life_events.customer_versions WHERE company_id=c AND customer_id=customer) ids) THEN RAISE EXCEPTION 'customer_masterdata_source_epoch_changed' USING ERRCODE='40001';END IF;
 IF person.id IS NULL THEN RAISE EXCEPTION 'customer_masterdata_tenant_required' USING ERRCODE='42501';END IF;
 life:=public.ediel_customer_life_event_export_at_v1(c,customer,actor,at);
 day:=(at AT TIME ZONE 'Etc/GMT-1')::date;
 -- Future-only E effects have not altered today's observed customer/address.
 -- This current-day source is not a reconstruction of an earlier unknown day.
 IF life->>'status'='held' THEN
  IF day=(observed AT TIME ZONE 'Etc/GMT-1')::date AND NOT EXISTS(SELECT FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=c AND v.customer_id=customer AND v.effective_at<=at) THEN life:=NULL;
  ELSE RETURN life;END IF;
 END IF;
 -- A mutable identity without its own dated source is observed current data,
 -- not a statement about a different historical/future market day.
 IF day=(observed AT TIME ZONE 'Etc/GMT-1')::date THEN
  PERFORM id FROM public.customer_addresses WHERE company_id=c AND customer_id=customer AND type='registered' ORDER BY id FOR SHARE;
  IF (SELECT count(*) FROM public.customer_addresses a WHERE a.company_id=c AND a.customer_id=customer AND a.type='registered' AND a.is_active IS TRUE AND (a.moved_in_at IS NULL OR a.moved_in_at<=day) AND (a.moved_out_at IS NULL OR day<a.moved_out_at))>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['unique_owned_registered_customer_address']);END IF;
  SELECT * INTO address FROM public.customer_addresses a WHERE a.company_id=c AND a.customer_id=customer AND a.type='registered' AND a.is_active IS TRUE AND (a.moved_in_at IS NULL OR a.moved_in_at<=day) AND (a.moved_out_at IS NULL OR day<a.moved_out_at);
  IF address.id IS NOT NULL THEN
   identity:=CASE WHEN nullif(person.org_number,'') IS NOT NULL THEN jsonb_build_object('id',person.org_number,'qualifier','SE1','agency','260') WHEN nullif(person.personal_number,'') IS NOT NULL THEN jsonb_build_object('id',person.personal_number,'qualifier','SE2','agency','260') END;
   name:=coalesce(nullif(person.company_name,''),nullif(person.full_name,''),nullif(person.name,''));
   masterdata:=jsonb_build_object('nameParts',CASE WHEN length(name)<=35 THEN jsonb_build_array(name) WHEN length(name)<=70 THEN jsonb_build_array(substr(name,1,35),substr(name,36)) ELSE '[]'::jsonb END,'streetParts',CASE WHEN nullif(address.street_2,'') IS NULL THEN jsonb_build_array(coalesce(address.street_1,'')) ELSE jsonb_build_array(coalesce(address.street_1,''),address.street_2) END,'postalCode',address.postal_code,'city',address.city,'country',address.country);
   source_kind:='registered_customer_address';source_reference:=address.id::text;
   source:=jsonb_build_object('customer',jsonb_build_object('id',person.id,'org_number',person.org_number,'personal_number',person.personal_number,'company_name',person.company_name,'full_name',person.full_name,'name',person.name),'address',to_jsonb(address));
  END IF;
 END IF;
 IF masterdata IS NULL OR gridex_customer_masterdata.identity_v1(identity) IS NOT TRUE OR gridex_customer_masterdata.literal_masterdata_v1(masterdata) IS NOT TRUE THEN
  IF env IS NOT NULL THEN
   PERFORM id FROM gridex_customer_masterdata.signed_declarations d WHERE d.company_id=c AND d.customer_id=customer AND d.environment=env ORDER BY id FOR SHARE;
   IF (SELECT count(*) FROM gridex_customer_masterdata.signed_declarations d WHERE d.company_id=c AND d.customer_id=customer AND d.environment=env AND d.approved_at<=statement_timestamp() AND d.valid_from<=at AND (d.valid_to IS NULL OR at<d.valid_to) AND NOT EXISTS(SELECT FROM gridex_customer_masterdata.revocations r WHERE r.declaration_id=d.id))>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['unique_authentic_signed_customer_masterdata_declaration']);END IF;
   SELECT * INTO declaration FROM gridex_customer_masterdata.signed_declarations d WHERE d.company_id=c AND d.customer_id=customer AND d.environment=env AND d.approved_at<=statement_timestamp() AND d.valid_from<=at AND (d.valid_to IS NULL OR at<d.valid_to) AND NOT EXISTS(SELECT FROM gridex_customer_masterdata.revocations r WHERE r.declaration_id=d.id);
   IF declaration.id IS NOT NULL THEN
    SELECT * INTO contract FROM public.customer_contracts WHERE id=declaration.contract_id AND company_id=c FOR SHARE;
    IF contract.id IS NULL OR contract.customer_id IS DISTINCT FROM customer OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR contract.signed_version IS DISTINCT FROM declaration.contract_revision OR contract.document_sha256 IS DISTINCT FROM declaration.agreement_sha256 OR gridex_received_sources.production_contract_hash_v1(contract) IS DISTINCT FROM declaration.contract_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_authentic_signed_masterdata_customer_contract']);END IF;
    IF gridex_ediel_retention.contract_copy_source_current_v1(c,'gridex_customer_masterdata','signed_declarations',declaration.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_unpurged_signed_masterdata_originals']);END IF; identity:=declaration.customer_identity;masterdata:=declaration.end_user_masterdata;source_kind:='signed_contract_masterdata';source_reference:=declaration.source_reference;source:=to_jsonb(declaration);
   END IF;
  END IF;
 END IF;
 -- E owns each changed field. Its qualified effective projection overlays the
 -- end-user source, without ever falling back field-by-field to IT/IV.
 IF life->>'status'='authorized' AND (life->>'effectiveVersionCount')::integer>0 THEN
  IF life#>>'{customerFields,org_number}' IS NOT NULL THEN identity:=jsonb_build_object('id',life#>>'{customerFields,org_number}','qualifier','SE1','agency','260');ELSIF life#>>'{customerFields,personal_number}' IS NOT NULL THEN identity:=jsonb_build_object('id',life#>>'{customerFields,personal_number}','qualifier','SE2','agency','260');END IF;
  masterdata:=coalesce(masterdata,'{}')||jsonb_strip_nulls(jsonb_build_object('nameParts',life#>'{endUserMasterdata,name}','streetParts',life#>'{endUserMasterdata,street}','postalCode',life#>'{endUserMasterdata,postCode}','city',life#>'{endUserMasterdata,city}','country',life#>'{endUserMasterdata,country}'));
  source:=jsonb_build_object('base',source,'customerHistory',life);source_kind:='confirmed_customer_history';source_reference:=life->>'sourceMessageId';
 END IF;
 IF gridex_customer_masterdata.identity_v1(identity) IS NOT TRUE OR gridex_customer_masterdata.literal_masterdata_v1(masterdata) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_qualified_customer_identity_registered_address_at_requested_time']);END IF;
 source_digest:=encode(sha256(convert_to(source::text,'UTF8')),'hex');
 RETURN jsonb_build_object('status','authorized','companyId',c,'customerId',customer,'environment',env,'asOf',at,'sourceKind',source_kind,'sourceReference',source_reference,'sourceDigest',source_digest,'customerIdentity',identity,'endUserMasterdata',masterdata,'sourceProof',jsonb_build_object('rowProof',source,'sourceIds',source_ids));
END$$;

--
-- Name: bind_original_v1(); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.bind_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE p gridex_customer_masterdata.preparations%rowtype;b jsonb;obj jsonb;ud jsonb;q jsonb;fixture_actor uuid;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF NEW.direction<>'outbound' OR NEW.message_family<>'PRODAT' OR (NEW.message_code IN('Z01','Z02','Z03','Z04','Z05','Z06','Z08','Z09')) IS NOT TRUE THEN RETURN NEW;END IF;
 IF NEW.message_code NOT IN('Z01','Z03') AND nullif(NEW.parsed_payload->>'customerMasterdataSourceContextId','') IS NULL THEN RETURN NEW;END IF;
 ud:=gridex_customer_masterdata.wire_ud_v1(NEW.raw_payload);IF ud IS NOT NULL AND jsonb_array_length(ud)=0 THEN RETURN NEW;END IF;
 IF NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NOT NULL AND NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NULL THEN
  SELECT actor_user_id INTO fixture_actor FROM gridex_negative_fixtures.positive_witnesses WHERE id=(NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId')::uuid AND company_id=NEW.company_id FOR SHARE;
  q:=gridex_negative_fixtures.prepared_positive_fixture_v1(NEW.company_id,(NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId')::uuid,NEW.raw_payload,fixture_actor);
 ELSIF NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL AND NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN
  SELECT actor_user_id INTO fixture_actor FROM gridex_negative_fixtures.negative_prepared_witnesses WHERE id=(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid AND company_id=NEW.company_id FOR SHARE;
  q:=gridex_negative_fixtures.prepared_negative_fixture_v1(NEW.company_id,(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid,NEW.raw_payload,fixture_actor);END IF;
 IF q->>'authorizesBusinessEffect'='false' AND q->>'companyId'=NEW.company_id::text AND NEW.environment='test' THEN RETURN NEW;END IF;
 IF nullif(NEW.parsed_payload->>'customerMasterdataSourceContextId','') IS NULL THEN RAISE EXCEPTION 'customer_masterdata_protected_source_context_required';END IF;
 SELECT * INTO p FROM gridex_customer_masterdata.preparations WHERE id=(NEW.parsed_payload->>'customerMasterdataSourceContextId')::uuid AND company_id=NEW.company_id FOR SHARE;
 IF p.id IS NULL OR p.actor_user_id IS DISTINCT FROM NEW.created_by OR p.customer_id IS DISTINCT FROM NEW.customer_id OR (p.environment IS NOT NULL AND p.environment IS DISTINCT FROM NEW.environment) OR NEW.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'customer_masterdata_prepared_source_scope_required';END IF;
 IF gridex_ediel_retention.contract_copy_preparation_current_v1(NEW.company_id,p.id) IS NOT TRUE THEN RAISE EXCEPTION 'customer_masterdata_consumed_original_copy_tombstoned';END IF; PERFORM gridex_customer_masterdata.require_recovery_preparation_v1(p,NEW,NEW.created_by,'prepare'); PERFORM gridex_customer_masterdata.require_cancellation_preparation_v1(p,NEW,NEW.created_by,'prepare'); b:=gridex_customer_masterdata.basis_v1(NEW.company_id,p.customer_id,p.actor_user_id,p.as_of,p.environment,'prepare',p.observed_at,p.basis#>'{sourceProof,sourceIds}');
 IF b IS DISTINCT FROM p.basis OR ud IS NULL THEN RAISE EXCEPTION 'customer_masterdata_prepared_source_changed';END IF;
 FOR obj IN SELECT item FROM jsonb_array_elements(ud)item LOOP IF obj->'customerIdentity' IS DISTINCT FROM b->'customerIdentity' OR obj->'endUserMasterdata' IS DISTINCT FROM gridex_customer_masterdata.wire_masterdata_v1(b->'endUserMasterdata') THEN RAISE EXCEPTION 'customer_masterdata_actual_wire_changed';END IF;END LOOP;
 INSERT INTO gridex_customer_masterdata.originals(message_id,company_id,preparation_id,payload_hash) VALUES(NEW.id,NEW.company_id,p.id,NEW.immutable_payload_hash);RETURN NEW;
END$$;

--
-- Name: declaration_scope_v1(); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.declaration_scope_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE c uuid;customer uuid;BEGIN
 IF TG_TABLE_NAME='revocations' THEN SELECT company_id,customer_id INTO c,customer FROM gridex_customer_masterdata.signed_declarations WHERE id=NEW.declaration_id;ELSE c:=NEW.company_id;customer:=NEW.customer_id;END IF;
 IF c IS NULL OR customer IS NULL THEN RAISE EXCEPTION 'customer_masterdata_declaration_scope_required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('customer-masterdata:'||c::text||':'||customer::text,0));
 IF TG_TABLE_NAME='revocations' THEN PERFORM id FROM gridex_customer_masterdata.signed_declarations WHERE id=NEW.declaration_id FOR UPDATE;END IF;RETURN NEW;END$$;

--
-- Name: identity_v1(jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.identity_v1(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT jsonb_typeof(d)='object' AND (d->>'qualifier' IN('SE1','SE2')) IS TRUE AND d->>'agency'='260' AND length(d->>'id') BETWEEN 1 AND 35 AND d->>'id'=btrim(d->>'id') AND (d->>'id')!~'[[:cntrl:]]'$$;

--
-- Name: literal_masterdata_v1(jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.literal_masterdata_v1(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT jsonb_typeof(d)='object' AND NOT EXISTS(SELECT FROM jsonb_object_keys(d) k WHERE k NOT IN('nameParts','streetParts','postalCode','city','country'))
 AND jsonb_typeof(d->'nameParts')='array' AND jsonb_array_length(d->'nameParts') BETWEEN 1 AND 2 AND NOT EXISTS(SELECT FROM jsonb_array_elements(d->'nameParts') item WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}') NOT BETWEEN 1 AND 35 OR (item#>>'{}')~'[[:cntrl:]]')
 AND jsonb_typeof(d->'streetParts')='array' AND jsonb_array_length(d->'streetParts') BETWEEN 1 AND 3 AND NOT EXISTS(SELECT FROM jsonb_array_elements(d->'streetParts') item WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}') NOT BETWEEN 0 AND 35 OR (item#>>'{}')~'[[:cntrl:]]')
 AND EXISTS(SELECT FROM jsonb_array_elements(d->'streetParts')item WHERE item#>>'{}' NOT IN('','.'))
 AND length(d->>'postalCode') BETWEEN 1 AND 9 AND length(d->>'city') BETWEEN 1 AND 35 AND length(d->>'country')=2 AND (d->>'country')~'^[A-Z]{2}$' AND (d->>'postalCode')!~'[[:cntrl:]]' AND (d->>'city')!~'[[:cntrl:]]'
$_$;

--
-- Name: prelock_message_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.prelock_message_v1(c uuid, message uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT NULL FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(SELECT value::uuid FROM gridex_customer_masterdata.originals o JOIN gridex_customer_masterdata.preparations p ON p.id=o.preparation_id CROSS JOIN LATERAL jsonb_array_elements_text(p.basis#>'{sourceProof,sourceIds}') WHERE o.company_id=c AND o.message_id=message) ORDER BY m.id FOR UPDATE$$;

--
-- Name: prelock_new_v1(); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.prelock_new_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE p gridex_customer_masterdata.preparations%rowtype;BEGIN
 IF NEW.direction='outbound' AND NEW.message_family='PRODAT' AND NEW.message_code IN('Z01','Z02','Z03','Z04','Z05','Z06','Z08','Z09') AND nullif(NEW.parsed_payload->>'customerMasterdataSourceContextId','') IS NOT NULL THEN
 SELECT * INTO p FROM gridex_customer_masterdata.preparations WHERE id=(NEW.parsed_payload->>'customerMasterdataSourceContextId')::uuid AND company_id=NEW.company_id;
 IF p.cancellation_origin_id IS NOT NULL THEN PERFORM gridex_switch_cancellations.prelock_customer_source_v1(NEW.company_id,(SELECT o.switch_id FROM gridex_switch_cancellations.origins o WHERE o.company_id=NEW.company_id AND o.id=p.cancellation_origin_id));END IF; IF p.id IS NOT NULL THEN PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=NEW.company_id AND m.id IN(SELECT value::uuid FROM jsonb_array_elements_text(p.basis#>'{sourceProof,sourceIds}')) ORDER BY m.id FOR UPDATE;END IF;END IF;RETURN NEW;END$$;

--
-- Name: preparations; Type: TABLE; Schema: gridex_customer_masterdata; Owner: -
--

CREATE TABLE gridex_customer_masterdata.preparations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    environment text,
    as_of timestamp with time zone NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    actor_user_id uuid NOT NULL,
    basis jsonb NOT NULL,
    basis_hash text NOT NULL,
    recovery_operation_id uuid,
    cancellation_origin_id uuid,
    CONSTRAINT customer_masterdata_one_scoped_origin CHECK (((recovery_operation_id IS NULL) OR (cancellation_origin_id IS NULL))),
    CONSTRAINT preparations_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text])))
);

ALTER TABLE ONLY gridex_customer_masterdata.preparations FORCE ROW LEVEL SECURITY;

--
-- Name: require_cancellation_preparation_v1(gridex_customer_masterdata.preparations, public.ediel_messages, uuid, text); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.require_cancellation_preparation_v1(p gridex_customer_masterdata.preparations, m public.ediel_messages, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_switch_cancellations.origins%rowtype;source gridex_customer_masterdata.preparations%rowtype;q jsonb;w jsonb;
BEGIN
 IF p.cancellation_origin_id IS NULL THEN
  IF p.recovery_operation_id IS NOT NULL THEN RETURN;END IF;
  w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);
  IF EXISTS(SELECT FROM gridex_switch_cancellations.origins WHERE company_id=m.company_id AND (id::text=m.source_operation_id OR intent_id=m.intent_id OR message_id=m.id)) OR w#>>'{objects,0,reason}'='Z24' THEN RAISE EXCEPTION 'customer_masterdata_cancellation_fresh_preparation_required';END IF;
  RETURN;
 END IF;
 q:=gridex_switch_cancellations.customer_draft_v1(m.company_id,p.cancellation_origin_id,actor,phase,m.intent_id,m.communication_route_id,m.raw_payload);
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=m.company_id AND id=p.cancellation_origin_id FOR SHARE;
 SELECT * INTO source FROM gridex_customer_masterdata.preparations WHERE id=(q->>'sourceContextId')::uuid AND company_id=m.company_id FOR SHARE;
 IF p.recovery_operation_id IS NOT NULL OR p.id=source.id OR p.actor_user_id IS DISTINCT FROM m.created_by OR p.customer_id IS DISTINCT FROM source.customer_id
  OR p.environment IS DISTINCT FROM source.environment OR p.as_of IS DISTINCT FROM source.as_of OR p.observed_at IS DISTINCT FROM source.observed_at OR p.basis IS DISTINCT FROM source.basis OR p.basis_hash IS DISTINCT FROM source.basis_hash
  OR m.source_operation_id IS DISTINCT FROM o.id::text OR m.original_message_id IS DISTINCT FROM o.original_message_id::text OR m.switch_request_id IS DISTINCT FROM o.switch_id
  OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.customer_id::text IS DISTINCT FROM o.basis->>'customerId'
  OR m.site_id::text IS DISTINCT FROM o.basis->>'siteId' OR m.metering_point_id::text IS DISTINCT FROM o.basis->>'meteringPointId' OR m.environment IS DISTINCT FROM o.basis->>'environment'
  OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM q#>>'{cancellationBinding,payloadHash}'
  OR (o.message_id IS NOT NULL AND (o.message_id IS DISTINCT FROM m.id OR o.payload_hash IS DISTINCT FROM m.immutable_payload_hash))
 THEN RAISE EXCEPTION 'customer_masterdata_cancellation_preparation_scope_required';END IF;
END$$;

--
-- Name: require_current_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.require_current_v1(c uuid, message uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;p gridex_customer_masterdata.preparations%rowtype;b jsonb;ud jsonb;obj jsonb;q jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_switch_cancellations.prelock_customer_message_v1(c,message); SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'customer_masterdata_message_required';END IF;
 IF m.direction<>'outbound' OR m.message_family<>'PRODAT' OR (m.message_code IN('Z01','Z02','Z03','Z04','Z05','Z06','Z08','Z09')) IS NOT TRUE THEN RETURN;END IF;
 IF m.message_code NOT IN('Z01','Z03') AND nullif(m.parsed_payload->>'customerMasterdataSourceContextId','') IS NULL AND NOT EXISTS(SELECT FROM gridex_customer_masterdata.originals WHERE company_id=c AND message_id=m.id) THEN RETURN;END IF;
 ud:=gridex_customer_masterdata.wire_ud_v1(m.raw_payload);IF ud IS NOT NULL AND jsonb_array_length(ud)=0 AND NOT EXISTS(SELECT FROM gridex_customer_masterdata.originals WHERE company_id=c AND message_id=m.id) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM gridex_customer_masterdata.originals WHERE message_id=m.id AND company_id=c) THEN
  PERFORM gridex_customer_life_events.require_actor_v1(c,actor,phase);
  IF m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NOT NULL AND m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NULL THEN q:=gridex_negative_fixtures.require_positive_message_v1(c,m.id,m.message_code);
  ELSIF m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL AND m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN q:=gridex_negative_fixtures.require_negative_message_v1(c,m.id,m.message_code);END IF;
  IF q->>'authorizesBusinessEffect'='false' AND q->>'companyId'=c::text AND m.environment='test' THEN RETURN;END IF;
 END IF;
 SELECT prep.* INTO p FROM gridex_customer_masterdata.originals o JOIN gridex_customer_masterdata.preparations prep ON prep.id=o.preparation_id WHERE o.company_id=c AND o.message_id=m.id AND o.payload_hash=m.immutable_payload_hash FOR SHARE OF prep;
 IF p.id IS NULL OR p.customer_id IS DISTINCT FROM m.customer_id OR (p.environment IS NOT NULL AND p.environment IS DISTINCT FROM m.environment) OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'customer_masterdata_immutable_original_required';END IF;
 IF gridex_ediel_retention.contract_copy_preparation_current_v1(c,p.id) IS NOT TRUE THEN RAISE EXCEPTION 'customer_masterdata_consumed_original_copy_tombstoned';END IF; PERFORM gridex_customer_masterdata.require_recovery_preparation_v1(p,m,actor,phase); PERFORM gridex_customer_masterdata.require_cancellation_preparation_v1(p,m,actor,phase); b:=gridex_customer_masterdata.basis_v1(c,p.customer_id,actor,p.as_of,p.environment,phase,p.observed_at,p.basis#>'{sourceProof,sourceIds}');
 IF b IS DISTINCT FROM p.basis OR ud IS NULL THEN RAISE EXCEPTION 'customer_masterdata_current_source_changed';END IF;
 FOR obj IN SELECT item FROM jsonb_array_elements(ud)item LOOP IF obj->'customerIdentity' IS DISTINCT FROM b->'customerIdentity' OR obj->'endUserMasterdata' IS DISTINCT FROM gridex_customer_masterdata.wire_masterdata_v1(b->'endUserMasterdata') THEN RAISE EXCEPTION 'customer_masterdata_actual_wire_changed';END IF;END LOOP;
END$$;

--
-- Name: require_recovery_preparation_v1(gridex_customer_masterdata.preparations, public.ediel_messages, uuid, text); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.require_recovery_preparation_v1(p gridex_customer_masterdata.preparations, m public.ediel_messages, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;op gridex_received_sources.prodat_recovery_operations%rowtype;o gridex_received_sources.prodat_recovery_origins%rowtype;source gridex_customer_masterdata.preparations%rowtype;
BEGIN
 IF p.recovery_operation_id IS NULL THEN IF EXISTS(SELECT FROM gridex_received_sources.prodat_recovery_operations WHERE id::text=m.source_operation_id AND company_id=m.company_id AND kind IN('contrl_correction','aperak_correction')) THEN RAISE EXCEPTION 'customer_masterdata_recovery_fresh_preparation_required';END IF;RETURN;END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(m.company_id,actor,phase);
 q:=gridex_received_sources.qualified_recovery_origin_v1(m.company_id,p.recovery_operation_id);
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p.recovery_operation_id AND company_id=m.company_id FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.prodat_recovery_origins WHERE operation_id=op.id AND company_id=m.company_id FOR SHARE;
 SELECT prep.* INTO source FROM gridex_customer_masterdata.originals original JOIN gridex_customer_masterdata.preparations prep ON prep.id=original.preparation_id WHERE original.company_id=m.company_id AND original.message_id=(q->>'sourceOriginMessageId')::uuid FOR SHARE OF prep;
 IF source.id IS NULL OR p.id=source.id OR p.actor_user_id IS DISTINCT FROM m.created_by OR p.customer_id IS DISTINCT FROM source.customer_id OR p.environment IS DISTINCT FROM source.environment OR p.as_of IS DISTINCT FROM source.as_of OR p.observed_at IS DISTINCT FROM source.observed_at OR p.basis IS DISTINCT FROM source.basis OR m.source_operation_id IS DISTINCT FROM op.id::text OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.original_message_id IS DISTINCT FROM op.original_message_id::text OR m.raw_payload IS DISTINCT FROM op.corrected_raw_payload OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM op.corrected_payload_hash THEN RAISE EXCEPTION 'customer_masterdata_recovery_preparation_scope_required';END IF;
END$$;

--
-- Name: wire_masterdata_v1(jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.wire_masterdata_v1(d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 -- P118 and the common prodatEndUserAddressWireLines primitive: dot formats
 -- only an empty first source slot when a later actual slot is known.
 IF d#>>'{streetParts,0}'='' AND EXISTS(SELECT FROM jsonb_array_elements_text(d->'streetParts') WITH ORDINALITY x(part,n) WHERE n>1 AND length(part)>0) THEN RETURN jsonb_set(d,'{streetParts,0}','"."');END IF;RETURN d;
END$$;

--
-- Name: wire_ud_v1(text); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.wire_ud_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE token jsonb;parts jsonb;objects jsonb:='[]';BEGIN
 FOR token IN SELECT item FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(raw)) item LOOP
  IF token->>'tag'='NAD' AND token#>>'{elements,1,0}'='UD' THEN
   IF jsonb_array_length(token#>'{elements,2}') IS DISTINCT FROM 3 THEN RETURN NULL;END IF;
   parts:=jsonb_build_object('customerIdentity',jsonb_build_object('id',token#>>'{elements,2,0}','qualifier',token#>>'{elements,2,1}','agency',token#>>'{elements,2,2}'),'endUserMasterdata',jsonb_build_object('nameParts',token#>'{elements,4}','streetParts',token#>'{elements,5}','postalCode',token#>>'{elements,8,0}','city',token#>>'{elements,6,0}','country',token#>>'{elements,9,0}'));
   objects:=objects||jsonb_build_array(parts);
  END IF;
 END LOOP;RETURN objects;
END$$;

--
-- Name: bind_source_before_registered_scope_v1(public.ediel_messages, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bind_source_before_registered_scope_v1(m public.ediel_messages, p_kind text, p_basis jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.source_bindings%rowtype;e gridex_ediel_ack_guide.editions%rowtype;observed timestamptz;c uuid;
BEGIN
 c:=CASE WHEN p_kind IN('technical','common') THEN (p_basis->>'companyId')::uuid ELSE m.company_id END;
 SELECT * INTO b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind=p_kind FOR SHARE;
 IF FOUND THEN IF b.company_id IS DISTINCT FROM c OR b.environment IS DISTINCT FROM m.environment OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR b.original_basis IS DISTINCT FROM p_basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;RETURN;END IF;
 IF p_kind IN('technical','common') THEN observed:=(p_basis->>'observedAt')::timestamptz;
 ELSE observed:=(gridex_ediel_inbound_context.require_v1(m.company_id,m.id)->>'observedAt')::timestamptz;END IF;
 SELECT * INTO e FROM gridex_ediel_ack_guide.editions ORDER BY installed_at DESC,source_version LIMIT 1 FOR SHARE;
 IF observed IS NULL OR e.source_version IS NULL OR observed<e.installed_at OR NOT isfinite(observed) THEN RAISE EXCEPTION 'ediel_historical_ack_guide_basis_unavailable';END IF;
 INSERT INTO gridex_ediel_ack_guide.source_bindings VALUES(m.id,p_kind,c,m.environment,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),e.source_version,p_basis);
END $$;

--
-- Name: bind_source_v1(public.ediel_messages, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bind_source_v1(m public.ediel_messages, p_kind text, p_basis jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.source_bindings%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_guide.bind_source_before_registered_scope_v1(m,p_kind,p_basis);
 SELECT * INTO STRICT b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind=p_kind;
 PERFORM gridex_ediel_ack_guide.require_registered_basis_v1(m,p_kind,p_basis,gridex_ediel_ack_guide.projection_for_original_v1(b.source_version));
END $$;

--
-- Name: bound_prodat_response_before_domain_effects_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bound_prodat_response_before_domain_effects_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.prodat_structural_response_bindings%rowtype;facet jsonb;actual jsonb;positive_indices integer[];BEGIN
 SELECT binding.* INTO b FROM gridex_ediel_ack_guide.prodat_structural_response_bindings binding JOIN gridex_ediel_outbound_owner.consumptions c ON c.witness_id=binding.witness_id WHERE c.source_message_id=m.id;
 IF b.witness_id IS NULL AND m.execution_context_snapshot->>'outboundOwnerWitnessId' IS NOT NULL THEN SELECT * INTO b FROM gridex_ediel_ack_guide.prodat_structural_response_bindings WHERE witness_id=(m.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;END IF;
 IF b.witness_id IS NULL THEN
  -- The real owner invokes the national checker before the new seal exists.
  -- A draft can read committed primary receipts, but cannot provide a final
  -- verdict. Persisted ACKs require their original immutable binding instead.
  IF m.id IS NULL AND s.message_code IN('Z06','Z10') AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=s.id) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=s.id) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=s.id AND v.company_id=s.company_id AND v.environment=s.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN
   facet:=gridex_received_sources.prodat_structural_response_v1(m.company_id,s.id,NULL);
   actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(m.raw_payload,facet->'objects');
   SELECT array_agg((x->>'lineIndex')::integer ORDER BY(x->>'lineIndex')::integer) INTO positive_indices FROM jsonb_array_elements(actual)x WHERE x->>'ercCode'='100';
   IF positive_indices IS NOT NULL AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=s.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=s.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=s.id AND v.company_id=s.company_id AND v.environment=s.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN
    RETURN gridex_received_sources.prodat_structural_response_v1(m.company_id,s.id,positive_indices);
   END IF;
  END IF;
  RETURN gridex_ediel_ack_guide.bound_prodat_response_before_structural_v1(m,s);
 END IF;
 IF b.source_message_id IS DISTINCT FROM s.id OR b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.ack_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR b.facet_hash IS DISTINCT FROM encode(sha256(convert_to(b.facet_text,'UTF8')),'hex') OR b.facet_text::jsonb->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_structural_response_frozen_binding_changed';END IF;
 RETURN b.facet_text::jsonb;
END $$;

--
-- Name: bound_prodat_response_before_structural_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bound_prodat_response_before_structural_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.prodat_response_owner_bindings%rowtype;facet jsonb;f gridex_received_sources.prodat_response_facets%rowtype;
BEGIN
 SELECT binding.* INTO b FROM gridex_ediel_ack_guide.prodat_response_owner_bindings binding JOIN gridex_ediel_outbound_owner.consumptions c ON c.witness_id=binding.witness_id WHERE c.source_message_id=m.id;
 IF b.witness_id IS NULL AND m.execution_context_snapshot->>'outboundOwnerWitnessId' IS NOT NULL THEN SELECT * INTO b FROM gridex_ediel_ack_guide.prodat_response_owner_bindings WHERE witness_id=(m.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;END IF;
 IF b.witness_id IS NULL THEN
  IF m.id IS NOT NULL THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_unavailable';END IF;
  RETURN gridex_received_sources.require_prodat_responses_v1(m.company_id,s.id);
 END IF;
 IF b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.source_message_id IS DISTINCT FROM s.id OR b.ack_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_changed';END IF;
 SELECT * INTO f FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=b.assessment_id;
 IF f.response_facts_hash IS DISTINCT FROM b.facet_hash THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_changed';END IF;
 RETURN gridex_received_sources.read_prodat_response_assessment_v1(m.company_id,s.id,b.assessment_id);
END $$;

--
-- Name: bound_prodat_response_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bound_prodat_response_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE initial jsonb;actual jsonb;positive_indices integer[];final_facet jsonb;
BEGIN
 IF m.id IS NULL AND s.message_code IN('Z04','Z05','Z14','Z15') THEN
  initial:=gridex_received_sources.require_prodat_responses_v1(m.company_id,s.id);
  actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(m.raw_payload,initial->'objects');
  SELECT array_agg(DISTINCT(x->>'lineIndex')::integer ORDER BY(x->>'lineIndex')::integer) INTO positive_indices FROM jsonb_array_elements(actual)x WHERE x->>'ercCode'='100';
  IF positive_indices IS NOT NULL THEN
   final_facet:=gridex_received_sources.prodat_structural_response_v1(m.company_id,s.id,positive_indices);
   IF final_facet IS NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_required';END IF;RETURN final_facet;
  END IF;
 END IF;
 RETURN gridex_ediel_ack_guide.bound_prodat_response_before_domain_effects_v1(m,s);
END $$;

--
-- Name: date_time_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.date_time_v1(v text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN IF v!~'^[0-9]{12}$' THEN RETURN false;END IF;RETURN to_char(make_timestamp(substr(v,1,4)::int,substr(v,5,2)::int,substr(v,7,2)::int,substr(v,9,2)::int,substr(v,11,2)::int,0),'YYYYMMDDHH24MI')=v;EXCEPTION WHEN OTHERS THEN RETURN false;END $_$;

--
-- Name: lock_prodat_scope_before_insert(); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.lock_prodat_scope_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a jsonb;BEGIN
 IF NEW.direction='outbound' AND NEW.message_family='APERAK' THEN a:=gridex_ack_authority.wire_v1(NEW.raw_payload);IF a#>>'{type,2}'='96A' AND a#>>'{type,4}'='E2SE6A' THEN
  PERFORM s.id FROM public.ediel_messages s WHERE s.id=NEW.related_message_id AND s.direction='inbound' AND s.environment=NEW.environment AND(s.company_id=NEW.company_id OR(s.company_id IS NULL AND EXISTS(SELECT FROM gridex_ediel_common_header.negative_witnesses w WHERE w.id=(NEW.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId')::uuid AND w.source_message_id=s.id AND w.company_id=NEW.company_id AND w.environment=NEW.environment AND w.payload_sha256=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex')))) FOR UPDATE;
 END IF;END IF;RETURN NEW;END $$;

--
-- Name: message_reference_profile_violation_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.message_reference_profile_violation_v1(p_raw text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cfg jsonb:='{"version":1,"field":"0062","maximumDecodedLength":14,"profiles":[{"technicalProfile":["PRODAT","D","97A","UN","E2SE6A"],"source":{"id":"P","filename":"260630_Ediel_PRODAT_APERAK_Anvisning_version_26-A_16-B(6).pdf","sha256":"83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95","pages":[41,84]}},{"technicalProfile":["APERAK","D","96A","UN","E2SE6A"],"source":{"id":"P","filename":"260630_Ediel_PRODAT_APERAK_Anvisning_version_26-A_16-B(6).pdf","sha256":"83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95","pages":[97,105]}},{"technicalProfile":["PRODAT","D","97A","UN","E2SE6B"],"source":{"id":"P","filename":"260630_Ediel_PRODAT_APERAK_Anvisning_version_26-A_16-B(6).pdf","sha256":"83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95","pages":[41,84]}},{"technicalProfile":["APERAK","D","96A","UN","E2SE6B"],"source":{"id":"P","filename":"260630_Ediel_PRODAT_APERAK_Anvisning_version_26-A_16-B(6).pdf","sha256":"83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95","pages":[97,105]}},{"technicalProfile":["UTILTS","D","02B","UN","E5SE5A"],"source":{"id":"U","filename":"260331_Ediel_UTILTS-APERAK_Anvisning_version_25-A-4.pdf","sha256":"0524c18f38864ebe081dec9d3d53f1797b224ef0af7b01986627e895f47d99be","pages":[71,100]}},{"technicalProfile":["APERAK","D","04A","UN","E5SE5A"],"source":{"id":"U","filename":"260331_Ediel_UTILTS-APERAK_Anvisning_version_25-A-4.pdf","sha256":"0524c18f38864ebe081dec9d3d53f1797b224ef0af7b01986627e895f47d99be","pages":[112,120]}}]}'::jsonb;tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(p_raw);token jsonb;profile jsonb;maximum integer;reference jsonb;
BEGIN
 IF tokens IS NULL THEN RETURN false;END IF; -- Existing syntax owner handles unreadable wire.
 FOR token IN SELECT t FROM jsonb_array_elements(tokens)t LOOP
  IF token->>'tag'='UNH' THEN
   maximum:=NULL;
   FOR profile IN SELECT p FROM jsonb_array_elements(cfg->'profiles')p LOOP
    IF NOT EXISTS(SELECT FROM jsonb_array_elements_text(profile->'technicalProfile')WITH ORDINALITY part(value,position)
     WHERE token#>>ARRAY['elements','2',(part.position-1)::text] IS DISTINCT FROM part.value) THEN maximum:=(cfg->>'maximumDecodedLength')::integer;EXIT;END IF;
   END LOOP;
   reference:=token#>'{elements,1}';
  ELSIF token->>'tag'='UNT' THEN reference:=token#>'{elements,2}';
  ELSE CONTINUE;END IF;
  IF maximum IS NOT NULL AND EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(reference,'[]'::jsonb))part WHERE char_length(part)>maximum) THEN RETURN true;END IF;
  IF token->>'tag'='UNT' THEN maximum:=NULL;END IF;
 END LOOP;
 RETURN false;
END $$;

--
-- Name: prepared_reference_fixture_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prepared_reference_fixture_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;BEGIN
 IF i->>'environment'='test' AND i->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL
  AND i->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN
  q:=gridex_negative_fixtures.prepared_negative_fixture_v1((i->>'companyId')::uuid,(i->>'sourceQualifiedNegativeFixtureWitnessId')::uuid,i->>'rawPayload',(i->>'actorUserId')::uuid);
 END IF;RETURN q;END $$;

--
-- Name: prodat_original_outcomes_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_original_outcomes_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE facet jsonb;
BEGIN
 IF m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL AND gridex_ediel_header_negative_birth.evidence_v1(s) IS NOT NULL THEN RETURN gridex_ediel_header_negative_birth.scopes_v1(m.raw_payload,s);END IF;
 IF m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL OR EXISTS(SELECT FROM gridex_ediel_ack_guide.established_prodat_acks WHERE ack_message_id=m.id) THEN RETURN gridex_ediel_ack_guide.prodat_outcomes_v1(m.raw_payload,s.raw_payload);END IF;
 facet:=gridex_ediel_ack_guide.bound_prodat_response_v1(m,s);
 RETURN gridex_ediel_ack_guide.prodat_outcomes_v2(m.raw_payload,s.raw_payload,facet->'objects');
END $$;

--
-- Name: prodat_outcomes_v1(text, text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_outcomes_v1(raw text, source_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb:=gridex_ack_authority.wire_v1(raw);s jsonb:=gridex_ack_authority.wire_v1(source_raw);tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);original jsonb:=gridex_utilts_binding.wire_tokens_v1(source_raw);t jsonb;g jsonb;source_objects jsonb;matches jsonb;result jsonb:='[]';group_end integer;own_li text;own_object text;erc_index integer:=0;outcome text;
BEGIN
 IF a IS NULL OR s IS NULL OR a->>'family'<>'APERAK' OR a#>>'{type,2}'<>'96A' OR a#>>'{type,4}'<>'E2SE6A' OR s->>'family'<>'PRODAT' OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 IF a->>'function'='27' THEN
  IF jsonb_array_length(coalesce(a->'erc','[]'))=0 OR EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc')e WHERE e='100') THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  RETURN jsonb_build_array(jsonb_build_object('scope','message','reference',coalesce(s->>'document',''),'physicalReference',jsonb_build_object('documentId',s->>'document'),'outcome','negative'));
 END IF;
 IF a->>'function' IS DISTINCT FROM '34' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 SELECT coalesce(jsonb_agg(object),'[]') INTO source_objects FROM (
  SELECT jsonb_build_object('lineIndex',(lin->>'index')::int,'id',lin#>>'{elements,3,0}','li',(SELECT min(r#>>'{elements,1,1}') FROM jsonb_array_elements(original)r WHERE r->>'tag'='RFF' AND r#>>'{elements,1,0}'='LI' AND (r->>'index')::int>(lin->>'index')::int AND (r->>'index')::int<coalesce((SELECT min((n->>'index')::int) FROM jsonb_array_elements(original)n WHERE n->>'tag' IN('LIN','UNT') AND (n->>'index')::int>(lin->>'index')::int),2147483647))) object FROM jsonb_array_elements(original)lin WHERE lin->>'tag'='LIN')objects;
 IF EXISTS(SELECT FROM jsonb_array_elements(original)lin WHERE lin->>'tag'='LIN' AND (SELECT count(*) FROM jsonb_array_elements(original)r WHERE r->>'tag'='RFF' AND r#>>'{elements,1,0}'='LI' AND(r->>'index')::int>(lin->>'index')::int AND(r->>'index')::int<coalesce((SELECT min((n->>'index')::int) FROM jsonb_array_elements(original)n WHERE n->>'tag' IN('LIN','UNT') AND(n->>'index')::int>(lin->>'index')::int),2147483647))>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::int LOOP
  SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>(t->>'index')::int AND x->>'tag' IN('ERC','UNT','UNZ');
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' IN('LI','Z07') AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end GROUP BY x#>>'{elements,1,0}' HAVING count(*)>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  SELECT min(x#>>'{elements,1,1}') INTO own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT min(x#>>'{elements,1,1}') INTO own_object FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT jsonb_agg(x) INTO matches FROM jsonb_array_elements(source_objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_object END AND(own_object IS NULL OR x->>'id'=own_object);
  IF jsonb_array_length(coalesce(matches,'[]'))<>1 THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  -- Outcome is the existing native wire owner's own ERC ordinal projection.
  -- No national error code or field label is selected or inferred here.
  IF a->'erc'->>erc_index IS DISTINCT FROM t#>>'{elements,1,0}' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  outcome:=CASE WHEN a->'erc'->>erc_index='100' THEN 'positive' ELSE 'negative' END;erc_index:=erc_index+1;
  g:=jsonb_build_object('scope','object','reference',matches#>>'{0,lineIndex}','physicalReference',matches->0,'outcome',outcome);result:=result||jsonb_build_array(g);
 END LOOP;
 IF jsonb_array_length(result)=0 OR EXISTS(SELECT FROM jsonb_array_elements(result)x GROUP BY x->>'scope',x->>'reference' HAVING count(DISTINCT x->>'outcome')<>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_contradictory_own_outcome';END IF;
 SELECT jsonb_agg(x ORDER BY x->>'reference') INTO result FROM(SELECT DISTINCT x FROM jsonb_array_elements(result)x)unique_scopes;RETURN result;
END $$;

--
-- Name: prodat_outcomes_v2(text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_outcomes_v2(raw text, source_raw text, p_objects jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb:=gridex_ack_authority.wire_v1(raw);s jsonb:=gridex_ack_authority.wire_v1(source_raw);tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);original jsonb:=gridex_utilts_binding.wire_tokens_v1(source_raw);t jsonb;g jsonb;source_objects jsonb;matches jsonb;result jsonb:='[]';group_end integer;own_li text;own_object text;erc_index integer:=0;outcome text;
BEGIN
 IF a IS NULL OR s IS NULL OR a->>'family'<>'APERAK' OR a#>>'{type,2}'<>'96A' OR a#>>'{type,4}'<>'E2SE6A' OR s->>'family'<>'PRODAT' OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 IF a->>'function'='27' THEN
  IF jsonb_array_length(coalesce(a->'erc','[]'))=0 OR EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc')e WHERE e='100') THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  RETURN jsonb_build_array(jsonb_build_object('scope','message','reference',coalesce(s->>'document',''),'physicalReference',jsonb_build_object('documentId',s->>'document'),'outcome','negative'));
 END IF;
 IF a->>'function' IS DISTINCT FROM '34' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('lineIndex',x->'lineIndex','id',x->'id','li',x->'li')),'[]') INTO source_objects FROM jsonb_array_elements(p_objects)x;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::int LOOP
  SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>(t->>'index')::int AND x->>'tag' IN('ERC','UNT','UNZ');
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' IN('LI','Z07') AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end GROUP BY x#>>'{elements,1,0}' HAVING count(*)>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  SELECT min(x#>>'{elements,1,1}') INTO own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT min(x#>>'{elements,1,1}') INTO own_object FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND(x->>'index')::int>(t->>'index')::int AND(x->>'index')::int<group_end;
  SELECT jsonb_agg(x) INTO matches FROM jsonb_array_elements(source_objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_object END AND(own_object IS NULL OR x->>'id'=own_object);
  IF jsonb_array_length(coalesce(matches,'[]'))<>1 THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  -- Outcome is the existing native wire owner's own ERC ordinal projection.
  -- No national error code or field label is selected or inferred here.
  IF a->'erc'->>erc_index IS DISTINCT FROM t#>>'{elements,1,0}' THEN RAISE EXCEPTION 'ediel_prodat_ack_physical_scope_required';END IF;
  outcome:=CASE WHEN a->'erc'->>erc_index='100' THEN 'positive' ELSE 'negative' END;erc_index:=erc_index+1;
  g:=jsonb_build_object('scope','object','reference',matches#>>'{0,lineIndex}','physicalReference',matches->0,'outcome',outcome);result:=result||jsonb_build_array(g);
 END LOOP;
 IF jsonb_array_length(result)=0 OR EXISTS(SELECT FROM jsonb_array_elements(result)x GROUP BY x->>'scope',x->>'reference' HAVING count(DISTINCT x->>'outcome')<>1) THEN RAISE EXCEPTION 'ediel_prodat_ack_contradictory_own_outcome';END IF;
 SELECT jsonb_agg(x ORDER BY x->>'reference') INTO result FROM(SELECT DISTINCT x FROM jsonb_array_elements(result)x)unique_scopes;RETURN result;
END $$;

--
-- Name: prodat_scope_overlap_v1(jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_scope_overlap_v1(a jsonb, b jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT a->>'scope'='message' OR b->>'scope'='message' OR(a->>'scope'=b->>'scope' AND a->>'reference'=b->>'reference')$$;

--
-- Name: prodat_unused_document_before_storage_v1(); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_unused_document_before_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.direction='outbound' AND NEW.raw_payload IS NOT NULL THEN
  IF TG_OP='INSERT' THEN
   PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(NEW.raw_payload);
  ELSIF OLD.raw_payload IS NULL THEN
   PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(NEW.raw_payload);
  END IF;
 END IF;RETURN NEW;
END$$;

--
-- Name: prodat_wire_responses_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_wire_responses_v1(raw text, objects jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);a jsonb:=gridex_ack_authority.wire_v1(raw);t jsonb;ftx jsonb;own_li text;own_id text;object jsonb;result jsonb:='[]';finish integer;n integer;scope text;
BEGIN
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a#>>'{type,2}' IS DISTINCT FROM '96A' OR a#>>'{type,4}' IS DISTINCT FROM 'E2SE6A' OR a->>'function' NOT IN('27','34') THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
 scope:=CASE a->>'function' WHEN '27' THEN 'message' ELSE 'object' END;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::integer LOOP
  SELECT min((x->>'index')::integer) INTO finish FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>(t->>'index')::integer AND x->>'tag' IN('ERC','UNT','UNZ');
  SELECT x INTO ftx FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND(x->>'index')::integer=(t->>'index')::integer+1;
  IF ftx IS NULL THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  SELECT count(*),min(x#>>'{elements,1,1}') INTO n,own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::integer>(t->>'index')::integer AND(x->>'index')::integer<finish;
  IF n>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  SELECT count(*),min(x#>>'{elements,1,1}') INTO n,own_id FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND(x->>'index')::integer>(t->>'index')::integer AND(x->>'index')::integer<finish;
  IF n>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;object:=NULL;
  IF scope='object' THEN
   SELECT count(*) INTO n FROM jsonb_array_elements(objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_id END AND(own_id IS NULL OR x->>'id'=own_id);
   SELECT x INTO object FROM jsonb_array_elements(objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_id END AND(own_id IS NULL OR x->>'id'=own_id);
   IF n<>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  END IF;
  result:=result||jsonb_build_array(jsonb_build_object('scope',scope,'lineIndex',CASE WHEN scope='object' THEN object->'lineIndex' ELSE 'null'::jsonb END,
   'ercCode',t#>>'{elements,1,0}','fieldCode',nullif(ftx#>>'{elements,3,0}',''),'text',ftx#>>'{elements,4,0}','id',own_id,'li',own_li));
 END LOOP;
 RETURN result;
END $$;

--
-- Name: projection_before_err_reason_scopes_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(p_source_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb;extended jsonb;
BEGIN
 SELECT projection INTO STRICT original FROM gridex_ediel_ack_guide.editions WHERE source_version=p_source_version;
 IF original ? 'registeredGuideScopes' THEN RETURN original;END IF;
 SELECT e.projection INTO extended FROM gridex_ediel_ack_guide.edition_extensions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.extended_source_version WHERE x.original_source_version=p_source_version;
 IF extended IS NULL OR extended->'constraints' IS DISTINCT FROM original->'constraints' OR extended->'originalSources' IS DISTINCT FROM original->'originalSources' THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 RETURN extended;
END $$;

--
-- Name: projection_for_original_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.projection_for_original_v1(p_source_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb;known jsonb;n integer;
BEGIN
 original:=gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(p_source_version);
 IF original ? 'utiltsErrReasonGuideScopes' THEN RETURN original;END IF;
 SELECT count(*) INTO n FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 SELECT e.projection INTO known FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 IF n<>1 OR known IS NULL THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 -- Supplemental source knowledge only: no new reception/version/acceptance.
 RETURN original||jsonb_build_object('utiltsErrReasonGuideScopes',known->'utiltsErrReasonGuideScopes');
END $$;

--
-- Name: qualify_err_reason_projection_v1(jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.qualify_err_reason_projection_v1(p_projection jsonb, p_basis jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb:=p_basis#>'{snapshot,rulePack}';reasons jsonb;n integer;
BEGIN
 IF r->>'family' IS DISTINCT FROM 'UTILTS' THEN RETURN p_projection;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 SELECT s->'allowedReasons' INTO reasons FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 IF n<>1 OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)=0 THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 RETURN jsonb_set(p_projection,'{utiltsErr,allowedReasons}',reasons,false);
END $$;

--
-- Name: require_before_mixed_object_results_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_before_mixed_object_results_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;b gridex_ediel_ack_guide.source_bindings%rowtype;projection jsonb;basis jsonb;binding_kind text;observed timestamptz:=clock_timestamp();stamp text;document_at timestamptz;
BEGIN
 IF m.message_family NOT IN('APERAK','CONTRL','UTILTS_ERR') THEN RETURN;END IF;
 binding_kind:=CASE WHEN m.message_family='CONTRL' THEN 'technical' WHEN m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN 'common' ELSE 'national' END;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND (company_id=m.company_id OR (binding_kind IN('technical','common') AND company_id IS NULL)) AND environment=m.environment AND direction='inbound' FOR SHARE;IF source.id IS NULL THEN RAISE EXCEPTION 'ediel_native_ack_guide_source_required';END IF;
 basis:=CASE binding_kind WHEN 'technical' THEN gridex_ediel_technical_ack.require_source_v1(m.company_id,source.id) WHEN 'common' THEN gridex_ediel_common_header.require_ack_v1(m) ELSE gridex_ediel_source_rules.require_v1(m.company_id,source.id) END;
 SELECT * INTO b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=source.id AND kind=binding_kind FOR SHARE;IF b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_ack_guide_basis_unavailable';END IF;
 IF b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR b.original_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(b.source_version);projection:=gridex_ediel_ack_guide.qualify_err_reason_projection_v1(projection,basis);PERFORM gridex_ediel_ack_guide.require_registered_basis_v1(source,binding_kind,basis,projection);
 IF NOT coalesce(gridex_ediel_ack_guide.validate_response_for_message_v1(m,source,projection),false) THEN RAISE EXCEPTION 'ediel_native_ack_guide_invalid';END IF;
 IF m.message_family='UTILTS_ERR' AND projection#>>'{utiltsErr,documentDate,noFuture}'='true' THEN
  SELECT x#>>'{elements,1,1}' INTO stamp FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload))x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=projection#>>'{utiltsErr,documentDate,qualifier}';
  document_at:=(make_timestamp(substr(stamp,1,4)::int,substr(stamp,5,2)::int,substr(stamp,7,2)::int,substr(stamp,9,2)::int,substr(stamp,11,2)::int,0) AT TIME ZONE 'UTC')-interval '1 hour';IF document_at>observed THEN RAISE EXCEPTION 'ediel_native_err_document_date_future';END IF;
 END IF;
END $$;

--
-- Name: require_before_prodat_scope_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_before_prodat_scope_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;tokens jsonb;t jsonb;group_tokens jsonb;next_group integer;li text;point text;r gridex_received_sources.prodat_mixed_object_receipts%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_guide.require_before_mixed_object_results_v1(m);
 IF m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'PRODAT' THEN RETURN;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'='100') THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'<>'100') THEN
  IF EXISTS(SELECT FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=source.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') AND a.facts_text::jsonb->>'applicationDecision'='rejected' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)) THEN RAISE EXCEPTION 'prodat_mixed_ack_whole_source_success_forbidden';END IF;
  RETURN;
 END IF;
 SELECT * INTO r FROM gridex_received_sources.prodat_mixed_object_receipts WHERE source_message_id=source.id AND company_id=m.company_id AND environment=m.environment AND source_payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') FOR SHARE;
 IF NOT FOUND AND EXISTS(SELECT FROM gridex_received_sources.supply_object_partitions p WHERE p.source_message_id=source.id AND p.company_id=m.company_id
   AND p.environment=m.environment AND p.payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'))
  AND EXISTS(SELECT FROM pg_trigger WHERE tgrelid='public.ediel_messages'::regclass AND tgname='domain_response_birth' AND tgenabled<>'D'
   AND tgfoid='gridex_received_sources.require_domain_response_at_birth_v1()'::regprocedure) THEN RETURN;END IF;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=a.id AND f.facts_hash=r.object_facts_hash AND f.source_payload_hash=r.source_payload_hash WHERE a.facts_hash=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND a.source_message_id=source.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=r.source_payload_hash AND a.facts_text::jsonb->>'syntaxDecision'='accepted' AND a.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))
 OR NOT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_reply_outbox o WHERE o.source_message_id=source.id AND o.company_id=m.company_id AND o.environment=m.environment AND o.source_payload_hash=r.source_payload_hash AND o.object_facts_hash=r.object_facts_hash) THEN RAISE EXCEPTION 'prodat_mixed_ack_committed_own_results_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'='100' LOOP
  SELECT min((x->>'index')::integer) INTO next_group FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::integer>(t->>'index')::integer AND x->>'tag' IN('ERC','UNT');
  SELECT jsonb_agg(x) INTO group_tokens FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::integer>(t->>'index')::integer AND (x->>'index')::integer<next_group;
  SELECT x#>>'{elements,1,1}' INTO li FROM jsonb_array_elements(group_tokens) x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI';
  SELECT x#>>'{elements,1,1}' INTO point FROM jsonb_array_elements(group_tokens) x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07';
  IF li IS NULL OR point IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=point AND o->>'lineItemReference'=li AND o->>'disposition'='accepted')
   OR NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations c WHERE c.company_id=m.company_id AND c.source_message_id=source.id AND c.source_object->>'point'=point AND c.source_object->>'li'=li) THEN RAISE EXCEPTION 'prodat_mixed_ack_own_commit_mismatch';END IF;
 END LOOP;
END $$;

--
-- Name: require_fresh_ack_envelope_before_storage_v1(); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_fresh_ack_envelope_before_storage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.direction='outbound' AND NEW.raw_payload IS NOT NULL THEN
  IF TG_OP='INSERT' THEN PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(NEW.raw_payload,NEW.message_family);
  ELSIF OLD.raw_payload IS NULL THEN PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(NEW.raw_payload,NEW.message_family);END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: require_fresh_ack_envelope_v1(text, text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(p_raw text, p_declared_family text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(p_raw);unb jsonb;unh jsonb;unt jsonb;unz jsonb;n integer;is_ack boolean;
BEGIN
 is_ack:=coalesce(p_declared_family IN('CONTRL','APERAK','UTILTS_ERR'),false);
 IF tokens IS NULL THEN
  IF is_ack THEN RAISE EXCEPTION 'ediel_fresh_ack_envelope_invalid';END IF;
  -- An unreadable non-declared payload remains subject to the existing owner
  -- admission; do not introduce an alternate prefix/body parser here.
  RETURN;
 END IF;
 is_ack:=is_ack OR EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}' IN('CONTRL','APERAK'))
  OR(EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='UTILTS')
   AND EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='ERR'));
 IF NOT is_ack THEN RETURN;END IF;
 n:=jsonb_array_length(tokens);
 IF n<4 OR EXISTS(SELECT FROM unnest(ARRAY['UNB','UNH','UNT','UNZ'])tag WHERE(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'=tag)<>1)
  OR tokens->0->>'tag' IS DISTINCT FROM 'UNB' OR tokens->1->>'tag' IS DISTINCT FROM 'UNH'
  OR tokens->(n-2)->>'tag' IS DISTINCT FROM 'UNT' OR tokens->(n-1)->>'tag' IS DISTINCT FROM 'UNZ' THEN
  RAISE EXCEPTION 'ediel_fresh_ack_envelope_invalid';
 END IF;
 unb:=tokens->0;unh:=tokens->1;unt:=tokens->(n-2);unz:=tokens->(n-1);
 -- Each service count/reference is one decoded simple element. No trim,
 -- truncation or re-splitting of a released data/component separator occurs.
 IF jsonb_array_length(coalesce(unb#>'{elements,5}','[]'))<>1 OR nullif(unb#>>'{elements,5,0}','') IS NULL
  OR jsonb_array_length(coalesce(unz#>'{elements,2}','[]'))<>1 OR nullif(unz#>>'{elements,2,0}','') IS NULL
  OR unb#>>'{elements,5,0}' IS DISTINCT FROM unz#>>'{elements,2,0}'
  OR jsonb_array_length(coalesce(unh#>'{elements,1}','[]'))<>1 OR nullif(unh#>>'{elements,1,0}','') IS NULL
  OR jsonb_array_length(coalesce(unt#>'{elements,2}','[]'))<>1 OR nullif(unt#>>'{elements,2,0}','') IS NULL
  OR unh#>>'{elements,1,0}' IS DISTINCT FROM unt#>>'{elements,2,0}'
  OR jsonb_array_length(coalesce(unz#>'{elements,1}','[]'))<>1 OR coalesce(unz#>>'{elements,1,0}','')!~'^[0-9]+$'
  OR jsonb_array_length(coalesce(unt#>'{elements,1}','[]'))<>1 OR coalesce(unt#>>'{elements,1,0}','')!~'^[0-9]+$' THEN
  RAISE EXCEPTION 'ediel_fresh_ack_envelope_invalid';
 END IF;
 IF(unz#>>'{elements,1,0}')::numeric<>1 OR(unt#>>'{elements,1,0}')::numeric<>n-2 THEN
  RAISE EXCEPTION 'ediel_fresh_ack_envelope_invalid';
 END IF;
END $_$;

--
-- Name: require_message_reference_profile_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_message_reference_profile_v1(p_raw text, p_qualification jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NOT gridex_ediel_ack_guide.message_reference_profile_violation_v1(p_raw) THEN RETURN;END IF;
 IF p_qualification->>'kind'='source_qualified_negative_fixture' AND p_qualification->>'expectedOutcome'='negative'
  AND p_qualification->>'authorizesBusinessEffect'='false' AND p_qualification->'expectedDiagnosticCodes' ? 'message_reference_length_invalid' THEN RETURN;END IF;
 RAISE EXCEPTION 'ediel_message_reference_length_invalid';END $$;

--
-- Name: require_prodat_scope_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_prodat_scope_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb;source public.ediel_messages%rowtype;own_scopes jsonb;scope jsonb;prior_scope jsonb;prior public.ediel_messages%rowtype;row_scope gridex_ediel_ack_guide.outbound_prodat_scopes%rowtype;source_hash text;ack_hash text;protected boolean;
BEGIN
 IF gridex_ediel_duplicate_responses.allows_message_v1(m) THEN RETURN;END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;a:=gridex_ack_authority.wire_v1(m.raw_payload);
 IF a IS NULL OR a#>>'{type,2}' IS DISTINCT FROM '96A' OR a#>>'{type,4}' IS DISTINCT FROM 'E2SE6A' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND direction='inbound' AND environment=m.environment AND(company_id=m.company_id OR(company_id IS NULL AND m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL)) FOR UPDATE;
 IF source.id IS NULL OR m.company_id IS NULL THEN RAISE EXCEPTION 'ediel_prodat_ack_source_scope_required';END IF;
 source_hash:=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex');ack_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');own_scopes:=gridex_ediel_ack_guide.prodat_original_outcomes_v1(m,source);
 IF EXISTS(SELECT FROM gridex_ediel_ack_guide.outbound_prodat_scopes r WHERE r.ack_message_id=m.id AND(r.source_message_id IS DISTINCT FROM source.id OR r.company_id IS DISTINCT FROM m.company_id OR r.environment IS DISTINCT FROM m.environment OR r.source_payload_sha256 IS DISTINCT FROM source_hash OR r.ack_payload_sha256 IS DISTINCT FROM ack_hash)) THEN RAISE EXCEPTION 'ediel_prodat_ack_scope_original_changed';END IF;
 -- The source row lock serializes every whole-message/own-object reservation.
 -- Old protected ACK originals are read as actual raw scopes; mutable status,
 -- ack_outcome and caller parsed hints never establish a historical decision.
 FOR prior IN SELECT p.* FROM public.ediel_messages p WHERE p.id IS DISTINCT FROM m.id AND (
  (p.direction='outbound' AND p.message_family='APERAK' AND p.related_message_id=source.id AND p.company_id=m.company_id AND p.environment=m.environment)
  OR EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses w ON w.id=c.witness_id WHERE c.source_message_id=p.id AND w.related_message_id=source.id AND w.family='APERAK')
  OR EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions c JOIN gridex_ediel_common_header.negative_witnesses w ON w.id=c.witness_id WHERE c.ack_message_id=p.id AND w.source_message_id=source.id)) FOR SHARE LOOP
  IF gridex_ediel_duplicate_responses.is_duplicate_ack_v1(prior.id) THEN CONTINUE;END IF;
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.environment IS DISTINCT FROM m.environment OR prior.direction IS DISTINCT FROM 'outbound' OR prior.message_family IS DISTINCT FROM 'APERAK' OR prior.related_message_id IS DISTINCT FROM source.id THEN RAISE EXCEPTION 'ediel_historical_prodat_ack_scope_basis_unavailable';END IF;
  IF gridex_ack_authority.wire_v1(prior.raw_payload)#>>'{type,2}' IS DISTINCT FROM '96A' THEN RAISE EXCEPTION 'ediel_historical_prodat_ack_scope_basis_unavailable';END IF;
  protected:=EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses w ON w.id=c.witness_id WHERE c.source_message_id=prior.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(prior.raw_payload,'UTF8')),'hex') AND w.company_id=c.company_id AND w.environment=c.environment AND w.payload_sha256=c.payload_sha256 AND w.related_message_id=source.id AND w.family='APERAK')
   OR EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions c JOIN gridex_ediel_common_header.negative_witnesses w ON w.id=c.witness_id WHERE c.ack_message_id=prior.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(prior.raw_payload,'UTF8')),'hex') AND w.company_id=c.company_id AND w.environment=c.environment AND w.payload_sha256=c.payload_sha256 AND w.source_message_id=source.id);
  IF NOT protected THEN RAISE EXCEPTION 'ediel_historical_prodat_ack_scope_basis_unavailable';END IF;
  FOR prior_scope IN SELECT x FROM jsonb_array_elements(gridex_ediel_ack_guide.prodat_original_outcomes_v1(prior,source))x LOOP
   FOR scope IN SELECT x FROM jsonb_array_elements(own_scopes)x LOOP
    IF gridex_ediel_ack_guide.prodat_scope_overlap_v1(scope,prior_scope) THEN IF scope->>'outcome' IS DISTINCT FROM prior_scope->>'outcome' THEN RAISE EXCEPTION 'ediel_prodat_ack_scope_conflicting_outcome';ELSE RAISE EXCEPTION 'ediel_prodat_ack_scope_already_fixed';END IF;END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 FOR scope IN SELECT x FROM jsonb_array_elements(own_scopes)x LOOP
  FOR row_scope IN SELECT * FROM gridex_ediel_ack_guide.outbound_prodat_scopes r WHERE r.source_message_id=source.id FOR SHARE LOOP
   IF row_scope.company_id IS DISTINCT FROM m.company_id OR row_scope.environment IS DISTINCT FROM m.environment OR row_scope.source_payload_sha256 IS DISTINCT FROM source_hash THEN RAISE EXCEPTION 'ediel_prodat_ack_scope_original_changed';END IF;
   IF gridex_ediel_ack_guide.prodat_scope_overlap_v1(scope,jsonb_build_object('scope',row_scope.scope_kind,'reference',row_scope.scope_reference)) THEN
    IF row_scope.outcome IS DISTINCT FROM scope->>'outcome' THEN RAISE EXCEPTION 'ediel_prodat_ack_scope_conflicting_outcome';END IF;
    IF row_scope.ack_message_id IS DISTINCT FROM m.id OR row_scope.ack_payload_sha256 IS DISTINCT FROM ack_hash OR row_scope.physical_source_reference IS DISTINCT FROM scope->'physicalReference' THEN RAISE EXCEPTION 'ediel_prodat_ack_scope_already_fixed';END IF;
   END IF;
  END LOOP;
  IF m.id IS NULL THEN CONTINUE;END IF;
  INSERT INTO gridex_ediel_ack_guide.outbound_prodat_scopes(company_id,environment,source_message_id,source_payload_sha256,scope_kind,scope_reference,physical_source_reference,outcome,ack_message_id,ack_payload_sha256)
   SELECT m.company_id,m.environment,source.id,source_hash,scope->>'scope',scope->>'reference',scope->'physicalReference',scope->>'outcome',m.id,ack_hash
   WHERE NOT EXISTS(SELECT FROM gridex_ediel_ack_guide.outbound_prodat_scopes r WHERE r.source_message_id=source.id AND r.scope_kind=scope->>'scope' AND r.scope_reference=scope->>'reference')
   ON CONFLICT DO NOTHING;
 END LOOP;
END $$;

--
-- Name: require_prodat_unused_document_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_prodat_unused_document_v1(p_raw text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cfg jsonb;tokens jsonb;bgm jsonb;position integer;
BEGIN
 SELECT projection#>'{constraints,PRODAT}' INTO STRICT cfg
 FROM gridex_ediel_ack_guide.editions
 WHERE source_version='a30473a34535076e12e46386563adb3fa36431a0e7a245fc1be666c5737e8708';
 tokens:=gridex_utilts_binding.wire_tokens_v1(p_raw);
 -- The existing syntax/source owner rejects unreadable or wrong profiles.
 -- This projection adds no alternate family inference or body parser.
 IF tokens IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t
  WHERE t->>'tag'='UNH' AND t#>'{elements,2}'=cfg->'technicalProfile') THEN RETURN;END IF;
 FOR bgm IN SELECT t FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' LOOP
  FOR position IN SELECT value::integer FROM jsonb_array_elements_text(cfg->'unusedDocumentElements') LOOP
   IF EXISTS(SELECT FROM jsonb_array_elements_text(bgm->'elements'->position)component WHERE component<>'') THEN
    RAISE EXCEPTION 'ediel_prodat_aperak_unused_document_element';
   END IF;
  END LOOP;
 END LOOP;
END$$;

--
-- Name: require_reference_profile_before_birth_v1(); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_reference_profile_before_birth_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;actor uuid;BEGIN
 IF NEW.direction='outbound' AND NEW.raw_payload IS NOT NULL AND(TG_OP='INSERT' OR OLD.raw_payload IS NULL)
  AND gridex_ediel_ack_guide.message_reference_profile_violation_v1(NEW.raw_payload) THEN
  IF NEW.environment='test' AND NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL
   AND NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN
   SELECT actor_user_id INTO actor FROM gridex_negative_fixtures.negative_prepared_witnesses WHERE id=(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid AND company_id=NEW.company_id FOR SHARE;
   q:=gridex_negative_fixtures.prepared_negative_fixture_v1(NEW.company_id,(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid,NEW.raw_payload,actor);
  END IF;PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(NEW.raw_payload,q);
 END IF;RETURN NEW;END $$;

