-- Name: require_reference_profile_current_message_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_reference_profile_current_message_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;BEGIN
 IF NOT gridex_ediel_ack_guide.message_reference_profile_violation_v1(m.raw_payload) THEN RETURN;END IF;
 IF m.environment='test' AND m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL
  AND m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN q:=gridex_negative_fixtures.require_negative_message_v1(m.company_id,m.id,m.message_code);END IF;
 PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(m.raw_payload,q);END $$;

--
-- Name: require_registered_basis_v1(public.ediel_messages, text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_registered_basis_v1(m public.ediel_messages, p_kind text, p_basis jsonb, p_projection jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;v text;n integer;physical jsonb;
BEGIN
 IF p_kind='technical' THEN RETURN;END IF;
 IF p_kind='common' THEN r:=p_basis#>'{familyEdition,rulePack}';v:=p_basis#>>'{familyEdition,version}';ELSE r:=p_basis#>'{snapshot,rulePack}';v:=p_basis->>'version';
  IF p_basis#>>'{snapshot,version}' IS DISTINCT FROM v THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 END IF;
 IF p_kind='common' THEN physical:=gridex_ediel_header_negative_birth.source_wire_v1(m);ELSE physical:=gridex_ack_authority.wire_v1(m.raw_payload);END IF;
 IF r IS NULL OR physical IS NULL OR r->>'family' IS DISTINCT FROM physical->>'family' OR nullif(v,'') IS NULL THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(p_projection->'registeredGuideScopes')s WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 IF n<>1 THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
END $$;

--
-- Name: require_unused_unh_before_birth_v1(); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_unused_unh_before_birth_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;actor uuid;BEGIN
 IF NEW.direction='outbound' AND NEW.raw_payload IS NOT NULL AND(TG_OP='INSERT' OR OLD.raw_payload IS NULL)
  AND gridex_ediel_ack_guide.unused_unh_violation_v1(NEW.raw_payload) THEN
  IF NEW.environment='test' AND NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NOT NULL
   AND NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS NULL THEN
   SELECT actor_user_id INTO actor FROM gridex_negative_fixtures.negative_prepared_witnesses WHERE id=(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid AND company_id=NEW.company_id FOR SHARE;
   q:=gridex_negative_fixtures.prepared_negative_fixture_v1(NEW.company_id,(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid,NEW.raw_payload,actor);
  END IF;PERFORM gridex_ediel_ack_guide.require_unused_unh_v1(NEW.raw_payload,'outbound',q);
 END IF;RETURN NEW;END $$;

