CREATE FUNCTION gridex_ediel_ack_guide.validate_prodat_planned_v1(p_raw text, p_source_raw text, p_projection jsonb, p_source_objects jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
