-- Name: service_scope_immutable_v1(); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.service_scope_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN RAISE EXCEPTION 'ediel_ack_service_scope_immutable';END $$;

--
-- Name: actor_v2(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.actor_v2(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF mode IS NULL OR mode NOT IN('read','report') THEN RETURN false;END IF;
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,CASE mode WHEN 'read' THEN 'read' ELSE 'prepare' END);
 RETURN true;EXCEPTION WHEN insufficient_privilege THEN RETURN false;END$$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN RAISE EXCEPTION 'ediel_business_incident_immutable';END $$;

--
-- Name: inspect_ack_v1(uuid, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.inspect_ack_v1(c uuid, env text, source_id uuid, actor uuid, family text, ack_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 IF gridex_ediel_business_incidents.actor_v2(c,actor,'read') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_ack_replay_actor_not_authorized' USING ERRCODE='42501';END IF;
 RETURN gridex_ediel_duplicate_responses.read_business_original_v1(c,env,source_id,actor,family,ack_id,'read');END$$;

--
-- Name: original_read_v2(uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.original_read_v2(c uuid, actor uuid, input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;owned jsonb;receipt jsonb;scopes jsonb;scope jsonb;tokens jsonb;refs text[];context jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF c IS NULL OR actor IS NULL OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(input) k WHERE k NOT IN('commandId','sourceMessageId','ackMessageId','scopeReference','finding'))
 OR NOT(input ?& ARRAY['commandId','sourceMessageId','ackMessageId','scopeReference','finding']) OR jsonb_typeof(input->'finding') IS DISTINCT FROM 'object'
 OR EXISTS(SELECT FROM jsonb_object_keys(input->'finding') k WHERE k NOT IN('code','summary')) OR input#>>'{finding,code}' IS DISTINCT FROM 'late_internal_business_error'
 OR jsonb_typeof(input#>'{finding,summary}') IS DISTINCT FROM 'string' OR length(btrim(input#>>'{finding,summary}')) NOT BETWEEN 1 AND 2000
 OR jsonb_typeof(input->'scopeReference') IS DISTINCT FROM 'string' OR length(btrim(input->>'scopeReference')) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'ediel_business_incident_input_invalid';END IF;
 PERFORM (input->>'commandId')::uuid;
 IF gridex_ediel_business_incidents.actor_v2(c,actor,'read') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_business_incident_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE company_id=c AND id=(input->>'sourceMessageId')::uuid AND direction='inbound' AND message_family IN('PRODAT','UTILTS') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_business_incident_own_source_required';END IF;
 owned:=gridex_ediel_business_incidents.inspect_ack_v1(c,source.environment,source.id,actor,'APERAK',(input->>'ackMessageId')::uuid);
 IF owned IS NULL OR owned#>>'{sourceMessage,id}' IS DISTINCT FROM source.id::text THEN RAISE EXCEPTION 'ediel_business_incident_own_ack_required';END IF;
 ack:=jsonb_populate_record(NULL::public.ediel_messages,owned->'ackMessage');
 context:=gridex_ediel_ack_replay.require_current_source_role_v2(c,source.environment,source.id);
 receipt:=gridex_ediel_transport.accepted_source_basis_v1(ack);
 IF receipt IS NULL OR receipt->>'status' IS DISTINCT FROM 'accepted_projection' OR receipt->>'messageId' IS DISTINCT FROM ack.id::text THEN RAISE EXCEPTION 'ediel_business_incident_actual_accepted_ack_required';END IF;
 IF source.message_family='PRODAT' THEN
  scopes:=gridex_ediel_ack_guide.prodat_outcomes_v1(ack.raw_payload,source.raw_payload);
  SELECT x INTO scope FROM jsonb_array_elements(scopes)x WHERE x->>'reference'=input->>'scopeReference' AND x->>'outcome'='positive';
  IF scope IS NULL OR (SELECT count(*) FROM jsonb_array_elements(scopes)x WHERE x->>'reference'=input->>'scopeReference' AND x->>'outcome'='positive')<>1 THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
 ELSE
  tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  IF (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM' AND x#>>'{elements,1,0}'='312')<>1 OR ack.ack_outcome IS DISTINCT FROM 'positive' THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
  SELECT array_agg(x#>>'{elements,1,1}') INTO refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='ACW';
  IF NOT coalesce(input->>'scopeReference'=ANY(refs),false) OR (SELECT count(*) FROM unnest(refs) r WHERE r=input->>'scopeReference')<>1 THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
  scope:=jsonb_build_object('scope','transaction','reference',input->>'scopeReference','outcome','positive');
 END IF;
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,source.environment,source.id,actor,'APERAK',ack.id,'read');
 RETURN jsonb_build_object('companyId',c,'environment',source.environment,'sourceMessageId',source.id,'ackMessageId',ack.id,'sourceHash',encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'),'ackHash',encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex'),'scope',scope,'sourceContext',context,'transportReceipt',receipt);
END $$;

--
-- Name: original_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.original_v1(c uuid, actor uuid, input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;owned jsonb;receipt jsonb;scopes jsonb;scope jsonb;tokens jsonb;refs text[];context jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF c IS NULL OR actor IS NULL OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(input) k WHERE k NOT IN('commandId','sourceMessageId','ackMessageId','scopeReference','finding'))
 OR NOT(input ?& ARRAY['commandId','sourceMessageId','ackMessageId','scopeReference','finding']) OR jsonb_typeof(input->'finding') IS DISTINCT FROM 'object'
 OR EXISTS(SELECT FROM jsonb_object_keys(input->'finding') k WHERE k NOT IN('code','summary')) OR input#>>'{finding,code}' IS DISTINCT FROM 'late_internal_business_error'
 OR jsonb_typeof(input#>'{finding,summary}') IS DISTINCT FROM 'string' OR length(btrim(input#>>'{finding,summary}')) NOT BETWEEN 1 AND 2000
 OR jsonb_typeof(input->'scopeReference') IS DISTINCT FROM 'string' OR length(btrim(input->>'scopeReference')) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'ediel_business_incident_input_invalid';END IF;
 PERFORM (input->>'commandId')::uuid;
 IF gridex_ediel_business_incidents.actor_v2(c,actor,'report') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_business_incident_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE company_id=c AND id=(input->>'sourceMessageId')::uuid AND direction='inbound' AND message_family IN('PRODAT','UTILTS') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_business_incident_own_source_required';END IF;
 owned:=gridex_ediel_duplicate_responses.read_business_original_v1(c,source.environment,source.id,actor,'APERAK',(input->>'ackMessageId')::uuid,'prepare');
 IF owned IS NULL OR owned#>>'{sourceMessage,id}' IS DISTINCT FROM source.id::text THEN RAISE EXCEPTION 'ediel_business_incident_own_ack_required';END IF;
 ack:=jsonb_populate_record(NULL::public.ediel_messages,owned->'ackMessage');
 context:=gridex_ediel_ack_replay.require_current_source_role_v2(c,source.environment,source.id);
 receipt:=gridex_ediel_transport.accepted_source_basis_v1(ack);
 IF receipt IS NULL OR receipt->>'status' IS DISTINCT FROM 'accepted_projection' OR receipt->>'messageId' IS DISTINCT FROM ack.id::text THEN RAISE EXCEPTION 'ediel_business_incident_actual_accepted_ack_required';END IF;
 IF source.message_family='PRODAT' THEN
  scopes:=gridex_ediel_ack_guide.prodat_outcomes_v1(ack.raw_payload,source.raw_payload);
  SELECT x INTO scope FROM jsonb_array_elements(scopes)x WHERE x->>'reference'=input->>'scopeReference' AND x->>'outcome'='positive';
  IF scope IS NULL OR (SELECT count(*) FROM jsonb_array_elements(scopes)x WHERE x->>'reference'=input->>'scopeReference' AND x->>'outcome'='positive')<>1 THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
 ELSE
  tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  IF (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM' AND x#>>'{elements,1,0}'='312')<>1 OR ack.ack_outcome IS DISTINCT FROM 'positive' THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
  SELECT array_agg(x#>>'{elements,1,1}') INTO refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='ACW';
  IF NOT coalesce(input->>'scopeReference'=ANY(refs),false) OR (SELECT count(*) FROM unnest(refs) r WHERE r=input->>'scopeReference')<>1 THEN RAISE EXCEPTION 'ediel_business_incident_actual_positive_scope_required';END IF;
  scope:=jsonb_build_object('scope','transaction','reference',input->>'scopeReference','outcome','positive');
 END IF;
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,source.environment,source.id,actor,'APERAK',ack.id,'prepare');
 RETURN jsonb_build_object('companyId',c,'environment',source.environment,'sourceMessageId',source.id,'ackMessageId',ack.id,'sourceHash',encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'),'ackHash',encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex'),'scope',scope,'sourceContext',context,'transportReceipt',receipt);
END $$;

--
-- Name: incidents; Type: TABLE; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE TABLE gridex_ediel_business_incidents.incidents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    command_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    ack_message_id uuid NOT NULL,
    source_hash text NOT NULL,
    ack_hash text NOT NULL,
    scope jsonb NOT NULL,
    source_context jsonb NOT NULL,
    transport_receipt jsonb NOT NULL,
    input jsonb NOT NULL,
    reported_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    status text DEFAULT 'reported'::text NOT NULL,
    CONSTRAINT incidents_ack_hash_check CHECK ((ack_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT incidents_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT incidents_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT incidents_status_check CHECK ((status = 'reported'::text))
);

ALTER TABLE ONLY gridex_ediel_business_incidents.incidents FORCE ROW LEVEL SECURITY;

--
-- Name: result_v1(gridex_ediel_business_incidents.incidents); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.result_v1(i gridex_ediel_business_incidents.incidents) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('incidentId',i.id,'commandId',i.command_id,'companyId',i.company_id,'environment',i.environment,'sourceMessageId',i.source_message_id,'ackMessageId',i.ack_message_id,'scope',i.scope,'reportedAt',i.reported_at,'finding',i.input->'finding','status','reported','findingValidated',false,'ackHistoryChanged',false,'contactStatus','held','correctionStatus','held','trafficAuthorized',false)
$$;

--
-- Name: assert_ack_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.assert_ack_v1(m public.ediel_messages, e jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;wire jsonb;source public.ediel_messages%rowtype;u jsonb;g jsonb;ftx jsonb;unb jsonb;unh jsonb;bgm jsonb;
BEGIN
 IF e->>'assignedNegativeBirthReceiptId' IS NOT NULL THEN PERFORM gridex_ediel_header_negative_birth.assert_ack_v1(m,e);RETURN;END IF;
 IF m.company_id::text IS DISTINCT FROM e->>'companyId' OR m.environment IS DISTINCT FROM e->>'environment' OR m.related_message_id::text IS DISTINCT FROM e->>'sourceMessageId' OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' OR m.message_code IS DISTINCT FROM 'APERAK'
  OR m.canonical_rule_pack_id IS NOT NULL OR m.rule_profile_version_id IS NOT NULL OR m.rule_profile_key IS NOT NULL OR m.rule_profile_version IS NOT NULL OR m.rule_pack_checksum IS NOT NULL OR coalesce(m.rule_pack_snapshot,'{}')<>'{}' THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);wire:=gridex_ack_authority.wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'family'<>'APERAK' OR wire->>'function' IS DISTINCT FROM '27' OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='ERC')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='FTX')<>1 THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 SELECT t->'elements' INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';SELECT t->'elements' INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';SELECT t->'elements' INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 SELECT t->'elements' INTO g FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='ERC';SELECT t->'elements' INTO ftx FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='FTX';
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=m.related_message_id FOR SHARE;u:=gridex_ediel_technical_ack.envelope(source.raw_payload);
 IF unh->2 IS DISTINCT FROM e#>'{familyEdition,sourceProjection,catalog,ackConstraints,technicalProfile}' OR unb->2 IS DISTINCT FROM u->'receiver' OR unb->3 IS DISTINCT FROM u->'sender' OR coalesce(unb#>>'{7,0}','') IS DISTINCT FROM u->>'applicationReference' OR coalesce(unb#>>'{11,0}','') IS DISTINCT FROM u->>'testIndicator'
  OR g->1 IS DISTINCT FROM jsonb_build_array(e#>>'{field202,ercCode}','','260') OR ftx->1 IS DISTINCT FROM '["AAO"]'::jsonb OR ftx->3 IS DISTINCT FROM '["202","","260"]'::jsonb OR ftx->4 IS DISTINCT FROM jsonb_build_array(e#>>'{field202,text}') OR length(ftx#>>'{4,0}')>(e#>>'{familyEdition,sourceProjection,catalog,ackConstraints,textMax}')::integer
  OR wire->>'legalSender' IS DISTINCT FROM e#>>'{identities,legalReceiver,id}' OR wire->>'legalReceiver' IS DISTINCT FROM e#>>'{identities,legalSender,id}' THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 -- Full legal qualifiers/country and known original document reference stay
 -- tied to the actual physical own header, not merely matching public IDs.
 IF EXISTS(SELECT FROM unnest(ARRAY['FR','DO'])role WHERE (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'=role)<>1) THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='FR' AND t#>'{elements,2}'=e#>'{identities,legalReceiver,identityComponents}' AND t#>>'{elements,9,0}'=e#>>'{identities,legalReceiver,country}')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='DO' AND t#>'{elements,2}'=e#>'{identities,legalSender,identityComponents}' AND t#>>'{elements,9,0}'=e#>>'{identities,legalSender,country}') THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 IF jsonb_array_length(ftx)>5 OR coalesce(ftx->2,'[]') NOT IN('[]'::jsonb,'[""]'::jsonb) OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'=e#>>'{familyEdition,sourceProjection,catalog,commonAckConstraints,documentDate,qualifier}' AND t#>>'{elements,1,2}'=e#>>'{familyEdition,sourceProjection,catalog,commonAckConstraints,documentDate,format}' AND t#>>'{elements,1,1}'~'^[0-9]{12}$')<>1
  OR EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('IDE','LIN','UCI','UCM'))
  OR EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}' NOT IN('ACW')) THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
 IF NOT coalesce(gridex_ack_authority.source_match_v1(wire,gridex_ack_authority.wire_v1(source.raw_payload)),false) THEN RAISE EXCEPTION 'ediel_common_header_negative_scope_invalid';END IF;
END$_$;

--
-- Name: capture_source(); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.capture_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE observed timestamptz:=clock_timestamp();tokens jsonb;header jsonb;bgm jsonb;parts jsonb;u jsonb;fr jsonb;recipient jsonb;edition jsonb;guide jsonb;pack public.ediel_rule_packs%rowtype;sources jsonb;
 cs uuid[];actors uuid[];c uuid;namespace jsonb;state text:='ready';reason text;defect text;description text;first_detail integer;date date;editions jsonb;
BEGIN
 IF TG_OP='INSERT' AND gridex_ediel_header_negative_birth.is_bound_v1(NEW,true) IS TRUE THEN
  INSERT INTO gridex_ediel_common_header.sources SELECT NEW.id,NEW.company_id,NEW.company_id,NEW.environment,r.payload_sha256,r.source_received_at,r.observed_at,'ready',NULL,r.evidence FROM gridex_ediel_header_negative_birth.receipts r WHERE r.source_message_id=NEW.id AND r.creation_txid=txid_current() AND r.status='pending';
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND nullif(OLD.raw_payload,'') IS NOT NULL THEN RETURN NEW;END IF;
 IF NEW.direction IS DISTINCT FROM 'inbound' OR nullif(NEW.raw_payload,'') IS NULL OR EXISTS(SELECT FROM gridex_ediel_common_header.sources WHERE source_message_id=NEW.id) THEN RETURN NEW;END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(NEW.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 THEN RETURN NEW;END IF;
 SELECT t INTO header FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';IF header#>>'{elements,2,0}' IS DISTINCT FROM 'PRODAT' THEN RETURN NEW;END IF;
 SELECT min((t->>'index')::integer) INTO first_detail FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('LIN','UNT','UNZ');
 SELECT t INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' AND (t->>'index')::integer<first_detail;
 IF bgm IS NULL THEN RETURN NEW;END IF;parts:=bgm#>'{elements,1}';
 -- The source-generated original family list owns field202; no arbitrary
 -- selected code, subtype or market role can be manufactured for an unknown.
 SELECT coalesce(jsonb_agg(e.evidence),'[]') INTO editions FROM gridex_ediel_common_header.source_editions e WHERE EXISTS(SELECT FROM jsonb_array_elements(e.evidence#>'{catalog,guides}')g WHERE (g->>'effectiveFrom')::date<=(NEW.message_received_at AT TIME ZONE 'Europe/Stockholm')::date AND(g->>'effectiveTo' IS NULL OR(NEW.message_received_at AT TIME ZONE 'Europe/Stockholm')::date<=(g->>'effectiveTo')::date));
 edition:=editions->0;IF jsonb_array_length(editions)=1 AND edition#>'{catalog,allowedCodes}' ? coalesce(parts->>0,'') THEN RETURN NEW;END IF;
 BEGIN
  IF jsonb_array_length(editions)<>1 THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
  IF NEW.environment NOT IN('test','production') OR NEW.message_received_at IS NULL OR octet_length(NEW.raw_payload)>262144 THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
  date:=(NEW.message_received_at AT TIME ZONE 'Europe/Stockholm')::date;
  SELECT g INTO STRICT guide FROM jsonb_array_elements(edition#>'{catalog,guides}')g WHERE (g->>'effectiveFrom')::date<=date AND (g->>'effectiveTo' IS NULL OR date<=(g->>'effectiveTo')::date);
  IF header#>'{elements,2}' IS DISTINCT FROM edition#>'{catalog,technicalType}' THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
  u:=gridex_ediel_technical_ack.envelope(NEW.raw_payload);
  IF u IS NULL OR u->>'environment' IS DISTINCT FROM NEW.environment OR NOT(edition#>'{catalog,applicationReferences}' ? (u->>'applicationReference')) THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
  SELECT t INTO STRICT fr FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='FR' AND (t->>'index')::integer<first_detail;
  SELECT t INTO STRICT recipient FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='DO' AND (t->>'index')::integer<first_detail;
  IF jsonb_array_length(fr#>'{elements,2}')<>3 OR jsonb_array_length(recipient#>'{elements,2}')<>3 OR nullif(fr#>>'{elements,2,0}','') IS NULL OR nullif(recipient#>>'{elements,2,0}','') IS NULL
   OR fr#>>'{elements,2,1}' IS DISTINCT FROM '160' OR fr#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' OR recipient#>>'{elements,2,1}' IS DISTINCT FROM '160' OR recipient#>>'{elements,2,2}' IS DISTINCT FROM 'SVK'
   OR coalesce(fr#>>'{elements,9,0}','')!~'^[A-Z]{2}$' OR coalesce(recipient#>>'{elements,9,0}','')!~'^[A-Z]{2}$' THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
  -- Namespace ownership is a legal identity fact only, never an inferred role,
  -- grant or entitlement to process the unknown business message.
  LOCK TABLE public.tenant_actor_identifiers IN SHARE MODE;
  SELECT array_agg(DISTINCT i.company_id),array_agg(DISTINCT i.actor_id) INTO cs,actors FROM public.tenant_actor_identifiers i WHERE i.environment=NEW.environment AND i.identifier_type='EdielId' AND i.identifier_value=recipient#>>'{elements,2,0}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
  IF cardinality(cs) IS DISTINCT FROM 1 OR cardinality(actors) IS DISTINCT FROM 1 OR (NEW.company_id IS NOT NULL AND NEW.company_id IS DISTINCT FROM cs[1]) THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;c:=cs[1];
  SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) INTO namespace FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.actor_id=actors[1] AND i.environment=NEW.environment AND i.identifier_type='EdielId' AND i.identifier_value=recipient#>>'{elements,2,0}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
  LOCK TABLE public.ediel_rule_packs,public.ediel_rule_pack_sources IN SHARE MODE;
  SELECT * INTO STRICT pack FROM public.ediel_rule_packs r WHERE r.family='PRODAT' AND r.market='electricity' AND r.status IN('active','transition','future') AND r.guide_version||':r'||r.guide_revision=edition#>>'{catalog,registeredVersion}' AND r.unh_association_code=guide->>'associationAssignedCode' AND r.valid_from<=date AND(r.valid_to IS NULL OR date<=r.valid_to);
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id;
  defect:=CASE WHEN EXISTS(SELECT FROM jsonb_array_elements_text(parts)p WHERE nullif(p,'') IS NOT NULL) THEN 'invalid' ELSE 'missing' END;
  description:=CASE defect WHEN 'missing' THEN (edition#>>'{catalog,label}')||' saknas' ELSE 'Felaktigt '||(edition#>>'{catalog,label}')||' '||(SELECT string_agg(p,':' ORDER BY i) FROM jsonb_array_elements_text(parts)WITH ORDINALITY x(p,i)) END;
 EXCEPTION WHEN OTHERS THEN state:='held';reason:='ediel_common_header_rejection_basis_required';END;
 INSERT INTO gridex_ediel_common_header.sources VALUES(NEW.id,NEW.company_id,c,NEW.environment,encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'),NEW.message_received_at,observed,state,reason,
  jsonb_build_object('kind','prodat_common_header_rejection','version',1,'companyId',c,'environment',NEW.environment,'sourceMessageId',NEW.id,'sourceHash',encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'),'sourceReceivedAt',NEW.message_received_at,'observedAt',observed,
   'field202',jsonb_build_object('fieldCode','202','ercCode',CASE defect WHEN 'missing' THEN '41' ELSE '42' END,'text',description),'guide',guide,'familyEdition',jsonb_build_object('version',edition#>>'{catalog,registeredVersion}','rulePack',to_jsonb(pack),'guideSources',sources,'sourceProjection',edition),
   'identities',jsonb_build_object('family','PRODAT','transport',jsonb_build_object('interchangeReference',u->>'interchangeReference','uciReference',u->>'uciReference','senderComponents',u->'sender','receiverComponents',u->'receiver'),
    'legalSender',jsonb_build_object('id',fr#>>'{elements,2,0}','identityComponents',fr#>'{elements,2}','country',fr#>>'{elements,9,0}'),'legalReceiver',jsonb_build_object('id',recipient#>>'{elements,2,0}','identityComponents',recipient#>'{elements,2}','country',recipient#>>'{elements,9,0}'),'applicationReference',u->>'applicationReference'),
   'legalNamespace',namespace,'authorizesBusinessEffect',false));RETURN NEW;
END$_$;

--
-- Name: consume_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.consume_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;p gridex_ediel_common_header.negative_consumptions%rowtype;BEGIN
 w:=gridex_ediel_common_header.witness_v1(m);SELECT * INTO p FROM gridex_ediel_common_header.negative_consumptions WHERE witness_id=w.id FOR UPDATE;
 IF FOUND THEN IF p.ack_message_id IS DISTINCT FROM m.id THEN RAISE EXCEPTION 'ediel_common_header_negative_witness_already_consumed';END IF;RETURN;END IF;
 INSERT INTO gridex_ediel_common_header.negative_consumptions VALUES(w.id,m.id,m.company_id,m.environment,w.payload_sha256);END$$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN RAISE EXCEPTION 'ediel_common_header_basis_immutable';END$$;

--
-- Name: prepare_v1(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.prepare_v1(c uuid, env text, msg uuid, actor uuid, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb;m public.ediel_messages%rowtype;token uuid;
BEGIN
 IF NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL) OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden';END IF;
 e:=gridex_ediel_common_header.require_v1(c,env,msg);PERFORM gridex_ediel_common_header.require_current_scope_v1(e);m.company_id:=c;m.environment:=env;m.related_message_id:=msg;m.direction:='outbound';m.message_family:='APERAK';m.message_code:='APERAK';m.raw_payload:=raw;
 PERFORM gridex_ediel_common_header.assert_ack_v1(m,e);
 PERFORM gridex_ediel_ack_guide.bind_source_v1(source,'common',e) FROM public.ediel_messages source WHERE source.id=msg;
 INSERT INTO gridex_ediel_common_header.negative_witnesses(company_id,environment,source_message_id,actor_user_id,payload_sha256,evidence) VALUES(c,env,msg,actor,encode(sha256(convert_to(raw,'UTF8')),'hex'),e)RETURNING id INTO token;
 RETURN jsonb_build_object('witnessId',token,'evidence',e);
END$$;

--
-- Name: prepare_with_route_v2(uuid, text, uuid, uuid, text, text, text, integer); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.prepare_with_route_v2(c uuid, env text, msg uuid, actor uuid, raw text, smtp_from text, smtp_host text, smtp_port integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE e jsonb;r jsonb;m public.ediel_messages%rowtype;token uuid;BEGIN
 e:=gridex_ediel_common_header.require_v1(c,env,msg);r:=gridex_ediel_common_header.read_negative_route_v1(c,actor,msg,smtp_from,smtp_host,smtp_port);
 m.company_id:=c;m.environment:=env;m.related_message_id:=msg;m.direction:='outbound';m.message_family:='APERAK';m.message_code:='APERAK';m.raw_payload:=raw;
 PERFORM gridex_ediel_common_header.assert_ack_v1(m,e);PERFORM gridex_ediel_ack_guide.bind_source_v1(source,'common',e) FROM public.ediel_messages source WHERE source.id=msg;
 INSERT INTO gridex_ediel_common_header.negative_witnesses(company_id,environment,source_message_id,actor_user_id,payload_sha256,evidence) VALUES(c,env,msg,actor,encode(sha256(convert_to(raw,'UTF8')),'hex'),e) RETURNING id INTO token;
 INSERT INTO gridex_ediel_common_header.negative_route_bindings VALUES(token,r);
 RETURN jsonb_build_object('witnessId',token,'evidence',e);END $$;

--
-- Name: read_ack_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.read_ack_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;e jsonb;result jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment AND direction='outbound' FOR SHARE;
 e:=gridex_ediel_common_header.require_ack_v1(m);result:=gridex_ediel_common_header.read_v1(p_company_id,p_environment,m.related_message_id);RETURN result||jsonb_build_object('ackMessage',to_jsonb(m));END$$;

--
-- Name: read_negative_route_v1(uuid, uuid, uuid, text, text, integer); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.read_negative_route_v1(c uuid, actor uuid, msg uuid, current_smtp_from text, current_smtp_host text, current_smtp_port integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE e jsonb;t jsonb;BEGIN
 t:=gridex_ediel_technical_ack.require_source_v1(c,msg);e:=gridex_ediel_common_header.require_v1(c,t->>'environment',msg);
 IF e->>'environment'='test' THEN PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(actor,c);ELSE PERFORM gridex_negative_fixtures.assert_actor_v1(actor,c,'communication.write');END IF;
 PERFORM gridex_ediel_common_header.require_current_scope_v1(e);
 IF t->>'sourceHash' IS DISTINCT FROM e->>'sourceHash' OR t->>'syntaxAssessmentId' IS DISTINCT FROM e->>'syntaxAssessmentId' THEN RAISE EXCEPTION 'ediel_common_header_route_basis_mismatch';END IF;
 RETURN gridex_ediel_technical_ack.select_configured_reply_route_v2(c,t,'APERAK',current_smtp_from,current_smtp_host,current_smtp_port);END $$;

--
-- Name: read_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.read_v1(c uuid, env text, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE e jsonb;m public.ediel_messages%rowtype;BEGIN
 e:=gridex_ediel_common_header.require_v1(c,env,msg);SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=msg FOR SHARE;RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(m),'evidence',e);END$$;

--
-- Name: require_ack_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.require_ack_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;BEGIN
 w:=gridex_ediel_common_header.witness_v1(m);PERFORM gridex_ediel_common_header.require_current_scope_v1(w.evidence);
 IF NOT EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions p WHERE p.witness_id=w.id AND p.ack_message_id=m.id AND p.company_id=m.company_id AND p.environment=m.environment AND p.payload_sha256=w.payload_sha256) THEN RAISE EXCEPTION 'ediel_common_header_negative_witness_required';END IF;RETURN w.evidence;END$$;

--
-- Name: require_current_scope_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.require_current_scope_v1(e jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE companies uuid[];actors uuid[];technical jsonb;observed timestamptz:=clock_timestamp();BEGIN
 SELECT array_agg(DISTINCT i.company_id),array_agg(DISTINCT i.actor_id) INTO companies,actors FROM public.tenant_actor_identifiers i WHERE i.environment=e->>'environment' AND i.identifier_type='EdielId' AND i.identifier_value=e#>>'{identities,legalReceiver,id}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
 IF cardinality(companies) IS DISTINCT FROM 1 OR cardinality(actors) IS DISTINCT FROM 1 OR companies[1]::text IS DISTINCT FROM e->>'companyId' OR NOT EXISTS(SELECT FROM jsonb_array_elements(e->'legalNamespace')n WHERE n->>'actor_id'=actors[1]::text) THEN RAISE EXCEPTION 'ediel_common_header_current_identity_unavailable';END IF;
 SELECT evidence INTO technical FROM gridex_ediel_technical_ack.sources WHERE source_message_id=(e->>'sourceMessageId')::uuid;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(technical);
 IF e->>'assignedNegativeBirthReceiptId' IS NOT NULL THEN PERFORM gridex_ediel_header_negative_birth.reply_application_v1(m,e) FROM public.ediel_messages m WHERE m.id=(e->>'sourceMessageId')::uuid;END IF;END$$;

--
-- Name: require_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.require_v1(c uuid, env text, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;b gridex_ediel_common_header.sources%rowtype;f gridex_ediel_technical_ack.syntax_facets%rowtype;t gridex_ediel_technical_ack.sources%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=msg AND direction='inbound' FOR SHARE;SELECT * INTO b FROM gridex_ediel_common_header.sources WHERE source_message_id=msg;
 IF b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_common_header_basis_unavailable';END IF;
 IF m.id IS NULL OR b.status<>'ready' OR b.company_id IS DISTINCT FROM c OR b.environment IS DISTINCT FROM env OR m.environment IS DISTINCT FROM env OR m.company_id IS DISTINCT FROM b.source_company_id
  OR b.source_received_at IS DISTINCT FROM m.message_received_at OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
 SELECT * INTO f FROM gridex_ediel_technical_ack.syntax_facets a WHERE a.source_message_id=msg AND a.company_id=c AND a.environment=env AND a.payload_sha256=b.payload_sha256 AND a.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 SELECT * INTO t FROM gridex_ediel_technical_ack.sources WHERE source_message_id=msg;
 IF f.id IS NULL OR f.facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.facts_text,'UTF8')),'hex') OR f.facts_text::jsonb->>'owner' IS DISTINCT FROM 'canonical-runtime-syntax-v1' OR f.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted'
  OR t.status IS DISTINCT FROM 'ready' OR t.company_id IS DISTINCT FROM c OR t.environment IS DISTINCT FROM env OR t.payload_sha256 IS DISTINCT FROM b.payload_sha256 THEN RAISE EXCEPTION 'ediel_common_header_rejection_basis_required';END IF;
 RETURN b.evidence||jsonb_build_object('syntaxAssessmentId',f.id);
END$$;

--
-- Name: negative_witnesses; Type: TABLE; Schema: gridex_ediel_common_header; Owner: -
--

CREATE TABLE gridex_ediel_common_header.negative_witnesses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    source_message_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    payload_sha256 text NOT NULL,
    evidence jsonb NOT NULL
);

ALTER TABLE ONLY gridex_ediel_common_header.negative_witnesses FORCE ROW LEVEL SECURITY;

--
-- Name: witness_before_route_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.witness_before_route_v1(m public.ediel_messages) RETURNS gridex_ediel_common_header.negative_witnesses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;BEGIN
 SELECT * INTO w FROM gridex_ediel_common_header.negative_witnesses WHERE id=(m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId')::uuid FOR SHARE;
 IF w.id IS NULL OR w.company_id IS DISTINCT FROM m.company_id OR w.environment IS DISTINCT FROM m.environment OR w.source_message_id IS DISTINCT FROM m.related_message_id OR w.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_common_header_negative_witness_required';END IF;
 PERFORM gridex_ediel_common_header.assert_ack_v1(m,w.evidence);RETURN w;END$$;

--
-- Name: witness_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_common_header; Owner: -
--

CREATE FUNCTION gridex_ediel_common_header.witness_v1(m public.ediel_messages) RETURNS gridex_ediel_common_header.negative_witnesses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;r jsonb;current_route jsonb;t jsonb;BEGIN
 w:=gridex_ediel_common_header.witness_before_route_v1(m);
 SELECT route INTO r FROM gridex_ediel_common_header.negative_route_bindings WHERE witness_id=w.id;
 IF r IS NULL OR m.communication_route_id::text IS DISTINCT FROM r#>>'{route,id}' OR m.route_profile_id::text IS DISTINCT FROM r#>>'{routeRuntime,route_profile_id}'
  OR m.sender_email IS DISTINCT FROM r->>'senderEmail' OR m.receiver_email IS DISTINCT FROM r->>'receiverEmail' OR m.mailbox IS DISTINCT FROM r->>'mailbox'
  OR m.sender_ediel_id IS DISTINCT FROM r->>'senderEdielId' OR m.receiver_ediel_id IS DISTINCT FROM r->>'receiverEdielId'
  OR coalesce(m.sender_sub_address,'') IS DISTINCT FROM coalesce(r->>'senderSubAddress','') OR coalesce(m.receiver_sub_address,'') IS DISTINCT FROM coalesce(r->>'receiverSubAddress','')
  OR m.application_reference IS DISTINCT FROM r->>'applicationReference' THEN RAISE EXCEPTION 'ediel_common_header_negative_route_binding_required';END IF;
 t:=gridex_ediel_technical_ack.require_source_v1(w.company_id,w.source_message_id);PERFORM gridex_ediel_common_header.require_current_scope_v1(w.evidence);
 current_route:=gridex_ediel_technical_ack.select_configured_reply_route_v2(w.company_id,t,'APERAK',r->>'senderEmail',r->>'smtpHost',(r->>'smtpPort')::integer);
 IF current_route IS DISTINCT FROM r THEN RAISE EXCEPTION 'ediel_common_header_negative_current_route_required';END IF;
 RETURN w;END $$;

--
-- Name: allows_message_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.allows_message_v1(m public.ediel_messages) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT m.direction='outbound' AND m.message_family='APERAK' AND EXISTS(SELECT FROM gridex_ediel_duplicate_responses.intents i WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.source_message_id=m.related_message_id AND i.ack_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  AND((i.owner_xid=pg_current_xact_id() AND(m.id IS NULL OR m.id=i.ack_message_id)) OR EXISTS(SELECT FROM gridex_ediel_duplicate_responses.consumptions c JOIN gridex_ediel_outbound_owner.consumptions w ON w.source_message_id=c.acknowledgement_id AND w.company_id=i.company_id AND w.environment=i.environment AND w.payload_sha256=i.ack_hash WHERE c.intent_id=i.id AND c.acknowledgement_id=m.id AND m.id=i.ack_message_id)))
$$;

--
-- Name: create_v1(uuid, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.create_v1(c uuid, source_id uuid, mail_id uuid, actor uuid, draft jsonb, smtp jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE existing jsonb;s public.ediel_messages%rowtype;m public.ediel_messages%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;
 env text;source_hash text;family text:='APERAK';sequence_field text;sequence_value text;outcome text:='negative';
 source jsonb;i gridex_ediel_duplicate_responses.intents%rowtype;outbox_id uuid;ctx jsonb;basis jsonb;prepared jsonb;route jsonb;tokens jsonb;unb jsonb;unh jsonb;bgm jsonb;parsed jsonb;raw text;physical_family text;wire_outcome text;common boolean;
 op text;event_id uuid;business_type text;business_id uuid;resource record;resource_json jsonb;reference record;result jsonb;
BEGIN
 -- Shared permission/bilateral prefix precedes the write-compatible native
 -- candidate universe; no SHARE-to-INSERT upgrade or caller hash capability.
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE gridex_ediel_duplicate_responses.intents IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 source:=gridex_ediel_duplicate_responses.source_v1(c,source_id,mail_id,actor);
 s:=jsonb_populate_record(NULL::public.ediel_messages,source->'sourceMessage');env:=s.environment;source_hash:=source->>'sourceHash';basis:=source->'sourceRulePackEvidence';
 SELECT * INTO i FROM gridex_ediel_duplicate_responses.intents WHERE reception_id=(source->>'receptionId')::uuid;
 existing:=gridex_ediel_duplicate_responses.read_result_v1(i);IF existing IS NOT NULL THEN
  PERFORM gridex_ediel_duplicate_responses.source_v1(c,source_id,mail_id,actor);
  RETURN existing||jsonb_build_object('replayed',true);END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(c,s.id);
 -- Fresh-only caller whitelist. An established own response above never uses
 -- a new draft, mints a witness, writes a receipt/event or selects a route.
 IF jsonb_typeof(draft) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(draft) k WHERE k<>ALL(ARRAY[
  'rawPayload','messageVersion','processType','transportType','mailbox','senderEdielId','senderName','senderSubAddress','receiverEdielId','receiverName','receiverSubAddress',
  'senderEmail','receiverEmail','subject','fileName','mimeType','interchangeReference','externalReference','correlationReference','transactionReference','applicationReference',
  'originalMessageId','originalTransactionId','originalMessageCode','communicationRouteId','routeProfileId','parsedPayload','validationReport',
  'requiresContrl','requiresAperak','syntaxCheckStatus','functionalCheckStatus','messageCreatedAt','validatedAt','ackDueAt'])) THEN RAISE EXCEPTION 'ediel_ack_atomic_draft_whitelist_required';END IF;
 raw:=draft->>'rawPayload';IF nullif(raw,'') IS NULL OR octet_length(raw)>8388608 THEN RAISE EXCEPTION 'ediel_ack_atomic_wire_required';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 THEN RAISE EXCEPTION 'ediel_ack_atomic_wire_required';END IF;
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';SELECT t INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 physical_family:=CASE WHEN unh#>>'{elements,2,0}'='UTILTS' AND bgm#>>'{elements,1,0}'='ERR' THEN 'UTILTS_ERR' ELSE unh#>>'{elements,2,0}' END;
 IF physical_family IS DISTINCT FROM family THEN RAISE EXCEPTION 'ediel_ack_atomic_wire_family_mismatch';END IF;
 IF jsonb_typeof(smtp) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_duplicate_actual_smtp_required';END IF;
 route:=gridex_ediel_technical_ack.select_configured_reply_route_v2(c,source->'technicalBasis','APERAK',smtp->>'from',smtp->>'host',(smtp->>'port')::int);
 IF tokens#>>'{4,elements,1,1}' IS DISTINCT FROM source->>'sourceReceivedDate203' OR tokens#>>'{4,elements,1,2}' IS DISTINCT FROM '203' THEN RAISE EXCEPTION 'ediel_duplicate_actual_received_clock_required';END IF;
 SELECT b.source_version INTO STRICT i.guide_source_version FROM gridex_ediel_ack_guide.source_bindings b WHERE b.source_message_id=s.id AND b.kind='national' AND b.company_id=c AND b.environment=env;
 PERFORM gridex_ediel_duplicate_responses.require_wire_v1(raw,s.raw_payload,(SELECT e.projection FROM gridex_ediel_ack_guide.editions e WHERE e.source_version=i.guide_source_version));
 i.id:=gen_random_uuid();i.reception_id:=(source->>'receptionId')::uuid;i.response_request_id:=(source->>'responseRequestId')::uuid;i.company_id:=c;i.source_message_id:=s.id;i.environment:=env;i.source_hash:=source_hash;i.actor_user_id:=actor;
 i.ack_message_id:=gen_random_uuid();i.ack_hash:=encode(sha256(convert_to(raw,'UTF8')),'hex');i.source_role_hash:=encode(sha256(convert_to((source->'currentContext')::text,'UTF8')),'hex');i.owner_xid:=pg_current_xact_id();i.created_at:=clock_timestamp();
 INSERT INTO gridex_ediel_duplicate_responses.intents SELECT i.*;
 prepared:=gridex_ediel_outbound_owner.prepare_v1(jsonb_build_object('companyId',c,'environment',env,'actorUserId',actor,'rawPayload',raw,'relatedMessageId',s.id,'rulePackEvidence',basis));
 SELECT * INTO STRICT w FROM gridex_ediel_outbound_owner.witnesses WHERE id=(prepared->>'witnessId')::uuid;
 IF w.family IS DISTINCT FROM 'APERAK' OR w.related_message_id IS DISTINCT FROM s.id OR w.company_id IS DISTINCT FROM c OR w.environment IS DISTINCT FROM env OR w.payload_sha256 IS DISTINCT FROM i.ack_hash THEN RAISE EXCEPTION 'ediel_duplicate_owner_scope_mismatch';END IF;
 -- Native parse controls all physical reference/endpoint metadata; no parsed
 -- caller reference or foreign resource ID becomes a business identity.
 parsed:=coalesce(draft->'parsedPayload','{}'::jsonb)-ARRAY['relatedTransactionReference','utiltsErrSequenceToken','ackScope','sourceMessageId','ackSourceId','serviceAssignment','sourceAuthority','rulePackEvidence'];
 IF jsonb_typeof(parsed) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_ack_atomic_metadata_required';END IF;
 IF sequence_field IS NOT NULL THEN parsed:=parsed||jsonb_build_object(sequence_field,sequence_value);END IF;
 IF sequence_field='relatedTransactionReference' THEN parsed:=parsed||jsonb_build_object('ackScope','transaction');END IF;
 parsed:=parsed||jsonb_build_object('ackSourceId',s.id,'ackFamily',family);
 op:='ediel_duplicate103:'||i.reception_id::text;
 m.id:=i.ack_message_id;m.company_id:=c;m.environment:=env;m.direction:='outbound';m.message_standard:='edifact';m.message_family:=family;
 m.message_code:=CASE WHEN w.id IS NOT NULL THEN w.code ELSE family END;m.raw_payload:=raw;m.related_message_id:=s.id;m.status:='draft';m.source_operation_id:=op;
 m.test_flag:=CASE env WHEN 'production' THEN 0 ELSE 1 END;m.message_version:=draft->>'messageVersion';m.process_type:=draft->>'processType';m.transport_type:='smtp';
 m.sender_ediel_id:=unb#>>'{elements,2,0}';m.receiver_ediel_id:=unb#>>'{elements,3,0}';m.sender_sub_address:=nullif(unb#>>'{elements,2,2}','');m.receiver_sub_address:=nullif(unb#>>'{elements,3,2}','');
 m.interchange_reference:=unb#>>'{elements,5,0}';m.application_reference:=unb#>>'{elements,7,0}';m.original_message_id:=unh#>>'{elements,1,0}';m.external_reference:=bgm#>>'{elements,2,0}';
 m.original_transaction_id:=sequence_value;m.original_message_code:=CASE WHEN common THEN NULL ELSE s.message_code END;
 SELECT t#>>'{elements,1,1}' INTO m.correlation_reference FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' ORDER BY (t->>'index')::int LIMIT 1;
 SELECT t#>>'{elements,1,1}' INTO m.transaction_reference FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='TN' ORDER BY (t->>'index')::int LIMIT 1;
 m.sender_name:=draft->>'senderName';m.receiver_name:=draft->>'receiverName';m.subject:=draft->>'subject';m.file_name:=draft->>'fileName';m.mime_type:=draft->>'mimeType';
 m.communication_route_id:=nullif(draft->>'communicationRouteId','')::uuid;m.route_profile_id:=nullif(draft->>'routeProfileId','')::uuid;
 m.sender_email:=draft->>'senderEmail';m.receiver_email:=draft->>'receiverEmail';m.mailbox:=draft->>'mailbox';
 IF route IS NOT NULL THEN
  IF m.communication_route_id::text IS DISTINCT FROM route#>>'{route,id}' OR m.route_profile_id::text IS DISTINCT FROM route#>>'{routeRuntime,route_profile_id}'
   OR m.sender_email IS DISTINCT FROM route->>'senderEmail' OR m.receiver_email IS DISTINCT FROM route->>'receiverEmail' OR m.mailbox IS DISTINCT FROM route->>'mailbox' THEN RAISE EXCEPTION 'ediel_ack_atomic_route_changed';END IF;
 ELSE
  -- Fresh ordinary response selects the exact named route/profile under lock;
  -- replay above never consults these mutable rows.
  LOCK TABLE public.communication_routes,public.ediel_route_profiles,public.ediel_transport_profiles IN SHARE MODE;
  IF NOT EXISTS(SELECT FROM public.communication_routes r JOIN public.ediel_route_profiles p ON p.communication_route_id=r.id AND p.company_id=c
   WHERE r.id=m.communication_route_id AND p.id=m.route_profile_id AND r.company_id=c AND r.is_active AND p.is_enabled AND p.environment=env
    AND p.sender_ediel_id=m.sender_ediel_id AND p.receiver_ediel_id=m.receiver_ediel_id
    AND coalesce(p.sender_subaddress,p.sender_sub_address,'')=coalesce(m.sender_sub_address,'') AND coalesce(p.receiver_subaddress,p.receiver_sub_address,'')=coalesce(m.receiver_sub_address,'')
    AND p.application_reference IS NOT DISTINCT FROM m.application_reference AND r.target_email IS NOT DISTINCT FROM m.receiver_email AND p.mailbox IS NOT DISTINCT FROM m.mailbox) THEN RAISE EXCEPTION 'ediel_ack_atomic_route_changed';END IF;
 END IF;
 IF common THEN m.execution_context_snapshot:=jsonb_build_object('prodatCommonHeaderNegativeWitnessId',prepared->>'witnessId');
 ELSIF w.id IS NOT NULL THEN
  m.execution_context_snapshot:=jsonb_build_object('outboundOwnerWitnessId',w.id);m.canonical_rule_pack_id:=(w.evidence->>'rulePackId')::uuid;m.rule_profile_version_id:=(w.evidence->>'messageProfileId')::uuid;
  m.rule_profile_key:=w.evidence->>'profileKey';m.rule_profile_version:=w.evidence->>'version';m.rule_pack_checksum:=w.evidence->>'sourceHash';m.rule_pack_snapshot:=w.evidence->'snapshot';
  -- Protocol-only negative response inherits no business resource links.
 END IF;
 m.parsed_payload:=parsed;m.validation_report:=coalesce(draft->'validationReport','{}'::jsonb);m.requires_contrl:=false;m.requires_aperak:=false;
 m.contrl_status:='not_required';m.aperak_status:='not_required';m.utilts_err_status:='not_required';m.syntax_check_status:=draft->>'syntaxCheckStatus';m.functional_check_status:=draft->>'functionalCheckStatus';
 m.message_created_at:=coalesce((draft->>'messageCreatedAt')::timestamptz,clock_timestamp());m.validated_at:=(draft->>'validatedAt')::timestamptz;m.ack_due_at:=(draft->>'ackDueAt')::timestamptz;
 m.created_by:=actor;m.updated_by:=actor;
 -- Set physical outcome before immutable namespace/public row insertion.
 IF family='CONTRL' THEN wire_outcome:=CASE basis->>'syntaxDecision' WHEN 'accepted' THEN 'positive' WHEN 'rejected' THEN 'negative' END;
 ELSIF common OR family='UTILTS_ERR' THEN wire_outcome:='negative';
 ELSE wire_outcome:=CASE WHEN EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='ERC') AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='ERC' AND t#>>'{elements,1,0}'<>'100') THEN 'positive' ELSE 'negative' END;END IF;
 IF wire_outcome IS NULL OR outcome IS NOT NULL AND outcome IS DISTINCT FROM wire_outcome THEN RAISE EXCEPTION 'ediel_ack_atomic_wire_outcome_mismatch';END IF;
 m.ack_outcome:=wire_outcome;m.ack_status:=wire_outcome;m.parsed_payload:=m.parsed_payload||jsonb_build_object('ackOutcome',wire_outcome);
 INSERT INTO public.ediel_messages(id,company_id,environment,direction,message_standard,message_family,message_code,message_version,process_type,test_flag,status,transport_type,
  raw_payload,related_message_id,source_operation_id,sender_ediel_id,receiver_ediel_id,sender_sub_address,receiver_sub_address,sender_name,receiver_name,sender_email,receiver_email,mailbox,subject,file_name,mime_type,
  communication_route_id,route_profile_id,interchange_reference,application_reference,original_message_id,original_transaction_id,original_message_code,external_reference,correlation_reference,transaction_reference,
  execution_context_snapshot,canonical_rule_pack_id,rule_profile_version_id,rule_profile_key,rule_profile_version,rule_pack_checksum,rule_pack_snapshot,
  customer_id,site_id,metering_point_id,grid_owner_id,switch_request_id,grid_owner_data_request_id,outbound_request_id,partner_export_id,
  parsed_payload,validation_report,requires_contrl,requires_aperak,contrl_status,aperak_status,utilts_err_status,ack_outcome,ack_status,syntax_check_status,functional_check_status,message_created_at,validated_at,ack_due_at,created_by,updated_by)
 VALUES(m.id,m.company_id,m.environment,m.direction,m.message_standard,m.message_family,m.message_code,m.message_version,m.process_type,m.test_flag,m.status,m.transport_type,
  m.raw_payload,m.related_message_id,m.source_operation_id,m.sender_ediel_id,m.receiver_ediel_id,m.sender_sub_address,m.receiver_sub_address,m.sender_name,m.receiver_name,m.sender_email,m.receiver_email,m.mailbox,m.subject,m.file_name,m.mime_type,
  m.communication_route_id,m.route_profile_id,m.interchange_reference,m.application_reference,m.original_message_id,m.original_transaction_id,m.original_message_code,m.external_reference,m.correlation_reference,m.transaction_reference,
  m.execution_context_snapshot,m.canonical_rule_pack_id,m.rule_profile_version_id,m.rule_profile_key,m.rule_profile_version,m.rule_pack_checksum,m.rule_pack_snapshot,
  m.customer_id,m.site_id,m.metering_point_id,m.grid_owner_id,m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id,
  m.parsed_payload,m.validation_report,m.requires_contrl,m.requires_aperak,m.contrl_status,m.aperak_status,m.utilts_err_status,m.ack_outcome,m.ack_status,m.syntax_check_status,m.functional_check_status,m.message_created_at,m.validated_at,m.ack_due_at,m.created_by,m.updated_by) RETURNING * INTO m;
 -- Native witness/source/guide triggers consumed the exact same-TX intent.
 IF NOT EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions co WHERE co.source_message_id=m.id AND co.witness_id=w.id AND co.company_id=c AND co.environment=env AND co.payload_sha256=i.ack_hash) THEN RAISE EXCEPTION 'ediel_duplicate_native_witness_not_consumed';END IF;
 INSERT INTO public.ediel_outbox(company_id,ediel_message_id,source_message_id,status,priority,lock_key,message_family,message_code,ack_outcome,environment,route_profile_id,payload,created_by,updated_by)
 VALUES(c,m.id,s.id,'prepared',100,c::text||':'||env||':ack:'||m.id::text,'APERAK',m.message_code,'negative',env,m.route_profile_id,'{}',actor,actor) RETURNING id INTO outbox_id;
 INSERT INTO public.ediel_message_events(company_id,ediel_message_id,message_id,event_type,event_status,message,payload,event_payload,created_by)
  VALUES(c,m.id,m.id,'created','info','Ediel message '||family||' '||coalesce(m.message_code,'')||' skapad.',jsonb_build_object('status',m.status,'direction',m.direction,'externalReference',m.external_reference,'communicationRouteId',m.communication_route_id),jsonb_build_object('sourceMessageId',s.id,'sourceOperationId',op,'atomicOwner',true),actor) RETURNING id INTO event_id;
 INSERT INTO gridex_ediel_duplicate_responses.consumptions(intent_id,acknowledgement_id,outbox_id,event_id,actor_user_id) VALUES(i.id,m.id,outbox_id,event_id,actor);
 -- NEW transport receipt only; canonical source and old ACK remain untouched.
 UPDATE public.inbound_email_messages SET processing_status='manual_review',match_status='protocol_response_prepared',error_message=NULL,match_payload=coalesce(match_payload,'{}')||jsonb_build_object('protocolResponse',jsonb_build_object('receptionId',i.reception_id,'responseRequestId',i.response_request_id,'ackMessageId',m.id,'outboxId',outbox_id)),updated_at=clock_timestamp() WHERE id=mail_id AND company_id=c;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_duplicate_new_mail_scope_changed';END IF;
 -- Row/table locks stabilize mutations; clocks can still cross validity bounds
 -- while native witness/namespace/outbox work waits. Recheck at commit end.
 result:=gridex_ediel_duplicate_responses.read_result_v1(i);
 IF gridex_ediel_duplicate_responses.source_v1(c,source_id,mail_id,actor) IS DISTINCT FROM source THEN RAISE EXCEPTION 'ediel_duplicate_current_source_changed';END IF;
 RETURN result||jsonb_build_object('replayed',false);
END $$;

--
-- Name: is_duplicate_ack_v1(uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.is_duplicate_ack_v1(ack_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT EXISTS(SELECT FROM gridex_ediel_duplicate_responses.consumptions c WHERE c.acknowledgement_id=ack_id)$$;

--
-- Name: matches_business_sequence_v1(public.ediel_messages, public.ediel_messages, text, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.matches_business_sequence_v1(source public.ediel_messages, ack public.ediel_messages, sequence_field text, sequence_value text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt gridex_ediel_ack_replay.creation_receipts%rowtype;a jsonb;s jsonb;tokens jsonb;BEGIN
 a:=gridex_ack_authority.wire_v1(ack.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 SELECT * INTO receipt FROM gridex_ediel_ack_replay.creation_receipts WHERE ack_message_id=ack.id FOR SHARE;
 IF receipt.ack_message_id IS NOT NULL AND (receipt.sequence_field IS DISTINCT FROM sequence_field OR receipt.sequence_value IS DISTINCT FROM sequence_value) THEN RETURN false;END IF;
 IF sequence_field='relatedTransactionReference' THEN
  RETURN coalesce(s->'ide','[]') ? sequence_value AND (CASE ack.message_family WHEN 'APERAK' THEN coalesce(a#>'{refs,ACW}','[]') ELSE coalesce(a#>'{refs,TN}','[]') END) ? sequence_value;
 ELSIF sequence_field='utiltsErrSequenceToken' THEN
  tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  RETURN EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='E01' AND t#>>'{elements,2,0}'='41' AND t#>>'{elements,3,0}'=sequence_value);
 ELSIF sequence_field IS NOT NULL OR sequence_value IS NOT NULL THEN RAISE EXCEPTION 'ediel_ack_replay_sequence_mismatch';END IF;
 -- The immutable birth tuple disambiguates a recorded full response. Older
 -- unreceipted UTILTS originals need actual full raw series coverage; never
 -- reinterpret one physical status/transaction as an unscoped response.
 IF receipt.ack_message_id IS NULL AND source.message_family='UTILTS' THEN
  IF ack.message_family='UTILTS_ERR' THEN
   tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
   IF EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='E01' AND t#>>'{elements,2,0}'='41') THEN RAISE EXCEPTION 'ediel_historical_ack_sequence_basis_unavailable';END IF;
  ELSIF ack.message_family='APERAK' THEN
   IF jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))>0 AND EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(s->'ide','[]'))x WHERE NOT coalesce(a#>'{refs,ACW}','[]') ? x) THEN RAISE EXCEPTION 'ediel_historical_ack_sequence_basis_unavailable';END IF;
  END IF;
 END IF;
 RETURN true;
END$$;

--
-- Name: read_business_original_v1(uuid, text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.read_business_original_v1(c uuid, env text, source_id uuid, actor uuid, family text, ack_id uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;ids uuid[];context jsonb;ack_context jsonb;basis jsonb;own_basis jsonb;
 a jsonb;s jsonb;tokens jsonb;sequence_field text:=NULL;sequence_value text:=NULL;common_source boolean;observed timestamptz:=clock_timestamp();companies uuid[];wire_outcome text;
BEGIN
 IF c IS NULL OR actor IS NULL OR source_id IS NULL OR env IS NULL OR env NOT IN('test','production') OR family IS NULL OR family NOT IN('CONTRL','APERAK','UTILTS_ERR')
  OR (sequence_field IS NULL)<>(sequence_value IS NULL) OR sequence_field IS NOT NULL AND (sequence_field NOT IN('relatedTransactionReference','utiltsErrSequenceToken') OR nullif(btrim(sequence_value),'') IS NULL)
  OR family='CONTRL' AND sequence_field IS NOT NULL OR sequence_field='utiltsErrSequenceToken' AND family<>'UTILTS_ERR' THEN
  RAISE EXCEPTION 'ediel_ack_replay_scope_required' USING ERRCODE='22023';END IF;
 -- A permission decision must remain true through source/ACK qualification.
 -- SHARE prevents UPDATE/DELETE and phantom INSERT grants/namespace collisions;
 -- all permission sources used by the current native resolver are included.
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.companies co WHERE co.id=c AND co.status='active') THEN
  RAISE EXCEPTION 'ediel_ack_replay_actor_not_authorized' USING ERRCODE='42501';END IF;
 -- Stabilize the entire own-source candidate set, including opposite outcomes.
 -- A later concurrent INSERT is re-read through this same command after 23505.
 LOCK TABLE public.ediel_messages IN SHARE MODE;
 SELECT * INTO source FROM public.ediel_messages WHERE id=source_id AND environment=env AND direction='inbound'
  AND message_standard='edifact' AND (company_id=c OR company_id IS NULL) FOR SHARE;
 IF source.id IS NULL OR nullif(source.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_ack_replay_actual_source_unavailable';END IF;
 common_source:=family='APERAK' AND source.message_family='PRODAT' AND EXISTS(SELECT FROM gridex_ediel_common_header.sources p WHERE p.source_message_id=source.id AND p.company_id=c AND p.environment=env AND p.status='ready');
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 IF family='CONTRL' THEN
  basis:=gridex_ediel_technical_ack.require_source_v1(c,source.id);
  PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(basis);
 ELSIF common_source THEN
  basis:=gridex_ediel_common_header.require_v1(c,env,source.id);
  PERFORM gridex_ediel_common_header.require_current_scope_v1(basis);
 ELSE
  IF source.company_id IS DISTINCT FROM c THEN RAISE EXCEPTION 'ediel_ack_replay_actual_source_unavailable';END IF;
  basis:=gridex_ediel_source_rules.require_v1(c,source.id);
  context:=gridex_ediel_ack_replay.require_current_source_role_v2(c,env,source.id);
  -- The immutable local legal recipient becomes the ACK issuer. Both wire
  -- legal parties and full transport components are matched below; only the
  -- current local namespace is resolved here, without profile/role re-selection.
  IF context->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR context->>'companyId' IS DISTINCT FROM c::text OR context->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  SELECT array_agg(DISTINCT i.company_id) INTO companies FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId'
   AND i.identifier_value=context->>'legalEdielId' AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to);
  IF cardinality(companies) IS DISTINCT FROM 1 OR companies[1] IS DISTINCT FROM c OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env
   AND i.actor_id::text=context->>'legalActorId' AND i.identifier_type='EdielId' AND i.identifier_value=context->>'legalEdielId'
   AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)) THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(context);
 END IF;
 IF ack_id IS NULL THEN PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source));END IF;
 SELECT array_agg(m.id) INTO ids FROM public.ediel_messages m WHERE m.id=ack_id AND m.company_id=c AND m.environment=env AND m.direction='outbound' AND m.message_family=family;
 IF coalesce(cardinality(ids),0)=0 THEN PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);RETURN NULL;END IF;
 IF cardinality(ids)<>1 THEN RAISE EXCEPTION 'ediel_ack_replay_own_response_ambiguous';END IF;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ids[1] AND company_id=c AND environment=env AND direction='outbound' AND message_family=family FOR SHARE;
 PERFORM gridex_ediel_duplicate_responses.require_business_binding_v1(c,env,source.id,ack.id,family); ack.related_message_id:=source.id;
 IF NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage w WHERE w.source_message_id=ack.id AND w.company_id=c AND w.environment=env
  AND w.payload_sha256=encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'ediel_ack_replay_private_own_wire_unavailable';END IF;
 IF family='CONTRL' THEN
  own_basis:=gridex_ediel_technical_ack.require_contrl_v1(ack);
  IF own_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  wire_outcome:=CASE own_basis->>'syntaxDecision' WHEN 'accepted' THEN 'positive' WHEN 'rejected' THEN 'negative' END;
 ELSIF common_source THEN
  own_basis:=gridex_ediel_ack_replay.require_common_own_v2(ack);
  IF own_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  wire_outcome:='negative';
 ELSE
  own_basis:=gridex_ediel_duplicate_responses.require_business_owner_v1(c,ack.id,source.id);
  IF own_basis IS DISTINCT FROM basis OR gridex_ediel_source_rules.require_v1(c,ack.id) IS DISTINCT FROM basis
   OR NOT EXISTS(SELECT FROM gridex_ediel_source_rules.receipts r WHERE r.source_message_id=ack.id AND r.original_source_message_id=source.id) THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  ack_context:=gridex_ediel_inbound_context.require_v1(c,ack.id);
  IF ack_context->>'basisKind' IS DISTINCT FROM 'prescribed_outbound_ack' OR ack_context->>'originalSourceMessageId' IS DISTINCT FROM source.id::text
   OR ack_context->>'originalSourceHash' IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex')
   OR ack_context->>'legalActorId' IS DISTINCT FROM context->>'legalActorId' OR ack_context->>'legalEdielId' IS DISTINCT FROM context->>'legalEdielId'
   OR ack_context->>'transportActorId' IS DISTINCT FROM context->>'transportActorId' THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  a:=gridex_ack_authority.wire_v1(ack.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
  IF NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_ack_replay_physical_source_mismatch';END IF;
  IF sequence_field='relatedTransactionReference' AND (NOT coalesce(s->'ide','[]') ? sequence_value
   OR NOT (CASE family WHEN 'APERAK' THEN coalesce(a#>'{refs,ACW}','[]') ELSE coalesce(a#>'{refs,TN}','[]') END) ? sequence_value
   OR ack.parsed_payload->>'ackScope' IS DISTINCT FROM 'transaction') THEN RAISE EXCEPTION 'ediel_ack_replay_sequence_mismatch';END IF;
  IF sequence_field='utiltsErrSequenceToken' THEN
   tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='E01' AND t#>>'{elements,2,0}'='41' AND t#>>'{elements,3,0}'=sequence_value) THEN RAISE EXCEPTION 'ediel_ack_replay_sequence_mismatch';END IF;
  END IF;
  wire_outcome:=CASE WHEN family='UTILTS_ERR' THEN 'negative' WHEN jsonb_array_length(coalesce(a->'erc','[]'))>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc') x WHERE x<>'100') THEN 'positive' ELSE 'negative' END;
 END IF;
 IF common_source THEN PERFORM gridex_ediel_ack_replay.require_common_guide_v2(ack,own_basis);ELSE PERFORM gridex_ediel_ack_replay.require_readonly_guide_v2(ack);END IF;
 IF family='APERAK' AND source.message_family='PRODAT' THEN PERFORM gridex_ediel_ack_replay.require_readonly_prodat_ledger_v2(ack);END IF;
 IF family='APERAK' AND source.message_family='PRODAT' AND EXISTS(SELECT FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(ack.raw_payload))t WHERE t->>'tag'='ERC' AND t#>>'{elements,1,0}'='100') THEN
  PERFORM public.ediel_require_recorded_prodat_bilateral_ack_source_v1(c,source.id,encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'));END IF;
 IF NOT common_source AND family<>'CONTRL' AND context->>'actorRole' IN('energy_service_company','esco') AND wire_outcome='positive' THEN
  PERFORM gridex_ediel_ack_replay.require_positive_service_scope_v1(c,env,source.id,ack.raw_payload);END IF;
 IF wire_outcome IS NULL THEN RAISE EXCEPTION 'ediel_ack_replay_own_outcome_mismatch';END IF;
 PERFORM gridex_ediel_duplicate_responses.require_business_creation_outcome_v1(c,env,source.id,ack,wire_outcome);
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,env,source.id,actor,family,NULL,phase);
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source),'ackMessage',to_jsonb(ack)||jsonb_build_object('ack_outcome',wire_outcome));
END $$;

--
-- Name: intents; Type: TABLE; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE TABLE gridex_ediel_duplicate_responses.intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reception_id uuid NOT NULL,
    response_request_id uuid NOT NULL,
    company_id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    environment text NOT NULL,
    source_hash text NOT NULL,
    actor_user_id uuid NOT NULL,
    ack_message_id uuid NOT NULL,
    ack_hash text NOT NULL,
    source_role_hash text NOT NULL,
    guide_source_version text NOT NULL,
    owner_xid xid8 DEFAULT pg_current_xact_id() NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

ALTER TABLE ONLY gridex_ediel_duplicate_responses.intents FORCE ROW LEVEL SECURITY;

--
-- Name: read_result_v1(gridex_ediel_duplicate_responses.intents); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.read_result_v1(i gridex_ediel_duplicate_responses.intents) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c gridex_ediel_duplicate_responses.consumptions%rowtype;m public.ediel_messages%rowtype;o public.ediel_outbox%rowtype;BEGIN
 SELECT * INTO c FROM gridex_ediel_duplicate_responses.consumptions WHERE intent_id=i.id;
 IF c.intent_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=c.acknowledgement_id AND company_id=i.company_id AND environment=i.environment AND related_message_id=i.source_message_id FOR SHARE;
 SELECT * INTO o FROM public.ediel_outbox WHERE id=c.outbox_id AND company_id=i.company_id AND environment=i.environment AND ediel_message_id=m.id AND source_message_id=i.source_message_id FOR SHARE;
 IF m.id IS NULL OR o.id IS NULL OR m.message_family IS DISTINCT FROM 'APERAK' OR m.direction IS DISTINCT FROM 'outbound' OR m.ack_outcome IS DISTINCT FROM 'negative' OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM i.ack_hash OR gridex_ediel_duplicate_responses.allows_message_v1(m) IS NOT TRUE OR NOT EXISTS(SELECT FROM public.ediel_message_events e WHERE e.id=c.event_id AND e.company_id=i.company_id AND e.ediel_message_id=m.id) THEN RAISE EXCEPTION 'ediel_duplicate_established_receipt_changed';END IF;
 RETURN jsonb_build_object('status','protocol_response_prepared','ackMessage',to_jsonb(m),'outboxId',o.id,'receptionId',i.reception_id,'responseRequestId',i.response_request_id,'businessEffectAuthorized',false);
END $$;

--
-- Name: require_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR (phase IN('prepare','send')) IS NOT TRUE
  OR (CASE phase WHEN 'prepare' THEN public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE
      WHEN 'send' THEN public.gridex_actor_has_company_permission(actor,c,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'ediel.send') IS TRUE END) IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_duplicate_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: require_business_binding_v1(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_binding_v1(c uuid, env text, source_id uuid, ack_id uuid, family text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE basis jsonb;entry jsonb;BEGIN
 basis:=gridex_ack_authority.read_outbound_originals_v1(source_id,family);
 IF basis->>'sourceMessageId' IS DISTINCT FROM source_id::text OR basis->>'companyId' IS DISTINCT FROM c::text OR basis->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
 SELECT x INTO entry FROM jsonb_array_elements(basis->'originals')x WHERE x#>>'{message,id}'=ack_id::text;
 IF entry->>'status' IS DISTINCT FROM 'qualified' THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
END$$;

--
-- Name: require_business_creation_outcome_v1(uuid, text, uuid, public.ediel_messages, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_creation_outcome_v1(c uuid, env text, source_id uuid, ack public.ediel_messages, outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE receipt gridex_ediel_ack_replay.creation_receipts%rowtype;source public.ediel_messages%rowtype;BEGIN
 SELECT * INTO receipt FROM gridex_ediel_ack_replay.creation_receipts WHERE ack_message_id=ack.id FOR SHARE;
 IF receipt.ack_message_id IS NULL THEN RETURN;END IF;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id FOR SHARE;
 IF receipt.company_id IS DISTINCT FROM c OR receipt.environment IS DISTINCT FROM env OR receipt.source_message_id IS DISTINCT FROM source_id
  OR receipt.family IS DISTINCT FROM ack.message_family OR receipt.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')
  OR receipt.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR receipt.outcome IS DISTINCT FROM outcome
 THEN RAISE EXCEPTION 'ediel_business_ack_creation_outcome_changed';END IF;
END$$;

--
-- Name: require_business_owner_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_owner_v1(p_company_id uuid, p_message_id uuid, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='outbound' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=c.witness_id
  WHERE c.source_message_id=m.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE OF witness;
 IF w.id IS NULL THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 IF w.related_message_id IS DISTINCT FROM p_source_id THEN RAISE EXCEPTION 'ediel_business_ack_private_relation_changed';END IF; m.related_message_id:=p_source_id; PERFORM gridex_ediel_outbound_owner.assert_message_v1(m,w);RETURN w.evidence;
END $$;

--
-- Name: require_business_read_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_read_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF phase NOT IN('prepare','read','send') OR phase IS NULL OR c IS NULL OR actor IS NULL
  OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR (CASE phase WHEN 'prepare' THEN public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE
 WHEN 'read' THEN public.gridex_actor_has_company_permission(actor,c,'communication.read') IS TRUE
 WHEN 'send' THEN public.gridex_actor_has_company_permission(actor,c,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'ediel.send') IS TRUE ELSE false END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_business_ack_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: require_namespace_v1(uuid, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_namespace_v1(c uuid, env text, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE companies uuid[];observed timestamptz;BEGIN
 IF ctx->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR ctx->>'companyId' IS DISTINCT FROM c::text OR ctx->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_duplicate_legal_scope_invalid';END IF;
 observed:=clock_timestamp();
 SELECT array_agg(DISTINCT i.company_id) INTO companies FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId'
  AND i.identifier_value=ctx->>'legalEdielId' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
 IF cardinality(companies) IS DISTINCT FROM 1 OR companies[1] IS DISTINCT FROM c OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env
  AND i.actor_id::text=ctx->>'legalActorId' AND i.identifier_type='EdielId' AND i.identifier_value=ctx->>'legalEdielId'
  AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to)) THEN RAISE EXCEPTION 'ediel_duplicate_legal_scope_invalid';END IF;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(ctx);
END$$;

--
-- Name: require_transport_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_transport_v1(c uuid, ack_id uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i gridex_ediel_duplicate_responses.intents%rowtype;r gridex_ediel_inbound_receptions.receptions%rowtype;source jsonb;BEGIN
 SELECT intent.* INTO i FROM gridex_ediel_duplicate_responses.consumptions co JOIN gridex_ediel_duplicate_responses.intents intent ON intent.id=co.intent_id WHERE co.acknowledgement_id=ack_id;
 IF i.id IS NULL THEN RETURN;END IF;
 IF i.company_id IS DISTINCT FROM c THEN RAISE EXCEPTION 'ediel_duplicate_transport_company_changed';END IF;
 SELECT * INTO STRICT r FROM gridex_ediel_inbound_receptions.receptions WHERE id=i.reception_id;
 source:=gridex_ediel_duplicate_responses.source_for_execution_v1(c,i.source_message_id,r.inbound_email_message_id,actor,'send');
 IF source->>'sourceHash' IS DISTINCT FROM i.source_hash OR encode(sha256(convert_to((source->'currentContext')::text,'UTF8')),'hex') IS DISTINCT FROM i.source_role_hash OR gridex_ediel_duplicate_responses.read_result_v1(i) IS NULL THEN RAISE EXCEPTION 'ediel_duplicate_current_capability_changed';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(c,i.source_message_id);
 IF gridex_ediel_duplicate_responses.source_for_execution_v1(c,i.source_message_id,r.inbound_email_message_id,actor,'send') IS DISTINCT FROM source THEN RAISE EXCEPTION 'ediel_duplicate_current_capability_changed';END IF;
END$$;

--
-- Name: require_wire_v1(text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_wire_v1(raw text, source_raw text, projection jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;tags text[];ref_count int;BEGIN
 IF gridex_ediel_ack_guide.validate_v1(raw,source_raw,projection) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_duplicate_native_103_wire_required';END IF;
 PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(raw,'APERAK');
 SELECT array_agg(x->>'tag' ORDER BY(x->>'index')::int) INTO tags FROM jsonb_array_elements(tokens)x;
 -- Strict complete D96A producer subset: SG1 ACW before SG2 legal NAD;
 -- SG3 ERC+FTX; at most one SG4 RFF. No directory relaxation for known Z07+LI.
 IF tags IS DISTINCT FROM ARRAY['UNB','UNH','BGM','DTM','DTM','RFF','NAD','NAD','ERC','FTX','UNT','UNZ']::text[] AND tags IS DISTINCT FROM ARRAY['UNB','UNH','BGM','DTM','DTM','RFF','NAD','NAD','ERC','FTX','RFF','UNT','UNZ']::text[] THEN RAISE EXCEPTION 'ediel_duplicate_strict_96a_scope_held';END IF;
 IF tokens#>>'{2,elements,3,0}' IS DISTINCT FROM '27' OR tokens#>>'{3,elements,1,0}' IS DISTINCT FROM '137' OR tokens#>>'{4,elements,1,0}' IS DISTINCT FROM '178' OR tokens#>>'{5,elements,1,0}' IS DISTINCT FROM 'ACW'
  OR tokens#>>'{6,elements,1,0}' IS DISTINCT FROM 'FR' OR tokens#>>'{7,elements,1,0}' IS DISTINCT FROM 'DO' OR tokens#>>'{8,elements,1,0}' IS DISTINCT FROM '40' OR tokens#>>'{9,elements,3,0}' IS DISTINCT FROM '103' OR tokens#>>'{9,elements,4,0}' IS DISTINCT FROM 'Dubblett av meddelandet' THEN RAISE EXCEPTION 'ediel_duplicate_exact_103_required';END IF;
 -- Mandatory own known reference facts are retained, including when that
 -- requires a truthful strict-directory hold. Never drop one to make wire green.
 SELECT count(DISTINCT jsonb_build_array(x#>>'{elements,1,0}',x#>>'{elements,1,1}')) INTO ref_count FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND nullif(x#>>'{elements,1,1}','') IS NOT NULL;
 IF ref_count>1 THEN RAISE EXCEPTION 'ediel_duplicate_multiple_own_reference_scope_held';END IF;
 IF ref_count=1 AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)a JOIN jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))s ON s->>'tag'='RFF' AND s#>>'{elements,1,0}'='LI' AND a#>>'{elements,1,1}'=s#>>'{elements,1,1}' WHERE a->>'tag'='RFF' AND a#>>'{elements,1,0}'='LI') THEN RAISE EXCEPTION 'ediel_duplicate_known_own_reference_required';END IF;
 SELECT count(DISTINCT x#>>'{elements,3,0}') INTO ref_count FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))x WHERE x->>'tag'='LIN' AND nullif(x#>>'{elements,3,0}','') IS NOT NULL;
 IF ref_count>1 THEN RAISE EXCEPTION 'ediel_duplicate_multiple_own_reference_scope_held';END IF;
 IF ref_count=1 AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)a JOIN jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))s ON s->>'tag'='LIN' AND a#>>'{elements,1,1}'=s#>>'{elements,3,0}' WHERE a->>'tag'='RFF' AND a#>>'{elements,1,0}'='Z07') THEN RAISE EXCEPTION 'ediel_duplicate_known_own_reference_required';END IF;
END $$;

--
-- Name: source_for_execution_v1(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.source_for_execution_v1(c uuid, source_id uuid, mail_id uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_ediel_inbound_receptions.receptions%rowtype;q gridex_ediel_inbound_receptions.response_requests%rowtype;
 first gridex_ediel_inbound_receptions.receptions%rowtype;ctx jsonb;basis jsonb;t jsonb;original_hash text;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 PERFORM gridex_ediel_duplicate_responses.require_actor_v1(c,actor,phase);
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c AND direction='inbound' AND message_standard='edifact' AND message_family='PRODAT' FOR SHARE;
 IF m.id IS NULL OR nullif(m.raw_payload,'') IS NULL OR m.message_received_at IS NULL THEN RAISE EXCEPTION 'ediel_duplicate_actual_original_required';END IF;
 original_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 -- Same protected source-only legal namespace/endpoint as read_exact_v2,
 -- with the actual execution purpose kept independent of that prepare port.
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id);
 basis:=gridex_ediel_source_rules.require_v1(c,m.id);
 PERFORM gridex_ediel_duplicate_responses.require_namespace_v1(c,m.environment,ctx);
 IF ctx->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR ctx->>'applicationReference' IS DISTINCT FROM '23-DDQ-PRODAT' THEN RAISE EXCEPTION 'ediel_duplicate_captured_legal_ddq_required';END IF;
 SELECT * INTO r FROM gridex_ediel_inbound_receptions.receptions WHERE company_id=c AND source_message_id=m.id AND inbound_email_message_id=mail_id FOR SHARE;
 SELECT * INTO q FROM gridex_ediel_inbound_receptions.response_requests WHERE reception_id=r.id AND company_id=c AND source_message_id=m.id FOR SHARE;
 SELECT * INTO first FROM gridex_ediel_inbound_receptions.receptions WHERE company_id=c AND source_message_id=m.id AND classification='first_reception' FOR SHARE;
 IF r.id IS NULL OR q.id IS NULL OR first.id IS NULL OR r.classification IS DISTINCT FROM 'protocol_duplicate' OR q.reason IS DISTINCT FROM 'authentic_duplicate_transport_response_policy_required'
  OR r.inbound_email_message_id=first.inbound_email_message_id OR r.environment IS DISTINCT FROM m.environment OR r.canonical_payload_hash IS DISTINCT FROM original_hash OR r.received_payload_hash IS DISTINCT FROM original_hash
  OR first.canonical_payload_hash IS DISTINCT FROM original_hash OR first.received_payload_hash IS DISTINCT FROM original_hash OR r.scope IS DISTINCT FROM first.scope
  OR r.received_at IS NULL OR r.received_at<first.received_at THEN RAISE EXCEPTION 'ediel_duplicate_genuine_same_original_reception_required';END IF;
 -- P26.A p99 field A901 / DTM178 is the actual arrival. This response
 -- belongs to this NEW native reception, never the worker or first-reception
 -- clock. The canonical original timestamp and its earlier ACK remain fixed.
 -- Native source syntax/family and inherited edition/source binding are fixed.
 t:=gridex_ediel_technical_ack.require_source_v1(c,m.id);
 IF t->>'sourceHash' IS DISTINCT FROM original_hash OR t->>'environment' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'ediel_duplicate_source_syntax_required';END IF;
 IF NOT EXISTS(SELECT FROM gridex_ediel_ack_guide.source_bindings b JOIN gridex_ediel_ack_guide.editions e ON e.source_version=b.source_version WHERE b.source_message_id=m.id AND b.kind='national' AND b.company_id=c AND b.environment=m.environment AND b.payload_sha256=original_hash AND b.original_basis=basis AND e.projection#>>'{constraints,PRODAT,applicationTexts,103}'='Dubblett av meddelandet') THEN RAISE EXCEPTION 'ediel_duplicate_inherited_103_guide_required';END IF;
 -- Source/guide/reception reads may wait; current clocks are independent of
 -- table-lock stability. Repeat purpose, role and namespace at the final edge.
 IF gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id) IS DISTINCT FROM ctx THEN RAISE EXCEPTION 'ediel_duplicate_current_source_changed';END IF;
 PERFORM gridex_ediel_duplicate_responses.require_namespace_v1(c,m.environment,ctx);
 PERFORM gridex_ediel_duplicate_responses.require_actor_v1(c,actor,phase);
 RETURN jsonb_build_object('sourceMessage',to_jsonb(m),'receptionId',r.id,'responseRequestId',q.id,'sourceHash',original_hash,'currentContext',ctx,'technicalBasis',t,'sourceReceivedDate203',to_char(r.received_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'),'sourceRulePackEvidence',basis,'businessEffectAuthorized',false);
END $$;

--
-- Name: source_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.source_v1(c uuid, source_id uuid, mail_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ediel_duplicate_responses.source_for_execution_v1(c,source_id,mail_id,actor,'prepare')$$;

--
-- Name: immutable_result_v1(); Type: FUNCTION; Schema: gridex_ediel_exports; Owner: -
--

CREATE FUNCTION gridex_ediel_exports.immutable_result_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP='DELETE' AND OLD.expires_at<=clock_timestamp() THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'ediel_export_result_immutable';
END $$;

--
-- Name: immutable_scope_v1(); Type: FUNCTION; Schema: gridex_ediel_exports; Owner: -
--

CREATE FUNCTION gridex_ediel_exports.immutable_scope_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP<>'UPDATE' OR
  ROW(NEW.id,NEW.beneficiary_company_id,NEW.actor_user_id,NEW.idempotency_key,NEW.grant_id,NEW.expected_grant_version,
      NEW.series_id,NEW.purpose,NEW.fields,NEW.start_at,NEW.end_at,NEW.page_limit,NEW.after_at,NEW.after_id,NEW.created_at)
  IS DISTINCT FROM
  ROW(OLD.id,OLD.beneficiary_company_id,OLD.actor_user_id,OLD.idempotency_key,OLD.grant_id,OLD.expected_grant_version,
      OLD.series_id,OLD.purpose,OLD.fields,OLD.start_at,OLD.end_at,OLD.page_limit,OLD.after_at,OLD.after_id,OLD.created_at)
 THEN RAISE EXCEPTION 'ediel_export_scope_immutable'; END IF;
 RETURN NEW;
END $$;

--
-- Name: assert_ack_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.assert_ack_v1(m public.ediel_messages, e jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;retained jsonb;field text:=e#>>'{negativeField,fieldCode}';t jsonb:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);a jsonb:=gridex_ack_authority.wire_v1(m.raw_payload);s jsonb;u jsonb;h jsonb;b jsonb;g jsonb;f jsonb;reply text;
BEGIN
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id FOR SHARE;retained:=gridex_ediel_header_negative_birth.evidence_v1(source);
 IF retained IS NULL OR (e-'syntaxAssessmentId') IS DISTINCT FROM retained OR field NOT IN('202','311','223') OR retained->'negativeField' IS DISTINCT FROM e->'negativeField' OR retained->'ownOccurrence' IS DISTINCT FROM e->'ownOccurrence'
  OR m.company_id IS DISTINCT FROM source.company_id OR m.environment IS DISTINCT FROM source.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' OR m.message_code IS DISTINCT FROM 'APERAK'
  OR m.canonical_rule_pack_id IS NOT NULL OR m.rule_profile_version_id IS NOT NULL OR m.rule_profile_key IS NOT NULL OR m.rule_profile_version IS NOT NULL OR m.rule_pack_checksum IS NOT NULL OR coalesce(m.rule_pack_snapshot,'{}')<>'{}'::jsonb
  OR a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a->>'function' IS DISTINCT FROM (CASE field WHEN '223' THEN '34' ELSE '27' END)
  OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='ERC')<>1 OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='FTX')<>1 THEN RAISE EXCEPTION 'assigned_prodat_negative_ack_scope_required';END IF;
 reply:=gridex_ediel_header_negative_birth.reply_application_v1(source,e);s:=gridex_ediel_header_negative_birth.source_wire_v1(source);u:=gridex_ediel_technical_ack.envelope(source.raw_payload);
 SELECT x->'elements' INTO h FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNH';SELECT x->'elements' INTO b FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNB';SELECT x->'elements' INTO g FROM jsonb_array_elements(t)x WHERE x->>'tag'='ERC';SELECT x->'elements' INTO f FROM jsonb_array_elements(t)x WHERE x->>'tag'='FTX';
 IF h->2 IS DISTINCT FROM e#>'{familyEdition,sourceProjection,catalog,ackConstraints,technicalProfile}' OR b->2 IS DISTINCT FROM u->'receiver' OR b->3 IS DISTINCT FROM u->'sender' OR nullif(b#>>'{7,0}','') IS DISTINCT FROM reply OR coalesce(b#>>'{11,0}','') IS DISTINCT FROM u->>'testIndicator'
  OR g->1 IS DISTINCT FROM jsonb_build_array(e#>>'{negativeField,ercCode}','','260') OR f->1 IS DISTINCT FROM '["AAO"]'::jsonb OR f->3 IS DISTINCT FROM jsonb_build_array(field,'','260') OR f->4 IS DISTINCT FROM jsonb_build_array(e#>>'{negativeField,text}')
  OR jsonb_array_length(f)>5 OR coalesce(f->2,'[]') NOT IN('[]'::jsonb,'[""]'::jsonb) OR length(f#>>'{4,0}')>(e#>>'{familyEdition,sourceProjection,catalog,ackConstraints,textMax}')::int
  OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='BGM')<>1 OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='DTM')<>1
  OR EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag' NOT IN('UNB','UNH','BGM','DTM','NAD','ERC','FTX','RFF','UNT','UNZ'))
  OR (SELECT(x->>'index')::int FROM jsonb_array_elements(t)x WHERE x->>'tag'='FTX') IS DISTINCT FROM (SELECT(x->>'index')::int+1 FROM jsonb_array_elements(t)x WHERE x->>'tag'='ERC')
  OR nullif(h#>>'{1,0}','') IS NULL OR length(h#>>'{1,0}')>14
  OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=e#>>'{familyEdition,sourceProjection,catalog,commonAckConstraints,documentDate,qualifier}' AND x#>>'{elements,1,2}'=e#>>'{familyEdition,sourceProjection,catalog,commonAckConstraints,documentDate,format}' AND gridex_ediel_ack_guide.date_time_v1(x#>>'{elements,1,1}') IS TRUE)<>1
  THEN RAISE EXCEPTION 'assigned_prodat_negative_ack_scope_required';END IF;
 IF EXISTS(SELECT FROM unnest(ARRAY['FR','DO'])role WHERE(SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=role)<>1)
  OR EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' IN('FR','DO') AND(x->>'index')::int>=(SELECT(z->>'index')::int FROM jsonb_array_elements(t)z WHERE z->>'tag'='ERC'))
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='FR' AND x#>'{elements,2}'=e#>'{identities,legalReceiver,identityComponents}' AND x#>>'{elements,9,0}'=e#>>'{identities,legalReceiver,country}')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='DO' AND x#>'{elements,2}'=e#>'{identities,legalSender,identityComponents}' AND x#>>'{elements,9,0}'=e#>>'{identities,legalSender,country}') THEN RAISE EXCEPTION 'assigned_prodat_negative_ack_scope_required';END IF;
 -- APP correction applies only to this actual frozen311 negative, in a local
 -- wire observation. Retained source raw/APP and the global predicate stay intact.
 IF field='311' THEN s:=jsonb_set(s,'{app}',to_jsonb(reply));END IF;
 IF NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'assigned_prodat_negative_ack_scope_required';END IF;
 IF field='223' THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' IN('LI','Z07') AND(x->>'index')::int<(SELECT(z->>'index')::int FROM jsonb_array_elements(t)z WHERE z->>'tag'='FTX'))
   OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND x#>>'{elements,1,1}'=e#>>'{ownOccurrence,lineItemReference}')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND x#>>'{elements,1,1}'=e#>>'{ownOccurrence,objectId}')<>1
   OR EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' NOT IN('ACW','LI','Z07')) THEN RAISE EXCEPTION 'assigned_prodat_negative_223_own_object_required';END IF;
 ELSE
  IF EXISTS(SELECT FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' NOT IN('ACW')) THEN RAISE EXCEPTION 'assigned_prodat_negative_ack_scope_required';END IF;
 END IF;
END $$;

--
-- Name: classify_v1(text); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.classify_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);u jsonb:=gridex_ediel_technical_ack.envelope(raw);h jsonb;b jsonb;l jsonb;selector jsonb;trailer jsonb;end_interchange jsonb;reason text;code text;field text;li text;missing integer;
BEGIN
 IF t IS NULL OR u IS NULL OR octet_length(raw)>262144
  OR EXISTS(SELECT FROM unnest(ARRAY['UNB','UNH','BGM','LIN','UNT','UNZ'])tag WHERE (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'=tag)<>1) THEN RETURN NULL;END IF;
 SELECT x INTO trailer FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNT';SELECT x INTO end_interchange FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNZ';
 SELECT x INTO h FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNH';SELECT x INTO b FROM jsonb_array_elements(t)x WHERE x->>'tag'='BGM';SELECT x INTO l FROM jsonb_array_elements(t)x WHERE x->>'tag'='LIN';
 IF (h->>'index')::int<>1 OR (trailer->>'index')::int<>jsonb_array_length(t)-2 OR (end_interchange->>'index')::int<>jsonb_array_length(t)-1
  OR trailer#>'{elements,1}' IS DISTINCT FROM jsonb_build_array(((trailer->>'index')::int-(h->>'index')::int+1)::text) OR trailer#>'{elements,2}' IS DISTINCT FROM h#>'{elements,1}'
  OR end_interchange#>'{elements,1}' IS DISTINCT FROM '["1"]'::jsonb OR end_interchange#>>'{elements,2,0}' IS DISTINCT FROM u->>'interchangeReference'
  OR h#>'{elements,2}' IS DISTINCT FROM '["PRODAT","D","97A","UN","E2SE6A"]'::jsonb
  OR nullif(h#>>'{elements,1,0}','') IS NULL OR length(h#>>'{elements,1,0}')>14
  OR nullif(b#>>'{elements,2,0}','') IS NULL OR length(b#>>'{elements,2,0}')>35
  OR b#>>'{elements,3,0}' IS DISTINCT FROM '9' OR b#>>'{elements,4,0}' IS DISTINCT FROM 'AB'
  OR l#>'{elements,1}' IS DISTINCT FROM '["1"]'::jsonb OR coalesce(l#>'{elements,2}','[]') NOT IN('[]'::jsonb,'[""]'::jsonb)
  OR coalesce(l#>>'{elements,3,0}','')!~'^[0-9]{18}$' OR coalesce(l#>>'{elements,3,3}','') NOT IN('9','89')
  OR (l->>'index')::int<=(b->>'index')::int THEN RETURN NULL;END IF;
 SELECT x INTO selector FROM jsonb_array_elements(t)x WHERE x->>'tag'='CCI' AND x#>>'{elements,2,0}'='Z13';
 IF (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='CCI' AND x#>>'{elements,2,0}'='Z13')>1 THEN RETURN NULL;END IF;
 IF selector IS NOT NULL THEN
  IF (selector->>'index')::int<=(l->>'index')::int THEN RETURN NULL;END IF;
  SELECT x#>>'{elements,1,0}' INTO reason FROM jsonb_array_elements(t)x WHERE x->>'tag'='CAV' AND (x->>'index')::int=(selector->>'index')::int+1;
  IF reason IS DISTINCT FROM 'Z25' THEN RETURN NULL;END IF;
 END IF;
 missing:=(nullif(b#>>'{elements,1,0}','') IS NULL)::int+(nullif(u->>'applicationReference','') IS NULL)::int+(selector IS NULL)::int;
 IF missing<>1 THEN RETURN NULL;END IF;code:=nullif(b#>>'{elements,1,0}','');
 field:=CASE WHEN code IS NULL THEN '202' WHEN nullif(u->>'applicationReference','') IS NULL THEN '311' ELSE '223' END;
 IF field='202' AND(u->>'applicationReference' IS DISTINCT FROM '23-DDQ-PRODAT' OR reason IS DISTINCT FROM 'Z25' OR EXISTS(SELECT FROM jsonb_array_elements_text(coalesce(b#>'{elements,1}','[]'))x WHERE nullif(x,'') IS NOT NULL)) THEN RETURN NULL;END IF;
 IF field IN('311','223') AND code IS DISTINCT FROM 'Z04' THEN RETURN NULL;END IF;
 IF field='223' AND u->>'applicationReference' IS DISTINCT FROM '23-DDQ-PRODAT' THEN RETURN NULL;END IF;
 IF field='311' AND reason IS DISTINCT FROM 'Z25' THEN RETURN NULL;END IF;
 SELECT min(x#>>'{elements,1,1}') INTO li FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND (x->>'index')::int>(l->>'index')::int;
 IF (SELECT count(*) FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND (x->>'index')::int>(l->>'index')::int)<>1 OR nullif(li,'') IS NULL OR length(li)>35 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('fieldCode',field,'physicalCode',code,'parsedCode',coalesce(code,'PRODAT_UNKNOWN'),'originalUNB',u,'messageReference',h#>>'{elements,1,0}',
  'negativeScope',CASE field WHEN '223' THEN 'object' ELSE 'message' END,'ownOccurrence',CASE WHEN field='223' THEN jsonb_build_object('scope','object','messageReference',h#>>'{elements,1,0}','lineIndex',0,'lineNumber','1','registerPosition',1,'firstLineIndex',(l->>'index')::int,'objectId',l#>>'{elements,3,0}','identityAgency',l#>>'{elements,3,3}','lineItemReference',li) ELSE NULL END);
END $_$;

--
-- Name: complete_v1(); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.complete_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT FROM gridex_ediel_header_negative_birth.receipts r JOIN public.ediel_messages m ON m.id=r.source_message_id WHERE r.source_message_id=NEW.source_message_id AND r.status='consumed' AND gridex_ediel_header_negative_birth.is_bound_v1(m,false)) THEN RAISE EXCEPTION 'assigned_prodat_negative_birth_not_consumed';END IF;RETURN NEW;
END $$;

--
-- Name: create_v1(uuid, text, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.create_v1(c uuid, env text, actor uuid, mail_id uuid, parse_id uuid, expected_raw text, expected_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE mail public.inbound_email_messages%rowtype;p public.inbound_ediel_parse_results%rowtype;box public.ediel_mailboxes%rowtype;m public.ediel_messages%rowtype;r gridex_ediel_header_negative_birth.receipts%rowtype;
 observed timestamptz;classification jsonb;e jsonb;facts jsonb;reception jsonb;tokens jsonb;bgm jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_ediel_inbound_receptions.authorize_v1(c,actor,'communication.write');
 IF env IS NULL OR env NOT IN('test','production') OR mail_id IS NULL OR parse_id IS NULL OR expected_raw IS NULL OR expected_hash IS NULL OR expected_hash IS DISTINCT FROM encode(sha256(convert_to(expected_raw,'UTF8')),'hex') THEN RAISE EXCEPTION 'assigned_prodat_negative_expected_original_required';END IF;
 SELECT * INTO mail FROM public.inbound_email_messages WHERE id=mail_id FOR UPDATE;SELECT * INTO p FROM public.inbound_ediel_parse_results WHERE id=parse_id FOR SHARE;SELECT * INTO box FROM public.ediel_mailboxes WHERE id=mail.mailbox_id FOR SHARE;
 IF mail.id IS NULL OR mail.company_id IS DISTINCT FROM c OR mail.environment IS DISTINCT FROM env OR mail.received_at IS NULL OR p.id IS NULL OR p.company_id IS DISTINCT FROM c OR p.inbound_email_message_id IS DISTINCT FROM mail.id OR p.raw_payload IS DISTINCT FROM expected_raw
  OR box.id IS NULL OR box.environment IS DISTINCT FROM env OR box.is_active IS NOT TRUE OR (box.company_id IS DISTINCT FROM c AND box.is_shared_platform_mailbox IS NOT TRUE)
  OR box.email_address IS NULL OR btrim(box.email_address)!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$' THEN RAISE EXCEPTION 'assigned_prodat_negative_retained_ingress_required';END IF;
 PERFORM a.id FROM public.inbound_email_attachments a WHERE a.inbound_email_message_id=mail.id ORDER BY a.id FOR SHARE;
 IF NOT(coalesce(position(p.raw_payload IN mail.raw_edifact_payload),0)>0 OR coalesce(position(p.raw_payload IN mail.body_text),0)>0 OR coalesce(position(p.raw_payload IN mail.raw_email),0)>0 OR EXISTS(SELECT FROM public.inbound_email_attachments a WHERE a.inbound_email_message_id=mail.id AND(a.company_id IS NULL OR a.company_id=c) AND coalesce(position(p.raw_payload IN a.raw_text),0)>0)) THEN RAISE EXCEPTION 'assigned_prodat_negative_retained_bytes_required';END IF;
 classification:=gridex_ediel_header_negative_birth.classify_v1(expected_raw);
 IF classification IS NULL OR p.message_family IS DISTINCT FROM 'PRODAT' OR p.message_code IS DISTINCT FROM classification->>'parsedCode'
  OR p.sender_sub_address IS DISTINCT FROM nullif(classification#>>'{originalUNB,sender,2}','') OR p.receiver_sub_address IS DISTINCT FROM nullif(classification#>>'{originalUNB,receiver,2}','')
  OR p.application_reference IS DISTINCT FROM nullif(classification#>>'{originalUNB,applicationReference}','') OR p.sender_ediel_id IS DISTINCT FROM classification#>>'{originalUNB,sender,0}' OR p.receiver_ediel_id IS DISTINCT FROM classification#>>'{originalUNB,receiver,0}' OR p.interchange_reference IS DISTINCT FROM classification#>>'{originalUNB,interchangeReference}' THEN RAISE EXCEPTION 'assigned_prodat_negative_exact_classification_required';END IF;
 SELECT * INTO r FROM gridex_ediel_header_negative_birth.receipts WHERE inbound_email_message_id=mail_id FOR SHARE;
 IF r.source_message_id IS NOT NULL THEN
  SELECT * INTO m FROM public.ediel_messages WHERE id=r.source_message_id FOR SHARE;
  IF r.company_id IS DISTINCT FROM c OR r.environment IS DISTINCT FROM env OR r.actor_user_id IS DISTINCT FROM actor OR r.parse_result_id IS DISTINCT FROM parse_id OR r.payload_sha256 IS DISTINCT FROM expected_hash OR r.source_received_at IS DISTINCT FROM mail.received_at OR NOT gridex_ediel_header_negative_birth.is_bound_v1(m,false) THEN RAISE EXCEPTION 'assigned_prodat_negative_replay_conflict';END IF;
 ELSE
  observed:=clock_timestamp();e:=gridex_ediel_header_negative_birth.family_basis_v1(c,env,expected_raw,mail.received_at,observed,classification);m.id:=gen_random_uuid();
  e:=e||jsonb_build_object('sourceMessageId',m.id,'assignedNegativeBirthReceiptId',m.id);
  facts:=jsonb_build_object('messageCode',p.message_code,'applicationReference',p.application_reference,'senderEdielId',p.sender_ediel_id,'receiverEdielId',p.receiver_ediel_id,'interchangeReference',p.interchange_reference);
  INSERT INTO gridex_ediel_header_negative_birth.receipts VALUES(m.id,c,env,actor,mail.id,p.id,expected_hash,mail.received_at,observed,txid_current(),'pending',facts,e) RETURNING * INTO r;
  tokens:=gridex_utilts_binding.wire_tokens_v1(expected_raw);SELECT x INTO bgm FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';
  INSERT INTO public.ediel_messages(id,company_id,environment,direction,message_standard,message_family,message_code,status,created_by,resolved_company_id,
   sender_ediel_id,receiver_ediel_id,sender_sub_address,receiver_sub_address,parsed_unb_sender_ediel_id,parsed_unb_receiver_ediel_id,application_reference,interchange_reference,external_reference,raw_payload,parsed_payload,
   inbound_email_message_id,mailbox_message_id,message_received_at,processing_status,tenant_resolution_status,business_match_status)
  VALUES(m.id,c,env,'inbound','edifact','PRODAT',p.message_code,'validation_failed',actor,c,p.sender_ediel_id,p.receiver_ediel_id,p.sender_sub_address,p.receiver_sub_address,p.sender_ediel_id,p.receiver_ediel_id,p.application_reference,p.interchange_reference,bgm#>>'{elements,2,0}',expected_raw,p.parsed_payload,
   mail.id,mail.id::text,mail.received_at,'manual_review','tenant_resolved','business_unresolved') RETURNING * INTO m;
  IF NOT gridex_ediel_header_negative_birth.is_bound_v1(m,true) THEN RAISE EXCEPTION 'assigned_prodat_negative_birth_scope_required';END IF;
  reception:=public.ediel_record_inbound_reception_v1(c,m.id,actor,mail.id,p.id);
  IF reception->>'classification' IS DISTINCT FROM 'first_reception' THEN RAISE EXCEPTION 'assigned_prodat_negative_first_reception_required';END IF;
  UPDATE gridex_ediel_header_negative_birth.receipts SET status='consumed' WHERE source_message_id=m.id RETURNING * INTO r;
 END IF;
 RETURN jsonb_build_object('version',1,'disposition','assigned_header_negative','sourceMessageId',r.source_message_id,'companyId',r.company_id,'environment',r.environment,'sourcePayloadHash',r.payload_sha256,'inboundEmailMessageId',r.inbound_email_message_id,'parseResultId',r.parse_result_id,'sourceReceivedAt',r.source_received_at,
  'fieldCode',r.evidence#>>'{negativeField,fieldCode}','rejectionField',r.evidence->'negativeField','correctedApplicationReference',CASE WHEN r.evidence#>>'{negativeField,fieldCode}'='311' THEN r.evidence->'replyApplicationReference' ELSE 'null'::jsonb END,'authorizesBusinessEffect',false,'permanentNegative',true);
END $_$;

--
-- Name: evidence_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.evidence_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb;
BEGIN
 IF NOT(gridex_ediel_header_negative_birth.is_bound_v1(m,true) OR gridex_ediel_header_negative_birth.is_bound_v1(m,false)) THEN RETURN NULL;END IF;
 SELECT evidence INTO e FROM gridex_ediel_header_negative_birth.receipts WHERE source_message_id=m.id;RETURN e;
END $$;

--
-- Name: family_basis_v1(uuid, text, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.family_basis_v1(c uuid, env text, raw text, received_at timestamp with time zone, observed timestamp with time zone, classification jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);l integer;fr jsonb;recipient jsonb;cs uuid[];actors uuid[];namespace jsonb;
 editions jsonb;edition jsonb;guide jsonb;pack public.ediel_rule_packs%rowtype;sources jsonb;day date;g jsonb;process jsonb;process_version text;role_facts jsonb;market_facts jsonb;correction jsonb;field text:=classification->>'fieldCode';reply_app text:=nullif(classification#>>'{originalUNB,applicationReference}','');
BEGIN
 IF classification IS NULL OR classification#>>'{originalUNB,environment}' IS DISTINCT FROM env OR received_at IS NULL THEN RAISE EXCEPTION 'assigned_prodat_negative_family_basis_required';END IF;
 SELECT min((x->>'index')::int) INTO l FROM jsonb_array_elements(t)x WHERE x->>'tag'='LIN';
 SELECT x INTO STRICT fr FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='FR' AND (x->>'index')::int<l;
 SELECT x INTO STRICT recipient FROM jsonb_array_elements(t)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='DO' AND (x->>'index')::int<l;
 IF fr#>'{elements,2}' IS DISTINCT FROM jsonb_build_array(fr#>>'{elements,2,0}','160','SVK') OR recipient#>'{elements,2}' IS DISTINCT FROM jsonb_build_array(recipient#>>'{elements,2,0}','160','SVK')
  OR coalesce(fr#>>'{elements,2,0}','')!~'^[0-9]{5}$' OR coalesce(recipient#>>'{elements,2,0}','')!~'^[0-9]{5}$'
  OR coalesce(fr#>>'{elements,9,0}','')!~'^[A-Z]{2}$' OR coalesce(recipient#>>'{elements,9,0}','')!~'^[A-Z]{2}$' THEN RAISE EXCEPTION 'assigned_prodat_negative_legal_header_required';END IF;
 LOCK TABLE public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles IN SHARE MODE;
 SELECT array_agg(DISTINCT i.company_id),array_agg(DISTINCT i.actor_id) INTO cs,actors FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId' AND i.identifier_value=recipient#>>'{elements,2,0}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
 IF cardinality(cs) IS DISTINCT FROM 1 OR cardinality(actors) IS DISTINCT FROM 1 OR cs[1] IS DISTINCT FROM c THEN RAISE EXCEPTION 'assigned_prodat_negative_namespace_required';END IF;
 SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) INTO namespace FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.actor_id=actors[1] AND i.environment=env AND i.identifier_type='EdielId' AND i.identifier_value=recipient#>>'{elements,2,0}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
 day:=(received_at AT TIME ZONE 'Europe/Stockholm')::date;
 SELECT jsonb_agg(e.evidence) INTO editions FROM gridex_ediel_common_header.source_editions e WHERE e.evidence#>>'{originalSource,sha256}'='83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95' AND EXISTS(SELECT FROM jsonb_array_elements(e.evidence#>'{catalog,guides}')x WHERE(x->>'effectiveFrom')::date<=day AND(x->>'effectiveTo' IS NULL OR day<=(x->>'effectiveTo')::date));
 IF jsonb_array_length(coalesce(editions,'[]'))<>1 THEN RAISE EXCEPTION 'assigned_prodat_negative_original_guide_required';END IF;edition:=editions->0;
 SELECT x INTO STRICT guide FROM jsonb_array_elements(edition#>'{catalog,guides}')x WHERE(x->>'effectiveFrom')::date<=day AND(x->>'effectiveTo' IS NULL OR day<=(x->>'effectiveTo')::date);
 LOCK TABLE public.ediel_rule_packs,public.ediel_rule_pack_sources IN SHARE MODE;
 SELECT * INTO STRICT pack FROM public.ediel_rule_packs p WHERE p.family='PRODAT' AND p.market='electricity' AND p.status IN('active','transition','future') AND p.guide_version||':r'||p.guide_revision=edition#>>'{catalog,registeredVersion}' AND p.unh_association_code=guide->>'associationAssignedCode' AND p.valid_from<=day AND(p.valid_to IS NULL OR day<=p.valid_to);
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id;
 SELECT evidence INTO STRICT g FROM gridex_ediel_header_negative_birth.guide_extensions;
 IF g->>'sourceSha256' IS DISTINCT FROM edition#>>'{originalSource,sha256}' OR g#>>'{sourceTable,source}' IS DISTINCT FROM 'P' OR g#>>'{sourceTable,page}' IS DISTINCT FROM '120' OR g->>'tableIndex' IS DISTINCT FROM '105' THEN RAISE EXCEPTION 'assigned_prodat_negative_original_guide_required';END IF;
 IF field='311' THEN
  -- Existing frozen source process projection, not a business profile, owns the
  -- correction. The actual source remains missing APP and receives no role grant.
  process_version:='111385d7f0a83dd865de369ccee9aae3dc52098a5d3105cb3bacb4070ff7579b';
  SELECT x INTO STRICT process FROM gridex_ediel_readiness.source_editions e CROSS JOIN LATERAL jsonb_array_elements(e.catalog)x WHERE e.source_version=process_version AND x->>'family'='PRODAT' AND x->>'code'='Z04' AND x->>'subtype'='H' AND x->>'transactionReasonCode'='Z25' AND x->>'direction'='inbound' AND x->'receiverRoles'='["supplier"]'::jsonb AND x->'applicationReferences'='["23-DDQ-PRODAT"]'::jsonb;
  SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) INTO role_facts FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=env AND r.actor_id=actors[1] AND r.role_code='electricity_supplier' AND r.valid_from<=observed AND(r.valid_to IS NULL OR observed<r.valid_to);
  SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO market_facts FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=env AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND(p.valid_to IS NULL OR observed<p.valid_to);
  IF jsonb_array_length(coalesce(role_facts,'[]'))<>1 OR jsonb_array_length(coalesce(market_facts,'[]'))<>1 THEN RAISE EXCEPTION 'assigned_prodat_negative_311_supplier_process_required';END IF;
  reply_app:=process#>>'{applicationReferences,0}';
  correction:=jsonb_build_object('sourceEdition',edition->>'sourceVersion','sourceSha256',g->>'sourceSha256','tableIndex',105,'page',120,'fieldCode','311','originalApplicationReference',NULL,'expectedApplicationReference',reply_app,'processEdition',process_version,'canonicalProjection',process,'actorRole','electricity_supplier','market','electricity','legalActorId',actors[1],'roleFacts',role_facts,'marketFacts',market_facts,'sourceTableSha256',g->>'sourceTableSha256');
 END IF;
 RETURN jsonb_build_object('kind','prodat_common_header_rejection','version',1,'companyId',c,'environment',env,'sourceHash',encode(sha256(convert_to(raw,'UTF8')),'hex'),'sourceReceivedAt',received_at,'observedAt',observed,
  'negativeField',jsonb_build_object('fieldCode',field,'ercCode','41','text',(edition#>>ARRAY['catalog','ackConstraints','fieldLabels',field])||' saknas'),'negativeScope',classification->'negativeScope','ownOccurrence',classification->'ownOccurrence',
  'guide',guide,'familyEdition',jsonb_build_object('version',edition#>>'{catalog,registeredVersion}','rulePack',to_jsonb(pack),'guideSources',sources,'sourceProjection',edition||jsonb_build_object('negativeHeaderGuide',g)),
  'identities',jsonb_build_object('family','PRODAT','transport',jsonb_build_object('interchangeReference',classification#>>'{originalUNB,interchangeReference}','uciReference',classification#>>'{originalUNB,uciReference}','senderComponents',classification#>'{originalUNB,sender}','receiverComponents',classification#>'{originalUNB,receiver}'),
   'legalSender',jsonb_build_object('id',fr#>>'{elements,2,0}','identityComponents',fr#>'{elements,2}','country',fr#>>'{elements,9,0}'),'legalReceiver',jsonb_build_object('id',recipient#>>'{elements,2,0}','identityComponents',recipient#>'{elements,2}','country',recipient#>>'{elements,9,0}'),'applicationReference',nullif(classification#>>'{originalUNB,applicationReference}','')),
  'legalNamespace',namespace,'replyApplicationReference',reply_app,'applicationReferenceCorrection',correction,'authorizesBusinessEffect',false,'permanentNegative',true)
  || CASE WHEN field='202' THEN jsonb_build_object('field202',jsonb_build_object('fieldCode','202','ercCode','41','text',edition#>>'{catalog,label}'||' saknas')) ELSE '{}'::jsonb END;
END $_$;

--
-- Name: immutable_guide_v1(); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.immutable_guide_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN RAISE EXCEPTION 'assigned_prodat_negative_original_guide_immutable';END $$;

--
-- Name: is_bound_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.is_bound_v1(m public.ediel_messages, pending boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_ediel_header_negative_birth.receipts r WHERE r.source_message_id=m.id AND r.company_id=m.company_id AND r.environment=m.environment AND r.actor_user_id=m.created_by
  AND r.inbound_email_message_id=m.inbound_email_message_id AND r.inbound_email_message_id::text=m.mailbox_message_id AND r.source_received_at=m.message_received_at AND r.payload_sha256=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  AND m.direction='inbound' AND m.message_standard='edifact' AND m.message_family='PRODAT' AND m.resolved_company_id=m.company_id
  AND m.message_code=r.source_facts->>'messageCode' AND m.application_reference IS NOT DISTINCT FROM r.source_facts->>'applicationReference'
  AND m.sender_ediel_id=r.source_facts->>'senderEdielId' AND m.receiver_ediel_id=r.source_facts->>'receiverEdielId' AND m.interchange_reference=r.source_facts->>'interchangeReference'
  AND m.canonical_rule_pack_id IS NULL AND m.rule_profile_version_id IS NULL AND m.rule_profile_key IS NULL AND m.rule_profile_version IS NULL AND m.rule_pack_checksum IS NULL AND coalesce(m.rule_pack_snapshot,'{}')='{}'::jsonb
  AND m.switch_request_id IS NULL AND m.grid_owner_data_request_id IS NULL AND m.partner_export_id IS NULL
  AND m.customer_id IS NULL AND m.site_id IS NULL AND m.metering_point_id IS NULL AND m.grid_owner_id IS NULL AND m.outbound_request_id IS NULL AND m.related_message_id IS NULL
  AND ((pending AND r.status='pending' AND r.creation_txid=txid_current()) OR(NOT pending AND r.status='consumed')))
$$;

--
-- Name: original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT FROM gridex_ediel_header_negative_birth.receipts r WHERE r.source_message_id=OLD.id) THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;
 IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND gridex_ediel_header_negative_birth.is_bound_v1(NEW,false) AND NEW.immutable_payload_hash IS NOT DISTINCT FROM OLD.immutable_payload_hash
  AND NEW.sender_sub_address IS NOT DISTINCT FROM OLD.sender_sub_address AND NEW.receiver_sub_address IS NOT DISTINCT FROM OLD.receiver_sub_address
  AND NEW.parsed_unb_sender_ediel_id IS NOT DISTINCT FROM OLD.parsed_unb_sender_ediel_id AND NEW.parsed_unb_receiver_ediel_id IS NOT DISTINCT FROM OLD.parsed_unb_receiver_ediel_id
  AND NEW.external_reference IS NOT DISTINCT FROM OLD.external_reference THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'assigned_prodat_negative_original_immutable' USING ERRCODE='23514';
END $$;

--
-- Name: receipt_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.receipt_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='pending' AND NEW.status='consumed' AND OLD.creation_txid=txid_current()
  AND (to_jsonb(NEW)-'status')=(to_jsonb(OLD)-'status') AND EXISTS(SELECT FROM public.ediel_messages m WHERE m.id=NEW.source_message_id AND gridex_ediel_header_negative_birth.is_bound_v1(m,true)) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'assigned_prodat_negative_birth_receipt_immutable' USING ERRCODE='23514';
END $$;

--
-- Name: reply_application_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.reply_application_v1(m public.ediel_messages, e jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE retained jsonb;correction jsonb;
BEGIN
 retained:=gridex_ediel_header_negative_birth.evidence_v1(m);
 IF retained IS NULL OR retained->'negativeField' IS DISTINCT FROM e->'negativeField' OR retained->'applicationReferenceCorrection' IS DISTINCT FROM e->'applicationReferenceCorrection' OR retained->'replyApplicationReference' IS DISTINCT FROM e->'replyApplicationReference' THEN RAISE EXCEPTION 'assigned_prodat_negative_reply_source_required';END IF;
 IF retained#>>'{negativeField,fieldCode}'<>'311' THEN RETURN retained->>'replyApplicationReference';END IF;
 correction:=retained->'applicationReferenceCorrection';
 IF m.application_reference IS NOT NULL OR gridex_ediel_header_negative_birth.classify_v1(m.raw_payload)->>'fieldCode' IS DISTINCT FROM '311'
  OR correction->>'processEdition' IS DISTINCT FROM '111385d7f0a83dd865de369ccee9aae3dc52098a5d3105cb3bacb4070ff7579b' OR correction->>'expectedApplicationReference' IS DISTINCT FROM '23-DDQ-PRODAT'
  OR correction->>'sourceSha256' IS DISTINCT FROM '83c2f1d2915851d2e670731f6ab404ef06c9b9def282afbafdfa0eda836a6e95' OR correction->>'tableIndex' IS DISTINCT FROM '105' OR correction->>'page' IS DISTINCT FROM '120'
  OR correction->'originalApplicationReference' IS DISTINCT FROM 'null'::jsonb OR correction->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR correction->>'market' IS DISTINCT FROM 'electricity'
 THEN RAISE EXCEPTION 'assigned_prodat_negative_reply_source_required';END IF;
 RETURN correction->>'expectedApplicationReference';
END $$;

--
-- Name: require_fresh_reply_process_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.require_fresh_reply_process_v1(m public.ediel_messages, e jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE retained jsonb;correction jsonb;observed timestamptz:=clock_timestamp();legal_actor_uuid uuid;
BEGIN
 PERFORM gridex_ediel_header_negative_birth.reply_application_v1(m,e);retained:=gridex_ediel_header_negative_birth.evidence_v1(m);
 IF retained IS NULL OR retained->'negativeField' IS DISTINCT FROM e->'negativeField' OR retained->'applicationReferenceCorrection' IS DISTINCT FROM e->'applicationReferenceCorrection' OR retained->'replyApplicationReference' IS DISTINCT FROM e->'replyApplicationReference' THEN RAISE EXCEPTION 'assigned_prodat_negative_reply_source_required';END IF;
 IF retained#>>'{negativeField,fieldCode}'<>'311' THEN RETURN;END IF;
 correction:=retained->'applicationReferenceCorrection';legal_actor_uuid:=(correction->>'legalActorId')::uuid;
 LOCK TABLE public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles IN SHARE MODE;
 IF correction->>'processEdition' IS DISTINCT FROM '111385d7f0a83dd865de369ccee9aae3dc52098a5d3105cb3bacb4070ff7579b' OR correction->>'expectedApplicationReference' IS DISTINCT FROM '23-DDQ-PRODAT'
  OR m.application_reference IS NOT NULL OR gridex_ediel_header_negative_birth.classify_v1(m.raw_payload)->>'fieldCode' IS DISTINCT FROM '311'
  OR NOT EXISTS(SELECT FROM gridex_ediel_readiness.source_editions d CROSS JOIN LATERAL jsonb_array_elements(d.catalog)x WHERE d.source_version=correction->>'processEdition' AND x=correction->'canonicalProjection')
  OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.actor_id=legal_actor_uuid AND i.identifier_type='EdielId' AND i.identifier_value=e#>>'{identities,legalReceiver,id}' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to))
  OR (SELECT count(*) FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment AND r.actor_id=legal_actor_uuid AND r.role_code='electricity_supplier' AND r.valid_from<=observed AND(r.valid_to IS NULL OR observed<r.valid_to))<>1
  OR (SELECT count(*) FROM public.tenant_ediel_profiles p WHERE p.company_id=m.company_id AND p.environment=m.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND(p.valid_to IS NULL OR observed<p.valid_to))<>1 THEN RAISE EXCEPTION 'assigned_prodat_negative_311_current_process_required';END IF;
 RETURN;
END $$;

--
-- Name: scopes_v1(text, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.scopes_v1(raw text, source public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb:=gridex_ediel_header_negative_birth.evidence_v1(source);m public.ediel_messages%rowtype;wire jsonb;
BEGIN
 IF e#>>'{negativeField,fieldCode}' IS DISTINCT FROM '311' THEN RETURN gridex_ediel_ack_guide.prodat_outcomes_v1(raw,source.raw_payload);END IF;
 m.company_id:=source.company_id;m.environment:=source.environment;m.direction:='outbound';m.message_family:='APERAK';m.message_code:='APERAK';m.related_message_id:=source.id;m.raw_payload:=raw;
 PERFORM gridex_ediel_header_negative_birth.assert_ack_v1(m,e);wire:=gridex_ediel_header_negative_birth.source_wire_v1(source);
 RETURN jsonb_build_array(jsonb_build_object('scope','message','reference',wire->>'document','physicalReference',jsonb_build_object('documentId',wire->>'document'),'outcome','negative'));
END $$;

--
-- Name: source_matches_v1(jsonb, jsonb, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.source_matches_v1(a jsonb, s jsonb, source public.ediel_messages) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb:=gridex_ediel_header_negative_birth.evidence_v1(source);app text;
BEGIN
 IF e#>>'{negativeField,fieldCode}' IS DISTINCT FROM '311' THEN RETURN gridex_ack_authority.source_match_v1(a,s);END IF;
 IF s IS DISTINCT FROM gridex_ack_authority.wire_v1(source.raw_payload) OR a->>'family' IS DISTINCT FROM 'APERAK' OR a->>'function' IS DISTINCT FROM '27' OR a->'erc' IS DISTINCT FROM '["41"]'::jsonb THEN RETURN false;END IF;
 app:=gridex_ediel_header_negative_birth.reply_application_v1(source,e);RETURN gridex_ack_authority.source_match_v1(a,jsonb_set(gridex_ediel_header_negative_birth.source_wire_v1(source),'{app}',to_jsonb(app)));
END $$;

--
-- Name: source_wire_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_header_negative_birth; Owner: -
--

CREATE FUNCTION gridex_ediel_header_negative_birth.source_wire_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb:=gridex_ediel_header_negative_birth.evidence_v1(m);classification jsonb;t jsonb;u jsonb;h jsonb;b jsonb;refs jsonb;
BEGIN
 IF e#>>'{negativeField,fieldCode}' IS DISTINCT FROM '311' THEN RETURN gridex_ack_authority.wire_v1(m.raw_payload);END IF;
 classification:=gridex_ediel_header_negative_birth.classify_v1(m.raw_payload);
 IF classification->>'fieldCode' IS DISTINCT FROM '311' THEN RAISE EXCEPTION 'assigned_prodat_negative_reply_source_required';END IF;
 t:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);u:=classification->'originalUNB';
 SELECT x->'elements' INTO STRICT h FROM jsonb_array_elements(t)x WHERE x->>'tag'='UNH';SELECT x->'elements' INTO STRICT b FROM jsonb_array_elements(t)x WHERE x->>'tag'='BGM';
 SELECT jsonb_agg(x#>>'{elements,1,1}' ORDER BY(x->>'index')::int) INTO refs FROM jsonb_array_elements(t)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI';
 -- Missing APP is an original physical fact. This local observation describes
 -- the actual retained wire; only the reply comparison corrects its APP below.
 RETURN jsonb_build_object('sender',u->'sender','receiver',u->'receiver','interchange',u->'interchangeReference','app',NULL,'environment',u->'environment','family','PRODAT','type',h->2,'unhRef',h#>>'{1,0}','code',b#>>'{1,0}','document',b#>>'{2,0}','function',b#>>'{3,0}','legalSender',e#>>'{identities,legalSender,id}','legalReceiver',e#>>'{identities,legalReceiver,id}','refs',jsonb_build_object('LI',refs));
END $$;

--
-- Name: capture(); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE observed timestamptz:=clock_timestamp(); context jsonb:='{}'; status text:='ready'; reason text;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF nullif(NEW.raw_payload,'') IS NULL OR left(NEW.raw_payload,3) NOT IN('UNA','UNB') OR EXISTS(SELECT FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=NEW.id) THEN RETURN NEW; END IF;
 BEGIN context:=gridex_ediel_inbound_context.derive(NEW,observed);
 EXCEPTION WHEN OTHERS THEN status:='held';reason:=CASE WHEN SQLERRM IN('ediel_inbound_legal_context_required','ediel_historical_identity_basis_unavailable') THEN SQLERRM ELSE 'ediel_original_identity_capture_failed' END; END;
 INSERT INTO gridex_ediel_inbound_context.receipts VALUES(NEW.id,NEW.company_id,NEW.environment,NEW.direction,encode(digest(convert_to(NEW.raw_payload,'UTF8'),'sha256'),'hex'),NEW.message_received_at,observed,status,reason,context);
 RETURN NEW;
END $$;

--
-- Name: derive(public.ediel_messages, timestamp with time zone); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.derive(m public.ediel_messages, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;basis jsonb;a jsonb;s jsonb;
BEGIN
 IF m.direction='outbound' AND m.message_family='APERAK' THEN
  SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
  IF source.message_family='UTILTS_ERR' THEN
   basis:=gridex_received_err_response.require_v1(m.company_id,m.environment,source.id);a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
   IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required';END IF;
   RETURN basis->'localContext'||jsonb_build_object('basisKind','prescribed_outbound_ack','originalSourceMessageId',source.id,'originalSourceHash',basis->'sourceHash','direction','outbound','wireFamily','APERAK','wireCode',a->>'code');
  END IF;
 END IF;
 RETURN gridex_ediel_inbound_context.derive_before_received_err_response_v1(m,p_observed_at);
END $$;

--
-- Name: derive_before_received_err_response_v1(public.ediel_messages, timestamp with time zone); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.derive_before_received_err_response_v1(m public.ediel_messages, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE tokens jsonb; family text; code text; reason text; reasons jsonb; own_projection jsonb; edition text; role_key text;
 legal_id text; wire_transport text; application text; test_indicator text; legal_qualifier text; legal_count integer;
 c uuid; candidates uuid[]; actor uuid; role text; roles integer; transport_actor uuid; transport_id text;
 profile public.tenant_ediel_profiles%rowtype; relation public.tenant_counterparty_relations%rowtype;
 source public.ediel_messages%rowtype; basis gridex_ediel_inbound_context.receipts%rowtype; facts jsonb;
BEGIN
 IF m.company_id IS NULL OR m.environment NOT IN('test','production') OR m.direction NOT IN('inbound','outbound') THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH')<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 SELECT x#>>'{elements,2,0}' INTO family FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH';
 SELECT x#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='BGM';
 SELECT x#>>'{elements,7,0}',coalesce(x#>>'{elements,11,0}',''),x#>>ARRAY['elements',CASE WHEN m.direction='inbound' THEN '3' ELSE '2' END,'0'] INTO application,test_indicator,wire_transport FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB';
 IF test_indicator NOT IN('','1') OR m.environment IS DISTINCT FROM (CASE WHEN test_indicator='1' THEN 'test' ELSE 'production' END) OR nullif(wire_transport,'') IS NULL THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 -- An outgoing prescribed ACK inherits the original local recipient's genuine
 -- basis; ordinary E66 receiver roles are never applied to reverse ACK traffic.
 IF m.direction='outbound' AND (family IN('APERAK','CONTRL') OR family='UTILTS' AND code='ERR') THEN
  SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_identity_basis_unavailable'; END IF;
  SELECT * INTO basis FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=source.id;
  IF NOT FOUND OR basis.status<>'ready' OR basis.direction<>'inbound' OR basis.payload_sha256 IS DISTINCT FROM encode(digest(convert_to(source.raw_payload,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION 'ediel_historical_identity_basis_unavailable'; END IF;
  IF wire_transport IS DISTINCT FROM basis.context->>'transportEdielId' OR application IS DISTINCT FROM basis.context->>'applicationReference' THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
  IF family<>'CONTRL' THEN
   legal_qualifier:=CASE WHEN basis.context->>'family'='PRODAT' THEN 'FR' ELSE 'MS' END;
   SELECT count(DISTINCT x#>>'{elements,2,0}'),min(x#>>'{elements,2,0}') INTO legal_count,legal_id FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=legal_qualifier;
   IF legal_count<>1 OR legal_id IS DISTINCT FROM basis.context->>'legalEdielId' THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
  END IF;
  RETURN basis.context||jsonb_build_object('basisKind','prescribed_outbound_ack','originalSourceMessageId',source.id,'originalSourceHash',basis.payload_sha256,'direction','outbound','wireFamily',family,'wireCode',code);
 END IF;
 IF family NOT IN('PRODAT','UTILTS') OR family IS DISTINCT FROM m.message_family OR code IS DISTINCT FROM m.message_code THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 IF family='PRODAT' THEN
  SELECT coalesce(jsonb_agg(DISTINCT cav.token#>>'{elements,1,0}'),'[]') INTO reasons FROM jsonb_array_elements(tokens) WITH ORDINALITY cci(token,n)
   JOIN jsonb_array_elements(tokens) WITH ORDINALITY cav(token,n) ON cav.n=cci.n+1 WHERE cci.token->>'tag'='CCI' AND cci.token#>>'{elements,2,0}'='Z13' AND cav.token->>'tag'='CAV';
  IF jsonb_array_length(reasons)<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;reason:=reasons->>0;
 END IF;
 SELECT e.source_version,p INTO edition,own_projection FROM (SELECT * FROM gridex_ediel_readiness.source_editions ORDER BY recorded_at DESC,source_version LIMIT 1) e CROSS JOIN LATERAL jsonb_array_elements(e.catalog) p
  WHERE p->>'family'=family AND p->>'code'=code AND p->>'transactionReasonCode' IS NOT DISTINCT FROM reason;
 IF own_projection IS NULL OR own_projection->>'direction' NOT IN(m.direction,'both') OR NOT(coalesce(own_projection->'applicationReferences','[]') ? application) THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 role_key:=CASE WHEN m.direction='inbound' THEN 'receiverRoles' ELSE 'senderRoles' END;
 legal_qualifier:=CASE WHEN family='PRODAT' THEN CASE WHEN m.direction='inbound' THEN 'DO' ELSE 'FR' END ELSE CASE WHEN m.direction='inbound' THEN 'MR' ELSE 'MS' END END;
 SELECT count(DISTINCT x#>>'{elements,2,0}'),min(x#>>'{elements,2,0}') INTO legal_count,legal_id FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=legal_qualifier;
 IF legal_count<>1 OR nullif(legal_id,'') IS NULL THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 -- The candidate universe is global and evaluated at the observed DB instant,
 -- not at an editable/backdated message/header timestamp.
 SELECT array_agg(DISTINCT i.company_id) INTO candidates FROM public.tenant_actor_identifiers i WHERE i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=legal_id AND i.valid_from<=p_observed_at AND (i.valid_to IS NULL OR p_observed_at<i.valid_to);
 -- Inbound attribution requires global uniqueness. An authorized outbound
 -- company may share a legal ESCO with another tenant; its OWN profile is still
 -- unique and journal membership is checked by the actual command owner.
 -- Durable global physical reference namespaces prevent source collisions.
 IF m.direction='inbound' THEN
  IF cardinality(candidates) IS DISTINCT FROM 1 OR candidates[1] IS DISTINCT FROM m.company_id THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 ELSE
  IF NOT coalesce(m.company_id=ANY(candidates),false) THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 END IF;c:=m.company_id;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 IF (SELECT count(DISTINCT(i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.valid_from<=p_observed_at AND (i.valid_to IS NULL OR p_observed_at<i.valid_to))<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 SELECT i.actor_id INTO actor FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=legal_id AND i.valid_from<=p_observed_at AND (i.valid_to IS NULL OR p_observed_at<i.valid_to) LIMIT 1;
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=m.environment ORDER BY p.id FOR SHARE;
 IF (SELECT count(*) FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=m.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=p_observed_at AND (p.valid_to IS NULL OR p_observed_at<p.valid_to))<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 SELECT * INTO profile FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=m.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=p_observed_at AND (p.valid_to IS NULL OR p_observed_at<p.valid_to);
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=m.environment AND r.actor_id=actor ORDER BY r.id FOR SHARE;
 SELECT count(DISTINCT r.role_code),min(r.role_code) INTO roles,role FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=m.environment AND r.actor_id=actor AND r.valid_from<=p_observed_at AND (r.valid_to IS NULL OR p_observed_at<r.valid_to)
  AND (own_projection->role_key ? r.role_code OR own_projection->role_key ? CASE r.role_code WHEN 'electricity_supplier' THEN 'supplier' WHEN 'energy_service_company' THEN 'esco' ELSE r.role_code END);
 IF roles<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=m.environment AND r.relation_type='ediel_transport_agent' ORDER BY r.id FOR SHARE;
 IF (SELECT count(*) FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=m.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=p_observed_at AND (r.valid_to IS NULL OR p_observed_at<r.valid_to))>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 SELECT * INTO relation FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=m.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=p_observed_at AND (r.valid_to IS NULL OR p_observed_at<r.valid_to);
 transport_id:=legal_id;transport_actor:=actor;
 IF FOUND THEN
  transport_actor:=relation.counterparty_actor_id;
  PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=transport_actor ORDER BY i.id FOR SHARE;
  IF transport_actor=actor OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=transport_actor AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=p_observed_at::date) AND (i.valid_to IS NULL OR p_observed_at::date<=i.valid_to))<>1 THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
  SELECT i.identifier_value INTO transport_id FROM public.platform_actor_identifiers i WHERE i.actor_id=transport_actor AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=p_observed_at::date) AND (i.valid_to IS NULL OR p_observed_at::date<=i.valid_to) LIMIT 1;
 END IF;
 IF transport_id IS DISTINCT FROM wire_transport THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 facts:=jsonb_build_object('profile',to_jsonb(profile),'identifiers',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=m.environment AND i.actor_id=actor AND i.identifier_type='EdielId' AND i.valid_from<=p_observed_at AND (i.valid_to IS NULL OR p_observed_at<i.valid_to)),
  'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=m.environment AND r.actor_id=actor AND r.role_code=role AND r.valid_from<=p_observed_at AND (r.valid_to IS NULL OR p_observed_at<r.valid_to)),
  'transportRelation',CASE WHEN relation.id IS NULL THEN NULL ELSE to_jsonb(relation) END,'transportIdentifiers',CASE WHEN relation.id IS NULL THEN NULL ELSE (SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.platform_actor_identifiers i WHERE i.actor_id=transport_actor AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=p_observed_at::date) AND (i.valid_to IS NULL OR p_observed_at::date<=i.valid_to)) END);
 RETURN jsonb_build_object('basisKind','observed_source_persistence','companyId',c,'environment',m.environment,'direction',m.direction,'family',family,'code',code,'subtype',own_projection->'subtype','legalActorId',actor,'legalEdielId',legal_id,'actorRole',role,'transportActorId',transport_actor,'transportEdielId',transport_id,'applicationReference',application,'sourceEdition',edition,'canonicalProjection',own_projection,'observedAt',p_observed_at,'sourceReceivedAt',m.message_received_at,'facts',facts);
END $$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_original_identity_basis_immutable'; END $$;

--
-- Name: require_ack_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.require_ack_v1(ack public.ediel_messages, source public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE context jsonb; tokens jsonb; receiver text;
BEGIN
 IF ack.direction IS DISTINCT FROM 'inbound' OR source.direction IS DISTINCT FROM 'outbound' OR ack.company_id IS DISTINCT FROM source.company_id OR ack.environment IS DISTINCT FROM source.environment THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 context:=gridex_ediel_inbound_context.require_v1(source.company_id,source.id);
 -- Complete physical ACK family/party/reference/global uniqueness qualification
 -- is owned by gridex_ack_authority; this guard adds genuine original rolebasis.
 tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
 SELECT x#>>'{elements,3,0}' INTO receiver FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB';
 IF receiver IS DISTINCT FROM context->>'transportEdielId' THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 RETURN context||jsonb_build_object('basisKind','qualified_outbound_original_ack','ackMessageId',ack.id,'originalSourceMessageId',source.id);
END $$;

--
-- Name: require_before_received_err_response_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.require_before_received_err_response_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE m public.ediel_messages%rowtype; basis gridex_ediel_inbound_context.receipts%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 SELECT * INTO basis FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=m.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_identity_basis_unavailable'; END IF;
 IF basis.status<>'ready' OR basis.company_id IS DISTINCT FROM m.company_id OR basis.environment IS DISTINCT FROM m.environment OR basis.direction IS DISTINCT FROM m.direction
  OR basis.source_received_at IS DISTINCT FROM m.message_received_at OR basis.payload_sha256 IS DISTINCT FROM encode(digest(convert_to(m.raw_payload,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 RETURN basis.context;
END $$;

--
-- Name: require_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.require_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;basis jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id;
 IF m.direction='inbound' AND m.message_family='UTILTS_ERR' AND EXISTS(SELECT FROM gridex_received_err_response.receipts WHERE source_message_id=m.id) THEN
  basis:=gridex_received_err_response.require_v1(p_company_id,m.environment,m.id);RETURN basis->'localContext';
 END IF;
 RETURN gridex_ediel_inbound_context.require_before_received_err_response_v1(p_company_id,p_message_id);
END $$;

--
-- Name: authorize_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_inbound_receptions; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_receptions.authorize_v1(c uuid, actor uuid, permission text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM x.user_id FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR permission IS NULL OR permission NOT IN('communication.write','communication.read')
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=c AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
  OR (CASE permission WHEN 'communication.read' THEN coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.read'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false)
   ELSE coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false) END) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_reception_actor_forbidden' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: capture_technical_mailbox_birth_v1(); Type: FUNCTION; Schema: gridex_ediel_inbound_receptions; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_receptions.capture_technical_mailbox_birth_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE mail public.inbound_email_messages%rowtype;box public.ediel_mailboxes%rowtype;
BEGIN
 IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'gridex_unattributed_intake' OR TG_TABLE_NAME<>'raw_births'
 THEN RAISE EXCEPTION 'ediel_original_mailbox_birth_owner_required';END IF;
 SELECT * INTO mail FROM public.inbound_email_messages WHERE id=NEW.inbound_email_message_id FOR SHARE;
 SELECT * INTO box FROM public.ediel_mailboxes WHERE id=mail.mailbox_id FOR SHARE;
 -- Missing SMTP holds the later return route, not storage of original mail.
 IF mail.id IS NULL OR box.id IS NULL OR (mail.environment IN ('test','production')) IS NOT TRUE
  OR box.environment IS DISTINCT FROM mail.environment OR box.is_active IS NOT TRUE
  OR NEW.snapshot_hash IS DISTINCT FROM gridex_unattributed_intake.raw_hash_v1(mail)
  OR box.email_address IS NULL OR btrim(box.email_address)!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
 THEN RETURN NEW;END IF;
 INSERT INTO gridex_ediel_inbound_receptions.technical_mailbox_births(
  inbound_email_message_id,raw_snapshot_hash,mailbox_id,environment,mailbox_company_id,mailbox_shared,smtp_address,observed_at)
 VALUES(mail.id,NEW.snapshot_hash,box.id,mail.environment,box.company_id,box.is_shared_platform_mailbox,btrim(box.email_address),NEW.observed_at);
 RETURN NEW;
END $_$;

--
-- Name: guard_original_v1(); Type: FUNCTION; Schema: gridex_ediel_inbound_receptions; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_receptions.guard_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT FROM gridex_ediel_inbound_receptions.receptions r WHERE r.source_message_id=OLD.id)
  AND (TG_OP='DELETE' OR
   (NEW.company_id,NEW.environment,NEW.direction,NEW.message_standard,NEW.message_family,NEW.message_code,NEW.raw_payload,NEW.sender_ediel_id,NEW.receiver_ediel_id,NEW.application_reference,NEW.interchange_reference,NEW.message_received_at,NEW.mailbox_message_id)
   IS DISTINCT FROM
   (OLD.company_id,OLD.environment,OLD.direction,OLD.message_standard,OLD.message_family,OLD.message_code,OLD.raw_payload,OLD.sender_ediel_id,OLD.receiver_ediel_id,OLD.application_reference,OLD.interchange_reference,OLD.message_received_at,OLD.mailbox_message_id))
 THEN RAISE EXCEPTION 'ediel_registered_reception_original_immutable';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

--
-- Name: receptions; Type: TABLE; Schema: gridex_ediel_inbound_receptions; Owner: -
--

CREATE TABLE gridex_ediel_inbound_receptions.receptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    inbound_email_message_id uuid NOT NULL,
    parse_result_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    environment text NOT NULL,
    canonical_payload_hash text NOT NULL,
    received_payload_hash text NOT NULL,
    received_at timestamp with time zone NOT NULL,
    classification text NOT NULL,
    scope jsonb NOT NULL,
    transport_source_snapshot jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT receptions_classification_check CHECK ((classification = ANY (ARRAY['first_reception'::text, 'protocol_duplicate'::text, 'identity_conflict'::text]))),
    CONSTRAINT receptions_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text])))
);

ALTER TABLE ONLY gridex_ediel_inbound_receptions.receptions FORCE ROW LEVEL SECURITY;

--
-- Name: result_v1(gridex_ediel_inbound_receptions.receptions, boolean); Type: FUNCTION; Schema: gridex_ediel_inbound_receptions; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_receptions.result_v1(r gridex_ediel_inbound_receptions.receptions, replay boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT jsonb_build_object('companyId',r.company_id,'sourceMessageId',r.source_message_id,'inboundEmailMessageId',r.inbound_email_message_id,'parseResultId',r.parse_result_id,'receptionId',r.id,'classification',r.classification,'isReplay',replay,'receivedAt',r.received_at,'canonicalPayloadHash',r.canonical_payload_hash,'receivedPayloadHash',r.received_payload_hash,'responseRequestId',q.id,'status',CASE WHEN q.id IS NULL THEN 'observed' ELSE 'held' END,'reason',q.reason,'businessEffectAuthorized',false) FROM (SELECT 1) single LEFT JOIN gridex_ediel_inbound_receptions.response_requests q ON q.reception_id=r.id$$;

