--
-- Name: assert_message_before_native_ack_guide_v1(public.ediel_messages, gridex_ediel_outbound_owner.witnesses); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.assert_message_before_native_ack_guide_v1(m public.ediel_messages, w gridex_ediel_outbound_owner.witnesses) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF m.company_id IS DISTINCT FROM w.company_id OR m.environment IS DISTINCT FROM w.environment OR m.direction IS DISTINCT FROM 'outbound'
  OR m.message_family IS DISTINCT FROM w.family OR gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code) IS DISTINCT FROM gridex_ediel_transport.canonical_message_code_v1(w.family,w.code) OR m.related_message_id IS DISTINCT FROM w.related_message_id
  OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM w.payload_sha256
  OR m.canonical_rule_pack_id::text IS DISTINCT FROM w.evidence->>'rulePackId' OR m.rule_profile_version_id::text IS DISTINCT FROM w.evidence->>'messageProfileId'
  OR m.rule_profile_key IS DISTINCT FROM w.evidence->>'profileKey' OR m.rule_profile_version IS DISTINCT FROM w.evidence->>'version' OR m.rule_pack_checksum IS DISTINCT FROM w.evidence->>'sourceHash'
  OR m.rule_pack_snapshot->>'profileKey' IS DISTINCT FROM w.evidence->>'profileKey' OR m.rule_pack_snapshot->>'profileVersionId' IS DISTINCT FROM w.evidence->>'messageProfileId'
  OR m.rule_pack_snapshot#>'{rulePack}' IS DISTINCT FROM w.evidence#>'{snapshot,rulePack}'
  OR m.rule_pack_snapshot#>'{messageProfile}' IS DISTINCT FROM w.evidence#>'{snapshot,messageProfile}'
  OR m.rule_pack_snapshot#>'{guideSources}' IS DISTINCT FROM w.evidence#>'{snapshot,guideSources}'
  OR m.rule_pack_snapshot->>'version' IS DISTINCT FROM w.evidence->>'version' OR m.rule_pack_snapshot->>'checksum' IS DISTINCT FROM w.evidence->>'sourceHash' THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_scope_invalid';END IF;
END $$;

--
-- Name: assert_message_before_utilts_err_source_v1(public.ediel_messages, gridex_ediel_outbound_owner.witnesses); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.assert_message_before_utilts_err_source_v1(m public.ediel_messages, w gridex_ediel_outbound_owner.witnesses) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN PERFORM gridex_ediel_outbound_owner.assert_message_before_native_ack_guide_v1(m,w);PERFORM gridex_ediel_ack_guide.require_v1(m);END $$;

--
-- Name: assert_message_v1(public.ediel_messages, gridex_ediel_outbound_owner.witnesses); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.assert_message_v1(m public.ediel_messages, w gridex_ediel_outbound_owner.witnesses) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN PERFORM gridex_ediel_outbound_owner.assert_message_before_utilts_err_source_v1(m,w);PERFORM gridex_ediel_outbound_owner.require_utilts_err_source_v1(m,false);END $$;

--
-- Name: assert_preparation_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.assert_preparation_v1(i jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(i->>'companyId')::uuid;actor uuid:=(i->>'actorUserId')::uuid;
 env text:=i->>'environment';raw text:=i->>'rawPayload';positive uuid:=(i->>'sourceQualifiedPositiveFixtureWitnessId')::uuid;
 negative uuid:=(i->>'sourceQualifiedNegativeFixtureWitnessId')::uuid;q jsonb;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 THEN RAISE EXCEPTION 'ediel_outbound_owner_actor_scope_required' USING ERRCODE='42501';END IF;
 IF public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE THEN RETURN;END IF;
 IF env IS DISTINCT FROM 'test' OR public.gridex_actor_has_company_permission(actor,c,'ediel_testing.write') IS NOT TRUE
  OR (positive IS NULL)=(negative IS NULL) THEN RAISE EXCEPTION 'ediel_outbound_owner_preparation_permission_required' USING ERRCODE='42501';END IF;
 -- Caller IDs are selectors only. The source owner rechecks actual registered
 -- original, run/role/case/revision/step/bytes, exact preparer and current scope.
 IF positive IS NOT NULL THEN q:=gridex_negative_fixtures.prepared_positive_fixture_v1(c,positive,raw,actor);
 ELSE q:=gridex_negative_fixtures.prepared_negative_fixture_v1(c,negative,raw,actor);END IF;
 IF q IS NULL OR q->>'companyId' IS DISTINCT FROM c::text OR q->'authorizesBusinessEffect' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'ediel_outbound_owner_preparation_fixture_required';END IF;
END $$;

--
-- Name: consume(); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.consume() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w gridex_ediel_outbound_owner.witnesses%rowtype;prior gridex_ediel_outbound_owner.consumptions%rowtype;token uuid;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF NEW.direction='outbound' AND NEW.message_family='APERAK' AND NEW.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId' THEN
  PERFORM gridex_ediel_common_header.consume_v1(NEW);PERFORM gridex_ediel_ack_guide.require_v1(NEW);RETURN NEW;
 END IF;
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family NOT IN('PRODAT','UTILTS','APERAK','UTILTS_ERR') OR nullif(NEW.raw_payload,'') IS NULL THEN RETURN NEW;END IF;
 token:=(NEW.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;
 SELECT * INTO w FROM gridex_ediel_outbound_owner.witnesses WHERE id=token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 PERFORM gridex_ediel_outbound_owner.assert_message_v1(NEW,w);
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(NEW,false);
 SELECT * INTO prior FROM gridex_ediel_outbound_owner.consumptions WHERE witness_id=w.id;
 IF FOUND THEN
  IF prior.source_message_id IS DISTINCT FROM NEW.id THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_already_consumed';END IF;
  RETURN NEW;
 END IF;
 -- The same INSERT transaction owns both actual immutable physical message
 -- scope and one-use protected witness consumption. Failure rolls back both.
 INSERT INTO gridex_ediel_outbound_owner.consumptions VALUES(w.id,NEW.id,w.company_id,w.environment,w.payload_sha256);
 RETURN NEW;
END $$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN RAISE EXCEPTION 'ediel_outbound_owner_witness_immutable';END $$;

--
-- Name: prepare_before_bilateral_prodat_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_bilateral_prodat_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(p_input->>'rawPayload');
 RETURN gridex_ediel_outbound_owner.prepare_before_fresh_ack_envelope_v1(p_input);
END $$;

--
-- Name: prepare_before_fresh_ack_envelope_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_fresh_ack_envelope_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb;facet jsonb;result jsonb;source public.ediel_messages%rowtype;f gridex_received_sources.prodat_response_facets%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;final_facet jsonb;positive_indices integer[];actual jsonb;
BEGIN
 a:=gridex_ack_authority.wire_v1(i->>'rawPayload');
 IF a->>'family'='APERAK' AND a#>>'{type,2}'='96A' AND a#>>'{type,4}'='E2SE6A' THEN
  PERFORM src.source_message_id FROM gridex_received_sources.sources src WHERE src.source_message_id=(i->>'relatedMessageId')::uuid AND src.company_id=(i->>'companyId')::uuid AND src.environment=i->>'environment' FOR UPDATE;
  SELECT * INTO source FROM public.ediel_messages WHERE id=(i->>'relatedMessageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='inbound' AND message_family='PRODAT' FOR SHARE;
  IF source.id IS NULL THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
  IF source.message_code IN('Z04','Z05','Z14','Z15') THEN facet:=gridex_received_sources.prodat_structural_response_v1(source.company_id,source.id,NULL);
  ELSE IF source.message_code IN('Z06','Z10') AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=source.id) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=source.id) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=source.id AND v.company_id=source.company_id AND v.environment=source.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN facet:=gridex_received_sources.prodat_structural_response_v1(source.company_id,source.id,NULL);END IF; END IF;
  IF facet IS NULL THEN facet:=gridex_received_sources.require_prodat_responses_v1(source.company_id,source.id);END IF;
  actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(i->>'rawPayload',facet->'objects');
  SELECT array_agg((x->>'lineIndex')::integer ORDER BY(x->>'lineIndex')::integer) INTO positive_indices FROM jsonb_array_elements(actual)x WHERE x->>'ercCode'='100';
  IF positive_indices IS NOT NULL AND source.message_code IN('Z04','Z05','Z14','Z15') THEN
   final_facet:=gridex_received_sources.prodat_structural_response_v1(source.company_id,source.id,positive_indices);
   IF final_facet IS NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_required';END IF;
  ELSE IF positive_indices IS NOT NULL AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=source.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=source.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=source.id AND v.company_id=source.company_id AND v.environment=source.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN final_facet:=gridex_received_sources.prodat_structural_response_v1(source.company_id,source.id,positive_indices);END IF; END IF;
 END IF;
 result:=gridex_ediel_outbound_owner.prepare_before_prodat_response_plan_v1(i);
 IF facet IS NOT NULL THEN
  SELECT * INTO f FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=(facet->>'assessmentId')::uuid;
  SELECT * INTO w FROM gridex_ediel_outbound_owner.witnesses WHERE id=(result->>'witnessId')::uuid;
  IF w.id IS NULL OR w.company_id IS DISTINCT FROM source.company_id OR w.environment IS DISTINCT FROM source.environment OR w.related_message_id IS DISTINCT FROM source.id OR w.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(i->>'rawPayload','UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
  INSERT INTO gridex_ediel_ack_guide.prodat_response_owner_bindings VALUES(w.id,f.assessment_id,source.id,w.company_id,w.environment,w.payload_sha256,f.response_facts_hash);
  IF final_facet IS NOT NULL THEN INSERT INTO gridex_ediel_ack_guide.prodat_structural_response_bindings VALUES(w.id,source.id,w.company_id,w.environment,w.payload_sha256,final_facet::text,encode(sha256(convert_to(final_facet::text,'UTF8')),'hex'));END IF;
 END IF;
 RETURN result;
END $$;

--
-- Name: prepare_before_national_rescission_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_national_rescission_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF gridex_ediel_ack_guide.unused_unh_violation_v1(i->>'rawPayload') THEN
  PERFORM gridex_ediel_ack_guide.require_unused_unh_v1(i->>'rawPayload','outbound',gridex_ediel_ack_guide.prepared_reference_fixture_v1(i));END IF;
 RETURN gridex_ediel_outbound_owner.prepare_before_unused_unh_v1(i);END $$;

--
-- Name: prepare_before_native_ack_guide_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_native_ack_guide_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid;actor uuid;env text;raw text;related uuid;m public.ediel_messages%rowtype;context jsonb;tokens jsonb;
 p public.ediel_message_profiles%rowtype;r public.ediel_rule_packs%rowtype;named_sources jsonb;e jsonb;witness uuid;original public.ediel_messages%rowtype;observed timestamptz:=clock_timestamp();business_date date;
BEGIN
 business_date:=(observed AT TIME ZONE 'Europe/Stockholm')::date;
 c:=(i->>'companyId')::uuid;actor:=(i->>'actorUserId')::uuid;env:=i->>'environment';raw:=i->>'rawPayload';related:=(i->>'relatedMessageId')::uuid;e:=i->'rulePackEvidence';
 IF c IS NULL OR actor IS NULL OR env IS NULL OR env NOT IN('test','production') OR nullif(raw,'') IS NULL OR octet_length(raw)>8388608 OR jsonb_typeof(e) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
 PERFORM gridex_ediel_outbound_owner.assert_preparation_v1(i);
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
 SELECT t#>>'{elements,2,0}' INTO m.message_family FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';
 SELECT t#>>'{elements,1,0}' INTO m.message_code FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 m.message_code:=gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code);
 IF m.message_family='UTILTS' AND m.message_code='ERR' THEN m.message_family:='UTILTS_ERR';END IF;
 IF m.message_family NOT IN('PRODAT','UTILTS','APERAK','UTILTS_ERR') THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
 m.company_id:=c;m.environment:=env;m.direction:='outbound';m.raw_payload:=raw;m.related_message_id:=related;
 -- Reuse the single source-generated legal/transport/role authority. This
 -- prospective read grants no historical receipt or market activation.
 context:=gridex_ediel_inbound_context.derive(m,observed);
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(m,false);
 IF context->>'basisKind'='prescribed_outbound_ack' THEN
  SELECT * INTO original FROM public.ediel_messages WHERE id=related AND company_id=c AND environment=env AND direction='inbound' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable';END IF;
  IF e IS DISTINCT FROM gridex_ediel_source_rules.require_v1(c,original.id) THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
 ELSE
  SELECT * INTO p FROM public.ediel_message_profiles WHERE id::text=e->>'messageProfileId' AND profile_key=e->>'profileKey' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
  SELECT * INTO r FROM public.ediel_rule_packs WHERE id=p.rule_pack_id AND id::text=e->>'rulePackId' AND source_hash=e->>'sourceHash' FOR SHARE;
  IF NOT FOUND OR e->>'version' IS DISTINCT FROM r.guide_version||':r'||r.guide_revision OR nullif(e->>'version','') IS NULL
   OR e#>'{snapshot,rulePack}' IS DISTINCT FROM to_jsonb(r) OR e#>'{snapshot,messageProfile}' IS DISTINCT FROM to_jsonb(p)
   OR r.market IS DISTINCT FROM 'electricity' OR r.family IS DISTINCT FROM m.message_family OR gridex_ediel_source_rules.pack_effective_v1(r.id,'outbound',business_date) IS NOT TRUE
   OR NOT p.is_enabled OR p.message_code IS DISTINCT FROM m.message_code OR p.direction NOT IN('outbound','both') OR coalesce(p.transaction_subtype,'') IS DISTINCT FROM coalesce(context->>'subtype','') THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
  PERFORM s.id FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=r.id ORDER BY s.id FOR SHARE;
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO named_sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=r.id;
  IF e#>'{snapshot,guideSources}' IS DISTINCT FROM named_sources THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_required';END IF;
 END IF;
 -- Source-facing snapshot fields are a projection of this exact owner witness;
 -- they cannot be replaced by independently matching mutable public columns.
 e:=e||jsonb_build_object('snapshot',(e->'snapshot')||jsonb_build_object('profileKey',e->>'profileKey','profileVersionId',e->>'messageProfileId','version',e->>'version','checksum',e->>'sourceHash'));
 INSERT INTO gridex_ediel_outbound_owner.witnesses(company_id,actor_user_id,environment,payload_sha256,family,code,related_message_id,context,evidence)
  VALUES(c,actor,env,encode(sha256(convert_to(raw,'UTF8')),'hex'),m.message_family,m.message_code,related,context,e) RETURNING id INTO witness;
 RETURN jsonb_build_object('version',1,'witnessId',witness,'evidence',e);
END $$;

--
-- Name: prepare_before_preparation_permission_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_preparation_permission_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;tokens jsonb;
BEGIN
 tokens:=gridex_utilts_binding.wire_tokens_v1(p_input->>'rawPayload');SELECT x#>>'{elements,2,0}' INTO m.message_family FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH';
 IF m.message_family IN('APERAK','CONTRL') THEN m.company_id:=(p_input->>'companyId')::uuid;m.environment:=p_input->>'environment';m.direction:='outbound';m.raw_payload:=p_input->>'rawPayload';m.related_message_id:=(p_input->>'relatedMessageId')::uuid;PERFORM gridex_ediel_ack_guide.require_v1(m);END IF;
 RETURN gridex_ediel_outbound_owner.prepare_before_native_ack_guide_v1(p_input);
END $$;

--
-- Name: prepare_before_prodat_response_plan_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_prodat_response_plan_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a jsonb;
BEGIN a:=gridex_ack_authority.wire_v1(p_input->>'rawPayload');IF a->>'family'='UTILTS' AND a->>'code'='ERR' THEN m.company_id:=(p_input->>'companyId')::uuid;m.environment:=p_input->>'environment';m.direction:='outbound';m.message_family:='UTILTS_ERR';m.message_code:='ERR';m.raw_payload:=p_input->>'rawPayload';m.related_message_id:=(p_input->>'relatedMessageId')::uuid;PERFORM gridex_ediel_ack_guide.require_v1(m);END IF;RETURN gridex_ediel_outbound_owner.prepare_before_registered_responses_v1(p_input);END $$;

--
-- Name: prepare_before_prodat_unused_document_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_prodat_unused_document_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_bilateral_prodat.outbound_operations%rowtype;own jsonb;
BEGIN
 IF gridex_bilateral_prodat.outbound_required_v1(p_input->>'rawPayload') IS TRUE THEN
  PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
  SELECT * INTO o FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=(p_input->>'bilateralOriginalMessageId')::uuid AND company_id=(p_input->>'companyId')::uuid;
  IF o.message_id IS NULL OR o.creation_txid IS DISTINCT FROM txid_current() OR o.actor_user_id::text IS DISTINCT FROM p_input->>'actorUserId' OR o.environment IS DISTINCT FROM p_input->>'environment' OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(p_input->>'rawPayload','UTF8')),'hex')
   OR o.capability IS DISTINCT FROM gridex_bilateral_prodat.outbound_capability_v1(o.company_id,o.actor_user_id,o.environment,p_input->>'rawPayload') THEN RAISE EXCEPTION 'bilateral_prodat_outbound_atomic_original_required';END IF;
  FOR own IN SELECT x FROM jsonb_array_elements(o.capability->'objects')x LOOP
   IF own->>'rulePackId' IS DISTINCT FROM p_input#>>'{rulePackEvidence,rulePackId}' OR own->>'messageProfileId' IS DISTINCT FROM p_input#>>'{rulePackEvidence,messageProfileId}' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_captured_source_grammar_required';END IF;
  END LOOP;
 END IF;
 RETURN gridex_ediel_outbound_owner.prepare_before_bilateral_prodat_v1(p_input);
END$$;

