-- Name: prepare_before_unused_unh_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_unused_unh_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF gridex_ediel_ack_guide.message_reference_profile_violation_v1(i->>'rawPayload') THEN
  PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(i->>'rawPayload',gridex_ediel_ack_guide.prepared_reference_fixture_v1(i));END IF;
 RETURN gridex_ediel_outbound_owner.prepare_before_reference_profile_v1(i);END $$;

--
-- Name: prepare_before_utilts_err_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_before_utilts_err_source_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 -- Qualify the executor before the preserved ACK/source/private history read.
 PERFORM gridex_ediel_outbound_owner.assert_preparation_v1(p_input);
 RETURN gridex_ediel_outbound_owner.prepare_before_preparation_permission_v1(p_input);
END $$;

--
-- Name: prepare_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.prepare_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_supply_rescission.outbound_operations%rowtype;own jsonb;BEGIN
 IF gridex_ediel_duplicate_responses.allows_message_v1(jsonb_populate_record(NULL::public.ediel_messages,jsonb_build_object('direction','outbound','message_family','APERAK','company_id',p_input->>'companyId','environment',p_input->>'environment','related_message_id',p_input->>'relatedMessageId','raw_payload',p_input->>'rawPayload'))) THEN
  PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(p_input->>'rawPayload','APERAK');PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(p_input->>'rawPayload');
  RETURN gridex_ediel_outbound_owner.prepare_before_prodat_response_plan_v1(p_input);END IF;
 IF gridex_supply_rescission.outbound_required_v1(p_input->>'rawPayload') IS TRUE THEN
  PERFORM gridex_supply_rescission.lock_original_v1();SELECT * INTO o FROM gridex_supply_rescission.outbound_operations WHERE message_id=(p_input->>'nationalOriginalMessageId')::uuid AND company_id=(p_input->>'companyId')::uuid;
  IF o.message_id IS NULL OR o.creation_txid IS DISTINCT FROM txid_current() OR o.actor_user_id::text IS DISTINCT FROM p_input->>'actorUserId' OR o.environment IS DISTINCT FROM p_input->>'environment' OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(p_input->>'rawPayload','UTF8')),'hex') OR o.capability IS DISTINCT FROM gridex_supply_rescission.outbound_capability_v1(o.company_id,o.actor_user_id,o.environment,p_input->>'rawPayload',o.mandate_id) THEN RAISE EXCEPTION 'supply_rescission_atomic_original_required';END IF;
  own:=o.capability#>'{objects,0}';IF own->>'rulePackId' IS DISTINCT FROM p_input#>>'{rulePackEvidence,rulePackId}' OR own->>'messageProfileId' IS DISTINCT FROM p_input#>>'{rulePackEvidence,messageProfileId}' THEN RAISE EXCEPTION 'supply_rescission_actual_selected_source_grammar_required';END IF;
 END IF;RETURN gridex_ediel_outbound_owner.prepare_before_national_rescission_v1(p_input);
END$$;

--
-- Name: require_positive_before_received_err_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_positive_before_received_err_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;s jsonb;groups jsonb;g jsonb;code text;transaction_id text;header_scope boolean;expected_header jsonb;actual_header jsonb;reservation public.ediel_ack_transaction_results%rowtype;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'UTILTS' THEN RETURN;END IF;
 -- Reuse the one native physical ACK lexical/scope projector. The added own
 -- ERC groups never select policy, decide business acceptance or invent codes.
 a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a#>>'{type,1}' IS DISTINCT FROM 'D' OR a#>>'{type,2}' IS DISTINCT FROM '04A' OR a#>>'{type,3}' IS DISTINCT FROM 'UN' OR a#>>'{type,4}' IS DISTINCT FROM 'E5SE5A'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
 code:=a->>'code';groups:=a->'ercGroups';
 IF code IS NULL OR code NOT IN('312','313') OR jsonb_typeof(groups) IS DISTINCT FROM 'array' OR jsonb_array_length(groups)=0
  OR (jsonb_array_length(groups)<>jsonb_array_length(coalesce(a#>'{refs,ACW}','[]')) AND NOT(code='313' AND jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))=0)) OR jsonb_array_length(groups)<>jsonb_array_length(coalesce(a#>'{refs,DM}','[]'))
  OR EXISTS(SELECT x FROM jsonb_array_elements_text(coalesce(a#>'{refs,DM}','[]'))x GROUP BY x HAVING count(*)>1)
  OR (code='312' AND EXISTS(SELECT x FROM jsonb_array_elements_text(coalesce(a#>'{refs,ACW}','[]'))x GROUP BY x HAVING count(*)>1)) THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
 header_scope:=code='313' AND jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))=0;
 IF header_scope THEN
  expected_header:=gridex_received_sources.require_utilts_header_v1(m.company_id,source.id);
  IF EXISTS(SELECT FROM jsonb_array_elements(groups)x WHERE jsonb_array_length(coalesce(x->'texts','[]'))<>1) THEN RAISE EXCEPTION 'utilts_header_ack_owner_unavailable';END IF;
  SELECT jsonb_agg(row ORDER BY row::text) INTO actual_header FROM (SELECT jsonb_build_object('ercCode',x->>'code','fieldCode',x#>>'{texts,0,3,0}','text',x#>>'{texts,0,4,0}') row FROM jsonb_array_elements(groups)x) own_errors;
  SELECT jsonb_agg(x ORDER BY x::text) INTO expected_header FROM jsonb_array_elements(expected_header->'applicationErrors')x;
  IF actual_header IS DISTINCT FROM expected_header THEN RAISE EXCEPTION 'utilts_header_ack_owner_unavailable';END IF;
 END IF;
 FOR g IN SELECT x FROM jsonb_array_elements(groups)x LOOP
  IF nullif(g->>'code','') IS NULL OR (code='312' AND g->>'code' IS DISTINCT FROM '100') OR (code='313' AND g->>'code'='100')
   OR jsonb_array_length(g->'acw')<>(CASE WHEN header_scope THEN 0 ELSE 1 END) OR jsonb_array_length(g->'dm')<>1 OR (NOT header_scope AND nullif(g#>>'{acw,0}','') IS NULL) OR nullif(g#>>'{dm,0}','') IS NULL OR length(g#>>'{dm,0}')>(gridex_ediel_ack_guide.utilts_reference_constraints_v1()->>'ownDmMax')::integer OR btrim(g#>>'{dm,0}') IS DISTINCT FROM g#>>'{dm,0}' THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
  IF header_scope THEN CONTINUE;END IF;
  transaction_id:=g#>>'{acw,0}';
  IF code='312' THEN
   PERFORM public.gridex_require_utilts_positive_ack_authority_v1(m.company_id,m.environment,source.id,transaction_id,
    CASE WHEN p_sending THEN m.id ELSE NULL END,CASE WHEN p_sending THEN m.raw_payload ELSE NULL END);
  ELSE
   -- A negative own-IDE response cannot replace an already established positive
   -- storage/ACK result or bypass its own immutable planned/final reservation.
   SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=source.id AND source_transaction_id=transaction_id FOR SHARE;
   IF NOT FOUND OR reservation.planned_response_type IS DISTINCT FROM 'negative_aperak' OR reservation.disposition='accepted'
    OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'negative_aperak')
    OR (p_sending AND (reservation.final_response_type IS DISTINCT FROM 'negative_aperak' OR reservation.response_message_id IS DISTINCT FROM m.id OR reservation.finalized_at IS NULL)) THEN RAISE EXCEPTION 'utilts_negative_ack_reservation_unavailable';END IF;
  END IF;
 END LOOP;
END $$;

--
-- Name: require_positive_utilts_ack_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;s jsonb;groups jsonb;g jsonb;ids text[]:='{}';dms text[]:='{}';tx text;dm text;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN PERFORM gridex_ediel_outbound_owner.require_positive_before_received_err_v1(m,p_sending);RETURN;END IF;
 a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);groups:=a->'ercGroups';
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a->>'code' IS DISTINCT FROM '312' OR a#>>'{type,2}' IS DISTINCT FROM '04A' OR a#>>'{type,4}' IS DISTINCT FROM 'E5SE5A'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) OR jsonb_typeof(groups) IS DISTINCT FROM 'array' OR jsonb_array_length(groups)=0 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 FOR g IN SELECT x FROM jsonb_array_elements(groups)x LOOP
  tx:=g#>>'{acw,0}';dm:=g#>>'{dm,0}';
  IF g->>'code' IS DISTINCT FROM '100' OR jsonb_array_length(g->'acw')<>1 OR jsonb_array_length(g->'dm')<>1 OR nullif(tx,'') IS NULL OR nullif(dm,'') IS NULL OR length(dm)>(gridex_ediel_ack_guide.utilts_reference_constraints_v1()->>'ownDmMax')::integer OR tx=ANY(ids) OR dm=ANY(dms) THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
  ids:=array_append(ids,tx);dms:=array_append(dms,dm);
  PERFORM public.gridex_require_utilts_positive_ack_authority_v1(m.company_id,m.environment,source.id,tx,CASE WHEN p_sending THEN m.id ELSE NULL END,CASE WHEN p_sending THEN m.raw_payload ELSE NULL END);
 END LOOP;
END $$;

--
-- Name: require_utilts_err_source_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_utilts_err_source_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;tokens jsonb;a jsonb;s jsonb;facet jsonb;own_facet jsonb;
 t jsonb;sts jsonb;reference jsonb;original_reference jsonb;group_start integer;group_end integer;
 transaction_id text;national_code text;own_id text;count_refs integer;seen text[]:='{}';own_ids text[]:='{}';
 reservation public.ediel_ack_transaction_results%rowtype;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.id IS NULL OR source.message_family IS DISTINCT FROM 'UTILTS' THEN RAISE EXCEPTION 'utilts_err_own_source_unavailable';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 IF tokens IS NULL OR a IS NULL OR s IS NULL OR a->>'family' IS DISTINCT FROM 'UTILTS' OR a->>'code' IS DISTINCT FROM 'ERR'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'utilts_err_own_source_unavailable';END IF;
 facet:=gridex_received_sources.require_utilts_functional_responses_v1(m.company_id,source.id);
 IF NOT coalesce(facet->>'version' IN('1','2'),false) OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR jsonb_typeof(facet->'transactions') IS DISTINCT FROM 'array'
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE')=0 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE' ORDER BY(x->>'index')::int LOOP
  group_start:=(t->>'index')::int;SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>group_start AND x->>'tag' IN('IDE','UNT','UNZ');
  own_id:=t#>>'{elements,2,0}';
  IF t#>>'{elements,1,0}' IS DISTINCT FROM '24' OR nullif(own_id,'') IS NULL OR own_id=ANY(own_ids) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;own_ids:=array_append(own_ids,own_id);
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'='E01' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x->'elements' INTO sts FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'='E01' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  national_code:=sts#>>'{3,0}';
  IF sts->1 IS DISTINCT FROM '["E01","","260"]'::jsonb OR sts->2 IS DISTINCT FROM '["41"]'::jsonb OR sts->3 IS DISTINCT FROM jsonb_build_array(national_code,'','260') OR jsonb_array_length(sts)>4 OR nullif(national_code,'') IS NULL THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='TN' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x#>'{elements,1}' INTO reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='TN' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  transaction_id:=reference->>1;
  IF reference IS DISTINCT FROM jsonb_build_array('TN',transaction_id) OR nullif(transaction_id,'') IS NULL OR NOT coalesce(s->'ide','[]') ? transaction_id OR (transaction_id||'|'||national_code)=ANY(seen) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;seen:=array_append(seen,transaction_id||'|'||national_code);
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x#>'{elements,1}' INTO original_reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF original_reference IS DISTINCT FROM jsonb_build_array(s->>'code',s->>'document') THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(facet->'transactions')x WHERE x->>'transactionId'=transaction_id;IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x INTO own_facet FROM jsonb_array_elements(facet->'transactions')x WHERE x->>'transactionId'=transaction_id;
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(own_facet->'errors')x WHERE x->>'code'=national_code AND (
    (facet->>'version'='1' AND x->>'referenceQualifier'='TN' AND x->>'referenceNumber'=transaction_id)
    OR (facet->>'version'='2' AND x->'responseReference'=jsonb_build_object('qualifier','TN','number',transaction_id) AND (
      (x->>'originalScope'='transaction' AND x->>'referenceQualifier'='TN' AND x->>'referenceNumber'=transaction_id)
      OR (x->>'originalScope'='message' AND x->'referenceNumber'='null'::jsonb)
    ))
  )) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=source.id AND source_transaction_id=transaction_id FOR SHARE;
  IF NOT FOUND OR reservation.planned_response_type IS DISTINCT FROM 'utilts_err' OR reservation.disposition IS DISTINCT FROM 'processability_rejected'
   OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'utilts_err') OR (p_sending AND (reservation.final_response_type IS DISTINCT FROM 'utilts_err' OR reservation.response_message_id IS DISTINCT FROM m.id OR reservation.finalized_at IS NULL)) THEN RAISE EXCEPTION 'utilts_err_own_reservation_unavailable';END IF;
 END LOOP;
END $$;

--
-- Name: require_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='outbound' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=c.witness_id
  WHERE c.source_message_id=m.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE OF witness;
 IF w.id IS NULL THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 PERFORM gridex_ediel_outbound_owner.assert_message_v1(m,w);RETURN w.evidence;
END $$;

--
-- Name: capture(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;q jsonb;deps jsonb;BEGIN
 result:=gridex_ediel_readiness.capture_before_registry_markets_v1(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 q:=gridex_registry_import.require_message_market_v1(p_company_id,p_message_id);
 IF q IS NULL THEN RETURN result;END IF;
 deps:=(result->'dependencies')||jsonb_build_object('sourceQualifiedRegistryMarket',q);
 RETURN result||jsonb_build_object('dependencies',deps,'dependencyHash',encode(sha256(convert_to(jsonb_build_object('scope',result->'scope','dependencies',deps)::text,'UTF8')),'hex'));
END$$;

--
-- Name: capture_before_registry_markets_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture_before_registry_markets_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE current_scope jsonb; deps jsonb; m public.ediel_messages%rowtype; r public.ediel_route_profiles%rowtype; communication public.communication_routes%rowtype; registry_route public.platform_actor_routes%rowtype; registry_id uuid; route_dependency jsonb;
BEGIN
 current_scope:=gridex_ediel_readiness.capture_before_route_dependencies_v1(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.ediel_route_profiles WHERE id=m.route_profile_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO communication FROM public.communication_routes WHERE id=r.communication_route_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR communication.is_active IS DISTINCT FROM true OR to_jsonb(communication)->>'environment_type' IS DISTINCT FROM 'production' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 BEGIN registry_id:=nullif(r.metadata->>'platform_actor_route_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END;
 IF registry_id IS NOT NULL THEN
  SELECT * INTO registry_route FROM public.platform_actor_routes WHERE id=registry_id AND environment='production' FOR SHARE;
  IF NOT FOUND OR registry_route.is_verified IS DISTINCT FROM true OR registry_route.status IS DISTINCT FROM 'active' OR to_jsonb(registry_route)->'auto_send_allowed'='false'::jsonb THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  IF nullif(btrim(registry_route.communication_address),'') IS NULL OR lower(btrim(registry_route.communication_address)) IS DISTINCT FROM lower(btrim(communication.target_email)) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  IF coalesce(nullif(btrim(registry_route.party_id),''),nullif(btrim(registry_route.interchange_party_id),'')) IS DISTINCT FROM nullif(btrim(r.receiver_ediel_id),'')
   OR upper(registry_route.message_family) IS DISTINCT FROM upper(m.message_family) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 -- Only selected actual fields. No global routes hash or secret auth_config.
 route_dependency:=jsonb_build_object('communicationRoute',jsonb_build_object('id',communication.id,'companyId',communication.company_id,'active',communication.is_active,'environment',to_jsonb(communication)->'environment_type','targetEmail',communication.target_email,'endpoint',to_jsonb(communication)->'endpoint','counterpartyEdielId',to_jsonb(communication)->'counterparty_ediel_id','payloadVersion',to_jsonb(communication)->'supported_payload_version','messageFamilies',to_jsonb(communication)->'supported_message_families','messageCodes',to_jsonb(communication)->'supported_message_codes'),
  'registryRoute',CASE WHEN registry_id IS NULL THEN NULL ELSE jsonb_build_object('id',registry_route.id,'actorId',registry_route.actor_id,'environment',registry_route.environment,'messageFamily',registry_route.message_family,'applicationReference',registry_route.application_reference,'subaddress',registry_route.subaddress,'communicationType',registry_route.communication_type,'communicationAddress',registry_route.communication_address,'partyId',registry_route.party_id,'interchangePartyId',registry_route.interchange_party_id,'verified',registry_route.is_verified,'status',registry_route.status,'source',registry_route.source,'sourceVersion',registry_route.metadata->'source_version') END);
 deps:=(current_scope->'dependencies')||jsonb_build_object('selectedRouteSecurity',route_dependency);
 RETURN current_scope||jsonb_build_object('dependencies',deps,'dependencyHash',encode(digest(convert_to(jsonb_build_object('scope',current_scope->'scope','dependencies',deps)::text,'UTF8'),'sha256'),'hex'));
END $$;

--
-- Name: capture_before_route_dependencies_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture_before_route_dependencies_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE m public.ediel_messages%rowtype; r public.ediel_route_profiles%rowtype; scope jsonb; deps jsonb; profile_rows jsonb; role_rows jsonb;
 identifier_rows jsonb; capability_rows jsonb; permission_rows jsonb:='[]'; assignment_rows jsonb:='[]'; certificate_rows jsonb;
 schema_parts jsonb; schema_hash text; schema_ready boolean; release_row public.platform_release_receipts%rowtype; source_tokens jsonb; family text; code text; wire_subtype text; derived jsonb; selected_profile public.ediel_message_profiles%rowtype; selected_pack public.ediel_rule_packs%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR p_legal_actor_id IS NULL OR nullif(p_actor_role,'') IS NULL
  OR p_family IS NULL OR p_family NOT IN ('PRODAT','UTILTS','AI_LIST') OR nullif(p_code,'') IS NULL OR p_code='ERR'
  OR p_release_sha IS NULL OR p_release_sha !~ '^[0-9a-f]{40}$' OR p_rulepack_hash IS NULL OR p_rulepack_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO release_row FROM public.platform_release_receipts WHERE environment='production' AND status='verified'
  AND verified_at IS NOT NULL AND nullif(ci_run_id,'') IS NOT NULL AND nullif(deployment_id,'') IS NOT NULL
  ORDER BY verified_at DESC,recorded_at DESC,id LIMIT 1 FOR SHARE;
 IF NOT FOUND OR release_row.release_sha IS DISTINCT FROM p_release_sha THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND environment='production' FOR SHARE;
 IF NOT FOUND OR m.direction<>'outbound' OR m.message_family IS DISTINCT FROM p_family OR m.message_code IS DISTINCT FROM p_code
  OR (p_family<>'AI_LIST' AND m.rule_pack_checksum IS DISTINCT FROM p_rulepack_hash) OR m.raw_payload IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 derived:=gridex_ediel_readiness.source_scope(m);
 IF derived->>'actorId' IS DISTINCT FROM p_legal_actor_id::text OR derived->>'actorRole' IS DISTINCT FROM p_actor_role
  OR derived->>'family' IS DISTINCT FROM p_family OR derived->>'code' IS DISTINCT FROM p_code OR derived->>'subtype' IS DISTINCT FROM p_subtype
  OR derived->>'assignmentId' IS DISTINCT FROM p_assignment_id::text THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 wire_subtype:=derived#>>'{canonicalProjection,transactionReasonCode}';
 IF p_family<>'AI_LIST' THEN
  SELECT * INTO selected_profile FROM public.ediel_message_profiles mp WHERE mp.id=m.rule_profile_version_id AND mp.rule_pack_id=m.canonical_rule_pack_id AND mp.message_code=p_code
   AND mp.transaction_subtype=coalesce(p_subtype,'') AND mp.is_enabled AND mp.direction IN ('outbound','both') FOR SHARE;
  IF NOT FOUND OR (p_family='PRODAT' AND selected_profile.profile->>'reasonForTransaction' IS DISTINCT FROM wire_subtype) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT * INTO selected_pack FROM public.ediel_rule_packs rp WHERE rp.id=selected_profile.rule_pack_id AND rp.family=p_family AND rp.market='electricity' AND rp.status='active'
   AND rp.source_hash=p_rulepack_hash AND rp.valid_from<=current_date AND (rp.valid_to IS NULL OR rp.valid_to>=current_date) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'companyId',a.company_id,'environment',a.environment,'market',a.market,'enabled',a.is_enabled,'validFrom',a.valid_from,'validTo',a.valid_to) ORDER BY a.id),'[]') INTO profile_rows FROM public.tenant_ediel_profiles a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.market='electricity' AND a.is_enabled AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO identifier_rows FROM public.tenant_actor_identifiers a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.actor_id=p_legal_actor_id AND a.identifier_type='EdielId' AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO role_rows FROM public.tenant_actor_roles a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.actor_id=p_legal_actor_id AND a.role_code=p_actor_role AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO capability_rows FROM public.tenant_message_capabilities a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.message_family=p_family AND a.message_code=p_code AND a.transaction_subtype IN ('*',coalesce(p_subtype,''))
   AND a.direction IN ('outbound','both') AND a.is_enabled AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 IF p_family='AI_LIST' AND NOT EXISTS(SELECT FROM jsonb_array_elements(identifier_rows) x WHERE x->>'identifier_value'=split_part(m.raw_payload,';',4)) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF jsonb_array_length(profile_rows)=0 OR jsonb_array_length(identifier_rows)=0 OR jsonb_array_length(role_rows)=0 OR jsonb_array_length(capability_rows)=0 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO r FROM public.ediel_route_profiles WHERE company_id=p_company_id AND id=m.route_profile_id AND environment='production' FOR SHARE;
 IF NOT FOUND OR NOT coalesce(r.is_enabled,false) OR r.is_active=false OR r.communication_route_id IS DISTINCT FROM m.communication_route_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF EXISTS(SELECT FROM public.ediel_certificates c WHERE c.company_id=p_company_id AND c.id IN (r.certificate_id,r.receiver_certificate_id)
   AND ((c.certificate_valid_from IS NOT NULL AND c.certificate_valid_from>now()) OR (c.certificate_valid_to IS NOT NULL AND c.certificate_valid_to<=now()))) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'fingerprint',c.certificate_fingerprint,'validFrom',c.certificate_valid_from,'validTo',c.certificate_valid_to,'status',c.status,'encryptionStatus',c.encryption_status) ORDER BY c.id),'[]') INTO certificate_rows
  FROM public.ediel_certificates c WHERE c.company_id=p_company_id AND c.id IN (r.certificate_id,r.receiver_certificate_id);
 IF p_actor_role IN ('energy_service_company','esco','service_provider') THEN
  IF p_assignment_id IS NULL OR public.ediel_service_assignment_assessment_v1(p_company_id,p_assignment_id)->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT jsonb_build_array(to_jsonb(a)) INTO assignment_rows FROM public.ediel_service_assignments a
   WHERE a.id=p_assignment_id AND a.company_id=p_company_id AND a.environment='production' AND a.provider_actor_id=p_legal_actor_id AND a.customer_id=m.customer_id;
  IF assignment_rows IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('permission',to_jsonb(p),'link',to_jsonb(l),'grants',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.id) FROM public.ediel_data_access_grants g WHERE g.company_id=p_company_id AND g.permission_link_id=l.id),'[]')) ORDER BY l.id),'[]') INTO permission_rows
   FROM public.ediel_assignment_permission_links l JOIN public.metering_permissions p ON p.id=l.permission_id AND p.company_id=l.company_id WHERE l.company_id=p_company_id AND l.assignment_id=p_assignment_id;
 ELSE
  IF p_assignment_id IS NOT NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 -- Live schema identity for this capability's own dependency relations/functions.
 -- Unrelated UI/schema additions do not invalidate a different dependency graph.
 SELECT coalesce(is_ready,false) INTO schema_ready FROM public.platform_runtime_readiness WHERE id=true;
 IF NOT coalesce(schema_ready,false) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) ORDER BY n.nspname,c.relname,a.attnum)
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relname=ANY(ARRAY['ediel_messages','ediel_route_profiles','ediel_certificates','tenant_ediel_profiles','tenant_actor_identifiers','tenant_actor_roles','tenant_message_capabilities',CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'ediel_service_assignments' END,CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'metering_permissions' END,CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'ediel_data_access_grants' END]) AND a.attnum>0 AND NOT a.attisdropped),
  'functions',(SELECT jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,p.oid)
   FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='gridex_ediel_readiness' AND p.proname IN ('capture','source_scope'))) INTO schema_parts;
 schema_hash:=encode(digest(convert_to(schema_parts::text,'UTF8'),'sha256'),'hex');
 scope:=jsonb_build_object('companyId',p_company_id,'actorId',p_legal_actor_id,'actorRole',p_actor_role,'market','electricity','environment','production','family',p_family,'code',p_code,'subtype',p_subtype,'assignmentId',p_assignment_id);
 deps:=jsonb_build_object('releaseSha',p_release_sha,'releaseReceipt',jsonb_build_object('id',release_row.id,'ciRunId',release_row.ci_run_id,'deploymentId',release_row.deployment_id,'schemaMigrationVersion',release_row.schema_migration_version,'databaseSchemaFingerprint',to_jsonb(release_row)->'database_schema_fingerprint','generatedTypesHash',to_jsonb(release_row)->'generated_types_hash','migrationManifestHash',to_jsonb(release_row)->'migration_manifest_hash'),'schemaFingerprint',schema_hash,'rulepackHash',p_rulepack_hash,'wireTransactionReason',wire_subtype,'technicalFormatVersion',CASE WHEN p_family='AI_LIST' THEN 'Ver20140401' ELSE NULL END,'rulepackId',m.canonical_rule_pack_id,'ruleProfileVersionId',m.rule_profile_version_id,
   'canonicalProjection',derived->'canonicalProjection','canonicalProjectionHash',derived->'canonicalProjectionHash','transportRelation',derived->'transportRelation','transportEdielId',derived->'transportEdielId','transportIdentifiers',derived->'transportIdentifiers',
   'normativeProjection',CASE WHEN p_family='AI_LIST' THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('packId',selected_pack.id,'sourceHash',selected_pack.source_hash,'status',selected_pack.status,'guideVersion',selected_pack.guide_version,'guideRevision',selected_pack.guide_revision,'validFrom',selected_pack.valid_from,'validTo',selected_pack.valid_to,'profileId',selected_profile.id,'profileKey',selected_profile.profile_key,'subtype',selected_profile.transaction_subtype,'profile',selected_profile.profile)) END,
  'tenantRuleProfileVersion',coalesce((SELECT jsonb_build_object('id',rv.id,'version',rv.version,'status',rv.status,'checksum',rv.checksum,'sourceRevision',rv.source_revision)
    FROM public.ediel_rule_profile_versions rv WHERE rv.company_id=p_company_id AND rv.id=m.rule_profile_version_id), '{}'::jsonb),
  'profile',profile_rows,'legalIdentifiers' ,identifier_rows,'actorRole',role_rows,'capability',capability_rows,
  'route',jsonb_build_object('id',r.id,'communicationRouteId',r.communication_route_id,'routeVersion',to_jsonb(r)->'route_version','senderEdielId',r.sender_ediel_id,'receiverEdielId',r.receiver_ediel_id,'senderSubaddress',coalesce(r.sender_sub_address,r.sender_subaddress),'receiverSubaddress',coalesce(r.receiver_sub_address,r.receiver_subaddress),'mailboxId',r.mailbox_id,'transportProfileId',r.transport_profile_id,'certificateId',r.certificate_id,'receiverCertificateId',r.receiver_certificate_id,'enabled',r.is_enabled,'active',r.is_active),
  'certificates',certificate_rows,'assignments',assignment_rows,'permissions',permission_rows);
 RETURN jsonb_build_object('authorityVersion',1,'scope',scope,'dependencies',deps,'dependencyHash',encode(digest(convert_to(jsonb_build_object('scope',scope,'dependencies',deps)::text,'UTF8'),'sha256'),'hex'));
END $_$;

--
-- Name: reject_mutation(); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_scoped_evidence_immutable'; END $$;

--
-- Name: source_scope(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.source_scope(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE ai_parties jsonb;tokens jsonb; own_projection jsonb; family text; code text; reason text; wire_sender text; legal_actor uuid; legal_id text;
 transport_id text; transport_identifiers jsonb; relation public.tenant_counterparty_relations%rowtype; role text; role_count integer; reasons jsonb; assignment uuid;
BEGIN
 IF m.direction<>'outbound' OR m.environment<>'production' OR m.company_id IS NULL OR nullif(m.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF m.message_family='AI_LIST' THEN
  IF m.message_code<>'AI' OR split_part(m.raw_payload,';',1)<>'AI' OR rtrim(split_part(split_part(m.raw_payload,E'\n',1),';',10),E'\r')<>'Ver20140401' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  family:='AI_LIST';code:='AI';wire_sender:=split_part(m.raw_payload,';',4);
  own_projection:=jsonb_build_object('family','AI_LIST','code','AI','subtype',NULL,'transactionReasonCode',NULL,'senderRoles',jsonb_build_array('supplier'),'direction','outbound');
 ELSE
  tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
  IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT t#>>'{elements,2,0}' INTO family FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH';
  SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  SELECT t#>>'{elements,2,0}' INTO wire_sender FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB';
  IF family='PRODAT' THEN
   SELECT coalesce(jsonb_agg(DISTINCT cav.token#>>'{elements,1,0}'),'[]') INTO reasons FROM jsonb_array_elements(tokens) WITH ORDINALITY cci(token,n)
    JOIN jsonb_array_elements(tokens) WITH ORDINALITY cav(token,n) ON cav.n=cci.n+1 WHERE cci.token->>'tag'='CCI' AND cci.token#>>'{elements,2,0}'='Z13' AND cav.token->>'tag'='CAV';
   IF jsonb_array_length(reasons)<>1 OR nullif(reasons->>0,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
   reason:=reasons->>0;
  END IF;
  SELECT projection INTO own_projection FROM (SELECT catalog FROM gridex_ediel_readiness.source_editions ORDER BY recorded_at DESC,source_version LIMIT 1) edition CROSS JOIN LATERAL jsonb_array_elements(edition.catalog) projection
   WHERE projection->>'family'=family AND projection->>'code'=code AND projection->>'transactionReasonCode' IS NOT DISTINCT FROM reason;
  IF own_projection IS NULL OR own_projection->>'direction' NOT IN ('outbound','both') THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 IF family IS DISTINCT FROM m.message_family OR code IS DISTINCT FROM m.message_code THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 -- Count the entire current legal identity set: no stale proof can opt into a
 -- different valid actor of the same tenant or resolve an ambiguous identity.
 IF (SELECT count(DISTINCT (i.actor_id,btrim(i.identifier_value))) FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment='production' AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT i.actor_id,btrim(i.identifier_value) INTO legal_actor,legal_id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment='production' AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()) LIMIT 1;
 IF legal_actor IS NULL OR nullif(legal_id,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF family='AI_LIST' THEN
  IF wire_sender IS DISTINCT FROM legal_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 ELSE
  IF (SELECT count(*) FROM public.tenant_counterparty_relations t WHERE t.company_id=m.company_id AND t.environment='production' AND t.relation_type='ediel_transport_agent' AND t.is_enabled AND t.valid_from<=now() AND (t.valid_to IS NULL OR t.valid_to>now()))>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT * INTO relation FROM public.tenant_counterparty_relations t WHERE t.company_id=m.company_id AND t.environment='production' AND t.relation_type='ediel_transport_agent' AND t.is_enabled AND t.valid_from<=now() AND (t.valid_to IS NULL OR t.valid_to>now());
  transport_id:=legal_id;
  IF FOUND THEN
   IF relation.counterparty_actor_id=legal_actor OR (SELECT count(DISTINCT btrim(i.identifier_value)) FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
   SELECT btrim(i.identifier_value) INTO transport_id FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date) LIMIT 1;
   SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) INTO transport_identifiers FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
   IF transport_id=legal_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  END IF;
  IF nullif(transport_id,'') IS NULL OR wire_sender IS DISTINCT FROM transport_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 SELECT count(DISTINCT a.role_code),min(a.role_code) INTO role_count,role FROM public.tenant_actor_roles a WHERE a.company_id=m.company_id AND a.environment='production' AND a.actor_id=legal_actor AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now())
  AND own_projection->'senderRoles' ? CASE a.role_code WHEN 'electricity_supplier' THEN 'supplier' WHEN 'energy_service_company' THEN 'esco' ELSE a.role_code END;
 IF role_count<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF role IN ('energy_service_company','esco') THEN
  BEGIN assignment:=nullif(m.parsed_payload->>'serviceAssignmentId','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END;
  IF assignment IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 IF family='AI_LIST' THEN
  ai_parties:=gridex_ai_processing.party_source_v1(m.company_id,m.intent_id);PERFORM gridex_ai_processing.require_party_wire_v1(m.raw_payload,ai_parties);
  IF m.sender_ediel_id IS DISTINCT FROM ai_parties->>'technicalSender' OR m.receiver_ediel_id IS DISTINCT FROM ai_parties->>'technicalReceiver' THEN RAISE EXCEPTION 'ai_list_readiness_technical_party_source_mismatch';END IF;
  transport_id:=ai_parties->>'technicalSender';transport_identifiers:=ai_parties#>'{sourceBasis,transportIdentifiers}';
 END IF;
 RETURN jsonb_build_object('actorId',legal_actor,'actorRole',role,'family',family,'code',code,'subtype',own_projection->'subtype','assignmentId',assignment,'canonicalProjection',own_projection,'canonicalProjectionHash',encode(digest(convert_to(own_projection::text,'UTF8'),'sha256'),'hex'),'transportRelation',CASE WHEN family='AI_LIST' THEN ai_parties#>'{sourceBasis,transportRelation}' WHEN relation.id IS NULL THEN NULL ELSE to_jsonb(relation) END,'transportEdielId',transport_id,'transportIdentifiers',transport_identifiers);
END $$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.actor_v1(c uuid, actor uuid, permission text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 -- Hold the actual authorization registry, including insertion of new deny
 -- overrides, throughout this operation; a preceding server/UI check is not it.
 LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(actor);PERFORM id FROM public.companies WHERE id=c FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;
 PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF public.ediel_retention_session_actor_v1() IS DISTINCT FROM actor OR permission NOT IN('ediel.retention.submit','ediel.retention.review','ediel.retention.purge')
 OR NOT public.ediel_retention_lock_auth_actor_v1(actor)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR gridex_ediel_retention.permission_v1(c,actor,permission) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_retention_current_actor_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: artifact_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.artifact_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' OR old.source_bytes IS NULL OR new.source_bytes IS NOT NULL OR new.purged_at IS NULL
 OR (to_jsonb(new)-ARRAY['source_bytes','purged_at']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['source_bytes','purged_at'])
 OR NOT EXISTS(SELECT FROM gridex_ediel_retention.purges p WHERE p.artifact_id=old.id AND p.company_id=old.company_id AND p.source_hash=old.source_hash AND p.claims_hash=old.claims_hash AND p.byte_length=octet_length(old.source_bytes) AND p.created_at=new.purged_at)
 THEN RAISE EXCEPTION 'ediel_artifact_immutable_without_qualified_purge';END IF;RETURN new;
END$$;

--
-- Name: artifact_insert_length_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.artifact_insert_length_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF new.source_bytes IS NULL OR new.purged_at IS NOT NULL THEN RAISE EXCEPTION 'ediel_retention_new_source_bytes_required';END IF;
 new.source_byte_length:=octet_length(new.source_bytes);RETURN new;
END$$;

--
-- Name: blob_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;p public.ediel_message_payloads%rowtype;facts jsonb;rawhash text;bytes bigint;path text;payloads jsonb;
BEGIN
 IF k='received_ediel_message_content' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=target AND company_id=c FOR SHARE;SELECT * INTO STRICT s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=c FOR SHARE;
  IF m.direction IS DISTINCT FROM 'inbound' OR s.raw_payload IS NULL OR m.raw_payload IS DISTINCT FROM s.raw_payload OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'retention_actual_received_original_required';END IF;
  PERFORM id FROM public.ediel_message_payloads WHERE company_id=c AND ediel_message_id=m.id ORDER BY id FOR SHARE;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'raw',raw_payload,'encrypted',encrypted_payload,'hash',raw_payload_hash,'kind',payload_kind) ORDER BY id),'[]') INTO payloads FROM public.ediel_message_payloads WHERE company_id=c AND ediel_message_id=m.id;
  rawhash:=s.payload_hash;bytes:=octet_length(convert_to(s.raw_payload,'UTF8'));facts:=jsonb_build_object('source',to_jsonb(s),'publicContent',gridex_ediel_retention.public_content_v1(m),'payloadCopies',payloads);
 ELSIF k='transport_raw_mime_bytes' THEN
  SELECT * INTO STRICT p FROM public.ediel_message_payloads WHERE id=target AND company_id=c FOR SHARE;SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p.ediel_message_id AND company_id=c FOR SHARE;
  rawhash:=p.metadata->>'archived_mime_sha256';bytes:=(p.metadata->>'archived_mime_bytes')::bigint;path:='transport/'||c::text||'/'||m.id::text||'/'||rawhash||'.eml';
  IF m.direction IS DISTINCT FROM 'outbound' OR p.payload_kind NOT IN('raw_mime','smime_enveloped') OR p.metadata->>'archive_verified' IS DISTINCT FROM 'true' OR rawhash!~'^[a-f0-9]{64}$' OR bytes NOT BETWEEN 1 AND 33554432 OR p.encrypted_payload_ref IS DISTINCT FROM 'storage://ediel-files/'||path
  OR NOT (EXISTS(SELECT FROM gridex_ediel_transport.attempts a WHERE a.company_id=c AND a.message_id=m.id AND a.entered_at IS NOT NULL AND a.binding->>'mimeSha256'=rawhash AND a.binding->>'mimeArchiveRef'=p.encrypted_payload_ref AND a.binding->>'mimeLength'=bytes::text AND a.binding->>'rfcMessageId'=p.metadata->>'archived_rfc_message_id')
   OR EXISTS(SELECT FROM gridex_outbound_dispatch.attempts a JOIN gridex_outbound_dispatch.events e ON e.attempt_id=a.id AND e.kind='provider_call_entered' WHERE a.company_id=c AND a.message_id=m.id AND a.binding->>'mimeSha256'=rawhash AND a.binding->>'mimeArchiveRef'=p.encrypted_payload_ref AND a.binding->>'mimeLength'=bytes::text AND a.binding->>'rfcMessageId'=p.metadata->>'archived_rfc_message_id')) THEN RAISE EXCEPTION 'retention_private_entered_mime_original_required';END IF;
  facts:=jsonb_build_object('snapshot',to_jsonb(p),'message',m.id,'company',c,'environment',m.environment);
 ELSE RAISE EXCEPTION 'retention_class_not_implemented';END IF;
 RETURN jsonb_build_object('companyId',c,'retentionClass',k,'targetId',target,'messageId',m.id,'sourceHash',rawhash,'targetHash',encode(sha256(convert_to(facts::text,'UTF8')),'hex'),'publicContentHash',encode(sha256(convert_to(gridex_ediel_retention.public_content_v1(m)::text,'UTF8')),'hex'),'byteLength',bytes,'storagePath',path);
END$_$;

--
-- Name: blob_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.blob_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id uuid NOT NULL,
    message_id uuid NOT NULL,
    source_hash text NOT NULL,
    target_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT blob_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT blob_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT blob_decisions_retention_class_check CHECK ((retention_class = ANY (ARRAY['received_ediel_message_content'::text, 'transport_raw_mime_bytes'::text]))),
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0))))
);

ALTER TABLE ONLY gridex_ediel_retention.blob_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: blob_current_v1(gridex_ediel_retention.blob_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_current_v1(d gridex_ediel_retention.blob_decisions) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_ediel_retention.blob_reviews%rowtype;claims jsonb;BEGIN
 SELECT * INTO r FROM gridex_ediel_retention.blob_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(r.actor_user_id);PERFORM id FROM public.user_profiles WHERE id=r.actor_user_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id FOR SHARE;
 IF r.outcome IS DISTINCT FROM 'approved' OR NOT public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=r.actor_user_id AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id AND status='active' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE THEN RETURN NULL;END IF;
 IF gridex_ediel_retention.class_permission_v1(d.company_id,r.actor_user_id,d.retention_class) IS NOT TRUE THEN RETURN NULL;END IF;claims:=gridex_ediel_retention.blob_receipt_v1(d);IF claims IS NULL OR (claims->>'retainUntil')::timestamptz>now() THEN RETURN NULL;END IF;RETURN r.id;
END$$;

--
-- Name: blob_decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: blob_receipt_v1(gridex_ediel_retention.blob_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_receipt_v1(d gridex_ediel_retention.blob_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_ediel_retention.issuers%rowtype;p jsonb;b bytea;issued timestamptz;expires timestamptz;deadline timestamptz;
BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF k.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=k.id) OR EXISTS(SELECT FROM gridex_ediel_retention.blob_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 b:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(b,k.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(b,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_blob_retention_policy_v1' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'targetId' IS DISTINCT FROM d.target_id::text OR p->>'messageId' IS DISTINCT FROM d.message_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetHash' IS DISTINCT FROM d.target_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'issuerLegalReference' IS DISTINCT FROM k.legal_reference OR nullif(p->>'legalBasisReference','') IS NULL OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR issued>now() OR expires<=now() OR issued<k.valid_from OR expires>k.valid_to THEN RETURN NULL;END IF;RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: blob_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_ediel_retention.blob_decisions WHERE id=NEW.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'blob_retention_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: certification_classification_revocations_retention_original_gua(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.certification_classification_revocations_retention_original_gua() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND (gridex_ediel_retention.protected_copy_transition_v1('certification_revocation_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE) THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: certification_classifications_retention_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.certification_classifications_retention_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND (gridex_ediel_retention.protected_copy_transition_v1('certification_classification_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE OR gridex_ediel_retention.protected_copy_transition_v1('certification_workbook_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE) THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: class_permission_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.class_permission_v1(c uuid, actor uuid, retention_class text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT gridex_ediel_retention.permission_v1(c,actor,CASE retention_class WHEN 'requested_change_source_artifact_bytes' THEN 'ediel.retention.source_bytes' WHEN 'customer_canonical_personal_fields' THEN 'ediel.retention.customer_fields' WHEN 'received_ediel_message_content' THEN 'ediel.retention.original_bytes' WHEN 'transport_raw_mime_bytes' THEN 'ediel.retention.mime_bytes' ELSE NULL END) IS TRUE
$$;

--
-- Name: classification_copy_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;bytes bytea;BEGIN
 r:=gridex_ediel_retention.classification_copy_row_v1(c,k,target);bytes:=decode(substr(r->>'document_bytes',3),'hex');
 IF bytes IS NULL OR octet_length(bytes)<1 THEN RAISE EXCEPTION 'decision_evidence_actual_original_bytes_required';END IF;
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'byteLength',octet_length(bytes));
END$$;

--
-- Name: classification_copy_insert_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.source_original IS NULL OR encode(sha256(NEW.source_original),'hex') IS DISTINCT FROM NEW.source_sha256 OR TG_TABLE_NAME='inbound_classifications' AND(to_jsonb(NEW)->>'classification_original' IS NULL OR encode(sha256(decode(substr(to_jsonb(NEW)->>'classification_original',3),'hex')),'hex') IS DISTINCT FROM to_jsonb(NEW)->>'classification_sha256') THEN RAISE EXCEPTION 'classification_copy_new_actual_bytes_required';END IF;RETURN NEW;
END$$;

--
-- Name: classification_copy_row_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_row_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q gridex_customer_life_events.inbound_classifications%rowtype;v gridex_customer_life_events.classification_revocations%rowtype;bytes bytea;h text;meta jsonb;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO q FROM gridex_customer_life_events.inbound_classifications WHERE id=target AND company_id=c;
 IF q.id IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 PERFORM id FROM public.ediel_messages WHERE id=q.source_message_id AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 SELECT * INTO STRICT q FROM gridex_customer_life_events.inbound_classifications WHERE id=target AND company_id=c FOR UPDATE;
 meta:=to_jsonb(q)-ARRAY['source_original','classification_original'];
 IF k='life_event_classification_source_original_bytes' THEN bytes:=q.source_original;h:=q.source_sha256;
 ELSIF k='life_event_classification_receipt_original_bytes' THEN bytes:=q.classification_original;h:=q.classification_sha256;
 ELSIF k='life_event_classification_revocation_original_bytes' THEN
  SELECT * INTO v FROM gridex_customer_life_events.classification_revocations WHERE classification_id=target FOR UPDATE;IF v.classification_id IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
  bytes:=v.source_original;h:=v.source_sha256;meta:=jsonb_build_object('classification',meta,'revocation',to_jsonb(v)-'source_original');
 ELSE RAISE EXCEPTION 'classification_copy_class_required';END IF;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=c;
 IF bytes IS NOT NULL AND encode(sha256(bytes),'hex') IS DISTINCT FROM h OR bytes IS NULL AND(t.target_id IS NULL OR t.source_hash IS DISTINCT FROM h) THEN RAISE EXCEPTION 'decision_evidence_original_custody_mismatch';END IF;
 RETURN jsonb_build_object('id',target,'company_id',c,'document_bytes',CASE WHEN bytes IS NULL THEN NULL ELSE '\x'||encode(bytes,'hex') END,'document_hash',h,'document_byte_length',CASE WHEN bytes IS NULL THEN t.byte_length ELSE NULL END,'document_purged_at',t.created_at,'source_metadata',meta);
END$$;

--
-- Name: classification_copy_source_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_source_current_v1(c uuid, mid uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE actual_company uuid;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT company_id INTO actual_company FROM public.ediel_messages WHERE id=mid AND(c IS NULL OR company_id=c) FOR SHARE;
 IF actual_company IS NULL THEN RETURN false;END IF;
 PERFORM id FROM gridex_customer_life_events.inbound_classifications WHERE source_message_id=mid AND company_id=actual_company FOR SHARE;
 RETURN NOT EXISTS(SELECT FROM gridex_ediel_retention.classification_copy_revocations WHERE source_message_id=mid AND company_id=actual_company);
END$$;

--
-- Name: classification_copy_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_transition_v1(k text, o jsonb, n jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE target uuid:=coalesce(o->>'id',o->>'classification_id')::uuid;q gridex_customer_life_events.inbound_classifications%rowtype;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;d gridex_ediel_retention.decision_evidence_policies%rowtype;r gridex_ediel_retention.decision_evidence_reviews%rowtype;p jsonb;b jsonb;bytes bytea;h text;field text;permission text;at timestamptz;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO q FROM gridex_customer_life_events.inbound_classifications WHERE id=target;
 PERFORM id FROM public.ediel_messages WHERE id=q.source_message_id AND company_id=q.company_id FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO STRICT q FROM gridex_customer_life_events.inbound_classifications WHERE id=target FOR UPDATE;
 field:=CASE k WHEN 'life_event_classification_source_original_bytes' THEN 'source_original' WHEN 'life_event_classification_receipt_original_bytes' THEN 'classification_original' WHEN 'life_event_classification_revocation_original_bytes' THEN 'source_original' END;
 IF field IS NULL OR o->>field IS NULL OR n->>field IS NOT NULL OR(o-field) IS DISTINCT FROM(n-field) THEN RETURN false;END IF;
 bytes:=decode(substr(o->>field,3),'hex');h:=encode(sha256(bytes),'hex');
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=q.company_id;
 IF t.target_id IS NULL OR h IS DISTINCT FROM t.source_hash OR octet_length(bytes) IS DISTINCT FROM t.byte_length OR NOT EXISTS(SELECT FROM gridex_ediel_retention.classification_copy_revocations WHERE retention_class=k AND classification_id=target AND company_id=q.company_id AND source_message_id=q.source_message_id AND policy_id=t.policy_id AND review_id=t.review_id AND source_hash=h AND actor_user_id=t.actor_user_id) THEN RETURN false;END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=t.policy_id FOR UPDATE;
 SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF r.id IS DISTINCT FROM t.review_id OR r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR d.retention_class IS DISTINCT FROM k OR d.target_id IS DISTINCT FROM target OR d.company_id IS DISTINCT FROM q.company_id OR d.source_hash IS DISTINCT FROM h OR d.target_metadata_hash IS DISTINCT FROM t.target_metadata_hash THEN RETURN false;END IF;
 b:=gridex_ediel_retention.classification_copy_basis_v1(q.company_id,k,target);
 IF b->>'sourceHash' IS DISTINCT FROM d.source_hash OR b->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash THEN RETURN false;END IF;
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;
 PERFORM gridex_ediel_retention.decision_evidence_actor_v1(q.company_id,t.actor_user_id,k,'ediel.retention.purge');
 PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(q.company_id,r.actor_user_id,k);
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;
 SELECT permission_key INTO STRICT permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 IF gridex_ediel_retention.permission_v1(q.company_id,t.actor_user_id,'ediel.retention.purge') IS NOT TRUE OR gridex_ediel_retention.permission_v1(q.company_id,t.actor_user_id,permission) IS NOT TRUE OR gridex_ediel_retention.permission_v1(q.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(q.company_id,r.actor_user_id,permission) IS NOT TRUE THEN RETURN false;END IF;
 at:=clock_timestamp();RETURN (p->>'retainUntil')::timestamptz<=at AND(p->>'issuedAt')::timestamptz<=at AND(p->>'expiresAt')::timestamptz>at AND(p->>'journalRetainUntil')::timestamptz>at;
END$$;

--
-- Name: classification_copy_view_update_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_copy_view_update_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k text;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN
 SELECT retention_class INTO STRICT k FROM gridex_ediel_retention.decision_evidence_catalog WHERE source_table=TG_TABLE_NAME;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=OLD.id AND company_id=OLD.company_id;
 IF t.target_id IS NULL OR OLD.document_bytes IS NULL OR NEW.document_bytes IS NOT NULL OR(to_jsonb(OLD)-ARRAY['document_bytes','document_byte_length','document_purged_at']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['document_bytes','document_byte_length','document_purged_at']) OR NEW.document_byte_length IS DISTINCT FROM t.byte_length OR NEW.document_purged_at IS DISTINCT FROM t.created_at THEN RAISE EXCEPTION 'classification_copy_physical_transition_required';END IF;
 IF k='life_event_classification_source_original_bytes' THEN UPDATE gridex_customer_life_events.inbound_classifications SET source_original=NULL WHERE id=OLD.id AND company_id=OLD.company_id;
 ELSIF k='life_event_classification_receipt_original_bytes' THEN UPDATE gridex_customer_life_events.inbound_classifications SET classification_original=NULL WHERE id=OLD.id AND company_id=OLD.company_id;
 ELSE UPDATE gridex_customer_life_events.classification_revocations SET source_original=NULL WHERE classification_id=OLD.id;END IF;RETURN NEW;
END$$;

--
-- Name: classification_revocations_classification_copy_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.classification_revocations_classification_copy_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.classification_copy_transition_v1('life_event_classification_revocation_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: consumed_source_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.consumed_source_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE contract uuid;source uuid;origin uuid;BEGIN
 IF TG_TABLE_NAME='normal_supply_activations' THEN
  SELECT contract_id,source_message_id,original_message_id INTO STRICT contract,source,origin FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=NEW.period_id AND company_id=NEW.company_id FOR SHARE;
 ELSIF TG_TABLE_NAME='normal_switch_confirmations' THEN contract:=NEW.contract_id;source:=NEW.source_message_id;origin:=NEW.original_message_id;
 ELSE
  source:=NEW.source_message_id;
  IF NEW.event_id IS NOT NULL THEN SELECT contract_id INTO STRICT contract FROM gridex_requested_changes.events WHERE id=NEW.event_id AND company_id=NEW.company_id FOR SHARE;
  ELSE SELECT contract_id INTO STRICT contract FROM gridex_bilateral_customer_sources.artifacts WHERE id=NEW.bilateral_artifact_id AND company_id=NEW.company_id FOR SHARE;END IF;
 END IF;
 IF contract IS NULL THEN RAISE EXCEPTION 'retention_actual_consumed_contract_required';END IF;
 PERFORM public.ediel_require_contract_records_available_v1(NEW.company_id,contract);PERFORM public.ediel_require_source_bytes_available_v1(NEW.company_id,source);IF origin IS NOT NULL THEN PERFORM public.ediel_require_source_bytes_available_v1(NEW.company_id,origin);END IF;RETURN NEW;
END$$;

--
-- Name: contract_copy_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;b bytea;BEGIN
 r:=gridex_ediel_retention.contract_copy_row_v1(c,k,target);b:=decode(substr(r->>'document_bytes',3),'hex');IF b IS NULL OR octet_length(b)<1 THEN RAISE EXCEPTION 'decision_evidence_actual_original_bytes_required';END IF;
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'byteLength',octet_length(b));END$$;

--
-- Name: contract_copy_insert_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_TABLE_NAME='preparations' THEN IF NEW.basis_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.basis::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'contract_copy_new_full_preparation_hash_required';END IF;
 ELSIF NEW.agreement_original IS NULL OR NEW.source_original IS NULL OR encode(sha256(NEW.agreement_original),'hex') IS DISTINCT FROM NEW.agreement_sha256 OR encode(sha256(NEW.source_original),'hex') IS DISTINCT FROM NEW.source_sha256 THEN RAISE EXCEPTION 'contract_copy_new_actual_original_bytes_required';END IF;RETURN NEW;END$$;

--
-- Name: contract_copy_preparation_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_preparation_current_v1(c uuid, target uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r gridex_customer_masterdata.preparations%rowtype;p jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT * INTO r FROM gridex_customer_masterdata.preparations WHERE id=target AND company_id=c FOR SHARE;IF r.id IS NULL THEN RETURN false;END IF;p:=gridex_ediel_retention.contract_copy_prepared_proof_v1(r.basis);
 IF p IS NULL THEN RETURN NOT EXISTS(SELECT FROM gridex_ediel_retention.contract_copy_revocations WHERE company_id=c AND target_id=target AND retention_class LIKE 'masterdata_preparation_%');END IF;
 RETURN p->>'agreement_original' IS NOT NULL AND p->>'source_original' IS NOT NULL AND encode(sha256(decode(substr(p->>'agreement_original',3),'hex')),'hex')=p->>'agreement_sha256' AND encode(sha256(decode(substr(p->>'source_original',3),'hex')),'hex')=p->>'source_sha256' AND gridex_ediel_retention.contract_copy_source_current_v1(c,'gridex_customer_masterdata','signed_declarations',(p->>'id')::uuid) AND NOT EXISTS(SELECT FROM gridex_ediel_retention.contract_copy_revocations WHERE company_id=c AND target_id=target AND retention_class LIKE 'masterdata_preparation_%');END$$;

--
-- Name: contract_copy_prepared_metadata_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_prepared_metadata_v1(b jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF b#>>'{sourceProof,rowProof,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,'{sourceProof,rowProof}',(b#>'{sourceProof,rowProof}')-ARRAY['agreement_original','source_original']);
 ELSIF b#>>'{sourceProof,rowProof,base,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,'{sourceProof,rowProof,base}',(b#>'{sourceProof,rowProof,base}')-ARRAY['agreement_original','source_original']);END IF;RETURN b;END$$;

--
-- Name: contract_copy_prepared_proof_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_prepared_proof_v1(b jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT CASE WHEN b#>>'{sourceProof,rowProof,contract_id}' IS NOT NULL AND b#>>'{sourceProof,rowProof,id}' IS NOT NULL THEN b#>'{sourceProof,rowProof}' WHEN b#>>'{sourceProof,rowProof,base,contract_id}' IS NOT NULL AND b#>>'{sourceProof,rowProof,base,id}' IS NOT NULL THEN b#>'{sourceProof,rowProof,base}' END$$;

--
-- Name: contract_copy_prepared_redact_v1(jsonb, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_prepared_redact_v1(b jsonb, field text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF field NOT IN('agreement_original','source_original') THEN RAISE EXCEPTION 'contract_copy_exact_body_required';END IF;
 IF b#>>'{sourceProof,rowProof,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,ARRAY['sourceProof','rowProof',field],'null');
 ELSIF b#>>'{sourceProof,rowProof,base,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,ARRAY['sourceProof','rowProof','base',field],'null');END IF;RAISE EXCEPTION 'contract_copy_exact_prepared_source_required';END$$;

--
-- Name: contract_copy_row_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_row_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE spec record;r jsonb;meta jsonb;proof jsonb;bytes bytea;h text;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;customer uuid;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT * INTO STRICT spec FROM gridex_ediel_retention.contract_copy_catalog WHERE retention_class=k;
 EXECUTE format('SELECT to_jsonb(x) FROM %I.%I x WHERE id=$1 AND company_id=$2',spec.source_schema,spec.source_table) INTO r USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;customer:=(r->>'customer_id')::uuid;
 IF spec.source_schema='gridex_customer_masterdata' THEN
  PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(SELECT v.source_message_id FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=c AND v.customer_id=customer) ORDER BY m.id FOR UPDATE;
  PERFORM pg_advisory_xact_lock(hashtextextended('customer-masterdata:'||c::text||':'||customer::text,0));
  PERFORM ct.id FROM public.customer_contracts ct WHERE ct.company_id=c AND ct.id IN(SELECT d.contract_id FROM gridex_customer_masterdata.signed_declarations d WHERE d.company_id=c AND d.customer_id=customer) ORDER BY ct.id FOR SHARE;
  PERFORM id FROM public.customers WHERE id=customer AND company_id=c FOR UPDATE;
 ELSIF spec.source_table='contract_request_declarations' THEN
  PERFORM id FROM public.customer_contracts WHERE id=(r->>'contract_id')::uuid AND company_id=c FOR SHARE;
  PERFORM pg_advisory_xact_lock(hashtextextended('contract-method-request:'||c::text||':'||(r->>'contract_id'),0));
 END IF;
 EXECUTE format('SELECT to_jsonb(x) FROM %I.%I x WHERE id=$1 AND company_id=$2 FOR UPDATE',spec.source_schema,spec.source_table) INTO r USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 IF spec.source_table='preparations' THEN proof:=gridex_ediel_retention.contract_copy_prepared_proof_v1(r->'basis');h:=proof->>spec.hash_column;bytes:=decode(substr(proof->>spec.body_column,3),'hex');meta:=(r-'basis')||jsonb_build_object('basis',gridex_ediel_retention.contract_copy_prepared_metadata_v1(r->'basis'));
 ELSE h:=r->>spec.hash_column;bytes:=decode(substr(r->>spec.body_column,3),'hex');meta:=r-ARRAY['agreement_original','source_original'];END IF;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=c;
 IF h IS NULL OR bytes IS NOT NULL AND encode(sha256(bytes),'hex') IS DISTINCT FROM h OR bytes IS NULL AND(t.target_id IS NULL OR t.source_hash IS DISTINCT FROM h) THEN RAISE EXCEPTION 'decision_evidence_original_custody_mismatch';END IF;
 RETURN jsonb_build_object('id',target,'company_id',c,'document_bytes',CASE WHEN bytes IS NULL THEN NULL ELSE '\x'||encode(bytes,'hex') END,'document_hash',h,'document_byte_length',CASE WHEN bytes IS NULL THEN t.byte_length ELSE NULL END,'document_purged_at',t.created_at,'source_metadata',meta);
END$_$;

--
-- Name: contract_copy_source_before_intake_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_source_before_intake_v1(c uuid, ns text, tab text, target uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE r jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();IF (ns='gridex_customer_masterdata' AND tab='signed_declarations' OR ns='gridex_metering_method_changes' AND tab IN('contract_request_declarations','events')) IS NOT TRUE THEN RAISE EXCEPTION 'contract_copy_exact_source_namespace_required';END IF;
 EXECUTE format('SELECT to_jsonb(x) FROM %I.%I x WHERE id=$1 AND company_id=$2 FOR SHARE',ns,tab) INTO r USING target,c;
 RETURN r IS NOT NULL AND r->>'approved_by' IS NOT NULL AND r->>'approved_at' IS NOT NULL AND(r->>'approved_at')::timestamptz<=clock_timestamp() AND r->>'agreement_original' IS NOT NULL AND r->>'source_original' IS NOT NULL AND encode(sha256(decode(substr(r->>'agreement_original',3),'hex')),'hex')=r->>'agreement_sha256' AND encode(sha256(decode(substr(r->>'source_original',3),'hex')),'hex')=r->>'source_sha256' AND NOT EXISTS(SELECT FROM gridex_ediel_retention.contract_copy_revocations v JOIN gridex_ediel_retention.contract_copy_catalog s USING(retention_class) WHERE v.company_id=c AND v.target_id=target AND s.source_schema=ns AND s.source_table=tab);
END$_$;

--
-- Name: contract_copy_source_current_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_source_current_v1(c uuid, ns text, tab text, target uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k text;BEGIN
    SELECT kind INTO k FROM gridex_contract_source_intake.kinds WHERE source_schema=ns AND source_table=tab;PERFORM gridex_contract_source_intake.lock_target_contract_v1(c,k,target); IF gridex_ediel_retention.contract_copy_source_before_intake_v1(c,ns,tab,target) IS NOT TRUE THEN RETURN false;END IF;
    SELECT kind INTO k FROM gridex_contract_source_intake.kinds WHERE source_schema=ns AND source_table=tab;
    RETURN NOT EXISTS(SELECT FROM gridex_contract_source_intake.qualifications WHERE target_id=target) OR gridex_contract_source_intake.current_v1(c,k,target);
   END$$;

--
-- Name: contract_copy_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_transition_v1(k text, o jsonb, n jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE spec record;target uuid:=(o->>'id')::uuid;c uuid:=(o->>'company_id')::uuid;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;d gridex_ediel_retention.decision_evidence_policies%rowtype;r gridex_ediel_retention.decision_evidence_reviews%rowtype;p jsonb;b jsonb;bytes bytea;at timestamptz;permission text;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.contract_copy_catalog WHERE retention_class=k;
 IF spec.source_table='preparations' THEN
  IF n IS DISTINCT FROM(o-'basis')||jsonb_build_object('basis',gridex_ediel_retention.contract_copy_prepared_redact_v1(o->'basis',spec.body_column)) THEN RETURN false;END IF;bytes:=decode(substr(gridex_ediel_retention.contract_copy_prepared_proof_v1(o->'basis')->>spec.body_column,3),'hex');
 ELSE IF o->>spec.body_column IS NULL OR n->>spec.body_column IS NOT NULL OR(o-spec.body_column) IS DISTINCT FROM(n-spec.body_column) THEN RETURN false;END IF;bytes:=decode(substr(o->>spec.body_column,3),'hex');END IF;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=c;
 IF t.target_id IS NULL OR bytes IS NULL OR encode(sha256(bytes),'hex') IS DISTINCT FROM t.source_hash OR octet_length(bytes) IS DISTINCT FROM t.byte_length OR NOT EXISTS(SELECT FROM gridex_ediel_retention.contract_copy_revocations WHERE retention_class=k AND target_id=target AND company_id=c AND policy_id=t.policy_id AND review_id=t.review_id AND source_hash=t.source_hash AND actor_user_id=t.actor_user_id) THEN RETURN false;END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=t.policy_id FOR UPDATE;SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF r.id IS DISTINCT FROM t.review_id OR r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR d.retention_class IS DISTINCT FROM k OR d.target_id IS DISTINCT FROM target OR d.company_id IS DISTINCT FROM c OR d.source_hash IS DISTINCT FROM t.source_hash OR d.target_metadata_hash IS DISTINCT FROM t.target_metadata_hash THEN RETURN false;END IF;
 b:=gridex_ediel_retention.contract_copy_basis_v1(c,k,target);IF b->>'sourceHash' IS DISTINCT FROM d.source_hash OR b->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash THEN RETURN false;END IF;
 PERFORM gridex_ediel_retention.decision_evidence_actor_v1(c,t.actor_user_id,k,'ediel.retention.purge');PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(c,r.actor_user_id,k);
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);SELECT permission_key INTO STRICT permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 IF p IS NULL OR gridex_ediel_retention.permission_v1(c,t.actor_user_id,'ediel.retention.purge') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,t.actor_user_id,permission) IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,r.actor_user_id,permission) IS NOT TRUE THEN RETURN false;END IF;
 at:=clock_timestamp();RETURN(p->>'retainUntil')::timestamptz<=at AND(p->>'issuedAt')::timestamptz<=at AND(p->>'expiresAt')::timestamptz>at AND(p->>'journalRetainUntil')::timestamptz>at;
END$$;

--
-- Name: contract_copy_view_update_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_view_update_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE spec record;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;changed int;BEGIN
 SELECT s.* INTO STRICT spec FROM gridex_ediel_retention.contract_copy_catalog s WHERE view_name=TG_TABLE_NAME;SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=spec.retention_class AND target_id=OLD.id AND company_id=OLD.company_id;
 IF t.target_id IS NULL OR OLD.document_bytes IS NULL OR NEW.document_bytes IS NOT NULL OR(to_jsonb(OLD)-ARRAY['document_bytes','document_byte_length','document_purged_at']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['document_bytes','document_byte_length','document_purged_at']) OR NEW.document_byte_length IS DISTINCT FROM t.byte_length OR NEW.document_purged_at IS DISTINCT FROM t.created_at THEN RAISE EXCEPTION 'contract_copy_exact_physical_transition_required';END IF;
 IF spec.source_table='preparations' THEN EXECUTE format('UPDATE %I.%I SET basis=gridex_ediel_retention.contract_copy_prepared_redact_v1(basis,$1) WHERE id=$2 AND company_id=$3',spec.source_schema,spec.source_table) USING spec.body_column,OLD.id,OLD.company_id;
 ELSE EXECUTE format('UPDATE %I.%I SET %I=NULL WHERE id=$1 AND company_id=$2',spec.source_schema,spec.source_table,spec.body_column) USING OLD.id,OLD.company_id;END IF;
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'contract_copy_exact_native_row_required';END IF;RETURN NEW;END$_$;

--
-- Name: contract_declarations_retention_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_declarations_retention_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND (gridex_ediel_retention.protected_copy_transition_v1('brp_declaration_agreement_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE OR gridex_ediel_retention.protected_copy_transition_v1('brp_declaration_source_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE) THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: contract_storage_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_storage_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t gridex_ediel_retention.record_tombstones%rowtype;d gridex_ediel_retention.record_decisions%rowtype;basis jsonb;r uuid;actor uuid:=public.ediel_retention_session_actor_v1();BEGIN
 IF TG_OP<>'DELETE' AND new.bucket_id='customer-contract-documents' AND EXISTS(SELECT FROM gridex_ediel_retention.record_tombstones WHERE retention_class='contract_signed_pdf_bytes' AND storage_path=new.name) THEN RAISE EXCEPTION 'contract_pdf_retention_tombstoned';END IF;
 IF (CASE WHEN TG_OP='INSERT' THEN new.bucket_id ELSE old.bucket_id END) IS DISTINCT FROM 'customer-contract-documents' THEN IF TG_OP='DELETE' THEN RETURN old;ELSE RETURN new;END IF;END IF;
 SELECT * INTO t FROM gridex_ediel_retention.record_tombstones WHERE retention_class='contract_signed_pdf_bytes' AND storage_path=(CASE WHEN TG_OP='INSERT' THEN new.name ELSE old.name END);
 IF NOT FOUND THEN IF TG_OP IN('UPDATE','DELETE') AND EXISTS(SELECT FROM public.customer_contract_documents WHERE storage_bucket='customer-contract-documents' AND storage_path=old.name) THEN RAISE EXCEPTION 'contract_pdf_native_class_purge_required';END IF;IF TG_OP='DELETE' THEN RETURN old;ELSE RETURN new;END IF;END IF;
 IF TG_OP<>'DELETE' THEN RAISE EXCEPTION 'contract_pdf_retention_tombstoned';END IF;
 PERFORM gridex_ediel_retention.record_actor_v1(t.company_id,actor,t.retention_class,'ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.record_decisions WHERE id=t.decision_id FOR UPDATE;
 r:=gridex_ediel_retention.record_current_review_v1(d);basis:=gridex_ediel_retention.record_basis_v1(t.company_id,t.retention_class,t.target_id);
 IF r IS NULL OR basis->>'targetHash' IS DISTINCT FROM t.target_hash OR basis->>'storagePath' IS DISTINCT FROM old.name THEN RAISE EXCEPTION 'contract_pdf_current_legal_purge_required';END IF;
 INSERT INTO gridex_ediel_retention.record_events(retention_class,target_id,kind,actor_user_id) VALUES(t.retention_class,t.target_id,'storage_delete_authorized',actor) ON CONFLICT DO NOTHING;RETURN old;
END$$;

--
-- Name: customer_decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.customer_decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_additional_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: gridex_new_public_resource_reference(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_new_public_resource_reference(p_prefix text) RETURNS text
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select lower(regexp_replace(coalesce(p_prefix, 'resource'), '[^a-z0-9_]', '_', 'g'))
    || '_' || replace(gen_random_uuid()::text, '-', '');
$$;

--
-- Name: gridex_normalize_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_email(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select nullif(lower(btrim(coalesce(p_email, ''))), '')
$$;

--
-- Name: gridex_normalize_org_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_org_number(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select nullif(regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g'), '')
$$;

--
-- Name: gridex_normalize_personal_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_personal_number(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select nullif(regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g'), '')
$$;

--
-- Name: gridex_normalize_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_phone(p_phone text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
