$$;

--
-- Name: customers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    customer_type text DEFAULT 'private'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    first_name text,
    last_name text,
    full_name text,
    company_name text,
    personal_number text,
    normalized_personal_number text GENERATED ALWAYS AS (public.gridex_normalize_personal_number(personal_number)) STORED,
    org_number text,
    normalized_org_number text GENERATED ALWAYS AS (public.gridex_normalize_org_number(org_number)) STORED,
    email text,
    normalized_email text GENERATED ALWAYS AS (public.gridex_normalize_email(email)) STORED,
    phone text,
    normalized_phone text GENERATED ALWAYS AS (public.gridex_normalize_phone(phone)) STORED,
    preferred_language text DEFAULT 'sv'::text,
    source text,
    customer_number text,
    apartment_number text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    identity_number text,
    organization_number text,
    name text,
    onboarding_status text,
    activated_at timestamp with time zone,
    ended_at timestamp with time zone,
    acquisition_channel text,
    campaign_id uuid,
    sales_agent_id uuid,
    partner_id uuid,
    onboarding_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    next_action text,
    ready_for_billing_at timestamp with time zone,
    intake_status text,
    intake_missing_fields text[] DEFAULT '{}'::text[] NOT NULL,
    intake_quality_score integer,
    intake_warnings text[] DEFAULT '{}'::text[] NOT NULL,
    is_test_data boolean DEFAULT false NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    archive_reason text,
    anonymized_at timestamp with time zone,
    anonymized_by uuid,
    data_retention_note text,
    external_customer_id text,
    customer_reference text DEFAULT public.gridex_new_public_resource_reference('customer'::text) NOT NULL,
    billing_street text,
    billing_postal_code text,
    billing_city text,
    billing_country text DEFAULT 'SE'::text NOT NULL,
    active_sites integer DEFAULT 0 NOT NULL,
    pending_sites integer DEFAULT 0 NOT NULL,
    blocked_sites integer DEFAULT 0 NOT NULL,
    latest_customer_action text,
    process_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    invoice_email text,
    billing_profile_revision integer DEFAULT 0 NOT NULL,
    moved_out_at date,
    lifecycle_closed_at timestamp with time zone,
    lifecycle_closed_by uuid,
    lifecycle_status_reason text,
    legal_hold boolean DEFAULT false NOT NULL,
    legal_hold_reason text,
    possible_duplicate boolean DEFAULT false,
    duplicate_review_status text,
    merge_status text,
    merged_into_customer_id uuid,
    merged_at timestamp with time zone,
    merged_by uuid,
    CONSTRAINT customers_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text, 'association'::text]))),
    CONSTRAINT customers_intake_quality_score_check CHECK (((intake_quality_score IS NULL) OR ((intake_quality_score >= 0) AND (intake_quality_score <= 100)))),
    CONSTRAINT customers_intake_status_check CHECK (((intake_status IS NULL) OR (intake_status = ANY (ARRAY['draft'::text, 'incomplete'::text, 'needs_completion'::text, 'pending_information'::text, 'pending_power_of_attorney'::text, 'pending_duplicate_review'::text, 'blocked'::text, 'rejected'::text, 'ready_for_contract'::text, 'ready_for_operations'::text, 'application_received'::text, 'needs_contract_or_poa'::text, 'needs_grid_owner_resolution'::text, 'needs_facility_lookup'::text, 'facility_lookup_ready_to_send'::text, 'facility_lookup_waiting_response'::text, 'ready_for_supplier_switch'::text, 'supplier_switch_waiting_response'::text, 'active_supply'::text, 'needs_admin_review'::text])))),
    CONSTRAINT customers_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_verification'::text, 'active'::text, 'inactive'::text, 'moved'::text, 'terminated'::text, 'blocked'::text, 'archived'::text])))
);

