-- Name: customer_personal_fields_v1(public.customers); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.customer_personal_fields_v1(c public.customers) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT to_jsonb(c)-ARRAY['normalized_personal_number','normalized_org_number','normalized_email','normalized_phone','created_at','updated_at','created_by','updated_by','anonymized_at','anonymized_by','data_retention_note']
$$;

--
-- Name: customer_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.customer_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    retention_class text NOT NULL,
    source_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT customer_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT customer_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT customer_decisions_retention_class_check CHECK ((retention_class = 'customer_canonical_personal_fields'::text)),
    CONSTRAINT customer_decisions_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0))))
);

ALTER TABLE ONLY gridex_ediel_retention.customer_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: customer_receipt_v1(gridex_ediel_retention.customer_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.customer_receipt_v1(d gridex_ediel_retention.customer_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;
BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF k.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=k.id) OR EXISTS(SELECT FROM gridex_ediel_retention.customer_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,k.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_customer_retention_policy_v1' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'customerId' IS DISTINCT FROM d.customer_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'issuerLegalReference' IS DISTINCT FROM k.legal_reference OR nullif(p->>'legalBasisReference','') IS NULL
 OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR issued>now() OR expires<=now() OR issued<k.valid_from OR expires>k.valid_to THEN RETURN NULL;END IF;RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: customer_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.customer_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM gridex_ediel_retention.customer_decisions WHERE id=new.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'customer_retention_revocation_target_required';END IF;RETURN new;END$$;

--
-- Name: customer_tombstone_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.customer_tombstone_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t gridex_ediel_retention.customer_tombstones%rowtype;BEGIN
 SELECT * INTO t FROM gridex_ediel_retention.customer_tombstones WHERE customer_id=old.id;
 IF NOT FOUND THEN IF TG_OP='DELETE' THEN RETURN old;ELSE RETURN new;END IF;END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'customer_retention_no_tombstone_cascade';END IF;
 IF new.company_id IS DISTINCT FROM t.company_id OR new.status IS DISTINCT FROM 'archived' OR new.anonymized_at IS DISTINCT FROM t.created_at OR new.anonymized_by IS DISTINCT FROM t.actor_user_id
 OR new.first_name IS NOT NULL OR new.last_name IS NOT NULL OR new.full_name IS DISTINCT FROM 'Pseudonymiserad kund' OR new.company_name IS NOT NULL OR new.personal_number IS NOT NULL OR new.org_number IS NOT NULL OR new.email IS NOT NULL OR new.phone IS NOT NULL OR new.apartment_number IS NOT NULL OR new.identity_number IS NOT NULL OR new.organization_number IS NOT NULL OR new.name IS DISTINCT FROM 'Pseudonymiserad kund' OR new.billing_street IS NOT NULL OR new.billing_postal_code IS NOT NULL OR new.billing_city IS NOT NULL OR new.metadata IS DISTINCT FROM '{}'::jsonb OR new.onboarding_issues IS DISTINCT FROM '[]'::jsonb OR new.intake_missing_fields IS DISTINCT FROM '{}'::text[] OR new.intake_warnings IS DISTINCT FROM '{}'::text[] OR new.process_summary IS DISTINCT FROM '{}'::jsonb OR new.archive_reason IS NOT NULL OR new.next_action IS NOT NULL OR new.latest_customer_action IS NOT NULL THEN RAISE EXCEPTION 'customer_retention_personal_fields_tombstoned';END IF;RETURN new;
END$$;

--
-- Name: decision_evidence_actor_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_actor_v1(c uuid, actor uuid, k text, operation text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE permission text;BEGIN
 IF operation='ediel.retention.read' THEN PERFORM gridex_ediel_retention.record_read_actor_v1(c,actor);ELSE PERFORM gridex_ediel_retention.actor_v1(c,actor,operation);END IF;
 SELECT permission_key INTO STRICT permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 IF gridex_ediel_retention.permission_v1(c,actor,permission) IS NOT TRUE THEN RAISE EXCEPTION 'decision_evidence_current_class_grant_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: decision_evidence_additional_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_additional_transition_v1(tab text, o jsonb, n jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k text;permission text;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;d gridex_ediel_retention.decision_evidence_policies%rowtype;r gridex_ediel_retention.decision_evidence_reviews%rowtype;p jsonb;b jsonb;at timestamptz;BEGIN
 SELECT retention_class,permission_key INTO k,permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE source_table=tab AND retention_class IN('invoice_file_retention_decision_original_bytes','customer_retention_decision_original_bytes');
 IF k IS NULL OR gridex_ediel_retention.decision_evidence_transition_v1(tab,o,n) IS NOT TRUE THEN RETURN false;END IF;
 SELECT * INTO STRICT t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=(o->>'id')::uuid AND company_id=(o->>'company_id')::uuid;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=t.policy_id FOR UPDATE;
 SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF r.id IS DISTINCT FROM t.review_id OR r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR d.company_id IS DISTINCT FROM t.company_id OR d.retention_class IS DISTINCT FROM k OR d.target_id IS DISTINCT FROM t.target_id OR d.source_hash IS DISTINCT FROM t.source_hash OR d.target_metadata_hash IS DISTINCT FROM t.target_metadata_hash THEN RETURN false;END IF;
 b:=gridex_ediel_retention.decision_evidence_basis_v1(t.company_id,k,t.target_id);IF b->>'sourceHash' IS DISTINCT FROM d.source_hash OR b->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash THEN RETURN false;END IF;
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;
 PERFORM gridex_ediel_retention.decision_evidence_actor_v1(t.company_id,t.actor_user_id,k,'ediel.retention.purge');PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(t.company_id,r.actor_user_id,k);
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;
 IF gridex_ediel_retention.permission_v1(t.company_id,t.actor_user_id,'ediel.retention.purge') IS NOT TRUE OR gridex_ediel_retention.permission_v1(t.company_id,t.actor_user_id,permission) IS NOT TRUE OR gridex_ediel_retention.permission_v1(t.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(t.company_id,r.actor_user_id,permission) IS NOT TRUE THEN RETURN false;END IF;
 at:=clock_timestamp();RETURN (p->>'retainUntil')::timestamptz<=at AND(p->>'issuedAt')::timestamptz<=at AND(p->>'expiresAt')::timestamptz>at AND(p->>'journalRetainUntil')::timestamptz>at;
END$$;

--
-- Name: decision_evidence_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE tab text;r jsonb;bytes bytea;BEGIN
 IF k IN('life_event_classification_source_original_bytes','life_event_classification_receipt_original_bytes','life_event_classification_revocation_original_bytes') THEN RETURN gridex_ediel_retention.classification_copy_basis_v1(c,k,target);END IF; IF k IN('masterdata_declaration_agreement_original_bytes','masterdata_declaration_source_original_bytes','masterdata_preparation_agreement_original_bytes','masterdata_preparation_source_original_bytes','metering_contract_request_agreement_original_bytes','metering_contract_request_source_original_bytes','metering_method_event_agreement_original_bytes','metering_method_event_source_original_bytes') THEN RETURN gridex_ediel_retention.contract_copy_basis_v1(c,k,target);END IF; IF EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=k) THEN RETURN gridex_ediel_retention.protected_copy_basis_v1(c,k,target);END IF; SELECT source_table INTO STRICT tab FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 EXECUTE format('SELECT to_jsonb(d),d.document_bytes FROM gridex_ediel_retention.%I d WHERE id=$1 AND company_id=$2 FOR UPDATE',tab) INTO r,bytes USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 IF bytes IS NULL OR octet_length(bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(bytes),'hex') IS DISTINCT FROM r->>'document_hash' THEN RAISE EXCEPTION 'decision_evidence_actual_original_bytes_required';END IF;
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'byteLength',octet_length(bytes));
END$_$;

--
-- Name: decision_evidence_lock_reviewer_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_lock_reviewer_v1(c uuid, actor uuid, k text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE permission text;BEGIN
 IF public.ediel_retention_lock_auth_actor_v1(actor) IS NOT TRUE THEN RAISE EXCEPTION 'decision_evidence_current_reviewer_required' USING ERRCODE='42501';END IF;
 PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 SELECT permission_key INTO STRICT permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active' AND to_jsonb(u)->>'disabled_at' IS NULL) OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(c,actor,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,actor,permission) IS NOT TRUE THEN RAISE EXCEPTION 'decision_evidence_current_reviewer_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: decision_evidence_lock_v1(uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_lock_v1(c uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$SELECT pg_advisory_xact_lock(hashtextextended('gridex:retention:decision-original:'||c::text,0))$$;

--
-- Name: decision_evidence_original_insert_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_original_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.document_bytes IS NULL OR NEW.document_purged_at IS NOT NULL OR octet_length(NEW.document_bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(NEW.document_bytes),'hex') IS DISTINCT FROM NEW.document_hash OR NEW.document_byte_length IS NOT NULL AND NEW.document_byte_length<>octet_length(NEW.document_bytes) THEN RAISE EXCEPTION 'decision_original_new_actual_bytes_required';END IF;RETURN NEW;
END$$;

--
-- Name: decision_evidence_policies_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_policies_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: decision_evidence_policies; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.decision_evidence_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id uuid NOT NULL,
    source_hash text NOT NULL,
    target_metadata_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT decision_evidence_policies_check CHECK ((target_id <> id)),
    CONSTRAINT decision_evidence_policies_check1 CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT decision_evidence_policies_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT decision_evidence_policies_document_hash_check CHECK ((document_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT decision_evidence_policies_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT decision_evidence_policies_target_metadata_hash_check CHECK ((target_metadata_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.decision_evidence_policies FORCE ROW LEVEL SECURITY;

--
-- Name: decision_evidence_policy_current_v1(gridex_ediel_retention.decision_evidence_policies); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_policy_current_v1(d gridex_ediel_retention.decision_evidence_policies) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r gridex_ediel_retention.decision_evidence_reviews%rowtype;b jsonb;BEGIN
 IF gridex_ediel_retention.decision_evidence_receipt_v1(d) IS NULL OR EXISTS(SELECT FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id) THEN RETURN false;END IF;
 SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by THEN RETURN false;END IF;
 PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(d.company_id,r.actor_user_id,d.retention_class);b:=gridex_ediel_retention.decision_evidence_basis_v1(d.company_id,d.retention_class,d.target_id);RETURN b->>'sourceHash'=d.source_hash AND b->>'targetMetadataHash'=d.target_metadata_hash;
EXCEPTION WHEN insufficient_privilege THEN RETURN false;WHEN raise_exception THEN IF SQLERRM IN('decision_evidence_actual_original_bytes_required','decision_evidence_original_scope_required') THEN RETURN false;END IF;RAISE;
END$$;

--
-- Name: decision_evidence_read_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_read_actor_v1(c uuid, actor uuid, k text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE operation text;BEGIN
 IF gridex_ediel_retention.record_permission_v1(c,actor,'__read_scope__') IS TRUE THEN operation:='ediel.retention.read';
 ELSIF gridex_ediel_retention.permission_v1(c,actor,'ediel.retention.review') IS TRUE THEN operation:='ediel.retention.review';
 ELSIF gridex_ediel_retention.permission_v1(c,actor,'ediel.retention.submit') IS TRUE THEN operation:='ediel.retention.submit';ELSE operation:='ediel.retention.purge';END IF;
 PERFORM gridex_ediel_retention.decision_evidence_actor_v1(c,actor,k,operation);
END$$;

--
-- Name: decision_evidence_receipt_v1(gridex_ediel_retention.decision_evidence_policies); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_receipt_v1(d gridex_ediel_retention.decision_evidence_policies) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;BEGIN
 IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash OR jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF issuer.id IS NULL OR encode(sha256(issuer.legal_evidence),'hex') IS DISTINCT FROM issuer.legal_hash OR clock_timestamp()<issuer.valid_from OR clock_timestamp()>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.decision_evidence_revocations WHERE policy_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;journal_end:=(p->>'journalRetainUntil')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_retention_decision_original_policy_v1' OR p->>'operation' IS DISTINCT FROM 'erase_retention_decision_original_bytes' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'targetId' IS DISTINCT FROM d.target_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference OR nullif(btrim(p->>'legalBasisReference'),'') IS NULL OR nullif(btrim(p->>'journalPurposeReference'),'') IS NULL OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR issued>clock_timestamp() OR expires<=clock_timestamp() OR issued<issuer.valid_from OR expires>issuer.valid_to OR journal_end<=clock_timestamp() OR journal_end<deadline THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: decision_evidence_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM gridex_ediel_retention.decision_evidence_policies WHERE id=NEW.policy_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_revocation_original_required';END IF;RETURN NEW;
END$$;

--
-- Name: decision_evidence_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decision_evidence_transition_v1(tab text, o jsonb, n jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k text;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN
 SELECT retention_class INTO k FROM gridex_ediel_retention.decision_evidence_catalog WHERE source_table=tab;SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=(o->>'id')::uuid AND company_id=(o->>'company_id')::uuid;
 RETURN t.target_id IS NOT NULL AND o->>'document_bytes' IS NOT NULL AND n->>'document_bytes' IS NULL AND (n->>'document_purged_at')::timestamptz=t.created_at AND (n->>'document_byte_length')::bigint=t.byte_length AND o->>'document_hash'=t.source_hash AND encode(sha256(convert_to((o-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex')=t.target_metadata_hash AND (o-ARRAY['document_bytes','document_byte_length','document_purged_at'])=(n-ARRAY['document_bytes','document_byte_length','document_purged_at']);
END$$;

--
-- Name: decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: finance_actor_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_actor_v1(c uuid, actor uuid, k text, op text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE key text;BEGIN
 SELECT permission_key INTO STRICT key FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=k;
 IF op='ediel.retention.read' THEN PERFORM gridex_ediel_retention.record_read_actor_v1(c,actor);ELSE PERFORM gridex_ediel_retention.actor_v1(c,actor,op);END IF;
 IF gridex_ediel_retention.permission_v1(c,actor,key) IS NOT TRUE THEN RAISE EXCEPTION 'finance_retention_current_exact_class_required' USING ERRCODE='42501';END IF;END$$;

--
-- Name: finance_basis_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_basis_v1(c uuid, k text, target text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;r jsonb;body jsonb;underlay jsonb;invoice jsonb;item jsonb;settlement jsonb;ref uuid;customer uuid;start_at timestamptz;end_at timestamptz;scope jsonb;included_ids uuid[];closed boolean;source_bound boolean:=false;original_sha text;node record;scope_company uuid;scope_customer uuid;included_ref uuid;finance_graph jsonb;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=k;
 IF target!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' AND NOT(spec.source_table='portfolio_settlement_audit_log' AND target~'^[1-9][0-9]{0,18}$') THEN RAISE EXCEPTION 'finance_retention_actual_selector_required';END IF;
 IF EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones WHERE retention_class=k AND target_id=target AND company_id=c) THEN RAISE EXCEPTION 'finance_copy_retention_tombstoned';END IF;
 EXECUTE format('SELECT to_jsonb(x) FROM %I.%I x WHERE %I::text=$1 AND company_id=$2 FOR SHARE',spec.source_schema,spec.source_table,spec.id_column) INTO r USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'finance_retention_actual_source_required';END IF;
 SELECT jsonb_object_agg(col,r->col) INTO body FROM unnest(spec.body_columns)col;
 IF octet_length(body::text) NOT BETWEEN 1 AND 20971520 OR body@>'{"retentionUnavailable":true}' THEN RAISE EXCEPTION 'finance_retention_actual_body_required';END IF;
 -- All period selectors come from real native relationships, never policy JSON.
 IF spec.source_kind='invoice' THEN invoice:=r;
 ELSIF spec.source_kind='invoice_line' THEN SELECT to_jsonb(x) INTO invoice FROM public.customer_invoices x WHERE id=(r->>'invoice_id')::uuid AND company_id=c FOR SHARE;
 ELSIF spec.source_kind='item' THEN item:=r;
 ELSIF spec.source_kind IN('item_child','provider_event') THEN ref:=coalesce(r->>'invoice_export_item_id',r->>'matched_invoice_export_item_id')::uuid;SELECT to_jsonb(x) INTO item FROM public.invoice_export_items x WHERE id=ref AND company_id=c FOR SHARE;
 ELSIF spec.source_kind='settlement' THEN settlement:=r;
 ELSIF spec.source_kind='settlement_child' THEN ref:=coalesce(r->>'settlement_id',r->>'portfolio_monthly_settlement_id')::uuid;SELECT to_jsonb(x) INTO settlement FROM public.portfolio_monthly_settlements x WHERE id=ref AND company_id=c FOR SHARE;END IF;
 IF spec.source_kind IN('underlay','underlay_child') THEN ref:=CASE WHEN spec.source_kind='underlay' THEN (r->>spec.id_column)::uuid ELSE (r->>'billing_underlay_id')::uuid END;
 ELSE ref:=coalesce(invoice->>'billing_underlay_id',item->>'billing_underlay_id',r->>'billing_underlay_id')::uuid;END IF;
 IF ref IS NOT NULL THEN SELECT to_jsonb(x) INTO underlay FROM public.billing_underlays x WHERE id=ref AND company_id=c FOR SHARE;END IF;
 IF underlay IS NOT NULL THEN
  customer:=(underlay->>'customer_id')::uuid;start_at:=(underlay->>'billing_period_start')::timestamptz;end_at:=(underlay->>'billing_period_end')::timestamptz;
  SELECT source_basis_hash INTO original_sha FROM gridex_billing_source.underlay_bindings WHERE underlay_id=ref AND company_id=c AND (source_basis_hash=encode(sha256(convert_to(source_basis::text,'UTF8')),'hex') OR EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones t WHERE t.retention_class='billing_underlay_source_body' AND t.target_id=ref::text AND t.company_id=c));source_bound:=original_sha IS NOT NULL;
 ELSIF settlement IS NOT NULL THEN start_at:=(settlement->>'delivery_month')::date::timestamptz;end_at:=start_at+interval '1 month';original_sha:=settlement->>'calculation_snapshot_sha256';source_bound:=settlement->>'status'='locked' AND (original_sha=encode(sha256(convert_to((settlement->'calculation_snapshot')::text,'UTF8')),'hex') OR EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones t WHERE t.retention_class='settlement_calculation_body' AND t.target_id=settlement->>'id' AND t.company_id=c));
 ELSIF spec.source_kind='run' AND r->>'billing_month'~'^\d{4}-\d{2}$' THEN
  start_at:=(r->>'billing_month'||'-01')::date::timestamptz;end_at:=start_at+interval '1 month';
  SELECT count(*)>0 AND bool_and(b.underlay_id IS NOT NULL AND (b.source_basis_hash=encode(sha256(convert_to(b.source_basis::text,'UTF8')),'hex') OR EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones t WHERE t.company_id=c AND t.retention_class='billing_underlay_source_body' AND t.target_id=b.underlay_id::text))),encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('itemId',i.id,'underlayId',i.billing_underlay_id,'sourceHash',b.source_basis_hash) ORDER BY i.id),'[]')::text,'UTF8')),'hex') INTO source_bound,original_sha FROM public.invoice_export_items i LEFT JOIN gridex_billing_source.underlay_bindings b ON b.underlay_id=i.billing_underlay_id AND b.company_id=c WHERE i.company_id=c AND i.export_run_id=(r->>'id')::uuid;
 END IF;
 IF start_at IS NULL OR end_at IS NULL OR NOT isfinite(start_at) OR NOT isfinite(end_at) OR end_at<=start_at THEN RAISE EXCEPTION 'finance_retention_native_exact_period_required';END IF;
 LOCK TABLE public.customers,public.customer_supply_periods,public.customer_invoices,public.invoice_export_items,public.invoice_export_attempts IN SHARE ROW EXCLUSIVE MODE;
 IF customer IS NULL THEN SELECT coalesce(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO included_ids FROM public.customers WHERE company_id=c;ELSE included_ids:=ARRAY[customer];END IF;
 -- Decode actual stored native copy references. A known foreign included
 -- customer/contract/message cannot be hidden by the row's customer selector.
 FOR node IN SELECT * FROM gridex_ediel_retention.process_nodes_v1(body) LOOP
  IF node.key IN('companyId','company_id') AND jsonb_typeof(node.value)='string' AND (node.value#>>'{}') IS DISTINCT FROM c::text THEN RAISE EXCEPTION 'finance_retention_foreign_included_scope';END IF;
  IF node.key IN('customerId','customer_id','contractId','contract_id','customer_contract_id','sourceMessageId','source_message_id','messageId','originalMessageId') AND jsonb_typeof(node.value)='string' THEN
   BEGIN included_ref:=(node.value#>>'{}')::uuid;EXCEPTION WHEN invalid_text_representation THEN CONTINUE;END;
   scope_company:=NULL;scope_customer:=NULL;
   IF node.key IN('customerId','customer_id') THEN SELECT company_id,id INTO scope_company,scope_customer FROM public.customers WHERE id=included_ref;
   ELSIF node.key IN('contractId','contract_id','customer_contract_id') THEN SELECT company_id,customer_id INTO scope_company,scope_customer FROM public.customer_contracts WHERE id=included_ref;
   ELSE SELECT company_id,customer_id INTO scope_company,scope_customer FROM public.ediel_messages WHERE id=included_ref;END IF;
   IF scope_company IS NOT NULL AND scope_company IS DISTINCT FROM c THEN RAISE EXCEPTION 'finance_retention_foreign_included_scope';END IF;
  END IF;
 END LOOP;
 -- Free text and provider/aggregate copies are not an exhaustive caller list.
 -- Qualify the conservative real company population and its open finance graph.
 SELECT coalesce(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO included_ids FROM public.customers WHERE company_id=c;
 IF cardinality(included_ids)>10000 THEN RAISE EXCEPTION 'finance_retention_included_scope_bound';END IF;
 IF EXISTS(SELECT FROM public.customers WHERE id=ANY(included_ids) AND company_id IS DISTINCT FROM c) THEN RAISE EXCEPTION 'finance_retention_foreign_included_scope';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('customerId',x.id,'status',x.status,'supplies',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') FROM public.customer_supply_periods s WHERE s.company_id=c AND s.customer_id=x.id),'invoices',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'status',i.status) ORDER BY i.id),'[]') FROM public.customer_invoices i WHERE i.company_id=c AND i.customer_id=x.id)) ORDER BY x.id),'[]'),coalesce(bool_and(x.status='archived'),true) INTO scope,closed FROM public.customers x WHERE x.company_id=c AND id=ANY(included_ids);
 closed:=closed AND source_bound AND end_at<=clock_timestamp()
 AND NOT EXISTS(SELECT FROM public.customer_supply_periods s WHERE s.company_id=c AND s.customer_id=ANY(included_ids) AND s.status NOT IN('cancelled','rejected','terminated','ended','closed','inactive') AND (coalesce(s.actual_end_date,s.end_date) IS NULL OR coalesce(s.actual_end_date,s.end_date)>=current_date))
 AND NOT EXISTS(SELECT FROM public.customer_invoices i WHERE i.company_id=c AND i.customer_id=ANY(included_ids) AND i.status NOT IN('paid','cancelled','void','credited'))
 AND NOT EXISTS(SELECT FROM public.invoice_export_items i WHERE i.company_id=c AND i.customer_id=ANY(included_ids) AND (i.status IS NULL OR upper(i.status) NOT IN('SENT','CREDITED','CANCELLED','REJECTED')))
 AND NOT EXISTS(SELECT FROM public.invoice_export_attempts a JOIN public.invoice_export_items i ON i.id=a.invoice_export_item_id WHERE i.company_id=c AND i.customer_id=ANY(included_ids) AND a.finished_at IS NULL);
 SELECT coalesce(jsonb_agg(jsonb_build_object('itemId',i.id,'customerId',i.customer_id,'underlayId',i.billing_underlay_id,'runId',i.export_run_id,'status',i.status,'sourceHash',b.source_basis_hash,'attempts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'finishedAt',a.finished_at) ORDER BY a.id),'[]') FROM public.invoice_export_attempts a WHERE a.company_id=c AND a.invoice_export_item_id=i.id)) ORDER BY i.id),'[]') INTO finance_graph FROM public.invoice_export_items i LEFT JOIN gridex_billing_source.underlay_bindings b ON b.underlay_id=i.billing_underlay_id AND b.company_id=c WHERE i.company_id=c;
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceTable',spec.source_schema||'.'||spec.source_table,'bodyColumns',spec.body_columns,'sourceHash',encode(sha256(convert_to(body::text,'UTF8')),'hex'),'targetHash',encode(sha256(convert_to(r::text,'UTF8')),'hex'),'scopeHash',encode(sha256(convert_to(jsonb_build_object('companyId',c,'customers',scope,'financialGraph',finance_graph,'periodStart',start_at,'periodEnd',end_at,'sourceBound',source_bound,'originalProducerHash',original_sha)::text,'UTF8')),'hex'),'periodStart',start_at,'periodEnd',end_at,'originalProducerHash',original_sha,'byteLength',octet_length(body::text),'includedCustomers',included_ids,'allIncludedScopesClosed',closed,'sourceBound',source_bound,'complete',false,'authority','none');END$_$;

--
-- Name: finance_decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: finance_fresh_consumption_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_fresh_consumption_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb:=to_jsonb(NEW);source uuid;BEGIN
 IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),r) IS TRUE THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='portfolio_monthly_settlements' THEN source:=(r->>'supersedes_settlement_id')::uuid;IF source IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(NEW.company_id,'settlement_calculation_body',source::text);END IF;
 ELSE source:=(r->>'billing_underlay_id')::uuid;IF source IS NOT NULL THEN PERFORM public.ediel_require_invoice_source_copies_available_v1(NEW.company_id,source);END IF;END IF;RETURN NEW;END$$;

