--
-- Name: finance_guard_v1_4b456f7ba70048a2ee25293af993be96(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_4b456f7ba70048a2ee25293af993be96() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if old.billing_configuration_snapshot_sha256 is not null
     and (
       new.billing_configuration_snapshot is distinct from old.billing_configuration_snapshot
       or new.billing_configuration_snapshot_sha256 is distinct from old.billing_configuration_snapshot_sha256
       or new.billing_configuration_snapshotted_at is distinct from old.billing_configuration_snapshotted_at
     ) then
    raise exception 'billing_configuration_snapshot_is_immutable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

