--
-- Name: finance_guard_v1_7ddb10144d6f8333b9c1b21ecec204e6(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_7ddb10144d6f8333b9c1b21ecec204e6() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if tg_op='DELETE' or old.customer_invoice_id is not null
     or new.customer_invoice_id is null
     or new.invoice_idempotency_key is null
     or (to_jsonb(new)-'customer_invoice_id'-'invoice_idempotency_key')
       <>(to_jsonb(old)-'customer_invoice_id'-'invoice_idempotency_key') then
    raise exception using errcode='55000',message='portfolio_invoice_binding_immutable';
  end if;
  return new;
end $$;

--
-- Name: finance_guard_v1_920138d4568f5425448044a4962765ea(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_920138d4568f5425448044a4962765ea() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
declare
  protected boolean;
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if coalesce(current_setting('app.gridex_billing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  protected := old.status in ('sent', 'credited');

  if tg_op = 'DELETE' then
    if protected then
      raise exception 'Skickade/krediterade fakturaexportposter kan inte raderas (item %). Skapa kredit eller korrigering i stället.', old.id
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if not protected then
    return new;
  end if;

  -- Block re-send: status must never go back to a sendable state.
  if new.status in ('pending', 'failed', 'failed_retryable') then
    raise exception 'Fakturaexportpost % är redan skickad och kan inte skickas om. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Block financial mutation of a sent invoice.
  if new.amount_ex_vat is distinct from old.amount_ex_vat
     or new.vat_amount is distinct from old.vat_amount
     or new.amount_inc_vat is distinct from old.amount_inc_vat
     or new.rounding_amount is distinct from old.rounding_amount
     or new.request_payload is distinct from old.request_payload
     or new.idempotency_key is distinct from old.idempotency_key
     or new.pricing_run_id is distinct from old.pricing_run_id
     or new.billing_underlay_id is distinct from old.billing_underlay_id
     or new.customer_id is distinct from old.customer_id
  then
    raise exception 'Fakturaexportpost % är skickad och får inte ändras finansiellt. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Provider invoice identity may be set once but never rewritten.
  if old.provider_invoice_guid is not null
     and new.provider_invoice_guid is distinct from old.provider_invoice_guid
  then
    raise exception 'Fakturaexportpost % har redan ett leverantörs-id och det får inte skrivas om.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

--
-- Name: finance_guard_v1_af0ed0f697cd8415944398b0334f752d(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_af0ed0f697cd8415944398b0334f752d() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if tg_op = 'UPDATE' and old.status in ('issued', 'sent', 'exported', 'paid') and (
    new.portfolio_id is distinct from old.portfolio_id
    or new.customer_contract_id is distinct from old.customer_contract_id
    or new.price_plan_version_id is distinct from old.price_plan_version_id
    or new.portfolio_monthly_settlement_id is distinct from old.portfolio_monthly_settlement_id
    or new.portfolio_settlement_revision is distinct from old.portfolio_settlement_revision
    or new.portfolio_settlement_sha256 is distinct from old.portfolio_settlement_sha256
    or new.portfolio_settlement_snapshot is distinct from old.portfolio_settlement_snapshot
    or new.portfolio_price_area_code is distinct from old.portfolio_price_area_code
    or new.portfolio_delivery_month is distinct from old.portfolio_delivery_month
    or new.portfolio_price_ore_per_kwh is distinct from old.portfolio_price_ore_per_kwh
    or new.portfolio_management_fee_ore_per_kwh is distinct from old.portfolio_management_fee_ore_per_kwh
    or new.portfolio_gross_energy_cost_sek is distinct from old.portfolio_gross_energy_cost_sek
    or new.portfolio_energy_volume_kwh is distinct from old.portfolio_energy_volume_kwh
    or new.delivery_month is distinct from old.delivery_month
    or new.price_area_code is distinct from old.price_area_code
    or new.consumption_kwh is distinct from old.consumption_kwh
    or new.portfolio_share_percent is distinct from old.portfolio_share_percent
    or new.spot_share_percent is distinct from old.spot_share_percent
    or new.fixed_share_percent is distinct from old.fixed_share_percent
    or new.fixed_price_sek_per_kwh is distinct from old.fixed_price_sek_per_kwh
    or new.portfolio_energy_cost_sek is distinct from old.portfolio_energy_cost_sek
    or new.spot_energy_cost_sek is distinct from old.spot_energy_cost_sek
    or new.fixed_energy_cost_sek is distinct from old.fixed_energy_cost_sek
    or new.management_fee_sek is distinct from old.management_fee_sek
    or new.other_fees_sek is distinct from old.other_fees_sek
    or new.vat_rate is distinct from old.vat_rate
    or new.calculation_snapshot is distinct from old.calculation_snapshot
    or new.calculation_snapshot_sha256 is distinct from old.calculation_snapshot_sha256
  ) then
    raise exception using errcode = '55000', message = 'issued_invoice_portfolio_evidence_immutable';
  end if;

  if new.status in ('issued', 'sent', 'exported', 'paid')
     and new.portfolio_id is not null
     and (
       new.portfolio_monthly_settlement_id is null
       or new.portfolio_settlement_status <> 'locked'
       or nullif(new.portfolio_settlement_sha256, '') is null
       or coalesce(new.portfolio_settlement_snapshot, '{}'::jsonb) = '{}'::jsonb
       or new.customer_contract_id is null
       or new.price_plan_version_id is null
       or new.delivery_month is null
       or new.price_area_code is null
       or new.consumption_kwh is null
       or new.portfolio_share_percent is null
       or new.spot_share_percent is null
       or new.fixed_share_percent is null
       or abs(
         new.portfolio_share_percent
         + new.spot_share_percent
         + new.fixed_share_percent
         - 100
       ) > 0.000001
       or new.portfolio_energy_cost_sek is null
       or new.spot_energy_cost_sek is null
       or new.fixed_energy_cost_sek is null
       or (new.fixed_share_percent > 0 and new.fixed_price_sek_per_kwh is null)
       or new.management_fee_sek is null
       or new.other_fees_sek is null
       or new.vat_rate is null
       or nullif(new.calculation_snapshot_sha256, '') is null
       or coalesce(new.calculation_snapshot, '{}'::jsonb) = '{}'::jsonb
     ) then
    raise exception using errcode = '23514', message = 'final_invoice_requires_locked_portfolio_settlement_evidence';
  end if;
  return new;
end $$;

--
-- Name: finance_guard_v1_b73f12ceefeb096bb3e00fe783ed6214(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_b73f12ceefeb096bb3e00fe783ed6214() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT FROM gridex_billing_source.underlay_bindings WHERE underlay_id=old.id) AND (tg_op='DELETE' OR
  ROW(new.company_id,new.customer_id,new.metering_point_id,new.supply_period_id,new.contract_id,new.pricing_snapshot_id,new.contract_price_snapshot_id,new.total_kwh,new.billing_period_start,new.billing_period_end,new.payload,new.pricing_snapshot,new.energy_direction,new.settlement_type)
  IS DISTINCT FROM ROW(old.company_id,old.customer_id,old.metering_point_id,old.supply_period_id,old.contract_id,old.pricing_snapshot_id,old.contract_price_snapshot_id,old.total_kwh,old.billing_period_start,old.billing_period_end,old.payload,old.pricing_snapshot,old.energy_direction,old.settlement_type)) THEN RAISE EXCEPTION 'billing_source_finalized_underlay_immutable' USING ERRCODE='55000'; END IF;
 RETURN CASE WHEN tg_op='DELETE' THEN old ELSE new END;
END $$;

--
-- Name: finance_guard_v1_fdc2215667d256f07f3c0fbb40e0d73f(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_guard_v1_fdc2215667d256f07f3c0fbb40e0d73f() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if tg_op='DELETE' then raise exception using errcode='55000',message='portfolio_settlement_append_only'; end if;
  if old.status<>new.status and not (
    (old.status='draft' and new.status='calculated')
    or (old.status='calculated' and new.status='reviewed')
    or (old.status='reviewed' and new.status='final')
    or (old.status='final' and new.status='locked')
  ) then
    raise exception using errcode='23514',message='invalid_portfolio_settlement_transition';
  end if;
  if new.status in('final','locked') and (
    new.portfolio_price_ore_per_kwh is null
    or new.calculation_snapshot_sha256 is null
    or new.calculated_at is null or new.reviewed_at is null or new.approved_at is null
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_final_evidence_incomplete';
  end if;
  if old.status='locked' and not (
    coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
    and new.is_current=false and new.superseded_by_settlement_id is not null
    and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')=(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
  ) then
    raise exception using errcode='55000',message='locked_portfolio_settlement_immutable';
  end if;
  if old.status='final' and not (
    (
      new.status='locked'
      and (to_jsonb(new)-'status'-'locked_by'-'locked_at')
        =(to_jsonb(old)-'status'-'locked_by'-'locked_at')
    ) or (
      coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
      and new.status='final' and new.is_current=false
      and new.superseded_by_settlement_id is not null
      and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')
        =(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
    )
  ) then
    raise exception using errcode='55000',message='final_portfolio_settlement_immutable_create_correction_revision';
  end if;
  return new;
end $$;

--
-- Name: finance_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.finance_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id text NOT NULL,
    source_hash text NOT NULL,
    target_hash text NOT NULL,
    scope_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT finance_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT finance_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT finance_decisions_scope_hash_check CHECK ((scope_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT finance_decisions_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT finance_decisions_target_hash_check CHECK ((target_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.finance_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: finance_receipt_v1(gridex_ediel_retention.finance_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_receipt_v1(d gridex_ediel_retention.finance_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;operation text;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF issuer.id IS NULL OR now()<issuer.valid_from OR now()>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.finance_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;journal_end:=(p->>'journalRetainUntil')::timestamptz;
 SELECT x.operation INTO STRICT operation FROM gridex_ediel_retention.finance_class_catalog x WHERE retention_class=d.retention_class;
 IF p->>'format' IS DISTINCT FROM 'ediel_finance_copy_retention_policy_v1' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'targetId' IS DISTINCT FROM d.target_id OR p->>'companyId' IS DISTINCT FROM d.company_id::text
 OR p->>'sourceTable' IS DISTINCT FROM (SELECT source_schema||'.'||source_table FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=d.retention_class)
 OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetHash' IS DISTINCT FROM d.target_hash OR p->>'scopeHash' IS DISTINCT FROM d.scope_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'operation' IS DISTINCT FROM operation
 OR p->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference OR nullif(p->>'legalBasisReference','') IS NULL OR nullif(p->>'journalPurposeReference','') IS NULL OR p->>'accessRevocationRequired' IS DISTINCT FROM 'true'
 OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR journal_end<=now() OR issued>now() OR expires<=now() OR issued<issuer.valid_from OR expires>issuer.valid_to THEN RETURN NULL;END IF;RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;END$_$;

--
-- Name: finance_redacted_v1(text, jsonb, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_redacted_v1(k text, oldrow jsonb, hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;col text;type oid;marker jsonb:=jsonb_build_object('retentionUnavailable',true,'sourceHash',hash,'complete',false,'authority','none');result jsonb:=oldrow;BEGIN SELECT * INTO STRICT spec FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=k;FOREACH col IN ARRAY spec.body_columns LOOP SELECT atttypid INTO STRICT type FROM pg_attribute WHERE attrelid=format('%I.%I',spec.source_schema,spec.source_table)::regclass AND attname=col;result:=jsonb_set(result,ARRAY[col],CASE WHEN type='jsonb'::regtype THEN marker ELSE to_jsonb(marker::text) END);END LOOP;RETURN result;END$$;

--
-- Name: finance_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_ediel_retention.finance_decisions WHERE id=NEW.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'finance_retention_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: finance_target_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.finance_target_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;r jsonb;BEGIN SELECT * INTO STRICT spec FROM gridex_ediel_retention.finance_class_catalog WHERE source_schema=TG_TABLE_SCHEMA AND source_table=TG_TABLE_NAME;r:=CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END;IF EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones WHERE retention_class=spec.retention_class AND target_id=r->>spec.id_column) AND NOT(TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW))) THEN RAISE EXCEPTION 'finance_copy_retention_tombstoned';END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END$$;

--
-- Name: inbound_classifications_classification_copy_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.inbound_classifications_classification_copy_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND (gridex_ediel_retention.classification_copy_transition_v1('life_event_classification_source_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE OR gridex_ediel_retention.classification_copy_transition_v1('life_event_classification_receipt_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE) THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: invoice_file_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_actor_v1(c uuid, actor uuid, op text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF op='ediel.retention.read' THEN PERFORM gridex_ediel_retention.record_read_actor_v1(c,actor);ELSE PERFORM gridex_ediel_retention.actor_v1(c,actor,op);END IF;
 IF gridex_ediel_retention.permission_v1(c,actor,'ediel.retention.invoice_copy_evidence') IS NOT TRUE THEN RAISE EXCEPTION 'invoice_file_current_exact_class_required' USING ERRCODE='42501';END IF;END$$;

--
-- Name: invoice_file_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s gridex_ediel_retention.invoice_file_sources%rowtype;spec record;r jsonb;invoice jsonb;item jsonb;underlay jsonb;binding jsonb;scope jsonb;customer uuid;start_at timestamptz;end_at timestamptz;closed boolean;BEGIN
 SELECT * INTO STRICT s FROM gridex_ediel_retention.invoice_file_sources WHERE company_id=c AND retention_class=k AND target_id=target FOR SHARE;
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.invoice_file_catalog WHERE retention_class=k;
 LOCK TABLE public.customer_invoices,public.customer_invoice_documents,public.invoice_documents,public.invoice_export_items,public.invoice_export_attempts,public.customers,public.customer_supply_periods IN SHARE MODE;
 EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE id=$1 AND company_id=$2 FOR SHARE',spec.source_table) INTO r USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'invoice_file_actual_source_removed';END IF;
 IF spec.source_table='customer_invoices' THEN invoice:=r;
 ELSIF spec.source_table='customer_invoice_documents' THEN SELECT to_jsonb(x) INTO invoice FROM public.customer_invoices x WHERE id=(r->>'invoice_id')::uuid AND company_id=c FOR SHARE;
 ELSE SELECT to_jsonb(x) INTO item FROM public.invoice_export_items x WHERE id=(r->>'invoice_export_item_id')::uuid AND company_id=c FOR SHARE;END IF;
 customer:=coalesce(invoice->>'customer_id',item->>'customer_id')::uuid;
 SELECT to_jsonb(x) INTO underlay FROM public.billing_underlays x WHERE company_id=c AND id=coalesce(invoice->>'billing_underlay_id',item->>'billing_underlay_id')::uuid FOR SHARE;
 SELECT to_jsonb(x) INTO binding FROM gridex_billing_source.underlay_bindings x WHERE company_id=c AND underlay_id=(underlay->>'id')::uuid FOR SHARE;
 IF customer IS NULL OR underlay IS NULL OR binding IS NULL OR underlay->>'customer_id' IS DISTINCT FROM customer::text OR NOT EXISTS(SELECT FROM public.customers WHERE id=customer AND company_id=c) THEN RAISE EXCEPTION 'invoice_file_native_invoice_underlay_scope_required';END IF;
 IF binding->>'source_basis_hash' IS DISTINCT FROM encode(sha256(convert_to((binding->'source_basis')::text,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones WHERE company_id=c AND retention_class='billing_underlay_source_body' AND target_id=underlay->>'id') THEN RAISE EXCEPTION 'invoice_file_actual_billing_source_required';END IF;
 start_at:=(underlay->>'billing_period_start')::timestamptz;end_at:=(underlay->>'billing_period_end')::timestamptz;
 IF isfinite(start_at) IS NOT TRUE OR isfinite(end_at) IS NOT TRUE OR end_at<=start_at THEN RAISE EXCEPTION 'invoice_file_native_closed_period_required';END IF;
 SELECT jsonb_build_object('customer',to_jsonb(x),'supplies',(SELECT coalesce(jsonb_agg(to_jsonb(sp) ORDER BY sp.id),'[]') FROM public.customer_supply_periods sp WHERE sp.company_id=c AND sp.customer_id=customer),'invoices',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'status',i.status) ORDER BY i.id),'[]') FROM public.customer_invoices i WHERE i.company_id=c AND i.customer_id=customer),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'status',i.status,'attempts',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM public.invoice_export_attempts a WHERE a.company_id=c AND a.invoice_export_item_id=i.id)) ORDER BY i.id),'[]') FROM public.invoice_export_items i WHERE i.company_id=c AND i.customer_id=customer)) INTO scope FROM public.customers x WHERE id=customer AND company_id=c;
 closed:=end_at<=clock_timestamp() AND scope#>>'{customer,status}'='archived'
 AND NOT EXISTS(SELECT FROM public.customer_supply_periods WHERE company_id=c AND customer_id=customer AND (status IS NULL OR status NOT IN('cancelled','rejected','terminated','ended','closed','inactive') OR coalesce(actual_end_date,end_date) IS NULL OR coalesce(actual_end_date,end_date)>=current_date))
 AND NOT EXISTS(SELECT FROM public.customer_invoices WHERE company_id=c AND customer_id=customer AND (status IS NULL OR lower(status) NOT IN('paid','cancelled','void','credited')))
 AND NOT EXISTS(SELECT FROM public.invoice_export_items WHERE company_id=c AND customer_id=customer AND (status IS NULL OR upper(status) NOT IN('SENT','CREDITED','CANCELLED','REJECTED')))
 AND NOT EXISTS(SELECT FROM public.invoice_export_attempts a JOIN public.invoice_export_items i ON i.id=a.invoice_export_item_id WHERE i.company_id=c AND i.customer_id=customer AND (a.company_id IS DISTINCT FROM c OR a.finished_at IS NULL));
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceId',s.id,'sourceHash',s.source_hash,'targetHash',encode(sha256(convert_to(jsonb_build_object('source',to_jsonb(s),'target',r)::text,'UTF8')),'hex'),'scopeHash',encode(sha256(convert_to(jsonb_build_object('scope',scope,'underlayId',underlay->>'id','sourceBasisHash',binding->>'source_basis_hash','periodStart',start_at,'periodEnd',end_at)::text,'UTF8')),'hex'),'storageBucket',s.storage_bucket,'storagePath',s.storage_path,'byteLength',s.byte_length,'periodStart',start_at,'periodEnd',end_at,'allIncludedScopesClosed',closed,'complete',false,'authority','none');END$_$;

--
-- Name: invoice_file_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.invoice_file_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id uuid NOT NULL,
    source_id uuid NOT NULL,
    source_hash text NOT NULL,
    target_hash text NOT NULL,
    scope_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT invoice_file_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT invoice_file_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT invoice_file_decisions_scope_hash_check CHECK ((scope_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT invoice_file_decisions_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT invoice_file_decisions_target_hash_check CHECK ((target_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.invoice_file_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: invoice_file_current_v1(gridex_ediel_retention.invoice_file_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_current_v1(d gridex_ediel_retention.invoice_file_decisions) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r gridex_ediel_retention.invoice_file_reviews%rowtype;basis jsonb;p jsonb;BEGIN
 SELECT * INTO r FROM gridex_ediel_retention.invoice_file_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) IS NOT TRUE OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,'ediel.retention.invoice_copy_evidence') IS NOT TRUE THEN RETURN NULL;END IF;
 basis:=gridex_ediel_retention.invoice_file_basis_v1(d.company_id,d.retention_class,d.target_id);p:=gridex_ediel_retention.invoice_file_receipt_v1(d);
 IF p IS NULL OR (p->>'retainUntil')::timestamptz>clock_timestamp() OR basis->>'targetHash' IS DISTINCT FROM d.target_hash OR basis->>'scopeHash' IS DISTINCT FROM d.scope_hash OR basis->>'sourceHash' IS DISTINCT FROM d.source_hash OR basis->>'allIncludedScopesClosed' IS DISTINCT FROM 'true' OR p->>'periodStart' IS DISTINCT FROM basis->>'periodStart' OR p->>'periodEnd' IS DISTINCT FROM basis->>'periodEnd' THEN RETURN NULL;END IF;RETURN r.id;END$$;

--
-- Name: invoice_file_decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_additional_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: invoice_file_locator_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_locator_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE spec record;r jsonb;invoice jsonb;item jsonb;object jsonb;bucket text;path text;customer uuid;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.invoice_file_catalog WHERE retention_class=k;
 EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE id=$1 AND company_id=$2 FOR SHARE',spec.source_table) INTO r USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'invoice_file_actual_scoped_target_required';END IF;
 path:=nullif(r->>spec.body_column,'');bucket:=nullif(r->>'storage_bucket','');
 IF bucket IS NULL THEN bucket:=nullif(r#>>'{metadata,bucket}','');END IF;
 IF split_part(path,'/',1) IN('customer-documents','customer-contract-documents','contract-pdfs','billing-exports') THEN
  IF bucket IS NOT NULL AND bucket<>split_part(path,'/',1) THEN RAISE EXCEPTION 'invoice_file_bucket_path_conflict';END IF;
  bucket:=split_part(path,'/',1);path:=substring(path FROM length(bucket)+2);
 END IF;
 IF bucket IS NULL OR bucket NOT IN('customer-documents','customer-contract-documents','contract-pdfs','billing-exports') OR path IS NULL OR length(path)>1024 OR path~'(^|/)\.\.?(/|$)' OR path~'(^/|//|^[A-Za-z]+:)' OR path NOT LIKE 'companies/'||c::text||'/%' THEN RAISE EXCEPTION 'invoice_file_owned_storage_locator_required';END IF;
 IF spec.source_table='customer_invoices' THEN invoice:=r;
 ELSIF spec.source_table='customer_invoice_documents' THEN SELECT to_jsonb(x) INTO invoice FROM public.customer_invoices x WHERE id=(r->>'invoice_id')::uuid AND company_id=c FOR SHARE;
 ELSE SELECT to_jsonb(x) INTO item FROM public.invoice_export_items x WHERE id=(r->>'invoice_export_item_id')::uuid AND company_id=c FOR SHARE;END IF;
 customer:=coalesce(invoice->>'customer_id',item->>'customer_id')::uuid;
 IF customer IS NULL OR NOT EXISTS(SELECT FROM public.customers WHERE id=customer AND company_id=c) OR r->>'customer_id' IS NOT NULL AND r->>'customer_id'<>customer::text THEN RAISE EXCEPTION 'invoice_file_actual_parent_customer_required';END IF;
 IF bucket='customer-documents' AND (cardinality(string_to_array(path,'/'))<>7 OR split_part(path,'/',3)<>'customers' OR split_part(path,'/',4)<>customer::text OR split_part(path,'/',5)!~'^[a-f0-9-]{36}$' OR split_part(path,'/',6)<>'grid_invoice_suggested') THEN RAISE EXCEPTION 'invoice_file_customer_document_scope_required';END IF;
 IF bucket='customer-documents' AND split_part(path,'/',5)<>customer::text AND NOT EXISTS(SELECT FROM public.customer_sites WHERE id=split_part(path,'/',5)::uuid AND company_id=c AND customer_id=customer) THEN RAISE EXCEPTION 'invoice_file_actual_customer_site_tuple_required';END IF;
 SELECT to_jsonb(x) INTO object FROM storage.objects x WHERE bucket_id=bucket AND name=path FOR SHARE;
 IF object IS NULL OR coalesce(object#>>'{metadata,size}','')!~'^[0-9]{1,9}$' OR (object#>>'{metadata,size}')::bigint NOT BETWEEN 1 AND 20971520 THEN RAISE EXCEPTION 'invoice_file_native_storage_object_required';END IF;
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'targetHash',encode(sha256(convert_to(jsonb_build_object('target',r,'storageObject',object)::text,'UTF8')),'hex'),'storageBucket',bucket,'storagePath',path,'storageObjectId',object->>'id','storageByteLength',(object#>>'{metadata,size}')::bigint,'customerId',customer,'invoiceId',invoice->>'id','exportItemId',item->>'id');END$_$;

--
-- Name: invoice_file_receipt_v1(gridex_ediel_retention.invoice_file_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_receipt_v1(d gridex_ediel_retention.invoice_file_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE issuer gridex_ediel_retention.issuers%rowtype;s gridex_ediel_retention.invoice_file_sources%rowtype;p jsonb;b bytea;now_at timestamptz;issued timestamptz;expires timestamptz;retain timestamptz;journal timestamptz;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash OR jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 SELECT * INTO s FROM gridex_ediel_retention.invoice_file_sources WHERE id=d.source_id AND company_id=d.company_id FOR SHARE;now_at:=clock_timestamp();
 IF issuer.id IS NULL OR s.id IS NULL OR now_at<issuer.valid_from OR now_at>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 b:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(b,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(b,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;retain:=(p->>'retainUntil')::timestamptz;journal:=(p->>'journalRetainUntil')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_invoice_file_retention_policy_v1' OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'targetId' IS DISTINCT FROM d.target_id::text OR p->>'sourceId' IS DISTINCT FROM d.source_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetHash' IS DISTINCT FROM d.target_hash OR p->>'scopeHash' IS DISTINCT FROM d.scope_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'storageBucket' IS DISTINCT FROM s.storage_bucket OR p->>'storagePath' IS DISTINCT FROM s.storage_path OR p->>'byteLength' IS DISTINCT FROM s.byte_length::text OR p->>'operation' IS DISTINCT FROM 'delete_storage_pdf' OR p->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference OR p->>'accessRevocationRequired' IS DISTINCT FROM 'true' OR nullif(p->>'legalBasisReference','') IS NULL OR nullif(p->>'journalPurposeReference','') IS NULL OR isfinite(issued) IS NOT TRUE OR isfinite(expires) IS NOT TRUE OR isfinite(retain) IS NOT TRUE OR isfinite(journal) IS NOT TRUE OR issued>now_at OR expires<=now_at OR issued<issuer.valid_from OR expires>issuer.valid_to OR journal<=now_at THEN RETURN NULL;END IF;
 RETURN p;EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;END$_$;

--
-- Name: invoice_file_ref_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_ref_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec record;r jsonb;s gridex_ediel_retention.invoice_file_sources%rowtype;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.invoice_file_catalog WHERE source_table=TG_TABLE_NAME;r:=CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END;
 SELECT * INTO s FROM gridex_ediel_retention.invoice_file_sources WHERE retention_class=spec.retention_class AND target_id=(r->>'id')::uuid;
 IF s.id IS NOT NULL AND (TG_OP='DELETE' OR to_jsonb(NEW)->spec.body_column IS DISTINCT FROM r->spec.body_column OR to_jsonb(NEW)->'company_id' IS DISTINCT FROM r->'company_id' OR to_jsonb(NEW)->'storage_bucket' IS DISTINCT FROM r->'storage_bucket') THEN RAISE EXCEPTION 'invoice_file_captured_reference_immutable';END IF;
 IF TG_OP='INSERT' AND EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_sources x JOIN gridex_ediel_retention.invoice_file_tombstones t ON t.source_id=x.id WHERE NEW.company_id=x.company_id AND to_jsonb(NEW)->>spec.body_column IN(x.storage_path,x.storage_bucket||'/'||x.storage_path)) THEN RAISE EXCEPTION 'invoice_file_tombstoned_reference_not_reusable';END IF;IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END$$;

--
-- Name: invoice_file_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_ediel_retention.invoice_file_decisions WHERE id=NEW.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'invoice_file_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: invoice_file_sources; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.invoice_file_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id uuid NOT NULL,
    target_hash text NOT NULL,
    storage_object_id uuid NOT NULL,
    storage_bucket text NOT NULL,
    storage_path text NOT NULL,
    source_hash text NOT NULL,
    byte_length bigint NOT NULL,
    captured_by uuid NOT NULL,
    captured_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT invoice_file_sources_byte_length_check CHECK (((byte_length >= 1) AND (byte_length <= 20971520))),
    CONSTRAINT invoice_file_sources_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT invoice_file_sources_target_hash_check CHECK ((target_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.invoice_file_sources FORCE ROW LEVEL SECURITY;

--
-- Name: invoice_file_shared_scope_v1(text, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_shared_scope_v1(bucket text, path text) RETURNS SETOF gridex_ediel_retention.invoice_file_sources
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE spec record;row record;s gridex_ediel_retention.invoice_file_sources%rowtype;l jsonb;BEGIN
 LOCK TABLE public.customer_invoice_documents,public.invoice_documents,public.customer_invoices IN SHARE MODE;
 FOR spec IN SELECT * FROM gridex_ediel_retention.invoice_file_catalog ORDER BY retention_class LOOP
  IF EXISTS(SELECT FROM pg_class WHERE oid=('public.'||spec.source_table)::regclass) THEN
   FOR row IN EXECUTE format('SELECT id FROM public.%I x WHERE coalesce(to_jsonb(x)->>%L,'''') NOT IN($1,$2,$3) AND (position($2 IN coalesce(to_jsonb(x)->>''public_url'',''''))>0 OR position($2 IN coalesce(to_jsonb(x)->>''pdf_url'',''''))>0)',spec.source_table,spec.body_column) USING path,bucket||'/'||path,'storage://'||bucket||'/'||path LOOP RAISE EXCEPTION 'invoice_file_remote_or_ambiguous_shared_copy_held';END LOOP;
  END IF;
  FOR row IN EXECUTE format('SELECT id,company_id FROM public.%I WHERE %I=$1 OR %I=$2 OR %I=$3 ORDER BY id',spec.source_table,spec.body_column,spec.body_column,spec.body_column) USING path,bucket||'/'||path,'storage://'||bucket||'/'||path LOOP
   SELECT * INTO s FROM gridex_ediel_retention.invoice_file_sources WHERE retention_class=spec.retention_class AND target_id=row.id AND company_id=row.company_id FOR SHARE;
   IF s.id IS NULL OR s.storage_bucket<>bucket OR s.storage_path<>path THEN RAISE EXCEPTION 'invoice_file_every_shared_reference_capture_required';END IF;RETURN NEXT s;
  END LOOP;
 END LOOP;END$_$;

--
-- Name: invoice_file_storage_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.invoice_file_storage_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE s gridex_ediel_retention.invoice_file_sources%rowtype;t gridex_ediel_retention.invoice_file_tombstones%rowtype;d gridex_ediel_retention.invoice_file_decisions%rowtype;actor uuid;bucket text;path text;BEGIN
 bucket:=CASE WHEN TG_OP='INSERT' THEN NEW.bucket_id ELSE OLD.bucket_id END;path:=CASE WHEN TG_OP='INSERT' THEN NEW.name ELSE OLD.name END;
 -- An existing actual PDF reference cannot bypass custody by skipping source
 -- capture; each matching row must be represented before any physical DELETE.
 IF TG_OP='DELETE' AND bucket IN('customer-documents','customer-contract-documents','contract-pdfs','billing-exports') THEN PERFORM 1 FROM gridex_ediel_retention.invoice_file_shared_scope_v1(bucket,path);END IF;
 IF TG_OP='UPDATE' AND (NEW.bucket_id IS DISTINCT FROM OLD.bucket_id OR NEW.name IS DISTINCT FROM OLD.name) AND EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_sources WHERE storage_bucket=NEW.bucket_id AND storage_path=NEW.name) THEN RAISE EXCEPTION 'invoice_file_storage_target_immutable';END IF;
 FOR s IN SELECT * FROM gridex_ediel_retention.invoice_file_sources WHERE storage_bucket=bucket AND storage_path=path ORDER BY id FOR SHARE LOOP
  IF TG_OP<>'DELETE' THEN RAISE EXCEPTION 'invoice_file_storage_original_immutable';END IF;
  actor:=public.ediel_retention_session_actor_v1();PERFORM gridex_ediel_retention.invoice_file_actor_v1(s.company_id,actor,'ediel.retention.purge');
  SELECT * INTO t FROM gridex_ediel_retention.invoice_file_tombstones WHERE source_id=s.id;
  IF t.source_id IS NULL THEN RAISE EXCEPTION 'invoice_file_native_tombstone_required';END IF;
  SELECT * INTO STRICT d FROM gridex_ediel_retention.invoice_file_decisions WHERE id=t.decision_id FOR UPDATE;
  IF gridex_ediel_retention.invoice_file_current_v1(d) IS DISTINCT FROM t.review_id THEN RAISE EXCEPTION 'invoice_file_storage_current_legal_review_required';END IF;
  PERFORM 1 FROM gridex_ediel_retention.invoice_file_shared_scope_v1(bucket,path);
  INSERT INTO gridex_ediel_retention.invoice_file_events(source_id,kind,actor_user_id) VALUES(s.id,'storage_delete_authorized',actor) ON CONFLICT DO NOTHING;
 END LOOP;IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END$$;

