END$$;

--
-- Name: permission_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.permission_v1(c uuid, actor uuid, wanted text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE retention_keys constant text[]:=ARRAY['ediel.retention.submit','ediel.retention.review','ediel.retention.purge','ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'];
retention_grant_observed_at timestamptz;
BEGIN
 IF wanted<>ALL(retention_keys) THEN RETURN gridex_requested_changes.scoped_permission_v1(c,actor,wanted) IS TRUE
 AND NOT EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.key=wanted)
 AND NOT EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND (o.company_id=c OR o.company_id IS NULL) AND o.is_active AND o.effect='deny' AND o.permission_key=wanted)
 AND public.gridex_actor_has_company_permission(actor,c,wanted) IS TRUE;END IF;
 IF NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status IN('active','archived','pending_deletion','closed'))
  OR NOT public.ediel_retention_lock_auth_actor_v1(actor)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL) THEN RETURN false;END IF;
 retention_grant_observed_at:=clock_timestamp();
 IF NOT EXISTS(SELECT FROM public.permissions WHERE key=wanted AND is_active)
  OR EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.key=wanted)
  OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND (o.company_id=c OR o.company_id IS NULL) AND o.is_active AND o.effect='deny' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=retention_grant_observed_at) AND (o.valid_to IS NULL OR retention_grant_observed_at<o.valid_to))
  OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.key=wanted) THEN RETURN false;END IF;
 RETURN EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
  OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted)
  OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND o.company_id=c AND o.is_active AND o.effect='allow' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=retention_grant_observed_at) AND (o.valid_to IS NULL OR retention_grant_observed_at<o.valid_to));
END$$;

--
-- Name: process_basis_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_basis_v1(c uuid, k text, target text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE row_body jsonb;body jsonb;source_hash text;bytes bigint;cust uuid;ref uuid;found_company uuid;found_customer uuid;node record;included_ids uuid[]:=ARRAY[]::uuid[];wildcard boolean:=false;scope jsonb;closed boolean;table_name text;BEGIN
 SELECT source_table INTO STRICT table_name FROM gridex_ediel_retention.process_class_catalog WHERE retention_class=k;
 IF EXISTS(SELECT FROM gridex_ediel_retention.process_tombstones WHERE retention_class=k AND target_id=target AND company_id=c) THEN RAISE EXCEPTION 'process_journal_retention_tombstoned';END IF;
 IF k='correction_process_fact_body' THEN
  IF target!~'^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'process_retention_fact_selector_required';END IF;
  SELECT to_jsonb(f) INTO row_body FROM gridex_correction_process.facts f WHERE id=target::bigint AND company_id=c FOR SHARE;
  body:=jsonb_build_object('table',row_body->>'table_name','rowId',row_body->>'row_id','operation',row_body->>'operation','old',row_body->'old_fact','new',row_body->'new_fact');source_hash:=row_body->>'facts_hash';bytes:=octet_length(body::text);
 ELSE
  IF target!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'process_retention_snapshot_selector_required';END IF;
  EXECUTE format('SELECT to_jsonb(f) FROM gridex_correction_process.%I f WHERE id=$1 AND company_id=$2 FOR SHARE',table_name) INTO row_body USING target::uuid,c;
  body:=(row_body->>'readset_text')::jsonb;source_hash:=row_body->>'readset_hash';bytes:=octet_length(row_body->>'readset_text');
 END IF;
 IF row_body IS NULL OR bytes NOT BETWEEN 1 AND 20971520 OR source_hash IS DISTINCT FROM encode(sha256(convert_to(CASE WHEN k='correction_process_fact_body' THEN body::text ELSE row_body->>'readset_text' END,'UTF8')),'hex') THEN RAISE EXCEPTION 'process_retention_actual_original_hash_required';END IF;
 -- Hold range writes while the actual entire included customer/supply graph is
 -- qualified. Unknown scope expands to every native customer in this company;
 -- it can qualify when every scope is closed, without inventing completeness.
 LOCK TABLE public.customers,public.customer_supply_periods IN SHARE ROW EXCLUSIVE MODE;
 FOR node IN SELECT * FROM gridex_ediel_retention.process_nodes_v1(body||jsonb_build_object('customer_id',row_body->'customer_id','subjectMessageId',row_body->'subject_message_id')) LOOP
  IF node.key IN('companyId','company_id') AND jsonb_typeof(node.value)='string' AND (node.value#>>'{}') IS DISTINCT FROM c::text THEN RAISE EXCEPTION 'process_retention_foreign_included_scope';END IF;
  IF node.key IN('customerId','customer_id','contractId','contract_id','customer_contract_id','sourceMessageId','source_message_id','subjectMessageId','messageId','originalMessageId','outbound_z03_message_id','inbound_z04_message_id') AND jsonb_typeof(node.value)='string' THEN
   BEGIN ref:=(node.value#>>'{}')::uuid;EXCEPTION WHEN invalid_text_representation THEN wildcard:=true;CONTINUE;END;
   found_company:=NULL;found_customer:=NULL;
   IF node.key IN('customerId','customer_id') THEN SELECT company_id,id INTO found_company,found_customer FROM public.customers WHERE id=ref;
   ELSIF node.key IN('contractId','contract_id','customer_contract_id') THEN SELECT company_id,customer_id INTO found_company,found_customer FROM public.customer_contracts WHERE id=ref;
   ELSE SELECT company_id,customer_id INTO found_company,found_customer FROM public.ediel_messages WHERE id=ref;END IF;
   IF found_company IS NOT NULL AND found_company IS DISTINCT FROM c THEN RAISE EXCEPTION 'process_retention_foreign_included_scope';END IF;
   IF found_company IS NULL OR found_customer IS NULL THEN wildcard:=true;ELSE included_ids:=array_append(included_ids,found_customer);END IF;
  END IF;
 END LOOP;
 IF cardinality(included_ids)>10000 THEN RAISE EXCEPTION 'process_retention_customer_scope_bound';END IF;
 IF cardinality(included_ids)=0 OR k<>'correction_process_fact_body' THEN wildcard:=true;END IF;
 IF wildcard THEN SELECT coalesce(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO included_ids FROM public.customers WHERE company_id=c;ELSE SELECT array_agg(DISTINCT v ORDER BY v) INTO included_ids FROM unnest(included_ids)v;END IF;
 IF cardinality(included_ids)>10000 THEN RAISE EXCEPTION 'process_retention_customer_scope_bound';END IF;
 PERFORM id FROM public.customers WHERE company_id=c AND id=ANY(included_ids) ORDER BY id FOR SHARE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('customerId',u.id,'status',u.status,'supply',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') FROM public.customer_supply_periods s WHERE s.company_id=c AND s.customer_id=u.id)) ORDER BY u.id),'[]'),
  coalesce(bool_and(u.status='archived' AND NOT EXISTS(SELECT FROM public.customer_supply_periods s WHERE s.company_id=c AND s.customer_id=u.id AND s.status NOT IN('cancelled','rejected','terminated','ended','closed','inactive') AND (coalesce(s.actual_end_date,s.end_date) IS NULL OR coalesce(s.actual_end_date,s.end_date)>=current_date))),true)
 INTO scope,closed FROM public.customers u WHERE u.company_id=c AND u.id=ANY(included_ids);
 RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceTable',table_name,'sourceHash',source_hash,'targetHash',encode(sha256(convert_to(row_body::text,'UTF8')),'hex'),'scopeHash',encode(sha256(convert_to(jsonb_build_object('companyId',c,'wildcard',wildcard,'scopes',scope)::text,'UTF8')),'hex'),'byteLength',bytes,'includedCustomers',included_ids,'allIncludedScopesClosed',closed,'unknownScopeExpandedToCompany',wildcard,'complete',false,'authority','none');
END$_$;

--
-- Name: process_combined_snapshots_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_combined_snapshots_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_process_retention_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'correction_process_append_only' USING ERRCODE='55000';
END $$;

--
-- Name: process_customer_version_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_customer_version_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE contract uuid;BEGIN
 IF NEW.event_id IS NOT NULL THEN SELECT e.contract_id INTO contract FROM gridex_requested_changes.events e WHERE e.id=NEW.event_id AND e.company_id=NEW.company_id FOR SHARE;
 ELSIF NEW.bilateral_artifact_id IS NOT NULL THEN SELECT a.contract_id INTO contract FROM gridex_bilateral_customer_sources.artifacts a WHERE a.id=NEW.bilateral_artifact_id AND a.company_id=NEW.company_id FOR SHARE;END IF;
 IF contract IS NULL THEN RAISE EXCEPTION 'retention_customer_version_actual_prospective_contract_required';END IF;
 PERFORM public.ediel_require_contract_records_available_v1(NEW.company_id,contract);PERFORM public.ediel_require_source_bytes_available_v1(NEW.company_id,NEW.source_message_id);RETURN NEW;END$$;

--
-- Name: process_decisions_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_decisions_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: process_facts_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_facts_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_process_retention_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'correction_process_append_only' USING ERRCODE='55000';
END $$;

--
-- Name: process_nodes_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_nodes_v1(body jsonb) RETURNS TABLE(key text, value jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE queue jsonb[]:=ARRAY[body];node jsonb;item record;count integer:=0;BEGIN
 WHILE cardinality(queue)>0 LOOP node:=queue[1];queue:=queue[2:];count:=count+1;IF count>100000 THEN RAISE EXCEPTION 'process_retention_scope_node_bound';END IF;
  IF jsonb_typeof(node)='object' THEN FOR item IN SELECT * FROM jsonb_each(node) LOOP key:=item.key;value:=item.value;RETURN NEXT;
   IF item.key IN('readsetText','factsText') AND jsonb_typeof(item.value)='string' THEN queue:=array_append(queue,(item.value#>>'{}')::jsonb);ELSE queue:=array_append(queue,item.value);END IF;END LOOP;
  ELSIF jsonb_typeof(node)='array' THEN FOR item IN SELECT v FROM jsonb_array_elements(node) v LOOP queue:=array_append(queue,item.v);END LOOP;END IF;
 END LOOP;
END$$;

--
-- Name: process_readsets_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_readsets_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_process_retention_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'correction_process_append_only' USING ERRCODE='55000';
END $$;

--
-- Name: process_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.process_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id text NOT NULL,
    source_hash text NOT NULL,
    target_hash text NOT NULL,
    scope_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT process_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT process_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT process_decisions_scope_hash_check CHECK ((scope_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT process_decisions_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT process_decisions_target_hash_check CHECK ((target_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.process_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: process_receipt_v1(gridex_ediel_retention.process_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_receipt_v1(d gridex_ediel_retention.process_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;operation text;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF issuer.id IS NULL OR now()<issuer.valid_from OR now()>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.process_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;journal_end:=(p->>'journalRetainUntil')::timestamptz;
 SELECT x.operation INTO STRICT operation FROM gridex_ediel_retention.process_class_catalog x WHERE retention_class=d.retention_class;
 IF p->>'format' IS DISTINCT FROM 'ediel_process_journal_retention_policy_v1' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'targetId' IS DISTINCT FROM d.target_id OR p->>'companyId' IS DISTINCT FROM d.company_id::text
 OR p->>'sourceTable' IS DISTINCT FROM (SELECT source_table FROM gridex_ediel_retention.process_class_catalog WHERE retention_class=d.retention_class)
 OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetHash' IS DISTINCT FROM d.target_hash OR p->>'scopeHash' IS DISTINCT FROM d.scope_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'operation' IS DISTINCT FROM operation
 OR p->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference OR nullif(p->>'legalBasisReference','') IS NULL OR nullif(p->>'journalPurposeReference','') IS NULL OR p->>'accessRevocationRequired' IS DISTINCT FROM 'true'
 OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR journal_end<=now() OR issued>now() OR expires<=now() OR issued<issuer.valid_from OR expires>issuer.valid_to THEN RETURN NULL;END IF;RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;END$_$;

--
-- Name: process_redacted_v1(text, jsonb, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_redacted_v1(k text, b jsonb, h text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN k='correction_process_fact_body' THEN b||jsonb_build_object('old_fact',null,'new_fact',jsonb_build_object('retentionUnavailable',true,'sourceHash',h,'complete',false,'authority','none')) ELSE b||jsonb_build_object('readset_text',jsonb_build_object('retentionUnavailable',true,'sourceHash',h,'complete',false,'authority','none')::text) END
$$;

--
-- Name: process_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_ediel_retention.process_decisions WHERE id=NEW.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'process_retention_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: process_target_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_target_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE k text;target text;BEGIN
 SELECT retention_class INTO STRICT k FROM gridex_ediel_retention.process_class_catalog WHERE source_table=TG_TABLE_NAME;target:=(CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END)->>'id';
 IF EXISTS(SELECT FROM gridex_ediel_retention.process_tombstones WHERE retention_class=k AND target_id=target) AND NOT (TG_OP='UPDATE' AND public.ediel_is_qualified_process_retention_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW))) THEN RAISE EXCEPTION 'process_journal_retention_tombstoned';END IF;IF TG_OP='DELETE' THEN RAISE EXCEPTION 'process_journal_native_class_retention_required';END IF;RETURN NEW;END$$;

--
-- Name: process_witness_source_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.process_witness_source_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM gridex_correction_process.facts WHERE id=NEW.fact_id AND company_id=NEW.company_id AND facts_hash=NEW.facts_hash FOR SHARE;
 IF NOT FOUND OR public.ediel_process_journal_tombstoned_v1(NEW.company_id,'correction_process_fact_body',NEW.fact_id::text,NEW.facts_hash) THEN RAISE EXCEPTION 'process_journal_retention_tombstoned';END IF;RETURN NEW;END$$;

--
-- Name: protected_copy_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;b bytea;BEGIN r:=gridex_ediel_retention.protected_copy_row_v1(c,k,target);b:=decode(substr(r->>'document_bytes',3),'hex');IF b IS NULL OR octet_length(b) NOT BETWEEN 1 AND 10485760 THEN RAISE EXCEPTION 'decision_evidence_actual_original_bytes_required';END IF;RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'byteLength',octet_length(b));END$$;

--
-- Name: protected_copy_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_current_v1(c uuid, target uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 RETURN NOT EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_revocations WHERE company_id=c AND target_id=target);
END$$;

--
-- Name: protected_copy_insert_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec record;row jsonb:=to_jsonb(NEW);c uuid;ct uuid;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF TG_TABLE_SCHEMA='gridex_brp_sources' THEN
  IF TG_TABLE_NAME='contract_declarations' THEN c:=NEW.company_id;ct:=NEW.contract_id;ELSE SELECT company_id,contract_id INTO c,ct FROM gridex_brp_sources.contract_declarations WHERE id=NEW.declaration_id;END IF;
  PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'protected_copy_actual_contract_scope_required';END IF;
 END IF;
 FOR spec IN SELECT * FROM gridex_ediel_retention.protected_copy_specs WHERE source_schema=TG_TABLE_SCHEMA AND source_table=TG_TABLE_NAME LOOP
  IF row->>spec.body_field IS NULL OR encode(sha256(decode(substr(row->>spec.body_field,3),'hex')),'hex') IS DISTINCT FROM row->>spec.hash_field THEN RAISE EXCEPTION 'protected_copy_new_actual_bytes_required';END IF;
 END LOOP;RETURN NEW;
END$$;

--
-- Name: protected_copy_row_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_row_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE spec gridex_ediel_retention.protected_copy_specs%rowtype;ct uuid;r jsonb;b bytea;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT * INTO STRICT spec FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=k;
 IF spec.source_schema='gridex_brp_sources' THEN
  SELECT contract_id INTO ct FROM gridex_brp_sources.contract_declarations WHERE id=target AND company_id=c;
  PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||c::text||':'||ct::text,0));PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id=target AND company_id=c FOR UPDATE;
 ELSIF spec.source_schema='gridex_contract_source_intake' THEN
  PERFORM gridex_contract_source_intake.lock_graph_v1();
  SELECT contract_id INTO ct FROM gridex_contract_source_intake.artifacts WHERE id=target AND company_id=c;
  PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('contract-original-intake:'||c::text||':'||ct::text,0));PERFORM id FROM gridex_contract_source_intake.artifacts WHERE id=target AND company_id=c FOR UPDATE;

 ELSIF spec.source_schema='gridex_brp_declaration_intake' THEN
  SELECT contract_id INTO ct FROM gridex_brp_declaration_intake.artifacts WHERE id=target AND company_id=c;
  PERFORM id FROM public.customer_contracts WHERE id=ct AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('contract-brp:'||c::text||':'||ct::text,0));
  PERFORM id FROM gridex_brp_sources.contract_declarations WHERE id IN(SELECT declaration_id FROM gridex_brp_declaration_intake.origins WHERE artifact_id=target AND company_id=c) ORDER BY id FOR UPDATE;
  PERFORM id FROM gridex_brp_declaration_intake.artifacts WHERE id=target AND company_id=c FOR UPDATE;

 ELSIF spec.source_schema='gridex_supply_rescission' THEN
  PERFORM gridex_supply_rescission.lock_v1();
  PERFORM id FROM gridex_supply_rescission.artifacts WHERE id=target AND company_id=c FOR UPDATE;
 ELSE
  PERFORM id FROM gridex_customer_life_events.certification_classifications WHERE id=target AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
  IF spec.source_table='certification_classification_revocations' THEN PERFORM declaration_id FROM gridex_customer_life_events.certification_classification_revocations WHERE declaration_id=target FOR UPDATE;END IF;
 END IF;
 EXECUTE format('SELECT to_jsonb(v),v.document_bytes FROM gridex_ediel_retention.%I v WHERE id=$1 AND company_id=$2',spec.view_name) INTO r,b USING target,c;
 IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=c;
 IF b IS NOT NULL AND encode(sha256(b),'hex') IS DISTINCT FROM r->>'document_hash' OR b IS NULL AND(t.target_id IS NULL OR t.source_hash IS DISTINCT FROM r->>'document_hash') THEN RAISE EXCEPTION 'decision_evidence_original_custody_mismatch';END IF;
 RETURN r||jsonb_build_object('document_byte_length',CASE WHEN b IS NULL THEN t.byte_length ELSE NULL END,'document_purged_at',t.created_at);
END$_$;

--
-- Name: protected_copy_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_transition_v1(k text, o jsonb, n jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec gridex_ediel_retention.protected_copy_specs%rowtype;target uuid:=coalesce(o->>'id',o->>'declaration_id')::uuid;c uuid;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;d gridex_ediel_retention.decision_evidence_policies%rowtype;r gridex_ediel_retention.decision_evidence_reviews%rowtype;basis jsonb;p jsonb;h text;b bytea;permission text;at timestamptz;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=k;
 IF o->>spec.body_field IS NULL OR n->>spec.body_field IS NOT NULL OR(o-spec.body_field) IS DISTINCT FROM(n-spec.body_field) THEN RETURN false;END IF;
 IF spec.source_table='certification_classification_revocations' THEN SELECT company_id INTO c FROM gridex_customer_life_events.certification_classifications WHERE id=target;ELSE c:=(o->>'company_id')::uuid;END IF;
 basis:=gridex_ediel_retention.protected_copy_basis_v1(c,k,target);b:=decode(substr(o->>spec.body_field,3),'hex');h:=encode(sha256(b),'hex');
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=target AND company_id=c;
 IF t.target_id IS NULL OR t.source_hash IS DISTINCT FROM h OR t.byte_length IS DISTINCT FROM octet_length(b) OR t.target_metadata_hash IS DISTINCT FROM basis->>'targetMetadataHash' OR NOT EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_revocations WHERE retention_class=k AND target_id=target AND company_id=c AND policy_id=t.policy_id AND review_id=t.review_id AND source_hash=h AND actor_user_id=t.actor_user_id) THEN RETURN false;END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=t.policy_id FOR UPDATE;SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF r.id IS DISTINCT FROM t.review_id OR r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR d.company_id IS DISTINCT FROM c OR d.retention_class IS DISTINCT FROM k OR d.target_id IS DISTINCT FROM target OR d.source_hash IS DISTINCT FROM h OR d.target_metadata_hash IS DISTINCT FROM t.target_metadata_hash THEN RETURN false;END IF;
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;PERFORM gridex_ediel_retention.decision_evidence_actor_v1(c,t.actor_user_id,k,'ediel.retention.purge');PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(c,r.actor_user_id,k);p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);IF p IS NULL THEN RETURN false;END IF;
 SELECT permission_key INTO STRICT permission FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;
 IF gridex_ediel_retention.permission_v1(c,t.actor_user_id,'ediel.retention.purge') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,t.actor_user_id,permission) IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,r.actor_user_id,permission) IS NOT TRUE THEN RETURN false;END IF;
 at:=clock_timestamp();RETURN(p->>'retainUntil')::timestamptz<=at AND(p->>'issuedAt')::timestamptz<=at AND(p->>'expiresAt')::timestamptz>at AND(p->>'journalRetainUntil')::timestamptz>at;
END$$;

--
-- Name: protected_copy_view_update_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.protected_copy_view_update_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE spec gridex_ediel_retention.protected_copy_specs%rowtype;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;key text;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.protected_copy_specs WHERE view_name=TG_TABLE_NAME;SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=spec.retention_class AND target_id=OLD.id AND company_id=OLD.company_id;
 IF t.target_id IS NULL OR OLD.document_bytes IS NULL OR NEW.document_bytes IS NOT NULL OR(to_jsonb(OLD)-ARRAY['document_bytes','document_byte_length','document_purged_at']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['document_bytes','document_byte_length','document_purged_at']) OR NEW.document_byte_length IS DISTINCT FROM t.byte_length OR NEW.document_purged_at IS DISTINCT FROM t.created_at THEN RAISE EXCEPTION 'protected_copy_physical_transition_required';END IF;
 key:=CASE spec.source_table WHEN 'certification_classification_revocations' THEN 'declaration_id' ELSE 'id' END;EXECUTE format('UPDATE %I.%I SET %I=NULL WHERE %I=$1',spec.source_schema,spec.source_table,spec.body_field,key) USING OLD.id;RETURN NEW;
END$_$;

--
-- Name: public_content_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.public_content_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT jsonb_build_object('raw',m.raw_payload,'parsed',m.parsed_payload,'validation',m.validation_report,'metadata',m.metadata) $$;

--
-- Name: decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    artifact_id uuid NOT NULL,
    source_hash text NOT NULL,
    claims_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576)))
);

ALTER TABLE ONLY gridex_ediel_retention.decisions FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_v1(gridex_ediel_retention.decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.receipt_v1(d gridex_ediel_retention.decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;
BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 IF k.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=k.id) OR EXISTS(SELECT FROM gridex_ediel_retention.revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,k.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_retention_policy_v1' OR p->>'retentionClass' IS DISTINCT FROM 'requested_change_source_artifact_bytes'
 OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'artifactId' IS DISTINCT FROM d.artifact_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'claimsHash' IS DISTINCT FROM d.claims_hash
 OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'issuerLegalReference' IS DISTINCT FROM k.legal_reference OR nullif(p->>'legalBasisReference','') IS NULL
 OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR issued>now() OR expires<=now() OR issued<k.valid_from OR expires>k.valid_to THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

