end $$;

--
-- Name: record_decisions; Type: TABLE; Schema: gridex_ediel_retention; Owner: -
--

CREATE TABLE gridex_ediel_retention.record_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    retention_class text NOT NULL,
    target_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    contract_id uuid,
    source_hash text NOT NULL,
    target_hash text NOT NULL,
    document_bytes bytea,
    document_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    document_byte_length bigint,
    document_purged_at timestamp with time zone,
    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),
    CONSTRAINT record_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),
    CONSTRAINT record_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),
    CONSTRAINT record_decisions_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT record_decisions_target_hash_check CHECK ((target_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_retention.record_decisions FORCE ROW LEVEL SECURITY;

--
-- Name: record_current_review_v1(gridex_ediel_retention.record_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_current_review_v1(d gridex_ediel_retention.record_decisions) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_ediel_retention.record_reviews%rowtype;claims jsonb;BEGIN
 SELECT * INTO r FROM gridex_ediel_retention.record_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(r.actor_user_id);PERFORM id FROM public.user_profiles WHERE id=r.actor_user_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id FOR SHARE;
 IF r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE OR gridex_ediel_retention.record_permission_v1(d.company_id,r.actor_user_id,d.retention_class) IS NOT TRUE THEN RETURN NULL;END IF;
 claims:=gridex_ediel_retention.record_receipt_v1(d);IF claims IS NULL OR (claims->>'retainUntil')::timestamptz>now() THEN RETURN NULL;END IF;RETURN r.id;
END$$;

