--
-- Name: record_lock_review_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_lock_review_actor_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF public.ediel_retention_lock_auth_actor_v1(actor) IS NOT TRUE THEN RAISE EXCEPTION 'process_retention_current_review_actor_required';END IF;
 PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF gridex_ediel_retention.record_permission_v1(c,actor,'legal_acceptance_personal_snapshot') IS NOT TRUE OR gridex_ediel_retention.permission_v1(c,actor,'ediel.retention.review') IS NOT TRUE THEN RAISE EXCEPTION 'process_retention_current_review_actor_required';END IF;END$$;

--
-- Name: record_permission_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_permission_v1(c uuid, actor uuid, k text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wanted text;BEGIN
 IF k='__read_scope__' THEN wanted:='ediel.retention.read';ELSE SELECT permission_key INTO wanted FROM gridex_ediel_retention.record_class_catalog WHERE retention_class=k;END IF;
 IF wanted IS NULL OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status IN('active','archived','pending_deletion','closed'))
 OR NOT public.ediel_retention_lock_auth_actor_v1(actor)
 OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active' AND to_jsonb(u)->>'disabled_at' IS NULL)
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.permissions WHERE key=wanted AND is_active) THEN RETURN false;END IF;
 IF EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND (o.company_id=c OR o.company_id IS NULL) AND o.is_active AND o.effect='deny' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=now()) AND (o.valid_to IS NULL OR now()<o.valid_to))
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.key=wanted) THEN RETURN false;END IF;
 RETURN EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND o.company_id=c AND o.is_active AND o.effect='allow' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=now()) AND (o.valid_to IS NULL OR now()<o.valid_to));
END$$;

--
-- Name: record_read_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_read_actor_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(actor);PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM id FROM public.companies WHERE id=c FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF public.ediel_retention_session_actor_v1() IS DISTINCT FROM actor OR gridex_ediel_retention.record_permission_v1(c,actor,'__read_scope__') IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_read_actor_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: record_receipt_v1(gridex_ediel_retention.record_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_receipt_v1(d gridex_ediel_retention.record_decisions) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE issuer gridex_ediel_retention.issuers%rowtype;spec gridex_ediel_retention.record_class_catalog%rowtype;body jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_deadline timestamptz;
BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;
 IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;
 SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.record_class_catalog WHERE retention_class=d.retention_class;
 IF issuer.id IS NULL OR now()<issuer.valid_from OR now()>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.record_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;
 bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;
 body:=convert_from(bytes,'UTF8')::jsonb;issued:=(body->>'issuedAt')::timestamptz;expires:=(body->>'expiresAt')::timestamptz;deadline:=(body->>'retainUntil')::timestamptz;journal_deadline:=(body->>'journalRetainUntil')::timestamptz;
 IF body->>'format' IS DISTINCT FROM 'ediel_customer_record_retention_policy_v1' OR body->>'retentionClass' IS DISTINCT FROM d.retention_class OR body->>'sourceTable' IS DISTINCT FROM spec.source_table OR body->>'operation' IS DISTINCT FROM spec.operation OR body->>'companyId' IS DISTINCT FROM d.company_id::text OR body->>'customerId' IS DISTINCT FROM d.customer_id::text OR body->>'targetId' IS DISTINCT FROM d.target_id::text OR body->>'sourceHash' IS DISTINCT FROM d.source_hash OR body->>'targetHash' IS DISTINCT FROM d.target_hash OR body->>'documentHash' IS DISTINCT FROM d.document_hash OR body->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference
 OR nullif(body->>'legalBasisReference','') IS NULL OR nullif(body->>'journalPurposeReference','') IS NULL OR body->>'accessRevocationRequired' IS DISTINCT FROM 'true'
 OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_deadline) IS DISTINCT FROM true OR issued>now() OR expires<=now() OR issued<issuer.valid_from OR expires>issuer.valid_to OR journal_deadline<=now() THEN RETURN NULL;END IF;
 RETURN body;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: record_redacted_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_redacted_v1(k text, rowdata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE fields jsonb;BEGIN SELECT redaction INTO STRICT fields FROM gridex_ediel_retention.record_class_catalog WHERE retention_class=k;
 IF fields->>'recipient_email'='RETENTION_EMAIL' THEN fields:=jsonb_set(fields,'{recipient_email}',to_jsonb('retained-signature-'||(rowdata->>'id')||'@example.invalid'));END IF;
 RETURN rowdata||fields;
END$$;

--
-- Name: record_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_ediel_retention.record_decisions WHERE id=new.decision_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'record_retention_revocation_target_required';END IF;RETURN new;END$$;

--
-- Name: record_target_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.record_target_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE spec gridex_ediel_retention.record_class_catalog%rowtype;t gridex_ediel_retention.record_tombstones%rowtype;BEGIN
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.record_class_catalog WHERE source_table=TG_TABLE_NAME;
 SELECT * INTO t FROM gridex_ediel_retention.record_tombstones WHERE retention_class=spec.retention_class AND target_id=(CASE WHEN TG_OP='INSERT' THEN new.id ELSE old.id END);
 IF FOUND THEN IF TG_OP='UPDATE' AND public.ediel_is_qualified_customer_record_transition_v1(TG_TABLE_NAME,to_jsonb(old),to_jsonb(new)) THEN RETURN new;END IF;RAISE EXCEPTION 'customer_record_retention_tombstoned';END IF;
 IF TG_OP='INSERT' AND TG_TABLE_NAME IN('customer_contract_documents','customer_contract_signature_requests','customer_contract_acceptances','customer_contract_evidence') AND EXISTS(SELECT FROM gridex_ediel_retention.record_tombstones WHERE company_id=new.company_id AND contract_id=(to_jsonb(new)->>'customer_contract_id')::uuid) THEN RAISE EXCEPTION 'customer_contract_records_retention_tombstoned';END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'customer_record_native_class_retention_required';ELSE RETURN new;END IF;
END$$;

--
-- Name: revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_TABLE_NAME='issuer_revocations' THEN PERFORM id FROM gridex_ediel_retention.issuers WHERE id=NEW.issuer_id FOR UPDATE;
 ELSE PERFORM id FROM gridex_ediel_retention.decisions WHERE id=NEW.decision_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_retention_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: signed_brp_intake_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.signed_brp_intake_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (
  gridex_ediel_retention.protected_copy_transition_v1('signed_brp_intake_agreement_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE OR
  gridex_ediel_retention.protected_copy_transition_v1('signed_brp_intake_source_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE
 ) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'ediel_source_append_only';
END$$;

--
-- Name: source_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.source_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' OR old.raw_payload IS NULL OR new.raw_payload IS NOT NULL OR new.retention_purged_at IS NULL OR (to_jsonb(new)-ARRAY['raw_payload','retention_purged_at','scope_point']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['raw_payload','retention_purged_at','scope_point']) OR NOT EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class='received_ediel_message_content' AND t.target_id=old.source_message_id AND t.company_id=old.company_id AND t.source_hash=old.payload_hash AND t.byte_length=octet_length(convert_to(old.raw_payload,'UTF8')) AND t.created_at=new.retention_purged_at) THEN RAISE EXCEPTION 'received_original_immutable_without_native_retention';END IF;RETURN new;END$$;

--
-- Name: source_insert_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.source_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF new.retention_purged_at IS NOT NULL THEN RAISE EXCEPTION 'received_original_new_tombstone_forbidden';END IF;new.retention_byte_length:=octet_length(convert_to(new.raw_payload,'UTF8'));RETURN new;END$$;

--
-- Name: storage_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.storage_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t gridex_ediel_retention.blob_tombstones%rowtype;d gridex_ediel_retention.blob_decisions%rowtype;basis jsonb;r uuid;actor uuid:=public.ediel_retention_session_actor_v1();BEGIN
 IF TG_OP<>'DELETE' AND new.bucket_id='ediel-files' AND EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones WHERE retention_class='transport_raw_mime_bytes' AND storage_path=new.name) THEN RAISE EXCEPTION 'ediel_storage_retention_object_tombstoned';END IF;
 IF (CASE WHEN TG_OP='INSERT' THEN new.bucket_id ELSE old.bucket_id END) IS DISTINCT FROM 'ediel-files' THEN IF TG_OP='DELETE' THEN RETURN old;ELSE RETURN new;END IF;END IF;
 SELECT * INTO t FROM gridex_ediel_retention.blob_tombstones WHERE retention_class='transport_raw_mime_bytes' AND storage_path=(CASE WHEN TG_OP='INSERT' THEN new.name ELSE old.name END);
 IF NOT FOUND THEN IF TG_OP='UPDATE' AND old.name LIKE 'transport/%' AND EXISTS(SELECT FROM public.ediel_message_payloads p WHERE p.encrypted_payload_ref='storage://ediel-files/'||old.name AND p.metadata->>'archive_verified'='true') THEN RAISE EXCEPTION 'ediel_storage_archived_object_immutable';END IF;IF TG_OP='DELETE' AND old.name LIKE 'transport/%' THEN RAISE EXCEPTION 'ediel_storage_native_class_purge_required';END IF;IF TG_OP='DELETE' THEN RETURN old;ELSE RETURN new;END IF;END IF;
 IF TG_OP<>'DELETE' THEN RAISE EXCEPTION 'ediel_storage_retention_object_tombstoned';END IF;
 PERFORM gridex_ediel_retention.actor_v1(t.company_id,actor,'ediel.retention.purge');IF gridex_ediel_retention.class_permission_v1(t.company_id,actor,t.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'blob_retention_scoped_communication_required';END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.blob_decisions WHERE id=t.decision_id FOR UPDATE;r:=gridex_ediel_retention.blob_current_v1(d);basis:=gridex_ediel_retention.blob_basis_v1(t.company_id,t.retention_class,t.target_id);
 IF r IS NULL OR basis->>'targetHash' IS DISTINCT FROM t.target_hash OR basis->>'storagePath' IS DISTINCT FROM old.name THEN RAISE EXCEPTION 'ediel_storage_current_legal_purge_required';END IF;
 INSERT INTO gridex_ediel_retention.blob_events(retention_class,target_id,kind,actor_user_id) VALUES(t.retention_class,t.target_id,'storage_delete_authorized',actor) ON CONFLICT DO NOTHING;RETURN old;
END$$;

--
-- Name: supply_rescission_original_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.supply_rescission_original_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND gridex_ediel_retention.protected_copy_transition_v1('supply_rescission_source_original_bytes',to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'permission_transition_evidence_is_append_only' USING ERRCODE='23514';
END$$;

--
-- Name: actor_current_v1(uuid, uuid, boolean); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.actor_current_v1(c uuid, actor uuid, review boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$ BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 RETURN c IS NOT NULL AND actor IS NOT NULL AND EXISTS(SELECT FROM public.companies x WHERE x.id=c AND x.status='active')
 AND EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
 AND EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
 AND CASE WHEN review THEN gridex_ediel_services.scoped_review_permission_v1(c,actor) ELSE public.gridex_actor_has_company_permission(actor,c,'metering.write') END IS TRUE;
END $$;

--
-- Name: assignment_assessment_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.assignment_assessment_basis_v1(p_provider_company_id uuid, p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.ediel_service_assignments%rowtype; missing text[]:='{}'; k text; t timestamptz:=now(); transport_required boolean;
begin
 select * into a from public.ediel_service_assignments where company_id=p_provider_company_id and id=p_assignment_id for share;
 if not found then return jsonb_build_object('status','held','missing',array['assignment_not_found']); end if;
 if a.scope_basis_version is null or not exists(select from gridex_service_administration.scope_versions sv where sv.company_id=a.company_id and sv.assignment_id=a.id and sv.scope_basis_version=a.scope_basis_version and sv.scope=gridex_service_administration.scope_v1(a)) then return jsonb_build_object('status','held','missing',array['authentic_assignment_scope_journal_required']);end if;
 if a.status<>'active' or a.valid_from>t or (a.valid_to is not null and a.valid_to<=t) then missing:=array_append(missing,'assignment_not_active'); end if;
 perform 1 from public.tenant_ediel_profiles x where x.id=a.actor_profile_id and x.company_id=a.company_id for share;
 perform 1 from public.tenant_actor_roles r where r.company_id=a.company_id and r.actor_id=a.provider_actor_id and r.environment=a.environment for share;
 perform 1 from public.tenant_actor_identifiers i where i.company_id=a.company_id and i.environment=a.environment for share;
 perform 1 from public.tenant_counterparty_relations r where r.company_id=a.company_id and r.environment=a.environment and r.relation_type='ediel_transport_agent' for share;
 if not exists(select 1 from public.tenant_ediel_profiles x where x.id=a.actor_profile_id and x.company_id=a.company_id and x.environment=a.environment and x.market='electricity' and x.is_enabled and x.valid_from<=t and (x.valid_to is null or x.valid_to>t)) then missing:=array_append(missing,'provider_profile_not_current'); end if;
 if not exists(select 1 from public.tenant_actor_roles r where r.company_id=a.company_id and r.actor_id=a.provider_actor_id and r.environment=a.environment and r.role_code='energy_service_company' and r.valid_from<=t and (r.valid_to is null or r.valid_to>t)) then missing:=array_append(missing,'provider_legal_esco_role_missing'); end if;
 if not exists(select 1 from public.tenant_actor_identifiers i where i.company_id=a.company_id and i.actor_id=a.provider_actor_id and i.environment=a.environment and i.identifier_type='EdielId' and length(btrim(i.identifier_value))>0 and i.valid_from<=t and (i.valid_to is null or i.valid_to>t)) then missing:=array_append(missing,'provider_legal_identity_missing'); end if;
 -- Mirror the shared canonical tenant identity: one current legal actor/Ediel ID.
 if (select count(distinct (i.actor_id,i.identifier_value)) from public.tenant_actor_identifiers i where i.company_id=a.company_id and i.environment=a.environment and i.identifier_type='EdielId' and i.valid_from<=t and (i.valid_to is null or i.valid_to>t))<>1 then missing:=array_append(missing,'provider_legal_identity_ambiguous'); end if;
 select exists(select 1 from public.tenant_counterparty_relations r where r.company_id=a.company_id and r.environment=a.environment and r.relation_type='ediel_transport_agent' and r.is_enabled and r.counterparty_actor_id<>a.provider_actor_id and r.valid_from<=t and (r.valid_to is null or r.valid_to>t)) into transport_required;
 perform 1 from public.ediel_service_evidence e where e.company_id=a.company_id and e.assignment_id=a.id for share;
 foreach k in array array['end_user_contract','dso_contract','service_contract','downstream_use','privacy_roles'] loop
  if not exists(select 1 from public.ediel_service_evidence e where e.company_id=a.company_id and e.assignment_id=a.id and e.kind=k and e.status='verified' and e.approved_assignment_version=a.scope_basis_version and e.valid_from<=t and (e.valid_to is null or e.valid_to>t) and e.approved_at<=t) then missing:=array_append(missing,k); end if;
 end loop;
 if (select count(*) from public.tenant_counterparty_relations r where r.company_id=a.company_id and r.environment=a.environment and r.relation_type='ediel_transport_agent' and r.is_enabled and r.valid_from<=t and (r.valid_to is null or r.valid_to>t))>1 then missing:=array_append(missing,'provider_transport_relation_ambiguous'); end if;
 if transport_required and not exists(select 1 from public.ediel_service_evidence e join public.tenant_counterparty_relations r on r.id=e.transport_relation_id and r.counterparty_actor_id=e.transport_actor_id and r.company_id=a.company_id and r.environment=a.environment and r.relation_type='ediel_transport_agent' and r.is_enabled and r.valid_from<=t and (r.valid_to is null or r.valid_to>t) where e.company_id=a.company_id and e.assignment_id=a.id and e.kind='transport_mandate' and e.status='verified' and e.approved_assignment_version=a.scope_basis_version and e.valid_from<=t and (e.valid_to is null or e.valid_to>t) and e.approved_at<=t) then missing:=array_append(missing,'transport_mandate'); end if;
 if cardinality(missing)>0 then return jsonb_build_object('status','held','missing',missing); end if;
 return jsonb_build_object('status','authorized','providerCompanyId',a.company_id,'providerActorId',a.provider_actor_id,'beneficiaryCompanyId',a.beneficiary_company_id,'assignmentId',a.id,'assignmentVersion',a.version,'environment',a.environment,'customerId',a.customer_id,'dsoActorId',a.dso_actor_id,'mode',a.mode,'purpose',a.purpose);
end;
$$;

--
-- Name: ediel_service_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_service_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    beneficiary_company_id uuid NOT NULL,
    provider_actor_id uuid NOT NULL,
    actor_profile_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    dso_actor_id uuid NOT NULL,
    environment text NOT NULL,
    mode text NOT NULL,
    purpose text NOT NULL,
    object_ids text[] NOT NULL,
    product_ids text[] NOT NULL,
    field_sets text[] NOT NULL,
    data_start timestamp with time zone NOT NULL,
    data_end timestamp with time zone,
    valid_from timestamp with time zone NOT NULL,
    valid_to timestamp with time zone,
    status text DEFAULT 'held'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scope_basis_version bigint,
    CONSTRAINT ediel_service_assignments_check CHECK ((company_id <> beneficiary_company_id)),
    CONSTRAINT ediel_service_assignments_check1 CHECK (((data_end IS NULL) OR (data_end > data_start))),
    CONSTRAINT ediel_service_assignments_check2 CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT ediel_service_assignments_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT ediel_service_assignments_field_sets_check CHECK (((cardinality(field_sets) > 0) AND (array_position(field_sets, NULL::text) IS NULL))),
    CONSTRAINT ediel_service_assignments_mode_check CHECK ((mode = ANY (ARRAY['V'::text, 'VH'::text]))),
    CONSTRAINT ediel_service_assignments_object_ids_check CHECK (((cardinality(object_ids) > 0) AND (array_position(object_ids, NULL::text) IS NULL))),
    CONSTRAINT ediel_service_assignments_product_ids_check CHECK (((cardinality(product_ids) > 0) AND (array_position(product_ids, NULL::text) IS NULL))),
    CONSTRAINT ediel_service_assignments_purpose_check CHECK ((length(btrim(purpose)) > 0)),
    CONSTRAINT ediel_service_assignments_scope_basis_version_check CHECK ((scope_basis_version > 0)),
    CONSTRAINT ediel_service_assignments_status_check CHECK ((status = ANY (ARRAY['held'::text, 'active'::text, 'revoked'::text, 'ended'::text]))),
    CONSTRAINT ediel_service_assignments_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.ediel_service_assignments FORCE ROW LEVEL SECURITY;

--
-- Name: current_periodic_reason_agreement_v1(public.ediel_service_assignments, text, text, text); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.current_periodic_reason_agreement_v1(a public.ediel_service_assignments, app text, sender text, receiver text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE k text;e public.ediel_service_evidence%rowtype;artifact gridex_ediel_services.artifacts%rowtype;v gridex_ediel_services.periodic_reason_reviews%rowtype;claims jsonb;result jsonb:='[]';candidate jsonb;
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1();
 FOREACH k IN ARRAY ARRAY['dso_contract','service_contract'] LOOP
  candidate:=NULL;
  FOR e IN SELECT x.* FROM public.ediel_service_evidence x WHERE x.company_id=a.company_id AND x.assignment_id=a.id AND x.kind=k AND x.status='verified' ORDER BY x.id LOOP
   SELECT * INTO v FROM gridex_ediel_services.periodic_reason_reviews WHERE company_id=a.company_id AND evidence_id=e.id ORDER BY review_sequence DESC LIMIT 1;
   IF v.id IS NULL OR v.decision<>'approved' OR v.generic_review_id IS DISTINCT FROM (SELECT r.id FROM gridex_ediel_services.reviews r WHERE r.company_id=a.company_id AND r.evidence_id=e.id ORDER BY r.review_sequence DESC LIMIT 1) OR v.scope_basis_version IS DISTINCT FROM a.scope_basis_version OR gridex_ediel_services.actor_current_v1(a.company_id,v.reviewer_user_id,true) IS NOT TRUE OR gridex_ediel_services.review_current_v1(e) IS NOT TRUE THEN CONTINUE;END IF;
   SELECT * INTO artifact FROM gridex_ediel_services.artifacts WHERE company_id=a.company_id AND id=v.artifact_id;
   claims:=gridex_ediel_services.signed_periodic_reason_claims_v1(artifact);
   IF claims IS NULL OR claims IS DISTINCT FROM v.claims OR v.claims_hash IS DISTINCT FROM encode(sha256(convert_to(claims::text,'UTF8')),'hex')
   OR claims->>'applicationReference' IS DISTINCT FROM app OR claims->>'senderEdielId' IS DISTINCT FROM sender OR claims->>'receiverEdielId' IS DISTINCT FROM receiver THEN CONTINUE;END IF;
   IF candidate IS NOT NULL THEN RAISE EXCEPTION 'ediel_periodic_reason_agreement_ambiguous';END IF;
   candidate:=jsonb_build_object('reasonCode',claims->>'reasonCode','kind',k,'reviewId',v.id,'claimsHash',v.claims_hash,'artifactId',artifact.id,'sourceHash',artifact.source_hash,'scopeHash',artifact.scope_hash,'assignmentId',a.id,'scopeBasisVersion',a.scope_basis_version);
  END LOOP;
  IF candidate IS NULL THEN RETURN NULL;END IF;
  result:=result||jsonb_build_array(candidate);
 END LOOP;
 IF (SELECT count(DISTINCT x->>'reasonCode') FROM jsonb_array_elements(result)x)<>1 THEN RAISE EXCEPTION 'ediel_periodic_reason_contract_agreement_conflict';END IF;
 RETURN result;
END $$;

--
-- Name: requested_method_supported_v1(text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.requested_method_supported_v1(method text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT EXISTS(SELECT FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()) p WHERE p.value->>'method'=method)$$;

--
-- Name: ediel_service_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_service_evidence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    kind text NOT NULL,
    source_reference text NOT NULL,
    source_sha256 text NOT NULL,
    source_version text NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_to timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    approved_assignment_version bigint,
    transport_relation_id uuid,
    transport_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    permission_purpose_code text,
    permission_reporting_frequency text,
    permission_request_grid_area text,
    permission_reporting_term_kind text,
    permission_customer_classification text,
    permission_termination_reason text,
    permission_termination_at timestamp with time zone,
    permission_agreement_reference text,
    permission_requested_method text,
    permission_network_contract_start date,
    permission_network_contract_end date,
    CONSTRAINT ediel_service_evidence_approved_assignment_version_check CHECK ((approved_assignment_version > 0)),
    CONSTRAINT ediel_service_evidence_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT ediel_service_evidence_check1 CHECK (((status <> 'verified'::text) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (approved_assignment_version IS NOT NULL)))),
    CONSTRAINT ediel_service_evidence_check2 CHECK (((kind <> 'transport_mandate'::text) OR ((transport_relation_id IS NOT NULL) AND (transport_actor_id IS NOT NULL)))),
    CONSTRAINT ediel_service_evidence_kind_check CHECK ((kind = ANY (ARRAY['end_user_contract'::text, 'dso_contract'::text, 'service_contract'::text, 'downstream_use'::text, 'privacy_roles'::text, 'transport_mandate'::text]))),
    CONSTRAINT ediel_service_evidence_network_period CHECK (((permission_network_contract_end IS NULL) OR ((permission_network_contract_start IS NOT NULL) AND (permission_network_contract_end >= permission_network_contract_start)))),
    CONSTRAINT ediel_service_evidence_network_period_kind CHECK (((kind = 'dso_contract'::text) OR ((permission_network_contract_start IS NULL) AND (permission_network_contract_end IS NULL)))),
    CONSTRAINT ediel_service_evidence_permission_agreement_reference_check CHECK (((permission_agreement_reference IS NULL) OR ((permission_agreement_reference = btrim(permission_agreement_reference)) AND ((length(permission_agreement_reference) >= 1) AND (length(permission_agreement_reference) <= 35))))),
    CONSTRAINT ediel_service_evidence_permission_customer_classification_check CHECK ((permission_customer_classification = ANY (ARRAY['private'::text, 'nonprivate'::text]))),
    CONSTRAINT ediel_service_evidence_permission_purpose_code_check CHECK ((permission_purpose_code = ANY (ARRAY['B71'::text, 'B72'::text, 'B73'::text, 'B74'::text, 'B75'::text, 'B76'::text]))),
    CONSTRAINT ediel_service_evidence_permission_reporting_term_kind_check CHECK ((permission_reporting_term_kind = ANY (ARRAY['bounded'::text, 'indefinite'::text]))),
    CONSTRAINT ediel_service_evidence_permission_requested_method_check CHECK (((permission_requested_method IS NULL) OR gridex_metering_method_changes.requested_method_supported_v1(permission_requested_method))),
    CONSTRAINT ediel_service_evidence_permission_termination_reason_check CHECK ((permission_termination_reason = ANY (ARRAY['B77'::text, 'B78'::text, 'B79'::text, 'B80'::text, 'E37'::text]))),
    CONSTRAINT ediel_service_evidence_source_reference_check CHECK ((length(btrim(source_reference)) > 0)),
    CONSTRAINT ediel_service_evidence_source_sha256_check CHECK ((source_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ediel_service_evidence_source_version_check CHECK ((length(btrim(source_version)) > 0)),
    CONSTRAINT ediel_service_evidence_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'verified'::text, 'revoked'::text])))
);

