--
-- Name: artifacts; Type: TABLE; Schema: gridex_ediel_services; Owner: -
--

CREATE TABLE gridex_ediel_services.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    assignment_id uuid NOT NULL,
    scope_basis_version bigint NOT NULL,
    scope jsonb NOT NULL,
    scope_hash text NOT NULL,
    evidence_kind text NOT NULL,
    transport_relation_id uuid,
    transport_actor_id uuid,
    evidence_terms jsonb NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    mime_type text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    archived_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['end_user_contract'::text, 'dso_contract'::text, 'service_contract'::text, 'downstream_use'::text, 'privacy_roles'::text, 'transport_mandate'::text]))),
    CONSTRAINT artifacts_evidence_terms_check CHECK ((jsonb_typeof(evidence_terms) = 'object'::text)),
    CONSTRAINT artifacts_mime_type_check CHECK ((mime_type = 'application/pdf'::text)),
    CONSTRAINT artifacts_scope_hash_check CHECK ((scope_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_ediel_services.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_ediel_services.artifacts); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.receipt_current_v1(a gridex_ediel_services.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE k gridex_ediel_services.issuer_keys%rowtype;r gridex_ediel_services.issuer_representations%rowtype;payload jsonb;raw bytea;sig jsonb:=a.issuer_receipt;issued timestamptz;expires timestamptz;
BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 IF sig IS NULL OR jsonb_typeof(sig) IS DISTINCT FROM 'object' OR coalesce(sig->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(sig->>'payloadBase64','')) NOT BETWEEN 1 AND 65536
 OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.scope_hash IS DISTINCT FROM encode(sha256(convert_to(a.scope::text,'UTF8')),'hex') THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_ediel_services.issuer_keys WHERE id=(sig->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment;
 SELECT * INTO r FROM gridex_ediel_services.issuer_representations WHERE id=(sig->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment
 AND legal_actor_id::text=a.scope->>'providerActorId' AND beneficiary_company_id::text=a.scope->>'beneficiaryCompanyId' AND customer_id::text=a.scope->>'customerId' AND dso_actor_id::text=a.scope->>'dsoActorId'
 AND evidence_kind=a.evidence_kind AND scope_hash=a.scope_hash AND transport_relation_id IS NOT DISTINCT FROM a.transport_relation_id AND transport_actor_id IS NOT DISTINCT FROM a.transport_actor_id;
 IF k.id IS NULL OR r.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<r.valid_from OR now()>=r.valid_to
 OR EXISTS(SELECT FROM gridex_ediel_services.issuer_revocations x WHERE x.target_kind='key' AND x.target_id=k.id OR x.target_kind='representation' AND x.target_id=r.id) THEN RETURN false;END IF;
 raw:=decode(sig->>'payloadBase64','base64');IF sha256(gridex_ediel_services.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(sig->>'signatureHex','hex')) THEN RETURN false;END IF;
 payload:=convert_from(raw,'UTF8')::jsonb;issued:=(payload->>'issuedAt')::timestamptz;expires:=(payload->>'expiresAt')::timestamptz;
 RETURN (payload->>'format'='ediel_service_evidence_receipt_v1' AND payload->>'issuerCode'=k.issuer_code AND nullif(payload->>'receiptId','') IS NOT NULL
 AND payload->>'companyId'=a.company_id::text AND payload->>'environment'=a.environment AND payload->>'assignmentId'=a.assignment_id::text
 AND payload->>'scopeBasisVersion'=a.scope_basis_version::text AND payload->'scope'=a.scope AND payload->>'evidenceKind'=a.evidence_kind
 AND payload->'evidenceTerms'=a.evidence_terms AND payload->>'sourceHash'=a.source_hash AND payload->>'sourceReference'=a.source_reference AND payload->>'sourceVersion'=a.source_version
 AND payload->>'transportRelationId' IS NOT DISTINCT FROM a.transport_relation_id::text AND payload->>'transportActorId' IS NOT DISTINCT FROM a.transport_actor_id::text
 AND isfinite(issued) AND isfinite(expires) AND issued<=now() AND expires>now() AND issued>=greatest(k.valid_from,r.valid_from) AND expires<=least(k.valid_to,r.valid_to)) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END $_$;

--
-- Name: receipt_hmac_sha256_v1(bytea, bytea); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.receipt_hmac_sha256_v1(payload bytea, key bytea) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE block bytea;inner_pad bytea:=decode(repeat('00',64),'hex');outer_pad bytea:=decode(repeat('00',64),'hex');n int;
BEGIN block:=CASE WHEN octet_length(key)>64 THEN sha256(key) ELSE key END;block:=block||decode(repeat('00',64-octet_length(block)),'hex');
 FOR n IN 0..63 LOOP inner_pad:=set_byte(inner_pad,n,get_byte(block,n)#54);outer_pad:=set_byte(outer_pad,n,get_byte(block,n)#92);END LOOP;
 RETURN sha256(outer_pad||sha256(inner_pad||payload));END $$;

--
-- Name: require_periodic_outcome_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.require_periodic_outcome_v1(c uuid, sourceid uuid, transactionid text, disposition text, issues jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE source public.ediel_messages%rowtype;ctx jsonb;projection jsonb;own_reason jsonb;
BEGIN
 IF disposition<>'accepted' AND NOT coalesce(issues ? 'UTILTS_PERIODIC_DGI_REASON_INVALID',false) THEN RETURN;END IF;
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1();
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE company_id=c AND id=sourceid;
 IF source.message_family IS DISTINCT FROM 'UTILTS' OR source.message_code IS DISTINCT FROM 'E66' OR (source.application_reference ~ '^23-DGI-E66-(S|T)$') IS NOT TRUE THEN RETURN;END IF;
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,source.environment,sourceid);
 IF (ctx->>'actorRole' IN('energy_service_company','esco')) IS NOT TRUE THEN RETURN;END IF;
 projection:=gridex_ediel_services.periodic_reason_projection_v1(c,source.environment,sourceid);
 SELECT x INTO STRICT own_reason FROM jsonb_array_elements(projection->'expectedReasons')x WHERE x->>'transactionId'=transactionid;
 IF (disposition='accepted' AND own_reason->>'reasonCode' IS DISTINCT FROM own_reason->>'receivedReasonCode')
 OR (coalesce(issues ? 'UTILTS_PERIODIC_DGI_REASON_INVALID',false) AND (disposition<>'guide_rejected' OR own_reason->>'reasonCode' IS NOT DISTINCT FROM own_reason->>'receivedReasonCode')) THEN RAISE EXCEPTION 'utilts_periodic_own_source_outcome_unqualified' USING ERRCODE='P0U01';END IF;
END $_$;

--
-- Name: require_periodic_reason_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.require_periodic_reason_v1(c uuid, env text, sourceid uuid, transactionid text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE projection jsonb;own_reason jsonb;
BEGIN
 projection:=gridex_ediel_services.periodic_reason_projection_v1(c,env,sourceid);
 SELECT x INTO STRICT own_reason FROM jsonb_array_elements(projection->'expectedReasons')x WHERE x->>'transactionId'=transactionid;
 IF own_reason->>'reasonCode' IS DISTINCT FROM own_reason->>'receivedReasonCode' THEN RAISE EXCEPTION 'utilts_esco_periodic_reason_unqualified' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: review_before_source_timing_v1(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.review_before_source_timing_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_evidence_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE archive gridex_ediel_services.artifacts%rowtype;e public.ediel_service_evidence%rowtype;a public.ediel_service_assignments%rowtype;stage gridex_service_administration.commands%rowtype;v gridex_ediel_services.reviews%rowtype;decision text;seq bigint;missing jsonb:='[]';
BEGIN
 IF gridex_ediel_services.actor_current_v1(p_company_id,p_actor_user_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_evidence_reviewer_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) x WHERE x NOT IN('decision','reason','sourceHash','scopeHash')) OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR nullif(btrim(p_review->>'reason'),'') IS NULL OR length(p_review->>'reason')>2000 THEN RAISE EXCEPTION 'ediel_service_evidence_review_shape_invalid';END IF;
 SELECT * INTO archive FROM gridex_ediel_services.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE id=p_evidence_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO a FROM public.ediel_service_assignments WHERE id=e.assignment_id AND company_id=p_company_id;
 SELECT * INTO stage FROM gridex_service_administration.commands WHERE company_id=p_company_id AND input->>'action'='stage_evidence' AND result->>'evidenceId'=e.id::text;
 IF archive.id IS NULL OR e.id IS NULL OR a.id IS NULL OR stage.command_id IS NULL OR p_actor_user_id=archive.submitted_by OR p_actor_user_id=stage.actor_user_id THEN RAISE EXCEPTION 'ediel_service_evidence_separate_owned_review_required';END IF;
 IF archive.source_hash IS DISTINCT FROM p_review->>'sourceHash' OR archive.scope_hash IS DISTINCT FROM p_review->>'scopeHash' THEN RAISE EXCEPTION 'ediel_service_evidence_review_actual_hash_required';END IF;
 IF archive.assignment_id IS DISTINCT FROM a.id OR archive.scope_basis_version IS DISTINCT FROM a.scope_basis_version OR archive.scope IS DISTINCT FROM gridex_service_administration.scope_v1(a)
 OR archive.evidence_kind IS DISTINCT FROM e.kind OR archive.source_hash IS DISTINCT FROM e.source_sha256 OR archive.source_reference IS DISTINCT FROM e.source_reference OR archive.source_version IS DISTINCT FROM e.source_version
 OR archive.evidence_terms IS DISTINCT FROM gridex_ediel_services.evidence_terms_v1(e) OR archive.transport_relation_id IS DISTINCT FROM e.transport_relation_id OR archive.transport_actor_id IS DISTINCT FROM e.transport_actor_id THEN missing:=missing||'"current_exact_assignment_evidence_scope"'::jsonb;END IF;
 IF gridex_ediel_services.receipt_current_v1(archive) IS NOT TRUE THEN missing:=missing||'"authentic_current_issuer_and_representation_receipt"'::jsonb;END IF;
 IF e.valid_from>now() OR (e.valid_to IS NOT NULL AND now()>=e.valid_to) THEN missing:=missing||'"current_evidence_validity_required"'::jsonb;END IF;
 decision:=CASE WHEN p_review->>'decision'='reject' THEN 'rejected' WHEN p_review->>'decision'='hold' OR jsonb_array_length(missing)>0 THEN 'held' ELSE 'approved' END;
 SELECT coalesce(max(review_sequence),0)+1 INTO seq FROM gridex_ediel_services.reviews WHERE company_id=p_company_id AND evidence_id=e.id;
 INSERT INTO gridex_ediel_services.reviews(company_id,artifact_id,evidence_id,stage_command_id,scope_basis_version,evidence_basis,reviewer_user_id,review_sequence,decision,reason,missing)
 VALUES(p_company_id,archive.id,e.id,stage.command_id,a.scope_basis_version,gridex_ediel_services.evidence_basis_v1(e),p_actor_user_id,seq,decision,p_review->>'reason',missing) RETURNING * INTO v;
 IF decision='approved' THEN UPDATE public.ediel_service_evidence SET status='verified',approved_by=p_actor_user_id,approved_at=v.reviewed_at,approved_assignment_version=a.scope_basis_version WHERE id=e.id AND company_id=p_company_id;END IF;
 RETURN jsonb_build_object('status',CASE decision WHEN 'approved' THEN 'verified' ELSE decision END,'companyId',p_company_id,'reviewId',v.id,'reviewSequence',v.review_sequence,'artifactId',archive.id,'evidenceId',e.id,'scopeBasisVersion',a.scope_basis_version,'missing',missing,'marketActivationGranted',false);
END $$;

--
-- Name: review_current_v1(public.ediel_service_evidence); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.review_current_v1(e public.ediel_service_evidence) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE v gridex_ediel_services.reviews%rowtype;archive gridex_ediel_services.artifacts%rowtype;a public.ediel_service_assignments%rowtype;stage gridex_service_administration.commands%rowtype;
BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 SELECT * INTO v FROM gridex_ediel_services.reviews WHERE company_id=e.company_id AND evidence_id=e.id ORDER BY review_sequence DESC LIMIT 1;
 IF v.id IS NULL OR v.decision<>'approved' OR v.reviewed_at>clock_timestamp() OR e.valid_from>now() OR (e.valid_to IS NOT NULL AND now()>=e.valid_to) OR gridex_ediel_services.actor_current_v1(e.company_id,v.reviewer_user_id,true) IS NOT TRUE
 OR e.status IS DISTINCT FROM 'verified' OR e.approved_by IS DISTINCT FROM v.reviewer_user_id OR e.approved_at IS DISTINCT FROM v.reviewed_at
 OR e.approved_assignment_version IS DISTINCT FROM v.scope_basis_version OR gridex_ediel_services.evidence_basis_v1(e) IS DISTINCT FROM v.evidence_basis THEN RETURN false;END IF;
 SELECT * INTO archive FROM gridex_ediel_services.artifacts WHERE id=v.artifact_id AND company_id=e.company_id;
 SELECT * INTO stage FROM gridex_service_administration.commands WHERE command_id=v.stage_command_id AND company_id=e.company_id AND input->>'action'='stage_evidence' AND result->>'evidenceId'=e.id::text;
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=e.company_id AND id=e.assignment_id;
 RETURN archive.id IS NOT NULL AND stage.command_id IS NOT NULL AND v.reviewer_user_id<>archive.submitted_by AND v.reviewer_user_id<>stage.actor_user_id
 AND archive.assignment_id=a.id AND archive.scope_basis_version=a.scope_basis_version AND v.scope_basis_version=a.scope_basis_version
 AND archive.scope IS NOT DISTINCT FROM gridex_service_administration.scope_v1(a) AND archive.evidence_kind=e.kind
 AND archive.source_hash=e.source_sha256 AND archive.source_reference=e.source_reference AND archive.source_version=e.source_version
 AND archive.evidence_terms IS NOT DISTINCT FROM gridex_ediel_services.evidence_terms_v1(e) AND archive.transport_relation_id IS NOT DISTINCT FROM e.transport_relation_id AND archive.transport_actor_id IS NOT DISTINCT FROM e.transport_actor_id
 AND gridex_ediel_services.receipt_current_v1(archive) IS TRUE;
END $$;

--
-- Name: revocation_lock_v1(); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$ BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_ediel_services.issuer_keys WHERE id=NEW.target_id FOR UPDATE;
 ELSE PERFORM id FROM gridex_ediel_services.issuer_representations WHERE id=NEW.target_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_issuer_revocation_target_required';END IF;RETURN NEW;END $$;

--
-- Name: scoped_review_permission_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.scoped_review_permission_v1(c uuid, actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$ BEGIN
 -- The native resolver handles current denies; the explicit scoped grant below
 -- additionally prevents platform/global administrator inheritance.
 RETURN public.gridex_actor_has_company_permission(actor,c,'ediel.service_evidence.review') IS TRUE AND (
 EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key
  WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key='ediel.service_evidence.review')
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key
  WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key='ediel.service_evidence.review'));
END $$;

--
-- Name: signed_periodic_reason_claims_v1(gridex_ediel_services.artifacts); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.signed_periodic_reason_claims_v1(artifact gridex_ediel_services.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE payload jsonb;claims jsonb;a public.ediel_service_assignments%rowtype;sender_ids text[];receiver_ids text[];
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1();
 IF artifact.evidence_kind NOT IN('dso_contract','service_contract') OR gridex_ediel_services.receipt_current_v1(artifact) IS NOT TRUE THEN RETURN NULL;END IF;
 -- Decode only after authenticating the exact original signed payload bytes.
 payload:=convert_from(decode(artifact.issuer_receipt->>'payloadBase64','base64'),'UTF8')::jsonb;
 claims:=payload->'periodicE66Reason';
 IF jsonb_typeof(claims) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(claims) k WHERE k NOT IN('version','reasonCode','applicationReference','senderEdielId','receiverEdielId'))
 OR claims->'version' IS DISTINCT FROM '1'::jsonb OR (claims->>'reasonCode' IN('E23','E88')) IS NOT TRUE
 OR (claims->>'applicationReference'~'^23-DGI-E66-(S|T)$') IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=artifact.company_id AND id=artifact.assignment_id;
 IF a.id IS NULL OR a.scope_basis_version IS DISTINCT FROM artifact.scope_basis_version OR artifact.scope IS DISTINCT FROM gridex_service_administration.scope_v1(a) THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT i.identifier_value ORDER BY i.identifier_value) INTO sender_ids FROM public.platform_actor_identifiers i
  WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified
  AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
 SELECT array_agg(DISTINCT i.identifier_value ORDER BY i.identifier_value) INTO receiver_ids FROM public.tenant_actor_identifiers i
  WHERE i.company_id=a.company_id AND i.actor_id=a.provider_actor_id AND i.environment=a.environment AND i.identifier_type='EdielId'
  AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now());
 IF cardinality(sender_ids) IS DISTINCT FROM 1 OR cardinality(receiver_ids) IS DISTINCT FROM 1
 OR claims->>'senderEdielId' IS DISTINCT FROM sender_ids[1] OR claims->>'receiverEdielId' IS DISTINCT FROM receiver_ids[1]
 OR sender_ids[1]!~'^[0-9]{5}$' OR receiver_ids[1]!~'^[0-9]{5}$' THEN RETURN NULL;END IF;
 RETURN claims;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR character_not_in_repertoire THEN RETURN NULL;
END $_$;

--
-- Name: verified_evidence_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_services; Owner: -
--

CREATE FUNCTION gridex_ediel_services.verified_evidence_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$ BEGIN
 IF NEW.status='verified' AND gridex_ediel_services.review_current_v1(NEW) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_evidence_native_review_required';END IF;RETURN NEW;
END $$;

--
-- Name: capture_before_native_ack_guide_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.capture_before_native_ack_guide_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;e jsonb;p public.ediel_message_profiles%rowtype;r public.ediel_rule_packs%rowtype;sources jsonb;context jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF EXISTS(SELECT FROM gridex_ediel_source_rules.receipts WHERE source_message_id=m.id) THEN RETURN gridex_ediel_source_rules.require_v1(p_company_id,p_message_id);END IF;
 IF m.direction IS DISTINCT FROM 'outbound' THEN RETURN gridex_ediel_source_rules.capture_before_outbound_owner_v1(p_company_id,p_message_id);END IF;
 IF m.message_sent_at IS NOT NULL THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable';END IF;
 e:=gridex_ediel_outbound_owner.require_v1(p_company_id,p_message_id);
 context:=gridex_ediel_inbound_context.require_v1(p_company_id,p_message_id);
 IF context->>'basisKind' IS DISTINCT FROM 'prescribed_outbound_ack' THEN
  SELECT * INTO p FROM public.ediel_message_profiles WHERE id::text=e->>'messageProfileId' AND profile_key=e->>'profileKey' FOR SHARE;
  SELECT * INTO r FROM public.ediel_rule_packs WHERE id=p.rule_pack_id AND id::text=e->>'rulePackId' FOR SHARE;
  PERFORM s.id FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=r.id ORDER BY s.id FOR SHARE;
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=r.id;
  IF p.id IS NULL OR r.id IS NULL OR e#>'{snapshot,rulePack}' IS DISTINCT FROM to_jsonb(r) OR e#>'{snapshot,messageProfile}' IS DISTINCT FROM to_jsonb(p) OR e#>'{snapshot,guideSources}' IS DISTINCT FROM sources THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_scope_invalid';END IF;
 END IF;
 INSERT INTO gridex_ediel_source_rules.receipts(source_message_id,company_id,environment,direction,payload_sha256,original_source_message_id,evidence)
  VALUES(m.id,m.company_id,m.environment,m.direction,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),CASE WHEN context->>'basisKind'='prescribed_outbound_ack' THEN m.related_message_id ELSE NULL END,e);
 RETURN e;
END $$;

--
-- Name: capture_before_outbound_owner_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.capture_before_outbound_owner_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE m public.ediel_messages%rowtype; original public.ediel_messages%rowtype;
 profile public.ediel_message_profiles%rowtype; pack public.ediel_rule_packs%rowtype;
 basis gridex_ediel_source_rules.receipts%rowtype; assessment gridex_received_sources.validation_assessments%rowtype;
 context jsonb; facts jsonb; expected jsonb; evidence jsonb; snapshot jsonb; sources jsonb; observed timestamptz:=clock_timestamp();version text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR nullif(m.raw_payload,'') IS NULL OR m.environment NOT IN('test','production') OR m.direction NOT IN('inbound','outbound') THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
 SELECT * INTO basis FROM gridex_ediel_source_rules.receipts WHERE source_message_id=m.id;
 IF FOUND THEN RETURN gridex_ediel_source_rules.require_v1(p_company_id,p_message_id); END IF;
 -- This is only a first-effect/prepare capture of a genuinely prospective
 -- source. The original identity receipt already froze its persistence clock.
 IF m.message_sent_at IS NOT NULL THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable'; END IF;
 context:=gridex_ediel_inbound_context.require_v1(p_company_id,p_message_id);
 IF context->>'basisKind'='prescribed_outbound_ack' THEN
  SELECT * INTO original FROM public.ediel_messages WHERE id=(context->>'originalSourceMessageId')::uuid AND company_id=p_company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable'; END IF;
  evidence:=gridex_ediel_source_rules.require_v1(p_company_id,original.id);
  IF m.canonical_rule_pack_id::text IS DISTINCT FROM evidence->>'rulePackId' OR m.rule_profile_version_id::text IS DISTINCT FROM evidence->>'messageProfileId'
   OR m.rule_profile_version IS DISTINCT FROM evidence->>'version' OR m.rule_pack_checksum IS DISTINCT FROM evidence->>'sourceHash' THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
  INSERT INTO gridex_ediel_source_rules.receipts(source_message_id,company_id,environment,direction,payload_sha256,original_source_message_id,evidence)
   VALUES(m.id,m.company_id,m.environment,m.direction,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),original.id,evidence);
  RETURN evidence;
 END IF;
 IF m.message_family NOT IN('PRODAT','UTILTS') OR context->>'family' IS DISTINCT FROM m.message_family OR context->>'code' IS DISTINCT FROM m.message_code THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
 IF m.direction='inbound' THEN
  SELECT a.* INTO assessment FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment
   AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)
   AND a.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
  IF NOT FOUND OR assessment.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR assessment.facts_hash IS DISTINCT FROM encode(sha256(convert_to(assessment.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  facts:=assessment.facts_text::jsonb;expected:=facts->'rulePackEvidence';
  IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR jsonb_typeof(expected) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  SELECT * INTO profile FROM public.ediel_message_profiles WHERE id::text=expected->>'messageProfileId' AND profile_key=expected->>'profileKey' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  SELECT * INTO pack FROM public.ediel_rule_packs WHERE id=profile.rule_pack_id AND id::text=expected->>'rulePackId' AND source_hash=expected->>'sourceHash' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  -- The owner's exact accepted original version and named-row snapshot are
  -- part of its immutable facet. Today's matching IDs/hash cannot recreate
  -- a version/profile whose mutable named fields changed before first effect.
  version:=expected->>'version';
  IF nullif(version,'') IS NULL OR jsonb_typeof(expected->'snapshot') IS DISTINCT FROM 'object'
   OR expected#>'{snapshot,rulePack}' IS DISTINCT FROM to_jsonb(pack)
   OR expected#>'{snapshot,messageProfile}' IS DISTINCT FROM to_jsonb(profile) THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable';END IF;
  PERFORM s.id FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id ORDER BY s.id FOR SHARE;
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id;
  IF expected#>'{snapshot,guideSources}' IS DISTINCT FROM sources THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
 ELSE
  SELECT * INTO profile FROM public.ediel_message_profiles WHERE id=m.rule_profile_version_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  SELECT * INTO pack FROM public.ediel_rule_packs WHERE id=profile.rule_pack_id FOR SHARE;
  IF NOT FOUND OR pack.id IS DISTINCT FROM m.canonical_rule_pack_id OR pack.source_hash IS DISTINCT FROM m.rule_pack_checksum
   OR nullif(m.rule_profile_key,'') IS NULL OR nullif(m.rule_profile_version,'') IS NULL OR jsonb_typeof(m.rule_pack_snapshot) IS DISTINCT FROM 'object'
   OR m.rule_pack_snapshot->>'profileKey' IS DISTINCT FROM m.rule_profile_key OR m.rule_pack_snapshot->>'profileVersionId' IS DISTINCT FROM profile.id::text
   OR m.rule_pack_snapshot->>'version' IS DISTINCT FROM m.rule_profile_version OR m.rule_pack_snapshot->>'checksum' IS DISTINCT FROM pack.source_hash THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
  version:=m.rule_profile_version;
 END IF;
 IF pack.family IS DISTINCT FROM m.message_family OR pack.market IS DISTINCT FROM 'electricity' OR NOT profile.is_enabled OR profile.message_code IS DISTINCT FROM m.message_code OR profile.direction NOT IN(m.direction,'both')
  OR coalesce(profile.transaction_subtype,'') IS DISTINCT FROM coalesce(context->>'subtype','') OR gridex_ediel_source_rules.pack_effective_v1(pack.id,m.direction,(observed AT TIME ZONE 'Europe/Stockholm')::date) IS NOT TRUE OR nullif(version,'') IS NULL THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
 expected:=jsonb_build_object('profileKey',profile.profile_key,'messageProfileId',profile.id,'rulePackId',pack.id,'sourceHash',pack.source_hash);
 -- Freeze the exact NAMED rows. No latest pack or independent ACK profile is
 -- selected and no caller binding or historical public snapshot is authority.
 PERFORM s.id FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id ORDER BY s.id FOR SHARE;
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO sources FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id;
 snapshot:=jsonb_build_object('profileKey',profile.profile_key,'profileVersionId',profile.id,'version',version,'checksum',pack.source_hash,
  'originalMessageSnapshot',m.rule_pack_snapshot,'rulePack',to_jsonb(pack),'messageProfile',to_jsonb(profile),'guideSources',sources,'identitySourceEdition',context->'sourceEdition');
 evidence:=expected||jsonb_build_object('version',version,'snapshot',snapshot);
 INSERT INTO gridex_ediel_source_rules.receipts(source_message_id,company_id,environment,direction,payload_sha256,canonical_assessment_id,evidence)
  VALUES(m.id,m.company_id,m.environment,m.direction,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),assessment.id,evidence);
 RETURN evidence;
END $$;

--
-- Name: capture_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.capture_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;m public.ediel_messages%rowtype;
BEGIN
 basis:=gridex_ediel_source_rules.capture_before_native_ack_guide_v1(p_company_id,p_message_id);
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.message_family IN('PRODAT','UTILTS') THEN PERFORM gridex_ediel_ack_guide.bind_source_v1(m,'national',basis);END IF;
 RETURN basis;
END $$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_original_rule_pack_basis_immutable'; END $$;

--
-- Name: pack_effective_v1(uuid, text, date); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.pack_effective_v1(p_pack_id uuid, p_direction text, p_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(
  SELECT FROM public.ediel_rule_packs r
  WHERE r.id=p_pack_id AND r.status IN('active','transition','future') AND r.valid_from<=p_date
   AND (r.valid_to IS NULL OR p_date<=r.valid_to
    OR (p_direction='inbound' AND EXISTS(
     SELECT FROM public.ediel_rule_packs s
     WHERE s.family=r.family AND s.market=r.market AND s.id<>r.id AND s.status IN('active','transition','future')
      AND s.valid_from=r.valid_to+1 AND p_date>=s.valid_from AND p_date<=s.valid_from+13))))
$$;

--
-- Name: probe_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.probe_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype; evidence jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
 IF EXISTS(SELECT FROM gridex_ediel_source_rules.receipts WHERE source_message_id=m.id) THEN
  evidence:=gridex_ediel_source_rules.require_v1(p_company_id,p_message_id);
 ELSIF m.message_sent_at IS NOT NULL OR NOT EXISTS(SELECT FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=m.id) THEN
  -- This only lets native owners inspect an established immutable replay. It
  -- grants no new send/business/ACK capability and never creates a receipt.
  RETURN jsonb_build_object('status','historical');
 ELSE
  evidence:=gridex_ediel_source_rules.capture_v1(p_company_id,p_message_id);
 END IF;
 RETURN jsonb_build_object('status','captured','evidence',evidence);
END $$;

--
-- Name: read_ack_source_before_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.read_ack_source_before_basis_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE ack public.ediel_messages%rowtype; captured gridex_received_sources.sources%rowtype;
 source public.ediel_messages%rowtype; a jsonb; ids uuid[];
BEGIN
 IF current_user<>'service_role' AND session_user<>'service_role' AND coalesce(current_setting('role',true),'')<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production') OR p_ack_message_id IS NULL THEN RAISE EXCEPTION 'ack_execution_scope_required' USING ERRCODE='22023'; END IF;
 SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment AND direction='inbound';
 SELECT * INTO captured FROM gridex_received_sources.sources WHERE source_message_id=ack.id AND company_id=p_company_id AND environment=p_environment;
 IF ack.id IS NULL OR captured.source_message_id IS NULL OR captured.received_context IS NULL OR captured.source_received_at IS NULL
  OR captured.raw_payload IS DISTINCT FROM ack.raw_payload OR captured.payload_hash IS DISTINCT FROM ack.immutable_payload_hash
  OR captured.payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') THEN RETURN NULL; END IF;
 a:=gridex_ack_authority.wire_v1(ack.raw_payload);
 IF a IS NULL OR a->>'environment' IS DISTINCT FROM p_environment THEN RETURN NULL; END IF;
 -- Include every actual historical sent wire; metadata indexes are hints only.
 SELECT array_agg(m.id ORDER BY m.id) INTO ids FROM public.ediel_messages m WHERE m.direction='outbound' AND m.message_sent_at IS NOT NULL AND m.immutable_rendered_at IS NOT NULL
  AND m.immutable_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND gridex_ack_authority.source_match_v1(a,gridex_ack_authority.wire_v1(m.raw_payload));
 IF cardinality(ids) IS DISTINCT FROM 1 THEN RETURN NULL; END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=ids[1] AND company_id=p_company_id AND environment=p_environment;
 IF source.id IS NULL OR source.message_sent_at>captured.source_received_at THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source));
END $$;

--
-- Name: read_outbound_ack_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.read_outbound_ack_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE ack public.ediel_messages%rowtype; source public.ediel_messages%rowtype; evidence jsonb;
BEGIN
 SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment
  AND direction='outbound' AND message_family IN('CONTRL','APERAK','UTILTS_ERR') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_ack_actual_original_unavailable'; END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=ack.related_message_id AND company_id=ack.company_id AND environment=ack.environment AND direction='inbound' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_ack_actual_original_unavailable'; END IF;
 evidence:=gridex_ediel_source_rules.require_v1(p_company_id,source.id);
 RETURN jsonb_build_object('version',1,'ackMessage',to_jsonb(ack),'sourceMessage',to_jsonb(source),'sourceRulePackEvidence',evidence);
END $$;

--
-- Name: read_source_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.read_source_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE source public.ediel_messages%rowtype; evidence jsonb;
BEGIN
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='inbound' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_ack_actual_original_unavailable'; END IF;
 evidence:=gridex_ediel_source_rules.require_v1(p_company_id,source.id);
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source),'sourceRulePackEvidence',evidence);
END $$;

--
-- Name: require_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_source_rules; Owner: -
--

CREATE FUNCTION gridex_ediel_source_rules.require_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE m public.ediel_messages%rowtype; basis gridex_ediel_source_rules.receipts%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
 SELECT * INTO basis FROM gridex_ediel_source_rules.receipts WHERE source_message_id=m.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_rule_pack_basis_unavailable'; END IF;
 IF basis.company_id IS DISTINCT FROM m.company_id OR basis.environment IS DISTINCT FROM m.environment OR basis.direction IS DISTINCT FROM m.direction
  OR basis.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required'; END IF;
 -- Today's message/profile/pack metadata cannot alter the original decision.
 RETURN basis.evidence;
END $$;

--
-- Name: capture_reply_before_native_ack_guide_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.capture_reply_before_native_ack_guide_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;b gridex_ediel_technical_ack.sources%rowtype;v gridex_received_sources.validation_assessments%rowtype;facet gridex_ediel_technical_ack.syntax_facets%rowtype;facts jsonb;evidence jsonb;assessment uuid;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND (company_id=p_company_id OR company_id IS NULL) AND direction='inbound' FOR UPDATE;
 IF EXISTS(SELECT FROM gridex_ediel_technical_ack.replies WHERE source_message_id=m.id) THEN RETURN gridex_ediel_technical_ack.require_source_v1(p_company_id,m.id);END IF;
 SELECT * INTO b FROM gridex_ediel_technical_ack.sources WHERE source_message_id=m.id;
 IF m.id IS NULL OR b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_technical_ack_basis_unavailable';END IF;
 IF b.status<>'ready' OR b.company_id IS DISTINCT FROM p_company_id OR b.environment IS DISTINCT FROM m.environment OR b.source_received_at IS DISTINCT FROM m.message_received_at
  OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 SELECT a.* INTO facet FROM gridex_ediel_technical_ack.syntax_facets a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment AND a.payload_sha256=b.payload_sha256
  AND a.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 IF facet.id IS NOT NULL THEN
  IF facet.facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
  facts:=facet.facts_text::jsonb;assessment:=facet.id;
 ELSE
  SELECT a.* INTO v FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment AND a.source_payload_hash=b.payload_sha256
   AND a.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
   AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
  IF v.id IS NULL OR v.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR v.facts_hash IS DISTINCT FROM encode(sha256(convert_to(v.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
  facts:=v.facts_text::jsonb;assessment:=v.id;
 END IF;
 IF (facts->>'syntaxDecision' IS NULL OR facts->>'syntaxDecision' NOT IN('accepted','rejected')) THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 evidence:=b.evidence||jsonb_build_object('syntaxAssessmentId',assessment,'syntaxDecision',facts->>'syntaxDecision');
 INSERT INTO gridex_ediel_technical_ack.replies VALUES(m.id,p_company_id,m.environment,b.payload_sha256,assessment,evidence);
 RETURN evidence;
END $$;

--
-- Name: capture_reply_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.capture_reply_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;m public.ediel_messages%rowtype;
BEGIN
 basis:=gridex_ediel_technical_ack.capture_reply_before_native_ack_guide_v1(p_company_id,p_message_id);
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND (company_id=p_company_id OR company_id IS NULL) FOR SHARE;
 PERFORM gridex_ediel_ack_guide.bind_source_v1(m,'technical',basis);RETURN basis;
END $$;

--
-- Name: capture_source(); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.capture_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed timestamptz:=clock_timestamp();env jsonb;status text:='ready';reason text;cs uuid[];c uuid;aid uuid;facts jsonb;endpoint text;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF NEW.direction IS DISTINCT FROM 'inbound' OR nullif(NEW.raw_payload,'') IS NULL OR left(NEW.raw_payload,3) NOT IN('UNA','UNB') OR EXISTS(SELECT FROM gridex_ediel_technical_ack.sources WHERE source_message_id=NEW.id) THEN RETURN NEW;END IF;
 env:=gridex_ediel_technical_ack.envelope(NEW.raw_payload);endpoint:=env#>>'{receiver,0}';
 BEGIN
  IF env IS NULL OR env->>'environment' IS DISTINCT FROM NEW.environment THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
  -- A unique actual assigned local TECHNICAL endpoint. Identifiers describe
  -- endpoint ownership here; they never substitute a business NAD actor/role.
  SELECT array_agg(DISTINCT x.company_id) INTO cs FROM (
   SELECT i.company_id FROM public.tenant_actor_identifiers i WHERE i.environment=NEW.environment AND i.identifier_type='EdielId' AND i.identifier_value=endpoint
    AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)
    AND NOT EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=i.company_id AND r.environment=i.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to))
   UNION ALL SELECT r.company_id FROM public.tenant_counterparty_relations r JOIN public.platform_actor_identifiers i ON i.actor_id=r.counterparty_actor_id
    WHERE r.environment=NEW.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to)
     AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND (i.valid_from IS NULL OR i.valid_from<=observed::date) AND (i.valid_to IS NULL OR observed::date<=i.valid_to)
  )x;
  IF cardinality(cs) IS DISTINCT FROM 1 OR (NEW.company_id IS NOT NULL AND NEW.company_id IS DISTINCT FROM cs[1]) THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;c:=cs[1];
  PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=NEW.environment ORDER BY i.id FOR SHARE;
  PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=NEW.environment ORDER BY r.id FOR SHARE;
  IF (SELECT count(*) FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=NEW.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to))>1 THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
  SELECT min(x.actor_id::text)::uuid INTO aid FROM (
   SELECT i.actor_id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=NEW.environment AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)
    AND NOT EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=NEW.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to))
   UNION ALL SELECT r.counterparty_actor_id FROM public.tenant_counterparty_relations r JOIN public.platform_actor_identifiers i ON i.actor_id=r.counterparty_actor_id WHERE r.company_id=c AND r.environment=NEW.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to) AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND (i.valid_from IS NULL OR i.valid_from<=observed::date) AND (i.valid_to IS NULL OR observed::date<=i.valid_to)
  )x HAVING count(DISTINCT x.actor_id)=1;
  IF aid IS NULL THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
  facts:=jsonb_build_object('tenantIdentifiers',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=NEW.environment),'transportRelations',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=NEW.environment AND r.relation_type='ediel_transport_agent'),'platformIdentifiers',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.platform_actor_identifiers i WHERE i.actor_id=aid AND i.identifier_type='EdielId'));
 EXCEPTION WHEN OTHERS THEN status:='held';reason:='ediel_technical_endpoint_unqualified';END;
 INSERT INTO gridex_ediel_technical_ack.sources VALUES(NEW.id,NEW.company_id,c,NEW.environment,encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'),observed,NEW.message_received_at,status,reason,
  jsonb_build_object('kind','technical_syntax_ack','version',1,'companyId',c,'environment',NEW.environment,'sourceMessageId',NEW.id,'sourceHash',encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'),'observedAt',observed,'originalUNB',env,'transportActorId',aid,'transportEdielId',endpoint,'endpointFacts',facts));
 RETURN NEW;
END $$;

--
-- Name: envelope(text); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.envelope(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE advice text:='';body text;sep text:='+';release_char text:='?';terminator text:='''';chars text[];ch text;released boolean:=false;segment_start integer:=1;position integer:=0;segment_raw text;tokens jsonb;u jsonb;unbs integer:=0;header text;ref text;indicator text;
BEGIN
 IF p_raw IS NULL OR octet_length(p_raw)>8388608 THEN RETURN NULL;END IF;
 body:=p_raw;
 IF upper(left(body,3))='UNA' THEN
  IF left(body,3)<>'UNA' OR length(body)<9 THEN RETURN NULL;END IF;
  advice:=left(body,9);sep:=substr(body,5,1);release_char:=substr(body,7,1);terminator:=substr(body,9,1);body:=substr(body,10);
 END IF;
 -- Framing only. Each complete segment is decoded by the existing one-owner
 -- v2 lexer; incomplete/error-bearing body data is never a parsed business AST.
 body:=replace(replace(body,E'\r\n',''),E'\n','');chars:=string_to_array(body,NULL);
 FOREACH ch IN ARRAY chars LOOP
  position:=position+1;
  IF released THEN released:=false;CONTINUE;END IF;
  IF ch=release_char THEN released:=true;CONTINUE;END IF;
  IF ch<>terminator THEN CONTINUE;END IF;
  segment_raw:=substr(body,segment_start,position-segment_start);segment_start:=position+1;
  IF nullif(btrim(segment_raw,E' \t'),'') IS NULL THEN CONTINUE;END IF;
  IF u IS NULL AND left(ltrim(segment_raw,E' \t'),4) IS DISTINCT FROM 'UNB'||sep THEN RETURN NULL;END IF;
  IF left(ltrim(segment_raw,E' \t'),4)='UNB'||sep THEN
   unbs:=unbs+1;IF unbs<>1 THEN RETURN NULL;END IF;
   header:=advice||segment_raw||terminator;tokens:=gridex_utilts_binding.wire_tokens_v1(header);
   IF tokens IS NULL OR jsonb_array_length(tokens)<>1 OR tokens#>>'{0,tag}'<>'UNB'
    OR EXISTS(SELECT FROM unnest(string_to_array(header,NULL))c WHERE ascii(c)>255 OR ascii(c)<32) THEN RETURN NULL;END IF;
   u:=tokens#>'{0,elements}';
  ELSIF left(ltrim(segment_raw,E' \t'),4)='UNH'||sep THEN
   tokens:=gridex_utilts_binding.wire_tokens_v1(advice||segment_raw||terminator);
   IF tokens#>>'{0,elements,2,0}'='CONTRL' THEN RETURN NULL;END IF;
  END IF;
 END LOOP;
 -- A second header beginning an incomplete tail is also ambiguous, not an
 -- excuse to copy the first one. Missing/unterminated first UNB stays held.
 IF u IS NULL OR unbs<>1 OR left(ltrim(substr(body,segment_start),E' \t'),4)='UNB'||sep THEN RETURN NULL;END IF;
 ref:=u#>>'{5,0}';indicator:=coalesce(u#>>'{11,0}','');
 IF nullif(ref,'') IS NULL OR length(ref)>512 OR ref~'[[:cntrl:]]' OR jsonb_array_length(u->5)<>1
  OR nullif(u#>>'{2,0}','') IS NULL OR nullif(u#>>'{3,0}','') IS NULL OR jsonb_array_length(u->2)>3 OR jsonb_array_length(u->3)>3
  OR EXISTS(SELECT FROM jsonb_array_elements_text(u->2||u->3)c WHERE length(c)>35)
  OR coalesce(jsonb_array_length(u->7),1)<>1 OR coalesce(jsonb_array_length(u->11),1)<>1 OR indicator NOT IN('','1') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('sender',u->2,'receiver',u->3,'interchangeReference',ref,'uciReference',left(ref,14),
  'applicationReference',coalesce(u#>>'{7,0}',''),'environment',CASE WHEN indicator='1' THEN 'test' ELSE 'production' END,'testIndicator',indicator);
END $$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN RAISE EXCEPTION 'ediel_technical_ack_basis_immutable';END $$;

--
-- Name: read_endpoint_v1(uuid); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.read_endpoint_v1(p_source_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;b gridex_ediel_technical_ack.sources%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND direction='inbound' FOR SHARE;
 SELECT * INTO b FROM gridex_ediel_technical_ack.sources WHERE source_message_id=m.id;
 IF m.id IS NULL OR b.source_message_id IS NULL OR b.status<>'ready' OR (m.company_id IS NOT NULL AND m.company_id IS DISTINCT FROM b.company_id)
  OR m.environment IS DISTINCT FROM b.environment OR b.source_received_at IS DISTINCT FROM m.message_received_at OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('kind','technical_endpoint_only','companyId',b.company_id,'environment',b.environment,'sourceMessageId',m.id,'sourceHash',b.payload_sha256,'transportEdielId',b.evidence->'transportEdielId','originalUNB',b.evidence->'originalUNB','authorizesBusinessEffect',false);
END $$;

--
-- Name: read_persisted_contrl_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.read_persisted_contrl_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;e jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment AND direction='outbound' AND message_family='CONTRL' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 m.related_message_id:=gridex_ediel_technical_ack.retained_source_v1(m,true);
 e:=gridex_ediel_technical_ack.require_contrl_v1(m);
 RETURN jsonb_build_object('version',1,'authorizesExecution',false,'ackMessage',to_jsonb(m),'technicalSyntaxAckEvidence',e);
END $$;

--
-- Name: read_persisted_contrl_v2(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.read_persisted_contrl_v2(c uuid, env text, ack_id uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;source_id uuid;owned jsonb;e jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 SELECT * INTO m FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=env AND direction='outbound' AND message_family='CONTRL' FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 source_id:=gridex_ediel_technical_ack.retained_source_v1(m,true);
 IF source_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_technical_ack_private_chain_unavailable';END IF;
 owned:=gridex_ediel_duplicate_responses.read_business_original_v1(c,env,source_id,actor,'CONTRL',m.id,phase);
 m:=jsonb_populate_record(NULL::public.ediel_messages,owned->'ackMessage');e:=gridex_ediel_technical_ack.require_contrl_v1(m);
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,env,source_id,actor,'CONTRL',m.id,phase);
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 RETURN jsonb_build_object('version',2,'executionActorUserId',actor,'executionPhase',phase,'ackMessage',to_jsonb(m),'technicalSyntaxAckEvidence',e);
END$$;

--
-- Name: read_route_v1(uuid, uuid, uuid, text, text, integer); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.read_route_v1(c uuid, actor uuid, msg uuid, current_smtp_from text, current_smtp_host text, current_smtp_port integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE e jsonb;BEGIN
 e:=gridex_ediel_technical_ack.require_source_v1(c,msg);
 IF e->>'environment'='test' THEN PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(actor,c);ELSE PERFORM gridex_negative_fixtures.assert_actor_v1(actor,c,'communication.write');END IF;
 RETURN gridex_ediel_technical_ack.select_configured_reply_route_v2(c,e,'CONTRL',current_smtp_from,current_smtp_host,current_smtp_port);END $$;

--
-- Name: record_syntax_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.record_syntax_v1(p_company_id uuid, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;b gridex_ediel_technical_ack.sources%rowtype;f jsonb;prior gridex_ediel_technical_ack.syntax_facets%rowtype;facet_id uuid;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND direction='inbound' FOR UPDATE;
 SELECT * INTO b FROM gridex_ediel_technical_ack.sources WHERE source_message_id=m.id;
 IF m.id IS NULL OR b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_technical_ack_basis_unavailable';END IF;
 IF b.status<>'ready' OR b.company_id IS DISTINCT FROM p_company_id OR (m.company_id IS NOT NULL AND m.company_id IS DISTINCT FROM p_company_id)
  OR b.environment IS DISTINCT FROM m.environment OR b.payload_sha256 IS DISTINCT FROM p_source_payload_hash
  OR p_source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR p_facts_text IS NULL OR octet_length(p_facts_text)>65536 THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 f:=p_facts_text::jsonb;
 IF jsonb_typeof(f)<>'object' OR f-ARRAY['version','owner','syntaxDecision','reasonCodes']<>'{}'::jsonb OR f->'version' IS DISTINCT FROM '1'::jsonb
  OR f->>'owner' IS DISTINCT FROM 'canonical-runtime-syntax-v1' OR (f->>'syntaxDecision' IS NULL OR f->>'syntaxDecision' NOT IN('accepted','rejected'))
  OR jsonb_typeof(f->'reasonCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(f->'reasonCodes')>128
  OR EXISTS(SELECT FROM jsonb_array_elements(f->'reasonCodes')r WHERE jsonb_typeof(r)<>'string' OR r#>>'{}'!~'^[A-Za-z0-9_.:-]{1,128}$') THEN RAISE EXCEPTION 'ediel_technical_syntax_owner_required';END IF;
 SELECT * INTO prior FROM gridex_ediel_technical_ack.syntax_facets WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM m.environment OR prior.payload_sha256 IS DISTINCT FROM p_source_payload_hash OR prior.facts_text IS DISTINCT FROM p_facts_text THEN RAISE EXCEPTION 'ediel_technical_syntax_outcome_immutable';END IF;
  facet_id:=prior.id;
 ELSE
  INSERT INTO gridex_ediel_technical_ack.syntax_facets(source_message_id,company_id,environment,payload_sha256,facts_text,facts_hash)
   VALUES(m.id,p_company_id,m.environment,p_source_payload_hash,p_facts_text,encode(sha256(convert_to(p_facts_text,'UTF8')),'hex')) RETURNING syntax_facets.id INTO facet_id;
 END IF;
 RETURN jsonb_build_object('syntaxAssessmentId',facet_id,'scope','canonical_syntax_only','authorizesBusinessEffect',false);
END $_$;

--
-- Name: require_actor_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.require_actor_v1(c uuid, env text, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;
 PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR env IS NULL OR phase IS NULL OR phase NOT IN('prepare','read','send')
  OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR (CASE phase
   WHEN 'prepare' THEN public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE
    OR env='test' AND public.gridex_actor_has_company_permission(actor,c,'ediel_testing.write') IS TRUE
   WHEN 'read' THEN public.gridex_actor_has_company_permission(actor,c,'communication.read') IS TRUE
   WHEN 'send' THEN public.gridex_actor_has_company_permission(actor,c,'communication.send') IS TRUE
    OR public.gridex_actor_has_company_permission(actor,c,'ediel.send') IS TRUE
   ELSE false END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_technical_ack_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: require_contrl_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.require_contrl_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE source public.ediel_messages%rowtype;evidence jsonb;u jsonb;uci jsonb;tokens jsonb;expected text;header jsonb;trailer jsonb;interchange_trailer jsonb;message_count integer;
BEGIN
 IF EXISTS(SELECT FROM public.ediel_messages own WHERE own.id=m.id AND own.company_id=m.company_id AND own.environment=m.environment AND own.direction='outbound' AND own.message_family='CONTRL' AND own.raw_payload=m.raw_payload) THEN
  m.related_message_id:=gridex_ediel_technical_ack.retained_source_v1(m,true);
  IF m.related_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_technical_ack_private_chain_unavailable';END IF;
 END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'CONTRL' OR m.related_message_id IS NULL THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND direction='inbound' FOR SHARE;
 evidence:=gridex_ediel_technical_ack.require_source_v1(m.company_id,source.id);
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(evidence);
 IF m.environment IS DISTINCT FROM evidence->>'environment' THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UCI')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH' AND x#>>'{elements,2,0}'='CONTRL' AND x#>>'{elements,2,1}'='2' AND x#>>'{elements,2,2}'='2' AND x#>>'{elements,2,3}'='UN')<>1 THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNT')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNZ')<>1 THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 SELECT x->'elements' INTO header FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH';
 SELECT x->'elements' INTO trailer FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNT';
 SELECT x->'elements' INTO interchange_trailer FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNZ';
 SELECT count(*) INTO message_count FROM jsonb_array_elements(tokens)x WHERE x->>'tag' NOT IN('UNA','UNB','UNZ');
 SELECT x->'elements' INTO u FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNB';
 SELECT x->'elements' INTO uci FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UCI';
 IF nullif(header#>>'{1,0}','') IS NULL OR trailer#>>'{2,0}' IS DISTINCT FROM header#>>'{1,0}' OR trailer#>>'{1,0}' IS DISTINCT FROM message_count::text
  OR interchange_trailer#>>'{1,0}' IS DISTINCT FROM '1' OR interchange_trailer#>>'{2,0}' IS DISTINCT FROM u#>>'{5,0}' THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 expected:=CASE WHEN evidence->>'syntaxDecision'='accepted' THEN '1' ELSE '4' END;
 IF u->2 IS DISTINCT FROM evidence#>'{originalUNB,receiver}' OR u->3 IS DISTINCT FROM evidence#>'{originalUNB,sender}'
  OR coalesce(u#>>'{7,0}','') IS DISTINCT FROM evidence#>>'{originalUNB,applicationReference}' OR coalesce(u#>>'{11,0}','') IS DISTINCT FROM evidence#>>'{originalUNB,testIndicator}'
  OR uci#>>'{1,0}' IS DISTINCT FROM evidence#>>'{originalUNB,uciReference}' OR uci->2 IS DISTINCT FROM evidence#>'{originalUNB,sender}' OR uci->3 IS DISTINCT FROM evidence#>'{originalUNB,receiver}' OR uci#>>'{4,0}' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 -- Source-prescribed first14 projection must still identify one original wire
 -- globally, including preserved rows predating this prospective ledger.
 IF (SELECT count(*) FROM (SELECT o.* FROM public.ediel_messages o WHERE o.direction='inbound'
   AND (coalesce(evidence#>>'{originalUNB,uciReference}','') !~ '^[A-Za-z0-9]+$'
   OR (left(o.raw_payload,3)='UNA' AND (substring(o.raw_payload,5,1)<>'+' OR substring(o.raw_payload,7,1)<>'?' OR substring(o.raw_payload,9,1)<>''''))
   OR CASE WHEN char_length(evidence#>>'{originalUNB,uciReference}')=14
    THEN strpos(translate(o.raw_payload,E'?\r\n',''),'+'||(evidence#>>'{originalUNB,uciReference}'))>0
    ELSE strpos(translate(o.raw_payload,E'?\r\n',''),'+'||(evidence#>>'{originalUNB,uciReference}')||'+')>0
     OR strpos(translate(o.raw_payload,E'?\r\n',''),'+'||(evidence#>>'{originalUNB,uciReference}')||'''')>0 END) OFFSET 0) old
  CROSS JOIN LATERAL(SELECT gridex_ediel_technical_ack.envelope(old.raw_payload)e)p
  WHERE old.direction='inbound' AND p.e IS NOT NULL AND p.e->>'environment'=m.environment AND p.e->'sender'=evidence#>'{originalUNB,sender}' AND p.e->'receiver'=evidence#>'{originalUNB,receiver}' AND p.e->>'applicationReference'=evidence#>>'{originalUNB,applicationReference}' AND p.e->>'uciReference'=evidence#>>'{originalUNB,uciReference}')<>1 THEN RAISE EXCEPTION 'ediel_technical_ack_original_ambiguous';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens)cm WHERE cm->>'tag'='UCM' AND NOT EXISTS(SELECT FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(source.raw_payload))h WHERE h->>'tag'='UNH' AND h#>>'{elements,1,0}'=cm#>>'{elements,1,0}')) THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 RETURN evidence;
END $_$;

--
-- Name: require_current_endpoint_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.require_current_endpoint_v1(evidence jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(evidence->>'companyId')::uuid;env text:=evidence->>'environment';aid uuid:=(evidence->>'transportActorId')::uuid;endpoint text:=evidence->>'transportEdielId';observed timestamptz:=clock_timestamp();n integer;companies uuid[];
BEGIN
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=env ORDER BY r.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=aid ORDER BY i.id FOR SHARE;
 SELECT array_agg(DISTINCT x.company_id) INTO companies FROM (
  SELECT i.company_id FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId' AND i.identifier_value=endpoint
   AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)
   AND NOT EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=i.company_id AND r.environment=env AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to))
  UNION ALL SELECT r.company_id FROM public.tenant_counterparty_relations r JOIN public.platform_actor_identifiers i ON i.actor_id=r.counterparty_actor_id
   WHERE r.environment=env AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to)
    AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND (i.valid_from IS NULL OR i.valid_from<=observed::date) AND (i.valid_to IS NULL OR observed::date<=i.valid_to)
 )x;
 IF cardinality(companies) IS DISTINCT FROM 1 OR companies[1] IS DISTINCT FROM c THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
 SELECT count(*) INTO n FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=env AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to);
 IF n=0 THEN
  IF NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env AND i.actor_id=aid AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)) THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
 ELSIF n=1 THEN
  IF NOT EXISTS(SELECT FROM public.tenant_counterparty_relations r JOIN public.platform_actor_identifiers i ON i.actor_id=r.counterparty_actor_id WHERE r.company_id=c AND r.environment=env AND r.counterparty_actor_id=aid AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to) AND i.identifier_type='EdielId' AND i.identifier_value=endpoint AND (i.valid_from IS NULL OR i.valid_from<=observed::date) AND (i.valid_to IS NULL OR observed::date<=i.valid_to)) THEN RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
 ELSE RAISE EXCEPTION 'ediel_technical_endpoint_unqualified';END IF;
END $$;

--
-- Name: require_source_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.require_source_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;b gridex_ediel_technical_ack.sources%rowtype;r gridex_ediel_technical_ack.replies%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND direction='inbound' FOR SHARE;
 SELECT * INTO b FROM gridex_ediel_technical_ack.sources WHERE source_message_id=m.id;
 SELECT * INTO r FROM gridex_ediel_technical_ack.replies WHERE source_message_id=m.id;
 IF m.id IS NULL OR b.source_message_id IS NULL OR r.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_technical_ack_basis_unavailable';END IF;
 IF b.status<>'ready' OR b.company_id IS DISTINCT FROM p_company_id OR (m.company_id IS NOT NULL AND m.company_id IS DISTINCT FROM b.company_id) OR b.environment IS DISTINCT FROM m.environment
  OR b.source_received_at IS DISTINCT FROM m.message_received_at OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR r.payload_sha256 IS DISTINCT FROM b.payload_sha256 THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 RETURN r.evidence;
END $$;

--
-- Name: retained_source_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.retained_source_v1(m public.ediel_messages, complete_chain boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb;h jsonb;candidate uuid;ids uuid[]:='{}';source public.ediel_messages%rowtype;keys jsonb;payload_hash text;
BEGIN
 IF m.id IS NULL OR m.company_id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'CONTRL' OR nullif(m.raw_payload,'') IS NULL THEN RETURN NULL;END IF;
 payload_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 PERFORM 1 FROM gridex_ediel_wire_namespace.coverage WHERE source_message_id=m.id AND company_id=m.company_id AND environment=m.environment AND payload_sha256=payload_hash FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 a:=gridex_ack_authority.wire_v1(m.raw_payload);
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'CONTRL' THEN RETURN NULL;END IF;
 FOR source IN SELECT s.* FROM gridex_ediel_technical_ack.sources b JOIN gridex_ediel_technical_ack.replies r USING(source_message_id)
  JOIN public.ediel_messages s ON s.id=b.source_message_id
  WHERE b.status='ready' AND b.company_id=m.company_id AND r.company_id=b.company_id AND b.environment=m.environment AND r.environment=b.environment
   AND s.direction='inbound' AND s.environment=b.environment AND (s.company_id=b.company_id OR s.company_id IS NULL)
   AND b.payload_sha256=r.payload_sha256 AND b.payload_sha256=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  ORDER BY s.id FOR SHARE OF b,r,s LOOP
  h:=gridex_ediel_technical_ack.envelope(source.raw_payload);
  IF h IS NOT NULL AND a->'sender'=h->'receiver' AND a->'receiver'=h->'sender' AND a->>'environment'=h->>'environment'
   AND a->>'app'=h->>'applicationReference' AND a->>'uciRef'=h->>'uciReference' AND a->'uciSender'=h->'sender' AND a->'uciReceiver'=h->'receiver'
   AND EXISTS(SELECT FROM gridex_ediel_technical_ack.replies r WHERE r.source_message_id=source.id AND r.evidence->'originalUNB'=h
    AND r.evidence->>'syntaxDecision' IN('accepted','rejected') AND a->>'uciAction'=CASE r.evidence->>'syntaxDecision' WHEN 'accepted' THEN '1' ELSE '4' END)
  THEN ids:=array_append(ids,source.id);END IF;
 END LOOP;
 IF cardinality(ids)>1 THEN RAISE EXCEPTION 'ediel_technical_ack_original_ambiguous';END IF;
 candidate:=ids[1];IF candidate IS NULL OR NOT complete_chain THEN RETURN candidate;END IF;
 IF m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM payload_hash THEN RETURN NULL;END IF;
 keys:=gridex_ediel_wire_namespace.keys(m.raw_payload);
 PERFORM 1 FROM gridex_ediel_wire_namespace.reservations r WHERE r.source_message_id=m.id ORDER BY r.environment,r.sender_namespace,r.application_namespace,r.reference_kind,r.wire_reference FOR SHARE;
 IF EXISTS(SELECT FROM jsonb_array_elements(keys)k WHERE NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.reservations r
  WHERE r.environment=m.environment AND r.sender_namespace=k->>'sender' AND r.application_namespace=k->>'application' AND r.reference_kind=k->>'kind'
   AND r.wire_reference=k->>'value' AND r.source_message_id=m.id AND r.company_id=m.company_id AND r.first_payload_sha256=payload_hash)) THEN RETURN NULL;END IF;
 RETURN candidate;
END$$;

--
-- Name: select_configured_reply_route_v2(uuid, jsonb, text, text, text, integer); Type: FUNCTION; Schema: gridex_ediel_technical_ack; Owner: -
--

CREATE FUNCTION gridex_ediel_technical_ack.select_configured_reply_route_v2(c uuid, e jsonb, reply_family text, current_smtp_from text, current_smtp_host text, current_smtp_port integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE u jsonb;msg uuid:=(e->>'sourceMessageId')::uuid;route public.communication_routes%rowtype;profile public.ediel_route_profiles%rowtype;runtime jsonb;candidate_ids uuid[];candidate_profile_ids uuid[];env text;original public.ediel_messages%rowtype;reception gridex_ediel_inbound_receptions.receptions%rowtype;original_box public.ediel_mailboxes%rowtype;birth_smtp text;technical_birth record;smtp_birth gridex_ediel_inbound_receptions.technical_mailbox_births%rowtype;common_basis jsonb;
BEGIN
 IF reply_family IS NULL OR reply_family NOT IN('CONTRL','APERAK') OR e->>'companyId' IS DISTINCT FROM c::text THEN RAISE EXCEPTION 'ediel_prescribed_reply_route_basis_required';END IF;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(e);u:=e->'originalUNB';env:=e->>'environment';
 IF reply_family='APERAK' THEN
  SELECT b.evidence INTO common_basis FROM gridex_ediel_common_header.sources b WHERE b.source_message_id=msg AND b.company_id=c AND b.environment=env AND b.status='ready';
  IF common_basis#>>'{negativeField,fieldCode}'='311' THEN
   common_basis:=gridex_ediel_common_header.require_v1(c,env,msg);
   PERFORM gridex_ediel_header_negative_birth.require_fresh_reply_process_v1(m,common_basis) FROM public.ediel_messages m WHERE m.id=msg;
   SELECT jsonb_set(u,'{applicationReference}',to_jsonb(gridex_ediel_header_negative_birth.reply_application_v1(m,common_basis))) INTO u FROM public.ediel_messages m WHERE m.id=msg;
  END IF;
 END IF;
 IF current_smtp_from IS NULL OR current_smtp_from!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$' OR nullif(current_smtp_host,'') IS NULL OR current_smtp_port NOT BETWEEN 1 AND 65535 THEN RAISE EXCEPTION 'ediel_technical_ack_smtp_account_unqualified';END IF;
 -- Hold the configured candidate universe stable; duplicate matches are held,
 -- never chosen by age, preference, old email or a local role/default APP.
 SELECT * INTO original FROM public.ediel_messages WHERE id=msg AND (company_id=c OR company_id IS NULL) FOR SHARE;
 IF original.id IS NULL OR original.direction IS DISTINCT FROM 'inbound' OR original.environment IS DISTINCT FROM env
  OR nullif(original.mailbox_message_id,'') IS NULL OR nullif(original.raw_payload,'') IS NULL
  OR e->>'sourceHash' IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'ediel_original_mailbox_source_required';END IF;
 IF original.company_id IS NULL THEN
  IF gridex_unattributed_intake.is_birth_v1(original) IS NOT TRUE
   OR gridex_ediel_technical_ack.require_source_v1(c,original.id) IS DISTINCT FROM e
  THEN RAISE EXCEPTION 'ediel_original_mailbox_source_required';END IF;
  IF reply_family='APERAK' THEN
   common_basis:=gridex_ediel_common_header.require_v1(c,env,original.id);
   PERFORM gridex_ediel_common_header.require_current_scope_v1(common_basis);
   IF e->>'sourceHash' IS DISTINCT FROM common_basis->>'sourceHash'
    OR e->>'syntaxAssessmentId' IS DISTINCT FROM common_basis->>'syntaxAssessmentId'
   THEN RAISE EXCEPTION 'ediel_common_header_route_basis_mismatch';END IF;
  END IF;
  SELECT * INTO technical_birth FROM gridex_unattributed_intake.technical_births WHERE source_message_id=original.id FOR SHARE;
  PERFORM gridex_unattributed_intake.require_custody_v1(technical_birth.inbound_email_message_id,technical_birth.parse_result_id);
  IF NOT EXISTS(SELECT FROM gridex_ediel_technical_ack.sources source
   WHERE source.source_message_id=original.id AND source.company_id=c AND source.source_company_id IS NULL
    AND source.status='ready' AND source.environment=env AND source.payload_sha256=e->>'sourceHash'
    AND source.source_received_at=original.message_received_at)
   OR NOT EXISTS(SELECT FROM gridex_unattributed_intake.physical_claims claim
    WHERE claim.protected_source_id=original.id
     AND claim.physical_key=gridex_unattributed_intake.physical_key_v1(technical_birth.physical_envelope))
  THEN RAISE EXCEPTION 'ediel_original_mailbox_source_required';END IF;
  SELECT * INTO smtp_birth FROM gridex_ediel_inbound_receptions.technical_mailbox_births
   WHERE inbound_email_message_id=technical_birth.inbound_email_message_id AND environment=env FOR SHARE;
  birth_smtp:=smtp_birth.smtp_address;
  IF smtp_birth.inbound_email_message_id IS NULL OR birth_smtp IS NULL
   OR birth_smtp!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
   OR lower(btrim(current_smtp_from)) IS DISTINCT FROM lower(birth_smtp)
   OR NOT EXISTS(SELECT FROM gridex_unattributed_intake.raw_births raw
    WHERE raw.inbound_email_message_id=smtp_birth.inbound_email_message_id
     AND raw.snapshot_hash=smtp_birth.raw_snapshot_hash AND raw.observed_at=smtp_birth.observed_at)
  THEN RAISE EXCEPTION 'ediel_original_mailbox_smtp_custody_required';END IF;
  SELECT box.* INTO original_box FROM public.ediel_mailboxes box
   JOIN public.inbound_email_messages mail ON mail.mailbox_id=box.id
   WHERE mail.id=technical_birth.inbound_email_message_id AND box.id=smtp_birth.mailbox_id
    AND original.mailbox_message_id=mail.id::text AND original.inbound_email_message_id=mail.id
    AND mail.company_id IS NULL AND mail.environment=env AND box.environment=env AND box.is_active
    AND (box.company_id=c OR box.company_id IS NULL)
    AND box.company_id IS NOT DISTINCT FROM smtp_birth.mailbox_company_id
    AND box.is_shared_platform_mailbox IS NOT DISTINCT FROM smtp_birth.mailbox_shared
   FOR SHARE OF box,mail;
  IF original_box.id IS NULL THEN RAISE EXCEPTION 'ediel_original_mailbox_source_required';END IF;
  -- Recheck complete custody after the mailbox lock, including mailbox_type.
  PERFORM gridex_unattributed_intake.require_custody_v1(technical_birth.inbound_email_message_id,technical_birth.parse_result_id);
 ELSE
 SELECT * INTO reception FROM gridex_ediel_inbound_receptions.receptions
  WHERE source_message_id=original.id AND company_id=c AND environment=env
   AND classification='first_reception' AND inbound_email_message_id::text=original.mailbox_message_id FOR SHARE;
 birth_smtp:=reception.transport_source_snapshot->>'originalMailboxSmtpAddress';
 IF reception.id IS NULL OR reception.canonical_payload_hash IS DISTINCT FROM e->>'sourceHash'
  OR reception.received_payload_hash IS DISTINCT FROM reception.canonical_payload_hash
  OR reception.transport_source_snapshot->>'parsePayloadHash' IS DISTINCT FROM reception.received_payload_hash
  OR reception.transport_source_snapshot->>'originalMailboxEnvironment' IS DISTINCT FROM env
  OR birth_smtp IS NULL OR birth_smtp!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
  OR lower(btrim(current_smtp_from)) IS DISTINCT FROM lower(birth_smtp)
 THEN RAISE EXCEPTION 'ediel_original_mailbox_smtp_custody_required';END IF;
 SELECT box.* INTO original_box FROM public.ediel_mailboxes box
  JOIN public.inbound_email_messages mail ON mail.mailbox_id=box.id
  WHERE mail.id=reception.inbound_email_message_id AND box.id::text=reception.transport_source_snapshot->>'mailboxId'
   AND (mail.company_id IS NULL OR mail.company_id=c) AND (mail.environment IS NULL OR mail.environment=env)
   AND box.environment=env AND box.is_active
   AND (box.company_id=c OR box.company_id IS NULL OR box.is_shared_platform_mailbox)
   AND (reception.transport_source_snapshot->>'originalMailboxCompanyId'=c::text
    OR reception.transport_source_snapshot->>'originalMailboxCompanyId' IS NULL
    OR reception.transport_source_snapshot->'originalMailboxShared'='true'::jsonb)
  FOR SHARE OF box,mail;
 IF original_box.id IS NULL THEN RAISE EXCEPTION 'ediel_original_mailbox_source_required';END IF;
 END IF;
 LOCK TABLE public.communication_routes,public.ediel_route_profiles,public.ediel_transport_profiles IN SHARE MODE;
 SELECT array_agg(r.id),array_agg(p.id) INTO candidate_ids,candidate_profile_ids FROM public.communication_routes r JOIN public.ediel_route_profiles p ON p.communication_route_id=r.id AND p.company_id=r.company_id
 LEFT JOIN public.ediel_transport_profiles tp ON tp.id=p.transport_profile_id AND tp.company_id=c AND tp.environment=env
 WHERE r.company_id=c AND r.is_active AND r.route_scope='ediel_ack'
  AND ((env='production' AND r.environment_type::text='production') OR(env='test' AND r.environment_type::text IN('tgt_test','agt_test','bilateral_test')))
  AND p.environment=env AND p.is_enabled AND p.is_active AND p.message_standard='edifact' AND p.payload_format='edifact'
  AND (p.message_family IS NULL OR p.message_family=reply_family) AND (p.business_code IS NULL OR p.business_code=reply_family)
  AND p.sender_ediel_id=u#>>'{receiver,0}' AND p.receiver_ediel_id=u#>>'{sender,0}'
  AND coalesce(p.sender_subaddress,p.sender_sub_address,'')=coalesce(u#>>'{receiver,2}','')
  AND coalesce(p.receiver_subaddress,p.receiver_sub_address,'')=coalesce(u#>>'{sender,2}','')
  AND (p.sender_subaddress IS NULL OR p.sender_sub_address IS NULL OR p.sender_subaddress=p.sender_sub_address)
  AND (p.receiver_subaddress IS NULL OR p.receiver_sub_address IS NULL OR p.receiver_subaddress=p.receiver_sub_address)
  AND p.application_reference IS NOT DISTINCT FROM u->>'applicationReference' AND p.mailbox=current_smtp_from
  AND r.target_email~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
  AND ((p.transport_profile_id IS NULL AND p.smtp_host=current_smtp_host AND p.smtp_port=current_smtp_port)
    OR(tp.id IS NOT NULL AND tp.is_active AND tp.transport_channel='smtp' AND tp.direction IN('outbound','both') AND tp.sender_email=current_smtp_from AND tp.host=current_smtp_host AND tp.port=current_smtp_port
      AND(p.smtp_host IS NULL OR p.smtp_host=current_smtp_host) AND(p.smtp_port IS NULL OR p.smtp_port=current_smtp_port)));
 IF coalesce(cardinality(candidate_ids),0)<>1 THEN RAISE EXCEPTION 'ediel_technical_ack_route_count:%',coalesce(cardinality(candidate_ids),0);END IF;
 -- Read precisely the one named pair selected by that complete locked predicate.
 SELECT * INTO STRICT route FROM public.communication_routes r WHERE r.id=candidate_ids[1] AND r.company_id=c FOR SHARE;
 SELECT * INTO STRICT profile FROM public.ediel_route_profiles p WHERE p.id=candidate_profile_ids[1] AND p.company_id=c FOR SHARE;
 runtime:=to_jsonb(profile)||jsonb_build_object('route_profile_id',profile.id,'communication_route_id',route.id,'route_name',route.route_name,'communication_route_active',route.is_active,'route_scope',route.route_scope,'route_type',route.route_type,'grid_owner_id',route.grid_owner_id,'target_system',route.target_system,'endpoint',route.endpoint,'target_email',route.target_email,'supported_payload_version',route.supported_payload_version,'communication_route_notes',route.notes,'route_profile_notes',profile.notes);
 RETURN jsonb_build_object('kind',CASE WHEN reply_family='CONTRL' THEN 'technical_syntax_ack_route' ELSE 'prodat_common_header_negative_ack_route' END,'smtpHost',current_smtp_host,'smtpPort',current_smtp_port,'companyId',c,'environment',env,'sourceMessageId',msg,'sourceHash',e->>'sourceHash',
  'route',to_jsonb(route)||jsonb_build_object('auth_config','{}'::jsonb),'routeRuntime',runtime,'senderEdielId',u#>>'{receiver,0}','senderQualifier',nullif(u#>>'{receiver,1}',''),'senderSubAddress',nullif(u#>>'{receiver,2}',''),
  'receiverEdielId',u#>>'{sender,0}','receiverQualifier',nullif(u#>>'{sender,1}',''),'receiverSubAddress',nullif(u#>>'{sender,2}',''),'receiverMessageSubAddress',nullif(u#>>'{sender,2}',''),
  'applicationReference',u->>'applicationReference','senderEmail',current_smtp_from,'receiverEmail',route.target_email,'mailbox',current_smtp_from,
  'routeKey',concat(lower(reply_family),'_source_reply|',route.id,'|',profile.id,'|',env,'|',u->>'applicationReference'),'authorizesBusinessEffect',false);
END $_$;

--
-- Name: accepted_source_basis_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.accepted_source_basis_v1(p_message public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;candidates jsonb;candidate jsonb;binding jsonb;provider jsonb;plan jsonb;recipient text;original_hash text;
 p_company_id uuid:=p_message.company_id;p_environment text:=p_message.environment;p_message_id uuid:=p_message.id;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR (p_environment IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR SHARE;
 IF m.raw_payload IS DISTINCT FROM p_message.raw_payload OR m.immutable_payload_hash IS DISTINCT FROM p_message.immutable_payload_hash THEN RAISE EXCEPTION 'ediel_accepted_projection_original_changed';END IF;
 -- Both journals are private, append-only observations. A latest/default
 -- attempt, route, guide or market permission is never selected here.
 SELECT coalesce(jsonb_agg(v),'[]') INTO candidates FROM (
  SELECT jsonb_build_object('lane','generic_journal','attemptId',a.id,'binding',a.binding,'providerReceipt',a.provider_result,'observedAt',a.observed_at,'entered',a.entered_at IS NOT NULL,'originalHash',a.binding->>'originalHash') v
   FROM gridex_ediel_transport.attempts a WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.message_id=p_message_id AND a.classification='accepted'
  UNION ALL
  SELECT jsonb_build_object('lane','sealed_z08','attemptId',a.id,'binding',a.binding,'providerReceipt',e.facts->'provider','observedAt',e.observed_at,
    'entered',EXISTS(SELECT FROM gridex_outbound_dispatch.events entry WHERE entry.attempt_id=a.id AND entry.company_id=p_company_id AND entry.environment=p_environment AND entry.message_id=p_message_id AND entry.kind='provider_call_entered'),
    'originalHash',o.payload_hash,'sealedHash',encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex'))
   FROM gridex_outbound_dispatch.attempts a JOIN gridex_outbound_dispatch.originals o ON o.message_id=a.message_id AND o.company_id=a.company_id AND o.environment=a.environment
   JOIN gridex_outbound_dispatch.events e ON e.attempt_id=a.id AND e.company_id=a.company_id AND e.environment=a.environment AND e.message_id=a.message_id AND e.kind='provider_result' AND e.facts->>'classification'='accepted'
   WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.message_id=p_message_id
  LIMIT 2
 ) receipts;
 IF jsonb_array_length(candidates)=0 THEN RETURN NULL;END IF;
 IF jsonb_array_length(candidates)<>1 THEN RAISE EXCEPTION 'ediel_accepted_projection_ambiguous';END IF;
 candidate:=candidates->0;binding:=candidate->'binding';provider:=candidate->'providerReceipt';plan:=binding->'businessExpectationPlan';recipient:=nullif(binding->>'to','');
 original_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 IF m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM original_hash OR candidate->>'originalHash' IS DISTINCT FROM original_hash OR binding->>'originalHash' IS DISTINCT FROM original_hash OR (candidate->>'lane'='sealed_z08' AND candidate->>'sealedHash' IS DISTINCT FROM original_hash) THEN RAISE EXCEPTION 'ediel_accepted_projection_original_changed';END IF;
 IF candidate->>'entered' IS DISTINCT FROM 'true' OR nullif(candidate->>'observedAt','') IS NULL OR NOT isfinite((candidate->>'observedAt')::timestamptz) OR recipient IS NULL
  OR jsonb_typeof(provider) IS DISTINCT FROM 'object' OR jsonb_typeof(provider->'accepted') IS DISTINCT FROM 'array' OR jsonb_typeof(provider->'rejected') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'ediel_accepted_projection_receipt_invalid';END IF;
 IF jsonb_array_length(provider->'accepted')<1 OR jsonb_array_length(provider->'rejected')<>0 OR EXISTS(SELECT FROM jsonb_array_elements(provider->'accepted') v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string' OR lower(v#>>'{}') IS DISTINCT FROM lower(recipient)) OR (provider->>'messageId' IS NOT NULL AND jsonb_typeof(provider->'messageId') IS DISTINCT FROM 'string') OR (provider->>'response' IS NOT NULL AND jsonb_typeof(provider->'response') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'ediel_accepted_projection_expected_recipient_required';END IF;
 IF plan IS NOT NULL AND plan<>'null'::jsonb AND (jsonb_typeof(plan) IS DISTINCT FROM 'object' OR plan->>'version' IS DISTINCT FROM '1' OR plan->>'sourceCode' IS DISTINCT FROM m.message_code OR plan->>'expectedFamily' IS DISTINCT FROM 'PRODAT' OR plan->>'anchor' IS DISTINCT FROM 'actual_accepted_smtp_observed_at') THEN RAISE EXCEPTION 'ediel_accepted_projection_frozen_plan_invalid';END IF;
 RETURN jsonb_build_object('status','accepted_projection','companyId',p_company_id,'environment',p_environment,'messageId',p_message_id,'attemptId',candidate->>'attemptId','lane',candidate->>'lane','originalHash',original_hash,'observedAt',candidate->>'observedAt','providerReceipt',jsonb_build_object('accepted',provider->'accepted','rejected',provider->'rejected','messageId',provider->'messageId','response',provider->'response'),'frozenRecipient',recipient,'businessExpectationPlan',plan,'authorizesProviderEntry',false,'deliveryProven',false);
END $$;

--
-- Name: canonical_message_code_v1(text, text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.canonical_message_code_v1(family text, storage_code text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(projection->'logicalCodes'->>upper(btrim(family)),storage_code) FROM gridex_ediel_transport.technical_expectation_editions WHERE source_version='05abbd87fb53e2a4e5e0583741e4dad6fed9f525010420e93c12e9b5c3dfda98'
$$;

--
-- Name: dsn_boundary_v1(text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_boundary_v1(content_type text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE pair text[];value text;hex text;
BEGIN
 pair:=regexp_match(content_type,';[ \t]*boundary[ \t]*=[ \t]*(?:"([^"\n]*)"|([^; \t\n]+))','i');
 IF pair IS NOT NULL THEN RETURN coalesce(pair[1],pair[2]);END IF;
 pair:=regexp_match(content_type,';[ \t]*boundary\*[ \t]*=[ \t]*(?:"([^"\n]*)"|([^; \t\n]+))','i');
 pair:=regexp_match(coalesce(pair[1],pair[2],''),'^(?:utf-8|us-ascii)''[^'']*''(.*)$','i');
 IF pair IS NULL THEN RETURN NULL;END IF;
 value:=pair[1];
 IF value~'%(?![A-Fa-f0-9]{2})' THEN RAISE EXCEPTION 'dsn_boundary_invalid';END IF;
 SELECT string_agg(CASE WHEN left(token[1],1)='%' THEN substr(token[1],2) ELSE encode(convert_to(token[1],'UTF8'),'hex') END,'') INTO hex
  FROM regexp_matches(value,'%[A-Fa-f0-9]{2}|[^%]','g') token;
 RETURN convert_from(decode(coalesce(hex,''),'hex'),'UTF8');
END $_$;

--
-- Name: dsn_candidates_v1(uuid, text, text, text, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_candidates_v1(p_company_id uuid, p_environment text, p_rfc_message_id text, p_final_recipient text, p_mailbox_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN('test','production') OR p_environment IS NULL OR nullif(btrim(p_rfc_message_id),'') IS NULL OR nullif(btrim(p_final_recipient),'') IS NULL OR p_mailbox_id IS NULL THEN RAISE EXCEPTION 'ediel_dsn_scope_required';END IF;
 IF NOT EXISTS(SELECT FROM public.ediel_mailboxes b WHERE b.id=p_mailbox_id AND b.environment=p_environment AND b.is_active AND (b.company_id=p_company_id OR b.company_id IS NULL AND b.is_shared_platform_mailbox)) THEN RAISE EXCEPTION 'ediel_dsn_mailbox_scope_invalid';END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('attemptId',a.id,'messageId',a.message_id,'environment',a.environment,'enteredAt',a.entered_at,'observedAt',a.observed_at,'smtpClassification',a.classification,'lane',a.lane,'correlationStatus','unverified') ORDER BY a.created_at,a.id,a.lane)
  FROM gridex_ediel_transport.dsn_matchable_attempts_v1 a WHERE a.company_id=p_company_id AND a.environment=p_environment
   AND a.binding->>'sourceMailboxId'=p_mailbox_id::text
   AND a.binding->>'rfcMessageId'=p_rfc_message_id AND lower(a.binding->>'to')=lower(p_final_recipient)),'[]'::jsonb);
END $$;

--
-- Name: dsn_decode_body_v1(text, text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_decode_body_v1(body text, encoding text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE compact text;hex text;
BEGIN
 IF encoding IN('7bit','8bit','binary') THEN RETURN body;END IF;
 IF encoding='base64' THEN
  compact:=regexp_replace(body,'[[:space:]]','','g');
  IF compact!~'^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' THEN RAISE EXCEPTION 'dsn_encoding_invalid';END IF;
  RETURN convert_from(decode(compact,'base64'),'UTF8');
 ELSIF encoding='quoted-printable' THEN
  compact:=replace(body,E'=\n','');
  IF compact~'=(?![A-Fa-f0-9]{2})' THEN RAISE EXCEPTION 'dsn_encoding_invalid';END IF;
  SELECT string_agg(CASE WHEN left(token[1],1)='=' THEN substr(token[1],2) ELSE encode(convert_to(token[1],'UTF8'),'hex') END,'') INTO hex
   FROM regexp_matches(compact,'=[A-Fa-f0-9]{2}|[^=]','g') token;
  RETURN convert_from(decode(coalesce(hex,''),'hex'),'UTF8');
 END IF;
 RAISE EXCEPTION 'dsn_encoding_unsupported';
END $_$;

--
-- Name: dsn_field_v1(jsonb, text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_field_v1(fields jsonb, name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF jsonb_array_length(coalesce(fields->name,'[]'::jsonb))>1 THEN RAISE EXCEPTION 'dsn_field_ambiguous';END IF;
 RETURN nullif(fields->name->>0,'');
END $$;

--
-- Name: dsn_fields_v1(text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_fields_v1(block text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE fields jsonb:='{}';line text;pair text[];key text;
BEGIN
 IF octet_length(block)>65536 THEN RAISE EXCEPTION 'dsn_field_limit';END IF;
 FOREACH line IN ARRAY string_to_array(regexp_replace(replace(block,E'\r\n',E'\n'),E'\n[ \t]+',' ','g'),E'\n') LOOP
  pair:=regexp_match(line,'^([!-9;-~]+):[ \t]*(.*)$');
  IF pair IS NULL THEN CONTINUE;END IF;
  key:=lower(pair[1]);
  fields:=jsonb_set(fields,ARRAY[key],coalesce(fields->key,'[]'::jsonb)||to_jsonb(btrim(pair[2],E' \t')));
 END LOOP;
 RETURN fields;
END $_$;

--
-- Name: dsn_sending_mailbox_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_sending_mailbox_v1(c uuid, env text, smtp_from text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b public.ediel_mailboxes%rowtype;chosen uuid;n integer:=0;
BEGIN
 FOR b IN SELECT * FROM public.ediel_mailboxes WHERE is_active AND environment=env
  AND lower(email_address)=lower(dsn_sending_mailbox_v1.smtp_from) AND (company_id=c OR company_id IS NULL AND is_shared_platform_mailbox) ORDER BY id FOR SHARE LOOP
  chosen:=b.id;n:=n+1;
 END LOOP;
 RETURN CASE WHEN n=1 THEN chosen ELSE NULL END;
END $$;

--
-- Name: dsn_source_identity_matches_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_source_identity_matches_v1(raw text, report jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE pending jsonb:=jsonb_build_array(jsonb_build_object('raw',raw,'depth',0,'parent',NULL));next jsonb;
 statuses jsonb:='[]';returned jsonb:='[]';entity jsonb;fields jsonb;message_fields jsonb;recipient_fields jsonb;
 source text;body text;content_type text;media_type text;encoding text;boundary text;line text;marker text;
 parts text[];closed boolean;separator integer;n integer:=0;depth integer;blocks text[];
 original_ids jsonb:='[]';original_id text;diagnostic jsonb;recipient jsonb;derived jsonb;
BEGIN
 IF raw IS NULL OR octet_length(raw)>26214400 THEN RETURN false;END IF;
 WHILE jsonb_array_length(pending)>0 LOOP
  next:=pending->0;pending:=pending-0;depth:=(next->>'depth')::integer;
  source:=replace(next->>'raw',E'\r\n',E'\n');separator:=strpos(source,E'\n\n');
  IF depth>16 OR n>=256 OR octet_length(source)>26214400 THEN RETURN false;END IF;
  IF separator=0 THEN CONTINUE;END IF;
  IF separator>65536 THEN RETURN false;END IF;
  fields:=gridex_ediel_transport.dsn_fields_v1(left(source,separator-1));
  content_type:=coalesce(gridex_ediel_transport.dsn_field_v1(fields,'content-type'),'text/plain');
  media_type:=lower(btrim(split_part(content_type,';',1)));
  encoding:=lower(coalesce(gridex_ediel_transport.dsn_field_v1(fields,'content-transfer-encoding'),'7bit'));
  body:=replace(gridex_ediel_transport.dsn_decode_body_v1(substr(source,separator+2),encoding),E'\r\n',E'\n');n:=n+1;
  IF octet_length(body)>26214400 THEN RETURN false;END IF;
  entity:=jsonb_build_object('parent',next->'parent','body',body);
  IF media_type IN('message/delivery-status','message/global-delivery-status') THEN statuses:=statuses||entity;END IF;
  IF media_type IN('message/rfc822','message/global','text/rfc822-headers','message/global-headers') THEN returned:=returned||entity;END IF;
  IF media_type IN('message/rfc822','message/global') THEN
   pending:=pending||jsonb_build_object('raw',body,'depth',depth+1,'parent',n);CONTINUE;
  END IF;
  IF media_type NOT LIKE 'multipart/%' THEN CONTINUE;END IF;
  boundary:=gridex_ediel_transport.dsn_boundary_v1(content_type);
  IF boundary IS NULL OR length(boundary)=0 OR length(boundary)>70 OR boundary~E'[\r\n]' THEN RETURN false;END IF;
  parts:=NULL;closed:=false;
  FOREACH line IN ARRAY string_to_array(body,E'\n') LOOP
   marker:=rtrim(line,E' \t');
   IF marker='--'||boundary OR marker='--'||boundary||'--' THEN
    IF parts IS NOT NULL THEN
     pending:=pending||jsonb_build_object('raw',array_to_string(parts,E'\n'),'depth',depth+1,'parent',n);
     IF jsonb_array_length(pending)+n>256 THEN RETURN false;END IF;
    END IF;
    IF marker='--'||boundary||'--' THEN closed:=true;EXIT;END IF;
    parts:=ARRAY[]::text[];
   ELSIF parts IS NOT NULL THEN parts:=array_append(parts,line);END IF;
  END LOOP;
  IF NOT closed THEN RETURN false;END IF;
 END LOOP;
 IF jsonb_array_length(statuses)<>1 THEN RETURN false;END IF;
 blocks:=regexp_split_to_array(btrim(statuses->0->>'body',E' \t\r\n'),E'\n[ \t]*\n');
 -- The protected record owner qualifies exactly one recipient/attempt.
 IF array_length(blocks,1)<>2 THEN RETURN false;END IF;
 message_fields:=gridex_ediel_transport.dsn_fields_v1(blocks[1]);
 recipient_fields:=gridex_ediel_transport.dsn_fields_v1(blocks[2]);
 diagnostic:=gridex_ediel_transport.dsn_typed_field_v1(gridex_ediel_transport.dsn_field_v1(recipient_fields,'diagnostic-code'));
 recipient:=jsonb_build_object(
  'finalRecipient',gridex_ediel_transport.dsn_typed_field_v1(gridex_ediel_transport.dsn_field_v1(recipient_fields,'final-recipient')),
  'originalRecipient',gridex_ediel_transport.dsn_typed_field_v1(gridex_ediel_transport.dsn_field_v1(recipient_fields,'original-recipient')),
  'action',gridex_ediel_transport.dsn_field_v1(recipient_fields,'action'),'status',gridex_ediel_transport.dsn_field_v1(recipient_fields,'status'),
  'diagnosticCode',CASE WHEN diagnostic IS NOT NULL THEN jsonb_build_object('type',diagnostic->>'type','text',diagnostic->>'address') END,
  'remoteMta',gridex_ediel_transport.dsn_typed_field_v1(gridex_ediel_transport.dsn_field_v1(recipient_fields,'remote-mta')),
  'lastAttemptDate',gridex_ediel_transport.dsn_field_v1(recipient_fields,'last-attempt-date'),
  'willRetryUntil',gridex_ediel_transport.dsn_field_v1(recipient_fields,'will-retry-until'));
 FOR entity IN SELECT value FROM jsonb_array_elements(returned) LOOP
  IF entity->'parent' IS DISTINCT FROM statuses->0->'parent' THEN CONTINUE;END IF;
  fields:=gridex_ediel_transport.dsn_fields_v1(split_part(entity->>'body',E'\n\n',1));
  original_id:=gridex_ediel_transport.dsn_field_v1(fields,'message-id');
  IF original_id IS NULL OR original_id!~'^<[^<>[:space:]]+@[^<>[:space:]]+>$' THEN RETURN false;END IF;
  original_ids:=original_ids||to_jsonb(original_id);
 END LOOP;
 IF jsonb_array_length(original_ids)<>1 THEN RETURN false;END IF;
 derived:=jsonb_build_object('version',1,'transportCorrelation','unverified',
  'reportingMta',gridex_ediel_transport.dsn_typed_field_v1(gridex_ediel_transport.dsn_field_v1(message_fields,'reporting-mta')),
  'originalEnvelopeId',gridex_ediel_transport.dsn_field_v1(message_fields,'original-envelope-id'),
  'originalMessageIds',original_ids,'recipients',jsonb_build_array(recipient),'issues','[]'::jsonb);
 RETURN derived->'reportingMta'<>'null'::jsonb AND derived=report;
EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire OR untranslatable_character OR data_exception OR raise_exception THEN RETURN false;
END $_$;

--
-- Name: dsn_typed_field_v1(text); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.dsn_typed_field_v1(value text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE pair text[];
BEGIN
 IF value IS NULL THEN RETURN NULL;END IF;
 pair:=regexp_match(value,'^([A-Za-z0-9-]+);[ \t]*(.+)$');
 IF pair IS NULL THEN RAISE EXCEPTION 'dsn_typed_field_invalid';END IF;
 RETURN jsonb_build_object('type',lower(pair[1]),'address',pair[2]);
END $_$;

--
-- Name: freeze_dsn_attachment_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.freeze_dsn_attachment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT FROM gridex_ediel_transport.dsn_observations o WHERE o.attachment_id=OLD.id)
  AND (TG_OP='DELETE' OR NEW.raw_text IS DISTINCT FROM OLD.raw_text OR NEW.inbound_email_message_id IS DISTINCT FROM OLD.inbound_email_message_id)
 THEN RAISE EXCEPTION 'ediel_dsn_observation_source_immutable';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

--
-- Name: freeze_dsn_mail_source_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.freeze_dsn_mail_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT FROM gridex_ediel_transport.dsn_observations o WHERE o.inbound_email_message_id=OLD.id
  AND (NEW.company_id IS DISTINCT FROM OLD.company_id
   OR to_jsonb(NEW)->>'ediel_mailbox_id' IS DISTINCT FROM to_jsonb(OLD)->>'ediel_mailbox_id'
   OR to_jsonb(NEW)->>'mailbox_id' IS DISTINCT FROM to_jsonb(OLD)->>'mailbox_id'
   OR to_jsonb(NEW)->>'environment' IS DISTINCT FROM to_jsonb(OLD)->>'environment'
   OR o.source_field='raw_email' AND to_jsonb(NEW)->>'raw_email' IS DISTINCT FROM to_jsonb(OLD)->>'raw_email'
   OR o.source_field='body_text' AND to_jsonb(NEW)->>'body_text' IS DISTINCT FROM to_jsonb(OLD)->>'body_text')) THEN RAISE EXCEPTION 'ediel_dsn_observation_source_immutable';END IF;
 RETURN NEW;
END $$;

--
-- Name: mutate_before_bilateral_prodat_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_bilateral_prodat_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;contract uuid;BEGIN
 result:=gridex_ediel_transport.mutate_before_customer_records_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND result->>'proceed'='true' THEN
  PERFORM public.ediel_require_message_consumed_records_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid);
  SELECT coalesce(s.customer_contract_id,s.contract_id) INTO contract FROM public.supplier_switch_requests s JOIN public.ediel_messages m ON m.id=(p_input->>'messageId')::uuid AND m.company_id=s.company_id WHERE s.company_id=(p_input->>'companyId')::uuid AND s.outbound_z03_message_id=m.id;IF contract IS NOT NULL THEN PERFORM public.ediel_require_contract_records_available_v1((p_input->>'companyId')::uuid,contract);END IF;
 END IF;RETURN result;
END$$;

--
-- Name: mutate_before_blob_retention_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_blob_retention_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN r:=gridex_ediel_transport.mutate_before_temporary_exception_v1(i);PERFORM gridex_transport_exception.stage_v1(i,r);RETURN r;END$$;

--
-- Name: mutate_before_customer_event_recovery_cohort_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_customer_event_recovery_cohort_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;m public.ediel_messages%rowtype;BEGIN
 result:=gridex_ediel_transport.mutate_before_unused_unh_v1(i);
 IF(i->>'action' IN('prepare','enter')) IS TRUE AND result->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
  PERFORM gridex_ediel_ack_guide.require_unused_unh_current_message_v1(m);END IF;RETURN result;END $$;

--
-- Name: mutate_before_customer_life_event_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_customer_life_event_source_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;a gridex_ediel_transport.attempts%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_technical_expectation_v1(p_input);
 IF p_input->>'action' NOT IN('prepare','enter') OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid
  AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR UPDATE;
 SELECT * INTO STRICT a FROM gridex_ediel_transport.attempts WHERE id=(p_input->>'attemptId')::uuid
  AND message_id=m.id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
 PERFORM gridex_ediel_transport.require_technical_expectation_binding_v1(m,a.binding);
 PERFORM public.require_metering_method_expectation_binding_v1(m,a.binding);
 IF m.message_standard='edifact' AND m.message_family='PRODAT' AND m.message_code='Z09' THEN
  PERFORM public.ediel_require_metering_method_change_source_current_v1(m.company_id,m.id,(p_input->>'actorUserId')::uuid);
 END IF;
 RETURN result;
END $$;

--
-- Name: mutate_before_customer_masterdata_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_customer_masterdata_source_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;m public.ediel_messages%rowtype;
BEGIN
 IF p_input->>'action' IN('prepare','enter') THEN PERFORM gridex_bilateral_prodat.lock_outbound_v1();END IF;
 r:=gridex_ediel_transport.mutate_before_bilateral_prodat_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid FOR SHARE;PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);PERFORM public.ediel_require_current_prodat_bilateral_ack_source_v1(m.company_id,m.id);END IF;RETURN r;
END$$;

--
-- Name: mutate_before_customer_records_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_customer_records_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
 result:=gridex_ediel_transport.mutate_before_switch_production_brp_source_v1(input);
 IF (input->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM gridex_received_sources.require_switch_brp_source_current_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid,(input->>'actorUserId')::uuid);
 RETURN result;
END$$;

--
-- Name: mutate_before_duplicate_protocol_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_duplicate_protocol_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;m public.ediel_messages%rowtype;BEGIN
 IF p_input->>'action' IN('prepare','enter') THEN PERFORM gridex_supply_rescission.lock_original_v1();END IF;r:=gridex_ediel_transport.mutate_before_national_rescission_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid FOR SHARE;
  IF gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS TRUE THEN
   IF gridex_supply_rescission.sender_v1(m.company_id,(p_input->>'actorUserId')::uuid) IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_transport_executor_forbidden' USING ERRCODE='42501';END IF;
   PERFORM gridex_supply_rescission.require_original_v1(m,false);
   IF gridex_supply_rescission.sender_v1(m.company_id,(p_input->>'actorUserId')::uuid) IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_transport_executor_forbidden' USING ERRCODE='42501';END IF;
  END IF;END IF;RETURN r;
END$$;

--
-- Name: mutate_before_mandatory_intent_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_mandatory_intent_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_positive_storage_v1(i);
 IF i->>'action' NOT IN('prepare','enter') OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(m,true);RETURN result;
END $$;

--
-- Name: mutate_before_national_rescission_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_national_rescission_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(i->>'companyId')::uuid;mid uuid:=(i->>'messageId')::uuid;env text:=i->>'environment';action text:=i->>'action';op_id uuid;
 m public.ediel_messages%rowtype;r gridex_ediel_transport.reservations%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 IF(action IN('prepare','enter')) IS NOT TRUE THEN RETURN gridex_ediel_transport.mutate_before_recovery_execution_phase_v1(i);END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=env AND direction='outbound';
 IF m.id IS NULL THEN RETURN gridex_ediel_transport.mutate_before_recovery_execution_phase_v1(i);END IF;
 SELECT * INTO r FROM gridex_ediel_transport.reservations WHERE message_id=m.id;
 IF(action='prepare' AND r.message_id IS NOT NULL AND r.state IS DISTINCT FROM 'released')
  OR(action='enter' AND r.message_id IS NOT NULL AND r.state IS DISTINCT FROM 'prepared')
  OR gridex_ediel_transport.accepted_source_basis_v1(m) IS NOT NULL THEN RETURN gridex_ediel_transport.mutate_before_recovery_execution_phase_v1(i);END IF;
 -- This is the SAME existing retry/ACK universe lock, moved before source rows
 -- for fresh entry so no later table-lock upgrade can invert the cohort order.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT operation.id INTO op_id FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=mid AND operation.company_id=c;
 IF op_id IS NOT NULL THEN PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(c,op_id,mid);END IF;
 RETURN gridex_ediel_transport.mutate_before_recovery_execution_phase_v1(i);
END$$;

--
-- Name: mutate_before_native_ack_guide_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_native_ack_guide_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_mandatory_intent_v1(i);
 IF (i->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
 PERFORM public.ediel_require_brp_change_source_current_v1(m.company_id,m.id);
 RETURN result;
END $$;

--
-- Name: mutate_before_original_basis_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_original_basis_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(p_input->>'companyId')::uuid;mid uuid:=(p_input->>'messageId')::uuid;
 actor uuid:=(p_input->>'actorUserId')::uuid;aid uuid:=(p_input->>'attemptId')::uuid;
 m public.ediel_messages%rowtype;r gridex_ediel_transport.reservations%rowtype;a gridex_ediel_transport.attempts%rowtype;
 retry jsonb:=p_input#>'{binding,recoveryAuthorization}';basis jsonb;result jsonb;prior jsonb;
BEGIN
 IF p_input->>'action'='prepare' THEN
  -- Freeze the genuine candidate universe before rows, in the same lock order
  -- as qualified inbound ACK effects. This lock is not activation evidence.
  LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=p_input->>'environment' FOR UPDATE;
  PERFORM 1 FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
  PERFORM 1 FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
  IF actor IS NULL OR aid IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.immutable_rendered_at IS NULL
   OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
   OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
   OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
   OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false))
  THEN RAISE EXCEPTION 'ediel_transport_replay_scope_invalid' USING ERRCODE='42501';END IF;
  SELECT * INTO r FROM gridex_ediel_transport.reservations WHERE message_id=mid FOR UPDATE;
  IF FOUND AND r.state<>'released' THEN
   SELECT * INTO STRICT a FROM gridex_ediel_transport.attempts WHERE id=r.attempt_id AND message_id=mid AND company_id=c AND environment=m.environment FOR SHARE;
   IF a.binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'ediel_transport_original_changed';END IF;
   IF retry IS NULL OR retry='null'::jsonb OR r.state<>'observed' OR a.classification NOT IN('pre_connect_negative','explicit_negative','all_rejected') THEN
    -- Prior accepted/uncertain/scoped outcomes are historical observations. A
    -- later permission, route or rule change cannot authorize another entry.
    RETURN jsonb_build_object('proceed',false,'state',r.state,'classification',a.classification,
      'providerReceipt',CASE WHEN a.classification='accepted' THEN a.provider_result ELSE NULL END,'observedAt',a.observed_at);
   END IF;
   IF p_input#>>'{owner,kind}' IS DISTINCT FROM 'worker' OR jsonb_typeof(retry) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_transport_retry_private_outbox_required';END IF;
   basis:=public.ediel_prodat_retry_outbox_basis_v1(c,(p_input#>>'{owner,outboxId}')::uuid,actor);
   IF basis IS NULL OR basis IS DISTINCT FROM retry OR basis->>'messageId' IS DISTINCT FROM mid::text
    OR basis->>'previousAttemptId' IS DISTINCT FROM r.attempt_id::text THEN RAISE EXCEPTION 'ediel_transport_retry_binding_invalid';END IF;
   PERFORM 1 FROM public.ediel_outbox o WHERE o.id=(basis->>'outboxId')::uuid AND o.company_id=c AND o.ediel_message_id=mid AND o.environment=m.environment
    AND o.status='sending' AND o.current_send_attempt_id=(p_input#>>'{owner,sendAttemptId}')::uuid AND o.locked_by=p_input#>>'{owner,workerId}' FOR UPDATE;
   IF FOUND AND NOT EXISTS(SELECT FROM public.ediel_outbox lease WHERE lease.id=(p_input#>>'{owner,outboxId}')::uuid AND lease.company_id=c AND lease.ediel_message_id=mid AND lease.environment=m.environment AND lease.locked_at IS NOT NULL AND lease.locked_at<=clock_timestamp() AND lease.locked_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'ediel_transport_worker_fence_lost';END IF;
   IF NOT FOUND THEN RAISE EXCEPTION 'ediel_transport_worker_fence_lost';END IF;
   IF NOT public.ediel_consume_prodat_retry_authorization_v1(c,mid,r.attempt_id,aid,actor,(basis->>'operationId')::uuid) THEN RAISE EXCEPTION 'ediel_transport_retry_authorization_denied';END IF;
   prior:=to_jsonb(a);
   -- Only the mutable cursor is advanced in this transaction. Any current
   -- source/readiness/archive/worker failure rolls this and consumption back.
   UPDATE gridex_ediel_transport.reservations SET state='released' WHERE message_id=mid AND attempt_id=r.attempt_id AND state='observed';
   result:=gridex_ediel_transport.mutate_before_source_retry_v1(p_input);
   IF result->>'proceed' IS DISTINCT FROM 'true' OR NOT EXISTS(SELECT FROM gridex_ediel_transport.reservations x WHERE x.message_id=mid AND x.attempt_id=aid AND x.state='prepared')
    OR (SELECT to_jsonb(old) FROM gridex_ediel_transport.attempts old WHERE old.id=r.attempt_id) IS DISTINCT FROM prior THEN RAISE EXCEPTION 'ediel_transport_retry_cursor_contract_failed';END IF;
   RETURN result;
  ELSIF retry IS NOT NULL AND retry<>'null'::jsonb THEN
   RAISE EXCEPTION 'ediel_transport_retry_observed_original_required';
  END IF;
 END IF;
 IF p_input->>'action' IN('prepare','enter') THEN
  PERFORM public.ediel_require_prodat_recovery_current_v1(c,mid);
 END IF;
 RETURN gridex_ediel_transport.mutate_before_source_retry_v1(p_input);
END $$;

--
-- Name: mutate_before_positive_storage_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_positive_storage_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;evidence jsonb;attempt gridex_ediel_transport.attempts%rowtype;r gridex_ediel_transport.reservations%rowtype;actor uuid:=(p_input->>'actorUserId')::uuid;
BEGIN
 IF p_input->>'action'='enter' THEN
  SELECT * INTO m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR UPDATE;
  SELECT * INTO r FROM gridex_ediel_transport.reservations WHERE message_id=m.id FOR UPDATE;
  IF r.state IN('entered','observed') THEN
   SELECT * INTO attempt FROM gridex_ediel_transport.attempts WHERE id=r.attempt_id AND id=(p_input->>'attemptId')::uuid AND message_id=m.id AND company_id=m.company_id AND environment=m.environment AND actor_user_id=actor FOR SHARE;
   PERFORM 1 FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
   PERFORM 1 FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=actor FOR SHARE;
   IF attempt.id IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR attempt.binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash
    OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
    OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,m.company_id,'communication.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,m.company_id,'ediel.send'),false)) THEN RAISE EXCEPTION 'ediel_transport_replay_scope_invalid';END IF;
   RETURN jsonb_build_object('proceed',false,'state',r.state);
  END IF;
 END IF;
 result:=gridex_ediel_transport.mutate_before_original_basis_v1(p_input);
 IF p_input->>'action' NOT IN('prepare','enter') OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR UPDATE;
 IF m.message_family NOT IN('PRODAT','UTILTS','APERAK','UTILTS_ERR','CONTRL') THEN RETURN result;END IF;
 IF m.message_family='CONTRL' THEN
  evidence:=gridex_ediel_technical_ack.require_contrl_v1(m);
  IF p_input->>'action'='prepare' AND p_input#>'{binding,technicalSyntaxAckEvidence}' IS DISTINCT FROM evidence THEN RAISE EXCEPTION 'ediel_technical_ack_basis_required';END IF;
 ELSIF m.message_family='APERAK' AND m.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId' THEN
  evidence:=gridex_ediel_common_header.require_ack_v1(m);PERFORM gridex_ediel_ack_guide.require_v1(m);
  IF p_input->>'action'='prepare' AND p_input#>'{binding,prodatCommonHeaderRejectionEvidence}' IS DISTINCT FROM evidence THEN RAISE EXCEPTION 'ediel_common_header_negative_witness_required';END IF;
 ELSE
  evidence:=gridex_ediel_source_rules.capture_v1(m.company_id,m.id);
  IF p_input->>'action'='prepare' AND p_input#>'{binding,sourceRulePackEvidence}' IS DISTINCT FROM evidence THEN RAISE EXCEPTION 'ediel_source_rule_pack_basis_required';END IF;
 END IF;
 SELECT * INTO STRICT attempt FROM gridex_ediel_transport.attempts WHERE id=(p_input->>'attemptId')::uuid AND message_id=m.id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
 IF m.message_family='CONTRL' AND attempt.binding->'technicalSyntaxAckEvidence' IS DISTINCT FROM evidence OR m.message_family='APERAK' AND m.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId' AND attempt.binding->'prodatCommonHeaderRejectionEvidence' IS DISTINCT FROM evidence OR m.message_family<>'CONTRL' AND NOT(m.message_family='APERAK' AND m.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId') AND attempt.binding->'sourceRulePackEvidence' IS DISTINCT FROM evidence THEN RAISE EXCEPTION 'ediel_transport_original_basis_binding_required';END IF;
 RETURN result;
END $$;

--
-- Name: mutate_before_prodat_unused_document_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_prodat_unused_document_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
 result:=gridex_ediel_transport.mutate_before_registry_markets_v1(input);
 IF(input->>'action' IN('prepare','enter')) IS TRUE AND result->>'proceed'='true' THEN PERFORM gridex_registry_import.require_message_market_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid);END IF;
 RETURN result;
END$$;

--
-- Name: mutate_before_production_contract_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_production_contract_source_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r jsonb;
BEGIN r:=gridex_ediel_transport.mutate_before_switch_cancellation_v1(i);
 IF (i->>'action' IN('prepare','enter')) IS TRUE AND r->>'proceed'='true' THEN
  PERFORM public.ediel_require_switch_cancellation_source_current_v1((i->>'companyId')::uuid,(i->>'messageId')::uuid);END IF;
 RETURN r;END $$;

--
-- Name: mutate_before_recovery_execution_phase_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_recovery_execution_phase_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(i->>'companyId')::uuid;mid uuid:=(i->>'messageId')::uuid;env text:=i->>'environment';action text:=i->>'action';
 m public.ediel_messages%rowtype;r gridex_ediel_transport.reservations%rowtype;
BEGIN
 IF(action IN('prepare','enter')) IS NOT TRUE THEN RETURN gridex_ediel_transport.mutate_before_customer_event_recovery_cohort_v1(i);END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=env AND direction='outbound';
 IF m.id IS NULL THEN RETURN gridex_ediel_transport.mutate_before_customer_event_recovery_cohort_v1(i);END IF;
 SELECT * INTO r FROM gridex_ediel_transport.reservations WHERE message_id=m.id;
 IF(action='prepare' AND r.message_id IS NOT NULL AND r.state IS DISTINCT FROM 'released')
  OR(action='enter' AND r.message_id IS NOT NULL AND r.state IS DISTINCT FROM 'prepared')
  OR gridex_ediel_transport.accepted_source_basis_v1(m) IS NOT NULL THEN
  -- The real delegate retains current execution actor and exact frozen attempt
  -- checks. This branch introduces no new provider or source authorization.
  RETURN gridex_ediel_transport.mutate_before_customer_event_recovery_cohort_v1(i);
 END IF;
 PERFORM gridex_customer_life_events.prelock_recovery_lineage_v1(c,mid);
 RETURN gridex_ediel_transport.mutate_before_customer_event_recovery_cohort_v1(i);
END$$;

--
-- Name: mutate_before_reference_profile_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_reference_profile_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_prodat_unused_document_v1(p_input);
 IF (p_input->>'action' IN('prepare','enter')) IS TRUE AND result->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid
   AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR SHARE;
  PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(m.raw_payload);
 END IF;
 RETURN result;
END$$;

--
-- Name: mutate_before_registry_markets_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_registry_markets_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;m public.ediel_messages%rowtype;o gridex_requested_changes.origins%rowtype;a gridex_ediel_transport.attempts%rowtype;b jsonb;h text;e gridex_requested_method_watches.entry_sources%rowtype;
BEGIN
 IF i->>'action' IN('prepare','enter') THEN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();END IF;
 r:=gridex_ediel_transport.mutate_before_requested_method_entry_v1(i);
 IF i->>'action' IS DISTINCT FROM 'enter' OR r->>'proceed' IS DISTINCT FROM 'true' THEN RETURN r;END IF;
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE company_id=(i->>'companyId')::uuid AND message_id=(i->>'messageId')::uuid FOR SHARE;
 IF NOT FOUND OR (o.basis->>'variant' IN('F','G')) IS NOT TRUE THEN RETURN r;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=o.company_id AND id=o.message_id AND environment=i->>'environment' FOR SHARE;
 SELECT * INTO STRICT a FROM gridex_ediel_transport.attempts WHERE id=(i->>'attemptId')::uuid AND company_id=o.company_id AND environment=m.environment AND message_id=m.id FOR SHARE;
 b:=gridex_requested_changes.require_message_v1(m,a.actor_user_id,'communication.send');
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 PERFORM gridex_method_expectations.require_binding_v1(m,a.binding);
 h:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 IF b IS DISTINCT FROM o.basis OR a.entered_at IS NULL OR a.binding->>'originalHash' IS DISTINCT FROM h
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM h OR o.payload_hash IS DISTINCT FROM h THEN RAISE EXCEPTION 'ediel_method_expectation_current_entry_source_required';END IF;
 INSERT INTO gridex_requested_method_watches.entry_sources(attempt_id,company_id,environment,message_id,event_id,intent_id,source_payload_hash,basis,basis_hash,entry_binding_hash,message_scope,entered_at)
 VALUES(a.id,m.company_id,m.environment,m.id,o.event_id,o.intent_id,h,b,encode(sha256(convert_to(b::text,'UTF8')),'hex'),encode(sha256(convert_to(a.binding::text,'UTF8')),'hex'),gridex_requested_method_watches.message_scope_v1(m),a.entered_at);
 RETURN r;
END $$;

--
-- Name: mutate_before_requested_change_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_requested_change_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=gridex_ediel_transport.mutate_before_production_contract_source_v1(input);
 IF (input->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM gridex_received_sources.require_production_contract_source_current_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid,(input->>'actorUserId')::uuid);
 RETURN result;
END $$;

--
-- Name: mutate_before_requested_method_entry_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_requested_method_entry_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
 c uuid:=(p_input->>'companyId')::uuid;mid uuid:=(p_input->>'messageId')::uuid;
 env text:=p_input->>'environment';action text:=p_input->>'action';
 m public.ediel_messages%rowtype;r gridex_ediel_transport.reservations%rowtype;
BEGIN
 IF (action IN('prepare','enter')) IS NOT TRUE THEN
  RETURN gridex_ediel_transport.mutate_before_customer_masterdata_source_v1(p_input);
 END IF;
 -- Immutable origin supplies the source IDs. This is only lock ordering and
 -- qualifies no actor, rule, address, or customer from a caller selector.
 PERFORM gridex_customer_masterdata.prelock_message_v1(c,mid);
 SELECT * INTO m FROM public.ediel_messages
  WHERE id=mid AND company_id=c AND environment=env AND direction='outbound' FOR UPDATE;
 IF m.id IS NULL THEN RETURN gridex_ediel_transport.mutate_before_customer_masterdata_source_v1(p_input);END IF;
 SELECT * INTO r FROM gridex_ediel_transport.reservations WHERE message_id=m.id FOR UPDATE;
 IF action='prepare' AND r.message_id IS NOT NULL AND r.state<>'released'
  OR action='enter' AND r.state IN('entered','observed') THEN
  -- The delegate retains its current actor/read and exact attempt checks.
  RETURN gridex_ediel_transport.mutate_before_customer_masterdata_source_v1(p_input);
 END IF;
 PERFORM gridex_customer_masterdata.require_current_v1(c,mid,(p_input->>'actorUserId')::uuid,'send');
 RETURN gridex_ediel_transport.mutate_before_customer_masterdata_source_v1(p_input);
END$$;

--
-- Name: mutate_before_service_origin_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_service_origin_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
 c uuid:=(p_input->>'companyId')::uuid; env text:=p_input->>'environment'; mid uuid:=(p_input->>'messageId')::uuid;
 actor uuid:=(p_input->>'actorUserId')::uuid; aid uuid:=(p_input->>'attemptId')::uuid; action text:=p_input->>'action';
 owner jsonb:=p_input->'owner'; binding jsonb:=p_input->'binding'; result jsonb:=p_input->'result';
 m public.ediel_messages%rowtype; a gridex_ediel_transport.attempts%rowtype; r gridex_ediel_transport.reservations%rowtype; v_classification text; lane jsonb; ai_basis jsonb; is_ai boolean; technical_basis jsonb; technical_evidence jsonb; technical_candidate boolean:=false;
begin
 if c is null or actor is null or mid is null or aid is null or env is null or env not in ('test','production') or action is null or action not in ('prepare','enter','observe','release') then raise exception 'ediel_transport_scope_required'; end if;
 -- Routing is only a candidate selector. Authority comes from the existing
 -- actor-qualified private original port, with graph-first locks before rows.
 if env='production' and exists(select 1 from public.ediel_messages candidate
   where candidate.id=mid and candidate.company_id=c and candidate.environment=env
     and candidate.direction='outbound' and candidate.message_standard='edifact' and candidate.message_family='CONTRL') then
  technical_candidate:=true;
  technical_basis:=gridex_ediel_technical_ack.read_persisted_contrl_v2(c,env,mid,actor,'send');
 end if;
 perform 1 from public.user_profiles x where x.id=actor for share;
 perform 1 from public.company_memberships x where x.company_id=c and x.user_id=actor for share;
 -- A global administrator alone is not a tenant service context.
 if not exists(select 1 from public.company_memberships x where x.company_id=c and x.user_id=actor and x.status='active' and x.is_active and x.accepted_at is not null)
 or not exists(select 1 from public.user_profiles x where x.id=actor and x.user_status='active')
 or not (coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false)
   or coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false))
 then raise exception 'ediel_transport_actor_not_authorized' using errcode='42501'; end if;
 select * into strict m from public.ediel_messages where id=mid and company_id=c and environment=env for update;
 is_ai:=m.message_standard='ai_list' and m.message_family='AI_LIST' and m.message_code='AI';
 if m.direction is distinct from 'outbound' or not(m.message_standard='edifact' or coalesce(is_ai,false)) or m.raw_payload is null or m.immutable_rendered_at is null or m.immutable_payload_hash is distinct from encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 then raise exception 'ediel_transport_sealed_message_required'; end if;
 -- The private reader projects exactly two non-authoritative public caches.
 -- Bind those projections to its protected source/syntax, preserve stored rows,
 -- and compare every other field to the current locked sealed message.
 if technical_candidate then
  technical_evidence:=technical_basis->'technicalSyntaxAckEvidence';
  if jsonb_typeof(technical_basis) is distinct from 'object' or env is distinct from 'production' or m.message_family is distinct from 'CONTRL'
   or technical_basis->'version' is distinct from '2'::jsonb
   or technical_basis->>'executionActorUserId' is distinct from actor::text
   or technical_basis->>'executionPhase' is distinct from 'send'
   or jsonb_typeof(technical_basis->'ackMessage') is distinct from 'object'
   or jsonb_typeof(technical_evidence) is distinct from 'object'
   or technical_evidence->>'kind' is distinct from 'technical_syntax_ack'
   or technical_evidence->'version' is distinct from '1'::jsonb
   or technical_evidence->>'companyId' is distinct from c::text
   or technical_evidence->>'environment' is distinct from env
   or nullif(technical_evidence->>'sourceMessageId','') is null
   or technical_basis#>>'{ackMessage,related_message_id}' is distinct from technical_evidence->>'sourceMessageId'
   or technical_evidence->>'syntaxDecision' is null or technical_evidence->>'syntaxDecision' not in ('accepted','rejected')
   or technical_basis#>>'{ackMessage,ack_outcome}' is distinct from (case technical_evidence->>'syntaxDecision' when 'accepted' then 'positive' when 'rejected' then 'negative' end)
   or (technical_basis->'ackMessage')-array['related_message_id','ack_outcome'] is distinct from to_jsonb(m)-array['related_message_id','ack_outcome']
  then raise exception 'ediel_transport_technical_contrl_basis_mismatch' using errcode='42501'; end if;
 end if;
 if not technical_candidate and not exists(select 1 from public.canonical_tenant_operation_decision(c,case when env='production' then 'ediel.production.send' else 'ediel.test.process' end) d where d.allowed)
 then raise exception 'ediel_transport_actor_not_authorized' using errcode='42501'; end if;
 if action in ('prepare','enter') then
  if is_ai then ai_basis:=gridex_ai_processing.require_ai_outbound_source_v1(c,mid,actor); end if;
  perform public.ediel_require_scoped_capability_for_message_v1(c,mid);
 end if;
 if action='prepare' then
  -- Persist the actual configured send mailbox, never caller/returned headers.
  binding:=binding||jsonb_build_object('sourceMailboxId',gridex_ediel_transport.dsn_sending_mailbox_v1(c,env,binding->>'from'));
  -- Ask the existing source owner with an intentionally non-sendable probe.
  -- H, malformed/inconsistent Z08 and existing closure originals remain in that lane.
  -- The invalid owner cannot reach any write if the old authority returns scoped.
  if not is_ai then
  lane:=gridex_outbound_dispatch.mutate_v1(jsonb_build_object('companyId',c,'environment',env,'messageId',mid,'actorUserId',actor,'attemptId',aid,'action','prepare','owner',jsonb_build_object('kind','transport_scope_probe')));
  if (lane->>'scoped')::boolean is distinct from false then raise exception 'ediel_transport_special_source_authority_required'; end if;
  end if;
  if jsonb_typeof(owner) is distinct from 'object' or owner->>'kind' is null or owner->>'kind' not in ('direct','worker') or jsonb_typeof(binding) is distinct from 'object'
  or binding->>'originalHash' is distinct from m.immutable_payload_hash or binding->>'routeId' is distinct from m.communication_route_id::text or binding->>'to' is distinct from m.receiver_email
  or nullif(binding->>'from','') is null or coalesce(binding->>'payloadHash','') !~ '^[a-f0-9]{64}$' or coalesce(binding->>'mimeSha256','') !~ '^[a-f0-9]{64}$'
  or nullif(binding->>'rfcMessageId','') is null or nullif(binding->>'mimeArchiveRef','') is null or (binding->>'mimeLength')::bigint is null or (binding->>'mimeLength')::bigint<=0
  or (binding->>'payloadLength')::bigint is null or (binding->>'payloadLength')::bigint<=0 or (binding->>'payloadLength')::bigint>(case when is_ai then 10485760 else 262144 end)
  or nullif(binding->>'mimeMode','') is null or nullif(binding->>'encoding','') is null then raise exception 'ediel_transport_binding_invalid'; end if;
  if is_ai and (binding->>'payloadHash' is distinct from ai_basis->>'sourceHash'
   or (binding->>'payloadLength')::bigint is distinct from octet_length(convert_to(m.raw_payload,'UTF8'))::bigint
   or binding->>'encoding' is distinct from 'utf8') then raise exception 'ediel_ai_transport_source_bytes_required'; end if;
  if not is_ai and (binding->>'payloadHash' is distinct from encode(sha256(convert_to(m.raw_payload,'LATIN1')),'hex')
   or (binding->>'payloadLength')::bigint is distinct from octet_length(convert_to(m.raw_payload,'LATIN1'))::bigint
   or binding->>'encoding' is distinct from 'latin1') then raise exception 'ediel_transport_original_bytes_required'; end if;
  -- The archive writer must have committed and read back the same exact MIME bytes before provider entry.
  if not exists(select 1 from public.ediel_message_payloads x where x.company_id=c and x.ediel_message_id=mid and x.encrypted_payload_ref=binding->>'mimeArchiveRef'
    and x.payload_kind in ('raw_mime','smime_enveloped') and x.metadata->>'archive_verified'='true' and x.metadata->>'archived_mime_sha256'=binding->>'mimeSha256'
    and x.metadata->>'archived_rfc_message_id'=binding->>'rfcMessageId' and (x.metadata->>'archived_mime_bytes')::bigint=(binding->>'mimeLength')::bigint) then raise exception 'ediel_transport_archive_not_qualified'; end if;
  select * into r from gridex_ediel_transport.reservations where message_id=mid for update;
  if found and r.state<>'released' then
   select * into strict a from gridex_ediel_transport.attempts where id=r.attempt_id;
   if a.company_id<>c or a.environment<>env or a.binding->>'originalHash' is distinct from m.immutable_payload_hash then raise exception 'ediel_transport_original_changed'; end if;
   return jsonb_build_object('proceed',false,'state',r.state,'classification',a.classification,'providerReceipt',case when a.classification='accepted' then a.provider_result else null end,'observedAt',a.observed_at);
  end if;
  if owner->>'kind'='worker' then
   perform 1 from public.ediel_outbox o where o.id=(owner->>'outboxId')::uuid and o.ediel_message_id=mid and o.company_id=c and o.environment=env and o.status='sending' and o.current_send_attempt_id=(owner->>'sendAttemptId')::uuid and o.locked_by=owner->>'workerId' for update;
   IF FOUND AND NOT EXISTS(SELECT FROM public.ediel_outbox lease WHERE lease.id=(owner->>'outboxId')::uuid AND lease.company_id=c AND lease.ediel_message_id=mid AND lease.environment=env AND lease.locked_at IS NOT NULL AND lease.locked_at<=clock_timestamp() AND lease.locked_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'ediel_transport_worker_fence_lost';END IF;
   if not found then raise exception 'ediel_transport_worker_fence_lost'; end if;
  elsif owner is distinct from '{"kind":"direct"}'::jsonb then raise exception 'ediel_transport_direct_owner_invalid'; end if;
  insert into gridex_ediel_transport.attempts(id,message_id,company_id,environment,actor_user_id,owner,binding) values(aid,mid,c,env,actor,owner,binding);
  insert into gridex_ediel_transport.reservations(message_id,attempt_id,state) values(mid,aid,'prepared') on conflict(message_id) do update set attempt_id=excluded.attempt_id,state='prepared';
  return jsonb_build_object('proceed',true,'state','prepared');
 end if;
 select * into strict r from gridex_ediel_transport.reservations where message_id=mid for update;
 if r.attempt_id is distinct from aid then raise exception 'ediel_transport_stale_attempt'; end if;
 select * into strict a from gridex_ediel_transport.attempts where id=aid and message_id=mid and company_id=c and environment=env and actor_user_id=actor for update;
 if action='enter' then
  if r.state<>'prepared' then return jsonb_build_object('proceed',false,'state',r.state); end if;
  if is_ai and (a.binding->>'payloadHash' is distinct from ai_basis->>'sourceHash' or a.binding->>'encoding' is distinct from 'utf8') then raise exception 'ediel_ai_transport_source_bytes_required'; end if;
  if a.owner->>'kind'='worker' then
   perform 1 from public.ediel_outbox o where o.id=(a.owner->>'outboxId')::uuid and o.ediel_message_id=mid and o.company_id=c and o.environment=env and o.status='sending' and o.current_send_attempt_id=(a.owner->>'sendAttemptId')::uuid and o.locked_by=a.owner->>'workerId' for update;
   IF FOUND AND NOT EXISTS(SELECT FROM public.ediel_outbox lease WHERE lease.id=(a.owner->>'outboxId')::uuid AND lease.company_id=c AND lease.ediel_message_id=mid AND lease.environment=env AND lease.locked_at IS NOT NULL AND lease.locked_at<=clock_timestamp() AND lease.locked_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'ediel_transport_worker_fence_lost';END IF;
   if not found then raise exception 'ediel_transport_worker_fence_lost'; end if;
  end if;
  update gridex_ediel_transport.attempts set entered_at=now() where id=aid;
  update gridex_ediel_transport.reservations set state='entered' where message_id=mid;
  return jsonb_build_object('proceed',true,'state','entered');
 elsif action='release' then
  if r.state<>'prepared' or a.entered_at is not null then raise exception 'ediel_transport_release_unsafe'; end if;
  update gridex_ediel_transport.reservations set state='released' where message_id=mid;
  return jsonb_build_object('proceed',true,'state','released');
 end if;
 if jsonb_typeof(result) is distinct from 'object' or octet_length(result::text)>262144 or r.state not in ('entered','observed') then raise exception 'ediel_transport_result_invalid'; end if;
 if r.state='observed' then
  if result is distinct from a.provider_result then raise exception 'ediel_transport_result_immutable'; end if;
  return jsonb_build_object('classification',a.classification,'state','observed','observedAt',a.observed_at);
 end if;
 v_classification:='unknown';
 if jsonb_typeof(result->'accepted')='array' and jsonb_typeof(result->'rejected')='array'
 and not exists(select 1 from jsonb_array_elements((result->'accepted')||(result->'rejected')) x where jsonb_typeof(x)<>'string' or nullif(btrim(x#>>'{}'),'') is null)
 and not exists(select 1 from jsonb_array_elements_text((result->'accepted')||(result->'rejected')) x where lower(x) is distinct from lower(a.binding->>'to')) then
  if jsonb_array_length(result->'accepted')>0 and not exists(select 1 from jsonb_array_elements_text(result->'accepted') accepted where lower(accepted)<>lower(a.binding->>'to')) then
   v_classification:=case when jsonb_array_length(result->'rejected')=0 then 'accepted' else 'partial' end;
  elsif jsonb_array_length(result->'accepted')=0 and jsonb_array_length(result->'rejected')>0 then v_classification:='all_rejected'; end if;
 elsif result#>>'{error,syscall}'='connect' then v_classification:='pre_connect_negative';
 elsif result#>>'{error,responseCode}' ~ '^[45][0-9][0-9]$' then v_classification:='explicit_negative'; end if;
 update gridex_ediel_transport.attempts set observed_at=now(),provider_result=result,classification=v_classification where id=aid;
 update gridex_ediel_transport.reservations set state='observed' where message_id=mid;
 return jsonb_build_object('classification',v_classification,'state','observed','observedAt',now());
end;
$_$;

--
-- Name: mutate_before_signed_switch_method_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_signed_switch_method_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
 result:=gridex_ediel_transport.mutate_before_customer_life_event_source_v1(input);
 IF (input->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM gridex_customer_life_events.require_current_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid,(input->>'actorUserId')::uuid,'send');RETURN result;END $$;

--
-- Name: mutate_before_source_retry_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_source_retry_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
 IF p_input->>'action' IN ('prepare','enter') THEN PERFORM public.ediel_require_service_permission_origin_current_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid); END IF;
 IF p_input->>'action' IN ('prepare','enter') THEN PERFORM public.ediel_reserve_wire_reference_namespace_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid); END IF;
 RETURN gridex_ediel_transport.mutate_before_service_origin_v1(p_input);
END $$;

--
-- Name: mutate_before_switch_cancellation_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_switch_cancellation_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_utilts_err_source_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND result->>'proceed'='true' THEN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR SHARE;PERFORM gridex_ediel_outbound_owner.require_utilts_err_source_v1(m,true);END IF;RETURN result;
END $$;

--
-- Name: mutate_before_switch_original_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_switch_original_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_ediel_transport.mutate_before_native_ack_guide_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND result->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid AND environment=p_input->>'environment' AND direction='outbound' FOR SHARE;PERFORM gridex_ediel_ack_guide.require_v1(m);
 END IF;RETURN result;
END $$;

--
-- Name: mutate_before_switch_production_brp_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_switch_production_brp_source_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN r:=gridex_ediel_transport.mutate_before_blob_retention_v1(p_input);IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN PERFORM public.ediel_require_source_bytes_available_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid);END IF;RETURN r;END$$;

--
-- Name: mutate_before_technical_expectation_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_technical_expectation_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN
 r:=gridex_ediel_transport.mutate_before_requested_change_v1(i);
 IF (i->>'action' IN('prepare','enter')) IS TRUE AND r->>'proceed'='true' THEN PERFORM public.ediel_require_requested_change_source_current_v1((i->>'companyId')::uuid,(i->>'messageId')::uuid);END IF;RETURN r;END$$;

--
-- Name: mutate_before_temporary_exception_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_temporary_exception_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
 result:=gridex_ediel_transport.mutate_before_signed_switch_method_v1(input);
 IF (input->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM gridex_received_sources.require_switch_contract_request_current_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid,(input->>'actorUserId')::uuid);
 RETURN result;
END$$;

--
-- Name: mutate_before_unused_unh_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_unused_unh_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;m public.ediel_messages%rowtype;BEGIN
 result:=gridex_ediel_transport.mutate_before_reference_profile_v1(i);
 IF(i->>'action' IN('prepare','enter')) IS TRUE AND result->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
  PERFORM gridex_ediel_ack_guide.require_reference_profile_current_message_v1(m);END IF;RETURN result;END $$;

--
-- Name: mutate_before_utilts_err_source_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_before_utilts_err_source_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=gridex_ediel_transport.mutate_before_switch_original_v1(i);
 IF (i->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM public.ediel_require_switch_original_current_v1((i->>'companyId')::uuid,(i->>'messageId')::uuid);
 RETURN result;
END $$;

--
-- Name: mutate_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.mutate_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();r:=gridex_ediel_transport.mutate_before_duplicate_protocol_v1(p_input);IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN PERFORM gridex_ediel_duplicate_responses.require_transport_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid,(p_input->>'actorUserId')::uuid);END IF;RETURN r;END$$;

--
-- Name: open_reconciliation_case_v1(text, uuid, text, text, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.open_reconciliation_case_v1(p_lane text, p_attempt_id uuid, p_reason text, p_origin text, p_origin_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a record; m public.ediel_messages%rowtype; snapshot_id uuid; n bigint; old_case gridex_ediel_transport.reconciliation_cases%rowtype; case_id uuid; bh text;
BEGIN
 IF p_lane='generic_journal' THEN
  SELECT x.id,x.company_id,x.environment,x.message_id,x.actor_user_id,x.binding,x.entered_at INTO STRICT a
   FROM gridex_ediel_transport.attempts x JOIN gridex_ediel_transport.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state IN ('entered','observed')
   WHERE x.id=p_attempt_id AND x.entered_at IS NOT NULL;
 ELSIF p_lane='sealed_z08' THEN
  SELECT x.id,x.company_id,x.environment,x.message_id,x.actor_user_id,x.binding,e.observed_at entered_at INTO STRICT a
   FROM gridex_outbound_dispatch.attempts x
   JOIN gridex_outbound_dispatch.originals o ON o.message_id=x.message_id AND o.company_id=x.company_id AND o.environment=x.environment AND o.payload_hash=x.binding->>'originalHash' AND o.payload_hash=encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex')
   JOIN gridex_outbound_dispatch.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state='provider_call_entered'
   JOIN gridex_outbound_dispatch.events e ON e.attempt_id=x.id AND e.message_id=x.message_id AND e.company_id=x.company_id AND e.environment=x.environment AND e.kind='provider_call_entered'
   JOIN gridex_outbound_dispatch.witnesses w ON w.event_id=e.id AND w.company_id=e.company_id AND w.environment=e.environment
   WHERE x.id=p_attempt_id AND e.created_xid<>pg_current_xact_id() AND w.created_xid<>pg_current_xact_id()
    AND pg_visible_in_snapshot(e.created_xid,pg_current_snapshot()) AND pg_visible_in_snapshot(w.created_xid,pg_current_snapshot());
 ELSE RAISE EXCEPTION 'ediel_reconciliation_lane_invalid'; END IF;
 IF p_reason='provider_outcome_unknown' THEN
  IF p_lane='generic_journal' THEN
   IF p_origin IS DISTINCT FROM 'generic_observation' OR p_origin_id IS DISTINCT FROM a.id OR NOT EXISTS(SELECT FROM gridex_ediel_transport.attempts x WHERE x.id=a.id AND x.observed_at IS NOT NULL AND x.classification='unknown' AND jsonb_typeof(x.provider_result)='object')
   THEN RAISE EXCEPTION 'ediel_reconciliation_observation_binding_invalid'; END IF;
  ELSE
   IF p_origin IS DISTINCT FROM 'sealed_result' OR NOT EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.id=p_origin_id AND e.attempt_id=a.id AND e.message_id=a.message_id AND e.company_id=a.company_id AND e.environment=a.environment AND e.kind='provider_result' AND e.facts->>'classification'='uncertain' AND jsonb_typeof(e.facts->'provider')='object' AND e.facts->>'automaticResend'='false')
   THEN RAISE EXCEPTION 'ediel_reconciliation_observation_binding_invalid'; END IF;
  END IF;
 ELSIF p_reason='entry_unresolved_after_lease' THEN
  IF p_origin IS DISTINCT FROM 'worker_claim_uncertain'
   OR NOT EXISTS(SELECT FROM public.ediel_outbox o WHERE o.id=p_origin_id AND o.company_id=a.company_id AND o.environment=a.environment AND o.ediel_message_id=a.message_id AND o.status='delivery_uncertain')
   OR p_lane='generic_journal' AND EXISTS(SELECT FROM gridex_ediel_transport.attempts x WHERE x.id=a.id AND x.observed_at IS NOT NULL)
   OR p_lane='sealed_z08' AND EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.attempt_id=a.id AND e.kind='provider_result')
  THEN RAISE EXCEPTION 'ediel_reconciliation_unresolved_binding_invalid'; END IF;
 ELSE RAISE EXCEPTION 'ediel_reconciliation_reason_invalid'; END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=a.message_id AND company_id=a.company_id AND environment=a.environment FOR SHARE;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.immutable_rendered_at IS NULL OR m.raw_payload IS NULL
  OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR a.binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash
  OR coalesce(a.binding->>'mimeSha256','') !~ '^[a-f0-9]{64}$' OR coalesce(a.binding->>'mimeLength','') !~ '^[1-9][0-9]*$'
  OR nullif(a.binding->>'mimeArchiveRef','') IS NULL OR nullif(a.binding->>'rfcMessageId','') IS NULL
 THEN RAISE EXCEPTION 'ediel_reconciliation_original_binding_invalid'; END IF;
 bh:=encode(sha256(convert_to(a.binding::text,'UTF8')),'hex');
 SELECT * INTO old_case FROM gridex_ediel_transport.reconciliation_cases WHERE company_id=a.company_id AND environment=a.environment AND lane=p_lane AND attempt_id=a.id;
 IF FOUND THEN
  IF old_case.message_id IS DISTINCT FROM a.message_id OR old_case.actor_user_id IS DISTINCT FROM a.actor_user_id OR old_case.binding_hash IS DISTINCT FROM bh OR old_case.entered_at IS DISTINCT FROM a.entered_at
  THEN RAISE EXCEPTION 'ediel_reconciliation_case_binding_changed'; END IF;
  RETURN old_case.id;
 END IF;
 -- Lock the exact retained archive metadata, without copying bytes or addresses.
 PERFORM 1 FROM public.ediel_message_payloads p WHERE p.company_id=a.company_id AND p.ediel_message_id=a.message_id AND p.encrypted_payload_ref=a.binding->>'mimeArchiveRef' FOR SHARE;
 SELECT count(*),(array_agg(p.id))[1] INTO n,snapshot_id FROM public.ediel_message_payloads p
  WHERE p.company_id=a.company_id AND p.ediel_message_id=a.message_id AND p.encrypted_payload_ref=a.binding->>'mimeArchiveRef'
   AND p.payload_kind IN ('raw_mime','smime_enveloped') AND p.metadata->>'archive_verified'='true'
   AND p.metadata->>'archived_mime_sha256'=a.binding->>'mimeSha256' AND p.metadata->>'archived_mime_bytes'=a.binding->>'mimeLength'
   AND p.metadata->>'archived_rfc_message_id'=a.binding->>'rfcMessageId';
 IF n<>1 THEN RAISE EXCEPTION 'ediel_reconciliation_archive_binding_not_qualified'; END IF;
 INSERT INTO gridex_ediel_transport.reconciliation_cases(company_id,environment,lane,attempt_id,message_id,actor_user_id,original_hash,binding_hash,mime_sha256,mime_length,mime_archive_ref,mime_payload_snapshot_id,rfc_message_id,entered_at,reason)
 VALUES(a.company_id,a.environment,p_lane,a.id,a.message_id,a.actor_user_id,m.immutable_payload_hash,bh,a.binding->>'mimeSha256',(a.binding->>'mimeLength')::bigint,a.binding->>'mimeArchiveRef',snapshot_id,a.binding->>'rfcMessageId',a.entered_at,p_reason) RETURNING id INTO case_id;
 INSERT INTO gridex_ediel_transport.reconciliation_case_events(case_id,company_id,environment,actor_user_id,kind,origin,origin_id)
 VALUES(case_id,a.company_id,a.environment,a.actor_user_id,'opened',p_origin,p_origin_id);
 RETURN case_id;
END $_$;

--
-- Name: read_dsn_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.read_dsn_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM 1 FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM 1 FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.read'),false)
  OR NOT EXISTS(SELECT FROM public.ediel_messages m WHERE m.id=p_message_id AND m.company_id=p_company_id AND m.direction='outbound') THEN RAISE EXCEPTION 'ediel_dsn_actor_scope_invalid' USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM gridex_ediel_transport.dsn_observations WHERE company_id=p_company_id AND message_id=p_message_id)>256 THEN RAISE EXCEPTION 'ediel_dsn_observation_read_limit';END IF;
 RETURN jsonb_build_object('version',1,'companyId',p_company_id,'messageId',p_message_id,'authorizesResend',false,'deliveryProven',false,'observations',coalesce((SELECT jsonb_agg(jsonb_build_object('observationId',o.id,'attemptId',o.attempt_id,'observedAt',o.observed_at,'transportCorrelation','source_matched_unverified','recipient',o.report#>'{recipients,0}') ORDER BY o.observed_at,o.id) FROM gridex_ediel_transport.dsn_observations o WHERE o.company_id=p_company_id AND o.message_id=p_message_id),'[]'::jsonb));
END $$;

--
-- Name: read_reconciliation_cases_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.read_reconciliation_cases_v1(p_company_id uuid, p_environment text, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF (SELECT count(*) FROM gridex_ediel_transport.reconciliation_cases WHERE company_id=p_company_id AND environment=p_environment AND message_id=p_message_id)>50
 THEN RAISE EXCEPTION 'ediel_reconciliation_case_scope_overflow'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('caseId',c.id,'companyId',c.company_id,'environment',c.environment,'messageId',c.message_id,'lane',c.lane,'attemptId',c.attempt_id,'originalHash',c.original_hash,'mimeSha256',c.mime_sha256,'enteredAt',c.entered_at,'openedAt',c.opened_at,'reason',c.reason,
  'status',CASE WHEN coalesce(g.classification,s.classification) IN ('accepted','partial','all_rejected','explicit_negative','pre_connect_negative') THEN 'outcome_observed' ELSE 'needs_tracking' END,
  'observedClassification',coalesce(g.classification,s.classification),'observedAt',coalesce(g.observed_at,s.observed_at),'authorizesResend',false,'deliveryProven',false) ORDER BY c.opened_at,c.id),'[]'::jsonb) INTO result
 FROM gridex_ediel_transport.reconciliation_cases c
 LEFT JOIN gridex_ediel_transport.attempts g ON c.lane='generic_journal' AND g.id=c.attempt_id AND g.company_id=c.company_id AND g.environment=c.environment AND g.message_id=c.message_id AND g.entered_at=c.entered_at AND encode(sha256(convert_to(g.binding::text,'UTF8')),'hex')=c.binding_hash
 LEFT JOIN LATERAL (
  SELECT e.facts->>'classification' classification,e.observed_at FROM gridex_outbound_dispatch.attempts a
  JOIN gridex_outbound_dispatch.events e ON e.attempt_id=a.id AND e.message_id=a.message_id AND e.company_id=a.company_id AND e.environment=a.environment AND e.kind='provider_result'
  JOIN gridex_outbound_dispatch.witnesses w ON w.event_id=e.id AND w.company_id=e.company_id AND w.environment=e.environment
  WHERE c.lane='sealed_z08' AND a.id=c.attempt_id AND a.company_id=c.company_id AND a.environment=c.environment AND a.message_id=c.message_id
   AND encode(sha256(convert_to(a.binding::text,'UTF8')),'hex')=c.binding_hash AND e.created_xid<>pg_current_xact_id() AND w.created_xid<>pg_current_xact_id()
   AND pg_visible_in_snapshot(e.created_xid,pg_current_snapshot()) AND pg_visible_in_snapshot(w.created_xid,pg_current_snapshot())
 ) s ON true
 WHERE c.company_id=p_company_id AND c.environment=p_environment AND c.message_id=p_message_id;
 RETURN result;
END $$;

--
-- Name: reconciliation_append_only_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.reconciliation_append_only_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_reconciliation_append_only' USING ERRCODE='23514'; END $$;

--
-- Name: reconciliation_observed_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.reconciliation_observed_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_TABLE_SCHEMA='gridex_ediel_transport' AND TG_TABLE_NAME='attempts' AND TG_OP='UPDATE' THEN
  IF OLD.observed_at IS NULL AND NEW.observed_at IS NOT NULL AND NEW.classification='unknown' AND NEW.entered_at IS NOT NULL THEN
   PERFORM gridex_ediel_transport.open_reconciliation_case_v1('generic_journal',NEW.id,'provider_outcome_unknown','generic_observation',NEW.id);
  END IF;
 ELSIF TG_TABLE_SCHEMA='gridex_outbound_dispatch' AND TG_TABLE_NAME='events' AND TG_OP='INSERT' THEN
  IF NEW.kind='provider_result' AND NEW.facts->>'classification'='uncertain' THEN
   -- Result witness can only be made after commit; require the committed ENTRY witness.
   PERFORM gridex_ediel_transport.open_reconciliation_case_v1('sealed_z08',NEW.attempt_id,'provider_outcome_unknown','sealed_result',NEW.id);
  END IF;
 ELSE RAISE EXCEPTION 'ediel_reconciliation_observation_origin_invalid'; END IF;
 RETURN NEW;
END $$;

--
-- Name: reconciliation_worker_uncertain_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.reconciliation_worker_uncertain_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a record;
BEGIN
 IF OLD.status IS DISTINCT FROM 'sending' OR NEW.status IS DISTINCT FROM 'delivery_uncertain' OR OLD.current_send_attempt_id IS NULL OR OLD.locked_at IS NULL OR nullif(OLD.locked_by,'') IS NULL
  OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.ediel_message_id IS DISTINCT FROM OLD.ediel_message_id OR NEW.current_send_attempt_id IS DISTINCT FROM OLD.current_send_attempt_id
 THEN RETURN NEW; END IF;
 -- The prior real claim, not a caller boolean, must own an unresolved entry.
 FOR a IN
  SELECT x.id,'generic_journal'::text lane FROM gridex_ediel_transport.attempts x
   JOIN gridex_ediel_transport.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state='entered'
   WHERE x.company_id=OLD.company_id AND x.environment=OLD.environment AND x.message_id=OLD.ediel_message_id AND x.entered_at IS NOT NULL AND x.observed_at IS NULL
    AND x.owner->>'kind'='worker' AND x.owner->>'outboxId'=OLD.id::text AND x.owner->>'sendAttemptId'=OLD.current_send_attempt_id::text AND x.owner->>'workerId'=OLD.locked_by
  UNION ALL
  SELECT x.id,'sealed_z08' FROM gridex_outbound_dispatch.attempts x
   JOIN gridex_outbound_dispatch.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state='provider_call_entered'
   WHERE x.company_id=OLD.company_id AND x.environment=OLD.environment AND x.message_id=OLD.ediel_message_id
    AND x.owner->>'kind'='worker' AND x.owner->>'outboxId'=OLD.id::text AND x.owner->>'sendAttemptId'=OLD.current_send_attempt_id::text AND x.owner->>'workerId'=OLD.locked_by
    AND EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.attempt_id=x.id AND e.message_id=x.message_id AND e.company_id=x.company_id AND e.environment=x.environment AND e.kind='provider_call_entered')
    AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.attempt_id=x.id AND e.message_id=x.message_id AND e.company_id=x.company_id AND e.environment=x.environment AND e.kind='provider_result')
 LOOP
  PERFORM gridex_ediel_transport.open_reconciliation_case_v1(a.lane,a.id,'entry_unresolved_after_lease','worker_claim_uncertain',OLD.id);
 END LOOP;
 RETURN NEW;
END $$;

--
-- Name: record_dsn_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.record_dsn_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c uuid:=(p_input->>'companyId')::uuid;actor uuid:=(p_input->>'actorUserId')::uuid;mailid uuid:=(p_input->>'inboundEmailMessageId')::uuid;
 mail public.inbound_email_messages%rowtype;mb public.ediel_mailboxes%rowtype;body text;field text:=p_input->>'sourceField';attachment uuid:=(p_input->>'attachmentId')::uuid;
 report jsonb:=p_input->'report';recipient jsonb;sourcehash text;candidate jsonb;candidates jsonb;obs gridex_ediel_transport.dsn_observations%rowtype;
BEGIN
 PERFORM 1 FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM 1 FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR mailid IS NULL OR field IS NULL OR field NOT IN('raw_email','body_text','attachment')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.read'),false) THEN RAISE EXCEPTION 'ediel_dsn_actor_scope_invalid' USING ERRCODE='42501';END IF;
 SELECT * INTO mail FROM public.inbound_email_messages WHERE id=mailid AND company_id=c FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_dsn_mail_scope_invalid';END IF;
 SELECT * INTO mb FROM public.ediel_mailboxes WHERE id=coalesce(nullif(to_jsonb(mail)->>'ediel_mailbox_id','')::uuid,nullif(to_jsonb(mail)->>'mailbox_id','')::uuid) FOR SHARE;
 IF NOT FOUND OR NOT mb.is_active OR mb.environment NOT IN('test','production') OR mb.company_id IS DISTINCT FROM c AND NOT(mb.company_id IS NULL AND mb.is_shared_platform_mailbox)
  OR to_jsonb(mail)->>'environment' IS NOT NULL AND to_jsonb(mail)->>'environment' IS DISTINCT FROM mb.environment THEN RAISE EXCEPTION 'ediel_dsn_mailbox_scope_invalid';END IF;
 IF field='attachment' THEN
  SELECT a.raw_text INTO body FROM public.inbound_email_attachments a WHERE a.id=attachment AND a.inbound_email_message_id=mailid FOR SHARE;
 ELSE
  IF attachment IS NOT NULL THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
  body:=to_jsonb(mail)->>field;
 END IF;
 sourcehash:=encode(sha256(convert_to(body,'UTF8')),'hex');
 IF body IS NULL OR octet_length(body)>26214400 OR sourcehash IS DISTINCT FROM p_input->>'sourceHash' OR jsonb_typeof(report) IS DISTINCT FROM 'object' OR octet_length(report::text)>262144
  OR report->>'version' IS DISTINCT FROM '1' OR report->>'transportCorrelation' IS DISTINCT FROM 'unverified' OR report->'issues' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(report->'originalMessageIds') IS DISTINCT FROM 'array' OR jsonb_array_length(report->'originalMessageIds')<>1
  OR jsonb_typeof(report->'recipients') IS DISTINCT FROM 'array' OR jsonb_array_length(report->'recipients')<>1 THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
 recipient:=report->'recipients'->0;
 IF recipient->>'action' IS NULL OR recipient->>'action' NOT IN('failed','delayed','delivered','relayed','expanded') OR coalesce(recipient->>'status','')!~'^[245]\.[0-9]{1,3}\.[0-9]{1,3}$'
  OR left(recipient->>'status',1) IS DISTINCT FROM (CASE recipient->>'action' WHEN 'failed' THEN '5' WHEN 'delayed' THEN '4' ELSE '2' END)
  OR recipient#>>'{finalRecipient,type}' IS NULL OR recipient#>>'{finalRecipient,type}' NOT IN('rfc822','utf-8')
  OR coalesce(recipient#>>'{finalRecipient,address}','')!~'^[^[:space:]<>@]+@[^[:space:]<>@]+$'
  OR NOT gridex_ediel_transport.dsn_source_identity_matches_v1(body,report) THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
 candidates:=gridex_ediel_transport.dsn_candidates_v1(c,mb.environment,report#>>'{originalMessageIds,0}',recipient#>>'{finalRecipient,address}',mb.id);
 IF jsonb_array_length(candidates)<>1 THEN RAISE EXCEPTION 'ediel_dsn_attempt_ambiguous_or_missing';END IF;
 candidate:=candidates->0;
 SELECT * INTO obs FROM gridex_ediel_transport.dsn_observations WHERE inbound_email_message_id=mailid AND source_field=field AND source_sha256=sourcehash AND attempt_id=(candidate->>'attemptId')::uuid AND lane=candidate->>'lane';
 IF FOUND THEN
  IF obs.company_id IS DISTINCT FROM c OR obs.environment IS DISTINCT FROM mb.environment OR obs.attachment_id IS DISTINCT FROM attachment OR obs.report IS DISTINCT FROM report THEN RAISE EXCEPTION 'ediel_dsn_observation_immutable';END IF;
 ELSE
  IF EXISTS(SELECT FROM gridex_ediel_transport.dsn_observations o WHERE o.inbound_email_message_id=mailid AND o.source_field=field AND o.attachment_id IS NOT DISTINCT FROM attachment AND o.source_sha256<>sourcehash) THEN RAISE EXCEPTION 'ediel_dsn_observation_source_changed';END IF;
  INSERT INTO gridex_ediel_transport.dsn_observations(inbound_email_message_id,company_id,environment,mailbox_id,message_id,attempt_id,lane,source_field,attachment_id,source_sha256,report,report_sha256)
   VALUES(mailid,c,mb.environment,mb.id,(candidate->>'messageId')::uuid,(candidate->>'attemptId')::uuid,candidate->>'lane',field,attachment,sourcehash,report,encode(sha256(convert_to(report::text,'UTF8')),'hex')) RETURNING * INTO obs;
 END IF;
 RETURN jsonb_build_object('version',1,'observationId',obs.id,'attemptId',obs.attempt_id,'messageId',obs.message_id,'sourceHash',obs.source_sha256,'observedAt',obs.observed_at,'transportCorrelation','source_matched_unverified','authorizesResend',false,'deliveryProven',false);
END $_$;

--
-- Name: repair_before_method_watch_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.repair_before_method_watch_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE projection jsonb; source_projection jsonb;
BEGIN
 projection:=gridex_ediel_transport.repair_message_projection_v1(p_company_id,p_environment,p_actor_user_id,p_message_id);
 IF projection IS NULL THEN RETURN NULL;END IF;
 source_projection:=public.ediel_project_accepted_source_state_v1(p_company_id,p_environment,p_actor_user_id,p_message_id,projection->>'originalHash');
 IF source_projection->>'status' IS DISTINCT FROM 'source_projection'
  OR source_projection->>'companyId' IS DISTINCT FROM projection->>'companyId'
  OR source_projection->>'environment' IS DISTINCT FROM projection->>'environment'
  OR source_projection->>'messageId' IS DISTINCT FROM projection->>'messageId'
  OR source_projection->>'originalHash' IS DISTINCT FROM projection->>'originalHash'
  OR (source_projection->>'observedAt')::timestamptz IS DISTINCT FROM (projection->>'observedAt')::timestamptz
  THEN RAISE EXCEPTION 'ediel_accepted_projection_source_changed';END IF;
 RETURN projection;
END $$;

--
-- Name: repair_message_projection_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.repair_message_projection_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; projection jsonb; resulting_status text;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR p_message_id IS NULL OR (p_environment IN ('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR UPDATE;
 projection:=public.gridex_ediel_accepted_transport_projection_v1(p_company_id,p_environment,p_actor_user_id,p_message_id);
 IF projection IS NULL THEN RETURN NULL;END IF;
 UPDATE public.ediel_messages SET
  status=CASE WHEN status IN ('draft','prepared','queued','dispatching','provider_accepted','sent') THEN 'sent' ELSE status END,
  processing_status=CASE WHEN processing_status IS NULL OR processing_status IN ('draft','prepared','queued','dispatching','provider_accepted','sent') THEN 'sent' ELSE processing_status END,
  message_sent_at=(projection->>'observedAt')::timestamptz,updated_by=p_actor_user_id,updated_at=now()
 WHERE id=p_message_id AND company_id=p_company_id AND environment=p_environment RETURNING status INTO resulting_status;
 RETURN projection||jsonb_build_object('projectionStatus',resulting_status);
END $$;

--
-- Name: require_message_intent_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_message_intent_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;p public.ediel_message_profiles%rowtype;r public.ediel_rule_packs%rowtype;
 route public.communication_routes%rowtype;profile public.ediel_route_profiles%rowtype;point public.metering_points%rowtype;
 tokens jsonb;unb jsonb;unh jsonb;bgm jsonb;physical_points text[];
BEGIN
 -- Prescribed technical/application ACKs keep their own exact source owner;
 -- ordinary P/U messages, including test fixtures, require their own intent.
 IF m.direction IS DISTINCT FROM 'outbound' OR (m.message_family IN('PRODAT','UTILTS')) IS NOT TRUE THEN RETURN;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id AND company_id=m.company_id FOR SHARE;
 SELECT * INTO p FROM public.ediel_message_profiles WHERE id=m.rule_profile_version_id FOR SHARE;
 SELECT * INTO r FROM public.ediel_rule_packs WHERE id=m.canonical_rule_pack_id FOR SHARE;
 SELECT * INTO route FROM public.communication_routes WHERE id=m.communication_route_id FOR SHARE;
 SELECT * INTO profile FROM public.ediel_route_profiles WHERE id=m.route_profile_id FOR SHARE;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM m.environment OR i.market IS DISTINCT FROM 'electricity' OR i.message_family IS DISTINCT FROM m.message_family OR i.message_code IS DISTINCT FROM m.message_code
  OR (i.direction IN('outbound','inbound_response')) IS NOT TRUE OR i.validation_status IS DISTINCT FROM 'validated' OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.validation_result->>'status' IS DISTINCT FROM 'validated' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb
  OR i.ediel_message_id IS DISTINCT FROM m.id OR i.outbound_request_id IS DISTINCT FROM m.outbound_request_id OR i.route_profile_id IS DISTINCT FROM m.route_profile_id OR i.communication_route_id IS DISTINCT FROM m.communication_route_id
  OR i.customer_id IS DISTINCT FROM m.customer_id OR i.customer_site_id IS DISTINCT FROM m.site_id OR i.supplier_switch_request_id IS DISTINCT FROM m.switch_request_id
  OR route.id IS NULL OR profile.id IS NULL OR (route.company_id IS NOT NULL AND route.company_id IS DISTINCT FROM m.company_id) OR (profile.company_id IS NOT NULL AND profile.company_id IS DISTINCT FROM m.company_id)
  OR route.is_active IS DISTINCT FROM true OR profile.is_enabled IS DISTINCT FROM true OR profile.environment IS DISTINCT FROM m.environment OR profile.communication_route_id IS DISTINCT FROM route.id
  OR p.id IS NULL OR p.is_enabled IS DISTINCT FROM true OR p.rule_pack_id IS DISTINCT FROM r.id OR p.message_code IS DISTINCT FROM m.message_code OR r.family IS DISTINCT FROM m.message_family
  OR (i.expected_rule_version IS NOT NULL AND i.expected_rule_version IS DISTINCT FROM m.rule_profile_version) OR (i.expected_field_matrix_version IS NOT NULL AND i.expected_field_matrix_version IS DISTINCT FROM r.field_matrix_version)
  OR (i.payload->>'transactionSubtype' IS NOT NULL AND i.payload->>'transactionSubtype' IS DISTINCT FROM p.transaction_subtype) THEN RAISE EXCEPTION 'ediel_native_validated_intent_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_native_intent_wire_required';END IF;
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';SELECT t INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 IF unh#>>'{elements,2,0}' IS DISTINCT FROM i.message_family OR bgm#>>'{elements,1,0}' IS DISTINCT FROM i.message_code
  OR unh#>>'{elements,1,0}' IS DISTINCT FROM i.message_reference OR unb#>>'{elements,5,0}' IS DISTINCT FROM i.interchange_reference OR unb#>>'{elements,7,0}' IS DISTINCT FROM i.application_reference
  OR unb#>>'{elements,2,0}' IS DISTINCT FROM i.sender_ediel_id OR unb#>>'{elements,3,0}' IS DISTINCT FROM i.receiver_ediel_id
  OR nullif(unb#>>'{elements,2,2}','') IS DISTINCT FROM nullif(i.sender_subaddress,'') OR nullif(unb#>>'{elements,3,2}','') IS DISTINCT FROM nullif(i.receiver_subaddress,'')
  OR (i.transaction_reference IS NOT NULL AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE (t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND t#>>'{elements,1,1}'=i.transaction_reference) OR (t->>'tag'='IDE' AND t#>>'{elements,2,0}'=i.transaction_reference))) THEN RAISE EXCEPTION 'ediel_native_intent_wire_scope_changed';END IF;
 IF m.metering_point_id IS NOT NULL THEN
  SELECT * INTO point FROM public.metering_points WHERE id=m.metering_point_id AND company_id=m.company_id FOR SHARE;
  IF point.id IS NULL OR nullif(i.metering_point_id,'') IS NULL OR point.customer_id IS DISTINCT FROM m.customer_id OR point.site_id IS DISTINCT FROM m.site_id
   OR (i.metering_point_id IS DISTINCT FROM point.id::text AND i.metering_point_id IS DISTINCT FROM point.meter_point_id AND i.metering_point_id IS DISTINCT FROM point.ediel_metering_point_id)
   OR (i.grid_area_code IS NOT NULL AND i.grid_area_code IS DISTINCT FROM point.grid_area_code) THEN RAISE EXCEPTION 'ediel_native_intent_owned_point_required';END IF;
  SELECT array_agg(DISTINCT t#>>'{elements,3,0}') INTO physical_points FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('LIN','LOC') AND t#>>'{elements,3,0}' IS NOT NULL;
  IF m.message_family='PRODAT' AND physical_points IS NOT NULL AND (cardinality(physical_points)<>1 OR (physical_points[1] IS DISTINCT FROM point.meter_point_id AND physical_points[1] IS DISTINCT FROM point.ediel_metering_point_id)) THEN RAISE EXCEPTION 'ediel_native_intent_physical_point_scope_changed';END IF;
 ELSIF i.metering_point_id IS NOT NULL THEN RAISE EXCEPTION 'ediel_native_intent_owned_point_required';END IF;
END $$;

--
-- Name: require_technical_expectation_binding_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_technical_expectation_binding_v1(m public.ediel_messages, p_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE plan jsonb;admission jsonb;
BEGIN
 plan:=gridex_ediel_transport.require_technical_expectation_plan_v1(m,p_binding->'technicalExpectationPlan');
 IF plan IS NULL THEN RETURN p_binding;END IF;admission:=p_binding->'admissionDecision';
 IF jsonb_typeof(admission) IS DISTINCT FROM 'object' OR admission->>'version' IS DISTINCT FROM '1' OR admission->>'family' IS DISTINCT FROM m.message_family OR admission->>'code' IS DISTINCT FROM gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code)
  OR plan->'policy' IS DISTINCT FROM jsonb_build_object('guideRevision',admission#>'{guide,guideRevision}','referenceDate',admission->'referenceDate','profileKey',admission->'profileKey','sourceTrace',admission->'sourceTrace') THEN RAISE EXCEPTION 'ediel_technical_expectation_same_admission_required';END IF;
 RETURN p_binding;
END $$;

--
-- Name: require_technical_expectation_plan_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_technical_expectation_plan_v1(m public.ediel_messages, p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE projection jsonb;cfg jsonb;rule jsonb;expected_profile jsonb;basis jsonb;r jsonb;scope jsonb;policy jsonb;v text;reference_date date;
BEGIN
 SELECT e.projection INTO STRICT projection FROM gridex_ediel_transport.technical_expectation_editions e WHERE source_version='05abbd87fb53e2a4e5e0583741e4dad6fed9f525010420e93c12e9b5c3dfda98';cfg:=projection->'constraints';
 IF m.direction IS DISTINCT FROM 'outbound' OR m.company_id IS NULL OR (m.environment IS NULL OR m.environment NOT IN('test','production')) THEN RAISE EXCEPTION 'ediel_technical_expectation_source_scope_required';END IF;
 IF m.message_family='AI_LIST' THEN IF p_plan IS NOT NULL AND p_plan<>'null'::jsonb THEN RAISE EXCEPTION 'ediel_technical_expectation_not_applicable';END IF;RETURN NULL;END IF;
 SELECT x INTO rule FROM jsonb_array_elements(projection->'ackMatrix')x WHERE x->>'family'=m.message_family AND x->>'code' IN(gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code),'*') ORDER BY(x->>'code'='*') LIMIT 1;
 IF rule IS NULL THEN RAISE EXCEPTION 'ediel_technical_expectation_unknown_family';END IF;
 IF rule->>'technicalAck'='none' THEN IF p_plan IS NOT NULL AND p_plan<>'null'::jsonb THEN RAISE EXCEPTION 'ediel_technical_expectation_not_applicable';END IF;RETURN NULL;END IF;
 IF jsonb_typeof(p_plan) IS DISTINCT FROM 'object' OR p_plan-'policy' IS DISTINCT FROM cfg OR jsonb_typeof(p_plan->'policy') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_technical_expectation_source_plan_required';END IF;
 policy:=p_plan->'policy';
 IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(policy)k) IS DISTINCT FROM ARRAY['guideRevision','profileKey','referenceDate','sourceTrace']::text[] OR jsonb_typeof(policy->'guideRevision') IS DISTINCT FROM 'string' OR nullif(policy->>'guideRevision','') IS NULL OR jsonb_typeof(policy->'referenceDate') IS DISTINCT FROM 'string' OR coalesce(policy->>'referenceDate','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR jsonb_typeof(policy->'sourceTrace') IS DISTINCT FROM 'array' OR jsonb_array_length(policy->'sourceTrace')=0 THEN RAISE EXCEPTION 'ediel_technical_expectation_policy_required';END IF;
 BEGIN reference_date:=(policy->>'referenceDate')::date;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'ediel_technical_expectation_reference_date_invalid';END;
 IF reference_date::text IS DISTINCT FROM policy->>'referenceDate' OR extract(year FROM reference_date)<=0 THEN RAISE EXCEPTION 'ediel_technical_expectation_reference_date_invalid';END IF;
 SELECT x INTO expected_profile FROM jsonb_array_elements(projection->'profiles')x WHERE x->>'family'=m.message_family AND x->>'code'=gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code);
 IF expected_profile IS NULL OR policy->'profileKey' IS DISTINCT FROM expected_profile->'profileKey' THEN RAISE EXCEPTION 'ediel_technical_expectation_canonical_profile_required';END IF;
 IF m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN basis:=gridex_ediel_common_header.require_ack_v1(m);r:=basis#>'{familyEdition,rulePack}';v:=basis#>>'{familyEdition,version}';
 ELSE basis:=gridex_ediel_source_rules.require_v1(m.company_id,m.id);r:=basis#>'{snapshot,rulePack}';v:=basis->>'version';END IF;
 SELECT x INTO scope FROM jsonb_array_elements(projection->'scopes')x WHERE x->>'family'=r->>'family' AND x->>'guideVersion'=r->>'guide_version' AND x->>'guideRevision'=r->>'guide_revision' ;
 IF nullif(v,'') IS NULL OR (basis->>'kind' IS DISTINCT FROM 'prodat_common_header_rejection' AND basis#>>'{snapshot,version}' IS DISTINCT FROM v) OR scope IS NULL OR policy->>'guideRevision' IS DISTINCT FROM scope->>'canonicalGuideRevision' THEN RAISE EXCEPTION 'ediel_technical_expectation_original_guide_required';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(x)k) IS DISTINCT FROM ARRAY['authority','document','section']::text[] OR jsonb_typeof(x->'authority') IS DISTINCT FROM 'string' OR nullif(x->>'authority','') IS NULL OR jsonb_typeof(x->'document') IS DISTINCT FROM 'string' OR nullif(x->>'document','') IS NULL OR jsonb_typeof(x->'section') IS DISTINCT FROM 'string' OR nullif(x->>'section','') IS NULL)
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE x->>'authority'='guide' AND x->>'document'=scope->>'documentName')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE x->>'authority'='acknowledgement' AND x->>'document'=scope->>'documentName') THEN RAISE EXCEPTION 'ediel_technical_expectation_source_trace_required';END IF;
 RETURN p_plan;
END $_$;

--
-- Name: before_message_write(); Type: FUNCTION; Schema: gridex_ediel_wire_namespace; Owner: -
--

CREATE FUNCTION gridex_ediel_wire_namespace.before_message_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.direction IS DISTINCT FROM OLD.direction)
  AND EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage WHERE source_message_id=OLD.id) THEN RAISE EXCEPTION 'ediel_wire_reference_namespace_context_immutable'; END IF;
 PERFORM gridex_ediel_wire_namespace.reserve(NEW);
 RETURN NEW;
END $$;

--
-- Name: immutable(); Type: FUNCTION; Schema: gridex_ediel_wire_namespace; Owner: -
--

CREATE FUNCTION gridex_ediel_wire_namespace.immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'ediel_wire_reference_reservation_immutable'; END $$;

--
-- Name: keys(text); Type: FUNCTION; Schema: gridex_ediel_wire_namespace; Owner: -
--

CREATE FUNCTION gridex_ediel_wire_namespace.keys(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb; unb jsonb; unh jsonb; token jsonb; sender text; legal_sender text; application text; interchange text; family text; output jsonb:='[]'; value text; kind text; key jsonb; cfg jsonb; maximum integer;
BEGIN
 tokens:=gridex_utilts_binding.wire_tokens_v1(p_raw);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH')<>1 THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 SELECT x INTO unb FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB';
 SELECT x INTO unh FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH';
 sender:=nullif(unb#>>'{elements,2,0}',''); application:=nullif(unb#>>'{elements,7,0}',''); interchange:=nullif(unb#>>'{elements,5,0}',''); family:=unh#>>'{elements,2,0}';
 IF sender IS NULL OR (application IS NULL AND family<>'CONTRL') OR interchange IS NULL OR char_length(interchange)>14 OR family NOT IN('PRODAT','UTILTS','APERAK','CONTRL') THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 SELECT min(x#>>'{elements,2,0}') INTO legal_sender FROM jsonb_array_elements(tokens) x
  WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=CASE WHEN family='PRODAT' THEN 'FR' ELSE 'MS' END;
 IF (SELECT count(DISTINCT x#>>'{elements,2,0}') FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=CASE WHEN family='PRODAT' THEN 'FR' ELSE 'MS' END)>1 THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 legal_sender:=coalesce(nullif(legal_sender,''),sender);application:=coalesce(application,'');
 -- UNB is unique for the technical sender across applications/subaddresses.
 output:=jsonb_build_array(jsonb_build_object('sender',sender,'application','','kind','UNB','value',interchange));
 FOR token IN SELECT x FROM jsonb_array_elements(tokens) x WHERE x->>'tag' IN('UNH','BGM','IDE','RFF') LOOP
  kind:=NULL;value:=NULL;
  CASE token->>'tag'
   WHEN 'UNH' THEN kind:='UNH';value:=token#>>'{elements,1,0}';
   WHEN 'BGM' THEN IF NOT(family='APERAK' AND nullif(token#>>'{elements,2,0}','') IS NULL) THEN kind:='BGM';value:=token#>>'{elements,2,0}';END IF;
   WHEN 'IDE' THEN kind:='IDE';value:=token#>>'{elements,2,0}';
   WHEN 'RFF' THEN
    IF token#>>'{elements,1,0}'='DM' THEN kind:='DM';value:=coalesce(nullif(token#>>'{elements,1,1}',''),token#>>'{elements,2,0}'); END IF;
   ELSE NULL;
  END CASE;
  IF kind IS NOT NULL THEN
   maximum:=35;
   IF kind='DM' THEN
    cfg:=gridex_ediel_ack_guide.utilts_reference_constraints_v1();
    IF unh#>'{elements,2}'=cfg->'technicalProfile' THEN maximum:=(cfg->>'ownDmMax')::integer;END IF;
   END IF;
   IF nullif(value,'') IS NULL OR char_length(value)>maximum THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
   key:=jsonb_build_object('sender',CASE WHEN kind='UNH' THEN sender ELSE legal_sender END,'application',CASE WHEN kind='UNH' THEN interchange ELSE application END,'kind',kind,'value',value);
   IF output @> jsonb_build_array(key) THEN RAISE EXCEPTION 'ediel_wire_reference_duplicate_in_source'; END IF;
   output:=output||jsonb_build_array(key);
  END IF;
 END LOOP;
 RETURN output;
END $$;

--
-- Name: reserve(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_wire_namespace; Owner: -
--

CREATE FUNCTION gridex_ediel_wire_namespace.reserve(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE keys jsonb; key jsonb; payload_hash text; old public.ediel_messages%rowtype; old_keys jsonb; owner uuid; test_indicator text;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' THEN RETURN; END IF;
 IF nullif(m.raw_payload,'') IS NULL THEN RETURN; END IF;
 IF left(m.raw_payload,3) NOT IN('UNA','UNB') THEN
  IF m.message_family IN('PRODAT','UTILTS','UTILTS_ERR','APERAK','CONTRL') THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
  RETURN;
 END IF;
 IF m.company_id IS NULL OR m.environment NOT IN('test','production') OR m.id IS NULL THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 keys:=gridex_ediel_wire_namespace.keys(m.raw_payload);
 SELECT coalesce(x#>>'{elements,11,0}','') INTO test_indicator FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload)) x WHERE x->>'tag'='UNB';
 IF test_indicator NOT IN('','1') OR m.environment IS DISTINCT FROM (CASE WHEN test_indicator='1' THEN 'test' ELSE 'production' END) THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 payload_hash:=encode(digest(convert_to(m.raw_payload,'UTF8'),'sha256'),'hex');
 -- Stable lock order makes shared-sender concurrency atomic across tenants.
 FOR key IN SELECT x FROM jsonb_array_elements(keys) x ORDER BY x::text LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(m.environment||':'||key::text,0));
 END LOOP;
 IF EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage c WHERE c.source_message_id=m.id AND c.payload_sha256=payload_hash AND c.company_id=m.company_id AND c.environment=m.environment) THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(keys) k WHERE NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.reservations r WHERE r.environment=m.environment AND r.sender_namespace=k->>'sender' AND r.application_namespace=k->>'application' AND r.reference_kind=k->>'kind' AND r.wire_reference=k->>'value' AND r.source_message_id=m.id AND r.company_id=m.company_id)) THEN RAISE EXCEPTION 'ediel_wire_reference_reservation_missing'; END IF;
  RETURN;
 END IF;
 -- Genuine retained legacy rows have not been prospectively indexed. Inspect
 -- their actual bytes before first allocation; do not infer historical sends.
 FOR old IN SELECT e.* FROM public.ediel_messages e WHERE e.id<>m.id AND e.direction='outbound' AND e.environment=m.environment AND left(e.raw_payload,3) IN('UNA','UNB')
  AND NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage c WHERE c.source_message_id=e.id AND c.payload_sha256=encode(digest(convert_to(e.raw_payload,'UTF8'),'sha256'),'hex')) LOOP
  BEGIN old_keys:=gridex_ediel_wire_namespace.keys(old.raw_payload); EXCEPTION WHEN raise_exception THEN RAISE EXCEPTION 'ediel_wire_reference_legacy_source_unqualified'; END;
  IF EXISTS(SELECT FROM jsonb_array_elements(keys) k JOIN jsonb_array_elements(old_keys) o ON k=o) THEN RAISE EXCEPTION 'ediel_wire_reference_namespace_collision'; END IF;
 END LOOP;
 FOR key IN SELECT x FROM jsonb_array_elements(keys) x ORDER BY x::text LOOP
  INSERT INTO gridex_ediel_wire_namespace.reservations(environment,sender_namespace,application_namespace,reference_kind,wire_reference,source_message_id,company_id,first_payload_sha256)
   VALUES(m.environment,key->>'sender',key->>'application',key->>'kind',key->>'value',m.id,m.company_id,payload_hash) ON CONFLICT DO NOTHING;
  SELECT source_message_id INTO owner FROM gridex_ediel_wire_namespace.reservations WHERE environment=m.environment AND sender_namespace=key->>'sender' AND application_namespace=key->>'application' AND reference_kind=key->>'kind' AND wire_reference=key->>'value';
  IF owner IS DISTINCT FROM m.id OR NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.reservations WHERE environment=m.environment AND sender_namespace=key->>'sender' AND application_namespace=key->>'application' AND reference_kind=key->>'kind' AND wire_reference=key->>'value' AND company_id=m.company_id) THEN RAISE EXCEPTION 'ediel_wire_reference_namespace_collision'; END IF;
 END LOOP;
 INSERT INTO gridex_ediel_wire_namespace.coverage VALUES(m.id,payload_hash,m.company_id,m.environment)
  ON CONFLICT(source_message_id) DO UPDATE SET payload_sha256=EXCLUDED.payload_sha256,company_id=EXCLUDED.company_id,environment=EXCLUDED.environment;
END $$;

--
-- Name: actor_open_blocking_conflict_counts(); Type: FUNCTION; Schema: gridex_internal; Owner: -
--

CREATE FUNCTION gridex_internal.actor_open_blocking_conflict_counts() RETURNS TABLE(actor_id uuid, open_blocking_conflicts integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    c.actor_id,
    count(*)::integer as open_blocking_conflicts
  from public.actor_registry_conflicts c
  where c.status = 'open'
    and c.severity = 'blocking'
    and c.actor_id is not null
  group by c.actor_id;
$$;

--
-- Name: FUNCTION actor_open_blocking_conflict_counts(); Type: COMMENT; Schema: gridex_internal; Owner: -
--

COMMENT ON FUNCTION gridex_internal.actor_open_blocking_conflict_counts() IS 'GRIDEX-OPS-O-008: internal aggregate-only open blocking conflict counts for readiness views.';

--
-- Name: bind_message_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.bind_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE o gridex_metering_method_changes.origins%rowtype;
b jsonb;
w jsonb;
r public.outbound_requests%rowtype;i public.ediel_message_intents%rowtype;

BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF; SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE intent_id=NEW.intent_id
  OR message_id=NEW.id;
IF NOT FOUND THEN RETURN NEW;
END IF;

 IF o.message_id IS NOT NULL THEN IF gridex_metering_method_changes.message_binding_v1(NEW,o) IS NOT TRUE THEN RAISE EXCEPTION 'method_bound_message_immutable';
END IF;
RETURN NEW;
END IF;

 b:=gridex_metering_method_changes.context_v1(o.company_id,o.event_id,o.actor_user_id);
SELECT * INTO STRICT o FROM gridex_metering_method_changes.origins WHERE intent_id=NEW.intent_id FOR UPDATE;

 IF o.message_id IS NOT NULL THEN IF gridex_metering_method_changes.message_binding_v1(NEW,o) IS NOT TRUE THEN RAISE EXCEPTION 'method_bound_message_immutable';
END IF;
RETURN NEW;
END IF;

 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id
  AND company_id=o.company_id FOR SHARE;

 IF gridex_metering_method_changes.request_binding_v1(r,o) IS NOT TRUE THEN RAISE EXCEPTION 'metering_method_change_owned_request_changed';
END IF;

 SELECT * INTO i FROM public.ediel_message_intents WHERE company_id=o.company_id AND id=o.intent_id FOR SHARE;
 IF i.id IS NULL OR gridex_metering_method_changes.intent_binding_v1(i) IS DISTINCT FROM o.intent_binding OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'metering_method_change_owned_intent_changed';END IF;
 w:=gridex_metering_method_changes.wire_v1(NEW.raw_payload);

 IF b IS DISTINCT FROM o.basis
  OR b->>'status' IS DISTINCT FROM 'authorized'
  OR NEW.created_by IS DISTINCT FROM o.actor_user_id OR NEW.company_id IS DISTINCT FROM o.company_id
  OR NEW.environment IS DISTINCT FROM b->>'environment'
  OR NEW.direction IS DISTINCT FROM 'outbound'
  OR NEW.message_family IS DISTINCT FROM 'PRODAT'
  OR NEW.message_code IS DISTINCT FROM 'Z09'
  OR NEW.source_operation_id IS DISTINCT FROM o.event_id::text
  OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id
  OR NEW.site_id IS DISTINCT FROM (b->>'siteId')::uuid
  OR NEW.customer_id IS DISTINCT FROM (b->>'customerId')::uuid
  OR NEW.metering_point_id IS DISTINCT FROM (b->>'meteringPointId')::uuid
  OR NEW.communication_route_id IS DISTINCT FROM (o.intent_binding->>'route')::uuid
  OR NEW.route_profile_id IS DISTINCT FROM (o.intent_binding->>'routeProfile')::uuid
  OR NEW.sender_ediel_id IS DISTINCT FROM o.intent_binding->>'sender'
  OR NEW.receiver_ediel_id IS DISTINCT FROM o.intent_binding->>'receiver'
  OR NEW.interchange_reference IS DISTINCT FROM o.intent_binding->>'interchange'
  OR NEW.transaction_reference IS DISTINCT FROM o.intent_binding->>'transaction'
  OR w IS NULL
  OR (b->>'environment'='test' AND w->>'testIndicator' IS DISTINCT FROM '1')
  OR (b->>'environment'='production' AND (w->>'testIndicator' IN ('','0')) IS NOT TRUE)
  OR w->>'code' IS DISTINCT FROM 'Z09'
  OR w->>'application' IS DISTINCT FROM '23-DDQ-PRODAT'
  OR w->>'sender' IS DISTINCT FROM b->>'legalSenderId'
  OR w->>'receiver' IS DISTINCT FROM b->>'legalReceiverId'
  OR w#>>'{object,reason}' IS DISTINCT FROM b->>'reason'
  OR w#>>'{object,point}' IS DISTINCT FROM b->>'pointId'
  OR w#>>'{object,agency}' IS DISTINCT FROM b->>'identityAgency'
  OR w#>>'{object,gridArea}' IS DISTINCT FROM b->>'gridArea'
  OR w#>>'{object,method}' IS DISTINCT FROM b->>'method'
  OR w#>>'{object,effective}' IS DISTINCT FROM to_char((b->>'effectiveAt')::timestamptz AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI')
  OR w#>>'{object,li}' IS DISTINCT FROM o.intent_binding->>'transaction'
  OR w->>'interchange' IS DISTINCT FROM o.intent_binding->>'interchange'
  OR w->>'message' IS DISTINCT FROM o.intent_binding->>'message'
  OR w->>'transportSender' IS DISTINCT FROM o.intent_binding->>'sender'
  OR w->>'transportReceiver' IS DISTINCT FROM o.intent_binding->>'receiver'
  OR w->>'senderSubaddress' IS DISTINCT FROM o.intent_binding->>'senderSubaddress'
  OR w->>'receiverSubaddress' IS DISTINCT FROM o.intent_binding->>'receiverSubaddress' THEN RAISE EXCEPTION 'metering_method_change_exact_wire_basis_required';
END IF;

 UPDATE gridex_metering_method_changes.origins SET message_id=NEW.id,payload_hash=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') WHERE event_id=o.event_id;

 INSERT INTO gridex_metering_method_changes.desired_change_receipts(event_id,company_id,environment,message_id,payload_hash,basis,effective_at) VALUES(o.event_id,o.company_id,b->>'environment',NEW.id,encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'),b,(b->>'effectiveAt')::timestamptz);

 RETURN NEW;
END$$;

--
-- Name: bind_recovery_message_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.bind_recovery_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$DECLARE b jsonb;BEGIN
 b:=gridex_metering_method_changes.require_recovery_message_v1(NEW,NEW.created_by,'prepare');
 IF b IS NULL THEN RETURN NEW;END IF;
 INSERT INTO gridex_metering_method_changes.recovery_receipts(operation_id,company_id,event_id,source_origin_message_id,original_message_id,message_id,intent_id,outbound_request_id,actor_user_id,environment,basis,payload_hash,message_scope)
 VALUES((b->>'recoveryOperationId')::uuid,NEW.company_id,(b->>'eventId')::uuid,(b->>'sourceOriginMessageId')::uuid,(b->>'originalMessageId')::uuid,NEW.id,NEW.intent_id,NEW.outbound_request_id,NEW.created_by,NEW.environment,b,b->>'correctedPayloadHash',gridex_requested_method_watches.message_scope_v1(NEW)) ON CONFLICT(operation_id) DO NOTHING;
 RETURN NEW;
END$$;

--
-- Name: canonical_tuple_projection_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.canonical_tuple_projection_v1() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
-- BEGIN CANONICAL METHOD CHANGE PROJECTION
 SELECT '{"F":{"subtype":"F","reason":"E64","method":"Z04"},"G":{"subtype":"G","reason":"E32","method":"Z03"}}'::jsonb
-- END CANONICAL METHOD CHANGE PROJECTION
$$;

--
-- Name: certification_basis_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.certification_basis_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE positive boolean;negative boolean;q jsonb;BEGIN
 IF m.id IS NULL OR m.company_id IS NULL OR m.environment IS DISTINCT FROM 'test'
  OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09'
  OR EXISTS(SELECT FROM gridex_metering_method_changes.origins o WHERE o.company_id=m.company_id AND o.message_id=m.id)
 OR EXISTS(SELECT FROM gridex_metering_method_changes.recovery_receipts o WHERE o.company_id=m.company_id AND o.message_id=m.id) OR EXISTS(SELECT FROM gridex_requested_changes.origins o WHERE o.company_id=m.company_id AND o.message_id=m.id)
  THEN RETURN NULL;END IF;
 SELECT EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions f WHERE f.message_id=m.id AND f.company_id=m.company_id),
  EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions f WHERE f.message_id=m.id AND f.company_id=m.company_id)
  INTO positive,negative;
 IF positive AND negative THEN RAISE EXCEPTION 'metering_method_change_fixture_source_ambiguous';END IF;
 IF NOT positive AND NOT negative THEN RETURN NULL;END IF;
 q:=CASE WHEN positive THEN gridex_negative_fixtures.require_positive_message_v1(m.company_id,m.id,'Z09')
  ELSE gridex_negative_fixtures.require_negative_message_v1(m.company_id,m.id,'Z09') END;
 IF gridex_metering_method_changes.fixture_qualification_v1(q,m.company_id,positive) IS NOT TRUE
  OR q->>'wireSha256' IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  THEN RAISE EXCEPTION 'metering_method_change_current_test_original_required';END IF;
 RETURN q;
END $$;

--
-- Name: context_before_brp_source_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.context_before_brp_source_v1(c uuid, event uuid, actor uuid, phase text DEFAULT 'origination'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;d jsonb;e gridex_metering_method_changes.events%rowtype;
BEGIN
 b:=gridex_metering_method_changes.context_before_contract_request_v1(c,event,actor,phase);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO e FROM gridex_metering_method_changes.events WHERE id=event AND company_id=c;
 IF e.requested_method_declaration_id IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_new_agreement_requested_method_declaration']);END IF;
 d:=gridex_metering_method_changes.contract_request_basis_v1(c,e.contract_id,actor,CASE phase WHEN 'send' THEN 'send' ELSE 'prepare' END,e.environment);
 IF d->>'status' IS DISTINCT FROM 'authorized' THEN RETURN d;END IF;
 IF d->>'declarationId' IS DISTINCT FROM e.requested_method_declaration_id::text OR d->>'customerId' IS DISTINCT FROM e.customer_id::text OR d->>'siteId' IS DISTINCT FROM b->>'siteId' OR d->>'meteringPointId' IS DISTINCT FROM e.metering_point_id::text OR d->>'legalActorId' IS DISTINCT FROM e.legal_actor_id::text OR d->>'legalSenderId' IS DISTINCT FROM e.legal_sender_id OR d->>'legalReceiverId' IS DISTINCT FROM e.legal_receiver_id OR d->>'pointId' IS DISTINCT FROM e.point_id OR d->>'identityAgency' IS DISTINCT FROM e.identity_agency OR d->>'gridArea' IS DISTINCT FROM e.grid_area_code OR d->>'contractRevision' IS DISTINCT FROM e.contract_revision OR d->>'agreementSha256' IS DISTINCT FROM e.agreement_sha256 OR d->>'requestedMethod' IS DISTINCT FROM b->>'method' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_customer_agreed_method_event_and_signed_declaration']);END IF;
 RETURN b||jsonb_build_object('requestedMethodDeclaration',d);
END$$;

--
-- Name: context_before_contract_request_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.context_before_contract_request_v1(c uuid, event uuid, actor uuid, phase text DEFAULT 'origination'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e gridex_metering_method_changes.events%rowtype;contract public.customer_contracts%rowtype;point public.metering_points%rowtype;supply jsonb;header jsonb;network jsonb;tuple jsonb;
BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_ai_processing.authorize_purpose_phase_v1(c,actor,phase,NULL);
 PERFORM gridex_contract_source_intake.lock_target_contract_v1(c,'metering_method_event',event); SELECT * INTO e FROM gridex_metering_method_changes.events WHERE id=event AND company_id=c FOR SHARE;
 IF NOT FOUND OR e.approved_at>statement_timestamp() OR EXISTS(SELECT FROM gridex_metering_method_changes.revocations WHERE event_id=e.id) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_customer_agreed_method_event']);END IF;
 -- The exact same current source owner supplies the supply relation and locks.
 IF gridex_ediel_retention.contract_copy_source_current_v1(c,'gridex_metering_method_changes','events',e.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_unpurged_method_event_originals']);END IF; supply:=gridex_received_sources.supply_period_source_at_v1(c,e.supply_period_id,e.effective_at);
 IF supply IS NULL OR supply->>'qualified' IS DISTINCT FROM 'true' OR nullif(supply->>'siteId','') IS NULL OR supply->>'customerId' IS DISTINCT FROM e.customer_id::text OR supply->>'meteringPointId' IS DISTINCT FROM e.metering_point_id::text OR supply->>'legalActorId' IS DISTINCT FROM e.legal_actor_id::text OR supply->>'sourceMessageId' IS DISTINCT FROM e.supply_source_message_id::text OR (supply->>'marketStateVersion')::bigint IS DISTINCT FROM e.supply_state_version OR supply->>'dsoEdielId' IS DISTINCT FROM e.legal_receiver_id
 OR (SELECT count(*) FROM jsonb_array_elements(supply->'sourceObjects') own WHERE own->>'point'=e.point_id AND own->>'identityAgency'=e.identity_agency AND own->>'gridArea'=e.grid_area_code)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_exact_source_owned_supply_relation']);END IF;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=e.contract_id AND company_id=c FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=e.metering_point_id AND company_id=c FOR SHARE;
 IF contract.id IS NULL OR point.id IS NULL OR contract.customer_id IS DISTINCT FROM e.customer_id OR contract.metering_point_id IS DISTINCT FROM e.metering_point_id OR point.customer_id IS DISTINCT FROM e.customer_id
 OR point.ediel_metering_point_id IS DISTINCT FROM e.point_id OR point.grid_owner_ediel_id IS DISTINCT FROM e.legal_receiver_id OR point.grid_area_code IS DISTINCT FROM e.grid_area_code
 OR contract.signed_at IS NULL OR contract.signed_version IS DISTINCT FROM e.contract_revision OR (contract.status IN('signed','active')) IS NOT TRUE
 OR gridex_received_sources.production_contract_hash_v1(contract) IS DISTINCT FROM e.protected_contract_hash
 OR to_jsonb(contract)->>'document_sha256' IS DISTINCT FROM e.agreement_sha256 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_customer_signed_agreement_original_revision_and_point']);END IF;
 network:=gridex_network_registry_sources.network_for_company_v1(c,e.legal_receiver_id,e.environment);
 IF network->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','missing',ARRAY[coalesce(network->>'blocker','authenticated_versioned_network_owner_basis_required')]);END IF;
 -- This existing helper owns tenant legal supplier/role and authenticated
 -- versioned network context. Its AI purpose/list processing is not invoked.
 header:=gridex_ai_processing.header_company_basis_v1(c,e.environment,e.legal_sender_id,e.legal_receiver_id);
 IF header->>'legalActorId' IS DISTINCT FROM e.legal_actor_id::text THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_legal_supplier_original_scope_changed']);END IF;
 tuple:=gridex_metering_method_changes.canonical_tuple_projection_v1()->e.subtype;
 RETURN jsonb_build_object('status','authorized','companyId',c,'environment',e.environment,'eventId',e.id,'supplyPeriodId',e.supply_period_id,'supplyStateVersion',e.supply_state_version,'supplySourceMessageId',e.supply_source_message_id,'customerId',e.customer_id,'siteId',supply->>'siteId','meteringPointId',e.metering_point_id,'legalActorId',e.legal_actor_id,'legalSenderId',e.legal_sender_id,'legalReceiverId',e.legal_receiver_id,'pointId',e.point_id,'identityAgency',e.identity_agency,'gridArea',e.grid_area_code,'effectiveAt',e.effective_at,'contractId',e.contract_id,'contractRevision',e.contract_revision,'agreementSha256',e.agreement_sha256,'sourceReference',e.source_reference,'sourceVersion',e.source_version,'sourceDigest',e.source_sha256,'subtype',e.subtype,'reason',tuple->>'reason','method',tuple->>'method','headerBasis',header);
END$$;

--
-- Name: context_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.context_v1(c uuid, event uuid, actor uuid, phase text DEFAULT 'origination'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;brp jsonb;BEGIN
 b:=gridex_metering_method_changes.context_before_brp_source_v1(c,event,actor,phase);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 brp:=gridex_brp_sources.require_source_v1(c,(b->>'contractId')::uuid,actor,CASE phase WHEN 'send' THEN 'send' ELSE 'prepare' END,b->>'environment',(b->>'customerId')::uuid,(b->>'siteId')::uuid,(b->>'meteringPointId')::uuid,(b->>'effectiveAt')::timestamptz,(b->>'supplyPeriodId')::uuid);
 IF brp->>'status' IS DISTINCT FROM 'authorized' THEN RETURN brp;END IF;
 IF brp->>'pointId' IS DISTINCT FROM b->>'pointId' OR brp->>'identityAgency' IS DISTINCT FROM b->>'identityAgency' OR brp->>'legalActorId' IS DISTINCT FROM b->>'legalActorId' OR brp->>'legalSenderId' IS DISTINCT FROM b->>'legalSenderId' OR brp->>'legalReceiverId' IS DISTINCT FROM b->>'legalReceiverId' OR brp->>'gridArea' IS DISTINCT FROM b->>'gridArea' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_method_change_current_brp_full_scope']);END IF;
 RETURN b||jsonb_build_object('brpEdielId',brp->>'brpEdielId','brpSource',brp);
END$$;

--
-- Name: contract_declaration_scope_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.contract_declaration_scope_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior gridex_metering_method_changes.contract_request_declarations%rowtype;BEGIN
 IF TG_TABLE_NAME='contract_request_revocations' THEN
 SELECT * INTO prior FROM gridex_metering_method_changes.contract_request_declarations WHERE id=NEW.declaration_id;
 IF prior.id IS NULL THEN RAISE EXCEPTION 'contract_request_revocation_original_required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-method-request:'||prior.company_id::text||':'||prior.contract_id::text,0));
 PERFORM id FROM gridex_metering_method_changes.contract_request_declarations WHERE id=NEW.declaration_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'contract_request_revocation_original_required';END IF;
 ELSE
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-method-request:'||NEW.company_id::text||':'||NEW.contract_id::text,0));
 IF NEW.previous_declaration_id IS NOT NULL THEN
 SELECT * INTO prior FROM gridex_metering_method_changes.contract_request_declarations WHERE id=NEW.previous_declaration_id FOR UPDATE;
 IF prior.id IS NULL OR prior.company_id IS DISTINCT FROM NEW.company_id OR prior.environment IS DISTINCT FROM NEW.environment OR prior.contract_id IS DISTINCT FROM NEW.contract_id OR NEW.approved_at<prior.approved_at THEN RAISE EXCEPTION 'contract_request_declaration_own_version_required';END IF;
 END IF;END IF;RETURN NEW;
END$$;

--
-- Name: contract_request_basis_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.contract_request_basis_v1(c uuid, ct uuid, actor uuid, phase text, expected_environment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_metering_method_changes.contract_request_declarations%rowtype;contract public.customer_contracts%rowtype;point public.metering_points%rowtype;site public.customer_sites%rowtype;header jsonb;network jsonb;
BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF (phase IN('prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'contract_requested_method_phase_required';END IF;
 PERFORM gridex_ai_processing.authorize_purpose_phase_v1(c,actor,CASE phase WHEN 'prepare' THEN 'origination' ELSE 'send' END,NULL);
 SELECT * INTO contract FROM public.customer_contracts WHERE id=ct AND company_id=c FOR SHARE;
 IF contract.id IS NULL OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR (contract.status IN('signed','active')) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_signed_new_customer_agreement']);END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('contract-method-request:'||c::text||':'||ct::text,0));
 IF (SELECT count(*) FROM gridex_metering_method_changes.contract_request_declarations a WHERE a.company_id=c AND a.contract_id=ct AND (expected_environment IS NULL OR a.environment=expected_environment) AND a.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_declarations child WHERE child.previous_declaration_id=a.id AND child.approved_at<=statement_timestamp()) AND NOT EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_revocations r WHERE r.declaration_id=a.id))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['unique_authentic_new_agreement_requested_method_declaration']);END IF;
 SELECT * INTO d FROM gridex_metering_method_changes.contract_request_declarations a WHERE a.company_id=c AND a.contract_id=ct AND (expected_environment IS NULL OR a.environment=expected_environment) AND a.approved_at<=statement_timestamp() AND NOT EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_declarations child WHERE child.previous_declaration_id=a.id AND child.approved_at<=statement_timestamp()) AND NOT EXISTS(SELECT FROM gridex_metering_method_changes.contract_request_revocations r WHERE r.declaration_id=a.id) FOR SHARE;
 IF gridex_ediel_retention.contract_copy_source_current_v1(c,'gridex_metering_method_changes','contract_request_declarations',d.id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_unpurged_signed_method_declaration']);END IF; SELECT * INTO point FROM public.metering_points WHERE id=d.metering_point_id AND company_id=c FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=d.site_id AND company_id=c FOR SHARE;
 IF point.id IS NULL OR site.id IS NULL OR contract.customer_id IS DISTINCT FROM d.customer_id OR contract.metering_point_id IS DISTINCT FROM d.metering_point_id OR coalesce(contract.customer_site_id,contract.site_id) IS DISTINCT FROM d.site_id OR (contract.customer_site_id IS NOT NULL AND contract.customer_site_id IS DISTINCT FROM d.site_id) OR (contract.site_id IS NOT NULL AND contract.site_id IS DISTINCT FROM d.site_id)
 OR contract.signed_version IS DISTINCT FROM d.contract_revision OR gridex_received_sources.production_contract_hash_v1(contract) IS DISTINCT FROM d.protected_contract_hash OR contract.document_sha256 IS DISTINCT FROM d.agreement_sha256
 OR site.customer_id IS DISTINCT FROM d.customer_id OR point.customer_id IS DISTINCT FROM d.customer_id OR coalesce(point.customer_site_id,point.site_id) IS DISTINCT FROM d.site_id OR (point.customer_site_id IS NOT NULL AND point.customer_site_id IS DISTINCT FROM d.site_id) OR (point.site_id IS NOT NULL AND point.site_id IS DISTINCT FROM d.site_id)
 OR coalesce(nullif(point.ediel_metering_point_id,''),nullif(point.meter_point_id,'')) IS DISTINCT FROM d.point_id OR point.grid_owner_ediel_id IS DISTINCT FROM d.legal_receiver_id OR point.grid_area_code IS DISTINCT FROM d.grid_area_code THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_signed_agreement_revision_original_customer_site_point']);END IF;
 network:=gridex_network_registry_sources.network_for_company_v1(c,d.legal_receiver_id,d.environment);
 IF network->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','missing',ARRAY[coalesce(network->>'blocker','authenticated_versioned_network_owner_basis_required')]);END IF;
 header:=gridex_ai_processing.header_company_basis_v1(c,d.environment,d.legal_sender_id,d.legal_receiver_id);
 IF header->>'legalActorId' IS DISTINCT FROM d.legal_actor_id::text THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_legal_supplier_agreement_scope_changed']);END IF;
 RETURN jsonb_build_object('status','authorized','declarationId',d.id,'companyId',c,'environment',d.environment,'contractId',ct,'contractRevision',d.contract_revision,'protectedContractHash',d.protected_contract_hash,'agreementSha256',d.agreement_sha256,'customerId',d.customer_id,'siteId',d.site_id,'meteringPointId',d.metering_point_id,'pointId',d.point_id,'identityAgency',d.identity_agency,'legalActorId',d.legal_actor_id,'legalSenderId',d.legal_sender_id,'legalReceiverId',d.legal_receiver_id,'gridArea',d.grid_area_code,'requestedMethod',d.requested_method,'sourceReference',d.source_reference,'sourceVersion',d.source_version,'sourceDigest',d.source_sha256);
END$$;

--
-- Name: fixture_qualification_v1(jsonb, uuid, boolean); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.fixture_qualification_v1(q jsonb, c uuid, positive boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT
 q IS NOT NULL AND q->>'companyId'=c::text AND q->>'version'='1' AND q->>'roleCode'='supplier' AND q->>'suite'='PRODAT' AND q->'authorizesBusinessEffect'='false'::jsonb
 AND CASE WHEN positive THEN q->>'kind'='source_qualified_positive_fixture' AND q->>'expectedOutcome'='positive' AND q->'expectedDiagnosticCodes'='[]'::jsonb
 ELSE q->>'kind'='source_qualified_negative_fixture' AND q->>'expectedOutcome'='negative' AND jsonb_typeof(q->'expectedDiagnosticCodes')='array' AND jsonb_array_length(q->'expectedDiagnosticCodes') BETWEEN 1 AND 256 END$$;

--
-- Name: frozen_original_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.frozen_original_basis_v1(c uuid, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_requested_changes.origins%rowtype;b jsonb;w jsonb;h text;old_basis jsonb;effective timestamptz;accepted jsonb;a gridex_ediel_transport.attempts%rowtype;e gridex_requested_method_watches.entry_sources%rowtype;
BEGIN
 IF EXISTS(SELECT FROM gridex_metering_method_changes.recovery_receipts r WHERE r.company_id=c AND r.message_id=msg) THEN RETURN gridex_metering_method_changes.frozen_recovery_basis_v1(c,msg);END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE company_id=c AND message_id=msg FOR SHARE;
 IF NOT FOUND THEN RETURN gridex_metering_method_changes.frozen_original_before_requested_changes_v1(c,msg);END IF;
 old_basis:=gridex_metering_method_changes.frozen_original_before_requested_changes_v1(c,msg);
 IF old_basis IS NOT NULL THEN RAISE EXCEPTION 'ediel_method_expectation_original_owner_ambiguous';END IF;
 IF (o.basis->>'variant' IN('F','G')) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=c AND id=msg FOR SHARE;
 h:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09'
  OR m.intent_id IS DISTINCT FROM o.intent_id OR m.source_operation_id IS DISTINCT FROM o.event_id::text
  OR m.environment IS DISTINCT FROM o.basis->>'environment' OR m.immutable_rendered_at IS NULL
  OR m.immutable_payload_hash IS DISTINCT FROM h OR o.payload_hash IS DISTINCT FROM h THEN RETURN NULL;END IF;
 -- A later confirmed structural version/contract change cannot relabel the
 -- original. The private entry receipt records current qualification BEFORE
 -- provider entry. It becomes observational authority only with the exact
 -- subsequently accepted native journal; it authorizes no market/reading effect.
 accepted:=gridex_ediel_transport.accepted_source_basis_v1(m);
 IF accepted IS NOT NULL THEN
  IF accepted->>'lane' IS DISTINCT FROM 'generic_journal' THEN RETURN NULL;END IF;
  SELECT * INTO e FROM gridex_requested_method_watches.entry_sources WHERE attempt_id=(accepted->>'attemptId')::uuid AND company_id=c AND environment=m.environment AND message_id=m.id;
  SELECT * INTO a FROM gridex_ediel_transport.attempts WHERE id=e.attempt_id AND company_id=c AND environment=m.environment AND message_id=m.id;
  IF e.attempt_id IS NULL OR e.event_id IS DISTINCT FROM o.event_id OR e.intent_id IS DISTINCT FROM o.intent_id
   OR e.source_payload_hash IS DISTINCT FROM h OR e.basis IS DISTINCT FROM o.basis
   OR e.basis_hash IS DISTINCT FROM encode(sha256(convert_to(o.basis::text,'UTF8')),'hex')
   OR e.entry_binding_hash IS DISTINCT FROM encode(sha256(convert_to(a.binding::text,'UTF8')),'hex')
   OR e.message_scope IS DISTINCT FROM gridex_requested_method_watches.message_scope_v1(m)
   OR e.entered_at IS DISTINCT FROM a.entered_at OR a.entered_at IS NULL
   OR (accepted->>'observedAt')::timestamptz<a.entered_at THEN RETURN NULL;END IF;
  b:=e.basis;
 ELSE
  -- Prospective sends still require actual current archive/reviewer/issuer/
  -- contract/customer/supply/intent/route/physical LI qualification.
  BEGIN
   b:=gridex_requested_changes.require_message_v1(m,o.actor_user_id);
   PERFORM gridex_ediel_source_rules.require_v1(c,m.id);
  EXCEPTION WHEN raise_exception OR insufficient_privilege THEN RETURN NULL;END;
 END IF;
 IF b IS DISTINCT FROM o.basis OR b->>'status' IS DISTINCT FROM 'authorized'
  OR b->>'eventId' IS DISTINCT FROM o.event_id::text OR b->>'companyId' IS DISTINCT FROM c::text
  OR b->>'eventKind' IS DISTINCT FROM (CASE b->>'variant' WHEN 'F' THEN 'quarter_contract' WHEN 'G' THEN 'method_contract' END) THEN RETURN NULL;END IF;
 w:=gridex_metering_method_changes.wire_v1(m.raw_payload);
 effective:=(b->>'effectiveAt')::timestamptz;
 IF w IS NULL OR w->>'code' IS DISTINCT FROM 'Z09'
  OR w#>>'{object,reason}' IS DISTINCT FROM (CASE b->>'variant' WHEN 'F' THEN 'E64' WHEN 'G' THEN 'E32' END)
  OR w#>>'{object,effective}' IS DISTINCT FROM to_char(effective AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('authorized',true,'sourceOwner','requested_change_original_v1','eventId',o.event_id,
  'sourceMessageId',m.id,'sourcePayloadHash',h,'basis',b||jsonb_build_object('subtype',b->>'variant','method',CASE b->>'variant' WHEN 'F' THEN 'Z04' WHEN 'G' THEN 'Z03' END),
  'physicalObject',w->'object','validityDay',substring(w#>>'{object,effective}',1,8));
END $$;

--
-- Name: frozen_original_before_requested_changes_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.frozen_original_before_requested_changes_v1(c uuid, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_metering_method_changes.desired_change_receipts%rowtype;m public.ediel_messages%rowtype;o gridex_metering_method_changes.origins%rowtype;w jsonb;BEGIN
 SELECT * INTO r FROM gridex_metering_method_changes.desired_change_receipts WHERE company_id=c AND message_id=msg;
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=c AND id=msg;
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=c AND message_id=msg;
 IF r.event_id IS NULL OR o.event_id IS DISTINCT FROM r.event_id OR o.payload_hash IS DISTINCT FROM r.payload_hash OR o.basis IS DISTINCT FROM r.basis OR gridex_metering_method_changes.message_binding_v1(m,o) IS NOT TRUE THEN RETURN NULL;END IF;
 w:=gridex_metering_method_changes.wire_v1(m.raw_payload);
 IF w IS NULL OR w#>>'{object,effective}' IS DISTINCT FROM to_char(r.effective_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('authorized',true,'eventId',r.event_id,'sourceMessageId',msg,'sourcePayloadHash',r.payload_hash,'basis',r.basis,'physicalObject',w->'object','validityDay',substring(w#>>'{object,effective}',1,8));
END$$;

--
-- Name: frozen_recovery_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.frozen_recovery_basis_v1(c uuid, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE r gridex_metering_method_changes.recovery_receipts%rowtype;m public.ediel_messages%rowtype;source jsonb;w jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO r FROM gridex_metering_method_changes.recovery_receipts WHERE company_id=c AND message_id=msg FOR SHARE;
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=c AND id=msg FOR SHARE;
 IF r.operation_id IS NULL OR m.id IS NULL OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM r.payload_hash
  OR m.immutable_rendered_at IS NULL OR r.message_scope IS DISTINCT FROM gridex_requested_method_watches.message_scope_v1(m) THEN RETURN NULL;END IF;
 source:=gridex_metering_method_changes.frozen_original_before_requested_changes_v1(c,r.source_origin_message_id);w:=gridex_metering_method_changes.wire_v1(m.raw_payload);
 IF source IS NULL OR source->>'eventId' IS DISTINCT FROM r.event_id::text OR (r.basis-ARRAY['recoveryOperationId','originalMessageId','sourceOriginMessageId','correctedPayloadHash']) IS DISTINCT FROM source->'basis'
  OR w IS NULL OR w->'object' IS DISTINCT FROM source->'physicalObject' THEN RETURN NULL;END IF;
 RETURN source||jsonb_build_object('sourceMessageId',m.id,'sourcePayloadHash',r.payload_hash,'sourceOwner','metering_method_recovery_v1','recoveryOperationId',r.operation_id,'sourceOriginMessageId',r.source_origin_message_id);
END$$;

--
-- Name: guard_brp_wire_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.guard_brp_wire_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_metering_method_changes.origins%rowtype;b jsonb;tokens jsonb;nad jsonb;n integer;first_line integer;BEGIN
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=NEW.company_id AND intent_id=NEW.intent_id;
 IF o.event_id IS NULL THEN RETURN NEW;END IF;
 IF o.message_id IS NOT NULL THEN RETURN NEW;END IF; -- Existing frozen outcome has its original immutable binder.
 b:=gridex_metering_method_changes.context_v1(o.company_id,o.event_id,o.actor_user_id);
 IF b->>'status' IS DISTINCT FROM 'authorized' OR b IS DISTINCT FROM o.basis THEN RAISE EXCEPTION 'metering_method_change_current_brp_source_required';END IF;
 IF gridex_metering_method_changes.wire_brp_matches_v1(NEW.raw_payload,b) IS NOT TRUE THEN RAISE EXCEPTION 'metering_method_change_own_source_field262_required';END IF;RETURN NEW;
END$$;

--
-- Name: intent_binding_v1(public.ediel_message_intents); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.intent_binding_v1(i public.ediel_message_intents) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT jsonb_build_object('company',i.company_id,'environment',i.environment,'operation',i.operation_id,'customer',i.customer_id,'site',i.customer_site_id,'point',i.metering_point_id,'application',i.application_reference,'direction',i.direction,'family',i.message_family,'code',i.message_code,'validationStatus',i.validation_status,'businessProcess',i.business_process,'market',i.market,'sender',i.sender_ediel_id,'receiver',i.receiver_ediel_id,'senderSubaddress',i.sender_subaddress,'receiverSubaddress',i.receiver_subaddress,'interchange',i.interchange_reference,'message',i.message_reference,'transaction',i.transaction_reference,'route',i.communication_route_id,'routeProfile',i.route_profile_id)$$;

--
-- Name: origins; Type: TABLE; Schema: gridex_metering_method_changes; Owner: -
--

CREATE TABLE gridex_metering_method_changes.origins (
    event_id uuid NOT NULL,
    company_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    outbound_request_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    message_id uuid,
    payload_hash text,
    basis jsonb NOT NULL,
    intent_binding jsonb NOT NULL,
    reserved_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT origins_check CHECK (((message_id IS NULL) = (payload_hash IS NULL)))
);

ALTER TABLE ONLY gridex_metering_method_changes.origins FORCE ROW LEVEL SECURITY;

--
-- Name: message_binding_v1(public.ediel_messages, gridex_metering_method_changes.origins); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.message_binding_v1(m public.ediel_messages, o gridex_metering_method_changes.origins) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$SELECT
 m.created_by IS NOT DISTINCT FROM o.actor_user_id AND m.id IS NOT DISTINCT FROM o.message_id
  AND m.intent_id IS NOT DISTINCT FROM o.intent_id
  AND m.company_id IS NOT DISTINCT FROM o.company_id
  AND m.environment IS NOT DISTINCT FROM o.basis->>'environment'
  AND m.direction IS NOT DISTINCT FROM 'outbound'
  AND m.message_family IS NOT DISTINCT FROM 'PRODAT'
  AND m.message_code IS NOT DISTINCT FROM 'Z09'
  AND m.source_operation_id IS NOT DISTINCT FROM o.event_id::text
  AND m.outbound_request_id IS NOT DISTINCT FROM o.outbound_request_id
  AND m.site_id IS NOT DISTINCT FROM (o.basis->>'siteId')::uuid
  AND m.customer_id IS NOT DISTINCT FROM (o.basis->>'customerId')::uuid
  AND m.metering_point_id IS NOT DISTINCT FROM (o.basis->>'meteringPointId')::uuid
  AND m.communication_route_id IS NOT DISTINCT FROM (o.intent_binding->>'route')::uuid
  AND m.route_profile_id IS NOT DISTINCT FROM (o.intent_binding->>'routeProfile')::uuid
  AND m.sender_ediel_id IS NOT DISTINCT FROM o.intent_binding->>'sender'
  AND m.receiver_ediel_id IS NOT DISTINCT FROM o.intent_binding->>'receiver'
  AND m.interchange_reference IS NOT DISTINCT FROM o.intent_binding->>'interchange'
  AND m.transaction_reference IS NOT DISTINCT FROM o.intent_binding->>'transaction'
  AND o.payload_hash IS NOT DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')$$;

--
-- Name: origin_guard_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.origin_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$BEGIN IF TG_OP IS DISTINCT FROM 'UPDATE'
  OR (to_jsonb(NEW)-ARRAY['message_id','payload_hash']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['message_id','payload_hash'])
  OR OLD.message_id IS NOT NULL
  OR NEW.message_id IS NULL
  OR NEW.payload_hash IS NULL THEN RAISE EXCEPTION 'method_origin_immutable';
END IF;
RETURN NEW;
END$$;

--
-- Name: recovery_source_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.recovery_source_v1(c uuid, op_id uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;source public.ediel_messages%rowtype;o gridex_metering_method_changes.origins%rowtype;
 q jsonb;b jsonb;original_wire jsonb;corrected_wire jsonb;tokens jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(c,actor,phase);
 PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(c,op_id);
 q:=gridex_received_sources.qualified_recovery_origin_v1(c,op_id);
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=op_id AND company_id=c;
 IF (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE THEN RETURN NULL;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(op.corrected_raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z09')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}' IN(SELECT value->>'reason' FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()))) THEN RETURN NULL;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=(q->>'sourceOriginMessageId')::uuid AND company_id=c AND environment=op.environment FOR SHARE;
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE message_id=source.id AND company_id=c FOR SHARE;
 -- This port owns genuine customer-agreed metering events only. Other source
 -- owners retain their explicit native lanes; nothing manufactures a new event.
 IF o.event_id IS NULL THEN RETURN NULL;END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(c,actor,phase);
 b:=gridex_metering_method_changes.context_v1(c,o.event_id,actor,CASE phase WHEN 'send' THEN 'send' ELSE 'origination' END);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 original_wire:=gridex_metering_method_changes.wire_v1(source.raw_payload);corrected_wire:=gridex_metering_method_changes.wire_v1(op.corrected_raw_payload);
 IF source.direction IS DISTINCT FROM 'outbound' OR source.message_family IS DISTINCT FROM 'PRODAT' OR source.message_code IS DISTINCT FROM 'Z09'
  OR source.immutable_rendered_at IS NULL OR source.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex')
  OR o.payload_hash IS DISTINCT FROM source.immutable_payload_hash OR gridex_metering_method_changes.message_binding_v1(source,o) IS NOT TRUE
  OR b IS DISTINCT FROM o.basis OR original_wire IS NULL OR corrected_wire IS NULL
  OR gridex_metering_method_changes.wire_brp_matches_v1(source.raw_payload,b) IS NOT TRUE OR gridex_metering_method_changes.wire_brp_matches_v1(op.corrected_raw_payload,b) IS NOT TRUE
  OR corrected_wire->>'code' IS DISTINCT FROM 'Z09' OR corrected_wire->>'application' IS DISTINCT FROM '23-DDQ-PRODAT'
  OR corrected_wire->>'sender' IS DISTINCT FROM b->>'legalSenderId' OR corrected_wire->>'receiver' IS DISTINCT FROM b->>'legalReceiverId'
  OR corrected_wire->'object' IS DISTINCT FROM original_wire->'object'
  OR corrected_wire#>>'{object,reason}' IS DISTINCT FROM b->>'reason' OR corrected_wire#>>'{object,method}' IS DISTINCT FROM b->>'method'
  OR corrected_wire#>>'{object,effective}' IS DISTINCT FROM to_char((b->>'effectiveAt')::timestamptz AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI')
  OR corrected_wire#>>'{object,point}' IS DISTINCT FROM b->>'pointId' OR corrected_wire#>>'{object,agency}' IS DISTINCT FROM b->>'identityAgency'
  OR corrected_wire#>>'{object,gridArea}' IS DISTINCT FROM b->>'gridArea'
  OR (op.environment='test' AND corrected_wire->>'testIndicator' IS DISTINCT FROM '1')
  OR (op.environment='production' AND (corrected_wire->>'testIndicator' IN('','0')) IS NOT TRUE)
  THEN RAISE EXCEPTION 'metering_method_recovery_current_original_tuple_required';END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(c,actor,phase);
 RETURN b||jsonb_build_object('recoveryOperationId',op.id,'originalMessageId',op.original_message_id,'sourceOriginMessageId',source.id,'correctedPayloadHash',op.corrected_payload_hash);
END$$;

--
-- Name: request_binding_v1(public.outbound_requests, gridex_metering_method_changes.origins); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.request_binding_v1(r public.outbound_requests, o gridex_metering_method_changes.origins) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$SELECT
 r.id IS NOT DISTINCT FROM o.outbound_request_id
  AND r.company_id IS NOT DISTINCT FROM o.company_id
  AND r.source_id::text IS NOT DISTINCT FROM o.intent_id::text
  AND r.source_type IS NOT DISTINCT FROM 'manual'
  AND r.request_type IS NOT DISTINCT FROM 'customer_masterdata'
  AND r.site_id IS NOT DISTINCT FROM (o.basis->>'siteId')::uuid
  AND r.payload->>'environment' IS NOT DISTINCT FROM o.basis->>'environment'
  AND r.customer_id IS NOT DISTINCT FROM (o.basis->>'customerId')::uuid
  AND r.metering_point_id IS NOT DISTINCT FROM (o.basis->>'meteringPointId')::uuid
  AND r.operation_id IS NOT DISTINCT FROM o.event_id
  AND r.communication_route_id IS NOT DISTINCT FROM (o.intent_binding->>'route')::uuid$$;

--
-- Name: require_origin_before_insert_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.require_origin_before_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE positive uuid;negative uuid;q jsonb;w jsonb;tokens jsonb;o gridex_metering_method_changes.origins%rowtype;BEGIN
 IF gridex_metering_method_changes.require_recovery_message_v1(NEW,NEW.created_by,'prepare') IS NOT NULL THEN RETURN NEW;END IF;
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.raw_payload IS NULL THEN RETURN NEW;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(NEW.raw_payload);w:=gridex_metering_method_changes.wire_v1(NEW.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z09') OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}' IN(SELECT value->>'reason' FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()))) THEN RETURN NEW;END IF;
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=NEW.company_id AND intent_id=NEW.intent_id;
 IF o.event_id IS NULL AND NEW.environment='test' AND NEW.direction='outbound' AND NEW.message_standard='edifact' AND NEW.message_family='PRODAT' AND NEW.message_code='Z09' THEN
  positive:=nullif(NEW.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId','')::uuid;
  negative:=nullif(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId','')::uuid;
  IF positive IS NOT NULL AND negative IS NOT NULL THEN RAISE EXCEPTION 'metering_method_change_fixture_source_ambiguous';END IF;
  IF positive IS NOT NULL OR negative IS NOT NULL THEN
   q:=CASE WHEN positive IS NOT NULL THEN gridex_negative_fixtures.prepared_positive_fixture_v1(NEW.company_id,positive,NEW.raw_payload,NEW.created_by) ELSE gridex_negative_fixtures.prepared_negative_fixture_v1(NEW.company_id,negative,NEW.raw_payload,NEW.created_by) END;
   IF gridex_metering_method_changes.fixture_qualification_v1(q,NEW.company_id,positive IS NOT NULL) IS NOT TRUE THEN RAISE EXCEPTION 'metering_method_change_prepared_test_original_required';END IF;
   RETURN NEW; -- Same normal fixture consumption seals this exact original; no desired-change receipt.
  END IF;
 END IF;
 IF w IS NULL OR o.event_id IS NULL OR o.actor_user_id IS DISTINCT FROM NEW.created_by OR NEW.source_operation_id IS DISTINCT FROM o.event_id::text THEN RAISE EXCEPTION 'authentic_metering_method_change_origin_required';END IF;
 RETURN NEW;
END$$;

--
-- Name: require_recovery_message_v1(public.ediel_messages, uuid, text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.require_recovery_message_v1(m public.ediel_messages, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE b jsonb;q jsonb;o gridex_received_sources.prodat_recovery_origins%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;w jsonb;
 op uuid;prior gridex_metering_method_changes.recovery_receipts%rowtype;
BEGIN
 SELECT id INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id::text=m.source_operation_id AND company_id=m.company_id AND kind IN('contrl_correction','aperak_correction');
 IF op IS NULL THEN RETURN NULL;END IF;
 b:=gridex_metering_method_changes.recovery_source_v1(m.company_id,op,actor,phase);
 IF b IS NULL THEN RETURN NULL;END IF;
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'metering_method_recovery_current_source_held';END IF;
 SELECT * INTO o FROM gridex_received_sources.prodat_recovery_origins WHERE operation_id=op AND company_id=m.company_id FOR SHARE;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id AND company_id=m.company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=m.outbound_request_id AND company_id=m.company_id FOR SHARE;
 w:=gridex_metering_method_changes.wire_v1(m.raw_payload);
 IF o.operation_id IS NULL OR i.id IS NULL OR r.id IS NULL OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id
  OR m.original_message_id::text IS DISTINCT FROM b->>'originalMessageId' OR m.customer_id IS DISTINCT FROM (b->>'customerId')::uuid
  OR m.site_id IS DISTINCT FROM (b->>'siteId')::uuid OR m.metering_point_id IS DISTINCT FROM (b->>'meteringPointId')::uuid
  OR m.environment IS DISTINCT FROM b->>'environment' OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' OR m.created_by IS DISTINCT FROM o.actor_user_id
  OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM b->>'correctedPayloadHash'
  OR i.operation_id IS DISTINCT FROM op OR i.direction IS DISTINCT FROM m.direction OR i.message_family IS DISTINCT FROM m.message_family OR i.message_code IS DISTINCT FROM m.message_code
  OR i.validation_status IS DISTINCT FROM 'validated' OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb
  OR i.customer_id IS DISTINCT FROM m.customer_id OR i.customer_site_id IS DISTINCT FROM m.site_id
  OR i.environment IS DISTINCT FROM m.environment OR i.communication_route_id IS DISTINCT FROM m.communication_route_id OR i.route_profile_id IS DISTINCT FROM m.route_profile_id
  OR i.application_reference IS DISTINCT FROM '23-DDQ-PRODAT' OR i.interchange_reference IS DISTINCT FROM w->>'interchange'
  OR i.message_reference IS DISTINCT FROM w->>'message' OR i.transaction_reference IS DISTINCT FROM w#>>'{object,li}'
  OR i.sender_ediel_id IS DISTINCT FROM w->>'transportSender' OR i.receiver_ediel_id IS DISTINCT FROM w->>'transportReceiver'
  OR i.sender_subaddress IS DISTINCT FROM w->>'senderSubaddress' OR i.receiver_subaddress IS DISTINCT FROM w->>'receiverSubaddress'
  OR m.sender_ediel_id IS DISTINCT FROM i.sender_ediel_id OR m.receiver_ediel_id IS DISTINCT FROM i.receiver_ediel_id
  OR m.interchange_reference IS DISTINCT FROM i.interchange_reference OR m.transaction_reference IS DISTINCT FROM i.transaction_reference
  OR r.source_type IS DISTINCT FROM 'manual' OR r.request_type IS DISTINCT FROM 'customer_masterdata' OR r.source_id::text IS DISTINCT FROM i.id::text
  OR r.operation_id IS DISTINCT FROM op OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id
  OR r.metering_point_id IS DISTINCT FROM m.metering_point_id OR r.communication_route_id IS DISTINCT FROM m.communication_route_id
  OR r.payload->>'environment' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'metering_method_recovery_owned_carrier_required';END IF;
 SELECT * INTO prior FROM gridex_metering_method_changes.recovery_receipts WHERE operation_id=op FOR SHARE;
 IF prior.operation_id IS NOT NULL AND(prior.message_id IS DISTINCT FROM m.id OR prior.basis IS DISTINCT FROM b OR prior.payload_hash IS DISTINCT FROM b->>'correctedPayloadHash'
  OR prior.message_scope IS DISTINCT FROM gridex_requested_method_watches.message_scope_v1(m)) THEN RAISE EXCEPTION 'metering_method_recovery_bound_carrier_changed';END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(m.company_id,actor,phase);
 RETURN b;
END$$;

--
-- Name: require_source_before_requested_changes_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.require_source_before_requested_changes_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE m public.ediel_messages%rowtype;
o gridex_metering_method_changes.origins%rowtype;
b jsonb;
w jsonb;
tokens jsonb;q jsonb;positive boolean;negative boolean;
r public.outbound_requests%rowtype;i public.ediel_message_intents%rowtype;

BEGIN SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id
  AND id=p_message_id FOR SHARE;
tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
IF gridex_metering_method_changes.require_recovery_message_v1(m,p_actor_user_id,'send') IS NOT NULL THEN RETURN;END IF;
PERFORM gridex_ai_processing.authorize_purpose_phase_v1(p_company_id,p_actor_user_id,'send',NULL);
SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=p_company_id AND message_id=p_message_id;
IF NOT FOUND AND EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z09')
 AND EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}' IN(SELECT value->>'reason' FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()))) THEN
 IF m.environment='test' AND m.direction='outbound' AND m.message_standard='edifact' AND m.message_family='PRODAT' AND m.message_code='Z09' THEN
  SELECT EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions f WHERE f.message_id=m.id AND f.company_id=p_company_id),EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions f WHERE f.message_id=m.id AND f.company_id=p_company_id) INTO positive,negative;
  IF positive AND negative THEN RAISE EXCEPTION 'metering_method_change_fixture_source_ambiguous';END IF;
  IF positive OR negative THEN
   q:=CASE WHEN positive THEN gridex_negative_fixtures.require_positive_message_v1(p_company_id,m.id,'Z09') ELSE gridex_negative_fixtures.require_negative_message_v1(p_company_id,m.id,'Z09') END;
   IF gridex_metering_method_changes.fixture_qualification_v1(q,p_company_id,positive) IS NOT TRUE THEN RAISE EXCEPTION 'metering_method_change_current_test_original_required';END IF;
   RETURN; -- Actual live source/run/role/step/expiry/revision checks; never business authority.
  END IF;
 END IF;

END IF;
w:=gridex_metering_method_changes.wire_v1(m.raw_payload);
IF w IS NULL
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM'
  AND t#>>'{elements,1,0}'='Z09')
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV'
  AND t#>>'{elements,1,0}' IN(SELECT value->>'reason' FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()))) THEN RAISE EXCEPTION 'metering_method_change_physical_scope_required';
END IF;
IF w IS NULL
  OR w->>'code' IS DISTINCT FROM 'Z09'
  OR NOT EXISTS(SELECT FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()) pair WHERE pair.value->>'reason'=w#>>'{object,reason}') THEN RETURN;
END IF;

 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=p_company_id
  AND message_id=p_message_id;

 IF NOT FOUND THEN
 RAISE EXCEPTION 'authentic_metering_method_change_origin_required';
END IF;

 b:=gridex_metering_method_changes.context_v1(o.company_id,o.event_id,p_actor_user_id,'send');
SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id
  AND company_id=o.company_id FOR SHARE;
SELECT * INTO i FROM public.ediel_message_intents WHERE company_id=o.company_id AND id=o.intent_id FOR SHARE;
 IF i.id IS NULL OR gridex_metering_method_changes.intent_binding_v1(i) IS DISTINCT FROM o.intent_binding OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'metering_method_change_owned_intent_changed';END IF;
 IF gridex_metering_method_changes.request_binding_v1(r,o) IS NOT TRUE
  OR b IS DISTINCT FROM o.basis
  OR b->>'status' IS DISTINCT FROM 'authorized'
  OR gridex_metering_method_changes.message_binding_v1(m,o) IS NOT TRUE THEN RAISE EXCEPTION 'metering_method_change_current_source_held';
END IF;
END$$;

--
-- Name: revocation_lock_v1(); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM id FROM gridex_metering_method_changes.events WHERE id=NEW.event_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'method_revocation_event_required';END IF;RETURN NEW;
END$$;

--
-- Name: wire_before_complete_scope_v1(text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.wire_before_complete_scope_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);
v_token jsonb;
obj jsonb:='{}';
head jsonb:='{}';
characteristic text;
key text;

BEGIN IF tokens IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='UNB')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='BGM')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='UNH')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens) j WHERE j->>'tag'='LIN')<>1 THEN RETURN NULL;
END IF;

 FOR v_token IN SELECT j.value FROM jsonb_array_elements(tokens) AS j(value) LOOP
 IF v_token->>'tag'='BGM' THEN head:=head||jsonb_build_object('code',v_token#>>'{elements,1,0}');
ELSIF v_token->>'tag'='UNB' THEN head:=head||jsonb_build_object('application',v_token#>>'{elements,7,0}','interchange',v_token#>>'{elements,5,0}','transportSender',v_token#>>'{elements,2,0}','transportReceiver',v_token#>>'{elements,3,0}','senderSubaddress',nullif(v_token#>>'{elements,2,2}',''),'receiverSubaddress',nullif(v_token#>>'{elements,3,2}',''));
ELSIF v_token->>'tag'='UNH' THEN head:=head||jsonb_build_object('message',v_token#>>'{elements,1,0}');
ELSIF v_token->>'tag'='NAD'
  AND v_token#>>'{elements,1,0}' IN('FR','DO') THEN key:=CASE v_token#>>'{elements,1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
IF head?key
  OR v_token#>>'{elements,2,1}' IS DISTINCT FROM '160'
  OR v_token#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;
END IF;
head:=head||jsonb_build_object(key,v_token#>>'{elements,2,0}');

 ELSIF v_token->>'tag'='LIN' THEN obj:=obj||jsonb_build_object('point',v_token#>>'{elements,3,0}','agency',v_token#>>'{elements,3,3}');

 ELSIF v_token->>'tag'='CCI' THEN characteristic:=v_token#>>'{elements,2,0}';

 ELSIF v_token->>'tag'='CAV'
  AND characteristic='Z04' THEN IF obj?'method' THEN RETURN NULL;END IF;obj:=obj||jsonb_build_object('method',v_token#>>'{elements,1,0}');
 ELSIF v_token->>'tag'='CAV'
  AND characteristic='Z13' THEN IF obj?'reason' THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object('reason',v_token#>>'{elements,1,0}');

 ELSIF v_token->>'tag'='RFF'
  AND v_token#>>'{elements,1,0}' IN('LI','Z05') THEN key:=CASE v_token#>>'{elements,1,0}' WHEN 'LI' THEN 'li' ELSE 'gridArea' END;
IF obj?key THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object(key,v_token#>>'{elements,1,1}');

 ELSIF v_token->>'tag'='DTM'
  AND v_token#>>'{elements,1,0}'='157' THEN IF obj?'effective'
  OR v_token#>>'{elements,1,2}' IS DISTINCT FROM '203' THEN RETURN NULL;
END IF;
obj:=obj||jsonb_build_object('effective',v_token#>>'{elements,1,1}');

 ELSIF v_token->>'tag'='NAD' AND v_token#>>'{elements,1,0}' IN('UD','IT') THEN RETURN NULL;

END IF;
END LOOP;

 RETURN head||jsonb_build_object('object',obj);
END$$;

--
-- Name: wire_brp_matches_v1(text, jsonb); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.wire_brp_matches_v1(raw text, b jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb;nad jsonb;n integer;first_line integer;BEGIN
 tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);SELECT min((t->>'index')::integer) INTO first_line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN';
 SELECT count(*),jsonb_agg(t)->0 INTO n,nad FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' AND (t->>'index')::integer>first_line;
 RETURN n=1 AND nad#>>'{elements,2,0}' IS NOT DISTINCT FROM b->>'brpEdielId' AND nad#>>'{elements,2,1}'='160' AND nad#>>'{elements,2,2}'='SVK' AND jsonb_array_length(nad#>'{elements,2}')=3;
END$$;

--
-- Name: wire_v1(text); Type: FUNCTION; Schema: gridex_metering_method_changes; Owner: -
--

CREATE FUNCTION gridex_metering_method_changes.wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w jsonb;tokens jsonb;unb jsonb;
BEGIN
 w:=gridex_metering_method_changes.wire_before_complete_scope_v1(raw);
 IF w IS NULL THEN RETURN NULL;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT') THEN RETURN NULL;END IF;
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';
 RETURN w||jsonb_build_object('testIndicator',coalesce(unb#>>'{elements,11,0}',''));
END$$;

--
-- Name: applied_source_v1(); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.applied_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e uuid;BEGIN FOR e IN SELECT b.expectation_id FROM gridex_method_expectations.bindings b JOIN public.ediel_business_expectations x ON x.id=b.expectation_id
 WHERE b.company_id=NEW.company_id AND b.environment=NEW.environment AND x.status IN('pending','timeout','manual_review')
  AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.applied_structural_method_objects_v1(NEW.company_id,NEW.source_message_id))own
   WHERE gridex_method_expectations.compatible_v1(b.original_basis,b.accepted_basis,own)) ORDER BY b.expectation_id LOOP
 PERFORM gridex_method_expectations.reconcile_v1(e,NEW.source_message_id);END LOOP;RETURN NEW;END $$;

--
-- Name: compatible_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.compatible_v1(original jsonb, accepted jsonb, own jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb:=original->'basis';method text:=nullif(own->>'measurementMethod','');day date;BEGIN
 IF original->>'authorized' IS DISTINCT FROM 'true' OR method IS NULL OR (b->>'subtype' IN('F','G')) IS NOT TRUE
  OR nullif(own->>'sourceReceivedAt','') IS NULL OR nullif(own->>'effectiveAt','') IS NULL
  OR nullif(own->>'customerId','') IS NULL OR nullif(own->>'meteringPointId','') IS NULL
  OR nullif(own->>'objectId','') IS NULL OR nullif(own->>'identityAgency','') IS NULL
  OR nullif(own->>'legalSupplier','') IS NULL OR nullif(own->>'legalNetwork','') IS NULL
  OR own->>'companyId' IS DISTINCT FROM b->>'companyId' OR own->>'environment' IS DISTINCT FROM b->>'environment'
  OR own->>'customerId' IS DISTINCT FROM b->>'customerId' OR own->>'meteringPointId' IS DISTINCT FROM b->>'meteringPointId'
  OR own->>'objectId' IS DISTINCT FROM b->>'pointId' OR own->>'identityAgency' IS DISTINCT FROM b->>'identityAgency'
  OR own->>'legalSupplier' IS DISTINCT FROM b->>'legalSenderId' OR own->>'legalNetwork' IS DISTINCT FROM b->>'legalReceiverId'
  OR (b->>'subtype'='F' AND method IS DISTINCT FROM b->>'method') THEN RETURN false;END IF;
 day:=to_date(original->>'validityDay','YYYYMMDD');
 -- Observation criterion, not a new business validity rule or exact-instant
 -- equality: preserve both original dates and never infer a missing method.
 RETURN (own->>'sourceReceivedAt')::timestamptz >= (accepted->>'observedAt')::timestamptz
  AND ((own->>'effectiveAt')::timestamptz AT TIME ZONE 'Etc/GMT-1')::date>=day;
END $$;

--
-- Name: mutate_before_requested_method_original_v1(jsonb); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.mutate_before_requested_method_original_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(i->>'companyId')::uuid;env text:=i->>'environment';actor uuid:=(i->>'actorUserId')::uuid;
 action text:=i->>'action';mid uuid:=(i->>'messageId')::uuid;lim integer:=greatest(1,least(coalesce((i->>'limit')::integer,100),500));
 m public.ediel_messages%rowtype;b gridex_method_expectations.bindings%rowtype;original jsonb;accepted jsonb;binding jsonb;plan jsonb;cfg jsonb;
 expected uuid;day date;due_day date;result jsonb;e uuid;BEGIN
 IF c IS NULL OR actor IS NULL OR env IS NULL OR env NOT IN('test','production') OR action IS NULL OR action NOT IN('register','read','observe','expire') THEN RAISE EXCEPTION 'ediel_method_expectation_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR (CASE WHEN action='read' THEN public.gridex_actor_has_company_permission(actor,c,'communication.read')
   WHEN action IN('register','expire') THEN (public.gridex_actor_has_company_permission(actor,c,'ediel.send') OR public.gridex_actor_has_company_permission(actor,c,'communication.send'))
   ELSE public.gridex_actor_has_company_permission(actor,c,'communication.write') END) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_method_expectation_actor_forbidden' USING ERRCODE='42501';END IF;
 IF action='register' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=c AND environment=env AND id=mid AND direction='outbound' FOR UPDATE;
  SELECT * INTO b FROM gridex_method_expectations.bindings WHERE source_message_id=mid;
  IF FOUND THEN
   IF b.company_id IS DISTINCT FROM c OR b.environment IS DISTINCT FROM env OR b.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_method_expectation_original_changed';END IF;
   PERFORM gridex_method_expectations.reconcile_v1(b.expectation_id);
   RETURN jsonb_build_array((SELECT to_jsonb(x) FROM public.ediel_business_expectations x WHERE x.id=b.expectation_id));
  END IF;
  original:=gridex_metering_method_changes.frozen_original_basis_v1(c,mid);
  IF original IS NULL THEN RETURN '[]'::jsonb;END IF;
  accepted:=gridex_ediel_transport.accepted_source_basis_v1(m);
  IF accepted IS NULL THEN RAISE EXCEPTION 'ediel_method_expectation_actual_accepted_send_required';END IF;
  SELECT a.binding INTO STRICT binding FROM gridex_ediel_transport.attempts a WHERE a.id=(accepted->>'attemptId')::uuid AND a.company_id=c AND a.environment=env AND a.message_id=mid AND accepted->>'lane'='generic_journal';
  PERFORM gridex_method_expectations.require_binding_v1(m,binding);plan:=binding->'meteringMethodExpectationPlan';
  SELECT * INTO b FROM gridex_method_expectations.bindings WHERE company_id=c AND environment=env AND event_id=(original->>'eventId')::uuid FOR SHARE;
  IF b.expectation_id IS NOT NULL AND EXISTS(SELECT FROM gridex_metering_method_changes.recovery_receipts own WHERE own.company_id=c AND own.message_id=mid AND own.event_id=b.event_id) THEN
   IF b.original_basis->'basis' IS DISTINCT FROM original->'basis' OR b.validity_day IS DISTINCT FROM to_date(original->>'validityDay','YYYYMMDD') THEN RAISE EXCEPTION 'metering_method_recovery_watch_event_changed';END IF;
   INSERT INTO gridex_method_expectations.recovery_carriers(message_id,company_id,environment,expectation_id,operation_id,payload_hash,accepted_basis)
    VALUES(mid,c,env,b.expectation_id,(original->>'recoveryOperationId')::uuid,original->>'sourcePayloadHash',accepted) ON CONFLICT(message_id) DO NOTHING;
   IF NOT EXISTS(SELECT FROM gridex_method_expectations.recovery_carriers own WHERE own.company_id=c AND own.message_id=mid AND own.expectation_id=b.expectation_id AND own.operation_id=(original->>'recoveryOperationId')::uuid AND own.payload_hash=original->>'sourcePayloadHash' AND own.accepted_basis=accepted) THEN RAISE EXCEPTION 'metering_method_recovery_watch_carrier_changed';END IF;
   PERFORM gridex_method_expectations.reconcile_v1(b.expectation_id);
   RETURN jsonb_build_array((SELECT to_jsonb(x) FROM public.ediel_business_expectations x WHERE x.id=b.expectation_id));
  END IF;
  SELECT projection INTO STRICT cfg FROM gridex_method_expectations.editions WHERE source_version='2c97fad0987131bb221c6bafb4c7c21183f6d7168a57486199b228cf1e452f31';
  day:=to_date(original->>'validityDay','YYYYMMDD');due_day:=day+(cfg->>'offset')::integer;
  INSERT INTO public.ediel_business_expectations(company_id,environment,source_message_id,source_operation_id,expected_family,expected_code,expected_subtype,due_at,metadata)
   VALUES(c,env,mid,original->>'eventId',cfg->>'expectedFamily',cfg->>'expectedCode',NULL,((due_day+1)::timestamp AT TIME ZONE 'Europe/Stockholm'),
    jsonb_build_object('timerRuleId',cfg->>'ruleId','timerKind',cfg->>'timerKind','anchorType',cfg->>'anchor','validityDay',day,'dueDay',due_day,
     'actualAcceptedAt',accepted->>'observedAt','remoteReceiptKnown',false,'automaticResendAllowed',false,'authorizesMarketEffects',false,
     'observationCriterion','same_applied_own_Z06_explicit_method_customer_point_agency_parties_and_not_before_validity_day','preparedPolicy',plan->'policy')) RETURNING id INTO expected;
  INSERT INTO gridex_method_expectations.bindings(expectation_id,company_id,environment,source_message_id,event_id,source_payload_hash,source_version,original_basis,plan,accepted_basis,accepted_at,validity_day,due_day)
   VALUES(expected,c,env,mid,(original->>'eventId')::uuid,original->>'sourcePayloadHash','2c97fad0987131bb221c6bafb4c7c21183f6d7168a57486199b228cf1e452f31',original,plan,accepted,(accepted->>'observedAt')::timestamptz,day,due_day);
  PERFORM gridex_method_expectations.reconcile_v1(expected);
  RETURN jsonb_build_array((SELECT to_jsonb(x) FROM public.ediel_business_expectations x WHERE x.id=expected));
 END IF;
 IF action='observe' THEN
  PERFORM observed_source.id FROM public.ediel_messages observed_source WHERE observed_source.id=mid AND observed_source.company_id=c AND observed_source.environment=env AND observed_source.direction='inbound';
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_method_expectation_observed_source_scope_required';END IF;
 END IF;
 FOR e IN SELECT owned.expectation_id FROM gridex_method_expectations.bindings owned JOIN public.ediel_business_expectations x ON x.id=owned.expectation_id
  WHERE owned.company_id=c AND owned.environment=env AND (action='observe' OR mid IS NULL OR (owned.source_message_id=mid OR EXISTS(SELECT FROM gridex_method_expectations.recovery_carriers alias WHERE alias.company_id=c AND alias.environment=env AND alias.message_id=mid AND alias.expectation_id=owned.expectation_id)))
   AND (action IN('read','observe') OR x.status='pending' AND (clock_timestamp() AT TIME ZONE 'Europe/Stockholm')::date>owned.due_day)
  ORDER BY owned.expectation_id LIMIT lim LOOP
  IF action<>'read' THEN PERFORM gridex_method_expectations.reconcile_v1(e,CASE WHEN action='observe' THEN mid ELSE NULL END);END IF;
  IF action='expire' THEN UPDATE public.ediel_business_expectations x SET status='manual_review',updated_at=clock_timestamp(),
   metadata=metadata||jsonb_build_object('expiredAt',clock_timestamp(),'automaticResendAllowed',false,'authorizesMarketEffects',false)
   FROM gridex_method_expectations.bindings owned WHERE x.id=e AND owned.expectation_id=x.id AND x.status='pending' AND (clock_timestamp() AT TIME ZONE 'Europe/Stockholm')::date>owned.due_day;END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at,x.id),'[]') INTO result FROM (SELECT x.* FROM public.ediel_business_expectations x JOIN gridex_method_expectations.bindings owned ON owned.expectation_id=x.id
  WHERE owned.company_id=c AND owned.environment=env AND (action='observe' OR mid IS NULL OR (owned.source_message_id=mid OR EXISTS(SELECT FROM gridex_method_expectations.recovery_carriers alias WHERE alias.company_id=c AND alias.environment=env AND alias.message_id=mid AND alias.expectation_id=owned.expectation_id))) ORDER BY x.created_at,x.id LIMIT lim)x;
 RETURN result;
END $$;

--
-- Name: mutate_v1(jsonb); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.mutate_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF i->>'action'='register' AND EXISTS(SELECT FROM gridex_requested_changes.origins o WHERE o.company_id=(i->>'companyId')::uuid AND o.message_id=(i->>'messageId')::uuid AND o.basis->>'variant' IN('F','G'))
  AND gridex_metering_method_changes.frozen_original_basis_v1((i->>'companyId')::uuid,(i->>'messageId')::uuid) IS NULL THEN RAISE EXCEPTION 'ediel_method_expectation_requested_original_required';END IF;
 RETURN gridex_method_expectations.mutate_before_requested_method_original_v1(i);
END $$;

--
-- Name: reconcile_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.reconcile_v1(expected uuid, source_filter uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_method_expectations.bindings%rowtype;e public.ediel_business_expectations%rowtype;
 src record;own jsonb;matches jsonb;other public.ediel_messages%rowtype;original jsonb;accepted jsonb;compatible_count integer;seen_events text[];BEGIN
 SELECT * INTO b FROM gridex_method_expectations.bindings WHERE expectation_id=expected;
 IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO e FROM public.ediel_business_expectations WHERE id=expected AND company_id=b.company_id AND environment=b.environment FOR UPDATE;
 IF e.id IS NULL OR e.status NOT IN('pending','timeout','manual_review') THEN RETURN;END IF;
 FOR src IN SELECT r.source_message_id FROM(SELECT source_message_id,company_id,environment,applied_at FROM gridex_received_sources.structural_apply_receipts UNION ALL SELECT source_message_id,company_id,environment,applied_at FROM gridex_received_sources.structural_object_apply_receipts)r
  WHERE r.company_id=b.company_id AND r.environment=b.environment AND (source_filter IS NULL OR r.source_message_id=source_filter) GROUP BY r.source_message_id ORDER BY min(r.applied_at),r.source_message_id LOOP
  SELECT coalesce(jsonb_agg(o),'[]'::jsonb) INTO matches FROM jsonb_array_elements(gridex_received_sources.applied_structural_method_objects_v1(b.company_id,src.source_message_id))o
   WHERE gridex_method_expectations.compatible_v1(b.original_basis,b.accepted_basis,o);
  IF jsonb_array_length(matches)<>1 THEN CONTINUE;END IF;own:=matches->0;compatible_count:=0;seen_events:='{}'::text[];
  -- Include accepted originals not yet registered, so late registration cannot
  -- pick the newest event or borrow one Z06 for multiple compatible requests.
  FOR other IN SELECT m.* FROM public.ediel_messages m WHERE m.company_id=b.company_id AND m.environment=b.environment
   AND (EXISTS(SELECT FROM gridex_metering_method_changes.desired_change_receipts r WHERE r.company_id=b.company_id AND r.environment=b.environment AND r.message_id=m.id)
    OR EXISTS(SELECT FROM gridex_requested_changes.origins r WHERE r.company_id=b.company_id AND r.message_id=m.id AND r.basis->>'variant' IN('F','G')) OR EXISTS(SELECT FROM gridex_metering_method_changes.recovery_receipts r WHERE r.company_id=b.company_id AND r.environment=b.environment AND r.message_id=m.id))
    AND NOT EXISTS(SELECT FROM gridex_method_expectations.bindings x JOIN gridex_method_expectations.observations z ON z.expectation_id=x.expectation_id WHERE x.source_message_id=m.id)
   ORDER BY m.id LOOP
   original:=gridex_metering_method_changes.frozen_original_basis_v1(b.company_id,other.id);
   accepted:=gridex_ediel_transport.accepted_source_basis_v1(other);
   IF accepted IS NOT NULL AND gridex_method_expectations.compatible_v1(original,accepted,own) AND NOT(original->>'eventId'=ANY(seen_events)) THEN compatible_count:=compatible_count+1;seen_events:=array_append(seen_events,original->>'eventId');END IF;
  END LOOP;
  IF compatible_count<>1 THEN CONTINUE;END IF;
  INSERT INTO gridex_method_expectations.observations(expectation_id,source_message_id,source_payload_hash,own_object)
   VALUES(e.id,src.source_message_id,own->>'sourcePayloadHash',own);
  UPDATE public.ediel_business_expectations SET status='fulfilled',fulfilled_by_message_id=src.source_message_id,updated_at=clock_timestamp(),
   metadata=metadata||jsonb_build_object('resolvedBy','observed_applied_own_Z06_method','observedMethod',own->>'measurementMethod',
    'sourceReceivedAt',own->>'sourceReceivedAt','effectiveAt',own->>'effectiveAt','appliedAt',own->>'appliedAt',
    'receivedAfterDueDay',((own->>'sourceReceivedAt')::timestamptz AT TIME ZONE 'Europe/Stockholm')::date>b.due_day,
    'authorizesMarketEffects',false,'authorizesReadingAcceptance',false,'automaticResendAllowed',false) WHERE id=e.id;
  RETURN;
 END LOOP;
END $$;

--
-- Name: require_binding_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_method_expectations; Owner: -
--

CREATE FUNCTION gridex_method_expectations.require_binding_v1(m public.ediel_messages, binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE frozen jsonb;cfg jsonb;plan jsonb;admission jsonb;wire jsonb;day date;BEGIN
 IF gridex_metering_method_changes.certification_basis_v1(m) IS NOT NULL THEN
  IF binding->'meteringMethodExpectationPlan' IS NOT NULL AND binding->'meteringMethodExpectationPlan'<>'null'::jsonb
   THEN RAISE EXCEPTION 'ediel_method_expectation_certification_watch_not_applicable';END IF;
  RETURN binding;
 END IF;
 wire:=gridex_metering_method_changes.wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'code' IS DISTINCT FROM 'Z09' OR NOT EXISTS(
  SELECT FROM jsonb_each(gridex_metering_method_changes.canonical_tuple_projection_v1()) p WHERE p.value->>'reason'=wire#>>'{object,reason}') THEN
  IF binding->'meteringMethodExpectationPlan' IS NOT NULL AND binding->'meteringMethodExpectationPlan'<>'null'::jsonb THEN RAISE EXCEPTION 'ediel_method_expectation_not_applicable';END IF;RETURN binding;
 END IF;
 frozen:=gridex_metering_method_changes.frozen_original_basis_v1(m.company_id,m.id);
 IF frozen IS NULL OR frozen->>'authorized' IS DISTINCT FROM 'true' OR frozen->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR frozen#>>'{basis,environment}' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'ediel_method_expectation_original_required';END IF;
 SELECT projection INTO STRICT cfg FROM gridex_method_expectations.editions WHERE source_version='2c97fad0987131bb221c6bafb4c7c21183f6d7168a57486199b228cf1e452f31';
 plan:=binding->'meteringMethodExpectationPlan';admission:=binding->'admissionDecision';
 BEGIN day:=to_date(frozen->>'validityDay','YYYYMMDD');EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'ediel_method_expectation_validity_day_invalid';END;
 IF to_char(day,'YYYYMMDD') IS DISTINCT FROM frozen->>'validityDay' OR extract(year FROM day)<=0
  OR jsonb_typeof(plan) IS DISTINCT FROM 'object' OR plan-ARRAY['sourceSubtype','validityDay','policy'] IS DISTINCT FROM cfg
  OR plan->>'sourceSubtype' IS DISTINCT FROM frozen#>>'{basis,subtype}' OR plan->>'validityDay' IS DISTINCT FROM day::text
  OR jsonb_typeof(admission) IS DISTINCT FROM 'object' OR admission->>'version' IS DISTINCT FROM '1'
  OR admission->>'family' IS DISTINCT FROM 'PRODAT' OR admission->>'code' IS DISTINCT FROM 'Z09'
  OR plan->'policy' IS DISTINCT FROM jsonb_build_object('guideRevision',admission#>'{guide,guideRevision}','referenceDate',admission->'referenceDate','profileKey',admission->'profileKey','sourceTrace',admission->'sourceTrace')
 THEN RAISE EXCEPTION 'ediel_method_expectation_same_admission_required';END IF;
 RETURN binding;
END $$;

--
-- Name: assert_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.assert_actor_v1(actor uuid, company uuid, permission text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF actor IS NULL OR company IS NULL OR NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=company AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(actor,company,permission),false)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_actor_not_authorized' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: assert_prepare_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.assert_prepare_actor_v1(actor uuid, company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF actor IS NULL OR company IS NULL OR NOT EXISTS(SELECT FROM public.company_memberships x WHERE x.company_id=company AND x.user_id=actor AND x.status='active' AND x.is_active AND x.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles x WHERE x.id=actor AND x.user_status='active')
  OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,company,'communication.write'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,company,'ediel_testing.write'),false))
 THEN RAISE EXCEPTION 'ediel_fixture_prepare_actor_not_authorized' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: consume_negative_v1(); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.consume_negative_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w gridex_negative_fixtures.negative_prepared_witnesses%rowtype;f gridex_negative_fixtures.originals%rowtype;r public.ediel_test_runs%rowtype;prior gridex_negative_fixtures.negative_prepared_consumptions%rowtype;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS NULL THEN RETURN NEW;END IF;
 SELECT * INTO w FROM gridex_negative_fixtures.negative_prepared_witnesses WHERE id=(NEW.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId')::uuid FOR UPDATE;
 IF w.id IS NULL THEN RAISE EXCEPTION 'ediel_negative_fixture_witness_required';END IF;
 SELECT * INTO STRICT f FROM gridex_negative_fixtures.originals WHERE id=w.registration_id FOR SHARE;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
 IF NEW.company_id IS DISTINCT FROM w.company_id OR NEW.environment IS DISTINCT FROM 'test' OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_standard IS DISTINCT FROM 'edifact' OR NEW.raw_payload IS DISTINCT FROM f.original_wire THEN RAISE EXCEPTION 'ediel_negative_fixture_message_scope_invalid';END IF;
 SELECT * INTO prior FROM gridex_negative_fixtures.negative_prepared_consumptions WHERE registration_id=f.id;
 IF FOUND THEN IF prior.message_id IS DISTINCT FROM NEW.id OR prior.witness_id IS DISTINCT FROM w.id THEN RAISE EXCEPTION 'ediel_negative_fixture_original_already_consumed';END IF;RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND nullif(OLD.raw_payload,'') IS NOT NULL THEN RAISE EXCEPTION 'ediel_negative_fixture_historical_original_unavailable';END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=w.run_id AND company_id=w.company_id AND environment='test' AND status IN('draft','running') FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(w.actor_user_id,w.company_id);
 IF r.role_code IS DISTINCT FROM f.role_code OR r.test_case_code IS DISTINCT FROM f.case_code OR r.test_suite IS DISTINCT FROM f.suite OR r.approval_version IS DISTINCT FROM f.revision OR f.valid_until<=clock_timestamp() THEN RAISE EXCEPTION 'ediel_negative_fixture_current_run_required';END IF;
 -- Test provenance does not waive the normal canonical owner witness. Both
 -- private consumptions occur in the same actual INSERT transaction.
 PERFORM gridex_ediel_outbound_owner.require_v1(NEW.company_id,NEW.id);
 INSERT INTO gridex_negative_fixtures.negative_prepared_consumptions VALUES(w.id,f.id,NEW.id,w.company_id,w.wire_sha256);
 RETURN NEW;
END $$;

