--
-- Name: decode_latin1_v1(bytea); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.decode_latin1_v1(original bytea) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT string_agg(chr(get_byte(original,i)),'' ORDER BY i) FROM generate_series(0,octet_length(original)-1) i
$$;

