-- Name: prepared_positive_fixture_v1(uuid, uuid, text, uuid); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.prepared_positive_fixture_v1(p_company uuid, p_witness uuid, p_raw text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w gridex_negative_fixtures.positive_witnesses%rowtype;q jsonb;
BEGIN
 SELECT * INTO w FROM gridex_negative_fixtures.positive_witnesses WHERE id=p_witness AND company_id=p_company AND actor_user_id=p_actor FOR SHARE;
 IF w.id IS NULL OR EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.witness_id=w.id) THEN RAISE EXCEPTION 'ediel_positive_fixture_prepared_original_required';END IF;
 q:=gridex_negative_fixtures.read_positive_v1(jsonb_build_object('companyId',p_company,'runId',w.run_id,'stepNo',w.step_no,'actorUserId',p_actor,'rawPayload',p_raw));
 IF q IS NULL OR q IS DISTINCT FROM w.qualification THEN RAISE EXCEPTION 'ediel_positive_fixture_prepared_original_required';END IF;RETURN q;
END $$;

--
-- Name: publish_positive_v1(jsonb, bytea, text); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.publish_positive_v1(p_context jsonb, p_original bytea, p_publisher text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_test_runs%rowtype;prior gridex_negative_fixtures.positive_originals%rowtype;wire text;hash text;result uuid;tokens jsonb;
BEGIN
 IF p_publisher IS DISTINCT FROM 'gridex_ediel_fixture_authority_owner' OR p_original IS NULL OR octet_length(p_original) NOT BETWEEN 1 AND 10485760
  OR p_context->>'expectedOutcome' IS DISTINCT FROM 'positive' OR p_context->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb
  OR nullif(p_context->>'sourceReference','') IS NULL OR nullif(p_context->>'ownerDecisionReference','') IS NULL OR nullif(p_context->>'testReceiverEdielId','') IS NULL
 THEN RAISE EXCEPTION 'ediel_positive_fixture_qualified_original_required';END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=(p_context->>'runId')::uuid AND company_id=(p_context->>'companyId')::uuid AND environment='test' AND status IN('draft','running') FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_actor_v1((p_context->>'actorUserId')::uuid,r.company_id,'communication.write');
 IF r.role_code IS DISTINCT FROM p_context->>'roleCode' OR r.test_case_code IS DISTINCT FROM p_context->>'caseCode' OR r.test_suite IS DISTINCT FROM p_context->>'suite'
  OR r.approval_version IS DISTINCT FROM p_context->>'revision' OR (p_context->>'stepNo')::integer<=0 OR (p_context->>'validUntil')::timestamptz<=clock_timestamp()
 THEN RAISE EXCEPTION 'ediel_positive_fixture_run_scope_mismatch';END IF;
 wire:=gridex_negative_fixtures.decode_latin1_v1(p_original);hash:=encode(sha256(p_original),'hex');tokens:=gridex_received_sources.wire_tokens_bounded_v1(wire,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB' AND t#>>'{elements,3,0}'=p_context->>'testReceiverEdielId' AND t#>>'{elements,11,0}'='1') THEN RAISE EXCEPTION 'ediel_positive_fixture_test_original_required';END IF;

 IF current_setting('transaction_isolation') NOT IN('read committed','read uncommitted')
 THEN RAISE EXCEPTION 'ediel_fixture_publisher_read_committed_required' USING ERRCODE='25000';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(r.id::text||'|'||((p_context->>'stepNo')::integer)::text||'|'||hash,0));
 IF EXISTS(SELECT FROM gridex_negative_fixtures.originals opposite WHERE opposite.company_id=r.company_id AND opposite.run_id=r.id
  AND opposite.step_no=(p_context->>'stepNo')::integer AND opposite.revision=r.approval_version AND opposite.wire_sha256=hash)
 THEN RAISE EXCEPTION 'ediel_positive_fixture_original_conflict';END IF;
 SELECT * INTO prior FROM gridex_negative_fixtures.positive_originals WHERE company_id=r.company_id AND run_id=r.id AND step_no=(p_context->>'stepNo')::integer AND revision=r.approval_version AND wire_sha256=hash;
 IF FOUND THEN
  IF prior.test_receiver_ediel_id IS DISTINCT FROM p_context->>'testReceiverEdielId' OR prior.source_reference IS DISTINCT FROM p_context->>'sourceReference'
   OR prior.owner_decision_reference IS DISTINCT FROM p_context->>'ownerDecisionReference' OR prior.valid_until IS DISTINCT FROM (p_context->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'ediel_positive_fixture_original_conflict';END IF;
  RETURN prior.id;
 END IF;
 INSERT INTO gridex_negative_fixtures.positive_originals(company_id,run_id,role_code,case_code,suite,revision,step_no,source_reference,owner_decision_reference,original_file_sha256,wire_sha256,original_wire,expected_outcome,expected_diagnostic_codes,test_receiver_ediel_id,valid_until)
 VALUES(r.company_id,r.id,r.role_code,r.test_case_code,r.test_suite,r.approval_version,(p_context->>'stepNo')::integer,p_context->>'sourceReference',p_context->>'ownerDecisionReference',hash,hash,wire,'positive','[]',p_context->>'testReceiverEdielId',(p_context->>'validUntil')::timestamptz) RETURNING id INTO result;
 RETURN result;
END $$;

--
-- Name: publish_v1(jsonb, bytea, text); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.publish_v1(p_context jsonb, p_original bytea, p_publisher text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_test_runs%rowtype;prior gridex_negative_fixtures.originals%rowtype;wire text;hash text;result uuid;diagnostics jsonb:=p_context->'expectedDiagnosticCodes';
BEGIN
 IF p_publisher IS DISTINCT FROM 'gridex_ediel_fixture_authority_owner' OR p_original IS NULL OR octet_length(p_original) NOT BETWEEN 1 AND 10485760
 OR jsonb_typeof(diagnostics) IS DISTINCT FROM 'array' OR jsonb_array_length(diagnostics) NOT BETWEEN 1 AND 256
 OR EXISTS(SELECT FROM jsonb_array_elements(diagnostics) d WHERE jsonb_typeof(d)<>'string' OR length(d#>>'{}') NOT BETWEEN 1 AND 128)
 OR p_context->>'expectedOutcome' IS DISTINCT FROM 'negative' OR nullif(p_context->>'sourceReference','') IS NULL OR nullif(p_context->>'ownerDecisionReference','') IS NULL
 THEN RAISE EXCEPTION 'ediel_negative_fixture_qualified_original_required';END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=(p_context->>'runId')::uuid AND company_id=(p_context->>'companyId')::uuid AND environment='test' FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_actor_v1((p_context->>'actorUserId')::uuid,r.company_id,'communication.write');
 IF r.role_code IS DISTINCT FROM p_context->>'roleCode' OR r.test_case_code IS DISTINCT FROM p_context->>'caseCode' OR r.test_suite IS DISTINCT FROM p_context->>'suite'
 OR r.approval_version IS DISTINCT FROM p_context->>'revision' OR (p_context->>'stepNo')::integer<=0 OR (p_context->>'validUntil')::timestamptz<=now()
 THEN RAISE EXCEPTION 'ediel_negative_fixture_run_scope_mismatch';END IF;
 wire:=gridex_negative_fixtures.decode_latin1_v1(p_original);hash:=encode(sha256(p_original),'hex');

 IF current_setting('transaction_isolation') NOT IN('read committed','read uncommitted')
 THEN RAISE EXCEPTION 'ediel_fixture_publisher_read_committed_required' USING ERRCODE='25000';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(r.id::text||'|'||((p_context->>'stepNo')::integer)::text||'|'||hash,0));
 IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_originals opposite WHERE opposite.company_id=r.company_id AND opposite.run_id=r.id
  AND opposite.step_no=(p_context->>'stepNo')::integer AND opposite.revision=r.approval_version AND opposite.wire_sha256=hash)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
 SELECT * INTO prior FROM gridex_negative_fixtures.originals WHERE company_id=r.company_id AND run_id=r.id AND step_no=(p_context->>'stepNo')::integer AND revision=r.approval_version AND wire_sha256=hash;
 IF FOUND THEN
  IF prior.expected_diagnostic_codes IS DISTINCT FROM diagnostics OR prior.test_receiver_ediel_id IS DISTINCT FROM p_context->>'testReceiverEdielId'
   OR prior.source_reference IS DISTINCT FROM p_context->>'sourceReference' OR prior.owner_decision_reference IS DISTINCT FROM p_context->>'ownerDecisionReference'
   OR prior.valid_until IS DISTINCT FROM (p_context->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
  RETURN prior.id;
 END IF;
 INSERT INTO gridex_negative_fixtures.originals(company_id,run_id,role_code,case_code,suite,revision,step_no,source_reference,owner_decision_reference,original_file_sha256,wire_sha256,original_wire,expected_outcome,expected_diagnostic_codes,test_receiver_ediel_id,valid_until)
 VALUES(r.company_id,r.id,r.role_code,r.test_case_code,r.test_suite,r.approval_version,(p_context->>'stepNo')::integer,p_context->>'sourceReference',p_context->>'ownerDecisionReference',hash,hash,wire,'negative',diagnostics,p_context->>'testReceiverEdielId',(p_context->>'validUntil')::timestamptz) RETURNING id INTO result;
 RETURN result;
END$$;

--
-- Name: read_negative_preparation_v1(jsonb); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.read_negative_preparation_v1(p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_test_runs%rowtype;m public.ediel_messages%rowtype;run_id uuid;step integer;company uuid:=(p_context->>'companyId')::uuid;wire text:=p_context->>'rawPayload';f gridex_negative_fixtures.originals%rowtype;tokens jsonb;receiver text;
BEGIN
 IF p_context->>'messageId' IS NOT NULL THEN RAISE EXCEPTION 'ediel_negative_fixture_draft_context_required';END IF;
 IF p_context->>'messageId' IS NOT NULL THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_context->>'messageId')::uuid AND company_id=company AND direction='outbound' AND environment='test' AND message_standard='edifact';
  SELECT l.test_run_id,l.step_no INTO STRICT run_id,step FROM public.ediel_test_run_messages l JOIN public.ediel_test_runs x ON x.id=l.test_run_id AND x.company_id=m.company_id AND x.environment='test' WHERE l.ediel_message_id=m.id;
  wire:=m.raw_payload;
 ELSE run_id:=(p_context->>'runId')::uuid;step:=(p_context->>'stepNo')::integer;END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=run_id AND company_id=company AND environment='test' AND status IN ('draft','running') FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1((p_context->>'actorUserId')::uuid,company);
 SELECT * INTO f FROM gridex_negative_fixtures.originals WHERE company_id=company AND originals.run_id=r.id AND step_no=step AND revision=r.approval_version
  -- Exact text equality to the bijectively decoded stored original is required.
  -- The server adapter additionally recomputes its actual Latin1 byte hash.
  AND role_code=r.role_code AND case_code=r.test_case_code AND suite=r.test_suite AND original_wire=wire AND valid_until>now();
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(wire,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB')<>1 THEN RETURN NULL;END IF;
 SELECT t#>>'{elements,3,0}' INTO receiver FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB';
 IF receiver IS DISTINCT FROM f.test_receiver_ediel_id THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('kind','source_qualified_negative_fixture','version',1,'authorizesBusinessEffect',false,'registrationId',f.id,'companyId',company,'runId',r.id,'roleCode',r.role_code,'caseCode',r.test_case_code,'suite',r.test_suite,'revision',r.approval_version,'stepNo',step,'wireSha256',f.wire_sha256,'originalFileSha256',f.original_file_sha256,'expectedOutcome','negative','expectedDiagnosticCodes',f.expected_diagnostic_codes,'testReceiverEdielId',receiver,'validUntil',f.valid_until,'sourceReference',f.source_reference,'ownerDecisionReference',f.owner_decision_reference);
END$$;

--
-- Name: read_positive_v1(jsonb); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.read_positive_v1(p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_test_runs%rowtype;f gridex_negative_fixtures.positive_originals%rowtype;wire text:=p_context->>'rawPayload';tokens jsonb;
BEGIN
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=(p_context->>'runId')::uuid AND company_id=(p_context->>'companyId')::uuid AND environment='test' AND status IN('draft','running') FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1((p_context->>'actorUserId')::uuid,r.company_id);
 SELECT * INTO f FROM gridex_negative_fixtures.positive_originals WHERE company_id=r.company_id AND run_id=r.id AND role_code=r.role_code AND case_code=r.test_case_code AND suite=r.test_suite AND revision=r.approval_version
  AND step_no=(p_context->>'stepNo')::integer AND original_wire=wire AND valid_until>clock_timestamp();
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_positive_fixture_original_conflict';END IF;
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(wire,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB' AND t#>>'{elements,3,0}'=f.test_receiver_ediel_id AND t#>>'{elements,11,0}'='1') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('kind','source_qualified_positive_fixture','version',1,'registrationId',f.id,'companyId',r.company_id,'runId',r.id,'roleCode',r.role_code,'caseCode',r.test_case_code,'suite',r.test_suite,'revision',r.approval_version,'stepNo',f.step_no,
  'wireSha256',f.wire_sha256,'originalFileSha256',f.original_file_sha256,'expectedOutcome','positive','expectedDiagnosticCodes','[]'::jsonb,'testReceiverEdielId',f.test_receiver_ediel_id,'validUntil',f.valid_until,'sourceReference',f.source_reference,'ownerDecisionReference',f.owner_decision_reference,'authorizesBusinessEffect',false);
END $$;

--
-- Name: read_v1(jsonb); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.read_v1(p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_test_runs%rowtype;m public.ediel_messages%rowtype;run_id uuid;step integer;company uuid:=(p_context->>'companyId')::uuid;wire text:=p_context->>'rawPayload';f gridex_negative_fixtures.originals%rowtype;tokens jsonb;receiver text;
BEGIN
 IF p_context->>'messageId' IS NOT NULL THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_context->>'messageId')::uuid AND company_id=company AND direction='outbound' AND environment='test' AND message_standard='edifact';
  IF NOT EXISTS(SELECT FROM public.ediel_test_run_messages l JOIN public.ediel_test_runs x ON x.id=l.test_run_id AND x.company_id=m.company_id AND x.environment='test' WHERE l.ediel_message_id=m.id) THEN RETURN NULL;END IF;
  SELECT l.test_run_id,l.step_no INTO STRICT run_id,step FROM public.ediel_test_run_messages l JOIN public.ediel_test_runs x ON x.id=l.test_run_id AND x.company_id=m.company_id AND x.environment='test' WHERE l.ediel_message_id=m.id;
  wire:=m.raw_payload;
 ELSE run_id:=(p_context->>'runId')::uuid;step:=(p_context->>'stepNo')::integer;END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=run_id AND company_id=company AND environment='test' AND status IN ('draft','running') FOR SHARE;
 PERFORM gridex_negative_fixtures.assert_actor_v1((p_context->>'actorUserId')::uuid,company,'communication.send');
 SELECT * INTO f FROM gridex_negative_fixtures.originals WHERE company_id=company AND originals.run_id=r.id AND step_no=step AND revision=r.approval_version
  -- Exact text equality to the bijectively decoded stored original is required.
  -- The server adapter additionally recomputes its actual Latin1 byte hash.
  AND role_code=r.role_code AND case_code=r.test_case_code AND suite=r.test_suite AND original_wire=wire AND valid_until>now();
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(wire,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB')<>1 THEN RETURN NULL;END IF;
 SELECT t#>>'{elements,3,0}' INTO receiver FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB';
 IF receiver IS DISTINCT FROM f.test_receiver_ediel_id THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('registrationId',f.id,'companyId',company,'runId',r.id,'roleCode',r.role_code,'caseCode',r.test_case_code,'suite',r.test_suite,'revision',r.approval_version,'stepNo',step,'wireSha256',f.wire_sha256,'originalFileSha256',f.original_file_sha256,'expectedOutcome','negative','expectedDiagnosticCodes',f.expected_diagnostic_codes,'testReceiverEdielId',receiver,'validUntil',f.valid_until,'sourceReference',f.source_reference,'ownerDecisionReference',f.owner_decision_reference);
END$$;

--
-- Name: require_negative_message_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.require_negative_message_v1(p_company uuid, p_message uuid, p_expected_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;f gridex_negative_fixtures.originals%rowtype;w gridex_negative_fixtures.negative_prepared_witnesses%rowtype;r public.ediel_test_runs%rowtype;tokens jsonb;code text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message AND company_id=p_company AND environment='test' AND direction='outbound' AND message_standard='edifact' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_negative_fixtures.negative_prepared_consumptions c JOIN gridex_negative_fixtures.negative_prepared_witnesses witness ON witness.id=c.witness_id WHERE c.message_id=m.id AND c.company_id=p_company FOR SHARE OF witness;
 IF w.id IS NULL OR m.execution_context_snapshot->>'sourceQualifiedNegativeFixtureWitnessId' IS DISTINCT FROM w.id::text THEN RAISE EXCEPTION 'ediel_negative_fixture_original_required';END IF;
 SELECT * INTO STRICT f FROM gridex_negative_fixtures.originals WHERE id=w.registration_id FOR SHARE;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_negative_fixture_original_conflict';END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=w.run_id AND company_id=p_company AND environment='test' AND status IN('draft','running') FOR SHARE;
 IF m.raw_payload IS DISTINCT FROM f.original_wire OR r.role_code IS DISTINCT FROM f.role_code OR r.test_case_code IS DISTINCT FROM f.case_code OR r.test_suite IS DISTINCT FROM f.suite OR r.approval_version IS DISTINCT FROM f.revision OR f.valid_until<=clock_timestamp() THEN RAISE EXCEPTION 'ediel_negative_fixture_current_run_required';END IF;
 IF (SELECT count(*) FROM public.ediel_test_run_messages l WHERE l.ediel_message_id=m.id)<>1 OR NOT EXISTS(SELECT FROM public.ediel_test_run_messages l WHERE l.ediel_message_id=m.id AND l.test_run_id=w.run_id AND l.step_no=w.step_no) THEN RAISE EXCEPTION 'ediel_negative_fixture_actual_run_link_required';END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(w.actor_user_id,p_company);PERFORM gridex_ediel_outbound_owner.require_v1(p_company,m.id);
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(m.raw_payload,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_negative_fixture_physical_message_required';END IF;
 SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 IF code IS DISTINCT FROM m.message_code OR (p_expected_code IS NOT NULL AND code IS DISTINCT FROM p_expected_code) THEN RAISE EXCEPTION 'ediel_negative_fixture_physical_message_required';END IF;
 RETURN w.qualification;
END $$;

--
-- Name: require_positive_message_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_negative_fixtures; Owner: -
--

CREATE FUNCTION gridex_negative_fixtures.require_positive_message_v1(p_company uuid, p_message uuid, p_expected_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;f gridex_negative_fixtures.positive_originals%rowtype;w gridex_negative_fixtures.positive_witnesses%rowtype;r public.ediel_test_runs%rowtype;tokens jsonb;code text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message AND company_id=p_company AND environment='test' AND direction='outbound' AND message_standard='edifact' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_negative_fixtures.positive_consumptions c JOIN gridex_negative_fixtures.positive_witnesses witness ON witness.id=c.witness_id WHERE c.message_id=m.id AND c.company_id=p_company FOR SHARE OF witness;
 IF w.id IS NULL OR m.execution_context_snapshot->>'sourceQualifiedPositiveFixtureWitnessId' IS DISTINCT FROM w.id::text THEN RAISE EXCEPTION 'ediel_positive_fixture_original_required';END IF;
 SELECT * INTO STRICT f FROM gridex_negative_fixtures.positive_originals WHERE id=w.registration_id FOR SHARE;
 IF EXISTS(SELECT FROM gridex_negative_fixtures.originals opposite WHERE opposite.company_id=f.company_id AND opposite.run_id=f.run_id
  AND opposite.step_no=f.step_no AND opposite.revision=f.revision AND opposite.wire_sha256=f.wire_sha256)
 THEN RAISE EXCEPTION 'ediel_positive_fixture_original_conflict';END IF;
 SELECT * INTO STRICT r FROM public.ediel_test_runs WHERE id=w.run_id AND company_id=p_company AND environment='test' AND status IN('draft','running') FOR SHARE;
 IF m.raw_payload IS DISTINCT FROM f.original_wire OR r.role_code IS DISTINCT FROM f.role_code OR r.test_case_code IS DISTINCT FROM f.case_code OR r.test_suite IS DISTINCT FROM f.suite OR r.approval_version IS DISTINCT FROM f.revision OR f.valid_until<=clock_timestamp() THEN RAISE EXCEPTION 'ediel_positive_fixture_current_run_required';END IF;
 IF (SELECT count(*) FROM public.ediel_test_run_messages l WHERE l.ediel_message_id=m.id)<>1 OR NOT EXISTS(SELECT FROM public.ediel_test_run_messages l WHERE l.ediel_message_id=m.id AND l.test_run_id=w.run_id AND l.step_no=w.step_no) THEN RAISE EXCEPTION 'ediel_positive_fixture_actual_run_link_required';END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(w.actor_user_id,p_company);PERFORM gridex_ediel_outbound_owner.require_v1(p_company,m.id);
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(m.raw_payload,999999);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_positive_fixture_physical_message_required';END IF;
 SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 IF code IS DISTINCT FROM m.message_code OR (p_expected_code IS NOT NULL AND code IS DISTINCT FROM p_expected_code) THEN RAISE EXCEPTION 'ediel_positive_fixture_physical_message_required';END IF;
 RETURN w.qualification;
END $$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.actor_v1(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 RETURN mode IN('archive','read','review') AND gridex_requested_changes.actor_v1(c,actor,CASE WHEN mode='review' THEN 'archive' ELSE mode END,'method_contract') IS TRUE
 AND (mode<>'review' OR gridex_requested_changes.scoped_permission_v1(c,actor,'ediel.network_registry.review') IS TRUE);
END$$;

--
-- Name: claims_v1(uuid, jsonb); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.claims_v1(c uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE network public.platform_market_actors%rowtype;identifier public.platform_actor_identifiers%rowtype;role public.platform_actor_roles%rowtype;own_scope jsonb;from_at timestamptz;until_at timestamptz;n int;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR nullif(p->>'networkActorId','') IS NULL OR (p->>'environment' IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'network_registry_claims_required';END IF;
 from_at:=(p->>'validFrom')::timestamptz;until_at:=(p->>'validUntil')::timestamptz;
 IF from_at IS NULL OR until_at IS NULL OR NOT isfinite(from_at) OR NOT isfinite(until_at) OR from_at>=until_at OR until_at<=now() THEN RAISE EXCEPTION 'network_registry_validity_required';END IF;
 own_scope:=gridex_ai_purpose_sources.legal_scope_v1(c,p->>'environment');
 LOCK TABLE public.platform_market_actors IN SHARE MODE;
 SELECT * INTO network FROM public.platform_market_actors WHERE id=(p->>'networkActorId')::uuid FOR SHARE;
 PERFORM id FROM public.platform_actor_identifiers WHERE actor_id=network.id ORDER BY id FOR SHARE;PERFORM id FROM public.platform_actor_roles WHERE actor_id=network.id ORDER BY id FOR SHARE;
 SELECT count(*) INTO n FROM public.platform_actor_identifiers WHERE actor_id=network.id AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND (valid_from IS NULL OR valid_from<=current_date) AND (valid_to IS NULL OR valid_to>=current_date);
 SELECT * INTO identifier FROM public.platform_actor_identifiers WHERE actor_id=network.id AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND (valid_from IS NULL OR valid_from<=current_date) AND (valid_to IS NULL OR valid_to>=current_date) ORDER BY id LIMIT 1;
 SELECT * INTO role FROM public.platform_actor_roles WHERE actor_id=network.id AND actor_role='grid_owner' AND is_active ORDER BY id LIMIT 1;
 IF network.id IS NULL OR network.status IS DISTINCT FROM 'active' OR n<>1 OR coalesce(identifier.identifier_value,'')!~'^[0-9]{5}$' OR role.id IS NULL OR nullif(network.name,'') IS NULL THEN RAISE EXCEPTION 'network_registry_current_verified_network_scope_required';END IF;
 RETURN own_scope||jsonb_build_object('networkActorId',network.id,'networkEdielId',identifier.identifier_value,'networkName',network.name,'identifierHash',encode(sha256(convert_to((to_jsonb(identifier)-ARRAY['updated_at','created_at'])::text,'UTF8')),'hex'),'roleHash',encode(sha256(convert_to((to_jsonb(role)-ARRAY['updated_at','created_at'])::text,'UTF8')),'hex'),'validFrom',from_at,'validUntil',until_at,'sourceClass','authenticated_original_network_registry');
END$_$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_network_registry_sources; Owner: -
--

CREATE TABLE gridex_network_registry_sources.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    network_actor_id uuid NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_claims_hash_check CHECK ((claims_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_network_registry_sources.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: current_v1(gridex_network_registry_sources.artifacts); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.current_v1(a gridex_network_registry_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_network_registry_sources.origins%rowtype;r gridex_network_registry_sources.reviews%rowtype;receipt jsonb;actual jsonb;
BEGIN
 SELECT * INTO o FROM gridex_network_registry_sources.origins WHERE artifact_id=a.id AND company_id=a.company_id FOR SHARE;SELECT * INTO r FROM gridex_network_registry_sources.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=a.company_id FOR SHARE;
 IF o.id IS NULL OR o.environment IS DISTINCT FROM a.environment OR o.network_actor_id IS DISTINCT FROM a.network_actor_id OR o.registry_version IS DISTINCT FROM a.source_version OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_network_registry_sources.actor_v1(a.company_id,r.reviewer_user_id,'review') IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash OR EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=o.id) THEN RETURN NULL;END IF;
 actual:=gridex_network_registry_sources.claims_v1(a.company_id,a.claims);receipt:=gridex_network_registry_sources.receipt_current_v1(a);
 IF actual IS DISTINCT FROM a.claims OR receipt IS NULL OR r.clause IS DISTINCT FROM receipt->'clause' OR now()<(a.claims->>'validFrom')::timestamptz OR now()>=(a.claims->>'validUntil')::timestamptz THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('companyId',a.company_id,'environment',a.environment,'networkActorId',a.network_actor_id,'networkEdielId',a.claims->>'networkEdielId','registryVersionId',o.id,'registryVersion',o.registry_version,'sourceReference',a.source_reference,'sourceSha256',a.source_hash,'claimsHash',a.claims_hash,'artifactId',a.id,'ownerRegistryId',receipt->>'ownerRegistryId','ownerRegistryVersion',receipt->>'ownerRegistryVersion','validFrom',a.claims->>'validFrom','validUntil',a.claims->>'validUntil');
EXCEPTION WHEN raise_exception THEN RETURN NULL;
END$$;

--
-- Name: network_for_company_v1(uuid, text, text); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.network_for_company_v1(c uuid, network_id text, env text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a gridex_network_registry_sources.artifacts%rowtype;basis jsonb;n int;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE gridex_network_registry_sources.artifacts,gridex_network_registry_sources.reviews,gridex_network_registry_sources.origins,gridex_network_registry_sources.issuer_keys,gridex_network_registry_sources.representations,gridex_network_registry_sources.revocations IN SHARE MODE;
 IF (env IN('test','production')) IS NOT TRUE OR coalesce(network_id,'')!~'^[0-9]{5}$' THEN RAISE EXCEPTION 'network_registry_company_environment_required';END IF;
 SELECT count(*) INTO n FROM gridex_network_registry_sources.origins version JOIN gridex_network_registry_sources.artifacts artifact ON artifact.id=version.artifact_id WHERE version.company_id=c AND version.environment=env AND artifact.claims->>'networkEdielId'=network_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id);
 IF n<>1 THEN RETURN jsonb_build_object('status','held','blocker','ai_bi_network_registry_version_unqualified');END IF;
 SELECT artifact.* INTO a FROM gridex_network_registry_sources.origins version JOIN gridex_network_registry_sources.artifacts artifact ON artifact.id=version.artifact_id WHERE version.company_id=c AND version.environment=env AND artifact.claims->>'networkEdielId'=network_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id) FOR SHARE OF artifact;
 basis:=gridex_network_registry_sources.current_v1(a);IF basis IS NULL THEN RETURN jsonb_build_object('status','held','blocker','ai_bi_network_registry_current_source_unqualified');END IF;RETURN jsonb_build_object('status','authorized','basis',basis);
END$_$;

--
-- Name: receipt_current_v1(gridex_network_registry_sources.artifacts); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.receipt_current_v1(a gridex_network_registry_sources.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_network_registry_sources.issuer_keys%rowtype;g gridex_network_registry_sources.representations%rowtype;r jsonb:=a.issuer_receipt;raw bytea;p jsonb;issued timestamptz;expires timestamptz;
BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 65536 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_network_registry_sources.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment AND network_actor_id=(a.claims->>'networkActorId')::uuid FOR SHARE;
 SELECT * INTO g FROM gridex_network_registry_sources.representations WHERE id=(r->>'representationId')::uuid AND company_id=a.company_id AND environment=a.environment AND issuer_key_id=k.id AND network_actor_id=(a.claims->>'networkActorId')::uuid FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR EXISTS(SELECT FROM gridex_network_registry_sources.revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id OR target_kind='artifact' AND target_id=a.id) THEN RETURN NULL;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN NULL;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 IF p->>'format' IS DISTINCT FROM 'ediel_network_registry_receipt_v1' OR nullif(p->>'receiptId','') IS NULL OR p->'claims' IS DISTINCT FROM a.claims OR p->>'sourceHash' IS DISTINCT FROM a.source_hash OR p->>'sourceReference' IS DISTINCT FROM a.source_reference OR p->>'sourceVersion' IS DISTINCT FROM a.source_version OR p->>'registryVersion' IS DISTINCT FROM k.registry_version OR jsonb_typeof(p->'clause') IS DISTINCT FROM 'object' OR nullif(p#>>'{clause,locator}','') IS NULL OR nullif(p#>>'{clause,quote}','') IS NULL OR position(convert_to(p#>>'{clause,quote}','UTF8') IN a.source_bytes)=0 OR issued IS NULL OR expires IS NULL OR NOT isfinite(issued) OR NOT isfinite(expires) OR issued>now() OR expires<=now() OR issued<greatest(k.valid_from,g.valid_from) OR expires>least(k.valid_to,g.valid_to) OR expires<(a.claims->>'validUntil')::timestamptz THEN RETURN NULL;END IF;
 RETURN p||jsonb_build_object('ownerRegistryId',k.id,'ownerRegistryVersion',k.registry_version);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;
END$_$;

--
-- Name: revoke_lock_v1(); Type: FUNCTION; Schema: gridex_network_registry_sources; Owner: -
--

CREATE FUNCTION gridex_network_registry_sources.revoke_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_network_registry_sources.issuer_keys WHERE id=NEW.target_id FOR UPDATE;ELSIF NEW.target_kind='representation' THEN PERFORM id FROM gridex_network_registry_sources.representations WHERE id=NEW.target_id FOR UPDATE;ELSE PERFORM id FROM gridex_network_registry_sources.artifacts WHERE id=NEW.target_id FOR UPDATE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'network_registry_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'outbound_dispatch_append_only' USING ERRCODE='55000'; END $$;

--
-- Name: mutate_before_bilateral_prodat_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_bilateral_prodat_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN
 result:=gridex_outbound_dispatch.mutate_before_customer_records_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND result->>'proceed'='true' THEN PERFORM public.ediel_require_message_consumed_records_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid);END IF;RETURN result;
END$$;

--
-- Name: mutate_before_blob_retention_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_blob_retention_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN r:=gridex_outbound_dispatch.mutate_before_temporary_exception_v1(i);IF r->>'scoped'='true' THEN PERFORM gridex_transport_exception.stage_v1(i,r);END IF;RETURN r;END$$;

--
-- Name: mutate_before_customer_records_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_customer_records_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN r:=gridex_outbound_dispatch.mutate_before_blob_retention_v1(p_input);IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN PERFORM public.ediel_require_source_bytes_available_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid);END IF;RETURN r;END$$;

--
-- Name: mutate_before_duplicate_protocol_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_duplicate_protocol_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;m public.ediel_messages%rowtype;BEGIN
 IF p_input->>'action' IN('prepare','enter') THEN PERFORM gridex_supply_rescission.lock_original_v1();END IF;r:=gridex_outbound_dispatch.mutate_before_national_rescission_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid FOR SHARE;
  IF gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS TRUE THEN
   IF gridex_supply_rescission.sender_v1(m.company_id,(p_input->>'actorUserId')::uuid) IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_transport_executor_forbidden' USING ERRCODE='42501';END IF;
   PERFORM gridex_supply_rescission.require_original_v1(m,false);
   IF gridex_supply_rescission.sender_v1(m.company_id,(p_input->>'actorUserId')::uuid) IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_transport_executor_forbidden' USING ERRCODE='42501';END IF;
  END IF;END IF;RETURN r;
END$$;

--
-- Name: mutate_before_mandatory_intent_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_mandatory_intent_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_outbound_dispatch.mutate_before_positive_storage_v1(i);
 IF i->>'action' NOT IN('prepare','enter') OR result->>'scoped' IS DISTINCT FROM 'true' OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(m,true);RETURN result;
END $$;

--
-- Name: mutate_before_national_rescission_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_national_rescission_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;m public.ediel_messages%rowtype;BEGIN
 result:=gridex_outbound_dispatch.mutate_before_unused_unh_v1(i);
 IF(i->>'action' IN('prepare','enter')) IS TRUE AND result->>'scoped'='true' AND result->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
  PERFORM gridex_ediel_ack_guide.require_unused_unh_current_message_v1(m);END IF;RETURN result;END $$;

--
-- Name: mutate_before_native_ack_guide_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_native_ack_guide_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;
BEGIN
 result:=gridex_outbound_dispatch.mutate_before_mandatory_intent_v1(i);
 IF (i->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'scoped' IS DISTINCT FROM 'true' OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=(i->>'companyId')::uuid AND environment=i->>'environment' AND direction='outbound' FOR SHARE;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);RETURN result;
END $$;

--
-- Name: mutate_before_observed_clock_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_observed_clock_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
 c uuid:=(p_input->>'companyId')::uuid; env text:=p_input->>'environment'; actor uuid:=(p_input->>'actorUserId')::uuid;
 mid uuid:=(p_input->>'messageId')::uuid; aid uuid:=(p_input->>'attemptId')::uuid; action text:=p_input->>'action';
 m public.ediel_messages%rowtype; a gridex_outbound_dispatch.attempts%rowtype; r gridex_outbound_dispatch.reservations%rowtype;
 o gridex_outbound_dispatch.originals%rowtype; e gridex_outbound_dispatch.events%rowtype;
 tokens jsonb; owner jsonb:=p_input->'owner'; binding jsonb:=p_input->'binding'; result jsonb:=p_input->'result';
 observed timestamptz:=clock_timestamp();business_date date;
 scoped boolean; event_kind text; body jsonb; classification text; bytes bytea;
BEGIN
 business_date:=(observed AT TIME ZONE 'Europe/Stockholm')::date;
 IF action='prepare' THEN
  -- Canonical DB row owns eligibility. Caller subtype, status and hash cannot opt out.
  SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=env FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbound_dispatch_message_unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO o FROM gridex_outbound_dispatch.originals WHERE message_id=mid;
  tokens:=gridex_received_sources.closure_wire_tokens_v1(m.raw_payload);
  scoped:=o.message_id IS NOT NULL OR (m.direction='outbound' AND (
   m.message_code='Z08' OR (m.message_family='PRODAT' AND (tokens IS NULL OR NOT EXISTS(
    SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM')))
   OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z08')));
  -- A canonical LK wire remains outside this H checkpoint. A caller subtype
  -- cannot hide Z25/H bytes behind a different profile.
  IF o.message_id IS NULL AND m.direction='outbound' AND m.message_family='PRODAT'
   AND m.message_code='Z08' AND m.rule_profile_key='PRODAT:Z08:LK:26.A:r3'
   AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z08')
   AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z23')
   AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z25')
  THEN RETURN jsonb_build_object('scoped',false,'unscopedReason','canonical_lk_exemption'); END IF;
  IF NOT coalesce(scoped,false) THEN RETURN jsonb_build_object('scoped',false); END IF;
 IF c IS NULL OR actor IS NULL OR mid IS NULL OR env IS NULL OR env NOT IN ('test','production')
 OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false))
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.canonical_tenant_operation_decision(c,CASE env WHEN 'production' THEN 'ediel.production.send' ELSE 'ediel.test.process' END) d WHERE d.allowed)
 THEN RAISE EXCEPTION 'outbound_dispatch_actor_unavailable' USING ERRCODE='42501'; END IF;

  IF m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT'
  OR m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR octet_length(m.raw_payload)>262144 OR m.rule_profile_key IS DISTINCT FROM 'PRODAT:Z08:H:26.A:r3'
  OR NOT EXISTS(SELECT FROM public.ediel_message_profiles p JOIN public.ediel_rule_packs pack ON pack.id=p.rule_pack_id
    WHERE p.id=m.rule_profile_version_id AND p.profile_key=m.rule_profile_key AND p.is_enabled AND pack.id=m.canonical_rule_pack_id
    AND pack.status='active' AND pack.valid_from<=business_date AND (pack.valid_to IS NULL OR pack.valid_to>=business_date)
    AND pack.family='PRODAT' AND pack.guide_version='26.A' AND pack.guide_revision='3'
    AND pack.source_hash=m.rule_pack_checksum AND m.rule_profile_version=pack.guide_version||':r'||pack.guide_revision)
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z08')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z25'
   AND tokens->((t->>'index')::integer-1)->>'tag'='CCI' AND tokens->((t->>'index')::integer-1)#>>'{elements,2,0}'='Z13')
  THEN RAISE EXCEPTION 'outbound_dispatch_sealed_original_unavailable' USING ERRCODE='23514'; END IF;
  IF aid IS NULL OR jsonb_typeof(owner) IS DISTINCT FROM 'object' OR owner->>'kind' IS NULL OR owner->>'kind' NOT IN ('direct','worker')
  OR jsonb_typeof(binding) IS DISTINCT FROM 'object' OR binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash
  OR binding->>'routeId' IS DISTINCT FROM m.communication_route_id::text OR binding->>'to' IS DISTINCT FROM m.receiver_email
  OR nullif(binding->>'from','') IS NULL OR binding->>'encoding' IS DISTINCT FROM 'latin1'
  OR nullif(binding->>'mimeMode','') IS NULL OR octet_length(binding::text)>6291456
  THEN RAISE EXCEPTION 'outbound_dispatch_binding_invalid' USING ERRCODE='23514'; END IF;
  -- The actual prepared SMTP-from selects a unique current mailbox. Missing
  -- or ambiguous mailbox basis holds DSN correlation, not the send itself.
  binding:=binding||jsonb_build_object('sourceMailboxId',gridex_ediel_transport.dsn_sending_mailbox_v1(c,env,binding->>'from'));
  bytes:=decode(binding->>'payloadBase64','base64');
  IF bytes IS NULL OR octet_length(bytes)=0 OR octet_length(bytes)>262144
   OR bytes IS DISTINCT FROM convert_to(m.raw_payload,'LATIN1')
   OR binding->>'payloadHash' IS DISTINCT FROM encode(sha256(bytes),'hex')
   OR (binding->>'payloadLength')::integer IS DISTINCT FROM octet_length(bytes)
  THEN RAISE EXCEPTION 'outbound_dispatch_physical_bytes_invalid' USING ERRCODE='23514'; END IF;
  body:=jsonb_build_object('rawOriginalHash',m.immutable_payload_hash,'renderedAt',m.immutable_rendered_at,
    'profileKey',m.rule_profile_key,'profileId',m.rule_profile_version_id,'packId',m.canonical_rule_pack_id,'packChecksum',m.rule_pack_checksum,
    'sender',m.sender_ediel_id,'receiver',m.receiver_ediel_id,'pointId',m.metering_point_id,'siteId',m.site_id,
    'wireTokens',tokens,'coverage','prospective_only','complete',false);
  INSERT INTO gridex_outbound_dispatch.originals(message_id,company_id,environment,raw_payload,payload_hash,facts)
   VALUES(mid,c,env,m.raw_payload,m.immutable_payload_hash,body) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT o FROM gridex_outbound_dispatch.originals WHERE message_id=mid FOR UPDATE;
  IF o.company_id<>c OR o.environment<>env OR o.payload_hash<>m.immutable_payload_hash OR o.raw_payload<>m.raw_payload
  THEN RAISE EXCEPTION 'outbound_dispatch_original_changed' USING ERRCODE='23514'; END IF;
  SELECT * INTO r FROM gridex_outbound_dispatch.reservations WHERE message_id=mid FOR UPDATE;
  IF FOUND AND r.state<>'released' THEN
   SELECT ev.* INTO e FROM gridex_outbound_dispatch.events ev JOIN gridex_outbound_dispatch.witnesses w ON w.event_id=ev.id
    WHERE ev.attempt_id=r.attempt_id AND ev.kind='provider_result' AND ev.facts->>'classification'='accepted';
   RETURN jsonb_build_object('scoped',true,'proceed',false,'state',r.state,
    'acceptedReceipt',CASE WHEN e.id IS NOT NULL THEN (e.facts->'provider')||jsonb_build_object('observedAt',e.observed_at) ELSE NULL END);
  END IF;
  IF EXISTS(SELECT FROM gridex_outbound_dispatch.attempts WHERE id=aid) THEN RAISE EXCEPTION 'outbound_dispatch_attempt_reused'; END IF;
  IF owner->>'kind'='worker' THEN
   PERFORM 1 FROM public.ediel_outbox WHERE id=(owner->>'outboxId')::uuid AND ediel_message_id=mid AND company_id=c AND environment=env
    AND status='sending' AND current_send_attempt_id=(owner->>'sendAttemptId')::uuid AND locked_by=owner->>'workerId' FOR UPDATE;
   IF FOUND AND NOT EXISTS(SELECT FROM public.ediel_outbox lease WHERE lease.id=(owner->>'outboxId')::uuid AND lease.company_id=c AND lease.ediel_message_id=mid AND lease.environment=env AND lease.locked_at IS NOT NULL AND lease.locked_at<=clock_timestamp() AND lease.locked_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'outbound_dispatch_worker_fence_lost' USING ERRCODE='42501';END IF;
   IF NOT FOUND THEN RAISE EXCEPTION 'outbound_dispatch_worker_fence_lost' USING ERRCODE='42501'; END IF;
  ELSIF owner IS DISTINCT FROM '{"kind":"direct"}'::jsonb THEN RAISE EXCEPTION 'outbound_dispatch_direct_owner_invalid'; END IF;
  INSERT INTO gridex_outbound_dispatch.attempts(id,message_id,company_id,environment,actor_user_id,owner,binding) VALUES(aid,mid,c,env,actor,owner,binding);
  INSERT INTO gridex_outbound_dispatch.reservations(message_id,attempt_id,state) VALUES(mid,aid,'prepared')
   ON CONFLICT(message_id) DO UPDATE SET attempt_id=excluded.attempt_id,state='prepared';
  event_kind:='prepared';body:=jsonb_build_object('bindingHash',encode(sha256(convert_to(binding::text,'UTF8')),'hex'));
 ELSE
 IF c IS NULL OR actor IS NULL OR mid IS NULL OR env IS NULL OR env NOT IN ('test','production')
 OR NOT (coalesce(public.gridex_actor_has_company_permission(actor,c,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false))
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.canonical_tenant_operation_decision(c,CASE env WHEN 'production' THEN 'ediel.production.send' ELSE 'ediel.test.process' END) d WHERE d.allowed)
 THEN RAISE EXCEPTION 'outbound_dispatch_actor_unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO a FROM gridex_outbound_dispatch.attempts WHERE id=aid AND message_id=mid AND company_id=c AND environment=env AND actor_user_id=actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbound_dispatch_attempt_unavailable' USING ERRCODE='42501'; END IF;
  IF action='witness' THEN
   SELECT * INTO e FROM gridex_outbound_dispatch.events WHERE id=(p_input->>'eventId')::uuid AND attempt_id=aid AND company_id=c AND environment=env;
   IF NOT FOUND OR e.created_xid=pg_current_xact_id() OR NOT pg_visible_in_snapshot(e.created_xid,pg_current_snapshot())
   THEN RAISE EXCEPTION 'outbound_dispatch_visibility_unproven'; END IF;
   INSERT INTO gridex_outbound_dispatch.witnesses(event_id,company_id,environment,visibility_snapshot) VALUES(e.id,c,env,pg_current_snapshot()::text) ON CONFLICT DO NOTHING;
   RETURN jsonb_build_object('scoped',true,'eventId',e.id,'witnessed',true);
  END IF;
  -- Every transition locks the same original before the mutable current owner.
  PERFORM 1 FROM gridex_outbound_dispatch.originals WHERE message_id=mid FOR UPDATE;
  SELECT * INTO r FROM gridex_outbound_dispatch.reservations WHERE message_id=mid FOR UPDATE;
  IF r.attempt_id IS DISTINCT FROM aid THEN RAISE EXCEPTION 'outbound_dispatch_stale_owner'; END IF;
  IF action='enter' THEN
   IF r.state<>'prepared' THEN RETURN jsonb_build_object('scoped',true,'proceed',false,'state',r.state); END IF;
   IF a.owner->>'kind'='worker' THEN
    PERFORM 1 FROM public.ediel_outbox WHERE id=(a.owner->>'outboxId')::uuid AND ediel_message_id=mid AND company_id=c AND environment=env
     AND status='sending' AND current_send_attempt_id=(a.owner->>'sendAttemptId')::uuid AND locked_by=a.owner->>'workerId' FOR UPDATE;
   IF FOUND AND NOT EXISTS(SELECT FROM public.ediel_outbox lease WHERE lease.id=(a.owner->>'outboxId')::uuid AND lease.company_id=c AND lease.ediel_message_id=mid AND lease.environment=env AND lease.locked_at IS NOT NULL AND lease.locked_at<=clock_timestamp() AND lease.locked_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'outbound_dispatch_worker_fence_lost' USING ERRCODE='42501';END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'outbound_dispatch_worker_fence_lost' USING ERRCODE='42501'; END IF;
   END IF;
   UPDATE gridex_outbound_dispatch.reservations SET state='provider_call_entered' WHERE message_id=mid;
   event_kind:='provider_call_entered';body:='{"observation":"provider_entry_authorized_not_acceptance"}';
  ELSIF action='release' THEN
   IF r.state<>'prepared' OR EXISTS(SELECT FROM gridex_outbound_dispatch.events WHERE attempt_id=aid AND kind='provider_call_entered')
    THEN RAISE EXCEPTION 'outbound_dispatch_release_unsafe'; END IF;
   UPDATE gridex_outbound_dispatch.reservations SET state='released' WHERE message_id=mid;
   event_kind:='released';body:='{"proof":"entry_never_committed"}';
  ELSIF action='result' THEN
   IF r.state<>'provider_call_entered' OR jsonb_typeof(result) IS DISTINCT FROM 'object' OR octet_length(result::text)>262144
    THEN RAISE EXCEPTION 'outbound_dispatch_result_invalid'; END IF;
   classification:='uncertain';
   IF jsonb_typeof(result->'accepted')='array' AND jsonb_typeof(result->'rejected')='array'
    AND NOT EXISTS(SELECT FROM jsonb_array_elements((result->'accepted')||(result->'rejected')) x WHERE jsonb_typeof(x)<>'string' OR nullif(btrim(x#>>'{}'),'') IS NULL)
    AND NOT EXISTS(SELECT FROM jsonb_array_elements_text((result->'accepted')||(result->'rejected')) x WHERE lower(x) IS DISTINCT FROM lower(a.binding->>'to')) THEN
    IF jsonb_array_length(result->'accepted')>0 THEN classification:=CASE WHEN jsonb_array_length(result->'rejected')>0 THEN 'partial' ELSE 'accepted' END;
    ELSIF jsonb_array_length(result->'rejected')>0 THEN classification:='all_rejected'; END IF;
   ELSIF result#>>'{error,syscall}'='connect' THEN classification:='pre_connect_negative';
   ELSIF result#>>'{error,responseCode}' ~ '^[45][0-9][0-9]$' THEN classification:='explicit_negative'; END IF;
   event_kind:='provider_result';body:=jsonb_build_object('classification',classification,'provider',result,'acceptanceTime','not_observed','automaticResend',false);
  ELSE RAISE EXCEPTION 'outbound_dispatch_action_invalid'; END IF;
 END IF;
 INSERT INTO gridex_outbound_dispatch.events(message_id,attempt_id,company_id,environment,kind,facts) VALUES(mid,aid,c,env,event_kind,body)
  ON CONFLICT(attempt_id,kind) DO NOTHING RETURNING * INTO e;
 IF NOT FOUND THEN
  SELECT * INTO STRICT e FROM gridex_outbound_dispatch.events WHERE attempt_id=aid AND kind=event_kind;
  IF e.facts IS DISTINCT FROM body THEN RAISE EXCEPTION 'outbound_dispatch_receipt_conflict'; END IF;
 END IF;
 RETURN jsonb_build_object('scoped',true,'proceed',true,'eventId',e.id,'attemptId',aid,'kind',event_kind,'facts',e.facts);
END $_$;

--
-- Name: mutate_before_original_basis_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_original_basis_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result jsonb; observed timestamptz;
BEGIN
 result:=gridex_outbound_dispatch.mutate_before_observed_clock_v1(p_input);
 IF p_input->>'action'='result' AND result->>'scoped'='true' THEN
  SELECT e.observed_at INTO STRICT observed FROM gridex_outbound_dispatch.events e
   WHERE e.id=(result->>'eventId')::uuid AND e.attempt_id=(p_input->>'attemptId')::uuid
   AND e.message_id=(p_input->>'messageId')::uuid AND e.company_id=(p_input->>'companyId')::uuid
   AND e.environment=p_input->>'environment' AND e.kind='provider_result' FOR SHARE;
  IF observed IS NULL OR NOT isfinite(observed) THEN RAISE EXCEPTION 'outbound_dispatch_actual_observation_clock_required';END IF;
  result:=result||jsonb_build_object('observedAt',observed,'observationClock','database_provider_result_capture');
 END IF;
 RETURN result;
END $$;

--
-- Name: mutate_before_positive_storage_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_positive_storage_v1(i jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;m public.ediel_messages%rowtype;r gridex_outbound_dispatch.reservations%rowtype;
 a gridex_outbound_dispatch.attempts%rowtype;o gridex_outbound_dispatch.originals%rowtype;e gridex_outbound_dispatch.events%rowtype;
 c uuid:=(i->>'companyId')::uuid;actor uuid:=(i->>'actorUserId')::uuid;env text:=i->>'environment';basis jsonb;
BEGIN
 IF i->>'action' IN('prepare','enter') THEN
  SELECT * INTO m FROM public.ediel_messages WHERE id=(i->>'messageId')::uuid AND company_id=c AND environment=env AND direction='outbound' FOR UPDATE;
  SELECT * INTO r FROM gridex_outbound_dispatch.reservations WHERE message_id=m.id FOR UPDATE;
  IF r.state='provider_call_entered' THEN
   SELECT * INTO a FROM gridex_outbound_dispatch.attempts WHERE id=r.attempt_id AND message_id=m.id AND company_id=c AND environment=env FOR SHARE;
   SELECT * INTO o FROM gridex_outbound_dispatch.originals WHERE message_id=m.id AND company_id=c AND environment=env FOR SHARE;
   IF a.id IS NULL OR o.message_id IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
    OR o.payload_hash IS DISTINCT FROM m.immutable_payload_hash OR o.raw_payload IS DISTINCT FROM m.raw_payload OR a.binding->>'originalHash' IS DISTINCT FROM o.payload_hash
    OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
    OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.send'),false)
    OR (i->>'action'='enter' AND (a.id::text IS DISTINCT FROM i->>'attemptId' OR a.actor_user_id IS DISTINCT FROM actor)) THEN RAISE EXCEPTION 'outbound_dispatch_replay_scope_invalid';END IF;
   SELECT ev.* INTO e FROM gridex_outbound_dispatch.events ev JOIN gridex_outbound_dispatch.witnesses w ON w.event_id=ev.id
    WHERE ev.attempt_id=a.id AND ev.kind='provider_result' AND ev.company_id=c AND ev.environment=env AND ev.facts->>'classification'='accepted';
   RETURN jsonb_build_object('scoped',true,'proceed',false,'state',r.state,'acceptedReceipt',CASE WHEN e.id IS NOT NULL THEN (e.facts->'provider')||jsonb_build_object('observedAt',e.observed_at) ELSE NULL END);
  END IF;
 END IF;
 result:=gridex_outbound_dispatch.mutate_before_original_basis_v1(i);
 IF i->>'action' NOT IN('prepare','enter') OR result->>'scoped' IS DISTINCT FROM 'true' OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 basis:=gridex_ediel_source_rules.capture_v1(c,m.id);
 SELECT * INTO STRICT a FROM gridex_outbound_dispatch.attempts WHERE id=(i->>'attemptId')::uuid AND message_id=m.id AND company_id=c AND environment=env FOR SHARE;
 IF (i->>'action'='prepare' AND i#>'{binding,sourceRulePackEvidence}' IS DISTINCT FROM basis) OR a.binding->'sourceRulePackEvidence' IS DISTINCT FROM basis THEN RAISE EXCEPTION 'outbound_dispatch_original_basis_binding_required';END IF;
 RETURN result;
END $$;

--
-- Name: mutate_before_prodat_unused_document_v1(jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.mutate_before_prodat_unused_document_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;m public.ediel_messages%rowtype;
BEGIN
 IF p_input->>'action' IN('prepare','enter') THEN PERFORM gridex_bilateral_prodat.lock_outbound_v1();END IF;
 r:=gridex_outbound_dispatch.mutate_before_bilateral_prodat_v1(p_input);
 IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=(p_input->>'messageId')::uuid AND company_id=(p_input->>'companyId')::uuid FOR SHARE;PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);PERFORM public.ediel_require_current_prodat_bilateral_ack_source_v1(m.company_id,m.id);END IF;RETURN r;
END$$;

