    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();r:=gridex_outbound_dispatch.mutate_before_duplicate_protocol_v1(p_input);IF p_input->>'action' IN('prepare','enter') AND r->>'proceed'='true' THEN PERFORM gridex_ediel_duplicate_responses.require_transport_v1((p_input->>'companyId')::uuid,(p_input->>'messageId')::uuid,(p_input->>'actorUserId')::uuid);END IF;RETURN r;END$$;

--
-- Name: readset_v1(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.readset_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE ids uuid[]; n bigint; size bigint; too_large boolean; originals jsonb; attempts jsonb; events jsonb; witnesses jsonb; body jsonb;
BEGIN
 IF NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.read'),false)
 OR p_environment IS NULL OR p_environment NOT IN ('test','production')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
 THEN RAISE EXCEPTION 'outbound_dispatch_reader_unavailable' USING ERRCODE='42501'; END IF;
 -- Unknown party/object dimensions are wildcards. Compare outbound FR to the
 -- inbound receiver and outbound DO to inbound sender. Dates remain conservative.
 WITH candidates AS (
  SELECT o.message_id,o.raw_payload,(o.payload_hash=encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex')) AS seal_verified FROM gridex_outbound_dispatch.originals o WHERE o.company_id=p_company_id AND o.environment=p_environment
  UNION ALL
  SELECT m.id,m.raw_payload,(m.immutable_rendered_at IS NOT NULL AND m.immutable_payload_hash IS NOT NULL
   AND m.immutable_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) AS seal_verified FROM public.ediel_messages m WHERE m.company_id=p_company_id AND m.environment=p_environment
   AND m.direction='outbound' AND (m.message_code='Z08' OR m.rule_profile_key='PRODAT:Z08:H:26.A:r3'
    OR (m.message_family='PRODAT' AND (gridex_received_sources.closure_wire_tokens_v1(m.raw_payload) IS NULL
      OR EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v1(m.raw_payload)) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z08'))))
   AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.originals o WHERE o.message_id=m.id)
 ), scoped AS (
  SELECT c.* FROM candidates c CROSS JOIN LATERAL (SELECT gridex_outbound_dispatch.scope_v1(CASE WHEN c.seal_verified THEN c.raw_payload ELSE NULL END) value) s
  WHERE (nullif(p_scope->>'point','') IS NULL OR s.value->>'point' IS NULL OR s.value->>'point'=p_scope->>'point')
   AND (nullif(p_scope->>'inboundSender','') IS NULL OR s.value->>'outboundReceiver' IS NULL OR s.value->>'outboundReceiver'=p_scope->>'inboundSender')
   AND (nullif(p_scope->>'inboundReceiver','') IS NULL OR s.value->>'outboundSender' IS NULL OR s.value->>'outboundSender'=p_scope->>'inboundReceiver')
 ) SELECT count(*),coalesce(sum(octet_length(raw_payload)),0),coalesce(bool_or(octet_length(raw_payload)>262144),false),
  CASE WHEN count(*)<=1000 THEN array_agg(message_id) ELSE NULL END INTO n,size,too_large,ids FROM scoped;
 IF n>1000 OR too_large THEN RETURN jsonb_build_object('complete',false,'originalCount',n,'reason',CASE WHEN n>1000 THEN 'scoped_original_count_overflow' ELSE 'scoped_original_bytes_overflow' END); END IF;
 SELECT size+coalesce(sum(octet_length(binding::text)),0) INTO size FROM gridex_outbound_dispatch.attempts WHERE message_id=ANY(ids);
 IF size>6291456 THEN RETURN jsonb_build_object('complete',false,'originalCount',n,'reason','scoped_original_attempt_bytes_overflow'); END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'message_id'),'[]') INTO originals FROM (
  SELECT to_jsonb(o) x FROM gridex_outbound_dispatch.originals o WHERE message_id=ANY(ids)
  UNION ALL SELECT jsonb_build_object('message_id',m.id,'raw_payload',m.raw_payload,'payload_hash',m.immutable_payload_hash,'uninstrumented',true)
   FROM public.ediel_messages m WHERE id=ANY(ids) AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.originals o WHERE o.message_id=m.id)
 ) q;
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO attempts FROM gridex_outbound_dispatch.attempts a WHERE message_id=ANY(ids);
 SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]') INTO events FROM gridex_outbound_dispatch.events e WHERE message_id=ANY(ids);
 SELECT coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.event_id),'[]') INTO witnesses FROM gridex_outbound_dispatch.witnesses w JOIN gridex_outbound_dispatch.events e ON e.id=w.event_id WHERE e.message_id=ANY(ids);
 body:=jsonb_build_object('version',1,'complete',false,'reason','prospective_history_only','originalCount',n,'originals',originals,'attempts',attempts,'events',events,'witnesses',witnesses,
  'epoch',(SELECT to_jsonb(ep) FROM gridex_outbound_dispatch.epoch ep),'visibilitySnapshot',pg_current_snapshot()::text,
  'gaps',(SELECT coalesce(jsonb_agg(jsonb_build_object('messageId',id,'reason',reason)),'[]') FROM (
   SELECT m.id,'uninstrumented_original' reason FROM public.ediel_messages m WHERE id=ANY(ids) AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.originals o WHERE o.message_id=m.id)
   UNION ALL SELECT e.message_id,'unwitnessed_event' FROM gridex_outbound_dispatch.events e WHERE message_id=ANY(ids) AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.witnesses w WHERE w.event_id=e.id)
   UNION ALL SELECT e.message_id,'unresolved_provider_entry' FROM gridex_outbound_dispatch.events e WHERE message_id=ANY(ids) AND kind='provider_call_entered' AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.events r WHERE r.attempt_id=e.attempt_id AND r.kind='provider_result')
  ) g));
 IF octet_length(body::text)>6291456 THEN RETURN jsonb_build_object('complete',false,'originalCount',n,'reason','scoped_owner_inputs_overflow'); END IF;
 RETURN body;
END $$;

--
-- Name: scope_v1(text); Type: FUNCTION; Schema: gridex_outbound_dispatch; Owner: -
--

CREATE FUNCTION gridex_outbound_dispatch.scope_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t jsonb:=gridex_received_sources.closure_wire_tokens_v1(p_raw); point text; fr text; receiver text; n integer;
BEGIN
 IF t IS NULL THEN RETURN '{}'::jsonb; END IF;
 n:=jsonb_array_length(t);
 IF n<8 OR t->0->>'tag'<>'UNB' OR t->1->>'tag'<>'UNH' OR t->(n-2)->>'tag'<>'UNT' OR t->(n-1)->>'tag'<>'UNZ'
  OR t->1#>>'{elements,2,0}' IS DISTINCT FROM 'PRODAT'
  OR t->(n-2)#>'{elements,1}' IS DISTINCT FROM jsonb_build_array((n-2)::text)
  OR t->(n-2)#>'{elements,2}' IS DISTINCT FROM t->1#>'{elements,1}'
  OR (SELECT count(*) FROM jsonb_array_elements(t) x WHERE x->>'tag' IN ('UNB','UNH','UNT','UNZ','BGM'))<>5
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(t) x WHERE x->>'tag'='BGM' AND x#>>'{elements,1,0}'='Z08')
 THEN RETURN '{}'::jsonb; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(t) x WHERE x->>'tag'='LIN')=1 THEN
  SELECT x#>>'{elements,3,0}' INTO point FROM jsonb_array_elements(t) x WHERE x->>'tag'='LIN' AND x#>>'{elements,3,3}'='9';
 END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(t) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='FR')=1 THEN
  SELECT x#>>'{elements,2,0}' INTO fr FROM jsonb_array_elements(t) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='FR'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(t) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='DO')=1 THEN
  SELECT x#>>'{elements,2,0}' INTO receiver FROM jsonb_array_elements(t) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='DO'; END IF;
 RETURN jsonb_build_object('point',nullif(point,''),'outboundSender',nullif(fr,''),'outboundReceiver',nullif(receiver,''));
END $$;

--
-- Name: customer_document_path_allows(text, text); Type: FUNCTION; Schema: gridex_private; Owner: -
--

CREATE FUNCTION gridex_private.customer_document_path_allows(p_object_name text, p_access text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage', 'auth', 'gridex_private', 'pg_temp'
    AS $_$
declare
  v_parts text[];
  v_company_id uuid;
  v_customer_id uuid;
  v_site_id uuid;
  v_scope text;
  v_document_type text;
  v_file_name text;
  v_has_permission boolean;
begin
  if p_object_name is null
     or p_access not in ('read', 'write')
     or p_object_name <> btrim(p_object_name, '/')
     or p_object_name like '%//%'
  then
    return false;
  end if;

  v_parts := string_to_array(p_object_name, '/');

  if coalesce(array_length(v_parts, 1), 0) <> 7
     or v_parts[1] <> 'companies'
     or v_parts[3] <> 'customers'
  then
    return false;
  end if;

  if v_parts[2] !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or v_parts[4] !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    return false;
  end if;

  v_company_id := v_parts[2]::uuid;
  v_customer_id := v_parts[4]::uuid;
  v_scope := v_parts[5];
  v_document_type := v_parts[6];
  v_file_name := v_parts[7];

  if v_document_type not in (
    'power_of_attorney',
    'complete_agreement',
    'grid_invoice_suggested'
  ) then
    return false;
  end if;

  if v_file_name in ('', '.', '..')
     or char_length(v_file_name) > 255
     or v_file_name !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$'
  then
    return false;
  end if;

  if not exists (
    select 1
    from public.customers c
    where c.id = v_customer_id
      and c.company_id = v_company_id
  ) then
    return false;
  end if;

  if v_scope = 'customer' then
    null;
  elsif v_scope ~* '^site-[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_site_id := substring(v_scope from 6)::uuid;

    if not exists (
      select 1
      from public.customer_sites cs
      where cs.id = v_site_id
        and cs.customer_id = v_customer_id
        and cs.company_id = v_company_id
    ) then
      return false;
    end if;
  else
    return false;
  end if;

  if p_access = 'read' then
    v_has_permission :=
      public.gridex_actor_has_company_permission(
        auth.uid(),
        v_company_id,
        'masterdata.read'
      )
      or public.gridex_actor_has_company_permission(
        auth.uid(),
        v_company_id,
        'switching.read'
      );
  else
    v_has_permission :=
      public.gridex_actor_has_company_permission(
        auth.uid(),
        v_company_id,
        'masterdata.write'
      )
      or public.gridex_actor_has_company_permission(
        auth.uid(),
        v_company_id,
        'switching.write'
      );
  end if;

  return coalesce(v_has_permission, false);
exception
  when others then
    return false;
end;
$_$;

--
-- Name: FUNCTION customer_document_path_allows(p_object_name text, p_access text); Type: COMMENT; Schema: gridex_private; Owner: -
--

COMMENT ON FUNCTION gridex_private.customer_document_path_allows(p_object_name text, p_access text) IS 'Fail-closed authorization for canonical customer-documents object keys. Not exposed as a PostgREST RPC.';

--
-- Name: completed_v1(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.completed_v1(c uuid, case_id uuid, source_id uuid, actor uuid, decisions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE row_case public.ediel_inbound_cases%rowtype;m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;r gridex_prodat_object_batch.review_receipts%rowtype;
 basis gridex_ediel_inbound_context.receipts%rowtype;plan jsonb;ctx jsonb;observed timestamptz:=clock_timestamp();n int;resolved_role text;proof jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE user_id=actor AND company_id=c AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR NOT (public.gridex_actor_has_company_permission(actor,c,'communication.read') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE)
  OR NOT (public.gridex_actor_has_company_permission(actor,c,'customers.read') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'customers.write') IS TRUE) THEN RAISE EXCEPTION 'prodat_object_batch_current_read_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c AND direction='inbound' AND message_standard='edifact' AND message_family='PRODAT' FOR SHARE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=c AND environment=m.environment FOR SHARE;
 SELECT * INTO row_case FROM public.ediel_inbound_cases WHERE id=case_id AND company_id=c AND ediel_message_id=source_id FOR SHARE;
 IF row_case.id IS NULL OR row_case.status<>'applied' THEN RETURN NULL;END IF;
 SELECT * INTO r FROM gridex_prodat_object_batch.review_receipts q WHERE q.company_id=c AND q.case_id=row_case.id;
 SELECT * INTO basis FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=m.id AND company_id=c AND environment=m.environment;
 plan:=row_case.review_decision->'objectApplication';
 IF m.id IS NULL OR s.source_message_id IS NULL OR s.origin IS DISTINCT FROM 'database_insert' OR s.source_received_at IS DISTINCT FROM m.message_received_at OR s.received_context IS DISTINCT FROM m.execution_context_snapshot->'receivedProdatContext'
  OR s.payload_hash IS DISTINCT FROM r.source_hash OR r.source_message_id IS DISTINCT FROM m.id OR r.environment IS DISTINCT FROM m.environment OR r.actor_user_id IS DISTINCT FROM actor OR row_case.reviewed_by IS DISTINCT FROM actor OR row_case.reviewed_at IS DISTINCT FROM r.recorded_at
  OR plan->>'originalActorId' IS DISTINCT FROM actor::text OR plan->>'fingerprint' IS DISTINCT FROM r.fingerprint OR plan->>'commandHash' IS DISTINCT FROM r.command_hash OR gridex_prodat_object_batch.hash_v1(plan->'commands') IS DISTINCT FROM r.command_hash
  OR plan->>'sourceHash' IS DISTINCT FROM r.source_hash OR plan->'decisions' IS DISTINCT FROM decisions OR jsonb_typeof(plan->'commands') IS DISTINCT FROM 'array' OR jsonb_array_length(plan->'commands') NOT BETWEEN 2 AND 16
  OR jsonb_array_length(plan->'commands') IS DISTINCT FROM jsonb_array_length(plan->'receipts') OR r.assessment_id IS NULL
  OR basis.source_message_id IS NULL OR basis.status IS DISTINCT FROM 'ready' OR basis.direction IS DISTINCT FROM 'inbound' OR basis.payload_sha256 IS DISTINCT FROM r.source_hash OR basis.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'prodat_object_batch_completed_receipt_required';END IF;
 -- A NULL body is accepted only when the native immutable tombstone seals the
 -- same public/private original and actual purge time. No byte reconstruction.
 IF m.raw_payload IS NULL THEN
  IF s.raw_payload IS NOT NULL OR s.retention_purged_at IS NULL OR NOT EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class='received_ediel_message_content' AND t.target_id=m.id AND t.company_id=c AND t.source_hash=r.source_hash AND t.created_at=s.retention_purged_at) THEN RAISE EXCEPTION 'prodat_object_batch_native_byte_tombstone_required';END IF;
 ELSIF s.raw_payload IS DISTINCT FROM m.raw_payload OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM r.source_hash THEN RAISE EXCEPTION 'prodat_object_batch_completed_original_changed';END IF;
 ctx:=basis.context;
 IF ctx->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR ctx->>'companyId' IS DISTINCT FROM c::text OR ctx->>'environment' IS DISTINCT FROM m.environment OR ctx->>'family' IS DISTINCT FROM 'PRODAT' OR ctx->>'code' IS DISTINCT FROM m.message_code OR ctx->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT coalesce(ctx#>'{canonicalProjection,applicationReferences}' ? (ctx->>'applicationReference'),false)
  OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.id::text=ctx#>>'{facts,profile,id}' AND p.company_id=c AND p.environment=m.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND (p.valid_to IS NULL OR observed<p.valid_to))
  OR (SELECT count(*) FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=m.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND(p.valid_to IS NULL OR observed<p.valid_to))<>1 THEN RAISE EXCEPTION 'prodat_object_batch_current_captured_role_required';END IF;
 SELECT count(DISTINCT role_code),min(role_code) INTO n,resolved_role FROM public.tenant_actor_roles WHERE company_id=c AND environment=m.environment AND actor_id::text=ctx->>'legalActorId' AND valid_from<=observed AND(valid_to IS NULL OR observed<valid_to) AND(ctx#>'{canonicalProjection,receiverRoles}' ? role_code OR ctx#>'{canonicalProjection,receiverRoles}' ? CASE role_code WHEN 'electricity_supplier' THEN 'supplier' ELSE role_code END);
 IF n<>1 OR resolved_role IS DISTINCT FROM ctx->>'actorRole' THEN RAISE EXCEPTION 'prodat_object_batch_current_captured_role_required';END IF;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(ctx);
 proof:=jsonb_build_object('sourcePayloadHash',r.source_hash);
 PERFORM gridex_prodat_object_batch.require_review_v1(row_case,plan,jsonb_build_object('sourceMessage',jsonb_build_object('environment',m.environment),'sourcePayloadHash',r.source_hash),actor);
 PERFORM gridex_prodat_object_batch.require_receipts_v1(row_case,plan,proof);
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a WHERE a.id=r.assessment_id AND a.company_id=c AND a.environment=m.environment AND a.source_message_id=m.id AND a.source_payload_hash=r.source_hash) THEN RAISE EXCEPTION 'prodat_object_batch_completed_assessment_required';END IF;
 RETURN to_jsonb(row_case);
END $$;

--
-- Name: hash_v1(jsonb); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.hash_v1(j jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT encode(sha256(convert_to(gridex_prodat_object_batch.json_text_v1(j),'UTF8')),'hex')$$;

--
-- Name: json_text_v1(jsonb); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.json_text_v1(j jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result text;BEGIN
 IF jsonb_typeof(j)='object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||gridex_prodat_object_batch.json_text_v1(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(j);RETURN result;
 ELSIF jsonb_typeof(j)='array' THEN SELECT '['||coalesce(string_agg(gridex_prodat_object_batch.json_text_v1(value),',' ORDER BY ord),'')||']' INTO result FROM jsonb_array_elements(j) WITH ORDINALITY a(value,ord);RETURN result;
 ELSE RETURN j::text;END IF;
END $$;

--
-- Name: onboard_v1(jsonb); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.onboard_v1(command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(command->>'company_id')::uuid;actor uuid:=(command->>'actor_user_id')::uuid;case_id uuid:=split_part(command#>>'{application,source_record_id}',':object:',1)::uuid;
 row_case public.ediel_inbound_cases%rowtype;proof jsonb;plan jsonb;key text;canonical_command jsonb:=command-ARRAY['correlation_id','test_fail_after'];stored_command jsonb;r gridex_prodat_object_batch.graph_receipts%rowtype;op public.customer_onboarding_operations%rowtype;result jsonb;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();
 SELECT ediel_message_id INTO row_case.ediel_message_id FROM public.ediel_inbound_cases WHERE id=case_id AND company_id=c;
 proof:=gridex_prodat_object_batch.source_v1(c,row_case.ediel_message_id,actor);
 SELECT * INTO row_case FROM public.ediel_inbound_cases WHERE id=case_id AND company_id=c FOR UPDATE;
 plan:=row_case.review_decision->'objectApplication';
 IF row_case.id IS NULL OR row_case.reviewed_by IS DISTINCT FROM actor OR row_case.reviewed_at IS NULL OR row_case.status NOT IN('approved','failed','applied') THEN RAISE EXCEPTION 'prodat_object_batch_approved_case_required';END IF;
 PERFORM gridex_prodat_object_batch.require_plan_v1(row_case,plan,proof,actor);
 PERFORM gridex_prodat_object_batch.require_review_v1(row_case,plan,proof,actor);
 SELECT value INTO stored_command FROM jsonb_array_elements(plan->'commands') WHERE value->>'idempotency_key'=command->>'idempotency_key';
 IF stored_command IS NULL OR stored_command IS DISTINCT FROM canonical_command THEN RAISE EXCEPTION 'prodat_object_batch_exact_approved_command_required';END IF;
 SELECT gridex_prodat_object_batch.json_text_v1(jsonb_build_array(d->>'meteringPointId',d->>'identityAgency')) INTO key FROM jsonb_array_elements(plan->'decisions')d WHERE d->>'meteringPointId'=command#>>'{metering_point,meter_point_id}';
 SELECT * INTO r FROM gridex_prodat_object_batch.graph_receipts gr WHERE gr.company_id=c AND gr.case_id=row_case.id AND gr.object_key=key;
 IF r.operation_id IS NOT NULL THEN
  SELECT * INTO op FROM public.customer_onboarding_operations WHERE id=r.operation_id AND company_id=c AND channel='ediel_inbound' AND status='completed' FOR SHARE;
  IF op.id IS NULL OR r.source_hash IS DISTINCT FROM proof->>'sourcePayloadHash' OR r.command_hash IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(canonical_command) OR r.actor_user_id IS DISTINCT FROM actor OR r.result_hash IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(op.result_snapshot) THEN RAISE EXCEPTION 'prodat_object_batch_replay_conflict';END IF;
  RETURN op.result_snapshot; -- Established operation: no writer or new receipt.
 END IF;
 IF row_case.status='applied' THEN RAISE EXCEPTION 'prodat_object_batch_applied_receipt_missing';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(c,row_case.ediel_message_id);
 result:=public.gridex_onboard_customer_graph(command);
 IF result->'ok' IS DISTINCT FROM 'true'::jsonb THEN RETURN result;END IF;
 SELECT * INTO op FROM public.customer_onboarding_operations WHERE id=(result->>'operation_id')::uuid AND company_id=c AND channel='ediel_inbound' AND idempotency_key=command->>'idempotency_key' AND status='completed';
 IF op.id IS NULL OR op.result_snapshot IS DISTINCT FROM result OR op.command_snapshot-ARRAY['correlation_id','test_fail_after'] IS DISTINCT FROM canonical_command THEN RAISE EXCEPTION 'prodat_object_batch_native_graph_result_required';END IF;
 INSERT INTO gridex_prodat_object_batch.graph_receipts(company_id,case_id,source_message_id,environment,source_hash,assessment_id,actor_user_id,object_key,command_hash,result_hash,operation_id)
 VALUES(c,row_case.id,row_case.ediel_message_id,proof#>>'{sourceMessage,environment}',proof->>'sourcePayloadHash',(proof->>'assessmentId')::uuid,actor,key,gridex_prodat_object_batch.hash_v1(canonical_command),gridex_prodat_object_batch.hash_v1(result),op.id);
 RETURN result;
END $$;

--
-- Name: raw_segments_v1(text); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.raw_segments_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE body text:=raw;release_char text:='?';terminator text:='''';ch text;part text:='';released bool:=false;out jsonb:='[]';BEGIN
 IF gridex_received_sources.closure_wire_tokens_v2(raw) IS NULL THEN RETURN NULL;END IF;
 IF left(body,3)='UNA' THEN release_char:=substr(body,7,1);terminator:=substr(body,9,1);body:=substr(body,10);END IF;
 body:=replace(replace(body,E'\r\n',''),E'\n','');
 FOREACH ch IN ARRAY string_to_array(body,NULL) LOOP
  IF released THEN part:=part||ch;released:=false;
  ELSIF ch=release_char THEN part:=part||ch;released:=true;
  ELSIF ch=terminator THEN IF btrim(part,E' \t')<>'' THEN out:=out||jsonb_build_array(btrim(part,E' \t'));END IF;part:='';
  ELSE part:=part||ch;END IF;
 END LOOP;
 RETURN out;
END $$;

--
-- Name: ediel_inbound_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_inbound_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    ediel_message_id uuid,
    case_type text DEFAULT 'unresolved'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    customer_id uuid,
    site_id uuid,
    metering_point_id uuid,
    switch_request_id uuid,
    assigned_to uuid,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    message_family text,
    message_code text,
    transaction_type text,
    match_confidence numeric(5,2),
    parsed_customer jsonb DEFAULT '{}'::jsonb NOT NULL,
    parsed_site jsonb DEFAULT '{}'::jsonb NOT NULL,
    parsed_metering_point jsonb DEFAULT '{}'::jsonb NOT NULL,
    parsed_contract jsonb DEFAULT '{}'::jsonb NOT NULL,
    parsed_production jsonb DEFAULT '{}'::jsonb NOT NULL,
    proposed_action jsonb DEFAULT '{}'::jsonb NOT NULL,
    review_decision jsonb,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    applied_at timestamp with time zone,
    failure_reason text,
    CONSTRAINT ediel_inbound_cases_match_confidence_range CHECK (((match_confidence IS NULL) OR ((match_confidence >= (0)::numeric) AND (match_confidence <= (100)::numeric)))),
    CONSTRAINT ediel_inbound_cases_review_pair CHECK (((reviewed_at IS NULL) = (reviewed_by IS NULL)))
);

--
-- Name: require_plan_v1(public.ediel_inbound_cases, jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_plan_v1(row_case public.ediel_inbound_cases, plan jsonb, proof jsonb, actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE d jsonb;command jsonb;own jsonb;i int:=0;source public.ediel_messages%rowtype;scope_key text;BEGIN
 source:=jsonb_populate_record(NULL::public.ediel_messages,proof->'sourceMessage');
 IF plan->'version' IS DISTINCT FROM '1'::jsonb OR(plan->>'revision')::int<1 OR plan->>'originalActorId' IS DISTINCT FROM actor::text
  OR plan->>'sourceHash' IS DISTINCT FROM proof->>'sourcePayloadHash' OR jsonb_typeof(plan->'decisions') IS DISTINCT FROM 'array' OR jsonb_typeof(plan->'commands') IS DISTINCT FROM 'array' OR jsonb_typeof(plan->'receipts') IS DISTINCT FROM 'array'
  OR jsonb_array_length(plan->'decisions') IS DISTINCT FROM jsonb_array_length(proof#>'{applicationValidation,objects}') OR jsonb_array_length(plan->'commands') IS DISTINCT FROM jsonb_array_length(plan->'decisions')
  OR plan->>'commandHash' IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(plan->'commands')
  OR plan->>'fingerprint' IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(jsonb_build_array(row_case.company_id,row_case.id,source.id,proof->>'sourcePayloadHash',plan->'decisions')) THEN RAISE EXCEPTION 'prodat_object_batch_plan_integrity_required';END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(plan->'decisions') LOOP
  own:=proof#>ARRAY['applicationValidation','objects',i::text];command:=plan#>ARRAY['commands',i::text];
  scope_key:=gridex_prodat_object_batch.hash_v1(jsonb_build_array(d->>'meteringPointId',d->>'identityAgency'));
  IF d->>'meteringPointId' IS DISTINCT FROM own->>'objectId' OR d->>'identityAgency' IS DISTINCT FROM own->>'identityAgency' OR d->>'meteringPointId'!~'^[A-Z0-9]+$'
   OR(d->>'mode' IN('create_new_customer','update_existing_customer','link_existing_only')) IS NOT TRUE
   OR command->>'company_id' IS DISTINCT FROM row_case.company_id::text OR command->>'actor_user_id' IS DISTINCT FROM actor::text OR command->>'channel' IS DISTINCT FROM 'ediel_inbound'
   OR command#>>'{application,source_record_type}' IS DISTINCT FROM 'ediel_inbound_case' OR command#>>'{application,source_record_id}' IS DISTINCT FROM row_case.id::text||':object:'||scope_key
   OR command->>'idempotency_key' IS DISTINCT FROM 'ediel_inbound:'||row_case.id::text||':object:'||scope_key
   OR command#>>'{application,payload_snapshot,edielMessageId}' IS DISTINCT FROM source.id::text OR command#>>'{application,payload_snapshot,mode}' IS DISTINCT FROM d->>'mode'
   OR command#>>'{metering_point,meter_point_id}' IS DISTINCT FROM own->>'objectId' OR command#>>'{site,facility_id}' IS DISTINCT FROM own->>'objectId'
   OR jsonb_array_length(command#>'{application,payload_snapshot,prodatObjects}') IS DISTINCT FROM 1
   OR command#>>'{application,payload_snapshot,prodatObjects,0,meteringPointId}' IS DISTINCT FROM own->>'objectId'
   OR command#>>'{application,payload_snapshot,prodatObjects,0,identityAgency}' IS DISTINCT FROM own->>'identityAgency'
   OR jsonb_array_length(command#>'{application,payload_snapshot,prodatRegisters}') IS DISTINCT FROM jsonb_array_length(own->'registers')
   OR command#>'{application,payload_snapshot,prodatRegisters}' IS DISTINCT FROM command#>'{application,payload_snapshot,prodatObjects,0,registers}'
   OR command-ARRAY['company_id','actor_user_id','channel','idempotency_key','matching_policy','existing_customer_id','existing_site_id','existing_metering_point_id','update_existing','customer','site','metering_point','application']<>'{}'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_command_source_partition_required';END IF;
  IF d->>'mode'='create_new_customer' AND(command->>'matching_policy' IS DISTINCT FROM 'create_separate' OR command->>'existing_customer_id' IS NOT NULL OR command->>'existing_site_id' IS NOT NULL OR command->>'existing_metering_point_id' IS NOT NULL)
   OR d->>'mode'<>'create_new_customer' AND(command->>'matching_policy' IS DISTINCT FROM 'link_selected' OR command->>'existing_customer_id' IS DISTINCT FROM d->>'selectedCustomerId' OR command->>'existing_site_id' IS DISTINCT FROM d->>'selectedSiteId' OR command->>'existing_metering_point_id' IS DISTINCT FROM d->>'selectedMeteringPointId') THEN RAISE EXCEPTION 'prodat_object_batch_choice_required';END IF;
  PERFORM gridex_prodat_object_batch.require_wire_projection_v1(source.raw_payload,own,command,d->>'mode',actor);
  i:=i+1;
 END LOOP;
END $_$;

--
-- Name: require_receipts_v1(public.ediel_inbound_cases, jsonb, jsonb); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_receipts_v1(row_case public.ediel_inbound_cases, plan jsonb, proof jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;r gridex_prodat_object_batch.graph_receipts%rowtype;op public.customer_onboarding_operations%rowtype;key text;idx int;BEGIN
 IF (SELECT count(DISTINCT e->>'key') FROM jsonb_array_elements(plan->'receipts')e)<>jsonb_array_length(plan->'receipts') THEN RAISE EXCEPTION 'prodat_object_batch_duplicate_receipt';END IF;
 FOR receipt IN SELECT value FROM jsonb_array_elements(plan->'receipts') LOOP
  key:=receipt->>'key';SELECT (ord-1)::int INTO idx FROM jsonb_array_elements(plan->'decisions') WITH ORDINALITY d(value,ord) WHERE gridex_prodat_object_batch.json_text_v1(jsonb_build_array(value->>'meteringPointId',value->>'identityAgency'))=key;
  SELECT * INTO r FROM gridex_prodat_object_batch.graph_receipts WHERE company_id=row_case.company_id AND case_id=row_case.id AND object_key=key;
  SELECT * INTO op FROM public.customer_onboarding_operations WHERE id=r.operation_id AND company_id=row_case.company_id AND channel='ediel_inbound' AND status='completed' FOR SHARE;
  IF idx IS NULL OR r.operation_id IS NULL OR op.id IS NULL OR r.source_message_id IS DISTINCT FROM row_case.ediel_message_id OR r.source_hash IS DISTINCT FROM proof->>'sourcePayloadHash'
   OR r.actor_user_id::text IS DISTINCT FROM plan->>'originalActorId' OR r.command_hash IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(plan#>ARRAY['commands',idx::text])
   OR r.result_hash IS DISTINCT FROM gridex_prodat_object_batch.hash_v1(op.result_snapshot) OR op.result_snapshot IS DISTINCT FROM receipt->'result' THEN RAISE EXCEPTION 'prodat_object_batch_native_receipt_required';END IF;
 END LOOP;
END $$;

--
-- Name: require_review_v1(public.ediel_inbound_cases, jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_review_v1(row_case public.ediel_inbound_cases, plan jsonb, proof jsonb, actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r gridex_prodat_object_batch.review_receipts%rowtype;BEGIN
 SELECT * INTO r FROM gridex_prodat_object_batch.review_receipts WHERE company_id=row_case.company_id AND case_id=row_case.id;
 IF r.case_id IS NULL OR r.source_message_id IS DISTINCT FROM row_case.ediel_message_id OR r.environment IS DISTINCT FROM proof#>>'{sourceMessage,environment}' OR r.source_hash IS DISTINCT FROM proof->>'sourcePayloadHash'
  OR r.actor_user_id IS DISTINCT FROM actor OR r.actor_user_id IS DISTINCT FROM row_case.reviewed_by OR r.fingerprint IS DISTINCT FROM plan->>'fingerprint' OR r.command_hash IS DISTINCT FROM plan->>'commandHash'
  OR row_case.reviewed_at IS NULL OR row_case.reviewed_at IS DISTINCT FROM r.recorded_at THEN RAISE EXCEPTION 'prodat_object_batch_native_review_required';END IF;
END $$;

--
-- Name: require_service_v1(); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_service_v1() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'prodat_object_batch_service_required' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: require_wire_projection_v1(text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_wire_projection_v1(raw text, own jsonb, command jsonb, mode text, actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);raw_parts jsonb:=gridex_prodat_object_batch.raw_segments_v1(raw);t jsonb;e jsonb;first_index int:=(own#>>'{registers,0,segmentIndex}')::int;next_index int;
 ud jsonb;it jsonb;qty text;start_day text;frequency text;product text;reference text;area text;grid_id uuid;characteristic text;name text;personal text;org text;is_business bool;key text;expected jsonb;field_value jsonb;reg jsonb;wire_reg jsonb;reg_end int;reg_raw jsonb;reg_qty text;BEGIN
 IF tokens IS NULL THEN RAISE EXCEPTION 'prodat_object_batch_physical_projection_required';END IF;
 SELECT min((x->>'index')::int) INTO next_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>first_index;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>first_index AND (x->>'index')::int<next_index ORDER BY(x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN ud:=e;ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='IT' THEN it:=e;
  ELSIF t->>'tag'='QTY' AND e#>>'{1,0}'='31' THEN qty:=e#>>'{1,1}';
  ELSIF t->>'tag'='DTM' AND e#>>'{1,0}'='92' THEN start_day:=e#>>'{1,1}';
  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z07' THEN reference:=e#>>'{1,1}';
  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z05' THEN area:=e#>>'{1,1}';
  ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
  ELSIF t->>'tag'='CAV' AND characteristic='Z12' THEN frequency:=e#>>'{1,3}';
  ELSIF t->>'tag'='CAV' AND characteristic='Z14' THEN product:=e#>>'{1,3}';END IF;
 END LOOP;
 FOR reg IN SELECT value FROM jsonb_array_elements(command#>'{application,payload_snapshot,prodatRegisters}') LOOP
  SELECT x INTO wire_reg FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x#>>'{elements,1,0}'=reg->>'lineSequenceNumber';
  SELECT min((x->>'index')::int) INTO reg_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>(wire_reg->>'index')::int;
  SELECT jsonb_agg(raw_parts->((x->>'index')::int) ORDER BY(x->>'index')::int) INTO reg_raw FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>=(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;
  SELECT btrim(x#>>'{elements,1,1}') INTO reg_qty FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='QTY' AND x#>>'{elements,1,0}'='31' AND(x->>'index')::int>(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;
  IF wire_reg IS NULL OR wire_reg#>>'{elements,3,0}' IS DISTINCT FROM own->>'objectId' OR wire_reg#>>'{elements,3,3}' IS DISTINCT FROM own->>'identityAgency'
   OR reg->>'meteringPointId' IS DISTINCT FROM own->>'objectId' OR reg->>'identityAgency' IS DISTINCT FROM own->>'identityAgency'
   OR reg->'rawSegments' IS DISTINCT FROM reg_raw OR reg->>'annualConsumption' IS DISTINCT FROM reg_qty OR reg->>'registerIndex' IS DISTINCT FROM nullif(wire_reg#>>'{elements,4,1}','')
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(own->'registers')r WHERE r->'lineIndex'=reg->'sourceOrder' AND r->>'lineNumber'=reg->>'lineSequenceNumber' AND r->'segmentIndex'=wire_reg->'index') THEN RAISE EXCEPTION 'prodat_object_batch_physical_register_required';END IF;
 END LOOP;
 IF mode='link_existing_only' THEN
  IF command->'customer'<>'{}'::jsonb OR command->'site' IS DISTINCT FROM jsonb_build_object('facility_id',own->>'objectId') OR command->'metering_point' IS DISTINCT FROM jsonb_build_object('meter_point_id',own->>'objectId') OR command->'update_existing' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_link_identity_only_required';END IF;RETURN;
 END IF;
 IF area IS NOT NULL THEN SELECT id INTO grid_id FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area FOR SHARE;
  IF (SELECT count(*) FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area)>1 THEN RAISE EXCEPTION 'prodat_object_batch_grid_namespace_ambiguous';END IF;END IF;
 IF command#>'{site,grid_owner_id}' IS NOT NULL AND command#>'{site,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) OR command#>'{metering_point,grid_owner_id}' IS NOT NULL AND command#>'{metering_point,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) THEN RAISE EXCEPTION 'prodat_object_batch_wire_grid_owner_required';END IF;
 SELECT string_agg(btrim(v#>>'{}'),E'\n' ORDER BY ord) INTO name FROM jsonb_array_elements(coalesce(ud->4,'[]')) WITH ORDINALITY n(v,ord) WHERE ord<=2 AND btrim(v#>>'{}')<>'';
 is_business:=ud#>>'{2,1}'='SE1';
 IF ud#>>'{2,0}'~'^[0-9]+([-+][0-9]+)?$' THEN
  IF ud#>>'{2,1}'='SE1' THEN org:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');ELSIF ud#>>'{2,1}'='SE2' THEN personal:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');END IF;
 END IF;
 expected:=jsonb_build_object('customer_type',CASE WHEN is_business THEN 'business' ELSE 'private' END,'full_name',coalesce(name,'Ediel inbound-kund'),'company_name',CASE WHEN is_business THEN name END,
  'first_name',CASE WHEN NOT coalesce(is_business,false) THEN split_part(name,' ',1) END,'last_name',CASE WHEN NOT coalesce(is_business,false) THEN nullif(substr(name,strpos(name,' ')+1),name) END,'personal_number',personal,'org_number',org);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'customer') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_customer_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','source','metadata','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_customer_field_not_source_bound';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key='source' AND field_value IS DISTINCT FROM '"ediel_inbound"'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_customer_binding_required';END IF;
  IF key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
 END LOOP;
 expected:=jsonb_build_object('site_name','Ediel '||(own->>'objectId'),'facility_id',own->>'objectId','site_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,
  'street',CASE WHEN it IS NOT NULL THEN array_to_string(ARRAY(SELECT btrim(v#>>'{}') FROM jsonb_array_elements(it->5) WITH ORDINALITY a(v,ord) WHERE ord<=3 AND btrim(v#>>'{}')<>''),E'\n') END,
  'postal_code',nullif(it#>>'{8,0}',''),'city',nullif(it#>>'{6,0}',''),'country',coalesce(nullif(it#>>'{9,0}',''),'SE'),
  'annual_consumption_kwh',CASE WHEN qty IS NOT NULL THEN replace(qty,',','.')::numeric END,'move_in_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'site') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_site_required';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','internal_notes','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_site_field_not_source_bound';END IF;
 END LOOP;
 expected:=jsonb_build_object('meter_point_id',own->>'objectId','metering_point_id',own->>'objectId','site_facility_id',own->>'objectId','ediel_reference',reference,
  'measurement_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,'reading_frequency',CASE frequency WHEN 'D' THEN 'daily' WHEN 'M' THEN 'monthly' ELSE 'hourly' END,
  'start_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END,'is_settlement_relevant',true);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'metering_point') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_meter_required';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_meter_field_not_source_bound';END IF;
 END LOOP;
END $_$;

--
-- Name: source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.source_v1(c uuid, source_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;
 f gridex_received_sources.prodat_object_validation_facets%rowtype;r gridex_received_sources.prodat_response_facets%rowtype;app jsonb;ctx jsonb;own jsonb;fullown jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(actor,c,'communication.write') IS NOT TRUE
  OR public.gridex_actor_has_company_permission(actor,c,'customers.write') IS NOT TRUE THEN RAISE EXCEPTION 'prodat_object_batch_current_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=source_id AND company_id=c AND environment=m.environment FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.raw_payload IS NULL
  OR s.source_message_id IS NULL OR s.origin IS DISTINCT FROM 'database_insert' OR s.raw_payload IS DISTINCT FROM m.raw_payload
  OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR s.message_code IS DISTINCT FROM m.message_code
  OR s.source_received_at IS NULL OR s.source_received_at IS DISTINCT FROM m.message_received_at
  OR s.received_context IS DISTINCT FROM m.execution_context_snapshot->'receivedProdatContext'
  OR s.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' OR s.received_context->>'payloadHash' IS DISTINCT FROM s.payload_hash
  OR s.received_context->>'sourceMessageId' IS DISTINCT FROM m.id::text OR s.received_context->>'companyId' IS DISTINCT FROM c::text
  OR s.received_context->>'environment' IS DISTINCT FROM m.environment OR s.received_context->>'messageCode' IS DISTINCT FROM m.message_code
  OR (s.received_context->>'sourceReceivedAt')::timestamptz IS DISTINCT FROM s.source_received_at THEN RAISE EXCEPTION 'prodat_object_batch_immutable_original_required';END IF;
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id);
 IF ctx->>'actorRole' IS DISTINCT FROM 'electricity_supplier' THEN RAISE EXCEPTION 'prodat_object_batch_current_receiver_role_required';END IF;
 app:=gridex_received_sources.require_prodat_application_objects_v1(c,m.id);
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=(app->>'assessmentId')::uuid AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash FOR SHARE;
 SELECT * INTO f FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=a.id AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash;
 SELECT * INTO r FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash;
 IF a.id IS NULL OR f.assessment_id IS NULL OR r.assessment_id IS NULL OR f.facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.facts_text,'UTF8')),'hex')
  OR r.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.response_facts_text,'UTF8')),'hex') OR f.facts_text::jsonb->>'sharedAccepted' IS DISTINCT FROM 'true'
  OR a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR app->>'headerDecision' IS DISTINCT FROM 'accepted' OR jsonb_array_length(app->'objects') NOT BETWEEN 2 AND 16
  OR jsonb_array_length(app->'objects') IS DISTINCT FROM jsonb_array_length(f.facts_text::jsonb->'objects') THEN RAISE EXCEPTION 'prodat_object_batch_complete_own_facets_required';END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(app->'objects') LOOP
  SELECT value INTO fullown FROM jsonb_array_elements(f.facts_text::jsonb->'objects') WHERE value->>'objectId'=own->>'objectId' AND value->>'identityAgency'=own->>'identityAgency' AND value->>'messageReference'=own->>'messageReference' AND value->'firstLineIndex'=own#>'{registers,0,lineIndex}';
  IF own->>'applicationDecision' IS DISTINCT FROM 'accepted' OR fullown->>'disposition' IS DISTINCT FROM 'accepted'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(r.response_facts_text::jsonb->'objects') o WHERE o->>'id'=own->>'objectId' AND o->>'li' IS NOT DISTINCT FROM fullown->>'lineItemReference' AND o->'lineIndex'=own#>'{registers,0,segmentIndex}' AND o->>'outcome'='positive')
   OR EXISTS(SELECT FROM jsonb_array_elements(r.response_facts_text::jsonb->'responses') o WHERE o->>'ercCode'<>'100' AND(o->>'scope'='message' OR o->'lineIndex'=own#>'{registers,0,segmentIndex}')) THEN RAISE EXCEPTION 'prodat_object_batch_own_accepted_partition_required';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT o->>'objectId') FROM jsonb_array_elements(app->'objects')o)<>jsonb_array_length(app->'objects') THEN RAISE EXCEPTION 'prodat_object_batch_namespace_unsupported';END IF;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(m),'sourcePayloadHash',s.payload_hash,'assessmentId',a.id,'applicationValidation',app-'assessmentId');
END $$;

--
-- Name: bind_final_v1(); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.bind_final_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;tx text;prior gridex_received_err_response.final_responses%rowtype;
BEGIN
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'APERAK' THEN RETURN NEW;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=NEW.related_message_id AND company_id=NEW.company_id AND environment=NEW.environment AND direction='inbound' FOR UPDATE;
 IF source.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN RETURN NEW;END IF;
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(NEW,false);a:=gridex_ack_authority.wire_v1(NEW.raw_payload);
 FOR tx IN SELECT jsonb_array_elements_text(a#>'{refs,ACW}') LOOP
  SELECT * INTO prior FROM gridex_received_err_response.final_responses WHERE source_message_id=source.id AND transaction_id=tx;
  IF FOUND AND (prior.ack_message_id IS DISTINCT FROM NEW.id OR prior.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'utilts_err_application_response_final_scope_conflict' USING ERRCODE='23505';END IF;
  IF NOT FOUND THEN INSERT INTO gridex_received_err_response.final_responses(source_message_id,transaction_id,company_id,environment,ack_message_id,ack_payload_hash) VALUES(source.id,tx,NEW.company_id,NEW.environment,NEW.id,encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'));END IF;
 END LOOP;
 RETURN NEW;
END $$;

--
-- Name: capture_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.capture_v1(p_company uuid, p_environment text, p_source uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c gridex_ack_authority.source_correlations%rowtype;m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;
 captured gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;
 facts jsonb;evidence jsonb;expected jsonb;wire jsonb;source_wire jsonb;transactions jsonb;context jsonb;
BEGIN
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_source;
 SELECT * INTO original FROM public.ediel_messages WHERE id=c.source_message_id FOR SHARE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR UPDATE;
 IF EXISTS(SELECT FROM gridex_received_err_response.receipts WHERE source_message_id=p_source) THEN PERFORM gridex_received_err_response.require_v1(p_company,p_environment,p_source);RETURN;END IF;
 SELECT * INTO captured FROM gridex_received_sources.sources WHERE source_message_id=m.id;
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=c.canonical_assessment_id;
 wire:=gridex_ack_authority.wire_v1(m.raw_payload);source_wire:=gridex_ack_authority.wire_v1(original.raw_payload);
 IF m.id IS NULL OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' OR m.message_standard IS DISTINCT FROM 'edifact' OR c.ack_family IS DISTINCT FROM 'UTILTS_ERR'
  OR c.company_id IS DISTINCT FROM p_company OR c.environment IS DISTINCT FROM p_environment OR c.ack_outcome IS DISTINCT FROM 'negative'
  OR original.id IS NULL OR original.company_id IS DISTINCT FROM p_company OR original.environment IS DISTINCT FROM p_environment OR original.direction IS DISTINCT FROM 'outbound'
  OR original.message_sent_at IS NULL OR original.immutable_rendered_at IS NULL OR c.source_payload_hash IS DISTINCT FROM original.immutable_payload_hash
  OR c.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex')
  OR c.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR captured.raw_payload IS DISTINCT FROM m.raw_payload
  OR captured.company_id IS DISTINCT FROM p_company OR captured.environment IS DISTINCT FROM p_environment OR captured.payload_hash IS DISTINCT FROM c.ack_payload_hash OR captured.received_context IS NULL
  OR a.id IS NULL OR a.source_message_id IS DISTINCT FROM m.id OR a.company_id IS DISTINCT FROM p_company OR a.environment IS DISTINCT FROM p_environment OR a.source_payload_hash IS DISTINCT FROM c.ack_payload_hash
  OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
  OR a.xmin::text::numeric=mod(pg_current_xact_id()::text::numeric,4294967296)
  OR wire IS NULL OR wire->>'family' IS DISTINCT FROM 'UTILTS' OR wire->>'code' IS DISTINCT FROM 'ERR' OR NOT coalesce(gridex_ack_authority.source_match_v1(wire,source_wire),false)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 facts:=a.facts_text::jsonb;evidence:=gridex_ediel_source_rules.require_v1(p_company,original.id);
 expected:=jsonb_build_object('profileKey',evidence->'profileKey','messageProfileId',evidence->'messageProfileId','rulePackId',evidence->'rulePackId','sourceHash',evidence->'sourceHash','version',evidence->'version',
  'snapshot',jsonb_build_object('rulePack',evidence#>'{snapshot,rulePack}','messageProfile',evidence#>'{snapshot,messageProfile}','guideSources',evidence#>'{snapshot,guideSources}'));
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR facts->>'applicationDecision' IS DISTINCT FROM 'accepted'
  OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted' OR facts->'rulePackEvidence' IS DISTINCT FROM expected
  OR jsonb_typeof(wire->'ide') IS DISTINCT FROM 'array' OR jsonb_array_length(wire->'ide')=0
  OR EXISTS(SELECT FROM jsonb_array_elements_text(wire->'ide')t WHERE nullif(t,'') IS NULL)
  OR (SELECT count(*) FROM jsonb_array_elements_text(wire->'ide'))<>(SELECT count(DISTINCT t) FROM jsonb_array_elements_text(wire->'ide')t)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 SELECT jsonb_agg(jsonb_build_object('transactionIndex',n-1,'transactionId',t) ORDER BY n) INTO transactions FROM jsonb_array_elements_text(wire->'ide') WITH ORDINALITY x(t,n);
 -- The source's actual local outbound endpoint already had an immutable legal
 -- authority. Full physical reversal was proved by the correlation owner;
 -- this does not choose a current role or change the held receipt at insertion.
 context:=gridex_ediel_inbound_context.require_v1(p_company,original.id);
 IF context->>'transportEdielId' IS DISTINCT FROM wire#>>'{receiver,0}' OR context->>'legalEdielId' IS DISTINCT FROM wire->>'legalReceiver'
  OR context->>'applicationReference' IS DISTINCT FROM wire->>'app' THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 context:=context||jsonb_build_object('basisKind','accepted_received_err_application','companyId',p_company,'environment',p_environment,'direction','inbound',
  'family','UTILTS_ERR','code','ERR','wireFamily','UTILTS','wireCode','ERR','observedAt',c.correlated_at,'sourceReceivedAt',m.message_received_at,
  'correlatedOriginalMessageId',original.id,'canonicalAssessmentId',a.id,'sourceHash',c.ack_payload_hash,'authorizesBusinessEffect',false);
 INSERT INTO gridex_received_err_response.receipts VALUES(m.id,p_company,p_environment,c.ack_payload_hash,a.id,original.id,evidence,transactions,context,c.correlated_at);
 INSERT INTO gridex_ediel_source_rules.receipts(source_message_id,company_id,environment,direction,payload_sha256,canonical_assessment_id,original_source_message_id,evidence)
  VALUES(m.id,p_company,p_environment,'inbound',c.ack_payload_hash,a.id,original.id,evidence);
 PERFORM gridex_ediel_ack_guide.bind_source_v1(m,'national',evidence);
END $$;

--
-- Name: require_positive_before_received_err_v1(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.require_positive_before_received_err_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_transaction_id text, p_ack_message_id uuid DEFAULT NULL::uuid, p_ack_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 source public.ediel_messages%rowtype; ack public.ediel_messages%rowtype;
 receipt gridex_utilts_binding.receipts%rowtype; origin gridex_utilts_binding.receipts%rowtype;
 reservation public.ediel_ack_transaction_results%rowtype;
 series public.meter_reading_series%rowtype; stored gridex_utilts_binding.contracts%rowtype;
 tokens jsonb; ack_tokens jsonb; source_hash text; ack_hash text; document_id text;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_source_message_id IS NULL
 OR nullif(p_transaction_id,'') IS NULL OR (p_ack_message_id IS NULL)<>(p_ack_raw_payload IS NULL) THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01';
 END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
 IF NOT FOUND OR source.direction<>'inbound' OR source.message_family<>'UTILTS' OR source.raw_payload IS NULL THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 source_hash:=encode(digest(convert_to(source.raw_payload,'UTF8'),'sha256'),'hex');
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=source.id;
 IF NOT FOUND OR receipt.company_id IS DISTINCT FROM p_company_id OR receipt.environment IS DISTINCT FROM p_environment
 OR receipt.raw_hash IS DISTINCT FROM source_hash OR receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(source)
 OR NOT receipt.membership ? p_transaction_id THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,1,0}'='24' AND t#>>'{elements,2,0}'=p_transaction_id)<>1 THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=p_company_id AND environment=p_environment
  AND source_message_id=source.id AND source_transaction_id=p_transaction_id FOR SHARE;
 IF NOT FOUND OR reservation.disposition IS DISTINCT FROM 'accepted' OR reservation.planned_response_type IS DISTINCT FROM 'positive_aperak'
 OR reservation.persistence_status IS DISTINCT FROM 'persisted' OR reservation.persisted_series_id IS NULL
 OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'positive_aperak') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO series FROM public.meter_reading_series WHERE id=reservation.persisted_series_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR series.message_code IS DISTINCT FROM source.message_code OR series.source_transaction_reference IS DISTINCT FROM p_transaction_id
 OR jsonb_typeof(series.raw_transaction) IS DISTINCT FROM 'object'
 OR series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(series.raw_transaction::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 -- Identical old/late accepted data can legitimately reuse an earlier series.
 -- Its genuine source/contract origin stays authoritative; is_current is not an
 -- acceptance criterion and must not silently reject old-late-positive ACKs.
 SELECT * INTO origin FROM gridex_utilts_binding.receipts WHERE source_message_id=series.source_ediel_message_id;
 SELECT * INTO stored FROM gridex_utilts_binding.contracts WHERE series_id=series.id;
 IF origin.source_message_id IS NULL OR stored.series_id IS NULL OR origin.company_id IS DISTINCT FROM p_company_id
 OR origin.environment IS DISTINCT FROM p_environment OR origin.message_code IS DISTINCT FROM source.message_code
 OR stored.company_id IS DISTINCT FROM p_company_id OR stored.environment IS DISTINCT FROM p_environment
 OR stored.source_message_id IS DISTINCT FROM origin.source_message_id OR stored.transaction_id IS DISTINCT FROM p_transaction_id
 OR stored.contract_version NOT IN (1,2) OR stored.contract->>'version' IS DISTINCT FROM stored.contract_version::text
 OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(stored.contract),false)
 OR stored.contract_hash IS DISTINCT FROM encode(digest(convert_to(stored.contract::text,'UTF8'),'sha256'),'hex')
 OR stored.contract IS DISTINCT FROM series.raw_transaction->'consumptionContract' THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 IF p_ack_message_id IS NOT NULL THEN
  SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
  IF NOT FOUND OR ack.direction<>'outbound' OR ack.message_family<>'APERAK' OR ack.related_message_id IS DISTINCT FROM source.id
  OR ack.raw_payload IS DISTINCT FROM p_ack_raw_payload OR reservation.final_response_type IS DISTINCT FROM 'positive_aperak'
  OR reservation.response_message_id IS DISTINCT FROM ack.id OR reservation.finalized_at IS NULL THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  SELECT t#>>'{elements,2,0}' INTO document_id FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  IF ack_tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='UNH'
    AND t#>>'{elements,2,0}'='APERAK' AND t#>>'{elements,2,2}'='04A' AND t#>>'{elements,2,4}'='E5SE5A')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='312')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)<>1
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM')
      <>(SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW')
   OR EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       AND (nullif(t#>>'{elements,1,1}','') IS NULL OR length(t#>>'{elements,1,1}')>35 OR btrim(t#>>'{elements,1,1}') IS DISTINCT FROM t#>>'{elements,1,1}'))
   OR EXISTS(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       GROUP BY t#>>'{elements,1,1}' HAVING count(*)>1)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='DOC' AND t#>>'{elements,2,0}'=document_id)<>1 THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_hash:=encode(digest(convert_to(ack.raw_payload,'UTF8'),'sha256'),'hex');
 END IF;
 RETURN jsonb_build_object('authorityVersion',1,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',source.id,
  'transactionId',p_transaction_id,'sourceRawHash',source_hash,'ackMessageId',p_ack_message_id,'ackRawHash',ack_hash);
END $$;

--
-- Name: require_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.require_v1(p_company uuid, p_environment text, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_received_err_response.receipts%rowtype;c gridex_ack_authority.source_correlations%rowtype;m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR SHARE;
 SELECT * INTO r FROM gridex_received_err_response.receipts WHERE source_message_id=p_source;
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_source;
 IF m.id IS NULL OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' OR r.source_message_id IS NULL OR c.ack_family IS DISTINCT FROM 'UTILTS_ERR'
  OR r.company_id IS DISTINCT FROM m.company_id OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR r.payload_hash IS DISTINCT FROM c.ack_payload_hash OR c.company_id IS DISTINCT FROM r.company_id OR c.environment IS DISTINCT FROM r.environment
  OR r.canonical_assessment_id IS DISTINCT FROM c.canonical_assessment_id OR r.correlated_original_message_id IS DISTINCT FROM c.source_message_id
  OR r.evidence IS DISTINCT FROM gridex_ediel_source_rules.require_v1(p_company,c.source_message_id)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(m),'sourceRulePackEvidence',r.evidence,'sourceHash',r.payload_hash,
  'canonicalAssessmentId',r.canonical_assessment_id,'correlatedOriginalMessageId',r.correlated_original_message_id,'transactions',r.transactions,
  'localContext',r.local_context,'observedAt',r.observed_at,'authorizesBusinessEffect',false);
END $$;

--
-- Name: applied_source_v1(); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.applied_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior_source uuid;BEGIN
 PERFORM gridex_received_reading_expectations.capture_source_v1(NEW.company_id,NEW.environment,NEW.source_message_id);
 IF jsonb_array_length(gridex_received_reading_expectations.source_contracts_v1(NEW.company_id,NEW.environment,NEW.source_message_id))>0 THEN
  FOR prior_source IN SELECT r.source_message_id FROM gridex_utilts_binding.receipts r WHERE r.company_id=NEW.company_id AND r.environment=NEW.environment ORDER BY r.source_message_id LOOP
   PERFORM gridex_received_reading_expectations.consider_utilts_source_v1(NEW.company_id,NEW.environment,prior_source);
  END LOOP;
 END IF;RETURN NEW;END$$;

--
-- Name: apply_before_live_followup_v1(uuid, uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.apply_before_live_followup_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_object_line_indices integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;src gridex_received_sources.sources%rowtype;
 canonical gridex_received_sources.validation_assessments%rowtype;assessment gridex_received_sources.object_assessments%rowtype;
 prior gridex_received_sources.structural_apply_receipts%rowtype;entry jsonb;business jsonb;wire jsonb;tokens jsonb;own_tokens jsonb;
 objects jsonb:='[]';counted integer;reg jsonb;lin jsonb;point public.metering_points%rowtype;site public.customer_sites%rowtype;
 line_start integer;line_end integer;physical_count integer;effective_at timestamptz;result jsonb;applied_count integer:=0;period_preflight jsonb;locked_periods jsonb;application jsonb;selected jsonb:='[]';manifest jsonb:='[]';own_effect jsonb;first_line integer;scope_key text;requested integer[];
 batch gridex_received_sources.structural_apply_batches%rowtype;own_prior gridex_received_sources.structural_object_apply_receipts%rowtype;skipped_count integer:=0;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'structural_apply_service_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR (m.message_code IN ('Z06','Z10')) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_source_required'; END IF;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write'),false) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO prior FROM gridex_received_sources.structural_apply_receipts WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.environment IS DISTINCT FROM m.environment OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'structural_apply_replay_conflict'; END IF;
  RETURN prior.result;
 END IF;
 IF p_object_line_indices IS NOT NULL AND (cardinality(p_object_line_indices) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(p_object_line_indices) n WHERE n IS NULL OR n<0) OR cardinality(p_object_line_indices)<>(SELECT count(DISTINCT n) FROM unnest(p_object_line_indices)n)) THEN RAISE EXCEPTION 'structural_apply_requested_scope_invalid';END IF;
 SELECT array_agg(n ORDER BY n) INTO requested FROM unnest(p_object_line_indices)n;
 scope_key:=CASE WHEN p_object_line_indices IS NULL THEN 'all_source_objects' ELSE encode(sha256(convert_to(to_jsonb(requested)::text,'UTF8')),'hex') END;
 SELECT * INTO batch FROM gridex_received_sources.structural_apply_batches WHERE source_message_id=m.id AND requested_scope_key=scope_key;
 IF FOUND THEN
  IF batch.company_id IS DISTINCT FROM m.company_id OR batch.environment IS DISTINCT FROM m.environment OR batch.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'structural_apply_replay_conflict';END IF;
  RETURN batch.result;
 END IF;
 -- A differently requested read of already established own receipts is
 -- still replay. It must not acquire today's role/rule basis as new authority.
 IF requested IS NOT NULL AND cardinality(requested)=(SELECT count(*) FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested)) THEN
  IF EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested) AND(r.company_id IS DISTINCT FROM m.company_id OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'))) THEN RAISE EXCEPTION 'structural_apply_object_replay_conflict';END IF;
  SELECT jsonb_agg(r.effect ORDER BY r.first_line_index),sum(jsonb_array_length(r.object_scope->'registers')),jsonb_agg(jsonb_build_object('object',r.object_scope,'status','already_applied') ORDER BY r.first_line_index)
   INTO objects,applied_count,manifest FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested);
  RETURN jsonb_build_object('applied',true,'appliedCount',applied_count,'skippedCount',0,'objects',objects,'sourceMessageId',m.id,'manifest',manifest);
 END IF;
 -- Current admission cannot relabel an already committed source outcome.
 PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=p_company_id AND environment=m.environment FOR UPDATE;
 IF NOT FOUND OR src.raw_payload IS DISTINCT FROM m.raw_payload OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR src.source_received_at IS NULL OR src.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'structural_apply_immutable_source_required'; END IF;
 SELECT count(*) INTO counted FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
 IF counted<>1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_canonical_source_ambiguous'); END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 application:=gridex_received_sources.require_prodat_application_objects_v1(p_company_id,m.id);
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR application->>'assessmentId' IS DISTINCT FROM canonical.id::text OR application->>'headerDecision' IS DISTINCT FROM 'accepted' THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_canonical_source_not_accepted');END IF;
 SELECT count(*) INTO counted FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id);
 IF counted<>1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_original_review_required'); END IF;
 SELECT * INTO assessment FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF assessment.canonical_assessment_id IS DISTINCT FROM canonical.id OR jsonb_typeof(assessment.facts_text::jsonb->'objects') IS DISTINCT FROM 'array'
  OR jsonb_array_length(assessment.facts_text::jsonb->'objects')<1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_original_review_required'); END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(src.raw_payload);
 IF tokens IS NULL THEN RAISE EXCEPTION 'structural_apply_whole_wire_required'; END IF;
 SELECT count(*) INTO physical_count FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
 -- The owner assessment must cover every physical object/register, with no
 -- caller-provided changes, entity IDs, field labels or partial object writes.
 IF (SELECT coalesce(sum(jsonb_array_length(e#>'{object,registers}')),0) FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects') e)<>physical_count THEN RAISE EXCEPTION 'structural_apply_physical_scope_incomplete'; END IF;
 -- Keep the complete physical partition. Only SAME full application AND
 -- actual source-specific business/party owner can qualify a first effect.
 IF requested IS NOT NULL AND EXISTS(SELECT FROM unnest(requested)n WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects')e WHERE (e#>>'{object,registers,0,segmentIndex}')::integer=n)) THEN RAISE EXCEPTION 'structural_apply_requested_scope_invalid';END IF;
 FOR entry IN SELECT e FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects')e LOOP
  first_line:=(entry#>>'{object,registers,0,segmentIndex}')::integer;
  IF requested IS NOT NULL AND NOT first_line=ANY(requested) THEN
   manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','not_requested'));skipped_count:=skipped_count+jsonb_array_length(entry#>'{object,registers}');CONTINUE;
  END IF;
  SELECT * INTO own_prior FROM gridex_received_sources.structural_object_apply_receipts WHERE source_message_id=m.id AND first_line_index=first_line;
  IF FOUND THEN
   IF own_prior.company_id IS DISTINCT FROM m.company_id OR own_prior.environment IS DISTINCT FROM m.environment OR own_prior.payload_hash IS DISTINCT FROM src.payload_hash OR own_prior.object_scope IS DISTINCT FROM entry->'object' THEN RAISE EXCEPTION 'structural_apply_object_replay_conflict';END IF;
   objects:=objects||jsonb_build_array(own_prior.effect);applied_count:=applied_count+jsonb_array_length(entry#>'{object,registers}');
   manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','already_applied'));CONTINUE;
  END IF;
  IF entry->>'disposition'='accepted' AND coalesce(gridex_received_sources.prodat_application_object_accepted_v1(p_company_id,m.id,canonical.id,entry->'object'),false) THEN
   IF entry#>>'{business,owner}' IS DISTINCT FROM 'reviewed-received-structure-v1' OR(entry#>>'{business,wire,businessCase}' IN('change_with_reading','change_without_reading','meter_exchange')) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_original_review_required';END IF;
   selected:=selected||jsonb_build_array(entry);
  ELSE
   IF requested IS NOT NULL THEN RAISE EXCEPTION 'structural_apply_requested_object_not_qualified';END IF;
   skipped_count:=skipped_count+jsonb_array_length(entry#>'{object,registers}');manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status',CASE WHEN entry->>'disposition'='rejected' THEN 'rejected' ELSE 'held' END));
  END IF;
 END LOOP;
 IF jsonb_array_length(selected)=0 AND applied_count=0 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_no_qualified_object','manifest',manifest);END IF;
 -- Follow the normal supply commit order: original inbound baselines first,
 -- then their originating outbound requests, switches, periods, points/sites.
 -- Acquire whole-message sets before proof evaluation to prevent a concurrent
 -- cancellation/activation from changing coverage halfway through an apply.
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',sp.id,'sourceId',sp.source_message_id,'version',sp.market_state_version) ORDER BY sp.id),'[]') INTO period_preflight
 FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e);
 PERFORM original.id FROM public.ediel_messages original WHERE original.company_id=p_company_id AND original.environment=m.environment AND original.id IN(
  SELECT (e#>>'{business,coverageWindow,baselineSourceMessageId}')::uuid FROM jsonb_array_elements(selected) e UNION
  SELECT (e#>>'{business,coverageWindow,outboundSourceMessageId}')::uuid FROM jsonb_array_elements(selected) e UNION
  SELECT (p->>'sourceId')::uuid FROM jsonb_array_elements(period_preflight) p UNION
  SELECT tr.source_message_id FROM gridex_received_sources.supply_source_transitions tr,jsonb_array_elements(tr.resulting_states) own,jsonb_array_elements(period_preflight) p
   WHERE tr.company_id=p_company_id AND own->>'id'=p->>'id' AND own->>'market_state_version'=p->>'version'
 ) ORDER BY original.id FOR UPDATE;
 PERFORM sw.id FROM public.supplier_switch_requests sw WHERE sw.company_id=p_company_id
  AND sw.id IN(SELECT (e#>>'{business,switchRequestId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY sw.id FOR UPDATE;
 PERFORM sp.id FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id
  AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY sp.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',sp.id,'sourceId',sp.source_message_id,'version',sp.market_state_version) ORDER BY sp.id),'[]') INTO locked_periods
 FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e);
 IF locked_periods IS DISTINCT FROM period_preflight THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_supply_version_changed_retry'); END IF;
 PERFORM mp.id FROM public.metering_points mp WHERE mp.company_id=p_company_id
  AND mp.id IN(SELECT (e#>>'{business,meteringPointId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY mp.id FOR UPDATE;
 PERFORM cs.id FROM public.customer_sites cs WHERE cs.company_id=p_company_id
  AND cs.id IN(SELECT (e#>>'{business,siteId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY cs.id FOR UPDATE;
 FOR entry IN SELECT e FROM jsonb_array_elements(selected) e ORDER BY e#>>'{business,meteringPointId}' LOOP
  business:=entry->'business';wire:=business->'wire';
  IF entry->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
   OR (wire->>'businessCase' IN ('change_with_reading','change_without_reading','meter_exchange')) IS NOT TRUE
   OR gridex_received_sources.review_business_proof_consistent(entry->'party',business,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_original_review_required';END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=(business->>'meteringPointId')::uuid AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR point.meter_point_id IS DISTINCT FROM entry#>>'{object,objectId}' OR point.customer_id IS DISTINCT FROM (business->>'customerId')::uuid
   OR point.site_id IS DISTINCT FROM (business->>'siteId')::uuid THEN RAISE EXCEPTION 'structural_apply_point_scope_unqualified'; END IF;
  SELECT * INTO site FROM public.customer_sites WHERE id=point.site_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR site.customer_id IS DISTINCT FROM point.customer_id THEN RAISE EXCEPTION 'structural_apply_site_scope_unqualified'; END IF;
  effective_at:=(wire#>>'{effectiveFrom,utc}')::timestamptz;own_tokens:='[]';
  FOR reg IN SELECT r FROM jsonb_array_elements(entry#>'{object,registers}') r LOOP
   line_start:=(reg->>'segmentIndex')::integer;
   SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer=line_start;
   IF lin->>'tag' IS DISTINCT FROM 'LIN' OR lin#>>'{elements,3,0}' IS DISTINCT FROM entry#>>'{object,objectId}'
    OR lin#>>'{elements,3,3}' IS DISTINCT FROM entry#>>'{object,identityAgency}' OR lin#>>'{elements,1,0}' IS DISTINCT FROM reg->>'lineNumber' THEN RAISE EXCEPTION 'structural_apply_physical_scope_incomplete'; END IF;
   SELECT min((t->>'index')::integer) INTO line_end FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>line_start AND t->>'tag' IN ('LIN','UNT','UNZ','UNH');
   own_tokens:=own_tokens||jsonb_build_array(jsonb_build_object('register',reg,'tokens',(SELECT jsonb_agg(t ORDER BY (t->>'index')::integer) FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>=line_start AND (t->>'index')::integer<line_end)));
  END LOOP;
  -- The primary dated source ledger is used by structuralSourceSelection and
  -- the live UTILTS qualification boundary. Do not flatten its future/history
  -- versions into current global masterdata or alter any earlier meter values.
  own_effect:=jsonb_build_object('object',entry->'object','meteringPointId',point.id,'siteId',site.id,
   'effectiveAt',effective_at,'sourceReceivedAt',src.source_received_at,'wire',wire,'sourceRegisters',own_tokens,
   'readingFollowUp',jsonb_build_object('status',CASE WHEN wire->>'businessCase'='change_without_reading' THEN 'not_required_by_this_change' ELSE 'source_process_evidence_required' END,
    'criterion',CASE WHEN wire->>'businessCase'='change_without_reading' THEN 'AT-Z06G-SUPPLIER' WHEN wire->>'businessCase'='meter_exchange' THEN 'AT-Z10M-SUPPLIER' ELSE 'AT-Z06F-SUPPLIER' END,
    'deadline',NULL,'fulfilled',false));
  first_line:=(entry#>>'{object,registers,0,segmentIndex}')::integer;
  INSERT INTO gridex_received_sources.structural_object_apply_receipts(source_message_id,first_line_index,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,actor_user_id,source_received_at,object_scope,effect)
  VALUES(m.id,first_line,p_company_id,m.environment,src.payload_hash,canonical.id,assessment.id,p_actor_user_id,src.source_received_at,entry->'object',own_effect);
  objects:=objects||jsonb_build_array(own_effect);manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','applied'));
  applied_count:=applied_count+jsonb_array_length(entry#>'{object,registers}');
 END LOOP;
 result:=jsonb_build_object('applied',true,'appliedCount',applied_count,'objects',objects,'sourceMessageId',m.id,'objectAssessmentId',assessment.id,'canonicalAssessmentId',canonical.id,'skippedCount',skipped_count,'manifest',manifest);
 INSERT INTO gridex_received_sources.structural_apply_batches(source_message_id,requested_scope_key,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,result)
 VALUES(m.id,scope_key,p_company_id,m.environment,src.payload_hash,canonical.id,assessment.id,result);
 INSERT INTO public.ediel_message_events(company_id,ediel_message_id,message_id,event_type,event_status,message,payload,event_payload,created_by)
 VALUES(p_company_id,m.id,m.id,'manual_note','success','Granskad källbunden strukturversion tillämpad.',
  jsonb_build_object('safeApply',true,'safeApplyDecision','applied','appliedCount',applied_count,'sourceAssessmentId',assessment.id,'appliedAutomatically',false),
  jsonb_build_object('safeApply',true,'safeApplyDecision','applied','appliedCount',applied_count,'sourceAssessmentId',assessment.id,'appliedAutomatically',false),p_actor_user_id);
 RETURN result;
END $$;

--
-- Name: capture_source_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.capture_source_v1(c uuid, env text, msg uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE item jsonb;h text;prior gridex_received_reading_expectations.expectations%rowtype;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('z06f-reading:'||c::text||':'||env,0));
 FOR item IN SELECT value FROM jsonb_array_elements(gridex_received_reading_expectations.source_contracts_v1(c,env,msg)) LOOP
  h:=encode(sha256(convert_to(item::text,'UTF8')),'hex');
  SELECT * INTO prior FROM gridex_received_reading_expectations.expectations WHERE company_id=c AND environment=env AND source_message_id=msg AND first_line_index=(item->>'firstLineIndex')::int;
  IF FOUND THEN IF prior.contract IS DISTINCT FROM item OR prior.contract_hash IS DISTINCT FROM h THEN RAISE EXCEPTION 'z06f_reading_original_conflict';END IF;
  ELSE INSERT INTO gridex_received_reading_expectations.expectations(company_id,environment,source_message_id,first_line_index,contract,contract_hash) VALUES(c,env,msg,(item->>'firstLineIndex')::int,item,h);END IF;
 END LOOP;
END$$;

--
-- Name: consider_utilts_source_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.consider_utilts_source_v1(c uuid, env text, msg uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;prior_source uuid;tokens jsonb;membership jsonb;tx text;stored jsonb;start_at int;stop_at int;first_seq int;zone jsonb;offset_minutes int;
 header jsonb;sender text;receiver text;point text;agency text;reading jsonb;sequence record;own jsonb;register_id text;meter_id text;previous_register text;current_meter text;at timestamptz;dates jsonb;qty jsonb;
 e gridex_received_reading_expectations.expectations%rowtype;candidate_ids uuid[];receipt jsonb;matched bool;
BEGIN

 PERFORM pg_advisory_xact_lock(hashtextextended('z06f-reading:'||c::text||':'||env,0));
 SELECT * INTO m FROM public.ediel_messages WHERE id=msg AND company_id=c AND environment=env FOR SHARE SKIP LOCKED;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'UTILTS' OR(m.message_code IN('E30','E66','S07')) IS NOT TRUE THEN RETURN;END IF;
 SELECT r.membership INTO membership FROM gridex_utilts_binding.receipts r WHERE r.source_message_id=msg AND r.company_id=c AND r.environment=env;
 IF jsonb_typeof(membership) IS DISTINCT FROM 'array' THEN RETURN;END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);IF tokens IS NULL THEN RETURN;END IF;
 -- Whole binding is checked independently for EACH actual accepted member;
 -- a legitimate reused immutable origin series remains legitimate.
 FOR tx IN SELECT value FROM jsonb_array_elements_text(membership) LOOP
  BEGIN stored:=gridex_utilts_binding.stored_contract_v1(c,msg,tx);EXCEPTION WHEN SQLSTATE 'P0U01' THEN CONTINUE;END;
  IF stored->>'companyId' IS DISTINCT FROM c::text OR stored->>'environment' IS DISTINCT FROM env OR stored->>'transactionId' IS DISTINCT FROM tx THEN CONTINUE;END IF;
  SELECT(t->>'index')::int INTO STRICT start_at FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='IDE' AND t#>>'{elements,1,0}'='24' AND t#>>'{elements,2,0}'=tx;
  SELECT min((t->>'index')::int) INTO stop_at FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>start_at AND t->>'tag' IN('IDE','UNT');
  SELECT coalesce(min((t->>'index')::int),stop_at) INTO first_seq FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='SEQ' AND(t->>'index')::int>start_at AND(t->>'index')::int<stop_at;
  SELECT jsonb_agg(t ORDER BY(t->>'index')::int) INTO header FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>start_at AND(t->>'index')::int<first_seq;
  IF(SELECT count(*) FROM jsonb_array_elements(header)t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172')<>1 THEN CONTINUE;END IF;
  SELECT t#>>'{elements,2,0}',t#>>'{elements,2,2}' INTO point,agency FROM jsonb_array_elements(header)t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172';
  IF(agency IN('9','89')) IS NOT TRUE THEN CONTINUE;END IF;
  SELECT jsonb_agg(t) INTO zone FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='DTM' AND(t->>'index')::int<start_at AND t#>>'{elements,1,0}'='735';
  IF jsonb_array_length(zone) IS DISTINCT FROM 1 OR zone#>>'{0,elements,1,2}' IS DISTINCT FROM '406' OR zone#>>'{0,elements,1,1}'!~'^[+-][0-9]{4}$' THEN CONTINUE;END IF;
  IF substring(zone#>>'{0,elements,1,1}',2,2)::int>14 OR substring(zone#>>'{0,elements,1,1}',4,2)::int>59 THEN CONTINUE;END IF;
  offset_minutes:=(substring(zone#>>'{0,elements,1,1}',2,2)::int*60+substring(zone#>>'{0,elements,1,1}',4,2)::int)*CASE left(zone#>>'{0,elements,1,1}',1) WHEN '-' THEN -1 ELSE 1 END;
  IF abs(offset_minutes)>840 THEN CONTINUE;END IF;
  sender:=NULL;receiver:=NULL;
  IF(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS' AND(t->>'index')::int<start_at)<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MR' AND(t->>'index')::int<start_at)<>1 THEN CONTINUE;END IF;
  SELECT t#>>'{elements,2,0}' INTO sender FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS' AND(t->>'index')::int<start_at AND t#>>'{elements,2,1}'='SVK' AND t#>>'{elements,2,2}'='260';
  SELECT t#>>'{elements,2,0}' INTO receiver FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MR' AND(t->>'index')::int<start_at AND t#>>'{elements,2,1}'='SVK' AND t#>>'{elements,2,2}'='260';
  IF sender IS NULL OR receiver IS NULL THEN CONTINUE;END IF;
  -- Replay actual earlier applied owners through the same constructor. This
  -- derives new follow-up records from authentic retained effects, without
  -- backfilling source approvals, changing old receipts or trusting parsed rows.
  FOR prior_source IN SELECT DISTINCT source_message_id FROM(
   SELECT source_message_id,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND environment=env
   UNION ALL SELECT source_message_id,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND environment=env
  )r WHERE EXISTS(SELECT FROM jsonb_array_elements(r.objects)o WHERE o#>>'{object,objectId}'=point AND o#>>'{object,identityAgency}'=agency AND o#>>'{wire,businessCase}'='change_with_reading') LOOP
   PERFORM gridex_received_reading_expectations.capture_source_v1(c,env,prior_source);
  END LOOP;
  reading:='[]';previous_register:=NULL;current_meter:=NULL;
  FOR sequence IN SELECT(t->>'index')::int n,coalesce(lead((t->>'index')::int) OVER(ORDER BY(t->>'index')::int),stop_at) next_n FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='SEQ' AND(t->>'index')::int>start_at AND(t->>'index')::int<stop_at LOOP
   SELECT jsonb_agg(t ORDER BY(t->>'index')::int) INTO own FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>sequence.n AND(t->>'index')::int<sequence.next_n;
   SELECT jsonb_agg(t) INTO qty FROM jsonb_array_elements(own)t WHERE t->>'tag'='QTY' AND t#>>'{elements,1,0}'='220';
   IF qty IS NULL THEN CONTINUE;END IF;
   IF jsonb_array_length(qty)<>1 THEN reading:=NULL;EXIT;END IF;
   IF qty#>>'{0,elements,1,1}' IS NULL OR qty#>>'{0,elements,1,1}'='NULL' THEN CONTINUE;END IF;
   IF(SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='AES' AND jsonb_array_length(t->'elements'->1)=2 AND(t->>'index')::int<(qty#>>'{0,index}')::int)<>1 THEN reading:=NULL;EXIT;END IF;
   SELECT t#>>'{elements,1,1}' INTO register_id FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='AES' AND(t->>'index')::int<(qty#>>'{0,index}')::int;
   IF previous_register IS DISTINCT FROM register_id THEN current_meter:=NULL;END IF;previous_register:=register_id;
   IF(SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='MG' AND(t->>'index')::int<(qty#>>'{0,index}')::int)>1 THEN reading:=NULL;EXIT;END IF;
   SELECT t#>>'{elements,1,1}' INTO meter_id FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='MG' AND jsonb_array_length(t->'elements'->1)=2 AND(t->>'index')::int<(qty#>>'{0,index}')::int;
   IF meter_id IS NOT NULL THEN current_meter:=meter_id;END IF;meter_id:=current_meter;
   IF meter_id IS NULL THEN reading:=NULL;EXIT;END IF;
   SELECT jsonb_agg(t) INTO dates FROM jsonb_array_elements(own)t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='597' AND(t->>'index')::int>(qty#>>'{0,index}')::int;
   IF jsonb_array_length(dates) IS DISTINCT FROM 1 THEN reading:=NULL;EXIT;END IF;
   at:=gridex_received_reading_expectations.instant_v1(dates#>>'{0,elements,1,1}',dates#>>'{0,elements,1,2}',offset_minutes);
   IF at IS NULL THEN reading:=NULL;EXIT;END IF;
   reading:=reading||jsonb_build_array(jsonb_build_object('registerId',register_id,'meterNumber',meter_id,'readAt',at,'sourceQuantity',qty#>'{0,elements,1}'));
  END LOOP;
  candidate_ids:='{}';
  FOR e IN SELECT * FROM gridex_received_reading_expectations.expectations x WHERE x.company_id=c AND x.environment=env AND x.contract#>>'{object,objectId}'=point AND x.contract#>>'{object,identityAgency}'=agency AND x.contract#>>'{wire,legalSender}'=sender AND x.contract#>>'{wire,legalReceiver}'=receiver LOOP
   IF e.contract_hash IS DISTINCT FROM encode(sha256(convert_to(e.contract::text,'UTF8')),'hex') OR NOT EXISTS(SELECT FROM jsonb_array_elements(gridex_received_reading_expectations.source_contracts_v1(c,env,e.source_message_id))value WHERE value=e.contract) THEN CONTINUE;END IF;
   IF EXISTS(SELECT FROM gridex_received_reading_expectations.expectations correction WHERE correction.company_id=c AND correction.environment=env AND correction.contract#>>'{replaces,sourceMessageId}'=e.source_message_id::text AND correction.contract#>>'{object,objectId}'=point AND correction.contract#>>'{object,identityAgency}'=agency) THEN CONTINUE;END IF;
   matched:=false;
   IF e.contract->>'mode'='meter_reading' AND reading IS NOT NULL AND jsonb_array_length(reading)>0 THEN
    matched:=(SELECT jsonb_agg(value->'registerId' ORDER BY value->>'registerId') FROM jsonb_array_elements(reading) WHERE(value->>'readAt')::timestamptz=(e.contract->>'effectiveAt')::timestamptz)=(SELECT jsonb_agg(value ORDER BY value#>>'{}') FROM jsonb_array_elements(e.contract->'expectedRegisterIds'))
      AND NOT EXISTS(SELECT FROM jsonb_array_elements(reading)value WHERE(value->>'readAt')::timestamptz=(e.contract->>'effectiveAt')::timestamptz AND value->>'meterNumber' IS DISTINCT FROM e.contract#>>'{wire,meterNumber}');
   ELSIF e.contract->>'mode'='subsequent_values' THEN
    -- Observe initial subsequent values only. No claim about all future periods,
    -- no invented boundary reading where original field259 was absent.
    matched:=stored#>>'{metering,customerId}'=e.contract->>'customerId' AND stored#>>'{metering,meteringPointId}'=e.contract->>'meteringPointId'
     AND EXISTS(SELECT FROM jsonb_array_elements(stored->'observations')v WHERE(v->>'periodStart')::timestamptz>=(e.contract->>'effectiveAt')::timestamptz
      AND(v->>'periodStart')::timestamptz>=(e.contract#>>'{coverage,validFrom}')::timestamptz AND(e.contract#>>'{coverage,validTo}' IS NULL OR(v->>'periodEnd')::timestamptz<=(e.contract#>>'{coverage,validTo}')::timestamptz)
      AND CASE e.contract->>'measurementMethod' WHEN 'Z04' THEN v->>'resolution'='PT15M' WHEN 'Z02' THEN v->>'resolution'='PT1H' WHEN 'Z01' THEN v->>'resolution' IN('P1M','P1Y') ELSE false END
      AND NOT EXISTS(SELECT FROM gridex_received_reading_expectations.expectations later WHERE later.company_id=c AND later.environment=env AND later.contract#>>'{object,objectId}'=point AND later.contract#>>'{object,identityAgency}'=agency AND later.contract#>>'{wire,legalSender}'=sender AND later.contract#>>'{wire,legalReceiver}'=receiver AND(later.contract->>'effectiveAt')::timestamptz>(e.contract->>'effectiveAt')::timestamptz AND(later.contract->>'effectiveAt')::timestamptz<=(v->>'periodStart')::timestamptz));
   END IF;
   IF matched IS TRUE THEN candidate_ids:=array_append(candidate_ids,e.id);END IF;
  END LOOP;
  -- A reading cannot be borrowed by two indistinguishable structural originals.
  IF cardinality(candidate_ids)=1 THEN
   receipt:=jsonb_build_object('version',1,'utiltsSourceId',msg,'transactionId',tx,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),
     'storedContractHash',encode(sha256(convert_to(stored::text,'UTF8')),'hex'),'reading',reading,'observation','actual_accepted_persisted_member');
   INSERT INTO gridex_received_reading_expectations.observations(expectation_id,company_id,environment,utilts_source_message_id,transaction_id,source_payload_hash,receipt,receipt_hash)
    VALUES(candidate_ids[1],c,env,msg,tx,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),receipt,encode(sha256(convert_to(receipt::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
END$_$;

--
-- Name: current_status_v1(uuid, text, uuid, integer); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.current_status_v1(c uuid, env text, msg uuid, line_index integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('owner','applied-z06f-reading-followup-v1','criterion','AT-Z06F-SUPPLIER','sourceMessageId',msg,'firstLineIndex',line_index,'deadline',NULL,'automaticRequestAllowed',false,
 'status',CASE WHEN count(*)=0 THEN 'source_scope_unavailable' WHEN bool_and(observed) THEN CASE WHEN bool_and(mode='meter_reading') THEN 'reading_observed' ELSE 'initial_values_observed' END ELSE 'pending' END,
 'fulfilled',coalesce(bool_and(observed AND mode='meter_reading'),false),'expectationIds',coalesce(jsonb_agg(id),'[]'))
 FROM(SELECT e.id,e.contract->>'mode' mode,EXISTS(SELECT FROM gridex_received_reading_expectations.observations o WHERE o.expectation_id=e.id) observed FROM gridex_received_reading_expectations.expectations e WHERE e.company_id=c AND e.environment=env AND e.source_message_id=msg AND e.first_line_index=line_index) own;
$$;

--
-- Name: instant_v1(text, text, integer); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.instant_v1(value text, format text, offset_minutes integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE v timestamp;BEGIN
 IF (format='102' AND value~'^[0-9]{8}$') THEN v:=make_timestamp(substring(value,1,4)::int,substring(value,5,2)::int,substring(value,7,2)::int,0,0,0);
 ELSIF format IN('203','204') AND value~'^[0-9]{12}([0-9]{2})?$' AND length(value)=(CASE format WHEN '203' THEN 12 ELSE 14 END) THEN
 v:=make_timestamp(substring(value,1,4)::int,substring(value,5,2)::int,substring(value,7,2)::int,substring(value,9,2)::int,substring(value,11,2)::int,CASE format WHEN '204' THEN substring(value,13,2)::int ELSE 0 END);
 ELSE RETURN NULL;END IF;RETURN(v-make_interval(mins=>offset_minutes)) AT TIME ZONE 'UTC';EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN NULL;END$_$;

--
-- Name: source_contracts_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.source_contracts_v1(c uuid, env text, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;s gridex_received_sources.sources%rowtype;a gridex_received_sources.object_assessments%rowtype;f gridex_received_sources.prodat_ignored_field_facets%rowtype;
 own jsonb;assessed jsonb;business jsonb;wire jsonb;qualified jsonb;registers jsonb;expected jsonb;mode text;out jsonb:='[]';first_line integer;
BEGIN
 FOR r IN SELECT payload_hash,canonical_assessment_id,object_assessment_id,source_received_at,applied_at,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND environment=env AND source_message_id=msg
 UNION ALL SELECT payload_hash,canonical_assessment_id,object_assessment_id,source_received_at,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND environment=env AND source_message_id=msg LOOP
  SELECT * INTO s FROM gridex_received_sources.sources WHERE company_id=c AND environment=env AND source_message_id=msg;
  SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND company_id=c AND environment=env AND source_message_id=msg;
  SELECT * INTO f FROM gridex_received_sources.prodat_ignored_field_facets WHERE canonical_assessment_id=r.canonical_assessment_id AND company_id=c AND environment=env AND source_message_id=msg;
  IF s.source_message_id IS NULL OR a.id IS NULL OR f.canonical_assessment_id IS NULL OR s.payload_hash IS DISTINCT FROM r.payload_hash
   OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR a.source_payload_hash IS DISTINCT FROM s.payload_hash
   OR a.canonical_assessment_id IS DISTINCT FROM r.canonical_assessment_id OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
   OR NOT EXISTS(SELECT FROM public.ediel_messages original WHERE original.id=msg AND original.company_id=c AND original.environment=env AND original.direction='inbound' AND original.message_family='PRODAT' AND original.message_code='Z06' AND original.raw_payload=s.raw_payload AND original.message_received_at=s.source_received_at)
   OR f.source_payload_hash IS DISTINCT FROM s.payload_hash OR f.fields_hash IS DISTINCT FROM encode(sha256(convert_to(f.fields_text,'UTF8')),'hex') THEN CONTINUE;END IF;
  FOR own IN SELECT value FROM jsonb_array_elements(r.objects) LOOP
   SELECT value INTO assessed FROM jsonb_array_elements(a.facts_text::jsonb->'objects') value WHERE value->'object'=own->'object';
   business:=assessed->'business';wire:=business->'wire';first_line:=(own#>>'{object,registers,0,segmentIndex}')::integer;
   IF assessed->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
    OR wire IS DISTINCT FROM own->'wire' OR wire->>'messageCode' IS DISTINCT FROM 'Z06' OR wire->>'businessCase' IS DISTINCT FROM 'change_with_reading'
    OR business->>'companyId' IS DISTINCT FROM c::text OR business->>'environment' IS DISTINCT FROM env
    OR business->>'meteringPointId' IS DISTINCT FROM own->>'meteringPointId' OR business->>'siteId' IS DISTINCT FROM own->>'siteId'
    OR nullif(business->>'customerId','') IS NULL OR nullif(business->>'supplyPeriodId','') IS NULL OR first_line IS NULL
    OR wire#>>'{effectiveFrom,utc}' IS NULL OR (wire#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM (own->>'effectiveAt')::timestamptz
    OR gridex_received_sources.structural_effect_matches_v1(c,env,msg,a.id,(business->>'customerId')::uuid,(business->>'siteId')::uuid,(business->>'meteringPointId')::uuid,(business->>'supplyPeriodId')::uuid,own#>>'{object,objectId}',own#>>'{object,identityAgency}',r.applied_at) IS NOT TRUE THEN CONTINUE;END IF;
   SELECT value INTO qualified FROM jsonb_array_elements(gridex_received_sources.applied_structural_method_objects_v1(c,msg)) value
    WHERE value->>'objectId'=own#>>'{object,objectId}' AND value->>'identityAgency'=own#>>'{object,identityAgency}' AND value->>'businessCase'='change_with_reading';
   IF qualified IS NULL OR qualified->>'companyId' IS DISTINCT FROM c::text OR qualified->>'environment' IS DISTINCT FROM env OR qualified->>'sourceMessageId' IS DISTINCT FROM msg::text OR qualified->>'sourcePayloadHash' IS DISTINCT FROM s.payload_hash OR qualified->>'customerId' IS DISTINCT FROM business->>'customerId' OR qualified->>'meteringPointId' IS DISTINCT FROM business->>'meteringPointId'
    OR qualified->>'measurementMethod' IS NULL THEN CONTINUE;END IF;
   -- Original field259 identifies promised meter readings. An ignored physical
   -- value never becomes an expected register. No incoming UTILTS fills gaps.
   registers:=wire->'registers';
   IF EXISTS(SELECT FROM jsonb_array_elements(f.fields_text::jsonb) ignored WHERE ignored->>'fieldNumber' IN('259','224')
    AND ignored#>>'{occurrence,objectId}'=own#>>'{object,objectId}' AND ignored#>>'{occurrence,identityAgency}'=own#>>'{object,identityAgency}') THEN registers:=NULL;END IF;
   SELECT jsonb_agg(value->'registerId' ORDER BY (value->>'position')::int) INTO expected FROM jsonb_array_elements(registers) value;
   mode:=CASE WHEN expected IS NOT NULL AND jsonb_array_length(expected)>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements(expected) value WHERE value='null'::jsonb OR value='""'::jsonb)
      AND (SELECT count(DISTINCT value) FROM jsonb_array_elements(expected))=jsonb_array_length(expected) AND nullif(wire->>'meterNumber','') IS NOT NULL THEN 'meter_reading'
     ELSE 'subsequent_values' END;
   out:=out||jsonb_build_array(jsonb_build_object('version',1,'owner','applied-z06f-reading-followup-v1','companyId',c,'environment',env,'sourceMessageId',msg,
    'sourcePayloadHash',s.payload_hash,'canonicalAssessmentId',r.canonical_assessment_id,'objectAssessmentId',a.id,'objectFactsHash',a.facts_hash,
    'firstLineIndex',first_line,'object',own->'object','wire',wire,'customerId',business->>'customerId','siteId',business->>'siteId','meteringPointId',business->>'meteringPointId',
    'supplyPeriodId',business->>'supplyPeriodId','coverage',business->'coverageWindow','replaces',business->'replaces','measurementMethod',qualified->>'measurementMethod',
    'effectiveAt',own->'effectiveAt','sourceReceivedAt',s.source_received_at,'appliedAt',r.applied_at,'mode',mode,'expectedRegisterIds',expected,
    'deadline',NULL,'automaticRequestAllowed',false));
  END LOOP;
 END LOOP;
 RETURN out;
END$$;

--
-- Name: activate_supply_before_source_guard_v1(uuid, uuid, uuid, date, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(supplier_switch_request_id uuid, supply_period_id uuid, contract_id uuid, customer_application_id uuid, workflow_id uuid, domain_event_id uuid, notification_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_switch public.supplier_switch_requests%rowtype;
  v_period_id uuid;
  v_contract_id uuid;
  v_application_id uuid;
  v_workflow public.customer_application_workflows%rowtype;
  v_event_id uuid;
  v_job_id uuid;
  v_start_date date;
  v_key text;
  v_now timestamptz := now();
  v_tenant_reference text;
begin
  if p_company_id is null then
    raise exception 'supply_activation_company_required' using errcode = '22023';
  end if;
  if p_supplier_switch_request_id is null then
    raise exception 'supply_activation_switch_required' using errcode = '22023';
  end if;
  if p_source_message_id is null then
    raise exception 'supply_activation_source_message_required' using errcode = '22023';
  end if;

  select * into v_switch
  from public.supplier_switch_requests
  where id = p_supplier_switch_request_id
    and company_id = p_company_id
  for update;

  if not found then
    raise exception 'supply_activation_switch_not_found' using errcode = 'P0002';
  end if;
  if v_switch.customer_id is null then
    raise exception 'supply_activation_customer_required' using errcode = '23502';
  end if;
  if v_switch.metering_point_id is null then
    raise exception 'supply_activation_metering_point_required' using errcode = '23502';
  end if;

  v_contract_id := coalesce(v_switch.contract_id, v_switch.customer_contract_id);
  if v_contract_id is null then
    raise exception 'supply_activation_contract_required' using errcode = '23502';
  end if;
  if v_switch.status not in (
    'confirmed',
    'accepted',
    'completed'
  ) then
    raise exception 'supply_activation_switch_not_confirmed' using errcode = '23514';
  end if;

  if not exists(
    select 1
    from public.customer_contracts cc
    join public.metering_points mp
      on mp.id=v_switch.metering_point_id
     and mp.company_id=cc.company_id
     and mp.customer_id=cc.customer_id
    left join public.customer_sites cs
      on cs.id=coalesce(v_switch.customer_site_id,v_switch.site_id)
     and cs.company_id=cc.company_id
     and cs.customer_id=cc.customer_id
    where cc.id=v_contract_id
      and cc.company_id=p_company_id
      and cc.customer_id=v_switch.customer_id
      and (
        coalesce(v_switch.customer_site_id,v_switch.site_id) is null
        or cs.id is not null
      )
  ) then
    raise exception using
      errcode='23514',
      message='supply_activation_customer_contract_site_meter_mismatch';
  end if;

  v_start_date := coalesce(
    p_actual_start_date,
    v_switch.confirmed_start_date,
    v_switch.requested_start_date
  );
  if v_start_date is null then
    raise exception 'supply_activation_start_date_required' using errcode = '23502';
  end if;
  v_key := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    format('activate_customer_supply_v1:%s:%s', p_company_id, p_supplier_switch_request_id)
  );

  insert into public.customer_supply_periods(
    company_id,
    customer_id,
    metering_point_id,
    contract_id,
    start_date,
    actual_start_date,
    source,
    source_process,
    source_message_id,
    source_switch_request_id,
    status,
    metadata,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    v_switch.metering_point_id,
    v_contract_id,
    v_start_date,
    v_start_date,
    'activate_customer_supply_v1',
    'supplier_switch_confirmation',
    p_source_message_id,
    v_switch.id,
    'active',
    jsonb_build_object(
      'activation_idempotency_key', v_key,
      'activated_at', v_now
    ),
    v_now
  )
  on conflict (company_id, metering_point_id, start_date)
    where status in ('active', 'confirmed_by_grid_owner')
  do update set
    customer_id = excluded.customer_id,
    contract_id = excluded.contract_id,
    actual_start_date = coalesce(public.customer_supply_periods.actual_start_date, excluded.actual_start_date),
    source_message_id = excluded.source_message_id,
    source_switch_request_id = excluded.source_switch_request_id,
    status = 'active',
    metadata = coalesce(public.customer_supply_periods.metadata, '{}'::jsonb)
      || excluded.metadata,
    updated_at = excluded.updated_at
  returning id into v_period_id;

  update public.supplier_switch_requests
  set status = 'completed',
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      completed_at = coalesce(completed_at, v_now),
      external_reference = coalesce(external_reference, v_key),
      inbound_z04_message_id = coalesce(inbound_z04_message_id, p_source_message_id),
      lifecycle_blocked = false,
      lifecycle_block_source = null,
      updated_at = v_now
  where id = v_switch.id
    and company_id = p_company_id;

  update public.customer_contracts
  set status = 'active',
      lifecycle_stage = 'active',
      actual_start_date = coalesce(actual_start_date, v_start_date),
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      billing_eligible_at = coalesce(billing_eligible_at, v_now),
      billing_eligibility_source = coalesce(
        billing_eligibility_source,
        'activate_customer_supply_v1'
      ),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'activation_source_message_id', p_source_message_id
      ),
      updated_at = v_now
  where id = v_contract_id
    and company_id = p_company_id
    and customer_id = v_switch.customer_id
    and status in ('signed', 'active');

  if not found then
    raise exception 'supply_activation_contract_not_activatable' using errcode = '23514';
  end if;

  select workflow.* into v_workflow
  from public.customer_application_workflows workflow
  where workflow.company_id = p_company_id
    and workflow.customer_id = v_switch.customer_id
    and workflow.contract_id = v_contract_id
  order by created_at desc
  limit 1
  for update;

  if found then
    v_application_id := v_workflow.customer_application_id;

    insert into public.customer_application_workflow_events(
      company_id,
      workflow_id,
      customer_application_id,
      operation_id,
      from_state,
      to_state,
      event_code,
      actor_user_id,
      metadata,
      idempotency_key
    ) values (
      p_company_id,
      v_workflow.id,
      v_workflow.customer_application_id,
      v_workflow.operation_id,
      v_workflow.state,
      'completed',
      'workflow.supply_activated',
      p_actor_user_id,
      jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'actual_start_date', v_start_date
      ),
      v_key || ':workflow'
    )
    on conflict (company_id, idempotency_key) do nothing;

    update public.customer_application_workflows
    set state = 'completed',
        next_action = 'none',
        completed_at = coalesce(completed_at, v_now),
        last_transition_at = v_now,
        workflow_version = case
          when state = 'completed' then workflow_version
          else workflow_version + 1
        end,
        snapshot = coalesce(snapshot, '{}'::jsonb) || jsonb_build_object(
          'supply_period_id', v_period_id,
          'supplier_switch_request_id', v_switch.id,
          'actual_start_date', v_start_date,
          'billing_eligible_at', v_now,
          'next_action', 'none'
        ),
        updated_at = v_now
    where id = v_workflow.id;

    update public.website_customer_applications
    set status = 'active',
        actual_start_date = coalesce(actual_start_date, v_start_date),
        next_step = 'none',
        updated_at = v_now
    where id = v_application_id
      and company_id = p_company_id;
  end if;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    subject_customer_id,
    actor_user_id,
    source,
    idempotency_key,
    payload,
    occurred_at
  ) values (
    p_company_id,
    'supply.started',
    'customer_supply_period',
    v_period_id::text,
    v_switch.customer_id,
    p_actor_user_id,
    'activate_customer_supply_v1',
    v_key || ':domain_event',
    jsonb_build_object(
      'customer_id', v_switch.customer_id,
      'contract_id', v_contract_id,
      'customer_site_id', coalesce(v_switch.customer_site_id, v_switch.site_id),
      'metering_point_id', v_switch.metering_point_id,
      'supplier_switch_request_id', v_switch.id,
      'supply_period_id', v_period_id,
      'actual_start_date', v_start_date,
      'billing_eligible_at', v_now
    ),
    v_now
  )
  on conflict (idempotency_key) where idempotency_key is not null
  do nothing
  returning id into v_event_id;

  if v_event_id is null then
    select id into v_event_id
    from public.domain_events
    where idempotency_key = v_key || ':domain_event';
  end if;

  insert into public.customer_operation_jobs(
    company_id,
    customer_id,
    customer_site_id,
    metering_point_id,
    job_type,
    status,
    priority,
    idempotency_key,
    payload,
    request_snapshot,
    run_after,
    created_by,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    coalesce(v_switch.customer_site_id, v_switch.site_id),
    v_switch.metering_point_id,
    'dispatch_lifecycle_notification',
    'queued',
    40,
    'lifecycle_notification:' || v_key || ':customer.welcome_active',
    jsonb_build_object(
      'event_type', 'supply_period.activated',
      'source_event_id', v_event_id,
      'contract_id', v_contract_id,
      'payload', jsonb_build_object(
        'start_date', v_start_date,
        'supply_period_id', v_period_id
      )
    ),
    jsonb_build_object(
      'domain_event_id', v_event_id,
      'supplier_switch_request_id', v_switch.id
    ),
    v_now,
    p_actor_user_id,
    v_now
  )
  on conflict do nothing
  returning id into v_job_id;

  if v_job_id is null then
    select id into v_job_id
    from public.customer_operation_jobs
    where company_id = p_company_id
      and job_type = 'dispatch_lifecycle_notification'
      and idempotency_key = 'lifecycle_notification:' || v_key || ':customer.welcome_active'
    order by created_at desc
    limit 1;
  end if;

  select external_tenant_reference into v_tenant_reference
  from public.companies
  where id = p_company_id;

  insert into public.webhook_deliveries(
    company_id,
    webhook_subscription_id,
    domain_event_id,
    event_type,
    max_attempts,
    target_url,
    idempotency_key,
    payload
  )
  select
    p_company_id,
    subscription.id,
    v_event_id,
    'supply.started',
    subscription.max_attempts,
    subscription.endpoint_url,
    format('webhook:%s:%s', subscription.id, v_event_id),
    jsonb_build_object(
      'id', v_event_id,
      'type', 'supply.started',
      'event_id', v_event_id,
      'event_type', 'supply.started',
      'created_at', v_now,
      'tenant_reference', v_tenant_reference,
      'customer_id', v_switch.customer_id,
      'aggregate', jsonb_build_object(
        'type', 'customer_supply_period',
        'id', v_period_id
      ),
      'data', jsonb_build_object(
        'contract_id', v_contract_id,
        'supplier_switch_request_id', v_switch.id,
        'supply_period_id', v_period_id,
        'actual_start_date', v_start_date
      )
    )
  from public.webhook_subscriptions subscription
  where subscription.company_id = p_company_id
    and subscription.status = 'active'
    and (
      '*' = any(coalesce(subscription.event_types, '{}'::text[]))
      or 'supply.started' = any(coalesce(subscription.event_types, '{}'::text[]))
    )
  on conflict (idempotency_key) do nothing;

  return query select
    v_switch.id,
    v_period_id,
    v_contract_id,
    v_application_id,
    v_workflow.id,
    v_event_id,
    v_job_id;
end;
$$;

--
-- Name: FUNCTION activate_supply_before_source_guard_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date, p_actor_user_id uuid, p_idempotency_key text); Type: COMMENT; Schema: gridex_received_sources; Owner: -
--

COMMENT ON FUNCTION gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date, p_actor_user_id uuid, p_idempotency_key text) IS 'Idempotently and atomically activates confirmed customer supply, contract billing eligibility, workflow/projection, one supply.started domain event and durable notification/webhook outboxes.';

--
-- Name: advance_supply_before_normal_switch_v1(uuid, uuid, integer); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.advance_supply_before_normal_switch_v1(p_company_id uuid, p_actor_user_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE changed integer;activated integer;
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') THEN RETURN jsonb_build_object('updated',0);END IF;
 WITH due AS (SELECT p.id FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id WHERE (p_company_id IS NULL OR p.company_id=p_company_id) AND coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p.company_id,'metering.write'),false) AND EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) AND p.status='ending' AND p.market_end_at<=now() AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) s WHERE s->>'id'=p.id::text AND (s->>'market_state_version')::bigint=p.market_state_version AND (s->>'market_end_at')::timestamptz=p.market_end_at) ORDER BY p.market_end_at,p.id LIMIT least(greatest(coalesce(p_limit,100),1),200) FOR UPDATE OF p SKIP LOCKED)
 UPDATE public.customer_supply_periods p SET status='ended',updated_at=now() FROM due WHERE p.id=due.id AND (p_company_id IS NULL OR p.company_id=p_company_id) AND p.status='ending';
 GET DIAGNOSTICS changed=ROW_COUNT;
 -- These are separate regulated market relationships. No ordinary Z03 or
 -- consumer-contract activation/notification is introduced by this profile.
 WITH due AS (
  SELECT p.id FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_message_id AND tr.company_id=p.company_id
  JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id
  JOIN gridex_received_sources.regulated_supply_ground_versions g ON g.id::text=p.metadata->>'sourceGroundId' AND g.company_id=p.company_id AND g.environment=m.environment
  JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
  JOIN public.tenant_actor_roles role ON role.company_id=p.company_id AND role.environment=m.environment AND role.actor_id=g.legal_actor_id AND role.role_code='electricity_supplier' AND role.valid_from<=now() AND (role.valid_to IS NULL OR now()<role.valid_to)
  JOIN public.tenant_ediel_profiles profile ON profile.company_id=p.company_id AND profile.environment=m.environment AND profile.market='electricity' AND profile.is_enabled AND profile.valid_from<=now() AND (profile.valid_to IS NULL OR now()<profile.valid_to)
  WHERE (p_company_id IS NULL OR p.company_id=p_company_id) AND p.status='confirmed_by_grid_owner' AND p.source_process IN ('assigned_supply','production_receipt_obligation') AND p.market_start_at<=now()
   AND coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p.company_id,'metering.write'),false) AND EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
   AND gridex_regulated_supply.ground_current_v1(g.id,p.company_id,p.metering_point_id,p.market_start_at) IS TRUE
   AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND g.revoked_at IS NULL AND g.valid_from<=now() AND (g.valid_to IS NULL OR now()<g.valid_to) AND ba.is_enabled AND ba.source_reference=g.source_reference AND ba.valid_from<=now() AND (ba.valid_to IS NULL OR now()<ba.valid_to)
      AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) saved WHERE saved->>'id'=p.id::text AND (saved->>'market_state_version')::bigint=p.market_state_version AND (saved->>'market_start_at')::timestamptz=p.market_start_at AND saved->>'customer_id'=p.customer_id::text AND saved->>'metering_point_id'=p.metering_point_id::text AND saved->>'source_process'=p.source_process AND saved->'metadata'=p.metadata)
   ORDER BY p.market_start_at,p.id LIMIT least(greatest(coalesce(p_limit,100),1),200) FOR UPDATE OF p SKIP LOCKED FOR SHARE OF g,ba,role,profile)
 UPDATE public.customer_supply_periods p SET status='active',updated_at=now() FROM due WHERE p.id=due.id AND p.status='confirmed_by_grid_owner';
 GET DIAGNOSTICS activated=ROW_COUNT;RETURN jsonb_build_object('updated',changed+activated);

END $$;

--
-- Name: append_discovery(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_discovery(p_company_id uuid, p_environment text, p_snapshot_id uuid, p_snapshot_hash text, p_engine_version text, p_inventory_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE snap gridex_received_sources.snapshots%rowtype; inv jsonb; src jsonb; expected jsonb; item jsonb;
  v_id uuid; v_hash text; n bigint; distinct_n bigint;
  v_position bigint; v_segment numeric; v_expected_objects jsonb;
BEGIN
  SELECT * INTO snap FROM gridex_received_sources.snapshots WHERE id=p_snapshot_id AND company_id=p_company_id AND environment=p_environment;
  IF NOT FOUND OR p_snapshot_hash IS DISTINCT FROM snap.manifest_hash
     OR p_engine_version IS DISTINCT FROM 'physical-lin-inventory-v1' OR p_inventory_text IS NULL
     OR octet_length(p_inventory_text)>8388608 THEN
    RAISE EXCEPTION 'received_discovery_binding_unavailable' USING ERRCODE='23514';
  END IF;
  inv := p_inventory_text::jsonb;
  IF jsonb_typeof(inv) IS DISTINCT FROM 'object'
    OR inv - ARRAY['version','universe','historyCoverage','authorityStatus','selection','status','sources','issues'] <> '{}'::jsonb
    OR inv->'version' IS DISTINCT FROM '1'::jsonb OR inv->>'universe' IS DISTINCT FROM 'durable_received_sources'
    OR inv->>'historyCoverage' IS DISTINCT FROM 'before_ledger_unknown' OR inv->>'authorityStatus' IS DISTINCT FROM 'not_established'
    OR inv->>'selection' IS DISTINCT FROM 'not_performed' OR coalesce(inv->>'status','') NOT IN ('enumerated','incomplete')
    OR jsonb_typeof(inv->'sources') IS DISTINCT FROM 'array' OR jsonb_typeof(inv->'issues') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'received_discovery_not_an_approval' USING ERRCODE='23514';
  END IF;
  SELECT count(*),count(DISTINCT value->>'sourceMessageId') INTO n,distinct_n FROM jsonb_array_elements(inv->'sources');
  IF n<>distinct_n OR n>1000 OR (inv->>'status'='enumerated' AND
      (snap.manifest->'exhaustive' IS DISTINCT FROM 'true'::jsonb OR n<>(snap.manifest->>'sourceCount')::bigint OR inv->'issues'<>'[]'::jsonb))
    OR (n<>0 AND n<>(snap.manifest->>'sourceCount')::bigint) THEN
    RAISE EXCEPTION 'received_discovery_incomplete_set' USING ERRCODE='23514';
  END IF;
  FOR src IN SELECT value FROM jsonb_array_elements(inv->'sources') LOOP
    SELECT value INTO expected FROM jsonb_array_elements(snap.manifest->'sources') WHERE value->>'sourceMessageId'=src->>'sourceMessageId';
    IF NOT FOUND OR jsonb_typeof(src) IS DISTINCT FROM 'object'
      OR src - ARRAY['sourceMessageId','sourcePayloadHash','sourceReceivedAt','capturedAt','receiptStatus','disposition','status','occurrences','objects','issues'] <> '{}'::jsonb
      OR src->'sourcePayloadHash' IS DISTINCT FROM expected->'payloadHash'
      OR src->'sourceReceivedAt' IS DISTINCT FROM expected->'sourceReceivedAt' OR src->'capturedAt' IS DISTINCT FROM expected->'capturedAt'
      OR src->>'disposition' IS DISTINCT FROM 'not_checked' OR coalesce(src->>'status','') NOT IN ('enumerated','incomplete')
      OR coalesce(src->>'receiptStatus','') NOT IN ('recorded','unavailable')
      OR (src->>'receiptStatus'='recorded' AND expected->'receiptContextRecorded' IS DISTINCT FROM 'true'::jsonb)
      OR jsonb_typeof(src->'occurrences') IS DISTINCT FROM 'array' OR jsonb_typeof(src->'objects') IS DISTINCT FROM 'array'
      OR jsonb_typeof(src->'issues') IS DISTINCT FROM 'array'
      OR (inv->>'status'='enumerated' AND (src->>'status'<>'enumerated' OR src->>'receiptStatus'<>'recorded' OR src->'issues'<>'[]'::jsonb))
      OR (src->>'status'='enumerated' AND (jsonb_typeof(src->'sourcePayloadHash') IS DISTINCT FROM 'string'
        OR coalesce(src->>'sourcePayloadHash','') !~ '^[a-f0-9]{64}$' OR jsonb_array_length(src->'occurrences')=0 OR jsonb_array_length(src->'objects')=0 OR src->>'receiptStatus'<>'recorded' OR src->'issues'<>'[]'::jsonb)) THEN
      RAISE EXCEPTION 'received_discovery_source_mismatch' USING ERRCODE='23514';
    END IF;
    -- Persist the producer's complete typed observation contract, not merely
    -- a set of allowed key names. This validates evidence shape and internal
    -- tuple bindings; it is NOT a second wire parser or source approval owner.
    IF jsonb_array_length(src->'occurrences')>8192 OR jsonb_array_length(src->'objects')>8192 THEN
      RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
    END IF;
    v_segment := -1;
    FOR item,v_position IN SELECT value,ordinality FROM jsonb_array_elements(src->'occurrences') WITH ORDINALITY LOOP
      IF jsonb_typeof(item) IS DISTINCT FROM 'object'
        OR NOT item ?& ARRAY['ordinal','segmentIndex','messageIndex','lineNumber','objectId','identityAgency','identityStatus']
        OR item - ARRAY['ordinal','segmentIndex','messageIndex','lineNumber','objectId','identityAgency','identityStatus'] <> '{}'::jsonb
        OR jsonb_typeof(item->'ordinal') IS DISTINCT FROM 'number'
        OR jsonb_typeof(item->'segmentIndex') IS DISTINCT FROM 'number'
        OR coalesce(jsonb_typeof(item->'messageIndex'),'missing') NOT IN ('number','null')
        OR coalesce(jsonb_typeof(item->'lineNumber'),'missing') NOT IN ('string','null')
        OR coalesce(jsonb_typeof(item->'objectId'),'missing') NOT IN ('string','null')
        OR coalesce(jsonb_typeof(item->'identityAgency'),'missing') NOT IN ('string','null')
        OR jsonb_typeof(item->'identityStatus') IS DISTINCT FROM 'string'
        OR coalesce(item->>'identityStatus','') NOT IN ('observed','unresolved') THEN
        RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
      END IF;
      -- Cast only AFTER the mandatory JSON types were checked. Ordinals are
      -- consecutive physical occurrences and segment indexes strictly increase.
      IF item->'ordinal' IS DISTINCT FROM to_jsonb(v_position)
        OR (item->>'segmentIndex')::numeric < 0 OR (item->>'segmentIndex')::numeric >= 8192
        OR trunc((item->>'segmentIndex')::numeric) <> (item->>'segmentIndex')::numeric
        OR (item->>'segmentIndex')::numeric <= v_segment
        OR (item->'messageIndex' <> 'null'::jsonb AND ((item->>'messageIndex')::numeric < 0
          OR (item->>'messageIndex')::numeric >= 8192
          OR trunc((item->>'messageIndex')::numeric) <> (item->>'messageIndex')::numeric))
        OR (item->'lineNumber' <> 'null'::jsonb AND length(item->>'lineNumber') NOT BETWEEN 1 AND 128) THEN
        RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
      END IF;
      v_segment := (item->>'segmentIndex')::numeric;
      IF item->>'identityStatus'='observed' THEN
        IF jsonb_typeof(item->'messageIndex') IS DISTINCT FROM 'number'
          OR jsonb_typeof(item->'objectId') IS DISTINCT FROM 'string'
          OR length(item->>'objectId') NOT BETWEEN 1 AND 128
          OR jsonb_typeof(item->'identityAgency') IS DISTINCT FROM 'string'
          OR item->>'identityAgency' NOT IN ('9','89') THEN
          RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
        END IF;
      ELSIF item->'objectId' IS DISTINCT FROM 'null'::jsonb OR item->'identityAgency' IS DISTINCT FROM 'null'::jsonb
        OR src->>'status'='enumerated' THEN
        RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
      END IF;
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(src->'objects') LOOP
      IF jsonb_typeof(item) IS DISTINCT FROM 'object'
        OR NOT item ?& ARRAY['messageIndex','objectId','identityAgency','occurrenceOrdinals']
        OR item - ARRAY['messageIndex','objectId','identityAgency','occurrenceOrdinals'] <> '{}'::jsonb
        OR jsonb_typeof(item->'messageIndex') IS DISTINCT FROM 'number'
        OR jsonb_typeof(item->'objectId') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'identityAgency') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'occurrenceOrdinals') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
      END IF;
    END LOOP;
    -- Every observed occurrence must appear exactly once in the membership
    -- for its exact message/identity/agency tuple, preserving register repeats.
    -- This compares the submitted arrays, never interprets canonical registers.
    SELECT coalesce(jsonb_agg(jsonb_build_object('messageIndex',g.message_index,'objectId',g.object_id,
        'identityAgency',g.agency,'occurrenceOrdinals',g.ordinals) ORDER BY g.first_ordinal),'[]'::jsonb)
      INTO v_expected_objects
      FROM (SELECT value->'messageIndex' AS message_index,value->'objectId' AS object_id,value->'identityAgency' AS agency,
          jsonb_agg(value->'ordinal' ORDER BY ordinality) AS ordinals,min(ordinality) AS first_ordinal
        FROM jsonb_array_elements(src->'occurrences') WITH ORDINALITY
        WHERE value->>'identityStatus'='observed'
        GROUP BY value->'messageIndex',value->'objectId',value->'identityAgency') g;
    IF src->'objects' IS DISTINCT FROM v_expected_objects THEN
      RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT FROM jsonb_array_elements(src->'issues') AS value WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR value#>>'{}' !~ '^[a-z0-9_]{1,128}$') THEN
      RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
    END IF;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(inv->'issues') LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item - ARRAY['code','sourceMessageId'] <> '{}'::jsonb
      OR coalesce(item->>'code','') !~ '^[a-z0-9_]{1,128}$'
      OR (item ? 'sourceMessageId' AND NOT EXISTS(SELECT FROM jsonb_array_elements(inv->'sources') s WHERE s->>'sourceMessageId'=item->>'sourceMessageId')) THEN
      RAISE EXCEPTION 'received_discovery_observation_shape' USING ERRCODE='23514';
    END IF;
  END LOOP;
  v_hash:=encode(sha256(convert_to(p_inventory_text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.discovery_attempts(snapshot_id,company_id,environment,engine_version,inventory_text,inventory_hash)
    VALUES(snap.id,p_company_id,p_environment,p_engine_version,p_inventory_text,v_hash) RETURNING id INTO v_id;
  RETURN jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,'snapshotId',snap.id,
    'snapshotHash',snap.manifest_hash,'engineVersion',p_engine_version,'attemptId',v_id,'inventoryHash',v_hash);
END $_$;

--
-- Name: append_object_assessment(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_object_assessment(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_canonical_assessment_id uuid, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; canonical gridex_received_sources.validation_assessments%rowtype;
 facts jsonb; original jsonb; entry jsonb; scope jsonb; register_fact jsonb; business jsonb; party jsonb; records jsonb;
 position integer:=0; prior uuid; result_id uuid; digest text; snapshot_text text; valid_owners boolean; owner_readsets jsonb:='[]'::jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 IF NOT FOUND OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR src.received_context IS NULL OR p_facts_text IS NULL OR octet_length(p_facts_text)>262144 THEN RAISE EXCEPTION 'source_object_scope_unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments WHERE id=p_canonical_assessment_id AND source_message_id=src.source_message_id AND company_id=p_company_id AND environment=p_environment AND source_payload_hash=src.payload_hash;
 IF NOT FOUND THEN RAISE EXCEPTION 'source_object_canonical_unavailable' USING ERRCODE='23514'; END IF;
 facts:=p_facts_text::jsonb; original:=canonical.facts_text::jsonb;
 IF jsonb_typeof(facts) IS DISTINCT FROM 'object' OR NOT facts ?& ARRAY['version','owner','ruleVersion','canonicalFactsHash','objects']
 OR facts-ARRAY['version','owner','ruleVersion','canonicalFactsHash','objects']<>'{}'::jsonb
 OR facts->'version' IS DISTINCT FROM '1'::jsonb OR facts->>'owner' IS DISTINCT FROM 'received-source-object-decisions-v1'
 OR facts->>'ruleVersion' IS DISTINCT FROM '1' OR facts->>'canonicalFactsHash' IS DISTINCT FROM canonical.facts_hash
 OR jsonb_typeof(facts->'objects') IS DISTINCT FROM 'array' OR jsonb_typeof(original#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'source_object_facts_invalid' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(facts->'objects')<>jsonb_array_length(original#>'{registerValidation,objects}') OR jsonb_array_length(facts->'objects') NOT BETWEEN 1 AND 8192 THEN RAISE EXCEPTION 'source_object_membership_incomplete' USING ERRCODE='23514'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(facts->'objects') LOOP
  register_fact:=original#>ARRAY['registerValidation','objects',position::text];position:=position+1;
  scope:=entry->'object';business:=entry->'business';party:=entry->'party';
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR NOT entry ?& ARRAY['object','disposition','reasons','business','party']
   OR entry-ARRAY['object','disposition','reasons','business','party']<>'{}'::jsonb OR scope IS DISTINCT FROM register_fact-ARRAY['disposition','reasons']
   OR coalesce(entry->>'disposition','') NOT IN ('accepted','rejected','unavailable') OR jsonb_typeof(entry->'reasons') IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION 'source_object_decision_invalid' USING ERRCODE='23514';END IF;
  IF (entry->>'disposition'='accepted') IS DISTINCT FROM (jsonb_array_length(entry->'reasons')=0)
   OR jsonb_array_length(entry->'reasons')>128 OR EXISTS(SELECT FROM jsonb_array_elements(entry->'reasons') r WHERE jsonb_typeof(r) IS DISTINCT FROM 'string' OR r#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$') THEN RAISE EXCEPTION 'source_object_reason_invalid' USING ERRCODE='23514'; END IF;
  IF business<>'null'::jsonb AND (jsonb_typeof(business) IS DISTINCT FROM 'object' OR business->>'sourceMessageId' IS DISTINCT FROM src.source_message_id::text OR business->>'sourcePayloadHash' IS DISTINCT FROM src.payload_hash OR business->>'companyId' IS DISTINCT FROM p_company_id::text OR business->>'environment' IS DISTINCT FROM p_environment OR business->'object' IS DISTINCT FROM scope) THEN RAISE EXCEPTION 'source_object_business_scope_invalid' USING ERRCODE='23514'; END IF;
  IF party<>'null'::jsonb AND (jsonb_typeof(party) IS DISTINCT FROM 'object' OR party#>>'{source,sourceMessageId}' IS DISTINCT FROM src.source_message_id::text OR party#>>'{source,sourcePayloadHash}' IS DISTINCT FROM src.payload_hash OR party#>>'{source,companyId}' IS DISTINCT FROM p_company_id::text OR party#>>'{source,environment}' IS DISTINCT FROM p_environment OR party->'object' IS DISTINCT FROM scope) THEN RAISE EXCEPTION 'source_object_party_scope_invalid' USING ERRCODE='23514'; END IF;
  IF entry->>'disposition'='accepted' THEN
   IF business->>'owner'='inbound-customer-life-event-v1' THEN
    IF register_fact->>'disposition' IS DISTINCT FROM 'accepted' OR original->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR NOT coalesce(gridex_received_sources.prodat_application_object_accepted_v1(p_company_id,src.source_message_id,canonical.id,scope),false) OR business->'version' IS DISTINCT FROM '1'::jsonb OR party->'version' IS DISTINCT FROM '1'::jsonb THEN RAISE EXCEPTION 'source_object_customer_event_acceptance_unproven' USING ERRCODE='23514';END IF;
    SELECT pg_current_snapshot()::text,gridex_customer_life_events.owner_proof_consistent_v1(party,business,src.source_message_id) INTO snapshot_text,valid_owners;
   ELSE
   IF register_fact->>'disposition' IS DISTINCT FROM 'accepted' OR original->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR (original->>'applicationDecision' IS DISTINCT FROM 'accepted' AND gridex_received_sources.mixed_owned_confirmation_v1(p_company_id,p_environment,src.source_message_id,canonical.id,scope,business) IS NOT TRUE) OR original->>'functionalDecision' IS DISTINCT FROM 'accepted'
    OR (CASE business->>'owner' WHEN 'inbound-z04-switch-confirmation-v1' THEN business->>'businessDisposition'='committed' WHEN 'reviewed-received-structure-v1' THEN business->>'businessDisposition'='reviewed' WHEN 'reviewed-received-closure-v1' THEN business->>'businessDisposition'='reviewed' ELSE false END) IS DISTINCT FROM true
    OR business->'version' IS DISTINCT FROM '1'::jsonb OR party->'version' IS DISTINCT FROM '1'::jsonb
    OR party->>'owner' IS DISTINCT FROM 'received-source-party-binding-v1' OR party->>'ruleVersion' IS DISTINCT FROM '1' OR party->>'disposition' IS DISTINCT FROM 'accepted'
    OR party->'reasons' IS DISTINCT FROM '[]'::jsonb OR party#>>'{receiver,evidence,completeness}' IS DISTINCT FROM 'exact_count'
    OR scope->>'identityAgency' IS DISTINCT FROM '9' OR party#>>'{facility,meteringPoint,id}' IS DISTINCT FROM business->>'meteringPointId'
    OR party#>>'{facility,site,id}' IS DISTINCT FROM business->>'siteId' THEN RAISE EXCEPTION 'source_object_acceptance_unproven' USING ERRCODE='23514'; END IF;
   records:=party#>'{receiver,evidence,records}';
   -- All owner revalidation calls below share this SELECT's snapshot, rather
   -- than treating independent earlier network reads as an atomic observation.
   SELECT pg_current_snapshot()::text,
    (CASE business->>'owner' WHEN 'inbound-z04-switch-confirmation-v1' THEN gridex_received_sources.object_owner_proof_consistent(party,business,src.source_received_at) WHEN 'reviewed-received-structure-v1' THEN gridex_received_sources.review_business_proof_consistent(party,business,src.source_message_id) WHEN 'reviewed-received-closure-v1' THEN gridex_received_sources.review_closure_proof_consistent(party,business,src.source_message_id) ELSE false END)
    AND gridex_received_sources.owner_rows_match('profiles',records->'profiles',p_company_id,p_environment,NULL)
    AND gridex_received_sources.owner_rows_match('identifiers',records->'identifiers',p_company_id,p_environment,NULL)
    AND gridex_received_sources.owner_rows_match('roles',records->'roles',p_company_id,p_environment,(party#>>'{receiver,identity,legalActorId}')::uuid)
    AND gridex_received_sources.owner_rows_match('relations',records->'relations',p_company_id,p_environment,NULL)
    AND (CASE WHEN party#>>'{receiver,identity,representedByTransportAgent}'='true' THEN gridex_received_sources.owner_rows_match('transportIdentifiers',records->'transportIdentifiers',p_company_id,p_environment,(party#>>'{receiver,identity,transportActorId}')::uuid) ELSE records->'transportIdentifiers'='[]'::jsonb END)
    AND gridex_received_sources.owner_rows_match('point',jsonb_build_array(party#>'{facility,meteringPoint}'),p_company_id,p_environment,(business->>'meteringPointId')::uuid)
    AND gridex_received_sources.owner_rows_match('site',jsonb_build_array(party#>'{facility,site}'),p_company_id,p_environment,(business->>'siteId')::uuid)
    AND gridex_received_sources.owner_rows_match('gridOwner',jsonb_build_array(party#>'{facility,gridOwner}'),p_company_id,p_environment,(party#>>'{facility,gridOwner,id}')::uuid)
    AND (business->>'owner' IN ('reviewed-received-structure-v1','reviewed-received-closure-v1') OR EXISTS(SELECT FROM public.supplier_switch_requests sw JOIN public.customer_supply_periods sp ON sp.id=(business->>'supplyPeriodId')::uuid
      WHERE sw.id=(business->>'switchRequestId')::uuid AND sw.company_id=p_company_id AND sp.company_id=p_company_id
      AND sw.inbound_z04_message_id=src.source_message_id AND sp.source_message_id=src.source_message_id
      AND sw.metering_point_id=(business->>'meteringPointId')::uuid AND sp.metering_point_id=sw.metering_point_id
      AND sw.site_id=(business->>'siteId')::uuid AND sw.customer_id=(business->>'customerId')::uuid AND sp.customer_id=sw.customer_id
      AND sw.status='accepted' AND sp.status='confirmed_by_grid_owner'
      AND EXISTS(SELECT FROM public.metering_points mp JOIN public.customer_sites cs ON cs.id=mp.site_id WHERE mp.id=sw.metering_point_id AND mp.company_id=p_company_id AND cs.company_id=p_company_id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id AND cs.id=sw.site_id)
      AND sw.confirmed_start_date::text=business#>>'{committedRecords,switch,confirmedStartDate}' AND sp.start_date::text=business#>>'{committedRecords,supply,startDate}'))
   INTO snapshot_text,valid_owners;
   END IF;
   IF valid_owners IS DISTINCT FROM true THEN RAISE EXCEPTION 'source_object_owner_snapshot_changed' USING ERRCODE='23514'; END IF;
   owner_readsets:=owner_readsets||jsonb_build_array(jsonb_build_object('object',scope,'snapshot',snapshot_text,'observedAt',clock_timestamp()));
  END IF;
 END LOOP;
 SELECT id INTO prior FROM gridex_received_sources.object_assessments a WHERE source_message_id=src.source_message_id AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id);
 digest:=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex');
 INSERT INTO gridex_received_sources.object_assessments(source_message_id,company_id,environment,source_payload_hash,canonical_assessment_id,previous_assessment_id,facts_text,facts_hash,owner_readsets)
 VALUES(src.source_message_id,p_company_id,p_environment,src.payload_hash,canonical.id,prior,p_facts_text,digest,owner_readsets) RETURNING id INTO result_id;
 RETURN jsonb_build_object('version',1,'assessmentId',result_id,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',src.source_message_id,'sourcePayloadHash',src.payload_hash,'canonicalAssessmentId',canonical.id,'factsHash',digest);
END $_$;

--
-- Name: append_prodat_response_validation_v3(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_response_validation_v3(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_response_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;facet jsonb;digest text;
BEGIN
 IF p_response_facts_text IS NOT NULL THEN
  SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
  IF s.source_message_id IS NULL OR s.payload_hash IS DISTINCT FROM p_source_payload_hash OR octet_length(p_response_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  facet:=p_response_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,p_facts_text::jsonb,facet),false) THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  digest:=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex');
 END IF;
 receipt:=gridex_received_sources.append_prodat_validation_v2(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text);
 IF facet IS NOT NULL THEN INSERT INTO gridex_received_sources.prodat_response_facets VALUES((receipt->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_response_facts_text,digest);END IF;
 RETURN receipt||jsonb_build_object('version',3,'responseFactsHash',digest);
END $$;

--
-- Name: append_prodat_source_function_validation_v5(uuid, text, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_source_function_validation_v5(c uuid, env text, source_id uuid, source_hash text, facts_text text, ignored_text text, response_text text, application_text text, function_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;application jsonb;functional jsonb;application_digest text;function_digest text;
BEGIN
 IF function_text IS NULL THEN RETURN gridex_received_sources.append_prodat_validation_v4(c,env,source_id,source_hash,facts_text,ignored_text,response_text,application_text)||jsonb_build_object('version',5,'sourceFunctionFactsHash',NULL);END IF;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=source_id AND company_id=c AND environment=env FOR UPDATE;
 IF s.source_message_id IS NULL OR s.payload_hash IS DISTINCT FROM source_hash OR application_text IS NULL OR octet_length(function_text)>524288 OR octet_length(application_text)>524288 THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
 application:=application_text::jsonb;functional:=function_text::jsonb;
 IF gridex_received_sources.validate_prodat_application_v2(c,source_id,s.raw_payload,facts_text::jsonb,application,response_text::jsonb,functional) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
 application_digest:=encode(sha256(convert_to(application_text,'UTF8')),'hex');function_digest:=encode(sha256(convert_to(function_text,'UTF8')),'hex');
 receipt:=gridex_received_sources.append_prodat_response_validation_v3(c,env,source_id,source_hash,facts_text,ignored_text,response_text);
 INSERT INTO gridex_received_sources.prodat_application_facets VALUES((receipt->>'assessmentId')::uuid,source_id,c,env,source_hash,application_text,application_digest);
 INSERT INTO gridex_received_sources.prodat_source_function_facets VALUES((receipt->>'assessmentId')::uuid,source_id,c,env,source_hash,function_text,function_digest);
 RETURN receipt||jsonb_build_object('version',5,'applicationFactsHash',application_digest,'sourceFunctionFactsHash',function_digest);
END $$;

--
-- Name: append_prodat_validation_v2(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v2(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;fields jsonb;field jsonb;occ jsonb;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;tokens jsonb;line jsonb;digest text;
BEGIN
 -- Canonical source admission/whole register scope remain their prior owner.
 -- This transaction adds only the exclusion list from that same invocation.
 receipt:=gridex_received_sources.append_validation(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 SELECT * INTO STRICT a FROM gridex_received_sources.validation_assessments WHERE id=(receipt->>'assessmentId')::uuid AND company_id=p_company_id AND environment=p_environment;
 SELECT * INTO STRICT s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment;
 IF s.payload_hash IS DISTINCT FROM p_source_payload_hash OR a.source_message_id IS DISTINCT FROM s.source_message_id
  OR a.facts_text IS DISTINCT FROM p_facts_text OR a.facts_hash IS DISTINCT FROM receipt->>'factsHash' THEN RAISE EXCEPTION 'prodat_ignored_same_original_required';END IF;
 IF p_ignored_fields_text IS NOT NULL THEN
  tokens:=gridex_received_sources.closure_wire_tokens_v2(s.raw_payload);
  IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')<>1 THEN RAISE EXCEPTION 'prodat_ignored_same_original_required';END IF;
  IF octet_length(p_ignored_fields_text)>262144 THEN RAISE EXCEPTION 'prodat_ignored_field_budget_exceeded';END IF;fields:=p_ignored_fields_text::jsonb;
  IF jsonb_typeof(fields) IS DISTINCT FROM 'array' OR jsonb_array_length(fields)>8192 OR a.facts_text::jsonb->'registerValidation' IS NULL THEN RAISE EXCEPTION 'prodat_ignored_canonical_scope_required';END IF;
  FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP
   occ:=field->'occurrence';
   IF jsonb_typeof(field) IS DISTINCT FROM 'object' OR field-ARRAY['fieldNumber','sourceRule','occurrence']<>'{}'::jsonb
    OR field->>'sourceRule' IS DISTINCT FROM 'PRODAT26A:P119' OR nullif(field->>'fieldNumber','') IS NULL
    OR jsonb_typeof(occ) IS DISTINCT FROM 'object' OR (occ->>'scope' IN('header','object','register')) IS NOT TRUE
    OR occ->>'messageReference' IS DISTINCT FROM a.facts_text::jsonb->>'messageReference' THEN RAISE EXCEPTION 'prodat_ignored_field_scope_invalid';END IF;
   IF occ->>'scope'<>'header' THEN
    SELECT t INTO line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (SELECT count(*) FROM jsonb_array_elements(tokens) prior WHERE prior->>'tag'='LIN' AND (prior->>'index')::integer<(t->>'index')::integer)=(occ->>'lineIndex')::integer;
    IF line IS NULL OR line#>>'{elements,1,0}' IS DISTINCT FROM occ->>'lineNumber' OR line#>>'{elements,3,0}' IS DISTINCT FROM occ->>'objectId'
     OR line#>>'{elements,3,3}' IS DISTINCT FROM occ->>'identityAgency' THEN RAISE EXCEPTION 'prodat_ignored_field_physical_scope_invalid';END IF;
   END IF;
  END LOOP;
  digest:=encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.prodat_ignored_field_facets(canonical_assessment_id,company_id,environment,source_message_id,source_payload_hash,fields_text,fields_hash)
   VALUES(a.id,p_company_id,p_environment,s.source_message_id,s.payload_hash,p_ignored_fields_text,digest);
 END IF;
 RETURN receipt||jsonb_build_object('version',2,'ignoredFieldsHash',digest);
END $$;

--
-- Name: append_prodat_validation_v3(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v3(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_object_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;facet_receipt jsonb;assessment_id uuid;
BEGIN
 receipt:=gridex_received_sources.append_prodat_validation_v2(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text);
 assessment_id:=(receipt->>'assessmentId')::uuid;
 IF p_object_facts_text IS NOT NULL THEN
  facet_receipt:=public.gridex_record_prodat_object_validation_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,assessment_id,p_object_facts_text);
  IF facet_receipt->>'assessmentId' IS DISTINCT FROM assessment_id::text OR facet_receipt->>'companyId' IS DISTINCT FROM p_company_id::text
   OR facet_receipt->>'environment' IS DISTINCT FROM p_environment OR facet_receipt->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text
   OR facet_receipt->>'sourcePayloadHash' IS DISTINCT FROM p_source_payload_hash
   OR facet_receipt->>'objectFactsHash' IS DISTINCT FROM encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_primary_object_receipt_required';END IF;
 END IF;
 RETURN receipt||jsonb_build_object('version',3,'objectFactsHash',facet_receipt->>'objectFactsHash');
END $$;

--
-- Name: append_prodat_validation_v4(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v4(c uuid, env text, source_id uuid, source_hash text, facts_text text, ignored_text text, response_text text, application_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;facet jsonb;digest text;
BEGIN
 IF application_text IS NOT NULL THEN
  SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=source_id AND company_id=c AND environment=env FOR UPDATE;
  IF s.source_message_id IS NULL OR s.payload_hash IS DISTINCT FROM source_hash OR octet_length(application_text)>524288 THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  facet:=application_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_application_v1(s.raw_payload,facts_text::jsonb,facet,response_text::jsonb),false) THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  digest:=encode(sha256(convert_to(application_text,'UTF8')),'hex');
 END IF;
 receipt:=gridex_received_sources.append_prodat_response_validation_v3(c,env,source_id,source_hash,facts_text,ignored_text,response_text);
 IF facet IS NOT NULL THEN INSERT INTO gridex_received_sources.prodat_application_facets VALUES((receipt->>'assessmentId')::uuid,source_id,c,env,source_hash,application_text,digest);END IF;
 RETURN receipt||jsonb_build_object('version',4,'applicationFactsHash',digest);
END $$;

--
-- Name: append_prodat_validation_v5(uuid, text, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v5(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_object_facts_text text, p_response_facts_text text, p_application_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;m public.ediel_messages%rowtype;facts jsonb;response jsonb;application jsonb;objects jsonb;own jsonb;reg jsonb;app jsonb;planned jsonb;response_hash text;application_hash text;assessment uuid;
BEGIN
 -- Current actual authorization graph comes before any ledger/source/market
 -- lock. Writer-compatible facet locks precede the common graph's SHARE ledger
 -- locks, so two primary writers cannot deadlock while upgrading SHARE locks.
 PERFORM gridex_received_sources.lock_prodat_execution_actor_graph_v1();
 LOCK TABLE gridex_received_sources.validation_assessments,gridex_received_sources.prodat_ignored_field_facets,gridex_received_sources.prodat_object_validation_facets,gridex_received_sources.prodat_response_facets,gridex_received_sources.prodat_application_facets IN SHARE ROW EXCLUSIVE MODE;
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 IF m.id IS NULL OR s.source_message_id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR s.raw_payload IS NULL OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM p_source_payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_v5_same_original_required';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_source_message_id);
 facts:=p_facts_text::jsonb;
 IF p_response_facts_text IS NOT NULL THEN
  IF octet_length(p_response_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response:=p_response_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,facts,response),false) THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response_hash:=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex');
 END IF;
 IF p_application_facts_text IS NOT NULL THEN
  IF octet_length(p_application_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application:=p_application_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_application_v1(s.raw_payload,facts,application,response),false) THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application_hash:=encode(sha256(convert_to(p_application_facts_text,'UTF8')),'hex');
 END IF;
 IF p_object_facts_text IS NOT NULL THEN
  objects:=p_object_facts_text::jsonb;
  -- The physical register partition is the common join between the full-guide
  -- lineIndex, application register scopes and response segmentIndex. Different
  -- indexes or a negative/unknown sibling cannot borrow a positive facet.
  FOR own IN SELECT e FROM jsonb_array_elements(objects->'objects')e LOOP
   SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e->'objectId'=own->'objectId' AND e->'identityAgency'=own->'identityAgency' AND e->'messageReference'=own->'messageReference' AND e#>'{registers,0,lineIndex}'=own->'firstLineIndex';
   IF reg IS NULL THEN RAISE EXCEPTION 'prodat_v5_same_physical_partition_required';END IF;
   IF application IS NOT NULL THEN
    SELECT e INTO app FROM jsonb_array_elements(application->'objects')e WHERE e-'applicationDecision'-'reasonCodes'=reg-'disposition'-'reasons';
    IF app IS NULL OR own->>'disposition'='accepted' AND app->>'applicationDecision' IS DISTINCT FROM 'accepted'
      OR own->>'disposition'='rejected' AND app->>'applicationDecision' IS DISTINCT FROM 'rejected'
      OR own->>'disposition'='unavailable' AND app->>'applicationDecision'='accepted' THEN RAISE EXCEPTION 'prodat_v5_conflicting_own_application';END IF;
   END IF;
   IF response IS NOT NULL THEN
    SELECT e INTO planned FROM jsonb_array_elements(response->'objects')e WHERE e->'lineIndex'=reg#>'{registers,0,segmentIndex}';
    IF planned IS NULL OR planned->'id' IS DISTINCT FROM own->'objectId' OR nullif(planned->'li','null'::jsonb) IS DISTINCT FROM to_jsonb(nullif(own->>'lineItemReference',''))
     OR planned->>'outcome'='positive' AND (own->>'disposition' IS DISTINCT FROM 'accepted' OR application IS NOT NULL AND app->>'applicationDecision' IS DISTINCT FROM 'accepted') THEN RAISE EXCEPTION 'prodat_v5_conflicting_own_response';END IF;
   END IF;
  END LOOP;
 END IF;
 -- This is the sole primary append. Existing full-object v3 invokes the prior
 -- canonical/ignored owner and inserts its own facet under this assessment.
 receipt:=gridex_received_sources.append_prodat_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text,p_object_facts_text);
 assessment:=(receipt->>'assessmentId')::uuid;
 IF receipt->>'companyId' IS DISTINCT FROM p_company_id::text OR receipt->>'environment' IS DISTINCT FROM p_environment OR receipt->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text OR receipt->>'sourcePayloadHash' IS DISTINCT FROM p_source_payload_hash OR receipt->>'factsHash' IS DISTINCT FROM encode(sha256(convert_to(p_facts_text,'UTF8')),'hex') OR receipt->>'objectFactsHash' IS DISTINCT FROM (CASE WHEN p_object_facts_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') END) THEN RAISE EXCEPTION 'prodat_v5_primary_receipt_required';END IF;
 IF response IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_response_facets prior WHERE prior.assessment_id=assessment AND(prior.response_facts_hash IS DISTINCT FROM response_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v5_response_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_response_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_response_facts_text,response_hash) ON CONFLICT DO NOTHING;
 END IF;
 IF application IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_application_facets prior WHERE prior.assessment_id=assessment AND(prior.application_facts_hash IS DISTINCT FROM application_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v5_application_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_application_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_application_facts_text,application_hash) ON CONFLICT DO NOTHING;
 END IF;
 RETURN receipt||jsonb_build_object('version',5,'responseFactsHash',response_hash,'applicationFactsHash',application_hash);
END$$;

--
-- Name: append_prodat_validation_v6(uuid, text, uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v6(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_object_facts_text text, p_response_facts_text text, p_application_facts_text text, p_source_function_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;m public.ediel_messages%rowtype;facts jsonb;response jsonb;application jsonb;functional jsonb;functional_own jsonb;objects jsonb;own jsonb;reg jsonb;app jsonb;planned jsonb;response_hash text;application_hash text;function_hash text;assessment uuid;replay_candidate uuid;replay_rule_pack uuid;replay_rollback boolean:=false;
BEGIN
 -- Current actual authorization graph comes before any ledger/source/market
 -- lock. Writer-compatible facet locks precede the common graph's SHARE ledger
 -- locks, so two primary writers cannot deadlock while upgrading SHARE locks.
 PERFORM gridex_received_sources.lock_prodat_execution_actor_graph_v1();
 LOCK TABLE gridex_received_sources.validation_assessments,gridex_received_sources.prodat_ignored_field_facets,gridex_received_sources.prodat_object_validation_facets,gridex_received_sources.prodat_response_facets,gridex_received_sources.prodat_application_facets,gridex_received_sources.prodat_source_function_facets IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE gridex_customer_life_events.inbound_context_receipts IN SHARE MODE;
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 IF m.id IS NULL OR s.source_message_id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR s.raw_payload IS NULL OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM p_source_payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_v6_same_original_required';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_source_message_id);
 facts:=p_facts_text::jsonb;
 IF p_response_facts_text IS NOT NULL THEN
  IF octet_length(p_response_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response:=p_response_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,facts,response),false) THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response_hash:=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex');
 END IF;
 IF p_source_function_facts_text IS NOT NULL THEN
  IF octet_length(p_source_function_facts_text)>524288 OR p_application_facts_text IS NULL THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
  functional:=p_source_function_facts_text::jsonb;
  IF gridex_received_sources.validate_prodat_source_function_v1(p_company_id,p_source_message_id,s.raw_payload,facts,functional) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
  function_hash:=encode(sha256(convert_to(p_source_function_facts_text,'UTF8')),'hex');
 END IF;
 IF p_application_facts_text IS NOT NULL THEN
  IF octet_length(p_application_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application:=p_application_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_application_v2(p_company_id,p_source_message_id,s.raw_payload,facts,application,response,functional),false) THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application_hash:=encode(sha256(convert_to(p_application_facts_text,'UTF8')),'hex');
 END IF;
 IF p_object_facts_text IS NOT NULL THEN
  objects:=p_object_facts_text::jsonb;
  -- The physical register partition is the common join between the full-guide
  -- lineIndex, application register scopes and response segmentIndex. Different
  -- indexes or a negative sibling cannot borrow a positive facet. A separately
  -- authenticated customer source function never promotes full-guide evidence:
  -- its exact own application may stand independently of a global function hold.
  FOR own IN SELECT e FROM jsonb_array_elements(objects->'objects')e LOOP
   SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e->'objectId'=own->'objectId' AND e->'identityAgency'=own->'identityAgency' AND e->'messageReference'=own->'messageReference' AND e#>'{registers,0,lineIndex}'=own->'firstLineIndex';
   IF reg IS NULL THEN RAISE EXCEPTION 'prodat_v6_same_physical_partition_required';END IF;
   functional_own:=NULL;
   IF functional IS NOT NULL THEN
    SELECT e INTO functional_own FROM jsonb_array_elements(functional->'objects')e WHERE e-'functionalDecision'-'reasonCodes'=reg-'disposition'-'reasons';
    IF functional_own IS NULL THEN RAISE EXCEPTION 'prodat_v6_same_function_partition_required';END IF;
   END IF;
   IF application IS NOT NULL THEN
    SELECT e INTO app FROM jsonb_array_elements(application->'objects')e WHERE e-'applicationDecision'-'reasonCodes'=reg-'disposition'-'reasons';
    IF app IS NULL OR own->>'disposition'='accepted' AND app->>'applicationDecision' IS DISTINCT FROM 'accepted'
      OR own->>'disposition'='rejected' AND app->>'applicationDecision' IS DISTINCT FROM 'rejected'
      OR own->>'disposition'='unavailable' AND app->>'applicationDecision'='accepted' AND (functional_own->>'functionalDecision' IS DISTINCT FROM 'accepted' OR own->'reasons' IS DISTINCT FROM '["shared_source_not_qualified"]'::jsonb) THEN RAISE EXCEPTION 'prodat_v6_conflicting_own_application';END IF;
   END IF;
   IF response IS NOT NULL THEN
    SELECT e INTO planned FROM jsonb_array_elements(response->'objects')e WHERE e->'lineIndex'=reg#>'{registers,0,segmentIndex}';
    IF planned IS NULL OR planned->'id' IS DISTINCT FROM own->'objectId' OR nullif(planned->'li','null'::jsonb) IS DISTINCT FROM to_jsonb(nullif(own->>'lineItemReference',''))
     OR planned->>'outcome'='positive' AND ((own->>'disposition' IS DISTINCT FROM 'accepted' AND (functional_own->>'functionalDecision' IS DISTINCT FROM 'accepted' OR app->>'applicationDecision' IS DISTINCT FROM 'accepted' OR own->>'disposition' IS DISTINCT FROM 'unavailable' OR own->'reasons' IS DISTINCT FROM '["shared_source_not_qualified"]'::jsonb)) OR application IS NOT NULL AND app->>'applicationDecision' IS DISTINCT FROM 'accepted') THEN RAISE EXCEPTION 'prodat_v6_conflicting_own_response';END IF;
   END IF;
  END LOOP;
 END IF;
 -- Retain registry authority locks through an equivalent-append rollback.
 -- The inherited validator below still verifies every locked snapshot byte.
 IF facts->>'applicationDecision'='accepted' THEN
  LOCK TABLE public.ediel_rule_pack_sources IN SHARE MODE;
  SELECT id INTO replay_rule_pack FROM public.ediel_rule_packs
   WHERE id::text=facts#>>'{rulePackEvidence,rulePackId}'
    AND source_hash=facts#>>'{rulePackEvidence,sourceHash}' FOR SHARE;
  PERFORM 1 FROM public.ediel_message_profiles
   WHERE id::text=facts#>>'{rulePackEvidence,messageProfileId}'
    AND rule_pack_id=replay_rule_pack
    AND profile_key=facts#>>'{rulePackEvidence,profileKey}' FOR SHARE;
 END IF;
 -- Count every leaf before matching: no ancestor, ambiguous branch or ABA reuse.
 WITH leaves AS (
  SELECT v.id FROM gridex_received_sources.validation_assessments v
   WHERE v.source_message_id=p_source_message_id
    AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
 ) SELECT id INTO replay_candidate FROM leaves WHERE (SELECT count(*) FROM leaves)=1;
 BEGIN
 -- This is the sole primary append. Existing full-object v3 invokes the prior
 -- canonical/ignored owner and inserts its own facet under this assessment.
 receipt:=gridex_received_sources.append_prodat_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text,p_object_facts_text);
 assessment:=(receipt->>'assessmentId')::uuid;
 IF receipt->>'companyId' IS DISTINCT FROM p_company_id::text OR receipt->>'environment' IS DISTINCT FROM p_environment OR receipt->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text OR receipt->>'sourcePayloadHash' IS DISTINCT FROM p_source_payload_hash OR receipt->>'factsHash' IS DISTINCT FROM encode(sha256(convert_to(p_facts_text,'UTF8')),'hex') OR receipt->>'objectFactsHash' IS DISTINCT FROM (CASE WHEN p_object_facts_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') END) THEN RAISE EXCEPTION 'prodat_v6_primary_receipt_required';END IF;
 IF response IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_response_facets prior WHERE prior.assessment_id=assessment AND(prior.response_facts_hash IS DISTINCT FROM response_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_response_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_response_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_response_facts_text,response_hash) ON CONFLICT DO NOTHING;
 END IF;
 IF application IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_application_facets prior WHERE prior.assessment_id=assessment AND(prior.application_facts_hash IS DISTINCT FROM application_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_application_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_application_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_application_facts_text,application_hash) ON CONFLICT DO NOTHING;
 END IF;
 IF functional IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_source_function_facets prior WHERE prior.assessment_id=assessment AND(prior.function_facts_hash IS DISTINCT FROM function_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_source_function_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_source_function_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_source_function_facts_text,function_hash) ON CONFLICT DO NOTHING;
 END IF;
 -- Only a fully validated identical positive leaf can retain its identity.
 -- The redundant child and its facets have not committed; rollback does not
 -- delete or rewrite any existing history, receipt, ACK or market effect.
 IF replay_candidate IS NOT NULL AND assessment IS DISTINCT FROM replay_candidate
  AND facts->>'syntaxDecision'='accepted' AND facts->>'applicationDecision'='accepted'
  AND facts->>'functionalDecision'='accepted'
  AND EXISTS(SELECT FROM gridex_received_sources.validation_assessments v
   LEFT JOIN gridex_received_sources.prodat_ignored_field_facets ignored ON ignored.canonical_assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_object_validation_facets object ON object.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_response_facets response_facet ON response_facet.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_application_facets application_facet ON application_facet.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_source_function_facets function_facet ON function_facet.assessment_id=v.id
   WHERE v.id=replay_candidate
    AND v.owner='canonical-runtime-with-registry-v1'
    AND v.company_id=p_company_id
    AND v.environment=p_environment
    AND v.source_message_id=p_source_message_id
    AND v.source_payload_hash=p_source_payload_hash
    AND v.facts_text IS NOT DISTINCT FROM p_facts_text
    AND v.facts_hash=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex')
    AND EXISTS(SELECT FROM gridex_received_sources.validation_assessments attempted WHERE attempted.id=assessment AND attempted.previous_assessment_id=v.id AND attempted.source_message_id=v.source_message_id)
    AND ((p_ignored_fields_text IS NULL AND ignored.canonical_assessment_id IS NULL) OR
     (p_ignored_fields_text IS NOT NULL AND ignored.canonical_assessment_id IS NOT NULL
      AND ignored.company_id=p_company_id AND ignored.environment=p_environment
      AND ignored.source_message_id=p_source_message_id AND ignored.source_payload_hash=p_source_payload_hash
      AND ignored.fields_text IS NOT DISTINCT FROM p_ignored_fields_text
      AND ignored.fields_hash=encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex')))
    AND ((p_object_facts_text IS NULL AND object.assessment_id IS NULL) OR
     (p_object_facts_text IS NOT NULL AND object.assessment_id IS NOT NULL
      AND object.company_id=p_company_id AND object.environment=p_environment
      AND object.source_message_id=p_source_message_id AND object.source_payload_hash=p_source_payload_hash
      AND object.facts_text IS NOT DISTINCT FROM p_object_facts_text
      AND object.facts_hash=encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex')))
    AND ((p_response_facts_text IS NULL AND response_facet.assessment_id IS NULL) OR
     (p_response_facts_text IS NOT NULL AND response_facet.assessment_id IS NOT NULL
      AND response_facet.company_id=p_company_id AND response_facet.environment=p_environment
      AND response_facet.source_message_id=p_source_message_id AND response_facet.source_payload_hash=p_source_payload_hash
      AND response_facet.response_facts_text IS NOT DISTINCT FROM p_response_facts_text
      AND response_facet.response_facts_hash=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex')))
    AND ((p_application_facts_text IS NULL AND application_facet.assessment_id IS NULL) OR
     (p_application_facts_text IS NOT NULL AND application_facet.assessment_id IS NOT NULL
      AND application_facet.company_id=p_company_id AND application_facet.environment=p_environment
      AND application_facet.source_message_id=p_source_message_id AND application_facet.source_payload_hash=p_source_payload_hash
      AND application_facet.application_facts_text IS NOT DISTINCT FROM p_application_facts_text
      AND application_facet.application_facts_hash=encode(sha256(convert_to(p_application_facts_text,'UTF8')),'hex')))
    AND ((p_source_function_facts_text IS NULL AND function_facet.assessment_id IS NULL) OR
     (p_source_function_facts_text IS NOT NULL AND function_facet.assessment_id IS NOT NULL
      AND function_facet.company_id=p_company_id AND function_facet.environment=p_environment
      AND function_facet.source_message_id=p_source_message_id AND function_facet.source_payload_hash=p_source_payload_hash
      AND function_facet.function_facts_text IS NOT DISTINCT FROM p_source_function_facts_text
      AND function_facet.function_facts_hash=encode(sha256(convert_to(p_source_function_facts_text,'UTF8')),'hex')))) THEN
  replay_rollback:=true;
  RAISE EXCEPTION 'ediel_equivalent_prodat_canonical_replay_rollback' USING ERRCODE='GX001';
 END IF;
 EXCEPTION WHEN SQLSTATE 'GX001' THEN
  IF replay_rollback IS NOT TRUE OR SQLERRM IS DISTINCT FROM 'ediel_equivalent_prodat_canonical_replay_rollback' THEN RAISE;END IF;
  RETURN jsonb_build_object('version',6,'assessmentId',replay_candidate,'companyId',p_company_id,'environment',p_environment,
   'sourceMessageId',p_source_message_id,'sourcePayloadHash',p_source_payload_hash,
   'factsHash',encode(sha256(convert_to(p_facts_text,'UTF8')),'hex'),'sourceDisposition','not_established',
   'ignoredFieldsHash',CASE WHEN p_ignored_fields_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex') END,
   'objectFactsHash',CASE WHEN p_object_facts_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') END,
   'responseFactsHash',response_hash,'applicationFactsHash',application_hash,'sourceFunctionFactsHash',function_hash);
 END;
 RETURN receipt||jsonb_build_object('version',6,'responseFactsHash',response_hash,'applicationFactsHash',application_hash,'sourceFunctionFactsHash',function_hash);
END$$;

--
-- Name: append_utilts_validation_v1(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_utilts_validation_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_transaction_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;m public.ediel_messages%rowtype;response jsonb;projection jsonb;projection_hash text;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment;
 IF src.source_message_id IS NULL OR m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'UTILTS'
  OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR m.raw_payload IS DISTINCT FROM src.raw_payload OR src.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' THEN RAISE EXCEPTION 'received_utilts_transaction_source_unavailable' USING ERRCODE='23514'; END IF;
 IF p_transaction_facts_text IS NOT NULL THEN
  IF octet_length(p_transaction_facts_text)>524288 THEN RAISE EXCEPTION 'received_utilts_transaction_facts_invalid' USING ERRCODE='23514'; END IF;
  projection:=p_transaction_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(src.raw_payload,projection),false) THEN RAISE EXCEPTION 'received_utilts_transaction_facts_invalid' USING ERRCODE='23514'; END IF;
  projection_hash:=encode(sha256(convert_to(p_transaction_facts_text,'UTF8')),'hex');
 END IF;
 response:=gridex_received_sources.append_validation(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 IF projection IS NOT NULL THEN
  INSERT INTO gridex_received_sources.utilts_transaction_validations(assessment_id,source_message_id,company_id,environment,source_payload_hash,transaction_facts_text,transaction_facts_hash)
   VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_transaction_facts_text,projection_hash);
 END IF;
 RETURN response||jsonb_build_object('transactionFactsHash',projection_hash);
END $$;

--
-- Name: append_utilts_validation_v2(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_utilts_validation_v2(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_transaction_facts_text text, p_header_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;projection jsonb;facts jsonb;transactions jsonb;response jsonb;projection_hash text;
BEGIN
 IF p_header_facts_text IS NOT NULL THEN
  SELECT * INTO src FROM gridex_received_sources.sources WHERE company_id=p_company_id AND environment=p_environment AND source_message_id=p_source_message_id FOR UPDATE;
  IF src.source_message_id IS NULL OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR octet_length(p_header_facts_text)>524288 THEN RAISE EXCEPTION 'received_utilts_header_facts_invalid' USING ERRCODE='23514'; END IF;
  projection:=p_header_facts_text::jsonb;facts:=p_facts_text::jsonb;transactions:=p_transaction_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_utilts_header_v1(src.raw_payload,projection),false)
   OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'applicationDecision','') NOT IN ('rejected','manual_review')
   OR NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(src.raw_payload,transactions),false)
   OR EXISTS(SELECT FROM jsonb_array_elements(transactions->'transactions') t WHERE t->>'disposition' IS DISTINCT FROM 'guide_rejected' OR t->>'responseType' IS DISTINCT FROM 'negative_aperak') THEN RAISE EXCEPTION 'received_utilts_header_facts_invalid' USING ERRCODE='23514'; END IF;
  projection_hash:=encode(sha256(convert_to(p_header_facts_text,'UTF8')),'hex');
 END IF;
 response:=gridex_received_sources.append_utilts_validation_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_transaction_facts_text);
 IF projection IS NOT NULL THEN
  INSERT INTO gridex_received_sources.utilts_header_validations(assessment_id,source_message_id,company_id,environment,source_payload_hash,header_facts_text,header_facts_hash)
   VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_header_facts_text,projection_hash);
 END IF;
 RETURN response||jsonb_build_object('version',2,'headerFactsHash',projection_hash);
END $$;

--
-- Name: append_utilts_validation_v3(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_utilts_validation_v3(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_transaction_facts_text text, p_header_facts_text text, p_functional_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;projection jsonb;facts jsonb;transactions jsonb;response jsonb;projection_hash text;
BEGIN
 IF p_functional_facts_text IS NOT NULL THEN
  SELECT * INTO src FROM gridex_received_sources.sources WHERE company_id=p_company_id AND environment=p_environment AND source_message_id=p_source_message_id FOR UPDATE;
  IF src.source_message_id IS NULL OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR octet_length(p_functional_facts_text)>2097152 THEN RAISE EXCEPTION 'received_utilts_functional_facts_invalid' USING ERRCODE='23514'; END IF;
  projection:=p_functional_facts_text::jsonb;facts:=p_facts_text::jsonb;transactions:=p_transaction_facts_text::jsonb;
  IF facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'functionalDecision','') NOT IN ('rejected','manual_review')
   OR NOT coalesce(gridex_received_sources.validate_utilts_functional_v1(src.raw_payload,projection,transactions),false) THEN RAISE EXCEPTION 'received_utilts_functional_facts_invalid' USING ERRCODE='23514'; END IF;
  projection_hash:=encode(sha256(convert_to(p_functional_facts_text,'UTF8')),'hex');
 END IF;
 response:=gridex_received_sources.append_utilts_validation_v2(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_transaction_facts_text,p_header_facts_text);
 IF projection IS NOT NULL THEN
  INSERT INTO gridex_received_sources.utilts_functional_validations(assessment_id,source_message_id,company_id,environment,source_payload_hash,functional_facts_text,functional_facts_hash)
   VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_functional_facts_text,projection_hash);
 END IF;
 RETURN response||jsonb_build_object('version',3,'functionalFactsHash',projection_hash);
END $$;

--
-- Name: append_utilts_validation_v4(uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_utilts_validation_v4(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_transaction_facts_text text, p_header_facts_text text, p_functional_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;projection jsonb;facts jsonb;transactions jsonb;response jsonb;projection_hash text;
BEGIN
 IF p_functional_facts_text IS NULL OR p_functional_facts_text::jsonb->'version'='1'::jsonb THEN
  RETURN gridex_received_sources.append_utilts_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_transaction_facts_text,p_header_facts_text,p_functional_facts_text)||jsonb_build_object('version',4);
 END IF;
 SELECT * INTO src FROM gridex_received_sources.sources WHERE company_id=p_company_id AND environment=p_environment AND source_message_id=p_source_message_id FOR UPDATE;
 IF src.source_message_id IS NULL OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR octet_length(p_functional_facts_text)>2097152 THEN RAISE EXCEPTION 'received_utilts_functional_facts_invalid' USING ERRCODE='23514'; END IF;
 projection:=p_functional_facts_text::jsonb;facts:=p_facts_text::jsonb;transactions:=p_transaction_facts_text::jsonb;
 IF facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'functionalDecision','') NOT IN ('rejected','manual_review')
  OR NOT coalesce(gridex_received_sources.validate_utilts_functional_v2(src.raw_payload,projection,transactions),false) THEN RAISE EXCEPTION 'received_utilts_functional_facts_invalid' USING ERRCODE='23514'; END IF;
 projection_hash:=encode(sha256(convert_to(p_functional_facts_text,'UTF8')),'hex');
 response:=gridex_received_sources.append_utilts_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_transaction_facts_text,p_header_facts_text,NULL);
 INSERT INTO gridex_received_sources.utilts_functional_validations_v2(assessment_id,source_message_id,company_id,environment,source_payload_hash,functional_facts_text,functional_facts_hash)
  VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_functional_facts_text,projection_hash);
 RETURN response||jsonb_build_object('version',4,'functionalFactsHash',projection_hash);
END $$;

--
-- Name: append_validation(uuid, text, uuid, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_validation(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;result jsonb;BEGIN
 -- Preserve the existing source-ledger -> actual-message lock order. A new
 -- invalid assessment and its delegate writes roll back in this same RPC.
 result:=gridex_received_sources.append_validation_before_unused_unh_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 IF p_facts_text::jsonb->>'syntaxDecision'='accepted' AND p_facts_text::jsonb->>'applicationDecision'='accepted' THEN
  -- The protected delegate has already verified the tenant-bound retained
  -- source/hash. A physical technical source may retain company_id NULL;
  -- this check observes those exact same bytes without assigning a tenant.
  SELECT s.raw_payload INTO STRICT m.raw_payload FROM gridex_received_sources.sources s WHERE s.source_message_id=p_source_message_id AND s.company_id=p_company_id AND s.environment=p_environment
   AND s.raw_payload IS NOT NULL AND s.payload_hash=p_source_payload_hash AND encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')=p_source_payload_hash;
  PERFORM gridex_ediel_ack_guide.require_unused_unh_v1(m.raw_payload,'inbound');END IF;
 RETURN result;END $$;

--
-- Name: append_validation_before_reference_profile_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_validation_before_reference_profile_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; facts jsonb; pack jsonb; v_previous uuid; v_id uuid; v_hash text; registered public.ediel_rule_packs%rowtype;registered_profile public.ediel_message_profiles%rowtype;registered_sources jsonb;original_ack jsonb;actual_message public.ediel_messages%rowtype;facet jsonb; obj jsonb; reg jsonb; key text; object_keys text[]:=ARRAY[]::text[]; line_ids text[]:=ARRAY[]::text[]; segment_ids int[]:=ARRAY[]::int[]; previous_segment int; position int;
BEGIN
  -- Lock per source before selecting a predecessor. Concurrent assessments
  -- append a single linked sequence; no UPDATE of historic decisions occurs.
  SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id
    AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
  IF NOT FOUND OR src.payload_hash IS NULL OR src.received_context IS NULL
    OR p_source_payload_hash IS DISTINCT FROM src.payload_hash OR p_facts_text IS NULL OR octet_length(p_facts_text)>65536 THEN
    RAISE EXCEPTION 'received_validation_source_unavailable' USING ERRCODE='23514';
  END IF;
  facts:=p_facts_text::jsonb;
  IF jsonb_typeof(facts) IS DISTINCT FROM 'object'
    OR facts - ARRAY['version','owner','sourceDisposition','objectDisposition','partyDisposition','coverage','originalTenantMatch','syntaxDecision','applicationDecision','functionalDecision','messageReference','reasonCodes','rulePackEvidence','registerValidation'] <> '{}'::jsonb
    OR facts->'version' IS DISTINCT FROM '1'::jsonb OR facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1'
    OR facts->>'sourceDisposition' IS DISTINCT FROM 'not_established' OR facts->>'objectDisposition' IS DISTINCT FROM 'not_checked'
    OR facts->>'partyDisposition' IS DISTINCT FROM 'not_checked' OR facts->>'coverage' IS DISTINCT FROM 'canonical_runtime_only'
    OR facts->>'originalTenantMatch' IS DISTINCT FROM 'matched'
    OR coalesce(facts->>'syntaxDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR coalesce(facts->>'applicationDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR coalesce(facts->>'functionalDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR jsonb_typeof(facts->'reasonCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(facts->'reasonCodes')>128
    OR coalesce(jsonb_typeof(facts->'messageReference'),'missing') NOT IN ('string','null')
    OR length(coalesce(facts->>'messageReference',''))>128 THEN
    RAISE EXCEPTION 'received_validation_not_source_approval' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT FROM jsonb_array_elements(facts->'reasonCodes') AS value WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR value#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$') THEN
    RAISE EXCEPTION 'received_validation_reason_unavailable' USING ERRCODE='23514';
  END IF;
  pack:=facts->'rulePackEvidence';
  IF facts->>'applicationDecision'='accepted' AND (pack IS NULL OR pack='null'::jsonb) THEN
    RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
  END IF;
  IF pack IS DISTINCT FROM 'null'::jsonb THEN
    IF jsonb_typeof(pack) IS DISTINCT FROM 'object' OR NOT pack ?& ARRAY['profileKey','messageProfileId','rulePackId','sourceHash','version','snapshot']
      OR pack - ARRAY['profileKey','messageProfileId','rulePackId','sourceHash','version','snapshot'] <> '{}'::jsonb
      OR jsonb_typeof(pack->'snapshot') IS DISTINCT FROM 'object'
      OR NOT (pack->'snapshot') ?& ARRAY['rulePack','messageProfile','guideSources']
      OR (pack->'snapshot')-ARRAY['rulePack','messageProfile','guideSources'] <> '{}'::jsonb THEN
      RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
    END IF;
    SELECT * INTO actual_message FROM public.ediel_messages WHERE id=src.source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
    IF actual_message.message_family IN ('APERAK','CONTRL','UTILTS_ERR') THEN
      -- An ACK inherits the protected original's immutable witness. A later
      -- edit of activation rows never replaces its historic guide authority.
      original_ack:=gridex_ediel_source_rules.read_ack_source_before_basis_v1(p_company_id,p_environment,src.source_message_id);
      IF original_ack IS NOT NULL THEN
        original_ack:=gridex_ediel_source_rules.require_v1(p_company_id,(original_ack#>>'{sourceMessage,id}')::uuid);
      END IF;
      IF original_ack IS NULL OR pack IS DISTINCT FROM jsonb_build_object('profileKey',original_ack->'profileKey',
        'messageProfileId',original_ack->'messageProfileId','rulePackId',original_ack->'rulePackId','sourceHash',original_ack->'sourceHash',
        'version',original_ack->'version','snapshot',jsonb_build_object('rulePack',original_ack#>'{snapshot,rulePack}',
          'messageProfile',original_ack#>'{snapshot,messageProfile}','guideSources',original_ack#>'{snapshot,guideSources}')) THEN
        RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
      END IF;
    ELSE
      LOCK TABLE public.ediel_rule_pack_sources IN SHARE MODE;
      SELECT * INTO registered FROM public.ediel_rule_packs WHERE id::text=pack->>'rulePackId' AND source_hash=pack->>'sourceHash' FOR SHARE;
      SELECT * INTO registered_profile FROM public.ediel_message_profiles WHERE id::text=pack->>'messageProfileId'
        AND rule_pack_id=registered.id AND profile_key=pack->>'profileKey' FOR SHARE;
      SELECT coalesce(jsonb_agg(to_jsonb(source) ORDER BY source.id),'[]'::jsonb) INTO registered_sources FROM public.ediel_rule_pack_sources source WHERE rule_pack_id=registered.id;
      IF registered.id IS NULL OR registered_profile.id IS NULL
        OR pack->>'version' IS DISTINCT FROM registered.guide_version||':r'||registered.guide_revision
        OR pack#>'{snapshot,rulePack}' IS DISTINCT FROM to_jsonb(registered)
        OR pack#>'{snapshot,messageProfile}' IS DISTINCT FROM to_jsonb(registered_profile)
        OR pack#>'{snapshot,guideSources}' IS DISTINCT FROM registered_sources THEN
        RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  -- Optional live-owner register facet. Historical facet-only callers remain
  -- valid. This never grants full source, tenant, legal-party or business approval.
  IF facts ? 'registerValidation' THEN
    facet:=facts->'registerValidation';
    IF pack IS NULL OR pack='null'::jsonb OR jsonb_typeof(facet) IS DISTINCT FROM 'object'
      OR NOT facet ?& ARRAY['version','owner','coverage','objects']
      OR facet-ARRAY['version','owner','coverage','objects'] <> '{}'::jsonb
      OR facet->'version' IS DISTINCT FROM '1'::jsonb
      OR facet->>'owner' IS DISTINCT FROM 'validateProdatRegisterPolicy'
      OR facet->>'coverage' IS DISTINCT FROM 'canonical_register_only'
      OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'received_register_facet_invalid' USING ERRCODE='23514';
    END IF;
    IF jsonb_array_length(facet->'objects')>8192 THEN
      RAISE EXCEPTION 'received_register_facet_budget' USING ERRCODE='23514';
    END IF;
    FOR obj IN SELECT value FROM jsonb_array_elements(facet->'objects') LOOP
      IF jsonb_typeof(obj) IS DISTINCT FROM 'object'
        OR NOT obj ?& ARRAY['messageIndex','messageReference','objectId','identityAgency','disposition','registers','reasons']
        OR obj-ARRAY['messageIndex','messageReference','objectId','identityAgency','disposition','registers','reasons'] <> '{}'::jsonb
        OR jsonb_typeof(obj->'messageIndex') IS DISTINCT FROM 'number'
        OR coalesce(obj->>'messageIndex','') !~ '^(-1|[0-9]{1,4})$'
        OR coalesce(obj->>'disposition','') NOT IN ('accepted','rejected','unavailable')
        OR jsonb_typeof(obj->'registers') IS DISTINCT FROM 'array'
        OR jsonb_typeof(obj->'reasons') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'received_register_object_invalid' USING ERRCODE='23514';
      END IF;
      IF (obj->>'messageIndex')::int>=8192 OR jsonb_array_length(obj->'registers') NOT BETWEEN 1 AND 8192
        OR jsonb_array_length(obj->'reasons')>128 THEN
        RAISE EXCEPTION 'received_register_object_budget' USING ERRCODE='23514';
      END IF;
      FOREACH key IN ARRAY ARRAY['messageReference','objectId','identityAgency'] LOOP
        IF obj->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(obj->key) IS DISTINCT FROM 'string'
          OR length(obj->>key) NOT BETWEEN 1 AND 128 OR obj->>key <> btrim(obj->>key) OR obj->>key ~ '[[:cntrl:]]') THEN
          RAISE EXCEPTION 'received_register_identity_invalid' USING ERRCODE='23514';
        END IF;
      END LOOP;
      IF obj->>'disposition'<>'unavailable' AND ((obj->>'messageIndex')::int<>0 OR jsonb_typeof(obj->'messageReference')<>'string'
        OR ((jsonb_typeof(obj->'objectId')<>'string' OR coalesce(obj->>'identityAgency','') NOT IN ('9','89'))
          AND NOT ((obj->>'disposition'='accepted' AND gridex_received_sources.identity_omission_scope_v1(src.raw_payload,obj)) OR (obj->>'disposition'='rejected' AND (gridex_received_sources.rejected_identity_scope_v1(src.raw_payload,obj) IS TRUE OR gridex_received_sources.rejected_z04h_identity_scope_v1(src.raw_payload,obj) IS TRUE))))) THEN
        RAISE EXCEPTION 'received_register_unvalidated_scope' USING ERRCODE='23514';
      END IF;
      IF (obj->>'disposition'='accepted') IS DISTINCT FROM (jsonb_array_length(obj->'reasons')=0)
        OR EXISTS(SELECT FROM jsonb_array_elements(obj->'reasons') r WHERE jsonb_typeof(r) IS DISTINCT FROM 'string' OR r#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$')
        OR (SELECT count(*)<>count(DISTINCT r) FROM jsonb_array_elements(obj->'reasons') r) THEN
        RAISE EXCEPTION 'received_register_reason_invalid' USING ERRCODE='23514';
      END IF;
      key:=jsonb_build_array(obj->'messageIndex',obj->'objectId',obj->'identityAgency',CASE WHEN obj->'objectId'='null'::jsonb THEN obj#>'{registers,0,lineIndex}' ELSE 'null'::jsonb END)::text;
      IF key=ANY(object_keys) THEN RAISE EXCEPTION 'received_register_duplicate_object' USING ERRCODE='23514'; END IF;
      object_keys:=array_append(object_keys,key);
      previous_segment:=-1; position:=0;
      FOR reg IN SELECT value FROM jsonb_array_elements(obj->'registers') LOOP
        position:=position+1;
        IF jsonb_typeof(reg) IS DISTINCT FROM 'object'
          OR NOT reg ?& ARRAY['lineIndex','lineNumber','registerIndex','registerPosition','segmentIndex']
          OR reg-ARRAY['lineIndex','lineNumber','registerIndex','registerPosition','segmentIndex'] <> '{}'::jsonb THEN
          RAISE EXCEPTION 'received_register_occurrence_invalid' USING ERRCODE='23514';
        END IF;
        FOREACH key IN ARRAY ARRAY['lineIndex','registerPosition','segmentIndex'] LOOP
          IF jsonb_typeof(reg->key) IS DISTINCT FROM 'number' OR coalesce(reg->>key,'') !~ '^[0-9]{1,4}$' THEN
            RAISE EXCEPTION 'received_register_index_invalid' USING ERRCODE='23514';
          END IF;
          IF (reg->>key)::int>=8192 THEN RAISE EXCEPTION 'received_register_index_budget' USING ERRCODE='23514'; END IF;
        END LOOP;
        FOREACH key IN ARRAY ARRAY['lineNumber','registerIndex'] LOOP
          IF reg->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(reg->key) IS DISTINCT FROM 'string'
            OR length(reg->>key) NOT BETWEEN 1 AND 128 OR reg->>key<>btrim(reg->>key) OR reg->>key ~ '[[:cntrl:]]') THEN
            RAISE EXCEPTION 'received_register_wire_index_invalid' USING ERRCODE='23514';
          END IF;
        END LOOP;
        IF (reg->>'registerPosition')::int<>position OR (reg->>'segmentIndex')::int<=previous_segment
          OR jsonb_build_array(obj->'messageIndex',reg->'lineIndex')::text=ANY(line_ids) OR (reg->>'segmentIndex')::int=ANY(segment_ids) THEN
          RAISE EXCEPTION 'received_register_occurrence_conflict' USING ERRCODE='23514';
        END IF;
        line_ids:=array_append(line_ids,jsonb_build_array(obj->'messageIndex',reg->'lineIndex')::text);
        segment_ids:=array_append(segment_ids,(reg->>'segmentIndex')::int);
        previous_segment:=(reg->>'segmentIndex')::int;
      END LOOP;
    END LOOP;
  END IF;
  SELECT prior.id INTO v_previous FROM gridex_received_sources.validation_assessments prior WHERE prior.source_message_id=src.source_message_id
    AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=prior.id);
  v_hash:=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.validation_assessments(source_message_id,company_id,environment,source_payload_hash,previous_assessment_id,facts_text,facts_hash)
    VALUES(src.source_message_id,p_company_id,p_environment,src.payload_hash,v_previous,p_facts_text,v_hash) RETURNING id INTO v_id;
  RETURN jsonb_build_object('version',1,'assessmentId',v_id,'companyId',p_company_id,'environment',p_environment,
    'sourceMessageId',src.source_message_id,'sourcePayloadHash',src.payload_hash,'factsHash',v_hash,'sourceDisposition','not_established');
END $_$;

--
-- Name: append_validation_before_unused_unh_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_validation_before_unused_unh_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;result jsonb;BEGIN
 -- Preserve the existing source-ledger -> actual-message lock order. A new
 -- invalid assessment and its delegate writes roll back in this same RPC.
 result:=gridex_received_sources.append_validation_before_reference_profile_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 IF p_facts_text::jsonb->>'syntaxDecision'='accepted' THEN
  -- The protected delegate has already verified the tenant-bound retained
  -- source/hash. A physical technical source may retain company_id NULL;
  -- this check observes those exact same bytes without assigning a tenant.
  SELECT s.raw_payload INTO STRICT m.raw_payload FROM gridex_received_sources.sources s WHERE s.source_message_id=p_source_message_id AND s.company_id=p_company_id AND s.environment=p_environment
   AND s.raw_payload IS NOT NULL AND s.payload_hash=p_source_payload_hash AND encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')=p_source_payload_hash;
  PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(m.raw_payload);END IF;
 RETURN result;END $$;

--
-- Name: applied_structural_method_objects_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.applied_structural_method_objects_v1(c uuid, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;s gridex_received_sources.sources%rowtype;a gridex_received_sources.object_assessments%rowtype;f gridex_received_sources.prodat_ignored_field_facets%rowtype;
 own jsonb;assessed jsonb;business jsonb;first_register jsonb;token jsonb;characteristic text;method text;method_count integer;out jsonb:='[]';
BEGIN
 <<receipt_loop>> FOR r IN SELECT company_id,environment,source_message_id,payload_hash,object_assessment_id,canonical_assessment_id,source_received_at,applied_at,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND source_message_id=msg
 UNION ALL SELECT company_id,environment,source_message_id,payload_hash,object_assessment_id,canonical_assessment_id,source_received_at,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND source_message_id=msg LOOP
 SELECT * INTO s FROM gridex_received_sources.sources WHERE company_id=c AND source_message_id=msg AND environment=r.environment;
 SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND company_id=c AND source_message_id=msg AND environment=r.environment;
 SELECT * INTO f FROM gridex_received_sources.prodat_ignored_field_facets WHERE canonical_assessment_id=r.canonical_assessment_id AND company_id=c AND source_message_id=msg AND environment=r.environment;
 IF s.source_message_id IS NULL OR a.id IS NULL OR f.canonical_assessment_id IS NULL OR s.payload_hash IS DISTINCT FROM r.payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR a.source_payload_hash IS DISTINCT FROM s.payload_hash OR a.canonical_assessment_id IS DISTINCT FROM r.canonical_assessment_id OR f.source_payload_hash IS DISTINCT FROM s.payload_hash OR f.fields_hash IS DISTINCT FROM encode(sha256(convert_to(f.fields_text,'UTF8')),'hex') THEN CONTINUE receipt_loop;END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(r.objects) LOOP
  SELECT value INTO assessed FROM jsonb_array_elements(a.facts_text::jsonb->'objects') value WHERE value->'object'=own->'object';
  business:=assessed->'business';first_register:=own#>'{sourceRegisters,0}';
  IF assessed->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1' OR business->'wire' IS DISTINCT FROM own->'wire' OR business->>'companyId' IS DISTINCT FROM c::text OR business->>'environment' IS DISTINCT FROM r.environment OR business->>'meteringPointId' IS DISTINCT FROM own->>'meteringPointId' OR business->>'siteId' IS DISTINCT FROM own->>'siteId' OR nullif(business->>'customerId','') IS NULL OR own#>>'{wire,messageCode}' IS DISTINCT FROM 'Z06' OR (own#>>'{wire,businessCase}' IN('change_with_reading','change_without_reading')) IS NOT TRUE THEN CONTINUE;END IF;
  characteristic:=NULL;method:=NULL;method_count:=0;
  FOR token IN SELECT value FROM jsonb_array_elements(first_register->'tokens') LOOP
   IF token->>'tag'='CCI' THEN characteristic:=token#>>'{elements,2,0}';
   ELSIF token->>'tag'='CAV' AND characteristic='Z04' THEN method_count:=method_count+1;method:=token#>>'{elements,1,0}';END IF;
  END LOOP;
  IF method_count<>1 OR EXISTS(SELECT FROM jsonb_array_elements(f.fields_text::jsonb) ignored WHERE ignored->>'fieldNumber'='217' AND ignored#>>'{occurrence,objectId}'=own#>>'{object,objectId}' AND ignored#>>'{occurrence,identityAgency}'=own#>>'{object,identityAgency}' AND ignored#>>'{occurrence,messageReference}'=own#>>'{object,messageReference}' AND ignored#>>'{occurrence,lineIndex}'=first_register#>>'{register,lineIndex}') THEN method:=NULL;END IF;
  out:=out||jsonb_build_array(jsonb_build_object('companyId',c,'environment',r.environment,'sourceMessageId',msg,'sourcePayloadHash',r.payload_hash,'customerId',business->>'customerId','siteId',own->>'siteId','meteringPointId',own->>'meteringPointId','objectId',own#>>'{object,objectId}','identityAgency',own#>>'{object,identityAgency}','businessCase',own#>>'{wire,businessCase}','effectiveAt',own->'effectiveAt','legalNetwork',own#>>'{wire,legalSender}','legalSupplier',own#>>'{wire,legalReceiver}','measurementMethod',nullif(method,''),'sourceReceivedAt',r.source_received_at,'appliedAt',r.applied_at));
 END LOOP;
 END LOOP receipt_loop;
 RETURN CASE WHEN jsonb_array_length(out)=0 THEN NULL ELSE out END;
END$$;

--
-- Name: apply_owned_li_repair_v1(uuid, uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_owned_li_repair_v1(c uuid, op_id uuid, source_id uuid, ack_id uuid, raw text, allowed jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE p gridex_received_sources.prodat_recovery_li_preparations%rowtype;source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;scopes jsonb;current_objects jsonb;objects jsonb;scope jsonb;obj jsonb;a jsonb;out jsonb:='[]';negative_lines jsonb:='[]';
BEGIN
 SELECT * INTO p FROM gridex_received_sources.prodat_recovery_li_preparations WHERE operation_id=op_id FOR SHARE;IF NOT FOUND THEN
  SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c;
  IF jsonb_array_length(gridex_received_sources.missing_li_repair_scopes_v1(c,source.environment,ack_id,source_id))>0 THEN RAISE EXCEPTION 'prodat_recovery_owned_li_preparation_required';END IF;
  RETURN allowed;END IF;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=source.environment;
 scopes:=gridex_received_sources.missing_li_repair_scopes_v1(c,source.environment,ack_id,source_id);
 current_objects:=gridex_ack_authority.prodat_correction_objects_v1(c,source.environment,ack_id,source_id);
 IF p.company_id IS DISTINCT FROM c OR p.environment IS DISTINCT FROM source.environment OR p.original_message_id IS DISTINCT FROM source_id OR p.ack_message_id IS DISTINCT FROM ack_id
  OR p.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR p.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')
  OR p.missing_scopes IS DISTINCT FROM scopes OR current_objects IS DISTINCT FROM allowed OR p.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_li_preparation_changed';END IF;
 objects:=gridex_ack_authority.prodat_physical_recovery_wire_v1(source.raw_payload)->'objects';
 FOR scope IN SELECT x FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_receipt_v1(c,source.environment,ack_id,source_id)->'physicalOutcomes')x WHERE x->>'outcome'='negative' LOOP
  SELECT x INTO STRICT a FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload))x WHERE x->'lineIndex'=scope#>'{physicalReference,firstLineIndex}';negative_lines:=negative_lines||(a->'registerLineIndices');
 END LOOP;
 FOR obj IN SELECT x FROM jsonb_array_elements(objects)x WHERE negative_lines @> jsonb_build_array(x->'physicalLineIndex') LOOP
  SELECT x INTO a FROM jsonb_array_elements(p.allocations)x WHERE x->'sourceFirstLineIndex'=obj->'physicalLineIndex';
  IF a IS NOT NULL THEN IF obj->>'li' IS NOT NULL THEN RAISE EXCEPTION 'prodat_recovery_existing_li_replacement_forbidden';END IF;obj:=obj||jsonb_build_object('li',a->>'reference');END IF;
  out:=out||jsonb_build_array(obj-'physicalLineIndex');
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO out FROM jsonb_array_elements(out)x;RETURN out;
END$$;

--
-- Name: apply_permission_before_legal_context_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_permission_before_legal_context_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_expected_permission_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; origin public.ediel_messages%rowtype; p public.metering_permissions%rowtype;
 wire jsonb; original jsonb; a jsonb; b jsonb; prior gridex_received_sources.permission_transitions%rowtype;
 ids uuid[]; mode text; reason text; next_status text; negative_status text; count_positive int:=0; count_negative int:=0;
 start_day date; end_day date; end_time timestamptz; before_state jsonb; before_sites jsonb; after_state jsonb; ended_source public.ediel_messages%rowtype; ended_wire jsonb; termination public.ediel_messages%rowtype; termination_wire jsonb; qualified_original uuid; qualified_code text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','permission_source_unavailable'); END IF;
 IF NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_execution_actor_unqualified'); END IF;
 SELECT * INTO prior FROM gridex_received_sources.permission_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id<>p_company_id OR prior.payload_hash<>encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR (p_expected_permission_id IS NOT NULL AND prior.permission_id<>p_expected_permission_id) THEN RAISE EXCEPTION 'permission_replay_conflict'; END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'permissionId',prior.permission_id,'status',prior.resulting_state->>'status');
 END IF;
 -- The real canonical runtime must have accepted this exact immutable payload.
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment
 AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND (v.facts_text::jsonb)->>'syntaxDecision'='accepted'
 AND (v.facts_text::jsonb)->>'applicationDecision'='accepted' AND (v.facts_text::jsonb)->>'functionalDecision'='accepted'
 AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_permission_source_not_accepted'); END IF;
 wire:=gridex_received_sources.permission_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z14','Z15')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_wire_unavailable'); END IF;
 -- Correlation is exact: permission owner, outbound original Z13, environment,
 -- opposite legal actors, and original LI. No unrelated unique-row fallback.
 SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_permissions mp
 JOIN public.ediel_messages z ON z.id=coalesce(mp.source_z13_message_id,mp.outbound_z13_message_id) AND z.company_id=mp.company_id AND z.environment=m.environment
 WHERE mp.company_id=m.company_id AND (p_expected_permission_id IS NULL OR mp.id=p_expected_permission_id)
 AND z.direction='outbound' AND z.status='sent' AND z.message_sent_at IS NOT NULL
 AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'li','') IS NOT NULL AND o->>'li'=mp.rff_li_reference);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','no_unique_source_bound_permission'); END IF;
 SELECT * INTO p FROM public.metering_permissions WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=coalesce(p.source_z13_message_id,p.outbound_z13_message_id) AND company_id=m.company_id FOR SHARE;
 IF NOT FOUND OR origin.environment IS DISTINCT FROM m.environment OR origin.direction IS DISTINCT FROM 'outbound' OR origin.status IS DISTINCT FROM 'sent' OR origin.message_sent_at IS NULL
  OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_not_sealed_and_sent'); END IF;
 original:=gridex_received_sources.permission_wire_v1(origin.raw_payload);
 IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z13' OR wire->>'sender' IS DISTINCT FROM original->>'receiver' OR wire->>'receiver' IS DISTINCT FROM original->>'sender'
 OR p.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' THEN RETURN jsonb_build_object('applied',false,'reason','permission_legal_actor_mismatch'); END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(original->'objects') o WHERE o->>'li'=p.rff_li_reference)<>1 OR origin.customer_id IS DISTINCT FROM p.customer_id THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_customer_scope_unavailable'); END IF;
 SELECT o INTO b FROM jsonb_array_elements(original->'objects') o WHERE o->>'li'=p.rff_li_reference;
 IF b IS NULL OR nullif(b->>'customerIdentity','') IS NULL OR (b->>'reason' IN ('S17','S18')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_mode_unavailable'); END IF;
 mode:=b->>'reason';before_state:=to_jsonb(p);
 PERFORM ps.id FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id ORDER BY ps.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(ps) ORDER BY ps.id),'[]'::jsonb) INTO before_sites FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id;
 IF wire->>'code'='Z14' THEN
  IF p.source_z13_message_id IS NOT NULL AND p.outbound_z13_message_id IS NOT NULL AND p.source_z13_message_id<>p.outbound_z13_message_id THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_identity_conflict'); END IF;
  IF (p.status IN ('z13_sent','waiting_for_customer_approval','z13_ready')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_business_outcome_already_established'); END IF;
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   IF a->>'li' IS DISTINCT FROM p.rff_li_reference THEN RETURN jsonb_build_object('applied',false,'reason','permission_object_reference_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z96' AND a->>'status' IN ('A13','A76') THEN
    count_negative:=count_negative+1;
    IF negative_status IS NOT NULL AND negative_status<>a->>'status' THEN RETURN jsonb_build_object('applied',false,'reason','mixed_permission_denial_reasons'); END IF;
    negative_status:=a->>'status';
   ELSIF reason=mode AND a->>'status'='A74' THEN
    count_positive:=count_positive+1;start_day:=gridex_received_sources.permission_date_v1(a->>'reportStart');end_day:=gridex_received_sources.permission_date_v1(a->>'reportEnd');
    IF nullif(a->>'point','') IS NULL OR nullif(a->>'permissionId','') IS NULL OR nullif(a->>'customerIdentity','') IS NULL OR a->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity'
    OR (b->>'point' IS NOT NULL AND a->>'point' IS DISTINCT FROM b->>'point')
    OR start_day IS NULL OR gridex_received_sources.permission_time_v1(a->>'reportStart') IS NULL OR (a->>'reportEnd' IS NOT NULL AND gridex_received_sources.permission_time_v1(a->>'reportEnd') IS NULL) OR (a->>'reportEnd' IS NOT NULL AND end_day IS NULL) OR (end_day IS NOT NULL AND end_day<start_day) THEN RETURN jsonb_build_object('applied',false,'reason','permission_approved_object_evidence_invalid'); END IF;
   ELSE RETURN jsonb_build_object('applied',false,'reason','permission_business_reason_unqualified'); END IF;
  END LOOP;
  next_status:=CASE WHEN count_positive=0 THEN CASE negative_status WHEN 'A76' THEN 'rejected_passive_timeout' ELSE 'rejected_active' END WHEN count_negative>0 THEN 'partially_approved' ELSE 'active' END;
  -- Parent/site/history writes are one database transaction. Never copy one
  -- linked local site or point to every physical approved object.
  DELETE FROM public.metering_permission_sites WHERE company_id=m.company_id AND metering_permission_id=p.id;
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LOOP
   INSERT INTO public.metering_permission_sites(company_id,metering_permission_id,customer_id,facility_id,grid_area_code,status,start_date,end_date,start_at,end_at,metadata)
   VALUES(m.company_id,p.id,p.customer_id,a->>'point',a->>'gridArea','approved',gridex_received_sources.permission_date_v1(a->>'reportStart'),gridex_received_sources.permission_date_v1(a->>'reportEnd'),gridex_received_sources.permission_time_v1(a->>'reportStart'),gridex_received_sources.permission_time_v1(a->>'reportEnd'),jsonb_build_object('source','inbound_prodat_z14','edielMessageId',m.id,'permissionId',a->>'permissionId','mode',mode,'product',a->>'product'));
  END LOOP;
  SELECT o INTO a FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LIMIT 1;
  UPDATE public.metering_permissions SET status=next_status,source_z14_message_id=m.id,inbound_z14_message_id=m.id,
   permission_id=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_id END,
   permission_reference=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_reference END,
   approved_start_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportStart') ELSE NULL END,
   approved_end_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportEnd') ELSE NULL END,
   approved_start_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportStart') ELSE NULL END,
   approved_end_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportEnd') ELSE NULL END,
   product_code=CASE WHEN count_positive=1 THEN a->>'product' ELSE NULL END,
   report_frequency=CASE WHEN count_positive=1 THEN a->>'frequency' ELSE NULL END,
   last_blocker=CASE WHEN count_positive=0 THEN 'source_z14_denied_'||negative_status ELSE NULL END,
   metadata=coalesce(metadata,'{}')||jsonb_build_object('marketPermission',jsonb_build_object('mode',mode,'sourceZ14',m.id,'legalActor',wire->>'receiver','dsoActor',wire->>'sender','objects',wire->'objects')),
   market_state_version=market_state_version+1,updated_at=now(),updated_by=p_actor_user_id WHERE id=p.id AND company_id=m.company_id;
 ELSE
  -- Validate every physical object before mutating any of them.
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
   IF end_time IS NULL OR a->>'li' IS DISTINCT FROM p.rff_li_reference OR NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.facility_id=a->>'point' AND ps.metadata->>'permissionId'=a->>'permissionId') THEN RETURN jsonb_build_object('applied',false,'reason','z15_permission_object_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z24' THEN
    IF a->>'status' IS DISTINCT FROM 'A74' THEN RETURN jsonb_build_object('applied',false,'reason','z15c_status_unqualified'); END IF;
   ELSIF reason=mode AND a->>'status' IN ('A74','A75') AND a->>'endReason' IN ('B77','B78','B79','B80','E37') THEN NULL;
   ELSE RETURN jsonb_build_object('applied',false,'reason','z15_mode_or_reason_unqualified'); END IF;
  END LOOP;
  IF EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason) THEN RETURN jsonb_build_object('applied',false,'reason','mixed_z15_modes'); END IF;
  IF reason='Z24' THEN
   SELECT * INTO ended_source FROM public.ediel_messages WHERE id=p.inbound_z15_message_id AND company_id=m.company_id AND environment=m.environment;
   ended_wire:=gridex_received_sources.permission_wire_v1(ended_source.raw_payload);
   IF ended_wire IS NULL OR ended_wire->>'sender' IS DISTINCT FROM wire->>'sender' OR ended_wire->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR jsonb_array_length(ended_wire->'objects')<>jsonb_array_length(wire->'objects')
    OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(ended_wire->'objects') old WHERE old->>'reason'=mode AND old->>'permissionId'=own->>'permissionId' AND old->>'point'=own->>'point' AND old->>'permissionEnd'=own->>'permissionEnd' AND old->>'li'=own->>'li'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z15c_original_ending_not_bound'); END IF;
   SELECT * INTO prior FROM gridex_received_sources.permission_transitions WHERE source_message_id=ended_source.id AND permission_id=p.id;
   IF NOT FOUND OR p.market_state_version<>(prior.resulting_state->>'market_state_version')::bigint THEN RETURN jsonb_build_object('applied',false,'reason','z15c_original_snapshot_unavailable'); END IF;
   next_status:=prior.previous_state->>'status';
   UPDATE public.metering_permissions SET status=next_status,approved_end_date=(prior.previous_state->>'approved_end_date')::date,approved_end_at=(prior.previous_state->>'approved_end_at')::timestamptz WHERE id=p.id AND company_id=m.company_id;
   -- Restore exactly the previous object period; no customer-contract or
   -- beneficiary/service grant is revived by a market cancellation.
   UPDATE public.metering_permission_sites ps SET status=old->>'status',end_date=(old->>'end_date')::date,end_at=(old->>'end_at')::timestamptz,permission_end_at=(old->>'permission_end_at')::timestamptz,updated_at=now()
   FROM jsonb_array_elements(prior.previous_sites) old
   WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.id=(old->>'id')::uuid
    AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE own->>'point'=ps.facility_id);
  ELSE
   FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
    end_day:=gridex_received_sources.permission_date_v1(a->>'permissionEnd');end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
    UPDATE public.metering_permission_sites SET end_date=CASE WHEN end_at IS NULL OR end_time<end_at THEN end_day ELSE end_date END,end_at=least(end_at,end_time),permission_end_at=end_time,status=CASE WHEN end_time>now() THEN status ELSE 'ended' END,updated_at=now()
    WHERE company_id=m.company_id AND metering_permission_id=p.id AND facility_id=a->>'point';
   END LOOP;
   next_status:=CASE WHEN NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND (ps.permission_end_at IS NULL OR ps.permission_end_at>now())) THEN 'ended' ELSE p.status END;
   UPDATE public.metering_permissions SET status=next_status,
    approved_end_date=CASE WHEN jsonb_array_length(before_sites)=1 AND (approved_end_at IS NULL OR end_time<approved_end_at) THEN end_day ELSE approved_end_date END,
    approved_end_at=CASE WHEN jsonb_array_length(before_sites)=1 THEN least(approved_end_at,end_time) ELSE approved_end_at END WHERE id=p.id AND company_id=m.company_id;
  END IF;
  UPDATE public.metering_permissions SET inbound_z15_message_id=m.id,market_state_version=market_state_version+1,updated_at=now(),updated_by=p_actor_user_id,
   metadata=coalesce(metadata,'{}')||jsonb_build_object('z15',jsonb_build_object('edielMessageId',m.id,'reason',reason,'objects',wire->'objects')) WHERE id=p.id AND company_id=m.company_id;
 END IF;
 IF wire->>'code'='Z14' THEN
  qualified_original:=origin.id;qualified_code:='Z14';
  UPDATE public.ediel_business_expectations SET status=CASE WHEN count_positive=0 THEN 'rejected' ELSE 'fulfilled' END,
   fulfilled_by_message_id=m.id,updated_at=now()
   WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=origin.id
    AND expected_family='PRODAT' AND expected_code='Z14' AND status IN ('pending','timeout','manual_review');
 ELSIF reason=mode AND p.outbound_z18_message_id IS NOT NULL THEN
  SELECT * INTO termination FROM public.ediel_messages WHERE id=p.outbound_z18_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  termination_wire:=gridex_received_sources.permission_wire_v1(termination.raw_payload);
  IF termination.direction='outbound' AND termination.status='sent' AND termination.message_sent_at IS NOT NULL AND termination.immutable_rendered_at IS NOT NULL
   AND termination.immutable_payload_hash=encode(sha256(convert_to(termination.raw_payload,'UTF8')),'hex')
   AND termination_wire->>'code'='Z18' AND termination_wire->>'sender'=wire->>'receiver' AND termination_wire->>'receiver'=wire->>'sender'
   AND jsonb_array_length(termination_wire->'objects')=jsonb_array_length(wire->'objects')
   AND NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(termination_wire->'objects') requested WHERE requested->>'reason'=mode AND requested->>'li'=own->>'li' AND requested->>'point'=own->>'point' AND requested->>'permissionId'=own->>'permissionId' AND requested->>'permissionEnd'=own->>'permissionEnd'))
   THEN qualified_original:=termination.id;qualified_code:='Z15';
    UPDATE public.ediel_business_expectations SET status='fulfilled',fulfilled_by_message_id=m.id,updated_at=now()
    WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=termination.id AND expected_family='PRODAT' AND expected_code='Z15' AND status IN ('pending','timeout','manual_review'); END IF;
 END IF;
 SELECT to_jsonb(mp) INTO after_state FROM public.metering_permissions mp WHERE id=p.id;
 INSERT INTO gridex_received_sources.permission_transitions(source_message_id,company_id,permission_id,payload_hash,previous_state,previous_sites,resulting_state,actor_user_id,resulting_sites,qualified_original_message_id,qualified_expected_message_code)
 VALUES(m.id,m.company_id,p.id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),before_state,before_sites,after_state,p_actor_user_id,(SELECT coalesce(jsonb_agg(to_jsonb(ps) ORDER BY ps.id),'[]'::jsonb) FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id),qualified_original,qualified_code);
 RETURN jsonb_build_object('applied',true,'permissionId',p.id,'status',next_status,'stateVersion',after_state->'market_state_version');
END $$;

--
-- Name: apply_permission_before_own_partition_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_permission_before_own_partition_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_expected_permission_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF FOUND AND m.direction='inbound' AND m.message_family='PRODAT'
 AND NOT EXISTS(SELECT FROM gridex_received_sources.permission_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=m.company_id AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND (p_expected_permission_id IS NULL OR tr.permission_id=p_expected_permission_id))
 THEN PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);END IF;
 RETURN gridex_received_sources.apply_permission_before_legal_context_v1(p_company_id,p_source_message_id,p_actor_user_id,p_expected_permission_id);
END $$;

--
-- Name: apply_permission_group_v1(uuid, uuid, uuid, uuid, jsonb, uuid, jsonb, boolean); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_permission_group_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_expected_permission_id uuid, p_wire jsonb, p_canonical_id uuid, p_scopes jsonb, p_validate_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; origin public.ediel_messages%rowtype; p public.metering_permissions%rowtype;
 wire jsonb; original jsonb; a jsonb; b jsonb; prior gridex_received_sources.permission_effect_transitions_v1%rowtype;
 ids uuid[]; mode text; reason text; next_status text; negative_status text; count_positive int:=0; count_negative int:=0;incomplete boolean:=false;
 start_day date; end_day date; end_time timestamptz; before_state jsonb; before_sites jsonb; after_state jsonb; ended_source public.ediel_messages%rowtype; ended_wire jsonb; termination public.ediel_messages%rowtype; termination_wire jsonb; qualified_original uuid; qualified_code text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','permission_source_unavailable'); END IF;
 IF NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_execution_actor_unqualified'); END IF;
 SELECT * INTO prior FROM gridex_received_sources.permission_effect_transitions_v1 WHERE source_message_id=m.id AND permission_id=p_expected_permission_id;
 IF FOUND THEN
  IF prior.company_id<>p_company_id OR prior.payload_hash<>encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR (p_expected_permission_id IS NOT NULL AND prior.permission_id<>p_expected_permission_id) THEN RAISE EXCEPTION 'permission_replay_conflict'; END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'permissionId',prior.permission_id,'status',prior.resulting_state->>'status');
 END IF;
 -- Private input is minted from the SAME full raw/application partition.
 IF p_canonical_id IS NULL OR jsonb_typeof(p_scopes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_scopes)=0 OR p_wire->>'code' IS DISTINCT FROM m.message_code OR p_wire-'objects' IS DISTINCT FROM gridex_received_sources.permission_partition_wire_v1(m.raw_payload)-'objects'
  OR EXISTS(SELECT FROM jsonb_array_elements(p_scopes)x WHERE gridex_received_sources.prodat_application_object_accepted_v1(m.company_id,m.id,p_canonical_id,x) IS NOT TRUE)
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.id=p_canonical_id AND v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','permission_own_application_and_function_required');END IF;
 wire:=p_wire;
 IF wire IS NULL OR(wire->>'code' IN('Z14','Z15')) IS NOT TRUE OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'projectionHeld'='true' OR NOT EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.permission_partition_wire_v1(m.raw_payload)->'objects')x WHERE x=o)) THEN RETURN jsonb_build_object('applied',false,'reason','permission_wire_unavailable');END IF;
 -- Correlation is exact: permission owner, outbound original Z13, environment,
 -- opposite legal actors, and original LI. No unrelated unique-row fallback.
 SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_permissions mp
 JOIN public.ediel_messages z ON z.id=coalesce(mp.source_z13_message_id,mp.outbound_z13_message_id) AND z.company_id=mp.company_id AND z.environment=m.environment
 WHERE mp.company_id=m.company_id AND (p_expected_permission_id IS NULL OR mp.id=p_expected_permission_id)
 AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z) IS TRUE
 AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'li','') IS NOT NULL AND o->>'li'=mp.rff_li_reference);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','no_unique_source_bound_permission'); END IF;
 SELECT * INTO p FROM public.metering_permissions WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=coalesce(p.source_z13_message_id,p.outbound_z13_message_id) AND company_id=m.company_id FOR SHARE;
 IF NOT FOUND OR origin.environment IS DISTINCT FROM m.environment OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
  OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_not_sealed_and_sent'); END IF;
 original:=gridex_received_sources.permission_partition_wire_v1(origin.raw_payload);
 IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z13' OR wire->>'sender' IS DISTINCT FROM original->>'receiver' OR wire->>'receiver' IS DISTINCT FROM original->>'sender'
 OR p.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' THEN RETURN jsonb_build_object('applied',false,'reason','permission_legal_actor_mismatch'); END IF;
 IF origin.customer_id IS DISTINCT FROM p.customer_id OR (SELECT count(DISTINCT jsonb_build_array(o->'customerIdentity',o->'reason')) FROM jsonb_array_elements(original->'objects')o WHERE o->>'li'=p.rff_li_reference)<>1 OR EXISTS(SELECT FROM jsonb_array_elements(original->'objects')o WHERE o->>'li'=p.rff_li_reference AND(o->>'projectionHeld'='true' OR nullif(o->>'customerIdentity','') IS NULL OR(o->>'reason' IN('S17','S18')) IS NOT TRUE)) THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_customer_scope_unavailable');END IF;
 SELECT o INTO b FROM jsonb_array_elements(original->'objects')o WHERE o->>'li'=p.rff_li_reference;
 IF b IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_mode_unavailable');END IF;
 -- Every own positive physical installation is either exactly requested or
 -- part of the genuine customer-bound unspecified installation request.
 IF EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'status'='A74' AND(SELECT count(*) FROM jsonb_array_elements(original->'objects')x WHERE x->>'li'=p.rff_li_reference AND(x->>'point' IS NULL OR(x->>'point'=o->>'point' AND x->>'identityAgency' IS NOT DISTINCT FROM o->>'identityAgency')) )<>1) THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_physical_scope_unavailable');END IF;
 mode:=b->>'reason';before_state:=to_jsonb(p);qualified_original:=origin.id;qualified_code:=wire->>'code';
 PERFORM ps.id FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id ORDER BY ps.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(ps) ORDER BY ps.id),'[]'::jsonb) INTO before_sites FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id;
 IF wire->>'code'='Z14' THEN
  IF p.source_z13_message_id IS NOT NULL AND p.outbound_z13_message_id IS NOT NULL AND p.source_z13_message_id<>p.outbound_z13_message_id THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_identity_conflict'); END IF;
  IF (p.status IN ('z13_sent','waiting_for_customer_approval','z13_ready')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_business_outcome_already_established'); END IF;
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   IF a->>'customerIdentity' IS NOT NULL AND a->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity' THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_customer_scope_unavailable');END IF;
   IF a->>'li' IS DISTINCT FROM p.rff_li_reference THEN RETURN jsonb_build_object('applied',false,'reason','permission_object_reference_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z96' AND a->>'status' IN ('A13','A76') THEN
    count_negative:=count_negative+1;
    IF negative_status IS NOT NULL AND negative_status<>a->>'status' THEN RETURN jsonb_build_object('applied',false,'reason','mixed_permission_denial_reasons'); END IF;
    negative_status:=a->>'status';
   ELSIF reason=mode AND a->>'status'='A74' THEN
    -- Fresh positive Z14 must correspond to its independently sealed/sent
    -- own-LI original purpose. NULL is a distinct possible original value.
    IF (SELECT count(DISTINCT jsonb_build_array(o->'purpose')) FROM jsonb_array_elements(original->'objects')o WHERE o->>'li'=p.rff_li_reference)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_reporting_purpose_unqualified');END IF;
    IF a->>'purpose' IS DISTINCT FROM (SELECT DISTINCT o->>'purpose' FROM jsonb_array_elements(original->'objects')o WHERE o->>'li'=p.rff_li_reference) THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_reporting_purpose_mismatch');END IF;
    count_positive:=count_positive+1;start_day:=gridex_received_sources.permission_date_v1(a->>'reportStart');end_day:=gridex_received_sources.permission_date_v1(a->>'reportEnd');
    IF nullif(a->>'point','') IS NULL OR nullif(a->>'permissionId','') IS NULL OR nullif(a->>'customerIdentity','') IS NULL OR a->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity'
    
    OR start_day IS NULL OR gridex_received_sources.permission_time_v1(a->>'reportStart') IS NULL OR (a->>'reportEnd' IS NOT NULL AND gridex_received_sources.permission_time_v1(a->>'reportEnd') IS NULL) OR (a->>'reportEnd' IS NOT NULL AND end_day IS NULL) OR (end_day IS NOT NULL AND end_day<start_day) THEN RETURN jsonb_build_object('applied',false,'reason','permission_approved_object_evidence_invalid'); END IF;
   ELSE RETURN jsonb_build_object('applied',false,'reason','permission_business_reason_unqualified'); END IF;
  END LOOP;
  IF p_validate_only THEN RETURN jsonb_build_object('qualified',true);END IF;
  -- Z14N denies the referenced request. Its prescribed omitted installation
  -- cannot be treated as an unresponded positive-only point.
  incomplete:=count_positive>0 AND(EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.permission_partition_wire_v1(m.raw_payload)->'objects')x WHERE x->>'li'=p.rff_li_reference AND NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')y WHERE y=x)) OR EXISTS(SELECT FROM jsonb_array_elements(original->'objects')x WHERE x->>'li'=p.rff_li_reference AND x->>'point' IS NOT NULL AND NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')y WHERE y->>'point'=x->>'point' AND y->>'identityAgency' IS NOT DISTINCT FROM x->>'identityAgency')));
  next_status:=CASE WHEN count_positive=0 AND incomplete THEN p.status WHEN count_positive=0 THEN CASE negative_status WHEN 'A76' THEN 'rejected_passive_timeout' ELSE 'rejected_active' END WHEN count_negative>0 OR incomplete THEN 'partially_approved' ELSE 'active' END;
  -- Parent/site/history writes are one database transaction. Never copy one
  -- linked local site or point to every physical approved object.
  DELETE FROM public.metering_permission_sites WHERE company_id=m.company_id AND metering_permission_id=p.id AND facility_id IN(SELECT o->>'point' FROM jsonb_array_elements(wire->'objects')o WHERE o->>'status'='A74');
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LOOP
   INSERT INTO public.metering_permission_sites(company_id,metering_permission_id,customer_id,facility_id,grid_area_code,status,start_date,end_date,start_at,end_at,metadata)
   VALUES(m.company_id,p.id,p.customer_id,a->>'point',a->>'gridArea','approved',gridex_received_sources.permission_date_v1(a->>'reportStart'),gridex_received_sources.permission_date_v1(a->>'reportEnd'),gridex_received_sources.permission_time_v1(a->>'reportStart'),gridex_received_sources.permission_time_v1(a->>'reportEnd'),jsonb_build_object('source','inbound_prodat_z14','edielMessageId',m.id,'permissionId',a->>'permissionId','mode',mode,'product',a->>'product'));
  END LOOP;
  SELECT o INTO a FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LIMIT 1;
  UPDATE public.metering_permissions SET status=next_status,source_z14_message_id=m.id,inbound_z14_message_id=m.id,
   permission_id=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_id END,
   permission_reference=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_reference END,
   approved_start_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportStart') ELSE NULL END,
   approved_end_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportEnd') ELSE NULL END,
   approved_start_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportStart') ELSE NULL END,
   approved_end_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportEnd') ELSE NULL END,
   product_code=CASE WHEN count_positive=1 THEN a->>'product' ELSE NULL END,
   report_frequency=CASE WHEN count_positive=1 THEN a->>'frequency' ELSE NULL END,
   last_blocker=CASE WHEN count_positive=0 THEN 'source_z14_denied_'||negative_status ELSE NULL END,
   metadata=coalesce(metadata,'{}')||jsonb_build_object('marketPermission',jsonb_build_object('mode',mode,'sourceZ14',m.id,'legalActor',wire->>'receiver','dsoActor',wire->>'sender','objects',wire->'objects')),
   market_state_version=market_state_version+1,updated_at=now(),updated_by=p_actor_user_id WHERE id=p.id AND company_id=m.company_id;
 ELSE
  IF public.ediel_permission_source_is_current_v1(m.company_id,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_current_approved_source_required');END IF;
  -- Validate every physical object before mutating any of them.
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
   IF end_time IS NULL OR a->>'li' IS DISTINCT FROM p.rff_li_reference OR NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.facility_id=a->>'point' AND ps.metadata->>'permissionId'=a->>'permissionId') THEN RETURN jsonb_build_object('applied',false,'reason','z15_permission_object_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z24' THEN
    IF a->>'status' IS DISTINCT FROM 'A74' THEN RETURN jsonb_build_object('applied',false,'reason','z15c_status_unqualified'); END IF;
   ELSIF reason=mode AND a->>'status' IN ('A74','A75') AND a->>'endReason' IN ('B77','B78','B79','B80','E37') THEN NULL;
   ELSE RETURN jsonb_build_object('applied',false,'reason','z15_mode_or_reason_unqualified'); END IF;
  END LOOP;
  IF EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason) THEN RETURN jsonb_build_object('applied',false,'reason','mixed_z15_modes'); END IF;
  IF reason='Z24' THEN
   FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects')o LOOP
    SELECT tr.* INTO prior FROM gridex_received_sources.permission_effect_transitions_v1 tr WHERE tr.company_id=m.company_id AND tr.permission_id=p.id AND tr.qualified_expected_message_code='Z15'
     AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_state#>'{metadata,z15,objects}')x WHERE x->>'point'=a->>'point') ORDER BY(tr.resulting_state->>'market_state_version')::bigint DESC LIMIT 1;
    SELECT * INTO ended_source FROM public.ediel_messages WHERE id=prior.source_message_id AND company_id=m.company_id AND environment=m.environment;
    IF prior.source_message_id IS NULL OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(ended_source.raw_payload,'UTF8')),'hex') OR coalesce(prior.resulting_state->>'source_z13_message_id',prior.resulting_state->>'outbound_z13_message_id') IS DISTINCT FROM origin.id::text
     OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_state#>'{metadata,z15,objects}')x WHERE x->>'point'=a->>'point' AND x->>'permissionId'=a->>'permissionId' AND x->>'permissionEnd'=a->>'permissionEnd' AND x->>'li'=a->>'li' AND x->>'reason'=mode) THEN RETURN jsonb_build_object('applied',false,'reason','z15c_original_ending_not_bound');END IF;
    IF NOT EXISTS(SELECT FROM public.metering_permission_sites ps JOIN LATERAL jsonb_array_elements(prior.resulting_sites)s ON s->>'id'=ps.id::text WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.facility_id=a->>'point'
     AND(to_jsonb(ps)-ARRAY['status','updated_at'])=(s-ARRAY['status','updated_at']) AND(ps.status=s->>'status' OR(ps.status='ended' AND s->>'status' IN('approved','active') AND ps.permission_end_at<=now()))) THEN RETURN jsonb_build_object('applied',false,'reason','z15c_current_own_site_snapshot_unavailable');END IF;
   END LOOP;
   IF p_validate_only THEN RETURN jsonb_build_object('qualified',true);END IF;
   -- Validate the complete selected set before its first write.
   FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects')o LOOP
    SELECT tr.* INTO prior FROM gridex_received_sources.permission_effect_transitions_v1 tr WHERE tr.company_id=m.company_id AND tr.permission_id=p.id AND tr.qualified_expected_message_code='Z15' AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_state#>'{metadata,z15,objects}')x WHERE x->>'point'=a->>'point') ORDER BY(tr.resulting_state->>'market_state_version')::bigint DESC LIMIT 1;
    UPDATE public.metering_permission_sites ps SET status=old->>'status',end_date=(old->>'end_date')::date,end_at=(old->>'end_at')::timestamptz,permission_end_at=(old->>'permission_end_at')::timestamptz,updated_at=now()
     FROM jsonb_array_elements(prior.previous_sites)old WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.facility_id=a->>'point' AND ps.id=(old->>'id')::uuid;
   END LOOP;
   SELECT tr.resulting_state->>'status' INTO next_status FROM gridex_received_sources.permission_effect_transitions_v1 tr WHERE tr.company_id=m.company_id AND tr.permission_id=p.id AND tr.qualified_expected_message_code='Z14' ORDER BY(tr.resulting_state->>'market_state_version')::bigint DESC LIMIT 1;
   IF(next_status IN('active','approved','partially_approved','z14_received')) IS NOT TRUE THEN RAISE EXCEPTION 'z15c_original_permission_basis_unavailable';END IF;
   IF NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.status IN('approved','active')) THEN next_status:='ended';END IF;
   UPDATE public.metering_permissions SET status=next_status,approved_end_date=CASE WHEN jsonb_array_length(before_sites)=1 THEN(SELECT ps.end_date FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id) ELSE approved_end_date END,
    approved_end_at=CASE WHEN jsonb_array_length(before_sites)=1 THEN(SELECT ps.end_at FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id) ELSE approved_end_at END WHERE id=p.id AND company_id=m.company_id;

  ELSE
   IF p_validate_only THEN RETURN jsonb_build_object('qualified',true);END IF;
   FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
    end_day:=gridex_received_sources.permission_date_v1(a->>'permissionEnd');end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
    UPDATE public.metering_permission_sites SET end_date=CASE WHEN end_at IS NULL OR end_time<end_at THEN end_day ELSE end_date END,end_at=least(end_at,end_time),permission_end_at=end_time,status=CASE WHEN end_time>now() THEN status ELSE 'ended' END,updated_at=now()
    WHERE company_id=m.company_id AND metering_permission_id=p.id AND facility_id=a->>'point';
   END LOOP;
   next_status:=CASE WHEN NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND (ps.permission_end_at IS NULL OR ps.permission_end_at>now())) THEN 'ended' ELSE p.status END;
   UPDATE public.metering_permissions SET status=next_status,
    approved_end_date=CASE WHEN jsonb_array_length(before_sites)=1 AND (approved_end_at IS NULL OR end_time<approved_end_at) THEN end_day ELSE approved_end_date END,
    approved_end_at=CASE WHEN jsonb_array_length(before_sites)=1 THEN least(approved_end_at,end_time) ELSE approved_end_at END WHERE id=p.id AND company_id=m.company_id;
  END IF;
  UPDATE public.metering_permissions SET inbound_z15_message_id=m.id,market_state_version=market_state_version+1,updated_at=now(),updated_by=p_actor_user_id,
   metadata=coalesce(metadata,'{}')||jsonb_build_object('z15',jsonb_build_object('edielMessageId',m.id,'reason',reason,'objects',wire->'objects')) WHERE id=p.id AND company_id=m.company_id;
 END IF;
 IF wire->>'code'='Z14' THEN
  qualified_original:=origin.id;qualified_code:='Z14';
  UPDATE public.ediel_business_expectations SET status=CASE WHEN incomplete THEN 'manual_review' WHEN count_positive=0 THEN 'rejected' ELSE 'fulfilled' END,
   fulfilled_by_message_id=m.id,updated_at=now()
   WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=origin.id
    AND expected_family='PRODAT' AND expected_code='Z14' AND status IN ('pending','timeout','manual_review');
 ELSIF reason=mode AND p.outbound_z18_message_id IS NOT NULL THEN
  SELECT * INTO termination FROM public.ediel_messages WHERE id=p.outbound_z18_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  termination_wire:=gridex_received_sources.permission_wire_v1(termination.raw_payload);
  IF termination.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(termination) IS TRUE AND termination.immutable_rendered_at IS NOT NULL
   AND termination.immutable_payload_hash=encode(sha256(convert_to(termination.raw_payload,'UTF8')),'hex')
   AND termination_wire->>'code'='Z18' AND termination_wire->>'sender'=wire->>'receiver' AND termination_wire->>'receiver'=wire->>'sender'
   AND jsonb_array_length(termination_wire->'objects')=jsonb_array_length(wire->'objects')
   AND NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(termination_wire->'objects') requested WHERE requested->>'reason'=mode AND requested->>'li'=own->>'li' AND requested->>'point'=own->>'point' AND requested->>'permissionId'=own->>'permissionId' AND requested->>'permissionEnd'=own->>'permissionEnd'))
   THEN qualified_original:=termination.id;
    UPDATE public.ediel_business_expectations SET status='fulfilled',fulfilled_by_message_id=m.id,updated_at=now()
    WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=termination.id AND expected_family='PRODAT' AND expected_code='Z15' AND status IN ('pending','timeout','manual_review'); END IF;
 END IF;
 SELECT to_jsonb(mp) INTO after_state FROM public.metering_permissions mp WHERE id=p.id;
 INSERT INTO gridex_received_sources.permission_effect_receipts(source_message_id,company_id,permission_id,payload_hash,previous_state,previous_sites,resulting_state,actor_user_id,resulting_sites,qualified_original_message_id,qualified_expected_message_code,canonical_assessment_id,object_scopes)
 VALUES(m.id,m.company_id,p.id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),before_state,before_sites,after_state,p_actor_user_id,(SELECT coalesce(jsonb_agg(to_jsonb(ps) ORDER BY ps.id),'[]'::jsonb) FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id),qualified_original,qualified_code,p_canonical_id,p_scopes);
 RETURN jsonb_build_object('applied',true,'permissionId',p.id,'status',next_status,'stateVersion',after_state->'market_state_version');
END $$;

--
-- Name: apply_supply_before_legal_context_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_supply_before_legal_context_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason OR nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);
 END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.supply_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'sender' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'receiver'
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text)
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND object->>'reason' IN ('Z26','Z70')))
    );
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (planned->>'periodId')::uuid FROM jsonb_array_elements(plans) planned);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),wire->>'code',wire->'objects',before_states,after_states,ARRAY(SELECT (planned->>'switchId')::uuid FROM jsonb_array_elements(plans) planned WHERE planned->>'kind'='cancel_start'),p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'periods',after_states,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;

--
-- Name: apply_supply_before_normal_switch_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_supply_before_normal_switch_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF FOUND AND m.direction='inbound' AND m.message_family='PRODAT'
 AND NOT EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=m.company_id AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'))
 THEN PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);END IF;
 RETURN gridex_received_sources.apply_supply_before_legal_context_v1(p_company_id,p_source_message_id,p_actor_user_id);
END $$;

--
-- Name: apply_supply_before_own_partition_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_supply_before_own_partition_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;w jsonb;ids uuid[];
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 w:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF m.direction='inbound' AND m.message_family='PRODAT' AND w->>'code'='Z04' THEN
  -- A normal replay returns its immutable receipt before original locks.
  -- Original-before-switch order protects the preserved cancellation path.
  IF EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason' IN('Z22','Z23')) THEN RETURN gridex_received_sources.normal_switch_confirm_v1(p_company_id,p_source_message_id,p_actor_user_id);END IF;
  SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO ids FROM public.supplier_switch_requests s WHERE s.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'li'=s.rff_li_reference);
  PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ids) ORDER BY z.id FOR SHARE;
 END IF;
 RETURN gridex_received_sources.apply_supply_before_normal_switch_v1(p_company_id,p_source_message_id,p_actor_user_id);
END $$;

--
-- Name: assess_recovery_source_v1(uuid, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.assess_recovery_source_v1(p_company_id uuid, p_original_message_id uuid, p_actor_user_id uuid, p_operation_id uuid, p_source_ack_message_id uuid DEFAULT NULL::uuid, p_previous_attempt_id uuid DEFAULT NULL::uuid, p_corrected_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;attempt gridex_ediel_transport.attempts%rowtype;operation gridex_received_sources.prodat_recovery_operations%rowtype;
 original jsonb;corrected jsonb;response jsonb;allowed_objects jsonb;recovery_kind text;oid uuid;correlation record;
BEGIN
 IF p_operation_id IS NULL OR p_actor_user_id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_scope_required';END IF;

 PERFORM gridex_received_sources.prelock_recovery_candidate_v1(p_company_id,p_original_message_id,p_source_ack_message_id);
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_original_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_sealed_original_required';END IF;
 original:=gridex_received_sources.prodat_recovery_wire_v1(m.raw_payload);
 IF original IS NULL OR original->>'family' IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'prodat_recovery_original_scope_unavailable';END IF;
 IF p_previous_attempt_id IS NOT NULL THEN
  IF p_source_ack_message_id IS NOT NULL OR p_corrected_raw_payload IS NOT NULL THEN RAISE EXCEPTION 'prodat_recovery_kind_conflict';END IF;
  SELECT * INTO attempt FROM gridex_ediel_transport.attempts WHERE id=p_previous_attempt_id AND message_id=m.id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  IF NOT FOUND OR (attempt.classification IN ('pre_connect_negative','explicit_negative','all_rejected')) IS NOT TRUE OR attempt.observed_at IS NULL OR attempt.binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash
   OR EXISTS(SELECT FROM gridex_ediel_transport.attempts a WHERE a.message_id=m.id AND (a.classification IN ('accepted','partial','unknown') OR a.entered_at IS NOT NULL AND a.observed_at IS NULL))
   OR (m.contrl_status='received') IS TRUE OR (m.aperak_status='received') IS TRUE OR EXISTS(SELECT FROM public.ediel_messages a WHERE a.company_id=m.company_id AND a.environment=m.environment AND a.direction='inbound' AND a.original_message_id=m.id::text AND a.ack_outcome='positive') THEN RETURN jsonb_build_object('status','held','reason','verified_transfer_loss_required');END IF;
  recovery_kind:='verified_transfer_loss';
 ELSE
  IF p_source_ack_message_id IS NULL OR p_corrected_raw_payload IS NULL OR octet_length(p_corrected_raw_payload)>262144 THEN RAISE EXCEPTION 'prodat_correction_source_required';END IF;
  SELECT * INTO ack FROM public.ediel_messages WHERE id=p_source_ack_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  IF NOT FOUND OR ack.direction IS DISTINCT FROM 'inbound' OR (ack.message_family IN ('CONTRL','APERAK')) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_correction_ack_source_unavailable';END IF;
  IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=ack.id AND v.company_id=ack.company_id AND v.environment=ack.environment AND v.source_payload_hash=encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('status','held','reason','canonical_negative_ack_source_required');END IF;
  -- Sole ACK authority derives and commits its own whole raw correlation. A
  -- caller's outcome/reference, mutable row pointers or local ERC table grant nothing.
  SELECT * INTO correlation FROM gridex_ack_authority.source_correlations a WHERE a.ack_message_id=ack.id AND a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment FOR SHARE;
  IF NOT FOUND OR correlation.ack_family IS DISTINCT FROM ack.message_family OR correlation.ack_outcome IS DISTINCT FROM 'negative' OR correlation.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') OR correlation.source_payload_hash IS DISTINCT FROM m.immutable_payload_hash THEN RETURN jsonb_build_object('status','held','reason','qualified_negative_ack_source_required');END IF;
  response:=gridex_received_sources.prodat_recovery_wire_v1(ack.raw_payload);corrected:=gridex_received_sources.prodat_recovery_wire_v1(p_corrected_raw_payload);
  IF corrected IS NULL OR corrected->>'family' IS DISTINCT FROM 'PRODAT' OR corrected->>'code' IS DISTINCT FROM original->>'code' OR corrected->>'legalSender' IS DISTINCT FROM original->>'legalSender' OR corrected->>'legalReceiver' IS DISTINCT FROM original->>'legalReceiver' OR p_corrected_raw_payload=m.raw_payload THEN RETURN jsonb_build_object('status','held','reason','corrected_whole_original_scope_required');END IF;
  IF response IS NULL THEN RETURN jsonb_build_object('status','held','reason','negative_ack_wire_unavailable');END IF;
  allowed_objects:=original->'objects';
  IF ack.message_family='CONTRL' THEN
   IF correlation.ack_scope IS DISTINCT FROM 'interchange' THEN RETURN jsonb_build_object('status','held','reason','whole_original_negative_contrl_required');END IF;
   recovery_kind:='contrl_correction';
  ELSE
   -- Explicit physical object outcomes belong to the ACK owner. A positive
   -- sibling never enters this correction, and absent scope is not inferred.
   IF response->>'function'='27' THEN
    IF correlation.ack_scope IS DISTINCT FROM 'message' THEN RETURN jsonb_build_object('status','held','reason','source_supported_negative_aperak_scope_required');END IF;
   ELSIF response->>'function'='34' THEN
    allowed_objects:=gridex_ack_authority.prodat_correction_objects_v1(m.company_id,m.environment,ack.id,m.id);
    IF allowed_objects IS NULL THEN
    IF correlation.ack_scope IS DISTINCT FROM 'object' OR jsonb_typeof(correlation.scope_outcomes) IS DISTINCT FROM 'array' OR jsonb_array_length(correlation.scope_outcomes)=0
     OR EXISTS(SELECT FROM jsonb_array_elements(correlation.scope_outcomes) result WHERE (result->>'outcome' IN ('positive','negative')) IS NOT TRUE OR nullif(result->>'reference','') IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') own WHERE own->>'li'=result->>'reference')) THEN RETURN jsonb_build_object('status','held','reason','source_supported_negative_aperak_scope_required');END IF;
    SELECT coalesce(jsonb_agg(own ORDER BY own::text),'[]') INTO allowed_objects FROM jsonb_array_elements(original->'objects') own WHERE EXISTS(SELECT FROM jsonb_array_elements(correlation.scope_outcomes) result WHERE result->>'reference'=own->>'li' AND result->>'outcome'='negative');
    ELSE
     IF correlation.ack_scope IS DISTINCT FROM 'object' OR jsonb_typeof(allowed_objects) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('status','held','reason','source_supported_negative_aperak_scope_required');END IF;
     SELECT coalesce(jsonb_agg(own ORDER BY own::text),'[]'::jsonb) INTO allowed_objects FROM jsonb_array_elements(allowed_objects) own;
    END IF;
    IF jsonb_array_length(allowed_objects)=0 THEN RETURN jsonb_build_object('status','held','reason','negative_aperak_own_object_required');END IF;
   ELSE RETURN jsonb_build_object('status','held','reason','source_supported_negative_aperak_scope_required');END IF;
   IF nullif(corrected->>'bgmId','') IS NULL OR corrected->>'bgmId' IS NOT DISTINCT FROM original->>'bgmId' THEN RETURN jsonb_build_object('status','held','reason','negative_aperak_new_bgm_required');END IF;
   recovery_kind:='aperak_correction';
  END IF;
  allowed_objects:=gridex_received_sources.apply_owned_li_repair_v1(p_company_id,p_operation_id,m.id,ack.id,p_corrected_raw_payload,allowed_objects);
  IF corrected->'objects' IS DISTINCT FROM allowed_objects THEN RETURN jsonb_build_object('status','held','reason','corrected_exact_failed_scope_required');END IF;
 END IF;
 RETURN jsonb_build_object('status','qualified','kind',recovery_kind,'companyId',m.company_id,'environment',m.environment,'originalMessageId',m.id,'originalPayloadHash',m.immutable_payload_hash,'sourceAckHash',CASE WHEN ack.id IS NOT NULL THEN encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex') END,'correctedPayloadHash',CASE WHEN p_corrected_raw_payload IS NOT NULL THEN encode(sha256(convert_to(p_corrected_raw_payload,'UTF8')),'hex') END);
END $$;

--
-- Name: begin_document_reference_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.begin_document_reference_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_document_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE facts jsonb; a gridex_received_sources.document_reference_attempts%rowtype; predecessor uuid;
BEGIN
 PERFORM gridex_received_sources.document_reference_actor_v1(p_company_id,p_actor_user_id);
 facts:=gridex_received_sources.document_reference_facts_v1(p_company_id,p_environment,p_source_message_id,p_document_id);
 -- Preserve source registration as independently discoverable context. Foreign
 -- document failures above cannot write a concern about the foreign document.
 PERFORM gridex_received_sources.capture_correction_concern_v1(p_company_id,p_environment,p_source_message_id,p_actor_user_id);
 IF NOT EXISTS(SELECT FROM gridex_received_sources.correction_concerns c JOIN gridex_received_sources.correction_witnesses w ON w.capture_id=c.id AND w.facts_hash=c.facts_hash
 WHERE c.source_message_id=p_source_message_id AND c.company_id=p_company_id AND c.environment=p_environment AND c.created_xid<>pg_current_xact_id())
 THEN RAISE EXCEPTION 'document_source_capture_unwitnessed' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_source_message_id::text||p_document_id::text,0));
 SELECT id INTO predecessor FROM gridex_received_sources.document_reference_attempts WHERE source_message_id=p_source_message_id AND document_id=p_document_id ORDER BY recorded_at DESC,id DESC LIMIT 1;
 INSERT INTO gridex_received_sources.document_reference_attempts(company_id,environment,source_message_id,document_id,actor_user_id,predecessor_id,facts,facts_hash)
 VALUES(p_company_id,p_environment,p_source_message_id,p_document_id,p_actor_user_id,predecessor,facts,encode(sha256(convert_to(facts::text,'UTF8')),'hex')) RETURNING * INTO a;
 RETURN jsonb_build_object('kind',a.kind,'attemptId',a.id,'companyId',a.company_id,'environment',a.environment,'sourceMessageId',a.source_message_id,
 'documentId',a.document_id,'actorUserId',a.actor_user_id,'recordedAt',a.recorded_at,'factsHash',a.facts_hash,'eligible',facts->'eligible','document',facts->'document');
END $$;

--
-- Name: billing_supply_basis_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.billing_supply_basis_v1(p_company_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p_period_id AND company_id=p_company_id) THEN RETURN gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);END IF;
 b:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_start,p_end);
 IF b->>'activated' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 RETURN b;
END $$;

--
-- Name: billing_supply_before_normal_switch_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p public.customer_supply_periods%rowtype;tr gridex_received_sources.supply_source_transitions%rowtype;initial gridex_received_sources.supply_source_transitions%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;expected jsonb;first_state jsonb;basis jsonb;ids uuid[];discovered_version bigint;discovered_origin uuid;
BEGIN
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end<=p_start THEN RETURN NULL;END IF;
 -- Discovery does not authorize a read. Source transitions acquire source rows
 -- before the period; consumers must preserve that order, including the legal
 -- capture helper's source UPDATE lock. Requalify the period after those locks.
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND OR p.market_start_at IS NULL OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at) THEN RETURN NULL;END IF;
 SELECT array_agg(source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=p.market_state_version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 discovered_version:=p.market_state_version;discovered_origin:=p.source_message_id;
 PERFORM s.id FROM public.ediel_messages s WHERE s.company_id=p_company_id AND s.id=ANY(ARRAY[ids[1],discovered_origin]) ORDER BY s.id FOR UPDATE;
 BEGIN basis:=gridex_ediel_inbound_context.require_v1(p_company_id,discovered_origin);EXCEPTION WHEN OTHERS THEN RETURN NULL;END;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR p.market_state_version IS DISTINCT FROM discovered_version OR p.source_message_id IS DISTINCT FROM discovered_origin
 OR p.market_start_at IS NULL OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at) THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 IF expected IS NULL OR expected->>'status'='cancelled' OR (expected->>'company_id')::uuid IS DISTINCT FROM p.company_id OR (expected->>'customer_id')::uuid IS DISTINCT FROM p.customer_id OR (expected->>'metering_point_id')::uuid IS DISTINCT FROM p.metering_point_id
 OR (expected->>'market_state_version')::bigint IS DISTINCT FROM p.market_state_version OR (expected->>'market_start_at')::timestamptz IS DISTINCT FROM p.market_start_at OR (expected->>'market_end_at')::timestamptz IS DISTINCT FROM p.market_end_at
 OR (expected->>'source_message_id')::uuid IS DISTINCT FROM p.source_message_id OR (expected->>'source_end_message_id')::uuid IS DISTINCT FROM p.source_end_message_id OR expected#>>'{metadata,sourceGroundId}' IS DISTINCT FROM p.metadata->>'sourceGroundId' THEN RETURN NULL;END IF;
 SELECT * INTO initial FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=p.source_message_id AND company_id=p_company_id AND source_code='Z04';
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=initial.source_message_id AND company_id=p_company_id AND environment=m.environment;
 IF origin.id IS NULL OR initial.payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT own INTO first_state FROM jsonb_array_elements(initial.resulting_states) own WHERE own->>'id'=p.id::text;
 IF first_state IS NULL OR first_state#>>'{metadata,sourceGroundId}' IS DISTINCT FROM p.metadata->>'sourceGroundId' OR (first_state->>'customer_id')::uuid IS DISTINCT FROM p.customer_id OR (first_state->>'metering_point_id')::uuid IS DISTINCT FROM p.metering_point_id OR (first_state->>'market_start_at')::timestamptz IS DISTINCT FROM p.market_start_at THEN RETURN NULL;END IF;
 SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id::text=first_state#>>'{metadata,sourceGroundId}' AND company_id=p_company_id AND environment=m.environment FOR SHARE;
 IF NOT FOUND OR ground.revoked_at IS NOT NULL OR ground.valid_from>p_start OR (ground.valid_to IS NOT NULL AND p_end>ground.valid_to) OR nullif(ground.source_reference,'') IS NULL OR ground.source_sha256 !~ '^[a-f0-9]{64}$' OR nullif(ground.legal_decision_reference,'') IS NULL OR nullif(ground.registry_version,'') IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND (v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 IF basis->>'legalActorId' IS DISTINCT FROM ground.legal_actor_id::text OR basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'sourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,'groundId',ground.id,'groundSourceSha256',ground.source_sha256,'groundRegistryVersion',ground.registry_version);
END $_$;

--
-- Name: bind_prodat_recovery_message_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.bind_prodat_recovery_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;
BEGIN
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id::text=NEW.source_operation_id AND kind IN ('contrl_correction','aperak_correction');
 IF NOT FOUND THEN RETURN NEW;END IF;
 IF NEW.company_id IS DISTINCT FROM op.company_id OR NEW.environment IS DISTINCT FROM op.environment OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.original_message_id IS DISTINCT FROM op.original_message_id::text OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') OR op.corrected_raw_payload IS DISTINCT FROM NEW.raw_payload THEN RAISE EXCEPTION 'prodat_recovery_bound_message_conflict';END IF;
 INSERT INTO gridex_received_sources.prodat_recovery_messages(operation_id,message_id) VALUES(op.id,NEW.id);
 RETURN NEW;
END $$;

--
-- Name: bind_production_contract_origin_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.bind_production_contract_origin_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;e gridex_received_sources.production_contract_events%rowtype;b jsonb;w jsonb;obj jsonb;tokens jsonb;dates jsonb;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE intent_id=NEW.intent_id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id FOR SHARE;
 b:=public.ediel_production_contract_source_v1(o.company_id,e.id,o.actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'production_contract_source_changed';END IF;
 SELECT * INTO STRICT o FROM gridex_received_sources.production_contract_origins WHERE intent_id=NEW.intent_id FOR UPDATE;
 w:=gridex_received_sources.prodat_recovery_wire_v1(NEW.raw_payload);tokens:=gridex_received_sources.closure_wire_tokens_v2(NEW.raw_payload);
 IF NEW.company_id IS DISTINCT FROM e.company_id OR NEW.environment IS DISTINCT FROM e.environment OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM 'Z09' OR NEW.source_operation_id IS DISTINCT FROM e.id::text
 OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR NEW.customer_id IS DISTINCT FROM e.customer_id OR NEW.metering_point_id IS DISTINCT FROM e.metering_point_id OR w->>'family' IS DISTINCT FROM 'PRODAT' OR w->>'code' IS DISTINCT FROM 'Z09' OR w->>'legalSender' IS DISTINCT FROM e.legal_sender_id OR w->>'legalReceiver' IS DISTINCT FROM e.legal_receiver_id OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1
 THEN RAISE EXCEPTION 'production_contract_message_scope_mismatch';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN ('FR','DO') AND (t#>>'{elements,2,1}' IS DISTINCT FROM '160' OR t#>>'{elements,2,2}' IS DISTINCT FROM 'SVK')) THEN RAISE EXCEPTION 'production_contract_legal_party_qualifier_mismatch';END IF;
 obj:=w->'objects'->0;
 IF obj->>'point' IS DISTINCT FROM e.point_id OR obj->>'identityAgency' IS DISTINCT FROM e.identity_agency OR obj->>'reason' IS DISTINCT FROM 'Z70'
 THEN RAISE EXCEPTION 'production_contract_physical_object_mismatch';END IF;
 SELECT jsonb_agg(t->'elements'->1) INTO dates FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}' IN ('92','93','157');
 IF jsonb_array_length(dates) IS DISTINCT FROM 1 OR dates#>>'{0,0}' IS DISTINCT FROM (CASE e.event_kind WHEN 'signed' THEN '92' ELSE '93' END)
 OR dates#>>'{0,1}' IS DISTINCT FROM to_char(e.boundary_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI') OR dates#>>'{0,2}' IS DISTINCT FROM '203'
 THEN RAISE EXCEPTION 'production_contract_boundary_mismatch';END IF;
 IF o.message_id IS NOT NULL AND (o.message_id IS DISTINCT FROM NEW.id OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'production_contract_message_already_bound' USING ERRCODE='23505';END IF;
 UPDATE gridex_received_sources.production_contract_origins SET message_id=NEW.id,payload_hash=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') WHERE event_id=e.id;
 RETURN NEW;
END $$;

--
-- Name: bind_switch_brp_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.bind_switch_brp_source_v1(c uuid, message uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE b jsonb;m public.ediel_messages%rowtype;BEGIN
 b:=gridex_received_sources.switch_brp_source_basis_v1(c,message,actor,'prepare');SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=message AND company_id=c;
 INSERT INTO gridex_received_sources.switch_brp_source_bindings(message_id,company_id,brp_ediel_id,source_basis,payload_hash) VALUES(message,c,b->>'brpEdielId',b,m.immutable_payload_hash);
END$$;

--
-- Name: bind_switch_contract_request_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.bind_switch_contract_request_v1(c uuid, message uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE basis jsonb;m public.ediel_messages%rowtype;BEGIN
 basis:=gridex_received_sources.switch_contract_request_basis_v1(c,message,actor,'prepare');
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=message AND company_id=c;
 INSERT INTO gridex_received_sources.switch_contract_request_bindings(message_id,company_id,declaration_id,requested_method,source_basis,payload_hash)
 VALUES(message,c,(basis->>'declarationId')::uuid,basis->>'requestedMethod',basis,m.immutable_payload_hash);
END$$;

--
-- Name: capture_correction_concern_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.capture_correction_concern_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype; captured gridex_received_sources.correction_concerns%rowtype; observation jsonb; body jsonb;
BEGIN
 IF p_company_id IS NULL OR p_source_message_id IS NULL OR p_actor_user_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production')
 OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.companies WHERE id=p_company_id AND coalesce(is_active,true)
  AND coalesce(status,'active') NOT IN ('archived','suspended','pending_deletion','deleted','deleted_test_only','inactive','paused','closed'))
 THEN RAISE EXCEPTION 'correction_capture_actor_unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id
  AND company_id=p_company_id AND environment=p_environment;
 IF NOT FOUND OR src.origin<>'database_insert' OR src.message_code IS DISTINCT FROM 'Z05' OR src.source_received_at IS NULL
 OR src.raw_payload IS NULL OR octet_length(src.raw_payload)>2097152 OR src.payload_hash IS NULL
 OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(src.raw_payload,'UTF8')),'hex')
 OR NOT coalesce(src.received_context @> jsonb_build_object('version',1,'contextOrigin','database_insert',
  'sourceMessageId',src.source_message_id,'companyId',src.company_id,'environment',src.environment,'messageCode','Z05','payloadHash',src.payload_hash),false)
 OR (src.received_context->>'sourceReceivedAt')::timestamptz IS DISTINCT FROM src.source_received_at
 OR (src.received_context->>'capturedAt') IS NULL
 OR NOT isfinite((src.received_context->>'capturedAt')::timestamptz)
 OR (src.received_context->>'capturedAt')::timestamptz>src.captured_at
 THEN RAISE EXCEPTION 'correction_sealed_original_unavailable' USING ERRCODE='23514'; END IF;
 -- This is observational registration, not canonical review. Unsupported or
 -- malformed sealed Z05s remain visible as wildcard concerns, never exclusions.
 observation:=gridex_received_sources.correction_wire_observation_v1(src.raw_payload);
 body:=jsonb_build_object('version',1,'owner','sealed-z05-concern-v1','sourceMessageId',src.source_message_id,
  'sourcePayloadHash',src.payload_hash,'sourceReceivedAt',src.source_received_at,'sourceCapturedAt',src.captured_at,
  'scope',jsonb_build_object('companyId',src.company_id,'environment',src.environment,'customerId',NULL,'supplyPeriodId',NULL,
   'objectId',observation->'objectId','identityAgency',observation->'identityAgency',
   'legalSender',observation->'legalSender','legalReceiver',observation->'legalReceiver'),
  'oldStop',observation->'oldStop','proposedStop',observation->'proposedStop',
  'observedSourceStop',observation->'observedSourceStop','caseReference',observation->'caseReference',
  'candidateTarget',NULL,'disposition','unreviewed','provenance',jsonb_build_object('channel','sealed_inbound_original','authentication','unknown'),
  'retention',jsonb_build_object('sourceCategory','edifact_raw_payloads','coverage','not_established','documentBytes','unavailable'));
 INSERT INTO gridex_received_sources.correction_concerns(source_message_id,company_id,environment,source_payload_hash,actor_user_id,
  source_received_at,source_captured_at,facts,facts_hash)
 VALUES(src.source_message_id,src.company_id,src.environment,src.payload_hash,p_actor_user_id,src.source_received_at,src.captured_at,
  body,encode(sha256(convert_to(body::text,'UTF8')),'hex')) ON CONFLICT(source_message_id,rule_version) DO NOTHING;
 SELECT * INTO STRICT captured FROM gridex_received_sources.correction_concerns WHERE source_message_id=src.source_message_id AND rule_version='sealed-z05-concern-v1';
 IF captured.facts IS DISTINCT FROM body THEN RAISE EXCEPTION 'correction_original_facts_changed' USING ERRCODE='23514'; END IF;
 RETURN gridex_received_sources.correction_receipt_v1(captured);
END $$;

--
-- Name: capture_customer_primary_response_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.capture_customer_primary_response_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;tr gridex_customer_life_events.transitions%rowtype;own jsonb;business jsonb;first_line integer;prior gridex_received_sources.customer_primary_response_receipts%rowtype;
BEGIN
 FOR own IN SELECT e FROM jsonb_array_elements(NEW.facts_text::jsonb->'objects')e WHERE e->>'disposition'='accepted' AND e#>>'{business,owner}'='inbound-customer-life-event-v1' LOOP
  SELECT * INTO m FROM public.ediel_messages WHERE id=NEW.source_message_id AND company_id=NEW.company_id FOR SHARE;
  SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=m.id AND company_id=NEW.company_id;
  business:=own->'business';first_line:=(own#>>'{object,registers,0,segmentIndex}')::integer;
  IF m.id IS NULL OR m.environment IS DISTINCT FROM NEW.environment OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06'
   OR NEW.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR NEW.facts_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.facts_text,'UTF8')),'hex')
   OR tr.source_message_id IS NULL OR tr.payload_hash IS DISTINCT FROM NEW.source_payload_hash OR tr.canonical_assessment_id IS DISTINCT FROM NEW.canonical_assessment_id
   OR EXISTS(SELECT FROM gridex_customer_life_events.transitions committed_transition
      WHERE committed_transition.source_message_id=m.id AND committed_transition.company_id=NEW.company_id
       AND committed_transition.xmin::text::numeric=mod(pg_current_xact_id()::text::numeric,4294967296))
   OR (EXISTS(SELECT FROM gridex_received_sources.prodat_source_function_facets f
      WHERE f.assessment_id=NEW.canonical_assessment_id)
    AND gridex_received_sources.prodat_source_function_object_accepted_v1(
      NEW.company_id,m.id,NEW.canonical_assessment_id,own->'object') IS NOT TRUE)
   OR gridex_received_sources.prodat_first_register_characteristic_v1(m.raw_payload,own->'object','Z13') IS DISTINCT FROM 'E34'
   OR gridex_received_sources.prodat_application_object_accepted_v1(NEW.company_id,m.id,NEW.canonical_assessment_id,own->'object') IS NOT TRUE
   OR gridex_customer_life_events.owner_proof_consistent_v1(own->'party',business,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_customer_primary_response_own_effect_unavailable';END IF;
  SELECT * INTO prior FROM gridex_received_sources.customer_primary_response_receipts WHERE source_message_id=m.id AND first_line_index=first_line;
  IF FOUND THEN
   IF prior.company_id IS DISTINCT FROM NEW.company_id OR prior.environment IS DISTINCT FROM NEW.environment OR prior.payload_hash IS DISTINCT FROM NEW.source_payload_hash OR prior.canonical_assessment_id IS DISTINCT FROM NEW.canonical_assessment_id
    OR prior.customer_id::text IS DISTINCT FROM business->>'customerId' OR prior.customer_version::text IS DISTINCT FROM business->>'customerVersion' OR prior.effective_at IS DISTINCT FROM(business->>'effectiveAt')::timestamptz
    OR prior.object_scope IS DISTINCT FROM own->'object' OR prior.owner_fact IS DISTINCT FROM own THEN RAISE EXCEPTION 'prodat_customer_primary_response_original_conflict';END IF;
  ELSE
   INSERT INTO gridex_received_sources.customer_primary_response_receipts VALUES(m.id,first_line,NEW.company_id,NEW.environment,NEW.source_payload_hash,NEW.canonical_assessment_id,NEW.id,
    (business->>'customerId')::uuid,(business->>'customerVersion')::bigint,(business->>'effectiveAt')::timestamptz,tr.recorded_at,own->'object',own);
  END IF;
 END LOOP;
 RETURN NEW;
END $$;

--
-- Name: capture_insert(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.capture_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' OR TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'ediel_messages' THEN
    RAISE EXCEPTION 'received_source_capture_invalid_owner' USING ERRCODE = '23514';
  END IF;
  IF gridex_unattributed_intake.is_birth_v1(NEW,true) IS TRUE THEN RETURN NEW; END IF;
  IF NEW.direction = 'inbound' AND upper(coalesce(NEW.message_family, '')) = 'PRODAT'
     AND NEW.message_standard = 'edifact' THEN
    -- AFTER INSERT observes the final row after PR369's BEFORE trigger sealed
    -- the source. Only database-owned original columns are copied; no status,
    -- mutable metering link, parsed_payload or validation_report is authority.
    INSERT INTO gridex_received_sources.sources (
      source_message_id, company_id, environment, origin, message_code,
      source_received_at, captured_at, raw_payload, payload_hash, received_context
    ) VALUES (
      NEW.id, NEW.company_id, NEW.environment, 'database_insert', NEW.message_code,
      NEW.message_received_at, clock_timestamp(), NEW.raw_payload,
      NEW.immutable_payload_hash,
      NEW.execution_context_snapshot -> 'receivedProdatContext'
    );
    -- No ON CONFLICT DO NOTHING. Reusing a deleted source ID must not silently
    -- attach a different receipt to old history. Normal retries are UPDATEs.
  END IF;
  RETURN NEW;
END
$$;

--
-- Name: capture_utilts_insert_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.capture_utilts_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.direction='inbound' AND NEW.message_family='UTILTS' AND NEW.message_standard='edifact'
  AND NEW.execution_context_snapshot ? 'receivedUtiltsContext' THEN
  INSERT INTO gridex_received_sources.sources(source_message_id,company_id,environment,origin,message_code,source_received_at,captured_at,raw_payload,payload_hash,received_context)
   VALUES(NEW.id,NEW.company_id,NEW.environment,'database_insert',NEW.message_code,NEW.message_received_at,
    (NEW.execution_context_snapshot#>>'{receivedUtiltsContext,capturedAt}')::timestamptz,
    NEW.raw_payload,NEW.immutable_payload_hash,NEW.execution_context_snapshot->'receivedUtiltsContext');
 END IF;
 RETURN NEW;
END $$;

--
-- Name: closure_wire_matches_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.closure_wire_matches_v1(p_raw text, p_object jsonb, p_wire jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(gridex_received_sources.closure_wire_projection_v1(p_raw,p_object)=p_wire,false)
$$;

--
-- Name: closure_wire_projection_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.closure_wire_projection_v1(p_raw text, p_object jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE decoded jsonb:=gridex_received_sources.z05_wire_structure_v1(p_raw,p_object); wire jsonb;
BEGIN
 IF decoded IS NULL OR decoded#>>'{wire,reason}' NOT IN ('Z22','Z23')
 OR decoded->>'caseReferenceCount'<>'1' THEN RETURN NULL; END IF;
 wire:=decoded->'wire';
 RETURN wire||jsonb_build_object('subtype',CASE wire->>'reason' WHEN 'Z22' THEN 'L' ELSE 'LK' END);
END $$;

