--
-- Name: committed_permission_effects_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.committed_permission_effects_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;e gridex_received_sources.permission_effect_receipts%rowtype;v gridex_received_sources.validation_assessments%rowtype;f gridex_received_sources.prodat_application_facets%rowtype;r gridex_received_sources.prodat_response_facets%rowtype;scope jsonb;result jsonb:='[]';tx text:=(mod(pg_current_xact_id_if_assigned()::text::numeric,4294967296))::text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z14','Z15')) IS NOT TRUE THEN RETURN result;END IF;
 IF requested IS NOT NULL AND(cardinality(requested) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(requested)x WHERE x IS NULL OR x<0) OR cardinality(requested)<>(SELECT count(DISTINCT x) FROM unnest(requested)x)) THEN RAISE EXCEPTION 'permission_final_response_scope_required';END IF;
 FOR e IN SELECT x.* FROM gridex_received_sources.permission_effect_receipts x WHERE x.source_message_id=m.id AND x.company_id=c AND(tx IS NULL OR x.xmin::text<>tx) ORDER BY x.permission_id LOOP
  SELECT * INTO v FROM gridex_received_sources.validation_assessments WHERE id=e.canonical_assessment_id;
  SELECT * INTO f FROM gridex_received_sources.prodat_application_facets WHERE assessment_id=v.id AND company_id=c AND source_message_id=m.id;
  SELECT * INTO r FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=v.id;
  IF e.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR v.company_id IS DISTINCT FROM c OR v.source_message_id IS DISTINCT FROM m.id OR v.environment IS DISTINCT FROM m.environment OR v.source_payload_hash IS DISTINCT FROM e.payload_hash OR v.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR v.facts_hash IS DISTINCT FROM encode(sha256(convert_to(v.facts_text,'UTF8')),'hex') OR f.assessment_id IS NULL OR f.environment IS DISTINCT FROM m.environment OR f.source_payload_hash IS DISTINCT FROM e.payload_hash OR f.application_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.application_facts_text,'UTF8')),'hex') OR r.assessment_id IS NULL OR r.company_id IS DISTINCT FROM c OR r.source_message_id IS DISTINCT FROM m.id OR r.environment IS DISTINCT FROM m.environment OR r.source_payload_hash IS DISTINCT FROM e.payload_hash OR r.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.response_facts_text,'UTF8')),'hex') OR gridex_received_sources.validate_prodat_application_v1(m.raw_payload,v.facts_text::jsonb,f.application_facts_text::jsonb,r.response_facts_text::jsonb) IS NOT TRUE OR v.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR v.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'permission_committed_effect_source_conflict';END IF;
  FOR scope IN SELECT value FROM jsonb_array_elements(e.object_scopes) LOOP
   IF requested IS NOT NULL AND NOT(scope#>>'{registers,0,segmentIndex}')::integer=ANY(requested) THEN CONTINUE;END IF;
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(f.application_facts_text::jsonb->'objects')object WHERE object-'applicationDecision'-'reasonCodes'=scope AND object->>'applicationDecision'='accepted') THEN RAISE EXCEPTION 'permission_committed_own_application_conflict';END IF;
   result:=result||jsonb_build_array(jsonb_build_object('receiptId',e.id,'canonicalAssessmentId',v.id,'sourcePayloadHash',e.payload_hash,'objectScope',scope,'appliedAt',e.applied_at,'effectKind','metering_permission','effectFactsHash',encode(sha256(convert_to(jsonb_build_object('previousState',e.previous_state,'previousSites',e.previous_sites,'resultingState',e.resulting_state,'resultingSites',e.resulting_sites,'sourceOriginalId',e.qualified_original_message_id,'objectScopes',e.object_scopes)::text,'UTF8')),'hex')));
  END LOOP;
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(result) THEN RAISE EXCEPTION 'permission_final_response_own_effect_uncommitted';END IF;
 RETURN result;
END$$;

--
-- Name: committed_supply_effects_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.committed_supply_effects_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_received_sources.supply_object_effect_receipts%rowtype;p gridex_received_sources.supply_object_partitions%rowtype;a gridex_received_sources.validation_assessments%rowtype;
 f gridex_received_sources.prodat_application_facets%rowtype;response gridex_received_sources.prodat_response_facets%rowtype;own jsonb;effects jsonb:='[]';wire jsonb;effect jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z04','Z05')) IS NOT TRUE THEN RETURN NULL;END IF;
 IF requested IS NOT NULL AND(cardinality(requested) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(requested)x WHERE x IS NULL OR x<0) OR cardinality(requested)<>(SELECT count(DISTINCT x) FROM unnest(requested)x)) THEN RAISE EXCEPTION 'supply_final_response_scope_required';END IF;
 SELECT * INTO p FROM gridex_received_sources.supply_object_partitions WHERE source_message_id=m.id AND company_id=c;
 IF p.source_message_id IS NULL THEN RETURN gridex_bilateral_prodat.committed_h_start_effects_v1(c,source_id,requested);END IF;
 IF p.environment IS DISTINCT FROM m.environment OR p.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR p.partition_hash IS DISTINCT FROM encode(sha256(convert_to(p.partition_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'supply_final_response_source_changed';END IF;
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=p.canonical_assessment_id AND company_id=c AND source_message_id=m.id;
 SELECT * INTO f FROM gridex_received_sources.prodat_application_facets WHERE assessment_id=a.id AND company_id=c AND source_message_id=m.id;
 SELECT * INTO response FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id;
 IF a.id IS NULL OR a.environment IS DISTINCT FROM m.environment OR a.source_payload_hash IS DISTINCT FROM p.payload_hash OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1'
  OR a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR f.assessment_id IS NULL OR f.environment IS DISTINCT FROM m.environment OR f.source_payload_hash IS DISTINCT FROM p.payload_hash
  OR response.assessment_id IS NULL OR response.company_id IS DISTINCT FROM c OR response.source_message_id IS DISTINCT FROM m.id OR response.environment IS DISTINCT FROM m.environment OR response.source_payload_hash IS DISTINCT FROM p.payload_hash OR response.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(response.response_facts_text,'UTF8')),'hex')
  OR f.application_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.application_facts_text,'UTF8')),'hex')
  OR gridex_received_sources.validate_prodat_application_v1(m.raw_payload,a.facts_text::jsonb,f.application_facts_text::jsonb,response.response_facts_text::jsonb) IS NOT TRUE THEN RAISE EXCEPTION 'supply_final_response_admitted_canonical_required';END IF;
 FOR r IN SELECT stored.* FROM gridex_received_sources.supply_object_effect_receipts stored WHERE stored.company_id=c AND stored.source_message_id=m.id AND(requested IS NULL OR stored.first_line_index=ANY(requested))
  AND stored.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) ORDER BY stored.first_line_index LOOP
  effect:=r.effect_text::jsonb;wire:=gridex_received_sources.supply_wire_for_scope_v1(m.raw_payload,r.object_scope);
  SELECT o INTO own FROM jsonb_array_elements(f.application_facts_text::jsonb->'objects')o WHERE o-'applicationDecision'-'reasonCodes'=r.object_scope;
  IF r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM p.payload_hash OR r.canonical_assessment_id IS DISTINCT FROM a.id OR r.effect_hash IS DISTINCT FROM encode(sha256(convert_to(r.effect_text,'UTF8')),'hex')
   OR own->>'applicationDecision' IS DISTINCT FROM 'accepted' OR r.first_line_index IS DISTINCT FROM(r.object_scope#>>'{registers,0,segmentIndex}')::integer
   OR effect->>'owner' IS DISTINCT FROM 'inbound-supply-object-v1' OR effect->'object' IS DISTINCT FROM r.object_scope OR effect->'wire' IS DISTINCT FROM wire#>'{objects,0}'
   OR effect->>'sourceMessageId' IS DISTINCT FROM m.id::text OR effect->>'sourcePayloadHash' IS DISTINCT FROM p.payload_hash OR effect->>'companyId' IS DISTINCT FROM c::text OR effect->>'environment' IS DISTINCT FROM m.environment
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(p.partition_text::jsonb)part WHERE part->'object'=r.object_scope AND part->>'disposition'='applied' AND part->>'effectReceiptId'=r.id::text AND part->>'effectFactsHash'=r.effect_hash)
   OR NOT EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=c AND tr.payload_hash=p.payload_hash AND tr.resulting_states@>(effect->'resultingStates') AND(effect#>>'{plan,switchId}' IS NULL OR(effect#>>'{plan,switchId}')::uuid=ANY(tr.qualified_switch_ids)))
   OR(effect#>>'{plan,kind}'='cancel_start' AND NOT EXISTS(SELECT FROM jsonb_array_elements(effect->'resultingSwitches')sw WHERE sw->>'id'=effect#>>'{plan,switchId}' AND sw->>'status'='cancelled_before_start' AND sw->>'inbound_z04_message_id'=m.id::text)) THEN RAISE EXCEPTION 'supply_final_response_own_effect_required';END IF;
  effects:=effects||jsonb_build_array(jsonb_build_object('receiptId',r.id,'canonicalAssessmentId',r.canonical_assessment_id,'sourcePayloadHash',r.payload_hash,'objectScope',r.object_scope,'appliedAt',r.applied_at,'effectKind','supply','effectFactsHash',r.effect_hash));
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(effects) THEN RAISE EXCEPTION 'supply_final_response_own_effect_uncommitted';END IF;
 RETURN effects;
END$$;

--
-- Name: confirm_production_contract_on_ack_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.confirm_production_contract_on_ack_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;e gridex_received_sources.production_contract_events%rowtype;
BEGIN
 IF NEW.aperak_status IS DISTINCT FROM 'accepted' OR OLD.aperak_status IS NOT DISTINCT FROM NEW.aperak_status
 OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM 'Z09' THEN RETURN NEW;END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE message_id=NEW.id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id FOR SHARE;
 IF e.company_id IS DISTINCT FROM NEW.company_id OR e.environment IS DISTINCT FROM NEW.environment
 OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=e.id) THEN RETURN NEW;END IF;
 INSERT INTO gridex_received_sources.production_contract_confirmations(event_id,company_id,environment,message_id)
  VALUES(e.id,e.company_id,e.environment,NEW.id) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;

--
-- Name: confirmed_death_response_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.confirmed_death_response_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;v gridex_requested_changes.confirmed_customer_versions%rowtype;
 w gridex_requested_changes.customer_version_availability%rowtype;binding gridex_ediel_ack_guide.source_bindings%rowtype;
 snapshot jsonb;body jsonb;qualified jsonb;function_facet jsonb;scope jsonb;tokens jsonb;lin jsonb;own_tokens jsonb;ud jsonb;dtm jsonb;
 initial jsonb;planned jsonb;objects jsonb;projection jsonb;positive_text text;first_line integer;end_line integer;w_xmin numeric;modern_function jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_source_required';END IF;
 SELECT * INTO v FROM gridex_requested_changes.confirmed_customer_versions WHERE source_message_id=m.id AND company_id=c AND environment=m.environment FOR SHARE;
 IF v.source_message_id IS NULL OR v.event_id IS NULL OR v.bilateral_artifact_id IS NOT NULL OR v.party->>'deathStatus' IS DISTINCT FROM 'Z41'
  OR v.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR v.received_at IS DISTINCT FROM m.message_received_at
  OR v.created_xid=pg_current_xact_id() OR NOT pg_visible_in_snapshot(v.created_xid,pg_current_snapshot())
  OR NOT EXISTS(SELECT FROM gridex_requested_changes.events e WHERE e.id=v.event_id AND e.company_id=c AND e.environment=m.environment AND e.variant='E' AND e.event_kind='death') THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_own_effect_unavailable';END IF;
 SELECT * INTO w FROM gridex_requested_changes.customer_version_availability a WHERE a.source_message_id=v.source_message_id AND a.company_id=c AND a.environment=m.environment AND a.payload_hash=v.payload_hash FOR SHARE;
 SELECT a.xmin::text::numeric INTO w_xmin FROM gridex_requested_changes.customer_version_availability a WHERE a.source_message_id=v.source_message_id AND a.company_id=c AND a.environment=m.environment AND a.payload_hash=v.payload_hash;
 IF w.source_message_id IS NULL OR w_xmin=mod(pg_current_xact_id()::text::numeric,4294967296)
  OR NOT pg_visible_in_snapshot(v.created_xid,w.visibility_snapshot::pg_snapshot) THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_committed_availability_required';END IF;
 -- Reuse the existing actual history owner: latest accepted canonical source,
 -- independent current event/issuer/reviewer, own legal supply/site and custody.
 snapshot:=gridex_received_sources.open_object_selection_snapshot(c,m.environment,clock_timestamp());body:=(snapshot->>'readsetText')::jsonb;
 IF body->>'complete' IS DISTINCT FROM 'true' OR body->>'companyId' IS DISTINCT FROM c::text OR body->>'environment' IS DISTINCT FROM m.environment THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_complete_readset_required';END IF;
 qualified:=gridex_requested_changes.customer_facet_basis_v1(body,(body->>'cutoffAt')::timestamptz,c,m.environment,v.customer_id,v.site_id,m.id::text,v.object_id,v.identity_agency);
 IF qualified IS NULL OR qualified->>'sourceMessageId' IS DISTINCT FROM m.id::text OR qualified->>'payloadHash' IS DISTINCT FROM v.payload_hash
  OR qualified->>'customerId' IS DISTINCT FROM v.customer_id::text OR qualified->>'siteId' IS DISTINCT FROM v.site_id::text
  OR qualified->>'meteringPointId' IS DISTINCT FROM v.metering_point_id::text OR qualified->>'supplyPeriodId' IS DISTINCT FROM v.supply_period_id::text
  OR qualified->>'objectId' IS DISTINCT FROM v.object_id OR qualified->>'identityAgency' IS DISTINCT FROM v.identity_agency
  OR qualified->>'legalSender' IS DISTINCT FROM v.legal_sender OR qualified->>'legalReceiver' IS DISTINCT FROM v.legal_receiver
  OR (qualified->>'effectiveAt')::timestamptz IS DISTINCT FROM v.effective_at OR qualified->'party' IS DISTINCT FROM v.party
  OR (qualified->>'availableAt')::timestamptz IS DISTINCT FROM w.observed_at THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_current_owner_required';END IF;
 IF v.result->>'applied' IS DISTINCT FROM 'true' OR v.result->>'owner' IS DISTINCT FROM 'confirmed-customer-source-v1'
  OR v.result->>'sourceMessageId' IS DISTINCT FROM m.id::text OR v.result->>'payloadHash' IS DISTINCT FROM v.payload_hash
  OR v.result->>'eventId' IS DISTINCT FROM v.event_id::text OR v.result->>'appliedCount' IS DISTINCT FROM '1'
  OR jsonb_typeof(v.result->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(v.result->'objects')<>1
  OR v.result#>>'{objects,0,meteringPointId}' IS DISTINCT FROM v.metering_point_id::text OR v.result#>>'{objects,0,siteId}' IS DISTINCT FROM v.site_id::text
  OR (v.result#>>'{objects,0,effectiveAt}')::timestamptz IS DISTINCT FROM v.effective_at
  OR (v.result#>>'{objects,0,sourceReceivedAt}')::timestamptz IS DISTINCT FROM v.received_at THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_result_required';END IF;
 function_facet:=gridex_received_sources.require_prodat_application_objects_v1(c,m.id);
 IF function_facet->>'assessmentId' IS DISTINCT FROM v.canonical_assessment_id::text
  OR jsonb_typeof(function_facet->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(function_facet->'objects')<>1
  OR function_facet->>'headerDecision' IS DISTINCT FROM 'accepted'
  OR function_facet#>>'{objects,0,applicationDecision}' IS DISTINCT FROM 'accepted'
  OR function_facet#>'{objects,0,reasonCodes}' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_canonical_scope_required';END IF;
 scope:=(function_facet->'objects'->0)-'applicationDecision'-'reasonCodes';
 -- Do not filter a malformed or foreign modern row into the absence branch.
 -- Its own strict reader must qualify it; failure never falls back to APP.
 IF EXISTS(SELECT FROM gridex_received_sources.prodat_source_function_facets WHERE assessment_id=v.canonical_assessment_id) THEN
  modern_function:=gridex_received_sources.require_prodat_source_function_objects_v1(c,m.id);
  IF modern_function->>'assessmentId' IS DISTINCT FROM v.canonical_assessment_id::text
   OR jsonb_typeof(modern_function->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(modern_function->'objects')<>1
   OR modern_function#>>'{objects,0,functionalDecision}' IS DISTINCT FROM 'accepted'
   OR modern_function#>'{objects,0,reasonCodes}' IS DISTINCT FROM '[]'::jsonb
   OR (modern_function->'objects'->0)-'functionalDecision'-'reasonCodes' IS DISTINCT FROM scope THEN
   RAISE EXCEPTION 'prodat_confirmed_death_response_canonical_scope_required';END IF;
 END IF;first_line:=(scope#>>'{registers,0,segmentIndex}')::integer;
 IF scope->>'objectId' IS DISTINCT FROM v.object_id OR scope->>'identityAgency' IS DISTINCT FROM v.identity_agency
  OR scope#>>'{registers,0,registerPosition}' IS DISTINCT FROM '1' OR first_line IS NULL
  OR gridex_received_sources.prodat_first_register_characteristic_v1(m.raw_payload,scope,'Z13') IS DISTINCT FROM 'E34'
  OR gridex_received_sources.prodat_first_register_characteristic_v1(m.raw_payload,scope,'Z17') IS DISTINCT FROM 'Z41' THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_physical_scope_required';END IF;
 IF requested IS NOT NULL AND requested IS DISTINCT FROM ARRAY[first_line] THEN RAISE EXCEPTION 'prodat_confirmed_death_response_scope_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 SELECT t INTO lin FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' ORDER BY(t->>'index')::integer LIMIT 1;
 IF (lin->>'index')::integer IS DISTINCT FROM first_line OR lin#>>'{elements,3,0}' IS DISTINCT FROM v.object_id OR lin#>>'{elements,3,3}' IS DISTINCT FROM v.identity_agency
  OR (SELECT count(DISTINCT jsonb_build_array(t#>>'{elements,3,0}',t#>>'{elements,3,3}')) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN')<>1 THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_whole_object_required';END IF;
 SELECT min((t->>'index')::integer) INTO end_line FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::integer>first_line AND t->>'tag' IN('LIN','UNT','UNZ','UNH');
 SELECT jsonb_agg(t ORDER BY(t->>'index')::integer) INTO own_tokens FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::integer>first_line AND(t->>'index')::integer<end_line;
 IF (SELECT count(*) FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND nullif(t#>>'{elements,1,1}','') IS NOT NULL)<>1
  OR (SELECT count(*) FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157' AND t#>>'{elements,1,2}'='203')<>1 THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_own_party_clock_reference_required';END IF;
 SELECT t INTO ud FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD';
 SELECT t INTO dtm FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157';
 IF ud#>'{elements,2}' IS DISTINCT FROM jsonb_build_array(v.party->>'id',v.party->>'qualifier',v.party->>'agency')
  OR gridex_received_sources.permission_time_v1(dtm#>>'{elements,1,1}') IS DISTINCT FROM v.effective_at THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_own_party_clock_reference_required';END IF;
 initial:=gridex_received_sources.read_prodat_response_assessment_v1(c,m.id,v.canonical_assessment_id);
 SELECT e INTO planned FROM jsonb_array_elements(initial->'objects')e WHERE e->'lineIndex'=to_jsonb(first_line);
 IF planned IS NULL OR jsonb_array_length(initial->'objects')<>1 OR planned->>'outcome'='negative'
  OR planned->>'id' IS DISTINCT FROM v.object_id OR planned->'registerLineIndices' IS DISTINCT FROM(SELECT jsonb_agg(r->'segmentIndex' ORDER BY ord) FROM jsonb_array_elements(scope->'registers') WITH ORDINALITY x(r,ord))
  OR planned->>'li' IS DISTINCT FROM(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(own_tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI') THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_own_plan_required';END IF;
 SELECT * INTO binding FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind='national' FOR SHARE;
 IF binding.source_message_id IS NULL OR binding.company_id IS DISTINCT FROM c OR binding.environment IS DISTINCT FROM m.environment OR binding.payload_sha256 IS DISTINCT FROM v.payload_hash THEN
  RAISE EXCEPTION 'prodat_confirmed_death_response_original_guide_required';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(binding.source_version);positive_text:=projection#>>'{constraints,common,positiveText}';
 IF positive_text IS NULL OR NOT(projection#>'{constraints,PRODAT,allowedErc}'@>'["100"]'::jsonb) THEN RAISE EXCEPTION 'prodat_confirmed_death_response_original_guide_required';END IF;
 SELECT jsonb_agg(e||jsonb_build_object('outcome','positive') ORDER BY ord) INTO objects FROM jsonb_array_elements(initial->'objects') WITH ORDINALITY x(e,ord);
 RETURN initial||jsonb_build_object('objects',objects,'responses',jsonb_build_array(jsonb_build_object('scope','object','lineIndex',first_line,'ercCode','100','fieldCode',NULL,'text',positive_text,'id',planned->'id','li',planned->'li')),
  'effectScopes',jsonb_build_array(jsonb_build_object('lineIndex',first_line,'canonicalAssessmentId',v.canonical_assessment_id,'objectAssessmentId',NULL,
   'effectReceiptId',v.source_message_id,'effectFactsHash',encode(sha256(convert_to(to_jsonb(v)::text,'UTF8')),'hex'),'appliedAt',w.observed_at,'effectKind','confirmed_customer_version')));
END $$;

--
-- Name: correction_concerns; Type: TABLE; Schema: gridex_received_sources; Owner: -
--

CREATE TABLE gridex_received_sources.correction_concerns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_message_id uuid NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    source_payload_hash text NOT NULL,
    actor_user_id uuid NOT NULL,
    source_received_at timestamp with time zone NOT NULL,
    source_captured_at timestamp with time zone NOT NULL,
    captured_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_xid xid8 DEFAULT pg_current_xact_id() NOT NULL,
    rule_version text DEFAULT 'sealed-z05-concern-v1'::text NOT NULL,
    previous_capture_id uuid,
    facts jsonb NOT NULL,
    facts_hash text NOT NULL,
    disposition text DEFAULT 'unreviewed'::text NOT NULL,
    CONSTRAINT correction_concerns_check CHECK ((facts_hash = encode(sha256(convert_to((facts)::text, 'UTF8'::name)), 'hex'::text))),
    CONSTRAINT correction_concerns_check1 CHECK ((captured_at >= source_captured_at)),
    CONSTRAINT correction_concerns_disposition_check CHECK ((disposition = 'unreviewed'::text)),
    CONSTRAINT correction_concerns_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT correction_concerns_facts_check CHECK (((jsonb_typeof(facts) = 'object'::text) AND (octet_length((facts)::text) <= 262144))),
    CONSTRAINT correction_concerns_rule_version_check CHECK ((rule_version = 'sealed-z05-concern-v1'::text)),
    CONSTRAINT correction_concerns_source_payload_hash_check CHECK ((source_payload_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_received_sources.correction_concerns FORCE ROW LEVEL SECURITY;

--
-- Name: correction_receipt_v1(gridex_received_sources.correction_concerns); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.correction_receipt_v1(c gridex_received_sources.correction_concerns) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('version',1,'captureId',c.id,'companyId',c.company_id,'environment',c.environment,
  'sourceMessageId',c.source_message_id,'contentHash',c.source_payload_hash,'factsHash',c.facts_hash,
  'capturedAt',c.captured_at,'disposition','unreviewed')
$$;

--
-- Name: correction_wire_exact_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.correction_wire_exact_v1(p_raw text, p_object jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE decoded jsonb:=gridex_received_sources.z05_wire_structure_v1(p_raw,p_object); wire jsonb;
BEGIN
 IF decoded IS NULL OR decoded->'syntax' IS DISTINCT FROM '["UNOC","3"]'::jsonb
 OR decoded->'messageType' IS DISTINCT FROM '["PRODAT","D","97A","UN","E2SE6A"]'::jsonb
 OR decoded->>'objectCount'<>'1' OR decoded#>>'{wire,reason}' IS DISTINCT FROM 'Z24'
 OR decoded#>>'{wire,transportReceiver}' IS DISTINCT FROM decoded#>>'{wire,legalReceiver}'
 THEN RETURN NULL; END IF;
 wire:=decoded->'wire';
 RETURN wire||jsonb_build_object('subtype','C');
END $$;

--
-- Name: correction_wire_observation_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.correction_wire_observation_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v1(p_raw); line jsonb; obj jsonb; wire jsonb;
 result jsonb:=jsonb_build_object('objectId',NULL,'identityAgency',NULL,'legalSender',NULL,'legalReceiver',NULL,
  'caseReference',NULL,'candidateTarget',NULL,'oldStop',jsonb_build_object('kind','unknown'),
  'proposedStop',jsonb_build_object('kind','unknown'),'observedSourceStop',jsonb_build_object('kind','unknown'),'disposition','unreviewed');
BEGIN
 IF tokens IS NULL THEN RETURN result; END IF;
 SELECT t INTO line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' ORDER BY (t->>'index')::int LIMIT 1;
 IF line IS NULL THEN RETURN result; END IF;
 obj:=jsonb_build_object('messageIndex',0,'messageReference',tokens#>>'{1,elements,1,0}',
  'objectId',line#>>'{elements,3,0}','identityAgency',line#>>'{elements,3,3}',
  'registers',jsonb_build_array(jsonb_build_object('lineIndex',0,'lineNumber',line#>>'{elements,1,0}',
   'registerIndex',NULL,'registerPosition',1,'segmentIndex',(line->>'index')::int)));
 wire:=gridex_received_sources.correction_wire_exact_v1(p_raw,obj);
 IF wire IS NULL OR EXISTS(SELECT FROM unnest(ARRAY[obj->>'objectId',wire->>'legalSender',wire->>'legalReceiver']) v
  WHERE length(v)>128 OR v<>btrim(v) OR v ~ '[[:cntrl:]]') THEN RETURN result; END IF;
 -- A C date alone cannot establish the old L/LK target boundary. Keep oldStop
 -- unknown; only a later, independently linked target owner can enrich it.
 -- A bare, completely read C has no separate proposed date. Any additional
 -- free text/date or unfamiliar grammar stays unknown, hence whole-interval hold.
 result:=result||jsonb_build_object('objectId',obj->>'objectId','identityAgency','9',
  'legalSender',wire->>'legalSender','legalReceiver',wire->>'legalReceiver','caseReference',wire->>'caseReference',
  'observedSourceStop',jsonb_build_object('kind','known','utc',wire#>>'{effectiveTo,utc}'));
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE
  t->>'tag' NOT IN ('UNB','UNH','BGM','DTM','NAD','LIN','CCI','CAV','RFF','UNT','UNZ')
  OR (t->>'tag'='DTM' AND t#>>'{elements,1,0}' NOT IN ('137','ZZZ','93'))
  OR (t->>'tag'='RFF' AND t#>>'{elements,1,0}' NOT IN ('Z05','LI')))
  AND (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='93')=1
  AND (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CCI')=1
  AND (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV')=1
 THEN result:=result||jsonb_build_object('proposedStop',jsonb_build_object('kind','not_asserted')); END IF;
 RETURN result;
END $$;

--
-- Name: document_reference_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.document_reference_actor_v1(p_company_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL
 OR EXISTS(SELECT FROM unnest(ARRAY['communication.send','documents.read','customers.read']) permission
 WHERE NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,permission),false))
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id AND is_active AND status='active')
 OR NOT EXISTS(SELECT FROM public.companies WHERE id=p_company_id AND coalesce(is_active,true)
 AND coalesce(status,'active') NOT IN ('archived','suspended','pending_deletion','deleted','deleted_test_only','inactive','paused','closed'))
 THEN RAISE EXCEPTION 'document_reference_unavailable' USING ERRCODE='42501'; END IF;
END $$;

--
-- Name: document_reference_facts_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.document_reference_facts_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; doc public.customer_contract_documents%rowtype;
 wire jsonb; graph jsonb; n integer; eligible boolean; locked jsonb;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment;
 SELECT d.* INTO doc FROM public.customer_contract_documents d JOIN public.customer_contracts c ON c.id=d.customer_contract_id AND c.company_id=p_company_id
 WHERE d.id=p_document_id AND d.company_id=p_company_id;
 IF src.source_message_id IS NULL OR doc.id IS NULL OR src.origin<>'database_insert' OR src.message_code IS DISTINCT FROM 'Z05'
 OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(src.raw_payload,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'document_reference_unavailable' USING ERRCODE='42501'; END IF;
 wire:=gridex_received_sources.correction_wire_observation_v1(src.raw_payload);
 locked:=jsonb_build_object('id',doc.id,'company_id',doc.company_id,'customer_contract_id',doc.customer_contract_id,
 'document_type',doc.document_type,'storage_bucket',doc.storage_bucket,'storage_path',doc.storage_path,'mime_type',doc.mime_type,
 'document_sha256',doc.document_sha256,'generation_snapshot',doc.generation_snapshot);
 SELECT count(*),(jsonb_agg(jsonb_build_object('customerId',c.customer_id,'contractId',c.id,'siteId',s.id,'pointId',m.id,'supplyPeriodId',sp.id,
 'objectId',wire->>'objectId','identityAgency',wire->>'identityAgency','legalSender',wire->>'legalSender','legalReceiver',wire->>'legalReceiver')))->0 INTO n,graph
 FROM public.customer_contracts c
 JOIN public.customers customer ON customer.id=c.customer_id AND customer.company_id=p_company_id
 JOIN public.customer_sites s ON s.id=c.customer_site_id AND s.company_id=p_company_id AND s.customer_id=customer.id
 JOIN public.metering_points m ON m.id=c.metering_point_id AND m.company_id=p_company_id AND m.customer_id=customer.id AND m.site_id=s.id
 JOIN public.customer_supply_periods sp ON sp.company_id=p_company_id AND sp.customer_id=customer.id AND sp.metering_point_id=m.id AND sp.customer_contract_id=c.id
 JOIN public.grid_owners g ON g.id=m.grid_owner_id AND g.id=s.grid_owner_id AND (g.company_id IS NULL OR g.company_id=p_company_id)
 WHERE c.id=doc.customer_contract_id AND c.company_id=p_company_id AND (c.site_id IS NULL OR c.site_id=s.id)
 AND (m.customer_site_id IS NULL OR m.customer_site_id=s.id)
 AND (sp.contract_id IS NULL OR sp.contract_id=c.id)
 AND m.meter_point_id=wire->>'objectId' AND (m.metering_point_id IS NULL OR m.metering_point_id=wire->>'objectId')
 AND s.facility_id=wire->>'objectId' AND wire->>'identityAgency'='9'
 AND g.ediel_id=wire->>'legalSender' AND g.environment=p_environment AND g.is_active AND g.lifecycle_status='active'
 AND EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.company_id=p_company_id AND p.environment=p_environment AND p.market='electricity' AND p.is_enabled
 AND p.valid_from<=src.source_received_at AND (p.valid_to IS NULL OR src.source_received_at<p.valid_to))
 AND (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=p_company_id AND i.environment=p_environment
 AND i.identifier_type='EdielId' AND i.valid_from<=src.source_received_at AND (i.valid_to IS NULL OR src.source_received_at<i.valid_to))=1
 AND EXISTS(SELECT FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=p_company_id AND i.environment=p_environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'legalReceiver'
 AND i.valid_from<=src.source_received_at AND (i.valid_to IS NULL OR src.source_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=src.source_received_at AND (r.valid_to IS NULL OR src.source_received_at<r.valid_to));
 IF n<>1 THEN graph:=NULL; END IF;
 eligible:=n=1 AND doc.storage_path IS NOT NULL AND doc.document_type='signed_contract_pdf' AND doc.storage_bucket='customer-contract-documents'
 AND doc.mime_type='application/pdf' AND doc.document_sha256 ~ '^[a-f0-9]{64}$';
 RETURN jsonb_build_object('sourceHash',src.payload_hash,'sourceScope',wire,'document',locked,'graph',graph,'eligible',coalesce(eligible,false));
END $_$;

--
-- Name: gridex_apply_exact_z02_core_before_current_source_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.gridex_apply_exact_z02_core_before_current_source_v1(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_request public.customer_info_requests%rowtype;
  v_message public.ediel_messages%rowtype;
  v_site public.customer_sites%rowtype;
  v_meter public.metering_points%rowtype;
  v_conflict public.metering_points%rowtype;
  v_meter_external text;
  v_facility_id text;
  v_grid_area text;
  v_price_area text;
  v_source gridex_received_sources.sources%rowtype;
  v_dispatch gridex_ediel_transport.attempts%rowtype;
  v_original public.ediel_messages%rowtype;
  v_applied gridex_received_sources.z02_core_applications%rowtype;
  v_assessment gridex_received_sources.validation_assessments%rowtype;
  v_customer public.customers%rowtype;
  v_snapshot public.customer_operation_request_snapshots%rowtype;
  v_inbound_wire jsonb;v_original_wire jsonb;v_object jsonb;v_original_object jsonb;v_facet jsonb;
  v_match_count integer;v_result jsonb;v_expected_identity text;v_expected_qualifier text;
  v_current_address_hash text;
  v_price_area_count integer := 0;
  v_now timestamptz := now();
begin
  select * into v_request
  from public.customer_info_requests
  where id = p_request_id
    and company_id = p_company_id
    and customer_id = p_customer_id
    and site_id = p_site_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_request_site_customer_mismatch');
  end if;

  select * into v_message
  from public.ediel_messages
  where id = p_message_id
    and company_id = p_company_id
    and direction = 'inbound'
    and message_family = 'PRODAT'
    and upper(coalesce(message_code, '')) = 'Z02'
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_inbound_message_not_found');
  end if;

  select * into v_site
  from public.customer_sites
  where id = p_site_id
    and company_id = p_company_id
    and customer_id = p_customer_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_site_not_found');
  end if;

  if v_message.customer_id is not null and v_message.customer_id <> p_customer_id then
    return jsonb_build_object('ok', false, 'code', 'z02_customer_mismatch');
  end if;
  if v_message.site_id is not null and v_message.site_id <> p_site_id then
    return jsonb_build_object('ok', false, 'code', 'response_site_mismatch');
  end if;
  if v_request.grid_owner_id is not null
     and v_message.grid_owner_id is not null
     and v_request.grid_owner_id <> v_message.grid_owner_id then
    return jsonb_build_object('ok', false, 'code', 'grid_owner_conflict');
  end if;

  -- Lock/read the original tenant/environment source, never hydrate authority
  -- from mutable parsed_payload, validation_report, an incoming JSON signal or
  -- a cached job result. Already committed same-scope outcomes stay immutable.
  SELECT * INTO v_source FROM gridex_received_sources.sources
   WHERE source_message_id=p_message_id AND company_id=p_company_id AND environment=v_message.environment AND message_code='Z02';
  IF NOT FOUND OR v_source.raw_payload IS NULL OR v_source.payload_hash IS DISTINCT FROM v_message.immutable_payload_hash
   OR v_source.raw_payload IS DISTINCT FROM v_message.raw_payload OR v_source.source_received_at IS NULL THEN
   RETURN jsonb_build_object('ok',false,'code','z02_frozen_source_unavailable');END IF;
  SELECT * INTO v_applied FROM gridex_received_sources.z02_core_applications WHERE source_message_id=p_message_id AND request_id=p_request_id;
  IF FOUND THEN
   IF v_applied.company_id IS DISTINCT FROM p_company_id OR v_applied.customer_id IS DISTINCT FROM p_customer_id OR v_applied.site_id IS DISTINCT FROM p_site_id
    OR v_applied.source_payload_hash IS DISTINCT FROM v_source.payload_hash THEN RETURN jsonb_build_object('ok',false,'code','z02_applied_source_scope_mismatch');END IF;
   RETURN v_applied.result;
  END IF;
  SELECT count(*) INTO v_match_count FROM gridex_received_sources.validation_assessments a
   WHERE a.source_message_id=p_message_id AND a.company_id=p_company_id AND a.environment=v_source.environment AND a.source_payload_hash=v_source.payload_hash
   AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
  IF v_match_count<>1 THEN RETURN jsonb_build_object('ok',false,'code','z02_current_canonical_assessment_ambiguous'); END IF;
  SELECT a.* INTO v_assessment FROM gridex_received_sources.validation_assessments a
   WHERE a.source_message_id=p_message_id AND a.company_id=p_company_id AND a.environment=v_source.environment AND a.source_payload_hash=v_source.payload_hash
   AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
  IF NOT FOUND OR v_assessment.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted'
   OR v_assessment.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR v_assessment.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN
   RETURN jsonb_build_object('ok',false,'code','z02_canonical_source_not_accepted');END IF;
  SELECT * INTO v_original FROM public.ediel_messages
   WHERE id=v_request.ediel_message_id AND company_id=p_company_id AND environment=v_source.environment AND direction='outbound' AND message_standard='edifact' AND message_family='PRODAT' AND message_code='Z01'
    AND customer_id=p_customer_id AND site_id=p_site_id FOR SHARE;
  IF NOT FOUND OR v_original.raw_payload IS NULL OR v_original.immutable_rendered_at IS NULL
   OR v_original.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(v_original.raw_payload,'UTF8')),'hex')
   OR v_request.operation_id IS NULL OR p_operation_id IS NOT NULL AND p_operation_id IS DISTINCT FROM v_request.operation_id THEN
   RETURN jsonb_build_object('ok',false,'code','z02_originating_sent_source_unavailable');END IF;
  SELECT * INTO v_dispatch FROM gridex_ediel_transport.attempts a
   WHERE a.message_id=v_original.id AND a.company_id=p_company_id AND a.environment=v_source.environment
    AND a.binding->>'originalHash'=v_original.immutable_payload_hash AND a.classification='accepted'
    AND a.entered_at IS NOT NULL AND a.observed_at IS NOT NULL AND a.entered_at<=a.observed_at AND a.observed_at<=v_source.source_received_at
   ORDER BY a.observed_at,a.id LIMIT 1 FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','z02_originating_dispatch_proof_required'); END IF;
  v_inbound_wire:=gridex_received_sources.z02_core_wire_v1(v_source.raw_payload);v_original_wire:=gridex_received_sources.z02_core_wire_v1(v_original.raw_payload);
  IF v_inbound_wire IS NULL OR v_original_wire IS NULL OR v_inbound_wire->>'code'<>'Z02' OR v_original_wire->>'code'<>'Z01'
   OR v_inbound_wire->>'sender' IS DISTINCT FROM v_original_wire->>'receiver' OR v_inbound_wire->>'receiver' IS DISTINCT FROM v_original_wire->>'sender'
   OR v_inbound_wire->>'transportSender' IS DISTINCT FROM v_original_wire->>'transportReceiver' OR v_inbound_wire->>'transportReceiver' IS DISTINCT FROM v_original_wire->>'transportSender' THEN
   RETURN jsonb_build_object('ok',false,'code','z02_original_party_namespace_mismatch');END IF;
  SELECT count(*) INTO v_match_count FROM jsonb_array_elements(v_original_wire->'objects') x
   WHERE x->>'objectId'=coalesce(nullif(btrim(v_site.normalized_facility_id),''),nullif(btrim(v_site.facility_id),''));
  IF v_match_count<>1 THEN RETURN jsonb_build_object('ok',false,'code','z02_originating_object_ambiguous');END IF;
  SELECT x INTO v_original_object FROM jsonb_array_elements(v_original_wire->'objects') x
   WHERE x->>'objectId'=coalesce(nullif(btrim(v_site.normalized_facility_id),''),nullif(btrim(v_site.facility_id),''));
  SELECT count(*) INTO v_match_count FROM jsonb_array_elements(v_inbound_wire->'objects') x
   WHERE x->>'objectId'=v_original_object->>'objectId' AND x->>'identityAgency'=v_original_object->>'identityAgency'
    AND x->>'lineReference'=v_original_object->>'lineReference';
  IF v_match_count<>1 OR nullif(v_original_object->>'lineReference','') IS NULL THEN RETURN jsonb_build_object('ok',false,'code','z02_original_object_reference_mismatch');END IF;
  SELECT x INTO v_object FROM jsonb_array_elements(v_inbound_wire->'objects') x
   WHERE x->>'objectId'=v_original_object->>'objectId' AND x->>'identityAgency'=v_original_object->>'identityAgency' AND x->>'lineReference'=v_original_object->>'lineReference';
  SELECT count(*) INTO v_match_count FROM jsonb_array_elements(v_assessment.facts_text::jsonb#>'{registerValidation,objects}') x
   WHERE x->>'objectId'=v_object->>'objectId' AND x->>'identityAgency'=v_object->>'identityAgency' AND x->>'messageIndex'='0'
    AND x->>'messageReference'=v_inbound_wire->>'messageReference';
  IF v_match_count<>1 THEN RETURN jsonb_build_object('ok',false,'code','z02_own_canonical_object_ambiguous'); END IF;
  SELECT x INTO v_facet FROM jsonb_array_elements(v_assessment.facts_text::jsonb#>'{registerValidation,objects}') x
   WHERE x->>'objectId'=v_object->>'objectId' AND x->>'identityAgency'=v_object->>'identityAgency' AND x->>'messageIndex'='0'
    AND x->>'messageReference'=v_inbound_wire->>'messageReference';
  IF v_facet->>'disposition' IS DISTINCT FROM 'accepted' OR jsonb_array_length(v_facet->'registers') IS DISTINCT FROM 1
   OR v_facet#>>'{registers,0,lineIndex}' IS DISTINCT FROM v_object->>'lineIndex' OR v_facet#>>'{registers,0,segmentIndex}' IS DISTINCT FROM v_object->>'segmentIndex'
   OR v_facet#>>'{registers,0,lineNumber}' IS DISTINCT FROM v_object->>'lineNumber' THEN RETURN jsonb_build_object('ok',false,'code','z02_own_canonical_object_unavailable');END IF;
  IF (v_object->>'reason' IN ('Z22','Z23')) IS NOT TRUE OR v_object->>'reason' IS DISTINCT FROM v_original_object->>'reason'
   OR NOT EXISTS(SELECT FROM public.ediel_business_references br WHERE br.company_id=p_company_id AND br.source_message_id=v_original.id AND br.message_family='PRODAT' AND br.message_code='Z01' AND br.reference_type='RFF_LI' AND br.reference_value=v_object->>'lineReference') THEN
   RETURN jsonb_build_object('ok',false,'code','z02_source_reference_or_subtype_mismatch');END IF;
  SELECT * INTO v_customer FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id FOR SHARE;
  v_expected_identity:=coalesce(nullif(btrim(v_customer.org_number),''),nullif(btrim(v_customer.personal_number),''));
  v_expected_qualifier:=CASE WHEN nullif(btrim(v_customer.org_number),'') IS NOT NULL THEN 'SE1' WHEN nullif(btrim(v_customer.personal_number),'') IS NOT NULL THEN 'SE2' ELSE NULL END;
  IF v_expected_identity IS NULL OR v_object->>'customerId' IS DISTINCT FROM v_expected_identity OR v_object->>'customerQualifier' IS DISTINCT FROM v_expected_qualifier OR v_object->>'customerAgency' IS DISTINCT FROM '260'
   OR v_object->>'customerId' IS DISTINCT FROM v_original_object->>'customerId' OR v_object->>'customerQualifier' IS DISTINCT FROM v_original_object->>'customerQualifier'
   OR nullif(v_object->>'customerName','') IS NULL THEN RETURN jsonb_build_object('ok',false,'code','z02_verified_customer_identity_mismatch');END IF;
  SELECT * INTO v_snapshot FROM public.customer_operation_request_snapshots WHERE company_id=p_company_id AND operation_id=v_request.operation_id AND customer_id=p_customer_id AND customer_site_id=p_site_id
   AND request_kind='customer_data_request' AND request_reference=p_request_id::text AND superseded_at IS NULL FOR SHARE;
  v_current_address_hash:=coalesce(nullif(btrim(v_site.address_hash),''),lower(concat_ws('|',nullif(btrim(v_site.street),''),nullif(regexp_replace(coalesce(v_site.postal_code,''),'[^0-9]','','g'),''),nullif(btrim(v_site.city),''))));
  IF NOT FOUND OR v_snapshot.site_address_hash IS DISTINCT FROM v_current_address_hash OR v_snapshot.grid_owner_id IS DISTINCT FROM v_site.grid_owner_id
   OR nullif(v_original_object->>'installationAddress','') IS NOT NULL AND btrim(v_original_object->>'installationAddress') IS DISTINCT FROM btrim(v_site.street) THEN
   RETURN jsonb_build_object('ok',false,'code','z02_original_site_snapshot_changed');END IF;
  IF EXISTS(SELECT FROM gridex_received_sources.z02_core_applications WHERE source_message_id=p_message_id AND object_id=v_object->>'objectId' AND identity_agency=v_object->>'identityAgency') THEN
   RETURN jsonb_build_object('ok',false,'code','z02_object_already_applied_to_other_request');END IF;
  v_meter_external:=v_object->>'objectId';v_facility_id:=v_meter_external;v_grid_area:=v_object->>'gridArea';
  IF nullif(v_grid_area,'') IS NULL THEN RETURN jsonb_build_object('ok',false,'code','z02_source_grid_area_missing');END IF;

  select count(distinct upper(pga.price_area))::integer,
         min(upper(pga.price_area))
    into v_price_area_count, v_price_area
  from public.platform_grid_areas pga
  where pga.is_active = true
    and upper(pga.grid_area_code) = upper(v_grid_area)
    and upper(coalesce(pga.price_area, '')) in ('SE1','SE2','SE3','SE4')
    and (pga.valid_from is null or pga.valid_from <= (v_source.source_received_at AT TIME ZONE 'Etc/GMT-1')::date)
    and (pga.valid_to is null or pga.valid_to >= (v_source.source_received_at AT TIME ZONE 'Etc/GMT-1')::date);

  if v_meter_external is null then
    return jsonb_build_object('ok', false, 'code', 'z02_metering_point_missing');
  end if;
  if v_price_area_count <> 1 or v_price_area not in ('SE1','SE2','SE3','SE4') then
    return jsonb_build_object('ok', false, 'code', 'z02_grid_area_price_area_unresolved', 'gridAreaCode', v_grid_area);
  end if;
  if nullif(btrim(v_site.price_area_code), '') is not null and upper(v_site.price_area_code) <> v_price_area then
    return jsonb_build_object('ok', false, 'code', 'z02_existing_price_area_conflict', 'existingPriceArea', upper(v_site.price_area_code), 'canonicalPriceArea', v_price_area);
  end if;
  if v_site.facility_id is not null and btrim(v_site.facility_id) <> v_facility_id then
    return jsonb_build_object('ok', false, 'code', 'facility_identifier_conflict');
  end if;

  if v_facility_id is not null and exists (
    select 1
    from public.customer_sites s
    where s.company_id = p_company_id
      and s.id <> p_site_id
      and s.is_active = true
      and (
        s.normalized_facility_id = v_facility_id
        or s.facility_id = v_facility_id
      )
  ) then
    return jsonb_build_object('ok', false, 'code', 'cross_site_identifier_conflict');
  end if;

  select * into v_conflict
  from public.metering_points m
  where m.company_id = p_company_id
    and coalesce(m.customer_site_id, m.site_id) <> p_site_id
    and m.status in ('draft','pending_validation','active')
    and (
      m.metering_point_id = v_meter_external
      or m.meter_point_id = v_meter_external
      or m.ediel_reference = v_meter_external
      or m.ediel_metering_point_id = v_meter_external
    )
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', false,
      'code', 'duplicate_metering_point',
      'conflictingSiteId', coalesce(v_conflict.customer_site_id, v_conflict.site_id),
      'conflictingMeteringPointId', v_conflict.id
    );
  end if;

  -- Resolve the actual selected point before any writes. Core 209/260 facts
  -- cannot invent energy direction, reading frequency or settlement relevance
  -- for a new point; those belong to a separately sourced masterdata operation.
  SELECT * INTO v_meter FROM public.metering_points m
   WHERE m.company_id=p_company_id AND m.customer_id=p_customer_id
    AND coalesce(m.customer_site_id,m.site_id)=p_site_id
    AND (p_request_id IS NOT NULL AND m.id=v_request.metering_point_id
     OR v_request.metering_point_id IS NULL AND (m.metering_point_id=v_meter_external OR m.meter_point_id=v_meter_external OR m.ediel_reference=v_meter_external OR m.ediel_metering_point_id=v_meter_external))
   ORDER BY m.id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','z02_source_qualified_point_creation_required'); END IF;
  SELECT count(*) INTO v_match_count FROM public.metering_points m
   WHERE m.company_id=p_company_id AND m.customer_id=p_customer_id AND coalesce(m.customer_site_id,m.site_id)=p_site_id
    AND (m.id=v_request.metering_point_id OR v_request.metering_point_id IS NULL AND (m.metering_point_id=v_meter_external OR m.meter_point_id=v_meter_external OR m.ediel_reference=v_meter_external OR m.ediel_metering_point_id=v_meter_external));
  IF v_match_count<>1 THEN RETURN jsonb_build_object('ok',false,'code','z02_selected_point_ambiguous'); END IF;

  update public.customer_sites
  set facility_id = coalesce(v_facility_id, facility_id),
      normalized_facility_id = coalesce(v_facility_id, normalized_facility_id),
      grid_area_code = coalesce(v_grid_area, grid_area_code),
      price_area_code = coalesce(v_price_area, price_area_code),
      bidding_zone_code = coalesce(v_price_area, bidding_zone_code),
      facility_data_status = 'verified',
      facility_data_verified_at = v_now,
      resolution_status = 'facility_verified',
      data_quality_status = 'verified',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'facility_provenance', jsonb_build_object(
          'sourceType', 'ediel_inbound',
          'sourceMessageId', p_message_id,
          'sourcePartyId', coalesce(v_message.grid_owner_id, v_request.grid_owner_id),
          'receivedAt', v_now,
          'verificationLevel', 'market_verified',
          'verifiedAt', v_now,
          'customerInfoRequestId', p_request_id,
          'operationId', p_operation_id
        )
      ),
      updated_at = v_now,
      updated_by = p_actor_user_id
  where id = p_site_id
    and company_id = p_company_id
    and customer_id = p_customer_id;

    update public.metering_points
    set site_id = p_site_id,
        customer_site_id = p_site_id,
        customer_id = p_customer_id,
        metering_point_id = v_meter_external,
        meter_point_id = v_meter_external,
        ediel_metering_point_id = coalesce(ediel_metering_point_id, v_meter_external),
        ediel_reference = coalesce(ediel_reference, v_meter_external),
        site_facility_id = coalesce(v_facility_id, site_facility_id),
        grid_owner_id = coalesce(v_request.grid_owner_id, v_message.grid_owner_id, grid_owner_id),
        grid_area_code = coalesce(v_grid_area, grid_area_code),
        price_area_code = coalesce(v_price_area, price_area_code),
        bidding_zone_code = coalesce(v_price_area, bidding_zone_code),
        status = 'active',
        data_quality_status = 'verified',
        verification_status = 'verified',
        facility_data_status = 'verified',
        facility_data_verified_at = v_now,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'z02_market_verified', true,
          'z02_message_id', p_message_id,
          'customer_info_request_id', p_request_id,
          'operation_id', p_operation_id,
          'verified_at', v_now
        ),
        updated_at = v_now,
        updated_by = p_actor_user_id
    where id = v_meter.id
    returning * into v_meter;

  update public.customer_info_requests
  set status = 'ready_for_switch',
      metering_point_id = v_meter.id,
      response_ediel_message_id = p_message_id,
      received_at = coalesce(received_at, v_now),
      blocker_code = null,
      blocker_reason = null,
      blocker_details = '{}'::jsonb,
      route_resolution_status = 'z02_market_verified',
      next_required_action = 'Kör canonical supplier-switch readiness och nästa steg.',
      verified_payload = coalesce(verified_payload, '{}'::jsonb) || jsonb_build_object(
        'z02', jsonb_build_object(
          'message_id', p_message_id,
          'metering_point_id', v_meter_external,
          'facility_id', v_facility_id,
          'grid_area_code', v_grid_area,
          'price_area_code', v_price_area,
          'verification_level', 'market_verified',
          'verified_at', v_now,
          'atomic_core_apply', true
        )
      ),
      updated_at = v_now,
      updated_by = p_actor_user_id
  where id = p_request_id
    and company_id = p_company_id
    and customer_id = p_customer_id
    and site_id = p_site_id;

  if v_request.grid_owner_data_request_id is not null then
    update public.grid_owner_data_requests
    set status = 'received',
        response_payload = coalesce(response_payload, '{}'::jsonb) || jsonb_build_object(
          'z02_message_id', p_message_id,
          'metering_point_id', v_meter_external,
          'facility_id', v_facility_id,
          'grid_area_code', v_grid_area,
          'price_area_code', v_price_area,
          'atomic_core_apply', true,
          'received_at', v_now
        ),
        updated_at = v_now,
        updated_by = p_actor_user_id
    where id = v_request.grid_owner_data_request_id
      and company_id = p_company_id;
  end if;

  update public.ediel_messages
  set customer_id = p_customer_id,
      site_id = p_site_id,
      metering_point_id = v_meter.id,
      grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
      operation_id = coalesce(operation_id, p_operation_id),
      parsed_payload = coalesce(parsed_payload, '{}'::jsonb) || jsonb_build_object(
        'canonicalCorrelation', jsonb_build_object(
          'status', 'exact',
          'customer_info_request_id', p_request_id,
          'customer_id', p_customer_id,
          'site_id', p_site_id,
          'metering_point_record_id', v_meter.id,
          'operation_id', p_operation_id,
          'atomic_core_apply', true,
          'applied_at', v_now
        )
      ),
      updated_at = v_now
  where id = p_message_id
    and company_id = p_company_id;

  v_result := jsonb_build_object(
    'ok', true,
    'requestId', p_request_id,
    'messageId', p_message_id,
    'customerId', p_customer_id,
    'customerSiteId', p_site_id,
    'meteringPointRecordId', v_meter.id,
    'meteringPointExternalId', v_meter_external,
    'facilityId', v_facility_id,
    'gridAreaCode', v_grid_area,
    'priceAreaCode', v_price_area,
    'atomicCoreApply', true
  );
  INSERT INTO gridex_received_sources.z02_core_applications(source_message_id,company_id,environment,source_payload_hash,canonical_assessment_id,originating_z01_message_id,originating_transport_attempt_id,request_id,customer_id,site_id,object_id,identity_agency,metering_point_id,result)
  VALUES(p_message_id,p_company_id,v_source.environment,v_source.payload_hash,v_assessment.id,v_original.id,v_dispatch.id,p_request_id,p_customer_id,p_site_id,v_object->>'objectId',v_object->>'identityAgency',v_meter.id,v_result);
  RETURN v_result;
end;
$$;

--
-- Name: FUNCTION gridex_apply_exact_z02_core_before_current_source_v1(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: gridex_received_sources; Owner: -
--

COMMENT ON FUNCTION gridex_received_sources.gridex_apply_exact_z02_core_before_current_source_v1(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid, p_actor_user_id uuid) IS 'Atomic exact Z02 own-object application from immutable original + latest canonical facet + sealed originating Z01; excluded field213 and caller JSON never mutate business values. Final source-scoped outcomes are append-only.';

--
-- Name: identity_omission_cases_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.identity_omission_cases_v1() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
-- BEGIN CANONICAL IDENTITY OMISSION PROJECTION
 SELECT '[{"messageCode":"Z14","transactionReason":"Z96"},{"messageCode":"Z13","transactionReason":"S17"},{"messageCode":"Z13","transactionReason":"S18"}]'::jsonb
-- END CANONICAL IDENTITY OMISSION PROJECTION
$$;

--
-- Name: identity_omission_scope_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.identity_omission_scope_v1(raw text, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;lin jsonb;next_index integer;own jsonb;cci jsonb;cav jsonb;code text;reason text;idx integer;parent_index integer;
BEGIN
 IF object_scope->'objectId' IS DISTINCT FROM 'null'::jsonb OR object_scope->'identityAgency' IS DISTINCT FROM 'null'::jsonb
  OR object_scope->'messageIndex' IS DISTINCT FROM '0'::jsonb OR jsonb_array_length(object_scope->'registers') IS DISTINCT FROM 1
  OR object_scope#>'{registers,0,registerIndex}' IS DISTINCT FROM 'null'::jsonb OR object_scope#>'{registers,0,registerPosition}' IS DISTINCT FROM '1'::jsonb THEN RETURN false;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);IF tokens IS NULL THEN RETURN false;END IF;
 IF(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1
  OR(SELECT t#>>'{elements,2,0}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH') IS DISTINCT FROM 'PRODAT'
  OR(SELECT t#>>'{elements,1,0}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH') IS DISTINCT FROM object_scope->>'messageReference'
  OR(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RETURN false;END IF;
 SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 SELECT t INTO lin FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND t->'index'=object_scope#>'{registers,0,segmentIndex}';
 IF lin IS NULL OR jsonb_array_length(lin->'elements')>4 OR EXISTS(SELECT FROM jsonb_array_elements(coalesce(lin#>'{elements,3}','[]'))v WHERE v#>>'{}'<>'')
  OR lin#>>'{elements,1,0}'!~'^[0-9]{1,6}$' OR (lin#>>'{elements,1,0}')::integer<1 OR jsonb_array_length(lin#>'{elements,1}')<>1
  OR (lin#>>'{elements,1,0}')::integer IS DISTINCT FROM (object_scope#>>'{registers,0,lineIndex}')::integer+1
  OR lin#>>'{elements,1,0}' IS DISTINCT FROM object_scope#>>'{registers,0,lineNumber}'
  OR(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND(t->>'index')::integer<(lin->>'index')::integer) IS DISTINCT FROM (object_scope#>>'{registers,0,lineIndex}')::integer THEN RETURN false;END IF;
 SELECT min((t->>'index')::integer) INTO next_index FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('LIN','UNT','UNZ') AND(t->>'index')::integer>(lin->>'index')::integer;
 SELECT jsonb_agg(t ORDER BY(t->>'index')::integer) INTO own FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::integer>=(lin->>'index')::integer AND(t->>'index')::integer<next_index;
 IF(SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13')<>1 THEN RETURN false;END IF;
 SELECT t INTO cci FROM jsonb_array_elements(own)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13';idx:=(cci->>'index')::integer;
 SELECT t INTO cav FROM jsonb_array_elements(own)t WHERE(t->>'index')::integer=idx+1 AND t->>'tag'='CAV';
 SELECT min((t->>'index')::integer) INTO parent_index FROM jsonb_array_elements(own)t WHERE t->>'tag' IN('RFF','NAD');
 IF cav IS NULL OR(parent_index IS NOT NULL AND idx>=parent_index) OR jsonb_array_length(cci->'elements')<>3
  OR EXISTS(SELECT FROM jsonb_array_elements(cci#>'{elements,1}')v WHERE v#>>'{}'<>'') OR jsonb_array_length(cci#>'{elements,2}')<>1
  OR jsonb_array_length(cav->'elements')<>2 OR jsonb_array_length(cav#>'{elements,1}')<>1
  OR EXISTS(SELECT FROM jsonb_array_elements(own)t WHERE(t->>'index')::integer=idx+2 AND t->>'tag'='CAV') THEN RETURN false;END IF;
 reason:=cav#>>'{elements,1,0}';
 RETURN EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.identity_omission_cases_v1())e WHERE e->>'messageCode'=code AND e->>'transactionReason'=reason);
EXCEPTION WHEN OTHERS THEN RETURN false;END$_$;

--
-- Name: lock_prodat_execution_actor_graph_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.lock_prodat_execution_actor_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 LOCK TABLE auth.users,public.user_profiles,public.companies,public.company_memberships,public.admin_users,public.user_roles,public.roles,public.role_permissions,public.permissions,public.user_permissions IN SHARE MODE;
END $$;

--
-- Name: missing_li_repair_scopes_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.missing_li_repair_scopes_v1(c uuid, env text, ack_id uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE receipt jsonb;ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;tokens jsonb;erc jsonb;physical jsonb;scope jsonb;next_erc int;point text;count_groups int;result jsonb:='[]';
BEGIN
 receipt:=gridex_ack_authority.prodat_physical_receipt_v1(c,env,ack_id,source_id);IF receipt IS NULL THEN RETURN '[]';END IF;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=env;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c AND environment=env;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(ack.raw_payload);physical:=gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload);
 FOR scope IN SELECT x FROM jsonb_array_elements(receipt->'physicalOutcomes')x WHERE x->>'outcome'='negative' AND x#>>'{physicalReference,lineItemReference}' IS NULL LOOP
  count_groups:=0;
  FOR erc IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' LOOP
   SELECT min((x->>'index')::int) INTO next_erc FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>(erc->>'index')::int AND x->>'tag' IN('ERC','UNT','UNZ');
   IF erc#>>'{elements,1,0}'='41' AND erc#>>'{elements,1,2}'='260'
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND x#>>'{elements,1,0}'='AAO' AND x#>>'{elements,3,0}'='226' AND x#>>'{elements,3,2}'='260' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc)
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND x#>>'{elements,1,1}'=scope#>>'{physicalReference,objectId}' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc)
    AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc) THEN count_groups:=count_groups+1;END IF;
  END LOOP;
  IF count_groups<>1 THEN CONTINUE;END IF;
  SELECT x INTO STRICT physical FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload))x WHERE x->'lineIndex'=scope#>'{physicalReference,firstLineIndex}' AND x->>'id'=scope#>>'{physicalReference,objectId}' AND x->>'identityAgency'=scope#>>'{physicalReference,identityAgency}' AND x->>'li' IS NULL;
  result:=result||jsonb_build_array(physical);
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY(x->>'lineIndex')::int),'[]') INTO result FROM jsonb_array_elements(result)x;RETURN result;
END$$;

--
-- Name: mixed_owned_confirmation_v1(uuid, text, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.mixed_owned_confirmation_v1(c uuid, env text, msg uuid, assessment uuid, scope jsonb, business jsonb) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_object_receipts r JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=assessment AND f.source_message_id=r.source_message_id AND f.company_id=r.company_id AND f.environment=r.environment AND f.source_payload_hash=r.source_payload_hash AND f.facts_hash=r.object_facts_hash
  JOIN gridex_received_sources.normal_switch_confirmations n ON n.source_message_id=r.source_message_id AND n.company_id=r.company_id AND n.period_id::text=business->>'supplyPeriodId' AND n.switch_id::text=business->>'switchRequestId'
  WHERE r.company_id=c AND r.environment=env AND r.source_message_id=msg AND (SELECT current.facts_hash FROM gridex_received_sources.validation_assessments current WHERE current.id=assessment)=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND business->>'owner'='inbound-z04-switch-confirmation-v1' AND n.source_object->>'point'=scope->>'objectId'
   AND EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=scope->>'objectId' AND o->>'identityAgency'=scope->>'identityAgency' AND o->'firstLineIndex'=scope#>'{registers,0,lineIndex}' AND o->>'disposition'='accepted'))
$$;

--
-- Name: mixed_period_canonical_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.mixed_period_canonical_v1(assessment uuid, c uuid, period uuid, msg uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_object_receipts r
 JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=assessment AND f.source_payload_hash=r.source_payload_hash AND f.facts_hash=r.object_facts_hash
 JOIN gridex_received_sources.normal_switch_confirmations n ON n.source_message_id=r.source_message_id AND n.company_id=r.company_id AND n.period_id=period
 WHERE r.company_id=c AND r.source_message_id=msg AND (SELECT current.facts_hash FROM gridex_received_sources.validation_assessments current WHERE current.id=assessment)=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND f.facts_text::jsonb->>'sharedAccepted'='true'
 AND EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=n.source_object->>'point' AND o->>'identityAgency'=n.source_object->>'identityAgency' AND o->>'lineItemReference'=n.source_object->>'li' AND o->>'disposition'='accepted'))
$$;

--
-- Name: normal_switch_confirm_mixed_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.normal_switch_confirm_mixed_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 guide gridex_received_sources.prodat_object_validation_facets%rowtype;mixed_receipt gridex_received_sources.prodat_mixed_object_receipts%rowtype;whole_wire jsonb;guides jsonb;result jsonb;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 PERFORM gridex_received_sources.lock_prodat_execution_actor_graph_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(m.company_id,m.id);PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 SELECT * INTO mixed_receipt FROM gridex_received_sources.prodat_mixed_object_receipts WHERE source_message_id=m.id FOR SHARE;
 IF FOUND THEN
  IF mixed_receipt.company_id IS DISTINCT FROM m.company_id OR mixed_receipt.environment IS DISTINCT FROM m.environment OR mixed_receipt.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_mixed_replay_conflict';END IF;
  IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=a.id AND f.source_payload_hash=a.source_payload_hash AND f.facts_hash=mixed_receipt.object_facts_hash AND a.facts_hash=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=mixed_receipt.assessment_id)
   WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=mixed_receipt.source_payload_hash
   AND a.facts_text::jsonb->>'syntaxDecision'='accepted' AND a.facts_text::jsonb->>'applicationDecision'='rejected' AND a.facts_text::jsonb->>'functionalDecision'='accepted'
   AND f.facts_text::jsonb->>'sharedAccepted'='true' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)) THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_current_guide_changed');END IF;
  RETURN mixed_receipt.result||jsonb_build_object('idempotent',true);
 END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_existing_other_source_transition');END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'rejected' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 SELECT * INTO guide FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=canonical.id AND company_id=m.company_id AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE;
 IF NOT FOUND OR guide.facts_text::jsonb->>'sharedAccepted' IS DISTINCT FROM 'true' OR EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='unavailable') OR NOT EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='accepted') OR NOT EXISTS(SELECT FROM jsonb_array_elements(guide.facts_text::jsonb->'objects') o WHERE o->>'disposition'='rejected') THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_full_own_guides_required');END IF;
 guides:=guide.facts_text::jsonb->'objects';whole_wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF whole_wire IS NULL OR jsonb_array_length(whole_wire->'objects') IS DISTINCT FROM jsonb_array_length(guides) OR EXISTS(SELECT FROM jsonb_array_elements(guides) g WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(whole_wire->'objects') o WHERE o->>'point'=g->>'objectId' AND o->>'identityAgency'=g->>'identityAgency' AND o->>'li'=g->>'lineItemReference')) THEN RETURN jsonb_build_object('applied',false,'reason','prodat_mixed_whole_physical_scope_required');END IF;
 wire:=whole_wire||jsonb_build_object('objects',(SELECT jsonb_agg(o ORDER BY o->>'point') FROM jsonb_array_elements(whole_wire->'objects') o WHERE EXISTS(SELECT FROM jsonb_array_elements(guides) g WHERE g->>'objectId'=o->>'point' AND g->>'identityAgency'=o->>'identityAgency' AND g->>'disposition'='accepted')));

 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  OR jsonb_array_length(canonical.facts_text::jsonb#>'{registerValidation,objects}')<>jsonb_array_length(whole_wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'Z04',wire->'objects','[]',after_states,switch_ids,p_actor_user_id);
 result:=jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
 result:=result||jsonb_build_object('processedObjects',guides,'sourceMessageId',m.id,'sourcePayloadHash',guide.source_payload_hash,'companyId',m.company_id,'environment',m.environment,'objectFactsHash',guide.facts_hash);
 INSERT INTO gridex_received_sources.prodat_mixed_object_receipts(source_message_id,company_id,environment,source_payload_hash,assessment_id,object_facts_hash,processed_objects,result,actor_user_id) VALUES(m.id,m.company_id,m.environment,guide.source_payload_hash,canonical.id,guide.facts_hash,guides,result,p_actor_user_id);
 INSERT INTO gridex_received_sources.prodat_mixed_reply_outbox(source_message_id,company_id,environment,source_payload_hash,object_facts_hash,own_outcomes) VALUES(m.id,m.company_id,m.environment,guide.source_payload_hash,guide.facts_hash,guides);
 RETURN result;
END $$;

--
-- Name: normal_switch_confirm_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.normal_switch_confirm_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'normal_z04_replay_conflict';END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states,'switchIds',prior.qualified_switch_ids);
 END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  OR jsonb_array_length(canonical.facts_text::jsonb#>'{registerValidation,objects}')<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'Z04',wire->'objects','[]',after_states,switch_ids,p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
END $$;

--
-- Name: normal_switch_coverage_is_current_v1(uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.normal_switch_coverage_is_current_v1(p_company_id uuid, p_period_id uuid, p_switch_id uuid, p_source_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;finish timestamptz:=coalesce(p_end,p_start+interval '1 minute');
BEGIN
 b:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_start,finish);
 RETURN (b->>'qualified'='true' AND b->>'switchId'=p_switch_id::text AND b->>'initialSourceMessageId'=p_source_id::text AND (b->>'marketStartAt')::timestamptz=p_start AND (b->>'marketEndAt')::timestamptz IS NOT DISTINCT FROM p_end) IS TRUE;
END $$;

--
-- Name: normal_switch_scope_effect_v1(uuid, uuid, uuid, jsonb, uuid[], uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.normal_switch_scope_effect_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_scope jsonb, p_source_cohort uuid[], p_canonical_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE; IF gridex_received_sources.require_supply_scope_admission_v1(p_company_id,p_source_message_id,p_scope) IS DISTINCT FROM p_canonical_id THEN RAISE EXCEPTION 'supply_scoped_canonical_assessment_changed';END IF; IF jsonb_array_length(gridex_received_sources.require_prodat_application_objects_v1(p_company_id,p_source_message_id)->'objects')>1 THEN m.customer_id:=NULL;m.metering_point_id:=NULL;END IF;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'normal_z04_replay_conflict';END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states,'switchIds',prior.qualified_switch_ids);
 END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.id IS DISTINCT FROM p_canonical_id OR canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 wire:=gridex_received_sources.supply_wire_for_scope_v1(m.raw_payload,p_scope);
 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 IF EXISTS(SELECT FROM unnest(original_ids) id WHERE NOT(id=ANY(p_source_cohort))) THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point') AND(o->>'point' IS NULL OR o->>'identityAgency'=own->>'identityAgency'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  IF coalesce(sw.outbound_z03_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point') AND(o->>'point' IS NULL OR o->>'identityAgency'=own->>'identityAgency'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);

 RETURN jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'plans',plans,'previousStates','[]'::jsonb,'previousSwitches',before_switches,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
END $$;

--
-- Name: normal_switch_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.normal_switch_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w jsonb:=gridex_received_sources.supply_wire_v1(p_raw);tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);
 own jsonb;lin jsonb;objects jsonb:='[]';seen text[]:=ARRAY[]::text[];key text;
BEGIN
 IF w IS NULL OR tokens IS NULL THEN RETURN NULL;END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(w->'objects') o LOOP
  SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,1,0}'=own->>'line';
  IF lin IS NULL OR lin#>>'{elements,3,0}' IS DISTINCT FROM own->>'point' THEN RETURN NULL;END IF;
  key:=jsonb_build_array(own->>'point',lin#>>'{elements,3,3}')::text;
  IF key=ANY(seen) THEN CONTINUE;END IF;
  seen:=array_append(seen,key);
  objects:=objects||jsonb_build_array(own||jsonb_build_object('identityAgency',lin#>>'{elements,3,3}',
   'registerCount',(SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' AND t#>>'{elements,3,3}'=lin#>>'{elements,3,3}')));
 END LOOP;
 RETURN w||jsonb_build_object('objects',objects);
END $$;

--
-- Name: object_owner_before_normal_minute_v1(jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.object_owner_before_normal_minute_v1(p_party jsonb, p_business jsonb, p_received timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE identity jsonb:=p_party#>'{receiver,identity}'; evidence jsonb:=p_party#>'{receiver,evidence}';
 records jsonb:=evidence->'records'; facility jsonb:=p_party->'facility'; parties jsonb:=p_party->'parties';
 effective jsonb:=p_business->'effectiveFrom'; commit_row jsonb; name text; stamp text; instant timestamptz;
 party_start timestamptz; party_end timestamptz; evaluated timestamptz; role_values text[]; supplied_roles text[];
 actor_count bigint; identifier_count bigint; selected_actor_id uuid; legal_id text; relation_count bigint;
 relation_id uuid; transport_actor uuid; transport_id text; minute text; market_time timestamp; expected_day text;
BEGIN
 IF p_received IS NULL OR NOT isfinite(p_received)
  OR p_business->>'coverage' IS DISTINCT FROM 'committed_switch_and_supply_only'
  OR p_business->>'sourceDisposition' IS DISTINCT FROM 'not_established'
  OR p_business->>'graphNamespace' IS DISTINCT FROM 'legacy_unqualified'
  OR p_party->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR p_party->>'authentication' IS DISTINCT FROM 'not_assessed'
  OR evidence->'version' IS DISTINCT FROM '1'::jsonb
  OR evidence->>'owner' IS DISTINCT FROM 'canonical-tenant-ediel-identity-v1'
  OR evidence->>'consistency' IS DISTINCT FROM 'independent_reads'
  OR evidence->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR evidence->>'sourceDisposition' IS DISTINCT FROM 'not_established'
  OR facility->>'owner' IS DISTINCT FROM 'selected-facility-grid-owner-v1'
  OR facility->>'consistency' IS DISTINCT FROM 'independent_reads'
  OR facility->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR identity->>'companyId' IS DISTINCT FROM p_business->>'companyId'
  OR identity->>'environment' IS DISTINCT FROM p_business->>'environment'
  OR jsonb_typeof(identity->'representedByTransportAgent') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(identity->'roleCodes') IS DISTINCT FROM 'array'
  OR jsonb_typeof(parties) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 -- PostgreSQL's timestamp/date types own calendar parsing. Reject infinities,
 -- date-only spellings and excess fractional precision before typed equality.
 FOR stamp IN SELECT value FROM unnest(ARRAY[p_business->>'assessedAt',p_business->>'sourceReceivedAt',
  p_party#>>'{source,receivedAt}',p_party->>'assessedAt',p_party->>'completedAt',evidence->>'evaluatedAt',
  evidence->>'observedAt',evidence->>'completedAt',facility->>'observedAt',facility->>'completedAt']) value LOOP
  IF stamp IS NULL OR stamp !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RETURN false; END IF;
  instant:=stamp::timestamptz;
  IF NOT isfinite(instant) OR instant<p_received OR instant>statement_timestamp() THEN RETURN false; END IF;
 END LOOP;
 party_start:=(p_party->>'assessedAt')::timestamptz;party_end:=(p_party->>'completedAt')::timestamptz;evaluated:=(evidence->>'evaluatedAt')::timestamptz;
 IF (p_business->>'sourceReceivedAt')::timestamptz<>p_received OR (p_party#>>'{source,receivedAt}')::timestamptz<>p_received
  OR party_end<party_start OR evaluated<>party_start
  OR (evidence->>'observedAt')::timestamptz<evaluated OR (evidence->>'completedAt')::timestamptz<(evidence->>'observedAt')::timestamptz
  OR (evidence->>'completedAt')::timestamptz>party_end
  OR (facility->>'observedAt')::timestamptz<party_start OR (facility->>'completedAt')::timestamptz<(facility->>'observedAt')::timestamptz
  OR (facility->>'completedAt')::timestamptz>party_end THEN RETURN false; END IF;
 FOREACH name IN ARRAY ARRAY['legalSender','legalReceiver','transportSender','transportReceiver'] LOOP
  IF jsonb_typeof(parties->name) IS DISTINCT FROM 'string' OR length(parties->>name) NOT BETWEEN 1 AND 128
   OR parties->>name<>btrim(parties->>name) THEN RETURN false; END IF;
 END LOOP;
 -- Same half-open tenant validity used by resolveCanonicalTenantEdielIdentity.
 IF NOT EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.tenant_ediel_profiles,records->'profiles') r
  WHERE r.is_enabled AND r.market='electricity' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to)) THEN RETURN false; END IF;
 SELECT count(DISTINCT r.actor_id),count(DISTINCT nullif(btrim(r.identifier_value),'')),min(r.actor_id::text)::uuid,min(nullif(btrim(r.identifier_value),''))
 INTO actor_count,identifier_count,selected_actor_id,legal_id
 FROM jsonb_populate_recordset(NULL::public.tenant_actor_identifiers,records->'identifiers') r
 WHERE r.identifier_type='EdielId' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF actor_count<>1 OR identifier_count<>1 OR selected_actor_id::text IS DISTINCT FROM identity->>'legalActorId'
  OR legal_id IS DISTINCT FROM identity->>'legalEdielId' OR legal_id IS DISTINCT FROM parties->>'legalReceiver' THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT btrim(r.role_code) ORDER BY btrim(r.role_code)) INTO role_values
 FROM jsonb_populate_recordset(NULL::public.tenant_actor_roles,records->'roles') r
 WHERE r.actor_id=selected_actor_id AND nullif(btrim(r.role_code),'') IS NOT NULL AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF EXISTS(SELECT FROM jsonb_array_elements(identity->'roleCodes') r WHERE jsonb_typeof(r)<>'string') THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT value ORDER BY value) INTO supplied_roles FROM jsonb_array_elements_text(identity->'roleCodes');
 IF role_values IS DISTINCT FROM supplied_roles OR NOT coalesce('electricity_supplier'=ANY(role_values),false) THEN RETURN false; END IF;
 SELECT count(*),min(r.id::text)::uuid,min(r.counterparty_actor_id::text)::uuid INTO relation_count,relation_id,transport_actor
 FROM jsonb_populate_recordset(NULL::public.tenant_counterparty_relations,records->'relations') r
 WHERE r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF relation_count=0 THEN
  IF identity->'representedByTransportAgent'<>'false'::jsonb OR identity->'transportRelationId' IS DISTINCT FROM 'null'::jsonb
   OR identity->>'transportActorId' IS DISTINCT FROM selected_actor_id::text OR identity->>'transportEdielId' IS DISTINCT FROM legal_id
   OR records->'transportIdentifiers' IS DISTINCT FROM '[]'::jsonb THEN RETURN false; END IF;
 ELSE
  IF relation_count<>1 OR identity->'representedByTransportAgent'<>'true'::jsonb
   OR identity->>'transportRelationId' IS DISTINCT FROM relation_id::text OR identity->>'transportActorId' IS DISTINCT FROM transport_actor::text
   OR transport_actor=selected_actor_id THEN RETURN false; END IF;
  IF EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->'transportIdentifiers') r WHERE r.is_verified IS DISTINCT FROM true) THEN RETURN false; END IF;
  SELECT count(DISTINCT nullif(btrim(r.identifier_value),'')),min(nullif(btrim(r.identifier_value),'')) INTO identifier_count,transport_id
  FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->'transportIdentifiers') r
  WHERE r.actor_id=transport_actor AND r.identifier_type='EdielId'
   AND (r.valid_from IS NULL OR r.valid_from::timestamp AT TIME ZONE 'UTC'<=evaluated)
   AND (r.valid_to IS NULL OR evaluated<r.valid_to::timestamp AT TIME ZONE 'UTC');
  IF identifier_count<>1 OR transport_id=legal_id OR transport_id IS DISTINCT FROM identity->>'transportEdielId' THEN RETURN false; END IF;
 END IF;
 IF parties->>'transportReceiver' IS DISTINCT FROM identity->>'transportEdielId'
  OR parties->>'transportSender' IS DISTINCT FROM parties->>'legalSender'
  OR parties->>'legalSender' IS DISTINCT FROM facility#>>'{gridOwner,ediel_id}'
  OR facility#>'{gridOwner,is_active}' IS DISTINCT FROM 'true'::jsonb OR facility#>>'{gridOwner,lifecycle_status}' IS DISTINCT FROM 'active'
  OR facility#>>'{gridOwner,environment}' IS DISTINCT FROM p_business->>'environment'
  OR (p_business->>'environment'='production' AND facility#>>'{gridOwner,ediel_id}' IN ('91100','91109'))
  OR facility#>>'{meteringPoint,meter_point_id}' IS DISTINCT FROM p_business#>>'{object,objectId}'
  OR facility#>>'{site,facility_id}' IS DISTINCT FROM p_business#>>'{object,objectId}'
  OR facility#>>'{meteringPoint,site_id}' IS DISTINCT FROM facility#>>'{site,id}'
  OR (facility#>'{meteringPoint,customer_site_id}'<>'null'::jsonb AND facility#>>'{meteringPoint,customer_site_id}' IS DISTINCT FROM facility#>>'{site,id}')
  OR facility#>>'{meteringPoint,grid_owner_id}' IS DISTINCT FROM facility#>>'{gridOwner,id}'
  OR facility#>>'{site,grid_owner_id}' IS DISTINCT FROM facility#>>'{gridOwner,id}' THEN RETURN false; END IF;
 IF jsonb_typeof(effective) IS DISTINCT FROM 'object' OR effective->>'fieldNumber' IS DISTINCT FROM '210'
  OR effective->>'committedDatePrecision' IS DISTINCT FROM 'market_calendar_day'
  OR effective-ARRAY['fieldNumber','marketMinute','utc','committedDatePrecision']<>'{}'::jsonb THEN RETURN false; END IF;
 minute:=effective->>'marketMinute';
 IF minute IS NULL OR minute !~ '^[0-9]{12}$' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;
 market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);
 IF effective->>'utc' IS NULL OR (effective->>'utc')::timestamptz IS DISTINCT FROM (market_time AT TIME ZONE 'Etc/GMT-1') THEN RETURN false; END IF;
 expected_day:=to_char(market_time,'YYYY-MM-DD');
 FOREACH name IN ARRAY ARRAY['switch','supply'] LOOP
  commit_row:=p_business#>ARRAY['committedRecords',name];
  IF jsonb_typeof(commit_row) IS DISTINCT FROM 'object'
   OR commit_row->>'id' IS DISTINCT FROM p_business->>(CASE WHEN name='switch' THEN 'switchRequestId' ELSE 'supplyPeriodId' END)
   OR commit_row->>'companyId' IS DISTINCT FROM p_business->>'companyId'
   OR commit_row->>'customerId' IS DISTINCT FROM p_business->>'customerId'
   OR commit_row->>'meteringPointId' IS DISTINCT FROM p_business->>'meteringPointId'
   OR commit_row->>'sourceMessageId' IS DISTINCT FROM p_business->>'sourceMessageId'
   OR commit_row->>'status' IS DISTINCT FROM (CASE WHEN name='switch' THEN 'accepted' ELSE 'confirmed_by_grid_owner' END)
   OR commit_row->>(CASE WHEN name='switch' THEN 'confirmedStartDate' ELSE 'startDate' END) IS DISTINCT FROM expected_day
   OR (name='switch' AND commit_row->>'siteId' IS DISTINCT FROM p_business->>'siteId') THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $_$;

--
-- Name: object_owner_proof_consistent(jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.object_owner_proof_consistent(p_party jsonb, p_business jsonb, p_received timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;legacy_shape jsonb;
BEGIN
 IF p_business#>>'{effectiveFrom,committedDatePrecision}' IS DISTINCT FROM 'market_minute' THEN RETURN gridex_received_sources.object_owner_before_normal_minute_v1(p_party,p_business,p_received);END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=(p_business->>'supplyPeriodId')::uuid AND company_id=(p_business->>'companyId')::uuid AND source_message_id=(p_business->>'sourceMessageId')::uuid AND switch_id=(p_business->>'switchRequestId')::uuid;
 IF NOT FOUND OR p_business->>'owner' IS DISTINCT FROM 'inbound-z04-switch-confirmation-v1' OR p_business->>'sourcePayloadHash' IS DISTINCT FROM (SELECT payload_hash FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=proof.company_id)
  OR p_business#>>'{object,objectId}' IS DISTINCT FROM proof.source_object->>'point' OR p_business#>>'{object,identityAgency}' IS DISTINCT FROM proof.source_object->>'identityAgency'
  OR p_business->>'customerId' IS DISTINCT FROM proof.confirmed_period->>'customer_id' OR p_business->>'meteringPointId' IS DISTINCT FROM proof.confirmed_period->>'metering_point_id' OR p_business->>'siteId' IS DISTINCT FROM coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id')
  OR p_business#>>'{effectiveFrom,marketMinute}' IS DISTINCT FROM proof.source_object->>'start' OR (p_business#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM proof.market_start_at
  OR p_party#>>'{receiver,identity,legalActorId}' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR p_party#>>'{parties,legalReceiver}' IS DISTINCT FROM proof.legal_context->>'legalEdielId' THEN RETURN false;END IF;
 -- Reuse every existing source-party snapshot, scope, UTC and DATE-projection
 -- check. This local copy is only the legacy checker input; stored output and
 -- authoritative market timestamp remain precise and unchanged.
 legacy_shape:=jsonb_set(p_business,'{effectiveFrom,committedDatePrecision}','"market_calendar_day"');
 RETURN gridex_received_sources.object_owner_before_normal_minute_v1(p_party,legacy_shape,p_received) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $$;

--
-- Name: observe_document_reference_v1(uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.observe_document_reference_v1(p_company_id uuid, p_environment text, p_attempt_id uuid, p_actor_user_id uuid, p_observation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE a gridex_received_sources.document_reference_attempts%rowtype; o gridex_received_sources.document_reference_outcomes%rowtype;
 current_facts jsonb; observed jsonb:=p_observation; started timestamptz; completed timestamptz;
BEGIN
 PERFORM gridex_received_sources.document_reference_actor_v1(p_company_id,p_actor_user_id);
 SELECT * INTO a FROM gridex_received_sources.document_reference_attempts WHERE id=p_attempt_id AND company_id=p_company_id AND environment=p_environment AND actor_user_id=p_actor_user_id AND created_xid<>pg_current_xact_id();
 IF a.id IS NULL THEN RAISE EXCEPTION 'document_attempt_not_committed' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(observed) IS DISTINCT FROM 'object' OR octet_length(observed::text)>8192
 OR NOT observed ?& ARRAY['status','startedAt','completedAt','byteCount']
 OR EXISTS(SELECT FROM jsonb_object_keys(observed) k WHERE k NOT IN ('status','reason','startedAt','completedAt','byteCount','sha256'))
 OR observed->>'status' IS NULL OR observed->>'status' NOT IN ('verified_at_observation','unavailable')
 OR jsonb_typeof(observed->'byteCount') IS DISTINCT FROM 'number' OR observed->>'byteCount' !~ '^[0-9]+$'
 OR (observed->>'byteCount')::numeric>9007199254740991
 OR ((observed->>'byteCount')::numeric>2097152 AND observed->>'reason' IS DISTINCT FROM 'oversize') THEN RAISE EXCEPTION 'invalid_document_observation' USING ERRCODE='23514'; END IF;
 IF observed->>'startedAt' IS NOT NULL OR observed->>'completedAt' IS NOT NULL THEN
 started:=(observed->>'startedAt')::timestamptz;completed:=(observed->>'completedAt')::timestamptz;
 IF started IS NULL OR completed IS NULL OR NOT isfinite(started) OR NOT isfinite(completed) OR completed<started OR started<date_trunc('milliseconds',a.recorded_at) OR completed>clock_timestamp()+interval '1 second'
 THEN RAISE EXCEPTION 'invalid_document_observation_time' USING ERRCODE='23514'; END IF;
 END IF;
 IF observed->>'status'='verified_at_observation' AND (started IS NULL OR completed-started>interval '10 seconds' OR observed->>'sha256' IS DISTINCT FROM a.facts#>>'{document,document_sha256}' OR observed ? 'reason' OR a.facts->'eligible'<>'true'::jsonb)
 THEN RAISE EXCEPTION 'invalid_document_verified_observation' USING ERRCODE='23514'; END IF;
 IF observed->>'status'='unavailable' AND (observed ? 'sha256' OR observed->>'reason' IS NULL OR observed->>'reason' NOT IN ('ineligible_document','oversize','timeout','hash_mismatch','storage_error','unresolved_link'))
 THEN RAISE EXCEPTION 'invalid_document_unavailable_observation' USING ERRCODE='23514'; END IF;
 BEGIN current_facts:=gridex_received_sources.document_reference_facts_v1(p_company_id,p_environment,a.source_message_id,a.document_id);
 EXCEPTION WHEN insufficient_privilege THEN current_facts:=NULL; END;
 IF current_facts IS DISTINCT FROM a.facts THEN observed:=observed||jsonb_build_object('status','unavailable','reason','graph_changed'); END IF;
 INSERT INTO gridex_received_sources.document_reference_outcomes(attempt_id,company_id,environment,status,observation,facts_hash)
 VALUES(a.id,a.company_id,a.environment,observed->>'status',observed,encode(sha256(convert_to(observed::text,'UTF8')),'hex')) RETURNING * INTO o;
 RETURN jsonb_build_object('attemptId',a.id,'outcomeId',o.id,'factsHash',o.facts_hash,'status',o.status);
END $_$;

--
-- Name: open_object_selection_snapshot(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.open_object_selection_snapshot(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE observed timestamptz:=clock_timestamp(); body jsonb; snap text; bytes text; digest text; result_id uuid;
BEGIN
 IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production')
 OR p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff>observed THEN RAISE EXCEPTION 'source_selection_scope_unavailable' USING ERRCODE='22023'; END IF;
 -- Count, limits, payloads, all immutable decisions and witnesses are read in
 -- ONE MVCC statement. Overflows return an explicit incomplete empty readset.
 WITH candidates AS MATERIALIZED (
  SELECT s.source_message_id,octet_length(s.raw_payload) AS payload_bytes FROM gridex_received_sources.sources s
  WHERE s.company_id=p_company_id AND s.environment=p_environment AND s.captured_at<=p_cutoff
   AND (s.source_received_at IS NULL OR s.source_received_at<=p_cutoff) ORDER BY s.source_message_id LIMIT 1001
 ), assessments AS MATERIALIZED (
  SELECT a.id,a.source_message_id,octet_length(a.facts_text) AS fact_bytes FROM candidates s
  CROSS JOIN LATERAL(SELECT a.id,a.source_message_id,a.facts_text FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=s.source_message_id ORDER BY a.assessed_at,a.id LIMIT 129)a
 ), totals AS (
  SELECT (SELECT count(*) FROM candidates) AS n,
   (SELECT coalesce(sum(payload_bytes),0) FROM candidates)+(SELECT coalesce(sum(fact_bytes),0) FROM assessments) AS total_bytes,
   (SELECT coalesce(max(payload_bytes),0) FROM candidates) AS max_payload,
   (SELECT coalesce(max(n),0) FROM (SELECT count(*) AS n FROM assessments GROUP BY source_message_id)c) AS max_assessments
 ), bounded AS (SELECT *,n<=1000 AND total_bytes<=6291456 AND max_payload<=262144 AND max_assessments<=128 AS complete FROM totals)
 SELECT jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,'cutoffAt',p_cutoff,
  'capturedAt',observed,'complete',b.complete,'sourceCount',b.n,'historyCoverage','before_ledger_unknown',
  'ledgerStartedAt',(SELECT opened_at FROM gridex_received_sources.epoch WHERE singleton),
  'sources',CASE WHEN b.complete THEN (SELECT coalesce(jsonb_agg(jsonb_build_object(
   'sourceMessageId',s.source_message_id,'payloadHash',s.payload_hash,'rawPayload',s.raw_payload,
   'receivedAt',s.source_received_at,'capturedAt',s.captured_at,'messageCode',s.message_code,
   'assessments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'previousAssessmentId',a.previous_assessment_id,
    'canonicalAssessmentId',a.canonical_assessment_id,'assessedAt',a.assessed_at,
    'availableAt',w.observed_at,'availabilityWitnessId',w.id,'factsText',a.facts_text,'factsHash',a.facts_hash) ORDER BY a.assessed_at,a.id),'[]'::jsonb)
    FROM assessments list JOIN gridex_received_sources.object_assessments a ON a.id=list.id
    LEFT JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id AND w.company_id=a.company_id AND w.environment=a.environment AND w.facts_hash=a.facts_hash
    WHERE list.source_message_id=s.source_message_id)) ORDER BY s.source_message_id),'[]'::jsonb)
   FROM candidates c JOIN gridex_received_sources.sources s USING(source_message_id)) ELSE '[]'::jsonb END),pg_current_snapshot()::text
 INTO body,snap FROM bounded b;
 bytes:=body::text;
 -- JSON escaping/metadata may expand beyond the summed input budget.
 IF octet_length(bytes)>8388608 THEN body:=jsonb_set(jsonb_set(body,'{complete}','false'),'{sources}','[]');bytes:=body::text; END IF;
 digest:=encode(sha256(convert_to(bytes,'UTF8')),'hex');
 INSERT INTO gridex_received_sources.object_selection_snapshots(company_id,environment,cutoff_at,captured_at,readset_text,readset_hash,visibility_snapshot)
 VALUES(p_company_id,p_environment,p_cutoff,observed,bytes,digest,snap) RETURNING id INTO result_id;
 RETURN jsonb_build_object('snapshotId',result_id,'readsetText',bytes,'readsetHash',digest);
END $$;

--
-- Name: open_snapshot(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.open_snapshot(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE v_now timestamptz := clock_timestamp(); v_opened timestamptz;
  v_result jsonb; v_manifest jsonb; v_id uuid; v_hash text;
BEGIN
  IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production')
    OR p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff > v_now THEN
    RAISE EXCEPTION 'received_source_scope_unavailable' USING ERRCODE = '22023';
  END IF;
  SELECT opened_at INTO STRICT v_opened FROM gridex_received_sources.epoch WHERE singleton;
  -- Count, byte budgets and ALL returned rows share one MVCC statement snapshot.
  -- A 1001 count is an overflow sentinel, not an asserted universe size. No
  -- physical-object link or mutable message state participates in discovery.
  WITH candidates AS MATERIALIZED (
    SELECT source_message_id, octet_length(raw_payload) AS payload_bytes
    FROM gridex_received_sources.sources
    WHERE company_id=p_company_id AND environment=p_environment
      AND captured_at<=p_cutoff AND (source_received_at IS NULL OR source_received_at<=p_cutoff)
    LIMIT 1001
  ), totals AS (
    SELECT count(*) AS n, coalesce(sum(payload_bytes),0) AS total_bytes, coalesce(max(payload_bytes),0) AS max_bytes FROM candidates
  )
  SELECT jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,
    'cutoffAt',p_cutoff,'openedAt',v_opened,'readAt',v_now,'sourceCount',totals.n,
    'exhaustive',totals.n<=1000 AND totals.total_bytes<=4194304 AND totals.max_bytes<=262144,
    'sources', CASE WHEN totals.n<=1000 AND totals.total_bytes<=4194304 AND totals.max_bytes<=262144 THEN
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'sourceMessageId',source.source_message_id,'companyId',source.company_id,'environment',source.environment,
        'origin',source.origin,'messageCode',source.message_code,'sourceReceivedAt',source.source_received_at,
        'capturedAt',source.captured_at,'rawPayload',source.raw_payload,'payloadHash',source.payload_hash,
        'receivedContext',source.received_context) ORDER BY source.source_message_id),'[]'::jsonb)
      FROM candidates JOIN gridex_received_sources.sources AS source USING(source_message_id)) ELSE '[]'::jsonb END,
    'visibilitySnapshot',pg_current_snapshot()::text) INTO v_result FROM totals;
  -- The exact read set is fixed NOW, not reconstructed in a later client query.
  -- No raw payload copy in the manifest; immutable source identity/hash binds it.
  SELECT (v_result-'sources'-'visibilitySnapshot') || jsonb_build_object('sources',coalesce(jsonb_agg(
    (value - ARRAY['rawPayload','receivedContext','origin','messageCode','companyId','environment']) || jsonb_build_object('receiptContextRecorded',coalesce(jsonb_typeof(value->'receivedContext')='object',false))
    ORDER BY value->>'sourceMessageId'),'[]'::jsonb))
    INTO v_manifest FROM jsonb_array_elements(v_result->'sources');
  v_hash := encode(sha256(convert_to(v_manifest::text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.snapshots(company_id,environment,manifest,manifest_hash,visibility_snapshot)
    VALUES(p_company_id,p_environment,v_manifest,v_hash,v_result->>'visibilitySnapshot') RETURNING id INTO v_id;
  RETURN (v_result-'visibilitySnapshot') || jsonb_build_object('snapshotId',v_id,'snapshotHash',v_hash);
END $$;

--
-- Name: other_supply_scope_effect_v1(uuid, uuid, uuid, jsonb, uuid[], uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.other_supply_scope_effect_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_scope jsonb, p_source_cohort uuid[], p_canonical_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;sender_basis jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';previous_switches jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE; IF gridex_received_sources.require_supply_scope_admission_v1(p_company_id,p_source_message_id,p_scope) IS DISTINCT FROM p_canonical_id THEN RAISE EXCEPTION 'supply_scoped_canonical_assessment_changed';END IF; IF jsonb_array_length(gridex_received_sources.require_prodat_application_objects_v1(p_company_id,p_source_message_id)->'objects')>1 THEN m.customer_id:=NULL;m.metering_point_id:=NULL;END IF;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.id=p_canonical_id AND v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason OR nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);
 END IF;
 -- Only a first Z05/C restoration requires today's actual sender registry.
 -- Historical recorded outcomes returned above retain their original truth.
 IF wire->>'code'='Z05' AND reason='Z24' THEN
  sender_basis:=gridex_network_registry_sources.network_for_company_v1(m.company_id,wire->>'sender',m.environment);
  IF sender_basis->>'status' IS DISTINCT FROM 'authorized'
   OR sender_basis#>>'{basis,companyId}' IS DISTINCT FROM m.company_id::text
   OR sender_basis#>>'{basis,environment}' IS DISTINCT FROM m.environment
   OR sender_basis#>>'{basis,networkEdielId}' IS DISTINCT FROM wire->>'sender'
   THEN RETURN jsonb_build_object('applied',false,'reason','z05c_current_sender_network_registry_required');END IF;
 END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   IF coalesce(sw.outbound_z03_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(m.company_id,origin.id,sp.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload));
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   previous_switches:=previous_switches||jsonb_build_array(to_jsonb(sw));plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->>'sender'=wire->>'sender' AND coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->>'receiver'=wire->>'receiver' AND EXISTS(SELECT FROM jsonb_array_elements(coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->'objects') original_scope WHERE original_scope->>'point'=own->>'point' AND original_scope->>'identityAgency'=own->>'identityAgency')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   IF coalesce(sp.source_end_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text AND(state#>>'{metadata,sourceObject,point}'=own->>'point' OR state#>>'{metadata,normalSourceBasis,object,point}'=own->>'point'))
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND (object->>'reason' IN ('Z26','Z70') OR object->>'reason' IN ('Z22','Z23') AND EXISTS(SELECT FROM gridex_received_sources.supply_object_effect_receipts own_effect WHERE own_effect.company_id=p.company_id AND own_effect.source_message_id=tr.source_message_id AND own_effect.object_scope->>'objectId'=own->>'point' AND own_effect.object_scope->>'identityAgency'=own->>'identityAgency' AND gridex_received_sources.supply_effect_assessment_owns_period_v1(p.company_id,tr.source_message_id,p.id,own_effect.canonical_assessment_id)))))
    );
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   IF coalesce(sp.source_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(m.company_id,origin.id,sp.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload));
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (chosen_plan->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen_plan);

 RETURN jsonb_build_object('applied',true,'periods',after_states,'plans',plans,'previousStates',before_states,'previousSwitches',previous_switches,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;

--
-- Name: outbound_single_brp_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.outbound_single_brp_v1(raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE token jsonb;active_object boolean:=false;brp text;lines integer:=0;
BEGIN
 FOR token IN SELECT item FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(raw)) item LOOP
  IF token->>'tag'='LIN' THEN lines:=lines+1;active_object:=true;CONTINUE;END IF;
  IF token->>'tag'='UNT' THEN active_object:=false;END IF;
  IF active_object AND token->>'tag'='NAD' AND token#>>'{elements,1,0}'='Z02' THEN
   IF brp IS NOT NULL OR token#>>'{elements,2,1}' IS DISTINCT FROM '160' OR token#>>'{elements,2,2}' IS DISTINCT FROM 'SVK' OR jsonb_array_length(token#>'{elements,2}') IS DISTINCT FROM 3 THEN RETURN NULL;END IF;
   brp:=token#>>'{elements,2,0}';
   IF nullif(brp,'') IS NULL OR brp<>btrim(brp) OR length(brp)>35 OR brp~'[[:cntrl:]]' THEN RETURN NULL;END IF;
  END IF;
 END LOOP;
 IF lines<>1 THEN RETURN NULL;END IF;RETURN brp;
END$$;

--
-- Name: owner_rows_match(text, jsonb, uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.owner_rows_match(p_kind text, p_rows jsonb, p_company uuid, p_environment text, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE relation_name text; columns_text text; predicate_text text; matches boolean;
BEGIN
 IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows)>8192 THEN RETURN false; END IF;
 CASE p_kind
 WHEN 'profiles' THEN relation_name:='tenant_ediel_profiles'; columns_text:='id,company_id,environment,market,is_enabled,valid_from,valid_to'; predicate_text:='company_id=$2 AND environment=$3 AND market=''electricity'' AND is_enabled';
 WHEN 'identifiers' THEN relation_name:='tenant_actor_identifiers'; columns_text:='id,company_id,environment,actor_id,identifier_type,identifier_value,qualifier,subaddress,valid_from,valid_to'; predicate_text:='company_id=$2 AND environment=$3 AND identifier_type=''EdielId''';
 WHEN 'roles' THEN relation_name:='tenant_actor_roles'; columns_text:='id,company_id,environment,actor_id,role_code,valid_from,valid_to'; predicate_text:='company_id=$2 AND environment=$3 AND actor_id=$4';
 WHEN 'relations' THEN relation_name:='tenant_counterparty_relations'; columns_text:='id,company_id,environment,counterparty_actor_id,relation_type,is_enabled,valid_from,valid_to'; predicate_text:='company_id=$2 AND environment=$3 AND relation_type=''ediel_transport_agent'' AND is_enabled';
 WHEN 'transportIdentifiers' THEN relation_name:='platform_actor_identifiers'; columns_text:='id,actor_id,identifier_type,identifier_value,id_code_qualifier,id_code_responsible,source,is_verified,valid_from,valid_to,created_at,updated_at'; predicate_text:='actor_id=$4 AND identifier_type=''EdielId''';
 WHEN 'point' THEN relation_name:='metering_points'; columns_text:='id,company_id,meter_point_id,site_id,customer_site_id,grid_owner_id'; predicate_text:='company_id=$2 AND id=$4';
 WHEN 'site' THEN relation_name:='customer_sites'; columns_text:='id,company_id,facility_id,grid_owner_id'; predicate_text:='company_id=$2 AND id=$4';
 WHEN 'gridOwner' THEN relation_name:='grid_owners'; columns_text:='id,name,ediel_id,is_active,lifecycle_status,default_prodat_subaddress,default_utilts_subaddress,communication_email,email,environment'; predicate_text:='id=$4';
 ELSE RETURN false;
 END CASE;
 EXECUTE format('SELECT NOT EXISTS((SELECT %1$s FROM public.%2$I WHERE %3$s EXCEPT ALL SELECT %1$s FROM jsonb_populate_recordset(NULL::public.%2$I,$1)) UNION ALL (SELECT %1$s FROM jsonb_populate_recordset(NULL::public.%2$I,$1) EXCEPT ALL SELECT %1$s FROM public.%2$I WHERE %3$s))',columns_text,relation_name,predicate_text)
 INTO matches USING p_rows,p_company,p_environment,p_actor;
 RETURN matches;
END $_$;

--
-- Name: permission_date_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.permission_date_v1(p_value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result date;
BEGIN
 IF p_value IS NULL THEN RETURN NULL; END IF;
 IF p_value !~ '^[0-9]{8}([0-9]{4}([+-][0-9]{4})?)?$' THEN RETURN NULL; END IF;
 result:=to_date(substr(p_value,1,8),'YYYYMMDD');
 IF to_char(result,'YYYYMMDD')<>substr(p_value,1,8) THEN RETURN NULL; END IF;
 RETURN result;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $_$;

--
-- Name: permission_partition_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.permission_partition_wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;e jsonb;w jsonb:='{}';objects jsonb:='[]';physical jsonb:='[]';obj jsonb;prior jsonb;key text;field_value text;characteristic text;seen text[]:=ARRAY[]::text[];fingerprint text;field text;BEGIN
 IF tokens IS NULL OR(SELECT count(*) FROM jsonb_array_elements(tokens)token WHERE token->>'tag'='UNH')<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens)token WHERE token->>'tag'='BGM')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(tokens)ORDER BY(value->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='UNH' THEN w:=w||jsonb_build_object('messageReference',e#>>'{1,0}','family',e#>>'{2,0}');END IF;
  IF t->>'tag'='BGM' THEN w:=w||jsonb_build_object('code',e#>>'{1,0}');END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF w ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;END IF;
   w:=w||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
   obj:=jsonb_build_object('point',nullif(e#>>'{3,0}',''),'identityAgency',nullif(e#>>'{3,3}',''),'line',e#>>'{1,0}','firstLineIndex',t->'index','lineIndexes',jsonb_build_array(t->'index'));characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;field_value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN('LI','Z09','Z05') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z09' THEN 'permissionId' ELSE 'gridArea' END;field_value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';field_value:=e#>>'{2,0}';
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN('90','91','693','164') THEN
    key:=CASE e#>>'{1,0}' WHEN '90' THEN 'reportStart' WHEN '91' THEN 'reportEnd' WHEN '693' THEN 'permissionTime' ELSE 'permissionEnd' END;field_value:=e#>>'{1,1}';IF(e#>>'{1,2}' IN('102','203','303')) IS NOT TRUE THEN obj:=obj||'{"projectionHeld":true}';END IF;
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' WHEN 'Z24' THEN 'purpose' WHEN 'Z25' THEN 'endReason' WHEN 'Z12' THEN 'frequency' WHEN 'Z14' THEN 'product' END;field_value:=CASE characteristic WHEN 'Z12' THEN e#>>'{1,3}' WHEN 'Z14' THEN e#>>'{1,4}' ELSE e#>>'{1,0}' END;
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN obj:=obj||'{"projectionHeld":true}';END IF;obj:=obj||jsonb_build_object(key,nullif(field_value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 IF w->>'family' IS DISTINCT FROM 'PRODAT' OR(w->>'code' IN('Z13','Z14','Z15','Z18')) IS NOT TRUE OR nullif(w->>'sender','') IS NULL OR nullif(w->>'receiver','') IS NULL OR jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 -- Repeated register fragments belong to one physical installation. Every
 -- present consumed common value must equal its first physical occurrence.
 FOR obj IN SELECT value FROM jsonb_array_elements(objects) LOOP
  fingerprint:=jsonb_build_array(obj->'point',obj->'identityAgency',CASE WHEN obj->>'point' IS NULL THEN obj->'firstLineIndex' ELSE NULL END)::text;
  IF fingerprint=ANY(seen) THEN
   SELECT x INTO prior FROM jsonb_array_elements(physical)x WHERE x->'point' IS NOT DISTINCT FROM obj->'point' AND x->'identityAgency' IS NOT DISTINCT FROM obj->'identityAgency';
   FOREACH field IN ARRAY ARRAY['li','permissionId','gridArea','customerIdentity','reportStart','reportEnd','permissionTime','permissionEnd','reason','status','purpose','endReason','frequency','product'] LOOP IF obj ? field AND obj->field IS DISTINCT FROM prior->field THEN prior:=prior||'{"projectionHeld":true}';END IF;END LOOP;
   prior:=prior||jsonb_build_object('lineIndexes',prior->'lineIndexes'||obj->'lineIndexes');IF obj->>'projectionHeld'='true' THEN prior:=prior||'{"projectionHeld":true}';END IF;
   SELECT jsonb_agg(CASE WHEN x->>'firstLineIndex'=prior->>'firstLineIndex' THEN prior ELSE x END ORDER BY ord) INTO physical FROM jsonb_array_elements(physical)WITH ORDINALITY e(x,ord);
  ELSE seen:=array_append(seen,fingerprint);physical:=physical||jsonb_build_array(obj);END IF;
 END LOOP;
 RETURN w||jsonb_build_object('objects',physical);
END$$;

--
-- Name: permission_time_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.permission_time_v1(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result timestamptz; value text;
BEGIN
 IF p_value IS NULL OR p_value !~ '^[0-9]{12}$' OR gridex_received_sources.permission_date_v1(p_value) IS NULL THEN RETURN NULL; END IF;
 value:=substr(p_value,1,4)||'-'||substr(p_value,5,2)||'-'||substr(p_value,7,2)||'T'||substr(p_value,9,2)||':'||substr(p_value,11,2)||':00+01:00';
 result:=value::timestamptz;
 RETURN result;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $_$;

--
-- Name: permission_transition_immutable_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.permission_transition_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'permission_transition_is_immutable' USING ERRCODE='55000'; END $$;

--
-- Name: permission_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.permission_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w jsonb:=gridex_received_sources.permission_partition_wire_v1(p_raw);BEGIN IF w IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(w->'objects')x WHERE x->>'projectionHeld'='true') THEN RETURN NULL;END IF;RETURN w;END$$;

--
-- Name: prelock_recovery_candidate_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prelock_recovery_candidate_v1(c uuid, original_id uuid, ack_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE previous_op uuid;cohort uuid[];current_cohort uuid[];ids uuid[];
BEGIN
 SELECT link.operation_id INTO previous_op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations op ON op.id=link.operation_id WHERE link.message_id=original_id AND op.company_id=c;
 cohort:=CASE WHEN previous_op IS NULL THEN '{}'::uuid[] ELSE gridex_received_sources.recovery_source_cohort_v1(c,previous_op) END;
 ids:=array_append(cohort,original_id);IF ack_id IS NOT NULL THEN ids:=array_append(ids,ack_id);END IF;
 PERFORM 1 FROM public.ediel_messages m WHERE m.company_id=c AND m.id=ANY(ids) ORDER BY m.id FOR UPDATE;
 IF previous_op IS NOT NULL THEN
  current_cohort:=gridex_received_sources.recovery_source_cohort_v1(c,previous_op);
  IF current_cohort IS DISTINCT FROM cohort THEN RAISE EXCEPTION 'prodat_recovery_source_cohort_changed' USING ERRCODE='40001';END IF;
 END IF;
END$$;

--
-- Name: prelock_recovery_source_cohort_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prelock_recovery_source_cohort_v1(c uuid, op_id uuid, corrected_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cohort uuid[]:=gridex_received_sources.recovery_source_cohort_v1(c,op_id);all_ids uuid[];
BEGIN
 IF cohort IS NULL THEN RETURN;END IF;
 all_ids:=CASE WHEN corrected_id IS NULL THEN cohort ELSE array_append(cohort,corrected_id) END;
 PERFORM 1 FROM public.ediel_messages m WHERE m.company_id=c AND m.id=ANY(all_ids) ORDER BY m.id FOR UPDATE;
 IF gridex_received_sources.recovery_source_cohort_v1(c,op_id) IS DISTINCT FROM cohort THEN RAISE EXCEPTION 'prodat_recovery_source_cohort_changed' USING ERRCODE='40001';END IF;
 IF(SELECT count(DISTINCT m.id) FROM public.ediel_messages m WHERE m.company_id=c AND m.id=ANY(all_ids)) IS DISTINCT FROM (SELECT count(DISTINCT x) FROM unnest(all_ids) x) THEN RAISE EXCEPTION 'prodat_recovery_source_cohort_unavailable';END IF;
END$$;

--
-- Name: prodat_application_object_accepted_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_application_object_accepted_v1(c uuid, source_id uuid, canonical_id uuid, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE facet jsonb;
BEGIN
 facet:=gridex_received_sources.require_prodat_application_objects_v1(c,source_id);
 RETURN facet->>'headerDecision'='accepted' AND facet->>'assessmentId'=canonical_id::text
  AND EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')e WHERE e->>'applicationDecision'='accepted' AND e-'applicationDecision'-'reasonCodes'=object_scope);
END $$;

--
-- Name: prodat_first_register_characteristic_v1(text, jsonb, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_first_register_characteristic_v1(raw text, scope jsonb, qualifier text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);first_register jsonb:=scope#>'{registers,0}';lin jsonb;t jsonb;next_token jsonb;start_index integer;end_index integer;answer text;matches integer:=0;
BEGIN
 IF tokens IS NULL OR jsonb_typeof(scope->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(scope->'registers')=0 OR first_register->>'registerPosition' IS DISTINCT FROM '1' THEN RETURN NULL;END IF;
 start_index:=(first_register->>'segmentIndex')::integer;
 SELECT x INTO lin FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer=start_index;
 IF lin->>'tag' IS DISTINCT FROM 'LIN' OR lin#>>'{elements,3,0}' IS DISTINCT FROM scope->>'objectId' OR lin#>>'{elements,3,3}' IS DISTINCT FROM scope->>'identityAgency' OR lin#>>'{elements,1,0}' IS DISTINCT FROM first_register->>'lineNumber' THEN RETURN NULL;END IF;
 SELECT min((x->>'index')::integer) INTO end_index FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>start_index AND x->>'tag' IN('LIN','UNT','UNZ','UNH');
 IF end_index IS NULL THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>start_index AND(x->>'index')::integer<end_index AND x->>'tag'='CCI' AND x#>>'{elements,2,0}'=qualifier LOOP
  matches:=matches+1;SELECT x INTO next_token FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer=(t->>'index')::integer+1;
  IF next_token->>'tag' IS DISTINCT FROM 'CAV' THEN RETURN NULL;END IF;answer:=next_token#>>'{elements,1,0}';
 END LOOP;
 RETURN CASE WHEN matches=1 THEN nullif(answer,'') ELSE NULL END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END $$;

--
-- Name: prodat_recovery_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_recovery_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNT')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='UNZ')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='UNB' THEN out:=out||jsonb_build_object('interchange',e#>>'{5,0}','transportSender',e#>'{2}','transportReceiver',e#>'{3}');END IF;
  IF t->>'tag'='UNH' THEN out:=out||jsonb_build_object('family',e#>>'{2,0}','messageReference',e#>>'{1,0}','version',e#>'{2}');END IF;
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}','function',e#>>'{3,0}');END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'legalSender' ELSE 'legalReceiver' END;IF out ? key THEN RETURN NULL;END IF;out:=out||jsonb_build_object(key,e#>>'{2,0}');END IF;
  IF t->>'tag'='LIN' THEN IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;obj:=jsonb_build_object('point',nullif(e#>>'{3,0}', ''),'identityAgency',e#>>'{3,3}');characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}'='LI' THEN key:='li';value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' AND characteristic='Z13' THEN key:='reason';value:=e#>>'{1,0}';END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL;END IF;obj:=obj||jsonb_build_object(key,value);END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]'::jsonb) INTO objects FROM jsonb_array_elements(objects) x;
 RETURN out||jsonb_build_object('objects',objects,'tokens',tokens);
END $$;

--
-- Name: prodat_response_before_domain_effects_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_response_before_domain_effects_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_received_sources.customer_primary_response_receipts%rowtype;a gridex_received_sources.object_assessments%rowtype;
 binding gridex_ediel_ack_guide.source_bindings%rowtype;facet jsonb;initial jsonb;planned jsonb;own jsonb;original jsonb;projection jsonb;positive_text text;owned jsonb:='[]';structural_indices integer[];reason text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z06','Z10')) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_structural_response_source_required';END IF;
 IF requested IS NOT NULL AND(cardinality(requested) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(requested)x WHERE x IS NULL OR x<0) OR cardinality(requested)<>(SELECT count(DISTINCT x) FROM unnest(requested)x)) THEN RAISE EXCEPTION 'prodat_structural_response_scope_required';END IF;
 SELECT array_agg(first_line_index ORDER BY first_line_index) INTO structural_indices FROM gridex_received_sources.structural_object_apply_receipts e WHERE e.company_id=c AND e.environment=m.environment AND e.source_message_id=m.id AND(requested IS NULL OR e.first_line_index=ANY(requested));
 -- A new positive for E34 cannot borrow even a historical generic structure
 -- receipt. Its already sealed ACK remains governed by the earlier binding.
 IF m.message_code='Z06' AND EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts e WHERE e.company_id=c AND e.environment=m.environment AND e.source_message_id=m.id AND(requested IS NULL OR e.first_line_index=ANY(requested))
  AND gridex_received_sources.prodat_first_register_characteristic_v1(m.raw_payload,e.object_scope,'Z13') IS NOT DISTINCT FROM 'E34') THEN RAISE EXCEPTION 'prodat_customer_primary_response_own_effect_required';END IF;
 IF structural_indices IS NOT NULL THEN facet:=gridex_received_sources.prodat_structural_response_before_customer_v1(c,source_id,structural_indices);owned:=facet->'effectScopes';facet:=facet-'effectScopes';END IF;
 FOR r IN SELECT * FROM gridex_received_sources.customer_primary_response_receipts e WHERE e.company_id=c AND e.environment=m.environment AND e.source_message_id=m.id AND(requested IS NULL OR e.first_line_index=ANY(requested))
  AND e.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) ORDER BY e.first_line_index LOOP
  IF m.message_code IS DISTINCT FROM 'Z06' OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_customer_primary_response_original_changed';END IF;
  SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND source_message_id=m.id AND company_id=c AND environment=m.environment AND source_payload_hash=r.payload_hash AND canonical_assessment_id=r.canonical_assessment_id;
  IF a.id IS NULL OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR(SELECT count(*) FROM jsonb_array_elements(a.facts_text::jsonb->'objects')e WHERE e=r.owner_fact)<>1
   OR r.object_scope IS DISTINCT FROM r.owner_fact->'object' OR r.owner_fact->>'disposition' IS DISTINCT FROM 'accepted' OR r.owner_fact#>>'{business,owner}' IS DISTINCT FROM 'inbound-customer-life-event-v1'
   OR r.customer_id::text IS DISTINCT FROM r.owner_fact#>>'{business,customerId}' OR r.customer_version::text IS DISTINCT FROM r.owner_fact#>>'{business,customerVersion}' OR r.effective_at IS DISTINCT FROM(r.owner_fact#>>'{business,effectiveAt}')::timestamptz
   OR gridex_customer_life_events.owner_proof_consistent_v1(r.owner_fact->'party',r.owner_fact->'business',m.id) IS NOT TRUE
   OR gridex_received_sources.prodat_first_register_characteristic_v1(m.raw_payload,r.object_scope,'Z13') IS DISTINCT FROM 'E34' THEN RAISE EXCEPTION 'prodat_customer_primary_response_own_effect_unavailable';END IF;
  initial:=gridex_received_sources.read_prodat_response_assessment_v1(c,m.id,r.canonical_assessment_id);
  IF facet IS NULL THEN facet:=initial;END IF;
  SELECT e INTO planned FROM jsonb_array_elements(initial->'objects')e WHERE e->'lineIndex'=to_jsonb(r.first_line_index);
  IF planned IS NULL OR planned->>'outcome'='negative' OR planned->'id' IS DISTINCT FROM r.object_scope->'objectId' OR nullif(planned->>'li','') IS NULL
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')e WHERE e-'outcome'=planned-'outcome' AND e->>'outcome'<>'negative')
   OR EXISTS(SELECT FROM jsonb_array_elements(owned)e WHERE e->'lineIndex'=to_jsonb(r.first_line_index)) THEN RAISE EXCEPTION 'prodat_customer_primary_response_own_plan_unavailable';END IF;
  IF positive_text IS NULL THEN
   SELECT * INTO binding FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind='national' FOR SHARE;
   IF binding.source_message_id IS NULL OR binding.company_id IS DISTINCT FROM c OR binding.environment IS DISTINCT FROM m.environment OR binding.payload_sha256 IS DISTINCT FROM r.payload_hash THEN RAISE EXCEPTION 'prodat_structural_response_original_guide_unavailable';END IF;
   projection:=gridex_ediel_ack_guide.projection_for_original_v1(binding.source_version);positive_text:=projection#>>'{constraints,common,positiveText}';
   IF positive_text IS NULL OR NOT(projection#>'{constraints,PRODAT,allowedErc}'@>'["100"]'::jsonb) THEN RAISE EXCEPTION 'prodat_structural_response_original_guide_unavailable';END IF;
  END IF;
  owned:=owned||jsonb_build_array(jsonb_build_object('lineIndex',r.first_line_index,'canonicalAssessmentId',r.canonical_assessment_id,'objectAssessmentId',r.object_assessment_id,'appliedAt',r.applied_at,'effectKind','customer_version'));
  SELECT jsonb_agg(CASE WHEN e->'lineIndex'=to_jsonb(r.first_line_index) THEN e||jsonb_build_object('outcome','positive') ELSE e END ORDER BY ord) INTO original FROM jsonb_array_elements(facet->'objects') WITH ORDINALITY v(e,ord);facet:=jsonb_set(facet,'{objects}',original);
  SELECT coalesce(jsonb_agg(e ORDER BY ord),'[]') INTO original FROM jsonb_array_elements(facet->'responses') WITH ORDINALITY v(e,ord) WHERE e->'lineIndex' IS DISTINCT FROM to_jsonb(r.first_line_index);
  facet:=jsonb_set(facet,'{responses}',original||jsonb_build_array(jsonb_build_object('scope','object','lineIndex',r.first_line_index,'ercCode','100','fieldCode',NULL,'text',positive_text,'id',planned->'id','li',planned->'li')));
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(owned) THEN RAISE EXCEPTION 'prodat_structural_response_own_effect_unavailable';END IF;
 IF facet IS NULL THEN RETURN NULL;END IF;RETURN facet||jsonb_build_object('effectScopes',owned);
END $$;

--
-- Name: prodat_source_function_object_accepted_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_source_function_object_accepted_v1(c uuid, source_id uuid, canonical_id uuid, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE f jsonb;BEGIN
 f:=gridex_received_sources.require_prodat_source_function_objects_v1(c,source_id);
 RETURN f->>'assessmentId'=canonical_id::text AND EXISTS(SELECT FROM jsonb_array_elements(f->'objects')e WHERE e->>'functionalDecision'='accepted' AND e-'functionalDecision'-'reasonCodes'=object_scope);
END $$;

--
-- Name: prodat_structural_response_before_customer_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_structural_response_before_customer_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_received_sources.structural_object_apply_receipts%rowtype;a gridex_received_sources.object_assessments%rowtype;
 original jsonb;facet jsonb;initial jsonb;own jsonb;business jsonb;planned jsonb;projection jsonb;binding gridex_ediel_ack_guide.source_bindings%rowtype;positive_text text;owned jsonb:='[]';n integer;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR(m.message_code IN('Z06','Z10')) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_structural_response_source_required';END IF;
 IF requested IS NOT NULL AND(cardinality(requested) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(requested)x WHERE x IS NULL OR x<0) OR cardinality(requested)<>(SELECT count(DISTINCT x) FROM unnest(requested)x)) THEN RAISE EXCEPTION 'prodat_structural_response_scope_required';END IF;
 SELECT * INTO binding FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=source_id AND kind='national' FOR SHARE;
 IF binding.source_message_id IS NULL OR binding.company_id IS DISTINCT FROM c OR binding.environment IS DISTINCT FROM m.environment OR binding.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_structural_response_original_guide_unavailable';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(binding.source_version);positive_text:=projection#>>'{constraints,common,positiveText}';
 IF positive_text IS NULL OR NOT(projection#>'{constraints,PRODAT,allowedErc}'@>'["100"]'::jsonb) THEN RAISE EXCEPTION 'prodat_structural_response_original_guide_unavailable';END IF;
 FOR r IN SELECT * FROM gridex_received_sources.structural_object_apply_receipts e WHERE e.company_id=c AND e.source_message_id=source_id AND e.environment=m.environment AND(requested IS NULL OR e.first_line_index=ANY(requested))
  AND e.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) ORDER BY e.first_line_index LOOP
  IF r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR r.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'prodat_structural_response_original_changed';END IF;
  SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND source_message_id=m.id AND company_id=c AND environment=m.environment AND source_payload_hash=r.payload_hash AND canonical_assessment_id=r.canonical_assessment_id;
  IF a.id IS NULL OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_structural_response_own_effect_unavailable';END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(a.facts_text::jsonb->'objects')e WHERE e->'object'=r.object_scope;
  SELECT e INTO own FROM jsonb_array_elements(a.facts_text::jsonb->'objects')e WHERE e->'object'=r.object_scope;business:=own->'business';
  IF n<>1 OR own->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
   OR business->>'companyId' IS DISTINCT FROM c::text OR business->>'environment' IS DISTINCT FROM m.environment OR business->>'sourceMessageId' IS DISTINCT FROM m.id::text OR business->>'sourcePayloadHash' IS DISTINCT FROM r.payload_hash
   OR r.effect->'object' IS DISTINCT FROM own->'object' OR r.effect->'wire' IS DISTINCT FROM business->'wire' OR r.effect->>'meteringPointId' IS DISTINCT FROM business->>'meteringPointId' OR r.effect->>'siteId' IS DISTINCT FROM business->>'siteId'
   OR r.first_line_index IS DISTINCT FROM(own#>>'{object,registers,0,segmentIndex}')::integer THEN RAISE EXCEPTION 'prodat_structural_response_own_effect_unavailable';END IF;
  initial:=gridex_received_sources.read_prodat_response_assessment_v1(c,m.id,r.canonical_assessment_id);
  IF facet IS NULL THEN facet:=initial;END IF;
  SELECT e INTO planned FROM jsonb_array_elements(initial->'objects')e WHERE e->'lineIndex'=to_jsonb(r.first_line_index);
  IF planned IS NULL OR planned->>'outcome'='negative' OR planned->'id' IS DISTINCT FROM own#>'{object,objectId}' OR nullif(planned->>'li','') IS NULL
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')e WHERE e-'outcome'=planned-'outcome') THEN RAISE EXCEPTION 'prodat_structural_response_own_plan_unavailable';END IF;
  owned:=owned||jsonb_build_array(jsonb_build_object('lineIndex',r.first_line_index,'canonicalAssessmentId',r.canonical_assessment_id,'objectAssessmentId',r.object_assessment_id,'appliedAt',r.applied_at));
  SELECT jsonb_agg(CASE WHEN e->'lineIndex'=to_jsonb(r.first_line_index) THEN e||jsonb_build_object('outcome','positive') ELSE e END ORDER BY ord) INTO original FROM jsonb_array_elements(facet->'objects') WITH ORDINALITY v(e,ord);
  facet:=jsonb_set(facet,'{objects}',original);
  SELECT coalesce(jsonb_agg(e ORDER BY ord),'[]') INTO original FROM jsonb_array_elements(facet->'responses') WITH ORDINALITY v(e,ord) WHERE e->'lineIndex' IS DISTINCT FROM to_jsonb(r.first_line_index);
  facet:=jsonb_set(facet,'{responses}',original||jsonb_build_array(jsonb_build_object('scope','object','lineIndex',r.first_line_index,'ercCode','100','fieldCode',NULL,'text',positive_text,'id',planned->'id','li',planned->'li')));
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(owned) THEN RAISE EXCEPTION 'prodat_structural_response_own_effect_unavailable';END IF;
 IF facet IS NULL THEN RETURN NULL;END IF;
 RETURN facet||jsonb_build_object('effectScopes',owned);
END $$;

--
-- Name: prodat_structural_response_v1(uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.prodat_structural_response_v1(c uuid, source_id uuid, requested integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;effects jsonb;effect jsonb;scope jsonb;initial jsonb;facet jsonb;planned jsonb;
 binding gridex_ediel_ack_guide.source_bindings%rowtype;projection jsonb;positive_text text;owned jsonb:='[]';changed jsonb;
 first_line integer;indices jsonb;expected_kind text;own_count integer;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'prodat_domain_response_source_required';END IF;
 IF m.message_code='Z06' AND EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=m.id AND v.company_id=c AND v.environment=m.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL) THEN RETURN gridex_received_sources.confirmed_death_response_v1(c,source_id,requested);END IF;
 IF m.message_code IN('Z06','Z10') THEN RETURN gridex_received_sources.prodat_response_before_domain_effects_v1(c,source_id,requested);END IF;
 IF m.message_code NOT IN('Z04','Z05','Z14','Z15') THEN RAISE EXCEPTION 'prodat_domain_response_source_required';END IF;
 IF requested IS NOT NULL AND(cardinality(requested) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(requested)x WHERE x IS NULL OR x<0)
  OR cardinality(requested)<>(SELECT count(DISTINCT x) FROM unnest(requested)x)) THEN RAISE EXCEPTION 'prodat_domain_response_scope_required';END IF;
 -- These private getters qualify the stored effect's source/hash/full APP and
 -- admitted FUNCTION, its independent business proof, and real committed xmin.
 IF m.message_code IN('Z04','Z05') THEN
  expected_kind:='supply';effects:=gridex_received_sources.committed_supply_effects_v1(c,source_id,requested);
 ELSE
  expected_kind:='metering_permission';effects:=gridex_received_sources.committed_permission_effects_v1(c,source_id,requested);
 END IF;
 -- A legacy source without an authentic own-effect partition has no positive
 -- capability. Its already qualified own negatives remain renderable.
 IF effects IS NULL THEN
  IF requested IS NOT NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;RETURN NULL;
 END IF;
 IF jsonb_typeof(effects) IS DISTINCT FROM 'array' OR jsonb_array_length(effects)>8192 THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;
 IF jsonb_array_length(effects)=0 THEN
  IF requested IS NOT NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;RETURN NULL;
 END IF;
 SELECT * INTO binding FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind='national' FOR SHARE;
 IF binding.source_message_id IS NULL OR binding.company_id IS DISTINCT FROM c OR binding.environment IS DISTINCT FROM m.environment
  OR binding.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_domain_response_original_guide_unavailable';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(binding.source_version);positive_text:=projection#>>'{constraints,common,positiveText}';
 IF positive_text IS NULL OR NOT(projection#>'{constraints,PRODAT,allowedErc}'@>'["100"]'::jsonb) THEN RAISE EXCEPTION 'prodat_domain_response_original_guide_unavailable';END IF;
 FOR effect IN SELECT e FROM jsonb_array_elements(effects)e ORDER BY(e#>>'{objectScope,registers,0,segmentIndex}')::integer LOOP
  IF jsonb_typeof(effect) IS DISTINCT FROM 'object'
   OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(effect)k) IS DISTINCT FROM ARRAY['appliedAt','canonicalAssessmentId','effectFactsHash','effectKind','objectScope','receiptId','sourcePayloadHash']::text[]
   OR effect->>'effectKind' IS DISTINCT FROM expected_kind OR effect->>'sourcePayloadHash' IS DISTINCT FROM binding.payload_sha256
   OR effect->>'effectFactsHash' IS NULL OR effect->>'effectFactsHash'!~'^[a-f0-9]{64}$' OR effect->>'receiptId' IS NULL OR effect->>'canonicalAssessmentId' IS NULL
   OR effect->>'appliedAt' IS NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;
  PERFORM(effect->>'receiptId')::uuid,(effect->>'canonicalAssessmentId')::uuid;
  IF NOT isfinite((effect->>'appliedAt')::timestamptz) THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;
  scope:=effect->'objectScope';first_line:=(scope#>>'{registers,0,segmentIndex}')::integer;
  SELECT jsonb_agg(r->'segmentIndex' ORDER BY ord) INTO indices FROM jsonb_array_elements(scope->'registers') WITH ORDINALITY v(r,ord);
  initial:=gridex_received_sources.read_prodat_response_assessment_v1(c,m.id,(effect->>'canonicalAssessmentId')::uuid);
  IF facet IS NULL THEN
   -- National APP-positive siblings are not business effects. Keep only their
   -- already qualified negatives; a positive appears below for a real receipt.
   SELECT jsonb_agg(CASE WHEN e->>'outcome'='positive' THEN e||jsonb_build_object('outcome','held') ELSE e END ORDER BY ord)
    INTO changed FROM jsonb_array_elements(initial->'objects') WITH ORDINALITY v(e,ord);
   facet:=jsonb_set(initial,'{objects}',changed);
   SELECT coalesce(jsonb_agg(e ORDER BY ord),'[]') INTO changed FROM jsonb_array_elements(initial->'responses') WITH ORDINALITY v(e,ord) WHERE e->>'ercCode'<>'100';
   facet:=jsonb_set(facet,'{responses}',changed);
  END IF;
  SELECT count(*) INTO own_count FROM jsonb_array_elements(initial->'objects')e WHERE e->'lineIndex'=to_jsonb(first_line);
  SELECT e INTO planned FROM jsonb_array_elements(initial->'objects')e WHERE e->'lineIndex'=to_jsonb(first_line);
  IF own_count<>1 OR first_line IS NULL OR planned->>'outcome'='negative' OR nullif(planned->>'li','') IS NULL
   OR planned->'id' IS DISTINCT FROM scope->'objectId' OR planned->'registerLineIndices' IS DISTINCT FROM indices
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')e WHERE e-'outcome'=planned-'outcome' AND e->>'outcome'<>'negative')
   OR EXISTS(SELECT FROM jsonb_array_elements(owned)e WHERE e->'lineIndex'=to_jsonb(first_line))
   OR(requested IS NOT NULL AND NOT(first_line=ANY(requested))) THEN RAISE EXCEPTION 'prodat_domain_response_own_plan_unavailable';END IF;
  owned:=owned||jsonb_build_array(jsonb_build_object('lineIndex',first_line,'canonicalAssessmentId',effect->'canonicalAssessmentId',
   'objectAssessmentId',NULL,'effectReceiptId',effect->'receiptId','effectFactsHash',effect->'effectFactsHash','appliedAt',effect->'appliedAt','effectKind',expected_kind));
  SELECT jsonb_agg(CASE WHEN e->'lineIndex'=to_jsonb(first_line) THEN e||jsonb_build_object('outcome','positive') ELSE e END ORDER BY ord) INTO changed FROM jsonb_array_elements(facet->'objects') WITH ORDINALITY v(e,ord);
  facet:=jsonb_set(facet,'{objects}',changed);
  SELECT coalesce(jsonb_agg(e ORDER BY ord),'[]') INTO changed FROM jsonb_array_elements(facet->'responses') WITH ORDINALITY v(e,ord) WHERE e->'lineIndex' IS DISTINCT FROM to_jsonb(first_line);
  facet:=jsonb_set(facet,'{responses}',changed||jsonb_build_array(jsonb_build_object('scope','object','lineIndex',first_line,'ercCode','100','fieldCode',NULL,'text',positive_text,'id',planned->'id','li',planned->'li')));
 END LOOP;
 IF requested IS NOT NULL AND cardinality(requested)<>jsonb_array_length(owned) THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_unavailable';END IF;
 RETURN facet||jsonb_build_object('effectScopes',owned);
END $_$;

--
-- Name: production_contract_brp_wire_guard_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_brp_wire_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE o gridex_received_sources.production_contract_origins%rowtype;b jsonb;BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE message_id=NEW.id AND company_id=NEW.company_id;
 IF o.event_id IS NULL THEN RETURN NEW;END IF;
 b:=gridex_received_sources.production_contract_source_for_execution_v1(o.company_id,o.event_id,o.actor_user_id,'communication.write');
 IF b->>'status' IS DISTINCT FROM 'authorized' OR gridex_received_sources.outbound_single_brp_v1(NEW.raw_payload) IS DISTINCT FROM b->>'brpEdielId' THEN RAISE EXCEPTION 'production_contract_physical_source_brp_required';END IF;
 INSERT INTO gridex_received_sources.production_contract_brp_bindings(message_id,company_id,event_id,brp_ediel_id,source_basis,payload_hash) VALUES(NEW.id,o.company_id,o.event_id,b->>'brpEdielId',b->'brpBasis',NEW.immutable_payload_hash);RETURN NEW;
END$$;

--
-- Name: customer_contracts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid,
    site_id uuid,
    metering_point_id uuid,
    customer_site_id uuid,
    contract_offer_id uuid,
    source_type text DEFAULT 'manual_override'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    contract_name text DEFAULT 'Elavtal'::text NOT NULL,
    contract_type text DEFAULT 'variable_monthly'::text NOT NULL,
    campaign_name text,
    campaign_code text,
    campaign_version text,
    price_version text,
    terms_version text,
    contract_version text,
    signed_version text,
    terms_signed_version text,
    version_snapshot jsonb DEFAULT '{}'::jsonb,
    start_status text,
    old_supplier_start_at date,
    grid_owner_confirmed_start_at date,
    ediel_confirmed_start_at date,
    export_blocked boolean DEFAULT false NOT NULL,
    export_block_reason text,
    price_snapshot jsonb DEFAULT '{}'::jsonb,
    campaign_snapshot jsonb DEFAULT '{}'::jsonb,
    billing_ready_status text,
    billing_blocker_reasons jsonb DEFAULT '[]'::jsonb,
    withdrawal_requested_at timestamp with time zone,
    rejected_reason text,
    fixed_price_ore_per_kwh numeric,
    spot_markup_ore_per_kwh numeric,
    variable_fee_ore_per_kwh numeric,
    monthly_fee_sek numeric,
    green_fee_mode text DEFAULT 'none'::text,
    green_fee_value numeric,
    binding_months integer,
    notice_months integer,
    optional_fee_lines jsonb DEFAULT '[]'::jsonb,
    starts_at date,
    expected_start_at date,
    confirmed_start_at date,
    actual_start_at date,
    start_date_source text,
    ends_at date,
    signed_at timestamp with time zone,
    termination_notice_date date,
    termination_reason text,
    auto_renew_enabled boolean DEFAULT false NOT NULL,
    auto_renew_term_months integer,
    override_reason text,
    invoice_recipient text,
    invoice_email text,
    invoice_reference text,
    billing_street text,
    billing_postal_code text,
    billing_city text,
    billing_country text DEFAULT 'SE'::text,
    billing_address_same_as_site boolean DEFAULT true,
    billing_level text,
    consolidated_invoice boolean DEFAULT false,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    requested_start_mode text DEFAULT 'earliest_possible'::text NOT NULL,
    calculated_earliest_start_date date,
    price_area_used text,
    grid_area_code_used text,
    resolution_status text,
    onboarding_status text,
    onboarding_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    requested_start_date date,
    confirmed_start_date date,
    actual_start_date date,
    agreement_channel text,
    contract_number text,
    price_plan_id uuid,
    price_plan_version_id uuid,
    invoice_fee_sek numeric,
    markup_ore_per_kwh numeric,
    contract_price_snapshot_id uuid,
    legal_acceptance_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    legal_readiness_status text DEFAULT 'pending'::text NOT NULL,
    legal_readiness_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    application_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    website_application_id uuid,
    legal_bundle_id uuid,
    price_book_id uuid,
    snapshot_quality text,
    snapshot_hash text,
    billing_blocked_reason text,
    customer_number text,
    external_customer_id text,
    public_contract_offer_id uuid,
    offer_reference text,
    legal_versions_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    signature_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    signature_snapshot_sha256 text,
    signed_ip_hash text,
    signed_user_agent text,
    contract_product_id uuid,
    contract_product_version_id uuid,
    contract_publication_version_id uuid,
    legal_bundle_version_id uuid,
    commercial_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    legal_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    document_sha256 text,
    locked_at timestamp with time zone,
    tenant_communication_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    tenant_communication_snapshot_sha256 text,
    tenant_legal_party_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    lifecycle_stage text DEFAULT 'agreement_ready'::text NOT NULL,
    billing_eligible_at timestamp with time zone,
    billing_eligibility_source text,
    quote_reference text,
    energy_direction text DEFAULT 'consumption'::text NOT NULL,
    ended_at timestamp with time zone,
    status_reason_code text,
    customer_contract_reference text DEFAULT public.gridex_new_public_resource_reference('contract'::text) NOT NULL,
    discount_value numeric,
    discount_unit text,
    start_fee_sek numeric,
    admin_fee_sek numeric,
    break_fee_sek numeric,
    vat_rate numeric DEFAULT 0.25,
    is_distance_agreement boolean DEFAULT false NOT NULL,
    withdrawal_information_sent_at timestamp with time zone,
    withdrawal_deadline_at timestamp with time zone,
    billing_blocked_by_case_id uuid,
    CONSTRAINT customer_contracts_billing_identity_check CHECK (((billing_eligible_at IS NULL) OR ((contract_price_snapshot_id IS NOT NULL) AND (contract_product_version_id IS NOT NULL) AND (contract_publication_version_id IS NOT NULL) AND (price_area_used = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])) AND (NULLIF(snapshot_hash, ''::text) IS NOT NULL)))),
    CONSTRAINT customer_contracts_contract_type_check CHECK ((contract_type = ANY (ARRAY['fixed'::text, 'variable'::text, 'variable_spot'::text, 'variable_monthly'::text, 'variable_hourly'::text, 'variable_quarterly'::text, 'hourly_spot'::text, 'spot'::text, 'portfolio'::text, 'mixed'::text, 'manual_override'::text]))),
    CONSTRAINT customer_contracts_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT customer_contracts_invoice_fee_nonnegative CHECK (((invoice_fee_sek IS NULL) OR (invoice_fee_sek >= (0)::numeric))),
    CONSTRAINT customer_contracts_lifecycle_stage_check CHECK ((lifecycle_stage = ANY (ARRAY['agreement_ready'::text, 'agreement_signed'::text, 'facility_data_ready'::text, 'switch_data_ready'::text, 'switch_ready'::text, 'billing_ready'::text, 'active'::text]))),
    CONSTRAINT customer_contracts_requested_start_mode_check CHECK ((requested_start_mode = ANY (ARRAY['earliest_possible'::text, 'specific_date'::text]))),
    CONSTRAINT customer_contracts_source_type_check CHECK (((source_type IS NULL) OR (source_type = ANY (ARRAY['catalog'::text, 'manual_override'::text, 'manual'::text, 'admin'::text, 'api'::text, 'external_website'::text, 'website_application'::text, 'website_application_review'::text, 'customer_portal'::text, 'import'::text, 'migration'::text, 'system'::text])))),
    CONSTRAINT customer_contracts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_signature'::text, 'signature_failed'::text, 'signed'::text, 'active'::text, 'terminated'::text, 'cancelled'::text, 'expired'::text])))
);

--
-- Name: COLUMN customer_contracts.energy_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_contracts.energy_direction IS 'Canonical economic direction. Production uses credit/self-billing and must not create ordinary consumption supply/invoice flows.';

--
-- Name: production_contract_hash_v1(public.customer_contracts); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_hash_v1(c public.customer_contracts) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('id',c.id,'companyId',c.company_id,'customerId',c.customer_id,'pointId',c.metering_point_id,
 'contractVersion',c.contract_version,'signedVersion',c.signed_version,'signedAt',c.signed_at,'versionSnapshot',c.version_snapshot)::text,'UTF8')),'hex')
$$;

--
-- Name: production_contract_origin_guard_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_origin_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'production_contract_origin_immutable';END IF;
 IF (to_jsonb(NEW)-ARRAY['message_id','payload_hash']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['message_id','payload_hash'])
 OR OLD.message_id IS NOT NULL OR NEW.message_id IS NULL OR NEW.payload_hash IS NULL THEN RAISE EXCEPTION 'production_contract_origin_immutable';END IF;
 RETURN NEW;
END $$;

--
-- Name: production_contract_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 -- A revocation cannot race a qualified source read/message binding: all readers
 -- hold SHARE on the same immutable parent until their atomic effect commits.
 PERFORM e.id FROM gridex_received_sources.production_contract_events e WHERE e.id=NEW.event_id FOR UPDATE;
 RETURN NEW;
END $$;

--
-- Name: production_contract_source_before_brp_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_source_before_brp_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_permission text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;point public.metering_points%rowtype;site public.customer_sites%rowtype;
BEGIN
 basis:=gridex_received_sources.production_contract_source_before_site_v1(p_company_id,p_event_id,p_actor_user_id,p_permission);
 IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;END IF;
 SELECT * INTO point FROM public.metering_points WHERE id=(basis->>'meteringPointId')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=point.site_id AND company_id=p_company_id FOR SHARE;
 IF point.id IS NULL OR point.customer_id::text IS DISTINCT FROM basis->>'customerId' OR point.site_id IS NULL OR site.id IS NULL OR site.customer_id IS DISTINCT FROM point.customer_id THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_source_owned_site_required'));END IF;
 RETURN basis||jsonb_build_object('siteId',site.id);
END $$;

--
-- Name: production_contract_source_before_intake_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_source_before_intake_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_permission text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;brp jsonb;event gridex_received_sources.production_contract_events%rowtype;start_event gridex_received_sources.production_contract_events%rowtype;origin gridex_received_sources.production_contract_origins%rowtype;original public.ediel_messages%rowtype;proof gridex_received_sources.production_contract_brp_bindings%rowtype;wire jsonb;BEGIN
 -- Discovery is not authority. Lock the linked original before the existing
 -- owner locks contract/customer/point, then requalify the immutable exact tuple.
 SELECT * INTO event FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id;
 IF event.event_kind='ceased' THEN
  SELECT * INTO origin FROM gridex_received_sources.production_contract_origins WHERE event_id=event.start_event_id AND company_id=p_company_id;
  SELECT * INTO original FROM public.ediel_messages WHERE id=origin.message_id AND company_id=p_company_id FOR SHARE;
 END IF;
 basis:=gridex_received_sources.production_contract_source_before_brp_v1(p_company_id,p_event_id,p_actor_user_id,p_permission);
 IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;END IF;
 SELECT * INTO STRICT event FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id;
 IF event.event_kind='ceased' THEN
  SELECT * INTO start_event FROM gridex_received_sources.production_contract_events WHERE id=event.start_event_id AND company_id=p_company_id;
  SELECT * INTO proof FROM gridex_received_sources.production_contract_brp_bindings WHERE message_id=original.id AND company_id=p_company_id;
  wire:=gridex_received_sources.prodat_recovery_wire_v1(original.raw_payload);
  IF start_event.id IS NULL OR original.id IS NULL OR proof.message_id IS NULL OR proof.event_id IS DISTINCT FROM start_event.id OR origin.event_id IS DISTINCT FROM start_event.id
   OR start_event.event_kind IS DISTINCT FROM 'signed' OR start_event.contract_id IS DISTINCT FROM event.contract_id OR start_event.contract_revision IS DISTINCT FROM event.contract_revision OR start_event.protected_contract_hash IS DISTINCT FROM event.protected_contract_hash
   OR start_event.customer_id IS DISTINCT FROM event.customer_id OR start_event.metering_point_id IS DISTINCT FROM event.metering_point_id OR start_event.point_id IS DISTINCT FROM event.point_id OR start_event.identity_agency IS DISTINCT FROM event.identity_agency
   OR start_event.legal_actor_id IS DISTINCT FROM event.legal_actor_id OR start_event.legal_sender_id IS DISTINCT FROM event.legal_sender_id OR start_event.legal_receiver_id IS DISTINCT FROM event.legal_receiver_id OR start_event.environment IS DISTINCT FROM event.environment OR start_event.grid_area_code IS DISTINCT FROM event.grid_area_code
   OR original.environment IS DISTINCT FROM event.environment OR original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z09' OR original.immutable_rendered_at IS NULL
   OR proof.payload_hash IS DISTINCT FROM origin.payload_hash OR original.immutable_payload_hash IS DISTINCT FROM proof.payload_hash OR proof.payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex')
   OR wire IS NULL OR wire->>'legalSender' IS DISTINCT FROM event.legal_sender_id OR wire->>'legalReceiver' IS DISTINCT FROM event.legal_receiver_id OR jsonb_array_length(wire->'objects') IS DISTINCT FROM 1
   OR wire#>>'{objects,0,point}' IS DISTINCT FROM event.point_id OR wire#>>'{objects,0,identityAgency}' IS DISTINCT FROM event.identity_agency OR wire#>>'{objects,0,reason}' IS DISTINCT FROM 'Z70' OR gridex_received_sources.outbound_single_brp_v1(original.raw_payload) IS DISTINCT FROM proof.brp_ediel_id
   OR proof.source_basis->>'sourceKind' IS DISTINCT FROM 'signed_contract_brp_declaration' OR proof.source_basis->>'contractId' IS DISTINCT FROM event.contract_id::text
  THEN RETURN jsonb_build_object('status','held','missing',ARRAY['production_contract_exact_original_brp_party']);END IF;
  RETURN basis||jsonb_build_object('brpEdielId',proof.brp_ediel_id,'brpBasis',proof.source_basis,'brpBasisKind','production_original_contract_party','brpOriginalMessageId',original.id);
 END IF;
 brp:=gridex_brp_sources.require_source_v1(p_company_id,(basis->>'contractId')::uuid,p_actor_user_id,CASE p_permission WHEN 'communication.send' THEN 'send' ELSE 'prepare' END,basis->>'environment',(basis->>'customerId')::uuid,(basis->>'siteId')::uuid,(basis->>'meteringPointId')::uuid,(basis->>'boundaryAt')::timestamptz,NULL);
 IF brp->>'status' IS DISTINCT FROM 'authorized' THEN RETURN coalesce(brp,jsonb_build_object('status','held','missing',ARRAY['production_contract_source_brp_required']));END IF;
 IF brp->>'sourceKind' IS DISTINCT FROM 'signed_contract_brp_declaration' OR brp->>'companyId' IS DISTINCT FROM basis->>'companyId' OR brp->>'environment' IS DISTINCT FROM basis->>'environment' OR brp->>'contractId' IS DISTINCT FROM basis->>'contractId'
 OR brp->>'customerId' IS DISTINCT FROM basis->>'customerId' OR brp->>'siteId' IS DISTINCT FROM basis->>'siteId' OR brp->>'meteringPointId' IS DISTINCT FROM basis->>'meteringPointId' OR (brp->>'at')::timestamptz IS DISTINCT FROM (basis->>'boundaryAt')::timestamptz
 OR brp->>'pointId' IS DISTINCT FROM basis->>'pointId' OR brp->>'identityAgency' IS DISTINCT FROM basis->>'identityAgency' OR brp->>'gridArea' IS DISTINCT FROM basis->>'gridArea' OR brp->>'legalSenderId' IS DISTINCT FROM basis->>'legalSenderId' OR brp->>'legalReceiverId' IS DISTINCT FROM basis->>'legalReceiverId' OR brp->>'legalActorId' IS DISTINCT FROM basis->>'legalActorId' THEN RAISE EXCEPTION 'production_contract_brp_scope_required';END IF;
 RETURN basis||jsonb_build_object('brpEdielId',brp->>'brpEdielId','brpBasis',brp);
END$$;

--
-- Name: production_contract_source_before_site_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_source_before_site_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_permission text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e gridex_received_sources.production_contract_events%rowtype;c public.customer_contracts%rowtype;mp public.metering_points%rowtype;ids uuid[];start gridex_received_sources.production_contract_events%rowtype;
BEGIN
 IF (p_permission IN('communication.write','communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'production_contract_execution_phase_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 OR (CASE WHEN p_permission='communication.send' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) ELSE coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) END) IS NOT TRUE
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_execution_actor_unqualified'));END IF;
 PERFORM gridex_contract_source_intake.lock_target_contract_v1(p_company_id,'production_contract_event',p_event_id); SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR e.approved_at>now() OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=e.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('authentic_production_contract_event_required'));END IF;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=e.customer_id AND customer.company_id=e.company_id FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_customer_required'));END IF;
 SELECT * INTO c FROM public.customer_contracts WHERE id=e.contract_id AND company_id=e.company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=e.metering_point_id AND company_id=e.company_id FOR SHARE;
 IF c.id IS NULL OR mp.id IS NULL OR c.customer_id IS DISTINCT FROM e.customer_id OR c.metering_point_id IS DISTINCT FROM e.metering_point_id
 OR mp.customer_id IS DISTINCT FROM e.customer_id OR mp.product_direction IS DISTINCT FROM 'production'
 OR mp.ediel_metering_point_id IS DISTINCT FROM e.point_id OR mp.grid_owner_ediel_id IS DISTINCT FROM e.legal_receiver_id OR mp.grid_area_code IS DISTINCT FROM e.grid_area_code
 OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL OR c.signed_version IS DISTINCT FROM e.contract_revision
 OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM e.protected_contract_hash
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_owner_scope_changed'));END IF;
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment ORDER BY p.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment ORDER BY r.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.identifier_value=e.legal_receiver_id ORDER BY i.id FOR SHARE;
 PERFORM a.id FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id FOR SHARE;
 PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=now() AND (p.valid_to IS NULL OR now()<p.valid_to))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment AND r.actor_id=e.legal_actor_id AND r.role_code='electricity_supplier' AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to))
 OR (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))<>1
 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.actor_id=e.legal_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_sender_id AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_legal_supplier_required'));END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.platform_actor_identifiers i WHERE lower(i.identifier_type) IN ('edielid','ediel_id') AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to);
 IF coalesce(cardinality(ids),0)<>1 OR ids[1] IS DISTINCT FROM e.dso_actor_id
 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=e.dso_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to))
 OR NOT EXISTS(SELECT FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id AND a.status='active' AND a.match_status='verified')
 OR NOT EXISTS(SELECT FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id AND r.actor_role='grid_owner' AND r.is_active) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_verified_dso_identity_required'));END IF;
 IF e.event_kind='ceased' THEN
 SELECT * INTO start FROM gridex_received_sources.production_contract_events WHERE id=e.start_event_id AND company_id=e.company_id FOR SHARE;
 IF start.id IS NULL OR start.event_kind IS DISTINCT FROM 'signed' OR start.environment IS DISTINCT FROM e.environment OR start.contract_id IS DISTINCT FROM e.contract_id OR start.metering_point_id IS DISTINCT FROM e.metering_point_id OR start.customer_id IS DISTINCT FROM e.customer_id OR start.boundary_at>=e.boundary_at OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=start.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_original_start_required'));END IF;
 END IF;
 RETURN jsonb_build_object('status','authorized','companyId',e.company_id,'environment',e.environment,'eventId',e.id,'eventKind',e.event_kind,'sourceDigest',e.source_sha256,'sourceVersion',e.source_version,'sourceReference',e.source_reference,
 'legalActorId',e.legal_actor_id,'legalSenderId',e.legal_sender_id,'legalReceiverId',e.legal_receiver_id,'contractId',e.contract_id,'customerId',e.customer_id,'meteringPointId',e.metering_point_id,'pointId',e.point_id,'identityAgency',e.identity_agency,'gridArea',e.grid_area_code,
 'contractReference',e.contract_reference,'contractRevision',e.contract_revision,'boundaryAt',e.boundary_at);
END $$;

--
-- Name: production_contract_source_for_execution_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.production_contract_source_for_execution_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_permission text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE basis jsonb;BEGIN
    PERFORM gridex_contract_source_intake.lock_target_contract_v1(p_company_id,'production_contract_event',p_event_id); basis:=gridex_received_sources.production_contract_source_before_intake_v1(p_company_id,p_event_id,p_actor_user_id,p_permission);
    IF basis->>'status'='authorized' AND EXISTS(SELECT FROM gridex_contract_source_intake.qualifications WHERE target_id=p_event_id) AND gridex_contract_source_intake.current_v1(p_company_id,'production_contract_event',p_event_id) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_qualified_production_contract_original']);END IF;RETURN basis;
   END$$;

--
-- Name: qualified_recovery_origin_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.qualified_recovery_origin_v1(c uuid, op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE first_op gridex_received_sources.prodat_recovery_operations%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype;
 m public.ediel_messages%rowtype;next_op uuid;seen uuid[]:='{}';i int;
BEGIN
 SELECT * INTO first_op FROM gridex_received_sources.prodat_recovery_operations WHERE id=op_id AND company_id=c;
 IF first_op.id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_established_operation_required';END IF;
 PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(c,first_op.id);
 FOR i IN 1..32 LOOP
  IF op_id=ANY(seen) THEN RAISE EXCEPTION 'prodat_recovery_source_cohort_cycle';END IF;seen:=array_append(seen,op_id);
  SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=op_id AND company_id=c;
  IF op.environment IS DISTINCT FROM first_op.environment THEN RAISE EXCEPTION 'prodat_recovery_origin_environment_changed';END IF;
  PERFORM gridex_received_sources.require_established_recovery_source_v1(c,op.id);
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=c AND environment=op.environment FOR SHARE;
  SELECT operation_id INTO next_op FROM gridex_received_sources.prodat_recovery_messages WHERE message_id=m.id;
  IF next_op IS NULL THEN RETURN jsonb_build_object('sourceOriginMessageId',m.id,'originalMessageId',first_op.original_message_id,'operationId',first_op.id);END IF;
  SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=next_op AND company_id=c;
  IF (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR op.environment IS DISTINCT FROM m.environment
   OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.source_operation_id IS DISTINCT FROM op.id::text
   OR m.original_message_id IS DISTINCT FROM op.original_message_id::text OR m.raw_payload IS DISTINCT FROM op.corrected_raw_payload
   OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM op.corrected_payload_hash
   OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_origin_alias_changed';END IF;
  op_id:=next_op;
 END LOOP;
 RAISE EXCEPTION 'prodat_recovery_source_cohort_bound_exceeded';
END$$;

--
-- Name: qualify_established_recovery_source_v1(uuid, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.qualify_established_recovery_source_v1(p_company_id uuid, p_original_message_id uuid, p_actor_user_id uuid, p_operation_id uuid, p_source_ack_message_id uuid DEFAULT NULL::uuid, p_previous_attempt_id uuid DEFAULT NULL::uuid, p_corrected_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;q jsonb;
BEGIN
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id;
 IF op.id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_established_operation_required';END IF;
 q:=gridex_received_sources.assess_recovery_source_v1(p_company_id,p_original_message_id,p_actor_user_id,p_operation_id,p_source_ack_message_id,p_previous_attempt_id,p_corrected_raw_payload);
 IF q->>'status' IS DISTINCT FROM 'qualified' THEN RETURN q;END IF;
 IF op.environment IS DISTINCT FROM q->>'environment' OR op.original_message_id IS DISTINCT FROM p_original_message_id OR op.kind IS DISTINCT FROM q->>'kind'
  OR op.original_payload_hash IS DISTINCT FROM q->>'originalPayloadHash' OR op.source_ack_hash IS DISTINCT FROM q->>'sourceAckHash' OR op.corrected_payload_hash IS DISTINCT FROM q->>'correctedPayloadHash'
  OR op.previous_attempt_id IS DISTINCT FROM p_previous_attempt_id OR op.source_ack_message_id IS DISTINCT FROM p_source_ack_message_id OR op.corrected_raw_payload IS DISTINCT FROM p_corrected_raw_payload THEN RAISE EXCEPTION 'prodat_recovery_operation_conflict';END IF;
 RETURN jsonb_build_object('status','authorized','operationId',op.id,'kind',op.kind,'originalMessageId',op.original_message_id,'previousAttemptId',op.previous_attempt_id,'newMessageId',(SELECT message_id FROM gridex_received_sources.prodat_recovery_messages WHERE operation_id=op.id));
END$$;

--
-- Name: read_document_reference_context_v1(uuid, text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.read_document_reference_context_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_actor_user_id uuid, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype; rows jsonb; n integer;
BEGIN
 PERFORM gridex_received_sources.document_reference_actor_v1(p_company_id,p_actor_user_id);
 IF p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff>clock_timestamp() THEN RAISE EXCEPTION 'invalid_document_cutoff' USING ERRCODE='23514'; END IF;
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment
 AND message_code='Z05' AND captured_at<=p_cutoff;
 IF src.source_message_id IS NULL THEN RAISE EXCEPTION 'document_reference_unavailable' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO n FROM gridex_received_sources.document_reference_attempts WHERE source_message_id=src.source_message_id AND recorded_at<=p_cutoff;
 SELECT coalesce(jsonb_agg(row_data ORDER BY recorded_at,id),'[]'::jsonb) INTO rows FROM (
 SELECT a.recorded_at,a.id,jsonb_build_object('attemptId',a.id,'documentId',a.document_id,'recordedAt',a.recorded_at,'factsHash',a.facts_hash,
 'sourceScope',a.facts->'sourceScope','graph',a.facts->'graph','predecessorId',a.predecessor_id,
 'document',a.facts->'document','createdXid',a.created_xid::text,
 'outcome',CASE WHEN o.id IS NOT NULL THEN jsonb_build_object('outcomeId',o.id,'recordedAt',o.recorded_at,'createdXid',o.created_xid::text,'observation',o.observation,'factsHash',o.facts_hash) ELSE NULL END,
 'witness',CASE WHEN w.id IS NOT NULL THEN jsonb_build_object('witnessId',w.id,'availableAt',w.observed_at,'visibilitySnapshot',w.visibility_snapshot) ELSE NULL END) row_data
 FROM gridex_received_sources.document_reference_attempts a
 LEFT JOIN gridex_received_sources.document_reference_outcomes o ON o.attempt_id=a.id AND o.recorded_at<=p_cutoff AND o.created_xid<>pg_current_xact_id()
 LEFT JOIN gridex_received_sources.document_reference_witnesses w ON w.outcome_id=o.id AND w.observed_at<=p_cutoff
 WHERE a.source_message_id=src.source_message_id AND a.recorded_at<=p_cutoff AND a.created_xid<>pg_current_xact_id()
 ORDER BY a.recorded_at,a.id LIMIT 1000) bounded;
 RETURN jsonb_build_object('kind','context_document_reference_v1','companyId',p_company_id,'environment',p_environment,'sourceMessageId',src.source_message_id,
 'sourceHash',src.payload_hash,'sourceScope',gridex_received_sources.correction_wire_observation_v1(src.raw_payload),
 'cutoff',p_cutoff,'visibilitySnapshot',pg_current_snapshot()::text,'coverage','incomplete','authority','none','requiresRevalidation',true,'truncated',n>1000,'attempts',rows,
 'epoch',(SELECT jsonb_build_object('installedAt',installed_at,'historyCoverage',history_coverage) FROM gridex_received_sources.document_reference_epoch));
END $$;

--
-- Name: read_prodat_response_assessment_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.read_prodat_response_assessment_v1(p_company uuid, p_source uuid, p_assessment uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;a gridex_received_sources.validation_assessments%rowtype;f gridex_received_sources.prodat_response_facets%rowtype;basis jsonb;facts jsonb;facet jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE id=p_source AND company_id=p_company FOR SHARE;
 IF s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 SELECT v.* INTO a FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  AND v.id=p_assessment AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 SELECT * INTO f FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=a.source_payload_hash;
 IF a.id IS NULL OR f.assessment_id IS NULL OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR f.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.response_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 facts:=a.facts_text::jsonb;facet:=f.response_facts_text::jsonb;
 IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,facts,facet),false) THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
 IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version','snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'prodat_response_original_rule_witness_mismatch';END IF;
 RETURN facet||jsonb_build_object('assessmentId',a.id);
END $$;

--
-- Name: received_z14_reporting_source_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.received_z14_reporting_source_basis_v1(p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
 m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;
 z public.ediel_messages%rowtype;o gridex_service_permission.origins%rowtype;
 e public.ediel_service_evidence%rowtype;a gridex_ediel_services.artifacts%rowtype;
 v gridex_ediel_services.reviews%rowtype;latest gridex_ediel_services.reviews%rowtype;
 wire jsonb;tokens jsonb;env jsonb;original_wire jsonb;original_tokens jsonb;original_env jsonb;
 own jsonb;original_own jsonb;customer_party jsonb;original_customer jsonb;
 scope jsonb;birth_context jsonb;legal_context jsonb;accepted jsonb;known jsonb;
 result jsonb:='[]';held jsonb:='[]';missing text[];evidence_kind text;
 original_ids uuid[];origin_count integer;line_index integer:=0;known_service boolean:=false;
 basis_version bigint;recorded timestamptz;clock_at timestamptz:=clock_timestamp();
 source_end timestamptz;term jsonb;purpose jsonb;source_evidence uuid;qualified_evidence boolean;
 end_review timestamptz;end_archive timestamptz;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'received_reporting_service_required' USING ERRCODE='42501';END IF;
 IF p_source_message_id IS NULL OR p_actor_user_id IS NULL THEN RAISE EXCEPTION 'received_reporting_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id;
 IF m.id IS NULL THEN RETURN NULL;END IF;
 -- Reuse the existing READ graph lock before actor/current-revocation reads.
 -- It conveys no send/assessment authority and never changes domain rows.
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 IF NOT EXISTS(SELECT FROM public.companies c WHERE c.id=m.company_id AND c.status='active')
 OR NOT EXISTS(SELECT FROM auth.users u WHERE u.id=p_actor_user_id AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=clock_at))
 OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 OR NOT (coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'ediel.read'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'communication.read'),false))
 THEN RAISE EXCEPTION 'received_reporting_read_actor_forbidden' USING ERRCODE='42501';END IF;
 IF m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z14' THEN RETURN NULL;END IF;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=m.company_id;
 birth_context:=s.received_context;
 known:=jsonb_build_object('companyId',m.company_id,'sourceMessageId',m.id,'environment',m.environment,'sourcePayloadHash',s.payload_hash,'sourceReceivedAt',s.source_received_at,'sourceReceivedContext',birth_context,
  'sourceContextHash',encode(sha256(convert_to(birth_context::text,'UTF8')),'hex'),'actorUserId',p_actor_user_id,'evaluationUtcMs',floor(extract(epoch FROM clock_at)*1000)::bigint);
 IF s.source_message_id IS NULL OR s.origin IS DISTINCT FROM 'database_insert' OR s.environment IS DISTINCT FROM m.environment OR s.message_code IS DISTINCT FROM 'Z14'
 OR s.raw_payload IS NULL OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 OR s.source_received_at IS NULL OR NOT isfinite(s.source_received_at) OR s.source_received_at>clock_at OR s.captured_at IS NULL OR NOT isfinite(s.captured_at) OR s.captured_at<s.source_received_at OR s.captured_at>clock_at
 OR birth_context IS NULL OR birth_context IS DISTINCT FROM m.execution_context_snapshot->'receivedProdatContext'
 OR birth_context->'version' IS DISTINCT FROM '1'::jsonb OR birth_context->>'contextOrigin' IS DISTINCT FROM 'database_insert'
 OR birth_context->>'sourceMessageId' IS DISTINCT FROM m.id::text OR birth_context->>'companyId' IS DISTINCT FROM m.company_id::text
 OR birth_context->>'messageCode' IS DISTINCT FROM 'Z14' OR birth_context->>'environment' IS DISTINCT FROM m.environment OR birth_context->>'payloadHash' IS DISTINCT FROM s.payload_hash
 OR (birth_context->>'sourceReceivedAt')::timestamptz IS DISTINCT FROM s.source_received_at OR (birth_context->>'capturedAt') IS NULL OR NOT isfinite((birth_context->>'capturedAt')::timestamptz)
 OR (birth_context->>'capturedAt')::timestamptz<s.source_received_at OR (birth_context->>'capturedAt')::timestamptz>s.captured_at
 OR m.message_received_at IS DISTINCT FROM s.source_received_at
 THEN RETURN known||jsonb_build_object('status','held','objects','[]'::jsonb,'heldObjects','[]'::jsonb,'missing',ARRAY['immutable_received_reporting_scope_required']);END IF;
 wire:=gridex_received_sources.permission_partition_wire_v1(m.raw_payload);tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);env:=gridex_ediel_technical_ack.envelope(m.raw_payload);
 IF wire IS NULL OR tokens IS NULL OR env IS NULL OR wire->>'code' IS DISTINCT FROM 'Z14' OR env->>'environment' IS DISTINCT FROM m.environment
 THEN RETURN known||jsonb_build_object('status','held','objects','[]'::jsonb,'heldObjects','[]'::jsonb,'missing',ARRAY['complete_received_reporting_wire_required']);END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(wire->'objects') LOOP
  -- Negative objects have no positive reporting fields. Their existing owner
  -- remains authoritative; they never acquire private/bounded requiredness.
  IF own->>'reason'='Z96' THEN line_index:=line_index+1;CONTINUE;END IF;
  customer_party:=NULL;
  SELECT jsonb_agg(t->'elements'->2)->0 INTO customer_party FROM jsonb_array_elements(tokens)t
   WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' AND (t->>'index')::int>(own->>'firstLineIndex')::int
   AND (t->>'index')::int<coalesce((SELECT min((n->>'index')::int) FROM jsonb_array_elements(tokens)n WHERE n->>'tag'='LIN' AND (n->>'index')::int>(own->>'firstLineIndex')::int),2147483647)
   HAVING count(*)=1;
  scope:=jsonb_build_object('lineIndex',line_index,'objectId',own->'point','identityAgency',own->'identityAgency','lineItemReference',own->'li','customer',jsonb_build_object('id',customer_party->>0,'qualifier',customer_party->>1,'agency',customer_party->>2),'reason',own->'reason');
  missing:=ARRAY[]::text[];
  IF own->>'projectionHeld'='true' OR nullif(own->>'point','') IS NULL OR (own->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(own->>'li','') IS NULL
   OR (own->>'reason' IN('S17','S18')) IS NOT TRUE OR own->>'status' IS DISTINCT FROM 'A74' OR jsonb_array_length(customer_party) IS DISTINCT FROM 3 OR (customer_party->>1 IN('SE1','SE2')) IS NOT TRUE OR customer_party->>2 IS DISTINCT FROM '260'
  THEN held:=held||jsonb_build_array(jsonb_build_object('scope',scope,'missing',ARRAY['complete_own_received_reporting_identity_required']));line_index:=line_index+1;CONTINUE;END IF;
  -- The immutable origin's message/intent LI selects a possible service source;
  -- mutable permission status or live assignment version is never a selector.
  SELECT array_agg(zm.id ORDER BY zm.id) INTO original_ids FROM gridex_service_permission.origins so JOIN public.ediel_messages zm ON zm.id=so.message_id
   WHERE so.company_id=m.company_id AND so.message_code='Z13' AND zm.transaction_reference=own->>'li';
  IF coalesce(cardinality(original_ids),0)=0 THEN line_index:=line_index+1;CONTINUE;END IF;
  known_service:=true;
  -- Service-only legal facts are read only after an independent immutable
  -- service-origin candidate exists. Unrelated local U needs no such authority.
  legal_context:=gridex_ediel_ack_replay.require_current_source_role_v2(m.company_id,m.environment,m.id);
  IF legal_context->>'actorRole' IS DISTINCT FROM 'energy_service_company' OR wire->>'receiver' IS DISTINCT FROM legal_context->>'legalEdielId'
  THEN RETURN known||jsonb_build_object('status','held','objects','[]'::jsonb,'heldObjects','[]'::jsonb,'missing',ARRAY['current_received_reporting_legal_role_required']);END IF;
  IF cardinality(original_ids)<>1 THEN missing:=array_append(missing,'unique_immutable_service_original_required');
  ELSE
   SELECT * INTO z FROM public.ediel_messages WHERE id=original_ids[1];
   SELECT count(*) INTO origin_count FROM gridex_service_permission.origins WHERE message_id=z.id AND company_id=m.company_id;
   IF origin_count<>1 THEN missing:=array_append(missing,'unique_immutable_service_origin_required');
   ELSE
    SELECT * INTO o FROM gridex_service_permission.origins WHERE message_id=z.id AND company_id=m.company_id;
    IF z.company_id IS DISTINCT FROM m.company_id OR z.environment IS DISTINCT FROM m.environment OR z.direction IS DISTINCT FROM 'outbound' OR z.message_standard IS DISTINCT FROM 'edifact' OR z.message_family IS DISTINCT FROM 'PRODAT' OR z.message_code IS DISTINCT FROM 'Z13'
     OR (z.status IN('sent','acknowledged')) IS NOT TRUE OR z.message_sent_at IS NULL OR NOT isfinite(z.message_sent_at) OR z.message_sent_at>s.source_received_at OR z.message_sent_at<z.immutable_rendered_at OR z.immutable_rendered_at IS NULL OR NOT isfinite(z.immutable_rendered_at) OR z.raw_payload IS NULL
     OR z.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') OR o.intent_id IS DISTINCT FROM z.intent_id
     OR o.basis->>'code' IS DISTINCT FROM 'Z13' OR o.basis->>'status' IS DISTINCT FROM 'authorized' OR o.basis->>'companyId' IS DISTINCT FROM m.company_id::text OR o.basis->>'environment' IS DISTINCT FROM m.environment
     OR o.basis->>'assignmentId' IS DISTINCT FROM o.assignment_id::text OR o.basis->>'permissionId' IS DISTINCT FROM o.permission_id::text OR o.basis->>'customerId' IS DISTINCT FROM z.customer_id::text
     OR o.created_at IS NULL OR NOT isfinite(o.created_at) OR o.created_at>z.immutable_rendered_at
    THEN missing:=array_append(missing,'sealed_sent_immutable_service_original_required');
    ELSE
     accepted:=gridex_ediel_transport.accepted_source_basis_v1(z);
     IF accepted IS NULL OR accepted->>'status' IS DISTINCT FROM 'accepted_projection' OR accepted->>'messageId' IS DISTINCT FROM z.id::text OR accepted->>'companyId' IS DISTINCT FROM m.company_id::text OR accepted->>'environment' IS DISTINCT FROM m.environment OR accepted->>'originalHash' IS DISTINCT FROM z.immutable_payload_hash
      OR nullif(accepted->>'observedAt','') IS NULL OR NOT isfinite((accepted->>'observedAt')::timestamptz) OR (accepted->>'observedAt')::timestamptz<z.immutable_rendered_at OR (accepted->>'observedAt')::timestamptz>s.source_received_at
     THEN missing:=array_append(missing,'actual_unique_accepted_original_before_receive_required');END IF;
     original_wire:=gridex_received_sources.permission_partition_wire_v1(z.raw_payload);original_tokens:=gridex_received_sources.closure_wire_tokens_v2(z.raw_payload);original_env:=gridex_ediel_technical_ack.envelope(z.raw_payload);
     original_own:=NULL;original_customer:=NULL;
     SELECT jsonb_agg(x)->0 INTO original_own FROM jsonb_array_elements(original_wire->'objects')x WHERE x->>'li'=own->>'li' HAVING count(*)=1;
     IF original_own IS NOT NULL THEN
      SELECT jsonb_agg(t->'elements'->2)->0 INTO original_customer FROM jsonb_array_elements(original_tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' AND (t->>'index')::int>(original_own->>'firstLineIndex')::int
       AND (t->>'index')::int<coalesce((SELECT min((n->>'index')::int) FROM jsonb_array_elements(original_tokens)n WHERE n->>'tag'='LIN' AND (n->>'index')::int>(original_own->>'firstLineIndex')::int),2147483647) HAVING count(*)=1;
     END IF;
     IF original_wire IS NULL OR original_env IS NULL OR original_own IS NULL OR original_own->>'projectionHeld'='true' OR original_wire->>'code' IS DISTINCT FROM 'Z13'
      OR wire->>'sender' IS DISTINCT FROM original_wire->>'receiver' OR wire->>'receiver' IS DISTINCT FROM original_wire->>'sender'
      OR original_wire->>'sender' IS DISTINCT FROM o.basis->>'legalSenderId' OR original_wire->>'receiver' IS DISTINCT FROM o.basis->>'legalReceiverId'
      OR env->'sender' IS DISTINCT FROM original_env->'receiver' OR env->'receiver' IS DISTINCT FROM original_env->'sender' OR env->>'applicationReference' IS DISTINCT FROM original_env->>'applicationReference' OR env->>'environment' IS DISTINCT FROM original_env->>'environment'
      OR original_customer IS DISTINCT FROM customer_party OR nullif(customer_party->>0,'') IS NULL
      OR original_customer IS DISTINCT FROM (CASE WHEN nullif(o.basis#>>'{customer,org_number}','') IS NOT NULL THEN jsonb_build_array(o.basis#>>'{customer,org_number}','SE1','260') WHEN nullif(o.basis#>>'{customer,personal_number}','') IS NOT NULL THEN jsonb_build_array(o.basis#>>'{customer,personal_number}','SE2','260') ELSE NULL END)
      OR original_own->>'reason' IS DISTINCT FROM own->>'reason' OR original_own->>'reason' IS DISTINCT FROM (CASE o.basis->>'mode' WHEN 'V' THEN 'S17' WHEN 'VH' THEN 'S18' ELSE NULL END)
      OR original_own->>'purpose' IS DISTINCT FROM o.basis->>'purposeCode'
     THEN missing:=array_append(missing,'exact_independent_original_reporting_identity_required');END IF;
     IF (o.basis->>'scopeBasisVersion') ~ '^[1-9][0-9]{0,17}$' THEN basis_version:=(o.basis->>'scopeBasisVersion')::bigint;ELSE basis_version:=NULL;END IF;
     SELECT sv.scope,sv.recorded_at INTO scope,recorded FROM gridex_service_administration.scope_versions sv WHERE sv.company_id=m.company_id AND sv.assignment_id=o.assignment_id AND sv.scope_basis_version=basis_version;
     IF scope IS NULL OR recorded IS NULL OR NOT isfinite(recorded) OR recorded>o.created_at OR scope->>'companyId' IS DISTINCT FROM m.company_id::text OR scope->>'customerId' IS DISTINCT FROM o.basis->>'customerId'
      OR scope->>'environment' IS DISTINCT FROM m.environment OR scope->>'providerActorId' IS DISTINCT FROM o.basis->>'providerActorId' OR scope->>'dsoActorId' IS DISTINCT FROM o.basis->>'dsoActorId' OR scope->>'mode' IS DISTINCT FROM o.basis->>'mode'
      OR scope->>'providerActorId' IS DISTINCT FROM legal_context->>'legalActorId'
     THEN missing:=array_append(missing,'exact_historical_assignment_scope_required');END IF;
     IF (o.basis->>'evidenceId') ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN source_evidence:=(o.basis->>'evidenceId')::uuid;ELSE source_evidence:=NULL;END IF;
     end_review:=NULL;end_archive:=NULL;
     FOREACH evidence_kind IN ARRAY ARRAY['end_user_contract','dso_contract','service_contract','downstream_use','privacy_roles'] LOOP
      qualified_evidence:=false;
      FOR e IN SELECT ev.* FROM public.ediel_service_evidence ev WHERE ev.company_id=m.company_id AND ev.assignment_id=o.assignment_id AND ev.kind=evidence_kind AND (evidence_kind<>'end_user_contract' OR ev.id=source_evidence) LOOP
       IF e.status IS DISTINCT FROM 'verified' THEN CONTINUE;END IF;
       SELECT * INTO latest FROM gridex_ediel_services.reviews rv WHERE rv.company_id=m.company_id AND rv.evidence_id=e.id ORDER BY rv.review_sequence DESC LIMIT 1;
       IF latest.id IS NULL OR latest.decision IS DISTINCT FROM 'approved' OR latest.reviewed_at>clock_at
        OR e.approved_by IS DISTINCT FROM latest.reviewer_user_id OR e.approved_at IS DISTINCT FROM latest.reviewed_at OR e.approved_assignment_version IS DISTINCT FROM latest.scope_basis_version
        OR latest.evidence_basis IS DISTINCT FROM gridex_ediel_services.evidence_basis_v1(e)
        OR gridex_ediel_services.actor_current_v1(m.company_id,latest.reviewer_user_id,true) IS NOT TRUE
        OR NOT EXISTS(SELECT FROM auth.users u WHERE u.id=latest.reviewer_user_id AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=clock_at)) THEN CONTINUE;END IF;
       FOR v IN SELECT rv.* FROM gridex_ediel_services.reviews rv WHERE rv.company_id=m.company_id AND rv.evidence_id=e.id AND rv.scope_basis_version=basis_version AND rv.decision='approved' AND rv.reviewed_at<=o.created_at ORDER BY rv.review_sequence DESC LOOP
        SELECT * INTO a FROM gridex_ediel_services.artifacts ar WHERE ar.id=v.artifact_id AND ar.company_id=m.company_id;
        IF a.id IS NULL OR a.environment IS DISTINCT FROM m.environment OR a.assignment_id IS DISTINCT FROM o.assignment_id OR a.scope_basis_version IS DISTINCT FROM basis_version OR a.scope IS DISTINCT FROM scope
         OR a.scope_hash IS DISTINCT FROM encode(sha256(convert_to(a.scope::text,'UTF8')),'hex') OR a.evidence_kind IS DISTINCT FROM evidence_kind
         OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.source_hash IS DISTINCT FROM e.source_sha256 OR a.source_reference IS DISTINCT FROM e.source_reference OR a.source_version IS DISTINCT FROM e.source_version
         OR a.evidence_terms IS DISTINCT FROM gridex_ediel_services.evidence_terms_v1(e) OR v.evidence_basis IS DISTINCT FROM gridex_ediel_services.evidence_basis_v1(e)
         OR a.archived_at IS NULL OR NOT isfinite(a.archived_at) OR a.archived_at>v.reviewed_at OR v.reviewed_at IS NULL OR NOT isfinite(v.reviewed_at)
         OR NOT EXISTS(SELECT FROM auth.users u WHERE u.id=v.reviewer_user_id AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=clock_at))
         OR gridex_ediel_services.actor_current_v1(m.company_id,v.reviewer_user_id,true) IS NOT TRUE
         OR v.reviewer_user_id=a.submitted_by OR NOT EXISTS(SELECT FROM gridex_service_administration.commands stage WHERE stage.command_id=v.stage_command_id AND stage.company_id=m.company_id AND stage.input->>'action'='stage_evidence' AND stage.result->>'evidenceId'=e.id::text AND stage.actor_user_id<>v.reviewer_user_id AND stage.recorded_at<=v.reviewed_at)
         OR gridex_ediel_services.receipt_current_v1(a) IS NOT TRUE THEN CONTINUE;END IF;
        IF evidence_kind='end_user_contract' AND (e.source_sha256 IS DISTINCT FROM o.basis->>'evidenceSha256' OR e.source_version IS DISTINCT FROM o.basis->>'evidenceVersion'
         OR e.permission_customer_classification IS DISTINCT FROM o.basis->>'customerClassification' OR e.permission_reporting_term_kind IS DISTINCT FROM o.basis->>'reportingTerm' OR e.permission_purpose_code IS DISTINCT FROM o.basis->>'purposeCode') THEN CONTINUE;END IF;
        qualified_evidence:=true;IF evidence_kind='end_user_contract' THEN end_review:=v.reviewed_at;end_archive:=a.archived_at;END IF;EXIT;
       END LOOP;
       IF qualified_evidence THEN EXIT;END IF;
      END LOOP;
      IF NOT qualified_evidence THEN missing:=array_append(missing,'historical_review:'||evidence_kind);END IF;
     END LOOP;
     IF (o.basis->>'customerClassification' IN('private','nonprivate')) IS NOT TRUE OR (o.basis->>'reportingTerm' IN('bounded','indefinite')) IS NOT TRUE
      OR (o.basis->>'customerClassification'='private' AND nullif(o.basis->>'purposeCode','') IS NULL)
      OR (o.basis->>'purposeCode' IS NOT NULL AND (o.basis->>'purposeCode' IN('B71','B72','B73','B74','B75','B76')) IS NOT TRUE)
     THEN missing:=array_append(missing,'explicit_historical_classification_and_reporting_terms_required');END IF;
     IF o.basis->>'reportingTerm'='bounded' THEN
      source_end:=gridex_received_sources.permission_time_v1(original_own->>'reportEnd');
      IF source_end IS NULL OR source_end IS DISTINCT FROM (scope->>'dataEnd')::timestamptz OR source_end IS DISTINCT FROM (o.basis#>>'{objects,0,reportEnd}')::timestamptz THEN missing:=array_append(missing,'independent_bounded_reporting_end_required');END IF;
      term:=jsonb_build_object('kind','bounded','endMinute',original_own->>'reportEnd');
     ELSE
      IF original_own->>'reportEnd' IS NOT NULL OR scope->>'dataEnd' IS NOT NULL OR o.basis#>>'{objects,0,reportEnd}' IS NOT NULL THEN missing:=array_append(missing,'explicit_indefinite_reporting_term_required');END IF;
      term:=jsonb_build_object('kind','indefinite');
     END IF;
     purpose:=CASE WHEN o.basis->>'purposeCode' IS NULL THEN jsonb_build_object('kind','absent') ELSE jsonb_build_object('kind','present','code',o.basis->>'purposeCode') END;
    END IF;
   END IF;
  END IF;
  -- Rebuild the response selector: historical scope was used above only to
  -- qualify source provenance, never to copy installation/values into a reply.
  scope:=jsonb_build_object('lineIndex',line_index,'objectId',own->'point','identityAgency',own->'identityAgency','lineItemReference',own->'li','customer',jsonb_build_object('id',customer_party->>0,'qualifier',customer_party->>1,'agency',customer_party->>2),'reason',own->'reason');
  IF cardinality(missing)>0 THEN held:=held||jsonb_build_array(jsonb_build_object('scope',scope,'missing',missing));
  ELSE result:=result||jsonb_build_array(jsonb_build_object('scope',scope,'classification',o.basis->>'customerClassification','term',term,'purpose',purpose,'original',jsonb_build_object('messageId',z.id,'payloadHash',z.immutable_payload_hash,'originIntentId',o.intent_id,'assignmentId',o.assignment_id,'permissionId',o.permission_id,'scopeBasisVersion',basis_version,'acceptedAttemptId',accepted->>'attemptId','acceptedObservedAt',accepted->>'observedAt','originCreatedAt',o.created_at,'sealedAt',z.immutable_rendered_at,'evidenceId',source_evidence,'evidenceSha256',o.basis->>'evidenceSha256','evidenceVersion',o.basis->>'evidenceVersion','evidenceReviewedAt',end_review,'evidenceArchivedAt',end_archive)));END IF;
  line_index:=line_index+1;
 END LOOP;
 IF NOT known_service AND jsonb_array_length(held)=0 THEN RETURN NULL;END IF;
 RETURN known||jsonb_build_object('status',CASE WHEN jsonb_array_length(result)>0 THEN 'qualified' ELSE 'held' END,'objects',result,'heldObjects',held);
END $_$;

--
-- Name: recovery_reference_wire_data_v1(text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.recovery_reference_wire_data_v1(value text, component text, sep text, release_char text, term text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE out text:='';ch text;pos int;
BEGIN FOR pos IN 1..char_length(value) LOOP ch:=substr(value,pos,1);out:=out||CASE WHEN ch IN(component,sep,release_char,term) THEN release_char ELSE '' END||ch;END LOOP;RETURN out;END$$;

--
-- Name: recovery_source_cohort_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.recovery_source_cohort_v1(c uuid, op_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;ids uuid[]:='{}';seen uuid[]:='{}';i int;
BEGIN
 FOR i IN 1..32 LOOP
  SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=op_id AND company_id=c;
  IF op.id IS NULL THEN IF i=1 THEN RETURN NULL;END IF;RAISE EXCEPTION 'prodat_recovery_source_cohort_changed';END IF;
  IF op.id=ANY(seen) THEN RAISE EXCEPTION 'prodat_recovery_source_cohort_cycle';END IF;
  seen:=array_append(seen,op.id);ids:=array_append(ids,op.original_message_id);
  IF op.source_ack_message_id IS NOT NULL THEN ids:=array_append(ids,op.source_ack_message_id);END IF;
  SELECT operation_id INTO op_id FROM gridex_received_sources.prodat_recovery_messages WHERE message_id=op.original_message_id;
  IF op_id IS NULL THEN RETURN ARRAY(SELECT DISTINCT source_id FROM unnest(ids) source_id ORDER BY source_id);END IF;
 END LOOP;
 RAISE EXCEPTION 'prodat_recovery_source_cohort_bound_exceeded';
END$$;

--
-- Name: regulated_ground_immutable_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.regulated_ground_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'revoked_at') OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN RAISE EXCEPTION 'regulated_ground_source_immutable';END IF;
 RETURN NEW;
END $$;

--
-- Name: reject_mutation(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';
END
$$;

--
-- Name: rejected_identity_scope_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.rejected_identity_scope_v1(raw text, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb; own jsonb; lin jsonb; cci jsonb; cav jsonb; refs jsonb;
 message_end integer; next_index integer; parent_index integer; party_index integer;
 ordinal integer:=0; reason text; message_reason text; own_li text; selected_li text;
 line_refs text[]:=ARRAY[]::text[]; selected boolean:=false;
BEGIN
 IF raw IS NULL OR jsonb_typeof(object_scope) IS DISTINCT FROM 'object'
  OR object_scope->>'disposition' IS DISTINCT FROM 'rejected'
  OR object_scope->'objectId' IS DISTINCT FROM 'null'::jsonb
  OR object_scope->'messageIndex' IS DISTINCT FROM '0'::jsonb
  OR jsonb_typeof(object_scope->'registers') IS DISTINCT FROM 'array'
  OR jsonb_array_length(object_scope->'registers') IS DISTINCT FROM 1
  OR object_scope#>'{registers,0,registerIndex}' IS DISTINCT FROM 'null'::jsonb
  OR object_scope#>'{registers,0,registerPosition}' IS DISTINCT FROM '1'::jsonb THEN RETURN false; END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);
 IF tokens IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1
  OR (SELECT t#>>'{elements,2,0}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH') IS DISTINCT FROM 'PRODAT'
  OR (SELECT t#>>'{elements,1,0}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH') IS DISTINCT FROM object_scope->>'messageReference'
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1
  OR (SELECT t#>>'{elements,1,0}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM') IS DISTINCT FROM 'Z05'
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13')
   <>(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN')
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNT')<>1 THEN RETURN false; END IF;
 SELECT (t->>'index')::integer INTO message_end FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNT';
 IF (SELECT (t->>'index')::integer FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')
   >=(SELECT (t->>'index')::integer FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')
  OR (SELECT (t->>'index')::integer FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')
   >=(SELECT min((t->>'index')::integer) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN') THEN RETURN false; END IF;
 FOR lin IN SELECT t FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' ORDER BY (t->>'index')::integer LOOP
  ordinal:=ordinal+1;
  IF (lin->>'index')::integer>=message_end OR jsonb_array_length(lin->'elements')>4
   OR jsonb_array_length(lin#>'{elements,1}') IS DISTINCT FROM 1
   OR (lin#>>'{elements,1,0}' ~ '^[0-9]{1,6}$') IS NOT TRUE
   OR (lin#>>'{elements,1,0}')::integer<>ordinal THEN RETURN false; END IF;
  SELECT coalesce(min((t->>'index')::integer),message_end) INTO next_index
   FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('LIN','UNT','UNZ') AND (t->>'index')::integer>(lin->>'index')::integer;
  SELECT jsonb_agg(t ORDER BY (t->>'index')::integer) INTO own FROM jsonb_array_elements(tokens)t
   WHERE (t->>'index')::integer>=(lin->>'index')::integer AND (t->>'index')::integer<next_index;
  SELECT min((t->>'index')::integer) INTO parent_index FROM jsonb_array_elements(own)t WHERE t->>'tag' IN('RFF','NAD');
  IF (SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13')<>1 THEN RETURN false; END IF;
  SELECT t INTO cci FROM jsonb_array_elements(own)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13';
  SELECT t INTO cav FROM jsonb_array_elements(own)t WHERE t->>'tag'='CAV' AND (t->>'index')::integer=(cci->>'index')::integer+1;
  IF cav IS NULL OR (parent_index IS NOT NULL AND (cci->>'index')::integer>=parent_index)
   OR jsonb_array_length(cci->'elements')<>3 OR jsonb_array_length(cci#>'{elements,2}')<>1
   OR EXISTS(SELECT FROM jsonb_array_elements(cci#>'{elements,1}')v WHERE v#>>'{}'<>'')
   OR jsonb_array_length(cav->'elements')<>2 OR jsonb_array_length(cav#>'{elements,1}')<>1
   OR EXISTS(SELECT FROM jsonb_array_elements(own)t WHERE t->>'tag'='CAV' AND (t->>'index')::integer=(cav->>'index')::integer+1)
   OR coalesce(cav#>>'{elements,1,0}','') NOT IN('Z25','Z22') THEN RETURN false; END IF;
  reason:=cav#>>'{elements,1,0}';
  IF message_reason IS NOT NULL AND reason<>message_reason THEN RETURN false; END IF;
  message_reason:=reason;
  SELECT min((t->>'index')::integer) INTO party_index FROM jsonb_array_elements(own)t WHERE t->>'tag'='NAD';
  SELECT jsonb_agg(t) INTO refs FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI'
   AND (party_index IS NULL OR (t->>'index')::integer<party_index);
  own_li:=NULL;
  IF jsonb_array_length(refs)=1 AND jsonb_array_length(refs#>'{0,elements,1}')=2
   AND char_length(refs#>>'{0,elements,1,1}') BETWEEN 1 AND 128
   AND refs#>>'{0,elements,1,1}'=btrim(refs#>>'{0,elements,1,1}')
   AND refs#>>'{0,elements,1,1}' !~ '[[:cntrl:]]' THEN own_li:=refs#>>'{0,elements,1,1}'; END IF;
  line_refs:=array_append(line_refs,own_li);
  IF lin->'index'=object_scope#>'{registers,0,segmentIndex}' THEN
   IF nullif(lin#>>'{elements,3,0}','') IS NOT NULL
    OR to_jsonb(nullif(lin#>>'{elements,3,3}','')) IS DISTINCT FROM nullif(object_scope->'identityAgency','null'::jsonb)
    OR object_scope#>'{registers,0,lineIndex}' IS DISTINCT FROM to_jsonb(ordinal-1)
    OR object_scope#>>'{registers,0,lineNumber}' IS DISTINCT FROM lin#>>'{elements,1,0}'
    OR own_li IS NULL THEN RETURN false; END IF;
   selected:=true; selected_li:=own_li;
  END IF;
 END LOOP;
 RETURN selected AND selected_li IS NOT NULL AND (SELECT count(*) FROM unnest(line_refs)r WHERE r=selected_li)=1;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

--
-- Name: rejected_z04h_identity_scope_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.rejected_z04h_identity_scope_v1(raw text, object_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb;lin jsonb;cci jsonb;cav jsonb;unb jsonb;unh jsonb;bgm jsonb;own_li text;party integer;n integer;data_sep text:=CASE WHEN left(raw,3)='UNA' THEN substr(raw,5,1) ELSE '+' END;component_sep text:=CASE WHEN left(raw,3)='UNA' THEN substr(raw,4,1) ELSE ':' END;
BEGIN
 IF raw IS NULL OR octet_length(raw)>262144 OR jsonb_typeof(object_scope) IS DISTINCT FROM 'object'
  OR object_scope->>'disposition' IS DISTINCT FROM 'rejected' OR object_scope->'objectId' IS DISTINCT FROM 'null'::jsonb
  OR object_scope->'messageIndex' IS DISTINCT FROM '0'::jsonb
  OR jsonb_typeof(object_scope->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(object_scope->'registers')<>1
  OR object_scope#>'{registers,0,lineIndex}' IS DISTINCT FROM '0'::jsonb
  OR object_scope#>'{registers,0,registerIndex}' IS DISTINCT FROM 'null'::jsonb
  OR object_scope#>'{registers,0,registerPosition}' IS DISTINCT FROM '1'::jsonb
  OR object_scope#>>'{registers,0,lineNumber}' IS DISTINCT FROM '1' THEN RETURN false;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNT')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CCI' AND upper(btrim(t#>>'{elements,2,0}'))='Z13')<>1 THEN RETURN false;END IF;
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';
 SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';
 SELECT t INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 SELECT t INTO lin FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN';
 SELECT t INTO cci FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CCI' AND t#>>'{elements,2,0}'='Z13';
 SELECT t INTO cav FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CAV' AND (t->>'index')::integer=(cci->>'index')::integer+1;
 IF unb#>'{elements,7}' IS DISTINCT FROM '["23-DDQ-PRODAT"]'::jsonb
  OR unh#>'{elements,2}' IS DISTINCT FROM '["PRODAT","D","97A","UN","E2SE6A"]'::jsonb
  OR unh#>>'{elements,1,0}' IS DISTINCT FROM object_scope->>'messageReference'
  OR bgm#>'{elements,1}' IS DISTINCT FROM '["Z04"]'::jsonb OR (bgm->>'index')::integer>=(lin->>'index')::integer
  OR lin->'index' IS DISTINCT FROM object_scope#>'{registers,0,segmentIndex}'
  OR jsonb_array_length(lin->'elements')<>4 OR lin#>'{elements,1}' IS DISTINCT FROM '["1"]'::jsonb
  OR jsonb_array_length(lin#>'{elements,3}')<>4 OR lin#>'{elements,3,0}' IS DISTINCT FROM '""'::jsonb
  OR lin#>'{elements,3,1}' IS DISTINCT FROM '""'::jsonb OR lin#>'{elements,3,2}' IS DISTINCT FROM '""'::jsonb
  OR (lin#>>'{elements,3,3}' IN('9','89')) IS NOT TRUE
  OR to_jsonb(lin#>>'{elements,3,3}') IS DISTINCT FROM object_scope->'identityAgency'
  OR cci IS NULL OR cav IS NULL OR jsonb_array_length(cci->'elements')<>3
  OR cci#>'{elements,1}' IS DISTINCT FROM '[""]'::jsonb OR cci#>'{elements,2}' IS DISTINCT FROM '["Z13"]'::jsonb
  OR jsonb_array_length(cav->'elements')<>2 OR jsonb_array_length(cav#>'{elements,1}') NOT BETWEEN 1 AND 5
  OR cav#>>'{elements,1,0}' IS DISTINCT FROM 'Z25'
  OR EXISTS(SELECT FROM jsonb_array_elements(cav#>'{elements,1}')WITH ORDINALITY v(value,ord) WHERE ord>1 AND value IS DISTINCT FROM '""'::jsonb)
  OR gridex_received_sources.rejected_z04h_raw_segment_v1(raw,(cci->>'index')::integer) IS DISTINCT FROM 'CCI'||data_sep||data_sep||'Z13'
  OR gridex_received_sources.rejected_z04h_raw_segment_v1(raw,(cav->>'index')::integer) IS DISTINCT FROM 'CAV'||data_sep||'Z25'||repeat(component_sep,jsonb_array_length(cav#>'{elements,1}')-1)
  OR (cci->>'index')::integer<=(lin->>'index')::integer
  OR EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='CAV' AND (t->>'index')::integer=(cav->>'index')::integer+1)
 THEN RETURN false;END IF;
 SELECT min((t->>'index')::integer) INTO party FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('NAD','RFF') AND (t->>'index')::integer>(lin->>'index')::integer;
 IF party IS NOT NULL AND (cci->>'index')::integer>=party THEN RETURN false;END IF;
 SELECT min((t->>'index')::integer) INTO party FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('NAD','UNT') AND (t->>'index')::integer>(lin->>'index')::integer;
 SELECT count(*),min(t#>>'{elements,1,1}') INTO n,own_li FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF'
  AND t#>>'{elements,1,0}'='LI' AND (t->>'index')::integer>(lin->>'index')::integer AND (t->>'index')::integer<party
  AND jsonb_array_length(t->'elements')=2 AND jsonb_array_length(t#>'{elements,1}')=2;
 IF n<>1 OR own_li IS NULL OR length(own_li) NOT BETWEEN 1 AND 128 OR own_li<>btrim(own_li) OR own_li~'[[:cntrl:]]'
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI')<>1 THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: rejected_z04h_raw_segment_v1(text, integer); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.rejected_z04h_raw_segment_v1(raw text, wanted integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE body text;ch text;current text:='';released boolean:=false;idx integer:=0;
 release_char text:=CASE WHEN left(raw,3)='UNA' THEN substr(raw,7,1) ELSE '?' END;
 terminator text:=CASE WHEN left(raw,3)='UNA' THEN substr(raw,9,1) ELSE '''' END;
BEGIN
 IF raw IS NULL OR octet_length(raw)>262144 OR wanted NOT BETWEEN 0 AND 4095 THEN RETURN NULL;END IF;
 body:=CASE WHEN left(raw,3)='UNA' THEN substr(raw,10) ELSE raw END;
 body:=replace(replace(body,E'\r\n',''),E'\n','');
 FOREACH ch IN ARRAY string_to_array(body,NULL) LOOP
  IF released THEN current:=current||ch;released:=false;
  ELSIF ch=release_char THEN current:=current||ch;released:=true;
  ELSIF ch=terminator THEN
   IF btrim(current,E' \t')<>'' THEN
    IF idx=wanted THEN RETURN current;END IF;
    idx:=idx+1;
   END IF;current:='';
  ELSE current:=current||ch;END IF;
 END LOOP;
 RETURN NULL;
END $$;

--
-- Name: render_owned_li_repair_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.render_owned_li_repair_v1(raw text, allocations jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);sep text:='+';component text:=':';release_char text:='?';term text:='''';prefix text:='';start_pos int:=1;pos int;ch text;escaped boolean:=false;seg text;normalized text;token jsonb;idx int:=0;out text:='';allocation jsonb;remove_this boolean;first_sep int;second_sep int;new_count int;unh_index int;unt_index int;remove_count int;part_pos int;part_char text;part_released boolean;
BEGIN
 IF tokens IS NULL OR jsonb_typeof(allocations) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'prodat_recovery_li_wire_required';END IF;
 IF upper(left(raw,3))='UNA' THEN prefix:=left(raw,9);start_pos:=10;component:=substr(raw,4,1);sep:=substr(raw,5,1);release_char:=substr(raw,7,1);term:=substr(raw,9,1);END IF;
 SELECT(x->>'index')::int INTO STRICT unh_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH';SELECT(x->>'index')::int INTO STRICT unt_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNT';
 SELECT count(*) INTO remove_count FROM jsonb_array_elements(allocations)x WHERE x->>'inputLiIndex' IS NOT NULL;
 new_count:=unt_index-unh_index+1+jsonb_array_length(allocations)-remove_count;
 FOR pos IN start_pos..char_length(raw) LOOP
  ch:=substr(raw,pos,1);IF ch IN(E'\r',E'\n') THEN CONTINUE;END IF;IF escaped THEN escaped:=false;CONTINUE;ELSIF ch=release_char THEN escaped:=true;CONTINUE;END IF;
  IF ch<>term THEN CONTINUE;END IF;
  seg:=substr(raw,start_pos,pos-start_pos+1);start_pos:=pos+1;normalized:=replace(replace(left(seg,char_length(seg)-1),E'\r\n',''),E'\n','');
  IF btrim(normalized,E' \t')='' THEN out:=out||seg;CONTINUE;END IF;
  SELECT x INTO STRICT token FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int=idx;
  remove_this:=EXISTS(SELECT FROM jsonb_array_elements(allocations)a WHERE(a->>'inputLiIndex')::int=idx);
  IF remove_this AND(token->>'tag' IS DISTINCT FROM 'RFF' OR token#>>'{elements,1,0}' IS DISTINCT FROM 'LI') THEN RAISE EXCEPTION 'prodat_recovery_li_splice_scope_changed';END IF;
  IF NOT remove_this THEN
   IF token->>'tag'='UNT' THEN
    first_sep:=0;second_sep:=0;part_released:=false;
    FOR part_pos IN 1..char_length(seg) LOOP
     part_char:=substr(seg,part_pos,1);IF part_char IN(E'\r',E'\n') THEN CONTINUE;END IF;
     IF part_released THEN part_released:=false;CONTINUE;ELSIF part_char=release_char THEN part_released:=true;CONTINUE;END IF;
     IF part_char=sep THEN IF first_sep=0 THEN first_sep:=part_pos;ELSE second_sep:=part_pos;EXIT;END IF;END IF;
    END LOOP;
    IF first_sep=0 OR second_sep<=first_sep THEN RAISE EXCEPTION 'prodat_recovery_li_unt_required';END IF;
    seg:=left(seg,first_sep)||gridex_received_sources.recovery_reference_wire_data_v1(new_count::text,component,sep,release_char,term)||substr(seg,second_sep);
   END IF;
   out:=out||seg;
   SELECT a INTO allocation FROM jsonb_array_elements(allocations)a WHERE(a->>'inputFirstLineIndex')::int=idx;
   IF allocation IS NOT NULL THEN IF token->>'tag' IS DISTINCT FROM 'LIN' OR allocation->>'reference' !~ '^[A-Z0-9]{35}$' THEN RAISE EXCEPTION 'prodat_recovery_li_splice_scope_changed';END IF;
    out:=out||gridex_received_sources.recovery_reference_wire_data_v1('RFF',component,sep,release_char,term)||sep||gridex_received_sources.recovery_reference_wire_data_v1('LI',component,sep,release_char,term)||component||gridex_received_sources.recovery_reference_wire_data_v1(allocation->>'reference',component,sep,release_char,term)||term;
   END IF;
  END IF;
  idx:=idx+1;
 END LOOP;
 IF idx<>jsonb_array_length(tokens) OR btrim(substr(raw,start_pos),E' \t\r\n')<>'' OR escaped THEN RAISE EXCEPTION 'prodat_recovery_li_splice_framing_changed';END IF;
 RETURN prefix||out||substr(raw,start_pos);
END$_$;

--
-- Name: require_domain_response_at_birth_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_domain_response_at_birth_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;initial jsonb;actual jsonb;final_facet jsonb;positive_indices integer[];w gridex_ediel_outbound_owner.witnesses%rowtype;
 existing gridex_ediel_ack_guide.prodat_structural_response_bindings%rowtype;facet_text text;facet_hash text;
BEGIN
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'APERAK' OR NEW.raw_payload IS NULL
  OR(TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL) THEN RETURN NEW;END IF;
 SELECT * INTO s FROM public.ediel_messages WHERE id=NEW.related_message_id AND company_id=NEW.company_id AND environment=NEW.environment
  AND direction='inbound' AND message_family='PRODAT' FOR SHARE;
 IF s.id IS NULL OR(s.message_code NOT IN('Z04','Z05','Z14','Z15') AND NOT(s.message_code='Z06' AND EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=s.id AND v.company_id=s.company_id AND v.environment=s.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL))) THEN RETURN NEW;END IF;
 PERFORM src.source_message_id FROM gridex_received_sources.sources src WHERE src.source_message_id=s.id AND src.company_id=s.company_id AND src.environment=s.environment FOR UPDATE;
 SELECT * INTO w FROM gridex_ediel_outbound_owner.witnesses WHERE id=(NEW.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid FOR SHARE;
 IF w.id IS NULL OR w.company_id IS DISTINCT FROM NEW.company_id OR w.environment IS DISTINCT FROM NEW.environment OR w.related_message_id IS DISTINCT FROM s.id
  OR w.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_domain_response_frozen_owner_required';END IF;
 SELECT * INTO existing FROM gridex_ediel_ack_guide.prodat_structural_response_bindings WHERE witness_id=w.id;
 IF existing.witness_id IS NOT NULL THEN
  IF existing.source_message_id IS DISTINCT FROM s.id OR existing.company_id IS DISTINCT FROM NEW.company_id OR existing.environment IS DISTINCT FROM NEW.environment
   OR existing.ack_hash IS DISTINCT FROM w.payload_sha256 OR existing.facet_hash IS DISTINCT FROM encode(sha256(convert_to(existing.facet_text,'UTF8')),'hex')
   OR existing.facet_text::jsonb->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_domain_response_frozen_owner_changed';END IF;
  -- The actual prepare already froze committed effects. Do not reselect a
  -- newer canonical leaf or independent role when consuming that same seal.
  RETURN NEW;
 END IF;
 initial:=gridex_received_sources.require_prodat_responses_v1(NEW.company_id,s.id);
 actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(NEW.raw_payload,initial->'objects');
 SELECT array_agg(DISTINCT(x->>'lineIndex')::integer ORDER BY(x->>'lineIndex')::integer) INTO positive_indices FROM jsonb_array_elements(actual)x WHERE x->>'ercCode'='100';
 IF positive_indices IS NULL THEN RETURN NEW;END IF;
 final_facet:=gridex_received_sources.prodat_structural_response_v1(NEW.company_id,s.id,positive_indices);
 IF final_facet IS NULL THEN RAISE EXCEPTION 'prodat_domain_response_own_effect_required';END IF;
 facet_text:=final_facet::text;facet_hash:=encode(sha256(convert_to(facet_text,'UTF8')),'hex');
 INSERT INTO gridex_ediel_ack_guide.prodat_structural_response_bindings VALUES(w.id,s.id,NEW.company_id,NEW.environment,w.payload_sha256,facet_text,facet_hash);
 RETURN NEW;
END $$;

--
-- Name: require_established_recovery_source_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_established_recovery_source_v1(c uuid, operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;m public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;q jsonb;
BEGIN
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=operation_id AND company_id=c;
 IF op.id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_established_operation_required';END IF;
 -- Provenance actor is passed solely to the unchanged immutable-operation
 -- identity comparison. The private qualifier has no execution gate or INSERT.
 q:=gridex_received_sources.qualify_established_recovery_source_v1(c,op.original_message_id,op.actor_user_id,op.id,op.source_ack_message_id,op.previous_attempt_id,op.corrected_raw_payload);
 IF q->>'status' IS DISTINCT FROM 'authorized' OR q->>'operationId' IS DISTINCT FROM op.id::text THEN RAISE EXCEPTION 'prodat_recovery_source_context_held';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=c FOR SHARE;
 IF m.environment IS DISTINCT FROM op.environment OR m.immutable_payload_hash IS DISTINCT FROM op.original_payload_hash
  OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_current_source_required';END IF;
 IF op.kind IN('contrl_correction','aperak_correction') THEN
  SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=op.source_ack_message_id AND company_id=c AND environment=op.environment FOR SHARE;
  IF op.source_ack_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')
   OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(op.corrected_raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_current_source_required';END IF;
 END IF;
 RETURN q;
END$$;

--
-- Name: require_prodat_application_objects_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_prodat_application_objects_v1(c uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a gridex_received_sources.validation_assessments%rowtype;f gridex_received_sources.prodat_application_facets%rowtype;r gridex_received_sources.prodat_response_facets%rowtype;basis jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'prodat_application_original_owner_unavailable';END IF;
 SELECT v.* INTO a FROM gridex_received_sources.validation_assessments v WHERE v.company_id=c AND v.source_message_id=source_id AND v.environment=m.environment
  AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
  AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 SELECT * INTO f FROM gridex_received_sources.prodat_application_facets WHERE assessment_id=a.id AND company_id=c AND source_message_id=source_id AND environment=m.environment AND source_payload_hash=a.source_payload_hash;
 SELECT * INTO r FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id;
 IF a.id IS NULL OR f.assessment_id IS NULL OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
  OR f.application_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.application_facts_text,'UTF8')),'hex') OR NOT coalesce(gridex_received_sources.validate_prodat_application_v2(c,source_id,m.raw_payload,a.facts_text::jsonb,f.application_facts_text::jsonb,r.response_facts_text::jsonb,(SELECT sf.function_facts_text::jsonb FROM gridex_received_sources.prodat_source_function_facets sf WHERE sf.assessment_id=a.id AND sf.company_id=c AND sf.source_message_id=source_id AND sf.environment=m.environment AND sf.source_payload_hash=a.source_payload_hash AND sf.function_facts_hash=encode(sha256(convert_to(sf.function_facts_text,'UTF8')),'hex'))),false) THEN RAISE EXCEPTION 'prodat_application_original_owner_unavailable';END IF;
 basis:=gridex_ediel_source_rules.require_v1(c,source_id);
 IF a.facts_text::jsonb->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version',
  'snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'prodat_application_original_rule_witness_mismatch';END IF;
 RETURN f.application_facts_text::jsonb||jsonb_build_object('assessmentId',a.id);
END $$;

--
-- Name: require_prodat_responses_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_prodat_responses_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;a gridex_received_sources.validation_assessments%rowtype;f gridex_received_sources.prodat_response_facets%rowtype;basis jsonb;facts jsonb;facet jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE id=p_source AND company_id=p_company FOR SHARE;
 IF s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 SELECT v.* INTO a FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id) AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 SELECT * INTO f FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=a.source_payload_hash;
 IF a.id IS NULL OR f.assessment_id IS NULL OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR f.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.response_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 facts:=a.facts_text::jsonb;facet:=f.response_facts_text::jsonb;
 IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,facts,facet),false) THEN RAISE EXCEPTION 'prodat_response_original_owner_unavailable';END IF;
 basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
 IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version','snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'prodat_response_original_rule_witness_mismatch';END IF;
 RETURN facet||jsonb_build_object('assessmentId',a.id);
END $$;

--
-- Name: require_prodat_source_function_objects_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_prodat_source_function_objects_v1(c uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE application jsonb;a gridex_received_sources.validation_assessments%rowtype;f gridex_received_sources.prodat_source_function_facets%rowtype;m public.ediel_messages%rowtype;context_xmin numeric;
BEGIN
 application:=gridex_received_sources.require_prodat_application_objects_v1(c,source_id);
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=(application->>'assessmentId')::uuid;
 SELECT * INTO f FROM gridex_received_sources.prodat_source_function_facets WHERE assessment_id=a.id AND company_id=c AND source_message_id=source_id AND environment=a.environment AND source_payload_hash=a.source_payload_hash;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 IF f.assessment_id IS NULL OR f.function_facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.function_facts_text,'UTF8')),'hex')
  OR gridex_received_sources.validate_prodat_source_function_v1(c,source_id,m.raw_payload,a.facts_text::jsonb,f.function_facts_text::jsonb) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_source_function_original_owner_unavailable';END IF;
 RETURN f.function_facts_text::jsonb||jsonb_build_object('assessmentId',a.id);
END $$;

--
-- Name: require_production_contract_before_brp_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_production_contract_before_brp_current_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.production_contract_origins%rowtype;e gridex_received_sources.production_contract_events%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;point public.metering_points%rowtype;b jsonb;w jsonb;q jsonb;period gridex_received_sources.production_contract_periods%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype;original public.ediel_messages%rowtype;original_wire jsonb;actual_dates jsonb;original_dates jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'production_contract_current_message_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' THEN RETURN;END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE company_id=p_company_id AND message_id=m.id;
 w:=gridex_received_sources.prodat_recovery_wire_v1(m.raw_payload);
 IF o.event_id IS NULL THEN
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(coalesce(w->'objects','[]')) own WHERE own->>'reason'='Z70') THEN RETURN;END IF;
  SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
  IF op.id IS NOT NULL THEN
   PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,m.id);
   SELECT * INTO original FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id FOR SHARE;
   original_wire:=gridex_received_sources.prodat_recovery_wire_v1(original.raw_payload);
   IF original.id IS NULL OR m.original_message_id IS DISTINCT FROM original.id::text OR m.source_operation_id IS DISTINCT FROM op.id::text OR (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR op.corrected_raw_payload IS DISTINCT FROM m.raw_payload OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
    OR original_wire->>'legalSender' IS DISTINCT FROM w->>'legalSender' OR original_wire->>'legalReceiver' IS DISTINCT FROM w->>'legalReceiver' OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1 OR (w#>'{objects,0}'-'li'-'line') IS DISTINCT FROM (original_wire#>'{objects,0}'-'li'-'line') THEN RAISE EXCEPTION 'production_contract_recovery_source_scope_required';END IF;
   SELECT jsonb_agg(token->'elements'->1 ORDER BY token->>'index') INTO actual_dates FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(m.raw_payload)) token WHERE token->>'tag'='DTM' AND token#>>'{elements,1,0}' IN('92','93','157');
   SELECT jsonb_agg(token->'elements'->1 ORDER BY token->>'index') INTO original_dates FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(original.raw_payload)) token WHERE token->>'tag'='DTM' AND token#>>'{elements,1,0}' IN('92','93','157');
   IF actual_dates IS DISTINCT FROM original_dates THEN RAISE EXCEPTION 'production_contract_recovery_boundary_scope_required';END IF;
   PERFORM gridex_received_sources.require_production_contract_source_current_v1(p_company_id,original.id,p_actor_user_id);
   PERFORM gridex_ediel_transport.require_message_intent_v1(m);
   RETURN;
  END IF;
  -- A test environment alone cannot originate a production-contract event.
  IF m.environment IS DISTINCT FROM 'test' THEN RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) AND EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN RAISE EXCEPTION 'production_contract_fixture_source_ambiguous';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_positive_message_v1(p_company_id,m.id,'Z09');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_positive_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'positive' OR q->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'production_contract_fixture_scope_required';END IF;
  ELSIF EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_negative_message_v1(p_company_id,m.id,'Z09');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_negative_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'negative' OR jsonb_typeof(q->'expectedDiagnosticCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'expectedDiagnosticCodes') NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'production_contract_fixture_scope_required';END IF;
  ELSE RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
  IF q->>'companyId' IS DISTINCT FROM p_company_id::text OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'production_contract_fixture_supplier_required';END IF;
  RETURN;
 END IF;
 b:=gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,o.event_id,p_actor_user_id,'communication.send');
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'production_contract_current_source_required';END IF;
 SELECT * INTO STRICT e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id AND company_id=p_company_id;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=e.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO period FROM gridex_received_sources.production_contract_periods WHERE start_event_id=CASE WHEN e.event_kind='signed' THEN e.id ELSE e.start_event_id END AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR point.id IS NULL OR period.start_event_id IS NULL OR w IS NULL OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.source_operation_id IS DISTINCT FROM e.id::text
 OR m.environment IS DISTINCT FROM e.environment OR m.customer_id IS DISTINCT FROM e.customer_id OR m.metering_point_id IS DISTINCT FROM e.metering_point_id OR m.site_id IS DISTINCT FROM point.site_id OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 OR i.operation_id IS DISTINCT FROM e.id OR i.ediel_message_id IS DISTINCT FROM m.id OR i.outbound_request_id IS DISTINCT FROM r.id OR i.validation_status IS DISTINCT FROM 'validated'
 OR (r.payload->>'environment') IS DISTINCT FROM e.environment OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata' OR r.customer_id IS DISTINCT FROM e.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM e.metering_point_id
 OR period.environment IS DISTINCT FROM e.environment OR period.contract_id IS DISTINCT FROM e.contract_id OR period.customer_id IS DISTINCT FROM e.customer_id OR period.metering_point_id IS DISTINCT FROM e.metering_point_id OR (e.event_kind='signed' AND (period.start_at IS DISTINCT FROM e.boundary_at OR period.end_at IS NOT NULL)) OR (e.event_kind='ceased' AND (period.end_event_id IS DISTINCT FROM e.id OR period.end_at IS DISTINCT FROM e.boundary_at))
 OR w->>'code' IS DISTINCT FROM 'Z09' OR w->>'legalSender' IS DISTINCT FROM e.legal_sender_id OR w->>'legalReceiver' IS DISTINCT FROM e.legal_receiver_id OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1 OR w#>>'{objects,0,reason}' IS DISTINCT FROM 'Z70' OR w#>>'{objects,0,point}' IS DISTINCT FROM e.point_id OR w#>>'{objects,0,identityAgency}' IS DISTINCT FROM e.identity_agency
 THEN RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
END $$;

--
-- Name: require_production_contract_source_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_production_contract_source_current_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.production_contract_origins%rowtype;b jsonb;original public.ediel_messages%rowtype;
BEGIN
 PERFORM gridex_received_sources.require_production_contract_before_brp_current_v1(p_company_id,p_message_id,p_actor_user_id);
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' THEN RETURN;END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE message_id=m.id AND company_id=p_company_id;
 IF o.event_id IS NOT NULL THEN
  b:=gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,o.event_id,p_actor_user_id,'communication.send');
  IF b->>'status' IS DISTINCT FROM 'authorized' OR gridex_received_sources.outbound_single_brp_v1(m.raw_payload) IS DISTINCT FROM b->>'brpEdielId' THEN RAISE EXCEPTION 'production_contract_current_physical_brp_required';END IF;RETURN;
 END IF;
 -- The delegated owner has already qualified this recovery's exact original,
 -- scope and current authentic source. Keep its physical262 through correction.
 SELECT source.* INTO original FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id JOIN public.ediel_messages source ON source.id=operation.original_message_id AND source.company_id=operation.company_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
 IF original.id IS NOT NULL AND gridex_received_sources.outbound_single_brp_v1(m.raw_payload) IS DISTINCT FROM gridex_received_sources.outbound_single_brp_v1(original.raw_payload) THEN RAISE EXCEPTION 'production_contract_recovery_physical_brp_changed';END IF;
END$$;

--
-- Name: require_recovery_execution_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_recovery_execution_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed timestamptz;wanted text;
BEGIN
 IF c IS NULL OR actor IS NULL OR (phase IN('read','prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_recovery_execution_scope_required';END IF;
 wanted:=CASE phase WHEN 'read' THEN 'communication.read' WHEN 'prepare' THEN 'communication.write' ELSE 'communication.send' END;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM 1 FROM auth.users u WHERE u.id=actor FOR SHARE;
 PERFORM 1 FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM 1 FROM public.companies x WHERE x.id=c FOR SHARE;
 PERFORM 1 FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 observed:=clock_timestamp();
 IF NOT EXISTS(SELECT FROM auth.users u WHERE u.id=actor AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=observed))
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active' AND to_jsonb(u)->>'disabled_at' IS NULL)
  OR NOT EXISTS(SELECT FROM public.companies x WHERE x.id=c AND x.status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.permissions p WHERE p.key=wanted AND p.is_active)
  OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,wanted),false)
 THEN RAISE EXCEPTION 'prodat_recovery_execution_actor_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: require_recovery_insert_origin_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_recovery_insert_origin_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;o gridex_received_sources.prodat_recovery_origins%rowtype;i public.ediel_message_intents%rowtype;
BEGIN
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id::text=NEW.source_operation_id AND kind IN ('contrl_correction','aperak_correction');
 IF NOT FOUND THEN RETURN NEW;END IF;
 PERFORM public.ediel_prodat_recovery_operation_basis_v1(op.company_id,op.id,NEW.created_by);
 SELECT * INTO o FROM gridex_received_sources.prodat_recovery_origins WHERE operation_id=op.id;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=op.company_id FOR SHARE;
 PERFORM public.ediel_reserve_prodat_recovery_origin_v1(op.company_id,op.id,NEW.created_by,o.intent_id,o.outbound_request_id);
 IF o.operation_id IS NULL OR i.id IS NULL OR NEW.company_id IS DISTINCT FROM o.company_id OR NEW.intent_id IS DISTINCT FROM o.intent_id OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id
 OR NEW.environment IS DISTINCT FROM i.environment OR NEW.message_family IS DISTINCT FROM i.message_family OR NEW.message_code IS DISTINCT FROM i.message_code OR NEW.customer_id IS DISTINCT FROM i.customer_id
 OR NEW.raw_payload IS DISTINCT FROM op.corrected_raw_payload OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.original_message_id IS DISTINCT FROM op.original_message_id::text THEN RAISE EXCEPTION 'prodat_recovery_private_origin_required';END IF;
 RETURN NEW;
END $$;

--
-- Name: require_supply_scope_admission_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_supply_scope_admission_v1(c uuid, source_id uuid, scope jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a gridex_received_sources.validation_assessments%rowtype;application jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=c AND id=source_id FOR UPDATE;
 application:=gridex_received_sources.require_prodat_application_objects_v1(c,source_id);
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE company_id=c AND source_message_id=source_id AND id=(application->>'assessmentId')::uuid FOR SHARE;
 IF m.id IS NULL OR a.id IS NULL OR a.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR a.environment IS DISTINCT FROM m.environment
  OR a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR gridex_received_sources.prodat_application_object_accepted_v1(c,source_id,a.id,scope) IS NOT TRUE THEN RAISE EXCEPTION 'supply_own_canonical_application_and_function_required';END IF;
 RETURN a.id;
END$$;

--
-- Name: require_switch_brp_source_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_switch_brp_source_current_v1(c uuid, message uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.switch_brp_source_bindings%rowtype;b jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' OR NOT EXISTS(SELECT FROM gridex_received_sources.switch_originals o WHERE o.message_id=m.id AND o.company_id=c) THEN RETURN;END IF;
 SELECT * INTO s FROM gridex_received_sources.switch_brp_source_bindings WHERE message_id=m.id AND company_id=c;
 IF s.message_id IS NULL THEN RAISE EXCEPTION 'switch_historical_brp_source_unavailable';END IF;
 b:=gridex_received_sources.switch_brp_source_basis_v1(c,m.id,actor,'send');
 IF b IS DISTINCT FROM s.source_basis OR s.brp_ediel_id IS DISTINCT FROM b->>'brpEdielId' OR s.payload_hash IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'switch_current_brp_source_changed';END IF;
END$$;

--
-- Name: require_switch_contract_request_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_switch_contract_request_current_v1(c uuid, message uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;binding gridex_received_sources.switch_contract_request_bindings%rowtype;basis jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' THEN RETURN;END IF;
 -- Cancellation has its own withdrawal authority. Genuine consumed fixtures
 -- have their own normal canonical owner and never create a live switch original.
 IF NOT EXISTS(SELECT FROM gridex_received_sources.switch_originals o WHERE o.message_id=m.id AND o.company_id=c) THEN RETURN;END IF;
 SELECT * INTO binding FROM gridex_received_sources.switch_contract_request_bindings WHERE message_id=m.id AND company_id=c;
 IF binding.message_id IS NULL THEN RAISE EXCEPTION 'switch_historical_requested_method_basis_unavailable';END IF;
 basis:=gridex_received_sources.switch_contract_request_basis_v1(c,m.id,actor,'send');
 IF basis IS DISTINCT FROM binding.source_basis OR binding.requested_method IS DISTINCT FROM basis->>'requestedMethod' OR binding.declaration_id::text IS DISTINCT FROM basis->>'declarationId' OR binding.payload_hash IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'switch_current_requested_method_declaration_changed';END IF;
END$$;

--
-- Name: require_utilts_functional_responses_retained_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_functional_responses_retained_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;assessment gridex_received_sources.validation_assessments%rowtype;facet gridex_received_sources.utilts_functional_validations%rowtype;
 transaction_facet gridex_received_sources.utilts_transaction_validations%rowtype;facts jsonb;projection jsonb;transactions jsonb;basis jsonb;responses jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE company_id=p_company AND id=p_source FOR SHARE;
 IF s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'UTILTS' THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT v.* INTO assessment FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment
  AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
  AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 IF assessment.id IS NULL OR assessment.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR assessment.facts_hash IS DISTINCT FROM encode(sha256(convert_to(assessment.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO facet FROM gridex_received_sources.utilts_functional_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 SELECT * INTO transaction_facet FROM gridex_received_sources.utilts_transaction_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 IF facet.assessment_id IS NULL OR facet.functional_facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.functional_facts_text,'UTF8')),'hex')
  OR transaction_facet.assessment_id IS NULL OR transaction_facet.transaction_facts_hash IS DISTINCT FROM encode(sha256(convert_to(transaction_facet.transaction_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 facts:=assessment.facts_text::jsonb;projection:=facet.functional_facts_text::jsonb;transactions:=transaction_facet.transaction_facts_text::jsonb;
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'functionalDecision','') NOT IN ('rejected','manual_review')
  OR NOT coalesce(gridex_received_sources.validate_utilts_functional_v1(s.raw_payload,projection,transactions),false) THEN RAISE EXCEPTION 'utilts_functional_owner_outcome_mismatch' USING ERRCODE='P0U01'; END IF;
 basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
 IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version',
  'snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'utilts_functional_original_rule_witness_mismatch' USING ERRCODE='P0U01'; END IF;
 SELECT jsonb_agg(value||jsonb_build_object('errorCodes',(SELECT jsonb_agg(error_item->'code' ORDER BY error_ord) FROM jsonb_array_elements(value->'errors') WITH ORDINALITY errors(error_item,error_ord))) ORDER BY ord)
  INTO responses FROM jsonb_array_elements(projection->'transactions') WITH ORDINALITY t(value,ord);
 RETURN jsonb_build_object('version',1,'assessmentId',assessment.id,'sourcePayloadHash',assessment.source_payload_hash,'transactions',responses);
END $$;

--
-- Name: require_utilts_functional_responses_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_functional_responses_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 -- Never fall back to an older facet when the latest leaf lacks a v2 receipt
 -- or is uncommitted. Each retained/new owner performs its own exact checks.
 IF EXISTS(SELECT FROM gridex_received_sources.validation_assessments a JOIN gridex_received_sources.utilts_functional_validations_v2 f ON f.assessment_id=a.id
  WHERE a.company_id=p_company AND a.source_message_id=p_source AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)) THEN
  RETURN gridex_received_sources.require_utilts_functional_responses_v2(p_company,p_source);
 END IF;
 RETURN gridex_received_sources.require_utilts_functional_responses_retained_v1(p_company,p_source);
END $$;

--
-- Name: require_utilts_functional_responses_v2(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_functional_responses_v2(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;assessment gridex_received_sources.validation_assessments%rowtype;facet gridex_received_sources.utilts_functional_validations_v2%rowtype;
 transaction_facet gridex_received_sources.utilts_transaction_validations%rowtype;facts jsonb;projection jsonb;transactions jsonb;basis jsonb;responses jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE company_id=p_company AND id=p_source FOR SHARE;
 IF s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'UTILTS' THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT v.* INTO assessment FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment
  AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
  AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 IF assessment.id IS NULL OR assessment.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR assessment.facts_hash IS DISTINCT FROM encode(sha256(convert_to(assessment.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO facet FROM gridex_received_sources.utilts_functional_validations_v2 WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 SELECT * INTO transaction_facet FROM gridex_received_sources.utilts_transaction_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 IF facet.assessment_id IS NULL OR facet.functional_facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.functional_facts_text,'UTF8')),'hex')
  OR transaction_facet.assessment_id IS NULL OR transaction_facet.transaction_facts_hash IS DISTINCT FROM encode(sha256(convert_to(transaction_facet.transaction_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_functional_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 facts:=assessment.facts_text::jsonb;projection:=facet.functional_facts_text::jsonb;transactions:=transaction_facet.transaction_facts_text::jsonb;
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'functionalDecision','') NOT IN ('rejected','manual_review')
  OR NOT coalesce(gridex_received_sources.validate_utilts_functional_v2(s.raw_payload,projection,transactions),false) THEN RAISE EXCEPTION 'utilts_functional_owner_outcome_mismatch' USING ERRCODE='P0U01'; END IF;
 basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
 IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version',
  'snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'utilts_functional_original_rule_witness_mismatch' USING ERRCODE='P0U01'; END IF;
 SELECT jsonb_agg(value||jsonb_build_object('errorCodes',(SELECT jsonb_agg(error_item->'code' ORDER BY error_ord) FROM jsonb_array_elements(value->'errors') WITH ORDINALITY errors(error_item,error_ord))) ORDER BY ord)
  INTO responses FROM jsonb_array_elements(projection->'transactions') WITH ORDINALITY t(value,ord);
 RETURN jsonb_build_object('version',2,'assessmentId',assessment.id,'sourcePayloadHash',assessment.source_payload_hash,'transactions',responses);
END $$;

--
-- Name: require_utilts_header_before_issuer_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_header_before_issuer_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;assessment gridex_received_sources.validation_assessments%rowtype;facet gridex_received_sources.utilts_header_validations%rowtype;
 transaction_facet gridex_received_sources.utilts_transaction_validations%rowtype;facts jsonb;projection jsonb;transactions jsonb;basis jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE company_id=p_company AND id=p_source FOR SHARE;
 IF s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'UTILTS' THEN RAISE EXCEPTION 'utilts_header_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT v.* INTO assessment FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment
  AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
  AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 IF assessment.id IS NULL OR assessment.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR assessment.facts_hash IS DISTINCT FROM encode(sha256(convert_to(assessment.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_header_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO facet FROM gridex_received_sources.utilts_header_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 SELECT * INTO transaction_facet FROM gridex_received_sources.utilts_transaction_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 IF facet.assessment_id IS NULL OR facet.header_facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.header_facts_text,'UTF8')),'hex')
  OR transaction_facet.assessment_id IS NULL OR transaction_facet.transaction_facts_hash IS DISTINCT FROM encode(sha256(convert_to(transaction_facet.transaction_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_header_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 facts:=assessment.facts_text::jsonb;projection:=facet.header_facts_text::jsonb;transactions:=transaction_facet.transaction_facts_text::jsonb;
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR facts->>'applicationDecision' IS DISTINCT FROM 'rejected' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR NOT coalesce(gridex_received_sources.validate_utilts_header_v1(s.raw_payload,projection),false) OR NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(s.raw_payload,transactions),false)
  OR EXISTS(SELECT FROM jsonb_array_elements(transactions->'transactions') t WHERE t->>'disposition' IS DISTINCT FROM 'guide_rejected' OR t->>'responseType' IS DISTINCT FROM 'negative_aperak') THEN RAISE EXCEPTION 'utilts_header_owner_outcome_mismatch' USING ERRCODE='P0U01'; END IF;
 basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
 IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version',
  'snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'utilts_header_original_rule_witness_mismatch' USING ERRCODE='P0U01'; END IF;
 RETURN jsonb_build_object('version',1,'assessmentId',assessment.id,'sourcePayloadHash',assessment.source_payload_hash,'applicationErrors',projection->'applicationErrors');
END $$;

--
-- Name: require_utilts_header_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_header_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;facts jsonb;
BEGIN
 result:=gridex_received_sources.require_utilts_header_before_issuer_v1(p_company,p_source);
 SELECT facts_text::jsonb INTO facts FROM gridex_received_sources.validation_assessments WHERE id=(result->>'assessmentId')::uuid AND company_id=p_company AND source_message_id=p_source;
 IF facts->'reasonCodes' ? 'UTILTS_ISSUER_MESSAGE_REFERENCE_DUPLICATE' THEN
  PERFORM gridex_utilts_issuer.require_first_effect_v1(p_company,p_source,NULL,'guide_rejected',facts->'reasonCodes');
 END IF;
 RETURN result;
END $$;

--
-- Name: require_utilts_transaction_before_issuer_v1(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_transaction_before_issuer_v1(p_company uuid, p_source uuid, p_transaction text, p_disposition text, p_response text, p_issue_codes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;assessment gridex_received_sources.validation_assessments%rowtype;facet gridex_received_sources.utilts_transaction_validations%rowtype;facts jsonb;own jsonb;projection jsonb;basis jsonb;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE company_id=p_company AND id=p_source FOR SHARE;
 SELECT v.* INTO assessment FROM gridex_received_sources.validation_assessments v WHERE v.company_id=p_company AND v.source_message_id=p_source AND v.environment=s.environment
  AND v.source_payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
  AND v.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296) FOR SHARE;
 IF assessment.id IS NULL OR assessment.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR assessment.facts_hash IS DISTINCT FROM encode(sha256(convert_to(assessment.facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_transaction_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO facet FROM gridex_received_sources.utilts_transaction_validations WHERE assessment_id=assessment.id AND company_id=p_company AND source_message_id=p_source AND environment=s.environment AND source_payload_hash=assessment.source_payload_hash;
 IF facet.assessment_id IS NULL OR facet.transaction_facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.transaction_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_transaction_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 facts:=assessment.facts_text::jsonb;projection:=facet.transaction_facts_text::jsonb;
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(s.raw_payload,projection),false) THEN RAISE EXCEPTION 'utilts_transaction_owner_evidence_required' USING ERRCODE='P0U01'; END IF;
 SELECT value INTO STRICT own FROM jsonb_array_elements(projection->'transactions') WHERE coalesce(value->>'transactionId','transaction-'||((value->>'transactionIndex')::integer+1)::text)=p_transaction;
 IF own->>'disposition' IS DISTINCT FROM p_disposition OR own->>'responseType' IS DISTINCT FROM p_response OR own->'issueCodes' IS DISTINCT FROM p_issue_codes
  OR (p_disposition='accepted' AND facts->>'syntaxDecision' IS DISTINCT FROM 'accepted') THEN RAISE EXCEPTION 'utilts_transaction_owner_outcome_mismatch' USING ERRCODE='P0U01'; END IF;
 -- Global application/functional rejection can be another own IDE. Only this
 -- exact canonical own accepted outcome authorizes a new accepted effect.
 IF p_disposition='accepted' THEN
  basis:=gridex_ediel_source_rules.require_v1(p_company,p_source);
  IF facts->'rulePackEvidence' IS DISTINCT FROM jsonb_build_object('profileKey',basis->'profileKey','messageProfileId',basis->'messageProfileId','rulePackId',basis->'rulePackId','sourceHash',basis->'sourceHash','version',basis->'version',
    'snapshot',jsonb_build_object('rulePack',basis#>'{snapshot,rulePack}','messageProfile',basis#>'{snapshot,messageProfile}','guideSources',basis#>'{snapshot,guideSources}')) THEN RAISE EXCEPTION 'utilts_transaction_original_rule_witness_mismatch' USING ERRCODE='P0U01'; END IF;
 END IF;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'utilts_transaction_owner_evidence_required' USING ERRCODE='P0U01';
END $$;

--
-- Name: require_utilts_transaction_v1(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.require_utilts_transaction_v1(p_company uuid, p_source uuid, p_transaction text, p_disposition text, p_response text, p_issue_codes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM gridex_received_sources.require_utilts_transaction_before_issuer_v1(p_company,p_source,p_transaction,p_disposition,p_response,p_issue_codes);
 PERFORM gridex_utilts_issuer.require_first_effect_v1(p_company,p_source,p_transaction,p_disposition,p_issue_codes);
 PERFORM gridex_ediel_services.require_periodic_outcome_v1(p_company,p_source,p_transaction,p_disposition,p_issue_codes);
END $$;

--
-- Name: review_business_proof_before_customer_kind_v1(jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.review_business_proof_before_customer_kind_v1(p_party jsonb, p_business jsonb, p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; baseline gridex_received_sources.sources%rowtype;
 root gridex_received_sources.object_assessments%rowtype; current_root gridex_received_sources.object_assessments%rowtype;
 review_snap gridex_received_sources.object_selection_snapshots%rowtype;
 predecessor gridex_received_sources.object_assessments%rowtype;
 cover jsonb:=p_business->'coverageWindow'; wire jsonb:=p_business->'wire'; replacement jsonb:=p_business->'replaces';
 root_entry jsonb; current_entry jsonb; previous_entry jsonb; epoch timestamptz; valid_start timestamptz; valid_end timestamptz;
 change_at timestamptz; minute text; market_time timestamp; owner_ok boolean;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_id;
 IF NOT FOUND OR src.message_code NOT IN ('Z04','Z06','Z10') OR src.source_received_at IS NULL THEN RETURN false; END IF;
 -- Z06/E34 needs a persisted death assessment or a counterparty-scoped bilateral
 -- agreement. Neither authoritative producer exists in this review owner.
 IF src.message_code='Z06' AND p_business#>>'{wire,businessCase}'='customer_only' THEN RETURN false; END IF;
 IF p_business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
 OR p_business->>'coverage' IS DISTINCT FROM 'reviewed_post_ledger_supply'
 OR p_business->>'businessDisposition' IS DISTINCT FROM 'reviewed'
 OR p_business->>'reviewStatement' IS DISTINCT FROM 'original_structural_message'
 OR p_business->>'graphNamespace' IS DISTINCT FROM 'legacy_unqualified'
 OR p_business#>>'{object,identityAgency}' IS DISTINCT FROM '9'
 OR p_business-ARRAY['version','owner','coverage','sourceDisposition','businessDisposition','graphNamespace','sourceMessageId','sourcePayloadHash','sourceReceivedAt','companyId','environment','object','assessedAt','wire','reviewerUserId','reviewStatement','customerId','meteringPointId','siteId','switchRequestId','supplyPeriodId','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','replaces']<>'{}'::jsonb
 OR NOT p_business ?& ARRAY['wire','reviewerUserId','reviewStatement','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','replaces']
 OR NOT gridex_received_sources.review_party_proof_consistent(p_party,p_business,src.source_received_at)
 OR NOT EXISTS(SELECT FROM public.companies c WHERE c.id=src.company_id AND coalesce(c.status,'active') IN ('active','onboarding'))
 OR NOT (public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'communication.write')
   OR public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'ediel_testing.write')) THEN RETURN false; END IF;
 IF cover->>'kind' IS DISTINCT FROM 'post_ledger_supply' OR cover->>'supplyPeriodId' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR cover->>'switchRequestId' IS DISTINCT FROM p_business->>'switchRequestId'
 OR cover-ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']<>'{}'::jsonb
 OR NOT cover ?& ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']
 OR wire->'object' IS DISTINCT FROM p_business->'object' OR wire->>'messageCode' IS DISTINCT FROM src.message_code
 OR wire->>'legalSender' IS DISTINCT FROM p_party#>>'{parties,legalSender}' OR wire->>'legalReceiver' IS DISTINCT FROM p_party#>>'{parties,legalReceiver}'
 OR wire->>'transportSender' IS DISTINCT FROM p_party#>>'{parties,transportSender}' OR wire->>'transportReceiver' IS DISTINCT FROM p_party#>>'{parties,transportReceiver}'
 OR wire#>>'{effectiveFrom,fieldNumber}' IS DISTINCT FROM (CASE WHEN src.message_code='Z04' THEN '210' ELSE '216' END)
 OR (CASE src.message_code WHEN 'Z04' THEN wire->>'businessCase'='supply_baseline' WHEN 'Z10' THEN wire->>'businessCase'='meter_exchange'
     ELSE wire->>'businessCase' IN ('customer_only','change_with_reading','change_without_reading') END) IS DISTINCT FROM true
 OR jsonb_typeof(wire->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(wire->'registers')<>jsonb_array_length(p_business#>'{object,registers}')
 OR nullif(wire->>'caseReference','') IS NULL OR nullif(wire->>'documentReference','') IS NULL THEN RETURN false; END IF;
 SELECT * INTO review_snap FROM gridex_received_sources.object_selection_snapshots
 WHERE id=(p_business#>>'{reviewSnapshot,snapshotId}')::uuid AND company_id=src.company_id AND environment=src.environment
 AND readset_hash=p_business#>>'{reviewSnapshot,readsetHash}' AND cutoff_at=(p_business#>>'{reviewSnapshot,cutoffAt}')::timestamptz;
 IF NOT FOUND OR (review_snap.readset_text::jsonb->>'complete') IS DISTINCT FROM 'true'
 OR review_snap.cutoff_at>(p_business->>'assessedAt')::timestamptz
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') item
   WHERE item->>'sourceMessageId'=src.source_message_id::text AND item->>'payloadHash'=src.payload_hash) THEN RETURN false; END IF;
 SELECT opened_at INTO epoch FROM gridex_received_sources.epoch WHERE singleton;
 valid_start:=(cover->>'validFrom')::timestamptz; valid_end:=(cover->>'validTo')::timestamptz;
 minute:=wire#>>'{effectiveFrom,marketMinute}';
 IF minute IS NULL OR minute !~ '^[0-9]{12}$' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;
 market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);
 change_at:=market_time AT TIME ZONE 'Etc/GMT-1';
 IF (wire#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM change_at OR valid_start IS NULL OR NOT isfinite(valid_start)
 OR valid_start<epoch OR (valid_end IS NOT NULL AND (NOT isfinite(valid_end) OR valid_end<=valid_start))
 OR change_at<valid_start OR (valid_end IS NOT NULL AND change_at>=valid_end)
 OR (src.message_code='Z04' AND change_at<>valid_start) THEN RETURN false; END IF;
 SELECT * INTO baseline FROM gridex_received_sources.sources WHERE source_message_id=(cover->>'baselineSourceMessageId')::uuid
 AND company_id=src.company_id AND environment=src.environment AND message_code='Z04';
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT a.* INTO root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(cover->>'baselineAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id AND a.company_id=src.company_id
 AND a.environment=src.environment AND a.facts_hash=cover->>'baselineFactsHash' AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO root_entry FROM jsonb_array_elements(root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF root_entry->>'disposition' IS DISTINCT FROM 'accepted' OR root_entry#>>'{business,owner}' IS DISTINCT FROM 'inbound-z04-switch-confirmation-v1'
 OR root_entry#>>'{business,switchRequestId}' IS DISTINCT FROM p_business->>'switchRequestId'
 OR root_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR root_entry#>>'{business,customerId}' IS DISTINCT FROM p_business->>'customerId'
 OR root_entry#>>'{business,meteringPointId}' IS DISTINCT FROM p_business->>'meteringPointId'
 OR root_entry#>>'{business,siteId}' IS DISTINCT FROM p_business->>'siteId'
 OR (root_entry#>>'{business,effectiveFrom,utc}')::timestamptz IS DISTINCT FROM valid_start THEN RETURN false; END IF;
 SELECT a.* INTO current_root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(p_business->>'baselineCurrentAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id
 AND a.company_id=src.company_id AND a.environment=src.environment AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at
 AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO current_entry FROM jsonb_array_elements(current_root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF current_entry->>'disposition' IS DISTINCT FROM 'accepted' THEN RETURN false; END IF;
 -- The retained snapshot must actually contain the current baseline assessment,
 -- rather than merely sharing a plausible time and tenant with it.
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') source,
  LATERAL jsonb_array_elements(source->'assessments') assessment
  WHERE source->>'sourceMessageId'=baseline.source_message_id::text AND assessment->>'id'=current_root.id::text
  AND assessment->>'factsHash'=current_root.facts_hash AND (assessment->>'availableAt')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;
 SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw
 JOIN public.customer_supply_periods sp ON sp.id=(p_business->>'supplyPeriodId')::uuid
 JOIN public.ediel_messages outbound ON outbound.id=sw.outbound_z03_message_id
 JOIN public.metering_points mp ON mp.id=sw.metering_point_id JOIN public.customer_sites cs ON cs.id=sw.site_id
 WHERE sw.id=(p_business->>'switchRequestId')::uuid AND sw.company_id=src.company_id AND sp.company_id=src.company_id
 AND sw.inbound_z04_message_id=baseline.source_message_id AND sp.source_message_id=baseline.source_message_id
 AND gridex_received_sources.normal_switch_coverage_is_current_v1(src.company_id,sp.id,sw.id,baseline.source_message_id,valid_start,valid_end)
 AND sw.metering_point_id=(p_business->>'meteringPointId')::uuid AND sp.metering_point_id=sw.metering_point_id
 AND sw.customer_id=(p_business->>'customerId')::uuid AND sp.customer_id=sw.customer_id AND sw.site_id=(p_business->>'siteId')::uuid
 AND (sp.source_switch_request_id IS NULL OR sp.source_switch_request_id=sw.id)
 AND mp.company_id=src.company_id AND cs.company_id=src.company_id AND mp.site_id=cs.id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id
 AND sw.confirmed_start_date=sp.start_date
 AND sw.created_at=(cover->>'switchCreatedAt')::timestamptz AND sw.created_at>=epoch AND sw.created_at<=valid_start
 AND outbound.id=(cover->>'outboundSourceMessageId')::uuid AND outbound.company_id=src.company_id AND outbound.environment=src.environment
 AND outbound.direction='outbound' AND outbound.message_standard='edifact' AND outbound.message_family='PRODAT' AND outbound.message_code='Z03'
 AND outbound.created_at=(cover->>'outboundCreatedAt')::timestamptz AND outbound.created_at>=sw.created_at AND outbound.created_at<=review_snap.cutoff_at
 AND outbound.customer_id=sw.customer_id AND outbound.metering_point_id=sw.metering_point_id AND outbound.site_id=sw.site_id) INTO owner_ok;
 IF owner_ok IS DISTINCT FROM true THEN RETURN false; END IF;
 IF wire->>'functionCode'='5' THEN
  IF replacement IS NULL OR jsonb_typeof(replacement)<>'object' OR replacement->>'sourceMessageId'=src.source_message_id::text THEN RETURN false; END IF;
  SELECT a.* INTO predecessor FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
  WHERE a.id=(replacement->>'assessmentId')::uuid AND a.source_message_id=(replacement->>'sourceMessageId')::uuid
  AND a.company_id=src.company_id AND a.environment=src.environment AND a.source_payload_hash=replacement->>'payloadHash'
  AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at
  AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT value INTO previous_entry FROM jsonb_array_elements(predecessor.facts_text::jsonb->'objects')
  WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
  IF previous_entry->>'disposition' IS DISTINCT FROM 'accepted' OR previous_entry#>>'{business,owner}' IS DISTINCT FROM 'reviewed-received-structure-v1'
  OR previous_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
  OR previous_entry#>>'{business,wire,messageCode}' IS DISTINCT FROM wire->>'messageCode'
  OR previous_entry#>>'{business,wire,businessCase}' IS DISTINCT FROM wire->>'businessCase'
  OR previous_entry#>>'{business,wire,caseReference}' IS DISTINCT FROM wire->>'caseReference'
  OR previous_entry#>>'{business,wire,documentReference}' IS NOT DISTINCT FROM wire->>'documentReference'
  OR previous_entry#>>'{business,wire,legalSender}' IS DISTINCT FROM wire->>'legalSender'
  OR previous_entry#>>'{business,wire,legalReceiver}' IS DISTINCT FROM wire->>'legalReceiver' THEN RETURN false; END IF;
 ELSE
  IF wire->'functionCode' NOT IN ('"9"'::jsonb,'null'::jsonb) OR replacement IS DISTINCT FROM 'null'::jsonb
   OR (src.message_code='Z04' AND baseline.source_message_id<>src.source_message_id) THEN RETURN false; END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $_$;

--
-- Name: review_business_proof_consistent(jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.review_business_proof_consistent(p_party jsonb, p_business jsonb, p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s gridex_received_sources.sources%rowtype;reason text;BEGIN
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_id;
 IF s.message_code='Z06' THEN
  reason:=gridex_received_sources.prodat_first_register_characteristic_v1(s.raw_payload,p_business->'object','Z13');
  IF reason IS NULL OR reason='E34' THEN RETURN false;END IF;
 END IF;
 RETURN gridex_received_sources.review_business_proof_before_customer_kind_v1(p_party,p_business,p_source_id);
END $$;

--
-- Name: review_closure_proof_consistent(jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.review_closure_proof_consistent(p_party jsonb, p_business jsonb, p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; baseline gridex_received_sources.sources%rowtype;
 root gridex_received_sources.object_assessments%rowtype; current_root gridex_received_sources.object_assessments%rowtype;
 review_snap gridex_received_sources.object_selection_snapshots%rowtype;
 cover jsonb:=p_business->'coverageWindow'; wire jsonb:=p_business->'wire'; reference jsonb:=p_business->'baselineCoverageAssessment';
 root_entry jsonb; current_entry jsonb; epoch timestamptz; valid_start timestamptz; valid_end timestamptz;
 change_at timestamptz; minute text; market_time timestamp; owner_ok boolean;supply_basis jsonb;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_id AND company_id=(p_business->>'companyId')::uuid
 AND environment=p_business->>'environment' AND payload_hash=p_business->>'sourcePayloadHash';
 IF NOT FOUND OR src.message_code<>'Z05' OR src.source_received_at IS NULL THEN RETURN false; END IF;
 IF jsonb_typeof(p_business) IS DISTINCT FROM 'object'
 OR jsonb_typeof(cover) IS DISTINCT FROM 'object'
 OR jsonb_typeof(reference) IS DISTINCT FROM 'object'
 OR p_business->>'owner' IS DISTINCT FROM 'reviewed-received-closure-v1'
 OR p_business->>'coverage' IS DISTINCT FROM 'reviewed_post_ledger_closure'
 OR p_business->>'businessDisposition' IS DISTINCT FROM 'reviewed'
 OR p_business->>'reviewStatement' IS DISTINCT FROM 'original_supply_closure'
 OR p_business->>'graphNamespace' IS DISTINCT FROM 'legacy_unqualified'
 OR p_business#>>'{object,identityAgency}' IS DISTINCT FROM '9'
 OR p_business-ARRAY['version','owner','coverage','sourceDisposition','businessDisposition','graphNamespace','sourceMessageId','sourcePayloadHash','sourceReceivedAt','companyId','environment','object','assessedAt','wire','reviewerUserId','reviewStatement','customerId','meteringPointId','siteId','switchRequestId','supplyPeriodId','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','baselineCoverageAssessment','legacyEndDateProjection']<>'{}'::jsonb
 OR NOT p_business ?& ARRAY['version','owner','coverage','sourceDisposition','businessDisposition','graphNamespace','sourceMessageId','sourcePayloadHash','sourceReceivedAt','companyId','environment','object','assessedAt','wire','reviewerUserId','reviewStatement','customerId','meteringPointId','siteId','switchRequestId','supplyPeriodId','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','baselineCoverageAssessment','legacyEndDateProjection']
 OR jsonb_typeof(p_business->'reviewSnapshot') IS DISTINCT FROM 'object'
 OR (p_business->'reviewSnapshot')-ARRAY['snapshotId','readsetHash','cutoffAt']<>'{}'::jsonb
 OR NOT p_business->'reviewSnapshot' ?& ARRAY['snapshotId','readsetHash','cutoffAt']
 -- Handbok 26A p70 supplier handoff; LK is a conservative supported subset.
 OR substring(wire#>>'{effectiveTo,marketMinute}',9,4) IS DISTINCT FROM '0000'
 OR NOT gridex_received_sources.closure_wire_matches_v1(src.raw_payload,p_business->'object',wire)
 OR NOT gridex_received_sources.review_party_proof_consistent(p_party,p_business,src.source_received_at)
 OR NOT EXISTS(SELECT FROM public.companies c WHERE c.id=src.company_id AND coalesce(c.status,'active') IN ('active','onboarding'))
 OR NOT (public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'communication.write')
   OR public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'ediel_testing.write')) THEN RETURN false; END IF;
 IF cover->>'kind' IS DISTINCT FROM 'post_ledger_supply' OR cover->>'supplyPeriodId' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR cover->>'switchRequestId' IS DISTINCT FROM p_business->>'switchRequestId'
 OR cover-ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']<>'{}'::jsonb
 OR NOT cover ?& ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']
 OR wire->'object' IS DISTINCT FROM p_business->'object' OR wire->>'messageCode' IS DISTINCT FROM src.message_code
 OR wire->>'legalSender' IS DISTINCT FROM p_party#>>'{parties,legalSender}' OR wire->>'legalReceiver' IS DISTINCT FROM p_party#>>'{parties,legalReceiver}'
 OR wire->>'transportSender' IS DISTINCT FROM p_party#>>'{parties,transportSender}' OR wire->>'transportReceiver' IS DISTINCT FROM p_party#>>'{parties,transportReceiver}'
 THEN RETURN false; END IF;
 SELECT * INTO review_snap FROM gridex_received_sources.object_selection_snapshots
 WHERE id=(p_business#>>'{reviewSnapshot,snapshotId}')::uuid AND company_id=src.company_id AND environment=src.environment
 AND readset_hash=p_business#>>'{reviewSnapshot,readsetHash}' AND cutoff_at=(p_business#>>'{reviewSnapshot,cutoffAt}')::timestamptz;
 IF NOT FOUND OR (review_snap.readset_text::jsonb->>'complete') IS DISTINCT FROM 'true'
 OR review_snap.cutoff_at>(p_business->>'assessedAt')::timestamptz
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') item
   WHERE item->>'sourceMessageId'=src.source_message_id::text AND item->>'payloadHash'=src.payload_hash) THEN RETURN false; END IF;
 SELECT opened_at INTO epoch FROM gridex_received_sources.epoch WHERE singleton;
 valid_start:=(cover->>'validFrom')::timestamptz; valid_end:=(cover->>'validTo')::timestamptz;
 minute:=wire#>>'{effectiveTo,marketMinute}';
 IF minute IS NULL OR minute !~ '^[0-9]{12}$' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;
 market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);
 change_at:=market_time AT TIME ZONE 'Etc/GMT-1';
 IF (wire#>>'{effectiveTo,utc}')::timestamptz IS DISTINCT FROM change_at OR valid_start IS NULL OR NOT isfinite(valid_start)
 OR valid_start<epoch OR (valid_end IS NOT NULL AND (NOT isfinite(valid_end) OR valid_end<=valid_start))
 OR change_at<=valid_start OR (valid_end IS NOT NULL AND change_at<>valid_end)
 OR p_business->>'legacyEndDateProjection' IS DISTINCT FROM market_time::date::text THEN RETURN false; END IF;
 SELECT * INTO baseline FROM gridex_received_sources.sources WHERE source_message_id=(cover->>'baselineSourceMessageId')::uuid
 AND company_id=src.company_id AND environment=src.environment AND message_code='Z04';
 IF NOT FOUND OR baseline.source_message_id=src.source_message_id OR reference IS DISTINCT FROM jsonb_build_object(
  'sourceMessageId',baseline.source_message_id,'assessmentId',p_business->>'baselineCurrentAssessmentId',
  'factsHash',reference->>'factsHash','payloadHash',baseline.payload_hash) THEN RETURN false; END IF;
 SELECT a.* INTO root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(cover->>'baselineAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id AND a.company_id=src.company_id
 AND a.environment=src.environment AND a.facts_hash=cover->>'baselineFactsHash' AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO root_entry FROM jsonb_array_elements(root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF root_entry->>'disposition' IS DISTINCT FROM 'accepted' OR root_entry#>>'{business,owner}' IS DISTINCT FROM 'inbound-z04-switch-confirmation-v1'
 OR root.source_payload_hash IS DISTINCT FROM baseline.payload_hash
 OR root_entry#>>'{business,sourceMessageId}' IS DISTINCT FROM baseline.source_message_id::text
 OR root_entry#>>'{business,sourcePayloadHash}' IS DISTINCT FROM baseline.payload_hash
 OR root_entry#>>'{business,companyId}' IS DISTINCT FROM src.company_id::text
 OR root_entry#>>'{business,environment}' IS DISTINCT FROM src.environment
 OR root_entry#>>'{party,parties,legalSender}' IS DISTINCT FROM wire->>'legalSender'
 OR root_entry#>>'{party,parties,legalReceiver}' IS DISTINCT FROM wire->>'legalReceiver'
 OR root_entry#>>'{business,switchRequestId}' IS DISTINCT FROM p_business->>'switchRequestId'
 OR root_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR root_entry#>>'{business,customerId}' IS DISTINCT FROM p_business->>'customerId'
 OR root_entry#>>'{business,meteringPointId}' IS DISTINCT FROM p_business->>'meteringPointId'
 OR root_entry#>>'{business,siteId}' IS DISTINCT FROM p_business->>'siteId'
 OR (root_entry#>>'{business,effectiveFrom,utc}')::timestamptz IS DISTINCT FROM valid_start THEN RETURN false; END IF;
 SELECT a.* INTO current_root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(p_business->>'baselineCurrentAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id
 AND a.company_id=src.company_id AND a.environment=src.environment AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at
 AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO current_entry FROM jsonb_array_elements(current_root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF current_entry->>'disposition' IS DISTINCT FROM 'accepted'
 OR current_entry#>>'{business,owner}' IS DISTINCT FROM 'reviewed-received-structure-v1'
 OR current_entry#>>'{business,wire,messageCode}' IS DISTINCT FROM 'Z04'
 OR current_entry#>'{business,wire,functionCode}' NOT IN ('"9"'::jsonb,'null'::jsonb)
 OR current_entry#>'{business,replaces}' IS DISTINCT FROM 'null'::jsonb
 OR current_entry#>'{business,coverageWindow}' IS DISTINCT FROM cover
 OR current_root.facts_hash IS DISTINCT FROM reference->>'factsHash'
 OR current_root.source_payload_hash IS DISTINCT FROM baseline.payload_hash
 OR current_entry#>>'{business,sourceMessageId}' IS DISTINCT FROM baseline.source_message_id::text
 OR current_entry#>>'{business,sourcePayloadHash}' IS DISTINCT FROM baseline.payload_hash
 OR current_entry#>>'{business,companyId}' IS DISTINCT FROM src.company_id::text
 OR current_entry#>>'{business,environment}' IS DISTINCT FROM src.environment
 OR current_entry#>>'{business,customerId}' IS DISTINCT FROM p_business->>'customerId'
 OR current_entry#>>'{business,meteringPointId}' IS DISTINCT FROM p_business->>'meteringPointId'
 OR current_entry#>>'{business,siteId}' IS DISTINCT FROM p_business->>'siteId'
 OR current_entry#>>'{business,switchRequestId}' IS DISTINCT FROM p_business->>'switchRequestId'
 OR current_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR current_entry#>>'{business,wire,legalSender}' IS DISTINCT FROM wire->>'legalSender'
 OR current_entry#>>'{business,wire,legalReceiver}' IS DISTINCT FROM wire->>'legalReceiver'
 OR (current_entry#>>'{business,wire,effectiveFrom,utc}')::timestamptz IS DISTINCT FROM valid_start
 THEN RETURN false; END IF;
 -- The retained snapshot must actually contain the current baseline assessment,
 -- rather than merely sharing a plausible time and tenant with it.
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') source,
  LATERAL jsonb_array_elements(source->'assessments') assessment
  WHERE source->>'sourceMessageId'=baseline.source_message_id::text AND source->>'payloadHash'=baseline.payload_hash
  AND assessment->>'id'=root.id::text AND assessment->>'factsHash'=root.facts_hash
  AND (assessment->>'availableAt')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') source,
  LATERAL jsonb_array_elements(source->'assessments') assessment
  WHERE source->>'sourceMessageId'=baseline.source_message_id::text AND assessment->>'id'=current_root.id::text
  AND assessment->>'factsHash'=current_root.facts_hash AND (assessment->>'availableAt')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;
 -- Selection may not choose a convenient reviewed root among ambiguous
 -- latest witnessed baselines for this same immutable supply and object.
 IF (SELECT count(*) FROM gridex_received_sources.object_assessments a
  JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id AND w.facts_hash=a.facts_hash
  JOIN gridex_received_sources.sources source ON source.source_message_id=a.source_message_id
  CROSS JOIN LATERAL jsonb_array_elements(a.facts_text::jsonb->'objects') item
  WHERE a.company_id=src.company_id AND a.environment=src.environment AND source.message_code='Z04'
  AND w.observed_at<=review_snap.cutoff_at
  AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id)
  AND item->>'disposition'='accepted' AND item#>>'{business,owner}'='reviewed-received-structure-v1'
  AND item#>>'{business,supplyPeriodId}'=p_business->>'supplyPeriodId'
  AND item#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND item#>>'{object,identityAgency}'='9'
  AND item#>>'{business,wire,legalSender}'=wire->>'legalSender'
  AND item#>>'{business,wire,legalReceiver}'=wire->>'legalReceiver')<>1 THEN RETURN false; END IF;
 -- The current closing source and initial approved source form one immutable
 -- versioned relation. A legacy DATE/status row cannot reconstruct this tuple.
 supply_basis:=gridex_received_sources.supply_period_source_basis_v1(src.company_id,(p_business->>'supplyPeriodId')::uuid,valid_start,change_at);
 IF supply_basis IS NULL OR supply_basis->>'qualified' IS DISTINCT FROM 'true'
  OR supply_basis->>'companyId' IS DISTINCT FROM src.company_id::text OR supply_basis->>'periodId' IS DISTINCT FROM p_business->>'supplyPeriodId'
  OR supply_basis->>'switchId' IS DISTINCT FROM p_business->>'switchRequestId'
  OR supply_basis->>'initialSourceMessageId' IS DISTINCT FROM baseline.source_message_id::text
  OR supply_basis->>'sourceMessageId' IS DISTINCT FROM src.source_message_id::text
  OR supply_basis->>'customerId' IS DISTINCT FROM p_business->>'customerId' OR supply_basis->>'meteringPointId' IS DISTINCT FROM p_business->>'meteringPointId'
  OR supply_basis->>'siteId' IS DISTINCT FROM p_business->>'siteId' OR supply_basis->>'dsoEdielId' IS DISTINCT FROM wire->>'legalSender'
  OR (supply_basis->>'marketStartAt')::timestamptz IS DISTINCT FROM valid_start OR (supply_basis->>'marketEndAt')::timestamptz IS DISTINCT FROM change_at
  OR supply_basis->>'originalMessageId' IS DISTINCT FROM cover->>'outboundSourceMessageId'
  OR jsonb_array_length(supply_basis->'sourceObjects') IS DISTINCT FROM 1
  OR supply_basis#>>'{sourceObjects,0,point}' IS DISTINCT FROM p_business#>>'{object,objectId}'
  OR supply_basis#>>'{sourceObjects,0,identityAgency}' IS DISTINCT FROM p_business#>>'{object,identityAgency}' THEN RETURN false;END IF;
 SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw
 JOIN public.customer_supply_periods sp ON sp.id=(p_business->>'supplyPeriodId')::uuid
 JOIN public.ediel_messages outbound ON outbound.id=sw.outbound_z03_message_id
 JOIN public.metering_points mp ON mp.id=sw.metering_point_id JOIN public.customer_sites cs ON cs.id=sw.site_id
 WHERE sw.id=(p_business->>'switchRequestId')::uuid AND sw.company_id=src.company_id AND sp.company_id=src.company_id
 AND sw.inbound_z04_message_id=baseline.source_message_id AND sp.source_message_id=baseline.source_message_id AND sp.source_end_message_id=src.source_message_id
 AND sw.rff_li_reference=current_entry#>>'{business,wire,caseReference}'
 AND sw.metering_point_id=(p_business->>'meteringPointId')::uuid AND sp.metering_point_id=sw.metering_point_id
 AND sw.customer_id=(p_business->>'customerId')::uuid AND sp.customer_id=sw.customer_id AND sw.site_id=(p_business->>'siteId')::uuid
 AND (sp.source_switch_request_id IS NULL OR sp.source_switch_request_id=sw.id)
 AND mp.company_id=src.company_id AND cs.company_id=src.company_id AND mp.site_id=cs.id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id
 AND sw.confirmed_start_date=sp.start_date
 AND sp.end_date=market_time::date
 AND sw.created_at=(cover->>'switchCreatedAt')::timestamptz AND sw.created_at>=epoch AND sw.created_at<=valid_start
 AND outbound.id=(cover->>'outboundSourceMessageId')::uuid AND outbound.company_id=src.company_id AND outbound.environment=src.environment
 AND outbound.direction='outbound' AND outbound.message_standard='edifact' AND outbound.message_family='PRODAT' AND outbound.message_code='Z03'
 AND outbound.created_at=(cover->>'outboundCreatedAt')::timestamptz AND outbound.created_at>=sw.created_at AND outbound.created_at<=review_snap.cutoff_at
 AND (supply_basis->>'originalAcceptedAt')::timestamptz>=outbound.created_at AND (supply_basis->>'originalAcceptedAt')::timestamptz<=baseline.source_received_at
 AND outbound.customer_id=sw.customer_id AND outbound.metering_point_id=sw.metering_point_id AND outbound.site_id=sw.site_id) INTO owner_ok;
 IF owner_ok IS DISTINCT FROM true THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $_$;

--
-- Name: review_party_proof_consistent(jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.review_party_proof_consistent(p_party jsonb, p_business jsonb, p_received timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE identity jsonb:=p_party#>'{receiver,identity}'; evidence jsonb:=p_party#>'{receiver,evidence}';
 records jsonb:=evidence->'records'; facility jsonb:=p_party->'facility'; parties jsonb:=p_party->'parties';
 effective jsonb:=p_business->'effectiveFrom'; commit_row jsonb; name text; stamp text; instant timestamptz;
 party_start timestamptz; party_end timestamptz; evaluated timestamptz; role_values text[]; supplied_roles text[];
 actor_count bigint; identifier_count bigint; selected_actor_id uuid; legal_id text; relation_count bigint;
 relation_id uuid; transport_actor uuid; transport_id text; minute text; market_time timestamp; expected_day text;
BEGIN
 IF p_received IS NULL OR NOT isfinite(p_received)
  OR p_business->>'sourceDisposition' IS DISTINCT FROM 'not_established'
  OR p_business->>'graphNamespace' IS DISTINCT FROM 'legacy_unqualified'
  OR p_party->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR p_party->>'authentication' IS DISTINCT FROM 'not_assessed'
  OR evidence->'version' IS DISTINCT FROM '1'::jsonb
  OR evidence->>'owner' IS DISTINCT FROM 'canonical-tenant-ediel-identity-v1'
  OR evidence->>'consistency' IS DISTINCT FROM 'independent_reads'
  OR evidence->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR evidence->>'sourceDisposition' IS DISTINCT FROM 'not_established'
  OR facility->>'owner' IS DISTINCT FROM 'selected-facility-grid-owner-v1'
  OR facility->>'consistency' IS DISTINCT FROM 'independent_reads'
  OR facility->>'historicalKnowledge' IS DISTINCT FROM 'not_established'
  OR identity->>'companyId' IS DISTINCT FROM p_business->>'companyId'
  OR identity->>'environment' IS DISTINCT FROM p_business->>'environment'
  OR jsonb_typeof(identity->'representedByTransportAgent') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(identity->'roleCodes') IS DISTINCT FROM 'array'
  OR jsonb_typeof(parties) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 -- PostgreSQL's timestamp/date types own calendar parsing. Reject infinities,
 -- date-only spellings and excess fractional precision before typed equality.
 FOR stamp IN SELECT value FROM unnest(ARRAY[p_business->>'assessedAt',p_business->>'sourceReceivedAt',
  p_party#>>'{source,receivedAt}',p_party->>'assessedAt',p_party->>'completedAt',evidence->>'evaluatedAt',
  evidence->>'observedAt',evidence->>'completedAt',facility->>'observedAt',facility->>'completedAt']) value LOOP
  IF stamp IS NULL OR stamp !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RETURN false; END IF;
  instant:=stamp::timestamptz;
  IF NOT isfinite(instant) OR instant<p_received OR instant>statement_timestamp() THEN RETURN false; END IF;
 END LOOP;
 party_start:=(p_party->>'assessedAt')::timestamptz;party_end:=(p_party->>'completedAt')::timestamptz;evaluated:=(evidence->>'evaluatedAt')::timestamptz;
 IF (p_business->>'sourceReceivedAt')::timestamptz<>p_received OR (p_party#>>'{source,receivedAt}')::timestamptz<>p_received
  OR party_end<party_start OR evaluated<>party_start
  OR (evidence->>'observedAt')::timestamptz<evaluated OR (evidence->>'completedAt')::timestamptz<(evidence->>'observedAt')::timestamptz
  OR (evidence->>'completedAt')::timestamptz>party_end
  OR (facility->>'observedAt')::timestamptz<party_start OR (facility->>'completedAt')::timestamptz<(facility->>'observedAt')::timestamptz
  OR (facility->>'completedAt')::timestamptz>party_end THEN RETURN false; END IF;
 FOREACH name IN ARRAY ARRAY['legalSender','legalReceiver','transportSender','transportReceiver'] LOOP
  IF jsonb_typeof(parties->name) IS DISTINCT FROM 'string' OR length(parties->>name) NOT BETWEEN 1 AND 128
   OR parties->>name<>btrim(parties->>name) THEN RETURN false; END IF;
 END LOOP;
 -- Same half-open tenant validity used by resolveCanonicalTenantEdielIdentity.
 IF NOT EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.tenant_ediel_profiles,records->'profiles') r
  WHERE r.is_enabled AND r.market='electricity' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to)) THEN RETURN false; END IF;
 SELECT count(DISTINCT r.actor_id),count(DISTINCT nullif(btrim(r.identifier_value),'')),min(r.actor_id::text)::uuid,min(nullif(btrim(r.identifier_value),''))
 INTO actor_count,identifier_count,selected_actor_id,legal_id
 FROM jsonb_populate_recordset(NULL::public.tenant_actor_identifiers,records->'identifiers') r
 WHERE r.identifier_type='EdielId' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF actor_count<>1 OR identifier_count<>1 OR selected_actor_id::text IS DISTINCT FROM identity->>'legalActorId'
  OR legal_id IS DISTINCT FROM identity->>'legalEdielId' OR legal_id IS DISTINCT FROM parties->>'legalReceiver' THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT btrim(r.role_code) ORDER BY btrim(r.role_code)) INTO role_values
 FROM jsonb_populate_recordset(NULL::public.tenant_actor_roles,records->'roles') r
 WHERE r.actor_id=selected_actor_id AND nullif(btrim(r.role_code),'') IS NOT NULL AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF EXISTS(SELECT FROM jsonb_array_elements(identity->'roleCodes') r WHERE jsonb_typeof(r)<>'string') THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT value ORDER BY value) INTO supplied_roles FROM jsonb_array_elements_text(identity->'roleCodes');
 IF role_values IS DISTINCT FROM supplied_roles OR NOT coalesce('electricity_supplier'=ANY(role_values),false) THEN RETURN false; END IF;
 SELECT count(*),min(r.id::text)::uuid,min(r.counterparty_actor_id::text)::uuid INTO relation_count,relation_id,transport_actor
 FROM jsonb_populate_recordset(NULL::public.tenant_counterparty_relations,records->'relations') r
 WHERE r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);
 IF relation_count=0 THEN
  IF identity->'representedByTransportAgent'<>'false'::jsonb OR identity->'transportRelationId' IS DISTINCT FROM 'null'::jsonb
   OR identity->>'transportActorId' IS DISTINCT FROM selected_actor_id::text OR identity->>'transportEdielId' IS DISTINCT FROM legal_id
   OR records->'transportIdentifiers' IS DISTINCT FROM '[]'::jsonb THEN RETURN false; END IF;
 ELSE
  IF relation_count<>1 OR identity->'representedByTransportAgent'<>'true'::jsonb
   OR identity->>'transportRelationId' IS DISTINCT FROM relation_id::text OR identity->>'transportActorId' IS DISTINCT FROM transport_actor::text
   OR transport_actor=selected_actor_id THEN RETURN false; END IF;
  IF EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->'transportIdentifiers') r WHERE r.is_verified IS DISTINCT FROM true) THEN RETURN false; END IF;
  SELECT count(DISTINCT nullif(btrim(r.identifier_value),'')),min(nullif(btrim(r.identifier_value),'')) INTO identifier_count,transport_id
  FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->'transportIdentifiers') r
  WHERE r.actor_id=transport_actor AND r.identifier_type='EdielId'
   AND (r.valid_from IS NULL OR r.valid_from::timestamp AT TIME ZONE 'UTC'<=evaluated)
   AND (r.valid_to IS NULL OR evaluated<r.valid_to::timestamp AT TIME ZONE 'UTC');
  IF identifier_count<>1 OR transport_id=legal_id OR transport_id IS DISTINCT FROM identity->>'transportEdielId' THEN RETURN false; END IF;
 END IF;
 IF parties->>'transportReceiver' IS DISTINCT FROM identity->>'transportEdielId'
  OR parties->>'transportSender' IS DISTINCT FROM parties->>'legalSender'
  OR parties->>'legalSender' IS DISTINCT FROM facility#>>'{gridOwner,ediel_id}'
  OR facility#>'{gridOwner,is_active}' IS DISTINCT FROM 'true'::jsonb OR facility#>>'{gridOwner,lifecycle_status}' IS DISTINCT FROM 'active'
  OR facility#>>'{gridOwner,environment}' IS DISTINCT FROM p_business->>'environment'
  OR (p_business->>'environment'='production' AND facility#>>'{gridOwner,ediel_id}' IN ('91100','91109'))
  OR facility#>>'{meteringPoint,meter_point_id}' IS DISTINCT FROM p_business#>>'{object,objectId}'
  OR facility#>>'{site,facility_id}' IS DISTINCT FROM p_business#>>'{object,objectId}'
  OR facility#>>'{meteringPoint,site_id}' IS DISTINCT FROM facility#>>'{site,id}'
  OR (facility#>'{meteringPoint,customer_site_id}'<>'null'::jsonb AND facility#>>'{meteringPoint,customer_site_id}' IS DISTINCT FROM facility#>>'{site,id}')
  OR facility#>>'{meteringPoint,grid_owner_id}' IS DISTINCT FROM facility#>>'{gridOwner,id}'
  OR facility#>>'{site,grid_owner_id}' IS DISTINCT FROM facility#>>'{gridOwner,id}' THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $_$;

--
-- Name: seal_utilts_insert_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.seal_utilts_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed timestamptz:=clock_timestamp();
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.execution_context_snapshot ? 'receivedUtiltsContext' THEN
   IF NEW.execution_context_snapshot->'receivedUtiltsContext' IS DISTINCT FROM OLD.execution_context_snapshot->'receivedUtiltsContext'
    OR NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.immutable_payload_hash IS DISTINCT FROM OLD.immutable_payload_hash
    OR ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_family,NEW.message_standard,NEW.message_code,NEW.message_received_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_family,OLD.message_standard,OLD.message_code,OLD.message_received_at)
   THEN RAISE EXCEPTION 'immutable_received_utilts_source_cannot_change' USING ERRCODE='23514'; END IF;
  ELSIF NEW.execution_context_snapshot ? 'receivedUtiltsContext' THEN
   RAISE EXCEPTION 'received_utilts_context_cannot_be_backfilled' USING ERRCODE='23514';
  END IF;
 ELSIF TG_OP='INSERT' THEN
  IF jsonb_typeof(NEW.execution_context_snapshot) IN ('object','array') THEN
   NEW.execution_context_snapshot:=NEW.execution_context_snapshot-'receivedUtiltsContext';
  END IF;
  IF NEW.direction='inbound' AND NEW.message_family='UTILTS' AND NEW.message_standard='edifact'
   AND NEW.id IS NOT NULL AND NEW.company_id IS NOT NULL AND NEW.environment IN('test','production')
   AND NEW.message_code IS NOT NULL AND NEW.message_received_at IS NOT NULL AND NEW.raw_payload IS NOT NULL THEN
   NEW.immutable_payload_hash:=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex');
   NEW.execution_context_snapshot:=(CASE WHEN jsonb_typeof(NEW.execution_context_snapshot)='object' THEN NEW.execution_context_snapshot ELSE '{}'::jsonb END)
    ||jsonb_build_object('receivedUtiltsContext',jsonb_build_object('version',1,'contextOrigin','database_insert','sourceMessageId',NEW.id,
     'companyId',NEW.company_id,'environment',NEW.environment,'messageCode',NEW.message_code,'payloadHash',NEW.immutable_payload_hash,
     'sourceReceivedAt',NEW.message_received_at,'capturedAt',observed));
  END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: selection_body_v2(uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.selection_body_v2(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone, p_observed timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE body jsonb; bytes text;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_cutoff IS NULL
 OR NOT isfinite(p_cutoff) OR p_cutoff>p_observed THEN
  RAISE EXCEPTION 'source_selection_scope_unavailable' USING ERRCODE='22023'; END IF;
 WITH candidates AS MATERIALIZED (
  SELECT s.source_message_id,octet_length(s.raw_payload) AS payload_bytes FROM gridex_received_sources.sources s
  WHERE s.company_id=p_company_id AND s.environment=p_environment AND s.captured_at<=p_cutoff
   AND (s.source_received_at IS NULL OR s.source_received_at<=p_cutoff) ORDER BY s.source_message_id LIMIT 1001
 ), assessments AS MATERIALIZED (
  SELECT a.id,a.source_message_id,octet_length(a.facts_text) AS fact_bytes FROM candidates s
  CROSS JOIN LATERAL(SELECT a.id,a.source_message_id,a.facts_text FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=s.source_message_id ORDER BY a.assessed_at,a.id LIMIT 129)a
 ), totals AS (
  SELECT (SELECT count(*) FROM candidates) AS n,
   (SELECT coalesce(sum(payload_bytes),0) FROM candidates)+(SELECT coalesce(sum(fact_bytes),0) FROM assessments) AS total_bytes,
   (SELECT coalesce(max(payload_bytes),0) FROM candidates) AS max_payload,
   (SELECT coalesce(max(n),0) FROM (SELECT count(*) AS n FROM assessments GROUP BY source_message_id)c) AS max_assessments
 ), bounded AS (SELECT *,n<=1000 AND total_bytes<=6291456 AND max_payload<=262144 AND max_assessments<=128 AS complete FROM totals)
 SELECT jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,'cutoffAt',p_cutoff,
  'capturedAt',p_observed,'complete',b.complete,'sourceCount',b.n,'historyCoverage','before_ledger_unknown',
  'ledgerStartedAt',(SELECT opened_at FROM gridex_received_sources.epoch WHERE singleton),
  'sources',CASE WHEN b.complete THEN (SELECT coalesce(jsonb_agg(jsonb_build_object(
   'sourceMessageId',s.source_message_id,'payloadHash',s.payload_hash,'rawPayload',s.raw_payload,
   'receivedAt',s.source_received_at,'capturedAt',s.captured_at,'messageCode',s.message_code,
   'assessments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'previousAssessmentId',a.previous_assessment_id,
    'canonicalAssessmentId',a.canonical_assessment_id,'assessedAt',a.assessed_at,
    'availableAt',w.observed_at,'availabilityWitnessId',w.id,'factsText',a.facts_text,'factsHash',a.facts_hash) ORDER BY a.assessed_at,a.id),'[]'::jsonb)
    FROM assessments list JOIN gridex_received_sources.object_assessments a ON a.id=list.id
    LEFT JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id AND w.company_id=a.company_id AND w.environment=a.environment AND w.facts_hash=a.facts_hash
    WHERE list.source_message_id=s.source_message_id)) ORDER BY s.source_message_id),'[]'::jsonb)
   FROM candidates c JOIN gridex_received_sources.sources s USING(source_message_id)) ELSE '[]'::jsonb END)
 INTO body FROM bounded b;

 bytes:=body::text;
 IF octet_length(bytes)>8388608 THEN
  body:=jsonb_set(jsonb_set(body,'{complete}','false'),'{sources}','[]');
 END IF;
 RETURN body;
END $$;

