--
-- Name: sent_source_is_current_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.sent_source_is_current_v1(m public.ediel_messages) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR (m.status IN('sent','acknowledged')) IS NOT TRUE OR m.message_sent_at IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;
 -- The shared private provider journal supplies actual acceptance. A positive
 -- ACK projection does not approve a supply or manufacture a sent original.
 RETURN gridex_ediel_transport.accepted_source_basis_v1(m) IS NOT NULL;
END $$;

--
-- Name: source_wire_point_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.source_wire_point_v1(p_raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v1(p_raw);
 n integer; valid_n integer; point text;
BEGIN
 IF tokens IS NULL THEN RETURN NULL; END IF;
 n:=jsonb_array_length(tokens);
 IF n<8 OR tokens->0->>'tag' IS DISTINCT FROM 'UNB' OR tokens->1->>'tag' IS DISTINCT FROM 'UNH'
 OR tokens->(n-2)->>'tag' IS DISTINCT FROM 'UNT' OR tokens->(n-1)->>'tag' IS DISTINCT FROM 'UNZ'
 OR tokens->0#>>'{elements,1,1}' IS DISTINCT FROM '3'
 OR tokens->1#>>'{elements,2,0}' IS DISTINCT FROM 'PRODAT'
 OR tokens->1#>'{elements,1}' IS DISTINCT FROM jsonb_build_array(tokens->1#>>'{elements,1,0}')
 OR nullif(tokens->1#>>'{elements,1,0}','') IS NULL
 OR tokens->(n-2)#>'{elements,1}' IS DISTINCT FROM jsonb_build_array((n-2)::text)
 OR tokens->(n-2)#>'{elements,2}' IS DISTINCT FROM tokens->1#>'{elements,1}'
 OR tokens->(n-1)#>'{elements,1}' IS DISTINCT FROM '["1"]'::jsonb
 OR tokens->0#>'{elements,5}' IS DISTINCT FROM jsonb_build_array(tokens->0#>>'{elements,5,0}')
 OR nullif(tokens->0#>>'{elements,5,0}','') IS NULL
 OR EXISTS (SELECT FROM (VALUES ('UNB'),('UNH'),('UNT'),('UNZ'),('BGM')) AS required(tag)
   WHERE (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'=required.tag)<>1)
 OR EXISTS (SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM'
  AND ((t->>'index')::integer<=1 OR (t->>'index')::integer >=
   (SELECT min((l->>'index')::integer) FROM jsonb_array_elements(tokens) l WHERE l->>'tag'='LIN')))
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM'
  AND t#>'{elements,1}' IN ('["Z04"]'::jsonb,'["Z05"]'::jsonb,
   '["Z06"]'::jsonb,'["Z10"]'::jsonb))<>1
 OR tokens->0#>>'{elements,5,0}' IS DISTINCT FROM tokens->(n-1)#>>'{elements,2,0}' THEN RETURN NULL; END IF;
 SELECT count(*),count(*) FILTER (WHERE t#>>'{elements,3,3}'='9'
  AND nullif(t#>>'{elements,3,0}','') IS NOT NULL),max(t#>>'{elements,3,0}')
 INTO n,valid_n,point FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
 IF n=1 AND valid_n=1 AND length(point)<=128 THEN RETURN point; END IF;
 RETURN NULL;
END $$;

--
-- Name: structural_effect_matches_v1(uuid, text, uuid, uuid, uuid, uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.structural_effect_matches_v1(c uuid, env text, source_id uuid, assessment_id uuid, customer uuid, site uuid, point uuid, period uuid, object_id text, agency text, cutoff timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH receipts AS(SELECT source_message_id,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,applied_at,objects FROM gridex_received_sources.structural_apply_receipts
 UNION ALL SELECT source_message_id,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts)
 SELECT count(*)=1 FROM receipts r
 JOIN gridex_received_sources.sources s ON s.source_message_id=r.source_message_id AND s.company_id=r.company_id AND s.environment=r.environment AND s.payload_hash=r.payload_hash
 JOIN gridex_received_sources.object_assessments a ON a.id=r.object_assessment_id AND a.company_id=r.company_id AND a.environment=r.environment AND a.source_message_id=r.source_message_id AND a.source_payload_hash=r.payload_hash AND a.canonical_assessment_id=r.canonical_assessment_id,
 LATERAL jsonb_array_elements(a.facts_text::jsonb->'objects') own,LATERAL jsonb_array_elements(r.objects) applied
 WHERE r.company_id=c AND r.environment=env AND r.source_message_id=source_id AND r.object_assessment_id=assessment_id AND r.applied_at<=cutoff
 AND s.payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND a.facts_hash=encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
 AND own->>'disposition'='accepted' AND own#>>'{business,owner}'='reviewed-received-structure-v1'
 AND own#>>'{business,companyId}'=c::text AND own#>>'{business,environment}'=env AND own#>>'{business,customerId}'=customer::text AND own#>>'{business,siteId}'=site::text AND own#>>'{business,meteringPointId}'=point::text AND own#>>'{business,supplyPeriodId}'=period::text
 AND own#>>'{object,objectId}'=object_id AND own#>>'{object,identityAgency}'=agency AND applied->'object'=own->'object' AND applied->'wire'=own#>'{business,wire}'
 AND applied->>'meteringPointId'=point::text AND applied->>'siteId'=site::text
$$;

--
-- Name: supply_effect_assessment_owns_period_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_effect_assessment_owns_period_v1(c uuid, source_id uuid, period_id uuid, canonical_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_received_sources.supply_object_effect_receipts%rowtype;m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT stored.* INTO r FROM gridex_received_sources.supply_object_effect_receipts stored WHERE stored.company_id=c AND stored.source_message_id=source_id AND stored.canonical_assessment_id=canonical_id AND stored.environment=m.environment
  AND stored.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  AND stored.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND stored.effect_hash=encode(sha256(convert_to(stored.effect_text,'UTF8')),'hex')
  AND EXISTS(SELECT FROM jsonb_array_elements(stored.effect_text::jsonb->'resultingStates')state WHERE state->>'id'=period_id::text);
 RETURN r.id IS NOT NULL AND r.effect_text::jsonb->>'owner'='inbound-supply-object-v1' AND r.effect_text::jsonb->'object'=r.object_scope
  AND EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.company_id=c AND tr.source_message_id=source_id AND tr.payload_hash=r.payload_hash AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states)state WHERE state->>'id'=period_id::text AND r.effect_text::jsonb->'resultingStates'@>jsonb_build_array(state)));
END$$;

--
-- Name: supply_period_source_at_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_period_source_at_v1(p_company_id uuid, p_period_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) THEN RETURN NULL;END IF;
 basis:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_at,p_at+interval '1 microsecond');
 IF basis IS NULL OR basis->>'qualified' IS DISTINCT FROM 'true' OR (basis->>'marketStartAt')::timestamptz IS NULL OR (basis->>'marketStartAt')::timestamptz>p_at OR ((basis->>'marketEndAt') IS NOT NULL AND p_at>=(basis->>'marketEndAt')::timestamptz) THEN RETURN NULL;END IF;
 RETURN basis||jsonb_build_object('basisKind','exact_source_point','at',p_at);
EXCEPTION WHEN datetime_field_overflow THEN RETURN NULL;
END $$;

--
-- Name: supply_period_source_basis_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_period_source_basis_v1(p_company_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p public.customer_supply_periods%rowtype;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 tr gridex_received_sources.supply_source_transitions%rowtype;activation gridex_received_sources.normal_supply_activations%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;initial_message public.ediel_messages%rowtype;c public.customer_contracts%rowtype;s public.supplier_switch_requests%rowtype;
 expected jsonb;baseline jsonb;legal jsonb;initial_owned jsonb;source_objects jsonb;initial_wire jsonb;accepted_original jsonb;initial_transition gridex_received_sources.supply_source_transitions%rowtype;ids uuid[];version bigint;source_id uuid;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 PERFORM gridex_regulated_supply.lock_graph_v1();
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF p.source_process IN('assigned_supply','production_receipt_obligation') AND gridex_regulated_supply.ground_current_v1((p.metadata->>'sourceGroundId')::uuid,p_company_id,p.metering_point_id,p.market_start_at) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p.id AND company_id=p_company_id;
 IF NOT FOUND THEN
  baseline:=gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);
  IF baseline IS NULL THEN RETURN NULL;END IF;
  SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
  IF p.market_state_version IS DISTINCT FROM (baseline->>'marketStateVersion')::bigint THEN RETURN NULL;END IF;
  SELECT own#>'{metadata,sourceObject}' INTO initial_owned FROM gridex_received_sources.supply_source_transitions initial,jsonb_array_elements(initial.resulting_states) own WHERE initial.source_message_id=p.source_message_id AND initial.company_id=p_company_id AND own->>'id'=p.id::text;
  SELECT * INTO origin FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=p_company_id;
  SELECT jsonb_agg(own) INTO source_objects FROM jsonb_array_elements(coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->'objects') own WHERE own->>'point'=initial_owned->>'point' AND own->>'li'=initial_owned->>'li' AND own->>'start'=initial_owned->>'start';
  IF jsonb_array_length(source_objects) IS DISTINCT FROM 1 OR (source_objects#>>'{0,identityAgency}' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  RETURN baseline||jsonb_build_object('initialSourceMessageId',p.source_message_id,'legalActorId',(SELECT g.legal_actor_id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.id::text=baseline->>'groundId' AND g.company_id=p_company_id),'sourceObjects',source_objects,'dsoEdielId',coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->>'sender');
 END IF;
 IF gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,proof.source_message_id) IS NOT TRUE THEN RETURN NULL;END IF;
 IF p.source_end_message_id IS NOT NULL AND gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,p.source_end_message_id) IS NOT TRUE THEN RETURN NULL;END IF;
 version:=p.market_state_version;source_id:=p.source_message_id;
 SELECT array_agg(t.source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[ids[1],source_id,proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 legal:=gridex_ediel_inbound_context.require_v1(p_company_id,proof.source_message_id);
 SELECT * INTO initial_message FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 SELECT * INTO initial_transition FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=p_company_id;
 initial_wire:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,initial_message.id,p.id),gridex_received_sources.normal_switch_wire_v1(initial_message.raw_payload));
 IF initial_message.direction IS DISTINCT FROM 'inbound' OR initial_message.message_family IS DISTINCT FROM 'PRODAT' OR initial_message.message_code IS DISTINCT FROM 'Z04'
  OR initial_transition.payload_hash IS DISTINCT FROM encode(sha256(convert_to(initial_message.raw_payload,'UTF8')),'hex')
  OR initial_wire->>'receiver' IS DISTINCT FROM proof.legal_context->>'legalEdielId' OR nullif(initial_wire->>'sender','') IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(initial_wire->'objects') own WHERE own=proof.source_object)<>1
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=initial_message.id AND v.company_id=p_company_id AND v.environment=initial_message.environment AND v.source_payload_hash=initial_transition.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF p.market_state_version IS DISTINCT FROM version OR p.source_message_id IS DISTINCT FROM source_id OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id
  OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid
  OR p.market_start_at IS DISTINCT FROM proof.market_start_at OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at)
  OR (p.status IN('confirmed_by_grid_owner','active','ending','ended')) IS NOT TRUE OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id
  OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id OR s.lifecycle_blocked THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 SELECT * INTO activation FROM gridex_received_sources.normal_supply_activations WHERE period_id=p.id AND company_id=p_company_id;
 baseline:=CASE WHEN activation.period_id IS NOT NULL AND tr.source_message_id=proof.source_message_id THEN activation.resulting_period ELSE expected END;
 IF expected IS NULL OR baseline IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR (to_jsonb(p)-ARRAY['updated_at','status']) IS DISTINCT FROM (baseline-ARRAY['updated_at','status'])
  OR (p.status IS DISTINCT FROM baseline->>'status' AND NOT(p.status='ended' AND baseline->>'status'='ending' AND p.market_end_at<=now()))
  OR (s.status IS DISTINCT FROM proof.confirmed_switch->>'status' AND NOT(s.status='completed' AND activation.period_id IS NOT NULL)) THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active') OR c.status='terminated' AND c.termination_reason='supply_end' AND p.end_date IS NOT NULL AND c.ended_at IS NOT NULL
   AND ((c.ended_at AT TIME ZONE 'UTC')::date=p.end_date OR (c.ended_at AT TIME ZONE 'Europe/Stockholm')::date=p.end_date)) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR legal->>'legalActorId' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 accepted_original:=gridex_ediel_transport.accepted_source_basis_v1(origin);
 IF accepted_original IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'companyId',p.company_id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'siteId',coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id'),'switchId',proof.switch_id,
  'sourceMessageId',m.id,'initialSourceMessageId',proof.source_message_id,'currentSourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,
  'legalActorId',proof.legal_context->>'legalActorId','sourceObjects',jsonb_build_array(proof.source_object),'dsoEdielId',initial_wire->>'sender','originalMessageId',origin.id,'originalPayloadHash',origin.immutable_payload_hash,'originalAcceptedAt',accepted_original->>'observedAt','activated',activation.period_id IS NOT NULL);
END $$;

--
-- Name: supply_period_source_before_internal_site_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_period_source_before_internal_site_v1(p_company_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p public.customer_supply_periods%rowtype;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 tr gridex_received_sources.supply_source_transitions%rowtype;activation gridex_received_sources.normal_supply_activations%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;initial_message public.ediel_messages%rowtype;c public.customer_contracts%rowtype;s public.supplier_switch_requests%rowtype;
 expected jsonb;baseline jsonb;legal jsonb;initial_owned jsonb;source_objects jsonb;initial_wire jsonb;accepted_original jsonb;initial_transition gridex_received_sources.supply_source_transitions%rowtype;ids uuid[];version bigint;source_id uuid;
BEGIN
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p.id AND company_id=p_company_id;
 IF NOT FOUND THEN
  baseline:=gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);
  IF baseline IS NULL THEN RETURN NULL;END IF;
  SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
  IF p.market_state_version IS DISTINCT FROM (baseline->>'marketStateVersion')::bigint THEN RETURN NULL;END IF;
  SELECT own#>'{metadata,sourceObject}' INTO initial_owned FROM gridex_received_sources.supply_source_transitions initial,jsonb_array_elements(initial.resulting_states) own WHERE initial.source_message_id=p.source_message_id AND initial.company_id=p_company_id AND own->>'id'=p.id::text;
  SELECT * INTO origin FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=p_company_id;
  SELECT jsonb_agg(own) INTO source_objects FROM jsonb_array_elements(coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->'objects') own WHERE own->>'point'=initial_owned->>'point' AND own->>'li'=initial_owned->>'li' AND own->>'start'=initial_owned->>'start';
  IF jsonb_array_length(source_objects) IS DISTINCT FROM 1 OR (source_objects#>>'{0,identityAgency}' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  RETURN baseline||jsonb_build_object('initialSourceMessageId',p.source_message_id,'legalActorId',(SELECT g.legal_actor_id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.id::text=baseline->>'groundId' AND g.company_id=p_company_id),'sourceObjects',source_objects,'dsoEdielId',coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->>'sender');
 END IF;
 version:=p.market_state_version;source_id:=p.source_message_id;
 SELECT array_agg(t.source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[ids[1],source_id,proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 legal:=gridex_ediel_inbound_context.require_v1(p_company_id,proof.source_message_id);
 SELECT * INTO initial_message FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 SELECT * INTO initial_transition FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=p_company_id;
 initial_wire:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,initial_message.id,p.id),gridex_received_sources.normal_switch_wire_v1(initial_message.raw_payload));
 IF initial_message.direction IS DISTINCT FROM 'inbound' OR initial_message.message_family IS DISTINCT FROM 'PRODAT' OR initial_message.message_code IS DISTINCT FROM 'Z04'
  OR initial_transition.payload_hash IS DISTINCT FROM encode(sha256(convert_to(initial_message.raw_payload,'UTF8')),'hex')
  OR initial_wire->>'receiver' IS DISTINCT FROM proof.legal_context->>'legalEdielId' OR nullif(initial_wire->>'sender','') IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(initial_wire->'objects') own WHERE own=proof.source_object)<>1
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=initial_message.id AND v.company_id=p_company_id AND v.environment=initial_message.environment AND v.source_payload_hash=initial_transition.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF p.market_state_version IS DISTINCT FROM version OR p.source_message_id IS DISTINCT FROM source_id OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id
  OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid
  OR p.market_start_at IS DISTINCT FROM proof.market_start_at OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at)
  OR (p.status IN('confirmed_by_grid_owner','active','ending','ended')) IS NOT TRUE OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id
  OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id OR s.lifecycle_blocked THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 SELECT * INTO activation FROM gridex_received_sources.normal_supply_activations WHERE period_id=p.id AND company_id=p_company_id;
 baseline:=CASE WHEN activation.period_id IS NOT NULL AND tr.source_message_id=proof.source_message_id THEN activation.resulting_period ELSE expected END;
 IF expected IS NULL OR baseline IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR (to_jsonb(p)-ARRAY['updated_at','status']) IS DISTINCT FROM (baseline-ARRAY['updated_at','status'])
  OR (p.status IS DISTINCT FROM baseline->>'status' AND NOT(p.status='ended' AND baseline->>'status'='ending' AND p.market_end_at<=now()))
  OR (s.status IS DISTINCT FROM proof.confirmed_switch->>'status' AND NOT(s.status='completed' AND activation.period_id IS NOT NULL)) THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR legal->>'legalActorId' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 accepted_original:=gridex_ediel_transport.accepted_source_basis_v1(origin);
 IF accepted_original IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'companyId',p.company_id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'siteId',coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id'),'switchId',proof.switch_id,
  'sourceMessageId',m.id,'initialSourceMessageId',proof.source_message_id,'currentSourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,
  'legalActorId',proof.legal_context->>'legalActorId','sourceObjects',jsonb_build_array(proof.source_object),'dsoEdielId',initial_wire->>'sender','originalMessageId',origin.id,'originalPayloadHash',origin.immutable_payload_hash,'originalAcceptedAt',accepted_original->>'observedAt','activated',activation.period_id IS NOT NULL);
END $$;

--
-- Name: supply_wire_for_period_receipt_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_for_period_receipt_v1(c uuid, source_id uuid, period_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_received_sources.supply_object_effect_receipts%rowtype;wire jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT e.* INTO r FROM gridex_received_sources.supply_object_effect_receipts e WHERE e.company_id=c AND e.source_message_id=source_id AND e.environment=m.environment
  AND e.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  AND e.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND e.effect_hash=encode(sha256(convert_to(e.effect_text,'UTF8')),'hex')
  AND EXISTS(SELECT FROM jsonb_array_elements(e.effect_text::jsonb->'resultingStates')state WHERE state->>'id'=period_id::text);
 IF r.id IS NULL OR r.effect_text::jsonb->>'owner' IS DISTINCT FROM 'inbound-supply-object-v1' OR r.effect_text::jsonb->'object' IS DISTINCT FROM r.object_scope THEN RETURN NULL;END IF;
 wire:=gridex_received_sources.supply_wire_for_scope_v1(m.raw_payload,r.object_scope);
 IF wire#>'{objects,0}' IS DISTINCT FROM r.effect_text::jsonb->'wire' THEN RETURN NULL;END IF;RETURN wire;
END$$;

--
-- Name: supply_wire_for_scope_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_for_scope_v1(raw text, scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;e jsonb;header jsonb:='{}';own jsonb;first_index integer;last_index integer;key text;value text;characteristic text;
BEGIN
 IF tokens IS NULL OR scope->>'messageIndex' IS DISTINCT FROM '0' OR jsonb_typeof(scope->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(scope->'registers')<1 THEN RETURN NULL;END IF;
 first_index:=(scope#>>'{registers,0,segmentIndex}')::integer;
 SELECT x INTO t FROM jsonb_array_elements(tokens)x WHERE x->>'index'=first_index::text AND x->>'tag'='LIN';
 IF t IS NULL OR t#>>'{elements,3,0}' IS DISTINCT FROM scope->>'objectId' OR t#>>'{elements,3,3}' IS DISTINCT FROM scope->>'identityAgency' THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(scope->'registers')r WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x->>'index'=r->>'segmentIndex' AND x#>>'{elements,3,0}'=scope->>'objectId' AND x#>>'{elements,3,3}'=scope->>'identityAgency')) THEN RETURN NULL;END IF;
 SELECT min((x->>'index')::integer) INTO last_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND (x->>'index')::integer>first_index;
 IF(SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM')<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer<(SELECT min((first_lin->>'index')::integer) FROM jsonb_array_elements(tokens)first_lin WHERE first_lin->>'tag'='LIN') AND x->>'tag' IN('BGM','NAD') ORDER BY(x->>'index')::integer LOOP
  e:=t->'elements';IF t->>'tag'='BGM' THEN header:=header||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}');END IF;
  IF t->>'tag'='NAD' AND e#>>'{1,0}' IN('FR','DO') THEN key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;IF header?key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;END IF;header:=header||jsonb_build_object(key,e#>>'{2,0}');END IF;
 END LOOP;
 -- Only message-header parties precede the FIRST physical LIN. Later objects
 -- must not expose an earlier object's NAD as a second message header.
 IF nullif(header->>'sender','') IS NULL OR nullif(header->>'receiver','') IS NULL OR(header->>'code' IN('Z04','Z05')) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT x INTO t FROM jsonb_array_elements(tokens)x WHERE x->>'index'=first_index::text;
 own:=jsonb_build_object('point',scope->>'objectId','identityAgency',scope->>'identityAgency','line',t#>>'{elements,1,0}','registerCount',jsonb_array_length(scope->'registers'));
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>first_index AND(last_index IS NULL OR(x->>'index')::integer<last_index) ORDER BY(x->>'index')::integer LOOP
  e:=t->'elements';key:=NULL;value:=NULL;
  IF t->>'tag'='RFF' AND e#>>'{1,0}' IN('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
  ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
  ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN('92','93') THEN IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL;END IF;key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
  ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
  ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';END IF;
  IF key IS NOT NULL THEN IF own?key THEN RETURN NULL;END IF;own:=own||jsonb_build_object(key,nullif(value,''));END IF;
 END LOOP;
 RETURN header||jsonb_build_object('objects',jsonb_build_array(own));
END$$;

--
-- Name: supply_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}'); END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF out ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   out:=out||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   obj:=jsonb_build_object('point',nullif(e#>>'{3,0}',''),'line',e#>>'{1,0}');characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN ('92','93') THEN
    key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
    IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL; END IF;
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 IF (out->>'code' IN ('Z03','Z04','Z05','Z09')) IS NOT TRUE OR nullif(out->>'sender','') IS NULL OR nullif(out->>'receiver','') IS NULL OR jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN out||jsonb_build_object('objects',objects);
END $$;

--
-- Name: switch_brp_source_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_brp_source_basis_v1(c uuid, message uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;b jsonb;wire jsonb;at timestamptz;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c;
 IF m.id IS NULL OR o.message_id IS NULL THEN RAISE EXCEPTION 'switch_brp_original_required';END IF;
 wire:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);at:=gridex_received_sources.permission_time_v1(o.original_object->>'start');
 b:=gridex_brp_sources.require_source_v1(c,o.contract_id,actor,phase,m.environment,m.customer_id,m.site_id,m.metering_point_id,at,NULL);
 IF b->>'status' IS DISTINCT FROM 'authorized' OR b->>'sourceKind' IS DISTINCT FROM 'signed_contract_brp_declaration' OR wire IS NULL OR at IS NULL
  OR b->>'companyId' IS DISTINCT FROM c::text OR b->>'environment' IS DISTINCT FROM m.environment OR b->>'contractId' IS DISTINCT FROM o.contract_id::text
  OR b->>'customerId' IS DISTINCT FROM m.customer_id::text OR b->>'siteId' IS DISTINCT FROM m.site_id::text OR b->>'meteringPointId' IS DISTINCT FROM m.metering_point_id::text
  OR (b->>'at')::timestamptz IS DISTINCT FROM at OR b->>'legalSenderId' IS DISTINCT FROM wire->>'sender' OR b->>'legalReceiverId' IS DISTINCT FROM wire->>'receiver'
  OR b->>'pointId' IS DISTINCT FROM o.original_object->>'point' OR b->>'identityAgency' IS DISTINCT FROM o.original_object->>'identityAgency' OR b->>'gridArea' IS DISTINCT FROM o.original_object->>'gridArea'
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_rendered_at IS NULL
  OR gridex_received_sources.outbound_single_brp_v1(m.raw_payload) IS DISTINCT FROM b->>'brpEdielId'
 THEN RAISE EXCEPTION 'switch_signed_source_brp_required';END IF;RETURN b;
END$$;

--
-- Name: switch_contract_request_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_contract_request_basis_v1(c uuid, message uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;basis jsonb;wire jsonb;method text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c;
 IF m.id IS NULL OR o.message_id IS NULL THEN RAISE EXCEPTION 'switch_signed_requested_method_original_required';END IF;
 basis:=gridex_metering_method_changes.contract_request_basis_v1(c,o.contract_id,actor,phase,m.environment);
 wire:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);
 method:=gridex_received_sources.switch_requested_method_v1(m.raw_payload);
 IF basis->>'status' IS DISTINCT FROM 'authorized' OR wire IS NULL OR method IS NULL OR method IS DISTINCT FROM basis->>'requestedMethod'
  OR basis->>'companyId' IS DISTINCT FROM c::text OR basis->>'environment' IS DISTINCT FROM m.environment OR basis->>'contractId' IS DISTINCT FROM o.contract_id::text OR basis->>'protectedContractHash' IS DISTINCT FROM o.contract_hash
  OR basis->>'customerId' IS DISTINCT FROM m.customer_id::text OR basis->>'siteId' IS DISTINCT FROM m.site_id::text OR basis->>'meteringPointId' IS DISTINCT FROM m.metering_point_id::text
  OR basis->>'legalSenderId' IS DISTINCT FROM wire->>'sender' OR basis->>'legalReceiverId' IS DISTINCT FROM wire->>'receiver'
  OR basis->>'pointId' IS DISTINCT FROM o.original_object->>'point' OR basis->>'identityAgency' IS DISTINCT FROM o.original_object->>'identityAgency' OR basis->>'gridArea' IS DISTINCT FROM o.original_object->>'gridArea'
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_rendered_at IS NULL
 THEN RAISE EXCEPTION 'switch_signed_new_agreement_requested_method_required';END IF;
 RETURN basis;
END$$;

--
-- Name: switch_origin_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_origin_wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w jsonb:=gridex_received_sources.normal_switch_wire_v1(raw);tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;installation jsonb;customer jsonb;own jsonb;
BEGIN
 IF w IS NULL OR w->>'code' IS DISTINCT FROM 'Z03' OR jsonb_array_length(w->'objects')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) item WHERE item->>'tag'='LIN')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT e FROM jsonb_array_elements(tokens)e LOOP
  IF t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' THEN IF customer IS NOT NULL THEN RETURN NULL;END IF;customer:=jsonb_build_object('customerQualifier',t#>>'{elements,2,1}','customerAgency',t#>>'{elements,2,2}');END IF;
  IF t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IT' THEN IF installation IS NOT NULL THEN RETURN NULL;END IF;installation:=jsonb_build_object('installationPoint',t#>>'{elements,2,0}','installationAgency',t#>>'{elements,2,2}');END IF;
 END LOOP;
 own:=w#>'{objects,0}';
 IF nullif(own->>'point','') IS NULL OR (own->>'identityAgency' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
 IF installation IS NOT NULL AND (installation->>'installationPoint' IS DISTINCT FROM own->>'point' OR installation->>'installationAgency' IS DISTINCT FROM own->>'identityAgency') THEN RETURN NULL;END IF;
 IF customer IS NULL THEN RETURN NULL;END IF;
 own:=own||customer||jsonb_build_object('installationPoint',own->>'point','installationAgency',own->>'identityAgency');
 RETURN w||jsonb_build_object('objects',jsonb_build_array(own));
END $$;

--
-- Name: switch_original_message_immutable_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_original_message_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT FROM gridex_received_sources.switch_originals o WHERE o.message_id=OLD.id) AND
 ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_standard,NEW.message_family,NEW.message_code,NEW.intent_id,NEW.outbound_request_id,NEW.source_operation_id,NEW.switch_request_id,NEW.customer_id,NEW.site_id,NEW.metering_point_id,NEW.raw_payload,NEW.immutable_payload_hash,NEW.immutable_rendered_at,NEW.original_message_id)
 IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_standard,OLD.message_family,OLD.message_code,OLD.intent_id,OLD.outbound_request_id,OLD.source_operation_id,OLD.switch_request_id,OLD.customer_id,OLD.site_id,OLD.metering_point_id,OLD.raw_payload,OLD.immutable_payload_hash,OLD.immutable_rendered_at,OLD.original_message_id)
 THEN RAISE EXCEPTION 'switch_original_bound_message_immutable';END IF;RETURN NEW;
END $$;

--
-- Name: switch_requested_method_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_requested_method_v1(raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE token jsonb;active_object boolean:=false;common_open boolean:=true;attribute text;method text;seen_cci boolean:=false;
BEGIN
 FOR token IN SELECT item FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(raw)) item LOOP
  IF token->>'tag'='LIN' THEN IF active_object THEN RETURN NULL;END IF;active_object:=true;attribute:=NULL;CONTINUE;END IF;
  IF NOT active_object OR NOT common_open THEN CONTINUE;END IF;
  IF token->>'tag'='DTM' AND NOT seen_cci THEN CONTINUE;END IF;
  IF token->>'tag' IN('RFF','NAD','DTM','UNT') THEN common_open:=false;attribute:=NULL;CONTINUE;END IF;
  IF token->>'tag'='CCI' THEN seen_cci:=true;attribute:=token#>>'{elements,2,0}';CONTINUE;END IF;
  IF token->>'tag'='CAV' AND attribute='Z04' THEN
   IF method IS NOT NULL OR nullif(token#>>'{elements,1,0}','') IS NULL THEN RETURN NULL;END IF;
   method:=token#>>'{elements,1,0}';attribute:=NULL;
  END IF;
 END LOOP;
 RETURN method;
END$$;

--
-- Name: validate_prodat_application_v1(text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_application_v1(raw text, facts jsonb, facet jsonb, response jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE object jsonb;reg jsonb;scope jsonb;reasons jsonb;seen jsonb:='[]';state text;
BEGIN
 IF jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['coverage','headerDecision','objects','owner','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'owner' IS DISTINCT FROM 'canonical-prodat-application-all-v1' OR facet->>'coverage' IS DISTINCT FROM 'canonical_own_application_only'
  OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') OR(facet->>'headerDecision' IN('accepted','rejected','held')) IS NOT TRUE
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(facet->'objects')<>jsonb_array_length(facts#>'{registerValidation,objects}')
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only' THEN RETURN false;END IF;
 FOR object IN SELECT e FROM jsonb_array_elements(facet->'objects')e LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['applicationDecision','identityAgency','messageIndex','messageReference','objectId','reasonCodes','registers']::text[] THEN RETURN false;END IF;
  scope:=object-'applicationDecision'-'reasonCodes';reasons:=object->'reasonCodes';state:=object->>'applicationDecision';
  IF(state IN('accepted','rejected','held')) IS NOT TRUE OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)>128
   OR EXISTS(SELECT FROM jsonb_array_elements(reasons)e WHERE jsonb_typeof(e)<>'string' OR e#>>'{}'!~'^[A-Za-z0-9_.:-]{1,128}$')
   OR (SELECT count(*) FROM jsonb_array_elements(reasons)e)<>(SELECT count(DISTINCT e) FROM jsonb_array_elements(reasons)e)
   OR (state='accepted' AND jsonb_array_length(reasons)<>0) OR(state<>'accepted' AND jsonb_array_length(reasons)=0) OR seen@>jsonb_build_array(scope) THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(scope);
  SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e-'disposition'-'reasons'=scope;
  IF reg IS NULL OR state='accepted' AND(reg->>'disposition' IS DISTINCT FROM 'accepted' OR facet->>'headerDecision' IS DISTINCT FROM 'accepted' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted')
   OR reg->>'disposition'='rejected' AND state='accepted' OR state='accepted' AND EXISTS(SELECT FROM jsonb_array_elements(coalesce(response->'responses','[]'))e WHERE e->>'ercCode'<>'100'
     AND(e->>'scope'='message' OR e->'lineIndex'=object#>'{registers,0,segmentIndex}')) THEN RETURN false;END IF;
 END LOOP;
 -- The existing actual register binder covers all physical LIN; application
 -- grouping must be exactly that partition, never a caller-selected subset.
 IF EXISTS(SELECT FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE NOT seen@>jsonb_build_array(e-'disposition'-'reasons')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

--
-- Name: validate_prodat_application_v2(uuid, uuid, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_application_v2(c uuid, source_id uuid, raw text, facts jsonb, facet jsonb, response jsonb, source_function jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF source_function IS NULL THEN RETURN gridex_received_sources.validate_prodat_application_v1(raw,facts,facet,response);END IF;
 IF gridex_received_sources.validate_prodat_source_function_v1(c,source_id,raw,facts,source_function) IS NOT TRUE THEN RETURN false;END IF;
 -- V1's physical/full-application checks are retained. Its historical global
 -- functional prerequisite is not an application fact: V5 supplies a distinct
 -- complete genuine source/function partition. The temporary shape input is
 -- neither persisted nor returned, and grants no application-based effect.
 RETURN gridex_received_sources.validate_prodat_application_v1(raw,facts||jsonb_build_object('functionalDecision','accepted'),facet,response);
END $$;

--
-- Name: validate_prodat_responses_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_responses_v1(raw text, facts jsonb, facet jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);object jsonb;response jsonb;register_object jsonb;first_line jsonb;line jsonb;indices jsonb;seen integer[]:='{}';idx integer;own_li text;first_end integer;n integer;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')<>1
  OR jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['objects','responses','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_typeof(facet->'responses') IS DISTINCT FROM 'array'
  OR jsonb_array_length(facet->'objects')>8192 OR jsonb_array_length(facet->'responses')>8192 THEN RETURN false;END IF;
 FOR object IN SELECT x FROM jsonb_array_elements(facet->'objects')x LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['id','li','lineIndex','outcome','registerLineIndices']::text[]
   OR (object->>'outcome' IN('positive','negative','held')) IS NOT TRUE OR jsonb_typeof(object->'lineIndex') IS DISTINCT FROM 'number'
   OR jsonb_typeof(object->'registerLineIndices') IS DISTINCT FROM 'array' OR jsonb_array_length(object->'registerLineIndices')=0 OR object->'lineIndex' IS DISTINCT FROM object#>'{registerLineIndices,0}' THEN RETURN false;END IF;
  idx:=(object->>'lineIndex')::integer;SELECT t INTO first_line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND(t->>'index')::integer=idx;
  IF first_line IS NULL OR to_jsonb(nullif(first_line#>>'{elements,3,0}','')) IS DISTINCT FROM nullif(object->'id','null'::jsonb) THEN RETURN false;END IF;
  SELECT min((t->>'index')::integer) INTO first_end FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::integer>idx AND t->>'tag' IN('NAD','LIN','UNT');
  SELECT count(*),min(t#>>'{elements,1,1}') INTO n,own_li FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND(t->>'index')::integer>idx AND(t->>'index')::integer<first_end;
  IF n>1 OR to_jsonb(nullif(own_li,'')) IS DISTINCT FROM nullif(object->'li','null'::jsonb) THEN RETURN false;END IF;
  SELECT x INTO register_object FROM jsonb_array_elements(facts#>'{registerValidation,objects}')x WHERE x#>'{registers,0,segmentIndex}'=object->'lineIndex';
  SELECT jsonb_agg(x->'segmentIndex' ORDER BY ord) INTO indices FROM jsonb_array_elements(register_object->'registers') WITH ORDINALITY v(x,ord);
  IF register_object IS NULL OR indices IS DISTINCT FROM object->'registerLineIndices' OR register_object->'objectId' IS DISTINCT FROM object->'id' THEN RETURN false;END IF;
  FOR idx IN SELECT value::text::integer FROM jsonb_array_elements(object->'registerLineIndices') LOOP
   IF idx=ANY(seen) THEN RETURN false;END IF;seen:=array_append(seen,idx);
   SELECT t INTO line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND(t->>'index')::integer=idx;
   IF line IS NULL OR line#>'{elements,3,0}' IS DISTINCT FROM first_line#>'{elements,3,0}' OR line#>'{elements,3,3}' IS DISTINCT FROM first_line#>'{elements,3,3}' THEN RETURN false;END IF;
  END LOOP;
  IF object->>'outcome'='positive' AND(facts->>'applicationDecision' IS DISTINCT FROM 'accepted' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted' OR register_object->>'disposition' IS DISTINCT FROM 'accepted') THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND NOT((t->>'index')::integer=ANY(seen))) THEN RETURN false;END IF;
 FOR response IN SELECT x FROM jsonb_array_elements(facet->'responses')x LOOP
  IF jsonb_typeof(response) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(response)k) IS DISTINCT FROM ARRAY['ercCode','fieldCode','id','li','lineIndex','scope','text']::text[]
   OR (response->>'scope' IN('message','object')) IS NOT TRUE OR jsonb_typeof(response->'ercCode') IS DISTINCT FROM 'string' OR response->>'ercCode'!~'^[0-9]{1,3}$'
   OR jsonb_typeof(response->'text') IS DISTINCT FROM 'string' OR length(response->>'text') NOT BETWEEN 1 AND 512 OR response->>'text'~'[[:cntrl:]]'
   OR (jsonb_typeof(response->'fieldCode') IN('string','null')) IS NOT TRUE THEN RETURN false;END IF;
  IF response->>'scope'='message' THEN IF response->'lineIndex' IS DISTINCT FROM 'null'::jsonb OR response->>'ercCode'='100' THEN RETURN false;END IF;
  ELSE SELECT x INTO object FROM jsonb_array_elements(facet->'objects')x WHERE x->'lineIndex'=response->'lineIndex';
   IF object IS NULL OR object->>'outcome' IS DISTINCT FROM (CASE WHEN response->>'ercCode'='100' THEN 'positive' ELSE 'negative' END) OR object->'id' IS DISTINCT FROM response->'id' OR object->'li' IS DISTINCT FROM response->'li' THEN RETURN false;END IF;
  END IF;
  IF response->>'ercCode'<>'100' AND(facts->>'applicationDecision' IN('rejected','manual_review')) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')o WHERE o->>'outcome'<>'held' AND NOT EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='object' AND r->'lineIndex'=o->'lineIndex'))
  OR(EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='message') AND EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='object')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

--
-- Name: validate_prodat_source_function_v1(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_source_function_v1(c uuid, source_id uuid, raw text, facts jsonb, facet jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r gridex_customer_life_events.inbound_context_receipts%rowtype;object jsonb;scope jsonb;reg jsonb;seen jsonb:='[]';state text;reasons jsonb;m public.ediel_messages%rowtype;context_xmin numeric;
BEGIN
 IF jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['coverage','objects','owner','sourceContextFactsHash','sourceContextReceiptId','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'owner' IS DISTINCT FROM 'canonical-prodat-source-function-v1' OR facet->>'coverage' IS DISTINCT FROM 'customer_life_event_only'
  OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') OR facet->>'sourceContextFactsHash'!~'^[a-f0-9]{64}$'
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(facet->'objects')<>jsonb_array_length(facts#>'{registerValidation,objects}')
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only' THEN RETURN false;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 SELECT stored.xmin::text::numeric INTO context_xmin FROM gridex_customer_life_events.inbound_context_receipts stored WHERE stored.id=(facet->>'sourceContextReceiptId')::uuid AND stored.company_id=c AND stored.source_message_id=source_id;
 SELECT * INTO r FROM gridex_customer_life_events.inbound_context_receipts WHERE id=(facet->>'sourceContextReceiptId')::uuid AND company_id=c AND source_message_id=source_id FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' OR m.raw_payload IS DISTINCT FROM raw
  OR r.id IS NULL OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM facet->>'sourcePayloadHash' OR r.context_facts_hash IS DISTINCT FROM facet->>'sourceContextFactsHash'
  OR r.context_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.context_facts::text,'UTF8')),'hex') OR r.context_facts->>'rawPayload' IS DISTINCT FROM raw
  OR r.context_facts->>'status' IS DISTINCT FROM 'authorized' OR context_xmin=mod(pg_current_xact_id()::text::numeric,4294967296) THEN RETURN false;END IF;
 FOR object IN SELECT e FROM jsonb_array_elements(facet->'objects')e LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['functionalDecision','identityAgency','messageIndex','messageReference','objectId','reasonCodes','registers']::text[] THEN RETURN false;END IF;
  scope:=object-'functionalDecision'-'reasonCodes';state:=object->>'functionalDecision';reasons:=object->'reasonCodes';
  IF(state IN('accepted','held','not_applicable')) IS NOT TRUE OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)>128
   OR EXISTS(SELECT FROM jsonb_array_elements(reasons)e WHERE jsonb_typeof(e)<>'string' OR e#>>'{}'!~'^[A-Za-z0-9_.:-]{1,128}$')
   OR(SELECT count(*) FROM jsonb_array_elements(reasons)e)<>(SELECT count(DISTINCT e) FROM jsonb_array_elements(reasons)e)
   OR state='accepted' AND jsonb_array_length(reasons)<>0 OR state<>'accepted' AND jsonb_array_length(reasons)=0 OR seen@>jsonb_build_array(scope) THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(scope);
  SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e-'disposition'-'reasons'=scope;
  IF reg IS NULL OR state='accepted' AND gridex_customer_life_events.inbound_context_object_is_qualified_v1(c,source_id,r.id,scope) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE NOT seen@>jsonb_build_array(e-'disposition'-'reasons')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value OR data_exception THEN RETURN false;
END $_$;

--
-- Name: validate_utilts_functional_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_functional_v1(raw text, projection jsonb, transactions jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE selected jsonb;item jsonb;error_item jsonb;eligible jsonb;i integer;
BEGIN
 IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(raw,transactions),false)
  OR jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions') NOT BETWEEN 1 AND 999 THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO eligible FROM jsonb_array_elements(transactions->'transactions') WITH ORDINALITY t(value,ord)
  WHERE value->>'disposition'='processability_rejected' AND value->>'responseType'='utilts_err';
 IF jsonb_array_length(eligible)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(eligible)-1 LOOP
  selected:=eligible->i;item:=projection->'transactions'->i;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','errors']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM selected->'transactionIndex' OR item->'transactionId' IS DISTINCT FROM selected->'transactionId'
   OR jsonb_typeof(item->'transactionId') IS DISTINCT FROM 'string' OR length(item->>'transactionId') NOT BETWEEN 1 AND 35
   OR jsonb_typeof(item->'errors') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'errors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
  FOR error_item IN SELECT value FROM jsonb_array_elements(item->'errors') LOOP
   -- Shape and actual national projection binding only. The shared ERR guide
   -- owns allowed codes/semantics; no internal diagnostic or local code map.
   IF jsonb_typeof(error_item) IS DISTINCT FROM 'object' OR error_item-ARRAY['code','referenceQualifier','referenceNumber']<>'{}'::jsonb
    OR jsonb_typeof(error_item->'code') IS DISTINCT FROM 'string' OR error_item->>'code' !~ '^E[A-Z0-9]{1,7}$'
    OR jsonb_typeof(error_item->'referenceQualifier') IS DISTINCT FROM 'string' OR error_item->>'referenceQualifier' !~ '^[A-Z0-9]{1,3}$'
    OR error_item->'referenceNumber' IS DISTINCT FROM item->'transactionId' THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT count(*) FROM jsonb_array_elements(item->'errors'))<>(SELECT count(DISTINCT value->>'code') FROM jsonb_array_elements(item->'errors')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

--
-- Name: validate_utilts_functional_v2(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_functional_v2(raw text, projection jsonb, transactions jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE selected jsonb;item jsonb;error_item jsonb;owner_item jsonb;eligible jsonb;i integer;
BEGIN
 IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(raw,transactions),false)
  OR jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '2'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions') NOT BETWEEN 1 AND 999 THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO eligible FROM jsonb_array_elements(transactions->'transactions') WITH ORDINALITY t(value,ord)
  WHERE value->>'disposition'='processability_rejected' AND value->>'responseType'='utilts_err';
 IF jsonb_array_length(eligible)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(eligible)-1 LOOP
  selected:=eligible->i;item:=projection->'transactions'->i;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','errors']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM selected->'transactionIndex' OR item->'transactionId' IS DISTINCT FROM selected->'transactionId'
   OR jsonb_typeof(item->'transactionId') IS DISTINCT FROM 'string' OR length(item->>'transactionId') NOT BETWEEN 1 AND 35
   OR jsonb_typeof(item->'errors') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'errors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
  FOR error_item IN SELECT value FROM jsonb_array_elements(item->'errors') LOOP
   IF jsonb_typeof(error_item) IS DISTINCT FROM 'object' OR error_item-ARRAY['code','ownerIssueCodes','originalScope','referenceQualifier','referenceNumber','responseReference']<>'{}'::jsonb
    OR jsonb_typeof(error_item->'code') IS DISTINCT FROM 'string' OR error_item->>'code' !~ '^E[A-Z0-9]{1,7}$'
    OR jsonb_typeof(error_item->'ownerIssueCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(error_item->'ownerIssueCodes') NOT BETWEEN 1 AND 128
    OR coalesce(error_item->>'originalScope','') NOT IN ('message','transaction')
    OR (error_item->'referenceQualifier' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(error_item->'referenceQualifier') IS DISTINCT FROM 'string' OR error_item->>'referenceQualifier' !~ '^[A-Z0-9]{1,3}$'))
    OR jsonb_typeof(error_item->'responseReference') IS DISTINCT FROM 'object' OR (error_item->'responseReference')-ARRAY['qualifier','number']<>'{}'::jsonb
    OR error_item#>>'{responseReference,qualifier}' IS DISTINCT FROM 'TN' OR error_item#>'{responseReference,number}' IS DISTINCT FROM item->'transactionId'
    OR (error_item->>'originalScope'='message' AND error_item->'referenceNumber' IS DISTINCT FROM 'null'::jsonb)
    OR (error_item->>'originalScope'='transaction' AND (error_item->>'referenceQualifier' IS DISTINCT FROM 'TN' OR error_item->'referenceNumber' IS DISTINCT FROM item->'transactionId')) THEN RETURN false; END IF;
   FOR owner_item IN SELECT value FROM jsonb_array_elements(error_item->'ownerIssueCodes') LOOP
    IF jsonb_typeof(owner_item) IS DISTINCT FROM 'string' OR NOT coalesce(selected->'issueCodes' @> jsonb_build_array(owner_item),false) THEN RETURN false; END IF;
   END LOOP;
   IF (SELECT count(*) FROM jsonb_array_elements(error_item->'ownerIssueCodes'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(error_item->'ownerIssueCodes')) THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT count(*) FROM jsonb_array_elements(item->'errors'))<>(SELECT count(DISTINCT value-ARRAY['ownerIssueCodes','responseReference']) FROM jsonb_array_elements(item->'errors')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

--
-- Name: validate_utilts_header_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_header_v1(raw text, projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;item jsonb;
BEGIN
 IF jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','applicationErrors']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'applicationErrors') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'applicationErrors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='UTILTS') THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(projection->'applicationErrors') LOOP
  -- Only shape/original binding here. The shared national guide's native
  -- checker owns ERC/text semantics; no second field or text/error table.
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['ercCode','fieldCode','text']<>'{}'::jsonb OR item->>'ercCode' NOT IN ('41','42')
   OR jsonb_typeof(item->'ercCode') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'fieldCode') IS DISTINCT FROM 'string' OR item->>'fieldCode' !~ '^[A-Za-z0-9_./-]{1,17}$'
   OR jsonb_typeof(item->'text') IS DISTINCT FROM 'string' OR length(item->>'text') NOT BETWEEN 1 AND 512 OR item->>'text' ~ '[[:cntrl:]]' THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

--
-- Name: validate_utilts_transactions_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_transactions_v1(raw text, projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;membership jsonb;item jsonb;physical jsonb;ordinal integer;expected_response text;
BEGIN
 IF jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions')>999 THEN RETURN false; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);IF tokens IS NULL THEN RETURN false;END IF;
 SELECT coalesce(jsonb_agg(t ORDER BY (t->>'index')::integer),'[]') INTO membership FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE';
 IF jsonb_array_length(membership)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR item,ordinal IN SELECT value,(i-1)::integer FROM jsonb_array_elements(projection->'transactions') WITH ORDINALITY x(value,i) LOOP
  physical:=membership->ordinal;
  expected_response:=CASE item->>'disposition' WHEN 'accepted' THEN 'positive_aperak' WHEN 'syntax_rejected' THEN 'negative_contrl' WHEN 'guide_rejected' THEN 'negative_aperak' WHEN 'processability_rejected' THEN 'utilts_err' WHEN 'internal_review' THEN 'none' END;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','disposition','responseType','issueCodes']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM to_jsonb(ordinal) OR item->'transactionId' IS DISTINCT FROM coalesce(to_jsonb(nullif(physical#>>'{elements,2,0}','')),'null'::jsonb)
   OR expected_response IS NULL OR item->>'responseType' IS DISTINCT FROM expected_response OR jsonb_typeof(item->'issueCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'issueCodes')>128
   OR EXISTS(SELECT FROM jsonb_array_elements(item->'issueCodes') code WHERE jsonb_typeof(code) IS DISTINCT FROM 'string' OR code#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$') THEN RETURN false; END IF;
  IF item->>'disposition'='accepted' AND (physical#>>'{elements,1,0}' IS DISTINCT FROM '24' OR nullif(item->>'transactionId','') IS NULL OR length(item->>'transactionId')>35 OR jsonb_array_length(item->'issueCodes')<>0) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

--
-- Name: wire_tokens_bounded_v1(text, integer); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.wire_tokens_bounded_v1(p_raw text, p_max_lines integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
 component_sep text:=':'; data_sep text:='+'; release_char text:='?'; terminator text:='''';
 decimal_mark text:='.'; reserved text:=' '; body text; ch text; chars text[];
 released boolean:=false; current_component text:=''; current_element jsonb:='[]'; elements jsonb:='[]';
 result jsonb:='[]'; tag text; segment_count integer:=0; line_count integer:=0;
 component_size integer:=0; component_count integer:=0; element_count integer:=0;
BEGIN
 IF (p_max_lines BETWEEN 1 AND 999999) IS NOT TRUE OR p_raw IS NULL OR octet_length(p_raw)>262144 THEN RETURN NULL; END IF;
 -- Read advice before CRLF/LF normalization. No inferred repetition grammar.
 body:=p_raw;
 IF upper(left(body,3))='UNA' THEN
  IF left(body,3)<>'UNA' OR char_length(body)<9 THEN RETURN NULL; END IF;
  component_sep:=substr(body,4,1);data_sep:=substr(body,5,1);decimal_mark:=substr(body,6,1);
  release_char:=substr(body,7,1);reserved:=substr(body,8,1);terminator:=substr(body,9,1);body:=substr(body,10);
 END IF;
 IF reserved<>' ' OR decimal_mark NOT IN ('.',',')
 OR decimal_mark=ANY(ARRAY[component_sep,data_sep,release_char,terminator])
 OR (SELECT count(DISTINCT value) FROM unnest(ARRAY[component_sep,data_sep,release_char,terminator]) value)<>4
 OR EXISTS(SELECT FROM unnest(ARRAY[component_sep,data_sep,release_char,terminator]) value
   WHERE ascii(value)<33 OR ascii(value)>126 OR value ~ '[A-Za-z0-9]') THEN RETURN NULL; END IF;
 body:=replace(replace(body,E'\r\n',''),E'\n','');
 IF strpos(body,E'\r')>0 OR right(body,1)<>terminator THEN RETURN NULL; END IF;
 -- NULL delimiter enumerates code points, NOT segments/elements. Exactly one
 -- state machine consumes these; decoded literals are never split again.
 chars:=string_to_array(body,NULL);
 FOREACH ch IN ARRAY chars LOOP
  IF released THEN
   current_component:=current_component||ch;component_size:=component_size+1;released:=false;
  ELSIF ch=release_char THEN released:=true;
  ELSIF ch=component_sep OR ch=data_sep OR ch=terminator THEN
   -- Match canonical leading segment trim. Other whitespace forms are held
   -- explicitly; in particular a released trailing space must not be trimmed.
   IF elements='[]'::jsonb AND current_element='[]'::jsonb THEN current_component:=ltrim(current_component,E' \t'); END IF;
   IF ch=terminator AND current_component<>rtrim(current_component,E' \t') THEN RETURN NULL; END IF;
   IF ch=terminator AND elements='[]'::jsonb AND current_element='[]'::jsonb AND current_component='' THEN CONTINUE; END IF;
   current_element:=current_element||jsonb_build_array(current_component);component_count:=component_count+1;
   current_component:='';component_size:=0;
   IF component_count>128 THEN RETURN NULL; END IF;
   IF ch<>component_sep THEN
    elements:=elements||jsonb_build_array(current_element);element_count:=element_count+1;
    current_element:='[]';component_count:=0;
    IF element_count>128 THEN RETURN NULL; END IF;
   END IF;
   IF ch=terminator THEN
    tag:=elements#>>'{0,0}';
    IF jsonb_array_length(elements->0)<>1 OR tag !~ '^[A-Z]{3}$' OR tag='UNA' THEN RETURN NULL; END IF;
    IF tag='LIN' THEN line_count:=line_count+1; END IF;
    IF segment_count>=4096 OR line_count>p_max_lines THEN RETURN NULL; END IF;
    result:=result||jsonb_build_array(jsonb_build_object('index',segment_count,'tag',tag,'elements',elements));
    segment_count:=segment_count+1;elements:='[]';element_count:=0;
   END IF;
  ELSE current_component:=current_component||ch;component_size:=component_size+1;
  END IF;
  IF component_size>4096 THEN RETURN NULL; END IF;
 END LOOP;
 IF released OR current_component<>'' OR elements<>'[]'::jsonb OR current_element<>'[]'::jsonb THEN RETURN NULL; END IF;
 RETURN result;
END $_$;

--
-- Name: witness_correction_concern_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.witness_correction_concern_v1(p_company_id uuid, p_environment text, p_capture_id uuid, p_facts_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE captured gridex_received_sources.correction_concerns%rowtype; witness gridex_received_sources.correction_witnesses%rowtype; snap text;
BEGIN
 SELECT c.* INTO captured FROM gridex_received_sources.correction_concerns c
 WHERE c.id=p_capture_id AND c.company_id=p_company_id AND c.environment=p_environment AND c.facts_hash=p_facts_hash
  AND c.created_xid<>pg_current_xact_id();
 IF captured.id IS NULL THEN RAISE EXCEPTION 'correction_availability_unproven' USING ERRCODE='23514'; END IF;
 snap:=pg_current_snapshot()::text;
 INSERT INTO gridex_received_sources.correction_witnesses(capture_id,company_id,environment,facts_hash,visibility_snapshot)
 VALUES(captured.id,captured.company_id,captured.environment,captured.facts_hash,snap) ON CONFLICT(capture_id) DO NOTHING;
 SELECT * INTO STRICT witness FROM gridex_received_sources.correction_witnesses WHERE capture_id=captured.id;
 RETURN gridex_received_sources.correction_receipt_v1(captured)||jsonb_build_object('witnessId',witness.id,'availableAt',witness.observed_at);
END $$;

--
-- Name: witness_document_reference_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.witness_document_reference_v1(p_company_id uuid, p_environment text, p_outcome_id uuid, p_facts_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_received_sources.document_reference_outcomes%rowtype; w gridex_received_sources.document_reference_witnesses%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.document_reference_outcomes WHERE id=p_outcome_id AND company_id=p_company_id AND environment=p_environment AND facts_hash=p_facts_hash AND created_xid<>pg_current_xact_id();
 IF o.id IS NULL THEN RAISE EXCEPTION 'document_outcome_not_committed' USING ERRCODE='23514'; END IF;
 INSERT INTO gridex_received_sources.document_reference_witnesses(outcome_id,company_id,environment,facts_hash,visibility_snapshot)
 VALUES(o.id,o.company_id,o.environment,o.facts_hash,pg_current_snapshot()::text) ON CONFLICT(outcome_id) DO NOTHING;
 SELECT * INTO STRICT w FROM gridex_received_sources.document_reference_witnesses WHERE outcome_id=o.id;
 RETURN jsonb_build_object('attemptId',o.attempt_id,'outcomeId',o.id,'factsHash',o.facts_hash,'witnessId',w.id,'availableAt',w.observed_at);
END $$;

--
-- Name: witness_object_availability(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.witness_object_availability(p_company_id uuid, p_environment text, p_assessment_id uuid, p_facts_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE found_id uuid; source_id uuid; snap text; witness gridex_received_sources.object_availability_witnesses%rowtype;
BEGIN
 -- A result from the current transaction is expressly insufficient. The owner
 -- append must have committed before this separate service RPC can observe it.
 SELECT a.id,a.source_message_id,pg_current_snapshot()::text INTO found_id,source_id,snap
 FROM gridex_received_sources.object_assessments a
 WHERE a.id=p_assessment_id AND a.company_id=p_company_id AND a.environment=p_environment
 AND a.facts_hash=p_facts_hash AND a.created_xid<>pg_current_xact_id();
 IF found_id IS NULL THEN RAISE EXCEPTION 'source_object_availability_unproven' USING ERRCODE='23514'; END IF;
 INSERT INTO gridex_received_sources.object_availability_witnesses(assessment_id,company_id,environment,source_message_id,facts_hash,visibility_snapshot)
 VALUES(found_id,p_company_id,p_environment,source_id,p_facts_hash,snap) ON CONFLICT(assessment_id) DO NOTHING;
 SELECT * INTO STRICT witness FROM gridex_received_sources.object_availability_witnesses WHERE assessment_id=found_id;
 RETURN jsonb_build_object('version',1,'witnessId',witness.id,'assessmentId',found_id,'companyId',p_company_id,'environment',p_environment,'factsHash',p_facts_hash,'availableAt',witness.observed_at);
END $$;

--
-- Name: z02_address_source_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.z02_address_source_basis_v1(p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;
 original public.ediel_messages%rowtype;candidate public.ediel_messages%rowtype;
 request public.customer_info_requests%rowtype;candidate_request public.customer_info_requests%rowtype;
 site public.customer_sites%rowtype;customer public.customers%rowtype;
 snapshot public.customer_operation_request_snapshots%rowtype;
 dispatch gridex_ediel_transport.attempts%rowtype;
 source_wire jsonb;original_wire jsonb;source_object jsonb;original_object jsonb;
 candidate_wire jsonb;candidate_object jsonb;receipt jsonb;
 source_transport jsonb;candidate_transport jsonb;
 matches integer:=0;object_matches integer;request_id uuid;original_id uuid;
 expected_object text;expected_identity text;expected_qualifier text;address_hash text;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN
  RAISE EXCEPTION 'z02_address_source_service_required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Service execution is not authority to disclose another company's source.
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'z02_address_source_actor_required' USING ERRCODE='42501';END IF;
 PERFORM cm.user_id FROM public.company_memberships cm
  WHERE cm.company_id=s.company_id AND cm.user_id=p_actor_user_id
   AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND OR NOT (
  coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,s.company_id,'ediel.read'),false)
  OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,s.company_id,'communication.read'),false)) THEN
  RAISE EXCEPTION 'z02_address_source_actor_read_required' USING ERRCODE='42501';
 END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(s.company_id,s.source_message_id);
 SELECT * INTO m FROM public.ediel_messages WHERE id=s.source_message_id
  AND company_id=s.company_id AND environment=s.environment FOR SHARE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z02'
  OR s.message_code IS DISTINCT FROM 'Z02' OR s.raw_payload IS NULL
  OR s.raw_payload IS DISTINCT FROM m.raw_payload
  OR s.payload_hash IS DISTINCT FROM m.immutable_payload_hash
  OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  OR s.source_received_at IS NULL OR NOT isfinite(s.source_received_at)
  OR s.source_received_at IS DISTINCT FROM m.message_received_at
  OR m.customer_id IS NULL OR m.site_id IS NULL THEN RETURN NULL;END IF;

 SELECT * INTO site FROM public.customer_sites WHERE id=m.site_id
  AND company_id=s.company_id AND customer_id=m.customer_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO customer FROM public.customers WHERE id=m.customer_id AND company_id=s.company_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 expected_object:=coalesce(nullif(btrim(site.normalized_facility_id),''),nullif(btrim(site.facility_id),''));
 expected_identity:=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''));
 expected_qualifier:=CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1'
  WHEN nullif(btrim(customer.personal_number),'') IS NOT NULL THEN 'SE2' ELSE NULL END;
 IF expected_object IS NULL OR expected_identity IS NULL THEN RETURN NULL;END IF;
 source_wire:=gridex_received_sources.z02_core_wire_v1(s.raw_payload);
 IF source_wire IS NULL OR source_wire->>'code' IS DISTINCT FROM 'Z02' THEN RETURN NULL;END IF;
 SELECT x->'elements' INTO source_transport FROM jsonb_array_elements(
  gridex_received_sources.closure_wire_tokens_v2(s.raw_payload)) x WHERE x->>'tag'='UNB';
 SELECT count(*) INTO object_matches FROM jsonb_array_elements(source_wire->'objects') x
  WHERE x->>'objectId'=expected_object;
 IF object_matches<>1 THEN RETURN NULL;END IF;
 SELECT x INTO source_object FROM jsonb_array_elements(source_wire->'objects') x WHERE x->>'objectId'=expected_object;
 IF nullif(source_object->>'identityAgency','') IS NULL OR nullif(source_object->>'lineReference','') IS NULL
  OR (source_object->>'reason' IN ('Z22','Z23')) IS NOT TRUE THEN RETURN NULL;END IF;

 -- Select by the physical source correlation, not latest request or mutable
 -- sent_at/parsed_payload. Multiple matching requests are unavailable authority.
 FOR candidate_request IN SELECT r.* FROM public.customer_info_requests r
  WHERE r.company_id=s.company_id AND r.customer_id=m.customer_id AND r.site_id=m.site_id
   AND r.operation_id IS NOT NULL AND r.ediel_message_id IS NOT NULL FOR SHARE
 LOOP
  SELECT * INTO candidate FROM public.ediel_messages o WHERE o.id=candidate_request.ediel_message_id
   AND o.company_id=s.company_id AND o.environment=s.environment AND o.direction='outbound'
   AND o.message_standard='edifact' AND o.message_family='PRODAT' AND o.message_code='Z01'
   AND o.customer_id=m.customer_id AND o.site_id=m.site_id FOR SHARE;
  IF NOT FOUND OR candidate.raw_payload IS NULL OR candidate.immutable_rendered_at IS NULL
   OR NOT isfinite(candidate.immutable_rendered_at)
   OR candidate.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(candidate.raw_payload,'UTF8')),'hex')
   THEN CONTINUE;END IF;
  candidate_wire:=gridex_received_sources.z02_core_wire_v1(candidate.raw_payload);
  SELECT x->'elements' INTO candidate_transport FROM jsonb_array_elements(
   gridex_received_sources.closure_wire_tokens_v2(candidate.raw_payload)) x WHERE x->>'tag'='UNB';
  IF candidate_wire IS NULL OR candidate_wire->>'code' IS DISTINCT FROM 'Z01'
   OR source_wire->>'sender' IS DISTINCT FROM candidate_wire->>'receiver'
   OR source_wire->>'receiver' IS DISTINCT FROM candidate_wire->>'sender'
   OR nullif(source_wire->>'transportSender','') IS NULL OR nullif(source_wire->>'transportReceiver','') IS NULL
   OR source_wire->>'transportSender' IS DISTINCT FROM candidate_wire->>'transportReceiver'
   OR source_wire->>'transportReceiver' IS DISTINCT FROM candidate_wire->>'transportSender'
   OR source_transport->2 IS DISTINCT FROM candidate_transport->3
   OR source_transport->3 IS DISTINCT FROM candidate_transport->2 THEN CONTINUE;END IF;
  SELECT count(*) INTO object_matches FROM jsonb_array_elements(candidate_wire->'objects') x
   WHERE x->>'objectId'=expected_object;
  IF object_matches<>1 THEN CONTINUE;END IF;
  SELECT x INTO candidate_object FROM jsonb_array_elements(candidate_wire->'objects') x WHERE x->>'objectId'=expected_object;
  IF candidate_object->>'identityAgency' IS DISTINCT FROM source_object->>'identityAgency'
   OR candidate_object->>'lineReference' IS DISTINCT FROM source_object->>'lineReference'
   OR candidate_object->>'reason' IS DISTINCT FROM source_object->>'reason'
   OR candidate_object->>'customerId' IS DISTINCT FROM expected_identity
   OR candidate_object->>'customerQualifier' IS DISTINCT FROM expected_qualifier
   OR candidate_object->>'customerAgency' IS DISTINCT FROM '260'
   OR nullif(candidate_object->>'customerName','') IS NULL
   OR NOT EXISTS(SELECT FROM public.ediel_business_references br WHERE br.company_id=s.company_id
    AND br.source_message_id=candidate.id AND br.message_family='PRODAT' AND br.message_code='Z01'
    AND br.reference_type='RFF_LI' AND br.reference_value=source_object->>'lineReference') THEN CONTINUE;END IF;
  matches:=matches+1;request_id:=candidate_request.id;original_id:=candidate.id;
  original_wire:=candidate_wire;original_object:=candidate_object;
 END LOOP;
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT * INTO request FROM public.customer_info_requests WHERE id=request_id;
 SELECT * INTO original FROM public.ediel_messages WHERE id=original_id;
 PERFORM public.ediel_require_source_bytes_available_v1(s.company_id,original.id);
 IF request.grid_owner_id IS NOT NULL AND (
  request.grid_owner_id IS DISTINCT FROM site.grid_owner_id
  OR m.grid_owner_id IS NOT NULL AND m.grid_owner_id IS DISTINCT FROM request.grid_owner_id
  OR original.grid_owner_id IS NOT NULL AND original.grid_owner_id IS DISTINCT FROM request.grid_owner_id)
  THEN RETURN NULL;END IF;
 SELECT count(*) INTO matches FROM public.customer_operation_request_snapshots x
  WHERE x.company_id=s.company_id AND x.operation_id=request.operation_id AND x.customer_id=m.customer_id
   AND x.customer_site_id=m.site_id AND x.request_kind='customer_data_request'
   AND x.request_reference=request.id::text AND x.superseded_at IS NULL;
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT * INTO snapshot FROM public.customer_operation_request_snapshots x
  WHERE x.company_id=s.company_id AND x.operation_id=request.operation_id AND x.customer_id=m.customer_id
   AND x.customer_site_id=m.site_id AND x.request_kind='customer_data_request'
   AND x.request_reference=request.id::text AND x.superseded_at IS NULL FOR SHARE;
 address_hash:=coalesce(nullif(btrim(site.address_hash),''),lower(concat_ws('|',nullif(btrim(site.street),''),
  nullif(regexp_replace(coalesce(site.postal_code,''),'[^0-9]','','g'),''),nullif(btrim(site.city),''))));
 IF snapshot.site_address_hash IS DISTINCT FROM address_hash OR snapshot.grid_owner_id IS DISTINCT FROM site.grid_owner_id
  OR nullif(original_object->>'installationAddress','') IS NOT NULL
   AND btrim(original_object->>'installationAddress') IS DISTINCT FROM btrim(site.street) THEN RETURN NULL;END IF;

 -- Reuse the genuine private provider receipt reader after READ authorization.
 -- Its historical sender is not requalified against present-day SEND rights.
 receipt:=gridex_ediel_transport.accepted_source_basis_v1(original);
 IF receipt IS NULL OR receipt->>'status' IS DISTINCT FROM 'accepted_projection'
  OR receipt->>'lane' IS DISTINCT FROM 'generic_journal' THEN RETURN NULL;END IF;
 SELECT * INTO dispatch FROM gridex_ediel_transport.attempts a WHERE a.id=(receipt->>'attemptId')::uuid
  AND a.company_id=s.company_id AND a.environment=s.environment AND a.message_id=original.id
  AND a.classification='accepted' AND a.binding->>'originalHash'=original.immutable_payload_hash
  AND a.entered_at IS NOT NULL AND a.observed_at IS NOT NULL
  AND isfinite(a.entered_at) AND isfinite(a.observed_at)
  AND original.immutable_rendered_at<=a.entered_at AND a.entered_at<=a.observed_at
  AND a.observed_at<=s.source_received_at
  AND a.observed_at=(receipt->>'observedAt')::timestamptz FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;

 -- Incoming UD fields are intentionally absent from the authority predicate.
 -- The caller parses original C059 bytes and validates reply fields separately.
 RETURN jsonb_build_object('status','z02_address_source_basis','version',1,
  'companyId',s.company_id,'environment',s.environment,'sourceMessageId',m.id,
  'sourcePayloadHash',s.payload_hash,'sourceReceivedAt',s.source_received_at,'sourceRawPayload',s.raw_payload,
  'sourceMessage',to_jsonb(m),'sourceContext',s.received_context,
  'originalMessageId',original.id,'originalPayloadHash',original.immutable_payload_hash,
  'originalRenderedAt',original.immutable_rendered_at,'originalRawPayload',original.raw_payload,
  'originalMessage',to_jsonb(original),'sourceObject',source_object,'originalObject',original_object,
  'request',to_jsonb(request),'requestSnapshot',to_jsonb(snapshot),'customer',to_jsonb(customer),'site',to_jsonb(site),
  'acceptedTransport',to_jsonb(dispatch),'acceptedTransportReceipt',receipt);
END $$;

--
-- Name: z02_core_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.z02_core_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;
 result jsonb:='{}';objects jsonb:='[]';obj jsonb;key text;value text;characteristic text;line_index integer:=-1;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH')<>1
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='BGM')<>1 THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::integer LOOP
  e:=t->'elements';key:=NULL;value:=NULL;
  IF t->>'tag'='UNB' THEN
   IF result ? 'transportSender' OR jsonb_array_length(e->2)<>2 OR jsonb_array_length(e->3)<>2
    OR (e#>>'{2,1}' IN ('14','ZZ')) IS NOT TRUE OR (e#>>'{3,1}' IN ('14','ZZ')) IS NOT TRUE THEN RETURN NULL; END IF;
   result:=result||jsonb_build_object('transportSender',e#>>'{2,0}','transportReceiver',e#>>'{3,0}');
  ELSIF t->>'tag'='UNH' THEN result:=result||jsonb_build_object('messageReference',e#>>'{1,0}');
  ELSIF t->>'tag'='BGM' THEN result:=result||jsonb_build_object('code',e#>>'{1,0}');
  ELSIF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF result ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   result:=result||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   line_index:=line_index+1;characteristic:=NULL;
   obj:=jsonb_build_object('objectId',e#>>'{3,0}','identityAgency',e#>>'{3,3}','lineIndex',line_index,'lineNumber',e#>>'{1,0}','segmentIndex',(t->>'index')::integer);
  ELSIF obj IS NOT NULL AND t->>'tag' NOT IN ('UNT','UNZ') THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'lineReference' ELSE 'gridArea' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' AND characteristic='Z13' THEN key:='reason';value:=e#>>'{1,0}';characteristic:=NULL;
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN
    IF obj ? 'customerId' THEN RETURN NULL; END IF;
    obj:=obj||jsonb_build_object('customerId',e#>>'{2,0}','customerQualifier',e#>>'{2,1}','customerAgency',e#>>'{2,2}','customerName',e#>>'{4,0}');
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='IT' THEN
    IF obj ? 'installationAddress' THEN RETURN NULL; END IF;
    obj:=obj||jsonb_build_object('installationAddress',e#>>'{5,0}','installationPostcode',e#>>'{8,0}','installationCity',e#>>'{6,0}');
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
 IF (result->>'code' IN ('Z01','Z02')) IS NOT TRUE OR nullif(result->>'sender','') IS NULL OR nullif(result->>'receiver','') IS NULL
 OR jsonb_array_length(objects)=0 THEN RETURN NULL; END IF;
 RETURN result||jsonb_build_object('objects',objects);
END $$;

--
-- Name: z05_wire_structure_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.z05_wire_structure_v1(p_raw text, p_object jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE
 tokens jsonb:=gridex_received_sources.closure_wire_tokens_v1(p_raw); token jsonb; e jsonb;
 unb jsonb; unh jsonb; unt jsonb; unz jsonb; bgm jsonb; fr jsonb; receiver jsonb; zone jsonb;
 n integer; first_line integer; stop_index integer; chosen_index integer; next_line integer;
 line_index integer:=0; object_value jsonb; selected_object jsonb; identities jsonb:='[]'; identity_value jsonb;
 selected_date jsonb; selected_reason jsonb; selected_reference jsonb; common_end integer; reference_end integer;
 date_count integer:=0; reason_count integer:=0; reference_count integer:=0;
 reason text; minute text; market_time timestamp; utc_value timestamptz; tag_name text;
BEGIN
 IF tokens IS NULL OR jsonb_typeof(p_object) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 n:=jsonb_array_length(tokens);
 IF n<8 THEN RETURN NULL; END IF;
 FOREACH tag_name IN ARRAY ARRAY['UNB','UNH','UNT','UNZ','BGM'] LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'=tag_name)<>1 THEN RETURN NULL; END IF;
 END LOOP;
 unb:=tokens->0;unh:=tokens->1;unt:=tokens->(n-2);unz:=tokens->(n-1);
 SELECT t INTO bgm FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
 SELECT min((t->>'index')::integer) INTO first_line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
 IF first_line IS NULL OR unb->>'tag'<>'UNB' OR unh->>'tag'<>'UNH' OR unt->>'tag'<>'UNT' OR unz->>'tag'<>'UNZ'
 OR (bgm->>'index')::integer<=1 OR (bgm->>'index')::integer>=first_line
 OR unb#>>'{elements,1,1}' IS DISTINCT FROM '3' OR unh#>>'{elements,2,0}' IS DISTINCT FROM 'PRODAT'
 OR jsonb_array_length(unh#>'{elements,1}') IS DISTINCT FROM 1 OR nullif(unh#>>'{elements,1,0}','') IS NULL
 OR unt#>'{elements,2}' IS DISTINCT FROM unh#>'{elements,1}'
 OR unt#>'{elements,1}' IS DISTINCT FROM jsonb_build_array((n-2)::text)
 OR unz#>'{elements,1}' IS DISTINCT FROM '["1"]'::jsonb
 OR jsonb_array_length(unb#>'{elements,5}') IS DISTINCT FROM 1 OR nullif(unb#>>'{elements,5,0}','') IS NULL
 OR unz#>'{elements,2}' IS DISTINCT FROM unb#>'{elements,5}'
 OR bgm#>'{elements,1}' IS DISTINCT FROM '["Z05"]'::jsonb
 OR jsonb_array_length(bgm#>'{elements,2}') IS DISTINCT FROM 1 OR nullif(bgm#>>'{elements,2,0}','') IS NULL
 OR coalesce(bgm#>'{elements,3}','[""]'::jsonb) NOT IN ('["9"]'::jsonb,'[""]'::jsonb) THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='NAD' AND t#>'{elements,1}'='["FR"]'::jsonb)<>1
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='NAD' AND t#>'{elements,1}'='["DO"]'::jsonb)<>1
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='DTM' AND t#>>'{elements,1,0}'='ZZZ')<>1 THEN RETURN NULL; END IF;
 SELECT t->'elements' INTO fr FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='NAD' AND t#>'{elements,1}'='["FR"]'::jsonb;
 SELECT t->'elements' INTO receiver FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='NAD' AND t#>'{elements,1}'='["DO"]'::jsonb;
 SELECT t#>'{elements,1}' INTO zone FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::int<first_line AND t->>'tag'='DTM' AND t#>>'{elements,1,0}'='ZZZ';
 IF zone IS DISTINCT FROM '["ZZZ","1","805"]'::jsonb
 OR jsonb_array_length(fr->2) IS DISTINCT FROM 3 OR jsonb_array_length(receiver->2) IS DISTINCT FROM 3
 OR fr#>>'{2,1}' IS DISTINCT FROM '160' OR fr#>>'{2,2}' IS DISTINCT FROM 'SVK'
 OR receiver#>>'{2,1}' IS DISTINCT FROM '160' OR receiver#>>'{2,2}' IS DISTINCT FROM 'SVK'
 OR nullif(fr#>>'{2,0}','') IS NULL OR fr#>>'{2,0}'<>btrim(fr#>>'{2,0}')
 OR nullif(receiver#>>'{2,0}','') IS NULL OR receiver#>>'{2,0}'<>btrim(receiver#>>'{2,0}')
 OR jsonb_array_length(unb#>'{elements,2}') IS DISTINCT FROM 2 OR jsonb_array_length(unb#>'{elements,3}') IS DISTINCT FROM 2
 OR unb#>>'{elements,2,0}' IS DISTINCT FROM fr#>>'{2,0}'
 OR unb#>>'{elements,2,1}' NOT IN ('14','ZZ') OR unb#>>'{elements,3,1}' NOT IN ('14','ZZ')
 OR nullif(unb#>>'{elements,3,0}','') IS NULL OR unb#>>'{elements,3,0}'<>btrim(unb#>>'{elements,3,0}') THEN RETURN NULL; END IF;
 -- Enumerate and validate EVERY physical LIN before matching caller scope.
 -- No caller offset or object ID selects an alleged segment as authority.
 FOR token IN SELECT t FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' ORDER BY (t->>'index')::integer LOOP
  e:=token->'elements';stop_index:=(token->>'index')::integer;
  IF stop_index<=1 OR stop_index>=n-2 OR jsonb_array_length(e)<>4
  OR e->1 IS DISTINCT FROM jsonb_build_array((line_index+1)::text)
  OR jsonb_array_length(e->3) IS DISTINCT FROM 4 OR nullif(e#>>'{3,0}','') IS NULL
  OR e#>>'{3,3}' IS DISTINCT FROM '9' OR e#>>'{3,1}' IS DISTINCT FROM '' OR e#>>'{3,2}' IS DISTINCT FROM ''
  THEN RETURN NULL; END IF;
  identity_value:=jsonb_build_array(e#>>'{3,0}',e#>>'{3,3}');
  IF identities @> jsonb_build_array(identity_value) THEN RETURN NULL; END IF;
  identities:=identities||jsonb_build_array(identity_value);
  object_value:=jsonb_build_object('messageIndex',0,'messageReference',unh#>>'{elements,1,0}',
    'objectId',e#>>'{3,0}','identityAgency',e#>>'{3,3}','registers',jsonb_build_array(jsonb_build_object(
      'lineIndex',line_index,'lineNumber',e#>>'{1,0}','registerIndex',NULL,'registerPosition',1,'segmentIndex',stop_index)));
  IF object_value=p_object THEN selected_object:=object_value;chosen_index:=stop_index; END IF;
  line_index:=line_index+1;
 END LOOP;
 IF selected_object IS NULL THEN RETURN NULL; END IF;
 SELECT min((t->>'index')::integer) INTO next_line FROM jsonb_array_elements(tokens) t
 WHERE (t->>'index')::integer>chosen_index AND t->>'tag' IN ('LIN','UNT');
 SELECT coalesce(min((t->>'index')::integer),next_line) INTO common_end FROM jsonb_array_elements(tokens) t
 WHERE (t->>'index')::integer>chosen_index AND (t->>'index')::integer<next_line AND t->>'tag' IN ('RFF','NAD');
 SELECT coalesce(min((t->>'index')::integer),next_line) INTO reference_end FROM jsonb_array_elements(tokens) t
 WHERE (t->>'index')::integer>chosen_index AND (t->>'index')::integer<next_line AND t->>'tag'='NAD';
 FOR token IN SELECT t FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>chosen_index AND (t->>'index')::integer<next_line LOOP
  e:=token->'elements';stop_index:=(token->>'index')::integer;
  IF stop_index<common_end AND token->>'tag'='DTM' AND e#>>'{1,0}'='93' THEN
   date_count:=date_count+1;selected_date:=e->1;
  END IF;
  IF stop_index<common_end AND token->>'tag'='CCI' AND e#>'{2}'='["Z13"]'::jsonb THEN
   reason_count:=reason_count+1;
   IF stop_index+1>=common_end OR tokens->(stop_index+1)->>'tag'<>'CAV' THEN RETURN NULL; END IF;
   selected_reason:=tokens->(stop_index+1)#>'{elements,1}';
  END IF;
  IF stop_index<reference_end AND token->>'tag'='RFF' AND e#>>'{1,0}'='LI' THEN
   reference_count:=reference_count+1;selected_reference:=e->1;
  END IF;
 END LOOP;
 IF date_count<>1 OR reason_count<>1 OR reference_count>1 OR jsonb_array_length(selected_date) IS DISTINCT FROM 3
 OR selected_date->>2 IS DISTINCT FROM '203' OR jsonb_array_length(selected_reason) IS DISTINCT FROM 1
 OR (reference_count=1 AND (jsonb_array_length(selected_reference) IS DISTINCT FROM 2 OR nullif(selected_reference->>1,'') IS NULL)) THEN RETURN NULL; END IF;
 minute:=selected_date->>1;reason:=selected_reason->>0;
 IF minute IS NULL OR minute !~ '^[0-9]{12}$' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN NULL; END IF;
 market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);
 utc_value:=market_time AT TIME ZONE 'Etc/GMT-1';
 IF NOT isfinite(utc_value) THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('wire',jsonb_build_object('object',selected_object,'messageCode','Z05','reason',reason,
  'functionCode',nullif(bgm#>>'{elements,3,0}',''),'documentReference',bgm#>>'{elements,2,0}','caseReference',selected_reference->>1,
  'effectiveTo',jsonb_build_object('fieldNumber','211','marketMinute',minute,'utc',to_char(utc_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
  'legalSender',fr#>>'{2,0}','legalReceiver',receiver#>>'{2,0}',
  'transportSender',unb#>>'{elements,2,0}','transportReceiver',unb#>>'{elements,3,0}',
  'transportSenderQualifier',unb#>>'{elements,2,1}','transportReceiverQualifier',unb#>>'{elements,3,1}'),
  'syntax',unb#>'{elements,1}','messageType',unh#>'{elements,2}',
  'objectCount',line_index,'caseReferenceCount',reference_count);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN NULL;
END $_$;

--
-- Name: capture_actor_market_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_actor_market_v1(a uuid, m text, s text, rec jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF a IS NULL OR(m IN('EL','GAS')) IS NOT TRUE OR rec->>'market' IS DISTINCT FROM m OR nullif(rec->>'edielId','') IS NULL OR nullif(rec->>'countryCode','') IS NULL THEN RAISE EXCEPTION 'ediel_registry_market_source_required';END IF;
 INSERT INTO gridex_registry_import.market_records(actor_id,market,source_sha256,record_sha256,record) VALUES(a,m,s,encode(sha256(convert_to(rec::text,'UTF8')),'hex'),rec);
 INSERT INTO gridex_registry_import.market_current VALUES(a,m,s) ON CONFLICT(actor_id,market) DO UPDATE SET source_sha256=excluded.source_sha256;
END$$;

--
-- Name: capture_route_market_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_route_market_v1(rid uuid, a uuid, m text, s text, rec jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r public.platform_actor_routes%rowtype;BEGIN
 SELECT * INTO r FROM public.platform_actor_routes WHERE id=rid FOR SHARE;IF r.id IS NULL OR r.actor_id IS DISTINCT FROM a OR r.registry_market IS DISTINCT FROM m THEN RAISE EXCEPTION 'ediel_registry_route_market_source_required';END IF;
 INSERT INTO gridex_registry_import.route_market_sources VALUES(rid,a,m,s,encode(sha256(convert_to(rec::text,'UTF8')),'hex'),gridex_registry_import.route_tuple_v1(r));
 INSERT INTO gridex_registry_import.route_market_current VALUES(rid,s) ON CONFLICT(route_id) DO UPDATE SET source_sha256=excluded.source_sha256;
END$$;

--
-- Name: capture_route_version_v1(); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_route_version_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE version bigint;snapshot jsonb;
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(new)-ARRAY['updated_at','metadata']) IS NOT DISTINCT FROM (to_jsonb(old)-ARRAY['updated_at','metadata']) THEN RETURN new;END IF;
 IF TG_OP='UPDATE' AND (new.id IS DISTINCT FROM old.id OR new.actor_id IS DISTINCT FROM old.actor_id) THEN RAISE EXCEPTION 'ediel_registry_route_identity_immutable';END IF;
 snapshot:=to_jsonb(old);SELECT coalesce(max(revision),0)+1 INTO version FROM gridex_registry_import.route_versions WHERE route_id=old.id;
 INSERT INTO gridex_registry_import.route_versions(route_id,actor_id,revision,snapshot,snapshot_hash) VALUES(old.id,old.actor_id,version,snapshot,encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));
 IF TG_OP='DELETE' THEN RETURN old;END IF;RETURN new;
END$$;

--
-- Name: current_el_actor_source_v1(uuid); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.current_el_actor_source_v1(p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s text;rec gridex_registry_import.market_records%rowtype;n gridex_registry_import.normalized_batches%rowtype;b gridex_registry_import.batches%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 IF p_actor_id IS NULL THEN RAISE EXCEPTION 'ediel_registry_actual_legal_actor_required';END IF;
 SELECT source_sha256 INTO s FROM gridex_registry_import.market_current WHERE actor_id=p_actor_id AND market='EL' FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','actorId',p_actor_id,'reason','current_original_legal_actor_source_required');END IF;
 SELECT * INTO rec FROM gridex_registry_import.market_records WHERE actor_id=p_actor_id AND market='EL' AND source_sha256=s FOR SHARE;
 SELECT * INTO n FROM gridex_registry_import.normalized_batches WHERE source_sha256=s FOR SHARE;
 SELECT * INTO b FROM gridex_registry_import.batches WHERE source_sha256=s FOR SHARE;
 PERFORM 1 FROM public.platform_actor_identifiers i WHERE i.identifier_type='EdielId' AND i.identifier_value=rec.record->>'edielId' ORDER BY i.actor_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=p_actor_id AND status='active') OR rec.actor_id IS NULL OR n.source_sha256 IS NULL OR b.source_sha256 IS NULL OR rec.record->>'market' IS DISTINCT FROM 'EL'
  OR nullif(rec.record->>'name','') IS NULL OR nullif(rec.record->>'countryCode','') IS NULL OR (rec.record->>'edielId' ~ '^[0-9]{5}$') IS NOT TRUE
  OR rec.record_sha256 IS DISTINCT FROM encode(sha256(convert_to(rec.record::text,'UTF8')),'hex')
  OR b.created_at>clock_timestamp() OR b.source_sha256 IS DISTINCT FROM encode(sha256(b.source_bytes),'hex')
  OR b.normalized_sha256 IS DISTINCT FROM encode(sha256(convert_to(n.records::text,'UTF8')),'hex')
  OR(SELECT count(*) FROM jsonb_array_elements(n.records)item WHERE item=rec.record)<>1
  OR(SELECT count(*) FROM public.platform_actor_identifiers i WHERE i.identifier_type='EdielId' AND i.identifier_value=rec.record->>'edielId' AND i.actor_id=p_actor_id AND(i.valid_from IS NULL OR i.valid_from<=clock_timestamp()::date) AND(i.valid_to IS NULL OR clock_timestamp()::date<=i.valid_to))<>1 THEN
  RETURN jsonb_build_object('status','held','actorId',p_actor_id,'reason','current_original_legal_actor_source_required');END IF;
 RETURN jsonb_build_object('status','source_qualified','actorId',p_actor_id,'market','EL','legalEdielId',rec.record->>'edielId','legalName',rec.record->>'name','countryCode',rec.record->>'countryCode','roles',rec.record->'roles','sourceSha256',s,'sourceRecordSha256',rec.record_sha256);
END$_$;

--
-- Name: current_el_tenant_actor_source_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.current_el_tenant_actor_source_v1(c uuid, legal_actor uuid, env text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE legal_id text;n int;source_actor uuid;q jsonb;identifiers jsonb;roles jsonb;profiles jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF c IS NULL OR legal_actor IS NULL OR(env IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_owned_tenant_supplier_required';END IF;
 PERFORM id FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 PERFORM id FROM public.tenant_actor_roles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 PERFORM id FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 SELECT count(DISTINCT(actor_id,btrim(identifier_value))),min(btrim(identifier_value)),jsonb_agg(to_jsonb(i) ORDER BY id) INTO n,legal_id,identifiers FROM public.tenant_actor_identifiers i WHERE company_id=c AND environment=env AND actor_id=legal_actor AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 IF n<>1 OR legal_id!~'^[0-9]{5}$' OR(SELECT count(DISTINCT(actor_id,btrim(identifier_value)))FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to))<>1 THEN RAISE EXCEPTION 'ediel_registry_unique_current_tenant_legal_identifier_required';END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO roles FROM public.tenant_actor_roles r WHERE company_id=c AND environment=env AND actor_id=legal_actor AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 SELECT jsonb_agg(to_jsonb(p) ORDER BY id) INTO profiles FROM public.tenant_ediel_profiles p WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 IF roles IS NULL OR profiles IS NULL THEN RAISE EXCEPTION 'ediel_registry_current_tenant_el_supplier_required';END IF;
 PERFORM id FROM public.platform_actor_identifiers WHERE identifier_type='EdielId' AND identifier_value=legal_id ORDER BY id FOR SHARE;
 SELECT count(DISTINCT actor_id),min(actor_id::text)::uuid INTO n,source_actor FROM public.platform_actor_identifiers WHERE identifier_type='EdielId' AND identifier_value=legal_id AND(valid_from IS NULL OR valid_from<=clock_timestamp()::date) AND(valid_to IS NULL OR clock_timestamp()::date<=valid_to);
 IF n<>1 THEN RETURN jsonb_build_object('status','held','reason','current_original_legal_actor_source_required','companyId',c,'environment',env,'legalActorId',legal_actor);END IF;
 q:=gridex_registry_import.current_el_actor_source_v1(source_actor);
 IF NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=source_actor AND status='active') OR NOT EXISTS(SELECT FROM public.platform_actor_roles WHERE actor_id=source_actor AND actor_role='electricity_supplier' AND is_active) OR q->>'status' IS DISTINCT FROM 'source_qualified' OR q->>'legalEdielId' IS DISTINCT FROM legal_id OR q->>'market' IS DISTINCT FROM 'EL' OR(q->'roles' @> '["electricity_supplier"]'::jsonb) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','reason','current_original_legal_actor_source_required','companyId',c,'environment',env,'legalActorId',legal_actor,'sourceActorId',source_actor);END IF;
 RETURN q||jsonb_build_object('companyId',c,'environment',env,'legalActorId',legal_actor,'sourceActorId',source_actor,'tenantIdentifierSource',identifiers,'tenantRoleSource',roles,'tenantProfileSource',profiles);
END$_$;

--
-- Name: dispatch_source_v1(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.dispatch_source_v1(c uuid, communication uuid, profile uuid, env text, family text, application text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p public.ediel_route_profiles%rowtype;r public.communication_routes%rowtype;profile_id text;communication_id text;registry_id uuid;q jsonb;profile_wire jsonb;subaddress text;source_family text;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 source_family:=CASE WHEN family='AI_LIST' THEN 'AI' ELSE family END;
 SELECT * INTO p FROM public.ediel_route_profiles WHERE id=profile AND company_id=c FOR SHARE;
 SELECT * INTO r FROM public.communication_routes WHERE id=communication AND company_id=c FOR SHARE;
 IF p.id IS NULL OR r.id IS NULL OR p.communication_route_id IS DISTINCT FROM r.id OR(env IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_owned_route_profile_required';END IF;
 profile_id:=nullif(p.metadata->>'platform_actor_route_id','');communication_id:=nullif(r.auth_config->>'platform_actor_route_id','');
 IF profile_id IS NOT NULL AND communication_id IS NOT NULL AND profile_id IS DISTINCT FROM communication_id THEN RAISE EXCEPTION 'ediel_registry_route_mapping_conflict';END IF;
 IF coalesce(profile_id,communication_id) IS NULL THEN
  IF p.metadata->>'materialized_from'='platform_actor_routes' OR r.auth_config->>'materialized_from'='platform_actor_routes' THEN RAISE EXCEPTION 'ediel_registry_route_mapping_required';END IF;RETURN NULL;
 END IF;
 registry_id:=coalesce(profile_id,communication_id)::uuid;q:=gridex_registry_import.require_el_route_v1(registry_id);profile_wire:=to_jsonb(p);
 IF nullif(profile_wire->>'receiver_subaddress','') IS NOT NULL AND nullif(profile_wire->>'receiver_sub_address','') IS NOT NULL AND profile_wire->>'receiver_subaddress' IS DISTINCT FROM profile_wire->>'receiver_sub_address' THEN RAISE EXCEPTION 'ediel_registry_route_dispatch_source_mismatch';END IF;
 subaddress:=coalesce(nullif(profile_wire->>'receiver_subaddress',''),nullif(profile_wire->>'receiver_sub_address',''));
 -- Registry APP absence remains absent. The SAME canonical policy owns the
 -- protocol APP; actual saved/profile APP is still bound below. A declared
 -- registry APP can never be widened to a different selected application.
 IF q#>>'{wire,environment}' IS DISTINCT FROM env OR q#>>'{wire,family}' IS DISTINCT FROM source_family OR profile_wire->>'environment' IS DISTINCT FROM env
  OR profile_wire->>'message_family' IS DISTINCT FROM family OR lower(q#>>'{wire,transport}') IS DISTINCT FROM 'smtp'
  OR profile_wire->>'transport_type' IS DISTINCT FROM 'smtp' OR to_jsonb(r)->>'route_type' IS DISTINCT FROM 'ediel_partner'
  OR(env='production' AND to_jsonb(r)->>'environment_type' IS DISTINCT FROM 'production') OR(env='test' AND(to_jsonb(r)->>'environment_type' IN('tgt_test','agt_test','bilateral_test')) IS NOT TRUE)
  OR profile_wire->>'receiver_ediel_id' IS DISTINCT FROM q#>>'{wire,interchangePartyId}' OR subaddress IS DISTINCT FROM nullif(q#>>'{wire,subaddress}','')
  OR nullif(profile_wire->>'application_reference','') IS DISTINCT FROM nullif(application,'')
  OR(q#>>'{wire,applicationReference}' IS NOT NULL AND q#>>'{wire,applicationReference}' IS DISTINCT FROM application)
  OR r.target_email IS DISTINCT FROM q#>>'{wire,address}' THEN RAISE EXCEPTION 'ediel_registry_route_dispatch_source_mismatch';END IF;
 IF family='AI_LIST' AND(application IS NOT NULL OR q#>>'{wire,applicationReference}' IS NOT NULL OR nullif(q->>'legalName','') IS NULL
  OR profile_wire->>'is_active' IS DISTINCT FROM 'true' OR profile_wire->>'is_enabled' IS DISTINCT FROM 'true'
  OR to_jsonb(r)->>'is_active' IS DISTINCT FROM 'true' OR profile_wire->>'message_standard' IS DISTINCT FROM 'ai_list'
  OR profile_wire->>'payload_format' IS DISTINCT FROM 'raw') THEN RAISE EXCEPTION 'ediel_registry_ai_list_dispatch_source_required';END IF;
 RETURN q||jsonb_build_object('companyId',c,'communicationRouteId',r.id,'routeProfileId',p.id,'selectedApplicationReference',application)
  ||CASE WHEN family='AI_LIST' THEN jsonb_build_object('canonicalFamily','AI') ELSE '{}'::jsonb END;
END$$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION 'ediel_registry_source_batch_immutable';END $$;

--
-- Name: lock_import_graph_v1(); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.lock_import_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 LOCK TABLE auth.users,public.user_profiles,public.companies,public.company_memberships,public.admin_users,
  public.user_roles,public.roles,public.role_permissions,public.permissions,public.user_permissions,public.user_permission_overrides,
  public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles,public.tenant_counterparty_relations,public.platform_actor_identifiers,
  public.ediel_service_assignments,public.ediel_service_evidence,public.ediel_data_access_grants,public.ediel_assignment_permission_links,
  public.metering_permissions,public.metering_permission_sites,public.ediel_ack_transaction_results,public.meter_reading_series,
  gridex_utilts_binding.receipts,gridex_utilts_binding.contracts,gridex_service_administration.scope_versions,
  gridex_received_sources.permission_transitions,gridex_received_sources.validation_assessments IN SHARE ROW EXCLUSIVE MODE;
END $$;

--
-- Name: require_el_route_v1(uuid); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.require_el_route_v1(rid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;BEGIN
 q:=gridex_registry_import.route_source_v1(rid);
 IF q->>'status' IS DISTINCT FROM 'source_qualified' OR q->>'market' IS DISTINCT FROM 'EL' THEN RAISE EXCEPTION 'ediel_registry_current_el_route_source_required';END IF;RETURN q;
END$$;

--
-- Name: require_message_market_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.require_message_market_v1(c uuid, mid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;q jsonb;tokens jsonb;unb jsonb;unh jsonb;receiver_legal jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'ediel_registry_message_scope_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR(m.message_family IN('PRODAT','UTILTS','AI','AI_LIST')) IS NOT TRUE OR m.message_code='ERR' THEN RETURN NULL;END IF;
 q:=gridex_registry_import.dispatch_source_v1(c,m.communication_route_id,m.route_profile_id,m.environment,m.message_family,m.application_reference);
 IF q IS NULL THEN RETURN NULL;END IF;
 IF m.receiver_ediel_id IS DISTINCT FROM q#>>'{wire,interchangePartyId}' OR nullif(m.receiver_sub_address,'') IS DISTINCT FROM nullif(q#>>'{wire,subaddress}','') OR m.receiver_email IS DISTINCT FROM q#>>'{wire,address}' OR m.transport_type IS DISTINCT FROM 'smtp' THEN RAISE EXCEPTION 'ediel_registry_message_dispatch_source_mismatch';END IF;
 IF m.message_family IN('PRODAT','UTILTS') THEN
  tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
  IF(SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB')<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1 THEN RAISE EXCEPTION 'ediel_registry_message_wire_source_required';END IF;
  SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';
  IF unb#>>'{elements,3,0}' IS DISTINCT FROM q#>>'{wire,interchangePartyId}' OR nullif(unb#>>'{elements,3,2}','') IS DISTINCT FROM nullif(q#>>'{wire,subaddress}','') OR nullif(unb#>>'{elements,7,0}','') IS DISTINCT FROM nullif(m.application_reference,'') OR unh#>>'{elements,2,0}' IS DISTINCT FROM m.message_family THEN RAISE EXCEPTION 'ediel_registry_message_wire_source_mismatch';END IF;
  -- Legal receiver is the original actor PartyId, independently of technical
  -- UNB interchange identity. Only own common-header NAD is consumed.
  IF(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'=CASE m.message_family WHEN 'PRODAT' THEN 'DO' ELSE 'MR' END AND (t->>'index')::int < coalesce((SELECT min((u->>'index')::int) FROM jsonb_array_elements(tokens)u WHERE u->>'tag'=CASE m.message_family WHEN 'PRODAT' THEN 'LIN' ELSE 'IDE' END),2147483647))<>1 THEN RAISE EXCEPTION 'ediel_registry_message_legal_receiver_required';END IF;
  SELECT t INTO receiver_legal FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'=CASE m.message_family WHEN 'PRODAT' THEN 'DO' ELSE 'MR' END AND (t->>'index')::int < coalesce((SELECT min((u->>'index')::int) FROM jsonb_array_elements(tokens)u WHERE u->>'tag'=CASE m.message_family WHEN 'PRODAT' THEN 'LIN' ELSE 'IDE' END),2147483647);
  IF receiver_legal#>>'{elements,2,0}' IS DISTINCT FROM q->>'legalEdielId' THEN RAISE EXCEPTION 'ediel_registry_message_legal_receiver_source_mismatch';END IF;
 END IF;RETURN q;
END$$;

--
-- Name: route_source_v1(uuid); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.route_source_v1(rid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r public.platform_actor_routes%rowtype;own gridex_registry_import.route_market_sources%rowtype;rec gridex_registry_import.market_records%rowtype;n gridex_registry_import.normalized_batches%rowtype;b gridex_registry_import.batches%rowtype;s text;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 SELECT * INTO r FROM public.platform_actor_routes WHERE id=rid FOR SHARE;
 IF r.id IS NULL OR r.registry_market IS NULL OR(r.valid_from IS NOT NULL AND r.valid_from>clock_timestamp()::date) OR(r.valid_to IS NOT NULL AND r.valid_to<clock_timestamp()::date) THEN RETURN jsonb_build_object('status','held','routeId',rid,'reason','source_declared_registry_market_required');END IF;
 SELECT source_sha256 INTO s FROM gridex_registry_import.route_market_current WHERE route_id=r.id FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','routeId',rid,'reason','prospective_route_market_basis_required');END IF;
 SELECT * INTO own FROM gridex_registry_import.route_market_sources WHERE route_id=r.id AND source_sha256=s FOR SHARE;
 SELECT * INTO rec FROM gridex_registry_import.market_records WHERE actor_id=own.actor_id AND market=own.market AND source_sha256=own.source_sha256 FOR SHARE;
 SELECT * INTO n FROM gridex_registry_import.normalized_batches WHERE source_sha256=own.source_sha256 FOR SHARE;
 SELECT * INTO b FROM gridex_registry_import.batches WHERE source_sha256=own.source_sha256 FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=r.actor_id AND status='active') OR own.route_id IS NULL OR rec.actor_id IS NULL OR b.source_sha256 IS NULL OR n.source_sha256 IS NULL OR own.actor_id IS DISTINCT FROM r.actor_id OR own.market IS DISTINCT FROM r.registry_market
  OR own.wire_tuple IS DISTINCT FROM gridex_registry_import.route_tuple_v1(r) OR rec.record_sha256 IS DISTINCT FROM own.record_sha256
  OR (rec.record->>'edielId' ~ '^[0-9]{5}$') IS NOT TRUE OR rec.record->>'market' IS DISTINCT FROM own.market OR nullif(rec.record->>'countryCode','') IS NULL OR rec.record->>'edielId' IS DISTINCT FROM r.party_id
  OR b.created_at>clock_timestamp() OR b.source_sha256 IS DISTINCT FROM encode(sha256(b.source_bytes),'hex') OR b.normalized_sha256 IS DISTINCT FROM encode(sha256(convert_to(n.records::text,'UTF8')),'hex')
  OR(SELECT count(*) FROM jsonb_array_elements(n.records) item WHERE item=rec.record)<>1
  OR NOT EXISTS(SELECT FROM gridex_registry_import.market_current p WHERE p.actor_id=own.actor_id AND p.market=own.market AND p.source_sha256=own.source_sha256)
  OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=own.actor_id AND i.identifier_type='EdielId' AND i.identifier_value=rec.record->>'edielId' AND(i.valid_from IS NULL OR i.valid_from<=clock_timestamp()::date) AND(i.valid_to IS NULL OR clock_timestamp()::date<=i.valid_to)) THEN
  RETURN jsonb_build_object('status','held','routeId',rid,'reason','current_exact_registry_market_source_required');END IF;
 RETURN jsonb_build_object('status','source_qualified','routeId',r.id,'actorId',r.actor_id,'market',own.market,'sourceSha256',own.source_sha256,'sourceRecordSha256',own.record_sha256,'countryCode',rec.record->>'countryCode','legalName',rec.record->>'name','roles',rec.record->'roles','legalEdielId',rec.record->>'edielId','wire',own.wire_tuple);
END$_$;

--
-- Name: platform_actor_routes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_actor_routes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid NOT NULL,
    message_family text NOT NULL,
    application_reference text,
    environment text DEFAULT 'production'::text NOT NULL,
    subaddress text,
    communication_type text,
    communication_address text,
    edi_charset text,
    edi_syntax text,
    party_id text,
    party_id_qualifier text,
    party_id_responsible text,
    interchange_party_id text,
    interchange_id_qualifier text,
    requires_poa boolean DEFAULT true NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    auto_send_allowed boolean DEFAULT false NOT NULL,
    status text DEFAULT 'needs_review'::text NOT NULL,
    valid_from date,
    valid_to date,
    source text DEFAULT 'companies_xml'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    registry_market text,
    CONSTRAINT platform_actor_routes_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT platform_actor_routes_registry_market_check CHECK ((registry_market = ANY (ARRAY['EL'::text, 'GAS'::text]))),
    CONSTRAINT platform_actor_routes_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'needs_review'::text, 'blocked'::text])))
);

--
-- Name: route_tuple_v1(public.platform_actor_routes); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.route_tuple_v1(r public.platform_actor_routes) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT jsonb_build_object('actorId',r.actor_id,'market',r.registry_market,'family',r.message_family,'environment',r.environment,'subaddress',r.subaddress,'applicationReference',r.application_reference,'address',r.communication_address,'transport',r.communication_type,'partyId',r.party_id,'interchangePartyId',r.interchange_party_id,'partyQualifier',r.party_id_qualifier,'partyResponsible',r.party_id_responsible,'interchangeQualifier',r.interchange_id_qualifier,'charset',r.edi_charset,'syntax',r.edi_syntax) $$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.actor_v1(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 RETURN mode IN('archive','read','review') AND EXISTS(SELECT FROM public.companies WHERE id=c AND status='active')
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now()))
 AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND public.gridex_actor_has_company_permission(actor,c,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND public.gridex_actor_has_company_permission(actor,c,'contracts.read') IS TRUE
 AND public.gridex_actor_has_company_permission(actor,c,CASE mode WHEN 'read' THEN 'metering.read' ELSE 'metering.write' END) IS TRUE
 AND (mode<>'review' OR public.gridex_actor_has_company_permission(actor,c,'ediel.regulated_supply.review') IS TRUE AND (
 EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key='ediel.regulated_supply.review')
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key='ediel.regulated_supply.review')));
END$$;

--
-- Name: ground_current_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.ground_current_v1(ground uuid, company uuid, point uuid, effective timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE o gridex_regulated_supply.origins%rowtype;a gridex_regulated_supply.artifacts%rowtype;r gridex_regulated_supply.reviews%rowtype;g gridex_received_sources.regulated_supply_ground_versions%rowtype;scope jsonb;
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 SELECT * INTO o FROM gridex_regulated_supply.origins WHERE ground_id=ground AND company_id=company;
 SELECT * INTO a FROM gridex_regulated_supply.artifacts WHERE id=o.artifact_id AND company_id=company;SELECT * INTO r FROM gridex_regulated_supply.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=company;
 SELECT * INTO g FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ground AND company_id=company;
 IF o.ground_id IS NULL OR a.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_regulated_supply.actor_v1(company,r.reviewer_user_id,'review') IS NOT TRUE
 OR g.revoked_at IS NOT NULL OR (to_jsonb(g)-'revoked_at') IS DISTINCT FROM o.ground_binding OR g.approved_by IS DISTINCT FROM r.reviewer_user_id OR g.approved_at IS DISTINCT FROM r.reviewed_at
 OR a.scope->>'meteringPointId' IS DISTINCT FROM point::text OR (a.scope->>'startAt')::timestamptz IS DISTINCT FROM effective OR gridex_regulated_supply.receipt_current_v1(a) IS NOT TRUE THEN RETURN false;END IF;
 scope:=gridex_regulated_supply.scope_v1(company,a.selector);RETURN scope IS NOT NULL AND scope=a.scope;
END$$;

--
-- Name: ground_wire_current_v1(uuid, uuid, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.ground_wire_current_v1(ground uuid, company uuid, point uuid, effective timestamp with time zone, own jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_regulated_supply.artifacts%rowtype;BEGIN
 IF gridex_regulated_supply.ground_current_v1(ground,company,point,effective) IS NOT TRUE THEN RETURN false;END IF;
 SELECT archive.* INTO a FROM gridex_regulated_supply.origins o JOIN gridex_regulated_supply.artifacts archive ON archive.id=o.artifact_id AND archive.company_id=o.company_id WHERE o.ground_id=ground AND o.company_id=company;
 RETURN (a.scope->>'point'=own->>'point' AND a.scope->>'identityAgency'=own->>'identityAgency' AND a.scope->>'customerIdentity'=own->>'customerIdentity' AND a.scope->>'gridArea'=own->>'gridArea'
 AND a.scope->>'kind'=CASE own->>'reason' WHEN 'Z26' THEN 'assigned_supply' WHEN 'Z70' THEN 'production_receipt_obligation' END
 AND (a.scope->>'kind'<>'production_receipt_obligation' OR a.scope->>'consumptionPoint'=own->>'consumptionPoint')) IS TRUE;
END$$;

--
-- Name: lock_graph_v1(); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.lock_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 -- Write-compatible serialization precedes every source/market row. Readers
 -- use the same order; no SHARE-to-writer upgrade or grant-revocation race.
 LOCK TABLE gridex_regulated_supply.artifacts,gridex_regulated_supply.issuer_keys,gridex_regulated_supply.issuer_representations,
 gridex_regulated_supply.issuer_revocations,gridex_regulated_supply.reviews,gridex_regulated_supply.origins,
 gridex_received_sources.regulated_supply_ground_versions IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.customer_contracts,public.customer_contract_documents,public.customers,public.customer_sites,public.metering_points,public.grid_owners,public.tenant_bilateral_agreements IN SHARE MODE;
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_regulated_supply; Owner: -
--

CREATE TABLE gridex_regulated_supply.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    selector jsonb NOT NULL,
    scope jsonb NOT NULL,
    scope_hash text NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    mime_type text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    receipt_hash text NOT NULL,
    submitted_by uuid NOT NULL,
    archived_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_mime_type_check CHECK ((mime_type = ANY (ARRAY['application/pdf'::text, 'text/plain'::text, 'application/json'::text]))),
    CONSTRAINT artifacts_receipt_hash_check CHECK ((receipt_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_scope_hash_check CHECK ((scope_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_regulated_supply.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_regulated_supply.artifacts); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.receipt_current_v1(a gridex_regulated_supply.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE k gridex_regulated_supply.issuer_keys%rowtype;r gridex_regulated_supply.issuer_representations%rowtype;p jsonb;raw bytea;issued timestamptz;expires timestamptz;receipt jsonb:=a.issuer_receipt;
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 IF receipt IS NULL OR jsonb_typeof(receipt) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(receipt) key WHERE key NOT IN('keyId','representationId','payloadBase64','signatureHex')) OR coalesce(receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 65536
 OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.scope_hash IS DISTINCT FROM encode(sha256(convert_to(a.scope::text,'UTF8')),'hex') THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_regulated_supply.issuer_keys WHERE id=(receipt->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment;
 SELECT * INTO r FROM gridex_regulated_supply.issuer_representations WHERE id=(receipt->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment
 AND legal_actor_id::text=a.scope->>'legalActorId' AND dso_actor_id::text=a.scope->>'dsoActorId' AND grid_area_code=a.scope->>'gridArea' AND permitted_kind=a.scope->>'kind' AND bilateral_agreement_id::text=a.scope->>'bilateralAgreementId';
 IF k.id IS NULL OR r.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<r.valid_from OR now()>=r.valid_to OR EXISTS(SELECT FROM gridex_regulated_supply.issuer_revocations v WHERE v.target_kind='key' AND v.target_id=k.id OR v.target_kind='representation' AND v.target_id=r.id) THEN RETURN false;END IF;
 raw:=decode(receipt->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(receipt->>'signatureHex','hex')) THEN RETURN false;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 RETURN (p->>'format'='ediel_regulated_supply_ground_receipt_v1' AND p->>'issuerCode'=k.issuer_code AND nullif(p->>'receiptId','') IS NOT NULL AND p->>'companyId'=a.company_id::text AND p->>'environment'=a.environment AND p->'scope'=a.scope
 AND p->>'sourceHash'=a.source_hash AND p->>'sourceReference'=a.source_reference AND p->>'sourceVersion'=a.source_version AND nullif(p->>'legalDecisionReference','') IS NOT NULL AND length(p->>'legalDecisionReference')<=2000
 AND isfinite(issued) AND isfinite(expires) AND issued<=now() AND expires>greatest(now(),(a.scope->>'startAt')::timestamptz) AND (a.scope->>'startAt')::timestamptz>=r.valid_from AND issued>=greatest(k.valid_from,r.valid_from) AND expires<=least(k.valid_to,r.valid_to)) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END$_$;

--
-- Name: scope_v1(uuid, jsonb); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.scope_v1(c uuid, selector jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE contract public.customer_contracts%rowtype;customer public.customers%rowtype;point public.metering_points%rowtype;site public.customer_sites%rowtype;agreement public.tenant_bilateral_agreements%rowtype;doc public.customer_contract_documents%rowtype;
 consumption public.customer_supply_periods%rowtype;consumption_point public.metering_points%rowtype;env text:=selector->>'environment';kind text:=selector->>'kind';at timestamptz;ids uuid[];legal uuid;dso uuid;sender text;registry jsonb;sig text;supply jsonb;legal_binding jsonb;
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();
 IF jsonb_typeof(selector) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(selector) k WHERE k NOT IN('environment','kind','contractId','meteringPointId','identityAgency','bilateralAgreementId','startAt','consumptionSupplyPeriodId')) OR (selector->>'identityAgency' IN('9','89')) IS NOT TRUE OR (env IN('test','production')) IS NOT TRUE OR (kind IN('assigned_supply','production_receipt_obligation')) IS NOT TRUE THEN RETURN NULL;END IF;
 at:=(selector->>'startAt')::timestamptz;IF NOT isfinite(at) OR extract(second FROM at)<>0 THEN RETURN NULL;END IF;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=(selector->>'contractId')::uuid AND company_id=c FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=(selector->>'meteringPointId')::uuid AND company_id=c FOR SHARE;
 SELECT * INTO customer FROM public.customers WHERE id=point.customer_id AND company_id=c FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(point.customer_site_id,point.site_id) AND company_id=c AND customer_id=customer.id FOR SHARE;
 IF contract.id IS NULL OR point.id IS NULL OR customer.id IS NULL OR site.id IS NULL OR contract.customer_id IS DISTINCT FROM customer.id OR contract.metering_point_id IS DISTINCT FROM point.id OR contract.status NOT IN('signed','active')
 OR contract.signed_at IS NULL OR contract.signed_version IS DISTINCT FROM contract.contract_version OR nullif(point.ediel_metering_point_id,'') IS NULL OR nullif(point.grid_area_code,'') IS NULL OR nullif(point.grid_owner_ediel_id,'') IS NULL
 OR NOT EXISTS(SELECT FROM public.grid_owners WHERE id=site.grid_owner_id AND company_id=c AND ediel_id=point.grid_owner_ediel_id AND environment=env AND is_active) THEN RETURN NULL;END IF;
 IF (SELECT count(*) FROM public.metering_points owned WHERE owned.company_id=c AND owned.ediel_metering_point_id=point.ediel_metering_point_id)<>1 OR (SELECT count(*) FROM public.customer_contracts owned WHERE owned.company_id=c AND owned.customer_id=customer.id AND owned.metering_point_id=point.id AND owned.status IN('signed','active') AND owned.signed_version=owned.contract_version)<>1 THEN RETURN NULL;END IF;
 sig:=encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex');
 SELECT * INTO doc FROM public.customer_contract_documents WHERE company_id=c AND customer_contract_id=contract.id AND document_type='signed_contract_pdf' AND document_sha256=contract.document_sha256 AND verified_at IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
 IF doc.id IS NULL OR contract.signature_snapshot_sha256 IS DISTINCT FROM sig OR contract.signature_snapshot->>'company_id' IS DISTINCT FROM c::text OR contract.signature_snapshot->>'customer_id' IS DISTINCT FROM customer.id::text OR contract.signature_snapshot->>'contract_id' IS DISTINCT FROM contract.id::text THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=c AND i.environment=env AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to) AND r.role_code='electricity_supplier' AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to)) THEN RETURN NULL;END IF;legal:=ids[1];
 SELECT identifier_value INTO sender FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND actor_id=legal AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to) ORDER BY id LIMIT 1;
 IF (SELECT count(DISTINCT identifier_value) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND actor_id=legal AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to))<>1 THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT actor_id) INTO ids FROM public.platform_actor_identifiers WHERE lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=point.grid_owner_ediel_id AND is_verified AND (valid_from IS NULL OR valid_from<=(now() AT TIME ZONE 'Etc/GMT-1')::date) AND (valid_to IS NULL OR (now() AT TIME ZONE 'Etc/GMT-1')::date<=valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;dso:=ids[1];
 SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.id),'[]') INTO registry FROM public.platform_actor_identifiers i WHERE actor_id=dso AND lower(identifier_type) IN('edielid','ediel_id') AND identifier_value=point.grid_owner_ediel_id AND is_verified AND (valid_from IS NULL OR valid_from<=(now() AT TIME ZONE 'Etc/GMT-1')::date) AND (valid_to IS NULL OR (now() AT TIME ZONE 'Etc/GMT-1')::date<=valid_to);
 SELECT * INTO agreement FROM public.tenant_bilateral_agreements WHERE id=(selector->>'bilateralAgreementId')::uuid AND company_id=c AND environment=env AND counterparty_actor_id=dso AND is_enabled AND valid_from<=at AND (valid_to IS NULL OR at<valid_to) FOR SHARE;
 IF agreement.id IS NULL OR agreement.capability_code IS DISTINCT FROM (CASE kind WHEN 'assigned_supply' THEN 'PRODAT:Z04:A' ELSE 'PRODAT:Z04:D' END) OR nullif(agreement.source_reference,'') IS NULL THEN RETURN NULL;END IF;
 IF kind='production_receipt_obligation' THEN
  SELECT * INTO consumption FROM public.customer_supply_periods WHERE id=(selector->>'consumptionSupplyPeriodId')::uuid AND company_id=c AND customer_id=customer.id FOR SHARE;
  SELECT * INTO consumption_point FROM public.metering_points WHERE id=consumption.metering_point_id AND company_id=c FOR SHARE;
  supply:=gridex_received_sources.supply_period_source_basis_v1(c,consumption.id,at,at+interval '1 minute');
  IF point.product_direction IS DISTINCT FROM 'production' OR consumption_point.product_direction IS DISTINCT FROM 'consumption' OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM customer.id::text OR nullif(consumption_point.ediel_metering_point_id,'') IS NULL THEN RETURN NULL;END IF;
 ELSIF selector->>'consumptionSupplyPeriodId' IS NOT NULL OR point.product_direction IS DISTINCT FROM 'consumption' THEN RETURN NULL;END IF;
 SELECT jsonb_build_object('profile',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.tenant_ediel_profiles p WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to)),
 'identifiers',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.tenant_actor_identifiers i WHERE company_id=c AND environment=env AND actor_id=legal AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to)),
 'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.tenant_actor_roles r WHERE company_id=c AND environment=env AND actor_id=legal AND role_code='electricity_supplier' AND valid_from<=now() AND (valid_to IS NULL OR now()<valid_to))) INTO legal_binding;
 RETURN jsonb_build_object('companyId',c,'environment',env,'kind',kind,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'contractDocumentBinding',to_jsonb(doc),'signatureHash',sig,
 'customerId',customer.id,'customerIdentity',coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),'')),'customerHash',encode(sha256(convert_to(to_jsonb(customer)::text,'UTF8')),'hex'),
 'meteringPointId',point.id,'point',point.ediel_metering_point_id,'identityAgency',selector->>'identityAgency','pointHash',encode(sha256(convert_to(to_jsonb(point)::text,'UTF8')),'hex'),'siteHash',encode(sha256(convert_to(to_jsonb(site)::text,'UTF8')),'hex'),
 'legalActorId',legal,'legalSenderId',sender,'dsoActorId',dso,'legalReceiverId',point.grid_owner_ediel_id,'gridArea',point.grid_area_code,'registryBinding',registry,'legalBinding',legal_binding,
 'bilateralAgreementId',agreement.id,'agreementBinding',to_jsonb(agreement),'startAt',at,'consumptionSupplyPeriodId',consumption.id,'consumptionPoint',consumption_point.ediel_metering_point_id,'consumptionBasis',supply);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN NULL;
END$$;

--
-- Name: source_capability_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_regulated_supply; Owner: -
--

CREATE FUNCTION gridex_regulated_supply.source_capability_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE wire jsonb;legal jsonb;own jsonb;event_at timestamptz;ids uuid[];point uuid;objects jsonb:='[]';g gridex_received_sources.regulated_supply_ground_versions%rowtype;
BEGIN
 PERFORM gridex_regulated_supply.lock_graph_v1();IF m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.raw_payload IS NULL THEN RETURN NULL;END IF;PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
 IF NOT EXISTS(SELECT FROM gridex_received_sources.sources original WHERE original.source_message_id=m.id AND original.company_id=m.company_id AND original.environment=m.environment AND original.raw_payload=m.raw_payload AND original.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RETURN NULL;END IF;
 legal:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);IF EXISTS(SELECT FROM gridex_ediel_source_rules.receipts WHERE source_message_id=m.id) THEN PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
  ELSIF m.canonical_rule_pack_id IS NULL OR m.rule_profile_version_id IS NULL OR nullif(m.rule_pack_checksum,'') IS NULL THEN RETURN NULL;END IF;wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'code' IS DISTINCT FROM 'Z04' OR wire->>'receiver' IS DISTINCT FROM legal->>'legalEdielId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier' THEN RETURN NULL;END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
  IF (own->>'reason' IN('Z26','Z70')) IS NOT TRUE THEN RETURN NULL;END IF;event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  SELECT array_agg(mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_owner_ediel_id=wire->>'sender' AND mp.grid_area_code=own->>'gridArea';IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;point:=ids[1];
  SELECT array_agg(ground.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions ground WHERE ground.company_id=m.company_id AND ground.environment=m.environment AND ground.legal_actor_id::text=legal->>'legalActorId' AND ground.process=CASE own->>'reason' WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END AND ground.approved_at<=m.message_received_at AND gridex_regulated_supply.ground_wire_current_v1(ground.id,m.company_id,point,event_at,own) IS TRUE;
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO g FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1];
  objects:=objects||jsonb_build_array(jsonb_build_object('objectId',own->>'point','identityAgency',own->>'identityAgency','firstLineIndex',gridex_bilateral_prodat.first_line_index_v1(m.raw_payload,own),'lineItemReference',own->>'li','profileVersionId',g.id,'process',g.process,'sourceHash',g.source_sha256,'sourceGrammarHash',right(g.registry_version,64)));
 END LOOP;
 IF jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('version',1,'owner','immutable-regulated-supply-ground-v1','companyId',m.company_id,'environment',m.environment,'sourceMessageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'messageCode','Z04','subtype',CASE objects#>>'{0,process}' WHEN 'assigned_supply' THEN 'A' ELSE 'D' END,'objects',objects);
END$$;

--
-- Name: actor_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.actor_v1(c uuid, actor uuid, mode text, kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM auth.users WHERE id=actor FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 RETURN actor IS NOT NULL AND mode IN('archive','read','review') AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now()))
 AND gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'customers.read' ELSE 'customers.write' END) IS TRUE
 AND (kind='death' OR gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'contracts.read' ELSE 'contracts.write' END) IS TRUE)
 AND (mode<>'review' OR gridex_requested_changes.scoped_permission_v1(c,actor,'ediel.source.review') IS TRUE);
END$$;

--
-- Name: bind_message_v1(); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.bind_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE o gridex_requested_changes.origins%rowtype;BEGIN
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE intent_id=NEW.intent_id AND company_id=NEW.company_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 PERFORM gridex_requested_changes.require_message_v1(NEW,o.actor_user_id);
 IF o.message_id IS NOT NULL THEN RAISE EXCEPTION 'requested_change_message_already_bound' USING ERRCODE='23505';END IF;
 UPDATE gridex_requested_changes.origins SET message_id=NEW.id,payload_hash=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') WHERE event_id=o.event_id;RETURN NEW;END$$;

--
-- Name: capture_ai_customer_sources_v1(); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.capture_ai_customer_sources_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO NEW.source_ids FROM(SELECT DISTINCT id FROM(SELECT jsonb_array_elements_text(NEW.source_ids) id UNION ALL SELECT x->>'customerSourceMessageId' FROM jsonb_array_elements(NEW.row_sources) x WHERE x ? 'customerSourceMessageId') all_ids WHERE id IS NOT NULL) ids;
 RETURN NEW;
END$$;

--
-- Name: context_before_intake_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.context_before_intake_v1(c uuid, event uuid, actor uuid, permission text DEFAULT 'communication.write'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e gridex_requested_changes.events%rowtype;contract public.customer_contracts%rowtype;customer public.customers%rowtype;supply jsonb;initial public.ediel_messages%rowtype;tokens jsonb;party jsonb;mp public.metering_points%rowtype;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF permission NOT IN('communication.write','communication.send') OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(actor,c,permission) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_execution_actor_unqualified']);END IF;
 SELECT * INTO e FROM gridex_requested_changes.events WHERE id=event AND company_id=c FOR SHARE;
 IF NOT FOUND OR e.approved_at>now() OR EXISTS(SELECT FROM gridex_requested_changes.revocations WHERE event_id=e.id) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_customer_death_or_signed_metering_change_event']);END IF;
 supply:=gridex_received_sources.supply_period_source_basis_v1(c,e.supply_period_id,e.effective_at,e.effective_at+interval '1 minute');
 IF supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'sourceMessageId' IS DISTINCT FROM e.supply_source_message_id::text OR (supply->>'marketStateVersion')::bigint IS DISTINCT FROM e.supply_state_version OR supply->>'customerId' IS DISTINCT FROM e.customer_id::text OR supply->>'meteringPointId' IS DISTINCT FROM e.metering_point_id::text OR supply->>'legalActorId' IS DISTINCT FROM e.legal_actor_id::text OR supply->>'dsoEdielId' IS DISTINCT FROM e.legal_receiver_id
 OR (SELECT count(*) FROM jsonb_array_elements(supply->'sourceObjects') own WHERE own->>'point'=e.point_id AND own->>'identityAgency'=e.identity_agency)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_current_approved_physical_supply']);END IF;
 SELECT * INTO initial FROM public.ediel_messages WHERE company_id=c AND id=(supply->>'initialSourceMessageId')::uuid FOR SHARE;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(initial.raw_payload);
 IF initial.environment IS DISTINCT FROM e.environment OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' AND t#>>'{elements,2,0}'=e.brp_ediel_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK')<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_owned_original_brp_identity']);END IF;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=e.contract_id AND company_id=c FOR SHARE;SELECT * INTO customer FROM public.customers WHERE id=e.customer_id AND company_id=c FOR SHARE;SELECT * INTO mp FROM public.metering_points WHERE id=e.metering_point_id AND company_id=c FOR SHARE;
 IF contract.id IS NULL OR customer.id IS NULL OR mp.id IS NULL OR contract.customer_id IS DISTINCT FROM e.customer_id OR contract.metering_point_id IS DISTINCT FROM e.metering_point_id OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR gridex_received_sources.production_contract_hash_v1(contract) IS DISTINCT FROM e.protected_contract_hash OR encode(sha256(convert_to((to_jsonb(customer)-'updated_at')::text,'UTF8')),'hex') IS DISTINCT FROM e.customer_snapshot_hash OR mp.customer_id IS DISTINCT FROM e.customer_id OR mp.product_direction IS DISTINCT FROM 'consumption' OR mp.ediel_metering_point_id IS DISTINCT FROM e.point_id OR mp.grid_owner_ediel_id IS DISTINCT FROM e.legal_receiver_id OR mp.grid_area_code IS DISTINCT FROM e.grid_area_code THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_exact_owned_contract_customer_point']);END IF;
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE company_id=c AND environment=e.environment ORDER BY id FOR SHARE;PERFORM p.id FROM public.tenant_actor_identifiers p WHERE company_id=c AND environment=e.environment ORDER BY id FOR SHARE;PERFORM p.id FROM public.tenant_actor_roles p WHERE company_id=c AND environment=e.environment ORDER BY id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=e.environment AND market='electricity' AND is_enabled AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=e.environment AND actor_id=e.legal_actor_id AND role_code='electricity_supplier' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) OR (SELECT count(DISTINCT(actor_id,identifier_value)) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=e.environment AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()))<>1 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=e.environment AND actor_id=e.legal_actor_id AND identifier_type='EdielId' AND identifier_value=e.legal_sender_id AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_current_legal_supplier']);END IF;
 party:=e.customer_identity;
 IF jsonb_typeof(party) IS DISTINCT FROM 'object' OR nullif(party->>'id','') IS NULL OR nullif(party->>'name','') IS NULL OR (party->>'qualifier' IN('','1','SE1','SE2')) IS NOT TRUE OR party->>'agency' IS DISTINCT FROM (CASE WHEN party->>'qualifier'='' THEN '89' ELSE '260' END) OR jsonb_typeof(party->'addressLines') IS DISTINCT FROM 'array'
 OR e.invoicee_profile->>'meteringPointId' IS DISTINCT FROM e.point_id OR e.invoicee_profile->>'identityAgency' IS DISTINCT FROM e.identity_agency OR e.invoicee_profile#>>'{source,companyId}' IS DISTINCT FROM c::text OR e.invoicee_profile#>'{endUser,identity}' IS DISTINCT FROM jsonb_build_object('id',party->>'id','qualifier',party->>'qualifier','agency',party->>'agency') THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_explicit_customer_invoicee_source']);END IF;
 RETURN jsonb_build_object('status','authorized','companyId',c,'environment',e.environment,'eventId',e.id,'variant',e.variant,'eventKind',e.event_kind,'supplyPeriodId',e.supply_period_id,'supplySourceMessageId',e.supply_source_message_id,'supplyStateVersion',e.supply_state_version,'customerId',e.customer_id,'meteringPointId',e.metering_point_id,'legalActorId',e.legal_actor_id,'legalSenderId',e.legal_sender_id,'legalReceiverId',e.legal_receiver_id,'pointId',e.point_id,'identityAgency',e.identity_agency,'gridArea',e.grid_area_code,'brpEdielId',e.brp_ediel_id,'effectiveAt',e.effective_at,'sourceReference',e.source_reference,'sourceVersion',e.source_version,'sourceDigest',e.source_sha256,'customerIdentity',party,'invoiceeProfile',e.invoicee_profile);
END$$;

--
-- Name: context_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.context_v1(c uuid, event uuid, actor uuid, permission text DEFAULT 'communication.write'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;o gridex_requested_changes.review_origins%rowtype;a gridex_requested_changes.artifacts%rowtype;r gridex_requested_changes.reviews%rowtype;contract public.customer_contracts%rowtype;doc public.customer_contract_documents%rowtype;
BEGIN b:=gridex_requested_changes.context_before_intake_v1(c,event,actor,permission);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE event_id=event AND company_id=c FOR SHARE;SELECT * INTO a FROM gridex_requested_changes.artifacts WHERE id=o.artifact_id AND company_id=c FOR SHARE;SELECT * INTO r FROM gridex_requested_changes.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 IF o.event_id IS NULL OR a.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_requested_changes.actor_v1(c,r.reviewer_user_id,'review',a.kind) IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_current_immutable_archived_review_authority']);END IF;
 IF a.kind='death' THEN IF gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_current_issuer_and_representation_receipt']);END IF;
 ELSE SELECT * INTO contract FROM public.customer_contracts WHERE id=a.contract_id AND company_id=c FOR SHARE;SELECT * INTO doc FROM public.customer_contract_documents WHERE id=o.contract_document_id AND company_id=c AND customer_contract_id=contract.id FOR SHARE;
  IF doc.id IS NULL OR to_jsonb(doc) IS DISTINCT FROM o.contract_document_binding OR contract.document_sha256 IS DISTINCT FROM a.source_hash OR contract.signature_snapshot_sha256 IS DISTINCT FROM o.signature_hash OR encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex') IS DISTINCT FROM o.signature_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['actual_current_signed_contract_document_signature']);END IF;
 END IF;RETURN b;
END$$;

--
-- Name: customer_facet_basis_v1(jsonb, timestamp with time zone, uuid, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.customer_facet_basis_v1(body jsonb, cutoff timestamp with time zone, c uuid, env text, customer uuid, site uuid, source_id text, p_object_id text, agency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_requested_changes.confirmed_customer_versions%rowtype;a gridex_bilateral_customer_sources.artifacts%rowtype;snap gridex_received_sources.object_selection_snapshots%rowtype;w gridex_requested_changes.customer_version_availability%rowtype;src jsonb;receipt jsonb;n int;
BEGIN
 SELECT * INTO v FROM gridex_requested_changes.confirmed_customer_versions WHERE source_message_id::text=source_id AND company_id=c AND environment=env AND customer_id=customer AND site_id=site AND object_id=p_object_id AND identity_agency=agency AND canonical_assessment_id IS NOT NULL FOR SHARE;
 IF v.bilateral_artifact_id IS NULL THEN RETURN gridex_requested_changes.customer_facet_before_bilateral_v1(body,cutoff,c,env,customer,site,source_id,p_object_id,agency);END IF;
 SELECT count(*) INTO n FROM gridex_received_sources.object_selection_snapshots s WHERE s.company_id=c AND s.environment=env AND s.cutoff_at=cutoff AND s.readset_text::jsonb=body AND s.readset_hash=encode(sha256(convert_to(s.readset_text,'UTF8')),'hex');IF n<>1 THEN RETURN NULL;END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots s WHERE s.company_id=c AND s.environment=env AND s.cutoff_at=cutoff AND s.readset_text::jsonb=body FOR SHARE;
 IF NOT pg_visible_in_snapshot(v.created_xid,snap.visibility_snapshot::pg_snapshot) THEN RETURN NULL;END IF;
 SELECT * INTO w FROM gridex_requested_changes.customer_version_availability WHERE source_message_id=v.source_message_id AND company_id=c AND environment=env AND payload_hash=v.payload_hash AND observed_at<=cutoff FOR SHARE;IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(x)->0 INTO n,src FROM jsonb_array_elements(body->'sources') x WHERE x->>'sourceMessageId'=source_id AND x->>'payloadHash'=v.payload_hash;
 IF n<>1 OR src->>'rawPayload' IS NULL OR encode(sha256(convert_to(src->>'rawPayload','UTF8')),'hex') IS DISTINCT FROM v.payload_hash THEN RETURN NULL;END IF;
 SELECT * INTO a FROM gridex_bilateral_customer_sources.artifacts WHERE id=v.bilateral_artifact_id AND company_id=c AND environment=env AND source_message_id=v.source_message_id FOR SHARE;receipt:=gridex_bilateral_customer_sources.current_v1(a);
 IF receipt IS NULL OR a.claims->>'payloadHash' IS DISTINCT FROM v.payload_hash OR a.claims->>'customerId' IS DISTINCT FROM customer::text OR a.claims->>'siteId' IS DISTINCT FROM site::text OR a.claims->>'meteringPointId' IS DISTINCT FROM v.metering_point_id::text OR a.claims->>'supplyPeriodId' IS DISTINCT FROM v.supply_period_id::text OR a.claims->>'objectId' IS DISTINCT FROM p_object_id OR a.claims->>'identityAgency' IS DISTINCT FROM agency OR (a.claims->>'effectiveAt')::timestamptz IS DISTINCT FROM v.effective_at OR (a.claims->>'sourceReceivedAt')::timestamptz IS DISTINCT FROM v.received_at OR a.claims->>'legalSender' IS DISTINCT FROM v.legal_sender OR a.claims->>'legalReceiver' IS DISTINCT FROM v.legal_receiver OR a.claims->'party' IS DISTINCT FROM v.party OR a.claims->>'canonicalAssessmentId' IS DISTINCT FROM v.canonical_assessment_id::text THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('sourceMessageId',v.source_message_id,'payloadHash',v.payload_hash,'companyId',c,'environment',env,'customerId',customer,'siteId',site,'meteringPointId',v.metering_point_id,'supplyPeriodId',v.supply_period_id,'objectId',v.object_id,'identityAgency',v.identity_agency,'legalSender',v.legal_sender,'legalReceiver',v.legal_receiver,'effectiveAt',v.effective_at,'marketMinute',to_char(v.effective_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'),'availableAt',w.observed_at,'party',v.party,'authorityKind','bilateral','identityChangeAuthorized',receipt->'authorizedFields' @> '["227"]'::jsonb);
END$$;

--
-- Name: customer_facet_before_bilateral_v1(jsonb, timestamp with time zone, uuid, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.customer_facet_before_bilateral_v1(body jsonb, cutoff timestamp with time zone, c uuid, env text, customer uuid, site uuid, source_id text, p_object_id text, agency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_requested_changes.confirmed_customer_versions%rowtype;w gridex_requested_changes.customer_version_availability%rowtype;e gridex_requested_changes.events%rowtype;
 snap gridex_received_sources.object_selection_snapshots%rowtype;m public.ediel_messages%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;src jsonb;b jsonb;n integer;
BEGIN
 SELECT count(*) INTO n FROM gridex_received_sources.object_selection_snapshots s WHERE s.company_id=c AND s.environment=env AND s.cutoff_at=cutoff AND s.readset_text::jsonb=body AND s.readset_hash=encode(sha256(convert_to(s.readset_text,'UTF8')),'hex');
 IF n<>1 THEN RETURN NULL;END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots s WHERE s.company_id=c AND s.environment=env AND s.cutoff_at=cutoff AND s.readset_text::jsonb=body FOR SHARE;
 SELECT * INTO v FROM gridex_requested_changes.confirmed_customer_versions x WHERE x.source_message_id::text=source_id AND x.company_id=c AND x.environment=env AND x.customer_id=customer AND x.site_id=site AND x.object_id=p_object_id AND x.identity_agency=agency AND x.canonical_assessment_id IS NOT NULL FOR SHARE;
 IF NOT FOUND OR NOT pg_visible_in_snapshot(v.created_xid,snap.visibility_snapshot::pg_snapshot) THEN RETURN NULL;END IF;
 SELECT * INTO w FROM gridex_requested_changes.customer_version_availability x WHERE x.source_message_id=v.source_message_id AND x.company_id=c AND x.environment=env AND x.payload_hash=v.payload_hash AND x.observed_at<=cutoff FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(x)->0 INTO n,src FROM jsonb_array_elements(body->'sources') x WHERE x->>'sourceMessageId'=source_id AND x->>'payloadHash'=v.payload_hash;
 IF n<>1 OR src->>'rawPayload' IS NULL OR encode(sha256(convert_to(src->>'rawPayload','UTF8')),'hex') IS DISTINCT FROM v.payload_hash THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages x WHERE x.id=v.source_message_id AND x.company_id=c AND x.environment=env FOR SHARE;
 IF m.raw_payload IS DISTINCT FROM src->>'rawPayload' OR m.message_received_at IS DISTINCT FROM v.received_at THEN RETURN NULL;END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.id=v.canonical_assessment_id AND a.source_message_id=v.source_message_id AND a.company_id=c AND a.environment=env AND a.source_payload_hash=v.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF NOT FOUND OR canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted' THEN RETURN NULL;END IF;
 SELECT * INTO e FROM gridex_requested_changes.events x WHERE x.id=v.event_id AND x.company_id=c AND x.environment=env FOR SHARE;
 b:=gridex_requested_changes.context_v1(c,e.id,e.approved_by,'communication.write');
 IF b->>'status' IS DISTINCT FROM 'authorized' OR e.customer_id IS DISTINCT FROM v.customer_id OR e.metering_point_id IS DISTINCT FROM v.metering_point_id OR e.supply_period_id IS DISTINCT FROM v.supply_period_id OR e.point_id IS DISTINCT FROM p_object_id OR e.identity_agency IS DISTINCT FROM agency OR e.effective_at IS DISTINCT FROM v.effective_at OR e.legal_receiver_id IS DISTINCT FROM v.legal_sender OR e.legal_sender_id IS DISTINCT FROM v.legal_receiver OR v.party->>'id' IS DISTINCT FROM e.customer_identity->>'id' THEN RETURN NULL;END IF;
 PERFORM s.id FROM public.customer_sites s WHERE s.id=site AND s.company_id=c AND s.customer_id=customer FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(c,v.source_message_id);PERFORM gridex_ediel_source_rules.require_v1(c,v.source_message_id);
 RETURN jsonb_build_object('sourceMessageId',v.source_message_id,'payloadHash',v.payload_hash,'companyId',c,'environment',env,'customerId',customer,'siteId',site,'meteringPointId',v.metering_point_id,'supplyPeriodId',v.supply_period_id,'objectId',v.object_id,'identityAgency',v.identity_agency,'legalSender',v.legal_sender,'legalReceiver',v.legal_receiver,'effectiveAt',v.effective_at,'marketMinute',to_char(v.effective_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'),'availableAt',w.observed_at,'party',v.party);
END$$;

--
-- Name: issuer_revocation_lock_v1(); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.issuer_revocation_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_requested_changes.issuer_keys WHERE id=NEW.target_id FOR UPDATE;ELSE PERFORM id FROM gridex_requested_changes.issuer_representations WHERE id=NEW.target_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'requested_change_issuer_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: origin_guard_v1(); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.origin_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['message_id','payload_hash']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['message_id','payload_hash']) OR OLD.message_id IS NOT NULL OR NEW.message_id IS NULL OR NEW.payload_hash IS NULL THEN RAISE EXCEPTION 'requested_change_origin_immutable';END IF;RETURN NEW;END$$;

--
-- Name: party_matches_v1(jsonb, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.party_matches_v1(t jsonb, identity jsonb, names jsonb, lines jsonb, city text, postal text, country text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wire_lines jsonb:=lines;
BEGIN
 IF coalesce(lines->>0,'')='' AND EXISTS(SELECT FROM jsonb_array_elements_text(lines) WITH ORDINALITY x(v,n) WHERE n>1 AND v<>'') THEN wire_lines:=jsonb_set(lines,'{0}','"."');END IF;
 RETURN t#>'{elements,2}'=jsonb_build_array(identity->>'id',identity->>'qualifier',identity->>'agency') AND t#>'{elements,4}'=names AND t#>'{elements,5}'=wire_lines AND t#>>'{elements,6,0}' IS NOT DISTINCT FROM city AND t#>>'{elements,8,0}' IS NOT DISTINCT FROM postal AND t#>>'{elements,9,0}' IS NOT DISTINCT FROM country;
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_requested_changes; Owner: -
--

CREATE TABLE gridex_requested_changes.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    supply_period_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    metering_point_id uuid NOT NULL,
    legal_actor_id uuid NOT NULL,
    legal_sender_id text NOT NULL,
    legal_receiver_id text NOT NULL,
    point_id text NOT NULL,
    identity_agency text NOT NULL,
    grid_area_code text NOT NULL,
    brp_ediel_id text NOT NULL,
    supply_source_message_id uuid NOT NULL,
    supply_state_version bigint NOT NULL,
    protected_contract_hash text NOT NULL,
    customer_snapshot_hash text NOT NULL,
    kind text NOT NULL,
    effective_at timestamp with time zone NOT NULL,
    source_bytes bytea,
    source_hash text NOT NULL,
    mime_type text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    source_byte_length bigint,
    purged_at timestamp with time zone,
    CONSTRAINT artifacts_effective_at_check CHECK ((isfinite(effective_at) AND (EXTRACT(second FROM effective_at) = (0)::numeric))),
    CONSTRAINT artifacts_kind_check CHECK ((kind = ANY (ARRAY['death'::text, 'quarter_contract'::text, 'method_contract'::text]))),
    CONSTRAINT artifacts_mime_type_check CHECK ((mime_type = ANY (ARRAY['application/pdf'::text, 'text/plain'::text, 'application/json'::text]))),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608))),
    CONSTRAINT artifacts_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE ONLY gridex_requested_changes.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_requested_changes.artifacts); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.receipt_current_v1(a gridex_requested_changes.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_requested_changes.issuer_keys%rowtype;g gridex_requested_changes.issuer_representations%rowtype;p jsonb;raw bytea;r jsonb:=a.issuer_receipt;issued timestamptz;expires timestamptz;
BEGIN
 IF a.kind<>'death' OR r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_requested_changes.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment FOR SHARE;
 SELECT * INTO g FROM gridex_requested_changes.issuer_representations WHERE id=(r->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment AND legal_actor_id=a.legal_actor_id AND permitted_kind='death' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR EXISTS(SELECT FROM gridex_requested_changes.issuer_revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id) THEN RETURN false;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN false;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 RETURN p->>'format'='ediel_requested_change_issuer_receipt_v1' AND p->>'issuerCode'=k.issuer_code AND p->>'receiptId'<>'' AND p->>'companyId'=a.company_id::text AND p->>'environment'=a.environment AND p->>'legalActorId'=a.legal_actor_id::text AND p->>'customerId'=a.customer_id::text AND p->>'meteringPointId'=a.metering_point_id::text AND p->>'kind'='death' AND (p->>'effectiveAt')::timestamptz=a.effective_at AND p->>'sourceHash'=a.source_hash AND p->>'sourceReference'=a.source_reference AND p->>'sourceVersion'=a.source_version AND p->'customerIdentity'=a.claims->'customerIdentity' AND isfinite(issued) AND isfinite(expires) AND issued<=now() AND expires>now() AND issued>=greatest(k.valid_from,g.valid_from) AND expires<=least(k.valid_to,g.valid_to);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END$_$;

--
-- Name: receipt_hmac_sha256_v1(bytea, bytea); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.receipt_hmac_sha256_v1(payload bytea, key bytea) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE block bytea;inner_pad bytea:=decode(repeat('00',64),'hex');outer_pad bytea:=decode(repeat('00',64),'hex');n int;
BEGIN block:=CASE WHEN octet_length(key)>64 THEN sha256(key) ELSE key END;block:=block||decode(repeat('00',64-octet_length(block)),'hex');
 FOR n IN 0..63 LOOP inner_pad:=set_byte(inner_pad,n,get_byte(block,n)#54);outer_pad:=set_byte(outer_pad,n,get_byte(block,n)#92);END LOOP;
 RETURN sha256(outer_pad||sha256(inner_pad||payload));END$$;

--
-- Name: require_message_v1(public.ediel_messages, uuid, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.require_message_v1(m public.ediel_messages, actor uuid, permission text DEFAULT 'communication.write'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_requested_changes.origins%rowtype;e gridex_requested_changes.events%rowtype;b jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;tokens jsonb;own jsonb;reason text;iv jsonb;ud jsonb;point jsonb;need_iv boolean;
BEGIN
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE intent_id=m.intent_id AND company_id=m.company_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'requested_change_original_origin_required';END IF;
 SELECT * INTO e FROM gridex_requested_changes.events WHERE id=o.event_id FOR SHARE;b:=gridex_requested_changes.context_v1(m.company_id,e.id,actor,permission);IF b->>'status' IS DISTINCT FROM 'authorized' OR b IS DISTINCT FROM o.basis THEN RAISE EXCEPTION 'requested_change_original_current_source_required';END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=m.company_id FOR SHARE;SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=m.company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR (to_jsonb(i)-ARRAY['validation_result','blocking_reasons','validation_status','render_status','outbox_status','updated_by','updated_at','ediel_message_id','outbound_request_id']) IS DISTINCT FROM o.intent_binding OR (to_jsonb(r)-ARRAY['status','payload','response_payload','attempts_count','queued_at','prepared_at','sent_at','acknowledged_at','failed_at','failure_reason','updated_at','updated_by']) IS DISTINCT FROM o.request_binding OR m.environment IS DISTINCT FROM e.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' OR m.source_operation_id::text IS DISTINCT FROM e.id::text OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.customer_id IS DISTINCT FROM e.customer_id OR m.metering_point_id IS DISTINCT FROM e.metering_point_id OR m.application_reference IS DISTINCT FROM i.application_reference OR m.sender_ediel_id IS DISTINCT FROM i.sender_ediel_id OR m.receiver_ediel_id IS DISTINCT FROM i.receiver_ediel_id OR nullif(m.sender_sub_address,'') IS DISTINCT FROM nullif(i.sender_subaddress,'') OR nullif(m.receiver_sub_address,'') IS DISTINCT FROM nullif(i.receiver_subaddress,'') OR m.route_profile_id IS DISTINCT FROM i.route_profile_id OR m.communication_route_id IS DISTINCT FROM i.communication_route_id THEN RAISE EXCEPTION 'requested_change_message_scope_changed';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);reason:=CASE e.variant WHEN 'E' THEN 'E34' WHEN 'F' THEN 'E64' ELSE 'E32' END;
 IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z09' AND t#>>'{elements,2,0}'=i.interchange_reference)<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=e.point_id AND t#>>'{elements,3,3}'=e.identity_agency)<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND t#>>'{elements,1,1}'=i.transaction_reference)<>1 THEN RAISE EXCEPTION 'requested_change_physical_original_scope_changed';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='FR' AND t#>>'{elements,2,0}'=e.legal_sender_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='DO' AND t#>>'{elements,2,0}'=e.legal_receiver_id AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK')<>1 THEN RAISE EXCEPTION 'requested_change_legal_parties_changed';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='157' AND t#>>'{elements,1,1}'=to_char(e.effective_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI') AND t#>>'{elements,1,2}'='203')<>1 OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}' IN('92','93')) OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'=reason)<>1 THEN RAISE EXCEPTION 'requested_change_reason_or_effective_boundary_changed';END IF;
 IF e.variant='E' THEN
  SELECT t INTO ud FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD';
  IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1 OR gridex_requested_changes.party_matches_v1(ud,e.customer_identity,jsonb_build_array(e.customer_identity->>'name'),e.customer_identity->'addressLines',e.customer_identity->>'city',e.customer_identity->>'postalCode',e.customer_identity->>'country') IS NOT TRUE OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z41')<>1 THEN RAISE EXCEPTION 'requested_change_death_customer_changed';END IF;
  IF e.invoicee_profile#>>'{invoicee,availability}' IS DISTINCT FROM 'available' OR e.invoicee_profile#>'{endUser,address,representation}' IS NULL OR e.invoicee_profile#>>'{endUser,address,representation,convention}' IS DISTINCT FROM e.invoicee_profile#>>'{invoicee,address,representation,convention}' OR e.invoicee_profile#>'{endUser,address,representation,mode}' IS DISTINCT FROM e.invoicee_profile#>'{invoicee,address,representation,mode}' OR EXISTS(SELECT FROM jsonb_array_elements(e.invoicee_profile#>'{endUser,address,lines}') v WHERE jsonb_typeof(v)<>'string') OR EXISTS(SELECT FROM jsonb_array_elements(e.invoicee_profile#>'{invoicee,address,lines}') v WHERE jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'requested_change_invoicee_comparison_unqualified';END IF;
  need_iv:=e.invoicee_profile#>'{endUser,identity}' IS DISTINCT FROM e.invoicee_profile#>'{invoicee,identity}' OR ((e.invoicee_profile#>'{endUser,address}')-'representation') IS DISTINCT FROM ((e.invoicee_profile#>'{invoicee,address}')-'representation');
  SELECT t INTO iv FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV';
  IF need_iv THEN
   IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV')<>1 OR gridex_requested_changes.party_matches_v1(iv,e.invoicee_profile#>'{invoicee,identity}',e.invoicee_profile#>'{invoicee,nameLines}',e.invoicee_profile#>'{invoicee,address,lines}',e.invoicee_profile#>>'{invoicee,address,city}',e.invoicee_profile#>>'{invoicee,address,postalCode}',e.invoicee_profile#>>'{invoicee,address,country}') IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_invoicee_changed';END IF;
  ELSIF iv IS NOT NULL THEN RAISE EXCEPTION 'requested_change_invoicee_forbidden';END IF;
 ELSE
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN('UD','IV')) OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'='Z41') OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}'=(CASE e.variant WHEN 'F' THEN 'Z04' ELSE 'Z03' END))<>1 THEN RAISE EXCEPTION 'requested_change_metering_method_or_customer_scope_changed';END IF;
 END IF;
 IF o.message_id IS NOT NULL AND (o.message_id IS DISTINCT FROM m.id OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'requested_change_bound_original_changed';END IF;
 RETURN b;
END$$;

--
-- Name: revoke_lock_v1(); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.revoke_lock_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM id FROM gridex_requested_changes.events WHERE id=NEW.event_id FOR UPDATE;RETURN NEW;END$$;

--
-- Name: scoped_permission_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_requested_changes; Owner: -
--

CREATE FUNCTION gridex_requested_changes.scoped_permission_v1(c uuid, actor uuid, wanted text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM p.id FROM public.permissions p WHERE p.key=wanted ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_permissions p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_roles p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.roles p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.id) ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.role_permissions p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.role_id) ORDER BY p.id FOR SHARE;
 RETURN NOT EXISTS(SELECT FROM public.user_permission_overrides d WHERE d.user_id=actor AND (d.company_id IS NULL OR d.company_id=c) AND d.is_active AND d.effect='deny' AND d.permission_key=wanted AND (d.valid_from IS NULL OR d.valid_from<=clock_timestamp()) AND (d.valid_to IS NULL OR clock_timestamp()<d.valid_to))
 AND NOT EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id IS NULL OR u.company_id=c) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.is_active AND p.key=wanted)
 AND NOT EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.is_active AND p.key=wanted)
 AND (EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted));
END$$;

--
-- Name: actor_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.actor_v1(c uuid, actor uuid, mode text, kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM auth.users WHERE id=actor FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 RETURN actor IS NOT NULL AND mode IN('archive','read','review') AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=clock_timestamp()))
 AND gridex_requested_customer_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND gridex_requested_customer_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'customers.read' ELSE 'customers.write' END) IS TRUE
 AND (kind='death' OR gridex_requested_customer_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'contracts.read' ELSE 'contracts.write' END) IS TRUE)
 AND (mode<>'review' OR gridex_requested_customer_changes.scoped_permission_v1(c,actor,'ediel.source.review') IS TRUE);
END$$;

--
-- Name: current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.current_v1(artifact uuid, c uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_customer_changes.artifacts%rowtype;o gridex_requested_customer_changes.origins%rowtype;r gridex_requested_customer_changes.reviews%rowtype;receipt jsonb;actual jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();SELECT * INTO a FROM gridex_requested_customer_changes.artifacts WHERE id=artifact AND company_id=c;
 IF a.id IS NULL THEN RETURN NULL;END IF;
 actual:=gridex_requested_customer_changes.source_claims_v1(c,a.environment,a.agreement_id,a.supply_period_id,a.contract_id,a.raw_payload);
 SELECT * INTO a FROM gridex_requested_customer_changes.artifacts WHERE id=artifact AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_requested_customer_changes.origins WHERE artifact_id=a.id AND company_id=c FOR SHARE;SELECT * INTO r FROM gridex_requested_customer_changes.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 IF o.artifact_id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_requested_customer_changes.actor_v1(c,r.reviewer_user_id,'review','method_contract') IS NOT TRUE OR actual IS DISTINCT FROM a.claims OR a.claims_hash IS DISTINCT FROM encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.created_at>r.reviewed_at OR r.reviewed_at>o.recorded_at OR o.recorded_at>clock_timestamp() THEN RETURN NULL;END IF;
 receipt:=gridex_requested_customer_changes.receipt_current_v1(a);IF receipt IS NULL OR receipt->'clause' IS DISTINCT FROM r.clause OR position(convert_to(r.clause->>'quote','UTF8') IN a.source_bytes)=0 THEN RETURN NULL;END IF;
 -- All source/issuer/artifact locks are now held. Re-evaluate wall-clock legal
 -- scope and reviewer permissions after any wait before returning authority.
 actual:=gridex_requested_customer_changes.source_claims_v1(c,a.environment,a.agreement_id,a.supply_period_id,a.contract_id,a.raw_payload);
 IF actual IS DISTINCT FROM a.claims OR gridex_requested_customer_changes.actor_v1(c,r.reviewer_user_id,'review','method_contract') IS NOT TRUE THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',o.event_id);
EXCEPTION WHEN raise_exception OR data_exception THEN RETURN NULL;END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE TABLE gridex_requested_customer_changes.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    agreement_id uuid NOT NULL,
    supply_period_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    raw_payload text NOT NULL,
    claims jsonb NOT NULL,
    claims_hash text NOT NULL,
    source_bytes bytea NOT NULL,
    source_hash text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    submitted_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT artifacts_check CHECK ((source_hash = encode(sha256(source_bytes), 'hex'::text))),
    CONSTRAINT artifacts_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT artifacts_raw_payload_check CHECK (((octet_length(raw_payload) >= 1) AND (octet_length(raw_payload) <= 1048576))),
    CONSTRAINT artifacts_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 8388608)))
);

ALTER TABLE ONLY gridex_requested_customer_changes.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_requested_customer_changes.artifacts); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.receipt_current_v1(a gridex_requested_customer_changes.artifacts) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k gridex_requested_customer_changes.issuer_keys%rowtype;g gridex_requested_customer_changes.representations%rowtype;r jsonb:=a.issuer_receipt;p jsonb;raw bytea;issued timestamptz;expires timestamptz;
BEGIN
 IF a.claims->>'supplyQualified' IS DISTINCT FROM 'true' OR r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 65536 THEN RETURN NULL;END IF;
 SELECT * INTO k FROM gridex_requested_customer_changes.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment AND counterparty_actor_id=(a.claims->>'counterpartyActorId')::uuid FOR SHARE;
 SELECT * INTO g FROM gridex_requested_customer_changes.representations WHERE id=(r->>'representationId')::uuid AND company_id=a.company_id AND environment=a.environment AND issuer_key_id=k.id AND legal_actor_id=(a.claims->>'legalActorId')::uuid AND agreement_id=a.agreement_id AND purpose='prodat_z09e_requested_customer_change' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR clock_timestamp()<k.valid_from OR clock_timestamp()>=k.valid_to OR clock_timestamp()<g.valid_from OR clock_timestamp()>=g.valid_to OR EXISTS(SELECT FROM gridex_requested_customer_changes.revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id OR target_kind='artifact' AND target_id=a.id) THEN RETURN NULL;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF replace(encode(raw,'base64'),E'\n','') IS DISTINCT FROM r->>'payloadBase64' OR sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN NULL;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 IF issued IS NULL OR expires IS NULL OR NOT isfinite(issued) OR NOT isfinite(expires) OR expires<=issued THEN RETURN NULL;END IF;
 IF p->>'format' IS DISTINCT FROM 'ediel_requested_customer_change_receipt_v1' OR p->>'purpose' IS DISTINCT FROM 'prodat_z09e_requested_customer_change' OR nullif(p->>'receiptId','') IS NULL OR p->'claims' IS DISTINCT FROM a.claims OR p->>'sourceHash' IS DISTINCT FROM a.source_hash OR p->>'sourceReference' IS DISTINCT FROM a.source_reference OR p->>'sourceVersion' IS DISTINCT FROM a.source_version OR jsonb_typeof(p->'authorizedFields') IS DISTINCT FROM 'array' OR (p->'authorizedFields' @> '["227","228","231","232","316"]'::jsonb) IS NOT TRUE OR EXISTS(SELECT FROM jsonb_array_elements_text(p->'authorizedFields')f WHERE f NOT IN('227','228','229','231','232','249','250','251','252','253','316','317','318')) OR EXISTS(SELECT FROM jsonb_array_elements(a.claims->'customerTokens')t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' AND t#>'{elements,5}' IS NOT NULL AND (p->'authorizedFields' @> '["229"]'::jsonb) IS NOT TRUE) OR EXISTS(SELECT FROM jsonb_array_elements(a.claims->'customerTokens')t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV') AND (p->'authorizedFields' @> '["250","251","252","253","317","318"]'::jsonb) IS NOT TRUE OR EXISTS(SELECT FROM jsonb_array_elements(a.claims->'customerTokens')t WHERE t->>'tag'='DTM') AND (p->'authorizedFields' @> '["249"]'::jsonb) IS NOT TRUE OR NOT isfinite(issued) OR NOT isfinite(expires) OR issued>a.created_at OR issued>clock_timestamp() OR expires<=clock_timestamp() OR issued<greatest(k.valid_from,g.valid_from) OR expires>least(k.valid_to,g.valid_to) THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN data_exception THEN RETURN NULL;
END$_$;

--
-- Name: revoke_lock_v1(); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.revoke_lock_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_requested_customer_changes.issuer_keys WHERE id=NEW.target_id FOR UPDATE;
 ELSIF NEW.target_kind='representation' THEN PERFORM id FROM gridex_requested_customer_changes.representations WHERE id=NEW.target_id FOR UPDATE;
 ELSE PERFORM id FROM gridex_requested_customer_changes.artifacts WHERE id=NEW.target_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'requested_customer_change_revocation_target_required';END IF;RETURN NEW;END$$;

--
-- Name: scoped_permission_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.scoped_permission_v1(c uuid, actor uuid, wanted text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM p.id FROM public.permissions p WHERE p.key=wanted ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_permissions p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_roles p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.roles p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.id) ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.role_permissions p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.role_id) ORDER BY p.id FOR SHARE;
 RETURN NOT EXISTS(SELECT FROM public.user_permission_overrides d WHERE d.user_id=actor AND (d.company_id IS NULL OR d.company_id=c) AND d.is_active AND d.effect='deny' AND d.permission_key=wanted AND (d.valid_from IS NULL OR d.valid_from<=clock_timestamp()) AND (d.valid_to IS NULL OR clock_timestamp()<d.valid_to))
 AND NOT EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id IS NULL OR u.company_id=c) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.is_active AND p.key=wanted)
 AND NOT EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.is_active AND p.key=wanted)
 AND (EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted));
END$$;

--
-- Name: source_claims_v1(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_requested_customer_changes; Owner: -
--

CREATE FUNCTION gridex_requested_customer_changes.source_claims_v1(c uuid, env text, agreement uuid, supply_id uuid, contract_id uuid, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wire jsonb;own jsonb;tokens jsonb;first_lin int;end_lin int;customer_tokens jsonb;sp public.customer_supply_periods%rowtype;cc public.customer_contracts%rowtype;mp public.metering_points%rowtype;ba public.tenant_bilateral_agreements%rowtype;supply jsonb;at_time timestamptz;legal_actor uuid;sender text;scope jsonb;qualified bool;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF(env IN('test','production')) IS NOT TRUE OR raw IS NULL OR octet_length(raw) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'requested_customer_change_raw_required';END IF;
 wire:=gridex_customer_life_events.wire_v1(raw);tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);
 IF wire IS NULL OR wire->>'code' IS DISTINCT FROM 'Z09' OR jsonb_array_length(wire->'objects')<>1 THEN RAISE EXCEPTION 'requested_customer_change_whole_owned_z09e_required';END IF;own:=wire->'objects'->0;
 IF own->>'reason' IS DISTINCT FROM 'E34' OR own ? 'customerStatus' OR own->>'projectionHeld'='true' THEN RAISE EXCEPTION 'requested_customer_change_non_death_e34_required';END IF;
 at_time:=(own->>'effectiveAt')::timestamptz;
 IF at_time IS NULL OR NOT isfinite(at_time) THEN RAISE EXCEPTION 'requested_customer_change_physical_216_dtm157_required';END IF;
 SELECT min((t->>'index')::int) INTO first_lin FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN';
 SELECT min((t->>'index')::int) INTO end_lin FROM jsonb_array_elements(tokens)t WHERE (t->>'index')::int>first_lin AND t->>'tag' IN('LIN','UNH','UNT','UNZ');
 SELECT jsonb_agg(jsonb_build_object('tag',t->>'tag','elements',t->'elements') ORDER BY (t->>'index')::int) INTO customer_tokens FROM jsonb_array_elements(tokens)t WHERE (t->>'index')::int>first_lin AND (end_lin IS NULL OR(t->>'index')::int<end_lin) AND (t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN('UD','IV') OR t->>'tag'='DTM' AND t#>>'{elements,1,0}'='329');
 IF (SELECT count(*) FROM jsonb_array_elements(customer_tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1 OR (SELECT count(*) FROM jsonb_array_elements(customer_tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IV')>1 THEN RAISE EXCEPTION 'requested_customer_change_own_exact_customer_tokens_required';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=supply_id AND company_id=c;
 -- Qualified supply owner locks the immutable source union before own resources.
 supply:=gridex_received_sources.supply_period_source_at_v1(c,sp.id,at_time);qualified:=supply->>'qualified'='true';
 SELECT * INTO cc FROM public.customer_contracts WHERE id=contract_id AND company_id=c FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=sp.metering_point_id AND company_id=c FOR SHARE;
 IF sp.id IS NULL OR cc.id IS NULL OR mp.id IS NULL OR cc.customer_id IS DISTINCT FROM sp.customer_id OR cc.metering_point_id IS DISTINCT FROM mp.id OR mp.customer_id IS DISTINCT FROM sp.customer_id OR (cc.status IN('signed','active')) IS NOT TRUE OR cc.signed_at IS NULL OR nullif(cc.signed_version,'') IS NULL OR coalesce(sp.customer_contract_id,sp.contract_id) IS DISTINCT FROM cc.id OR mp.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR mp.grid_owner_ediel_id IS DISTINCT FROM wire->>'legalReceiver' OR mp.grid_area_code IS DISTINCT FROM own->>'gridArea' OR mp.product_direction IS DISTINCT FROM 'consumption' THEN RAISE EXCEPTION 'requested_customer_change_actual_owned_contract_point_required';END IF;
 PERFORM id FROM public.customer_sites WHERE id=coalesce(mp.customer_site_id,mp.site_id) AND company_id=c AND customer_id=sp.customer_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'requested_customer_change_owned_site_required';END IF;
 IF qualified AND (supply->>'companyId' IS DISTINCT FROM c::text OR supply->>'customerId' IS DISTINCT FROM sp.customer_id::text OR supply->>'siteId' IS DISTINCT FROM coalesce(mp.customer_site_id,mp.site_id)::text OR supply->>'meteringPointId' IS DISTINCT FROM mp.id::text OR supply->>'dsoEdielId' IS DISTINCT FROM wire->>'legalReceiver' OR NOT EXISTS(SELECT FROM jsonb_array_elements(supply->'sourceObjects')o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'gridArea'=own->>'gridArea')) THEN RAISE EXCEPTION 'requested_customer_change_same_owned_supply_required';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=supply_id AND company_id=c FOR SHARE;
 SELECT min(identifier_value),min(actor_id::text)::uuid INTO sender,legal_actor FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR valid_to>clock_timestamp());
 IF sender IS DISTINCT FROM wire->>'legalSender' OR (SELECT count(DISTINCT(actor_id,identifier_value)) FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR valid_to>clock_timestamp()))<>1 OR qualified AND supply->>'legalActorId' IS DISTINCT FROM legal_actor::text OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=env AND actor_id=legal_actor AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR valid_to>clock_timestamp())) OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR valid_to>clock_timestamp())) THEN RAISE EXCEPTION 'requested_customer_change_current_own_legal_supplier_required';END IF;
 SELECT * INTO ba FROM public.tenant_bilateral_agreements WHERE id=agreement AND company_id=c AND environment=env FOR SHARE;
 PERFORM id FROM public.platform_actor_identifiers WHERE actor_id=ba.counterparty_actor_id ORDER BY id FOR SHARE;PERFORM id FROM public.platform_actor_roles WHERE actor_id=ba.counterparty_actor_id ORDER BY id FOR SHARE;
 IF ba.id IS NULL OR ba.capability_code IS DISTINCT FROM 'prodat_z09e_requested_customer_change' OR ba.is_enabled IS NOT TRUE OR ba.valid_from IS NULL OR ba.valid_from>clock_timestamp() OR ba.valid_to<=clock_timestamp() OR nullif(ba.source_reference,'') IS NULL OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers WHERE actor_id=ba.counterparty_actor_id AND identifier_type='EdielId' AND identifier_value=wire->>'legalReceiver' AND is_verified AND(valid_from IS NULL OR valid_from<=(clock_timestamp()::date)) AND(valid_to IS NULL OR (clock_timestamp()::date)<=valid_to)) OR NOT EXISTS(SELECT FROM public.platform_actor_roles WHERE actor_id=ba.counterparty_actor_id AND actor_role='grid_owner' AND is_active) THEN RAISE EXCEPTION 'requested_customer_change_exact_current_dso_mandate_required';END IF;
 scope:=jsonb_build_array(jsonb_build_object('periodId',sp.id,'customerId',sp.customer_id,'siteId',coalesce(mp.customer_site_id,mp.site_id),'meteringPointId',mp.id,'pointId',own->>'point','identityAgency',own->>'identityAgency','gridArea',own->>'gridArea','sourceMessageId',supply->>'sourceMessageId','sourcePayloadHash',supply->>'payloadHash','marketStateVersion',supply->>'marketStateVersion','effectiveAt',own->>'effectiveAt','lineItemReference',own->>'li'));
 RETURN jsonb_build_object('purpose','prodat_z09e_requested_customer_change','companyId',c,'environment',env,'agreementId',ba.id,'agreementHash',encode(sha256(convert_to((to_jsonb(ba)-ARRAY['updated_at','created_at'])::text,'UTF8')),'hex'),'agreementReference',ba.source_reference,'agreementTermsHash',encode(sha256(convert_to(ba.terms::text,'UTF8')),'hex'),'counterpartyActorId',ba.counterparty_actor_id,'contractId',cc.id,'contractHash',gridex_received_sources.production_contract_hash_v1(cc),'customerId',sp.customer_id,'supplyPeriodId',sp.id,'supplyQualified',coalesce(qualified,false),'scope',scope,'legalActorId',legal_actor,'legalSender',sender,'legalReceiver',wire->>'legalReceiver','effectiveAt',own->>'effectiveAt','payloadHash',encode(sha256(convert_to(raw,'UTF8')),'hex'),'customerTokens',customer_tokens);
END$$;

--
-- Name: message_scope_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_requested_method_watches; Owner: -
--

CREATE FUNCTION gridex_requested_method_watches.message_scope_v1(m public.ediel_messages) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(m)) WHERE key=ANY(ARRAY[
 'id','company_id','environment','direction','message_standard','message_family','message_code','message_version',
 'created_by','intent_id','source_operation_id','outbound_request_id','customer_id','metering_point_id',
 'communication_route_id','route_profile_id','sender_ediel_id','receiver_ediel_id','sender_subaddress','receiver_subaddress',
 'application_reference','interchange_reference','transaction_reference','immutable_payload_hash','immutable_rendered_at']);
$$;

--
-- Name: coordinate_before_manual_resolution_v1(uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.coordinate_before_manual_resolution_v1(p_provider_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_command text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.ediel_service_assignments%rowtype; assessment jsonb; permission uuid; sharing integer;
begin
 perform u.id from public.user_profiles u where u.id=p_actor_user_id for share;
 perform m.user_id from public.company_memberships m where m.company_id=p_provider_company_id and m.user_id=p_actor_user_id for share;
 if not exists(select 1 from public.company_memberships m where m.company_id=p_provider_company_id and m.user_id=p_actor_user_id and m.status='active' and m.is_active and m.accepted_at is not null) or not exists(select 1 from public.user_profiles u where u.id=p_actor_user_id and u.user_status='active') or not coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_provider_company_id,'metering.write'),false) then raise exception 'ediel_service_command_forbidden' using errcode='42501'; end if;
 -- Lock the shared market tuple before any assignment row, avoiding A/B lock inversion.
 select * into strict a from public.ediel_service_assignments where company_id=p_provider_company_id and id=p_assignment_id;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
 select * into strict a from public.ediel_service_assignments where company_id=p_provider_company_id and id=p_assignment_id for update;
 if p_expected_version is null or p_expected_version<1 or a.version is distinct from p_expected_version then raise exception 'ediel_assignment_version_stale'; end if;
 if p_command='end_assignment' then
  update public.ediel_service_assignments set status='ended' where company_id=a.company_id and id=a.id;
  update public.ediel_data_access_grants set status='revoked',revoked_at=coalesce(revoked_at,now()) where company_id=a.company_id and assignment_id=a.id and status<>'revoked';
  select l.permission_id into permission from public.ediel_assignment_permission_links l where l.company_id=a.company_id and l.assignment_id=a.id order by l.created_at desc,l.id desc limit 1;
  select count(*) into sharing from public.ediel_assignment_permission_links l join public.ediel_service_assignments b on b.company_id=l.company_id and b.id=l.assignment_id where l.company_id=a.company_id and l.permission_id=permission and b.id<>a.id and b.status='active' and b.valid_from<=now() and (b.valid_to is null or b.valid_to>now());
  return jsonb_build_object('status',case when permission is not null and sharing=0 then 'market_termination_required' else 'assignment_ended' end,'permissionId',permission);
 elsif p_command is distinct from 'request_access' then raise exception 'ediel_service_command_invalid'; end if;
 assessment:=public.ediel_service_assignment_assessment_v1(a.company_id,a.id);
 if assessment->>'status'<>'authorized' then return assessment||jsonb_build_object('permissionId',null); end if;
 -- Compatibility requires the same market actor, environment, end-user, DSO, purpose, mode and full approved scope.
 select l.permission_id into permission from public.ediel_assignment_permission_links l
 join public.ediel_service_assignments b on b.company_id=l.company_id and b.id=l.assignment_id
 join public.metering_permissions p on p.company_id=l.company_id and p.id=l.permission_id
 where b.company_id=a.company_id and b.environment=a.environment and b.provider_actor_id=a.provider_actor_id and b.customer_id=a.customer_id and b.dso_actor_id=a.dso_actor_id and b.purpose=a.purpose and b.mode=a.mode
 and b.status='active' and b.valid_from<=now() and (b.valid_to is null or b.valid_to>now()) and a.field_sets <@ b.field_sets and public.ediel_service_assignment_assessment_v1(b.company_id,b.id)->>'status'='authorized' and a.object_ids <@ b.object_ids and a.product_ids <@ b.product_ids and a.data_start>=b.data_start and (b.data_end is null or (a.data_end is not null and a.data_end<=b.data_end))
 and p.status in ('draft','z13_ready','z13_sent','waiting_for_customer_approval','approved','partially_approved','z14_received','active')
 order by l.created_at,l.id limit 1;
 if permission is null then
  insert into public.metering_permissions(company_id,customer_id,status,purpose_code,permission_scope,requested_start_date,requested_end_date,metadata)
  values(a.company_id,a.customer_id,'draft',a.purpose,a.mode,(a.data_start at time zone 'Europe/Stockholm')::date,(a.data_end at time zone 'Europe/Stockholm')::date,jsonb_build_object('service_assignment_id',a.id,'provider_actor_id',a.provider_actor_id,'environment',a.environment,'dso_actor_id',a.dso_actor_id,'scope','service_assignment')) returning id into permission;
  insert into public.ediel_assignment_permission_links(company_id,assignment_id,permission_id) values(a.company_id,a.id,permission) on conflict do nothing;
  return jsonb_build_object('status','permission_required','permissionId',permission);
 end if;
 insert into public.ediel_assignment_permission_links(company_id,assignment_id,permission_id) values(a.company_id,a.id,permission) on conflict do nothing;
 return jsonb_build_object('status','reuse_permission','permissionId',permission);
end;
$$;

--
-- Name: coordinate_before_source_timing_v1(uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.coordinate_before_source_timing_v1(p_provider_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_command text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;a public.ediel_service_assignments%rowtype;sources uuid[];BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 IF p_command='request_access' THEN
  PERFORM gridex_service_administration.require_manual_actor_v1(p_provider_company_id,p_actor_user_id);
  SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_provider_company_id AND id=p_assignment_id;
  IF p_expected_version IS NULL OR p_expected_version<1 OR a.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'ediel_assignment_version_stale';END IF;
  sources:=gridex_service_administration.permission_originals_for_tuple_v1(a);
  PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=a.company_id AND m.id=ANY(sources) ORDER BY m.id FOR SHARE;
  PERFORM pg_advisory_xact_lock(hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
  IF gridex_service_administration.permission_originals_for_tuple_v1(a) IS DISTINCT FROM sources THEN RETURN jsonb_build_object('status','held','missing',ARRAY['permission_original_changed_retry_required']);END IF;
 END IF;
 result:=gridex_service_administration.coordinate_before_manual_resolution_v1(p_provider_company_id,p_assignment_id,p_actor_user_id,p_expected_version,p_command);
 IF p_command IS DISTINCT FROM 'request_access' OR (result->>'status' IN('permission_required','reuse_permission')) IS NOT TRUE THEN RETURN result;END IF;
 IF result->>'status'='permission_required' THEN
  SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_provider_company_id AND id=p_assignment_id FOR SHARE;
  -- Only this newly created, unbound draft receives its date projection. The
  -- actual source instants keep the Ediel fixed UTC+1 market calendar; no prior
  -- original/status/ACK is rewritten by this prospective coordinator.
  UPDATE public.metering_permissions SET requested_start_date=(a.data_start AT TIME ZONE INTERVAL '01:00')::date,requested_end_date=(a.data_end AT TIME ZONE INTERVAL '01:00')::date WHERE company_id=a.company_id AND id=(result->>'permissionId')::uuid AND status='draft' AND source_z13_message_id IS NULL AND outbound_z13_message_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_new_permission_draft_required';END IF;
  INSERT INTO gridex_service_administration.permission_request_owners(company_id,permission_id,assignment_id,scope_basis_version,scope) VALUES(a.company_id,(result->>'permissionId')::uuid,a.id,a.scope_basis_version,gridex_service_administration.scope_v1(a));
 END IF;
 RETURN public.ediel_resolve_service_permission_command_v1(p_provider_company_id,p_assignment_id,p_actor_user_id,p_expected_version,(result->>'permissionId')::uuid);
END $$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION 'ediel_service_command_immutable';END $$;

--
-- Name: manual_hold_v1(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.manual_hold_v1(c uuid, customer uuid, actor uuid, selection jsonb, missing jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE request_id uuid;task uuid;fingerprint text;BEGIN
 fingerprint:=encode(sha256(convert_to(selection::text||':'||missing::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel_manual_permission:'||c::text||':'||customer::text||':'||actor::text||':'||fingerprint,0));
 SELECT r.id INTO request_id FROM gridex_service_administration.manual_permission_requests r WHERE r.company_id=c AND r.customer_id=customer AND r.actor_user_id=actor AND r.selection_hash=fingerprint;
 IF request_id IS NULL THEN
  request_id:=gen_random_uuid();
  INSERT INTO public.customer_operation_tasks(company_id,customer_id,task_type,status,priority,title,description,assigned_to,metadata,created_by,updated_by)
   VALUES(c,customer,'ediel_service_permission_source_held','open','high','Mätvärdestillstånd behöver källunderlag','Välj ett entydigt aktuellt tjänsteuppdrag och styrkt behörighetsunderlag innan marknadsbegäran skapas.',actor,jsonb_build_object('serviceCommandRequestId',request_id,'selection',selection,'missing',missing,'marketActivationGranted',false),actor,actor) RETURNING id INTO task;
  INSERT INTO gridex_service_administration.manual_permission_requests(id,company_id,customer_id,actor_user_id,selection,selection_hash,missing,task_id) VALUES(request_id,c,customer,actor,selection,fingerprint,missing,task);
 END IF;
 RETURN jsonb_build_object('status','held','requestId',request_id,'missing',missing);
END $$;

--
-- Name: metering_permissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.metering_permissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    site_id uuid,
    metering_point_id uuid,
    grid_owner_id uuid,
    authorization_document_id uuid,
    permission_reference text,
    case_reference text,
    status text DEFAULT 'draft'::text NOT NULL,
    requested_start_date date,
    requested_end_date date,
    approved_start_date date,
    approved_end_date date,
    resolution_code text,
    report_frequency text,
    source_z13_message_id uuid,
    source_z14_message_id uuid,
    last_blocker text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    customer_site_id uuid,
    grid_owner_ediel_id text,
    permission_scope text,
    purpose_code text,
    product_code text,
    direction_code text,
    requested_from_date date,
    requested_to_date date,
    rff_li_reference text,
    permission_id text,
    outbound_z13_message_id uuid,
    inbound_z14_message_id uuid,
    inbound_z15_message_id uuid,
    outbound_z18_message_id uuid,
    market_state_version bigint DEFAULT 0 NOT NULL,
    approved_start_at timestamp with time zone,
    approved_end_at timestamp with time zone,
    CONSTRAINT metering_permissions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'missing_authorization'::text, 'z13_ready'::text, 'z13_sent'::text, 'waiting_for_customer_approval'::text, 'partially_approved'::text, 'approved'::text, 'rejected_active'::text, 'rejected_passive_timeout'::text, 'z14_received'::text, 'active'::text, 'ended'::text, 'cancelled'::text, 'blocked'::text])))
);

--
-- Name: permission_matches_assignment_v1(public.ediel_service_assignments, public.metering_permissions); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.permission_matches_assignment_v1(a public.ediel_service_assignments, p public.metering_permissions) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE sender text;receiver text;
BEGIN
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment ORDER BY i.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id ORDER BY i.id FOR SHARE;
 IF (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RETURN false;END IF;
 SELECT i.identifier_value INTO sender FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()) LIMIT 1;
 SELECT i.identifier_value INTO receiver FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date) LIMIT 1;
 RETURN p.company_id=a.company_id AND p.customer_id=a.customer_id AND sender IS NOT NULL AND receiver IS NOT NULL AND p.grid_owner_ediel_id=receiver AND p.metadata#>>'{marketPermission,legalActor}'=sender AND p.metadata#>>'{marketPermission,dsoActor}'=receiver AND p.metadata#>>'{marketPermission,mode}'=CASE a.mode WHEN 'V' THEN 'S17' WHEN 'VH' THEN 'S18' END AND public.ediel_permission_source_is_current_v1(a.company_id,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS TRUE;
END $$;

--
-- Name: permission_originals_for_tuple_v1(public.ediel_service_assignments); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.permission_originals_for_tuple_v1(a public.ediel_service_assignments) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(array_agg(DISTINCT o.message_id ORDER BY o.message_id),'{}'::uuid[]) FROM gridex_service_permission.origins o JOIN public.ediel_service_assignments b ON b.company_id=o.company_id AND b.id=o.assignment_id WHERE o.company_id=a.company_id AND o.message_code='Z13' AND o.message_id IS NOT NULL AND b.environment=a.environment AND b.provider_actor_id=a.provider_actor_id AND b.customer_id=a.customer_id AND b.dso_actor_id=a.dso_actor_id AND b.mode=a.mode
$$;

--
-- Name: record_scope_v1(); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.record_scope_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
 IF NEW.scope_basis_version IS NOT NULL AND (TG_OP='INSERT' OR NEW.scope_basis_version IS DISTINCT FROM OLD.scope_basis_version) THEN INSERT INTO gridex_service_administration.scope_versions(company_id,assignment_id,scope_basis_version,scope) VALUES(NEW.company_id,NEW.id,NEW.scope_basis_version,gridex_service_administration.scope_v1(NEW));END IF;
 RETURN NEW;
END $$;

--
-- Name: require_manual_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.require_manual_actor_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(actor,c,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_manual_actor_forbidden' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: scope_guard_v1(); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.scope_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.scope_basis_version IS NOT NULL THEN RAISE EXCEPTION 'ediel_service_scope_version_server_owned';END IF;
  NEW.scope_basis_version:=1;
 ELSE
  IF NEW.scope_basis_version IS DISTINCT FROM OLD.scope_basis_version THEN RAISE EXCEPTION 'ediel_service_scope_version_server_owned';END IF;
  IF gridex_service_administration.scope_v1(NEW) IS DISTINCT FROM gridex_service_administration.scope_v1(OLD) THEN
   -- An unjournalled legacy basis remains unknown even after editing it.
   NEW.scope_basis_version:=CASE WHEN OLD.scope_basis_version IS NULL THEN NULL ELSE OLD.scope_basis_version+1 END;
   IF NEW.status NOT IN ('revoked','ended') THEN NEW.status:='held';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: scope_v1(public.ediel_service_assignments); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.scope_v1(a public.ediel_service_assignments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
 SELECT jsonb_build_object('companyId',a.company_id,'beneficiaryCompanyId',a.beneficiary_company_id,'providerActorId',a.provider_actor_id,'actorProfileId',a.actor_profile_id,'customerId',a.customer_id,'dsoActorId',a.dso_actor_id,'environment',a.environment,'mode',a.mode,'purpose',a.purpose,'objects',a.object_ids,'products',a.product_ids,'fields',a.field_sets,'dataStart',a.data_start,'dataEnd',a.data_end,'validFrom',a.valid_from,'validTo',a.valid_to)
$$;

--
-- Name: bind_agreement_reference_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.bind_agreement_reference_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE origin gridex_service_permission.origins%rowtype;
BEGIN
 SELECT * INTO origin FROM gridex_service_permission.origins WHERE intent_id=NEW.intent_id AND company_id=NEW.company_id;
 IF origin.intent_id IS NOT NULL THEN PERFORM gridex_service_permission.require_agreement_reference_v1(NEW,origin.basis);END IF;
 RETURN NEW;
END $$;

--
-- Name: bind_message_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.bind_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s gridex_service_permission.origins%rowtype; b jsonb; wire jsonb; o jsonb; p public.metering_permissions%rowtype;
BEGIN
 SELECT * INTO s FROM gridex_service_permission.origins WHERE intent_id=NEW.intent_id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 b:=gridex_service_permission.context_v1(s.company_id,s.assignment_id,s.actor_user_id,(s.basis->>'assignmentVersion')::bigint,s.message_code,s.permission_id);
 SELECT * INTO STRICT s FROM gridex_service_permission.origins WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF s.message_id IS NOT NULL THEN RAISE EXCEPTION 'ediel_permission_origin_already_bound' USING ERRCODE='23505'; END IF;
 IF b IS DISTINCT FROM s.basis OR b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_permission_origin_basis_stale'; END IF;
 wire:=gridex_received_sources.permission_wire_v1(NEW.raw_payload);
 IF NEW.company_id IS DISTINCT FROM s.company_id OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM s.message_code OR NEW.environment IS DISTINCT FROM b->>'environment' OR NEW.customer_id IS DISTINCT FROM (b->>'customerId')::uuid OR wire->>'sender' IS DISTINCT FROM b->>'legalSenderId' OR wire->>'receiver' IS DISTINCT FROM b->>'legalReceiverId' OR wire->>'code' IS DISTINCT FROM s.message_code OR wire IS NULL OR jsonb_array_length(wire->'objects')<>jsonb_array_length(b->'objects') OR (s.message_code='Z18' AND (SELECT count(DISTINCT (v->>'point',v->>'permissionId')) FROM jsonb_array_elements(wire->'objects') v)<>jsonb_array_length(b->'objects')) THEN RAISE EXCEPTION 'ediel_permission_origin_wire_scope_mismatch'; END IF;
 FOR o IN SELECT v FROM jsonb_array_elements(wire->'objects') v LOOP
  IF o->>'reason' IS DISTINCT FROM (CASE b->>'mode' WHEN 'V' THEN 'S17' ELSE 'S18' END) OR o->>'li' IS DISTINCT FROM (SELECT transaction_reference FROM public.ediel_message_intents WHERE id=s.intent_id) OR nullif(o->>'li','') IS NULL THEN RAISE EXCEPTION 'ediel_permission_origin_wire_mode_mismatch'; END IF;
  IF s.message_code='Z13' THEN
   IF nullif(o->>'point','') IS NOT NULL OR nullif(o->>'gridArea','') IS NOT NULL OR nullif(b#>>'{objects,0,gridArea}','') IS NULL OR o->>'purpose' IS DISTINCT FROM b->>'purposeCode' OR o->>'frequency' IS DISTINCT FROM b->>'frequency' OR o->>'product' IS DISTINCT FROM b#>>'{objects,0,product}' OR gridex_received_sources.permission_time_v1(o->>'reportStart') IS DISTINCT FROM (b#>>'{objects,0,reportStart}')::timestamptz OR gridex_received_sources.permission_time_v1(o->>'reportEnd') IS DISTINCT FROM (b#>>'{objects,0,reportEnd}')::timestamptz OR nullif(o->>'customerIdentity','') IS NULL OR o->>'customerIdentity' IS DISTINCT FROM coalesce(nullif(btrim(b#>>'{customer,org_number}'),''),nullif(btrim(b#>>'{customer,personal_number}'),'')) THEN RAISE EXCEPTION 'ediel_permission_origin_wire_request_mismatch'; END IF;
  ELSE
   IF o->>'li' IS DISTINCT FROM b->>'li' OR o->>'endReason' IS DISTINCT FROM b->>'terminationReason' OR NOT EXISTS(SELECT FROM jsonb_array_elements(b->'objects') expected WHERE expected->>'point'=o->>'point' AND expected->>'permissionId'=o->>'permissionId' AND (expected->>'permissionEnd')::timestamptz=gridex_received_sources.permission_time_v1(o->>'permissionEnd')) THEN RAISE EXCEPTION 'ediel_permission_origin_wire_termination_mismatch'; END IF;
  END IF;
 END LOOP;
 SELECT * INTO STRICT p FROM public.metering_permissions WHERE company_id=s.company_id AND id=s.permission_id FOR UPDATE;
 IF s.message_code='Z13' THEN
  UPDATE public.metering_permissions SET source_z13_message_id=NEW.id,outbound_z13_message_id=NEW.id,rff_li_reference=wire#>>'{objects,0,li}',grid_owner_ediel_id=b->>'legalReceiverId',status='z13_ready',updated_by=s.actor_user_id,updated_at=now() WHERE id=p.id AND company_id=s.company_id AND source_z13_message_id IS NULL AND outbound_z13_message_id IS NULL;
 ELSE
  UPDATE public.metering_permissions SET outbound_z18_message_id=NEW.id,updated_by=s.actor_user_id,updated_at=now() WHERE id=p.id AND company_id=s.company_id;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_permission_origin_existing_message_conflict'; END IF;
 UPDATE gridex_service_permission.origins SET message_id=NEW.id WHERE intent_id=s.intent_id;
 RETURN NEW;
END $$;

--
-- Name: bind_requested_method_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.bind_requested_method_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE origin gridex_service_permission.origins%rowtype;BEGIN
 SELECT * INTO origin FROM gridex_service_permission.origins WHERE intent_id=NEW.intent_id AND company_id=NEW.company_id;
 IF origin.intent_id IS NOT NULL THEN PERFORM gridex_service_permission.require_requested_method_v1(NEW,origin.basis);END IF;
 RETURN NEW;
END $$;

--
-- Name: context_before_agreement_reference_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_before_agreement_reference_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a public.ediel_service_assignments%rowtype; p public.metering_permissions%rowtype; e public.ediel_service_evidence%rowtype;
 assessment jsonb; objects jsonb; legal_id text; dso_id text; customer_record jsonb; previous_origin gridex_service_permission.origins%rowtype;
BEGIN
 IF c IS NULL OR aid IS NULL OR actor IS NULL OR pid IS NULL OR expected_version IS NULL OR expected_version<1 OR (code IN ('Z13','Z18')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_scope_required'; END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
 OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
 OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'metering.write'),false) THEN RAISE EXCEPTION 'ediel_permission_origin_actor_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid;
 -- Same tuple order as the coordinator. The permission cannot be terminated
 -- concurrently with another assignment acquiring/reusing that permission.
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid FOR SHARE;
 IF a.version IS DISTINCT FROM expected_version THEN RAISE EXCEPTION 'ediel_permission_origin_assignment_stale'; END IF;
 IF a.scope_basis_version IS NULL OR NOT EXISTS(SELECT FROM gridex_service_administration.scope_versions sv WHERE sv.company_id=c AND sv.assignment_id=aid AND sv.scope_basis_version=a.scope_basis_version AND sv.scope=gridex_service_administration.scope_v1(a)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_assignment_scope_journal_required']);END IF;
 -- Legal ESCO and its own electricity profile must remain current for BOTH
 -- request and termination; an ended internal assignment does not revoke a
 -- legal actor's authorization checks.
 PERFORM x.id FROM public.tenant_ediel_profiles x WHERE x.company_id=c AND x.id=a.actor_profile_id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.actor_id=a.provider_actor_id AND r.environment=a.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles x WHERE x.company_id=c AND x.id=a.actor_profile_id AND x.environment=a.environment AND x.market='electricity' AND x.is_enabled AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.actor_id=a.provider_actor_id AND r.environment=a.environment AND r.role_code='energy_service_company' AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_provider_electricity_profile_and_esco_role']); END IF;
 PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' ORDER BY r.id FOR SHARE;
 PERFORM ev.id FROM public.ediel_service_evidence ev WHERE ev.company_id=c AND ev.assignment_id=aid ORDER BY ev.id FOR SHARE;
 IF (SELECT count(*) FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now()))>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['provider_transport_relation_ambiguous']); END IF;
 IF EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.counterparty_actor_id<>a.provider_actor_id AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now())) AND NOT EXISTS(SELECT FROM public.ediel_service_evidence ev JOIN public.tenant_counterparty_relations r ON r.company_id=c AND r.id=ev.transport_relation_id AND r.counterparty_actor_id=ev.transport_actor_id AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now()) WHERE ev.company_id=c AND ev.assignment_id=aid AND ev.kind='transport_mandate' AND ev.status='verified' AND ev.approved_assignment_version=a.scope_basis_version AND ev.approved_at<=now() AND ev.valid_from<=now() AND (ev.valid_to IS NULL OR ev.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_transport_mandate']); END IF;

 SELECT * INTO STRICT p FROM public.metering_permissions WHERE company_id=c AND id=pid FOR UPDATE;
 IF p.customer_id IS DISTINCT FROM a.customer_id OR NOT EXISTS(SELECT FROM public.ediel_assignment_permission_links l WHERE l.company_id=c AND l.assignment_id=aid AND l.permission_id=pid) THEN RAISE EXCEPTION 'ediel_permission_origin_link_mismatch'; END IF;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment FOR SHARE;
 SELECT min(i.identifier_value) INTO legal_id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now());
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id FOR SHARE;
 SELECT min(i.identifier_value) INTO dso_id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
 IF (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['provider_legal_identity_ambiguous']); END IF;
 IF nullif(legal_id,'') IS NULL OR nullif(dso_id,'') IS NULL OR (SELECT count(DISTINCT i.identifier_value) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_unique_legal_sender_and_dso_identity']); END IF;
 SELECT to_jsonb(x) INTO customer_record FROM public.customers x WHERE x.id=a.customer_id AND x.company_id=c FOR SHARE;
 PERFORM x.id FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid FOR SHARE;
 IF code='Z13' THEN
  assessment:=public.ediel_service_assignment_assessment_v1(c,aid);
  IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RETURN assessment; END IF;
  IF (p.status IN ('draft','z13_ready','z13_sent','waiting_for_customer_approval')) IS NOT TRUE OR (p.status IN ('z13_sent','waiting_for_customer_approval') AND p.outbound_z13_message_id IS NULL) OR (p.source_z13_message_id IS NOT NULL AND p.source_z13_message_id IS DISTINCT FROM p.outbound_z13_message_id) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['request_permission_state']); END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now() AND x.permission_purpose_code IS NOT NULL AND nullif(x.permission_reporting_frequency,'') IS NOT NULL ORDER BY x.id LIMIT 1;
  IF NOT FOUND OR (SELECT count(DISTINCT (x.permission_purpose_code,x.permission_reporting_frequency,x.permission_request_grid_area,x.permission_reporting_term_kind,x.permission_customer_classification)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_assessed_permission_reporting_tuple']); END IF;
  IF cardinality(a.product_ids)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['single_source_defined_request_product']); END IF;
  IF nullif(e.permission_request_grid_area,'') IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_defined_request_grid_area']); END IF;
  IF e.permission_reporting_term_kind IS NULL OR e.permission_customer_classification IS NULL OR (e.permission_reporting_term_kind='bounded' AND a.data_end IS NULL) OR (e.permission_reporting_term_kind='indefinite' AND (a.data_end IS NOT NULL OR a.mode='VH')) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_declared_reporting_term_and_customer_classification']); END IF;
  IF date_trunc('minute',a.data_start) IS DISTINCT FROM a.data_start OR date_trunc('minute',a.data_end) IS DISTINCT FROM a.data_end THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_minute_precision_reporting_dates']); END IF;
  objects:=jsonb_build_array(jsonb_build_object('point',NULL,'permissionId',NULL,'product',a.product_ids[1],'gridArea',e.permission_request_grid_area,'reportStart',a.data_start,'reportEnd',a.data_end));
 ELSE
  IF a.status IS DISTINCT FROM 'ended' OR a.mode IS DISTINCT FROM 'V' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['ended_fortlopande_assignment']); END IF;
  IF EXISTS(SELECT FROM public.ediel_assignment_permission_links l JOIN public.ediel_service_assignments other ON other.company_id=l.company_id AND other.id=l.assignment_id WHERE l.company_id=c AND l.permission_id=pid AND other.status='active' AND other.valid_from<=now() AND (other.valid_to IS NULL OR other.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['permission_still_required_by_active_assignment']); END IF;
  PERFORM s.id FROM public.metering_permission_sites s WHERE s.company_id=c AND s.metering_permission_id=pid ORDER BY s.id FOR SHARE;
  IF (p.status IN ('active','approved','partially_approved')) IS NOT TRUE OR public.ediel_permission_source_is_current_v1(c,pid,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS NOT TRUE OR gridex_service_administration.permission_matches_assignment_v1(a,p) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_source_approved_permission']); END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='service_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now() AND x.permission_termination_reason IS NOT NULL AND x.permission_termination_at IS NOT NULL ORDER BY x.id LIMIT 1;
  IF NOT FOUND OR (SELECT count(DISTINCT (x.permission_termination_reason,x.permission_termination_at)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='service_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_assessed_permission_termination']); END IF;
  IF p.outbound_z18_message_id IS NOT NULL THEN
   SELECT * INTO previous_origin FROM gridex_service_permission.origins prior WHERE prior.company_id=c AND prior.permission_id=pid AND prior.message_id=p.outbound_z18_message_id AND prior.message_code='Z18';
   IF NOT FOUND OR (NOT(previous_origin.basis->>'evidenceId'=e.id::text AND (previous_origin.basis->>'permissionStateVersion')::bigint=p.market_state_version) AND (p.metadata#>>'{z15,reason}' IS DISTINCT FROM 'Z24' OR p.market_state_version<=(previous_origin.basis->>'permissionStateVersion')::bigint)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['prior_termination_cycle_not_source_cancelled']); END IF;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('point',s.facility_id,'permissionId',s.metadata->>'permissionId','product',s.metadata->>'product','gridArea',s.grid_area_code,'permissionEnd',e.permission_termination_at) ORDER BY s.facility_id,s.id) INTO objects FROM public.metering_permission_sites s WHERE s.company_id=c AND s.metering_permission_id=pid AND s.status IN ('approved','active');
  IF objects IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['approved_permission_objects']); END IF;
  IF date_trunc('minute',e.permission_termination_at) IS DISTINCT FROM e.permission_termination_at THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_minute_precision_termination_date']); END IF;
 END IF;
 RETURN jsonb_build_object('status','authorized','companyId',c,'assignmentId',aid,'assignmentVersion',a.version,'scopeBasisVersion',a.scope_basis_version,'permissionId',pid,'permissionStateVersion',p.market_state_version,'code',code,'environment',a.environment,'providerActorId',a.provider_actor_id,'dsoActorId',a.dso_actor_id,'legalSenderId',legal_id,'legalReceiverId',dso_id,'customerId',a.customer_id,'customer',customer_record,'mode',a.mode,'purposeCode',e.permission_purpose_code,'frequency',e.permission_reporting_frequency,'reportingTerm',e.permission_reporting_term_kind,'customerClassification',e.permission_customer_classification,'terminationReason',e.permission_termination_reason,'evidenceId',e.id,'evidenceSha256',e.source_sha256,'evidenceVersion',e.source_version,'objects',objects,'li',CASE WHEN code='Z18' THEN p.rff_li_reference ELSE NULL END);
END $$;

--
-- Name: context_before_requested_method_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_before_requested_method_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;e public.ediel_service_evidence%rowtype;
BEGIN
 basis:=gridex_service_permission.context_before_agreement_reference_v1(c,aid,actor,expected_version,code,pid);
 IF basis->>'status' IS DISTINCT FROM 'authorized' OR code IS DISTINCT FROM 'Z13' THEN RETURN basis;END IF;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=c AND assignment_id=aid AND id=(basis->>'evidenceId')::uuid FOR SHARE;
 IF e.id IS NULL OR e.kind IS DISTINCT FROM 'end_user_contract' OR e.status IS DISTINCT FROM 'verified' OR nullif(e.permission_agreement_reference,'') IS NULL
  OR (SELECT count(DISTINCT (x.permission_purpose_code,x.permission_reporting_frequency,x.permission_request_grid_area,x.permission_reporting_term_kind,x.permission_customer_classification,x.permission_agreement_reference)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=(basis->>'scopeBasisVersion')::bigint AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_source_defined_end_user_agreement_reference']);END IF;
 RETURN basis||jsonb_build_object('agreementReference',e.permission_agreement_reference);
END $$;

--
-- Name: context_before_source_timing_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_before_source_timing_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
BEGIN
 IF c IS NULL OR aid IS NULL OR actor IS NULL OR pid IS NULL OR expected_version IS NULL OR expected_version<1 OR (code IN('Z13','Z18')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'metering.write'),false) THEN RAISE EXCEPTION 'ediel_permission_origin_actor_forbidden' USING ERRCODE='42501';END IF;
 RETURN gridex_service_permission.context_source_v1(c,aid,actor,expected_version,code,pid);
END$$;

--
-- Name: context_source_agreement_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_source_agreement_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;e public.ediel_service_evidence%rowtype;
BEGIN
 basis:=gridex_service_permission.context_source_base_v1(c,aid,actor,expected_version,code,pid);
 IF basis->>'status' IS DISTINCT FROM 'authorized' OR code IS DISTINCT FROM 'Z13' THEN RETURN basis;END IF;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=c AND assignment_id=aid AND id=(basis->>'evidenceId')::uuid FOR SHARE;
 IF e.id IS NULL OR e.kind IS DISTINCT FROM 'end_user_contract' OR e.status IS DISTINCT FROM 'verified' OR nullif(e.permission_agreement_reference,'') IS NULL
  OR (SELECT count(DISTINCT (x.permission_purpose_code,x.permission_reporting_frequency,x.permission_request_grid_area,x.permission_reporting_term_kind,x.permission_customer_classification,x.permission_agreement_reference)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=(basis->>'scopeBasisVersion')::bigint AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_source_defined_end_user_agreement_reference']);END IF;
 RETURN basis||jsonb_build_object('agreementReference',e.permission_agreement_reference);
END $$;

--
-- Name: context_source_base_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_source_base_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a public.ediel_service_assignments%rowtype; p public.metering_permissions%rowtype; e public.ediel_service_evidence%rowtype;
 assessment jsonb; objects jsonb; legal_id text; dso_id text; customer_record jsonb; previous_origin gridex_service_permission.origins%rowtype;
BEGIN
 IF c IS NULL OR aid IS NULL OR actor IS NULL OR pid IS NULL OR expected_version IS NULL OR expected_version<1 OR (code IN ('Z13','Z18')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_scope_required'; END IF;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid;
 -- Same tuple order as the coordinator. The permission cannot be terminated
 -- concurrently with another assignment acquiring/reusing that permission.
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid FOR SHARE;
 IF a.version IS DISTINCT FROM expected_version THEN RAISE EXCEPTION 'ediel_permission_origin_assignment_stale'; END IF;
 IF a.scope_basis_version IS NULL OR NOT EXISTS(SELECT FROM gridex_service_administration.scope_versions sv WHERE sv.company_id=c AND sv.assignment_id=aid AND sv.scope_basis_version=a.scope_basis_version AND sv.scope=gridex_service_administration.scope_v1(a)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_assignment_scope_journal_required']);END IF;
 -- Legal ESCO and its own electricity profile must remain current for BOTH
 -- request and termination; an ended internal assignment does not revoke a
 -- legal actor's authorization checks.
 PERFORM x.id FROM public.tenant_ediel_profiles x WHERE x.company_id=c AND x.id=a.actor_profile_id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.actor_id=a.provider_actor_id AND r.environment=a.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles x WHERE x.company_id=c AND x.id=a.actor_profile_id AND x.environment=a.environment AND x.market='electricity' AND x.is_enabled AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.actor_id=a.provider_actor_id AND r.environment=a.environment AND r.role_code='energy_service_company' AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_provider_electricity_profile_and_esco_role']); END IF;
 PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' ORDER BY r.id FOR SHARE;
 PERFORM ev.id FROM public.ediel_service_evidence ev WHERE ev.company_id=c AND ev.assignment_id=aid ORDER BY ev.id FOR SHARE;
 IF (SELECT count(*) FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now()))>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['provider_transport_relation_ambiguous']); END IF;
 IF EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=c AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.counterparty_actor_id<>a.provider_actor_id AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now())) AND NOT EXISTS(SELECT FROM public.ediel_service_evidence ev JOIN public.tenant_counterparty_relations r ON r.company_id=c AND r.id=ev.transport_relation_id AND r.counterparty_actor_id=ev.transport_actor_id AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR r.valid_to>now()) WHERE ev.company_id=c AND ev.assignment_id=aid AND ev.kind='transport_mandate' AND ev.status='verified' AND ev.approved_assignment_version=a.scope_basis_version AND ev.approved_at<=now() AND ev.valid_from<=now() AND (ev.valid_to IS NULL OR ev.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_transport_mandate']); END IF;

 SELECT * INTO STRICT p FROM public.metering_permissions WHERE company_id=c AND id=pid FOR UPDATE;
 IF p.customer_id IS DISTINCT FROM a.customer_id OR NOT EXISTS(SELECT FROM public.ediel_assignment_permission_links l WHERE l.company_id=c AND l.assignment_id=aid AND l.permission_id=pid) THEN RAISE EXCEPTION 'ediel_permission_origin_link_mismatch'; END IF;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment FOR SHARE;
 SELECT min(i.identifier_value) INTO legal_id FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now());
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id FOR SHARE;
 SELECT min(i.identifier_value) INTO dso_id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
 IF (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['provider_legal_identity_ambiguous']); END IF;
 IF nullif(legal_id,'') IS NULL OR nullif(dso_id,'') IS NULL OR (SELECT count(DISTINCT i.identifier_value) FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_unique_legal_sender_and_dso_identity']); END IF;
 SELECT to_jsonb(x) INTO customer_record FROM public.customers x WHERE x.id=a.customer_id AND x.company_id=c FOR SHARE;
 PERFORM x.id FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid FOR SHARE;
 IF code='Z13' THEN
  assessment:=public.ediel_service_assignment_assessment_v1(c,aid);
  IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RETURN assessment; END IF;
  IF (p.status IN ('draft','z13_ready','z13_sent','waiting_for_customer_approval')) IS NOT TRUE OR (p.status IN ('z13_sent','waiting_for_customer_approval') AND p.outbound_z13_message_id IS NULL) OR (p.source_z13_message_id IS NOT NULL AND p.source_z13_message_id IS DISTINCT FROM p.outbound_z13_message_id) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['request_permission_state']); END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now() AND x.permission_purpose_code IS NOT NULL AND nullif(x.permission_reporting_frequency,'') IS NOT NULL ORDER BY x.id LIMIT 1;
  IF NOT FOUND OR (SELECT count(DISTINCT (x.permission_purpose_code,x.permission_reporting_frequency,x.permission_request_grid_area,x.permission_reporting_term_kind,x.permission_customer_classification)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_assessed_permission_reporting_tuple']); END IF;
  IF cardinality(a.product_ids)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['single_source_defined_request_product']); END IF;
  IF nullif(e.permission_request_grid_area,'') IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_defined_request_grid_area']); END IF;
  IF e.permission_reporting_term_kind IS NULL OR e.permission_customer_classification IS NULL OR (e.permission_reporting_term_kind='bounded' AND a.data_end IS NULL) OR (e.permission_reporting_term_kind='indefinite' AND (a.data_end IS NOT NULL OR a.mode='VH')) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_declared_reporting_term_and_customer_classification']); END IF;
  IF date_trunc('minute',a.data_start) IS DISTINCT FROM a.data_start OR date_trunc('minute',a.data_end) IS DISTINCT FROM a.data_end THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_minute_precision_reporting_dates']); END IF;
  objects:=jsonb_build_array(jsonb_build_object('point',NULL,'permissionId',NULL,'product',a.product_ids[1],'gridArea',e.permission_request_grid_area,'reportStart',a.data_start,'reportEnd',a.data_end));
 ELSE
  IF a.status IS DISTINCT FROM 'ended' OR a.mode IS DISTINCT FROM 'V' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['ended_fortlopande_assignment']); END IF;
  IF EXISTS(SELECT FROM public.ediel_assignment_permission_links l JOIN public.ediel_service_assignments other ON other.company_id=l.company_id AND other.id=l.assignment_id WHERE l.company_id=c AND l.permission_id=pid AND other.status='active' AND other.valid_from<=now() AND (other.valid_to IS NULL OR other.valid_to>now())) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['permission_still_required_by_active_assignment']); END IF;
  PERFORM s.id FROM public.metering_permission_sites s WHERE s.company_id=c AND s.metering_permission_id=pid ORDER BY s.id FOR SHARE;
  IF (p.status IN ('active','approved','partially_approved')) IS NOT TRUE OR public.ediel_permission_source_is_current_v1(c,pid,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS NOT TRUE OR gridex_service_administration.permission_matches_assignment_v1(a,p) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_source_approved_permission']); END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='service_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now() AND x.permission_termination_reason IS NOT NULL AND x.permission_termination_at IS NOT NULL ORDER BY x.id LIMIT 1;
  IF NOT FOUND OR (SELECT count(DISTINCT (x.permission_termination_reason,x.permission_termination_at)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='service_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_assessed_permission_termination']); END IF;
  IF p.outbound_z18_message_id IS NOT NULL THEN
   SELECT * INTO previous_origin FROM gridex_service_permission.origins prior WHERE prior.company_id=c AND prior.permission_id=pid AND prior.message_id=p.outbound_z18_message_id AND prior.message_code='Z18';
   IF NOT FOUND OR (NOT(previous_origin.basis->>'evidenceId'=e.id::text AND (previous_origin.basis->>'permissionStateVersion')::bigint=p.market_state_version) AND (p.metadata#>>'{z15,reason}' IS DISTINCT FROM 'Z24' OR p.market_state_version<=(previous_origin.basis->>'permissionStateVersion')::bigint)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['prior_termination_cycle_not_source_cancelled']); END IF;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('point',s.facility_id,'permissionId',s.metadata->>'permissionId','product',s.metadata->>'product','gridArea',s.grid_area_code,'permissionEnd',e.permission_termination_at) ORDER BY s.facility_id,s.id) INTO objects FROM public.metering_permission_sites s WHERE s.company_id=c AND s.metering_permission_id=pid AND s.status IN ('approved','active');
  IF objects IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['approved_permission_objects']); END IF;
  IF date_trunc('minute',e.permission_termination_at) IS DISTINCT FROM e.permission_termination_at THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_minute_precision_termination_date']); END IF;
 END IF;
 RETURN jsonb_build_object('status','authorized','companyId',c,'assignmentId',aid,'assignmentVersion',a.version,'scopeBasisVersion',a.scope_basis_version,'permissionId',pid,'permissionStateVersion',p.market_state_version,'code',code,'environment',a.environment,'providerActorId',a.provider_actor_id,'dsoActorId',a.dso_actor_id,'legalSenderId',legal_id,'legalReceiverId',dso_id,'customerId',a.customer_id,'customer',customer_record,'mode',a.mode,'purposeCode',e.permission_purpose_code,'frequency',e.permission_reporting_frequency,'reportingTerm',e.permission_reporting_term_kind,'customerClassification',e.permission_customer_classification,'terminationReason',e.permission_termination_reason,'evidenceId',e.id,'evidenceSha256',e.source_sha256,'evidenceVersion',e.source_version,'objects',objects,'li',CASE WHEN code='Z18' THEN p.rff_li_reference ELSE NULL END);
END $$;

--
-- Name: context_source_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_source_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;e public.ediel_service_evidence%rowtype;
BEGIN
 basis:=gridex_service_permission.context_source_agreement_v1(c,aid,actor,expected_version,code,pid);
 IF basis->>'status' IS DISTINCT FROM 'authorized' OR code IS DISTINCT FROM 'Z13' THEN RETURN basis;END IF;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=c AND assignment_id=aid AND id=(basis->>'evidenceId')::uuid FOR SHARE;
 IF e.id IS NULL OR e.kind IS DISTINCT FROM 'end_user_contract' OR e.status IS DISTINCT FROM 'verified'
  OR gridex_metering_method_changes.requested_method_supported_v1(e.permission_requested_method) IS NOT TRUE
  OR (SELECT count(DISTINCT (x.permission_purpose_code,x.permission_reporting_frequency,x.permission_request_grid_area,x.permission_reporting_term_kind,x.permission_customer_classification,x.permission_agreement_reference,x.permission_requested_method)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='end_user_contract' AND x.status='verified' AND x.approved_assignment_version=(basis->>'scopeBasisVersion')::bigint AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) AND x.approved_at<=now())<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_source_defined_requested_reporting_method']);END IF;
 RETURN basis||jsonb_build_object('requestedMethod',e.permission_requested_method);
END $$;

--
-- Name: context_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.context_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE timing jsonb;basis jsonb;BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 IF code='Z13' THEN
  timing:=gridex_service_permission.current_request_timing_v1(c,aid,actor,expected_version,true);
  IF timing->>'status' IS DISTINCT FROM 'authorized' OR timing->>'permissionId' IS DISTINCT FROM pid::text THEN RETURN jsonb_build_object('status','held','missing',coalesce(timing->'missing','["immutable_service_request_permission_required"]'::jsonb));END IF;
 END IF;
 basis:=gridex_service_permission.context_before_source_timing_v1(c,aid,actor,expected_version,code,pid);
 IF basis->>'status'='authorized' AND code='Z13' THEN RETURN basis||jsonb_build_object('requestTiming',timing->'proof');END IF;
 RETURN basis;
END $$;

--
-- Name: current_request_timing_v1(uuid, uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.current_request_timing_v1(c uuid, aid uuid, actor uuid, expected_version bigint, require_recorded boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a public.ediel_service_assignments%rowtype;e public.ediel_service_evidence%rowtype;review gridex_ediel_services.reviews%rowtype;recorded gridex_service_permission.request_timing_receipts%rowtype;day date;bounds jsonb;proof jsonb;scope jsonb;BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();PERFORM gridex_service_administration.require_manual_actor_v1(c,actor);
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid;
 IF a.id IS NULL OR a.version IS DISTINCT FROM expected_version OR a.scope_basis_version IS NULL THEN RAISE EXCEPTION 'ediel_assignment_version_stale';END IF;
 IF public.ediel_service_assignment_assessment_v1(c,aid)->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_authentic_service_assignment_evidence_required']);END IF;
 scope:=gridex_service_administration.scope_v1(a);
 SELECT * INTO recorded FROM gridex_service_permission.request_timing_receipts WHERE company_id=c AND assignment_id=aid AND scope_basis_version=a.scope_basis_version;
 IF recorded.assignment_id IS NOT NULL THEN
  IF recorded.scope IS DISTINCT FROM scope THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_service_request_scope_changed']);END IF;
  SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=c AND assignment_id=aid AND id=(recorded.proof->>'evidenceId')::uuid;
  day:=recorded.request_day;
 ELSE
  IF require_recorded THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_service_request_timing_required']);END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='dso_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.permission_network_contract_start IS NOT NULL AND gridex_ediel_services.review_current_v1(x) IS TRUE ORDER BY x.id LIMIT 1;
  IF e.id IS NULL OR (SELECT count(DISTINCT (x.permission_network_contract_start,x.permission_network_contract_end)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='dso_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.permission_network_contract_start IS NOT NULL AND gridex_ediel_services.review_current_v1(x) IS TRUE)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_unique_dso_network_contract_period_required']);END IF;
  day:=(clock_timestamp() AT TIME ZONE 'Europe/Stockholm')::date;
 END IF;
 IF e.id IS NULL OR e.kind IS DISTINCT FROM 'dso_contract' OR e.approved_assignment_version IS DISTINCT FROM a.scope_basis_version OR gridex_ediel_services.review_current_v1(e) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['captured_dso_contract_authority_not_current']);END IF;
 SELECT * INTO review FROM gridex_ediel_services.reviews WHERE company_id=c AND evidence_id=e.id ORDER BY review_sequence DESC LIMIT 1;
 proof:=jsonb_build_object('version',1,'evidenceId',e.id,'sourceHash',e.source_sha256,'sourceReference',e.source_reference,'sourceVersion',e.source_version,'networkStart',e.permission_network_contract_start,'networkEnd',e.permission_network_contract_end,'reviewId',review.id,'reviewerUserId',review.reviewer_user_id,'reviewSequence',review.review_sequence,'scopeBasisVersion',a.scope_basis_version,'requestDay',day);
 IF recorded.assignment_id IS NOT NULL AND recorded.proof IS DISTINCT FROM proof THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_captured_dso_contract_proof_changed']);END IF;
 bounds:=gridex_service_permission.evaluate_request_period_v1(a.mode,a.data_start,a.data_end,day,e.permission_network_contract_start,e.permission_network_contract_end);
 RETURN bounds||jsonb_build_object('proof',proof,'scope',scope,'permissionId',recorded.permission_id);
END $$;

--
-- Name: evaluate_request_period_v1(text, timestamp with time zone, timestamp with time zone, date, date, date); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.evaluate_request_period_v1(mode text, starts timestamp with time zone, ends timestamp with time zone, day date, network_start date, network_end date) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE first_day date;last_day date;earliest date;missing text[]:='{}';BEGIN
 IF mode IS NULL OR mode NOT IN('V','VH') OR day IS NULL OR network_start IS NULL OR NOT isfinite(day) OR NOT isfinite(network_start)
 OR network_end IS NOT NULL AND (NOT isfinite(network_end) OR network_end<network_start) OR starts IS NULL OR NOT isfinite(starts) OR ends IS NOT NULL AND NOT isfinite(ends) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_dso_network_contract_period_required']);END IF;
 first_day:=(starts AT TIME ZONE INTERVAL '01:00')::date;last_day:=(ends AT TIME ZONE INTERVAL '01:00')::date;
 earliest:=greatest((day-interval '3 years')::date,network_start);
 IF first_day<earliest THEN missing:=array_append(missing,'esco_request_start_before_three_year_or_network_contract_bound');END IF;
 IF network_end IS NOT NULL AND (first_day>network_end OR last_day>network_end) THEN missing:=array_append(missing,'esco_request_outside_dso_network_contract_period');END IF;
 IF mode='VH' THEN
  IF last_day IS NULL THEN missing:=array_append(missing,'esco_historical_end_required');END IF;
  IF first_day>=day OR last_day>=day THEN missing:=array_append(missing,'esco_historical_period_must_precede_request_day');END IF;
 ELSE
  IF network_end IS NOT NULL AND network_end<day THEN missing:=array_append(missing,'esco_continuous_dso_contract_not_current');END IF;
  IF first_day>day THEN missing:=array_append(missing,'esco_continuous_start_after_request_day');END IF;
  IF last_day IS NOT NULL AND last_day<=day THEN missing:=array_append(missing,'esco_continuous_end_must_be_future');END IF;
 END IF;
 IF ends IS NOT NULL AND ends<=starts THEN missing:=array_append(missing,'esco_request_period_end_before_start');END IF;
 RETURN jsonb_build_object('status',CASE WHEN cardinality(missing)=0 THEN 'authorized' ELSE 'held' END,'missing',missing,'requestDay',day,'earliestAllowedDate',earliest,'startDate',first_day,'endDate',last_day,'mode',mode,'networkStart',network_start,'networkEnd',network_end);
END $$;

--
-- Name: lock_request_writer_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.lock_request_writer_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 LOCK TABLE auth.users,public.user_profiles,public.companies,public.company_memberships,public.admin_users,
  public.user_roles,public.roles,public.role_permissions,public.permissions,public.user_permissions,public.user_permission_overrides,
  public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles,public.tenant_counterparty_relations,public.platform_actor_identifiers IN SHARE MODE;
 LOCK TABLE public.ediel_service_assignments,public.ediel_service_evidence,public.ediel_data_access_grants,public.ediel_assignment_permission_links,public.metering_permissions,public.metering_permission_sites IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.ediel_ack_transaction_results,public.meter_reading_series,gridex_utilts_binding.receipts,gridex_utilts_binding.contracts,
 gridex_service_administration.scope_versions,gridex_received_sources.permission_transitions,gridex_received_sources.validation_assessments IN SHARE MODE;
 LOCK TABLE gridex_service_administration.commands,gridex_ediel_services.artifacts IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE gridex_ediel_services.issuer_keys,gridex_ediel_services.issuer_representations,gridex_ediel_services.issuer_revocations IN SHARE MODE;
 LOCK TABLE gridex_ediel_services.reviews IN SHARE ROW EXCLUSIVE MODE;
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
END $$;

--
-- Name: origin_immutable_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.origin_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.message_id IS NULL AND NEW.message_id IS NOT NULL AND (to_jsonb(OLD)-'message_id')=(to_jsonb(NEW)-'message_id') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'ediel_permission_origin_immutable';
END $$;

--
-- Name: recovery_operation_before_current_service_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.recovery_operation_before_current_service_v1(p_company_id uuid, p_operation_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;phase text;origin jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id;
 IF op.id IS NULL OR op.kind='verified_transfer_loss' THEN RETURN NULL;END IF;
 PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(p_company_id,op.id);
 phase:=CASE WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) THEN 'send' ELSE 'prepare' END;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,phase);
 origin:=gridex_received_sources.qualified_recovery_origin_v1(p_company_id,op.id);
 RETURN jsonb_build_object('sourceOriginMessageId',origin->>'sourceOriginMessageId','originalMessageId',op.original_message_id,'operationId',op.id,'sourceAckMessageId',op.source_ack_message_id,'kind',op.kind,'correctedPayloadHash',op.corrected_payload_hash,'allowedObjects',gridex_received_sources.prodat_recovery_wire_v1(op.corrected_raw_payload)->'objects');
END$$;

--
-- Name: request_timing_source_v1(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.request_timing_source_v1(c uuid, aid uuid, expected_version bigint, require_recorded boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a public.ediel_service_assignments%rowtype;e public.ediel_service_evidence%rowtype;review gridex_ediel_services.reviews%rowtype;recorded gridex_service_permission.request_timing_receipts%rowtype;day date;bounds jsonb;proof jsonb;scope jsonb;BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=c AND id=aid;
 IF a.id IS NULL OR a.version IS DISTINCT FROM expected_version OR a.scope_basis_version IS NULL THEN RAISE EXCEPTION 'ediel_assignment_version_stale';END IF;
 IF public.ediel_service_assignment_assessment_v1(c,aid)->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_authentic_service_assignment_evidence_required']);END IF;
 scope:=gridex_service_administration.scope_v1(a);
 SELECT * INTO recorded FROM gridex_service_permission.request_timing_receipts WHERE company_id=c AND assignment_id=aid AND scope_basis_version=a.scope_basis_version;
 IF recorded.assignment_id IS NOT NULL THEN
  IF recorded.scope IS DISTINCT FROM scope THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_service_request_scope_changed']);END IF;
  SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=c AND assignment_id=aid AND id=(recorded.proof->>'evidenceId')::uuid;
  day:=recorded.request_day;
 ELSE
  IF require_recorded THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_service_request_timing_required']);END IF;
  SELECT * INTO e FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='dso_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.permission_network_contract_start IS NOT NULL AND gridex_ediel_services.review_current_v1(x) IS TRUE ORDER BY x.id LIMIT 1;
  IF e.id IS NULL OR (SELECT count(DISTINCT (x.permission_network_contract_start,x.permission_network_contract_end)) FROM public.ediel_service_evidence x WHERE x.company_id=c AND x.assignment_id=aid AND x.kind='dso_contract' AND x.status='verified' AND x.approved_assignment_version=a.scope_basis_version AND x.permission_network_contract_start IS NOT NULL AND gridex_ediel_services.review_current_v1(x) IS TRUE)<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_unique_dso_network_contract_period_required']);END IF;
  day:=(clock_timestamp() AT TIME ZONE 'Europe/Stockholm')::date;
 END IF;
 IF e.id IS NULL OR e.kind IS DISTINCT FROM 'dso_contract' OR e.approved_assignment_version IS DISTINCT FROM a.scope_basis_version OR gridex_ediel_services.review_current_v1(e) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['captured_dso_contract_authority_not_current']);END IF;
 SELECT * INTO review FROM gridex_ediel_services.reviews WHERE company_id=c AND evidence_id=e.id ORDER BY review_sequence DESC LIMIT 1;
 proof:=jsonb_build_object('version',1,'evidenceId',e.id,'sourceHash',e.source_sha256,'sourceReference',e.source_reference,'sourceVersion',e.source_version,'networkStart',e.permission_network_contract_start,'networkEnd',e.permission_network_contract_end,'reviewId',review.id,'reviewerUserId',review.reviewer_user_id,'reviewSequence',review.review_sequence,'scopeBasisVersion',a.scope_basis_version,'requestDay',day);
 IF recorded.assignment_id IS NOT NULL AND recorded.proof IS DISTINCT FROM proof THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_captured_dso_contract_proof_changed']);END IF;
 bounds:=gridex_service_permission.evaluate_request_period_v1(a.mode,a.data_start,a.data_end,day,e.permission_network_contract_start,e.permission_network_contract_end);
 RETURN bounds||jsonb_build_object('proof',proof,'scope',scope,'permissionId',recorded.permission_id);
END $$;

--
-- Name: require_agreement_reference_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_agreement_reference_v1(m public.ediel_messages, basis jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb;
BEGIN
 IF m.message_code IS DISTINCT FROM 'Z13' THEN RETURN;END IF;
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(m.raw_payload,999999);
 IF tokens IS NULL OR nullif(basis->>'agreementReference','') IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ANJ')<>1
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ANJ' AND t#>>'{elements,1,1}'=basis->>'agreementReference') THEN RAISE EXCEPTION 'ediel_permission_authentic_agreement_reference_required';END IF;
END $$;

--
-- Name: require_current_before_agreement_reference_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_current_before_agreement_reference_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE operation_actor uuid;qualified jsonb;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL THEN RAISE EXCEPTION 'ediel_service_permission_scope_required';END IF;
 -- Preserve original service-message authorization. Ordinary messages without
 -- service origins remain under their own authorities.
 PERFORM gridex_service_permission.require_original_current_v1(p_company_id,p_message_id);
 SELECT operation.actor_user_id INTO operation_actor
 FROM gridex_received_sources.prodat_recovery_messages link
 JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id
 WHERE link.message_id=p_message_id AND operation.company_id=p_company_id;
 IF NOT FOUND THEN RETURN;END IF;
 qualified:=public.ediel_prodat_recovery_original_basis_v1(p_company_id,p_message_id,operation_actor);
 IF qualified IS NULL OR nullif(qualified->>'originalMessageId','') IS NULL OR qualified->>'originalMessageId'=p_message_id::text THEN RAISE EXCEPTION 'ediel_service_recovery_original_unqualified';END IF;
 -- The operation reader above independently checks this same original; no
 -- recursion through a new intent, editable source-id or metadata is used.
 PERFORM gridex_service_permission.require_original_current_v1(p_company_id,(qualified->>'originalMessageId')::uuid);
END $$;

--
-- Name: require_current_before_requested_method_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_current_before_requested_method_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;basis jsonb;
BEGIN
 PERFORM gridex_service_permission.require_current_before_agreement_reference_v1(p_company_id,p_message_id);
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 SELECT own.basis INTO basis FROM gridex_service_permission.origins own WHERE own.message_id=m.id AND own.company_id=p_company_id;
 IF basis IS NULL THEN
  -- The preceding existing current-source recovery authority independently
  -- qualified this same private operation/message/hash/original relation.
  SELECT own.basis INTO basis FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations op ON op.id=link.operation_id JOIN gridex_service_permission.origins own ON own.message_id=op.original_message_id AND own.company_id=op.company_id WHERE link.message_id=m.id AND op.company_id=p_company_id;
 END IF;
 IF basis IS NOT NULL THEN PERFORM gridex_service_permission.require_agreement_reference_v1(m,basis);END IF;
END $$;

--
-- Name: require_original_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_original_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s gridex_service_permission.origins%rowtype; b jsonb;
BEGIN
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RETURN; END IF;
 b:=gridex_service_permission.context_v1(s.company_id,s.assignment_id,s.actor_user_id,(s.basis->>'assignmentVersion')::bigint,s.message_code,s.permission_id);
 PERFORM 1 FROM gridex_service_permission.origins WHERE intent_id=s.intent_id AND message_id=p_message_id FOR SHARE;
 IF b IS DISTINCT FROM s.basis OR b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_permission_origin_basis_stale'; END IF;
END $$;

--
-- Name: require_original_source_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_original_source_current_v1(c uuid, message uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE timing jsonb;s gridex_service_permission.origins%rowtype;current_source gridex_service_permission.origins%rowtype;b jsonb;m public.ediel_messages%rowtype;
BEGIN
 IF c IS NULL OR message IS NULL THEN RAISE EXCEPTION 'ediel_service_permission_scope_required';END IF;
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=c AND message_id=message;
 IF s.message_id IS NULL THEN RETURN;END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=c AND id=message FOR UPDATE;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM s.message_code OR m.intent_id IS DISTINCT FROM s.intent_id OR m.environment IS DISTINCT FROM s.basis->>'environment'
  OR m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ediel_permission_origin_source_message_changed';END IF;
 b:=gridex_service_permission.context_source_v1(s.company_id,s.assignment_id,s.actor_user_id,(s.basis->>'assignmentVersion')::bigint,s.message_code,s.permission_id);
 SELECT * INTO current_source FROM gridex_service_permission.origins WHERE company_id=c AND message_id=message FOR SHARE;
 IF s.message_code='Z13' THEN timing:=gridex_service_permission.request_timing_source_v1(s.company_id,s.assignment_id,(s.basis->>'assignmentVersion')::bigint,true); IF timing->>'status' IS DISTINCT FROM 'authorized' OR timing->>'permissionId' IS DISTINCT FROM s.permission_id::text OR s.basis->'requestTiming' IS DISTINCT FROM timing->'proof' THEN RAISE EXCEPTION 'ediel_permission_origin_basis_stale';END IF; b:=b||jsonb_build_object('requestTiming',timing->'proof');END IF;
 IF current_source IS DISTINCT FROM s OR b IS DISTINCT FROM s.basis OR b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_permission_origin_basis_stale';END IF;
 PERFORM gridex_service_permission.require_agreement_reference_v1(m,b);
 PERFORM gridex_service_permission.require_requested_method_v1(m,b);
END$$;

--
-- Name: require_requested_method_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.require_requested_method_v1(m public.ediel_messages, basis jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb;t jsonb;attribute text;method text;objects integer:=0;inside boolean:=false;
BEGIN
 IF m.message_code IS DISTINCT FROM 'Z13' THEN RETURN;END IF;
 IF jsonb_typeof(basis->'objects') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
 IF jsonb_array_length(basis->'objects')=0 THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
 tokens:=gridex_received_sources.wire_tokens_bounded_v1(m.raw_payload,999999);
 IF tokens IS NULL OR gridex_metering_method_changes.requested_method_supported_v1(basis->>'requestedMethod') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(tokens) LOOP
  IF t->>'tag'='LIN' THEN
   IF inside AND method IS DISTINCT FROM basis->>'requestedMethod' THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
   inside:=true;objects:=objects+1;attribute:=NULL;method:=NULL;
  ELSIF inside AND t->>'tag'='CCI' THEN attribute:=t#>>'{elements,2,0}';
  ELSIF inside AND t->>'tag'='CAV' AND attribute='Z04' THEN
   IF method IS NOT NULL THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
   method:=t#>>'{elements,1,0}';attribute:=NULL;
  END IF;
 END LOOP;
 IF NOT inside OR method IS DISTINCT FROM basis->>'requestedMethod' OR objects<>jsonb_array_length(basis->'objects') THEN RAISE EXCEPTION 'ediel_permission_authentic_requested_method_required';END IF;
END $$;

--
-- Name: reserve_v1(uuid, uuid, uuid, bigint, text, uuid, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.reserve_v1(c uuid, aid uuid, actor uuid, expected_version bigint, code text, pid uuid, iid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b jsonb; i public.ediel_message_intents%rowtype; saved gridex_service_permission.origins%rowtype; v_command_key text;
BEGIN
 b:=gridex_service_permission.context_v1(c,aid,actor,expected_version,code,pid);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b; END IF;
 SELECT * INTO STRICT i FROM public.ediel_message_intents WHERE id=iid AND company_id=c FOR SHARE;
 IF i.business_process IS DISTINCT FROM 'metering_permission' OR i.environment IS DISTINCT FROM b->>'environment' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM code OR i.customer_id IS DISTINCT FROM (b->>'customerId')::uuid OR i.payload->'sourcePermissionBasis' IS DISTINCT FROM b THEN RAISE EXCEPTION 'ediel_permission_origin_intent_mismatch'; END IF;
 v_command_key:=CASE WHEN code='Z13' THEN 'original' ELSE (b->>'evidenceId')||':'||(b->>'permissionStateVersion') END;
 INSERT INTO gridex_service_permission.origins(intent_id,company_id,assignment_id,permission_id,actor_user_id,message_code,command_key,basis) VALUES(iid,c,aid,pid,actor,code,v_command_key,b) ON CONFLICT(company_id,permission_id,message_code,command_key) DO NOTHING;
 SELECT * INTO STRICT saved FROM gridex_service_permission.origins WHERE company_id=c AND permission_id=pid AND message_code=code AND origins.command_key=v_command_key FOR UPDATE;
 IF saved.intent_id IS DISTINCT FROM iid OR saved.basis IS DISTINCT FROM b THEN RAISE EXCEPTION 'ediel_permission_origin_frozen_basis_conflict'; END IF;
 RETURN jsonb_build_object('status','reserved','messageId',saved.message_id);
END $$;

--
-- Name: resolve_before_request_timing_v1(uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.resolve_before_request_timing_v1(p_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_permission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a public.ediel_service_assignments%rowtype;p public.metering_permissions%rowtype;owner public.ediel_service_assignments%rowtype;owner_id uuid;owner_scope bigint;owner_snapshot jsonb;assessment jsonb;original uuid;original_row public.ediel_messages%rowtype;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_service_administration.require_manual_actor_v1(p_company_id,p_actor_user_id);
 IF p_assignment_id IS NULL OR p_permission_id IS NULL OR p_expected_version IS NULL OR p_expected_version<1 THEN RAISE EXCEPTION 'ediel_service_permission_command_scope_required';END IF;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=p_assignment_id;
 -- Discover only an immutable origin; lock its actual source before assignments
 -- and permission rows, matching the provider's source-before-projection order.
 SELECT o.message_id INTO original FROM gridex_service_permission.origins o WHERE o.company_id=p_company_id AND o.permission_id=p_permission_id AND o.message_code='Z13';
 IF original IS NOT NULL THEN SELECT * INTO original_row FROM public.ediel_messages WHERE company_id=p_company_id AND id=original FOR SHARE;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
 IF (SELECT o.message_id FROM gridex_service_permission.origins o WHERE o.company_id=p_company_id AND o.permission_id=p_permission_id AND o.message_code='Z13') IS DISTINCT FROM original THEN RETURN jsonb_build_object('status','held','missing',ARRAY['permission_original_changed_retry_required']);END IF;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=p_assignment_id FOR SHARE;
 IF a.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'ediel_assignment_version_stale';END IF;
 assessment:=public.ediel_service_assignment_assessment_v1(a.company_id,a.id);
 IF assessment->>'status' IS DISTINCT FROM 'authorized' THEN RETURN assessment;END IF;
 SELECT * INTO STRICT p FROM public.metering_permissions WHERE company_id=p_company_id AND id=p_permission_id FOR SHARE;
 IF p.customer_id IS DISTINCT FROM a.customer_id OR NOT EXISTS(SELECT FROM public.ediel_assignment_permission_links l WHERE l.company_id=a.company_id AND l.assignment_id=a.id AND l.permission_id=p.id) THEN RAISE EXCEPTION 'ediel_service_manual_permission_not_linked';END IF;
 PERFORM s.id FROM public.metering_permission_sites s WHERE s.company_id=a.company_id AND s.metering_permission_id=p.id ORDER BY s.id FOR SHARE;
 IF p.status IN ('active','approved','partially_approved','z14_received') THEN
  IF gridex_service_administration.permission_matches_assignment_v1(a,p) IS NOT TRUE
   OR EXISTS(SELECT FROM unnest(a.object_ids) object_id CROSS JOIN unnest(a.product_ids) product_id WHERE NOT EXISTS(SELECT FROM public.metering_permission_sites s WHERE s.company_id=a.company_id AND s.metering_permission_id=p.id AND s.customer_id=a.customer_id AND s.facility_id=object_id AND s.status IN('approved','active') AND s.metadata->>'source'='inbound_prodat_z14' AND s.metadata->>'edielMessageId'=coalesce(p.inbound_z14_message_id,p.source_z14_message_id)::text AND s.metadata->>'mode'=CASE a.mode WHEN 'V' THEN 'S17' ELSE 'S18' END AND s.metadata->>'product'=product_id AND s.start_at IS NOT NULL AND a.data_start>=s.start_at AND (s.end_at IS NULL OR (a.data_end IS NOT NULL AND a.data_end<=s.end_at)) AND (s.permission_end_at IS NULL OR s.permission_end_at>now())))
   THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_source_approved_compatible_permission']);END IF;
  RETURN jsonb_build_object('status','reuse_permission','permissionId',p.id,'marketPermissionState','approved','accessGranted',false);
 END IF;
 IF (p.status IN('draft','z13_ready','z13_sent','waiting_for_customer_approval')) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_permission_request_state']);END IF;
 SELECT r.assignment_id,r.scope_basis_version,r.scope INTO owner_id,owner_scope,owner_snapshot FROM gridex_service_administration.permission_request_owners r WHERE r.company_id=a.company_id AND r.permission_id=p.id;
 IF owner_id IS NULL THEN
  -- An existing genuinely reserved/bound source origin is a retained owner.
  -- A parsed metadata assignment_id or today's sole link is not historical proof.
  SELECT o.assignment_id,(o.basis->>'scopeBasisVersion')::bigint,o.message_id INTO owner_id,owner_scope,original FROM gridex_service_permission.origins o WHERE o.company_id=a.company_id AND o.permission_id=p.id AND o.message_code='Z13';
 ELSE
  SELECT o.message_id INTO original FROM gridex_service_permission.origins o WHERE o.company_id=a.company_id AND o.permission_id=p.id AND o.message_code='Z13';
 END IF;
 IF owner_id IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['prospective_or_original_permission_request_owner']);END IF;
 SELECT * INTO owner FROM public.ediel_service_assignments WHERE company_id=a.company_id AND id=owner_id FOR SHARE;
 IF NOT FOUND OR owner.scope_basis_version IS DISTINCT FROM owner_scope OR (owner_snapshot IS NOT NULL AND gridex_service_administration.scope_v1(owner) IS DISTINCT FROM owner_snapshot)
  OR owner.environment IS DISTINCT FROM a.environment OR owner.provider_actor_id IS DISTINCT FROM a.provider_actor_id OR owner.customer_id IS DISTINCT FROM a.customer_id OR owner.dso_actor_id IS DISTINCT FROM a.dso_actor_id OR owner.mode IS DISTINCT FROM a.mode OR owner.purpose IS DISTINCT FROM a.purpose
  OR NOT(a.object_ids<@owner.object_ids AND a.product_ids<@owner.product_ids AND a.field_sets<@owner.field_sets) OR a.data_start<owner.data_start OR (owner.data_end IS NOT NULL AND (a.data_end IS NULL OR a.data_end>owner.data_end)) OR public.ediel_service_assignment_assessment_v1(a.company_id,owner.id)->>'status' IS DISTINCT FROM 'authorized'
  THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_compatible_permission_request_owner']);END IF;
 IF p.outbound_z13_message_id IS NOT NULL OR p.source_z13_message_id IS NOT NULL THEN
  IF original IS NULL OR p.outbound_z13_message_id IS DISTINCT FROM original OR p.source_z13_message_id IS DISTINCT FROM original OR original_row.id IS DISTINCT FROM original OR original_row.company_id IS DISTINCT FROM a.company_id OR original_row.environment IS DISTINCT FROM a.environment OR original_row.direction IS DISTINCT FROM 'outbound' OR original_row.message_family IS DISTINCT FROM 'PRODAT' OR original_row.message_code IS DISTINCT FROM 'Z13' OR original_row.customer_id IS DISTINCT FROM a.customer_id OR NOT EXISTS(SELECT FROM gridex_service_permission.origins o WHERE o.company_id=a.company_id AND o.permission_id=p.id AND o.assignment_id=owner.id AND o.message_id=original_row.id AND o.intent_id=original_row.intent_id AND o.message_code='Z13') THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_owned_pending_permission_original']);END IF;
  -- This sole canonical owner compares the saved bytes to the prospective
  -- immutable witness. It does not select a new rule or alter the old original.
  PERFORM gridex_ediel_outbound_owner.require_v1(a.company_id,original);
  IF original_row.status='draft' AND owner.id=a.id THEN
   -- Only the exact first owner's bound draft can resume the canonical gateway
   -- after a pre-queue crash. A different beneficiary never queues that request.
   PERFORM r.id FROM public.outbound_requests r WHERE r.company_id=a.company_id AND r.id=original_row.outbound_request_id FOR SHARE;
   IF original_row.outbound_request_id IS NULL OR NOT EXISTS(SELECT FROM public.outbound_requests r WHERE r.company_id=a.company_id AND r.id=original_row.outbound_request_id AND r.customer_id=a.customer_id AND r.source_type='manual' AND r.source_id=original_row.intent_id AND r.request_type='metering_access' AND r.operation_id=p.id AND r.payload->>'servicePermissionCommandKey'=original_row.intent_id::text AND r.payload->>'environment'=a.environment) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['owned_bound_first_draft_request']);END IF;
   RETURN jsonb_build_object('status','permission_required','permissionId',p.id,'messageId',original,'intentId',original_row.intent_id,'outboundRequestId',original_row.outbound_request_id);
  END IF;
  RETURN jsonb_build_object('status','reuse_permission','permissionId',p.id,'marketPermissionState','pending','messageId',original,'accessGranted',false);
 END IF;
 IF owner.id IS DISTINCT FROM a.id THEN RETURN jsonb_build_object('status','reuse_permission','permissionId',p.id,'marketPermissionState','pending','accessGranted',false);END IF;
 RETURN jsonb_build_object('status','permission_required','permissionId',p.id);
END $$;

--
-- Name: wait_after_z13_ack_v1(); Type: FUNCTION; Schema: gridex_service_permission; Owner: -
--

CREATE FUNCTION gridex_service_permission.wait_after_z13_ack_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
 c gridex_ack_authority.source_correlations%rowtype;
 a gridex_ack_authority.source_correlations%rowtype;
 s public.ediel_messages%rowtype;
 p public.metering_permissions%rowtype;
 o gridex_service_permission.origins%rowtype;
 wire jsonb; original jsonb; expected jsonb; proof jsonb; ack_raw text;
 positive_aperaks uuid[]:=ARRAY[]::uuid[]; positive_contrl boolean:=false;
BEGIN
 IF NEW.result->'sourceAccepted' IS DISTINCT FROM 'true'::jsonb
  OR NEW.result->'finalAckReached' IS DISTINCT FROM 'true'::jsonb
  OR NEW.result->'wholeSourceRejected' IS DISTINCT FROM 'false'::jsonb THEN RETURN NEW; END IF;
 SELECT * INTO STRICT c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=NEW.ack_message_id;
 -- Most ACKs have no service-permission origin. Do not impose new permission
 -- locks or business authority on those unrelated source families.
 SELECT * INTO o FROM gridex_service_permission.origins
  WHERE message_id=c.source_message_id AND company_id=c.company_id AND message_code='Z13';
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO s FROM public.ediel_messages WHERE id=c.source_message_id FOR UPDATE;
 IF s.company_id IS DISTINCT FROM c.company_id OR s.environment IS DISTINCT FROM c.environment
  OR s.direction IS DISTINCT FROM 'outbound' OR s.message_family IS DISTINCT FROM 'PRODAT'
  OR s.message_code IS DISTINCT FROM 'Z13' OR s.intent_id IS DISTINCT FROM o.intent_id THEN RETURN NEW; END IF;
 IF s.message_sent_at IS NULL OR s.immutable_rendered_at IS NULL
  OR s.immutable_payload_hash IS DISTINCT FROM c.source_payload_hash
  OR c.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  OR NEW.result#>>'{sourceMessage,id}' IS DISTINCT FROM s.id::text
  OR NEW.result#>>'{sourceMessage,company_id}' IS DISTINCT FROM c.company_id::text
  OR NEW.result#>>'{sourceMessage,environment}' IS DISTINCT FROM c.environment
  OR NEW.result#>>'{sourceMessage,raw_payload}' IS DISTINCT FROM s.raw_payload THEN
  RAISE EXCEPTION 'ediel_z13_waiting_source_receipt_conflict' USING ERRCODE='23514';
 END IF;
 -- A distinct later ACK must not repair an aggregate already completed before
 -- this migration. Earlier *partial* receipts can still complete prospectively.
 IF EXISTS(SELECT FROM gridex_ack_authority.applied_receipts r
  JOIN gridex_ack_authority.source_correlations prior USING(ack_message_id)
  WHERE prior.source_message_id=s.id AND r.ack_message_id<>NEW.ack_message_id
   AND r.result->'sourceAccepted'='true'::jsonb AND r.result->'finalAckReached'='true'::jsonb)
 THEN RETURN NEW; END IF;
 wire:=gridex_ack_authority.wire_v1(s.raw_payload);
 IF wire->>'family' IS DISTINCT FROM 'PRODAT' OR wire->>'code' IS DISTINCT FROM 'Z13'
  OR wire->>'environment' IS DISTINCT FROM c.environment THEN RETURN NEW; END IF;
 PERFORM gridex_ack_authority.require_physical_actor_v1(c.company_id,c.actor_user_id,true);
 proof:=gridex_ack_authority.read_committed_v1(c.company_id,c.environment,c.ack_message_id,c.actor_user_id);
 IF proof->>'kind' IS DISTINCT FROM 'exact_receipt' OR proof->'result' IS DISTINCT FROM NEW.result THEN
  RAISE EXCEPTION 'ediel_z13_waiting_committed_receipt_required' USING ERRCODE='23514'; END IF;
 expected:=gridex_ack_authority.prodat_expected_physical_scope_keys_v1(s.raw_payload,s.id);
 IF jsonb_typeof(expected) IS DISTINCT FROM 'array' OR jsonb_array_length(expected)=0
  OR EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=s.id AND x.outcome='negative')
 THEN RETURN NEW; END IF;
 -- The final ACK may be CONTRL arriving after APERAK. Qualify that earlier
 -- APERAK's immutable canonical receipt and physical scopes as well. The outer
 -- owner writes its physical receipt AFTER applied_receipts; do not demand it
 -- prematurely for the current APERAK. Recompute the same actual projection.
 FOR a IN SELECT * FROM gridex_ack_authority.source_correlations
  WHERE source_message_id=s.id AND company_id=c.company_id AND environment=c.environment
   AND source_payload_hash=c.source_payload_hash AND ack_outcome='positive'
   AND ack_family IN('CONTRL','APERAK') ORDER BY ack_message_id LOOP
  proof:=gridex_ack_authority.read_committed_v1(c.company_id,c.environment,a.ack_message_id,c.actor_user_id);
  IF proof->>'kind' IS DISTINCT FROM 'exact_receipt' THEN CONTINUE; END IF;
  IF a.ack_family='CONTRL' AND a.ack_scope='interchange'
   AND EXISTS(SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=s.id
    AND x.ack_message_id=a.ack_message_id AND x.ack_family='CONTRL' AND x.ack_scope='interchange' AND x.outcome='positive')
  THEN positive_contrl:=true;
  ELSIF a.ack_family='APERAK' AND a.ack_scope='object' THEN
   SELECT raw_payload INTO STRICT ack_raw FROM public.ediel_messages WHERE id=a.ack_message_id;
   IF a.scope_outcomes IS DISTINCT FROM gridex_ack_authority.prodat_physical_outcomes_v1(ack_raw,s.raw_payload,s.id)
   THEN RAISE EXCEPTION 'ediel_z13_waiting_physical_scope_conflict' USING ERRCODE='23514'; END IF;
   positive_aperaks:=array_append(positive_aperaks,a.ack_message_id);
  END IF;
 END LOOP;
 IF NOT positive_contrl OR cardinality(positive_aperaks)=0
  OR EXISTS(SELECT FROM jsonb_array_elements_text(expected) ref WHERE NOT EXISTS(
   SELECT FROM gridex_ack_authority.scope_outcomes x WHERE x.source_message_id=s.id
    AND x.ack_family='APERAK' AND x.ack_scope='object' AND x.source_reference=ref
    AND x.ack_message_id=ANY(positive_aperaks) AND x.outcome='positive')) THEN RETURN NEW; END IF;
 -- The current graph owner already holds SHARE on this table before locking
 -- messages. A blocking upgrade here can deadlock with another ACK waiting on
 -- messages. NOWAIT deliberately propagates 55P03: the ENTIRE ACK transaction
 -- rolls back and can retry; never commit acceptance with a skipped projection.
 LOCK TABLE public.metering_permissions IN ROW EXCLUSIVE MODE NOWAIT;
 SELECT * INTO p FROM public.metering_permissions WHERE id=o.permission_id AND company_id=c.company_id FOR UPDATE;
 original:=gridex_received_sources.permission_partition_wire_v1(s.raw_payload);
 IF NOT FOUND OR (p.status IN('z13_ready','z13_sent')) IS NOT TRUE
  OR p.source_z13_message_id IS DISTINCT FROM s.id OR p.outbound_z13_message_id IS DISTINCT FROM s.id
  OR s.customer_id IS NULL OR p.customer_id IS DISTINCT FROM s.customer_id
  OR o.basis->>'customerId' IS DISTINCT FROM p.customer_id::text
  OR nullif(btrim(p.rff_li_reference),'') IS NULL
  OR jsonb_typeof(original->'objects') IS DISTINCT FROM 'array'
  OR (SELECT count(*) FROM jsonb_array_elements(original->'objects') x WHERE x->>'li'=p.rff_li_reference)<>1
  OR nullif(p.grid_owner_ediel_id,'') IS NULL OR p.grid_owner_ediel_id IS DISTINCT FROM original->>'receiver'
  OR p.source_z14_message_id IS NOT NULL OR p.inbound_z14_message_id IS NOT NULL OR p.inbound_z15_message_id IS NOT NULL
  OR p.market_state_version IS DISTINCT FROM 0::bigint OR p.permission_reference IS NOT NULL
  OR p.approved_start_date IS NOT NULL OR p.approved_end_date IS NOT NULL
  OR p.approved_start_at IS NOT NULL OR p.approved_end_at IS NOT NULL
  OR coalesce(p.metadata,'{}'::jsonb) ?| ARRAY['marketPermission','z14','z15'] THEN RETURN NEW; END IF;
 UPDATE public.metering_permissions SET status='waiting_for_customer_approval',updated_at=now(),updated_by=c.actor_user_id
  WHERE id=p.id AND company_id=c.company_id;
 RETURN NEW;
END $$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.actor_v1(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN mode IN('archive','read','review') AND gridex_supply_rescission.execution_actor_active_v1(c,actor) IS TRUE
 AND gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'contracts.read') IS TRUE
 AND gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,CASE mode WHEN 'read' THEN 'metering.read' ELSE 'metering.write' END) IS TRUE
 AND(mode<>'review' OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'ediel.supply_rescission.review') IS TRUE);
END$$;

--
-- Name: apply_supply_before_rescission_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.apply_supply_before_rescission_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;w jsonb;own jsonb;binding jsonb;plans jsonb:='[]';r jsonb;prior boolean;BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NOT NULL THEN PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);END IF;w:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF m.direction='inbound' AND m.message_family='PRODAT' AND w->>'code'='Z05' AND EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason'='Z23') THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE (o->>'reason' IN('Z22','Z23')) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','bilateral_closure_whole_scope_required');END IF;
  prior:=EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id AND company_id=m.company_id);
  IF prior THEN IF gridex_bilateral_prodat.recorded_closure_end_current_v1(m.company_id,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_closure_recorded_current_profile_required';END IF;
  ELSE FOR own IN SELECT o FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason'='Z23' LOOP binding:=gridex_bilateral_prodat.matched_closure_operation_v1(m,w,own);IF binding IS NULL THEN RAISE EXCEPTION 'bilateral_closure_exact_sent_original_required';END IF;plans:=plans||jsonb_build_array(jsonb_build_object('object',own,'binding',binding));END LOOP;END IF;
  r:=gridex_bilateral_prodat.confirm_closure_end_v1(p_company_id,p_source_message_id,p_actor_user_id);IF r->>'applied'='true' AND NOT prior THEN PERFORM gridex_bilateral_prodat.record_closure_end_v1(m,plans);END IF;RETURN r;
 END IF;RETURN gridex_bilateral_prodat.apply_supply_before_closure_v1(p_company_id,p_source_message_id,p_actor_user_id);
END$$;

--
-- Name: calendar_cutoff_v1(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.calendar_cutoff_v1(effective timestamp with time zone, observed timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT effective IS NOT NULL AND observed IS NOT NULL AND isfinite(effective) AND isfinite(observed) AND ((observed AT TIME ZONE 'UTC')+interval '1 hour')::date<=((effective AT TIME ZONE 'UTC')+interval '1 hour')::date
$$;

--
-- Name: confirm_end_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.confirm_end_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 PERFORM gridex_supply_rescission.lock_original_v1();
 PERFORM gridex_bilateral_prodat.lock_closure_v1();
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);
 END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  reason:=own->>'reason';
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.supply_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'sender' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'receiver'
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23','Z25') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations confirmation WHERE confirmation.period_id=p.id AND confirmation.company_id=p.company_id AND confirmation.source_message_id=p.source_message_id AND confirmation.source_object->>'point'=own->>'point' AND confirmation.source_object->>'identityAgency'=own->>'identityAgency' AND confirmation.source_object->>'customerIdentity'=own->>'customerIdentity' AND confirmation.source_object->>'gridArea'=own->>'gridArea' AND confirmation.market_start_at<event_at AND gridex_received_sources.supply_period_source_basis_v1(p.company_id,p.id,event_at-interval '1 minute',event_at) IS NOT NULL) OR
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text)
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND object->>'reason' IN ('Z26','Z70')))
    );
   IF own->>'reason'='Z23' THEN PERFORM gridex_bilateral_prodat.require_matched_closure_v1(m,wire,own);ids:=ARRAY[(gridex_bilateral_prodat.matched_closure_operation_v1(m,wire,own)->>'periodId')::uuid];END IF;
   IF gridex_supply_rescission.has_end_selector_v1(m,own) IS TRUE THEN PERFORM gridex_supply_rescission.require_matched_end_v1(m,wire,own);ids:=ARRAY[(gridex_supply_rescission.matched_end_v1(m,wire,own)->>'periodId')::uuid];END IF;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (planned->>'periodId')::uuid FROM jsonb_array_elements(plans) planned);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),wire->>'code',wire->'objects',before_states,after_states,ARRAY(SELECT (planned->>'switchId')::uuid FROM jsonb_array_elements(plans) planned WHERE planned->>'kind'='cancel_start'),p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'periods',after_states,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;

--
-- Name: end_watch_applied_v1(); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.end_watch_applied_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE e uuid;BEGIN
 FOR e IN SELECT expectation_id FROM gridex_business_expectations.bindings WHERE company_id=NEW.company_id AND environment=NEW.environment AND source_message_id=NEW.original_message_id ORDER BY expectation_id LOOP PERFORM gridex_business_expectations.reconcile_v1(e);END LOOP;RETURN NEW;
END$$;

--
-- Name: execution_actor_active_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.execution_actor_active_v1(c uuid, actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_supply_rescission.lock_v1();
 RETURN actor IS NOT NULL AND EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND(banned_until IS NULL OR banned_until<=clock_timestamp()))
 AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL);
END$$;

--
-- Name: guard_original_v1(); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.guard_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM gridex_supply_rescission.require_original_v1(NEW,TG_OP='INSERT');RETURN NEW;END$$;

--
-- Name: has_end_selector_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.has_end_selector_v1(m public.ediel_messages, own jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT own->>'reason'='Z22' AND EXISTS(SELECT FROM gridex_supply_rescission.mandates legal WHERE legal.company_id=m.company_id AND legal.environment=m.environment AND 'H'||replace(legal.id::text,'-','')=own->>'li' AND legal.scope->>'externalPoint'=own->>'point' AND legal.scope->>'identityAgency'=own->>'identityAgency');$$;

--
-- Name: lock_original_v1(); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.lock_original_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_supply_rescission.lock_v1();PERFORM gridex_bilateral_prodat.lock_closure_v1();
 LOCK TABLE gridex_supply_rescission.outbound_operations,gridex_supply_rescission.outbound_receipts,gridex_supply_rescission.end_receipts IN SHARE ROW EXCLUSIVE MODE;
END$$;

--
-- Name: lock_v1(); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.lock_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE gridex_supply_rescission.artifacts,gridex_supply_rescission.issuer_keys,gridex_supply_rescission.issuer_representations,gridex_supply_rescission.issuer_revocations,gridex_supply_rescission.reviews,gridex_supply_rescission.mandates IN SHARE ROW EXCLUSIVE MODE;
END$$;

--
-- Name: mandate_current_v1(uuid, uuid, boolean); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.mandate_current_v1(c uuid, mandate uuid, fresh boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m gridex_supply_rescission.mandates%rowtype;a gridex_supply_rescission.artifacts%rowtype;r gridex_supply_rescission.reviews%rowtype;current_scope jsonb;BEGIN
 PERFORM gridex_supply_rescission.lock_v1();SELECT * INTO m FROM gridex_supply_rescission.mandates WHERE id=mandate AND company_id=c;SELECT * INTO a FROM gridex_supply_rescission.artifacts WHERE id=m.artifact_id AND company_id=c;SELECT * INTO r FROM gridex_supply_rescission.reviews WHERE id=m.review_id AND artifact_id=a.id AND company_id=c;
 IF m.id IS NULL OR a.id IS NULL OR r.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_supply_rescission.actor_v1(c,a.submitted_by,'archive') IS NOT TRUE OR gridex_supply_rescission.actor_v1(c,r.reviewer_user_id,'review') IS NOT TRUE OR gridex_supply_rescission.receipt_current_v1(a) IS NOT TRUE OR m.source_hash IS DISTINCT FROM a.source_hash OR m.scope IS DISTINCT FROM a.scope THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=m.environment AND market='electricity' AND is_enabled AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to)) OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=m.environment AND actor_id::text=m.scope->>'legalActorId' AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to)) OR (SELECT count(DISTINCT(company_id,actor_id)) FROM public.tenant_actor_identifiers WHERE environment=m.environment AND identifier_type='EdielId' AND identifier_value=m.scope->>'legalSenderId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to))<>1 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=m.environment AND actor_id::text=m.scope->>'legalActorId' AND identifier_type='EdielId' AND identifier_value=m.scope->>'legalSenderId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to)) OR (SELECT count(DISTINCT actor_id) FROM public.platform_actor_identifiers WHERE identifier_value=m.scope->>'legalReceiverId' AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND(valid_from IS NULL OR valid_from<=(clock_timestamp()::date)) AND(valid_to IS NULL OR (clock_timestamp()::date)<=valid_to))<>1 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers WHERE actor_id::text=m.scope->>'dsoActorId' AND identifier_value=m.scope->>'legalReceiverId' AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND(valid_from IS NULL OR valid_from<=(clock_timestamp()::date)) AND(valid_to IS NULL OR (clock_timestamp()::date)<=valid_to)) OR NOT EXISTS(SELECT FROM public.customer_contracts contract WHERE contract.id::text=m.scope->>'contractId' AND contract.company_id=c AND contract.customer_id::text=m.scope->>'customerId' AND contract.metering_point_id::text=m.scope->>'pointId' AND gridex_received_sources.production_contract_hash_v1(contract)=m.scope->>'contractHash') THEN RETURN false;END IF;
 IF fresh THEN current_scope:=gridex_supply_rescission.scope_v1(c,a.selector);IF current_scope IS DISTINCT FROM m.scope OR gridex_supply_rescission.calendar_cutoff_v1((m.scope->>'effectiveAt')::timestamptz,clock_timestamp()) IS NOT TRUE THEN RETURN false;END IF;END IF;
 RETURN true;
END$$;

--
-- Name: matched_end_v1(public.ediel_messages, jsonb, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.matched_end_v1(m public.ediel_messages, w jsonb, own jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE ids uuid[];z public.ediel_messages%rowtype;o gridex_supply_rescission.outbound_operations%rowtype;legal gridex_supply_rescission.mandates%rowtype;ow jsonb;p public.customer_supply_periods%rowtype;BEGIN
 IF w IS DISTINCT FROM gridex_received_sources.normal_switch_wire_v1(m.raw_payload) OR w->>'code' IS DISTINCT FROM 'Z05' OR gridex_supply_rescission.has_end_selector_v1(m,own) IS NOT TRUE OR (SELECT count(*) FROM jsonb_array_elements(w->'objects') actual WHERE actual=own)<>1 THEN RETURN NULL;END IF;
 SELECT array_agg(candidate.id ORDER BY candidate.id) INTO ids FROM public.ediel_messages candidate JOIN gridex_supply_rescission.outbound_operations op ON op.company_id=candidate.company_id AND op.message_id=candidate.id
 WHERE candidate.company_id=m.company_id AND candidate.environment=m.environment AND candidate.direction='outbound' AND candidate.message_family='PRODAT' AND candidate.message_code='Z08' AND gridex_received_sources.sent_source_is_current_v1(candidate) AND op.capability#>>'{objects,0,lineItemReference}'=own->>'li' AND op.capability#>>'{objects,0,objectId}'=own->>'point' AND op.capability#>>'{objects,0,identityAgency}'=own->>'identityAgency';
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO z FROM public.ediel_messages WHERE id=ids[1] AND company_id=m.company_id FOR SHARE;SELECT * INTO o FROM gridex_supply_rescission.outbound_operations WHERE message_id=z.id AND company_id=m.company_id;SELECT * INTO legal FROM gridex_supply_rescission.mandates WHERE id=o.mandate_id AND company_id=m.company_id;
 PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(z);ow:=gridex_bilateral_prodat.draft_wire_v1(z.raw_payload);SELECT * INTO p FROM public.customer_supply_periods WHERE id=(legal.scope->>'periodId')::uuid AND company_id=m.company_id;
 IF p.id IS NULL OR p.source_end_message_id IS NOT NULL OR p.market_end_at IS NOT NULL OR p.market_state_version IS DISTINCT FROM(legal.scope->>'stateVersion')::bigint OR p.customer_id::text IS DISTINCT FROM legal.scope->>'customerId' OR p.metering_point_id::text IS DISTINCT FROM legal.scope->>'pointId'
  OR ow->>'sender' IS DISTINCT FROM w->>'receiver' OR ow->>'receiver' IS DISTINCT FROM w->>'sender' OR jsonb_array_length(ow->'objects')<>1 OR ow#>>'{objects,0,reason}' IS DISTINCT FROM 'Z25' OR ow#>>'{objects,0,li}' IS DISTINCT FROM own->>'li' OR ow#>>'{objects,0,point}' IS DISTINCT FROM own->>'point'
  OR own->>'customerIdentity' IS DISTINCT FROM legal.scope#>>'{customerIdentity,id}' OR gridex_supply_rescission.own_customer_identity_v1(m.raw_payload,own) IS DISTINCT FROM legal.scope->'customerIdentity' OR own->>'gridArea' IS DISTINCT FROM legal.scope->>'gridArea'
  OR gridex_received_sources.permission_time_v1(own->>'end') IS DISTINCT FROM(legal.scope->>'effectiveAt')::timestamptz OR gridex_received_sources.permission_time_v1(ow#>>'{objects,0,end}') IS DISTINCT FROM(legal.scope->>'effectiveAt')::timestamptz THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('mandateId',legal.id,'originalMessageId',z.id,'originalPayloadHash',z.immutable_payload_hash,'periodId',p.id);
END$$;

--
-- Name: outbound_capability_v1(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.outbound_capability_v1(c uuid, actor uuid, env text, raw text, mandate uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE cap jsonb;BEGIN
 IF gridex_supply_rescission.actor_v1(c,actor,'archive') IS NOT TRUE THEN RETURN NULL;END IF;
 cap:=gridex_supply_rescission.outbound_source_capability_v1(c,actor,env,raw,mandate);
 IF gridex_supply_rescission.actor_v1(c,actor,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_producer_forbidden' USING ERRCODE='42501';END IF;RETURN cap;
END$$;

--
-- Name: outbound_required_v1(text); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.outbound_required_v1(raw text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w jsonb;BEGIN
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000)) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT') THEN RETURN false;END IF;
 w:=gridex_bilateral_prodat.draft_wire_v1(raw);RETURN(w->>'code'='Z08' AND EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason'='Z25')) IS TRUE;
END$$;

--
-- Name: outbound_source_capability_v1(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.outbound_source_capability_v1(c uuid, actor uuid, env text, raw text, mandate uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m gridex_supply_rescission.mandates%rowtype;s jsonb;w jsonb;o jsonb;profile uuid;BEGIN
 PERFORM gridex_supply_rescission.lock_original_v1();
 IF actor IS NULL OR env NOT IN('test','production') OR octet_length(raw) NOT BETWEEN 1 AND 8388608 OR(SELECT count(*) FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='UNH')<>1 OR gridex_supply_rescission.mandate_current_v1(c,mandate,true) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO m FROM gridex_supply_rescission.mandates WHERE id=mandate AND company_id=c AND environment=env;s:=m.scope;w:=gridex_bilateral_prodat.draft_wire_v1(raw);o:=w#>'{objects,0}';
 IF m.id IS NULL OR gridex_supply_rescission.outbound_required_v1(raw) IS NOT TRUE OR jsonb_array_length(w->'objects')<>1 OR w->>'bgmId' IS DISTINCT FROM 'H'||replace(m.id::text,'-','')
  OR w->>'sender' IS DISTINCT FROM s->>'legalSenderId' OR w->>'receiver' IS DISTINCT FROM s->>'legalReceiverId'
  OR o->>'li' IS DISTINCT FROM 'H'||replace(m.id::text,'-','') OR o->>'point' IS DISTINCT FROM s->>'externalPoint' OR o->>'reason' IS DISTINCT FROM 'Z25'
  OR (SELECT t#>>'{elements,3,3}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000)) t WHERE t->>'tag'='LIN') IS DISTINCT FROM s->>'identityAgency'
  OR o->>'gridArea' IS DISTINCT FROM s->>'gridArea' OR o->>'customerIdentity' IS DISTINCT FROM s#>>'{customerIdentity,id}'
  OR gridex_supply_rescission.own_customer_identity_v1(raw,o) IS DISTINCT FROM s->'customerIdentity'
  OR gridex_received_sources.permission_time_v1(o->>'end') IS DISTINCT FROM(s->>'effectiveAt')::timestamptz THEN RETURN NULL;END IF;
 SELECT(p->>'id')::uuid INTO profile FROM jsonb_array_elements(s#>'{sourceGrammar,profiles}') p WHERE p->>'profile_key'='PRODAT:Z08:H:26.A:r3' AND p->>'direction' IN('outbound','both');IF profile IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('version',1,'owner','immutable-national-supply-rescission-original-v1','companyId',c,'environment',env,'actorUserId',actor,'mandateId',m.id,'payloadHash',encode(sha256(convert_to(raw,'UTF8')),'hex'),'messageCode','Z08','objects',jsonb_build_array(jsonb_build_object('process','national_supply_rescission','mandateId',m.id,'objectId',s->>'externalPoint','identityAgency',s->>'identityAgency','lineItemReference',o->>'li','firstLineIndex',gridex_bilateral_prodat.first_line_index_v1(raw,o||jsonb_build_object('identityAgency',s->>'identityAgency')),'sourceHash',m.source_hash,'sourceGrammarHash',s->>'sourceGrammarHash','rulePackId',s->>'rulePackId','messageProfileId',profile,'pointId',s->>'pointId','customerId',s->>'customerId','siteId',s->>'siteId','contractId',s->>'contractId','contractHash',s->>'contractHash','eventAt',s->>'effectiveAt','supplyPeriodId',s->>'periodId','marketStateVersion',s->>'stateVersion')));
END$$;

--
-- Name: own_customer_identity_v1(text, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.own_customer_identity_v1(raw text, own jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);lin jsonb;party jsonb;stop int;BEGIN
 IF tokens IS NULL THEN RETURN NULL;END IF;
 IF(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND t#>>'{elements,1,0}'=own->>'line' AND t#>>'{elements,3,0}'=own->>'point')<>1 THEN RETURN NULL;END IF;
 SELECT t INTO lin FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND t#>>'{elements,1,0}'=own->>'line' AND t#>>'{elements,3,0}'=own->>'point';
 SELECT min((t->>'index')::int) INTO stop FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>(lin->>'index')::int AND t->>'tag' IN('LIN','UNT','UNH','UNZ');
 IF stop IS NULL OR(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>(lin->>'index')::int AND(t->>'index')::int<stop AND t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD')<>1 THEN RETURN NULL;END IF;
 SELECT t#>'{elements,2}' INTO party FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>(lin->>'index')::int AND(t->>'index')::int<stop AND t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD';
 RETURN jsonb_build_object('id',party->>0,'qualifier',party->>1,'agency',party->>2);
END$$;

--
-- Name: artifacts; Type: TABLE; Schema: gridex_supply_rescission; Owner: -
--

CREATE TABLE gridex_supply_rescission.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    selector jsonb NOT NULL,
    scope jsonb NOT NULL,
    scope_hash text NOT NULL,
    source_bytes bytea,
    source_hash text NOT NULL,
    mime_type text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    issuer_receipt jsonb,
    receipt_hash text NOT NULL,
    submitted_by uuid NOT NULL,
    archived_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

ALTER TABLE ONLY gridex_supply_rescission.artifacts FORCE ROW LEVEL SECURITY;

--
-- Name: receipt_current_v1(gridex_supply_rescission.artifacts); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.receipt_current_v1(a gridex_supply_rescission.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE key gridex_supply_rescission.issuer_keys%rowtype;representation gridex_supply_rescission.issuer_representations%rowtype;payload jsonb;bytes bytea;issued timestamptz;expires timestamptz;completed timestamptz;BEGIN
 PERFORM gridex_supply_rescission.lock_v1(); IF gridex_ediel_retention.protected_copy_current_v1(a.company_id,a.id) IS NOT TRUE THEN RETURN false;END IF;
 IF a.source_bytes IS NULL OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.scope::text,'UTF8')),'hex') IS DISTINCT FROM a.scope_hash OR jsonb_typeof(a.issuer_receipt) IS DISTINCT FROM 'object' OR a.issuer_receipt-ARRAY['keyId','representationId','payloadBase64','signatureHex']<>'{}'::jsonb OR coalesce(a.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' THEN RETURN false;END IF;
 SELECT * INTO key FROM gridex_supply_rescission.issuer_keys WHERE id=(a.issuer_receipt->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment;
 SELECT * INTO representation FROM gridex_supply_rescission.issuer_representations WHERE id=(a.issuer_receipt->>'representationId')::uuid AND issuer_key_id=key.id AND company_id=a.company_id AND environment=a.environment AND legal_actor_id::text=a.scope->>'legalActorId' AND dso_actor_id::text=a.scope->>'dsoActorId' AND grid_area_code=a.scope->>'gridArea';
 IF key.id IS NULL OR representation.id IS NULL OR clock_timestamp()<greatest(key.valid_from,representation.valid_from) OR clock_timestamp()>=least(key.valid_to,representation.valid_to) OR EXISTS(SELECT FROM gridex_supply_rescission.issuer_revocations v WHERE v.target_kind='key' AND v.target_id=key.id OR v.target_kind='representation' AND v.target_id=representation.id) THEN RETURN false;END IF;
 bytes:=decode(a.issuer_receipt->>'payloadBase64','base64');IF octet_length(bytes) NOT BETWEEN 1 AND 1048576 OR sha256(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,key.receipt_signing_key)) IS DISTINCT FROM sha256(decode(a.issuer_receipt->>'signatureHex','hex')) THEN RETURN false;END IF;
 payload:=convert_from(bytes,'UTF8')::jsonb;issued:=(payload->>'issuedAt')::timestamptz;expires:=(payload->>'expiresAt')::timestamptz;completed:=(payload->>'legalPrerequisitesCompletedAt')::timestamptz;
 RETURN(payload->>'format'='ediel_national_supply_rescission_receipt_v1' AND payload->>'purpose'='national_prodat_z08h_legal_rescission' AND payload->>'issuerCode'=key.issuer_code AND payload->>'companyId'=a.company_id::text AND payload->>'environment'=a.environment AND payload->'scope'=a.scope AND payload->>'sourceHash'=a.source_hash AND payload->>'sourceReference'=a.source_reference AND payload->>'sourceVersion'=a.source_version
 AND nullif(btrim(payload->>'receiptId'),'') IS NOT NULL AND nullif(btrim(payload->>'legalCaseReference'),'') IS NOT NULL AND nullif(btrim(payload->>'legalDecisionReference'),'') IS NOT NULL AND nullif(btrim(payload->>'legalPrerequisitesReference'),'') IS NOT NULL
 AND isfinite(issued) AND isfinite(expires) AND isfinite(completed) AND completed<=issued AND issued<=clock_timestamp() AND completed<=(a.scope->>'effectiveAt')::timestamptz AND issued>=greatest(key.valid_from,representation.valid_from) AND expires>clock_timestamp() AND expires>(a.scope->>'effectiveAt')::timestamptz AND expires<=least(key.valid_to,representation.valid_to)) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;END$_$;

--
-- Name: record_end_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.record_end_v1(m public.ediel_messages, plans jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE t gridex_received_sources.supply_source_transitions%rowtype;plan jsonb;b jsonb;own jsonb;BEGIN
 SELECT * INTO STRICT t FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id AND company_id=m.company_id;
 FOR plan IN SELECT p FROM jsonb_array_elements(plans)p LOOP b:=plan->'binding';own:=plan->'object';
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) state WHERE state->>'id'=b->>'periodId' AND state->>'source_end_message_id'=m.id::text AND(state->>'market_end_at')::timestamptz=gridex_received_sources.permission_time_v1(own->>'end')) THEN RAISE EXCEPTION 'supply_rescission_actual_owned_end_required';END IF;
  INSERT INTO gridex_supply_rescission.end_receipts(source_message_id,mandate_id,company_id,environment,source_payload_hash,original_message_id,original_payload_hash,period_id,source_object,transition_hash) VALUES(m.id,(b->>'mandateId')::uuid,m.company_id,m.environment,t.payload_hash,(b->>'originalMessageId')::uuid,b->>'originalPayloadHash',(b->>'periodId')::uuid,own,encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex'));
 END LOOP;IF gridex_supply_rescission.recorded_end_current_v1(m.company_id,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_recorded_current_source_required';END IF;
 INSERT INTO public.audit_logs(company_id,actor_user_id,action,entity_type,entity_id,metadata) VALUES(m.company_id,t.actor_user_id,'ediel.supply_rescission.end_applied','ediel_message',m.id,jsonb_build_object('sourcePayloadHash',t.payload_hash,'ownedOriginals',plans,'resultingStates',t.resulting_states));
END$$;

--
-- Name: recorded_end_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.recorded_end_current_v1(c uuid, s uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;t gridex_received_sources.supply_source_transitions%rowtype;r gridex_supply_rescission.end_receipts%rowtype;z public.ediel_messages%rowtype;n int;BEGIN
 PERFORM gridex_supply_rescission.lock_original_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=s AND company_id=c;SELECT * INTO t FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=s AND company_id=c;
 IF m.id IS NULL OR t.source_message_id IS NULL OR m.raw_payload IS NULL OR t.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;PERFORM public.ediel_require_source_bytes_available_v1(c,s);
 SELECT count(*) INTO n FROM jsonb_array_elements(t.source_objects) own WHERE gridex_supply_rescission.has_end_selector_v1(m,own);IF n=0 THEN RETURN NOT EXISTS(SELECT FROM gridex_supply_rescission.end_receipts WHERE company_id=c AND source_message_id=s);END IF;
 IF n<>(SELECT count(*) FROM gridex_supply_rescission.end_receipts WHERE company_id=c AND source_message_id=s) THEN RETURN false;END IF;
 FOR r IN SELECT receipt.* FROM gridex_supply_rescission.end_receipts receipt WHERE receipt.company_id=c AND receipt.source_message_id=s LOOP
  IF r.environment IS DISTINCT FROM m.environment OR r.source_payload_hash IS DISTINCT FROM t.payload_hash OR r.transition_hash IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') OR gridex_supply_rescission.mandate_current_v1(c,r.mandate_id,false) IS NOT TRUE OR NOT EXISTS(SELECT FROM jsonb_array_elements(t.source_objects) own WHERE own=r.source_object) OR NOT EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) state WHERE state->>'id'=r.period_id::text AND state->>'source_end_message_id'=s::text AND(state->>'market_end_at')::timestamptz=gridex_received_sources.permission_time_v1(r.source_object->>'end')) THEN RETURN false;END IF;
  SELECT * INTO z FROM public.ediel_messages WHERE id=r.original_message_id AND company_id=c AND environment=m.environment;IF z.id IS NULL OR z.immutable_payload_hash IS DISTINCT FROM r.original_payload_hash OR gridex_received_sources.sent_source_is_current_v1(z) IS NOT TRUE THEN RETURN false;END IF;PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(z);
 END LOOP;RETURN true;
END$$;

--
-- Name: require_draft_v1(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_draft_v1(c uuid, actor uuid, d jsonb, cap jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;BEGIN
 s:=public.ediel_read_supply_rescission_mandate_v1(c,actor,(d->>'sourceOperationId')::uuid);
 IF s IS NULL OR cap->>'mandateId' IS DISTINCT FROM s->>'mandateId' OR d->>'customerId' IS DISTINCT FROM s->>'customerId' OR d->>'siteId' IS DISTINCT FROM s->>'siteId' OR d->>'meteringPointId' IS DISTINCT FROM s->>'pointId' OR nullif(d->>'switchRequestId','') IS NOT NULL THEN RAISE EXCEPTION 'supply_rescission_actual_mandate_required';END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=(d->>'intentId')::uuid AND company_id=c FOR UPDATE;SELECT * INTO r FROM public.outbound_requests WHERE id=(d->>'outboundRequestId')::uuid AND company_id=c FOR SHARE;
 IF i.id IS NULL OR i.ediel_message_id IS NOT NULL OR i.created_by IS DISTINCT FROM actor OR i.environment IS DISTINCT FROM s->>'environment' OR i.direction IS DISTINCT FROM 'outbound' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z08' OR i.operation_id::text IS DISTINCT FROM s->>'mandateId' OR i.payload->>'transactionSubtype' IS DISTINCT FROM 'H'
  OR i.customer_id::text IS DISTINCT FROM s->>'customerId' OR i.customer_site_id::text IS DISTINCT FROM s->>'siteId' OR i.metering_point_id IS DISTINCT FROM s->>'pointId' OR i.transaction_reference IS DISTINCT FROM s->>'lineItemReference'
  OR r.id IS NULL OR r.request_type IS DISTINCT FROM 'supplier_switch_cancellation' OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM i.operation_id OR r.customer_id IS DISTINCT FROM i.customer_id OR r.site_id IS DISTINCT FROM i.customer_site_id OR r.metering_point_id::text IS DISTINCT FROM s->>'pointId' OR r.payload->>'environment' IS DISTINCT FROM s->>'environment' THEN RAISE EXCEPTION 'supply_rescission_validated_own_intent_request_required';END IF;
END$$;

--
-- Name: require_intake_session_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_intake_session_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF actor IS NULL OR auth.uid() IS DISTINCT FROM actor OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN
  RAISE EXCEPTION 'supply_rescission_authenticated_session_required' USING ERRCODE='42501';
 END IF;
 IF phase NOT IN('read','archive','review') OR gridex_supply_rescission.actor_v1(c,actor,phase) IS NOT TRUE THEN
  RAISE EXCEPTION 'supply_rescission_current_intake_actor_forbidden' USING ERRCODE='42501';
 END IF;
END$$;

--
-- Name: require_matched_end_v1(public.ediel_messages, jsonb, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_matched_end_v1(m public.ediel_messages, w jsonb, own jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF gridex_supply_rescission.matched_end_v1(m,w,own) IS NULL THEN RAISE EXCEPTION 'supply_rescission_exact_sent_original_required';END IF;
END$$;

--
-- Name: require_original_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_original_v1(m public.ediel_messages, creating boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_supply_rescission.outbound_operations%rowtype;r gridex_supply_rescission.outbound_receipts%rowtype;cap jsonb;BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN RETURN;END IF;
 PERFORM gridex_supply_rescission.lock_original_v1();SELECT * INTO o FROM gridex_supply_rescission.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;SELECT * INTO r FROM gridex_supply_rescission.outbound_receipts WHERE message_id=m.id AND company_id=m.company_id;
 IF o.message_id IS NULL OR r.message_id IS NULL OR m.source_operation_id IS DISTINCT FROM o.mandate_id::text OR m.created_by IS DISTINCT FROM o.actor_user_id OR m.environment IS DISTINCT FROM o.environment OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR r.payload_hash IS DISTINCT FROM o.payload_hash OR r.witness_id::text IS DISTINCT FROM m.execution_context_snapshot->>'outboundOwnerWitnessId'
  OR creating AND o.creation_txid IS DISTINCT FROM txid_current() OR NOT EXISTS(SELECT FROM gridex_ediel_outbound_owner.witnesses witness WHERE witness.id=r.witness_id AND witness.company_id=m.company_id AND witness.actor_user_id=o.actor_user_id AND witness.environment=o.environment AND witness.payload_sha256=o.payload_hash) THEN RAISE EXCEPTION 'supply_rescission_atomic_original_required';END IF;
 cap:=gridex_supply_rescission.outbound_source_capability_v1(m.company_id,o.actor_user_id,m.environment,m.raw_payload,o.mandate_id);IF cap IS NULL OR cap IS DISTINCT FROM o.capability THEN RAISE EXCEPTION 'supply_rescission_current_mandate_required';END IF;
END$$;

--
-- Name: require_recorded_outbound_source_current_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_recorded_outbound_source_current_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_supply_rescission.outbound_operations%rowtype;r gridex_supply_rescission.outbound_receipts%rowtype;mandate gridex_supply_rescission.mandates%rowtype;BEGIN
 PERFORM gridex_supply_rescission.lock_original_v1();PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
 SELECT * INTO o FROM gridex_supply_rescission.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;SELECT * INTO r FROM gridex_supply_rescission.outbound_receipts WHERE message_id=m.id AND company_id=m.company_id;
 SELECT * INTO mandate FROM gridex_supply_rescission.mandates WHERE id=o.mandate_id AND company_id=m.company_id;
 IF o.message_id IS NULL OR r.message_id IS NULL OR m.raw_payload IS NULL OR m.source_operation_id IS DISTINCT FROM o.mandate_id::text OR m.environment IS DISTINCT FROM o.environment OR m.created_by IS DISTINCT FROM o.actor_user_id
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR r.payload_hash IS DISTINCT FROM o.payload_hash OR r.witness_id::text IS DISTINCT FROM m.execution_context_snapshot->>'outboundOwnerWitnessId'
  OR gridex_supply_rescission.mandate_current_v1(m.company_id,o.mandate_id,false) IS NOT TRUE OR o.capability#>>'{objects,0,sourceHash}' IS DISTINCT FROM mandate.source_hash OR o.capability#>>'{objects,0,sourceGrammarHash}' IS DISTINCT FROM mandate.scope->>'sourceGrammarHash'
  OR NOT EXISTS(SELECT FROM gridex_ediel_outbound_owner.consumptions used JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=used.witness_id WHERE used.source_message_id=m.id AND used.company_id=m.company_id AND used.environment=m.environment AND used.payload_sha256=o.payload_hash AND witness.id=r.witness_id AND witness.payload_sha256=o.payload_hash AND witness.actor_user_id=o.actor_user_id)
  OR NOT EXISTS(SELECT FROM gridex_ediel_source_rules.receipts source WHERE source.source_message_id=m.id AND source.company_id=m.company_id AND source.environment=m.environment AND source.direction='outbound' AND source.payload_sha256=o.payload_hash) THEN RAISE EXCEPTION 'supply_rescission_recorded_original_required';END IF;
END$$;

--
-- Name: require_recorded_outbound_v1(public.ediel_messages, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.require_recorded_outbound_v1(m public.ediel_messages, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF gridex_supply_rescission.actor_v1(m.company_id,actor,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_recorded_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(m);
 IF gridex_supply_rescission.actor_v1(m.company_id,actor,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_reader_forbidden' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: scope_v1(uuid, jsonb); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.scope_v1(c uuid, selector jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE p public.customer_supply_periods%rowtype;mp public.metering_points%rowtype;customer public.customers%rowtype;contract public.customer_contracts%rowtype;site public.customer_sites%rowtype;
 basis jsonb;env text;sender text;initial public.ediel_messages%rowtype;effective timestamptz;legal uuid;dso uuid;pack public.ediel_rule_packs%rowtype;profiles jsonb;grammar jsonb;identity text;ids uuid[];BEGIN
 PERFORM gridex_supply_rescission.lock_v1();
 IF jsonb_typeof(selector) IS DISTINCT FROM 'object' OR selector-ARRAY['environment','supplyPeriodId','effectiveAt','rulePackId']<>'{}'::jsonb OR NOT(selector ?& ARRAY['environment','supplyPeriodId','effectiveAt','rulePackId']) THEN RETURN NULL;END IF;
 env:=selector->>'environment';effective:=(selector->>'effectiveAt')::timestamptz;
 IF env NOT IN('test','production') OR effective IS NULL OR NOT isfinite(effective) OR date_trunc('minute',effective) IS DISTINCT FROM effective THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=(selector->>'supplyPeriodId')::uuid AND company_id=c;
 IF p.id IS NULL OR p.market_start_at>=effective OR p.market_end_at IS NOT NULL OR p.source_end_message_id IS NOT NULL OR (p.status IN('active','confirmed_by_grid_owner')) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO mp FROM public.metering_points WHERE id=p.metering_point_id AND company_id=c;
 SELECT * INTO customer FROM public.customers WHERE id=p.customer_id AND company_id=c;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(mp.customer_site_id,mp.site_id) AND company_id=c AND customer_id=p.customer_id;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(p.contract_id,p.customer_contract_id) AND company_id=c AND customer_id=p.customer_id AND metering_point_id=mp.id;
 basis:=gridex_received_sources.supply_period_source_basis_v1(c,p.id,effective-interval '1 minute',effective);
 IF basis IS NULL OR basis->>'qualified' IS DISTINCT FROM 'true' OR nullif(basis->>'originalMessageId','') IS NULL OR coalesce(basis->>'originalPayloadHash','')!~'^[a-f0-9]{64}$' OR (SELECT environment FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=c) IS DISTINCT FROM env OR mp.id IS NULL OR customer.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR mp.customer_id IS DISTINCT FROM p.customer_id OR nullif(mp.ediel_metering_point_id,'') IS NULL OR nullif(mp.grid_area_code,'') IS NULL OR nullif(mp.grid_owner_ediel_id,'') IS NULL THEN RETURN NULL;END IF;
 legal:=(basis->>'legalActorId')::uuid;
 SELECT * INTO initial FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=c AND environment=env;
 sender:=gridex_received_sources.normal_switch_wire_v1(initial.raw_payload)->>'receiver';
 IF nullif(sender,'') IS NULL OR (SELECT count(DISTINCT(company_id,actor_id)) FROM public.tenant_actor_identifiers WHERE environment=env AND identifier_type='EdielId' AND identifier_value=sender AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to))<>1 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND actor_id=legal AND identifier_type='EdielId' AND identifier_value=sender AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to)) OR NOT EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=c AND environment=env AND actor_id=legal AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to)) THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT actor_id) INTO ids FROM public.platform_actor_identifiers WHERE identifier_value=mp.grid_owner_ediel_id AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND(valid_from IS NULL OR valid_from<=(clock_timestamp()::date)) AND(valid_to IS NULL OR (clock_timestamp()::date)<=valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;dso:=ids[1];
 SELECT * INTO pack FROM public.ediel_rule_packs WHERE id=(selector->>'rulePackId')::uuid AND family='PRODAT' AND market='electricity' AND status='active' AND guide_version='26.A' AND guide_revision='3' AND valid_from<=(clock_timestamp()::date) AND(valid_to IS NULL OR (clock_timestamp()::date)<=valid_to);
 IF pack.id IS NULL OR NOT EXISTS(SELECT FROM public.ediel_rule_pack_sources WHERE rule_pack_id=pack.id) THEN RETURN NULL;END IF;
 SELECT jsonb_agg(to_jsonb(selected_profile) ORDER BY selected_profile.id) INTO profiles FROM public.ediel_message_profiles selected_profile WHERE selected_profile.rule_pack_id=pack.id AND selected_profile.is_enabled AND(selected_profile.message_code='Z08' AND selected_profile.transaction_subtype='H' AND selected_profile.direction IN('outbound','both') OR selected_profile.message_code='Z05' AND selected_profile.transaction_subtype='L' AND selected_profile.direction IN('inbound','both'));
 IF jsonb_array_length(profiles)<>2 OR NOT EXISTS(SELECT FROM jsonb_array_elements(profiles) profile WHERE profile->>'profile_key'='PRODAT:Z08:H:26.A:r3') OR NOT EXISTS(SELECT FROM jsonb_array_elements(profiles) profile WHERE profile->>'profile_key'='PRODAT:Z05:L:26.A:r3') THEN RETURN NULL;END IF;
 grammar:=jsonb_build_object('pack',to_jsonb(pack),'profiles',profiles,'sources',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.ediel_rule_pack_sources s WHERE s.rule_pack_id=pack.id),'fields',(SELECT jsonb_agg(to_jsonb(f) ORDER BY f.id) FROM public.ediel_field_rules f WHERE f.message_family='PRODAT' AND coalesce(f.is_active,true) AND coalesce(f.enabled,true)
   AND EXISTS(SELECT FROM jsonb_array_elements(profiles) profile WHERE profile->>'message_code'=f.message_code AND (nullif(f.subtype,'') IS NULL OR f.subtype=profile->>'transaction_subtype'))),'segments',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.ediel_segment_rules s WHERE s.message_profile_id IN(SELECT(profile->>'id')::uuid FROM jsonb_array_elements(profiles) profile)));
 identity:=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''));IF nullif(identity,'') IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.switch_brp_source_bindings b WHERE b.message_id=(basis->>'originalMessageId')::uuid AND b.company_id=c AND nullif(b.brp_ediel_id,'') IS NOT NULL) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('purpose','national_prodat_z08h_legal_rescission','companyId',c,'environment',env,'periodId',p.id,'stateVersion',p.market_state_version,'initialSourceMessageId',p.source_message_id,'initialPayloadHash',encode(sha256(convert_to(initial.raw_payload,'UTF8')),'hex'),'originalMessageId',basis->>'originalMessageId','originalPayloadHash',basis->>'originalPayloadHash','customerId',customer.id,'siteId',site.id,'pointId',mp.id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'externalPoint',mp.ediel_metering_point_id,'identityAgency','9','gridArea',mp.grid_area_code,'legalActorId',legal,'legalSenderId',sender,'dsoActorId',dso,'legalReceiverId',mp.grid_owner_ediel_id,'customerIdentity',jsonb_build_object('id',identity,'qualifier',CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1' ELSE 'SE2' END,'agency','260'),'effectiveAt',effective,'balanceResponsibleId',(SELECT b.brp_ediel_id FROM gridex_received_sources.switch_brp_source_bindings b WHERE b.message_id=(basis->>'originalMessageId')::uuid AND b.company_id=c),'rulePackId',pack.id,'sourceGrammar',grammar,'sourceGrammarHash',encode(sha256(convert_to(grammar::text,'UTF8')),'hex'));
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN NULL;END$_$;

--
-- Name: sender_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_supply_rescission; Owner: -
--

CREATE FUNCTION gridex_supply_rescission.sender_v1(c uuid, actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN gridex_supply_rescission.execution_actor_active_v1(c,actor) IS TRUE
 AND(gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'communication.send') IS TRUE
 OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(c,actor,'ediel.send') IS TRUE);
END$$;

--
-- Name: bind_message_v1(); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.bind_message_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o gridex_switch_cancellations.origins%rowtype;b jsonb;w jsonb;own jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE intent_id=NEW.intent_id;IF NOT FOUND THEN RETURN NEW;END IF;
 b:=gridex_switch_cancellations.context_v1(o.company_id,o.switch_id,o.actor_user_id);
 SELECT * INTO STRICT o FROM gridex_switch_cancellations.origins WHERE intent_id=NEW.intent_id FOR UPDATE;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 IF b->>'status' IS DISTINCT FROM 'authorized' OR (b-ARRAY['operationId','intentId','outboundRequestId','messageId']) IS DISTINCT FROM o.basis
  OR to_jsonb(i)-ARRAY['created_at','updated_at','validation_status','validation_report','render_status','outbox_status','ack_status','ediel_message_id','outbound_request_id'] IS DISTINCT FROM o.intent_binding
  OR i.validation_status IS DISTINCT FROM 'validated' OR r.source_type IS DISTINCT FROM 'manual' OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.operation_id IS DISTINCT FROM i.operation_id OR r.payload->>'environment' IS DISTINCT FROM NEW.environment
  OR r.customer_id IS DISTINCT FROM NEW.customer_id OR r.site_id IS DISTINCT FROM NEW.site_id OR r.metering_point_id IS DISTINCT FROM NEW.metering_point_id
 THEN RAISE EXCEPTION 'switch_cancellation_current_origin_required';END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(NEW.raw_payload);own:=w#>'{objects,0}';
 IF w IS NULL OR w->>'code' IS DISTINCT FROM 'Z03' OR own->>'reason' IS DISTINCT FROM 'Z24' OR NEW.company_id IS DISTINCT FROM o.company_id OR NEW.environment IS DISTINCT FROM b->>'environment'
  OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_standard IS DISTINCT FROM 'edifact' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM 'Z03'
  OR NEW.intent_id IS DISTINCT FROM i.id OR NEW.interchange_reference IS DISTINCT FROM i.interchange_reference OR NEW.transaction_reference IS DISTINCT FROM i.transaction_reference
  OR NEW.application_reference IS DISTINCT FROM i.application_reference OR NEW.sender_ediel_id IS DISTINCT FROM i.sender_ediel_id OR NEW.receiver_ediel_id IS DISTINCT FROM i.receiver_ediel_id
  OR NEW.sender_sub_address IS DISTINCT FROM i.sender_subaddress OR NEW.receiver_sub_address IS DISTINCT FROM i.receiver_subaddress
  OR NEW.communication_route_id IS DISTINCT FROM i.communication_route_id OR NEW.route_profile_id IS DISTINCT FROM i.route_profile_id
  OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR NEW.source_operation_id IS DISTINCT FROM o.id::text OR NEW.original_message_id IS DISTINCT FROM o.original_message_id::text
  OR NEW.switch_request_id IS DISTINCT FROM o.switch_id OR NEW.customer_id::text IS DISTINCT FROM b->>'customerId' OR NEW.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId' OR NEW.site_id::text IS DISTINCT FROM b->>'siteId'
  OR own->>'li' IS DISTINCT FROM b->>'li' OR own->>'installationPoint' IS DISTINCT FROM b->>'pointId' OR own->>'installationAgency' IS DISTINCT FROM b->>'identityAgency'
  OR own->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity' OR own->>'customerQualifier' IS DISTINCT FROM b->>'customerQualifier' OR own->>'customerAgency' IS DISTINCT FROM '260' OR own->>'gridArea' IS DISTINCT FROM b->>'gridArea'
  OR own->>'start' IS DISTINCT FROM b#>>'{sourceObject,start}' OR w->>'sender' IS DISTINCT FROM b->>'legalSenderId' OR w->>'receiver' IS DISTINCT FROM b->>'legalReceiverId'
  OR NEW.immutable_rendered_at IS NULL OR NEW.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_cancellation_exact_original_wire_required';END IF;
 PERFORM gridex_switch_cancellations.require_original_method_v1(o.company_id,o.original_message_id,o.original_hash,NEW.environment,NEW.raw_payload);
 IF o.message_id IS NOT NULL THEN RAISE EXCEPTION 'switch_cancellation_original_already_bound';END IF;
 UPDATE gridex_switch_cancellations.origins SET message_id=NEW.id,payload_hash=NEW.immutable_payload_hash WHERE id=o.id;
 UPDATE public.supplier_switch_requests SET status='cancellation_requested',updated_by=o.actor_user_id,updated_at=now() WHERE id=o.switch_id AND company_id=o.company_id;
 RETURN NEW;
END $$;

--
-- Name: bound_message_immutable_v1(); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.bound_message_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT FROM gridex_switch_cancellations.origins o WHERE o.message_id=OLD.id) AND
 ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_standard,NEW.message_family,NEW.message_code,NEW.intent_id,NEW.outbound_request_id,NEW.source_operation_id,
 NEW.original_message_id,NEW.switch_request_id,NEW.customer_id,NEW.site_id,NEW.metering_point_id,NEW.raw_payload,NEW.immutable_payload_hash,NEW.immutable_rendered_at,
 NEW.sender_ediel_id,NEW.receiver_ediel_id,NEW.sender_sub_address,NEW.receiver_sub_address,NEW.communication_route_id,NEW.route_profile_id,NEW.application_reference,NEW.interchange_reference,NEW.transaction_reference)
 IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_standard,OLD.message_family,OLD.message_code,OLD.intent_id,OLD.outbound_request_id,OLD.source_operation_id,
 OLD.original_message_id,OLD.switch_request_id,OLD.customer_id,OLD.site_id,OLD.metering_point_id,OLD.raw_payload,OLD.immutable_payload_hash,OLD.immutable_rendered_at,
 OLD.sender_ediel_id,OLD.receiver_ediel_id,OLD.sender_sub_address,OLD.receiver_sub_address,OLD.communication_route_id,OLD.route_profile_id,OLD.application_reference,OLD.interchange_reference,OLD.transaction_reference)
 THEN RAISE EXCEPTION 'switch_cancellation_bound_message_immutable';END IF;RETURN NEW;END $$;

--
-- Name: context_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.context_v1(c uuid, sw uuid, actor uuid, prepare_execution boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE s public.supplier_switch_requests%rowtype;m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;
 ct public.customer_contracts%rowtype;mp public.metering_points%rowtype;w jsonb;own jsonb;current_legal jsonb;prior_legal jsonb;t jsonb;ud jsonb;
 original_id uuid;start_day date;deadline date;today date:=(clock_timestamp()+interval '1 hour')::date;reserved gridex_switch_cancellations.origins%rowtype;
BEGIN
 -- Discover only a selector. Recheck the parent after ordered genuine original,
 -- executor and parent locks; no public metadata constitutes source authority.
 PERFORM gridex_switch_cancellations.prelock_customer_source_v1(c,sw); SELECT outbound_z03_message_id INTO original_id FROM public.supplier_switch_requests WHERE id=sw AND company_id=c;
 SELECT * INTO m FROM public.ediel_messages WHERE id=original_id AND company_id=c FOR UPDATE;
 IF prepare_execution IS NULL THEN RAISE EXCEPTION 'switch_cancellation_execution_phase_required';END IF;
 IF prepare_execution THEN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF c IS NULL OR sw IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(actor,c,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'switch_cancellation_actor_forbidden' USING ERRCODE='42501';END IF;
 END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=sw AND company_id=c FOR UPDATE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c AND switch_id=s.id;
 IF s.id IS NULL OR m.id IS NULL OR o.message_id IS NULL OR s.outbound_z03_message_id IS DISTINCT FROM m.id OR m.direction IS DISTINCT FROM 'outbound'
  OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR gridex_received_sources.sent_source_is_current_v1(m) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['genuine_own_source_bound_accepted_z03_original']);END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);own:=w#>'{objects,0}';
 IF w IS NULL OR own IS DISTINCT FROM o.original_object OR (own->>'reason' IN('Z22','Z23')) IS NOT TRUE OR nullif(own->>'li','') IS NULL
  OR own->>'li' IS DISTINCT FROM s.rff_li_reference OR nullif(own->>'customerIdentity','') IS NULL OR nullif(own->>'installationPoint','') IS NULL
  OR nullif(own->>'gridArea','') IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['immutable_original_customer_point_li_subtype']);END IF;
 prior_legal:=gridex_ediel_inbound_context.require_v1(c,m.id);
 current_legal:=gridex_ediel_inbound_context.derive(m,clock_timestamp());
 IF prior_legal->>'legalActorId' IS DISTINCT FROM current_legal->>'legalActorId' OR current_legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR current_legal->>'legalEdielId' IS DISTINCT FROM w->>'sender' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_same_legal_supplier_source_context']);END IF;
 SELECT * INTO ct FROM public.customer_contracts WHERE id=o.contract_id AND company_id=c FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=c FOR SHARE;
 PERFORM site.id FROM public.customer_sites site WHERE site.id=coalesce(s.site_id,s.customer_site_id) AND site.company_id=c FOR SHARE;
 IF ct.id IS NULL OR mp.id IS NULL OR ct.customer_id IS DISTINCT FROM s.customer_id OR ct.metering_point_id IS DISTINCT FROM mp.id
  OR coalesce(s.customer_contract_id,s.contract_id) IS DISTINCT FROM o.contract_id
  OR NOT EXISTS(SELECT FROM public.customer_sites site WHERE site.id=mp.site_id AND site.company_id=c)
  OR s.customer_id::text IS DISTINCT FROM o.resulting_switch->>'customer_id' OR s.metering_point_id::text IS DISTINCT FROM o.resulting_switch->>'metering_point_id'
  OR coalesce(s.site_id,s.customer_site_id)::text IS DISTINCT FROM coalesce(o.resulting_switch->>'site_id',o.resulting_switch->>'customer_site_id')
  OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM ct.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM ct.id)
  OR mp.customer_id IS DISTINCT FROM s.customer_id OR mp.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id)
  OR own->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''))
  OR own->>'gridArea' IS DISTINCT FROM mp.grid_area_code OR w->>'receiver' IS DISTINCT FROM mp.grid_owner_ediel_id
  OR s.lifecycle_blocked IS TRUE OR (s.status IN('prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancellation_sent')) IS NOT TRUE
 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_current_owned_switch_customer_contract_physical_scope']);END IF;
 start_day:=gridex_received_sources.permission_date_v1(own->>'start');
 deadline:=CASE own->>'reason' WHEN 'Z22' THEN start_day-4 WHEN 'Z23' THEN start_day END;
 IF start_day IS NULL OR start_day IS DISTINCT FROM s.requested_start_date OR deadline IS NULL OR today>deadline THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_z03_cancellation_calendar_window']);END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(m.raw_payload))x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='UD' LOOP
  IF ud IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['unique_original_customer_identity']);END IF;ud:=t;
 END LOOP;
 IF ud IS NULL OR (ud#>>'{elements,2,1}' IN('SE1','SE2')) IS NOT TRUE OR ud#>>'{elements,2,2}' IS DISTINCT FROM '260' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['qualified_original_customer_identity']);END IF;
 SELECT * INTO reserved FROM gridex_switch_cancellations.origins WHERE company_id=c AND switch_id=s.id AND original_message_id=m.id;
 RETURN jsonb_build_object('status','authorized','companyId',c,'environment',m.environment,'switchRequestId',s.id,'originalMessageId',m.id,'originalHash',o.payload_hash,
  'operationId',reserved.id,'intentId',reserved.intent_id,'outboundRequestId',reserved.outbound_request_id,'messageId',reserved.message_id,
  'customerId',s.customer_id,'siteId',mp.site_id,'meteringPointId',mp.id,'legalActorId',current_legal->>'legalActorId','legalSenderId',w->>'sender','legalReceiverId',w->>'receiver',
  'pointId',own->>'installationPoint','identityAgency',own->>'installationAgency','gridArea',own->>'gridArea','li',own->>'li','startAt',gridex_received_sources.permission_time_v1(own->>'start'),
  'originalSubtype',CASE own->>'reason' WHEN 'Z22' THEN 'L' ELSE 'LK' END,'deadline',deadline,'customerIdentity',own->>'customerIdentity','customerQualifier',ud#>>'{elements,2,1}',
  'customerName',coalesce(ud#>>'{elements,4,0}',''),'sourceObject',own);
END $$;

--
-- Name: customer_draft_v1(uuid, uuid, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.customer_draft_v1(c uuid, operation uuid, actor uuid, phase text, intent uuid, route uuid, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_switch_cancellations.origins%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;q jsonb;b jsonb;w jsonb;own jsonb;tokens jsonb;original_tokens jsonb;unb jsonb;unh jsonb;unt jsonb;unz jsonb;ud jsonb;obj jsonb;source gridex_customer_masterdata.preparations%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=c AND id=operation;
 IF o.id IS NULL THEN RAISE EXCEPTION 'customer_masterdata_cancellation_private_origin_required';END IF;
 PERFORM gridex_switch_cancellations.prelock_customer_source_v1(c,o.switch_id,o.message_id);
 q:=gridex_switch_cancellations.customer_source_v1(c,o.switch_id,actor,phase);
 b:=gridex_switch_cancellations.context_v1(c,o.switch_id,actor,phase='prepare');
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=c AND id=operation FOR SHARE;
 SELECT * INTO i FROM public.ediel_message_intents WHERE company_id=c AND id=o.intent_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE company_id=c AND id=o.outbound_request_id FOR SHARE;
 IF b->>'status' IS DISTINCT FROM 'authorized' OR (b-ARRAY['operationId','intentId','outboundRequestId','messageId']) IS DISTINCT FROM o.basis
  OR o.original_message_id::text IS DISTINCT FROM q#>>'{cancellationSourceBinding,originalMessageId}' OR o.original_hash IS DISTINCT FROM q#>>'{cancellationSourceBinding,originalHash}'
  OR o.intent_id IS DISTINCT FROM intent OR i.id IS NULL OR r.id IS NULL OR i.operation_id IS DISTINCT FROM operation OR i.communication_route_id IS DISTINCT FROM route
  OR i.environment IS DISTINCT FROM b->>'environment' OR i.direction IS DISTINCT FROM 'outbound' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z03'
  OR i.business_process IS DISTINCT FROM 'supplier_switch' OR i.validation_status IS DISTINCT FROM 'validated' OR i.customer_id::text IS DISTINCT FROM b->>'customerId'
  OR i.metering_point_id IS DISTINCT FROM b->>'pointId' OR i.grid_area_code IS DISTINCT FROM b->>'gridArea' OR i.transaction_reference IS DISTINCT FROM b->>'li'
  OR to_jsonb(i)-ARRAY['created_at','updated_at','validation_status','validation_report','render_status','outbox_status','ack_status','ediel_message_id','outbound_request_id'] IS DISTINCT FROM o.intent_binding
  OR r.payload->>'environment' IS DISTINCT FROM b->>'environment' OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text
  OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.operation_id IS DISTINCT FROM operation OR r.customer_id::text IS DISTINCT FROM b->>'customerId'
  OR r.site_id::text IS DISTINCT FROM b->>'siteId' OR r.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId'
 THEN RAISE EXCEPTION 'customer_masterdata_cancellation_private_scope_required';END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(raw);own:=w#>'{objects,0}';tokens:=gridex_received_sources.closure_wire_tokens_v2(raw);
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';
 SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';
 SELECT t INTO unt FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNT';
 SELECT t INTO unz FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNZ';
 SELECT gridex_received_sources.closure_wire_tokens_v2(m.raw_payload) INTO original_tokens FROM public.ediel_messages m WHERE m.company_id=c AND m.id=o.original_message_id;
 IF raw IS NULL OR w IS NULL OR w->>'code' IS DISTINCT FROM 'Z03' OR own->>'reason' IS DISTINCT FROM 'Z24'
  OR own->>'li' IS DISTINCT FROM b->>'li' OR own->>'installationPoint' IS DISTINCT FROM b->>'pointId' OR own->>'installationAgency' IS DISTINCT FROM b->>'identityAgency'
  OR own->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity' OR own->>'customerQualifier' IS DISTINCT FROM b->>'customerQualifier' OR own->>'customerAgency' IS DISTINCT FROM '260'
  OR own->>'gridArea' IS DISTINCT FROM b->>'gridArea' OR own->>'start' IS DISTINCT FROM b#>>'{sourceObject,start}'
  OR w->>'sender' IS DISTINCT FROM b->>'legalSenderId' OR w->>'receiver' IS DISTINCT FROM b->>'legalReceiverId'
  OR w->>'bgmId' IS DISTINCT FROM i.interchange_reference OR unb#>>'{elements,2,0}' IS DISTINCT FROM i.sender_ediel_id OR unb#>>'{elements,3,0}' IS DISTINCT FROM i.receiver_ediel_id
  OR coalesce(unb#>>'{elements,2,2}','') IS DISTINCT FROM coalesce(i.sender_subaddress,'') OR coalesce(unb#>>'{elements,3,2}','') IS DISTINCT FROM coalesce(i.receiver_subaddress,'')
  OR unb#>>'{elements,5,0}' IS DISTINCT FROM i.interchange_reference OR unb#>>'{elements,7,0}' IS DISTINCT FROM i.application_reference
  OR unh#>>'{elements,1,0}' IS DISTINCT FROM i.message_reference
  OR unb->'index' >= unh->'index' OR unh->'index' >= unt->'index' OR unt->'index' >= unz->'index'
  OR unt#>>'{elements,1,0}' IS DISTINCT FROM ((unt->>'index')::int-(unh->>'index')::int+1)::text
  OR unt#>>'{elements,2,0}' IS DISTINCT FROM unh#>>'{elements,1,0}' OR unz#>>'{elements,1,0}' IS DISTINCT FROM '1' OR unz#>>'{elements,2,0}' IS DISTINCT FROM unb#>>'{elements,5,0}'
  OR unb->'index' IS DISTINCT FROM (SELECT to_jsonb(min((t->>'index')::int)) FROM jsonb_array_elements(tokens)t)
  OR unz->'index' IS DISTINCT FROM (SELECT to_jsonb(max((t->>'index')::int)) FROM jsonb_array_elements(tokens)t)
  OR unh#>'{elements,2}' IS DISTINCT FROM (SELECT t#>'{elements,2}' FROM jsonb_array_elements(original_tokens)t WHERE t->>'tag'='UNH')
  OR unb#>'{elements,1}' IS DISTINCT FROM (SELECT t#>'{elements,1}' FROM jsonb_array_elements(original_tokens)t WHERE t->>'tag'='UNB')
  OR EXISTS(SELECT FROM unnest(ARRAY['UNB','UNH','BGM','UNT','UNZ']) tag WHERE (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'=tag)<>1)
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ANJ')<>1
  OR (SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ANJ') IS DISTINCT FROM (SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(original_tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ANJ')
 THEN RAISE EXCEPTION 'customer_masterdata_cancellation_actual_wire_required';END IF;
 PERFORM gridex_switch_cancellations.require_original_method_v1(c,o.original_message_id,o.original_hash,i.environment,raw);
 ud:=gridex_customer_masterdata.wire_ud_v1(raw);
 IF ud IS NULL OR jsonb_array_length(ud)<>1 THEN RAISE EXCEPTION 'customer_masterdata_cancellation_actual_wire_required';END IF;
 FOR obj IN SELECT item FROM jsonb_array_elements(ud)item LOOP IF obj->'customerIdentity' IS DISTINCT FROM q->'customerIdentity' OR obj->'endUserMasterdata' IS DISTINCT FROM gridex_customer_masterdata.wire_masterdata_v1(q->'endUserMasterdata') THEN RAISE EXCEPTION 'customer_masterdata_cancellation_actual_wire_changed';END IF;END LOOP;
 SELECT * INTO source FROM gridex_customer_masterdata.preparations WHERE id=(q->>'sourceContextId')::uuid AND company_id=c FOR SHARE;
 IF source.id IS NULL OR source.cancellation_origin_id IS NOT NULL THEN RAISE EXCEPTION 'customer_masterdata_cancellation_original_scope_required';END IF;
 RETURN q||jsonb_build_object('cancellationBinding',jsonb_build_object('operationId',o.id,'switchRequestId',o.switch_id,'actorUserId',actor,'intentId',i.id,'routeId',i.communication_route_id,'environment',i.environment,'originalMessageId',o.original_message_id,'originalHash',o.original_hash,'payloadHash',encode(sha256(convert_to(raw,'UTF8')),'hex')));
END$$;

--
-- Name: customer_source_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.customer_source_v1(c uuid, sw uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;m public.ediel_messages%rowtype;p gridex_customer_masterdata.preparations%rowtype;b jsonb;
BEGIN
 IF phase NOT IN('prepare','send') OR phase IS NULL THEN RAISE EXCEPTION 'customer_masterdata_cancellation_phase_required';END IF;
 PERFORM gridex_switch_cancellations.prelock_customer_source_v1(c,sw);
 PERFORM gridex_customer_life_events.require_actor_v1(c,actor,phase);
 q:=gridex_switch_cancellations.context_v1(c,sw,actor,phase='prepare');
 IF q->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'customer_masterdata_cancellation_source_held';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=(q->>'originalMessageId')::uuid AND company_id=c FOR SHARE;
 SELECT prep.* INTO p FROM gridex_customer_masterdata.originals o JOIN gridex_customer_masterdata.preparations prep ON prep.id=o.preparation_id WHERE o.company_id=c AND o.message_id=m.id AND o.payload_hash=m.immutable_payload_hash FOR SHARE OF prep;
 IF p.id IS NULL OR p.actor_user_id IS DISTINCT FROM m.created_by OR p.customer_id IS DISTINCT FROM m.customer_id OR m.customer_id::text IS DISTINCT FROM q->>'customerId'
  OR p.cancellation_origin_id IS NOT NULL OR (p.environment IS NOT NULL AND p.environment IS DISTINCT FROM m.environment)
  OR m.immutable_payload_hash IS DISTINCT FROM q->>'originalHash' OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.intent_id IS NULL OR m.communication_route_id IS NULL THEN RAISE EXCEPTION 'customer_masterdata_cancellation_original_scope_required';END IF;
 -- This is a real prepare/current-source read. The ordinary SEND-only reader
 -- remains unchanged; a prepare-only writer does not borrow SEND authority.
 PERFORM gridex_customer_masterdata.require_current_v1(c,m.id,actor,phase);
 b:=gridex_customer_masterdata.basis_v1(c,p.customer_id,actor,p.as_of,p.environment,phase,p.observed_at,p.basis#>'{sourceProof,sourceIds}');
 IF b IS DISTINCT FROM p.basis THEN RAISE EXCEPTION 'customer_masterdata_cancellation_original_source_changed';END IF;
 RETURN (b-'sourceProof')||jsonb_build_object('sourceContextId',p.id,'messageBinding',jsonb_build_object('id',m.id,'environment',m.environment,'intentId',m.intent_id,'routeId',m.communication_route_id,'payloadHash',m.immutable_payload_hash),
  'cancellationSourceBinding',jsonb_build_object('switchRequestId',sw,'actorUserId',actor,'originalMessageId',m.id,'originalHash',m.immutable_payload_hash,'environment',m.environment,'originalPreparerId',p.actor_user_id));
END$$;

--
-- Name: origin_immutable_v1(); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.origin_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$BEGIN
 IF TG_OP='UPDATE' AND OLD.message_id IS NULL AND NEW.message_id IS NOT NULL AND NEW.payload_hash IS NOT NULL
  AND to_jsonb(NEW)-ARRAY['message_id','payload_hash'] IS NOT DISTINCT FROM to_jsonb(OLD)-ARRAY['message_id','payload_hash'] THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'switch_cancellation_origin_immutable';END $$;

--
-- Name: original_method_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.original_method_v1(c uuid, original uuid, expected_hash text, expected_environment text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;
 binding gridex_received_sources.switch_contract_request_bindings%rowtype;
 d gridex_metering_method_changes.contract_request_declarations%rowtype;
 w jsonb;own jsonb;method text;frozen jsonb;prior_legal jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=original AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c FOR SHARE;
 SELECT * INTO binding FROM gridex_received_sources.switch_contract_request_bindings WHERE message_id=m.id AND company_id=c FOR SHARE;
 SELECT * INTO d FROM gridex_metering_method_changes.contract_request_declarations WHERE id=binding.declaration_id AND company_id=c FOR SHARE;
 IF m.id IS NULL OR o.message_id IS NULL OR binding.message_id IS NULL OR d.id IS NULL
  OR m.environment IS DISTINCT FROM expected_environment OR m.direction IS DISTINCT FROM 'outbound'
  OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM expected_hash
  OR o.payload_hash IS DISTINCT FROM expected_hash OR binding.payload_hash IS DISTINCT FROM expected_hash
  OR expected_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR gridex_received_sources.sent_source_is_current_v1(m) IS NOT TRUE THEN RETURN NULL;END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);own:=w#>'{objects,0}';
 method:=gridex_received_sources.switch_requested_method_v1(m.raw_payload);
 IF w IS NULL OR own IS DISTINCT FROM o.original_object OR (own->>'reason' IN('Z22','Z23')) IS NOT TRUE
  OR method IS NULL OR method IS DISTINCT FROM binding.requested_method OR method IS DISTINCT FROM d.requested_method
  OR d.environment IS DISTINCT FROM m.environment OR d.contract_id IS DISTINCT FROM o.contract_id OR d.protected_contract_hash IS DISTINCT FROM o.contract_hash
  OR d.customer_id IS DISTINCT FROM m.customer_id OR d.site_id IS DISTINCT FROM m.site_id OR d.metering_point_id IS DISTINCT FROM m.metering_point_id
  OR d.point_id IS DISTINCT FROM own->>'point' OR d.identity_agency IS DISTINCT FROM own->>'identityAgency'
  OR d.grid_area_code IS DISTINCT FROM own->>'gridArea' OR d.legal_sender_id IS DISTINCT FROM w->>'sender' OR d.legal_receiver_id IS DISTINCT FROM w->>'receiver'
 THEN RETURN NULL;END IF;
 prior_legal:=gridex_ediel_inbound_context.require_v1(c,m.id);
 IF d.legal_actor_id::text IS DISTINCT FROM prior_legal->>'legalActorId' THEN RETURN NULL;END IF;
 -- This is the existing immutable declaration's original evidence projection.
 -- No current-declaration selection, revocation lookup or contract reapproval.
 frozen:=jsonb_build_object('status','authorized','declarationId',d.id,'companyId',c,'environment',d.environment,'contractId',d.contract_id,
  'contractRevision',d.contract_revision,'protectedContractHash',d.protected_contract_hash,'agreementSha256',d.agreement_sha256,
  'customerId',d.customer_id,'siteId',d.site_id,'meteringPointId',d.metering_point_id,'pointId',d.point_id,'identityAgency',d.identity_agency,
  'legalActorId',d.legal_actor_id,'legalSenderId',d.legal_sender_id,'legalReceiverId',d.legal_receiver_id,'gridArea',d.grid_area_code,
  'requestedMethod',d.requested_method,'sourceReference',d.source_reference,'sourceVersion',d.source_version,'sourceDigest',d.source_sha256);
 IF binding.source_basis IS DISTINCT FROM frozen THEN RETURN NULL;END IF;
 RETURN method;
END$$;

--
-- Name: prelock_customer_message_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.prelock_customer_message_v1(c uuid, message uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE sw uuid;
BEGIN
 SELECT o.switch_id INTO sw FROM gridex_switch_cancellations.origins o JOIN public.ediel_messages m ON m.company_id=o.company_id AND (m.id=o.message_id OR m.intent_id=o.intent_id) WHERE m.company_id=c AND m.id=message;
 IF sw IS NOT NULL THEN PERFORM gridex_switch_cancellations.prelock_customer_source_v1(c,sw,message);END IF;
END$$;

--
-- Name: prelock_customer_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.prelock_customer_source_v1(c uuid, sw uuid, message uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original uuid;customer uuid;after_original uuid;after_customer uuid;source_ids jsonb;after_sources jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT outbound_z03_message_id,customer_id INTO original,customer FROM public.supplier_switch_requests WHERE company_id=c AND id=sw;
 SELECT coalesce(jsonb_agg(DISTINCT v.source_message_id ORDER BY v.source_message_id),'[]') INTO source_ids FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=c AND v.customer_id=customer;
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=c AND m.id IN(
  SELECT original UNION SELECT message UNION
  SELECT v.source_message_id FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=c AND v.customer_id=customer UNION
  SELECT value::uuid FROM gridex_customer_masterdata.originals o JOIN gridex_customer_masterdata.preparations p ON p.id=o.preparation_id CROSS JOIN LATERAL jsonb_array_elements_text(p.basis#>'{sourceProof,sourceIds}') WHERE o.company_id=c AND o.message_id=original
 ) ORDER BY m.id FOR UPDATE;
 SELECT outbound_z03_message_id,customer_id INTO after_original,after_customer FROM public.supplier_switch_requests WHERE company_id=c AND id=sw;
 SELECT coalesce(jsonb_agg(DISTINCT v.source_message_id ORDER BY v.source_message_id),'[]') INTO after_sources FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=c AND v.customer_id=customer;
 IF ROW(after_original,after_customer) IS DISTINCT FROM ROW(original,customer) OR after_sources IS DISTINCT FROM source_ids THEN RAISE EXCEPTION 'customer_masterdata_cancellation_source_epoch_changed' USING ERRCODE='40001';END IF;
END$$;

--
-- Name: require_original_method_v1(uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_switch_cancellations; Owner: -
--

CREATE FUNCTION gridex_switch_cancellations.require_original_method_v1(c uuid, original uuid, expected_hash text, expected_environment text, raw text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE method text:=gridex_switch_cancellations.original_method_v1(c,original,expected_hash,expected_environment);
BEGIN
 IF method IS NULL OR gridex_received_sources.switch_requested_method_v1(raw) IS DISTINCT FROM method
 THEN RAISE EXCEPTION 'switch_cancellation_exact_original_method_required';END IF;
END$$;

--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.actor_v1(c uuid, a uuid, p text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 LOCK TABLE auth.users,public.user_profiles,public.company_memberships,public.user_permissions,public.role_permissions,public.user_roles,public.roles,public.permissions IN SHARE MODE;
 LOCK TABLE public.companies IN SHARE MODE;
 IF a IS NULL OR c IS NULL OR NOT EXISTS(SELECT FROM auth.users WHERE id=a)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=a AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE user_id=a AND company_id=c AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(a,c,p) IS NOT TRUE THEN RAISE EXCEPTION 'transport_exception_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

--
-- Name: case_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.case_v1(m public.ediel_messages, s jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE k text:=s->>'case';a gridex_certificate_trust.authority_versions%rowtype;prior jsonb:='[]';cdps jsonb;crls jsonb;
BEGIN
 IF k='temporary_encryption_failure' THEN
  IF s#>>'{incident,temporaryOnly}' IS DISTINCT FROM 'true' OR coalesce(s#>>'{incident,failureCode}','') NOT IN('encryption_runtime_unavailable','cms_encryption_failed')
   OR gridex_transport_exception.hash_v1(s#>>'{incident,originalSha256}') IS NOT TRUE THEN RAISE EXCEPTION 'transport_exception_actual_temporary_encryption_failure_required';END IF;
 ELSIF k='recipient_certificate_unavailable' THEN
  IF s#>>'{incident,directorySearchCompleted}' IS DISTINCT FROM 'true' OR s#>>'{incident,resultCount}' IS DISTINCT FROM '0'
   OR gridex_transport_exception.hash_v1(s#>>'{incident,originalSha256}') IS NOT TRUE
   OR EXISTS(SELECT FROM gridex_certificate_trust.authority_versions WHERE company_id=m.company_id AND environment=m.environment
    AND receiver_ediel_id=m.receiver_ediel_id AND valid_from<=clock_timestamp() AND valid_to>clock_timestamp())
   THEN RAISE EXCEPTION 'transport_exception_completed_no_certificate_search_required';END IF;
 ELSIF k='crl_refresh_failure' THEN
  cdps:=s#>'{incident,cdpResults}';crls:=s#>'{incident,priorCrlSha256}';
  IF s#>>'{incident,allCertificateCdpsAttempted}' IS DISTINCT FROM 'true' OR s#>>'{incident,nearestPreviousCachedCrl}' IS DISTINCT FROM 'true'
   OR jsonb_typeof(cdps) IS DISTINCT FROM 'array' OR jsonb_typeof(crls) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'transport_exception_all_cdp_failure_and_nearest_previous_crl_required';END IF;
  IF jsonb_array_length(cdps) NOT BETWEEN 1 AND 16 OR jsonb_array_length(crls) NOT BETWEEN 1 AND 16
   OR EXISTS(SELECT FROM jsonb_array_elements(cdps) c WHERE c->>'result' IS DISTINCT FROM 'failed' OR nullif(c->>'cdp','') IS NULL OR gridex_transport_exception.hash_v1(c->>'originalSha256') IS NOT TRUE)
   OR (SELECT count(DISTINCT c->>'cdp') FROM jsonb_array_elements(cdps) c)<>jsonb_array_length(cdps)
   THEN RAISE EXCEPTION 'transport_exception_actual_all_cdp_failure_required';END IF;
  SELECT * INTO a FROM gridex_certificate_trust.authority_versions WHERE id=(s#>>'{incident,certificateAuthorityId}')::uuid
   AND company_id=m.company_id AND environment=m.environment AND receiver_ediel_id=m.receiver_ediel_id
   AND valid_from<=clock_timestamp() AND valid_to>clock_timestamp() FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'transport_exception_actual_previous_crl_owner_required';END IF;
  SELECT jsonb_agg(encode(sha256(convert_to(c#>>'{}','UTF8')),'hex') ORDER BY n) INTO prior FROM jsonb_array_elements(a.crls) WITH ORDINALITY x(c,n);
  IF prior IS DISTINCT FROM crls THEN RAISE EXCEPTION 'transport_exception_previous_crl_original_changed';END IF;
 ELSE RAISE EXCEPTION 'transport_exception_exact_source_case_required';END IF;
 RETURN prior;
END$$;

--
-- Name: hash_v1(text); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.hash_v1(v text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$SELECT coalesce(v~'^[a-f0-9]{64}$',false)$_$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'transport_exception_journal_immutable';END$$;

--
-- Name: publish_v1(uuid, uuid, uuid, bytea, bytea, text); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.publish_v1(c uuid, mid uuid, actor uuid, source bytea, approval bytea, publisher text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s jsonb;a jsonb;m public.ediel_messages%rowtype;reviewer uuid;vf timestamptz;vt timestamptz;result uuid;sd text;ad text;
BEGIN
 IF publisher IS DISTINCT FROM 'gridex_ediel_transport_exception_owner' OR source IS NULL OR approval IS NULL
  OR octet_length(source) NOT BETWEEN 1 AND 1048576 OR octet_length(approval) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'transport_exception_qualified_source_owner_required' USING ERRCODE='42501';END IF;
 s:=convert_from(source,'UTF8')::jsonb;a:=convert_from(approval,'UTF8')::jsonb;sd:=encode(sha256(source),'hex');ad:=encode(sha256(approval),'hex');
 PERFORM gridex_transport_exception.actor_v1(c,actor,'communication.write');
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;
 PERFORM gridex_transport_exception.scope_v1(m,s);PERFORM gridex_transport_exception.case_v1(m,s);
 reviewer:=(a->>'approvedBy')::uuid;PERFORM gridex_transport_exception.actor_v1(c,reviewer,'communication.write');
 vf:=(a->>'validFrom')::timestamptz;vt:=(a->>'validTo')::timestamptz;
 IF jsonb_typeof(a) IS DISTINCT FROM 'object' OR a->>'schema' IS DISTINCT FROM 'gridex_transport_exception_approval_v1'
  OR a->>'sourceDigest' IS DISTINCT FROM sd OR a->>'companyId' IS DISTINCT FROM c::text OR a->>'messageId' IS DISTINCT FROM mid::text
  OR a->>'case' IS DISTINCT FROM s->>'case' OR a->>'approved' IS DISTINCT FROM 'true' OR nullif(a->>'approvalReference','') IS NULL
  OR vf IS NULL OR vt IS NULL OR vf>clock_timestamp() OR vt<=clock_timestamp() OR vt>vf+interval '24 hours'
  OR vt>(s#>>'{tls,validTo}')::timestamptz OR vt>(s#>>'{counterparty,validTo}')::timestamptz
  OR (s#>>'{incident,observedAt}')::timestamptz IS NULL OR (s#>>'{incident,observedAt}')::timestamptz>clock_timestamp()
  OR (s#>>'{incident,observedAt}')::timestamptz<clock_timestamp()-interval '24 hours'
  OR coalesce(a->>'maximumAttempts','') !~ '^[1-3]$' THEN RAISE EXCEPTION 'transport_exception_exact_current_bounded_approval_required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text||'|'||mid::text||'|transport_exception',0));
 INSERT INTO gridex_transport_exception.approvals(company_id,message_id,environment,source_original,approval_original,source_digest,approval_digest,source_facts,approval_facts,approved_by,kind,valid_from,valid_to,maximum_attempts)
 VALUES(c,mid,m.environment,source,approval,sd,ad,s,a,reviewer,s->>'case',vf,vt,(a->>'maximumAttempts')::integer)
 ON CONFLICT(company_id,message_id,source_digest,approval_digest) DO NOTHING RETURNING id INTO result;
 IF result IS NULL THEN SELECT id INTO STRICT result FROM gridex_transport_exception.approvals WHERE company_id=c AND message_id=mid AND source_digest=sd AND approval_digest=ad;END IF;
 RETURN result;
END$_$;

--
-- Name: read_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.read_v1(c uuid, mid uuid, actor uuid, eid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_transport_exception.approvals%rowtype;m public.ediel_messages%rowtype;prior jsonb;
BEGIN
 PERFORM gridex_transport_exception.actor_v1(c,actor,'communication.send');
 LOCK TABLE gridex_transport_exception.revocations IN SHARE MODE;
 SELECT * INTO a FROM gridex_transport_exception.approvals WHERE id=eid AND company_id=c AND message_id=mid FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','missing',ARRAY['transport_exception_approved_source_absent']);END IF;
 IF a.valid_from>clock_timestamp() OR a.valid_to<=clock_timestamp() OR EXISTS(SELECT FROM gridex_transport_exception.revocations WHERE approval_id=a.id)
  THEN RETURN jsonb_build_object('status','held','missing',ARRAY['transport_exception_source_revoked_or_expired']);END IF;
 PERFORM gridex_transport_exception.actor_v1(c,a.approved_by,'communication.write');
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=a.environment FOR SHARE;
 IF a.source_digest IS DISTINCT FROM encode(sha256(a.source_original),'hex') OR a.approval_digest IS DISTINCT FROM encode(sha256(a.approval_original),'hex')
  OR a.source_facts IS DISTINCT FROM convert_from(a.source_original,'UTF8')::jsonb OR a.approval_facts IS DISTINCT FROM convert_from(a.approval_original,'UTF8')::jsonb
  THEN RAISE EXCEPTION 'transport_exception_original_integrity_required';END IF;
 PERFORM gridex_transport_exception.scope_v1(m,a.source_facts);prior:=gridex_transport_exception.case_v1(m,a.source_facts);
 RETURN jsonb_build_object('status','authorized','version',1,'approvalId',a.id,'companyId',c,'environment',a.environment,'messageId',mid,'actorUserId',actor,
  'originalHash',m.immutable_payload_hash,'routeId',m.communication_route_id,'senderEdielId',m.sender_ediel_id,'receiverEdielId',m.receiver_ediel_id,'receiverEmail',m.receiver_email,
  'case',a.kind,'sourceDigest',a.source_digest,'approvalDigest',a.approval_digest,'tlsEvidenceDigest',a.source_facts#>>'{tls,originalSha256}',
  'validFrom',a.valid_from,'validTo',a.valid_to,'priorCrlSha256',prior,
  'certificateAuthorityId',CASE WHEN a.kind='crl_refresh_failure' THEN a.source_facts#>>'{incident,certificateAuthorityId}' ELSE NULL END,
  'cdpLocations',CASE WHEN a.kind='crl_refresh_failure' THEN (SELECT jsonb_agg(x->>'cdp' ORDER BY x->>'cdp') FROM jsonb_array_elements(a.source_facts#>'{incident,cdpResults}') x) ELSE '[]'::jsonb END);
END$$;

--
-- Name: revoke_v1(uuid, uuid, bytea, text); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.revoke_v1(eid uuid, actor uuid, original bytea, publisher text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_transport_exception.approvals%rowtype;f jsonb;
BEGIN IF publisher IS DISTINCT FROM 'gridex_ediel_transport_exception_owner' OR original IS NULL OR octet_length(original) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'transport_exception_qualified_source_owner_required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_transport_exception.approvals WHERE id=eid FOR SHARE;PERFORM gridex_transport_exception.actor_v1(a.company_id,actor,'communication.write');
 f:=convert_from(original,'UTF8')::jsonb;
 IF f->>'schema' IS DISTINCT FROM 'gridex_transport_exception_revocation_v1' OR f->>'approvalId' IS DISTINCT FROM eid::text OR f->>'companyId' IS DISTINCT FROM a.company_id::text OR nullif(f->>'reasonReference','') IS NULL THEN RAISE EXCEPTION 'transport_exception_actual_revocation_original_required';END IF;
 INSERT INTO gridex_transport_exception.revocations VALUES(eid,actor,original,encode(sha256(original),'hex'),clock_timestamp()) ON CONFLICT(approval_id) DO NOTHING;
END$$;

--
-- Name: scope_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.scope_v1(m public.ediel_messages, s jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.ediel_route_profiles%rowtype;tls jsonb:=s->'tls';counterparty jsonb:=s->'counterparty';
BEGIN
 LOCK TABLE public.tenant_actor_identifiers,public.tenant_actor_roles,public.platform_actor_identifiers,public.platform_actor_roles,public.communication_routes,public.ediel_route_profiles,gridex_certificate_trust.authority_versions IN SHARE MODE;
 IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR s->>'schema' IS DISTINCT FROM 'gridex_transport_exception_incident_v1'
  OR s->>'normativeSha256' IS DISTINCT FROM '5204d4514774b04b8eedb039e1f4799ed447c7fef14554577935e2d7bd93f951'
  OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT'
  OR m.raw_payload IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR s->>'companyId' IS DISTINCT FROM m.company_id::text OR s->>'messageId' IS DISTINCT FROM m.id::text
  OR s->>'environment' IS DISTINCT FROM m.environment OR s->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash
  OR s->>'routeId' IS DISTINCT FROM m.communication_route_id::text OR s->>'senderEdielId' IS DISTINCT FROM m.sender_ediel_id
  OR s->>'receiverEdielId' IS DISTINCT FROM m.receiver_ediel_id OR s->>'receiverEmail' IS DISTINCT FROM m.receiver_email
  THEN RAISE EXCEPTION 'transport_exception_current_immutable_scope_required';END IF;
 PERFORM gridex_ediel_outbound_owner.require_v1(m.company_id,m.id);
 SELECT * INTO r FROM public.ediel_route_profiles WHERE id=m.route_profile_id AND company_id=m.company_id
  AND communication_route_id=m.communication_route_id AND environment=m.environment FOR SHARE;
 PERFORM id FROM public.communication_routes WHERE id=m.communication_route_id AND company_id=m.company_id AND is_active FOR SHARE;
 IF NOT FOUND OR r.id IS NULL OR r.is_enabled IS NOT TRUE OR r.is_active IS NOT TRUE OR r.tls_required IS NOT TRUE
  OR r.sender_ediel_id IS DISTINCT FROM m.sender_ediel_id OR r.receiver_ediel_id IS DISTINCT FROM m.receiver_ediel_id
  OR coalesce(nullif(r.smtp_to,''),nullif(r.receiver_email,'')) IS DISTINCT FROM m.receiver_email
  OR (r.valid_from IS NOT NULL AND r.valid_from>clock_timestamp()) OR (r.valid_to IS NOT NULL AND r.valid_to<=clock_timestamp())
  THEN RAISE EXCEPTION 'transport_exception_current_owned_tls_route_required';END IF;
 IF (SELECT count(*) FROM public.tenant_actor_identifiers x WHERE x.company_id=m.company_id AND x.environment=m.environment
  AND x.identifier_type='EdielId' AND x.identifier_value=m.sender_ediel_id AND x.valid_from<=clock_timestamp() AND (x.valid_to IS NULL OR x.valid_to>clock_timestamp()))<>1
  OR NOT EXISTS(SELECT FROM public.tenant_actor_roles x WHERE x.company_id=m.company_id AND x.environment=m.environment AND x.role_code='electricity_supplier'
   AND x.valid_from<=clock_timestamp() AND (x.valid_to IS NULL OR x.valid_to>clock_timestamp())
   AND EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=x.company_id AND i.environment=x.environment AND i.actor_id=x.actor_id
    AND i.identifier_type='EdielId' AND i.identifier_value=m.sender_ediel_id AND i.valid_from<=clock_timestamp() AND (i.valid_to IS NULL OR i.valid_to>clock_timestamp())))
  OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers x JOIN public.platform_actor_roles a ON a.actor_id=x.actor_id
   WHERE x.identifier_type='EdielId' AND x.identifier_value=m.receiver_ediel_id AND x.is_verified
    AND (x.valid_from IS NULL OR x.valid_from<=clock_timestamp()) AND (x.valid_to IS NULL OR x.valid_to>clock_timestamp())
    AND a.actor_role='grid_owner' AND a.is_active)
  THEN RAISE EXCEPTION 'transport_exception_current_legal_namespace_required';END IF;
 IF jsonb_typeof(tls) IS DISTINCT FROM 'object' OR tls->>'required' IS DISTINCT FROM 'true'
  OR tls->>'allRelayHopsVerified' IS DISTINCT FROM 'true' OR tls->>'certificateVerified' IS DISTINCT FROM 'true'
  OR coalesce(tls->>'minimumVersion','') NOT IN('TLS1.2','TLS1.3')
  OR gridex_transport_exception.hash_v1(tls->>'originalSha256') IS NOT TRUE
  OR nullif(tls->>'originalReference','') IS NULL OR (tls->>'validFrom')::timestamptz IS NULL OR (tls->>'validTo')::timestamptz IS NULL
  OR (tls->>'validFrom')::timestamptz>clock_timestamp() OR (tls->>'validTo')::timestamptz<=clock_timestamp()
  OR jsonb_typeof(counterparty) IS DISTINCT FROM 'object' OR counterparty->>'receiverEdielId' IS DISTINCT FROM m.receiver_ediel_id
  OR counterparty->>'temporaryReserveConfirmed' IS DISTINCT FROM 'true'
  OR gridex_transport_exception.hash_v1(counterparty->>'originalSha256') IS NOT TRUE OR nullif(counterparty->>'originalReference','') IS NULL
  OR (counterparty->>'validFrom')::timestamptz IS NULL OR (counterparty->>'validTo')::timestamptz IS NULL
  OR (counterparty->>'validFrom')::timestamptz>clock_timestamp() OR (counterparty->>'validTo')::timestamptz<=clock_timestamp()
  THEN RAISE EXCEPTION 'transport_exception_current_end_to_end_tls_and_counterparty_originals_required';END IF;
END$$;

--
-- Name: stage_v1(jsonb, jsonb); Type: FUNCTION; Schema: gridex_transport_exception; Owner: -
--

CREATE FUNCTION gridex_transport_exception.stage_v1(i jsonb, r jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action text:=i->>'action';c uuid:=(i->>'companyId')::uuid;mid uuid:=(i->>'messageId')::uuid;actor uuid:=(i->>'actorUserId')::uuid;
 attempt uuid:=(i->>'attemptId')::uuid;b jsonb:=i#>'{binding,transportException}';a jsonb;o gridex_transport_exception.operations%rowtype;m public.ediel_messages%rowtype;limit_attempts integer;event_kind text;
BEGIN
 IF action='prepare' AND r->>'proceed'='true' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=mid AND company_id=c FOR SHARE;
  IF b IS NULL OR b='null'::jsonb THEN
   IF m.direction='outbound' AND m.environment='production'
    AND i#>>'{binding,mimeMode}' IS DISTINCT FROM 'ediel-smime-enveloped' THEN RAISE EXCEPTION 'transport_exception_actual_approved_plaintext_source_required';END IF;
   RETURN;
  END IF;
  a:=gridex_transport_exception.read_v1(c,mid,actor,(b->>'approvalId')::uuid);
  IF a->>'status' IS DISTINCT FROM 'authorized' OR b IS DISTINCT FROM (a-ARRAY['status','version','companyId','environment','messageId','actorUserId','routeId','senderEdielId','receiverEdielId','receiverEmail','validFrom','validTo'])
   OR ((a->>'case'='crl_refresh_failure') IS DISTINCT FROM (i#>>'{binding,mimeMode}'='ediel-smime-enveloped'))
   THEN RAISE EXCEPTION 'transport_exception_fresh_exact_attempt_binding_required';END IF;
  SELECT * INTO o FROM gridex_transport_exception.operations WHERE attempt_id=attempt FOR SHARE;
  IF FOUND THEN
   IF o.company_id IS DISTINCT FROM c OR o.message_id IS DISTINCT FROM mid OR o.actor_user_id IS DISTINCT FROM actor OR o.environment IS DISTINCT FROM m.environment OR o.binding IS DISTINCT FROM b
    THEN RAISE EXCEPTION 'transport_exception_attempt_scope_changed';END IF;RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended((a->>'approvalId')||'|transport_exception_budget',0));
  SELECT maximum_attempts INTO STRICT limit_attempts FROM gridex_transport_exception.approvals WHERE id=(a->>'approvalId')::uuid FOR SHARE;
  IF (SELECT count(*) FROM gridex_transport_exception.operations WHERE approval_id=(a->>'approvalId')::uuid)>=limit_attempts THEN RAISE EXCEPTION 'transport_exception_bounded_attempt_budget_exhausted';END IF;
  INSERT INTO gridex_transport_exception.operations VALUES(attempt,(a->>'approvalId')::uuid,c,mid,m.environment,actor,b,clock_timestamp());
  INSERT INTO gridex_transport_exception.events(attempt_id,company_id,message_id,kind,facts) VALUES(attempt,c,mid,'prepared',r);
  INSERT INTO gridex_transport_exception.alarms(attempt_id,company_id,message_id,responsible_user_id,facts)
   SELECT attempt,c,mid,approved_by,jsonb_build_object('case',a->>'case','sourceDigest',a->>'sourceDigest','approvalDigest',a->>'approvalDigest','tlsEvidenceDigest',a->>'tlsEvidenceDigest','mandatoryTls',true,'validTo',a->>'validTo','administratorAlarm',true)
   FROM gridex_transport_exception.approvals WHERE id=(a->>'approvalId')::uuid;
 ELSIF action IN('enter','observe','result','release') THEN
  SELECT * INTO o FROM gridex_transport_exception.operations WHERE attempt_id=attempt FOR SHARE;IF NOT FOUND THEN RETURN;END IF;
  IF o.company_id IS DISTINCT FROM c OR o.message_id IS DISTINCT FROM mid OR o.actor_user_id IS DISTINCT FROM actor OR o.environment IS DISTINCT FROM i->>'environment' THEN RAISE EXCEPTION 'transport_exception_attempt_scope_changed';END IF;
  IF action='enter' AND r->>'proceed'='true' THEN
   a:=gridex_transport_exception.read_v1(c,mid,actor,o.approval_id);
   IF a->>'status' IS DISTINCT FROM 'authorized' OR o.binding IS DISTINCT FROM (a-ARRAY['status','version','companyId','environment','messageId','actorUserId','routeId','senderEdielId','receiverEdielId','receiverEmail','validFrom','validTo']) THEN RAISE EXCEPTION 'transport_exception_fresh_entry_authority_required';END IF;event_kind:='entered';
  ELSIF action IN('observe','result') AND EXISTS(SELECT FROM gridex_transport_exception.events WHERE attempt_id=attempt AND kind='entered') THEN event_kind:='observed';
  ELSIF action='release' THEN event_kind:='released';ELSE RETURN;END IF;
  INSERT INTO gridex_transport_exception.events(attempt_id,company_id,message_id,kind,facts) VALUES(attempt,c,mid,event_kind,r) ON CONFLICT(attempt_id,kind) DO NOTHING;
 END IF;
END$$;

--
-- Name: inbound_email_attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inbound_email_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    inbound_email_message_id uuid,
    filename text,
    mime_type text,
    size_bytes bigint,
    storage_path text,
    raw_text text,
    is_edifact_candidate boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: attachment_hash_v1(public.inbound_email_attachments); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.attachment_hash_v1(a public.inbound_email_attachments) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT gridex_unattributed_intake.sha_v1(jsonb_build_object('id',a.id,'mail',a.inbound_email_message_id,
  'raw',gridex_unattributed_intake.sha_v1(a.raw_text),'filename',a.filename,'mime',a.mime_type,
  'candidate',a.is_edifact_candidate,'size',a.size_bytes,'storage',a.storage_path)::text)
$$;

--
-- Name: attachment_set_v1(uuid); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.attachment_set_v1(mail_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT gridex_unattributed_intake.sha_v1(coalesce(jsonb_agg(jsonb_build_object('id',a.id,
  'hash',gridex_unattributed_intake.attachment_hash_v1(a)) ORDER BY a.id),'[]')::text)
 FROM public.inbound_email_attachments a WHERE a.inbound_email_message_id=mail_id
$$;

--
-- Name: capture_custody_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.capture_custody_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_unattributed_intake.raw_births%rowtype;m public.inbound_email_messages%rowtype;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'ediel_technical_custody_birth_only';END IF;
 IF gridex_unattributed_intake.service_session_v1() IS NOT TRUE THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='inbound_email_messages' THEN
  INSERT INTO gridex_unattributed_intake.raw_births(inbound_email_message_id,snapshot_hash)
   VALUES(NEW.id,gridex_unattributed_intake.raw_hash_v1(NEW));
 ELSE
  SELECT * INTO m FROM public.inbound_email_messages WHERE id=NEW.inbound_email_message_id FOR SHARE;
  SELECT * INTO r FROM gridex_unattributed_intake.raw_births WHERE inbound_email_message_id=m.id;
  IF r.inbound_email_message_id IS NULL OR r.snapshot_hash IS DISTINCT FROM gridex_unattributed_intake.raw_hash_v1(m) THEN RETURN NEW;END IF;
  IF TG_TABLE_NAME='inbound_email_attachments' THEN
   INSERT INTO gridex_unattributed_intake.attachment_births VALUES(NEW.id,m.id,gridex_unattributed_intake.attachment_hash_v1(NEW));
  ELSIF TG_TABLE_NAME='inbound_ediel_parse_results' THEN
   INSERT INTO gridex_unattributed_intake.parse_births VALUES(NEW.id,m.id,gridex_unattributed_intake.parse_hash_v1(NEW),
    gridex_unattributed_intake.attachment_set_v1(m.id),gridex_unattributed_intake.selection_v1(NEW));
  ELSE RAISE EXCEPTION 'ediel_technical_custody_owner_required';END IF;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: complete_birth_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.complete_birth_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 PERFORM gridex_unattributed_intake.receipt_v1(NEW.source_message_id,NEW.actor_user_id);
 RETURN NEW;
END $$;

--
-- Name: complete_claim_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.complete_claim_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF NEW.protected_source_id IS NULL AND EXISTS(SELECT FROM gridex_unattributed_intake.physical_claims
  WHERE physical_key=NEW.physical_key AND protected_source_id IS NULL AND claim_transaction=NEW.claim_transaction) THEN
  RAISE EXCEPTION 'ediel_technical_intake_transient_probe_not_deleted' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;

--
-- Name: guard_original_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.guard_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE mail_id uuid;old_mail_id uuid;old_json jsonb;new_json jsonb;
BEGIN
 IF TG_TABLE_NAME='ediel_messages' THEN
  IF NOT EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE source_message_id=OLD.id) THEN
   IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'ediel_technical_intake_original_immutable';END IF;
  IF OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
  old_json:=to_jsonb(OLD)-ARRAY['status','validation_report','contrl_status','aperak_status','utilts_err_status','ack_outcome',
   'syntax_check_status','functional_check_status','failure_reason','parsed_at','validated_at','acknowledged_at','failed_at',
   'ack_due_at','updated_at','updated_by','tenant_resolution_status','business_match_status','ack_status','processing_status',
   'backend_automation_status','backend_automation_reason','contrl_due_at','business_response_due_at','response_overdue_at'];
  new_json:=to_jsonb(NEW)-ARRAY['status','validation_report','contrl_status','aperak_status','utilts_err_status','ack_outcome',
   'syntax_check_status','functional_check_status','failure_reason','parsed_at','validated_at','acknowledged_at','failed_at',
   'ack_due_at','updated_at','updated_by','tenant_resolution_status','business_match_status','ack_status','processing_status',
   'backend_automation_status','backend_automation_reason','contrl_due_at','business_response_due_at','response_overdue_at'];
  IF old_json IS DISTINCT FROM new_json OR gridex_unattributed_intake.is_birth_v1(NEW) IS NOT TRUE THEN
   RAISE EXCEPTION 'ediel_technical_intake_original_immutable' USING ERRCODE='23514';END IF;
 ELSE
  IF TG_TABLE_NAME='inbound_email_messages' THEN mail_id:=OLD.id;
  ELSE
   IF TG_OP<>'DELETE' THEN mail_id:=NEW.inbound_email_message_id;END IF;
   IF TG_OP<>'INSERT' THEN old_mail_id:=OLD.inbound_email_message_id;END IF;
  END IF;
  IF EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE inbound_email_message_id IN(mail_id,old_mail_id)) THEN
   IF TG_TABLE_NAME='inbound_email_messages' AND TG_OP='UPDATE' AND NEW.company_id IS NULL
    AND gridex_unattributed_intake.raw_hash_v1(NEW)=gridex_unattributed_intake.raw_hash_v1(OLD) THEN RETURN NEW;END IF;
   IF TG_TABLE_NAME='inbound_ediel_parse_results' AND TG_OP='UPDATE'
    AND gridex_unattributed_intake.parse_hash_v1(NEW)=gridex_unattributed_intake.parse_hash_v1(OLD) THEN RETURN NEW;END IF;
   RAISE EXCEPTION 'ediel_technical_intake_custody_immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;

--
-- Name: guard_physical_claim_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.guard_physical_claim_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF TG_OP='DELETE' AND OLD.protected_source_id IS NULL AND OLD.claim_transaction=txid_current() THEN RETURN OLD;END IF;
 RAISE EXCEPTION 'ediel_technical_intake_physical_reservation_immutable' USING ERRCODE='23514';END $$;

--
-- Name: guard_physical_original_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.guard_physical_original_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE key text;
BEGIN
 IF NEW.direction IS DISTINCT FROM 'inbound' OR NEW.raw_payload IS NULL THEN RETURN NEW;END IF;
 key:=gridex_unattributed_intake.physical_key_v1(gridex_ediel_technical_ack.envelope(NEW.raw_payload));
 IF key IS NULL THEN RETURN NEW;END IF;
 IF gridex_unattributed_intake.is_birth_v1(NEW,true) IS TRUE THEN
  IF NOT EXISTS(SELECT FROM gridex_unattributed_intake.physical_claims
    WHERE physical_key=key AND protected_source_id=NEW.id) THEN
   RAISE EXCEPTION 'ediel_technical_intake_physical_reservation_required' USING ERRCODE='23514';END IF;
 ELSE
  -- A unique-index probe observes an existing protected reservation even if a
  -- REPEATABLE READ caller's ordinary SELECT snapshot cannot see that birth.
  BEGIN
   INSERT INTO gridex_unattributed_intake.physical_claims VALUES(key,NULL,txid_current());
  EXCEPTION WHEN unique_violation THEN
   RAISE EXCEPTION 'ediel_technical_intake_physical_original_exists' USING ERRCODE='23505';
  END;
  DELETE FROM gridex_unattributed_intake.physical_claims WHERE physical_key=key
   AND protected_source_id IS NULL AND claim_transaction=txid_current();
 END IF;
 RETURN NEW;
END $$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 RAISE EXCEPTION 'ediel_technical_intake_receipt_immutable' USING ERRCODE='23514';END $$;

--
-- Name: is_birth_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_unattributed_intake; Owner: -
--

CREATE FUNCTION gridex_unattributed_intake.is_birth_v1(m public.ediel_messages, pending boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_unattributed_intake.technical_births b WHERE b.source_message_id=m.id
  AND (NOT pending OR b.birth_transaction=txid_current()) AND m.company_id IS NULL AND m.resolved_company_id IS NULL
  AND m.direction='inbound' AND m.message_standard='edifact' AND m.message_family=b.message_family AND m.message_code=b.message_code
  AND m.environment=b.environment AND m.message_received_at=b.received_at AND m.inbound_email_message_id=b.inbound_email_message_id
  AND m.mailbox_message_id=b.inbound_email_message_id::text
  AND gridex_unattributed_intake.sha_v1(m.raw_payload)=b.payload_hash
  AND gridex_ediel_technical_ack.envelope(m.raw_payload)=b.physical_envelope
  AND m.customer_id IS NULL AND m.site_id IS NULL AND m.metering_point_id IS NULL AND m.grid_owner_id IS NULL
  AND m.party_id IS NULL AND m.party_address_id IS NULL AND m.resolved_grid_owner_id IS NULL AND m.resolved_counterparty_id IS NULL
  AND m.operation_id IS NULL AND m.intent_id IS NULL AND m.source_operation_id IS NULL AND m.outbound_request_id IS NULL
  AND m.switch_request_id IS NULL AND m.grid_owner_data_request_id IS NULL AND m.grid_owner_information_request_id IS NULL
  AND m.partner_export_id IS NULL AND m.related_message_id IS NULL AND m.communication_route_id IS NULL
  AND m.canonical_rule_pack_id IS NULL AND m.execution_context_snapshot='{}'::jsonb)
$$;

