    CONSTRAINT metering_values_billing_gate_status_check CHECK ((billing_gate_status = ANY (ARRAY['pending_match'::text, 'eligible'::text, 'blocked'::text, 'conflict'::text]))),
    CONSTRAINT metering_values_billing_status_check CHECK ((billing_status = ANY (ARRAY['pending_match'::text, 'billable'::text, 'blocked'::text, 'conflict'::text, 'invoiced'::text, 'credited'::text]))),
    CONSTRAINT metering_values_revision_status_check CHECK ((revision_status = ANY (ARRAY['current'::text, 'replaced'::text, 'superseded'::text, 'void'::text])))
);

--
-- Name: check_metering_result_v1(public.metering_values, jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.check_metering_result_v1(p_result public.metering_values, p_payload jsonb, p_environment text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m jsonb:=to_jsonb(p_result); n public.normalized_metering_values%rowtype; field text; normalized jsonb; count_rows integer:=0;
BEGIN
 FOREACH field IN ARRAY string_to_array('company_id customer_id site_id customer_site_id metering_point_id grid_owner_id source_request_id reading_type resolution quality_code register_code product_code direction unit source_system price_area canonical_dedupe_key',' ') LOOP
  IF m->>field IS DISTINCT FROM p_payload->>field THEN RAISE EXCEPTION 'utilts_consumption_existing_metering_conflict' USING ERRCODE='P0U01'; END IF;
 END LOOP;
 IF p_result.value_kwh IS DISTINCT FROM (p_payload->>'value_kwh')::numeric
  OR p_result.read_at IS DISTINCT FROM (p_payload->>'read_at')::timestamptz
  OR p_result.period_start IS DISTINCT FROM (p_payload->>'period_start')::timestamptz
  OR p_result.period_end IS DISTINCT FROM (p_payload->>'period_end')::timestamptz THEN
  RAISE EXCEPTION 'utilts_consumption_existing_metering_conflict' USING ERRCODE='P0U01'; END IF;
 -- The natural key has no environment: prove it from each original lineage.
 IF NOT EXISTS(SELECT FROM public.ediel_messages s WHERE s.id=p_result.source_ediel_message_id AND s.company_id=p_result.company_id AND s.environment=p_environment)
  OR EXISTS(SELECT FROM public.metering_value_sources l LEFT JOIN public.ediel_messages s ON s.id=l.source_ediel_message_id AND s.company_id=l.company_id
   WHERE l.company_id=p_result.company_id AND l.metering_value_id=p_result.id AND s.environment IS DISTINCT FROM p_environment) THEN
  RAISE EXCEPTION 'utilts_consumption_existing_metering_environment_conflict' USING ERRCODE='P0U01'; END IF;
 FOR n IN SELECT v.* FROM public.normalized_metering_values v WHERE v.company_id=p_result.company_id
  AND v.source_metering_value_id=p_result.id AND v.revision_status='current' FOR UPDATE LOOP
  count_rows:=count_rows+1; normalized:=to_jsonb(n);
  FOREACH field IN ARRAY string_to_array('company_id customer_id site_id customer_site_id metering_point_id facility_id price_area grid_area resolution register_code product_code direction unit canonical_dedupe_key',' ') LOOP
   IF normalized->>field IS DISTINCT FROM p_payload->>field THEN RAISE EXCEPTION 'utilts_consumption_existing_normalized_conflict' USING ERRCODE='P0U01'; END IF;
  END LOOP;
  IF n.quantity_kwh IS DISTINCT FROM (p_payload->>'value_kwh')::numeric OR n.quality_status IS DISTINCT FROM p_payload->>'quality_code'
   OR n.source_type IS DISTINCT FROM p_payload->>'source_system' OR n.period_start IS DISTINCT FROM (p_payload->>'period_start')::timestamptz
   OR n.period_end IS DISTINCT FROM (p_payload->>'period_end')::timestamptz THEN
   RAISE EXCEPTION 'utilts_consumption_existing_normalized_conflict' USING ERRCODE='P0U01'; END IF;
 END LOOP;
 IF count_rows<>1 THEN RAISE EXCEPTION 'utilts_consumption_existing_normalized_ambiguous' USING ERRCODE='P0U01'; END IF;
END $$;

--
-- Name: decimal_rules_v1(jsonb, text, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.decimal_rules_v1(tokens jsonb, tx text, decimal_mark text DEFAULT '.'::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE own_start integer;own_end integer;first_seq integer;t jsonb;value text;field text;max_dec integer;decimals integer;unit text;code text;product text;resolution text;format text;guide jsonb:='[]';functional jsonb:='[]';qualifier text;
BEGIN
 SELECT (s->>'index')::integer INTO STRICT own_start FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='IDE' AND s#>>'{elements,2,0}'=tx;
 SELECT min((s->>'index')::integer) INTO own_end FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>own_start AND s->>'tag' IN('IDE','UNT');
 SELECT min((s->>'index')::integer) INTO first_seq FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>own_start AND (s->>'index')::integer<own_end AND s->>'tag'='SEQ';
 SELECT s#>>'{elements,1,0}' INTO STRICT code FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='BGM';
 SELECT s#>>'{elements,3,0}' INTO product FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='LIN' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 SELECT s#>>'{elements,1,1}',s#>>'{elements,1,2}' INTO resolution,format FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='DTM' AND s#>>'{elements,1,0}'='354' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 SELECT s#>>'{elements,3,0}' INTO unit FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='MEA' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 IF code='E30' AND unit IS NULL AND ((resolution='15' AND format='806') OR (resolution='1' AND format IN('801','802'))) THEN unit:='KWH'; END IF;
 FOR t IN SELECT s FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>first_seq AND (s->>'index')::integer<own_end AND s->>'tag' IN('QTY','PRI','MOA') LOOP
  value:=t#>>'{elements,1,1}';qualifier:=t#>>'{elements,1,0}';max_dec:=NULL;
  field:=CASE t->>'tag' WHEN 'MOA' THEN CASE qualifier WHEN '9' THEN '522' END WHEN 'PRI' THEN CASE qualifier WHEN 'CAL' THEN '523' END WHEN 'QTY' THEN CASE qualifier WHEN '135' THEN '515' WHEN '136' THEN '516' WHEN '220' THEN '517' WHEN '42' THEN '521' END END;
  IF field IS NULL THEN CONTINUE; END IF;
  IF value='NULL' AND field IN('516','517') THEN CONTINUE; END IF;
  IF decimal_mark NOT IN('.',',') OR value IS NULL OR value='' OR replace(value,decimal_mark,'.') !~ '^-?[0-9]+([.][0-9]+)?$'
   OR length(value)>(CASE field WHEN '523' THEN 15 ELSE 35 END) THEN guide:=guide||jsonb_build_array(field);CONTINUE; END IF;
  decimals:=CASE WHEN strpos(value,decimal_mark)>0 THEN length(value)-strpos(value,decimal_mark) ELSE 0 END;
  IF field IN('522','523') THEN
   max_dec:=CASE field WHEN '522' THEN 2 ELSE 6 END;
   IF decimals>max_dec THEN guide:=guide||jsonb_build_array(field); END IF;
   CONTINUE;
  END IF;
  IF qualifier IN('135','136') AND product='8716867000030' AND unit IS NOT NULL AND unit<>'KWH' THEN functional:=functional||'"E73"'::jsonb;CONTINUE; END IF;
  max_dec:=CASE WHEN unit='P1' THEN 3 WHEN qualifier='220' AND resolution='1' AND format IN('801','802') THEN 0
   WHEN qualifier IN('135','136') AND unit='KWH' THEN CASE WHEN resolution='1' AND format IN('801','802') THEN 0 WHEN (resolution='15' AND format='806') OR (resolution='1' AND format='805') THEN 3 END END;
  IF max_dec IS NOT NULL AND decimals>max_dec THEN functional:=functional||'"E51"'::jsonb; END IF;
 END LOOP;
 RETURN jsonb_build_object('guide',guide,'functional',functional);
EXCEPTION WHEN no_data_found OR too_many_rows THEN RETURN NULL;
END $_$;

--
-- Name: esco_local_time_v1(text, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.esco_local_time_v1(value text, offset_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE local_value timestamp;offset_minutes int;BEGIN
 IF value !~ '^[0-9]{12}$' OR offset_value !~ '^[+-][0-9]{4}$' OR substr(offset_value,4,2)::int>59 OR substr(offset_value,2,2)::int>14 OR (substr(offset_value,2,2)::int=14 AND substr(offset_value,4,2)::int<>0) THEN RETURN NULL;END IF;
 local_value:=make_timestamp(substr(value,1,4)::int,substr(value,5,2)::int,substr(value,7,2)::int,substr(value,9,2)::int,substr(value,11,2)::int,0);
 offset_minutes:=(substr(offset_value,2,2)::int*60+substr(offset_value,4,2)::int)*CASE left(offset_value,1) WHEN '-' THEN -1 ELSE 1 END;
 RETURN (local_value-make_interval(mins=>offset_minutes)) AT TIME ZONE 'UTC';
EXCEPTION WHEN OTHERS THEN RETURN NULL;END $_$;

--
-- Name: exact_keys_v1(jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.exact_keys_v1(v jsonb, k text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN jsonb_typeof(v)='object' THEN
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) =
  (SELECT array_agg(key ORDER BY key) FROM unnest(string_to_array(k,' ')) key)
 ELSE false END
$$;

--
-- Name: guard_source_v1(); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.guard_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE receipt gridex_utilts_binding.receipts%rowtype;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=OLD.id;
 IF FOUND AND (NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR
   gridex_utilts_binding.source_context_v1(NEW) IS DISTINCT FROM receipt.source_context) THEN
  RAISE EXCEPTION 'utilts_source_binding_conflict' USING ERRCODE='P0U01';
 END IF;
 RETURN NEW;
END $$;

--
-- Name: immutable_v1(); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.immutable_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 RAISE EXCEPTION 'utilts_consumption_binding_immutable' USING ERRCODE='P0U01';
END $$;

--
-- Name: legacy_retry_item_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.legacy_retry_item_v1(item jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c jsonb:=item->'consumptionContract'; o jsonb; observations jsonb:='[]'; quantities jsonb:='[]';
BEGIN
 IF c->'version'='1'::jsonb THEN RETURN item; END IF;
 FOR o IN SELECT value FROM jsonb_array_elements(c->'observations') LOOP
  observations:=observations||jsonb_build_array(o||jsonb_build_object('quantity',(item->'quantities'->((o->>'sourceOrdinal')::integer)->>'value')::double precision));
 END LOOP;
 FOR o IN SELECT value FROM jsonb_array_elements(item->'quantities') LOOP
  quantities:=quantities||jsonb_build_array(o||jsonb_build_object('value',(o->>'value')::double precision));
 END LOOP;
 RETURN item||jsonb_build_object('quantities',quantities,'consumptionContract',c||
  jsonb_build_object('version',1,'projectionVersion','utilts-consumption-v1','observations',observations));
END $$;

--
-- Name: lock_attribution_v1(uuid, jsonb, boolean); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.lock_attribution_v1(p_company uuid, p_attribution jsonb, p_billing boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_customer uuid:=(p_attribution->>'customerId')::uuid; v_point public.metering_points%rowtype;
 v_site public.customer_sites%rowtype; v_request public.grid_owner_data_requests%rowtype; v_site_id uuid;
BEGIN
 IF p_attribution->>'capability' IS DISTINCT FROM 'write' THEN RAISE EXCEPTION 'utilts_consumption_not_writable' USING ERRCODE='P0U01'; END IF;
 PERFORM 1 FROM public.customers c WHERE c.id=v_customer AND c.company_id=p_company FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'utilts_consumption_customer_changed' USING ERRCODE='P0U01'; END IF;
 FOR v_site_id IN SELECT DISTINCT x::uuid FROM unnest(ARRAY[p_attribution->>'siteId',p_attribution->>'customerSiteId']) x WHERE x IS NOT NULL ORDER BY 1 LOOP
  SELECT s.* INTO v_site FROM public.customer_sites s WHERE s.id=v_site_id AND s.company_id=p_company FOR SHARE;
  IF NOT FOUND OR v_site.customer_id IS DISTINCT FROM v_customer OR v_site.grid_owner_id::text IS DISTINCT FROM p_attribution->>'gridOwnerId' THEN
   RAISE EXCEPTION 'utilts_consumption_site_ownership_changed' USING ERRCODE='P0U01'; END IF;
 END LOOP;
 IF p_attribution->>'meteringPointId' IS NOT NULL THEN
  SELECT p.* INTO v_point FROM public.metering_points p WHERE p.id=(p_attribution->>'meteringPointId')::uuid AND p.company_id=p_company FOR SHARE;
  IF NOT FOUND OR v_point.customer_id IS DISTINCT FROM v_customer
   OR coalesce(v_point.site_id,v_point.customer_site_id)::text IS DISTINCT FROM p_attribution->>'siteId'
   OR coalesce(v_point.customer_site_id,v_point.site_id)::text IS DISTINCT FROM p_attribution->>'customerSiteId'
   OR v_point.grid_owner_id::text IS DISTINCT FROM p_attribution->>'gridOwnerId' THEN
   RAISE EXCEPTION 'utilts_consumption_point_ownership_changed' USING ERRCODE='P0U01'; END IF;
 END IF;
 IF p_attribution->>'gridOwnerId' IS NOT NULL THEN
  PERFORM 1 FROM public.grid_owners g WHERE g.id=(p_attribution->>'gridOwnerId')::uuid AND g.company_id=p_company FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'utilts_consumption_grid_owner_changed' USING ERRCODE='P0U01'; END IF;
 END IF;
 IF p_attribution->>'sourceRequestId' IS NOT NULL THEN
  SELECT r.* INTO v_request FROM public.grid_owner_data_requests r WHERE r.id=(p_attribution->>'sourceRequestId')::uuid AND r.company_id=p_company FOR SHARE;
  IF NOT FOUND OR v_request.customer_id IS DISTINCT FROM v_customer OR v_request.site_id::text IS DISTINCT FROM p_attribution->>'siteId'
   OR v_request.metering_point_id::text IS DISTINCT FROM p_attribution->>'meteringPointId'
   OR v_request.grid_owner_id::text IS DISTINCT FROM p_attribution->>'gridOwnerId'
   OR (p_billing AND v_request.request_scope IS DISTINCT FROM 'billing_underlay') THEN
   RAISE EXCEPTION 'utilts_consumption_request_changed' USING ERRCODE='P0U01'; END IF;
 ELSIF p_billing THEN RAISE EXCEPTION 'utilts_consumption_request_missing' USING ERRCODE='P0U01';
 END IF;
END $$;

--
-- Name: lock_storage_graph_v1(); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.lock_storage_graph_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 -- Identical prefix/order to ACK replay. Writers take their final compatible
 -- table mode before any source or shared graph read; no SHARE-to-write upgrade.
 LOCK TABLE auth.users,public.user_profiles,public.companies,public.company_memberships,public.admin_users,
 public.user_roles,public.roles,public.role_permissions,public.permissions,public.user_permissions,public.user_permission_overrides,
 public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles,public.tenant_counterparty_relations,public.platform_actor_identifiers,
 public.ediel_service_assignments,public.ediel_service_evidence,public.ediel_data_access_grants,public.ediel_assignment_permission_links,
 public.metering_permissions,public.metering_permission_sites IN SHARE MODE;
 LOCK TABLE public.ediel_ack_transaction_results,public.meter_reading_series,gridex_utilts_binding.receipts,gridex_utilts_binding.contracts IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE gridex_service_administration.scope_versions,gridex_received_sources.permission_transitions,gridex_received_sources.validation_assessments IN SHARE MODE;
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();
END $$;

--
-- Name: persist_consumption_before_actor_v1(uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.persist_consumption_before_actor_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_raw_payload text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;item jsonb;rules jsonb;hash text;committed boolean;mark text;result jsonb;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 PERFORM gridex_utilts_binding.lock_storage_graph_v1();
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id FOR UPDATE;
 IF source.id IS NULL OR source.company_id IS DISTINCT FROM p_company_id OR source.environment IS DISTINCT FROM p_environment OR source.message_code IS DISTINCT FROM p_message_code
  OR source.direction IS DISTINCT FROM 'inbound' OR source.message_family IS DISTINCT FROM 'UTILTS' OR source.raw_payload IS DISTINCT FROM p_raw_payload OR jsonb_typeof(p_transactions) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'utilts_source_binding_conflict' USING ERRCODE='P0U01'; END IF;
 PERFORM gridex_utilts_binding.require_current_esco_storage_v1(p_company_id,p_environment,p_source_message_id,p_transactions);
 p_transactions:=gridex_utilts_binding.preserve_committed_projection_v1(p_company_id,p_environment,p_source_message_id,p_transactions);
 hash:=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex');mark:=CASE WHEN left(source.raw_payload,3)='UNA' THEN substring(source.raw_payload,6,1) ELSE '.' END;
 FOR item IN SELECT value FROM jsonb_array_elements(p_transactions) LOOP
  SELECT EXISTS(SELECT FROM gridex_utilts_binding.receipts r JOIN public.ediel_ack_transaction_results a ON a.source_message_id=r.source_message_id
   WHERE r.source_message_id=source.id AND r.company_id=p_company_id AND r.environment=p_environment AND r.raw_hash=hash
    AND a.company_id=p_company_id AND a.environment=p_environment AND a.source_transaction_id=item->>'transactionId'
    AND a.disposition IS NOT DISTINCT FROM item->>'disposition' AND a.planned_response_type IS NOT DISTINCT FROM item->>'responseType'
    AND ((a.disposition='accepted' AND a.persistence_status='persisted' AND a.planned_response_type='positive_aperak') OR (a.disposition<>'accepted' AND a.finalized_at IS NOT NULL))) INTO committed;
  -- Authentic committed V1/V2 replay is validated by the retained owner below;
  -- these new rules cannot rewrite a prior final ACK/contract interpretation.
  IF committed THEN CONTINUE; END IF;
  PERFORM gridex_received_sources.require_utilts_transaction_v1(p_company_id,source.id,item->>'transactionId',item->>'disposition',item->>'responseType',item->'issueCodes');
  IF item->>'disposition'<>'accepted' THEN CONTINUE; END IF;
  PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,source.id);
  PERFORM gridex_ediel_source_rules.require_v1(p_company_id,source.id);
  rules:=gridex_utilts_binding.decimal_rules_v1(gridex_utilts_binding.wire_tokens_v1(source.raw_payload),item->>'transactionId',mark);
  IF rules IS NULL OR jsonb_array_length(rules->'guide')<>0 OR jsonb_array_length(rules->'functional')<>0 THEN RAISE EXCEPTION 'utilts_source_decimal_or_unit_rules_failed' USING ERRCODE='P0U01'; END IF;
 END LOOP;
 result:=gridex_utilts_binding.persist_consumption_before_precision_v1(p_company_id,p_environment,p_source_message_id,p_message_code,p_raw_payload,p_transactions);
 -- The observer independently reads actual immutable private accepted history.
 -- Caller disposition/result booleans cannot qualify a reading observation.
 -- The existing owner retains its source row lock; the observer's late graph
 -- lock was removed by44958 and other busy source rows use SKIP LOCKED.
 PERFORM gridex_received_reading_expectations.consider_utilts_source_v1(p_company_id,p_environment,p_source_message_id);
 RETURN result;
END $$;

--
-- Name: persist_consumption_before_precision_v1(uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.persist_consumption_before_precision_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_raw_payload text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 source public.ediel_messages%rowtype; receipt gridex_utilts_binding.receipts%rowtype;
 stored gridex_utilts_binding.contracts%rowtype; series public.meter_reading_series%rowtype;
 tokens jsonb; membership jsonb; expected jsonb; raw_hash text; item jsonb; c jsonb; r jsonb; results jsonb; answer jsonb:='[]';
 v_series_id uuid; identity text; contract_hash text; origin gridex_utilts_binding.receipts%rowtype;
 decimal_mark text; legacy_transactions jsonb;
 own_start integer; own_end integer; sequence_start integer; sequence_end integer; sequence_count integer;
BEGIN
 IF p_company_id IS NULL OR p_environment IS NULL OR p_environment NOT IN ('test','production') OR p_message_code IS NULL OR jsonb_typeof(p_transactions) IS DISTINCT FROM 'array' OR jsonb_array_length(p_transactions)=0 THEN
  RAISE EXCEPTION 'utilts_consumption_input_invalid' USING ERRCODE='P0U01';
 END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id FOR UPDATE;
 IF NOT FOUND OR source.company_id IS DISTINCT FROM p_company_id OR source.environment IS DISTINCT FROM p_environment OR source.direction<>'inbound' OR source.message_family<>'UTILTS' OR source.message_code IS DISTINCT FROM p_message_code
 OR p_raw_payload IS NULL OR source.raw_payload IS DISTINCT FROM p_raw_payload THEN RAISE EXCEPTION 'utilts_source_binding_conflict' USING ERRCODE='P0U01'; END IF;
 raw_hash:=encode(digest(convert_to(source.raw_payload,'UTF8'),'sha256'),'hex');
 decimal_mark:=CASE WHEN left(source.raw_payload,3)='UNA' THEN substring(source.raw_payload,6,1) ELSE '.' END;
 tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 IF tokens IS NULL THEN RAISE EXCEPTION 'utilts_physical_membership_unavailable' USING ERRCODE='P0U01'; END IF;
 -- This owner deliberately does not reinterpret multiple physical messages.
 IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='UTILTS')
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM')<>1
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'=p_message_code) THEN
  RAISE EXCEPTION 'utilts_physical_membership_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT coalesce(jsonb_agg(coalesce(nullif(t#>>'{elements,2,0}',''),'transaction-'||ordinal::text) ORDER BY ordinal),'["transaction-1"]') INTO membership
 FROM (SELECT t,row_number() OVER(ORDER BY (t->>'index')::integer) ordinal FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE') physical;
 SELECT jsonb_agg(t->'transactionId' ORDER BY ordinal) INTO expected FROM jsonb_array_elements(p_transactions) WITH ORDINALITY x(t,ordinal);
 IF membership IS DISTINCT FROM expected OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(membership))<>jsonb_array_length(membership) THEN
  RAISE EXCEPTION 'utilts_physical_membership_conflict' USING ERRCODE='P0U01'; END IF;
 -- An invalid physical IDE remains a member so its negative guide outcome can
 -- be bound to this source. It must never create accepted consumption authority.
 IF EXISTS(SELECT FROM jsonb_array_elements(p_transactions) x(item)
  JOIN jsonb_array_elements(tokens) t ON t->>'tag'='IDE' AND t#>>'{elements,2,0}'=x.item->>'transactionId'
  WHERE x.item->>'disposition'='accepted' AND t#>>'{elements,1,0}' IS DISTINCT FROM '24') THEN
  RAISE EXCEPTION 'utilts_consumption_identity_unsupported' USING ERRCODE='P0U01'; END IF;
 -- Namespace validation precedes receipt/ACK/series writes, independently of
 -- application comparison exemptions and mutable plain-ID matches.
 FOR item IN SELECT value FROM jsonb_array_elements(p_transactions) LOOP
  c:=item->'consumptionContract';
  IF NOT coalesce(CASE WHEN c->'version'='3'::jsonb THEN gridex_utilts_binding.valid_rejected_item_v3(item) ELSE gridex_utilts_binding.validate_contract_v1(c) END,false) THEN
   RAISE EXCEPTION 'utilts_consumption_contract_invalid' USING ERRCODE='P0U01'; END IF;
  IF c->'version'='2'::jsonb AND NOT coalesce(gridex_utilts_binding.validate_decimal_source_v2(tokens,item,decimal_mark),false) THEN
   RAISE EXCEPTION 'utilts_consumption_decimal_source_conflict' USING ERRCODE='P0U01'; END IF;
  IF item->>'disposition'='accepted' AND (p_message_code IN ('E30','E66','S07','E72','S02') OR jsonb_array_length(c->'observations')>0
   OR (p_message_code IN ('S01','E73') AND NOT gridex_utilts_binding.unowned_regulating_object_v1(tokens,item->>'transactionId'))) THEN
   identity:=gridex_utilts_binding.supported_point_v1(tokens,item->>'transactionId');
   IF identity IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(c->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM identity) THEN
    RAISE EXCEPTION 'utilts_consumption_identity_unsupported' USING ERRCODE='P0U01'; END IF;
  END IF;
  IF item->>'disposition'='accepted' AND p_message_code='S02' THEN
   SELECT (t->>'index')::integer INTO STRICT own_start FROM jsonb_array_elements(tokens) t
    WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=item->>'transactionId';
   SELECT min((t->>'index')::integer) INTO own_end FROM jsonb_array_elements(tokens) t
    WHERE (t->>'index')::integer>own_start AND t->>'tag' IN ('IDE','UNT');
   sequence_count:=0;
   FOR sequence_start IN SELECT (t->>'index')::integer FROM jsonb_array_elements(tokens) t
    WHERE t->>'tag'='SEQ' AND (t->>'index')::integer>own_start AND (t->>'index')::integer<own_end ORDER BY 1 LOOP
    sequence_count:=sequence_count+1;
    SELECT coalesce(min((t->>'index')::integer),own_end) INTO sequence_end FROM jsonb_array_elements(tokens) t
     WHERE (t->>'index')::integer>sequence_start AND (t->>'index')::integer<own_end AND t->>'tag'='SEQ';
    IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='QTY'
     AND (t->>'index')::integer>sequence_start AND (t->>'index')::integer<sequence_end
     AND t#>>'{elements,1,0}'='135' AND nullif(btrim(t#>>'{elements,1,1}'),'') IS NOT NULL) THEN
     RAISE EXCEPTION 'utilts_s02_quantity_required' USING ERRCODE='P0U01'; END IF;
   END LOOP;
   IF sequence_count=0 THEN RAISE EXCEPTION 'utilts_s02_quantity_required' USING ERRCODE='P0U01'; END IF;
  END IF;
 END LOOP;
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=p_source_message_id;
 IF NOT FOUND THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(p_transactions) t WHERE t#>'{consumptionContract,version}' IS DISTINCT FROM '2'::jsonb AND NOT coalesce(gridex_utilts_binding.valid_rejected_item_v3(t),false)) THEN
   RAISE EXCEPTION 'utilts_new_consumption_requires_v2' USING ERRCODE='P0U01'; END IF;
  IF EXISTS(SELECT FROM public.ediel_ack_transaction_results WHERE source_message_id=p_source_message_id)
  OR EXISTS(SELECT FROM public.meter_reading_series WHERE source_ediel_message_id=p_source_message_id) THEN
   RAISE EXCEPTION 'utilts_historical_binding_unavailable' USING ERRCODE='P0U01'; END IF;
  INSERT INTO gridex_utilts_binding.receipts(source_message_id,company_id,environment,message_code,raw_hash,source_context,membership,contract_version)
   VALUES(p_source_message_id,p_company_id,p_environment,p_message_code,raw_hash,gridex_utilts_binding.source_context_v1(source),membership,2) RETURNING * INTO receipt;
 ELSIF receipt.company_id IS DISTINCT FROM p_company_id OR receipt.environment IS DISTINCT FROM p_environment
 OR receipt.message_code IS DISTINCT FROM p_message_code OR receipt.contract_version NOT IN (1,2) OR receipt.raw_hash IS DISTINCT FROM raw_hash OR receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(source) OR receipt.membership IS DISTINCT FROM membership THEN
  RAISE EXCEPTION 'utilts_source_binding_conflict' USING ERRCODE='P0U01';
 END IF;
 -- A retained V1 is solely an authentic retry of this exact source/hash.
 -- New accepted effects require V2; an old held/negative receipt cannot mint V1.
 IF receipt.contract_version=1 THEN
  FOR item IN SELECT value FROM jsonb_array_elements(p_transactions) LOOP
   IF item->>'disposition'='accepted' AND NOT EXISTS(
    SELECT FROM public.ediel_ack_transaction_results a JOIN gridex_utilts_binding.contracts old ON old.series_id=a.persisted_series_id
    WHERE a.source_message_id=p_source_message_id AND a.company_id=p_company_id AND a.environment=p_environment
    AND a.source_transaction_id=item->>'transactionId' AND a.disposition='accepted' AND a.persistence_status='persisted'
    AND old.contract_version=1 AND old.company_id=p_company_id AND old.environment=p_environment) THEN
    RAISE EXCEPTION 'utilts_legacy_retry_contract_unavailable' USING ERRCODE='P0U01'; END IF;
  END LOOP;
  SELECT jsonb_agg(gridex_utilts_binding.legacy_retry_item_v1(t) ORDER BY ordinal) INTO legacy_transactions
   FROM jsonb_array_elements(p_transactions) WITH ORDINALITY x(t,ordinal);
  p_transactions:=legacy_transactions;
 END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(p_transactions) t WHERE t#>'{consumptionContract,version}' IS DISTINCT FROM to_jsonb(receipt.contract_version) AND NOT (receipt.contract_version=2 AND coalesce(gridex_utilts_binding.valid_rejected_item_v3(t),false))) THEN
  RAISE EXCEPTION 'utilts_consumption_version_conflict' USING ERRCODE='P0U01'; END IF;
 -- Acquire all locks before insertion, in stable order (including the private
 -- insertion core's logical-series lock) to avoid opposite-order batch deadlocks.
 FOR item IN SELECT value FROM jsonb_array_elements(p_transactions) ORDER BY value->>'transactionId' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||'|'||p_environment||'|'||p_source_message_id::text||'|'||(item->>'transactionId'),0));
 END LOOP;
 FOR identity IN SELECT DISTINCT concat_ws('|',p_company_id::text,p_environment,coalesce(t->>'seriesKind','actual'),p_message_code,coalesce(t->>'externalMeteringPointId',''),coalesce(t->>'gridAreaId',''),coalesce(t->>'periodStart',''),coalesce(t->>'periodEnd',''),coalesce(t->>'resolution','UNKNOWN'),coalesce(t->>'productId','')) FROM jsonb_array_elements(p_transactions) t ORDER BY 1 LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(identity,0));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_transactions) LOOP
  c:=item->'consumptionContract';
  IF NOT coalesce(CASE WHEN c->'version'='3'::jsonb THEN gridex_utilts_binding.valid_rejected_item_v3(item) ELSE gridex_utilts_binding.validate_contract_v1(c) END,false) OR c->>'companyId' IS DISTINCT FROM p_company_id::text OR c->>'environment' IS DISTINCT FROM p_environment
   OR c->>'messageCode' IS DISTINCT FROM p_message_code OR c->>'transactionId' IS DISTINCT FROM item->>'transactionId' OR c->>'seriesKind' IS DISTINCT FROM item->>'seriesKind' THEN
   RAISE EXCEPTION 'utilts_consumption_contract_invalid' USING ERRCODE='P0U01'; END IF;
 END LOOP;
 results:=gridex_utilts_binding.persist_series_v1(p_company_id,p_environment,p_source_message_id,p_message_code,p_transactions);
 FOR r IN SELECT value FROM jsonb_array_elements(results) LOOP
  SELECT value INTO STRICT item FROM jsonb_array_elements(p_transactions) WHERE value->>'transactionId'=r->>'transactionId';
  c:=item->'consumptionContract';
  IF r->>'persistenceStatus'='persisted' THEN
   v_series_id:=(r->>'seriesId')::uuid;
   SELECT * INTO series FROM public.meter_reading_series WHERE id=v_series_id AND company_id=p_company_id FOR SHARE;
   IF NOT FOUND OR series.message_code IS DISTINCT FROM p_message_code OR series.source_transaction_reference IS DISTINCT FROM item->>'transactionId'
    OR jsonb_typeof(series.raw_transaction) IS DISTINCT FROM 'object' OR series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(series.raw_transaction::text,'UTF8'),'sha256'),'hex')
    OR series.raw_transaction IS DISTINCT FROM item THEN RAISE EXCEPTION 'utilts_consumption_raw_conflict' USING ERRCODE='P0U01'; END IF;
   SELECT * INTO origin FROM gridex_utilts_binding.receipts WHERE source_message_id=series.source_ediel_message_id;
   IF NOT FOUND OR origin.company_id<>p_company_id OR origin.environment<>p_environment OR origin.message_code<>p_message_code THEN RAISE EXCEPTION 'utilts_consumption_origin_conflict' USING ERRCODE='P0U01'; END IF;
   SELECT * INTO stored FROM gridex_utilts_binding.contracts WHERE contracts.series_id=v_series_id;
   IF NOT FOUND THEN
    IF coalesce((r->>'idempotentReplay')::boolean,true) THEN RAISE EXCEPTION 'utilts_historical_contract_unavailable' USING ERRCODE='P0U01'; END IF;
    INSERT INTO gridex_utilts_binding.contracts(series_id,company_id,environment,source_message_id,transaction_id,contract_version,contract,contract_hash)
     VALUES(v_series_id,p_company_id,p_environment,p_source_message_id,item->>'transactionId',receipt.contract_version,c,encode(digest(convert_to(c::text,'UTF8'),'sha256'),'hex')) RETURNING * INTO stored;
   END IF;
   contract_hash:=encode(digest(convert_to(stored.contract::text,'UTF8'),'sha256'),'hex');
   IF stored.company_id<>p_company_id OR stored.environment<>p_environment OR stored.transaction_id<>item->>'transactionId' OR stored.contract_version IS DISTINCT FROM receipt.contract_version OR stored.contract->'version' IS DISTINCT FROM to_jsonb(stored.contract_version)
    OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(stored.contract),false) OR stored.contract_hash IS DISTINCT FROM contract_hash OR stored.contract IS DISTINCT FROM c THEN
    RAISE EXCEPTION 'utilts_consumption_contract_conflict' USING ERRCODE='P0U01'; END IF;
   r:=r||jsonb_build_object('contractVersion',stored.contract_version,'contractHash',stored.contract_hash,'consumptionContract',stored.contract);
  END IF;
  answer:=answer||jsonb_build_array(r||jsonb_build_object('sourceBinding',jsonb_build_object('sourceMessageId',receipt.source_message_id,'rawHash',receipt.raw_hash,'boundAt',receipt.bound_at)));
 END LOOP;
 RETURN answer;
END $$;

--
-- Name: persist_series_legacy_v1(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.persist_series_legacy_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_source public.ediel_messages%rowtype;
  v_tokens jsonb;
  v_item jsonb;
  v_existing public.ediel_ack_transaction_results%rowtype;
  v_issue_codes text[];
  v_transaction_id text;
  v_disposition text;
  v_response_type text;
  v_dedupe_key text;
  v_series_identity text;
  v_series_id uuid;
  v_previous_id uuid;
  v_version integer;
  v_inserted boolean;
  v_quantity jsonb;
  v_order integer;
  v_results jsonb := '[]'::jsonb;
begin
  if p_environment not in ('test','production') then raise exception 'utilts_environment_invalid'; end if;
  if jsonb_typeof(p_transactions) <> 'array' then raise exception 'utilts_transactions_must_be_array'; end if;

  select * into v_source from public.ediel_messages where id=p_source_message_id for share;
  if not found or v_source.message_family <> 'UTILTS' then raise exception 'utilts_source_message_missing'; end if;
  if v_source.company_id is distinct from p_company_id or v_source.environment is distinct from p_environment then
    raise exception 'utilts_source_tenant_or_environment_mismatch' using errcode='23514';
  end if;
  v_tokens := gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload);
  if v_tokens is null then raise exception 'utilts_physical_membership_unavailable' using errcode='P0U01'; end if;

  for v_item in select value from jsonb_array_elements(p_transactions)
  loop
    v_transaction_id := nullif(btrim(v_item->>'transactionId'),'');
    v_disposition := coalesce(nullif(v_item->>'disposition',''),'processability_rejected');
    v_response_type := coalesce(nullif(v_item->>'responseType',''),'utilts_err');
    if v_transaction_id is null then v_transaction_id := 'transaction-' || (jsonb_array_length(v_results)+1)::text; end if;
    -- An accepted LOC+175 has no approved object owner or separate sink.
    -- Fail before the ACK/series write; the outer RPC also rolls its receipt back.
    if v_disposition='accepted' and gridex_utilts_binding.unowned_regulating_object_v1(v_tokens,v_transaction_id) then
      raise exception 'utilts_regulating_object_owner_unavailable' using errcode='P0U01';
    end if;
    v_issue_codes := coalesce(array(select jsonb_array_elements_text(coalesce(v_item->'issueCodes','[]'::jsonb))),array[]::text[]);
    -- The ACK and series are durable effects. A fresh structural assessment on
    -- retry may upgrade a held transaction, but may not silently revoke one
    -- that already produced a series or a finalized market response. Serialize
    -- retries for this source transaction before looking at the existing row.
    perform pg_advisory_xact_lock(hashtextextended(
      p_company_id::text || '|' || p_environment || '|' || p_source_message_id::text || '|' || v_transaction_id, 0));
    select * into v_existing from public.ediel_ack_transaction_results
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id for update;
    -- An identical held original has already reserved its no-response result.
    -- Keep its row and timestamp immutable; a changed assessment may still
    -- upgrade this unfinalized hold through the existing path below.
    if found and v_disposition='internal_review' and v_response_type='none'
      and v_existing.disposition='internal_review' and v_existing.planned_response_type='none'
      and v_existing.final_response_type is null and v_existing.persistence_status='not_applicable'
      and v_existing.persisted_series_id is null and v_existing.issue_codes is not distinct from v_issue_codes then
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','internal_review',
        'responseType','none','persistenceStatus','not_applicable'));
      continue;
    end if;
    -- Persistence is the durable response reservation, before any ACK draft
    -- can be created. Only a held, unfinalized row without side effects may
    -- change on later structural review. A planned ERR/APERAK/CONTRL remains
    -- fixed even if processing crashes between ACK creation and finalization.
    if found and not (v_existing.disposition='internal_review'
      and v_existing.planned_response_type='none' and v_existing.final_response_type is null
      and v_existing.persistence_status='not_applicable') then
      if v_existing.disposition is distinct from v_disposition
        or v_existing.planned_response_type is distinct from v_response_type
        or v_existing.issue_codes is distinct from v_issue_codes then
        raise exception 'utilts_committed_transaction_retry_conflict' using errcode='23514';
      end if;
      if v_existing.persistence_status='persisted' then
        if v_existing.persisted_series_id is null then
          raise exception 'utilts_committed_series_missing' using errcode='23514';
        end if;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'transactionId',v_transaction_id,'disposition',v_disposition,
          'responseType',v_response_type,'persistenceStatus','persisted',
          'seriesId',v_existing.persisted_series_id,'idempotentReplay',true));
      else
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'transactionId',v_transaction_id,'disposition',v_disposition,
          'responseType',v_response_type,'persistenceStatus',v_existing.persistence_status));
      end if;
      continue;
    end if;

    insert into public.ediel_ack_transaction_results(
      company_id,environment,source_message_id,source_transaction_id,
      syntax_result,guide_validation_result,processability_result,
      disposition,planned_response_type,issue_codes,persistence_status,updated_at
    ) values (
      p_company_id,p_environment,p_source_message_id,v_transaction_id,
      case when v_disposition='syntax_rejected' then 'negative' else 'positive' end,
      case when v_disposition='guide_rejected' then 'negative' when v_disposition='syntax_rejected' then 'pending' else 'positive' end,
      case when v_disposition='processability_rejected' then 'negative' when v_disposition='accepted' then 'positive' when v_disposition='internal_review' then 'pending' else 'not_applicable' end,
      v_disposition,v_response_type,
      v_issue_codes,
      case when v_disposition='accepted' then 'pending' else 'not_applicable' end,now()
    ) on conflict(company_id,environment,source_message_id,source_transaction_id)
    do update set
      syntax_result=excluded.syntax_result,
      guide_validation_result=excluded.guide_validation_result,
      processability_result=excluded.processability_result,
      disposition=excluded.disposition,
      planned_response_type=excluded.planned_response_type,
      issue_codes=excluded.issue_codes,
      persistence_status=excluded.persistence_status,
      persisted_series_id=null,
      persistence_error=null,
      updated_at=now();

    if v_disposition <> 'accepted' then
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition',v_disposition,
        'responseType',v_response_type,'persistenceStatus','not_applicable'
      ));
      continue;
    end if;

    begin
      v_series_identity := concat_ws('|',p_company_id::text,p_environment,coalesce(v_item->>'seriesKind','actual'),
        p_message_code,coalesce(v_item->>'externalMeteringPointId',''),coalesce(v_item->>'gridAreaId',''),
        coalesce(v_item->>'periodStart',''),coalesce(v_item->>'periodEnd',''),
        coalesce(v_item->>'resolution','UNKNOWN'),coalesce(v_item->>'productId',''));
      perform pg_advisory_xact_lock(hashtextextended(v_series_identity,0));
      v_dedupe_key := encode(digest(convert_to(v_series_identity || '|' || v_transaction_id,'UTF8'),'sha256'),'hex');
      v_previous_id := null;
      v_version := 1;
      select id,version_no into v_previous_id,v_version
      from public.meter_reading_series
      where company_id=p_company_id and is_current
        and series_kind=coalesce(v_item->>'seriesKind','actual')
        and coalesce(message_code,'')=coalesce(p_message_code,'')
        and coalesce(external_metering_point_id,'')=coalesce(v_item->>'externalMeteringPointId','')
        and coalesce(grid_area_id,'')=coalesce(v_item->>'gridAreaId','')
        and period_start is not distinct from nullif(v_item->>'periodStart','')::timestamptz
        and period_end is not distinct from nullif(v_item->>'periodEnd','')::timestamptz
        and resolution=coalesce(v_item->>'resolution','UNKNOWN')
        and coalesce(product_id,'')=coalesce(v_item->>'productId','')
        and dedupe_key<>v_dedupe_key
        and exists(select from public.ediel_messages origin where origin.id=meter_reading_series.source_ediel_message_id and origin.company_id=p_company_id and origin.environment=p_environment)
      order by version_no desc limit 1 for update;
      if v_previous_id is not null then v_version := v_version + 1; end if;

      insert into public.meter_reading_series(
        company_id,metering_point_id,source_ediel_message_id,external_metering_point_id,
        grid_area_id,period_start,period_end,resolution,unit,quality_status,dedupe_key,
        message_code,source_transaction_reference,series_kind,product_id,time_series_product,
        actor_context,registration_date,latest_update_date,version_no,supersedes_series_id,
        is_current,correction_reason,raw_transaction,immutable_hash
      ) values (
        p_company_id,nullif(v_item->>'meteringPointId','')::uuid,p_source_message_id,
        nullif(v_item->>'externalMeteringPointId',''),nullif(v_item->>'gridAreaId',''),
        nullif(v_item->>'periodStart','')::timestamptz,nullif(v_item->>'periodEnd','')::timestamptz,
        coalesce(nullif(v_item->>'resolution',''),'UNKNOWN'),coalesce(nullif(v_item->>'unit',''),'KWH'),
        'received',v_dedupe_key,p_message_code,v_transaction_id,coalesce(v_item->>'seriesKind','actual'),
        nullif(v_item->>'productId',''),v_item->'timeSeriesProduct',coalesce(v_item->'actorContext','{}'::jsonb),
        nullif(v_item->>'registrationDate','')::timestamptz,nullif(v_item->>'latestUpdateDate','')::timestamptz,
        v_version,v_previous_id,true,nullif(v_item->>'correctionReason',''),v_item,
        encode(digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex')
      ) on conflict(company_id,dedupe_key) do nothing returning id into v_series_id;
      v_inserted := v_series_id is not null;
      if not v_inserted then
        select id into v_series_id from public.meter_reading_series
        where company_id=p_company_id and dedupe_key=v_dedupe_key;
      else
        if v_previous_id is not null then
          update public.meter_reading_series set is_current=false where id=v_previous_id;
        end if;
        v_order := 0;
        for v_quantity in select value from jsonb_array_elements(coalesce(v_item->'quantities','[]'::jsonb))
        loop
          v_order := v_order + 1;
          insert into public.meter_reading_values(
            company_id,series_id,reading_at,quantity,unit,quality,source_order,
            observation_id,qualifier,raw_value,metadata
          ) values (
            p_company_id,v_series_id,nullif(v_quantity->>'readingAt','')::timestamptz,
            nullif(v_quantity->>'value','')::numeric,coalesce(nullif(v_item->>'unit',''),'KWH'),
            coalesce(nullif(v_quantity->>'quality',''),'unknown'),v_order,
            coalesce(nullif(v_quantity->>'observationId',''),v_order::text),
            nullif(v_quantity->>'qualifier',''),v_quantity->>'raw',coalesce(v_quantity->'metadata','{}'::jsonb)
          );
        end loop;
      end if;

      update public.ediel_ack_transaction_results set
        persistence_status='persisted',persisted_series_id=v_series_id,persistence_error=null,updated_at=now()
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','accepted','responseType','positive_aperak',
        'persistenceStatus','persisted','seriesId',v_series_id,'idempotentReplay',not v_inserted
      ));
    exception when others then
      -- A local write error has no national ERR meaning. Propagate it so the
      -- enclosing RPC rolls back this receipt, every sibling and every ACK
      -- reservation together. The original SQLSTATE stays available to ops.
      raise;
    end;
  end loop;
  return v_results;
end $$;

--
-- Name: persist_series_v1(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.persist_series_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt gridex_utilts_binding.receipts%rowtype;
BEGIN
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=p_source_message_id FOR SHARE;
 IF NOT FOUND OR receipt.company_id IS DISTINCT FROM p_company_id OR receipt.environment IS DISTINCT FROM p_environment
  OR receipt.message_code IS DISTINCT FROM p_message_code THEN
  RAISE EXCEPTION 'utilts_consumption_receipt_missing' USING ERRCODE='P0U01';
 END IF;
 IF receipt.contract_version=1 THEN
  RETURN gridex_utilts_binding.persist_series_legacy_v1(p_company_id,p_environment,p_source_message_id,p_message_code,p_transactions);
 ELSIF receipt.contract_version=2 THEN
  RETURN gridex_utilts_binding.persist_series_v2(p_company_id,p_environment,p_source_message_id,p_message_code,p_transactions);
 END IF;
 RAISE EXCEPTION 'utilts_consumption_contract_invalid' USING ERRCODE='P0U01';
END $$;

--
-- Name: persist_series_v2(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.persist_series_v2(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_source public.ediel_messages%rowtype;
  v_tokens jsonb;
  v_item jsonb;
  v_existing public.ediel_ack_transaction_results%rowtype;
  v_issue_codes text[];
  v_transaction_id text;
  v_disposition text;
  v_response_type text;
  v_dedupe_key text;
  v_series_identity text;
  v_series_id uuid;
  v_previous_id uuid;
  v_late_older boolean;
  v_version integer;
  v_inserted boolean;
  v_quantity jsonb;
  v_order integer;
  v_results jsonb := '[]'::jsonb;
begin
  if p_environment not in ('test','production') then raise exception 'utilts_environment_invalid'; end if;
  if jsonb_typeof(p_transactions) <> 'array' then raise exception 'utilts_transactions_must_be_array'; end if;

  select * into v_source from public.ediel_messages where id=p_source_message_id for share;
  if not found or v_source.message_family <> 'UTILTS' then raise exception 'utilts_source_message_missing'; end if;
  if v_source.company_id is distinct from p_company_id or v_source.environment is distinct from p_environment then
    raise exception 'utilts_source_tenant_or_environment_mismatch' using errcode='23514';
  end if;
  v_tokens := gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload);
  if v_tokens is null then raise exception 'utilts_physical_membership_unavailable' using errcode='P0U01'; end if;

  for v_item in select value from jsonb_array_elements(p_transactions)
  loop
    v_transaction_id := nullif(v_item->>'transactionId','');
    v_disposition := coalesce(nullif(v_item->>'disposition',''),'processability_rejected');
    v_response_type := coalesce(nullif(v_item->>'responseType',''),'utilts_err');
    if v_transaction_id is null then v_transaction_id := 'transaction-' || (jsonb_array_length(v_results)+1)::text; end if;
    IF v_disposition='accepted' AND NOT coalesce(gridex_utilts_binding.valid_transaction_reference_v2(v_transaction_id),false) THEN
      RAISE EXCEPTION 'utilts_consumption_identity_unsupported' USING ERRCODE='P0U01';
    END IF;
    -- An accepted LOC+175 has no approved object owner or separate sink.
    -- Fail before the ACK/series write; the outer RPC also rolls its receipt back.
    if v_disposition='accepted' and gridex_utilts_binding.unowned_regulating_object_v1(v_tokens,v_transaction_id) then
      raise exception 'utilts_regulating_object_owner_unavailable' using errcode='P0U01';
    end if;
    v_issue_codes := coalesce(array(select jsonb_array_elements_text(coalesce(v_item->'issueCodes','[]'::jsonb))),array[]::text[]);
    -- The ACK and series are durable effects. A fresh structural assessment on
    -- retry may upgrade a held transaction, but may not silently revoke one
    -- that already produced a series or a finalized market response. Serialize
    -- retries for this source transaction before looking at the existing row.
    perform pg_advisory_xact_lock(hashtextextended(
      p_company_id::text || '|' || p_environment || '|' || p_source_message_id::text || '|' || v_transaction_id, 0));
    select * into v_existing from public.ediel_ack_transaction_results
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id for update;
    -- An identical held original has already reserved its no-response result.
    -- Keep its row and timestamp immutable; a changed assessment may still
    -- upgrade this unfinalized hold through the existing path below.
    if found and v_disposition='internal_review' and v_response_type='none'
      and v_existing.disposition='internal_review' and v_existing.planned_response_type='none'
      and v_existing.final_response_type is null and v_existing.persistence_status='not_applicable'
      and v_existing.persisted_series_id is null and v_existing.issue_codes is not distinct from v_issue_codes then
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','internal_review',
        'responseType','none','persistenceStatus','not_applicable'));
      continue;
    end if;
    -- Persistence is the durable response reservation, before any ACK draft
    -- can be created. Only a held, unfinalized row without side effects may
    -- change on later structural review. A planned ERR/APERAK/CONTRL remains
    -- fixed even if processing crashes between ACK creation and finalization.
    if found and not (v_existing.disposition='internal_review'
      and v_existing.planned_response_type='none' and v_existing.final_response_type is null
      and v_existing.persistence_status='not_applicable') then
      if v_existing.disposition is distinct from v_disposition
        or v_existing.planned_response_type is distinct from v_response_type
        or v_existing.issue_codes is distinct from v_issue_codes then
        raise exception 'utilts_committed_transaction_retry_conflict' using errcode='23514';
      end if;
      if v_existing.persistence_status='persisted' then
        if v_existing.persisted_series_id is null then
          raise exception 'utilts_committed_series_missing' using errcode='23514';
        end if;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'transactionId',v_transaction_id,'disposition',v_disposition,
          'responseType',v_response_type,'persistenceStatus','persisted',
          'seriesId',v_existing.persisted_series_id,'idempotentReplay',true));
      else
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'transactionId',v_transaction_id,'disposition',v_disposition,
          'responseType',v_response_type,'persistenceStatus',v_existing.persistence_status));
      end if;
      continue;
    end if;

    insert into public.ediel_ack_transaction_results(
      company_id,environment,source_message_id,source_transaction_id,
      syntax_result,guide_validation_result,processability_result,
      disposition,planned_response_type,issue_codes,persistence_status,updated_at
    ) values (
      p_company_id,p_environment,p_source_message_id,v_transaction_id,
      case when v_disposition='syntax_rejected' then 'negative' else 'positive' end,
      case when v_disposition='guide_rejected' then 'negative' when v_disposition='syntax_rejected' then 'pending' else 'positive' end,
      case when v_disposition='processability_rejected' then 'negative' when v_disposition='accepted' then 'positive' when v_disposition='internal_review' then 'pending' else 'not_applicable' end,
      v_disposition,v_response_type,
      v_issue_codes,
      case when v_disposition='accepted' then 'pending' else 'not_applicable' end,now()
    ) on conflict(company_id,environment,source_message_id,source_transaction_id)
    do update set
      syntax_result=excluded.syntax_result,
      guide_validation_result=excluded.guide_validation_result,
      processability_result=excluded.processability_result,
      disposition=excluded.disposition,
      planned_response_type=excluded.planned_response_type,
      issue_codes=excluded.issue_codes,
      persistence_status=excluded.persistence_status,
      persisted_series_id=null,
      persistence_error=null,
      updated_at=now();

    if v_disposition <> 'accepted' then
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition',v_disposition,
        'responseType',v_response_type,'persistenceStatus','not_applicable'
      ));
      continue;
    end if;

    begin
      v_series_identity := concat_ws('|',p_company_id::text,p_environment,coalesce(v_item->>'seriesKind','actual'),
        p_message_code,coalesce(v_item->>'externalMeteringPointId',''),coalesce(v_item->>'gridAreaId',''),
        coalesce(v_item->>'periodStart',''),coalesce(v_item->>'periodEnd',''),
        coalesce(v_item->>'resolution','UNKNOWN'),coalesce(v_item->>'productId',''));
      perform pg_advisory_xact_lock(hashtextextended(v_series_identity,0));
      v_dedupe_key := encode(digest(convert_to(v_series_identity || '|' || v_transaction_id,'UTF8'),'sha256'),'hex');
      v_previous_id := null;
      v_version := 1;
      v_late_older := false;
      select id,version_no into v_previous_id,v_version
      from public.meter_reading_series
      where company_id=p_company_id and is_current
        and series_kind=coalesce(v_item->>'seriesKind','actual')
        and coalesce(message_code,'')=coalesce(p_message_code,'')
        and coalesce(external_metering_point_id,'')=coalesce(v_item->>'externalMeteringPointId','')
        and coalesce(grid_area_id,'')=coalesce(v_item->>'gridAreaId','')
        and period_start is not distinct from nullif(v_item->>'periodStart','')::timestamptz
        and period_end is not distinct from nullif(v_item->>'periodEnd','')::timestamptz
        and resolution=coalesce(v_item->>'resolution','UNKNOWN')
        and coalesce(product_id,'')=coalesce(v_item->>'productId','')
        and dedupe_key<>v_dedupe_key
        and exists(select from public.ediel_messages origin where origin.id=meter_reading_series.source_ediel_message_id and origin.company_id=p_company_id and origin.environment=p_environment)
      order by version_no desc limit 1 for update;
      if v_previous_id is not null then
        v_version := v_version + 1;
        -- U-04: a version whose own 532/512 is older than the current one is
        -- retained as history and never displaces newer data on late arrival.
        select coalesce(nullif(v_item->>'latestUpdateDate','')::timestamptz,nullif(v_item->>'registrationDate','')::timestamptz)
               < coalesce(p.latest_update_date,p.registration_date)
          into v_late_older from public.meter_reading_series p where p.id=v_previous_id;
        v_late_older := coalesce(v_late_older,false);
      end if;

      insert into public.meter_reading_series(
        company_id,metering_point_id,source_ediel_message_id,external_metering_point_id,
        grid_area_id,period_start,period_end,resolution,unit,quality_status,dedupe_key,
        message_code,source_transaction_reference,series_kind,product_id,time_series_product,
        actor_context,registration_date,latest_update_date,version_no,supersedes_series_id,
        is_current,correction_reason,raw_transaction,immutable_hash
      ) values (
        p_company_id,nullif(v_item->>'meteringPointId','')::uuid,p_source_message_id,
        nullif(v_item->>'externalMeteringPointId',''),nullif(v_item->>'gridAreaId',''),
        nullif(v_item->>'periodStart','')::timestamptz,nullif(v_item->>'periodEnd','')::timestamptz,
        coalesce(nullif(v_item->>'resolution',''),'UNKNOWN'),coalesce(nullif(v_item->>'unit',''),'KWH'),
        'received',v_dedupe_key,p_message_code,v_transaction_id,coalesce(v_item->>'seriesKind','actual'),
        nullif(v_item->>'productId',''),v_item->'timeSeriesProduct',coalesce(v_item->'actorContext','{}'::jsonb),
        nullif(v_item->>'registrationDate','')::timestamptz,nullif(v_item->>'latestUpdateDate','')::timestamptz,
        v_version,case when v_late_older then null else v_previous_id end,not v_late_older,nullif(v_item->>'correctionReason',''),v_item,
        encode(digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex')
      ) on conflict(company_id,dedupe_key) do nothing returning id into v_series_id;
      v_inserted := v_series_id is not null;
      if not v_inserted then
        select id into v_series_id from public.meter_reading_series
        where company_id=p_company_id and dedupe_key=v_dedupe_key;
      else
        if v_previous_id is not null and not v_late_older then
          update public.meter_reading_series set is_current=false where id=v_previous_id;
        end if;
        v_order := 0;
        for v_quantity in select value from jsonb_array_elements(coalesce(v_item->'quantities','[]'::jsonb))
        loop
          v_order := v_order + 1;
          insert into public.meter_reading_values(
            company_id,series_id,reading_at,quantity,unit,quality,source_order,
            observation_id,qualifier,raw_value,metadata
          ) values (
            p_company_id,v_series_id,nullif(v_quantity->>'readingAt','')::timestamptz,
            nullif(v_quantity->>'value','')::numeric,coalesce(nullif(v_item->>'unit',''),'KWH'),
            coalesce(nullif(v_quantity->>'quality',''),'unknown'),v_order,
            coalesce(nullif(v_quantity->>'observationId',''),v_order::text),
            nullif(v_quantity->>'qualifier',''),v_quantity->>'raw',coalesce(v_quantity->'metadata','{}'::jsonb)
          );
        end loop;
      end if;

      update public.ediel_ack_transaction_results set
        persistence_status='persisted',persisted_series_id=v_series_id,persistence_error=null,updated_at=now()
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','accepted','responseType','positive_aperak',
        'persistenceStatus','persisted','seriesId',v_series_id,'idempotentReplay',not v_inserted
      ));
    exception when others then
      -- A local write error has no national ERR meaning. Propagate it so the
      -- enclosing RPC rolls back this receipt, every sibling and every ACK
      -- reservation together. The original SQLSTATE stays available to ops.
      raise;
    end;
  end loop;
  return v_results;
end $$;

--
-- Name: preserve_committed_projection_v1(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.preserve_committed_projection_v1(c uuid, env text, sid uuid, transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE s public.ediel_messages%rowtype;item jsonb;old_item jsonb;adapted jsonb;answer jsonb:='[]';r gridex_utilts_binding.receipts%rowtype;v public.meter_reading_series%rowtype;
BEGIN
 SELECT * INTO STRICT s FROM public.ediel_messages WHERE company_id=c AND id=sid AND environment=env;
 SELECT * INTO r FROM gridex_utilts_binding.receipts WHERE source_message_id=sid AND company_id=c AND environment=env;
 IF r.source_message_id IS NULL OR r.raw_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR r.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(s) THEN RETURN transactions;END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(transactions) LOOP
  SELECT series.* INTO v FROM public.ediel_ack_transaction_results a JOIN public.meter_reading_series series ON series.id=a.persisted_series_id AND series.company_id=a.company_id
   WHERE a.company_id=c AND a.environment=env AND a.source_message_id=sid AND a.source_transaction_id=item->>'transactionId'
    AND a.disposition='accepted' AND a.persistence_status='persisted' AND a.planned_response_type='positive_aperak' FOR SHARE OF a,series;
  IF FOUND AND v.immutable_hash=encode(sha256(convert_to(v.raw_transaction::text,'UTF8')),'hex') THEN
   old_item:=v.raw_transaction;
   -- Only the newly introduced metadata fields differ. V1's existing numeric
   -- comparison remains the immutable private owner's exact original shape.
   adapted:=(item-'productId')||jsonb_build_object('periodStart',item#>'{consumptionContract,interpretation,localPeriodStart}','periodEnd',item#>'{consumptionContract,interpretation,localPeriodEnd}');
   IF r.contract_version=1 THEN adapted:=gridex_utilts_binding.legacy_retry_item_v1(adapted);END IF;
   IF adapted IS NOT DISTINCT FROM old_item THEN item:=adapted;END IF;
  END IF;
  answer:=answer||jsonb_build_array(item);
 END LOOP;
 RETURN answer;
END $$;

--
-- Name: require_current_esco_storage_v1(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.require_current_esco_storage_v1(c uuid, env text, sourceid uuid, transactions jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE ctx jsonb;source public.ediel_messages%rowtype;tokens jsonb;item jsonb;contract jsonb;point text;product text;period text;offset_value text;v_period_start timestamptz;v_period_end timestamptz;
 own_start int;own_end int;header_end int;sender text;candidate uuid;candidates uuid[];
 a public.ediel_service_assignments%rowtype;g public.ediel_data_access_grants%rowtype;l public.ediel_assignment_permission_links%rowtype;p public.metering_permissions%rowtype;dso_ids text[];
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1();
 -- The private receipt decides the legal role; caller JSON cannot opt out.
 SELECT context INTO ctx FROM gridex_ediel_inbound_context.receipts WHERE company_id=c AND source_message_id=sourceid AND environment=env AND status='ready';
 IF ctx IS NULL THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(transactions) x WHERE x->>'disposition'='accepted') THEN PERFORM gridex_ediel_inbound_context.require_v1(c,sourceid);END IF;
  RETURN;
 END IF;
 ctx:=gridex_ediel_inbound_context.require_v1(c,sourceid);
 IF (ctx->>'actorRole' IN ('energy_service_company','esco')) IS NOT TRUE THEN RETURN;END IF;
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,env,sourceid);
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE company_id=c AND id=sourceid AND environment=env FOR SHARE;
 IF ctx->>'family' IS DISTINCT FROM 'UTILTS' OR ctx->>'code' IS DISTINCT FROM 'E66' OR source.direction IS DISTINCT FROM 'inbound'
 OR source.message_family IS DISTINCT FROM 'UTILTS' OR source.message_code IS DISTINCT FROM 'E66'
 OR ctx->>'applicationReference' IS DISTINCT FROM source.application_reference OR (ctx->>'applicationReference' ~ '^23-(DDQ|DGI)-E66-(S|T)$') IS NOT TRUE THEN RAISE EXCEPTION 'utilts_esco_source_scope_unqualified' USING ERRCODE='42501';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 SELECT min(x#>>'{elements,2,0}') INTO sender FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS';
 IF sender IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS')<>1 THEN RAISE EXCEPTION 'utilts_esco_source_dso_unqualified' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(transactions) LOOP
  -- Every requested outcome must be the actual canonical private own-IDE facet.
  PERFORM gridex_received_sources.require_utilts_transaction_v1(c,sourceid,item->>'transactionId',item->>'disposition',item->>'responseType',item->'issueCodes');
  -- A protocol-prescribed negative own-original response needs communication
  -- authority/current local role, but does not authorize positive business data.
  IF item->>'disposition'<>'accepted' THEN CONTINUE;END IF;
  PERFORM gridex_ediel_source_rules.require_v1(c,sourceid);
  contract:=item->'consumptionContract';
  IF NOT coalesce(gridex_utilts_binding.validate_contract_v1(contract),false) OR contract->>'companyId' IS DISTINCT FROM c::text OR contract->>'environment' IS DISTINCT FROM env OR contract->>'messageCode' IS DISTINCT FROM 'E66' OR contract->>'seriesKind' IS DISTINCT FROM 'actual' OR item->>'seriesKind' IS DISTINCT FROM 'actual' OR contract->>'transactionId' IS DISTINCT FROM item->>'transactionId' THEN RAISE EXCEPTION 'utilts_esco_contract_scope_unqualified' USING ERRCODE='42501';END IF;
  point:=gridex_utilts_binding.supported_point_v1(tokens,item->>'transactionId');
  SELECT (x->>'index')::int INTO STRICT own_start FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='IDE' AND x#>>'{elements,2,0}'=item->>'transactionId';
  SELECT min((x->>'index')::int) INTO own_end FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::int>own_start AND x->>'tag' IN('IDE','UNT');
  SELECT coalesce(min((x->>'index')::int),own_end) INTO header_end FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::int>own_start AND (x->>'index')::int<own_end AND x->>'tag'='SEQ';
  SELECT x#>>'{elements,3,0}' INTO STRICT product FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='LIN' AND (x->>'index')::int>own_start AND (x->>'index')::int<header_end AND x#>>'{elements,3,3}'='9';
  SELECT x#>>'{elements,1,1}' INTO STRICT period FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='DTM' AND (x->>'index')::int>own_start AND (x->>'index')::int<header_end AND x#>>'{elements,1,0}'='324' AND x#>>'{elements,1,2}'='719';
  SELECT x#>>'{elements,1,1}' INTO STRICT offset_value FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='DTM' AND (x->>'index')::int<own_start AND x#>>'{elements,1,0}'='735' AND x#>>'{elements,1,2}'='406';
  v_period_start:=gridex_utilts_binding.esco_local_time_v1(substr(period,1,12),offset_value);v_period_end:=gridex_utilts_binding.esco_local_time_v1(substr(period,13,12),offset_value);
  IF point IS NULL OR period !~ '^[0-9]{24}$' OR nullif(product,'') IS NULL OR v_period_start IS NULL OR v_period_end IS NULL OR v_period_end<=v_period_start
  OR item->>'externalMeteringPointId' IS DISTINCT FROM point OR item->>'productId' IS DISTINCT FROM product OR (item->>'periodStart')::timestamptz IS DISTINCT FROM v_period_start OR (item->>'periodEnd')::timestamptz IS DISTINCT FROM v_period_end
  OR (contract#>>'{interpretation,localPeriodStart}')::timestamp IS DISTINCT FROM (v_period_start+make_interval(mins=>(substr(offset_value,2,2)::int*60+substr(offset_value,4,2)::int)*CASE left(offset_value,1) WHEN '-' THEN -1 ELSE 1 END)) AT TIME ZONE 'UTC' OR (contract#>>'{interpretation,localPeriodEnd}')::timestamp IS DISTINCT FROM (v_period_end+make_interval(mins=>(substr(offset_value,2,2)::int*60+substr(offset_value,4,2)::int)*CASE left(offset_value,1) WHEN '-' THEN -1 ELSE 1 END)) AT TIME ZONE 'UTC' OR contract#>>'{interpretation,timezoneRaw}' IS DISTINCT FROM offset_value
  OR EXISTS(SELECT FROM jsonb_array_elements(contract->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM point OR o->>'productCode' IS DISTINCT FROM product OR (o->>'periodStart')::timestamptz<v_period_start OR (o->>'periodEnd')::timestamptz>v_period_end) THEN RAISE EXCEPTION 'utilts_esco_physical_scope_unqualified' USING ERRCODE='42501';END IF;
  PERFORM gridex_ediel_ack_replay.current_service_grant_set_v2(c,env,ctx,sender,point,product,v_period_start,v_period_end,contract,NULL);
  IF (ctx->>'applicationReference' ~ '^23-DGI-E66-(S|T)$') IS TRUE THEN
   PERFORM gridex_ediel_services.require_periodic_reason_v1(c,env,sourceid,item->>'transactionId');
  END IF;

 END LOOP;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'utilts_esco_physical_scope_unqualified' USING ERRCODE='42501';END $_$;

--
-- Name: require_execution_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.require_execution_actor_v1(p_company_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL
  OR NOT EXISTS(SELECT FROM auth.users u WHERE u.id=p_actor_user_id AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp()))
  OR NOT EXISTS(SELECT FROM public.companies c WHERE c.id=p_company_id AND coalesce(c.is_active,true)
    AND coalesce(c.status,'active') NOT IN('archived','suspended','pending_deletion','deleted'))
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id
    AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR gridex_bilateral_customer_sources.classified_scoped_permission_wallclock_v1(p_company_id,p_actor_user_id,'metering.write') IS NOT TRUE THEN
  RAISE EXCEPTION 'utilts_execution_actor_forbidden' USING ERRCODE='42501';END IF;
END $$;

--
-- Name: require_positive_storage_authority_v1(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.require_positive_storage_authority_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_transaction_id text, p_ack_message_id uuid DEFAULT NULL::uuid, p_ack_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 source public.ediel_messages%rowtype; ack public.ediel_messages%rowtype;
 receipt gridex_utilts_binding.receipts%rowtype; origin gridex_utilts_binding.receipts%rowtype;
 reservation public.ediel_ack_transaction_results%rowtype;
 series public.meter_reading_series%rowtype; stored gridex_utilts_binding.contracts%rowtype;
 tokens jsonb; ack_tokens jsonb; source_hash text; ack_hash text; document_id text;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_source_message_id IS NULL
 OR nullif(p_transaction_id,'') IS NULL OR (p_ack_message_id IS NULL)<>(p_ack_raw_payload IS NULL) THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01';
 END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
 IF NOT FOUND OR source.direction<>'inbound' OR source.message_family<>'UTILTS' OR source.raw_payload IS NULL THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 source_hash:=encode(digest(convert_to(source.raw_payload,'UTF8'),'sha256'),'hex');
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=source.id;
 IF NOT FOUND OR receipt.company_id IS DISTINCT FROM p_company_id OR receipt.environment IS DISTINCT FROM p_environment
 OR receipt.raw_hash IS DISTINCT FROM source_hash OR receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(source)
 OR NOT receipt.membership ? p_transaction_id THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,1,0}'='24' AND t#>>'{elements,2,0}'=p_transaction_id)<>1 THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=p_company_id AND environment=p_environment
  AND source_message_id=source.id AND source_transaction_id=p_transaction_id FOR SHARE;
 IF NOT FOUND OR reservation.disposition IS DISTINCT FROM 'accepted' OR reservation.planned_response_type IS DISTINCT FROM 'positive_aperak'
 OR reservation.persistence_status IS DISTINCT FROM 'persisted' OR reservation.persisted_series_id IS NULL
 OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'positive_aperak') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO series FROM public.meter_reading_series WHERE id=reservation.persisted_series_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR series.message_code IS DISTINCT FROM source.message_code OR series.source_transaction_reference IS DISTINCT FROM p_transaction_id
 OR jsonb_typeof(series.raw_transaction) IS DISTINCT FROM 'object'
 OR series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(series.raw_transaction::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 -- Identical old/late accepted data can legitimately reuse an earlier series.
 -- Its genuine source/contract origin stays authoritative; is_current is not an
 -- acceptance criterion and must not silently reject old-late-positive ACKs.
 SELECT * INTO origin FROM gridex_utilts_binding.receipts WHERE source_message_id=series.source_ediel_message_id;
 SELECT * INTO stored FROM gridex_utilts_binding.contracts WHERE series_id=series.id;
 IF origin.source_message_id IS NULL OR stored.series_id IS NULL OR origin.company_id IS DISTINCT FROM p_company_id
 OR origin.environment IS DISTINCT FROM p_environment OR origin.message_code IS DISTINCT FROM source.message_code
 OR stored.company_id IS DISTINCT FROM p_company_id OR stored.environment IS DISTINCT FROM p_environment
 OR stored.source_message_id IS DISTINCT FROM origin.source_message_id OR stored.transaction_id IS DISTINCT FROM p_transaction_id
 OR stored.contract_version NOT IN (1,2) OR stored.contract->>'version' IS DISTINCT FROM stored.contract_version::text
 OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(stored.contract),false)
 OR stored.contract_hash IS DISTINCT FROM encode(digest(convert_to(stored.contract::text,'UTF8'),'sha256'),'hex')
 OR stored.contract IS DISTINCT FROM series.raw_transaction->'consumptionContract' THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 IF p_ack_message_id IS NOT NULL THEN
  SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
  IF NOT FOUND OR ack.direction<>'outbound' OR ack.message_family<>'APERAK' OR ack.related_message_id IS DISTINCT FROM source.id
  OR ack.raw_payload IS DISTINCT FROM p_ack_raw_payload OR reservation.final_response_type IS DISTINCT FROM 'positive_aperak'
  OR reservation.response_message_id IS DISTINCT FROM ack.id OR reservation.finalized_at IS NULL THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  SELECT t#>>'{elements,2,0}' INTO document_id FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  IF ack_tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='UNH'
    AND t#>>'{elements,2,0}'='APERAK' AND t#>>'{elements,2,2}'='04A' AND t#>>'{elements,2,4}'='E5SE5A')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='312')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)<>1
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM')
      <>(SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW')
   OR EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       AND (nullif(t#>>'{elements,1,1}','') IS NULL OR length(t#>>'{elements,1,1}')>35 OR btrim(t#>>'{elements,1,1}') IS DISTINCT FROM t#>>'{elements,1,1}'))
   OR EXISTS(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       GROUP BY t#>>'{elements,1,1}' HAVING count(*)>1)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='DOC' AND t#>>'{elements,2,0}'=document_id)<>1 THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_hash:=encode(digest(convert_to(ack.raw_payload,'UTF8'),'sha256'),'hex');
 END IF;
 IF p_ack_message_id IS NOT NULL AND EXISTS(SELECT FROM gridex_ediel_inbound_context.receipts x WHERE x.company_id=p_company_id AND x.source_message_id=source.id AND x.environment=p_environment AND x.status='ready' AND x.context->>'actorRole' IN('energy_service_company','esco')) THEN
  PERFORM gridex_ediel_ack_replay.require_positive_service_scope_v1(p_company_id,p_environment,source.id,ack.raw_payload);
 END IF;
 RETURN jsonb_build_object('authorityVersion',1,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',source.id,
  'transactionId',p_transaction_id,'sourceRawHash',source_hash,'ackMessageId',p_ack_message_id,'ackRawHash',ack_hash);
END $$;

--
-- Name: source_context_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.source_context_v1(s public.ediel_messages) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',s.id,'company',s.company_id,'environment',s.environment,'direction',s.direction,
 'family',s.message_family,'code',s.message_code,'sender',s.sender_ediel_id,'receiver',s.receiver_ediel_id,
 'senderSubAddress',s.sender_sub_address,'receiverSubAddress',s.receiver_sub_address,
 'interchange',s.interchange_reference,'transaction',s.transaction_reference,'application',s.application_reference,
 'originalMessage',s.original_message_id,'externalReference',s.external_reference)
$$;

--
-- Name: stored_contract_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.stored_contract_v1(p_company uuid, p_source uuid, p_transaction text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_source public.ediel_messages%rowtype; v_receipt gridex_utilts_binding.receipts%rowtype;
 v_ack public.ediel_ack_transaction_results%rowtype; v_series public.meter_reading_series%rowtype;
 v_contract gridex_utilts_binding.contracts%rowtype; v_point text;
BEGIN
 SELECT s.* INTO v_source FROM public.ediel_messages s WHERE s.id=p_source AND s.company_id=p_company FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'utilts_consumption_source_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT r.* INTO v_receipt FROM gridex_utilts_binding.receipts r WHERE r.source_message_id=p_source AND r.company_id=p_company;
 IF NOT FOUND OR v_receipt.environment IS DISTINCT FROM v_source.environment OR v_receipt.message_code IS DISTINCT FROM v_source.message_code
 OR v_receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(v_source)
 OR v_receipt.raw_hash IS DISTINCT FROM encode(digest(convert_to(v_source.raw_payload,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_consumption_source_binding_invalid' USING ERRCODE='P0U01'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements_text(v_receipt.membership) m(transaction_id) WHERE NOT EXISTS(
  SELECT FROM public.ediel_ack_transaction_results a WHERE a.company_id=p_company AND a.environment=v_source.environment AND a.source_message_id=p_source AND a.source_transaction_id=m.transaction_id))
 OR (SELECT count(*) FROM public.ediel_ack_transaction_results a WHERE a.source_message_id=p_source)<>jsonb_array_length(v_receipt.membership) THEN
  RAISE EXCEPTION 'utilts_consumption_membership_incomplete' USING ERRCODE='P0U01'; END IF;
 SELECT a.* INTO v_ack FROM public.ediel_ack_transaction_results a WHERE a.company_id=p_company AND a.environment=v_source.environment
 AND a.source_message_id=p_source AND a.source_transaction_id=p_transaction FOR SHARE;
 IF NOT FOUND OR v_ack.disposition IS DISTINCT FROM 'accepted' OR v_ack.persistence_status IS DISTINCT FROM 'persisted'
 OR v_ack.planned_response_type IS DISTINCT FROM 'positive_aperak' THEN RAISE EXCEPTION 'utilts_consumption_not_accepted' USING ERRCODE='P0U01'; END IF;
 SELECT s.* INTO v_series FROM public.meter_reading_series s WHERE s.id=v_ack.persisted_series_id AND s.company_id=p_company FOR SHARE;
 IF NOT FOUND OR v_series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(v_series.raw_transaction::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_consumption_raw_conflict' USING ERRCODE='P0U01'; END IF;
 SELECT c.* INTO v_contract FROM gridex_utilts_binding.contracts c WHERE c.series_id=v_series.id AND c.company_id=p_company;
 IF NOT FOUND OR v_contract.contract_version NOT IN (1,2) OR v_contract.contract_version IS DISTINCT FROM v_receipt.contract_version
 OR v_contract.contract->'version' IS DISTINCT FROM to_jsonb(v_contract.contract_version) OR v_contract.environment IS DISTINCT FROM v_source.environment OR v_contract.transaction_id IS DISTINCT FROM p_transaction
 OR v_contract.contract->>'companyId' IS DISTINCT FROM p_company::text OR v_contract.contract->>'environment' IS DISTINCT FROM v_source.environment
 OR v_contract.contract->>'messageCode' IS DISTINCT FROM v_source.message_code OR v_contract.contract->>'transactionId' IS DISTINCT FROM p_transaction
 OR v_contract.contract_hash IS DISTINCT FROM encode(digest(convert_to(v_contract.contract::text,'UTF8'),'sha256'),'hex')
 OR v_contract.contract IS DISTINCT FROM v_series.raw_transaction->'consumptionContract'
 OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(v_contract.contract),false) THEN
  RAISE EXCEPTION 'utilts_consumption_contract_conflict' USING ERRCODE='P0U01'; END IF;
 -- Pre-forward receipts are not a namespace approval either. All sinks use
 -- this check, including direct calls with an already committed contract.
 v_point:=gridex_utilts_binding.supported_point_v1(gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload),p_transaction);
 IF v_point IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(v_contract.contract->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM v_point) THEN
  RAISE EXCEPTION 'utilts_consumption_identity_unsupported' USING ERRCODE='P0U01'; END IF;
 IF v_contract.contract_version=2 AND NOT coalesce(gridex_utilts_binding.validate_decimal_source_v2(gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload),v_series.raw_transaction,
  CASE WHEN left(v_source.raw_payload,3)='UNA' THEN substring(v_source.raw_payload,6,1) ELSE '.' END),false) THEN
  RAISE EXCEPTION 'utilts_consumption_decimal_source_conflict' USING ERRCODE='P0U01'; END IF;
 RETURN v_contract.contract;
END $$;

--
-- Name: supported_point_v1(jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.supported_point_v1(tokens jsonb, transaction_id text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE first_ide integer; start_at integer; stop_at integer; end_at integer; point jsonb; party jsonb; role_name text;
BEGIN
 SELECT min((t->>'index')::integer) INTO first_ide FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE';
 FOREACH role_name IN ARRAY ARRAY['MS','MR'] LOOP
  SELECT jsonb_agg(t) INTO party FROM jsonb_array_elements(tokens) t
   WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'=role_name AND (t->>'index')::integer<first_ide;
  IF jsonb_array_length(party) IS DISTINCT FROM 1 OR party#>'{0,elements,1}' IS DISTINCT FROM jsonb_build_array(role_name)
   OR jsonb_array_length(party#>'{0,elements,2}') IS DISTINCT FROM 3
   OR nullif(btrim(party#>>'{0,elements,2,0}'),'') IS NULL
   OR party#>>'{0,elements,2,0}' IS DISTINCT FROM btrim(party#>>'{0,elements,2,0}')
   OR party#>>'{0,elements,2,1}' IS DISTINCT FROM 'SVK' OR party#>>'{0,elements,2,2}' IS DISTINCT FROM '260' THEN RETURN NULL; END IF;
 END LOOP;
 SELECT jsonb_agg(t) INTO point FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=transaction_id;
 IF jsonb_array_length(point) IS DISTINCT FROM 1 OR point#>'{0,elements,1}' IS DISTINCT FROM '["24"]'::jsonb
  OR point#>'{0,elements,2}' IS DISTINCT FROM jsonb_build_array(transaction_id) THEN RETURN NULL; END IF;
 start_at:=(point#>>'{0,index}')::integer;
 SELECT min((t->>'index')::integer) INTO end_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 IF end_at IS NULL THEN RETURN NULL; END IF;
 -- Preserve the previously reviewed LOC+175 physical-IDE refusal.
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC'
   AND t#>>'{elements,1,0}'='175' AND (t->>'index')::integer>start_at
   AND (t->>'index')::integer<end_at) THEN RETURN NULL; END IF;
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','SEQ','UNT');
 -- A post-SEQ LOC+172 is still inside this IDE, even though it is outside
 -- the SG5 header selected below. Earlier duplicate LOC+172 is caught there.
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC'
   AND t#>>'{elements,1,0}'='172' AND (t->>'index')::integer>=stop_at
   AND (t->>'index')::integer<end_at) THEN RETURN NULL; END IF;
 SELECT jsonb_agg(t) INTO point FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 IF jsonb_array_length(point) IS DISTINCT FROM 1 OR point#>'{0,elements,1}' IS DISTINCT FROM '["172"]'::jsonb
  OR jsonb_array_length(point#>'{0,elements,2}') IS DISTINCT FROM 3
  OR point#>>'{0,elements,2,1}' IS DISTINCT FROM '' OR point#>>'{0,elements,2,2}' IS DISTINCT FROM '9'
  OR nullif(btrim(point#>>'{0,elements,2,0}'),'') IS NULL
  OR point#>>'{0,elements,2,0}' IS DISTINCT FROM btrim(point#>>'{0,elements,2,0}')
  OR point#>>'{0,elements,2,0}' ~ '[[:cntrl:]]' THEN RETURN NULL; END IF;
 RETURN point#>>'{0,elements,2,0}';
END $$;

--
-- Name: unowned_regulating_object_v1(jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.unowned_regulating_object_v1(tokens jsonb, transaction_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(
  SELECT 1 FROM jsonb_array_elements(tokens) ide
  JOIN jsonb_array_elements(tokens) loc ON (loc->>'index')::integer>(ide->>'index')::integer
  WHERE ide->>'tag'='IDE' AND ide#>>'{elements,1,0}'='24'
   AND ide#>>'{elements,2,0}'=transaction_id
   AND loc->>'tag'='LOC' AND loc#>>'{elements,1,0}'='175'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(tokens) boundary
    WHERE boundary->>'tag' IN ('IDE','UNT')
     AND (boundary->>'index')::integer>(ide->>'index')::integer
     AND (boundary->>'index')::integer<(loc->>'index')::integer)
 )
$$;

--
-- Name: valid_rejected_item_v3(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.valid_rejected_item_v3(item jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(item->>'disposition'='guide_rejected' AND item->>'responseType'='negative_aperak'
  AND jsonb_typeof(item->'issueCodes')='array' AND item->'issueCodes' ? 'UTILTS_TRANSACTION_ID_INVALID'
  AND item->>'transactionId'=item#>>'{consumptionContract,transactionId}'
  AND gridex_utilts_binding.validate_rejected_contract_v3(item->'consumptionContract'),false)
$$;

--
-- Name: valid_transaction_reference_v2(text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.valid_transaction_reference_v2(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT value IS NOT NULL AND char_length(value) BETWEEN 1 AND 35
  AND value !~ '^ *$' AND right(value,1)<>' '
  AND NOT EXISTS(SELECT FROM generate_series(1,char_length(value)) n
   WHERE ascii(substr(value,n,1))<32 OR ascii(substr(value,n,1)) BETWEEN 127 AND 159 OR ascii(substr(value,n,1))>255)
$_$;

--
-- Name: validate_contract_base_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_contract_base_v1(c jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a jsonb; o jsonb; i jsonb; field text; n integer:=0; seen jsonb:='[]'; contribution jsonb;
BEGIN
 IF NOT coalesce(gridex_utilts_binding.exact_keys_v1(c,'version projectionVersion attributionVersion companyId environment messageCode transactionId seriesKind profileKey profileVersion rulePackHash guideRevision interpretation observations metering billing billingContributionOrdinals sourceType'),false)
 OR c->'version' IS DISTINCT FROM '1'::jsonb OR c->>'projectionVersion' IS DISTINCT FROM 'utilts-consumption-v1' OR c->>'attributionVersion' IS DISTINCT FROM 'tenant-match-v1'
 OR c->>'sourceType' IS DISTINCT FROM 'ediel_utilts' OR c->>'environment' NOT IN ('test','production')
 OR jsonb_typeof(c->'observations')<>'array' OR jsonb_typeof(c->'billingContributionOrdinals')<>'array' THEN RETURN false; END IF;
 FOREACH field IN ARRAY ARRAY['environment','companyId','messageCode','transactionId','seriesKind','guideRevision'] LOOP
  IF jsonb_typeof(c->field)<>'string' OR nullif(btrim(c->>field),'') IS NULL THEN RETURN false; END IF;
 END LOOP;
 PERFORM (c->>'companyId')::uuid;
 IF EXISTS(SELECT FROM jsonb_each(c) e WHERE e.key IN ('profileKey','profileVersion','rulePackHash') AND jsonb_typeof(e.value) NOT IN ('string','null')) THEN RETURN false; END IF;
 i:=c->'interpretation';
 IF NOT coalesce(gridex_utilts_binding.exact_keys_v1(i,'localPeriodStart localPeriodEnd localRegistration resolutionValue resolutionFormat timezoneRaw timezoneFormat offsetMinutes timestampPolicy'),false)
 OR jsonb_typeof(i->'timestampPolicy')<>'string' OR i->>'timestampPolicy' NOT IN ('explicit-offset-v1','no-consumption-v1')
 OR (i->'timezoneFormat'<>'null'::jsonb AND i->>'timezoneFormat'<>'406')
 OR (i->'offsetMinutes'<>'null'::jsonb AND (jsonb_typeof(i->'offsetMinutes')<>'number' OR (i->>'offsetMinutes')::numeric<>trunc((i->>'offsetMinutes')::numeric) OR abs((i->>'offsetMinutes')::numeric)>840)) THEN RETURN false; END IF;
 FOREACH field IN ARRAY ARRAY['localPeriodStart','localPeriodEnd','localRegistration','resolutionValue','resolutionFormat','timezoneRaw'] LOOP
  IF jsonb_typeof(i->field) NOT IN ('string','null') THEN RETURN false; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['metering','billing'] LOOP
  a:=c->field;
  IF NOT coalesce(gridex_utilts_binding.exact_keys_v1(a,'capability reason customerId siteId customerSiteId meteringPointId gridOwnerId sourceRequestId'||CASE WHEN field='billing' THEN ' requestScope periodStart periodEnd month year status sourceSystem currency' ELSE '' END),false)
  OR jsonb_typeof(a->'capability')<>'string' OR a->>'capability' NOT IN ('write','skip') OR (a->>'capability'='skip' AND nullif(a->>'reason','') IS NULL)
  OR (a->>'capability'='write' AND (a->>'customerId' IS NULL OR a->'reason'<>'null'::jsonb OR (field='metering' AND a->>'meteringPointId' IS NULL))) THEN RETURN false; END IF;
  IF EXISTS(SELECT FROM jsonb_each(a) e WHERE e.key IN ('customerId','siteId','customerSiteId','meteringPointId','gridOwnerId','sourceRequestId','reason') AND jsonb_typeof(e.value) NOT IN ('string','null')) THEN RETURN false; END IF;
  IF field='billing' THEN
   IF a->>'status' IS DISTINCT FROM 'received' OR a->>'sourceSystem' IS DISTINCT FROM 'ediel_utilts' OR a->>'currency' IS DISTINCT FROM 'SEK'
   OR (a->'periodStart'<>'null'::jsonb AND NOT gridex_utilts_binding.absolute_v1(a->'periodStart'))
   OR (a->'periodEnd'<>'null'::jsonb AND NOT gridex_utilts_binding.absolute_v1(a->'periodEnd'))
   OR (a->>'capability'='write' AND (a->>'sourceRequestId' IS NULL OR a->>'requestScope'<>'billing_underlay' OR a->>'periodEnd' IS NULL OR a->>'month' IS NULL OR a->>'year' IS NULL)) THEN RETURN false; END IF;
   IF coalesce(a->>'periodEnd',a->>'periodStart') IS NOT NULL AND
    ((a->>'month')::integer IS DISTINCT FROM extract(month FROM coalesce(a->>'periodEnd',a->>'periodStart')::timestamptz)::integer OR
     (a->>'year')::integer IS DISTINCT FROM extract(year FROM coalesce(a->>'periodEnd',a->>'periodStart')::timestamptz)::integer) THEN RETURN false; END IF;
  END IF;
 END LOOP;
 FOR o IN SELECT value FROM jsonb_array_elements(c->'observations') LOOP
  IF NOT coalesce(gridex_utilts_binding.exact_keys_v1(o,'ordinal sourceOrdinal quantity periodStart periodEnd readAt resolution unit quality readingType direction registerCode productCode sourceLineReference externalPoint gridArea'),false)
  OR o->'ordinal' IS DISTINCT FROM to_jsonb(n) OR jsonb_typeof(o->'sourceOrdinal')<>'number' OR (o->>'sourceOrdinal')::numeric<>trunc((o->>'sourceOrdinal')::numeric)
  OR (o->>'sourceOrdinal')::numeric<0 OR seen @> jsonb_build_array(o->'sourceOrdinal')
  OR jsonb_typeof(o->'quantity')<>'number' OR NOT gridex_utilts_binding.absolute_v1(o->'periodStart') OR NOT gridex_utilts_binding.absolute_v1(o->'periodEnd') OR NOT gridex_utilts_binding.absolute_v1(o->'readAt')
  OR o->>'periodStart'>=o->>'periodEnd' OR o->>'unit' IS DISTINCT FROM 'kWh' OR jsonb_typeof(o->'readingType')<>'string' OR o->>'readingType' NOT IN ('consumption','production','estimated','adjustment')
  OR o->>'direction' IS DISTINCT FROM (CASE WHEN o->>'readingType'='production' THEN 'production' ELSE 'consumption' END) THEN RETURN false; END IF;
  IF EXISTS(SELECT FROM jsonb_each(o) e WHERE e.key IN ('resolution','quality','registerCode','productCode','sourceLineReference','externalPoint','gridArea') AND jsonb_typeof(e.value) NOT IN ('string','null')) THEN RETURN false; END IF;
  seen:=seen||jsonb_build_array(o->'sourceOrdinal'); n:=n+1;
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY x),'[]') INTO contribution FROM generate_series(0,n-1) x WHERE c#>>'{billing,capability}'='write';
 IF c->'billingContributionOrdinals' IS DISTINCT FROM contribution THEN RETURN false; END IF;
 IF i->>'timestampPolicy'='no-consumption-v1' AND (n<>0 OR c#>>'{metering,capability}'<>'skip' OR c#>>'{billing,capability}'<>'skip') THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: validate_contract_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_contract_v1(c jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o jsonb; observations jsonb:='[]'; projected jsonb;
BEGIN
 IF c->'version'='1'::jsonb THEN RETURN gridex_utilts_binding.validate_legacy_contract_v1(c); END IF;
 IF c->'version' IS DISTINCT FROM '2'::jsonb OR c->>'projectionVersion' IS DISTINCT FROM 'utilts-consumption-v2'
  OR jsonb_typeof(c->'observations') IS DISTINCT FROM 'array'
  OR jsonb_typeof(c->'transactionId') IS DISTINCT FROM 'string'
  OR NOT coalesce(gridex_utilts_binding.valid_transaction_reference_v2(c->>'transactionId'),false) THEN RETURN false; END IF;
 FOR o IN SELECT value FROM jsonb_array_elements(c->'observations') LOOP
  IF jsonb_typeof(o->'quantity') IS DISTINCT FROM 'string'
   OR gridex_utilts_binding.canonical_decimal_v2(o->>'quantity') IS DISTINCT FROM o->>'quantity' THEN RETURN false; END IF;
  -- Reuse the strict frozen V1 shape/time/attribution predicates with an exact
  -- numeric JSON projection. This is validation only, never stored V2 content.
  observations:=observations||jsonb_build_array(o||jsonb_build_object('quantity',(o->>'quantity')::numeric));
 END LOOP;
 projected:=c||jsonb_build_object('version',1,'projectionVersion','utilts-consumption-v1','observations',observations,'transactionId',btrim(c->>'transactionId'));
 -- The frozen validator checks padded text generically. This shape-only copy
 -- uses its nonempty canonical form AFTER exact physical U505 validation.
 -- No stored contract, hash, original or consumer reference is normalized.
 RETURN gridex_utilts_binding.validate_legacy_contract_v1(projected);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: validate_decimal_source_v2(jsonb, jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_decimal_source_v2(tokens jsonb, item jsonb, decimal_mark text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE start_at integer; stop_at integer; first_sequence integer; sequence_at integer; next_sequence integer;
 quantities jsonb; source_quantity jsonb; supplied jsonb; o jsonb; ordinal integer; unit text; own_mea jsonb; scale numeric; code text; energy_unit text; quality_end integer;
BEGIN
 IF item->>'disposition'<>'accepted' THEN RETURN true; END IF;
 SELECT t#>>'{elements,1,0}' INTO STRICT code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
 SELECT (t->>'index')::integer INTO STRICT start_at FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=item->>'transactionId';
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 SELECT coalesce(min((t->>'index')::integer),stop_at) INTO first_sequence FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='SEQ' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 SELECT jsonb_agg(t) INTO own_mea FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='MEA'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence;
 IF own_mea IS NOT NULL THEN
  IF jsonb_array_length(own_mea) IS DISTINCT FROM 1 OR own_mea#>>'{0,elements,1,0}' IS DISTINCT FROM 'AAZ' THEN RETURN false; END IF;
  unit:=own_mea#>>'{0,elements,3,0}';
  IF nullif(unit,'') IS NULL THEN RETURN false; END IF;
 END IF;
 -- A source-only request, dated E30 reading or monetary series may have no
 -- field264. Preserve its exact raw values without inventing a kWh consumer.
 IF unit IS DISTINCT FROM item->>'unit' OR (code='E30' AND own_mea IS NOT NULL) THEN RETURN false; END IF;
 energy_unit:=unit;
 -- U p36 requires standard E30 quarter/month/year energy in kWh, while p85
 -- excludes MEA. This explicit source condition never manufactures a raw MEA.
 IF code='E30' AND unit IS NULL AND (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence AND t#>>'{elements,1,0}'='354')=1
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence AND t#>>'{elements,1,0}'='354'
  AND ((t#>>'{elements,1,1}'='15' AND t#>>'{elements,1,2}'='806') OR (t#>>'{elements,1,1}'='1' AND t#>>'{elements,1,2}' IN ('801','802'))))
 THEN energy_unit:='KWH'; END IF;
 IF code IN ('E31','E66','S07','S02','S03','S04') AND unit IS NULL THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(t ORDER BY (t->>'index')::integer),'[]') INTO quantities FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='QTY' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 IF code IN ('S01','S05') AND jsonb_array_length(quantities)>0 AND unit IS NULL THEN RETURN false; END IF;
 IF jsonb_typeof(item->'quantities') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'quantities')<>jsonb_array_length(quantities) THEN RETURN false; END IF;
 FOR ordinal IN 0..jsonb_array_length(quantities)-1 LOOP
  source_quantity:=quantities->ordinal; supplied:=item->'quantities'->ordinal;
  IF supplied->>'qualifier' IS DISTINCT FROM source_quantity#>>'{elements,1,0}'
   OR nullif(source_quantity#>>'{elements,1,2}','') IS NOT NULL THEN RETURN false; END IF;
  SELECT max((t->>'index')::integer) INTO sequence_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ'
   AND (t->>'index')::integer>start_at AND (t->>'index')::integer<(source_quantity->>'index')::integer;
  SELECT coalesce(min((t->>'index')::integer),stop_at) INTO next_sequence FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ'
   AND (t->>'index')::integer>sequence_at AND (t->>'index')::integer<stop_at;
  IF sequence_at IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='MEA'
   AND (t->>'index')::integer>sequence_at AND (t->>'index')::integer<next_sequence
   AND (t#>>'{elements,1,0}' IS DISTINCT FROM 'AAZ' OR t#>>'{elements,3,0}' IS DISTINCT FROM unit)) THEN RETURN false; END IF;
  IF source_quantity#>>'{elements,1,0}' IN ('136','220') AND source_quantity#>>'{elements,1,1}'='NULL' THEN
   IF source_quantity#>>'{elements,1,0}'='136' OR code='E30' THEN
    SELECT coalesce(min((t->>'index')::integer),next_sequence) INTO quality_end FROM jsonb_array_elements(tokens) t
     WHERE t->>'tag'='QTY' AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<next_sequence;
    IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS'
     AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<quality_end
     AND t#>>'{elements,1,0}'='8' AND t#>>'{elements,2,0}'='46') THEN RETURN false; END IF;
   END IF;
   IF supplied->'value' IS DISTINCT FROM 'null'::jsonb THEN RETURN false; END IF;
  ELSIF jsonb_typeof(supplied->'value') IS DISTINCT FROM 'string'
   OR gridex_utilts_binding.canonical_decimal_v2(source_quantity#>>'{elements,1,1}',decimal_mark) IS DISTINCT FROM supplied->>'value'
   OR gridex_utilts_binding.canonical_decimal_v2(supplied->>'value') IS DISTINCT FROM supplied->>'value' THEN RETURN false; END IF;
 END LOOP;
 FOR o IN SELECT value FROM jsonb_array_elements(item#>'{consumptionContract,observations}') LOOP
  source_quantity:=quantities->((o->>'sourceOrdinal')::integer);
  scale:=CASE energy_unit WHEN 'KWH' THEN 1 WHEN 'MWH' THEN 1000 WHEN 'GWH' THEN 1000000 END;
  IF source_quantity IS NULL OR source_quantity#>>'{elements,1,0}' IS DISTINCT FROM '136'
   OR scale IS NULL OR trim_scale(gridex_utilts_binding.canonical_decimal_v2(source_quantity#>>'{elements,1,1}',decimal_mark)::numeric*scale)::text IS DISTINCT FROM o->>'quantity'
   THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: validate_legacy_contract_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_legacy_contract_v1(c jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p_contract ALIAS FOR $1; v_billing jsonb:=p_contract->'billing'; v_value jsonb; v_key text; v_observation jsonb;
BEGIN
 IF NOT coalesce(gridex_utilts_binding.validate_contract_base_v1(p_contract),false) THEN RETURN false; END IF;
 IF jsonb_typeof(v_billing->'requestScope') NOT IN ('string','null')
 OR (v_billing->>'capability'='write' AND v_billing->>'requestScope' IS DISTINCT FROM 'billing_underlay') THEN RETURN false; END IF;
 FOREACH v_key IN ARRAY ARRAY['month','year'] LOOP
  v_value:=v_billing->v_key;
  IF v_value<>'null'::jsonb AND (jsonb_typeof(v_value)<>'number' OR (v_value#>>'{}')::numeric<>trunc((v_value#>>'{}')::numeric)) THEN RETURN false; END IF;
 END LOOP;
 IF (v_billing->>'month')::numeric NOT BETWEEN 1 AND 12 OR (v_billing->>'year')::numeric NOT BETWEEN 1900 AND 9999 THEN RETURN false; END IF;
 -- TypeScript rejects empty/padded strings in all nullable text fields too.
 FOR v_value IN SELECT value FROM jsonb_each(p_contract) UNION ALL SELECT value FROM jsonb_each(p_contract->'interpretation')
  UNION ALL SELECT value FROM jsonb_each(p_contract->'metering') UNION ALL SELECT value FROM jsonb_each(v_billing) LOOP
  IF jsonb_typeof(v_value)='string' AND (nullif(btrim(v_value#>>'{}'),'') IS NULL OR btrim(v_value#>>'{}')<>v_value#>>'{}') THEN RETURN false; END IF;
 END LOOP;
 FOR v_observation IN SELECT value FROM jsonb_array_elements(p_contract->'observations') LOOP
  PERFORM (v_observation->>'quantity')::double precision;
  FOR v_value IN SELECT value FROM jsonb_each(v_observation) LOOP
   IF jsonb_typeof(v_value)='string' AND (nullif(btrim(v_value#>>'{}'),'') IS NULL OR btrim(v_value#>>'{}')<>v_value#>>'{}') THEN RETURN false; END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

--
-- Name: validate_rejected_contract_v3(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_rejected_contract_v3(c jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed text;maximum integer;projected jsonb;
BEGIN
 observed:=c->>'transactionId';maximum:=(gridex_ediel_ack_guide.utilts_reference_constraints_v1()->>'originalAcwMax')::integer;
 IF c->'version' IS DISTINCT FROM '3'::jsonb OR c->>'projectionVersion' IS DISTINCT FROM 'utilts-rejected-diagnostic-v3'
  OR jsonb_typeof(c->'transactionId') IS DISTINCT FROM 'string' OR observed IS NULL OR char_length(observed) NOT BETWEEN 1 AND maximum
  OR coalesce(gridex_utilts_binding.valid_transaction_reference_v2(observed),false)
  OR EXISTS(SELECT FROM generate_series(1,char_length(observed)) n WHERE ascii(substr(observed,n,1))<32 OR ascii(substr(observed,n,1)) BETWEEN 127 AND 159 OR ascii(substr(observed,n,1))>255)
  OR c->'observations' IS DISTINCT FROM '[]'::jsonb OR c->'billingContributionOrdinals' IS DISTINCT FROM '[]'::jsonb
  OR c#>>'{metering,capability}' IS DISTINCT FROM 'skip' OR c#>>'{billing,capability}' IS DISTINCT FROM 'skip'
  OR c#>>'{interpretation,timestampPolicy}' IS DISTINCT FROM 'no-consumption-v1' THEN RETURN false; END IF;
 -- Shape-only projection into the strict frozen zero-effect validator. The
 -- replacement is never returned/stored/hashed and never denotes sourceID.
 projected:=c||jsonb_build_object('version',1,'projectionVersion','utilts-consumption-v1','transactionId','rejected-observation');
 RETURN gridex_utilts_binding.validate_legacy_contract_v1(projected);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

--
-- Name: wire_tokens_v1(text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.wire_tokens_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
 component_sep text:=':'; data_sep text:='+'; release_char text:='?'; terminator text:='''';
 decimal_mark text:='.'; reserved text:=' '; body text; ch text; chars text[];
 released boolean:=false; current_component text:=''; current_element jsonb:='[]'; elements jsonb:='[]';
 result jsonb:='[]'; tag text; segment_count integer:=0; line_count integer:=0;
 component_size integer:=0; component_count integer:=0; element_count integer:=0;
BEGIN
 IF p_raw IS NULL OR octet_length(p_raw)>8388608 THEN RETURN NULL; END IF;
 -- Read advice before CRLF/LF normalization. No inferred repetition grammar.
 body:=p_raw;
 IF upper(left(body,3))='UNA' THEN
  IF left(body,3)<>'UNA' OR char_length(body)<9 THEN RETURN NULL; END IF;
  component_sep:=substr(body,4,1);data_sep:=substr(body,5,1);decimal_mark:=substr(body,6,1);
  release_char:=substr(body,7,1);reserved:=substr(body,8,1);terminator:=substr(body,9,1);body:=substr(body,10);
 END IF;
 IF reserved<>' ' OR decimal_mark NOT IN ('.',',')
 OR decimal_mark=ANY(ARRAY[component_sep,data_sep,release_char,terminator])
 OR (SELECT count(DISTINCT value) FROM unnest(ARRAY[component_sep,data_sep,release_char,terminator]) value)<>4
 OR EXISTS(SELECT FROM unnest(ARRAY[component_sep,data_sep,release_char,terminator]) value
   WHERE ascii(value)<33 OR ascii(value)>126 OR value ~ '[A-Za-z0-9]') THEN RETURN NULL; END IF;
 body:=replace(replace(body,E'\r\n',''),E'\n','');
 IF strpos(body,E'\r')>0 OR right(body,1)<>terminator THEN RETURN NULL; END IF;
 -- NULL delimiter enumerates code points, NOT segments/elements. Exactly one
 -- state machine consumes these; decoded literals are never split again.
 chars:=string_to_array(body,NULL);
 FOREACH ch IN ARRAY chars LOOP
  IF released THEN
   current_component:=current_component||ch;component_size:=component_size+1;released:=false;
  ELSIF ch=release_char THEN released:=true;
  ELSIF ch=component_sep OR ch=data_sep OR ch=terminator THEN
   -- Match canonical leading segment trim. Other whitespace forms are held
   -- explicitly; in particular a released trailing space must not be trimmed.
   IF elements='[]'::jsonb AND current_element='[]'::jsonb THEN current_component:=ltrim(current_component,E' \t'); END IF;
   IF ch=terminator AND current_component<>rtrim(current_component,E' \t') THEN RETURN NULL; END IF;
   IF ch=terminator AND elements='[]'::jsonb AND current_element='[]'::jsonb AND current_component='' THEN CONTINUE; END IF;
   current_element:=current_element||jsonb_build_array(current_component);component_count:=component_count+1;
   current_component:='';component_size:=0;
   IF component_count>128 THEN RETURN NULL; END IF;
   IF ch<>component_sep THEN
    elements:=elements||jsonb_build_array(current_element);element_count:=element_count+1;
    current_element:='[]';component_count:=0;
    IF element_count>128 THEN RETURN NULL; END IF;
   END IF;
   IF ch=terminator THEN
    tag:=elements#>>'{0,0}';
    IF jsonb_array_length(elements->0)<>1 OR tag !~ '^[A-Z]{3}$' OR tag='UNA' THEN RETURN NULL; END IF;
    IF tag='LIN' THEN line_count:=line_count+1; END IF;
    IF segment_count>=100000 OR line_count>4096 THEN RETURN NULL; END IF;
    result:=result||jsonb_build_array(jsonb_build_object('index',segment_count,'tag',tag,'elements',elements));
    segment_count:=segment_count+1;elements:='[]';element_count:=0;
   END IF;
  ELSE current_component:=current_component||ch;component_size:=component_size+1;
  END IF;
  IF component_size>4096 THEN RETURN NULL; END IF;
 END LOOP;
 IF released OR current_component<>'' OR elements<>'[]'::jsonb OR current_element<>'[]'::jsonb THEN RETURN NULL; END IF;
 RETURN result;
END $_$;

--
-- Name: capture_insert_v1(); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.capture_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;wire jsonb;tokens jsonb;token jsonb;legal jsonb;sender jsonb;first_detail integer;v gridex_utilts_issuer.issuer_versions%rowtype;mandate gridex_utilts_issuer.transport_mandate_versions%rowtype;
 matches integer;epoch bigint;txs jsonb:='[]';collisions jsonb:='[]';ref text;duplicate_message boolean:=false;ordinal integer:=0;reason text:='ediel_utilts_foreign_issuer_basis_unavailable';
BEGIN
 IF NEW.direction IS DISTINCT FROM 'inbound' OR NEW.message_standard IS DISTINCT FROM 'edifact' OR NEW.message_family IS DISTINCT FROM 'UTILTS' THEN RETURN NEW;END IF;
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=NEW.id AND company_id=NEW.company_id AND environment=NEW.environment AND origin='database_insert';
 IF src.source_message_id IS NULL OR src.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' OR src.raw_payload IS DISTINCT FROM NEW.raw_payload
  OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') THEN RETURN NEW;END IF;
 wire:=gridex_ack_authority.wire_v1(NEW.raw_payload);tokens:=gridex_utilts_binding.wire_tokens_v1(NEW.raw_payload);
 IF wire IS NOT NULL AND tokens IS NOT NULL AND wire->>'family'='UTILTS' AND wire->>'code' IS DISTINCT FROM 'ERR' THEN
  SELECT min((x->>'index')::integer) INTO first_detail FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='IDE';
  SELECT count(*) INTO matches FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS' AND (first_detail IS NULL OR (x->>'index')::integer<first_detail);
  IF matches=1 THEN SELECT x#>'{elements,2}' INTO legal FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS' AND (first_detail IS NULL OR (x->>'index')::integer<first_detail);END IF;
  sender:=wire->'sender';ref:=wire->>'document';
  FOR token IN SELECT value FROM jsonb_array_elements(tokens) x(value) WHERE value->>'tag'='IDE' ORDER BY (value->>'index')::integer LOOP
   txs:=txs||jsonb_build_array(jsonb_build_object('transactionIndex',ordinal,'transactionId',token#>>'{elements,2,0}'));ordinal:=ordinal+1;
  END LOOP;
  IF legal IS NOT NULL THEN PERFORM gridex_utilts_issuer.lock_legal_identity_v1(NEW.environment,legal);END IF;
  SELECT count(*) INTO matches FROM gridex_utilts_issuer.issuer_versions i JOIN gridex_utilts_issuer.namespaces n ON n.id=i.namespace_id JOIN gridex_utilts_issuer.transport_mandate_versions m ON m.issuer_version_id=i.id
   WHERE n.environment=NEW.environment AND i.legal_identity=legal AND m.transport_sender=sender
    AND i.approved_at<=src.captured_at AND m.approved_at<=src.captured_at AND i.valid_from<=src.captured_at AND (i.valid_until IS NULL OR src.captured_at<i.valid_until)
    AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
    AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=n.id AND (r.issuer_version_id=i.id OR r.mandate_version_id=m.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
  IF matches=1 THEN
   SELECT i.* INTO v FROM gridex_utilts_issuer.issuer_versions i JOIN gridex_utilts_issuer.namespaces n ON n.id=i.namespace_id JOIN gridex_utilts_issuer.transport_mandate_versions m ON m.issuer_version_id=i.id
    WHERE n.environment=NEW.environment AND i.legal_identity=legal AND m.transport_sender=sender
     AND i.approved_at<=src.captured_at AND m.approved_at<=src.captured_at AND i.valid_from<=src.captured_at AND (i.valid_until IS NULL OR src.captured_at<i.valid_until)
     AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
     AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=n.id AND (r.issuer_version_id=i.id OR r.mandate_version_id=m.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
   SELECT * INTO mandate FROM gridex_utilts_issuer.transport_mandate_versions m WHERE m.issuer_version_id=v.id AND m.transport_sender=sender AND m.approved_at<=src.captured_at AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
    AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.mandate_version_id=m.id AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
   PERFORM gridex_utilts_issuer.lock_namespace_v1(v.namespace_id);
   -- Fence newly committed revocation/version observations after acquiring the
   -- same namespace lock as approval/revocation and first-effect consumers.
   IF EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=v.namespace_id AND (r.issuer_version_id=v.id OR r.mandate_version_id=mandate.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at) THEN v.id:=NULL;mandate.id:=NULL;v.namespace_id:=NULL;
   ELSE
    SELECT coalesce(max(a.namespace_epoch),0)+1 INTO epoch FROM gridex_utilts_issuer.source_admissions a WHERE a.namespace_id=v.namespace_id;
    duplicate_message:=ref IS NOT NULL AND EXISTS(SELECT FROM gridex_utilts_issuer.observed_identifiers o WHERE o.namespace_id=v.namespace_id AND o.field_number='203' AND o.physical_reference=ref);
    SELECT coalesce(jsonb_agg(own ORDER BY (own->>'transactionIndex')::integer),'[]') INTO collisions FROM jsonb_array_elements(txs) own WHERE EXISTS(SELECT FROM gridex_utilts_issuer.observed_identifiers o WHERE o.namespace_id=v.namespace_id AND o.field_number='505' AND o.physical_reference=own->>'transactionId');
    reason:='ediel_utilts_identity_history_coverage_unavailable';
   END IF;
  ELSIF matches>1 THEN reason:='ediel_utilts_foreign_issuer_binding_ambiguous';END IF;
 END IF;
 INSERT INTO gridex_utilts_issuer.source_admissions(source_message_id,company_id,environment,source_payload_hash,observed_at,namespace_id,issuer_version_id,mandate_version_id,namespace_epoch,message_reference,transactions,message_reference_collision,transaction_reference_collisions,hold_reason)
  VALUES(NEW.id,NEW.company_id,NEW.environment,src.payload_hash,src.captured_at,v.namespace_id,v.id,mandate.id,epoch,ref,txs,duplicate_message,collisions,reason);
 IF v.id IS NOT NULL THEN
  IF nullif(ref,'') IS NOT NULL THEN INSERT INTO gridex_utilts_issuer.observed_identifiers VALUES(NEW.id,v.namespace_id,'203',ref,-1);END IF;
  INSERT INTO gridex_utilts_issuer.observed_identifiers SELECT NEW.id,v.namespace_id,'505',own->>'transactionId',(own->>'transactionIndex')::integer FROM jsonb_array_elements(txs) own WHERE nullif(own->>'transactionId','') IS NOT NULL;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: fence_ground_insert_v1(); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.fence_ground_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE ns uuid;issuer gridex_utilts_issuer.issuer_versions%rowtype;env text;identity jsonb;admission gridex_utilts_issuer.source_admissions%rowtype;item jsonb;
BEGIN
 IF TG_TABLE_NAME='transport_mandate_versions' THEN SELECT * INTO issuer FROM gridex_utilts_issuer.issuer_versions WHERE id=NEW.issuer_version_id;ns:=issuer.namespace_id;identity:=issuer.legal_identity;
 ELSE ns:=NEW.namespace_id;IF TG_TABLE_NAME='issuer_versions' THEN identity:=NEW.legal_identity;END IF;END IF;
 IF identity IS NOT NULL THEN SELECT environment INTO env FROM gridex_utilts_issuer.namespaces WHERE id=ns;PERFORM gridex_utilts_issuer.lock_legal_identity_v1(env,identity);END IF;
 PERFORM gridex_utilts_issuer.lock_namespace_v1(ns);
 IF TG_TABLE_NAME='revocations' THEN
  IF NOT EXISTS(SELECT FROM gridex_utilts_issuer.issuer_versions v WHERE v.namespace_id=ns AND (v.id=NEW.issuer_version_id OR EXISTS(SELECT FROM gridex_utilts_issuer.transport_mandate_versions m WHERE m.id=NEW.mandate_version_id AND m.issuer_version_id=v.id))) THEN RAISE EXCEPTION 'utilts_issuer_revocation_scope_invalid' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_TABLE_NAME='source_absence_grounds' THEN
  SELECT * INTO admission FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=NEW.source_message_id;
  IF admission.namespace_id IS NULL OR ROW(NEW.namespace_id,NEW.issuer_version_id,NEW.mandate_version_id,NEW.namespace_epoch,NEW.source_payload_hash)
   IS DISTINCT FROM ROW(admission.namespace_id,admission.issuer_version_id,admission.mandate_version_id,admission.namespace_epoch,admission.source_payload_hash) THEN RAISE EXCEPTION 'utilts_issuer_absence_scope_invalid' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(NEW.normalized_issued_identifiers) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['field','reference','originalIssuanceReference','originalSourceSha256','originEvidenceSha256']<>'{}'::jsonb
    OR jsonb_typeof(item->'field') IS DISTINCT FROM 'string' OR coalesce(item->>'field','') NOT IN('203','505') OR jsonb_typeof(item->'reference') IS DISTINCT FROM 'string' OR length(item->>'reference')=0
    OR jsonb_typeof(item->'originalIssuanceReference') IS DISTINCT FROM 'string' OR length(item->>'originalIssuanceReference')=0
    OR jsonb_typeof(item->'originalSourceSha256') IS DISTINCT FROM 'string' OR coalesce(item->>'originalSourceSha256','') !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(item->'originEvidenceSha256') IS DISTINCT FROM 'string' OR coalesce(item->>'originEvidenceSha256','') !~ '^[a-f0-9]{64}$'
   THEN RAISE EXCEPTION 'utilts_issuer_history_projection_invalid' USING ERRCODE='23514';END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $_$;

--
-- Name: lock_legal_identity_v1(text, jsonb); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.lock_legal_identity_v1(p_environment text, p_identity jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF p_environment IS NULL OR p_identity IS NULL THEN RAISE EXCEPTION 'utilts_issuer_identity_required' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel-utilts-legal-issuer:'||p_environment||':'||p_identity::text,0));
END $$;

--
-- Name: lock_namespace_v1(uuid); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.lock_namespace_v1(p_namespace uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF p_namespace IS NULL THEN RAISE EXCEPTION 'utilts_issuer_namespace_required' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel-utilts-issuer:'||p_namespace::text,0));
END $$;

--
-- Name: read_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.read_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a gridex_utilts_issuer.source_admissions%rowtype;grounds gridex_utilts_issuer.source_absence_grounds%rowtype;known boolean;collisions jsonb;reason text;qualified boolean:=false;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND direction='inbound' AND message_family='UTILTS' AND message_standard='edifact';
 IF m.id IS NULL THEN RAISE EXCEPTION 'utilts_issuer_source_scope_required' USING ERRCODE='23514';END IF;
 SELECT * INTO a FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=m.id AND company_id=p_company AND environment=m.environment AND source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 reason:=coalesce(a.hold_reason,'ediel_utilts_historical_issuer_basis_unavailable');known:=coalesce(a.message_reference_collision,false);collisions:=coalesce(a.transaction_reference_collisions,'[]');
 IF a.namespace_id IS NOT NULL THEN
  SELECT * INTO grounds FROM gridex_utilts_issuer.source_absence_grounds WHERE source_message_id=a.source_message_id AND source_payload_hash=a.source_payload_hash AND namespace_id=a.namespace_id AND issuer_version_id=a.issuer_version_id AND mandate_version_id=a.mandate_version_id AND namespace_epoch=a.namespace_epoch AND approved_at<=statement_timestamp();
  IF EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=a.namespace_id AND (r.issuer_version_id=a.issuer_version_id OR r.mandate_version_id=a.mandate_version_id) AND r.approved_at<=statement_timestamp() AND r.effective_at<=statement_timestamp()) THEN
   -- A revocation holds new positive effects; it cannot rewrite an
   -- authenticated collision observed under the original issuer admission.
   reason:='ediel_utilts_foreign_issuer_basis_revoked';
  ELSE
   IF grounds.source_message_id IS NOT NULL THEN
    known:=known OR EXISTS(SELECT FROM jsonb_array_elements(grounds.normalized_issued_identifiers) x WHERE x->>'field'='203' AND x->>'reference'=a.message_reference);
    SELECT coalesce(jsonb_agg(own ORDER BY (own->>'transactionIndex')::integer),'[]') INTO collisions FROM jsonb_array_elements(a.transactions) own WHERE a.transaction_reference_collisions @>jsonb_build_array(own) OR EXISTS(SELECT FROM jsonb_array_elements(grounds.normalized_issued_identifiers) x WHERE x->>'field'='505' AND x->>'reference'=own->>'transactionId');
    qualified:=true;reason:=NULL;
   END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('version',1,'companyId',p_company,'environment',m.environment,'sourceMessageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),
  'status',CASE WHEN qualified THEN 'qualified' ELSE 'held' END,'authorityVersionId',a.issuer_version_id,'namespaceEpoch',a.namespace_epoch::text,
  'messageReferenceCollision',known,'transactionReferenceCollisions',collisions,'holdReason',reason);
END $$;

--
-- Name: require_first_effect_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.require_first_effect_v1(p_company uuid, p_source uuid, p_transaction text, p_disposition text, p_issue_codes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_utilts_issuer.source_admissions%rowtype;facts jsonb;
BEGIN
 SELECT * INTO a FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=p_source AND company_id=p_company;
 IF a.namespace_id IS NOT NULL THEN PERFORM gridex_utilts_issuer.lock_namespace_v1(a.namespace_id);END IF;
 facts:=gridex_utilts_issuer.read_v1(p_company,p_source);
 IF p_disposition='accepted' AND (facts->>'status' IS DISTINCT FROM 'qualified' OR facts->'messageReferenceCollision' IS DISTINCT FROM 'false'::jsonb
  OR EXISTS(SELECT FROM jsonb_array_elements(facts->'transactionReferenceCollisions') x WHERE x->>'transactionId'=p_transaction)) THEN RAISE EXCEPTION 'utilts_issuer_identity_first_effect_held' USING ERRCODE='P0U01';END IF;
 IF p_issue_codes ? 'UTILTS_ISSUER_MESSAGE_REFERENCE_DUPLICATE' AND facts->'messageReferenceCollision' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'utilts_issuer_duplicate_source_proof_required' USING ERRCODE='P0U01';END IF;
 IF p_issue_codes ? 'UTILTS_ISSUER_TRANSACTION_REFERENCE_DUPLICATE' AND NOT EXISTS(SELECT FROM jsonb_array_elements(facts->'transactionReferenceCollisions') x WHERE x->>'transactionId'=p_transaction) THEN RAISE EXCEPTION 'utilts_issuer_duplicate_source_proof_required' USING ERRCODE='P0U01';END IF;
END $$;

--
-- Name: spot_price_monthly_summaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_monthly_summaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'elprisetjustnu'::text NOT NULL,
    price_area text NOT NULL,
    billing_month text NOT NULL,
    average_sek_per_kwh numeric NOT NULL,
    min_sek_per_kwh numeric NOT NULL,
    max_sek_per_kwh numeric NOT NULL,
    interval_count integer DEFAULT 0 NOT NULL,
    expected_interval_count integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'incomplete'::text NOT NULL,
    locked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period_start timestamp with time zone,
    period_end timestamp with time zone,
    covered_duration_minutes bigint,
    expected_duration_minutes bigint,
    quality_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    provider_fetched_at timestamp with time zone,
    verified_at timestamp with time zone,
    locked_by uuid,
    lock_reason text,
    source_checksum text,
    CONSTRAINT spot_price_monthly_summaries_billing_month_check CHECK ((billing_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT spot_price_monthly_summaries_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_monthly_summaries_status_check CHECK ((status = ANY (ARRAY['incomplete'::text, 'complete'::text, 'verified'::text, 'locked'::text]))),
    CONSTRAINT spot_price_monthly_verified_coverage_check CHECK (((status <> ALL (ARRAY['verified'::text, 'locked'::text])) OR ((period_start IS NOT NULL) AND (period_end IS NOT NULL) AND (period_end > period_start) AND (average_sek_per_kwh IS NOT NULL) AND (min_sek_per_kwh IS NOT NULL) AND (max_sek_per_kwh IS NOT NULL) AND (covered_duration_minutes = expected_duration_minutes) AND (
CASE
    WHEN (jsonb_typeof(quality_issues) = 'array'::text) THEN jsonb_array_length(quality_issues)
    ELSE 1
END = 0) AND (verified_at IS NOT NULL) AND (NULLIF(btrim(source_checksum), ''::text) IS NOT NULL) AND ((status <> 'locked'::text) OR ((locked_at IS NOT NULL) AND (locked_at >= verified_at))))))
);

--
-- Name: activate_customer_supply_v1(uuid, uuid, uuid, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_customer_supply_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(supplier_switch_request_id uuid, supply_period_id uuid, contract_id uuid, customer_application_id uuid, workflow_id uuid, domain_event_id uuid, notification_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;prior gridex_received_sources.normal_supply_activations%rowtype;
 p public.customer_supply_periods%rowtype;s public.supplier_switch_requests%rowtype;m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;c public.customer_contracts%rowtype;result jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'normal_supply_activation_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE company_id=p_company_id AND switch_id=p_supplier_switch_request_id AND source_message_id=p_source_message_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'normal_supply_activation_immutable_confirmation_required';END IF;
 IF gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,proof.source_message_id) IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_supply_activation_recorded_profile_required';END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=p_company_id AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND proof.switch_id=ANY(tr.qualified_switch_ids)) THEN RAISE EXCEPTION 'normal_supply_activation_source_changed';END IF;
 SELECT * INTO prior FROM gridex_received_sources.normal_supply_activations WHERE period_id=proof.period_id;
 IF FOUND THEN
  -- Established own activation is returned before today's profile, contract,
  -- deadline or rule decisions. It cannot authorize a second market effect.
  RETURN QUERY SELECT (prior.result->>'supplier_switch_request_id')::uuid,(prior.result->>'supply_period_id')::uuid,(prior.result->>'contract_id')::uuid,(prior.result->>'customer_application_id')::uuid,(prior.result->>'workflow_id')::uuid,(prior.result->>'domain_event_id')::uuid,(prior.result->>'notification_job_id')::uuid;RETURN;
 END IF;
 PERFORM public.ediel_require_contract_records_available_v1(p_company_id,proof.contract_id);PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,proof.source_message_id);PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,proof.original_message_id);PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);
 IF proof.market_start_at>now() THEN RAISE EXCEPTION 'normal_supply_activation_not_due';END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=proof.period_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 PERFORM profile.id FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment ORDER BY profile.id FOR SHARE;
 PERFORM role.id FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment ORDER BY role.id FOR SHARE;
 PERFORM identifier.id FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment ORDER BY identifier.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment AND profile.market='electricity' AND profile.is_enabled AND profile.valid_from<=now() AND (profile.valid_to IS NULL OR now()<profile.valid_to))
  OR NOT EXISTS(SELECT FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment AND role.actor_id::text=proof.legal_context->>'legalActorId' AND role.role_code='electricity_supplier' AND role.valid_from<=now() AND (role.valid_to IS NULL OR now()<role.valid_to))
  OR (SELECT count(DISTINCT (identifier.actor_id,identifier.identifier_value)) FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.identifier_type='EdielId' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to))<>1
  OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.actor_id::text=proof.legal_context->>'legalActorId' AND identifier.identifier_type='EdielId' AND identifier.identifier_value=proof.legal_context->>'legalEdielId' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to)) THEN RAISE EXCEPTION 'normal_supply_activation_current_legal_actor_required';END IF;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR p.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR p.market_state_version IS DISTINCT FROM (proof.confirmed_period->>'market_state_version')::bigint OR p.market_start_at IS DISTINCT FROM proof.market_start_at
  OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid OR p.market_end_at IS NOT NULL OR p.metadata IS DISTINCT FROM proof.confirmed_period->'metadata'
  OR s.status IS DISTINCT FROM 'accepted' OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id OR s.lifecycle_blocked OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id
  OR s.contract_id IS DISTINCT FROM (proof.confirmed_switch->>'contract_id')::uuid OR s.customer_contract_id IS DISTINCT FROM (proof.confirmed_switch->>'customer_contract_id')::uuid OR s.site_id IS DISTINCT FROM (proof.confirmed_switch->>'site_id')::uuid OR s.customer_site_id IS DISTINCT FROM (proof.confirmed_switch->>'customer_site_id')::uuid
  OR p.contract_id IS DISTINCT FROM (proof.confirmed_period->>'contract_id')::uuid OR p.customer_contract_id IS DISTINCT FROM (proof.confirmed_period->>'customer_contract_id')::uuid
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR (p_actual_start_date IS NOT NULL AND p_actual_start_date IS DISTINCT FROM p.start_date) THEN RAISE EXCEPTION 'normal_supply_activation_current_confirmation_changed';END IF;
 SELECT to_jsonb(effect) INTO result FROM gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id,proof.switch_id,proof.source_message_id,p.start_date,p_actor_user_id,'ediel-normal-activation:'||proof.period_id) effect;
 IF result->>'supply_period_id' IS DISTINCT FROM proof.period_id::text THEN RAISE EXCEPTION 'normal_supply_activation_period_replaced';END IF;
 INSERT INTO gridex_received_sources.normal_supply_activations(period_id,company_id,source_message_id,actor_user_id,previous_period,resulting_period,result)
 SELECT proof.period_id,p_company_id,proof.source_message_id,p_actor_user_id,to_jsonb(p),to_jsonb(current),result FROM public.customer_supply_periods current WHERE current.id=proof.period_id AND current.company_id=p_company_id;
 RETURN QUERY SELECT (result->>'supplier_switch_request_id')::uuid,(result->>'supply_period_id')::uuid,(result->>'contract_id')::uuid,(result->>'customer_application_id')::uuid,(result->>'workflow_id')::uuid,(result->>'domain_event_id')::uuid,(result->>'notification_job_id')::uuid;
END $$;

--
-- Name: agent_top_accounts_for_company(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_top_accounts_for_company(p_company_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(account_number text, abs_amount numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_entries regclass := to_regclass('public.journal_entries');
  v_lines regclass := to_regclass('public.journal_entry_lines');
begin
  if v_entries is null
     or v_lines is null
     or not exists (
       select 1
       from pg_attribute
       where attrelid = v_entries
         and attname = 'company_id'
         and not attisdropped
     ) then
    return;
  end if;

  return query execute $sql$
    select
      line.account_number::text,
      sum(abs(
        coalesce(line.debit_amount, 0)
        - coalesce(line.credit_amount, 0)
      ))::numeric
    from public.journal_entry_lines line
    join public.journal_entries entry on entry.id = line.journal_entry_id
    where entry.company_id = $1
      and entry.status = 'posted'
    group by line.account_number
    order by 2 desc, line.account_number
    limit least(greatest(coalesce($2, 20), 1), 100)
  $sql$ using p_company_id, p_limit;
end
$_$;

--
-- Name: anonymize_user_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_user_account(target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $_$
begin
  if auth.uid() is distinct from target_user_id then
    raise exception using
      errcode = '42501',
      message = 'Can only anonymize your own account';
  end if;

  if exists (
    select 1
    from public.company_memberships membership
    join public.companies company on company.id = membership.company_id
    where membership.user_id = target_user_id
      and coalesce(membership.status, 'active') = 'active'
      and coalesce(
        nullif(lower(membership.membership_role), ''),
        nullif(lower(membership.role), ''),
        nullif(lower(membership.role_key), '')
      ) = 'owner'
      and company.archived_at is null
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'Active companies must be transferred or archived first';
  end if;

  if to_regclass('public.user_preferences') is not null then
    execute 'delete from public.user_preferences where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_permission_overrides') is not null then
    execute 'delete from public.user_permission_overrides where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_roles') is not null then
    execute 'delete from public.user_roles where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.company_memberships') is not null then
    execute 'delete from public.company_memberships where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.agency_members') is not null then
    execute 'delete from public.agency_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.team_members') is not null then
    execute 'delete from public.team_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.bankid_enrichment') is not null then
    execute 'delete from public.bankid_enrichment where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.extension_data') is not null then
    execute
      'delete from public.extension_data where user_id = $1 and key = ''bankid_enrichment'''
      using target_user_id;
  end if;

  if to_regclass('public.company_invitations') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public'
         and table_name = 'company_invitations'
         and column_name = 'invited_user_id'
     ) then
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
        and table_name = 'company_invitations'
        and column_name = 'invited_user_id'
        and is_nullable = 'YES'
    ) then
      execute 'update public.company_invitations set invited_user_id = null where invited_user_id = $1'
        using target_user_id;
    else
      execute 'delete from public.company_invitations where invited_user_id = $1'
        using target_user_id;
    end if;
  end if;

  -- Revoke existing authenticated sessions without deleting the auth identity.
  -- The identity itself remains so the product can retain its established
  -- account-closure semantics while authorization state is removed atomically.
  if to_regclass('auth.sessions') is not null then
    execute 'delete from auth.sessions where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('auth.refresh_tokens') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'auth'
         and table_name = 'refresh_tokens'
         and column_name = 'user_id'
     ) then
    execute 'delete from auth.refresh_tokens where user_id::text = $1::text'
      using target_user_id;
  end if;

  update public.user_profiles
  set email = null,
      full_name = null,
      phone = null,
      user_status = 'disabled',
      active_company_id = null,
      updated_at = now()
  where id = target_user_id;
end
$_$;

--
-- Name: authenticate_integration_request_v1(text, text, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  -- Existing callers pass the requested route's exact scopes. Staff opt-in is
  -- explicit: neither legacy wildcard nor website/customer permission groups
  -- may grant this new family. Unknown staff paths fail closed.
  with staff_policy as (
    select
      p_route ~ '^/api/v1/(staff|staff-onboarding)(/|$)' as is_staff_route,
      case
        when p_route='/api/v1/staff-onboarding/invitations/accept' then array['staff_users.write']::text[]
        when p_route='/api/v1/staff-onboarding/identity/resolve' then array['staff_users.read']::text[]
        when p_route='/api/v1/staff/users' then array['staff_users.read','staff_users.write']::text[]
        when p_route='/api/v1/staff/roles' then array['staff_users.read']::text[]
        when p_route ~ '^/api/v1/staff/users/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(/(disable|enable))?$' then array['staff_users.write']::text[]
        when p_route='/api/v1/staff/customers' or p_route ~ '^/api/v1/staff/customers/customer_[A-Za-z0-9_-]{32}$' then array['staff_customers.read']::text[]
        when p_route ~ '^/api/v1/staff/customers/customer_[A-Za-z0-9_-]{32}/(contact|identity-change)$' then array['staff_customers.write']::text[]
        when p_route='/api/v1/staff/cases' then array['staff_cases.read','staff_cases.write']::text[]
        when p_route ~ '^/api/v1/staff/cases/support_case_[A-Za-z0-9_-]{32}$' then array['staff_cases.read']::text[]
        when p_route ~ '^/api/v1/staff/cases/support_case_[A-Za-z0-9_-]{32}/events$' then array['staff_cases.read']::text[]
        when p_route ~ '^/api/v1/staff/cases/support_case_[A-Za-z0-9_-]{32}/(messages|notes|phone-interactions|status|assignee)$' then array['staff_cases.write']::text[]
        when p_route ~ '^/api/v1/staff/cases/support_case_[A-Za-z0-9_-]{32}/attachments$' then array['staff_cases.read','staff_cases.write']::text[]
        when p_route ~ '^/api/v1/staff/cases/support_case_[A-Za-z0-9_-]{32}/attachments/support_attachment_[A-Za-z0-9_-]{24}/file$' then array['staff_cases.read']::text[]
        else array[]::text[]
      end as allowed_scopes
  ), auth as (
    select *
    from public.authenticate_integration_request_v1_credential_core(
      p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
      p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
    )
  ), readiness as (
    select
      auth.*,
      staff_policy.is_staff_route,
      coalesce(
        cardinality(p_required_all)>0
        and cardinality(coalesce(p_required_any,array[]::text[]))=0
        and p_required_all <@ staff_policy.allowed_scopes
        and p_required_all <@ coalesce(auth.scopes,array[]::text[])
        and array_position(p_required_all,null) is null,
        false
      ) as staff_scopes_ready,
      exists (
        select 1 from public.companies company
        where company.id=auth.company_id and company.status='active'
          and company.is_active is true
      ) as staff_company_ready,
      exists (
        select 1
        from public.integration_api_clients client
        where client.id=auth.client_id
          and client.company_id=auth.company_id
          and client.launch_ready is true
          and jsonb_typeof(coalesce(client.launch_blockers,'[]'::jsonb))='array'
          and jsonb_array_length(coalesce(client.launch_blockers,'[]'::jsonb))=0
      ) as client_ready,
      exists (
        select 1
        from public.tenant_website_installation_receipts receipt
        where receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.profile_key='tenant_website'
          and receipt.state='completed'
          and receipt.completed_at is not null
          and nullif(receipt.receipt_sha256,'') is not null
          and (
            receipt.id::text = nullif(auth.metadata->>'provisioning_receipt_id','')
            or (
              nullif(auth.metadata->>'provisioning_receipt_id','') is null
            )
          )
      ) as receipt_ready,
      exists (
        select 1
        from public.company_capabilities capability
        where capability.company_id=auth.company_id
          and capability.capability_code='api_sales'
          and capability.enabled is true
          and capability.readiness_status='ready'
      ) as capability_ready,
      exists (
        select 1
        from public.tenant_website_installation_receipts receipt
        where p_route like 'provisioning-smoke:%'
          and receipt.id::text = nullif(auth.metadata->>'provisioning_receipt_id','')
          and receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.profile_key='tenant_website'
          and receipt.state in (
            'client_ready','credential_created','preflight_passed','feed_verified','failed'
          )
      ) as provisioning_smoke_ready
    from auth cross join staff_policy
  )
  select
    case
      when readiness.auth_outcome<>'allowed' then readiness.auth_outcome
      when readiness.is_staff_route and readiness.staff_scopes_ready and readiness.staff_company_ready then 'allowed'
      when readiness.is_staff_route then 'denied'
      when p_route like 'provisioning-smoke:%' and readiness.provisioning_smoke_ready then 'allowed'
      when p_route like 'provisioning-smoke:%' then 'denied'
      when readiness.client_ready and readiness.receipt_ready and readiness.capability_ready then 'allowed'
      else 'denied'
    end,
    case
      when readiness.auth_outcome<>'allowed' then readiness.error_code
      when readiness.is_staff_route and not readiness.staff_scopes_ready then 'api_scope_missing'
      when readiness.is_staff_route and not readiness.staff_company_ready then 'tenant_inactive'
      when readiness.is_staff_route then null
      when p_route like 'provisioning-smoke:%' and not readiness.provisioning_smoke_ready then 'provisioning_smoke_receipt_invalid'
      when p_route like 'provisioning-smoke:%' then null
      when not readiness.client_ready then 'api_client_not_launch_ready'
      when not readiness.receipt_ready then 'integration_receipt_not_verified'
      when not readiness.capability_ready then 'integration_capability_not_ready'
      else null
    end,
    readiness.tenant_status,
    readiness.client_id,
    readiness.company_id,
    readiness.client_name,
    readiness.client_status,
    readiness.key_prefix,
    readiness.scopes,
    readiness.allowed_ips,
    readiness.allowed_origins,
    readiness.metadata,
    readiness.rate_limit_per_minute,
    readiness.expires_at,
    readiness.request_count,
    readiness.route_limit,
    readiness.reset_at
  from readiness
$_$;

--
-- Name: FUNCTION authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[], p_required_any text[], p_client_ip text, p_origin text, p_rate_limit_cost integer, p_window_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[], p_required_any text[], p_client_ip text, p_origin text, p_rate_limit_cost integer, p_window_seconds integer) IS 'Atomic integration auth. Exact staff paths require explicit matching staff scopes and active company; staff traffic does not require Website sales provisioning. Existing Website/customer traffic retains current launch, linked completed receipt and api_sales readiness; bounded provisioning smoke requires the exact in-progress receipt.';

--
-- Name: authenticate_integration_request_v1_credential_core(text, text, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_integration_request_v1_credential_core(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select
    auth.auth_outcome,
    auth.error_code,
    auth.tenant_status,
    auth.client_id,
    auth.company_id,
    auth.client_name,
    auth.client_status,
    auth.key_prefix,
    auth.scopes,
    auth.allowed_ips,
    auth.allowed_origins,
    auth.metadata,
    auth.rate_limit_per_minute,
    auth.expires_at,
    auth.request_count,
    auth.route_limit,
    auth.reset_at
  from private.authenticate_integration_request_v1_secret_internal(
    p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
    p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
  ) auth
$$;

--
-- Name: authenticate_provisioning_smoke_request_v1(text, text, uuid, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_provisioning_smoke_request_v1(p_key_prefix text, p_secret_hash text, p_receipt_id uuid, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with auth as (
    select *
    from public.authenticate_integration_request_v1_credential_core(
      p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
      p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
    )
  ), checked as (
    select
      auth.*,
      p_route like 'provisioning-smoke:%'
      and exists (
        select 1 from public.tenant_website_installation_receipts receipt
        where receipt.id=p_receipt_id
          and receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.state in (
            'client_ready','credential_created','preflight_passed',
            'feed_verified','failed'
          )
      ) as smoke_allowed
    from auth
  )
  select
    case
      when checked.auth_outcome<>'allowed' then checked.auth_outcome
      when checked.smoke_allowed then 'allowed'
      else 'denied'
    end,
    case
      when checked.auth_outcome<>'allowed' then checked.error_code
      when not checked.smoke_allowed then 'provisioning_smoke_receipt_invalid'
      else null
    end,
    checked.tenant_status,
    checked.client_id,
    checked.company_id,
    checked.client_name,
    checked.client_status,
    checked.key_prefix,
    checked.scopes,
    checked.allowed_ips,
    checked.allowed_origins,
    checked.metadata,
    checked.rate_limit_per_minute,
    checked.expires_at,
    checked.request_count,
    checked.route_limit,
    checked.reset_at
  from checked
$$;

--
-- Name: backfill_companies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_companies() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
  v_before integer := 0;
  v_after integer := 0;
  v_company_id uuid;
  v_inserted integer := 0;
begin
  v_run_id := public.gridex_db1_start_backfill_run('db1_backfill_companies', 'companies');
  select count(*) into v_before from public.companies;
  v_company_id := public.gridex_db1_default_company_id();
  select count(*) into v_after from public.companies;
  v_inserted := greatest(v_after - v_before, 0);

  return public.gridex_db1_finish_backfill_run(
    v_run_id,
    'completed',
    jsonb_build_object('default_company_id', v_company_id, 'safe_default_only', true),
    v_after,
    v_inserted,
    0,
    0,
    0
  );
end;
$$;

--
-- Name: backfill_poa_scopes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_poa_scopes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
  v_company_id uuid;
  r record;
  v_seen integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_row_count integer := 0;
begin
  v_run_id := public.gridex_db1_start_backfill_run('db1_backfill_poa_scopes', 'powers_of_attorney');
  v_company_id := public.gridex_db1_default_company_id();

  if v_company_id is null then
    return public.gridex_db1_finish_backfill_run(v_run_id, 'skipped', jsonb_build_object('reason', 'ambiguous_company'), 0, 0, 0, 1, 0);
  end if;

  if to_regclass('public.powers_of_attorney') is null or to_regclass('public.power_of_attorney_scopes') is null then
    return public.gridex_db1_finish_backfill_run(v_run_id, 'skipped', jsonb_build_object('reason', 'poa_tables_missing'), 0, 0, 0, 1, 0);
  end if;

  update public.powers_of_attorney
  set company_id = v_company_id,
      updated_at = now()
  where company_id is null;
  get diagnostics v_row_count = row_count;
  v_updated := v_updated + v_row_count;

  for r in select * from public.powers_of_attorney loop
    v_seen := v_seen + 1;
    begin
      if exists(select 1 from public.power_of_attorney_scopes s where s.power_of_attorney_id = r.id) then
        v_skipped := v_skipped + 1;
        continue;
      end if;

      insert into public.power_of_attorney_scopes (
        company_id, power_of_attorney_id, customer_id, site_id, metering_point_id,
        scope_type, status, is_active, valid_from, valid_to, metadata, created_at, updated_at
      ) values (
        coalesce(r.company_id, v_company_id), r.id, r.customer_id, r.site_id, r.metering_point_id,
        coalesce(r.scope, 'supplier_switch'), 'active', true, r.valid_from, r.valid_to,
        jsonb_build_object('source_table', 'powers_of_attorney', 'source_id', r.id, 'backfill', 'db1_backfill_poa_scopes'),
        now(), now()
      );
      v_inserted := v_inserted + 1;
    exception when others then
      v_failed := v_failed + 1;
      insert into public.backfill_run_items(backfill_run_id, source_table, source_id, target_table, status, message, details)
      values (v_run_id, 'powers_of_attorney', coalesce(r.id::text, '<null>'), 'power_of_attorney_scopes', 'failed', SQLERRM, jsonb_build_object('sqlstate', SQLSTATE));
    end;
  end loop;

  return public.gridex_db1_finish_backfill_run(v_run_id, 'completed', jsonb_build_object('source_table', 'powers_of_attorney'), v_seen, v_inserted, v_updated, v_skipped, v_failed);
end;
$$;

--
-- Name: canonical_accept_tenant_invitation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_accept_tenant_invitation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_invitation_id uuid := nullif(p_command->>'invitation_id','')::uuid;
  v_idempotency_key text := nullif(btrim(p_command->>'idempotency_key'),'');
  v_invitation public.company_invitations%rowtype;
  v_company_status text;
  v_auth_email text;
  v_profile_active boolean;
  v_role_key text;
  v_membership_role text;
  v_role_id uuid;
  v_existing_user_role_id uuid;
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_actor_user_id is null or v_user_id is null or v_actor_user_id<>v_user_id
     or v_invitation_id is null or v_idempotency_key is null then
    raise exception using errcode='22023', message='verified_user_invitation_and_idempotency_required';
  end if;

  select * into v_invitation
  from public.company_invitations
  where id=v_invitation_id
  for update;
  if not found then
    raise exception using errcode='P0002', message='tenant_invitation_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('tenant-invitation:'||v_invitation.company_id::text||':'||v_invitation_id::text,0));
  v_hash := public.canonical_json_sha256(v_request);

  select * into v_existing
  from public.canonical_command_results
  where company_id=v_invitation.company_id
    and command_type='tenant.invitation.accept'
    and idempotency_key=v_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception using errcode='23505', message='IDEMPOTENCY_KEY_REUSE_MISMATCH';
    end if;
    return v_existing.result_payload;
  end if;

  if coalesce(v_invitation.status,'')='accepted'
     and v_invitation.invited_user_id=v_user_id then
    v_result:=jsonb_build_object(
      'changed',false,'already_accepted',true,'company_id',v_invitation.company_id,
      'user_id',v_user_id,'invitation_id',v_invitation_id
    );
    insert into public.canonical_command_results(
      company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
    ) values(
      v_invitation.company_id,'tenant.invitation.accept',v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
    );
    return v_result;
  end if;

  if coalesce(v_invitation.status,'')<>'pending' then
    raise exception using errcode='23514', message='tenant_invitation_not_pending';
  end if;
  if v_invitation.expires_at is not null and v_invitation.expires_at<=now() then
    raise exception using errcode='23514', message='tenant_invitation_expired';
  end if;
  if v_invitation.invited_user_id is not null and v_invitation.invited_user_id<>v_user_id then
    raise exception using errcode='42501', message='tenant_invitation_user_mismatch';
  end if;

  select coalesce(lower(u.email),public.gridex_staff_anchor_invitation_email_v1(v_invitation.id,v_invitation.company_id,u.id)),
         exists(select 1 from public.user_profiles up where up.id=u.id and up.user_status='active')
    into v_auth_email,v_profile_active
  from auth.users u
  where u.id=v_user_id and u.deleted_at is null
    and (u.banned_until is null or u.banned_until<=now());
  if v_auth_email is null or not coalesce(v_profile_active,false) then
    raise exception using errcode='42501', message='target_auth_user_missing_or_inactive';
  end if;
  if v_auth_email<>lower(coalesce(v_invitation.email,v_invitation.invited_email,'')) then
    raise exception using errcode='42501', message='tenant_invitation_email_mismatch';
  end if;

  select status into v_company_status
  from public.companies where id=v_invitation.company_id for update;
  if v_company_status not in ('onboarding','active') then
    raise exception using errcode='23514', message='tenant_state_blocks_invitation_acceptance';
  end if;

  v_role_key:=lower(coalesce(nullif(v_invitation.role_key,''),'customer_service_agent'));
  select m.membership_role into v_membership_role
  from public.canonical_tenant_access_role_mapping m
  where m.role_key=v_role_key and m.is_assignable;
  if v_membership_role is null then
    raise exception using errcode='22023', message='canonical_tenant_role_not_assignable';
  end if;
  if nullif(lower(v_invitation.membership_role),'') is not null
     and lower(v_invitation.membership_role)<>v_membership_role then
    raise exception using errcode='23514', message='invitation_membership_role_role_key_mismatch';
  end if;

  select r.id into v_role_id
  from public.roles r
  where lower(coalesce(r.key,r.name))=v_role_key
  order by r.created_at asc,r.id asc
  limit 1;
  if v_role_id is null then
    raise exception using errcode='22023', message='canonical_tenant_role_definition_missing';
  end if;

  insert into public.company_memberships(
    company_id,user_id,membership_role,role_key,status,is_active,invited_email,
    invited_by,invited_at,accepted_at,disabled_at,removed_at,status_reason,metadata
  ) values(
    v_invitation.company_id,v_user_id,v_membership_role,v_role_key,'active',true,v_auth_email,
    v_invitation.invited_by,coalesce(v_invitation.created_at,now()),now(),null,null,null,
    jsonb_build_object('canonical_invitation_id',v_invitation_id,'canonical_access_command',v_idempotency_key)
  ) on conflict(company_id,user_id) do update set
    membership_role=excluded.membership_role,role_key=excluded.role_key,status='active',is_active=true,
    invited_email=excluded.invited_email,accepted_at=coalesce(public.company_memberships.accepted_at,now()),
    disabled_at=null,removed_at=null,status_reason=null,
    metadata=coalesce(public.company_memberships.metadata,'{}'::jsonb)||excluded.metadata,
    updated_at=now();

  update public.user_roles
  set status='disabled',is_active=false,updated_at=now()
  where company_id=v_invitation.company_id and user_id=v_user_id and coalesce(is_active,true);

  select ur.id into v_existing_user_role_id
  from public.user_roles ur
  where ur.company_id=v_invitation.company_id and ur.user_id=v_user_id and ur.role_id=v_role_id
  order by ur.created_at asc,ur.id asc
  limit 1
  for update;
  if v_existing_user_role_id is null then
    insert into public.user_roles(user_id,company_id,role,role_id,status,is_active,created_at,updated_at)
    values(v_user_id,v_invitation.company_id,v_role_key,v_role_id,'active',true,now(),now());
  else
    update public.user_roles
    set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
    where id=v_existing_user_role_id;
  end if;

  update public.company_invitations
  set status='accepted',accepted_at=now(),invited_user_id=v_user_id,
      membership_role=v_membership_role,role_key=v_role_key,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'access_source','canonical_verified_auth_invitation','accepted_by_verified_user',true
      ),updated_at=now()
  where id=v_invitation_id;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,before_state,after_state
  ) values(
    v_invitation.company_id,'TENANT_INVITATION_ACCEPTED','tenant_user',v_user_id,v_actor_user_id,
    'Verified tenant invitation accepted',v_idempotency_key,
    jsonb_build_object('invitation_id',v_invitation_id,'status',v_invitation.status),
    jsonb_build_object('membership_role',v_membership_role,'role_key',v_role_key,'status','active')
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values(
    v_invitation.company_id,'TENANT_INVITATION_ACCEPTED','tenant_user',v_user_id,v_idempotency_key,
    jsonb_build_object('invitation_id',v_invitation_id,'membership_role',v_membership_role,'role_key',v_role_key),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(
    v_invitation.company_id,v_event_id,'tenant.invitation.accepted',v_idempotency_key,
    jsonb_build_object('company_id',v_invitation.company_id,'user_id',v_user_id,'invitation_id',v_invitation_id)
  );

  v_result:=jsonb_build_object(
    'changed',true,'already_accepted',false,'company_id',v_invitation.company_id,
    'user_id',v_user_id,'invitation_id',v_invitation_id,
    'membership_role',v_membership_role,'role_key',v_role_key
  );
  insert into public.canonical_command_results(
    company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
  ) values(
    v_invitation.company_id,'tenant.invitation.accept',v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
  );
  return v_result;
end
$$;

--
-- Name: canonical_actor_is_authorized(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_actor_is_authorized(p_company_id uuid, p_actor_user_id uuid, p_permission_key text, p_platform_only boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.canonical_actor_is_platform_admin(p_actor_user_id)
    or (
      not p_platform_only
      and p_company_id is not null
      and exists (
        select 1
        from auth.users u
        join public.user_profiles up on up.id = u.id
        join public.company_memberships cm
          on cm.user_id = u.id
         and cm.company_id = p_company_id
         and cm.status = 'active'
         and coalesce(cm.is_active, true)
        join public.user_roles ur
          on ur.user_id = u.id
         and ur.company_id = p_company_id
         and coalesce(ur.status, 'active') = 'active'
         and coalesce(ur.is_active, true)
        join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)
        join public.role_permissions rp on rp.role_id = r.id
        join public.permissions p on p.id = rp.permission_id
        where u.id = p_actor_user_id
          and u.deleted_at is null
          and (u.banned_until is null or u.banned_until <= now())
          and u.email_confirmed_at is not null
          and up.user_status = 'active'
          and p.key = p_permission_key
      )
    )
$$;

--
-- Name: canonical_actor_is_platform_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_actor_is_platform_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_user_id is not null
    and exists (
      select 1
      from auth.users u
      join public.user_profiles up on up.id=u.id
      where u.id=p_user_id
        and u.deleted_at is null
        and (u.banned_until is null or u.banned_until <= now())
        and up.user_status='active'
    )
    and (
      exists (
        select 1
        from public.admin_users au
        where au.user_id=p_user_id
          and coalesce(au.is_active,true)
          and public.gridex_normalize_platform_role(au.role)
            in ('super_admin','platform_admin')
      )
      or exists (
        select 1
        from public.user_roles ur
        left join public.roles r on r.id=ur.role_id
        where ur.user_id=p_user_id
          and ur.company_id is null
          and coalesce(ur.is_active,true)
          and coalesce(ur.status,'active')='active'
          and public.gridex_normalize_platform_role(coalesce(ur.role,r.key,r.name))
            in ('super_admin','platform_admin')
      )
    )
$$;

--
-- Name: canonical_approve_actor_test_attestation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_actor_test_attestation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_attestation_id uuid:=(p_command->>'attestation_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_decision_reason text:=nullif(btrim(p_command->>'decision_reason'),'');
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_attestation public.actor_test_manual_attestations%rowtype;
  v_run public.ediel_test_runs%rowtype;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_attempt_id uuid;
  v_event_id uuid;
  v_digest text;
  v_existing jsonb;
  v_result jsonb;
  v_actor_role text;
begin
  if v_company_id is null or v_attestation_id is null or v_actor_user_id is null
     or v_decision_reason is null or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'manual_attestation_approval_fields_required';
  end if;

  if not public.gridex_actor_has_company_permission(
    v_actor_user_id,v_company_id,'ediel_testing.attest'
  ) then
    raise exception using errcode='42501',message='ediel_testing_attest_permission_denied';
  end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='ediel.test.attestation.approve' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select * into v_attestation from public.actor_test_manual_attestations
  where id=v_attestation_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_attestation_not_found'; end if;
  if v_attestation.status<>'requested' then raise exception 'attestation_is_not_pending'; end if;
  if v_attestation.requested_by=v_actor_user_id then raise exception 'attestation_requires_separate_approver'; end if;

  select * into v_run from public.ediel_test_runs
  where id=v_attestation.test_run_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_test_run_not_found'; end if;
  if v_run.environment_type='production'::public.ediel_environment_type
     or lower(coalesce(v_run.environment,''))<>'test' then
    raise exception 'manual_attestation_requires_consistent_test_environment';
  end if;
  if v_run.configuration_snapshot_id is null or coalesce(v_run.is_stale,false) then
    raise exception 'stale_test_run_cannot_be_manually_attested';
  end if;
  select * into v_snapshot from public.ediel_configuration_snapshots
  where id=v_run.configuration_snapshot_id and company_id=v_company_id;
  if not found then raise exception 'test_run_snapshot_not_found_for_tenant'; end if;

  v_actor_role:=case lower(coalesce(nullif(v_run.actor_role,''),v_run.role_code))
    when 'supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else null
  end;
  if v_actor_role is null
     or nullif(btrim(v_run.test_suite),'') is null
     or nullif(btrim(v_run.setup_package),'') is null
     or nullif(btrim(v_run.message_family),'') is null
     or nullif(btrim(v_run.rulebook_version),'') is null then
    raise exception 'manual_attestation_canonical_identity_incomplete';
  end if;

  v_digest:=encode(extensions.digest(convert_to(v_attestation.reason||'|'||v_attestation.evidence_reference||'|'||v_decision_reason,'utf8'),'sha256'::text),'hex');
  insert into public.actor_test_attempts(
    company_id,test_run_id,test_case_code,environment_type,actor_role,role_code,
    test_suite,setup_package,message_family,message_variant,status,machine_verified,
    configuration_snapshot_id,configuration_hash,rulebook_version,engine_version,
    started_at,completed_at,evidence_digest,failure_details,created_by
  ) values (
    v_company_id,v_run.id,v_attestation.test_case_code,v_run.environment_type,v_actor_role,v_run.role_code,
    v_run.test_suite,v_run.setup_package,upper(v_run.message_family),v_run.message_variant,'manual_verified',false,
    v_snapshot.id,v_snapshot.configuration_hash,coalesce(v_run.rulebook_version,'unknown'),v_run.engine_version,
    coalesce(v_run.started_at,v_run.created_at),now(),v_digest,
    jsonb_build_object('reason',v_attestation.reason,'evidence_reference',v_attestation.evidence_reference,'decision_reason',v_decision_reason),
    v_actor_user_id
  ) returning id into v_attempt_id;

  update public.actor_test_manual_attestations
  set attempt_id=v_attempt_id,approved_by=v_actor_user_id,approved_at=now(),status='approved',decision_reason=v_decision_reason
  where id=v_attestation_id and company_id=v_company_id;

  insert into public.actor_test_results(
    company_id,test_key,status,latest_run_at,passed_at,failure_reason,ediel_test_run_id,evidence,
    configuration_snapshot_id,configuration_hash,is_stale,stale_reason,created_by,updated_by,created_at,updated_at
  ) values (
    v_company_id,v_attestation.test_case_code,'manual_verified',now(),null,null,v_run.id,
    jsonb_build_object('manual_attestation_id',v_attestation_id,'attempt_id',v_attempt_id,'reason',v_attestation.reason,
      'evidence_reference',v_attestation.evidence_reference,'approved_by',v_actor_user_id,'decision_reason',v_decision_reason),
    v_snapshot.id,v_snapshot.configuration_hash,false,null,v_actor_user_id,v_actor_user_id,now(),now()
  ) on conflict(company_id,test_key) do update set
    status='manual_verified',latest_run_at=excluded.latest_run_at,passed_at=null,failure_reason=null,
    ediel_test_run_id=excluded.ediel_test_run_id,evidence=excluded.evidence,
    configuration_snapshot_id=excluded.configuration_snapshot_id,configuration_hash=excluded.configuration_hash,
    is_stale=false,stale_reason=null,updated_by=excluded.updated_by,updated_at=excluded.updated_at;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,after_state
  ) values (
    v_company_id,'EDIEL_TEST_MANUALLY_ATTESTED','actor_test_attempt',v_attempt_id,
    v_actor_user_id,v_decision_reason,v_idempotency_key,
    jsonb_build_object('status','manual_verified','test_run_id',v_run.id,'attestation_id',v_attestation_id,
      'configuration_snapshot_id',v_snapshot.id)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'EDIEL_TEST_MANUALLY_ATTESTED','actor_test_attempt',v_attempt_id,v_idempotency_key,
    jsonb_build_object('test_run_id',v_run.id,'test_case_code',v_attestation.test_case_code,
      'attestation_id',v_attestation_id,'configuration_snapshot_id',v_snapshot.id),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'ediel.test.manually_attested',v_idempotency_key,
    jsonb_build_object('attempt_id',v_attempt_id,'attestation_id',v_attestation_id,'test_run_id',v_run.id));

  v_result:=jsonb_build_object('attempt_id',v_attempt_id,'attestation_id',v_attestation_id,
    'status','manual_verified','configuration_snapshot_id',v_snapshot.id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'ediel.test.attestation.approve',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_approve_first_live_send(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_first_live_send(p_company_id uuid, p_readiness_check_id uuid, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('readiness_check_id', p_readiness_check_id);
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, 'ediel.send', false) then
    raise exception 'actor_not_authorized_for_first_live_send';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':ediel.production.first_live_send.approve', 0));
  v_hash := public.canonical_json_sha256(v_request);
  select * into v_existing from public.canonical_command_results
  where company_id = p_company_id and command_type = 'ediel.production.first_live_send.approve'
    and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.actor_user_id is distinct from p_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;
  if exists (
    select 1 from public.ediel_production_state
    where company_id = p_company_id and first_live_send_approved_at is not null
  ) then raise exception 'first_live_send_already_approved'; end if;
  v_result := public.canonical_approve_first_live_send_v1_unchecked(
    p_company_id, p_readiness_check_id, p_actor_user_id, p_idempotency_key
  );
  update public.canonical_command_results set request_payload = v_request
  where company_id = p_company_id and command_type = 'ediel.production.first_live_send.approve'
    and idempotency_key = p_idempotency_key;
  return v_result;
end;
$$;

--
-- Name: canonical_approve_first_live_send_v1_unchecked(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_first_live_send_v1_unchecked(p_company_id uuid, p_readiness_check_id uuid, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_state public.ediel_production_state%rowtype;
  v_readiness public.ediel_production_readiness_checks%rowtype;
  v_existing jsonb;
  v_event_id uuid;
  v_result jsonb;
begin
  select result_payload into v_existing from public.canonical_command_results
  where company_id=p_company_id and command_type='ediel.production.first_live_send.approve' and idempotency_key=p_idempotency_key;
  if found then return v_existing; end if;

  select * into v_company from public.companies where id=p_company_id for update;
  select * into v_state from public.ediel_production_state where company_id=p_company_id for update;
  if v_company.status<>'active' then raise exception 'tenant_must_be_active'; end if;
  if v_state.state<>'live' then raise exception 'ediel_production_must_be_live'; end if;
  select * into v_readiness from public.ediel_production_readiness_checks
  where id=p_readiness_check_id and company_id=p_company_id;
  if not found or v_readiness.status not in ('ready','warning','live')
     or jsonb_array_length(coalesce(v_readiness.blocking_issues,'[]'::jsonb))>0
     or coalesce(v_readiness.is_stale,false)
     or v_readiness.configuration_snapshot_id is distinct from v_state.configuration_snapshot_id then
    raise exception 'valid_current_readiness_check_required';
  end if;

  update public.ediel_production_state
  set first_live_send_approved_by=p_actor_user_id,
      first_live_send_approved_at=coalesce(first_live_send_approved_at,now()),
      updated_at=now()
  where company_id=p_company_id;
  update public.companies
  set ediel_first_live_send_approved_by=p_actor_user_id,
      ediel_first_live_send_approved_at=coalesce(ediel_first_live_send_approved_at,now()),
      updated_at=now()
  where id=p_company_id;

  insert into public.canonical_domain_events(company_id,event_type,aggregate_type,aggregate_id,aggregate_version,idempotency_key,payload,created_by)
  values(p_company_id,'EDIEL_FIRST_LIVE_SEND_APPROVED','ediel_production',p_company_id,v_state.state_version,
    p_idempotency_key,jsonb_build_object('readiness_check_id',p_readiness_check_id),p_actor_user_id)
  returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(p_company_id,v_event_id,'ediel.production.first_live_send.approved',p_idempotency_key,
    jsonb_build_object('company_id',p_company_id,'readiness_check_id',p_readiness_check_id));
  insert into public.canonical_audit_events(company_id,event_type,aggregate_type,aggregate_id,state_version,actor_user_id,reason,idempotency_key,after_state)
  values(p_company_id,'EDIEL_FIRST_LIVE_SEND_APPROVED','ediel_production',p_company_id,v_state.state_version,
    p_actor_user_id,'Första live-sändning godkänd.',p_idempotency_key,
    jsonb_build_object('approved',true,'readiness_check_id',p_readiness_check_id));

  v_result:=jsonb_build_object('changed',true,'company_id',p_company_id,'approved',true,'domain_event_id',v_event_id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(p_company_id,'ediel.production.first_live_send.approve',p_idempotency_key,
    jsonb_build_object('readiness_check_id',p_readiness_check_id),v_result,p_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_authenticated_tenant_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_authenticated_tenant_context(p_selected_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  -- The scoped implementation filters roles and permissions by
  -- user_role.company_id = selected company. Permissions never span companies.
  return public.canonical_authenticated_tenant_context_v1_scoped(p_selected_company_id);
end
$$;

--
-- Name: FUNCTION canonical_authenticated_tenant_context(p_selected_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_authenticated_tenant_context(p_selected_company_id uuid) IS 'F-1: delegates to the company-scoped resolver. Permissions are never unioned across companies.';

--
-- Name: canonical_authenticated_tenant_context_v1_scoped(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_authenticated_tenant_context_v1_scoped(p_selected_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_user_email text;
  v_platform boolean := false;
  v_profile_active boolean := false;
  v_selected_company_id uuid;
  v_memberships jsonb := '[]'::jsonb;
  v_roles jsonb := '[]'::jsonb;
  v_permissions jsonb := '[]'::jsonb;
  v_company jsonb;
  v_policy jsonb := '{}'::jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('authorized',false,'reason_code','authentication_required');
  end if;

  select exists(
    select 1 from auth.users u
    join public.user_profiles profile on profile.id=u.id
    where u.id=v_user_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= now())
      and u.email_confirmed_at is not null
      and profile.user_status='active'
  ) into v_profile_active;
  if not v_profile_active then
    return jsonb_build_object('authorized',false,'reason_code','identity_not_active');
  end if;

  v_platform := public.canonical_actor_is_platform_admin(v_user_id);
  select u.email into v_user_email from auth.users u where u.id=v_user_id;

  if v_platform then
    select coalesce(jsonb_agg(jsonb_build_object(
      'membership_id',null,
      'company_id',company.id,
      'company_name',company.name,
      'company_slug',company.slug,
      'org_number',company.org_number,
      'membership_role','platform_admin',
      'role_key','platform_admin',
      'status',company.status
    ) order by company.name),'[]'::jsonb)
    into v_memberships
    from public.companies company
    where company.status <> 'deleted_test_only';

    if p_selected_company_id is not null and exists(
      select 1 from public.companies where id=p_selected_company_id and status <> 'deleted_test_only'
    ) then
      v_selected_company_id := p_selected_company_id;
    end if;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'membership_id',membership.id,
      'company_id',company.id,
      'company_name',company.name,
      'company_slug',company.slug,
      'org_number',company.org_number,
      'membership_role',membership.membership_role,
      'role_key',role.key,
      'status',company.status
    ) order by (membership.membership_role='owner') desc, company.name),'[]'::jsonb)
    into v_memberships
    from public.company_memberships membership
    join public.companies company on company.id=membership.company_id
    join public.user_roles user_role
      on user_role.user_id=membership.user_id
     and user_role.company_id=membership.company_id
     and coalesce(user_role.status,'active')='active'
     and coalesce(user_role.is_active,true)
    join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
    where membership.user_id=v_user_id
      and membership.status='active'
      and coalesce(membership.is_active,true);

    select company_id into v_selected_company_id
    from public.company_memberships membership
    where membership.user_id=v_user_id
      and membership.status='active'
      and coalesce(membership.is_active,true)
      and (p_selected_company_id is null or membership.company_id=p_selected_company_id)
      and exists(
        select 1 from public.user_roles user_role
        where user_role.user_id=membership.user_id
          and user_role.company_id=membership.company_id
          and coalesce(user_role.status,'active')='active'
          and coalesce(user_role.is_active,true)
      )
    order by (membership.company_id=p_selected_company_id) desc,
             (membership.membership_role='owner') desc,
             membership.created_at
    limit 1;
  end if;

  select coalesce(jsonb_agg(distinct role.key),'[]'::jsonb)
  into v_roles
  from public.user_roles user_role
  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
  where user_role.user_id=v_user_id
    and coalesce(user_role.status,'active')='active'
    and coalesce(user_role.is_active,true)
    and (user_role.company_id is null or user_role.company_id=v_selected_company_id);

  select coalesce(jsonb_agg(distinct permission.key),'[]'::jsonb)
  into v_permissions
  from public.user_roles user_role
  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
  join public.role_permissions role_permission on role_permission.role_id=role.id
  join public.permissions permission on permission.id=role_permission.permission_id
  where user_role.user_id=v_user_id
    and coalesce(user_role.status,'active')='active'
    and coalesce(user_role.is_active,true)
    and (user_role.company_id is null or user_role.company_id=v_selected_company_id)
    and coalesce(role_permission.effect,'allow')='allow';

  if v_selected_company_id is not null then
    select jsonb_build_object(
      'id',company.id,
      'name',company.name,
      'slug',company.slug,
      'org_number',company.org_number,
      'status',company.status,
      'lifecycle_status',company.lifecycle_status,
      'lifecycle_state_version',company.lifecycle_state_version
    ) into v_company
    from public.companies company where company.id=v_selected_company_id;

    select coalesce(jsonb_object_agg(operation.operation, to_jsonb(decision)),'{}'::jsonb)
    into v_policy
    from unnest(array[
      'tenant.provisioning.execute','email.send','webhook.deliver',
      'customer_automation.execute','facility_lookup.execute',
      'contract_channel.sell','api_client.execute'
    ]::text[]) operation(operation)
    cross join lateral public.canonical_tenant_operation_decision(
      v_selected_company_id, operation.operation
    ) decision;
  end if;

  return jsonb_build_object(
    'authorized',true,
    'user_id',v_user_id,
    'user_email',v_user_email,
    'is_platform_admin',v_platform,
    'selected_company_id',v_selected_company_id,
    'memberships',v_memberships,
    'roles',v_roles,
    'permissions',v_permissions,
    'company',v_company,
    'operation_policy',v_policy,
    'access_invariant_ok',v_platform or v_selected_company_id is not null
  );
end
$$;

--
-- Name: canonical_bind_test_run_active_configuration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_bind_test_run_active_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_role text;
  v_environment_type public.ediel_environment_type;
  v_message_family text;
  v_definition_count integer;
  v_definition public.ediel_test_cases%rowtype;
  v_config_count integer;
  v_config public.ediel_active_test_configurations%rowtype;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_actor public.ediel_actor_settings%rowtype;
  v_route public.ediel_route_profiles%rowtype;
begin
  if lower(coalesce(new.environment,'test')) <> 'test' then return new; end if;
  if new.company_id is null then return new; end if;

  v_actor_role := case lower(coalesce(nullif(new.actor_role,''),new.role_code))
    when 'supplier' then 'supplier'
    when 'electricity_supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else null
  end;
  if v_actor_role is null then return new; end if;

  v_message_family := upper(coalesce(nullif(new.message_family,''),new.test_suite));
  v_environment_type := new.environment_type;

  select count(*) into v_definition_count
  from public.ediel_test_cases tc
  where tc.is_active
    and upper(tc.test_case_code)=upper(new.test_case_code)
    and lower(tc.actor_role)=v_actor_role
    and upper(tc.message_family)=v_message_family;

  if v_definition_count=1 then
    select * into strict v_definition
    from public.ediel_test_cases tc
    where tc.is_active
      and upper(tc.test_case_code)=upper(new.test_case_code)
      and lower(tc.actor_role)=v_actor_role
      and upper(tc.message_family)=v_message_family;

    v_environment_type := case
      when upper(v_definition.suite_key) like 'AGT\_%' escape '\' then 'agt_test'::public.ediel_environment_type
      when upper(v_definition.suite_key) like 'TGT\_%' escape '\' then 'tgt_test'::public.ediel_environment_type
      else coalesce(v_environment_type,'bilateral_test'::public.ediel_environment_type)
    end;
    v_message_family := upper(v_definition.message_family);
  elsif v_definition_count>1 then
    raise exception 'canonical_test_definition_ambiguous_for_run';
  end if;

  select count(*) into v_config_count
  from public.ediel_active_test_configurations c
  where c.company_id=new.company_id
    and c.environment='test'
    and c.status='active'
    and c.environment_type=v_environment_type
    and upper(c.test_suite)=upper(new.test_suite)
    and lower(c.actor_role)=v_actor_role
    and upper(c.message_family)=v_message_family
    and (
      nullif(btrim(new.setup_package),'') is null
      or upper(new.setup_package)=upper(new.test_suite)
      or c.setup_package=new.setup_package
    );

  if v_config_count=0 then
    if coalesce(new.engine_version,'')='actor-testing-evidence-v2'
       or lower(coalesce(new.status,'')) in ('running','passed') then
      raise exception 'active_role_scoped_test_configuration_required';
    end if;
    return new;
  end if;
  if v_config_count>1 then
    raise exception 'active_role_scoped_test_configuration_ambiguous';
  end if;

  select * into strict v_config
  from public.ediel_active_test_configurations c
  where c.company_id=new.company_id
    and c.environment='test'
    and c.status='active'
    and c.environment_type=v_environment_type
    and upper(c.test_suite)=upper(new.test_suite)
    and lower(c.actor_role)=v_actor_role
    and upper(c.message_family)=v_message_family
    and (
      nullif(btrim(new.setup_package),'') is null
      or upper(new.setup_package)=upper(new.test_suite)
      or c.setup_package=new.setup_package
    );

  if v_config.actor_profile_id is null or v_config.route_profile_id is null then
    raise exception 'active_test_configuration_actor_and_route_binding_required';
  end if;

  select * into v_snapshot
  from public.ediel_configuration_snapshots
  where id=v_config.configuration_snapshot_id and company_id=new.company_id;
  if not found then raise exception 'active_test_configuration_snapshot_not_found'; end if;

  select * into v_actor
  from public.ediel_actor_settings
  where id=v_config.actor_profile_id and company_id=new.company_id;
  if not found or lower(coalesce(v_actor.environment,''))<>'test' or coalesce(v_actor.is_active,false)<>true then
    raise exception 'active_test_configuration_actor_invalid';
  end if;

  select * into v_route
  from public.ediel_route_profiles
  where id=v_config.route_profile_id and company_id=new.company_id;
  if not found or lower(coalesce(v_route.environment,''))<>'test'
     or coalesce(v_route.is_active,true)<>true or coalesce(v_route.is_enabled,true)<>true then
    raise exception 'active_test_configuration_route_invalid';
  end if;

  if upper(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id,''))
     <> upper(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id,'')) then
    raise exception 'active_test_configuration_route_sender_actor_mismatch';
  end if;

  new.actor_role := v_actor_role;
  new.message_family := v_message_family;
  new.environment_type := v_environment_type;
  new.setup_package := v_config.setup_package;
  new.actor_profile_id := v_config.actor_profile_id;
  new.route_profile_id := v_config.route_profile_id;
  new.configuration_snapshot_id := v_config.configuration_snapshot_id;
  new.configuration_hash := v_snapshot.configuration_hash;
  return new;
end;
$$;

--
-- Name: canonical_block_claimed_ediel_outbox_item(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_block_claimed_ediel_outbox_item(p_outbox_item_id uuid, p_worker_id text, p_reason text, p_company_status text DEFAULT NULL::text, p_operation_decision jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_changed integer;
begin
  if p_outbox_item_id is null or nullif(btrim(p_worker_id),'') is null
     or nullif(btrim(p_reason),'') is null then
    raise exception using errcode='22023', message='outbox_item_worker_and_reason_required';
  end if;

  update public.ediel_outbox
  set status='blocked_tenant_state',
      blocked_reason=p_reason,
      blocked_at=now(),
      company_status_snapshot=p_company_status,
      operation_decision_snapshot=coalesce(p_operation_decision,'{}'::jsonb),
      locked_at=null,
      locked_by=null,
      updated_at=now()
  where id=p_outbox_item_id
    and locked_by=p_worker_id
    and status='sending';
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception using errcode='P0001', message='ediel_outbox_claim_block_lock_lost';
  end if;
  return 'blocked_tenant_state';
end
$$;

--
-- Name: ediel_configuration_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_configuration_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    snapshot_version bigint NOT NULL,
    actor_role text,
    test_ediel_id text,
    production_ediel_id text,
    test_brp_ediel_id text,
    production_brp_ediel_id text,
    test_application_reference text,
    production_application_reference text,
    primary_test_route_id uuid,
    primary_production_route_id uuid,
    payload jsonb NOT NULL,
    configuration_hash text NOT NULL,
    reason text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: canonical_capture_ediel_configuration_snapshot(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_configuration_snapshot(p_company_id uuid, p_actor_user_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_actor_user_id is null then
    return public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
      p_company_id,
      null,
      p_reason
    );
  end if;

  if not public.canonical_actor_is_authorized(
    p_company_id,
    p_actor_user_id,
    'ediel.profile.write',
    false
  ) then
    raise exception 'actor_not_authorized_for_configuration_snapshot';
  end if;

  return public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
    p_company_id,
    p_actor_user_id,
    p_reason
  );
end;
$$;

--
-- Name: canonical_capture_ediel_configuration_snapshot_v1_unchecked(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(p_company_id uuid, p_actor_user_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_payload jsonb;
  v_hash text;
  v_next_version bigint;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_existing public.ediel_configuration_snapshots%rowtype;
begin
  if p_company_id is null then raise exception 'company_id_required'; end if;
  select * into v_company from public.companies where id = p_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;

  v_payload := jsonb_build_object(
    'company', jsonb_build_object(
      'id', v_company.id,
      'actor_role', coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>'market_role', '')),
      'test_ediel_id', v_company.test_ediel_id,
      'production_ediel_id', v_company.production_ediel_id,
      'brp_ediel_id', v_company.brp_ediel_id,
      'test_application_reference', v_company.test_application_reference,
      'production_application_reference', v_company.production_application_reference,
      'test_sender_sub_address', v_company.test_sender_sub_address,
      'production_sender_sub_address', v_company.production_sender_sub_address,
      'test_mailbox', v_company.test_mailbox,
      'production_mailbox', v_company.production_mailbox,
      'primary_test_route_id', v_company.ediel_primary_test_route_profile_id,
      'primary_production_route_id', v_company.ediel_primary_production_route_profile_id
    ),
    'actor_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id,
        'environment', a.environment,
        'actor_role', coalesce(a.actor_role, a.role),
        'ediel_id', coalesce(a.actor_ediel_id, a.ediel_id),
        'sender_subaddress', coalesce(a.sender_sub_address, a.sender_subaddress),
        'receiver_subaddress', coalesce(a.receiver_sub_address, a.receiver_subaddress),
        'application_reference', coalesce(a.application_reference, a.default_application_reference),
        'mailbox', a.mailbox,
        'brp_ediel_id', a.brp_ediel_id,
        'is_active', a.is_active
      ) order by a.environment, a.id)
      from public.ediel_actor_settings a
      where a.company_id = p_company_id
    ), '[]'::jsonb),
    'routes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'environment', r.environment,
        'route_type', r.route_type,
        'sender_ediel_id', r.sender_ediel_id,
        'sender_subaddress', coalesce(r.sender_sub_address, r.sender_subaddress),
        'receiver_ediel_id', r.receiver_ediel_id,
        'receiver_subaddress', coalesce(r.receiver_sub_address, r.receiver_subaddress),
        'mailbox_id', r.mailbox_id,
        'transport_profile_id', r.transport_profile_id,
        'certificate_id', r.certificate_id,
        'receiver_certificate_id', r.receiver_certificate_id,
        'is_active', r.is_active,
        'is_enabled', r.is_enabled
      ) order by r.environment, r.id)
      from public.ediel_route_profiles r
      where r.company_id = p_company_id
    ), '[]'::jsonb),
    'mailboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'environment', m.environment,
        'mailbox_name', m.mailbox_name,
        'email_address', m.email_address,
        'imap_host', m.imap_host,
        'imap_port', m.imap_port,
        'provider', m.provider,
        'mailbox_type', m.mailbox_type,
        'is_active', m.is_active,
        'is_shared_platform_mailbox', m.is_shared_platform_mailbox,
        'secret_reference_present', m.secret_reference is not null
      ) order by m.environment, m.id)
      from public.ediel_mailboxes m
      where m.company_id = p_company_id
    ), '[]'::jsonb),
    'certificates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id,
        'fingerprint', c.certificate_fingerprint,
        'valid_from', c.certificate_valid_from,
        'valid_to', c.certificate_valid_to,
        'encryption_status', c.encryption_status,
        'status', c.status
      ) order by c.id)
      from public.ediel_certificates c
      where c.company_id = p_company_id
    ), '[]'::jsonb),
    'active_test_configurations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'environment', tc.environment,
        'test_suite', tc.test_suite,
        'actor_role', tc.actor_role,
        'message_family', tc.message_family,
        'setup_package', tc.setup_package,
        'status', tc.status
      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)
      from public.ediel_active_test_configurations tc
      where tc.company_id = p_company_id and tc.status = 'active'
    ), '[]'::jsonb),
    'active_rule_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.id,
        'rule_key', rv.rule_key,
        'version_code', rv.version_code,
        'schema_version', rv.schema_version,
        'environment', rv.environment,
        'message_family', rv.message_family,
        'message_code', rv.message_code,
        'business_process', rv.business_process,
        'source_version', rv.source_version,
        'status', rv.status,
        'is_active', rv.is_active
      ) order by rv.rule_key, rv.version_code, rv.id)
      from public.ediel_rule_versions rv
      where coalesce(rv.is_active, false) = true
        and coalesce(rv.status, 'active') = 'active'
    ), '[]'::jsonb),
    'active_rule_packs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rp.id,
        'market', rp.market,
        'family', rp.family,
        'guide_version', rp.guide_version,
        'guide_revision', rp.guide_revision,
        'unh_association_code', rp.unh_association_code,
        'valid_from', rp.valid_from,
        'valid_to', rp.valid_to,
        'status', rp.status,
        'source_hash', rp.source_hash,
        'field_matrix_version', rp.field_matrix_version,
        'code_list_versions', rp.code_list_versions
      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)
      from public.ediel_rule_packs rp
      where rp.status = 'active'
    ), '[]'::jsonb),
    'enabled_message_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', mp.id,
        'rule_pack_id', mp.rule_pack_id,
        'message_code', mp.message_code,
        'transaction_subtype', mp.transaction_subtype,
        'direction', mp.direction,
        'business_process', mp.business_process,
        'phase', mp.phase,
        'profile_key', mp.profile_key,
        'profile', mp.profile,
        'is_enabled', mp.is_enabled
      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)
      from public.ediel_message_profiles mp
      where mp.is_enabled = true
    ), '[]'::jsonb),
    'active_tenant_rule_profile_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rpv.id,
        'rule_profile_id', rpv.rule_profile_id,
        'profile_key', rpv.profile_key,
        'version', rpv.version,
        'status', rpv.status,
        'checksum', rpv.checksum,
        'source_revision', rpv.source_revision,
        'rules', rpv.rules
      ) order by rpv.profile_key, rpv.version, rpv.id)
      from public.ediel_rule_profile_versions rpv
      where rpv.company_id = p_company_id and rpv.status = 'active'
    ), '[]'::jsonb),
    'engine_version', 'canonical-evidence-v3'
  );

  v_hash := encode(digest(convert_to(v_payload::text, 'utf8'), 'sha256'), 'hex');
  select * into v_existing
  from public.ediel_configuration_snapshots
  where company_id = p_company_id and configuration_hash = v_hash;
  if found then return v_existing; end if;

  select coalesce(max(snapshot_version), 0) + 1 into v_next_version
  from public.ediel_configuration_snapshots
  where company_id = p_company_id;

  insert into public.ediel_configuration_snapshots(
    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,
    test_brp_ediel_id, production_brp_ediel_id,
    test_application_reference, production_application_reference,
    primary_test_route_id, primary_production_route_id, payload, configuration_hash,
    reason, created_by
  ) values (
    p_company_id,
    v_next_version,
    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>'market_role', '')),
    v_company.test_ediel_id,
    v_company.production_ediel_id,
    v_company.brp_ediel_id,
    v_company.brp_ediel_id,
    v_company.test_application_reference,
    v_company.production_application_reference,
    v_company.ediel_primary_test_route_profile_id,
    v_company.ediel_primary_production_route_profile_id,
    v_payload,
    v_hash,
    coalesce(nullif(btrim(p_reason), ''), 'configuration_changed'),
    p_actor_user_id
  ) returning * into v_snapshot;

  -- Exactly one durable readiness revalidation job per immutable snapshot.
  insert into public.company_provisioning_jobs(
    company_id,
    job_key,
    status,
    idempotency_key,
    available_at,
    last_error_details
  ) values (
    p_company_id,
    'ediel_readiness_revalidate',
    'pending',
    v_snapshot.id::text,
    now(),
    '{}'::jsonb
  )
  on conflict (company_id, job_key, idempotency_key) do nothing;

  update public.ediel_test_runs
  set is_stale = true,
      stale_reason = 'configuration_changed',
      stale_at = now()
  where company_id = p_company_id
    and completed_at is not null
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.actor_test_results
  set is_stale = true,
      stale_reason = 'configuration_changed',
      updated_at = now()
  where company_id = p_company_id
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.ediel_production_readiness_checks
  set is_stale = true,
      stale_reason = 'configuration_changed'
  where company_id = p_company_id
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.ediel_go_live_events
  set is_stale = true,
      stale_reason = 'configuration_changed'
  where company_id = p_company_id
    and event_type = 'production_dry_run'
    and configuration_snapshot_id is distinct from v_snapshot.id;

  -- This aggregate snapshot is retained for operations/dashboard continuity.
  -- A dependency change invalidates only matching immutable capability proofs
  -- on their next read; it must not pause an unrelated legal role/capability.
  -- Explicit operator production state and send locks are preserved.
  update public.ediel_production_state
  set configuration_snapshot_id = v_snapshot.id,
      updated_at = now()
  where company_id = p_company_id;

  return v_snapshot;
end;
$$;

--
-- Name: canonical_capture_ediel_test_configuration_snapshot(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_test_configuration_snapshot(p_company_id uuid, p_actor_user_id uuid, p_actor_profile_id uuid, p_route_profile_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_actor public.ediel_actor_settings%rowtype;
  v_route public.ediel_route_profiles%rowtype;
  v_communication_route public.communication_routes%rowtype;
  v_payload jsonb;
  v_hash text;
  v_next_version bigint;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_existing public.ediel_configuration_snapshots%rowtype;
  v_actor_role text;
  v_actor_ediel_id text;
  v_route_sender text;
  v_route_receiver text;
begin
  if p_company_id is null or p_actor_profile_id is null or p_route_profile_id is null then
    raise exception 'company_actor_profile_and_route_required';
  end if;
  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, 'ediel.profile.write', false) then
    raise exception 'actor_not_authorized_for_test_configuration_snapshot';
  end if;

  select * into v_company
  from public.companies
  where id=p_company_id
  for update;
  if not found then raise exception 'tenant_not_found'; end if;

  select * into v_actor
  from public.ediel_actor_settings
  where id=p_actor_profile_id and company_id=p_company_id
  for share;
  if not found then raise exception 'tenant_scoped_test_actor_profile_not_found'; end if;
  if lower(coalesce(v_actor.environment,'')) <> 'test' or coalesce(v_actor.is_active,false) <> true then
    raise exception 'test_actor_profile_must_be_active_test_profile';
  end if;

  v_actor_role := case lower(coalesce(nullif(v_actor.actor_role,''),v_actor.role))
    when 'supplier' then 'supplier'
    when 'electricity_supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else lower(coalesce(nullif(v_actor.actor_role,''),v_actor.role))
  end;
  v_actor_ediel_id := nullif(btrim(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id)), '');
  if v_actor_role is null or v_actor_ediel_id is null then
    raise exception 'test_actor_profile_identity_incomplete';
  end if;

  select * into v_route
  from public.ediel_route_profiles
  where id=p_route_profile_id and company_id=p_company_id
  for share;
  if not found then raise exception 'tenant_scoped_test_route_profile_not_found'; end if;
  if lower(coalesce(v_route.environment,'')) <> 'test'
     or coalesce(v_route.is_active,true) <> true
     or coalesce(v_route.is_enabled,true) <> true then
    raise exception 'test_route_profile_must_be_active_test_route';
  end if;

  v_route_sender := nullif(btrim(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id)), '');
  v_route_receiver := nullif(btrim(coalesce(v_route.receiver_ediel_id,v_route.counterparty_ediel_id)), '');
  if v_route_sender is null or upper(v_route_sender) <> upper(v_actor_ediel_id) then
    raise exception 'test_route_sender_must_match_actor_profile';
  end if;
  if v_route_receiver is null then
    raise exception 'test_route_receiver_required';
  end if;
  if v_route.actor_setting_id is not null and v_route.actor_setting_id <> v_actor.id then
    raise exception 'test_route_actor_binding_mismatch';
  end if;

  select * into v_communication_route
  from public.communication_routes
  where id=v_route.communication_route_id and company_id=p_company_id
  for share;
  if not found or v_communication_route.is_active is distinct from true
     or v_communication_route.environment_type is null
     or v_communication_route.environment_type not in ('agt_test','tgt_test','bilateral_test') then
    raise exception 'test_route_communication_source_required';
  end if;

  v_payload := jsonb_build_object(
    'test_context', jsonb_build_object(
      'actor_profile_id', v_actor.id,
      'route_profile_id', v_route.id,
      'actor_role', v_actor_role,
      'test_ediel_id', v_actor_ediel_id,
      'counterparty_ediel_id', v_route_receiver,
      'message_family', upper(coalesce(v_route.message_family,'')),
      'application_reference', v_route.application_reference,
      'environment_type', v_communication_route.environment_type
    ),
    'company', jsonb_build_object(
      'id', v_company.id,
      'actor_role', v_actor_role,
      'test_ediel_id', v_actor_ediel_id,
      'production_ediel_id', v_company.production_ediel_id,
      'brp_ediel_id', coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),
      'test_application_reference', v_route.application_reference,
      'production_application_reference', v_company.production_application_reference,
      'primary_test_route_id', v_route.id,
      'primary_production_route_id', v_company.ediel_primary_production_route_profile_id
    ),
    'actor_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',a.id,'environment',a.environment,'actor_role',coalesce(a.actor_role,a.role),
        'ediel_id',coalesce(a.actor_ediel_id,a.ediel_id),
        'sender_subaddress',coalesce(a.sender_sub_address,a.sender_subaddress),
        'receiver_subaddress',coalesce(a.receiver_sub_address,a.receiver_subaddress),
        'application_reference',coalesce(a.application_reference,a.default_application_reference),
        'mailbox',a.mailbox,'brp_ediel_id',a.brp_ediel_id,'is_active',a.is_active
      ) order by a.environment,a.id)
      from public.ediel_actor_settings a
      where a.company_id=p_company_id
    ),'[]'::jsonb),
    'routes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,'environment',r.environment,'route_type',r.route_type,
        'actor_setting_id',r.actor_setting_id,
        'sender_ediel_id',r.sender_ediel_id,
        'sender_subaddress',coalesce(r.sender_sub_address,r.sender_subaddress),
        'receiver_ediel_id',r.receiver_ediel_id,
        'receiver_subaddress',coalesce(r.receiver_sub_address,r.receiver_subaddress),
        'application_reference',r.application_reference,
        'message_family',r.message_family,
        'environment_type',cr.environment_type,
        'mailbox_id',r.mailbox_id,'transport_profile_id',r.transport_profile_id,
        'certificate_id',r.certificate_id,'receiver_certificate_id',r.receiver_certificate_id,
        'transport_security_mode',r.transport_security_mode,
        'is_active',r.is_active,'is_enabled',r.is_enabled
      ) order by r.environment,r.id)
      from public.ediel_route_profiles r
      left join public.communication_routes cr
        on cr.id=r.communication_route_id and cr.company_id=r.company_id
      where r.company_id=p_company_id
    ),'[]'::jsonb),
    'mailboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',m.id,'environment',m.environment,'mailbox_name',m.mailbox_name,
        'email_address',m.email_address,'provider',m.provider,'mailbox_type',m.mailbox_type,
        'transport_mode',m.transport_mode,'tls_required',m.tls_required,
        'signing_mode',m.signing_mode,'encryption_mode',m.encryption_mode,
        'is_active',m.is_active,'is_shared_platform_mailbox',m.is_shared_platform_mailbox
      ) order by m.environment,m.id)
      from public.ediel_mailboxes m
      where m.company_id=p_company_id or m.id=v_route.mailbox_id
    ),'[]'::jsonb),
    'certificates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',c.id,'fingerprint',coalesce(c.fingerprint_sha256,c.certificate_fingerprint),
        'owner_ediel_id',c.owner_ediel_id,'owner_subaddress',c.owner_subaddress,
        'message_family',c.message_family,'purpose',c.purpose,'usage',c.usage,
        'valid_from',coalesce(c.valid_from,c.certificate_valid_from),
        'valid_to',coalesce(c.valid_to,c.certificate_valid_to),
        'encryption_status',c.encryption_status,'status',c.status
      ) order by c.id)
      from public.ediel_certificates c
      where c.id in (v_route.certificate_id,v_route.receiver_certificate_id)
    ),'[]'::jsonb),
    'active_rule_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rule_key',rv.rule_key,'version_code',rv.version_code,'schema_version',rv.schema_version,
        'environment',rv.environment,'status',rv.status,'is_active',rv.is_active
      ) order by rv.rule_key,rv.version_code)
      from public.ediel_rule_versions rv
      where coalesce(rv.is_active,false)=true and coalesce(rv.status,'active')='active'
    ),'[]'::jsonb),
    'engine_version','canonical-evidence-v3-role-scoped'
  );

  v_hash := encode(digest(convert_to(v_payload::text,'utf8'),'sha256'),'hex');
  select * into v_existing
  from public.ediel_configuration_snapshots
  where company_id=p_company_id and configuration_hash=v_hash;
  if found then return v_existing; end if;

  select coalesce(max(snapshot_version),0)+1 into v_next_version
  from public.ediel_configuration_snapshots
  where company_id=p_company_id;

  insert into public.ediel_configuration_snapshots(
    company_id,snapshot_version,actor_role,test_ediel_id,production_ediel_id,
    test_brp_ediel_id,production_brp_ediel_id,
    test_application_reference,production_application_reference,
    primary_test_route_id,primary_production_route_id,payload,configuration_hash,
    reason,created_by
  ) values (
    p_company_id,v_next_version,v_actor_role,v_actor_ediel_id,v_company.production_ediel_id,
    coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),v_company.brp_ediel_id,
    v_route.application_reference,v_company.production_application_reference,
    v_route.id,v_company.ediel_primary_production_route_profile_id,
    v_payload,v_hash,coalesce(nullif(btrim(p_reason),''),'test_configuration_changed'),p_actor_user_id
  ) returning * into v_snapshot;

  update public.ediel_test_runs r
  set is_stale=true,stale_reason='role_scoped_test_configuration_changed',stale_at=now()
  where r.company_id=p_company_id
    and r.completed_at is not null
    and r.configuration_snapshot_id is distinct from v_snapshot.id
    and case lower(coalesce(nullif(r.actor_role,''),r.role_code))
      when 'supplier' then 'supplier'
      when 'electricity_supplier' then 'supplier'
      when 'esco' then 'energy_service_company'
      when 'energy_service_company' then 'energy_service_company'
      else lower(coalesce(nullif(r.actor_role,''),r.role_code))
    end = v_actor_role
    and upper(coalesce(r.message_family,r.test_suite,'')) = upper(coalesce(v_route.message_family,r.test_suite,''));

  update public.actor_test_results ar
  set is_stale=true,stale_reason='role_scoped_test_configuration_changed',updated_at=now()
  from public.ediel_test_runs r
  where ar.company_id=p_company_id
    and ar.ediel_test_run_id=r.id
    and r.company_id=p_company_id
    and r.configuration_snapshot_id is distinct from v_snapshot.id
    and case lower(coalesce(nullif(r.actor_role,''),r.role_code))
      when 'supplier' then 'supplier'
      when 'electricity_supplier' then 'supplier'
      when 'esco' then 'energy_service_company'
      when 'energy_service_company' then 'energy_service_company'
      else lower(coalesce(nullif(r.actor_role,''),r.role_code))
    end = v_actor_role
    and upper(coalesce(r.message_family,r.test_suite,'')) = upper(coalesce(v_route.message_family,r.test_suite,''));

  return v_snapshot;
end;
$$;

--
-- Name: canonical_change_tenant_user_access(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_command jsonb := p_command;
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_actor_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_operation text := p_command->>'staff_operation';
  v_key text := p_command->>'idempotency_key';
  v_existing public.canonical_command_results%rowtype;
  v_member public.company_memberships%rowtype;
  v_result jsonb;
BEGIN
  IF v_operation IS NULL THEN RETURN public.canonical_change_tenant_user_access_pre_staff_v1(p_command); END IF;
  IF nullif(btrim(v_key),'') IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_company_id::text||':tenant.user_access.change:'||v_key,0));
  PERFORM 1 FROM public.companies WHERE id=v_company_id FOR NO KEY UPDATE;
  SELECT * INTO v_existing FROM public.canonical_command_results
  WHERE company_id=v_company_id AND command_type='tenant.user_access.change' AND idempotency_key=v_key;
  IF FOUND THEN
    IF v_existing.actor_user_id IS DISTINCT FROM v_actor_id THEN RAISE EXCEPTION 'idempotency_actor_mismatch'; END IF;
    -- Staff request stays unmodified in the outer cache (enable resolves role only inside the transaction).
    IF v_existing.request_hash IS DISTINCT FROM public.canonical_json_sha256(p_command-'actor_user_id') THEN
      RAISE EXCEPTION 'idempotency_key_payload_mismatch';
    END IF;
    PERFORM public.gridex_assert_staff_command_v1(p_command,true);
    RETURN v_existing.result_payload;
  END IF;
  PERFORM public.gridex_assert_staff_command_v1(v_command);
  SELECT * INTO v_member FROM public.company_memberships WHERE company_id=v_company_id AND user_id=v_user_id;
  IF v_operation IN ('enable','disable') THEN
    v_command := v_command || jsonb_build_object('role_key',v_member.role_key,'membership_role',v_member.membership_role);
  END IF;
  v_result := public.canonical_change_tenant_user_access_pre_staff_v1(v_command);
  UPDATE public.company_memberships SET role_key=v_command->>'role_key',
    disabled_by=CASE WHEN v_operation='disable' THEN v_actor_id ELSE NULL END,
    status_reason=CASE WHEN v_operation='disable' THEN v_command->>'reason' ELSE NULL END
  WHERE company_id=v_company_id AND user_id=v_user_id;
  SELECT * INTO v_member FROM public.company_memberships WHERE company_id=v_company_id AND user_id=v_user_id;
  v_result := jsonb_build_object('user_id',v_user_id,'role_key',v_member.role_key,'membership_role',v_member.membership_role,'status',v_member.status);
  UPDATE public.canonical_command_results
  SET request_payload=p_command-'actor_user_id', request_hash=public.canonical_json_sha256(p_command-'actor_user_id'), result_payload=v_result
  WHERE company_id=v_company_id AND command_type='tenant.user_access.change' AND idempotency_key=v_key;
  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,new_values,metadata,
    actor_type,request_id,correlation_id,resource_type,resource_id)
  VALUES(v_company_id,v_actor_id,'user',v_user_id::text,'STAFF_'||upper(v_operation),v_result,
    jsonb_build_object('channel',p_command->>'channel','api_client_id',p_command->>'api_client_id'),
    'user',v_key,v_key,'staff',v_user_id::text);
  IF v_operation='disable' THEN
    UPDATE public.company_invitations SET status='invitation_revoked',revoked_at=now()
    WHERE company_id=v_company_id AND invited_user_id=v_user_id
      AND status IN ('pending','sending','sent','delivery_uncertain');
  END IF;
  RETURN v_result;
END;
$$;

--
-- Name: canonical_change_tenant_user_access_pre_staff_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access_pre_staff_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_action text := lower(coalesce(p_command->>'action',''));
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_role_key text := lower(nullif(btrim(p_command->>'role_key'),''));
  v_requested_membership text := lower(nullif(btrim(p_command->>'membership_role'),''));
  v_membership_role text;
  v_normalized jsonb := p_command;
begin
  if v_action = 'upsert' then
    if v_role_key is null then
      raise exception using errcode='22023', message='canonical_role_key_required';
    end if;

    select m.membership_role
      into v_membership_role
    from public.canonical_tenant_access_role_mapping m
    where m.role_key=v_role_key and m.is_assignable;

    if v_membership_role is null then
      raise exception using errcode='22023', message='canonical_tenant_role_not_assignable';
    end if;

    if v_requested_membership is not null
       and v_requested_membership is distinct from v_membership_role then
      raise exception using errcode='23514', message='membership_role_role_key_mismatch';
    end if;

    v_normalized := v_normalized || jsonb_build_object(
      'role_key',v_role_key,
      'membership_role',v_membership_role
    );
  end if;

  v_normalized := v_normalized || jsonb_build_object('actor_user_id',nullif(p_command->>'actor_user_id',''));

  declare
    v_result jsonb;
    v_role_id uuid;
    v_active_user_role_id uuid;
    v_existing_mapped_role_id uuid;
  begin
    v_result := public.canonical_change_tenant_user_access_v2_unmapped(v_normalized);

    if v_action = 'upsert' and v_company_id is not null and v_user_id is not null then
      select r.id into v_role_id
      from public.roles r
      where lower(coalesce(r.key,r.name))=v_role_key
      order by r.created_at asc,r.id asc
      limit 1;
      if v_role_id is null then
        raise exception using errcode='22023', message='canonical_tenant_role_definition_missing';
      end if;
      select ur.id into v_active_user_role_id
      from public.user_roles ur
      where ur.company_id=v_company_id and ur.user_id=v_user_id
        and coalesce(ur.is_active,true) and coalesce(ur.status,'active')='active'
      order by ur.created_at desc,ur.id desc
      limit 1
      for update;
      if v_active_user_role_id is null then
        raise exception using errcode='P0001', message='canonical_active_tenant_role_missing_after_access_change';
      end if;

      select ur.id into v_existing_mapped_role_id
      from public.user_roles ur
      where ur.company_id=v_company_id and ur.user_id=v_user_id
        and ur.role_id=v_role_id and ur.id<>v_active_user_role_id
      order by ur.created_at asc,ur.id asc
      limit 1
      for update;

      if v_existing_mapped_role_id is null then
        update public.user_roles
        set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
        where id=v_active_user_role_id;
      else
        update public.user_roles
        set status='disabled',is_active=false,updated_at=now()
        where id=v_active_user_role_id;
        update public.user_roles
        set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
        where id=v_existing_mapped_role_id;
      end if;
    end if;

    return v_result;
  end;
end
$$;

--
-- Name: canonical_change_tenant_user_access_v1_unchecked(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access_v1_unchecked(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_user_id uuid:=(p_command->>'user_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_action text:=lower(p_command->>'action');
  v_membership_role text:=lower(coalesce(nullif(p_command->>'membership_role',''),'member'));
  v_role_key text:=lower(coalesce(nullif(p_command->>'role_key',''),v_membership_role));
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_company_status text;
  v_current_role text;
  v_current_status text;
  v_actor_membership_role text;
  v_actor_is_platform_admin boolean:=false;
  v_owner_count integer;
  v_admin_count integer;
  v_target_auth_active boolean:=false;
  v_target_profile_active boolean:=false;
  v_existing jsonb;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_company_id is null or v_user_id is null or v_actor_user_id is null
     or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'company_user_actor_and_idempotency_required';
  end if;
  if v_action not in ('upsert','remove','disable') then raise exception 'invalid_access_action'; end if;
  if v_membership_role not in ('owner','admin','company_admin','operations','support','member','viewer') then raise exception 'invalid_membership_role'; end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='tenant.user_access.change' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select status into v_company_status from public.companies where id=v_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;
  if v_company_status not in ('onboarding','active','paused') then
    raise exception 'tenant_state_blocks_user_management:%',coalesce(v_company_status,'unknown');
  end if;

  v_actor_is_platform_admin:=public.canonical_actor_is_platform_admin(v_actor_user_id);
  if not v_actor_is_platform_admin then
    select membership_role into v_actor_membership_role
    from public.company_memberships
    where company_id=v_company_id and user_id=v_actor_user_id
      and status='active' and coalesce(is_active,true)
    for update;
    if p_command ? 'staff_operation' then
      if not ('users.write'=any(public.gridex_staff_actor_permissions_v1(v_company_id,v_actor_user_id,false))) then
        raise exception 'staff_permission_denied';
      end if;
    elsif v_actor_membership_role not in ('owner','admin','company_admin') then
      raise exception 'actor_not_authorized_for_tenant_user_management';
    end if;
  end if;

  select membership_role,status into v_current_role,v_current_status
  from public.company_memberships
  where company_id=v_company_id and user_id=v_user_id
  for update;

  select count(*) into v_owner_count from public.company_memberships
  where company_id=v_company_id and status='active' and coalesce(is_active,true) and membership_role='owner';
  select count(*) into v_admin_count from public.company_memberships
  where company_id=v_company_id and status='active' and coalesce(is_active,true)
    and membership_role in ('owner','admin','company_admin');

  if v_current_status='active' and v_current_role='owner' and v_owner_count<=1
     and (v_action<>'upsert' or v_membership_role<>'owner') then
    raise exception 'last_active_owner_cannot_be_removed_or_downgraded';
  end if;
  if v_current_status='active' and v_current_role in ('owner','admin','company_admin') and v_admin_count<=1
     and (v_action<>'upsert' or v_membership_role not in ('owner','admin','company_admin')) then
    raise exception 'last_active_admin_cannot_be_removed_or_downgraded';
  end if;
  if not v_actor_is_platform_admin and v_membership_role='owner' and v_actor_membership_role<>'owner' then
    raise exception 'only_owner_or_platform_admin_can_assign_owner';
  end if;
  if not v_actor_is_platform_admin and v_current_role='owner' and v_actor_membership_role<>'owner' then
    raise exception 'only_owner_or_platform_admin_can_modify_owner';
  end if;

  if v_action='upsert' then
    select exists(select 1 from auth.users u where u.id=v_user_id and coalesce(u.banned_until,now()-interval '1 second')<=now())
      into v_target_auth_active;
    select exists(select 1 from public.user_profiles up where up.id=v_user_id and up.user_status='active')
      into v_target_profile_active;
    if not v_target_auth_active then raise exception 'target_auth_user_missing_or_inactive'; end if;
    if not v_target_profile_active then raise exception 'target_user_profile_missing_or_inactive'; end if;

    insert into public.company_memberships(
      company_id,user_id,membership_role,role_key,status,is_active,invited_by,accepted_at,
      suspended_at,disabled_at,removed_at,metadata
    ) values (
      v_company_id,v_user_id,v_membership_role,v_role_key,'active',true,v_actor_user_id,now(),
      null,null,null,jsonb_build_object('canonical_access_command',v_idempotency_key)
    )
    on conflict(company_id,user_id) do update set
      membership_role=excluded.membership_role,role_key=excluded.role_key,status='active',is_active=true,
      accepted_at=coalesce(public.company_memberships.accepted_at,now()),
      suspended_at=null,disabled_at=null,removed_at=null,
      metadata=coalesce(public.company_memberships.metadata,'{}'::jsonb)||excluded.metadata,
      updated_at=now();

    update public.user_roles set status='disabled',is_active=false,updated_at=now()
    where company_id=v_company_id and user_id=v_user_id and is_active=true;
    insert into public.user_roles(user_id,company_id,role,status,is_active,created_at,updated_at)
    values(v_user_id,v_company_id,v_role_key,'active',true,now(),now());
  else
    update public.company_memberships
      set status=case when v_action='remove' then 'removed' else 'disabled' end,
          is_active=false,
          disabled_at=case when v_action='disable' then now() else disabled_at end,
          removed_at=case when v_action='remove' then now() else removed_at end,
          metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('canonical_access_command',v_idempotency_key),
          updated_at=now()
      where company_id=v_company_id and user_id=v_user_id;
    update public.user_roles set status='disabled',is_active=false,updated_at=now()
      where company_id=v_company_id and user_id=v_user_id and is_active=true;
  end if;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,before_state,after_state
  ) values (
    v_company_id,'TENANT_USER_ROLE_CHANGED','tenant_user',v_user_id,v_actor_user_id,
    p_command->>'reason',v_idempotency_key,
    jsonb_build_object('membership_role',v_current_role,'status',v_current_status),
    jsonb_build_object('action',v_action,'membership_role',v_membership_role,'role_key',v_role_key)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'TENANT_USER_ROLE_CHANGED','tenant_user',v_user_id,v_idempotency_key,
    jsonb_build_object('action',v_action,'membership_role',v_membership_role,'role_key',v_role_key),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'tenant.user.role.changed',v_idempotency_key,
    jsonb_build_object('company_id',v_company_id,'user_id',v_user_id,'action',v_action));

  v_result:=jsonb_build_object('changed',true,'company_id',v_company_id,'user_id',v_user_id,
    'action',v_action,'membership_role',v_membership_role,'role_key',v_role_key);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'tenant.user_access.change',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_change_tenant_user_access_v2_unmapped(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access_v2_unmapped(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id', '')::uuid;
  v_idempotency_key text := p_command->>'idempotency_key';
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
begin
  if p_command ? 'staff_operation' then
    if not ('users.write'=any(public.gridex_staff_actor_permissions_v1(v_company_id,v_actor_user_id,p_command->>'channel'='ops'))) then
      raise exception 'staff_permission_denied';
    end if;
  elsif not public.canonical_actor_is_authorized(v_company_id, v_actor_user_id, 'tenant.user.manage', false) then
    raise exception 'actor_not_authorized_for_tenant_user_management';
  end if;
  if nullif(btrim(v_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text || ':tenant.user_access.change:' || v_idempotency_key, 0));
  v_hash := public.canonical_json_sha256(v_request);
  select * into v_existing from public.canonical_command_results
  where company_id = v_company_id and command_type = 'tenant.user_access.change'
    and idempotency_key = v_idempotency_key;
  if found then
    if v_existing.actor_user_id is distinct from v_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;
  v_result := public.canonical_change_tenant_user_access_v1_unchecked(p_command);
  update public.canonical_command_results set request_payload = v_request, request_hash = v_hash
  where company_id = v_company_id and command_type = 'tenant.user_access.change'
    and idempotency_key = v_idempotency_key;
  return v_result;
end;
$$;

--
-- Name: canonical_claim_company_provisioning_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_claim_company_provisioning_jobs(p_worker_id text, p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, company_id uuid, job_key text, idempotency_key text, attempt_count integer, max_attempts integer, lease_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'worker_id_required';
  end if;

  update public.company_provisioning_jobs job
  set status = case when job.attempt_count >= job.max_attempts then 'dead_letter' else 'retry' end,
      dead_letter_at = case when job.attempt_count >= job.max_attempts then coalesce(job.dead_letter_at, now()) else job.dead_letter_at end,
      available_at = case when job.attempt_count < job.max_attempts then now() else job.available_at end,
      last_error_code = 'stale_worker_lease',
      last_error_message = 'Provisioning worker lease expired before completion.',
      locked_at = null,
      locked_by = null,
      lease_token = null,
      updated_at = now()
  where job.status = 'processing'
    and job.locked_at < now() - make_interval(secs => greatest(30, least(p_lease_seconds, 3600)));

  return query
  with candidates as (
    select job.id
    from public.company_provisioning_jobs job
    join public.companies company on company.id = job.company_id
    where job.status in ('pending','retry')
      and job.available_at <= now()
      and job.attempt_count < job.max_attempts
      and company.status in ('onboarding','active')
      and (select decision.allowed
           from public.canonical_tenant_operation_decision(job.company_id, 'tenant.provisioning.execute') decision
           limit 1)
    order by job.available_at, job.created_at
    for update of job skip locked
    limit greatest(1, least(coalesce(p_limit, 20), 100))
  ), claimed as (
    update public.company_provisioning_jobs job
    set status = 'processing',
        attempt_count = job.attempt_count + 1,
        started_at = coalesce(job.started_at, now()),
        claimed_at = now(),
        locked_at = now(),
        locked_by = p_worker_id,
        lease_token = gen_random_uuid(),
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
    from candidates
    where job.id = candidates.id
    returning job.*
  )
  select claimed.id, claimed.company_id, claimed.job_key,
         claimed.idempotency_key, claimed.attempt_count,
         claimed.max_attempts, claimed.lease_token
  from claimed;
end
$$;

--
-- Name: canonical_command_request_hash_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_command_request_hash_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_hash text := public.canonical_json_sha256(coalesce(new.request_payload, '{}'::jsonb));
begin
  if new.request_hash is not null and new.request_hash <> v_hash then
    raise exception 'canonical_request_hash_mismatch';
  end if;
  new.request_hash := v_hash;
  return new;
end;
$$;

