--
-- Name: canonical_company_readiness(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_company_readiness(p_company_id uuid, p_configuration_snapshot_id uuid DEFAULT NULL::uuid, p_readiness_check_id uuid DEFAULT NULL::uuid, p_dry_run_id uuid DEFAULT NULL::uuid, p_target_state text DEFAULT 'prepared'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_status text;
  v_snapshot_id uuid;
  v_snapshot_hash text;
  v_latest_snapshot_id uuid;
  v_active_profile_count bigint;
  v_active_route_count bigint;
  v_check public.ediel_production_readiness_checks%rowtype;
  v_dry_run public.ediel_go_live_events%rowtype;
  v_blockers jsonb := '[]'::jsonb;
begin
  select status into v_company_status from public.companies where id = p_company_id;
  if not found then
    return jsonb_build_object('ready', false, 'company_id', p_company_id,
      'target_state', p_target_state, 'blockers', jsonb_build_array('tenant_not_found'));
  end if;

  if v_company_status <> 'active' then
    v_blockers := v_blockers || jsonb_build_array('tenant_not_active');
  end if;

  select id, configuration_hash into v_latest_snapshot_id, v_snapshot_hash
  from public.ediel_configuration_snapshots
  where company_id = p_company_id
  order by snapshot_version desc
  limit 1;
  v_snapshot_id := coalesce(p_configuration_snapshot_id, v_latest_snapshot_id);
  if v_snapshot_id is null then
    v_blockers := v_blockers || jsonb_build_array('configuration_snapshot_missing');
  elsif v_snapshot_id is distinct from v_latest_snapshot_id then
    v_blockers := v_blockers || jsonb_build_array('configuration_snapshot_stale');
  end if;

  select count(*) into v_active_profile_count
  from public.ediel_actor_settings
  where company_id = p_company_id and environment = 'production' and is_active = true
    and lower(coalesce(role, actor_role)) in ('supplier', 'electricity_supplier');
  if v_active_profile_count <> 1 then
    v_blockers := v_blockers || jsonb_build_array('production_profile_identity_ambiguous');
  elsif not exists (
    select 1 from public.canonical_ediel_profile_identities i
    join public.ediel_actor_settings a on a.id = i.profile_id
    where i.company_id = p_company_id and i.environment = 'production'
      and i.actor_role in ('supplier', 'electricity_supplier')
      and a.company_id = i.company_id and a.environment = i.environment
      and lower(coalesce(a.role, a.actor_role)) = i.actor_role
      and a.is_active = true
  ) then
    v_blockers := v_blockers || jsonb_build_array('production_profile_identity_missing');
  end if;

  select count(*) into v_active_route_count
  from public.ediel_route_profiles
  where company_id = p_company_id and environment = 'production'
    and coalesce(is_active, false) and coalesce(is_enabled, false);
  if v_active_route_count = 0 then
    v_blockers := v_blockers || jsonb_build_array('production_route_missing');
  end if;

  if p_readiness_check_id is null then
    v_blockers := v_blockers || jsonb_build_array('readiness_check_missing');
  else
    select * into v_check from public.ediel_production_readiness_checks
    where id = p_readiness_check_id and company_id = p_company_id;
    if not found
       or v_check.status not in ('ready', 'warning', 'live')
       or jsonb_array_length(coalesce(v_check.blocking_issues, '[]'::jsonb)) > 0
       or coalesce(v_check.is_stale, false)
       or v_check.configuration_snapshot_id is distinct from v_snapshot_id then
      v_blockers := v_blockers || jsonb_build_array('readiness_check_invalid_or_stale');
    end if;
  end if;

  if p_target_state = 'live' then
    if p_dry_run_id is null then
      v_blockers := v_blockers || jsonb_build_array('production_dry_run_missing');
    else
      select * into v_dry_run from public.ediel_go_live_events
      where id = p_dry_run_id and company_id = p_company_id
        and event_type = 'production_dry_run';
      if not found
         or v_dry_run.to_status not in ('allowed', 'warning')
         or coalesce(v_dry_run.is_stale, false)
         or v_dry_run.configuration_snapshot_id is distinct from v_snapshot_id
         or coalesce(v_dry_run.expires_at, v_dry_run.created_at + interval '24 hours') <= now() then
        v_blockers := v_blockers || jsonb_build_array('production_dry_run_invalid_or_stale');
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'ready', jsonb_array_length(v_blockers) = 0,
    'company_id', p_company_id,
    'company_status', v_company_status,
    'target_state', p_target_state,
    'configuration_snapshot_id', v_snapshot_id,
    'configuration_hash', v_snapshot_hash,
    'readiness_check_id', p_readiness_check_id,
    'dry_run_id', p_dry_run_id,
    'active_production_profiles', v_active_profile_count,
    'active_production_routes', v_active_route_count,
    'blockers', v_blockers
  );
end;
$$;

--
-- Name: FUNCTION canonical_company_readiness(p_company_id uuid, p_configuration_snapshot_id uuid, p_readiness_check_id uuid, p_dry_run_id uuid, p_target_state text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_company_readiness(p_company_id uuid, p_configuration_snapshot_id uuid, p_readiness_check_id uuid, p_dry_run_id uuid, p_target_state text) IS 'Read-only canonical production gate. Never creates snapshots or readiness evidence.';

--
-- Name: canonical_complete_company_provisioning_job(uuid, uuid, boolean, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_complete_company_provisioning_job(p_job_id uuid, p_lease_token uuid, p_succeeded boolean, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_error_details jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_previous_dead_letter_at timestamptz;
  v_result jsonb;
begin
  select dead_letter_at into v_previous_dead_letter_at
  from public.company_provisioning_jobs
  where id=p_job_id
  for update;

  v_result := public.canonical_complete_company_provisioning_job_v1_pre_history_guard(
    p_job_id,p_lease_token,p_succeeded,p_error_code,p_error_message,p_error_details
  );

  if v_previous_dead_letter_at is not null then
    update public.company_provisioning_jobs
    set dead_letter_at=v_previous_dead_letter_at
    where id=p_job_id and dead_letter_at is null;
  end if;
  return v_result;
end
$$;

--
-- Name: canonical_complete_company_provisioning_job_v1_pre_history_guar(uuid, uuid, boolean, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_complete_company_provisioning_job_v1_pre_history_guar(p_job_id uuid, p_lease_token uuid, p_succeeded boolean, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_error_details jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.company_provisioning_jobs%rowtype;
  v_status text;
  v_delay_seconds integer;
begin
  select * into v_job
  from public.company_provisioning_jobs
  where id = p_job_id
  for update;
  if not found then raise exception 'provisioning_job_not_found'; end if;
  if v_job.status <> 'processing' or v_job.lease_token is distinct from p_lease_token then
    raise exception 'provisioning_job_lease_conflict';
  end if;

  if p_succeeded then
    v_status := 'completed';
  elsif v_job.attempt_count >= v_job.max_attempts then
    v_status := 'dead_letter';
  else
    v_status := 'retry';
  end if;
  v_delay_seconds := least(3600, 30 * (2 ^ greatest(v_job.attempt_count - 1, 0))::integer);

  update public.company_provisioning_jobs
  set status = v_status,
      completed_at = case when p_succeeded then now() else completed_at end,
      dead_letter_at = case when v_status = 'dead_letter' then now() else null end,
      available_at = case when v_status = 'retry' then now() + make_interval(secs => v_delay_seconds) else available_at end,
      last_error_code = case when p_succeeded then null else coalesce(nullif(p_error_code, ''), 'provisioning_job_failed') end,
      last_error_message = case when p_succeeded then null else left(coalesce(p_error_message, 'Provisioning job failed.'), 1000) end,
      last_error_details = case when p_succeeded then '{}'::jsonb else coalesce(p_error_details, '{}'::jsonb) end,
      locked_at = null,
      locked_by = null,
      lease_token = null,
      updated_at = now()
  where id = p_job_id;

  return jsonb_build_object(
    'job_id', p_job_id,
    'status', v_status,
    'attempt_count', v_job.attempt_count,
    'max_attempts', v_job.max_attempts
  );
end
$$;

--
-- Name: canonical_create_tenant_invitation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_create_tenant_invitation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_actor_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_key text := p_command->>'idempotency_key';
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
BEGIN
  IF NOT (p_command ? 'staff_operation') THEN RETURN public.canonical_create_tenant_invitation_pre_staff_v1(p_command); END IF;
  IF p_command->>'staff_operation'<>'invite' THEN RAISE EXCEPTION 'staff_invalid_operation'; END IF;
  IF nullif(btrim(v_key),'') IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_company_id::text||':tenant.invitation.create:'||v_key,0));
  PERFORM 1 FROM public.companies WHERE id=v_company_id FOR NO KEY UPDATE;
  SELECT * INTO v_existing FROM public.canonical_command_results
  WHERE company_id=v_company_id AND command_type='tenant.invitation.create' AND idempotency_key=v_key;
  IF FOUND THEN
    IF v_existing.actor_user_id IS DISTINCT FROM v_actor_id THEN RAISE EXCEPTION 'idempotency_actor_mismatch'; END IF;
    IF v_existing.request_hash IS DISTINCT FROM public.canonical_json_sha256(p_command-'actor_user_id') THEN RAISE EXCEPTION 'idempotency_key_payload_mismatch'; END IF;
    PERFORM public.gridex_assert_staff_command_v1(p_command,true);
    RETURN v_existing.result_payload;
  END IF;
  PERFORM public.gridex_assert_staff_command_v1(p_command);
  v_result := public.canonical_create_tenant_invitation_pre_staff_v1(p_command);
  UPDATE public.canonical_command_results SET request_payload=p_command-'actor_user_id',request_hash=public.canonical_json_sha256(p_command-'actor_user_id')
  WHERE company_id=v_company_id AND command_type='tenant.invitation.create' AND idempotency_key=v_key;
  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,new_values,metadata,
    actor_type,request_id,correlation_id,resource_type,resource_id)
  VALUES(v_company_id,v_actor_id,'company_invitation',v_result->>'invitation_id','STAFF_INVITED',
    jsonb_build_object('status','pending','role_key',p_command->>'role_key'),
    jsonb_build_object('channel',p_command->>'channel','api_client_id',p_command->>'api_client_id'),
    'user',v_key,v_key,'staff_invitation',v_result->>'invitation_id');
  RETURN v_result;
END;
$$;

--
-- Name: canonical_create_tenant_invitation_pre_staff_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_create_tenant_invitation_pre_staff_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_email text := lower(btrim(p_command->>'email'));
  v_idempotency_key text := btrim(p_command->>'idempotency_key');
  v_token uuid;
  v_invitation_id uuid;
  v_existing jsonb;
  v_event_id uuid;
  v_result jsonb;
begin
  if v_company_id is null or nullif(v_email,'') is null or nullif(v_idempotency_key,'') is null then
    raise exception 'company_email_and_idempotency_key_required';
  end if;
  if p_command ? 'staff_operation' then
    if not ('users.write'=any(public.gridex_staff_actor_permissions_v1(v_company_id,v_actor_user_id,p_command->>'channel'='ops'))) then
      raise exception 'staff_permission_denied';
    end if;
  elsif not (
    public.canonical_actor_is_authorized(v_company_id,v_actor_user_id,'tenants.invite',false)
    or public.canonical_actor_is_authorized(v_company_id,v_actor_user_id,'users.write',false)
  ) then
    raise exception using errcode='42501', message='actor_not_authorized_for_tenant_invitation';
  end if;

  select result_payload into v_existing
  from public.canonical_command_results
  where company_id=v_company_id
    and command_type='tenant.invitation.create'
    and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  v_token := gen_random_uuid();
  insert into public.company_invitations(
    company_id,email,full_name,membership_role,role_key,status,token,
    invited_by,expires_at,accept_token_hash,idempotency_key,metadata
  ) values (
    v_company_id,v_email,nullif(btrim(p_command->>'full_name'),''),
    coalesce(nullif(lower(btrim(p_command->>'membership_role')),''),'member'),
    coalesce(nullif(lower(btrim(p_command->>'role_key')),''),'member'),
    'pending',v_token,v_actor_user_id,now()+interval '14 days',
    encode(digest(v_token::text,'sha256'),'hex'),v_idempotency_key,
    jsonb_build_object(
      'invite_source',coalesce(nullif(p_command->>'source',''),'canonical_invitation'),
      'access_source','verified_auth_invitation_link',
      'provider_delivery_status','pending'
    )
  )
  returning id into v_invitation_id;

  insert into public.company_provisioning_jobs(company_id,job_key,idempotency_key)
  values(v_company_id,'auth_invite',v_idempotency_key)
  on conflict(company_id,job_key,idempotency_key) do nothing;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,
    idempotency_key,after_state
  ) values (
    v_company_id,'TENANT_INVITATION_CREATED','company_invitation',v_invitation_id,
    v_actor_user_id,'Durable invitation intent created before provider delivery.',
    v_idempotency_key,jsonb_build_object('status','pending','role_key',p_command->>'role_key')
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'TENANT_INVITATION_CREATED','company_invitation',v_invitation_id,
    v_idempotency_key,jsonb_build_object('invitation_id',v_invitation_id,'status','pending'),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'tenant.invitation.created',v_idempotency_key,
    jsonb_build_object('invitation_id',v_invitation_id));

  v_result := jsonb_build_object(
    'invitation_id',v_invitation_id,
    'company_id',v_company_id,
    'token',v_token,
    'status','pending'
  );
  insert into public.canonical_command_results(
    company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id
  ) values (
    v_company_id,'tenant.invitation.create',v_idempotency_key,
    p_command - 'email',v_result,v_actor_user_id
  );
  return v_result;
end
$$;

