--
-- Name: ediel_archive_regulated_supply_ground_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_regulated_supply_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE v_scope jsonb;selector jsonb;bytes bytea;v_hash text;v_scope_hash text;rh text;a gridex_regulated_supply.artifacts%rowtype;
BEGIN
 IF gridex_regulated_supply.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'regulated_supply_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission) k WHERE k NOT IN('environment','kind','contractId','meteringPointId','identityAgency','bilateralAgreementId','startAt','consumptionSupplyPeriodId','source','issuerReceipt')) OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'source') k WHERE k NOT IN('bytesBase64','mimeType','reference','version')) THEN RAISE EXCEPTION 'regulated_supply_archive_shape_required';END IF;
 selector:=p_submission-ARRAY['source','issuerReceipt'];v_scope:=gridex_regulated_supply.scope_v1(p_company_id,selector);
 IF v_scope IS NULL THEN RETURN jsonb_build_object('status','held','companyId',p_company_id,'missing',ARRAY['actual_current_own_contract_point_legal_registry_and_bilateral_scope']);END IF;
 IF length(coalesce(p_submission#>>'{source,bytesBase64}',''))>11184812 THEN RAISE EXCEPTION 'regulated_supply_archive_bytes_limit';END IF;bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');
 IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR (p_submission#>>'{source,mimeType}' IN('application/pdf','text/plain','application/json')) IS NOT TRUE OR p_submission#>>'{source,mimeType}'='application/pdf' AND substring(bytes,1,5)<>decode('255044462d','hex')
 OR p_submission#>>'{source,reference}' IS DISTINCT FROM v_scope#>>'{agreementBinding,source_reference}' OR nullif(p_submission#>>'{source,version}','') IS NULL OR length(p_submission#>>'{source,version}')>200 THEN RAISE EXCEPTION 'regulated_supply_archive_actual_bytes_reference_version_required';END IF;
 v_hash:=encode(sha256(bytes),'hex');v_scope_hash:=encode(sha256(convert_to(v_scope::text,'UTF8')),'hex');rh:=encode(sha256(convert_to(coalesce(p_submission->'issuerReceipt','null'::jsonb)::text,'UTF8')),'hex');
 SELECT * INTO a FROM gridex_regulated_supply.artifacts WHERE company_id=p_company_id AND environment=v_scope->>'environment' AND scope_hash=v_scope_hash AND source_hash=v_hash AND receipt_hash=rh;
 IF FOUND THEN IF a.source_reference IS DISTINCT FROM p_submission#>>'{source,reference}' OR a.source_version IS DISTINCT FROM p_submission#>>'{source,version}' THEN RAISE EXCEPTION 'regulated_supply_archive_original_conflict';END IF;
 ELSE INSERT INTO gridex_regulated_supply.artifacts(company_id,environment,selector,scope,scope_hash,source_bytes,source_hash,mime_type,source_reference,source_version,issuer_receipt,receipt_hash,submitted_by)
 VALUES(p_company_id,v_scope->>'environment',selector,v_scope,v_scope_hash,bytes,v_hash,p_submission#>>'{source,mimeType}',p_submission#>>'{source,reference}',p_submission#>>'{source,version}',p_submission->'issuerReceipt',rh,p_actor_user_id) RETURNING * INTO a;END IF;
 RETURN jsonb_build_object('status','archived','companyId',p_company_id,'artifactId',a.id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'missing',ARRAY['separate_qualified_source_review_required']);
END$$;

--
-- Name: ediel_archive_requested_change_source_before_scope_fence_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_requested_change_source_before_scope_fence_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c public.customer_contracts%rowtype;u public.customers%rowtype;mp public.metering_points%rowtype;sp public.customer_supply_periods%rowtype;m public.ediel_messages%rowtype;supply jsonb;bytes bytea;hash text;claims jsonb;ch text;kind text;at timestamptz;sender text;brp text;tokens jsonb;a gridex_requested_changes.artifacts%rowtype;missing jsonb:='["separate_source_review_required"]';
BEGIN
 kind:=p_submission->>'kind';IF (kind IN('death','quarter_contract','method_contract')) IS NOT TRUE OR gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'archive',kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission)<>'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission) k WHERE k NOT IN('supplyPeriodId','contractId','kind','effectiveAt','source','customerIdentity','invoiceeProfile','issuerReceipt')) OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'source') k WHERE k NOT IN('bytesBase64','mimeType','reference','version')) THEN RAISE EXCEPTION 'requested_change_archive_shape_required';END IF;
 IF length(coalesce(p_submission#>>'{source,bytesBase64}',''))>11184812 THEN RAISE EXCEPTION 'requested_change_source_bytes_limit';END IF;bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');hash:=encode(sha256(bytes),'hex');at:=(p_submission->>'effectiveAt')::timestamptz;
 IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR (p_submission#>>'{source,mimeType}' IN('application/pdf','text/plain','application/json')) IS NOT TRUE OR nullif(p_submission#>>'{source,reference}','') IS NULL OR length(p_submission#>>'{source,reference}')>2000 OR nullif(p_submission#>>'{source,version}','') IS NULL OR length(p_submission#>>'{source,version}')>200 OR NOT isfinite(at) OR extract(second FROM at)<>0 OR p_submission#>>'{source,mimeType}'='application/pdf' AND substring(bytes,1,5)<>decode('255044462d','hex') THEN RAISE EXCEPTION 'requested_change_source_bytes_or_minute_invalid';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=(p_submission->>'supplyPeriodId')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=(p_submission->>'contractId')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO u FROM public.customers WHERE id=sp.customer_id AND company_id=p_company_id FOR SHARE;SELECT * INTO mp FROM public.metering_points WHERE id=sp.metering_point_id AND company_id=p_company_id FOR SHARE;
 supply:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,sp.id,at,at+interval '1 minute');
 IF sp.id IS NULL OR c.id IS NULL OR u.id IS NULL OR mp.id IS NULL OR c.customer_id IS DISTINCT FROM sp.customer_id OR c.metering_point_id IS DISTINCT FROM sp.metering_point_id OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM u.id::text OR supply->>'meteringPointId' IS DISTINCT FROM mp.id::text THEN RAISE EXCEPTION 'requested_change_archive_owned_current_supply_contract_required';END IF;
 SELECT identifier_value INTO sender FROM public.tenant_actor_identifiers WHERE company_id=p_company_id AND environment=supply->>'environment' AND actor_id=(supply->>'legalActorId')::uuid AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()) ORDER BY id LIMIT 1 FOR SHARE;
 -- The source owner may omit environment in older approved supply snapshots;
 -- it is always taken from the actual initial received original, never input.
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND id=(supply->>'initialSourceMessageId')::uuid FOR SHARE;
 IF sender IS NULL THEN SELECT identifier_value INTO sender FROM public.tenant_actor_identifiers WHERE company_id=p_company_id AND environment=m.environment AND actor_id=(supply->>'legalActorId')::uuid AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()) ORDER BY id LIMIT 1 FOR SHARE;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);SELECT t#>>'{elements,2,0}' INTO brp FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK';
 IF sender IS NULL OR brp IS NULL OR (SELECT count(*) FROM jsonb_array_elements(supply->'sourceObjects') x WHERE x->>'point'=mp.ediel_metering_point_id AND x->>'identityAgency' IN('9','89'))<>1 THEN RAISE EXCEPTION 'requested_change_archive_physical_original_identity_required';END IF;
 claims:=jsonb_build_object('kind',kind,'effectiveAt',at,'customerIdentity',p_submission->'customerIdentity','invoiceeProfile',p_submission->'invoiceeProfile');ch:=encode(sha256(convert_to(claims::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('requested_change_archive:'||p_company_id::text||hash||ch,0));
 SELECT * INTO a FROM gridex_requested_changes.artifacts WHERE company_id=p_company_id AND environment=m.environment AND source_hash=hash AND claims_hash=ch FOR SHARE;
 IF FOUND THEN IF a.supply_period_id IS DISTINCT FROM sp.id OR a.contract_id IS DISTINCT FROM c.id OR a.source_reference IS DISTINCT FROM p_submission#>>'{source,reference}' OR a.source_version IS DISTINCT FROM p_submission#>>'{source,version}' OR a.issuer_receipt IS DISTINCT FROM p_submission->'issuerReceipt' THEN RAISE EXCEPTION 'requested_change_archive_original_conflict';END IF;
 ELSE INSERT INTO gridex_requested_changes.artifacts(company_id,environment,supply_period_id,contract_id,customer_id,metering_point_id,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,brp_ediel_id,supply_source_message_id,supply_state_version,protected_contract_hash,customer_snapshot_hash,kind,effective_at,source_bytes,source_hash,mime_type,source_reference,source_version,claims,claims_hash,issuer_receipt,submitted_by)
 VALUES(p_company_id,m.environment,sp.id,c.id,u.id,mp.id,(supply->>'legalActorId')::uuid,sender,supply->>'dsoEdielId',mp.ediel_metering_point_id,(SELECT x->>'identityAgency' FROM jsonb_array_elements(supply->'sourceObjects') x WHERE x->>'point'=mp.ediel_metering_point_id),mp.grid_area_code,brp,(supply->>'sourceMessageId')::uuid,(supply->>'marketStateVersion')::bigint,gridex_received_sources.production_contract_hash_v1(c),encode(sha256(convert_to((to_jsonb(u)-'updated_at')::text,'UTF8')),'hex'),kind,at,bytes,hash,p_submission#>>'{source,mimeType}',p_submission#>>'{source,reference}',p_submission#>>'{source,version}',claims,ch,p_submission->'issuerReceipt',p_actor_user_id) RETURNING * INTO a;END IF;
 IF kind='death' AND gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN missing:=missing||'"authentic_current_issuer_and_representation_receipt"'::jsonb;END IF;
 RETURN jsonb_build_object('status','archived','artifactId',a.id,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'missing',missing);
END$$;

--
-- Name: ediel_archive_requested_change_source_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_requested_change_source_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();RETURN public.ediel_archive_requested_change_source_before_scope_fence_v1(p_company_id,p_actor_user_id,p_submission);END$$;

--
-- Name: ediel_archive_requested_customer_change_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_requested_customer_change_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_customer_changes.artifacts%rowtype;captured_claims jsonb;bytes bytea;hash text;ch text;missing jsonb:='[]';BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'requested_customer_change_service_required' USING ERRCODE='42501';END IF;
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'archive','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission)k WHERE k NOT IN('environment','agreementId','supplyPeriodId','contractId','rawPayload','source','issuerReceipt')) OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'source')k WHERE k NOT IN('bytesBase64','mimeType','reference','version')) OR length(coalesce(p_submission#>>'{source,bytesBase64}','')) NOT BETWEEN 1 AND 11184812 OR p_submission#>>'{source,mimeType}' IS DISTINCT FROM 'application/pdf' OR nullif(p_submission#>>'{source,reference}','') IS NULL OR length(p_submission#>>'{source,reference}')>2000 OR nullif(p_submission#>>'{source,version}','') IS NULL OR length(p_submission#>>'{source,version}')>200 THEN RAISE EXCEPTION 'requested_customer_change_archive_shape_required';END IF;
 bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR replace(encode(bytes,'base64'),E'\n','') IS DISTINCT FROM p_submission#>>'{source,bytesBase64}' OR substring(bytes,1,5)<>decode('255044462d','hex') THEN RAISE EXCEPTION 'requested_customer_change_original_pdf_required';END IF;
 captured_claims:=gridex_requested_customer_changes.source_claims_v1(p_company_id,p_submission->>'environment',(p_submission->>'agreementId')::uuid,(p_submission->>'supplyPeriodId')::uuid,(p_submission->>'contractId')::uuid,p_submission->>'rawPayload');hash:=encode(sha256(bytes),'hex');ch:=encode(sha256(convert_to(captured_claims::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('requested_customer_change_archive:'||p_company_id::text||hash||ch,0));
 SELECT * INTO a FROM gridex_requested_customer_changes.artifacts WHERE company_id=p_company_id AND environment=captured_claims->>'environment' AND source_hash=hash AND claims_hash=ch FOR SHARE;
 IF FOUND THEN IF a.raw_payload IS DISTINCT FROM p_submission->>'rawPayload' OR a.source_reference IS DISTINCT FROM p_submission#>>'{source,reference}' OR a.source_version IS DISTINCT FROM p_submission#>>'{source,version}' OR a.issuer_receipt IS DISTINCT FROM p_submission->'issuerReceipt' THEN RAISE EXCEPTION 'requested_customer_change_original_conflict';END IF;
 ELSE
  IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'archive','method_contract') IS NOT TRUE OR captured_claims IS DISTINCT FROM gridex_requested_customer_changes.source_claims_v1(p_company_id,captured_claims->>'environment',(p_submission->>'agreementId')::uuid,(p_submission->>'supplyPeriodId')::uuid,(p_submission->>'contractId')::uuid,p_submission->>'rawPayload') THEN RAISE EXCEPTION 'requested_customer_change_post_wait_archive_actor_or_source_forbidden' USING ERRCODE='42501';END IF;
  INSERT INTO gridex_requested_customer_changes.artifacts(company_id,environment,agreement_id,supply_period_id,contract_id,raw_payload,claims,claims_hash,source_bytes,source_hash,source_reference,source_version,issuer_receipt,submitted_by)VALUES(p_company_id,captured_claims->>'environment',(p_submission->>'agreementId')::uuid,(p_submission->>'supplyPeriodId')::uuid,(p_submission->>'contractId')::uuid,p_submission->>'rawPayload',captured_claims,ch,bytes,hash,p_submission#>>'{source,reference}',p_submission#>>'{source,version}',p_submission->'issuerReceipt',p_actor_user_id) RETURNING * INTO a;END IF;
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'archive','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_post_wait_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF a.claims->>'supplyQualified' IS DISTINCT FROM 'true' THEN missing:='["current_owned_supply_source_required"]';ELSIF gridex_requested_customer_changes.receipt_current_v1(a) IS NULL THEN missing:='["authentic_current_outgoing_customer_mandate"]';END IF;
 RETURN jsonb_build_object('status','archived','artifactId',a.id,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'missing',missing);END$$;

--
-- Name: ediel_archive_service_evidence_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_service_evidence_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE a public.ediel_service_assignments%rowtype;bytes bytea;archive gridex_ediel_services.artifacts%rowtype;terms_record public.ediel_service_evidence%rowtype;terms jsonb;v_scope jsonb;sh text;v_source_hash text;kind text;missing jsonb:='["separate_qualified_reviewer_required"]';
BEGIN
 PERFORM gridex_service_permission.lock_request_writer_v1();
 IF gridex_ediel_services.actor_current_v1(p_company_id,p_actor_user_id,false) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission) x WHERE x NOT IN('assignmentId','scopeBasisVersion','kind','source','terms','issuerReceipt','transportRelationId','transportActorId'))
 OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'source') x WHERE x NOT IN('bytesBase64','mimeType','reference','version')) THEN RAISE EXCEPTION 'ediel_service_archive_shape_invalid';END IF;
 IF jsonb_typeof(p_submission->'terms') IS DISTINCT FROM 'object' OR NOT(p_submission->'terms' ? 'valid_from' AND p_submission->'terms' ? 'valid_to') OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'terms') x WHERE x NOT IN('valid_from','valid_to','permission_agreement_reference','permission_requested_method','permission_network_contract_start','permission_network_contract_end','permission_purpose_code','permission_reporting_frequency','permission_request_grid_area','permission_reporting_term_kind','permission_customer_classification','permission_termination_reason','permission_termination_at')) THEN RAISE EXCEPTION 'ediel_service_archive_evidence_terms_required';END IF;
 IF EXISTS(SELECT FROM jsonb_each(p_submission->'terms') x WHERE x.key IN('permission_network_contract_start','permission_network_contract_end') AND x.value<>'null'::jsonb AND (jsonb_typeof(x.value)<>'string' OR x.value#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) THEN RAISE EXCEPTION 'ediel_service_archive_network_period_invalid';END IF;
 terms_record:=jsonb_populate_record(NULL::public.ediel_service_evidence,p_submission->'terms');terms:=gridex_ediel_services.evidence_terms_v1(terms_record);
 IF (terms_record.permission_agreement_reference IS NOT NULL AND (terms_record.permission_agreement_reference<>btrim(terms_record.permission_agreement_reference) OR length(terms_record.permission_agreement_reference) NOT BETWEEN 1 AND 35)) OR (terms_record.permission_requested_method IS NOT NULL AND gridex_metering_method_changes.requested_method_supported_v1(terms_record.permission_requested_method) IS NOT TRUE) THEN RAISE EXCEPTION 'ediel_service_archive_source_permission_terms_invalid';END IF;
 IF (terms_record.permission_network_contract_start IS NOT NULL AND NOT isfinite(terms_record.permission_network_contract_start)) OR (terms_record.permission_network_contract_end IS NOT NULL AND (NOT isfinite(terms_record.permission_network_contract_end) OR terms_record.permission_network_contract_start IS NULL OR terms_record.permission_network_contract_end<terms_record.permission_network_contract_start)) THEN RAISE EXCEPTION 'ediel_service_archive_network_period_invalid';END IF;
 IF terms_record.valid_from IS NULL OR NOT isfinite(terms_record.valid_from) OR (terms_record.valid_to IS NOT NULL AND (NOT isfinite(terms_record.valid_to) OR terms_record.valid_to<=terms_record.valid_from)) THEN RAISE EXCEPTION 'ediel_service_archive_evidence_terms_invalid';END IF;
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=(p_submission->>'assignmentId')::uuid;
 IF a.id IS NULL OR a.scope_basis_version IS DISTINCT FROM (p_submission->>'scopeBasisVersion')::bigint OR a.scope_basis_version IS NULL THEN RAISE EXCEPTION 'ediel_service_archive_current_scope_required';END IF;
 v_scope:=gridex_service_administration.scope_v1(a);sh:=encode(sha256(convert_to(v_scope::text,'UTF8')),'hex');
 IF NOT EXISTS(SELECT FROM gridex_service_administration.scope_versions s WHERE s.company_id=a.company_id AND s.assignment_id=a.id AND s.scope_basis_version=a.scope_basis_version AND s.scope=v_scope) THEN RAISE EXCEPTION 'ediel_service_archive_authentic_scope_required';END IF;
 bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');kind:=p_submission->>'kind';v_source_hash:=encode(sha256(bytes),'hex');
 IF kind IS DISTINCT FROM 'dso_contract' AND (terms_record.permission_network_contract_start IS NOT NULL OR terms_record.permission_network_contract_end IS NOT NULL) THEN RAISE EXCEPTION 'ediel_service_archive_network_period_kind_invalid';END IF;
 IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR substring(bytes,1,5)<>decode('255044462d','hex') OR p_submission#>>'{source,mimeType}' IS DISTINCT FROM 'application/pdf'
 OR nullif(p_submission#>>'{source,reference}','') IS NULL OR length(p_submission#>>'{source,reference}')>2000 OR nullif(p_submission#>>'{source,version}','') IS NULL OR length(p_submission#>>'{source,version}')>200 THEN RAISE EXCEPTION 'ediel_service_archive_bytes_invalid';END IF;
 IF kind='transport_mandate' THEN
  IF NOT EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=a.company_id AND r.id=(p_submission->>'transportRelationId')::uuid AND r.counterparty_actor_id=(p_submission->>'transportActorId')::uuid AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to)) THEN RAISE EXCEPTION 'ediel_service_archive_transport_relation_required';END IF;
 ELSIF p_submission->>'transportRelationId' IS NOT NULL OR p_submission->>'transportActorId' IS NOT NULL THEN RAISE EXCEPTION 'ediel_service_archive_transport_scope_invalid';END IF;
 SELECT * INTO archive FROM gridex_ediel_services.artifacts x WHERE x.company_id=a.company_id AND x.environment=a.environment AND x.assignment_id=a.id AND x.scope_basis_version=a.scope_basis_version AND x.evidence_kind=kind AND x.source_hash=v_source_hash AND x.source_reference=p_submission#>>'{source,reference}' AND x.source_version=p_submission#>>'{source,version}';
 IF FOUND THEN
  IF archive.evidence_terms IS DISTINCT FROM terms OR archive.issuer_receipt IS DISTINCT FROM p_submission->'issuerReceipt' OR archive.transport_relation_id IS DISTINCT FROM (p_submission->>'transportRelationId')::uuid OR archive.transport_actor_id IS DISTINCT FROM (p_submission->>'transportActorId')::uuid THEN RAISE EXCEPTION 'ediel_service_archive_receipt_conflict';END IF;
 ELSE
  INSERT INTO gridex_ediel_services.artifacts(company_id,environment,assignment_id,scope_basis_version,scope,scope_hash,evidence_kind,transport_relation_id,transport_actor_id,evidence_terms,source_bytes,source_hash,mime_type,source_reference,source_version,issuer_receipt,submitted_by)
  VALUES(a.company_id,a.environment,a.id,a.scope_basis_version,v_scope,sh,kind,(p_submission->>'transportRelationId')::uuid,(p_submission->>'transportActorId')::uuid,terms,bytes,v_source_hash,'application/pdf',p_submission#>>'{source,reference}',p_submission#>>'{source,version}',p_submission->'issuerReceipt',p_actor_user_id) RETURNING * INTO archive;
 END IF;
 IF gridex_ediel_services.receipt_current_v1(archive) IS NOT TRUE THEN missing:=missing||'"authentic_current_issuer_and_representation_receipt"'::jsonb;END IF;
 RETURN jsonb_build_object('status','archived','companyId',archive.company_id,'assignmentId',archive.assignment_id,'artifactId',archive.id,'sourceHash',archive.source_hash,'scopeHash',archive.scope_hash,'scopeBasisVersion',archive.scope_basis_version,'missing',missing);
END $_$;

--
-- Name: ediel_archive_signed_brp_declaration_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_signed_brp_declaration_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE terminal_result jsonb;terminal_kind text;
BEGIN
 terminal_result:=gridex_brp_declaration_intake.terminal_archive_body_v1(p_company_id,p_actor_user_id,p_submission);
 IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_terminal_actor_revoked' USING ERRCODE='42501';END IF;
 RETURN terminal_result;
END$$;

--
-- Name: ediel_archive_supply_rescission_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_archive_supply_rescission_v1(p_company_id uuid, p_actor_user_id uuid, p_submission jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE gridex_intake_session_result_v1 jsonb; selector jsonb;v_scope jsonb;bytes bytea;hash text;rh text;a gridex_supply_rescission.artifacts%rowtype;BEGIN PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'archive');
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission) IS DISTINCT FROM 'object' OR p_submission-ARRAY['environment','supplyPeriodId','effectiveAt','rulePackId','source','issuerReceipt']<>'{}'::jsonb OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR (p_submission->'source')-ARRAY['bytesBase64','mimeType','reference','version']<>'{}'::jsonb THEN RAISE EXCEPTION 'supply_rescission_archive_shape_required';END IF;
 selector:=p_submission-ARRAY['source','issuerReceipt'];v_scope:=gridex_supply_rescission.scope_v1(p_company_id,selector);IF v_scope IS NULL THEN gridex_intake_session_result_v1 := jsonb_build_object('status','held','companyId',p_company_id,'missing',ARRAY['actual_current_own_supply_signed_contract_and_national_source_grammar']); PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'archive'); RETURN gridex_intake_session_result_v1;END IF;
 bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');hash:=encode(sha256(bytes),'hex');rh:=encode(sha256(convert_to(coalesce(p_submission->'issuerReceipt','null')::text,'UTF8')),'hex');
 IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR p_submission#>>'{source,mimeType}' NOT IN('application/pdf','text/plain') OR nullif(btrim(p_submission#>>'{source,reference}'),'') IS NULL OR length(p_submission#>>'{source,reference}')>2000 OR nullif(btrim(p_submission#>>'{source,version}'),'') IS NULL OR length(p_submission#>>'{source,version}')>200 THEN RAISE EXCEPTION 'supply_rescission_original_bytes_reference_required';END IF;
 SELECT * INTO a FROM gridex_supply_rescission.artifacts WHERE company_id=p_company_id AND environment=v_scope->>'environment' AND scope_hash=encode(sha256(convert_to(v_scope::text,'UTF8')),'hex') AND source_hash=hash AND receipt_hash=rh;
 IF a.id IS NULL THEN INSERT INTO gridex_supply_rescission.artifacts(company_id,environment,selector,scope,scope_hash,source_bytes,source_hash,mime_type,source_reference,source_version,issuer_receipt,receipt_hash,submitted_by) VALUES(p_company_id,v_scope->>'environment',selector,v_scope,encode(sha256(convert_to(v_scope::text,'UTF8')),'hex'),bytes,hash,p_submission#>>'{source,mimeType}',p_submission#>>'{source,reference}',p_submission#>>'{source,version}',p_submission->'issuerReceipt',rh,p_actor_user_id) RETURNING * INTO a;END IF;
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_post_write_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 gridex_intake_session_result_v1 := jsonb_build_object('status','archived','companyId',p_company_id,'artifactId',a.id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'missing',ARRAY['authentic_legal_rescission_issuer_and_separate_qualified_review']); PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'archive'); RETURN gridex_intake_session_result_v1;
END$$;

--
-- Name: ediel_begin_blob_purge_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_begin_blob_purge_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.blob_decisions%rowtype;t gridex_ediel_retention.blob_tombstones%rowtype;basis jsonb;r uuid;at timestamptz:=clock_timestamp();BEGIN
 PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');
 LOCK TABLE public.ediel_message_payloads IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.blob_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,d.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required';END IF;PERFORM id FROM public.ediel_messages WHERE id=d.message_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO t FROM gridex_ediel_retention.blob_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id;
 IF FOUND THEN IF t.decision_id IS DISTINCT FROM d.id THEN RAISE EXCEPTION 'blob_retention_tombstone_conflict';END IF;RETURN jsonb_build_object('status',CASE WHEN t.retention_class='received_ediel_message_content' OR EXISTS(SELECT FROM gridex_ediel_retention.blob_events e WHERE e.retention_class=t.retention_class AND e.target_id=t.target_id AND e.kind='physical_bytes_removed') THEN 'purged' ELSE 'storage_purge_pending' END,'targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'storagePath',t.storage_path,'replay',true);END IF;
 r:=gridex_ediel_retention.blob_current_v1(d);IF r IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_blob_class_legal_review_deadline']);END IF;
 basis:=gridex_ediel_retention.blob_basis_v1(p_company_id,d.retention_class,d.target_id);IF basis->>'targetHash' IS DISTINCT FROM d.target_hash OR basis->>'sourceHash' IS DISTINCT FROM d.source_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_native_blob_target_changed']);END IF;
 INSERT INTO gridex_ediel_retention.blob_tombstones(retention_class,target_id,company_id,message_id,decision_id,review_id,source_hash,target_hash,public_content_hash,byte_length,storage_path,actor_user_id,created_at) VALUES(d.retention_class,d.target_id,d.company_id,d.message_id,d.id,r,d.source_hash,d.target_hash,basis->>'publicContentHash',(basis->>'byteLength')::bigint,basis->>'storagePath',p_actor_user_id,at);
 IF d.retention_class='received_ediel_message_content' THEN
  UPDATE gridex_received_sources.sources SET raw_payload=NULL,retention_purged_at=at WHERE source_message_id=d.target_id AND company_id=p_company_id;
  UPDATE public.ediel_message_payloads SET raw_payload=NULL,encrypted_payload=NULL WHERE company_id=p_company_id AND ediel_message_id=d.message_id;
  UPDATE public.ediel_messages SET raw_payload=NULL,parsed_payload='{}',validation_report='{}',metadata='{}' WHERE id=d.message_id AND company_id=p_company_id;
 END IF;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_message',d.message_id,'ediel.retention.blob_tombstoned',jsonb_build_object('decisionId',d.id,'targetId',d.target_id,'sourceHash',d.source_hash,'retentionClass',d.retention_class,'purgedAt',at));RETURN jsonb_build_object('status',CASE WHEN d.retention_class='received_ediel_message_content' THEN 'purged' ELSE 'storage_purge_pending' END,'targetId',d.target_id,'sourceHash',d.source_hash,'byteLength',(basis->>'byteLength')::bigint,'storagePath',basis->>'storagePath','replay',false);
END$$;

--
-- Name: ediel_begin_customer_record_retention_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_begin_customer_record_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE d gridex_ediel_retention.record_decisions%rowtype;t gridex_ediel_retention.record_tombstones%rowtype;spec gridex_ediel_retention.record_class_catalog%rowtype;basis jsonb;claims jsonb;r uuid;customer public.customers%rowtype;at timestamptz:=clock_timestamp();assignments text;BEGIN
 PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.record_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;
 IF gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,d.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_record_class_grant_required';END IF;
 SELECT * INTO t FROM gridex_ediel_retention.record_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id;
 IF FOUND THEN IF t.decision_id IS DISTINCT FROM d.id THEN RAISE EXCEPTION 'record_retention_tombstone_conflict';END IF;RETURN jsonb_build_object('status',CASE WHEN t.retention_class='contract_signed_pdf_bytes' AND NOT EXISTS(SELECT FROM gridex_ediel_retention.record_events WHERE retention_class=t.retention_class AND target_id=t.target_id AND kind='storage_object_absent') THEN 'storage_purge_pending' ELSE 'redacted' END,'retentionClass',t.retention_class,'targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'storagePath',t.storage_path,'replay',true);END IF;
 r:=gridex_ediel_retention.record_current_review_v1(d);IF r IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_exact_class_legal_review_deadline']);END IF;
 LOCK TABLE public.customer_supply_periods,public.customer_portal_accounts,public.customer_portal_claims IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO STRICT customer FROM public.customers WHERE id=d.customer_id AND company_id=p_company_id FOR UPDATE;
 IF customer.status IS DISTINCT FROM 'archived' OR EXISTS(SELECT FROM public.customer_supply_periods WHERE company_id=p_company_id AND customer_id=d.customer_id AND status NOT IN('cancelled','rejected','terminated','ended','closed','inactive') AND (coalesce(actual_end_date,end_date) IS NULL OR coalesce(actual_end_date,end_date)>=current_date)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['operative_customer_closed_and_no_active_supply']);END IF;
 basis:=gridex_ediel_retention.record_basis_v1(p_company_id,d.retention_class,d.target_id);IF basis->>'targetHash' IS DISTINCT FROM d.target_hash OR basis->>'sourceHash' IS DISTINCT FROM d.source_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_native_record_target_changed']);END IF;
 SELECT * INTO STRICT spec FROM gridex_ediel_retention.record_class_catalog WHERE retention_class=d.retention_class;
 IF d.retention_class='customer_address_history' AND EXISTS(SELECT FROM public.customer_addresses WHERE id=d.target_id AND (is_active OR moved_out_at IS NULL OR moved_out_at>=current_date)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['inactive_historical_address_required']);END IF;
 claims:=gridex_ediel_retention.record_receipt_v1(d);
 UPDATE public.customer_portal_accounts SET status='revoked',is_active=false,updated_at=at WHERE company_id=p_company_id AND customer_id=d.customer_id;
 UPDATE public.customer_portal_claims SET status='revoked',updated_at=at WHERE company_id=p_company_id AND customer_id=d.customer_id;
 INSERT INTO gridex_ediel_retention.record_tombstones(retention_class,target_id,company_id,customer_id,contract_id,decision_id,review_id,source_hash,target_hash,byte_length,storage_path,actor_user_id,journal_retain_until,journal_purpose_reference,created_at) VALUES(d.retention_class,d.target_id,p_company_id,d.customer_id,d.contract_id,d.id,r,d.source_hash,d.target_hash,(basis->>'byteLength')::bigint,basis->>'storagePath',p_actor_user_id,(claims->>'journalRetainUntil')::timestamptz,claims->>'journalPurposeReference',at);
 IF d.retention_class<>'contract_signed_pdf_bytes' THEN
  SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.%I,gridex_ediel_retention.record_redacted_v1(%L,to_jsonb(r)))).%I',key,spec.source_table,d.retention_class,key),',') INTO assignments FROM jsonb_object_keys(spec.redaction) key;
  EXECUTE format('UPDATE public.%I r SET %s WHERE id=$1 AND company_id=$2',spec.source_table,assignments) USING d.target_id,p_company_id;
  INSERT INTO gridex_ediel_retention.record_events(retention_class,target_id,kind,actor_user_id) VALUES(d.retention_class,d.target_id,'personal_fields_redacted',p_actor_user_id);
 END IF;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'customer_record',d.target_id,'ediel.retention.record_tombstoned',jsonb_build_object('decisionId',d.id,'reviewId',r,'retentionClass',d.retention_class,'sourceHash',d.source_hash,'targetHash',d.target_hash,'accessRevoked',true,'journalRetainUntil',claims->>'journalRetainUntil','journalPurposeReference',claims->>'journalPurposeReference'));
 RETURN jsonb_build_object('status',CASE WHEN d.retention_class='contract_signed_pdf_bytes' THEN 'storage_purge_pending' ELSE 'redacted' END,'retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',d.source_hash,'byteLength',(basis->>'byteLength')::bigint,'storagePath',basis->>'storagePath','replay',false);
END$_$;

--
-- Name: ediel_begin_invoice_file_purge_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_begin_invoice_file_purge_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.invoice_file_decisions%rowtype;s gridex_ediel_retention.invoice_file_sources%rowtype;other gridex_ediel_retention.invoice_file_sources%rowtype;q gridex_ediel_retention.invoice_file_decisions%rowtype;r uuid;p jsonb;t record;BEGIN
 PERFORM gridex_ediel_retention.invoice_file_actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.invoice_file_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;SELECT * INTO STRICT s FROM gridex_ediel_retention.invoice_file_sources WHERE id=d.source_id FOR SHARE;
 -- Completed immutable receipt first: no reactivation of old policy or bytes.
 IF EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_events WHERE source_id=s.id AND kind='storage_object_absent') THEN RETURN jsonb_build_object('status','purged','sourceId',s.id,'sourceHash',s.source_hash,'byteLength',s.byte_length,'bytesAvailable',false,'replay',true);END IF;
 FOR other IN SELECT * FROM gridex_ediel_retention.invoice_file_shared_scope_v1(s.storage_bucket,s.storage_path) ORDER BY id LOOP
  IF other.company_id<>p_company_id OR other.source_hash<>s.source_hash OR other.byte_length<>s.byte_length THEN RAISE EXCEPTION 'invoice_file_shared_foreign_or_changed_bytes';END IF;
  SELECT * INTO q FROM gridex_ediel_retention.invoice_file_decisions WHERE source_id=other.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE;
  IF q.id IS NULL THEN RAISE EXCEPTION 'invoice_file_each_copy_legal_decision_required';END IF;r:=gridex_ediel_retention.invoice_file_current_v1(q);p:=gridex_ediel_retention.invoice_file_receipt_v1(q);IF r IS NULL OR p IS NULL THEN RAISE EXCEPTION 'invoice_file_each_copy_current_legal_review_required';END IF;
  INSERT INTO gridex_ediel_retention.invoice_file_tombstones(source_id,company_id,decision_id,review_id,actor_user_id,journal_retain_until,journal_purpose_reference) VALUES(other.id,p_company_id,q.id,r,p_actor_user_id,(p->>'journalRetainUntil')::timestamptz,p->>'journalPurposeReference') ON CONFLICT DO NOTHING;
 END LOOP;
 IF NOT EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_tombstones WHERE source_id=s.id) THEN RAISE EXCEPTION 'invoice_file_actual_reference_scope_required';END IF;
 RETURN jsonb_build_object('status','storage_purge_pending','sourceId',s.id,'sourceHash',s.source_hash,'byteLength',s.byte_length,'storageBucket',s.storage_bucket,'storagePath',s.storage_path,'replay',EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_tombstones WHERE source_id=s.id AND decision_id<>d.id));END$$;

--
-- Name: ediel_beneficiary_series_page_v1(uuid, uuid, uuid, bigint, text, uuid, text[], timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_beneficiary_series_page_v1(p_beneficiary_company_id uuid, p_actor_user_id uuid, p_grant_id uuid, p_expected_grant_version bigint, p_purpose text, p_series_id uuid, p_fields text[], p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer DEFAULT 100, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 page jsonb; g public.ediel_data_access_grants%rowtype; a public.ediel_service_assignments%rowtype;
 s public.meter_reading_series%rowtype; m public.ediel_messages%rowtype; ctx jsonb;
 stored gridex_utilts_binding.contracts%rowtype; native_contract jsonb; source_sender text;
 source_app text; source_role text; origin jsonb; receipt_proof jsonb; h text; receipt_id uuid;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 page:=gridex_ediel_ack_replay.beneficiary_series_page_filtered_v2(
  p_beneficiary_company_id,p_actor_user_id,p_grant_id,p_expected_grant_version,p_purpose,p_series_id,
  p_fields,p_start,p_end,p_limit,p_after_at,p_after_id);
 SELECT * INTO STRICT g FROM public.ediel_data_access_grants WHERE id=p_grant_id AND beneficiary_company_id=p_beneficiary_company_id FOR SHARE;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=g.company_id AND id=g.assignment_id FOR SHARE;
 SELECT * INTO STRICT s FROM public.meter_reading_series WHERE company_id=g.company_id AND id=p_series_id FOR SHARE;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=g.company_id AND id=s.source_ediel_message_id;
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(g.company_id,m.environment,m.id);
 SELECT * INTO STRICT stored FROM gridex_utilts_binding.contracts
  WHERE company_id=g.company_id AND source_message_id=m.id AND series_id=s.id;
 native_contract:=gridex_utilts_binding.stored_contract_v1(g.company_id,m.id,stored.transaction_id);
 IF native_contract IS DISTINCT FROM stored.contract OR stored.contract_version NOT IN (1,2) OR stored.contract->>'version' IS DISTINCT FROM stored.contract_version::text OR stored.contract_hash IS NULL
  OR stored.contract_hash IS DISTINCT FROM encode(sha256(convert_to(stored.contract::text,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'ediel_projection_native_origin_unavailable'; END IF;
 SELECT t#>>'{elements,7,0}' INTO STRICT source_app FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload)) t WHERE t->>'tag'='UNB';
 SELECT t#>>'{elements,2,0}' INTO STRICT source_sender FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload)) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS';
 source_role:=split_part(source_app,'-',2);
 IF source_app IS NULL OR source_app IS DISTINCT FROM ctx->>'applicationReference' OR source_role NOT IN ('DDQ','DGI')
  OR source_sender IS NULL OR ctx->>'actorRole' IS DISTINCT FROM 'energy_service_company'
  OR page->>'grantId' IS DISTINCT FROM g.id::text OR (page->>'grantVersion')::bigint IS DISTINCT FROM g.version
  OR page->>'seriesId' IS DISTINCT FROM s.id::text
 THEN RAISE EXCEPTION 'ediel_projection_source_provenance_unavailable'; END IF;
 origin:=jsonb_build_object(
  'version',1,'sourceMessageId',m.id,'sourceRawHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),
  'sourceFamily',m.message_family,'sourceCode',m.message_code,'sourceEnvironment',m.environment,
  'sourceRole',source_role,'sourceApplicationReference',source_app,'sourceSenderEdielId',source_sender,
  'receiverActorId',ctx->>'legalActorId','receiverRole',ctx->>'actorRole',
  'contractVersion',stored.contract_version,'contractHash',stored.contract_hash,
  'purpose',g.purpose,'fields',to_jsonb(p_fields),
  'qualityOrigin',CASE WHEN 'quality'=ANY(p_fields) THEN jsonb_build_object('sourceMessageId',m.id,'seriesId',s.id,'column','meter_reading_values.quality') ELSE NULL END);
 receipt_proof:=jsonb_build_object('version',1,'providerCompanyId',g.company_id,'beneficiaryCompanyId',p_beneficiary_company_id,
  'actorUserId',p_actor_user_id,'assignmentId',a.id,'assignmentVersion',a.version,'grantId',g.id,'grantVersion',g.version,
  'permissionLinkId',g.permission_link_id,'seriesId',s.id,'origin',origin,'start',p_start,'end',p_end,
  'limit',p_limit,'afterAt',p_after_at,'afterId',p_after_id,
  'pageHash',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 h:=encode(sha256(convert_to(receipt_proof::text,'UTF8')),'hex');
 -- The capability hash is derived from the fully qualified native proof above;
 -- it is never supplied by a caller. Serialize this one proof only after all
 -- current authority/source checks, then return retained bytes without an
 -- attempted INSERT. Different purposes/actors/pages retain separate receipts.
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel_beneficiary_projection_receipt:'||h,0));
 SELECT id INTO receipt_id FROM gridex_ediel_services.projection_receipts WHERE proof_hash=h AND proof=receipt_proof;
 IF receipt_id IS NULL THEN
  IF EXISTS(SELECT FROM gridex_ediel_services.projection_receipts WHERE proof_hash=h) THEN
   RAISE EXCEPTION 'ediel_projection_receipt_proof_conflict';
  END IF;
  INSERT INTO gridex_ediel_services.projection_receipts(company_id,beneficiary_company_id,actor_user_id,source_message_id,series_id,grant_id,grant_version,proof_hash,proof)
   VALUES(g.company_id,p_beneficiary_company_id,p_actor_user_id,m.id,s.id,g.id,g.version,h,receipt_proof)
   RETURNING id INTO STRICT receipt_id;
 END IF;
 RETURN page||jsonb_build_object('consumerReceiptId',receipt_id,'provenance',origin);
END $$;

--
