--
-- Name: ediel_compare_and_set_prodat_object_case_v1(uuid, uuid, uuid, uuid, timestamp with time zone, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_compare_and_set_prodat_object_case_v1(p_company_id uuid, p_case_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_expected_updated_at timestamp with time zone, p_expected_status text, p_expected_fingerprint text, p_expected_revision integer, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE row_case public.ediel_inbound_cases%rowtype;proof jsonb;oldplan jsonb;plan jsonb;result jsonb;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();proof:=gridex_prodat_object_batch.source_v1(p_company_id,p_source_message_id,p_actor_user_id);
 SELECT * INTO row_case FROM public.ediel_inbound_cases WHERE id=p_case_id AND company_id=p_company_id AND ediel_message_id=p_source_message_id FOR UPDATE;
 IF row_case.id IS NULL THEN RAISE EXCEPTION 'prodat_object_batch_case_source_required';END IF;
 oldplan:=row_case.review_decision->'objectApplication';
 IF oldplan IS NOT NULL AND oldplan->>'originalActorId' IS DISTINCT FROM p_actor_user_id::text THEN RAISE EXCEPTION 'prodat_object_batch_original_actor_required';END IF;
 IF row_case.status='applied' THEN
  PERFORM gridex_prodat_object_batch.require_plan_v1(row_case,oldplan,proof,p_actor_user_id);PERFORM gridex_prodat_object_batch.require_receipts_v1(row_case,oldplan,proof);PERFORM gridex_prodat_object_batch.require_review_v1(row_case,oldplan,proof,p_actor_user_id);
  IF oldplan->>'fingerprint' IS DISTINCT FROM p_expected_fingerprint THEN RAISE EXCEPTION 'prodat_object_batch_replay_conflict';END IF;
  RETURN NULL; -- CAS lost to an identical finished operation; caller re-reads.
 END IF;
 IF row_case.updated_at IS DISTINCT FROM p_expected_updated_at OR row_case.status IS DISTINCT FROM p_expected_status OR oldplan->>'fingerprint' IS DISTINCT FROM p_expected_fingerprint OR(oldplan->>'revision')::int IS DISTINCT FROM p_expected_revision THEN RETURN NULL;END IF;
 IF p_patch-ARRAY['status','review_decision','reviewed_by','reviewed_at','failure_reason','updated_by','customer_id','site_id','metering_point_id','applied_at']<>'{}'::jsonb OR p_patch->>'updated_by' IS DISTINCT FROM p_actor_user_id::text OR(p_patch->>'status' IN('approved','failed','applied')) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_object_batch_case_patch_required';END IF;
 plan:=coalesce(p_patch#>'{review_decision,objectApplication}',oldplan);
 PERFORM gridex_prodat_object_batch.require_plan_v1(row_case,plan,proof,p_actor_user_id);PERFORM gridex_prodat_object_batch.require_receipts_v1(row_case,plan,proof);
 IF oldplan IS NULL THEN
  IF EXISTS(SELECT FROM gridex_prodat_object_batch.review_receipts WHERE company_id=p_company_id AND case_id=p_case_id) THEN RAISE EXCEPTION 'prodat_object_batch_original_review_conflict';END IF;
  IF row_case.status NOT IN('pending_review','failed') OR plan->'revision'<>'1'::jsonb OR p_patch->>'reviewed_by' IS DISTINCT FROM p_actor_user_id::text OR jsonb_array_length(plan->'receipts')<>0 OR p_patch->>'status'<>'approved' THEN RAISE EXCEPTION 'prodat_object_batch_initial_review_required';END IF;
  INSERT INTO gridex_prodat_object_batch.review_receipts(company_id,case_id,source_message_id,environment,source_hash,assessment_id,actor_user_id,fingerprint,command_hash) VALUES(p_company_id,p_case_id,p_source_message_id,proof#>>'{sourceMessage,environment}',proof->>'sourcePayloadHash',(proof->>'assessmentId')::uuid,p_actor_user_id,plan->>'fingerprint',plan->>'commandHash');
 ELSE
  PERFORM gridex_prodat_object_batch.require_review_v1(row_case,oldplan,proof,p_actor_user_id);
  IF row_case.reviewed_by IS DISTINCT FROM p_actor_user_id OR plan-ARRAY['revision','receipts'] IS DISTINCT FROM oldplan-ARRAY['revision','receipts'] OR(plan->>'revision')::int<>(oldplan->>'revision')::int+1 OR NOT((plan->'receipts') @> (oldplan->'receipts')) THEN RAISE EXCEPTION 'prodat_object_batch_saved_plan_changed';END IF;
 END IF;
 IF p_patch->>'status'='applied' THEN
  IF jsonb_array_length(plan->'receipts')<>jsonb_array_length(plan->'commands') THEN RAISE EXCEPTION 'prodat_object_batch_incomplete';END IF;
  result:=jsonb_build_object('objectCount',jsonb_array_length(plan->'commands'),'receipts',plan->'receipts','fingerprint',plan->>'fingerprint','sourceHash',plan->>'sourceHash');
  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,new_values,metadata) VALUES(p_company_id,p_actor_user_id,'ediel_inbound_case',p_case_id::text,'ediel_inbound_objects_applied',result,jsonb_build_object('edielMessageId',p_source_message_id,'fingerprint',plan->>'fingerprint'));
  INSERT INTO public.ediel_message_events(company_id,ediel_message_id,event_type,event_status,message,payload,created_by) VALUES(p_company_id,p_source_message_id,'validated','success','Samtliga PRODAT-objekt har egna kanoniska kundtransaktioner och sparade kvitton.',result,p_actor_user_id);
 END IF;
 UPDATE public.ediel_inbound_cases SET status=p_patch->>'status',review_decision=coalesce(p_patch->'review_decision',review_decision),reviewed_by=coalesce((p_patch->>'reviewed_by')::uuid,reviewed_by),reviewed_at=CASE WHEN oldplan IS NULL THEN(SELECT recorded_at FROM gridex_prodat_object_batch.review_receipts WHERE company_id=p_company_id AND case_id=p_case_id) ELSE reviewed_at END,
  failure_reason=p_patch->>'failure_reason',updated_by=p_actor_user_id,updated_at=clock_timestamp(),applied_at=CASE WHEN p_patch->>'status'='applied' THEN clock_timestamp() ELSE applied_at END,
  customer_id=CASE WHEN p_patch->>'status'='applied' THEN NULL ELSE customer_id END,site_id=CASE WHEN p_patch->>'status'='applied' THEN NULL ELSE site_id END,metering_point_id=CASE WHEN p_patch->>'status'='applied' THEN NULL ELSE metering_point_id END WHERE id=row_case.id RETURNING * INTO row_case;
 RETURN to_jsonb(row_case);
END $$;

--
-- Name: ediel_configuration_change_snapshot_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_configuration_change_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if current_setting('gridex.skip_ediel_snapshot_trigger', true) = 'on' then
    if tg_level = 'STATEMENT' then return null; end if;
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if tg_level = 'STATEMENT' then
    if tg_table_name not in ('ediel_rule_versions', 'ediel_rule_packs', 'ediel_message_profiles') then
      return null;
    end if;

    for v_company_id in
      select c.id
      from public.companies c
      where c.status = 'active'
        and (
          exists(select 1 from public.ediel_production_state ps where ps.company_id = c.id)
          or exists(select 1 from public.ediel_actor_settings eas where eas.company_id = c.id)
        )
      order by c.id
    loop
      perform public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
        v_company_id,
        auth.uid(),
        tg_table_name || '_changed'
      );
    end loop;
    return null;
  end if;

  if tg_op = 'DELETE' then
    v_company_id := old.company_id;
  else
    v_company_id := new.company_id;
  end if;

  if v_company_id is not null then
    perform public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
      v_company_id,
      auth.uid(),
      tg_table_name || '_changed'
    );
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;

--
-- Name: ediel_confirmed_customer_snapshot_before_scope_fence_v1(uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_confirmed_customer_snapshot_before_scope_fence_v1(p_company_id uuid, p_actor_user_id uuid, p_snapshot_id uuid, p_readset_hash text, p_customer_id uuid, p_site_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snap gridex_received_sources.object_selection_snapshots%rowtype;v gridex_requested_changes.confirmed_customer_versions%rowtype;b jsonb;rows jsonb:='[]';n integer:=0;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'read','death') IS NOT TRUE THEN RAISE EXCEPTION 'customer_history_reader_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots s WHERE s.id=p_snapshot_id AND s.company_id=p_company_id AND s.readset_hash=p_readset_hash FOR SHARE;
 IF NOT FOUND OR snap.readset_hash IS DISTINCT FROM encode(sha256(convert_to(snap.readset_text,'UTF8')),'hex') OR snap.readset_text::jsonb->>'complete' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'customer_history_actual_snapshot_required';END IF;
 PERFORM s.id FROM public.customer_sites s WHERE s.id=p_site_id AND s.company_id=p_company_id AND s.customer_id=p_customer_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'customer_history_owned_site_required';END IF;
 FOR v IN SELECT * FROM gridex_requested_changes.confirmed_customer_versions x WHERE x.company_id=p_company_id AND x.environment=snap.environment AND x.customer_id=p_customer_id AND x.site_id=p_site_id AND x.canonical_assessment_id IS NOT NULL ORDER BY x.effective_at,x.source_message_id FOR SHARE LOOP
  n:=n+1;IF n>1000 THEN RAISE EXCEPTION 'customer_history_bounded_read_incomplete';END IF;
  b:=gridex_requested_changes.customer_facet_basis_v1(snap.readset_text::jsonb,snap.cutoff_at,p_company_id,snap.environment,p_customer_id,p_site_id,v.source_message_id::text,v.object_id,v.identity_agency);
  IF b IS NOT NULL THEN rows:=rows||jsonb_build_array(b);END IF;
 END LOOP;
 RETURN jsonb_build_object('owner','confirmed-customer-facet-snapshot-v1','companyId',p_company_id,'environment',snap.environment,'customerId',p_customer_id,'siteId',p_site_id,'snapshotId',snap.id,'readsetHash',snap.readset_hash,'cutoffAt',snap.cutoff_at,'versions',rows);
END$$;

--
-- Name: ediel_confirmed_customer_snapshot_v1(uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_confirmed_customer_snapshot_v1(p_company_id uuid, p_actor_user_id uuid, p_snapshot_id uuid, p_readset_hash text, p_customer_id uuid, p_site_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();result:=public.ediel_confirmed_customer_snapshot_before_scope_fence_v1(p_company_id,p_actor_user_id,p_snapshot_id,p_readset_hash,p_customer_id,p_site_id);IF EXISTS(SELECT FROM jsonb_array_elements(result->'versions') x WHERE x->>'authorityKind'='bilateral') AND gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_history_reader_forbidden' USING ERRCODE='42501';END IF;RETURN result;END$$;

--
-- Name: ediel_consume_prodat_mixed_reply_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_consume_prodat_mixed_reply_v1(p_company_id uuid, p_source_message_id uuid, p_acknowledgement_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;m public.ediel_messages%rowtype;tokens jsonb;intent uuid;prior gridex_received_sources.prodat_mixed_reply_consumptions%rowtype;hash text;
BEGIN
 receipt:=public.ediel_read_prodat_mixed_reply_v1(p_company_id,p_source_message_id,p_actor_user_id);
 IF receipt IS NULL THEN RAISE EXCEPTION 'prodat_mixed_reply_current_intent_required';END IF;
 intent:=(receipt->>'replyIntentId')::uuid;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_acknowledgement_id AND company_id=p_company_id AND environment=receipt->>'environment' AND related_message_id=p_source_message_id FOR SHARE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RAISE EXCEPTION 'prodat_mixed_reply_actual_ack_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,3,0}'='34')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='ERC' AND t#>>'{elements,1,0}'='100')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='ERC' AND t#>>'{elements,1,0}'<>'100') THEN RAISE EXCEPTION 'prodat_mixed_reply_own_ack_required';END IF;
 PERFORM gridex_ediel_ack_guide.require_v1(m);
 PERFORM o.id FROM public.ediel_outbox o WHERE o.company_id=p_company_id AND o.environment=m.environment AND o.ediel_message_id=m.id AND o.source_message_id=p_source_message_id AND o.message_family='APERAK' AND o.status IN('prepared','queued','sending','sent') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'prodat_mixed_reply_actual_dispatch_outbox_required';END IF;
 hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 SELECT * INTO prior FROM gridex_received_sources.prodat_mixed_reply_consumptions WHERE reply_intent_id=intent FOR SHARE;
 IF FOUND THEN
  IF prior.acknowledgement_id IS DISTINCT FROM m.id OR prior.acknowledgement_payload_hash IS DISTINCT FROM hash THEN RAISE EXCEPTION 'prodat_mixed_reply_consumption_replay_conflict';END IF;
  RETURN jsonb_build_object('consumed',true,'idempotent',true,'replyIntentId',intent,'acknowledgementId',m.id);
 END IF;
 INSERT INTO gridex_received_sources.prodat_mixed_reply_consumptions(reply_intent_id,acknowledgement_id,company_id,environment,source_message_id,acknowledgement_payload_hash,actor_user_id) VALUES(intent,m.id,p_company_id,m.environment,p_source_message_id,hash,p_actor_user_id);
 RETURN jsonb_build_object('consumed',true,'idempotent',false,'replyIntentId',intent,'acknowledgementId',m.id);
END $$;

--
-- Name: ediel_consume_prodat_retry_authorization_v1(uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_consume_prodat_retry_authorization_v1(p_company_id uuid, p_message_id uuid, p_previous_attempt_id uuid, p_new_attempt_id uuid, p_actor_user_id uuid, p_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;m public.ediel_messages%rowtype;a gridex_ediel_transport.attempts%rowtype;used uuid;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND THEN RETURN false;END IF;
 BEGIN PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'send');EXCEPTION WHEN insufficient_privilege THEN RETURN false;END;
 SELECT * INTO op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id AND original_message_id=m.id AND kind='verified_transfer_loss' AND previous_attempt_id=p_previous_attempt_id;
 SELECT * INTO a FROM gridex_ediel_transport.attempts WHERE id=p_previous_attempt_id AND company_id=p_company_id AND message_id=m.id AND environment=m.environment FOR SHARE;
 IF op.id IS NULL OR op.environment IS DISTINCT FROM m.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.immutable_rendered_at IS NULL OR a.id IS NULL OR p_new_attempt_id IS NULL OR p_new_attempt_id=p_previous_attempt_id OR op.original_payload_hash IS DISTINCT FROM m.immutable_payload_hash OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR (a.classification IN ('pre_connect_negative','explicit_negative','all_rejected')) IS NOT TRUE OR a.observed_at IS NULL
 OR NOT EXISTS(SELECT FROM gridex_ediel_transport.reservations r WHERE r.message_id=m.id AND r.attempt_id=p_previous_attempt_id AND r.state='observed') OR (m.contrl_status='received') IS TRUE OR (m.aperak_status='received') IS TRUE OR EXISTS(SELECT FROM public.ediel_messages ack WHERE ack.company_id=m.company_id AND ack.environment=m.environment AND ack.direction='inbound' AND ack.original_message_id=m.id::text AND ack.ack_outcome='positive')
 OR EXISTS(SELECT FROM gridex_ediel_transport.attempts prior WHERE prior.message_id=m.id AND (prior.classification IN ('accepted','partial','unknown') OR prior.entered_at IS NOT NULL AND prior.observed_at IS NULL)) THEN RETURN false;END IF;
 PERFORM gridex_received_sources.require_established_recovery_source_v1(p_company_id,op.id);
 INSERT INTO gridex_received_sources.prodat_recovery_attempts(operation_id,attempt_id) VALUES(op.id,p_new_attempt_id) ON CONFLICT DO NOTHING;
 SELECT attempt_id INTO used FROM gridex_received_sources.prodat_recovery_attempts WHERE operation_id=op.id;
 RETURN used=p_new_attempt_id;
END $$;

