    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ediel_header_negative_birth.create_v1(p_company_id,p_environment,p_actor_user_id,p_inbound_email_message_id,p_parse_result_id,p_expected_raw_payload,p_expected_payload_hash)$$;

--
-- Name: ediel_create_bilateral_prodat_original_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_create_bilateral_prodat_original_v1(p_company_id uuid, p_actor_user_id uuid, p_draft jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE raw text:=p_draft->>'rawPayload';env text:=p_draft->>'environment';cap jsonb;own jsonb;e jsonb;sealed jsonb;m public.ediel_messages%rowtype;mid uuid:=gen_random_uuid();reference record;token jsonb;intent public.ediel_message_intents%rowtype;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();
 PERFORM gridex_bilateral_prodat.lock_outbound_v1();
 IF jsonb_typeof(p_draft) IS DISTINCT FROM 'object' OR p_draft->>'companyId' IS DISTINCT FROM p_company_id::text OR p_draft->>'direction' IS DISTINCT FROM 'outbound' OR p_draft->>'messageStandard' IS DISTINCT FROM 'edifact' OR p_draft->>'messageFamily' IS DISTINCT FROM 'PRODAT'
 OR p_draft->>'messageCode' NOT IN('Z03','Z08') OR coalesce(p_draft->>'status','draft') NOT IN('draft','prepared','queued') OR nullif(p_draft->>'sourceOperationId','') IS NULL
 OR nullif(p_draft->>'messageSentAt','') IS NOT NULL OR nullif(p_draft->>'relatedMessageId','') IS NOT NULL THEN RAISE EXCEPTION 'bilateral_prodat_outbound_actual_draft_required';END IF;
 IF (SELECT count(*) FROM public.ediel_messages WHERE company_id=p_company_id AND environment=env AND direction='outbound' AND source_operation_id=p_draft->>'sourceOperationId')>1 THEN RAISE EXCEPTION 'bilateral_prodat_outbound_operation_ambiguous';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=env AND direction='outbound' AND source_operation_id=p_draft->>'sourceOperationId' FOR SHARE;
 IF FOUND THEN
  IF m.raw_payload IS DISTINCT FROM raw OR m.message_code IS DISTINCT FROM p_draft->>'messageCode' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_operation_conflict';END IF;
  PERFORM gridex_bilateral_prodat.require_recorded_outbound_v1(m,p_actor_user_id);RETURN jsonb_build_object('version',1,'message',to_jsonb(m),'replayed',true);
 END IF;
 cap:=gridex_bilateral_prodat.outbound_capability_v1(p_company_id,p_actor_user_id,env,raw);
 IF cap IS NULL OR cap->>'messageCode' IS DISTINCT FROM p_draft->>'messageCode' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_current_profile_required';END IF;
 FOR own IN SELECT x FROM jsonb_array_elements(cap->'objects')x LOOP
  IF nullif(p_draft->>'customerId','') IS NOT NULL AND p_draft->>'customerId' IS DISTINCT FROM own->>'customerId'
   OR nullif(p_draft->>'meteringPointId','') IS NOT NULL AND p_draft->>'meteringPointId' IS DISTINCT FROM own->>'pointId'
   OR nullif(p_draft->>'siteId','') IS NOT NULL AND p_draft->>'siteId' IS DISTINCT FROM own->>'siteId'
   OR nullif(p_draft->>'switchRequestId','') IS NOT NULL AND p_draft->>'switchRequestId' IS DISTINCT FROM own->>'switchId' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_actual_owned_draft_required';END IF;
 END LOOP;
 IF cap->>'messageCode'='Z03' THEN
  IF jsonb_array_length(cap->'objects')<>1 OR nullif(p_draft->>'switchRequestId','') IS NULL OR p_draft->>'sourceOperationId' IS DISTINCT FROM cap#>>'{objects,0,switchId}' OR p_draft->>'switchRequestId' IS DISTINCT FROM cap#>>'{objects,0,switchId}' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_actual_h_operation_required';END IF;
  SELECT * INTO intent FROM public.ediel_message_intents WHERE id=(p_draft->>'intentId')::uuid AND company_id=p_company_id FOR UPDATE;
  IF intent.id IS NULL OR intent.environment IS DISTINCT FROM env OR intent.message_family IS DISTINCT FROM 'PRODAT' OR intent.message_code IS DISTINCT FROM 'Z03' OR intent.direction IS DISTINCT FROM 'outbound' OR intent.created_by IS DISTINCT FROM p_actor_user_id OR intent.operation_id IS DISTINCT FROM (p_draft->>'switchRequestId')::uuid OR intent.supplier_switch_request_id IS DISTINCT FROM intent.operation_id OR intent.ediel_message_id IS NOT NULL
   OR intent.customer_id::text IS DISTINCT FROM cap#>>'{objects,0,customerId}' OR intent.customer_site_id::text IS DISTINCT FROM cap#>>'{objects,0,siteId}' OR intent.payload->>'transactionSubtype' IS DISTINCT FROM 'H' THEN RAISE EXCEPTION 'bilateral_prodat_outbound_actual_h_intent_required';END IF;
 END IF;
 IF cap->>'messageCode'='Z08' THEN PERFORM gridex_bilateral_prodat.require_closure_draft_v1(p_company_id,p_actor_user_id,p_draft,cap);END IF;
 IF p_draft#>>'{executionContextSnapshot,outboundOwnerWitnessId}' IS NOT NULL THEN RAISE EXCEPTION 'bilateral_prodat_outbound_atomic_original_required';END IF;
 e:=jsonb_build_object('rulePackId',p_draft->>'canonicalRulePackId','messageProfileId',p_draft->>'ruleProfileVersionId','profileKey',p_draft->>'ruleProfileKey','version',p_draft->>'ruleProfileVersion','sourceHash',p_draft->>'rulePackChecksum','snapshot',p_draft->'rulePackSnapshot');
 INSERT INTO gridex_bilateral_prodat.outbound_operations(message_id,company_id,environment,actor_user_id,payload_hash,capability,creation_txid) VALUES(mid,p_company_id,env,p_actor_user_id,cap->>'payloadHash',cap,txid_current());
 sealed:=gridex_ediel_outbound_owner.prepare_v1(jsonb_build_object('companyId',p_company_id,'actorUserId',p_actor_user_id,'environment',env,'rawPayload',raw,'rulePackEvidence',e,'bilateralOriginalMessageId',mid));
 INSERT INTO gridex_bilateral_prodat.outbound_receipts(message_id,company_id,witness_id,payload_hash) VALUES(mid,p_company_id,(sealed->>'witnessId')::uuid,cap->>'payloadHash');
 INSERT INTO public.ediel_messages(id,company_id,environment,direction,message_standard,message_family,message_code,status,created_by,updated_by,raw_payload,canonical_rule_pack_id,rule_profile_key,rule_profile_version_id,rule_profile_version,rule_pack_checksum,rule_pack_snapshot,execution_context_snapshot,tenant_resolution_status,business_match_status,processing_status,message_version,process_type,transport_type,mailbox,sender_ediel_id,sender_name,sender_sub_address,receiver_ediel_id,receiver_name,receiver_sub_address,sender_email,receiver_email,subject,file_name,mime_type,interchange_reference,external_reference,correlation_reference,transaction_reference,application_reference,original_message_id,original_transaction_id,original_message_code,source_operation_id,transport_security_mode,route_transport_security_mode,contrl_status,aperak_status,utilts_err_status,communication_route_id,route_profile_id,intent_id,party_id,party_address_id,expected_receiver_certificate_id,outbound_request_id,switch_request_id,grid_owner_data_request_id,partner_export_id,customer_id,site_id,metering_point_id,grid_owner_id,parsed_payload,validation_report,requires_contrl,requires_aperak,was_smime_encrypted,cms_expected_receiver_present,test_flag,unb_sender_id,unb_receiver_id,unb_sender_subaddress,unb_receiver_subaddress,message_reference,bgm_code,bgm_reference)
 VALUES(mid,p_company_id,env,'outbound','edifact','PRODAT',cap->>'messageCode',coalesce(p_draft->>'status','draft'),p_actor_user_id,p_actor_user_id,raw,(e->>'rulePackId')::uuid,e->>'profileKey',(e->>'messageProfileId')::uuid,e->>'version',e->>'sourceHash',e->'snapshot',jsonb_build_object('outboundOwnerWitnessId',sealed->>'witnessId'),'tenant_resolved','not_checked',coalesce(p_draft->>'status','draft'),p_draft->>'messageVersion',p_draft->>'processType',p_draft->>'transportType',p_draft->>'mailbox',p_draft->>'senderEdielId',p_draft->>'senderName',p_draft->>'senderSubAddress',p_draft->>'receiverEdielId',p_draft->>'receiverName',p_draft->>'receiverSubAddress',p_draft->>'senderEmail',p_draft->>'receiverEmail',p_draft->>'subject',p_draft->>'fileName',p_draft->>'mimeType',p_draft->>'interchangeReference',p_draft->>'externalReference',p_draft->>'correlationReference',p_draft->>'transactionReference',p_draft->>'applicationReference',p_draft->>'originalMessageId',p_draft->>'originalTransactionId',p_draft->>'originalMessageCode',p_draft->>'sourceOperationId',p_draft->>'transportSecurityMode',p_draft->>'routeTransportSecurityMode',p_draft->>'contrlStatus',p_draft->>'aperakStatus',p_draft->>'utiltsErrStatus',nullif(p_draft->>'communicationRouteId','')::uuid,nullif(p_draft->>'routeProfileId','')::uuid,nullif(p_draft->>'intentId','')::uuid,nullif(p_draft->>'partyId','')::uuid,NULL,nullif(p_draft->>'expectedReceiverCertificateId','')::uuid,nullif(p_draft->>'outboundRequestId','')::uuid,nullif(p_draft->>'switchRequestId','')::uuid,nullif(p_draft->>'gridOwnerDataRequestId','')::uuid,nullif(p_draft->>'partnerExportId','')::uuid,nullif(p_draft->>'customerId','')::uuid,nullif(p_draft->>'siteId','')::uuid,nullif(p_draft->>'meteringPointId','')::uuid,nullif(p_draft->>'gridOwnerId','')::uuid,coalesce(p_draft->'parsedPayload','{}'::jsonb),coalesce(p_draft->'validationReport','{}'::jsonb),(p_draft->>'requiresContrl')::boolean,(p_draft->>'requiresAperak')::boolean,(p_draft->>'wasSmimeEncrypted')::boolean,(p_draft->>'cmsExpectedReceiverPresent')::boolean,coalesce((p_draft->>'testFlag')::integer,CASE env WHEN 'test' THEN 1 ELSE 0 END),p_draft->>'senderEdielId',p_draft->>'receiverEdielId',p_draft->>'senderSubAddress',p_draft->>'receiverSubAddress',p_draft->>'originalMessageId',cap->>'messageCode',p_draft->>'externalReference') RETURNING * INTO m;
 PERFORM gridex_ediel_source_rules.capture_v1(m.company_id,m.id);
 IF m.message_code='Z03' THEN
  UPDATE public.ediel_message_intents SET ediel_message_id=m.id,outbound_request_id=m.outbound_request_id,render_status='rendered',updated_at=now() WHERE id=m.intent_id AND company_id=m.company_id;
  PERFORM public.ediel_bind_switch_original_v1(m.company_id,m.switch_request_id,m.id,p_actor_user_id);
 END IF;
 IF m.message_code='Z08' THEN UPDATE public.ediel_message_intents SET ediel_message_id=m.id,outbound_request_id=m.outbound_request_id,render_status='rendered',updated_at=now() WHERE id=m.intent_id AND company_id=m.company_id;END IF;
 -- Immutable own references and created event are part of the same transaction.
 IF coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id) IS NOT NULL THEN
 FOR reference IN SELECT DISTINCT reference_type,reference_value FROM (
 SELECT 'UNB_REF'::text reference_type,m.interchange_reference reference_value UNION ALL SELECT 'BGM_REF',m.external_reference
 UNION ALL SELECT 'RFF_'||(t#>>'{elements,1,0}'),t#>>'{elements,1,1}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}' IN('LI','ACW','Z07','TN')) refs WHERE nullif(reference_value,'') IS NOT NULL LOOP
  IF EXISTS(SELECT FROM public.ediel_business_references existing WHERE existing.company_id=m.company_id AND existing.reference_type=reference.reference_type AND existing.reference_value=reference.reference_value AND existing.business_object_type=CASE WHEN m.switch_request_id IS NOT NULL THEN 'supplier_switch_request' WHEN m.grid_owner_data_request_id IS NOT NULL THEN 'grid_owner_data_request' WHEN m.outbound_request_id IS NOT NULL THEN 'outbound_request' ELSE 'partner_export' END AND existing.business_object_id=coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id) AND existing.source_message_id IS DISTINCT FROM m.id) THEN RAISE EXCEPTION 'bilateral_prodat_outbound_reference_owner_conflict';END IF;
  INSERT INTO public.ediel_business_references(company_id,source_message_id,reference_type,reference_value,message_family,message_code,business_object_type,business_object_id,customer_id,customer_site_id,metering_point_id)
   VALUES(m.company_id,m.id,reference.reference_type,reference.reference_value,m.message_family,m.message_code,CASE WHEN m.switch_request_id IS NOT NULL THEN 'supplier_switch_request' WHEN m.grid_owner_data_request_id IS NOT NULL THEN 'grid_owner_data_request' WHEN m.outbound_request_id IS NOT NULL THEN 'outbound_request' ELSE 'partner_export' END,coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id),m.customer_id,m.site_id,m.metering_point_id)
   ON CONFLICT(company_id,reference_type,reference_value,business_object_type,business_object_id) DO NOTHING;
 END LOOP;END IF;
 INSERT INTO public.ediel_message_events(company_id,ediel_message_id,message_id,event_type,event_status,message,payload,event_payload,created_by)
 VALUES(m.company_id,m.id,m.id,'created','info','Bilateral PRODAT original created by atomic source owner',jsonb_build_object('sourceOperationId',m.source_operation_id,'payloadHash',cap->>'payloadHash'),jsonb_build_object('owner','bilateral_prodat_outbound_atomic_v1'),p_actor_user_id);
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,m.company_id,'ediel_message',m.id,'ediel.bilateral_profile.original_registered',jsonb_build_object('payloadHash',cap->>'payloadHash','objects',cap->'objects'));
 PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);
 RETURN jsonb_build_object('version',1,'message',to_jsonb(m),'replayed',false);
END$$;

--
-- Name: ediel_create_national_supply_rescission_original_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_create_national_supply_rescission_original_v1(p_company_id uuid, p_actor_user_id uuid, p_draft jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE raw text:=p_draft->>'rawPayload';env text:=p_draft->>'environment';cap jsonb;own jsonb;e jsonb;sealed jsonb;m public.ediel_messages%rowtype;mid uuid:=gen_random_uuid();reference record;token jsonb;intent public.ediel_message_intents%rowtype;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();
 PERFORM gridex_supply_rescission.lock_original_v1();
 IF jsonb_typeof(p_draft) IS DISTINCT FROM 'object' OR p_draft->>'companyId' IS DISTINCT FROM p_company_id::text OR p_draft->>'direction' IS DISTINCT FROM 'outbound' OR p_draft->>'messageStandard' IS DISTINCT FROM 'edifact' OR p_draft->>'messageFamily' IS DISTINCT FROM 'PRODAT'
 OR p_draft->>'messageCode' IS DISTINCT FROM 'Z08' OR coalesce(p_draft->>'status','draft') NOT IN('draft','prepared','queued') OR nullif(p_draft->>'sourceOperationId','') IS NULL
 OR nullif(p_draft->>'messageSentAt','') IS NOT NULL OR nullif(p_draft->>'relatedMessageId','') IS NOT NULL THEN RAISE EXCEPTION 'national_supply_rescission_actual_draft_required';END IF;
 IF (SELECT count(*) FROM public.ediel_messages WHERE company_id=p_company_id AND environment=env AND direction='outbound' AND source_operation_id=p_draft->>'sourceOperationId')>1 THEN RAISE EXCEPTION 'national_supply_rescission_operation_ambiguous';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=env AND direction='outbound' AND source_operation_id=p_draft->>'sourceOperationId' FOR SHARE;
 IF FOUND THEN
  IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_replay_actor_forbidden' USING ERRCODE='42501';END IF;
  IF m.raw_payload IS DISTINCT FROM raw OR m.message_code IS DISTINCT FROM p_draft->>'messageCode' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'national_supply_rescission_operation_conflict';END IF;
  PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(m);IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_replay_producer_forbidden' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('version',1,'message',to_jsonb(m),'replayed',true);
 END IF;
 cap:=gridex_supply_rescission.outbound_capability_v1(p_company_id,p_actor_user_id,env,raw,(p_draft->>'sourceOperationId')::uuid);
 IF cap IS NULL OR cap->>'messageCode' IS DISTINCT FROM p_draft->>'messageCode' THEN RAISE EXCEPTION 'national_supply_rescission_current_profile_required';END IF;
 FOR own IN SELECT x FROM jsonb_array_elements(cap->'objects')x LOOP
  IF nullif(p_draft->>'customerId','') IS NOT NULL AND p_draft->>'customerId' IS DISTINCT FROM own->>'customerId'
   OR nullif(p_draft->>'meteringPointId','') IS NOT NULL AND p_draft->>'meteringPointId' IS DISTINCT FROM own->>'pointId'
   OR nullif(p_draft->>'siteId','') IS NOT NULL AND p_draft->>'siteId' IS DISTINCT FROM own->>'siteId'
   OR nullif(p_draft->>'switchRequestId','') IS NOT NULL AND p_draft->>'switchRequestId' IS DISTINCT FROM own->>'switchId' THEN RAISE EXCEPTION 'national_supply_rescission_actual_owned_draft_required';END IF;
 END LOOP;
 IF cap->>'messageCode'='Z03' THEN
  IF jsonb_array_length(cap->'objects')<>1 OR nullif(p_draft->>'switchRequestId','') IS NULL OR p_draft->>'sourceOperationId' IS DISTINCT FROM cap#>>'{objects,0,switchId}' OR p_draft->>'switchRequestId' IS DISTINCT FROM cap#>>'{objects,0,switchId}' THEN RAISE EXCEPTION 'national_supply_rescission_actual_h_operation_required';END IF;
  SELECT * INTO intent FROM public.ediel_message_intents WHERE id=(p_draft->>'intentId')::uuid AND company_id=p_company_id FOR UPDATE;
  IF intent.id IS NULL OR intent.environment IS DISTINCT FROM env OR intent.message_family IS DISTINCT FROM 'PRODAT' OR intent.message_code IS DISTINCT FROM 'Z03' OR intent.direction IS DISTINCT FROM 'outbound' OR intent.created_by IS DISTINCT FROM p_actor_user_id OR intent.operation_id IS DISTINCT FROM (p_draft->>'switchRequestId')::uuid OR intent.supplier_switch_request_id IS DISTINCT FROM intent.operation_id OR intent.ediel_message_id IS NOT NULL
   OR intent.customer_id::text IS DISTINCT FROM cap#>>'{objects,0,customerId}' OR intent.customer_site_id::text IS DISTINCT FROM cap#>>'{objects,0,siteId}' OR intent.payload->>'transactionSubtype' IS DISTINCT FROM 'H' THEN RAISE EXCEPTION 'national_supply_rescission_actual_h_intent_required';END IF;
 END IF;
 IF cap->>'messageCode'='Z08' THEN PERFORM gridex_supply_rescission.require_draft_v1(p_company_id,p_actor_user_id,p_draft,cap);END IF;
 IF p_draft#>>'{executionContextSnapshot,outboundOwnerWitnessId}' IS NOT NULL THEN RAISE EXCEPTION 'national_supply_rescission_atomic_original_required';END IF;
 e:=jsonb_build_object('rulePackId',p_draft->>'canonicalRulePackId','messageProfileId',p_draft->>'ruleProfileVersionId','profileKey',p_draft->>'ruleProfileKey','version',p_draft->>'ruleProfileVersion','sourceHash',p_draft->>'rulePackChecksum','snapshot',p_draft->'rulePackSnapshot');
 INSERT INTO gridex_supply_rescission.outbound_operations(message_id,company_id,environment,actor_user_id,mandate_id,payload_hash,capability,creation_txid) VALUES(mid,p_company_id,env,p_actor_user_id,(p_draft->>'sourceOperationId')::uuid,cap->>'payloadHash',cap,txid_current());
 sealed:=gridex_ediel_outbound_owner.prepare_v1(jsonb_build_object('companyId',p_company_id,'actorUserId',p_actor_user_id,'environment',env,'rawPayload',raw,'rulePackEvidence',e,'nationalOriginalMessageId',mid));
 INSERT INTO gridex_supply_rescission.outbound_receipts(message_id,company_id,witness_id,payload_hash) VALUES(mid,p_company_id,(sealed->>'witnessId')::uuid,cap->>'payloadHash');
 INSERT INTO public.ediel_messages(id,company_id,environment,direction,message_standard,message_family,message_code,status,created_by,updated_by,raw_payload,canonical_rule_pack_id,rule_profile_key,rule_profile_version_id,rule_profile_version,rule_pack_checksum,rule_pack_snapshot,execution_context_snapshot,tenant_resolution_status,business_match_status,processing_status,message_version,process_type,transport_type,mailbox,sender_ediel_id,sender_name,sender_sub_address,receiver_ediel_id,receiver_name,receiver_sub_address,sender_email,receiver_email,subject,file_name,mime_type,interchange_reference,external_reference,correlation_reference,transaction_reference,application_reference,original_message_id,original_transaction_id,original_message_code,source_operation_id,transport_security_mode,route_transport_security_mode,contrl_status,aperak_status,utilts_err_status,communication_route_id,route_profile_id,intent_id,party_id,party_address_id,expected_receiver_certificate_id,outbound_request_id,switch_request_id,grid_owner_data_request_id,partner_export_id,customer_id,site_id,metering_point_id,grid_owner_id,parsed_payload,validation_report,requires_contrl,requires_aperak,was_smime_encrypted,cms_expected_receiver_present,test_flag,unb_sender_id,unb_receiver_id,unb_sender_subaddress,unb_receiver_subaddress,message_reference,bgm_code,bgm_reference)
 VALUES(mid,p_company_id,env,'outbound','edifact','PRODAT',cap->>'messageCode',coalesce(p_draft->>'status','draft'),p_actor_user_id,p_actor_user_id,raw,(e->>'rulePackId')::uuid,e->>'profileKey',(e->>'messageProfileId')::uuid,e->>'version',e->>'sourceHash',e->'snapshot',jsonb_build_object('outboundOwnerWitnessId',sealed->>'witnessId'),'tenant_resolved','not_checked',coalesce(p_draft->>'status','draft'),p_draft->>'messageVersion',p_draft->>'processType',p_draft->>'transportType',p_draft->>'mailbox',p_draft->>'senderEdielId',p_draft->>'senderName',p_draft->>'senderSubAddress',p_draft->>'receiverEdielId',p_draft->>'receiverName',p_draft->>'receiverSubAddress',p_draft->>'senderEmail',p_draft->>'receiverEmail',p_draft->>'subject',p_draft->>'fileName',p_draft->>'mimeType',p_draft->>'interchangeReference',p_draft->>'externalReference',p_draft->>'correlationReference',p_draft->>'transactionReference',p_draft->>'applicationReference',p_draft->>'originalMessageId',p_draft->>'originalTransactionId',p_draft->>'originalMessageCode',p_draft->>'sourceOperationId',p_draft->>'transportSecurityMode',p_draft->>'routeTransportSecurityMode',p_draft->>'contrlStatus',p_draft->>'aperakStatus',p_draft->>'utiltsErrStatus',nullif(p_draft->>'communicationRouteId','')::uuid,nullif(p_draft->>'routeProfileId','')::uuid,nullif(p_draft->>'intentId','')::uuid,nullif(p_draft->>'partyId','')::uuid,NULL,nullif(p_draft->>'expectedReceiverCertificateId','')::uuid,nullif(p_draft->>'outboundRequestId','')::uuid,nullif(p_draft->>'switchRequestId','')::uuid,nullif(p_draft->>'gridOwnerDataRequestId','')::uuid,nullif(p_draft->>'partnerExportId','')::uuid,nullif(p_draft->>'customerId','')::uuid,nullif(p_draft->>'siteId','')::uuid,nullif(p_draft->>'meteringPointId','')::uuid,nullif(p_draft->>'gridOwnerId','')::uuid,coalesce(p_draft->'parsedPayload','{}'::jsonb),coalesce(p_draft->'validationReport','{}'::jsonb),(p_draft->>'requiresContrl')::boolean,(p_draft->>'requiresAperak')::boolean,(p_draft->>'wasSmimeEncrypted')::boolean,(p_draft->>'cmsExpectedReceiverPresent')::boolean,coalesce((p_draft->>'testFlag')::integer,CASE env WHEN 'test' THEN 1 ELSE 0 END),p_draft->>'senderEdielId',p_draft->>'receiverEdielId',p_draft->>'senderSubAddress',p_draft->>'receiverSubAddress',p_draft->>'originalMessageId',cap->>'messageCode',p_draft->>'externalReference') RETURNING * INTO m;
 PERFORM gridex_ediel_source_rules.capture_v1(m.company_id,m.id);
 IF m.message_code='Z03' THEN
  UPDATE public.ediel_message_intents SET ediel_message_id=m.id,outbound_request_id=m.outbound_request_id,render_status='rendered',updated_at=now() WHERE id=m.intent_id AND company_id=m.company_id;
  PERFORM public.ediel_bind_switch_original_v1(m.company_id,m.switch_request_id,m.id,p_actor_user_id);
 END IF;
 IF m.message_code='Z08' THEN UPDATE public.ediel_message_intents SET ediel_message_id=m.id,outbound_request_id=m.outbound_request_id,render_status='rendered',updated_at=now() WHERE id=m.intent_id AND company_id=m.company_id;END IF;
 -- Immutable own references and created event are part of the same transaction.
 IF coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id) IS NOT NULL THEN
 FOR reference IN SELECT DISTINCT reference_type,reference_value FROM (
 SELECT 'UNB_REF'::text reference_type,m.interchange_reference reference_value UNION ALL SELECT 'BGM_REF',m.external_reference
 UNION ALL SELECT 'RFF_'||(t#>>'{elements,1,0}'),t#>>'{elements,1,1}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}' IN('LI','ACW','Z07','TN')) refs WHERE nullif(reference_value,'') IS NOT NULL LOOP
  IF EXISTS(SELECT FROM public.ediel_business_references existing WHERE existing.company_id=m.company_id AND existing.reference_type=reference.reference_type AND existing.reference_value=reference.reference_value AND existing.business_object_type=CASE WHEN m.switch_request_id IS NOT NULL THEN 'supplier_switch_request' WHEN m.grid_owner_data_request_id IS NOT NULL THEN 'grid_owner_data_request' WHEN m.outbound_request_id IS NOT NULL THEN 'outbound_request' ELSE 'partner_export' END AND existing.business_object_id=coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id) AND existing.source_message_id IS DISTINCT FROM m.id) THEN RAISE EXCEPTION 'national_supply_rescission_reference_owner_conflict';END IF;
  INSERT INTO public.ediel_business_references(company_id,source_message_id,reference_type,reference_value,message_family,message_code,business_object_type,business_object_id,customer_id,customer_site_id,metering_point_id)
   VALUES(m.company_id,m.id,reference.reference_type,reference.reference_value,m.message_family,m.message_code,CASE WHEN m.switch_request_id IS NOT NULL THEN 'supplier_switch_request' WHEN m.grid_owner_data_request_id IS NOT NULL THEN 'grid_owner_data_request' WHEN m.outbound_request_id IS NOT NULL THEN 'outbound_request' ELSE 'partner_export' END,coalesce(m.switch_request_id,m.grid_owner_data_request_id,m.outbound_request_id,m.partner_export_id),m.customer_id,m.site_id,m.metering_point_id)
   ON CONFLICT(company_id,reference_type,reference_value,business_object_type,business_object_id) DO NOTHING;
 END LOOP;END IF;
 INSERT INTO public.ediel_message_events(company_id,ediel_message_id,message_id,event_type,event_status,message,payload,event_payload,created_by)
 VALUES(m.company_id,m.id,m.id,'created','info','National legal supply rescission original created by atomic source owner',jsonb_build_object('sourceOperationId',m.source_operation_id,'payloadHash',cap->>'payloadHash'),jsonb_build_object('owner','national_supply_rescission_atomic_v1'),p_actor_user_id);
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,m.company_id,'ediel_message',m.id,'ediel.supply_rescission.original_registered',jsonb_build_object('payloadHash',cap->>'payloadHash','objects',cap->'objects'));
 PERFORM gridex_supply_rescission.require_original_v1(m,false);
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_producer_forbidden' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('version',1,'message',to_jsonb(m),'replayed',false);
END$$;

--
-- Name: ediel_create_outbound_ack_atomic_v1(uuid, text, uuid, text, uuid, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_create_outbound_ack_atomic_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_actor_user_id uuid, p_ack_family text, p_sequence_field text, p_sequence_value text, p_outcome text, p_draft jsonb, p_common_smtp jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 RETURN gridex_ediel_ack_replay.create_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_actor_user_id,p_ack_family,p_sequence_field,p_sequence_value,p_outcome,p_draft,p_common_smtp);END $$;

--
-- Name: ediel_create_outbound_ack_scope_atomic_v2(uuid, text, uuid, text, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_create_outbound_ack_scope_atomic_v2(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_actor_user_id uuid, p_ack_family text, p_outcome text, p_draft jsonb, p_common_smtp jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN gridex_ediel_ack_replay.create_scope_v2(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_actor_user_id,p_ack_family,NULL,NULL,p_outcome,p_draft,p_common_smtp);END $$;

--
-- Name: ediel_current_retention_companies_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_current_retention_companies_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=public.ediel_retention_session_actor_v1();company record;session jsonb;rows jsonb:='[]'::jsonb;n integer:=0;BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'retention_current_session_actor_required' USING ERRCODE='42501';END IF;
 LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(actor);PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;
 FOR company IN SELECT c.id,c.name,c.status FROM public.company_memberships m JOIN public.companies c ON c.id=m.company_id WHERE m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL AND c.status IN('active','archived','pending_deletion','closed') ORDER BY c.id LIMIT 1001 LOOP
  n:=n+1;IF n>1000 THEN RAISE EXCEPTION 'retention_current_company_list_bound';END IF;
  BEGIN
   session:=public.ediel_current_retention_session_v1(company.id,actor);
   rows:=rows||jsonb_build_array(jsonb_build_object('companyId',company.id,'name',company.name,'status',company.status,'permissions',session->'permissions'));
  EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 END LOOP;
 RETURN rows;
END$$;

--
-- Name: ediel_current_retention_session_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_current_retention_session_v1(p_company_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wanted text;own_class text;allowed text[]:=ARRAY[]::text[];BEGIN
 LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(p_actor_user_id);PERFORM id FROM public.user_profiles WHERE id=p_actor_user_id FOR SHARE;PERFORM id FROM public.companies WHERE id=p_company_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id FOR SHARE;
 IF public.ediel_retention_session_actor_v1() IS DISTINCT FROM p_actor_user_id THEN RAISE EXCEPTION 'retention_current_session_actor_required' USING ERRCODE='42501';END IF;
 FOREACH wanted IN ARRAY ARRAY['ediel.retention.read','ediel.retention.submit','ediel.retention.review','ediel.retention.purge','ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.contract_pdf','ediel.retention.signature','ediel.retention.address_history','ediel.retention.portal_history','ediel.retention.legal_history','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'] LOOP
  SELECT retention_class INTO own_class FROM gridex_ediel_retention.record_class_catalog WHERE permission_key=wanted ORDER BY retention_class LIMIT 1;IF wanted='ediel.retention.read' THEN own_class:='__read_scope__';END IF;
  IF (own_class IS NOT NULL AND gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,own_class) IS TRUE) OR (own_class IS NULL AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,wanted) IS TRUE) THEN allowed:=array_append(allowed,wanted);END IF;
 END LOOP;
 IF NOT allowed&&ARRAY['ediel.retention.read','ediel.retention.submit','ediel.retention.review','ediel.retention.purge'] OR NOT allowed&&ARRAY['ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.contract_pdf','ediel.retention.signature','ediel.retention.address_history','ediel.retention.portal_history','ediel.retention.legal_history','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'] THEN RAISE EXCEPTION 'retention_current_explicit_session_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('companyId',p_company_id,'actorUserId',p_actor_user_id,'permissions',allowed);
END$$;

--
-- Name: ediel_customer_event_certification_basis_v1(uuid, uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_event_certification_basis_v1(p_company_id uuid, p_run_id uuid, p_step_no integer, p_actor_user_id uuid, p_raw_payload text, p_expected_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE q jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_event_service_required' USING ERRCODE='42501';END IF;
 IF p_expected_outcome='positive' THEN q:=gridex_negative_fixtures.read_positive_v1(jsonb_build_object('companyId',p_company_id,'runId',p_run_id,'stepNo',p_step_no,'actorUserId',p_actor_user_id,'rawPayload',p_raw_payload));
 ELSIF p_expected_outcome='negative' THEN q:=gridex_negative_fixtures.read_negative_preparation_v1(jsonb_build_object('companyId',p_company_id,'runId',p_run_id,'stepNo',p_step_no,'actorUserId',p_actor_user_id,'rawPayload',p_raw_payload));
 ELSE RAISE EXCEPTION 'customer_event_fixture_outcome_required';END IF;
 RETURN gridex_customer_life_events.certification_basis_v1(q,p_raw_payload);
END$$;

--
-- Name: ediel_customer_event_certification_original_v1(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_event_certification_original_v1(p_company_id uuid, p_run_id uuid, p_step_no integer, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE candidate record;wire jsonb;q jsonb;basis jsonb;selected jsonb;context jsonb;seen integer:=0;held boolean:=false;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_event_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(p_actor_user_id,p_company_id);
 FOR candidate IN SELECT id,original_wire,'positive'::text outcome FROM gridex_negative_fixtures.positive_originals WHERE company_id=p_company_id AND run_id=p_run_id AND step_no=p_step_no
  UNION ALL SELECT id,original_wire,'negative'::text FROM gridex_negative_fixtures.originals WHERE company_id=p_company_id AND run_id=p_run_id AND step_no=p_step_no ORDER BY id LOOP
  seen:=seen+1;IF seen>8192 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('bounded_unambiguous_registered_customer_event_test_original'));END IF;
  wire:=gridex_customer_life_events.wire_partition_v1(candidate.original_wire);
  IF wire->>'code' IS DISTINCT FROM 'Z09' OR NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'reason'='E34') THEN CONTINUE;END IF;
  context:=jsonb_build_object('companyId',p_company_id,'runId',p_run_id,'stepNo',p_step_no,'actorUserId',p_actor_user_id,'rawPayload',candidate.original_wire);
  IF candidate.outcome='positive' THEN q:=gridex_negative_fixtures.read_positive_v1(context);ELSE q:=gridex_negative_fixtures.read_negative_preparation_v1(context);END IF;
  IF q IS NULL THEN CONTINUE;END IF;
  IF q->>'registrationId' IS DISTINCT FROM candidate.id::text THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('unambiguous_registered_customer_event_test_original'));END IF;
  basis:=gridex_customer_life_events.certification_basis_v1(q,candidate.original_wire);
  IF basis->>'status' IS DISTINCT FROM 'authorized' THEN held:=true;CONTINUE;END IF;
  IF selected IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('unambiguous_registered_customer_event_test_original'));END IF;
  selected:=basis;
 END LOOP;
 IF held THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('independent_authentic_certification_customer_event_classification'));END IF;
 RETURN selected;
END$$;

--
-- Name: ediel_customer_event_certification_preparation_basis_v1(uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_event_certification_preparation_basis_v1(p_company_id uuid, p_run_id uuid, p_step_no integer, p_actor_user_id uuid, p_raw_payload text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE wire jsonb;positive jsonb;negative jsonb;context jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_event_service_required' USING ERRCODE='42501';END IF;
 wire:=gridex_customer_life_events.wire_partition_v1(p_raw_payload);
 IF wire->>'code' IS DISTINCT FROM 'Z09' OR NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects')o WHERE o->>'reason'='E34') THEN RETURN NULL;END IF;
 PERFORM gridex_negative_fixtures.assert_prepare_actor_v1(p_actor_user_id,p_company_id);
 context:=jsonb_build_object('companyId',p_company_id,'runId',p_run_id,'stepNo',p_step_no,'actorUserId',p_actor_user_id,'rawPayload',p_raw_payload);
 positive:=gridex_negative_fixtures.read_positive_v1(context);negative:=gridex_negative_fixtures.read_negative_preparation_v1(context);
 IF positive IS NOT NULL AND negative IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('unambiguous_registered_customer_event_test_original'));END IF;
 IF positive IS NULL AND negative IS NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('authentic_registered_customer_event_test_original'));END IF;
 RETURN gridex_customer_life_events.certification_basis_v1(coalesce(positive,negative),p_raw_payload);
END$$;

--
-- Name: ediel_customer_life_event_boundaries_v1(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_boundaries_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE epoch timestamptz;projection jsonb;boundaries jsonb:='[]';BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT FROM gridex_customer_life_events.customer_versions scoped_customer_event JOIN gridex_bilateral_customer_sources.life_event_classification_origins origin ON origin.source_message_id=scoped_customer_event.source_message_id AND origin.company_id=scoped_customer_event.company_id WHERE scoped_customer_event.company_id=p_company_id AND scoped_customer_event.customer_id=p_customer_id)
  AND gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN
  RAISE EXCEPTION 'classified_customer_personal_history_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(p_company_id,p_actor_user_id,'read');
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to THEN RAISE EXCEPTION 'customer_life_event_boundary_period_required';END IF;
 IF NOT EXISTS(SELECT FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'customer_life_event_projection_tenant_scope_required';END IF;
 -- Source locks use the same order as mutation owners. Source assessments and
 -- their availability cannot change between epoch discovery and projection.
 PERFORM m.id FROM public.ediel_messages m WHERE m.company_id=p_company_id AND m.id IN(SELECT v.source_message_id FROM gridex_customer_life_events.customer_versions v WHERE v.company_id=p_company_id AND v.customer_id=p_customer_id AND v.effective_at<p_to) ORDER BY m.id FOR UPDATE;
 projection:=public.ediel_customer_life_event_export_at_v1(p_company_id,p_customer_id,p_actor_user_id,p_from);
 IF projection->>'status'='held' THEN RETURN projection;END IF;
 FOR epoch IN SELECT DISTINCT effective_at FROM gridex_customer_life_events.customer_versions WHERE company_id=p_company_id AND customer_id=p_customer_id AND effective_at>=p_from AND effective_at<p_to ORDER BY effective_at LOOP
  projection:=public.ediel_customer_life_event_export_at_v1(p_company_id,p_customer_id,p_actor_user_id,epoch);
  IF projection->>'status' IS DISTINCT FROM 'authorized' OR (projection->>'effectiveVersionCount')::integer<1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['qualified_customer_event_epoch_projection']);END IF;
  boundaries:=boundaries||jsonb_build_array(jsonb_build_object('effectiveAt',epoch,'sourceMessageId',projection->>'sourceMessageId','customerVersion',projection->'customerVersion','projection',projection));
 END LOOP;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'customerId',p_customer_id,'from',p_from,'to',p_to,'boundaries',boundaries);
END$$;

--
-- Name: ediel_customer_life_event_brp_scope_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_brp_scope_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;ev gridex_customer_life_events.events%rowtype;wire jsonb;scope jsonb;own jsonb;scopes jsonb:='[]';BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 basis:=gridex_customer_life_events.source_before_dated_brp_v1(p_company_id,p_event_id,p_actor_user_id,'prepare');IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;END IF;
 SELECT * INTO STRICT ev FROM gridex_customer_life_events.events WHERE id=p_event_id AND company_id=p_company_id;wire:=gridex_customer_life_events.wire_v1(basis->>'rawPayload');
 FOR scope IN SELECT item FROM jsonb_array_elements(ev.approved_scope)item LOOP
  SELECT item INTO own FROM jsonb_array_elements(wire->'objects')item WHERE item->>'point'=scope->>'pointId' AND item->>'identityAgency'=scope->>'identityAgency';
  scopes:=scopes||jsonb_build_array(jsonb_build_object('companyId',p_company_id,'environment',ev.environment,'contractId',NULL,'customerId',ev.customer_id,'siteId',scope->>'siteId','meteringPointId',scope->>'meteringPointId','at',own->>'effectiveAt','supplyPeriodId',scope->>'periodId'));
 END LOOP;RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'eventId',p_event_id,'scopes',scopes);
END$$;

--
-- Name: ediel_customer_life_event_committed_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_committed_source_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tr gridex_customer_life_events.transitions%rowtype;m public.ediel_messages%rowtype;sc jsonb;versions jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(p_company_id,p_actor_user_id,'prepare');
 SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=p_message_id AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id;
 IF tr.source_message_id IS NULL OR m.id IS NULL OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT jsonb_agg(jsonb_build_object('customerId',v.customer_id,'version',v.version,'effectiveAt',v.effective_at)) INTO versions FROM gridex_customer_life_events.customer_versions v WHERE v.source_message_id=m.id AND v.company_id=p_company_id;
 RETURN jsonb_build_object('version',1,'sourceMessageId',m.id,'sourcePayloadHash',tr.payload_hash,'companyId',p_company_id,'environment',m.environment,'rawPayload',m.raw_payload,'legalContext',tr.legal_context,'sourceObjects',tr.source_objects,'scopes',tr.approved_scope,'customerVersions',versions,'canonicalAssessmentId',tr.canonical_assessment_id,'observedAt',tr.observed_at);
END$$;

--
-- Name: ediel_customer_life_event_export_at_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_export_at_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_customer_life_events.customer_versions%rowtype;tr gridex_customer_life_events.transitions%rowtype;a gridex_received_sources.object_assessments%rowtype;sc jsonb;entry jsonb;own jsonb;
 patch jsonb:='{}';address jsonb:='{}';fields text[];n text;phase text;version_count integer:=0;last_source uuid;last_version bigint;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 IF p_as_of IS NULL OR NOT isfinite(p_as_of) THEN RAISE EXCEPTION 'customer_life_event_export_date_required';END IF;
 IF NOT EXISTS(SELECT FROM gridex_customer_life_events.customer_versions WHERE company_id=p_company_id AND customer_id=p_customer_id) THEN RETURN jsonb_build_object('status','not_applicable');END IF;
 phase:=CASE WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.read'),false) THEN 'read' WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) THEN 'prepare' ELSE 'send' END;
 IF EXISTS(SELECT FROM gridex_customer_life_events.customer_versions scoped_customer_event JOIN gridex_bilateral_customer_sources.life_event_classification_origins origin ON origin.source_message_id=scoped_customer_event.source_message_id AND origin.company_id=scoped_customer_event.company_id WHERE scoped_customer_event.company_id=p_company_id AND scoped_customer_event.customer_id=p_customer_id)
  AND gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN
  RAISE EXCEPTION 'classified_customer_personal_history_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(p_company_id,p_actor_user_id,phase);
 IF NOT EXISTS(SELECT FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'customer_life_event_projection_tenant_scope_required';END IF;
 FOR v IN SELECT * FROM gridex_customer_life_events.customer_versions WHERE company_id=p_company_id AND customer_id=p_customer_id AND effective_at<=p_as_of ORDER BY effective_at,version LOOP
  SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=v.source_message_id AND company_id=p_company_id;
  IF (SELECT count(*) FROM gridex_received_sources.object_assessments oa WHERE oa.source_message_id=v.source_message_id AND oa.company_id=p_company_id AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=oa.id))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_primary_customer_event_owner']);END IF;
  SELECT oa.* INTO a FROM gridex_received_sources.object_assessments oa JOIN gridex_received_sources.object_availability_witnesses aw ON aw.assessment_id=oa.id AND aw.company_id=oa.company_id AND aw.environment=oa.environment AND aw.source_message_id=oa.source_message_id AND aw.facts_hash=oa.facts_hash
   WHERE oa.source_message_id=v.source_message_id AND oa.company_id=p_company_id AND oa.source_payload_hash=tr.payload_hash AND oa.facts_hash=encode(sha256(convert_to(oa.facts_text,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=oa.id);
  IF a.id IS NULL OR jsonb_typeof(a.facts_text::jsonb->'objects') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['committed_primary_customer_event_availability']);END IF;
  FOR sc IN SELECT value FROM jsonb_array_elements(tr.approved_scope) WHERE value->>'customerId'=p_customer_id::text LOOP
   IF (SELECT count(*) FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=sc->>'pointId' AND obj#>>'{object,identityAgency}'=sc->>'identityAgency')<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_customer_event_primary_scope']);END IF;
   SELECT obj INTO entry FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=sc->>'pointId' AND obj#>>'{object,identityAgency}'=sc->>'identityAgency';
   IF entry->>'disposition' IS DISTINCT FROM 'accepted' OR gridex_customer_life_events.owner_proof_consistent_v1(entry->'party',entry->'business',v.source_message_id) IS DISTINCT FROM true THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_qualified_customer_event_projection']);END IF;
  END LOOP;
  SELECT scope INTO sc FROM jsonb_array_elements(tr.approved_scope) scope WHERE scope->>'customerId'=p_customer_id::text LIMIT 1;
  SELECT obj INTO own FROM jsonb_array_elements(tr.source_objects) obj WHERE obj->>'point'=sc->>'pointId' AND obj->>'identityAgency'=sc->>'identityAgency';
  SELECT array_agg(f) INTO fields FROM jsonb_array_elements_text(sc->'allowedFields') f;
  IF '228'=ANY(fields) AND jsonb_typeof(own->'name')='array' THEN SELECT string_agg(part,' ' ORDER BY ord) INTO n FROM jsonb_array_elements_text(own->'name') WITH ORDINALITY x(part,ord);patch:=patch||jsonb_build_object('name',n,'full_name',n);IF own#>>'{customerParty,1}'='SE1' THEN patch:=patch||jsonb_build_object('company_name',n);END IF;address:=address||jsonb_build_object('name',own->'name');END IF;
  IF '227'=ANY(fields) THEN patch:=patch||jsonb_build_object(CASE own#>>'{customerParty,1}' WHEN 'SE1' THEN 'org_number' ELSE 'personal_number' END,own#>>'{customerParty,0}');END IF;
  IF '229'=ANY(fields) AND jsonb_typeof(own->'street')='array' THEN address:=address||jsonb_build_object('street',own->'street');END IF;
  IF '231'=ANY(fields) AND own->>'postCode' IS NOT NULL THEN address:=address||jsonb_build_object('postCode',own->>'postCode');END IF;
  IF '232'=ANY(fields) AND own->>'city' IS NOT NULL THEN address:=address||jsonb_build_object('city',own->>'city');END IF;
  IF '316'=ANY(fields) AND own->>'country' IS NOT NULL THEN address:=address||jsonb_build_object('country',own->>'country');END IF;
  version_count:=version_count+1;last_source:=v.source_message_id;last_version:=v.version;
 END LOOP;
 IF EXISTS(
  SELECT FROM gridex_customer_life_events.customer_versions future
  JOIN gridex_customer_life_events.transitions later ON later.source_message_id=future.source_message_id AND later.company_id=future.company_id
  CROSS JOIN LATERAL jsonb_array_elements(later.approved_scope) later_scope
  CROSS JOIN LATERAL jsonb_array_elements_text(later_scope->'allowedFields') field
  WHERE future.company_id=p_company_id AND future.customer_id=p_customer_id AND future.effective_at>p_as_of AND later_scope->>'customerId'=p_customer_id::text
   AND field IN('227','228','229','231','232','316')
   AND NOT EXISTS(
    SELECT FROM gridex_customer_life_events.customer_versions prior
    JOIN gridex_customer_life_events.transitions earlier ON earlier.source_message_id=prior.source_message_id AND earlier.company_id=prior.company_id
    CROSS JOIN LATERAL jsonb_array_elements(earlier.approved_scope) earlier_scope
    WHERE prior.company_id=p_company_id AND prior.customer_id=p_customer_id AND prior.effective_at<=p_as_of AND earlier_scope->>'customerId'=p_customer_id::text AND (earlier_scope->'allowedFields') ? field
   )
 ) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_qualified_customer_masterdata_at_requested_time']);END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'customerId',p_customer_id,'asOf',p_as_of,'sourceMessageId',last_source,'customerVersion',last_version,'effectiveVersionCount',version_count,'customerFields',patch,'endUserMasterdata',address);
END$$;

--
-- Name: ediel_customer_life_event_export_projection_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_export_projection_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_customer_life_events.customer_versions%rowtype;tr gridex_customer_life_events.transitions%rowtype;a gridex_received_sources.object_assessments%rowtype;sc jsonb;entry jsonb;own jsonb;
 patch jsonb:='{}';address jsonb:='{}';fields text[];n text;phase text;version_count integer:=0;last_source uuid;last_version bigint;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM gridex_customer_life_events.customer_versions WHERE company_id=p_company_id AND customer_id=p_customer_id) THEN RETURN jsonb_build_object('status','not_applicable');END IF;
 phase:=CASE WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.read'),false) THEN 'read' WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) THEN 'prepare' ELSE 'send' END;
 IF EXISTS(SELECT FROM gridex_customer_life_events.customer_versions scoped_customer_event JOIN gridex_bilateral_customer_sources.life_event_classification_origins origin ON origin.source_message_id=scoped_customer_event.source_message_id AND origin.company_id=scoped_customer_event.company_id WHERE scoped_customer_event.company_id=p_company_id AND scoped_customer_event.customer_id=p_customer_id)
  AND gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN
  RAISE EXCEPTION 'classified_customer_personal_history_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(p_company_id,p_actor_user_id,phase);
 IF NOT EXISTS(SELECT FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'customer_life_event_projection_tenant_scope_required';END IF;
 FOR v IN SELECT * FROM gridex_customer_life_events.customer_versions WHERE company_id=p_company_id AND customer_id=p_customer_id AND effective_at<=clock_timestamp() ORDER BY effective_at,version LOOP
  SELECT * INTO tr FROM gridex_customer_life_events.transitions WHERE source_message_id=v.source_message_id AND company_id=p_company_id;
  IF (SELECT count(*) FROM gridex_received_sources.object_assessments oa WHERE oa.source_message_id=v.source_message_id AND oa.company_id=p_company_id AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=oa.id))<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_primary_customer_event_owner']);END IF;
  SELECT oa.* INTO a FROM gridex_received_sources.object_assessments oa JOIN gridex_received_sources.object_availability_witnesses aw ON aw.assessment_id=oa.id AND aw.company_id=oa.company_id AND aw.environment=oa.environment AND aw.source_message_id=oa.source_message_id AND aw.facts_hash=oa.facts_hash
   WHERE oa.source_message_id=v.source_message_id AND oa.company_id=p_company_id AND oa.source_payload_hash=tr.payload_hash AND oa.facts_hash=encode(sha256(convert_to(oa.facts_text,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=oa.id);
  IF a.id IS NULL OR jsonb_typeof(a.facts_text::jsonb->'objects') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['committed_primary_customer_event_availability']);END IF;
  FOR sc IN SELECT value FROM jsonb_array_elements(tr.approved_scope) WHERE value->>'customerId'=p_customer_id::text LOOP
   IF (SELECT count(*) FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=sc->>'pointId' AND obj#>>'{object,identityAgency}'=sc->>'identityAgency')<>1 THEN RETURN jsonb_build_object('status','held','missing',ARRAY['whole_customer_event_primary_scope']);END IF;
   SELECT obj INTO entry FROM jsonb_array_elements(a.facts_text::jsonb->'objects') obj WHERE obj#>>'{object,objectId}'=sc->>'pointId' AND obj#>>'{object,identityAgency}'=sc->>'identityAgency';
   IF entry->>'disposition' IS DISTINCT FROM 'accepted' OR gridex_customer_life_events.owner_proof_consistent_v1(entry->'party',entry->'business',v.source_message_id) IS DISTINCT FROM true THEN RETURN jsonb_build_object('status','held','missing',ARRAY['source_qualified_customer_event_projection']);END IF;
  END LOOP;
  SELECT scope INTO sc FROM jsonb_array_elements(tr.approved_scope) scope WHERE scope->>'customerId'=p_customer_id::text LIMIT 1;
  SELECT obj INTO own FROM jsonb_array_elements(tr.source_objects) obj WHERE obj->>'point'=sc->>'pointId' AND obj->>'identityAgency'=sc->>'identityAgency';
  SELECT array_agg(f) INTO fields FROM jsonb_array_elements_text(sc->'allowedFields') f;
  IF '228'=ANY(fields) AND jsonb_typeof(own->'name')='array' THEN SELECT string_agg(part,' ' ORDER BY ord) INTO n FROM jsonb_array_elements_text(own->'name') WITH ORDINALITY x(part,ord);patch:=patch||jsonb_build_object('name',n,'full_name',n);IF own#>>'{customerParty,1}'='SE1' THEN patch:=patch||jsonb_build_object('company_name',n);END IF;address:=address||jsonb_build_object('name',own->'name');END IF;
  IF '227'=ANY(fields) THEN patch:=patch||jsonb_build_object(CASE own#>>'{customerParty,1}' WHEN 'SE1' THEN 'org_number' ELSE 'personal_number' END,own#>>'{customerParty,0}');END IF;
  IF '229'=ANY(fields) AND jsonb_typeof(own->'street')='array' THEN address:=address||jsonb_build_object('street',own->'street');END IF;
  IF '231'=ANY(fields) AND own->>'postCode' IS NOT NULL THEN address:=address||jsonb_build_object('postCode',own->>'postCode');END IF;
  IF '232'=ANY(fields) AND own->>'city' IS NOT NULL THEN address:=address||jsonb_build_object('city',own->>'city');END IF;
  IF '316'=ANY(fields) AND own->>'country' IS NOT NULL THEN address:=address||jsonb_build_object('country',own->>'country');END IF;
  version_count:=version_count+1;last_source:=v.source_message_id;last_version:=v.version;
 END LOOP;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'customerId',p_customer_id,'sourceMessageId',last_source,'customerVersion',last_version,'effectiveVersionCount',version_count,'customerFields',patch,'endUserMasterdata',address);
END$$;

--
-- Name: ediel_customer_life_event_inbound_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_inbound_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;r gridex_customer_life_events.inbound_context_receipts%rowtype;digest text;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();

 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 b:=gridex_customer_life_events.inbound_basis_v1(p_company_id,p_message_id,p_actor_user_id);IF b IS NULL OR b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 digest:=encode(sha256(convert_to(b::text,'UTF8')),'hex');
 INSERT INTO gridex_customer_life_events.inbound_context_receipts(company_id,environment,source_message_id,payload_hash,context_facts,context_facts_hash,actor_user_id) VALUES(p_company_id,b->>'environment',p_message_id,b->>'sourcePayloadHash',b,digest,p_actor_user_id) ON CONFLICT DO NOTHING RETURNING * INTO r;
 IF r.id IS NULL THEN SELECT * INTO STRICT r FROM gridex_customer_life_events.inbound_context_receipts WHERE company_id=p_company_id AND source_message_id=p_message_id AND payload_hash=b->>'sourcePayloadHash' AND context_facts_hash=digest;END IF;
 RETURN b||jsonb_build_object('sourceContextReceiptId',r.id,'sourceContextFactsHash',digest);
END$$;

