 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 RETURN gridex_customer_life_events.require_current_v1(p_company_id,p_message_id,p_actor_user_id,CASE WHEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) THEN 'send' ELSE 'prepare' END);END $$;

--
-- Name: ediel_customer_life_event_patches_v1(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_customer_life_event_patches_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_cutoff timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT FROM gridex_customer_life_events.customer_versions scoped_customer_event JOIN gridex_bilateral_customer_sources.life_event_classification_origins origin ON origin.source_message_id=scoped_customer_event.source_message_id AND origin.company_id=scoped_customer_event.company_id WHERE scoped_customer_event.company_id=p_company_id AND scoped_customer_event.customer_id=p_customer_id)
  AND gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN
  RAISE EXCEPTION 'classified_customer_personal_history_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_customer_life_events.require_actor_v1(p_company_id,p_actor_user_id,'read');RETURN gridex_customer_life_events.qualified_patches_v1(p_company_id,p_customer_id,p_from,p_to,p_cutoff);
END$$;

