    SET search_path TO 'pg_catalog'
    AS $$BEGIN PERFORM gridex_ediel_retention.finance_actor_v1(p_company_id,p_actor_user_id,p_retention_class,CASE WHEN gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.read') THEN 'ediel.retention.read' ELSE 'ediel.retention.review' END);RETURN gridex_ediel_retention.finance_basis_v1(p_company_id,p_retention_class,p_target_id);END$$;

--
-- Name: ediel_finish_blob_storage_purge_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_finish_blob_storage_purge_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.blob_decisions%rowtype;t gridex_ediel_retention.blob_tombstones%rowtype;BEGIN
 PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.blob_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;SELECT * INTO STRICT t FROM gridex_ediel_retention.blob_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id;
 IF t.retention_class IS DISTINCT FROM 'transport_raw_mime_bytes' OR NOT EXISTS(SELECT FROM gridex_ediel_retention.blob_events WHERE retention_class=t.retention_class AND target_id=t.target_id AND kind='storage_delete_authorized') OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='ediel-files' AND name=t.storage_path) THEN RAISE EXCEPTION 'ediel_storage_actual_delete_receipt_required';END IF;
 IF EXISTS(SELECT FROM gridex_ediel_retention.blob_events WHERE retention_class=t.retention_class AND target_id=t.target_id AND kind='physical_bytes_removed') THEN RETURN jsonb_build_object('status','purged','targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'replay',true);END IF;
 INSERT INTO gridex_ediel_retention.blob_events(retention_class,target_id,kind,actor_user_id) VALUES(t.retention_class,t.target_id,'physical_bytes_removed',p_actor_user_id) ON CONFLICT DO NOTHING;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_message_payload',t.target_id,'ediel.retention.mime_bytes_removed',jsonb_build_object('decisionId',d.id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'physicalReceipt','authenticated_storage_delete_object_absence'));RETURN jsonb_build_object('status','purged','targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'replay',false);
END$$;

--
-- Name: ediel_finish_contract_document_retention_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_finish_contract_document_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.record_decisions%rowtype;t gridex_ediel_retention.record_tombstones%rowtype;spec gridex_ediel_retention.record_class_catalog%rowtype;assignments text;BEGIN
 PERFORM gridex_ediel_retention.record_actor_v1(p_company_id,p_actor_user_id,'contract_signed_pdf_bytes','ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.record_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;SELECT * INTO STRICT t FROM gridex_ediel_retention.record_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id;
 IF t.retention_class IS DISTINCT FROM 'contract_signed_pdf_bytes' OR NOT EXISTS(SELECT FROM gridex_ediel_retention.record_events WHERE retention_class=t.retention_class AND target_id=t.target_id AND kind='storage_delete_authorized') OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='customer-contract-documents' AND name=t.storage_path) THEN RAISE EXCEPTION 'contract_pdf_actual_storage_delete_receipt_required';END IF;
 IF NOT EXISTS(SELECT FROM gridex_ediel_retention.record_events WHERE retention_class=t.retention_class AND target_id=t.target_id AND kind='storage_object_absent') THEN
  UPDATE public.customer_contract_documents SET storage_path=NULL,generation_snapshot='{}' WHERE id=t.target_id AND company_id=t.company_id;
  INSERT INTO gridex_ediel_retention.record_events(retention_class,target_id,kind,actor_user_id) VALUES(t.retention_class,t.target_id,'storage_object_absent',p_actor_user_id);
  INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'customer_contract_document',t.target_id,'ediel.retention.contract_pdf_storage_absent',jsonb_build_object('decisionId',d.id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'nativeReceipt','authenticated_storage_delete_object_absence'));
  RETURN jsonb_build_object('status','storage_object_absent','retentionClass',t.retention_class,'targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'replay',false);
 END IF;RETURN jsonb_build_object('status','storage_object_absent','retentionClass',t.retention_class,'targetId',t.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'replay',true);
END$$;

--
-- Name: ediel_finish_invoice_file_purge_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_finish_invoice_file_purge_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.invoice_file_decisions%rowtype;s gridex_ediel_retention.invoice_file_sources%rowtype;other gridex_ediel_retention.invoice_file_sources%rowtype;BEGIN
 PERFORM gridex_ediel_retention.invoice_file_actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');SELECT * INTO STRICT d FROM gridex_ediel_retention.invoice_file_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;SELECT * INTO STRICT s FROM gridex_ediel_retention.invoice_file_sources WHERE id=d.source_id FOR SHARE;
 IF EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_events WHERE source_id=s.id AND kind='storage_object_absent') THEN RETURN jsonb_build_object('status','purged','sourceId',s.id,'sourceHash',s.source_hash,'byteLength',s.byte_length,'bytesAvailable',false,'replay',true);END IF;
 IF EXISTS(SELECT FROM storage.objects WHERE bucket_id=s.storage_bucket AND name=s.storage_path) THEN RAISE EXCEPTION 'invoice_file_native_storage_object_still_present';END IF;
 FOR other IN SELECT * FROM gridex_ediel_retention.invoice_file_sources WHERE storage_bucket=s.storage_bucket AND storage_path=s.storage_path ORDER BY id FOR SHARE LOOP
  IF other.company_id<>p_company_id OR NOT EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_tombstones WHERE source_id=other.id) OR NOT EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_events WHERE source_id=other.id AND kind='storage_delete_authorized') THEN RAISE EXCEPTION 'invoice_file_authenticated_storage_delete_receipt_required';END IF;
  INSERT INTO gridex_ediel_retention.invoice_file_events(source_id,kind,actor_user_id) VALUES(other.id,'storage_object_absent',p_actor_user_id) ON CONFLICT DO NOTHING;
 END LOOP;RETURN jsonb_build_object('status','purged','sourceId',s.id,'sourceHash',s.source_hash,'byteLength',s.byte_length,'bytesAvailable',false,'replay',false);END$$;

