CREATE FUNCTION public.ediel_invoice_file_storage_delete_target_v1(p_bucket text, p_path text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE s gridex_ediel_retention.invoice_file_sources%rowtype;actor uuid:=public.ediel_retention_session_actor_v1();n int:=0;BEGIN FOR s IN SELECT * FROM gridex_ediel_retention.invoice_file_sources WHERE storage_bucket=p_bucket AND storage_path=p_path LOOP n:=n+1;IF NOT EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_tombstones WHERE source_id=s.id) OR gridex_ediel_retention.permission_v1(s.company_id,actor,'ediel.retention.purge') IS NOT TRUE OR gridex_ediel_retention.permission_v1(s.company_id,actor,'ediel.retention.invoice_copy_evidence') IS NOT TRUE THEN RETURN false;END IF;END LOOP;RETURN n>0;END$$;

--
-- Name: ediel_is_duplicate_protocol_ack_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_is_duplicate_protocol_ack_v1(p_ack_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ediel_duplicate_responses.is_duplicate_ack_v1(p_ack_id) AND(coalesce(current_setting('role',true),'')='service_role' OR EXISTS(SELECT FROM public.ediel_messages m JOIN public.user_profiles u ON u.id=auth.uid() AND u.user_status='active' JOIN public.company_memberships cm ON cm.company_id=m.company_id AND cm.user_id=u.id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL WHERE m.id=p_ack_id AND(public.gridex_actor_has_company_permission(u.id,m.company_id,'communication.read') IS TRUE OR public.gridex_actor_has_company_permission(u.id,m.company_id,'communication.send') IS TRUE)))$$;

--
-- Name: ediel_is_qualified_customer_record_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_is_qualified_customer_record_transition_v1(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE spec gridex_ediel_retention.record_class_catalog%rowtype;t gridex_ediel_retention.record_tombstones%rowtype;BEGIN
 SELECT * INTO spec FROM gridex_ediel_retention.record_class_catalog WHERE source_table=p_table;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO t FROM gridex_ediel_retention.record_tombstones WHERE retention_class=spec.retention_class AND target_id=(p_old->>'id')::uuid AND company_id=(p_old->>'company_id')::uuid;
 IF NOT FOUND OR p_new IS NULL THEN RETURN false;END IF;
 IF encode(sha256(convert_to(p_old::text,'UTF8')),'hex') IS DISTINCT FROM t.target_hash AND (p_old-'updated_at') IS DISTINCT FROM (gridex_ediel_retention.record_redacted_v1(spec.retention_class,p_old)-'updated_at') THEN RETURN false;END IF;
 RETURN (p_new-'updated_at') IS NOT DISTINCT FROM (gridex_ediel_retention.record_redacted_v1(spec.retention_class,p_old)-'updated_at');
END$$;

--
-- Name: ediel_is_qualified_finance_retention_transition_v1(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_is_qualified_finance_retention_transition_v1(p_schema text, p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;t gridex_ediel_retention.finance_tombstones%rowtype;BEGIN SELECT * INTO spec FROM gridex_ediel_retention.finance_class_catalog WHERE source_schema=p_schema AND source_table=p_table;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO t FROM gridex_ediel_retention.finance_tombstones WHERE retention_class=spec.retention_class AND target_id=p_old->>spec.id_column;RETURN t.target_id IS NOT NULL AND t.company_id::text=p_old->>'company_id' AND t.target_hash=encode(sha256(convert_to(p_old::text,'UTF8')),'hex') AND p_new=gridex_ediel_retention.finance_redacted_v1(spec.retention_class,p_old,t.source_hash);END$$;

--
-- Name: ediel_is_qualified_process_retention_transition_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_is_qualified_process_retention_transition_v1(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE t gridex_ediel_retention.process_tombstones%rowtype;k text;BEGIN
 SELECT retention_class INTO k FROM gridex_ediel_retention.process_class_catalog WHERE source_table=p_table;SELECT * INTO t FROM gridex_ediel_retention.process_tombstones WHERE retention_class=k AND target_id=p_old->>'id';
 RETURN t.target_id IS NOT NULL AND t.company_id::text=p_old->>'company_id' AND t.target_hash=encode(sha256(convert_to(p_old::text,'UTF8')),'hex') AND p_new=gridex_ediel_retention.process_redacted_v1(k,p_old,t.source_hash);END$$;

--
-- Name: ediel_is_qualified_retention_transition_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_is_qualified_retention_transition_v1(oldrow public.ediel_messages, newrow public.ediel_messages) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT oldrow.raw_payload IS NOT NULL AND newrow.raw_payload IS NULL AND newrow.parsed_payload='{}'::jsonb AND newrow.validation_report='{}'::jsonb AND coalesce(newrow.metadata,'{}')='{}'::jsonb
 AND (to_jsonb(oldrow)-ARRAY['raw_payload','parsed_payload','validation_report','metadata','updated_at']) IS NOT DISTINCT FROM (to_jsonb(newrow)-ARRAY['raw_payload','parsed_payload','validation_report','metadata','updated_at'])
 AND EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class='received_ediel_message_content' AND t.target_id=oldrow.id AND t.company_id=oldrow.company_id AND t.source_hash=encode(sha256(convert_to(oldrow.raw_payload,'UTF8')),'hex') AND t.public_content_hash=encode(sha256(convert_to(gridex_ediel_retention.public_content_v1(oldrow)::text,'UTF8')),'hex'))
$$;

--
-- Name: ediel_list_business_acks_for_source_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_list_business_acks_for_source_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_environment text DEFAULT NULL::text, p_ack_family text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;m public.ediel_messages%rowtype;family text;source_family text;qualified jsonb;basis jsonb;entry jsonb;items jsonb:='[]';BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_business_ack_current_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO s FROM public.ediel_messages WHERE id=p_source_message_id AND direction='inbound' AND(company_id=p_company_id OR company_id IS NULL) FOR SHARE;
 IF s.id IS NULL OR(p_environment IS NOT NULL AND p_environment IS DISTINCT FROM s.environment) THEN RAISE EXCEPTION 'ediel_business_ack_original_scope_required';END IF;
 source_family:=coalesce(p_ack_family,CASE WHEN s.message_family IN('PRODAT','UTILTS','UTILTS_ERR') THEN 'APERAK' WHEN s.message_family='APERAK' THEN 'CONTRL' END);
 -- Even an empty candidate set requires the actual current private original.
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(p_company_id,s.environment,s.id,p_actor_user_id,source_family,NULL,'prepare');
 FOREACH family IN ARRAY CASE WHEN p_ack_family IS NULL THEN ARRAY['CONTRL','APERAK','UTILTS_ERR'] ELSE ARRAY[p_ack_family] END LOOP
  basis:=gridex_ack_authority.read_outbound_originals_v1(s.id,family);
  IF basis->>'sourceMessageId' IS DISTINCT FROM s.id::text OR basis->>'companyId' IS DISTINCT FROM p_company_id::text OR basis->>'environment' IS DISTINCT FROM s.environment THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(basis->'originals') LOOP
   IF entry->>'status' IS DISTINCT FROM 'qualified' THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
   m:=jsonb_populate_record(NULL::public.ediel_messages,entry->'message');
   qualified:=gridex_ediel_duplicate_responses.read_business_original_v1(p_company_id,s.environment,s.id,p_actor_user_id,family,m.id,'prepare');
   IF qualified#>>'{ackMessage,id}' IS DISTINCT FROM m.id::text THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
   items:=items||jsonb_build_array(qualified->'ackMessage');
  END LOOP;
 END LOOP;
 PERFORM gridex_ediel_duplicate_responses.require_actor_v1(p_company_id,p_actor_user_id,'prepare');
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(p_company_id,s.environment,s.id,p_actor_user_id,source_family,NULL,'prepare');
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'created_at' DESC,value->>'id' DESC),'[]') INTO items FROM jsonb_array_elements(items);
 RETURN jsonb_build_object('version',1,'companyId',p_company_id,'sourceMessageId',s.id,'environment',s.environment,'ackFamily',p_ack_family,'messages',items);
END$$;

