--
-- Name: ediel_metering_method_change_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_change_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_metering_method_changes.origins%rowtype;b jsonb;BEGIN
 PERFORM gridex_ai_processing.authorize_purpose_phase_v1(p_company_id,p_actor_user_id,'send',NULL);
 SELECT gridex_metering_method_changes.require_recovery_message_v1(m,p_actor_user_id,'send') INTO b FROM public.ediel_messages m WHERE m.company_id=p_company_id AND m.id=p_message_id;
 IF b IS NOT NULL THEN RETURN jsonb_build_object('basis',b,'intentId',(SELECT intent_id FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id));END IF;
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 b:=gridex_metering_method_changes.context_v1(o.company_id,o.event_id,p_actor_user_id,'send');
 IF b IS DISTINCT FROM o.basis THEN RETURN jsonb_build_object('status','held','missing',ARRAY['metering_method_change_current_source_changed']);END IF;
 PERFORM public.ediel_require_metering_method_change_source_current_v1(p_company_id,p_message_id,p_actor_user_id);
 RETURN jsonb_build_object('basis',b,'intentId',o.intent_id,'actorUserId',o.actor_user_id);
END$$;

--
-- Name: ediel_metering_method_change_scope_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_change_scope_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_metering_method_changes.context_before_brp_source_v1(p_company_id,p_event_id,p_actor_user_id,'origination')$$;

--
-- Name: ediel_metering_method_change_send_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_change_send_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;q jsonb;kind text;BEGIN
 -- This is the existing provider-phase permission/source owner, not a new
 -- guide decision or an environment-derived certification authorization.
 PERFORM public.ediel_require_metering_method_change_source_current_v1(p_company_id,p_message_id,p_actor_user_id);
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR SHARE;
 q:=gridex_metering_method_changes.certification_basis_v1(m);
 IF q IS NOT NULL THEN kind:='certification';
 ELSIF EXISTS(SELECT FROM gridex_requested_changes.origins o WHERE o.company_id=m.company_id AND o.message_id=m.id AND o.basis->>'variant' IN('F','G')) THEN
  IF gridex_metering_method_changes.frozen_original_basis_v1(m.company_id,m.id) IS NULL THEN RAISE EXCEPTION 'ediel_method_expectation_requested_original_required';END IF;kind:='agreement';
 ELSIF EXISTS(SELECT FROM gridex_metering_method_changes.recovery_receipts o WHERE o.company_id=m.company_id AND o.message_id=m.id) THEN kind:='agreement';
 ELSIF EXISTS(SELECT FROM gridex_metering_method_changes.origins o WHERE o.company_id=m.company_id AND o.message_id=m.id) THEN kind:='agreement';
 ELSE kind:='not_applicable';END IF;
 RETURN jsonb_build_object('version',1,'kind',kind,'companyId',m.company_id,'environment',m.environment,
  'messageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'intentId',m.intent_id);
END $$;

--
-- Name: ediel_metering_method_change_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_change_source_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_metering_method_changes.context_v1(p_company_id,p_event_id,p_actor_user_id)$$;

--
-- Name: ediel_metering_method_recovery_scope_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_recovery_scope_v1(p_company_id uuid, p_operation_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE q jsonb;op gridex_received_sources.prodat_recovery_operations%rowtype;o gridex_metering_method_changes.origins%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'prepare');
 PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(p_company_id,p_operation_id);q:=gridex_received_sources.qualified_recovery_origin_v1(p_company_id,p_operation_id);
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id;
 IF (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO o FROM gridex_metering_method_changes.origins WHERE company_id=p_company_id AND message_id=(q->>'sourceOriginMessageId')::uuid FOR SHARE;
 IF o.event_id IS NULL THEN RETURN NULL;END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'prepare');
 RETURN jsonb_build_object('companyId',p_company_id,'recoveryOperationId',op.id,'eventId',o.event_id,'originalMessageId',op.original_message_id,'sourceOriginMessageId',o.message_id,'environment',op.environment,'correctedPayloadHash',op.corrected_payload_hash);
END$$;

--
-- Name: ediel_metering_method_recovery_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_metering_method_recovery_source_v1(p_company_id uuid, p_operation_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$SELECT gridex_metering_method_changes.recovery_source_v1(p_company_id,p_operation_id,p_actor_user_id,'prepare')$$;

--
-- Name: ediel_originate_requested_change_before_scope_fence_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_originate_requested_change_before_scope_fence_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_route jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e gridex_requested_changes.events%rowtype;b jsonb;o gridex_requested_changes.origins%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;route public.ediel_route_profiles%rowtype;ref text;owned_site uuid;
BEGIN
 SELECT * INTO e FROM gridex_requested_changes.events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;b:=gridex_requested_changes.context_v1(p_company_id,p_event_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE event_id=e.id FOR UPDATE;
 IF FOUND THEN RETURN jsonb_build_object('status','originated','intentId',o.intent_id,'outboundRequestId',o.outbound_request_id,'messageId',o.message_id);END IF;

 SELECT site_id INTO owned_site FROM public.metering_points
  WHERE id=e.metering_point_id AND company_id=e.company_id AND customer_id=e.customer_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'requested_change_owned_point_site_required';END IF;
 IF owned_site IS NOT NULL THEN
  PERFORM id FROM public.customer_sites WHERE id=owned_site AND company_id=e.company_id AND customer_id=e.customer_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'requested_change_owned_point_site_required';END IF;
 END IF;
 SELECT * INTO route FROM public.ediel_route_profiles WHERE id=(p_route->>'routeProfileId')::uuid AND company_id=p_company_id AND environment=e.environment FOR SHARE;
 PERFORM id FROM public.communication_routes WHERE id=(p_route->>'communicationRouteId')::uuid AND company_id=p_company_id AND is_active FOR SHARE;
 IF NOT FOUND OR route.id IS NULL OR NOT route.is_enabled OR NOT route.is_active OR route.sender_ediel_id IS DISTINCT FROM p_route->>'senderEdielId' OR route.receiver_ediel_id IS DISTINCT FROM p_route->>'receiverEdielId' OR nullif(route.sender_sub_address,'') IS DISTINCT FROM nullif(p_route->>'senderSubaddress','') OR nullif(route.receiver_sub_address,'') IS DISTINCT FROM nullif(p_route->>'receiverSubaddress','') OR p_route->>'applicationReference' IS DISTINCT FROM '23-DDQ-PRODAT' THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_exact_owned_current_route']);END IF;
 ref:=replace(gen_random_uuid()::text,'-','');ref:=upper(substring(ref,1,14));
 INSERT INTO public.ediel_message_intents(company_id,environment,market,message_family,message_code,business_process,direction,sender_ediel_id,sender_subaddress,receiver_ediel_id,receiver_subaddress,application_reference,route_profile_id,communication_route_id,customer_id,customer_site_id,operation_id,metering_point_id,facility_id,grid_area_code,interchange_reference,message_reference,transaction_reference,payload,idempotency_key,created_by,updated_by)
 VALUES(p_company_id,e.environment,'electricity','PRODAT','Z09','customer_masterdata','outbound',route.sender_ediel_id,nullif(route.sender_sub_address,''),route.receiver_ediel_id,nullif(route.receiver_sub_address,''),'23-DDQ-PRODAT',route.id,(p_route->>'communicationRouteId')::uuid,e.customer_id,owned_site,e.id,e.point_id,e.point_id,e.grid_area_code,ref,'1',ref,jsonb_build_object('actorRole','supplier','requestedChangeEventId',e.id,'variant',e.variant),'requested-change:'||e.id::text,p_actor_user_id,p_actor_user_id) RETURNING * INTO i;
 INSERT INTO public.outbound_requests(company_id,customer_id,site_id,metering_point_id,communication_route_id,request_type,source_type,source_id,status,channel_type,payload,created_by,updated_by,operation_id)
 VALUES(p_company_id,e.customer_id,owned_site,e.metering_point_id,i.communication_route_id,'customer_masterdata','manual',i.id,'prepared','smtp',jsonb_build_object('requestedChangeEventId',e.id,'intentId',i.id),p_actor_user_id,p_actor_user_id,e.id) RETURNING * INTO r;
 INSERT INTO gridex_requested_changes.origins(event_id,company_id,actor_user_id,intent_id,outbound_request_id,basis,intent_binding,request_binding) VALUES(e.id,p_company_id,p_actor_user_id,i.id,r.id,b,to_jsonb(i)-ARRAY['validation_result','blocking_reasons','validation_status','render_status','outbox_status','updated_by','updated_at','ediel_message_id','outbound_request_id'],to_jsonb(r)-ARRAY['status','payload','response_payload','attempts_count','queued_at','prepared_at','sent_at','acknowledged_at','failed_at','failure_reason','updated_at','updated_by']);
 RETURN jsonb_build_object('status','originated','intentId',i.id,'outboundRequestId',r.id,'messageId',null);
END$$;

