--

CREATE FUNCTION public.ediel_prepare_common_header_negative_ack_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_actor_user_id uuid, p_raw_payload text) RETURNS jsonb
    LANGUAGE plpgsql
