    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RETURN gridex_bilateral_prodat.dispatch_mixed_start_v1(p_company_id,p_source_message_id,p_actor_user_id);END $$;

--
-- Name: ediel_prodat_recovery_operation_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prodat_recovery_operation_basis_v1(p_company_id uuid, p_operation_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;
BEGIN
 basis:=gridex_service_permission.recovery_operation_before_current_service_v1(p_company_id,p_operation_id,p_actor_user_id);
 IF basis IS NULL THEN RETURN NULL;END IF;
 IF nullif(basis->>'sourceOriginMessageId','') IS NULL OR basis->>'operationId' IS DISTINCT FROM p_operation_id::text THEN RAISE EXCEPTION 'ediel_service_recovery_basis_unqualified';END IF;
 PERFORM gridex_service_permission.require_original_source_current_v1(p_company_id,(basis->>'sourceOriginMessageId')::uuid);
 RETURN basis;
END$$;

--
-- Name: ediel_prodat_recovery_original_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prodat_recovery_original_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;b jsonb;
BEGIN
 SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=p_message_id AND operation.company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,p_message_id);
 b:=public.ediel_prodat_recovery_operation_basis_v1(p_company_id,op.id,p_actor_user_id);
 IF b IS NULL THEN RAISE EXCEPTION 'prodat_recovery_original_basis_unqualified';END IF;
 RETURN b;
END $$;

--
-- Name: ediel_prodat_recovery_workspace_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prodat_recovery_workspace_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE chosen public.ediel_messages%rowtype;record jsonb;result jsonb;current_content boolean;source_state text:='not_applicable';
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'prodat_recovery_workspace_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF p_message_id IS NOT NULL THEN LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;END IF;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'read');
 IF p_message_id IS NOT NULL THEN
  SELECT * INTO chosen FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='outbound' AND message_family='PRODAT' FOR SHARE;
  IF chosen.id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_workspace_message_unavailable';END IF;
  PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'read');
  current_content:=chosen.raw_payload IS NOT NULL AND chosen.immutable_payload_hash IS NOT NULL AND chosen.immutable_payload_hash=encode(sha256(convert_to(chosen.raw_payload,'UTF8')),'hex');
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations op ON op.id=link.operation_id WHERE link.message_id=chosen.id AND op.company_id=p_company_id) THEN
   BEGIN PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,chosen.id);source_state:='qualified';EXCEPTION WHEN OTHERS THEN source_state:='held';END;
  END IF;
  record:=jsonb_build_object('messageId',chosen.id,'operationId',chosen.source_operation_id,'originalMessageId',chosen.original_message_id,'environment',chosen.environment,'status',chosen.status,'code',chosen.message_code,'rawPayload',CASE WHEN current_content THEN chosen.raw_payload END,'payloadHash',chosen.immutable_payload_hash,'contentCurrent',current_content,'sourceCurrent',source_state,'contrl',chosen.contrl_status,'aperak',chosen.aperak_status);
 END IF;
 SELECT jsonb_build_object('companyId',p_company_id,'actorUserId',p_actor_user_id,'record',record,
  'originals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'environment',x.environment,'label',concat(x.message_code,' · ',x.environment,' · ',coalesce(x.external_reference,x.id::text),' · ',x.created_at))) FROM(SELECT id,message_code,environment,external_reference,created_at FROM public.ediel_messages WHERE company_id=p_company_id AND direction='outbound' AND message_family='PRODAT' ORDER BY created_at DESC,id LIMIT 200)x),'[]'),
  'acks',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'environment',x.environment,'label',concat(x.message_family,' · ',x.environment,' · ',coalesce(x.external_reference,x.id::text),' · ',x.created_at))) FROM(SELECT id,message_family,environment,external_reference,created_at FROM public.ediel_messages WHERE company_id=p_company_id AND direction='inbound' AND message_family IN('APERAK','CONTRL') ORDER BY created_at DESC,id LIMIT 200)x),'[]'),
  'corrections',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'environment',x.environment,'status',x.status,'label',concat(x.message_code,' · ',x.status,' · ',x.environment,' · ',coalesce(x.external_reference,x.id::text),' · ',x.created_at))) FROM(SELECT m.id,m.message_code,m.environment,m.status,m.external_reference,m.created_at FROM public.ediel_messages m JOIN gridex_received_sources.prodat_recovery_messages link ON link.message_id=m.id JOIN gridex_received_sources.prodat_recovery_operations op ON op.id=link.operation_id AND op.company_id=m.company_id AND op.environment=m.environment WHERE m.company_id=p_company_id AND m.direction='outbound' AND m.message_family='PRODAT' ORDER BY m.created_at DESC,m.id LIMIT 200)x),'[]'),
  'attempts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'messageId',x.message_id,'label',concat(coalesce(x.classification,'unobserved'),' · ',x.created_at,' · ',x.id))) FROM(SELECT a.id,a.message_id,a.classification,a.created_at FROM gridex_ediel_transport.attempts a JOIN public.ediel_messages m ON m.id=a.message_id AND m.company_id=a.company_id AND m.environment=a.environment WHERE a.company_id=p_company_id AND m.direction='outbound' AND m.message_family='PRODAT' ORDER BY a.created_at DESC,a.id LIMIT 200)x),'[]')) INTO result;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'read');
 RETURN result;
END$$;

--
-- Name: ediel_prodat_retry_outbox_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prodat_retry_outbox_basis_v1(p_company_id uuid, p_outbox_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;o public.ediel_outbox%rowtype;m public.ediel_messages%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'send');
 SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_outboxes b JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=b.operation_id WHERE b.outbox_id=p_outbox_id AND operation.company_id=p_company_id AND operation.kind='verified_transfer_loss';
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO STRICT o FROM public.ediel_outbox WHERE id=p_outbox_id AND company_id=p_company_id AND ediel_message_id=op.original_message_id AND environment=op.environment FOR SHARE;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id AND environment=op.environment FOR SHARE;
 IF op.original_payload_hash IS DISTINCT FROM m.immutable_payload_hash OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR o.lock_key IS DISTINCT FROM 'prodat-loss-retry:'||op.id THEN RAISE EXCEPTION 'prodat_retry_outbox_source_changed';END IF;
 RETURN jsonb_build_object('operationId',op.id,'previousAttemptId',op.previous_attempt_id,'messageId',m.id,'outboxId',o.id,'originalPayloadHash',op.original_payload_hash);
END $$;

--
-- Name: ediel_production_contract_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_production_contract_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;m public.ediel_messages%rowtype;b jsonb;r public.outbound_requests%rowtype;e gridex_received_sources.production_contract_events%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.intent_id IS DISTINCT FROM o.intent_id OR m.source_operation_id IS DISTINCT FROM o.event_id::text OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'production_contract_bound_payload_changed';END IF;
 b:=gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,o.event_id,p_actor_user_id,CASE WHEN public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') IS TRUE THEN 'communication.send' ELSE 'communication.write' END);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id AND company_id=o.company_id;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 IF e.id IS NULL OR r.id IS NULL OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR (r.payload->>'environment') IS DISTINCT FROM e.environment
 OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM o.intent_id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata'
 OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'production_contract_current_request_required';END IF;
 RETURN jsonb_build_object('basis',b,'intentId',o.intent_id);
END $$;

--
-- Name: ediel_production_contract_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_production_contract_source_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RETURN gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,p_event_id,p_actor_user_id,'communication.write');END $$;

--
-- Name: ediel_project_accepted_source_state_v1(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_project_accepted_source_state_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid, p_expected_original_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE m public.ediel_messages%rowtype;receipt jsonb;attempt_binding jsonb;technical_plan jsonb;technical_due timestamptz;technical_basis text:='current_final_or_not_required';expectations jsonb:='[]';e jsonb;observed timestamptz;business_due timestamptz;business_pending boolean:=false;
 r public.outbound_requests%rowtype;g public.grid_owner_data_requests%rowtype;c public.customer_info_requests%rowtype;
 terminal boolean;business_terminal boolean;business_watch_pending boolean;request_status text;data_status text;info_status text;source_bound_ack boolean:=false;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR p_message_id IS NULL OR (p_environment IN('test','production')) IS NOT TRUE
  OR p_expected_original_hash IS NULL OR p_expected_original_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'ediel_source_projection_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_source_projection_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND environment=p_environment AND direction='outbound' FOR UPDATE;
 IF m.immutable_payload_hash IS DISTINCT FROM p_expected_original_hash THEN RAISE EXCEPTION 'ediel_source_projection_original_changed';END IF;
 receipt:=gridex_ediel_transport.accepted_source_basis_v1(m);
 IF receipt IS NULL THEN RAISE EXCEPTION 'ediel_source_projection_accepted_receipt_required';END IF;
 observed:=(receipt->>'observedAt')::timestamptz;
 IF observed IS NULL OR receipt->>'originalHash' IS DISTINCT FROM p_expected_original_hash THEN RAISE EXCEPTION 'ediel_source_projection_frozen_clock_required';END IF;
 terminal:=(m.status IN('delivered','acknowledged','failed','cancelled','rejected','completed')) IS TRUE;
 business_terminal:=(m.status IN('failed','cancelled','rejected','completed')) IS TRUE;
 IF receipt->>'lane'='generic_journal' THEN SELECT a.binding INTO attempt_binding FROM gridex_ediel_transport.attempts a WHERE a.id=(receipt->>'attemptId')::uuid AND a.company_id=m.company_id AND a.environment=m.environment AND a.message_id=m.id;
 ELSIF receipt->>'lane'='sealed_z08' THEN SELECT a.binding INTO attempt_binding FROM gridex_outbound_dispatch.attempts a WHERE a.id=(receipt->>'attemptId')::uuid AND a.company_id=m.company_id AND a.environment=m.environment AND a.message_id=m.id;
 ELSE RAISE EXCEPTION 'ediel_source_projection_accepted_lane_required';END IF;
 IF attempt_binding IS NULL OR attempt_binding->>'originalHash' IS DISTINCT FROM m.immutable_payload_hash THEN RAISE EXCEPTION 'ediel_source_projection_accepted_binding_required';END IF;
 source_bound_ack:=CASE WHEN (m.message_standard='edifact' AND m.message_family IN('CONTRL','APERAK') AND m.related_message_id IS NOT NULL) IS TRUE THEN (gridex_ack_authority.wire_v1(m.raw_payload)->>'family'=m.message_family) IS TRUE ELSE false END;
 technical_plan:=attempt_binding->'technicalExpectationPlan';
 IF NOT terminal AND m.requires_contrl IS TRUE AND m.contrl_status IS DISTINCT FROM 'received' THEN
  IF technical_plan IS NULL OR technical_plan='null'::jsonb THEN
   IF m.contrl_due_at IS NULL OR m.ack_due_at IS NULL THEN RAISE EXCEPTION 'ediel_source_projection_frozen_technical_plan_required';END IF;
   technical_basis:='retained_legacy_projection_not_reverified';
  ELSE
   technical_plan:=gridex_ediel_transport.require_technical_expectation_plan_v1(m,technical_plan);
   IF jsonb_typeof(technical_plan) IS DISTINCT FROM 'object' OR technical_plan->>'version' IS DISTINCT FROM '1' OR technical_plan->>'ruleId' IS DISTINCT FROM 'TM-CONTRL'
    OR technical_plan->>'unit' IS DISTINCT FROM 'minutes' OR technical_plan->>'anchor' IS DISTINCT FROM 'actual_accepted_smtp_observed_at'
    OR technical_plan->>'timerKind' IS DISTINCT FROM 'internal_sender_watch' OR technical_plan->'remoteReceiptKnown' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(technical_plan#>'{policy,sourceTrace}') IS DISTINCT FROM 'array' OR nullif(technical_plan#>>'{policy,guideRevision}','') IS NULL
    OR nullif(technical_plan#>>'{policy,referenceDate}','') IS NULL OR (technical_plan->>'offset')::integer IS NULL OR (technical_plan->>'offset')::integer<=0
    THEN RAISE EXCEPTION 'ediel_source_projection_technical_plan_invalid';END IF;
   technical_due:=observed+make_interval(mins=>(technical_plan->>'offset')::integer);technical_basis:='frozen_plan';
  END IF;
 END IF;
 IF m.message_standard='edifact' AND m.message_family='PRODAT' AND (m.message_code IN('Z01','Z13','Z18') OR m.message_code='Z08' AND gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS TRUE) THEN
  expectations:=gridex_business_expectations.mutate_v1(jsonb_build_object('companyId',p_company_id,'environment',p_environment,'actorUserId',p_actor_user_id,'messageId',p_message_id,'action','register'));
  IF jsonb_typeof(expectations) IS DISTINCT FROM 'array' OR jsonb_array_length(expectations)<>1 THEN RAISE EXCEPTION 'ediel_source_projection_frozen_expectation_required';END IF;
  e:=expectations->0;
  IF e->>'source_message_id' IS DISTINCT FROM m.id::text OR (e#>>'{metadata,anchorAt}')::timestamptz IS DISTINCT FROM observed THEN RAISE EXCEPTION 'ediel_source_projection_expectation_clock_changed';END IF;
  IF m.message_code='Z01' THEN
   IF e->>'expected_code' IS DISTINCT FROM 'Z02' OR nullif(e->>'due_at','') IS NULL THEN RAISE EXCEPTION 'ediel_source_projection_frozen_z02_deadline_required';END IF;
   business_due:=(e->>'due_at')::timestamptz;business_pending:=e->>'status'='pending';
  END IF;
 END IF;
 -- Lock and qualify every actual consumer before the first source projection write. A bad final
 -- relation cannot leave half-repaired clocks/statuses in another source row.
 IF NOT source_bound_ack AND m.outbound_request_id IS NOT NULL THEN
  SELECT * INTO r FROM public.outbound_requests WHERE id=m.outbound_request_id AND company_id=m.company_id FOR UPDATE;
  IF r.id IS NULL OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'ediel_source_projection_owned_outbound_request_required';END IF;
 END IF;
 IF NOT source_bound_ack AND m.grid_owner_data_request_id IS NOT NULL THEN
  SELECT * INTO g FROM public.grid_owner_data_requests WHERE id=m.grid_owner_data_request_id AND company_id=m.company_id FOR UPDATE;
  IF g.id IS NULL OR g.customer_id IS DISTINCT FROM m.customer_id OR g.site_id IS DISTINCT FROM m.site_id OR g.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'ediel_source_projection_owned_data_request_required';END IF;
 END IF;
 IF m.message_family='PRODAT' AND m.message_code='Z01' THEN
  PERFORM x.id FROM public.customer_info_requests x WHERE x.ediel_message_id=m.id ORDER BY x.id FOR UPDATE;
  IF (SELECT count(*) FROM public.customer_info_requests x WHERE x.ediel_message_id=m.id)>1 THEN RAISE EXCEPTION 'ediel_source_projection_info_request_not_unique';END IF;
  SELECT * INTO c FROM public.customer_info_requests WHERE ediel_message_id=m.id;
  IF c.id IS NOT NULL AND (c.company_id IS DISTINCT FROM m.company_id OR c.customer_id IS DISTINCT FROM m.customer_id OR c.site_id IS DISTINCT FROM m.site_id OR c.metering_point_id IS DISTINCT FROM m.metering_point_id
    OR c.outbound_request_id IS DISTINCT FROM m.outbound_request_id OR c.grid_owner_data_request_id IS DISTINCT FROM m.grid_owner_data_request_id) THEN RAISE EXCEPTION 'ediel_source_projection_owned_info_request_required';END IF;
 END IF;
 -- A positive technical/application ACK does not fulfill a pending Z02.
 -- Only current pre-business/waiting state may gain the business watch; a
 -- progressed business result and its cleared deadline remain established.
 business_watch_pending:=NOT business_terminal AND business_pending AND (c.id IS NULL OR c.status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response','waiting_for_z02'));
 -- Current row facts decide whether a watch is still pending. Received/final
 -- ACK state and cleared deadlines survive later receipt projection repair.
 UPDATE public.ediel_messages SET message_sent_at=observed,
  contrl_due_at=CASE WHEN technical_basis='frozen_plan' THEN technical_due ELSE contrl_due_at END,
  ack_due_at=CASE WHEN technical_basis='frozen_plan' THEN technical_due ELSE ack_due_at END,
  business_response_due_at=CASE WHEN NOT business_watch_pending THEN business_response_due_at ELSE business_due END,
  updated_by=p_actor_user_id,updated_at=now() WHERE id=m.id;
 IF NOT source_bound_ack AND r.id IS NOT NULL THEN
  UPDATE public.outbound_requests SET status=CASE WHEN status IN('draft','queued','prepared') THEN 'sent' ELSE status END,sent_at=observed,
   failure_reason=CASE WHEN status IN('draft','queued','prepared') THEN NULL ELSE failure_reason END,updated_by=p_actor_user_id,updated_at=now()
  WHERE id=r.id RETURNING status INTO request_status;
 END IF;
 IF NOT source_bound_ack AND g.id IS NOT NULL THEN
  UPDATE public.grid_owner_data_requests SET status=CASE WHEN status='pending' THEN 'sent' ELSE status END,sent_at=observed,
   failed_at=CASE WHEN status='pending' THEN NULL ELSE failed_at END,failure_reason=CASE WHEN status='pending' THEN NULL ELSE failure_reason END,updated_by=p_actor_user_id,updated_at=now()
  WHERE id=g.id RETURNING status INTO data_status;
 END IF;
 IF c.id IS NOT NULL THEN
  UPDATE public.customer_info_requests SET
   status=CASE WHEN NOT business_terminal AND business_pending AND status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response') THEN 'waiting_for_z02' ELSE status END,
   sent_at=observed,
   blocker_code=CASE WHEN NOT business_terminal AND business_pending AND status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response') THEN NULL ELSE blocker_code END,
   blocker_reason=CASE WHEN NOT business_terminal AND business_pending AND status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response') THEN NULL ELSE blocker_reason END,
   blocker_details=CASE WHEN NOT business_terminal AND business_pending AND status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response') THEN '{}'::jsonb ELSE blocker_details END,
   next_required_action=CASE WHEN NOT business_terminal AND business_pending AND status IN('ready_to_send','z01_prepared','sent_to_grid_owner','sent','waiting_response') THEN 'Invänta Z02 eller negativ APERAK från nätägaren. CONTRL bevakas parallellt från faktisk Z01-sändtid.' ELSE next_required_action END,
   updated_by=p_actor_user_id,updated_at=now() WHERE id=c.id RETURNING status INTO info_status;
 END IF;
 IF m.message_code='Z08' AND gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS TRUE AND gridex_supply_rescission.sender_v1(p_company_id,p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_h_projection_terminal_sender_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('status','source_projection','companyId',m.company_id,'environment',m.environment,'messageId',m.id,'originalHash',receipt->>'originalHash','observedAt',observed,
  'technicalDeadlineBasis',technical_basis,'outboundRequestStatus',request_status,'dataRequestStatus',data_status,'infoRequestStatus',info_status,'authorizesProviderEntry',false);
END $_$;

--
-- Name: ediel_project_supply_end_followup_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_project_supply_end_followup_v1(p_company_id uuid, p_effect_receipt_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_received_sources.supply_object_effect_receipts%rowtype;old gridex_received_sources.supply_end_followups%rowtype;
 m public.ediel_messages%rowtype;effect jsonb;plan jsonb;period jsonb;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 site_id uuid;switch_id uuid;case_id uuid;customer_id uuid;point_id uuid;v_period_id uuid;receipts jsonb;current_period public.customer_supply_periods%rowtype;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'supply_followup_service_required' USING ERRCODE='42501';END IF;
 -- Discovery carries no authority. Source lock precedes executor and relations.
 SELECT * INTO r FROM gridex_received_sources.supply_object_effect_receipts WHERE id=p_effect_receipt_id AND company_id=p_company_id;
 IF r.id IS NULL THEN RAISE EXCEPTION 'supply_followup_own_receipt_required';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=r.source_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'supply_followup_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 IF m.id IS NULL OR m.environment IS DISTINCT FROM r.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR r.effect_hash IS DISTINCT FROM encode(sha256(convert_to(r.effect_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'supply_followup_source_conflict';END IF;
 SELECT * INTO old FROM gridex_received_sources.supply_end_followups WHERE effect_receipt_id=r.id;
 IF old.effect_receipt_id IS NOT NULL THEN
  IF old.company_id IS DISTINCT FROM p_company_id OR old.source_message_id IS DISTINCT FROM m.id OR old.source_payload_hash IS DISTINCT FROM r.payload_hash OR old.effect_facts_hash IS DISTINCT FROM r.effect_hash
   OR NOT EXISTS(SELECT FROM public.customer_cases c WHERE c.id=old.case_id AND c.company_id=old.company_id AND c.customer_id=old.customer_id AND c.metering_point_id=old.metering_point_id AND c.site_id IS NOT DISTINCT FROM old.site_id) THEN RAISE EXCEPTION 'supply_followup_replay_conflict';END IF;
  RETURN jsonb_build_object('status','existing','caseId',old.case_id,'effectReceiptId',r.id,'sourceMessageId',m.id);
 END IF;
 receipts:=gridex_received_sources.committed_supply_effects_v1(p_company_id,m.id,ARRAY[r.first_line_index]);
 IF jsonb_typeof(receipts) IS DISTINCT FROM 'array' OR jsonb_array_length(receipts)<>1 OR receipts#>>'{0,receiptId}' IS DISTINCT FROM r.id::text THEN RAISE EXCEPTION 'supply_followup_committed_effect_required';END IF;
 effect:=r.effect_text::jsonb;plan:=effect->'plan';
 IF plan->>'kind' IS DISTINCT FROM 'end' THEN RETURN jsonb_build_object('status','not_applicable','effectReceiptId',r.id,'sourceMessageId',m.id);END IF;
 IF m.message_code IS DISTINCT FROM 'Z05' OR effect->'wire' IS DISTINCT FROM plan->'object' OR jsonb_typeof(effect->'resultingStates') IS DISTINCT FROM 'array' OR jsonb_array_length(effect->'resultingStates')<>1 THEN RAISE EXCEPTION 'supply_followup_end_scope_required';END IF;
 period:=effect#>'{resultingStates,0}';v_period_id:=(period->>'id')::uuid;customer_id:=(period->>'customer_id')::uuid;point_id:=(period->>'metering_point_id')::uuid;
 IF v_period_id IS NULL OR customer_id IS NULL OR point_id IS NULL OR v_period_id::text IS DISTINCT FROM plan->>'periodId' OR period->>'company_id' IS DISTINCT FROM p_company_id::text
  OR period->>'source_end_message_id' IS DISTINCT FROM m.id::text OR (period->>'status' IN('ending','ended')) IS NOT TRUE
  OR (period->>'market_end_at')::timestamptz IS DISTINCT FROM (plan->>'eventAt')::timestamptz THEN RAISE EXCEPTION 'supply_followup_end_state_required';END IF;
 -- Existing tasks preserve their historical outcome above. A new operational
 -- task cannot be born for an end already superseded by an authentic C/update.
 SELECT * INTO current_period FROM public.customer_supply_periods WHERE id=v_period_id AND company_id=p_company_id FOR SHARE;
 IF current_period.id IS NULL OR current_period.customer_id IS DISTINCT FROM customer_id OR current_period.metering_point_id IS DISTINCT FROM point_id
  OR current_period.source_end_message_id IS DISTINCT FROM m.id OR current_period.market_state_version::text IS DISTINCT FROM period->>'market_state_version'
  OR current_period.market_end_at IS DISTINCT FROM (period->>'market_end_at')::timestamptz
  OR coalesce(current_period.contract_id,current_period.customer_contract_id)::text IS DISTINCT FROM coalesce(period->>'contract_id',period->>'customer_contract_id')
  OR (current_period.status IN('ending','ended')) IS NOT TRUE THEN RETURN jsonb_build_object('status','not_applicable','reason','own_end_no_longer_current','effectReceiptId',r.id,'sourceMessageId',m.id);END IF;
 -- Site/switch come only from the same immutable normal confirmation, when
 -- available. Regulated receipts without a frozen internal site keep NULL.
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE company_id=p_company_id AND period_id=v_period_id;
 IF proof.source_message_id IS NOT NULL THEN
  IF proof.confirmed_period->>'id' IS DISTINCT FROM v_period_id::text OR proof.confirmed_period->>'customer_id' IS DISTINCT FROM customer_id::text
   OR proof.confirmed_period->>'metering_point_id' IS DISTINCT FROM point_id::text OR proof.confirmed_switch->>'customer_id' IS DISTINCT FROM customer_id::text OR proof.confirmed_switch->>'metering_point_id' IS DISTINCT FROM point_id::text
   OR proof.confirmed_switch->>'id' IS DISTINCT FROM proof.switch_id::text THEN RAISE EXCEPTION 'supply_followup_initial_scope_conflict';END IF;
  site_id:=coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id')::uuid;switch_id:=proof.switch_id;
 END IF;
 INSERT INTO public.customer_cases(company_id,customer_id,site_id,metering_point_id,customer_contract_id,supplier_switch_request_id,case_type,status,priority,title,description,reason_category,next_action,source,metadata,created_by,updated_by,source_ediel_message_id,source_business_process)
 VALUES(p_company_id,customer_id,site_id,point_id,coalesce(period->>'contract_id',period->>'customer_contract_id')::uuid,switch_id,'other','open','normal','Leveransen upphör – slutför mätvärden och fakturering',
  'Ett källbundet leveransslut är registrerat. Säkerställ slutmätvärden och slutfakturering för den berörda perioden med bibehållen historik.','final_metering_and_billing','Kontrollera slutmätvärden och faktureringsberedskap vid angiven giltig sluttid.','ediel_supply_end_effect',
  jsonb_build_object('review_intent','final_metering_and_billing','source_ediel_message_id',m.id,'supply_period_id',v_period_id,'effect_receipt_id',r.id,'effect_facts_hash',r.effect_hash,'source_payload_hash',r.payload_hash,'object_scope',r.object_scope,'market_end_at',period->>'market_end_at'),p_actor_user_id,p_actor_user_id,m.id,'supply_termination') RETURNING id INTO case_id;
 INSERT INTO gridex_received_sources.supply_end_followups(effect_receipt_id,company_id,source_message_id,source_payload_hash,effect_facts_hash,case_id,customer_id,metering_point_id,site_id,supply_period_id,actor_user_id)
 VALUES(r.id,p_company_id,m.id,r.payload_hash,r.effect_hash,case_id,customer_id,point_id,site_id,v_period_id,p_actor_user_id);
 RETURN jsonb_build_object('status','created','caseId',case_id,'effectReceiptId',r.id,'sourceMessageId',m.id);
END$$;

--
-- Name: ediel_pseudonymise_customer_retention_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_pseudonymise_customer_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.customer_decisions%rowtype;r gridex_ediel_retention.customer_reviews%rowtype;c public.customers%rowtype;t gridex_ediel_retention.customer_tombstones%rowtype;claims jsonb;source text;at timestamptz:=clock_timestamp();
BEGIN PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.purge');
 IF gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.customer_fields') IS NOT TRUE THEN RAISE EXCEPTION 'customer_retention_scoped_write_required' USING ERRCODE='42501';END IF;
 -- Prevent a new operational supply or portal grant from appearing while the
 -- native closed/readset check, access revocation and pseudonymisation commit.
 LOCK TABLE public.customer_supply_periods,public.customer_portal_accounts,public.customer_portal_claims IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.customer_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO STRICT c FROM public.customers WHERE id=d.customer_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO t FROM gridex_ediel_retention.customer_tombstones WHERE customer_id=c.id;
 IF FOUND THEN IF t.decision_id IS DISTINCT FROM d.id THEN RAISE EXCEPTION 'customer_retention_tombstone_conflict';END IF;RETURN jsonb_build_object('status','pseudonymised','customerId',c.id,'sourceHash',t.source_hash,'pseudonymisedAt',t.created_at,'replay',true);END IF;
 SELECT * INTO r FROM gridex_ediel_retention.customer_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(r.actor_user_id);PERFORM id FROM public.user_profiles WHERE id=r.actor_user_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=p_company_id AND user_id=r.actor_user_id FOR SHARE;
 IF NOT public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=r.actor_user_id AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=p_company_id AND user_id=r.actor_user_id AND status='active' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(p_company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_retention_reviewer_authority']);END IF;
 IF gridex_ediel_retention.class_permission_v1(p_company_id,r.actor_user_id,'customer_canonical_personal_fields') IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_retention_class_reviewer_authority']);END IF;claims:=gridex_ediel_retention.customer_receipt_v1(d);
 IF r.outcome IS DISTINCT FROM 'approved' OR claims IS NULL OR (claims->>'retainUntil')::timestamptz>now() THEN RETURN jsonb_build_object('status','held','missing',ARRAY['current_customer_class_legal_retention_deadline']);END IF;
 IF c.status IS DISTINCT FROM 'archived' OR EXISTS(SELECT FROM public.customer_supply_periods WHERE company_id=p_company_id AND customer_id=c.id AND status NOT IN('cancelled','rejected','terminated','ended','closed','inactive') AND (coalesce(actual_end_date,end_date) IS NULL OR coalesce(actual_end_date,end_date)>=current_date)) THEN RETURN jsonb_build_object('status','held','missing',ARRAY['operative_customer_closed_and_no_active_supply']);END IF;
 source:=encode(sha256(convert_to(gridex_ediel_retention.customer_personal_fields_v1(c)::text,'UTF8')),'hex');IF source IS DISTINCT FROM d.source_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['exact_native_customer_personal_fields_changed']);END IF;
 -- Access is revoked before physical current personal-field erasure. Tenant
 -- users, retained invoices, metering values and protocol journals are untouched.
 UPDATE public.customer_portal_accounts SET status='revoked',is_active=false,updated_at=at WHERE company_id=p_company_id AND customer_id=c.id;
 UPDATE public.customer_portal_claims SET status='revoked',updated_at=at WHERE company_id=p_company_id AND customer_id=c.id;
 INSERT INTO gridex_ediel_retention.customer_tombstones(customer_id,company_id,decision_id,review_id,source_hash,retention_class,actor_user_id,created_at) VALUES(c.id,p_company_id,d.id,r.id,source,d.retention_class,p_actor_user_id,at);
 UPDATE public.customers SET first_name=NULL,last_name=NULL,full_name='Pseudonymiserad kund',company_name=NULL,personal_number=NULL,org_number=NULL,email=NULL,phone=NULL,apartment_number=NULL,identity_number=NULL,organization_number=NULL,name='Pseudonymiserad kund',billing_street=NULL,billing_postal_code=NULL,billing_city=NULL,metadata='{}',onboarding_issues='[]',intake_missing_fields='{}',intake_warnings='{}',process_summary='{}',archive_reason=NULL,next_action=NULL,latest_customer_action=NULL,anonymized_at=at,anonymized_by=p_actor_user_id,data_retention_note=claims->>'legalBasisReference',updated_at=at,updated_by=p_actor_user_id WHERE id=c.id AND company_id=p_company_id;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'customer',c.id,'ediel.retention.customer_pseudonymised',jsonb_build_object('decisionId',d.id,'reviewId',r.id,'sourceHash',source,'retentionClass',d.retention_class,'pseudonymisedAt',at));
 RETURN jsonb_build_object('status','pseudonymised','customerId',c.id,'sourceHash',source,'pseudonymisedAt',at,'replay',false);
END$$;

