-- Name: ediel_qualify_bilateral_prodat_outbound_draft_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_bilateral_prodat_outbound_draft_v1(p_company_id uuid, p_actor_user_id uuid, p_environment text, p_raw_payload text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN gridex_bilateral_prodat.outbound_capability_v1(p_company_id,p_actor_user_id,p_environment,p_raw_payload);END$$;

--
-- Name: ediel_qualify_bilateral_prodat_switch_preparation_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_bilateral_prodat_switch_preparation_v1(p_company_id uuid, p_switch_id uuid, p_actor_user_id uuid, p_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE sw public.supplier_switch_requests%rowtype;point public.metering_points%rowtype;site public.customer_sites%rowtype;customer public.customers%rowtype;contract public.customer_contracts%rowtype;
 g gridex_bilateral_prodat.profile_versions%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;ids uuid[];event_at timestamptz;profile_id uuid;sig text;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE OR p_environment NOT IN('test','production') THEN RETURN NULL;END IF;
 SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=p_switch_id AND company_id=p_company_id FOR SHARE;
 IF sw.id IS NULL OR sw.prodat_variant IS DISTINCT FROM 'H' OR sw.prodat_reason IS DISTINCT FROM 'Z25' OR sw.lifecycle_blocked IS DISTINCT FROM false OR sw.requested_start_date IS NULL
  OR sw.status NOT IN('draft','ready','ready_for_switch','ready_for_z03','z03_ready','validated','prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')
  OR (sw.outbound_z03_message_id IS NOT NULL AND NOT EXISTS(SELECT FROM gridex_bilateral_prodat.outbound_operations existing WHERE existing.message_id=sw.outbound_z03_message_id AND existing.company_id=p_company_id)) THEN RETURN NULL;END IF;
 SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=p_company_id FOR SHARE;
 SELECT * INTO customer FROM public.customers WHERE id=sw.customer_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.customer_contract_id,sw.contract_id) AND company_id=p_company_id FOR SHARE;
 IF point.id IS NULL OR site.id IS NULL OR customer.id IS NULL OR contract.id IS NULL OR point.customer_id IS DISTINCT FROM customer.id OR coalesce(point.customer_site_id,point.site_id) IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM customer.id
  OR contract.customer_id IS DISTINCT FROM customer.id OR contract.metering_point_id IS DISTINCT FROM point.id OR contract.status NOT IN('signed','active') OR contract.signed_at IS NULL OR contract.signed_version IS DISTINCT FROM contract.contract_version
  OR nullif(point.ediel_metering_point_id,'') IS NULL OR nullif(point.grid_owner_ediel_id,'') IS NULL OR nullif(point.grid_area_code,'') IS NULL THEN RETURN NULL;END IF;
 IF (SELECT count(*) FROM public.customer_contracts own WHERE own.company_id=p_company_id AND own.customer_id=customer.id AND own.metering_point_id=point.id AND own.status IN('signed','active') AND own.signed_at IS NOT NULL AND own.signed_version=own.contract_version)<>1 THEN RETURN NULL;END IF;
 sig:=encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex');
 IF contract.signature_snapshot_sha256 IS DISTINCT FROM sig OR contract.signature_snapshot->>'company_id' IS DISTINCT FROM p_company_id::text OR contract.signature_snapshot->>'customer_id' IS DISTINCT FROM customer.id::text OR contract.signature_snapshot->>'contract_id' IS DISTINCT FROM contract.id::text
  OR NOT EXISTS(SELECT FROM public.customer_contract_documents doc WHERE doc.company_id=p_company_id AND doc.customer_contract_id=contract.id AND doc.document_type='signed_contract_pdf' AND doc.document_sha256=contract.document_sha256 AND doc.verified_at IS NOT NULL) THEN RETURN NULL;END IF;
 event_at:=gridex_received_sources.permission_time_v1(to_char(sw.requested_start_date,'YYYYMMDD')||'0000');
 SELECT array_agg(v.id ORDER BY v.id) INTO ids FROM gridex_bilateral_prodat.profile_versions v JOIN gridex_bilateral_prodat.origins origin ON origin.ground_id=v.id AND origin.company_id=v.company_id JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=origin.artifact_id AND archived.company_id=v.company_id
 WHERE v.company_id=p_company_id AND v.environment=p_environment AND v.process='normal_start_h' AND v.grid_area_code=point.grid_area_code AND archived.scope->>'legalReceiverId'=point.grid_owner_ediel_id
  AND EXISTS(SELECT FROM jsonb_array_elements(archived.scope#>'{sourceGrammar,profiles}') profile WHERE profile->>'message_code'='Z03' AND profile->>'transaction_subtype'='H' AND profile->>'direction' IN('outbound','both')) AND gridex_bilateral_prodat.ground_current_v1(v.id,p_company_id,event_at) IS TRUE;
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 SELECT * INTO g FROM gridex_bilateral_prodat.profile_versions WHERE id=ids[1];SELECT archived.* INTO a FROM gridex_bilateral_prodat.origins origin JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=origin.artifact_id AND archived.company_id=origin.company_id WHERE origin.ground_id=g.id;
 SELECT (profile->>'id')::uuid INTO profile_id FROM jsonb_array_elements(a.scope#>'{sourceGrammar,profiles}')profile WHERE profile->>'message_code'='Z03' AND profile->>'direction' IN('outbound','both');
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,contract.id);
 RETURN jsonb_build_object('version',1,'owner','immutable-bilateral-prodat-switch-preparation-v1','companyId',p_company_id,'actorUserId',p_actor_user_id,'environment',p_environment,'switchId',sw.id,'pointId',point.id,'objectId',point.ediel_metering_point_id,'customerId',customer.id,'siteId',site.id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'requestedStartDate',sw.requested_start_date,'senderEdielId',a.scope->>'legalSenderId','receiverEdielId',a.scope->>'legalReceiverId','gridAreaCode',point.grid_area_code,'profileVersionId',g.id,'rulePackId',a.scope->>'rulePackId','messageProfileId',profile_id,'sourceVersion',a.scope->>'sourceVersion','sourceHash',a.source_hash,'sourceGrammarHash',a.scope->>'sourceGrammarHash');
END$$;

--
-- Name: ediel_qualify_brp_source_candidate_v1(uuid, uuid, uuid, text, uuid, uuid, uuid, timestamp with time zone, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_brp_source_candidate_v1(p_company_id uuid, p_contract_id uuid, p_actor_user_id uuid, p_environment text, p_customer_id uuid, p_site_id uuid, p_point_id uuid, p_at timestamp with time zone, p_period_id uuid, p_snapshot_id uuid, p_readset_hash text, p_source_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snap gridex_received_sources.object_selection_snapshots%rowtype;supply jsonb;b jsonb;BEGIN
 PERFORM gridex_ai_processing.authorize_purpose_phase_v1(p_company_id,p_actor_user_id,'origination',NULL);
 supply:=gridex_received_sources.supply_period_source_at_v1(p_company_id,p_period_id,p_at);
 IF supply IS NULL OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM p_customer_id::text OR supply->>'siteId' IS DISTINCT FROM p_site_id::text OR supply->>'meteringPointId' IS DISTINCT FROM p_point_id::text THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_current_source_owned_supply_relation']);END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots WHERE id=p_snapshot_id AND company_id=p_company_id AND environment=p_environment AND readset_hash=p_readset_hash;
 IF snap.id IS NULL OR snap.readset_hash IS DISTINCT FROM encode(sha256(convert_to(snap.readset_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'brp_candidate_protected_snapshot_required';END IF;
 b:=gridex_brp_sources.candidate_v1(snap.readset_text::jsonb,snap.cutoff_at,p_company_id,p_environment,p_customer_id,p_site_id,p_point_id,p_at,supply,p_source_message_id);
 IF b IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['same_dated_structural_owner_brp_candidate']);END IF;
 INSERT INTO gridex_brp_sources.qualified_candidates(company_id,environment,customer_id,site_id,metering_point_id,supply_period_id,at,snapshot_id,readset_hash,source_message_id,basis,qualified_by)
 VALUES(p_company_id,p_environment,p_customer_id,p_site_id,p_point_id,p_period_id,p_at,p_snapshot_id,p_readset_hash,p_source_message_id,b,p_actor_user_id) ON CONFLICT(company_id,environment,supply_period_id,at,snapshot_id,source_message_id) DO NOTHING;
 RETURN b;
END$$;

--
-- Name: ediel_qualify_persisted_prodat_outbound_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_persisted_prodat_outbound_source_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;cap jsonb;BEGIN
 IF gridex_supply_rescission.sender_v1(p_company_id,p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_outbound_current_sender_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN IF gridex_supply_rescission.sender_v1(p_company_id,p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_outbound_terminal_sender_required' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 IF gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS TRUE THEN
  PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(m);
  SELECT capability INTO cap FROM gridex_supply_rescission.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 ELSIF gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS TRUE THEN
  PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
  PERFORM gridex_bilateral_prodat.require_recorded_outbound_source_current_v1(m);
  SELECT capability INTO cap FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 ELSE IF gridex_supply_rescission.sender_v1(p_company_id,p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_outbound_terminal_sender_required' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 IF cap->>'actorUserId' IS DISTINCT FROM m.created_by::text OR cap->>'payloadHash' IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_outbound_original_provenance_required';END IF;
 IF gridex_supply_rescission.sender_v1(p_company_id,p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_outbound_terminal_sender_required' USING ERRCODE='42501';END IF;
 RETURN cap||jsonb_build_object('originalActorUserId',cap->>'actorUserId','actorUserId',p_actor_user_id);
END$$;

--
-- Name: ediel_qualify_supply_rescission_draft_v1(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_supply_rescission_draft_v1(p_company_id uuid, p_actor_user_id uuid, p_environment text, p_raw_payload text, p_mandate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN gridex_supply_rescission.outbound_capability_v1(p_company_id,p_actor_user_id,p_environment,p_raw_payload,p_mandate_id);
END$$;

--
-- Name: ediel_qualify_supply_rescission_prepared_original_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_qualify_supply_rescission_prepared_original_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;cap jsonb;BEGIN
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_current_prepare_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR gridex_supply_rescission.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_prepare_actor_required' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 PERFORM gridex_supply_rescission.require_recorded_outbound_source_current_v1(m);
 SELECT capability INTO cap FROM gridex_supply_rescission.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_prepare_actor_required' USING ERRCODE='42501';END IF;
 RETURN cap||jsonb_build_object('originalActorUserId',cap->>'actorUserId','actorUserId',p_actor_user_id);
END$$;

--
-- Name: ediel_queue_beneficiary_export_v1(uuid, uuid, uuid, uuid, bigint, text, uuid, text[], timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_queue_beneficiary_export_v1(p_beneficiary_company_id uuid, p_actor_user_id uuid, p_idempotency_key uuid, p_grant_id uuid, p_expected_grant_version bigint, p_purpose text, p_series_id uuid, p_fields text[], p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer DEFAULT 100, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j gridex_ediel_exports.jobs%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 -- Existing full actor/tenant/legal/source/grant filter, without a receipt or
 -- cached result. Any transient values are discarded inside this transaction.
 PERFORM gridex_ediel_ack_replay.beneficiary_series_page_filtered_v2(p_beneficiary_company_id,p_actor_user_id,p_grant_id,p_expected_grant_version,p_purpose,p_series_id,p_fields,p_start,p_end,p_limit,p_after_at,p_after_id);
 IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'ediel_export_key_required'; END IF;
 INSERT INTO gridex_ediel_exports.jobs(beneficiary_company_id,actor_user_id,idempotency_key,grant_id,expected_grant_version,series_id,purpose,fields,start_at,end_at,page_limit,after_at,after_id)
 VALUES(p_beneficiary_company_id,p_actor_user_id,p_idempotency_key,p_grant_id,p_expected_grant_version,p_series_id,p_purpose,p_fields,p_start,p_end,p_limit,p_after_at,p_after_id)
 ON CONFLICT(beneficiary_company_id,actor_user_id,idempotency_key) DO NOTHING;
 SELECT * INTO STRICT j FROM gridex_ediel_exports.jobs WHERE beneficiary_company_id=p_beneficiary_company_id AND actor_user_id=p_actor_user_id AND idempotency_key=p_idempotency_key;
 IF ROW(j.grant_id,j.expected_grant_version,j.series_id,j.purpose,j.fields,j.start_at,j.end_at,j.page_limit,j.after_at,j.after_id)
  IS DISTINCT FROM ROW(p_grant_id,p_expected_grant_version,p_series_id,p_purpose,p_fields,p_start,p_end,p_limit,p_after_at,p_after_id)
 THEN RAISE EXCEPTION 'ediel_export_idempotency_scope_mismatch'; END IF;
 RETURN jsonb_build_object('jobId',j.id,'status',j.status);
END $$;

--
-- Name: ediel_queue_prodat_retry_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_queue_prodat_retry_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype;b gridex_received_sources.prodat_recovery_outboxes%rowtype;o public.ediel_outbox%rowtype;assessment jsonb;queued_id uuid;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'send');
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id AND original_message_id=m.id AND kind='verified_transfer_loss';
 IF m.environment IS DISTINCT FROM op.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR op.original_payload_hash IS DISTINCT FROM m.immutable_payload_hash OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_retry_queue_source_changed';END IF;
 SELECT * INTO b FROM gridex_received_sources.prodat_recovery_outboxes WHERE operation_id=op.id;
 IF FOUND THEN
  SELECT * INTO STRICT o FROM public.ediel_outbox WHERE id=b.outbox_id AND company_id=p_company_id AND ediel_message_id=m.id AND environment=m.environment;
  RETURN jsonb_build_object('status','existing','outboxId',o.id,'operationId',op.id,'previousAttemptId',op.previous_attempt_id);
 END IF;
 assessment:=gridex_received_sources.require_established_recovery_source_v1(p_company_id,op.id);
 IF assessment->>'status' IS DISTINCT FROM 'authorized' OR NOT EXISTS(SELECT FROM gridex_ediel_transport.reservations r WHERE r.message_id=m.id AND r.attempt_id=op.previous_attempt_id AND r.state='observed') THEN RAISE EXCEPTION 'prodat_retry_queue_actual_negative_required';END IF;
 INSERT INTO public.ediel_outbox(company_id,ediel_message_id,status,priority,lock_key,message_family,message_code,environment,route_profile_id,payload,queued_at,created_by,updated_by)
 VALUES(m.company_id,m.id,'queued',50,'prodat-loss-retry:'||op.id,'PRODAT',m.message_code,m.environment,m.route_profile_id,jsonb_build_object('recoveryOperationId',op.id,'previousAttemptId',op.previous_attempt_id),now(),p_actor_user_id,p_actor_user_id) ON CONFLICT(lock_key) DO NOTHING RETURNING id INTO queued_id;
 IF queued_id IS NULL THEN RAISE EXCEPTION 'prodat_retry_queue_unbound_collision';END IF;
 INSERT INTO gridex_received_sources.prodat_recovery_outboxes(operation_id,outbox_id,actor_user_id) VALUES(op.id,queued_id,p_actor_user_id);
 RETURN jsonb_build_object('status','queued','outboxId',queued_id,'operationId',op.id,'previousAttemptId',op.previous_attempt_id);
END $$;

--
-- Name: ediel_read_actor_registry_batch_v1(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_actor_registry_batch_v1(p_actor_user_id uuid, p_source_base64 text, p_source_sha256 text, p_source_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE prior gridex_registry_import.batches%rowtype;source_bytes bytea;source_hash text;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 IF p_actor_user_id IS NULL OR public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM auth.users u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM au.user_id FROM public.admin_users au WHERE au.user_id=p_actor_user_id FOR SHARE;
 PERFORM ur.id FROM public.user_roles ur WHERE ur.user_id=p_actor_user_id FOR SHARE;
 IF public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_revoked' USING ERRCODE='42501';END IF;
 source_bytes:=decode(p_source_base64,'base64');
 IF p_source_base64 IS NULL OR octet_length(source_bytes) NOT BETWEEN 1 AND 16777216 OR (p_source_kind IN('companies_xml','companies_txt','csv')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_source_shape_required';END IF;
 source_hash:=encode(sha256(source_bytes),'hex');
 IF p_source_sha256 IS DISTINCT FROM source_hash THEN RAISE EXCEPTION 'ediel_registry_exact_source_hash_required';END IF;
 SELECT * INTO prior FROM gridex_registry_import.batches WHERE source_sha256=source_hash FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF prior.source_bytes IS DISTINCT FROM source_bytes OR prior.source_kind IS DISTINCT FROM p_source_kind THEN RAISE EXCEPTION 'ediel_registry_exact_original_source_required';END IF;
 RETURN prior.result||jsonb_build_object('reusedExistingRun',true);
END $$;

--
-- Name: ediel_read_ai_purpose_source_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_ai_purpose_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_ai_purpose_sources.artifacts%rowtype;r gridex_ai_purpose_sources.reviews%rowtype;result jsonb;basis jsonb;state text;missing jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_purpose_service_required' USING ERRCODE='42501';END IF;
 IF gridex_ai_purpose_sources.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'ai_purpose_read_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM gridex_ai_purpose_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ai_purpose_artifact_unavailable';END IF;
 SELECT * INTO r FROM gridex_ai_purpose_sources.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1 FOR SHARE;basis:=gridex_ai_purpose_sources.current_v1(a);
 state:=CASE WHEN basis IS NOT NULL THEN 'authorized' WHEN r.decision='rejected' THEN 'rejected' WHEN r.id IS NOT NULL THEN 'held' ELSE 'archived' END;missing:=CASE WHEN basis IS NOT NULL THEN '[]'::jsonb WHEN r.id IS NOT NULL AND r.decision<>'approved' THEN r.missing ELSE '["current_purpose_authority_missing_or_revoked"]'::jsonb END;
 result:=a.claims-ARRAY['companyId','legalActorId','legalSupplierEdielId','legalCompany','sourceProfile','retentionClass'];result:=result||jsonb_build_object('artifactId',a.id,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType','application/pdf','byteLength',octet_length(a.source_bytes),'status',state,'missing',missing);
 IF p_include_bytes THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF;RETURN result;
END$$;

--
-- Name: ediel_read_beneficiary_export_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_beneficiary_export_v1(p_beneficiary_company_id uuid, p_actor_user_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j gridex_ediel_exports.jobs%rowtype; current_page jsonb; retained jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO j FROM gridex_ediel_exports.jobs WHERE id=p_job_id AND beneficiary_company_id=p_beneficiary_company_id AND actor_user_id=p_actor_user_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_export_not_found' USING ERRCODE='42501'; END IF;
 -- Complete current authority and immutable source proof again; no earlier
 -- job completion, receipt or payload authorizes this read.
 current_page:=public.ediel_beneficiary_series_page_v1(j.beneficiary_company_id,j.actor_user_id,j.grant_id,j.expected_grant_version,j.purpose,j.series_id,j.fields,j.start_at,j.end_at,j.page_limit,j.after_at,j.after_id);
 IF j.status='completed' THEN
  IF j.result_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'ediel_export_expired'; END IF;
  SELECT page INTO STRICT retained FROM gridex_ediel_exports.results WHERE job_id=j.id AND beneficiary_company_id=j.beneficiary_company_id AND actor_user_id=j.actor_user_id AND expires_at>clock_timestamp() FOR SHARE;
  IF retained IS DISTINCT FROM current_page THEN RAISE EXCEPTION 'ediel_export_result_basis_changed'; END IF;
 END IF;
 RETURN jsonb_build_object('jobId',j.id,'status',j.status,'page',retained);
END $$;

--
-- Name: ediel_read_bilateral_customer_source_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_customer_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_bilateral_customer_sources.artifacts%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;status text;missing jsonb;result jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM public.ediel_messages WHERE company_id=p_company_id AND id=(SELECT source_message_id FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id) FOR SHARE;

 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'bilateral_customer_source_service_required' USING ERRCODE='42501';END IF;
 IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_source_read_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a) IS NOT NULL THEN status:='authorized';missing:='[]';ELSIF r.decision='rejected' THEN status:='rejected';missing:=r.missing;ELSIF r.id IS NOT NULL THEN status:='held';missing:=CASE WHEN r.decision='approved' THEN '["current_bilateral_source_authority_unavailable"]'::jsonb ELSE r.missing END;ELSE status:='archived';missing:='["separate_bilateral_source_review_required"]';END IF;
 result:=jsonb_build_object('artifactId',a.id,'sourceMessageId',a.source_message_id,'agreementId',a.agreement_id,'supplyPeriodId',a.supply_period_id,'contractId',a.contract_id,'effectiveAt',a.claims->'effectiveAt','sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType','application/pdf','byteLength',octet_length(a.source_bytes),'status',status,'missing',missing);
 IF p_include_bytes THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF; IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN result;
END$$;

--
-- Name: ediel_read_bilateral_prodat_closure_operation_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_closure_operation_v1(p_company_id uuid, p_actor_user_id uuid, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 RETURN gridex_bilateral_prodat.closure_operation_current_v1(p_company_id,p_actor_user_id,p_operation_id);END$$;

--
-- Name: ediel_read_bilateral_prodat_ground_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_bilateral_prodat.artifacts%rowtype;r gridex_bilateral_prodat.reviews%rowtype;o gridex_bilateral_prodat.origins%rowtype;out jsonb;current boolean:=false;
BEGIN
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_artifact_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_prodat.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 SELECT * INTO r FROM gridex_bilateral_prodat.reviews WHERE company_id=p_company_id AND artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;SELECT * INTO o FROM gridex_bilateral_prodat.origins WHERE company_id=p_company_id AND artifact_id=a.id;
 IF o.ground_id IS NOT NULL THEN current:=gridex_bilateral_prodat.ground_current_v1(o.ground_id,p_company_id,greatest(now(),(a.scope->>'validFrom')::timestamptz));END IF;
 out:=jsonb_build_object('status',CASE WHEN current THEN 'authorized' WHEN o.ground_id IS NOT NULL THEN 'held' WHEN r.id IS NOT NULL THEN r.decision ELSE 'archived' END,'companyId',p_company_id,'artifactId',a.id,'profileVersionId',o.ground_id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'scope',a.scope,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'mimeType',a.mime_type,'byteLength',octet_length(a.source_bytes),'missing',CASE WHEN current THEN '[]'::jsonb WHEN o.ground_id IS NOT NULL THEN '["actual_current_qualified_ground"]'::jsonb ELSE coalesce(r.missing,'["separate_qualified_source_review_required"]') END);
 IF p_include_bytes THEN out:=out||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;RETURN out;
END$$;

--
-- Name: ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;cap jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN RETURN NULL;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_message_id);PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);
 SELECT capability INTO cap FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;RETURN cap;
END$$;

--
-- Name: ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;cap jsonb;BEGIN
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_current_reader_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_terminal_reader_required' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);PERFORM gridex_bilateral_prodat.require_recorded_outbound_source_current_v1(m);
 SELECT capability INTO cap FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_terminal_reader_required' USING ERRCODE='42501';END IF;
 RETURN cap||jsonb_build_object('originalActorUserId',cap->>'actorUserId','actorUserId',p_actor_user_id);
END$$;

--
-- Name: ediel_read_blob_retention_decision_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_blob_retention_decision_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.blob_decisions%rowtype;t gridex_ediel_retention.blob_tombstones%rowtype;permission text;reviews jsonb;current_review uuid;basis jsonb;physical boolean:=false;
BEGIN
 -- actor_v1 takes the authorization registry locks. Never trust a browser's
 -- selected class, actor, reviewer outcome or prior HTTP authorization check.
 IF NOT p_include_document AND gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,'__read_scope__') IS TRUE THEN permission:='ediel.retention.read';
 ELSIF gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.review') IS TRUE THEN permission:='ediel.retention.review';
 ELSIF NOT p_include_document AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.submit') IS TRUE THEN permission:='ediel.retention.submit';
 ELSIF NOT p_include_document AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.purge') IS TRUE THEN permission:='ediel.retention.purge';
 ELSE RAISE EXCEPTION 'retention_current_read_grant_required' USING ERRCODE='42501';END IF;
 IF permission='ediel.retention.read' THEN PERFORM gridex_ediel_retention.record_read_actor_v1(p_company_id,p_actor_user_id);ELSE PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,permission);END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.blob_decisions WHERE company_id=p_company_id AND id=p_decision_id FOR SHARE;
 IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,d.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required' USING ERRCODE='42501';END IF;
 IF encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RAISE EXCEPTION 'retention_actual_document_hash_required';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('reviewId',r.id,'actorUserId',r.actor_user_id,'outcome',r.outcome,'reason',r.reason,'createdAt',r.created_at) ORDER BY r.created_at,r.id),'[]') INTO reviews FROM gridex_ediel_retention.blob_reviews r WHERE r.decision_id=d.id;
 SELECT * INTO t FROM gridex_ediel_retention.blob_tombstones WHERE company_id=p_company_id AND decision_id=d.id AND retention_class=d.retention_class AND target_id=d.target_id FOR SHARE;
 current_review:=gridex_ediel_retention.blob_current_v1(d);
 IF t.target_id IS NULL AND current_review IS NOT NULL THEN
  BEGIN
   basis:=gridex_ediel_retention.blob_basis_v1(p_company_id,d.retention_class,d.target_id);
   IF basis->>'targetHash' IS DISTINCT FROM d.target_hash OR basis->>'sourceHash' IS DISTINCT FROM d.source_hash THEN current_review:=NULL;END IF;
  EXCEPTION WHEN no_data_found OR raise_exception THEN current_review:=NULL;END;
 ELSIF t.target_id IS NOT NULL THEN current_review:=NULL;END IF;
 IF t.target_id IS NOT NULL THEN
  IF d.retention_class='transport_raw_mime_bytes' THEN
   physical:=EXISTS(SELECT FROM gridex_ediel_retention.blob_events WHERE retention_class=d.retention_class AND target_id=d.target_id AND kind='physical_bytes_removed');
  ELSE
   physical:=EXISTS(SELECT FROM gridex_received_sources.sources s JOIN public.ediel_messages m ON m.company_id=s.company_id AND m.id=s.source_message_id WHERE s.company_id=p_company_id AND s.source_message_id=d.message_id AND s.raw_payload IS NULL AND s.retention_purged_at IS NOT NULL AND m.raw_payload IS NULL AND m.parsed_payload='{}'::jsonb AND m.validation_report='{}'::jsonb AND m.metadata='{}'::jsonb)
    AND NOT EXISTS(SELECT FROM public.ediel_message_payloads p WHERE p.company_id=p_company_id AND p.ediel_message_id=d.message_id AND (p.raw_payload IS NOT NULL OR p.encrypted_payload IS NOT NULL));
  END IF;
 END IF;
 RETURN jsonb_build_object('companyId',d.company_id,'decisionId',d.id,'retentionClass',d.retention_class,'targetId',d.target_id,'messageId',d.message_id,'sourceHash',d.source_hash,'targetHash',d.target_hash,'documentHash',d.document_hash,'documentByteLength',octet_length(d.document_bytes),'submittedBy',d.submitted_by,'createdAt',d.created_at,
 'issuerQualified',gridex_ediel_retention.blob_receipt_v1(d) IS NOT NULL,'currentQualified',current_review IS NOT NULL,'revoked',EXISTS(SELECT FROM gridex_ediel_retention.blob_revocations WHERE decision_id=d.id),'reviews',reviews,
 'purge',CASE WHEN t.target_id IS NULL THEN NULL ELSE jsonb_build_object('createdAt',t.created_at,'byteLength',t.byte_length,'physicalBytesRemoved',physical) END,
 'documentBase64',CASE WHEN p_include_document THEN replace(encode(d.document_bytes,'base64'),E'\n','') ELSE NULL END);
END$$;

--
-- Name: ediel_read_business_ack_status_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_business_ack_status_v1(p_source_message_id uuid, p_actor_user_id uuid, p_company_id uuid DEFAULT NULL::uuid, p_ack_family text DEFAULT NULL::text, p_environment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;company uuid;basis jsonb;entry jsonb;
 family text;items jsonb:='[]';held uuid[]:='{}';correlation record;snapshot jsonb;receipt jsonb;qualified jsonb;
 latest_capture timestamptz;latest_ack uuid;ambiguous_summary boolean:=false;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();
 IF p_source_message_id IS NULL OR p_actor_user_id IS NULL
  OR (p_ack_family IS NOT NULL AND p_ack_family NOT IN('CONTRL','APERAK','UTILTS_ERR'))
  THEN RAISE EXCEPTION 'ediel_business_ack_status_scope_required' USING ERRCODE='22023';END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND direction IN('inbound','outbound') FOR SHARE;
 IF source.id IS NULL OR(p_environment IS NOT NULL AND source.environment IS DISTINCT FROM p_environment)
  THEN RAISE EXCEPTION 'ediel_business_ack_status_source_required';END IF;
 -- A null public company is resolved only by the actual native source owner.
 IF source.direction='inbound' THEN
  basis:=gridex_ack_authority.read_outbound_originals_v1(source.id,coalesce(p_ack_family,'APERAK'));
 END IF;
 company:=coalesce(source.company_id,(basis->>'companyId')::uuid);
 IF company IS NULL OR(p_company_id IS NOT NULL AND p_company_id IS DISTINCT FROM company)
  THEN RAISE EXCEPTION 'ediel_business_ack_status_tenant_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.companies WHERE id=company AND is_active AND status='active')
  OR public.gridex_actor_has_company_permission(p_actor_user_id,company,'communication.read') IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_business_ack_status_reader_required' USING ERRCODE='42501';END IF;
 IF source.direction='inbound' THEN
 FOREACH family IN ARRAY CASE WHEN p_ack_family IS NULL THEN ARRAY['CONTRL','APERAK','UTILTS_ERR'] ELSE ARRAY[p_ack_family] END LOOP
  PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(company,source.environment,source.id,p_actor_user_id,family,NULL,'read');
  basis:=gridex_ack_authority.read_outbound_originals_v1(source.id,family);
  IF basis->>'sourceMessageId' IS DISTINCT FROM source.id::text OR basis->>'environment' IS DISTINCT FROM source.environment
   OR (basis->>'companyId' IS NOT NULL AND basis->>'companyId' IS DISTINCT FROM company::text)
   THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(basis->'originals') LOOP
   IF gridex_ediel_duplicate_responses.is_duplicate_ack_v1((entry#>>'{message,id}')::uuid) THEN CONTINUE;END IF;
   -- A native consumption/witness may qualify an original whose mutable
   -- public relation is absent. Project the private binding; never repair it.
   IF entry->>'status'='qualified' THEN
    qualified:=gridex_ediel_duplicate_responses.read_business_original_v1(company,source.environment,source.id,p_actor_user_id,family,(entry#>>'{message,id}')::uuid,'read');
    IF qualified#>>'{ackMessage,id}' IS DISTINCT FROM entry#>>'{message,id}' THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
    items:=items||jsonb_build_array(qualified->'ackMessage');
   ELSE held:=array_append(held,(entry#>>'{message,id}')::uuid);END IF;
  END LOOP;
 END LOOP;
 ELSE
  -- Incoming ACK status is disclosed only through its immutable correlation
  -- and the existing exact-receipt owner. Mutable aggregate caches are unused.
  FOR correlation IN SELECT c.*,r.captured_at FROM gridex_ack_authority.source_correlations c
   LEFT JOIN gridex_ack_authority.applied_receipts r USING(ack_message_id)
   WHERE c.source_message_id=source.id AND c.company_id=company AND c.environment=source.environment
   ORDER BY r.captured_at ASC NULLS FIRST,c.ack_message_id LOOP
   basis:=gridex_ack_authority.read_committed_v1(company,source.environment,correlation.ack_message_id,p_actor_user_id);
   IF basis->>'kind' IS DISTINCT FROM 'exact_receipt' THEN held:=array_append(held,correlation.ack_message_id);CONTINUE;END IF;
   IF basis->>'sourceMessageId' IS DISTINCT FROM source.id::text OR basis->>'companyId' IS DISTINCT FROM company::text
    OR basis->>'environment' IS DISTINCT FROM source.environment OR basis->>'ackFamily' IS DISTINCT FROM correlation.ack_family
    THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
   SELECT to_jsonb(m)||jsonb_build_object('related_message_id',source.id,'ack_outcome',correlation.ack_outcome)
    INTO entry FROM public.ediel_messages m WHERE m.id=correlation.ack_message_id;
   IF p_ack_family IS NULL OR correlation.ack_family=p_ack_family THEN items:=items||jsonb_build_array(entry);END IF;
   IF correlation.captured_at IS NULL THEN held:=array_append(held,correlation.ack_message_id);CONTINUE;END IF;
   IF latest_capture IS NOT DISTINCT FROM correlation.captured_at THEN
    IF snapshot IS DISTINCT FROM basis#>'{result,sourceMessage}' THEN ambiguous_summary:=true;END IF;
   ELSE ambiguous_summary:=false;END IF;
   snapshot:=basis#>'{result,sourceMessage}';receipt:=((basis->'result')-'sourceMessage')||
    jsonb_build_object('ackMessageId',correlation.ack_message_id,'capturedAt',correlation.captured_at);
   latest_capture:=correlation.captured_at;latest_ack:=correlation.ack_message_id;
  END LOOP;
  IF ambiguous_summary THEN held:=array_append(held,latest_ack);snapshot:=NULL;receipt:=NULL;END IF;
 END IF;
 -- Inner original qualification can wait. Recheck before disclosing its result.
 IF public.gridex_actor_has_company_permission(p_actor_user_id,company,'communication.read') IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_business_ack_status_reader_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('version',1,'companyId',company,'sourceMessageId',source.id,
  'environment',source.environment,'sourceDirection',source.direction,'sourceSnapshot',snapshot,'sourceReceipt',receipt,
  'ackFamily',p_ack_family,'messages',items,'heldOriginalIds',held);
END $$;

