--
-- Name: ediel_read_customer_record_retention_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_customer_record_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.record_decisions%rowtype;claims jsonb;BEGIN
 IF gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,'__read_scope__') IS TRUE THEN PERFORM gridex_ediel_retention.record_read_actor_v1(p_company_id,p_actor_user_id);ELSE PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.review');END IF;SELECT * INTO STRICT d FROM gridex_ediel_retention.record_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR SHARE;
 IF gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,d.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_read_scope_required';END IF;
 claims:=gridex_ediel_retention.record_receipt_v1(d);
 RETURN jsonb_build_object('decisionId',d.id,'retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',d.source_hash,'targetHash',d.target_hash,'documentHash',d.document_hash,'documentBase64',encode(d.document_bytes,'base64'),'submittedBy',d.submitted_by,'issuerQualified',claims IS NOT NULL,'retainUntil',claims->>'retainUntil','journalRetainUntil',claims->>'journalRetainUntil','journalPurposeReference',claims->>'journalPurposeReference');
END$$;

--
-- Name: ediel_read_decision_evidence_policy_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_decision_evidence_policy_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.decision_evidence_policies%rowtype;p jsonb;r jsonb;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;bytes_length bigint;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_ediel_retention.decision_evidence_lock_v1(p_company_id);
 SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=p_policy_id AND company_id=p_company_id FOR SHARE;PERFORM gridex_ediel_retention.decision_evidence_read_actor_v1(p_company_id,p_actor_user_id,d.retention_class);IF p_include_document THEN PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,d.retention_class,'ediel.retention.review');END IF;
 IF d.document_bytes IS NOT NULL AND encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RAISE EXCEPTION 'decision_evidence_policy_original_hash_required';END IF;
 p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id AND company_id=p_company_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('reviewId',id,'actorUserId',actor_user_id,'outcome',outcome,'reason',reason,'createdAt',created_at) ORDER BY created_at,id),'[]') INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id;
 bytes_length:=coalesce(octet_length(d.document_bytes),d.document_byte_length);
 RETURN jsonb_build_object('companyId',d.company_id,'policyId',d.id,'retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',d.source_hash,'targetMetadataHash',d.target_metadata_hash,'documentHash',d.document_hash,'documentByteLength',bytes_length,'bytesAvailable',d.document_bytes IS NOT NULL,'documentPurgedAt',d.document_purged_at,'documentBase64',CASE WHEN p_include_document AND d.document_bytes IS NOT NULL THEN replace(encode(d.document_bytes,'base64'),E'\n','') ELSE NULL END,'submittedBy',d.submitted_by,'createdAt',d.created_at,'issuerQualified',p IS NOT NULL,'currentQualified',gridex_ediel_retention.decision_evidence_policy_current_v1(d),'revoked',EXISTS(SELECT FROM gridex_ediel_retention.decision_evidence_revocations WHERE policy_id=d.id),'reviews',r,'purge',CASE WHEN t.target_id IS NULL THEN NULL ELSE jsonb_build_object('purgedAt',t.created_at,'sourceHash',t.source_hash,'byteLength',t.byte_length) END,'authority','none');
END$$;

