--
-- Name: ediel_read_received_err_application_response_authority_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_received_err_application_response_authority_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active' FOR SHARE;
 IF NOT FOUND OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
 RETURN gridex_received_err_response.require_v1(p_company_id,p_environment,p_source_message_id);
END $$;

--
-- Name: ediel_read_registry_preview_snapshot_v1(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_registry_preview_snapshot_v1(p_actor_user_id uuid, p_ediel_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actors jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 IF coalesce(cardinality(p_ediel_ids),0)>4096 OR public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel_registry_atomic_apply_v1',0));
 PERFORM id FROM public.user_profiles WHERE id=p_actor_user_id FOR SHARE;PERFORM user_id FROM public.admin_users WHERE user_id=p_actor_user_id FOR SHARE;
 IF public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_revoked' USING ERRCODE='42501';END IF;
 LOCK TABLE public.platform_market_actors,public.platform_actor_identifiers,public.platform_actor_roles,public.platform_actor_routes IN SHARE MODE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('actorId',a.id,'edielId',i.identifier_value,'name',a.name,'legalName',a.legal_name,'market',a.metadata->>'market','countryCode',a.country_code,'orgNumber',a.org_number,
 'svkId',(SELECT identifier_value FROM public.platform_actor_identifiers x WHERE x.actor_id=a.id AND x.identifier_type='SvKId' ORDER BY id LIMIT 1),
 'eic',(SELECT identifier_value FROM public.platform_actor_identifiers x WHERE x.actor_id=a.id AND x.identifier_type='EIC' ORDER BY id LIMIT 1),
 'roles',(SELECT coalesce(jsonb_agg(actor_role ORDER BY actor_role),'[]') FROM public.platform_actor_roles x WHERE x.actor_id=a.id AND x.is_active),
 'routes',(SELECT coalesce(jsonb_agg(jsonb_build_object('messageFamily',r.message_family,'environment',r.environment,'applicationReference',r.application_reference,'subaddress',r.subaddress,'communicationType',r.communication_type,'communicationAddress',r.communication_address,'partyId',r.party_id,'interchangePartyId',r.interchange_party_id,'partyIdQualifier',r.party_id_qualifier,'partyIdResponsible',r.party_id_responsible,'interchangeIdQualifier',r.interchange_id_qualifier,'ediCharset',r.edi_charset,'ediSyntax',r.edi_syntax) ORDER BY r.id),'[]') FROM public.platform_actor_routes r WHERE r.actor_id=a.id)) ORDER BY a.id,i.identifier_value),'[]') INTO actors
 FROM public.platform_market_actors a JOIN public.platform_actor_identifiers i ON i.actor_id=a.id AND lower(i.identifier_type) IN('edielid','ediel_id') WHERE i.identifier_value=ANY(p_ediel_ids);
 RETURN jsonb_build_object('actors',actors,'snapshotHash',encode(sha256(convert_to(actors::text,'UTF8')),'hex'));
END$$;

--
-- Name: ediel_read_regulated_supply_ground_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_regulated_supply_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_regulated_supply.artifacts%rowtype;r gridex_regulated_supply.reviews%rowtype;o gridex_regulated_supply.origins%rowtype;out jsonb;current boolean:=false;
BEGIN
 IF gridex_regulated_supply.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'regulated_supply_artifact_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_regulated_supply.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 SELECT * INTO r FROM gridex_regulated_supply.reviews WHERE company_id=p_company_id AND artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;SELECT * INTO o FROM gridex_regulated_supply.origins WHERE company_id=p_company_id AND artifact_id=a.id;
 IF o.ground_id IS NOT NULL THEN current:=gridex_regulated_supply.ground_current_v1(o.ground_id,p_company_id,(a.scope->>'meteringPointId')::uuid,(a.scope->>'startAt')::timestamptz);END IF;
 out:=jsonb_build_object('status',CASE WHEN current THEN 'authorized' WHEN o.ground_id IS NOT NULL THEN 'held' WHEN r.id IS NOT NULL THEN r.decision ELSE 'archived' END,'companyId',p_company_id,'artifactId',a.id,'groundId',o.ground_id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'scope',a.scope,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'mimeType',a.mime_type,'byteLength',octet_length(a.source_bytes),'missing',CASE WHEN current THEN '[]'::jsonb WHEN o.ground_id IS NOT NULL THEN '["actual_current_qualified_ground"]'::jsonb ELSE coalesce(r.missing,'["separate_qualified_source_review_required"]') END);
 IF p_include_bytes THEN out:=out||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;RETURN out;
END$$;

--
-- Name: ediel_read_requested_change_artifact_before_scope_fence_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_requested_change_artifact_before_scope_fence_v1(p_company_id uuid, p_artifact_id uuid, p_actor_user_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_changes.artifacts%rowtype;r gridex_requested_changes.reviews%rowtype;o gridex_requested_changes.review_origins%rowtype;result jsonb;b jsonb;
BEGIN SELECT * INTO STRICT a FROM gridex_requested_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'read',a.kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_artifact_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM gridex_requested_changes.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE artifact_id=a.id;
 IF o.event_id IS NOT NULL THEN SELECT reviewer_user_id INTO r.reviewer_user_id FROM gridex_requested_changes.reviews WHERE id=o.review_id;b:=gridex_requested_changes.context_v1(a.company_id,o.event_id,r.reviewer_user_id,'communication.write');END IF;
 IF a.source_bytes IS NULL THEN b:=jsonb_build_object('status','held','missing',ARRAY['requested_change_source_bytes_retention_tombstone']);END IF;
 result:=jsonb_build_object('artifactId',a.id,'kind',a.kind,'effectiveAt',a.effective_at,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType',a.mime_type,'byteLength',coalesce(octet_length(a.source_bytes),(to_jsonb(a)->>'source_byte_length')::int),'customerIdentity',a.claims->'customerIdentity','invoiceeProfile',a.claims->'invoiceeProfile','status',CASE WHEN o.event_id IS NOT NULL AND b->>'status'='authorized' THEN 'authorized' WHEN b->>'status'='held' THEN 'held' WHEN r.decision='approved' THEN 'held' WHEN r.id IS NOT NULL THEN r.decision ELSE 'archived' END,'eventId',o.event_id,'missing',coalesce(b->'missing',r.missing,'["separate_source_review_required"]'::jsonb));
 IF p_include_bytes THEN IF a.source_bytes IS NULL THEN RAISE EXCEPTION 'requested_change_artifact_bytes_retained_as_tombstone';END IF;result:=result||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;RETURN result;
END$$;

--
-- Name: ediel_read_requested_change_artifact_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_requested_change_artifact_v1(p_company_id uuid, p_artifact_id uuid, p_actor_user_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();RETURN public.ediel_read_requested_change_artifact_before_scope_fence_v1(p_company_id,p_artifact_id,p_actor_user_id,p_include_bytes);END$$;

--
-- Name: ediel_read_requested_customer_change_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_requested_customer_change_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_customer_changes.artifacts%rowtype;r gridex_requested_customer_changes.reviews%rowtype;o gridex_requested_customer_changes.origins%rowtype;current_source jsonb;status text;missing jsonb;result jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'requested_customer_change_service_required' USING ERRCODE='42501';END IF;
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_read_actor_forbidden' USING ERRCODE='42501';END IF;
 current_source:=gridex_requested_customer_changes.current_v1(p_artifact_id,p_company_id);
 SELECT * INTO STRICT a FROM gridex_requested_customer_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;SELECT * INTO r FROM gridex_requested_customer_changes.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1 FOR SHARE;SELECT * INTO o FROM gridex_requested_customer_changes.origins WHERE artifact_id=a.id;
 IF current_source IS NOT NULL THEN status:='authorized';missing:='[]';ELSIF r.decision='rejected' THEN status:='rejected';missing:=r.missing;ELSIF r.id IS NOT NULL THEN status:='held';missing:=CASE WHEN r.decision='approved' THEN '["current_outgoing_customer_mandate_unavailable"]'::jsonb ELSE r.missing END;ELSE status:='archived';missing:='["separate_requested_customer_change_review_required"]';END IF;
 IF o.artifact_id IS NULL AND status='archived' THEN
  IF a.claims->>'supplyQualified' IS DISTINCT FROM 'true' THEN missing:=missing||'["current_owned_supply_source_required"]'::jsonb;
  ELSIF gridex_requested_customer_changes.receipt_current_v1(a) IS NULL THEN missing:=missing||'["authentic_current_outgoing_customer_mandate"]'::jsonb;END IF;
 END IF;
 result:=jsonb_build_object('artifactId',a.id,'agreementId',a.agreement_id,'supplyPeriodId',a.supply_period_id,'contractId',a.contract_id,'eventId',o.event_id,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType','application/pdf','byteLength',octet_length(a.source_bytes),'status',status,'missing',missing);
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_post_wait_reader_forbidden' USING ERRCODE='42501';END IF;
 IF p_include_bytes THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF;RETURN result;END$$;

--
-- Name: ediel_read_retention_decision_original_v1(uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_retention_decision_original_v1(p_company_id uuid, p_actor_user_id uuid, p_retention_class text, p_target_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE tab text;r jsonb;b bytea;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_ediel_retention.decision_evidence_lock_v1(p_company_id);
 PERFORM gridex_ediel_retention.decision_evidence_read_actor_v1(p_company_id,p_actor_user_id,p_retention_class);IF p_include_document THEN PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,p_retention_class,'ediel.retention.review');END IF;
 IF p_retention_class IN('life_event_classification_source_original_bytes','life_event_classification_receipt_original_bytes','life_event_classification_revocation_original_bytes') THEN r:=gridex_ediel_retention.classification_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex'); SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id; RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; IF p_retention_class IN('masterdata_declaration_agreement_original_bytes','masterdata_declaration_source_original_bytes','masterdata_preparation_agreement_original_bytes','masterdata_preparation_source_original_bytes','metering_contract_request_agreement_original_bytes','metering_contract_request_source_original_bytes','metering_method_event_agreement_original_bytes','metering_method_event_source_original_bytes') THEN r:=gridex_ediel_retention.contract_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex');SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; IF EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=p_retention_class) THEN r:=gridex_ediel_retention.protected_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex');SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'
','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; SELECT source_table INTO STRICT tab FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=p_retention_class;EXECUTE format('SELECT to_jsonb(d),d.document_bytes FROM gridex_ediel_retention.%I d WHERE id=$1 AND company_id=$2 FOR SHARE',tab) INTO r,b USING p_target_id,p_company_id;IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;
 SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;
 IF b IS NULL AND (t.target_id IS NULL OR r->>'document_hash' IS DISTINCT FROM t.source_hash) OR b IS NOT NULL AND encode(sha256(b),'hex') IS DISTINCT FROM r->>'document_hash' THEN RAISE EXCEPTION 'decision_evidence_original_custody_mismatch';END IF;
 RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');
END$_$;

--
-- Name: ediel_read_service_evidence_archive_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_service_evidence_archive_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_ediel_services.artifacts%rowtype;v gridex_ediel_services.reviews%rowtype;result jsonb;
BEGIN
 IF gridex_ediel_services.actor_current_v1(p_company_id,p_actor_user_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_evidence_reviewer_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM gridex_ediel_services.artifacts WHERE company_id=p_company_id AND id=p_artifact_id;
 IF a.id IS NULL THEN RAISE EXCEPTION 'ediel_service_evidence_owned_archive_required';END IF;
 SELECT * INTO v FROM gridex_ediel_services.reviews WHERE company_id=p_company_id AND artifact_id=a.id ORDER BY review_sequence DESC LIMIT 1;
 result:=jsonb_build_object('artifactId',a.id,'companyId',a.company_id,'assignmentId',a.assignment_id,'scopeBasisVersion',a.scope_basis_version,'kind',a.evidence_kind,'mimeType',a.mime_type,'sourceHash',a.source_hash,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'scopeHash',a.scope_hash,'scope',a.scope,'evidenceTerms',a.evidence_terms,'byteLength',octet_length(a.source_bytes),'issuerCurrent',gridex_ediel_services.receipt_current_v1(a),'reviewStatus',coalesce(v.decision,'unreviewed'),'marketActivationGranted',false);
 IF p_include_bytes IS TRUE THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF;RETURN result;
END $$;

