--
-- Name: ediel_read_source_supply_at_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_source_supply_at_v1(p_company_id uuid, p_actor_user_id uuid, p_period_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'structural_supply_basis_service_required' USING ERRCODE='42501'; END IF;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT(coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel_testing.write'),false)) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
 RETURN gridex_received_sources.supply_period_source_at_v1(p_company_id,p_period_id,p_at);
END $$;

--
-- Name: ediel_read_source_supply_basis_v1(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_source_supply_basis_v1(p_company_id uuid, p_actor_user_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'structural_supply_basis_service_required' USING ERRCODE='42501'; END IF;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT(coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel_testing.write'),false)) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
 RETURN gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_start,p_end);
END $$;

--
-- Name: ediel_read_structural_effect_scope_v1(uuid, text, uuid, uuid, text, uuid, uuid, uuid, uuid, timestamp with time zone, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_structural_effect_scope_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_snapshot_id uuid, p_readset_hash text, p_customer_id uuid, p_site_id uuid, p_point_id uuid, p_period_id uuid, p_at timestamp with time zone, p_source_message_id uuid, p_assessment_id uuid, p_object_id text, p_identity_agency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snap gridex_received_sources.object_selection_snapshots%rowtype;supply jsonb;BEGIN
 -- Delegate the existing protected read owner and exact current relation.
 supply:=public.ediel_read_source_supply_at_v1(p_company_id,p_actor_user_id,p_period_id,p_at);
 IF supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM p_customer_id::text OR supply->>'siteId' IS DISTINCT FROM p_site_id::text OR supply->>'meteringPointId' IS DISTINCT FROM p_point_id::text THEN RETURN jsonb_build_object('applied',false);END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots WHERE id=p_snapshot_id AND company_id=p_company_id AND environment=p_environment AND readset_hash=p_readset_hash;
 IF snap.id IS NULL OR snap.readset_hash IS DISTINCT FROM encode(sha256(convert_to(snap.readset_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'structural_effect_protected_snapshot_required';END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(snap.readset_text::jsonb->'sources') s,LATERAL jsonb_array_elements(s->'assessments') a WHERE s->>'sourceMessageId'=p_source_message_id::text AND a->>'id'=p_assessment_id::text AND NOT EXISTS(SELECT FROM jsonb_array_elements(s->'assessments') child WHERE child->>'previousAssessmentId'=a->>'id')) THEN RETURN jsonb_build_object('applied',false);END IF;
 RETURN jsonb_build_object('applied',gridex_received_sources.structural_effect_matches_v1(p_company_id,p_environment,p_source_message_id,p_assessment_id,p_customer_id,p_site_id,p_point_id,p_period_id,p_object_id,p_identity_agency,snap.cutoff_at));
END$$;

--
-- Name: ediel_read_supply_rescission_artifact_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_supply_rescission_artifact_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE gridex_intake_session_result_v1 jsonb; a gridex_supply_rescission.artifacts%rowtype;m gridex_supply_rescission.mandates%rowtype;r gridex_supply_rescission.reviews%rowtype;current boolean;out jsonb;BEGIN PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'read');
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM gridex_supply_rescission.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;IF a.id IS NULL THEN RAISE EXCEPTION 'supply_rescission_artifact_unavailable';END IF;
 SELECT * INTO m FROM gridex_supply_rescission.mandates WHERE artifact_id=a.id AND company_id=p_company_id;
 SELECT * INTO r FROM gridex_supply_rescission.reviews WHERE artifact_id=a.id AND company_id=p_company_id ORDER BY reviewed_at DESC,id DESC LIMIT 1;
 current:=m.id IS NOT NULL AND gridex_supply_rescission.mandate_current_v1(p_company_id,m.id);
 out:=jsonb_build_object('status',CASE WHEN current THEN 'authorized' WHEN m.id IS NOT NULL THEN 'held' WHEN r.decision='rejected' THEN 'rejected' WHEN r.id IS NOT NULL THEN 'held' ELSE 'archived' END,'companyId',p_company_id,'artifactId',a.id,'mandateId',m.id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'scope',a.scope,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'mimeType',a.mime_type,'byteLength',octet_length(a.source_bytes),'missing',CASE WHEN current THEN '[]'::jsonb WHEN m.id IS NOT NULL THEN '["current_legal_source_or_scope_held"]'::jsonb ELSE coalesce(r.missing,'["authentic_legal_rescission_issuer_and_separate_qualified_review"]'::jsonb) END);
 IF p_include_bytes THEN IF a.source_bytes IS NULL OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash THEN RAISE EXCEPTION 'supply_rescission_original_bytes_unavailable';END IF;out:=out||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;gridex_intake_session_result_v1 := out; PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'read'); RETURN gridex_intake_session_result_v1;
END$$;

--
-- Name: ediel_read_supply_rescission_mandate_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_supply_rescission_mandate_v1(p_company_id uuid, p_actor_user_id uuid, p_mandate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m gridex_supply_rescission.mandates%rowtype;BEGIN
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'archive') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_actor_forbidden' USING ERRCODE='42501';END IF;
 IF gridex_supply_rescission.mandate_current_v1(p_company_id,p_mandate_id) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO m FROM gridex_supply_rescission.mandates WHERE id=p_mandate_id AND company_id=p_company_id;
 RETURN m.scope||jsonb_build_object('status','authorized','version',1,'owner','immutable-national-supply-rescission-mandate-v1','mandateId',m.id,'actorUserId',p_actor_user_id,'sourceHash',m.source_hash,'lineItemReference','H'||replace(m.id::text,'-',''),'documentReference','H'||replace(m.id::text,'-',''));
END$$;

--
-- Name: ediel_read_supply_rescission_original_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_supply_rescission_original_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;cap jsonb;BEGIN
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_recorded_actor_forbidden' USING ERRCODE='42501';END IF;
 PERFORM gridex_supply_rescission.lock_original_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id;IF m.id IS NULL THEN IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_reader_forbidden' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 PERFORM gridex_supply_rescission.require_recorded_outbound_v1(m,p_actor_user_id);SELECT capability INTO cap FROM gridex_supply_rescission.outbound_operations WHERE company_id=p_company_id AND message_id=m.id;IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_terminal_reader_forbidden' USING ERRCODE='42501';END IF;RETURN cap||jsonb_build_object('originalActorUserId',cap->>'actorUserId','actorUserId',p_actor_user_id);
END$$;

