    AS $$
BEGIN IF current_user<>'service_role' THEN RAISE EXCEPTION 'ediel_dsn_service_required' USING ERRCODE='42501';END IF;RETURN gridex_ediel_transport.record_dsn_v1(p_input);END $$;

--
-- Name: ediel_record_inbound_reception_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_record_inbound_reception_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_inbound_email_message_id uuid, p_parse_result_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;mail public.inbound_email_messages%rowtype;p public.inbound_ediel_parse_results%rowtype;
 box public.ediel_mailboxes%rowtype;prior gridex_ediel_inbound_receptions.receptions%rowtype;r gridex_ediel_inbound_receptions.receptions%rowtype;canonical_hash text;incoming_hash text;kind text;
BEGIN
 PERFORM gridex_ediel_inbound_receptions.authorize_v1(p_company_id,p_actor_user_id,'communication.write');
 IF p_message_id IS NULL OR p_inbound_email_message_id IS NULL OR p_parse_result_id IS NULL THEN RAISE EXCEPTION 'ediel_real_reception_source_required';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR (m.environment IN('test','production')) IS NOT TRUE OR nullif(m.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_reception_original_not_owned';END IF;
 -- Serialize the exact retained receipt before its possible held projection;
 -- two different canonical selectors must not both upgrade a shared mail lock.
 SELECT * INTO mail FROM public.inbound_email_messages WHERE id=p_inbound_email_message_id FOR UPDATE;
 SELECT * INTO p FROM public.inbound_ediel_parse_results WHERE id=p_parse_result_id FOR SHARE;
 SELECT * INTO box FROM public.ediel_mailboxes WHERE id=mail.mailbox_id FOR SHARE;
 IF mail.id IS NULL OR p.id IS NULL OR p.inbound_email_message_id IS DISTINCT FROM mail.id OR p.company_id IS DISTINCT FROM p_company_id
  OR (mail.company_id IS NOT NULL AND mail.company_id IS DISTINCT FROM p_company_id)
  OR (mail.environment IS NOT NULL AND mail.environment IS DISTINCT FROM m.environment)
  OR box.id IS NULL OR box.environment IS DISTINCT FROM m.environment
  OR (box.company_id IS NOT NULL AND box.company_id IS DISTINCT FROM p_company_id AND box.is_shared_platform_mailbox IS NOT TRUE)
  OR mail.received_at IS NULL OR nullif(p.raw_payload,'') IS NULL
  OR p.sender_ediel_id IS DISTINCT FROM m.sender_ediel_id OR p.receiver_ediel_id IS DISTINCT FROM m.receiver_ediel_id
  OR p.application_reference IS DISTINCT FROM m.application_reference OR p.interchange_reference IS DISTINCT FROM m.interchange_reference
  OR p.message_family IS DISTINCT FROM m.message_family OR p.message_code IS DISTINCT FROM m.message_code
 THEN RAISE EXCEPTION 'ediel_real_reception_source_scope_required';END IF;
 PERFORM a.id FROM public.inbound_email_attachments a WHERE a.inbound_email_message_id=mail.id ORDER BY a.id FOR SHARE;
 -- The parse must come from the retained actual transport source. An editable
 -- parse projection alone cannot manufacture a new mailbox reception.
 IF NOT(coalesce(position(p.raw_payload IN mail.raw_edifact_payload),0)>0 OR coalesce(position(p.raw_payload IN mail.body_text),0)>0
  OR coalesce(position(p.raw_payload IN mail.raw_email),0)>0 OR EXISTS(SELECT FROM public.inbound_email_attachments a WHERE a.inbound_email_message_id=mail.id AND (a.company_id IS NULL OR a.company_id=p_company_id) AND coalesce(position(p.raw_payload IN a.raw_text),0)>0)) THEN RAISE EXCEPTION 'ediel_reception_retained_transport_bytes_required';END IF;
 canonical_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');incoming_hash:=encode(sha256(convert_to(p.raw_payload,'UTF8')),'hex');
 SELECT * INTO prior FROM gridex_ediel_inbound_receptions.receptions WHERE inbound_email_message_id=mail.id FOR SHARE;
 IF prior.id IS NOT NULL THEN
  IF prior.company_id IS DISTINCT FROM p_company_id OR prior.source_message_id IS DISTINCT FROM m.id OR prior.environment IS DISTINCT FROM m.environment
   OR prior.canonical_payload_hash IS DISTINCT FROM canonical_hash OR prior.received_payload_hash IS DISTINCT FROM incoming_hash THEN RAISE EXCEPTION 'ediel_reception_frozen_source_conflict';END IF;
  RETURN gridex_ediel_inbound_receptions.result_v1(prior,true);
 END IF;
 kind:=CASE WHEN incoming_hash IS DISTINCT FROM canonical_hash THEN 'identity_conflict'
  WHEN (m.mailbox_message_id=mail.id::text)
   AND NOT EXISTS(SELECT FROM gridex_ediel_inbound_receptions.receptions old WHERE old.source_message_id=m.id AND old.classification='first_reception') THEN 'first_reception'
  ELSE 'protocol_duplicate' END;
 IF box.email_address IS NULL OR btrim(box.email_address)!~'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$' THEN
  RAISE EXCEPTION 'ediel_original_mailbox_smtp_custody_required';END IF;
 INSERT INTO gridex_ediel_inbound_receptions.receptions(company_id,source_message_id,inbound_email_message_id,parse_result_id,actor_user_id,environment,canonical_payload_hash,received_payload_hash,received_at,classification,scope,transport_source_snapshot)
 VALUES(p_company_id,m.id,mail.id,p.id,p_actor_user_id,m.environment,canonical_hash,incoming_hash,mail.received_at,kind,jsonb_build_object('sender',p.sender_ediel_id,'receiver',p.receiver_ediel_id,'applicationReference',p.application_reference,'interchangeReference',p.interchange_reference,'family',p.message_family,'code',p.message_code),jsonb_build_object('mailboxId',mail.mailbox_id,'internetMessageId',mail.internet_message_id,'rawMessageSha256',mail.raw_message_sha256,'parsePayloadHash',incoming_hash,'sourceKind','retained_mail_observation','deliveryAuthenticated',false,'originalMailboxSmtpAddress',btrim(box.email_address),'originalMailboxCompanyId',box.company_id,'originalMailboxEnvironment',box.environment,'originalMailboxShared',box.is_shared_platform_mailbox)) RETURNING * INTO r;
 IF kind<>'first_reception' THEN
  INSERT INTO gridex_ediel_inbound_receptions.response_requests(reception_id,company_id,source_message_id,reason) VALUES(r.id,p_company_id,m.id,CASE kind WHEN 'identity_conflict' THEN 'same_identity_different_original_requires_review' ELSE 'authentic_duplicate_transport_response_policy_required' END);
  UPDATE public.inbound_email_messages SET company_id=p_company_id,processing_status='manual_review',match_status='protocol_response_held',error_message='Ny Ediel-mottagning kräver källbelagt protokollsvar.',match_payload=coalesce(match_payload,'{}')||jsonb_build_object('protocolReception',gridex_ediel_inbound_receptions.result_v1(r,false)),updated_at=clock_timestamp() WHERE id=mail.id AND (company_id IS NULL OR company_id=p_company_id);
 END IF;
 RETURN gridex_ediel_inbound_receptions.result_v1(r,false);
END $_$;

--
-- Name: ediel_record_scoped_capability_evidence_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text, text, uuid[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_record_scoped_capability_evidence_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text, p_expected_dependency_hash text, p_certification_evidence_ids uuid[], p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'gridex_ediel_readiness'
    AS $_$
DECLARE current_evidence jsonb; records jsonb; required text[]:=ARRAY['TGT','AGT','SHADOW_PRODUCTION','LIVE_TENANT_INTEGRITY','RESTORE_REPLAY']; proof_id uuid;
BEGIN
 current_evidence:=gridex_ediel_readiness.capture(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 IF p_expected_dependency_hash IS DISTINCT FROM current_evidence->>'dependencyHash' OR p_expires_at IS NULL OR p_expires_at<=clock_timestamp() OR cardinality(p_certification_evidence_ids) IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF EXISTS(SELECT FROM public.ediel_messages WHERE company_id=p_company_id AND environment='production' AND direction='outbound' AND message_family=p_family AND message_code=p_code AND status='sent') THEN required:=required||'LIMITED_PILOT'::text; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]') INTO records FROM public.ediel_certification_evidence e
  WHERE e.id=ANY(p_certification_evidence_ids) AND e.company_id=p_company_id AND e.environment='production' AND e.status='passed'
   AND e.external_reference IS NOT NULL AND e.evidence_document_reference IS NOT NULL AND e.approved_by IS NOT NULL AND e.approved_at IS NOT NULL
   AND e.tested_at IS NOT NULL AND e.tested_at<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>=p_expires_at)
   AND e.metadata->'edielScopedReadiness'->'scope'=current_evidence->'scope'
   AND e.metadata->'edielScopedReadiness'->>'dependencyHash'=p_expected_dependency_hash
   AND jsonb_typeof(e.metadata#>'{edielScopedReadiness,tests}')='array'
   AND jsonb_array_length(e.metadata#>'{edielScopedReadiness,tests}')>0
   AND NOT EXISTS(SELECT FROM jsonb_array_elements(e.metadata#>'{edielScopedReadiness,tests}') t WHERE jsonb_typeof(t)<>'object'
     OR nullif(t->>'testId','') IS NULL OR nullif(t->>'sourceRevision','') IS NULL OR nullif(t->>'evidenceReference','') IS NULL
     OR t->>'candidateSha' IS DISTINCT FROM p_release_sha OR t->>'result' IS DISTINCT FROM 'passed' OR coalesce(t->>'payloadSha256','') !~ '^[0-9a-f]{64}$');
 IF jsonb_array_length(records)<>cardinality(p_certification_evidence_ids) OR EXISTS(SELECT FROM unnest(required) k WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(records) e WHERE e->>'evidence_type'=k)) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 INSERT INTO gridex_ediel_readiness.evidence(company_id,scope,dependency_hash,dependencies,certification_records,expires_at)
 VALUES(p_company_id,current_evidence->'scope',p_expected_dependency_hash,current_evidence->'dependencies',records,p_expires_at)
 ON CONFLICT(company_id,scope,dependency_hash,expires_at) DO NOTHING RETURNING id INTO proof_id;
 IF proof_id IS NULL THEN SELECT id INTO proof_id FROM gridex_ediel_readiness.evidence WHERE company_id=p_company_id AND scope=current_evidence->'scope' AND dependency_hash=p_expected_dependency_hash AND expires_at=p_expires_at; END IF;
 RETURN proof_id;
END $_$;

--
-- Name: ediel_record_technical_syntax_facet_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_record_technical_syntax_facet_v1(p_company_id uuid, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;RETURN gridex_ediel_technical_ack.record_syntax_v1(p_company_id,p_source_message_id,p_source_payload_hash,p_facts_text);END $$;

--
-- Name: ediel_record_technical_syntax_facet_v2(uuid, uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_record_technical_syntax_facet_v2(p_company_id uuid, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_actor_user_id uuid, p_phase text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE env text;r jsonb;BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 SELECT environment INTO env FROM public.ediel_messages WHERE id=p_source_message_id;
 PERFORM gridex_ediel_technical_ack.require_actor_v1(p_company_id,env,p_actor_user_id,p_phase);
 r:=gridex_ediel_technical_ack.record_syntax_v1(p_company_id,p_source_message_id,p_source_payload_hash,p_facts_text);
 PERFORM gridex_ediel_technical_ack.require_actor_v1(p_company_id,env,p_actor_user_id,p_phase);
 RETURN r;
END$$;

--
-- Name: ediel_register_invoice_file_source_v1(uuid, uuid, text, uuid, text, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_register_invoice_file_source_v1(p_company_id uuid, p_actor_user_id uuid, p_retention_class text, p_target_id uuid, p_target_hash text, p_storage_object_id uuid, p_source_hash text, p_byte_length bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE l jsonb;s gridex_ediel_retention.invoice_file_sources%rowtype;BEGIN
 -- Service-only producer executes after authenticated current scope and actual
 -- server Storage download; it repeats current native actor/class qualification.
 IF gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.submit') IS NOT TRUE OR gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.invoice_copy_evidence') IS NOT TRUE THEN RAISE EXCEPTION 'invoice_file_current_capture_actor_required' USING ERRCODE='42501';END IF;
 l:=gridex_ediel_retention.invoice_file_locator_v1(p_company_id,p_retention_class,p_target_id);
 IF l->>'targetHash' IS DISTINCT FROM p_target_hash OR l->>'storageObjectId' IS DISTINCT FROM p_storage_object_id::text OR (l->>'storageByteLength')::bigint IS DISTINCT FROM p_byte_length OR p_source_hash!~'^[a-f0-9]{64}$' OR p_byte_length NOT BETWEEN 1 AND 20971520 THEN RAISE EXCEPTION 'invoice_file_storage_capture_binding_changed';END IF;
 IF EXISTS(SELECT FROM gridex_ediel_retention.invoice_file_sources captured JOIN gridex_ediel_retention.invoice_file_tombstones t ON t.source_id=captured.id WHERE captured.storage_bucket=l->>'storageBucket' AND captured.storage_path=l->>'storagePath') THEN RAISE EXCEPTION 'invoice_file_storage_tombstoned';END IF;
 INSERT INTO gridex_ediel_retention.invoice_file_sources(company_id,retention_class,target_id,target_hash,storage_object_id,storage_bucket,storage_path,source_hash,byte_length,captured_by) VALUES(p_company_id,p_retention_class,p_target_id,p_target_hash,p_storage_object_id,l->>'storageBucket',l->>'storagePath',p_source_hash,p_byte_length,p_actor_user_id) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT s FROM gridex_ediel_retention.invoice_file_sources WHERE company_id=p_company_id AND retention_class=p_retention_class AND target_id=p_target_id FOR SHARE;
 IF s.target_hash<>p_target_hash OR s.source_hash<>p_source_hash OR s.byte_length<>p_byte_length OR s.storage_object_id<>p_storage_object_id THEN RAISE EXCEPTION 'invoice_file_original_capture_conflict';END IF;
 RETURN jsonb_build_object('sourceId',s.id,'sourceHash',s.source_hash,'byteLength',s.byte_length,'retentionClass',s.retention_class,'targetId',s.target_id,'authority','none');END$_$;

