--
-- Name: ediel_require_invoice_source_copies_available_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_invoice_source_copies_available_v1(p_company_id uuid, p_underlay_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_export_item_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE source uuid;BEGIN
 IF p_underlay_id IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(p_company_id,'billing_underlay_source_body',p_underlay_id::text);PERFORM public.ediel_require_finance_copy_available_v1(p_company_id,'billing_underlay_payload_body',p_underlay_id::text);SELECT portfolio_monthly_settlement_id INTO source FROM public.billing_underlays WHERE company_id=p_company_id AND id=p_underlay_id;IF source IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(p_company_id,'settlement_calculation_body',source::text);END IF;END IF;
 IF p_invoice_id IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(p_company_id,'invoice_calculation_body',p_invoice_id::text);END IF;IF p_export_item_id IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(p_company_id,'invoice_export_item_body',p_export_item_id::text);END IF;END$$;

--
-- Name: ediel_require_message_consumed_records_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_message_consumed_records_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE contract uuid;source uuid;BEGIN
 PERFORM id FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'retention_consumed_message_scope_required';END IF;
 FOR contract IN SELECT o.contract_id FROM gridex_received_sources.switch_originals o WHERE o.company_id=p_company_id AND o.message_id=p_message_id UNION SELECT e.contract_id FROM gridex_requested_changes.events e JOIN public.ediel_messages m ON m.company_id=e.company_id AND m.source_operation_id=e.id::text WHERE m.id=p_message_id AND e.company_id=p_company_id LOOP PERFORM public.ediel_require_contract_records_available_v1(p_company_id,contract);END LOOP;
 -- Immutable original-message links are native source selectors, never body
 -- metadata or an untrusted caller array. Byte retention has its own owner.
 SELECT CASE WHEN original_message_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN original_message_id::uuid END INTO source FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id;IF source IS NOT NULL THEN PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,source);END IF;
END$_$;

--
-- Name: ediel_require_metering_method_change_source_current_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_metering_method_change_source_current_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_requested_changes.origins%rowtype;b jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE company_id=p_company_id AND message_id=p_message_id FOR SHARE;
 IF NOT FOUND OR (o.basis->>'variant' IN('F','G')) IS NOT TRUE THEN
  PERFORM gridex_metering_method_changes.require_source_before_requested_changes_v1(p_company_id,p_message_id,p_actor_user_id);RETURN;
 END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR SHARE;
 b:=gridex_requested_changes.require_message_v1(m,p_actor_user_id,'communication.send');
 IF b IS DISTINCT FROM o.basis OR gridex_metering_method_changes.frozen_original_basis_v1(p_company_id,p_message_id) IS NULL THEN RAISE EXCEPTION 'ediel_method_expectation_requested_original_required';END IF;
END $$;

--
-- Name: ediel_require_portal_retention_access_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_portal_retention_access_v1(p_company_id uuid, p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE revoked_at timestamptz;BEGIN
 PERFORM id FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'customer_record_customer_scope_required';END IF;
 IF EXISTS(SELECT FROM gridex_ediel_retention.customer_tombstones WHERE company_id=p_company_id AND customer_id=p_customer_id) THEN RAISE EXCEPTION 'portal_customer_retention_access_revoked';END IF;
 SELECT max(created_at) INTO revoked_at FROM gridex_ediel_retention.record_tombstones WHERE company_id=p_company_id AND customer_id=p_customer_id;
 IF revoked_at IS NOT NULL AND NOT (EXISTS(SELECT FROM public.customer_portal_accounts WHERE company_id=p_company_id AND customer_id=p_customer_id AND status='active' AND is_active AND created_at>revoked_at) AND EXISTS(SELECT FROM public.customer_portal_claims WHERE company_id=p_company_id AND customer_id=p_customer_id AND status='approved' AND created_at>revoked_at)) THEN RAISE EXCEPTION 'portal_customer_retention_access_revoked';END IF;
END$$;

