 IF EXISTS(SELECT FROM gridex_ediel_retention.process_tombstones WHERE company_id=p_company_id AND retention_class=p_retention_class AND target_id=p_target_id) THEN RAISE EXCEPTION 'process_journal_retention_tombstoned';END IF;PERFORM gridex_ediel_retention.process_basis_v1(p_company_id,p_retention_class,p_target_id);END$$;

--
-- Name: ediel_require_prodat_bilateral_positive_source_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_prodat_bilateral_positive_source_v1(p_company_id uuid, p_source_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;facet gridex_received_sources.prodat_object_validation_facets%rowtype;tr gridex_received_sources.supply_source_transitions%rowtype;prior gridex_bilateral_prodat.source_capability_receipts%rowtype;
 wire jsonb;guide jsonb;own jsonb;cap jsonb;positive jsonb:='[]';ids uuid[];point public.metering_points%rowtype;state jsonb;event_at timestamptz;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RETURN;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z25','Z26','Z70') OR wire->>'code'='Z05' AND o->>'reason'='Z23')) THEN RETURN;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);
 SELECT * INTO prior FROM gridex_bilateral_prodat.source_capability_receipts WHERE source_message_id=m.id;
 IF FOUND THEN PERFORM public.ediel_require_recorded_prodat_bilateral_ack_source_v1(m.company_id,m.id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'));RETURN;END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
 SELECT * INTO facet FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=canonical.id AND company_id=m.company_id AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=canonical.source_payload_hash;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id AND company_id=m.company_id;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR (canonical.facts_text::jsonb->>'applicationDecision' IN('accepted','rejected')) IS NOT TRUE OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR facet.facts_text::jsonb->>'sharedAccepted' IS DISTINCT FROM 'true' OR facet.facts_text::jsonb->>'owner' IS DISTINCT FROM 'canonical-full-prodat-object-validation-v1'
  OR facet.facts_text::jsonb->>'coverage' IS DISTINCT FROM 'full_canonical_guide_objects_only' OR facet.facts_hash IS DISTINCT FROM encode(sha256(convert_to(facet.facts_text,'UTF8')),'hex')
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR tr.source_message_id IS NULL OR tr.payload_hash IS DISTINCT FROM canonical.source_payload_hash OR tr.source_code IS DISTINCT FROM wire->>'code'
  OR EXISTS(SELECT FROM jsonb_array_elements(facet.facts_text::jsonb->'objects') o WHERE o->>'disposition'='unavailable')
  OR jsonb_array_length(facet.facts_text::jsonb->'objects') IS DISTINCT FROM jsonb_array_length(wire->'objects') THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
 FOR guide IN SELECT o FROM jsonb_array_elements(facet.facts_text::jsonb->'objects') o WHERE o->>'disposition'='accepted' LOOP
  SELECT o INTO own FROM jsonb_array_elements(wire->'objects') o WHERE o->>'point'=guide->>'objectId' AND o->>'identityAgency'=guide->>'identityAgency' AND o->>'li'=guide->>'lineItemReference' AND gridex_bilateral_prodat.first_line_index_v1(m.raw_payload,o)=(guide->>'firstLineIndex')::integer;
  IF own IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o-'registerCount'=own-'registerCount') THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  IF NOT(own->>'reason' IN('Z25','Z26','Z70') OR wire->>'code'='Z05' AND own->>'reason'='Z23') THEN CONTINUE;END IF;
  cap:=gridex_bilateral_prodat.own_source_capability_v1(m,wire,own);IF cap IS NULL THEN RAISE EXCEPTION 'prodat_bilateral_current_authority_required';END IF;
  SELECT array_agg(mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_owner_ediel_id=wire->>'sender' AND mp.grid_area_code=own->>'gridArea';
  IF coalesce(cardinality(ids),0)<>1 THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id;
  SELECT p INTO state FROM jsonb_array_elements(tr.resulting_states) p WHERE p->>'metering_point_id'=point.id::text AND p->>'customer_id'=point.customer_id::text;
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF state IS NULL OR event_at IS NULL OR NOT EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id::text=state->>'id' AND to_jsonb(p)-ARRAY['updated_at','status']=state-ARRAY['updated_at','status']) THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  IF cap->>'owner'='immutable-regulated-supply-ground-v1' AND (state#>>'{metadata,sourceGroundId}' IS DISTINCT FROM cap->>'profileVersionId' OR state->>'source_message_id' IS DISTINCT FROM m.id::text) THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  IF cap->>'process'='normal_start_h' AND NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations confirmation WHERE confirmation.source_message_id=m.id AND confirmation.company_id=m.company_id AND confirmation.period_id::text=state->>'id' AND confirmation.source_object=own) THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  IF cap->>'process'='own_end_h' AND (state->>'source_end_message_id' IS DISTINCT FROM m.id::text OR (state->>'market_end_at')::timestamptz IS DISTINCT FROM event_at) THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  IF cap->>'process'='closure_request_lk' AND (state->>'source_end_message_id' IS DISTINCT FROM m.id::text OR gridex_bilateral_prodat.recorded_closure_end_current_v1(m.company_id,m.id) IS NOT TRUE) THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
  positive:=positive||jsonb_build_array(cap||jsonb_build_object('pointId',point.id,'eventAt',event_at,'supplyPeriodId',state->>'id'));
 END LOOP;
 IF jsonb_array_length(positive)=0 THEN RAISE EXCEPTION 'prodat_bilateral_positive_source_unqualified';END IF;
 INSERT INTO gridex_bilateral_prodat.source_capability_receipts(source_message_id,company_id,environment,source_payload_hash,assessment_id,object_facts_hash,positive_objects,business_transition_hash)
 VALUES(m.id,m.company_id,m.environment,canonical.source_payload_hash,canonical.id,facet.facts_hash,positive,encode(sha256(convert_to(to_jsonb(tr)::text,'UTF8')),'hex'));
 PERFORM public.ediel_require_recorded_prodat_bilateral_ack_source_v1(m.company_id,m.id,canonical.source_payload_hash);
END$$;

--
-- Name: ediel_require_prodat_recovery_current_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_prodat_recovery_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;m public.ediel_messages%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=p_message_id AND operation.company_id=p_company_id;
 IF op.id IS NULL THEN RETURN;END IF;
 PERFORM gridex_received_sources.prelock_recovery_source_cohort_v1(p_company_id,op.id,p_message_id);
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.environment IS DISTINCT FROM op.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT'
  OR m.source_operation_id IS DISTINCT FROM op.id::text OR m.original_message_id IS DISTINCT FROM op.original_message_id::text
  OR m.raw_payload IS DISTINCT FROM op.corrected_raw_payload OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_current_source_required';END IF;
 -- Source-only: actual sender/worker is authorized by its existing journal.
 -- An inactive historical creator cannot invalidate genuine immutable source.
 PERFORM gridex_received_sources.qualified_recovery_origin_v1(p_company_id,op.id);
END$$;

--
-- Name: ediel_require_recorded_prodat_bilateral_ack_source_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_recorded_prodat_bilateral_ack_source_v1(p_company_id uuid, p_source_message_id uuid, p_source_payload_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE tr gridex_received_sources.supply_source_transitions%rowtype;r gridex_bilateral_prodat.source_capability_receipts%rowtype;m public.ediel_messages%rowtype;own jsonb;g gridex_received_sources.regulated_supply_ground_versions%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;wire jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM gridex_bilateral_prodat.source_capability_receipts WHERE source_message_id=p_source_message_id AND company_id=p_company_id;
 IF r.source_message_id IS NULL THEN
  wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
  IF m.message_family='PRODAT' AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z25','Z26','Z70') OR wire->>'code'='Z05' AND o->>'reason'='Z23')) THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;RETURN;
 END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=r.source_message_id AND company_id=r.company_id;
 IF tr.source_message_id IS NULL OR encode(sha256(convert_to(to_jsonb(tr)::text,'UTF8')),'hex') IS DISTINCT FROM r.business_transition_hash THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
 IF m.id IS NULL OR r.environment IS DISTINCT FROM m.environment OR r.source_payload_hash IS DISTINCT FROM p_source_payload_hash
  OR NOT EXISTS(SELECT FROM gridex_received_sources.sources original WHERE original.source_message_id=r.source_message_id AND original.company_id=r.company_id AND original.environment=r.environment AND original.payload_hash=r.source_payload_hash)
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments assessment JOIN gridex_received_sources.prodat_object_validation_facets facet ON facet.assessment_id=assessment.id AND facet.facts_hash=r.object_facts_hash WHERE assessment.id=r.assessment_id AND assessment.company_id=r.company_id AND assessment.environment=r.environment AND assessment.source_message_id=r.source_message_id AND assessment.source_payload_hash=r.source_payload_hash) THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(r.positive_objects) o WHERE o->>'process'='closure_request_lk') AND gridex_bilateral_prodat.recorded_closure_end_current_v1(m.company_id,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(r.positive_objects) o LOOP
  IF own->>'owner'='immutable-regulated-supply-ground-v1' THEN
   SELECT * INTO g FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=(own->>'profileVersionId')::uuid AND company_id=r.company_id;
   IF g.id IS NULL OR g.source_sha256 IS DISTINCT FROM own->>'sourceHash' OR right(g.registry_version,64) IS DISTINCT FROM own->>'sourceGrammarHash'
    OR gridex_regulated_supply.ground_current_v1(g.id,r.company_id,(own->>'pointId')::uuid,(own->>'eventAt')::timestamptz) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
  ELSIF own->>'owner'='immutable-bilateral-prodat-profile-v1' THEN
   SELECT archived.* INTO a FROM gridex_bilateral_prodat.origins origin JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=origin.artifact_id AND archived.company_id=origin.company_id WHERE origin.ground_id=(own->>'profileVersionId')::uuid AND origin.company_id=r.company_id;
   IF a.id IS NULL OR a.source_hash IS DISTINCT FROM own->>'sourceHash' OR a.scope->>'sourceGrammarHash' IS DISTINCT FROM own->>'sourceGrammarHash' OR gridex_bilateral_prodat.recorded_profile_authority_v1((own->>'profileVersionId')::uuid,r.company_id) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
  ELSE RAISE EXCEPTION 'prodat_bilateral_recorded_source_authority_required';END IF;
 END LOOP;
END$$;

--
-- Name: ediel_require_requested_change_source_current_before_scope_fenc(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_requested_change_source_current_before_scope_fenc(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_requested_changes.origins%rowtype;tokens jsonb;q jsonb;
BEGIN SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;IF m.direction IS DISTINCT FROM 'outbound' THEN RETURN;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='Z09') OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='CAV' AND t#>>'{elements,1,0}' IN('E34','E64','E32')) THEN RETURN;END IF;
 SELECT * INTO o FROM gridex_requested_changes.origins WHERE message_id=m.id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND THEN

  IF EXISTS(SELECT FROM gridex_customer_life_events.originals life_original
    WHERE life_original.company_id=p_company_id AND life_original.message_id=m.id) THEN
   SELECT gridex_customer_life_events.require_current_v1(p_company_id,m.id,life_origin.actor_user_id,'prepare') INTO q
    FROM gridex_customer_life_events.originals life_original
    JOIN gridex_customer_life_events.origins life_origin ON life_origin.event_id=life_original.event_id AND life_origin.company_id=life_original.company_id
    WHERE life_original.company_id=p_company_id AND life_original.message_id=m.id;
   IF q#>>'{basis,status}' IS DISTINCT FROM 'authorized' THEN
    RAISE EXCEPTION 'customer_life_event_current_original_scope_changed';
   END IF;
   RETURN;
  END IF;
  IF m.environment='test' AND m.message_standard='edifact' AND m.message_family='PRODAT' AND m.message_code='Z09' THEN
   -- The established fixture owner checks actual registered original/run/step/
   -- role and sole-consumed message. No live business approval is created.
   q:=gridex_negative_fixtures.require_positive_message_v1(p_company_id,p_message_id,'Z09');
   IF q->>'kind'='source_qualified_positive_fixture' AND q->>'version'='1' AND q->>'companyId'=p_company_id::text AND q->>'roleCode'='supplier' AND q->>'suite'='PRODAT' AND q->>'expectedOutcome'='positive' AND q->'expectedDiagnosticCodes'='[]'::jsonb AND q->'authorizesBusinessEffect'='false'::jsonb THEN RETURN;END IF;
  END IF;
  RAISE EXCEPTION 'requested_change_original_origin_required';
 END IF;PERFORM gridex_requested_changes.require_message_v1(m,o.actor_user_id);
END$$;

--
-- Name: ediel_require_requested_change_source_current_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_requested_change_source_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM public.ediel_require_requested_change_source_current_before_scope_fence_v1(p_company_id,p_message_id);RETURN;END$$;

--
-- Name: ediel_require_scoped_capability_for_message_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_scoped_capability_for_message_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'gridex_ediel_readiness'
    AS $$
DECLARE m public.ediel_messages%rowtype; proof gridex_ediel_readiness.evidence%rowtype; release_sha text; current_evidence jsonb; derived jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR m.direction<>'outbound' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF m.environment<>'production' OR m.message_family IN ('CONTRL','APERAK','UTILTS_ERR') OR (m.message_family='UTILTS' AND m.message_code='ERR') THEN RETURN; END IF;
 IF m.message_family NOT IN ('PRODAT','UTILTS','AI_LIST') THEN RETURN; END IF;
 derived:=gridex_ediel_readiness.source_scope(m);
 SELECT r.release_sha INTO release_sha FROM public.platform_release_receipts r WHERE r.environment='production' AND r.status='verified' AND r.verified_at IS NOT NULL ORDER BY r.verified_at DESC,r.recorded_at DESC,r.id LIMIT 1 FOR SHARE;
 FOR proof IN SELECT e.* FROM gridex_ediel_readiness.evidence e WHERE e.company_id=p_company_id AND e.scope->>'actorId'=derived->>'actorId'
  AND e.scope->>'actorRole'=derived->>'actorRole' AND e.scope->>'family'=derived->>'family' AND e.scope->>'code'=derived->>'code'
  AND e.scope->>'subtype' IS NOT DISTINCT FROM derived->>'subtype' AND e.scope->>'assignmentId' IS NOT DISTINCT FROM derived->>'assignmentId'
  AND e.expires_at>clock_timestamp() ORDER BY e.verified_at DESC,e.id LOOP
  BEGIN
   current_evidence:=public.ediel_scoped_capability_readiness_v1(p_company_id,m.id,(derived->>'actorId')::uuid,derived->>'actorRole',derived->>'family',derived->>'code',derived->>'subtype',(derived->>'assignmentId')::uuid,release_sha,CASE WHEN m.message_family='AI_LIST' THEN proof.dependencies->>'rulepackHash' ELSE m.rule_pack_checksum END);
   IF current_evidence->'ready'='true'::jsonb THEN RETURN; END IF;
  EXCEPTION WHEN SQLSTATE 'P0001' THEN CONTINUE;
  END;
 END LOOP;
 RAISE EXCEPTION 'ediel_scoped_capability_evidence_required';
END $$;

--
-- Name: ediel_require_service_permission_origin_current_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_service_permission_origin_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;origin jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 IF p_company_id IS NULL OR p_message_id IS NULL THEN RAISE EXCEPTION 'ediel_service_permission_scope_required';END IF;
 PERFORM gridex_service_permission.require_original_source_current_v1(p_company_id,p_message_id);
 SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=p_message_id AND operation.company_id=p_company_id;
 IF op.id IS NULL THEN RETURN;END IF;
 PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,p_message_id);
 -- Same original service authority, without treating its preparer as today's
 -- transport executor. No new intent is rebound to an old service origin.
 origin:=gridex_received_sources.qualified_recovery_origin_v1(p_company_id,op.id);
 PERFORM gridex_service_permission.require_original_source_current_v1(p_company_id,(origin->>'sourceOriginMessageId')::uuid);
END$$;

--
-- Name: ediel_require_source_bytes_available_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_source_bytes_available_v1(p_company_id uuid, p_source_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones WHERE company_id=p_company_id AND message_id=p_source_message_id) THEN RAISE EXCEPTION 'ediel_original_bytes_retention_tombstoned';END IF;END$$;

--
-- Name: ediel_require_source_rule_pack_basis_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_source_rule_pack_basis_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_ediel_source_rules.require_v1(p_company_id,p_message_id);
END $$;

--
-- Name: ediel_require_switch_cancellation_source_current_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_switch_cancellation_source_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_switch_cancellations.origins%rowtype;b jsonb;w jsonb;q jsonb;positive boolean;negative boolean;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;
BEGIN
 PERFORM gridex_switch_cancellations.prelock_customer_message_v1(p_company_id,p_message_id); SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'switch_cancellation_message_scope_required';END IF;
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE message_id=m.id AND company_id=p_company_id;
 IF o.message_id IS NULL AND m.environment='test' AND m.direction='outbound' AND m.message_standard='edifact' AND m.message_family='PRODAT' AND m.message_code='Z03' THEN
  SELECT EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.message_id=m.id AND c.company_id=p_company_id),
   EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions c WHERE c.message_id=m.id AND c.company_id=p_company_id) INTO positive,negative;
  IF positive AND negative THEN RAISE EXCEPTION 'switch_cancellation_fixture_source_ambiguous';END IF;
  IF positive OR negative THEN
   q:=CASE WHEN positive THEN gridex_negative_fixtures.require_positive_message_v1(p_company_id,m.id,'Z03') ELSE gridex_negative_fixtures.require_negative_message_v1(p_company_id,m.id,'Z03') END;
   IF q IS NULL OR q->>'companyId' IS DISTINCT FROM p_company_id::text OR q->>'version' IS DISTINCT FROM '1' OR q->>'roleCode' IS DISTINCT FROM 'supplier'
    OR q->'authorizesBusinessEffect' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(q->'expectedDiagnosticCodes') IS DISTINCT FROM 'array'
    OR (positive AND (q->>'kind' IS DISTINCT FROM 'source_qualified_positive_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'positive' OR q->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb))
    OR (negative AND (q->>'kind' IS DISTINCT FROM 'source_qualified_negative_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'negative' OR jsonb_array_length(q->'expectedDiagnosticCodes') NOT BETWEEN 1 AND 256))
   THEN RAISE EXCEPTION 'switch_cancellation_fixture_source_required';END IF;
   -- Genuine certification provenance only. No production cancellation origin,
   -- switch status or supply history is created by this branch.
   RETURN;
  END IF;
 END IF;
 w:=gridex_received_sources.supply_wire_v1(m.raw_payload);
 IF w->>'code' IS DISTINCT FROM 'Z03' OR NOT EXISTS(SELECT FROM jsonb_array_elements(w->'objects') own WHERE own->>'reason'='Z24') THEN RETURN;END IF;
 IF gridex_received_sources.switch_origin_wire_v1(m.raw_payload) IS NULL THEN RAISE EXCEPTION 'switch_cancellation_exact_original_wire_required';END IF;
 IF o.message_id IS NULL OR o.payload_hash IS DISTINCT FROM m.immutable_payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_cancellation_private_origin_required';END IF;
 b:=gridex_switch_cancellations.context_v1(o.company_id,o.switch_id,o.actor_user_id,false);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR i.validation_status IS DISTINCT FROM 'validated' OR to_jsonb(i)-ARRAY['created_at','updated_at','validation_status','validation_report','render_status','outbox_status','ack_status','ediel_message_id','outbound_request_id'] IS DISTINCT FROM o.intent_binding
  OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.operation_id IS DISTINCT FROM i.operation_id
  OR r.payload->>'environment' IS DISTINCT FROM m.environment OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'switch_cancellation_current_intent_request_required';END IF;
 IF b->>'status' IS DISTINCT FROM 'authorized' OR (b-ARRAY['operationId','intentId','outboundRequestId','messageId']) IS DISTINCT FROM o.basis THEN RAISE EXCEPTION 'switch_cancellation_current_source_held';END IF;
 PERFORM gridex_switch_cancellations.require_original_method_v1(o.company_id,o.original_message_id,o.original_hash,m.environment,m.raw_payload);
END $$;

--
-- Name: ediel_require_switch_original_current_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_switch_original_current_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;s public.supplier_switch_requests%rowtype;
 c public.customer_contracts%rowtype;mp public.metering_points%rowtype;r public.outbound_requests%rowtype;i public.ediel_message_intents%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype; expected_operation uuid;expected_request_source uuid;expected_request_type text;q jsonb;w jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'switch_original_message_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' THEN RETURN;END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);
 -- Z03C has its own cancellation owner, never a new normal-switch original.
 IF w IS NOT NULL AND w#>>'{objects,0,reason}'='Z24' THEN RETURN;END IF;
 IF gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS TRUE THEN
  IF public.ediel_read_bilateral_prodat_outbound_original_v1(m.company_id,m.id) IS NULL THEN RAISE EXCEPTION 'switch_original_current_source_required';END IF;
  RETURN;
 END IF;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=m.company_id;
 IF NOT FOUND THEN
  IF m.environment IS DISTINCT FROM 'test' THEN RAISE EXCEPTION 'switch_original_source_required';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id)
   AND EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN RAISE EXCEPTION 'switch_fixture_source_ambiguous';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_positive_message_v1(m.company_id,m.id,'Z03');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_positive_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'positive' OR q->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'switch_fixture_positive_scope_required';END IF;
  ELSIF EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_negative_message_v1(m.company_id,m.id,'Z03');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_negative_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'negative' OR jsonb_typeof(q->'expectedDiagnosticCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'expectedDiagnosticCodes') NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'switch_fixture_negative_scope_required';END IF;
  ELSE RAISE EXCEPTION 'switch_original_source_required';END IF;
  IF q->>'companyId' IS DISTINCT FROM m.company_id::text OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'switch_fixture_supplier_scope_required';END IF;
  RETURN;
 END IF;
 expected_operation:=o.switch_id;expected_request_source:=o.switch_id;expected_request_type:='supplier_switch_request';
 IF o.recovery_operation_id IS NOT NULL THEN
  SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
  IF op.id IS DISTINCT FROM o.recovery_operation_id OR (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR m.original_message_id IS DISTINCT FROM op.original_message_id::text THEN RAISE EXCEPTION 'switch_correction_current_operation_required';END IF;
  PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,m.id);
  expected_operation:=op.id;expected_request_source:=o.intent_id;expected_request_type:='manual';
 END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=o.switch_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=o.contract_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=s.company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id FOR SHARE;
 IF i.id IS NULL OR i.operation_id IS DISTINCT FROM expected_operation OR i.supplier_switch_request_id IS DISTINCT FROM s.id OR m.source_operation_id IS DISTINCT FROM expected_operation::text OR w IS NULL OR (w#>>'{objects,0,reason}' IN('Z22','Z23')) IS NOT TRUE
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.switch_request_id IS DISTINCT FROM s.id OR m.customer_id IS DISTINCT FROM s.customer_id OR m.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id) OR m.metering_point_id IS DISTINCT FROM s.metering_point_id
  OR r.id IS NULL OR (r.payload->>'environment') IS DISTINCT FROM m.environment OR r.source_type IS DISTINCT FROM expected_request_type OR r.source_id IS DISTINCT FROM expected_request_source OR r.operation_id IS DISTINCT FROM expected_operation OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id
  OR s.id IS NULL OR c.id IS NULL OR mp.id IS NULL OR s.outbound_z03_message_id IS DISTINCT FROM m.id OR s.inbound_z04_message_id IS NOT NULL OR s.lifecycle_blocked IS DISTINCT FROM false OR (s.status IN('prepared','queued','submitted')) IS NOT TRUE
  OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM c.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM c.id)
  OR (s.site_id IS NOT NULL AND s.site_id IS DISTINCT FROM m.site_id) OR (s.customer_site_id IS NOT NULL AND s.customer_site_id IS DISTINCT FROM m.site_id)
  OR s.rff_li_reference IS DISTINCT FROM o.original_object->>'li' OR w#>'{objects,0}' IS DISTINCT FROM o.original_object
  OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM o.contract_hash OR (c.status IN('signed','active')) IS NOT TRUE
  OR c.customer_id IS DISTINCT FROM m.customer_id OR c.metering_point_id IS DISTINCT FROM mp.id OR mp.customer_id IS DISTINCT FROM m.customer_id OR mp.site_id IS DISTINCT FROM m.site_id
  OR o.original_object->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''))
  THEN RAISE EXCEPTION 'switch_original_current_source_required';END IF;
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,c.id);
END $$;

--
-- Name: ediel_require_technical_syntax_ack_basis_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_technical_syntax_ack_basis_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;RETURN gridex_ediel_technical_ack.require_source_v1(p_company_id,p_message_id);END $$;

--
-- Name: ediel_require_technical_syntax_ack_basis_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_require_technical_syntax_ack_basis_v2(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_phase text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE env text;r jsonb;BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 SELECT environment INTO env FROM public.ediel_messages WHERE id=p_message_id;
 PERFORM gridex_ediel_technical_ack.require_actor_v1(p_company_id,env,p_actor_user_id,p_phase);
 r:=gridex_ediel_technical_ack.require_source_v1(p_company_id,p_message_id);
 PERFORM gridex_ediel_technical_ack.require_actor_v1(p_company_id,env,p_actor_user_id,p_phase);
 RETURN r;
END$$;

--
-- Name: ediel_reserve_brp_change_origin_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_brp_change_origin_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE basis jsonb;
prior gridex_brp_changes.origins%rowtype;
i public.ediel_message_intents%rowtype;
r public.outbound_requests%rowtype;

BEGIN basis:=gridex_brp_changes.context_v1(p_company_id,p_event_id,p_actor_user_id);
IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;
END IF;

 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('brp-change:'||p_company_id::text||':'||p_event_id::text,0));
SELECT * INTO prior FROM gridex_brp_changes.origins WHERE company_id=p_company_id
  AND event_id=p_event_id FOR UPDATE;

 IF FOUND THEN IF prior.intent_id IS DISTINCT FROM p_intent_id
  OR prior.basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'brp_change_frozen_origin_conflict';
END IF;
RETURN jsonb_build_object('status','reserved','messageId',prior.message_id,'outboundRequestId',prior.outbound_request_id);
END IF;

 SELECT * INTO i FROM public.ediel_message_intents WHERE company_id=p_company_id
  AND id=p_intent_id FOR SHARE;
SELECT * INTO r FROM public.outbound_requests WHERE company_id=p_company_id
  AND id=p_outbound_request_id FOR SHARE;

 IF i.id IS NULL
  OR r.id IS NULL
  OR i.environment IS DISTINCT FROM basis->>'environment'
  OR i.direction IS DISTINCT FROM 'outbound'
  OR i.message_family IS DISTINCT FROM 'PRODAT'
  OR i.message_code IS DISTINCT FROM 'Z09'
  OR i.operation_id IS DISTINCT FROM p_event_id
  OR i.customer_site_id IS DISTINCT FROM (basis->>'siteId')::uuid
  OR i.customer_id IS DISTINCT FROM (basis->>'customerId')::uuid
  OR i.metering_point_id IS DISTINCT FROM basis->>'pointId'
  OR i.validation_status IS DISTINCT FROM 'validated'
  OR i.application_reference IS DISTINCT FROM '23-DDQ-PRODAT'
  OR r.payload->>'environment' IS DISTINCT FROM basis->>'environment'
  OR r.request_type IS DISTINCT FROM 'customer_masterdata'
  OR r.source_type IS DISTINCT FROM 'manual'
  OR i.communication_route_id IS NULL
  OR i.route_profile_id IS NULL
  OR nullif(i.interchange_reference,'') IS NULL
  OR nullif(i.message_reference,'') IS NULL
  OR nullif(i.transaction_reference,'') IS NULL
  OR r.source_id::text IS DISTINCT FROM i.id::text
  OR r.site_id IS DISTINCT FROM (basis->>'siteId')::uuid
  OR r.metering_point_id IS DISTINCT FROM (basis->>'meteringPointId')::uuid
  OR r.operation_id IS DISTINCT FROM p_event_id
  OR r.customer_id IS DISTINCT FROM i.customer_id
  OR r.communication_route_id IS DISTINCT FROM i.communication_route_id THEN RAISE EXCEPTION 'brp_change_owned_intent_request_required';
END IF;

 INSERT INTO gridex_brp_changes.origins(event_id,company_id,intent_id,outbound_request_id,actor_user_id,basis,intent_binding) VALUES(p_event_id,p_company_id,p_intent_id,p_outbound_request_id,p_actor_user_id,basis,jsonb_build_object('sender',i.sender_ediel_id,'receiver',i.receiver_ediel_id,'senderSubaddress',i.sender_subaddress,'receiverSubaddress',i.receiver_subaddress,'interchange',i.interchange_reference,'message',i.message_reference,'transaction',i.transaction_reference,'route',i.communication_route_id,'routeProfile',i.route_profile_id));

 RETURN jsonb_build_object('status','reserved','messageId',NULL,'outboundRequestId',p_outbound_request_id);
END$$;

--
-- Name: ediel_reserve_customer_life_event_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_customer_life_event_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;o gridex_customer_life_events.origins%rowtype;original gridex_customer_life_events.originals%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_life_event_service_required' USING ERRCODE='42501';END IF;
 b:=gridex_customer_life_events.source_v1(p_company_id,p_event_id,p_actor_user_id,'prepare');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO o FROM gridex_customer_life_events.origins WHERE event_id=p_event_id AND company_id=p_company_id;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=coalesce(o.outbound_request_id,p_outbound_request_id) AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR i.environment IS DISTINCT FROM b->>'environment' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z09' OR i.direction IS DISTINCT FROM 'outbound' OR i.communication_route_id IS NULL OR i.route_profile_id IS NULL OR i.operation_id IS DISTINCT FROM p_event_id OR i.validation_status IS DISTINCT FROM 'validated'
  OR i.customer_id::text IS DISTINCT FROM b->>'customerId' OR i.customer_site_id::text IS DISTINCT FROM b->>'siteId' OR i.metering_point_id IS DISTINCT FROM b->>'pointId'
  OR i.interchange_reference IS DISTINCT FROM b->>'interchangeReference' OR i.message_reference IS DISTINCT FROM b->>'messageReference' OR i.transaction_reference IS DISTINCT FROM b->>'transactionReference'
  OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM p_event_id OR r.payload->>'environment' IS DISTINCT FROM b->>'environment' OR r.request_type IS DISTINCT FROM 'customer_masterdata' OR r.customer_id::text IS DISTINCT FROM b->>'customerId' OR r.site_id::text IS DISTINCT FROM b->>'siteId' OR r.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId' THEN RAISE EXCEPTION 'customer_life_event_owned_intent_request_required';END IF;
 IF o.event_id IS NOT NULL AND o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'customer_life_event_original_reservation_conflict';END IF;
 INSERT INTO gridex_customer_life_events.origins(event_id,company_id,intent_id,outbound_request_id,actor_user_id) VALUES(p_event_id,p_company_id,i.id,r.id,p_actor_user_id) ON CONFLICT(event_id) DO NOTHING;
 SELECT * INTO original FROM gridex_customer_life_events.originals WHERE event_id=p_event_id AND company_id=p_company_id;
 RETURN jsonb_build_object('status','reserved','messageId',original.message_id,'outboundRequestId',r.id);
END $$;

--
-- Name: ediel_reserve_metering_method_change_origin_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_metering_method_change_origin_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE basis jsonb;
prior gridex_metering_method_changes.origins%rowtype;
i public.ediel_message_intents%rowtype;
r public.outbound_requests%rowtype;

BEGIN basis:=gridex_metering_method_changes.context_v1(p_company_id,p_event_id,p_actor_user_id);
IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN basis;
END IF;

 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('metering-method-change:'||p_company_id::text||':'||p_event_id::text,0));
SELECT * INTO prior FROM gridex_metering_method_changes.origins WHERE company_id=p_company_id
  AND event_id=p_event_id FOR UPDATE;

 IF FOUND THEN IF prior.intent_id IS DISTINCT FROM p_intent_id
  OR prior.basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'metering_method_change_frozen_origin_conflict';
END IF;
RETURN jsonb_build_object('status','reserved','messageId',prior.message_id,'outboundRequestId',prior.outbound_request_id);
END IF;

 SELECT * INTO i FROM public.ediel_message_intents WHERE company_id=p_company_id
  AND id=p_intent_id FOR SHARE;
SELECT * INTO r FROM public.outbound_requests WHERE company_id=p_company_id
  AND id=p_outbound_request_id FOR SHARE;

 IF i.id IS NULL
  OR r.id IS NULL
  OR i.business_process IS DISTINCT FROM 'customer_masterdata' OR i.market IS DISTINCT FROM 'electricity' OR i.environment IS DISTINCT FROM basis->>'environment'
  OR i.direction IS DISTINCT FROM 'outbound'
  OR i.message_family IS DISTINCT FROM 'PRODAT'
  OR i.message_code IS DISTINCT FROM 'Z09'
  OR i.operation_id IS DISTINCT FROM p_event_id
  OR i.customer_site_id IS DISTINCT FROM (basis->>'siteId')::uuid OR i.customer_id IS DISTINCT FROM (basis->>'customerId')::uuid
  OR i.metering_point_id IS DISTINCT FROM basis->>'pointId'
  OR i.validation_status IS DISTINCT FROM 'validated' OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb
  OR i.application_reference IS DISTINCT FROM '23-DDQ-PRODAT'
  OR r.request_type IS DISTINCT FROM 'customer_masterdata'
  OR r.source_type IS DISTINCT FROM 'manual'
  OR i.communication_route_id IS NULL
  OR i.route_profile_id IS NULL
  OR nullif(i.interchange_reference,'') IS NULL
  OR nullif(i.message_reference,'') IS NULL
  OR nullif(i.transaction_reference,'') IS NULL
  OR r.source_id::text IS DISTINCT FROM i.id::text
  OR r.metering_point_id IS DISTINCT FROM (basis->>'meteringPointId')::uuid
  OR r.operation_id IS DISTINCT FROM p_event_id
  OR r.site_id IS DISTINCT FROM (basis->>'siteId')::uuid
  OR r.payload->>'environment' IS DISTINCT FROM basis->>'environment'
  OR r.customer_id IS DISTINCT FROM i.customer_id
  OR r.communication_route_id IS DISTINCT FROM i.communication_route_id THEN RAISE EXCEPTION 'metering_method_change_owned_intent_request_required';
END IF;

 INSERT INTO gridex_metering_method_changes.origins(event_id,company_id,intent_id,outbound_request_id,actor_user_id,basis,intent_binding) VALUES(p_event_id,p_company_id,p_intent_id,p_outbound_request_id,p_actor_user_id,basis,gridex_metering_method_changes.intent_binding_v1(i));

 RETURN jsonb_build_object('status','reserved','messageId',NULL,'outboundRequestId',p_outbound_request_id);
END$$;

--
-- Name: ediel_reserve_prodat_recovery_origin_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_prodat_recovery_origin_v1(p_company_id uuid, p_operation_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;o gridex_received_sources.prodat_recovery_origins%rowtype;i public.ediel_message_intents%rowtype;m public.ediel_messages%rowtype;r public.outbound_requests%rowtype;basis jsonb;w jsonb;request_type text;
BEGIN
 basis:=public.ediel_prodat_recovery_operation_basis_v1(p_company_id,p_operation_id,p_actor_user_id);
 IF basis IS NULL THEN RAISE EXCEPTION 'prodat_recovery_correction_basis_required';END IF;
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id;
 -- The preceding source qualification already holds the sealed original lock.
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id;
 w:=gridex_received_sources.prodat_recovery_wire_v1(op.corrected_raw_payload);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 request_type:=CASE WHEN w->>'code' IN ('Z03','Z08') THEN 'supplier_switch' WHEN w->>'code' IN ('Z13','Z18') THEN 'metering_access' ELSE 'customer_masterdata' END;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM op.environment OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM w->>'code'
 OR i.direction IS DISTINCT FROM 'outbound' OR i.customer_id IS DISTINCT FROM m.customer_id OR i.operation_id IS DISTINCT FROM op.id
 OR i.validation_status IS DISTINCT FROM 'validated' OR i.interchange_reference IS DISTINCT FROM w->>'interchange' OR i.message_reference IS DISTINCT FROM w->>'messageReference'
 OR i.sender_ediel_id IS DISTINCT FROM w#>>'{transportSender,0}' OR i.receiver_ediel_id IS DISTINCT FROM w#>>'{transportReceiver,0}'
 OR i.communication_route_id IS NULL OR i.route_profile_id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_intent_scope_required';END IF;
 SELECT * INTO o FROM gridex_received_sources.prodat_recovery_origins WHERE operation_id=op.id FOR UPDATE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=coalesce(o.outbound_request_id,p_outbound_request_id) FOR SHARE;
 IF r.id IS NULL OR r.company_id IS DISTINCT FROM p_company_id OR r.customer_id IS DISTINCT FROM m.customer_id OR (r.payload->>'environment') IS DISTINCT FROM op.environment OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.operation_id IS DISTINCT FROM op.id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id OR r.request_type IS DISTINCT FROM request_type THEN RAISE EXCEPTION 'prodat_recovery_owned_request_required';END IF;
 IF o.operation_id IS NOT NULL THEN
  IF o.company_id IS DISTINCT FROM p_company_id OR o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'prodat_recovery_origin_conflict';END IF;
  RETURN jsonb_build_object('status','reserved','intentId',o.intent_id,'outboundRequestId',o.outbound_request_id,'messageId',(SELECT message_id FROM gridex_received_sources.prodat_recovery_messages WHERE operation_id=op.id));
 END IF;
 IF EXISTS(SELECT FROM gridex_received_sources.prodat_recovery_messages WHERE operation_id=op.id) THEN RAISE EXCEPTION 'prodat_recovery_legacy_bound_origin_held';END IF;
 INSERT INTO gridex_received_sources.prodat_recovery_origins(operation_id,company_id,intent_id,outbound_request_id,actor_user_id) VALUES(op.id,p_company_id,i.id,p_outbound_request_id,p_actor_user_id);
 RETURN jsonb_build_object('status','reserved','intentId',i.id,'outboundRequestId',p_outbound_request_id,'messageId',null);
END $$;

--
-- Name: ediel_reserve_production_contract_origin_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_production_contract_origin_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;e gridex_received_sources.production_contract_events%rowtype;o gridex_received_sources.production_contract_origins%rowtype;i public.ediel_message_intents%rowtype;period gridex_received_sources.production_contract_periods%rowtype;r public.outbound_requests%rowtype;point public.metering_points%rowtype;
BEGIN
 PERFORM gridex_contract_source_intake.lock_target_contract_v1(p_company_id,'production_contract_event',p_event_id); SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;
 PERFORM mp.id FROM public.metering_points mp WHERE mp.id=e.metering_point_id AND mp.company_id=e.company_id FOR UPDATE;
 b:=public.ediel_production_contract_source_v1(p_company_id,p_event_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM e.environment OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z09' OR i.customer_id IS DISTINCT FROM e.customer_id OR i.metering_point_id IS DISTINCT FROM e.point_id OR i.operation_id IS DISTINCT FROM e.id
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_intent_scope_mismatch'));END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE event_id=e.id FOR UPDATE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=coalesce(o.outbound_request_id,p_outbound_request_id) AND company_id=e.company_id FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=e.metering_point_id AND company_id=e.company_id FOR SHARE;
 IF r.id IS NULL OR point.id IS NULL OR r.customer_id IS DISTINCT FROM e.customer_id OR r.site_id IS DISTINCT FROM point.site_id OR r.metering_point_id IS DISTINCT FROM e.metering_point_id OR (r.payload->>'environment') IS DISTINCT FROM e.environment
 OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata' THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_request_required'));END IF;
 IF o.event_id IS NOT NULL THEN IF o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'production_contract_origin_conflict';END IF;RETURN jsonb_build_object('status','reserved','messageId',o.message_id,'outboundRequestId',o.outbound_request_id);END IF;
 IF e.event_kind='signed' THEN
 IF EXISTS(SELECT FROM gridex_received_sources.production_contract_periods p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.metering_point_id=e.metering_point_id AND (p.end_at IS NULL OR p.end_at>e.boundary_at)) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_overlapping_owned_period'));END IF;
 INSERT INTO gridex_received_sources.production_contract_periods(start_event_id,company_id,environment,contract_id,customer_id,metering_point_id,start_at) VALUES(e.id,e.company_id,e.environment,e.contract_id,e.customer_id,e.metering_point_id,e.boundary_at);
 ELSE
 SELECT * INTO period FROM gridex_received_sources.production_contract_periods WHERE start_event_id=e.start_event_id AND company_id=e.company_id FOR UPDATE;
 IF NOT FOUND OR period.end_event_id IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_open_period_required'));END IF;
 UPDATE gridex_received_sources.production_contract_periods SET end_at=e.boundary_at,end_event_id=e.id WHERE start_event_id=period.start_event_id;
 END IF;
 INSERT INTO gridex_received_sources.production_contract_origins(event_id,intent_id,company_id,actor_user_id,outbound_request_id) VALUES(e.id,i.id,e.company_id,p_actor_user_id,p_outbound_request_id);
 RETURN jsonb_build_object('status','reserved','messageId',null,'outboundRequestId',p_outbound_request_id);
END $$;

--
-- Name: ediel_reserve_service_permission_origin_v1(uuid, uuid, uuid, bigint, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_service_permission_origin_v1(p_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_code text, p_permission_id uuid, p_intent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'ediel_permission_origin_service_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_service_permission.reserve_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,p_code,p_permission_id,p_intent_id);
END $$;

--
-- Name: ediel_reserve_switch_cancellation_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_switch_cancellation_v1(p_company_id uuid, p_switch_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;o gridex_switch_cancellations.origins%rowtype;binding jsonb;
BEGIN
 b:=gridex_switch_cancellations.context_v1(p_company_id,p_switch_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=p_outbound_request_id AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR i.environment IS DISTINCT FROM b->>'environment' OR i.direction IS DISTINCT FROM 'outbound' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z03'
  OR i.business_process IS DISTINCT FROM 'supplier_switch' OR i.customer_id::text IS DISTINCT FROM b->>'customerId' OR i.metering_point_id IS DISTINCT FROM b->>'pointId' OR i.grid_area_code IS DISTINCT FROM b->>'gridArea'
  OR i.operation_id IS NULL OR i.validation_status IS DISTINCT FROM 'validated' OR i.transaction_reference IS DISTINCT FROM b->>'li'
  OR r.payload->>'environment' IS DISTINCT FROM b->>'environment' OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.request_type IS DISTINCT FROM 'supplier_switch'
  OR r.operation_id IS DISTINCT FROM i.operation_id OR r.customer_id::text IS DISTINCT FROM b->>'customerId' OR r.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId' OR r.site_id::text IS DISTINCT FROM b->>'siteId'
 THEN RAISE EXCEPTION 'switch_cancellation_validated_intent_request_required';END IF;
 binding:=to_jsonb(i)-ARRAY['created_at','updated_at','validation_status','validation_report','render_status','outbox_status','ack_status','ediel_message_id','outbound_request_id'];
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=p_company_id AND switch_id=p_switch_id AND original_message_id=(b->>'originalMessageId')::uuid FOR UPDATE;
 IF FOUND THEN IF o.intent_id IS DISTINCT FROM i.id OR o.outbound_request_id IS DISTINCT FROM r.id OR o.intent_binding IS DISTINCT FROM binding OR o.original_hash IS DISTINCT FROM b->>'originalHash' THEN RAISE EXCEPTION 'switch_cancellation_reservation_conflict';END IF;
 ELSE INSERT INTO gridex_switch_cancellations.origins(id,company_id,switch_id,original_message_id,original_hash,intent_id,outbound_request_id,actor_user_id,basis,intent_binding)
 VALUES(i.operation_id::uuid,p_company_id,p_switch_id,(b->>'originalMessageId')::uuid,b->>'originalHash',i.id,r.id,p_actor_user_id,b-ARRAY['operationId','intentId','outboundRequestId','messageId'],binding) RETURNING * INTO o;END IF;
 RETURN jsonb_build_object('status','reserved','operationId',o.id,'intentId',o.intent_id,'outboundRequestId',o.outbound_request_id,'messageId',o.message_id);
END $$;

--
-- Name: ediel_reserve_wire_reference_namespace_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_wire_reference_namespace_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'outbound' OR nullif(m.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 PERFORM gridex_ediel_wire_namespace.reserve(m);
END $$;

--
-- Name: ediel_resolve_service_permission_command_v1(uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_resolve_service_permission_command_v1(p_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_permission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$DECLARE timing jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 IF p_assignment_id IS NULL OR p_permission_id IS NULL OR p_expected_version IS NULL OR p_expected_version<1 THEN RAISE EXCEPTION 'ediel_service_permission_command_scope_required';END IF;
 PERFORM gridex_service_permission.lock_request_writer_v1();
 timing:=gridex_service_permission.current_request_timing_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,false);
 IF timing->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','permissionId',NULL,'missing',timing->'missing');END IF;
 -- A recorded immutable request binds this assignment scope to one permission.
 IF timing->>'permissionId' IS NOT NULL AND timing->>'permissionId' IS DISTINCT FROM p_permission_id::text THEN
  RETURN jsonb_build_object('status','held','permissionId',NULL,'missing',ARRAY['immutable_service_request_permission_mismatch']);
 END IF;
 RETURN gridex_service_permission.resolve_before_request_timing_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,p_permission_id);
END $$;

--
-- Name: ediel_retention_lock_auth_actor_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_retention_lock_auth_actor_v1(p_actor_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE active boolean;
BEGIN
 -- The same FOR SHARE lock as the installed actor/reviewer owners prevents a
 -- concurrent deletion/ban from passing a prior unlocked authorization check.
 SELECT deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now())
 INTO active FROM auth.users WHERE id=p_actor_user_id FOR SHARE;
 IF active IS DISTINCT FROM true THEN RETURN false;END IF;
 PERFORM id FROM public.user_profiles WHERE id=p_actor_user_id FOR SHARE;
 RETURN EXISTS(SELECT FROM public.user_profiles p WHERE p.id=p_actor_user_id
               AND p.user_status='active' AND to_jsonb(p)->>'disabled_at' IS NULL);
END$$;

