--

CREATE FUNCTION public.ediel_review_invoice_file_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.invoice_file_decisions%rowtype;basis jsonb;p jsonb;r uuid;outcome text;BEGIN SELECT * INTO STRICT d FROM gridex_ediel_retention.invoice_file_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;PERFORM gridex_ediel_retention.invoice_file_actor_v1(p_company_id,p_actor_user_id,'ediel.retention.review');IF p_outcome NOT IN('approve','hold','reject') OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>4000 THEN RAISE EXCEPTION 'invoice_file_review_shape_required';END IF;IF p_outcome='approve' AND d.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'invoice_file_separate_reviewer_required';END IF;
 basis:=gridex_ediel_retention.invoice_file_basis_v1(p_company_id,d.retention_class,d.target_id);p:=gridex_ediel_retention.invoice_file_receipt_v1(d);outcome:=CASE WHEN p_outcome='reject' THEN 'rejected' WHEN p_outcome='approve' AND p IS NOT NULL AND basis->>'allIncludedScopesClosed'='true' AND basis->>'targetHash'=d.target_hash AND basis->>'scopeHash'=d.scope_hash AND p->>'periodStart'=basis->>'periodStart' AND p->>'periodEnd'=basis->>'periodEnd' THEN 'approved' ELSE 'held' END;
 INSERT INTO gridex_ediel_retention.invoice_file_reviews(decision_id,actor_user_id,outcome,reason) VALUES(d.id,p_actor_user_id,outcome,p_reason) RETURNING id INTO r;RETURN jsonb_build_object('status',outcome,'decisionId',d.id,'reviewId',r);END$$;

--
-- Name: ediel_review_network_registry_source_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
