CREATE FUNCTION public.ediel_review_network_registry_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_network_registry_sources.artifacts%rowtype;r gridex_network_registry_sources.reviews%rowtype;o gridex_network_registry_sources.origins%rowtype;prior gridex_network_registry_sources.origins%rowtype;actual jsonb;receipt jsonb;missing jsonb:='[]';result text;version_id uuid;n int;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'network_registry_service_required' USING ERRCODE='42501';END IF;
 IF gridex_network_registry_sources.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'network_registry_review_actor_forbidden' USING ERRCODE='42501';END IF;
 -- Same central authorization prefix, then stable decision/journal table fence.
 LOCK TABLE gridex_network_registry_sources.origins,gridex_network_registry_sources.reviews IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO a FROM gridex_network_registry_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR NOT(p_review ?& ARRAY['sourceHash','claimsHash','decision','reason']) OR EXISTS(SELECT FROM jsonb_object_keys(p_review) x WHERE x NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR length(coalesce(p_review->>'reason','')) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'network_registry_actual_archived_candidate_required';END IF;
 IF a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'network_registry_separate_reviewer_required' USING ERRCODE='42501';END IF;
 actual:=gridex_network_registry_sources.claims_v1(a.company_id,a.claims);receipt:=gridex_network_registry_sources.receipt_current_v1(a);
 IF actual IS DISTINCT FROM a.claims OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash THEN missing:=missing||'"current_exact_archived_claims_required"'::jsonb;END IF;
 IF receipt IS NULL THEN missing:=missing||'"authentic_current_network_registry_issuer_and_representation"'::jsonb;END IF;
 IF p_review->>'decision'='approve' AND (jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR p_review->'clause' IS DISTINCT FROM receipt->'clause') THEN missing:=missing||'"exact_signed_original_legal_clause_required"'::jsonb;END IF;
 SELECT * INTO o FROM gridex_network_registry_sources.origins WHERE artifact_id=a.id;
 IF FOUND THEN IF gridex_network_registry_sources.current_v1(a) IS NULL THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'missing','["current_network_registry_authority_revoked_or_superseded"]'::jsonb);END IF;RETURN jsonb_build_object('status','authorized','artifactId',a.id,'registryVersionId',o.id);END IF;
 result:=CASE WHEN p_review->>'decision'='reject' THEN 'rejected' WHEN p_review->>'decision'='hold' OR jsonb_array_length(missing)>0 THEN 'held' ELSE 'approved' END;
 INSERT INTO gridex_network_registry_sources.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,result,p_review->>'reason',p_review->'clause',missing) RETURNING * INTO r;
 IF result<>'approved' THEN RETURN jsonb_build_object('status',result,'artifactId',a.id,'missing',missing);END IF;
 SELECT count(*) INTO n FROM gridex_network_registry_sources.origins version WHERE company_id=a.company_id AND environment=a.environment AND network_actor_id=a.network_actor_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id);
 IF n>1 THEN RAISE EXCEPTION 'network_registry_previous_version_ambiguous';END IF;
 SELECT * INTO prior FROM gridex_network_registry_sources.origins version WHERE company_id=a.company_id AND environment=a.environment AND network_actor_id=a.network_actor_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id) FOR SHARE;
 INSERT INTO gridex_network_registry_sources.origins(artifact_id,review_id,company_id,environment,network_actor_id,registry_version,previous_version_id) VALUES(a.id,r.id,a.company_id,a.environment,a.network_actor_id,a.source_version,prior.id) RETURNING id INTO version_id;
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'registryVersionId',version_id);
END$$;

--
-- Name: ediel_review_periodic_e66_reason_v1(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_periodic_e66_reason_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_evidence_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE artifact gridex_ediel_services.artifacts%rowtype;e public.ediel_service_evidence%rowtype;generic gridex_ediel_services.reviews%rowtype;
 claims jsonb;v gridex_ediel_services.periodic_reason_reviews%rowtype;seq bigint;decision text;
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1(true);
 IF gridex_ediel_services.actor_current_v1(p_company_id,p_actor_user_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_periodic_reason_reviewer_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('decision','reason','sourceHash','scopeHash'))
 OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR nullif(btrim(p_review->>'reason'),'') IS NULL OR length(p_review->>'reason')>2000 THEN RAISE EXCEPTION 'ediel_periodic_reason_review_shape_invalid';END IF;
 SELECT * INTO artifact FROM gridex_ediel_services.artifacts WHERE company_id=p_company_id AND id=p_artifact_id;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=p_company_id AND id=p_evidence_id FOR SHARE;
 SELECT * INTO generic FROM gridex_ediel_services.reviews WHERE company_id=p_company_id AND artifact_id=p_artifact_id AND evidence_id=p_evidence_id ORDER BY review_sequence DESC LIMIT 1;
 IF artifact.id IS NULL OR e.id IS NULL OR generic.id IS NULL OR artifact.submitted_by=p_actor_user_id OR generic.decision<>'approved' OR generic.id IS DISTINCT FROM (SELECT r.id FROM gridex_ediel_services.reviews r WHERE r.company_id=p_company_id AND r.evidence_id=p_evidence_id ORDER BY r.review_sequence DESC LIMIT 1)
 OR generic.artifact_id IS DISTINCT FROM artifact.id OR generic.scope_basis_version IS DISTINCT FROM artifact.scope_basis_version
 OR gridex_ediel_services.review_current_v1(e) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_periodic_reason_separate_current_review_required';END IF;
 IF artifact.source_hash IS DISTINCT FROM p_review->>'sourceHash' OR artifact.scope_hash IS DISTINCT FROM p_review->>'scopeHash' THEN RAISE EXCEPTION 'ediel_periodic_reason_review_original_hash_required';END IF;
 claims:=gridex_ediel_services.signed_periodic_reason_claims_v1(artifact);
 IF claims IS NULL THEN RAISE EXCEPTION 'ediel_periodic_reason_signed_bilateral_claim_required';END IF;
 SELECT coalesce(max(review_sequence),0)+1 INTO seq FROM gridex_ediel_services.periodic_reason_reviews WHERE company_id=p_company_id AND evidence_id=p_evidence_id;
 decision:=CASE p_review->>'decision' WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'held' END;
 INSERT INTO gridex_ediel_services.periodic_reason_reviews(company_id,artifact_id,evidence_id,generic_review_id,scope_basis_version,claims,claims_hash,reviewer_user_id,review_sequence,decision,reason)
 VALUES(p_company_id,artifact.id,e.id,generic.id,artifact.scope_basis_version,claims,encode(sha256(convert_to(claims::text,'UTF8')),'hex'),p_actor_user_id,seq,decision,p_review->>'reason') RETURNING * INTO v;
 RETURN jsonb_build_object('version',1,'reviewId',v.id,'companyId',v.company_id,'artifactId',v.artifact_id,'evidenceId',v.evidence_id,'reviewSequence',v.review_sequence,'status',v.decision,'claimsHash',v.claims_hash,'reasonCode',claims->>'reasonCode','marketActivationGranted',false);
END $$;

--
-- Name: ediel_review_process_journal_retention_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_process_journal_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.process_decisions%rowtype;basis jsonb;outcome text;r uuid;BEGIN
 PERFORM gridex_ediel_retention.record_actor_v1(p_company_id,p_actor_user_id,'legal_acceptance_personal_snapshot','ediel.retention.review');SELECT * INTO STRICT d FROM gridex_ediel_retention.process_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;
 IF p_outcome NOT IN('approve','hold','reject') OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>4000 THEN RAISE EXCEPTION 'process_retention_review_shape_required';END IF;IF p_outcome='approve' AND d.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'process_retention_separate_reviewer_required';END IF;
 basis:=gridex_ediel_retention.process_basis_v1(p_company_id,d.retention_class,d.target_id);outcome:=CASE WHEN p_outcome='reject' THEN 'rejected' WHEN p_outcome='approve' AND gridex_ediel_retention.process_receipt_v1(d) IS NOT NULL AND basis->>'sourceHash'=d.source_hash AND basis->>'targetHash'=d.target_hash AND basis->>'scopeHash'=d.scope_hash AND basis->>'allIncludedScopesClosed'='true' THEN 'approved' ELSE 'held' END;
 INSERT INTO gridex_ediel_retention.process_reviews(decision_id,actor_user_id,outcome,reason) VALUES(d.id,p_actor_user_id,outcome,p_reason) RETURNING id INTO r;INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'process_journal_retention',d.id,'ediel.retention.process_reviewed',jsonb_build_object('reviewId',r,'outcome',outcome));RETURN jsonb_build_object('status',outcome,'decisionId',d.id,'reviewId',r);END$$;

--
-- Name: ediel_review_regulated_supply_ground_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_regulated_supply_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_regulated_supply.artifacts%rowtype;o gridex_regulated_supply.origins%rowtype;g gridex_received_sources.regulated_supply_ground_versions%rowtype;scope jsonb;decision text;missing jsonb:='[]';rid uuid;receipt jsonb;
BEGIN
 IF gridex_regulated_supply.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'regulated_supply_review_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_regulated_supply.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 decision:=p_review->>'decision';IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('sourceHash','scopeHash','decision','reason')) OR (decision IN('approve','hold','reject')) IS NOT TRUE OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'scopeHash' IS DISTINCT FROM a.scope_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'regulated_supply_review_exact_archived_candidate_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'regulated_supply_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_regulated_supply.origins WHERE artifact_id=a.id AND company_id=a.company_id;
 IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'regulated_supply_authorized_ground_requires_revocation';END IF;
 IF gridex_regulated_supply.ground_current_v1(o.ground_id,a.company_id,(a.scope->>'meteringPointId')::uuid,(a.scope->>'startAt')::timestamptz) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','companyId',p_company_id,'artifactId',a.id,'missing',ARRAY['actual_current_qualified_ground']);END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'artifactId',a.id,'groundId',o.ground_id,'missing','[]'::jsonb);END IF;
 IF decision='hold' THEN missing:='["explicit_source_review_hold"]';ELSIF decision='reject' THEN missing:='["explicit_source_review_rejection"]';
 ELSE scope:=gridex_regulated_supply.scope_v1(p_company_id,a.selector);
 IF scope IS NULL OR scope IS DISTINCT FROM a.scope THEN missing:='["actual_current_immutable_contract_point_legal_registry_scope"]';
 ELSIF gridex_regulated_supply.receipt_current_v1(a) IS NOT TRUE THEN missing:='["authentic_current_issuer_representation_and_legal_ground_receipt"]';END IF;END IF;
 IF missing<>'[]'::jsonb THEN INSERT INTO gridex_regulated_supply.reviews(company_id,artifact_id,reviewer_user_id,decision,reason,missing) VALUES(p_company_id,a.id,p_actor_user_id,CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',missing);
 RETURN jsonb_build_object('status',CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,'companyId',p_company_id,'artifactId',a.id,'missing',missing);END IF;
 receipt:=convert_from(decode(a.issuer_receipt->>'payloadBase64','base64'),'UTF8')::jsonb;
 INSERT INTO gridex_regulated_supply.reviews(company_id,artifact_id,reviewer_user_id,decision,reason,missing) VALUES(p_company_id,a.id,p_actor_user_id,'approved',p_review->>'reason','[]') RETURNING id INTO rid;
 INSERT INTO gridex_received_sources.regulated_supply_ground_versions(company_id,environment,legal_actor_id,dso_actor_id,grid_area_code,process,bilateral_agreement_id,consumption_supply_period_id,source_reference,source_sha256,legal_decision_reference,registry_version,approved_by,approved_at,valid_from,valid_to)
 VALUES(p_company_id,a.environment,(a.scope->>'legalActorId')::uuid,(a.scope->>'dsoActorId')::uuid,a.scope->>'gridArea',a.scope->>'kind',(a.scope->>'bilateralAgreementId')::uuid,(a.scope->>'consumptionSupplyPeriodId')::uuid,a.source_reference,a.source_hash,receipt->>'legalDecisionReference',a.source_version||':'||a.scope_hash,p_actor_user_id,(SELECT reviewed_at FROM gridex_regulated_supply.reviews WHERE id=rid),(a.scope->>'startAt')::timestamptz,least((a.scope#>>'{agreementBinding,valid_to}')::timestamptz,(receipt->>'expiresAt')::timestamptz)) RETURNING * INTO g;
 INSERT INTO gridex_regulated_supply.origins(ground_id,company_id,artifact_id,review_id,ground_binding) VALUES(g.id,p_company_id,a.id,rid,to_jsonb(g)-'revoked_at');
 IF gridex_regulated_supply.ground_current_v1(g.id,p_company_id,(a.scope->>'meteringPointId')::uuid,(a.scope->>'startAt')::timestamptz) IS NOT TRUE THEN RAISE EXCEPTION 'regulated_supply_postwrite_actual_ground_unqualified';END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'artifactId',a.id,'groundId',g.id,'missing','[]'::jsonb);
END$$;

--
-- Name: ediel_review_requested_change_artifact_before_scope_fence_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_requested_change_artifact_before_scope_fence_v1(p_company_id uuid, p_artifact_id uuid, p_actor_user_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_changes.artifacts%rowtype;c public.customer_contracts%rowtype;d public.customer_contract_documents%rowtype;o gridex_requested_changes.review_origins%rowtype;e gridex_requested_changes.events%rowtype;review_id uuid;missing jsonb:='[]';b jsonb;decision text;sig text;
BEGIN SELECT * INTO STRICT a FROM gridex_requested_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'review',a.kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_review_actor_forbidden' USING ERRCODE='42501';END IF;
 IF a.source_bytes IS NULL THEN RAISE EXCEPTION 'requested_change_artifact_bytes_retained_as_tombstone';END IF;
 decision:=p_review->>'decision';IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR decision NOT IN('approve','hold','reject') OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'requested_change_review_actual_archived_candidate_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'requested_change_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE artifact_id=a.id FOR SHARE;
 IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'requested_change_authorized_origin_requires_revocation';END IF;b:=gridex_requested_changes.context_v1(p_company_id,o.event_id,p_actor_user_id,'communication.write');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',b->'missing');END IF;RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',o.event_id);END IF;
 IF decision='hold' THEN missing:='["explicit_source_review_hold"]';ELSIF decision='reject' THEN missing:='["explicit_source_review_rejection"]';
 ELSIF a.kind='death' THEN IF gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN missing:='["authentic_current_issuer_and_representation_receipt"]';END IF;
 ELSE
  SELECT * INTO c FROM public.customer_contracts WHERE id=a.contract_id AND company_id=a.company_id FOR SHARE;
  sig:=encode(sha256(convert_to(c.signature_snapshot::text,'UTF8')),'hex');SELECT * INTO d FROM public.customer_contract_documents WHERE company_id=a.company_id AND customer_contract_id=c.id AND document_type='signed_contract_pdf' AND document_sha256=a.source_hash AND verified_at IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
  IF c.id IS NULL OR d.id IS NULL OR a.mime_type<>'application/pdf' OR c.document_sha256 IS DISTINCT FROM a.source_hash OR c.signed_at IS NULL OR c.signed_version IS DISTINCT FROM c.contract_version OR c.signature_snapshot_sha256 IS DISTINCT FROM sig OR c.signature_snapshot->>'company_id' IS DISTINCT FROM a.company_id::text OR c.signature_snapshot->>'customer_id' IS DISTINCT FROM a.customer_id::text OR c.signature_snapshot->>'contract_id' IS DISTINCT FROM c.id::text OR jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review->'clause') k WHERE k NOT IN('locator','quote')) OR nullif(p_review#>>'{clause,locator}','') IS NULL OR length(p_review#>>'{clause,locator}')>1000 OR nullif(p_review#>>'{clause,quote}','') IS NULL OR length(p_review#>>'{clause,quote}')>10000 THEN missing:='["actual_own_signed_contract_pdf_signature_and_verbatim_metering_clause"]';END IF;
 END IF;
 IF missing<>'[]'::jsonb THEN INSERT INTO gridex_requested_changes.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',p_review->'clause',missing);RETURN jsonb_build_object('status',CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,'artifactId',a.id,'missing',missing);END IF;
 INSERT INTO gridex_requested_changes.events(company_id,environment,supply_period_id,supply_source_message_id,supply_state_version,contract_id,protected_contract_hash,customer_id,metering_point_id,customer_snapshot_hash,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,brp_ediel_id,variant,event_kind,effective_at,customer_identity,invoicee_profile,source_reference,source_sha256,source_version,approved_by,approved_at)
 VALUES(a.company_id,a.environment,a.supply_period_id,a.supply_source_message_id,a.supply_state_version,a.contract_id,a.protected_contract_hash,a.customer_id,a.metering_point_id,a.customer_snapshot_hash,a.legal_actor_id,a.legal_sender_id,a.legal_receiver_id,a.point_id,a.identity_agency,a.grid_area_code,a.brp_ediel_id,CASE a.kind WHEN 'death' THEN 'E' WHEN 'quarter_contract' THEN 'F' ELSE 'G' END,a.kind,a.effective_at,a.claims->'customerIdentity',a.claims->'invoiceeProfile',a.source_reference,a.source_hash,a.source_version,p_actor_user_id,now()) RETURNING * INTO e;
 b:=gridex_requested_changes.context_before_intake_v1(a.company_id,e.id,p_actor_user_id,'communication.write');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'requested_change_review_current_owned_source_required';END IF;
 INSERT INTO gridex_requested_changes.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause) VALUES(a.id,a.company_id,p_actor_user_id,'approved',p_review->>'reason',p_review->'clause') RETURNING id INTO review_id;
 INSERT INTO gridex_requested_changes.review_origins(event_id,artifact_id,review_id,company_id,contract_document_id,contract_document_binding,signature_hash) VALUES(e.id,a.id,review_id,a.company_id,d.id,CASE WHEN d.id IS NULL THEN NULL ELSE to_jsonb(d) END,sig);
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',e.id);
END$$;

--
-- Name: ediel_review_requested_change_artifact_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_requested_change_artifact_v1(p_company_id uuid, p_artifact_id uuid, p_actor_user_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();RETURN public.ediel_review_requested_change_artifact_before_scope_fence_v1(p_company_id,p_artifact_id,p_actor_user_id,p_review);END$$;

--
-- Name: ediel_review_requested_customer_change_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_requested_customer_change_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_customer_changes.artifacts%rowtype;r gridex_requested_customer_changes.reviews%rowtype;o gridex_requested_customer_changes.origins%rowtype;actual jsonb;receipt jsonb;decision text;missing jsonb:='[]';event uuid;fields text[];current_source jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'requested_customer_change_service_required' USING ERRCODE='42501';END IF;
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_review_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_requested_customer_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 actual:=gridex_requested_customer_changes.source_claims_v1(a.company_id,a.environment,a.agreement_id,a.supply_period_id,a.contract_id,a.raw_payload);
 SELECT * INTO STRICT a FROM gridex_requested_customer_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;decision:=p_review->>'decision';
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review)k WHERE k NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR(decision IN('approve','hold','reject')) IS NOT TRUE OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'requested_customer_change_actual_archive_review_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'requested_customer_change_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_requested_customer_changes.origins WHERE artifact_id=a.id FOR SHARE;
 IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'requested_customer_change_current_origin_requires_revocation';END IF;current_source:=gridex_requested_customer_changes.current_v1(a.id,p_company_id);RETURN coalesce(current_source,jsonb_build_object('status','held','artifactId',a.id,'missing',ARRAY['current_outgoing_customer_mandate_unavailable']));END IF;
 IF decision='hold' THEN missing:='["explicit_requested_customer_change_hold"]';ELSIF decision='reject' THEN missing:='["explicit_requested_customer_change_rejection"]';ELSE
  receipt:=gridex_requested_customer_changes.receipt_current_v1(a);
  IF actual IS DISTINCT FROM a.claims OR a.claims->>'supplyQualified' IS DISTINCT FROM 'true' THEN missing:='["current_owned_supply_source_required"]';ELSIF receipt IS NULL THEN missing:='["authentic_current_outgoing_customer_mandate"]';
  ELSIF jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review->'clause')k WHERE k NOT IN('locator','quote')) OR nullif(p_review#>>'{clause,locator}','') IS NULL OR length(p_review#>>'{clause,locator}')>1000 OR nullif(p_review#>>'{clause,quote}','') IS NULL OR length(p_review#>>'{clause,quote}')>10000 OR receipt->'clause' IS DISTINCT FROM p_review->'clause' OR position(convert_to(p_review#>>'{clause,quote}','UTF8') IN a.source_bytes)=0 THEN missing:='["actual_original_pdf_verbatim_outgoing_customer_clause"]';END IF;
 END IF;
 IF gridex_requested_customer_changes.actor_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'requested_customer_change_post_wait_reviewer_forbidden' USING ERRCODE='42501';END IF;
 IF missing='[]'::jsonb AND (gridex_requested_customer_changes.source_claims_v1(a.company_id,a.environment,a.agreement_id,a.supply_period_id,a.contract_id,a.raw_payload) IS DISTINCT FROM a.claims OR gridex_requested_customer_changes.receipt_current_v1(a) IS NULL) THEN missing:='["current_outgoing_customer_mandate_unavailable"]';END IF;
 INSERT INTO gridex_requested_customer_changes.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing)VALUES(a.id,p_company_id,p_actor_user_id,CASE WHEN missing='[]'::jsonb THEN 'approved' WHEN decision='reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',p_review->'clause',missing)RETURNING * INTO r;
 IF missing<>'[]'::jsonb THEN RETURN jsonb_build_object('status',CASE WHEN decision='reject' THEN 'rejected' ELSE 'held' END,'artifactId',a.id,'missing',missing);END IF;
 SELECT array_agg(f ORDER BY f) INTO fields FROM jsonb_array_elements_text(receipt->'authorizedFields')f WHERE f IN('227','228','229','231','232','316');event:=gen_random_uuid();
 INSERT INTO gridex_customer_life_events.events(id,company_id,environment,customer_id,classification,legal_actor_id,legal_sender_id,legal_receiver_id,source_reference,source_version,source_sha256,legal_decision_reference,bilateral_agreement_id,bilateral_capability_code,bilateral_source_reference,bilateral_terms_sha256,approved_raw_payload,approved_payload_hash,approved_scope,allowed_customer_fields,information_known_at,approved_by,approved_at)
 VALUES(event,a.company_id,a.environment,(a.claims->>'customerId')::uuid,'other_masterdata',(a.claims->>'legalActorId')::uuid,a.claims->>'legalSender',a.claims->>'legalReceiver',a.source_reference,a.source_version,a.source_hash,r.id::text,a.agreement_id,'prodat_z09e_requested_customer_change',a.claims->>'agreementReference',a.claims->>'agreementTermsHash',a.raw_payload,a.claims->>'payloadHash',a.claims->'scope',fields,a.created_at,p_actor_user_id,clock_timestamp());
 INSERT INTO gridex_requested_customer_changes.origins(artifact_id,review_id,event_id,company_id)VALUES(a.id,r.id,event,a.company_id);
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',event);END$$;

