--
-- Name: ediel_revoke_network_registry_source_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_revoke_network_registry_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_network_registry_sources.artifacts%rowtype;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'network_registry_service_required' USING ERRCODE='42501';END IF;
 IF gridex_network_registry_sources.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'network_registry_review_actor_forbidden' USING ERRCODE='42501';END IF;
 LOCK TABLE gridex_network_registry_sources.artifacts,gridex_network_registry_sources.reviews,gridex_network_registry_sources.origins,gridex_network_registry_sources.issuer_keys,gridex_network_registry_sources.representations,gridex_network_registry_sources.revocations IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO a FROM gridex_network_registry_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF a.id IS NULL OR jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_review))<>3 OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR length(coalesce(p_review->>'reason','')) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'network_registry_actual_revocation_candidate_required';END IF;
 INSERT INTO gridex_network_registry_sources.revocations(target_kind,target_id,source_reference,source_hash) VALUES('artifact',a.id,p_review->>'reason',a.source_hash) ON CONFLICT(target_kind,target_id) DO NOTHING;
 RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',ARRAY['network_registry_source_withdrawn']);
END$$;

--
-- Name: ediel_revoke_process_journal_retention_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_revoke_process_journal_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_retention.record_actor_v1(p_company_id,p_actor_user_id,'legal_acceptance_personal_snapshot','ediel.retention.review');PERFORM id FROM gridex_ediel_retention.process_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;IF NOT FOUND OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>4000 THEN RAISE EXCEPTION 'process_retention_revoke_scope_required';END IF;
 INSERT INTO gridex_ediel_retention.process_revocations(decision_id,actor_user_id,reason) VALUES(p_decision_id,p_actor_user_id,p_reason) ON CONFLICT DO NOTHING;END$$;

--
-- Name: ediel_revoke_signed_brp_declaration_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_revoke_signed_brp_declaration_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE terminal_result jsonb;terminal_kind text;
BEGIN
 terminal_result:=gridex_brp_declaration_intake.terminal_revoke_body_v1(p_company_id,p_actor_user_id,p_artifact_id,p_reason);
 IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'revoke') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_terminal_actor_revoked' USING ERRCODE='42501';END IF;
 RETURN terminal_result;
END$$;

--
-- Name: ediel_revoke_transport_exception_v1(uuid, uuid, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_revoke_transport_exception_v1(p_exception_id uuid, p_actor_user_id uuid, p_original bytea) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF current_user<>'gridex_ediel_transport_exception_owner' THEN RAISE EXCEPTION 'transport_exception_qualified_source_owner_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_transport_exception.revoke_v1(p_exception_id,p_actor_user_id,p_original,current_user);END$$;

--
-- Name: ediel_scoped_capability_readiness_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_scoped_capability_readiness_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'gridex_ediel_readiness'
    AS $$
DECLARE current_evidence jsonb; proof gridex_ediel_readiness.evidence%rowtype;
BEGIN
 current_evidence:=gridex_ediel_readiness.capture(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 SELECT * INTO proof FROM gridex_ediel_readiness.evidence WHERE company_id=p_company_id AND scope=current_evidence->'scope' AND dependency_hash=current_evidence->>'dependencyHash' AND expires_at>clock_timestamp() ORDER BY verified_at DESC,id LIMIT 1;
 -- Evidence revocation/expiry is re-read, not cached in the immutable proof.
 IF FOUND AND NOT EXISTS(SELECT FROM jsonb_array_elements(proof.certification_records) old LEFT JOIN public.ediel_certification_evidence live ON live.id=(old->>'id')::uuid AND live.company_id=p_company_id
    WHERE live.id IS NULL OR to_jsonb(live) IS DISTINCT FROM old OR live.status<>'passed' OR (live.valid_until IS NOT NULL AND live.valid_until<=clock_timestamp())) THEN
  RETURN current_evidence||jsonb_build_object('ready',true,'evidenceId',proof.id,'expiresAt',proof.expires_at);
 END IF;
 RETURN current_evidence||jsonb_build_object('ready',false,'evidenceId',NULL,'expiresAt',NULL);
END $$;

--
-- Name: ediel_service_administration_command_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_administration_command_v1(p_company_id uuid, p_actor_user_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE action text;v_command_id uuid;fields jsonb;allowed text[];a public.ediel_service_assignments%rowtype;g public.ediel_data_access_grants%rowtype;
 n_a public.ediel_service_assignments%rowtype;n_e public.ediel_service_evidence%rowtype;n_g public.ediel_data_access_grants%rowtype;
 prior gridex_service_administration.commands%rowtype;result jsonb;expected_version bigint;detail_text text;message_text text;l public.ediel_assignment_permission_links%rowtype;permission public.metering_permissions%rowtype;
BEGIN
 PERFORM gridex_service_permission.lock_request_writer_v1();
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_administration_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_input) k WHERE k NOT IN ('action','commandId','assignmentId','expectedVersion','grantId','expectedGrantVersion','fields')) THEN RAISE EXCEPTION 'ediel_service_command_shape_required';END IF;
 action:=p_input->>'action';v_command_id:=(p_input->>'commandId')::uuid;fields:=coalesce(p_input->'fields','{}');
 IF v_command_id IS NULL OR (action IN ('create_assignment','stage_evidence','create_grant','revoke_grant','approve_assignment','publish_grant')) IS NOT TRUE OR jsonb_typeof(fields) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_service_command_shape_required';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('ediel_service_command:'||v_command_id::text,0));
 SELECT * INTO prior FROM gridex_service_administration.commands c WHERE c.command_id=v_command_id FOR SHARE;
 IF FOUND THEN IF prior.company_id IS DISTINCT FROM p_company_id OR prior.actor_user_id IS DISTINCT FROM p_actor_user_id OR prior.input IS DISTINCT FROM p_input THEN RAISE EXCEPTION 'ediel_service_command_scope_conflict';END IF;RETURN prior.result;END IF;
 IF action='create_assignment' THEN
  IF p_input ? 'assignmentId' OR p_input ? 'expectedVersion' OR p_input ? 'grantId' THEN RAISE EXCEPTION 'ediel_service_create_scope_invalid';END IF;
  allowed:=ARRAY['beneficiary_company_id','provider_actor_id','actor_profile_id','customer_id','dso_actor_id','environment','mode','purpose','object_ids','product_ids','field_sets','data_start','data_end','valid_from','valid_to'];
  IF EXISTS(SELECT FROM jsonb_object_keys(fields) k WHERE NOT(k=ANY(allowed))) THEN RAISE EXCEPTION 'ediel_service_assignment_field_forbidden';END IF;
  n_a:=jsonb_populate_record(NULL::public.ediel_service_assignments,fields);
  -- These are administrative draft ownership checks; they grant no market or
  -- beneficiary permission and do not certify the referenced external actor.
  PERFORM x.id FROM public.customers x WHERE x.id=n_a.customer_id AND x.company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_customer_not_owned';END IF;
  PERFORM x.id FROM public.tenant_ediel_profiles x WHERE x.id=n_a.actor_profile_id AND x.company_id=p_company_id AND x.environment=n_a.environment FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_profile_not_owned';END IF;
  PERFORM x.id FROM public.tenant_actor_identifiers x WHERE x.company_id=p_company_id AND x.environment=n_a.environment AND x.actor_id=n_a.provider_actor_id AND x.identifier_type='EdielId' AND x.valid_from<=now() AND (x.valid_to IS NULL OR x.valid_to>now()) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_legal_provider_not_owned';END IF;
  INSERT INTO public.ediel_service_assignments(company_id,beneficiary_company_id,provider_actor_id,actor_profile_id,customer_id,dso_actor_id,environment,mode,purpose,object_ids,product_ids,field_sets,data_start,data_end,valid_from,valid_to,status)
   VALUES(p_company_id,n_a.beneficiary_company_id,n_a.provider_actor_id,n_a.actor_profile_id,n_a.customer_id,n_a.dso_actor_id,n_a.environment,n_a.mode,n_a.purpose,n_a.object_ids,n_a.product_ids,n_a.field_sets,n_a.data_start,n_a.data_end,n_a.valid_from,n_a.valid_to,'held') RETURNING * INTO a;
  result:=jsonb_build_object('status','held','assignmentId',a.id,'assignmentVersion',a.version,'missing',jsonb_build_array('authentic_current_owner_approvals_and_scoped_readiness'));
 ELSE
  expected_version:=(p_input->>'expectedVersion')::bigint;
  IF p_input->>'assignmentId' IS NULL OR expected_version IS NULL OR expected_version<1 THEN RAISE EXCEPTION 'ediel_service_assignment_version_required';END IF;
  SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=(p_input->>'assignmentId')::uuid;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(a.company_id::text||':'||a.environment||':'||a.provider_actor_id::text||':'||a.customer_id::text||':'||a.dso_actor_id::text||':'||a.mode,0));
  SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=(p_input->>'assignmentId')::uuid FOR UPDATE;
  IF a.version IS DISTINCT FROM expected_version THEN RAISE EXCEPTION 'ediel_service_assignment_stale';END IF;
  IF action='approve_assignment' THEN
   IF fields<>'{}'::jsonb OR p_input ? 'grantId' OR a.status IS DISTINCT FROM 'held' THEN RAISE EXCEPTION 'ediel_service_approval_scope_invalid';END IF;
   -- Only actual preexisting verified owner evidence can approve this scope.
   -- A held assessment rolls this status/history write back atomically.
   BEGIN
    UPDATE public.ediel_service_assignments SET status='active' WHERE company_id=p_company_id AND id=a.id RETURNING * INTO a;
    result:=public.ediel_service_assignment_assessment_v1(p_company_id,a.id);
    IF result->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_service_assignment_approval_held' USING DETAIL=result::text;END IF;
    result:=result||jsonb_build_object('status','approved_waiting_permission','accessGranted',false);
   EXCEPTION WHEN SQLSTATE 'P0001' THEN
    GET STACKED DIAGNOSTICS detail_text=PG_EXCEPTION_DETAIL,message_text=MESSAGE_TEXT;
    IF message_text IS DISTINCT FROM 'ediel_service_assignment_approval_held' THEN RAISE;END IF;
    result:=detail_text::jsonb;
   END;
  ELSIF action='stage_evidence' THEN
   IF p_input ? 'grantId' THEN RAISE EXCEPTION 'ediel_service_evidence_scope_invalid';END IF;
   allowed:=ARRAY['kind','source_reference','source_sha256','source_version','valid_from','valid_to','transport_relation_id','transport_actor_id','permission_agreement_reference','permission_requested_method','permission_network_contract_start','permission_network_contract_end','permission_purpose_code','permission_reporting_frequency','permission_request_grid_area','permission_reporting_term_kind','permission_customer_classification','permission_termination_reason','permission_termination_at'];
   IF EXISTS(SELECT FROM jsonb_object_keys(fields) k WHERE NOT(k=ANY(allowed))) THEN RAISE EXCEPTION 'ediel_service_evidence_approval_field_forbidden';END IF;
   n_e:=jsonb_populate_record(NULL::public.ediel_service_evidence,fields);
   IF n_e.kind='transport_mandate' THEN PERFORM r.id FROM public.tenant_counterparty_relations r WHERE r.company_id=p_company_id AND r.id=n_e.transport_relation_id AND r.counterparty_actor_id=n_e.transport_actor_id AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_transport_relation_not_owned';END IF;END IF;
   INSERT INTO public.ediel_service_evidence(company_id,assignment_id,kind,source_reference,source_sha256,source_version,valid_from,valid_to,status,transport_relation_id,transport_actor_id,permission_agreement_reference,permission_requested_method,permission_network_contract_start,permission_network_contract_end,permission_purpose_code,permission_reporting_frequency,permission_request_grid_area,permission_reporting_term_kind,permission_customer_classification,permission_termination_reason,permission_termination_at)
    VALUES(p_company_id,a.id,n_e.kind,n_e.source_reference,n_e.source_sha256,n_e.source_version,n_e.valid_from,n_e.valid_to,'pending',n_e.transport_relation_id,n_e.transport_actor_id,n_e.permission_agreement_reference,n_e.permission_requested_method,n_e.permission_network_contract_start,n_e.permission_network_contract_end,n_e.permission_purpose_code,n_e.permission_reporting_frequency,n_e.permission_request_grid_area,n_e.permission_reporting_term_kind,n_e.permission_customer_classification,n_e.permission_termination_reason,n_e.permission_termination_at) RETURNING * INTO n_e;
   result:=jsonb_build_object('status','pending','assignmentId',a.id,'assignmentVersion',a.version,'evidenceId',n_e.id,'approvalGranted',false);
  ELSIF action='create_grant' THEN
   IF p_input ? 'grantId' THEN RAISE EXCEPTION 'ediel_service_grant_scope_invalid';END IF;
   allowed:=ARRAY['permission_link_id','object_ids','product_ids','fields','data_start','data_end','valid_from','valid_to'];
   IF EXISTS(SELECT FROM jsonb_object_keys(fields) k WHERE NOT(k=ANY(allowed))) THEN RAISE EXCEPTION 'ediel_service_grant_field_forbidden';END IF;
   n_g:=jsonb_populate_record(NULL::public.ediel_data_access_grants,fields);
   INSERT INTO public.ediel_data_access_grants(company_id,beneficiary_company_id,assignment_id,permission_link_id,object_ids,product_ids,fields,purpose,data_start,data_end,valid_from,valid_to,status)
    VALUES(p_company_id,a.beneficiary_company_id,a.id,n_g.permission_link_id,n_g.object_ids,n_g.product_ids,n_g.fields,a.purpose,n_g.data_start,n_g.data_end,n_g.valid_from,n_g.valid_to,'held') RETURNING * INTO g;
   result:=jsonb_build_object('status','held','assignmentId',a.id,'assignmentVersion',a.version,'grantId',g.id,'grantVersion',g.version,'accessGranted',false);
  ELSE
   IF fields<>'{}'::jsonb OR p_input->>'grantId' IS NULL THEN RAISE EXCEPTION 'ediel_service_revoke_scope_invalid';END IF;
   IF (p_input->>'expectedGrantVersion')::bigint IS NULL OR (p_input->>'expectedGrantVersion')::bigint<1 THEN RAISE EXCEPTION 'ediel_grant_version_required';END IF;
   SELECT * INTO STRICT g FROM public.ediel_data_access_grants WHERE company_id=p_company_id AND assignment_id=a.id AND id=(p_input->>'grantId')::uuid FOR UPDATE;
   IF g.version IS DISTINCT FROM (p_input->>'expectedGrantVersion')::bigint THEN RAISE EXCEPTION 'ediel_grant_version_stale';END IF;
   IF action='publish_grant' THEN
    IF g.status IS DISTINCT FROM 'held' OR g.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'ediel_revoked_grant_requires_new_basis';END IF;
    result:=public.ediel_service_assignment_assessment_v1(p_company_id,a.id);
    IF result->>'status' IS DISTINCT FROM 'authorized' THEN RETURN result;END IF;
    SELECT * INTO STRICT l FROM public.ediel_assignment_permission_links WHERE company_id=p_company_id AND id=g.permission_link_id AND assignment_id=a.id FOR SHARE;
    SELECT * INTO STRICT permission FROM public.metering_permissions WHERE company_id=p_company_id AND id=l.permission_id FOR SHARE;
    PERFORM x.id FROM public.metering_permission_sites x WHERE x.company_id=p_company_id AND x.metering_permission_id=permission.id ORDER BY x.id FOR SHARE;
    IF (permission.status IN ('active','approved','partially_approved')) IS NOT TRUE OR permission.customer_id IS DISTINCT FROM a.customer_id OR gridex_service_administration.permission_matches_assignment_v1(a,permission) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('current_source_approved_market_permission'));END IF;
    IF g.valid_from>now() OR (g.valid_to IS NOT NULL AND g.valid_to<=now()) OR g.beneficiary_company_id IS DISTINCT FROM a.beneficiary_company_id OR g.purpose IS DISTINCT FROM a.purpose OR NOT(g.object_ids<@a.object_ids AND g.product_ids<@a.product_ids AND g.fields<@a.field_sets) OR g.data_start<a.data_start OR (a.data_end IS NOT NULL AND (g.data_end IS NULL OR g.data_end>a.data_end)) THEN RAISE EXCEPTION 'ediel_grant_basis_changed';END IF;
    IF EXISTS(SELECT FROM unnest(g.object_ids) object_id CROSS JOIN unnest(g.product_ids) product_id WHERE NOT EXISTS(SELECT FROM public.metering_permission_sites x WHERE x.company_id=p_company_id AND x.metering_permission_id=permission.id AND x.customer_id=a.customer_id AND x.facility_id=object_id AND x.status IN ('approved','active') AND x.metadata->>'source'='inbound_prodat_z14' AND x.metadata->>'edielMessageId'=coalesce(permission.inbound_z14_message_id,permission.source_z14_message_id)::text AND x.metadata->>'mode'=CASE a.mode WHEN 'V' THEN 'S17' ELSE 'S18' END AND x.metadata->>'product'=product_id AND x.start_at IS NOT NULL AND g.data_start>=x.start_at AND (x.end_at IS NULL OR (g.data_end IS NOT NULL AND g.data_end<=x.end_at)))) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('explicit_approved_object_product_period'));END IF;
    UPDATE public.ediel_data_access_grants SET status='active' WHERE company_id=p_company_id AND id=g.id RETURNING * INTO g;
    result:=jsonb_build_object('status','active','assignmentId',a.id,'assignmentVersion',a.version,'grantId',g.id,'grantVersion',g.version,'accessGranted',true);
   ELSE
   IF g.status<>'revoked' THEN UPDATE public.ediel_data_access_grants SET status='revoked',revoked_at=now() WHERE id=g.id AND company_id=p_company_id RETURNING * INTO g;END IF;
   result:=jsonb_build_object('status','revoked','assignmentId',a.id,'assignmentVersion',a.version,'grantId',g.id,'grantVersion',g.version,'accessGranted',false);
   END IF;
  END IF;
 END IF;
 INSERT INTO gridex_service_administration.commands(command_id,company_id,actor_user_id,input,result) VALUES(v_command_id,p_company_id,p_actor_user_id,p_input,result);
 RETURN result;
END $$;

--
-- Name: ediel_service_administration_read_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_administration_read_v1(p_company_id uuid, p_actor_user_id uuid, p_assignment_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE assignments jsonb;evidence jsonb;grants jsonb;history jsonb;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.read') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_administration_actor_forbidden' USING ERRCODE='42501';END IF;
 IF p_assignment_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.ediel_service_assignments a WHERE a.company_id=p_company_id AND a.id=p_assignment_id) THEN RAISE EXCEPTION 'ediel_service_assignment_unavailable';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment',to_jsonb(a),'assessment',public.ediel_service_assignment_assessment_v1(p_company_id,a.id)) ORDER BY a.created_at DESC,a.id),'[]') INTO assignments FROM(SELECT * FROM public.ediel_service_assignments WHERE company_id=p_company_id AND (p_assignment_id IS NULL OR id=p_assignment_id) ORDER BY created_at DESC,id LIMIT 100) a;
 IF p_assignment_id IS NOT NULL THEN
  SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at DESC,e.id),'[]') INTO evidence FROM(SELECT * FROM public.ediel_service_evidence WHERE company_id=p_company_id AND assignment_id=p_assignment_id ORDER BY created_at DESC,id LIMIT 100) e;
  SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY g.created_at DESC,g.id),'[]') INTO grants FROM(SELECT * FROM public.ediel_data_access_grants WHERE company_id=p_company_id AND assignment_id=p_assignment_id ORDER BY created_at DESC,id LIMIT 100) g;
  SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.id DESC),'[]') INTO history FROM(SELECT * FROM public.ediel_service_history WHERE company_id=p_company_id AND (entity_table='ediel_service_assignments' AND entity_id=p_assignment_id OR entity_table='ediel_service_evidence' AND entity_id IN(SELECT id FROM public.ediel_service_evidence WHERE company_id=p_company_id AND assignment_id=p_assignment_id) OR entity_table='ediel_data_access_grants' AND entity_id IN(SELECT id FROM public.ediel_data_access_grants WHERE company_id=p_company_id AND assignment_id=p_assignment_id)) ORDER BY id DESC LIMIT 100) h;
 END IF;
 RETURN jsonb_build_object('companyId',p_company_id,'assignments',assignments,'evidence',coalesce(evidence,'[]'),'grants',coalesce(grants,'[]'),'history',coalesce(history,'[]'),'marketActivationGranted',false);
END $$;

--
-- Name: ediel_service_assignment_assessment_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_assignment_assessment_v1(p_provider_company_id uuid, p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE result jsonb;a public.ediel_service_assignments%rowtype;k text;missing text[]:=ARRAY[]::text[];
BEGIN
 PERFORM gridex_ediel_services.lock_evidence_graph_v1();result:=gridex_ediel_services.assignment_assessment_basis_v1(p_provider_company_id,p_assignment_id);
 IF result->>'status' IS DISTINCT FROM 'authorized' THEN RETURN result;END IF;
 SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=p_provider_company_id AND id=p_assignment_id;
 FOREACH k IN ARRAY ARRAY['end_user_contract','dso_contract','service_contract','downstream_use','privacy_roles'] LOOP
  IF NOT EXISTS(SELECT FROM public.ediel_service_evidence e WHERE e.company_id=a.company_id AND e.assignment_id=a.id AND e.kind=k AND gridex_ediel_services.review_current_v1(e) IS TRUE) THEN missing:=array_append(missing,'native_review:'||k);END IF;
 END LOOP;
 IF EXISTS(SELECT FROM public.tenant_counterparty_relations r WHERE r.company_id=a.company_id AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.counterparty_actor_id<>a.provider_actor_id AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to))
 AND NOT EXISTS(SELECT FROM public.ediel_service_evidence e JOIN public.tenant_counterparty_relations r ON r.id=e.transport_relation_id AND r.counterparty_actor_id=e.transport_actor_id AND r.company_id=a.company_id AND r.environment=a.environment AND r.relation_type='ediel_transport_agent' AND r.is_enabled AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to) WHERE e.company_id=a.company_id AND e.assignment_id=a.id AND e.kind='transport_mandate' AND gridex_ediel_services.review_current_v1(e) IS TRUE) THEN missing:=array_append(missing,'native_review:transport_mandate');END IF;
 IF cardinality(missing)>0 THEN RETURN jsonb_build_object('status','held','missing',missing);END IF;RETURN result;
END $$;

--
-- Name: ediel_service_evidence_immutable_basis_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_evidence_immutable_basis_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP='DELETE' OR TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'ediel_evidence_source_removal_forbidden'; END IF;
 IF OLD.status IN ('verified','revoked') AND
  (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN
  RAISE EXCEPTION 'ediel_verified_evidence_requires_new_source_record';
 END IF;
 IF OLD.status='revoked' AND NEW.status IS DISTINCT FROM 'revoked' THEN RAISE EXCEPTION 'ediel_revoked_evidence_requires_new_source_record'; END IF;
 IF OLD.status='verified' AND (NEW.status IN ('verified','revoked')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_verified_evidence_cannot_be_unapproved'; END IF;
 RETURN NEW;
END $$;

--
-- Name: ediel_service_history_record_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_history_record_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 insert into public.ediel_service_history(company_id,entity_table,entity_id,before_record,after_record)
 values(new.company_id,tg_table_name,new.id,case when tg_op='UPDATE' then to_jsonb(old) else null end,to_jsonb(new));
 return new;
end;
$$;

--
-- Name: ediel_service_permission_manual_context_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_manual_context_v1(p_company_id uuid, p_actor_user_id uuid, p_customer_id uuid, p_selection jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE aid uuid;pid uuid;expected bigint;code text;mode text;link_count integer;a public.ediel_service_assignments%rowtype;p public.metering_permissions%rowtype;result jsonb;basis jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_service_administration.require_manual_actor_v1(p_company_id,p_actor_user_id);
 PERFORM x.id FROM public.customers x WHERE x.company_id=p_company_id AND x.id=p_customer_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_service_manual_customer_not_owned';END IF;
 IF jsonb_typeof(p_selection) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_selection) k WHERE k NOT IN('permissionId','assignmentId','expectedVersion','code','mode','fromDate','toDate')) OR (p_selection->>'code' IN('Z13','Z18')) IS NOT TRUE OR (p_selection->>'mode' IS NOT NULL AND (p_selection->>'mode' IN('V','VH')) IS NOT TRUE) THEN RAISE EXCEPTION 'ediel_service_manual_selection_invalid';END IF;
 aid:=(p_selection->>'assignmentId')::uuid;pid:=(p_selection->>'permissionId')::uuid;expected:=(p_selection->>'expectedVersion')::bigint;code:=p_selection->>'code';mode:=p_selection->>'mode';
 IF pid IS NOT NULL THEN
  SELECT * INTO p FROM public.metering_permissions WHERE company_id=p_company_id AND id=pid;
  IF NOT FOUND OR p.customer_id IS DISTINCT FROM p_customer_id THEN RAISE EXCEPTION 'ediel_service_manual_permission_not_owned';END IF;
  IF aid IS NULL THEN
   SELECT count(*),min(l.assignment_id::text)::uuid INTO link_count,aid FROM public.ediel_assignment_permission_links l WHERE l.company_id=p_company_id AND l.permission_id=pid;
   IF link_count<>1 THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('explicit_or_unique_source_assignment_permission_link'));END IF;
  END IF;
 END IF;
 IF aid IS NULL THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('explicit_source_assignment_required'));END IF;
 SELECT * INTO a FROM public.ediel_service_assignments WHERE company_id=p_company_id AND id=aid;
 IF NOT FOUND OR a.customer_id IS DISTINCT FROM p_customer_id THEN RAISE EXCEPTION 'ediel_service_manual_assignment_not_owned';END IF;
 IF (expected IS NULL OR expected<1) AND p_selection->>'assignmentId' IS NOT NULL THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('explicit_assignment_version_required'));END IF;
 expected:=coalesce(expected,a.version);
 IF pid IS NOT NULL AND NOT EXISTS(SELECT FROM public.ediel_assignment_permission_links l WHERE l.company_id=p_company_id AND l.assignment_id=aid AND l.permission_id=pid) THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('source_assignment_permission_link_required'));END IF;
 IF mode IS NOT NULL AND mode IS DISTINCT FROM a.mode OR p_selection->>'fromDate' IS NOT NULL AND (p_selection->>'fromDate')::date IS DISTINCT FROM (a.data_start AT TIME ZONE INTERVAL '01:00')::date OR p_selection->>'toDate' IS NOT NULL AND (p_selection->>'toDate')::date IS DISTINCT FROM (a.data_end AT TIME ZONE INTERVAL '01:00')::date THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('selected_request_scope_differs_from_source_assignment'));END IF;
 IF pid IS NULL THEN
  IF code='Z18' THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,jsonb_build_array('explicit_termination_permission_required'));END IF;
  result:=public.ediel_coordinate_service_permission_v1(p_company_id,aid,p_actor_user_id,expected,'request_access');pid:=(result->>'permissionId')::uuid;
 ELSIF code='Z13' THEN result:=public.ediel_resolve_service_permission_command_v1(p_company_id,aid,p_actor_user_id,expected,pid);
 END IF;
 IF result->>'status'='held' THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,result->'missing');END IF;
 IF result->>'status'='reuse_permission' THEN RETURN result||jsonb_build_object('companyId',p_company_id,'customerId',p_customer_id,'assignmentId',aid,'assignmentVersion',expected,'code',code);END IF;
 basis:=gridex_service_permission.context_v1(p_company_id,aid,p_actor_user_id,expected,code,pid);
 IF basis->>'status' IS DISTINCT FROM 'authorized' THEN RETURN gridex_service_administration.manual_hold_v1(p_company_id,p_customer_id,p_actor_user_id,p_selection,coalesce(basis->'missing',jsonb_build_array('current_source_permission_context')));END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'customerId',p_customer_id,'assignmentId',aid,'assignmentVersion',expected,'permissionId',pid,'code',code);
END $$;

--
-- Name: ediel_service_permission_manual_options_v1(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_manual_options_v1(p_company_id uuid, p_actor_user_id uuid, p_permission_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE options jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.read') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_manual_read_forbidden' USING ERRCODE='42501';END IF;
 IF p_permission_ids IS NULL OR cardinality(p_permission_ids)>100 OR array_position(p_permission_ids,NULL) IS NOT NULL OR cardinality(p_permission_ids)<>(SELECT count(DISTINCT id) FROM unnest(p_permission_ids) id) THEN RAISE EXCEPTION 'ediel_service_manual_option_selection_invalid';END IF;
 IF (SELECT count(*) FROM public.metering_permissions p WHERE p.company_id=p_company_id AND p.id=ANY(p_permission_ids))<>cardinality(p_permission_ids) THEN RAISE EXCEPTION 'ediel_service_manual_permission_not_owned';END IF;
 PERFORM a.id FROM public.ediel_service_assignments a JOIN public.ediel_assignment_permission_links l ON l.company_id=a.company_id AND l.assignment_id=a.id JOIN public.metering_permissions p ON p.company_id=l.company_id AND p.id=l.permission_id WHERE l.company_id=p_company_id AND l.permission_id=ANY(p_permission_ids) AND a.customer_id=p.customer_id ORDER BY a.id FOR SHARE OF a;
 PERFORM p.id FROM public.metering_permissions p WHERE p.company_id=p_company_id AND p.id=ANY(p_permission_ids) ORDER BY p.id FOR SHARE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('permissionId',p.id,'assignmentId',a.id,'assignmentVersion',a.version,'beneficiaryCompanyId',a.beneficiary_company_id,'beneficiaryLabel',beneficiary.name,'purpose',a.purpose,'mode',a.mode,'status',a.status) ORDER BY p.id,a.id),'[]') INTO options FROM public.ediel_assignment_permission_links l JOIN public.ediel_service_assignments a ON a.company_id=l.company_id AND a.id=l.assignment_id JOIN public.metering_permissions p ON p.company_id=l.company_id AND p.id=l.permission_id JOIN public.companies beneficiary ON beneficiary.id=a.beneficiary_company_id WHERE l.company_id=p_company_id AND l.permission_id=ANY(p_permission_ids) AND a.customer_id=p.customer_id;
 RETURN jsonb_build_object('companyId',p_company_id,'options',options);
END $$;

--
-- Name: ediel_service_permission_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s gridex_service_permission.origins%rowtype;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_message_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_permission_origin_message_unbound'; END IF;
 PERFORM public.ediel_require_service_permission_origin_current_v1(p_company_id,p_message_id);
 RETURN jsonb_build_object('basis',s.basis,'actorUserId',s.actor_user_id,'intentId',s.intent_id);
END $$;

--
-- Name: ediel_service_permission_message_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s gridex_service_permission.origins%rowtype;current_source gridex_service_permission.origins%rowtype;m public.ediel_messages%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR p_actor_user_id IS NULL OR (p_phase IN('prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_message_phase_required';END IF;
 -- Recovery qualification prelocks its complete source/ACK cohort first. The
 -- selected terminal source is already held there; ordinary originals use the
 -- same source-before-current-actor order here.
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR UPDATE;
 PERFORM 1 FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM 1 FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR (CASE p_phase WHEN 'prepare' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false)
   WHEN 'send' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_permission_origin_message_forbidden' USING ERRCODE='42501';END IF;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'ediel_permission_origin_message_not_owned';END IF;
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF s.message_id IS NULL THEN RETURN NULL;END IF;
 IF s.intent_id IS DISTINCT FROM m.intent_id OR s.basis->>'companyId' IS DISTINCT FROM p_company_id::text OR s.basis->>'code' IS DISTINCT FROM m.message_code OR s.basis->>'environment' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'ediel_permission_origin_message_basis_changed';END IF;
 -- Full current service source, legal tuple, immutable wire/evidence and bounds
 -- remain mandatory. The historic source actor is provenance, not this caller.
 PERFORM gridex_service_permission.require_original_source_current_v1(p_company_id,p_message_id);
 -- The sole source owner locks permission/evidence before its immutable origin.
 -- Do not invert that order by locking this origin before current qualification.
 SELECT * INTO current_source FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id FOR SHARE;
 IF current_source IS DISTINCT FROM s THEN RAISE EXCEPTION 'ediel_permission_origin_message_basis_changed' USING ERRCODE='40001';END IF;
 RETURN jsonb_build_object('basis',s.basis,'actorUserId',s.actor_user_id,'intentId',s.intent_id);
END$$;

--
-- Name: ediel_service_permission_origin_v1(uuid, uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_origin_v1(p_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_code text, p_permission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'ediel_permission_origin_service_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_service_permission.context_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,p_code,p_permission_id);
END $$;

--
-- Name: ediel_service_scope_guard_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_scope_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare a public.ediel_service_assignments%rowtype; l public.ediel_assignment_permission_links%rowtype; p public.metering_permissions%rowtype;
begin
 if tg_table_name='ediel_service_assignments' then
  if tg_op='UPDATE' then
   if (new.company_id,new.beneficiary_company_id,new.provider_actor_id,new.actor_profile_id,new.customer_id,new.dso_actor_id,new.environment,new.mode) is distinct from
      (old.company_id,old.beneficiary_company_id,old.provider_actor_id,old.actor_profile_id,old.customer_id,old.dso_actor_id,old.environment,old.mode) then raise exception 'ediel_assignment_identity_immutable'; end if;
   new.version:=old.version+1; new.updated_at:=now();
  end if;
  return new;
 end if;
 select * into strict a from public.ediel_service_assignments where company_id=new.company_id and id=new.assignment_id for share;
 if tg_table_name='ediel_assignment_permission_links' then
  if tg_op='UPDATE' and (new.company_id,new.assignment_id,new.permission_id) is distinct from (old.company_id,old.assignment_id,old.permission_id) then raise exception 'ediel_permission_link_identity_immutable'; end if;
  select * into strict p from public.metering_permissions where company_id=new.company_id and id=new.permission_id for share;
  if p.customer_id is distinct from a.customer_id then raise exception 'ediel_assignment_permission_customer_mismatch'; end if;
  return new;
 end if;
 select * into strict l from public.ediel_assignment_permission_links where company_id=new.company_id and id=new.permission_link_id for share;
 if l.assignment_id<>a.id or new.beneficiary_company_id<>a.beneficiary_company_id or new.purpose<>a.purpose or
    not(new.object_ids <@ a.object_ids and new.product_ids <@ a.product_ids and new.fields <@ a.field_sets) or
    new.data_start<a.data_start or (a.data_end is not null and (new.data_end is null or new.data_end>a.data_end)) or
    new.valid_from<a.valid_from or (a.valid_to is not null and (new.valid_to is null or new.valid_to>a.valid_to)) then
  raise exception 'ediel_grant_scope_exceeds_assignment';
 end if;
 if tg_op='UPDATE' then
  if (new.company_id,new.beneficiary_company_id,new.assignment_id,new.permission_link_id) is distinct from
     (old.company_id,old.beneficiary_company_id,old.assignment_id,old.permission_link_id) then raise exception 'ediel_grant_identity_immutable'; end if;
  if old.status='revoked' and new.status<>'revoked' then raise exception 'ediel_revoked_grant_requires_new_basis'; end if;
  new.version:=old.version+1; new.updated_at:=now();
 end if;
 return new;
end;
$$;

--
-- Name: ediel_signed_brp_declaration_scope_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_signed_brp_declaration_scope_v1(p_company_id uuid, p_actor_user_id uuid, p_selector jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE terminal_result jsonb;terminal_kind text;
BEGIN
 terminal_result:=gridex_brp_declaration_intake.terminal_scope_body_v1(p_company_id,p_actor_user_id,p_selector);
 IF gridex_brp_declaration_intake.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'signed_brp_terminal_actor_revoked' USING ERRCODE='42501';END IF;
 RETURN terminal_result;
END$$;

--
-- Name: ediel_storage_retention_target_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_storage_retention_target_v1(p_path text) RETURNS SETOF boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT true FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class='transport_raw_mime_bytes' AND t.storage_path=p_path AND gridex_ediel_retention.permission_v1(t.company_id,public.ediel_retention_session_actor_v1(),'ediel.retention.purge') IS TRUE AND EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=t.company_id AND m.user_id=public.ediel_retention_session_actor_v1() AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
$$;

--
-- Name: ediel_submit_artifact_retention_v1(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_submit_artifact_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_document_base64 text, p_issuer_receipt jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_requested_changes.artifacts%rowtype;bytes bytea;hash text;d gridex_ediel_retention.decisions%rowtype;
BEGIN PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.submit');
 IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,'requested_change_source_artifact_bytes') IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required';END IF;SELECT * INTO STRICT a FROM gridex_requested_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;
 IF a.source_bytes IS NULL OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash THEN RAISE EXCEPTION 'ediel_retention_actual_archived_bytes_required';END IF;
 IF length(p_document_base64)>1398104 THEN RAISE EXCEPTION 'ediel_retention_document_limit';END IF;bytes:=decode(p_document_base64,'base64');hash:=encode(sha256(bytes),'hex');
 IF octet_length(bytes) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'ediel_retention_document_required';END IF;
 INSERT INTO gridex_ediel_retention.decisions(company_id,artifact_id,source_hash,claims_hash,document_bytes,document_hash,issuer_receipt,submitted_by)
 VALUES(p_company_id,a.id,a.source_hash,a.claims_hash,bytes,hash,p_issuer_receipt,p_actor_user_id) ON CONFLICT(company_id,artifact_id,document_hash) DO NOTHING;
 IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,'requested_change_source_artifact_bytes') IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required';END IF;SELECT * INTO STRICT d FROM gridex_ediel_retention.decisions WHERE company_id=p_company_id AND artifact_id=a.id AND document_hash=hash FOR SHARE;
 IF d.issuer_receipt IS DISTINCT FROM p_issuer_receipt THEN RAISE EXCEPTION 'ediel_retention_original_receipt_conflict';END IF;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_retention_decision',d.id,'ediel.retention.submitted',jsonb_build_object('artifactId',a.id,'sourceHash',a.source_hash,'documentHash',hash));
 RETURN jsonb_build_object('status','submitted','decisionId',d.id,'documentHash',hash,'sourceHash',a.source_hash,'issuerQualified',gridex_ediel_retention.receipt_v1(d) IS NOT NULL);
END$$;

