--
-- Name: ediel_supply_rescission_scope_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_supply_rescission_scope_v1(p_company_id uuid, p_actor_user_id uuid, p_selector jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE gridex_intake_session_result_v1 jsonb; scope jsonb;BEGIN PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'read');
 IF gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'supply_rescission_actor_forbidden' USING ERRCODE='42501';END IF;
 scope:=gridex_supply_rescission.scope_v1(p_company_id,p_selector);IF scope IS NULL THEN gridex_intake_session_result_v1 := jsonb_build_object('status','held','companyId',p_company_id,'missing',ARRAY['actual_current_own_supply_signed_contract_and_national_source_grammar']); PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'read'); RETURN gridex_intake_session_result_v1;END IF;
 gridex_intake_session_result_v1 := jsonb_build_object('status','scoped','companyId',p_company_id,'scope',scope,'scopeHash',encode(sha256(convert_to(scope::text,'UTF8')),'hex'),'missing','[]'::jsonb); PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,'read'); RETURN gridex_intake_session_result_v1;
END$$;

--
-- Name: ediel_supply_start_is_cancelled_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_supply_start_is_cancelled_v1(p_company_id uuid, p_switch_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=sw.inbound_z04_message_id AND tr.company_id=sw.company_id WHERE sw.id=p_switch_request_id AND sw.company_id=p_company_id AND sw.status='cancelled_before_start' AND sw.id=ANY(tr.qualified_switch_ids) AND tr.source_code='Z04' AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'reason'='Z24'))
$$;

--
-- Name: ediel_switch_cancellation_customer_masterdata_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_switch_cancellation_customer_masterdata_basis_v1(p_company_id uuid, p_switch_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_masterdata_service_required' USING ERRCODE='42501';END IF;
 RETURN gridex_switch_cancellations.customer_source_v1(p_company_id,p_switch_id,p_actor_user_id,'prepare');
END$$;

--
-- Name: ediel_switch_cancellation_customer_masterdata_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_switch_cancellation_customer_masterdata_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_switch_cancellations.origins%rowtype;p gridex_customer_masterdata.preparations%rowtype;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_masterdata_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_switch_cancellations.prelock_customer_message_v1(p_company_id,p_message_id);
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR SHARE;
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=p_company_id AND message_id=m.id FOR SHARE;
 IF m.id IS NULL OR o.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' OR m.status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'customer_masterdata_cancellation_bound_draft_required';END IF;
 PERFORM gridex_customer_masterdata.require_current_v1(p_company_id,m.id,p_actor_user_id,'prepare');
 SELECT prep.* INTO p FROM gridex_customer_masterdata.originals original JOIN gridex_customer_masterdata.preparations prep ON prep.id=original.preparation_id WHERE original.company_id=p_company_id AND original.message_id=m.id AND original.payload_hash=m.immutable_payload_hash FOR SHARE OF prep;
 IF p.id IS NULL OR p.cancellation_origin_id IS DISTINCT FROM o.id OR p.actor_user_id IS DISTINCT FROM m.created_by THEN RAISE EXCEPTION 'customer_masterdata_cancellation_bound_draft_required';END IF;
 RETURN (p.basis-'sourceProof')||jsonb_build_object('sourceContextId',p.id,'messageBinding',jsonb_build_object('id',m.id,'environment',m.environment,'intentId',m.intent_id,'routeId',m.communication_route_id,'payloadHash',m.immutable_payload_hash),
  'cancellationBinding',jsonb_build_object('operationId',o.id,'switchRequestId',o.switch_id,'actorUserId',p_actor_user_id,'originalMessageId',o.original_message_id,'originalHash',o.original_hash,'preparerId',p.actor_user_id));
END$$;

--
-- Name: ediel_switch_cancellation_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_switch_cancellation_source_v1(p_company_id uuid, p_switch_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$DECLARE b jsonb;method text;
BEGIN
 b:=gridex_switch_cancellations.context_v1(p_company_id,p_switch_id,p_actor_user_id);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 method:=gridex_switch_cancellations.original_method_v1(p_company_id,(b->>'originalMessageId')::uuid,b->>'originalHash',b->>'environment');
 IF method IS NULL THEN RETURN jsonb_build_object('status','held','missing',ARRAY['qualified_immutable_original_requested_method']);END IF;
 RETURN b||jsonb_build_object('requestedMethod',method);
END $$;

--
-- Name: ediel_transport_exception_alarms_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_transport_exception_alarms_v1(p_company_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE alarms jsonb;BEGIN PERFORM gridex_transport_exception.actor_v1(p_company_id,p_actor_user_id,'communication.write');
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'attemptId',attempt_id,'messageId',message_id,'responsibleUserId',responsible_user_id,'facts',facts,'createdAt',created_at) ORDER BY created_at),'[]') INTO alarms
 FROM(SELECT * FROM gridex_transport_exception.alarms WHERE company_id=p_company_id ORDER BY created_at DESC LIMIT 100) a;RETURN alarms;END$$;

--
-- Name: ediel_verify_registry_el_actor_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_verify_registry_el_actor_v1(p_actor_user_id uuid, p_actor_id uuid, p_route_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r public.platform_actor_routes%rowtype;q jsonb;ids uuid[]:='{}';BEGIN
 PERFORM gridex_registry_import.lock_import_graph_v1();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE ROW EXCLUSIVE MODE;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_registry_service_required' USING ERRCODE='42501';END IF;
 IF p_actor_user_id IS NULL OR public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;PERFORM u.id FROM auth.users u WHERE u.id=p_actor_user_id FOR SHARE;PERFORM a.user_id FROM public.admin_users a WHERE a.user_id=p_actor_user_id FOR SHARE;PERFORM u.id FROM public.user_roles u WHERE u.user_id=p_actor_user_id FOR SHARE;
 IF public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_revoked' USING ERRCODE='42501';END IF;
 PERFORM a.id FROM public.platform_market_actors a WHERE a.id=p_actor_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'ediel_registry_actor_required';END IF;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=p_actor_id ORDER BY i.id FOR SHARE;
 FOR r IN SELECT * FROM public.platform_actor_routes x WHERE x.actor_id=p_actor_id AND(p_route_id IS NULL OR x.id=p_route_id) ORDER BY x.id FOR UPDATE LOOP
  q:=gridex_registry_import.route_source_v1(r.id);
  IF q->>'status'='source_qualified' AND q->>'market'='EL' THEN ids:=array_append(ids,r.id);END IF;
 END LOOP;
 IF cardinality(ids)=0 OR p_route_id IS NOT NULL AND(cardinality(ids)<>1 OR ids[1] IS DISTINCT FROM p_route_id) THEN RAISE EXCEPTION 'ediel_registry_current_el_route_source_required';END IF;
 UPDATE public.platform_market_actors SET match_status='verified',visible_to_tenants=true,verified_at=clock_timestamp(),verified_by=p_actor_user_id,status='active',updated_at=clock_timestamp() WHERE id=p_actor_id;
 UPDATE public.platform_actor_routes SET status='active',is_verified=true,auto_send_allowed=false,updated_at=clock_timestamp() WHERE id=ANY(ids);
 RETURN jsonb_build_object('actorId',p_actor_id,'routeIds',ids,'market','EL','autoSendAllowed',false);
END$$;

--
-- Name: ediel_witness_confirmed_customer_source_before_scope_fence_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_witness_confirmed_customer_source_before_scope_fence_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v gridex_requested_changes.confirmed_customer_versions%rowtype;w gridex_requested_changes.customer_version_availability%rowtype;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'archive','death') IS NOT TRUE THEN RAISE EXCEPTION 'customer_source_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO v FROM gridex_requested_changes.confirmed_customer_versions WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND canonical_assessment_id IS NOT NULL AND created_xid<>pg_current_xact_id() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'customer_source_committed_version_required';END IF;
 INSERT INTO gridex_requested_changes.customer_version_availability(source_message_id,company_id,environment,payload_hash,visibility_snapshot) VALUES(v.source_message_id,v.company_id,v.environment,v.payload_hash,pg_current_snapshot()::text) ON CONFLICT DO NOTHING;
 SELECT * INTO w FROM gridex_requested_changes.customer_version_availability WHERE source_message_id=v.source_message_id;
 RETURN jsonb_build_object('owner','confirmed-customer-source-availability-v1','sourceMessageId',v.source_message_id,'payloadHash',w.payload_hash,'availableAt',w.observed_at);
END$$;

--
-- Name: ediel_witness_confirmed_customer_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_witness_confirmed_customer_source_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();RETURN public.ediel_witness_confirmed_customer_source_before_scope_fence_v1(p_company_id,p_source_message_id,p_actor_user_id);END$$;

--
-- Name: ensure_customer_invoice_reference_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_customer_invoice_reference_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.company_id is not distinct from old.company_id
     and new.id is not distinct from old.id then
    new.invoice_reference := old.invoice_reference;
    return new;
  end if;
  new.invoice_reference := 'invoice_' || substr(
    translate(
      rtrim(encode(extensions.digest(convert_to(
        'gridex-public-reference:v1:' || new.company_id::text || ':invoice:' || new.id::text,
        'UTF8'
      ), 'sha256'::text), 'base64'), '='),
      '+/', '-_'
    ),
    1,
    32
  );
  return new;
end;
$$;

--
-- Name: gridex_accept_external_staff_invitation_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_accept_external_staff_invitation_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb; b public.tenant_staff_identity_bindings%rowtype; i public.company_invitations%rowtype;
BEGIN
 result:=public.gridex_lookup_pending_staff_identity_binding_v1(p_command);
 IF result->>'binding_id' IS DISTINCT FROM p_command->>'binding_id' OR result->>'binding_version' IS DISTINCT FROM p_command->>'binding_version'
  OR p_command->'email_confirmed' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'staff_identity_acceptance_invalid' USING ERRCODE='42501'; END IF;
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE id=(result->>'binding_id')::uuid FOR UPDATE;
 SELECT * INTO i FROM public.company_invitations WHERE id=b.invitation_id;
 IF lower(btrim(p_command->>'verified_email')) IS DISTINCT FROM lower(btrim(i.email)) OR i.invited_user_id IS DISTINCT FROM b.actor_user_id
  OR nullif(btrim(p_command->>'idempotency_key'),'') IS NULL
 THEN RAISE EXCEPTION 'staff_identity_acceptance_invalid' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id FOR SHARE OF u,profile;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=b.actor_user_id AND u.deleted_at IS NULL
  AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp()) AND profile.user_status='active')
 THEN RAISE EXCEPTION 'staff_identity_actor_inactive' USING ERRCODE='42501'; END IF;
 IF b.status='pending' THEN UPDATE public.tenant_staff_identity_bindings SET status='active' WHERE id=b.id; END IF;
 -- Stable authority only. No tenant access token, password or verification
 -- snapshot enters the unchanged command hash, audit or membership engine.
 RETURN public.canonical_accept_tenant_invitation(jsonb_build_object('company_id',b.company_id,'invitation_id',b.invitation_id,'user_id',b.actor_user_id,'actor_user_id',b.actor_user_id,
   'api_client_id',b.api_client_id,'channel','staff_external_onboarding','idempotency_key',p_command->>'idempotency_key'));
END $$;

--
-- Name: gridex_accept_staff_invitation_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_accept_staff_invitation_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_actor_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_invitation_id uuid := nullif(p_command->>'invitation_id','')::uuid;
  v_client_id uuid := nullif(p_command->>'api_client_id','')::uuid;
  v_provider_id uuid := nullif(p_command->>'provider_id','')::uuid;
  v_key text := nullif(btrim(p_command->>'idempotency_key'),'');
  v_client public.integration_api_clients%rowtype;
  v_provider public.tenant_customer_identity_providers%rowtype;
  v_invitation public.company_invitations%rowtype;
  v_binding jsonb;
  v_origin text;
  v_email text;
  v_auth_confirmed timestamptz;
  v_deleted timestamptz;
  v_banned timestamptz;
  v_company_status text;
  v_company_active boolean;
BEGIN
  IF v_company_id IS NULL OR v_user_id IS NULL OR v_actor_id IS DISTINCT FROM v_user_id
    OR v_invitation_id IS NULL OR v_client_id IS NULL OR v_provider_id IS NULL OR v_key IS NULL
    OR p_command->>'channel' IS DISTINCT FROM 'staff_onboarding'
    OR jsonb_typeof(p_command->'verified_client') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_command->'verified_provider') IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_identity_invalid'; END IF;

  -- Shared staff commands lock company first. Client/provider/Auth updates
  -- cannot invalidate a checked snapshot during the canonical transaction.
  SELECT status,is_active INTO v_company_status,v_company_active FROM public.companies WHERE id=v_company_id FOR NO KEY UPDATE;
  IF NOT FOUND OR v_company_status IS DISTINCT FROM 'active' OR v_company_active IS DISTINCT FROM true
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_company_inactive'; END IF;
  SELECT * INTO v_client FROM public.integration_api_clients
    WHERE id=v_client_id AND company_id=v_company_id FOR SHARE;
  IF NOT FOUND OR v_client.status IS DISTINCT FROM 'active' OR v_client.deleted_at IS NOT NULL OR v_client.revoked_at IS NOT NULL
    OR (v_client.expires_at IS NOT NULL AND v_client.expires_at<=now())
    OR NOT ('staff_users.write'=ANY(coalesce(v_client.scopes,ARRAY[]::text[])))
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_client_invalid'; END IF;
  v_origin := v_client.metadata->>'staff_onboarding_origin';
  IF v_origin IS NULL OR v_origin !~ '^https://([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$'
    OR v_origin ~ '\.(localhost|local|internal|test|invalid)$'
    OR NOT (v_origin=ANY(coalesce(v_client.allowed_origins,ARRAY[]::text[])))
    OR p_command->'verified_client' IS DISTINCT FROM jsonb_build_object(
      'secret_hash',v_client.secret_hash,'scopes',to_jsonb(v_client.scopes),
      'allowed_origins',to_jsonb(v_client.allowed_origins),'staff_onboarding_origin',v_origin)
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_client_changed'; END IF;

  SELECT * INTO v_provider FROM public.tenant_customer_identity_providers
    WHERE id=v_provider_id AND company_id=v_company_id FOR SHARE;
  IF NOT FOUND OR v_provider.purpose IS DISTINCT FROM 'staff' OR NOT coalesce(v_provider.is_active,false)
    OR v_provider.subject_claim IS DISTINCT FROM 'sub' OR v_provider.enforcement IS DISTINCT FROM 'enforce'
    OR p_command->'verified_provider' IS DISTINCT FROM jsonb_build_object(
      'kind',v_provider.kind,'issuer',v_provider.issuer,'audience',v_provider.audience,
      'jwks_uri',v_provider.jwks_uri,'public_jwk',v_provider.public_jwk,
      'subject_claim',v_provider.subject_claim,'enforcement',v_provider.enforcement)
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_provider_changed'; END IF;

  SELECT lower(u.email),u.email_confirmed_at,u.deleted_at,u.banned_until
    INTO v_email,v_auth_confirmed,v_deleted,v_banned FROM auth.users u WHERE u.id=v_user_id FOR SHARE;
  IF NOT FOUND OR v_email IS NULL OR v_auth_confirmed IS NULL OR v_deleted IS NOT NULL
    OR (v_banned IS NOT NULL AND v_banned>now())
    OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=v_user_id AND user_status='active')
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_auth_invalid'; END IF;
  SELECT * INTO v_invitation FROM public.company_invitations
    WHERE id=v_invitation_id AND company_id=v_company_id FOR UPDATE;
  IF NOT FOUND OR v_invitation.invited_user_id IS DISTINCT FROM v_user_id
    OR lower(btrim(v_invitation.email)) IS DISTINCT FROM v_email
    OR v_invitation.status NOT IN ('pending','accepted')
    OR (v_invitation.status='pending' AND (v_invitation.expires_at IS NULL OR v_invitation.expires_at<=now()))
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_invitation_invalid'; END IF;
  SELECT request_payload INTO v_binding FROM public.canonical_command_results
    WHERE company_id=v_company_id AND command_type='tenant.invitation.create'
      AND result_payload->>'invitation_id'=v_invitation_id::text FOR SHARE;
  IF NOT FOUND OR v_binding->>'company_id' IS DISTINCT FROM v_company_id::text
    OR v_binding->>'channel' IS DISTINCT FROM 'staff_api'
    OR v_binding->>'staff_operation' IS DISTINCT FROM 'invite'
    OR v_binding->>'api_client_id' IS DISTINCT FROM v_client_id::text
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='staff_onboarding_invitation_client_mismatch'; END IF;

  -- Only stable canonical authority fields enter the durable request/hash.
  -- Verification snapshots and secrets are never copied into receipts/audits.
  RETURN public.canonical_accept_tenant_invitation(jsonb_build_object(
    'company_id',v_company_id,'invitation_id',v_invitation_id,'user_id',v_user_id,
    'actor_user_id',v_user_id,'idempotency_key',v_key,
    'channel','staff_onboarding','api_client_id',v_client_id));
END;
$_$;

--
-- Name: FUNCTION gridex_accept_staff_invitation_v1(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_accept_staff_invitation_v1(p_command jsonb) IS 'Independent staff onboarding: verified Prod Auth and signed provider proof are checked by the API; locked native client/provider/invitation authority is checked before unchanged canonical acceptance. Service-only.';

--
-- Name: gridex_acquire_automation_lock(text, uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_acquire_automation_lock(p_lock_key text, p_lock_token uuid, p_company_id uuid DEFAULT NULL::uuid, p_ttl_seconds integer DEFAULT 3600, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz;
begin
  if nullif(btrim(p_lock_key), '') is null or p_lock_token is null then
    raise exception 'lock_key_and_token_required' using errcode = '22023';
  end if;
  if p_ttl_seconds < 30 or p_ttl_seconds > 86400 then
    raise exception 'lock_ttl_out_of_range' using errcode = '22023';
  end if;
  v_expires := v_now + make_interval(secs => p_ttl_seconds);

  delete from public.automation_locks where expires_at <= v_now;
  insert into public.automation_locks(lock_key, company_id, lock_token, locked_at, expires_at, metadata)
  values (btrim(p_lock_key), p_company_id, p_lock_token, v_now, v_expires, coalesce(p_metadata, '{}'::jsonb))
  on conflict (lock_key) do nothing;
  return found;
end;
$$;

--
-- Name: gridex_actor_has_company_permission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (p_actor_user_id is not null AND EXISTS(SELECT FROM public.permissions catalog WHERE catalog.key=p_permission AND catalog.is_active) and p_company_id is not null
  and exists(
    select 1 from auth.users u
    where u.id = p_actor_user_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= clock_timestamp())
  )
  and (
    exists(
      select 1 from public.admin_users au
      where au.user_id = p_actor_user_id
        and coalesce(au.is_active, true)
        and lower(coalesce(au.role, '')) in ('super_admin', 'superadmin', 'platform_superadmin')
    )
    or exists(
      select 1
      from public.user_roles ur left join public.roles r on r.id = ur.role_id
      where ur.user_id = p_actor_user_id and ur.company_id is null
        and coalesce(ur.status, 'active') = 'active' and coalesce(ur.is_active, true)
        and lower(coalesce(ur.role, r.key, r.name, '')) in ('super_admin', 'superadmin', 'platform_superadmin')
    )
    or (
      exists(
        select 1 from public.company_memberships cm
        join public.companies c on c.id = cm.company_id
        where cm.user_id = p_actor_user_id and cm.company_id = p_company_id
          and coalesce(cm.status, 'active') = 'active' and coalesce(cm.is_active, true)
          and coalesce(c.is_active, true)
          and coalesce(c.status, 'active') not in ('archived', 'suspended', 'pending_deletion', 'deleted')
      )
      and p_permission = any(
        public.gridex_get_user_permissions_in_company(p_actor_user_id, p_company_id)
      )
    )
  )
  ) and not exists(
    select 1 from public.user_permissions d left join public.permissions p on p.id=d.permission_id
    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)
      and d.is_active and d.status='active' and d.effect='deny'
      and coalesce(nullif(d.permission_key,''),p.key)=p_permission
  ) and not exists(
    select 1 from public.user_permission_overrides d
    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)
      and d.is_active and d.effect='deny' and d.permission_key=p_permission
      and (d.valid_from is null or d.valid_from<=clock_timestamp()) and (d.valid_to is null or clock_timestamp()<d.valid_to)
  )
$$;

--
-- Name: FUNCTION gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text) IS 'F-17: resolves the permission in the company being asked about. Backs the storage policies on customer documents.';

--
-- Name: gridex_actor_readiness_backfill(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_actor_readiness_backfill(p_run_type text DEFAULT 'nightly_backfill'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_actors int := 0;
  v_routes int := 0;
  v_certs jsonb;
begin
  insert into public.platform_actor_readiness_runs(run_type, status, metadata)
  values (coalesce(p_run_type, 'nightly_backfill'), 'running', jsonb_build_object('source', 'gridex_actor_readiness_backfill'))
  returning id into v_run_id;

  update public.platform_actor_identifiers i
  set is_verified = true,
      metadata = coalesce(i.metadata, '{}'::jsonb) || jsonb_build_object('auto_verified_from_registry_at', now(), 'auto_readiness_run_id', v_run_id),
      updated_at = now()
  where i.identifier_type in ('EdielId','EIC','SvKId','OrgNo')
    and coalesce(i.source, '') in ('companies_xml','xml_actor_registry','xml_import','svk_esett_actor_registry_match')
    and coalesce(i.is_verified, false) = false;

  update public.platform_market_actors a
  set status = 'active',
      match_status = case when exists (
        select 1 from public.platform_actor_identifiers i
        where i.actor_id = a.id and i.identifier_type in ('EdielId','EIC','SvKId') and i.is_verified = true
      ) then 'verified' else a.match_status end,
      visible_to_tenants = case when exists (
        select 1 from public.platform_actor_roles r
        where r.actor_id = a.id and r.actor_role in ('grid_owner','electricity_supplier') and r.is_active = true
      ) then true else a.visible_to_tenants end,
      verified_at = case when a.verified_at is null and exists (
        select 1 from public.platform_actor_identifiers i
        where i.actor_id = a.id and i.identifier_type in ('EdielId','EIC','SvKId') and i.is_verified = true
      ) then now() else a.verified_at end,
      metadata = coalesce(a.metadata, '{}'::jsonb) || jsonb_build_object('auto_readiness_backfilled_at', now(), 'auto_readiness_run_id', v_run_id),
      updated_at = now()
  where a.status in ('active','needs_review')
    and exists (select 1 from public.platform_actor_roles r where r.actor_id = a.id and r.is_active = true);

  get diagnostics v_actors = row_count;

  update public.platform_actor_routes r
  set status = 'active',
      is_verified = true,
      auto_send_allowed = false,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'verification_status', 'auto_verified_from_actor_registry',
        'auto_readiness_checked_at', now(),
        'auto_readiness_run_id', v_run_id,
        'auto_send_policy', 'requires_send_readiness_before_enable'
      ),
      updated_at = now()
  from public.platform_actor_identifiers i
  where i.actor_id = r.actor_id
    and i.identifier_type = 'EdielId'
    and i.is_verified = true
    and r.status in ('needs_review','active')
    and coalesce(r.is_verified, false) = false
    and upper(r.message_family) in ('PRODAT','UTILTS')
    and r.environment in ('test','production')
    and upper(coalesce(r.communication_type, 'SMTP')) = 'SMTP'
    and nullif(trim(coalesce(r.communication_address, '')), '') is not null
    and r.party_id = i.identifier_value
    and r.interchange_party_id = i.identifier_value
    and (r.valid_to is null or r.valid_to >= current_date);

  get diagnostics v_routes = row_count;

  v_certs := public.gridex_refresh_actor_certificate_statuses('certificate_refresh');
  perform public.gridex_apply_actor_auto_send_readiness(v_run_id);

  update public.platform_actor_readiness_runs
  set status = 'completed', finished_at = now(), checked_actor_count = v_actors, checked_route_count = v_routes,
      metadata = metadata || jsonb_build_object('cert_refresh', v_certs)
  where id = v_run_id;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'actors_backfilled', v_actors, 'routes_verified', v_routes, 'cert_refresh', v_certs);
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_address_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_address_complete(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_country text := coalesce(p_value->>'country_code', '');
  v_postal text := coalesce(p_value->>'postal_code', '');
begin
  if length(btrim(coalesce(p_value->>'address_line_1', ''))) < 3
     or length(btrim(coalesce(p_value->>'city', ''))) < 2
     or v_country !~ '^[A-Z]{2}$' then
    return false;
  end if;
  if v_country = 'SE' then
    return v_postal ~ '^[0-9]{3} [0-9]{2}$';
  end if;
  return length(btrim(v_postal)) between 2 and 16;
end
$_$;

--
-- Name: gridex_address_is_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_address_is_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gridex_address_complete(coalesce(p_value, '{}'::jsonb))
$$;

--
-- Name: gridex_new_external_tenant_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_new_external_tenant_reference() RETURNS text
    LANGUAGE sql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select 'tenant_'
    || replace(gen_random_uuid()::text, '-', '')
    || substr(replace(gen_random_uuid()::text, '-', ''), 1, 4)
$$;

--
-- Name: gridex_normalize_facility_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_facility_id(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select nullif(upper(regexp_replace(coalesce(p_value, ''), '[^A-Za-z0-9]', '', 'g')), '')
$$;

--
-- Name: gridex_normalize_metering_point_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_metering_point_id(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select nullif(upper(regexp_replace(coalesce(p_value, ''), '[^A-Za-z0-9]', '', 'g')), '')
$$;

