    CONSTRAINT companies_ediel_route_resolution_mode_chk CHECK ((ediel_route_resolution_mode = ANY (ARRAY['automatic'::text, 'manual_review_required'::text, 'disabled'::text]))),
    CONSTRAINT companies_ediel_shared_transport_mode_chk CHECK ((ediel_shared_transport_mode = ANY (ARRAY['shared_platform_mailbox'::text, 'company_specific_mailbox'::text, 'disabled'::text]))),
