    CONSTRAINT companies_operating_environment_check CHECK ((operating_environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT companies_outbound_frozen_channels_check CHECK ((outbound_frozen_channels <@ ARRAY['ediel'::text, 'manual_email'::text, 'customer_email'::text, 'invoice_export'::text, 'webhook'::text])),
    CONSTRAINT companies_status_check CHECK ((status = ANY (ARRAY['active'::text, 'onboarding'::text, 'paused'::text, 'suspended'::text, 'closed'::text, 'archived'::text, 'pending_deletion'::text, 'deleted_test_only'::text])))
