--
-- Name: gridex_route_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_route_readiness_v WITH (security_invoker='true') AS
 WITH required_families AS (
         SELECT x.actor_role,
            x.message_family,
            x.requirement_level
           FROM ( VALUES ('grid_owner'::text,'PRODAT'::text,'critical'::text), ('grid_owner'::text,'UTILTS'::text,'recommended'::text), ('electricity_supplier'::text,'CONTACT'::text,'optional'::text), ('supplier'::text,'CONTACT'::text,'optional'::text), ('system_supplier'::text,'NONE'::text,'not_required'::text)) x(actor_role, message_family, requirement_level)
        ), actor_roles AS (
         SELECT a.id AS actor_id,
            a.name,
            a.legal_name,
            a.org_number,
            a.status AS actor_status,
            a.match_status,
            a.visible_to_tenants,
            r.actor_role
           FROM (public.platform_market_actors a
             JOIN public.platform_actor_roles r ON (((r.actor_id = a.id) AND (r.is_active = true))))
        ), expected AS (
         SELECT ar.actor_id,
            ar.name,
            ar.legal_name,
            ar.org_number,
            ar.actor_status,
            ar.match_status,
            ar.visible_to_tenants,
            ar.actor_role,
            rf.message_family,
            rf.requirement_level
           FROM (actor_roles ar
             JOIN required_families rf ON ((rf.actor_role = ar.actor_role)))
        ), route_match AS (
         SELECT DISTINCT ON (e_1.actor_id, e_1.actor_role, e_1.message_family) e_1.actor_id,
            e_1.actor_role,
            e_1.message_family,
            pr.id AS route_id,
            pr.application_reference,
            pr.environment,
            pr.subaddress,
            pr.communication_type,
            pr.communication_address,
            pr.edi_charset,
            pr.edi_syntax,
            pr.party_id,
            pr.interchange_party_id,
            pr.requires_poa,
            pr.is_verified,
            pr.auto_send_allowed,
            pr.status AS route_status,
            pr.source AS route_source,
            pr.updated_at AS route_updated_at
           FROM (expected e_1
             LEFT JOIN public.platform_actor_routes pr ON (((pr.actor_id = e_1.actor_id) AND ((upper(pr.message_family) = e_1.message_family) OR ((e_1.message_family = 'CONTACT'::text) AND (upper(COALESCE(pr.message_family, ''::text)) = ANY (ARRAY['CONTACT'::text, 'MAIL'::text, 'EMAIL'::text])))))))
          ORDER BY e_1.actor_id, e_1.actor_role, e_1.message_family,
                CASE
                    WHEN (pr.status = 'active'::text) THEN 0
                    ELSE 1
                END,
                CASE
                    WHEN pr.is_verified THEN 0
                    ELSE 1
                END, pr.updated_at DESC NULLS LAST
        )
 SELECT COALESCE(rm.route_id, e.actor_id) AS id,
    e.actor_id,
    e.name AS actor_name,
    e.legal_name,
    e.org_number,
    e.actor_status,
    e.match_status,
    e.visible_to_tenants,
    e.actor_role,
    e.message_family,
    e.requirement_level,
    rm.route_id,
    rm.application_reference,
    rm.environment,
    rm.subaddress,
    rm.communication_type,
    rm.communication_address,
    rm.edi_charset,
    rm.edi_syntax,
    rm.party_id,
    rm.interchange_party_id,
    rm.requires_poa,
    COALESCE(rm.is_verified, false) AS is_verified,
    COALESCE(rm.auto_send_allowed, false) AS auto_send_allowed,
    rm.route_status,
    rm.route_source,
    rm.route_updated_at,
        CASE
            WHEN (e.requirement_level = 'not_required'::text) THEN 'not_required'::text
            WHEN ((rm.route_id IS NULL) AND (e.actor_role = 'grid_owner'::text) AND (e.message_family = 'PRODAT'::text)) THEN 'critical_missing_route'::text
            WHEN ((rm.route_id IS NULL) AND (e.actor_role = 'grid_owner'::text) AND (e.message_family = 'UTILTS'::text)) THEN 'recommended_missing_route'::text
            WHEN (rm.route_id IS NULL) THEN 'optional_missing_route'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rm.communication_address, ''::text)), ''::text) IS NULL) THEN 'not_sendable'::text
            WHEN ((COALESCE(rm.is_verified, false) = false) OR (COALESCE(rm.route_status, 'needs_review'::text) <> 'active'::text)) THEN 'needs_review'::text
            WHEN COALESCE(rm.auto_send_allowed, false) THEN 'ready_auto_send_allowed'::text
            ELSE 'ready_verified_manual_send'::text
        END AS readiness_status,
        CASE
            WHEN ((rm.route_id IS NULL) AND (e.actor_role = 'grid_owner'::text) AND (e.message_family = 'PRODAT'::text)) THEN 'Lägg in och verifiera PRODAT-route innan leverantörsbyte/anläggningsdata skickas.'::text
            WHEN ((rm.route_id IS NULL) AND (e.actor_role = 'grid_owner'::text) AND (e.message_family = 'UTILTS'::text)) THEN 'Komplettera UTILTS-route innan automatiserade mätvärdesflöden används.'::text
            WHEN (rm.route_id IS NULL) THEN 'Skapa kontaktväg eller markera aktören som contact-only/not required.'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rm.communication_address, ''::text)), ''::text) IS NULL) THEN 'Komplettera kommunikationsadress innan sändning.'::text
            WHEN ((COALESCE(rm.is_verified, false) = false) OR (COALESCE(rm.route_status, 'needs_review'::text) <> 'active'::text)) THEN 'Verifiera route. Auto-send slås inte på automatiskt.'::text
            WHEN COALESCE(rm.auto_send_allowed, false) THEN 'Autosändning är tillåten. Kontrollera audit/readiness.'::text
            ELSE 'Verifierad för manuell sändning. Auto-send är medvetet av.'::text
        END AS next_step
   FROM (expected e
     LEFT JOIN route_match rm ON (((rm.actor_id = e.actor_id) AND (rm.actor_role = e.actor_role) AND (rm.message_family = e.message_family))));

