--
-- Name: gridex_ai_list_import_company_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ai_list_import_company_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner uuid;
BEGIN
 SELECT m.company_id INTO owner FROM public.ediel_messages m WHERE m.id=NEW.source_ediel_message_id;
 IF owner IS NULL OR NEW.company_id IS DISTINCT FROM owner THEN RAISE EXCEPTION 'ai_list_import_tenant_mismatch' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;

--
-- Name: gridex_ai_outbound_origin_status_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ai_outbound_origin_status_v1(p_company_id uuid, p_actor_user_id uuid, p_intent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_ai_processing.outbound_origins%rowtype;b gridex_ai_processing.outbound_origin_bindings%rowtype;i public.ediel_message_intents%rowtype;m public.ediel_messages%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_list_origination_service_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_ai_processing.authorize_original_actor_v1(p_company_id,p_actor_user_id);
 -- A bound message is locked before the intent, matching current provider
 -- entry. Immutable bindings discover that exact row without a latest lookup.
 SELECT * INTO b FROM gridex_ai_processing.outbound_origin_bindings WHERE intent_id=p_intent_id AND company_id=p_company_id;
 IF FOUND THEN SELECT * INTO m FROM public.ediel_messages WHERE id=b.message_id AND company_id=p_company_id FOR SHARE;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_validated_technical_intent_required';END IF;
 SELECT * INTO o FROM gridex_ai_processing.outbound_origins WHERE intent_id=i.id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND THEN
  PERFORM gridex_ai_processing.require_export_decision_for_intent_v1(p_company_id,p_actor_user_id,p_intent_id);
  RETURN jsonb_build_object('status','new');
 END IF;
 PERFORM gridex_ai_processing.authorize_original_read_v1(p_company_id,p_actor_user_id);
 IF o.environment IS DISTINCT FROM i.environment OR o.operation_id IS DISTINCT FROM i.operation_id OR o.intent_basis IS DISTINCT FROM gridex_ai_processing.intent_basis_v1(i)
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ai_list_private_original_conflict';END IF;
 SELECT * INTO b FROM gridex_ai_processing.outbound_origin_bindings WHERE intent_id=i.id AND company_id=p_company_id FOR SHARE;
 IF FOUND THEN
  IF m.id IS DISTINCT FROM b.message_id OR b.payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.raw_payload IS DISTINCT FROM o.raw_payload
   OR m.intent_id IS DISTINCT FROM i.id OR m.environment IS DISTINCT FROM i.environment OR m.source_operation_id IS DISTINCT FROM i.operation_id::text OR m.sender_ediel_id IS DISTINCT FROM i.sender_ediel_id OR m.receiver_ediel_id IS DISTINCT FROM i.receiver_ediel_id
   OR m.customer_id IS DISTINCT FROM i.customer_id OR m.site_id IS DISTINCT FROM i.customer_site_id OR m.communication_route_id IS DISTINCT FROM i.communication_route_id OR m.route_profile_id IS DISTINCT FROM i.route_profile_id THEN RAISE EXCEPTION 'ai_list_private_original_conflict';END IF;
  RETURN jsonb_build_object('status','bound','messageId',b.message_id,'payloadHash',o.payload_hash);
 END IF;
 -- Immutable own original first: no current legal/route/guide/purpose reselect
 -- can rewrite this stored raw/name/party binding. A NEW INSERT/send still
 -- passes its existing phase-specific protected original/current source gate.
 RETURN jsonb_build_object('status','original','rawPayload',o.raw_payload,'fileName',o.file_name,'mimeType',o.mime_type,'payloadHash',o.payload_hash);
END$$;

--
-- Name: gridex_ai_prepare_outbound_original_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ai_prepare_outbound_original_v1(p_company_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_draft_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_list_origination_service_required' USING ERRCODE='42501'; END IF;
 IF p_draft_text IS NULL OR octet_length(p_draft_text)>23068672 THEN RAISE EXCEPTION 'ai_list_original_draft_resource_bound'; END IF;
 RETURN gridex_ai_processing.require_original_draft_v1(p_company_id,p_actor_user_id,p_intent_id,p_draft_text::jsonb);
END $$;

--
-- Name: gridex_ai_record_outbound_original_v1(uuid, uuid, uuid, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ai_record_outbound_original_v1(p_company_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_snapshot_id uuid, p_readset_hash text, p_raw_payload text, p_file_name text, p_mime_type text, p_row_sources text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE i public.ediel_message_intents%rowtype;snap gridex_received_sources.object_selection_snapshots%rowtype;
 prior gridex_ai_processing.outbound_origins%rowtype;wire jsonb;decision jsonb;basis jsonb;source_ids jsonb;header text;point uuid;row_sources jsonb;customer_history jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_list_origination_service_required' USING ERRCODE='42501'; END IF;
 PERFORM gridex_ai_processing.authorize_original_actor_v1(p_company_id,p_actor_user_id);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_validated_technical_intent_required';END IF;

 SELECT * INTO prior FROM gridex_ai_processing.outbound_origins WHERE intent_id=i.id;
 IF FOUND THEN
  PERFORM gridex_ai_processing.authorize_original_read_v1(p_company_id,p_actor_user_id);
  IF prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM i.environment OR prior.operation_id IS DISTINCT FROM i.operation_id OR prior.intent_basis IS DISTINCT FROM gridex_ai_processing.intent_basis_v1(i) OR prior.raw_payload IS DISTINCT FROM p_raw_payload OR prior.file_name IS DISTINCT FROM p_file_name OR prior.mime_type IS DISTINCT FROM p_mime_type OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(p_raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'ai_list_original_conflict'; END IF;
  RETURN jsonb_build_object('status','original','payloadHash',prior.payload_hash);
 END IF;
 i:=gridex_ai_processing.intent_request_v1(p_company_id,p_intent_id);
 decision:=gridex_ai_processing.require_export_decision_for_intent_v1(p_company_id,p_actor_user_id,p_intent_id);
 basis:=gridex_ai_processing.party_source_v1(p_company_id,i.id);
 wire:=gridex_ai_processing.require_party_wire_v1(p_raw_payload,basis);

 header:=split_part(replace(p_raw_payload,E'\r\n',E'\n'),E'\n',1);
 IF split_part(header,';',8) IS DISTINCT FROM replace(i.payload->>'fromDate','-','') OR split_part(header,';',9) IS DISTINCT FROM replace(i.payload->>'toDate','-','') THEN RAISE EXCEPTION 'ai_list_original_search_scope_mismatch'; END IF;
 IF p_file_name IS NULL OR lower(p_file_name) NOT LIKE '%.csv' OR p_mime_type IS NULL OR p_mime_type!~* '^text/csv([ \t]*;[ \t]*charset[ \t]*=[ \t]*(utf-8|"utf-8"))?[ \t]*$' THEN RAISE EXCEPTION 'ai_list_csv_file_type_required'; END IF;

 -- A source-owned persisted COMPLETE snapshot, not a caller serialized history.
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots WHERE id=p_snapshot_id AND company_id=p_company_id AND environment=i.environment AND readset_hash=p_readset_hash FOR SHARE;
 IF NOT FOUND OR snap.readset_hash IS DISTINCT FROM encode(sha256(convert_to(snap.readset_text,'UTF8')),'hex') OR snap.cutoff_at<i.created_at
  OR snap.readset_text::jsonb->>'complete' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'ai_list_original_complete_history_snapshot_required'; END IF;
 -- First acquire source-owned customer epochs and the normal supply owner's
 -- source/period locks; tenant site/point equality is checked after those locks.
 customer_history:=gridex_ai_processing.customer_history_for_rows_v1(snap.readset_text::jsonb,snap.cutoff_at,i,p_raw_payload,p_row_sources);
 row_sources:=gridex_ai_processing.require_original_row_sources_v1(snap.readset_text::jsonb,snap.cutoff_at,i,p_raw_payload,p_row_sources);
 PERFORM cs.id FROM public.customer_sites cs WHERE cs.id=i.customer_site_id AND cs.company_id=p_company_id AND cs.customer_id=i.customer_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_customer_site_scope_mismatch'; END IF;
 IF nullif(i.metering_point_id,'') IS NOT NULL THEN
  point:=i.metering_point_id::uuid;
  PERFORM mp.id FROM public.metering_points mp WHERE mp.id=point AND mp.company_id=p_company_id AND mp.customer_id=i.customer_id AND coalesce(mp.customer_site_id,mp.site_id)=i.customer_site_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ai_list_metering_point_scope_mismatch'; END IF;
 END IF;
 -- References below have already passed own original/hash/leaf/cell/period
 -- equality. Earlier superseded accepted markers cannot enter this provenance.
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO source_ids FROM (
  SELECT DISTINCT ref->>key AS id FROM jsonb_array_elements(row_sources) ref,
   unnest(ARRAY['sourceMessageId','baselineSourceMessageId','addressSourceMessageId']) key
  UNION SELECT p->>'sourceMessageId' FROM jsonb_array_elements(customer_history->'patches') p
 ) ids;
 INSERT INTO gridex_ai_processing.outbound_origins(intent_id,company_id,environment,actor_user_id,processing_decision_id,snapshot_id,readset_hash,raw_payload,payload_hash,file_name,mime_type,header_basis,source_ids,row_sources,customer_history_basis)
 VALUES(i.id,p_company_id,i.environment,p_actor_user_id,(decision#>>'{decision,id}')::uuid,snap.id,snap.readset_hash,p_raw_payload,encode(sha256(convert_to(p_raw_payload,'UTF8')),'hex'),p_file_name,p_mime_type,basis,source_ids,row_sources,customer_history);
 RETURN jsonb_build_object('status','original','payloadHash',encode(sha256(convert_to(p_raw_payload,'UTF8')),'hex'));
END $_$;

--
-- Name: gridex_analytics_point_month_internal(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_analytics_point_month_internal(p_company_id uuid, p_month date) RETURNS TABLE(metering_point_id uuid, customer_id uuid, grid_owner_id uuid, bidding_zone_code text, kwh numeric, value_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return query
  select mp.id, mp.customer_id, mp.grid_owner_id, upper(nullif(trim(mp.bidding_zone_code), '')),
         coalesce(r.kwh, 0), coalesce(r.value_count, 0)
  from public.metering_points mp
  left join public.metering_point_monthly_consumption r
    on r.company_id = p_company_id and r.metering_point_id = mp.id
   and r.month = date_trunc('month', p_month)::date
  where mp.company_id = p_company_id;
end;
$$;

--
-- Name: gridex_anonymize_customer_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_anonymize_customer_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_customer public.customers%rowtype;
  v_retention_until date;
  v_label text := 'Anonymiserad kund';
  p_today date := current_date;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_anonymize_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_actor_user_id is null then
    raise exception using errcode = '22023', message = 'customer_anonymize_payload_invalid';
  end if;

  select * into v_customer
  from public.customers
  where id = p_customer_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;

  if v_customer.anonymized_at is not null then
    return jsonb_build_object('already_anonymized', true, 'anonymized_at', v_customer.anonymized_at);
  end if;
  if v_customer.legal_hold then
    raise exception using errcode = '23514', message = 'customer_anonymize_legal_hold',
      detail = coalesce(v_customer.legal_hold_reason, '');
  end if;
  if v_customer.status not in ('archived', 'moved', 'inactive', 'terminated') then
    raise exception using errcode = '23514', message = 'customer_anonymize_customer_still_active';
  end if;
  if exists (
    select 1 from public.customer_supply_periods p
    where p.customer_id = p_customer_id
      and p.status in ('active', 'confirmed_by_grid_owner')
      and (coalesce(p.actual_end_date, p.end_date) is null or coalesce(p.actual_end_date, p.end_date) >= p_today)
  ) then
    raise exception using errcode = '23514', message = 'customer_anonymize_supply_ongoing';
  end if;
  if exists (
    select 1 from public.customer_invoices i
    where i.customer_id = p_customer_id
      and i.status in ('draft', 'issued', 'sent', 'overdue', 'failed')
  ) then
    raise exception using errcode = '23514', message = 'customer_anonymize_unsettled_invoices';
  end if;

  v_retention_until := public.gridex_customer_retention_until_v1(p_customer_id);
  if v_retention_until is not null and p_today < v_retention_until then
    raise exception using errcode = '23514', message = 'customer_anonymize_retention_period_active',
      detail = v_retention_until::text;
  end if;

  update public.customers
  set first_name = null,
      last_name = null,
      full_name = v_label,
      name = v_label,
      company_name = case when company_name is null then null else v_label end,
      personal_number = null,
      identity_number = null,
      org_number = null,
      organization_number = null,
      email = null,
      invoice_email = null,
      phone = null,
      apartment_number = null,
      billing_street = null,
      billing_postal_code = null,
      billing_city = null,
      anonymized_at = now(),
      anonymized_by = p_actor_user_id,
      data_retention_note = 'Personuppgifter anonymiserade efter utgången lagringstid (' || v_retention_until::text || ').',
      updated_at = now()
  where id = p_customer_id and company_id = p_company_id;

  update public.customer_contacts
  set name = null, email = null, phone = null, title = null,
      updated_at = now()
  where customer_id = p_customer_id and company_id = p_company_id;

  update public.customer_addresses
  set street_1 = null, street_2 = null, postal_code = null, city = null, is_active = false,
      updated_at = now()
  where customer_id = p_customer_id and company_id = p_company_id;

  update public.customer_portal_accounts
  set email = null, user_email = null, verified_identity_snapshot = null, is_active = false,
      updated_at = now()
  where customer_id = p_customer_id and company_id = p_company_id;

  update public.customer_internal_notes
  set body = '[Anteckning borttagen vid anonymisering]'
  where customer_id = p_customer_id and company_id = p_company_id;

  insert into public.audit_logs (actor_user_id, company_id, entity_type, entity_id, action, metadata)
  values (
    p_actor_user_id, p_company_id, 'customer', p_customer_id::text, 'customer.anonymized',
    jsonb_build_object(
      'label', 'Anonymiserade kund efter lagringstid',
      'retention_until', v_retention_until,
      'retained', 'Fakturor, avtal, signeringsbevis och Ediel-meddelanden behålls oförändrade.'
    )
  );

  return jsonb_build_object('already_anonymized', false, 'retention_until', v_retention_until);
end
$$;

--
-- Name: gridex_apply_actor_auto_send_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_actor_auto_send_readiness(p_existing_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_enabled int := 0;
  v_disabled int := 0;
begin
  if p_existing_run_id is null then
    insert into public.platform_actor_readiness_runs(run_type, status, metadata)
    values ('auto_send_apply', 'running', jsonb_build_object('source', 'gridex_apply_actor_auto_send_readiness', 'scope', 'electricity_prodat_utilts_no_gas'))
    returning id into v_run_id;
  else
    v_run_id := p_existing_run_id;
  end if;

  update public.platform_actor_routes r
  set auto_send_allowed = true,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'auto_send_enabled_at', now(),
        'auto_send_enabled_by', 'system',
        'auto_send_enabled_reason', 'all_readiness_checks_passed',
        'readiness_run_id', v_run_id,
        'certificate_fingerprint', v.certificate_fingerprint_sha256,
        'auto_send_scope', 'electricity_prodat_utilts_no_gas'
      ),
      updated_at = now()
  from public.platform_actor_send_readiness_v v
  where v.route_id = r.id
    and v.readiness_status = 'ready_for_auto_send'
    and upper(coalesce(v.message_family, '')) in ('PRODAT','UTILTS')
    and upper(coalesce(v.subaddress, '')) <> 'GAS'
    and coalesce(r.auto_send_allowed, false) = false;

  get diagnostics v_enabled = row_count;

  update public.platform_actor_routes r
  set auto_send_allowed = false,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'auto_send_disabled_at', now(),
        'auto_send_disabled_by', 'system',
        'auto_send_disabled_reason', case
          when upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS') then 'message_family_out_of_electricity_auto_send_scope'
          when upper(coalesce(v.subaddress, '')) = 'GAS' then 'gas_route_out_of_electricity_auto_send_scope'
          else 'readiness_not_green'
        end,
        'readiness_run_id', v_run_id,
        'blocking_reasons', v.blocking_reasons,
        'warnings', v.warnings
      ),
      updated_at = now()
  from public.platform_actor_send_readiness_v v
  where v.route_id = r.id
    and coalesce(r.auto_send_allowed, false) = true
    and (
      v.readiness_status <> 'ready_for_auto_send'
      or upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS')
      or upper(coalesce(v.subaddress, '')) = 'GAS'
    );

  get diagnostics v_disabled = row_count;

  insert into public.platform_actor_readiness_checks(run_id, actor_id, route_id, certificate_id, check_type, status, blocking_reasons, warnings, metadata, checked_at, next_check_at)
  select v_run_id, v.actor_id, v.route_id, v.certificate_id, 'auto_send',
         case when v.readiness_status = 'ready_for_auto_send'
                and upper(coalesce(v.message_family, '')) in ('PRODAT','UTILTS')
                and upper(coalesce(v.subaddress, '')) <> 'GAS' then 'passed'
              when cardinality(v.blocking_reasons) > 0 then 'blocking'
              when cardinality(v.warnings) > 0 then 'warning'
              else 'unknown' end,
         case
           when upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS') then array_append(v.blocking_reasons, 'message_family_out_of_electricity_auto_send_scope')
           when upper(coalesce(v.subaddress, '')) = 'GAS' then array_append(v.blocking_reasons, 'gas_route_out_of_electricity_auto_send_scope')
           else v.blocking_reasons
         end,
         v.warnings,
         jsonb_build_object('readiness_status', v.readiness_status, 'message_family', v.message_family, 'environment', v.environment, 'subaddress', v.subaddress, 'auto_send_scope', 'electricity_prodat_utilts_no_gas'),
         now(), v.next_check_at
  from public.platform_actor_send_readiness_v v;

  if p_existing_run_id is null then
    update public.platform_actor_readiness_runs
    set status = 'completed', finished_at = now(), auto_enabled_count = v_enabled, auto_disabled_count = v_disabled,
        metadata = metadata || jsonb_build_object('auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas')
    where id = v_run_id;
  else
    update public.platform_actor_readiness_runs
    set auto_enabled_count = auto_enabled_count + v_enabled,
        auto_disabled_count = auto_disabled_count + v_disabled,
        metadata = metadata || jsonb_build_object('auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas')
    where id = v_run_id;
  end if;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas');
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_apply_billing_export_partner_result(uuid, uuid, uuid[], jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_billing_export_partner_result(p_company_id uuid, p_export_run_id uuid, p_accepted_ids uuid[] DEFAULT '{}'::uuid[], p_rejected jsonb DEFAULT '[]'::jsonb, p_response jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_target_count integer; v_accounted_count integer; v_unknown_count integer; v_rejected_count integer;
begin
  if jsonb_typeof(coalesce(p_rejected,'[]'::jsonb))<>'array' then raise exception using errcode='22023',message='rejected_rows_must_be_array'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_export_run_id::text||':partner-result',0));
  perform 1 from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  select count(*) into v_target_count from public.billing_export_run_items
   where company_id=p_company_id and billing_export_run_id=p_export_run_id and status in ('ready','ready_for_retry') and export_status='queued';
  select count(distinct id) into v_accounted_count from (
    select unnest(coalesce(p_accepted_ids,'{}'::uuid[])) id
    union all
    select nullif(x->>'id','')::uuid from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x
  ) q;
  select count(*) into v_unknown_count from (
    select unnest(coalesce(p_accepted_ids,'{}'::uuid[])) id
    union all select nullif(x->>'id','')::uuid from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x
  ) q where q.id is null or not exists(select 1 from public.billing_export_run_items i where i.id=q.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.status in ('ready','ready_for_retry') and i.export_status='queued');
  if v_unknown_count>0 or v_accounted_count<>v_target_count then raise exception using errcode='23514',message='partner_row_acknowledgement_incomplete_or_unknown'; end if;
  if exists(select 1 from unnest(coalesce(p_accepted_ids,'{}'::uuid[])) a join jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x on nullif(x->>'id','')::uuid=a) then
    raise exception using errcode='23514',message='partner_row_both_accepted_and_rejected';
  end if;
  update public.billing_export_run_items set export_status='sent',partner_result_type='accepted',sent_at=now(),failed_at=null,last_error=null,sent_by=p_actor_user_id,
    partner_response_log=coalesce(partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now()
  where company_id=p_company_id and billing_export_run_id=p_export_run_id and export_status='queued' and id=any(coalesce(p_accepted_ids,'{}'::uuid[]));
  update public.partner_exports p set status='sent',sent_at=now(),failure_reason=null,response_payload=p_response,
    partner_response_log=coalesce(p.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now(),updated_by=p_actor_user_id
  from public.billing_export_run_items i where i.partner_export_id=p.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.id=any(coalesce(p_accepted_ids,'{}'::uuid[]));
  with rejected as (select nullif(x->>'id','')::uuid id,coalesce(nullif(x->>'error',''),'Fakturapartnern avvisade raden.') error from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x)
  update public.billing_export_run_items i set export_status='failed',status='ready_for_retry',
    partner_result_type=case when nullif(p_response->>'error','') is null then 'rejected' else 'transport_failed' end,
    failed_at=now(),last_error=r.error,
    partner_response_log=coalesce(i.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now()
  from rejected r where i.id=r.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.export_status='queued';
  with rejected as (select nullif(x->>'id','')::uuid id,coalesce(nullif(x->>'error',''),'Fakturapartnern avvisade raden.') error from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x)
  update public.partner_exports p set status='failed',failed_at=now(),failure_reason=r.error,response_payload=p_response,
    partner_response_log=coalesce(p.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),retry_count=p.retry_count+1,updated_at=now(),updated_by=p_actor_user_id
  from rejected r, public.billing_export_run_items i
  where i.id=r.id and i.partner_export_id=p.id
    and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id;
  select jsonb_array_length(coalesce(p_rejected,'[]'::jsonb)) into v_rejected_count;
  update public.billing_export_runs set partner_response_log=coalesce(partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now() where id=p_export_run_id and company_id=p_company_id;
  perform public.gridex_refresh_billing_export_run(p_company_id,p_export_run_id);
  return jsonb_build_object('accepted',coalesce(cardinality(p_accepted_ids),0),'rejected',v_rejected_count);
end $$;

--
-- Name: gridex_apply_contract_offer_standard_fees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_contract_offer_standard_fees() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_offer public.contract_offers%rowtype;
begin
  if new.contract_offer_id is null or new.company_id is null then
    return new;
  end if;

  -- Customer-specific/manual pricing is intentional and must not be replaced
  -- by catalog values merely because the original offer reference is retained.
  if coalesce(new.source_type, '') in ('manual', 'manual_override') then
    return new;
  end if;

  select offer.*
    into v_offer
  from public.contract_offers offer
  where offer.id = new.contract_offer_id
    and offer.company_id = new.company_id;

  if not found then
    return new;
  end if;

  new.monthly_fee_sek := v_offer.monthly_fee_sek;
  new.invoice_fee_sek := v_offer.invoice_fee_sek;
  new.green_fee_mode := v_offer.green_fee_mode;
  new.green_fee_value := v_offer.green_fee_value;
  new.discount_value := v_offer.discount_value;
  new.discount_unit := v_offer.discount_unit;
  new.start_fee_sek := v_offer.start_fee_sek;
  new.admin_fee_sek := v_offer.admin_fee_sek;
  new.break_fee_sek := v_offer.break_fee_sek;
  new.vat_rate := v_offer.vat_rate;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_apply_contract_offer_standard_fees(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_apply_contract_offer_standard_fees() IS 'Projects catalog-wide standard fees into a newly bound customer contract without mutating manual overrides or tracking later offer edits.';

--
-- Name: gridex_apply_exact_z02_core(uuid, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_exact_z02_core(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;
 prior gridex_received_sources.z02_core_applications%rowtype;application jsonb;obj jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN
  RAISE EXCEPTION 'z02_source_service_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z02' THEN
  RETURN jsonb_build_object('ok',false,'code','z02_inbound_message_not_found');END IF;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=p_company_id AND environment=m.environment AND message_code='Z02';
 IF s.source_message_id IS NULL OR s.raw_payload IS NULL OR s.raw_payload IS DISTINCT FROM m.raw_payload
  OR s.payload_hash IS DISTINCT FROM m.immutable_payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN
  RETURN jsonb_build_object('ok',false,'code','z02_frozen_source_unavailable');END IF;
 SELECT * INTO prior FROM gridex_received_sources.z02_core_applications WHERE source_message_id=m.id AND request_id=p_request_id;
 IF prior.source_message_id IS NOT NULL AND (prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM m.environment
   OR prior.customer_id IS DISTINCT FROM p_customer_id OR prior.site_id IS DISTINCT FROM p_site_id OR prior.source_payload_hash IS DISTINCT FROM s.payload_hash) THEN
  RETURN jsonb_build_object('ok',false,'code','z02_applied_source_scope_mismatch');END IF;
 -- Fixed history remains confidential. Current READ authorization does not
 -- relabel, replay or apply the old result and does not reselect its rulepack.
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id
  AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'z02_execution_actor_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'z02_execution_actor_required' USING ERRCODE='42501';END IF;
 IF prior.source_message_id IS NOT NULL THEN
  IF NOT(coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.read'),false)
   OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.read'),false)) THEN
   RAISE EXCEPTION 'z02_history_actor_read_required' USING ERRCODE='42501';END IF;
  RETURN prior.result;
 END IF;
 IF public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN
  RAISE EXCEPTION 'z02_execution_actor_required' USING ERRCODE='42501';END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);
 application:=gridex_received_sources.require_prodat_application_objects_v1(p_company_id,m.id);
 IF application->>'headerDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(application->'objects') IS DISTINCT FROM 'array'
  OR jsonb_array_length(application->'objects')=0 THEN RETURN jsonb_build_object('ok',false,'code','z02_own_application_scope_unavailable');END IF;
 -- The legacy whole-source Z02 operation still requires global acceptance.
 -- Its exact own LIN/register correlation is unchanged in the delegate. Full
 -- canonical field-owner acceptance is additionally required, never inferred
 -- from a register-only or ACK-planning facet.
 FOR obj IN SELECT e FROM jsonb_array_elements(application->'objects') e LOOP
  IF gridex_received_sources.prodat_application_object_accepted_v1(p_company_id,m.id,(application->>'assessmentId')::uuid,obj-'applicationDecision'-'reasonCodes') IS DISTINCT FROM true THEN
   RETURN jsonb_build_object('ok',false,'code','z02_own_application_scope_unavailable');END IF;
 END LOOP;
 RETURN gridex_received_sources.gridex_apply_exact_z02_core_before_current_source_v1(p_company_id,p_customer_id,p_site_id,p_request_id,m.id,p_operation_id,p_actor_user_id);
END $$;

--
-- Name: gridex_apply_inbound_ack_source_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_inbound_ack_source_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid, p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'ack_source_service_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_ack_authority.apply_v1(p_company_id,p_environment,p_ack_message_id,p_source_message_id,p_actor_user_id);
END $$;

--
-- Name: gridex_apply_public_contract_backfill_v1(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_public_contract_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_offer_id uuid DEFAULT NULL::uuid, p_publication_version_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(company_id uuid, offer_id uuid, publication_version_id uuid, channel text, action text, applied boolean, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  candidate record;
  result jsonb;
begin
  if p_actor_user_id is null then
    raise exception using errcode='22023',
      message='PUBLICATION_BACKFILL_ACTOR_REQUIRED';
  end if;
  for candidate in
    select * from public.gridex_preview_public_contract_backfill_v1(
      p_company_id,p_offer_id,p_publication_version_id,p_channel
    )
  loop
    if not candidate.safe_to_apply then
      with review as (
        select candidate.company_id company_id,
          coalesce(
            (select pv.price_plan_version_id
              from public.contract_publication_versions pv
              where pv.id=candidate.publication_version_id),
            (select offer.price_plan_version_id
              from public.contract_offers offer
              where offer.id=candidate.offer_id)
          ) price_plan_version_id,
          case when candidate.publication_version_id is null
            then 'contract_offers' else 'contract_publication_versions' end
            source_table,
          coalesce(candidate.publication_version_id,candidate.offer_id)
            source_id,
          coalesce(candidate.manual_review_reason,
            'PUBLICATION_BACKFILL_UNSAFE') reason_code,
          jsonb_build_object('channel',candidate.channel,
            'detected_problem',candidate.detected_problem) details
      )
      insert into public.contract_pricing_migration_reviews(
        company_id,price_plan_version_id,source_table,source_id,
        reason_code,details
      )
      select review.company_id,review.price_plan_version_id,
        review.source_table,review.source_id,review.reason_code,review.details
      from review
      where not exists(
        select 1 from public.contract_pricing_migration_reviews existing
        where existing.company_id=review.company_id
          and existing.price_plan_version_id is not distinct from
            review.price_plan_version_id
          and existing.source_table=review.source_table
          and existing.source_id is not distinct from review.source_id
          and existing.reason_code=review.reason_code
      );
      company_id:=candidate.company_id;offer_id:=candidate.offer_id;
      publication_version_id:=candidate.publication_version_id;
      channel:=candidate.channel;action:='MANUAL_REVIEW';applied:=false;
      details:=jsonb_build_object('reason',candidate.manual_review_reason);
      return next;
      continue;
    end if;

    begin
      -- Restore a reusable template copy only when the published snapshot is
      -- the deterministic source. Commercial values are copied unchanged.
      with version_row as (
        select * from public.contract_publication_versions
        where id=candidate.publication_version_id
      ), inserted as (
        insert into public.contract_price_options(
          company_id,contract_product_version_id,price_plan_version_id,
          contract_publication_version_id,option_reference,option_code,
          customer_name,internal_description,contract_type,binding_months,
          notice_months,auto_renew_enabled,renewal_term_months,valid_from,
          valid_to,earliest_start_date,latest_start_date,status,sort_order,
          version_number,metadata,created_by,customer_type,is_default,
          selection_required
        )
        select source.company_id,source.contract_product_version_id,
          source.price_plan_version_id,null,source.option_reference,
          source.option_code,source.customer_name,source.internal_description,
          source.contract_type,source.binding_months,source.notice_months,
          source.auto_renew_enabled,source.renewal_term_months,
          source.valid_from,source.valid_to,source.earliest_start_date,
          source.latest_start_date,source.status,source.sort_order,
          source.version_number,coalesce(source.metadata,'{}'::jsonb)
            ||jsonb_build_object(
              'restored_from_publication_price_option_id',source.id),
          coalesce(p_actor_user_id,source.created_by),source.customer_type,
          source.is_default,source.selection_required
        from public.contract_price_options source
        join version_row v on v.id=source.contract_publication_version_id
        where not exists(select 1 from public.contract_price_options template
          where template.company_id=source.company_id
            and template.contract_product_version_id=
              source.contract_product_version_id
            and template.price_plan_version_id=source.price_plan_version_id
            and template.contract_publication_version_id is null
            and template.option_reference=source.option_reference
            and template.option_code=source.option_code)
        on conflict do nothing
        returning id,metadata
      )
      insert into public.contract_price_option_area_prices(
        company_id,contract_price_option_id,price_plan_version_id,
        price_row_reference,price_area,amount,unit,vat_treatment,
        valid_from,valid_to,metadata,created_by,status
      )
      select template.company_id,template.id,template.price_plan_version_id,
        area.price_row_reference,area.price_area,area.amount,area.unit,
        area.vat_treatment,area.valid_from,area.valid_to,
        coalesce(area.metadata,'{}'::jsonb)||jsonb_build_object(
          'restored_from_area_price_id',area.id),
        coalesce(p_actor_user_id,area.created_by),area.status
      from inserted template
      join public.contract_price_option_area_prices area
        on area.contract_price_option_id=
          (template.metadata->>'restored_from_publication_price_option_id')::uuid
      on conflict(contract_price_option_id,price_area) do nothing;

      result:=public.gridex_finalize_contract_publication_v1(
        candidate.publication_version_id,p_actor_user_id,true
      );
      company_id:=candidate.company_id;offer_id:=candidate.offer_id;
      publication_version_id:=candidate.publication_version_id;
      channel:=candidate.channel;action:=candidate.proposed_action;
      applied:=true;details:=result;
    exception
      when sqlstate '23503' or sqlstate '23505' or sqlstate '23514'
        or sqlstate '55000' or sqlstate 'P0001' or sqlstate 'P0002' then
        insert into public.contract_pricing_migration_reviews(
          company_id,price_plan_version_id,source_table,source_id,
          reason_code,details
        )
        select candidate.company_id,pv.price_plan_version_id,
          'contract_publication_versions',candidate.publication_version_id,
          'PUBLICATION_BACKFILL_APPLY_BLOCKED',
          jsonb_build_object('channel',candidate.channel,
            'sqlstate',sqlstate,'message',sqlerrm)
        from public.contract_publication_versions pv
        where pv.id=candidate.publication_version_id
        on conflict do nothing;
        company_id:=candidate.company_id;offer_id:=candidate.offer_id;
        publication_version_id:=candidate.publication_version_id;
        channel:=candidate.channel;action:='MANUAL_REVIEW';applied:=false;
        details:=jsonb_build_object('reason','APPLY_VALIDATION_FAILED',
          'sqlstate',sqlstate,'message',sqlerrm);
    end;
    return next;
  end loop;
end $$;

--
-- Name: gridex_apply_public_contract_legal_backfill_v1(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  candidate record;
  scanned_count bigint:=0;
  already_valid_count bigint:=0;
  backfilled_count bigint:=0;
  ambiguous_count bigint:=0;
  missing_source_count bigint:=0;
  blocked_count bigint:=0;
  failed_count bigint:=0;
  v_snapshot jsonb;
  v_before_snapshot jsonb;
  v_before_hash text;
  v_after_hash text;
  failure_details jsonb:='[]'::jsonb;
begin
  for candidate in
    select * from public.gridex_preview_public_contract_legal_backfill_v1(
      p_company_id
    )
  loop
    scanned_count:=scanned_count+1;
    if candidate.category='already_valid' then
      already_valid_count:=already_valid_count+1;
    elsif candidate.category='missing_source' then
      missing_source_count:=missing_source_count+1;
    elsif candidate.category='blocked' then
      blocked_count:=blocked_count+1;
    elsif candidate.category='backfillable' then
      if p_dry_run then
        backfilled_count:=backfilled_count+1;
      else
        begin
          v_snapshot:=public.gridex_publication_legal_snapshot_json_v1(
            candidate.company_id,candidate.legal_bundle_version_id
          );
          if v_snapshot is null then
            missing_source_count:=missing_source_count+1;
          else
            select pv.publication_snapshot,pv.content_sha256
              into v_before_snapshot,v_before_hash
            from public.contract_publication_versions pv
            where pv.id=candidate.publication_version_id
            for update;
            v_after_hash:=encode(extensions.digest(
              jsonb_set(coalesce(v_before_snapshot,'{}'::jsonb),
                '{legal_snapshot}',v_snapshot,true)::text,'sha256'
            ),'hex');
            perform set_config('gridex.version_transition','on',true);
            perform set_config('gridex.publication_graph_repair','on',true);
            update public.contract_publication_versions pv
            set publication_snapshot=jsonb_set(
                  coalesce(v_before_snapshot,'{}'::jsonb),
                  '{legal_snapshot}',v_snapshot,true
                ),
                content_sha256=v_after_hash
            where pv.id=candidate.publication_version_id;
            perform set_config('gridex.publication_graph_repair','off',true);
            insert into public.audit_logs(
              company_id,actor_user_id,entity_type,entity_id,action,
              old_values,new_values,metadata
            ) values(
              candidate.company_id,p_actor_user_id,
              'contract_publication_version',
              candidate.publication_version_id::text,
              'public_contract_legal_snapshot_backfilled',
              jsonb_build_object(
                'content_sha256',v_before_hash,
                'legal_snapshot',v_before_snapshot->'legal_snapshot'
              ),
              jsonb_build_object(
                'content_sha256',v_after_hash,
                'legal_snapshot',v_snapshot
              ),
              jsonb_build_object(
                'derivation_method',candidate.derivation_method,
                'commercial_values_changed',false,
                'contract_schema_version','2026-08-01.1'
              )
            );
            backfilled_count:=backfilled_count+1;
          end if;
        exception when others then
          perform set_config('gridex.publication_graph_repair','off',true);
          failed_count:=failed_count+1;
          failure_details:=failure_details||jsonb_build_array(jsonb_build_object(
            'publication_version_id',candidate.publication_version_id,
            'sqlstate',sqlstate,
            'message',sqlerrm
          ));
        end;
      end if;
    else
      ambiguous_count:=ambiguous_count+1;
    end if;
  end loop;
  return jsonb_build_object(
    'dry_run',p_dry_run,
    'scanned',scanned_count,
    'already_valid',already_valid_count,
    'backfilled',backfilled_count,
    'ambiguous',ambiguous_count,
    'missing_source',missing_source_count,
    'blocked',blocked_count,
    'failed',failed_count,
    'failure_details',failure_details
  );
end $$;

--
-- Name: FUNCTION gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid, p_dry_run boolean, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid, p_dry_run boolean, p_actor_user_id uuid) IS 'Idempotent exact-relation legal snapshot backfill. Never selects first/latest bundle version.';

--
-- Name: gridex_approve_first_production_send(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_approve_first_production_send(p_company_id uuid, p_actor_setting_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.ediel_actor_settings
  set
    first_production_send_approved = true,
    production_send_lock_enabled = false,
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'production_send_approved_by', p_actor_user_id,
      'production_send_approved_at', now(),
      'production_send_approval_reason', coalesce(p_reason, 'Första produktionssändningen godkänd av platform admin.')
    )
  where company_id = p_company_id
    and environment = 'production'
    and is_active = true
    and (p_actor_setting_id is null or id = p_actor_setting_id);

  insert into public.ediel_production_send_approvals(
    company_id,
    actor_setting_id,
    environment,
    status,
    approved_by,
    reason,
    metadata
  ) values (
    p_company_id,
    p_actor_setting_id,
    'production',
    'approved',
    p_actor_user_id,
    p_reason,
    jsonb_build_object('source', 'gridex_approve_first_production_send')
  );
end;
$$;

--
-- Name: gridex_approve_invoice_test_item_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_approve_invoice_test_item_v1(p_company_id uuid, p_invoice_export_item_id uuid, p_approval jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_now timestamptz := now();
  v_item_id uuid;
  v_invoice_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'invoice_test_approval_service_role_required';
  end if;
  if p_company_id is null or p_invoice_export_item_id is null or jsonb_typeof(p_approval) <> 'object' then
    raise exception using errcode = '22023', message = 'invoice_test_approval_payload_invalid';
  end if;

  update public.invoice_export_items
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('approval', p_approval),
      updated_at = v_now
  where company_id = p_company_id
    and id = p_invoice_export_item_id
    and environment = 'test'
    and status = 'pending'
  returning id into v_item_id;
  if v_item_id is null then
    raise exception using errcode = '23514', message = 'invoice_test_approval_item_not_pending';
  end if;

  update public.customer_invoices
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('approval', p_approval),
      updated_at = v_now
  where company_id = p_company_id
    and invoice_export_item_id = p_invoice_export_item_id
    and status = 'draft'
  returning id into v_invoice_id;
  if v_invoice_id is null then
    raise exception using errcode = '23514', message = 'invoice_test_approval_invoice_not_draft';
  end if;

  return jsonb_build_object('invoice_export_item_id', v_item_id, 'invoice_id', v_invoice_id);
end
$$;

--
-- Name: gridex_approve_portal_claim_v1(uuid, uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_approve_portal_claim_v1(p_company_id uuid, p_customer_id uuid, p_user_id uuid, p_account jsonb, p_claim jsonb, p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_now timestamptz := now();
  v_account_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'portal_claim_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_user_id is null then
    raise exception using errcode = '22023', message = 'portal_claim_payload_invalid';
  end if;

  perform 1 from public.customers
  where id = p_customer_id and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;

  insert into public.customer_portal_accounts (
    company_id, user_id, user_email, customer_id, role, is_active, activated_at, verified_at,
    match_method, verified_identity_snapshot, updated_at
  ) values (
    p_company_id, p_user_id, p_account->>'user_email', p_customer_id, 'owner', true, v_now, v_now,
    coalesce(p_account->>'match_method', 'self_claim_strict_identity'),
    coalesce(p_account->'verified_identity_snapshot', '{}'::jsonb), v_now
  )
  on conflict (user_id, customer_id) where user_id is not null and customer_id is not null
  do update set
    company_id = excluded.company_id,
    user_email = excluded.user_email,
    role = excluded.role,
    is_active = true,
    activated_at = excluded.activated_at,
    verified_at = excluded.verified_at,
    match_method = excluded.match_method,
    verified_identity_snapshot = excluded.verified_identity_snapshot,
    updated_at = excluded.updated_at
  where public.customer_portal_accounts.company_id is not distinct from excluded.company_id
     or public.customer_portal_accounts.company_id is null
  returning id into v_account_id;
  if v_account_id is null then
    -- An existing link for this user/customer belongs to another tenant.
    raise exception using errcode = '42501', message = 'portal_claim_account_tenant_mismatch';
  end if;

  insert into public.customer_portal_claims (
    user_id, company_id, user_email, customer_id, status, match_method, personal_number_last4,
    email_matched, name_matched, personal_number_matched, installation_matched,
    matched_site_id, matched_metering_point_id, input_snapshot, match_snapshot, reviewed_at
  ) values (
    p_user_id, p_company_id, p_account->>'user_email', p_customer_id, 'approved',
    coalesce(p_claim->>'match_method', 'self_claim_strict_identity'),
    p_claim->>'personal_number_last4',
    true, true, true, true,
    nullif(p_claim->>'matched_site_id', '')::uuid,
    nullif(p_claim->>'matched_metering_point_id', '')::uuid,
    coalesce(p_claim->'input_snapshot', '{}'::jsonb),
    coalesce(p_claim->'match_snapshot', '{}'::jsonb),
    v_now
  );

  insert into public.customer_portal_events (company_id, customer_id, user_id, event_type, message, metadata)
  values (
    p_company_id, p_customer_id, p_user_id,
    coalesce(p_event->>'event_type', 'portal_account_verified'),
    p_event->>'message',
    coalesce(p_event->'metadata', '{}'::jsonb)
  );

  return jsonb_build_object('account_id', v_account_id);
end
$$;

--
-- Name: gridex_archive_contract_product(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_before jsonb;
  v_channels bigint:=0;
  v_publications bigint:=0;
  v_versions bigint:=0;
  v_assignments bigint:=0;
  v_public_offers bigint:=0;
  v_offers bigint:=0;
  v_readiness jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.archive');
  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'mode','blocked','code','contract_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;
  if o.lifecycle_status='archived' then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','archived','code','contract_already_archived',
      'offer_id',o.id,'contract_product_id',o.contract_product_id
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,o.id,'archive',null
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'mode','blocked',
      'code','invalid_contract_transition',
      'current_status',o.lifecycle_status,'requested_status','archived',
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;
  v_before:=to_jsonb(o);

  if o.contract_product_id is null then
    perform public.gridex_sync_internal_offer_to_canonical(o.id);
    select * into o from public.contract_offers where id=o.id for update;
  end if;

  update public.tenant_contract_channels ch
  set status='ended',valid_to=coalesce(ch.valid_to,now()),updated_by=p_actor_user_id,updated_at=now()
  from public.tenant_contract_assignments ta
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where ch.assignment_id=ta.id and ta.company_id=p_company_id and cpv.contract_product_id=o.contract_product_id
    and ch.status<>'ended';
  get diagnostics v_channels=row_count;

  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions pv
  set status=case when pv.locked_at is null then 'archived' else 'ended' end,
      valid_to=coalesce(pv.valid_to,now())
  from public.contract_publications p
  join public.tenant_contract_assignments ta on ta.id=p.assignment_id
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where pv.contract_publication_id=p.id and ta.company_id=p_company_id
    and cpv.contract_product_id=o.contract_product_id
    and pv.status not in ('ended','archived');
  get diagnostics v_versions=row_count;

  update public.contract_publications p set status='archived',updated_at=now()
  from public.tenant_contract_assignments ta
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where p.assignment_id=ta.id and ta.company_id=p_company_id and cpv.contract_product_id=o.contract_product_id
    and p.status<>'archived';
  get diagnostics v_publications=row_count;

  update public.tenant_contract_assignments ta
  set status='ended',valid_to=coalesce(ta.valid_to,current_date),updated_at=now()
  from public.contract_product_versions cpv
  where cpv.id=ta.contract_product_version_id and ta.company_id=p_company_id
    and cpv.contract_product_id=o.contract_product_id and ta.status<>'ended';
  get diagnostics v_assignments=row_count;

  perform set_config('gridex.public_offer_write','on',true);
  update public.public_contract_offers
  set lifecycle_status='archived',publication_status='archived',is_public=false,is_archived=true,
      website_enabled=false,website_cta_enabled=false,archived_at=coalesce(archived_at,now()),
      updated_by=p_actor_user_id,updated_at=now()
  where company_id=p_company_id and (
      (o.contract_product_id is not null and contract_product_id=o.contract_product_id)
      or source_contract_offer_id in (
        select series_offer.id from public.contract_offers series_offer
        where series_offer.company_id=p_company_id and series_offer.version_series_id=o.version_series_id
      )
    ) and not is_archived;
  get diagnostics v_public_offers=row_count;

  update public.contract_offers series_offer
  set lifecycle_status='archived',status='inactive',is_active=false,
      archived_at=coalesce(series_offer.archived_at,now()),
      updated_by=p_actor_user_id,updated_at=now()
  where series_offer.company_id=p_company_id
    and (series_offer.version_series_id=o.version_series_id
         or (o.contract_product_id is not null and series_offer.contract_product_id=o.contract_product_id))
    and series_offer.lifecycle_status<>'archived';
  get diagnostics v_offers=row_count;

  select * into o from public.contract_offers where id=p_offer_id;
  update public.contract_products set status='archived',updated_at=now()
  where id=o.contract_product_id and company_id=p_company_id;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(p_company_id,p_actor_user_id,'contract_product',o.contract_product_id::text,'contract.product.archived',
    v_before,to_jsonb(o),jsonb_build_object(
      'offer_id',o.id,'history_preserved',true,'affected_channels',v_channels,
      'affected_publication_versions',v_versions,'affected_public_offers',v_public_offers
    ));

  return jsonb_build_object(
    'ok',true,'changed',(v_channels+v_publications+v_versions+v_assignments+v_public_offers+v_offers)>0,
    'mode','archived','code','contract_archived','offer',to_jsonb(o),'contract_product_id',o.contract_product_id,
    'affected_channels',v_channels,'affected_publications',v_publications,
    'affected_publication_versions',v_versions,'affected_assignments',v_assignments,
    'affected_public_offers',v_public_offers,'affected_contract_offers',v_offers
  );
end $$;

--
-- Name: FUNCTION gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Atomic idempotent contract archive RPC. Preserves history and qualifies every valid_to reference.';

--
-- Name: gridex_archive_customer_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_customer_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_customer public.customers%rowtype;
  v_after public.customers%rowtype;
  v_reason text := coalesce(nullif(btrim(p_reason), ''), 'Arkiverad via kundkort.');
  v_now timestamptz := now();
  v_contract record;
  v_sites integer := 0;
  v_points integer := 0;
  v_contracts integer := 0;
  v_switch_ids uuid[] := '{}';
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_archive_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_actor_user_id is null then
    raise exception using errcode = '22023', message = 'customer_archive_payload_invalid';
  end if;

  select * into v_customer
  from public.customers
  where id = p_customer_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;

  if v_customer.status = 'archived' then
    return jsonb_build_object('customer', to_jsonb(v_customer), 'already_archived', true);
  end if;

  update public.customers
  set status = 'archived',
      archived_at = v_now,
      archived_by = p_actor_user_id,
      archive_reason = v_reason,
      updated_at = v_now
  where id = p_customer_id and company_id = p_company_id
  returning * into v_after;

  update public.customer_sites
  set status = 'closed', closed_at = v_now, closed_reason = v_reason, updated_at = v_now
  where company_id = p_company_id and customer_id = p_customer_id;
  get diagnostics v_sites = row_count;

  update public.metering_points mp
  set status = 'closed', closed_at = v_now, closed_reason = v_reason, updated_at = v_now
  where mp.company_id = p_company_id
    and (mp.customer_id = p_customer_id
      or mp.site_id in (
        select s.id from public.customer_sites s
        where s.company_id = p_company_id and s.customer_id = p_customer_id));
  get diagnostics v_points = row_count;

  for v_contract in
    select c.id
    from public.customer_contracts c
    where c.company_id = p_company_id
      and c.customer_id = p_customer_id
      and c.status in ('draft', 'pending_signature', 'signature_failed', 'signed', 'active')
    order by c.id
  loop
    perform public.gridex_record_customer_contract_event_v1(
      p_company_id,
      v_contract.id,
      p_customer_id,
      'cancelled',
      v_now,
      'Avtalet avslutades när kunden arkiverades.',
      jsonb_build_object(
        'ends_at', to_char(v_now at time zone 'UTC', 'YYYY-MM-DD'),
        'termination_notice_date', v_now,
        'termination_reason', 'other',
        'rejected_reason', v_reason
      ),
      p_actor_user_id,
      null,
      'customer-archive:' || p_customer_id::text || ':' || v_contract.id::text
    );
    v_contracts := v_contracts + 1;
  end loop;

  with failed as (
    update public.supplier_switch_requests
    set status = 'failed', failed_at = v_now, failure_reason = v_reason, updated_at = v_now
    where company_id = p_company_id
      and customer_id = p_customer_id
      and status in ('draft', 'queued', 'submitted', 'accepted',
        'cancellation_requested', 'cancellation_sent', 'manual_followup_required')
    returning id
  )
  select coalesce(array_agg(id order by id), '{}') into v_switch_ids from failed;

  insert into public.audit_logs (
    actor_user_id, company_id, entity_type, entity_id, action,
    old_values, new_values, metadata, previous_status, new_status
  ) values (
    p_actor_user_id, p_company_id, 'customer', p_customer_id::text, 'customer.archived',
    to_jsonb(v_customer), to_jsonb(v_after),
    jsonb_build_object(
      'label', 'Arkiverade kund',
      'reason', v_reason,
      'retainedData', true,
      'hardDelete', false,
      'closedSites', v_sites,
      'closedMeteringPoints', v_points,
      'cancelledContracts', v_contracts,
      'failedSwitchRequests', coalesce(array_length(v_switch_ids, 1), 0),
      'source', 'gridex_archive_customer_v1'
    ),
    v_customer.status, 'archived'
  );

  return jsonb_build_object(
    'customer', to_jsonb(v_after),
    'already_archived', false,
    'closed_sites', v_sites,
    'closed_metering_points', v_points,
    'cancelled_contracts', v_contracts,
    'failed_switch_request_ids', to_jsonb(v_switch_ids)
  );
end
$$;

--
-- Name: gridex_archive_draft_legal_template_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_draft_legal_template_version(p_version_id uuid) RETURNS uuid
