--
-- Name: gridex_capture_ediel_route_profile_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_ediel_route_profile_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_route_version integer;
  v_actor uuid;
begin
  if TG_OP = 'UPDATE' and to_jsonb(old) = to_jsonb(new) then
    return new;
  end if;

  v_route_version := coalesce(new.route_version, 1);
  v_actor := coalesce(new.updated_by, new.created_by);

  insert into public.ediel_route_history (
    route_profile_id,
    company_id,
    route_version,
    snapshot,
    change_reason,
    created_by
  )
  values (
    new.id,
    new.company_id,
    v_route_version,
    to_jsonb(new),
    case when TG_OP = 'INSERT' then 'created' else 'updated' end,
    v_actor
  )
  on conflict (route_profile_id, route_version) do nothing;

  return new;
end;
$$;

--
-- Name: gridex_capture_ediel_rule_pack_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_ediel_rule_pack_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_profile_rule_pack_id uuid;
begin
  if new.direction='outbound' and new.message_family='APERAK' and new.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId' then
    perform gridex_ediel_common_header.witness_v1(new);return new;
  end if;
  -- A protected technical CONTRL does not borrow a nonexistent businesspack.
  -- The actual original syntax owner and qualified endpoint/wire scope suffice.
  if new.direction='outbound' and new.message_family='CONTRL' then
    perform gridex_ediel_technical_ack.require_contrl_v1(new);
    return new;
  end if;
  if new.direction='outbound' and new.message_family in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR') then
    if new.company_id is null then
      raise exception 'outbound_ediel_company_id_required' using errcode='23502';
    end if;

    if nullif(new.rule_profile_key,'') is null or new.rule_profile_version_id is null
       or nullif(new.rule_profile_version,'') is null or nullif(new.rule_pack_checksum,'') is null
       or coalesce(new.rule_pack_snapshot,'{}'::jsonb)='{}'::jsonb then
      raise exception 'outbound_ediel_rule_pack_snapshot_required' using errcode='23514';
    end if;

    select mp.rule_pack_id into v_profile_rule_pack_id
    from public.ediel_message_profiles mp
    where mp.id = new.rule_profile_version_id
      and mp.is_enabled = true;

    if v_profile_rule_pack_id is null then
      raise exception 'canonical_ediel_message_profile_required:%', new.rule_profile_version_id using errcode='23503';
    end if;

    if new.canonical_rule_pack_id is null or new.canonical_rule_pack_id <> v_profile_rule_pack_id then
      raise exception 'canonical_ediel_rule_pack_profile_mismatch:%:%', coalesce(new.canonical_rule_pack_id::text,'null'), v_profile_rule_pack_id::text using errcode='23514';
    end if;

    insert into public.ediel_rule_pack_snapshots(
      company_id,ediel_message_id,profile_key,rule_profile_version_id,profile_version,checksum,snapshot
    ) values (
      new.company_id,new.id,new.rule_profile_key,new.rule_profile_version_id,new.rule_profile_version,new.rule_pack_checksum,new.rule_pack_snapshot
    ) on conflict(ediel_message_id) do update set
      company_id=excluded.company_id,
      profile_key=excluded.profile_key,
      rule_profile_version_id=excluded.rule_profile_version_id,
      profile_version=excluded.profile_version,
      checksum=excluded.checksum,
      snapshot=excluded.snapshot;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_capture_manual_email_template_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_manual_email_template_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.request_id is null then
    return new;
  end if;

  update public.grid_owner_information_requests r
  set rendered_subject = new.subject,
      rendered_body_hash = encode(
        extensions.digest(coalesce(new.body_text, new.body_html, ''), 'sha256'),
        'hex'
      ),
      updated_at = greatest(r.updated_at, coalesce(new.updated_at, now()))
  where r.id = new.request_id
    and r.company_id = new.company_id;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_capture_manual_email_template_audit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_capture_manual_email_template_audit() IS 'Captures exact rendered manual e-mail subject and SHA-256 body hash on the originating grid-owner information request.';

--
-- Name: gridex_capture_portfolio_monthly_price_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_portfolio_monthly_price_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  row_id uuid;
  row_company_id uuid;
  row_version integer;
  row_changed_by uuid;
  row_old jsonb;
  row_new jsonb;
begin
  if tg_op = 'DELETE' then
    row_id := old.id;
    row_company_id := old.company_id;
    row_version := coalesce(old.version_number, 1);
    row_changed_by := coalesce(old.updated_by, old.created_by);
    row_old := to_jsonb(old);
    row_new := null;
  elsif tg_op = 'INSERT' then
    row_id := new.id;
    row_company_id := new.company_id;
    row_version := coalesce(new.version_number, 1);
    row_changed_by := coalesce(new.updated_by, new.created_by);
    row_old := null;
    row_new := to_jsonb(new);
  else
    row_id := new.id;
    row_company_id := new.company_id;
    row_version := coalesce(new.version_number, old.version_number, 1);
    row_changed_by := coalesce(new.updated_by, new.created_by, old.updated_by, old.created_by);
    row_old := to_jsonb(old);
    row_new := to_jsonb(new);
  end if;

  insert into public.portfolio_monthly_price_history(
    portfolio_price_id,
    company_id,
    version_number,
    action,
    old_values,
    new_values,
    changed_by
  ) values (
    row_id,
    row_company_id,
    row_version,
    lower(tg_op),
    row_old,
    row_new,
    row_changed_by
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

--
-- Name: gridex_capture_signed_contract_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_signed_contract_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_acceptance jsonb; v_sha text; v_pub uuid; v_product_version uuid; v_product uuid; v_bundle uuid;
begin
  if new.status not in ('signed','active') or new.signed_at is null then return new; end if;
  if tg_op='UPDATE' and old.status in ('signed','active') and old.signed_at is not null then return new; end if;

  if new.contract_publication_version_id is null and new.public_contract_offer_id is not null then
    select cpv.id,cpv.contract_product_version_id,pv.contract_product_id,cpv.legal_bundle_version_id
      into v_pub,v_product_version,v_product,v_bundle
    from public.contract_publication_versions cpv
    join public.contract_product_versions pv on pv.id=cpv.contract_product_version_id
    where cpv.legacy_public_contract_offer_id=new.public_contract_offer_id
    order by cpv.version_number desc limit 1;
    new.contract_publication_version_id:=v_pub;
    new.contract_product_version_id:=coalesce(new.contract_product_version_id,v_product_version);
    new.contract_product_id:=coalesce(new.contract_product_id,v_product);
    new.legal_bundle_version_id:=coalesce(new.legal_bundle_version_id,v_bundle);
  end if;

  new.locked_at:=coalesce(new.locked_at,now());
  new.commercial_snapshot:=coalesce(nullif(new.commercial_snapshot,'{}'::jsonb),jsonb_build_object(
    'contract_name',new.contract_name,'contract_type',new.contract_type,'price_plan_id',new.price_plan_id,
    'price_plan_version_id',new.price_plan_version_id,'price_snapshot',new.price_snapshot,'campaign_snapshot',new.campaign_snapshot));
  new.legal_snapshot:=coalesce(nullif(new.legal_snapshot,'{}'::jsonb),jsonb_build_object(
    'legal_bundle_version_id',new.legal_bundle_version_id,'legal_versions_snapshot',new.legal_versions_snapshot,
    'terms_version',new.terms_version,'terms_signed_version',new.terms_signed_version));
  v_acceptance:=jsonb_build_object('customer_contract_id',new.id,'company_id',new.company_id,'accepted_at',new.signed_at,
    'offer_reference',new.offer_reference,'publication_version_id',new.contract_publication_version_id,
    'commercial_snapshot',new.commercial_snapshot,'legal_snapshot',new.legal_snapshot,'signature_snapshot_sha256',new.signature_snapshot_sha256);
  v_sha:=encode(digest(v_acceptance::text,'sha256'),'hex');
  insert into public.customer_contract_acceptances(company_id,customer_contract_id,contract_publication_version_id,accepted_at,channel,signing_method,customer_identity_snapshot,power_of_attorney_snapshot,acceptance_snapshot,acceptance_sha256)
  values(new.company_id,new.id,new.contract_publication_version_id,new.signed_at,coalesce(new.source_type,'website'),'server_verified',jsonb_build_object('customer_id',new.customer_id), '{}'::jsonb,v_acceptance,v_sha)
  on conflict do nothing;
  insert into public.customer_contract_evidence(company_id,customer_contract_id,evidence_type,evidence_snapshot,evidence_sha256,captured_at)
  values(new.company_id,new.id,'contract_acceptance',v_acceptance,v_sha,new.signed_at) on conflict do nothing;
  return new;
end $$;

--
-- Name: billing_automation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_automation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    billing_month text NOT NULL,
    target_system text NOT NULL,
    export_format text NOT NULL,
    send_to_partner boolean DEFAULT false NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT billing_automation_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT billing_automation_jobs_billing_month_check CHECK ((billing_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT billing_automation_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT billing_automation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'completed_with_blockers'::text, 'failed'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.billing_automation_jobs FORCE ROW LEVEL SECURITY;

--
-- Name: gridex_claim_billing_automation_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_claim_billing_automation_jobs(p_worker_id text, p_limit integer DEFAULT 8) RETURNS SETOF public.billing_automation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if nullif(btrim(p_worker_id),'') is null then raise exception 'worker_id_required'; end if;
  if p_limit < 1 or p_limit > 50 then raise exception 'invalid_claim_limit'; end if;
  return query
  with candidates as (
    select j.id
    from public.billing_automation_jobs j
    where j.status in ('queued','failed')
      and j.available_at <= now()
      and j.attempts < j.max_attempts
      and (j.locked_at is null or j.locked_at < now() - interval '30 minutes')
    order by j.available_at,j.created_at,j.company_id
    for update skip locked
    limit p_limit
  )
  update public.billing_automation_jobs j
     set status='running', locked_at=now(), locked_by=p_worker_id,
         attempts=j.attempts+1, updated_at=now(), last_error=null
    from candidates c
   where j.id=c.id
  returning j.*;
end $$;

--
-- Name: customer_operation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_operation_jobs (
