--
-- Name: gridex_contract_actor_can_operate_company(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_actor_can_operate_company(p_actor_user_id uuid, p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
  select p_actor_user_id is not null
    and p_company_id is not null
    and (coalesce(auth.role(),'')='service_role' or p_actor_user_id=auth.uid())
    and (
      exists(
        select 1
        from public.admin_users admin_user
        where admin_user.user_id=p_actor_user_id
          and coalesce(admin_user.is_active,true)
          and lower(coalesce(admin_user.role,'')) in (
            'super_admin','superadmin','platform_superadmin'
          )
      )
      or exists(
        select 1
        from public.user_roles user_role
        left join public.roles role on role.id=user_role.role_id
        where user_role.user_id=p_actor_user_id
          and coalesce(user_role.status,'active')='active'
          and coalesce(user_role.is_active,true)
          and lower(coalesce(user_role.role,role.key,role.name,'')) in (
            'super_admin','superadmin','platform_superadmin'
          )
      )
      or exists(
        select 1
        from public.company_memberships membership
        where membership.user_id=p_actor_user_id
          and membership.company_id=p_company_id
          and coalesce(membership.status,'active')='active'
          and coalesce(membership.is_active,true)
      )
    )
$$;

--
-- Name: gridex_contract_actor_has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_actor_has_permission(p_actor_user_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_actor_user_id is not null
    and (coalesce(auth.role(),'')='service_role' or p_actor_user_id=auth.uid())
    and (
      exists(
        select 1 from public.admin_users au
        where au.user_id=p_actor_user_id
          and coalesce(au.is_active,true)
          and public.gridex_normalize_platform_role(au.role)
            in ('super_admin','platform_admin')
      )
      or exists(
        select 1
        from public.user_roles ur
        left join public.roles r on r.id=ur.role_id
        where ur.user_id=p_actor_user_id
          and coalesce(ur.status,'active')='active'
          and coalesce(ur.is_active,true)
          and public.gridex_normalize_platform_role(
            coalesce(ur.role,r.key,r.name)
          ) in ('super_admin','platform_admin')
      )
      or public.gridex_has_permission(p_actor_user_id,p_permission)
    )
$$;

--
-- Name: FUNCTION gridex_contract_actor_has_permission(p_actor_user_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_actor_has_permission(p_actor_user_id uuid, p_permission text) IS 'Canonical contract permission gate aligned with the platform_admin role used by the admin contracts page.';

--
-- Name: gridex_contract_business_usage_counts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_business_usage_counts(p_company_id uuid, p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_customer_contracts bigint:=0;
  v_applications bigint:=0;
  v_external_intakes bigint:=0;
  v_snapshots bigint:=0;
  v_invoices bigint:=0;
  v_billing_underlays bigint:=0;
  v_billing_underlay_items bigint:=0;
  v_charge_ledger bigint:=0;
  v_acceptances bigint:=0;
begin
  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id;
  if not found then
    return jsonb_build_object('ok',false,'code','contract_offer_not_found');
  end if;

  select count(*) into v_customer_contracts
  from public.customer_contracts c
  where c.company_id=p_company_id and (
    c.contract_offer_id=o.id
    or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
    or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
        and c.contract_offer_id is null and c.contract_product_version_id is null)
  );

  select count(*) into v_applications
  from public.website_customer_applications a
  where a.company_id=p_company_id
    and coalesce(a.status,'application_received') not in ('cancelled','failed','rejected')
    and exists(
      select 1 from public.public_contract_offers po
      where po.id=a.public_contract_offer_id and (
        po.source_contract_offer_id=o.id
        or (o.contract_product_version_id is not null and po.contract_product_version_id=o.contract_product_version_id)
        or (o.contract_product_id is not null and po.contract_product_id=o.contract_product_id
            and po.source_contract_offer_id is null and po.contract_product_version_id is null)
      )
    );

  select count(*) into v_external_intakes
  from public.external_contract_intakes x
  where x.company_id=p_company_id
    and coalesce(x.status,'received') not in ('cancelled','failed','duplicate')
    and (
      x.contract_offer_id=o.id
      or exists(
        select 1 from public.public_contract_offers po
        where po.id=x.public_contract_offer_id and (
          po.source_contract_offer_id=o.id
          or (o.contract_product_version_id is not null and po.contract_product_version_id=o.contract_product_version_id)
          or (o.contract_product_id is not null and po.contract_product_id=o.contract_product_id
              and po.source_contract_offer_id is null and po.contract_product_version_id is null)
        )
      )
    );

  -- Preview-only public price snapshots are technical data. A snapshot blocks
  -- deletion only when it belongs to a real customer contract for this offer.
  select count(*) into v_snapshots
  from public.contract_price_snapshots s
  where s.company_id=p_company_id and exists(
    select 1 from public.customer_contracts c
    where c.id=s.contract_id and c.company_id=p_company_id and (
      c.contract_offer_id=o.id
      or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
      or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
          and c.contract_offer_id is null and c.contract_product_version_id is null)
    )
  );

  select count(*) into v_invoices
  from public.customer_invoices i
  where i.company_id=p_company_id and exists(
    select 1 from public.customer_contracts c
    where c.id=coalesce(i.customer_contract_id,i.contract_id)
      and c.company_id=p_company_id and (
        c.contract_offer_id=o.id
        or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
        or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
            and c.contract_offer_id is null and c.contract_product_version_id is null)
      )
  );

  select count(*) into v_billing_underlays
  from public.billing_underlays b
  where b.company_id=p_company_id and exists(
    select 1 from public.customer_contracts c
    where c.id=b.contract_id and c.company_id=p_company_id and (
      c.contract_offer_id=o.id
      or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
      or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
          and c.contract_offer_id is null and c.contract_product_version_id is null)
    )
  );

  select count(*) into v_billing_underlay_items
  from public.billing_underlay_items bi
  join public.billing_underlays b on b.id=bi.billing_underlay_id and b.company_id=bi.company_id
  where bi.company_id=p_company_id and exists(
    select 1 from public.customer_contracts c
    where c.id=b.contract_id and c.company_id=p_company_id and (
      c.contract_offer_id=o.id
      or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
      or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
          and c.contract_offer_id is null and c.contract_product_version_id is null)
    )
  );

  select count(*) into v_charge_ledger
  from public.contract_charge_ledger l
  where l.company_id=p_company_id and exists(
    select 1 from public.customer_contracts c
    where c.id=l.customer_contract_id and c.company_id=p_company_id and (
      c.contract_offer_id=o.id
      or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
      or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
          and c.contract_offer_id is null and c.contract_product_version_id is null)
    )
  );

  select count(*) into v_acceptances
  from public.customer_contract_acceptances a
  join public.customer_contracts c on c.id=a.customer_contract_id and c.company_id=a.company_id
  where a.company_id=p_company_id and (
    c.contract_offer_id=o.id
    or (o.contract_product_version_id is not null and c.contract_product_version_id=o.contract_product_version_id)
    or (o.contract_product_id is not null and c.contract_product_id=o.contract_product_id
        and c.contract_offer_id is null and c.contract_product_version_id is null)
  );

  return jsonb_build_object(
    'ok',true,
    'customer_contracts',v_customer_contracts,
    'customer_applications',v_applications,
    'external_intakes',v_external_intakes,
    'binding_price_snapshots',v_snapshots,
    'invoices',v_invoices,
    'billing_underlays',v_billing_underlays,
    'billing_underlay_items',v_billing_underlay_items,
    'charge_ledger',v_charge_ledger,
    'legal_acceptances',v_acceptances,
    'total',v_customer_contracts+v_applications+v_external_intakes+v_snapshots+
      v_invoices+v_billing_underlays+v_billing_underlay_items+v_charge_ledger+v_acceptances
  );
end $$;

--
-- Name: tenant_contract_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_contract_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    contract_product_version_id uuid NOT NULL,
    internal_sales_allowed boolean DEFAULT true NOT NULL,
    website_publication_allowed boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    legal_mode text DEFAULT 'ops_standard'::text NOT NULL,
    valid_from date,
    valid_to date,
    assigned_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    api_publication_allowed boolean DEFAULT false NOT NULL,
    CONSTRAINT tenant_contract_assignments_legal_mode_check CHECK ((legal_mode = ANY (ARRAY['ops_standard'::text, 'ops_standard_with_addendum'::text, 'tenant_legal'::text]))),
    CONSTRAINT tenant_contract_assignments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'ended'::text])))
);

--
-- Name: gridex_contract_channel_permission_allowed(public.tenant_contract_assignments, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_channel_permission_allowed(p_assignment public.tenant_contract_assignments, p_channel text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select case lower(coalesce(p_channel,''))
    when 'internal' then p_assignment.internal_sales_allowed
    when 'website' then p_assignment.website_publication_allowed
    when 'api' then p_assignment.api_publication_allowed
    else false
  end
$$;

--
-- Name: gridex_contract_delete_blocker_details_v1(text[], jsonb, bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_delete_blocker_details_v1(p_reason_codes text[], p_business jsonb, p_quote_count bigint, p_counts jsonb, p_foreign_key_blockers jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'resource_type',case b.code
          when 'HAS_CUSTOMER_CONTRACTS' then 'customer_contract'
          when 'HAS_ACCEPTED_APPLICATIONS' then 'customer_application'
          when 'HAS_EXTERNAL_INTAKES' then 'external_intake'
          when 'HAS_BINDING_PRICE_SNAPSHOTS' then 'contract_price_snapshot'
          when 'HAS_INVOICES' then 'customer_invoice'
          when 'HAS_BILLING_HISTORY' then 'billing_underlay'
          when 'HAS_CHARGE_LEDGER' then 'charge_ledger'
          when 'HAS_LEGAL_ACCEPTANCES' then 'customer_contract_acceptance'
          when 'HAS_WEBSITE_QUOTES' then 'website_quote'
          when 'HAS_SUCCESSOR_VERSION' then 'successor_contract_version'
          when 'HAS_SHARED_CANONICAL_VERSION' then 'shared_contract_product_version'
          when 'HAS_SHARED_LEGAL_VERSION' then 'shared_legal_bundle_version'
          when 'PUBLICATION_GRAPH_INCONSISTENT' then 'publication_graph'
          when 'PERMANENT_DELETE_REQUIRES_DRAFT' then 'contract_lifecycle'
          when 'HAS_RESTRICTING_FOREIGN_KEYS' then 'foreign_key'
          else lower(b.code)
        end,
        'count',case b.code
          when 'HAS_CUSTOMER_CONTRACTS' then coalesce((p_business->>'customer_contracts')::bigint,0)
          when 'HAS_ACCEPTED_APPLICATIONS' then coalesce((p_business->>'customer_applications')::bigint,0)
          when 'HAS_EXTERNAL_INTAKES' then coalesce((p_business->>'external_intakes')::bigint,0)
          when 'HAS_BINDING_PRICE_SNAPSHOTS' then coalesce((p_business->>'binding_price_snapshots')::bigint,0)
          when 'HAS_INVOICES' then coalesce((p_business->>'invoices')::bigint,0)
          when 'HAS_BILLING_HISTORY' then coalesce((p_business->>'billing_underlays')::bigint,0)+coalesce((p_business->>'billing_underlay_items')::bigint,0)
          when 'HAS_CHARGE_LEDGER' then coalesce((p_business->>'charge_ledger')::bigint,0)
          when 'HAS_LEGAL_ACCEPTANCES' then coalesce((p_business->>'legal_acceptances')::bigint,0)
          when 'HAS_WEBSITE_QUOTES' then coalesce(p_quote_count,0)
          when 'HAS_SUCCESSOR_VERSION' then coalesce((p_counts->>'successor_offers')::bigint,0)
          when 'HAS_SHARED_CANONICAL_VERSION' then coalesce((p_counts->>'shared_product_version_references')::bigint,0)
          when 'HAS_SHARED_LEGAL_VERSION' then coalesce((p_counts->>'shared_legal_version_references')::bigint,0)
          when 'PUBLICATION_GRAPH_INCONSISTENT' then coalesce((p_counts->>'unsafe_graph_issues')::bigint,0)
          when 'HAS_RESTRICTING_FOREIGN_KEYS' then coalesce((p_foreign_key_blockers->>'count')::bigint,0)
          else 1
        end,
        'reason',b.code,
        'message',case b.code
          when 'HAS_CUSTOMER_CONTRACTS' then 'Signerade eller aktiva kundavtal måste bevaras.'
          when 'HAS_ACCEPTED_APPLICATIONS' then 'En eller flera kundansökningar refererar till avtalet.'
          when 'HAS_EXTERNAL_INTAKES' then 'Externa kundintag refererar till avtalet.'
          when 'HAS_BINDING_PRICE_SNAPSHOTS' then 'Bindande prissnapshots måste bevaras.'
          when 'HAS_INVOICES' then 'Fakturahistorik refererar till avtalet.'
          when 'HAS_BILLING_HISTORY' then 'Faktureringsunderlag refererar till avtalet.'
          when 'HAS_CHARGE_LEDGER' then 'Avgiftsliggaren refererar till avtalet.'
          when 'HAS_LEGAL_ACCEPTANCES' then 'Juridiska accepter måste bevaras.'
          when 'HAS_WEBSITE_QUOTES' then 'Utfärdade website-offerter måste bevaras.'
          when 'HAS_SUCCESSOR_VERSION' then 'Avtalsversionen har en efterföljande version.'
          when 'HAS_SHARED_CANONICAL_VERSION' then 'Canonical avtalsversion delas av annan data.'
          when 'HAS_SHARED_LEGAL_VERSION' then 'Juridikversionen delas av annan data.'
          when 'PUBLICATION_GRAPH_INCONSISTENT' then 'Publiceringsgrafen är inkonsekvent och måste repareras.'
          when 'PERMANENT_DELETE_REQUIRES_DRAFT' then 'Permanent radering tillåts endast för draft eller ready.'
          when 'HAS_RESTRICTING_FOREIGN_KEYS' then 'Skyddade foreign keys refererar fortfarande till publiceringen.'
          else b.code
        end
      ))
      order by b.ordinal
    ),
    '[]'::jsonb
  )
  from unnest(coalesce(p_reason_codes,'{}'::text[])) with ordinality b(code,ordinal)
$$;

--
-- Name: gridex_contract_delete_dependency_graph_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_delete_dependency_graph_v2(p_company_id uuid, p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_preview jsonb;
  v_blockers jsonb:='[]'::jsonb;
  v_offer public.contract_offers%rowtype;
  v_company_name text;
  v_preview_token text;
begin
  select * into v_offer
  from public.contract_offers offer
  where offer.id=p_offer_id
    and offer.company_id=p_company_id;

  if not found then
    return jsonb_build_object(
      'ok',false,
      'code','contract_not_found',
      'contract_offer_id',p_offer_id,
      'contract_product_id',null,
      'can_delete',false,
      'deletable',false,
      'recommended_action','none',
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_offer',
        'resource_id',null,
        'count',0,
        'reason','contract_not_found',
        'classification','repairable_broken_relation',
        'recommended_action','none',
        'message','Avtalet hittades inte för valt bolag.'
      ))
    );
  end if;

  select company.name into v_company_name
  from public.companies company
  where company.id=p_company_id;

  v_preview:=public.gridex_preview_delete_unused_contract(
    p_company_id,
    p_offer_id
  );

  select coalesce(jsonb_agg(
    blocker
    || jsonb_build_object(
      'resource_id',coalesce(blocker->'resource_id','null'::jsonb),
      'classification',case
        when blocker->>'reason' in (
          'HAS_INVOICES','HAS_BILLING_HISTORY','HAS_CHARGE_LEDGER',
          'HAS_LEGAL_ACCEPTANCES'
        ) then 'regulatory_retention_blocker'
        when blocker->>'reason' in (
          'HAS_CUSTOMER_CONTRACTS','HAS_ACCEPTED_APPLICATIONS',
          'HAS_EXTERNAL_INTAKES','HAS_BINDING_PRICE_SNAPSHOTS',
          'HAS_WEBSITE_QUOTES'
        ) then 'business_history_blocker'
        when blocker->>'reason' in (
          'HAS_SUCCESSOR_VERSION','HAS_SHARED_CANONICAL_VERSION',
          'HAS_SHARED_LEGAL_VERSION','PUBLICATION_GRAPH_INCONSISTENT',
          'HAS_RESTRICTING_FOREIGN_KEYS'
        ) then 'repairable_broken_relation'
        else 'business_history_blocker'
      end,
      'recommended_action',case
        when blocker->>'reason' in (
          'HAS_SUCCESSOR_VERSION','HAS_SHARED_CANONICAL_VERSION',
          'HAS_SHARED_LEGAL_VERSION','PUBLICATION_GRAPH_INCONSISTENT',
          'HAS_RESTRICTING_FOREIGN_KEYS'
        ) then 'repair'
        else 'archive'
      end
    )
  ),'[]'::jsonb)
  into v_blockers
  from jsonb_array_elements(coalesce(v_preview->'blockers','[]'::jsonb)) blocker;

  v_preview:=v_preview
    || jsonb_build_object(
      'contract_offer_id',v_offer.id,
      'contract_product_id',v_offer.contract_product_id,
      'product_name',v_offer.name,
      'company_id',p_company_id,
      'company_name',v_company_name,
      'blockers',v_blockers,
      'dependency_classification',jsonb_build_object(
        'deletable_internal_dependency',coalesce(v_preview->'removable_system_dependencies','{}'::jsonb),
        'business_history_blocker',coalesce((select jsonb_agg(value) from jsonb_array_elements(v_blockers) value where value->>'classification'='business_history_blocker'),'[]'::jsonb),
        'regulatory_retention_blocker',coalesce((select jsonb_agg(value) from jsonb_array_elements(v_blockers) value where value->>'classification'='regulatory_retention_blocker'),'[]'::jsonb),
        'repairable_broken_relation',coalesce((select jsonb_agg(value) from jsonb_array_elements(v_blockers) value where value->>'classification'='repairable_broken_relation'),'[]'::jsonb)
      )
    );

  v_preview_token:=md5((v_preview-'preview_token')::text);
  return v_preview||jsonb_build_object('preview_token',v_preview_token);
end
$$;

--
-- Name: FUNCTION gridex_contract_delete_dependency_graph_v2(p_company_id uuid, p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_delete_dependency_graph_v2(p_company_id uuid, p_offer_id uuid) IS 'Canonical tenant-scoped delete dependency graph shared by actor-aware preview and locked commit. Classifies removable draft dependencies, business history, regulatory retention and repairable broken relations.';

--
-- Name: gridex_contract_energy_direction_guard_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_energy_direction_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_expected text;
begin
  if tg_table_name='contract_product_versions' then
    select energy_direction into v_expected
    from public.contract_products
    where id=new.contract_product_id;
  elsif tg_table_name='contract_publication_versions' then
    select energy_direction into v_expected
    from public.contract_product_versions
    where id=new.contract_product_version_id;
  elsif tg_table_name='public_contract_offers' then
    if new.contract_publication_version_id is not null then
      select energy_direction into v_expected
      from public.contract_publication_versions
      where id=new.contract_publication_version_id;
    elsif new.contract_product_version_id is not null then
      select energy_direction into v_expected
      from public.contract_product_versions
      where id=new.contract_product_version_id;
    elsif new.source_contract_offer_id is not null then
      select energy_direction into v_expected
      from public.contract_offers
      where id=new.source_contract_offer_id
        and company_id=new.company_id;
    elsif new.contract_product_id is not null then
      select energy_direction into v_expected
      from public.contract_products
      where id=new.contract_product_id;
    else
      v_expected:=coalesce(
        nullif(new.energy_direction,''),
        nullif(new.metadata->>'energy_direction',''),
        'consumption'
      );
    end if;
  else
    raise exception using errcode='42809',message='energy_direction_guard_wrong_table';
  end if;

  if v_expected is null or v_expected not in ('consumption','production') then
    raise exception using errcode='23514',message='canonical_energy_direction_missing';
  end if;
  if new.energy_direction is not null and new.energy_direction<>v_expected then
    raise exception using errcode='23514',message='canonical_energy_direction_mismatch';
  end if;
  new.energy_direction:=v_expected;
  return new;
end
$$;

--
-- Name: gridex_contract_offer_company_resolution(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_offer_company_resolution(p_offer_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with offer as (
  select o.* from public.contract_offers o where o.id=p_offer_id
), candidate_rows(company_id,source) as (
  select o.company_id,'contract_offers.company_id' from offer o
  union all
  select ppv.company_id,'price_plan_versions.company_id'
    from offer o join public.price_plan_versions ppv on ppv.id=o.price_plan_version_id
  union all
  select pp.company_id,'price_plans.company_id'
    from offer o join public.price_plans pp on pp.id=o.price_plan_id
  union all
  select cp.company_id,'contract_products.company_id'
    from offer o join public.contract_products cp on cp.id=o.contract_product_id
  union all
  select cp.company_id,'contract_product_versions.contract_product_id'
    from offer o
    join public.contract_product_versions cpv on cpv.id=o.contract_product_version_id
    join public.contract_products cp on cp.id=cpv.contract_product_id
  union all
  select tca.company_id,'tenant_contract_assignments.company_id'
    from offer o
    join public.tenant_contract_assignments tca
      on tca.contract_product_version_id=o.contract_product_version_id
  union all
  select cc.company_id,'customer_contracts.company_id'
    from public.customer_contracts cc
    where cc.contract_offer_id=p_offer_id
  union all
  select cov.company_id,'contract_offer_versions.company_id'
    from public.contract_offer_versions cov
    where cov.contract_offer_id=p_offer_id
), valid as (
  select company_id,source from candidate_rows where company_id is not null
), summary as (
  select
    count(distinct company_id)::integer company_count,
    coalesce(array_agg(distinct company_id order by company_id),'{}'::uuid[]) company_ids,
    coalesce(jsonb_agg(jsonb_build_object('company_id',company_id,'source',source)
      order by source,company_id),'[]'::jsonb) sources
  from valid
)
select case
  when company_count=1 then jsonb_build_object(
    'status','ready','company_id',company_ids[1],'sources',sources
  )
  when company_count=0 then jsonb_build_object(
    'status','blocked','code','tenant_context_missing','company_ids','[]'::jsonb,'sources',sources
  )
  else jsonb_build_object(
    'status','blocked','code','tenant_context_conflict','company_ids',to_jsonb(company_ids),'sources',sources
  )
end
from summary;
$$;

--
-- Name: FUNCTION gridex_contract_offer_company_resolution(p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_offer_company_resolution(p_offer_id uuid) IS 'Resolves a legacy internal offer tenant only from deterministic relational evidence. Missing or conflicting ownership is platform-remediated and never guessed.';

--
-- Name: gridex_contract_offer_references_v1(uuid, uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_offer_references_v1(p_company_id uuid, p_public_offer_ids uuid[] DEFAULT '{}'::uuid[], p_product_version_ids uuid[] DEFAULT '{}'::uuid[], p_publication_version_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(reference order by reference),'{}'::text[])
  from (
    select distinct nullif(btrim(cpv.offer_reference),'') as reference
    from public.contract_publication_versions cpv
    join public.contract_publications cp
      on cp.id=cpv.contract_publication_id
    join public.tenant_contract_assignments ta
      on ta.id=cp.assignment_id
    where ta.company_id=p_company_id
      and (
        cpv.id=any(coalesce(p_publication_version_ids,'{}'::uuid[]))
        or cpv.contract_product_version_id=any(coalesce(p_product_version_ids,'{}'::uuid[]))
        or cpv.legacy_public_contract_offer_id=any(coalesce(p_public_offer_ids,'{}'::uuid[]))
      )

    union

    select distinct coalesce(
      nullif(btrim(pco.metadata->>'offer_reference'),''),
      nullif(btrim(pco.metadata->>'canonical_offer_reference'),'')
    ) as reference
    from public.public_contract_offers pco
    where pco.company_id=p_company_id
      and (
        pco.id=any(coalesce(p_public_offer_ids,'{}'::uuid[]))
        or pco.contract_product_version_id=any(coalesce(p_product_version_ids,'{}'::uuid[]))
      )
  ) refs
  where reference is not null
$$;

--
-- Name: FUNCTION gridex_contract_offer_references_v1(p_company_id uuid, p_public_offer_ids uuid[], p_product_version_ids uuid[], p_publication_version_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_offer_references_v1(p_company_id uuid, p_public_offer_ids uuid[], p_product_version_ids uuid[], p_publication_version_ids uuid[]) IS 'Returns tenant-scoped canonical offer references from contract_publication_versions.offer_reference with metadata fallback for legacy public offers.';

--
-- Name: gridex_contract_offer_slug_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_offer_slug_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_supplied text:=nullif(btrim(new.slug),'');
  v_legacy_generated text:=nullif(
    lower(trim(both '-' from regexp_replace(coalesce(new.name,''),'[^a-zA-Z0-9]+','-','g'))),
    ''
  );
begin
  -- Detect the legacy ASCII-only generated value and regenerate from name
  -- before Swedish characters have been lost.
  if v_supplied is null or v_supplied=v_legacy_generated then
    new.slug:=public.gridex_contract_slugify(new.name);
  else
    new.slug:=public.gridex_contract_slugify(v_supplied);
  end if;
  return new;
end
$$;

--
-- Name: gridex_contract_platform_integrity_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_platform_integrity_report(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
select jsonb_build_object(
  'company_id',p_company_id,'generated_at',now(),
  'published_offers_missing_canonical_binding',(select count(*) from public.public_contract_offers o where o.company_id=p_company_id and o.publication_status='published' and (o.contract_product_version_id is null or o.contract_publication_version_id is null or o.legal_bundle_version_id is null or o.price_plan_version_id is null or o.price_book_id is null)),
  'published_versions_blocked',(select count(*) from public.contract_publication_readiness_v r where r.company_id=p_company_id and r.status='published' and coalesce(array_length(r.blockers,1),0)>0),
  'signed_contracts_missing_exact_binding',(select count(*) from public.customer_contracts c where c.company_id=p_company_id and c.status in ('signed','active') and (c.contract_publication_version_id is null or c.contract_product_version_id is null or c.legal_bundle_version_id is null or c.contract_price_snapshot_id is null)),
  'ready_underlays_missing_exact_binding',(select count(*) from public.billing_underlays b where b.company_id=p_company_id and b.readiness_status='ready' and (b.contract_id is null or coalesce(b.contract_price_snapshot_id,b.pricing_snapshot_id) is null)),
  'ready_exports_with_contract_mismatch',(select count(*) from public.billing_export_run_items i join public.billing_underlays b on b.id=i.billing_underlay_id and b.company_id=i.company_id where i.company_id=p_company_id and i.status='ready' and i.contract_id is distinct from b.contract_id),
  'production_underlays_invalid',(select count(*) from public.billing_underlays b where b.company_id=p_company_id and b.energy_direction='production' and (b.settlement_type not in ('credit_invoice','self_billing') or b.total_kwh<=0)),
  'consumption_corrections_invalid',(select count(*) from public.billing_underlays b where b.company_id=p_company_id and b.energy_direction='consumption_correction' and (b.settlement_type<>'credit_invoice' or b.total_kwh<=0)),
  'export_readiness_blocked',(select count(*) from public.billing_export_readiness_v r where r.company_id=p_company_id and not r.is_exportable),
  'orphan_unlocked_price_versions',(select count(*) from public.price_plan_versions v where v.company_id=p_company_id and v.locked_at is null and not exists(select 1 from public.public_contract_offers o where o.price_plan_version_id=v.id) and not exists(select 1 from public.contract_publication_versions cpv where cpv.price_plan_version_id=v.id) and not exists(select 1 from public.contract_offers o where o.price_plan_version_id=v.id) and not exists(select 1 from public.customer_contracts c where c.price_plan_version_id=v.id) and not exists(select 1 from public.contract_price_snapshots s where s.price_plan_version_id=v.id) and not exists(select 1 from public.billing_underlays b where b.price_plan_version_id=v.id) and not exists(select 1 from public.billing_underlay_items i where i.price_plan_version_id=v.id)),
  'orphan_unlocked_price_books',(select count(*) from public.price_books b where b.company_id=p_company_id and b.locked_at is null and not exists(select 1 from public.public_contract_offers o where o.price_book_id=b.id) and not exists(select 1 from public.contract_publication_versions cpv where cpv.price_book_id=b.id) and not exists(select 1 from public.contract_offers o where o.price_book_id=b.id) and not exists(select 1 from public.customer_contracts c where c.price_book_id=b.id) and not exists(select 1 from public.contract_price_snapshots s where s.price_book_id=b.id) and not exists(select 1 from public.billing_underlays u where u.price_book_id=b.id) and not exists(select 1 from public.billing_underlay_items i where i.price_book_id=b.id)),
  'runtime_functions_present',jsonb_build_object(
    'public_offer_upsert',to_regprocedure('public.gridex_upsert_public_contract_offer(uuid,uuid,text,jsonb,jsonb,uuid)') is not null,
    'website_contract_create',to_regprocedure('public.gridex_create_website_customer_contract(uuid,jsonb,text)') is not null,
    'pricing_persist',to_regprocedure('public.gridex_persist_pricing_run(uuid,uuid,jsonb,jsonb)') is not null,
    'export_create',to_regprocedure('public.gridex_create_billing_export_run(jsonb,jsonb)') is not null,
    'export_queue',to_regprocedure('public.gridex_queue_billing_export_run(uuid,uuid,uuid)') is not null,
    'export_partner_result',to_regprocedure('public.gridex_apply_billing_export_partner_result(uuid,uuid,uuid[],jsonb,jsonb,uuid)') is not null
  ),
  'runtime_search_path_valid',not exists(
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname in ('gridex_create_or_version_contract_pricing','gridex_materialize_legal_bundle_version','gridex_sync_public_offer_to_canonical','gridex_sync_internal_offer_to_canonical','gridex_create_website_customer_contract','gridex_persist_pricing_run','gridex_lock_pricing_run')
      and not ('search_path=public, extensions, pg_temp'=any(coalesce(p.proconfig,'{}'::text[])) or 'search_path=public,extensions,pg_temp'=any(coalesce(p.proconfig,'{}'::text[])))
  )
) $$;

--
-- Name: gridex_contract_platform_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_platform_readiness(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_company_id is null then
    raise exception using
      errcode = '22023',
      message = 'company_id_required';
  end if;

  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     and not public.gridex_can_read_company(p_company_id)
  then
    raise exception using
      errcode = '42501',
      message = 'insufficient_company_access';
  end if;

  return public.gridex_contract_platform_readiness_internal_v1(p_company_id);
end;
$$;

--
-- Name: FUNCTION gridex_contract_platform_readiness(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_platform_readiness(p_company_id uuid) IS 'Tenant-authorized readiness facade. Authenticated callers may only read companies permitted by gridex_can_read_company; service_role may inspect any company. Database administrators can use the revoked internal function directly.';

--
-- Name: gridex_contract_platform_readiness_internal_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_platform_readiness_internal_v1(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with tenant as (
  select * from public.gridex_tenant_contract_readiness_v where company_id=p_company_id
), email_status as (
  select
    case
      when not exists(select 1 from public.company_email_settings s where s.company_id=p_company_id) then 'unknown'
      when exists(select 1 from public.company_email_settings s where s.company_id=p_company_id and coalesce(s.is_active,false)=true and nullif(s.sender_email,'') is not null) then 'ready'
      else 'blocked'
    end as status,
    array_remove(array[
      case when not exists(select 1 from public.company_email_settings s where s.company_id=p_company_id) then 'email_settings_missing' end,
      case when exists(select 1 from public.company_email_settings s where s.company_id=p_company_id) and not exists(select 1 from public.company_email_settings s where s.company_id=p_company_id and coalesce(s.is_active,false)=true and nullif(s.sender_email,'') is not null) then 'email_sender_not_ready' end,
      case when not exists(select 1 from public.company_email_templates t where t.company_id=p_company_id and t.is_active=true) then 'active_email_templates_missing' end
    ],null) blockers
), docs as (
  select
    case when exists(
      select 1 from public.customer_contracts c
      where c.company_id=p_company_id and c.signed_at is not null
        and not exists(
          select 1 from public.customer_contract_documents d
          where d.customer_contract_id=c.id and d.document_type='signed_contract_pdf'
            and d.storage_bucket='customer-contract-documents' and nullif(d.storage_path,'') is not null
        )
    ) then 'blocked' else 'ready' end status,
    coalesce(array(
      select 'signed_contract_pdf_missing:'||c.id::text
      from public.customer_contracts c
      where c.company_id=p_company_id and c.signed_at is not null
        and not exists(
          select 1 from public.customer_contract_documents d
          where d.customer_contract_id=c.id and d.document_type='signed_contract_pdf'
            and d.storage_bucket='customer-contract-documents' and nullif(d.storage_path,'') is not null
        )
      order by c.created_at desc limit 25
    ),'{}') blockers
), operations as (
  select
    case when exists(
      select 1 from public.customer_contracts c
      where c.company_id=p_company_id and c.status in('signed','active')
        and (c.contract_publication_version_id is null or c.price_plan_version_id is null or c.legal_bundle_version_id is null)
    ) then 'blocked' else 'ready' end status,
    coalesce(array(
      select 'customer_contract_version_binding_missing:'||c.id::text
      from public.customer_contracts c
      where c.company_id=p_company_id and c.status in('signed','active')
        and (c.contract_publication_version_id is null or c.price_plan_version_id is null or c.legal_bundle_version_id is null)
      order by c.created_at desc limit 25
    ),'{}') blockers
)
select jsonb_build_object(
  'company_id',p_company_id,
  'legal_profile',jsonb_build_object(
    'status',coalesce(t.legal_profile_status,'unknown'),
    'missing_fields',coalesce(t.legal_profile_missing_fields,'{}'),
    'review_required',coalesce(t.legal_profile_review_required,false)
  ),
  'publication',jsonb_build_object(
    'status',coalesce(t.overall_status,'unknown'),
    'blockers',coalesce(t.publication_blockers,'{}'),
    'published_versions',coalesce(t.published_publication_versions,0)
  ),
  'website',jsonb_build_object(
    'can_display',coalesce(t.can_display,false),
    'blockers',case when coalesce(t.can_display,false) then '[]'::jsonb else to_jsonb(coalesce(t.publication_blockers,'{}')) end
  ),
  'applications',jsonb_build_object(
    'can_accept',coalesce(t.can_accept_applications,false),
    'blockers',case when coalesce(t.can_accept_applications,false) then '[]'::jsonb else to_jsonb(coalesce(t.publication_blockers,'{}')) end
  ),
  'email',jsonb_build_object('status',e.status,'blockers',e.blockers),
  'documents',jsonb_build_object('status',d.status,'blockers',d.blockers),
  'customer_operations',jsonb_build_object('status',o.status,'blockers',o.blockers),
  'evaluated_at',now()
)
from (select 1 as singleton) seed
left join tenant t on true
cross join email_status e
cross join docs d
cross join operations o;
$$;

--
-- Name: FUNCTION gridex_contract_platform_readiness_internal_v1(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_platform_readiness_internal_v1(p_company_id uuid) IS 'Internal unchecked readiness implementation. Never grant to tenant roles; call through gridex_contract_platform_readiness(uuid).';

--
-- Name: gridex_contract_price_snapshots_company_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_price_snapshots_company_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_parent_company_id uuid;
begin
  if new.contract_id is null then
    raise exception 'contract_price_snapshot_contract_id_required'
      using errcode = '23502';
  end if;

  select c.company_id
  into v_parent_company_id
  from public.customer_contracts c
  where c.id = new.contract_id;

  if not found then
    raise exception 'contract_price_snapshot_contract_not_found'
      using errcode = '23503',
            detail = jsonb_build_object(
              'contract_price_snapshot_id', new.id,
              'contract_id', new.contract_id
            )::text;
  end if;

  perform public.gridex_assert_same_company(
    new.company_id,
    v_parent_company_id,
    TG_TABLE_NAME,
    'contract_id'
  );

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_contract_price_snapshots_company_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_price_snapshots_company_guard() IS 'Validates contract_price_snapshots.contract_id ownership without referencing nonexistent NEW.customer_contract_id.';

--
-- Name: gridex_contract_product_version_integrity_guard_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_product_version_integrity_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_expected_hash text;
begin
  if nullif(new.commercial_snapshot->>'contract_type', '')
       is distinct from new.contract_type then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_snapshot_contract_type_mismatch';
  end if;

  if nullif(new.commercial_snapshot->>'energy_direction', '')
       is distinct from new.energy_direction then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_snapshot_energy_direction_mismatch';
  end if;

  v_expected_hash :=
    encode(digest(new.commercial_snapshot::text, 'sha256'), 'hex');
  if new.content_sha256 is distinct from v_expected_hash then
    raise exception using
      errcode = '23514',
      message = 'contract_product_version_content_hash_mismatch',
      detail = jsonb_build_object(
        'expected', v_expected_hash,
        'received', new.content_sha256
      )::text;
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_contract_product_version_integrity_guard_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_product_version_integrity_guard_v1() IS 'Rejects new product versions whose query columns, canonical snapshot and SHA-256 evidence disagree.';

--
-- Name: gridex_contract_publication_revision_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_publication_revision_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_channel text;
  v_entity_id text;
  v_assignment_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_option_id uuid;
  v_row jsonb;
begin
  v_row:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_entity_id:=v_row->>'id';
  if tg_table_name='public_contract_offers' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_channel:='website';
  elsif tg_table_name='tenant_contract_channels' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publications' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publication_versions' then
    v_publication_id:=(v_row->>'contract_publication_id')::uuid;
    select a.company_id,p.channel into v_company_id,v_channel
    from public.contract_publications p
    join public.tenant_contract_assignments a on a.id=p.assignment_id
    where p.id=v_publication_id;
  elsif tg_table_name='contract_price_options' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_publication_version_id:=nullif(
      v_row->>'contract_publication_version_id',''
    )::uuid;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  elsif tg_table_name='contract_price_option_area_prices' then
    v_option_id:=(v_row->>'contract_price_option_id')::uuid;
    select o.company_id,o.contract_publication_version_id
      into v_company_id,v_publication_version_id
    from public.contract_price_options o where o.id=v_option_id;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  end if;
  if v_company_id is not null and v_channel in ('website','api') then
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,v_channel,tg_table_name||'.'||lower(tg_op),v_entity_id
    );
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: gridex_contract_readiness_blocker_details_v1(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_readiness_blocker_details_v1(p_blockers text[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'code',b.code,
        'field',case b.code
          when 'contract_offer_not_found' then 'contract_offer_id'
          when 'lifecycle_status_not_publishable' then 'lifecycle_status'
          when 'name_missing' then 'name'
          when 'canonical_product_missing' then 'contract_product_id'
          when 'canonical_product_version_missing' then 'contract_product_version_id'
          when 'canonical_product_version_mismatch' then 'contract_product_version_id'
          when 'tenant_assignment_missing' then 'tenant_contract_assignment_id'
          when 'internal_channel_missing' then 'internal_channel'
          when 'price_plan_missing' then 'price_plan_id'
          when 'price_plan_version_missing' then 'price_plan_version_id'
          when 'price_book_missing' then 'price_book_id'
          when 'invoice_fee_missing' then 'invoice_fee_sek'
          when 'invoice_fee_invalid' then 'invoice_fee_sek'
          when 'vat_rate_invalid' then 'vat_rate'
          when 'fixed_price_missing' then 'fixed_price_ore_per_kwh'
          when 'price_areas_missing' then 'commercial_snapshot.price_areas'
          when 'duplicate_price_areas' then 'commercial_snapshot.price_areas'
          when 'resolution_missing' then 'commercial_snapshot.interval_resolution'
          when 'resolution_mismatch' then 'commercial_snapshot.interval_resolution'
          when 'invalid_validity_period' then 'valid_to'
          when 'invalid_max_customers' then 'max_customers'
          when 'automatic_renewal_term_missing' then 'automatic_renewal_term_months'
          when 'discount_months_missing' then 'discount_months'
          when 'portfolio_id_missing' then 'commercial_snapshot.portfolio_method.portfolio_id'
          when 'pricing_weights_invalid' then 'commercial_snapshot.portfolio_method.mix_shares'
          when 'production_settlement_mode_missing' then 'commercial_snapshot.production.settlement_mode'
          when 'tenant_go_live_not_ready' then 'company_id'
          when 'tenant_legal_profile_not_ready' then 'tenant_legal_profile'
          when 'required_legal_modules_missing' then 'legal_bundle'
          else null
        end,
        'message',case b.code
          when 'contract_offer_not_found' then 'Avtalsversionen hittades inte för valt bolag.'
          when 'lifecycle_status_not_publishable' then 'Nuvarande lifecycle-status kan inte publiceras. Skapa eller öppna ett draft, ready eller paused-utkast.'
          when 'name_missing' then 'Internt avtalsnamn saknas.'
          when 'canonical_product_missing' then 'Canonical avtalsprodukt saknas.'
          when 'canonical_product_version_missing' then 'Canonical immutable avtalsversion saknas.'
          when 'canonical_product_version_mismatch' then 'Avtalsversionen tillhör inte vald canonical produkt.'
          when 'tenant_assignment_missing' then 'Aktiv tenanttilldelning till exakt avtalsversion saknas.'
          when 'internal_channel_missing' then 'Intern försäljningskanal saknas för tenanttilldelningen.'
          when 'price_plan_missing' then 'Prisplan saknas.'
          when 'price_plan_version_missing' then 'Låst prisversion saknas.'
          when 'price_book_missing' then 'Prisbok eller prissnapshot saknas.'
          when 'invoice_fee_missing' then 'Fakturaavgiften måste vara explicit angiven, även när den är 0.'
          when 'invoice_fee_invalid' then 'Fakturaavgiften får inte vara negativ.'
          when 'vat_rate_invalid' then 'Moms måste ligga mellan 0 och 1.'
          when 'fixed_price_missing' then 'Fastprisavtal saknar ett positivt pris per kWh.'
          when 'price_areas_missing' then 'Minst ett tillåtet elområde måste anges.'
          when 'duplicate_price_areas' then 'Elområdeslistan innehåller dubbletter.'
          when 'resolution_missing' then 'Prisupplösning saknas i den immutable kommersiella snapshoten.'
          when 'resolution_mismatch' then 'Prisupplösningen matchar inte vald avtalsmodell.'
          when 'invalid_validity_period' then 'Giltig till ligger före giltig från.'
          when 'invalid_max_customers' then 'Max antal kunder måste vara större än 0.'
          when 'automatic_renewal_term_missing' then 'Automatisk förlängning saknar förlängningsperiod.'
          when 'discount_months_missing' then 'Rabattvärde finns men rabattperiod saknas.'
          when 'portfolio_id_missing' then 'Portfölj- eller mixavtal saknar portfölj-ID.'
          when 'pricing_weights_invalid' then 'Spot-, portfölj- och fastvikter måste summera till 100 procent.'
          when 'production_settlement_mode_missing' then 'Produktionsavtalet saknar avräkningsmodell.'
          when 'tenant_go_live_not_ready' then 'Tenantens produktionsrouting, BRP eller avsändaridentitet är inte komplett.'
          when 'tenant_legal_profile_not_ready' then 'Tenantens juridiska profil är inte komplett och granskad.'
          when 'required_legal_modules_missing' then 'Ett eller flera obligatoriska juridikmoduler saknar publicerad låst version.'
          else b.code
        end
      ))
      order by b.ordinal
    ),
    '[]'::jsonb
  )
  from unnest(coalesce(p_blockers,'{}'::text[])) with ordinality b(code,ordinal)
$$;

--
-- Name: gridex_contract_readiness_blocker_v2(text, text, text, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_readiness_blocker_v2(p_code text, p_field text, p_message text, p_current_value jsonb DEFAULT NULL::jsonb, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'code',p_code,
    'field',p_field,
    'message',p_message,
    'current_value',p_current_value,
    'resource_type',p_resource_type,
    'resource_id',p_resource_id,
    'metadata',p_metadata
  ))
$$;

--
-- Name: gridex_contract_slugify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_slugify(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select nullif(
    trim(both '-' from regexp_replace(
      translate(lower(btrim(p_value)), 'åäö', 'aao'),
      '[^a-z0-9]+',
      '-',
      'g'
    )),
    ''
  )
$$;

--
-- Name: FUNCTION gridex_contract_slugify(p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_contract_slugify(p_value text) IS 'Canonical future-write slug normalizer. Transliteration: å/ä -> a, ö -> o. Slug is non-unique and is not contract identity.';

--
-- Name: gridex_contract_system_dependency_counts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contract_system_dependency_counts(p_company_id uuid, p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  g jsonb;
  c jsonb;
  v_offer_versions bigint:=0;
begin
  g:=public.gridex_resolve_contract_lifecycle_graph(p_company_id,p_offer_id);
  if not coalesce((g->>'ok')::boolean,false) then return g; end if;
  c:=coalesce(g->'counts','{}'::jsonb);
  select count(*) into v_offer_versions
  from public.contract_offer_versions
  where company_id=p_company_id and contract_offer_id=p_offer_id;
  return jsonb_build_object(
    'ok',true,
    'offer_versions',v_offer_versions,
    'successor_offers',coalesce((c->>'successor_offers')::bigint,0),
    'public_offers',coalesce((c->>'public_offers')::bigint,0),
    'product_versions',jsonb_array_length(coalesce(g->'contract_product_version_ids','[]'::jsonb)),
    'tenant_assignments',coalesce((c->>'tenant_assignments')::bigint,0),
    'channel_rows',(
      select count(*) from public.tenant_contract_channels
      where assignment_id=any(array(select jsonb_array_elements_text(g->'tenant_assignment_ids')::uuid))
    ),
    'active_channels',(
      select count(*) from public.tenant_contract_channels
      where assignment_id=any(array(select jsonb_array_elements_text(g->'tenant_assignment_ids')::uuid))
        and status='active'
    ),
    'publications',coalesce((c->>'publications')::bigint,0),
    'publication_versions',coalesce((c->>'publication_versions')::bigint,0),
    'direct_reverse_legacy_references',coalesce((c->>'direct_reverse_legacy_references')::bigint,0),
    'repairable_stale_reverse_references',coalesce((c->>'repairable_stale_reverse_references')::bigint,0),
    'legal_bundle_versions',coalesce((c->>'legal_bundle_versions')::bigint,0),
    'shared_product_version_references',coalesce((c->>'shared_product_version_references')::bigint,0),
    'shared_legal_version_references',coalesce((c->>'shared_legal_version_references')::bigint,0),
    'unsafe_graph_issues',coalesce((c->>'unsafe_graph_issues')::bigint,0),
    'graph',g
  );
end $$;

--
-- Name: gridex_copy_contract_offer_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_copy_contract_offer_v1(p_company_id uuid, p_source_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_source public.contract_offers%rowtype;
  v_payload jsonb;
  v_pricing_snapshot jsonb;
  v_result jsonb;
  v_new_offer_id uuid;
  v_suffix text := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'contract_offer_copy_service_role_required';
  end if;

  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.create'
  );

  select *
  into v_source
  from public.contract_offers
  where id = p_source_offer_id
    and company_id = p_company_id
  for share;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'contract_offer_copy_source_not_found';
  end if;

  v_pricing_snapshot :=
    coalesce(v_source.commercial_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'copied_from_contract_offer_id', v_source.id,
      'copy_operation', 'gridex_copy_contract_offer_v1'
    );

  v_payload :=
    to_jsonb(v_source)
    - array[
        'id',
        'contract_product_id',
        'contract_product_version_id',
        'version_series_id',
        'supersedes_offer_id',
        'copied_from_contract_offer_id',
        'created_at',
        'created_by',
        'updated_at',
        'updated_by',
        'published_at',
        'archived_at',
        'superseded_at',
        'ended_at',
        'version_snapshot',
        'commercial_snapshot'
      ]
    || jsonb_build_object(
      'name', v_source.name || ' (kopia)',
      'slug',
        public.gridex_contract_slugify(v_source.slug || '-kopia-' || v_suffix),
      'status', 'draft',
      'lifecycle_status', 'draft',
      'is_active', false,
      'valid_from', null,
      'valid_to', null,
      'channels', jsonb_build_object(
        'internal', 'paused',
        'website', 'paused',
        'api', 'paused'
      ),
      'copied_from_contract_offer_id', v_source.id
    );

  v_result := public.gridex_upsert_internal_contract_offer_v2(
    p_company_id,
    null,
    v_payload,
    v_pricing_snapshot,
    p_actor_user_id
  );

  if not coalesce((v_result->>'ok')::boolean, true) then
    return v_result;
  end if;

  v_new_offer_id := nullif(v_result#>>'{offer,id}', '')::uuid;
  if v_new_offer_id is null then
    raise exception using
      errcode = '23502',
      message = 'contract_offer_copy_result_missing_offer_id';
  end if;

  update public.contract_offers
  set copied_from_contract_offer_id = v_source.id,
      updated_at = now(),
      updated_by = p_actor_user_id
  where id = v_new_offer_id
    and company_id = p_company_id
    and lifecycle_status = 'draft';
  if not found then
    raise exception using
      errcode = '23514',
      message = 'contract_offer_copy_draft_binding_failed';
  end if;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    actor_user_id,
    source,
    idempotency_key,
    payload
  ) values (
    p_company_id,
    'contract.offer.copied',
    'contract_offer',
    v_new_offer_id,
    p_actor_user_id,
    'gridex_copy_contract_offer_v1',
    'contract-copy:' || v_new_offer_id::text,
    jsonb_build_object(
      'source_contract_offer_id', v_source.id,
      'new_contract_offer_id', v_new_offer_id
    )
  ) on conflict do nothing;

  return v_result || jsonb_build_object(
    'ok', true,
    'copied', true,
    'source_contract_offer_id', v_source.id,
    'new_contract_offer_id', v_new_offer_id
  );
end
$$;

--
-- Name: FUNCTION gridex_copy_contract_offer_v1(p_company_id uuid, p_source_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_copy_contract_offer_v1(p_company_id uuid, p_source_offer_id uuid, p_actor_user_id uuid) IS 'Creates a new unpublished contract product/version graph from any tenant-scoped source offer. Customer contracts, quotes, signatures, POAs, publications and capacity state are never copied.';

--
-- Name: gridex_correction_combined_snapshot_v1(uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_correction_combined_snapshot_v1(p_company_id uuid, p_environment text, p_message_id uuid, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'combined_snapshot_service_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_correction_process.open_combined_v1(p_company_id,p_environment,p_message_id,p_cutoff);
END $$;

--
-- Name: gridex_create_actor_registry_conflict(uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_actor_registry_conflict(p_company_id uuid, p_import_run_id uuid, p_import_item_id uuid, p_actor_id uuid, p_grid_owner_id uuid, p_supplier_id uuid, p_conflict_type text, p_severity text, p_title text, p_message text, p_current_data jsonb DEFAULT '{}'::jsonb, p_incoming_data jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_fingerprint text;
  v_id uuid;
begin
  v_fingerprint := encode(digest(coalesce(p_conflict_type, '') || '|' || coalesce(p_actor_id::text, '') || '|' || coalesce(p_grid_owner_id::text, '') || '|' || coalesce(p_supplier_id::text, '') || '|' || coalesce(p_current_data::text, '{}') || '|' || coalesce(p_incoming_data::text, '{}'), 'sha256'), 'hex');

  insert into public.actor_registry_conflicts(
    company_id, import_run_id, import_item_id, actor_id, grid_owner_id, supplier_id,
    conflict_type, severity, status, title, message, current_data, incoming_data,
    conflict_fingerprint, metadata
  ) values (
    p_company_id, p_import_run_id, p_import_item_id, p_actor_id, p_grid_owner_id, p_supplier_id,
    coalesce(p_conflict_type, 'manual_review_required'), coalesce(p_severity, 'blocking'), 'open',
    coalesce(p_title, 'Behöver granskas'), coalesce(p_message, 'Aktörsdata behöver granskas innan den används.'),
    coalesce(p_current_data, '{}'::jsonb), coalesce(p_incoming_data, '{}'::jsonb),
    v_fingerprint, coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (conflict_fingerprint) where conflict_fingerprint is not null
  do update set
    status = case when actor_registry_conflicts.status in ('resolved','ignored') then actor_registry_conflicts.status else 'open' end,
    updated_at = now(),
    metadata = coalesce(actor_registry_conflicts.metadata, '{}'::jsonb) || excluded.metadata
  returning id into v_id;

  return v_id;
end;
$$;

--
-- Name: gridex_create_billing_export_run(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_billing_export_run(p_run jsonb, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item jsonb;company uuid;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 company:=(p_run->>'company_id')::uuid;
 IF company IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'billing_export_source_scope_required'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  IF item->>'status'='ready' THEN PERFORM gridex_billing_source.require_underlay_v1(company,(item->>'billing_underlay_id')::uuid); END IF;
 END LOOP;
 RETURN gridex_billing_source.gridex_create_billing_export_run_before_source_v2(p_run,p_items);
END $$;

--
-- Name: gridex_create_customer_info_request_v1(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_customer_info_request_v1(p_company_id uuid, p_request jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_customer_id uuid := nullif(p_request->>'customer_id', '')::uuid;
  v_site_id uuid := nullif(p_request->>'site_id', '')::uuid;
  v_metering_point_id uuid := nullif(p_request->>'metering_point_id', '')::uuid;
  v_automation_key text := nullif(btrim(p_request->>'automation_key'), '');
  v_categories jsonb := coalesce(p_request->'requested_data_categories', '[]'::jsonb);
  v_row public.customer_info_requests%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_info_request_service_role_required';
  end if;
  if p_company_id is null or v_customer_id is null
     or nullif(p_request->>'request_type', '') is null
     or nullif(p_request->>'target_party_type', '') is null
     or jsonb_typeof(v_categories) <> 'array' or jsonb_array_length(v_categories) = 0 then
    raise exception using errcode = '22023', message = 'customer_info_request_payload_invalid';
  end if;
  if not exists (select 1 from public.customers where id = v_customer_id and company_id = p_company_id) then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_company';
  end if;
  if v_site_id is not null and not exists (
    select 1 from public.customer_sites where id = v_site_id and company_id = p_company_id and customer_id = v_customer_id
  ) then
    raise exception using errcode = 'P0002', message = 'site_not_found_for_customer';
  end if;
  if v_metering_point_id is not null and not exists (
    select 1 from public.metering_points where id = v_metering_point_id and company_id = p_company_id and customer_id = v_customer_id
  ) then
    raise exception using errcode = 'P0002', message = 'metering_point_not_found_for_customer';
  end if;

  if v_automation_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':cir:' || v_automation_key, 0));
    select * into v_row from public.customer_info_requests
     where company_id = p_company_id and automation_key = v_automation_key;
    if found then
      return jsonb_build_object('created', false, 'request', to_jsonb(v_row));
    end if;
  end if;

  insert into public.customer_info_requests (
    company_id, customer_id, site_id, metering_point_id, grid_owner_id, operation_id,
    request_type, target_party_type, target_party_name, current_supplier_name,
    status, requested_data_categories, verified_payload, notes,
    automation_origin, automation_key, created_by, updated_by
  ) values (
    p_company_id, v_customer_id, v_site_id, v_metering_point_id,
    nullif(p_request->>'grid_owner_id', '')::uuid, nullif(p_request->>'operation_id', '')::uuid,
    p_request->>'request_type', p_request->>'target_party_type', nullif(p_request->>'target_party_name', ''),
    nullif(p_request->>'current_supplier_name', ''),
    'draft', v_categories, coalesce(p_request->'verified_payload', '{}'::jsonb), nullif(p_request->>'notes', ''),
    nullif(p_request->>'automation_origin', ''), v_automation_key, p_actor_user_id, p_actor_user_id
  ) returning * into v_row;

  insert into public.customer_info_request_events (
    company_id, customer_info_request_id, customer_id, event_type, message, payload, created_by
  ) values (
    p_company_id, v_row.id, v_customer_id, 'created', 'Uppgiftsbegäran skapades.',
    jsonb_build_object(
      'requested_data_categories', v_categories,
      'siteId', v_site_id, 'meteringPointId', v_metering_point_id,
      'gridOwnerId', v_row.grid_owner_id, 'operationId', v_row.operation_id,
      'automationOrigin', v_row.automation_origin),
    p_actor_user_id);

  return jsonb_build_object('created', true, 'request', to_jsonb(v_row));
end;
$$;

--
-- Name: gridex_create_customer_site_with_address(uuid, uuid, text, text, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_customer_site_with_address(p_company_id uuid, p_customer_id uuid, p_site_name text, p_facility_id text, p_street text, p_postal_code text, p_city text, p_country text, p_address_normalized text, p_address_hash text, p_source text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_site_id uuid;
  v_now timestamptz := now();
  v_country text := coalesce(nullif(btrim(p_country), ''), 'SE');
  v_site_name text := coalesce(nullif(btrim(p_site_name), ''), 'Anläggning');
  v_claimed_grid_area_code text := nullif(btrim(p_metadata ->> 'claimed_grid_area_code'), '');
  v_claimed_price_area_code text := upper(nullif(btrim(p_metadata ->> 'claimed_price_area_code'), ''));
  v_claimed_grid_owner_id uuid := null;
begin
  if p_company_id is null then
    raise exception 'company_id_required' using errcode = '22023';
  end if;
  if p_customer_id is null then
    raise exception 'customer_id_required' using errcode = '22023';
  end if;
  if p_address_hash is null or btrim(p_address_hash) = '' then
    raise exception 'address_hash_required' using errcode = '22023';
  end if;

  if (p_metadata ->> 'claimed_grid_owner_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_claimed_grid_owner_id := (p_metadata ->> 'claimed_grid_owner_id')::uuid;
  end if;

  select id
    into v_site_id
    from public.customer_sites
   where company_id = p_company_id
     and customer_id = p_customer_id
     and address_hash = p_address_hash
     and coalesce(is_active, true) = true
   order by created_at asc
   limit 1
   for update;

  if v_site_id is not null then
    update public.customer_sites
       set site_name = coalesce(nullif(btrim(site_name), ''), v_site_name),
           facility_id = coalesce(nullif(btrim(facility_id), ''), nullif(btrim(p_facility_id), '')),
           street = coalesce(nullif(btrim(street), ''), p_street),
           postal_code = coalesce(nullif(btrim(postal_code), ''), p_postal_code),
           city = coalesce(nullif(btrim(city), ''), p_city),
           country = coalesce(nullif(btrim(country), ''), v_country),
           address_normalized = coalesce(nullif(btrim(address_normalized), ''), p_address_normalized),
           address_hash = coalesce(nullif(btrim(address_hash), ''), p_address_hash),
           address_source = coalesce(nullif(btrim(address_source), ''), coalesce(nullif(btrim(p_source), ''), 'website')),
           address_received_at = coalesce(address_received_at, v_now),
           address_status = case when p_source = 'grid_owner_response' then 'verified' else coalesce(address_status, 'candidate') end,
           address_quality_status = coalesce(address_quality_status, 'complete'),
           facility_data_status = coalesce(facility_data_status, case when p_source = 'grid_owner_response' then 'verified' else 'unverified' end),
           resolution_status = coalesce(resolution_status, 'needs_review'),
           grid_owner_id = coalesce(grid_owner_id, v_claimed_grid_owner_id),
           selected_grid_owner_id = coalesce(selected_grid_owner_id, v_claimed_grid_owner_id),
           grid_area_code = coalesce(nullif(btrim(grid_area_code), ''), v_claimed_grid_area_code),
           price_area_code = coalesce(nullif(btrim(price_area_code), ''), v_claimed_price_area_code),
           bidding_zone_code = coalesce(nullif(btrim(bidding_zone_code), ''), v_claimed_price_area_code),
           metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
           updated_at = v_now
     where id = v_site_id
       and company_id = p_company_id
       and customer_id = p_customer_id;
    return v_site_id;
  end if;

  insert into public.customer_sites (
    company_id,
    customer_id,
    site_name,
    facility_id,
    site_type,
    status,
    is_active,
    street,
    postal_code,
    city,
    country,
    address_normalized,
    address_hash,
    address_source,
    address_received_at,
    address_status,
    address_quality_status,
    address_quality_warnings,
    facility_data_status,
    resolution_status,
    grid_owner_id,
    selected_grid_owner_id,
    grid_area_code,
    price_area_code,
    bidding_zone_code,
    metadata,
    created_at,
    updated_at
  ) values (
    p_company_id,
    p_customer_id,
    v_site_name,
    nullif(btrim(p_facility_id), ''),
    'consumption',
    'draft',
    true,
    p_street,
    p_postal_code,
    p_city,
    v_country,
    p_address_normalized,
    p_address_hash,
    coalesce(nullif(btrim(p_source), ''), 'website'),
    v_now,
    case when p_source = 'grid_owner_response' then 'verified' else 'candidate' end,
    'complete',
    '[]'::jsonb,
    case when p_source = 'grid_owner_response' then 'verified' else 'unverified' end,
    'needs_review',
    v_claimed_grid_owner_id,
    v_claimed_grid_owner_id,
    v_claimed_grid_area_code,
    v_claimed_price_area_code,
    v_claimed_price_area_code,
    coalesce(p_metadata, '{}'::jsonb),
    v_now,
    v_now
  ) returning id into v_site_id;

  insert into public.customer_addresses (
    company_id, customer_id, type, street_1, postal_code, city, country,
    is_active, metadata, created_at, updated_at
  ) values (
    p_company_id, p_customer_id, 'facility', p_street, p_postal_code, p_city,
    v_country, true,
    jsonb_build_object('customer_site_id', v_site_id, 'address_hash', p_address_hash, 'source', p_source),
    v_now, v_now
  );

  insert into public.customer_site_address_history (
    company_id, customer_id, customer_site_id, address_hash, source,
    source_reference, actor_user_id, snapshot
  ) values (
    p_company_id, p_customer_id, v_site_id, p_address_hash,
    coalesce(nullif(btrim(p_source), ''), 'website'), null, null,
    jsonb_build_object(
      'street', p_street,
      'postal_code', p_postal_code,
      'city', p_city,
      'country', v_country,
      'address_hash', p_address_hash,
      'source', p_source,
      'claimed_grid_owner_id', v_claimed_grid_owner_id,
      'claimed_grid_area_code', v_claimed_grid_area_code,
      'claimed_price_area_code', v_claimed_price_area_code
    )
  );

  return v_site_id;
end;
$_$;

--
-- Name: gridex_create_external_staff_invitation_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_external_staff_invitation_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE membership text;
BEGIN
 PERFORM public.gridex_staff_identity_registration_v1(p_command,true);
 SELECT membership_role INTO membership FROM public.canonical_tenant_access_role_mapping WHERE role_key=p_command->>'role_key' AND is_assignable;
 RETURN public.canonical_create_tenant_invitation(jsonb_build_object('company_id',(p_command->>'company_id')::uuid,'actor_user_id',(p_command->>'actor_user_id')::uuid,
  'api_client_id',(p_command->>'api_client_id')::uuid,'channel','ops','staff_operation','invite','external_staff_identity',true,
  'email',p_command->>'email','full_name',p_command->>'full_name','role_key',p_command->>'role_key','membership_role',membership,
  'idempotency_key',p_command->>'idempotency_key','source','ops_external_staff_bootstrap'));
END $$;

--
-- Name: gridex_create_grid_owner_data_request_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_grid_owner_data_request_v1(p_company_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_customer_id uuid := nullif(p_request->>'customer_id', '')::uuid;
  v_site_id uuid := nullif(p_request->>'site_id', '')::uuid;
  v_point_id uuid := nullif(p_request->>'metering_point_id', '')::uuid;
  v_grid_owner_id uuid := nullif(p_request->>'grid_owner_id', '')::uuid;
  v_operation_id uuid := nullif(p_request->>'operation_id', '')::uuid;
  v_scope text := coalesce(nullif(p_request->>'request_scope', ''), 'customer_masterdata');
  v_key text := nullif(p_request->>'automation_key', '');
  v_existing public.grid_owner_data_requests%rowtype;
  v_row public.grid_owner_data_requests%rowtype;
  v_payload jsonb;
  v_columns text;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'grid_owner_data_request_service_role_required';
  end if;
  if p_company_id is null or v_customer_id is null then
    raise exception using errcode = '22023', message = 'grid_owner_data_request_payload_invalid';
  end if;

  perform 1 from public.customers
  where id = v_customer_id and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;
  if v_site_id is not null then
    perform 1 from public.customer_sites
    where id = v_site_id and company_id = p_company_id and customer_id = v_customer_id;
    if not found then
      raise exception using errcode = 'P0002', message = 'site_not_found_for_customer';
    end if;
  end if;
  if v_point_id is not null then
    perform 1 from public.metering_points mp
    where mp.id = v_point_id
      and mp.company_id = p_company_id
      and (mp.customer_id = v_customer_id or mp.site_id = v_site_id
           or mp.site_id in (select s.id from public.customer_sites s
                             where s.customer_id = v_customer_id and s.company_id = p_company_id));
    if not found then
      raise exception using errcode = 'P0002', message = 'metering_point_not_found_for_customer';
    end if;
  end if;

  -- Serialise concurrent creates of the same logical request.
  if v_key is not null or v_operation_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(
      'grid_owner_data_request:' || p_company_id::text || ':' || coalesce(v_key, v_operation_id::text || ':' || v_scope), 0));
  end if;

  if v_key is not null then
    select * into v_existing
    from public.grid_owner_data_requests
    where company_id = p_company_id and automation_key = v_key and status in ('pending', 'sent')
    order by created_at desc
    limit 1;
    if found then
      return jsonb_build_object('request', to_jsonb(v_existing), 'existing', true);
    end if;
  end if;

  if v_operation_id is not null then
    select * into v_existing
    from public.grid_owner_data_requests
    where company_id = p_company_id
      and operation_id = v_operation_id
      and customer_id = v_customer_id
      and request_scope = v_scope
      and site_id is not distinct from v_site_id
      and metering_point_id is not distinct from v_point_id
      and grid_owner_id is not distinct from v_grid_owner_id
    order by created_at desc
    limit 1;
    if found then
      return jsonb_build_object('request', to_jsonb(v_existing), 'existing', true);
    end if;
  end if;

  v_payload := (p_request - array['id', 'company_id', 'status', 'created_at', 'updated_at'])
    || jsonb_build_object('company_id', p_company_id, 'status', 'pending', 'request_scope', v_scope);
  select string_agg(quote_ident(key), ', ' order by key) into v_columns
  from jsonb_object_keys(v_payload) as key
  where key in (
    select attname from pg_attribute
    where attrelid = 'public.grid_owner_data_requests'::regclass and attnum > 0 and not attisdropped
  );
  execute format(
    'insert into public.grid_owner_data_requests (%1$s) select %1$s from jsonb_populate_record(null::public.grid_owner_data_requests, $1) returning *',
    v_columns
  ) into v_row using v_payload;

  return jsonb_build_object('request', to_jsonb(v_row), 'existing', false);
end
$_$;

--
-- Name: gridex_create_internal_customer_contract_v1(uuid, uuid, uuid, uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_internal_customer_contract_v1(p_company_id uuid, p_customer_id uuid, p_contract_offer_id uuid, p_site_id uuid, p_metering_point_id uuid, p_selection jsonb, p_contract jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  v_offer public.contract_offers%rowtype;
  v_option public.contract_price_options%rowtype;
  v_area public.contract_price_option_area_prices%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_snapshot_id uuid;
  v_publication_version_id uuid;
  v_selected_refs text[];
  v_resolved_count integer;
  v_pricing_model text;
  v_snapshot jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.create');
  if p_selection->>'snapshot_schema'<>'gridex_contract_pricing_v6_selection'
    or jsonb_typeof(p_selection->'base_price_components_snapshot')<>'array'
    or jsonb_typeof(p_selection->'price_components_snapshot')<>'array'
    or nullif(p_selection->>'price_option_reference','') is null
    or nullif(p_selection->>'invoice_delivery_method','') is null then
    raise exception using errcode='22023',message='internal_contract_commercial_selection_incomplete';
  end if;
  if nullif(p_contract->>'signed_at','') is not null or coalesce(nullif(p_contract->>'status',''),'draft') in ('signed','active') then
    raise exception using errcode='23514',message='internal_contract_raw_signature_state_forbidden';
  end if;

  select offer.* into v_offer from public.contract_offers offer
  where offer.id=p_contract_offer_id and offer.company_id=p_company_id and offer.lifecycle_status='published' and offer.is_active for share;
  if not found then raise exception using errcode='P0002',message='internal_contract_offer_not_sellable'; end if;
  if not exists(select 1 from public.customers customer where customer.id=p_customer_id and customer.company_id=p_company_id) then
    raise exception using errcode='23514',message='internal_contract_customer_tenant_mismatch';
  end if;
  if p_site_id is not null and not exists(select 1 from public.customer_sites site where site.id=p_site_id and site.company_id=p_company_id and site.customer_id=p_customer_id) then
    raise exception using errcode='23514',message='internal_contract_site_tenant_mismatch';
  end if;
  if p_metering_point_id is not null and not exists(select 1 from public.metering_points point where point.id=p_metering_point_id and point.company_id=p_company_id and (p_site_id is null or point.site_id=p_site_id)) then
    raise exception using errcode='23514',message='internal_contract_metering_point_tenant_mismatch';
  end if;

  select option_row.* into v_option from public.contract_price_options option_row
  where option_row.company_id=p_company_id and option_row.contract_product_version_id=v_offer.contract_product_version_id
    and option_row.price_plan_version_id=v_offer.price_plan_version_id and option_row.option_reference=p_selection->>'price_option_reference' and option_row.status='active'
  order by option_row.created_at desc limit 1;
  if not found then raise exception using errcode='23514',message='internal_contract_price_option_not_available'; end if;
  if v_offer.contract_type='fixed' then
    select area_row.* into v_area from public.contract_price_option_area_prices area_row
    where area_row.company_id=p_company_id and area_row.contract_price_option_id=v_option.id
      and area_row.price_row_reference=p_selection->>'area_price_reference' and area_row.price_area=p_selection->>'price_area';
    if not found then raise exception using errcode='23514',message='internal_contract_area_price_not_available'; end if;
  end if;

  v_selected_refs:=array(select value from jsonb_array_elements_text(coalesce(p_selection->'selected_component_references','[]'::jsonb)));
  select count(*) into v_resolved_count from jsonb_array_elements(p_selection->'price_components_snapshot') component
  where coalesce(component->>'componentReference',component->>'component_reference',component#>>'{metadata,component_reference}')=any(v_selected_refs);
  if v_resolved_count<>coalesce(array_length(v_selected_refs,1),0) or exists(
    select 1 from unnest(v_selected_refs) reference where not exists(
      select 1 from public.price_components component where component.company_id=p_company_id
        and component.price_plan_version_id=v_offer.price_plan_version_id and component.component_reference=reference and component.status='active'
    )
  ) then raise exception using errcode='23514',message='internal_contract_component_selection_mismatch'; end if;

  v_publication_version_id:=public.gridex_ensure_internal_contract_publication(p_company_id,v_offer.id,p_actor_user_id);
  if v_publication_version_id is null then raise exception using errcode='23514',message='internal_contract_publication_version_missing'; end if;
  select pricing_model into v_pricing_model from public.contract_product_versions where id=v_offer.contract_product_version_id;
  v_snapshot:=private.gridex_normalize_fixed_area_snapshot_v1(p_selection);

  insert into public.customer_contracts(
    company_id,customer_id,site_id,customer_site_id,metering_point_id,contract_offer_id,contract_product_id,contract_product_version_id,
    contract_publication_version_id,price_plan_id,price_plan_version_id,price_book_id,legal_bundle_version_id,source_type,status,contract_name,contract_type,
    energy_direction,offer_reference,commercial_snapshot,price_snapshot,monthly_fee_sek,invoice_fee_sek,fixed_price_ore_per_kwh,
    binding_months,notice_months,optional_fee_lines,agreement_channel,starts_at,ends_at,signed_at,auto_renew_enabled,auto_renew_term_months,
    override_reason,metadata,created_by,updated_by
  ) values(
    p_company_id,p_customer_id,p_site_id,p_site_id,p_metering_point_id,v_offer.id,v_offer.contract_product_id,v_offer.contract_product_version_id,
    v_publication_version_id,v_offer.price_plan_id,v_offer.price_plan_version_id,v_offer.price_book_id,v_offer.legal_bundle_version_id,'catalog','draft',
    coalesce(nullif(p_contract->>'contract_name',''),v_offer.name),v_offer.contract_type,v_offer.energy_direction,
    (select cpv.offer_reference from public.contract_publication_versions cpv where cpv.id=v_publication_version_id),v_snapshot,v_snapshot,
    (select (component->>'amount')::numeric from jsonb_array_elements(v_snapshot->'price_components_snapshot') component where coalesce(component->>'componentCode',component->>'component_code',component#>>'{metadata,component_code}')='monthly_fee' limit 1),
    (select (component->>'amount')::numeric from jsonb_array_elements(v_snapshot->'price_components_snapshot') component where coalesce(component->>'componentCode',component->>'component_code',component#>>'{metadata,component_code}') in ('invoice_administration_fee','invoice_fee') limit 1),
    case when v_offer.contract_type='fixed' then case when v_area.unit='sek_per_kwh' then v_area.amount*100 else v_area.amount end else null end,
    v_option.binding_months,v_option.notice_months,v_snapshot->'price_components_snapshot','internal',nullif(p_contract->>'starts_at','')::date,
    nullif(p_contract->>'ends_at','')::date,null,v_option.auto_renew_enabled,v_option.renewal_term_months,nullif(p_contract->>'override_reason',''),
    jsonb_build_object('source_of_truth','contract_price_options','price_option_reference',v_option.option_reference,'area_price_reference',v_area.price_row_reference,
      'invoice_delivery_method',p_selection->>'invoice_delivery_method','selected_component_references',to_jsonb(v_selected_refs)),p_actor_user_id,p_actor_user_id
  ) returning * into v_contract;

  insert into public.contract_price_snapshots(
    company_id,contract_id,customer_id,source,price_plan_version_id,pricing_model,base_price_components_snapshot,price_components_snapshot,
    snapshot_json,valid_from,valid_to,snapshot_schema_version,price_option_reference,area_price_reference,invoice_delivery_method,
    selected_component_references,snapshot_hash,snapshot_quality
  ) values(
    p_company_id,v_contract.id,p_customer_id,'internal_customer_contract_selection',v_offer.price_plan_version_id,coalesce(v_pricing_model,'spot'),
    v_snapshot->'base_price_components_snapshot',v_snapshot->'price_components_snapshot',v_snapshot,
    coalesce(nullif(p_contract->>'starts_at','')::date,current_date),nullif(p_contract->>'ends_at','')::date,
    'gridex_contract_pricing_v6_selection',v_option.option_reference,v_area.price_row_reference,p_selection->>'invoice_delivery_method',v_selected_refs,
    encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex'),'canonical'
  ) returning id into v_snapshot_id;

  update public.customer_contracts set contract_price_snapshot_id=v_snapshot_id,updated_at=now() where id=v_contract.id and company_id=p_company_id returning * into v_contract;
  return jsonb_build_object('ok',true,'contract',to_jsonb(v_contract),'contract_price_snapshot_id',v_snapshot_id,
    'price_option_reference',v_option.option_reference,'area_price_reference',v_area.price_row_reference,'selected_component_references',to_jsonb(v_selected_refs));
end
$$;

--
-- Name: gridex_create_invoice_export_file_v1(uuid, text, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_invoice_export_file_v1(p_company_id uuid, p_billing_month text, p_environment text, p_actor_user_id uuid, p_rows jsonb, p_rows_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  c record;
  v_ids uuid[];
  v_locked integer;
  v_file_id uuid := gen_random_uuid();
  v_total numeric;
  r jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'invoice_file_actor_required' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'invoice_file_empty' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_export_target_system, billing_provider_environment, invoice_export_enabled
    INTO c FROM public.companies WHERE id = p_company_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'company_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF c.invoice_export_target_system IS DISTINCT FROM 'file_export'
     OR c.billing_provider_environment IS DISTINCT FROM p_environment
     OR c.invoice_export_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'invoice_file_provider_not_active' USING ERRCODE = '55000';
  END IF;

  SELECT array_agg((x->>'invoice_export_item_id')::uuid) INTO v_ids FROM jsonb_array_elements(p_rows) x;
  IF v_ids IS NULL OR cardinality(v_ids) <> (SELECT count(DISTINCT u) FROM unnest(v_ids) u) THEN
    RAISE EXCEPTION 'invoice_file_rows_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_locked FROM (
    SELECT i.id FROM public.invoice_export_items i
      JOIN public.invoice_export_runs run ON run.id = i.export_run_id AND run.company_id = i.company_id
     WHERE i.company_id = p_company_id
       AND i.id = ANY (v_ids)
       AND i.status = 'pending'
       AND i.export_file_id IS NULL
       AND i.metadata->'approval'->>'status' = 'approved'
       AND run.provider = 'file_export'
       AND run.environment = p_environment
       AND run.billing_month = p_billing_month
     FOR UPDATE OF i
  ) locked;
  IF v_locked <> cardinality(v_ids) THEN
    RAISE EXCEPTION 'invoice_file_items_changed' USING ERRCODE = '40001';
  END IF;

  SELECT coalesce(sum((x->>'amount_inc_vat')::numeric), 0) INTO v_total FROM jsonb_array_elements(p_rows) x;

  INSERT INTO public.invoice_export_files (id, company_id, billing_month, environment, row_count, total_inc_vat, rows, rows_sha256, created_by)
  VALUES (v_file_id, p_company_id, p_billing_month, p_environment, cardinality(v_ids), v_total, p_rows, p_rows_sha256, p_actor_user_id);

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    UPDATE public.invoice_export_items
       SET status = 'sent', export_file_id = v_file_id, provider_status = 'exported_to_file',
           sent_at = now(), next_retry_at = NULL, error_code = NULL, updated_at = now()
     WHERE company_id = p_company_id AND id = (r->>'invoice_export_item_id')::uuid;
    UPDATE public.customer_invoices
       SET status = 'sent', issued_at = (r->>'invoice_date')::date, due_date = (r->>'due_date')::date,
           partner_invoice_reference = 'file:' || v_file_id::text, updated_at = now()
     WHERE company_id = p_company_id AND invoice_export_item_id = (r->>'invoice_export_item_id')::uuid
       AND status = 'draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invoice_file_invoice_mirror_missing' USING ERRCODE = '40001';
    END IF;
  END LOOP;

  UPDATE public.invoice_export_runs run
     SET status = 'sent', sent_items = (SELECT count(*) FROM public.invoice_export_items i
                                         WHERE i.company_id = run.company_id AND i.export_run_id = run.id AND i.status = 'sent'),
         finished_at = now(), updated_at = now()
   WHERE run.company_id = p_company_id
     AND run.id IN (SELECT export_run_id FROM public.invoice_export_items WHERE company_id = p_company_id AND id = ANY (v_ids))
     AND NOT EXISTS (SELECT 1 FROM public.invoice_export_items i
                      WHERE i.company_id = run.company_id AND i.export_run_id = run.id AND i.status <> 'sent');

  INSERT INTO public.audit_logs (company_id, actor_user_id, actor_type, entity_type, entity_id, action,
                                 new_values, metadata, resource_type, resource_id)
  VALUES (p_company_id, p_actor_user_id, 'user', 'invoice_export_file', v_file_id::text, 'invoice_file_created',
          jsonb_build_object('billing_month', p_billing_month, 'row_count', cardinality(v_ids), 'total_inc_vat', v_total),
          jsonb_build_object('environment', p_environment, 'rows_sha256', p_rows_sha256),
          'invoice_export_file', v_file_id::text);

  RETURN v_file_id;
END $$;

--
-- Name: gridex_create_invoice_export_graph_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_invoice_export_graph_v1(p_run jsonb, p_items jsonb, p_invoices jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_run->>'company_id', '')::uuid;
  v_idempotency_key text := nullif(p_run->>'idempotency_key', '');
  v_core_run jsonb := p_run - array['legacy_run', 'legacy_items'];
  v_logical_items jsonb;
  v_logical_invoices jsonb;
  v_payload_hash text;
  v_existing_run_id uuid;
  v_existing_payload_hash text;
  v_legacy_existing_id uuid;
  v_core_result jsonb;
  v_legacy_result jsonb;
  v_event_id uuid;
  v_item jsonb;
  v_invoice jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'invoice_export_graph_service_role_required';
  end if;
  if v_company_id is null or v_idempotency_key is null then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_company_idempotency_required';
  end if;
  if jsonb_typeof(coalesce(p_run->'legacy_run', 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_run->'legacy_items', 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_items, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_invoices, 'null'::jsonb)) <> 'array' then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_graph_payload_invalid';
  end if;
  if jsonb_array_length(p_items) <> jsonb_array_length(p_invoices) then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_graph_array_mismatch';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item->'total_kwh') <> 'number'
       or jsonb_typeof(v_item->'amount_ex_vat') <> 'number'
       or jsonb_typeof(v_item->'vat_amount') <> 'number'
       or jsonb_typeof(v_item->'amount_inc_vat') <> 'number'
       or nullif(v_item->>'currency', '') is null then
      raise exception using
        errcode = '22023',
        message = 'invoice_export_item_financial_values_required';
    end if;
  end loop;
  for v_invoice in select value from jsonb_array_elements(p_invoices)
  loop
    if jsonb_typeof(v_invoice->'total_kwh') <> 'number'
       or jsonb_typeof(v_invoice->'amount_ex_vat') <> 'number'
       or jsonb_typeof(v_invoice->'vat_amount') <> 'number'
       or jsonb_typeof(v_invoice->'amount_inc_vat') <> 'number'
       or nullif(v_invoice->>'currency', '') is null then
      raise exception using
        errcode = '22023',
        message = 'customer_invoice_financial_values_required';
    end if;
  end loop;

  select coalesce(
    jsonb_agg(
      value - array['id', 'metadata', 'idempotency_key']
      order by value->>'billing_underlay_id'
    ),
    '[]'::jsonb
  )
  into v_logical_items
  from jsonb_array_elements(p_items);

  select coalesce(
    jsonb_agg(
      value - array['invoice_export_item_id', 'metadata']
      order by value->>'customer_id', value->>'period_start'
    ),
    '[]'::jsonb
  )
  into v_logical_invoices
  from jsonb_array_elements(p_invoices);

  v_payload_hash := encode(
    digest(
      jsonb_build_object(
        'run',
          v_core_run - array[
            'id',
            'requested_by',
            'idempotency_key',
            'payload_hash'
          ],
        'items', v_logical_items,
        'invoices', v_logical_invoices
      )::text,
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(
    hashtextextended(v_company_id::text || ':' || v_idempotency_key, 0)
  );

  select run.id, run.payload_hash
  into v_existing_run_id, v_existing_payload_hash
  from public.invoice_export_runs run
  where run.company_id = v_company_id
    and run.idempotency_key = v_idempotency_key
  for update;

  if v_existing_run_id is not null
     and v_existing_payload_hash is not null
     and v_existing_payload_hash <> v_payload_hash then
    raise exception using
      errcode = '23505',
      message = 'invoice_export_idempotency_payload_mismatch';
  end if;

  -- If a compatibility run predates the canonical graph, preserve its durable
  -- identity when creating the canonical side.
  select run.id
  into v_legacy_existing_id
  from public.billing_export_runs run
  where run.company_id = v_company_id
    and run.idempotency_key = v_idempotency_key
  for update;
  if v_existing_run_id is null and v_legacy_existing_id is not null then
    v_core_run := jsonb_set(
      v_core_run,
      '{id}',
      to_jsonb(v_legacy_existing_id::text),
      true
    );
  end if;

  v_core_result :=
    public.gridex_create_invoice_export_graph_v1_core(
      v_core_run,
      p_items,
      p_invoices
    );
  v_existing_run_id := nullif(v_core_result->>'run_id', '')::uuid;
  if v_existing_run_id is null then
    raise exception using
      errcode = '23502',
      message = 'invoice_export_graph_result_missing_run_id';
  end if;

  update public.invoice_export_runs
  set payload_hash = coalesce(payload_hash, v_payload_hash),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'payload_hash', v_payload_hash,
          'canonical_runtime', 'gridex_create_invoice_export_graph_v1'
        )
  where id = v_existing_run_id
    and company_id = v_company_id;

  v_legacy_result := public.gridex_create_billing_export_run(
    jsonb_set(
      p_run->'legacy_run',
      '{id}',
      to_jsonb(v_existing_run_id::text),
      true
    ) || jsonb_build_object(
      'idempotency_key', v_idempotency_key,
      'payload_hash', v_payload_hash
    ),
    p_run->'legacy_items'
  );
  if nullif(v_legacy_result->>'id', '')::uuid
       is distinct from v_existing_run_id then
    raise exception using
      errcode = '23514',
      message = 'invoice_export_compatibility_run_identity_mismatch';
  end if;
  update public.billing_export_runs
  set payload_hash = coalesce(payload_hash, v_payload_hash),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'canonical_invoice_export_run_id', v_existing_run_id,
          'payload_hash', v_payload_hash
        )
  where id = v_existing_run_id
    and company_id = v_company_id;
  select to_jsonb(run)
  into v_legacy_result
  from public.billing_export_runs run
  where run.id = v_existing_run_id
    and run.company_id = v_company_id;

  if not coalesce((v_core_result->>'existing')::boolean, false) then
    insert into public.domain_events(
      company_id,
      event_type,
      aggregate_type,
      aggregate_id,
      actor_user_id,
      source,
      idempotency_key,
      payload
    ) values (
      v_company_id,
      'invoice.export_graph.created',
      'invoice_export_run',
      v_existing_run_id,
      nullif(p_run->>'requested_by', '')::uuid,
      'gridex_create_invoice_export_graph_v1',
      'invoice-export-created:' || v_existing_run_id::text,
      jsonb_build_object(
        'invoice_export_run_id', v_existing_run_id,
        'item_count', jsonb_array_length(p_items),
        'payload_hash', v_payload_hash
      )
    ) returning id into v_event_id;

    insert into public.event_outbox(
      company_id,
      domain_event_id,
      destination_type,
      destination_key,
      payload
    ) values (
      v_company_id,
      v_event_id,
      'webhook',
      'invoice.export_graph.created',
      jsonb_build_object(
        'domain_event_id', v_event_id,
        'event_type', 'invoice.export_graph.created',
        'invoice_export_run_id', v_existing_run_id
      )
    ) on conflict do nothing;
  end if;

  return v_core_result || jsonb_build_object(
    'payload_hash', v_payload_hash,
    'legacy_run', v_legacy_result
  );
end
$$;

--
-- Name: FUNCTION gridex_create_invoice_export_graph_v1(p_run jsonb, p_items jsonb, p_invoices jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_create_invoice_export_graph_v1(p_run jsonb, p_items jsonb, p_invoices jsonb) IS 'Canonical atomic invoice-export entry point. Reserves canonical export items, invoice mirrors, legacy send projections, domain event and outbox with payload-safe idempotency.';

--
-- Name: gridex_create_invoice_export_graph_v1_core(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_invoice_export_graph_v1_core(p_run jsonb, p_items jsonb, p_invoices jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=nullif(p_run->>'company_id','')::uuid;
  v_run_id uuid:=coalesce(nullif(p_run->>'id','')::uuid,gen_random_uuid());
  v_idempotency_key text:=nullif(p_run->>'idempotency_key','');
  v_existing_id uuid;
  v_item jsonb;
  v_invoice jsonb;
  v_underlay public.billing_underlays%rowtype;
  v_export_item_id uuid;
  v_count integer:=0;
begin
  if auth.role()<>'service_role' then
    raise exception using errcode='42501',message='invoice_export_graph_service_role_required';
  end if;
  if v_company_id is null or v_idempotency_key is null then
    raise exception using errcode='22023',message='invoice_export_company_idempotency_required';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array'
     or jsonb_typeof(coalesce(p_invoices,'[]'::jsonb))<>'array'
     or jsonb_array_length(coalesce(p_items,'[]'::jsonb))
        <>jsonb_array_length(coalesce(p_invoices,'[]'::jsonb)) then
    raise exception using errcode='22023',message='invoice_export_graph_array_mismatch';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended(v_company_id::text||':'||v_idempotency_key,0)
  );
  select id into v_existing_id
  from public.invoice_export_runs
  where company_id=v_company_id and idempotency_key=v_idempotency_key;
  if v_existing_id is not null then
    return jsonb_build_object('run_id',v_existing_id,'existing',true);
  end if;

  insert into public.invoice_export_runs(
    id,company_id,provider,environment,billing_month,financing_mode,status,
    total_items,readiness_snapshot,metadata,requested_by,idempotency_key
  ) values (
    v_run_id,v_company_id,coalesce(nullif(p_run->>'provider',''),'capway_aptic'),
    coalesce(nullif(p_run->>'environment',''),'test'),p_run->>'billing_month',
    coalesce(nullif(p_run->>'financing_mode',''),'invoice_service'),'draft',
    jsonb_array_length(p_items),coalesce(p_run->'readiness_snapshot','{}'::jsonb),
    coalesce(p_run->'metadata','{}'::jsonb),nullif(p_run->>'requested_by','')::uuid,
    v_idempotency_key
  );

  for v_item,v_invoice in
    select i.value,n.value
    from jsonb_array_elements(p_items) with ordinality i(value,ordinality)
    join jsonb_array_elements(p_invoices) with ordinality n(value,ordinality)
      using(ordinality)
  loop
    v_export_item_id:=nullif(v_item->>'id','')::uuid;
    select * into v_underlay
    from public.billing_underlays
    where id=nullif(v_item->>'billing_underlay_id','')::uuid
      and company_id=v_company_id
    for share;
    if not found
       or v_underlay.customer_id is distinct from nullif(v_item->>'customer_id','')::uuid
       or coalesce(v_underlay.customer_contract_id,v_underlay.contract_id)
          is distinct from nullif(v_item->>'customer_contract_id','')::uuid then
      raise exception using errcode='23514',message='invoice_export_underlay_customer_contract_mismatch';
    end if;
    insert into public.invoice_export_items(
      id,company_id,export_run_id,customer_id,billing_underlay_id,
      pricing_run_id,customer_contract_id,metering_point_id,period_start,
      period_end,total_kwh,currency,provider,environment,status,financing_mode,
      amount_ex_vat,vat_amount,amount_inc_vat,idempotency_key,metadata
    ) values (
      v_export_item_id,v_company_id,v_run_id,nullif(v_item->>'customer_id','')::uuid,
      v_underlay.id,nullif(v_item->>'pricing_run_id','')::uuid,
      nullif(v_item->>'customer_contract_id','')::uuid,
      nullif(v_item->>'metering_point_id','')::uuid,
      nullif(v_item->>'period_start','')::date,nullif(v_item->>'period_end','')::date,
      nullif(v_item->>'total_kwh','')::numeric,
      coalesce(nullif(v_item->>'currency',''),'SEK'),
      coalesce(nullif(v_item->>'provider',''),'capway_aptic'),
      coalesce(nullif(v_item->>'environment',''),'test'),'pending',
      coalesce(nullif(v_item->>'financing_mode',''),'invoice_service'),
      coalesce(nullif(v_item->>'amount_ex_vat','')::numeric,0),
      coalesce(nullif(v_item->>'vat_amount','')::numeric,0),
      coalesce(nullif(v_item->>'amount_inc_vat','')::numeric,0),
      nullif(v_item->>'idempotency_key',''),coalesce(v_item->'metadata','{}'::jsonb)
    );
    if nullif(v_invoice->>'invoice_export_item_id','')::uuid is distinct from v_export_item_id
       or nullif(v_invoice->>'customer_id','')::uuid is distinct from v_underlay.customer_id
       or nullif(v_invoice->>'customer_contract_id','')::uuid
          is distinct from coalesce(v_underlay.customer_contract_id,v_underlay.contract_id) then
      raise exception using errcode='23514',message='customer_invoice_export_identity_mismatch';
    end if;
    insert into public.customer_invoices(
      company_id,customer_id,contract_id,customer_contract_id,
      billing_underlay_id,partner_export_id,partner_invoice_reference,invoice_export_item_id,
      canonical_export_item_id,
      period_start,period_end,total_kwh,amount_ex_vat,vat_amount,amount_inc_vat,
      currency,status,source_system,metadata,updated_at
    ) values (
      v_company_id,v_underlay.customer_id,
      coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),
      coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),
      v_underlay.id,v_export_item_id,
      coalesce(
        nullif(v_invoice->>'partner_invoice_reference',''),
        'pending:' || v_export_item_id::text
      ),
      v_export_item_id,v_export_item_id,
      nullif(v_invoice->>'period_start','')::date,
      nullif(v_invoice->>'period_end','')::date,
      nullif(v_invoice->>'total_kwh','')::numeric,
      coalesce(nullif(v_invoice->>'amount_ex_vat','')::numeric,0),
      coalesce(nullif(v_invoice->>'vat_amount','')::numeric,0),
      coalesce(nullif(v_invoice->>'amount_inc_vat','')::numeric,0),
      coalesce(nullif(v_invoice->>'currency',''),'SEK'),'draft',
      'canonical_invoice_export',coalesce(v_invoice->'metadata','{}'::jsonb),now()
    );
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object(
    'run_id',v_run_id,'existing',false,'item_count',v_count
  );
end
$$;

--
-- Name: gridex_create_invoice_review_draft_v1(uuid, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_invoice_review_draft_v1(p_company_id uuid, p_run jsonb, p_items jsonb, p_invoices jsonb, p_enrichment jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_item_id uuid := nullif(p_enrichment->>'invoice_export_item_id', '')::uuid;
  v_invoice_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'invoice_review_draft_service_role_required';
  end if;
  if p_company_id is null or v_item_id is null
     or nullif(p_run->>'company_id', '')::uuid is distinct from p_company_id then
    raise exception using errcode = '22023', message = 'invoice_review_draft_payload_invalid';
  end if;

  v_result := public.gridex_create_invoice_export_graph_v1(p_run, p_items, p_invoices);

  update public.customer_invoices
  set price_plan_version_id = nullif(p_enrichment->>'price_plan_version_id', '')::uuid,
      price_area_code = nullif(p_enrichment->>'price_area_code', ''),
      consumption_kwh = nullif(p_enrichment->>'consumption_kwh', '')::numeric,
      vat_rate = nullif(p_enrichment->>'vat_rate', '')::numeric,
      calculation_snapshot = p_enrichment->'calculation_snapshot',
      calculation_snapshot_sha256 = nullif(p_enrichment->>'calculation_snapshot_sha256', ''),
      metadata = coalesce(p_enrichment->'metadata', metadata),
      updated_at = now()
  where company_id = p_company_id
    and invoice_export_item_id = v_item_id
  returning id into v_invoice_id;
  if v_invoice_id is null then
    raise exception using errcode = 'P0002', message = 'invoice_review_draft_invoice_missing';
  end if;

  return v_result || jsonb_build_object('invoice_id', v_invoice_id);
end
$$;

--
-- Name: gridex_create_legal_template_version(text, text, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_legal_template_version(p_module_key text, p_version_label text, p_title text, p_body text, p_publish boolean DEFAULT false, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_template_id uuid; v_version_id uuid; v_number integer; v_hash text;
  v_variables text[];
begin
  if nullif(btrim(p_module_key),'') is null or nullif(btrim(p_title),'') is null or nullif(btrim(p_body),'') is null then
    raise exception using errcode='22023',message='module_title_body_required';
  end if;
  select id into v_template_id from public.legal_templates
  where module_key=p_module_key and status='active';
  if v_template_id is null then
    raise exception using errcode='P0002',message='canonical_legal_module_not_found';
  end if;

  v_hash:=encode(digest(btrim(p_title)||E'\n'||p_body,'sha256'),'hex');
  select id into v_version_id from public.legal_template_versions
  where legal_template_id=v_template_id and content_sha256=v_hash limit 1;
  if v_version_id is not null then return v_version_id; end if;

  select coalesce(max(version_number),0)+1 into v_number
  from public.legal_template_versions where legal_template_id=v_template_id;
  select coalesce(array_agg(distinct m[1] order by m[1]),'{}'::text[]) into v_variables
  from regexp_matches(p_title||E'\n'||p_body,'\{\{[[:space:]]*([a-zA-Z0-9_.-]+)[[:space:]]*\}\}','g') as m;

  insert into public.legal_template_versions(
    legal_template_id,version_number,version_label,title,body,variables,content_sha256,status,
    reviewed_by,reviewed_at,published_at,locked_at,created_by
  ) values(
    v_template_id,v_number,coalesce(nullif(btrim(p_version_label),''),v_number::text),btrim(p_title),p_body,
    v_variables,v_hash,case when p_publish then 'published' else 'draft' end,
    case when p_publish then p_actor_user_id end,case when p_publish then now() end,
    case when p_publish then now() end,case when p_publish then now() end,p_actor_user_id
  ) returning id into v_version_id;
  return v_version_id;
end $$;

--
-- Name: gridex_create_or_version_contract_pricing(uuid, text, text, text, text, jsonb, date, date, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_or_version_contract_pricing(p_company_id uuid, p_plan_name text, p_contract_type text, p_pricing_model text, p_customer_type text, p_snapshot jsonb, p_valid_from date DEFAULT NULL::date, p_valid_to date DEFAULT NULL::date, p_publish boolean DEFAULT false, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_plan_id uuid; v_version_id uuid; v_book_id uuid; v_previous_version_id uuid;
  v_plan_code text; v_hash text; v_version_number integer; v_version_label text;
  v_now timestamptz:=now(); v_component jsonb; v_reused boolean:=false;
  v_snapshot jsonb; v_areas text[];
begin
  if p_company_id is null or not exists(select 1 from public.companies where id=p_company_id) then
    raise exception 'Bolaget hittades inte.' using errcode='23503';
  end if;
  if nullif(btrim(p_plan_name),'') is null then raise exception 'Avtalsnamn krävs.'; end if;
  if jsonb_typeof(p_snapshot)<>'object' then raise exception 'Prissnapshot måste vara ett JSON-objekt.'; end if;
  if p_valid_from is not null and p_valid_to is not null and p_valid_to<p_valid_from then raise exception 'Slutdatum får inte ligga före startdatum.'; end if;
  if p_customer_type not in ('private','business','both') then raise exception 'Ogiltig kundtyp.'; end if;
  if p_pricing_model not in ('spot','fixed','portfolio','mixed','manual_override') then raise exception 'Ogiltig prismodell.'; end if;

  v_snapshot:=p_snapshot;
  if coalesce((v_snapshot->>'vat_rate')::numeric,0)>1 then
    v_snapshot:=jsonb_set(v_snapshot,'{vat_rate}',to_jsonb(((v_snapshot->>'vat_rate')::numeric/100)),true);
  end if;
  if not (v_snapshot ? 'vat_rate') then v_snapshot:=jsonb_set(v_snapshot,'{vat_rate}','0.25'::jsonb,true); end if;
  select coalesce(array_agg(value order by value),'{}') into v_areas
  from jsonb_array_elements_text(coalesce(v_snapshot->'price_areas','[]'::jsonb));
  if exists(select 1 from unnest(v_areas) a where a not in ('SE1','SE2','SE3','SE4')) then raise exception 'Ogiltigt prisområde.'; end if;
  if p_publish and coalesce(array_length(v_areas,1),0)=0 then raise exception 'Minst ett prisområde krävs för publicering.'; end if;

  v_plan_code:=lower(trim(both '-' from regexp_replace(
    coalesce(nullif(v_snapshot->>'plan_code',''),nullif(v_snapshot->>'product_key',''),p_plan_name),
    '[^a-zA-Z0-9]+','-','g')));
  v_plan_code:=left(v_plan_code,80);
  v_hash:=encode(digest(v_snapshot::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_plan_code,0));
  perform set_config('gridex.pricing_version_write','on',true);

  insert into public.price_plans(company_id,plan_code,name,pricing_model,customer_type,status,created_by,updated_by)
  values(p_company_id,v_plan_code,btrim(p_plan_name),p_pricing_model,p_customer_type,case when p_publish then 'active' else 'draft' end,p_actor_user_id,p_actor_user_id)
  on conflict(company_id,plan_code) do update set
    name=excluded.name,pricing_model=excluded.pricing_model,customer_type=excluded.customer_type,
    status=case when p_publish then 'active' else public.price_plans.status end,
    updated_by=excluded.updated_by,updated_at=now()
  returning id into v_plan_id;

  select id,version_number,version_label into v_version_id,v_version_number,v_version_label
  from public.price_plan_versions
  where company_id=p_company_id and price_plan_id=v_plan_id and content_sha256=v_hash
  order by created_at limit 1;
  v_reused:=v_version_id is not null;

  if v_version_id is null then
    select id into v_previous_version_id from public.price_plan_versions where price_plan_id=v_plan_id order by version_number desc limit 1;
    select coalesce(max(version_number),0)+1 into v_version_number from public.price_plan_versions where price_plan_id=v_plan_id;
    v_version_label:='v'||v_version_number::text;
    insert into public.price_plan_versions(company_id,price_plan_id,version_number,version_label,status,valid_from,valid_to,snapshot_json,content_sha256,approved_at,approved_by,published_at,locked_at,supersedes_version_id,created_by,updated_at)
    values(p_company_id,v_plan_id,v_version_number,v_version_label,case when p_publish then 'published' else 'draft' end,p_valid_from,p_valid_to,v_snapshot,v_hash,
      case when p_publish then v_now end,case when p_publish then p_actor_user_id end,case when p_publish then v_now end,case when p_publish then v_now end,v_previous_version_id,p_actor_user_id,v_now)
    returning id into v_version_id;

    for v_component in select value from jsonb_array_elements(coalesce(v_snapshot->'base_components','[]'::jsonb)) loop
      if p_publish and nullif(v_component->>'price_area','') is null then raise exception 'Alla baspriskomponenter måste ha prisområde.'; end if;
      insert into public.base_price_components(company_id,price_plan_version_id,source_type,label,weight_percent,fixed_price_sek_per_kwh,price_area,valid_from,valid_to,status,metadata,created_by)
      values(p_company_id,v_version_id,coalesce(v_component->>'source_type','manual'),v_component->>'label',coalesce((v_component->>'weight_percent')::numeric,100),
        nullif(v_component->>'fixed_price_sek_per_kwh','')::numeric,nullif(v_component->>'price_area',''),p_valid_from,p_valid_to,
        case when p_publish then 'active' else 'draft' end,coalesce(v_component->'metadata','{}'::jsonb),p_actor_user_id);
    end loop;

    for v_component in select value from jsonb_array_elements(coalesce(v_snapshot->'price_components','[]'::jsonb)) loop
      if (v_component->>'unit') not in ('sek_month','sek_invoice','sek_once','sek_contract','sek_event','ore_per_kwh','sek_per_kwh','percent','percentage') then
        raise exception 'Ogiltig priskomponentenhet: %',v_component->>'unit';
      end if;
      insert into public.price_components(company_id,price_plan_version_id,component_type,name,description,calculation_type,calculation_base,amount,unit,vat_applicable,invoice_line_visible,website_card_visible,periodization_mode,priority,valid_from,valid_to,status,metadata,created_by)
      values(p_company_id,v_version_id,coalesce(v_component->>'component_type','fee'),coalesce(v_component->>'name',v_component->>'component_code','Avgift'),v_component->>'description',
        coalesce(v_component->>'calculation_type','fixed_once'),nullif(v_component->>'calculation_base',''),(v_component->>'amount')::numeric,v_component->>'unit',coalesce((v_component->>'vat_applicable')::boolean,true),
        coalesce((v_component->>'invoice_line_visible')::boolean,true),coalesce((v_component->>'website_card_visible')::boolean,(v_component#>>'{metadata,visibility,website_card}')::boolean,true),
        coalesce(v_component->>'periodization_mode','none'),coalesce((v_component->>'priority')::integer,100),
        p_valid_from,p_valid_to,case when p_publish then 'active' else 'draft' end,
        coalesce(v_component->'metadata','{}'::jsonb)||jsonb_build_object('component_code',v_component->>'component_code','calculation_base',nullif(v_component->>'calculation_base','')),p_actor_user_id);
    end loop;
  elsif p_publish then
    update public.price_plan_versions set status='published',approved_at=coalesce(approved_at,v_now),approved_by=coalesce(approved_by,p_actor_user_id),published_at=coalesce(published_at,v_now),locked_at=coalesce(locked_at,v_now),updated_at=v_now where id=v_version_id;
    update public.base_price_components set status='active' where price_plan_version_id=v_version_id and status='draft';
    update public.price_components set status='active' where price_plan_version_id=v_version_id and status='draft';
  end if;

  select id into v_book_id from public.price_books where company_id=p_company_id and price_plan_version_id=v_version_id and content_sha256=v_hash order by created_at limit 1;
  if v_book_id is null then
    insert into public.price_books(company_id,name,status,valid_from,valid_to,price_plan_id,price_plan_version_id,content_sha256,published_at,locked_at)
    values(p_company_id,'Prislista · '||btrim(p_plan_name)||' · '||v_version_label,case when p_publish then 'published' else 'draft' end,p_valid_from,p_valid_to,v_plan_id,v_version_id,v_hash,case when p_publish then v_now end,case when p_publish then v_now end)
    returning id into v_book_id;
    insert into public.price_book_lines(price_book_id,sort_order,component_key,value,unit,metadata)
    values(v_book_id,10,'price_plan_version',null,'reference',jsonb_build_object('price_plan_id',v_plan_id,'price_plan_version_id',v_version_id,'version_number',v_version_number,'version_label',v_version_label,'content_sha256',v_hash,'snapshot',v_snapshot));
    for v_component in select value from jsonb_array_elements(coalesce(v_snapshot->'price_components','[]'::jsonb)) loop
      insert into public.price_book_lines(price_book_id,sort_order,component_key,value,unit,metadata)
      values(v_book_id,100+coalesce((v_component->>'priority')::integer,100),coalesce(v_component->>'component_code',v_component->>'component_type','fee'),(v_component->>'amount')::numeric,v_component->>'unit',v_component);
    end loop;
  elsif p_publish then
    update public.price_books set status='published',published_at=coalesce(published_at,v_now),locked_at=coalesce(locked_at,v_now),updated_at=v_now where id=v_book_id;
  end if;

  return jsonb_build_object('price_plan_id',v_plan_id,'price_plan_version_id',v_version_id,'price_book_id',v_book_id,'version_number',v_version_number,'version_label',v_version_label,'content_sha256',v_hash,'reused',v_reused,'snapshot',v_snapshot);
end $$;

--
-- Name: gridex_create_partner_contract_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_partner_contract_v1(p_company_id uuid, p_api_client_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_offer jsonb;
  v_customer jsonb := coalesce(p_payload->'customer', '{}'::jsonb);
  v_site jsonb := coalesce(p_payload->'site', '{}'::jsonb);
  v_agreement jsonb := coalesce(p_payload->'agreement', '{}'::jsonb);
  v_poa jsonb := coalesce(p_payload->'power_of_attorney', '{}'::jsonb);
  v_customer_type text := lower(coalesce(nullif(btrim(v_customer->>'type'), ''), nullif(btrim(v_customer->>'customer_type'), ''), 'private'));
  v_site_type text := lower(coalesce(nullif(btrim(v_site->>'electricity_type'), ''), nullif(btrim(v_site->>'site_electricity_type'), ''), 'consumption'));
  v_offer_reference text := nullif(btrim(p_payload->>'offer_reference'), '');
  v_external_customer_id text := nullif(btrim(coalesce(v_customer->>'external_customer_id', p_payload->>'external_customer_id')), '');
  v_identity_number text := regexp_replace(coalesce(v_customer->>'identity_number', v_customer->>'soc_id', ''), '[^0-9]', '', 'g');
  v_org_number text := regexp_replace(coalesce(v_customer->>'organization_number', v_customer->>'org_number', ''), '[^0-9]', '', 'g');
  v_email text := lower(nullif(btrim(v_customer->>'email'), ''));
  v_customer_id uuid;
  v_site_id uuid;
  v_contract_id uuid;
  v_poa_id uuid;
  v_customer_reference text;
  v_site_reference text;
  v_contract_reference text;
  v_poa_reference text;
  v_customer_number text;
  v_contract_name text;
  v_contract_type text;
  v_energy_direction text;
  v_publication_version_id uuid;
  v_contract_product_version_id uuid;
  v_contract_product_id uuid;
  v_price_plan_id uuid;
  v_price_plan_version_id uuid;
  v_price_book_id uuid;
  v_legal_bundle_version_id uuid;
  v_agreement_accepted_at timestamptz;
  v_signed boolean := false;
  v_now timestamptz := now();
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;
  if p_company_id is null or p_api_client_id is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode='22023', message='partner_api_contract_payload_invalid';
  end if;
  if not exists (
    select 1
    from public.integration_api_clients c
    where c.id = p_api_client_id
      and c.company_id = p_company_id
      and c.status = 'active'
  ) then
    raise exception using errcode='42501', message='partner_api_client_not_active_for_company';
  end if;

  if v_customer_type = 'company' then
    v_customer_type := 'business';
  end if;
  if v_customer_type not in ('private', 'business', 'association') then
    raise exception using errcode='22023', message='partner_api_customer_type_invalid';
  end if;
  if v_site_type = 'production' then
    v_energy_direction := 'production';
  elsif v_site_type = 'consumption' then
    v_energy_direction := 'consumption';
  else
    raise exception using errcode='22023', message='partner_api_site_electricity_type_invalid';
  end if;
  if v_offer_reference is null then
    raise exception using errcode='22023', message='partner_api_offer_reference_required';
  end if;
  if v_email is null or position('@' in v_email) <= 1 then
    raise exception using errcode='22023', message='partner_api_customer_email_required';
  end if;
  if v_external_customer_id is null then
    raise exception using errcode='22023', message='partner_api_external_customer_id_required';
  end if;
  if v_customer_type = 'private' and length(v_identity_number) < 10 then
    raise exception using errcode='22023', message='partner_api_customer_identity_number_required';
  end if;
  if v_customer_type in ('business','association') and length(v_org_number) < 10 then
    raise exception using errcode='22023', message='partner_api_customer_organization_number_required';
  end if;
  if nullif(btrim(coalesce(v_site->>'street', v_site->>'address', '')), '') is null
     or nullif(btrim(coalesce(v_site->>'postal_code', v_site->>'zip_code', '')), '') is null
     or nullif(btrim(v_site->>'city'), '') is null then
    raise exception using errcode='22023', message='partner_api_site_address_required';
  end if;

  v_offer := public.gridex_resolve_partner_api_offer_v1(
    p_company_id,
    v_offer_reference,
    case when v_customer_type = 'association' then null else v_customer_type end
  );
  v_publication_version_id := (v_offer->>'publication_version_id')::uuid;
  v_contract_product_version_id := (v_offer->>'contract_product_version_id')::uuid;
  v_contract_product_id := (v_offer->>'contract_product_id')::uuid;
  v_price_plan_id := nullif(v_offer->>'price_plan_id','')::uuid;
  v_price_plan_version_id := nullif(v_offer->>'price_plan_version_id','')::uuid;
  v_price_book_id := nullif(v_offer->>'price_book_id','')::uuid;
  v_legal_bundle_version_id := nullif(v_offer->>'legal_bundle_version_id','')::uuid;
  v_contract_type := coalesce(nullif(v_offer->>'contract_type',''), 'variable');
  v_energy_direction := coalesce(nullif(v_offer->>'energy_direction',''), v_energy_direction);

  select coalesce(nullif(btrim(cp.name), ''), 'API contract')
  into v_contract_name
  from public.contract_product_versions cpv
  join public.contract_products cp on cp.id = cpv.contract_product_id
  where cpv.id = v_contract_product_version_id
    and (cp.company_id = p_company_id or cp.company_id is null)
  limit 1;
  v_contract_name := coalesce(v_contract_name, 'API contract');

  if nullif(btrim(v_agreement->>'accepted_at'),'') is not null then
    begin
      v_agreement_accepted_at := (v_agreement->>'accepted_at')::timestamptz;
    exception when others then
      raise exception using errcode='22023', message='partner_api_agreement_accepted_at_invalid';
    end;
    v_signed :=
      nullif(btrim(v_agreement->>'signer_name'),'') is not null
      and nullif(btrim(v_agreement->>'evidence_reference'),'') is not null;
    if not v_signed then
      raise exception using errcode='22023', message='partner_api_agreement_evidence_required';
    end if;
  end if;

  insert into public.customers(
    company_id,
    customer_type,
    status,
    first_name,
    last_name,
    full_name,
    company_name,
    personal_number,
    identity_number,
    org_number,
    organization_number,
    email,
    phone,
    source,
    acquisition_channel,
    external_customer_id,
    billing_street,
    billing_postal_code,
    billing_city,
    billing_country,
    metadata
  ) values (
    p_company_id,
    v_customer_type,
    'active',
    nullif(btrim(v_customer->>'first_name'),''),
    nullif(btrim(v_customer->>'last_name'),''),
    nullif(btrim(concat_ws(' ', v_customer->>'first_name', v_customer->>'last_name')),''),
    nullif(btrim(v_customer->>'company_name'),''),
    case when v_customer_type = 'private' then v_identity_number else null end,
    case when v_customer_type = 'private' then v_identity_number else null end,
    case when v_customer_type <> 'private' then v_org_number else null end,
    case when v_customer_type <> 'private' then v_org_number else null end,
    v_email,
    nullif(btrim(coalesce(v_customer->>'phone', v_customer->>'cell_phone')),''),
    'api',
    'partner_api',
    v_external_customer_id,
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,street}', v_customer->>'invoice_address')),''),
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,postal_code}', v_customer->>'zip_code')),''),
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,city}', v_customer->>'city')),''),
    upper(coalesce(nullif(btrim(coalesce(v_customer#>>'{invoice_address,country}', v_customer->>'country')),''), 'SE')),
    jsonb_build_object(
      'source_channel','partner_api',
      'api_client_id',p_api_client_id,
      'external_payload_metadata',coalesce(p_payload->'metadata','{}'::jsonb)
    )
  )
  returning id, customer_reference, customer_number
  into v_customer_id, v_customer_reference, v_customer_number;

  insert into public.customer_sites(
    company_id,
    customer_id,
    site_name,
    site_type,
    status,
    facility_id,
    street,
    address,
    postal_code,
    city,
    country,
    move_in_date,
    annual_consumption_kwh,
    metadata
  ) values (
    p_company_id,
    v_customer_id,
    coalesce(nullif(btrim(v_site->>'name'),''), concat_ws(', ', coalesce(v_site->>'street', v_site->>'address'), v_site->>'city')),
    v_site_type,
    'draft',
    nullif(regexp_replace(coalesce(v_site->>'facility_id',''), '[^0-9]', '', 'g'),''),
    nullif(btrim(coalesce(v_site->>'street', v_site->>'address')),''),
    nullif(btrim(coalesce(v_site->>'address', v_site->>'street')),''),
    nullif(btrim(coalesce(v_site->>'postal_code', v_site->>'zip_code')),''),
    nullif(btrim(v_site->>'city'),''),
    upper(coalesce(nullif(btrim(v_site->>'country'),''), 'SE')),
    case when nullif(btrim(v_site->>'move_in_date'),'') is null then null else (v_site->>'move_in_date')::date end,
    case when nullif(btrim(v_site->>'annual_consumption_kwh'),'') is null then null else (v_site->>'annual_consumption_kwh')::numeric end,
    jsonb_build_object('source_channel','partner_api','api_client_id',p_api_client_id)
  )
  returning id, facility_reference
  into v_site_id, v_site_reference;

  insert into public.customer_contracts(
    company_id,
    customer_id,
    site_id,
    customer_site_id,
    source_type,
    status,
    contract_name,
    contract_type,
    signed_at,
    agreement_channel,
    is_distance_agreement,
    requested_start_date,
    requested_start_mode,
    offer_reference,
    contract_product_id,
    contract_product_version_id,
    contract_publication_version_id,
    legal_bundle_version_id,
    price_plan_id,
    price_plan_version_id,
    price_book_id,
    energy_direction,
    customer_number,
    external_customer_id,
    metadata
  ) values (
    p_company_id,
    v_customer_id,
    v_site_id,
    v_site_id,
    'api',
    case when v_signed then 'signed' else 'pending_signature' end,
    v_contract_name,
    v_contract_type,
    case when v_signed then v_agreement_accepted_at else null end,
    'api',
    coalesce((v_agreement->>'distance_agreement')::boolean, true),
    case when nullif(btrim(p_payload->>'requested_start_date'),'') is null then null else (p_payload->>'requested_start_date')::date end,
    coalesce(nullif(btrim(p_payload->>'requested_start_mode'),''), 'earliest_possible'),
    v_offer_reference,
    v_contract_product_id,
    v_contract_product_version_id,
    v_publication_version_id,
    v_legal_bundle_version_id,
    v_price_plan_id,
    v_price_plan_version_id,
    v_price_book_id,
    v_energy_direction,
    v_customer_number,
    v_external_customer_id,
    jsonb_build_object(
      'source_channel','partner_api',
      'api_client_id',p_api_client_id,
      'agreement_evidence_reference',nullif(btrim(v_agreement->>'evidence_reference'),''),
      'agreement_signer_name',nullif(btrim(v_agreement->>'signer_name'),'')
    )
  )
  returning id, customer_contract_reference
  into v_contract_id, v_contract_reference;

  if jsonb_typeof(p_payload->'power_of_attorney') = 'object'
     and coalesce((v_poa->>'accepted')::boolean, false) then
    insert into public.powers_of_attorney(
      company_id,
      customer_id,
      site_id,
      customer_site_id,
      contract_id,
      customer_contract_id,
      scope,
      status,
      signed_at,
      accepted_at,
      signer_name,
      signer_identity_number,
      method,
      accepted_source,
      source,
      document_path,
      document_hash,
      evidence_payload,
      metadata,
      customer_number,
      external_customer_id
    ) values (
      p_company_id,
      v_customer_id,
      v_site_id,
      v_site_id,
      v_contract_id,
      v_contract_id,
      case
        when lower(coalesce(v_poa->>'transaction_type','switch')) = 'switch' then 'supplier_switch'
        else 'supplier_switch'
      end,
      'signed',
      coalesce(nullif(v_poa->>'accepted_at','')::timestamptz, v_now),
      coalesce(nullif(v_poa->>'accepted_at','')::timestamptz, v_now),
      nullif(btrim(v_poa->>'signer_name'),''),
      nullif(regexp_replace(coalesce(v_poa->>'signer_identity_number',''), '[^0-9]', '', 'g'),''),
      lower(coalesce(nullif(btrim(v_poa->>'poa_type'),''), 'web')),
      'partner_api',
      'partner_api',
      nullif(btrim(v_poa->>'document_path'),''),
      nullif(btrim(v_poa->>'document_sha256'),''),
      jsonb_build_object(
        'evidence_reference', nullif(btrim(v_poa->>'evidence_reference'),''),
        'transaction_type', upper(coalesce(nullif(btrim(v_poa->>'transaction_type'),''), 'SWITCH'))
      ),
      jsonb_build_object('source_channel','partner_api','api_client_id',p_api_client_id),
      v_customer_number,
      v_external_customer_id
    )
    returning id, power_of_attorney_reference
    into v_poa_id, v_poa_reference;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'contract_reference', v_contract_reference,
    'status', case when v_signed then 'signed' else 'pending_signature' end,
    'customer', jsonb_build_object(
      'customer_reference', v_customer_reference,
      'customer_number', v_customer_number
    ),
    'site', jsonb_build_object('site_reference', v_site_reference),
    'power_of_attorney',
      case when v_poa_reference is null then null
           else jsonb_build_object('power_of_attorney_reference', v_poa_reference)
      end
  ));
end
$$;

--
-- Name: gridex_create_partner_webhook_subscription_v1(uuid, uuid, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_partner_webhook_subscription_v1(p_company_id uuid, p_api_client_id uuid, p_name text, p_endpoint_url text, p_event_types text[], p_secret text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_secret_id uuid;
  v_row public.webhook_subscriptions%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;
  if p_company_id is null or p_api_client_id is null then
    raise exception using errcode='22023', message='partner_api_webhook_identity_required';
  end if;
  if not exists (
    select 1 from public.integration_api_clients c
    where c.id = p_api_client_id and c.company_id = p_company_id and c.status = 'active'
  ) then
    raise exception using errcode='42501', message='partner_api_client_not_active_for_company';
  end if;
  if nullif(btrim(p_name),'') is null then
    raise exception using errcode='22023', message='partner_api_webhook_name_required';
  end if;
  if p_endpoint_url !~ '^https://[^[:space:]]+$' then
    raise exception using errcode='22023', message='partner_api_webhook_https_required';
  end if;
  if coalesce(cardinality(p_event_types),0) = 0 then
    raise exception using errcode='22023', message='partner_api_webhook_event_types_required';
  end if;
  if exists (
    select 1
    from unnest(p_event_types) event_type
    where event_type not in (
      'customer.created',
      'customer.updated',
      'site.created',
      'site.updated',
      'power_of_attorney.created',
      'contract.created',
      'contract.status_changed',
      'invoice.created',
      'invoice.updated',
      -- retained compatibility event for existing Partner API subscriptions
      'metering_values.updated'
    )
  ) then
    raise exception using errcode='22023', message='partner_api_webhook_event_type_invalid';
  end if;
  if nullif(p_secret,'') is null or char_length(p_secret) < 32 then
    raise exception using errcode='22023', message='partner_api_webhook_secret_too_short';
  end if;

  select vault.create_secret(
    p_secret,
    'gridex_webhook_' || replace(gen_random_uuid()::text,'-',''),
    'Gridex Partner API webhook signing secret'
  ) into v_secret_id;

  insert into public.webhook_subscriptions(
    company_id,
    api_client_id,
    name,
    description,
    endpoint_url,
    event_types,
    status,
    signing_algorithm,
    signing_secret_ref,
    signing_secret_hash,
    custom_headers,
    timeout_ms,
    max_attempts,
    metadata
  ) values (
    p_company_id,
    p_api_client_id,
    btrim(p_name),
    nullif(btrim(coalesce(p_description,'')),''),
    btrim(p_endpoint_url),
    p_event_types,
    'active',
    'HMAC-SHA256',
    v_secret_id::text,
    encode(extensions.digest(convert_to(p_secret,'utf8'),'sha256'),'hex'),
    '{}'::jsonb,
    10000,
    8,
    jsonb_build_object('source','partner_api','secret_store','supabase_vault')
  )
  returning * into v_row;

  return jsonb_build_object(
    'webhook_subscription_reference', v_row.webhook_subscription_reference,
    'name', v_row.name,
    'endpoint_url', v_row.endpoint_url,
    'event_types', to_jsonb(v_row.event_types),
    'status', v_row.status,
    'created_at', v_row.created_at
  );
exception
  when others then
    if v_secret_id is not null and not exists (
      select 1 from public.webhook_subscriptions
      where signing_secret_ref = v_secret_id::text
    ) then
      delete from vault.secrets where id = v_secret_id;
    end if;
    raise;
end
$_$;

--
-- Name: gridex_create_portfolio(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_portfolio(p_actor_user_id uuid, p_company_id uuid, p_code text, p_name text, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  perform public.gridex_assert_portfolio_permission(
    p_actor_user_id,'portfolio_settlement.create',p_company_id,null
  );
  if nullif(btrim(p_code),'') is null or nullif(btrim(p_name),'') is null then
    raise exception using errcode='22023',message='portfolio_code_and_name_required';
  end if;
  insert into public.portfolios(company_id,code,name,description,created_by,updated_by)
  values(p_company_id,lower(btrim(p_code)),btrim(p_name),nullif(btrim(p_description),''),p_actor_user_id,p_actor_user_id)
  returning id into v_id;
  insert into public.portfolio_settlement_audit_log(
    company_id,portfolio_id,actor_user_id,permission,action,new_values
  ) values(p_company_id,v_id,p_actor_user_id,'portfolio_settlement.create','portfolio.created',jsonb_build_object('code',lower(btrim(p_code)),'name',btrim(p_name)));
  return v_id;
end $$;

--
-- Name: gridex_create_portfolio_settlement_correction(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_portfolio_settlement_correction(p_actor_user_id uuid, p_settlement_id uuid, p_reason text, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_old public.portfolio_monthly_settlements%rowtype; v_new_id uuid; v_revision integer;
begin
  select * into v_old from public.portfolio_monthly_settlements where id=p_settlement_id for update;
  if not found then raise exception using errcode='P0002',message='portfolio_settlement_not_found'; end if;
  perform public.gridex_assert_portfolio_permission(p_actor_user_id,'portfolio_settlement.correct',v_old.company_id,v_old.portfolio_id);
  if v_old.status not in('final','locked') or not v_old.is_current then
    raise exception using errcode='23514',message='only_current_final_settlement_can_be_corrected';
  end if;
  if nullif(btrim(p_reason),'') is null then raise exception using errcode='22023',message='portfolio_correction_reason_required'; end if;
  if p_idempotency_key is not null then
    select id into v_new_id from public.portfolio_monthly_settlements
    where company_id=v_old.company_id and idempotency_key=p_idempotency_key;
    if v_new_id is not null then return v_new_id; end if;
  end if;
  select coalesce(max(revision_no),0)+1 into v_revision
  from public.portfolio_monthly_settlements
  where company_id=v_old.company_id and portfolio_id=v_old.portfolio_id
    and price_area_code=v_old.price_area_code and delivery_month=v_old.delivery_month
    and price_plan_version_id=v_old.price_plan_version_id;
  v_new_id:=extensions.gen_random_uuid();
  perform set_config('gridex.portfolio_actor_user_id',p_actor_user_id::text,true);
  perform set_config('gridex.portfolio_audit_reason',btrim(p_reason),true);
  perform set_config('gridex.portfolio_correction_write','on',true);
  update public.portfolio_monthly_settlements
  set is_current=false,superseded_by_settlement_id=v_new_id
  where id=v_old.id;
  insert into public.portfolio_monthly_settlements(
    id,company_id,portfolio_id,price_area_code,delivery_month,price_plan_version_id,revision_no,is_current,status,source,
    gross_energy_cost_sek,hedging_result_sek,balancing_cost_sek,
    other_allowed_cost_sek,energy_volume_kwh,portfolio_price_ore_per_kwh,
    management_fee_ore_per_kwh,calculation_base,vat_rate,currency,settlement_timing,
    correction_reason,supersedes_settlement_id,idempotency_key,created_by
  ) values(
    v_new_id,v_old.company_id,v_old.portfolio_id,v_old.price_area_code,v_old.delivery_month,v_old.price_plan_version_id,v_revision,true,'draft','correction',
    v_old.gross_energy_cost_sek,v_old.hedging_result_sek,v_old.balancing_cost_sek,
    v_old.other_allowed_cost_sek,v_old.energy_volume_kwh,v_old.portfolio_price_ore_per_kwh,
    v_old.management_fee_ore_per_kwh,v_old.calculation_base,v_old.vat_rate,v_old.currency,v_old.settlement_timing,
    btrim(p_reason),v_old.id,p_idempotency_key,p_actor_user_id
  );
  return v_new_id;
end $$;

--
-- Name: gridex_create_staff_support_case_v1(uuid, uuid, uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_staff_support_case_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_api_client_id uuid, p_title text, p_description text, p_category text, p_priority text, p_idempotency_key text, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_case public.customer_cases%ROWTYPE;
  v_case_id uuid:=gen_random_uuid();
  v_request_hash text;
  v_metadata jsonb;
  v_category text:=coalesce(nullif(btrim(p_category),''),'support');
  v_next_action text:='Supportärendet ska triageras inom tenantens ordinarie ärendeflöde.';
BEGIN
  PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'cases.write');
  IF NOT EXISTS(SELECT FROM public.integration_api_clients WHERE id=p_api_client_id AND company_id=p_company_id AND 'staff_cases.write'=ANY(scopes))
  THEN RAISE EXCEPTION 'staff_api_client_scope_missing' USING ERRCODE='42501'; END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 180
    OR (p_description IS NOT NULL AND length(p_description)>8000)
    OR length(v_category)>120 OR p_priority IS NULL OR p_priority NOT IN('low','normal','high','urgent')
    OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 200
    OR (p_metadata IS NOT NULL AND jsonb_typeof(p_metadata)<>'object')
  THEN RAISE EXCEPTION 'staff_support_create_invalid' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.customers WHERE id=p_customer_id AND company_id=p_company_id
    AND merged_into_customer_id IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'support_customer_not_found' USING ERRCODE='P0002'; END IF;
  -- The existing support unique key is company + customer + support key. Serialize before the
  -- lookup so a concurrent exact retry observes the committed row instead of failing midway.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_customer_id::text||':'||p_idempotency_key,0));
  v_request_hash:=encode(extensions.digest(jsonb_build_object('customer_id',p_customer_id,'actor_user_id',p_actor_user_id,
    'api_client_id',p_api_client_id,'title',btrim(p_title),'description',p_description,'category',v_category,
    'priority',p_priority,'metadata',coalesce(p_metadata,'{}'::jsonb))::text,'sha256'),'hex');
  SELECT * INTO v_case FROM public.customer_cases WHERE company_id=p_company_id AND customer_id=p_customer_id
    AND metadata->>'support_idempotency_key'=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF v_case.source IS DISTINCT FROM 'tenant_support_staff_api' OR v_case.case_type<>'other'
      OR v_case.metadata->>'support_case' IS DISTINCT FROM 'true'
      OR v_case.metadata->>'staff_create_request_hash' IS DISTINCT FROM v_request_hash
      OR v_case.billing_blocked OR v_case.billing_manual_review OR v_case.cancellation_required THEN
      RAISE EXCEPTION 'staff_support_idempotency_conflict' USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object('case',to_jsonb(v_case),'reused',true);
  END IF;
  v_metadata:=coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('support_case',true,'support_channel','staff_api',
    'support_idempotency_key',p_idempotency_key,'staff_create_request_hash',v_request_hash,'opened_by','staff',
    'actor_user_id',p_actor_user_id,'api_client_id',p_api_client_id,'description_visibility','internal',
    'support_public_reference','support_case_'||substr(translate(rtrim(encode(extensions.digest(
      'gridex-public-reference:v1:'||p_company_id::text||':support_case:'||v_case_id::text,'sha256'),'base64'),'='),'+/','-_'),1,32));
  INSERT INTO public.customer_cases(id,company_id,customer_id,case_type,status,priority,title,description,reason_category,
    source,metadata,next_action,billing_blocked,billing_manual_review,cancellation_required,cancellation_status,created_by,updated_by)
  VALUES(v_case_id,p_company_id,p_customer_id,'other','open',p_priority,btrim(p_title),p_description,v_category,
    'tenant_support_staff_api',v_metadata,v_next_action,false,false,false,'not_required',p_actor_user_id,p_actor_user_id)
  RETURNING * INTO v_case;
  INSERT INTO public.customer_case_events(company_id,customer_case_id,customer_id,event_type,event_status,message,payload,created_by)
  VALUES(p_company_id,v_case.id,p_customer_id,'created','info','Supportärende registrerat. '||v_next_action,
    jsonb_build_object('channel','staff_api','api_client_id',p_api_client_id,'actor_user_id',p_actor_user_id,
      'visibility','internal','operational_impact','none'),p_actor_user_id);
  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,new_values,metadata)
  VALUES(p_company_id,p_actor_user_id,'customer_case',v_case.id::text,'customer_case_created',
    jsonb_build_object('case_type',v_case.case_type,'status',v_case.status,'priority',v_case.priority),
    jsonb_build_object('channel','staff_api','api_client_id',p_api_client_id,'customer_id',p_customer_id,
      'support_idempotency_key',p_idempotency_key));
  RETURN jsonb_build_object('case',to_jsonb(v_case),'reused',false);
END$$;

--
-- Name: gridex_create_supplier_switch_v1(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_supplier_switch_v1(p_company_id uuid, p_request jsonb, p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_row public.supplier_switch_requests%rowtype;
  v_existing public.supplier_switch_requests%rowtype;
  v_key text := nullif(p_request->>'automation_key', '');
  v_payload jsonb;
  v_columns text;
begin
  perform public.gridex_assert_switch_writer_v1(p_company_id);

  if v_key is not null then
    select * into v_existing
    from public.supplier_switch_requests
    where company_id = p_company_id
      and automation_key = v_key
      and status in ('draft', 'queued', 'submitted', 'accepted', 'cancellation_requested',
        'cancellation_sent', 'manual_followup_required', 'pending', 'ready', 'prepared',
        'in_progress', 'sent', 'waiting_response', 'awaiting_confirmation', 'confirmed')
    limit 1;
    if found then
      return jsonb_build_object('request', to_jsonb(v_existing), 'existing', true);
    end if;
  end if;

  -- Insert only the columns the caller sent so table defaults still apply;
  -- the tenant always comes from p_company_id.
  v_payload := (p_request - 'company_id') || jsonb_build_object('company_id', p_company_id);
  select string_agg(quote_ident(key), ', ' order by key) into v_columns
  from jsonb_object_keys(v_payload) as key
  where key in (
    select attname from pg_attribute
    where attrelid = 'public.supplier_switch_requests'::regclass and attnum > 0 and not attisdropped
  );
  execute format(
    'insert into public.supplier_switch_requests (%1$s) select %1$s from jsonb_populate_record(null::public.supplier_switch_requests, $1) returning *',
    v_columns
  ) into v_row using v_payload;

  insert into public.supplier_switch_events (
    switch_request_id, event_type, event_status, message, payload, company_id, created_by
  ) values (
    v_row.id,
    coalesce(p_event->>'event_type', 'created'),
    coalesce(p_event->>'event_status', 'success'),
    p_event->>'message',
    coalesce(p_event->'payload', '{}'::jsonb),
    p_company_id,
    nullif(p_event->>'created_by', '')::uuid
  );

  return jsonb_build_object('request', to_jsonb(v_row), 'existing', false);
end
$_$;

--
-- Name: gridex_create_tenant_legal_override(uuid, text, text, text, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_tenant_legal_override(p_company_id uuid, p_module_key text, p_legal_mode text, p_version_label text, p_title text, p_body text, p_publish boolean DEFAULT false, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_id uuid; v_hash text;
begin
  if p_company_id is null or nullif(btrim(p_module_key),'') is null or nullif(btrim(p_title),'') is null or nullif(btrim(p_body),'') is null then
    raise exception using errcode='22023',message='company_module_title_body_required';
  end if;
  if p_legal_mode not in('addendum','replacement') then
    raise exception using errcode='22023',message='invalid_tenant_legal_mode';
  end if;
  if not exists(select 1 from public.companies where id=p_company_id) then
    raise exception using errcode='P0002',message='company_not_found';
  end if;
  if not exists(select 1 from public.legal_templates where module_key=p_module_key and status='active') then
    raise exception using errcode='P0002',message='canonical_legal_module_not_found';
  end if;
  v_hash:=encode(digest(btrim(p_title)||E'\n'||p_body,'sha256'),'hex');
  select id into v_id from public.tenant_legal_overrides
  where company_id=p_company_id and module_key=p_module_key and content_sha256=v_hash limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.tenant_legal_overrides(
    company_id,module_key,legal_mode,version_label,title,body,content_sha256,status,submitted_at,
    reviewed_at,reviewed_by,locked_at,created_by
  ) values(
    p_company_id,p_module_key,p_legal_mode,
    coalesce(nullif(btrim(p_version_label),''),to_char(now() at time zone 'UTC','YYYY-MM-DD-HH24MISS')),
    btrim(p_title),p_body,v_hash,
    case when p_publish then 'published' else 'draft' end,
    case when p_publish then now() end,case when p_publish then now() end,
    case when p_publish then p_actor_user_id end,case when p_publish then now() end,p_actor_user_id
  ) returning id into v_id;
  return v_id;
end $$;

--
-- Name: gridex_create_website_customer_contract(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_create_website_customer_contract(p_company_id uuid, p_contract_payload jsonb, p_customer_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_offer public.public_contract_offers%rowtype;
  v_publication public.contract_publication_versions%rowtype;
  v_contract_version public.contract_product_versions%rowtype;
  v_price_snapshot jsonb;
  v_contract public.customer_contracts%rowtype;
  v_snapshot_id uuid;
  v_contract_id uuid:=gen_random_uuid();
begin
  if p_company_id is null or jsonb_typeof(coalesce(p_contract_payload,'null'::jsonb))<>'object' then
    raise exception using errcode='22023',message='company_and_contract_payload_required';
  end if;
  if nullif(p_contract_payload->>'public_contract_offer_id','') is null
     or nullif(p_contract_payload->>'offer_reference','') is null then
    raise exception using errcode='22023',message='exact_public_offer_identity_required';
  end if;

  select * into v_offer
  from public.public_contract_offers
  where id=(p_contract_payload->>'public_contract_offer_id')::uuid
    and company_id=p_company_id
    and publication_status='published'
    and website_enabled=true
    and is_archived=false
  for share;
  if not found then raise exception using errcode='P0002',message='published_public_offer_not_found_for_tenant'; end if;

  select * into v_publication
  from public.contract_publication_versions
  where id=v_offer.contract_publication_version_id
    and legacy_public_contract_offer_id=v_offer.id
    and offer_reference=p_contract_payload->>'offer_reference'
    and status='published'
    and locked_at is not null
  for share;
  if not found then raise exception using errcode='23514',message='exact_locked_publication_version_required'; end if;

  select * into v_contract_version
  from public.contract_product_versions
  where id=v_publication.contract_product_version_id
    and status='approved'
    and locked_at is not null
  for share;
  if not found then raise exception using errcode='23514',message='exact_locked_contract_version_required'; end if;

  select snapshot_json into v_price_snapshot
  from public.price_plan_versions
  where id=v_publication.price_plan_version_id
    and company_id=p_company_id
    and status in ('published','active')
    and locked_at is not null;
  if not found or coalesce(v_price_snapshot,'{}'::jsonb)='{}'::jsonb then
    raise exception using errcode='23514',message='exact_locked_price_snapshot_required';
  end if;

  insert into public.customer_contracts(
    id,company_id,customer_id,site_id,customer_site_id,metering_point_id,
    source_type,status,contract_number,contract_name,contract_type,
    price_plan_id,price_plan_version_id,contract_offer_id,public_contract_offer_id,offer_reference,
    legal_versions_snapshot,signature_snapshot,signature_snapshot_sha256,signed_ip_hash,signed_user_agent,
    is_distance_agreement,starts_at,expected_start_at,requested_start_date,requested_start_mode,
    calculated_earliest_start_date,price_area_used,grid_area_code_used,resolution_status,
    confirmed_start_date,actual_start_date,signed_at,
    monthly_fee_sek,invoice_fee_sek,markup_ore_per_kwh,spot_markup_ore_per_kwh,
    variable_fee_ore_per_kwh,fixed_price_ore_per_kwh,green_fee_mode,green_fee_value,
    binding_months,notice_months,campaign_code,price_version,terms_version,
    optional_fee_lines,agreement_channel,metadata,price_snapshot,
    contract_product_id,contract_product_version_id,contract_publication_version_id,
    legal_bundle_version_id,commercial_snapshot,legal_snapshot,created_at,updated_at
  ) values (
    v_contract_id,p_company_id,(p_contract_payload->>'customer_id')::uuid,
    nullif(p_contract_payload->>'site_id','')::uuid,nullif(p_contract_payload->>'customer_site_id','')::uuid,
    nullif(p_contract_payload->>'metering_point_id','')::uuid,
    coalesce(nullif(p_contract_payload->>'source_type',''),'website_application'),
    coalesce(nullif(p_contract_payload->>'status',''),'pending_signature'),
    nullif(p_contract_payload->>'contract_number',''),coalesce(nullif(p_contract_payload->>'contract_name',''),v_offer.public_name),
    v_contract_version.contract_type,v_publication.price_plan_id,v_publication.price_plan_version_id,
    nullif(p_contract_payload->>'contract_offer_id','')::uuid,v_offer.id,v_publication.offer_reference,
    coalesce(p_contract_payload->'legal_versions_snapshot','[]'::jsonb),'{}'::jsonb,null,null,null,
    true,nullif(p_contract_payload->>'starts_at','')::date,nullif(p_contract_payload->>'expected_start_at','')::date,
    nullif(p_contract_payload->>'requested_start_date','')::date,
    coalesce(nullif(p_contract_payload->>'requested_start_mode',''),'earliest_possible'),
    nullif(p_contract_payload->>'calculated_earliest_start_date','')::date,
    nullif(p_contract_payload->>'price_area_used',''),nullif(p_contract_payload->>'grid_area_code_used',''),
    nullif(p_contract_payload->>'resolution_status',''),nullif(p_contract_payload->>'confirmed_start_date','')::date,
    nullif(p_contract_payload->>'actual_start_date','')::date,null,
    nullif(p_contract_payload->>'monthly_fee_sek','')::numeric,nullif(p_contract_payload->>'invoice_fee_sek','')::numeric,
    nullif(p_contract_payload->>'markup_ore_per_kwh','')::numeric,nullif(p_contract_payload->>'spot_markup_ore_per_kwh','')::numeric,
    nullif(p_contract_payload->>'variable_fee_ore_per_kwh','')::numeric,nullif(p_contract_payload->>'fixed_price_ore_per_kwh','')::numeric,
    coalesce(nullif(p_contract_payload->>'green_fee_mode',''),'none'),nullif(p_contract_payload->>'green_fee_value','')::numeric,
    nullif(p_contract_payload->>'binding_months','')::integer,nullif(p_contract_payload->>'notice_months','')::integer,
    nullif(p_contract_payload->>'campaign_code',''),coalesce(nullif(p_contract_payload->>'price_version',''),v_publication.price_plan_version_id::text),
    nullif(p_contract_payload->>'terms_version',''),coalesce(v_price_snapshot->'price_components','[]'::jsonb),
    coalesce(nullif(p_contract_payload->>'agreement_channel',''),'website'),
    coalesce(p_contract_payload->'metadata','{}'::jsonb)||jsonb_build_object(
      'source_of_truth','contract_publication_versions',
      'contract_publication_version_id',v_publication.id,
      'contract_product_version_id',v_contract_version.id,
      'legal_bundle_version_id',v_publication.legal_bundle_version_id,
      'price_plan_version_id',v_publication.price_plan_version_id
    ),
    v_price_snapshot,v_contract_version.contract_product_id,v_contract_version.id,v_publication.id,
    v_publication.legal_bundle_version_id,v_contract_version.commercial_snapshot,
    (select rendered_snapshot from public.legal_bundle_versions where id=v_publication.legal_bundle_version_id),now(),now()
  ) returning * into v_contract;

  insert into public.contract_price_snapshots(
    company_id,contract_id,customer_id,contract_number,customer_number,source,
    price_plan_id,price_plan_version_id,price_book_id,public_contract_offer_id,
    public_price_text,terms_url,spot_weight_percent,portfolio_weight_percent,fixed_weight_percent,
    pricing_model,base_price_components_snapshot,price_components_snapshot,snapshot_json,
    valid_from,valid_to,snapshot_hash,snapshot_quality
  ) values (
    p_company_id,v_contract.id,v_contract.customer_id,v_contract.contract_number,p_customer_number,'website_customer_applications',
    v_publication.price_plan_id,v_publication.price_plan_version_id,v_publication.price_book_id,v_offer.id,
    v_offer.public_price_text,v_offer.terms_url,v_offer.spot_weight_percent,v_offer.portfolio_weight_percent,v_offer.fixed_weight_percent,
    v_contract_version.pricing_model,coalesce(v_price_snapshot->'base_components','[]'::jsonb),
    coalesce(v_price_snapshot->'price_components','[]'::jsonb),
    jsonb_build_object(
      'schema','gridex_contract_acceptance_v3','source_of_truth','contract_publication_versions',
      'offer_reference',v_publication.offer_reference,'public_contract_offer_id',v_offer.id,
      'contract_publication_version_id',v_publication.id,'contract_product_version_id',v_contract_version.id,
      'legal_bundle_version_id',v_publication.legal_bundle_version_id,
      'price_plan_id',v_publication.price_plan_id,'price_plan_version_id',v_publication.price_plan_version_id,
      'price_book_id',v_publication.price_book_id,'pricing',v_price_snapshot,
      'commercial',v_contract_version.commercial_snapshot
    ),
    coalesce(nullif(p_contract_payload->>'requested_start_date','')::date,v_publication.valid_from::date),
    v_publication.valid_to::date,
    encode(digest(jsonb_build_object('publication',v_publication.id,'pricing',v_price_snapshot,'commercial',v_contract_version.commercial_snapshot)::text,'sha256'),'hex'),
    'exact_locked_publication'
  ) returning id into v_snapshot_id;

  update public.customer_contracts
  set contract_price_snapshot_id=v_snapshot_id,updated_at=now()
  where id=v_contract.id and company_id=p_company_id
  returning * into v_contract;

  return jsonb_build_object('contract',to_jsonb(v_contract),'contract_price_snapshot_id',v_snapshot_id);
end
$$;

--
-- Name: gridex_current_user_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_current_user_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_email text := lower(coalesce((select auth.jwt()) ->> 'email', ''));
  v_company_ids jsonb := '[]'::jsonb;
  v_default_company_id uuid;
  v_roles jsonb := '[]'::jsonb;
  v_is_platform_admin boolean := false;
begin
  if v_uid is null then
    return jsonb_build_object(
      'user_id', null,
      'email', null,
      'is_platform_admin', false,
      'company_ids', '[]'::jsonb,
      'default_company_id', null,
      'roles', '[]'::jsonb
    );
  end if;

  v_is_platform_admin := public.gridex_user_is_platform_admin();

  select coalesce(jsonb_agg(distinct c.company_id), '[]'::jsonb),
         min(c.company_id::text)::uuid
    into v_company_ids, v_default_company_id
  from public.gridex_user_company_ids() as c(company_id);

  select coalesce(jsonb_agg(distinct role_key order by role_key), '[]'::jsonb)
    into v_roles
  from (
    select lower(coalesce(au.role, '')) as role_key
    from public.admin_users au
    where au.user_id = v_uid
      and coalesce(au.is_active, true) = true
      and coalesce(au.role, '') <> ''
    union
    select lower(coalesce(ur.role, r.key, r.name, '')) as role_key
    from public.user_roles ur
    left join public.roles r on r.id = ur.role_id
    where ur.user_id = v_uid
      and coalesce(ur.status, 'active') = 'active'
      and coalesce(ur.is_active, true) = true
      and coalesce(ur.role, r.key, r.name, '') <> ''
    union
    select lower(coalesce(cm.role_key, cm.membership_role::text, cm.role, '')) as role_key
    from public.company_memberships cm
    where cm.user_id = v_uid
      and coalesce(cm.status, 'active') = 'active'
      and coalesce(cm.is_active, true) = true
      and coalesce(cm.role_key, cm.membership_role::text, cm.role, '') <> ''
  ) r;

  return jsonb_build_object(
    'user_id', v_uid,
    'email', nullif(v_email, ''),
    'is_platform_admin', v_is_platform_admin,
    'company_ids', v_company_ids,
    'default_company_id', v_default_company_id,
    'roles', v_roles
  );
exception when undefined_table or undefined_column then
  return jsonb_build_object(
    'user_id', v_uid,
    'email', nullif(v_email, ''),
    'is_platform_admin', public.gridex_user_is_platform_admin(),
    'company_ids', '[]'::jsonb,
    'default_company_id', null,
    'roles', '[]'::jsonb,
    'warning', 'context_partially_available'
  );
end;
$$;

--
-- Name: gridex_customer_application_dependency_wait_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_application_dependency_wait_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_next_action text;
  v_first_blocker text;
  v_retry_at timestamptz;
  v_application_id uuid;
begin
  if new.job_type <> 'customer_application_continuation' then
    return new;
  end if;

  if new.status not in ('completed','needs_review') then
    return new;
  end if;

  v_next_action := nullif(new.result->>'next_action','');
  select nullif(item->>'code','')
    into v_first_blocker
  from jsonb_array_elements(coalesce(new.result->'blockers','[]'::jsonb)) item
  limit 1;

  if v_next_action = 'resolve_grid_owner'
     or v_first_blocker in ('grid_owner_missing','grid_owner_verification_required') then
    v_retry_at := now() + interval '1 hour';
    begin
      v_application_id := nullif(new.payload->>'application_id','')::uuid;
    exception when invalid_text_representation then
      v_application_id := null;
    end;

    new.status := 'queued';
    new.run_after := v_retry_at;
    new.completed_at := null;
    new.stale_reason := null;
    new.last_error := null;
    new.last_error_code := null;
    new.last_error_message := null;
    new.attempts := greatest(coalesce(new.attempts,0) - 1, 0);
    new.result := coalesce(new.result,'{}'::jsonb) || jsonb_build_object(
      'dependency_wait', true,
      'dependency_code', 'grid_owner_resolution',
      'retry_at', v_retry_at,
      'automation_state', 'waiting_for_dependency',
      'next_action', 'resolve_grid_owner',
      'workflow_state', 'facility_request_pending'
    );

    if new.customer_site_id is not null then
      update public.customer_sites
      set onboarding_status = 'needs_grid_owner_resolution',
          next_action = 'resolve_grid_owner',
          facility_data_status = 'pending_resolution',
          updated_at = now()
      where id = new.customer_site_id
        and company_id = new.company_id
        and customer_id = new.customer_id;
    end if;

    if v_application_id is not null then
      update public.customer_application_workflows
      set state = 'facility_request_pending',
          snapshot = coalesce(snapshot,'{}'::jsonb) || jsonb_build_object(
            'next_action','resolve_grid_owner',
            'automation_wait',true,
            'dependency_code','grid_owner_resolution',
            'retry_at',v_retry_at,
            'continuation_job_id',new.id
          ),
          updated_at = now()
      where company_id = new.company_id
        and customer_application_id = v_application_id;

      update public.website_customer_applications
      set status = 'needs_address_resolution',
          next_step = 'resolve_grid_owner',
          response_payload = coalesce(response_payload,'{}'::jsonb) || jsonb_build_object(
            'status','processing',
            'workflow_state','facility_request_pending',
            'next_step','resolve_grid_owner',
            'automation',jsonb_build_object(
              'status','waiting_for_dependency',
              'dependency_code','grid_owner_resolution',
              'retry_at',v_retry_at,
              'job_id',new.id
            )
          ),
          updated_at = now()
      where id = v_application_id
        and company_id = new.company_id;
    end if;
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_customer_application_dependency_wait_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_customer_application_dependency_wait_guard() IS 'Converts grid-owner-resolution-only continuation outcomes into retryable dependency waits, preserves retry budget, and projects the waiting state back to customer site, workflow, and website application.';

--
-- Name: gridex_customer_application_runtime_contract_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_application_runtime_contract_v1() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
with checks as (
  select
    to_regclass('public.supplier_switch_requests') is not null as supplier_switch_requests_exists,
    exists (
      select 1 from pg_catalog.pg_attribute
      where attrelid = to_regclass('public.supplier_switch_requests')
        and attname = 'communication_route_id' and attnum > 0 and not attisdropped
    ) as communication_route_id_exists,
    exists (
      select 1 from pg_catalog.pg_attribute
      where attrelid = to_regclass('public.supplier_switch_requests')
        and attname = 'ediel_route_profile_id' and attnum > 0 and not attisdropped
    ) as ediel_route_profile_id_exists,
    to_regclass('public.communication_routes') is not null as communication_routes_exists,
    to_regclass('public.ediel_route_profiles') is not null as ediel_route_profiles_exists,
    to_regprocedure('extensions.digest(text,text)') is not null as pgcrypto_digest_exists,
    to_regprocedure('public.gridex_set_grid_owner_request_idempotency_key()') is not null as request_idempotency_function_exists,
    coalesce(position(
      'extensions.digest' in pg_get_functiondef(to_regprocedure('public.gridex_set_grid_owner_request_idempotency_key()'))
    ) > 0, false) as request_idempotency_digest_qualified,
    exists (
      select 1 from pg_catalog.pg_trigger
      where tgrelid = to_regclass('public.grid_owner_information_requests')
        and tgname = 'trg_grid_owner_information_requests_idempotency'
        and not tgisinternal
        and tgenabled <> 'D'
    ) as request_idempotency_trigger_enabled,
    to_regprocedure('public.gridex_lock_signed_customer_contract()') is not null as signed_contract_integrity_function_exists
)
select jsonb_build_object(
  'ready',
    supplier_switch_requests_exists
    and communication_route_id_exists
    and ediel_route_profile_id_exists
    and communication_routes_exists
    and ediel_route_profiles_exists
    and pgcrypto_digest_exists
    and request_idempotency_function_exists
    and request_idempotency_digest_qualified
    and request_idempotency_trigger_enabled
    and signed_contract_integrity_function_exists,
  'checks', jsonb_build_object(
    'supplier_switch_requests_exists', supplier_switch_requests_exists,
    'communication_route_id_exists', communication_route_id_exists,
    'ediel_route_profile_id_exists', ediel_route_profile_id_exists,
    'communication_routes_exists', communication_routes_exists,
    'ediel_route_profiles_exists', ediel_route_profiles_exists,
    'pgcrypto_digest_exists', pgcrypto_digest_exists,
    'request_idempotency_function_exists', request_idempotency_function_exists,
    'request_idempotency_digest_qualified', request_idempotency_digest_qualified,
    'request_idempotency_trigger_enabled', request_idempotency_trigger_enabled,
    'signed_contract_integrity_function_exists', signed_contract_integrity_function_exists
  )
)
from checks;
$$;

--
-- Name: gridex_customer_billing_profile_bump(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_billing_profile_bump() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.billing_profile_revision := 1;
  ELSIF NEW.invoice_email IS DISTINCT FROM OLD.invoice_email
     OR NEW.billing_street IS DISTINCT FROM OLD.billing_street
     OR NEW.billing_postal_code IS DISTINCT FROM OLD.billing_postal_code
     OR NEW.billing_city IS DISTINCT FROM OLD.billing_city
     OR NEW.billing_country IS DISTINCT FROM OLD.billing_country THEN
    NEW.billing_profile_revision := OLD.billing_profile_revision + 1;
  ELSE
    -- The revision is owned by this trigger; writers cannot move it.
    NEW.billing_profile_revision := OLD.billing_profile_revision;
  END IF;
  RETURN NEW;
END $$;

--
-- Name: gridex_customer_billing_profile_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_billing_profile_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_changed text[] := '{}'::text[];
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.billing_profile_revision = OLD.billing_profile_revision THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    v_changed := ARRAY['created'];
  ELSE
    IF NEW.invoice_email IS DISTINCT FROM OLD.invoice_email THEN v_changed := array_append(v_changed, 'invoice_email'); END IF;
    IF NEW.billing_street IS DISTINCT FROM OLD.billing_street THEN v_changed := array_append(v_changed, 'billing_street'); END IF;
    IF NEW.billing_postal_code IS DISTINCT FROM OLD.billing_postal_code THEN v_changed := array_append(v_changed, 'billing_postal_code'); END IF;
    IF NEW.billing_city IS DISTINCT FROM OLD.billing_city THEN v_changed := array_append(v_changed, 'billing_city'); END IF;
    IF NEW.billing_country IS DISTINCT FROM OLD.billing_country THEN v_changed := array_append(v_changed, 'billing_country'); END IF;
  END IF;
  INSERT INTO public.customer_billing_profile_revisions
    (company_id, customer_id, revision, invoice_email, billing_street, billing_postal_code, billing_city, billing_country, changed_fields)
  VALUES
    (NEW.company_id, NEW.id, NEW.billing_profile_revision, NEW.invoice_email, NEW.billing_street, NEW.billing_postal_code,
     NEW.billing_city, NEW.billing_country, v_changed);
  RETURN NULL;
END $$;

--
-- Name: gridex_customer_cleanup_external_ref(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_cleanup_external_ref(p_customer_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_external_ref text;
begin
  -- Some live schemas store external_customer_id on intake tables instead of customers.
  -- Keep this dynamic so the cleanup view does not break when a column is absent.
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'customers'
      and column_name = 'external_customer_id'
  ) then
    execute 'select external_customer_id::text from public.customers where id = $1 limit 1'
      into v_external_ref
      using p_customer_id;
  end if;

  if coalesce(v_external_ref, '') <> '' then
    return v_external_ref;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'external_contract_intakes'
      and column_name = 'external_customer_id'
  ) and exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'external_contract_intakes'
      and column_name = 'created_customer_id'
  ) then
    execute '
      select external_customer_id::text
      from public.external_contract_intakes
      where created_customer_id = $1
      order by created_at desc nulls last
      limit 1'
      into v_external_ref
      using p_customer_id;
  end if;

  return nullif(v_external_ref, '');
end;
$_$;

--
-- Name: gridex_customer_contact_change_v1(uuid, uuid, text, uuid, uuid, text, text, timestamp with time zone, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_contact_change_v1(p_company_id uuid, p_customer_id uuid, p_actor_kind text, p_actor_user_id uuid, p_api_client_id uuid, p_portal_identity_id text, p_channel text, p_expected_updated_at timestamp with time zone, p_customer_patch jsonb, p_contact_patch jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_allowed_customer constant text[] := ARRAY[
    'customer_type','status','first_name','last_name','full_name','company_name','personal_number','org_number',
    'email','phone','invoice_email','preferred_language','apartment_number','metadata'
  ];
  v_allowed_contact constant text[] := ARRAY['name','email','phone'];
  v_customer public.customers%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_contact public.customer_contacts%ROWTYPE;
  v_contact_before jsonb := NULL;
  v_contact_after jsonb := NULL;
  v_changes jsonb := '{}'::jsonb;
  v_contact_changes jsonb := '{}'::jsonb;
  v_key text;
  v_event_id uuid;
  v_now timestamptz := clock_timestamp();
  v_idempotency_key text;
BEGIN
  IF p_actor_kind NOT IN ('staff','customer_portal') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_actor_kind_invalid';
  END IF;
  IF p_actor_kind='staff' AND p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_staff_actor_required';
  END IF;
  IF p_actor_kind='customer_portal' AND p_api_client_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_api_client_required';
  END IF;
  IF p_channel NOT IN ('ops','customer_api','phone','staff_api') OR p_channel IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='contact_change_channel_invalid';
  END IF;
  IF p_channel='staff_api' THEN
    IF p_actor_kind IS DISTINCT FROM 'staff' THEN
      RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='contact_change_staff_api_actor_invalid';
    END IF;
    PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'masterdata.write');
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(coalesce(p_customer_patch,'{}'::jsonb)) LOOP
    IF NOT v_key = ANY(v_allowed_customer) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_field_not_allowed:'||v_key;
    END IF;
  END LOOP;
  FOR v_key IN SELECT jsonb_object_keys(coalesce(p_contact_patch,'{}'::jsonb)) LOOP
    IF NOT v_key = ANY(v_allowed_contact) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_contact_field_not_allowed:'||v_key;
    END IF;
  END LOOP;

  v_idempotency_key := CASE WHEN p_idempotency_key IS NULL THEN NULL
    WHEN p_channel='staff_api' THEN 'customer.contact_changed:'||p_company_id||':staff_api:'||p_api_client_id||':'||p_customer_id||':'||p_idempotency_key
    ELSE 'customer.contact_changed:'||p_company_id||':'||p_idempotency_key END;

  -- Idempotent replay: the same key returns the recorded result without writing again.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_event_id FROM public.domain_events
      WHERE company_id=p_company_id AND idempotency_key=v_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object('replayed',true,'domain_event_id',v_event_id);
    END IF;
  END IF;

  SELECT * INTO v_customer FROM public.customers
    WHERE id=p_customer_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='customer_not_found_in_scope';
  END IF;

  -- Staff: the canonical resolver grants masterdata.write in exactly this company (active member
  -- with the permission) or to an active platform superadmin; disabled/banned users never pass.
  IF p_actor_kind='staff'
     AND p_channel <> 'staff_api'
     AND NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'masterdata.write'),false) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='contact_change_actor_not_authorized';
  END IF;

  IF v_customer.merged_into_customer_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_merged_write_conflict';
  END IF;

  IF p_expected_updated_at IS NOT NULL AND v_customer.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='contact_change_version_conflict';
  END IF;
  IF v_customer.status='archived' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='contact_change_customer_archived';
  END IF;

  v_before := to_jsonb(v_customer);
  SELECT jsonb_object_agg(e.key, jsonb_build_object('from', v_before->e.key, 'to', e.value))
    INTO v_changes
    FROM jsonb_each(coalesce(p_customer_patch,'{}'::jsonb)) e
    WHERE (v_before->e.key) IS DISTINCT FROM e.value;
  v_changes := coalesce(v_changes,'{}'::jsonb);

  IF v_changes <> '{}'::jsonb THEN
    UPDATE public.customers c SET
      customer_type = CASE WHEN p_customer_patch ? 'customer_type' THEN p_customer_patch->>'customer_type' ELSE c.customer_type END,
      status = CASE WHEN p_customer_patch ? 'status' THEN p_customer_patch->>'status' ELSE c.status END,
      first_name = CASE WHEN p_customer_patch ? 'first_name' THEN p_customer_patch->>'first_name' ELSE c.first_name END,
      last_name = CASE WHEN p_customer_patch ? 'last_name' THEN p_customer_patch->>'last_name' ELSE c.last_name END,
      full_name = CASE WHEN p_customer_patch ? 'full_name' THEN p_customer_patch->>'full_name' ELSE c.full_name END,
      company_name = CASE WHEN p_customer_patch ? 'company_name' THEN p_customer_patch->>'company_name' ELSE c.company_name END,
      personal_number = CASE WHEN p_customer_patch ? 'personal_number' THEN p_customer_patch->>'personal_number' ELSE c.personal_number END,
      org_number = CASE WHEN p_customer_patch ? 'org_number' THEN p_customer_patch->>'org_number' ELSE c.org_number END,
      email = CASE WHEN p_customer_patch ? 'email' THEN p_customer_patch->>'email' ELSE c.email END,
      phone = CASE WHEN p_customer_patch ? 'phone' THEN p_customer_patch->>'phone' ELSE c.phone END,
      invoice_email = CASE WHEN p_customer_patch ? 'invoice_email' THEN p_customer_patch->>'invoice_email' ELSE c.invoice_email END,
      preferred_language = CASE WHEN p_customer_patch ? 'preferred_language' THEN p_customer_patch->>'preferred_language' ELSE c.preferred_language END,
      apartment_number = CASE WHEN p_customer_patch ? 'apartment_number' THEN p_customer_patch->>'apartment_number' ELSE c.apartment_number END,
      metadata = CASE WHEN p_customer_patch ? 'metadata' THEN p_customer_patch->'metadata' ELSE c.metadata END,
      updated_at = v_now
    WHERE c.id=v_customer.id AND c.company_id=p_company_id
    RETURNING * INTO v_customer;
  END IF;
  v_after := to_jsonb(v_customer);

  IF coalesce(p_contact_patch,'{}'::jsonb) <> '{}'::jsonb THEN
    SELECT * INTO v_contact FROM public.customer_contacts
      WHERE company_id=p_company_id AND customer_id=p_customer_id AND is_primary
      ORDER BY created_at ASC LIMIT 1 FOR UPDATE;
    IF FOUND THEN
      v_contact_before := to_jsonb(v_contact);
      SELECT jsonb_object_agg(e.key, jsonb_build_object('from', v_contact_before->e.key, 'to', e.value))
        INTO v_contact_changes
        FROM jsonb_each(p_contact_patch) e
        WHERE (v_contact_before->e.key) IS DISTINCT FROM e.value;
      v_contact_changes := coalesce(v_contact_changes,'{}'::jsonb);
      IF v_contact_changes <> '{}'::jsonb THEN
        UPDATE public.customer_contacts cc SET
          name = CASE WHEN p_contact_patch ? 'name' THEN p_contact_patch->>'name' ELSE cc.name END,
          email = CASE WHEN p_contact_patch ? 'email' THEN p_contact_patch->>'email' ELSE cc.email END,
          phone = CASE WHEN p_contact_patch ? 'phone' THEN p_contact_patch->>'phone' ELSE cc.phone END
        WHERE cc.id=v_contact.id AND cc.company_id=p_company_id AND cc.customer_id=p_customer_id
        RETURNING to_jsonb(cc.*) INTO v_contact_after;
      END IF;
    ELSIF p_contact_patch ? 'name' OR p_contact_patch ? 'email' OR p_contact_patch ? 'phone' THEN
      INSERT INTO public.customer_contacts(company_id,customer_id,type,name,email,phone,title,is_primary)
      VALUES (p_company_id,p_customer_id,'primary',p_contact_patch->>'name',p_contact_patch->>'email',p_contact_patch->>'phone',NULL,true)
      RETURNING to_jsonb(customer_contacts.*) INTO v_contact_after;
      v_contact_changes := jsonb_build_object('created', true);
    END IF;
  END IF;

  IF v_changes = '{}'::jsonb AND v_contact_changes = '{}'::jsonb THEN
    RETURN jsonb_build_object('replayed',false,'changed',false,'customer_updated_at',v_customer.updated_at);
  END IF;

  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  VALUES (
    p_company_id, p_actor_user_id, 'customer', p_customer_id::text, 'customer_profile_updated',
    (SELECT coalesce(jsonb_object_agg(k, v->'from'),'{}'::jsonb) FROM jsonb_each(v_changes) x(k,v)),
    (SELECT coalesce(jsonb_object_agg(k, v->'to'),'{}'::jsonb) FROM jsonb_each(v_changes) x(k,v)),
    jsonb_build_object(
      'channel', p_channel,
      'actor_type', CASE WHEN p_actor_kind='staff' THEN 'staff' ELSE 'customer_portal_account' END,
      'api_client_id', p_api_client_id,
      'portal_identity_id', p_portal_identity_id,
      'primary_contact_changes', v_contact_changes,
      'transaction', 'gridex_customer_contact_change_v1'
    )
  );

  -- Durable integration intent. Only changed field names leave the database; values stay internal.
  INSERT INTO public.domain_events(company_id,event_type,aggregate_type,aggregate_id,subject_customer_id,actor_user_id,source,idempotency_key,payload)
  VALUES (
    p_company_id, 'customer.contact_changed', 'customer', p_customer_id::text, p_customer_id, p_actor_user_id,
    CASE WHEN p_channel='staff_api' THEN 'staff_api' WHEN p_actor_kind='staff' THEN 'ops' ELSE 'customer_api' END,
    v_idempotency_key,
    jsonb_build_object(
      'changed_fields', (SELECT coalesce(jsonb_agg(k ORDER BY k),'[]'::jsonb) FROM jsonb_object_keys(v_changes) k),
      'primary_contact_changed', v_contact_changes <> '{}'::jsonb,
      'channel',p_channel,
      'api_client_id',p_api_client_id,
      'actor_user_id',p_actor_user_id,
      'customer_version', v_customer.updated_at
    )
  ) RETURNING id INTO v_event_id;

  INSERT INTO public.event_outbox(company_id,domain_event_id,destination_type,destination_key,status,attempts,max_attempts,available_at,payload)
  VALUES (p_company_id, v_event_id, 'webhook', 'webhook_fanout_v1', 'queued', 0, 12, v_now,
    jsonb_build_object('event_type','customer.contact_changed','aggregate_type','customer','aggregate_id',p_customer_id::text));

  RETURN jsonb_build_object(
    'replayed', false,
    'changed', true,
    'domain_event_id', v_event_id,
    'customer_updated_at', v_customer.updated_at,
    'changes', v_changes,
    'primary_contact_changes', v_contact_changes
  );
END
$$;

