--
-- Name: company_customer_intake_queue_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_customer_intake_queue_v WITH (security_invoker='true') AS
 SELECT i.id AS intake_id,
    i.company_id,
    i.created_customer_id AS customer_id,
    COALESCE(c.customer_number, NULL::text) AS customer_number,
    COALESCE(NULLIF(TRIM(BOTH FROM concat_ws(' '::text, i.first_name, i.last_name)), ''::text), NULLIF(i.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(c.company_name, ''::text), 'Namnlös kundansökan'::text) AS customer_name,
    COALESCE(i.email, c.email) AS customer_email,
    COALESCE(i.phone, c.phone) AS customer_phone,
    i.status,
    array_remove(ARRAY[
        CASE
            WHEN (NULLIF(COALESCE(i.facility_id, ''::text), ''::text) IS NULL) THEN 'facility_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((NULLIF(COALESCE(i.meter_point_id, ''::text), ''::text) IS NULL) AND (i.created_metering_point_id IS NULL)) THEN 'metering_point_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (i.created_customer_id IS NULL) THEN 'customer'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (i.created_site_id IS NULL) THEN 'site'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (i.created_contract_id IS NULL) THEN 'contract'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((jsonb_typeof(i.issues) = 'array'::text) AND (jsonb_array_length(i.issues) > 0)) THEN 'review_issues'::text
            ELSE NULL::text
        END], NULL::text) AS missing_fields,
    array_remove(ARRAY[
        CASE
            WHEN (i.status = ANY (ARRAY['needs_review'::text, 'failed'::text])) THEN i.status
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(COALESCE(i.facility_id, ''::text), ''::text) IS NULL) THEN 'missing_facility_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((NULLIF(COALESCE(i.meter_point_id, ''::text), ''::text) IS NULL) AND (i.created_metering_point_id IS NULL)) THEN 'missing_metering_point_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((jsonb_typeof(i.issues) = 'array'::text) AND (jsonb_array_length(i.issues) > 0)) THEN 'intake_issues'::text
            ELSE NULL::text
        END], NULL::text) AS blocking_reasons,
    COALESCE((i.payload #>> '{energy_resolution,grid_owner_name}'::text[]), (i.payload #>> '{gridOwner,name}'::text[]), (i.payload #>> '{suggested_grid_owner_name}'::text[])) AS suggested_grid_owner_name,
    COALESCE((i.payload #>> '{energy_resolution,grid_area_code}'::text[]), (i.payload #>> '{gridOwner,grid_area_code}'::text[]), (i.payload #>> '{suggested_grid_area_code}'::text[])) AS suggested_grid_area_code,
    i.price_area_code,
        CASE
            WHEN (COALESCE((i.payload #>> '{energy_resolution,confidence}'::text[]), (i.payload #>> '{confidence}'::text[]), ''::text) ~ '^[0-9]+(\.[0-9]+)?$'::text) THEN (COALESCE((i.payload #>> '{energy_resolution,confidence}'::text[]), (i.payload #>> '{confidence}'::text[])))::numeric
            ELSE NULL::numeric
        END AS confidence,
        CASE
            WHEN (i.status = 'failed'::text) THEN 'Granska fel och åtgärda ansökan'::text
            WHEN (i.status = 'needs_review'::text) THEN 'Komplettera saknade uppgifter'::text
            WHEN (NULLIF(COALESCE(i.facility_id, ''::text), ''::text) IS NULL) THEN 'Begär eller fyll i anläggnings-id'::text
            WHEN ((NULLIF(COALESCE(i.meter_point_id, ''::text), ''::text) IS NULL) AND (i.created_metering_point_id IS NULL)) THEN 'Begär eller fyll i mätpunkt'::text
            WHEN (i.created_contract_id IS NULL) THEN 'Slutför avtal'::text
            ELSE 'Granska och fortsätt'::text
        END AS next_action,
    i.created_at,
    i.updated_at
   FROM (public.external_contract_intakes i
     LEFT JOIN public.customers c ON ((c.id = i.created_customer_id)));

