--
-- Name: company_customer_list_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_customer_list_summary_v WITH (security_invoker='true') AS
 SELECT c.id AS customer_id,
    c.company_id,
    c.customer_number,
    COALESCE(NULLIF(c.full_name, ''::text), NULLIF(c.company_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), 'Namnlös kund'::text) AS customer_name,
    c.email,
    c.phone,
    c.status,
    c.customer_type,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id))) AS sites_count,
    ( SELECT count(*) AS count
           FROM public.metering_points mp
          WHERE ((mp.company_id = c.company_id) AND (mp.customer_id = c.id))) AS metering_points_count,
    latest_contract.status AS active_contract_status,
    GREATEST(c.updated_at, COALESCE(latest_contract.updated_at, c.updated_at), COALESCE(( SELECT max(t.updated_at) AS max
           FROM public.customer_operation_tasks t
          WHERE ((t.company_id = c.company_id) AND (t.customer_id = c.id))), c.updated_at)) AS latest_activity_at,
    ( SELECT count(*) AS count
           FROM public.customer_operation_tasks t
          WHERE ((t.company_id = c.company_id) AND (t.customer_id = c.id) AND (t.status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text])))) AS blocking_reason_count
   FROM (public.customers c
     LEFT JOIN LATERAL ( SELECT cc.status,
            cc.updated_at
           FROM public.customer_contracts cc
          WHERE ((cc.company_id = c.company_id) AND (cc.customer_id = c.id))
          ORDER BY cc.updated_at DESC NULLS LAST, cc.created_at DESC
         LIMIT 1) latest_contract ON (true))
  WHERE ((c.company_id IS NOT NULL) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])));

--
-- Name: gridex_customer_list_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_list_summary(p_company_id uuid, p_limit integer DEFAULT 100) RETURNS SETOF public.company_customer_list_summary_v
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select *
  from public.company_customer_list_summary_v
  where company_id = p_company_id
  order by latest_activity_at desc nulls last
  limit greatest(1, least(coalesce(p_limit, 100), 500))
$$;

