--
-- Name: gridex_customer_operation_outcome_class(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_operation_outcome_class(p_status text, p_attempts integer, p_max_attempts integer) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when p_status = 'needs_review' then 'REVIEW'
    when p_status in ('blocked', 'cancelled') then 'STOP'
    when p_status = 'delivery_uncertain' then 'RETRY'
    when p_status = 'failed'
      and coalesce(p_attempts, 0) < greatest(coalesce(p_max_attempts, 1), 1)
      then 'RETRY'
    when p_status = 'failed' then 'STOP'
    else 'AUTO'
  end
$$;

--
-- Name: gridex_customer_portfolio_active_counts(uuid[], date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_active_counts(p_company_ids uuid[], p_at date DEFAULT CURRENT_DATE) RETURNS TABLE(company_id uuid, active_customers integer, active_metering_points integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_at date := coalesce(p_at, current_date);
begin
  if p_company_ids is null or cardinality(p_company_ids) > 1000 then
    raise exception 'Between 0 and 1000 companies are required' using errcode = '22023';
  end if;

  foreach v_id in array p_company_ids loop
    perform public.gridex_customer_portfolio_assert_read(v_id);
  end loop;

  return query
  select ids.id,
         count(distinct sp.customer_id)::integer,
         count(distinct sp.metering_point_id)::integer
  from unnest(p_company_ids) as ids(id)
  left join public.customer_supply_periods sp
    on sp.company_id = ids.id
   and sp.status <> 'cancelled'
   and sp.start_date <= v_at
   and (sp.end_date is null or sp.end_date > v_at)
  group by ids.id;
end;
$$;

--
-- Name: gridex_customer_portfolio_assert_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_assert_read(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_platform_id uuid;
begin
  if p_company_id is null then
    raise exception 'company_id is required' using errcode = '22023';
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    return;
  end if;

  if public.gridex_can_read_company(p_company_id) then
    return;
  end if;

  select c.white_label_platform_id into v_platform_id
  from public.companies c
  where c.id = p_company_id;

  if v_platform_id is not null and public.gridex_user_can_read_whitelabel_platform(v_platform_id) then
    return;
  end if;

  raise exception 'Not allowed to read portfolio for this company' using errcode = '42501';
end;
$$;

--
-- Name: gridex_customer_portfolio_bidding_zones(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_bidding_zones(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(bidding_zone_code text, active_customers integer, metering_points integer, forecast_12m_kwh numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_at date := coalesce(p_as_of, current_date);
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);

  return query
  with active as (
    select sp.customer_id, sp.metering_point_id,
           coalesce(nullif(upper(trim(mp.bidding_zone_code)), ''), 'UNKNOWN') as zone
    from public.customer_supply_periods sp
    left join public.metering_points mp on mp.id = sp.metering_point_id
    where sp.company_id = p_company_id and sp.status <> 'cancelled'
      and sp.start_date <= v_at and (sp.end_date is null or sp.end_date > v_at)
  ),
  fc as (
    select coalesce(nullif(upper(trim(mp.bidding_zone_code)), ''), 'UNKNOWN') as zone, sum(pf.kwh) as kwh
    from public.gridex_customer_portfolio_point_forecast_internal(p_company_id, v_at, 12) pf
    left join public.metering_points mp on mp.id = pf.metering_point_id
    group by 1
  )
  select z.zone,
         count(distinct a.customer_id)::integer,
         count(distinct a.metering_point_id)::integer,
         round(coalesce(max(fc.kwh), 0), 3)
  from (select zone from active union select zone from fc) z
  left join active a on a.zone = z.zone
  left join fc on fc.zone = z.zone
  group by z.zone
  order by z.zone;
end;
$$;

--
-- Name: gridex_customer_portfolio_churn_reasons(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_churn_reasons(p_company_id uuid, p_from date, p_to date) RETURNS TABLE(month date, reason text, customers integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 3700 then
    raise exception 'Invalid period' using errcode = '22023';
  end if;

  return query
  with spans as (
    select sp.customer_id,
           case when bool_or(sp.end_date is null) then null else max(sp.end_date) end as last_end
    from public.customer_supply_periods sp
    where sp.company_id = p_company_id and sp.status <> 'cancelled'
    group by sp.customer_id
  ),
  churned as (
    select s.customer_id, s.last_end
    from spans s
    where s.last_end between date_trunc('month', p_from)::date
                         and (date_trunc('month', p_to) + interval '1 month' - interval '1 day')::date
  )
  select date_trunc('month', ch.last_end)::date,
         coalesce(
           (select nullif(trim(cc.termination_reason), '') from public.customer_contracts cc
             where cc.company_id = p_company_id and cc.customer_id = ch.customer_id
               and cc.termination_reason is not null
             order by cc.ends_at desc nulls last limit 1),
           (select coalesce(nullif(trim(e.reason), ''), e.event_type) from public.customer_lifecycle_events e
             where e.company_id = p_company_id and e.customer_id = ch.customer_id
               and e.event_status = 'completed' and e.event_type in ('move_out', 'terminate')
             order by e.effective_date desc nulls last, e.created_at desc limit 1),
           'unknown'
         ) as reason,
         count(*)::integer
  from churned ch
  group by 1, 2
  order by 1, 3 desc;
end;
$$;

--
-- Name: gridex_customer_portfolio_cohorts(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_cohorts(p_company_id uuid, p_months integer DEFAULT 12) RETURNS TABLE(cohort_month date, customers integer, retained_1m numeric, retained_3m numeric, retained_6m numeric, retained_12m numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_months integer := least(greatest(coalesce(p_months, 12), 1), 36);
  v_from date := (date_trunc('month', current_date) - make_interval(months => v_months - 1))::date;
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);

  return query
  with periods as (
    select sp.customer_id, sp.start_date, sp.end_date
    from public.customer_supply_periods sp
    where sp.company_id = p_company_id and sp.status <> 'cancelled'
  ),
  members as (
    select p.customer_id, date_trunc('month', min(p.start_date))::date as cohort
    from periods p
    group by p.customer_id
    having min(p.start_date) >= v_from
  ),
  checks as (
    select mb.cohort, mb.customer_id, k.k,
           (mb.cohort + make_interval(months => k.k + 1) - interval '1 day')::date as at_date
    from members mb
    cross join (values (1), (3), (6), (12)) as k(k)
  ),
  results as (
    select c.cohort, c.customer_id, c.k, c.at_date, count(p.customer_id) > 0 as active
    from checks c
    left join periods p on p.customer_id = c.customer_id
      and p.start_date <= c.at_date and (p.end_date is null or p.end_date > c.at_date)
    group by c.cohort, c.customer_id, c.k, c.at_date
  ),
  rates as (
    select r.cohort, r.k,
           case when max(r.at_date) < current_date then round(avg(case when r.active then 1 else 0 end), 4) end as rate
    from results r
    group by r.cohort, r.k
  )
  select mb.cohort,
         count(*)::integer,
         max(ra.rate) filter (where ra.k = 1),
         max(ra.rate) filter (where ra.k = 3),
         max(ra.rate) filter (where ra.k = 6),
         max(ra.rate) filter (where ra.k = 12)
  from members mb
  left join rates ra on ra.cohort = mb.cohort
  group by mb.cohort
  order by mb.cohort;
end;
$$;

--
-- Name: gridex_customer_portfolio_expiring_poa(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_expiring_poa(p_company_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(power_of_attorney_id uuid, customer_id uuid, customer_name text, scope text, valid_to date, days_left integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);

  return query
  select x.id, x.customer_id,
         coalesce(nullif(trim(c.full_name), ''), nullif(trim(c.company_name), ''),
                  nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), c.customer_number),
         x.scope, x.valid_to, (x.valid_to - current_date)::integer
  from public.powers_of_attorney x
  left join public.customers c on c.id = x.customer_id and c.company_id = x.company_id
  where x.company_id = p_company_id
    and x.status in ('signed', 'accepted', 'active', 'completed')
    and x.valid_to between current_date and current_date + least(greatest(coalesce(p_days, 30), 1), 365)
  order by x.valid_to, x.id
  limit 500;
end;
$$;

--
-- Name: gridex_customer_portfolio_forecast(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_forecast(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(month date, month_index integer, forecast_kwh numeric, low_kwh numeric, high_kwh numeric, metering_points integer, points_with_history integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);
  return query
  select * from public.gridex_customer_portfolio_forecast_cached_internal(p_company_id, coalesce(p_as_of, current_date));
end;
$$;

--
-- Name: gridex_customer_portfolio_forecast_accuracy(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_forecast_accuracy(p_company_id uuid, p_from date, p_to date) RETURNS TABLE(month date, forecast_kwh numeric, actual_kwh numeric, diff_kwh numeric, diff_percent numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 3700 then
    raise exception 'Invalid period' using errcode = '22023';
  end if;

  return query
  with months as (
    select gs::date as m
    from generate_series(date_trunc('month', p_from)::date, date_trunc('month', p_to)::date, interval '1 month') gs
  ),
  fc as (
    select s.as_of_month as m, s.forecast_kwh
    from public.customer_portfolio_forecast_snapshots s
    where s.company_id = p_company_id and s.month_index = 1
  ),
  act as (
    select r.month as m, sum(r.kwh) as kwh
    from public.metering_point_monthly_consumption r
    where r.company_id = p_company_id
      and r.value_count > 0
      and r.month between date_trunc('month', p_from)::date and date_trunc('month', p_to)::date
    group by 1
  )
  select mo.m, fc.forecast_kwh, round(act.kwh, 3),
         round(act.kwh - fc.forecast_kwh, 3),
         case when fc.forecast_kwh > 0 then round((act.kwh - fc.forecast_kwh) / fc.forecast_kwh * 100, 2) end
  from months mo
  left join fc on fc.m = mo.m
  left join act on act.m = mo.m
  order by mo.m;
end;
$$;

--
-- Name: gridex_customer_portfolio_forecast_cached_internal(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_forecast_cached_internal(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(month date, month_index integer, forecast_kwh numeric, low_kwh numeric, high_kwh numeric, metering_points integer, points_with_history integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_month date := date_trunc('month', coalesce(p_as_of, current_date))::date;
begin
  if exists (
    select 1 from public.customer_portfolio_forecast_snapshots s
    where s.company_id = p_company_id and s.as_of_month = v_month
  ) then
    return query
    select s.month, s.month_index, s.forecast_kwh, s.low_kwh, s.high_kwh, s.metering_points, s.points_with_history
    from public.customer_portfolio_forecast_snapshots s
    where s.company_id = p_company_id and s.as_of_month = v_month
    order by s.month;
  else
    return query select * from public.gridex_customer_portfolio_forecast_internal(p_company_id, v_month, 12);
  end if;
end;
$$;

--
-- Name: gridex_customer_portfolio_forecast_internal(uuid, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_forecast_internal(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_months integer DEFAULT 12) RETURNS TABLE(month date, month_index integer, forecast_kwh numeric, low_kwh numeric, high_kwh numeric, metering_points integer, points_with_history integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_start date := date_trunc('month', coalesce(p_as_of, current_date))::date;
  v_months integer := least(greatest(coalesce(p_months, 12), 1), 24);
begin
  return query
  with targets as (
    select (v_start + make_interval(months => i))::date as t_month, i + 1 as idx
    from generate_series(0, v_months - 1) i
  ),
  pp as (
    select * from public.gridex_customer_portfolio_point_forecast_internal(p_company_id, v_start, v_months)
  )
  select t.t_month, t.idx,
         round(coalesce(sum(pp.kwh), 0), 3),
         round(coalesce(sum(pp.kwh * case when pp.exact then 0.92 when pp.has_history then 0.85 else 0.7 end), 0), 3),
         round(coalesce(sum(pp.kwh * case when pp.exact then 1.08 when pp.has_history then 1.15 else 1.3 end), 0), 3),
         count(pp.metering_point_id)::integer,
         count(pp.metering_point_id) filter (where pp.has_history)::integer
  from targets t
  left join pp on pp.month = t.t_month
  group by t.t_month, t.idx
  order by t.t_month;
end;
$$;

--
-- Name: gridex_customer_portfolio_monthly_internal(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_monthly_internal(p_company_id uuid, p_from date, p_to date) RETURNS TABLE(month date, active_customers_start integer, active_customers integer, new_customers integer, churned_customers integer, net_change integer, churn_rate numeric, active_metering_points integer, poa_requested integer, poa_signed integer, poa_active integer, metering_requests_total integer, metering_requests_historical integer, metering_requests_ongoing integer, metering_requests_failed integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_from date := date_trunc('month', p_from)::date;
  v_to date := date_trunc('month', p_to)::date;
begin
  return query
  with months as (
    select gs::date as m_start,
           (gs + interval '1 month' - interval '1 day')::date as m_end
    from generate_series(v_from, v_to, interval '1 month') gs
  ),
  periods as (
    select sp.customer_id, sp.metering_point_id, sp.start_date, sp.end_date
    from public.customer_supply_periods sp
    where sp.company_id = p_company_id
      and sp.status <> 'cancelled'
      and sp.start_date <= (v_to + interval '1 month' - interval '1 day')::date
      and (sp.end_date is null or sp.end_date >= v_from - 1)
  ),
  active as (
    select m.m_start,
           count(distinct p.customer_id) filter (
             where p.start_date <= m.m_start - 1 and (p.end_date is null or p.end_date > m.m_start - 1)) as start_cnt,
           count(distinct p.customer_id) filter (
             where p.start_date <= m.m_end and (p.end_date is null or p.end_date > m.m_end)) as end_cnt,
           count(distinct p.metering_point_id) filter (
             where p.start_date <= m.m_end and (p.end_date is null or p.end_date > m.m_end)) as points_cnt
    from months m
    join periods p on p.start_date <= m.m_end and (p.end_date is null or p.end_date > m.m_start - 1)
    group by m.m_start
  ),
  spans as (
    select sp.customer_id,
           min(sp.start_date) as first_start,
           case when bool_or(sp.end_date is null) then null else max(sp.end_date) end as last_end
    from public.customer_supply_periods sp
    where sp.company_id = p_company_id and sp.status <> 'cancelled'
    group by sp.customer_id
  ),
  starts as (
    select date_trunc('month', s.first_start)::date as m, count(*) as cnt
    from spans s where s.first_start >= v_from group by 1
  ),
  ends as (
    select date_trunc('month', s.last_end)::date as m, count(*) as cnt
    from spans s where s.last_end >= v_from group by 1
  ),
  poa as (
    select x.created_at::date as created_on, x.signed_at::date as signed_on,
           x.valid_from, x.valid_to, x.status
    from public.powers_of_attorney x
    where x.company_id = p_company_id
  ),
  poa_created as (
    select date_trunc('month', x.created_on)::date as m, count(*) as cnt from poa x where x.created_on >= v_from group by 1
  ),
  poa_signed as (
    select date_trunc('month', x.signed_on)::date as m, count(*) as cnt from poa x where x.signed_on >= v_from group by 1
  ),
  poa_valid as (
    select m.m_start, count(*) as cnt
    from months m
    join poa x on x.status in ('signed', 'accepted', 'active', 'completed')
      and coalesce(x.valid_from, x.signed_on, x.created_on) <= m.m_end
      and (x.valid_to is null or x.valid_to >= m.m_end)
    group by m.m_start
  ),
  req as (
    select date_trunc('month', x.requested_at)::date as m,
           count(*) as total,
           count(*) filter (where x.request_scope in ('meter_values', 'billing_underlay')
             and x.requested_period_start is not null
             and x.requested_period_start < date_trunc('month', x.requested_at)::date) as historical,
           count(*) filter (where x.request_scope in ('meter_values', 'billing_underlay')
             and (x.requested_period_start is null
                  or x.requested_period_start >= date_trunc('month', x.requested_at)::date)) as ongoing,
           count(*) filter (where x.status in ('failed', 'rejected', 'error')) as failed
    from public.grid_owner_data_requests x
    where x.company_id = p_company_id
      and x.requested_at >= v_from
      and x.requested_at < v_to + interval '1 month'
    group by 1
  )
  select m.m_start,
         coalesce(a.start_cnt, 0)::integer,
         coalesce(a.end_cnt, 0)::integer,
         coalesce(st.cnt, 0)::integer,
         coalesce(en.cnt, 0)::integer,
         null::integer,
         null::numeric,
         coalesce(a.points_cnt, 0)::integer,
         coalesce(pc.cnt, 0)::integer,
         coalesce(ps.cnt, 0)::integer,
         coalesce(pv.cnt, 0)::integer,
         coalesce(r.total, 0)::integer,
         coalesce(r.historical, 0)::integer,
         coalesce(r.ongoing, 0)::integer,
         coalesce(r.failed, 0)::integer
  from months m
  left join active a on a.m_start = m.m_start
  left join starts st on st.m = m.m_start
  left join ends en on en.m = m.m_start
  left join poa_created pc on pc.m = m.m_start
  left join poa_signed ps on ps.m = m.m_start
  left join poa_valid pv on pv.m_start = m.m_start
  left join req r on r.m = m.m_start
  order by m.m_start;
end;
$$;

--
-- Name: gridex_customer_portfolio_point_forecast_internal(uuid, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_point_forecast_internal(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_months integer DEFAULT 12) RETURNS TABLE(month date, month_index integer, metering_point_id uuid, kwh numeric, has_history boolean, exact boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_start date := date_trunc('month', coalesce(p_as_of, current_date))::date;
  v_hist_from date := (date_trunc('month', coalesce(p_as_of, current_date)) - interval '12 months')::date;
  v_months integer := least(greatest(coalesce(p_months, 12), 1), 24);
begin
  return query
  with targets as (
    select (v_start + make_interval(months => i))::date as t_month, i + 1 as idx
    from generate_series(0, v_months - 1) i
  ),
  profile as (
    select w.month_number, w.weight_percent * 12 / 100.0 as factor
    from public.consumption_profile_month_weights w
    where w.profile_id = (
      select cp.id from public.consumption_profiles cp
      where cp.is_default = true and (cp.company_id = p_company_id or cp.company_id is null)
      order by (cp.company_id is null), cp.created_at
      limit 1
    )
  ),
  points as (
    select sp.metering_point_id,
           case when bool_or(sp.end_date is null) then null else max(sp.end_date) end as supply_end
    from public.customer_supply_periods sp
    where sp.company_id = p_company_id
      and sp.status <> 'cancelled'
      and sp.start_date <= v_start
      and (sp.end_date is null or sp.end_date >= v_start)
    group by sp.metering_point_id
  ),
  history as (
    select r.metering_point_id, extract(month from r.month)::integer as month_number, r.kwh
    from public.metering_point_monthly_consumption r
    join points pt on pt.metering_point_id = r.metering_point_id
    where r.company_id = p_company_id
      and r.value_count > 0
      and r.month >= v_hist_from
      and r.month < v_start
  ),
  point_avg as (
    select h.metering_point_id, avg(h.kwh) as avg_kwh from history h group by 1
  ),
  company_avg as (
    select avg(pa.avg_kwh) as avg_kwh from point_avg pa
  )
  select t.t_month, t.idx, pt.metering_point_id,
         greatest(0, coalesce(
           h.kwh,
           pa.avg_kwh * coalesce(pr.factor, 1),
           (select ca.avg_kwh from company_avg ca) * coalesce(pr.factor, 1),
           0
         )),
         (pa.metering_point_id is not null),
         (h.kwh is not null)
  from targets t
  cross join points pt
  left join history h on h.metering_point_id = pt.metering_point_id
    and h.month_number = extract(month from t.t_month)::integer
  left join point_avg pa on pa.metering_point_id = pt.metering_point_id
  left join profile pr on pr.month_number = extract(month from t.t_month)::integer
  where pt.supply_end is null or pt.supply_end >= t.t_month;
end;
$$;

--
-- Name: gridex_customer_portfolio_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_portfolio_summary(p_company_id uuid, p_from date DEFAULT ((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) - '11 mons'::interval))::date, p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(month date, active_customers_start integer, active_customers integer, new_customers integer, churned_customers integer, net_change integer, churn_rate numeric, active_metering_points integer, poa_requested integer, poa_signed integer, poa_active integer, metering_requests_total integer, metering_requests_historical integer, metering_requests_ongoing integer, metering_requests_failed integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_customer_portfolio_assert_read(p_company_id);
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 3700 then
    raise exception 'Invalid period' using errcode = '22023';
  end if;

  return query
  select r.month, r.active_customers_start, r.active_customers, r.new_customers, r.churned_customers,
         r.active_customers - r.active_customers_start,
         case when r.active_customers_start > 0
              then round(r.churned_customers::numeric / r.active_customers_start, 4) end,
         r.active_metering_points, r.poa_requested, r.poa_signed, r.poa_active,
         r.metering_requests_total, r.metering_requests_historical, r.metering_requests_ongoing,
         r.metering_requests_failed
  from public.gridex_customer_portfolio_monthly_internal(p_company_id, p_from, p_to) r;
end;
$$;

--
-- Name: gridex_customer_retention_until_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_retention_until_v1(p_customer_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  -- The last business event decides the retention year; records are kept to
  -- the end of the seventh year after it, so anonymization is allowed from
  -- 1 January of the eighth year.
  select make_date(extract(year from last_event)::int + 8, 1, 1)
  from (
    select greatest(
      (select max(coalesce(i.paid_at, i.issued_at, i.created_at)) from public.customer_invoices i where i.customer_id = c.id),
      (select max(coalesce(p.actual_end_date, p.end_date)::timestamptz) from public.customer_supply_periods p where p.customer_id = c.id),
      c.archived_at,
      c.lifecycle_closed_at,
      c.created_at
    ) as last_event
    from public.customers c
    where c.id = p_customer_id
  ) last_activity
$$;

--
-- Name: gridex_customer_status_counts_v1(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_status_counts_v1(p_company_id uuid DEFAULT NULL::uuid, p_customer_type text DEFAULT 'all'::text, p_exclude_test_data boolean DEFAULT false) RETURNS TABLE(all_count bigint, draft bigint, pending_verification bigint, active bigint, inactive bigint, moved bigint, terminated bigint, blocked bigint, archived bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    count(*) filter (
      where c.status is null
         or c.status not in ('archived', 'deleted', 'deleted_test_only', 'pending_deletion')
    ) as all_count,
    count(*) filter (where c.status = 'draft') as draft,
    count(*) filter (where c.status = 'pending_verification') as pending_verification,
    count(*) filter (where c.status = 'active') as active,
    count(*) filter (where c.status = 'inactive') as inactive,
    count(*) filter (where c.status = 'moved') as moved,
    count(*) filter (where c.status = 'terminated') as terminated,
    count(*) filter (where c.status = 'blocked') as blocked,
    count(*) filter (where c.status = 'archived') as archived
  from public.customers c
  where c.company_id is not null
    and (p_company_id is null or c.company_id = p_company_id)
    and (c.source is null or c.source <> 'ediel_portal_test')
    and (
      coalesce(p_customer_type, 'all') = 'all'
      or (
        p_customer_type = 'private'
        and (c.customer_type is null or c.customer_type = 'private')
      )
      or (
        p_customer_type in ('business', 'association')
        and c.customer_type = p_customer_type
      )
    )
    and (
      not coalesce(p_exclude_test_data, false)
      or (
        (c.is_test_data is null or c.is_test_data = false)
        and (c.source is null or c.source not ilike '%test%')
      )
    );
$$;

--
-- Name: FUNCTION gridex_customer_status_counts_v1(p_company_id uuid, p_customer_type text, p_exclude_test_data boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_customer_status_counts_v1(p_company_id uuid, p_customer_type text, p_exclude_test_data boolean) IS 'Service-role aggregate for OPS customer status chips; preserves tenant/test/customer-type filters while collapsing nine count round-trips into one scan.';

--
-- Name: gridex_db1_default_company_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_default_company_id() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_company_id uuid;
  v_company_count integer := 0;
begin
  select count(*) into v_company_count from public.companies;

  if v_company_count = 0 then
    insert into public.companies (name, slug, company_slug, status, is_active, is_paused, metadata)
    values ('Div3rsa AB', 'div3rsa-ab', 'div3rsa-ab', 'active', true, false, '{"source":"db1_default_company"}'::jsonb)
    returning id into v_company_id;
    return v_company_id;
  end if;

  if v_company_count = 1 then
    select id
    into v_company_id
    from public.companies
    order by created_at nulls last, id::text
    limit 1;
    return v_company_id;
  end if;

  perform public.gridex_db1_log_finding(
    'warning',
    'default_company',
    'companies',
    'No default company selected because more than one company exists.',
    jsonb_build_object('company_count', v_company_count)
  );
  return null;
end;
$$;

--
-- Name: gridex_db1_finish_backfill_run(uuid, text, jsonb, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_finish_backfill_run(p_run_id uuid, p_status text, p_summary jsonb DEFAULT '{}'::jsonb, p_rows_seen integer DEFAULT 0, p_rows_inserted integer DEFAULT 0, p_rows_updated integer DEFAULT 0, p_rows_skipped integer DEFAULT 0, p_rows_failed integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  update public.backfill_runs
  set status = coalesce(p_status, 'completed'),
      completed_at = now(),
      rows_seen = coalesce(p_rows_seen, 0),
      rows_inserted = coalesce(p_rows_inserted, 0),
      rows_updated = coalesce(p_rows_updated, 0),
      rows_skipped = coalesce(p_rows_skipped, 0),
      rows_failed = coalesce(p_rows_failed, 0),
      summary = coalesce(p_summary, '{}'::jsonb)
  where id = p_run_id;

  return jsonb_build_object(
    'run_id', p_run_id,
    'status', coalesce(p_status, 'completed'),
    'rows_seen', coalesce(p_rows_seen, 0),
    'rows_inserted', coalesce(p_rows_inserted, 0),
    'rows_updated', coalesce(p_rows_updated, 0),
    'rows_skipped', coalesce(p_rows_skipped, 0),
    'rows_failed', coalesce(p_rows_failed, 0),
    'summary', coalesce(p_summary, '{}'::jsonb)
  );
end;
$$;

--
-- Name: gridex_db1_log_finding(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_log_finding(p_severity text, p_area text, p_object text, p_message text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  insert into public.gridex_schema_repair_findings(repair_key, severity, finding_area, object_name, message, details)
  values ('db1_schema_repair_backfill_foundation_20260522', p_severity, p_area, p_object, p_message, coalesce(p_details, '{}'::jsonb));
end;
$$;

--
-- Name: gridex_db1_start_backfill_run(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_start_backfill_run(p_run_key text, p_source_scope text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
begin
  insert into public.backfill_runs (run_key, source_scope, status, started_at, completed_at, summary)
  values (p_run_key, p_source_scope, 'running', now(), null, '{}'::jsonb)
  on conflict (run_key) do update
  set status = 'running',
      source_scope = excluded.source_scope,
      started_at = now(),
      completed_at = null,
      rows_seen = 0,
      rows_inserted = 0,
      rows_updated = 0,
      rows_skipped = 0,
      rows_failed = 0,
      summary = '{}'::jsonb
  returning id into v_run_id;

  return v_run_id;
end;
$$;

--
-- Name: gridex_db1_try_exec(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_try_exec(p_area text, p_object text, p_sql text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  execute p_sql;
exception when others then
  perform public.gridex_db1_log_finding(
    'warning',
    p_area,
    p_object,
    SQLERRM,
    jsonb_build_object('sqlstate', SQLSTATE, 'sql', p_sql)
  );
end;
$$;

--
-- Name: gridex_db4b_archive_customer_registry_row(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db4b_archive_customer_registry_row(p_lookup text, p_email text DEFAULT NULL::text, p_apply boolean DEFAULT false, p_reason text DEFAULT 'Archived old/test customer from active customer registry.'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_customer_count integer := 0;
  v_updated_customers integer := 0;
begin
  if nullif(btrim(coalesce(p_lookup, '')), '') is null
     and nullif(btrim(coalesce(p_email, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'p_lookup or p_email is required';
  end if;

  select count(*) into v_customer_count
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  if not p_apply then
    return jsonb_build_object(
      'apply', false,
      'matched_customers', v_customer_count,
      'matched_customer_profiles', 0,
      'message', 'Dry-run only. Re-run with p_apply=true to archive matching canonical customer rows.'
    );
  end if;

  insert into public.gridex_archived_customer_registry_rows(
    archived_by, archive_reason, source_table, source_id, source_email, source_row
  )
  select
    v_actor, p_reason, 'customers', customer.id::text, customer.email,
    to_jsonb(customer)
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  update public.customers customer
  set status = 'archived',
      metadata = coalesce(customer.metadata, '{}'::jsonb) || jsonb_build_object(
        'archived_from_active_registry', true,
        'archived_at', now(),
        'archived_reason', p_reason,
        'db4b_cleanup', true
      ),
      updated_at = now(),
      updated_by = coalesce(v_actor, customer.updated_by)
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );
  get diagnostics v_updated_customers = row_count;

  return jsonb_build_object(
    'apply', true,
    'matched_customers_before_apply', v_customer_count,
    'matched_customer_profiles_before_apply', 0,
    'archived_customers', v_updated_customers,
    'removed_customer_profiles', 0,
    'message', 'Matching canonical customer rows were archived. Authentication and tenant memberships were not touched.'
  );
end
$$;

--
-- Name: gridex_decide_customer_identity_change_v1(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_decide_customer_identity_change_v1(p_company_id uuid, p_request_id uuid, p_outcome text, p_decided_by text, p_actor_user_id uuid DEFAULT NULL::uuid, p_acceptance jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  r public.customer_identity_change_requests%rowtype;
  v_current text;
BEGIN
  IF p_outcome NOT IN ('applied', 'rejected', 'expired', 'cancelled') THEN
    RAISE EXCEPTION 'identity_change_outcome_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_decided_by NOT IN ('customer', 'staff', 'system') THEN
    RAISE EXCEPTION 'identity_change_actor_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO r FROM public.customer_identity_change_requests
   WHERE id = p_request_id AND company_id = p_company_id
   FOR UPDATE;
  IF r.id IS NULL THEN RAISE EXCEPTION 'identity_change_not_found' USING ERRCODE = 'P0002'; END IF;

  IF r.source_channel='staff_api' AND p_decided_by='staff' THEN
    PERFORM public.gridex_staff_assert_write_actor_v1(r.company_id,p_actor_user_id,r.api_client_id,'customers.write');
  END IF;
  IF r.status <> 'pending_customer_approval' THEN
    RAISE EXCEPTION 'identity_change_not_pending' USING ERRCODE = '55000';
  END IF;
  IF p_outcome = 'applied' AND r.approval_required AND p_decided_by <> 'customer' THEN
    RAISE EXCEPTION 'identity_change_requires_customer_approval' USING ERRCODE = '42501';
  END IF;
  IF p_outcome IN ('applied', 'rejected') AND r.approval_required AND r.expires_at <= now() THEN
    UPDATE public.customer_identity_change_requests SET status = 'expired', decided_at = now(), decided_by = 'system' WHERE id = r.id;
    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, field, previous_value_masked, new_value_masked)
    VALUES (r.company_id, r.customer_id, r.id, 'expired', 'system', r.field,
            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));
    RETURN jsonb_build_object('status', 'expired', 'request_id', r.id);
  END IF;

  -- A takeover of binding contracts needs the new party's explicit acceptance of exactly the
  -- contracts and terms that were shown (same snapshot hash), each confirmation separately.
  IF p_outcome = 'applied' AND r.takeover_required THEN
    IF p_acceptance IS NULL
       OR p_acceptance->>'snapshot_sha256' IS DISTINCT FROM r.takeover_snapshot_sha256
       OR (p_acceptance->'confirmations'->>'identity') IS DISTINCT FROM 'true'
       OR (p_acceptance->'confirmations'->>'contracts') IS DISTINCT FROM 'true'
       OR (p_acceptance->'confirmations'->>'terms') IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'identity_change_takeover_acceptance_required' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_outcome = 'applied' THEN
    -- The value must still be what the request was based on; otherwise someone changed it meanwhile.
    EXECUTE format('SELECT %I FROM public.customers WHERE company_id = $1 AND id = $2 FOR UPDATE', r.field)
      INTO v_current USING r.company_id, r.customer_id;
    IF v_current IS DISTINCT FROM r.previous_value THEN
      RAISE EXCEPTION 'identity_change_stale' USING ERRCODE = 'PT409';
    END IF;
    EXECUTE format('UPDATE public.customers SET %I = $1, updated_at = now() WHERE company_id = $2 AND id = $3', r.field)
      USING r.new_value, r.company_id, r.customer_id;
  END IF;

  UPDATE public.customer_identity_change_requests
     SET status = p_outcome, decided_at = now(), decided_by = p_decided_by,
         acceptance_evidence = CASE WHEN p_outcome = 'applied' AND p_decided_by = 'customer' AND p_acceptance IS NOT NULL
                                    THEN p_acceptance || jsonb_build_object('accepted_at', now())
                                    ELSE acceptance_evidence END
   WHERE id = r.id;

  IF r.approval_required AND p_outcome IN ('applied', 'rejected') THEN
    INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked)
    VALUES (r.company_id, r.customer_id, r.id, CASE WHEN p_outcome = 'applied' THEN 'approved' ELSE 'rejected' END,
            p_decided_by, p_actor_user_id, r.field,
            public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value));
  END IF;
  INSERT INTO public.customer_identity_change_events (company_id, customer_id, request_id, event_type, actor_kind, actor_user_id, field, previous_value_masked, new_value_masked, detail)
  VALUES (r.company_id, r.customer_id, r.id,
          CASE p_outcome WHEN 'applied' THEN 'applied' WHEN 'rejected' THEN 'rejected' ELSE p_outcome END,
          p_decided_by, p_actor_user_id, r.field,
          public.gridex_mask_identity_number(r.previous_value), public.gridex_mask_identity_number(r.new_value),
          jsonb_build_object('affected_contract_count', r.affected_contract_count, 'approval_required', r.approval_required,
                             'takeover_required', r.takeover_required, 'takeover_snapshot_sha256', r.takeover_snapshot_sha256,
                             'document_sha256', r.document_sha256,
                             'channel',r.source_channel,'api_client_id',r.api_client_id,
                             'originating_staff_actor_user_id',r.requested_by));

  INSERT INTO public.audit_logs (company_id, actor_user_id, actor_type, system_actor, entity_type, entity_id, action,
                                 old_values, new_values, metadata, request_id, correlation_id, resource_type, resource_id)
  VALUES (r.company_id, p_actor_user_id,
          CASE WHEN p_actor_user_id IS NULL THEN 'system' ELSE 'user' END,
          CASE WHEN p_actor_user_id IS NULL THEN 'customer_identity_change:' || p_decided_by ELSE NULL END,
          'customer', r.customer_id::text, 'customer_identity_change_' || p_outcome,
          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.previous_value)),
          jsonb_build_object(r.field, public.gridex_mask_identity_number(r.new_value)),
          jsonb_build_object('identity_change_request_id', r.id, 'decided_by', p_decided_by,
                             'approval_required', r.approval_required, 'affected_contract_count', r.affected_contract_count,
                             'takeover_required', r.takeover_required, 'takeover_snapshot_sha256', r.takeover_snapshot_sha256,
                             'document_sha256', r.document_sha256,
                             'channel',r.source_channel,'api_client_id',r.api_client_id,
                             'originating_staff_actor_user_id',r.requested_by),
          r.id::text, r.id::text, 'customer_identity_change_request', r.id::text);

  RETURN jsonb_build_object('status', p_outcome, 'request_id', r.id, 'customer_id', r.customer_id, 'field', r.field);
END $_$;

--
-- Name: gridex_default_customer_number_prefix(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_default_customer_number_prefix(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
begin
  select public.gridex_normalize_customer_number_prefix(
           coalesce(
             nullif(c.customer_number_prefix, ''),
             nullif(s.prefix, ''),
             c.metadata->>'customer_number_prefix'
           ),
           coalesce(nullif(c.slug, ''), nullif(c.name, ''), 'GDX')
         )
    into v_prefix
  from public.companies c
  left join public.company_customer_number_sequences s on s.company_id = c.id
  where c.id = p_company_id;

  return coalesce(v_prefix, 'GDX');
end;
$$;

--
-- Name: gridex_default_document_prefix(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_default_document_prefix(p_company_id uuid, p_sequence_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
  v_company_name text;
begin
  select c.name,
         case
           when p_sequence_key = 'contract' then c.contract_number_prefix
           when p_sequence_key = 'application' then c.application_number_prefix
           else null
         end
    into v_company_name, v_prefix
  from public.companies c
  where c.id = p_company_id;

  if v_prefix is null or btrim(v_prefix) = '' then
    v_prefix := case
      when p_sequence_key = 'contract' then 'AVT'
      when p_sequence_key = 'application' then 'APP'
      else upper(left(regexp_replace(coalesce(v_company_name, 'DOC'), '[^A-Za-z0-9]', '', 'g'), 6))
    end;
  end if;

  v_prefix := upper(regexp_replace(v_prefix, '[^A-Z0-9]', '', 'g'));
  if length(v_prefix) < 2 then
    v_prefix := rpad(v_prefix, 2, 'X');
  end if;
  return left(v_prefix, 16);
end;
$$;

--
-- Name: gridex_delete_partner_webhook_subscription_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_partner_webhook_subscription_v1(p_company_id uuid, p_api_client_id uuid, p_subscription_reference text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_subscription public.webhook_subscriptions%rowtype;
  v_secret_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;

  select *
  into v_subscription
  from public.webhook_subscriptions
  where company_id = p_company_id
    and api_client_id = p_api_client_id
    and webhook_subscription_reference = btrim(p_subscription_reference)
  for update;

  if not found then
    return false;
  end if;

  begin
    v_secret_id := nullif(v_subscription.signing_secret_ref,'')::uuid;
  exception when invalid_text_representation then
    v_secret_id := null;
  end;

  delete from public.webhook_subscriptions
  where id = v_subscription.id
    and company_id = p_company_id
    and api_client_id = p_api_client_id;

  if v_secret_id is not null then
    delete from vault.secrets where id = v_secret_id;
  end if;
  return true;
end
$$;

--
-- Name: gridex_delete_test_customer_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_test_customer_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_customer public.customers%rowtype;
  v_site_ids uuid[];
  v_point_ids uuid[];
  v_outbound_ids uuid[];
  v_test_run_ids uuid[];
  v_protected text[] := '{}';
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_delete_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_actor_user_id is null then
    raise exception using errcode = '22023', message = 'customer_delete_payload_invalid';
  end if;

  select * into v_customer
  from public.customers
  where id = p_customer_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;

  if v_customer.is_test_data is not true
     and coalesce(lower(v_customer.source), '') not like '%test%' then
    raise exception using errcode = '23514', message = 'customer_delete_requires_test_data';
  end if;

  select coalesce(array_agg(id), '{}') into v_site_ids
  from public.customer_sites where customer_id = p_customer_id;
  select coalesce(array_agg(id), '{}') into v_point_ids
  from public.metering_points
  where customer_id = p_customer_id or site_id = any (v_site_ids);

  -- Same protected-history rule as the customer card: real history is archived, never deleted.
  if exists (select 1 from public.customer_contracts where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'customer_contracts'); end if;
  if exists (select 1 from public.customer_invoices where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'customer_invoices'); end if;
  if exists (select 1 from public.supplier_switch_requests where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'supplier_switch_requests'); end if;
  if exists (select 1 from public.ediel_messages
             where customer_id = p_customer_id
                or site_id = any (v_site_ids)
                or metering_point_id = any (v_point_ids)) then
    v_protected := array_append(v_protected, 'ediel_messages'); end if;
  if exists (select 1 from public.partner_exports where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'partner_exports'); end if;
  if exists (select 1 from public.grid_owner_information_requests
             where customer_id = p_customer_id or customer_site_id = any (v_site_ids)) then
    v_protected := array_append(v_protected, 'grid_owner_information_requests'); end if;
  if exists (select 1 from public.powers_of_attorney where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'powers_of_attorney'); end if;
  if exists (select 1 from public.customer_documents where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'customer_documents'); end if;
  if exists (select 1 from public.customer_operation_events where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'customer_operation_events'); end if;
  if exists (select 1 from public.customer_blockers where customer_id = p_customer_id) then
    v_protected := array_append(v_protected, 'customer_blockers'); end if;
  if exists (select 1 from public.communication_logs
             where customer_id = p_customer_id
                or site_id = any (v_site_ids)
                or metering_point_id = any (v_point_ids)) then
    v_protected := array_append(v_protected, 'communication_logs'); end if;

  if cardinality(v_protected) > 0 then
    raise exception using
      errcode = '23514',
      message = 'customer_delete_protected_history',
      detail = array_to_string(v_protected, ',');
  end if;

  -- Audit first; the row survives because audit_logs has no customer foreign key.
  insert into public.audit_logs (
    actor_user_id, company_id, entity_type, entity_id, action, old_values, metadata
  ) values (
    p_actor_user_id, p_company_id, 'customer', p_customer_id::text, 'customer.deleted_test',
    to_jsonb(v_customer),
    jsonb_build_object(
      'label', 'Raderade testkund',
      'sites', cardinality(v_site_ids),
      'meteringPoints', cardinality(v_point_ids),
      'source', 'gridex_delete_test_customer_v1'
    )
  );

  select coalesce(array_agg(id), '{}') into v_test_run_ids
  from public.ediel_test_runs
  where customer_id = p_customer_id
     or site_id = any (v_site_ids)
     or metering_point_id = any (v_point_ids);
  delete from public.ediel_test_run_messages where test_run_id = any (v_test_run_ids);
  delete from public.ediel_test_runs where id = any (v_test_run_ids);

  select coalesce(array_agg(id), '{}') into v_outbound_ids
  from public.outbound_requests where customer_id = p_customer_id;
  delete from public.outbound_dispatch_events where outbound_request_id = any (v_outbound_ids);
  delete from public.outbound_requests where id = any (v_outbound_ids);

  delete from public.customer_portal_events where customer_id = p_customer_id;
  delete from public.metering_values where customer_id = p_customer_id;
  delete from public.billing_underlays where customer_id = p_customer_id;
  delete from public.grid_owner_data_requests where customer_id = p_customer_id;
  delete from public.customer_authorization_documents where customer_id = p_customer_id;
  delete from public.customer_operation_tasks where customer_id = p_customer_id;
  delete from public.customer_internal_notes where customer_id = p_customer_id;
  delete from public.customer_portal_claims where customer_id = p_customer_id;
  delete from public.customer_portal_accounts where customer_id = p_customer_id;
  delete from public.customer_addresses where customer_id = p_customer_id;
  delete from public.customer_contacts where customer_id = p_customer_id;
  delete from public.metering_points where id = any (v_point_ids);
  delete from public.customer_sites where id = any (v_site_ids);
  delete from public.customers where id = p_customer_id and company_id = p_company_id;

  return jsonb_build_object(
    'deleted', true,
    'sites', cardinality(v_site_ids),
    'metering_points', cardinality(v_point_ids),
    'test_runs', cardinality(v_test_run_ids),
    'outbound_requests', cardinality(v_outbound_ids)
  );
end
$$;

--
-- Name: gridex_delete_unused_contract(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_preview jsonb;
  v_graph jsonb;
  v_product_id uuid;
  v_public_offer_ids uuid[]:='{}'::uuid[];
  v_assignment_ids uuid[]:='{}'::uuid[];
  v_product_version_ids uuid[]:='{}'::uuid[];
  v_publication_ids uuid[]:='{}'::uuid[];
  v_publication_version_ids uuid[]:='{}'::uuid[];
  v_legal_version_ids uuid[]:='{}'::uuid[];
  v_counts jsonb:='{}'::jsonb;
  v_count bigint;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.delete_unused');
  select * into o
  from public.contract_offers co
  where co.id=p_offer_id and co.company_id=p_company_id
  for update;
  if not found then
    raise exception using errcode='P0002',message='contract_offer_not_found';
  end if;

  v_preview:=public.gridex_preview_delete_unused_contract(p_company_id,p_offer_id);
  if not coalesce((v_preview->>'can_delete')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'deleted',false,'mode','blocked',
      'code','contract_delete_blocked',
      'reason_codes',coalesce(v_preview->'reason_codes','[]'::jsonb),
      'blockers',coalesce(v_preview->'blockers','[]'::jsonb),
      'recommended_action',coalesce(v_preview->>'recommended_action','review'),
      'delete_preview',v_preview
    );
  end if;

  v_graph:=v_preview->'graph';
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_public_offer_ids
    from jsonb_array_elements_text(coalesce(v_graph->'public_contract_offer_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_assignment_ids
    from jsonb_array_elements_text(coalesce(v_graph->'tenant_assignment_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_product_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'contract_product_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_publication_ids
    from jsonb_array_elements_text(coalesce(v_graph->'publication_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_publication_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'publication_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_legal_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'legal_bundle_version_ids','[]'::jsonb));

  v_product_id:=o.contract_product_id;
  perform set_config('gridex.public_offer_write','on',true);
  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.publication_link_repair','on',true);

  update public.tenant_contract_channels ch
  set status='ended',
      valid_to=coalesce(ch.valid_to,now()),
      updated_by=p_actor_user_id,
      updated_at=now()
  where ch.assignment_id=any(v_assignment_ids) and ch.status<>'ended';

  update public.contract_publications cp
  set status='ended',updated_at=now()
  where cp.id=any(v_publication_ids) and cp.status not in ('ended','archived');

  update public.contract_publication_versions cpv
  set status='ended',valid_to=coalesce(cpv.valid_to,now())
  where cpv.id=any(v_publication_version_ids)
    and cpv.status not in ('ended','archived');

  update public.contract_publication_versions cpv
  set legacy_public_contract_offer_id=null
  where cpv.legacy_public_contract_offer_id=any(v_public_offer_ids);

  -- Diagnostics belong to the removed technical graph. Delete them before the
  -- public offer regardless of historical FK action drift.
  delete from public.contract_lifecycle_backfill_issues i
  where i.company_id=p_company_id and (
    i.contract_offer_id=p_offer_id
    or i.public_contract_offer_id=any(v_public_offer_ids)
  );
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_lifecycle_backfill_issues',v_count);

  perform public.gridex_assert_no_public_offer_fk_references(v_public_offer_ids);

  delete from public.contract_offer_versions cov
  where cov.company_id=p_company_id and cov.contract_offer_id=o.id;
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_offer_versions',v_count);

  delete from public.public_contract_offers pco where pco.id=any(v_public_offer_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('public_contract_offers',v_count);

  delete from public.contract_publication_versions cpv
  where cpv.id=any(v_publication_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_publication_versions',v_count);

  delete from public.contract_publications cp where cp.id=any(v_publication_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_publications',v_count);

  delete from public.tenant_contract_channels ch where ch.assignment_id=any(v_assignment_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('tenant_contract_channels',v_count);

  delete from public.tenant_contract_assignments ta where ta.id=any(v_assignment_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('tenant_contract_assignments',v_count);

  delete from public.contract_offers co
  where co.id=o.id and co.company_id=p_company_id;
  get diagnostics v_count=row_count;
  if v_count<>1 then
    raise exception using errcode='55000',message='contract_offer_delete_count_mismatch';
  end if;
  v_counts:=v_counts||jsonb_build_object('contract_offers',v_count);

  delete from public.legal_bundle_version_documents d
  where d.legal_bundle_version_id=any(v_legal_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('legal_bundle_version_documents',v_count);

  delete from public.legal_bundle_versions lbv where lbv.id=any(v_legal_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('legal_bundle_versions',v_count);

  delete from public.contract_product_versions cpv
  where cpv.id=any(v_product_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_product_versions',v_count);

  if v_product_id is not null
     and not exists(
       select 1 from public.contract_product_versions cpv
       where cpv.contract_product_id=v_product_id
     ) then
    delete from public.contract_products cp
    where cp.id=v_product_id and cp.company_id=p_company_id;
    get diagnostics v_count=row_count;
    v_counts:=v_counts||jsonb_build_object('contract_products',v_count);
  end if;

  -- Price versions/books are immutable shared pricing evidence and have many
  -- later consumers (quotes, portfolio, invoices). Contract deletion does not
  -- own their garbage collection.
  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_product',coalesce(v_product_id,p_offer_id)::text,
    'contract.delete_unused',to_jsonb(o),null,
    jsonb_build_object('offer_id',p_offer_id,'deleted_rows',v_counts,'preview',v_preview)
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'deleted',true,'mode','deleted',
    'offer_id',p_offer_id,'contract_product_id',v_product_id,
    'deleted_rows',v_counts
  );
end $$;

--
-- Name: FUNCTION gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Atomically deletes a completely unused exclusive contract graph after locking, shared resolver preview, safe compatibility repair and final dynamic FK assertions.';

--
-- Name: gridex_delete_unused_contract_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_preview jsonb;
  v_result jsonb;
  v_offer_exists boolean:=false;
begin
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.delete_unused'
  );

  perform pg_advisory_xact_lock(
    hashtextextended(
      'gridex:contract-delete:'||p_company_id::text||':'||p_offer_id::text,
      0
    )
  );

  select true into v_offer_exists
  from public.contract_offers offer
  where offer.id=p_offer_id
    and offer.company_id=p_company_id
  for update;

  if not coalesce(v_offer_exists,false) then
    if exists(
      select 1
      from public.audit_logs audit
      where audit.company_id=p_company_id
        and audit.action='contract.delete_unused'
        and audit.metadata->>'offer_id'=p_offer_id::text
    ) then
      return jsonb_build_object(
        'ok',true,
        'changed',false,
        'deleted',true,
        'mode','deleted',
        'code','contract_already_deleted',
        'offer_id',p_offer_id
      );
    end if;
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_not_found',
      'recommended_action','none',
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_offer',
        'resource_id',null,
        'count',0,
        'reason','contract_not_found',
        'classification','repairable_broken_relation',
        'recommended_action','none',
        'message','Avtalet hittades inte för valt bolag.'
      ))
    );
  end if;

  v_preview:=public.gridex_contract_delete_dependency_graph_v2(
    p_company_id,
    p_offer_id
  );

  if nullif(p_expected_preview_token,'') is not null
     and p_expected_preview_token is distinct from v_preview->>'preview_token' then
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_delete_preview_stale',
      'message','Avtalsberoendena ändrades efter förhandsgranskningen. Granska raderingen igen.',
      'recommended_action','refresh_preview',
      'delete_preview',v_preview,
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_product',
        'resource_id',v_preview->>'contract_product_id',
        'count',1,
        'reason','contract_delete_preview_stale',
        'classification','repairable_broken_relation',
        'recommended_action','refresh_preview',
        'message','Avtalsberoendena ändrades efter förhandsgranskningen.'
      ))
    );
  end if;

  if not coalesce((v_preview->>'can_delete')::boolean,false) then
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_delete_blocked',
      'message','Avtalet har historik eller beroenden som måste bevaras.',
      'reason_codes',coalesce(v_preview->'reason_codes','[]'::jsonb),
      'blockers',coalesce(v_preview->'blockers','[]'::jsonb),
      'recommended_action',coalesce(v_preview->>'recommended_action','archive'),
      'delete_preview',v_preview
    );
  end if;

  -- The existing commit performs the exact same canonical preview again while
  -- the offer row remains locked, and deletes only the approved internal graph.
  v_result:=public.gridex_delete_unused_contract(
    p_company_id,
    p_offer_id,
    p_actor_user_id
  );

  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
    'preview_token',v_preview->>'preview_token',
    'delete_preview',v_preview
  );
end
$$;

--
-- Name: FUNCTION gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text) IS 'Concurrency-safe, idempotent permanent delete for unused contracts. Repeats the canonical dependency graph under advisory and row locks.';

--
-- Name: gridex_dependency_circuit_before_request_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dependency_circuit_before_request_v1(p_dependency_key text, p_probe_lease_seconds integer DEFAULT 30) RETURNS TABLE(allowed boolean, circuit_state text, retry_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare v_key text:=lower(btrim(coalesce(p_dependency_key,''))); v_row public.dependency_circuit_state%rowtype;
begin
  if v_key !~ '^[a-z0-9._:-]{2,100}$' or p_probe_lease_seconds<5 or p_probe_lease_seconds>300 then raise exception using errcode='22023',message='dependency_circuit_input_invalid'; end if;
  insert into public.dependency_circuit_state(dependency_key) values(v_key) on conflict(dependency_key) do nothing;
  select * into v_row from public.dependency_circuit_state where dependency_key=v_key for update;
  if v_row.state='closed' then update public.dependency_circuit_state set last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'closed'::text,null::timestamptz; return; end if;
  if v_row.state='open' and v_row.half_open_after<=now() then update public.dependency_circuit_state set state='half_open',probe_lease_expires_at=now()+make_interval(secs=>p_probe_lease_seconds),last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'half_open'::text,null::timestamptz; return; end if;
  if v_row.state='half_open' and (v_row.probe_lease_expires_at is null or v_row.probe_lease_expires_at<=now()) then update public.dependency_circuit_state set probe_lease_expires_at=now()+make_interval(secs=>p_probe_lease_seconds),last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'half_open'::text,null::timestamptz; return; end if;
  return query select false,v_row.state,coalesce(v_row.half_open_after,v_row.probe_lease_expires_at);
end $_$;

--
-- Name: dependency_circuit_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dependency_circuit_state (
    dependency_key text NOT NULL,
    state text DEFAULT 'closed'::text NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    opened_at timestamp with time zone,
    half_open_after timestamp with time zone,
    probe_lease_expires_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    last_error_code text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dependency_circuit_state_consecutive_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT dependency_circuit_state_state_check CHECK ((state = ANY (ARRAY['closed'::text, 'open'::text, 'half_open'::text])))
);

--
-- Name: gridex_dependency_circuit_record_v1(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dependency_circuit_record_v1(p_dependency_key text, p_outcome text, p_error_code text DEFAULT NULL::text, p_failure_threshold integer DEFAULT 5, p_open_seconds integer DEFAULT 60) RETURNS public.dependency_circuit_state
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare v_key text:=lower(btrim(coalesce(p_dependency_key,''))); v_outcome text:=lower(btrim(coalesce(p_outcome,''))); v_result public.dependency_circuit_state%rowtype;
begin
  if v_key !~ '^[a-z0-9._:-]{2,100}$' or v_outcome not in ('success','failure') or p_failure_threshold<1 or p_failure_threshold>100 or p_open_seconds<5 or p_open_seconds>3600 then raise exception using errcode='22023',message='dependency_circuit_input_invalid'; end if;
  insert into public.dependency_circuit_state(dependency_key) values(v_key) on conflict(dependency_key) do nothing;
  if v_outcome='success' then update public.dependency_circuit_state set state='closed',consecutive_failures=0,opened_at=null,half_open_after=null,probe_lease_expires_at=null,last_success_at=now(),last_attempt_at=now(),last_error_code=null,updated_at=now() where dependency_key=v_key returning * into v_result;
  else update public.dependency_circuit_state set consecutive_failures=consecutive_failures+1,state=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then 'open' else state end,opened_at=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then now() else opened_at end,half_open_after=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then now()+make_interval(secs=>p_open_seconds) else half_open_after end,probe_lease_expires_at=null,last_failure_at=now(),last_attempt_at=now(),last_error_code=nullif(left(btrim(coalesce(p_error_code,'')),100),''),updated_at=now() where dependency_key=v_key returning * into v_result; end if;
  return v_result;
end $_$;

--
-- Name: gridex_dispute_information_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dispute_information_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select length(btrim(coalesce(p_value->>'authority',''))) >= 3
     and (coalesce(p_value->>'url','') ~* '^https?://' or length(btrim(coalesce(p_value->>'description',''))) >= 20)
$$;

--
-- Name: gridex_ediel_accepted_transport_projection_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ediel_accepted_transport_projection_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; candidates jsonb; candidate jsonb; binding jsonb; provider jsonb; plan jsonb; recipient text; original_hash text;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR p_message_id IS NULL OR (p_environment IN ('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR SHARE;
 RETURN gridex_ediel_transport.accepted_source_basis_v1(m);
END $$;

