--
-- Name: gridex_ediel_message_inbound_email_tenant_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ediel_message_inbound_email_tenant_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.inbound_email_message_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.inbound_email_messages m
    WHERE m.id = NEW.inbound_email_message_id
      AND m.company_id IS NOT DISTINCT FROM NEW.company_id
  ) THEN
    RAISE EXCEPTION 'ediel_message_inbound_email_tenant_mismatch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

--
-- Name: gridex_ediel_message_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ediel_message_summary(p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(total_messages bigint, inbound_messages bigint, outbound_messages bigint, draft_messages bigint, failed_messages bigint, queued_messages bigint, prepared_messages bigint, sent_messages bigint, ack_pending_messages bigint, ack_overdue_messages bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    select
      count(*) as total_messages,
      count(*) filter (where direction = 'inbound') as inbound_messages,
      count(*) filter (where direction = 'outbound') as outbound_messages,
      count(*) filter (where status = 'draft') as draft_messages,
      count(*) filter (where status = 'failed') as failed_messages,
      count(*) filter (where status = 'queued') as queued_messages,
      count(*) filter (where status = 'prepared') as prepared_messages,
      count(*) filter (where status = 'sent') as sent_messages,
      count(*) filter (
        where contrl_status = 'pending' or aperak_status = 'pending'
      ) as ack_pending_messages,
      count(*) filter (
        where (contrl_status = 'pending' or aperak_status = 'pending')
          and ack_due_at < now()
      ) as ack_overdue_messages
    from public.ediel_messages
    where p_company_id is null or company_id = p_company_id
  $$;

