--
-- Name: gridex_ediel_negative_fixture_read_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ediel_negative_fixture_read_v1(p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'ediel_negative_fixture_service_required' USING ERRCODE='42501';END IF;
 RETURN gridex_negative_fixtures.read_v1(p_context);END$$;

