--
-- Name: gridex_insert_jsonb_row(regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_insert_jsonb_row(p_table regclass, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_columns text;
  v_select text;
  v_sql text;
  v_result jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'row payload must be a JSON object' using errcode = '22023';
  end if;

  select string_agg(format('%I', a.attname), ', ' order by a.attnum),
         string_agg(format('x.%I', a.attname), ', ' order by a.attnum)
    into v_columns, v_select
    from pg_attribute a
   where a.attrelid = p_table
     and a.attnum > 0
     and not a.attisdropped
     and a.attgenerated = ''
     and a.attidentity = ''
     and p_payload ? a.attname;

  if v_columns is null then
    raise exception 'payload has no writable columns for %', p_table using errcode = '22023';
  end if;

  v_sql := format(
    'insert into %s as target (%s) select %s from jsonb_populate_record(null::%s, $1) x returning to_jsonb(target)',
    p_table, v_columns, v_select, p_table
  );
  execute v_sql into v_result using p_payload;
  return v_result;
end;
$_$;

--
-- Name: gridex_internal_write_tenant_row_v1(regclass, uuid, uuid, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_internal_write_tenant_row_v1(p_table regclass, p_company_id uuid, p_id uuid, p_values jsonb, p_allowed text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_cols text;
  v_id uuid;
begin
  select string_agg(format('%I', key), ',' order by key)
    into v_cols
    from jsonb_object_keys(coalesce(p_values, '{}'::jsonb)) as key
   where key = any(p_allowed);

  if p_id is null then
    if v_cols is null then
      raise exception using errcode = '22023', message = 'tenant_row_insert_without_columns';
    end if;
    execute format(
      'insert into %s (company_id,%s) select $1,%s from jsonb_populate_record(null::%s, $2) returning id',
      p_table, v_cols, v_cols, p_table)
      into v_id using p_company_id, p_values;
    return v_id;
  end if;

  if v_cols is not null then
    execute format(
      'update %s set (%s) = (select %s from jsonb_populate_record(null::%s, $3)) where id = $1 and company_id = $2 returning id',
      p_table, v_cols, v_cols, p_table)
      into v_id using p_id, p_company_id, p_values;
    if v_id is null then
      raise exception using errcode = 'P0002', message = 'tenant_row_not_found_for_company';
    end if;
  end if;
  return p_id;
end;
$_$;

--
-- Name: gridex_invalidate_site_operations_on_address_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invalidate_site_operations_on_address_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_hash text := nullif(btrim(old.address_hash), '');
  v_new_hash text := nullif(btrim(new.address_hash), '');
  v_old_raw_fingerprint text;
  v_new_raw_fingerprint text;
  v_address_changed boolean;
begin
  v_old_raw_fingerprint := lower(concat_ws('|',
    nullif(btrim(old.street), ''),
    regexp_replace(coalesce(old.postal_code, ''), '\D', '', 'g'),
    nullif(btrim(old.city), ''),
    nullif(btrim(old.country), '')
  ));
  v_new_raw_fingerprint := lower(concat_ws('|',
    nullif(btrim(new.street), ''),
    regexp_replace(coalesce(new.postal_code, ''), '\D', '', 'g'),
    nullif(btrim(new.city), ''),
    nullif(btrim(new.country), '')
  ));

  if v_old_hash is null and v_new_hash is not null then
    -- First canonicalization. A hash representation being added is not itself
    -- an address mutation; only a simultaneous semantic raw-address change is.
    v_address_changed := v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  elsif v_old_hash is not null and v_new_hash is not null then
    -- Once canonical identity exists, the hash is authoritative. Also fail
    -- closed if raw address data changes without the caller rotating the hash.
    v_address_changed :=
      v_old_hash is distinct from v_new_hash
      or v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  else
    -- Covers raw-address-only sites and removal of an established canonical
    -- hash. Both are treated conservatively as mutations when identity changes.
    v_address_changed :=
      v_old_hash is distinct from v_new_hash
      or v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  end if;

  if v_address_changed then
    update public.customer_operation_jobs
       set status = 'needs_review',
           stale_reason = 'site_address_changed_after_operation_started',
           locked_at = null,
           locked_by = null,
           lock_token = null,
           completed_at = now(),
           updated_at = now()
     where company_id = new.company_id
       and customer_site_id = new.id
       and status in ('queued', 'running', 'waiting_response');

    update public.customer_operation_request_snapshots
       set superseded_at = now()
     where company_id = new.company_id
       and customer_site_id = new.id
       and superseded_at is null;
  end if;

  return new;
end;
$$;

--
-- Name: gridex_invoice_export_files_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invoice_export_files_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'invoice_export_files_append_only' USING ERRCODE = '42501';
END $$;

--
-- Name: gridex_invoice_fee_readiness(jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invoice_fee_readiness(p_snapshot jsonb, p_row_amount numeric) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with raw_components as (
  select component
  from jsonb_array_elements(
    case
      when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components')='array'
        then coalesce(p_snapshot,'{}'::jsonb)->'price_components'
      when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components_snapshot')='array'
        then coalesce(p_snapshot,'{}'::jsonb)->'price_components_snapshot'
      else '[]'::jsonb
    end
  ) component
  where coalesce(
    nullif(component->>'component_code',''),
    nullif(component->>'component_type',''),
    nullif(component#>>'{metadata,component_code}','')
  )='invoice_fee'
  and coalesce(nullif(component->>'status',''),'active')='active'
), normalized as (
  select
    component,
    public.gridex_safe_nonnegative_numeric(component->>'amount') as amount,
    component->>'unit' as unit,
    component->>'calculation_type' as calculation_type,
    case
      when lower(coalesce(component->>'website_card_visible','')) in('true','false')
        then (component->>'website_card_visible')::boolean
      when lower(coalesce(component#>>'{metadata,visibility,website_card}','')) in('true','false')
        then (component#>>'{metadata,visibility,website_card}')::boolean
      else true
    end as website_card_visible
  from raw_components
), scored as (
  select
    count(*)::integer as component_count,
    count(*) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    )::integer as valid_component_count,
    min(amount) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    ) as amount,
    bool_or(website_card_visible) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    ) as website_card_visible
  from normalized
)
select case
  when component_count>1 then jsonb_build_object('status','blocked','code','invoice_fee_ambiguous')
  when valid_component_count<>1 then jsonb_build_object('status','blocked','code','invoice_fee_missing')
  when p_row_amount is null or p_row_amount<0 or p_row_amount<>amount then
    jsonb_build_object(
      'status','blocked','code','invoice_fee_conflict','amount',amount,
      'unit','sek_invoice','calculation_type','per_invoice',
      'website_card_visible',coalesce(website_card_visible,true),
      'source','price_plan_version'
    )
  else jsonb_build_object(
    'status','ready','amount',amount,'unit','sek_invoice',
    'calculation_type','per_invoice',
    'website_card_visible',coalesce(website_card_visible,true),
    'source','price_plan_version'
  )
end
from scored;
$$;

--
-- Name: FUNCTION gridex_invoice_fee_readiness(p_snapshot jsonb, p_row_amount numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_invoice_fee_readiness(p_snapshot jsonb, p_row_amount numeric) IS 'Canonical invoice fee assertion. Zero is valid; null is missing. Presentation visibility never controls quote, contract or invoice calculation.';

--
-- Name: gridex_invoice_fee_ready_v1(numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invoice_fee_ready_v1(p_row_amount numeric, p_snapshot jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
  with components as (
    select component.value
    from jsonb_array_elements(
      case
        when jsonb_typeof(p_snapshot->'price_components')='array'
          then p_snapshot->'price_components'
        when jsonb_typeof(p_snapshot->'price_components_snapshot')='array'
          then p_snapshot->'price_components_snapshot'
        else '[]'::jsonb
      end
    ) component(value)
    where coalesce(nullif(component.value->>'component_code',''),
      nullif(component.value->>'component_type',''),
      nullif(component.value->'metadata'->>'component_code',''))='invoice_fee'
      and coalesce(nullif(component.value->>'status',''),'active')='active'
  ), canonical as (
    select (value->>'amount')::numeric amount
    from components
    where value->>'unit'='sek_invoice'
      and value->>'calculation_type'='per_invoice'
      and coalesce(value->>'amount','') ~ '^-?[0-9]+([.][0-9]+)?$'
      and (value->>'amount')::numeric>=0
  )
  select p_row_amount is not null
    and (select count(*) from components)=1
    and (select count(*) from canonical)=1
    and abs(p_row_amount-(select amount from canonical))<=0.000000001
$_$;

--
-- Name: gridex_invoice_fee_snapshot_candidate(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invoice_fee_snapshot_candidate(p_snapshot jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with selected_snapshot as (
  select case
    when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components')='array'
      or jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components_snapshot')='array'
      then coalesce(p_snapshot,'{}'::jsonb)
    when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'pricing_snapshot')='object'
      then coalesce(p_snapshot,'{}'::jsonb)->'pricing_snapshot'
    else '{}'::jsonb
  end snapshot
), components as (
  select component
  from selected_snapshot,
  lateral jsonb_array_elements(
    case
      when jsonb_typeof(snapshot->'price_components')='array' then snapshot->'price_components'
      when jsonb_typeof(snapshot->'price_components_snapshot')='array' then snapshot->'price_components_snapshot'
      else '[]'::jsonb
    end
  ) component
  where coalesce(
    nullif(component->>'component_code',''),
    nullif(component->>'component_type',''),
    nullif(component#>>'{metadata,component_code}','')
  )='invoice_fee'
  and coalesce(nullif(component->>'status',''),'active')='active'
), normalized as (
  select
    public.gridex_safe_nonnegative_numeric(component->>'amount') amount,
    component->>'unit' unit,
    component->>'calculation_type' calculation_type,
    case
      when lower(coalesce(component->>'website_card_visible','')) in('true','false')
        then (component->>'website_card_visible')::boolean
      when lower(coalesce(component#>>'{metadata,visibility,website_card}','')) in('true','false')
        then (component#>>'{metadata,visibility,website_card}')::boolean
      else false
    end website_card_visible
  from components
), scored as (
  select
    count(*)::integer component_count,
    count(*) filter(where unit='sek_invoice' and calculation_type='per_invoice' and amount is not null)::integer valid_count,
    min(amount) filter(where unit='sek_invoice' and calculation_type='per_invoice' and amount is not null) amount,
    bool_or(website_card_visible) filter(where unit='sek_invoice' and calculation_type='per_invoice' and amount is not null) website_card_visible
  from normalized
)
select case
  when component_count>1 then jsonb_build_object('status','blocked','code','invoice_fee_ambiguous')
  when valid_count<>1 then jsonb_build_object('status','blocked','code','invoice_fee_missing')
  else jsonb_build_object(
    'status','ready','amount',amount,'unit','sek_invoice','calculation_type','per_invoice',
    'website_card_visible',coalesce(website_card_visible,false)
  )
end
from scored;
$$;

--
-- Name: gridex_invoice_fee_snapshot_readiness(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_invoice_fee_snapshot_readiness(p_snapshot jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with raw_components as (
  select component
  from jsonb_array_elements(
    case
      when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components')='array'
        then coalesce(p_snapshot,'{}'::jsonb)->'price_components'
      when jsonb_typeof(coalesce(p_snapshot,'{}'::jsonb)->'price_components_snapshot')='array'
        then coalesce(p_snapshot,'{}'::jsonb)->'price_components_snapshot'
      else '[]'::jsonb
    end
  ) component
  where coalesce(
    nullif(component->>'component_code',''),
    nullif(component->>'component_type',''),
    nullif(component#>>'{metadata,component_code}','')
  )='invoice_fee'
  and coalesce(nullif(component->>'status',''),'active')='active'
), normalized as (
  select
    component,
    public.gridex_safe_nonnegative_numeric(component->>'amount') as amount,
    component->>'unit' as unit,
    component->>'calculation_type' as calculation_type,
    case
      when lower(coalesce(component->>'website_card_visible','')) in('true','false')
        then (component->>'website_card_visible')::boolean
      when lower(coalesce(component#>>'{metadata,visibility,website_card}','')) in('true','false')
        then (component#>>'{metadata,visibility,website_card}')::boolean
      else true
    end as website_card_visible
  from raw_components
), scored as (
  select
    count(*)::integer as component_count,
    count(*) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    )::integer as valid_component_count,
    min(amount) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    ) as amount,
    bool_or(website_card_visible) filter(
      where unit='sek_invoice'
        and calculation_type='per_invoice'
        and amount is not null
    ) as website_card_visible
  from normalized
)
select case
  when component_count>1 then jsonb_build_object('status','blocked','code','invoice_fee_ambiguous')
  when valid_component_count<>1 then jsonb_build_object('status','blocked','code','invoice_fee_missing')
  else jsonb_build_object(
    'status','ready','amount',amount,'unit','sek_invoice',
    'calculation_type','per_invoice',
    'website_card_visible',coalesce(website_card_visible,true),
    'source','price_plan_version'
  )
end
from scored;
$$;

--
-- Name: FUNCTION gridex_invoice_fee_snapshot_readiness(p_snapshot jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_invoice_fee_snapshot_readiness(p_snapshot jsonb) IS 'Validates canonical invoice_fee configuration without requiring website-only public_contract_offers materialization.';

--
-- Name: gridex_is_current_session_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_is_current_session_allowed() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_disabled_at timestamptz;
begin
  if v_user_id is null then
    return false;
  end if;
  if to_regclass('public.user_profiles') is null then
    return true;
  end if;
  if exists(
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'user_profiles'
      and column_name = 'disabled_at'
  ) then
    execute
      'select profile.user_status,profile.disabled_at
       from public.user_profiles profile where profile.id=$1'
    into v_status, v_disabled_at
    using v_user_id;
  else
    select profile.user_status
    into v_status
    from public.user_profiles profile
    where profile.id = v_user_id;
  end if;
  if coalesce(v_status, 'active') in (
    'disabled',
    'locked_security',
    'removed_from_company',
    'invitation_revoked'
  ) then
    return false;
  end if;
  return v_disabled_at is null;
end
$_$;

--
-- Name: FUNCTION gridex_is_current_session_allowed(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_is_current_session_allowed() IS 'Tenant session guard with schema-aware disabled_at handling and no invalid intermediate function definition.';

--
-- Name: gridex_json_text(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_json_text(p_payload jsonb, VARIADIC p_keys text[]) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(trim(p_payload ->> k), '');
    if v is not null then
      return v;
    end if;
  end loop;
  return null;
end;
$$;

--
-- Name: gridex_jsonb_has_text(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_jsonb_has_text(p_value jsonb, p_path text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select length(btrim(coalesce(p_value #>> p_path, ''))) > 0
$$;

--
-- Name: gridex_jsonb_nonblank(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_jsonb_nonblank(p_value jsonb, p_keys text[] DEFAULT ARRAY['text'::text]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_key text; v_text text;
begin
  if p_value is null or p_value='{}'::jsonb or p_value='null'::jsonb then return false; end if;
  if jsonb_typeof(p_value)='string' then return nullif(btrim(p_value#>>'{}'),'') is not null; end if;
  foreach v_key in array coalesce(p_keys,'{}') loop
    v_text:=nullif(btrim(coalesce(p_value->>v_key,'')),'');
    if v_text is not null then return true; end if;
  end loop;
  return false;
end $$;

--
-- Name: gridex_jsonb_to_text_array(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_jsonb_to_text_array(value jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select coalesce(array_agg(item), '{}'::text[])
  from jsonb_array_elements_text(
    case
      when value is null then '[]'::jsonb
      when jsonb_typeof(value) = 'array' then value
      when jsonb_typeof(value) = 'string' then jsonb_build_array(value #>> '{}')
      else '[]'::jsonb
    end
  ) as x(item)
$$;

--
-- Name: gridex_jsonb_valid_email(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_jsonb_valid_email(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select coalesce(p_value->>'email','') ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
$_$;

--
-- Name: gridex_jsonb_valid_phone(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_jsonb_valid_phone(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select length(regexp_replace(coalesce(p_value->>'phone',''),'[^0-9]','','g')) >= 7
$$;

--
-- Name: gridex_legacy_internal_offer_pricing_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_legacy_internal_offer_pricing_snapshot(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_existing jsonb;
  v_components jsonb := '[]'::jsonb;
  v_base_components jsonb := '[]'::jsonb;
  v_retained jsonb := '[]'::jsonb;
  v_visibility jsonb;
  v_price_areas jsonb;
  v_pricing_model text;
  v_interval_resolution text;
  v_code text;
  v_component jsonb;
begin
  select * into o
  from public.contract_offers
  where id=p_offer_id;

  if not found then
    raise exception using errcode='P0002',message='internal_contract_offer_not_found';
  end if;

  v_existing := case
    when jsonb_typeof(o.commercial_snapshot)='object' and o.commercial_snapshot<>'{}'::jsonb
      then o.commercial_snapshot
    when jsonb_typeof(o.version_snapshot->'pricing_snapshot')='object'
      then o.version_snapshot->'pricing_snapshot'
    else '{}'::jsonb
  end;

  v_visibility := coalesce(v_existing->'website_visibility','{}'::jsonb);
  v_price_areas := case
    when jsonb_typeof(v_existing->'price_areas')='array' then v_existing->'price_areas'
    when jsonb_typeof(o.version_snapshot#>'{pricing,priceAreas}')='array' then o.version_snapshot#>'{pricing,priceAreas}'
    else '[]'::jsonb
  end;

  v_pricing_model := case
    when o.contract_type='fixed' then 'fixed'
    when o.contract_type='portfolio' then 'portfolio'
    when o.contract_type='mixed' then 'mixed'
    else 'spot'
  end;

  v_interval_resolution := case
    when o.contract_type='variable_hourly' then 'hourly'
    when o.contract_type='variable_quarterly' then 'quarterly'
    when o.contract_type='fixed' then 'fixed'
    when o.contract_type='portfolio' then 'portfolio'
    else 'monthly'
  end;

  if jsonb_typeof(v_existing->'base_components')='array'
     and jsonb_array_length(v_existing->'base_components')>0 then
    v_base_components:=v_existing->'base_components';
  elsif o.contract_type='fixed' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source_type','fixed','label','Fast pris','weight_percent',100,
      'fixed_price_sek_per_kwh',case when o.fixed_price_ore_per_kwh is null then null else o.fixed_price_ore_per_kwh/100 end,
      'price_area',area
    ))),'[]'::jsonb)
    into v_base_components
    from (
      select value as area from jsonb_array_elements_text(v_price_areas)
      union all
      select null where jsonb_array_length(v_price_areas)=0
    ) areas;
  else
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source_type','spot','label','Spotpris','weight_percent',100,
      'fixed_price_sek_per_kwh',null,'price_area',area
    ))),'[]'::jsonb)
    into v_base_components
    from (
      select value as area from jsonb_array_elements_text(v_price_areas)
      union all
      select null where jsonb_array_length(v_price_areas)=0
    ) areas;
  end if;

  -- Preserve unknown/extension components, but replace all compatibility
  -- components from the row with one canonical representation.
  if jsonb_typeof(v_existing->'price_components')='array' then
    select coalesce(jsonb_agg(component order by ordinal),'[]'::jsonb)
      into v_retained
    from jsonb_array_elements(v_existing->'price_components') with ordinality rows(component,ordinal)
    where coalesce(
      nullif(component->>'component_code',''),
      nullif(component->>'component_type',''),
      nullif(component#>>'{metadata,component_code}','')
    ) not in(
      'monthly_fee','invoice_fee','spot_markup','variable_fee','green_energy_fee',
      'start_fee','administration_fee','admin_fee','break_fee'
    );
  end if;

  v_components := v_retained;

  if o.monthly_fee_sek is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','monthly_fee','component_type','monthly_fee','name','Månadsavgift',
      'amount',o.monthly_fee_sek,'calculation_type','per_month','unit','sek_month',
      'priority',100,'status','active',
      'website_card_visible',coalesce((v_visibility->>'monthly_fee')::boolean,true),
      'metadata',jsonb_build_object('lifecycle','per_month')
    ));
  end if;

  if o.invoice_fee_sek is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','invoice_fee','component_type','invoice_fee','name','Fakturaavgift',
      'amount',o.invoice_fee_sek,'calculation_type','per_invoice','unit','sek_invoice',
      'priority',110,'status','active',
      'website_card_visible',coalesce((v_visibility->>'invoice_fee')::boolean,false),
      'metadata',jsonb_build_object(
        'lifecycle','per_invoice',
        'visibility',jsonb_build_object(
          'website_card',coalesce((v_visibility->>'invoice_fee')::boolean,false),
          'quote_breakdown',true,'checkout',true,'contract_document',true,'invoice',true
        )
      )
    ));
  end if;

  if o.spot_markup_ore_per_kwh is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','spot_markup','component_type','spot_markup','name','Spotpåslag',
      'amount',o.spot_markup_ore_per_kwh,'calculation_type','per_kwh','unit','ore_per_kwh',
      'priority',130,'status','active',
      'website_card_visible',coalesce((v_visibility->>'spot_markup')::boolean,true),
      'metadata',jsonb_build_object('replaces_legacy_markup',true)
    ));
  end if;

  if o.variable_fee_ore_per_kwh is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','variable_fee','component_type','variable_fee','name','Rörlig avgift',
      'amount',o.variable_fee_ore_per_kwh,'calculation_type','per_kwh','unit','ore_per_kwh',
      'priority',140,'status','active',
      'website_card_visible',coalesce((v_visibility->>'variable_fee')::boolean,true),
      'metadata','{}'::jsonb
    ));
  end if;

  if o.green_fee_value is not null and coalesce(o.green_fee_mode,'none')<>'none' then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','green_energy_fee','component_type','green_energy_fee','name','Grön el-avgift',
      'amount',o.green_fee_value,
      'calculation_type',case when o.green_fee_mode='sek_month' then 'per_month' else 'per_kwh' end,
      'unit',case when o.green_fee_mode='sek_month' then 'sek_month' else 'ore_per_kwh' end,
      'priority',150,'status','active',
      'website_card_visible',coalesce((v_visibility->>'green_energy_fee')::boolean,true),
      'metadata','{}'::jsonb
    ));
  end if;

  if o.start_fee_sek is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','start_fee','component_type','start_fee','name','Startavgift',
      'amount',o.start_fee_sek,'calculation_type','fixed_once','unit','sek_once',
      'priority',200,'status','active','website_card_visible',false,'metadata','{}'::jsonb
    ));
  end if;

  if o.admin_fee_sek is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','administration_fee','component_type','administration_fee','name','Administrationsavgift',
      'amount',o.admin_fee_sek,'calculation_type','per_month','unit','sek_month',
      'priority',210,'status','active','website_card_visible',false,'metadata','{}'::jsonb
    ));
  end if;

  if o.break_fee_sek is not null then
    v_components := v_components || jsonb_build_array(jsonb_build_object(
      'component_code','break_fee','component_type','break_fee','name','Brytavgift',
      'amount',o.break_fee_sek,'calculation_type','fixed_once','unit','sek_once',
      'priority',220,'status','active','website_card_visible',false,'metadata','{}'::jsonb
    ));
  end if;

  return jsonb_strip_nulls(
    v_existing || jsonb_build_object(
      'schema_version',5,
      'contract_type',o.contract_type,
      'customer_type',o.customer_type,
      'pricing_model',v_pricing_model,
      'price_areas',v_price_areas,
      'valid_from',o.valid_from,
      'valid_to',o.valid_to,
      'binding_months',o.default_binding_months,
      'notice_months',o.default_notice_months,
      'automatic_renewal',coalesce(o.automatic_renewal,false),
      'power_of_attorney_required',coalesce(o.power_of_attorney_required,true),
      'base_components',v_base_components,
      'price_components',v_components,
      'website_visibility',v_visibility || jsonb_build_object(
        'invoice_fee',coalesce((v_visibility->>'invoice_fee')::boolean,false)
      ),
      'vat_rate',case when coalesce(o.vat_rate,0.25)>1 then o.vat_rate/100 else coalesce(o.vat_rate,0.25) end,
      'vat_rate_percent',case when coalesce(o.vat_rate,0.25)>1 then o.vat_rate else coalesce(o.vat_rate,0.25)*100 end,
      'interval_resolution',v_interval_resolution,
      'legacy_source',jsonb_build_object(
        'table','contract_offers','offer_id',o.id,'completed_at',now()
      )
    )
  );
end $$;

--
-- Name: FUNCTION gridex_legacy_internal_offer_pricing_snapshot(p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_legacy_internal_offer_pricing_snapshot(p_offer_id uuid) IS 'Builds a full schema-v5 pricing snapshot from an unreferenced legacy internal offer. It preserves unknown extension components and treats invoice fee zero as a real value.';

--
-- Name: gridex_legacy_legal_type_for_module(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_legacy_legal_type_for_module(p_module text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
select case
  when p_module in ('privacy_policy') then 'privacy_policy'
  when p_module in ('withdrawal_right','withdrawal_form','pre_contract_information') then 'withdrawal'
  when p_module in ('power_of_attorney') then 'power_of_attorney'
  when p_module in ('price_terms','variable_price_terms','hourly_price_terms','quarterly_price_terms','fixed_price_terms','portfolio_terms','mixed_price_terms') then 'price_terms'
  else 'terms' end
$$;

--
-- Name: gridex_legal_contact_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_legal_contact_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gridex_jsonb_valid_email(coalesce(p_value,'{}'::jsonb))
      or public.gridex_jsonb_valid_phone(coalesce(p_value,'{}'::jsonb))
      or public.gridex_address_complete(public.gridex_contact_address(coalesce(p_value,'{}'::jsonb)))
$$;

--
-- Name: gridex_legal_missing_field_details(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_legal_missing_field_details(p_company_id uuid, p_fields text[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'code', code,
    'label', case code
      when 'legal_name' then 'Juridiskt bolagsnamn'
      when 'organization_number' then 'Organisationsnummer'
      when 'postal_address' then 'Postadress'
      when 'customer_service_email' then 'Kundservice'
      when 'phone' then 'Telefon'
      when 'website' then 'Webbplats'
      when 'complaints_contact' then 'Klagomålskontakt'
      when 'data_protection_contact' then 'Dataskyddskontakt'
      when 'billing_information' then 'Faktureringskontakt'
      when 'dispute_resolution_information' then 'Tvistlösning'
      else replace(code, '_', ' ') end,
    'message', case code
      when 'organization_number' then 'Fyll i ett giltigt svenskt organisationsnummer med korrekt kontrollsiffra.'
      when 'postal_address' then 'Fyll i gatuadress, postnummer, ort och land under Postadress.'
      when 'complaints_contact' then 'Fyll i minst e-post, telefon eller komplett postadress under Klagomål.'
      when 'data_protection_contact' then 'Fyll i minst e-post, telefon eller komplett postadress under Dataskydd.'
      when 'billing_information' then 'Fyll i minst e-post, telefon eller komplett faktureringsadress under Fakturering.'
      else 'Komplettera uppgiften under Redigera bolagsuppgifter.' end,
    'edit_section', case code
      when 'postal_address' then 'company_address'
      when 'complaints_contact' then 'company_complaints'
      when 'data_protection_contact' then 'company_data_protection'
      when 'billing_information' then 'company_billing'
      else 'company_profile' end
  ) order by ordinality), '[]'::jsonb)
  from unnest(coalesce(p_fields, '{}'::text[])) with ordinality as f(code, ordinality)
$$;

--
-- Name: gridex_legal_text_versions_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_legal_text_versions_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at := now();
  if new.status = 'published' and new.published_at is null then
    new.published_at := now();
  end if;
  return new;
end $$;

--
-- Name: gridex_list_customer_operation_events(uuid, text, text, text, boolean, timestamp with time zone, timestamp with time zone, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_list_customer_operation_events(p_company_id uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_event_group text DEFAULT NULL::text, p_action_required boolean DEFAULT NULL::boolean, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, company_id uuid, customer_id uuid, customer_site_id uuid, metering_point_id uuid, customer_operation_job_id uuid, operation_id uuid, event_code text, title text, message text, status text, severity text, action_required boolean, action_url text, source text, occurred_at timestamp with time zone, customer_name text, customer_number text, customer_email text, site_name text, site_address text, facility_id text, metering_point_reference text, grid_owner_name text, job_type text, job_status text, payload jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    event.id,
    event.company_id,
    event.customer_id,
    event.customer_site_id,
    event.metering_point_id,
    event.customer_operation_job_id,
    event.operation_id,
    event.event_code,
    event.title,
    event.message,
    event.status,
    event.severity,
    event.action_required,
    event.action_url,
    event.source,
    event.occurred_at,
    coalesce(nullif(customer.company_name, ''), nullif(customer.full_name, ''), nullif(trim(concat_ws(' ', customer.first_name, customer.last_name)), ''), customer.email, 'Kund utan namn') as customer_name,
    customer.customer_number,
    customer.email as customer_email,
    site.site_name,
    nullif(trim(concat_ws(', ', nullif(site.street, ''), nullif(trim(concat_ws(' ', site.postal_code, site.city)), ''))), '') as site_address,
    site.facility_id,
    meter.meter_point_id as metering_point_reference,
    grid_owner.name as grid_owner_name,
    job.job_type,
    job.status as job_status,
    event.payload
  from public.customer_operation_events event
  join public.customers customer
    on customer.id = event.customer_id and customer.company_id = event.company_id
  left join public.customer_sites site
    on site.id = event.customer_site_id and site.company_id = event.company_id
  left join public.metering_points meter
    on meter.id = event.metering_point_id and meter.company_id = event.company_id
  left join public.grid_owners grid_owner
    on grid_owner.id = coalesce(meter.grid_owner_id, site.grid_owner_id)
  left join public.customer_operation_jobs job
    on job.id = event.customer_operation_job_id and job.company_id = event.company_id
  where event.company_id = p_company_id
    and (
      nullif(trim(p_search), '') is null
      or lower(concat_ws(' ',
        customer.customer_number,
        customer.company_name,
        customer.full_name,
        customer.first_name,
        customer.last_name,
        customer.email,
        site.site_name,
        site.street,
        site.postal_code,
        site.city,
        site.facility_id,
        meter.meter_point_id,
        grid_owner.name,
        event.operation_id::text,
        event.payload::text
      )) like '%' || lower(trim(p_search)) || '%'
    )
    and (p_status is null or event.status = p_status)
    and (p_event_group is null or split_part(event.event_code, '.', 1) = p_event_group)
    and (p_action_required is null or event.action_required = p_action_required)
    and (p_date_from is null or event.occurred_at >= p_date_from)
    and (p_date_to is null or event.occurred_at < p_date_to)
    and (
      p_cursor is null
      or event.occurred_at < p_cursor
      or (event.occurred_at = p_cursor and p_cursor_id is not null and event.id < p_cursor_id)
    )
  order by event.occurred_at desc, event.id desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;

--
-- Name: gridex_list_external_api_contracts(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_list_external_api_contracts(p_company_id uuid, p_customer_type text DEFAULT NULL::text) RETURNS TABLE(data jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'offer_reference',pv.offer_reference,
    'name',coalesce(pv.publication_snapshot->'commercial_snapshot'->>'name',
      pv.publication_snapshot->'commercial_snapshot'->>'public_name','Elavtal'),
    'description',coalesce(
      pv.publication_snapshot->'commercial_snapshot'->>'description',
      pv.publication_snapshot->'commercial_snapshot'->>'public_description'),
    'contract_type',coalesce(
      pv.publication_snapshot->'commercial_snapshot'->>'contract_type',
      product_version.contract_type),
    'energy_direction',coalesce(nullif(pv.energy_direction,''),
      nullif(product_version.energy_direction,''),'consumption'),
    'customer_type',pv.customer_type,
    'price_options',coalesce(pv.publication_snapshot->'price_options','[]'::jsonb),
    'pricing',coalesce(
      pv.publication_snapshot->'commercial_snapshot'->'pricing',
      pv.publication_snapshot->'commercial_snapshot','{}'::jsonb),
    'legal',public.gridex_publication_legal_snapshot_json_v1(
      assignment.company_id,pv.legal_bundle_version_id
    ),
    'valid_from',pv.valid_from,'valid_to',pv.valid_to,'channel','api'
  )
  from public.contract_publication_versions pv
  join public.contract_publications publication
    on publication.id=pv.contract_publication_id
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  join public.tenant_contract_channels channel_row
    on channel_row.assignment_id=assignment.id and channel_row.channel='api'
  join public.contract_product_versions product_version
    on product_version.id=pv.contract_product_version_id
  join public.companies company on company.id=assignment.company_id
  where assignment.company_id=p_company_id and company.status='active'
    and nullif(btrim(company.external_tenant_reference),'') is not null
    and assignment.status='active' and assignment.api_publication_allowed
    and publication.channel='api' and publication.status='published'
    and pv.channel='api' and pv.status='published' and pv.locked_at is not null
    and pv.legal_bundle_version_id is not null
    and public.gridex_publication_legal_snapshot_json_v1(
      assignment.company_id,pv.legal_bundle_version_id
    ) is not null
    and pv.content_sha256=encode(
      extensions.digest(pv.publication_snapshot::text,'sha256'),'hex')
    and jsonb_array_length(coalesce(
      pv.publication_snapshot->'price_options','[]'::jsonb))>0
    and channel_row.status='active'
    and (assignment.valid_from is null or assignment.valid_from<=
      (now() at time zone 'Europe/Stockholm')::date)
    and (assignment.valid_to is null or assignment.valid_to>=
      (now() at time zone 'Europe/Stockholm')::date)
    and (channel_row.valid_from is null or channel_row.valid_from<=now())
    and (channel_row.valid_to is null or channel_row.valid_to>now())
    and (pv.valid_from is null or pv.valid_from<=now())
    and (pv.valid_to is null or pv.valid_to>now())
    and (p_customer_type is null or pv.customer_type='both'
      or pv.customer_type=p_customer_type)
    and exists(
      select 1 from public.canonical_public_contract_diagnostics_v diagnostic
      where diagnostic.publication_version_id=pv.id
        and diagnostic.channel='api' and diagnostic.visible
        and diagnostic.snapshot_source_contract_offer_id=
          diagnostic.source_contract_offer_id::text
    )
  order by pv.published_at desc nulls last,pv.created_at desc
$$;

