-- Name: FUNCTION gridex_list_external_api_contracts(p_company_id uuid, p_customer_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_list_external_api_contracts(p_company_id uuid, p_customer_type text) IS 'Tenant-scoped external feed for contracts published to the api channel.';

--
-- Name: gridex_list_readable_whitelabel_platforms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_list_readable_whitelabel_platforms() RETURNS TABLE(id uuid, name text, slug text, status text, membership_role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  return query
  select p.id, p.name, p.slug, p.status,
         coalesce(m.membership_role, case when public.gridex_user_is_platform_admin() then 'platform_admin' end)
  from public.white_label_platforms p
  left join public.white_label_platform_memberships m
    on m.white_label_platform_id = p.id and m.user_id = auth.uid() and m.status = 'active'
  where public.gridex_user_can_read_whitelabel_platform(p.id)
  order by p.name;
end;
$$;

--
-- Name: gridex_lock_commercial_child(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_commercial_child() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_price_plan_version_id uuid:=old.price_plan_version_id;
  v_old_projection jsonb;
  v_new_projection jsonb;
  v_repair boolean:=coalesce(
    current_setting('gridex.publication_graph_repair',true),'')='on';
begin
  if not exists(
    select 1 from public.price_plan_versions version_row
    where version_row.id=v_price_plan_version_id
      and version_row.locked_at is not null
  ) then
    return case when tg_op='DELETE' then old else new end;
  end if;

  if tg_op='DELETE' or tg_table_name<>'contract_price_options' then
    raise exception using errcode='55000',
      message='locked_commercial_pricing_is_immutable';
  end if;

  v_old_projection:=to_jsonb(old)-array[
    'contract_publication_version_id','customer_type',
    'is_default','selection_required'
  ]::text[];
  v_new_projection:=to_jsonb(new)-array[
    'contract_publication_version_id','customer_type',
    'is_default','selection_required'
  ]::text[];

  if v_old_projection is distinct from v_new_projection then
    raise exception using errcode='55000',
      message='locked_commercial_pricing_is_immutable';
  end if;
  if not (
    old.contract_publication_version_id is not distinct from
      new.contract_publication_version_id
    or (
      v_repair
      and old.contract_publication_version_id is null
      and new.contract_publication_version_id is not null
      and (
        current_user in ('postgres','supabase_admin','service_role')
        or pg_has_role(current_user,'service_role','member')
      )
    )
  ) then
    raise exception using errcode='55000',
      message='locked_commercial_pricing_is_immutable';
  end if;
  if not (
    old.customer_type is not distinct from new.customer_type
    or (old.customer_type is null and new.customer_type is not null)
  ) or not (
    old.is_default is not distinct from new.is_default
    or (old.is_default is null and new.is_default is not null)
  ) or not (
    old.selection_required is not distinct from new.selection_required
    or (old.selection_required is null and new.selection_required is not null)
  ) then
    raise exception using errcode='55000',
      message='locked_commercial_pricing_is_immutable';
  end if;
  return new;
end $$;

--
-- Name: gridex_lock_customer_contract_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_customer_contract_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    raise exception using errcode='55000',message='customer_contract_document_immutable';
  end if;
  if old.storage_path is not null and (
    new.company_id is distinct from old.company_id
    or new.customer_contract_id is distinct from old.customer_contract_id
    or new.document_type is distinct from old.document_type
    or new.storage_bucket is distinct from old.storage_bucket
    or new.storage_path is distinct from old.storage_path
    or new.mime_type is distinct from old.mime_type
    or new.document_sha256 is distinct from old.document_sha256
    or new.generation_snapshot is distinct from old.generation_snapshot
  ) then
    raise exception using errcode='55000',message='customer_contract_document_immutable';
  end if;
  return new;
end $$;

--
-- Name: gridex_lock_customer_contract_tenant_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_customer_contract_tenant_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_profile jsonb; v_company jsonb; v_email jsonb; v_snapshot jsonb;
begin
  if tg_op='UPDATE' and (old.signed_at is not null or old.locked_at is not null or old.status in('signed','active','terminated','cancelled','expired'))
     and old.tenant_communication_snapshot<>'{}'::jsonb then
    new.tenant_communication_snapshot:=old.tenant_communication_snapshot;
    new.tenant_communication_snapshot_sha256:=old.tenant_communication_snapshot_sha256;
    new.tenant_legal_party_snapshot:=old.tenant_legal_party_snapshot;
    return new;
  end if;
  if new.company_id is null then return new; end if;
  select to_jsonb(t) into v_profile from public.tenant_legal_profiles t where t.company_id=new.company_id;
  select to_jsonb(c) into v_company from public.companies c where c.id=new.company_id;
  select to_jsonb(e) into v_email from public.company_email_settings e where e.company_id=new.company_id;
  new.tenant_legal_party_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'postal_address',v_profile->'postal_address','customer_service_email',v_profile->>'customer_service_email',
    'phone',v_profile->>'phone','website',v_profile->>'website','tenant_legal_profile_sha256',encode(digest(coalesce(v_profile,'{}')::text,'sha256'),'hex')
  ));
  v_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'snapshot_version','gridex_tenant_communication_v1',
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'brand_name',coalesce(v_company#>>'{branding,brand_name}',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_name',coalesce(v_email->>'sender_name',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_email',v_email->>'sender_email','reply_to',coalesce(v_email->>'reply_to_email',v_email->>'support_email',v_profile->>'customer_service_email'),
    'support_email',coalesce(v_email->>'support_email',v_profile->>'customer_service_email'),
    'logo_url',coalesce(v_company#>>'{branding,logo_url}',v_company->>'logo_url'),
    'brand_colors',coalesce(v_company#>'{branding,colors}','{}'::jsonb),
    'legal_footer',coalesce(v_company#>>'{branding,legal_footer}',v_email->>'legal_footer'),
    'phone',coalesce(v_profile->>'phone',v_company->>'phone'),
    'website',coalesce(v_profile->>'website',v_company->>'website'),
    'contract_publication_version_id',new.contract_publication_version_id,
    'price_plan_version_id',new.price_plan_version_id,'legal_bundle_version_id',new.legal_bundle_version_id,
    'locked_at',coalesce(new.signed_at,new.created_at,now())
  ));
  new.tenant_communication_snapshot:=v_snapshot;
  new.tenant_communication_snapshot_sha256:=encode(digest(v_snapshot::text,'sha256'),'hex');
  return new;
end $$;

--
-- Name: gridex_lock_pricing_run(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_pricing_run(p_company_id uuid, p_pricing_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_run public.pricing_runs%rowtype;
  v_underlay public.billing_underlays%rowtype;
  v_month text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_pricing_run_id::text,0));
  select * into v_run from public.pricing_runs where id=p_pricing_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_run_not_found_for_tenant'; end if;
  if v_run.status not in ('success','locked') then raise exception using errcode='23514',message='only_successful_pricing_run_can_be_locked'; end if;
  select * into v_underlay from public.billing_underlays where id=v_run.billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_underlay_not_found'; end if;
  v_month:=to_char(v_run.billing_period_start at time zone 'Europe/Stockholm','YYYY-MM');
  if v_run.status='locked' then
    return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
  end if;

  insert into public.price_period_locks(company_id,billing_month,lock_scope,status,locked_by,locked_at)
  values(p_company_id,v_month,'pricing_preview','locked',p_actor_user_id,now())
  on conflict(company_id,billing_month,lock_scope) do update set status='locked',locked_by=excluded.locked_by,locked_at=excluded.locked_at;

  insert into public.contract_charge_ledger(
    company_id,customer_contract_id,component_key,event_key,pricing_run_id,amount_ex_vat,metadata
  )
  select p_company_id,v_underlay.contract_id,
    coalesce(nullif(l.metadata->>'component_key',''),l.line_type||':'||encode(digest(lower(l.description),'sha256'),'hex')),
    case
      when coalesce(l.metadata->>'lifecycle','')='event_only' then coalesce(nullif(l.metadata->>'billing_event_id',''),nullif(l.metadata->>'event',''),'event')
      else 'contract'
    end,v_run.id,l.amount_ex_vat,l.metadata
  from public.pricing_preview_lines l
  where l.pricing_run_id=v_run.id
    and coalesce(l.metadata->>'lifecycle','') in ('once_per_contract','one_time','event_only')
  on conflict(customer_contract_id,component_key,event_key) do nothing;

  update public.pricing_runs set status='locked',locked_at=now() where id=v_run.id;
  update public.billing_underlays set readiness_status='ready',updated_at=now()
  where id=v_underlay.id and company_id=p_company_id;
  return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
end
$$;

--
-- Name: gridex_lock_signed_customer_contract(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_signed_customer_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_old jsonb := to_jsonb(old);
  v_new jsonb := to_jsonb(new);
  v_immutable_keys text[] := array[
    'company_id','customer_id','contract_name','contract_type',
    'energy_direction','site_id','customer_site_id','metering_point_id',
    'contract_offer_id','public_contract_offer_id','offer_reference',
    'quote_reference','contract_product_id','contract_product_version_id',
    'contract_publication_version_id','price_plan_id',
    'price_plan_version_id','price_book_id','legal_bundle_version_id',
    'contract_price_snapshot_id','commercial_snapshot','legal_snapshot',
    'legal_versions_snapshot','tenant_communication_snapshot',
    'tenant_communication_snapshot_sha256','tenant_legal_party_snapshot',
    'signature_snapshot','signature_snapshot_sha256',
    'price_snapshot','campaign_snapshot','fixed_price_ore_per_kwh',
    'spot_markup_ore_per_kwh','variable_fee_ore_per_kwh',
    'markup_ore_per_kwh','monthly_fee_sek','invoice_fee_sek',
    'discount_value','discount_unit','start_fee_sek','admin_fee_sek',
    'break_fee_sek','vat_rate','green_fee_mode','green_fee_value',
    'binding_months','notice_months','optional_fee_lines','starts_at',
    'expected_start_at','ends_at','auto_renew_enabled',
    'auto_renew_term_months','terms_version','terms_signed_version',
    'signed_version','signed_at','signed_ip_hash','signed_user_agent'
  ];
  v_key text;
begin
  if tg_op='DELETE' then
    if old.status in ('signed','active','terminated','cancelled','expired')
       or old.signed_at is not null or old.locked_at is not null then
      raise exception using errcode='55000',message='signed_customer_contract_delete_forbidden';
    end if;
    return old;
  end if;

  if old.status in ('signed','active','terminated','cancelled','expired')
     or old.signed_at is not null or old.locked_at is not null then
    foreach v_key in array v_immutable_keys loop
      if v_new->v_key is distinct from v_old->v_key then
        raise exception using errcode='55000',message='signed_customer_contract_immutable:'||v_key;
      end if;
    end loop;

    if new.document_sha256 is distinct from old.document_sha256 then
      if old.document_sha256 is not null
         or coalesce(new.document_sha256,'') !~ '^[0-9a-f]{64}$'
         or not exists(
           select 1 from public.customer_contract_documents d
           where d.company_id=old.company_id
             and d.customer_contract_id=old.id
             and d.document_type='signed_contract_pdf'
             and d.document_sha256=new.document_sha256
             and d.verified_at is not null
         ) then
        raise exception using errcode='55000',message='signed_customer_contract_document_hash_binding_invalid';
      end if;
    end if;

    new.locked_at:=coalesce(old.locked_at,old.signed_at,now());
  elsif new.signed_at is not null or new.status in ('signed','active') then
    new.locked_at:=coalesce(new.locked_at,new.signed_at,now());
  end if;
  return new;
end
$_$;

--
-- Name: gridex_lock_spot_price_month(text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lock_spot_price_month(p_provider text, p_price_area text, p_billing_month text, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_row public.spot_price_monthly_summaries%rowtype;
  v_now timestamptz:=now();
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'spot_settlement_lock_service_role_required' using errcode='42501';
  end if;
  if upper(coalesce(p_price_area,'')) not in ('SE1','SE2','SE3','SE4')
     or coalesce(p_billing_month,'') !~ '^\d{4}-\d{2}$' then
    raise exception 'invalid_spot_settlement_period' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_provider))||':'||upper(trim(p_price_area))||':'||p_billing_month,0));
  select * into v_row
  from public.spot_price_monthly_summaries s
  where s.source=lower(trim(p_provider))
    and s.price_area=upper(trim(p_price_area))
    and s.billing_month=p_billing_month
  for update;
  if not found then raise exception 'market_price_unavailable' using errcode='P0002'; end if;
  if v_row.status not in ('verified','locked') or v_row.verified_at is null
     or v_row.period_start is null or v_row.period_end is null or v_row.period_end<=v_row.period_start
     or v_row.covered_duration_minutes is null or v_row.expected_duration_minutes is null
     or v_row.covered_duration_minutes is distinct from v_row.expected_duration_minutes
     or (case
           when jsonb_typeof(v_row.quality_issues) = 'array'
             then jsonb_array_length(v_row.quality_issues)
           else 1
         end) > 0
     or nullif(btrim(v_row.source_checksum),'') is null
     or (v_row.status='locked' and (v_row.locked_at is null or v_row.locked_at<v_row.verified_at)) then
    raise exception 'market_price_incomplete' using errcode='23514';
  end if;
  if v_row.status='locked' then return to_jsonb(v_row); end if;
  update public.spot_price_monthly_summaries
  set status='locked',locked_at=v_now,locked_by=p_actor_user_id,lock_reason=nullif(btrim(p_reason),''),updated_at=v_now
  where id=v_row.id
  returning * into v_row;
  insert into public.canonical_energy_flow_events(event_type,source,payload,actor_type,actor_id)
  values('market_price.period.locked','spot_settlement_lock',jsonb_build_object(
    'summary_id',v_row.id,'provider',v_row.source,'price_area',v_row.price_area,
    'billing_month',v_row.billing_month,'source_checksum',v_row.source_checksum,
    'locked_at',v_row.locked_at,'reason',v_row.lock_reason
  ),case when p_actor_user_id is null then 'system' else 'user' end,p_actor_user_id);
  return to_jsonb(v_row);
end;
$_$;

--
-- Name: FUNCTION gridex_lock_spot_price_month(p_provider text, p_price_area text, p_billing_month text, p_actor_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_lock_spot_price_month(p_provider text, p_price_area text, p_billing_month text, p_actor_user_id uuid, p_reason text) IS 'Explicit service-role settlement lock. A locked summary is immutable and never subject to preview freshness.';

--
-- Name: gridex_lonlat_to_grid_area(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lonlat_to_grid_area(p_longitude numeric, p_latitude numeric) RETURNS TABLE(grid_area_code text, grid_area_name text, grid_owner_id uuid, grid_owner_name text, price_area text, confidence numeric, source text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with projected as (
    select extensions.ST_Transform(
      extensions.ST_SetSRID(
        extensions.ST_MakePoint(
          p_longitude::double precision,
          p_latitude::double precision
        ),
        4326
      ),
      3006
    ) as geom
  )
  select resolved.*
  from projected
  cross join lateral public.gridex_point_to_grid_area(
    extensions.ST_X(projected.geom)::numeric,
    extensions.ST_Y(projected.geom)::numeric
  ) as resolved;
$$;

--
-- Name: gridex_lookup_pending_staff_identity_binding_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_lookup_pending_staff_identity_binding_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE registration jsonb; b public.tenant_staff_identity_bindings%rowtype;
BEGIN
 registration:=public.gridex_staff_identity_registration_v1(p_command,true);
 PERFORM public.gridex_staff_identity_invitation_v1(p_command,false);
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE company_id=(p_command->>'company_id')::uuid AND api_client_id=(p_command->>'api_client_id')::uuid
  AND provider_id=(p_command->>'provider_id')::uuid AND invitation_id=(p_command->>'invitation_id')::uuid AND local_user_id=(p_command->>'local_user_id')::uuid
  AND local_auth_issuer=p_command->>'local_auth_issuer' AND local_auth_issuer=registration->>'auth_issuer' AND status IN('pending','active') FOR UPDATE;
 IF NOT FOUND OR b.provider_configuration IS DISTINCT FROM p_command->'verified_provider' THEN RAISE EXCEPTION 'staff_identity_binding_missing' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('actor_user_id',b.actor_user_id,'binding_id',b.id,'binding_version',b.version);
END $$;

--
-- Name: gridex_luhn_valid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_luhn_valid(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_digits text := regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
  v_sum integer := 0;
  v_digit integer;
begin
  if v_digits !~ '^[0-9]{10}$' then return false; end if;
  for i in 1..10 loop
    v_digit := substring(v_digits from i for 1)::integer;
    if mod(i, 2) = 1 then
      v_digit := v_digit * 2;
      if v_digit > 9 then v_digit := v_digit - 9; end if;
    end if;
    v_sum := v_sum + v_digit;
  end loop;
  return mod(v_sum, 10) = 0;
end
$_$;

--
-- Name: gridex_make_idempotency_key(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_make_idempotency_key(VARIADIC p_parts text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select encode(
    digest(
      array_to_string(
        coalesce(
          (
            select array_agg(coalesce(nullif(btrim(part_value), ''), '<null>') order by part_order)
            from unnest(p_parts) with ordinality as parts(part_value, part_order)
          ),
          array[]::text[]
        ),
        '|'
      ),
      'sha256'
    ),
    'hex'
  )
$$;

--
-- Name: gridex_make_source_hash(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_make_source_hash(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select encode(digest(coalesce(p_payload, '{}'::jsonb)::text, 'sha256'), 'hex')
$$;

--
-- Name: gridex_mark_customer_contract_signature_request_sent_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_mark_customer_contract_signature_request_sent_v1(p_request_id uuid, p_company_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update public.customer_contract_signature_requests
  set sent_at=coalesce(sent_at,now())
  where id=p_request_id and company_id=p_company_id and revoked_at is null and used_at is null;
$$;

--
-- Name: gridex_mask_identity_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_mask_identity_number(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE WHEN p_value IS NULL OR btrim(p_value) = '' THEN NULL
              ELSE '••••' || right(regexp_replace(p_value, '[^0-9]', '', 'g'), 4) END
$$;

--
-- Name: gridex_mask_sensitive_payload(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_mask_sensitive_payload(payload jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select case
    when payload is null then '{}'::jsonb
    else payload
      - 'personal_number'
      - 'personnummer'
      - 'secret'
      - 'api_key'
      - 'token'
      - 'password'
      || jsonb_build_object('masked_by_retention', true, 'masked_at', now())
  end;
$$;

--
-- Name: gridex_match_actor_registry_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_match_actor_registry_item(p_import_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.actor_registry_import_items%rowtype;
  v_matches uuid[] := '{}'::uuid[];
  v_match uuid;
  v_reason text;
  v_count int;
begin
  select * into v_item from public.actor_registry_import_items where id = p_import_item_id for update;
  if not found then
    raise exception 'actor registry import item not found';
  end if;

  if v_item.normalized_ediel_id is not null then
    select array_agg(distinct actor_id) into v_matches
    from public.platform_actor_identifiers
    where lower(identifier_type) in ('edielid','ediel_id')
      and public.gridex_normalize_actor_identifier('ediel_id', identifier_value) = v_item.normalized_ediel_id;
    v_reason := 'ediel_id';
  end if;

  if coalesce(array_length(v_matches, 1), 0) = 0 and v_item.normalized_org_no is not null then
    select array_agg(distinct id) into v_matches
    from public.platform_market_actors
    where public.gridex_normalize_actor_identifier('org_number', org_number) = v_item.normalized_org_no;
    v_reason := 'org_number';
  end if;

  if coalesce(array_length(v_matches, 1), 0) = 0 and v_item.normalized_eic is not null then
    select array_agg(distinct actor_id) into v_matches
    from public.platform_actor_identifiers
    where lower(identifier_type) in ('eic','eic_code')
      and public.gridex_normalize_actor_identifier('eic', identifier_value) = v_item.normalized_eic;
    v_reason := 'eic';
  end if;

  if coalesce(array_length(v_matches, 1), 0) = 0 and v_item.normalized_name is not null then
    select array_agg(id) into v_matches
    from public.platform_market_actors
    where normalized_name = v_item.normalized_name;
    v_reason := 'name_exact';
  end if;

  v_count := coalesce(array_length(v_matches, 1), 0);

  if v_count = 1 then
    v_match := v_matches[1];
    update public.actor_registry_import_items
    set match_status = 'matched', matched_actor_id = v_match, match_confidence = case when v_reason in ('ediel_id','org_number','eic') then 'strong' else 'weak' end,
        match_reason = v_reason, review_required = false, review_reason = null, updated_at = now()
    where id = p_import_item_id;
    return jsonb_build_object('status', 'matched', 'actor_id', v_match, 'reason', v_reason);
  elsif v_count > 1 then
    perform public.gridex_create_actor_registry_conflict(
      v_item.company_id, v_item.import_run_id, v_item.id, null, null, null,
      'duplicate_' || coalesce(v_reason, 'actor'), 'blocking', 'Dubblett i aktörsregistret',
      'Flera aktörer matchar samma starka identifierare. Systemet applicerar inte importposten automatiskt.',
      jsonb_build_object('matching_actor_ids', v_matches, 'match_reason', v_reason),
      v_item.normalized_payload,
      jsonb_build_object('function', 'gridex_match_actor_registry_item')
    );
    update public.actor_registry_import_items
    set match_status = 'conflict', review_required = true, review_reason = 'duplicate_' || coalesce(v_reason, 'actor'), updated_at = now()
    where id = p_import_item_id;
    return jsonb_build_object('status', 'conflict', 'reason', v_reason, 'matches', v_matches);
  else
    update public.actor_registry_import_items
    set match_status = 'pending', matched_actor_id = null, match_confidence = 'none', match_reason = 'no_match', updated_at = now()
    where id = p_import_item_id;
    return jsonb_build_object('status', 'no_match');
  end if;
end;
$$;

--
-- Name: gridex_materialize_company_operational_routes(uuid, text, text, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_company_operational_routes(p_company_id uuid, p_environment text DEFAULT NULL::text, p_message_family text DEFAULT NULL::text, p_grid_owner_id uuid DEFAULT NULL::uuid, p_platform_actor_route_id uuid DEFAULT NULL::uuid, p_message_code text DEFAULT NULL::text, p_dry_run boolean DEFAULT true) RETURNS TABLE(result_status text, reason_code text, company_id uuid, grid_owner_id uuid, grid_owner_name text, grid_owner_ediel_id text, platform_actor_route_id uuid, message_family text, message_code text, environment text, communication_route_id uuid, ediel_route_profile_id uuid, company_market_party_route_id uuid, repaired_outbound_count integer, repaired_customer_info_count integer, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  v_platform record;
  v_sender record;
  v_route_scope text;
  v_message_code text;
  v_env text;
  v_env_type public.ediel_environment_type;
  v_target_system text;
  v_comm_route_id uuid;
  v_route_profile_id uuid;
  v_company_party_route_id uuid;
  v_receiver_ediel_id text;
  v_receiver_subaddress text;
  v_sender_ediel_id text;
  v_sender_subaddress text;
  v_application_reference text;
  v_existing_id uuid;
  v_post record;
  v_repaired_outbound_count integer;
  v_repaired_customer_info_count integer;
  v_now timestamptz;
begin
  if p_company_id is null then
    raise exception 'p_company_id is required';
  end if;

  -- Guard: if p_grid_owner_id is provided without p_platform_actor_route_id
  -- or vice-versa (except p_grid_owner_id alone is allowed as filter), both
  -- narrow the candidate set. Wide apply requires both to be null.

  for r in
    select *
    from public.gridex_company_route_readiness_v gr
    where gr.company_id = p_company_id
      and coalesce(gr.operational_route_ready, false) = false
      and coalesce(gr.platform_route_ready, false) = true
      and gr.blocker_code = 'platform_route_exists_but_not_materialized'
      and gr.sender_settings_id is not null
      and gr.platform_actor_route_id is not null
      and gr.grid_owner_id is not null
      and nullif(gr.grid_owner_ediel_id, '') is not null
      and gr.environment in ('test', 'production')
      and (p_environment is null or gr.environment = p_environment)
      and (p_message_family is null or gr.message_family = upper(p_message_family))
      -- Single-route filters (safe: narrows to at most one candidate)
      and (p_grid_owner_id is null or gr.grid_owner_id = p_grid_owner_id)
      and (p_platform_actor_route_id is null or gr.platform_actor_route_id = p_platform_actor_route_id)
      and (p_message_code is null or coalesce(gr.message_code, '') = p_message_code or (p_message_code = 'Z01' and gr.message_code is null and upper(coalesce(gr.message_family, '')) = 'PRODAT'))
    order by gr.environment, gr.grid_owner_name, gr.message_family, gr.message_code nulls first
  loop
    v_comm_route_id := null;
    v_route_profile_id := null;
    v_company_party_route_id := null;
    v_repaired_outbound_count := 0;
    v_repaired_customer_info_count := 0;
    v_now := now();
    v_env := r.environment;
    v_message_code := nullif(r.message_code, '');
    if upper(coalesce(r.message_family, '')) = 'PRODAT' and v_message_code is null then
      v_message_code := 'Z01';
    end if;
    if upper(coalesce(r.message_family, '')) = 'UTILTS' and v_message_code = '' then
      v_message_code := null;
    end if;

    -- Route scope from central matrix
    v_route_scope := case
      when upper(coalesce(r.message_family, '')) = 'PRODAT' then
        case
          when v_message_code in ('Z03','Z04','Z05','Z06','Z09','Z10') then 'supplier_switch'
          when v_message_code in ('Z13','Z14','Z15','Z18')             then 'metering_access'
          else 'customer_masterdata'
        end
      when upper(coalesce(r.message_family, '')) = 'UTILTS' then 'meter_values'
      else 'customer_masterdata'
    end;

    if v_env = 'production' then
      v_env_type := 'production'::public.ediel_environment_type;
      v_target_system := 'production_ediel';
    elsif v_env = 'test' then
      v_env_type := 'agt_test'::public.ediel_environment_type;
      v_target_system := 'ediel';
    else
      result_status := 'skipped';
      reason_code := 'environment_not_resolved';
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := null;
      ediel_route_profile_id := null;
      company_market_party_route_id := null;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object('next_required_action', 'Välj test eller production innan materialisering.');
      return next;
      continue;
    end if;

    select * into v_platform
    from public.platform_actor_routes par
    where par.id = r.platform_actor_route_id
      and par.environment = v_env
      and par.status = 'active'
      and par.is_verified = true
    limit 1;

    if not found or nullif(coalesce(v_platform.communication_address, ''), '') is null then
      result_status := 'skipped';
      reason_code := 'platform_route_missing_or_not_verified';
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := null;
      ediel_route_profile_id := null;
      company_market_party_route_id := null;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object('next_required_action', 'Verifiera global route och kommunikationsadress.');
      return next;
      continue;
    end if;

    select * into v_sender
    from public.ediel_actor_settings eas
    where eas.id = r.sender_settings_id
      and eas.company_id = r.company_id
      and eas.environment = v_env
      and eas.is_active = true
    limit 1;

    if not found then
      result_status := 'skipped';
      reason_code := 'sender_settings_missing';
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := null;
      ediel_route_profile_id := null;
      company_market_party_route_id := null;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object('next_required_action', 'Lägg in aktiv Ediel-aktör för bolag och miljö.');
      return next;
      continue;
    end if;

    v_receiver_ediel_id := coalesce(nullif(v_platform.party_id, ''), nullif(v_platform.interchange_party_id, ''), nullif(r.grid_owner_ediel_id, ''));
    v_receiver_subaddress := nullif(v_platform.subaddress, '');
    v_sender_ediel_id := coalesce(nullif(v_sender.ediel_id, ''), nullif(v_sender.actor_ediel_id, ''));
    v_sender_subaddress := case
      when upper(coalesce(r.message_family, '')) = 'PRODAT'
        then coalesce(nullif(v_sender.sender_subaddress_prodat, ''), nullif(v_sender.sender_subaddress, ''))
      else coalesce(nullif(v_sender.sender_subaddress, ''))
    end;
    v_application_reference := coalesce(
      nullif(v_platform.application_reference, ''),
      nullif(v_sender.application_reference, ''),
      nullif(v_sender.default_application_reference, ''),
      case
        when v_route_scope = 'metering_access' then '23-DGI-PRODAT'
        when upper(coalesce(r.message_family, '')) = 'PRODAT' then '23-DDQ-PRODAT'
        when upper(coalesce(r.message_family, '')) = 'UTILTS' then '23-DDQ-UTILTS'
        else '23-DDQ-PRODAT'
      end
    );

    if v_sender_ediel_id is null or v_receiver_ediel_id is null then
      result_status := 'skipped';
      reason_code := 'ediel_identity_missing';
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := null;
      ediel_route_profile_id := null;
      company_market_party_route_id := null;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object('sender_ediel_id_present', v_sender_ediel_id is not null, 'receiver_ediel_id_present', v_receiver_ediel_id is not null);
      return next;
      continue;
    end if;

    if p_dry_run then
      result_status := 'dry_run';
      reason_code := null;
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := null;
      ediel_route_profile_id := null;
      company_market_party_route_id := null;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object(
        'communication_route', jsonb_build_object('route_type', 'ediel_partner', 'route_scope', v_route_scope, 'target_system', v_target_system, 'target_email', v_platform.communication_address, 'environment_type', v_env_type::text),
        'route_profile', jsonb_build_object('sender_ediel_id', v_sender_ediel_id, 'receiver_ediel_id', v_receiver_ediel_id, 'message_family', r.message_family, 'message_code', v_message_code, 'ack_mode', 'contrl_and_aperak'),
        'company_market_party_route', jsonb_build_object('market_party_id', v_platform.actor_id, 'platform_actor_route_id', r.platform_actor_route_id)
      );
      return next;
      continue;
    end if;

    -- ---- communication_routes ----
    select cr.id into v_existing_id
    from public.communication_routes cr
    where cr.company_id = r.company_id
      and cr.grid_owner_id = r.grid_owner_id
      and cr.route_scope = v_route_scope
      and cr.auth_config->>'platform_actor_route_id' = r.platform_actor_route_id::text
    order by cr.updated_at desc nulls last, cr.created_at desc nulls last
    limit 1;

    if v_existing_id is null then
      insert into public.communication_routes (
        company_id, route_name, is_active, route_scope, route_type, route_group,
        grid_owner_id, target_system, endpoint, target_email, auth_config,
        supported_payload_version, supported_message_families, supported_message_codes,
        environment_type, market_party_role, counterparty_ediel_id, notes, created_at, updated_at
      ) values (
        r.company_id,
        coalesce(r.grid_owner_name, 'Nätägare') || ' ' || coalesce(r.message_family, 'PRODAT') || ' ' || v_env,
        true,
        v_route_scope,
        'ediel_partner',
        'grid_owner',
        r.grid_owner_id,
        v_target_system,
        v_platform.communication_address,
        v_platform.communication_address,
        jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'platform_market_actor_id', v_platform.actor_id,
          'materialized_from', 'gridex_materialize_company_operational_routes',
          'message_family', r.message_family,
          'message_code', v_message_code,
          'environment', v_env,
          'receiver_subaddress_status', v_platform.metadata->>'subaddress_status',
          'blank_subaddress_requires_review', coalesce((v_platform.metadata->>'blank_subaddress_requires_review')::boolean, false)
        ),
        r.message_family,
        jsonb_build_array(r.message_family),
        case when v_message_code is null then '[]'::jsonb else jsonb_build_array(v_message_code) end,
        v_env_type,
        'grid_owner',
        v_receiver_ediel_id,
        'Materialiserad från verifierad aktörsregister-route.',
        v_now,
        v_now
      ) returning id into v_comm_route_id;
    else
      update public.communication_routes
      set
        route_name = coalesce(r.grid_owner_name, 'Nätägare') || ' ' || coalesce(r.message_family, 'PRODAT') || ' ' || v_env,
        is_active = true,
        route_type = 'ediel_partner',
        route_scope = v_route_scope,
        route_group = 'grid_owner',
        target_system = v_target_system,
        endpoint = v_platform.communication_address,
        target_email = v_platform.communication_address,
        auth_config = coalesce(auth_config, '{}'::jsonb) || jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'platform_market_actor_id', v_platform.actor_id,
          'materialized_from', 'gridex_materialize_company_operational_routes',
          'message_family', r.message_family,
          'message_code', v_message_code,
          'environment', v_env
        ),
        supported_payload_version = r.message_family,
        supported_message_families = jsonb_build_array(r.message_family),
        supported_message_codes = case when v_message_code is null then '[]'::jsonb else jsonb_build_array(v_message_code) end,
        environment_type = v_env_type,
        market_party_role = 'grid_owner',
        counterparty_ediel_id = v_receiver_ediel_id,
        updated_at = v_now
      where id = v_existing_id
      returning id into v_comm_route_id;
    end if;

    -- ---- ediel_route_profiles ----
    select erp.id into v_existing_id
    from public.ediel_route_profiles erp
    where erp.company_id = r.company_id
      and erp.communication_route_id = v_comm_route_id
      and erp.environment = v_env
      and coalesce(erp.metadata->>'platform_actor_route_id', '') = r.platform_actor_route_id::text
    order by erp.updated_at desc nulls last, erp.created_at desc nulls last
    limit 1;

    if v_existing_id is null then
      insert into public.ediel_route_profiles (
        company_id, communication_route_id, environment, environment_type, route_name,
        route_type, payload_format, message_standard, ack_mode, default_test_flag,
        default_timezone, sender_ediel_id, own_ediel_id, sender_sub_address,
        sender_subaddress, own_subaddress, receiver_ediel_id, counterparty_ediel_id,
        receiver_sub_address, receiver_subaddress, counterparty_subaddress,
        receiver_name, application_reference, message_family, message_code,
        default_message_version, mailbox, encryption_mode, transport_type,
        ack_policy, is_active, is_enabled, metadata, created_at, updated_at
      ) values (
        r.company_id,
        v_comm_route_id,
        v_env,
        v_env_type,
        coalesce(r.grid_owner_name, 'Nätägare') || ' ' || coalesce(r.message_family, 'PRODAT'),
        'email',
        'edifact',
        'edifact',
        'contrl_and_aperak',
        case when v_env = 'production' then 0 else 1 end,
        1,
        v_sender_ediel_id,
        v_sender_ediel_id,
        v_sender_subaddress,
        v_sender_subaddress,
        v_sender_subaddress,
        v_receiver_ediel_id,
        v_receiver_ediel_id,
        v_receiver_subaddress,
        v_receiver_subaddress,
        v_receiver_subaddress,
        r.grid_owner_name,
        v_application_reference,
        r.message_family,
        v_message_code,
        case when upper(coalesce(r.message_family, '')) = 'PRODAT' then '26A' else null end,
        null,
        case when upper(coalesce(r.message_family, '')) = 'PRODAT' then 'smime' else 'none' end,
        'smtp',
        'contrl_and_aperak',
        true,
        true,
        jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'platform_market_actor_id', v_platform.actor_id,
          'sender_settings_id', r.sender_settings_id,
          'production_send_lock_status', r.production_send_lock_status,
          'materialized_from', 'gridex_materialize_company_operational_routes'
        ),
        v_now,
        v_now
      ) returning id into v_route_profile_id;
    else
      update public.ediel_route_profiles
      set
        environment_type = v_env_type,
        route_name = coalesce(r.grid_owner_name, 'Nätägare') || ' ' || coalesce(r.message_family, 'PRODAT'),
        is_active = true,
        is_enabled = true,
        ack_mode = 'contrl_and_aperak',
        ack_policy = 'contrl_and_aperak',
        sender_ediel_id = v_sender_ediel_id,
        own_ediel_id = v_sender_ediel_id,
        sender_sub_address = v_sender_subaddress,
        sender_subaddress = v_sender_subaddress,
        own_subaddress = v_sender_subaddress,
        receiver_ediel_id = v_receiver_ediel_id,
        counterparty_ediel_id = v_receiver_ediel_id,
        receiver_sub_address = v_receiver_subaddress,
        receiver_subaddress = v_receiver_subaddress,
        counterparty_subaddress = v_receiver_subaddress,
        receiver_name = r.grid_owner_name,
        application_reference = v_application_reference,
        message_family = r.message_family,
        message_code = v_message_code,
        transport_type = 'smtp',
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'platform_market_actor_id', v_platform.actor_id,
          'sender_settings_id', r.sender_settings_id,
          'production_send_lock_status', r.production_send_lock_status,
          'materialized_from', 'gridex_materialize_company_operational_routes'
        ),
        updated_at = v_now
      where id = v_existing_id
      returning id into v_route_profile_id;
    end if;

    -- ---- company_market_party_routes ----
    select cmpr.id into v_existing_id
    from public.company_market_party_routes cmpr
    where cmpr.company_id = r.company_id
      and cmpr.market_party_id = v_platform.actor_id
      and cmpr.message_family = r.message_family
      and coalesce(cmpr.environment, cmpr.metadata->>'environment') = v_env
      and coalesce(nullif(cmpr.message_code, ''), nullif(cmpr.metadata->>'message_code', ''), '') = coalesce(v_message_code, '')
      and coalesce(cmpr.platform_actor_route_id::text, cmpr.metadata->>'platform_actor_route_id') = r.platform_actor_route_id::text
      and cmpr.active = true
    order by cmpr.updated_at desc nulls last, cmpr.created_at desc nulls last
    limit 1;

    if v_existing_id is null then
      insert into public.company_market_party_routes (
        company_id, market_party_id, message_family, message_code, environment,
        platform_actor_route_id, communication_route_id, route_profile_id, active,
        metadata, created_by, updated_at
      ) values (
        r.company_id,
        v_platform.actor_id,
        r.message_family,
        v_message_code,
        v_env,
        r.platform_actor_route_id,
        v_comm_route_id,
        v_route_profile_id,
        true,
        jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'materialized_from', 'gridex_materialize_company_operational_routes',
          'environment', v_env,
          'message_code', v_message_code,
          'communication_route_id', v_comm_route_id,
          'ediel_route_profile_id', v_route_profile_id,
          'sender_settings_id', r.sender_settings_id,
          'receiver_ediel_id', v_receiver_ediel_id,
          'receiver_subaddress', v_receiver_subaddress,
          'target_email', v_platform.communication_address,
          'production_send_lock_status', r.production_send_lock_status
        ),
        null,
        v_now
      ) returning id into v_company_party_route_id;
    else
      update public.company_market_party_routes
      set
        message_code = v_message_code,
        environment = v_env,
        platform_actor_route_id = r.platform_actor_route_id,
        communication_route_id = v_comm_route_id,
        route_profile_id = v_route_profile_id,
        active = true,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'platform_actor_route_id', r.platform_actor_route_id,
          'materialized_from', 'gridex_materialize_company_operational_routes',
          'environment', v_env,
          'message_code', v_message_code,
          'communication_route_id', v_comm_route_id,
          'ediel_route_profile_id', v_route_profile_id,
          'sender_settings_id', r.sender_settings_id,
          'receiver_ediel_id', v_receiver_ediel_id,
          'receiver_subaddress', v_receiver_subaddress,
          'target_email', v_platform.communication_address,
          'production_send_lock_status', r.production_send_lock_status
        ),
        updated_at = v_now
      where id = v_existing_id
      returning id into v_company_party_route_id;
    end if;

    -- ---- Postcheck ----
    select * into v_post
    from public.gridex_company_route_readiness_v gr
    where gr.company_id = r.company_id
      and gr.grid_owner_id = r.grid_owner_id
      and gr.platform_actor_route_id = r.platform_actor_route_id
      and gr.message_family = r.message_family
      and coalesce(gr.message_code, '') = coalesce(v_message_code, '')
      and gr.environment = v_env
    limit 1;

    if not found
       or coalesce(v_post.operational_route_ready, false) is not true
       or v_post.communication_route_id is null
       or v_post.ediel_route_profile_id is null
       or v_post.company_market_party_route_id is null then

      insert into public.audit_logs (company_id, entity_type, entity_id, action, metadata, created_at)
      values (
        r.company_id,
        'platform_actor_routes',
        r.platform_actor_route_id::text,
        'route_readiness.materialize_postcheck_failed',
        jsonb_build_object(
          'companyId', r.company_id,
          'gridOwnerId', r.grid_owner_id,
          'platformActorRouteId', r.platform_actor_route_id,
          'messageFamily', r.message_family,
          'messageCode', v_message_code,
          'environment', v_env,
          'communicationRouteId', v_comm_route_id,
          'edielRouteProfileId', v_route_profile_id,
          'companyMarketPartyRouteId', v_company_party_route_id,
          'postcheck', to_jsonb(v_post)
        ),
        v_now
      );

      result_status := 'blocked';
      reason_code := 'route_materialization_postcheck_failed';
      company_id := r.company_id;
      grid_owner_id := r.grid_owner_id;
      grid_owner_name := r.grid_owner_name;
      grid_owner_ediel_id := r.grid_owner_ediel_id;
      platform_actor_route_id := r.platform_actor_route_id;
      message_family := r.message_family;
      message_code := v_message_code;
      environment := r.environment;
      communication_route_id := v_comm_route_id;
      ediel_route_profile_id := v_route_profile_id;
      company_market_party_route_id := v_company_party_route_id;
      repaired_outbound_count := 0;
      repaired_customer_info_count := 0;
      details := jsonb_build_object('postcheck', to_jsonb(v_post));
      return next;
      continue;
    end if;

    -- ---- Repair null-route outbound rows ----
    update public.outbound_requests obr
    set
      communication_route_id = v_comm_route_id,
      ediel_route_profile_id = v_route_profile_id,
      channel_type = 'ediel_partner',
      route_decision_payload = coalesce(obr.route_decision_payload, '{}'::jsonb) || jsonb_build_object(
        'decision_status', case when v_env = 'production' and v_post.production_send_lock_status = 'locked' then 'blocked' else 'ready' end,
        'communication_route_id', v_comm_route_id,
        'ediel_route_profile_id', v_route_profile_id,
        'message_family', r.message_family,
        'message_code', v_message_code,
        'environment', v_env,
        'repair_source', 'gridex_materialize_company_operational_routes'
      ),
      payload = coalesce(obr.payload, '{}'::jsonb) || jsonb_build_object(
        'communication_route_id', v_comm_route_id,
        'ediel_route_profile_id', v_route_profile_id,
        'route_materialization_repaired', true,
        'route_materialization_repaired_at', v_now,
        'environment', v_env,
        'operation_id', coalesce(obr.operation_id::text, obr.payload->>'operation_id')
      ),
      failure_reason = case
        when v_env = 'production' and v_post.production_send_lock_status = 'locked'
          then 'Första produktionssändning måste godkännas innan meddelandet skickas.'
        else obr.failure_reason
      end,
      updated_at = v_now
    where obr.company_id = r.company_id
      and obr.grid_owner_id = r.grid_owner_id
      and obr.request_type in ('customer_masterdata', 'customer_masterdata_request')
      and obr.communication_route_id is null
      and obr.status in ('failed', 'queued', 'prepared');
    get diagnostics v_repaired_outbound_count = row_count;

    -- ---- Repair stuck customer_info_requests ----
    update public.customer_info_requests cir
    set
      status = 'blocked',
      blocker_code = case
        when v_env = 'production' and v_post.production_send_lock_status = 'locked' then 'production_send_locked'
        else 'z01_prepared'
      end,
      blocker_reason = case
        when v_env = 'production' and v_post.production_send_lock_status = 'locked'
          then 'Första produktionssändning måste godkännas innan meddelandet skickas.'
        else 'PRODAT Z01 är förberedd efter route-materialisering.'
      end,
      route_resolution_status = 'operational_route_ready',
      route_resolution_reason = 'Operativ route materialiserades och tidigare null-route-flöde reparerades.',
      next_required_action = case
        when v_env = 'production' and v_post.production_send_lock_status = 'locked'
          then 'Första produktionssändning måste godkännas innan meddelandet skickas.'
        else 'Granska och fortsätt dispatchflödet.'
      end,
      grid_owner_data_request_id = coalesce(
        cir.grid_owner_data_request_id,
        (
          select godr.id
          from public.grid_owner_data_requests godr
          where godr.company_id = cir.company_id
            and godr.customer_id = cir.customer_id
            and godr.grid_owner_id = cir.grid_owner_id
            and godr.request_scope = 'customer_masterdata'
          order by godr.updated_at desc nulls last, godr.created_at desc nulls last
          limit 1
        )
      ),
      outbound_request_id = coalesce(
        cir.outbound_request_id,
        (
          select obr.id
          from public.outbound_requests obr
          where obr.company_id = cir.company_id
            and obr.customer_id = cir.customer_id
            and coalesce(obr.site_id::text, '') = coalesce(cir.site_id::text, '')
            and obr.grid_owner_id = cir.grid_owner_id
            and obr.request_type in ('customer_masterdata', 'customer_masterdata_request')
          order by obr.updated_at desc nulls last, obr.created_at desc nulls last
          limit 1
        )
      ),
      updated_at = v_now
    where cir.company_id = r.company_id
      and cir.grid_owner_id = r.grid_owner_id
      and cir.status in ('blocked', 'route_missing', 'missing_authorization', 'manual_review_required', 'z01_prepared')
      and coalesce(cir.blocker_code, '') in ('operational_route_missing', 'platform_route_exists_but_not_materialized', 'environment_not_resolved');
    get diagnostics v_repaired_customer_info_count = row_count;

    -- ---- Audit log success ----
    insert into public.audit_logs (company_id, entity_type, entity_id, action, metadata, created_at)
    values (
      r.company_id,
      'platform_actor_routes',
      r.platform_actor_route_id::text,
      'route_readiness.materialized_and_repaired',
      jsonb_build_object(
        'companyId', r.company_id,
        'gridOwnerId', r.grid_owner_id,
        'platformActorRouteId', r.platform_actor_route_id,
        'messageFamily', r.message_family,
        'messageCode', v_message_code,
        'environment', v_env,
        'communicationRouteId', v_comm_route_id,
        'edielRouteProfileId', v_route_profile_id,
        'companyMarketPartyRouteId', v_company_party_route_id,
        'repairedOutboundCount', v_repaired_outbound_count,
        'repairedCustomerInfoCount', v_repaired_customer_info_count,
        'productionSendLockStatus', v_post.production_send_lock_status
      ),
      v_now
    );

    result_status := 'materialized';
    reason_code := null;
    company_id := r.company_id;
    grid_owner_id := r.grid_owner_id;
    grid_owner_name := r.grid_owner_name;
    grid_owner_ediel_id := r.grid_owner_ediel_id;
    platform_actor_route_id := r.platform_actor_route_id;
    message_family := r.message_family;
    message_code := v_message_code;
    environment := r.environment;
    communication_route_id := v_comm_route_id;
    ediel_route_profile_id := v_route_profile_id;
    company_market_party_route_id := v_company_party_route_id;
    repaired_outbound_count := v_repaired_outbound_count;
    repaired_customer_info_count := v_repaired_customer_info_count;
    details := jsonb_build_object('production_send_lock_status', v_post.production_send_lock_status, 'send_ready', v_post.send_ready);
    return next;
  end loop;
end;
$$;

--
-- Name: gridex_materialize_legal_bundle_version(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_legal_bundle_version(p_company_id uuid, p_contract_product_version_id uuid, p_legacy_legal_bundle_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_required text[];
  v_module text;
  v_profile public.tenant_legal_profiles%rowtype;
  v_company jsonb;
  v_profile_snapshot jsonb;
  v_profile_hash text;
  v_template_version_id uuid;
  v_template_version_number integer;
  v_template_title text;
  v_template_body text;
  v_override_id uuid;
  v_override_mode text;
  v_override_title text;
  v_override_body text;
  v_title text;
  v_source_body text;
  v_rendered text;
  v_doc_unresolved text[];
  v_unresolved text[] := array[]::text[];
  v_docs jsonb := '[]'::jsonb;
  v_bundle_id uuid;
  v_number integer;
  v_hash text;
  v_mode text := 'ops_standard';
  v_origin text;
  v_template_version text;
  v_doc jsonb;
begin
  select required_legal_modules
    into v_required
  from public.contract_product_versions
  where id = p_contract_product_version_id;
  if not found then
    raise exception using errcode='P0002', message='contract_product_version_not_found';
  end if;

  select *
    into v_profile
  from public.tenant_legal_profiles
  where company_id = p_company_id;
  if not found then
    raise exception using errcode='23514', message='tenant_legal_profile_missing';
  end if;

  select to_jsonb(c)
    into v_company
  from public.companies c
  where c.id = p_company_id;
  if v_company is null then
    raise exception using errcode='P0002', message='company_not_found';
  end if;

  v_profile_snapshot := to_jsonb(v_profile) - 'verified_by';
  v_profile_hash := encode(digest(v_profile_snapshot::text,'sha256'),'hex');

  foreach v_module in array coalesce(v_required,'{}'::text[]) loop
    v_template_version_id := null;
    v_template_version_number := null;
    v_template_title := null;
    v_template_body := null;
    v_override_id := null;
    v_override_mode := null;
    v_override_title := null;
    v_override_body := null;
    v_title := null;
    v_source_body := null;
    v_origin := null;
    v_template_version := null;

    select ltv.id, ltv.version_number, ltv.title, ltv.body
      into v_template_version_id, v_template_version_number, v_template_title, v_template_body
    from public.legal_templates lt
    join public.legal_template_versions ltv on ltv.legal_template_id = lt.id
    where lt.module_key = v_module
      and lt.status = 'active'
      and ltv.status = 'published'
      and ltv.locked_at is not null
    order by ltv.version_number desc, ltv.published_at desc nulls last
    limit 1;

    select o.id, o.legal_mode, o.title, o.body
      into v_override_id, v_override_mode, v_override_title, v_override_body
    from public.tenant_legal_overrides o
    where o.company_id = p_company_id
      and o.module_key = v_module
      and o.status in ('approved','published')
      and o.locked_at is not null
    order by o.reviewed_at desc nulls last, o.created_at desc
    limit 1;

    if v_override_id is not null and v_override_mode = 'replacement' then
      v_title := v_override_title;
      v_source_body := v_override_body;
      v_origin := 'tenant_replacement';
      v_template_version := 'tenant:' || v_override_id::text;
      v_mode := 'tenant_legal';
      v_template_version_id := null;
    elsif v_template_version_id is not null then
      v_title := v_template_title;
      v_source_body := v_template_body;
      v_origin := 'platform_template';
      v_template_version := v_template_version_number::text;
      if v_override_id is not null and v_override_mode = 'addendum' then
        v_title := v_title || ' – tenanttillägg';
        v_source_body := v_source_body || E'\n\nTenanttillägg\n' || v_override_body;
        v_origin := 'platform_template_with_tenant_addendum';
        if v_mode <> 'tenant_legal' then
          v_mode := 'ops_standard_with_addendum';
        end if;
      else
        v_override_id := null;
      end if;
    else
      v_unresolved := array_append(v_unresolved,'missing_document:' || v_module);
      continue;
    end if;

    v_title := public.gridex_render_legal_document(v_title,v_profile_snapshot,v_company);
    v_rendered := public.gridex_render_legal_document(v_source_body,v_profile_snapshot,v_company);

    select coalesce(array_agg(distinct match[1] order by match[1]),'{}'::text[])
      into v_doc_unresolved
    from regexp_matches(
      v_title || E'\n' || v_rendered,
      '\{\{[[:space:]]*([a-zA-Z0-9_.-]+)[[:space:]]*\}\}',
      'g'
    ) as match;

    if cardinality(v_doc_unresolved) > 0 then
      v_unresolved := v_unresolved || array(
        select 'unresolved_placeholder:' || v_module || ':' || placeholder
        from unnest(v_doc_unresolved) as placeholder
      );
    end if;

    v_docs := v_docs || jsonb_build_array(jsonb_build_object(
      'module_key',v_module,
      'title',v_title,
      'rendered_body',v_rendered,
      'origin',v_origin,
      'legal_template_version_id',v_template_version_id,
      'tenant_legal_override_id',v_override_id,
      'template_version',v_template_version,
      'tenant_customized',v_override_id is not null,
      'unresolved_variables',to_jsonb(v_doc_unresolved),
      'rendered_sha256',encode(digest(v_title || E'\n' || v_rendered,'sha256'),'hex'),
      'sort_order',coalesce(array_position(v_required,v_module),100) * 10
    ));
  end loop;

  select coalesce(array_agg(distinct item order by item),'{}'::text[])
    into v_unresolved
  from unnest(v_unresolved) as item;

  v_hash := encode(digest(jsonb_build_object(
    'schema','gridex_legal_bundle_v5',
    'company_id',p_company_id,
    'contract_product_version_id',p_contract_product_version_id,
    'profile_sha256',v_profile_hash,
    'required_modules',v_required,
    'documents',v_docs
  )::text,'sha256'),'hex');

  select id
    into v_bundle_id
  from public.legal_bundle_versions
  where company_id = p_company_id
    and contract_product_version_id = p_contract_product_version_id
    and content_sha256 = v_hash
  limit 1;
  if v_bundle_id is not null then
    return v_bundle_id;
  end if;

  select coalesce(max(version_number),0) + 1
    into v_number
  from public.legal_bundle_versions
  where company_id = p_company_id
    and contract_product_version_id = p_contract_product_version_id;

  insert into public.legal_bundle_versions(
    company_id,contract_product_version_id,legacy_legal_bundle_id,version_number,legal_mode,
    rendered_snapshot,unresolved_variables,content_sha256,status,created_by,
    tenant_legal_profile_snapshot,tenant_legal_profile_sha256
  ) values(
    p_company_id,p_contract_product_version_id,null,v_number,v_mode,
    jsonb_build_object(
      'schema','gridex_legal_bundle_v5',
      'required_modules',v_required,
      'tenant_legal_profile',v_profile_snapshot,
      'tenant_legal_profile_sha256',v_profile_hash,
      'documents',v_docs
    ),v_unresolved,v_hash,'draft',p_actor_user_id,v_profile_snapshot,v_profile_hash
  ) returning id into v_bundle_id;

  for v_doc in select value from jsonb_array_elements(v_docs) loop
    insert into public.legal_bundle_version_documents(
      legal_bundle_version_id,module_key,legal_template_version_id,tenant_legal_override_id,
      legacy_legal_text_version_id,title,rendered_body,content_sha256,sort_order,
      origin,template_key,template_version,tenant_customized,unresolved_variables
    ) values(
      v_bundle_id,
      v_doc->>'module_key',
      nullif(v_doc->>'legal_template_version_id','')::uuid,
      nullif(v_doc->>'tenant_legal_override_id','')::uuid,
      null,
      v_doc->>'title',
      v_doc->>'rendered_body',
      v_doc->>'rendered_sha256',
      coalesce((v_doc->>'sort_order')::integer,100),
      v_doc->>'origin',
      v_doc->>'module_key',
      v_doc->>'template_version',
      coalesce((v_doc->>'tenant_customized')::boolean,false),
      coalesce(array(select jsonb_array_elements_text(v_doc->'unresolved_variables')),'{}'::text[])
    );
  end loop;

  return v_bundle_id;
end $$;

--
-- Name: FUNCTION gridex_materialize_legal_bundle_version(p_company_id uuid, p_contract_product_version_id uuid, p_legacy_legal_bundle_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_materialize_legal_bundle_version(p_company_id uuid, p_contract_product_version_id uuid, p_legacy_legal_bundle_id uuid, p_actor_user_id uuid) IS 'Creates an immutable legal bundle directly from published legal_template_versions and approved tenant overrides. Legacy bundle arguments are ignored.';

--
-- Name: gridex_materialize_poa_scopes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_poa_scopes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_scope text;
  v_valid_from date;
  v_valid_to date;
begin
  if lower(coalesce(new.status, '')) <> 'signed' then
    update public.power_of_attorney_scopes s
       set status = coalesce(nullif(lower(new.status), ''), 'inactive'),
           is_active = false,
           valid_to = coalesce(s.valid_to, current_date),
           updated_at = now()
     where s.company_id = new.company_id
       and s.power_of_attorney_id = new.id
       and coalesce(s.is_active, true) = true;
    return new;
  end if;

  if lower(coalesce(new.source, '')) <> 'website_api'
     or jsonb_typeof(new.signed_scope_snapshot) <> 'array'
     or coalesce(jsonb_array_length(new.signed_scope_snapshot), 0) = 0 then
    return new;
  end if;

  v_valid_from := coalesce(new.accepted_at, new.signed_at, new.valid_from, now())::date;
  v_valid_to := coalesce(new.valid_to::date, new.valid_until);

  for v_scope in
    select distinct nullif(btrim(value), '')
      from jsonb_array_elements_text(new.signed_scope_snapshot) as scopes(value)
     where nullif(btrim(value), '') is not null
  loop
    insert into public.power_of_attorney_scopes(
      company_id,
      power_of_attorney_id,
      customer_id,
      site_id,
      metering_point_id,
      customer_contract_id,
      scope_type,
      status,
      is_active,
      valid_from,
      valid_to,
      metadata,
      created_at,
      updated_at
    ) values (
      new.company_id,
      new.id,
      new.customer_id,
      coalesce(new.customer_site_id, new.site_id),
      new.metering_point_id,
      coalesce(new.customer_contract_id, new.contract_id),
      v_scope,
      'active',
      true,
      v_valid_from,
      v_valid_to,
      jsonb_build_object(
        'source', 'powers_of_attorney.signed_scope_snapshot',
        'power_of_attorney_source', new.source,
        'materialization_version', 'signed_scope_v1'
      ),
      now(),
      now()
    )
    on conflict (company_id, power_of_attorney_id, scope_type)
    do update set
      customer_id = excluded.customer_id,
      site_id = excluded.site_id,
      metering_point_id = excluded.metering_point_id,
      customer_contract_id = excluded.customer_contract_id,
      status = 'active',
      is_active = true,
      valid_from = excluded.valid_from,
      valid_to = excluded.valid_to,
      metadata = coalesce(public.power_of_attorney_scopes.metadata, '{}'::jsonb) || excluded.metadata,
      updated_at = now();
  end loop;

  -- If an immutable signed snapshot is ever narrowed by a corrective migration,
  -- stale relational scopes must not remain externally usable.
  update public.power_of_attorney_scopes s
     set status = 'inactive',
         is_active = false,
         valid_to = coalesce(s.valid_to, current_date),
         updated_at = now()
   where s.company_id = new.company_id
     and s.power_of_attorney_id = new.id
     and coalesce(s.is_active, true) = true
     and not exists (
       select 1
         from jsonb_array_elements_text(new.signed_scope_snapshot) x(value)
        where nullif(btrim(x.value), '') = s.scope_type
     );

  return new;
end;
$$;

--
-- Name: gridex_materialize_publication_price_options_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_publication_price_options_v1(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v public.contract_publication_versions%rowtype;
  v_company_id uuid;
  v_source_publication_version_id uuid;
  v_source_kind text;
  v_prior_candidate_count integer:=0;
  v_prior_graph_count integer:=0;
  v_source_option_count integer:=0;
  v_source_default_count integer:=0;
  v_inserted integer:=0;
  v_target_option_count integer:=0;
begin
  select publication_version.* into v
  from public.contract_publication_versions publication_version
  where publication_version.id=p_publication_version_id
  for update;

  if not found then
    raise exception using errcode='P0002',
      message='PUBLICATION_VERSION_NOT_FOUND';
  end if;

  select assignment.company_id into v_company_id
  from public.contract_publications publication
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  where publication.id=v.contract_publication_id;

  if not found then
    raise exception using errcode='23514',
      message='PUBLICATION_TENANT_NOT_READY';
  end if;

  if exists(
    select 1 from public.contract_price_options target
    where target.contract_publication_version_id=v.id
      and target.status='active'
  ) then
    v_source_kind:='existing_snapshot';
  elsif exists(
    select 1 from public.contract_price_options template
    where template.company_id=v_company_id
      and template.contract_product_version_id=v.contract_product_version_id
      and template.price_plan_version_id=v.price_plan_version_id
      and template.contract_publication_version_id is null
      and template.status='active'
  ) then
    v_source_kind:='template';
  else
    with candidate_versions as (
      select distinct source.contract_publication_version_id id
      from public.contract_price_options source
      join public.contract_publication_versions source_version
        on source_version.id=source.contract_publication_version_id
      join public.contract_publications source_publication
        on source_publication.id=source_version.contract_publication_id
      join public.tenant_contract_assignments source_assignment
        on source_assignment.id=source_publication.assignment_id
      where source_assignment.company_id=v_company_id
        and source.contract_product_version_id=v.contract_product_version_id
        and source.price_plan_version_id=v.price_plan_version_id
        and source.contract_publication_version_id<>v.id
        and source.status='active'
    )
    select count(*),count(distinct
      public.gridex_publication_price_options_json_v1(candidate.id)::text)
      into v_prior_candidate_count,v_prior_graph_count
    from candidate_versions candidate;

    if v_prior_candidate_count=0 then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_OPTIONS_MISSING';
    elsif v_prior_graph_count<>1 then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_SOURCE_AMBIGUOUS';
    end if;

    select source.contract_publication_version_id
      into v_source_publication_version_id
    from public.contract_price_options source
    join public.contract_publication_versions source_version
      on source_version.id=source.contract_publication_version_id
    join public.contract_publications source_publication
      on source_publication.id=source_version.contract_publication_id
    join public.tenant_contract_assignments source_assignment
      on source_assignment.id=source_publication.assignment_id
    where source_assignment.company_id=v_company_id
      and source.contract_product_version_id=v.contract_product_version_id
      and source.price_plan_version_id=v.price_plan_version_id
      and source.contract_publication_version_id<>v.id
      and source.status='active'
    group by source.contract_publication_version_id,
      source_version.version_number,source_version.created_at
    order by source_version.version_number desc,source_version.created_at desc
    limit 1;
    v_source_kind:='prior_snapshot';
  end if;

  if v_source_kind<>'existing_snapshot' then
    select count(*),count(*) filter(where source.is_default is true)
      into v_source_option_count,v_source_default_count
    from public.contract_price_options source
    where source.company_id=v_company_id
      and source.contract_product_version_id=v.contract_product_version_id
      and source.price_plan_version_id=v.price_plan_version_id
      and source.status='active'
      and (
        (v_source_kind='template'
          and source.contract_publication_version_id is null)
        or (v_source_kind='prior_snapshot'
          and source.contract_publication_version_id=
            v_source_publication_version_id)
      );

    if v_source_option_count=0 then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_OPTIONS_MISSING';
    elsif v_source_default_count>1 then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_OPTION_DEFAULT_INVALID';
    end if;

    with source_options as (
      select source.*
      from public.contract_price_options source
      where source.company_id=v_company_id
        and source.contract_product_version_id=v.contract_product_version_id
        and source.price_plan_version_id=v.price_plan_version_id
        and source.status='active'
        and (
          (v_source_kind='template'
            and source.contract_publication_version_id is null)
          or (v_source_kind='prior_snapshot'
            and source.contract_publication_version_id=
              v_source_publication_version_id)
        )
    ), source_stats as (
      select count(*) option_count from source_options
    ), inserted as (
      insert into public.contract_price_options(
        company_id,contract_product_version_id,price_plan_version_id,
        contract_publication_version_id,option_reference,option_code,
        customer_name,internal_description,contract_type,binding_months,
        notice_months,auto_renew_enabled,renewal_term_months,valid_from,
        valid_to,earliest_start_date,latest_start_date,status,sort_order,
        version_number,metadata,created_by,customer_type,is_default,
        selection_required
      )
      select source.company_id,source.contract_product_version_id,
        source.price_plan_version_id,v.id,source.option_reference,
        source.option_code,source.customer_name,source.internal_description,
        source.contract_type,source.binding_months,source.notice_months,
        source.auto_renew_enabled,source.renewal_term_months,
        source.valid_from,source.valid_to,source.earliest_start_date,
        source.latest_start_date,source.status,source.sort_order,
        source.version_number,
        coalesce(source.metadata,'{}'::jsonb)||jsonb_build_object(
          'materialized_from_price_option_id',source.id,
          'materialized_source_kind',v_source_kind
        ),coalesce(p_actor_user_id,source.created_by),
        coalesce(source.customer_type,v.customer_type),
        coalesce(source.is_default,source_stats.option_count=1),
        coalesce(source.selection_required,source_stats.option_count>1)
      from source_options source
      cross join source_stats
      where not exists(
        select 1 from public.contract_price_options target
        where target.contract_publication_version_id=v.id
          and (
            target.option_reference=source.option_reference
            or target.option_code=source.option_code
          )
      )
      returning id
    )
    select count(*) into v_inserted from inserted;
  end if;

  select count(*) into v_target_option_count
  from public.contract_price_options target
  where target.contract_publication_version_id=v.id
    and target.status='active';

  if v_target_option_count=0 then
    raise exception using errcode='23514',
      message='PUBLICATION_PRICE_OPTION_SNAPSHOT_INSERT_FAILED',
      detail=jsonb_build_object(
        'publication_version_id',v.id,
        'source_kind',v_source_kind,
        'source_publication_version_id',v_source_publication_version_id,
        'source_option_count',v_source_option_count,
        'inserted_price_options',v_inserted,
        'target_price_option_count',v_target_option_count,
        'unique_objects',public.gridex_price_option_unique_objects_v1()
      )::text;
  end if;

  if v_source_kind<>'existing_snapshot'
     and v_target_option_count<>v_source_option_count then
    raise exception using errcode='23514',
      message='PUBLICATION_PRICE_OPTION_SNAPSHOT_COUNT_MISMATCH',
      detail=jsonb_build_object(
        'publication_version_id',v.id,
        'source_kind',v_source_kind,
        'source_publication_version_id',v_source_publication_version_id,
        'source_option_count',v_source_option_count,
        'inserted_price_options',v_inserted,
        'target_price_option_count',v_target_option_count,
        'unique_objects',public.gridex_price_option_unique_objects_v1()
      )::text;
  end if;

  -- Copy area rows without a broad conflict handler. Existing rows are skipped
  -- only by their canonical option + area identity.
  insert into public.contract_price_option_area_prices(
    company_id,contract_price_option_id,price_plan_version_id,
    price_row_reference,price_area,amount,unit,vat_treatment,
    valid_from,valid_to,metadata,created_by,status
  )
  select target.company_id,target.id,target.price_plan_version_id,
    source_area.price_row_reference,source_area.price_area,
    source_area.amount,source_area.unit,source_area.vat_treatment,
    source_area.valid_from,source_area.valid_to,
    coalesce(source_area.metadata,'{}'::jsonb)||jsonb_build_object(
      'materialized_from_area_price_id',source_area.id
    ),coalesce(p_actor_user_id,source_area.created_by),source_area.status
  from public.contract_price_options target
  join public.contract_price_options source
    on source.id=(target.metadata->>'materialized_from_price_option_id')::uuid
  join public.contract_price_option_area_prices source_area
    on source_area.contract_price_option_id=source.id
  where target.contract_publication_version_id=v.id
    and not exists(
      select 1 from public.contract_price_option_area_prices existing_area
      where existing_area.contract_price_option_id=target.id
        and existing_area.price_area=source_area.price_area
    );

  -- Legacy partial snapshots may lack materialization metadata. Complete only
  -- from the exact same template identity and unchanged commercial values.
  insert into public.contract_price_option_area_prices(
    company_id,contract_price_option_id,price_plan_version_id,
    price_row_reference,price_area,amount,unit,vat_treatment,
    valid_from,valid_to,metadata,created_by,status
  )
  select target.company_id,target.id,target.price_plan_version_id,
    source_area.price_row_reference,source_area.price_area,
    source_area.amount,source_area.unit,source_area.vat_treatment,
    source_area.valid_from,source_area.valid_to,
    coalesce(source_area.metadata,'{}'::jsonb)||jsonb_build_object(
      'materialized_from_area_price_id',source_area.id,
      'materialized_source_kind','template_reference_match'
    ),coalesce(p_actor_user_id,source_area.created_by),source_area.status
  from public.contract_price_options target
  join public.contract_price_options source
    on source.company_id=target.company_id
   and source.contract_product_version_id=target.contract_product_version_id
   and source.price_plan_version_id=target.price_plan_version_id
   and source.contract_publication_version_id is null
   and source.status='active'
   and source.option_reference=target.option_reference
   and source.option_code=target.option_code
   and source.contract_type=target.contract_type
   and source.binding_months is not distinct from target.binding_months
   and source.notice_months is not distinct from target.notice_months
   and source.auto_renew_enabled is not distinct from target.auto_renew_enabled
   and source.renewal_term_months is not distinct from target.renewal_term_months
   and source.valid_from is not distinct from target.valid_from
   and source.valid_to is not distinct from target.valid_to
   and source.earliest_start_date is not distinct from target.earliest_start_date
   and source.latest_start_date is not distinct from target.latest_start_date
   and coalesce(source.metadata->>'fixed_price','')=
     coalesce(target.metadata->>'fixed_price','')
   and coalesce(source.metadata->>'markup','')=
     coalesce(target.metadata->>'markup','')
   and coalesce(source.metadata->>'monthly_fee','')=
     coalesce(target.metadata->>'monthly_fee','')
  join public.contract_price_option_area_prices source_area
    on source_area.contract_price_option_id=source.id
  where target.contract_publication_version_id=v.id
    and not exists(
      select 1 from public.contract_price_option_area_prices existing_area
      where existing_area.contract_price_option_id=target.id
        and existing_area.price_area=source_area.price_area
    );

  -- Complete only relation-policy metadata; commercial values remain unchanged.
  perform set_config('gridex.publication_graph_repair','on',true);
  update public.contract_price_options target
  set is_default=true,selection_required=false
  where target.contract_publication_version_id=v.id
    and (target.is_default is null or target.selection_required is null)
    and 1=(
      select count(*) from public.contract_price_options all_options
      where all_options.contract_publication_version_id=v.id
        and all_options.status='active'
    );
  perform set_config('gridex.publication_graph_repair','off',true);

  return jsonb_build_object(
    'publication_version_id',v.id,
    'source_kind',v_source_kind,
    'source_publication_version_id',v_source_publication_version_id,
    'source_price_option_count',v_source_option_count,
    'inserted_price_options',v_inserted,
    'target_price_option_count',v_target_option_count,
    'price_options',public.gridex_publication_price_options_json_v1(v.id)
  );
end $$;

--
-- Name: FUNCTION gridex_materialize_publication_price_options_v1(p_publication_version_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_materialize_publication_price_options_v1(p_publication_version_id uuid, p_actor_user_id uuid) IS 'Strictly copies active template/prior-snapshot rows into one publication version. No broad conflict is swallowed; source/target counts must match before publication can finalize.';

--
-- Name: gridex_materialize_signed_website_poa_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_signed_website_poa_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_document_id uuid;
  v_document record;
  v_has_external_capture boolean;
begin
  if lower(coalesce(new.source, '')) <> 'website_api'
     or lower(coalesce(new.status, '')) <> 'signed' then
    return new;
  end if;

  if jsonb_typeof(new.fullmakt_snapshot) = 'object'
     and new.fullmakt_snapshot <> '{}'::jsonb then
    return new;
  end if;

  if coalesce(jsonb_array_length(new.signed_scope_snapshot), 0) = 0
     or nullif(btrim(new.signer_name), '') is null
     or nullif(btrim(new.signer_identity_number), '') is null
     or nullif(btrim(new.method), '') is null
     or coalesce(new.accepted_at, new.signed_at) is null then
    return new;
  end if;

  v_has_external_capture :=
    lower(coalesce(new.evidence_payload->>'externally_sendable_at_capture', '')) in ('true','1','yes')
    or lower(coalesce(new.evidence_payload->>'capture_type', '')) = 'structured_complete'
    or lower(coalesce(new.metadata->>'poa_capture_type', '')) = 'structured_complete'
    or lower(coalesce(new.metadata->>'externally_sendable', '')) in ('true','1','yes');

  if not v_has_external_capture then
    return new;
  end if;

  v_document_id := coalesce(new.legal_bundle_version_document_id, new.legal_text_version_id);
  if v_document_id is null then
    return new;
  end if;

  select d.id,
         d.legal_bundle_version_id,
         d.template_version,
         d.title,
         d.rendered_body,
         d.content_sha256,
         b.published_at as bundle_published_at,
         b.locked_at as bundle_locked_at
    into v_document
    from public.legal_bundle_version_documents d
    join public.legal_bundle_versions b on b.id = d.legal_bundle_version_id
   where d.id = v_document_id
     and b.company_id = new.company_id
     and d.module_key = 'power_of_attorney'
     and b.status = 'published'
     and b.locked_at is not null
     and coalesce(cardinality(d.unresolved_variables), 0) = 0
     and nullif(btrim(d.title), '') is not null
     and nullif(btrim(d.rendered_body), '') is not null
   limit 1;

  if v_document.id is null then
    return new;
  end if;

  new.fullmakt_snapshot := jsonb_build_object(
    'snapshot_version', 'website_poa_v1',
    'source', 'locked_legal_bundle_document',
    'application_id', new.metadata->>'application_id',
    'accepted_at', coalesce(new.accepted_at, new.signed_at),
    'scopes', new.signed_scope_snapshot,
    'legal_text_version_id', v_document.id,
    'legal_bundle_version_id', v_document.legal_bundle_version_id,
    'legal_text', jsonb_build_object(
      'id', v_document.id,
      'type', 'power_of_attorney',
      'version', v_document.template_version,
      'title', v_document.title,
      'body', v_document.rendered_body,
      'content_sha256', v_document.content_sha256,
      'published_at', v_document.bundle_published_at,
      'locked_at', v_document.bundle_locked_at
    )
  );

  new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
    'poa_snapshot_materialized', true,
    'poa_snapshot_materialization_version', 'website_poa_v1'
  );

  return new;
end;
$$;

--
-- Name: gridex_materialize_supplier_switch_process_variant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_materialize_supplier_switch_process_variant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_process_type text;
  v_variant text;
  v_reason text;
  v_expected_z02 text;
  v_z03_variant text;
  v_canonical jsonb;
  v_portal jsonb;
begin
  case new.request_type
    when 'switch' then
      v_process_type := 'supplier_switch_existing_site';
      v_variant := CASE WHEN new.prodat_variant = 'H' AND new.prodat_reason = 'Z25' THEN 'H' ELSE 'L' END;
      v_reason := CASE WHEN v_variant = 'H' THEN 'Z25' ELSE 'Z22' END;
      v_expected_z02 := 'L';
      v_z03_variant := v_variant;
    when 'move_in' then
      v_process_type := 'move_in';
      v_variant := 'LK';
      v_reason := 'Z23';
      v_expected_z02 := 'LK';
      v_z03_variant := 'LK';
    else
      v_process_type := coalesce(nullif(new.process_type, ''), 'unknown');
      v_variant := null;
      v_reason := null;
      v_expected_z02 := null;
      v_z03_variant := null;
  end case;

  new.process_type := v_process_type;
  new.prodat_variant := v_variant;
  new.prodat_reason := v_reason;
  new.expected_z02_variant := v_expected_z02;
  new.z03_variant := v_z03_variant;

  v_canonical := jsonb_build_object(
    'process_type', v_process_type,
    'z01_variant', v_variant,
    'z01_reason', v_reason,
    'expected_z02_variant', v_expected_z02,
    'z03_variant', v_z03_variant,
    'source', 'gridex_materialize_supplier_switch_process_variant'
  );

  new.metadata := coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object('canonical_process', v_canonical);

  new.validation_snapshot := coalesce(new.validation_snapshot, '{}'::jsonb)
    || jsonb_build_object('canonicalProcess', v_canonical);

  if v_reason is not null then
    v_portal := coalesce(new.validation_snapshot -> 'portalData', '{}'::jsonb)
      || jsonb_build_object('reasonForTransaction', v_reason);
    new.validation_snapshot := jsonb_set(
      new.validation_snapshot,
      '{portalData}',
      v_portal,
      true
    );
  end if;

  return new;
end;
$$;

--
-- Name: gridex_merge_customers_v1(uuid, uuid, uuid[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_merge_customers_v1(p_company_id uuid, p_primary_customer_id uuid, p_source_customer_ids uuid[], p_actor_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  -- Customer-scoped tables whose rows follow the surviving customer. Tables
  -- without customer_id/company_id in this database are skipped.
  v_tables constant text[] := array[
    'customer_sites', 'metering_points', 'customer_contacts', 'customer_addresses',
    'customer_contracts', 'customer_contract_events', 'powers_of_attorney',
    'power_of_attorney_scopes', 'authorization_scopes', 'customer_authorization_documents',
    'customer_cases', 'customer_case_events', 'customer_info_requests',
    'customer_info_request_events', 'customer_internal_notes', 'customer_operation_tasks',
    'customer_lifecycle_decisions', 'customer_lifecycle_events',
    'customer_duplicate_resolution_events', 'customer_readiness_snapshots',
    'document_ai_extractions', 'supplier_switch_requests', 'supplier_switch_events',
    'grid_owner_data_requests', 'grid_owner_information_requests', 'outbound_requests', 'outbound_dispatch_events',
    'billing_underlays', 'billing_export_run_items', 'partner_exports',
    'tenant_email_outbox', 'ediel_messages', 'customer_import_rows',
    'customer_case_attachments', 'customer_portal_accounts',
    'customer_portal_identities', 'tenant_portal_customer_links',
    'customer_profiles', 'customer_portal_claims', 'customer_portal_events',
    'customer_portal_requests', 'customer_portal_completions',
    'customer_portal_api_access_logs', 'customer_portal_write_idempotency',
    'customer_events'
  ];
  v_primary public.customers%rowtype;
  v_source public.customers%rowtype;
  v_source_id uuid;
  v_table text;
  v_has_updated_by boolean;
  v_rows integer;
  v_moved jsonb;
  v_snapshot jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_merge_service_role_required';
  end if;
  if p_company_id is null or p_primary_customer_id is null or p_actor_user_id is null
     or coalesce(cardinality(p_source_customer_ids), 0) = 0
     or p_primary_customer_id = any (p_source_customer_ids)
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'customer_merge_payload_invalid';
  end if;

  -- Lock every customer in a stable order to avoid deadlocks between merges.
  perform 1 from public.customers
  where company_id = p_company_id
    and (id = p_primary_customer_id or id = any (p_source_customer_ids))
  order by id
  for update;

  select * into v_primary from public.customers
  where id = p_primary_customer_id and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_merge_primary_not_found_for_tenant';
  end if;
  if v_primary.merged_into_customer_id is not null or v_primary.status = 'archived' then
    raise exception using errcode = '23514', message = 'customer_merge_primary_not_mergeable';
  end if;

  -- Lock binding rows after the customer graph, in a consistent table/key order.
  perform 1 from public.customer_portal_accounts where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids)) order by id for update;
  perform 1 from public.customer_portal_identities where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids)) order by id for update;
  perform 1 from public.tenant_portal_customer_links where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids)) order by id for update;

  -- The public portal/auth IDs belong to one external subject; native account
  -- user_id has a different namespace and is deliberately not compared with it.
  if exists(select 1 from public.customer_portal_identities where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids))
    and status = 'active' and auth_user_id is not null and customer_portal_user_id is not null
    and auth_user_id <> customer_portal_user_id) then
    raise exception using errcode = '23514', message = 'customer_merge_ambiguous_portal_subject';
  end if;
  -- Header-based identity resolution cannot choose between different providers
  -- presenting the same raw external subject. Never collapse those providers.
  if exists(select 1 from public.customer_portal_identities where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids))
    and status = 'active' and coalesce(customer_portal_user_id, auth_user_id) is not null
    group by coalesce(customer_portal_user_id, auth_user_id) having count(*) > 1) then
    raise exception using errcode = '23514', message = 'customer_merge_ambiguous_portal_subject';
  end if;
  if exists(select 1 from public.customer_portal_identities where company_id = p_company_id
    and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids))
    and status = 'active' and nullif(btrim(external_account_id), '') is not null
    group by external_account_id having count(*) > 1)
    or exists(select 1 from public.customer_portal_accounts where company_id = p_company_id
      and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids))
      and is_active and (nullif(lower(btrim(status)), '') is null or lower(btrim(status)) in ('active','confirmed','enabled'))
      and nullif(btrim(external_account_id), '') is not null
      group by external_account_id having count(*) > 1)
    or exists(select 1 from public.tenant_portal_customer_links where company_id = p_company_id
      and (customer_id = p_primary_customer_id or customer_id = any(p_source_customer_ids))
      and status = 'active' and external_customer_id is not null
      group by external_customer_id having count(*) > 1) then
    raise exception using errcode = '23514', message = 'customer_merge_ambiguous_portal_subject';
  end if;

  set constraints customer_case_attachments_case_owner_fk, customer_case_events_case_owner_fk, customer_contracts_company_customer_customer_site_rel_fkey, customer_contracts_company_customer_site_rel_fkey, customer_info_requests_company_customer_site_rel_fkey, grid_owner_data_requests_company_customer_site_rel_fkey, grid_owner_information_requests_company_customer_site_rel_fkey, metering_points_company_customer_site_rel_fkey, outbound_requests_company_customer_customer_site_rel_fkey, outbound_requests_company_customer_site_rel_fkey, powers_of_attorney_company_customer_customer_site_rel_fkey, powers_of_attorney_company_customer_site_rel_fkey, supplier_switch_requests_company_customer_customer_site_rel_fke, supplier_switch_requests_company_customer_site_rel_fkey deferred;

  foreach v_source_id in array (select array_agg(distinct s) from unnest(p_source_customer_ids) s) loop
    select * into v_source from public.customers
    where id = v_source_id and company_id = p_company_id;
    if not found then
      -- Also the answer for another tenant's customer: never reveal or touch it.
      raise exception using errcode = 'P0002', message = 'customer_merge_source_not_found_for_tenant', detail = v_source_id::text;
    end if;
    if v_source.merged_into_customer_id is not null then
      raise exception using errcode = '23514', message = 'customer_merge_source_already_merged', detail = v_source_id::text;
    end if;

    v_moved := '{}'::jsonb;
    foreach v_table in array v_tables loop
      if to_regclass('public.' || v_table) is null
         or not exists (select 1 from pg_attribute where attrelid = to_regclass('public.' || v_table)
                        and attname = 'customer_id' and not attisdropped)
         or not exists (select 1 from pg_attribute where attrelid = to_regclass('public.' || v_table)
                        and attname = 'company_id' and not attisdropped) then
        continue;
      end if;
      v_has_updated_by := v_table <> 'customer_import_rows' and exists (
        select 1 from pg_attribute where attrelid = to_regclass('public.' || v_table)
          and attname = 'updated_by' and not attisdropped);
      execute format(
        'update public.%I set customer_id = $1%s where customer_id = $2 and company_id = $3',
        v_table, case when v_has_updated_by then ', updated_by = $4' else '' end
      ) using p_primary_customer_id, v_source_id, p_company_id, p_actor_user_id;
      get diagnostics v_rows = row_count;
      v_moved := v_moved || jsonb_build_object(v_table, v_rows);
    end loop;

    v_snapshot := jsonb_build_object(
      'id', v_source.id,
      'customer_number', v_source.customer_number,
      'full_name', v_source.full_name,
      'company_name', v_source.company_name,
      'email', v_source.email,
      'status', v_source.status
    );

    update public.customers
    set status = 'inactive',
        merge_status = 'merged',
        merged_into_customer_id = p_primary_customer_id,
        merged_at = now(),
        merged_by = p_actor_user_id,
        duplicate_review_status = 'merged',
        possible_duplicate = false,
        updated_by = p_actor_user_id,
        updated_at = now()
    where id = v_source_id and company_id = p_company_id;

    insert into public.customer_merge_events (
      company_id, primary_customer_id, merged_customer_id, reason, moved_counts, source_snapshot, created_by
    ) values (
      p_company_id, p_primary_customer_id, v_source_id, p_reason, v_moved, v_snapshot, p_actor_user_id
    );

    insert into public.audit_logs (
      actor_user_id, company_id, entity_type, entity_id, action, old_values, new_values, metadata
    ) values (
      p_actor_user_id, p_company_id, 'customer_merge', p_primary_customer_id::text, 'customers_merged',
      jsonb_build_object('source', v_snapshot),
      jsonb_build_object('primaryCustomerId', p_primary_customer_id, 'mergedCustomerId', v_source_id, 'moved', v_moved),
      jsonb_build_object('reason', p_reason, 'crossTenantBlocked', false, 'source', 'gridex_merge_customers_v1')
    );

    v_results := v_results || jsonb_build_array(jsonb_build_object('merged_customer_id', v_source_id, 'moved', v_moved));
  end loop;

  set constraints customer_case_attachments_case_owner_fk, customer_case_events_case_owner_fk, customer_contracts_company_customer_customer_site_rel_fkey, customer_contracts_company_customer_site_rel_fkey, customer_info_requests_company_customer_site_rel_fkey, grid_owner_data_requests_company_customer_site_rel_fkey, grid_owner_information_requests_company_customer_site_rel_fkey, metering_points_company_customer_site_rel_fkey, outbound_requests_company_customer_customer_site_rel_fkey, outbound_requests_company_customer_site_rel_fkey, powers_of_attorney_company_customer_customer_site_rel_fkey, powers_of_attorney_company_customer_site_rel_fkey, supplier_switch_requests_company_customer_customer_site_rel_fke, supplier_switch_requests_company_customer_site_rel_fkey immediate;

  return jsonb_build_object('primary_customer_id', p_primary_customer_id, 'merged', v_results);
end
$_$;

--
-- Name: gridex_new_offer_reference(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_new_offer_reference(p_seed text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select 'offer_'||encode(digest(p_seed||'|contract-offer-reference-v1','sha256'),'hex')
$$;

--
-- Name: gridex_next_application_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_next_application_number(p_company_id uuid) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.gridex_next_document_number(p_company_id, 'application', null);
$$;

--
-- Name: gridex_next_contract_number(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_next_contract_number(p_company_id uuid, p_customer_number text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.gridex_next_document_number(p_company_id, 'contract', p_customer_number);
$$;

--
-- Name: gridex_next_customer_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_next_customer_number(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_prefix text;
  v_existing_next bigint;
  v_number bigint;
begin
  if p_company_id is null then
    raise exception 'company_id is required';
  end if;

  v_prefix := public.gridex_default_customer_number_prefix(p_company_id);

  if v_prefix !~ '^[A-Z0-9]{2,12}$' then
    raise exception 'invalid customer number prefix: %', v_prefix;
  end if;

  select coalesce(max(nullif(substring(customer_number from '([0-9]+)$'), '')::bigint) + 1, 100001)
    into v_existing_next
  from public.customers
  where company_id = p_company_id
    and customer_number is not null;

  insert into public.company_customer_number_sequences(company_id, prefix, next_number)
  values (p_company_id, v_prefix, v_existing_next)
  on conflict (company_id) do nothing;

  update public.company_customer_number_sequences
     set next_number = greatest(next_number, v_existing_next) + 1,
         prefix = v_prefix,
         updated_at = now()
   where company_id = p_company_id
   returning prefix, next_number - 1 into v_prefix, v_number;

  if v_number is null then
    raise exception 'customer number sequence could not be reserved';
  end if;

  return v_prefix || '-' || v_number::text;
end;
$_$;

--
-- Name: FUNCTION gridex_next_customer_number(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_next_customer_number(p_company_id uuid) IS 'Atomically reserves a tenant-scoped customer number using companies.customer_number_prefix and company_customer_number_sequences.';

--
-- Name: gridex_next_document_number(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_next_document_number(p_company_id uuid, p_sequence_key text, p_customer_number text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
  v_number bigint;
  v_padding integer;
  v_customer text;
begin
  if p_company_id is null then
    raise exception 'company_id is required';
  end if;
  if p_sequence_key is null or btrim(p_sequence_key) = '' then
    raise exception 'sequence_key is required';
  end if;

  v_prefix := public.gridex_default_document_prefix(p_company_id, p_sequence_key);

  insert into public.company_number_sequences(company_id, sequence_key, prefix, next_number, padding)
  values (p_company_id, p_sequence_key, v_prefix, 100001, 6)
  on conflict (company_id, sequence_key) do nothing;

  update public.company_number_sequences
     set next_number = next_number + 1,
         updated_at = now()
   where company_id = p_company_id
     and sequence_key = p_sequence_key
   returning next_number - 1, prefix, padding
    into v_number, v_prefix, v_padding;

  if v_number is null then
    raise exception 'could not reserve document number';
  end if;

  v_customer := nullif(regexp_replace(coalesce(p_customer_number, ''), '[^A-Za-z0-9-]', '', 'g'), '');
  if p_sequence_key = 'contract' and v_customer is not null then
    return v_prefix || '-' || v_customer || '-' || lpad(v_number::text, v_padding, '0');
  end if;

  if p_sequence_key = 'application' then
    return v_prefix || '-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(v_number::text, v_padding, '0');
  end if;

  return v_prefix || '-' || lpad(v_number::text, v_padding, '0');
end;
$$;

--
-- Name: gridex_normalize_actor_identifier(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_actor_identifier(p_identifier_type text, p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_value is null then null
    when lower(coalesce(p_identifier_type, '')) in ('orgno','org_number','orgnr','organization_number') then nullif(regexp_replace(p_value, '\D', '', 'g'), '')
    when lower(coalesce(p_identifier_type, '')) in ('email','smtp','smtp_email','communication_address') then nullif(lower(btrim(p_value)), '')
    when lower(coalesce(p_identifier_type, '')) in ('subaddress','sub_address') then nullif(btrim(p_value), '')
    else nullif(upper(btrim(p_value)), '')
  end
$$;

