--
-- Name: gridex_normalize_grid_owner_information_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_grid_owner_information_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_dot integer;
  v_outbox record;
begin
  if new.request_type in ('facility_lookup', 'facility_identifier_lookup', 'metering_point_lookup') then
    new.requested_fields := array[
      'facility_id',
      'metering_point_id',
      'grid_area_code',
      'annual_consumption',
      'metering_method',
      'reporting_frequency',
      'current_supplier'
    ]::text[];
  end if;

  if coalesce(new.template_id, '') <> '' then
    v_dot := strpos(new.template_id, '.');
    if v_dot > 1 then
      new.template_key := left(new.template_id, v_dot - 1);
      new.template_version := substr(new.template_id, v_dot + 1);
    end if;
  end if;

  if new.id is not null and (new.rendered_subject is null or new.rendered_body_hash is null) then
    select o.subject, o.body_text, o.body_html
      into v_outbox
    from public.manual_email_outbox o
    where o.company_id = new.company_id
      and o.request_id = new.id
    order by o.created_at desc
    limit 1;

    if found then
      new.rendered_subject := coalesce(new.rendered_subject, v_outbox.subject);
      new.rendered_body_hash := coalesce(
        new.rendered_body_hash,
        encode(
          extensions.digest(coalesce(v_outbox.body_text, v_outbox.body_html, ''), 'sha256'),
          'hex'
        )
      );
    end if;
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_normalize_grid_owner_information_request(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_normalize_grid_owner_information_request() IS 'Enforces technical-only grid-owner facility fields and materializes template key/version plus rendered audit evidence.';

