-- Name: gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_customer_contract_signature_request_v1(p_company_id uuid, p_customer_id uuid, p_contract_id uuid, p_token_hash text, p_recipient_email text, p_expires_at timestamp with time zone, p_actor_user_id uuid, p_channel text DEFAULT 'internal'::text) RETURNS jsonb
