    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM public.ediel_require_contract_records_available_v1(p_company_id,p_contract_id);
 RETURN public.gridex_prepare_signature_before_record_retention_v1(p_company_id,p_customer_id,p_contract_id,p_token_hash,p_recipient_email,p_expires_at,p_actor_user_id,p_channel);
END$$;

--
-- Name: gridex_prepare_manual_contract_binding(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_manual_contract_binding(p_company_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_identity uuid := gen_random_uuid();
  v_saved jsonb;
  v_offer_id uuid;
  v_publication_id uuid;
  v_publication public.contract_publication_versions%rowtype;
  v_product public.contract_product_versions%rowtype;
  v_legal public.legal_bundle_versions%rowtype;
begin
  if p_company_id is null then
    raise exception using errcode='22023',message='company_required';
  end if;

  p_payload := coalesce(p_payload,'{}'::jsonb) || jsonb_build_object(
    'name',coalesce(nullif(p_payload->>'name',''),'Kundspecifikt avtal'),
    'slug','one-off-' || replace(v_identity::text,'-',''),
    'status','active',
    'is_active',true,
    'customer_type',coalesce(nullif(p_payload->>'customer_type',''),'both'),
    'contract_type',coalesce(nullif(p_payload->>'contract_type',''),'variable_hourly'),
    'campaign_code',coalesce(nullif(p_payload->>'campaign_code',''),'ONE_OFF'),
    'campaign_version',coalesce(nullif(p_payload->>'campaign_version',''),'v1'),
    'terms_version',coalesce(nullif(p_payload->>'terms_version',''),'canonical')
  );
  p_pricing_snapshot := coalesce(p_pricing_snapshot,'{}'::jsonb) || jsonb_build_object(
    'one_off',true,
    'one_off_identity',v_identity,
    'source_of_truth','price_plan_versions'
  );

  v_saved := public.gridex_upsert_internal_contract_offer(
    p_company_id,null,p_payload,p_pricing_snapshot,p_actor_user_id
  );
  v_offer_id := nullif(v_saved#>>'{offer,id}','')::uuid;
  if v_offer_id is null then
    raise exception using errcode='P0001',message='one_off_offer_creation_failed';
  end if;

  v_publication_id := public.gridex_ensure_internal_contract_publication(
    p_company_id,v_offer_id,p_actor_user_id
  );
  select * into v_publication
  from public.contract_publication_versions
  where id=v_publication_id and status='published' and locked_at is not null;
  if not found then
    raise exception using errcode='23514',message='one_off_publication_not_locked';
  end if;

  select * into v_product
  from public.contract_product_versions
  where id=v_publication.contract_product_version_id and status='approved' and locked_at is not null;
  if not found then
    raise exception using errcode='23514',message='one_off_product_version_not_locked';
  end if;
  select * into v_legal
  from public.legal_bundle_versions
  where id=v_publication.legal_bundle_version_id and status='published' and locked_at is not null;
  if not found or cardinality(v_legal.unresolved_variables)>0 then
    raise exception using errcode='23514',message='one_off_legal_version_not_ready';
  end if;

  update public.contract_offers
  set status='inactive',is_active=false,archived_at=coalesce(archived_at,now()),updated_at=now(),updated_by=p_actor_user_id
  where id=v_offer_id;

  return jsonb_build_object(
    'contract_offer_id',v_offer_id,
    'contract_product_id',v_product.contract_product_id,
    'contract_product_version_id',v_product.id,
    'contract_publication_version_id',v_publication.id,
    'price_plan_id',v_publication.price_plan_id,
    'price_plan_version_id',v_publication.price_plan_version_id,
    'price_book_id',v_publication.price_book_id,
    'legal_bundle_version_id',v_publication.legal_bundle_version_id,
    'offer_reference',v_publication.offer_reference,
    'commercial_snapshot',v_product.commercial_snapshot,
    'legal_snapshot',v_legal.rendered_snapshot,
    'source_of_truth','contract_publication_versions'
  );
end $$;

--
-- Name: gridex_prepare_signature_before_record_retention_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_signature_before_record_retention_v1(p_company_id uuid, p_customer_id uuid, p_contract_id uuid, p_token_hash text, p_recipient_email text, p_expires_at timestamp with time zone, p_actor_user_id uuid, p_channel text DEFAULT 'internal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_contract public.customer_contracts%rowtype;
  v_company public.companies%rowtype;
  v_binding jsonb;
  v_snapshot_id uuid;
  v_snapshot jsonb;
  v_base_components jsonb;
  v_price_components jsonb;
  v_pricing_model text;
  v_request public.customer_contract_signature_requests%rowtype;
  v_event jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.create');

  if p_company_id is null or p_customer_id is null or p_contract_id is null then
    raise exception using errcode='22023',message='signature_request_company_customer_contract_required';
  end if;
  if coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='signature_request_token_hash_invalid';
  end if;
  if nullif(btrim(coalesce(p_recipient_email,'')),'') is null or position('@' in p_recipient_email)=0 then
    raise exception using errcode='22023',message='signature_request_recipient_email_required';
  end if;
  if p_channel not in ('internal','website','partner_api','customer_portal') then
    raise exception using errcode='22023',message='signature_request_channel_invalid';
  end if;
  if p_expires_at is null or p_expires_at <= now() or p_expires_at > now()+interval '14 days' then
    raise exception using errcode='22023',message='signature_request_expiry_invalid';
  end if;

  select * into v_company from public.companies where id=p_company_id for share;
  if not found or not coalesce(v_company.is_active,false) or coalesce(v_company.lifecycle_status,'')<>'active' or v_company.suspended_at is not null then
    raise exception using errcode='55000',message='signature_request_tenant_not_operational';
  end if;

  select * into v_contract
  from public.customer_contracts
  where id=p_contract_id and company_id=p_company_id and customer_id=p_customer_id
  for update;
  if not found then
    raise exception using errcode='P0002',message='signature_request_contract_not_found_for_tenant';
  end if;
  if v_contract.status in ('signed','active','terminated','cancelled','expired') or v_contract.signed_at is not null then
    raise exception using errcode='23514',message='signature_request_contract_already_finalized';
  end if;
  if v_contract.status not in ('draft','pending_signature','signature_failed') then
    raise exception using errcode='23514',message='signature_request_contract_state_invalid';
  end if;

  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null then
    if v_contract.contract_offer_id is not null then
      perform public.gridex_ensure_internal_contract_publication(p_company_id,v_contract.contract_offer_id,p_actor_user_id);
      update public.customer_contracts
      set contract_offer_id=v_contract.contract_offer_id,updated_by=p_actor_user_id,updated_at=now()
      where id=v_contract.id and company_id=p_company_id
      returning * into v_contract;
    else
      v_binding:=public.gridex_prepare_manual_contract_binding(
        p_company_id,
        jsonb_strip_nulls(jsonb_build_object(
          'name',v_contract.contract_name,
          'customer_type',(select c.customer_type from public.customers c where c.id=v_contract.customer_id and c.company_id=p_company_id),
          'contract_type',v_contract.contract_type,
          'energy_direction',v_contract.energy_direction,
          'campaign_code',v_contract.campaign_code,
          'campaign_version',v_contract.campaign_version,
          'terms_version',v_contract.terms_version,
          'binding_months',v_contract.binding_months,
          'notice_months',v_contract.notice_months,
          'valid_from',coalesce(v_contract.starts_at::date,current_date),
          'valid_to',v_contract.ends_at::date
        )),
        coalesce(v_contract.price_snapshot,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'contract_type',v_contract.contract_type,
          'energy_direction',v_contract.energy_direction,
          'price_area',v_contract.price_area_used,
          'fixed_price_ore_per_kwh',v_contract.fixed_price_ore_per_kwh,
          'spot_markup_ore_per_kwh',v_contract.spot_markup_ore_per_kwh,
          'variable_fee_ore_per_kwh',v_contract.variable_fee_ore_per_kwh,
          'monthly_fee_sek',v_contract.monthly_fee_sek,
          'invoice_fee_sek',v_contract.invoice_fee_sek,
          'green_fee_mode',v_contract.green_fee_mode,
          'green_fee_value',v_contract.green_fee_value,
          'discount_value',v_contract.discount_value,
          'discount_unit',v_contract.discount_unit,
          'start_fee_sek',v_contract.start_fee_sek,
          'admin_fee_sek',v_contract.admin_fee_sek,
          'break_fee_sek',v_contract.break_fee_sek,
          'vat_rate',v_contract.vat_rate
        )),
        p_actor_user_id
      );
      update public.customer_contracts set
        contract_offer_id=nullif(v_binding->>'contract_offer_id','')::uuid,
        contract_product_id=nullif(v_binding->>'contract_product_id','')::uuid,
        contract_product_version_id=nullif(v_binding->>'contract_product_version_id','')::uuid,
        contract_publication_version_id=nullif(v_binding->>'contract_publication_version_id','')::uuid,
        price_plan_id=nullif(v_binding->>'price_plan_id','')::uuid,
        price_plan_version_id=nullif(v_binding->>'price_plan_version_id','')::uuid,
        price_book_id=nullif(v_binding->>'price_book_id','')::uuid,
        legal_bundle_version_id=nullif(v_binding->>'legal_bundle_version_id','')::uuid,
        offer_reference=v_binding->>'offer_reference',
        commercial_snapshot=coalesce(v_binding->'commercial_snapshot','{}'::jsonb),
        legal_snapshot=coalesce(v_binding->'legal_snapshot','{}'::jsonb),
        updated_by=p_actor_user_id,updated_at=now()
      where id=v_contract.id and company_id=p_company_id
      returning * into v_contract;
    end if;
  end if;

  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null then
    raise exception using errcode='23514',message='signature_request_exact_contract_chain_missing';
  end if;

  if v_contract.contract_price_snapshot_id is null then
    select coalesce(cpv.pricing_model,'spot') into v_pricing_model
    from public.contract_product_versions cpv where cpv.id=v_contract.contract_product_version_id;
    v_base_components:=coalesce(
      v_contract.price_snapshot->'base_price_components_snapshot',
      v_contract.commercial_snapshot->'base_price_components_snapshot',
      v_contract.commercial_snapshot->'base_components',
      '[]'::jsonb
    );
    v_price_components:=coalesce(
      v_contract.price_snapshot->'price_components_snapshot',
      v_contract.commercial_snapshot->'price_components_snapshot',
      v_contract.commercial_snapshot->'price_components',
      '[]'::jsonb
    );
    if jsonb_typeof(v_base_components)<>'array' then v_base_components:='[]'::jsonb; end if;
    if jsonb_typeof(v_price_components)<>'array' then v_price_components:='[]'::jsonb; end if;
    v_snapshot:=jsonb_strip_nulls(coalesce(v_contract.price_snapshot,'{}'::jsonb) || jsonb_build_object(
      'snapshot_schema','gridex_contract_pricing_v7_signed_receipt',
      'source','signature_prepare',
      'company_id',v_contract.company_id,
      'contract_id',v_contract.id,
      'contract_number',v_contract.contract_number,
      'customer_number',v_contract.customer_number,
      'contract_type',v_contract.contract_type,
      'energy_direction',v_contract.energy_direction,
      'price_area',v_contract.price_area_used,
      'fixed_price_ore_per_kwh',v_contract.fixed_price_ore_per_kwh,
      'spot_markup_ore_per_kwh',v_contract.spot_markup_ore_per_kwh,
      'variable_fee_ore_per_kwh',v_contract.variable_fee_ore_per_kwh,
      'monthly_fee_sek',v_contract.monthly_fee_sek,
      'invoice_fee_sek',v_contract.invoice_fee_sek,
      'green_fee_mode',v_contract.green_fee_mode,
      'green_fee_value',v_contract.green_fee_value,
      'discount_value',v_contract.discount_value,
      'discount_unit',v_contract.discount_unit,
      'start_fee_sek',v_contract.start_fee_sek,
      'admin_fee_sek',v_contract.admin_fee_sek,
      'break_fee_sek',v_contract.break_fee_sek,
      'vat_rate',v_contract.vat_rate,
      'binding_months',v_contract.binding_months,
      'notice_months',v_contract.notice_months,
      'starts_at',v_contract.starts_at,
      'ends_at',v_contract.ends_at,
      'offer_reference',v_contract.offer_reference,
      'contract_publication_version_id',v_contract.contract_publication_version_id,
      'contract_product_version_id',v_contract.contract_product_version_id,
      'price_plan_version_id',v_contract.price_plan_version_id,
      'legal_bundle_version_id',v_contract.legal_bundle_version_id,
      'base_price_components_snapshot',v_base_components,
      'price_components_snapshot',v_price_components
    ));
    v_snapshot:=private.gridex_normalize_fixed_area_snapshot_v1(v_snapshot);
    insert into public.contract_price_snapshots(
      company_id,contract_id,customer_id,price_plan_version_id,pricing_model,
      base_price_components_snapshot,price_components_snapshot,snapshot_json,
      valid_from,valid_to,source,contract_number,customer_number,snapshot_hash,
      snapshot_quality,snapshot_schema_version
    ) values(
      p_company_id,v_contract.id,v_contract.customer_id,v_contract.price_plan_version_id,
      coalesce(v_pricing_model,'spot'),v_snapshot->'base_price_components_snapshot',
      coalesce(v_snapshot->'price_components_snapshot','[]'::jsonb),v_snapshot,
      coalesce(v_contract.starts_at::date,current_date),v_contract.ends_at::date,
      'signature_prepare',v_contract.contract_number,v_contract.customer_number,
      encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex'),
      'canonical','gridex_contract_pricing_v7_signed_receipt'
    ) returning id into v_snapshot_id;
    update public.customer_contracts
    set contract_price_snapshot_id=v_snapshot_id,price_snapshot=v_snapshot,updated_by=p_actor_user_id,updated_at=now()
    where id=v_contract.id and company_id=p_company_id
    returning * into v_contract;
  end if;

  if not exists(
    select 1
    from public.contract_publication_versions cpv
    join public.contract_publications cp on cp.id=cpv.contract_publication_id
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id and ta.company_id=p_company_id
    join public.contract_product_versions ctv on ctv.id=cpv.contract_product_version_id
    join public.price_plan_versions ppv on ppv.id=cpv.price_plan_version_id
    join public.legal_bundle_versions lbv on lbv.id=cpv.legal_bundle_version_id
    join public.contract_price_snapshots cps on cps.id=v_contract.contract_price_snapshot_id and cps.contract_id=v_contract.id and cps.company_id=p_company_id
    where cpv.id=v_contract.contract_publication_version_id
      and cpv.contract_product_version_id=v_contract.contract_product_version_id
      and cpv.price_plan_version_id=v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and cpv.status='published' and cpv.locked_at is not null
      and ctv.status='approved' and ctv.locked_at is not null
      and ppv.status in ('published','approved','active') and ppv.locked_at is not null
      and lbv.status='published' and lbv.locked_at is not null and cardinality(lbv.unresolved_variables)=0
      and nullif(cps.snapshot_hash,'') is not null
  ) then
    raise exception using errcode='23514',message='signature_request_exact_locked_chain_invalid';
  end if;
  if not exists(select 1 from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id) then
    raise exception using errcode='23514',message='signature_request_legal_document_set_missing';
  end if;

  if v_contract.status in ('draft','signature_failed') then
    update public.customer_contracts
    set status='pending_signature',lifecycle_stage='agreement_ready',updated_by=p_actor_user_id,updated_at=now()
    where id=v_contract.id and company_id=p_company_id
    returning * into v_contract;
  end if;

  update public.customer_contract_signature_requests
  set revoked_at=now()
  where company_id=p_company_id and customer_contract_id=p_contract_id
    and used_at is null and revoked_at is null;

  insert into public.customer_contract_signature_requests(
    company_id,customer_id,customer_contract_id,token_hash,recipient_email,
    channel,expires_at,created_by,metadata
  ) values(
    p_company_id,p_customer_id,p_contract_id,p_token_hash,lower(btrim(p_recipient_email)),
    p_channel,p_expires_at,p_actor_user_id,
    jsonb_build_object(
      'contract_number',v_contract.contract_number,
      'offer_reference',v_contract.offer_reference,
      'contract_publication_version_id',v_contract.contract_publication_version_id,
      'price_plan_version_id',v_contract.price_plan_version_id,
      'legal_bundle_version_id',v_contract.legal_bundle_version_id,
      'contract_price_snapshot_id',v_contract.contract_price_snapshot_id
    )
  ) returning * into v_request;

  v_event:=public.gridex_record_customer_contract_event_v1(
    p_company_id,v_contract.id,v_contract.customer_id,'signature_requested',now(),
    'Online-signering begärd',
    jsonb_build_object('signature_request_id',v_request.id,'channel',p_channel,'expires_at',p_expires_at),
    p_actor_user_id,null,
    encode(extensions.digest(convert_to((v_request.id::text||':signature_requested'),'UTF8'),'sha256'),'hex')
  );

  return jsonb_build_object(
    'ok',true,
    'request_id',v_request.id,
    'company_id',p_company_id,
    'customer_id',v_contract.customer_id,
    'contract_id',v_contract.id,
    'contract_number',v_contract.contract_number,
    'contract_name',v_contract.contract_name,
    'status',v_contract.status,
    'recipient_email',v_request.recipient_email,
    'expires_at',v_request.expires_at,
    'channel',v_request.channel,
    'offer_reference',v_contract.offer_reference,
    'contract_publication_version_id',v_contract.contract_publication_version_id,
    'price_plan_version_id',v_contract.price_plan_version_id,
    'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_price_snapshot_id',v_contract.contract_price_snapshot_id
  );
end
$_$;

--
-- Name: gridex_prepare_staff_identity_delivery_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_staff_identity_delivery_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE registration jsonb; i public.company_invitations%rowtype; d public.tenant_staff_identity_deliveries%rowtype; actor uuid; payload jsonb; delivery_id uuid;
BEGIN
 registration:=public.gridex_staff_identity_registration_v1(p_command,true);
 i:=public.gridex_staff_identity_invitation_v1(p_command,true);
 SELECT * INTO d FROM public.tenant_staff_identity_deliveries WHERE invitation_id=i.id FOR UPDATE;
 IF FOUND THEN
  IF d.company_id<>i.company_id OR d.api_client_id<>(p_command->>'api_client_id')::uuid OR d.provider_id<>(p_command->>'provider_id')::uuid OR d.local_auth_issuer<>registration->>'auth_issuer'
  THEN RAISE EXCEPTION 'staff_identity_delivery_mismatch' USING ERRCODE='42501'; END IF;
  RETURN d.request_payload||jsonb_build_object('request_hash',d.request_hash);
 END IF;
 IF i.invited_user_id IS NOT NULL OR i.status<>'pending' OR i.token IS NULL
 THEN RAISE EXCEPTION 'staff_identity_existing_actor_requires_explicit_binding' USING ERRCODE='42501'; END IF;
 actor:=gen_random_uuid(); delivery_id:=gen_random_uuid();
 INSERT INTO auth.users(id,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,is_anonymous)
 VALUES(actor,'{}','{}',now(),now(),false);
 -- Contact/display data is explicit invitation data, never a GoTrue credential.
 INSERT INTO public.user_profiles(id,email,full_name,user_status) VALUES(actor,lower(btrim(i.email)),i.full_name,'active');
 INSERT INTO public.tenant_staff_actor_anchors(actor_user_id,company_id,invitation_id) VALUES(actor,i.company_id,i.id);
 payload:=jsonb_build_object('delivery_id',delivery_id,'actor_user_id',actor,'company_id',i.company_id,'api_client_id',(p_command->>'api_client_id')::uuid,
  'provider_id',(p_command->>'provider_id')::uuid,'invitation_id',i.id,'recipient_email',lower(btrim(i.email)),'full_name',i.full_name,
  'auth_issuer',registration->>'auth_issuer','callback_url',(registration->>'origin')||'/auth/invitation?token='||i.token::text);
 INSERT INTO public.tenant_staff_identity_deliveries(id,company_id,api_client_id,provider_id,invitation_id,actor_user_id,local_auth_issuer,recipient_email,request_payload,request_hash)
 VALUES(delivery_id,i.company_id,(p_command->>'api_client_id')::uuid,(p_command->>'provider_id')::uuid,i.id,actor,registration->>'auth_issuer',lower(btrim(i.email)),payload,public.canonical_json_sha256(payload));
 RETURN payload||jsonb_build_object('request_hash',public.canonical_json_sha256(payload));
END $$;

--
-- Name: gridex_prevent_locked_portfolio_price_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prevent_locked_portfolio_price_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.price_plan_version_id is not null and old.locked_at is not null then
    raise exception 'locked_portfolio_monthly_price_immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_prevent_published_legal_text_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prevent_published_legal_text_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'published' then
      raise exception 'Published legal text versions cannot be deleted. Archive by publishing a new version instead.';
    end if;
    return old;
  end if;

  if old.status = 'published' and (
    old.company_id is distinct from new.company_id or
    old.type is distinct from new.type or
    old.version is distinct from new.version or
    old.title is distinct from new.title or
    old.body is distinct from new.body
  ) then
    raise exception 'Published legal text content is immutable. Create a new version instead.';
  end if;

  return new;
end $$;

--
-- Name: gridex_preview_delete_unused_contract(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_business jsonb;
  v_graph jsonb;
  v_counts jsonb;
  v_public_offer_ids uuid[]:='{}'::uuid[];
  v_product_version_ids uuid[]:='{}'::uuid[];
  v_publication_version_ids uuid[]:='{}'::uuid[];
  v_legal_version_ids uuid[]:='{}'::uuid[];
  v_offer_references text[]:='{}'::text[];
  v_quote_count bigint:=0;
  v_backfill_issue_count bigint:=0;
  v_business_total bigint:=0;
  v_unsafe_total bigint:=0;
  v_reason_codes text[]:='{}'::text[];
  v_can_delete boolean:=false;
  v_delete_status_allowed boolean:=false;
  v_public_fk_blockers jsonb;
begin
  select * into o
  from public.contract_offers co
  where co.id=p_offer_id and co.company_id=p_company_id;
  if not found then
    return jsonb_build_object(
      'ok',false,'code','contract_offer_not_found',
      'can_delete',false,'deletable',false,
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_offer','count',0,
        'reason','contract_offer_not_found',
        'message','Avtalet hittades inte för valt bolag.'
      ))
    );
  end if;

  v_business:=public.gridex_contract_business_usage_counts(p_company_id,p_offer_id);
  v_graph:=public.gridex_resolve_contract_lifecycle_graph(p_company_id,p_offer_id);
  if not coalesce((v_graph->>'ok')::boolean,false) then
    return v_graph||jsonb_build_object('can_delete',false,'deletable',false);
  end if;
  v_counts:=coalesce(v_graph->'counts','{}'::jsonb);

  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_public_offer_ids
  from jsonb_array_elements_text(coalesce(v_graph->'public_contract_offer_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_product_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'contract_product_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_publication_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'publication_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_legal_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'legal_bundle_version_ids','[]'::jsonb));

  v_offer_references:=public.gridex_contract_offer_references_v1(
    p_company_id,
    v_public_offer_ids,
    v_product_version_ids,
    v_publication_version_ids
  );

  select count(*) into v_quote_count
  from public.website_contract_quotes q
  where q.company_id=p_company_id and (
    q.contract_product_version_id=any(v_product_version_ids)
    or q.contract_publication_version_id=any(v_publication_version_ids)
    or q.legal_bundle_version_id=any(v_legal_version_ids)
    or q.offer_reference=any(v_offer_references)
  );

  select count(*) into v_backfill_issue_count
  from public.contract_lifecycle_backfill_issues i
  where i.company_id=p_company_id and (
    i.contract_offer_id=p_offer_id
    or i.public_contract_offer_id=any(v_public_offer_ids)
  );

  v_business_total:=coalesce((v_business->>'total')::bigint,0)+v_quote_count;
  v_unsafe_total:=coalesce((v_counts->>'successor_offers')::bigint,0)
    +coalesce((v_counts->>'shared_product_version_references')::bigint,0)
    +coalesce((v_counts->>'shared_legal_version_references')::bigint,0)
    +coalesce((v_counts->>'unsafe_graph_issues')::bigint,0);
  v_delete_status_allowed:=o.lifecycle_status in ('draft','ready');

  if coalesce((v_business->>'customer_contracts')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_CUSTOMER_CONTRACTS'); end if;
  if coalesce((v_business->>'customer_applications')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_ACCEPTED_APPLICATIONS'); end if;
  if coalesce((v_business->>'external_intakes')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_EXTERNAL_INTAKES'); end if;
  if coalesce((v_business->>'binding_price_snapshots')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_BINDING_PRICE_SNAPSHOTS'); end if;
  if coalesce((v_business->>'invoices')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_INVOICES'); end if;
  if coalesce((v_business->>'billing_underlays')::bigint,0)>0 or coalesce((v_business->>'billing_underlay_items')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_BILLING_HISTORY'); end if;
  if coalesce((v_business->>'charge_ledger')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_CHARGE_LEDGER'); end if;
  if coalesce((v_business->>'legal_acceptances')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_LEGAL_ACCEPTANCES'); end if;
  if v_quote_count>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_WEBSITE_QUOTES'); end if;
  if coalesce((v_counts->>'successor_offers')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SUCCESSOR_VERSION'); end if;
  if coalesce((v_counts->>'shared_product_version_references')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SHARED_CANONICAL_VERSION'); end if;
  if coalesce((v_counts->>'shared_legal_version_references')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SHARED_LEGAL_VERSION'); end if;
  if coalesce((v_counts->>'unsafe_graph_issues')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'PUBLICATION_GRAPH_INCONSISTENT'); end if;
  if not v_delete_status_allowed then v_reason_codes:=array_append(v_reason_codes,'PERMANENT_DELETE_REQUIRES_DRAFT'); end if;

  -- Backfill issue rows are technical diagnostics and are deleted before their
  -- referenced public offer. They are reported but never misclassified as
  -- customer/business history.
  v_public_fk_blockers:=public.gridex_fk_reference_blockers(
    'public.public_contract_offers'::regclass,
    v_public_offer_ids,
    array[
      'contract_lifecycle_backfill_issues',
      'contract_publication_versions'
    ]
  );
  if coalesce((v_public_fk_blockers->>'count')::integer,0)>0 then
    v_reason_codes:=array_append(v_reason_codes,'HAS_RESTRICTING_FOREIGN_KEYS');
  end if;

  v_can_delete:=v_delete_status_allowed
    and v_business_total=0
    and v_unsafe_total=0
    and coalesce((v_public_fk_blockers->>'count')::integer,0)=0;

  return jsonb_build_object(
    'ok',true,
    'code',case when v_can_delete then null else 'contract_delete_blocked' end,
    'contract_product_id',o.contract_product_id,
    'can_delete',v_can_delete,
    'deletable',v_can_delete,
    'has_business_usage',v_business_total>0,
    'requires_archive',v_business_total>0 or not v_delete_status_allowed,
    'requires_unpublish',o.lifecycle_status in ('published','paused'),
    'recommended_action',case
      when o.lifecycle_status in ('published','paused') then 'unpublish'
      when o.lifecycle_status in ('closed','expired','archived','superseded') then 'hide_terminal'
      when v_business_total>0 then 'archive'
      when v_unsafe_total>0 then 'repair'
      when v_can_delete then 'delete'
      else 'review'
    end,
    'result_mode',case when v_can_delete then 'delete' else 'archive_only' end,
    'business_blockers',(v_business-'ok'-'total')||jsonb_build_object('website_quotes',v_quote_count),
    'business_references',(v_business-'ok'-'total')||jsonb_build_object('website_quotes',v_quote_count),
    'removable_system_dependencies',jsonb_build_object(
      'public_offers',coalesce((v_counts->>'public_offers')::bigint,0),
      'tenant_assignments',coalesce((v_counts->>'tenant_assignments')::bigint,0),
      'publications',coalesce((v_counts->>'publications')::bigint,0),
      'publication_versions',coalesce((v_counts->>'publication_versions')::bigint,0),
      'legal_bundle_versions',coalesce((v_counts->>'legal_bundle_versions')::bigint,0),
      'backfill_issues',v_backfill_issue_count
    ),
    'system_references',v_counts||jsonb_build_object(
      'website_quotes',v_quote_count,
      'contract_lifecycle_backfill_issues',v_backfill_issue_count
    ),
    'foreign_key_blockers',v_public_fk_blockers,
    'reason_codes',to_jsonb(v_reason_codes),
    'blockers',public.gridex_contract_delete_blocker_details_v1(
      v_reason_codes,v_business,v_quote_count,v_counts,v_public_fk_blockers
    ),
    'lifecycle_status',o.lifecycle_status,
    'canonical_mapping_complete',
      o.contract_product_id is not null and o.contract_product_version_id is not null,
    'legacy_cleanup_supported',true,
    'graph',v_graph
  );
end $$;

--
-- Name: FUNCTION gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid) IS 'Service-only tenant-safe delete preview using the same dependency graph and structured blockers as the commit command.';

--
-- Name: gridex_preview_delete_unused_contract_v2(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.delete_unused'
  );
  return public.gridex_contract_delete_dependency_graph_v2(
    p_company_id,
    p_offer_id
  );
end
$$;

--
-- Name: FUNCTION gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Service-only actor-aware delete preview. The server binds actor and tenant from the authenticated session.';

--
-- Name: gridex_preview_public_contract_backfill_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_public_contract_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_offer_id uuid DEFAULT NULL::uuid, p_publication_version_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT NULL::text) RETURNS TABLE(company_id uuid, external_tenant_reference text, offer_id uuid, offer_reference text, publication_id uuid, publication_version_id uuid, channel text, current_status text, detected_problem text, proposed_action text, safe_to_apply boolean, manual_review_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
with candidates as (
  select diagnostic.*,
    exists(select 1 from public.contract_price_options template
      where template.company_id=diagnostic.company_id
        and template.contract_product_version_id=(select pv.contract_product_version_id
          from public.contract_publication_versions pv
          where pv.id=diagnostic.publication_version_id)
        and template.price_plan_version_id=(select pv.price_plan_version_id
          from public.contract_publication_versions pv
          where pv.id=diagnostic.publication_version_id)
        and template.contract_publication_version_id is null) template_exists,
    exists(select 1 from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
        diagnostic.publication_version_id) snapshot_exists,
    (select count(*)
      from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
        diagnostic.publication_version_id) snapshot_option_count,
    (select count(*)
      from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
          diagnostic.publication_version_id
        and not exists(
          select 1 from public.contract_price_options template
          where template.company_id=snapshot_option.company_id
            and template.contract_product_version_id=
              snapshot_option.contract_product_version_id
            and template.price_plan_version_id=
              snapshot_option.price_plan_version_id
            and template.contract_publication_version_id is null
            and template.option_reference=snapshot_option.option_reference
            and template.option_code=snapshot_option.option_code
        )) template_missing_count,
    (select count(distinct prior.contract_publication_version_id)
      from public.contract_price_options prior
      join public.contract_publication_versions current_version
        on current_version.id=diagnostic.publication_version_id
      where prior.company_id=diagnostic.company_id
        and prior.contract_product_version_id=current_version.contract_product_version_id
        and prior.price_plan_version_id=current_version.price_plan_version_id
        and prior.contract_publication_version_id is not null
        and prior.contract_publication_version_id<>diagnostic.publication_version_id
    ) prior_snapshot_source_count
  from public.canonical_public_contract_diagnostics_v diagnostic
  where (diagnostic.publication_version_id is null
      or diagnostic.publication_version_status in (
        'published','paused','ended','draft','review'))
    and (p_company_id is null or diagnostic.company_id=p_company_id)
    and (p_offer_id is null or diagnostic.source_contract_offer_id=p_offer_id)
    and (p_publication_version_id is null
      or diagnostic.publication_version_id=p_publication_version_id)
    and (p_channel is null or diagnostic.channel=lower(p_channel))
)
select c.company_id,c.external_tenant_reference,
  c.source_contract_offer_id,c.offer_reference,c.publication_id,
  c.publication_version_id,c.channel,
  coalesce(c.publication_version_status,c.channel_state),
  array_to_string(c.blockers,','),
  case
    when c.publication_version_id is null then 'MANUAL_CHANNEL_OR_PUBLICATION_REVIEW'
    when c.price_option_count=0 then 'MATERIALIZE_PRICE_OPTION_SNAPSHOT'
    when c.missing_area_count>0 then 'COMPLETE_AREA_PRICE_RELATIONS'
    when c.template_missing_count>0 and c.snapshot_exists
      then 'RESTORE_TEMPLATE_COPY'
    else 'REFINALIZE_SNAPSHOT_AND_REVISION'
  end,
  (
    c.publication_version_id is not null
    and (c.price_option_count>0 or c.template_exists
      or c.snapshot_exists or c.prior_snapshot_source_count=1)
    and c.legal_ready
    and c.invoice_fee_ready
    and c.assignment_id is not null
    and c.channel_id is not null
    and c.snapshot_source_contract_offer_id=
      c.source_contract_offer_id::text
    and c.duplicate_option_count=0
    and c.supported_areas_valid
    and (c.missing_area_count=0 or c.template_exists)
  ),
  case
    when c.publication_version_id is null then 'PUBLICATION_VERSION_MISSING'
    when c.snapshot_source_contract_offer_id is distinct from
      c.source_contract_offer_id::text
      then 'SOURCE_OFFER_NOT_DETERMINISTIC'
    when c.duplicate_option_count>0
      then 'PRICE_OPTION_DUPLICATES_REQUIRE_REVIEW'
    when not c.supported_areas_valid
      then 'SUPPORTED_PRICE_AREAS_INVALID'
    when not c.legal_ready then 'LEGAL_BUNDLE_NOT_DETERMINISTIC'
    when not c.invoice_fee_ready then 'INVOICE_FEE_CONFIGURATION_MISSING'
    when c.assignment_id is null then 'TENANT_ASSIGNMENT_MISSING'
    when c.channel_id is null then 'CHANNEL_INTENT_NOT_PROVEN'
    when c.missing_area_count>0 and not c.template_exists
      then 'SUPPORTED_AREA_PRICE_SOURCE_MISSING'
    when not (c.price_option_count>0 or c.template_exists
      or c.snapshot_exists or c.prior_snapshot_source_count=1)
      then case when c.prior_snapshot_source_count>1
        then 'PRICE_SOURCE_AMBIGUOUS'
        else 'PRICE_SOURCE_NOT_DETERMINISTIC' end
    else null
  end
from candidates c
where cardinality(c.blockers)>0
   or c.template_missing_count>0
order by c.company_id,c.source_contract_offer_id,c.channel
$$;

--
-- Name: gridex_preview_public_contract_legal_backfill_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_public_contract_legal_backfill_v1(p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(publication_version_id uuid, company_id uuid, category text, safe_to_apply boolean, legal_bundle_version_id uuid, module_count bigint, derivation_method text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select pv.id,assignment.company_id,
    case
      when pv.legal_bundle_version_id is null then 'missing_source'
      when bundle.id is null then 'missing_source'
      when count(document.id)=0 then 'blocked'
      when pv.publication_snapshot->'legal_snapshot'->>'legal_bundle_version_id'=
          pv.legal_bundle_version_id::text
        and pv.publication_snapshot->'legal_snapshot'->>'immutable'='true'
        and jsonb_typeof(
          pv.publication_snapshot->'legal_snapshot'->'module_versions'
        )='array'
        and jsonb_array_length(case
          when jsonb_typeof(
            pv.publication_snapshot->'legal_snapshot'->'module_versions'
          )='array' then
            pv.publication_snapshot->'legal_snapshot'->'module_versions'
          else '[]'::jsonb end
        )=count(document.id)
        and not exists(
          select 1
          from jsonb_array_elements(case
            when jsonb_typeof(
              pv.publication_snapshot->'legal_snapshot'->'module_versions'
            )='array' then
              pv.publication_snapshot->'legal_snapshot'->'module_versions'
            else '[]'::jsonb end
          ) module
          where module->>'legal_bundle_version_id' is distinct from
            pv.legal_bundle_version_id::text
        ) then 'already_valid'
      else 'backfillable'
    end,
    pv.legal_bundle_version_id is not null and bundle.id is not null
      and count(document.id)>0,
    pv.legal_bundle_version_id,count(document.id),
    case when pv.legal_bundle_version_id is not null then
      'exact_locked_bundle_relation' else null end
  from public.contract_publication_versions pv
  join public.contract_publications publication
    on publication.id=pv.contract_publication_id
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  left join public.legal_bundle_versions bundle
    on bundle.id=pv.legal_bundle_version_id
   and bundle.company_id=assignment.company_id
   and bundle.locked_at is not null
  left join public.legal_bundle_version_documents document
    on document.legal_bundle_version_id=bundle.id
  where pv.status in ('published','paused','ended')
    and (p_company_id is null or assignment.company_id=p_company_id)
  group by pv.id,assignment.company_id,bundle.id
$$;

--
-- Name: gridex_price_option_unique_objects_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_price_option_unique_objects_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
with constraint_objects as (
  select
    table_rel.relname table_name,
    constraint_row.conname object_name,
    'constraint'::text object_kind,
    array_agg(attribute_row.attname::text order by key_row.ordinality) columns,
    null::text predicate
  from pg_constraint constraint_row
  join pg_class table_rel on table_rel.oid=constraint_row.conrelid
  join pg_namespace table_ns on table_ns.oid=table_rel.relnamespace
  cross join lateral unnest(constraint_row.conkey)
    with ordinality key_row(attnum,ordinality)
  join pg_attribute attribute_row
    on attribute_row.attrelid=table_rel.oid
   and attribute_row.attnum=key_row.attnum
  where table_ns.nspname='public'
    and table_rel.relname in (
      'contract_price_options','contract_price_option_area_prices'
    )
    and constraint_row.contype in ('p','u')
  group by table_rel.relname,constraint_row.conname
), standalone_indexes as (
  select
    table_rel.relname table_name,
    index_rel.relname object_name,
    'index'::text object_kind,
    array_agg(attribute_row.attname::text order by key_row.ordinality)
      filter(where key_row.ordinality<=index_row.indnkeyatts) columns,
    pg_get_expr(index_row.indpred,index_row.indrelid) predicate
  from pg_index index_row
  join pg_class table_rel on table_rel.oid=index_row.indrelid
  join pg_namespace table_ns on table_ns.oid=table_rel.relnamespace
  join pg_class index_rel on index_rel.oid=index_row.indexrelid
  cross join lateral unnest(index_row.indkey::smallint[])
    with ordinality key_row(attnum,ordinality)
  join pg_attribute attribute_row
    on attribute_row.attrelid=table_rel.oid
   and attribute_row.attnum=key_row.attnum
  where table_ns.nspname='public'
    and table_rel.relname in (
      'contract_price_options','contract_price_option_area_prices'
    )
    and index_row.indisunique
    and not index_row.indisprimary
    and index_row.indexprs is null
    and not exists(
      select 1 from pg_constraint constraint_row
      where constraint_row.conindid=index_row.indexrelid
    )
  group by table_rel.relname,index_rel.relname,index_row.indpred,
    index_row.indrelid
), all_objects as (
  select * from constraint_objects
  union all
  select * from standalone_indexes
)
select coalesce(
  jsonb_agg(
    jsonb_build_object(
      'table',table_name,
      'name',object_name,
      'kind',object_kind,
      'columns',to_jsonb(columns),
      'predicate',predicate
    ) order by table_name,object_kind,object_name
  ),
  '[]'::jsonb
)
from all_objects;
$$;

--
-- Name: gridex_process_ready_supplier_switch_activations(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_process_ready_supplier_switch_activations(p_actor_user_id uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_market_date date := (now() at time zone 'Europe/Stockholm')::date;
  v_row record;
  v_activation jsonb;
  v_status text;
  v_activated integer := 0;
  v_already_completed integer := 0;
  v_waiting integer := 0;
  v_blocked integer := 0;
  v_failed integer := 0;
  v_scanned integer := 0;
  v_failures jsonb := '[]'::jsonb;
  v_activated_customers jsonb := '[]'::jsonb;
begin
  if p_actor_user_id is null then
    raise exception 'supplier_switch_activation_actor_required';
  end if;

  for v_row in
    select
      r.id,
      r.company_id,
      r.customer_id
    from public.supplier_switch_requests r
    where r.status = 'accepted'
      and r.company_id is not null
      and r.inbound_z04_message_id is not null
      and coalesce(r.confirmed_start_date, r.requested_start_date) is not null
      and coalesce(r.confirmed_start_date, r.requested_start_date) <= v_market_date
    order by coalesce(r.confirmed_start_date, r.requested_start_date), r.created_at, r.id
    limit v_limit
  loop
    v_scanned := v_scanned + 1;

    begin
      v_activation := public.gridex_finalize_supplier_switch_activation(
        v_row.company_id,
        v_row.id,
        p_actor_user_id
      );
      v_status := coalesce(v_activation->>'status', 'unknown');

      if v_status = 'activated' then
        v_activated := v_activated + 1;
        if not (v_activated_customers @> jsonb_build_array(v_row.customer_id::text)) then
          v_activated_customers := v_activated_customers || jsonb_build_array(v_row.customer_id::text);
        end if;
      elsif v_status = 'already_completed' then
        v_already_completed := v_already_completed + 1;
      elsif v_status = 'waiting' then
        v_waiting := v_waiting + 1;
      elsif v_status = 'blocked' then
        v_blocked := v_blocked + 1;
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'requestId', v_row.id,
          'companyId', v_row.company_id,
          'code', coalesce(v_activation->>'reason_code', 'supplier_switch_activation_blocked')
        ));
      else
        v_failed := v_failed + 1;
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'requestId', v_row.id,
          'companyId', v_row.company_id,
          'code', coalesce(v_activation->>'reason_code', 'supplier_switch_activation_unexpected_result'),
          'status', v_status
        ));
      end if;
    exception when others then
      v_failed := v_failed + 1;
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'requestId', v_row.id,
        'companyId', v_row.company_id,
        'code', 'supplier_switch_activation_failed',
        'message', sqlerrm
      ));
    end;
  end loop;

  return jsonb_build_object(
    'marketDate', v_market_date,
    'scanned', v_scanned,
    'ready', v_scanned,
    'activated', v_activated,
    'alreadyCompleted', v_already_completed,
    'waiting', v_waiting,
    'blocked', v_blocked,
    'failed', v_failed,
    'failures', v_failures,
    'activatedCustomerIds', v_activated_customers
  );
end;
$$;

--
-- Name: gridex_prodat_variant_from_raw(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prodat_variant_from_raw(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when coalesce(p_raw, '') ~ E'CAV\\+[^'']*Z23' then 'LK'
    when coalesce(p_raw, '') ~ E'CAV\\+[^'']*Z22' then 'L'
    else null
  end
$$;

--
-- Name: gridex_project_terminal_application_continuation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_project_terminal_application_continuation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_application_id uuid;
  v_state text;
  v_public_status text;
  v_next_step text;
  v_reason text;
begin
  if new.job_type <> 'customer_application_continuation'
     or new.status not in ('failed','delivery_uncertain')
     or new.status is not distinct from old.status then
    return new;
  end if;

  begin
    v_application_id := nullif(new.payload ->> 'application_id', '')::uuid;
  exception when others then
    v_application_id := null;
  end;
  if v_application_id is null then return new; end if;

  v_state := 'failed';
  v_public_status := 'failed';
  v_next_step := 'resume_customer_application_continuation';
  v_reason := coalesce(new.last_error_code, new.last_error_message, new.last_error, 'customer_application_continuation_failed');

  update public.customer_application_workflows
  set state = v_state,
      next_action = v_next_step,
      failure_code = v_reason,
      snapshot = coalesce(snapshot, '{}'::jsonb) || jsonb_build_object(
        'terminal_job_id', new.id,
        'terminal_job_status', new.status,
        'terminal_error', v_reason
      ),
      last_job_id = new.id,
      last_transition_at = now(),
      updated_at = now()
  where company_id = new.company_id
    and customer_application_id = v_application_id;

  update public.website_customer_applications
  set status = 'failed',
      next_step = v_next_step,
      response_payload = coalesce(response_payload, '{}'::jsonb) || jsonb_build_object(
        'status', v_public_status,
        'workflow_state', v_state,
        'next_step', v_next_step,
        'blocking_reason', v_reason,
        'automation', jsonb_build_object(
          'status', new.status,
          'error_code', new.last_error_code,
          'error_message', coalesce(new.last_error_message, new.last_error)
        )
      ),
      updated_at = now()
  where id = v_application_id
    and company_id = new.company_id;

  return new;
end;
$$;

--
-- Name: gridex_promote_energy_geodata_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_promote_energy_geodata_version(p_geodata_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_version public.energy_geodata_versions%rowtype;
  v_feature record;
  v_feature_count integer := 0;
  v_now timestamptz := now();
  v_error_detail text;
  v_error_hint text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'energy_geodata_promote_service_role_required' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('energy-geodata:' || p_geodata_version_id::text, 0));

  select *
  into v_version
  from public.energy_geodata_versions
  where id = p_geodata_version_id
  for update;

  if not found then
    raise exception 'energy_geodata_version_not_found' using errcode = 'P0002';
  end if;
  if v_version.status = 'verified' then
    return to_jsonb(v_version);
  end if;
  if v_version.status <> 'importing' or v_version.coverage_status <> 'complete' then
    raise exception 'energy_geodata_version_not_complete' using errcode = '23514';
  end if;

  select count(*)::integer
  into v_feature_count
  from public.energy_geodata_features_staging
  where geodata_version_id = p_geodata_version_id;

  if v_feature_count <= 0 or v_feature_count <> v_version.feature_count then
    raise exception 'energy_geodata_feature_count_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'geodata_version_id', p_geodata_version_id,
              'staged_feature_count', v_feature_count,
              'declared_feature_count', v_version.feature_count
            )::text;
  end if;

  for v_feature in
    select feature_id, properties, geometry_geojson, source_url
    from public.energy_geodata_features_staging
    where geodata_version_id = p_geodata_version_id
    order by feature_id
  loop
    begin
      perform public.gridex_import_grid_area_geojson_feature(
        v_feature.feature_id,
        v_feature.properties,
        v_feature.geometry_geojson,
        v_feature.source_url
      );
    exception when others then
      get stacked diagnostics
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT;
      raise exception 'energy_geodata_feature_promotion_failed'
        using errcode = 'P0001',
              detail = jsonb_build_object(
                'geodata_version_id', p_geodata_version_id,
                'feature_id', v_feature.feature_id,
                'source_error_code', sqlstate,
                'source_error_message', sqlerrm,
                'source_error_detail', v_error_detail,
                'source_error_hint', v_error_hint
              )::text;
    end;

    update public.platform_grid_area_geometries
    set geodata_version_id = p_geodata_version_id,
        is_active = true,
        updated_at = v_now
    where source = 'svk_arcgis'
      and source_feature_id = v_feature.feature_id;
  end loop;

  update public.platform_grid_area_geometries
  set is_active = false,
      updated_at = v_now
  where source = 'svk_arcgis'
    and is_active = true
    and geodata_version_id is distinct from p_geodata_version_id;

  update public.energy_geodata_versions
  set status = 'superseded',
      updated_at = v_now
  where provider = v_version.provider
    and status = 'verified'
    and id <> p_geodata_version_id;

  update public.energy_geodata_versions
  set status = 'verified',
      coverage_status = 'complete',
      verified_at = v_now,
      completed_at = v_now,
      updated_at = v_now
  where id = p_geodata_version_id
  returning * into v_version;

  insert into public.canonical_energy_flow_events(event_type, source, payload, actor_type)
  values (
    'energy_geodata.version.verified',
    'svk_arcgis',
    jsonb_build_object(
      'geodata_version_id', v_version.id,
      'geodata_version', v_version.version_key,
      'feature_count', v_feature_count,
      'verified_at', v_version.verified_at,
      'source_url', v_version.source_url,
      'source_layer_id', v_version.metadata -> 'layer_id'
    ),
    'system'
  );

  return to_jsonb(v_version);
end;
$$;

--
-- Name: gridex_protect_authorization_scope_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_authorization_scope_coverage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Legacy rows may receive their first immutable snapshot once. The boolean
  -- coverage must then equal that snapshot exactly. After the snapshot exists,
  -- neither the snapshot nor any false->true coverage transition is allowed.
  if coalesce(jsonb_array_length(old.signed_scope_snapshot), 0) = 0
     and coalesce(jsonb_array_length(new.signed_scope_snapshot), 0) > 0 then
    if coalesce(new.covers_grid_owner_data, false) is distinct from (new.signed_scope_snapshot ?| array['grid_owner_data','facility_information_lookup','supplier_switch'])
       or coalesce(new.covers_current_supplier_contract, false) is distinct from (new.signed_scope_snapshot ?| array['current_supplier_contract','supplier_switch'])
       or coalesce(new.covers_metering_data, false) is distinct from (new.signed_scope_snapshot ?| array['metering_data','facility_information_lookup']) then
      raise exception 'Authorization coverage must match signed scope snapshot.' using errcode = '55000';
    end if;
    return new;
  end if;
  if old.signed_scope_snapshot is distinct from new.signed_scope_snapshot then
    raise exception 'Authorization signed scope snapshot is immutable.' using errcode = '55000';
  end if;
  if coalesce(new.covers_grid_owner_data, false) and not coalesce(old.covers_grid_owner_data, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  if coalesce(new.covers_current_supplier_contract, false) and not coalesce(old.covers_current_supplier_contract, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  if coalesce(new.covers_metering_data, false) and not coalesce(old.covers_metering_data, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_protect_closed_contract_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_closed_contract_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.lifecycle_status='closed' then
    raise exception using errcode='55000',message='contract_closed_terminal';
  end if;
  return old;
end $$;

--
-- Name: gridex_protect_customer_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_customer_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.customer_number is not null
     and btrim(old.customer_number) <> ''
     and new.customer_number is distinct from old.customer_number then
    raise exception using errcode = '23514', message = 'customer_number_is_permanent';
  end if;
  if (old.customer_number is null or btrim(old.customer_number) = '')
     and (new.customer_number is null or btrim(new.customer_number) = '')
     and new.customer_number is distinct from old.customer_number then
    -- normalize '' -> null noise writes without failing
    new.customer_number := old.customer_number;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_protect_locked_pricing_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_locked_pricing_runs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('app.gridex_pricing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status = 'locked' then
      raise exception 'Locked pricing runs cannot be deleted. Unlock the billing period and use the explicit maintenance path.'
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if old.status = 'locked' then
    raise exception 'Locked pricing runs are immutable. Unlock the billing period via the explicit maintenance path before changing run %.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

--
-- Name: gridex_protect_onboarding_legal_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_onboarding_legal_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'Published onboarding legal snapshots are immutable.' using errcode = '55000';
end;
$$;

--
-- Name: gridex_protect_published_legacy_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_published_legacy_offer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.publication_status='published'
     and coalesce(current_setting('gridex.public_offer_write',true),'')<>'on' then
    raise exception using errcode='55000',message='published_offer_is_immutable_create_new_version';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_protect_sent_invoice_export_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_sent_invoice_export_items() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  protected boolean;
begin
  if coalesce(current_setting('app.gridex_billing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  protected := old.status in ('sent', 'credited');

  if tg_op = 'DELETE' then
    if protected then
      raise exception 'Skickade/krediterade fakturaexportposter kan inte raderas (item %). Skapa kredit eller korrigering i stället.', old.id
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if not protected then
    return new;
  end if;

  -- Block re-send: status must never go back to a sendable state.
  if new.status in ('pending', 'failed', 'failed_retryable') then
    raise exception 'Fakturaexportpost % är redan skickad och kan inte skickas om. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Block financial mutation of a sent invoice.
  if new.amount_ex_vat is distinct from old.amount_ex_vat
     or new.vat_amount is distinct from old.vat_amount
     or new.amount_inc_vat is distinct from old.amount_inc_vat
     or new.rounding_amount is distinct from old.rounding_amount
     or new.request_payload is distinct from old.request_payload
     or new.idempotency_key is distinct from old.idempotency_key
     or new.pricing_run_id is distinct from old.pricing_run_id
     or new.billing_underlay_id is distinct from old.billing_underlay_id
     or new.customer_id is distinct from old.customer_id
  then
    raise exception 'Fakturaexportpost % är skickad och får inte ändras finansiellt. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Provider invoice identity may be set once but never rewritten.
  if old.provider_invoice_guid is not null
     and new.provider_invoice_guid is distinct from old.provider_invoice_guid
  then
    raise exception 'Fakturaexportpost % har redan ett leverantörs-id och det får inte skrivas om.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

--
-- Name: gridex_protect_signed_poa_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_signed_poa_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.signed_scope_snapshot is distinct from new.signed_scope_snapshot then
    raise exception 'Signed power-of-attorney scope snapshot is immutable.' using errcode = '55000';
  end if;
  if old.legal_snapshot_id is not null and old.legal_snapshot_id is distinct from new.legal_snapshot_id then
    raise exception 'Power-of-attorney legal snapshot link is immutable.' using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_provision_tenant_website_client_v1(uuid, text, text, text, text, text[], text[], integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text) RETURNS TABLE(api_client_id uuid, client_created boolean, tenant_reference text, receipt_id uuid, installation_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
declare
  v_environment text := coalesce(nullif(trim(p_environment),''), 'production');
  v_company public.companies%rowtype;
  v_client public.integration_api_clients%rowtype;
  v_active_count integer := 0;
  v_paused_count integer := 0;
  v_created boolean := false;
  v_adopted boolean := false;
  v_receipt_id uuid;
  v_previous_status text;
  v_previous_blockers jsonb;
begin
  if p_company_id is null or p_actor_user_id is null then
    raise exception using errcode='22023', message='TENANT_WEBSITE_PROVISIONING_CONTEXT_REQUIRED';
  end if;
  if v_environment not in ('development','staging','production') then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ENVIRONMENT_INVALID';
  end if;
  if nullif(trim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception using errcode='22023', message='TENANT_WEBSITE_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if coalesce(cardinality(p_scopes),0) = 0 then
    raise exception using errcode='22023', message='TENANT_WEBSITE_SCOPES_REQUIRED';
  end if;
  if coalesce(cardinality(p_allowed_origins),0) = 0 then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ORIGINS_REQUIRED';
  end if;
  if exists (
    select 1
    from unnest(coalesce(p_allowed_origins,'{}'::text[])) origin
    where origin !~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?$'
  ) then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ORIGIN_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':tenant_website:' || v_environment, 0)
  );

  select * into v_company
  from public.companies
  where id = p_company_id
  for update;

  if not found then
    raise exception using errcode='P0002', message='TENANT_NOT_FOUND';
  end if;
  if v_company.status not in ('active','onboarding') then
    raise exception using errcode='23514', message='TENANT_NOT_OPERATIONALLY_READY';
  end if;

  if nullif(trim(coalesce(v_company.external_tenant_reference,'')),'') is null then
    update public.companies
       set external_tenant_reference = 'tenant_' || substr(
             encode(extensions.digest(p_company_id::text,'sha256'),'hex'),
             1,
             36
           ),
           updated_at = now()
     where id = p_company_id
     returning * into v_company;
  end if;

  -- One idempotency key identifies the canonical production installation. A
  -- new explicit provisioning/revalidation run resets proof fields before any
  -- credential is made executable. This prevents a historical completed receipt
  -- from authorizing a changed configuration.
  insert into public.tenant_website_installation_receipts(
    company_id, environment, profile_key, idempotency_key, state,
    tenant_reference, allowed_origins, scopes, readiness_blockers,
    receipt_sha256, failure_code, failure_message, created_by, completed_at
  ) values (
    p_company_id, v_environment, 'tenant_website', trim(p_idempotency_key),
    'company_ready', v_company.external_tenant_reference,
    coalesce(p_allowed_origins,'{}'::text[]), coalesce(p_scopes,'{}'::text[]),
    '[]'::jsonb, null, null, null, p_actor_user_id, null
  )
  on conflict (company_id, environment, profile_key, idempotency_key)
  do update set
    state = 'company_ready',
    tenant_reference = excluded.tenant_reference,
    allowed_origins = excluded.allowed_origins,
    scopes = excluded.scopes,
    readiness_blockers = '[]'::jsonb,
    receipt_sha256 = null,
    failure_code = null,
    failure_message = null,
    completed_at = null,
    updated_at = now()
  returning id into v_receipt_id;

  select count(*)::integer into v_active_count
  from public.integration_api_clients existing
  where existing.company_id = p_company_id
    and existing.profile_key = 'tenant_website'
    and existing.status = 'active'
    and existing.deleted_at is null
    and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
    and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no');

  if v_active_count > 1 then
    update public.tenant_website_installation_receipts
       set state='failed',
           failure_code='DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT',
           failure_message='Explicit duplicate-client repair is required.',
           readiness_blockers=jsonb_build_array(jsonb_build_object(
             'code','duplicate_primary_tenant_website_client',
             'environment',v_environment
           )),
           updated_at=now()
     where id=v_receipt_id;
    raise exception using errcode='23505', message='DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT';
  end if;

  if v_active_count = 1 then
    select * into v_client
    from public.integration_api_clients existing
    where existing.company_id = p_company_id
      and existing.profile_key = 'tenant_website'
      and existing.status = 'active'
      and existing.deleted_at is null
      and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
      and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no')
    for update;

    if v_client.revoked_at is not null then
      update public.tenant_website_installation_receipts
         set state='failed',
             failure_code='TENANT_WEBSITE_ACTIVE_CLIENT_REVOKED',
             failure_message='The selected primary client has revocation evidence and cannot be reused.',
             readiness_blockers=jsonb_build_array(jsonb_build_object('code','api_client_revoked')),
             updated_at=now()
       where id=v_receipt_id;
      raise exception using errcode='23514', message='TENANT_WEBSITE_ACTIVE_CLIENT_REVOKED';
    end if;

    update public.integration_api_clients
       set scopes = (
             select array_agg(distinct scope order by scope)
             from unnest(coalesce(v_client.scopes,'{}'::text[]) || coalesce(p_scopes,'{}'::text[])) expanded(scope)
           ),
           allowed_origins = coalesce(p_allowed_origins,'{}'::text[]),
           rate_limit_per_minute = greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
           profile_key = 'tenant_website',
           launch_ready = false,
           launch_blockers = jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
           metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
             'primary',true,
             'environment',v_environment,
             'provisioning_idempotency_key',trim(p_idempotency_key),
             'provisioning_receipt_id',v_receipt_id,
             'tenant_identity_source','api_key',
             'go_live_flow','canonical_tenant_website_v2'
           ),
           updated_at = now()
     where id = v_client.id
     returning * into v_client;

  else
    select count(*)::integer into v_paused_count
    from public.integration_api_clients existing
    where existing.company_id = p_company_id
      and existing.profile_key = 'tenant_website'
      and existing.status = 'paused'
      and existing.deleted_at is null
      and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
      and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no');

    if v_paused_count > 1 then
      update public.tenant_website_installation_receipts
         set state='failed',
             failure_code='AMBIGUOUS_PAUSED_PRIMARY_TENANT_WEBSITE_CLIENT',
             failure_message='Multiple paused primary clients require explicit operator repair.',
             readiness_blockers=jsonb_build_array(jsonb_build_object(
               'code','ambiguous_paused_primary_tenant_website_client',
               'environment',v_environment
             )),
             updated_at=now()
       where id=v_receipt_id;
      raise exception using errcode='23505', message='AMBIGUOUS_PAUSED_PRIMARY_TENANT_WEBSITE_CLIENT';
    end if;

    if v_paused_count = 1 then
      select * into v_client
      from public.integration_api_clients existing
      where existing.company_id = p_company_id
        and existing.profile_key = 'tenant_website'
        and existing.status = 'paused'
        and existing.deleted_at is null
        and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
        and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no')
      for update;

      v_previous_status := v_client.status;
      v_previous_blockers := coalesce(v_client.launch_blockers,'[]'::jsonb);

      -- Auto-adoption is deliberately narrow. A paused credential may be reused
      -- only when every blocker is one of the canonical-readiness migration/
      -- revalidation blockers and at least one such blocker exists. Manual pause,
      -- revocation, deletion, unknown blocker shapes, or mixed blocker reasons
      -- require explicit operator review.
      if v_client.revoked_at is not null
         or jsonb_typeof(v_previous_blockers) <> 'array'
         or jsonb_array_length(v_previous_blockers) = 0
         or not exists (
           select 1
           from jsonb_array_elements(v_previous_blockers) blocker
           where coalesce(blocker->>'code','') in (
             'canonical_readiness_required',
             'canonical_readiness_revalidation_required',
             'canonical_readiness_revalidation_pending'
           )
         )
         or exists (
           select 1
           from jsonb_array_elements(v_previous_blockers) blocker
           where coalesce(blocker->>'code','') not in (
             'canonical_readiness_required',
             'canonical_readiness_revalidation_required',
             'canonical_readiness_revalidation_pending'
           )
         )
      then
        update public.tenant_website_installation_receipts
           set state='failed',
               failure_code='TENANT_WEBSITE_PAUSED_CLIENT_REQUIRES_OPERATOR_REVIEW',
               failure_message='Paused primary client was not paused solely by canonical readiness migration/revalidation.',
               readiness_blockers=jsonb_build_array(jsonb_build_object(
                 'code','paused_client_requires_operator_review',
                 'api_client_id',v_client.id
               )),
               updated_at=now()
         where id=v_receipt_id;
        raise exception using errcode='23514', message='TENANT_WEBSITE_PAUSED_CLIENT_REQUIRES_OPERATOR_REVIEW';
      end if;

      update public.integration_api_clients
         set status = 'active',
             scopes = (
               select array_agg(distinct scope order by scope)
               from unnest(coalesce(v_client.scopes,'{}'::text[]) || coalesce(p_scopes,'{}'::text[])) expanded(scope)
             ),
             allowed_origins = coalesce(p_allowed_origins,'{}'::text[]),
             rate_limit_per_minute = greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
             profile_key = 'tenant_website',
             launch_ready = false,
             launch_blockers = jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
             metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
               'primary',true,
               'environment',v_environment,
               'provisioning_idempotency_key',trim(p_idempotency_key),
               'provisioning_receipt_id',v_receipt_id,
               'tenant_identity_source','api_key',
               'go_live_flow','canonical_tenant_website_v2',
               'canonical_readiness_adopted_at',now(),
               'canonical_readiness_adopted_by',p_actor_user_id
             ),
             updated_at = now()
       where id = v_client.id
       returning * into v_client;

      v_adopted := true;
    else
      if nullif(trim(coalesce(p_key_prefix,'')),'') is null
         or nullif(trim(coalesce(p_secret_hash,'')),'') is null then
        raise exception using errcode='22023', message='TENANT_WEBSITE_CREDENTIAL_MATERIAL_REQUIRED';
      end if;

      insert into public.integration_api_clients(
        company_id, name, status, key_prefix, secret_hash, scopes,
        allowed_origins, allowed_ips, rate_limit_per_minute, created_by,
        permission_groups, purpose_label, profile_key, launch_ready,
        launch_blockers, metadata
      ) values (
        p_company_id,
        coalesce(nullif(trim(p_client_name),''),'Tenant website integration'),
        'active', trim(p_key_prefix), trim(p_secret_hash),
        coalesce(p_scopes,'{}'::text[]), coalesce(p_allowed_origins,'{}'::text[]),
        '{}'::text[], greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
        p_actor_user_id, '{}'::text[], 'Tenant website', 'tenant_website', false,
        jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
        jsonb_build_object(
          'primary',true,
          'environment',v_environment,
          'provisioning_idempotency_key',trim(p_idempotency_key),
          'provisioning_receipt_id',v_receipt_id,
          'tenant_identity_source','api_key',
          'go_live_flow','canonical_tenant_website_v2',
          'token_display','shown_once_on_create'
        )
      )
      returning * into v_client;
      v_created := true;
    end if;
  end if;

  update public.tenant_website_installation_receipts
     set api_client_id=v_client.id,
         state=case when v_created then 'credential_created' else 'client_ready' end,
         updated_at=now()
   where id=v_receipt_id;

  if v_adopted then
    insert into public.audit_logs(
      company_id, actor_user_id, entity_type, entity_id, action,
      old_values, new_values, metadata
    ) values (
      p_company_id,
      p_actor_user_id,
      'integration_api_client',
      v_client.id,
      'api_client.canonical_readiness_adopted',
      jsonb_build_object(
        'status',v_previous_status,
        'launch_blockers',v_previous_blockers
      ),
      jsonb_build_object(
        'status','active',
        'launch_ready',false,
        'launch_blockers',jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending'))
      ),
      jsonb_build_object(
        'environment',v_environment,
        'receipt_id',v_receipt_id,
        'credential_rotated',false,
        'reason','canonical_readiness_revalidation'
      )
    );
  end if;

  return query select
    v_client.id,
    v_created,
    v_company.external_tenant_reference,
    v_receipt_id,
    case when v_created then 'credential_created' else 'client_ready' end;
end
$_$;

--
-- Name: FUNCTION gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text) IS 'Canonical tenant website go-live/revalidation v2. Safely adopts only canonical-readiness-paused primary clients; manual pause/revocation remains fail-closed.';

--
-- Name: gridex_public_catalog_dependency_revision_trigger_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then
      v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id
      from public.contract_products cp
      where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id
      from public.legal_bundle_versions lb
      where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    else
      v_company_id := null;
  end case;

  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,
      'website',
      tg_table_name || '.' || lower(tg_op),
      v_entity_id
    );
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,
      'api',
      tg_table_name || '.' || lower(tg_op),
      v_entity_id
    );
  end if;

  if tg_op='DELETE' then return old; end if;
  return new;
end
$$;

--
-- Name: gridex_public_contract_offer_forward_link_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_public_contract_offer_forward_link_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.publication_link_repair','on',true);
  if old.contract_publication_version_id is not null
     and old.contract_publication_version_id is distinct from new.contract_publication_version_id then
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=null
    where id=old.contract_publication_version_id
      and legacy_public_contract_offer_id=old.id;
  end if;
  if new.contract_publication_version_id is not null then
    if not exists(
      select 1
      from public.contract_publication_versions cpv
      join public.contract_publications cp on cp.id=cpv.contract_publication_id
      join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
      where cpv.id=new.contract_publication_version_id
        and ta.company_id=new.company_id
        and (new.contract_product_version_id is null or cpv.contract_product_version_id=new.contract_product_version_id)
    ) then
      raise exception using errcode='23514',message='public_offer_forward_publication_link_invalid';
    end if;
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=new.id
    where id=new.contract_publication_version_id
      and legacy_public_contract_offer_id is distinct from new.id;
  end if;
  return new;
end $$;

--
-- Name: gridex_publication_compatibility_link_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_compatibility_link_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_forward_id uuid;
begin
  if new.legacy_public_contract_offer_id is null then return new; end if;
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  select po.company_id,po.contract_publication_version_id
    into v_company_id,v_forward_id
  from public.public_contract_offers po
  where po.id=new.legacy_public_contract_offer_id;
  if not found then
    raise exception using errcode='23503',message='legacy_public_contract_offer_not_found';
  end if;
  if v_forward_id is distinct from new.id then
    raise exception using errcode='23514',message='publication_version_link_mismatch';
  end if;
  if not exists(
    select 1
    from public.contract_publications cp
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
    where cp.id=new.contract_publication_id and ta.company_id=v_company_id
  ) then
    raise exception using errcode='23514',message='publication_company_mismatch';
  end if;
  return new;
end $$;

--
-- Name: gridex_publication_legal_snapshot_json_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_legal_snapshot_json_v1(p_company_id uuid, p_legal_bundle_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'legal_bundle_version_id',bundle.id,
    'status',bundle.status,
    'content_sha256',bundle.content_sha256,
    'immutable',bundle.locked_at is not null,
    'module_versions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',document.id,
        'legal_bundle_version_id',document.legal_bundle_version_id,
        'module_key',document.module_key,
        'title',document.title,
        'version',coalesce(nullif(document.template_version,''),
          bundle.published_at::text,document.created_at::text,document.id::text),
        'published_at',coalesce(bundle.published_at,document.created_at),
        'content_sha256',document.content_sha256,
        'origin',coalesce(nullif(document.origin,''),'canonical_bundle_document')
      ) order by document.sort_order,document.module_key,document.id
      ) from public.legal_bundle_version_documents document
      where document.legal_bundle_version_id=bundle.id
    ),'[]'::jsonb),
    'documents',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',document.id,
        'legal_bundle_version_id',document.legal_bundle_version_id,
        'module_key',document.module_key,
        'title',document.title,
        'version',coalesce(nullif(document.template_version,''),
          bundle.published_at::text,document.created_at::text,document.id::text),
        'published_at',coalesce(bundle.published_at,document.created_at),
        'content_sha256',document.content_sha256,
        'origin',coalesce(nullif(document.origin,''),'canonical_bundle_document')
      ) order by document.sort_order,document.module_key,document.id
      ) from public.legal_bundle_version_documents document
      where document.legal_bundle_version_id=bundle.id
    ),'[]'::jsonb)
  )
  from public.legal_bundle_versions bundle
  where bundle.id=p_legal_bundle_version_id
    and bundle.company_id=p_company_id
    and bundle.locked_at is not null
    and bundle.status in ('published','replaced','archived')
$$;

--
-- Name: gridex_publication_price_options_json_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_price_options_json_v1(p_publication_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
  select coalesce(jsonb_agg(
    jsonb_strip_nulls(jsonb_build_object(
      'price_option_reference',o.option_reference,
      'option_code',o.option_code,
      'customer_name',o.customer_name,
      'price_type',o.contract_type,
      'contract_type',o.contract_type,
      'customer_type',o.customer_type,
      'resolution',coalesce(nullif(o.metadata->>'resolution',''),
        case o.contract_type
          when 'variable_hourly' then 'hourly'
          when 'variable_quarterly' then 'quarterly'
          else 'monthly'
        end),
      'is_default',o.is_default,
      'default',o.is_default,
      'selection_required',o.selection_required,
      'currency',coalesce(nullif(o.metadata->>'currency',''),'SEK'),
      'unit',coalesce(nullif(o.metadata->>'unit',''),'ore_per_kwh'),
      'fixed_price',case when coalesce(o.metadata->>'fixed_price','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'fixed_price')::numeric else null end,
      'markup',case when coalesce(o.metadata->>'markup','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'markup')::numeric else null end,
      'monthly_fee',case when coalesce(o.metadata->>'monthly_fee','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'monthly_fee')::numeric else null end,
      'binding_months',o.binding_months,
      'notice_months',o.notice_months,
      'auto_renew_enabled',o.auto_renew_enabled,
      'renewal_term_months',o.renewal_term_months,
      'valid_from',o.valid_from,
      'valid_to',o.valid_to,
      'earliest_start_date',o.earliest_start_date,
      'latest_start_date',o.latest_start_date,
      'area_prices',coalesce((
        select jsonb_agg(jsonb_build_object(
          'area_price_reference',a.price_row_reference,
          'price_area',a.price_area,
          'energy_price_ore_per_kwh',case when a.unit='sek_per_kwh'
            then a.amount*100 else a.amount end,
          'unit','ore_per_kwh',
          'valid_from',a.valid_from,
          'valid_to',a.valid_to
        ) order by a.price_area)
        from public.contract_price_option_area_prices a
        where a.contract_price_option_id=o.id and a.status='active'
      ),'[]'::jsonb)
    )) order by o.sort_order,o.option_reference
  ),'[]'::jsonb)
  from public.contract_price_options o
  where o.contract_publication_version_id=p_publication_version_id
    and o.status='active'
$_$;

--
-- Name: gridex_publish_contract_channel(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  o public.contract_offers%rowtype;
  v_readiness jsonb;
  v_assignment_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_legal_version_id uuid;
  v_public_offer_id uuid;
  v_snapshot jsonb;
  v_hash text;
  v_offer_reference text;
  v_version integer;
  v_channel text;
  v_billing_model text;
  v_spot_weight numeric;
  v_portfolio_weight numeric;
  v_fixed_weight numeric;
  v_price_areas text[]:='{}'::text[];
begin
  v_channel:=lower(coalesce(p_channel,''));
  if v_channel not in ('internal','website','api','partner','phone') then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','invalid_contract_channel','channel',v_channel,
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'invalid_contract_channel','channel',
        'Kanalen måste vara internal, website, api, partner eller phone.',to_jsonb(v_channel)
      ))
    );
  end if;
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.publish');
  perform public.gridex_assert_contract_permission(p_actor_user_id,'pricing.publish');

  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_offer_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,p_offer_id,
    case when o.lifecycle_status='paused' then 'resume_channel' else 'activate_channel' end,
    v_channel
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_channel_not_ready',
      'channel',v_channel,'lifecycle_status',o.lifecycle_status,
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;
  if o.contract_product_version_id is null or not exists(
    select 1 from public.contract_product_versions pv
    where pv.id=o.contract_product_version_id and pv.status='approved' and pv.locked_at is not null
  ) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_locked',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_version_not_locked','contract_product_version_id',
        'Canonical avtalsversion måste vara approved och låst före kanalaktivering.',
        to_jsonb(o.contract_product_version_id),'contract_product_version',o.contract_product_version_id
      ))
    );
  end if;

  if exists(
    select 1
    from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    join public.contract_publications cp on cp.assignment_id=ta.id and cp.channel=v_channel
    join public.contract_publication_versions cpv
      on cpv.contract_publication_id=cp.id
     and cpv.contract_product_version_id=o.contract_product_version_id
    where ta.company_id=p_company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status='active'
      and ch.channel=v_channel and ch.status='active'
      and cp.status='published' and cpv.status='published'
      and cardinality(public.gridex_validate_publication_graph_v1(cpv.id))=0
      and (ch.valid_from is null or ch.valid_from<=now())
      and (ch.valid_to is null or ch.valid_to>=now())
      and (
        v_channel<>'website'
        or exists(
          select 1 from public.public_contract_offers pco
          where pco.company_id=p_company_id
            and pco.contract_publication_version_id=cpv.id
            and pco.source_contract_offer_id=o.id
            and pco.lifecycle_status='published'
            and pco.publication_status='published'
            and pco.is_public and pco.website_enabled and pco.website_cta_enabled
        )
      )
  ) then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','published','code','contract_channel_already_active',
      'channel',v_channel,'contract_product_id',o.contract_product_id,
      'contract_product_version_id',o.contract_product_version_id,
      'blockers','[]'::jsonb
    );
  end if;

  perform public.gridex_sync_internal_offer_to_canonical(o.id);
  select * into o from public.contract_offers where id=o.id;

  -- The compatibility public-offer row is still consumed by parts of the
  -- website runtime. Derive its presentation fields from the same immutable
  -- commercial snapshot that is locked into the publication version.
  v_billing_model:=coalesce(nullif(o.commercial_snapshot->>'pricing_model',''),o.contract_type);
  v_spot_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'spot_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'spot_weight_percent')::numeric end,
    100
  );
  v_portfolio_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'portfolio_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'portfolio_weight_percent')::numeric end,
    0
  );
  v_fixed_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'fixed_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'fixed_weight_percent')::numeric end,
    0
  );
  select coalesce(array_agg(distinct upper(btrim(area)) order by upper(btrim(area))),'{}'::text[])
  into v_price_areas
  from (
    select value as area
    from jsonb_array_elements_text(
      case when jsonb_typeof(o.commercial_snapshot->'price_areas')='array'
        then o.commercial_snapshot->'price_areas' else '[]'::jsonb end
    )
    where nullif(btrim(value),'') is not null
    union all
    select unnest(cpv.price_areas)
    from public.contract_product_versions cpv
    where cpv.id=o.contract_product_version_id
      and jsonb_array_length(
        case when jsonb_typeof(o.commercial_snapshot->'price_areas')='array'
          then o.commercial_snapshot->'price_areas' else '[]'::jsonb end
      )=0
  ) areas;

  -- Move only the selected channel from older versions in the same product
  -- series. Other channels stay active until separately switched.
  update public.tenant_contract_channels old_channel
  set status='ended',valid_to=coalesce(old_channel.valid_to,now()),updated_at=now()
  from public.tenant_contract_assignments old_assignment
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_channel.assignment_id=old_assignment.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_channel.channel=v_channel
    and old_channel.status in ('active','paused');

  -- Locked publication versions may only move through an explicit lifecycle transition.
  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions old_publication_version
  set status='ended',valid_to=coalesce(old_publication_version.valid_to,now())
  from public.contract_publications old_publication
  join public.tenant_contract_assignments old_assignment on old_assignment.id=old_publication.assignment_id
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_publication_version.contract_publication_id=old_publication.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_publication.channel=v_channel
    and old_publication_version.status='published';

  update public.contract_publications old_publication
  set status='ended',updated_at=now()
  from public.tenant_contract_assignments old_assignment
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_publication.assignment_id=old_assignment.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_publication.channel=v_channel
    and old_publication.status not in ('ended','archived');

  update public.tenant_contract_assignments old_assignment
  set status=case when exists(
        select 1 from public.tenant_contract_channels remaining
        where remaining.assignment_id=old_assignment.id and remaining.status='active'
          and (remaining.valid_from is null or remaining.valid_from<=now())
          and (remaining.valid_to is null or remaining.valid_to>=now())
      ) then 'active' else 'ended' end,
      valid_to=case when exists(
        select 1 from public.tenant_contract_channels remaining
        where remaining.assignment_id=old_assignment.id and remaining.status='active'
          and (remaining.valid_from is null or remaining.valid_from<=now())
          and (remaining.valid_to is null or remaining.valid_to>=now())
      ) then old_assignment.valid_to else coalesce(old_assignment.valid_to,current_date) end,
      updated_at=now()
  from public.contract_product_versions old_version
  where old_version.id=old_assignment.contract_product_version_id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id;

  update public.contract_offers old_offer
  set lifecycle_status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'published' else 'superseded' end,
      status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then 'active' else 'inactive' end,
      is_active=exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ),
      superseded_at=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then old_offer.superseded_at else coalesce(old_offer.superseded_at,now()) end,
      updated_by=p_actor_user_id,updated_at=now()
  where old_offer.company_id=p_company_id
    and old_offer.contract_product_id=o.contract_product_id
    and old_offer.id<>o.id
    and old_offer.lifecycle_status not in ('archived','expired','closed');

  update public.contract_offers
  set lifecycle_status='published',status='active',is_active=true,
      superseded_at=null,updated_by=p_actor_user_id,updated_at=now()
  where id=o.id;
  update public.contract_products set status='active',updated_at=now()
  where id=o.contract_product_id and company_id=p_company_id;

  select id into v_assignment_id
  from public.tenant_contract_assignments
  where company_id=p_company_id and contract_product_version_id=o.contract_product_version_id
  for update;
  if v_assignment_id is null then
    raise exception using errcode='23514',
      message='PUBLICATION_TENANT_NOT_READY';
  end if;

  update public.tenant_contract_assignments
  set website_publication_allowed=website_publication_allowed or v_channel='website',
      internal_sales_allowed=internal_sales_allowed or v_channel='internal',
      status='active',valid_from=o.valid_from,valid_to=o.valid_to,updated_at=now()
  where id=v_assignment_id;

  insert into public.tenant_contract_channels(
    assignment_id,channel,status,valid_from,valid_to,marketing_content,updated_by
  ) values(
    v_assignment_id,v_channel,'active',o.valid_from::timestamptz,o.valid_to::timestamptz,
    jsonb_build_object('name',o.name,'source_contract_offer_id',o.id,'source_of_truth','contract_product_versions'),
    p_actor_user_id
  ) on conflict(assignment_id,channel) do update set
    status='active',valid_from=excluded.valid_from,valid_to=excluded.valid_to,
    marketing_content=excluded.marketing_content,updated_by=excluded.updated_by,updated_at=now();

  select legal_bundle_version_id into v_legal_version_id
  from public.contract_offers where id=o.id;
  if v_legal_version_id is null then
    raise exception using errcode='23514',
      message='PUBLICATION_LEGAL_BUNDLE_MISSING';
  end if;

  -- A publication root and version remain non-visible while the immutable
  -- child graph is materialized. The surrounding RPC transaction guarantees
  -- that no observer can see an intermediate state.
  insert into public.contract_publications(assignment_id,channel,status,created_by)
  values(v_assignment_id,v_channel,'draft',p_actor_user_id)
  on conflict(assignment_id,channel) do update set status='draft',updated_at=now()
  returning id into v_publication_id;

  select id,offer_reference
    into v_publication_version_id,v_offer_reference
  from public.contract_publication_versions
  where contract_publication_id=v_publication_id
    and contract_product_version_id=o.contract_product_version_id
    and channel=v_channel
    and publication_snapshot->>'source_contract_offer_id'=o.id::text
  order by version_number desc
  limit 1
  for update;

  if v_publication_version_id is null then
    select coalesce(max(version_number),0)+1 into v_version
    from public.contract_publication_versions
    where contract_publication_id=v_publication_id;
    v_offer_reference:=public.gridex_new_offer_reference(
      concat_ws('|',p_company_id::text,o.version_series_id::text,
        o.version_number::text,v_channel)
    );
    v_snapshot:=jsonb_build_object(
      'schema','gridex_contract_publication_v6',
      'company_id',p_company_id,
      'contract_product_id',o.contract_product_id,
      'contract_product_version_id',o.contract_product_version_id,
      'source_contract_offer_id',o.id,
      'channel',v_channel,
      'offer_reference',v_offer_reference,
      'commercial_snapshot',o.commercial_snapshot,
      'legal_bundle_version_id',v_legal_version_id,
      'price_options','[]'::jsonb,
      'valid_from',o.valid_from,
      'valid_to',o.valid_to
    );
    v_hash:=encode(extensions.digest(v_snapshot::text,'sha256'),'hex');
    insert into public.contract_publication_versions(
      contract_publication_id,version_number,contract_product_version_id,
      price_plan_id,price_plan_version_id,price_book_id,legal_bundle_version_id,
      customer_type,channel,valid_from,valid_to,publication_snapshot,
      offer_reference,content_sha256,status,published_at,locked_at,created_by
    ) values(
      v_publication_id,v_version,o.contract_product_version_id,
      o.price_plan_id,o.price_plan_version_id,o.price_book_id,v_legal_version_id,
      o.customer_type,v_channel,o.valid_from::timestamptz,o.valid_to::timestamptz,
      v_snapshot,v_offer_reference,v_hash,'draft',null,null,p_actor_user_id
    ) returning id into v_publication_version_id;
  else
    perform set_config('gridex.version_transition','on',true);
    update public.contract_publication_versions
    set status='draft',valid_from=o.valid_from::timestamptz,
        valid_to=o.valid_to::timestamptz
    where id=v_publication_version_id;
  end if;

  perform public.gridex_finalize_contract_publication_v1(
    v_publication_version_id,p_actor_user_id,true
  );
  select publication_snapshot,content_sha256,offer_reference
    into v_snapshot,v_hash,v_offer_reference
  from public.contract_publication_versions
  where id=v_publication_version_id;

  update public.contract_publications
  set status='published',updated_at=now()
  where id=v_publication_id;

  if v_channel='website' then
    perform set_config('gridex.public_offer_write','on',true);

    -- Only one website offer in a product series may be public. Older public
    -- compatibility rows remain for historic references but are immediately
    -- removed from all public/CTA surfaces.
    update public.public_contract_offers old_public
    set lifecycle_status='superseded',publication_status='unpublished',
        is_public=false,website_enabled=false,website_cta_enabled=false,
        updated_by=p_actor_user_id,updated_at=now()
    where old_public.company_id=p_company_id
      and old_public.contract_product_id=o.contract_product_id
      and old_public.source_contract_offer_id is distinct from o.id
      and (old_public.is_public or old_public.website_enabled or old_public.website_cta_enabled
           or old_public.publication_status='published');

    select id into v_public_offer_id
    from public.public_contract_offers
    where company_id=p_company_id and source_contract_offer_id=o.id
    order by created_at desc limit 1 for update;

    if v_public_offer_id is null then
      insert into public.public_contract_offers(
        company_id,source_contract_offer_id,version_series_id,version_number,
        contract_product_id,contract_product_version_id,contract_publication_version_id,
        legal_bundle_version_id,price_plan_id,price_plan_version_id,price_book_id,
        product_code,offer_code,public_name,public_description,contract_type,billing_model,
        customer_type,monthly_fee_sek,invoice_fee_sek,spot_markup_ore_per_kwh,
        variable_fee_ore_per_kwh,fixed_price_ore_per_kwh,green_fee_mode,green_fee_value,
        start_fee_sek,administration_fee_sek,break_fee_sek,discount_value,discount_unit,
        discount_months,vat_rate,terms_version,binding_months,notice_months,
        spot_weight_percent,portfolio_weight_percent,fixed_weight_percent,price_areas,
        automatic_renewal,power_of_attorney_required,valid_from,valid_to,
        is_public,is_archived,publication_status,lifecycle_status,website_enabled,
        website_cta_enabled,published_at,metadata,created_by,updated_by
      ) values(
        p_company_id,o.id,o.version_series_id,o.version_number,
        o.contract_product_id,o.contract_product_version_id,v_publication_version_id,
        v_legal_version_id,o.price_plan_id,o.price_plan_version_id,o.price_book_id,
        'electricity','contract-'||o.version_series_id::text,o.name,o.description,o.contract_type,
        v_billing_model,o.customer_type,
        o.monthly_fee_sek,o.invoice_fee_sek,o.spot_markup_ore_per_kwh,o.variable_fee_ore_per_kwh,
        o.fixed_price_ore_per_kwh,o.green_fee_mode,o.green_fee_value,o.start_fee_sek,o.admin_fee_sek,
        o.break_fee_sek,o.discount_value,o.discount_unit,o.discount_months,o.vat_rate,o.terms_version,
        o.default_binding_months,o.default_notice_months,
        v_spot_weight,v_portfolio_weight,v_fixed_weight,v_price_areas,
        o.automatic_renewal,o.power_of_attorney_required,o.valid_from,o.valid_to,
        true,false,'published','published',true,true,now(),
        jsonb_build_object('source_of_truth','contract_product_versions','offer_reference',v_offer_reference),
        p_actor_user_id,p_actor_user_id
      ) returning id into v_public_offer_id;
    else
      update public.public_contract_offers set
        contract_product_id=o.contract_product_id,
        contract_product_version_id=o.contract_product_version_id,
        contract_publication_version_id=v_publication_version_id,
        legal_bundle_version_id=v_legal_version_id,
        price_plan_id=o.price_plan_id,price_plan_version_id=o.price_plan_version_id,price_book_id=o.price_book_id,
        public_name=o.name,public_description=o.description,contract_type=o.contract_type,
        billing_model=v_billing_model,customer_type=o.customer_type,
        monthly_fee_sek=o.monthly_fee_sek,invoice_fee_sek=o.invoice_fee_sek,
        spot_markup_ore_per_kwh=o.spot_markup_ore_per_kwh,variable_fee_ore_per_kwh=o.variable_fee_ore_per_kwh,
        fixed_price_ore_per_kwh=o.fixed_price_ore_per_kwh,green_fee_mode=o.green_fee_mode,green_fee_value=o.green_fee_value,
        start_fee_sek=o.start_fee_sek,administration_fee_sek=o.admin_fee_sek,break_fee_sek=o.break_fee_sek,
        discount_value=o.discount_value,discount_unit=o.discount_unit,discount_months=o.discount_months,
        vat_rate=o.vat_rate,terms_version=o.terms_version,binding_months=o.default_binding_months,
        notice_months=o.default_notice_months,
        spot_weight_percent=v_spot_weight,portfolio_weight_percent=v_portfolio_weight,
        fixed_weight_percent=v_fixed_weight,price_areas=v_price_areas,
        automatic_renewal=o.automatic_renewal,
        power_of_attorney_required=o.power_of_attorney_required,valid_from=o.valid_from,valid_to=o.valid_to,
        is_public=true,is_archived=false,publication_status='published',lifecycle_status='published',
        website_enabled=true,website_cta_enabled=true,published_at=coalesce(published_at,now()),archived_at=null,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source_of_truth','contract_product_versions','offer_reference',v_offer_reference),
        updated_by=p_actor_user_id,updated_at=now()
      where id=v_public_offer_id;
    end if;
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=v_public_offer_id
    where id=v_publication_version_id and legacy_public_contract_offer_id is null;
  end if;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(
    p_company_id,p_actor_user_id,'contract_publication_version',v_publication_version_id::text,
    'contract.channel.published',null,v_snapshot,
    jsonb_build_object('offer_id',o.id,'channel',v_channel,'offer_reference',v_offer_reference)
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'mode','published','channel',v_channel,
    'contract_product_id',o.contract_product_id,
    'contract_product_version_id',o.contract_product_version_id,
    'contract_publication_version_id',v_publication_version_id,
    'public_contract_offer_id',v_public_offer_id,
    'offer_reference',v_offer_reference,
    'affected_channels',1,
    'affected_publication_versions',1,
    'affected_public_offers',case when v_channel='website' then 1 else 0 end
  );
end $_$;

--
-- Name: FUNCTION gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) IS 'Canonical channel publication RPC. Final valid_to-qualified source of truth after 20260727030000.';

--
-- Name: contract_publication_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contract_publication_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_publication_id uuid NOT NULL,
    version_number integer NOT NULL,
    contract_product_version_id uuid NOT NULL,
    price_plan_id uuid,
    price_plan_version_id uuid,
    price_book_id uuid,
    legal_bundle_version_id uuid NOT NULL,
    legacy_public_contract_offer_id uuid,
    customer_type text NOT NULL,
    channel text NOT NULL,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    publication_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    offer_reference text,
    content_sha256 text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    locked_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    energy_direction text NOT NULL,
    CONSTRAINT contract_publication_versions_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text]))),
    CONSTRAINT contract_publication_versions_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT contract_publication_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'paused'::text, 'ended'::text, 'archived'::text])))
);

--
-- Name: COLUMN contract_publication_versions.energy_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_publication_versions.energy_direction IS 'Immutable direction copied from the exact published product version.';

--
-- Name: gridex_publish_contract_publication_version(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_publication_version(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS public.contract_publication_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_row public.contract_publication_versions; v_blockers text[]; v_company uuid; v_product uuid;
begin
  select r.blockers,r.company_id,pv.contract_product_id into v_blockers,v_company,v_product
  from public.contract_publication_readiness_v r
  join public.contract_publication_versions x on x.id=r.contract_publication_version_id
  join public.contract_product_versions pv on pv.id=x.contract_product_version_id
  where r.contract_publication_version_id=p_publication_version_id;
  if not found then raise exception 'publication_version_not_found'; end if;
  if coalesce(array_length(v_blockers,1),0)>0 then raise exception 'publication_not_ready:%',array_to_string(v_blockers,','); end if;
  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions oldv set status='ended'
  from public.contract_product_versions oldpv
  where oldv.contract_product_version_id=oldpv.id and oldpv.contract_product_id=v_product and oldv.id<>p_publication_version_id and oldv.status='published';
  update public.tenant_contract_channels ch set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where ch.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and ch.channel='website' and ch.status='active';
  update public.contract_publications p set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where p.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and p.channel='website' and p.status='published';
  update public.contract_publication_versions cpv set status='published',published_at=coalesce(cpv.published_at,now()),locked_at=coalesce(cpv.locked_at,now()),offer_reference=coalesce(cpv.offer_reference,'offer_'||encode(gen_random_bytes(20),'hex'))
  where cpv.id=p_publication_version_id returning * into v_row;
  update public.contract_publications set status='published',updated_at=now() where id=v_row.contract_publication_id;
  update public.tenant_contract_channels ch set status='active',updated_at=now() from public.contract_publications p where p.id=v_row.contract_publication_id and ch.assignment_id=p.assignment_id and ch.channel='website';
  return v_row;
end $$;

--
-- Name: gridex_publish_contract_version(uuid, uuid, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_result jsonb; v_publication_id uuid; v_readiness jsonb; v_message text; v_codes text[];
  v_payload jsonb:=coalesce(p_payload,'{}'::jsonb); v_legal_result jsonb:='{}'::jsonb;
  v_publish boolean; v_correlation_id text; v_audit_metadata jsonb;
  v_profile_status text; v_profile_missing_fields text[]; v_profile_review_required boolean;
  v_error_code text; v_user_message text;
  v_invoice_fee_raw text; v_invoice_fee numeric; v_invoice_fee_readiness jsonb;
begin
  begin
    if p_company_id is null or p_actor_user_id is null then raise exception using errcode='22023',message='company_and_actor_required'; end if;
    v_publish:=coalesce(v_payload->>'publication_status','draft')='published';
    v_correlation_id:=coalesce(nullif(v_payload#>>'{metadata,correlation_id}',''),gen_random_uuid()::text);

    v_invoice_fee_raw:=nullif(btrim(coalesce(v_payload->>'invoice_fee_sek','')),'');
    if v_invoice_fee_raw is not null then
      if replace(v_invoice_fee_raw,',','.') !~ '^[0-9]+([.][0-9]+)?$' then
        raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
      end if;
      v_invoice_fee:=replace(v_invoice_fee_raw,',','.')::numeric;
      if v_invoice_fee<0 then
        raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
      end if;
      v_payload:=jsonb_set(v_payload,'{invoice_fee_sek}',to_jsonb(v_invoice_fee),true);
    end if;
    if v_publish and v_invoice_fee is null then
      raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
    end if;
    v_invoice_fee_readiness:=public.gridex_invoice_fee_readiness(
      coalesce(p_pricing_snapshot,'{}'::jsonb),v_invoice_fee
    );
    if v_publish and coalesce(v_invoice_fee_readiness->>'status','blocked')<>'ready' then
      raise exception using errcode='23514',message='publication_not_ready:'||coalesce(v_invoice_fee_readiness->>'code','invoice_fee_missing');
    end if;

    if v_publish then
      select completeness_status,missing_fields,coalesce(review_required,false)
      into v_profile_status,v_profile_missing_fields,v_profile_review_required
      from public.tenant_legal_profiles where company_id=p_company_id;
      if not found then raise exception using errcode='23514',message='publication_not_ready:tenant_legal_profile_missing'; end if;
      if v_profile_status not in('complete','verified') or v_profile_review_required then
        v_codes:=array_remove(array[
          case when v_profile_status not in('complete','verified') then 'tenant_legal_profile_incomplete' end,
          case when v_profile_review_required then 'tenant_legal_profile_review_required' end
        ],null);
        select v_codes||coalesce(array_agg('missing_legal_profile_field:'||field order by field),'{}')
        into v_codes from unnest(coalesce(v_profile_missing_fields,'{}')) field;
        raise exception using errcode='23514',message='publication_not_ready:'||array_to_string(v_codes,',');
      end if;
    end if;

    v_payload:=jsonb_set(
      v_payload,'{metadata}',coalesce(v_payload->'metadata','{}'::jsonb)||jsonb_build_object(
        'correlation_id',v_correlation_id,
        'publication_command','gridex_publish_contract_version',
        'publication_command_version','2026-07-20.2',
        'legal_source','legal_template_versions'
      ),true
    )-'legal_bundle_id';

    if v_publish then
      v_legal_result:=public.gridex_resolve_or_create_legal_source_bundle(
        p_company_id,v_payload,coalesce(p_pricing_snapshot,'{}'::jsonb),p_actor_user_id
      );
    end if;

    v_result:=public.gridex_upsert_public_contract_offer(
      p_company_id,p_draft_contract_id,p_offer_code,v_payload,coalesce(p_pricing_snapshot,'{}'::jsonb),p_actor_user_id
    );
    v_publication_id:=nullif(v_result->>'contract_publication_version_id','')::uuid;

    if v_publication_id is not null then
      select jsonb_build_object(
        'status',readiness_status,'can_display',can_display,'can_accept_applications',can_accept_applications,
        'blockers',blockers,'display_blockers',display_blockers,'application_blockers',application_blockers,
        'legal_profile_missing_fields',legal_profile_missing_fields,'required_legal_modules',required_legal_modules,
        'included_legal_modules',included_legal_modules
      ) into v_readiness
      from public.contract_publication_readiness_v
      where contract_publication_version_id=v_publication_id;
    end if;

    if v_publish and exists(
      select 1
      from jsonb_array_elements_text(coalesce(v_readiness->'blockers','[]'::jsonb)) blocker
      where blocker in ('invoice_fee_missing','invoice_fee_conflict','invoice_fee_ambiguous')
    ) then
      select coalesce(array_agg(value order by value),'{}'::text[]) into v_codes
      from jsonb_array_elements_text(coalesce(v_readiness->'blockers','[]'::jsonb)) value
      where value in ('invoice_fee_missing','invoice_fee_conflict','invoice_fee_ambiguous');
      raise exception using errcode='23514',message='publication_not_ready:'||array_to_string(v_codes,',');
    end if;

    v_audit_metadata:=jsonb_strip_nulls(jsonb_build_object(
      'correlation_id',v_correlation_id,
      'offer_reference',v_result->>'offer_reference',
      'contract_publication_version_id',v_publication_id,
      'price_plan_id',v_result#>>'{pricing,price_plan_id}',
      'price_plan_version_id',v_result#>>'{pricing,price_plan_version_id}',
      'price_book_id',v_result#>>'{pricing,price_book_id}',
      'pricing_snapshot_sha256',v_result#>>'{pricing,content_sha256}',
      'legal_bundle_version_id',v_result#>>'{offer,legal_bundle_version_id}',
      'legal_source','legal_template_versions',
      'readiness',coalesce(v_readiness,'{}'::jsonb)
    ));

    insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
    values(
      p_company_id,p_actor_user_id,'contract_publication_version',
      coalesce(v_publication_id::text,v_result#>>'{offer,id}',coalesce(p_draft_contract_id::text,'unknown')),
      case when v_publish then 'contract.publication.atomic_published' else 'contract.publication.atomic_draft_saved' end,
      null,v_result,v_audit_metadata
    );

    return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
      'ok',true,'readiness',coalesce(v_readiness,'{}'::jsonb),
      'correlation_id',v_correlation_id,'legal_source','legal_template_versions'
    );
  exception when others then
    v_message:=sqlerrm;
    v_correlation_id:=coalesce(v_correlation_id,gen_random_uuid()::text);
    if v_message like 'publication_not_ready:%' then
      v_error_code:='publication_not_ready'; v_user_message:='Avtalet kan inte publiceras ännu.';
      v_codes:=string_to_array(substring(v_message from length('publication_not_ready:')+1),',');
    elsif v_message like 'legal_requirement_rule_missing:%' then
      v_error_code:='legal_requirement_rule_missing'; v_user_message:='Juridikregler saknas för vald kund- eller avtalstyp.'; v_codes:=array[v_message];
    elsif v_message like 'canonical_legal_template_missing:%' then
      v_error_code:='canonical_legal_template_missing'; v_user_message:='Publicerade juridikmoduler saknas.';
      select coalesce(array_agg('missing_legal_module:'||module_key order by module_key),'{}') into v_codes
      from unnest(string_to_array(substring(v_message from length('canonical_legal_template_missing:')+1),',')) module_key;
    else
      raise;
    end if;

    insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
    values(
      p_company_id,p_actor_user_id,'contract_publication_version',coalesce(p_draft_contract_id::text,'blocked'),
      'contract.publication.atomic_blocked',null,null,
      jsonb_build_object('correlation_id',v_correlation_id,'error_code',v_error_code,'blockers',v_codes,'database_message',v_message)
    );
    return jsonb_build_object('ok',false,'error_code',v_error_code,'message',v_user_message,'blockers',v_codes,'correlation_id',v_correlation_id);
  end;
end $_$;

--
-- Name: FUNCTION gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) IS 'Canonical atomic contract publication command. Pricing, legal, contract version and publication either commit together or roll back together.';

--
-- Name: gridex_publish_internal_contract_version(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_internal_contract_version(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_readiness jsonb;
  v_pricing jsonb;
  v_canonical uuid;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.publish');
  perform public.gridex_assert_contract_permission(p_actor_user_id,'pricing.publish');

  select * into o
  from public.contract_offers
  where id=p_offer_id and company_id=p_company_id
  for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_offer_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;
  if o.lifecycle_status='published' then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','published','code','contract_already_published',
      'offer',to_jsonb(o),'blockers','[]'::jsonb
    );
  end if;
  if o.lifecycle_status not in ('draft','ready','paused') then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_publishable',
      'lifecycle_status',o.lifecycle_status,
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'lifecycle_status_not_publishable','lifecycle_status',
        'Endast draft, ready eller paused kan publiceras som en immutable avtalsversion.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      ))
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,o.id,'publish_version',null
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_publishable',
      'lifecycle_status',o.lifecycle_status,
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;

  -- Pricing promotion can write canonical pricing rows. Keep it inside a
  -- subtransaction so an identity mismatch returns a structured business
  -- result without leaving orphaned price versions or books behind.
  begin
    v_pricing:=public.gridex_create_or_version_contract_pricing(
      p_company_id,o.name,o.contract_type,
      coalesce(o.commercial_snapshot->>'pricing_model',o.contract_type),
      o.customer_type,coalesce(o.commercial_snapshot,'{}'::jsonb)-'lifecycle_status',
      o.valid_from,o.valid_to,true,p_actor_user_id
    );

    if (v_pricing->>'price_plan_version_id')::uuid is distinct from o.price_plan_version_id
       or nullif(v_pricing->>'price_book_id','')::uuid is distinct from o.price_book_id then
      raise exception using
        errcode='P0001',
        message='contract_pricing_identity_changed_during_publish';
    end if;
  exception
    when raise_exception then
      if sqlerrm='contract_pricing_identity_changed_during_publish' then
        return jsonb_build_object(
          'ok',false,'changed',false,'code','contract_pricing_identity_changed_during_publish',
          'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'contract_pricing_identity_changed_during_publish','price_plan_version_id',
            'Publicering försökte byta den immutable prisidentiteten. Skapa en ny avtalsversion i stället.',
            to_jsonb(o.price_plan_version_id),'contract_offer',o.id
          ))
        );
      end if;
      raise;
  end;

  begin
    update public.contract_offers
    set lifecycle_status='published',status='active',is_active=true,
        price_plan_id=(v_pricing->>'price_plan_id')::uuid,
        price_plan_version_id=(v_pricing->>'price_plan_version_id')::uuid,
        price_book_id=nullif(v_pricing->>'price_book_id','')::uuid,
        updated_by=p_actor_user_id,updated_at=now()
    where id=o.id
    returning * into o;

    v_canonical:=public.gridex_sync_internal_offer_to_canonical(o.id);
  exception
    when check_violation then
      if sqlerrm='internal_offer_legal_documents_not_ready' then
        return jsonb_build_object(
          'ok',false,'changed',false,'code','contract_version_not_publishable',
          'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'unresolved_legal_variables','legal_bundle_version_id',
            'Juridikmaterialiseringen innehåller olösta variabler.',null,
            'contract_offer',o.id
          )),
          'readiness',v_readiness
        );
      end if;
      raise;
  end;
  select * into o from public.contract_offers where id=o.id;

  update public.contract_offers predecessor
  set lifecycle_status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'published' else 'superseded' end,
      status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'active' else 'inactive' end,
      is_active=exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>= now())
      ),
      superseded_at=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then predecessor.superseded_at else coalesce(predecessor.superseded_at,now()) end,
      updated_by=p_actor_user_id,updated_at=now()
  where predecessor.company_id=p_company_id
    and predecessor.version_series_id=o.version_series_id
    and predecessor.id<>o.id
    and predecessor.lifecycle_status in ('published','paused','ready','draft');

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_offer',o.id::text,
    'contract.version.published',null,to_jsonb(o),
    jsonb_build_object(
      'version_series_id',o.version_series_id,
      'contract_product_id',o.contract_product_id,
      'contract_product_version_id',v_canonical,
      'price_plan_version_id',o.price_plan_version_id,
      'price_book_id',o.price_book_id,
      'readiness',v_readiness
    )
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'mode','published','code','contract_version_published',
    'offer',to_jsonb(o),
    'contract_product_id',o.contract_product_id,
    'contract_product_version_id',v_canonical,
    'price_plan_version_id',o.price_plan_version_id,
    'price_book_id',o.price_book_id,
    'readiness',v_readiness
  );
end $$;

--
-- Name: FUNCTION gridex_publish_internal_contract_version(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_internal_contract_version(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Readiness-gated immutable version publication. Business blockers are returned as structured JSON.';

--
-- Name: gridex_publish_legal_template_version(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_legal_template_version(p_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.legal_template_versions
  set status='published',reviewed_by=p_actor_user_id,reviewed_at=now(),published_at=now(),locked_at=now()
  where id=p_version_id and status in('draft','review') and locked_at is null;
  if not found then
    if exists(select 1 from public.legal_template_versions where id=p_version_id and status='published' and locked_at is not null) then
      return p_version_id;
    end if;
    raise exception using errcode='55000',message='legal_template_version_not_publishable';
  end if;
  return p_version_id;
end $$;

--
-- Name: gridex_publish_market_price_preview(text, text, text, date, date, timestamp with time zone, numeric, timestamp with time zone, boolean, text, uuid[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_market_price_preview(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_as_of timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_fallback_used boolean DEFAULT false, p_fallback_reason text DEFAULT NULL::text, p_source_summary_ids uuid[] DEFAULT '{}'::uuid[], p_source_checksum text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'market_preview_publish_service_role_required' using errcode='42501';
  end if;
  if upper(coalesce(p_price_area,'')) not in ('SE1','SE2','SE3','SE4')
     or p_reference_period not in ('latest_complete_day','rolling_7_days','rolling_30_days','month_to_date','forecast')
     or p_period_end<p_period_start or p_as_of is null or p_stale_after<=p_as_of
     or p_price_sek_per_kwh is null then
    raise exception 'invalid_market_preview' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_provider))||':'||upper(trim(p_price_area))||':'||p_reference_period,0));
  update public.market_price_previews
  set status='superseded',updated_at=now()
  where provider=lower(trim(p_provider)) and price_area=upper(trim(p_price_area))
    and reference_period=p_reference_period and status='active';
  insert into public.market_price_previews(
    provider,price_area,reference_period,period_start,period_end,as_of,price_sek_per_kwh,
    stale_after,status,fallback_used,fallback_reason,source_summary_ids,source_checksum,metadata,updated_at
  ) values (
    lower(trim(p_provider)),upper(trim(p_price_area)),p_reference_period,p_period_start,p_period_end,p_as_of,p_price_sek_per_kwh,
    p_stale_after,'active',coalesce(p_fallback_used,false),nullif(btrim(p_fallback_reason),''),
    coalesce(p_source_summary_ids,'{}'::uuid[]),p_source_checksum,coalesce(p_metadata,'{}'::jsonb),now()
  ) returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: gridex_publish_market_price_preview_v2(text, text, text, date, date, timestamp with time zone, timestamp with time zone, numeric, timestamp with time zone, integer, integer, boolean, text, uuid[], text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean DEFAULT false, p_fallback_reason text DEFAULT NULL::text, p_source_summary_ids uuid[] DEFAULT '{}'::uuid[], p_source_checksum text DEFAULT NULL::text, p_source_resolution text DEFAULT 'daily'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_active public.market_price_previews%rowtype;
  v_id uuid;
  v_provider text := lower(trim(p_provider));
  v_area text := upper(trim(p_price_area));
  v_now timestamptz := now();
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'market_preview_publish_service_role_required' using errcode='42501';
  end if;
  if v_area not in ('SE1','SE2','SE3','SE4')
     or p_reference_period not in ('latest_complete_day','rolling_7_days','rolling_30_days','month_to_date','forecast')
     or p_period_end < p_period_start
     or p_source_as_of is null
     or p_generated_at is null
     or p_stale_after <= p_generated_at
     or p_price_sek_per_kwh is null
     or p_requested_days is null or p_requested_days <= 0
     or p_included_days is null or p_included_days <= 0 or p_included_days > p_requested_days then
    raise exception 'invalid_market_preview' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_provider||':'||v_area||':'||p_reference_period,0)
  );

  select * into v_active
  from public.market_price_previews m
  where m.provider = v_provider
    and m.price_area = v_area
    and m.reference_period = p_reference_period
    and m.status = 'active'
  for update;

  if found
     and v_active.source_checksum is not distinct from p_source_checksum
     and v_active.source_as_of is not distinct from p_source_as_of
     and v_active.price_sek_per_kwh is not distinct from p_price_sek_per_kwh
     and v_active.period_start = p_period_start
     and v_active.period_end = p_period_end
     and v_active.requested_days is not distinct from p_requested_days
     and v_active.included_days is not distinct from p_included_days
     and v_active.fallback_used is not distinct from coalesce(p_fallback_used,false)
     and v_active.fallback_reason is not distinct from nullif(btrim(p_fallback_reason),'') then
    return jsonb_build_object(
      'created', false,
      'unchanged', true,
      'preview_id', v_active.id,
      'source_checksum', v_active.source_checksum
    );
  end if;

  update public.market_price_previews
  set status='superseded', updated_at=v_now
  where provider=v_provider
    and price_area=v_area
    and reference_period=p_reference_period
    and status='active';

  insert into public.market_price_previews(
    provider,price_area,reference_period,period_start,period_end,
    as_of,source_as_of,generated_at,price_sek_per_kwh,stale_after,
    requested_days,included_days,status,fallback_used,fallback_reason,
    source_summary_ids,source_checksum,source_resolution,metadata,updated_at
  ) values (
    v_provider,v_area,p_reference_period,p_period_start,p_period_end,
    p_source_as_of,p_source_as_of,p_generated_at,p_price_sek_per_kwh,p_stale_after,
    p_requested_days,p_included_days,'active',coalesce(p_fallback_used,false),
    nullif(btrim(p_fallback_reason),''),coalesce(p_source_summary_ids,'{}'::uuid[]),
    p_source_checksum,coalesce(nullif(btrim(p_source_resolution),''),'daily'),
    coalesce(p_metadata,'{}'::jsonb),v_now
  ) returning id into v_id;

  return jsonb_build_object(
    'created', true,
    'unchanged', false,
    'preview_id', v_id,
    'source_checksum', p_source_checksum
  );
end;
$$;

--
-- Name: FUNCTION gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean, p_fallback_reason text, p_source_summary_ids uuid[], p_source_checksum text, p_source_resolution text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean, p_fallback_reason text, p_source_summary_ids uuid[], p_source_checksum text, p_source_resolution text, p_metadata jsonb) IS 'Publishes a canonical market preview idempotently. An unchanged source checksum and unchanged provider evidence never receive artificial freshness. A new source_as_of requires a real provider fetch.';

--
-- Name: gridex_publish_tenant_legal_override(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_tenant_legal_override(p_company_id uuid, p_override_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.tenant_legal_overrides
  set status='published',submitted_at=coalesce(submitted_at,now()),reviewed_at=now(),reviewed_by=p_actor_user_id,locked_at=now()
  where id=p_override_id and company_id=p_company_id and status in('draft','submitted','approved') and locked_at is null;
  if not found then
    if exists(select 1 from public.tenant_legal_overrides where id=p_override_id and company_id=p_company_id and status='published' and locked_at is not null) then
      return p_override_id;
    end if;
    raise exception using errcode='55000',message='tenant_legal_override_not_publishable';
  end if;
  return p_override_id;
end $$;

--
-- Name: gridex_published_website_offer_integrity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_published_website_offer_integrity(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with missing as (
  select cpv.id
  from public.contract_publication_versions cpv
  join public.contract_publications cp on cp.id=cpv.contract_publication_id
  join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
  where ta.company_id=p_company_id
    and cpv.status='published'
    and cp.status='published'
    and cp.channel='website'
    and not exists(
      select 1
      from public.public_contract_offers pco
      where pco.company_id=p_company_id
        and pco.contract_publication_version_id=cpv.id
        and pco.lifecycle_status='published'
        and pco.publication_status='published'
        and pco.is_public=true
        and pco.website_enabled=true
        and pco.website_cta_enabled=true
    )
)
select jsonb_build_object(
  'ready', count(*)=0,
  'missing_count', count(*),
  'missing_publication_version_ids', coalesce(jsonb_agg(id) filter(where id is not null),'[]'::jsonb),
  'source','canonical_runtime_v2'
)
from missing;
$$;

--
-- Name: gridex_queue_billing_export_run(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_queue_billing_export_run(p_company_id uuid, p_export_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_run public.billing_export_runs%rowtype; v_item public.billing_export_run_items%rowtype;
v_partner public.partner_exports%rowtype; v_key text; v_queued integer:=0; v_skipped integer:=0; v_blocked integer:=0;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_export_run_id::text||':queue',0));
  select * into v_run from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  for v_item in select * from public.billing_export_run_items
    where company_id=p_company_id and billing_export_run_id=p_export_run_id order by created_at,id for update
  loop
    if v_item.status not in ('ready','ready_for_retry') then v_blocked:=v_blocked+1; continue; end if;
    if not exists(select 1 from public.billing_export_readiness_v r where r.company_id=p_company_id and r.billing_underlay_id=v_item.billing_underlay_id and r.is_exportable) then
      update public.billing_export_run_items set status='blocked',readiness_status='blocked',export_status='blocked',
        blocker_reasons=coalesce(blocker_reasons,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('code','canonical_export_readiness_failed','severity','blocked')),
        last_error='Canonical exportreadiness blockerar raden.',failed_at=now(),updated_at=now() where id=v_item.id;
      v_blocked:=v_blocked+1; continue;
    end if;
    if v_item.customer_id is null then raise exception using errcode='23514',message='export_item_customer_required'; end if;
    if v_item.export_status in ('queued','sent','acknowledged') then v_skipped:=v_skipped+1; continue; end if;
    v_key:=coalesce(nullif(v_item.idempotency_key,''),'billing-export-run-item:'||v_item.id::text);
    if v_item.partner_export_id is not null then
      select * into v_partner from public.partner_exports
       where id=v_item.partner_export_id and company_id=p_company_id for update;
      if not found then
        select * into v_partner from public.partner_exports
         where company_id=p_company_id and idempotency_key=v_key for update;
      end if;
    else
      select * into v_partner from public.partner_exports
       where company_id=p_company_id and idempotency_key=v_key for update;
    end if;
    if not found then
      insert into public.partner_exports(company_id,customer_id,site_id,metering_point_id,billing_underlay_id,export_kind,target_system,status,
        payload,external_reference,export_batch_key,idempotency_key,adapter_key,payload_version,queued_at,created_by,updated_by)
      values(p_company_id,v_item.customer_id,v_item.site_id,v_item.metering_point_id,v_item.billing_underlay_id,'billing_underlay',v_run.target_system,'queued',
        jsonb_build_object('adapterPayload',v_item.adapter_payload_snapshot,'exportRunId',p_export_run_id,'exportRunItemId',v_item.id)||coalesce(v_item.payload_snapshot,'{}'::jsonb),
        coalesce(v_item.external_reference,'BILLING-'||upper(left(v_item.id::text,8))),p_export_run_id::text,v_key,
        coalesce(v_item.adapter_key,'gridex_billing_partner_v1'),coalesce(v_item.payload_version,'partner_export_v4c'),now(),p_actor_user_id,p_actor_user_id)
      returning * into v_partner;
    else
      update public.partner_exports set status='queued',
        payload=jsonb_build_object('adapterPayload',v_item.adapter_payload_snapshot,'exportRunId',p_export_run_id,'exportRunItemId',v_item.id)||coalesce(v_item.payload_snapshot,'{}'::jsonb),
        queued_at=now(),sent_at=null,failed_at=null,failure_reason=null,response_payload=null,
        updated_at=now(),updated_by=p_actor_user_id where id=v_partner.id returning * into v_partner;
    end if;
    update public.billing_export_run_items set export_status='queued',partner_result_type='none',partner_export_id=v_partner.id,idempotency_key=v_key,
      queued_at=now(),sent_at=null,failed_at=null,last_error=null,updated_at=now() where id=v_item.id;
    v_queued:=v_queued+1;
  end loop;
  perform public.gridex_refresh_billing_export_run(p_company_id,p_export_run_id);
  return jsonb_build_object('queued',v_queued,'skipped',v_skipped,'blocked',v_blocked);
end $$;

--
-- Name: gridex_read_billing_source_values_v1(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_billing_source_values_v1(p_company_id uuid, p_value_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n public.normalized_metering_values%rowtype;s public.ediel_messages%rowtype;b jsonb;result jsonb:='[]';
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_value_ids IS NULL OR cardinality(p_value_ids)>1000 OR array_position(p_value_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'billing_source_scope_required' USING ERRCODE='22023'; END IF;
 PERFORM gridex_billing_source.lock_values_v1(p_company_id,p_value_ids);
 FOR n IN SELECT * FROM public.normalized_metering_values WHERE company_id=p_company_id AND id=ANY(p_value_ids) ORDER BY id LOOP
  b:=gridex_billing_source.basis_v1(p_company_id,n.id);
  SELECT * INTO s FROM public.ediel_messages WHERE id=n.source_message_id AND company_id=p_company_id;
  result:=result||jsonb_build_array(to_jsonb(n)||jsonb_build_object('quantity_kwh',b->'quantityKwh','product_code',CASE WHEN b->'qualified'='true'::jsonb THEN b->'productCode' ELSE to_jsonb(n.product_code) END,'register_code',CASE WHEN b->'qualified'='true'::jsonb THEN b->'registerCode' ELSE to_jsonb(n.register_code) END,'quality_status',CASE WHEN b->'qualified'='true'::jsonb THEN b->'quality' ELSE to_jsonb(n.quality_status) END,
   'billing_source_basis',b,'billing_source_message',CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('id',s.id,'company_id',s.company_id,'message_family',s.message_family,'message_code',s.message_code,'status',s.status) END));
 END LOOP;
 RETURN result;
END $$;

--
-- Name: gridex_read_billing_underlay_source_basis_v1(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_billing_underlay_source_basis_v1(p_company_id uuid, p_underlay_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb:='[]';u public.billing_underlays%rowtype;b gridex_billing_source.underlay_bindings%rowtype;qualified boolean;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_underlay_ids IS NULL OR cardinality(p_underlay_ids)>1000 OR array_position(p_underlay_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'billing_underlay_read_scope_required'; END IF;
 FOR u IN SELECT * FROM public.billing_underlays WHERE company_id=p_company_id AND id=ANY(p_underlay_ids) ORDER BY id LOOP
  SELECT * INTO b FROM gridex_billing_source.underlay_bindings WHERE underlay_id=u.id AND company_id=p_company_id;
  qualified:=true;
  BEGIN PERFORM gridex_billing_source.require_underlay_v1(p_company_id,u.id);
  EXCEPTION WHEN check_violation THEN qualified:=false; END;
  result:=result||jsonb_build_array(jsonb_build_object('id',u.id,'qualified',qualified,'totalKwh',gridex_utilts_binding.canonical_decimal_v2(u.total_kwh::text),'sourceBasisHash',b.source_basis_hash,'correctionRequired',EXISTS(SELECT FROM gridex_billing_source.correction_journal j WHERE j.underlay_id=u.id)));
 END LOOP;
 RETURN result;
END $$;

