    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_user<>'service_role' AND session_user<>'service_role' AND coalesce(current_setting('role',true),'')<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 RETURN gridex_utilts_issuer.read_v1(p_company_id,p_message_id);
END $$;

--
-- Name: gridex_read_webhook_signing_secret_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_webhook_signing_secret_v1(p_company_id uuid, p_subscription_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_secret text;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;

  select secret.decrypted_secret
  into v_secret
  from public.webhook_subscriptions subscription
  join vault.decrypted_secrets secret
    on secret.id::text = subscription.signing_secret_ref
  where subscription.id = p_subscription_id
    and subscription.company_id = p_company_id
    and subscription.status = 'active'
  limit 1;

  return v_secret;
end
$$;

