-- Name: gridex_reaggregate_customer_after_legacy_state_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reaggregate_customer_after_legacy_state_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if pg_trigger_depth() < 2 then
    perform public.gridex_refresh_customer_process_summary(new.company_id,new.id,new.latest_customer_action);
  end if;
  return new;
end;
$$;

--
-- Name: gridex_rebuild_company_analytics_month(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_rebuild_company_analytics_month(p_company_id uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_next date := (date_trunc('month', p_month) + interval '1 month')::date;
  v_run_id uuid;
  v_customers integer;
  v_zones integer;
  v_owners integer;
begin
  if p_company_id is null or p_month is null then
    raise exception 'company_id and month are required' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('company_analytics:' || p_company_id::text || ':' || v_month::text, 0));
  perform public.gridex_rebuild_metering_monthly_consumption(p_company_id, v_month, v_month);

  -- Same rule as the analytics forecast page: latest consumption run covering the month.
  select fr.id into v_run_id
  from public.forecast_runs fr
  where fr.company_id = p_company_id
    and fr.forecast_type = 'consumption'
    and fr.period_start <= v_month
    and fr.period_end >= v_month
  order by fr.created_at desc
  limit 1;

  -- Company totals (customer counts are owned by the portfolio snapshot below).
  insert into public.company_monthly_metrics as cmm (
    company_id, month, total_customers, total_sites, active_sites, total_metering_points,
    active_metering_points, metering_values_received, metering_values_missing,
    requested_metering_values, successful_metering_requests, failed_metering_requests,
    forecast_kwh, actual_kwh, diff_kwh, diff_percent, updated_at
  )
  select p_company_id, v_month,
         (select count(*) from public.customers c where c.company_id = p_company_id),
         (select count(*) from public.customer_sites s where s.company_id = p_company_id),
         (select count(*) from public.customer_sites s where s.company_id = p_company_id and s.status in ('active', 'live', 'ongoing')),
         (select count(*) from public.metering_points mp where mp.company_id = p_company_id),
         (select count(*) from public.metering_points mp where mp.company_id = p_company_id and mp.status in ('active', 'live', 'ongoing')),
         (select coalesce(sum(a.value_count), 0) from public.gridex_analytics_point_month_internal(p_company_id, v_month) a),
         (select count(*) from public.data_quality_issues q
           where q.company_id = p_company_id and q.status = 'open' and q.issue_type = 'missing_metering_values'),
         (select count(*) from public.grid_owner_data_requests g
           where g.company_id = p_company_id and g.created_at >= v_month and g.created_at < v_next),
         (select count(*) from public.grid_owner_data_requests g
           where g.company_id = p_company_id and g.created_at >= v_month and g.created_at < v_next
             and g.status in ('completed', 'received', 'success', 'succeeded', 'done')),
         (select count(*) from public.grid_owner_data_requests g
           where g.company_id = p_company_id and g.created_at >= v_month and g.created_at < v_next
             and g.status in ('failed', 'error', 'rejected', 'blocked')),
         f.forecast_kwh, a.actual_kwh,
         a.actual_kwh - f.forecast_kwh,
         case when f.forecast_kwh <> 0 then (a.actual_kwh - f.forecast_kwh) / f.forecast_kwh * 100 end,
         now()
  from (select coalesce(sum(i.forecast_kwh), 0) as forecast_kwh
        from public.forecast_run_items i
        where i.company_id = p_company_id and i.forecast_run_id = v_run_id
          and i.period_start >= v_month and i.period_start < v_next) f,
       (select coalesce(sum(x.kwh), 0) as actual_kwh from public.gridex_analytics_point_month_internal(p_company_id, v_month) x) a
  on conflict (company_id, month) do update set
    total_customers = excluded.total_customers,
    total_sites = excluded.total_sites,
    active_sites = excluded.active_sites,
    total_metering_points = excluded.total_metering_points,
    active_metering_points = excluded.active_metering_points,
    metering_values_received = excluded.metering_values_received,
    metering_values_missing = excluded.metering_values_missing,
    requested_metering_values = excluded.requested_metering_values,
    successful_metering_requests = excluded.successful_metering_requests,
    failed_metering_requests = excluded.failed_metering_requests,
    forecast_kwh = excluded.forecast_kwh,
    actual_kwh = excluded.actual_kwh,
    diff_kwh = excluded.diff_kwh,
    diff_percent = excluded.diff_percent,
    updated_at = excluded.updated_at;

  -- Per customer (all customers, no cap).
  with sites as (
    select s.customer_id, count(*) as cnt from public.customer_sites s
    where s.company_id = p_company_id group by 1
  ),
  points as (
    select a.customer_id, count(*) as cnt, sum(a.kwh) as kwh from public.gridex_analytics_point_month_internal(p_company_id, v_month) a
    where a.customer_id is not null group by 1
  ),
  fc as (
    select i.customer_id, sum(i.forecast_kwh) as kwh from public.forecast_run_items i
    where i.company_id = p_company_id and i.forecast_run_id = v_run_id
      and i.period_start >= v_month and i.period_start < v_next and i.customer_id is not null
    group by 1
  ),
  rows_upserted as (
    insert into public.customer_monthly_metrics as m (
      company_id, customer_id, month, sites_count, metering_points_count,
      forecast_kwh, actual_kwh, diff_kwh, diff_percent, status, updated_at
    )
    select p_company_id, c.id, v_month, coalesce(s.cnt, 0), coalesce(p.cnt, 0),
           coalesce(f.kwh, 0), coalesce(p.kwh, 0),
           coalesce(p.kwh, 0) - coalesce(f.kwh, 0),
           case when coalesce(f.kwh, 0) <> 0 then (coalesce(p.kwh, 0) - f.kwh) / f.kwh * 100 end,
           c.status, now()
    from public.customers c
    left join sites s on s.customer_id = c.id
    left join points p on p.customer_id = c.id
    left join fc f on f.customer_id = c.id
    where c.company_id = p_company_id
    on conflict (company_id, customer_id, month) do update set
      sites_count = excluded.sites_count,
      metering_points_count = excluded.metering_points_count,
      forecast_kwh = excluded.forecast_kwh,
      actual_kwh = excluded.actual_kwh,
      diff_kwh = excluded.diff_kwh,
      diff_percent = excluded.diff_percent,
      status = excluded.status,
      updated_at = excluded.updated_at
    returning 1
  )
  select count(*) into v_customers from rows_upserted;

  -- Per bidding zone (SE1-SE4).
  with zones as (select unnest(array['SE1', 'SE2', 'SE3', 'SE4']) as zone),
  pts as (
    select a.bidding_zone_code as zone, count(*) as cnt, count(distinct a.customer_id) as customers, sum(a.kwh) as kwh
    from public.gridex_analytics_point_month_internal(p_company_id, v_month) a group by 1
  ),
  sites as (
    select upper(nullif(trim(s.bidding_zone_code), '')) as zone, count(*) as cnt
    from public.customer_sites s where s.company_id = p_company_id group by 1
  ),
  fc as (
    select upper(nullif(trim(i.bidding_zone_code), '')) as zone, sum(i.forecast_kwh) as kwh
    from public.forecast_run_items i
    where i.company_id = p_company_id and i.forecast_run_id = v_run_id
      and i.period_start >= v_month and i.period_start < v_next
    group by 1
  ),
  rows_upserted as (
    insert into public.bidding_zone_monthly_metrics as b (
      company_id, bidding_zone_code, month, customers_count, sites_count, metering_points_count,
      forecast_kwh, actual_kwh, diff_kwh, diff_percent, updated_at
    )
    select p_company_id, z.zone, v_month, coalesce(p.customers, 0), coalesce(s.cnt, 0), coalesce(p.cnt, 0),
           coalesce(f.kwh, 0), coalesce(p.kwh, 0),
           coalesce(p.kwh, 0) - coalesce(f.kwh, 0),
           case when coalesce(f.kwh, 0) <> 0 then (coalesce(p.kwh, 0) - f.kwh) / f.kwh * 100 end,
           now()
    from zones z
    left join pts p on p.zone = z.zone
    left join sites s on s.zone = z.zone
    left join fc f on f.zone = z.zone
    on conflict (company_id, bidding_zone_code, month) do update set
      customers_count = excluded.customers_count,
      sites_count = excluded.sites_count,
      metering_points_count = excluded.metering_points_count,
      forecast_kwh = excluded.forecast_kwh,
      actual_kwh = excluded.actual_kwh,
      diff_kwh = excluded.diff_kwh,
      diff_percent = excluded.diff_percent,
      updated_at = excluded.updated_at
    returning 1
  )
  select count(*) into v_zones from rows_upserted;

  -- Per grid owner.
  with owners as (select g.id from public.grid_owners g where g.company_id = p_company_id),
  pts as (
    select a.grid_owner_id, count(*) as cnt, count(distinct a.customer_id) as customers,
           sum(a.kwh) as kwh, sum(a.value_count) as values_received
    from public.gridex_analytics_point_month_internal(p_company_id, v_month) a where a.grid_owner_id is not null group by 1
  ),
  sites as (
    select s.grid_owner_id, count(*) as cnt from public.customer_sites s
    where s.company_id = p_company_id and s.grid_owner_id is not null group by 1
  ),
  reqs as (
    select g.grid_owner_id, count(*) as requested,
           count(*) filter (where g.status in ('failed', 'error', 'rejected', 'blocked')) as failed
    from public.grid_owner_data_requests g
    where g.company_id = p_company_id and g.grid_owner_id is not null
      and g.created_at >= v_month and g.created_at < v_next
    group by 1
  ),
  fc as (
    select i.grid_owner_id, sum(i.forecast_kwh) as kwh from public.forecast_run_items i
    where i.company_id = p_company_id and i.forecast_run_id = v_run_id
      and i.period_start >= v_month and i.period_start < v_next and i.grid_owner_id is not null
    group by 1
  ),
  missing as (
    select count(*) as cnt from public.data_quality_issues q
    where q.company_id = p_company_id and q.status = 'open' and q.issue_type = 'missing_metering_values'
  ),
  rows_upserted as (
    insert into public.grid_owner_monthly_metrics as g (
      company_id, grid_owner_id, month, customers_count, sites_count, metering_points_count,
      metering_values_requested, metering_values_received, metering_values_missing,
      failed_requests_count, forecast_kwh, actual_kwh, updated_at
    )
    select p_company_id, o.id, v_month, coalesce(p.customers, 0), coalesce(s.cnt, 0), coalesce(p.cnt, 0),
           coalesce(r.requested, 0), coalesce(p.values_received, 0), (select cnt from missing),
           coalesce(r.failed, 0), coalesce(f.kwh, 0), coalesce(p.kwh, 0), now()
    from owners o
    left join pts p on p.grid_owner_id = o.id
    left join sites s on s.grid_owner_id = o.id
    left join reqs r on r.grid_owner_id = o.id
    left join fc f on f.grid_owner_id = o.id
    on conflict (company_id, coalesce(grid_owner_id, '00000000-0000-0000-0000-000000000000'::uuid), month) do update set
      customers_count = excluded.customers_count,
      sites_count = excluded.sites_count,
      metering_points_count = excluded.metering_points_count,
      metering_values_requested = excluded.metering_values_requested,
      metering_values_received = excluded.metering_values_received,
      metering_values_missing = excluded.metering_values_missing,
      failed_requests_count = excluded.failed_requests_count,
      forecast_kwh = excluded.forecast_kwh,
      actual_kwh = excluded.actual_kwh,
      updated_at = excluded.updated_at
    returning 1
  )
  select count(*) into v_owners from rows_upserted;

  perform public.gridex_snapshot_customer_portfolio_month(p_company_id, v_month);

  return jsonb_build_object(
    'month', v_month,
    'forecast_run_id', v_run_id,
    'customers', v_customers,
    'bidding_zones', v_zones,
    'grid_owners', v_owners
  );
end;
$$;

--
-- Name: gridex_rebuild_company_legal_profile(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_rebuild_company_legal_profile(p_company_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_mark_reviewed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company jsonb;
  v_defaults jsonb;
  v_existing public.tenant_legal_profiles%rowtype;
  v_profile public.tenant_legal_profiles%rowtype;
  v_changed boolean := true;
  v_now timestamptz := now();
begin
  if coalesce(p_mark_reviewed, false) then
    raise exception using errcode = '42501', message = 'direct_legal_review_not_allowed_use_gridex_review_company_legal_profile';
  end if;

  select to_jsonb(c) into v_company
  from public.companies c
  where c.id = p_company_id
  for update;
  if v_company is null then
    raise exception using errcode = 'P0002', message = 'company_not_found';
  end if;

  v_defaults := public.gridex_company_legal_profile_defaults(v_company);
  select * into v_existing
  from public.tenant_legal_profiles
  where company_id = p_company_id;
  if found then
    v_changed := v_existing.source_company_snapshot_sha256 is distinct from v_defaults->>'source_company_snapshot_sha256';
  end if;

  insert into public.tenant_legal_profiles(
    company_id, legal_name, organization_number, postal_address, customer_service_address,
    customer_service_email, phone, website, customer_service_contact, complaints_contact,
    data_protection_contact, billing_information, dispute_resolution_information,
    source_company_snapshot, source_company_snapshot_sha256, source_company_updated_at,
    review_required, last_synced_at, last_synced_by
  ) values (
    p_company_id, v_defaults->>'legal_name', v_defaults->>'organization_number', v_defaults->'postal_address', v_defaults->'customer_service_address',
    v_defaults->>'customer_service_email', v_defaults->>'phone', v_defaults->>'website', v_defaults->'customer_service_contact', v_defaults->'complaints_contact',
    v_defaults->'data_protection_contact', v_defaults->'billing_information', v_defaults->'dispute_resolution_information',
    v_defaults->'source_company_snapshot', v_defaults->>'source_company_snapshot_sha256', v_now,
    false, v_now, p_actor_user_id
  )
  on conflict (company_id) do update set
    legal_name = excluded.legal_name,
    organization_number = excluded.organization_number,
    postal_address = excluded.postal_address,
    customer_service_address = excluded.customer_service_address,
    customer_service_email = excluded.customer_service_email,
    phone = excluded.phone,
    website = excluded.website,
    customer_service_contact = excluded.customer_service_contact,
    complaints_contact = excluded.complaints_contact,
    data_protection_contact = excluded.data_protection_contact,
    billing_information = excluded.billing_information,
    dispute_resolution_information = excluded.dispute_resolution_information,
    source_company_snapshot = excluded.source_company_snapshot,
    source_company_snapshot_sha256 = excluded.source_company_snapshot_sha256,
    source_company_updated_at = v_now,
    last_synced_at = v_now,
    last_synced_by = p_actor_user_id;

  select * into v_profile
  from public.tenant_legal_profiles
  where company_id = p_company_id;

  if coalesce(array_length(v_profile.missing_fields, 1), 0) > 0 then
    update public.tenant_legal_profiles
    set review_required = false,
        reviewed_at = null,
        reviewed_by = null,
        verified_at = null,
        verified_by = null
    where company_id = p_company_id;
  elsif v_changed then
    update public.tenant_legal_profiles
    set review_required = true,
        reviewed_at = null,
        reviewed_by = null,
        verified_at = null,
        verified_by = null
    where company_id = p_company_id;
  end if;

  select * into v_profile
  from public.tenant_legal_profiles
  where company_id = p_company_id;

  if p_actor_user_id is not null and to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs(
      actor_user_id, company_id, entity_type, entity_id, action, new_values, metadata
    ) values (
      p_actor_user_id,
      p_company_id,
      'tenant_legal_profile',
      p_company_id,
      'COMPANY_LEGAL_PROFILE_REBUILT',
      jsonb_build_object(
        'completeness_status', public.gridex_tenant_legal_profile_readiness_status(v_profile),
        'missing_fields', v_profile.missing_fields,
        'review_required', v_profile.review_required,
        'source_sha256', v_profile.source_company_snapshot_sha256
      ),
      jsonb_build_object('canonical_source', 'companies', 'atomic', true, 'review_operation', false)
    );
  end if;

  return jsonb_build_object(
    'company_id', p_company_id,
    'company_name', v_company->>'name',
    'completeness_status', public.gridex_tenant_legal_profile_readiness_status(v_profile),
    'missing_fields', v_profile.missing_fields,
    'missing_field_details', public.gridex_legal_missing_field_details(p_company_id, v_profile.missing_fields),
    'review_required', v_profile.review_required,
    'reviewed_at', coalesce(v_profile.reviewed_at, v_profile.verified_at),
    'updated_at', v_profile.updated_at
  );
end
$$;

--
-- Name: gridex_rebuild_metering_monthly_consumption(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_rebuild_metering_monthly_consumption(p_company_id uuid, p_from_month date, p_to_month date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_from date := date_trunc('month', p_from_month)::date;
  v_to date := date_trunc('month', p_to_month)::date;
  v_rows integer;
begin
  if p_company_id is null or p_from_month is null or p_to_month is null or v_from > v_to or v_to - v_from > 800 then
    raise exception 'Invalid company or month range' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('metering_monthly_consumption:' || p_company_id::text, 0));

  with fresh as (
    select mv.metering_point_id,
           date_trunc('month', mv.period_start)::date as month,
           sum(coalesce(mv.value_kwh, mv.quantity_kwh, mv.quantity)) as kwh,
           count(*)::integer as value_count
    from public.metering_values mv
    where mv.company_id = p_company_id
      and mv.metering_point_id is not null
      and coalesce(mv.is_current, true)
      and coalesce(mv.reading_type, 'consumption') = 'consumption'
      and coalesce(mv.value_kwh, mv.quantity_kwh, mv.quantity) is not null
      and mv.period_start >= v_from
      and mv.period_start < v_to + interval '1 month'
    group by 1, 2
  ),
  upserted as (
    insert into public.metering_point_monthly_consumption as c (company_id, metering_point_id, month, kwh, value_count, computed_at)
    select p_company_id, f.metering_point_id, f.month, f.kwh, f.value_count, now()
    from fresh f
    on conflict (company_id, metering_point_id, month) do update set
      kwh = excluded.kwh,
      value_count = excluded.value_count,
      computed_at = excluded.computed_at
    returning 1
  )
  select count(*) into v_rows from upserted;

  update public.metering_point_monthly_consumption c
     set kwh = 0, value_count = 0, computed_at = now()
   where c.company_id = p_company_id
     and c.month between v_from and v_to
     and c.value_count > 0
     and c.computed_at < now();

  return v_rows;
end;
$$;

--
-- Name: gridex_recalculate_actor_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_recalculate_actor_readiness(p_platform_market_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_grid_updated int := 0;
  v_supplier_updated int := 0;
begin
  update public.grid_owners g
  set verified_for_customer_flow = coalesce(r.can_start_supplier_switch, false),
      supplier_switch_ready = coalesce(r.can_start_supplier_switch, false),
      prodat_ready_for_customer_flow = coalesce(r.can_use_for_prodat, false),
      utilts_ready_for_metering_flow = coalesce(r.can_use_for_utilts, false),
      excluded_from_electricity_scope = coalesce(r.electricity_scope_status = 'excluded_from_electricity_scope', false),
      electricity_scope_status = coalesce(r.electricity_scope_status, 'separate_role_scope'),
      manual_review_required = coalesce(r.manual_review_required, false),
      manual_review_reason = r.manual_review_reason,
      actor_registry_status = case
        when coalesce(r.can_start_supplier_switch, false) then 'verified'
        when r.electricity_scope_status = 'excluded_from_electricity_scope' then 'excluded_from_electricity_scope'
        else 'under_review'
      end,
      verification_status = case
        when r.electricity_scope_status = 'excluded_from_electricity_scope' then 'excluded_from_electricity_scope'
        when coalesce(r.can_start_supplier_switch, false) then 'verified'
        when 'open_blocking_conflicts' = any(r.blocking_reasons) then 'unresolved_duplicate'
        when 'missing_prodat_route' = any(r.blocking_reasons) then 'needs_route'
        when 'missing_or_invalid_certificate' = any(r.blocking_reasons) then 'needs_certificate'
        when 'unsafe_or_missing_subaddress' = any(r.blocking_reasons) then 'needs_subaddress'
        when 'missing_contact_path' = any(r.blocking_reasons) then 'needs_contact'
        when 'missing_ediel_id' = any(r.blocking_reasons) then 'needs_ediel_id'
        else 'unknown'
      end,
      verification_reasons = coalesce(r.blocking_reasons, '{}'::text[]),
      verification_checked_at = now(),
      verified_at = case when coalesce(r.can_start_supplier_switch, false) then coalesce(g.verified_at, now()) else g.verified_at end,
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb) || jsonb_build_object(
        'o6_4_role_aware_readiness_at', now(),
        'electricity_scope_status', r.electricity_scope_status,
        'primary_role_group', r.primary_role_group,
        'manual_review_required', r.manual_review_required,
        'manual_review_reason', r.manual_review_reason
      ),
      updated_at = now()
  from public.actor_readiness_status r
  where g.platform_market_actor_id = r.platform_market_actor_id
    and (p_platform_market_actor_id is null or r.platform_market_actor_id = p_platform_market_actor_id);
  get diagnostics v_grid_updated = row_count;

  if to_regclass('public.electricity_suppliers') is not null then
    update public.electricity_suppliers s
    set verified_for_customer_flow = coalesce(r.can_use_for_prodat, false),
        can_start_supplier_switch = coalesce(r.can_use_for_prodat, false),
        actor_registry_status = case when coalesce(r.can_use_for_prodat, false) then 'verified' else 'under_review' end,
        verification_status = case when coalesce(r.can_use_for_prodat, false) then 'verified' else 'needs_review' end,
        verification_reasons = coalesce(r.blocking_reasons, '{}'::text[]),
        verification_checked_at = now(),
        verification_metadata = coalesce(s.verification_metadata, '{}'::jsonb) || jsonb_build_object('readiness_checked_at', now(), 'o6_4_scope', r.primary_role_group)
    from public.actor_readiness_status r
    where s.platform_market_actor_id = r.platform_market_actor_id
      and (p_platform_market_actor_id is null or r.platform_market_actor_id = p_platform_market_actor_id);
    get diagnostics v_supplier_updated = row_count;
  end if;

  return jsonb_build_object('ok', true, 'grid_owners_updated', v_grid_updated, 'suppliers_updated', v_supplier_updated, 'batch', 'O6.4');
end;
$$;

--
-- Name: gridex_received_source_snapshot_v1(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_received_source_snapshot_v1(p_company_id uuid, p_environment text, p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'received_evidence_service_required' USING ERRCODE='42501'; END IF;
 RETURN gridex_received_sources.open_snapshot(p_company_id,p_environment,p_cutoff);
END $$;

--
-- Name: gridex_reconcile_company_onboarding_tasks_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reconcile_company_onboarding_tasks_v1(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_contract jsonb := '{}'::jsonb;
  v_go_live jsonb := '{}'::jsonb;
  v_api boolean := false;
  v_prod_actor boolean := false;
  v_test_actor boolean := false;
  v_brp boolean := false;
  v_prod_route boolean := false;
  v_test_route boolean := false;
  v_transport boolean := false;
  v_prod_certificate boolean := false;
  v_legal boolean := false;
  v_website boolean := false;
  v_customer_automation boolean := false;
  v_complete_count integer := 0;
begin
  if not exists(select 1 from public.companies where id = p_company_id) then
    raise exception 'tenant_not_found';
  end if;

  perform public.gridex_seed_company_onboarding_tasks(p_company_id);

  v_contract := public.gridex_contract_platform_readiness_internal_v1(p_company_id);
  v_go_live := public.gridex_company_go_live_readiness(p_company_id);

  select exists(
    select 1
    from public.integration_api_clients i
    where i.company_id = p_company_id
      and i.status = 'active'
      and array[
        'integration_context.read',
        'website_contracts.read',
        'website_contracts.diagnostics',
        'website_energy_area.resolve',
        'website_quotes.write',
        'website_quotes.validate',
        'website_applications.write',
        'website_legal.read'
      ]::text[] <@ coalesce(i.scopes, '{}'::text[])
  ) into v_api;

  select exists(
    select 1 from public.ediel_actor_settings a
    where a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
  ) into v_prod_actor;

  select exists(
    select 1 from public.ediel_actor_settings a
    where a.company_id = p_company_id
      and a.environment = 'test'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
  ) into v_test_actor;

  select exists(
    select 1 from public.ediel_brp_settings b
    where b.company_id = p_company_id
      and b.environment = 'production'
      and coalesce(b.is_active, true) = true
      and nullif(btrim(coalesce(b.brp_ediel_id, '')), '') is not null
  ) into v_brp;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'production'
      and a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and upper(coalesce(r.message_family, '')) = 'PRODAT'
  ) into v_prod_route;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'test'
      and a.company_id = p_company_id
      and a.environment = 'test'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
  ) into v_test_route;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    join public.ediel_mailboxes m on m.id = r.mailbox_id
    where r.company_id = p_company_id
      and a.company_id = p_company_id
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and coalesce(m.is_active, false) = true
      and m.environment = r.environment
      and (m.company_id = p_company_id or m.company_id is null)
  ) into v_transport;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'production'
      and a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and upper(coalesce(r.message_family, '')) = 'PRODAT'
      and (
        coalesce(r.certificate_required, false) = false
        or lower(coalesce(r.receiver_source, '')) in (
          'selected_metering_point_grid_owner',
          'selected_customer_site_grid_owner',
          'selected_supplier_switch_grid_owner',
          'selected_data_request_grid_owner',
          'original_inbound_sender',
          'original_inbound_receiver'
        )
        or r.receiver_certificate_id is not null
        or r.certificate_id is not null
      )
  ) into v_prod_certificate;

  v_legal :=
    coalesce(v_contract #>> '{legal_profile,status}', '') = 'ready'
    and coalesce(v_contract #>> '{documents,status}', '') = 'ready';

  v_website :=
    v_api
    and coalesce((v_contract #>> '{website,can_display}')::boolean, false)
    and coalesce((v_contract #>> '{applications,can_accept}')::boolean, false);

  v_customer_automation :=
    coalesce((v_contract #>> '{applications,can_accept}')::boolean, false)
    and coalesce(v_contract #>> '{customer_operations,status}', '') = 'ready';

  update public.company_onboarding_tasks
  set status = case when v_api then 'complete' else 'pending' end,
      blocker_reason = case when v_api then null else 'Aktiv API-klient med obligatoriska website_sales-scopes saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'api_client_scopes';

  update public.company_onboarding_tasks
  set status = case when v_customer_automation then 'complete' else 'pending' end,
      blocker_reason = case when v_customer_automation then null else 'Ansöknings- eller kundoperationsflödet är inte ready.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'customer_automation_readiness';

  update public.company_onboarding_tasks
  set status = case when v_brp then 'complete' else 'pending' end,
      blocker_reason = case when v_brp then null else 'Aktiv production-BRP saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'brp_settings';

  update public.company_onboarding_tasks
  set status = case when v_prod_certificate then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_certificate then null else 'PRODAT-route saknar säker mottagar-/certifikatstrategi.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_certificate';

  update public.company_onboarding_tasks
  set status = case when v_prod_actor then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_actor then null else 'Aktiv supplier-produktionsaktörsprofil saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_ediel_actor_settings';

  update public.company_onboarding_tasks
  set status = case when v_test_actor then 'complete' else 'pending' end,
      blocker_reason = case when v_test_actor then null else 'Aktiv supplier-testaktörsprofil saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'test_ediel_actor_settings';

  update public.company_onboarding_tasks
  set status = case when v_legal then 'complete' else 'pending' end,
      blocker_reason = case when v_legal then null else 'Juridisk profil eller dokumentflöde är inte ready.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'legal_default_package';

  update public.company_onboarding_tasks
  set status = case when v_prod_route then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_route then null else 'Supplier-bunden PRODAT-produktionsroute saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_route_readiness';

  update public.company_onboarding_tasks
  set status = case when v_test_route then 'complete' else 'pending' end,
      blocker_reason = case when v_test_route then null else 'Supplier-bunden test-route saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'test_route_readiness';

  update public.company_onboarding_tasks
  set status = case when v_transport then 'complete' else 'pending' end,
      blocker_reason = case when v_transport then null else 'Aktiv route saknar tenant- eller shared-mailboxtransport.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'shared_mailbox_transport';

  update public.company_onboarding_tasks
  set status = case when v_website then 'complete' else 'pending' end,
      blocker_reason = case when v_website then null else 'Webb/API-kontraktflödet är inte komplett.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'website_portal_integration';

  select count(*)
  into v_complete_count
  from public.company_onboarding_tasks
  where company_id = p_company_id and status = 'complete';

  return jsonb_build_object(
    'company_id', p_company_id,
    'complete_count', v_complete_count,
    'total_count', (select count(*) from public.company_onboarding_tasks where company_id = p_company_id),
    'go_live', v_go_live,
    'source', 'canonical_runtime_v2',
    'reconciled_at', now()
  );
end;
$$;

--
-- Name: gridex_reconcile_grid_owner_mappings_v1(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reconcile_grid_owner_mappings_v1(p_apply boolean DEFAULT false) RETURNS TABLE(platform_grid_owner_id uuid, status text, candidate_ops_grid_owner_id uuid, match_method text, candidate_count integer, details jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with
unmapped as (
  select pgo.id, pgo.name, pgo.org_number, pgo.ediel_id, pgo.market_actor_id, pgo.metadata
  from public.platform_grid_owners pgo
  where pgo.ops_grid_owner_id is null
    and coalesce(pgo.is_active, true)
),
verified_actors as (
  select a.id
  from public.platform_market_actors a
  where a.match_status = 'verified'
),
verified_identifiers as (
  select
    i.actor_id,
    lower(regexp_replace(btrim(i.identifier_type), '[^a-z0-9]+', '', 'g')) as identifier_type_normalized,
    i.identifier_value
  from public.platform_actor_identifiers i
  where i.is_verified = true
    and (i.valid_from is null or i.valid_from <= current_date)
    and (i.valid_to is null or i.valid_to >= current_date)
),
candidates as (
  select u.id as platform_grid_owner_id, g.id as ops_grid_owner_id, 1 as priority,
         'verified_ediel_id'::text as match_method
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join verified_identifiers i
    on i.actor_id = u.market_actor_id
   and i.identifier_type_normalized = 'edielid'
  join public.grid_owners g
    on nullif(lower(btrim(g.ediel_id)), '') = nullif(lower(btrim(i.identifier_value)), '')
   and coalesce(g.is_active, true)
  where nullif(lower(btrim(u.ediel_id)), '') = nullif(lower(btrim(i.identifier_value)), '')

  union all

  select u.id, g.id, 2, 'verified_organization_number'::text
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join verified_identifiers i
    on i.actor_id = u.market_actor_id
   and i.identifier_type_normalized in ('orgno', 'orgnumber', 'orgnr', 'organizationnumber')
  join public.grid_owners g
    on nullif(regexp_replace(coalesce(g.org_number, g.organization_number, ''), '[^0-9]', '', 'g'), '')
       = nullif(regexp_replace(coalesce(i.identifier_value, ''), '[^0-9]', '', 'g'), '')
   and coalesce(g.is_active, true)
  where nullif(regexp_replace(coalesce(u.org_number, ''), '[^0-9]', '', 'g'), '')
        = nullif(regexp_replace(coalesce(i.identifier_value, ''), '[^0-9]', '', 'g'), '')

  union all

  select u.id, g.id, 3, 'verified_actor_identity'::text
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join public.grid_owners g
    on g.platform_market_actor_id = u.market_actor_id
   and coalesce(g.is_active, true)

  union all

  select u.id, g.id, 4, 'verified_exact_alias'::text
  from unmapped u
  join public.platform_actor_aliases aa
    on aa.actor_id = u.market_actor_id
   and aa.is_verified = true
  join public.grid_owners g
    on g.platform_market_actor_id = aa.actor_id
   and coalesce(g.is_active, true)
  where nullif(regexp_replace(lower(coalesce(aa.normalized_alias, aa.alias, '')), '[^a-z0-9åäö]+', '', 'g'), '')
        = nullif(regexp_replace(lower(coalesce(u.name, '')), '[^a-z0-9åäö]+', '', 'g'), '')

  union all

  select u.id, g.id, 5, 'verified_existing_relation'::text
  from unmapped u
  join public.grid_owners g
    on g.platform_grid_owner_id = u.id
   and g.verification_status = 'verified'
   and coalesce(g.manual_review_required, false) = false
   and coalesce(g.is_active, true)
),
best_priority as (
  select c.platform_grid_owner_id, min(c.priority) as priority
  from candidates c
  group by c.platform_grid_owner_id
),
best_candidates as (
  select c.platform_grid_owner_id, c.ops_grid_owner_id, c.priority, c.match_method
  from candidates c
  join best_priority b
    on b.platform_grid_owner_id = c.platform_grid_owner_id
   and b.priority = c.priority
),
classified as (
  select
    u.id as platform_grid_owner_id,
    count(distinct b.ops_grid_owner_id)::integer as candidate_count,
    case when count(distinct b.ops_grid_owner_id) = 1
      then min(b.ops_grid_owner_id::text)::uuid else null::uuid end as candidate_ops_grid_owner_id,
    min(b.match_method) as match_method,
    min(b.priority) as match_priority
  from unmapped u
  left join best_candidates b on b.platform_grid_owner_id = u.id
  group by u.id
),
target_counts as (
  select c.candidate_ops_grid_owner_id, count(*)::integer as target_count
  from classified c
  where c.candidate_count = 1 and c.candidate_ops_grid_owner_id is not null
  group by c.candidate_ops_grid_owner_id
),
guarded as (
  select
    c.*,
    coalesce(tc.target_count, 0)::integer as target_count,
    exists (
      select 1 from public.platform_grid_owners occupied
      where occupied.ops_grid_owner_id = c.candidate_ops_grid_owner_id
        and occupied.id <> c.platform_grid_owner_id
    ) as target_already_mapped
  from classified c
  left join target_counts tc on tc.candidate_ops_grid_owner_id = c.candidate_ops_grid_owner_id
),
applied as (
  update public.platform_grid_owners pgo
     set ops_grid_owner_id = c.candidate_ops_grid_owner_id,
         metadata = jsonb_set(
           coalesce(pgo.metadata, '{}'::jsonb),
           '{ops_reconciliation}',
           jsonb_build_object(
             'engine', 'gridex_reconcile_grid_owner_mappings_v1',
             'engine_version', 3,
             'match_method', c.match_method,
             'match_priority', c.match_priority,
             'confidence', 'deterministic',
             'verified', true,
             'ops_grid_owner_id', c.candidate_ops_grid_owner_id,
             'reconciled_at', now()
           ), true
         ),
         updated_at = now()
  from guarded c
  where p_apply
    and c.candidate_count = 1
    and c.candidate_ops_grid_owner_id is not null
    and c.target_count = 1
    and not c.target_already_mapped
    and pgo.id = c.platform_grid_owner_id
    and pgo.ops_grid_owner_id is null
  returning pgo.id
)
select
  c.platform_grid_owner_id,
  case
    when a.id is not null then 'mapped'
    when c.candidate_count > 1 or c.target_count > 1 or c.target_already_mapped then 'ambiguous'
    when c.candidate_count = 1 and not p_apply then 'would_map'
    else 'review_required'
  end as status,
  c.candidate_ops_grid_owner_id,
  c.match_method,
  c.candidate_count,
  jsonb_build_object(
    'engine_version', 3,
    'apply_requested', p_apply,
    'match_priority', c.match_priority,
    'deterministic', c.candidate_count = 1 and c.target_count = 1 and not c.target_already_mapped,
    'target_candidate_count', c.target_count,
    'target_already_mapped', c.target_already_mapped,
    'identifier_type_normalized', true,
    'fuzzy_write_allowed', false
  ) as details
from guarded c
left join applied a on a.id = c.platform_grid_owner_id
order by c.platform_grid_owner_id;
$$;

--
-- Name: FUNCTION gridex_reconcile_grid_owner_mappings_v1(p_apply boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_reconcile_grid_owner_mappings_v1(p_apply boolean) IS 'Deterministic Gridex OPS grid-owner reconciliation v3. Normalizes verified identifier types (Ediel and organization-number variants), preserves one-to-one target guards, and never performs fuzzy writes.';

--
-- Name: gridex_record_application_provisioning_step(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_application_provisioning_step(p_company_id uuid, p_customer_application_id uuid, p_operation_id uuid, p_step text, p_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.customer_application_provisioning_steps (
    company_id, customer_application_id, operation_id, step, status, payload
  ) values (
    p_company_id, p_customer_application_id, p_operation_id, p_step, p_status, coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (company_id, customer_application_id, operation_id, step)
  do update set
    status = excluded.status,
    payload = public.customer_application_provisioning_steps.payload || excluded.payload,
    updated_at = now();
end;
$$;

--
-- Name: gridex_record_contract_backfill_issue(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_contract_backfill_issue(p_company_id uuid, p_contract_offer_id uuid, p_public_contract_offer_id uuid, p_issue_code text, p_issue_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.contract_lifecycle_backfill_issues(
    company_id,contract_offer_id,public_contract_offer_id,issue_code,issue_detail,status,last_seen_at
  ) values(
    p_company_id,p_contract_offer_id,p_public_contract_offer_id,p_issue_code,coalesce(p_issue_detail,'{}'::jsonb),'open',now()
  )
  on conflict(
    issue_code,
    (coalesce(contract_offer_id,'00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(public_contract_offer_id,'00000000-0000-0000-0000-000000000000'::uuid))
  ) do update set
    company_id=excluded.company_id,
    issue_detail=excluded.issue_detail,
    status='open',last_seen_at=now(),resolved_at=null;
end $$;

--
-- Name: gridex_record_customer_contract_event_v1(uuid, uuid, uuid, text, timestamp with time zone, text, jsonb, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone DEFAULT now(), p_note text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_derived_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype;
  v_event public.customer_contract_events%rowtype;
  v_previous_status text;
  v_new_status text;
  v_domain_event_id uuid;
  v_idempotency_key text := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    encode(digest(
      concat_ws(
        ':',
        p_company_id,
        p_customer_contract_id,
        p_event_type,
        p_happened_at,
        coalesce(p_note, '')
      ),
      'sha256'
    ), 'hex')
  );
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'customer_contract_event_service_role_required';
  end if;
  if p_company_id is null
     or p_customer_contract_id is null
     or p_customer_id is null
     or p_event_type not in (
       'created', 'signature_requested', 'signature_failed',
       'signature_retry_requested', 'signed', 'activated', 'updated',
       'termination_notice_received', 'terminated', 'cancelled', 'note'
     ) then
    raise exception using
      errcode = '22023',
      message = 'customer_contract_event_payload_invalid';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':' || p_customer_contract_id::text, 0)
  );
  select *
  into v_contract
  from public.customer_contracts contract
  where contract.id = p_customer_contract_id
    and contract.company_id = p_company_id
    and contract.customer_id = p_customer_id
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'customer_contract_not_found_for_tenant';
  end if;

  select *
  into v_event
  from public.customer_contract_events event
  where event.company_id = p_company_id
    and event.customer_contract_id = p_customer_contract_id
    and event.metadata->>'idempotency_key' = v_idempotency_key
  order by event.created_at
  limit 1;
  if found then
    return jsonb_build_object(
      'event', to_jsonb(v_event),
      'contract_status', v_contract.status,
      'existing', true
    );
  end if;

  v_previous_status := v_contract.status;
  v_new_status := v_contract.status;

  if p_event_type = 'signature_failed' then
    if v_contract.status <> 'pending_signature' then
      raise exception using
        errcode = '23514',
        message = 'signature_failure_requires_pending_signature';
    end if;
    v_new_status := 'signature_failed';
    update public.customer_contracts contract
    set status = v_new_status,
        lifecycle_stage = 'agreement_ready',
        metadata = coalesce(contract.metadata, '{}'::jsonb)
          || coalesce(p_metadata, '{}'::jsonb)
          || jsonb_build_object(
            'signature_status', 'failed',
            'signature_failed_at', p_happened_at,
            'recoverable_by_new_signature_attempt', true
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where contract.id = p_customer_contract_id
      and contract.company_id = p_company_id;
  elsif p_event_type = 'signature_retry_requested' then
    if v_contract.status <> 'signature_failed' then
      raise exception using
        errcode = '23514',
        message = 'signature_retry_requires_signature_failed';
    end if;
    v_new_status := 'pending_signature';
    update public.customer_contracts contract
    set status = v_new_status,
        metadata = coalesce(contract.metadata, '{}'::jsonb)
          || coalesce(p_metadata, '{}'::jsonb)
          || jsonb_build_object(
            'signature_status', 'pending',
            'signature_retry_requested_at', p_happened_at,
            'recoverable_by_new_signature_attempt', false
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where contract.id = p_customer_contract_id
      and contract.company_id = p_company_id;
  elsif p_event_type = 'signed' then
    -- Only the canonical signature finalizer may transition a contract to
    -- signed. This event merely records that already-committed evidence.
    if v_contract.status <> 'signed'
       or v_contract.signed_at is null
       or v_contract.locked_at is null
       or nullif(v_contract.signature_snapshot_sha256, '') is null
       or v_contract.contract_publication_version_id is null
       or v_contract.contract_product_version_id is null
       or v_contract.legal_bundle_version_id is null
       or v_contract.contract_price_snapshot_id is null then
      raise exception using
        errcode = '23514',
        message = 'signed_event_requires_canonical_signature_evidence';
    end if;
  elsif p_event_type = 'activated' then
    -- Supply activation is a larger atomic graph and must use its dedicated
    -- command, which also writes the supply period and switch confirmation.
    raise exception using
      errcode = '23514',
      message = 'use_gridex_activate_customer_supply_v1';
  elsif p_event_type in ('terminated', 'cancelled') then
    v_new_status := case
      when p_event_type = 'terminated' then 'terminated'
      else 'cancelled'
    end;
    update public.customer_contracts
    set status = v_new_status,
        ended_at = coalesce(
          nullif(p_metadata->>'ended_at', '')::timestamptz,
          nullif(p_metadata->>'ends_at', '')::timestamptz,
          p_happened_at,
          ended_at
        ),
        termination_notice_date = coalesce(
          nullif(p_metadata->>'termination_notice_date', '')::timestamptz,
          termination_notice_date
        ),
        termination_reason = coalesce(
          nullif(p_metadata->>'termination_reason', ''),
          termination_reason
        ),
        withdrawal_requested_at = coalesce(
          nullif(p_metadata->>'withdrawal_requested_at', '')::timestamptz,
          withdrawal_requested_at
        ),
        rejected_reason = coalesce(
          nullif(p_metadata->>'rejected_reason', ''),
          rejected_reason
        ),
        status_reason_code = coalesce(
          nullif(p_metadata->>'reason_code', ''),
          status_reason_code,
          p_event_type
        ),
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
            'status_reason_code',
            nullif(p_metadata->>'reason_code', '')
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where id = p_customer_contract_id
      and company_id = p_company_id;
  elsif p_event_type = 'termination_notice_received' then
    update public.customer_contracts
    set termination_notice_date = p_happened_at,
        ended_at = coalesce(p_derived_ends_at, ended_at),
        updated_by = p_actor_user_id,
        updated_at = now()
    where id = p_customer_contract_id
      and company_id = p_company_id;
  end if;

  insert into public.customer_contract_events(
    company_id,
    customer_contract_id,
    customer_id,
    event_type,
    happened_at,
    note,
    metadata,
    actor_user_id
  ) values (
    p_company_id,
    p_customer_contract_id,
    p_customer_id,
    p_event_type,
    p_happened_at,
    p_note,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('idempotency_key', v_idempotency_key),
    p_actor_user_id
  )
  returning * into v_event;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    actor_user_id,
    source,
    idempotency_key,
    payload
  ) values (
    p_company_id,
    'contract.event.recorded',
    'customer_contract',
    p_customer_contract_id,
    p_actor_user_id,
    'gridex_record_customer_contract_event_v1',
    'customer-contract-event:' || v_idempotency_key,
    jsonb_build_object(
      'customer_contract_event_id', v_event.id,
      'customer_id', p_customer_id,
      'event_type', p_event_type,
      'previous_status', v_previous_status,
      'new_status', v_new_status
    )
  )
  on conflict do nothing
  returning id into v_domain_event_id;

  if v_domain_event_id is not null then
    insert into public.event_outbox(
      company_id,
      domain_event_id,
      destination_type,
      destination_key,
      payload
    ) values (
      p_company_id,
      v_domain_event_id,
      'webhook',
      'contract.event.recorded',
      jsonb_build_object(
        'domain_event_id', v_domain_event_id,
        'customer_contract_id', p_customer_contract_id,
        'event_type', p_event_type
      )
    ) on conflict do nothing;
  end if;

  return jsonb_build_object(
    'event', to_jsonb(v_event),
    'contract_status', v_new_status,
    'existing', false
  );
end
$$;

--
-- Name: FUNCTION gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone, p_note text, p_metadata jsonb, p_actor_user_id uuid, p_derived_ends_at timestamp with time zone, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone, p_note text, p_metadata jsonb, p_actor_user_id uuid, p_derived_ends_at timestamp with time zone, p_idempotency_key text) IS 'Atomic, tenant-scoped customer-contract event command. Signed events require pre-existing canonical evidence; activation is reserved for the supply activation graph.';

--
-- Name: gridex_record_invoice_fee_remediation(uuid, text, uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_invoice_fee_remediation(p_company_id uuid, p_source_table text, p_offer_id uuid, p_status text, p_blocker_code text, p_evidence jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_company_id is null
     and coalesce(p_blocker_code,'') not in('tenant_context_missing','tenant_context_conflict') then
    raise exception using errcode='23502',message='company_required_for_tenant_remediation';
  end if;

  insert into public.contract_invoice_fee_remediation_tasks(
    company_id,source_table,offer_id,status,blocker_code,evidence,last_error,resolved_at,updated_at
  ) values(
    p_company_id,p_source_table,p_offer_id,p_status,p_blocker_code,coalesce(p_evidence,'{}'::jsonb),p_error,
    case when p_status='resolved' then now() else null end,now()
  )
  on conflict(source_table,offer_id) do update set
    company_id=excluded.company_id,status=excluded.status,blocker_code=excluded.blocker_code,
    evidence=excluded.evidence,last_error=excluded.last_error,resolved_at=excluded.resolved_at,updated_at=now();
end $$;

--
-- Name: gridex_record_invoice_purchase_request_v1(uuid, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_invoice_purchase_request_v1(p_company_id uuid, p_invoice_export_item_id uuid, p_financing_mode text, p_payload jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_event_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'invoice_purchase_service_role_required';
  end if;
  if p_company_id is null or p_invoice_export_item_id is null
     or p_financing_mode not in ('factoring_without_recourse', 'factoring_with_recourse') then
    raise exception using errcode = '22023', message = 'invoice_purchase_payload_invalid';
  end if;

  update public.invoice_export_items
  set purchase_status = 'requested',
      financing_mode = p_financing_mode,
      updated_at = now()
  where id = p_invoice_export_item_id and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'invoice_export_item_not_found_for_tenant';
  end if;

  insert into public.invoice_purchase_events (
    company_id, invoice_export_item_id, event_type, purchase_status, finance_status, payload, created_by
  ) values (
    p_company_id, p_invoice_export_item_id, 'purchase_requested_manual', 'requested', p_financing_mode,
    coalesce(p_payload, '{}'::jsonb), p_actor_user_id
  )
  returning id into v_event_id;

  return jsonb_build_object('event_id', v_event_id);
end
$$;

--
-- Name: gridex_record_legacy_api_key_use_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_legacy_api_key_use_v1(p_api_client_id uuid, p_route text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
 update public.integration_api_clients set legacy_api_key_request_count=legacy_api_key_request_count+1,last_legacy_api_key_used_at=now(),last_legacy_api_key_route=left(nullif(btrim(coalesce(p_route,'')),''),500),legacy_api_key_migration_status=case when legacy_api_key_migration_status='migrated' then 'in_progress' when legacy_api_key_migration_status='unknown' then 'not_started' else legacy_api_key_migration_status end,updated_at=now() where id=p_api_client_id;
$$;

--
-- Name: gridex_record_prodat_object_validation_v1(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_prodat_object_validation_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_assessment_id uuid, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;c gridex_received_sources.validation_assessments%rowtype;facts jsonb;facet jsonb;own jsonb;scope jsonb;physical jsonb;tokens jsonb;lin jsonb;li text;next_line integer;hash text;existing gridex_received_sources.prodat_object_validation_facets%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_standard IS DISTINCT FROM 'edifact' OR p_source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR p_facts_text IS NULL OR octet_length(p_facts_text)>262144 THEN RAISE EXCEPTION 'prodat_full_object_original_required';END IF;
 SELECT * INTO c FROM gridex_received_sources.validation_assessments WHERE id=p_assessment_id AND company_id=p_company_id AND environment=p_environment AND source_message_id=m.id AND source_payload_hash=p_source_payload_hash FOR SHARE;
 IF NOT FOUND OR EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=c.id) THEN RAISE EXCEPTION 'prodat_full_object_current_assessment_required';END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 facts:=p_facts_text::jsonb;facet:=c.facts_text::jsonb->'registerValidation';tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF NOT facts ?& ARRAY['version','owner','coverage','sharedAccepted','reasonCodes','objects'] OR facts-ARRAY['version','owner','coverage','sharedAccepted','reasonCodes','objects']<>'{}'::jsonb OR facts->'version' IS DISTINCT FROM '1'::jsonb
  OR facts->>'owner' IS DISTINCT FROM 'canonical-full-prodat-object-validation-v1' OR facts->>'coverage' IS DISTINCT FROM 'full_canonical_guide_objects_only'
  OR jsonb_typeof(facts->'sharedAccepted') IS DISTINCT FROM 'boolean' OR (facts->>'sharedAccepted'='true' AND c.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted')
  OR facts->'reasonCodes' IS DISTINCT FROM c.facts_text::jsonb->'reasonCodes' OR facet->>'owner' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facet->>'coverage' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(facts->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(facts->'objects') IS DISTINCT FROM jsonb_array_length(facet->'objects') OR jsonb_array_length(facts->'objects') NOT BETWEEN 1 AND 16 THEN RAISE EXCEPTION 'prodat_full_object_canonical_scope_required';END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(facts->'objects') o LOOP
  IF NOT own ?& ARRAY['objectId','identityAgency','messageReference','firstLineIndex','lineItemReference','disposition','reasons','negativeFields'] OR own-ARRAY['objectId','identityAgency','messageReference','firstLineIndex','lineItemReference','disposition','reasons','negativeFields']<>'{}'::jsonb
   OR coalesce(own->>'disposition','') NOT IN('accepted','rejected','unavailable') OR jsonb_typeof(own->'reasons') IS DISTINCT FROM 'array' OR jsonb_typeof(own->'negativeFields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'prodat_full_object_facet_invalid';END IF;
  SELECT o INTO scope FROM jsonb_array_elements(facet->'objects') o WHERE o->'objectId'=own->'objectId' AND o->'identityAgency'=own->'identityAgency' AND o->'messageReference'=own->'messageReference' AND o#>'{registers,0,lineIndex}'=own->'firstLineIndex';
  IF scope IS NULL OR scope->>'messageIndex'<>'0' OR (own->>'disposition'='accepted' AND (facts->>'sharedAccepted'<>'true' OR scope->>'disposition'<>'accepted' OR own->'reasons'<>'[]'::jsonb OR own->'negativeFields'<>'[]'::jsonb)) OR (own->>'disposition'='rejected' AND (jsonb_array_length(own->'negativeFields')=0 OR jsonb_array_length(own->'reasons')=0)) THEN RAISE EXCEPTION 'prodat_full_object_own_decision_required';END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(own->'reasons') r
   WHERE r#>>'{}'<>'shared_source_not_qualified' AND NOT c.facts_text::jsonb->'reasonCodes' @> jsonb_build_array(r)
   AND NOT coalesce((r#>>'{}'='REGISTER_SCOPE_UNAVAILABLE'
    AND c.facts_text::jsonb->>'syntaxDecision'='accepted' AND c.facts_text::jsonb->>'applicationDecision'='rejected'
    AND facts->'sharedAccepted'='true'::jsonb
    AND own->>'disposition'='unavailable' AND scope->>'disposition'='unavailable'
    AND own->'negativeFields'='["209"]'::jsonb
    AND jsonb_array_length(own->'reasons')=2 AND own->'reasons' @> '["REGISTER_SCOPE_UNAVAILABLE","FIELD_MATRIX_REQUIRED_FIELD_MISSING"]'::jsonb
    AND scope->'reasons'='["REGISTER_SCOPE_UNAVAILABLE"]'::jsonb
    AND c.facts_text::jsonb->'reasonCodes'='["FIELD_MATRIX_REQUIRED_FIELD_MISSING"]'::jsonb
    AND own->'objectId'='null'::jsonb AND own->'identityAgency'='null'::jsonb
    AND scope->'objectId'='null'::jsonb AND scope->'identityAgency'='null'::jsonb
    AND jsonb_array_length(facet->'objects')=1 AND jsonb_array_length(scope->'registers')=1
    AND scope->'messageIndex'='0'::jsonb
    AND (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN')=1
    AND (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')=1
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN'
     AND t->'index'=scope#>'{registers,0,segmentIndex}'
     AND t#>>'{elements,1,0}'=scope#>>'{registers,0,lineNumber}'
     AND (SELECT count(*) FROM jsonb_array_elements(tokens)prior WHERE prior->>'tag'='LIN' AND (prior->>'index')::int<(t->>'index')::int)=(scope#>>'{registers,0,lineIndex}')::int
     AND jsonb_typeof(t#>'{elements,3}')='array'
     AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(t#>'{elements,3}')part WHERE part<>'')
     AND EXISTS(SELECT FROM jsonb_array_elements(tokens)header WHERE header->>'tag'='UNH'
      AND header#>>'{elements,1,0}'=scope->>'messageReference' AND coalesce(header#>>'{elements,1,0}','')<>''))),false))
   THEN RAISE EXCEPTION 'prodat_full_object_reason_changed';END IF;
  -- The canonical LIN number independently binds the full-guide owner to
  -- the stored original. Parser indexes are never caller supplied offsets.
  SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,1,0}'=scope#>>'{registers,0,lineNumber}';
  physical:=NULL;
  -- A rejected single-LIN original has no accepted fallback. Bind its actual
  -- position twice, independently of the missing sequence or object scalar.
  IF c.facts_text::jsonb->>'applicationDecision'='rejected' AND own->>'disposition'='unavailable'
   AND own->'reasons' ? 'FIELD_MATRIX_REQUIRED_FIELD_MISSING'
   AND own->'negativeFields' ?| ARRAY['314','209']
   AND jsonb_array_length(scope->'registers')=1 AND own->'firstLineIndex'=scope#>'{registers,0,lineIndex}'
   AND scope->'messageIndex'='0'::jsonb
   AND (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN')=1
   AND (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')=1 THEN
   SELECT t INTO physical FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN'
    AND t->'index'=scope#>'{registers,0,segmentIndex}'
    AND (SELECT count(*) FROM jsonb_array_elements(tokens)prior WHERE prior->>'tag'='LIN' AND (prior->>'index')::int<(t->>'index')::int)=(scope#>>'{registers,0,lineIndex}')::int
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)header WHERE header->>'tag'='UNH' AND header#>>'{elements,1,0}'=scope->>'messageReference' AND coalesce(header#>>'{elements,1,0}','')<>'');
  END IF;
  IF lin IS NULL AND physical IS NOT NULL AND own->'negativeFields' ? '314'
   AND facts->'sharedAccepted'='false'::jsonb AND scope->>'disposition'='rejected'
   AND scope->'reasons' ? 'PRODAT_REGISTER_STRUCTURE_INVALID'
   AND scope#>'{registers,0,lineNumber}'='null'::jsonb AND nullif(physical#>>'{elements,1,0}','') IS NULL THEN
   lin:=physical;
  END IF;
  IF lin IS NULL OR ((lin#>>'{elements,3,0}' IS DISTINCT FROM own->>'objectId' OR lin#>>'{elements,3,3}' IS DISTINCT FROM own->>'identityAgency') AND NOT (
   physical IS NOT NULL AND lin->'index'=physical->'index' AND own->'negativeFields' ? '209'
   AND scope->>'disposition'='unavailable' AND scope->'reasons' ? 'REGISTER_SCOPE_UNAVAILABLE'
   AND own->'objectId'='null'::jsonb AND own->'identityAgency'='null'::jsonb
   AND scope->'objectId'='null'::jsonb AND scope->'identityAgency'='null'::jsonb
   AND jsonb_typeof(physical#>'{elements,3}')='array'
   AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(physical#>'{elements,3}')part WHERE part<>''))) THEN
   RAISE EXCEPTION 'prodat_full_object_physical_scope_required';
  END IF;
 END LOOP;
 IF (SELECT count(DISTINCT (o->>'objectId',o->>'identityAgency',o->>'firstLineIndex')) FROM jsonb_array_elements(facts->'objects') o)<>jsonb_array_length(facts->'objects') THEN RAISE EXCEPTION 'prodat_full_object_duplicate_scope';END IF;
 hash:=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex');SELECT * INTO existing FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=c.id;
 IF FOUND AND existing.facts_hash IS DISTINCT FROM hash THEN RAISE EXCEPTION 'prodat_full_object_facet_replay_conflict';END IF;
 INSERT INTO gridex_received_sources.prodat_object_validation_facets(assessment_id,company_id,environment,source_message_id,source_payload_hash,facts_text,facts_hash) VALUES(c.id,p_company_id,p_environment,m.id,p_source_payload_hash,p_facts_text,hash) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('assessmentId',c.id,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',m.id,'sourcePayloadHash',p_source_payload_hash,'objectFactsHash',hash);
END $$;

