--
-- Name: gridex_refresh_actor_certificate_statuses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_actor_certificate_statuses(p_run_type text DEFAULT 'certificate_refresh'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_checked int := 0;
  v_missing int := 0;
begin
  insert into public.platform_actor_readiness_runs(run_type, status, metadata)
  values (coalesce(p_run_type, 'certificate_refresh'), 'running', jsonb_build_object('source', 'gridex_refresh_actor_certificate_statuses'))
  returning id into v_run_id;

  update public.platform_actor_certificates c
  set status = case
      when c.status = 'missing' then 'missing'
      when c.valid_to is not null and c.valid_to < now() then 'expired'
      when c.valid_to is not null and c.valid_to <= now() + interval '45 days' then 'expires_soon'
      when c.fingerprint_sha256 is not null and (c.valid_to is null or c.valid_to >= now()) then 'valid'
      else coalesce(nullif(c.status, ''), 'unknown')
    end,
    last_checked_at = coalesce(c.last_checked_at, now()),
    next_check_at = case
      when c.valid_to is not null and c.valid_to <= now() + interval '45 days' then now() + interval '7 days'
      else now() + interval '30 days'
    end,
    updated_at = now(),
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object('status_refreshed_at', now(), 'status_refreshed_by', 'system')
  where c.next_check_at is null or c.next_check_at <= now() or c.last_checked_at is null;

  get diagnostics v_checked = row_count;

  insert into public.platform_actor_certificates(actor_id, ediel_id, environment, certificate_type, purpose, status, source, metadata, last_checked_at, next_check_at)
  select distinct v.actor_id, v.ediel_id, v.environment, 'unknown', 'encryption', 'missing', 'auto_readiness_missing_certificate',
         jsonb_build_object('reason', 'PRODAT production route requires receiver certificate before auto-send', 'created_by', 'gridex_refresh_actor_certificate_statuses'),
         now(), now() + interval '30 days'
  from public.platform_actor_send_readiness_v v
  where v.requires_certificate = true
    and v.certificate_id is null
    and not exists (
      select 1
      from public.platform_actor_certificates existing
      where existing.actor_id = v.actor_id
        and existing.environment = v.environment
        and existing.purpose = 'encryption'
        and existing.status in ('missing','unknown')
    );

  get diagnostics v_missing = row_count;

  update public.platform_actor_readiness_runs
  set status = 'completed', finished_at = now(), checked_certificate_count = v_checked + v_missing,
      metadata = metadata || jsonb_build_object('certificates_refreshed', v_checked, 'missing_certificate_placeholders_created', v_missing)
  where id = v_run_id;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'certificates_refreshed', v_checked, 'missing_certificate_placeholders_created', v_missing);
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_refresh_billing_export_run(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_billing_export_run(p_company_id uuid, p_export_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_run public.billing_export_runs%rowtype; v_total integer; v_ready integer; v_blocked integer;
v_queued integer; v_sent integer; v_ack integer; v_failed integer; v_rejected integer; v_status text;
begin
  select * into v_run from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  select count(*),count(*) filter(where status in ('ready','ready_for_retry')),count(*) filter(where status='blocked'),
    count(*) filter(where export_status='queued'),count(*) filter(where export_status='sent'),
    count(*) filter(where export_status='acknowledged'),count(*) filter(where export_status='failed'),
    count(*) filter(where partner_result_type='rejected')
  into v_total,v_ready,v_blocked,v_queued,v_sent,v_ack,v_failed,v_rejected
  from public.billing_export_run_items where company_id=p_company_id and billing_export_run_id=p_export_run_id;
  v_status:=case
    when (v_failed>0 or v_blocked>0) and v_sent+v_ack>0 then 'partial_failed'
    when v_failed>0 then 'failed'
    when v_blocked>0 then 'blocked'
    when v_total>0 and v_ack=v_total then 'acknowledged'
    when v_total>0 and v_sent+v_ack=v_total then 'sent'
    when v_queued>0 then 'queued'
    when v_ready>0 then 'ready_with_flags'
    else 'blocked' end;
  update public.billing_export_runs set status=v_status,rows_total=v_total,rows_ready=v_ready,rows_blocked=v_blocked,
    rows_queued=v_queued,rows_sent=v_sent,rows_acknowledged=v_ack,rows_failed=v_failed,rows_rejected=v_rejected,
    rows_exported=v_sent+v_ack,updated_at=now()
  where id=p_export_run_id and company_id=p_company_id returning * into v_run;
  return to_jsonb(v_run);
end $$;

--
-- Name: gridex_refresh_customer_process_summary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_customer_process_summary(p_company_id uuid, p_customer_id uuid, p_latest_action text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_active integer;
  v_pending integer;
  v_blocked integer;
  v_total integer;
  v_summary jsonb;
begin
  -- A retention tombstone fixes this customer's summary at '{}'.
  IF gridex_correction_process.customer_retention_tombstoned_v1(p_company_id,p_customer_id) THEN RETURN '{}'::jsonb; END IF;
  select
    count(*) filter (where coalesce(onboarding_status,'') in ('active_supply','active')),
    count(*) filter (where coalesce(onboarding_status,'') not in ('active_supply','active','needs_admin_review','blocked')),
    count(*) filter (where coalesce(onboarding_status,'') in ('needs_admin_review','blocked')),
    count(*)
  into v_active,v_pending,v_blocked,v_total
  from public.customer_sites
  where company_id=p_company_id
    and customer_id=p_customer_id
    and coalesce(is_active,true)=true;

  v_summary := jsonb_build_object(
    'total_sites', v_total,
    'active_sites', v_active,
    'pending_sites', v_pending,
    'blocked_sites', v_blocked,
    'refreshed_at', now()
  );

  update public.customers
  set active_sites=v_active,
      pending_sites=v_pending,
      blocked_sites=v_blocked,
      latest_customer_action=coalesce(p_latest_action,latest_customer_action),
      process_summary=v_summary,
      intake_status=case
        when v_total=0 then 'needs_admin_review'
        when v_blocked>0 then 'blocked'
        when v_pending>0 then 'pending_information'
        when v_active=v_total then 'active_supply'
        else 'pending_information'
      end,
      next_action=case
        when v_blocked>0 then 'review_blocker'
        when v_pending>0 then 'continue_site_processes'
        else 'none'
      end,
      updated_at=now()
  where id=p_customer_id and company_id=p_company_id;

  return v_summary;
end;
$$;

--
-- Name: gridex_refresh_customer_summary_from_site_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_customer_summary_from_site_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.gridex_refresh_customer_process_summary(
    coalesce(new.company_id,old.company_id),
    coalesce(new.customer_id,old.customer_id),
    case when tg_op='DELETE' then 'site_deleted' else concat_ws(':',new.id::text,coalesce(new.onboarding_status,''),coalesce(new.next_action,'')) end
  );
  return coalesce(new,old);
end;
$$;

--
-- Name: gridex_refresh_legal_profile_completeness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_legal_profile_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.missing_fields := public.gridex_tenant_legal_profile_missing_fields(new);
  -- Keep the persisted value compatible with the existing table constraint and
  -- publication functions. The semantic API status is calculated separately as
  -- complete_unreviewed when review is still required.
  new.completeness_status := case
    when coalesce(array_length(new.missing_fields, 1), 0) > 0 then 'incomplete'
    when coalesce(new.review_required, false) then 'complete'
    when coalesce(new.reviewed_at, new.verified_at) is not null then 'verified'
    else 'complete'
  end;
  new.updated_at := now();
  return new;
end
$$;

--
-- Name: platform_runtime_readiness; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_runtime_readiness (
    id boolean DEFAULT true NOT NULL,
    schema_version text NOT NULL,
    schema_fingerprint text NOT NULL,
    is_ready boolean DEFAULT false NOT NULL,
    blocking_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    capabilities jsonb DEFAULT '{}'::jsonb NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    deployment_id text,
    migration_version text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_runtime_readiness_blocking_issues_check CHECK ((jsonb_typeof(blocking_issues) = 'array'::text)),
    CONSTRAINT platform_runtime_readiness_capabilities_check CHECK ((jsonb_typeof(capabilities) = 'object'::text)),
    CONSTRAINT platform_runtime_readiness_id_check CHECK (id),
    CONSTRAINT platform_runtime_readiness_migration_version_check CHECK ((migration_version ~ '^[0-9]{14}$'::text)),
    CONSTRAINT platform_runtime_readiness_schema_fingerprint_check CHECK ((schema_fingerprint ~ '^[a-f0-9]{64}$'::text))
);

--
-- Name: gridex_refresh_platform_runtime_readiness_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_platform_runtime_readiness_v1(p_schema_version text, p_deployment_id text DEFAULT NULL::text, p_migration_version text DEFAULT NULL::text) RETURNS public.platform_runtime_readiness
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_runtime record;
  v_result public.platform_runtime_readiness%rowtype;
  v_schema_version text := nullif(btrim(coalesce(p_schema_version, '')), '');
  v_migration_version text := nullif(btrim(coalesce(p_migration_version, '')), '');
begin
  if v_schema_version is null then raise exception using errcode='22023', message='runtime_schema_version_required'; end if;
  if v_migration_version is null then
    select max(version::text) into v_migration_version from supabase_migrations.schema_migrations;
  end if;
  if v_migration_version is null or v_migration_version !~ '^[0-9]{14}$' then
    raise exception using errcode='22023', message='runtime_migration_version_invalid';
  end if;
  select is_ready, schema_fingerprint, blocking_issues, capabilities into strict v_runtime
  from public.gridex_runtime_schema_capabilities_v3;
  insert into public.platform_runtime_readiness(id,schema_version,schema_fingerprint,is_ready,blocking_issues,capabilities,verified_at,deployment_id,migration_version,updated_at)
  values(true,v_schema_version,v_runtime.schema_fingerprint,v_runtime.is_ready and coalesce(cardinality(v_runtime.blocking_issues),0)=0,to_jsonb(coalesce(v_runtime.blocking_issues,'{}'::text[])),coalesce(v_runtime.capabilities,'{}'::jsonb),now(),nullif(btrim(coalesce(p_deployment_id,'')),''),v_migration_version,now())
  on conflict(id) do update set schema_version=excluded.schema_version,schema_fingerprint=excluded.schema_fingerprint,is_ready=excluded.is_ready,blocking_issues=excluded.blocking_issues,capabilities=excluded.capabilities,verified_at=excluded.verified_at,deployment_id=excluded.deployment_id,migration_version=excluded.migration_version,updated_at=excluded.updated_at
  returning * into v_result;
  return v_result;
end $_$;

--
-- Name: gridex_refresh_staff_identity_binding_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_staff_identity_binding_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b public.tenant_staff_identity_bindings%rowtype; operator_id uuid:=(p_command->>'operator_user_id')::uuid;
BEGIN
 PERFORM public.gridex_staff_identity_registration_v1(p_command,false);
 PERFORM 1 FROM auth.users u JOIN public.user_profiles profile ON profile.id=u.id WHERE u.id=operator_id FOR SHARE OF u,profile;
 IF NOT FOUND OR NOT coalesce('users.write'=ANY(public.gridex_staff_actor_permissions_v1((p_command->>'company_id')::uuid,operator_id,true)),false)
 THEN RAISE EXCEPTION 'staff_identity_rotation_not_authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE id=(p_command->>'binding_id')::uuid AND company_id=(p_command->>'company_id')::uuid
  AND api_client_id=(p_command->>'api_client_id')::uuid AND provider_id=(p_command->>'provider_id')::uuid FOR UPDATE;
 IF NOT FOUND OR b.status NOT IN('pending','active') OR b.version IS DISTINCT FROM (p_command->>'binding_version')::integer
  OR b.local_auth_issuer IS DISTINCT FROM (p_command->'verified_client'->'staff_tenant_auth'->>'url')||'/auth/v1'
 THEN RAISE EXCEPTION 'staff_identity_binding_mismatch' USING ERRCODE='42501'; END IF;
 IF b.provider_configuration IS DISTINCT FROM p_command->'verified_provider' THEN
  UPDATE public.tenant_staff_identity_bindings SET provider_configuration=p_command->'verified_provider',version=version+1 WHERE id=b.id RETURNING * INTO b;
  INSERT INTO public.canonical_audit_events(company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,before_state,after_state)
  VALUES(b.company_id,'TENANT_STAFF_IDENTITY_KEY_ROTATED','tenant_staff_identity',b.id,operator_id,'Explicit staff provider key rotation without identity remap','staff-binding-rotation:'||b.id::text||':'||b.version::text,
   jsonb_build_object('binding_version',b.version-1),jsonb_build_object('binding_version',b.version,'actor_user_id',b.actor_user_id));
 END IF;
 RETURN jsonb_build_object('actor_user_id',b.actor_user_id,'binding_id',b.id,'binding_version',b.version);
END $$;

--
-- Name: gridex_register_customer_lifecycle_decision_v1(uuid, uuid, uuid, text, text, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_register_customer_lifecycle_decision_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_decision_type text, p_scope_type text, p_scope_id uuid, p_received_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_now timestamptz := now();
  v_received timestamptz := coalesce(p_received_at, now());
  v_reason text := coalesce(nullif(btrim(p_reason), ''), 'Kundbeslut registrerat.');
  v_result jsonb := '{}'::jsonb;
  v_rows integer := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'lifecycle_decision_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_actor_user_id is null
     or p_decision_type not in ('withdrawal', 'cancelled', 'rejected')
     or p_scope_type not in ('customer', 'contract', 'site', 'metering_point')
     or (p_scope_type <> 'customer' and p_scope_id is null) then
    raise exception using errcode = '22023', message = 'lifecycle_decision_payload_invalid';
  end if;

  perform 1 from public.customers
  where id = p_customer_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;

  if p_scope_type = 'customer' then
    -- The whole customer relationship ends: the canonical archive closes the graph.
    v_result := public.gridex_archive_customer_v1(p_company_id, p_customer_id, p_actor_user_id, v_reason);
    update public.customers
    set lifecycle_status_reason = v_reason,
        lifecycle_closed_at = coalesce(lifecycle_closed_at, v_now)
    where id = p_customer_id and company_id = p_company_id;

  elsif p_scope_type = 'contract' then
    perform 1 from public.customer_contracts
    where id = p_scope_id and company_id = p_company_id and customer_id = p_customer_id;
    if not found then
      raise exception using errcode = 'P0002', message = 'contract_not_found_for_customer';
    end if;
    v_result := public.gridex_record_customer_contract_event_v1(
      p_company_id,
      p_scope_id,
      p_customer_id,
      'cancelled',
      v_received,
      v_reason,
      jsonb_build_object(
        'reason_code', case when p_decision_type = 'withdrawal' then 'cancelled_by_customer' else p_decision_type end,
        'withdrawal_requested_at', case when p_decision_type = 'withdrawal' then v_received end,
        'rejected_reason', case when p_decision_type = 'rejected' then v_reason end,
        'termination_reason', case p_decision_type
          when 'withdrawal' then 'customer_withdrawal'
          when 'cancelled' then 'customer_request'
          else 'other' end,
        'termination_notice_date', v_received,
        'ends_at', to_char(v_now at time zone 'UTC', 'YYYY-MM-DD')
      ),
      p_actor_user_id,
      null,
      'lifecycle-decision:' || p_scope_id::text || ':' || p_decision_type
    );

  elsif p_scope_type = 'site' then
    update public.customer_sites
    set status = 'closed', closed_at = v_now, closed_reason = v_reason, updated_by = p_actor_user_id
    where id = p_scope_id and customer_id = p_customer_id and company_id = p_company_id;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      raise exception using errcode = 'P0002', message = 'site_not_found_for_customer';
    end if;
    update public.metering_points
    set status = 'closed', closed_at = v_now, closed_reason = v_reason, updated_by = p_actor_user_id
    where site_id = p_scope_id and company_id = p_company_id and status <> 'closed';
    get diagnostics v_rows = row_count;
    v_result := jsonb_build_object('closed_metering_points', v_rows);

  else
    update public.metering_points
    set status = 'closed', closed_at = v_now, closed_reason = v_reason, updated_by = p_actor_user_id
    where id = p_scope_id
      and company_id = p_company_id
      and (customer_id = p_customer_id
        or site_id in (select s.id from public.customer_sites s
                       where s.customer_id = p_customer_id and s.company_id = p_company_id));
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      raise exception using errcode = 'P0002', message = 'metering_point_not_found_for_customer';
    end if;
  end if;

  return jsonb_build_object('scope_type', p_scope_type, 'scope_id', p_scope_id, 'effect', v_result);
end
$$;

--
-- Name: gridex_register_late_metering_correction(uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_register_late_metering_correction(p_company_id uuid, p_original_underlay_id uuid, p_corrected_underlay_id uuid, p_source_value_id uuid, p_reason text, p_currency text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_id uuid; v_status text;
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'adjustment_reason_required'; end if;
  if p_currency !~ '^[A-Z]{3}$' then raise exception 'invalid_currency'; end if;
  select status into v_status from public.billing_underlays where id=p_original_underlay_id and company_id=p_company_id;
  if not found then raise exception 'original_underlay_not_found_for_tenant'; end if;
  if v_status not in ('exported','invoiced','locked','completed') then raise exception 'underlay_not_locked_or_invoiced'; end if;
  insert into public.billing_adjustment_cases(company_id,original_billing_underlay_id,corrected_billing_underlay_id,source_normalized_metering_value_id,reason,status,currency)
  values(p_company_id,p_original_underlay_id,p_corrected_underlay_id,p_source_value_id,p_reason,'detected',p_currency)
  on conflict(company_id,original_billing_underlay_id,source_normalized_metering_value_id)
  do update set corrected_billing_underlay_id=excluded.corrected_billing_underlay_id,reason=excluded.reason,updated_at=now()
  returning id into v_id;
  return v_id;
end $_$;

