--
-- Name: gridex_reject_billing_configuration_snapshot_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_billing_configuration_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.billing_configuration_snapshot_sha256 is not null
     and (
       new.billing_configuration_snapshot is distinct from old.billing_configuration_snapshot
       or new.billing_configuration_snapshot_sha256 is distinct from old.billing_configuration_snapshot_sha256
       or new.billing_configuration_snapshotted_at is distinct from old.billing_configuration_snapshotted_at
     ) then
    raise exception 'billing_configuration_snapshot_is_immutable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_reject_locked_legal_document_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_legal_document_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists(
    select 1 from public.legal_bundle_versions b
    where b.id=old.legal_bundle_version_id
      and (b.locked_at is not null or b.published_at is not null)
  ) and coalesce(current_setting('gridex.version_transition',true),'')<>'on' then
    raise exception using errcode='55000',message='immutable_legal_document_locked';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_market_price_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_market_price_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    if old.status='locked' then
      raise exception 'locked_market_price_immutable' using errcode='55000';
    end if;
    return old;
  end if;
  if old.status='locked' and new is distinct from old then
    raise exception 'locked_market_price_immutable' using errcode='55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_reject_locked_price_book_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_price_book_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_book_id uuid;
  v_locked_at timestamptz;
begin
  if tg_table_name = 'price_books' then
    if old.locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
      raise exception 'Publicerad prislista är låst och får inte ändras.' using errcode = '55000';
    end if;
  else
    v_book_id := coalesce(old.price_book_id, new.price_book_id);
    select locked_at into v_locked_at from public.price_books where id = v_book_id;
    if v_locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
      raise exception 'Rad i låst prislista får inte ändras.' using errcode = '55000';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_price_child_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_price_child_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
