--
-- Name: gridex_staff_support_event(uuid, uuid, uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_staff_support_event(p_company_id uuid, p_case_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_api_client_id uuid, p_event_type text, p_message text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE v_case public.customer_cases%ROWTYPE; v_event public.customer_case_events%ROWTYPE; v_payload jsonb;
BEGIN
  PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'cases.write');
  SELECT * INTO v_case FROM public.customer_cases WHERE company_id=p_company_id AND id=p_case_id
    AND customer_id=p_customer_id AND metadata->>'support_case'='true' AND case_type='other' AND strpos(source,'tenant_support_')=1 AND NOT billing_blocked AND NOT billing_manual_review AND NOT cancellation_required FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'support_case_not_found' USING ERRCODE='P0002'; END IF;
  IF p_event_type NOT IN ('support_staff_reply','support_internal_note','support_phone_interaction') OR p_event_type IS NULL
    OR p_message IS NULL OR length(btrim(p_message)) NOT BETWEEN 1 AND 20000 THEN
    RAISE EXCEPTION 'support_event_invalid' USING ERRCODE='22023';
  END IF;
  v_payload:=coalesce(p_payload,'{}'::jsonb)||jsonb_build_object('channel','staff_api','api_client_id',p_api_client_id,
    'actor_user_id',p_actor_user_id,'author_type','staff',
    'visibility',CASE WHEN p_event_type='support_staff_reply' THEN 'customer' ELSE 'internal' END);
  INSERT INTO public.customer_case_events(company_id,customer_case_id,customer_id,event_type,event_status,message,payload,created_by)
    VALUES(p_company_id,p_case_id,p_customer_id,p_event_type,'info',p_message,v_payload,p_actor_user_id)
    RETURNING * INTO v_event;
  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,metadata)
    VALUES(p_company_id,p_actor_user_id,'customer_case',p_case_id::text,'support_'||p_event_type,
      jsonb_build_object('channel','staff_api','api_client_id',p_api_client_id,'customer_id',p_customer_id,'event_id',v_event.id));
  RETURN to_jsonb(v_event);
END$$;

--
-- Name: gridex_staff_tenant_onboarding_ready_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_staff_tenant_onboarding_ready_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 PERFORM public.gridex_staff_identity_registration_v1(p_command,true); RETURN 'true'::jsonb;
END $$;

--
-- Name: gridex_staff_update_customer_case_status(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_staff_update_customer_case_status(p_company_id uuid, p_case_id uuid, p_actor_user_id uuid, p_api_client_id uuid, p_status text, p_expected_source text DEFAULT NULL::text, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'cases.write');
  PERFORM 1 FROM public.customer_cases WHERE company_id=p_company_id AND id=p_case_id
    AND metadata->>'support_case'='true' AND case_type='other' AND strpos(source,'tenant_support_')=1 AND NOT billing_blocked AND NOT billing_manual_review AND NOT cancellation_required AND (p_expected_source IS NULL OR source=p_expected_source) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'support_case_not_found' USING ERRCODE='P0002'; END IF;
  RETURN public.gridex_update_customer_case_status_with_actor_v1(p_case_id,p_company_id,p_status,p_actor_user_id,
    p_expected_source,p_message,'staff_api',p_api_client_id);
END$$;

--
-- Name: gridex_stage_energy_geodata_feature(uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_stage_energy_geodata_feature(p_geodata_version_id uuid, p_feature_id text, p_properties jsonb, p_geometry_geojson jsonb, p_source_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'energy_geodata_stage_service_role_required' using errcode='42501';
  end if;
  if p_geodata_version_id is null or nullif(btrim(p_feature_id),'') is null
     or p_geometry_geojson is null or jsonb_typeof(p_geometry_geojson)<>'object' then
    raise exception 'invalid_energy_geodata_feature' using errcode='22023';
  end if;
  if not exists (
    select 1 from public.energy_geodata_versions
    where id=p_geodata_version_id and provider='svk_arcgis' and status='importing'
  ) then
    raise exception 'energy_geodata_version_not_importing' using errcode='55000';
  end if;
  insert into public.energy_geodata_features_staging(
    geodata_version_id,feature_id,source_url,properties,geometry_geojson,updated_at
  ) values (
    p_geodata_version_id,btrim(p_feature_id),p_source_url,coalesce(p_properties,'{}'::jsonb),p_geometry_geojson,now()
  )
  on conflict(geodata_version_id,feature_id) do update set
    source_url=excluded.source_url,
    properties=excluded.properties,
    geometry_geojson=excluded.geometry_geojson,
    updated_at=now()
  returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: gridex_stage_energy_geodata_features_v2(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_stage_energy_geodata_features_v2(p_geodata_version_id uuid, p_features jsonb) RETURNS TABLE(rows_received integer, rows_upserted integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare v_received integer; v_upserted integer;
begin
 if p_geodata_version_id is null or p_features is null or jsonb_typeof(p_features)<>'array' or jsonb_array_length(p_features)<1 or jsonb_array_length(p_features)>1000 then raise exception using errcode='22023',message='invalid_energy_geodata_feature_batch'; end if;
 if not exists(select 1 from public.energy_geodata_versions where id=p_geodata_version_id and provider='svk_arcgis' and status='importing') then raise exception using errcode='55000',message='energy_geodata_version_not_importing'; end if;
 select count(*)::integer into v_received from jsonb_array_elements(p_features);
 if exists(select 1 from jsonb_to_recordset(p_features) f(feature_id text,properties jsonb,geometry_geojson jsonb,source_url text) where nullif(btrim(feature_id),'') is null or geometry_geojson is null or jsonb_typeof(geometry_geojson)<>'object') then raise exception using errcode='22023',message='invalid_energy_geodata_feature'; end if;
 insert into public.energy_geodata_features_staging(geodata_version_id,feature_id,source_url,properties,geometry_geojson,updated_at)
 select p_geodata_version_id,btrim(f.feature_id),nullif(btrim(coalesce(f.source_url,'')),''),coalesce(f.properties,'{}'::jsonb),f.geometry_geojson,now() from jsonb_to_recordset(p_features) f(feature_id text,properties jsonb,geometry_geojson jsonb,source_url text)
 on conflict(geodata_version_id,feature_id) do update set source_url=excluded.source_url,properties=excluded.properties,geometry_geojson=excluded.geometry_geojson,updated_at=now();
 get diagnostics v_upserted=row_count; return query select v_received,v_upserted;
end $$;

--
-- Name: gridex_store_billing_underlay(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_store_billing_underlay(p_company_id uuid, p_underlay jsonb, p_items jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE item jsonb;basis jsonb;legal_basis jsonb;rows_basis jsonb:='[]';source_basis jsonb;basis_hash text;total numeric:=0;u public.billing_underlays%rowtype;
 n public.normalized_metering_values%rowtype;sp public.customer_supply_periods%rowtype;ct public.customer_contracts%rowtype;price public.contract_price_snapshots%rowtype;pv public.price_plan_versions%rowtype;
 prior gridex_billing_source.underlay_bindings%rowtype;stored_id uuid;start_at timestamptz;end_at timestamptz;ready boolean;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_underlay IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'billing_underlay_scope_required' USING ERRCODE='22023'; END IF;
 start_at:=(p_underlay->>'billing_period_start')::timestamptz;end_at:=(p_underlay->>'billing_period_end')::timestamptz;
 IF start_at IS NULL OR end_at IS NULL OR end_at<=start_at THEN RAISE EXCEPTION 'billing_underlay_exact_period_required' USING ERRCODE='22023'; END IF;
 ready:=p_underlay->>'status'='validated' OR p_underlay->>'readiness_status'='ready';
 PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':billing-underlay-batch',0));
 SELECT * INTO u FROM public.billing_underlays WHERE company_id=p_company_id AND customer_id=(p_underlay->>'customer_id')::uuid AND metering_point_id=(p_underlay->>'metering_point_id')::uuid
  AND underlay_year=(p_underlay->>'underlay_year')::integer AND underlay_month=(p_underlay->>'underlay_month')::integer
  AND billing_period_start=(start_at AT TIME ZONE 'Europe/Stockholm')::date AND billing_period_end=(end_at AT TIME ZONE 'Europe/Stockholm')::date AND energy_direction=p_underlay->>'energy_direction';
 PERFORM public.ediel_require_invoice_source_copies_available_v1(p_company_id,(p_underlay->>'id')::uuid);
SELECT * INTO prior FROM gridex_billing_source.underlay_bindings WHERE underlay_id=u.id;
 IF NOT ready THEN
  PERFORM 1 FROM public.billing_underlays WHERE id=u.id FOR UPDATE;
  IF prior.underlay_id IS NOT NULL THEN RAISE EXCEPTION 'billing_source_finalized_underlay_requires_correction' USING ERRCODE='55000'; END IF;
  RETURN gridex_billing_source.gridex_store_billing_underlay_before_source_v2(p_company_id,p_underlay,p_items,p_actor_user_id);
 END IF;
 IF jsonb_array_length(p_items)=0 OR (SELECT count(DISTINCT value->>'source_normalized_metering_value_id') FROM jsonb_array_elements(p_items))<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'billing_underlay_unique_sources_required'; END IF;
 PERFORM gridex_billing_source.lock_values_v1(p_company_id,ARRAY(SELECT (value->>'source_normalized_metering_value_id')::uuid FROM jsonb_array_elements(p_items)),(p_underlay->>'supply_period_id')::uuid);
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=(p_underlay->>'supply_period_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO ct FROM public.customer_contracts WHERE id=(p_underlay->>'contract_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO price FROM public.contract_price_snapshots WHERE id=(p_underlay->>'contract_price_snapshot_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO pv FROM public.price_plan_versions WHERE id=price.price_plan_version_id AND company_id=p_company_id FOR SHARE;
 IF sp.id IS NULL OR ct.id IS NULL OR price.id IS NULL OR pv.id IS NULL OR pv.locked_at IS NULL OR NOT coalesce(pv.content_sha256 ~ '^[a-f0-9]{64}$',false) OR NOT coalesce(pv.status IN ('active','approved','published'),false)
  OR sp.contract_id IS DISTINCT FROM ct.id OR sp.customer_id IS DISTINCT FROM ct.customer_id OR sp.metering_point_id IS DISTINCT FROM ct.metering_point_id
  OR NOT coalesce(sp.status IN ('active','confirmed_by_grid_owner'),false) OR NOT coalesce(ct.status IN ('signed','active'),false) OR price.contract_id IS DISTINCT FROM ct.id
  OR sp.customer_id::text IS DISTINCT FROM p_underlay->>'customer_id' OR sp.metering_point_id::text IS DISTINCT FROM p_underlay->>'metering_point_id'
  OR price.id::text IS DISTINCT FROM p_underlay->>'pricing_snapshot_id' OR price.price_plan_version_id::text IS DISTINCT FROM p_underlay->>'price_plan_version_id'
  OR price.snapshot_json IS DISTINCT FROM p_underlay->'pricing_snapshot' OR price.valid_from IS NULL OR (price.valid_from::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at
  OR (price.valid_to IS NOT NULL AND ((price.valid_to+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
  OR sp.start_date IS NULL OR (sp.start_date::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at OR (sp.end_date IS NOT NULL AND ((sp.end_date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
  OR nullif(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),'') IS NULL
  OR (left(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),10)::date::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at
  OR (nullif(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),'') IS NOT NULL AND ((left(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),10)::date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
 THEN RAISE EXCEPTION 'billing_underlay_supply_contract_price_basis_required' USING ERRCODE='23514'; END IF;
 legal_basis:=gridex_received_sources.billing_supply_basis_v1(p_company_id,sp.id,start_at,end_at);
 IF legal_basis IS NULL OR legal_basis->'qualified' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'billing_underlay_qualified_supply_source_required' USING ERRCODE='23514'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'source_normalized_metering_value_id' LOOP
  SELECT * INTO n FROM public.normalized_metering_values WHERE company_id=p_company_id AND id=(item->>'source_normalized_metering_value_id')::uuid FOR SHARE;
  basis:=gridex_billing_source.basis_v1(p_company_id,n.id);
  IF basis->'qualified' IS DISTINCT FROM 'true'::jsonb OR basis->'quality' IS DISTINCT FROM 'null'::jsonb OR basis->'qualityEstablished' IS DISTINCT FROM 'true'::jsonb
   OR n.billing_gate_status IS DISTINCT FROM 'eligible' OR n.billing_status IS DISTINCT FROM 'billable' OR n.supply_period_id IS DISTINCT FROM sp.id
   OR n.customer_id IS DISTINCT FROM sp.customer_id OR n.metering_point_id IS DISTINCT FROM sp.metering_point_id OR n.period_start<start_at OR n.period_end>end_at
   OR (item->>'quantity_kwh')::numeric IS DISTINCT FROM abs(n.quantity_kwh) OR (item->>'quantity')::numeric IS DISTINCT FROM abs(n.quantity_kwh)
   OR item->>'unit' IS DISTINCT FROM 'kWh' OR item->>'product_code' IS DISTINCT FROM basis->>'productCode' OR item->>'register_code' IS DISTINCT FROM basis->>'registerCode'
   OR p_underlay->>'energy_direction' IS DISTINCT FROM (CASE WHEN n.direction='production' THEN 'production' WHEN n.quantity_kwh<0 THEN 'consumption_correction' ELSE 'consumption' END)
   OR (item->>'period_start')::timestamptz IS DISTINCT FROM n.period_start OR (item->>'period_end')::timestamptz IS DISTINCT FROM n.period_end
  THEN RAISE EXCEPTION 'billing_underlay_qualified_source_mismatch' USING ERRCODE='23514'; END IF;
  total:=total+abs(n.quantity_kwh);rows_basis:=rows_basis||jsonb_build_array(basis||jsonb_build_object('revisionNumber',n.revision_number,'supplyPeriodId',sp.id));
 END LOOP;
 IF total IS DISTINCT FROM (p_underlay->>'total_kwh')::numeric THEN RAISE EXCEPTION 'billing_underlay_exact_total_mismatch'; END IF;
 source_basis:=jsonb_build_object('values',rows_basis,'supply',legal_basis,'contractId',ct.id,'contractStatus',ct.status,'price',to_jsonb(price),'priceVersionHash',pv.content_sha256,'energyDirection',p_underlay->>'energy_direction','start',start_at,'end',end_at);
 basis_hash:=encode(digest(convert_to(source_basis::text,'UTF8'),'sha256'),'hex');
 PERFORM 1 FROM public.billing_underlays WHERE id=u.id FOR UPDATE;
 IF prior.underlay_id IS NOT NULL THEN
  IF prior.source_basis_hash IS DISTINCT FROM basis_hash OR prior.exact_total_kwh IS DISTINCT FROM total THEN RAISE EXCEPTION 'billing_source_finalized_underlay_requires_correction' USING ERRCODE='55000'; END IF;
  RETURN prior.underlay_id;
 END IF;
 stored_id:=gridex_billing_source.gridex_store_billing_underlay_before_source_v2(p_company_id,p_underlay,p_items,p_actor_user_id);
 INSERT INTO gridex_billing_source.underlay_bindings(underlay_id,company_id,source_basis,source_basis_hash,exact_total_kwh,actor_user_id) VALUES(stored_id,p_company_id,source_basis,basis_hash,total,p_actor_user_id);
 RETURN stored_id;
END $_$;

--
-- Name: gridex_store_billing_underlay_batch(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_store_billing_underlay_batch(p_company_id uuid, p_commands jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_command jsonb;
  v_ids jsonb:='[]'::jsonb;
  v_id uuid;
begin
  if jsonb_typeof(coalesce(p_commands,'[]'::jsonb))<>'array' then
    raise exception using errcode='22023',message='billing_underlay_commands_must_be_array';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':billing-underlay-batch',0));
  for v_command in select value from jsonb_array_elements(coalesce(p_commands,'[]'::jsonb)) loop
    v_id:=public.gridex_store_billing_underlay(
      p_company_id,
      coalesce(v_command->'underlay','{}'::jsonb),
      coalesce(v_command->'items','[]'::jsonb),
      p_actor_user_id
    );
    v_ids:=v_ids||jsonb_build_array(v_id::text);
  end loop;
  return v_ids;
end
$$;

--
-- Name: gridex_submit_customer_move_out_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_submit_customer_move_out_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_customer_id uuid := nullif(p_command->>'customer_id', '')::uuid;
  v_api_client_id uuid := nullif(p_command->>'api_client_id', '')::uuid;
  v_idempotency_key text :=
    nullif(btrim(coalesce(p_command->>'idempotency_key', '')), '');
  v_facility_reference text :=
    nullif(btrim(coalesce(p_command->>'facility_reference', '')), '');
  v_contract_reference text :=
    nullif(btrim(coalesce(
      p_command->>'customer_contract_reference',
      ''
    )), '');
  v_requested_date date :=
    nullif(p_command->>'requested_move_out_date', '')::date;
  v_request_hash text :=
    md5((p_command - 'idempotency_key')::text);
  v_site public.customer_sites%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_existing public.customer_portal_completions%rowtype;
  v_completion public.customer_portal_completions%rowtype;
  v_customer_reference text;
  v_case_id uuid;
  v_event_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'customer_move_out_service_role_required';
  end if;
  if v_company_id is null
     or v_customer_id is null
     or v_api_client_id is null
     or v_idempotency_key is null
     or length(v_idempotency_key) not between 8 and 200
     or v_facility_reference is null
     or v_requested_date is null then
    raise exception using
      errcode = '22023',
      message = 'customer_move_out_command_invalid';
  end if;
  if v_requested_date < current_date
     or v_requested_date > current_date + 730 then
    raise exception using
      errcode = '22023',
      message = 'customer_move_out_date_invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    v_company_id::text || ':' || v_api_client_id::text || ':' ||
      v_customer_id::text || ':' || v_idempotency_key,
    0
  ));

  select coalesce(
    nullif(customer.external_customer_id, ''),
    nullif(customer.customer_number, '')
  )
  into v_customer_reference
  from public.customers customer
  where customer.id = v_customer_id
    and customer.company_id = v_company_id;
  if not found or v_customer_reference is null then
    raise exception using
      errcode = 'P0002',
      message = 'customer_move_out_customer_not_found';
  end if;

  select completion.*
  into v_existing
  from public.customer_portal_completions completion
  where completion.company_id = v_company_id
    and completion.api_client_id = v_api_client_id
    and completion.customer_id = v_customer_id
    and completion.completion_type = 'move_out'
    and completion.idempotency_key = v_idempotency_key
  limit 1;

  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception using
        errcode = '23505',
        message = 'customer_move_out_idempotency_conflict';
    end if;
    return jsonb_build_object(
      'completion_reference', v_existing.completion_reference,
      'customer_reference', v_customer_reference,
      'facility_reference', v_facility_reference,
      'contract_reference', v_contract_reference,
      'requested_move_out_date', v_requested_date,
      'status', v_existing.status,
      'submitted_at', v_existing.created_at,
      'replayed', true
    );
  end if;

  select site.*
  into v_site
  from public.customer_sites site
  where site.company_id = v_company_id
    and site.customer_id = v_customer_id
    and site.facility_reference = v_facility_reference
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'customer_move_out_facility_not_found';
  end if;

  if v_contract_reference is not null then
    select contract.*
    into v_contract
    from public.customer_contracts contract
    where contract.company_id = v_company_id
      and contract.customer_id = v_customer_id
      and contract.customer_contract_reference = v_contract_reference
      and coalesce(contract.customer_site_id, contract.site_id) = v_site.id
    for share;
    if not found then
      raise exception using
        errcode = 'P0002',
        message = 'customer_move_out_contract_not_found';
    end if;
    if v_contract.status not in (
      'signed',
      'active',
      'pending_activation',
      'pending_switch'
    ) then
      raise exception using
        errcode = '23514',
        message = 'customer_move_out_contract_status_invalid';
    end if;
  end if;

  insert into public.customer_portal_completions(
    company_id,
    customer_id,
    site_id,
    completion_type,
    status,
    submitted_payload,
    result_payload,
    api_client_id,
    idempotency_key,
    request_hash
  ) values (
    v_company_id,
    v_customer_id,
    v_site.id,
    'move_out',
    'submitted',
    jsonb_build_object(
      'facility_reference', v_facility_reference,
      'customer_contract_reference', v_contract_reference,
      'requested_move_out_date', v_requested_date,
      'reason', nullif(p_command->>'reason', ''),
      'new_address', coalesce(p_command->'new_address', '{}'::jsonb),
      'contact_details', coalesce(p_command->'contact_details', '{}'::jsonb),
      'metadata', coalesce(p_command->'metadata', '{}'::jsonb)
    ),
    jsonb_build_object(
      'requested_move_out_date', v_requested_date,
      'workflow_status', 'submitted'
    ),
    v_api_client_id,
    v_idempotency_key,
    v_request_hash
  )
  returning * into v_completion;

  insert into public.customer_cases(
    company_id,
    customer_id,
    site_id,
    customer_contract_id,
    case_type,
    status,
    priority,
    title,
    description,
    next_action,
    source,
    metadata
  ) values (
    v_company_id,
    v_customer_id,
    v_site.id,
    v_contract.id,
    'other',
    'open',
    'normal',
    'Utflyttningsanmälan',
    'Kunden har registrerat utflyttning via kundportal-API.',
    'review_move_out_submission',
    'customer_portal_api',
    jsonb_build_object(
      'completion_reference', v_completion.completion_reference,
      'facility_reference', v_facility_reference,
      'requested_move_out_date', v_requested_date
    )
  )
  returning id into v_case_id;

  update public.customer_portal_completions
  set linked_case_id = v_case_id,
      updated_at = now()
  where id = v_completion.id;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    subject_customer_id,
    source,
    idempotency_key,
    payload
  ) values (
    v_company_id,
    'customer.move_out_submitted',
    'customer_move_out',
    v_completion.completion_reference,
    v_customer_id,
    'customer_portal_api',
    'customer-move-out:' || v_company_id::text || ':' ||
      v_api_client_id::text || ':' || v_idempotency_key,
    jsonb_build_object(
      'completion_reference', v_completion.completion_reference,
      'facility_reference', v_facility_reference,
      'customer_contract_reference', v_contract_reference,
      'requested_move_out_date', v_requested_date,
      'status', 'submitted'
    )
  )
  returning id into v_event_id;

  insert into public.event_outbox(
    company_id,
    domain_event_id,
    destination_type,
    destination_key,
    payload
  ) values (
    v_company_id,
    v_event_id,
    'internal',
    'customer.move_out_submitted',
    jsonb_build_object(
      'event_reference', v_event_id,
      'completion_reference', v_completion.completion_reference
    )
  )
  on conflict do nothing;

  insert into public.audit_logs(
    company_id,
    actor_user_id,
    entity_type,
    entity_id,
    action,
    new_values,
    metadata
  ) values (
    v_company_id,
    null,
    'customer_move_out',
    v_completion.completion_reference,
    'customer.move_out_submitted',
    jsonb_build_object(
      'facility_reference', v_facility_reference,
      'customer_contract_reference', v_contract_reference,
      'requested_move_out_date', v_requested_date,
      'status', 'submitted'
    ),
    jsonb_build_object(
      'api_client_id', v_api_client_id,
      'idempotency_key_hash', md5(v_idempotency_key)
    )
  );

  return jsonb_build_object(
    'completion_reference', v_completion.completion_reference,
    'customer_reference', v_customer_reference,
    'facility_reference', v_facility_reference,
    'contract_reference', v_contract_reference,
    'requested_move_out_date', v_requested_date,
    'status', v_completion.status,
    'submitted_at', v_completion.created_at,
    'replayed', false
  );
end
$$;

--
-- Name: FUNCTION gridex_submit_customer_move_out_v1(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_submit_customer_move_out_v1(p_command jsonb) IS 'Tenant/customer-bound move-out submission using stable public references. The case, domain event, outbox and audit record commit atomically and replay by idempotency key.';

--
-- Name: gridex_supply_end_followup_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_supply_end_followup_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_end date := coalesce(NEW.actual_end_date, NEW.end_date);
  v_key text := 'source-end:' || NEW.id::text || ':' || coalesce(NEW.actual_end_date, NEW.end_date)::text;
  v_contract public.customer_contracts%rowtype;
  v_contract_id uuid := coalesce(NEW.customer_contract_id, NEW.contract_id);
  v_binding_end date;
BEGIN
  IF v_end IS NULL OR NEW.company_id IS NULL OR NEW.customer_id IS NULL
   OR coalesce(NEW.metadata->>'end_key','') <> ''
   OR NEW.status NOT IN ('ending','ended')
   OR (OLD.end_date IS NOT DISTINCT FROM NEW.end_date AND OLD.actual_end_date IS NOT DISTINCT FROM NEW.actual_end_date AND OLD.status IN ('ending','ended')) THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.customer_operation_tasks t WHERE t.company_id = NEW.company_id AND t.customer_id = NEW.customer_id
     AND t.task_type = 'final_invoice_pending' AND t.metadata->>'end_key' = v_key) THEN
    RETURN NEW;
  END IF;

  IF v_contract_id IS NOT NULL THEN
    SELECT * INTO v_contract FROM public.customer_contracts
     WHERE id = v_contract_id AND company_id = NEW.company_id AND customer_id = NEW.customer_id FOR UPDATE;
    IF FOUND AND v_contract.status IN ('signed','active') AND NOT EXISTS (
      SELECT 1 FROM public.customer_supply_periods other
       WHERE other.company_id = NEW.company_id AND coalesce(other.customer_contract_id, other.contract_id) = v_contract_id
         AND other.id <> NEW.id AND other.status IN ('active','confirmed_by_grid_owner')
         AND (coalesce(other.actual_end_date, other.end_date) IS NULL OR coalesce(other.actual_end_date, other.end_date) > v_end)) THEN
      BEGIN
        PERFORM public.gridex_record_customer_contract_event_v1(NEW.company_id, v_contract_id, NEW.customer_id, 'terminated', now(),
          'Avtalet upphörde eftersom leveransen till anläggningen upphörde.',
          jsonb_build_object('ends_at', v_end, 'termination_notice_date', now(), 'termination_reason', 'supply_end',
            'reason_code', 'supply_end', 'source_message_id', NEW.source_message_id),
          NULL, NULL, 'supply-end:' || v_contract_id::text || ':' || v_key);
      EXCEPTION WHEN OTHERS THEN
        -- The received supply end stands; a person ends the contract.
        INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
        VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'contract_end_review', 'open', 'high',
          'Avsluta avtal efter leveransslut',
          'Leveransen har upphört men avtalet kunde inte avslutas automatiskt. Kontrollera och avsluta avtalet.',
          jsonb_build_object('contract_id', v_contract_id, 'supply_end_date', v_end, 'end_key', v_key, 'reason', SQLERRM));
      END;
      IF coalesce(v_contract.binding_months, 0) > 0 AND v_contract.starts_at IS NOT NULL THEN
        v_binding_end := (v_contract.starts_at + make_interval(months => v_contract.binding_months))::date;
        IF v_binding_end > v_end THEN
          INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
          VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'break_fee_review', 'open', 'normal',
            'Bedöm brytavgift vid leveransslut',
            'Leveransen upphörde före bindningstidens slut. Bedöm om avtalet medger en brytavgift; inget debiteras automatiskt.',
            jsonb_build_object('contract_id', v_contract_id, 'binding_months', v_contract.binding_months,
              'binding_ends_at', v_binding_end, 'supply_end_date', v_end, 'end_key', v_key));
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
  VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'final_invoice_pending', 'open', 'high', 'Slutfaktura',
    'Leveransen upphör ' || to_char(v_end, 'YYYY-MM-DD') || '. Invänta slutavläsningen och fakturera perioden till och med slutdatumet.',
    jsonb_build_object('supply_end_date', v_end, 'end_reason', 'supply_end', 'end_key', v_key, 'supply_period_id', NEW.id));
  RETURN NEW;
END $$;

--
-- Name: gridex_supported_price_areas_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_supported_price_areas_v1(p_contract_product_version_id uuid) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when cardinality(coalesce(v.price_areas,'{}'::text[]))>0 then (
      select coalesce(array_agg(distinct upper(btrim(area))
        order by upper(btrim(area))),'{}'::text[])
      from unnest(v.price_areas) area
      where upper(btrim(area)) in ('SE1','SE2','SE3','SE4')
    )
    when v.contract_type='fixed' then array['SE1','SE2','SE3','SE4']::text[]
    else '{}'::text[]
  end
  from public.contract_product_versions v
  where v.id=p_contract_product_version_id
$$;

--
-- Name: gridex_suppress_retired_onboarding_outbox_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_suppress_retired_onboarding_outbox_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.destination_type='internal'
     and new.destination_key='customer-onboarding-orchestrator' then
    return null;
  end if;
  return new;
end
$$;

--
-- Name: gridex_sync_company_legal_profile_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_company_legal_profile_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.gridex_upsert_company_legal_profile_defaults(new.id);
  return new;
end $$;

--
-- Name: gridex_sync_company_legal_profile_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_company_legal_profile_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('gridex.skip_legal_profile_sync',true)='on' then return new; end if;
  perform public.gridex_rebuild_company_legal_profile(new.id,new.updated_by,false);
  return new;
end $$;

--
-- Name: gridex_sync_company_lifecycle_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_company_lifecycle_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.lifecycle_status := case new.status
    when 'active' then 'active'
    when 'onboarding' then 'onboarding'
    when 'paused' then 'suspended'
    when 'suspended' then 'suspended'
    when 'archived' then 'closing'
    when 'pending_deletion' then 'closing'
    when 'closed' then 'closed'
    when 'deleted_test_only' then 'closed'
    else coalesce(new.lifecycle_status, 'creating')
  end;
  return new;
end
$$;

--
-- Name: gridex_sync_internal_offer_to_canonical(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_internal_offer_to_canonical(p_offer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_product_id uuid;
  v_version_id uuid;
  v_assignment_id uuid;
  v_snapshot jsonb;
  v_hash text;
  v_number integer;
  v_required text[];
  v_legal_version_id uuid;
  v_production_enabled boolean:=false;
  v_sellable boolean:=false;
  v_product_status text;
  v_internal_allowed boolean:=true;
begin
  select * into o from public.contract_offers where id=p_offer_id for update;
  if not found or o.company_id is null then return null; end if;

  v_product_id:=o.contract_product_id;
  if v_product_id is null and o.supersedes_offer_id is not null then
    select contract_product_id into v_product_id
    from public.contract_offers where id=o.supersedes_offer_id;
  end if;
  if v_product_id is null then
    select id into v_product_id
    from public.contract_products
    where company_id=o.company_id and product_code='contract:'||o.version_series_id::text
    limit 1;
  end if;

  v_product_status:=case
    when o.lifecycle_status='published' then 'active'
    when o.lifecycle_status='archived' then 'archived'
    when exists(
      select 1 from public.contract_offers sibling
      where sibling.company_id=o.company_id
        and sibling.version_series_id=o.version_series_id
        and sibling.id<>o.id
        and sibling.lifecycle_status='published'
        and sibling.is_active
    ) then 'active'
    when o.lifecycle_status in ('draft','ready') then 'draft'
    else 'paused'
  end;

  if v_product_id is null then
    insert into public.contract_products(
      company_id,product_code,name,product_category,description,status,created_by
    ) values(
      o.company_id,'contract:'||o.version_series_id::text,o.name,'electricity',o.description,v_product_status,o.created_by
    ) returning id into v_product_id;
  else
    update public.contract_products
    set name=case when o.lifecycle_status='published'
                    or not exists(
                      select 1 from public.contract_offers sibling
                      where sibling.company_id=o.company_id
                        and sibling.version_series_id=o.version_series_id
                        and sibling.id<>o.id
                        and sibling.lifecycle_status='published'
                        and sibling.is_active
                    ) then o.name else name end,
        description=case when o.lifecycle_status='published'
                    or not exists(
                      select 1 from public.contract_offers sibling
                      where sibling.company_id=o.company_id
                        and sibling.version_series_id=o.version_series_id
                        and sibling.id<>o.id
                        and sibling.lifecycle_status='published'
                        and sibling.is_active
                    ) then o.description else description end,
        status=v_product_status,
        updated_at=now()
    where id=v_product_id and company_id=o.company_id;
  end if;

  v_production_enabled:=coalesce((o.commercial_snapshot#>>'{production,enabled}')::boolean,false);
  v_required:=public.gridex_required_legal_modules(
    o.customer_type,o.contract_type,'internal',coalesce(o.automatic_renewal,false),
    coalesce(o.power_of_attorney_required,true),v_production_enabled
  );

  -- Lifecycle/publication state is intentionally excluded from the immutable
  -- commercial hash. Publishing an unchanged draft must lock the same version,
  -- not create a second price/product version only because status changed.
  v_snapshot:=(coalesce(o.commercial_snapshot,'{}'::jsonb)-'lifecycle_status')||jsonb_strip_nulls(jsonb_build_object(
    'schema','gridex_contract_product_version_v5',
    'version_series_id',o.version_series_id,
    'legacy_contract_offer_id',o.id,
    'supersedes_offer_id',o.supersedes_offer_id,
    'company_id',o.company_id,
    'name',o.name,
    'customer_type',o.customer_type,
    'contract_type',o.contract_type,
    'energy_direction',coalesce(nullif(lower(o.energy_direction),''),'consumption'),
    'price_plan_id',o.price_plan_id,
    'price_plan_version_id',o.price_plan_version_id,
    'price_book_id',o.price_book_id,
    'price_version',o.price_version,
    'terms_version',o.terms_version,
    'valid_from',o.valid_from,
    'valid_to',o.valid_to,
    'max_customers',o.max_customers,
    'discount_value',o.discount_value,
    'discount_unit',o.discount_unit,
    'discount_months',o.discount_months,
    'discount_calculation_base',o.discount_calculation_base,
    'discount_starts_on_mode',o.discount_starts_on_mode,
    'automatic_renewal',o.automatic_renewal,
    'automatic_renewal_term_months',o.automatic_renewal_term_months,
    'power_of_attorney_required',o.power_of_attorney_required,
    'power_of_attorney_mode',o.power_of_attorney_mode,
    'optional_fees',coalesce(o.optional_fee_lines,'[]'::jsonb),
    'required_legal_modules',v_required,
    'legal_source','legal_template_versions'
  ));
  v_hash:=encode(digest(v_snapshot::text,'sha256'),'hex');

  select id into v_version_id
  from public.contract_product_versions
  where contract_product_id=v_product_id and content_sha256=v_hash
  limit 1;

  if v_version_id is null then
    select coalesce(max(version_number),0)+1 into v_number
    from public.contract_product_versions where contract_product_id=v_product_id;

    insert into public.contract_product_versions(
      contract_product_id,version_number,customer_type,contract_type,energy_direction,pricing_model,
      price_plan_id,price_plan_version_id,binding_months,notice_months,price_areas,
      automatic_renewal,power_of_attorney_required,required_legal_modules,
      commercial_snapshot,content_sha256,status,approved_at,approved_by,locked_at,created_by
    ) values(
      v_product_id,v_number,o.customer_type,o.contract_type,
      coalesce(nullif(lower(o.energy_direction),''),'consumption'),
      coalesce(v_snapshot->>'pricing_model',o.contract_type),o.price_plan_id,o.price_plan_version_id,
      o.default_binding_months,o.default_notice_months,
      coalesce(array(select jsonb_array_elements_text(coalesce(v_snapshot->'price_areas','[]'::jsonb))),'{}'::text[]),
      coalesce(o.automatic_renewal,false),coalesce(o.power_of_attorney_required,true),v_required,
      v_snapshot,v_hash,
      case when o.lifecycle_status='published' then 'approved' else 'draft' end,
      case when o.lifecycle_status='published' then now() end,
      case when o.lifecycle_status='published' then o.updated_by end,
      case when o.lifecycle_status='published' then now() end,
      o.created_by
    ) returning id into v_version_id;
  elsif o.lifecycle_status='published' then
    perform set_config('gridex.version_transition','on',true);
    update public.contract_product_versions
    set status='approved',approved_at=coalesce(approved_at,now()),approved_by=coalesce(approved_by,o.updated_by),locked_at=coalesce(locked_at,now())
    where id=v_version_id and (status<>'approved' or locked_at is null);
  end if;

  v_sellable:=o.lifecycle_status='published'
    and (o.valid_from is null or o.valid_from<=current_date)
    and (o.valid_to is null or o.valid_to>=current_date);

  if o.lifecycle_status='published' then
    -- Internal publication moves only the internal sales channel. Website/API
    -- channels on the predecessor remain live until that exact channel is
    -- explicitly published for the successor, preventing a sales outage.
    update public.tenant_contract_channels ch
    set status='ended',valid_to=coalesce(ch.valid_to,now()),updated_at=now()
    from public.tenant_contract_assignments ta
    join public.contract_product_versions oldv on oldv.id=ta.contract_product_version_id
    where ch.assignment_id=ta.id and ta.company_id=o.company_id
      and oldv.contract_product_id=v_product_id
      and ta.contract_product_version_id<>v_version_id
      and ch.channel='internal'
      and ch.status in ('active','paused');

    update public.tenant_contract_assignments ta
    set internal_sales_allowed=false,
        status=case when exists(
          select 1 from public.tenant_contract_channels remaining
          where remaining.assignment_id=ta.id and remaining.status='active'
            and (remaining.valid_from is null or remaining.valid_from<=now())
            and (remaining.valid_to is null or remaining.valid_to>=now())
        ) then 'active' else 'ended' end,
        valid_to=case when exists(
          select 1 from public.tenant_contract_channels remaining
          where remaining.assignment_id=ta.id and remaining.status='active'
            and (remaining.valid_from is null or remaining.valid_from<=now())
            and (remaining.valid_to is null or remaining.valid_to>=now())
        ) then ta.valid_to else coalesce(ta.valid_to,current_date) end,
        updated_at=now()
    from public.contract_product_versions oldv
    where oldv.id=ta.contract_product_version_id and ta.company_id=o.company_id
      and oldv.contract_product_id=v_product_id
      and ta.contract_product_version_id<>v_version_id;

    v_legal_version_id:=public.gridex_materialize_legal_bundle_version(
      o.company_id,v_version_id,null,o.updated_by
    );
    if exists(
      select 1 from public.legal_bundle_versions
      where id=v_legal_version_id and cardinality(unresolved_variables)>0
    ) then
      raise exception using errcode='23514',message='internal_offer_legal_documents_not_ready';
    end if;
    perform set_config('gridex.version_transition','on',true);
    update public.legal_bundle_versions
    set status='published',published_at=coalesce(published_at,now()),locked_at=coalesce(locked_at,now())
    where id=v_legal_version_id and locked_at is null;
  else
    v_legal_version_id:=o.legal_bundle_version_id;
  end if;

  insert into public.tenant_contract_assignments(
    company_id,contract_product_version_id,internal_sales_allowed,website_publication_allowed,
    status,legal_mode,valid_from,valid_to,assigned_by
  ) values(
    o.company_id,v_version_id,true,false,
    case when v_sellable then 'active' else 'paused' end,
    coalesce((select legal_mode from public.legal_bundle_versions where id=v_legal_version_id),'ops_standard'),
    o.valid_from,o.valid_to,o.updated_by
  )
  on conflict(company_id,contract_product_version_id) do update set
    -- Preserve explicit channel grants/denials. Canonical synchronization may
    -- repair lifecycle metadata but must never silently re-grant a channel.
    internal_sales_allowed=tenant_contract_assignments.internal_sales_allowed,
    website_publication_allowed=tenant_contract_assignments.website_publication_allowed,
    status=excluded.status,
    legal_mode=excluded.legal_mode,
    valid_from=excluded.valid_from,
    valid_to=excluded.valid_to,
    updated_at=now()
  returning id,internal_sales_allowed into v_assignment_id,v_internal_allowed;

  insert into public.tenant_contract_channels(
    assignment_id,channel,status,valid_from,valid_to,marketing_content,updated_by
  ) values(
    v_assignment_id,'internal',case when v_sellable and v_internal_allowed then 'active' else 'paused' end,
    o.valid_from::timestamptz,
    case when o.valid_to is null then null else (o.valid_to + 1)::timestamptz end,
    jsonb_build_object(
      'name',o.name,'version_series_id',o.version_series_id,
      'source_of_truth','contract_product_versions'
    ),o.updated_by
  )
  on conflict(assignment_id,channel) do update set
    status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,
    marketing_content=excluded.marketing_content,updated_by=excluded.updated_by,updated_at=now();

  update public.contract_offers
  set contract_product_id=v_product_id,
      contract_product_version_id=v_version_id,
      legal_bundle_version_id=v_legal_version_id,
      legal_bundle_id=null,
      updated_at=now()
  where id=o.id;

  return v_version_id;
end $$;

--
-- Name: gridex_sync_internal_offer_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_internal_offer_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth()=1 then perform public.gridex_sync_internal_offer_to_canonical(new.id); end if;
  return new;
end $$;

--
-- Name: gridex_sync_poa_expires_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_poa_expires_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  new.expires_at := coalesce(
    new.valid_to,
    case when new.valid_until is null then null
         else new.valid_until::timestamp at time zone 'UTC'
    end
  );
  return new;
end;
$$;

--
-- Name: gridex_sync_portfolio_monthly_prices_for_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_portfolio_monthly_prices_for_version(p_price_plan_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_version record; v_row jsonb; v_month text; v_area text; v_amount numeric; v_existing_id uuid; v_existing_price numeric; v_existing_locked timestamptz; v_status text;
begin
  select * into v_version from public.price_plan_versions where id=p_price_plan_version_id;
  if v_version.id is null then raise exception 'price_plan_version_missing'; end if;
  if jsonb_typeof(coalesce(v_version.snapshot_json,'{}'::jsonb)->'portfolio_monthly_prices') is distinct from 'array' then return; end if;
  v_status:=case when v_version.status in ('published','active','approved') and v_version.locked_at is not null then 'published' else 'draft' end;
  for v_row in select value from jsonb_array_elements(v_version.snapshot_json->'portfolio_monthly_prices') loop
    v_month:=left(coalesce(v_row->>'period_month',v_row->>'billing_month',''),7);
    v_area:=upper(coalesce(v_row->>'price_area_code',v_row->>'price_area',''));
    v_amount:=nullif(coalesce(v_row->>'amount_ore_per_kwh',v_row->>'amount'),'')::numeric;
    if v_month !~ '^\d{4}-\d{2}$' or v_area not in ('SE1','SE2','SE3','SE4') or v_amount is null then
      raise exception 'invalid_portfolio_monthly_price_snapshot';
    end if;
    v_existing_id:=null; v_existing_price:=null; v_existing_locked:=null;
    select id,price_ex_vat_sek_per_kwh,locked_at into v_existing_id,v_existing_price,v_existing_locked
    from public.portfolio_monthly_prices
      where price_plan_version_id=v_version.id and price_area=v_area and billing_month=v_month
        and superseded_at is null and status<>'superseded' limit 1;
    if v_existing_id is not null then
      if v_existing_locked is not null then
        if abs(v_existing_price-(v_amount/100))>0.00000001 then
          raise exception 'locked_portfolio_monthly_price_snapshot_mismatch';
        end if;
      else
        update public.portfolio_monthly_prices set
          price_plan_id=v_version.price_plan_id,price_ex_vat_sek_per_kwh=v_amount/100,
          status=v_status,source='contract_price_version',approved_at=case when v_status='published' then coalesce(v_version.approved_at,now()) end,
          confirmed_at=case when v_status='published' then coalesce(v_version.approved_at,now()) end,
          published_at=case when v_status='published' then coalesce(v_version.published_at,now()) end,
          locked_at=case when v_status='published' then coalesce(v_version.locked_at,now()) end,
          calculation_snapshot=jsonb_build_object('amount_ore_per_kwh',v_amount,'unit','ore_per_kwh','vat_included',false,'price_plan_version_id',v_version.id),updated_at=now()
        where id=v_existing_id;
      end if;
    else
      insert into public.portfolio_monthly_prices(
        company_id,price_plan_id,price_plan_version_id,price_area,billing_month,price_ex_vat_sek_per_kwh,currency,status,source,notes,version_number,
        approved_at,confirmed_at,published_at,locked_at,calculation_snapshot,created_by,updated_by
      ) values(
        v_version.company_id,v_version.price_plan_id,v_version.id,v_area,v_month,v_amount/100,'SEK',v_status,'contract_price_version',
        'Materialiserad från låst price_plan_version.snapshot_json',coalesce(v_version.version_number,1),
        case when v_status='published' then coalesce(v_version.approved_at,now()) end,case when v_status='published' then coalesce(v_version.approved_at,now()) end,
        case when v_status='published' then coalesce(v_version.published_at,now()) end,case when v_status='published' then coalesce(v_version.locked_at,now()) end,
        jsonb_build_object('amount_ore_per_kwh',v_amount,'unit','ore_per_kwh','vat_included',false,'price_plan_version_id',v_version.id),v_version.created_by,v_version.created_by
      );
    end if;
  end loop;
end $_$;

--
-- Name: gridex_sync_portfolio_monthly_prices_from_version_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_portfolio_monthly_prices_from_version_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.gridex_sync_portfolio_monthly_prices_for_version(new.id);
  return new;
end $$;

--
-- Name: gridex_sync_price_component_visibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_price_component_visibility() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_metadata_visible boolean;
  v_metadata_base text;
begin
  if jsonb_typeof(coalesce(new.metadata,'{}'::jsonb)->'visibility')='object'
     and (coalesce(new.metadata,'{}'::jsonb)->'visibility') ? 'website_card' then
    v_metadata_visible:=(new.metadata#>>'{visibility,website_card}')::boolean;
    new.website_card_visible:=v_metadata_visible;
  end if;
  v_metadata_base:=nullif(new.metadata->>'calculation_base','');
  if new.calculation_base is null and v_metadata_base is not null then
    new.calculation_base:=v_metadata_base;
  end if;
  if coalesce(new.unit,'') in ('percent','percentage') and new.calculation_base is null then
    raise exception 'percentage_component_calculation_base_missing';
  end if;
  if coalesce(new.unit,'') in ('percent','percentage') and (new.amount<0 or new.amount>100) then
    raise exception 'percentage_component_out_of_range';
  end if;
  new.metadata:=jsonb_set(
    coalesce(new.metadata,'{}'::jsonb)||jsonb_build_object('calculation_base',new.calculation_base),
    '{visibility}',
    coalesce(coalesce(new.metadata,'{}'::jsonb)->'visibility','{}'::jsonb)||jsonb_build_object(
      'website_card',new.website_card_visible,
      'quote_breakdown',true,
      'checkout',true,
      'contract_document',true,
      'invoice',new.invoice_line_visible
    ),true
  );
  return new;
end $$;

--
-- Name: gridex_sync_public_offer_to_canonical(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_public_offer_to_canonical(p_offer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  o public.public_contract_offers%rowtype; v_product_id uuid; v_contract_version_id uuid; v_assignment_id uuid;
  v_publication_id uuid; v_legal_version_id uuid; v_publication_version_id uuid; v_price_snapshot jsonb;
  v_commercial jsonb; v_publication jsonb; v_hash text; v_number integer; v_required text[]; v_published public.contract_publication_versions;
begin
  select * into o from public.public_contract_offers where id=p_offer_id for update;
  if not found then return null; end if;
  select snapshot_json into v_price_snapshot from public.price_plan_versions where id=o.price_plan_version_id and company_id=o.company_id and price_plan_id=o.price_plan_id;
  if v_price_snapshot is null then raise exception 'Exakt prisversion saknas för avtalet.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(o.company_id::text||':'||o.version_series_id::text,0));
  perform set_config('gridex.public_offer_write','on',true);

  insert into public.contract_products(company_id,product_code,name,product_category,description,status,created_by)
  values(o.company_id,'website:'||o.version_series_id::text,o.public_name,coalesce(o.contract_type,'unknown'),o.public_description,case when o.is_archived then 'archived' else 'active' end,o.created_by)
  on conflict(company_id,product_code) where company_id is not null do update set name=excluded.name,description=excluded.description,status=excluded.status,updated_at=now()
  returning id into v_product_id;

  v_required:=public.gridex_required_legal_modules(o.customer_type,o.contract_type,'website',o.automatic_renewal,o.power_of_attorney_required);
  v_commercial:=jsonb_build_object('schema','gridex_contract_commercial_v3','company_id',o.company_id,'version_series_id',o.version_series_id,'legacy_public_contract_offer_id',o.id,
    'contract_type',o.contract_type,'energy_direction',coalesce(nullif(lower(o.energy_direction),''),'consumption'),'billing_model',o.billing_model,'customer_type',o.customer_type,'price_plan_id',o.price_plan_id,'price_plan_version_id',o.price_plan_version_id,'price_book_id',o.price_book_id,
    'pricing_snapshot',v_price_snapshot,'price_areas',o.price_areas,'binding_months',o.binding_months,'notice_months',o.notice_months,'automatic_renewal',o.automatic_renewal,'power_of_attorney_required',o.power_of_attorney_required);
  v_hash:=encode(digest(v_commercial::text,'sha256'),'hex');
  select id into v_contract_version_id from public.contract_product_versions where contract_product_id=v_product_id and content_sha256=v_hash limit 1;
  if v_contract_version_id is null then
    select coalesce(max(version_number),0)+1 into v_number from public.contract_product_versions where contract_product_id=v_product_id;
    insert into public.contract_product_versions(contract_product_id,version_number,customer_type,contract_type,energy_direction,pricing_model,price_plan_id,price_plan_version_id,binding_months,notice_months,price_areas,automatic_renewal,power_of_attorney_required,required_legal_modules,commercial_snapshot,content_sha256,status,approved_at,approved_by,locked_at,created_by)
    values(v_product_id,v_number,o.customer_type,o.contract_type,
      coalesce(nullif(lower(o.energy_direction),''),'consumption'),coalesce(v_price_snapshot->>'pricing_model',o.billing_model,o.contract_type),o.price_plan_id,o.price_plan_version_id,o.binding_months,o.notice_months,o.price_areas,o.automatic_renewal,o.power_of_attorney_required,v_required,v_commercial,v_hash,
      case when o.publication_status='published' then 'approved' else 'draft' end,case when o.publication_status='published' then now() end,case when o.publication_status='published' then o.updated_by end,case when o.publication_status='published' then now() end,o.created_by)
    returning id into v_contract_version_id;
  end if;
  if o.publication_status='published' then
    perform set_config('gridex.version_transition','on',true);
    update public.contract_product_versions
    set status='approved',approved_at=coalesce(approved_at,now()),approved_by=coalesce(approved_by,o.updated_by),locked_at=coalesce(locked_at,now())
    where id=v_contract_version_id and (status<>'approved' or locked_at is null);
  end if;

  if o.publication_status='published' then
    perform set_config('gridex.version_transition','on',true);
    update public.tenant_contract_assignments ta set status='ended',valid_to=coalesce(ta.valid_to,current_date),updated_at=now()
    from public.contract_product_versions pv where pv.id=ta.contract_product_version_id and ta.company_id=o.company_id and pv.contract_product_id=v_product_id and ta.contract_product_version_id<>v_contract_version_id and ta.status='active';
  end if;

  insert into public.tenant_contract_assignments(company_id,contract_product_version_id,internal_sales_allowed,website_publication_allowed,status,legal_mode,valid_from,valid_to,assigned_by)
  values(o.company_id,v_contract_version_id,true,true,case when o.publication_status='published' then 'active' when o.is_archived then 'ended' else 'paused' end,'ops_standard',o.valid_from,o.valid_to,o.updated_by)
  on conflict(company_id,contract_product_version_id) do update set website_publication_allowed=true,status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,updated_at=now()
  returning id into v_assignment_id;
  insert into public.tenant_contract_channels(assignment_id,channel,status,valid_from,valid_to,marketing_content,updated_by)
  values(v_assignment_id,'website',case when o.publication_status='published' and o.website_enabled then 'active' when o.is_archived then 'ended' else 'paused' end,o.valid_from::timestamptz,
    case when o.valid_to is null then null else (o.valid_to + 1)::timestamptz end,jsonb_build_object('name',o.public_name,'description',o.public_description,'sort_order',o.sort_order),o.updated_by)
  on conflict(assignment_id,channel) do update set status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,marketing_content=excluded.marketing_content,updated_by=excluded.updated_by,updated_at=now();

  v_legal_version_id:=public.gridex_materialize_legal_bundle_version(o.company_id,v_contract_version_id,o.legal_bundle_id,o.updated_by);
  if o.publication_status='published' then
    update public.legal_bundle_versions set status='published',published_at=coalesce(published_at,now()),locked_at=coalesce(locked_at,now()) where id=v_legal_version_id and locked_at is null;
  end if;

  insert into public.contract_publications(assignment_id,channel,status,created_by)
  values(v_assignment_id,'website',case when o.publication_status='published' then 'review' when o.is_archived then 'archived' else 'draft' end,o.created_by)
  on conflict(assignment_id,channel) do update set status=excluded.status,updated_at=now()
  returning id into v_publication_id;

  v_publication:=jsonb_build_object('schema','gridex_contract_publication_v3','legacy_public_contract_offer_id',o.id,'version_series_id',o.version_series_id,'version_number',o.version_number,
    'company_id',o.company_id,'contract_product_id',v_product_id,'contract_product_version_id',v_contract_version_id,'legal_bundle_version_id',v_legal_version_id,
    'price_plan_id',o.price_plan_id,'price_plan_version_id',o.price_plan_version_id,'price_book_id',o.price_book_id,'energy_direction',coalesce(nullif(lower(o.energy_direction),''),'consumption'),'customer_type',o.customer_type,'channel','website','valid_from',o.valid_from,'valid_to',o.valid_to,
    'website_cta_enabled',o.website_cta_enabled,'public_name',o.public_name,'public_description',o.public_description,'public_price_text',o.public_price_text,'pricing_snapshot',v_price_snapshot);
  v_hash:=encode(digest(v_publication::text,'sha256'),'hex');
  select id into v_publication_version_id from public.contract_publication_versions where contract_publication_id=v_publication_id and content_sha256=v_hash limit 1;
  if v_publication_version_id is null then
    select coalesce(max(version_number),0)+1 into v_number from public.contract_publication_versions where contract_publication_id=v_publication_id;
    insert into public.contract_publication_versions(contract_publication_id,version_number,contract_product_version_id,price_plan_id,price_plan_version_id,price_book_id,legal_bundle_version_id,legacy_public_contract_offer_id,customer_type,energy_direction,channel,valid_from,valid_to,publication_snapshot,content_sha256,status,created_by)
    values(v_publication_id,v_number,v_contract_version_id,o.price_plan_id,o.price_plan_version_id,o.price_book_id,v_legal_version_id,o.id,o.customer_type,
      coalesce(nullif(lower(o.energy_direction),''),'consumption'),'website',o.valid_from::timestamptz,
    case when o.valid_to is null then null else (o.valid_to + 1)::timestamptz end,v_publication,v_hash,case when o.publication_status='published' then 'review' when o.is_archived then 'archived' else 'draft' end,o.created_by)
    returning id into v_publication_version_id;
  end if;

  update public.public_contract_offers set contract_product_id=v_product_id,contract_product_version_id=v_contract_version_id,legal_bundle_version_id=v_legal_version_id,contract_publication_version_id=v_publication_version_id,
    metadata=coalesce(metadata,'{}')||jsonb_build_object('contract_product_id',v_product_id,'contract_product_version_id',v_contract_version_id,'tenant_contract_assignment_id',v_assignment_id,'legal_bundle_version_id',v_legal_version_id,'contract_publication_id',v_publication_id,'contract_publication_version_id',v_publication_version_id,'canonical_publication_sha256',v_hash,'source_of_truth','contract_publication_versions')
  where id=o.id;

  if o.publication_status='published' then
    v_published:=public.gridex_publish_contract_publication_version(v_publication_version_id,o.updated_by);
    update public.public_contract_offers set metadata=metadata||jsonb_build_object('canonical_offer_reference',v_published.offer_reference),is_public=true,published_at=coalesce(published_at,v_published.published_at),readiness_status='ready',readiness_blockers='[]'::jsonb where id=o.id;
  end if;
  return v_publication_version_id;
end $$;

--
-- Name: gridex_sync_public_offer_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_public_offer_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth() = 1 then perform public.gridex_sync_public_offer_to_canonical(new.id); end if;
  return new;
end $$;

--
-- Name: gridex_sync_supply_customer_contract_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_supply_customer_contract_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.contract_id is not null and new.customer_contract_id is not null
     and new.contract_id is distinct from new.customer_contract_id then
    raise exception using errcode='23514',message='supply_contract_alias_mismatch';
  end if;
  new.customer_contract_id:=coalesce(new.customer_contract_id,new.contract_id);
  new.contract_id:=coalesce(new.contract_id,new.customer_contract_id);
  return new;
end
$$;

--
-- Name: gridex_sync_underlay_invoice_projection_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_sync_underlay_invoice_projection_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_export_run_id uuid;
begin
  if new.company_id is null or new.customer_id is null or new.billing_underlay_id is null then
    return new;
  end if;

  if new.invoice_export_item_id is not null then
    select iei.export_run_id
      into v_export_run_id
      from public.invoice_export_items iei
     where iei.id = new.invoice_export_item_id
       and iei.company_id = new.company_id
       and iei.customer_id = new.customer_id;
  end if;

  update public.billing_underlays bu
     set invoice_readiness_status = case
           when new.status = 'draft' then 'ready_for_invoice'
           when new.status in ('issued', 'sent', 'paid', 'overdue') then 'invoiced'
           when new.status = 'credited' then 'credited'
           when new.status = 'cancelled' then 'cancelled'
           when new.status = 'failed' then 'needs_review'
           else coalesce(bu.invoice_readiness_status, 'pending')
         end,
         invoice_export_run_id = coalesce(v_export_run_id, bu.invoice_export_run_id),
         invoice_export_locked_at = case
           when new.status in ('issued', 'sent', 'paid', 'overdue', 'credited')
             then coalesce(bu.invoice_export_locked_at, now())
           else bu.invoice_export_locked_at
         end,
         updated_at = now()
   where bu.id = new.billing_underlay_id
     and bu.company_id = new.company_id
     and bu.customer_id = new.customer_id;

  if not found then
    raise exception using
      errcode = '23514',
      message = 'invoice_projection_underlay_customer_mismatch';
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_sync_underlay_invoice_projection_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_sync_underlay_invoice_projection_v1() IS 'Maintains the customer-card invoice readiness projection from canonical customer_invoices. Does not decide billing readiness or provider send eligibility.';

--
-- Name: gridex_tenant_activation_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_tenant_activation_readiness(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c public.companies%rowtype;
  v_blockers jsonb := '[]'::jsonb;
  v_go_live jsonb := '{}'::jsonb;
  v_contract jsonb := '{}'::jsonb;
  v_incomplete_task_count integer := 0;
begin
  select * into c
  from public.companies
  where id = p_company_id;

  if not found then
    return jsonb_build_object(
      'ready', false,
      'blocking_reasons', jsonb_build_array(
        jsonb_build_object('code', 'tenant_not_found', 'message', 'Tenant hittades inte.')
      )
    );
  end if;

  if lower(coalesce(c.status, '')) in ('paused', 'suspended', 'archived', 'blocked', 'pending_deletion', 'deleted_test_only') then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_lifecycle_not_active',
      'message', 'Bolagets lifecycle-status tillåter inte aktivering.'
    ));
  end if;

  if nullif(btrim(coalesce(c.legal_name, c.name, '')), '') is null
     or nullif(btrim(coalesce(c.org_number, '')), '') is null then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_legal_entity',
      'message', 'Juridiskt namn eller organisationsnummer saknas.'
    ));
  end if;

  if not exists(
    select 1
    from public.company_memberships m
    where m.company_id = p_company_id
      and m.status = 'active'
      and coalesce(m.membership_role, '') in ('owner', 'admin', 'company_admin')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_admin',
      'message', 'Aktiv bolagsadministratör saknas.'
    ));
  end if;

  if nullif(btrim(coalesce(c.external_tenant_reference, '')), '') is null then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_external_reference',
      'message', 'Extern tenantreferens saknas.'
    ));
  end if;

  if not exists(
    select 1
    from public.integration_api_clients i
    where i.company_id = p_company_id
      and i.status = 'active'
      and array[
        'integration_context.read',
        'website_contracts.read',
        'website_contracts.diagnostics',
        'website_energy_area.resolve',
        'website_quotes.write',
        'website_quotes.validate',
        'website_applications.write',
        'website_legal.read'
      ]::text[] <@ coalesce(i.scopes, '{}'::text[])
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_required_scopes',
      'message', 'Aktiv API-klient med obligatoriska website_sales-scopes saknas.'
    ));
  end if;

  if not exists(
    select 1
    from public.tenant_contract_channels ch
    join public.tenant_contract_assignments ta on ta.id = ch.assignment_id
    where ta.company_id = p_company_id
      and ch.channel in ('website', 'api')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_contract_channel',
      'message', 'Försäljningskanal för hemsida/API saknas.'
    ));
  end if;

  if nullif(btrim(coalesce(c.primary_contact_email, c.support_email, '')), '') is null then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_missing_customer_communication',
      'message', 'Kund- eller supportadress saknas.'
    ));
  end if;

  begin
    v_contract := public.gridex_contract_platform_readiness_internal_v1(p_company_id);
  exception when others then
    v_contract := jsonb_build_object('error', sqlerrm);
  end;

  if coalesce((v_contract #>> '{website,can_display}')::boolean, false) = false then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_website_not_ready',
      'message', 'Publicerade avtal kan inte visas för tenantens webbflöde.'
    ));
  end if;
  if coalesce((v_contract #>> '{applications,can_accept}')::boolean, false) = false then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_applications_not_ready',
      'message', 'Tenantens ansökningsflöde kan inte ta emot nya avtal.'
    ));
  end if;
  if coalesce(v_contract #>> '{legal_profile,status}', '') <> 'ready' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_legal_profile_not_ready',
      'message', 'Juridisk profil är inte komplett.'
    ));
  end if;
  if coalesce(v_contract #>> '{documents,status}', '') <> 'ready' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_documents_not_ready',
      'message', 'Dokumentflödet är inte production-ready.'
    ));
  end if;
  if coalesce(v_contract #>> '{customer_operations,status}', '') <> 'ready' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_customer_operations_not_ready',
      'message', 'Kundoperationsflödet är inte production-ready.'
    ));
  end if;

  v_go_live := public.gridex_company_go_live_readiness(p_company_id);
  if coalesce(v_go_live ->> 'status', 'blocked') <> 'ready' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'tenant_ediel_go_live_not_ready',
      'message', 'Ediel go-live readiness är inte klar.',
      'details', coalesce(v_go_live -> 'blockers', '[]'::jsonb)
    ));
  end if;

  select count(*)
  into v_incomplete_task_count
  from public.company_onboarding_tasks t
  where t.company_id = p_company_id
    and t.status <> 'complete';

  return jsonb_build_object(
    'ready', jsonb_array_length(v_blockers) = 0,
    'tenant_id', p_company_id,
    'status', c.status,
    'blocking_reasons', v_blockers,
    'ediel', v_go_live,
    'contract_platform', v_contract,
    'onboarding_task_incomplete_count_advisory', v_incomplete_task_count,
    'onboarding_tasks_are_gate', false,
    'source', 'canonical_runtime_v2',
    'evaluated_at', now()
  );
end;
$$;

--
-- Name: FUNCTION gridex_tenant_activation_readiness(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_tenant_activation_readiness(p_company_id uuid) IS 'Structured activation blockers derived from persisted legal/admin/API/channel/communication/onboarding state.';

--
-- Name: tenant_legal_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_legal_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    legal_name text,
    organization_number text,
    postal_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    customer_service_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    customer_service_email text,
    phone text,
    website text,
    complaints_contact jsonb DEFAULT '{}'::jsonb NOT NULL,
    data_protection_contact jsonb DEFAULT '{}'::jsonb NOT NULL,
    billing_information jsonb DEFAULT '{}'::jsonb NOT NULL,
    dispute_resolution_information jsonb DEFAULT '{}'::jsonb NOT NULL,
    memberships jsonb DEFAULT '[]'::jsonb NOT NULL,
    completeness_status text DEFAULT 'incomplete'::text NOT NULL,
    verified_at timestamp with time zone,
    verified_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    missing_fields text[] DEFAULT '{}'::text[] NOT NULL,
    review_required boolean DEFAULT false NOT NULL,
    source_company_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_company_snapshot_sha256 text,
    source_company_updated_at timestamp with time zone,
    customer_service_contact jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    last_synced_at timestamp with time zone,
    last_synced_by uuid,
    CONSTRAINT tenant_legal_profiles_completeness_status_check CHECK ((completeness_status = ANY (ARRAY['incomplete'::text, 'complete'::text, 'verified'::text])))
);

--
-- Name: TABLE tenant_legal_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_legal_profiles IS 'Generated legal projection of companies plus platform defaults. Not an independently editable source.';

--
-- Name: gridex_tenant_legal_profile_missing_fields(public.tenant_legal_profiles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_tenant_legal_profile_missing_fields(p_profile public.tenant_legal_profiles) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_missing text[] := array[]::text[];
begin
  if length(btrim(coalesce(p_profile.legal_name, ''))) < 2
     or coalesce(p_profile.source_company_snapshot->>'legal_name_source', 'legacy_fallback') <> 'tenant_explicit'
  then
    v_missing := array_append(v_missing, 'legal_name');
  end if;
  if not public.gridex_luhn_valid(p_profile.organization_number) then v_missing := array_append(v_missing, 'organization_number'); end if;
  if not public.gridex_address_complete(p_profile.postal_address) then v_missing := array_append(v_missing, 'postal_address'); end if;
  if coalesce(p_profile.customer_service_email, '') !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then v_missing := array_append(v_missing, 'customer_service_email'); end if;
  if length(regexp_replace(coalesce(p_profile.phone, ''), '[^0-9]', '', 'g')) < 7 then v_missing := array_append(v_missing, 'phone'); end if;
  if coalesce(p_profile.website, '') !~* '^https?://([a-z0-9-]+\.)+[a-z]{2,}([/:?#].*)?$' then v_missing := array_append(v_missing, 'website'); end if;
  if not public.gridex_legal_contact_complete(p_profile.complaints_contact) then v_missing := array_append(v_missing, 'complaints_contact'); end if;
  if not public.gridex_legal_contact_complete(p_profile.data_protection_contact) then v_missing := array_append(v_missing, 'data_protection_contact'); end if;
  if not public.gridex_billing_information_complete(p_profile.billing_information) then v_missing := array_append(v_missing, 'billing_information'); end if;
  if not public.gridex_dispute_information_complete(p_profile.dispute_resolution_information) then v_missing := array_append(v_missing, 'dispute_resolution_information'); end if;
  return v_missing;
end
$_$;

--
-- Name: gridex_tenant_legal_profile_readiness_status(public.tenant_legal_profiles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_tenant_legal_profile_readiness_status(p_profile public.tenant_legal_profiles) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when coalesce(array_length(p_profile.missing_fields, 1), 0) > 0 then 'incomplete'
    when coalesce(p_profile.review_required, false) then 'complete_unreviewed'
    when coalesce(p_profile.reviewed_at, p_profile.verified_at) is not null then 'verified'
    else 'complete_unreviewed'
  end
$$;

--
-- Name: gridex_test_republish_active_public_contract_v2(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_test_republish_active_public_contract_v2(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_explicit_invoice_fee_sek numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_state text;
  v_message text;
  v_detail text;
  v_constraint text;
  v_table text;
begin
  begin
    v_result:=public.gridex_republish_active_public_contract_v2(
      p_publication_version_id,
      p_actor_user_id,
      p_explicit_invoice_fee_sek
    );

    raise exception using
      errcode='P0001',
      message='GRIDEX_REPUBLISH_ROLLBACK_TEST_SUCCESS',
      detail=v_result::text;
  exception
    when sqlstate 'P0001' then
      get stacked diagnostics
        v_state=returned_sqlstate,
        v_message=message_text,
        v_detail=pg_exception_detail,
        v_constraint=constraint_name,
        v_table=table_name;

      if v_message='GRIDEX_REPUBLISH_ROLLBACK_TEST_SUCCESS' then
        return jsonb_build_object(
          'ok',true,
          'rolled_back',true,
          'result',coalesce(nullif(v_detail,''),'{}')::jsonb,
          'unique_objects',public.gridex_price_option_unique_objects_v1()
        );
      end if;

      return jsonb_build_object(
        'ok',false,
        'rolled_back',true,
        'sqlstate',v_state,
        'message',v_message,
        'detail',v_detail,
        'constraint',nullif(v_constraint,''),
        'table',nullif(v_table,''),
        'unique_objects',public.gridex_price_option_unique_objects_v1()
      );
    when others then
      get stacked diagnostics
        v_state=returned_sqlstate,
        v_message=message_text,
        v_detail=pg_exception_detail,
        v_constraint=constraint_name,
        v_table=table_name;

      return jsonb_build_object(
        'ok',false,
        'rolled_back',true,
        'sqlstate',v_state,
        'message',v_message,
        'detail',v_detail,
        'constraint',nullif(v_constraint,''),
        'table',nullif(v_table,''),
        'unique_objects',public.gridex_price_option_unique_objects_v1()
      );
  end;
end $$;

--
-- Name: gridex_text_to_jsonb(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_text_to_jsonb(value text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  if value is null or btrim(value) = '' then
    return '{}'::jsonb;
  end if;

  return value::jsonb;
exception when others then
  return jsonb_build_object('raw', value);
end;
$$;

--
-- Name: gridex_text_to_text_array(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_text_to_text_array(value text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  if value is null or btrim(value) = '' then
    return '{}'::text[];
  end if;

  if left(btrim(value), 1) = '[' then
    return public.gridex_jsonb_to_text_array(value::jsonb);
  end if;

  if left(btrim(value), 1) = '{' and right(btrim(value), 1) = '}' then
    return value::text[];
  end if;

  return string_to_array(value, ',');
exception when others then
  return array[value];
end;
$$;

--
-- Name: gridex_transition_customer_application_workflow(uuid, uuid, text, text, text, jsonb, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_transition_customer_application_workflow(p_company_id uuid, p_customer_application_id uuid, p_to_state text, p_event_code text, p_reason_code text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(workflow_id uuid, operation_id uuid, state text, workflow_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.customer_application_workflows%rowtype;
  v_key text;
begin
  select * into v_row
  from public.customer_application_workflows
  where company_id=p_company_id and customer_application_id=p_customer_application_id
  for update;

  if not found then
    raise exception 'customer_application_workflow_not_found' using errcode='P0002';
  end if;
  if p_expected_version is not null and v_row.workflow_version <> p_expected_version then
    raise exception 'customer_application_workflow_version_conflict' using errcode='40001';
  end if;
  if p_to_state is null or btrim(p_to_state) = '' then
    raise exception 'customer_application_workflow_state_required' using errcode='22023';
  end if;

  if v_row.state in ('completed','cancelled')
     and p_to_state <> v_row.state
     and coalesce(p_event_code,'') <> 'workflow.reopened' then
    raise exception 'customer_application_workflow_terminal' using errcode='23514';
  end if;

  v_key := coalesce(nullif(btrim(p_idempotency_key), ''),
    format('workflow:%s:%s:%s:%s', v_row.id, v_row.workflow_version + 1, p_to_state, coalesce(p_event_code,'transition')));

  if exists (
    select 1 from public.customer_application_workflow_events
    where company_id=p_company_id and idempotency_key=v_key
  ) then
    return query
    select w.id,w.operation_id,w.state,w.workflow_version
    from public.customer_application_workflows w where w.id=v_row.id;
    return;
  end if;

  insert into public.customer_application_workflow_events(
    company_id,workflow_id,customer_application_id,operation_id,from_state,to_state,
    event_code,reason_code,actor_user_id,metadata,idempotency_key
  ) values (
    p_company_id,v_row.id,p_customer_application_id,v_row.operation_id,v_row.state,p_to_state,
    coalesce(nullif(btrim(p_event_code),''),'workflow.transitioned'),nullif(btrim(p_reason_code),''),
    p_actor_user_id,coalesce(p_metadata,'{}'::jsonb),v_key
  ) on conflict (company_id,idempotency_key) do nothing;

  update public.customer_application_workflows workflow
      set state=p_to_state,
          next_action=coalesce(p_metadata->>'next_action',workflow.next_action),
          snapshot=coalesce(workflow.snapshot,'{}'::jsonb) || coalesce(p_metadata,'{}'::jsonb),
          failure_code=case when p_to_state='failed' then coalesce(nullif(btrim(p_reason_code),''),workflow.failure_code) else null end,
          completed_at=case when p_to_state in ('completed','cancelled') then now() else null end,
          last_transition_at=now(),
          workflow_version=workflow.workflow_version+1,
          updated_at=now()
      where workflow.id=v_row.id;

  return query
  select w.id,w.operation_id,w.state,w.workflow_version
  from public.customer_application_workflows w where w.id=v_row.id;
end;
$$;

--
-- Name: gridex_transition_portfolio_settlement(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_transition_portfolio_settlement(p_actor_user_id uuid, p_settlement_id uuid, p_action text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_row public.portfolio_monthly_settlements%rowtype;
  v_price numeric;
  v_hash text;
  v_formula text;
  v_snapshot jsonb;
  v_now timestamptz := now();
begin
  select *
    into v_row
  from public.portfolio_monthly_settlements
  where id = p_settlement_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'portfolio_settlement_not_found';
  end if;

  perform set_config('gridex.portfolio_actor_user_id', p_actor_user_id::text, true);
  perform set_config('gridex.portfolio_audit_reason', coalesce(p_reason, ''), true);

  if p_action = 'calculate' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.calculate',
      v_row.company_id,
      v_row.portfolio_id
    );

    if v_row.status not in ('draft', 'calculated') then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_draft_or_calculated';
    end if;

    if v_row.portfolio_price_ore_per_kwh is not null then
      if v_row.portfolio_price_ore_per_kwh <= 0 then
        raise exception using errcode = '23514', message = 'portfolio_settlement_direct_price_invalid';
      end if;
      v_price := v_row.portfolio_price_ore_per_kwh;
      v_formula := 'manual_portfolio_price_ore_per_kwh';
    else
      if v_row.gross_energy_cost_sek is null or coalesce(v_row.energy_volume_kwh, 0) <= 0 then
        raise exception using errcode = '23514', message = 'portfolio_settlement_calculation_inputs_missing';
      end if;
      v_price := (
        (
          v_row.gross_energy_cost_sek
          + v_row.hedging_result_sek
          + v_row.balancing_cost_sek
          + v_row.other_allowed_cost_sek
        ) / v_row.energy_volume_kwh
      ) * 100;
      v_formula := '((gross_energy_cost_sek + hedging_result_sek + balancing_cost_sek + other_allowed_cost_sek) / energy_volume_kwh) * 100';
    end if;

    v_snapshot := jsonb_build_object(
      'formula', v_formula,
      'source', v_row.source,
      'company_id', v_row.company_id,
      'portfolio_id', v_row.portfolio_id,
      'price_area_code', v_row.price_area_code,
      'delivery_month', v_row.delivery_month,
      'price_plan_version_id', v_row.price_plan_version_id,
      'revision_no', v_row.revision_no,
      'gross_energy_cost_sek', v_row.gross_energy_cost_sek,
      'hedging_result_sek', v_row.hedging_result_sek,
      'balancing_cost_sek', v_row.balancing_cost_sek,
      'other_allowed_cost_sek', v_row.other_allowed_cost_sek,
      'energy_volume_kwh', v_row.energy_volume_kwh,
      'management_fee_ore_per_kwh', v_row.management_fee_ore_per_kwh,
      'portfolio_price_ore_per_kwh', v_price,
      'vat_rate', v_row.vat_rate
    );
    v_hash := encode(
      extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'),
      'hex'
    );

    update public.portfolio_monthly_settlements
    set status = 'calculated',
        portfolio_price_ore_per_kwh = v_price,
        calculation_snapshot = v_snapshot,
        calculation_snapshot_sha256 = v_hash,
        calculated_by = p_actor_user_id,
        calculated_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'review' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.review',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'calculated' then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_calculated';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'reviewed',
        reviewed_by = p_actor_user_id,
        reviewed_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'approve' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.approve',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'reviewed'
       or v_row.calculation_snapshot_sha256 is null
       or v_row.portfolio_price_ore_per_kwh is null then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_reviewed_and_calculated';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'final',
        approved_by = p_actor_user_id,
        approved_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'lock' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.lock',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'final' then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_final';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'locked',
        locked_by = p_actor_user_id,
        locked_at = v_now
    where id = v_row.id;

  else
    raise exception using errcode = '22023', message = 'unknown_portfolio_settlement_action';
  end if;

  return (
    select to_jsonb(s)
    from public.portfolio_monthly_settlements s
    where s.id = v_row.id
  );
end $$;

--
-- Name: gridex_transition_supplier_switch_v1(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_transition_supplier_switch_v1(p_company_id uuid, p_request_id uuid, p_patch jsonb, p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_before public.supplier_switch_requests%rowtype;
  v_after public.supplier_switch_requests%rowtype;
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb) - 'updated_at';
  v_key text;
  v_set text;
  v_allowed constant text[] := array[
    'status', 'requested_start_date', 'confirmed_start_date', 'submitted_at', 'completed_at',
    'failed_at', 'failure_reason', 'external_reference', 'validation_snapshot', 'metadata',
    'lifecycle_blocked', 'lifecycle_block_source', 'lifecycle_block_id', 'pause_reason',
    'paused_at', 'paused_by', 'inbound_z04_message_id', 'updated_by',
    'authorization_document_id', 'power_of_attorney_id', 'operation_id'
  ];
begin
  perform public.gridex_assert_switch_writer_v1(p_company_id);

  select * into v_before
  from public.supplier_switch_requests
  where id = p_request_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'supplier_switch_not_found_for_tenant';
  end if;

  for v_key in select jsonb_object_keys(v_patch) loop
    if not v_key = any (v_allowed) then
      raise exception using errcode = '22023', message = 'supplier_switch_patch_column_not_allowed', detail = v_key;
    end if;
  end loop;

  -- Only the keys the caller sent are written; identity and tenant columns never move.
  select string_agg(format('%1$I = patch.%1$I', key), ', ')
  into v_set
  from jsonb_object_keys(v_patch) as key;
  v_set := concat_ws(', ', v_set, 'updated_at = now()');

  execute format(
    'update public.supplier_switch_requests target set %s
       from jsonb_populate_record(null::public.supplier_switch_requests, $3) as patch
      where target.id = $1 and target.company_id = $2
      returning target.*',
    v_set
  ) into v_after using p_request_id, p_company_id, v_patch;

  if p_event is not null then
    insert into public.supplier_switch_events (
      switch_request_id, event_type, event_status, message, payload, company_id, created_by
    ) values (
      p_request_id,
      coalesce(p_event->>'event_type', 'status_changed'),
      coalesce(p_event->>'event_status', 'success'),
      p_event->>'message',
      coalesce(p_event->'payload', '{}'::jsonb)
        || jsonb_build_object('previous_status', v_before.status, 'new_status', v_after.status),
      p_company_id,
      nullif(p_event->>'created_by', '')::uuid
    );
  end if;

  return jsonb_build_object('before', to_jsonb(v_before), 'request', to_jsonb(v_after));
end
$_$;

--
-- Name: gridex_transition_tenant_lifecycle(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_transition_tenant_lifecycle(p_company_id uuid, p_next_status text, p_actor_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  c public.companies%rowtype;
  v_before jsonb;
  v_readiness jsonb;
  v_blockers jsonb:='[]'::jsonb;
  v_event_id uuid;
begin
  if p_actor_user_id is null or not (
    exists(select 1 from public.admin_users a where a.user_id=p_actor_user_id
      and coalesce(a.is_active,true)
      and lower(coalesce(a.role,'')) in ('super_admin','superadmin','platform_superadmin'))
    or exists(select 1 from public.user_roles ur left join public.roles r on r.id=ur.role_id
      where ur.user_id=p_actor_user_id and coalesce(ur.status,'active')='active'
        and coalesce(ur.is_active,true)
        and lower(coalesce(ur.role,r.key,r.name,'')) in ('super_admin','superadmin','platform_superadmin'))
  ) then
    raise exception using errcode='42501',message='tenant_lifecycle_forbidden';
  end if;
  if p_next_status not in ('active','onboarding','paused','suspended','closed','archived','pending_deletion') then
    raise exception using errcode='22023',message='tenant_lifecycle_status_invalid';
  end if;
  if p_next_status not in ('active','onboarding') and nullif(btrim(coalesce(p_reason,'')),'') is null then
    return jsonb_build_object('ok',false,'changed',false,'code','tenant_reason_required');
  end if;

  select * into c from public.companies where id=p_company_id for update;
  if not found then return jsonb_build_object('ok',false,'changed',false,'code','tenant_not_found'); end if;
  v_before:=to_jsonb(c);
  if c.status='closed' and p_next_status<>'closed' then
    return jsonb_build_object('ok',false,'changed',false,'code','tenant_closed_terminal');
  end if;

  if p_next_status='active' then
    v_readiness:=public.gridex_tenant_activation_readiness(p_company_id);
    if not coalesce((v_readiness->>'ready')::boolean,false) then
      insert into public.company_onboarding_lifecycle(
        company_id,current_step,status,blocking_reasons,last_error_code,updated_at
      ) values(
        p_company_id,'blocked','blocked',coalesce(v_readiness->'blocking_reasons','[]'::jsonb),
        'tenant_not_operationally_ready',now()
      ) on conflict(company_id) do update set
        current_step='blocked',status='blocked',
        blocking_reasons=excluded.blocking_reasons,last_error_code=excluded.last_error_code,updated_at=now();
      return jsonb_build_object(
        'ok',false,'changed',false,'code','tenant_not_operationally_ready',
        'blocking_reasons',v_readiness->'blocking_reasons','readiness',v_readiness
      );
    end if;
  end if;

  if p_next_status='closed' then
    if exists(select 1 from public.customer_contracts cc
      where cc.company_id=p_company_id and cc.status in ('active','signed','current')) then
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object(
        'code','tenant_has_active_customer_contracts','message','Aktiva kundavtal måste överföras eller avslutas.'));
    end if;
    if exists(select 1 from public.supplier_switch_requests s
      where s.company_id=p_company_id and s.status not in ('completed','failed','cancelled','rejected')) then
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object(
        'code','tenant_has_open_supplier_switches','message','Pågående leverantörsbyten måste slutföras.'));
    end if;
    if exists(select 1 from public.billing_underlays b
      where b.company_id=p_company_id and b.status not in ('completed','exported','cancelled','rejected')) then
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object(
        'code','tenant_has_unsettled_billing','message','Ofärdig fakturering måste regleras.'));
    end if;
    if jsonb_array_length(v_blockers)>0 then
      return jsonb_build_object('ok',false,'changed',false,'code','tenant_closure_blocked',
        'blocking_reasons',v_blockers);
    end if;
  end if;

  update public.companies set
    status=p_next_status,
    status_reason=p_reason,
    is_active=(p_next_status='active'),
    is_paused=(p_next_status in ('paused','suspended','closed','archived','pending_deletion')),
    paused_at=case when p_next_status='paused' then coalesce(paused_at,now()) when p_next_status='active' then null else paused_at end,
    paused_by=case when p_next_status='paused' then p_actor_user_id when p_next_status='active' then null else paused_by end,
    closed_at=case when p_next_status='closed' then coalesce(closed_at,now()) else closed_at end,
    closed_by=case when p_next_status='closed' then p_actor_user_id else closed_by end,
    closure_reason=case when p_next_status='closed' then p_reason else closure_reason end,
    updated_at=now()
  where id=p_company_id;

  if p_next_status in ('paused','suspended','closed','archived','pending_deletion') then
    update public.integration_api_clients
    set status=case when p_next_status='closed' then 'revoked' else 'paused' end,
        revoked_at=case when p_next_status='closed' then coalesce(revoked_at,now()) else revoked_at end,
        revoked_by=case when p_next_status='closed' then p_actor_user_id else revoked_by end,
        revoke_reason=case when p_next_status='closed' then p_reason else revoke_reason end,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'tenant_lifecycle_pause',true,'tenant_lifecycle_status',p_next_status
        ),updated_at=now()
    where company_id=p_company_id and status in ('active','paused');

    update public.tenant_contract_channels ch set
      status=case when p_next_status='closed' then 'ended' else 'paused' end,
      valid_to=case when p_next_status='closed' then coalesce(ch.valid_to,now()) else ch.valid_to end,
      updated_by=p_actor_user_id,updated_at=now()
    from public.tenant_contract_assignments ta
    where ch.assignment_id=ta.id and ta.company_id=p_company_id and ch.status='active';

    update public.website_contract_quotes set status='revoked',updated_at=now()
    where company_id=p_company_id and status='active';
  elsif p_next_status='active' then
    update public.integration_api_clients set
      status='active',
      metadata=coalesce(metadata,'{}'::jsonb)-'tenant_lifecycle_pause'-'tenant_lifecycle_status',
      updated_at=now()
    where company_id=p_company_id and status='paused'
      and coalesce((metadata->>'tenant_lifecycle_pause')::boolean,false);
  end if;

  insert into public.company_onboarding_lifecycle(
    company_id,current_step,status,completed_steps,blocking_reasons,
    last_error_code,completed_at,activated_at,updated_at
  ) values(
    p_company_id,
    case when p_next_status='active' then 'activated'
         when p_next_status='onboarding' then 'created' else 'blocked' end,
    case when p_next_status='active' then 'activated'
         when p_next_status='onboarding' then 'in_progress' else 'blocked' end,
    case when p_next_status='active' then array[
      'created','legal_setup','admin_setup','energy_setup','integration_setup',
      'branding_setup','contracts_setup','review','ready','activated'
    ]::text[] else '{}'::text[] end,
    '[]'::jsonb,null,
    case when p_next_status='active' then now() else null end,
    case when p_next_status='active' then now() else null end,now()
  ) on conflict(company_id) do update set
    current_step=excluded.current_step,status=excluded.status,
    completed_steps=case when p_next_status='active' then excluded.completed_steps
      else public.company_onboarding_lifecycle.completed_steps end,
    blocking_reasons='[]'::jsonb,last_error_code=null,
    completed_at=case when p_next_status='active' then now()
      else public.company_onboarding_lifecycle.completed_at end,
    activated_at=case when p_next_status='active' then now()
      else public.company_onboarding_lifecycle.activated_at end,
    updated_at=now();

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'company',p_company_id::text,
    'tenant.'||p_next_status,v_before,
    jsonb_build_object('status',p_next_status,'reason',p_reason),
    jsonb_build_object('previous_status',c.status,'next_status',p_next_status)
  );
  insert into public.domain_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,source,idempotency_key,payload
  ) values(
    p_company_id,'tenant.'||p_next_status,'company',p_company_id::text,p_actor_user_id,'database',
    format('tenant.%s:%s:%s',p_next_status,p_company_id,extract(epoch from now())::bigint),
    jsonb_build_object('previous_status',c.status,'status',p_next_status,'reason',p_reason)
  ) returning id into v_event_id;
  insert into public.event_outbox(company_id,domain_event_id,destination_type,destination_key,payload)
  values(p_company_id,v_event_id,'internal','tenant.'||p_next_status,
    jsonb_build_object('domain_event_id',v_event_id,'event_type','tenant.'||p_next_status))
  on conflict do nothing;

  return jsonb_build_object('ok',true,'changed',c.status is distinct from p_next_status,
    'mode',p_next_status,'previous_status',c.status,'status',p_next_status,'event_id',v_event_id);
end $$;

--
-- Name: FUNCTION gridex_transition_tenant_lifecycle(p_company_id uuid, p_next_status text, p_actor_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_transition_tenant_lifecycle(p_company_id uuid, p_next_status text, p_actor_user_id uuid, p_reason text) IS 'Canonical tenant lifecycle transaction. valid_to is fully qualified; tenant closure ends both active and paused sales channels.';

--
-- Name: gridex_unlock_pricing_runs_for_month(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_unlock_pricing_runs_for_month(p_company_id uuid, p_billing_month text, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_month_start date;
  v_month_end date;
  v_count integer;
begin
  if p_billing_month !~ '^\d{4}-\d{2}$' then
    raise exception 'billing_month must be formatted as YYYY-MM';
  end if;
  v_month_start := to_date(p_billing_month || '-01', 'YYYY-MM-DD');
  v_month_end := v_month_start + interval '1 month';

  perform set_config('app.gridex_pricing_maintenance', 'on', true);

  update public.pricing_runs
  set
    status = 'success',
    locked_at = null,
    metadata = metadata || jsonb_build_object(
      'unlocked_at', now(),
      'unlocked_by', p_actor_user_id,
      'unlock_reason', coalesce(p_reason, 'billing_period_unlocked')
    )
  where company_id = p_company_id
    and status = 'locked'
    and billing_period_start >= v_month_start
    and billing_period_start < v_month_end;

  get diagnostics v_count = row_count;

  perform set_config('app.gridex_pricing_maintenance', '', true);

  return v_count;
end;
$_$;

--
-- Name: gridex_unpublish_contract_channel(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_unpublish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_channel text:=lower(coalesce(p_channel,''));
  v_assignment_id uuid;
  v_channel_id uuid;
  v_channel_status text;
  v_active_publication_versions bigint:=0;
  v_active_public_offers bigint:=0;
  v_affected_channels bigint:=0;
  v_affected_publications bigint:=0;
  v_affected_versions bigint:=0;
  v_affected_public_offers bigint:=0;
begin
  if v_channel not in ('internal','website','api','partner','phone') then
    raise exception using errcode='22023',message='invalid_contract_channel';
  end if;
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.pause');

  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='contract_offer_not_found'; end if;

  if o.contract_product_id is null or o.contract_product_version_id is null then
    perform public.gridex_sync_internal_offer_to_canonical(o.id);
    select * into o from public.contract_offers where id=o.id for update;
  end if;
  if o.contract_product_version_id is null then
    return jsonb_build_object('ok',false,'changed',false,'code','contract_backfill_incomplete','offer_id',o.id,'channel',v_channel);
  end if;

  select ta.id,ch.id,ch.status into v_assignment_id,v_channel_id,v_channel_status
  from public.tenant_contract_assignments ta
  join public.tenant_contract_channels ch on ch.assignment_id=ta.id and ch.channel=v_channel
  where ta.company_id=p_company_id and ta.contract_product_version_id=o.contract_product_version_id
  for update of ta,ch;

  if v_channel_id is null then
    return jsonb_build_object('ok',false,'changed',false,'code','contract_channel_not_found','offer_id',o.id,'channel',v_channel);
  end if;

  select count(*) into v_active_publication_versions
  from public.contract_publication_versions pv
  join public.contract_publications p on p.id=pv.contract_publication_id
  where p.assignment_id=v_assignment_id and p.channel=v_channel and pv.status='published';

  if v_channel='website' then
    select count(*) into v_active_public_offers
    from public.public_contract_offers po
    where po.company_id=p_company_id and po.source_contract_offer_id=o.id
      and (po.is_public or po.website_enabled or po.website_cta_enabled or po.publication_status='published');
  end if;

  if v_channel_status<>'active' and v_active_publication_versions=0 and v_active_public_offers=0 then
    return jsonb_build_object(
      'ok',true,'changed',false,'already_unpublished',true,'mode','unpublished',
      'offer_id',o.id,'channel',v_channel,'resulting_status',v_channel_status,
      'affected_channels',0,'affected_publication_versions',0,'affected_public_offers',0
    );
  end if;

  if v_channel<>'internal' and v_channel_status='active'
     and v_active_publication_versions=0 then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','active_publication_version_not_found',
      'offer_id',o.id,'channel',v_channel
    );
  end if;

  update public.tenant_contract_channels
  set status='paused',updated_by=p_actor_user_id,updated_at=now()
  where id=v_channel_id and status='active';
  get diagnostics v_affected_channels=row_count;

  update public.contract_publications
  set status='paused',updated_at=now()
  where assignment_id=v_assignment_id and channel=v_channel and status='published';
  get diagnostics v_affected_publications=row_count;

  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions pv
  set status='ended',valid_to=coalesce(pv.valid_to,now())
  from public.contract_publications p
  where pv.contract_publication_id=p.id
    and p.assignment_id=v_assignment_id and p.channel=v_channel
    and pv.status='published';
  get diagnostics v_affected_versions=row_count;

  if v_channel='website' then
    perform set_config('gridex.public_offer_write','on',true);
    update public.public_contract_offers
    set lifecycle_status='paused',publication_status='unpublished',
        is_public=false,website_enabled=false,website_cta_enabled=false,
        updated_by=p_actor_user_id,updated_at=now()
    where company_id=p_company_id and source_contract_offer_id=o.id
      and (is_public or website_enabled or website_cta_enabled or publication_status='published');
    get diagnostics v_affected_public_offers=row_count;
  end if;

  -- Channel permission is deliberately preserved. Only runtime status changes.
  update public.tenant_contract_assignments ta
  set status=case when exists(
        select 1 from public.tenant_contract_channels active_channel
        where active_channel.assignment_id=ta.id and active_channel.status='active'
          and (active_channel.valid_from is null or active_channel.valid_from<=now())
          and (active_channel.valid_to is null or active_channel.valid_to>=now())
      ) then 'active' else 'paused' end,
      updated_at=now()
  where ta.id=v_assignment_id;

  update public.contract_offers source_offer
  set lifecycle_status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=source_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'published' else 'paused' end,
      status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=source_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then 'active' else 'inactive' end,
      is_active=exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=source_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ),
      updated_by=p_actor_user_id,updated_at=now()
  where source_offer.id=o.id;

  update public.contract_products product
  set status=case when exists(
        select 1 from public.contract_product_versions pv
        join public.tenant_contract_assignments ta on ta.contract_product_version_id=pv.id
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where pv.contract_product_id=product.id and ta.company_id=p_company_id
          and ta.status='active' and ch.status='active'
      ) then 'active' else 'paused' end,
      updated_at=now()
  where product.id=o.contract_product_id and product.company_id=p_company_id;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(p_company_id,p_actor_user_id,'contract_product_version',o.contract_product_version_id::text,
    'contract_channel_unpublished',null,null,
    jsonb_build_object(
      'offer_id',o.id,'channel',v_channel,'affected_channels',v_affected_channels,
      'affected_publications',v_affected_publications,'affected_publication_versions',v_affected_versions,
      'affected_public_offers',v_affected_public_offers,'channel_permission_preserved',true
    ));

  return jsonb_build_object(
    'ok',true,'changed',(v_affected_channels+v_affected_publications+v_affected_versions+v_affected_public_offers)>0,
    'mode','unpublished','offer_id',o.id,'channel',v_channel,'resulting_status','paused',
    'affected_channels',v_affected_channels,
    'affected_publications',v_affected_publications,
    'affected_publication_versions',v_affected_versions,
    'affected_public_offers',v_affected_public_offers
  );
end $$;

--
-- Name: FUNCTION gridex_unpublish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_unpublish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) IS 'Stops one sales channel without mutating the canonical commercial version or other channels.';

--
-- Name: gridex_update_company_and_rebuild_legal_profile(uuid, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_update_company_and_rebuild_legal_profile(p_company_id uuid, p_actor_user_id uuid, p_input jsonb, p_mark_reviewed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  c public.companies%rowtype;
  v_input jsonb := coalesce(p_input, '{}'::jsonb);
  v_name text;
  v_country text;
  v_complaints_country text;
  v_privacy_country text;
  v_billing_country text;
  v_result jsonb;
  v_skip_previous text := current_setting('gridex.skip_legal_profile_sync', true);
begin
  if coalesce(p_mark_reviewed, false) then
    raise exception using errcode = '42501', message = 'direct_legal_review_not_allowed_use_gridex_review_company_legal_profile';
  end if;

  select * into c
  from public.companies
  where id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'company_not_found';
  end if;

  v_name := case
    when v_input ? 'name' then nullif(btrim(coalesce(v_input->>'name', '')), '')
    else c.name
  end;
  if v_name is null then
    raise exception using errcode = '23514', message = 'company_name_required';
  end if;

  v_country := case
    when v_input ? 'country_code' then public.gridex_normalize_country_code(v_input->>'country_code', 'SE')
    else public.gridex_normalize_country_code(c.country_code, 'SE')
  end;
  v_complaints_country := case
    when v_input ? 'complaints_country_code' then
      case when nullif(btrim(coalesce(v_input->>'complaints_country_code', '')), '') is null
        then null
        else public.gridex_normalize_country_code(v_input->>'complaints_country_code', v_country)
      end
    else c.complaints_country_code
  end;
  v_privacy_country := case
    when v_input ? 'data_protection_country_code' then
      case when nullif(btrim(coalesce(v_input->>'data_protection_country_code', '')), '') is null
        then null
        else public.gridex_normalize_country_code(v_input->>'data_protection_country_code', v_country)
      end
    else c.data_protection_country_code
  end;
  v_billing_country := case
    when v_input ? 'billing_country_code' then
      case when nullif(btrim(coalesce(v_input->>'billing_country_code', '')), '') is null
        then null
        else public.gridex_normalize_country_code(v_input->>'billing_country_code', v_country)
      end
    else c.billing_country_code
  end;

  perform set_config('gridex.skip_legal_profile_sync', 'on', true);
  update public.companies set
    name = v_name,
    legal_name = case when v_input ? 'legal_name' then nullif(btrim(v_input->>'legal_name'), '') else legal_name end,
    org_number = case when v_input ? 'org_number' then public.gridex_normalize_swedish_organization_number(v_input->>'org_number') else org_number end,
    vat_number = case when v_input ? 'vat_number' then nullif(btrim(v_input->>'vat_number'), '') else vat_number end,
    customer_number_prefix = case when v_input ? 'customer_number_prefix' then nullif(upper(regexp_replace(coalesce(v_input->>'customer_number_prefix', ''), '[^A-Za-z0-9]', '', 'g')), '') else customer_number_prefix end,
    primary_contact_name = case when v_input ? 'primary_contact_name' then nullif(btrim(v_input->>'primary_contact_name'), '') else primary_contact_name end,
    primary_contact_email = case when v_input ? 'primary_contact_email' then nullif(lower(btrim(v_input->>'primary_contact_email')), '') else primary_contact_email end,
    support_email = case when v_input ? 'support_email' then nullif(lower(btrim(v_input->>'support_email')), '') else support_email end,
    phone = case when v_input ? 'phone' then nullif(btrim(v_input->>'phone'), '') else phone end,
    website = case when v_input ? 'website' then nullif(btrim(v_input->>'website'), '') else website end,
    customer_service_hours = case when v_input ? 'customer_service_hours' then nullif(btrim(v_input->>'customer_service_hours'), '') else customer_service_hours end,
    address_line_1 = case when v_input ? 'address_line_1' then nullif(btrim(v_input->>'address_line_1'), '') else address_line_1 end,
    address_line_2 = case when v_input ? 'address_line_2' then nullif(btrim(v_input->>'address_line_2'), '') else address_line_2 end,
    postal_code = case when v_input ? 'postal_code' then public.gridex_normalize_postal_code(v_input->>'postal_code', v_country) else postal_code end,
    city = case when v_input ? 'city' then nullif(btrim(v_input->>'city'), '') else city end,
    country_code = v_country,
    complaints_contact_name = case when v_input ? 'complaints_contact_name' then nullif(btrim(v_input->>'complaints_contact_name'), '') else complaints_contact_name end,
    complaints_email = case when v_input ? 'complaints_email' then nullif(lower(btrim(v_input->>'complaints_email')), '') else complaints_email end,
    complaints_phone = case when v_input ? 'complaints_phone' then nullif(btrim(v_input->>'complaints_phone'), '') else complaints_phone end,
    complaints_address_line_1 = case when v_input ? 'complaints_address_line_1' then nullif(btrim(v_input->>'complaints_address_line_1'), '') else complaints_address_line_1 end,
    complaints_address_line_2 = case when v_input ? 'complaints_address_line_2' then nullif(btrim(v_input->>'complaints_address_line_2'), '') else complaints_address_line_2 end,
    complaints_postal_code = case when v_input ? 'complaints_postal_code' then public.gridex_normalize_postal_code(v_input->>'complaints_postal_code', coalesce(v_complaints_country, v_country)) else complaints_postal_code end,
    complaints_city = case when v_input ? 'complaints_city' then nullif(btrim(v_input->>'complaints_city'), '') else complaints_city end,
    complaints_country_code = v_complaints_country,
    complaints_description = case when v_input ? 'complaints_description' then nullif(btrim(v_input->>'complaints_description'), '') else complaints_description end,
    data_protection_contact_name = case when v_input ? 'data_protection_contact_name' then nullif(btrim(v_input->>'data_protection_contact_name'), '') else data_protection_contact_name end,
    data_protection_email = case when v_input ? 'data_protection_email' then nullif(lower(btrim(v_input->>'data_protection_email')), '') else data_protection_email end,
    data_protection_phone = case when v_input ? 'data_protection_phone' then nullif(btrim(v_input->>'data_protection_phone'), '') else data_protection_phone end,
    data_protection_address_line_1 = case when v_input ? 'data_protection_address_line_1' then nullif(btrim(v_input->>'data_protection_address_line_1'), '') else data_protection_address_line_1 end,
    data_protection_address_line_2 = case when v_input ? 'data_protection_address_line_2' then nullif(btrim(v_input->>'data_protection_address_line_2'), '') else data_protection_address_line_2 end,
    data_protection_postal_code = case when v_input ? 'data_protection_postal_code' then public.gridex_normalize_postal_code(v_input->>'data_protection_postal_code', coalesce(v_privacy_country, v_country)) else data_protection_postal_code end,
    data_protection_city = case when v_input ? 'data_protection_city' then nullif(btrim(v_input->>'data_protection_city'), '') else data_protection_city end,
    data_protection_country_code = v_privacy_country,
    billing_contact_email = case when v_input ? 'billing_contact_email' then nullif(lower(btrim(v_input->>'billing_contact_email')), '') else billing_contact_email end,
    billing_contact_phone = case when v_input ? 'billing_contact_phone' then nullif(btrim(v_input->>'billing_contact_phone'), '') else billing_contact_phone end,
    billing_address_line_1 = case when v_input ? 'billing_address_line_1' then nullif(btrim(v_input->>'billing_address_line_1'), '') else billing_address_line_1 end,
    billing_address_line_2 = case when v_input ? 'billing_address_line_2' then nullif(btrim(v_input->>'billing_address_line_2'), '') else billing_address_line_2 end,
    billing_postal_code = case when v_input ? 'billing_postal_code' then public.gridex_normalize_postal_code(v_input->>'billing_postal_code', coalesce(v_billing_country, v_country)) else billing_postal_code end,
    billing_city = case when v_input ? 'billing_city' then nullif(btrim(v_input->>'billing_city'), '') else billing_city end,
    billing_country_code = v_billing_country,
    billing_terms_summary = case when v_input ? 'billing_terms_summary' then nullif(btrim(v_input->>'billing_terms_summary'), '') else billing_terms_summary end,
    dispute_resolution_override = case
      when not (v_input ? 'dispute_resolution_override') then dispute_resolution_override
      when coalesce(v_input->'dispute_resolution_override', 'null'::jsonb) in ('null'::jsonb, '{}'::jsonb) then '{}'::jsonb
      else v_input->'dispute_resolution_override'
    end,
    status = case when v_input ? 'status' then coalesce(nullif(btrim(v_input->>'status'), ''), status) else status end,
    status_reason = case when v_input ? 'status_reason' then nullif(btrim(v_input->>'status_reason'), '') else status_reason end,
    ediel_id = case when v_input ? 'ediel_id' then nullif(upper(btrim(v_input->>'ediel_id')), '') else ediel_id end,
    actor_role = case when v_input ? 'actor_role' then nullif(upper(btrim(v_input->>'actor_role')), '') else actor_role end,
    sender_sub_address = case when v_input ? 'sender_sub_address' then nullif(upper(btrim(v_input->>'sender_sub_address')), '') else sender_sub_address end,
    ediel_mailbox = case when v_input ? 'ediel_mailbox' then nullif(btrim(v_input->>'ediel_mailbox'), '') else ediel_mailbox end,
    operating_environment = case when v_input ? 'operating_environment' then coalesce(nullif(btrim(v_input->>'operating_environment'), ''), operating_environment) else operating_environment end,
    branding = case when v_input ? 'branding' then coalesce(branding, '{}'::jsonb) || coalesce(v_input->'branding', '{}'::jsonb) else branding end,
    updated_at = now(),
    updated_by = p_actor_user_id
  where id = p_company_id;
  perform set_config('gridex.skip_legal_profile_sync', coalesce(v_skip_previous, ''), true);

  v_result := public.gridex_rebuild_company_legal_profile(p_company_id, p_actor_user_id, false);
  if p_actor_user_id is not null and to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs(
      actor_user_id, company_id, entity_type, entity_id, action, new_values, metadata
    ) values (
      p_actor_user_id,
      p_company_id,
      'company',
      p_company_id,
      'COMPANY_PROFILE_AND_LEGAL_PROFILE_UPDATED',
      v_input,
      jsonb_build_object('atomic', true, 'legal_profile_result', v_result, 'review_operation', false)
    );
  end if;
  return v_result;
end
$$;

--
-- Name: FUNCTION gridex_update_company_and_rebuild_legal_profile(p_company_id uuid, p_actor_user_id uuid, p_input jsonb, p_mark_reviewed boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_update_company_and_rebuild_legal_profile(p_company_id uuid, p_actor_user_id uuid, p_input jsonb, p_mark_reviewed boolean) IS 'Canonical atomic write path for company data and generated tenant legal profile. All company editors must call this function.';

--
-- Name: gridex_update_customer_case_status(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_update_customer_case_status(p_case_id uuid, p_company_id uuid, p_status text, p_actor_user_id uuid, p_expected_source text DEFAULT NULL::text, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT public.gridex_update_customer_case_status_with_actor_v1(p_case_id,p_company_id,p_status,p_actor_user_id,p_expected_source,p_message,'ops',NULL)
$$;

--
-- Name: FUNCTION gridex_update_customer_case_status(p_case_id uuid, p_company_id uuid, p_status text, p_actor_user_id uuid, p_expected_source text, p_message text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_update_customer_case_status(p_case_id uuid, p_company_id uuid, p_status text, p_actor_user_id uuid, p_expected_source text, p_message text) IS 'Server-only atomic operational status/event/audit update; no source approval, ACK or business side effects.';

--
-- Name: gridex_update_customer_case_status_with_actor_v1(uuid, uuid, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_update_customer_case_status_with_actor_v1(p_case_id uuid, p_company_id uuid, p_status text, p_actor_user_id uuid, p_expected_source text, p_message text, p_channel text, p_api_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_case public.customer_cases%ROWTYPE;
  v_old_status text;
  v_is_platform boolean;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- Staff authorization owns the entire staff lane, including direct internal
  -- calls to this shared core. Take company/actor/client locks before the case
  -- row and never fall back to the legacy OPS permission catalogue.
  IF p_channel='staff_api' THEN
    PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'cases.write');
  END IF;

  SELECT * INTO v_case FROM public.customer_cases
    WHERE id=p_case_id AND company_id=p_company_id
      AND (p_expected_source IS NULL OR source=p_expected_source)
      AND (p_channel IS DISTINCT FROM 'staff_api' OR (
        metadata->>'support_case'='true' AND case_type='other'
        AND strpos(source,'tenant_support_')=1
        AND NOT billing_blocked AND NOT billing_manual_review AND NOT cancellation_required
      ))
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='customer_case_not_found_in_scope';
  END IF;

  IF p_channel IS DISTINCT FROM 'staff_api' THEN
    v_is_platform := public.canonical_actor_is_platform_admin(p_actor_user_id);
    -- Ediel's operational view is tenant-write only, even when the optional
    -- expected-source argument is omitted. Support retains its platform actor
    -- behavior, still subject to real selected-company membership below.
    IF v_case.source='ediel_inbound_state_machine' AND v_is_platform THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='ediel_case_status_requires_tenant_actor';
    END IF;

    -- The existing scoped permission resolver checks the auth user for deletion
    -- and bans inside its established definer boundary; do not grant this
    -- invoker direct access to auth.users.
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles up
      JOIN public.company_memberships cm ON cm.user_id=up.id AND cm.company_id=v_case.company_id
      JOIN public.companies c ON c.id=cm.company_id
      WHERE up.id=p_actor_user_id AND up.user_status='active'
        AND cm.status='active' AND coalesce(cm.is_active,true)
        AND c.status IN ('active','onboarding') AND coalesce(c.is_active,true)
    ) OR NOT (coalesce(v_is_platform,false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,v_case.company_id,'cases.write'),false))
    THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='customer_case_status_actor_not_authorized';
    END IF;
  END IF;

  v_old_status := v_case.status;
  UPDATE public.customer_cases SET status=p_status, updated_by=p_actor_user_id, updated_at=v_now,
    resolved_at=CASE WHEN p_status='resolved' THEN v_now ELSE resolved_at END,
    closed_at=CASE WHEN p_status='closed' THEN v_now ELSE closed_at END
    WHERE id=v_case.id AND company_id=v_case.company_id
    RETURNING * INTO v_case;

  INSERT INTO public.customer_case_events(
    company_id,customer_case_id,customer_id,event_type,event_status,message,payload,created_by
  ) VALUES (
    v_case.company_id,v_case.id,v_case.customer_id,'status_changed',
    CASE WHEN p_status IN ('closed','resolved') THEN 'success' ELSE 'info' END,
    coalesce(nullif(btrim(p_message),''),'Ärendet uppdaterades till '||p_status||'.'),
    CASE WHEN p_channel='staff_api' THEN
      jsonb_build_object('status',p_status,'channel',p_channel,'api_client_id',p_api_client_id,'actor_user_id',p_actor_user_id)
    ELSE jsonb_build_object('status',p_status) END,p_actor_user_id
  );
  -- The canonical audit trigger fills required actor/request/resource context.
  -- Neither an event error nor an audit error is swallowed: all three writes
  -- belong to this one database transaction and roll back together.
  INSERT INTO public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) VALUES (
    v_case.company_id,p_actor_user_id,'customer_case',v_case.id::text,'customer_case_status_changed',
    jsonb_build_object('status',v_old_status),
    jsonb_build_object('status',p_status,'message',p_message),
    CASE WHEN p_channel='staff_api' THEN
      jsonb_build_object('customer_id',v_case.customer_id,'channel',p_channel,'api_client_id',p_api_client_id)
    ELSE jsonb_build_object('customer_id',v_case.customer_id) END
  );
  RETURN to_jsonb(v_case);
END
$$;

--
-- Name: gridex_update_draft_legal_template_version(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_update_draft_legal_template_version(p_version_id uuid, p_title text, p_body text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_hash text; v_variables text[];
begin
  if nullif(btrim(p_title),'') is null or nullif(btrim(p_body),'') is null then
    raise exception using errcode='22023',message='title_body_required';
  end if;
  v_hash:=encode(digest(btrim(p_title)||E'\n'||p_body,'sha256'),'hex');
  select coalesce(array_agg(distinct m[1] order by m[1]),'{}'::text[]) into v_variables
  from regexp_matches(p_title||E'\n'||p_body,'\{\{[[:space:]]*([a-zA-Z0-9_.-]+)[[:space:]]*\}\}','g') as m;
  update public.legal_template_versions
  set title=btrim(p_title),body=p_body,variables=v_variables,content_sha256=v_hash,reviewed_by=null,
      reviewed_at=null
  where id=p_version_id and status='draft' and locked_at is null;
  if not found then raise exception using errcode='55000',message='only_unlocked_draft_template_can_be_updated'; end if;
  return p_version_id;
end $$;

--
-- Name: gridex_update_jsonb_row(regclass, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_update_jsonb_row(p_table regclass, p_id uuid, p_company_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_assignments text;
  v_sql text;
  v_result jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'row payload must be a JSON object' using errcode = '22023';
  end if;

  select string_agg(format('%1$I = x.%1$I', a.attname), ', ' order by a.attnum)
    into v_assignments
    from pg_attribute a
   where a.attrelid = p_table
     and a.attnum > 0
     and not a.attisdropped
     and a.attgenerated = ''
     and a.attidentity = ''
     and a.attname not in ('id','company_id','created_at','customer_number')
     and p_payload ? a.attname;

  if v_assignments is null then
    execute format('select to_jsonb(t) from %s t where t.id = $1 and t.company_id = $2', p_table)
      into v_result using p_id, p_company_id;
    return v_result;
  end if;

  v_sql := format(
    'update %s t set %s from jsonb_populate_record(null::%s, $1) x where t.id = $2 and t.company_id = $3 returning to_jsonb(t)',
    p_table, v_assignments, p_table
  );
  execute v_sql into v_result using p_payload, p_id, p_company_id;
  return v_result;
end;
$_$;

--
-- Name: gridex_upsert_company_legal_profile_defaults(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_company_legal_profile_defaults(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select public.gridex_rebuild_company_legal_profile(p_company_id,null,false) $$;

--
-- Name: gridex_upsert_customer_action_task(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_customer_action_task(p_company_id uuid, p_customer_id uuid, p_task_type text, p_title text, p_description text DEFAULT NULL::text, p_priority text DEFAULT 'normal'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task_id uuid;
begin
  if p_company_id is null or p_customer_id is null or nullif(btrim(coalesce(p_task_type, '')), '') is null then
    raise exception 'company_id, customer_id and task_type are required';
  end if;

  select id into v_task_id
  from public.customer_operation_tasks
  where company_id = p_company_id
    and customer_id = p_customer_id
    and task_type = p_task_type
    and status in ('open','in_progress','blocked')
  order by created_at desc
  limit 1;

  if v_task_id is null then
    insert into public.customer_operation_tasks(company_id, customer_id, task_type, status, priority, title, description, metadata)
    values (p_company_id, p_customer_id, p_task_type, 'open', coalesce(p_priority, 'normal'), p_title, p_description, coalesce(p_metadata, '{}'::jsonb))
    returning id into v_task_id;
  else
    update public.customer_operation_tasks
    set title = p_title,
        description = p_description,
        priority = coalesce(p_priority, priority),
        metadata = coalesce(p_metadata, '{}'::jsonb),
        updated_at = now()
    where id = v_task_id;
  end if;

  return v_task_id;
end $$;

--
-- Name: gridex_upsert_internal_contract_offer(uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_internal_contract_offer(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_old public.contract_offers%rowtype;
  v_saved public.contract_offers%rowtype;
  v_pricing jsonb;
  v_new_id uuid;
  v_active boolean;
  v_status text;
  v_lifecycle text;
  v_customer_type text;
  v_slug text;
  v_version integer;
  v_canonical uuid;
  v_series uuid;
  v_product_id uuid;
  v_create_version boolean:=false;
  v_invoice_fee numeric;
  v_poa_mode text;
  v_discount_value numeric;
  v_discount_months integer;
  v_auto_renewal boolean;
  v_auto_renewal_term integer;
  v_vat_rate numeric;
begin
  if p_company_id is null or p_actor_user_id is null then
    raise exception using errcode='22023',message='company_actor_required';
  end if;
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,case when p_offer_id is null then 'contracts.create' else 'contracts.edit_draft' end
  );
  perform public.gridex_assert_contract_permission(p_actor_user_id,'pricing.write');

  if p_offer_id is not null then
    select * into v_old from public.contract_offers
    where id=p_offer_id and company_id=p_company_id for update;
    if not found then raise exception using errcode='P0002',message='internal_contract_offer_not_found'; end if;
  end if;

  v_lifecycle:=coalesce(nullif(p_payload->>'lifecycle_status',''),'draft');
  if v_lifecycle not in ('draft','ready') then
    raise exception using errcode='23514',message='contract_draft_save_requires_draft_or_ready';
  end if;

  -- Saving commercial data never publishes it. Publication is a separate
  -- readiness-gated command that promotes and locks the exact same price and
  -- product versions.
  v_status:='draft';
  v_active:=false;
  v_customer_type:=coalesce(nullif(p_payload->>'customer_type',''),'both');
  if v_customer_type not in ('private','business','both') then
    raise exception using errcode='22023',message='invalid_customer_type';
  end if;

  v_invoice_fee:=nullif(replace(coalesce(p_payload->>'invoice_fee_sek',''),',','.'),'')::numeric;
  v_poa_mode:=coalesce(nullif(p_payload->>'power_of_attorney_mode',''),'required_when_information_missing');
  v_discount_value:=nullif(replace(coalesce(p_payload->>'discount_value',''),',','.'),'')::numeric;
  v_discount_months:=nullif(p_payload->>'discount_months','')::integer;
  v_auto_renewal:=coalesce((p_payload->>'automatic_renewal')::boolean,false);
  v_auto_renewal_term:=nullif(p_payload->>'automatic_renewal_term_months','')::integer;
  v_vat_rate:=coalesce(nullif(replace(coalesce(p_payload->>'vat_rate',''),',','.'),'')::numeric,25);
  -- Admin UI sends VAT as percent (25), while canonical database rows store
  -- a fraction (0.25). Direct callers may already send the canonical fraction.
  if v_vat_rate>1 and v_vat_rate<=100 then v_vat_rate:=v_vat_rate/100; end if;
  if v_poa_mode not in ('always_required','required_when_information_missing','not_required') then
    raise exception using errcode='22023',message='invalid_power_of_attorney_mode';
  end if;
  if v_discount_value is not null and (v_discount_value<0 or v_discount_months is null or v_discount_months<1) then
    raise exception using errcode='23514',message='invalid_discount_configuration';
  end if;
  if coalesce(p_payload->>'discount_unit','')='percent' and coalesce(v_discount_value,0)>100 then
    raise exception using errcode='23514',message='invalid_discount_percent';
  end if;
  if v_auto_renewal and coalesce(v_auto_renewal_term,0)<1 then
    raise exception using errcode='23514',message='automatic_renewal_term_missing';
  end if;
  if v_vat_rate<0 or v_vat_rate>1 then
    raise exception using errcode='23514',message='invalid_vat_rate';
  end if;
  if coalesce(nullif(p_payload->>'start_fee_sek','')::numeric,0)<0
     or coalesce(nullif(p_payload->>'admin_fee_sek','')::numeric,0)<0
     or coalesce(nullif(p_payload->>'break_fee_sek','')::numeric,0)<0
     or coalesce(nullif(p_payload->>'monthly_fee_sek','')::numeric,0)<0 then
    raise exception using errcode='23514',message='negative_contract_fee_not_allowed';
  end if;
  if v_active and v_invoice_fee is null then
    raise exception using errcode='23514',message='invoice_fee_missing';
  end if;
  if v_invoice_fee is not null and v_invoice_fee<0 then
    raise exception using errcode='23514',message='invalid_invoice_fee';
  end if;

  v_series:=coalesce(v_old.version_series_id,gen_random_uuid());
  v_product_id:=v_old.contract_product_id;
  v_create_version:=v_old.id is not null and (
    v_old.lifecycle_status in ('published','paused','expired','archived','superseded')
    or v_old.contract_product_version_id is not null and exists(
      select 1 from public.contract_product_versions cpv
      where cpv.id=v_old.contract_product_version_id and cpv.locked_at is not null
    )
    or exists(select 1 from public.customer_contracts c where c.company_id=p_company_id and (c.contract_offer_id=v_old.id or c.contract_product_id=v_old.contract_product_id))
  );
  if v_create_version then
    perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.create_version');
    if exists(
      select 1 from public.contract_offers open_draft
      where open_draft.company_id=p_company_id
        and open_draft.version_series_id=v_series
        and open_draft.id<>v_old.id
        and open_draft.lifecycle_status in ('draft','ready')
    ) then
      raise exception using errcode='23505',message='contract_series_open_draft_exists';
    end if;
  end if;

  p_pricing_snapshot:=(coalesce(p_pricing_snapshot,'{}'::jsonb)-'lifecycle_status')||jsonb_build_object(
    'plan_code','contract-'||v_series::text,
    'product_key','contract-'||v_series::text,
    'version_series_id',v_series
  );
  v_pricing:=public.gridex_create_or_version_contract_pricing(
    p_company_id,p_payload->>'name',p_payload->>'contract_type',
    coalesce(p_payload->>'pricing_model','spot'),v_customer_type,p_pricing_snapshot,
    nullif(p_payload->>'valid_from','')::date,nullif(p_payload->>'valid_to','')::date,
    v_active,p_actor_user_id
  );

  v_slug:=coalesce(
    nullif(p_payload->>'slug',''),
    lower(trim(both '-' from regexp_replace(p_payload->>'name','[^a-zA-Z0-9]+','-','g')))
  );
  if v_create_version then
    -- The currently published predecessor stays sellable while the successor
    -- is only a draft. It is superseded atomically only when the successor is
    -- successfully published.
    v_new_id:=gen_random_uuid();
    select coalesce(max(version_number),0)+1 into v_version
    from public.contract_offers where company_id=p_company_id and version_series_id=v_series;
    v_slug:=left(v_slug,105)||'-v'||v_version;
  else
    v_new_id:=coalesce(v_old.id,gen_random_uuid());
    v_version:=coalesce(v_old.version_number,1);
  end if;

  insert into public.contract_offers(
    id,company_id,version_series_id,supersedes_offer_id,contract_product_id,
    name,slug,status,lifecycle_status,contract_type,customer_type,
    campaign_name,campaign_code,campaign_version,price_version,terms_version,offer_version,version_number,
    version_snapshot,max_customers,discount_value,discount_unit,discount_months,discount_calculation_base,discount_starts_on_mode,
    start_fee_sek,admin_fee_sek,break_fee_sek,vat_rate,description,
    fixed_price_ore_per_kwh,spot_markup_ore_per_kwh,variable_fee_ore_per_kwh,monthly_fee_sek,invoice_fee_sek,
    green_fee_mode,green_fee_value,default_binding_months,default_notice_months,optional_fee_lines,
    is_active,valid_from,valid_to,price_plan_id,price_plan_version_id,price_book_id,commercial_snapshot,
    automatic_renewal,automatic_renewal_term_months,power_of_attorney_required,power_of_attorney_mode,
    legal_bundle_id,last_price_change_at,created_by,updated_by,archived_at
  ) values(
    v_new_id,p_company_id,v_series,case when v_create_version then v_old.id else v_old.supersedes_offer_id end,v_product_id,
    p_payload->>'name',v_slug,v_status,v_lifecycle,p_payload->>'contract_type',v_customer_type,
    nullif(p_payload->>'campaign_name',''),nullif(p_payload->>'campaign_code',''),nullif(p_payload->>'campaign_version',''),
    v_pricing->>'version_label',nullif(p_payload->>'terms_version',''),
    coalesce(nullif(p_payload->>'terms_version',''),v_pricing->>'version_label','v1'),v_version,
    jsonb_build_object(
      'model','canonical_contract_product_version','version_series_id',v_series,
      'price_plan_id',v_pricing->>'price_plan_id','price_plan_version_id',v_pricing->>'price_plan_version_id',
      'price_book_id',v_pricing->>'price_book_id','pricing_snapshot',p_pricing_snapshot,
      'legal_source','legal_template_versions'
    ),
    nullif(p_payload->>'max_customers','')::integer,
    v_discount_value,nullif(p_payload->>'discount_unit',''),
    v_discount_months,nullif(p_payload->>'discount_calculation_base',''),
    coalesce(nullif(p_payload->>'discount_starts_on_mode',''),'contract_start'),
    nullif(p_payload->>'start_fee_sek','')::numeric,nullif(p_payload->>'admin_fee_sek','')::numeric,
    nullif(p_payload->>'break_fee_sek','')::numeric,v_vat_rate,
    nullif(p_payload->>'description',''),nullif(p_payload->>'fixed_price_ore_per_kwh','')::numeric,
    nullif(p_payload->>'spot_markup_ore_per_kwh','')::numeric,nullif(p_payload->>'variable_fee_ore_per_kwh','')::numeric,
    nullif(p_payload->>'monthly_fee_sek','')::numeric,v_invoice_fee,
    coalesce(nullif(p_payload->>'green_fee_mode',''),'none'),nullif(p_payload->>'green_fee_value','')::numeric,
    nullif(p_payload->>'default_binding_months','')::integer,nullif(p_payload->>'default_notice_months','')::integer,
    coalesce(p_payload->'optional_fee_lines','[]'::jsonb),v_active,
    nullif(p_payload->>'valid_from','')::date,nullif(p_payload->>'valid_to','')::date,
    (v_pricing->>'price_plan_id')::uuid,(v_pricing->>'price_plan_version_id')::uuid,
    nullif(v_pricing->>'price_book_id','')::uuid,p_pricing_snapshot,
    v_auto_renewal,
    v_auto_renewal_term,
    v_poa_mode<>'not_required',
    v_poa_mode,
    null,case when coalesce((v_pricing->>'reused')::boolean,false) then coalesce(v_old.last_price_change_at,now()) else now() end,
    p_actor_user_id,p_actor_user_id,case when v_lifecycle='archived' then now() else null end
  )
  on conflict(id) do update set
    name=excluded.name,slug=excluded.slug,status=excluded.status,lifecycle_status=excluded.lifecycle_status,
    contract_type=excluded.contract_type,customer_type=excluded.customer_type,campaign_name=excluded.campaign_name,
    campaign_code=excluded.campaign_code,campaign_version=excluded.campaign_version,price_version=excluded.price_version,
    terms_version=excluded.terms_version,offer_version=excluded.offer_version,version_snapshot=excluded.version_snapshot,
    max_customers=excluded.max_customers,discount_value=excluded.discount_value,discount_unit=excluded.discount_unit,
    discount_months=excluded.discount_months,discount_calculation_base=excluded.discount_calculation_base,
    discount_starts_on_mode=excluded.discount_starts_on_mode,start_fee_sek=excluded.start_fee_sek,
    admin_fee_sek=excluded.admin_fee_sek,break_fee_sek=excluded.break_fee_sek,vat_rate=excluded.vat_rate,
    description=excluded.description,fixed_price_ore_per_kwh=excluded.fixed_price_ore_per_kwh,
    spot_markup_ore_per_kwh=excluded.spot_markup_ore_per_kwh,variable_fee_ore_per_kwh=excluded.variable_fee_ore_per_kwh,
    monthly_fee_sek=excluded.monthly_fee_sek,invoice_fee_sek=excluded.invoice_fee_sek,
    green_fee_mode=excluded.green_fee_mode,green_fee_value=excluded.green_fee_value,
    default_binding_months=excluded.default_binding_months,default_notice_months=excluded.default_notice_months,
    optional_fee_lines=excluded.optional_fee_lines,is_active=excluded.is_active,valid_from=excluded.valid_from,
    valid_to=excluded.valid_to,price_plan_id=excluded.price_plan_id,price_plan_version_id=excluded.price_plan_version_id,
    price_book_id=excluded.price_book_id,commercial_snapshot=excluded.commercial_snapshot,
    automatic_renewal=excluded.automatic_renewal,automatic_renewal_term_months=excluded.automatic_renewal_term_months,
    power_of_attorney_required=excluded.power_of_attorney_required,power_of_attorney_mode=excluded.power_of_attorney_mode,
    legal_bundle_id=null,last_price_change_at=excluded.last_price_change_at,
    archived_at=excluded.archived_at,updated_by=excluded.updated_by,updated_at=now()
  returning * into v_saved;

  v_canonical:=public.gridex_sync_internal_offer_to_canonical(v_saved.id);
  select * into v_saved from public.contract_offers where id=v_saved.id;

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_offer',v_saved.id::text,
    case when v_create_version then 'contract.version.created'
         when p_offer_id is null then 'contract.draft.created'
         else 'contract.draft.updated' end,
    case when v_old.id is null then null else to_jsonb(v_old) end,to_jsonb(v_saved),
    jsonb_build_object(
      'version_series_id',v_series,'contract_product_id',v_saved.contract_product_id,
      'contract_product_version_id',v_canonical,'price_plan_version_id',v_saved.price_plan_version_id,
      'lifecycle_status',v_lifecycle,'readiness','{}'::jsonb
    )
  );

  return jsonb_build_object(
    'offer',to_jsonb(v_saved),'pricing',v_pricing,
    'contract_product_id',v_saved.contract_product_id,
    'contract_product_version_id',v_canonical,
    'version_series_id',v_series,
    'created_new_version',v_create_version,
    'readiness','{}'::jsonb,
    'legal_source','legal_template_versions'
  );
end $$;

--
-- Name: FUNCTION gridex_upsert_internal_contract_offer(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_upsert_internal_contract_offer(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) IS 'Creates/updates draft or creates immutable version in one stable contract product series.';

--
-- Name: gridex_upsert_internal_contract_offer_v2(uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_internal_contract_offer_v2(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_offer_id uuid;
  v_product_id uuid;
  v_version_id uuid;
  v_assignment_id uuid;
  v_lifecycle_status text;
  v_existing_direction text;
  v_energy_direction text:=lower(coalesce(
    nullif(p_pricing_snapshot->>'energy_direction',''),
    nullif(p_payload->>'energy_direction','')
  ));
begin
  if v_energy_direction is null or v_energy_direction not in ('consumption','production') then
    return jsonb_build_object(
      'ok',false,'code','energy_direction_invalid',
      'message','Avtalsriktningen måste vara consumption eller production.',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'energy_direction_invalid','energy_direction',
        'Avtalsriktningen måste vara consumption eller production.',
        to_jsonb(v_energy_direction),'contract_offer',p_offer_id
      ))
    );
  end if;
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    case when p_offer_id is null then 'contracts.create' else 'contracts.edit_draft' end
  );

  if p_offer_id is not null then
    select o.lifecycle_status,o.energy_direction
      into v_lifecycle_status,v_existing_direction
    from public.contract_offers o
    where o.id=p_offer_id and o.company_id=p_company_id
    for update;
    if not found then
      return jsonb_build_object(
        'ok',false,'code','contract_not_found','message','Avtalet hittades inte för valt bolag.',
        'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'contract_offer_not_found','contract_offer_id',
          'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
          'contract_offer',p_offer_id
        ))
      );
    end if;
    if v_existing_direction is not null and v_existing_direction<>v_energy_direction then
      return jsonb_build_object(
        'ok',false,'code','energy_direction_change_requires_successor',
        'message','Avtalsriktningen är produktidentitet och får inte ändras i samma produktserie.',
        'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'energy_direction_change_requires_successor','energy_direction',
          'Skapa en separat efterföljande produkt för den andra energiriktningen.',
          to_jsonb(v_energy_direction),'contract_offer',p_offer_id,
          jsonb_build_object('current_direction',v_existing_direction,'recommended_action','create_successor_product')
        )),
        'recommended_action','create_successor_product'
      );
    end if;
    if v_lifecycle_status='archived' then
      return jsonb_build_object(
        'ok',false,'code','contract_archived','message','Ett arkiverat avtal är terminalt. Skapa en separat efterföljande produkt i stället.',
        'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'contract_archived','lifecycle_status',
          'Arkiverade avtal får inte redigeras eller få en vanlig ny version.',
          to_jsonb(v_lifecycle_status),'contract_offer',p_offer_id,
          jsonb_build_object('recommended_action','create_successor_product')
        )),
        'recommended_action','create_successor_product'
      );
    end if;
    if v_lifecycle_status='closed' then
      return jsonb_build_object(
        'ok',false,'code','contract_closed','message','Ett stängt avtal är terminalt och får inte versioneras.',
        'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'contract_closed_terminal','lifecycle_status',
          'Stängda avtal får inte redigeras eller versioneras.',
          to_jsonb(v_lifecycle_status),'contract_offer',p_offer_id
        ))
      );
    end if;
  end if;

  v_result:=public.gridex_upsert_internal_contract_offer(
    p_company_id,p_offer_id,p_payload,p_pricing_snapshot,p_actor_user_id
  );
  v_offer_id:=nullif(v_result#>>'{offer,id}','')::uuid;
  v_product_id:=nullif(v_result->>'contract_product_id','')::uuid;
  v_version_id:=nullif(v_result->>'contract_product_version_id','')::uuid;

  if v_offer_id is null or v_product_id is null or v_version_id is null then
    raise exception using errcode='23502',message='contract_create_canonical_ids_incomplete';
  end if;

  update public.contract_offers
  set energy_direction=v_energy_direction,updated_at=now()
  where id=v_offer_id and company_id=p_company_id;
  update public.contract_products
  set energy_direction=v_energy_direction,updated_at=now()
  where id=v_product_id and company_id=p_company_id;
  update public.contract_product_versions
  set energy_direction=v_energy_direction
  where id=v_version_id
    and contract_product_id=v_product_id
    and locked_at is null;
  if not exists(
    select 1
    from public.contract_offers o
    join public.contract_products cp on cp.id=o.contract_product_id
    join public.contract_product_versions cpv
      on cpv.id=o.contract_product_version_id
     and cpv.contract_product_id=cp.id
    where o.id=v_offer_id
      and o.company_id=p_company_id
      and cp.id=v_product_id
      and cpv.id=v_version_id
  ) then
    raise exception using errcode='23514',message='contract_create_canonical_graph_mismatch';
  end if;

  select ta.id into v_assignment_id
  from public.tenant_contract_assignments ta
  where ta.company_id=p_company_id
    and ta.contract_product_version_id=v_version_id
  order by ta.created_at desc,ta.id
  limit 1;
  if v_assignment_id is null then
    raise exception using errcode='23502',message='contract_create_tenant_assignment_missing';
  end if;

  return v_result||jsonb_build_object(
    'ok',true,
    'tenant_contract_assignment_id',v_assignment_id,
    'company_id',p_company_id
  );
end
$$;

--
-- Name: FUNCTION gridex_upsert_internal_contract_offer_v2(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_upsert_internal_contract_offer_v2(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) IS 'Service-only canonical create/version command. Actor is session-verified by the server action; archived and closed products are terminal.';

--
-- Name: gridex_upsert_internal_contract_offer_v3(uuid, uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_internal_contract_offer_v3(p_company_id uuid, p_offer_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_result jsonb;
  v_contract_product_version_id uuid;
  v_price_plan_version_id uuid;
  v_option jsonb;
  v_area jsonb;
  v_component jsonb;
  v_option_id uuid;
  v_option_references text[] := '{}'::text[];
  v_component_references text[] := '{}'::text[];
begin
  if p_pricing_snapshot->>'snapshot_schema'
      <> 'gridex_contract_pricing_v6_selection'
    or jsonb_typeof(p_pricing_snapshot->'price_options')<>'array'
    or jsonb_array_length(p_pricing_snapshot->'price_options')=0
    or jsonb_typeof(p_pricing_snapshot->'commercial_components')<>'array'
    or jsonb_typeof(p_pricing_snapshot->'invoice_delivery_methods')<>'array'
    or jsonb_array_length(p_pricing_snapshot->'invoice_delivery_methods')=0 then
    raise exception using
      errcode='22023',
      message='commercial_pricing_snapshot_incomplete';
  end if;

  v_result:=public.gridex_upsert_internal_contract_offer_v2(
    p_company_id,p_offer_id,p_payload,p_pricing_snapshot,p_actor_user_id
  );
  if coalesce((v_result->>'ok')::boolean,true)=false then
    return v_result;
  end if;
  v_contract_product_version_id :=
    nullif(v_result->>'contract_product_version_id','')::uuid;
  v_price_plan_version_id :=
    nullif(v_result#>>'{pricing,price_plan_version_id}','')::uuid;
  if v_contract_product_version_id is null
    or v_price_plan_version_id is null then
    raise exception using
      errcode='23502',
      message='commercial_pricing_canonical_version_missing';
  end if;

  for v_option in
    select value from jsonb_array_elements(
      p_pricing_snapshot->'price_options'
    )
  loop
    if coalesce(v_option->>'price_option_reference','')
        !~ '^[a-z0-9][a-z0-9_-]{2,99}$'
      or coalesce(v_option->>'option_code','')
        !~ '^[a-z0-9][a-z0-9_-]{2,99}$'
      or v_option->>'contract_type'<>p_payload->>'contract_type'
      or jsonb_typeof(v_option->'area_prices')<>'array' then
      raise exception using
        errcode='22023',
        message='commercial_price_option_invalid';
    end if;
    if v_option->>'contract_type'='fixed'
      and jsonb_array_length(v_option->'area_prices')=0 then
      raise exception using
        errcode='22023',
        message='fixed_price_option_area_price_missing';
    end if;

    insert into public.contract_price_options(
      company_id,contract_product_version_id,price_plan_version_id,
      option_reference,option_code,customer_name,internal_description,
      contract_type,binding_months,notice_months,auto_renew_enabled,
      renewal_term_months,valid_from,valid_to,earliest_start_date,
      latest_start_date,status,sort_order,version_number,metadata,created_by
    ) values(
      p_company_id,v_contract_product_version_id,v_price_plan_version_id,
      v_option->>'price_option_reference',v_option->>'option_code',
      v_option->>'customer_name',nullif(v_option->>'internal_description',''),
      v_option->>'contract_type',(v_option->>'binding_months')::integer,
      (v_option->>'notice_months')::integer,
      (v_option->>'auto_renew_enabled')::boolean,
      nullif(v_option->>'renewal_term_months','')::integer,
      nullif(v_option->>'valid_from','')::date,
      nullif(v_option->>'valid_to','')::date,
      nullif(v_option->>'earliest_start_date','')::date,
      nullif(v_option->>'latest_start_date','')::date,
      v_option->>'status',(v_option->>'sort_order')::integer,
      coalesce((v_option->>'version_number')::integer,1),
      coalesce(v_option->'metadata','{}'::jsonb),p_actor_user_id
    )
    returning id into v_option_id;

    v_option_references:=array_append(
      v_option_references,v_option->>'price_option_reference'
    );
    for v_area in
      select value from jsonb_array_elements(v_option->'area_prices')
    loop
      insert into public.contract_price_option_area_prices(
        company_id,contract_price_option_id,price_plan_version_id,
        price_row_reference,price_area,amount,unit,vat_treatment,
        valid_from,valid_to,metadata,created_by
      ) values(
        p_company_id,v_option_id,v_price_plan_version_id,
        v_area->>'price_row_reference',v_area->>'price_area',
        (v_area->>'amount')::numeric,v_area->>'unit',
        coalesce(v_area->>'vat_treatment','standard'),
        nullif(v_area->>'valid_from','')::date,
        nullif(v_area->>'valid_to','')::date,
        coalesce(v_area->'metadata','{}'::jsonb),p_actor_user_id
      );
    end loop;
  end loop;

  for v_component in
    select value from jsonb_array_elements(
      p_pricing_snapshot->'commercial_components'
    )
  loop
    if coalesce(v_component->>'component_reference','')
        !~ '^[a-z0-9][a-z0-9_-]{2,99}$'
      or coalesce(v_component->>'component_code','')
        !~ '^[a-z0-9][a-z0-9_-]{2,99}$'
      or v_component->>'selection_policy' not in (
        'mandatory','customer_optional','admin_optional','conditional'
      )
      or (
        v_component->>'unit'='percent'
        and nullif(v_component->>'calculation_base','') is null
      ) then
      raise exception using
        errcode='22023',
        message='commercial_price_component_invalid';
    end if;

    insert into public.price_components(
      company_id,price_plan_version_id,component_type,name,description,
      calculation_type,calculation_base,amount,unit,vat_applicable,
      invoice_line_visible,periodization_mode,priority,valid_from,valid_to,
      status,metadata,created_by,component_reference,component_code,
      customer_name,internal_name,selection_policy,default_selected,
      customer_can_deselect,admin_must_select,informational_only,lifecycle,
      periodization_rule,invoice_line_name,accounting_classification,
      vat_treatment,website_published,conditions
    ) values(
      p_company_id,v_price_plan_version_id,
      v_component->>'component_type',v_component->>'customer_name',
      nullif(v_component->>'customer_description',''),
      v_component->>'calculation_type',
      nullif(v_component->>'calculation_base',''),
      (v_component->>'amount')::numeric,v_component->>'unit',
      coalesce(v_component->>'vat_treatment','standard')<>'exempt',
      not coalesce((v_component->>'informational_only')::boolean,false),
      coalesce(v_component->>'periodization_rule','none'),
      (v_component->>'sort_order')::integer,
      nullif(v_component->>'valid_from','')::date,
      nullif(v_component->>'valid_to','')::date,'active',
      coalesce(v_component->'metadata','{}'::jsonb)
        || jsonb_build_object(
          'component_reference',v_component->>'component_reference',
          'component_code',v_component->>'component_code',
          'selection_policy',v_component->>'selection_policy',
          'lifecycle',v_component->>'lifecycle',
          'conditions',coalesce(v_component->'conditions','{}'::jsonb)
        ),
      p_actor_user_id,v_component->>'component_reference',
      v_component->>'component_code',v_component->>'customer_name',
      v_component->>'internal_name',v_component->>'selection_policy',
      (v_component->>'default_selected')::boolean,
      (v_component->>'customer_can_deselect')::boolean,
      (v_component->>'admin_must_select')::boolean,
      coalesce((v_component->>'informational_only')::boolean,false),
      v_component->>'lifecycle',v_component->>'periodization_rule',
      v_component->>'invoice_line_name',
      v_component->>'accounting_classification',
      v_component->>'vat_treatment',
      coalesce((v_component->>'website_published')::boolean,true),
      coalesce(v_component->'conditions','{}'::jsonb)
    );
    v_component_references:=array_append(
      v_component_references,v_component->>'component_reference'
    );
  end loop;

  return v_result||jsonb_build_object(
    'price_option_references',to_jsonb(v_option_references),
    'component_references',to_jsonb(v_component_references),
    'commercial_snapshot_schema','gridex_contract_pricing_v6_selection'
  );
exception
  when unique_violation then
    raise exception using
      errcode='23505',
      message='commercial_pricing_reference_duplicate';
end
$_$;

--
-- Name: gridex_upsert_public_contract_offer(uuid, uuid, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_upsert_public_contract_offer(p_company_id uuid, p_offer_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_old public.public_contract_offers%rowtype; v_saved public.public_contract_offers%rowtype; v_pricing jsonb;
  v_series uuid; v_version integer; v_actual_code text; v_publish boolean; v_publication_id uuid; v_cpv public.contract_publication_versions;
begin
  if p_company_id is null or p_actor_user_id is null then raise exception 'Bolag och aktör krävs.'; end if;
  v_publish:=coalesce(p_payload->>'publication_status','draft')='published';
  if p_offer_id is not null then select * into v_old from public.public_contract_offers where id=p_offer_id and company_id=p_company_id for update; end if;
  if p_offer_id is not null and not found then raise exception 'Avtalet hittades inte för bolaget.'; end if;
  v_series:=coalesce(v_old.version_series_id,gen_random_uuid());
  if v_old.id is not null and v_old.publication_status='published' then
    select coalesce(max(version_number),0)+1 into v_version from public.public_contract_offers where company_id=p_company_id and version_series_id=v_series;
  else v_version:=coalesce(v_old.version_number,1); end if;
  v_actual_code:=case when v_version=1 then p_offer_code else left(regexp_replace(p_offer_code,'-v[0-9]+$','','i'),100)||'-v'||v_version end;
  p_pricing_snapshot:=p_pricing_snapshot||jsonb_build_object('plan_code','contract-'||v_series::text,'product_key',v_series::text);
  v_pricing:=public.gridex_create_or_version_contract_pricing(p_company_id,p_payload->>'public_name',p_payload->>'contract_type',coalesce(p_payload->>'pricing_model','spot'),p_payload->>'customer_type',p_pricing_snapshot,
    nullif(p_payload->>'valid_from','')::date,nullif(p_payload->>'valid_to','')::date,v_publish,p_actor_user_id);
  perform set_config('gridex.public_offer_write','on',true);

  if v_old.id is not null and v_old.publication_status<>'published' then
    update public.public_contract_offers set
      offer_code=v_actual_code,public_name=p_payload->>'public_name',public_description=nullif(p_payload->>'public_description',''),product_code=coalesce(nullif(p_payload->>'product_code',''),'electricity'),
      contract_type=p_payload->>'contract_type',billing_model=p_payload->>'billing_model',customer_type=p_payload->>'customer_type',price_plan_id=(v_pricing->>'price_plan_id')::uuid,price_plan_version_id=(v_pricing->>'price_plan_version_id')::uuid,price_book_id=(v_pricing->>'price_book_id')::uuid,
      campaign_version_id=nullif(p_payload->>'campaign_version_id','')::uuid,legal_bundle_id=nullif(p_payload->>'legal_bundle_id','')::uuid,
      monthly_fee_sek=nullif(p_payload->>'monthly_fee_sek','')::numeric,invoice_fee_sek=nullif(p_payload->>'invoice_fee_sek','')::numeric,markup_ore_per_kwh=nullif(p_payload->>'markup_ore_per_kwh','')::numeric,spot_markup_ore_per_kwh=nullif(p_payload->>'spot_markup_ore_per_kwh','')::numeric,
      variable_fee_ore_per_kwh=nullif(p_payload->>'variable_fee_ore_per_kwh','')::numeric,fixed_price_ore_per_kwh=nullif(p_payload->>'fixed_price_ore_per_kwh','')::numeric,green_fee_mode=nullif(p_payload->>'green_fee_mode',''),green_fee_value=nullif(p_payload->>'green_fee_value','')::numeric,
      electricity_certificate_ore_per_kwh=nullif(p_payload->>'electricity_certificate_ore_per_kwh','')::numeric,start_fee_sek=nullif(p_payload->>'start_fee_sek','')::numeric,administration_fee_sek=nullif(p_payload->>'administration_fee_sek','')::numeric,break_fee_sek=nullif(p_payload->>'break_fee_sek','')::numeric,portfolio_management_fee_ore_per_kwh=nullif(p_payload->>'portfolio_management_fee_ore_per_kwh','')::numeric,
      discount_value=nullif(p_payload->>'discount_value','')::numeric,discount_unit=nullif(p_payload->>'discount_unit',''),discount_months=nullif(p_payload->>'discount_months','')::integer,vat_rate=coalesce(nullif(p_payload->>'vat_rate','')::numeric,25),
      terms_version=nullif(p_payload->>'terms_version',''),terms_url=nullif(p_payload->>'terms_url',''),public_price_text=p_payload->>'public_price_text',binding_months=nullif(p_payload->>'binding_months','')::integer,notice_months=nullif(p_payload->>'notice_months','')::integer,
      automatic_renewal=coalesce((p_payload->>'automatic_renewal')::boolean,false),power_of_attorney_required=coalesce((p_payload->>'power_of_attorney_required')::boolean,true),
      spot_weight_percent=coalesce(nullif(p_payload->>'spot_weight_percent','')::numeric,100),portfolio_weight_percent=coalesce(nullif(p_payload->>'portfolio_weight_percent','')::numeric,0),fixed_weight_percent=coalesce(nullif(p_payload->>'fixed_weight_percent','')::numeric,0),
      price_area=nullif(p_payload->>'price_area',''),price_areas=coalesce(array(select jsonb_array_elements_text(coalesce(p_pricing_snapshot->'price_areas','[]'::jsonb))),'{}'::text[]),valid_from=nullif(p_payload->>'valid_from','')::date,valid_to=nullif(p_payload->>'valid_to','')::date,
      publication_status=p_payload->>'publication_status',website_enabled=coalesce((p_payload->>'website_enabled')::boolean,false),website_cta_enabled=coalesce((p_payload->>'website_cta_enabled')::boolean,true),is_public=v_publish,is_archived=coalesce((p_payload->>'is_archived')::boolean,false),
      sort_order=coalesce(nullif(p_payload->>'sort_order','')::integer,100),readiness_issues=coalesce(p_payload->'readiness_issues','[]'),publication_notes=nullif(p_payload->>'publication_notes',''),published_at=case when v_publish then now() end,archived_at=case when coalesce((p_payload->>'is_archived')::boolean,false) then now() end,
      metadata=coalesce(v_old.metadata,'{}')||coalesce(p_payload->'metadata','{}')||jsonb_build_object('pricing_snapshot',p_pricing_snapshot),updated_by=p_actor_user_id,updated_at=now()
    where id=v_old.id returning * into v_saved;
  else
    if v_old.id is not null and v_old.publication_status='published' then
      update public.public_contract_offers
      set publication_status='superseded',is_public=false,is_archived=true,website_enabled=false,website_cta_enabled=false,archived_at=now(),updated_by=p_actor_user_id,updated_at=now()
      where id=v_old.id;
    end if;
    insert into public.public_contract_offers(company_id,version_series_id,version_number,supersedes_offer_id,offer_code,public_name,public_description,product_code,contract_type,billing_model,customer_type,price_plan_id,price_plan_version_id,price_book_id,campaign_version_id,legal_bundle_id,
      monthly_fee_sek,invoice_fee_sek,markup_ore_per_kwh,spot_markup_ore_per_kwh,variable_fee_ore_per_kwh,fixed_price_ore_per_kwh,green_fee_mode,green_fee_value,electricity_certificate_ore_per_kwh,start_fee_sek,administration_fee_sek,break_fee_sek,portfolio_management_fee_ore_per_kwh,discount_value,discount_unit,discount_months,vat_rate,terms_version,terms_url,public_price_text,binding_months,notice_months,automatic_renewal,power_of_attorney_required,spot_weight_percent,portfolio_weight_percent,fixed_weight_percent,price_area,price_areas,valid_from,valid_to,publication_status,website_enabled,website_cta_enabled,is_public,is_archived,sort_order,readiness_issues,publication_notes,published_at,archived_at,metadata,created_by,updated_by)
    values(p_company_id,v_series,v_version,v_old.id,v_actual_code,p_payload->>'public_name',nullif(p_payload->>'public_description',''),coalesce(nullif(p_payload->>'product_code',''),'electricity'),p_payload->>'contract_type',p_payload->>'billing_model',p_payload->>'customer_type',(v_pricing->>'price_plan_id')::uuid,(v_pricing->>'price_plan_version_id')::uuid,(v_pricing->>'price_book_id')::uuid,nullif(p_payload->>'campaign_version_id','')::uuid,nullif(p_payload->>'legal_bundle_id','')::uuid,
      nullif(p_payload->>'monthly_fee_sek','')::numeric,nullif(p_payload->>'invoice_fee_sek','')::numeric,nullif(p_payload->>'markup_ore_per_kwh','')::numeric,nullif(p_payload->>'spot_markup_ore_per_kwh','')::numeric,nullif(p_payload->>'variable_fee_ore_per_kwh','')::numeric,nullif(p_payload->>'fixed_price_ore_per_kwh','')::numeric,nullif(p_payload->>'green_fee_mode',''),nullif(p_payload->>'green_fee_value','')::numeric,nullif(p_payload->>'electricity_certificate_ore_per_kwh','')::numeric,nullif(p_payload->>'start_fee_sek','')::numeric,nullif(p_payload->>'administration_fee_sek','')::numeric,nullif(p_payload->>'break_fee_sek','')::numeric,nullif(p_payload->>'portfolio_management_fee_ore_per_kwh','')::numeric,nullif(p_payload->>'discount_value','')::numeric,nullif(p_payload->>'discount_unit',''),nullif(p_payload->>'discount_months','')::integer,coalesce(nullif(p_payload->>'vat_rate','')::numeric,25),nullif(p_payload->>'terms_version',''),nullif(p_payload->>'terms_url',''),p_payload->>'public_price_text',nullif(p_payload->>'binding_months','')::integer,nullif(p_payload->>'notice_months','')::integer,coalesce((p_payload->>'automatic_renewal')::boolean,false),coalesce((p_payload->>'power_of_attorney_required')::boolean,true),coalesce(nullif(p_payload->>'spot_weight_percent','')::numeric,100),coalesce(nullif(p_payload->>'portfolio_weight_percent','')::numeric,0),coalesce(nullif(p_payload->>'fixed_weight_percent','')::numeric,0),nullif(p_payload->>'price_area',''),coalesce(array(select jsonb_array_elements_text(coalesce(p_pricing_snapshot->'price_areas','[]'::jsonb))),'{}'::text[]),nullif(p_payload->>'valid_from','')::date,nullif(p_payload->>'valid_to','')::date,p_payload->>'publication_status',coalesce((p_payload->>'website_enabled')::boolean,false),coalesce((p_payload->>'website_cta_enabled')::boolean,true),v_publish,coalesce((p_payload->>'is_archived')::boolean,false),coalesce(nullif(p_payload->>'sort_order','')::integer,100),coalesce(p_payload->'readiness_issues','[]'),nullif(p_payload->>'publication_notes',''),case when v_publish then now() end,case when coalesce((p_payload->>'is_archived')::boolean,false) then now() end,coalesce(p_payload->'metadata','{}')||jsonb_build_object('pricing_snapshot',p_pricing_snapshot),p_actor_user_id,p_actor_user_id)
    returning * into v_saved;
  end if;

  v_publication_id:=public.gridex_sync_public_offer_to_canonical(v_saved.id);
  select * into v_cpv from public.contract_publication_versions where id=v_publication_id;
  select * into v_saved from public.public_contract_offers where id=v_saved.id;
  return jsonb_build_object('offer',to_jsonb(v_saved),'pricing',v_pricing,'contract_publication_version_id',v_publication_id,'offer_reference',v_cpv.offer_reference,'created_new_version',v_old.id is not null and v_old.publication_status='published');
end $_$;

--
-- Name: gridex_user_can_manage_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_user_can_manage_company(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.gridex_is_current_session_allowed()
    and (
      public.gridex_user_is_platform_admin()
      or (
        exists (
          select 1
          from public.companies company
          where company.id = p_company_id
            and company.status in ('active', 'onboarding')
        )
        and exists (
          select 1
          from public.company_memberships membership
          where membership.company_id = p_company_id
            and membership.user_id = (select auth.uid())
            and coalesce(membership.status, 'active') = 'active'
            and coalesce(membership.is_active, true)
            and coalesce(membership.membership_role, 'member')
              in ('owner', 'admin', 'company_admin')
        )
      )
    )
$$;

--
-- Name: gridex_user_can_read_whitelabel_platform(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_user_can_read_whitelabel_platform(p_white_label_platform_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
-- plpgsql (not sql) so the body is resolved at call time: the white-label tables
-- are absent in the canonical clean replay (see 20260829194612).
begin
  return p_white_label_platform_id is not null
    and public.gridex_is_current_session_allowed()
    and (
      public.gridex_user_is_platform_admin()
      or exists (
        select 1
        from public.white_label_platform_memberships m
        join public.white_label_platforms p on p.id = m.white_label_platform_id
        where m.white_label_platform_id = p_white_label_platform_id
          and m.user_id = auth.uid()
          and m.status = 'active'
          and p.status <> 'archived'
      )
    );
end;
$$;

--
-- Name: gridex_user_company_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_user_company_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select membership.company_id
  from public.company_memberships membership
  join public.companies company on company.id = membership.company_id
  where public.gridex_is_current_session_allowed()
    and membership.user_id = (select auth.uid())
    and coalesce(membership.status, 'active') = 'active'
    and coalesce(membership.is_active, true)
    and company.status in ('active', 'onboarding', 'paused')
$$;

--
-- Name: gridex_user_has_role_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_user_has_role_key(p_role_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
declare
  has_role_id boolean := false;
  has_role_text boolean := false;
  has_role_key boolean := false;
  has_status boolean := false;
  has_is_active boolean := false;
  sql text;
  result boolean := false;
begin
  if p_role_key is null or auth.uid() is null then
    return false;
  end if;
  if to_regclass('public.user_roles') is null then
    return false;
  end if;

  select exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_roles' and column_name='role_id') into has_role_id;
  select exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_roles' and column_name='role') into has_role_text;
  select exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_roles' and column_name='role_key') into has_role_key;
  select exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_roles' and column_name='status') into has_status;
  select exists(select 1 from information_schema.columns where table_schema='public' and table_name='user_roles' and column_name='is_active') into has_is_active;

  sql := 'select exists (select 1 from public.user_roles ur ';
  if has_role_id and to_regclass('public.roles') is not null then
    sql := sql || 'left join public.roles r on r.id = ur.role_id ';
  end if;
  sql := sql || 'where ur.user_id = $1 and (';

  if has_role_text then
    sql := sql || 'lower(coalesce(ur.role, '''')) = lower($2)';
  else
    sql := sql || 'false';
  end if;
  if has_role_key then
    sql := sql || ' or lower(coalesce(ur.role_key, '''')) = lower($2)';
  end if;
  if has_role_id and to_regclass('public.roles') is not null then
    sql := sql || ' or lower(coalesce(r.key, r.name, '''')) = lower($2)';
  end if;
  sql := sql || ')';

  if has_status then
    sql := sql || ' and coalesce(ur.status, ''active'') = ''active''';
  end if;
  if has_is_active then
    sql := sql || ' and coalesce(ur.is_active, true) = true';
  end if;

  sql := sql || ')';
  execute sql into result using auth.uid(), p_role_key;
  return coalesce(result, false);
exception when others then
  return false;
end;
$_$;

--
-- Name: gridex_user_is_platform_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_user_is_platform_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select auth.uid() is not null
    and exists (
      select 1
      from auth.users u
      join public.user_profiles up on up.id = u.id
      where u.id = auth.uid()
        and u.deleted_at is null
        and (u.banned_until is null or u.banned_until <= now())
        and u.email_confirmed_at is not null
        and up.user_status = 'active'
    )
    and (
      exists (
        select 1
        from public.admin_users au
        where au.user_id = auth.uid()
          and coalesce(au.is_active, true)
          and public.gridex_normalize_platform_role(au.role)
            in ('super_admin', 'platform_admin')
      )
      or exists (
        select 1
        from public.user_roles ur
        left join public.roles r on r.id = ur.role_id
        where ur.user_id = auth.uid()
          and ur.company_id is null
          and coalesce(ur.is_active, true)
          and coalesce(ur.status, 'active') = 'active'
          and public.gridex_normalize_platform_role(
            coalesce(ur.role, r.key, r.name)
          ) in ('super_admin', 'platform_admin')
      )
    )
$$;

--
-- Name: FUNCTION gridex_user_is_platform_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_user_is_platform_admin() IS 'Global platform-admin helper. user_roles grants are global only when company_id IS NULL and the Auth/profile identity is functioning.';

--
-- Name: gridex_validate_commercial_model_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_commercial_model_v1(p_company_id uuid, p_contract_product_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with version_row as (
    select version.id,version.contract_type,version.price_plan_version_id,
      version.commercial_snapshot
    from public.contract_product_versions version
    join public.contract_products product
      on product.id=version.contract_product_id
    where version.id=p_contract_product_version_id
      and product.company_id=p_company_id
  ), blockers as (
    select jsonb_build_object(
      'code','commercial_price_option_missing',
      'field','price_options',
      'message','Avtalsversionen saknar ett persistent prisalternativ.'
    ) blocker
    from version_row
    where commercial_snapshot->>'snapshot_schema'
        ='gridex_contract_pricing_v6_selection'
      and not exists(
        select 1 from public.contract_price_options option_row
        where option_row.company_id=p_company_id
          and option_row.contract_product_version_id=version_row.id
          and option_row.status='active'
      )
    union all
    select jsonb_build_object(
      'code','fixed_area_price_incomplete',
      'field','price_options',
      'message','Ett aktivt fastprisalternativ saknar en SE-områdesrad.'
    )
    from version_row
    where contract_type='fixed'
      and commercial_snapshot->>'snapshot_schema'
        ='gridex_contract_pricing_v6_selection'
      and exists(
        select 1
        from public.contract_price_options option_row
        where option_row.contract_product_version_id=version_row.id
          and option_row.status='active'
          and not exists(
            select 1
            from public.contract_price_option_area_prices area_row
            where area_row.contract_price_option_id=option_row.id
          )
      )
    union all
    select jsonb_build_object(
      'code','commercial_component_incomplete',
      'field','commercial_components',
      'message','En kommersiell komponent saknar stabil identitet eller fakturarad.'
    )
    from version_row
    where commercial_snapshot->>'snapshot_schema'
        ='gridex_contract_pricing_v6_selection'
      and exists(
        select 1 from public.price_components component
        where component.price_plan_version_id=version_row.price_plan_version_id
          and component.component_reference is not null
          and (
            component.component_code is null
            or component.selection_policy is null
            or nullif(component.invoice_line_name,'') is null
            or (
              component.unit='percent'
              and nullif(component.calculation_base,'') is null
            )
          )
      )
  )
  select jsonb_build_object(
    'ready',count(*)=0,
    'blockers',coalesce(jsonb_agg(blocker),'[]'::jsonb)
  )
  from blockers
$$;

--
-- Name: gridex_validate_company_legal_fields_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_company_legal_fields_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.country_code := public.gridex_normalize_country_code(new.country_code, 'SE');
  if new.complaints_country_code is not null then
    new.complaints_country_code := public.gridex_normalize_country_code(new.complaints_country_code, new.country_code);
  end if;
  if new.data_protection_country_code is not null then
    new.data_protection_country_code := public.gridex_normalize_country_code(new.data_protection_country_code, new.country_code);
  end if;
  if new.billing_country_code is not null then
    new.billing_country_code := public.gridex_normalize_country_code(new.billing_country_code, new.country_code);
  end if;

  new.postal_code := public.gridex_normalize_postal_code(new.postal_code, new.country_code);
  new.complaints_postal_code := public.gridex_normalize_postal_code(new.complaints_postal_code, coalesce(new.complaints_country_code, new.country_code));
  new.data_protection_postal_code := public.gridex_normalize_postal_code(new.data_protection_postal_code, coalesce(new.data_protection_country_code, new.country_code));
  new.billing_postal_code := public.gridex_normalize_postal_code(new.billing_postal_code, coalesce(new.billing_country_code, new.country_code));

  if new.org_number is not null then
    new.org_number := public.gridex_normalize_swedish_organization_number(new.org_number);
  end if;
  return new;
end
$$;

--
-- Name: gridex_validate_contract_channel_readiness(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_contract_channel_readiness(p_company_id uuid, p_assignment_id uuid, p_channel text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_assignment public.tenant_contract_assignments%rowtype;
  v_offer_id uuid;
  v_channel text := lower(coalesce(p_channel,''));
  v_base jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_external_blockers jsonb := '[]'::jsonb;
  v_permission boolean := false;
  v_tenant_status text;
  v_external_ready boolean := true;
begin
  if coalesce(auth.role(),'')<>'service_role'
    and not public.gridex_can_read_company(p_company_id) then
    return jsonb_build_object(
      'ready',false,
      'channel',v_channel,
      'blockers',jsonb_build_array(jsonb_build_object(
        'code','contract_company_scope_denied',
        'message','Användaren saknar åtkomst till valt bolag.'
      )),
      'external_access_ready',false,
      'external_blockers','[]'::jsonb
    );
  end if;
  if v_channel not in ('internal','website','api') then
    return jsonb_build_object(
      'ready',false,
      'channel',v_channel,
      'blockers',jsonb_build_array(jsonb_build_object(
        'code','invalid_contract_channel',
        'message','Kanalen måste vara internal, website eller api.'
      )),
      'external_access_ready',false,
      'external_blockers','[]'::jsonb
    );
  end if;

  select *
  into v_assignment
  from public.tenant_contract_assignments assignment
  where assignment.id=p_assignment_id
    and assignment.company_id=p_company_id;
  if not found then
    return jsonb_build_object(
      'ready',false,
      'channel',v_channel,
      'blockers',jsonb_build_array(jsonb_build_object(
        'code','contract_assignment_not_found',
        'message','Avtalstilldelningen hittades inte för valt bolag.'
      )),
      'external_access_ready',false,
      'external_blockers','[]'::jsonb
    );
  end if;

  select offer.id
  into v_offer_id
  from public.contract_offers offer
  where offer.company_id=p_company_id
    and offer.contract_product_version_id=v_assignment.contract_product_version_id
    and offer.lifecycle_status in ('published','paused')
  order by offer.version_number desc,offer.updated_at desc nulls last,offer.id
  limit 1;
  if v_offer_id is null then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','contract_offer_not_channel_activatable',
      'message','En publicerad eller pausad canonical avtalsversion saknas.'
    ));
  else
    v_base := public.gridex_validate_contract_readiness_v2(
      p_company_id,
      v_offer_id,
      'activate_channel',
      v_channel
    );
    v_blockers := v_blockers || coalesce(v_base->'blockers','[]'::jsonb);
  end if;

  v_permission := public.gridex_contract_channel_permission_allowed(
    v_assignment,
    v_channel
  );
  if not v_permission then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code',v_channel||'_publication_permission_missing',
      'message',case v_channel
        when 'internal' then 'Avtalet saknar behörighet för intern försäljning.'
        when 'website' then 'Avtalet saknar behörighet för hemsidepublicering.'
        else 'Avtalet saknar behörighet för API-publicering.'
      end
    ));
  end if;

  select company.status
  into v_tenant_status
  from public.companies company
  where company.id=p_company_id;
  if v_tenant_status is distinct from 'active' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','tenant_not_operational',
      'message','Bolaget måste vara aktivt för att publicera avtal.',
      'current_status',v_tenant_status
    ));
  end if;

  if v_channel='api' and not exists(
    select 1
    from public.integration_api_clients client
    where client.company_id=p_company_id
      and client.status='active'
      and (client.expires_at is null or client.expires_at>now())
      and coalesce(client.scopes,'{}'::text[]) @> array['api_contracts.read']::text[]
  ) then
    v_external_ready := false;
    v_external_blockers := jsonb_build_array(jsonb_build_object(
      'code','api_scope_missing',
      'message','API-kanalen kan publiceras, men ingen aktiv API-klient har api_contracts.read.'
    ));
  end if;

  return jsonb_build_object(
    'ready',jsonb_array_length(v_blockers)=0,
    'channel',v_channel,
    'assignment_id',p_assignment_id,
    'contract_offer_id',v_offer_id,
    'publication_allowed',v_permission,
    'blockers',v_blockers,
    'external_access_ready',
      jsonb_array_length(v_blockers)=0 and v_external_ready,
    'external_blockers',v_external_blockers,
    'base_readiness',v_base,
    'evaluated_at',now()
  );
end
$$;

--
-- Name: FUNCTION gridex_validate_contract_channel_readiness(p_company_id uuid, p_assignment_id uuid, p_channel text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_validate_contract_channel_readiness(p_company_id uuid, p_assignment_id uuid, p_channel text) IS 'One channel-specific readiness result shared by server and publish RPC.';

--
-- Name: gridex_validate_contract_pricing_references(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_contract_pricing_references() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.price_plan_id is not null and not exists(
    select 1 from public.price_plans p where p.id=new.price_plan_id and p.company_id=new.company_id
  ) then raise exception 'Prisplanen tillhör inte bolaget.' using errcode='23514'; end if;

  if new.price_plan_version_id is not null and not exists(
    select 1 from public.price_plan_versions v
    where v.id=new.price_plan_version_id and v.company_id=new.company_id and v.price_plan_id=new.price_plan_id
  ) then raise exception 'Prisversionen tillhör inte bolaget eller vald prisplan.' using errcode='23514'; end if;

  if new.price_book_id is not null and not exists(
    select 1 from public.price_books b
    where b.id=new.price_book_id and b.company_id=new.company_id
      and (new.price_plan_id is null or b.price_plan_id=new.price_plan_id)
      and (new.price_plan_version_id is null or b.price_plan_version_id=new.price_plan_version_id)
  ) then raise exception 'Prislistan tillhör inte bolaget eller vald prisversion.' using errcode='23514'; end if;
  return new;
end $$;

--
-- Name: gridex_validate_contract_readiness(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_contract_readiness(p_company_id uuid, p_contract_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_status text;
  v_operation text;
  v_result jsonb;
  v_codes jsonb;
begin
  select lifecycle_status into v_status
  from public.contract_offers
  where id=p_contract_offer_id and company_id=p_company_id;
  v_operation:=case when v_status in ('published','paused') then 'activate_channel' else 'publish_version' end;
  v_result:=public.gridex_validate_contract_readiness_v2(
    p_company_id,p_contract_offer_id,v_operation,
    case when v_operation='activate_channel' then 'website' else null end
  );
  select coalesce(jsonb_agg(item->>'code'),'[]'::jsonb)
  into v_codes
  from jsonb_array_elements(coalesce(v_result->'blockers','[]'::jsonb)) item;
  return (v_result-'blockers')||jsonb_build_object(
    'blockers',v_codes,
    'blocker_details',coalesce(v_result->'blockers','[]'::jsonb)
  );
end $$;

--
-- Name: FUNCTION gridex_validate_contract_readiness(p_company_id uuid, p_contract_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_validate_contract_readiness(p_company_id uuid, p_contract_offer_id uuid) IS 'Compatibility wrapper for legacy callers. New code must use gridex_validate_contract_readiness_v2.';

--
-- Name: gridex_validate_contract_readiness_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_contract_readiness_v2(p_company_id uuid, p_contract_offer_id uuid, p_operation text, p_channel text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $_$
declare
  o public.contract_offers%rowtype;
  v_operation text:=lower(nullif(btrim(coalesce(p_operation,'')),''));
  v_channel text:=lower(nullif(btrim(coalesce(p_channel,'')),''));
  v_blockers jsonb:='[]'::jsonb;
  v_snapshot jsonb:='{}'::jsonb;
  v_components jsonb:='[]'::jsonb;
  v_price_areas text[]:='{}'::text[];
  v_area text;
  v_resolution text;
  v_expected_resolution text;
  v_energy_direction text;
  v_production_enabled boolean:=false;
  v_spot_weight numeric;
  v_portfolio_weight numeric;
  v_fixed_weight numeric;
  v_required_modules text[]:='{}'::text[];
  v_module text;
  v_template_version_id uuid;
  v_template_title text;
  v_template_body text;
  v_override_id uuid;
  v_override_mode text;
  v_override_title text;
  v_override_body text;
  v_source_title text;
  v_source_body text;
  v_rendered_title text;
  v_rendered_body text;
  v_unresolved text[]:='{}'::text[];
  v_profile jsonb;
  v_company jsonb;
  v_can_execute boolean;
begin
  if v_operation is null or v_operation not in (
    'publish_version','activate_channel','resume_channel','close','archive','delete'
  ) then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'invalid_readiness_operation','operation',
        'Okänd readinessoperation.',to_jsonb(v_operation)
      )
    );
    return jsonb_build_object(
      'ok',false,'status','blocked','can_execute',false,'can_publish',false,
      'operation',v_operation,'channel',v_channel,'code','contract_not_ready',
      'blockers',v_blockers,'evaluated_at',now()
    );
  end if;

  if v_operation in ('activate_channel','resume_channel')
     and (v_channel is null or v_channel not in ('internal','website','api','partner','phone')) then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'invalid_contract_channel','channel',
        'Kanalen måste vara internal, website, api, partner eller phone.',
        to_jsonb(v_channel)
      )
    );
  end if;

  select * into o
  from public.contract_offers co
  where co.id=p_contract_offer_id and co.company_id=p_company_id;

  if not found then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',
        to_jsonb(p_contract_offer_id),'contract_offer',p_contract_offer_id
      )
    );
    return jsonb_build_object(
      'ok',false,'status','blocked','can_execute',false,'can_publish',false,
      'operation',v_operation,'channel',v_channel,'code','contract_not_ready',
      'blockers',v_blockers,'evaluated_at',now()
    );
  end if;

  if v_operation='publish_version' and o.lifecycle_status not in ('draft','ready','paused') then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'lifecycle_status_not_publishable','lifecycle_status',
        'Endast draft, ready eller paused kan publiceras som en immutable avtalsversion.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      )
    );
  elsif v_operation in ('activate_channel','resume_channel')
        and o.lifecycle_status not in ('published','paused') then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'lifecycle_status_not_channel_activatable','lifecycle_status',
        'Kanalen kan endast aktiveras för en publicerad eller pausad avtalsversion.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      )
    );
  elsif v_operation='close' and o.lifecycle_status not in ('draft','ready','published','paused') then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        case
          when o.lifecycle_status='closed' then 'contract_already_closed'
          when o.lifecycle_status='archived' then 'contract_already_archived'
          else 'lifecycle_status_not_closeable'
        end,
        'lifecycle_status','Endast draft, ready, published eller paused kan stängas.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      )
    );
  elsif v_operation='archive' and o.lifecycle_status not in ('draft','ready','paused','expired','closed','superseded') then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'lifecycle_status_not_archivable','lifecycle_status',
        'Publicerade avtal måste först pausas eller stängas innan arkivering.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      )
    );
  elsif v_operation='delete' and o.lifecycle_status not in ('draft','ready') then
    v_blockers:=v_blockers||jsonb_build_array(
      public.gridex_contract_readiness_blocker_v2(
        'permanent_delete_requires_draft','lifecycle_status',
        'Permanent radering är endast tillåten för oanvända draft- eller ready-versioner.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      )
    );
  end if;

  -- Close/archive/delete have their own dependency graph and must not be blocked
  -- by publication-only commercial requirements.
  if v_operation not in ('publish_version','activate_channel','resume_channel') then
    v_can_execute:=jsonb_array_length(v_blockers)=0;
    return jsonb_build_object(
      'ok',v_can_execute,
      'status',case when v_can_execute then 'ready' else 'blocked' end,
      'can_execute',v_can_execute,'can_publish',v_can_execute,
      'operation',v_operation,'channel',v_channel,
      'code',case when v_can_execute then 'contract_ready' else 'contract_not_ready' end,
      'blockers',v_blockers,'lifecycle_status',o.lifecycle_status,
      'evaluated_at',now()
    );
  end if;

  v_snapshot:=coalesce(o.commercial_snapshot,'{}'::jsonb);
  v_components:=case
    when jsonb_typeof(v_snapshot->'base_components')='array' then v_snapshot->'base_components'
    when jsonb_typeof(v_snapshot->'pricing_snapshot'->'base_components')='array'
      then v_snapshot->'pricing_snapshot'->'base_components'
    else '[]'::jsonb
  end;
  v_production_enabled:=lower(coalesce(v_snapshot#>>'{production,enabled}','false'))='true';
  v_energy_direction:=lower(nullif(btrim(v_snapshot->>'energy_direction'),''));
  if v_energy_direction is null then
    -- Compatibility for immutable snapshots created before direction became
    -- explicit. All newly written snapshots carry this field.
    v_energy_direction:=case when v_production_enabled then 'production' else 'consumption' end;
  end if;
  v_resolution:=lower(nullif(btrim(coalesce(
    v_snapshot->>'interval_resolution',
    v_snapshot#>>'{pricing,interval_resolution}',
    v_snapshot->>'resolution'
  )),''));
  v_expected_resolution:=case
    when o.contract_type in ('variable_monthly','spot') then 'monthly'
    when o.contract_type='variable_hourly' then 'hourly'
    when o.contract_type='variable_quarterly' then 'quarterly'
    when o.contract_type='fixed' then 'fixed'
    when o.contract_type='portfolio' then 'portfolio'
    else null
  end;

  select coalesce(array_agg(upper(btrim(area)) order by upper(btrim(area))),'{}'::text[])
  into v_price_areas
  from (
    select value as area
    from jsonb_array_elements_text(
      case when jsonb_typeof(v_snapshot->'price_areas')='array'
        then v_snapshot->'price_areas' else '[]'::jsonb end
    )
    where nullif(btrim(value),'') is not null
    union all
    select unnest(cpv.price_areas)
    from public.contract_product_versions cpv
    where cpv.id=o.contract_product_version_id
      and jsonb_array_length(
        case when jsonb_typeof(v_snapshot->'price_areas')='array'
          then v_snapshot->'price_areas' else '[]'::jsonb end
      )=0
  ) areas;

  if nullif(btrim(o.name),'') is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'name_missing','name','Internt avtalsnamn saknas.',null,'contract_offer',o.id));
  end if;
  if o.contract_product_id is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'canonical_product_missing','contract_product_id','Canonical avtalsprodukt saknas.',null,'contract_offer',o.id));
  end if;
  if o.contract_product_version_id is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'canonical_product_version_missing','contract_product_version_id','Canonical immutable avtalsversion saknas.',null,'contract_offer',o.id));
  elsif not exists(
    select 1 from public.contract_product_versions cpv
    where cpv.id=o.contract_product_version_id
      and cpv.contract_product_id=o.contract_product_id
  ) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'canonical_product_version_mismatch','contract_product_version_id','Avtalsversionen tillhör inte vald canonical produkt.',to_jsonb(o.contract_product_version_id),'contract_product_version',o.contract_product_version_id));
  end if;

  if o.contract_product_version_id is not null and not exists(
    select 1 from public.tenant_contract_assignments ta
    where ta.company_id=p_company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status in ('active','paused')
  ) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'tenant_assignment_missing','tenant_contract_assignment_id','Aktiv eller pausad tenanttilldelning till exakt avtalsversion saknas.',null,'contract_product_version',o.contract_product_version_id));
  end if;

  if o.contract_product_version_id is not null and not exists(
    select 1 from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    where ta.company_id=p_company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ch.channel='internal'
      and ch.status in ('active','paused')
  ) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'internal_channel_missing','internal_channel','Intern försäljningskanal saknas för tenanttilldelningen.',null,'contract_product_version',o.contract_product_version_id));
  end if;

  if o.price_plan_id is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('price_plan_missing','price_plan_id','Prisplan saknas.',null,'contract_offer',o.id));
  end if;
  if o.price_plan_version_id is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('price_plan_version_missing','price_plan_version_id','Låst prisversion saknas.',null,'contract_offer',o.id));
  end if;
  if o.price_book_id is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('price_book_missing','price_book_id','Prisbok eller prissnapshot saknas.',null,'contract_offer',o.id));
  end if;
  if o.invoice_fee_sek is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('invoice_fee_missing','invoice_fee_sek','Fakturaavgiften måste vara explicit angiven, även när den är 0.',null,'contract_offer',o.id));
  elsif o.invoice_fee_sek<0 then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('invoice_fee_invalid','invoice_fee_sek','Fakturaavgiften får inte vara negativ.',to_jsonb(o.invoice_fee_sek),'contract_offer',o.id));
  end if;
  if o.vat_rate is null or o.vat_rate<0 or o.vat_rate>1 then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('vat_rate_invalid','vat_rate','Moms måste ligga mellan 0 och 1.',to_jsonb(o.vat_rate),'contract_offer',o.id));
  end if;

  if cardinality(v_price_areas)=0 then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('price_areas_missing','commercial_snapshot.price_areas','Minst ett tillåtet elområde måste anges.',null,'contract_offer',o.id));
  elsif cardinality(v_price_areas)<>(select count(distinct area) from unnest(v_price_areas) area) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('duplicate_price_areas','commercial_snapshot.price_areas','Elområdeslistan innehåller dubbletter.',to_jsonb(v_price_areas),'contract_offer',o.id));
  end if;
  if exists(select 1 from unnest(v_price_areas) area where area not in ('SE1','SE2','SE3','SE4')) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('price_area_invalid','commercial_snapshot.price_areas','Elområdet måste vara SE1, SE2, SE3 eller SE4.',to_jsonb(v_price_areas),'contract_offer',o.id));
  end if;

  if o.contract_type='fixed' then
    foreach v_area in array v_price_areas loop
      if not exists(
        select 1
        from jsonb_array_elements(v_components) component
        where lower(coalesce(component->>'source_type',''))='fixed'
          and upper(coalesce(component->>'price_area',''))=v_area
          and coalesce(component->>'fixed_price_sek_per_kwh','') ~ '^[0-9]+([.][0-9]+)?$'
          and (component->>'fixed_price_sek_per_kwh')::numeric>0
      ) then
        v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'fixed_price_area_missing','commercial_snapshot.base_components.'||v_area,
          'Fastpris saknas eller är ogiltigt för '||v_area||'.',null,
          'contract_product_version',o.contract_product_version_id,
          jsonb_build_object('price_area',v_area)
        ));
      end if;
    end loop;
  end if;

  if v_resolution is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('resolution_missing','commercial_snapshot.interval_resolution','Prisupplösning saknas i den immutable kommersiella snapshoten.',null,'contract_offer',o.id));
  elsif v_expected_resolution is not null and v_resolution<>v_expected_resolution then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('resolution_mismatch','commercial_snapshot.interval_resolution','Prisupplösningen matchar inte vald avtalsmodell.',to_jsonb(v_resolution),'contract_offer',o.id,jsonb_build_object('expected',v_expected_resolution)));
  elsif o.contract_type='mixed' and v_resolution not in ('monthly','hourly','quarterly') then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('resolution_mismatch','commercial_snapshot.interval_resolution','Mixavtal måste använda monthly, hourly eller quarterly.',to_jsonb(v_resolution),'contract_offer',o.id));
  end if;

  if v_energy_direction not in ('consumption','production') then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'energy_direction_invalid','commercial_snapshot.energy_direction',
      'Avtalsriktningen måste vara consumption eller production.',to_jsonb(v_energy_direction),
      'contract_offer',o.id
    ));
  end if;
  if v_production_enabled and v_energy_direction<>'production' then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'production_direction_mismatch','commercial_snapshot.energy_direction',
      'Produktionsersättning är aktiverad men avtalsriktningen är inte production.',to_jsonb(v_energy_direction),
      'contract_offer',o.id
    ));
  elsif not v_production_enabled and v_energy_direction='production' then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
      'production_configuration_missing','commercial_snapshot.production.enabled',
      'Avtalsriktningen är production men produktionskonfigurationen är inte aktiverad.',to_jsonb(false),
      'contract_offer',o.id
    ));
  end if;
  if v_production_enabled then
    if nullif(v_snapshot#>>'{production,settlement_mode}','') is null then
      v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('production_settlement_mode_missing','commercial_snapshot.production.settlement_mode','Produktionsavtalet saknar avräkningsmodell.',null,'contract_offer',o.id));
    end if;
    if coalesce(
      case when coalesce(v_snapshot#>>'{production,compensation_ore_per_kwh}','') ~ '^[0-9]+([.][0-9]+)?$'
        then (v_snapshot#>>'{production,compensation_ore_per_kwh}')::numeric end,
      0
    )<=0 then
      v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('production_compensation_missing','commercial_snapshot.production.compensation_ore_per_kwh','Produktionsavtalet saknar en positiv ersättningsnivå.',null,'contract_offer',o.id));
    end if;
  end if;

  if o.valid_from is not null and o.valid_to is not null and o.valid_to<o.valid_from then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('invalid_validity_period','valid_to','Giltig till ligger före giltig från.',to_jsonb(o.valid_to),'contract_offer',o.id));
  end if;
  if o.max_customers is not null and o.max_customers<=0 then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('invalid_max_customers','max_customers','Max antal kunder måste vara större än 0.',to_jsonb(o.max_customers),'contract_offer',o.id));
  end if;
  if coalesce(o.automatic_renewal,false) and o.automatic_renewal_term_months is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('automatic_renewal_term_missing','automatic_renewal_term_months','Automatisk förlängning saknar förlängningsperiod.',null,'contract_offer',o.id));
  end if;
  if o.discount_value is not null and o.discount_months is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('discount_months_missing','discount_months','Rabattvärde finns men rabattperiod saknas.',null,'contract_offer',o.id));
  end if;
  if o.contract_type in ('portfolio','mixed') and nullif(v_snapshot#>>'{portfolio_method,portfolio_id}','') is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('portfolio_id_missing','commercial_snapshot.portfolio_method.portfolio_id','Portfölj- eller mixavtal saknar portfölj-ID.',null,'contract_offer',o.id));
  end if;
  if o.contract_type in ('portfolio','mixed') then
    v_spot_weight:=case
      when coalesce(v_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
        then (v_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}')::numeric
      else null
    end;
    v_portfolio_weight:=case
      when coalesce(v_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
        then (v_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}')::numeric
      else null
    end;
    v_fixed_weight:=case
      when coalesce(v_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
        then (v_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}')::numeric
      else null
    end;
    if v_spot_weight is null or v_portfolio_weight is null or v_fixed_weight is null
       or v_spot_weight<0 or v_portfolio_weight<0 or v_fixed_weight<0
       or v_spot_weight+v_portfolio_weight+v_fixed_weight<>100 then
      v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'pricing_weights_invalid','commercial_snapshot.portfolio_method.mix_shares',
        'Spot-, portfölj- och fastvikter måste vara numeriska, icke-negativa och summera till 100 procent.',
        jsonb_build_object(
          'spot_weight_percent',v_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}',
          'portfolio_weight_percent',v_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}',
          'fixed_weight_percent',v_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}'
        ),'contract_offer',o.id
      ));
    end if;
  end if;

  if not exists(
    select 1 from public.platform_go_live_readiness_v readiness
    where readiness.company_id=p_company_id
      and readiness.has_actor_setting and readiness.has_brp
      and readiness.has_prodat_route and readiness.has_utilts_route
      and readiness.has_sender_identity
  ) then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('tenant_go_live_not_ready','company_id','Tenantens produktionsrouting, BRP eller avsändaridentitet är inte komplett.',to_jsonb(p_company_id),'company',p_company_id));
  end if;

  select to_jsonb(lp) into v_profile
  from public.tenant_legal_profiles lp
  where lp.company_id=p_company_id
    and lp.completeness_status in ('complete','verified')
    and not coalesce(lp.review_required,false);
  if v_profile is null then
    v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2('tenant_legal_profile_not_ready','tenant_legal_profile','Tenantens juridiska profil är inte komplett och granskad.',null,'company',p_company_id));
  end if;
  select to_jsonb(company_row) into v_company
  from public.companies company_row
  where company_row.id=p_company_id;

  select cpv.required_legal_modules
  into v_required_modules
  from public.contract_product_versions cpv
  where cpv.id=o.contract_product_version_id
    and cpv.contract_product_id=o.contract_product_id;
  if coalesce(cardinality(v_required_modules),0)=0 then
    v_required_modules:=public.gridex_required_legal_modules(
      o.customer_type,o.contract_type,'website',coalesce(o.automatic_renewal,false),
      coalesce(o.power_of_attorney_required,true),v_production_enabled
    );
  end if;

  if v_operation='publish_version' then
    -- Preview the exact canonical legal source selection used by
    -- gridex_materialize_legal_bundle_version. No legacy legal_bundle row is
    -- required for a draft.
    foreach v_module in array coalesce(v_required_modules,'{}'::text[]) loop
      v_template_version_id:=null;
      v_template_title:=null;
      v_template_body:=null;
      v_override_id:=null;
      v_override_mode:=null;
      v_override_title:=null;
      v_override_body:=null;
      v_source_title:=null;
      v_source_body:=null;

      select ltv.id,ltv.title,ltv.body
      into v_template_version_id,v_template_title,v_template_body
      from public.legal_templates lt
      join public.legal_template_versions ltv on ltv.legal_template_id=lt.id
      where lt.module_key=v_module
        and lt.status='active'
        and ltv.status='published'
        and ltv.locked_at is not null
      order by ltv.version_number desc,ltv.published_at desc nulls last
      limit 1;

      select legal_override.id,legal_override.legal_mode,legal_override.title,legal_override.body
      into v_override_id,v_override_mode,v_override_title,v_override_body
      from public.tenant_legal_overrides legal_override
      where legal_override.company_id=p_company_id
        and legal_override.module_key=v_module
        and legal_override.status in ('approved','published')
        and legal_override.locked_at is not null
      order by legal_override.reviewed_at desc nulls last,legal_override.created_at desc
      limit 1;

      if v_override_id is not null and v_override_mode='replacement' then
        v_source_title:=v_override_title;
        v_source_body:=v_override_body;
      elsif v_template_version_id is not null then
        v_source_title:=v_template_title;
        v_source_body:=v_template_body;
        if v_override_id is not null and v_override_mode='addendum' then
          v_source_title:=v_source_title||' – tenanttillägg';
          v_source_body:=v_source_body||E'\n\nTenanttillägg\n'||v_override_body;
        end if;
      else
        v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
          'required_legal_module_missing','legal_sources.'||v_module,
          'Obligatorisk juridikmodul saknar en publicerad låst källa: '||v_module||'.',null,
          'contract_product_version',o.contract_product_version_id,jsonb_build_object('module_key',v_module)
        ));
        continue;
      end if;

      if v_profile is not null then
        v_rendered_title:=public.gridex_render_legal_document(v_source_title,v_profile,v_company);
        v_rendered_body:=public.gridex_render_legal_document(v_source_body,v_profile,v_company);
        select coalesce(array_agg(distinct match_value[1] order by match_value[1]),'{}'::text[])
        into v_unresolved
        from regexp_matches(
          v_rendered_title||E'\n'||v_rendered_body,
          '\{\{[[:space:]]*([a-zA-Z0-9_.-]+)[[:space:]]*\}\}',
          'g'
        ) as matches(match_value);
        if cardinality(v_unresolved)>0 then
          v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'unresolved_legal_variables','legal_sources.'||v_module,
            'Juridikmodulen innehåller olösta mallvariabler.',to_jsonb(v_unresolved),
            'contract_product_version',o.contract_product_version_id,jsonb_build_object('module_key',v_module)
          ));
        end if;
      end if;
    end loop;
  else
    -- Channel activation is bound to the immutable bundle created by internal
    -- publication. Preview and commit therefore inspect the exact same locked
    -- legal bundle version.
    if o.legal_bundle_version_id is null then
      v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'legal_bundle_version_missing','legal_bundle_version_id',
        'Låst juridikversion saknas. Publicera avtalsversionen internt först.',null,
        'contract_offer',o.id
      ));
    elsif not exists(
      select 1 from public.legal_bundle_versions lbv
      where lbv.id=o.legal_bundle_version_id
        and lbv.company_id=p_company_id
        and lbv.contract_product_version_id=o.contract_product_version_id
        and lbv.status='published'
        and lbv.locked_at is not null
        and coalesce(cardinality(lbv.unresolved_variables),0)=0
    ) then
      v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'legal_bundle_version_not_ready','legal_bundle_version_id',
        'Juridikversionen är inte publicerad, låst och fri från olösta variabler.',
        to_jsonb(o.legal_bundle_version_id),'legal_bundle_version',o.legal_bundle_version_id
      ));
    else
      foreach v_module in array coalesce(v_required_modules,'{}'::text[]) loop
        if not exists(
          select 1 from public.legal_bundle_version_documents document
          where document.legal_bundle_version_id=o.legal_bundle_version_id
            and document.module_key=v_module
            and coalesce(cardinality(document.unresolved_variables),0)=0
        ) then
          v_blockers:=v_blockers||jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'required_legal_module_missing','legal_bundle_version.'||v_module,
            'Den låsta juridikversionen saknar obligatorisk modul: '||v_module||'.',null,
            'legal_bundle_version',o.legal_bundle_version_id,jsonb_build_object('module_key',v_module)
          ));
        end if;
      end loop;
    end if;
  end if;

  v_can_execute:=jsonb_array_length(v_blockers)=0;
  return jsonb_build_object(
    'ok',v_can_execute,
    'status',case when v_can_execute then 'ready' else 'blocked' end,
    'can_execute',v_can_execute,
    'can_publish',v_can_execute,
    'operation',v_operation,
    'channel',v_channel,
    'code',case when v_can_execute then 'contract_ready' else 'contract_not_ready' end,
    'blockers',v_blockers,
    'lifecycle_status',o.lifecycle_status,
    'resolution',v_resolution,
    'expected_resolution',v_expected_resolution,
    'energy_direction',v_energy_direction,
    'required_legal_modules',to_jsonb(v_required_modules),
    'evaluated_at',now()
  );
end $_$;

--
-- Name: FUNCTION gridex_validate_contract_readiness_v2(p_company_id uuid, p_contract_offer_id uuid, p_operation text, p_channel text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_validate_contract_readiness_v2(p_company_id uuid, p_contract_offer_id uuid, p_operation text, p_channel text) IS 'Operation-specific, service-only contract readiness. Returns one structured blockers array for publish_version, activate_channel, resume_channel, close, archive and delete.';

--
-- Name: gridex_validate_customer_match_review_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_customer_match_review_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (
    select 1
      from unnest(coalesce(new.candidate_customer_ids, '{}'::uuid[])) candidate_id
      left join public.customers c
        on c.id = candidate_id and c.company_id = new.company_id
     where c.id is null
  ) then
    raise exception 'candidate_customer_outside_review_tenant' using errcode = '22023';
  end if;

  if new.status = 'resolved' then
    if new.resolved_by is null or new.resolution_type not in ('link_customer','create_separate') then
      raise exception 'complete_match_resolution_evidence_required' using errcode = '22023';
    end if;
    if new.resolution_type = 'link_customer' and (
      new.resolved_customer_id is null
      or not (new.resolved_customer_id = any(new.candidate_customer_ids))
      or not exists (
        select 1 from public.customers c
         where c.id = new.resolved_customer_id and c.company_id = new.company_id
      )
    ) then
      raise exception 'resolved_customer_not_in_tenant_candidate_set' using errcode = '22023';
    end if;
    if new.resolution_type = 'create_separate' and new.resolved_customer_id is not null then
      raise exception 'create_separate_resolution_cannot_link_customer' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_validate_ediel_message_contract(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_ediel_message_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_canonical boolean;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
  if tg_op='UPDATE' then
    if coalesce(old.execution_context_snapshot ? 'receivedProdatContext',false) then
      if new.raw_payload is distinct from old.raw_payload or new.immutable_payload_hash is distinct from old.immutable_payload_hash then
        raise exception 'immutable_ediel_payload_cannot_change' using errcode='23514';
      end if;
      if (new.execution_context_snapshot->'receivedProdatContext') is distinct from (old.execution_context_snapshot->'receivedProdatContext') then
        raise exception 'immutable_ediel_received_context_cannot_change' using errcode='23514';
      end if;
      if new.message_received_at is distinct from old.message_received_at then
        raise exception 'immutable_ediel_receipt_time_cannot_change' using errcode='23514';
      end if;
      if new.id is distinct from old.id or new.direction is distinct from old.direction
         or new.message_standard is distinct from old.message_standard or new.message_family is distinct from old.message_family
         or new.message_code is distinct from old.message_code then
        raise exception 'immutable_ediel_received_context_cannot_change' using errcode='23514';
      end if;
    elsif coalesce(new.execution_context_snapshot ? 'receivedProdatContext',false) then
      raise exception 'received_ediel_context_cannot_be_backfilled' using errcode='23514';
    end if;
  end if;
  v_canonical := upper(coalesce(new.message_family,'')) in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR');
  if v_canonical then
    if new.company_id is null then
      if gridex_unattributed_intake.is_birth_v1(new,tg_op='INSERT') is not true then
        raise exception 'canonical_ediel_company_required' using errcode='23502';
      end if;
    end if;
    if nullif(btrim(coalesce(new.environment,'')),'') is null then raise exception 'canonical_ediel_environment_required' using errcode='23502'; end if;
    if new.direction='outbound' then
      if new.canonical_rule_pack_id is null then
        perform public.gridex_require_outbound_reply_basis_v1(new);
      end if;
      if new.communication_route_id is null then raise exception 'canonical_ediel_route_required' using errcode='23502'; end if;
      if new.route_profile_id is null and nullif(new.execution_context_snapshot->>'routeProfileId','') is null then raise exception 'canonical_ediel_route_profile_required' using errcode='23502'; end if;
      if nullif(btrim(coalesce(new.application_reference,'')),'') is null then raise exception 'canonical_ediel_application_reference_required' using errcode='23502'; end if;
      if nullif(btrim(coalesce(new.source_operation_id,new.execution_context_snapshot->>'sourceOperationId','')),'') is null then raise exception 'canonical_ediel_source_operation_required' using errcode='23502'; end if;
      if new.raw_payload is not null and nullif(btrim(new.raw_payload),'') is not null then
        new.immutable_payload_hash := encode(digest(convert_to(new.raw_payload,'UTF8'),'sha256'),'hex');
        new.immutable_rendered_at := coalesce(new.immutable_rendered_at,now());
      end if;
    end if;
  end if;
  -- Seal only newly received EDIFACT PRODAT source bytes; never backfill UPDATEs.
  -- Null is no source. Empty text is a source. Ignore a caller-supplied hash.
  if tg_op='INSERT' and new.direction='inbound'
     and upper(coalesce(new.message_family,''))='PRODAT'
     and new.message_standard='edifact' then
    new.immutable_payload_hash := case when new.raw_payload is null then null
      else encode(digest(convert_to(new.raw_payload,'UTF8'),'sha256'),'hex') end;
  end if;
  if tg_op='UPDATE' and old.immutable_payload_hash is not null then
    if new.raw_payload is distinct from old.raw_payload or new.immutable_payload_hash is distinct from old.immutable_payload_hash then
      raise exception 'immutable_ediel_payload_cannot_change' using errcode='23514';
    end if;
  end if;
  if tg_op='INSERT' then
    -- Client data never owns this reserved namespace, including ineligible rows.
    if jsonb_typeof(new.execution_context_snapshot) in ('object','array') then
      new.execution_context_snapshot := new.execution_context_snapshot - 'receivedProdatContext';
    end if;
    if new.direction='inbound' and upper(coalesce(new.message_family,''))='PRODAT'
       and new.message_standard='edifact' and new.raw_payload is not null
       and new.id is not null and new.company_id is not null
       and nullif(btrim(new.environment),'') is not null and nullif(btrim(new.message_code),'') is not null
       and new.message_received_at is not null and new.immutable_payload_hash is not null then
      new.execution_context_snapshot := (case when jsonb_typeof(new.execution_context_snapshot)='object'
        then new.execution_context_snapshot else '{}'::jsonb end) || jsonb_build_object('receivedProdatContext',jsonb_build_object(
          'version',1,'contextOrigin','database_insert','sourceMessageId',new.id,'companyId',new.company_id,
          'environment',new.environment,'messageCode',new.message_code,'payloadHash',new.immutable_payload_hash,
          'sourceReceivedAt',new.message_received_at,'capturedAt',clock_timestamp()));
    end if;
  end if;
  return new;
end $$;

--
-- Name: gridex_validate_ediel_outbox_contract(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_ediel_outbox_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_message public.ediel_messages%rowtype;
begin
  select * into v_message from public.ediel_messages where id=new.ediel_message_id for share;
  if not found then raise exception 'ediel_outbox_message_missing' using errcode='23503'; end if;
  if v_message.company_id is null or new.company_id is null or v_message.company_id<>new.company_id then
    raise exception 'ediel_outbox_tenant_mismatch' using errcode='23514';
  end if;
  if v_message.immutable_payload_hash is null then raise exception 'ediel_outbox_immutable_payload_hash_required' using errcode='23502'; end if;
  new.immutable_payload_hash := v_message.immutable_payload_hash;
  return new;
end $$;

--
-- Name: gridex_validate_ediel_outbox_tenant_and_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_ediel_outbox_tenant_and_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m public.ediel_messages%rowtype;
begin
  select * into m from public.ediel_messages where id=new.ediel_message_id;
  if not found then raise exception 'ediel_outbox_message_missing' using errcode='23503'; end if;
  if new.company_id is null or m.company_id is null or new.company_id<>m.company_id then
    raise exception 'ediel_outbox_message_tenant_mismatch' using errcode='23514';
  end if;
  if m.direction<>'outbound' then raise exception 'ediel_outbox_requires_outbound_message' using errcode='23514'; end if;
  if m.message_family in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR')
     and (m.rule_profile_version_id is null or nullif(m.rule_pack_checksum,'') is null)
     and not (m.canonical_rule_pack_id is null and m.rule_profile_version_id is null
       and (m.message_family='CONTRL'
        or (m.message_family='APERAK' and m.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId'))) then
    raise exception 'ediel_outbox_rule_pack_snapshot_missing' using errcode='23514';
  end if;
  new.rule_profile_key:=m.rule_profile_key;
  new.rule_profile_version_id:=m.rule_profile_version_id;
  new.rule_profile_version:=m.rule_profile_version;
  new.rule_pack_checksum:=m.rule_pack_checksum;
  new.rule_pack_snapshot:=m.rule_pack_snapshot;
  return new;
end; $$;

--
-- Name: gridex_validate_outbound_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_outbound_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_facility text;
begin
  -- Only guard the customer_masterdata (PRODAT Z01) business process in
  -- active pre-send states. Other processes and terminal states pass through.
  if coalesce(new.business_process, '') <> 'customer_masterdata'
     and coalesce(new.request_type, '') not in ('customer_masterdata', 'customer_masterdata_request') then
    return new;
  end if;
  if coalesce(new.status, '') not in ('queued', 'prepared', 'ready') then
    return new;
  end if;
  if new.metering_point_id is not null then
    return new;
  end if;

  v_facility := coalesce(
    new.payload #>> '{site,facility_id}',
    new.payload #>> '{site,normalized_facility_id}',
    new.payload #>> '{metering_point,meter_point_id}',
    new.payload #>> '{metering_point,ediel_reference}',
    new.payload #>> '{metering_point,site_facility_id}',
    new.payload ->> 'facility_id'
  );
  if v_facility is not null and length(trim(v_facility)) > 0 then
    return new;
  end if;

  -- Demote instead of raising: the row is preserved for audit but can never
  -- claim an active queued/prepared state without facility identity.
  new.status := 'failed';
  new.failed_at := coalesce(new.failed_at, now());
  new.failure_reason := coalesce(
    nullif(new.failure_reason, ''),
    'Blockerad av gridex_validate_outbound_payload: anläggnings-ID/mätpunkts-ID saknas för customer_masterdata.'
  );
  new.blocking_reasons := coalesce(new.blocking_reasons, '[]'::jsonb) || jsonb_build_array(
    jsonb_build_object(
      'code', 'facility_or_metering_point_missing',
      'message', 'Anläggnings-ID/mätpunkts-ID saknas. Databas-guarden blockerade aktiv status.',
      'source', 'gridex_validate_outbound_payload'
    )
  );
  new.required_admin_actions := (
    select coalesce(jsonb_agg(distinct value), '[]'::jsonb)
    from jsonb_array_elements_text(
      coalesce(new.required_admin_actions, '[]'::jsonb) || '["request_facility_information"]'::jsonb
    ) as value
  );
  return new;
end;
$$;

--
-- Name: gridex_validate_portfolio_monthly_price_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_portfolio_monthly_price_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_company uuid; v_plan uuid;
begin
  if new.price_plan_version_id is null then return new; end if;
  select company_id,price_plan_id into v_company,v_plan
  from public.price_plan_versions where id=new.price_plan_version_id;
  if v_company is null then raise exception 'portfolio_price_plan_version_missing'; end if;
  if new.company_id<>v_company then raise exception 'portfolio_price_tenant_mismatch'; end if;
  if new.price_plan_id is null then new.price_plan_id:=v_plan; end if;
  if new.price_plan_id<>v_plan then raise exception 'portfolio_price_plan_mismatch'; end if;
  return new;
end $$;

--
-- Name: gridex_validate_price_option_publication_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_price_option_publication_v1(p_company_id uuid, p_publication_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with publication as (
  select
    version_row.*,
    assignment.company_id
  from public.contract_publication_versions version_row
  join public.contract_publications publication_root
    on publication_root.id=version_row.contract_publication_id
  join public.tenant_contract_assignments assignment
    on assignment.id=publication_root.assignment_id
  where version_row.id=p_publication_version_id
    and assignment.company_id=p_company_id
),
options as (
  select option_row.*
  from public.contract_price_options option_row
  join publication
    on publication.id=option_row.contract_publication_version_id
  where option_row.company_id=p_company_id
),
diagnostics as (
  select 'price_option_reference_missing' code,
    null::text price_option_reference,null::text price_area
  where not exists(select 1 from options where status='active')
  union all
  select 'price_option_default_missing',null,null
  where (select count(*) from options
    where status='active' and is_default is true)=0
  union all
  select 'price_option_default_duplicate',null,null
  where (select count(*) from options
    where status='active' and is_default is true)>1
  union all
  select 'price_option_selection_policy_inconsistent',null,null
  where (select count(*) from options
    where status='active' and selection_required is null)>0
     or (select count(distinct selection_required) from options
       where status='active')>1
  union all
  select 'price_option_customer_type_invalid',
    option_row.option_reference,null
  from options option_row
  join publication on true
  where option_row.customer_type is null
     or not (
       option_row.customer_type='both'
       or publication.customer_type='both'
       or option_row.customer_type=publication.customer_type
     )
  union all
  select 'price_option_product_plan_mismatch',
    option_row.option_reference,null
  from options option_row
  join publication on true
  where option_row.contract_product_version_id
      <>publication.contract_product_version_id
     or option_row.price_plan_version_id
      is distinct from publication.price_plan_version_id
  union all
  select case
      when option_row.status='paused' then 'price_option_paused'
      when option_row.status<>'active' then 'price_option_inactive'
      when option_row.valid_from is not null
        and option_row.valid_from>
          (now() at time zone 'Europe/Stockholm')::date
        then 'price_option_not_yet_valid'
      else 'price_option_expired'
    end,
    option_row.option_reference,null
  from options option_row
  where option_row.status<>'active'
     or (
       option_row.valid_from is not null
       and option_row.valid_from>
         (now() at time zone 'Europe/Stockholm')::date
     )
     or (
       option_row.valid_to is not null
       and option_row.valid_to<
         (now() at time zone 'Europe/Stockholm')::date
     )
  union all
  select 'fixed_price_area_missing',
    option_row.option_reference,required_area.price_area
  from options option_row
  cross join (
    values ('SE1'::text),('SE2'),('SE3'),('SE4')
  ) required_area(price_area)
  where option_row.status='active'
    and option_row.contract_type='fixed'
    and not exists(
      select 1
      from public.contract_price_option_area_prices area_row
      where area_row.company_id=p_company_id
        and area_row.contract_price_option_id=option_row.id
        and area_row.price_area=required_area.price_area
        and area_row.status='active'
        and (
          area_row.valid_from is null
          or area_row.valid_from<=
            (now() at time zone 'Europe/Stockholm')::date
        )
        and (
          area_row.valid_to is null
          or area_row.valid_to>=
            (now() at time zone 'Europe/Stockholm')::date
        )
        and area_row.unit in ('ore_per_kwh','sek_per_kwh')
    )
)
select coalesce(
  jsonb_agg(
    jsonb_strip_nulls(jsonb_build_object(
      'code',code,
      'offer_reference',(select offer_reference from publication),
      'price_option_reference',price_option_reference,
      'price_area',price_area
    ))
    order by code,price_option_reference,price_area
  ),
  '[]'::jsonb
)
from diagnostics
$$;

--
-- Name: gridex_validate_publication_graph_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_publication_graph_v1(p_publication_version_id uuid) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
with publication as (
  select pv.*,p.status publication_status,p.channel publication_channel,
    a.company_id,a.status assignment_status,a.website_publication_allowed,
    a.api_publication_allowed,c.status channel_status,
    public.gridex_supported_price_areas_v1(
      pv.contract_product_version_id
    ) supported_areas,
    (
      cardinality(coalesce(product_version.price_areas,'{}'::text[]))=0
      or (
        not exists(
          select 1
          from unnest(coalesce(product_version.price_areas,'{}'::text[])) area
          where upper(btrim(area)) not in ('SE1','SE2','SE3','SE4')
        )
        and cardinality(coalesce(product_version.price_areas,'{}'::text[]))=(
          select count(distinct upper(btrim(area)))
          from unnest(coalesce(product_version.price_areas,'{}'::text[])) area
        )
      )
    ) supported_areas_valid,
    product_version.contract_type,
    public.gridex_invoice_fee_ready_v1(
      case when coalesce(
        pv.publication_snapshot->'commercial_snapshot'->>'invoice_fee_sek','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (pv.publication_snapshot->'commercial_snapshot'->>'invoice_fee_sek')::numeric
        else null end,
      coalesce(pv.publication_snapshot->'commercial_snapshot','{}'::jsonb)
    ) invoice_fee_ready,
    exists(
      select 1 from public.contract_offers source_offer
      where source_offer.company_id=a.company_id
        and source_offer.id::text=
          pv.publication_snapshot->>'source_contract_offer_id'
        and source_offer.contract_product_version_id=
          pv.contract_product_version_id
        and source_offer.price_plan_version_id=pv.price_plan_version_id
    ) source_offer_consistent
  from public.contract_publication_versions pv
  join public.contract_publications p on p.id=pv.contract_publication_id
  join public.tenant_contract_assignments a on a.id=p.assignment_id
  left join public.tenant_contract_channels c
    on c.assignment_id=a.id and c.channel=p.channel
  join public.contract_product_versions product_version
    on product_version.id=pv.contract_product_version_id
  where pv.id=p_publication_version_id
), option_stats as (
  select count(*) filter(where o.status='active') option_count,
    count(*) filter(where o.status='active' and o.is_default) default_count,
    count(*) filter(where o.status='active' and o.selection_required) required_count,
    count(*) filter(where o.status='active' and o.selection_required is null)
      missing_selection_policy_count,
    count(*) filter(where o.status='active' and (
      nullif(btrim(o.option_reference),'') is null
      or nullif(btrim(o.option_code),'') is null
    )) missing_identifier_count,
    count(*) filter(where o.status='active' and (
      o.customer_type is null or not exists(
        select 1 from publication p
        where o.customer_type='both' or p.customer_type='both'
          or o.customer_type=p.customer_type
      )
    )) invalid_customer_type_count,
    count(*) filter(where o.status='active' and not exists(
      select 1 from publication p where o.contract_type=p.contract_type
    )) invalid_contract_type_count
  from public.contract_price_options o
  where o.contract_publication_version_id=p_publication_version_id
), duplicate_options as (
  select count(*) duplicate_count
  from (
    select o.option_reference stable_value
    from public.contract_price_options o
    where o.contract_publication_version_id=p_publication_version_id
      and o.status='active'
    group by o.option_reference having count(*)>1
    union all
    select o.option_code stable_value
    from public.contract_price_options o
    where o.contract_publication_version_id=p_publication_version_id
      and o.status='active'
    group by o.option_code having count(*)>1
  ) duplicated
), missing_areas as (
  select count(*) missing_count
  from publication p
  join public.contract_price_options o
    on o.contract_publication_version_id=p.id and o.status='active'
  cross join unnest(p.supported_areas) required_area
  where p.contract_type='fixed'
    and not exists(
      select 1 from public.contract_price_option_area_prices a
      where a.contract_price_option_id=o.id
        and a.price_area=required_area
        and a.status='active'
        and a.amount is not null and a.amount>=0
        and a.unit in ('ore_per_kwh','sek_per_kwh')
    )
), legal as (
  select exists(
    select 1
    from publication p
    join public.legal_bundle_versions b
      on b.id=p.legal_bundle_version_id and b.company_id=p.company_id
    where b.status in ('published','replaced','archived')
      and b.locked_at is not null
      and cardinality(coalesce(b.unresolved_variables,'{}'::text[]))=0
      and exists(
        select 1 from public.legal_bundle_version_documents d
        where d.legal_bundle_version_id=b.id
      )
  ) ready
)
select array_remove(array[
  case when not exists(select 1 from publication)
    then 'PUBLICATION_VERSION_NOT_FOUND' end,
  case when not coalesce((select source_offer_consistent from publication),false)
    then 'PUBLICATION_SOURCE_OFFER_MISMATCH' end,
  case when (select option_count from option_stats)=0
    then 'PUBLICATION_PRICE_OPTIONS_MISSING' end,
  case when (select missing_identifier_count from option_stats)>0
    then 'PUBLICATION_PRICE_OPTION_IDENTIFIER_MISSING' end,
  case when (select duplicate_count from duplicate_options)>0
    then 'PUBLICATION_PRICE_OPTION_DUPLICATE' end,
  case when (select default_count from option_stats)<>1
    then 'PUBLICATION_PRICE_OPTION_DEFAULT_INVALID' end,
  case when (select missing_selection_policy_count from option_stats)>0
    then 'PUBLICATION_PRICE_OPTION_SELECTION_POLICY_MISSING' end,
  case when (select option_count from option_stats)=1
      and (select required_count from option_stats)<>0
    then 'PUBLICATION_PRICE_OPTION_SELECTION_POLICY_INVALID' end,
  case when (select option_count from option_stats)>1
      and (select required_count from option_stats)<>(select option_count from option_stats)
    then 'PUBLICATION_PRICE_OPTION_SELECTION_POLICY_INVALID' end,
  case when (select invalid_customer_type_count from option_stats)>0
    then 'PUBLICATION_PRICE_OPTION_CUSTOMER_TYPE_INVALID' end,
  case when (select invalid_contract_type_count from option_stats)>0
    then 'PUBLICATION_PRICE_OPTION_CONTRACT_TYPE_INVALID' end,
  case when not coalesce((select supported_areas_valid from publication),false)
    then 'PUBLICATION_SUPPORTED_PRICE_AREA_INVALID' end,
  case when (select missing_count from missing_areas)>0
    then 'PUBLICATION_AREA_PRICES_MISSING' end,
  case when not (select ready from legal)
    then 'PUBLICATION_LEGAL_BUNDLE_MISSING' end,
  case when not coalesce((select invoice_fee_ready from publication),false)
    then 'INVOICE_FEE_CONFIGURATION_MISSING' end,
  case when coalesce((select assignment_status from publication),'missing')<>'active'
    then 'PUBLICATION_TENANT_NOT_READY' end,
  case when coalesce((select channel_status from publication),'missing')<>'active'
    then 'PUBLICATION_CHANNEL_NOT_ACTIVE' end,
  case when (select publication_channel from publication)='website'
      and not coalesce((select website_publication_allowed from publication),false)
    then 'PUBLICATION_WEBSITE_PERMISSION_MISSING' end,
  case when (select publication_channel from publication)='api'
      and not coalesce((select api_publication_allowed from publication),false)
    then 'PUBLICATION_API_PERMISSION_MISSING' end
]::text[],null)
$_$;

--
-- Name: gridex_validate_staff_identity_binding_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_staff_identity_binding_v1(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ DECLARE result jsonb; BEGIN
 result:=public.gridex_resolve_staff_identity_v1(p_command);
 IF result->>'binding_id' IS DISTINCT FROM p_command->>'binding_id' OR result->>'binding_version' IS DISTINCT FROM p_command->>'binding_version' OR result->>'actor_user_id' IS DISTINCT FROM p_command->>'actor_user_id'
 THEN RAISE EXCEPTION 'staff_identity_binding_mismatch' USING ERRCODE='42501'; END IF;
 RETURN result;
END $$;

--
-- Name: gridex_validate_website_application_portal_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_validate_website_application_portal_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_auth_user_id text;
  v_portal_user_id text;
  v_mode text;
begin
  if tg_op = 'INSERT' then
    -- Canonical website customers always participate in the portal identity
    -- lifecycle, but the tenant decides whether that identity is required now
    -- or may be linked after checkout.
    if coalesce(new.portal_identity_required, false) is not true then
      raise exception using
        errcode = '23514',
        message = 'portal_identity_lifecycle_required',
        detail = 'New website applications require portal_identity_required=true.';
    end if;

    select case lower(coalesce(c.metadata ->> 'website_portal_identity_mode', 'pre_auth_required'))
      when 'post_auth_allowed' then 'post_auth_allowed'
      else 'pre_auth_required'
    end
    into v_mode
    from public.companies c
    where c.id = new.company_id;

    if v_mode is null then
      raise exception using
        errcode = '23503',
        message = 'website_application_tenant_not_found',
        detail = 'The application company_id must identify an existing tenant.';
    end if;

    -- Freeze the policy that applied when the request was accepted so later
    -- tenant configuration changes cannot make historical rows un-updateable.
    new.portal_identity_submission_mode := v_mode;
  else
    if new.company_id is distinct from old.company_id then
      raise exception using
        errcode = '23514',
        message = 'website_application_tenant_change_forbidden',
        detail = 'A website application can never move between tenants.';
    end if;

    if coalesce(old.portal_identity_required, false) is true
       and coalesce(new.portal_identity_required, false) is not true then
      raise exception using
        errcode = '23514',
        message = 'portal_identity_lifecycle_downgrade_forbidden',
        detail = 'A canonical website application cannot disable portal identity lifecycle enforcement.';
    end if;

    if new.portal_identity_submission_mode is distinct from old.portal_identity_submission_mode then
      raise exception using
        errcode = '23514',
        message = 'portal_identity_submission_mode_immutable',
        detail = 'The submission-time portal identity policy is immutable.';
    end if;

    v_mode := old.portal_identity_submission_mode;
  end if;

  -- Historical rows created before this policy model remain operationally
  -- updateable. If a valid pair is later supplied, it is still validated below.
  if v_mode = 'legacy' then
    v_auth_user_id := nullif(btrim(coalesce(new.payload ->> 'auth_user_id', '')), '');
    v_portal_user_id := nullif(btrim(coalesce(new.payload ->> 'customer_portal_user_id', '')), '');
    if v_auth_user_id is null and v_portal_user_id is null then
      return new;
    end if;
  else
    v_auth_user_id := nullif(btrim(coalesce(new.payload ->> 'auth_user_id', '')), '');
    v_portal_user_id := nullif(btrim(coalesce(new.payload ->> 'customer_portal_user_id', '')), '');
  end if;

  -- Never accept a half-present identity. Optional means both absent, not one
  -- identifier without the other.
  if (v_auth_user_id is null) <> (v_portal_user_id is null) then
    raise exception using
      errcode = '23514',
      message = 'website_portal_identity_pair_required',
      detail = 'auth_user_id and customer_portal_user_id must either both be absent or both be present.';
  end if;

  if v_auth_user_id is null then
    if v_mode = 'pre_auth_required' then
      raise exception using
        errcode = '23514',
        message = 'portal_auth_identity_required',
        detail = 'This tenant requires auth_user_id and customer_portal_user_id before submission.';
    end if;
    return new;
  end if;

  if v_auth_user_id is distinct from v_portal_user_id
     or v_auth_user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception using
      errcode = '23514',
      message = 'portal_auth_identity_mismatch',
      detail = 'Portal identifiers must be the same valid UUID from one verified tenant server session.';
  end if;

  return new;
end;
$_$;

--
-- Name: gridex_verify_contract_lifecycle_backfill(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_verify_contract_lifecycle_backfill(p_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_checks jsonb;
  v_total bigint;
begin
  with checks as (
    select 'MISSING_CANONICAL_PRODUCT'::text check_name,count(*)::bigint error_count,
      coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb) examples,'critical'::text severity
    from (select id,row_number() over(order by id) rn from public.contract_offers
          where (p_company_id is null or company_id=p_company_id) and contract_product_id is null) q
    union all
    select 'MISSING_CANONICAL_VERSION',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select id,row_number() over(order by id) rn from public.contract_offers
          where (p_company_id is null or company_id=p_company_id) and contract_product_version_id is null) q
    union all
    select 'MISSING_TENANT_ASSIGNMENT',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select o.id,row_number() over(order by o.id) rn from public.contract_offers o
          where (p_company_id is null or o.company_id=p_company_id)
            and o.contract_product_version_id is not null and not exists(
              select 1 from public.tenant_contract_assignments ta
              where ta.company_id=o.company_id and ta.contract_product_version_id=o.contract_product_version_id)) q
    union all
    select 'ACTIVE_CHANNEL_WITHOUT_PUBLICATION_VERSION',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select ch.id,row_number() over(order by ch.id) rn
          from public.tenant_contract_channels ch
          join public.tenant_contract_assignments ta on ta.id=ch.assignment_id
          where (p_company_id is null or ta.company_id=p_company_id) and ch.status='active' and ch.channel<>'internal'
            and not exists(
              select 1 from public.contract_publications cp
              join public.contract_publication_versions cpv on cpv.contract_publication_id=cp.id
              where cp.assignment_id=ta.id and cp.channel=ch.channel and cpv.status='published'
                and cpv.contract_product_version_id=ta.contract_product_version_id)) q
    union all
    select 'ACTIVE_PUBLIC_OFFER_WITHOUT_CANONICAL_PUBLICATION',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select p.id,row_number() over(order by p.id) rn from public.public_contract_offers p
          where (p_company_id is null or p.company_id=p_company_id)
            and p.is_public and not p.is_archived and p.publication_status='published'
            and (p.source_contract_offer_id is null or p.contract_product_version_id is null
                 or p.contract_publication_version_id is null)) q
    union all
    select 'ARCHIVED_OFFER_WITH_ACTIVE_CHANNEL',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select o.id,row_number() over(order by o.id) rn from public.contract_offers o
          where (p_company_id is null or o.company_id=p_company_id) and o.lifecycle_status='archived'
            and exists(select 1 from public.tenant_contract_assignments ta
              join public.tenant_contract_channels ch on ch.assignment_id=ta.id
              where ta.company_id=o.company_id and ta.contract_product_version_id=o.contract_product_version_id
                and ch.status='active')) q
    union all
    select 'DUPLICATE_ACTIVE_PUBLICATION_VERSION',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select (array_agg(cpv.id order by cpv.id))[1] id,row_number() over(order by cp.id) rn
          from public.contract_publications cp
          join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
          join public.contract_publication_versions cpv on cpv.contract_publication_id=cp.id and cpv.status='published'
          where p_company_id is null or ta.company_id=p_company_id
          group by cp.id having count(*)>1) q
    union all
    select 'ORPHAN_PUBLICATION_VERSION',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'critical'
    from (select cpv.id,row_number() over(order by cpv.id) rn
          from public.contract_publication_versions cpv
          left join public.contract_publications cp on cp.id=cpv.contract_publication_id
          where cp.id is null) q
    union all
    select 'OPEN_BACKFILL_ISSUE',count(*),coalesce(jsonb_agg(id) filter(where rn<=10),'[]'::jsonb),'warning'
    from (select i.id,row_number() over(order by i.last_seen_at desc,i.id) rn
          from public.contract_lifecycle_backfill_issues i
          where i.status='open' and (p_company_id is null or i.company_id=p_company_id)) q
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'check_name',check_name,'error_count',error_count,'examples',examples,
           'severity',severity,
           'recommended_action',case when check_name='OPEN_BACKFILL_ISSUE'
             then 'Review contract_lifecycle_backfill_issues.' else 'Repair canonical contract lifecycle mapping.' end
         ) order by check_name),'[]'::jsonb),
         coalesce(sum(error_count) filter(where severity='critical'),0)
  into v_checks,v_total from checks;

  return jsonb_build_object(
    'ok',v_total=0,'critical_error_count',v_total,'checks',v_checks,'verified_at',now()
  );
end $$;

--
-- Name: FUNCTION gridex_verify_contract_lifecycle_backfill(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_verify_contract_lifecycle_backfill(p_company_id uuid) IS 'Returns machine-readable canonical lifecycle integrity checks and example IDs.';

--
-- Name: gridex_verify_contract_schema_alignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_verify_contract_schema_alignment() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_missing text[]:='{}'::text[];
  v_functions text[]:=array[
    'gridex_upsert_internal_contract_offer','gridex_sync_internal_offer_to_canonical',
    'gridex_validate_contract_readiness','gridex_publish_internal_contract_version','gridex_publish_contract_channel','gridex_unpublish_contract_channel',
    'gridex_pause_contract_channels','gridex_archive_contract_product',
    'gridex_restore_archived_contract','gridex_preview_delete_unused_contract',
    'gridex_delete_unused_contract','gridex_cleanup_unused_contract_drafts'
  ];
  v_function text;
  v_column text;
begin
  foreach v_function in array v_functions loop
    if to_regprocedure('public.'||v_function||case v_function
      when 'gridex_upsert_internal_contract_offer' then '(uuid,uuid,jsonb,jsonb,uuid)'
      when 'gridex_sync_internal_offer_to_canonical' then '(uuid)'
      when 'gridex_validate_contract_readiness' then '(uuid,uuid)'
      when 'gridex_publish_internal_contract_version' then '(uuid,uuid,uuid)'
      when 'gridex_publish_contract_channel' then '(uuid,uuid,text,uuid)'
      when 'gridex_unpublish_contract_channel' then '(uuid,uuid,text,uuid)'
      when 'gridex_pause_contract_channels' then '(uuid,uuid,uuid)'
      when 'gridex_archive_contract_product' then '(uuid,uuid,uuid)'
      when 'gridex_restore_archived_contract' then '(uuid,uuid,uuid)'
      when 'gridex_preview_delete_unused_contract' then '(uuid,uuid)'
      when 'gridex_delete_unused_contract' then '(uuid,uuid,uuid)'
      else '(uuid,uuid,boolean)' end) is null then
      v_missing:=array_append(v_missing,'function:'||v_function);
    end if;
  end loop;

  foreach v_column in array array[
    'version_series_id','lifecycle_status','discount_months','discount_calculation_base',
    'automatic_renewal_term_months','power_of_attorney_mode','contract_product_id','contract_product_version_id'
  ] loop
    if not exists(
      select 1 from information_schema.columns
      where table_schema='public' and table_name='contract_offers' and column_name=v_column
    ) then
      v_missing:=array_append(v_missing,'contract_offers.'||v_column);
    end if;
  end loop;

  if exists(
    select 1 from public.public_contract_offers
    where source_contract_offer_id is null
  ) then
    v_missing:=array_append(v_missing,'data:public_offer_without_canonical_source');
  end if;

  if exists(
    select 1 from public.public_contract_offers
    where (is_public or website_enabled or website_cta_enabled or publication_status='published')
      and (contract_product_id is null or contract_product_version_id is null
           or contract_publication_version_id is null)
  ) then
    v_missing:=array_append(v_missing,'data:published_offer_without_canonical_publication');
  end if;

  return jsonb_build_object(
    'ok',cardinality(v_missing)=0,
    'missing',v_missing,
    'checked_at',now(),
    'contract_model_version','2026-07-21.2'
  );
end $$;

--
-- Name: gridex_version_ediel_route_profile_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_version_ediel_route_profile_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'ediel_route_history_tenant_immutable'; END IF;
 IF (to_jsonb(NEW)-ARRAY['route_version','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['route_version','updated_at','updated_by']) THEN
  INSERT INTO public.ediel_route_history(route_profile_id,company_id,route_version,snapshot,change_reason,created_by)
   VALUES(OLD.id,OLD.company_id,coalesce(OLD.route_version,1),to_jsonb(OLD),'observed_before_update',coalesce(OLD.updated_by,OLD.created_by)) ON CONFLICT(route_profile_id,route_version) DO NOTHING;
  NEW.route_version:=coalesce(OLD.route_version,1)+1;
 ELSE NEW.route_version:=OLD.route_version;
 END IF;
 RETURN NEW;
END $$;

--
-- Name: gridex_whitelabel_portfolio_overview(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_whitelabel_portfolio_overview(p_white_label_platform_id uuid, p_month date DEFAULT CURRENT_DATE) RETURNS TABLE(company_id uuid, company_name text, company_status text, active_customers integer, new_customers integer, churned_customers integer, net_change integer, poa_requested integer, poa_active integer, metering_requests_total integer, metering_requests_historical integer, forecast_month_kwh numeric, forecast_3m_kwh numeric, forecast_6m_kwh numeric, forecast_12m_kwh numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_month date := date_trunc('month', coalesce(p_month, current_date))::date;
begin
  if not public.gridex_user_can_read_whitelabel_platform(p_white_label_platform_id)
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not allowed to read this white-label platform' using errcode = '42501';
  end if;

  return query
  select c.id, c.name, c.status,
         s.active_customers, s.new_customers, s.churned_customers,
         s.active_customers - s.active_customers_start,
         s.poa_requested, s.poa_active, s.metering_requests_total, s.metering_requests_historical,
         f.m1, f.m3, f.m6, f.m12
  from public.companies c
  cross join lateral public.gridex_customer_portfolio_monthly_internal(c.id, v_month, v_month) s
  cross join lateral (
    select sum(x.forecast_kwh) filter (where x.month_index <= 1) as m1,
           sum(x.forecast_kwh) filter (where x.month_index <= 3) as m3,
           sum(x.forecast_kwh) filter (where x.month_index <= 6) as m6,
           sum(x.forecast_kwh) as m12
    from public.gridex_customer_portfolio_forecast_cached_internal(c.id, v_month) x
  ) f
  where c.white_label_platform_id = p_white_label_platform_id
    and c.status <> 'deleted_test_only'
  order by c.name;
end;
$$;

