--
-- Name: guard_ediel_test_run_message_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_ediel_test_run_message_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_run public.ediel_test_runs%rowtype;
  v_message public.ediel_messages%rowtype;
begin
  select * into strict v_run from public.ediel_test_runs where id=new.test_run_id;
  select * into strict v_message from public.ediel_messages where id=new.ediel_message_id;

  if new.company_id is null or v_run.company_id is null or v_message.company_id is null
     or new.company_id<>v_run.company_id or new.company_id<>v_message.company_id then
    raise exception 'ediel_test_evidence_tenant_mismatch';
  end if;
  if lower(coalesce(v_run.environment,''))<>'test' then
    raise exception 'ediel_test_run_environment_must_be_test';
  end if;
  if lower(coalesce(v_message.environment,''))<>'test' or coalesce(v_message.test_flag,0)<>1 then
    raise exception 'production_message_cannot_be_test_evidence';
  end if;
  if v_message.created_at<coalesce(v_run.started_at,v_run.created_at) then
    raise exception 'test_evidence_predates_run';
  end if;
  return new;
end;
$$;

--
-- Name: guard_last_functioning_tenant_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_last_functioning_tenant_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_company_id uuid := old.company_id;
  v_old_role text := old.membership_role;
  v_old_was_active boolean := old.status = 'active' and coalesce(old.is_active, true);
  v_owner_count bigint;
  v_admin_count bigint;
begin
  if not v_old_was_active or v_old_role not in ('owner', 'admin', 'company_admin') then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;
  if tg_op = 'UPDATE'
     and new.status = 'active' and coalesce(new.is_active, true)
     and new.membership_role = v_old_role then
    return new;
  end if;
  if not exists (
    select 1 from auth.users u join public.user_profiles up on up.id = u.id
    where u.id = old.user_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= now())
      and u.email_confirmed_at is not null and up.user_status = 'active'
  ) then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  select count(*) into v_owner_count
  from public.company_memberships cm
  join auth.users u on u.id = cm.user_id
  join public.user_profiles up on up.id = u.id
  where cm.company_id = v_company_id and cm.status = 'active' and coalesce(cm.is_active, true)
    and cm.membership_role = 'owner' and u.deleted_at is null
    and (u.banned_until is null or u.banned_until <= now())
    and u.email_confirmed_at is not null and up.user_status = 'active';
  select count(*) into v_admin_count
  from public.company_memberships cm
  join auth.users u on u.id = cm.user_id
  join public.user_profiles up on up.id = u.id
  where cm.company_id = v_company_id and cm.status = 'active' and coalesce(cm.is_active, true)
    and cm.membership_role in ('owner', 'admin', 'company_admin') and u.deleted_at is null
    and (u.banned_until is null or u.banned_until <= now())
    and u.email_confirmed_at is not null and up.user_status = 'active';
  if v_old_role = 'owner' and v_owner_count = 0 then
    raise exception 'last_functioning_owner_cannot_be_removed_or_downgraded';
  end if;
  if v_admin_count = 0 then
    raise exception 'last_functioning_admin_cannot_be_removed_or_downgraded';
  end if;
  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;

--
-- Name: guard_machine_passed_actor_test_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_machine_passed_actor_test_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status='passed' and not exists(
    select 1
    from public.actor_test_attempts a
    where a.company_id=new.company_id
      and a.test_run_id=new.ediel_test_run_id
      and a.test_case_code=upper(new.test_key)
      and a.configuration_snapshot_id=new.configuration_snapshot_id
      and a.configuration_hash=new.configuration_hash
      and a.status='passed'
      and a.machine_verified
      and a.evidence_digest is not null
      and exists(
        select 1 from public.actor_test_attempt_evidence e
        where e.company_id=a.company_id and e.attempt_id=a.id
          and e.test_run_id=a.test_run_id
          and e.configuration_snapshot_id=a.configuration_snapshot_id
          and e.evidence_role='source_message'
      )
  ) then
    raise exception 'passed_requires_matching_canonical_machine_evidence';
  end if;
  if new.status='manual_verified' and not exists(
    select 1
    from public.actor_test_attempts a
    join public.actor_test_manual_attestations ma
      on ma.company_id=a.company_id and ma.attempt_id=a.id
    where a.company_id=new.company_id
      and a.test_run_id=new.ediel_test_run_id
      and a.test_case_code=upper(new.test_key)
      and a.configuration_snapshot_id=new.configuration_snapshot_id
      and a.configuration_hash=new.configuration_hash
      and a.status='manual_verified'
      and not a.machine_verified
      and ma.status='approved'
      and ma.requested_by<>ma.approved_by
  ) then
    raise exception 'manual_verified_requires_matching_canonical_attestation';
  end if;
  return new;
end;
$$;

--
-- Name: guard_tenant_invitation_acceptance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_tenant_invitation_acceptance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_status text;
begin
  if new.status='accepted'
     and (tg_op='INSERT' or old.status is distinct from 'accepted') then
    select status into v_status from public.companies where id=new.company_id;
    if v_status not in ('onboarding','active') then
      raise exception 'tenant_state_blocks_invitation_acceptance:%',coalesce(v_status,'unknown');
    end if;
  end if;
  return new;
end;
$$;

--
-- Name: integration_api_rate_limit_check(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.integration_api_rate_limit_check(p_api_client_id uuid, p_route text, p_limit integer, p_window_seconds integer DEFAULT 60) RETURNS TABLE(allowed boolean, request_count integer, limit_value integer, reset_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_window_seconds integer := greatest(1, least(coalesce(p_window_seconds, 60), 3600));
  v_limit integer := coalesce(p_limit, 0);
  v_route text := nullif(btrim(coalesce(p_route, '')), '');
  v_window_start timestamptz;
  v_company_id uuid;
  v_count integer;
begin
  if p_api_client_id is null or v_route is null then
    raise exception 'api_client_id and route are required' using errcode = '22023';
  end if;

  if v_limit <= 0 then
    raise exception 'rate limit must be greater than zero' using errcode = '22023';
  end if;

  select c.company_id
  into v_company_id
  from public.integration_api_clients c
  where c.id = p_api_client_id
    and c.status = 'active';

  if v_company_id is null then
    raise exception 'active API client not found' using errcode = '42501';
  end if;

  v_window_start := to_timestamp(
    floor(extract(epoch from clock_timestamp()) / v_window_seconds) * v_window_seconds
  );

  insert into public.integration_api_rate_limit_buckets (
    api_client_id,
    company_id,
    route,
    window_started_at,
    request_count,
    updated_at
  ) values (
    p_api_client_id,
    v_company_id,
    left(v_route, 300),
    v_window_start,
    1,
    clock_timestamp()
  )
  on conflict (api_client_id, route, window_started_at)
  do update set
    request_count = public.integration_api_rate_limit_buckets.request_count + 1,
    company_id = excluded.company_id,
    updated_at = clock_timestamp()
  returning integration_api_rate_limit_buckets.request_count into v_count;

  -- Cleanup once per newly opened bucket rather than on every request.
  if v_count = 1 then
    delete from public.integration_api_rate_limit_buckets
    where window_started_at < clock_timestamp() - interval '2 hours';
  end if;

  return query select
    v_count <= v_limit,
    v_count,
    v_limit,
    v_window_start + make_interval(secs => v_window_seconds);
end;
$$;

--
-- Name: FUNCTION integration_api_rate_limit_check(p_api_client_id uuid, p_route text, p_limit integer, p_window_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.integration_api_rate_limit_check(p_api_client_id uuid, p_route text, p_limit integer, p_window_seconds integer) IS 'Atomically consumes one request from a tenant-scoped API-client route bucket and returns limit/reset metadata.';

