--
-- Name: portal_customer_documents_page_v1(uuid, uuid, timestamp with time zone, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_customer_documents_page_v1(p_company_id uuid, p_customer_id uuid, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_source_rank integer DEFAULT NULL::integer, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 51) RETURNS TABLE(id uuid, source_table text, source_rank integer, document_type text, status text, title text, file_name text, mime_type text, file_size_bytes bigint, public_url text, source_system text, source text, power_of_attorney_id uuid, document_version text, uploaded_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with all_documents as (
    select
      d.id,
      'customer_documents'::text as source_table,
      2::integer as source_rank,
      d.document_type,
      d.status,
      d.title,
      d.file_name,
      d.mime_type,
      d.file_size_bytes,
      d.public_url,
      d.source_system,
      d.source,
      d.power_of_attorney_id,
      d.document_version,
      null::timestamptz as uploaded_at,
      d.created_at
    from public.customer_documents d
    where d.company_id = p_company_id
      and d.customer_id = p_customer_id
    union all
    select
      a.id,
      'customer_authorization_documents'::text as source_table,
      1::integer as source_rank,
      a.document_type,
      a.status,
      a.title,
      a.file_name,
      a.mime_type,
      a.file_size_bytes,
      null::text as public_url,
      'customer_authorization_documents'::text as source_system,
      'customer_authorization_documents'::text as source,
      a.power_of_attorney_id,
      null::text as document_version,
      a.uploaded_at,
      a.created_at
    from public.customer_authorization_documents a
    where a.company_id = p_company_id
      and a.customer_id = p_customer_id
      and a.status <> 'archived'
  ),
  deduplicated as (
    select x.*
    from (
      select
        d.*,
        row_number() over (
          partition by coalesce(
            d.power_of_attorney_id::text,
            d.source_table || ':' || d.id::text
          )
          order by d.source_rank desc, d.created_at desc, d.id desc
        ) as duplicate_rank
      from all_documents d
    ) x
    where x.duplicate_rank = 1
  )
  select
    d.id,d.source_table,d.source_rank,d.document_type,d.status,d.title,d.file_name,
    d.mime_type,d.file_size_bytes,d.public_url,d.source_system,d.source,
    d.power_of_attorney_id,d.document_version,d.uploaded_at,d.created_at
  from deduplicated d
  where p_cursor_created_at is null
     or (d.created_at, d.source_rank, d.id)
        < (p_cursor_created_at, coalesce(p_cursor_source_rank, 0), p_cursor_id)
  order by d.created_at desc, d.source_rank desc, d.id desc
  limit greatest(1, least(coalesce(p_limit, 51), 101));
$$;

--
-- Name: portal_customer_events_page_v1(uuid, uuid, timestamp with time zone, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_customer_events_page_v1(p_company_id uuid, p_customer_id uuid, p_cursor_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_source_rank integer DEFAULT NULL::integer, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 51) RETURNS TABLE(id uuid, source_table text, source_rank integer, event_type text, source text, occurred_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with all_events as (
    select
      e.id,
      'customer_events'::text as source_table,
      2::integer as source_rank,
      e.event_type,
      e.source,
      coalesce(e.occurred_at, e.created_at) as occurred_at,
      e.created_at
    from public.customer_events e
    where e.company_id = p_company_id
      and e.customer_id = p_customer_id

    union all

    select
      d.id,
      'domain_events'::text as source_table,
      1::integer as source_rank,
      d.event_type,
      d.source,
      coalesce(d.occurred_at, d.created_at) as occurred_at,
      d.created_at
    from public.domain_events d
    where d.company_id = p_company_id
      and d.subject_customer_id = p_customer_id
  )
  select
    e.id,
    e.source_table,
    e.source_rank,
    e.event_type,
    e.source,
    e.occurred_at,
    e.created_at
  from all_events e
  where p_cursor_occurred_at is null
     or (e.occurred_at, e.source_rank, e.id)
        < (p_cursor_occurred_at, coalesce(p_cursor_source_rank, 0), p_cursor_id)
  order by e.occurred_at desc, e.source_rank desc, e.id desc
  limit greatest(1, least(coalesce(p_limit, 51), 101));
$$;

