--
-- Name: prevent_terminal_actor_test_attempt_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_terminal_actor_test_attempt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.status in ('passed','failed','blocked','manual_verified','superseded') then
    raise exception 'terminal_actor_test_attempts_are_immutable';
  end if;
  if tg_op='UPDATE' and (
    new.company_id is distinct from old.company_id
    or new.test_run_id is distinct from old.test_run_id
    or new.test_case_code is distinct from old.test_case_code
    or new.environment_type is distinct from old.environment_type
    or new.actor_role is distinct from old.actor_role
    or new.role_code is distinct from old.role_code
    or new.test_suite is distinct from old.test_suite
    or new.setup_package is distinct from old.setup_package
    or new.message_family is distinct from old.message_family
    or new.message_variant is distinct from old.message_variant
    or new.configuration_snapshot_id is distinct from old.configuration_snapshot_id
    or new.configuration_hash is distinct from old.configuration_hash
    or new.rulebook_version is distinct from old.rulebook_version
  ) then
    raise exception 'actor_test_attempt_identity_is_immutable';
  end if;
  if tg_op='DELETE' then
    return old;
  end if;
  return new;
end;
$$;

--
-- Name: prevent_terminal_actor_test_attestation_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_terminal_actor_test_attestation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.status in ('approved','rejected','revoked') then
    raise exception 'terminal_actor_test_attestation_is_immutable';
  end if;
  if tg_op='DELETE' then return old; end if;
  if new.company_id is distinct from old.company_id
     or new.test_run_id is distinct from old.test_run_id
     or new.test_case_code is distinct from old.test_case_code
     or new.requested_by is distinct from old.requested_by
     or new.requested_at is distinct from old.requested_at
     or new.reason is distinct from old.reason
     or new.evidence_reference is distinct from old.evidence_reference then
    raise exception 'actor_test_attestation_identity_is_immutable';
  end if;
  return new;
end;
$$;

--
-- Name: project_website_application_committed_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_website_application_committed_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_event_type constant text:='WEBSITE_APPLICATION_COMMITTED';
  v_topic constant text:='website.application.committed';
  v_idempotency_key text;
  v_domain_event_id uuid;
  v_payload jsonb;
begin
  if new.event_code<>'workflow.committed' then return new; end if;

  v_idempotency_key:=format('website_application_committed:%s',new.customer_application_id);
  v_payload:=jsonb_build_object(
    'customer_application_id',new.customer_application_id,
    'workflow_id',new.workflow_id,
    'operation_id',new.operation_id,
    'state',new.to_state,
    'workflow_event_id',new.id,
    'workflow_event_occurred_at',new.occurred_at,
    'metadata',new.metadata
  );

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,
    idempotency_key,after_state,metadata
  ) values (
    new.company_id,v_event_type,'website_customer_application',new.customer_application_id,
    new.actor_user_id,'Durable customer-application workflow committed.',
    v_idempotency_key,jsonb_build_object('state',new.to_state,'workflow_id',new.workflow_id),v_payload
  ) on conflict(company_id,event_type,idempotency_key) do nothing;

  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    new.company_id,v_event_type,'website_customer_application',new.customer_application_id,
    v_idempotency_key,v_payload,new.actor_user_id
  ) on conflict(company_id,event_type,idempotency_key) do nothing;

  select id into strict v_domain_event_id
  from public.canonical_domain_events
  where company_id=new.company_id and event_type=v_event_type
    and idempotency_key=v_idempotency_key;

  insert into public.canonical_event_outbox(
    company_id,domain_event_id,topic,idempotency_key,payload
  ) values (
    new.company_id,v_domain_event_id,v_topic,v_idempotency_key,v_payload
  ) on conflict(company_id,topic,idempotency_key) do nothing;

  return new;
end;
$$;

--
-- Name: public_contract_feed_fingerprint_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_contract_feed_fingerprint_v1(p_company_id uuid, p_customer_type text DEFAULT NULL::text, p_channel text DEFAULT 'website'::text) RETURNS TABLE(fingerprint text, publication_revision bigint, publication_updated_at timestamp with time zone, stockholm_date date)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select
    md5(concat_ws(
      ':',
      p_company_id::text,
      p_channel,
      coalesce(p_customer_type,'all'),
      (current_timestamp at time zone 'Europe/Stockholm')::date::text,
      coalesce(r.revision,0)::text,
      coalesce(r.revision_token::text,'initial')
    )) as fingerprint,
    coalesce(r.revision,0)::bigint as publication_revision,
    r.updated_at as publication_updated_at,
    (current_timestamp at time zone 'Europe/Stockholm')::date as stockholm_date
  from (select 1) seed
  left join public.contract_publication_revisions r
    on r.company_id=p_company_id and r.channel=p_channel;
$$;

