--
-- Name: resolve_canonical_ediel_rule_pack(text, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_canonical_ediel_rule_pack(p_market text, p_family text, p_message_code text, p_transaction_subtype text, p_direction text, p_business_date date) RETURNS TABLE(rule_pack_id uuid, message_profile_id uuid, market text, family text, guide_version text, guide_revision text, unh_association_code text, valid_from date, valid_to date, source_document text, source_hash text, field_matrix_version text, profile_key text, business_process text, phase text, profile jsonb, parser_ready boolean, builder_ready boolean, validator_ready boolean, ack_ready boolean, state_machine_ready boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  if p_market <> 'electricity' or p_direction not in ('inbound','outbound') or p_business_date is null then
    raise exception 'canonical_rule_pack_invalid_request';
  end if;
  select count(*) into v_count
  from public.ediel_rule_packs rp
  join public.ediel_message_profiles mp on mp.rule_pack_id=rp.id and mp.is_enabled
  where rp.market=p_market and rp.family=upper(p_family) and mp.message_code=upper(p_message_code)
    and mp.transaction_subtype=coalesce(upper(nullif(btrim(p_transaction_subtype),'')),'')
    and mp.direction in (p_direction,'both')
    and rp.status in ('active','transition','future')
    and p_business_date >= rp.valid_from and (rp.valid_to is null or p_business_date <= rp.valid_to);
  if v_count <> 1 then
    raise exception 'canonical_rule_pack_resolution_count:%:%:%:%',v_count,p_family,p_message_code,coalesce(p_transaction_subtype,'');
  end if;
  return query
  select rp.id,mp.id,rp.market,rp.family,rp.guide_version,rp.guide_revision,rp.unh_association_code,
         rp.valid_from,rp.valid_to,rp.source_document,rp.source_hash,rp.field_matrix_version,
         mp.profile_key,mp.business_process,mp.phase,mp.profile,
         coalesce(rc.parser_ready,false),coalesce(rc.builder_ready,false),coalesce(rc.validator_ready,false),
         coalesce(rc.ack_ready,false),coalesce(rc.state_machine_ready,false)
  from public.ediel_rule_packs rp
  join public.ediel_message_profiles mp on mp.rule_pack_id=rp.id and mp.is_enabled
  left join public.ediel_runtime_capabilities rc on rc.rule_pack_id=rp.id and rc.message_code=mp.message_code
    and rc.transaction_subtype=mp.transaction_subtype and rc.direction in (p_direction,'both')
  where rp.market=p_market and rp.family=upper(p_family) and mp.message_code=upper(p_message_code)
    and mp.transaction_subtype=coalesce(upper(nullif(btrim(p_transaction_subtype),'')),'')
    and mp.direction in (p_direction,'both')
    and rp.status in ('active','transition','future')
    and p_business_date >= rp.valid_from and (rp.valid_to is null or p_business_date <= rp.valid_to);
end $$;

--
-- Name: resolve_canonical_ediel_rule_pack_with_witness_v1(text, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_canonical_ediel_rule_pack_with_witness_v1(p_market text, p_family text, p_message_code text, p_transaction_subtype text, p_direction text, p_business_date date) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected jsonb;pack public.ediel_rule_packs%rowtype;profile public.ediel_message_profiles%rowtype;sources jsonb;
BEGIN
 -- Hold the selection universe and source membership stable through the named
 -- read. Concurrent activation/config writes wait; no business tables lock.
 LOCK TABLE public.ediel_rule_packs,public.ediel_message_profiles,public.ediel_runtime_capabilities,public.ediel_rule_pack_sources IN SHARE MODE;
 SELECT to_jsonb(row) INTO STRICT selected FROM public.resolve_canonical_ediel_rule_pack(p_market,p_family,p_message_code,p_transaction_subtype,p_direction,p_business_date) row;
 SELECT * INTO STRICT pack FROM public.ediel_rule_packs WHERE id=(selected->>'rule_pack_id')::uuid FOR SHARE;
 SELECT * INTO STRICT profile FROM public.ediel_message_profiles WHERE id=(selected->>'message_profile_id')::uuid AND rule_pack_id=pack.id FOR SHARE;
 SELECT coalesce(jsonb_agg(to_jsonb(source) ORDER BY source.id),'[]'::jsonb) INTO sources FROM public.ediel_rule_pack_sources source WHERE rule_pack_id=pack.id;
 RETURN NEXT selected||jsonb_build_object('original_version',pack.guide_version||':r'||pack.guide_revision,
  'original_snapshot',jsonb_build_object('rulePack',to_jsonb(pack),'messageProfile',to_jsonb(profile),'guideSources',sources));
END $$;

--
-- Name: resolve_ediel_ack_matrix_rule(text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_ediel_ack_matrix_rule(p_message_family text, p_message_code text DEFAULT '*'::text, p_company_id uuid DEFAULT NULL::uuid, p_environment text DEFAULT NULL::text, p_requested_version text DEFAULT NULL::text) RETURNS TABLE(rule_id uuid, rule_version text, rule_checksum text, message_family text, message_code text, technical_ack text, application_ack text, business_responses text[], negative_application_response text, acknowledge_with text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id,r.rule_version,r.checksum,r.message_family,r.message_code,r.technical_ack,r.application_ack,
         r.business_responses,r.negative_application_response,r.acknowledge_with
  from public.ediel_ack_matrix_rules r
  where r.is_active=true
    and upper(r.message_family)=upper(p_message_family)
    and (upper(r.message_code)=upper(coalesce(nullif(p_message_code,''),'*')) or r.message_code='*')
    and (r.company_id is null or r.company_id=p_company_id)
    and (r.environment='all' or r.environment=coalesce(nullif(p_environment,''),'all'))
    and (
      p_requested_version is null
      or p_requested_version !~* '^canonical-'
      or r.rule_version=p_requested_version
    )
  order by case when r.company_id=p_company_id then 0 else 1 end,
           case when upper(r.message_code)=upper(coalesce(nullif(p_message_code,''),'*')) then 0 else 1 end,
           r.updated_at desc,
           r.created_at desc
  limit 1;
$$;

--
-- Name: resolve_ediel_rule_pack_fields(text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_ediel_rule_pack_fields(p_message_family text, p_message_code text, p_role_code text DEFAULT NULL::text, p_direction text DEFAULT NULL::text, p_environment text DEFAULT NULL::text, p_requested_version text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(profile_key text, rule_profile_version_id uuid, profile_version text, rule_pack_checksum text, message_family text, message_code text, field_key text, field_code text, field_name text, field_label text, segment_path text, requirement text, condition text, allowed_values text[], error_code_if_missing text, error_code_if_invalid text, error_code text, severity text, role_code text, direction text, environment text, version text, version_code text, is_active boolean, enabled boolean, dependency_note text, rule_payload jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with selected as (
    select p.*,v.id version_id,v.version selected_version,v.checksum,v.rules
    from public.ediel_rule_profiles p
    join public.ediel_rule_profile_versions v
      on v.profile_key=p.profile_key
     and v.version=p.active_version
     and v.status='active'
    where p.is_active=true
      and upper(p.message_family)=upper(p_message_family)
      and upper(coalesce(p.message_code,''))=upper(coalesce(p_message_code,''))
      and (p.company_id is null or p.company_id=p_company_id)
    order by case when p.company_id=p_company_id then 0 else 1 end,p.updated_at desc
    limit 1
  ), rows as (
    select
      s.profile_key,s.version_id,s.selected_version,s.checksum,
      s.message_family,s.message_code,
      coalesce(m.rule_payload->>'field_key','') as field_key,
      m.rule_payload->>'field_code' as field_code,
      m.rule_payload->>'field_name' as field_name,
      m.rule_payload->>'field_label' as field_label,
      coalesce(m.rule_payload->>'segment_path',m.segment) as segment_path,
      coalesce(m.rule_payload->>'requirement',m.rule_type,'optional') as requirement,
      m.rule_payload->>'condition' as condition,
      case when jsonb_typeof(m.rule_payload->'allowed_values')='array'
        then array(select jsonb_array_elements_text(m.rule_payload->'allowed_values')) else '{}'::text[] end as allowed_values,
      m.rule_payload->>'error_code_if_missing' as error_code_if_missing,
      m.rule_payload->>'error_code_if_invalid' as error_code_if_invalid,
      m.rule_payload->>'error_code' as error_code,
      coalesce(m.rule_payload->>'severity','error') as severity,
      m.rule_payload->>'role_code' as role_code,
      coalesce(m.rule_payload->>'direction','all') as direction,
      coalesce(m.rule_payload->>'environment','all') as environment,
      s.selected_version as version,
      s.selected_version as version_code,
      true as is_active,true as enabled,
      m.rule_payload->>'dependency_note' as dependency_note,
      m.rule_payload
    from selected s
    join public.ediel_field_matrix_rules m
      on m.rule_profile_version_id=s.version_id and m.status='active'
  )
  select * from rows
  union all
  select s.profile_key,s.version_id,s.selected_version,s.checksum,
         s.message_family,s.message_code,'__PROFILE__',null,null,null,null,'optional',null,
         '{}'::text[],null,null,null,'error',p_role_code,
         coalesce(p_direction,'all'),coalesce(p_environment,'all'),
         s.selected_version,s.selected_version,true,true,null,
         jsonb_build_object('profile_rules',s.rules,'snapshot_only',true)
  from selected s
  where not exists(select 1 from rows);
$$;

--
-- Name: resolve_ediel_timeseries_product_511(text, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_ediel_timeseries_product_511(p_product_characteristic text, p_product_type text, p_identity_type text, p_level_of_details text, p_business_activity_phase text, p_business_date date DEFAULT CURRENT_DATE) RETURNS TABLE(code text, description text, version text, message_codes text[], phase text, valid_from date, valid_to date, source_hash text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 select p.code,p.description,p.version,p.message_codes,p.phase,p.valid_from,p.valid_to,p.source_hash
 from public.ediel_timeseries_products p
 where p.family='UTILTS' and p.is_current
   and p.product_characteristic=upper(btrim(p_product_characteristic)) and p.product_type=upper(btrim(p_product_type))
   and p.identity_type=upper(btrim(p_identity_type)) and p.level_of_details=upper(btrim(p_level_of_details))
   and p.business_activity_phase=upper(btrim(p_business_activity_phase))
   and p.valid_from<=p_business_date and (p.valid_to is null or p.valid_to>=p_business_date)
 order by p.valid_from desc,p.version desc limit 1
$$;

--
-- Name: resolve_portal_customer_identity_v1(uuid, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_portal_customer_identity_v1(p_company_id uuid, p_email text DEFAULT NULL::text, p_customer_number text DEFAULT NULL::text, p_identifier text DEFAULT NULL::text, p_facility_id text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, company_id uuid, customer_number text, email text, personal_number text, org_number text, email_matched boolean, customer_number_matched boolean, identifier_matched boolean, facility_matched boolean, matched_factor_count integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
with candidate_rows as (
 select c.id,c.company_id,c.customer_number,c.email,c.personal_number,c.org_number,
  (nullif(lower(btrim(coalesce(p_email,''))),'') is not null and lower(btrim(coalesce(c.email,'')))=lower(btrim(p_email))) as email_matched,
  (nullif(btrim(coalesce(p_customer_number,'')),'') is not null and c.customer_number=btrim(p_customer_number)) as customer_number_matched,
  (nullif(btrim(coalesce(p_identifier,'')),'') is not null and (c.normalized_personal_number=btrim(p_identifier) or c.normalized_org_number=btrim(p_identifier) or regexp_replace(coalesce(c.personal_number,''),'[^0-9]','','g')=btrim(p_identifier) or regexp_replace(coalesce(c.org_number,''),'[^0-9]','','g')=btrim(p_identifier))) as identifier_matched,
  (nullif(btrim(coalesce(p_facility_id,'')),'') is not null and exists(select 1 from public.customer_sites s where s.company_id=p_company_id and s.customer_id=c.id and (s.normalized_facility_id=btrim(p_facility_id) or s.facility_id=btrim(p_facility_id)))) as facility_matched,
  c.created_at
 from public.customers c where c.company_id=p_company_id
), scored as (
 select r.*,(r.email_matched::integer+r.customer_number_matched::integer+r.identifier_matched::integer+r.facility_matched::integer) as factor_count from candidate_rows r
)
select s.id,s.company_id,s.customer_number,s.email,s.personal_number,s.org_number,s.email_matched,s.customer_number_matched,s.identifier_matched,s.facility_matched,s.factor_count
from scored s where s.factor_count>0 order by s.factor_count desc,s.created_at desc,s.id desc limit greatest(1,least(coalesce(p_limit,20),100));
$$;

--
-- Name: run_tenant_integrity_audit(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_tenant_integrity_audit(p_company_id uuid DEFAULT NULL::uuid, p_scope text DEFAULT 'all'::text, p_requested_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_run_id uuid;
  v_scope text := lower(coalesce(nullif(btrim(p_scope),''),'all'));
  v_total integer := 0;
  v_critical integer := 0;
  v_high integer := 0;
  v_medium integer := 0;
  v_low integer := 0;
  v_info integer := 0;
begin
  if v_scope not in ('all','access','operations','ediel') then
    raise exception using errcode='22023', message='tenant_integrity_invalid_scope';
  end if;
  if p_company_id is not null and not exists(select 1 from public.companies c where c.id=p_company_id) then
    raise exception using errcode='P0002', message='tenant_integrity_company_not_found';
  end if;

  insert into public.tenant_integrity_audit_runs(company_id,scope,requested_by,status,metadata)
  values(p_company_id,v_scope,p_requested_by,'running',jsonb_build_object('engine_version','v1'))
  returning id into v_run_id;

  begin
    if v_scope in ('all','operations') then
      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'TENANT-001',c.id,'company',c.id,r.severity,r.title,
             'Tenant lifecycle/status flags contradict the canonical tenant state.',
             md5('TENANT-001:'||c.id::text),
             jsonb_build_object('status',c.status,'is_active',c.is_active,'is_paused',c.is_paused,'lifecycle_status',c.lifecycle_status,'outbound_frozen',c.outbound_frozen)
      from public.companies c
      join public.tenant_integrity_rule_registry r on r.rule_key='TENANT-001' and r.is_enabled
      where (p_company_id is null or c.id=p_company_id)
        and (
          (c.status='paused' and coalesce(c.is_paused,false)=false)
          or (coalesce(c.is_paused,false)=true and c.status<>'paused')
          or (c.status in ('suspended','archived','pending_deletion','closed','deleted_test_only') and coalesce(c.is_active,false)=true)
        );

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'OPS-001',x.company_id,x.entity_type,x.entity_id,r.severity,r.title,
             x.message,md5('OPS-001:'||x.entity_type||':'||x.entity_id::text),x.evidence
      from (
        select coalesce(s.company_id,c.company_id) company_id,'customer_site'::text entity_type,s.id entity_id,
               'Customer site tenant differs from its customer tenant.'::text message,
               jsonb_build_object('site_company_id',s.company_id,'customer_company_id',c.company_id,'customer_id',c.id) evidence
        from public.customer_sites s join public.customers c on c.id=s.customer_id
        where s.company_id is distinct from c.company_id
          and (p_company_id is null or s.company_id=p_company_id or c.company_id=p_company_id)
        union all
        select coalesce(mp.company_id,s.company_id,c.company_id),'metering_point',mp.id,
               'Metering point relation disagrees with customer/site tenant or customer identity.',
               jsonb_build_object('meter_company_id',mp.company_id,'site_company_id',s.company_id,'customer_company_id',c.company_id,'meter_customer_id',mp.customer_id,'site_customer_id',s.customer_id,'site_id',s.id)
        from public.metering_points mp
        join public.customer_sites s on s.id=mp.site_id
        join public.customers c on c.id=s.customer_id
        where (mp.company_id is distinct from s.company_id or s.company_id is distinct from c.company_id or (mp.customer_id is not null and mp.customer_id is distinct from s.customer_id))
          and (p_company_id is null or mp.company_id=p_company_id or s.company_id=p_company_id or c.company_id=p_company_id)
        union all
        select coalesce(cc.company_id,c.company_id),'customer_contract',cc.id,
               'Customer contract relation disagrees with customer/site/metering point tenant.',
               jsonb_build_object('contract_company_id',cc.company_id,'customer_company_id',c.company_id,'site_company_id',s.company_id,'meter_company_id',mp.company_id,'customer_id',cc.customer_id,'site_id',coalesce(cc.customer_site_id,cc.site_id),'metering_point_id',cc.metering_point_id)
        from public.customer_contracts cc
        join public.customers c on c.id=cc.customer_id
        left join public.customer_sites s on s.id=coalesce(cc.customer_site_id,cc.site_id)
        left join public.metering_points mp on mp.id=cc.metering_point_id
        where (cc.company_id is distinct from c.company_id or (s.id is not null and cc.company_id is distinct from s.company_id) or (mp.id is not null and cc.company_id is distinct from mp.company_id))
          and (p_company_id is null or cc.company_id=p_company_id or c.company_id=p_company_id or s.company_id=p_company_id or mp.company_id=p_company_id)
        union all
        select coalesce(sw.company_id,c.company_id),'supplier_switch_request',sw.id,
               'Supplier switch relation disagrees with customer/site/metering point/contract tenant.',
               jsonb_build_object('switch_company_id',sw.company_id,'customer_company_id',c.company_id,'site_company_id',s.company_id,'meter_company_id',mp.company_id,'contract_company_id',cc.company_id,'customer_id',sw.customer_id,'site_id',sw.site_id,'metering_point_id',sw.metering_point_id)
        from public.supplier_switch_requests sw
        join public.customers c on c.id=sw.customer_id
        join public.customer_sites s on s.id=sw.site_id
        join public.metering_points mp on mp.id=sw.metering_point_id
        left join public.customer_contracts cc on cc.id=coalesce(sw.customer_contract_id,sw.contract_id)
        where (sw.company_id is distinct from c.company_id or sw.company_id is distinct from s.company_id or sw.company_id is distinct from mp.company_id or (cc.id is not null and sw.company_id is distinct from cc.company_id) or s.customer_id is distinct from sw.customer_id or (mp.customer_id is not null and mp.customer_id is distinct from sw.customer_id))
          and (p_company_id is null or sw.company_id=p_company_id or c.company_id=p_company_id or s.company_id=p_company_id or mp.company_id=p_company_id or cc.company_id=p_company_id)
      ) x
      join public.tenant_integrity_rule_registry r on r.rule_key='OPS-001' and r.is_enabled;

      -- tenant_integrity_outbound_schema_safe
      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'OUTBOUND-001',coalesce(o.company_id,c.company_id), 'outbound_request',o.id,r.severity,r.title,
             'Outbound request tenant disagrees with one or more linked business entities.',
             md5('OUTBOUND-001:'||o.id::text),
             jsonb_build_object('outbound_company_id',o.company_id,'customer_company_id',c.company_id,'site_company_id',s.company_id,'meter_company_id',mp.company_id,'customer_id',o.customer_id,'site_id',coalesce(o.customer_site_id,o.site_id),'metering_point_id',o.metering_point_id)
      from public.outbound_requests o
      join public.customers c on c.id=o.customer_id
      left join public.customer_sites s on s.id=coalesce(o.customer_site_id,o.site_id)
      left join public.metering_points mp on mp.id=o.metering_point_id
      join public.tenant_integrity_rule_registry r on r.rule_key='OUTBOUND-001' and r.is_enabled
      where (
          o.company_id is distinct from c.company_id
          or (s.id is not null and o.company_id is distinct from s.company_id)
          or (mp.id is not null and o.company_id is distinct from mp.company_id)
          or (mp.id is not null and mp.customer_id is not null and o.customer_id is distinct from mp.customer_id)
          or (o.customer_site_id is not null and o.site_id is not null and o.customer_site_id<>o.site_id)
        )
        and (p_company_id is null or o.company_id=p_company_id or c.company_id=p_company_id or s.company_id=p_company_id or mp.company_id=p_company_id);
    end if;

    if v_scope in ('all','access') then
      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'ACCESS-001',cm.company_id,'company_membership',cm.id,r.severity,r.title,
             'Active membership does not resolve to an active user profile.',md5('ACCESS-001:'||cm.id::text),
             jsonb_build_object('user_id',cm.user_id,'membership_status',cm.status,'membership_is_active',cm.is_active,'profile_status',up.user_status)
      from public.company_memberships cm
      left join public.user_profiles up on up.id=cm.user_id
      join public.tenant_integrity_rule_registry r on r.rule_key='ACCESS-001' and r.is_enabled
      where cm.status='active' and coalesce(cm.is_active,true)=true
        and (up.id is null or up.user_status<>'active')
        and (p_company_id is null or cm.company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'ACCESS-002',cm.company_id,'company_membership',cm.id,r.severity,r.title,
             'membership_role does not match canonical role_key mapping.',md5('ACCESS-002:'||cm.id::text),
             jsonb_build_object('user_id',cm.user_id,'role_key',cm.role_key,'membership_role',cm.membership_role,'expected_membership_role',m.membership_role)
      from public.company_memberships cm
      left join public.canonical_tenant_access_role_mapping m on m.role_key=lower(cm.role_key)
      join public.tenant_integrity_rule_registry r on r.rule_key='ACCESS-002' and r.is_enabled
      where cm.status='active' and coalesce(cm.is_active,true)=true
        and (cm.role_key is null or m.role_key is null or lower(cm.membership_role)<>lower(m.membership_role))
        and (p_company_id is null or cm.company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'ACCESS-003',cm.company_id,'company_membership',cm.id,r.severity,r.title,
             'Active membership lacks a matching active tenant RBAC role.',md5('ACCESS-003:'||cm.id::text),
             jsonb_build_object('user_id',cm.user_id,'role_key',cm.role_key,'membership_role',cm.membership_role)
      from public.company_memberships cm
      join public.tenant_integrity_rule_registry r on r.rule_key='ACCESS-003' and r.is_enabled
      where cm.status='active' and coalesce(cm.is_active,true)=true
        and not exists (
          select 1 from public.user_roles ur
          join public.roles rr on rr.id=ur.role_id
          where ur.company_id=cm.company_id and ur.user_id=cm.user_id
            and ur.status='active' and coalesce(ur.is_active,true)=true
            and lower(coalesce(rr.key,rr.name,ur.role,''))=lower(coalesce(cm.role_key,''))
        )
        and (p_company_id is null or cm.company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'ACCESS-004',up.active_company_id,'user_profile',up.id,r.severity,r.title,
             'active_company_id points to a tenant without an active membership.',md5('ACCESS-004:'||up.id::text||':'||up.active_company_id::text),
             jsonb_build_object('user_id',up.id,'active_company_id',up.active_company_id,'profile_status',up.user_status)
      from public.user_profiles up
      join public.tenant_integrity_rule_registry r on r.rule_key='ACCESS-004' and r.is_enabled
      where up.active_company_id is not null
        and not exists (
          select 1 from public.company_memberships cm
          where cm.company_id=up.active_company_id and cm.user_id=up.id
            and cm.status='active' and coalesce(cm.is_active,true)=true
        )
        and (p_company_id is null or up.active_company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'ACCESS-005',ci.company_id,'company_invitation',ci.id,r.severity,r.title,
             'Accepted invitation has no membership row for the invited tenant/user.',md5('ACCESS-005:'||ci.id::text),
             jsonb_build_object('invited_user_id',ci.invited_user_id,'invitation_status',ci.status,'role_key',ci.role_key,'membership_role',ci.membership_role)
      from public.company_invitations ci
      join public.tenant_integrity_rule_registry r on r.rule_key='ACCESS-005' and r.is_enabled
      where ci.status='accepted'
        and (ci.invited_user_id is null or not exists(
          select 1 from public.company_memberships cm where cm.company_id=ci.company_id and cm.user_id=ci.invited_user_id
        ))
        and (p_company_id is null or ci.company_id=p_company_id);
    end if;

    if v_scope in ('all','ediel') then
      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-001',coalesce(em.company_id,c.company_id,s.company_id,mp.company_id,o.company_id,sw.company_id),
             'ediel_message',em.id,r.severity,r.title,
             'Outbound Ediel message tenant disagrees with one or more linked business entities.',md5('EDIEL-001:'||em.id::text),
             jsonb_build_object('message_company_id',em.company_id,'customer_company_id',c.company_id,'site_company_id',s.company_id,'meter_company_id',mp.company_id,'outbound_company_id',o.company_id,'switch_company_id',sw.company_id,'status',em.status,'environment',em.environment)
      from public.ediel_messages em
      left join public.customers c on c.id=em.customer_id
      left join public.customer_sites s on s.id=em.site_id
      left join public.metering_points mp on mp.id=em.metering_point_id
      left join public.outbound_requests o on o.id=em.outbound_request_id
      left join public.supplier_switch_requests sw on sw.id=em.switch_request_id
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-001' and r.is_enabled
      where em.direction='outbound' and em.status<>'draft'
        and (
          (c.id is not null and em.company_id is distinct from c.company_id)
          or (s.id is not null and em.company_id is distinct from s.company_id)
          or (mp.id is not null and em.company_id is distinct from mp.company_id)
          or (o.id is not null and em.company_id is distinct from o.company_id)
          or (sw.id is not null and em.company_id is distinct from sw.company_id)
        )
        and (p_company_id is null or em.company_id=p_company_id or c.company_id=p_company_id or s.company_id=p_company_id or mp.company_id=p_company_id or o.company_id=p_company_id or sw.company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-002',coalesce(em.company_id,em.resolved_company_id),'ediel_message',em.id,r.severity,r.title,
             'Ediel message company_id disagrees with resolved_company_id.',md5('EDIEL-002:'||em.id::text),
             jsonb_build_object('company_id',em.company_id,'resolved_company_id',em.resolved_company_id,'direction',em.direction,'status',em.status,'tenant_resolution_status',em.tenant_resolution_status)
      from public.ediel_messages em
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-002' and r.is_enabled
      where em.company_id is not null and em.resolved_company_id is not null and em.company_id<>em.resolved_company_id
        and (p_company_id is null or em.company_id=p_company_id or em.resolved_company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-003',coalesce(eo.company_id,em.company_id),'ediel_outbox',eo.id,r.severity,r.title,
             'Sendable Ediel outbox tenant disagrees with its Ediel message tenant.',md5('EDIEL-003:'||eo.id::text),
             jsonb_build_object('outbox_company_id',eo.company_id,'message_company_id',em.company_id,'ediel_message_id',em.id,'outbox_status',eo.status,'environment',eo.environment)
      from public.ediel_outbox eo
      join public.ediel_messages em on em.id=eo.ediel_message_id
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-003' and r.is_enabled
      where eo.status in ('prepared','queued','sending','sent','delivery_uncertain')
        and eo.company_id is distinct from em.company_id
        and (p_company_id is null or eo.company_id=p_company_id or em.company_id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-004',c.id,'ediel_outbox',eo.id,r.severity,r.title,
             'Tenant is blocked/frozen but production Ediel work remains sendable.',md5('EDIEL-004:'||eo.id::text),
             jsonb_build_object('company_status',c.status,'outbound_frozen',c.outbound_frozen,'ediel_production_status',c.ediel_production_status,'outbox_status',eo.status,'environment',eo.environment,'ediel_message_id',eo.ediel_message_id)
      from public.ediel_outbox eo
      join public.companies c on c.id=eo.company_id
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-004' and r.is_enabled
      where eo.environment='production' and eo.status in ('prepared','queued','sending')
        and (c.status in ('paused','suspended','archived','pending_deletion','closed','deleted_test_only') or coalesce(c.outbound_frozen,false)=true or c.ediel_production_status in ('paused','blocked'))
        and (p_company_id is null or c.id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-005',c.id,'company',c.id,r.severity,r.title,
             'Production Ediel is enabled/live but no active valid production actor setting exists.',md5('EDIEL-005:'||c.id::text),
             jsonb_build_object('ediel_production_enabled',c.ediel_production_enabled,'live_ediel_enabled',c.live_ediel_enabled,'ediel_production_status',c.ediel_production_status)
      from public.companies c
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-005' and r.is_enabled
      where (coalesce(c.ediel_production_enabled,false)=true or coalesce(c.live_ediel_enabled,false)=true or c.ediel_production_status='live')
        and not exists (
          select 1 from public.ediel_actor_settings eas
          where eas.company_id=c.id and eas.environment='production' and eas.is_active=true
            and (eas.valid_from is null or eas.valid_from<=current_date)
            and (eas.valid_to is null or eas.valid_to>=current_date)
        )
        and (p_company_id is null or c.id=p_company_id);

      insert into public.tenant_integrity_findings
        (run_id,rule_key,company_id,entity_type,entity_id,severity,title,message,fingerprint,evidence)
      select v_run_id,'EDIEL-006',tep.company_id,'tenant_ediel_profile',min(tep.id::text)::uuid,r.severity,r.title,
             'More than one currently active tenant Ediel profile overlaps for the same tenant/environment/market.',
             md5('EDIEL-006:'||tep.company_id::text||':'||tep.environment||':'||tep.market),
             jsonb_build_object('environment',tep.environment,'market',tep.market,'active_profile_count',count(*),'profile_ids',jsonb_agg(tep.id order by tep.valid_from,tep.id))
      from public.tenant_ediel_profiles tep
      join public.tenant_integrity_rule_registry r on r.rule_key='EDIEL-006' and r.is_enabled
      where tep.is_enabled=true and tep.valid_from<=now() and (tep.valid_to is null or tep.valid_to>now())
        and (p_company_id is null or tep.company_id=p_company_id)
      group by tep.company_id,tep.environment,tep.market,r.severity,r.title
      having count(*)>1;
    end if;

    select count(*)::integer,
           count(*) filter(where severity='critical')::integer,
           count(*) filter(where severity='high')::integer,
           count(*) filter(where severity='medium')::integer,
           count(*) filter(where severity='low')::integer,
           count(*) filter(where severity='info')::integer
      into v_total,v_critical,v_high,v_medium,v_low,v_info
    from public.tenant_integrity_findings where run_id=v_run_id;

    update public.tenant_integrity_audit_runs
    set status='completed',finished_at=now(),finding_count=v_total,critical_count=v_critical,high_count=v_high,
        medium_count=v_medium,low_count=v_low,info_count=v_info,
        metadata=metadata||jsonb_build_object('completed_at',now())
    where id=v_run_id;

    return jsonb_build_object('ok',true,'run_id',v_run_id,'company_id',p_company_id,'scope',v_scope,
      'finding_count',v_total,'critical_count',v_critical,'high_count',v_high,'medium_count',v_medium,'low_count',v_low,'info_count',v_info);
  exception when others then
    update public.tenant_integrity_audit_runs
    set status='failed',finished_at=now(),error_message=left(sqlerrm,2000)
    where id=v_run_id;
    return jsonb_build_object('ok',false,'run_id',v_run_id,'company_id',p_company_id,'scope',v_scope,'error',sqlerrm);
  end;
end
$$;

--
-- Name: FUNCTION run_tenant_integrity_audit(p_company_id uuid, p_scope text, p_requested_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_tenant_integrity_audit(p_company_id uuid, p_scope text, p_requested_by uuid) IS 'Service-role-only cross-table tenant/access/operations/Ediel integrity auditor. Audit-only: never mutates business data.';

--
-- Name: set_updated_at_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

--
-- Name: store_website_public_contract_snapshot(text, text, text, bigint, text, text, text, text, jsonb, integer, integer, integer, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_website_public_contract_snapshot(p_cache_key text, p_tenant_reference text, p_customer_type text, p_publication_revision bigint, p_contract_version text, p_parser_version text, p_schema_sha256 text, p_etag text, p_snapshot jsonb, p_accepted_count integer, p_blocked_count integer, p_upstream_count integer, p_feed_state text, p_empty_feed_authorization jsonb, p_fetched_at timestamp with time zone) RETURNS TABLE(result text, stored boolean, empty_authorized boolean, stored_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_existing public.website_public_contract_snapshots%rowtype;
  v_canonical_revision bigint;
  v_canonical_token text;
  v_canonical_changed_at timestamptz;
  v_existing_found boolean := false;
  v_empty_authorized boolean := false;
  v_authorization_revision bigint;
  v_authorization_reason text;
begin
  if
    nullif(trim(p_cache_key), '') is null
    or p_tenant_reference !~ '^tenant_[0-9a-f]{36}$'
    or p_customer_type not in ('all', 'private', 'business')
    or p_publication_revision is null
    or p_publication_revision < 0
    or nullif(trim(p_contract_version), '') is null
    or nullif(trim(p_parser_version), '') is null
    or p_schema_sha256 !~ '^[0-9a-f]{64}$'
    or p_snapshot is null
    or jsonb_typeof(p_snapshot) <> 'object'
    or p_snapshot ->> 'tenant_reference' is distinct from p_tenant_reference
    or p_snapshot ->> 'contract_version' is distinct from p_contract_version
    or p_snapshot -> 'publication_revision' is distinct from to_jsonb(p_publication_revision)
    or p_snapshot ->> 'feed_state' is distinct from p_feed_state
    or (
      p_empty_feed_authorization is null
      and coalesce(p_snapshot -> 'empty_feed_authorization', 'null'::jsonb) <> 'null'::jsonb
    )
    or (
      p_empty_feed_authorization is not null
      and p_snapshot -> 'empty_feed_authorization' is distinct from p_empty_feed_authorization
    )
    or p_accepted_count is null
    or p_blocked_count is null
    or p_upstream_count is null
    or p_accepted_count < 0
    or p_blocked_count < 0
    or p_upstream_count <> p_accepted_count + p_blocked_count
    or p_fetched_at is null
  then
    raise exception using errcode = '22023',
      message = 'CANONICAL_WEBSITE_PUBLIC_CONTRACT_SNAPSHOT_ARGUMENTS_INVALID';
  end if;

  if
    jsonb_typeof(p_snapshot -> 'contracts') <> 'array'
    or jsonb_typeof(p_snapshot -> 'blocked_contracts') <> 'array'
    or jsonb_array_length(p_snapshot -> 'contracts') <> p_accepted_count
    or jsonb_array_length(p_snapshot -> 'blocked_contracts') <> p_blocked_count
  then
    raise exception using errcode = '22023',
      message = 'CANONICAL_WEBSITE_PUBLIC_CONTRACT_SNAPSHOT_COUNTS_INVALID';
  end if;

  if p_feed_state = 'contracts_present' then
    if p_accepted_count <= 0 or p_upstream_count <= 0 or p_empty_feed_authorization is not null then
      raise exception using errcode = '22023',
        message = 'CONTRACTS_PRESENT_SNAPSHOT_INVALID';
    end if;
  elsif p_feed_state = 'canonical_empty' then
    if
      p_accepted_count <> 0
      or p_blocked_count <> 0
      or p_upstream_count <> 0
      or jsonb_typeof(p_empty_feed_authorization) <> 'object'
      or p_empty_feed_authorization -> 'authorized' is distinct from 'true'::jsonb
      or p_empty_feed_authorization ->> 'canonical_source' is distinct from 'canonical_public_contract_delivery_readiness_v'
      or jsonb_typeof(p_empty_feed_authorization -> 'affected_offer_references') <> 'array'
      or jsonb_typeof(p_empty_feed_authorization -> 'blockers') <> 'array'
      or jsonb_path_exists(p_empty_feed_authorization, '$.affected_offer_references[*] ? (@.type() != "string")')
      or jsonb_path_exists(p_empty_feed_authorization, '$.blockers[*] ? (@.type() != "string")')
      or (p_empty_feed_authorization - array[
        'authorized', 'reason', 'publication_revision', 'canonical_source',
        'affected_offer_references', 'blockers'
      ]::text[]) <> '{}'::jsonb
    then
      raise exception using errcode = '22023',
        message = 'CANONICAL_EMPTY_SNAPSHOT_PROOF_INVALID';
    end if;

    begin
      v_authorization_revision := (p_empty_feed_authorization ->> 'publication_revision')::bigint;
    exception when others then
      raise exception using errcode = '22023',
        message = 'CANONICAL_EMPTY_SNAPSHOT_REVISION_INVALID';
    end;
    v_authorization_reason := p_empty_feed_authorization ->> 'reason';
    if
      v_authorization_revision is distinct from p_publication_revision
      or v_authorization_reason not in (
        'no_canonical_publications',
        'canonical_unpublished_or_archived',
        'publication_validity_ended',
        'canonical_no_visible_contracts'
      )
    then
      raise exception using errcode = '22023',
        message = 'CANONICAL_EMPTY_SNAPSHOT_PROOF_MISMATCH';
    end if;
    v_empty_authorized := true;
  else
    raise exception using errcode = '22023',
      message = 'CANONICAL_PUBLIC_CONTRACT_FEED_STATE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_cache_key, 0));

  execute $canonical$
    select r.revision, r.revision_token::text, r.updated_at
    from public.contract_publication_revisions r
    join public.companies c on c.id = r.company_id
    where c.external_tenant_reference = $1
      and r.channel = 'website'
    limit 1
  $canonical$
    into v_canonical_revision, v_canonical_token, v_canonical_changed_at
    using p_tenant_reference;

  if v_canonical_revision is not null then
    insert into public.ops_publication_state (
      tenant_reference, channel, publication_revision, revision_token,
      changed_at, updated_at
    ) values (
      p_tenant_reference, 'website', v_canonical_revision,
      v_canonical_token, v_canonical_changed_at, now()
    )
    on conflict (tenant_reference, channel)
    do update set
      publication_revision = excluded.publication_revision,
      revision_token = excluded.revision_token,
      changed_at = excluded.changed_at,
      updated_at = now();
  end if;

  if v_canonical_revision is null then
    select publication_revision
      into v_canonical_revision
      from public.ops_publication_state
     where tenant_reference = p_tenant_reference
       and channel = 'website'
     for share;
  end if;

  if v_canonical_revision is null then
    return query select
      'rejected_publication_state_missing'::text,
      false,
      false,
      null::bigint;
    return;
  end if;

  if p_publication_revision <> v_canonical_revision then
    return query select
      case
        when p_publication_revision < v_canonical_revision
          then 'rejected_older_than_publication_state'
        else 'rejected_ahead_of_publication_state'
      end::text,
      false,
      false,
      v_canonical_revision;
    return;
  end if;

  select *
    into v_existing
    from public.website_public_contract_snapshots
   where cache_key = p_cache_key
   for update;
  v_existing_found := found;

  if v_existing_found and (
    v_existing.tenant_reference <> p_tenant_reference
    or v_existing.customer_type <> p_customer_type
    or v_existing.channel <> 'website'
  ) then
    raise exception using errcode = '23505',
      message = 'PUBLIC_CONTRACT_SNAPSHOT_CACHE_KEY_TENANT_CONFLICT';
  end if;

  if v_existing_found
     and v_existing.publication_revision > p_publication_revision then
    return query select
      'rejected_older_than_stored_snapshot'::text,
      false,
      false,
      v_existing.publication_revision;
    return;
  end if;

  insert into public.website_public_contract_snapshots (
    cache_key, tenant_reference, channel, customer_type,
    publication_revision, contract_version, parser_version, schema_sha256,
    etag, snapshot, accepted_count, blocked_count, upstream_count,
    feed_state, empty_feed_authorization, fetched_at, updated_at
  ) values (
    p_cache_key, p_tenant_reference, 'website', p_customer_type,
    p_publication_revision, p_contract_version, p_parser_version,
    p_schema_sha256, p_etag, p_snapshot, p_accepted_count,
    p_blocked_count, p_upstream_count, p_feed_state,
    p_empty_feed_authorization, p_fetched_at, now()
  )
  on conflict (cache_key)
  do update set
    tenant_reference = excluded.tenant_reference,
    channel = excluded.channel,
    customer_type = excluded.customer_type,
    publication_revision = excluded.publication_revision,
    contract_version = excluded.contract_version,
    parser_version = excluded.parser_version,
    schema_sha256 = excluded.schema_sha256,
    etag = excluded.etag,
    snapshot = excluded.snapshot,
    accepted_count = excluded.accepted_count,
    blocked_count = excluded.blocked_count,
    upstream_count = excluded.upstream_count,
    feed_state = excluded.feed_state,
    empty_feed_authorization = excluded.empty_feed_authorization,
    fetched_at = excluded.fetched_at,
    updated_at = now();

  return query select
    case when p_feed_state = 'canonical_empty'
      then 'stored_canonical_empty'
      else 'stored'
    end::text,
    true,
    v_empty_authorized,
    p_publication_revision;
end;
$_$;

--
-- Name: applied_receipts; Type: TABLE; Schema: gridex_ack_authority; Owner: -
--

CREATE TABLE gridex_ack_authority.applied_receipts (
    ack_message_id uuid NOT NULL,
    result jsonb NOT NULL,
    captured_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT applied_receipts_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);

ALTER TABLE ONLY gridex_ack_authority.applied_receipts FORCE ROW LEVEL SECURITY;

--
-- Name: prodat_physical_receipts; Type: TABLE; Schema: gridex_ack_authority; Owner: -
--

CREATE TABLE gridex_ack_authority.prodat_physical_receipts (
    ack_message_id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    ack_payload_hash text NOT NULL,
    source_payload_hash text NOT NULL,
    scopes jsonb NOT NULL,
    source_projection_version jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT prodat_physical_receipts_scopes_check CHECK ((jsonb_typeof(scopes) = 'array'::text)),
    CONSTRAINT prodat_physical_receipts_source_projection_version_check CHECK ((jsonb_typeof(source_projection_version) = 'object'::text))
);

ALTER TABLE ONLY gridex_ack_authority.prodat_physical_receipts FORCE ROW LEVEL SECURITY;

--
-- Name: scope_outcomes; Type: TABLE; Schema: gridex_ack_authority; Owner: -
--

CREATE TABLE gridex_ack_authority.scope_outcomes (
    source_message_id uuid NOT NULL,
    ack_family text NOT NULL,
    ack_scope text NOT NULL,
    source_reference text NOT NULL,
    ack_message_id uuid NOT NULL,
    outcome text NOT NULL,
    CONSTRAINT scope_outcomes_outcome_check CHECK ((outcome = ANY (ARRAY['positive'::text, 'negative'::text])))
);

ALTER TABLE ONLY gridex_ack_authority.scope_outcomes FORCE ROW LEVEL SECURITY;

--
-- Name: source_correlations; Type: TABLE; Schema: gridex_ack_authority; Owner: -
--

CREATE TABLE gridex_ack_authority.source_correlations (
    ack_message_id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    ack_payload_hash text NOT NULL,
    source_payload_hash text NOT NULL,
    canonical_assessment_id uuid NOT NULL,
    ack_family text NOT NULL,
    ack_outcome text NOT NULL,
    ack_scope text NOT NULL,
    acknowledged_references jsonb NOT NULL,
    scope_outcomes jsonb NOT NULL,
    correlated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    actor_user_id uuid NOT NULL,
    CONSTRAINT source_correlations_ack_family_check CHECK ((ack_family = ANY (ARRAY['CONTRL'::text, 'APERAK'::text, 'UTILTS_ERR'::text]))),
    CONSTRAINT source_correlations_ack_outcome_check CHECK ((ack_outcome = ANY (ARRAY['positive'::text, 'negative'::text]))),
    CONSTRAINT source_correlations_ack_scope_check CHECK ((ack_scope = ANY (ARRAY['interchange'::text, 'message'::text, 'transaction'::text, 'object'::text]))),
    CONSTRAINT source_correlations_acknowledged_references_check CHECK ((jsonb_typeof(acknowledged_references) = 'array'::text)),
    CONSTRAINT source_correlations_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT source_correlations_scope_outcomes_check CHECK ((jsonb_typeof(scope_outcomes) = 'array'::text))
);

ALTER TABLE ONLY gridex_ack_authority.source_correlations FORCE ROW LEVEL SECURITY;

--
-- Name: decisions; Type: TABLE; Schema: gridex_ai_processing; Owner: -
--

CREATE TABLE gridex_ai_processing.decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    list_type text NOT NULL,
    purpose text NOT NULL,
    revision bigint NOT NULL,
    previous_decision_id uuid,
    gdpr_basis text NOT NULL,
    retention_days integer NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone,
    source_reference text NOT NULL,
    source_sha256 text NOT NULL,
    decision_owner_registry_id uuid NOT NULL,
    decision_owner_registry_version text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT decisions_check CHECK ((valid_until > valid_from)),
    CONSTRAINT decisions_decision_owner_registry_version_check CHECK (((length(btrim(decision_owner_registry_version)) >= 1) AND (length(btrim(decision_owner_registry_version)) <= 200))),
    CONSTRAINT decisions_gdpr_basis_check CHECK (((length(btrim(gdpr_basis)) >= 1) AND (length(btrim(gdpr_basis)) <= 2000))),
    CONSTRAINT decisions_list_type_check CHECK ((list_type = ANY (ARRAY['AI'::text, 'BI'::text]))),
    CONSTRAINT decisions_purpose_check CHECK ((purpose = ANY (ARRAY['ediel_list_reconciliation'::text, 'ediel_list_export'::text]))),
