--
-- Name: brp_declaration_agreement_originals; Type: VIEW; Schema: gridex_ediel_retention; Owner: -
--

CREATE VIEW gridex_ediel_retention.brp_declaration_agreement_originals WITH (security_barrier='true') AS
 SELECT id,
    company_id,
    agreement_original AS document_bytes,
    agreement_sha256 AS document_hash,
    NULL::bigint AS document_byte_length,
    NULL::timestamp with time zone AS document_purged_at,
    (to_jsonb(q.*) - ARRAY['agreement_original'::text, 'source_original'::text]) AS source_metadata
   FROM gridex_brp_sources.contract_declarations q;

--
-- Name: brp_declaration_source_originals; Type: VIEW; Schema: gridex_ediel_retention; Owner: -
