   FROM gridex_brp_sources.contract_declarations q;

--
-- Name: certification_classification_originals; Type: VIEW; Schema: gridex_ediel_retention; Owner: -
--

CREATE VIEW gridex_ediel_retention.certification_classification_originals WITH (security_barrier='true') AS
 SELECT id,
    company_id,
    classification_original AS document_bytes,
    classification_sha256 AS document_hash,
    NULL::bigint AS document_byte_length,
    NULL::timestamp with time zone AS document_purged_at,
    (to_jsonb(q.*) - ARRAY['workbook_original'::text, 'classification_original'::text]) AS source_metadata
   FROM gridex_customer_life_events.certification_classifications q;

--
-- Name: certification_revocation_originals; Type: VIEW; Schema: gridex_ediel_retention; Owner: -
--

CREATE VIEW gridex_ediel_retention.certification_revocation_originals WITH (security_barrier='true') AS
 SELECT q.id,
    q.company_id,
    r.source_original AS document_bytes,
    r.source_sha256 AS document_hash,
    NULL::bigint AS document_byte_length,
    NULL::timestamp with time zone AS document_purged_at,
    jsonb_build_object('classification', (to_jsonb(q.*) - ARRAY['workbook_original'::text, 'classification_original'::text]), 'revocation', (to_jsonb(r.*) - 'source_original'::text)) AS source_metadata
   FROM (gridex_customer_life_events.certification_classification_revocations r
     JOIN gridex_customer_life_events.certification_classifications q ON ((q.id = r.declaration_id)));

