-- Name: contract_request_declarations; Type: TABLE; Schema: gridex_metering_method_changes; Owner: -
--

CREATE TABLE gridex_metering_method_changes.contract_request_declarations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    previous_declaration_id uuid,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    contract_id uuid NOT NULL,
    contract_revision text NOT NULL,
    protected_contract_hash text NOT NULL,
    customer_id uuid NOT NULL,
    site_id uuid NOT NULL,
    metering_point_id uuid NOT NULL,
    legal_actor_id uuid NOT NULL,
    legal_sender_id text NOT NULL,
    legal_receiver_id text NOT NULL,
    point_id text NOT NULL,
    identity_agency text NOT NULL,
    grid_area_code text NOT NULL,
    requested_method text NOT NULL,
    agreement_original bytea,
    agreement_sha256 text NOT NULL,
    source_reference text NOT NULL,
    source_version text NOT NULL,
    source_original bytea,
    source_sha256 text NOT NULL,
    approved_by uuid NOT NULL,
    approved_at timestamp with time zone NOT NULL,
    CONSTRAINT contract_request_declarations_agreement_original_check CHECK (((octet_length(agreement_original) >= 1) AND (octet_length(agreement_original) <= 10485760))),
    CONSTRAINT contract_request_declarations_check CHECK ((agreement_sha256 = encode(sha256(agreement_original), 'hex'::text))),
    CONSTRAINT contract_request_declarations_check1 CHECK ((source_sha256 = encode(sha256(source_original), 'hex'::text))),
    CONSTRAINT contract_request_declarations_contract_revision_check CHECK ((length(contract_revision) > 0)),
    CONSTRAINT contract_request_declarations_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT contract_request_declarations_identity_agency_check CHECK ((identity_agency = ANY (ARRAY['9'::text, '89'::text]))),
    CONSTRAINT contract_request_declarations_protected_contract_hash_check CHECK ((protected_contract_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT contract_request_declarations_requested_method_check CHECK (gridex_metering_method_changes.requested_method_supported_v1(requested_method)),
    CONSTRAINT contract_request_declarations_source_original_check CHECK (((octet_length(source_original) >= 1) AND (octet_length(source_original) <= 10485760))),
    CONSTRAINT contract_request_declarations_source_reference_check CHECK ((length(source_reference) > 0)),
    CONSTRAINT contract_request_declarations_source_version_check CHECK ((length(source_version) > 0))
);

ALTER TABLE ONLY gridex_metering_method_changes.contract_request_declarations FORCE ROW LEVEL SECURITY;

