    CONSTRAINT events_source_reference_check CHECK ((length(source_reference) > 0)),
    CONSTRAINT events_source_version_check CHECK ((length(source_version) > 0)),
    CONSTRAINT events_subtype_check CHECK ((subtype = ANY (ARRAY['F'::text, 'G'::text]))),
