    source_field text NOT NULL,
    attachment_id uuid,
    source_sha256 text NOT NULL,
    report jsonb NOT NULL,
    report_sha256 text NOT NULL,
    observed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    authorizes_resend boolean DEFAULT false NOT NULL,
    delivery_proven boolean DEFAULT false NOT NULL,
    CONSTRAINT dsn_observations_authorizes_resend_check CHECK ((NOT authorizes_resend)),
