--
-- Name: permission_effect_transitions_v1; Type: VIEW; Schema: gridex_received_sources; Owner: -
--

CREATE VIEW gridex_received_sources.permission_effect_transitions_v1 AS
 SELECT permission_transitions.source_message_id,
    permission_transitions.company_id,
    permission_transitions.permission_id,
    permission_transitions.payload_hash,
    permission_transitions.previous_state,
    permission_transitions.previous_sites,
    permission_transitions.resulting_state,
    permission_transitions.applied_at,
    permission_transitions.actor_user_id,
    permission_transitions.resulting_sites,
    permission_transitions.qualified_original_message_id,
    permission_transitions.qualified_expected_message_code
   FROM gridex_received_sources.permission_transitions
UNION ALL
 SELECT permission_effect_receipts.source_message_id,
    permission_effect_receipts.company_id,
    permission_effect_receipts.permission_id,
    permission_effect_receipts.payload_hash,
    permission_effect_receipts.previous_state,
    permission_effect_receipts.previous_sites,
    permission_effect_receipts.resulting_state,
    permission_effect_receipts.applied_at,
    permission_effect_receipts.actor_user_id,
    permission_effect_receipts.resulting_sites,
    permission_effect_receipts.qualified_original_message_id,
    permission_effect_receipts.qualified_expected_message_code
   FROM gridex_received_sources.permission_effect_receipts;

