    CONSTRAINT received_source_hash_check CHECK ((((raw_payload IS NULL) AND (payload_hash IS NULL) AND (retention_purged_at IS NULL)) OR ((raw_payload IS NOT NULL) AND (payload_hash = encode(sha256(convert_to(raw_payload, 'UTF8'::name)), 'hex'::text)) AND (retention_purged_at IS NULL)) OR ((raw_payload IS NULL) AND (payload_hash ~ '^[a-f0-9]{64}$'::text) AND (retention_byte_length > 0) AND (retention_purged_at IS NOT NULL)))),
    CONSTRAINT sources_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT sources_origin_check CHECK ((origin = 'database_insert'::text))
);

ALTER TABLE ONLY gridex_received_sources.sources FORCE ROW LEVEL SECURITY;

