--
-- Name: actor_electricity_scope_classification_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actor_electricity_scope_classification_v WITH (security_invoker='true') AS
 WITH role_summary AS (
         SELECT r.actor_id,
            array_agg(DISTINCT lower(r.actor_role) ORDER BY (lower(r.actor_role))) AS roles,
            bool_or((lower(r.actor_role) = ANY (ARRAY['grid_owner'::text, 'network_owner'::text, 'netowner'::text, 'dso'::text, 'distribution_system_operator'::text, 'nätägare'::text, 'elnatsforetag'::text, 'elnätsföretag'::text]))) AS has_grid_owner_role,
            bool_or((lower(r.actor_role) = ANY (ARRAY['electricity_supplier'::text, 'power_supplier'::text, 'supplier'::text, 'elhandelsbolag'::text, 'elleverantor'::text, 'elleverantör'::text]))) AS has_electricity_supplier_role,
            bool_or((lower(r.actor_role) = ANY (ARRAY['system_supplier'::text, 'systemleverantor'::text, 'systemleverantör'::text]))) AS has_system_supplier_role,
            bool_or((lower(r.actor_role) = ANY (ARRAY['energy_service_company'::text, 'energyservicecompany'::text, 'esp'::text, 'asp'::text]))) AS has_energy_service_role,
            bool_or((lower(r.actor_role) = ANY (ARRAY['balance_responsible'::text, 'balanceresponsible'::text, 'balance_responsible_party'::text, 'balanceresponsibleparty'::text, 'brp'::text, 'bsp'::text, 'balansansvarig'::text]))) AS has_balance_role,
            bool_or((lower(r.actor_role) = ANY (ARRAY['gas_grid_owner'::text, 'gas_owner'::text, 'gas_network_owner'::text, 'gas_distribution_system_operator'::text, 'gasnat'::text, 'gasnät'::text]))) AS has_gas_role
           FROM public.platform_actor_roles r
          WHERE (COALESCE(r.is_active, true) = true)
          GROUP BY r.actor_id
        ), actor_ids AS (
         SELECT i.actor_id,
            max(i.identifier_value) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text]))) AS ediel_id,
            max(i.identifier_value) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['orgno'::text, 'org_number'::text, 'orgnr'::text]))) AS org_number,
            max(i.identifier_value) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['eic'::text, 'eic_code'::text]))) AS eic
           FROM public.platform_actor_identifiers i
          GROUP BY i.actor_id
        ), route_scope AS (
         SELECT r.actor_id,
            bool_or(((upper(r.message_family) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (COALESCE(r.status, ''::text) = 'active'::text))) AS has_electricity_route,
            bool_or(((upper(COALESCE(r.subaddress, ''::text)) = 'GAS'::text) OR (upper(COALESCE(r.application_reference, ''::text)) ~~ '%GAS%'::text) OR (COALESCE((r.metadata ->> 'scope'::text), ''::text) = ANY (ARRAY['gas'::text, 'gas_grid'::text])))) AS has_gas_route
           FROM public.platform_actor_routes r
          GROUP BY r.actor_id
        ), classified AS (
         SELECT a.id AS platform_market_actor_id,
            a.name AS actor_name,
            a.legal_name,
            COALESCE(ai.org_number, a.org_number) AS org_number,
            ai.ediel_id,
            ai.eic,
            COALESCE(rs.roles, '{}'::text[]) AS roles,
            COALESCE(rs.has_grid_owner_role, false) AS has_grid_owner_role,
            COALESCE(rs.has_electricity_supplier_role, false) AS has_electricity_supplier_role,
            COALESCE(rs.has_system_supplier_role, false) AS has_system_supplier_role,
            COALESCE(rs.has_energy_service_role, false) AS has_energy_service_role,
            COALESCE(rs.has_balance_role, false) AS has_balance_role,
            (COALESCE(rs.has_gas_role, false) OR COALESCE(route_scope.has_gas_route, false) OR (lower(((COALESCE(a.name, ''::text) || ' '::text) || COALESCE(a.legal_name, ''::text))) ~ '(^|[^a-zåäö0-9])(gas|gasnät|gasnat)([^a-zåäö0-9]|$)'::text)) AS is_gas_actor,
            (lower(((COALESCE(a.name, ''::text) || ' '::text) || COALESCE(a.legal_name, ''::text))) ~ '(^|[^a-zåäö0-9])(dummy|test|testaktör|testaktor|testsystem)([^a-zåäö0-9]|$)'::text) AS is_dummy_or_test_actor,
            COALESCE(route_scope.has_electricity_route, false) AS has_electricity_route
           FROM (((public.platform_market_actors a
             LEFT JOIN role_summary rs ON ((rs.actor_id = a.id)))
             LEFT JOIN actor_ids ai ON ((ai.actor_id = a.id)))
             LEFT JOIN route_scope ON ((route_scope.actor_id = a.id)))
        )
 SELECT platform_market_actor_id,
    actor_name,
    legal_name,
    org_number,
    ediel_id,
    eic,
    roles,
    has_grid_owner_role,
    has_electricity_supplier_role,
    has_system_supplier_role,
    has_energy_service_role,
    has_balance_role,
    is_gas_actor,
    is_dummy_or_test_actor,
    has_electricity_route,
    (has_system_supplier_role AND (NOT has_grid_owner_role) AND (NOT has_electricity_supplier_role)) AS is_system_supplier_only,
    (has_grid_owner_role AND (NOT is_gas_actor) AND (NOT is_dummy_or_test_actor) AND (NOT (has_system_supplier_role AND (NOT has_grid_owner_role) AND (NOT has_electricity_supplier_role)))) AS is_electricity_grid_owner_scope,
        CASE
            WHEN is_dummy_or_test_actor THEN 'dummy_or_test_excluded'::text
            WHEN is_gas_actor THEN 'gas_grid_owner'::text
            WHEN has_grid_owner_role THEN 'electricity_grid_owner'::text
            WHEN has_electricity_supplier_role THEN 'electricity_supplier'::text
            WHEN has_system_supplier_role THEN 'system_supplier'::text
            WHEN has_energy_service_role THEN 'energy_service_company'::text
            WHEN has_balance_role THEN 'balance_responsible'::text
            ELSE 'other'::text
        END AS primary_role_group,
        CASE
            WHEN is_dummy_or_test_actor THEN 'excluded_from_electricity_scope'::text
            WHEN is_gas_actor THEN 'excluded_from_electricity_scope'::text
            WHEN has_grid_owner_role THEN 'in_electricity_supplier_switch_scope'::text
            ELSE 'separate_role_scope'::text
        END AS electricity_scope_status
   FROM classified c;

--
-- Name: VIEW actor_electricity_scope_classification_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.actor_electricity_scope_classification_v IS 'O6.4 role/scope classifier. Supplier switch uses only non-gas, non-test, electricity grid owners; other roles are dashboard scope only.';

--
-- Name: platform_actor_certificates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_actor_certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid,
    ediel_id text,
    environment text DEFAULT 'production'::text NOT NULL,
    certificate_type text DEFAULT 'smime'::text NOT NULL,
    purpose text DEFAULT 'encryption'::text NOT NULL,
    subject text,
    issuer text,
    serial_number text,
    fingerprint_sha256 text,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    status text DEFAULT 'unknown'::text NOT NULL,
    source text DEFAULT 'auto_readiness'::text NOT NULL,
    source_url text,
    raw_certificate_pem text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_checked_at timestamp with time zone,
    next_check_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_actor_certificates_certificate_type_check CHECK ((certificate_type = ANY (ARRAY['smime'::text, 'cms'::text, 'x509'::text, 'unknown'::text]))),
    CONSTRAINT platform_actor_certificates_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT platform_actor_certificates_purpose_check CHECK ((purpose = ANY (ARRAY['encryption'::text, 'signing'::text, 'transport'::text, 'unknown'::text]))),
    CONSTRAINT platform_actor_certificates_status_check CHECK ((status = ANY (ARRAY['valid'::text, 'expires_soon'::text, 'expired'::text, 'missing'::text, 'mismatch'::text, 'invalid'::text, 'unknown'::text])))
);

--
-- Name: actor_readiness_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actor_readiness_status WITH (security_invoker='true') AS
 WITH ids AS (
         SELECT platform_actor_identifiers.actor_id,
            max(platform_actor_identifiers.identifier_value) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text]))) AS ediel_id,
            bool_or(COALESCE(platform_actor_identifiers.is_verified, false)) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text]))) AS ediel_id_verified,
            max(platform_actor_identifiers.identifier_value) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['orgno'::text, 'org_number'::text, 'orgnr'::text]))) AS org_number,
            max(platform_actor_identifiers.identifier_value) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['eic'::text, 'eic_code'::text]))) AS eic
           FROM public.platform_actor_identifiers
          GROUP BY platform_actor_identifiers.actor_id
        ), roles AS (
         SELECT platform_actor_roles.actor_id,
            array_agg(DISTINCT lower(platform_actor_roles.actor_role) ORDER BY (lower(platform_actor_roles.actor_role))) AS roles,
            bool_or((lower(platform_actor_roles.actor_role) = ANY (ARRAY['grid_owner'::text, 'network_owner'::text, 'netowner'::text, 'dso'::text, 'distribution_system_operator'::text, 'nätägare'::text, 'elnatsforetag'::text, 'elnätsföretag'::text]))) AS has_grid_owner_role,
            bool_or((lower(platform_actor_roles.actor_role) = ANY (ARRAY['electricity_supplier'::text, 'power_supplier'::text, 'supplier'::text, 'elhandelsbolag'::text, 'balance_responsible'::text, 'balansansvarig'::text]))) AS has_supplier_role
           FROM public.platform_actor_roles
          WHERE (COALESCE(platform_actor_roles.is_active, true) = true)
          GROUP BY platform_actor_roles.actor_id
        ), routes AS (
         SELECT platform_actor_routes.actor_id,
            (count(*) FILTER (WHERE ((upper(platform_actor_routes.message_family) = 'PRODAT'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text))))::integer AS prodat_route_count,
            (count(*) FILTER (WHERE ((upper(platform_actor_routes.message_family) = 'UTILTS'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text))))::integer AS utilts_route_count,
            bool_or(((upper(platform_actor_routes.message_family) = 'PRODAT'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text) AND COALESCE(platform_actor_routes.is_verified, false))) AS has_prodat_route,
            bool_or(((upper(platform_actor_routes.message_family) = 'UTILTS'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text) AND COALESCE(platform_actor_routes.is_verified, false))) AS has_utilts_route,
            bool_or(((COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text) AND ((NULLIF(btrim(COALESCE(platform_actor_routes.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((platform_actor_routes.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)))) AS has_safe_subaddress,
            bool_or(((upper(platform_actor_routes.message_family) = 'PRODAT'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text) AND ((NULLIF(btrim(COALESCE(platform_actor_routes.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((platform_actor_routes.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)))) AS has_safe_prodat_subaddress,
            bool_or(((upper(platform_actor_routes.message_family) = 'UTILTS'::text) AND (COALESCE(platform_actor_routes.status, ''::text) = 'active'::text) AND (COALESCE(platform_actor_routes.environment, 'production'::text) = 'production'::text) AND ((NULLIF(btrim(COALESCE(platform_actor_routes.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((platform_actor_routes.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)))) AS has_safe_utilts_subaddress,
            bool_or((NULLIF(btrim(COALESCE(platform_actor_routes.communication_address, ''::text)), ''::text) IS NOT NULL)) AS has_contact_path,
            bool_or(((upper(platform_actor_routes.message_family) = 'PRODAT'::text) AND (NULLIF(btrim(COALESCE(platform_actor_routes.communication_address, ''::text)), ''::text) IS NOT NULL))) AS has_prodat_contact_path,
            bool_or(((upper(COALESCE(platform_actor_routes.subaddress, ''::text)) = 'GAS'::text) OR (upper(COALESCE(platform_actor_routes.application_reference, ''::text)) ~~ '%GAS%'::text) OR (COALESCE((platform_actor_routes.metadata ->> 'scope'::text), ''::text) = ANY (ARRAY['gas'::text, 'gas_grid'::text])))) AS has_gas_route
           FROM public.platform_actor_routes
          GROUP BY platform_actor_routes.actor_id
        ), certs AS (
         SELECT DISTINCT ON (platform_actor_certificates.actor_id, platform_actor_certificates.environment, platform_actor_certificates.purpose) platform_actor_certificates.actor_id,
            platform_actor_certificates.environment,
            platform_actor_certificates.purpose,
            platform_actor_certificates.status,
            platform_actor_certificates.fingerprint_sha256,
            platform_actor_certificates.ediel_id,
            platform_actor_certificates.valid_to,
            platform_actor_certificates.raw_certificate_pem
           FROM public.platform_actor_certificates
          WHERE ((platform_actor_certificates.environment = 'production'::text) AND (platform_actor_certificates.purpose = ANY (ARRAY['encryption'::text, 'signing'::text])) AND (COALESCE(platform_actor_certificates.status, ''::text) = ANY (ARRAY['valid'::text, 'expires_soon'::text])) AND (platform_actor_certificates.valid_to IS NOT NULL) AND (platform_actor_certificates.valid_to > now()) AND (NULLIF(btrim(COALESCE(platform_actor_certificates.raw_certificate_pem, ''::text)), ''::text) IS NOT NULL))
          ORDER BY platform_actor_certificates.actor_id, platform_actor_certificates.environment, platform_actor_certificates.purpose, platform_actor_certificates.valid_to DESC NULLS LAST
        ), conflicts AS (
         SELECT actor_open_blocking_conflict_counts.actor_id,
            actor_open_blocking_conflict_counts.open_blocking_conflicts
           FROM gridex_internal.actor_open_blocking_conflict_counts() actor_open_blocking_conflict_counts(actor_id, open_blocking_conflicts)
        ), base AS (
         SELECT a.id AS platform_market_actor_id,
            a.name AS actor_name,
            a.legal_name,
            COALESCE(ids.org_number, a.org_number) AS org_number,
            ids.ediel_id,
            ids.eic,
            COALESCE(roles.roles, '{}'::text[]) AS roles,
            COALESCE(roles.has_grid_owner_role, false) AS has_grid_owner_role,
            COALESCE(roles.has_supplier_role, false) AS has_supplier_role,
            COALESCE(routes.has_prodat_route, false) AS has_prodat_route,
            COALESCE(routes.has_utilts_route, false) AS has_utilts_route,
            COALESCE(routes.has_safe_subaddress, false) AS has_safe_subaddress,
            COALESCE(routes.has_contact_path, false) AS has_contact_path,
            COALESCE(((certs.fingerprint_sha256 IS NOT NULL) AND ((certs.ediel_id IS NULL) OR (certs.ediel_id = ids.ediel_id))), false) AS has_valid_prodat_certificate,
            COALESCE(((certs.fingerprint_sha256 IS NOT NULL) AND ((certs.ediel_id IS NULL) OR (certs.ediel_id = ids.ediel_id))), false) AS has_valid_utilts_certificate,
            COALESCE(conflicts.open_blocking_conflicts, 0) AS open_blocking_conflicts,
            COALESCE(routes.has_safe_prodat_subaddress, false) AS has_safe_prodat_subaddress,
            COALESCE(routes.has_prodat_contact_path, false) AS has_prodat_contact_path,
            scope.is_gas_actor,
            scope.is_dummy_or_test_actor,
            scope.is_system_supplier_only,
            scope.is_electricity_grid_owner_scope,
            scope.primary_role_group,
            scope.electricity_scope_status
           FROM ((((((public.platform_market_actors a
             LEFT JOIN ids ON ((ids.actor_id = a.id)))
             LEFT JOIN roles ON ((roles.actor_id = a.id)))
             LEFT JOIN routes ON ((routes.actor_id = a.id)))
             LEFT JOIN certs ON (((certs.actor_id = a.id) AND (certs.environment = 'production'::text) AND (certs.purpose = 'encryption'::text))))
             LEFT JOIN conflicts ON ((conflicts.actor_id = a.id)))
             LEFT JOIN public.actor_electricity_scope_classification_v scope ON ((scope.platform_market_actor_id = a.id)))
        )
 SELECT platform_market_actor_id,
    actor_name,
    legal_name,
    org_number,
    ediel_id,
    eic,
    roles,
    has_grid_owner_role,
    has_supplier_role,
    has_prodat_route,
    has_utilts_route,
    has_safe_subaddress,
    has_contact_path,
    has_valid_prodat_certificate,
    has_valid_utilts_certificate,
    open_blocking_conflicts,
    ((ediel_id IS NOT NULL) AND has_prodat_route AND has_safe_prodat_subaddress AND has_prodat_contact_path AND has_valid_prodat_certificate AND (open_blocking_conflicts = 0)) AS can_use_for_prodat,
    ((ediel_id IS NOT NULL) AND has_utilts_route AND has_safe_subaddress AND has_contact_path AND (open_blocking_conflicts = 0)) AS can_use_for_utilts,
    (is_electricity_grid_owner_scope AND (ediel_id IS NOT NULL) AND has_prodat_route AND has_safe_prodat_subaddress AND has_prodat_contact_path AND has_valid_prodat_certificate AND (open_blocking_conflicts = 0)) AS can_start_supplier_switch,
        CASE
            WHEN (COALESCE(electricity_scope_status, ''::text) = 'excluded_from_electricity_scope'::text) THEN ARRAY['excluded_from_electricity_scope'::text]
            WHEN (NOT COALESCE(is_electricity_grid_owner_scope, false)) THEN array_remove(ARRAY[
            CASE
                WHEN has_grid_owner_role THEN NULL::text
                ELSE 'not_electricity_grid_owner'::text
            END], NULL::text)
            ELSE array_remove(ARRAY[
            CASE
                WHEN (ediel_id IS NULL) THEN 'missing_ediel_id'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NOT has_prodat_route) THEN 'missing_prodat_route'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (has_prodat_route AND (NOT has_safe_prodat_subaddress)) THEN 'unsafe_or_missing_subaddress'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (has_prodat_route AND (NOT has_prodat_contact_path)) THEN 'missing_contact_path'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (has_prodat_route AND (NOT has_valid_prodat_certificate)) THEN 'missing_or_invalid_certificate'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (open_blocking_conflicts > 0) THEN 'open_blocking_conflicts'::text
                ELSE NULL::text
            END], NULL::text)
        END AS blocking_reasons,
    now() AS checked_at,
    COALESCE(is_gas_actor, false) AS is_gas_actor,
    COALESCE(is_dummy_or_test_actor, false) AS is_dummy_or_test_actor,
    COALESCE(is_system_supplier_only, false) AS is_system_supplier_only,
    COALESCE(is_electricity_grid_owner_scope, false) AS is_electricity_grid_owner_scope,
    COALESCE(electricity_scope_status, 'separate_role_scope'::text) AS electricity_scope_status,
    COALESCE(primary_role_group, 'other'::text) AS primary_role_group,
        CASE
            WHEN (COALESCE(electricity_scope_status, ''::text) = 'excluded_from_electricity_scope'::text) THEN 'excluded_from_electricity_scope'::text
            WHEN (NOT COALESCE(is_electricity_grid_owner_scope, false)) THEN 'separate_role_scope'::text
            WHEN ((ediel_id IS NOT NULL) AND has_prodat_route AND has_safe_prodat_subaddress AND has_prodat_contact_path AND has_valid_prodat_certificate AND (open_blocking_conflicts = 0)) THEN 'ready'::text
            WHEN (NOT has_prodat_route) THEN 'manual_review_required'::text
            WHEN (NOT has_valid_prodat_certificate) THEN 'missing_or_invalid_certificate'::text
            WHEN (NOT has_safe_prodat_subaddress) THEN 'unsafe_or_missing_subaddress'::text
            WHEN (NOT has_prodat_contact_path) THEN 'missing_contact_path'::text
            WHEN (open_blocking_conflicts > 0) THEN 'open_blocking_conflicts'::text
            ELSE 'manual_review_required'::text
        END AS supplier_switch_readiness_status,
    (COALESCE(is_electricity_grid_owner_scope, false) AND (NOT has_prodat_route)) AS manual_review_required,
        CASE
            WHEN (COALESCE(is_electricity_grid_owner_scope, false) AND (NOT has_prodat_route)) THEN 'missing_prodat_route'::text
            ELSE NULL::text
        END AS manual_review_reason
   FROM base b;

--
-- Name: VIEW actor_readiness_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.actor_readiness_status IS 'Role-aware actor readiness. Blocking conflict counts use an aggregate-only internal helper so BL-002 row isolation cannot cause false readiness.';

--
-- Name: actor_readiness_by_role_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actor_readiness_by_role_v WITH (security_invoker='true') AS
 WITH grouped AS (
         SELECT actor_readiness_status.primary_role_group AS role_group,
            (count(*))::integer AS actor_count,
            (count(*) FILTER (WHERE actor_readiness_status.can_start_supplier_switch))::integer AS supplier_switch_ready_count,
            (count(*) FILTER (WHERE (actor_readiness_status.electricity_scope_status = 'excluded_from_electricity_scope'::text)))::integer AS excluded_from_electricity_scope_count,
            (count(*) FILTER (WHERE (actor_readiness_status.supplier_switch_readiness_status = 'manual_review_required'::text)))::integer AS manual_review_required_count,
            (count(*) FILTER (WHERE ('missing_or_invalid_certificate'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS missing_or_invalid_certificate_count,
            (count(*) FILTER (WHERE ('missing_prodat_route'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS missing_prodat_route_count,
            (count(*) FILTER (WHERE ('unsafe_or_missing_subaddress'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS unsafe_or_missing_subaddress_count,
            (count(*) FILTER (WHERE ('missing_contact_path'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS missing_contact_path_count,
            (count(*) FILTER (WHERE ('missing_ediel_id'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS missing_ediel_id_count,
            (count(*) FILTER (WHERE ('open_blocking_conflicts'::text = ANY (actor_readiness_status.blocking_reasons))))::integer AS open_blocking_conflicts_count
           FROM public.actor_readiness_status
          GROUP BY actor_readiness_status.primary_role_group
        )
 SELECT role_group,
    actor_count,
    supplier_switch_ready_count,
    excluded_from_electricity_scope_count,
    manual_review_required_count,
    missing_or_invalid_certificate_count,
    missing_prodat_route_count,
    unsafe_or_missing_subaddress_count,
    missing_contact_path_count,
    missing_ediel_id_count,
    open_blocking_conflicts_count
   FROM grouped;

--
-- Name: actor_registry_conflicts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.actor_registry_conflicts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    import_run_id uuid,
    import_item_id uuid,
    actor_id uuid,
    grid_owner_id uuid,
    supplier_id uuid,
    conflict_type text NOT NULL,
    severity text DEFAULT 'blocking'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    title text NOT NULL,
    message text NOT NULL,
    current_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    incoming_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    resolution text,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    conflict_fingerprint text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT actor_registry_conflicts_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'blocking'::text]))),
    CONSTRAINT actor_registry_conflicts_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text, 'ignored'::text])))
);

--
-- Name: actor_registry_duplicate_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actor_registry_duplicate_candidates_v WITH (security_invoker='true') AS
 WITH identifiers AS (
         SELECT platform_actor_identifiers.actor_id,
            lower(platform_actor_identifiers.identifier_type) AS identifier_type,
            public.gridex_normalize_actor_identifier(platform_actor_identifiers.identifier_type, platform_actor_identifiers.identifier_value) AS identifier_value
           FROM public.platform_actor_identifiers
          WHERE (NULLIF(btrim(platform_actor_identifiers.identifier_value), ''::text) IS NOT NULL)
        ), dupes AS (
         SELECT identifiers.identifier_type,
            identifiers.identifier_value,
            (count(DISTINCT identifiers.actor_id))::integer AS duplicate_count,
            array_agg(DISTINCT identifiers.actor_id ORDER BY identifiers.actor_id) AS actor_ids
           FROM identifiers
          WHERE ((identifiers.identifier_type = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'orgno'::text, 'org_number'::text, 'orgnr'::text, 'eic'::text, 'eic_code'::text])) AND (identifiers.identifier_value IS NOT NULL))
          GROUP BY identifiers.identifier_type, identifiers.identifier_value
         HAVING (count(DISTINCT identifiers.actor_id) > 1)
        ), names AS (
         SELECT 'name'::text AS identifier_type,
            platform_market_actors.normalized_name AS identifier_value,
            (count(*))::integer AS duplicate_count,
            array_agg(platform_market_actors.id ORDER BY platform_market_actors.id) AS actor_ids
           FROM public.platform_market_actors
          WHERE (platform_market_actors.normalized_name IS NOT NULL)
          GROUP BY platform_market_actors.normalized_name
         HAVING (count(*) > 1)
        )
 SELECT dupes.identifier_type AS duplicate_type,
    dupes.identifier_value AS duplicate_key,
    dupes.duplicate_count,
    dupes.actor_ids,
        CASE
            WHEN (dupes.identifier_type = ANY (ARRAY['edielid'::text, 'ediel_id'::text])) THEN 'blocking'::text
            ELSE 'warning'::text
        END AS severity,
    'manual_review_required'::text AS suggested_action
   FROM dupes
UNION ALL
 SELECT names.identifier_type AS duplicate_type,
    names.identifier_value AS duplicate_key,
    names.duplicate_count,
    names.actor_ids,
    'warning'::text AS severity,
    'manual_review_required'::text AS suggested_action
   FROM names;

