--
-- Name: actor_test_current_results_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.actor_test_current_results_v WITH (security_invoker='true') AS
 SELECT DISTINCT ON (a.company_id, a.environment_type, a.actor_role, a.test_suite, a.setup_package, a.message_family, a.test_case_code, a.message_variant, a.rulebook_version) a.id,
    a.company_id,
    a.test_run_id,
    a.test_case_code,
    a.environment_type,
    a.actor_role,
    a.role_code,
    a.test_suite,
    a.setup_package,
    a.message_family,
    a.message_variant,
    a.status,
    a.machine_verified,
    a.configuration_snapshot_id,
    a.configuration_hash,
    a.rulebook_version,
    a.engine_version,
    a.started_at,
    a.completed_at,
    a.evidence_digest,
    a.failure_code,
    a.failure_details,
    a.created_by,
    a.created_at
   FROM (public.actor_test_attempts a
     JOIN public.ediel_active_test_configurations c ON (((c.company_id = a.company_id) AND (c.configuration_snapshot_id = a.configuration_snapshot_id) AND (c.status = 'active'::text) AND (c.environment = 'test'::text) AND (c.actor_role = a.actor_role) AND (c.test_suite = a.test_suite) AND (c.message_family = a.message_family) AND (c.setup_package = a.setup_package))))
  WHERE (a.status <> 'superseded'::text)
  ORDER BY a.company_id, a.environment_type, a.actor_role, a.test_suite, a.setup_package, a.message_family, a.test_case_code, a.message_variant, a.rulebook_version, a.created_at DESC, a.id DESC;

