    version_series_id uuid DEFAULT gen_random_uuid() NOT NULL,
    supersedes_offer_id uuid,
    superseded_at timestamp with time zone,
    lifecycle_status text DEFAULT 'draft'::text NOT NULL,
    discount_months integer,
    discount_calculation_base text,
    discount_starts_on_mode text DEFAULT 'contract_start'::text NOT NULL,
    automatic_renewal_term_months integer,
    power_of_attorney_mode text DEFAULT 'required_when_information_missing'::text NOT NULL,
    closed_at timestamp with time zone,
