    CONSTRAINT contract_offers_auto_renew_term_check CHECK (((automatic_renewal_term_months IS NULL) OR (automatic_renewal_term_months > 0))),
    CONSTRAINT contract_offers_contract_type_check CHECK ((contract_type = ANY (ARRAY['fixed'::text, 'variable_monthly'::text, 'variable_hourly'::text, 'variable_quarterly'::text, 'portfolio'::text, 'mixed'::text]))),
    CONSTRAINT contract_offers_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text]))),
    CONSTRAINT contract_offers_discount_months_check CHECK (((discount_months IS NULL) OR (discount_months > 0))),
    CONSTRAINT contract_offers_discount_percent_check CHECK (((discount_value IS NULL) OR (discount_unit <> 'percent'::text) OR (discount_value <= (100)::numeric))),
    CONSTRAINT contract_offers_discount_period_consistency_check CHECK (((discount_value IS NULL) OR (discount_months IS NOT NULL))),
    CONSTRAINT contract_offers_discount_value_check CHECK (((discount_value IS NULL) OR (discount_value >= (0)::numeric))),
    CONSTRAINT contract_offers_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT contract_offers_invoice_fee_nonnegative CHECK (((invoice_fee_sek IS NULL) OR (invoice_fee_sek >= (0)::numeric))),
    CONSTRAINT contract_offers_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['draft'::text, 'ready'::text, 'published'::text, 'paused'::text, 'expired'::text, 'closed'::text, 'archived'::text, 'superseded'::text]))),
    CONSTRAINT contract_offers_max_customers_check CHECK (((max_customers IS NULL) OR (max_customers > 0))),
    CONSTRAINT contract_offers_months_nonnegative_check CHECK ((((default_binding_months IS NULL) OR (default_binding_months >= 0)) AND ((default_notice_months IS NULL) OR (default_notice_months >= 0)))),
    CONSTRAINT contract_offers_nonnegative_fees_check CHECK ((((start_fee_sek IS NULL) OR (start_fee_sek >= (0)::numeric)) AND ((admin_fee_sek IS NULL) OR (admin_fee_sek >= (0)::numeric)) AND ((break_fee_sek IS NULL) OR (break_fee_sek >= (0)::numeric)) AND ((monthly_fee_sek IS NULL) OR (monthly_fee_sek >= (0)::numeric)) AND ((invoice_fee_sek IS NULL) OR (invoice_fee_sek >= (0)::numeric)))),
    CONSTRAINT contract_offers_poa_mode_check CHECK ((power_of_attorney_mode = ANY (ARRAY['always_required'::text, 'required_when_information_missing'::text, 'not_required'::text]))),
    CONSTRAINT contract_offers_renewal_consistency_check CHECK (((NOT COALESCE(automatic_renewal, false)) OR (automatic_renewal_term_months IS NOT NULL))),
    CONSTRAINT contract_offers_valid_window_check CHECK (((valid_to IS NULL) OR (valid_from IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT contract_offers_vat_rate_fraction_contract CHECK (((vat_rate IS NULL) OR ((vat_rate >= (0)::numeric) AND (vat_rate <= (1)::numeric)))),
    CONSTRAINT contract_offers_vat_rate_range_check CHECK (((vat_rate IS NULL) OR ((vat_rate >= (0)::numeric) AND (vat_rate <= (1)::numeric))))
);

