    version_series_id uuid DEFAULT gen_random_uuid() NOT NULL,
    version_number integer DEFAULT 1 NOT NULL,
    supersedes_offer_id uuid,
    contract_product_id uuid,
    contract_product_version_id uuid,
    legal_bundle_version_id uuid,
    contract_publication_version_id uuid,
    source_contract_offer_id uuid,
    lifecycle_status text DEFAULT 'draft'::text NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    close_reason text,
    energy_direction text NOT NULL,
    CONSTRAINT public_contract_offers_contract_type_check CHECK ((contract_type = ANY (ARRAY['spot'::text, 'variable'::text, 'variable_spot'::text, 'variable_monthly'::text, 'variable_hourly'::text, 'variable_quarterly'::text, 'hourly_spot'::text, 'fixed'::text, 'portfolio'::text, 'mixed'::text, 'manual_override'::text]))),
    CONSTRAINT public_contract_offers_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text]))),
    CONSTRAINT public_contract_offers_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT public_contract_offers_invoice_fee_nonnegative CHECK (((invoice_fee_sek IS NULL) OR (invoice_fee_sek >= (0)::numeric))),
    CONSTRAINT public_contract_offers_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['draft'::text, 'ready'::text, 'published'::text, 'paused'::text, 'expired'::text, 'closed'::text, 'archived'::text, 'superseded'::text]))),
    CONSTRAINT public_contract_offers_months_check CHECK ((((binding_months IS NULL) OR (binding_months >= 0)) AND ((notice_months IS NULL) OR (notice_months >= 0)))),
    CONSTRAINT public_contract_offers_price_area_check CHECK (((price_area IS NULL) OR (price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])))),
    CONSTRAINT public_contract_offers_publication_status_check CHECK ((publication_status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'unpublished'::text, 'superseded'::text, 'archived'::text, 'expired'::text]))),
    CONSTRAINT public_contract_offers_valid_window_check CHECK (((valid_to IS NULL) OR (valid_from IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT public_contract_offers_weight_percent_check CHECK ((((spot_weight_percent >= (0)::numeric) AND (spot_weight_percent <= (100)::numeric)) AND ((portfolio_weight_percent >= (0)::numeric) AND (portfolio_weight_percent <= (100)::numeric)) AND ((fixed_weight_percent >= (0)::numeric) AND (fixed_weight_percent <= (100)::numeric)) AND ((contract_type <> ALL (ARRAY['portfolio'::text, 'mixed'::text])) OR (round(((COALESCE(spot_weight_percent, (0)::numeric) + COALESCE(portfolio_weight_percent, (0)::numeric)) + COALESCE(fixed_weight_percent, (0)::numeric)), 6) = (100)::numeric))))
);

