    CONSTRAINT contract_price_options_customer_type_check CHECK (((customer_type IS NULL) OR (customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text])))),
    CONSTRAINT contract_price_options_dates CHECK ((((valid_from IS NULL) OR (valid_to IS NULL) OR (valid_to >= valid_from)) AND ((earliest_start_date IS NULL) OR (latest_start_date IS NULL) OR (latest_start_date >= earliest_start_date)))),
    CONSTRAINT contract_price_options_notice_months_check CHECK (((notice_months >= 0) AND (notice_months <= 36))),
