    CONSTRAINT contract_price_options_renewal CHECK (((auto_renew_enabled AND ((renewal_term_months >= 1) AND (renewal_term_months <= 120))) OR ((NOT auto_renew_enabled) AND (renewal_term_months IS NULL)))),
    CONSTRAINT contract_price_options_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text]))),
