CREATE TABLE public.tenant_legal_overrides (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    module_key text NOT NULL,
    legal_mode text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    content_sha256 text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    submitted_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    review_notes text,
    locked_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    version_label text,
    CONSTRAINT tenant_legal_overrides_legal_mode_check CHECK ((legal_mode = ANY (ARRAY['addendum'::text, 'replacement'::text]))),
    CONSTRAINT tenant_legal_overrides_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'published'::text, 'replaced'::text, 'archived'::text, 'rejected'::text])))
);

--
-- Name: canonical_tenant_legal_overrides_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canonical_tenant_legal_overrides_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    module_key AS type,
    COALESCE(version_label, to_char((created_at AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD-HH24MISS'::text), "left"(content_sha256, 12)) AS version,
    title,
    body,
        CASE
            WHEN (status = ANY (ARRAY['published'::text, 'approved'::text])) THEN 'published'::text
            WHEN (status = ANY (ARRAY['archived'::text, 'replaced'::text, 'rejected'::text])) THEN 'archived'::text
            ELSE 'draft'::text
        END AS status,
        CASE
            WHEN (status = ANY (ARRAY['published'::text, 'approved'::text])) THEN COALESCE(reviewed_at, created_at)
            ELSE NULL::timestamp with time zone
        END AS published_at,
    created_at,
    COALESCE(reviewed_at, created_at) AS updated_at,
    jsonb_build_object('origin', 'tenant_override', 'legal_mode', legal_mode, 'content_sha256', content_sha256, 'canonical_status', status) AS metadata
   FROM public.tenant_legal_overrides o;

--
-- Name: canonical_visible_public_contracts_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canonical_visible_public_contracts_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    price_plan_id,
    price_plan_version_id,
    campaign_version_id,
    product_code,
    public_name,
    public_description,
    contract_type,
    billing_model,
    customer_type,
    monthly_fee_sek,
    invoice_fee_sek,
    markup_ore_per_kwh,
    spot_markup_ore_per_kwh,
    variable_fee_ore_per_kwh,
    fixed_price_ore_per_kwh,
    green_fee_mode,
    green_fee_value,
    terms_version,
    valid_from,
    valid_to,
    is_public,
    is_archived,
    sort_order,
    metadata,
    created_by,
    updated_by,
    created_at,
    updated_at,
    offer_code,
    publication_status,
    website_enabled,
    website_cta_enabled,
    public_price_text,
    terms_url,
    binding_months,
    notice_months,
    spot_weight_percent,
    portfolio_weight_percent,
    fixed_weight_percent,
    price_area,
    published_at,
    archived_at,
    readiness_issues,
    publication_notes,
    legal_bundle_id,
    price_book_id,
    readiness_status,
    readiness_blockers,
    electricity_certificate_ore_per_kwh,
    start_fee_sek,
    administration_fee_sek,
    break_fee_sek,
    portfolio_management_fee_ore_per_kwh,
    discount_value,
    discount_unit,
    discount_months,
    vat_rate,
    price_areas,
    automatic_renewal,
    power_of_attorney_required,
    version_series_id,
    version_number,
    supersedes_offer_id,
    contract_product_id,
    contract_product_version_id,
    legal_bundle_version_id,
    contract_publication_version_id,
    canonical_offer_reference,
    publication_locked_at,
    publication_content_sha256,
    canonical_pricing_snapshot,
    canonical_metadata,
    source_contract_offer_id,
    lifecycle_status,
    closed_at,
    closed_by,
    close_reason,
    energy_direction,
    website_publication_allowed,
    website_available_now
   FROM public.canonical_public_contract_offers_v visible
  WHERE (EXISTS ( SELECT 1
           FROM public.canonical_public_contract_diagnostics_v diagnostic
          WHERE ((diagnostic.company_id = visible.company_id) AND (diagnostic.source_contract_offer_id = visible.source_contract_offer_id) AND (diagnostic.channel = 'website'::text) AND diagnostic.visible)));

