--
-- Name: company_actor_testing_status_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_actor_testing_status_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    count(r.id) FILTER (WHERE (r.environment = 'test'::text)) AS total_tests,
    count(r.id) FILTER (WHERE (r.status = 'passed'::text)) AS passed_tests,
    count(r.id) FILTER (WHERE (r.status = ANY (ARRAY['failed'::text, 'blocked'::text]))) AS blocked_or_failed_tests,
    max(r.updated_at) AS last_test_updated_at,
        CASE
            WHEN (count(r.id) = 0) THEN 'not_started'::text
            WHEN (count(r.id) FILTER (WHERE (r.status = ANY (ARRAY['failed'::text, 'blocked'::text]))) > 0) THEN 'action_required'::text
            WHEN (count(r.id) FILTER (WHERE (r.status = 'passed'::text)) = count(r.id)) THEN 'passed'::text
            ELSE 'in_progress'::text
        END AS testing_status
   FROM (public.companies c
     LEFT JOIN public.company_actor_test_runs r ON ((r.company_id = c.id)))
  WHERE (to_regclass('public.companies'::text) IS NOT NULL)
  GROUP BY c.id, c.name;

--
-- Name: company_billing_period_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_billing_period_summary_v WITH (security_invoker='true') AS
 SELECT company_id,
    concat((underlay_year)::text, '-', lpad((underlay_month)::text, 2, '0'::text)) AS period_key,
    underlay_year,
    underlay_month,
    count(*) AS underlays_total,
    count(*) FILTER (WHERE (COALESCE(readiness_status, status) = ANY (ARRAY['ready'::text, 'validated'::text, 'exported'::text]))) AS underlays_ready,
    count(*) FILTER (WHERE (COALESCE(readiness_status, status) = ANY (ARRAY['blocked'::text, 'failed'::text, 'needs_review'::text]))) AS underlays_blocked,
    count(*) FILTER (WHERE ((exported_at IS NOT NULL) OR (status = 'exported'::text))) AS underlays_exported,
    max(updated_at) AS latest_activity_at
   FROM public.billing_underlays b
  WHERE ((company_id IS NOT NULL) AND (underlay_year IS NOT NULL) AND (underlay_month IS NOT NULL))
  GROUP BY company_id, underlay_year, underlay_month;

