--
-- Name: company_switch_queue_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_switch_queue_v WITH (security_invoker='true') AS
 SELECT s.id AS switch_id,
    s.company_id,
    s.customer_id,
    COALESCE(c.customer_number, ''::text) AS customer_number,
    COALESCE(NULLIF(c.full_name, ''::text), NULLIF(c.company_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), 'Namnlös kund'::text) AS customer_name,
    s.site_id,
    s.metering_point_id,
    s.status,
    s.requested_start_date,
    s.completed_at AS confirmed_start_date,
        CASE
            WHEN s.lifecycle_blocked THEN COALESCE(s.lifecycle_block_source, 'blocked'::text)
            WHEN (s.status = ANY (ARRAY['failed'::text, 'rejected'::text])) THEN COALESCE(s.failure_reason, s.status)
            WHEN ((s.power_of_attorney_id IS NULL) AND (s.authorization_document_id IS NULL)) THEN 'missing_power_of_attorney'::text
            WHEN (s.metering_point_id IS NULL) THEN 'missing_metering_point'::text
            WHEN (s.site_id IS NULL) THEN 'missing_site'::text
            ELSE NULL::text
        END AS blocking_reason,
        CASE
            WHEN (s.lifecycle_blocked OR (s.status = ANY (ARRAY['failed'::text, 'rejected'::text]))) THEN 'Åtgärda blockerare'::text
            WHEN (s.status = ANY (ARRAY['draft'::text, 'open'::text])) THEN 'Kontrollera och starta byte'::text
            WHEN (s.status = ANY (ARRAY['queued'::text, 'submitted'::text])) THEN 'Följ upp utskick'::text
            WHEN (s.status = ANY (ARRAY['accepted'::text, 'confirmed'::text, 'completed'::text])) THEN 'Bekräftad'::text
            ELSE 'Granska ärende'::text
        END AS next_action,
    s.created_at,
    s.updated_at
   FROM (public.supplier_switch_requests s
     LEFT JOIN public.customers c ON ((c.id = s.customer_id)));

