);

--
-- Name: customer_ops_master_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_ops_master_readiness_v WITH (security_invoker='true') AS
 SELECT company_id,
    id AS customer_id,
    customer_number,
    status AS customer_status,
    (EXISTS ( SELECT 1
           FROM public.customer_legal_acceptances a
          WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'terms'::text)))) AS has_terms_acceptance,
    (EXISTS ( SELECT 1
           FROM public.customer_legal_acceptances a
          WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'privacy_policy'::text)))) AS has_privacy_acceptance,
    (EXISTS ( SELECT 1
           FROM public.customer_legal_acceptances a
          WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'withdrawal_info'::text)))) AS has_withdrawal_acceptance,
    (EXISTS ( SELECT 1
           FROM public.customer_legal_acceptances a
          WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'price_snapshot'::text)))) AS has_price_snapshot_acceptance,
    (EXISTS ( SELECT 1
           FROM public.customer_legal_acceptances a
          WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'power_of_attorney'::text)))) AS has_power_of_attorney_acceptance,
    (EXISTS ( SELECT 1
           FROM public.powers_of_attorney p
          WHERE ((p.company_id = c.company_id) AND (p.customer_id = c.id) AND (p.status = ANY (ARRAY['signed'::text, 'accepted'::text, 'active'::text, 'completed'::text])) AND (COALESCE(p.revoked_at, ((p.valid_until)::timestamp with time zone + '1 day'::interval), ((p.valid_to)::timestamp with time zone + '1 day'::interval), (now() + '1 day'::interval)) > now()) AND ((p.scope = ANY (ARRAY['facility_data_request'::text, 'metering_point_lookup'::text, 'supplier_switch'::text, 'metering_values'::text, 'ediel_communication'::text])) OR (p.scope_summary ?| ARRAY['facility_data_request'::text, 'metering_point_lookup'::text, 'supplier_switch'::text, 'metering_values'::text, 'ediel_communication'::text]))))) AS has_active_power_of_attorney,
    (EXISTS ( SELECT 1
           FROM public.customer_contracts cc
          WHERE ((cc.company_id = c.company_id) AND (cc.customer_id = c.id) AND (cc.status = ANY (ARRAY['pending_signature'::text, 'signed'::text, 'active'::text, 'draft'::text]))))) AS has_contract,
    (EXISTS ( SELECT 1
           FROM (public.customer_contracts cc
             LEFT JOIN public.contract_price_snapshots cps ON (((cps.id = cc.contract_price_snapshot_id) AND (cps.company_id = cc.company_id))))
          WHERE ((cc.company_id = c.company_id) AND (cc.customer_id = c.id) AND ((cc.contract_price_snapshot_id IS NOT NULL) OR (cps.id IS NOT NULL) OR (COALESCE(cc.price_snapshot, '{}'::jsonb) <> '{}'::jsonb) OR (COALESCE(cc.version_snapshot, '{}'::jsonb) <> '{}'::jsonb))))) AS has_contract_snapshot,
    (EXISTS ( SELECT 1
           FROM public.customer_sites s
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (s.status = ANY (ARRAY['active'::text, 'pending_validation'::text, 'draft'::text]))))) AS has_site,
    (EXISTS ( SELECT 1
           FROM (public.customer_sites s
             JOIN public.metering_points mp ON (((mp.site_id = s.id) AND (mp.company_id = s.company_id))))
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (NULLIF(COALESCE(mp.meter_point_id, mp.metering_point_id, mp.ediel_metering_point_id), ''::text) IS NOT NULL)))) AS has_metering_point_id,
    (EXISTS ( SELECT 1
           FROM public.customer_sites s
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (s.grid_owner_id IS NOT NULL)))) AS has_grid_owner,
    (EXISTS ( SELECT 1
           FROM public.customer_sites s
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (NULLIF(COALESCE(s.grid_area_code, ''::text), ''::text) IS NOT NULL)))) AS has_grid_area,
    (EXISTS ( SELECT 1
           FROM (public.communication_routes r
             LEFT JOIN public.ediel_route_profiles rp ON (((rp.communication_route_id = r.id) AND (rp.company_id = r.company_id))))
          WHERE ((r.company_id = c.company_id) AND (r.is_active = true) AND (COALESCE(r.route_scope, ''::text) = ANY (ARRAY['supplier_switch'::text, 'customer_masterdata'::text, 'meter_values'::text, 'billing_underlay'::text, 'facility_data_request'::text, 'customer_data_request'::text, 'ediel_partner'::text, 'billing_metering'::text])) AND (COALESCE(rp.is_enabled, true) = true)))) AS has_ediel_route,
    array_remove(ARRAY[
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_legal_acceptances a
              WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'terms'::text))))) THEN 'Villkor saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_legal_acceptances a
              WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'privacy_policy'::text))))) THEN 'Integritetspolicy saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_legal_acceptances a
              WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'withdrawal_info'::text))))) THEN 'Ångerrättsinformation saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_legal_acceptances a
              WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.id) AND (a.acceptance_type = 'price_snapshot'::text))))) THEN 'Prissnapshot/godkänd prisbild saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.powers_of_attorney p
              WHERE ((p.company_id = c.company_id) AND (p.customer_id = c.id) AND (p.status = ANY (ARRAY['signed'::text, 'accepted'::text, 'active'::text, 'completed'::text])) AND (COALESCE(p.revoked_at, ((p.valid_until)::timestamp with time zone + '1 day'::interval), ((p.valid_to)::timestamp with time zone + '1 day'::interval), (now() + '1 day'::interval)) > now()))))) THEN 'Aktiv fullmakt saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_contracts cc
              WHERE ((cc.company_id = c.company_id) AND (cc.customer_id = c.id))))) THEN 'Kundavtal saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_sites s
              WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id))))) THEN 'Anläggning saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM (public.customer_sites s
                 JOIN public.metering_points mp ON (((mp.site_id = s.id) AND (mp.company_id = s.company_id))))
              WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (NULLIF(COALESCE(mp.meter_point_id, mp.metering_point_id, mp.ediel_metering_point_id), ''::text) IS NOT NULL))))) THEN 'Mätpunkts-ID saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_sites s
              WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (s.grid_owner_id IS NOT NULL))))) THEN 'Nätägare saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.customer_sites s
              WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id) AND (NULLIF(COALESCE(s.grid_area_code, ''::text), ''::text) IS NOT NULL))))) THEN 'Nätområde saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM public.communication_routes r
              WHERE ((r.company_id = c.company_id) AND (r.is_active = true))))) THEN 'Ediel-route saknas'::text
            ELSE NULL::text
        END], NULL::text) AS blocking_reasons,
    now() AS evaluated_at
   FROM public.customers c
  WHERE (company_id IS NOT NULL);

