    source text DEFAULT 'application'::text NOT NULL,
    event_version integer DEFAULT 1 NOT NULL,
    idempotency_key text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT domain_events_event_type_check CHECK ((event_type ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'::text)),
    CONSTRAINT domain_events_version_check CHECK ((event_version > 0))
);

--
-- Name: customer_ops_timeline_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_ops_timeline_v WITH (security_invoker='true') AS
 SELECT e.company_id,
    e.subject_customer_id AS customer_id,
    e.created_at,
    e.event_type,
        CASE e.event_type
            WHEN 'customer.created'::text THEN 'Ansökan mottagen'::text
            WHEN 'customer_number.assigned'::text THEN 'Kundnummer skapat'::text
            WHEN 'contract.application_received'::text THEN 'Ansökan mottagen'::text
            WHEN 'contract.confirmation_sent'::text THEN 'Avtalsbekräftelse skickad'::text
            WHEN 'contract.cooling_off_sent'::text THEN 'Ångerrättsinformation skickad'::text
            WHEN 'invoice.sent'::text THEN 'Faktura skickad'::text
            WHEN 'metering_values.updated'::text THEN 'Mätvärden uppdaterade'::text
            ELSE replace(e.event_type, '.'::text, ' '::text)
        END AS title,
    'domain_event'::text AS source,
    e.id AS source_id,
    e.payload AS metadata
   FROM public.domain_events e
  WHERE (e.subject_customer_id IS NOT NULL)
UNION ALL
 SELECT l.company_id,
    l.customer_id,
    l.created_at,
    COALESCE(l.event_key, l.template_key, 'email'::text) AS event_type,
        CASE COALESCE(l.event_key, l.template_key, 'email'::text)
            WHEN 'contract.application_received'::text THEN 'Ansökan mottagen-mail skickat'::text
            WHEN 'contract.confirmation_sent'::text THEN 'Avtalsbekräftelse skickad'::text
            WHEN 'contract.cooling_off_sent'::text THEN 'Ångerrättsinformation skickad'::text
            ELSE ('Kundmail: '::text || COALESCE(l.event_key, l.template_key, 'e-post'::text))
        END AS title,
    'communication_log'::text AS source,
    l.id AS source_id,
    jsonb_build_object('status', l.status, 'recipient', COALESCE(l.recipient, l.recipient_email), 'subject', l.subject, 'error', COALESCE(l.error_reason, l.error_message)) AS metadata
   FROM public.communication_logs l
  WHERE (l.customer_id IS NOT NULL)
UNION ALL
 SELECT a.company_id,
    a.customer_id,
    a.accepted_at AS created_at,
    a.acceptance_type AS event_type,
        CASE a.acceptance_type
            WHEN 'terms'::text THEN 'Villkor godkända'::text
            WHEN 'privacy_policy'::text THEN 'Integritetspolicy godkänd'::text
            WHEN 'withdrawal_info'::text THEN 'Ångerrättsinformation lämnad'::text
            WHEN 'power_of_attorney'::text THEN 'Fullmakt godkänd'::text
            WHEN 'price_snapshot'::text THEN 'Prisbild godkänd'::text
            ELSE 'Juridiskt godkännande'::text
        END AS title,
    'customer_legal_acceptance'::text AS source,
    a.id AS source_id,
    (jsonb_build_object('source', a.source, 'legal_text_version_id', a.legal_text_version_id) || COALESCE(a.metadata, '{}'::jsonb)) AS metadata
   FROM public.customer_legal_acceptances a;

