    expires_at timestamp with time zone,
    resolver_version text DEFAULT 'energy-resolver-v2'::text NOT NULL,
    geodata_version text,
    source_claims jsonb DEFAULT '{}'::jsonb NOT NULL,
    conflict_code text,
    price_area_assurance_status text DEFAULT 'unresolved'::text NOT NULL,
    price_area_assurance_source text,
    price_area_assurance_confidence numeric(5,4) DEFAULT 0 NOT NULL,
    price_area_assurance_source_version text,
    price_area_candidate_count integer DEFAULT 0 NOT NULL,
    price_area_unique_count integer DEFAULT 0 NOT NULL,
    price_area_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT customer_site_resolution_price_area_assurance_confidence_check CHECK (((price_area_assurance_confidence >= (0)::numeric) AND (price_area_assurance_confidence <= (1)::numeric))),
    CONSTRAINT customer_site_resolution_price_area_assurance_consistency_check CHECK (((price_area_assurance_status <> ALL (ARRAY['verified'::text, 'estimated'::text])) OR ((price_area IS NOT NULL) AND (price_area_unique_count = 1) AND (price_area_candidate_count >= 1) AND (price_area_assurance_source IS NOT NULL)))),
    CONSTRAINT customer_site_resolution_price_area_assurance_source_check CHECK (((price_area_assurance_source IS NULL) OR (price_area_assurance_source = ANY (ARRAY['facility_data'::text, 'grid_area_master'::text, 'address_polygon'::text, 'postal_city_consensus'::text, 'postal_consensus'::text, 'postal_centroid'::text])))),
    CONSTRAINT customer_site_resolution_price_area_assurance_status_check CHECK ((price_area_assurance_status = ANY (ARRAY['verified'::text, 'estimated'::text, 'ambiguous'::text, 'unresolved'::text]))),
    CONSTRAINT customer_site_resolution_price_area_candidate_count_check CHECK ((price_area_candidate_count >= 0)),
    CONSTRAINT customer_site_resolution_price_area_check CHECK (((price_area IS NULL) OR (price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])))),
    CONSTRAINT customer_site_resolution_price_area_unique_count_check CHECK (((price_area_unique_count >= 0) AND (price_area_unique_count <= price_area_candidate_count))),
    CONSTRAINT customer_site_resolution_resolution_status_check CHECK ((resolution_status = ANY (ARRAY['postal_suggested'::text, 'address_resolved'::text, 'grid_area_resolved'::text, 'grid_area_master_validated'::text, 'facility_data_requested'::text, 'facility_data_received'::text, 'facility_verified'::text, 'needs_review'::text, 'failed'::text, 'facility_data_invalid'::text, 'customer_information_mismatch'::text, 'grid_owner_rejected_request'::text, 'negative_aperak_received'::text, 'z02_rejected'::text, 'needs_customer_correction'::text, 'needs_grid_owner_followup'::text, 'protected_identity'::text])))
);

