CREATE VIEW public.ediel_certificate_refresh_candidates_v WITH (security_invoker='true') AS
 SELECT platform_market_actor_id,
    grid_owner_id,
    company_id,
    ediel_id,
    smtp_email,
    subaddress,
    environment,
    max(certificate_next_check_at) AS last_checked_at,
    NULL::timestamp with time zone AS certificate_valid_to,
    COALESCE(max(certificate_status), 'missing'::text) AS certificate_status
   FROM public.ediel_blocked_grid_owner_certificate_refresh_candidates_v
  GROUP BY platform_market_actor_id, grid_owner_id, company_id, ediel_id, smtp_email, subaddress, environment;

