-- Name: ediel_certification_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_certification_evidence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    environment text NOT NULL,
    evidence_type text NOT NULL,
    status text NOT NULL,
    engine_schema_version text NOT NULL,
    external_reference text,
    evidence_document_reference text,
    tested_at timestamp with time zone,
    valid_until timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ediel_certification_evidence_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT ediel_certification_evidence_evidence_type_check CHECK ((evidence_type = ANY (ARRAY['TGT'::text, 'AGT'::text, 'SHADOW_PRODUCTION'::text, 'LIMITED_PILOT'::text, 'LIVE_TENANT_INTEGRITY'::text, 'RESTORE_REPLAY'::text]))),
    CONSTRAINT ediel_certification_evidence_passed_integrity_check CHECK (((status <> 'passed'::text) OR ((NULLIF(btrim(external_reference), ''::text) IS NOT NULL) AND (NULLIF(btrim(evidence_document_reference), ''::text) IS NOT NULL) AND (tested_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (tested_at <= approved_at) AND ((valid_until IS NULL) OR (valid_until > tested_at))))),
    CONSTRAINT ediel_certification_evidence_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'passed'::text, 'failed'::text, 'expired'::text, 'revoked'::text])))
);

ALTER TABLE ONLY public.ediel_certification_evidence FORCE ROW LEVEL SECURITY;

--
-- Name: CONSTRAINT ediel_certification_evidence_passed_integrity_check ON ediel_certification_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT ediel_certification_evidence_passed_integrity_check ON public.ediel_certification_evidence IS 'Passed production evidence must be traceable, tested, explicitly approved, and temporally coherent.';

