-- Name: ediel_data_access_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_data_access_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    beneficiary_company_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    permission_link_id uuid NOT NULL,
    object_ids text[] NOT NULL,
    product_ids text[] NOT NULL,
    fields text[] NOT NULL,
    purpose text NOT NULL,
    data_start timestamp with time zone NOT NULL,
    data_end timestamp with time zone,
    valid_from timestamp with time zone NOT NULL,
    valid_to timestamp with time zone,
    status text DEFAULT 'held'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ediel_data_access_grants_check CHECK ((company_id <> beneficiary_company_id)),
    CONSTRAINT ediel_data_access_grants_check1 CHECK (((data_end IS NULL) OR (data_end > data_start))),
    CONSTRAINT ediel_data_access_grants_check2 CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT ediel_data_access_grants_check3 CHECK (((status <> 'revoked'::text) OR (revoked_at IS NOT NULL))),
    CONSTRAINT ediel_data_access_grants_fields_check CHECK (((cardinality(fields) > 0) AND (fields <@ ARRAY['reading_at'::text, 'quantity'::text, 'unit'::text, 'quality'::text, 'qualifier'::text, 'registration_date'::text, 'resolution'::text, 'product_id'::text]) AND (array_position(fields, NULL::text) IS NULL))),
    CONSTRAINT ediel_data_access_grants_object_ids_check CHECK (((cardinality(object_ids) > 0) AND (array_position(object_ids, NULL::text) IS NULL))),
    CONSTRAINT ediel_data_access_grants_product_ids_check CHECK (((cardinality(product_ids) > 0) AND (array_position(product_ids, NULL::text) IS NULL))),
    CONSTRAINT ediel_data_access_grants_purpose_check CHECK ((length(btrim(purpose)) > 0)),
    CONSTRAINT ediel_data_access_grants_status_check CHECK ((status = ANY (ARRAY['held'::text, 'active'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT ediel_data_access_grants_version_check CHECK ((version > 0))
);

