    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    sent_at timestamp with time zone,
    failed_at timestamp with time zone,
    last_error text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_outbox_attempts_check CHECK (((attempts >= 0) AND (max_attempts > 0))),
    CONSTRAINT event_outbox_destination_type_check CHECK ((destination_type = ANY (ARRAY['webhook'::text, 'email'::text, 'api'::text, 'internal'::text]))),
    CONSTRAINT event_outbox_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'sent'::text, 'failed'::text, 'dead_letter'::text, 'skipped'::text])))
);

