--
-- Name: gridcore_ediel_duplicate_ack_chains_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridcore_ediel_duplicate_ack_chains_v WITH (security_invoker='true') AS
 SELECT company_id,
    source_message_id,
    ack_family,
    ack_scope,
    COALESCE(transaction_reference, ''::text) AS transaction_reference_key,
    outcome,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at, id) AS row_ids
   FROM public.ediel_ack_chains
  GROUP BY company_id, source_message_id, ack_family, ack_scope, COALESCE(transaction_reference, ''::text), outcome
 HAVING (count(*) > 1);

--
-- Name: gridcore_ediel_duplicate_metering_points_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridcore_ediel_duplicate_metering_points_v WITH (security_invoker='true') AS
 SELECT company_id,
    metering_point_id,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at, id) AS row_ids
   FROM public.metering_points
  WHERE ((company_id IS NOT NULL) AND (metering_point_id IS NOT NULL))
  GROUP BY company_id, metering_point_id
 HAVING (count(*) > 1);

--
-- Name: gridcore_ediel_duplicate_metering_values_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridcore_ediel_duplicate_metering_values_v WITH (security_invoker='true') AS
 SELECT company_id,
    metering_point_id,
    product_code,
    register_code,
    meter_number,
    period_start,
    period_end,
    reading_type,
    source_transaction_id,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at, id) AS row_ids
   FROM public.metering_values
  WHERE ((company_id IS NOT NULL) AND (metering_point_id IS NOT NULL) AND (period_start IS NOT NULL) AND (period_end IS NOT NULL))
  GROUP BY company_id, metering_point_id, product_code, register_code, meter_number, period_start, period_end, reading_type, source_transaction_id
 HAVING (count(*) > 1);

