    with_check
   FROM pg_policies
  WHERE ((schemaname = 'public'::name) AND ((COALESCE(qual, ''::text) ~~* '%auth.uid()%'::text) OR (COALESCE(qual, ''::text) ~~* '%auth.role()%'::text) OR (COALESCE(qual, ''::text) ~~* '%auth.jwt()%'::text) OR (COALESCE(qual, ''::text) ~~* '%gridex_user_is_platform_admin()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%auth.uid()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%auth.role()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%auth.jwt()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%gridex_user_is_platform_admin()%'::text)));

