    requests_created integer DEFAULT 0 NOT NULL,
    cases_created integer DEFAULT 0 NOT NULL,
    exports_created integer DEFAULT 0 NOT NULL,
    blockers_found integer DEFAULT 0 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT operations_automation_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'completed_with_flags'::text, 'failed'::text])))
);

--
-- Name: gridex_batch_2b_live_control_tower_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_batch_2b_live_control_tower_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    c.status AS company_status,
        CASE eps.state
            WHEN 'live'::text THEN 'live'::text
            WHEN 'paused'::text THEN 'paused'::text
            WHEN 'blocked'::text THEN 'blocked'::text
            WHEN 'prepared'::text THEN 'production_prepared'::text
            WHEN 'retired'::text THEN 'blocked'::text
            WHEN 'configuring'::text THEN 'not_ready'::text
            WHEN 'disabled'::text THEN 'not_ready'::text
            ELSE c.production_status
        END AS production_status,
        CASE
            WHEN (eps.company_id IS NOT NULL) THEN (eps.state = 'live'::text)
            ELSE c.live_ediel_enabled
        END AS live_ediel_enabled,
    (COALESCE(( SELECT count(*) AS count
           FROM public.outbound_requests o
          WHERE ((o.company_id = c.id) AND (o.status = ANY (ARRAY['failed'::text, 'queued'::text, 'prepared'::text])))), (0)::bigint))::integer AS open_outbound_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.customer_cases cc
          WHERE ((cc.company_id = c.id) AND (cc.status <> ALL (ARRAY['resolved'::text, 'closed'::text, 'cancelled'::text])))), (0)::bigint))::integer AS open_case_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.billing_export_run_items bei
          WHERE ((bei.company_id = c.id) AND (bei.status = 'blocked'::text))), (0)::bigint))::integer AS blocked_export_rows,
    (COALESCE(( SELECT count(*) AS count
           FROM public.billing_import_rows bir
          WHERE ((bir.company_id = c.id) AND (bir.status = 'failed'::text))), (0)::bigint))::integer AS failed_import_rows,
    (COALESCE(( SELECT count(*) AS count
           FROM public.operations_automation_runs ar
          WHERE (ar.company_id = c.id)), (0)::bigint))::integer AS automation_run_count,
    COALESCE(( SELECT max(ar.created_at) AS max
           FROM public.operations_automation_runs ar
          WHERE (ar.company_id = c.id)), NULL::timestamp with time zone) AS last_automation_run_at,
    c.updated_at
   FROM (public.companies c
     LEFT JOIN public.ediel_production_state eps ON ((eps.company_id = c.id)));

