);

--
-- Name: gridex_company_operations_statistics_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_company_operations_statistics_v WITH (security_invoker='true') AS
 SELECT id AS company_id,
    name AS company_name,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE (x.company_id = c.id)) AS customers_total,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= date_trunc('day'::text, now())))) AS customers_today,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= (now() - '7 days'::interval)))) AS customers_last_7_days,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= date_trunc('month'::text, now())))) AS customers_this_month,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.status = 'active'::text))) AS customers_active,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE (x.company_id = c.id)) AS web_intakes_total,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'received'::text))) AS web_intakes_received,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'needs_review'::text))) AS web_intakes_needs_review,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'failed'::text))) AS web_intakes_failed,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_customer_id IS NOT NULL))) AS web_intakes_with_customer,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_site_id IS NOT NULL))) AS web_intakes_with_site,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_metering_point_id IS NOT NULL))) AS web_intakes_with_metering_point,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_contract_id IS NOT NULL))) AS web_intakes_with_contract,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE (x.company_id = c.id)) AS sites_total,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.grid_area_code IS NULL))) AS sites_missing_grid_area,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.grid_owner_id IS NULL))) AS sites_missing_grid_owner,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.price_area_code IS NULL))) AS sites_missing_price_area_code,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE (x.company_id = c.id)) AS metering_points_total,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.metering_point_id, x.meter_point_id) IS NOT NULL))) AS metering_points_with_identifier,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.metering_point_id, x.meter_point_id) IS NULL))) AS metering_points_without_identifier,
    ( SELECT count(*) AS count
           FROM public.customer_contracts x
          WHERE (x.company_id = c.id)) AS contracts_total,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE (x.company_id = c.id)) AS billing_underlays_total,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.readiness_status, x.status) = ANY (ARRAY['blocked'::text, 'failed'::text, 'needs_review'::text])))) AS billing_blocked_or_failed,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.direction = 'inbound'::text))) AS ediel_inbound,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.direction = 'outbound'::text))) AS ediel_outbound,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'blocked'::text, 'unresolved'::text])))) AS ediel_blocked_failed_unresolved,
    ( SELECT count(*) AS count
           FROM public.integration_api_requests x
          WHERE (x.company_id = c.id)) AS api_requests,
    ( SELECT count(*) AS count
           FROM public.integration_api_requests x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.status_code, 200) >= 400))) AS api_errors,
    ( SELECT count(*) AS count
           FROM public.webhook_deliveries x
          WHERE (x.company_id = c.id)) AS webhook_deliveries,
    ( SELECT count(*) AS count
           FROM public.webhook_deliveries x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'dead'::text, 'dead_letter'::text, 'retrying'::text])))) AS webhook_failures,
    ( SELECT COALESCE(sum(r.issue_count), (0)::numeric) AS "coalesce"
           FROM public.gridex_company_launch_blocker_reasons_v r
          WHERE ((r.company_id = c.id) AND (r.issue_count > 0))) AS customers_blocked_or_data_issues,
    ( SELECT COALESCE(jsonb_object_agg(r.reason_key, r.issue_count), '{}'::jsonb) AS "coalesce"
           FROM public.gridex_company_launch_blocker_reasons_v r
          WHERE ((r.company_id = c.id) AND (r.issue_count > 0))) AS blocker_reasons,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (jsonb_typeof(x.issues) = 'array'::text) AND (jsonb_array_length(x.issues) > 0))) AS web_intakes_with_issues,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.status, ''::text) = ANY (ARRAY['verified'::text, 'active'::text])))) AS metering_points_verified,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND ((x.grid_owner_id IS NULL) OR (x.grid_area_code IS NULL) OR (x.price_area_code IS NULL)))) AS metering_points_missing_market_data,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE (x.company_id = c.id)) AS supplier_switch_requests_total,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['ready'::text, 'ready_to_execute'::text, 'queued_for_outbound'::text])))) AS supplier_switch_ready,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND ((x.status = ANY (ARRAY['blocked'::text, 'failed'::text, 'rejected'::text])) OR (x.lifecycle_blocked = true)))) AS supplier_switch_blocked_failed,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['confirmed'::text, 'completed'::text])))) AS supplier_switch_confirmed,
    ( SELECT count(*) AS count
           FROM public.powers_of_attorney x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['signed'::text, 'accepted'::text, 'active'::text, 'completed'::text])))) AS active_powers_of_attorney,
    ( SELECT count(*) AS count
           FROM public.contract_price_snapshots x
          WHERE (x.company_id = c.id)) AS contract_price_snapshots_total,
    ( SELECT count(*) AS count
           FROM public.ediel_business_errors x
          WHERE ((x.company_id = c.id) AND (x.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])))) AS business_errors_open,
    ( SELECT count(*) AS count
           FROM public.facility_data_quality_issues x
          WHERE ((x.company_id = c.id) AND (x.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])))) AS facility_data_quality_issues_open,
    ( SELECT count(*) AS count
           FROM public.communication_logs x
          WHERE (x.company_id = c.id)) AS communication_logs_total,
    ( SELECT count(*) AS count
           FROM public.communication_logs x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'bounced'::text])))) AS communication_logs_failed_bounced,
    ( SELECT count(*) AS count
           FROM public.integration_api_rate_limit_events x
          WHERE (x.company_id = c.id)) AS api_rate_limit_events,
    ( SELECT count(*) AS count
           FROM public.platform_actor_import_issues x
          WHERE (x.status = 'open'::text)) AS platform_import_issues_open,
    ( SELECT count(*) AS count
           FROM public.gridex_route_readiness_v x
          WHERE (x.readiness_status = ANY (ARRAY['critical_missing_route'::text, 'recommended_missing_route'::text, 'not_sendable'::text, 'needs_review'::text]))) AS route_missing_or_not_ready
   FROM public.companies c;

--
-- Name: gridex_company_route_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_company_route_readiness_v WITH (security_invoker='true') AS
 WITH company_sender AS (
         SELECT eas.id AS sender_settings_id,
            eas.company_id,
            eas.environment,
            eas.ediel_id,
            eas.actor_ediel_id,
            eas.role,
            eas.actor_role,
            eas.market_roles,
            eas.production_send_lock_enabled,
            eas.first_production_send_approved,
            eas.is_active
           FROM public.ediel_actor_settings eas
          WHERE (eas.is_active = true)
        ), grid_owner_actor AS (
         SELECT go.id AS grid_owner_id,
            go.name AS grid_owner_name,
            go.ediel_id AS grid_owner_ediel_id,
            go.platform_market_actor_id,
            pma.id AS platform_market_actor_id_resolved,
            pma.name AS platform_actor_name,
            pma.status AS platform_actor_status,
            pma.match_status
           FROM (public.grid_owners go
             LEFT JOIN public.platform_market_actors pma ON ((pma.id = go.platform_market_actor_id)))
          WHERE (COALESCE(go.is_active, true) = true)
        ), platform_routes AS (
         SELECT par.id AS platform_actor_route_id,
            par.actor_id,
            par.message_family,
            COALESCE((par.metadata ->> 'message_code'::text),
                CASE
                    WHEN (par.message_family = 'PRODAT'::text) THEN 'Z01'::text
                    ELSE NULL::text
                END) AS message_code,
            par.environment,
            par.communication_address,
            par.party_id,
            par.interchange_party_id,
            par.status,
            par.is_verified,
            par.auto_send_allowed
           FROM public.platform_actor_routes par
          WHERE (par.status = 'active'::text)
        ), matrix AS (
         SELECT cs.company_id,
            goa.grid_owner_id,
            goa.grid_owner_name,
            goa.grid_owner_ediel_id,
            goa.platform_market_actor_id,
            pr.platform_actor_route_id,
            pr.message_family,
            pr.message_code,
            pr.environment,
            cs.sender_settings_id,
            cs.production_send_lock_enabled,
            cs.first_production_send_approved,
            cmpr.id AS company_market_party_route_id,
            cmpr.communication_route_id AS cmpr_communication_route_id,
            cmpr.route_profile_id AS cmpr_route_profile_id
           FROM (((company_sender cs
             JOIN grid_owner_actor goa ON ((goa.platform_market_actor_id IS NOT NULL)))
             JOIN platform_routes pr ON (((pr.actor_id = goa.platform_market_actor_id) AND (pr.environment = cs.environment) AND (pr.message_family = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])))))
             LEFT JOIN public.company_market_party_routes cmpr ON (((cmpr.company_id = cs.company_id) AND (cmpr.market_party_id = pr.actor_id) AND (cmpr.message_family = pr.message_family) AND (COALESCE(cmpr.environment, (cmpr.metadata ->> 'environment'::text)) = pr.environment) AND (COALESCE(NULLIF(cmpr.message_code, ''::text), NULLIF((cmpr.metadata ->> 'message_code'::text), ''::text),
                CASE
                    WHEN (pr.message_family = 'PRODAT'::text) THEN 'Z01'::text
                    ELSE ''::text
                END) = COALESCE(pr.message_code, ''::text)) AND (COALESCE((cmpr.platform_actor_route_id)::text, (cmpr.metadata ->> 'platform_actor_route_id'::text)) = (pr.platform_actor_route_id)::text) AND (cmpr.active = true))))
          WHERE (cs.environment = ANY (ARRAY['test'::text, 'production'::text]))
        ), resolved AS (
         SELECT m.company_id,
            m.grid_owner_id,
            m.grid_owner_name,
            m.grid_owner_ediel_id,
            m.platform_market_actor_id,
            m.platform_actor_route_id,
            m.message_family,
            m.message_code,
            m.environment,
            m.sender_settings_id,
            m.production_send_lock_enabled,
            m.first_production_send_approved,
            m.company_market_party_route_id,
            m.cmpr_communication_route_id,
            m.cmpr_route_profile_id,
            cr.id AS communication_route_id,
            erp.id AS ediel_route_profile_id,
            COALESCE(cr.is_active, false) AS communication_route_active,
            COALESCE(erp.is_active, false) AS profile_active,
            COALESCE(erp.is_enabled, false) AS profile_enabled,
            COALESCE(erp.receiver_ediel_id, cr.counterparty_ediel_id, m.grid_owner_ediel_id) AS receiver_ediel_id,
            erp.receiver_certificate_id,
            erp.security_policy_status
           FROM ((matrix m
             LEFT JOIN public.communication_routes cr ON ((cr.id = m.cmpr_communication_route_id)))
             LEFT JOIN public.ediel_route_profiles erp ON ((erp.id = m.cmpr_route_profile_id)))
        )
 SELECT company_id,
    grid_owner_id,
    grid_owner_name,
    grid_owner_ediel_id,
    platform_market_actor_id,
    platform_actor_route_id,
    message_family,
    message_code,
    environment,
    true AS actor_registry_ready,
    true AS platform_route_ready,
    ((company_market_party_route_id IS NOT NULL) AND communication_route_active AND profile_active AND profile_enabled) AS operational_route_ready,
    ((company_market_party_route_id IS NOT NULL) AND communication_route_active AND profile_active AND profile_enabled AND (NOT ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false))) AND (receiver_ediel_id IS NOT NULL)) AS send_ready,
        CASE
            WHEN (company_market_party_route_id IS NULL) THEN 'platform_route_exists_but_not_materialized'::text
            WHEN (NOT communication_route_active) THEN 'communication_route_inactive'::text
            WHEN (NOT (profile_active AND profile_enabled)) THEN 'ediel_route_profile_inactive'::text
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'production_send_locked'::text
            WHEN (receiver_ediel_id IS NULL) THEN 'receiver_ediel_id_missing'::text
            ELSE NULL::text
        END AS blocker_code,
        CASE
            WHEN (company_market_party_route_id IS NULL) THEN 'Nätägaren är verifierad i aktörsregistret, men bolagets operativa route är inte materialiserad.'::text
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'Första produktionssändningen kräver platform-admins godkännande.'::text
            WHEN (receiver_ediel_id IS NULL) THEN 'Operativ route saknar mottagande Ediel-ID.'::text
            WHEN (NOT communication_route_active) THEN 'Communication route är inaktiv.'::text
            WHEN (NOT (profile_active AND profile_enabled)) THEN 'Ediel route profile är inaktiv.'::text
            ELSE 'Route är operativ och redo enligt grundkontroller.'::text
        END AS readiness_message,
    communication_route_id,
    ediel_route_profile_id,
    company_market_party_route_id,
    sender_settings_id,
        CASE
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'locked'::text
            WHEN (environment = 'production'::text) THEN 'approved'::text
            ELSE 'not_applicable'::text
        END AS production_send_lock_status
   FROM resolved;

--
-- Name: gridex_customer_contracts_missing_price_snapshot_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_customer_contracts_missing_price_snapshot_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    customer_id,
    site_id,
    metering_point_id,
    status,
    created_at
   FROM public.customer_contracts
  WHERE ((status = ANY (ARRAY['signed'::text, 'active'::text])) AND (contract_price_snapshot_id IS NULL));

--
-- Name: gridex_customer_identity_duplicate_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_customer_identity_duplicate_candidates_v WITH (security_invoker='true') AS
 SELECT customers.company_id,
    'personal_number'::text AS match_type,
    customers.normalized_personal_number AS match_key,
    count(*) AS customer_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.normalized_personal_number IS NOT NULL)
  GROUP BY customers.company_id, customers.normalized_personal_number
 HAVING (count(*) > 1)
UNION ALL
 SELECT customers.company_id,
    'organization_number'::text AS match_type,
    customers.normalized_org_number AS match_key,
    count(*) AS customer_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.normalized_org_number IS NOT NULL)
  GROUP BY customers.company_id, customers.normalized_org_number
 HAVING (count(*) > 1)
UNION ALL
 SELECT customers.company_id,
    'email_weak_signal'::text AS match_type,
    customers.normalized_email AS match_key,
    count(*) AS customer_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.normalized_email IS NOT NULL)
  GROUP BY customers.company_id, customers.normalized_email
 HAVING (count(*) > 1);

--
-- Name: gridex_data_cleanup_customer_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_data_cleanup_customer_candidates_v WITH (security_invoker='true') AS
 SELECT id AS customer_id,
    company_id,
    customer_number,
    COALESCE(NULLIF(full_name, ''::text), NULLIF(company_name, ''::text), concat_ws(' '::text, NULLIF(first_name, ''::text), NULLIF(last_name, ''::text)), 'Kund utan namn'::text) AS customer_name,
    email,
    source,
    status,
    is_test_data,
    archived_at,
    created_at,
        CASE
            WHEN is_test_data THEN 'markerad_testdata'::text
            WHEN (lower(COALESCE(source, ''::text)) ~~ '%test%'::text) THEN 'källa_indikerar_test'::text
            WHEN (lower(COALESCE(public.gridex_customer_cleanup_external_ref(id), ''::text)) ~~ 'web-test%'::text) THEN 'extern_id_indikerar_test'::text
            WHEN (lower(COALESCE(public.gridex_customer_cleanup_external_ref(id), ''::text)) ~~ 'web-incomplete%'::text) THEN 'ofullständig_webbansökan'::text
            WHEN (lower(COALESCE(email, ''::text)) ~~ '%example.%'::text) THEN 'exempeladress'::text
            WHEN (lower(COALESCE(email, ''::text)) ~~ '%test%'::text) THEN 'testadress'::text
            ELSE 'manuell_granskning'::text
        END AS cleanup_reason,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE (s.customer_id = c.id)) AS site_count,
    ( SELECT count(*) AS count
           FROM public.customer_contracts cc
          WHERE (cc.customer_id = c.id)) AS contract_count,
    ( SELECT count(*) AS count
           FROM public.customer_contracts cc
          WHERE ((cc.customer_id = c.id) AND (COALESCE(cc.status, ''::text) = ANY (ARRAY['active'::text, 'signed'::text, 'confirmed'::text, 'switch_requested'::text])))) AS protected_contract_count,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests ssr
          WHERE (ssr.customer_id = c.id)) AS switch_count,
    ( SELECT count(*) AS count
           FROM public.billing_underlays bu
          WHERE (bu.customer_id = c.id)) AS billing_underlay_count,
    ( SELECT count(*) AS count
           FROM public.customer_invoices ci
          WHERE (ci.customer_id = c.id)) AS invoice_count,
    ( SELECT count(*) AS count
           FROM public.ediel_messages em
          WHERE (em.customer_id = c.id)) AS ediel_message_count,
    ((( SELECT count(*) AS count
           FROM public.customer_contracts cc
          WHERE ((cc.customer_id = c.id) AND (COALESCE(cc.status, ''::text) = ANY (ARRAY['active'::text, 'signed'::text, 'confirmed'::text, 'switch_requested'::text])))) = 0) AND (( SELECT count(*) AS count
           FROM public.supplier_switch_requests ssr
          WHERE (ssr.customer_id = c.id)) = 0) AND (( SELECT count(*) AS count
           FROM public.billing_underlays bu
          WHERE (bu.customer_id = c.id)) = 0) AND (( SELECT count(*) AS count
           FROM public.customer_invoices ci
          WHERE (ci.customer_id = c.id)) = 0) AND (( SELECT count(*) AS count
           FROM public.ediel_messages em
          WHERE (em.customer_id = c.id)) = 0)) AS can_hard_delete
   FROM public.customers c;

--
-- Name: VIEW gridex_data_cleanup_customer_candidates_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_data_cleanup_customer_candidates_v IS 'Platform-admin read model for previewing test customers and safe archive/delete decisions.';

--
-- Name: gridex_data_retention_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gridex_data_retention_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    data_category text NOT NULL,
    retention_days integer NOT NULL,
    action text NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gridex_data_retention_policies_action_check CHECK ((action = ANY (ARRAY['delete'::text, 'mask'::text, 'archive'::text]))),
    CONSTRAINT gridex_data_retention_policies_retention_days_check CHECK (((retention_days >= 1) AND (retention_days <= 3650)))
);

--
-- Name: gridex_db1_duplicate_customer_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_duplicate_customer_candidates_v WITH (security_invoker='true') AS
 SELECT customers.company_id,
    'email'::text AS match_type,
    customers.normalized_email AS match_key,
    count(*) AS duplicate_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.normalized_email IS NOT NULL)
  GROUP BY customers.company_id, customers.normalized_email
 HAVING (count(*) > 1)
UNION ALL
 SELECT customers.company_id,
    'personal_number'::text AS match_type,
    customers.normalized_personal_number AS match_key,
    count(*) AS duplicate_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.normalized_personal_number IS NOT NULL)
  GROUP BY customers.company_id, customers.normalized_personal_number
 HAVING (count(*) > 1)
UNION ALL
 SELECT customers.company_id,
    'customer_number'::text AS match_type,
    customers.customer_number AS match_key,
    count(*) AS duplicate_count,
    array_agg(customers.id ORDER BY customers.created_at) AS customer_ids
   FROM public.customers
  WHERE (customers.customer_number IS NOT NULL)
  GROUP BY customers.company_id, customers.customer_number
 HAVING (count(*) > 1);

--
-- Name: gridex_db1_duplicate_metering_point_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_duplicate_metering_point_candidates_v WITH (security_invoker='true') AS
 SELECT company_id,
    normalized_metering_point_id AS match_key,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at) AS metering_point_ids
   FROM public.metering_points
  WHERE (normalized_metering_point_id IS NOT NULL)
  GROUP BY company_id, normalized_metering_point_id
 HAVING (count(*) > 1);

--
-- Name: gridex_db1_duplicate_site_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_duplicate_site_candidates_v WITH (security_invoker='true') AS
 SELECT company_id,
    normalized_facility_id AS match_key,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at) AS site_ids
   FROM public.customer_sites
  WHERE (normalized_facility_id IS NOT NULL)
  GROUP BY company_id, normalized_facility_id
 HAVING (count(*) > 1);

--
-- Name: gridex_db1_rls_policy_gap_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_rls_policy_gap_v WITH (security_invoker='true') AS
 SELECT n.nspname AS schema_name,
    c.relname AS table_name,
    c.relrowsecurity AS rls_enabled,
    (EXISTS ( SELECT 1
           FROM pg_policies p
          WHERE ((p.schemaname = n.nspname) AND (p.tablename = c.relname)))) AS has_policy
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND (c.relname = ANY (ARRAY['companies'::name, 'company_memberships'::name, 'customers'::name, 'customer_sites'::name, 'metering_points'::name, 'powers_of_attorney'::name, 'supplier_switch_requests'::name, 'ediel_messages'::name, 'billing_export_runs'::name, 'billing_underlays'::name, 'outbound_requests'::name, 'audit_logs'::name])))
  ORDER BY c.relname;

--
-- Name: gridex_db1_schema_gap_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_schema_gap_v WITH (security_invoker='true') AS
 WITH expected(object_type, object_name, required_for) AS (
         VALUES ('table'::text,'companies'::text,'tenant'::text), ('table'::text,'company_memberships'::text,'tenant'::text), ('table'::text,'company_invitations'::text,'tenant'::text), ('table'::text,'customers'::text,'customer_core'::text), ('table'::text,'customer_addresses'::text,'customer_core'::text), ('table'::text,'customer_contacts'::text,'customer_core'::text), ('table'::text,'customer_internal_notes'::text,'customer_core'::text), ('table'::text,'customer_sites'::text,'operations'::text), ('table'::text,'metering_points'::text,'operations'::text), ('table'::text,'powers_of_attorney'::text,'authorization'::text), ('table'::text,'customer_authorization_documents'::text,'authorization'::text), ('table'::text,'supplier_switch_requests'::text,'supplier_switch'::text), ('table'::text,'supplier_switch_events'::text,'supplier_switch'::text), ('table'::text,'grid_owners'::text,'masterdata'::text), ('table'::text,'electricity_suppliers'::text,'masterdata'::text), ('table'::text,'price_areas'::text,'masterdata'::text), ('table'::text,'price_area_localities'::text,'masterdata'::text), ('table'::text,'communication_routes'::text,'outbound'::text), ('table'::text,'grid_owner_data_requests'::text,'outbound'::text), ('table'::text,'outbound_requests'::text,'outbound'::text), ('table'::text,'outbound_dispatch_events'::text,'outbound'::text), ('table'::text,'ediel_actor_settings'::text,'ediel'::text), ('table'::text,'ediel_route_profiles'::text,'ediel'::text), ('table'::text,'ediel_message_rules'::text,'ediel'::text), ('table'::text,'ediel_messages'::text,'ediel'::text), ('table'::text,'ediel_message_events'::text,'ediel'::text), ('table'::text,'ediel_message_validation_issues'::text,'ediel'::text), ('table'::text,'billing_underlays'::text,'billing'::text), ('table'::text,'billing_export_runs'::text,'billing'::text), ('table'::text,'billing_export_run_items'::text,'billing'::text), ('table'::text,'partner_exports'::text,'billing'::text), ('table'::text,'audit_logs'::text,'audit'::text), ('table'::text,'backfill_runs'::text,'backfill'::text), ('table'::text,'canonical_record_links'::text,'backfill'::text), ('view'::text,'ediel_route_runtime_v'::text,'ediel'::text), ('view'::text,'ediel_message_ack_state_v'::text,'ediel'::text), ('view'::text,'ediel_overdue_message_acks_v'::text,'ediel'::text), ('view'::text,'ediel_duplicate_ack_candidates_v'::text,'ediel'::text), ('view'::text,'ediel_rule_ambiguities_v'::text,'ediel'::text)
        )
 SELECT object_type,
    object_name,
    required_for,
    (to_regclass(('public.'::text || object_name)) IS NOT NULL) AS exists_in_database,
        CASE
            WHEN (to_regclass(('public.'::text || object_name)) IS NULL) THEN 'missing'::text
            ELSE 'ok'::text
        END AS status
   FROM expected
  ORDER BY required_for, object_type, object_name;

--
-- Name: gridex_db1_storage_gap_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_storage_gap_v WITH (security_invoker='true') AS
 WITH expected(bucket_id) AS (
         VALUES ('customer-documents'::text), ('contract-pdfs'::text), ('customer-intake'::text), ('billing-imports'::text), ('billing-exports'::text), ('ediel-files'::text), ('actor-test-evidence'::text)
        )
 SELECT e.bucket_id,
    (b.id IS NOT NULL) AS exists_in_storage,
    COALESCE(b.public, false) AS is_public,
    b.file_size_limit,
    b.allowed_mime_types
   FROM (expected e
     LEFT JOIN storage.buckets b ON ((b.id = e.bucket_id)))
  ORDER BY e.bucket_id;

--
-- Name: gridex_db1_tenant_gap_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_tenant_gap_v WITH (security_invoker='true') AS
 SELECT 'customer_contracts'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.customer_contracts
  WHERE (customer_contracts.company_id IS NULL)
UNION ALL
 SELECT 'customers'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.customers
  WHERE (customers.company_id IS NULL)
UNION ALL
 SELECT 'customer_sites'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.customer_sites
  WHERE (customer_sites.company_id IS NULL)
UNION ALL
 SELECT 'metering_points'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.metering_points
  WHERE (metering_points.company_id IS NULL)
UNION ALL
 SELECT 'powers_of_attorney'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.powers_of_attorney
  WHERE (powers_of_attorney.company_id IS NULL)
UNION ALL
 SELECT 'supplier_switch_requests'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.supplier_switch_requests
  WHERE (supplier_switch_requests.company_id IS NULL)
UNION ALL
 SELECT 'ediel_messages'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.ediel_messages
  WHERE (ediel_messages.company_id IS NULL)
UNION ALL
 SELECT 'billing_underlays'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.billing_underlays
  WHERE (billing_underlays.company_id IS NULL)
UNION ALL
 SELECT 'billing_export_runs'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.billing_export_runs
  WHERE (billing_export_runs.company_id IS NULL)
UNION ALL
 SELECT 'outbound_requests'::text AS table_name,
    count(*) AS rows_without_company_id
   FROM public.outbound_requests
  WHERE (outbound_requests.company_id IS NULL);

--
-- Name: gridex_db1_backfill_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_backfill_readiness_v WITH (security_invoker='true') AS
 SELECT 'schema_gap'::text AS check_key,
    count(*) AS issue_count,
    'missing expected tables/views'::text AS description
   FROM public.gridex_db1_schema_gap_v
  WHERE (gridex_db1_schema_gap_v.exists_in_database = false)
UNION ALL
 SELECT 'tenant_gap'::text AS check_key,
    (COALESCE(sum(gridex_db1_tenant_gap_v.rows_without_company_id), (0)::numeric))::bigint AS issue_count,
    'rows missing company_id'::text AS description
   FROM public.gridex_db1_tenant_gap_v
UNION ALL
 SELECT 'duplicate_customers'::text AS check_key,
    count(*) AS issue_count,
    'duplicate customer candidates'::text AS description
   FROM public.gridex_db1_duplicate_customer_candidates_v
UNION ALL
 SELECT 'duplicate_sites'::text AS check_key,
    count(*) AS issue_count,
    'duplicate site candidates'::text AS description
   FROM public.gridex_db1_duplicate_site_candidates_v
UNION ALL
 SELECT 'duplicate_metering_points'::text AS check_key,
    count(*) AS issue_count,
    'duplicate metering point candidates'::text AS description
   FROM public.gridex_db1_duplicate_metering_point_candidates_v
UNION ALL
 SELECT 'storage_gap'::text AS check_key,
    count(*) AS issue_count,
    'missing storage buckets'::text AS description
   FROM public.gridex_db1_storage_gap_v
  WHERE (gridex_db1_storage_gap_v.exists_in_storage = false)
UNION ALL
 SELECT 'rls_policy_gap'::text AS check_key,
    count(*) AS issue_count,
    'important tables without RLS/policies'::text AS description
   FROM public.gridex_db1_rls_policy_gap_v
  WHERE ((gridex_db1_rls_policy_gap_v.rls_enabled = false) OR (gridex_db1_rls_policy_gap_v.has_policy = false));

--
-- Name: gridex_db1_rbac_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_db1_rbac_health_v WITH (security_invoker='true') AS
 SELECT 'user_roles_table'::text AS check_key,
    ((to_regclass('public.user_roles'::text) IS NOT NULL))::text AS result,
    NULL::text AS details
UNION ALL
 SELECT 'roles_table'::text AS check_key,
    ((to_regclass('public.roles'::text) IS NOT NULL))::text AS result,
    NULL::text AS details
UNION ALL
 SELECT 'user_roles_has_role_id'::text AS check_key,
    ((EXISTS ( SELECT 1
           FROM information_schema.columns
          WHERE (((columns.table_schema)::name = 'public'::name) AND ((columns.table_name)::name = 'user_roles'::name) AND ((columns.column_name)::name = 'role_id'::name)))))::text AS result,
    NULL::text AS details
UNION ALL
 SELECT 'user_roles_has_role_text'::text AS check_key,
    ((EXISTS ( SELECT 1
           FROM information_schema.columns
          WHERE (((columns.table_schema)::name = 'public'::name) AND ((columns.table_name)::name = 'user_roles'::name) AND ((columns.column_name)::name = 'role'::name)))))::text AS result,
    NULL::text AS details
UNION ALL
 SELECT 'company_memberships_table'::text AS check_key,
    ((to_regclass('public.company_memberships'::text) IS NOT NULL))::text AS result,
    NULL::text AS details
UNION ALL
 SELECT 'rbac_helper_platform_admin_callable'::text AS check_key,
    'true'::text AS result,
    'function recreated in DB1'::text AS details;

--
-- Name: gridex_duplicate_index_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_duplicate_index_candidates_v WITH (security_invoker='true') AS
 WITH index_catalog AS (
         SELECT ns.nspname AS schema_name,
            tbl.relname AS table_name,
            idx.relname AS index_name,
            i.indexrelid,
            i.indisunique,
            i.indisprimary,
            i.indisexclusion,
            i.indimmediate,
            i.indisvalid,
            i.indnkeyatts,
            i.indnatts,
            am.amname AS access_method,
            (i.indkey)::text AS indkey,
            COALESCE(pg_get_expr(i.indexprs, i.indrelid), ''::text) AS indexprs,
            COALESCE(pg_get_expr(i.indpred, i.indrelid), ''::text) AS indpred,
            (i.indcollation)::text AS indcollation,
            (i.indclass)::text AS indclass,
            (i.indoption)::text AS indoption,
            (EXISTS ( SELECT 1
                   FROM pg_constraint c
                  WHERE (c.conindid = i.indexrelid))) AS backs_constraint
           FROM ((((pg_index i
             JOIN pg_class idx ON ((idx.oid = i.indexrelid)))
             JOIN pg_class tbl ON ((tbl.oid = i.indrelid)))
             JOIN pg_namespace ns ON ((ns.oid = tbl.relnamespace)))
             JOIN pg_am am ON ((am.oid = idx.relam)))
          WHERE ((ns.nspname = 'public'::name) AND (NOT i.indisprimary) AND i.indisvalid)
        ), duplicate_groups AS (
         SELECT index_catalog.schema_name,
            index_catalog.table_name,
            index_catalog.indisunique,
            index_catalog.indisprimary,
            index_catalog.indisexclusion,
            index_catalog.indimmediate,
            index_catalog.indnkeyatts,
            index_catalog.indnatts,
            index_catalog.access_method,
            index_catalog.indkey,
            index_catalog.indexprs,
            index_catalog.indpred,
            index_catalog.indcollation,
            index_catalog.indclass,
            index_catalog.indoption,
            array_agg(index_catalog.index_name ORDER BY index_catalog.backs_constraint DESC, (length((index_catalog.index_name)::text)), index_catalog.index_name) AS index_names,
            count(*) AS index_count
           FROM index_catalog
          GROUP BY index_catalog.schema_name, index_catalog.table_name, index_catalog.indisunique, index_catalog.indisprimary, index_catalog.indisexclusion, index_catalog.indimmediate, index_catalog.indnkeyatts, index_catalog.indnatts, index_catalog.access_method, index_catalog.indkey, index_catalog.indexprs, index_catalog.indpred, index_catalog.indcollation, index_catalog.indclass, index_catalog.indoption
         HAVING (count(*) > 1)
        )
 SELECT schema_name,
    table_name,
    indisunique,
    indisprimary,
    indisexclusion,
    indimmediate,
    indnkeyatts,
    indnatts,
    access_method,
    indkey,
    indexprs,
    indpred,
    indcollation,
    indclass,
    indoption,
    index_names,
    index_count
   FROM duplicate_groups;

--
-- Name: platform_grid_area_geometries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_grid_area_geometries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    grid_area_id uuid,
    grid_area_code text NOT NULL,
    source_feature_id text,
    source text DEFAULT 'svk_arcgis'::text NOT NULL,
    source_url text,
    source_properties jsonb DEFAULT '{}'::jsonb NOT NULL,
    geometry extensions.geometry(MultiPolygon,3006),
    geometry_geojson jsonb,
    is_active boolean DEFAULT true NOT NULL,
    valid_from date,
    valid_to date,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    geodata_version_id uuid
);

--
-- Name: COLUMN platform_grid_area_geometries.geodata_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_grid_area_geometries.geodata_version_id IS 'Verified geodata version that atomically published this active polygon. Previous versions are deactivated during promotion.';

--
-- Name: platform_grid_areas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_grid_areas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    grid_area_code text NOT NULL,
    grid_area_name text,
    grid_owner_id uuid,
    grid_owner_name text,
    price_area text,
    source text DEFAULT 'svk_esett'::text NOT NULL,
    source_version text,
    is_active boolean DEFAULT true NOT NULL,
    valid_from date,
    valid_to date,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_grid_areas_price_area_check CHECK (((price_area IS NULL) OR (price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))))
);

--
-- Name: gridex_energy_geodata_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_energy_geodata_health_v WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM public.platform_grid_areas) AS grid_areas_total,
    ( SELECT count(*) AS count
           FROM public.platform_grid_area_geometries) AS grid_area_geometries_total,
    GREATEST((( SELECT count(*) AS count
           FROM public.platform_grid_areas) - ( SELECT count(*) AS count
           FROM public.platform_grid_area_geometries)), (0)::bigint) AS grid_areas_without_geometry,
        CASE
            WHEN (to_regclass('public.platform_grid_area_geometries'::text) IS NULL) THEN 'missing_geometry_table'::text
            WHEN (( SELECT count(*) AS count
               FROM public.platform_grid_area_geometries) = 0) THEN 'geometry_import_required'::text
            WHEN (GREATEST((( SELECT count(*) AS count
               FROM public.platform_grid_areas) - ( SELECT count(*) AS count
               FROM public.platform_grid_area_geometries)), (0)::bigint) > 0) THEN 'partial_geometry_coverage'::text
            ELSE 'ready'::text
        END AS status,
    'Postnummer/adressfallback får endast vara förslag tills polygongeometrier är importerade och verifierade.'::text AS policy;

--
-- Name: gridex_energy_resolutions_needing_review_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_energy_resolutions_needing_review_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    customer_id,
    customer_site_id,
    customer_application_id,
    grid_owner_id,
    grid_area_code,
    grid_area_name,
    grid_owner_name,
    price_area,
    resolution_status,
    confidence,
    source_chain,
    input_snapshot,
    result_snapshot,
    automation_allowed,
    next_required_action,
    facility_data_verified_at,
    verified_by,
    created_at,
    updated_at,
    resolved_at,
    expires_at,
    resolver_version,
    geodata_version,
    source_claims,
    conflict_code
   FROM public.customer_site_resolution
  WHERE ((resolution_status = ANY (ARRAY['needs_review'::text, 'failed'::text])) OR (automation_allowed = false) OR (expires_at <= now()));

--
-- Name: gridex_route_materialization_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_route_materialization_readiness_v WITH (security_invoker='true') AS
 SELECT g.company_id,
    g.id AS grid_owner_id,
    g.name AS grid_owner_name,
    g.platform_market_actor_id,
    r.id AS platform_actor_route_id,
    upper(COALESCE(r.message_family, 'PRODAT'::text)) AS message_family,
    COALESCE((r.metadata ->> 'message_code'::text),
        CASE
            WHEN (upper(COALESCE(r.message_family, 'PRODAT'::text)) = 'PRODAT'::text) THEN 'Z01'::text
            ELSE NULL::text
        END) AS message_code,
    COALESCE(r.environment, 'production'::text) AS environment,
    ((g.platform_market_actor_id IS NOT NULL) AND (COALESCE(g.verification_status, ''::text) = ANY (ARRAY['verified'::text, 'needs_route'::text, 'needs_certificate'::text, 'needs_contact'::text, 'needs_subaddress'::text]))) AS actor_registry_ready,
    ((r.id IS NOT NULL) AND (COALESCE(r.status, ''::text) = 'active'::text) AND (COALESCE(r.is_verified, false) = true)) AS platform_route_ready,
    ((cr.id IS NOT NULL) AND (COALESCE(cr.is_active, true) = true) AND (rp.id IS NOT NULL) AND (COALESCE(rp.is_enabled, true) = true) AND (COALESCE(rp.is_active, true) = true) AND (COALESCE((cr.environment_type)::text, rp.environment, r.environment) = COALESCE(r.environment, 'production'::text))) AS operational_route_ready,
    ((cr.id IS NOT NULL) AND (rp.id IS NOT NULL) AND (NULLIF(btrim(COALESCE(rp.sender_ediel_id, ''::text)), ''::text) IS NOT NULL) AND (NULLIF(btrim(COALESCE(rp.receiver_ediel_id, g.ediel_id, ''::text)), ''::text) IS NOT NULL) AND (NULLIF(btrim(COALESCE(cr.target_email, ''::text)), ''::text) IS NOT NULL) AND (NOT ((COALESCE(eas.production_send_lock_enabled, false) = true) AND (COALESCE(eas.first_production_send_approved, false) = false) AND (COALESCE(r.environment, 'production'::text) = 'production'::text)))) AS send_ready,
        CASE
            WHEN ((r.id IS NOT NULL) AND (cr.id IS NULL)) THEN 'platform_route_exists_but_not_materialized'::text
            WHEN (cr.id IS NULL) THEN 'operational_route_missing'::text
            WHEN (rp.id IS NULL) THEN 'operational_route_missing'::text
            WHEN (COALESCE((cr.environment_type)::text, rp.environment, r.environment) <> COALESCE(r.environment, 'production'::text)) THEN 'environment_mismatch'::text
            WHEN ((COALESCE(eas.production_send_lock_enabled, false) = true) AND (COALESCE(eas.first_production_send_approved, false) = false) AND (COALESCE(r.environment, 'production'::text) = 'production'::text)) THEN 'production_send_locked'::text
            ELSE NULL::text
        END AS blocker_code,
        CASE
            WHEN ((r.id IS NOT NULL) AND (cr.id IS NULL)) THEN 'Nätägaren är verifierad i aktörsregistret, men operativ route saknas.'::text
            WHEN ((cr.id IS NULL) OR (rp.id IS NULL)) THEN 'Operativ route eller route profile saknas.'::text
            WHEN (COALESCE((cr.environment_type)::text, rp.environment, r.environment) <> COALESCE(r.environment, 'production'::text)) THEN 'Miljö stämmer inte mellan aktörsregister, communication route och route profile.'::text
            WHEN ((COALESCE(eas.production_send_lock_enabled, false) = true) AND (COALESCE(eas.first_production_send_approved, false) = false) AND (COALESCE(r.environment, 'production'::text) = 'production'::text)) THEN 'Första produktionssändningen kräver plattformsadministratörens godkännande.'::text
            ELSE 'Routekedjan är redo.'::text
        END AS readiness_message,
    cr.id AS communication_route_id,
    rp.id AS ediel_route_profile_id,
    cmpr.id AS company_market_party_route_id,
    eas.id AS sender_settings_id
   FROM (((((public.grid_owners g
     LEFT JOIN public.platform_actor_routes r ON (((r.actor_id = g.platform_market_actor_id) AND (COALESCE(r.status, ''::text) = 'active'::text) AND (COALESCE(r.is_verified, false) = true))))
     LEFT JOIN public.communication_routes cr ON (((cr.company_id = g.company_id) AND (cr.grid_owner_id = g.id) AND ((cr.auth_config ->> 'platform_actor_route_id'::text) = (r.id)::text))))
     LEFT JOIN public.ediel_route_profiles rp ON (((rp.company_id = g.company_id) AND (rp.communication_route_id = cr.id) AND ((rp.metadata ->> 'platform_actor_route_id'::text) = (r.id)::text))))
     LEFT JOIN public.company_market_party_routes cmpr ON (((cmpr.company_id = g.company_id) AND (cmpr.market_party_id = g.platform_market_actor_id) AND (upper(cmpr.message_family) = upper(COALESCE(r.message_family, 'PRODAT'::text))) AND (cmpr.active = true) AND (COALESCE((cmpr.metadata ->> 'environment'::text), COALESCE(r.environment, 'production'::text)) = COALESCE(r.environment, 'production'::text)) AND (COALESCE((cmpr.metadata ->> 'message_code'::text), COALESCE((r.metadata ->> 'message_code'::text), ''::text)) = COALESCE((r.metadata ->> 'message_code'::text), COALESCE((cmpr.metadata ->> 'message_code'::text), ''::text))))))
     LEFT JOIN public.ediel_actor_settings eas ON (((eas.company_id = g.company_id) AND (eas.environment = COALESCE(r.environment, 'production'::text)) AND (COALESCE(eas.is_active, true) = true))))
  WHERE (g.platform_market_actor_id IS NOT NULL);

--
-- Name: gridex_energy_route_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_energy_route_health_v WITH (security_invoker='true') AS
 SELECT 'grid_areas_total'::text AS check_key,
    count(*) AS check_count,
        CASE
            WHEN (count(*) = 0) THEN 'critical'::text
            ELSE 'ok'::text
        END AS status
   FROM public.platform_grid_areas
UNION ALL
 SELECT 'grid_area_geometries_total'::text AS check_key,
    count(*) AS check_count,
        CASE
            WHEN (count(*) = 0) THEN 'critical'::text
            ELSE 'ok'::text
        END AS status
   FROM public.platform_grid_area_geometries
UNION ALL
 SELECT 'grid_areas_without_geometry'::text AS check_key,
    count(*) AS check_count,
        CASE
            WHEN (count(*) > 0) THEN 'warning'::text
            ELSE 'ok'::text
        END AS status
   FROM public.platform_grid_areas ga
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.platform_grid_area_geometries gg
          WHERE ((gg.grid_area_code = ga.grid_area_code) AND (COALESCE(gg.is_active, true) = true)))))
UNION ALL
 SELECT 'verified_platform_routes_without_operational_route'::text AS check_key,
    count(*) AS check_count,
        CASE
            WHEN (count(*) > 0) THEN 'warning'::text
            ELSE 'ok'::text
        END AS status
   FROM public.gridex_route_materialization_readiness_v
  WHERE ((gridex_route_materialization_readiness_v.platform_route_ready = true) AND (gridex_route_materialization_readiness_v.operational_route_ready = false))
UNION ALL
 SELECT 'company_routes_without_operational_route'::text AS check_key,
    count(*) AS check_count,
        CASE
            WHEN (count(*) > 0) THEN 'warning'::text
            ELSE 'ok'::text
        END AS status
   FROM public.gridex_company_route_readiness_v
  WHERE ((gridex_company_route_readiness_v.platform_route_ready = true) AND (gridex_company_route_readiness_v.operational_route_ready = false));

--
-- Name: gridex_grid_owner_business_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_grid_owner_business_readiness_v WITH (security_invoker='true') AS
 SELECT company_id,
    grid_owner_id,
    grid_owner_name,
    grid_owner_ediel_id,
    platform_market_actor_id,
    platform_actor_route_id,
    message_family,
    message_code,
    environment,
    actor_registry_ready,
    platform_route_ready,
    operational_route_ready,
    send_ready,
    blocker_code,
    readiness_message,
    communication_route_id,
    ediel_route_profile_id,
    company_market_party_route_id,
    sender_settings_id,
    production_send_lock_status,
        CASE
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%dummy%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%test%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%systemleverantör%'::text)) THEN 'dummy'::text
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%svenska kraftnät%'::text) OR (COALESCE(grid_owner_ediel_id, ''::text) = '10000'::text)) THEN 'system_actor'::text
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%gas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%swedegas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%weum%'::text)) THEN 'gas'::text
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%industri%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%billerud%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%ovako%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%bruk%'::text)) THEN 'industrial'::text
            WHEN (grid_owner_id IS NOT NULL) THEN 'electricity_grid_owner'::text
            ELSE 'unknown'::text
        END AS actor_scope,
    COALESCE(send_ready, false) AS technical_send_ready,
        CASE
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%dummy%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%test%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%systemleverantör%'::text)) THEN false
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%gas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%swedegas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%weum%'::text)) THEN false
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%svenska kraftnät%'::text) OR (COALESCE(grid_owner_ediel_id, ''::text) = '10000'::text)) THEN false
            WHEN ((COALESCE(send_ready, false) = true) AND (grid_owner_id IS NOT NULL) AND (blocker_code IS NULL)) THEN true
            ELSE false
        END AS business_production_approved,
        CASE
            WHEN ((lower(COALESCE(grid_owner_name, ''::text)) ~~ '%dummy%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%test%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%systemleverantör%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%gas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%swedegas%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%weum%'::text) OR (lower(COALESCE(grid_owner_name, ''::text)) ~~ '%svenska kraftnät%'::text) OR (COALESCE(grid_owner_ediel_id, ''::text) = '10000'::text)) THEN true
            ELSE false
        END AS excluded_from_standard_customer_flows,
        CASE
            WHEN ((message_family = 'PRODAT'::text) AND (message_code = 'Z01'::text)) THEN 'facility_lookup'::text
            WHEN (message_family = 'PRODAT'::text) THEN 'prodat_customer_process'::text
            WHEN (message_family = 'UTILTS'::text) THEN 'metering_values'::text
            ELSE 'unknown'::text
        END AS process_scope
   FROM public.gridex_company_route_readiness_v gr;

--
-- Name: VIEW gridex_grid_owner_business_readiness_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_grid_owner_business_readiness_v IS 'Business-level grid owner readiness for automatic customer intake. technical_send_ready can be true while business_production_approved is false for dummy, gas, system or special actors.';

--
-- Name: gridex_grid_owner_duplicate_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_grid_owner_duplicate_v WITH (security_invoker='true') AS
 WITH base AS (
         SELECT g_1.id,
            g_1.name,
            g_1.ediel_id,
            g_1.org_number,
                CASE
                    WHEN (NULLIF(btrim(COALESCE(g_1.ediel_id, ''::text)), ''::text) IS NOT NULL) THEN ('ediel:'::text || lower(btrim(g_1.ediel_id)))
                    WHEN (NULLIF(regexp_replace(COALESCE(g_1.org_number, ''::text), '[^0-9]'::text, ''::text, 'g'::text), ''::text) IS NOT NULL) THEN ('org:'::text || regexp_replace(g_1.org_number, '[^0-9]'::text, ''::text, 'g'::text))
                    ELSE NULL::text
                END AS duplicate_key
           FROM public.grid_owners g_1
        ), grouped AS (
         SELECT base.duplicate_key,
            (count(*))::integer AS duplicate_count,
            array_agg(base.id ORDER BY base.name) AS duplicate_ids
           FROM base
          WHERE (base.duplicate_key IS NOT NULL)
          GROUP BY base.duplicate_key
        )
 SELECT b.id AS grid_owner_id,
    b.name,
    b.ediel_id,
    b.org_number,
    b.duplicate_key,
    COALESCE(g.duplicate_count, 1) AS duplicate_count,
    COALESCE(g.duplicate_ids, ARRAY[b.id]) AS duplicate_ids
   FROM (base b
     LEFT JOIN grouped g ON ((g.duplicate_key = b.duplicate_key)));

--
-- Name: VIEW gridex_grid_owner_duplicate_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_grid_owner_duplicate_v IS 'Canonical grid-owner duplicate projection. Only verified canonical identity surfaces (Ediel ID or normalized organization number) produce duplicate keys; display names never authorize duplicate classification.';

--
-- Name: gridex_grid_owner_verification_status_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_grid_owner_verification_status_v WITH (security_invoker='true') AS
 WITH actor_base AS (
         SELECT a_1.id AS actor_id,
            a_1.name,
            a_1.org_number,
            a_1.status,
            a_1.match_status,
            a_1.visible_to_tenants,
            a_1.updated_at,
            max(i.identifier_value) FILTER (WHERE (i.identifier_type = 'EdielId'::text)) AS ediel_id,
            bool_or((r_1.actor_role = ANY (ARRAY['grid_owner'::text, 'netowner'::text, 'network_owner'::text]))) AS has_grid_owner_role
           FROM ((public.platform_market_actors a_1
             LEFT JOIN public.platform_actor_roles r_1 ON (((r_1.actor_id = a_1.id) AND COALESCE(r_1.is_active, true))))
             LEFT JOIN public.platform_actor_identifiers i ON ((i.actor_id = a_1.id)))
          GROUP BY a_1.id, a_1.name, a_1.org_number, a_1.status, a_1.match_status, a_1.visible_to_tenants, a_1.updated_at
        ), route_base AS (
         SELECT platform_actor_routes.actor_id,
            bool_or((upper(platform_actor_routes.message_family) = 'PRODAT'::text)) AS has_prodat_route,
            bool_or((upper(platform_actor_routes.message_family) = 'UTILTS'::text)) AS has_utilts_route,
            bool_or((COALESCE(platform_actor_routes.communication_address, ''::text) <> ''::text)) AS has_contact_path,
            bool_or((COALESCE(platform_actor_routes.is_verified, false) OR (platform_actor_routes.status = ANY (ARRAY['active'::text, 'verified'::text])))) AS has_verified_route,
            bool_or(COALESCE(platform_actor_routes.auto_send_allowed, false)) AS has_auto_send_route,
            (count(*))::integer AS route_count
           FROM public.platform_actor_routes
          GROUP BY platform_actor_routes.actor_id
        )
 SELECT a.actor_id,
    a.name,
    a.org_number,
    a.ediel_id,
    a.status,
    a.match_status,
    a.visible_to_tenants,
    COALESCE(a.has_grid_owner_role, false) AS has_grid_owner_role,
    COALESCE(r.has_prodat_route, false) AS has_prodat_route,
    COALESCE(r.has_utilts_route, false) AS has_utilts_route,
    COALESCE(r.has_contact_path, false) AS has_contact_path,
    COALESCE(r.has_verified_route, false) AS has_verified_route,
    COALESCE(r.has_auto_send_route, false) AS has_auto_send_route,
    COALESCE(r.route_count, 0) AS route_count,
        CASE
            WHEN (NOT COALESCE(a.has_grid_owner_role, false)) THEN 'inte_nätägare'::text
            WHEN ((a.ediel_id IS NULL) OR (btrim(a.ediel_id) = ''::text)) THEN 'saknar_ediel_id'::text
            WHEN ((NOT COALESCE(r.has_prodat_route, false)) AND (NOT COALESCE(r.has_utilts_route, false))) THEN 'saknar_route'::text
            WHEN (NOT COALESCE(r.has_contact_path, false)) THEN 'saknar_kontaktväg'::text
            WHEN ((a.match_status = 'verified'::text) AND COALESCE(r.has_verified_route, false)) THEN 'verifierad'::text
            WHEN (a.match_status = 'verified'::text) THEN 'delvis_verifierad'::text
            ELSE 'kräver_manuell_kontroll'::text
        END AS verification_status,
        CASE
            WHEN ((a.ediel_id IS NULL) OR (btrim(a.ediel_id) = ''::text)) THEN 'Komplettera Ediel-ID innan aktören kan användas i kundintag.'::text
            WHEN ((NOT COALESCE(r.has_prodat_route, false)) AND (NOT COALESCE(r.has_utilts_route, false))) THEN 'Lägg till PRODAT/UTILTS-route eller fallback innan automatiska förfrågningar.'::text
            WHEN (NOT COALESCE(r.has_contact_path, false)) THEN 'Komplettera SMTP/kontaktväg för fallback och manuell hantering.'::text
            WHEN (a.match_status <> 'verified'::text) THEN 'Verifiera aktören i plattformsregistret.'::text
            ELSE 'Ingen manuell åtgärd krävs.'::text
        END AS next_action,
    a.updated_at
   FROM (actor_base a
     LEFT JOIN route_base r ON ((r.actor_id = a.actor_id)))
  WHERE COALESCE(a.has_grid_owner_role, false);

--
-- Name: VIEW gridex_grid_owner_verification_status_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_grid_owner_verification_status_v IS 'Grid-owner readiness summary for intake, actor registry and platform backfill. Address/postal code can suggest; Ediel/nätområdeskod/facility data verify.';

--
-- Name: spot_price_daily_summaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_daily_summaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'elprisetjustnu'::text NOT NULL,
    price_area text NOT NULL,
    price_date date NOT NULL,
    average_sek_per_kwh numeric,
    min_sek_per_kwh numeric,
    max_sek_per_kwh numeric,
    interval_count integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'complete'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period_start timestamp with time zone,
    period_end timestamp with time zone,
    expected_interval_count integer,
    covered_duration_minutes integer,
    expected_duration_minutes integer,
    resolution text,
    quality_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    provider_fetched_at timestamp with time zone,
    verified_at timestamp with time zone,
    locked_at timestamp with time zone,
    source_checksum text,
    CONSTRAINT spot_price_daily_summaries_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_daily_summaries_status_check CHECK ((status = ANY (ARRAY['incomplete'::text, 'complete'::text, 'verified'::text, 'locked'::text]))),
    CONSTRAINT spot_price_daily_verified_coverage_check CHECK (((status <> ALL (ARRAY['verified'::text, 'locked'::text])) OR ((period_start IS NOT NULL) AND (period_end IS NOT NULL) AND (period_end > period_start) AND (average_sek_per_kwh IS NOT NULL) AND (min_sek_per_kwh IS NOT NULL) AND (max_sek_per_kwh IS NOT NULL) AND (covered_duration_minutes = expected_duration_minutes) AND (
CASE
    WHEN (jsonb_typeof(quality_issues) = 'array'::text) THEN jsonb_array_length(quality_issues)
    ELSE 1
END = 0) AND (verified_at IS NOT NULL) AND (NULLIF(btrim(source_checksum), ''::text) IS NOT NULL) AND ((status <> 'locked'::text) OR ((locked_at IS NOT NULL) AND (locked_at >= verified_at))))))
);

--
-- Name: gridex_latest_spot_price_by_area_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_latest_spot_price_by_area_v WITH (security_invoker='true') AS
 SELECT DISTINCT ON (price_area) price_area,
    source,
    price_date,
    status,
    average_sek_per_kwh,
    provider_fetched_at,
    verified_at,
    locked_at,
    updated_at
   FROM public.spot_price_daily_summaries
  ORDER BY price_area, price_date DESC, updated_at DESC;

--
-- Name: gridex_launch_db_security_warnings_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_launch_db_security_warnings_v WITH (security_invoker='true') AS
 SELECT (md5(('rls_disabled:'::text || (c.oid)::text)))::uuid AS id,
    'critical'::text AS severity,
    'rls_disabled'::text AS warning_type,
    n.nspname AS schema_name,
    c.relname AS object_name,
    'table'::text AS object_type,
    'RLS är avstängd på en public tabell som inte är explicit publik.'::text AS message,
    'Aktivera RLS och lägg rätt tenant/platform/service policy.'::text AS recommended_action,
    now() AS created_at
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = 'public'::name) AND (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"])) AND (c.relrowsecurity = false) AND (c.relname !~~ 'pg_%'::text) AND (c.relname <> ALL (ARRAY['schema_migrations'::name, 'spatial_ref_sys'::name])))
UNION ALL
 SELECT (md5(('missing_policy:'::text || (c.oid)::text)))::uuid AS id,
    'warning'::text AS severity,
    'rls_enabled_no_policy'::text AS warning_type,
    n.nspname AS schema_name,
    c.relname AS object_name,
    'table'::text AS object_type,
    'RLS är aktiverat men tabellen saknar policy. UI kan bli tomt eller krascha.'::text AS message,
    'Klassificera tabellen som tenant-readable, platform-only eller service-only och lägg policy.'::text AS recommended_action,
    now() AS created_at
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = 'public'::name) AND (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"])) AND (c.relrowsecurity = true) AND (NOT (EXISTS ( SELECT 1
           FROM pg_policy pol
          WHERE (pol.polrelid = c.oid)))))
UNION ALL
 SELECT (md5(('anon_table:'::text || (c.oid)::text)))::uuid AS id,
    'critical'::text AS severity,
    'anon_table_access'::text AS warning_type,
    n.nspname AS schema_name,
    c.relname AS object_name,
    'table'::text AS object_type,
    'Anon har direkt privilegium på public tabell.'::text AS message,
    'Revoke all from anon eller flytta läsning bakom server/API.'::text AS recommended_action,
    now() AS created_at
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = 'public'::name) AND (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"])) AND (has_table_privilege('anon'::name, c.oid, 'SELECT'::text) OR has_table_privilege('anon'::name, c.oid, 'INSERT'::text) OR has_table_privilege('anon'::name, c.oid, 'UPDATE'::text) OR has_table_privilege('anon'::name, c.oid, 'DELETE'::text)) AND (c.relname <> 'spot_price_monthly_summaries_public'::name))
UNION ALL
 SELECT (md5(('anon_func:'::text || (p.oid)::text)))::uuid AS id,
    'critical'::text AS severity,
    'anon_security_definer_execute'::text AS warning_type,
    n.nspname AS schema_name,
    p.proname AS object_name,
    'function'::text AS object_type,
    'Anon kan köra SECURITY DEFINER-funktion.'::text AS message,
    'Revoke execute från anon och exponera bara säker server action/RPC.'::text AS recommended_action,
    now() AS created_at
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = 'public'::name) AND (p.prosecdef = true) AND has_function_privilege('anon'::name, p.oid, 'EXECUTE'::text))
UNION ALL
 SELECT (md5(('view_definer:'::text || (c.oid)::text)))::uuid AS id,
    'warning'::text AS severity,
    'view_not_security_invoker'::text AS warning_type,
    n.nspname AS schema_name,
    c.relname AS object_name,
    'view'::text AS object_type,
    'View saknar security_invoker=true och kan kringgå RLS beroende på Postgres/Supabase-inställning.'::text AS message,
    'Sätt security_invoker=true eller lås vyn bakom server/service-role.'::text AS recommended_action,
    now() AS created_at
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = 'public'::name) AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"])) AND (NOT ('security_invoker=true'::text = ANY (COALESCE(c.reloptions, ARRAY[]::text[])))) AND (c.relname = ANY (ARRAY['billing_readiness_flags'::name, 'ediel_active_actor_settings_v'::name, 'ediel_message_ack_state_v'::name, 'ediel_outbound_route_candidates_v'::name, 'ediel_retry_candidates_v'::name, 'ediel_route_runtime_v'::name, 'ediel_unresolved_messages'::name, 'gridex_automation_control_center_v'::name, 'gridex_user_auth_integrity_v'::name, 'gridex_route_readiness_v'::name, 'gridex_company_operations_statistics_v'::name, 'gridex_launch_error_summary_v'::name])));

--
-- Name: gridex_launch_error_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_launch_error_summary_v WITH (security_invoker='true') AS
 SELECT f.company_id,
    f.id,
    'facility_data_quality_issues'::text AS source_table,
    f.issue_type AS error_key,
    f.status,
    f.severity,
    f.recommended_action,
    f.customer_id,
    f.customer_site_id,
    f.metering_point_id,
    f.created_at
   FROM public.facility_data_quality_issues f
  WHERE (f.status <> ALL (ARRAY['resolved'::text, 'ignored'::text]))
UNION ALL
 SELECT e.company_id,
    e.id,
    'ediel_business_errors'::text AS source_table,
    e.business_error AS error_key,
    e.status,
        CASE
            WHEN (e.status = ANY (ARRAY['resolved'::text, 'ignored'::text])) THEN 'info'::text
            WHEN ((e.retry_allowed = false) AND (e.status = 'open'::text)) THEN 'critical'::text
            WHEN (e.business_error = ANY (ARRAY['object_not_identified'::text, 'facility_rejected'::text, 'negative_aperak'::text, 'z02_rejected'::text, 'protected_identity'::text])) THEN 'critical'::text
            WHEN (e.status ~~ 'waiting_%'::text) THEN 'warning'::text
            ELSE 'warning'::text
        END AS severity,
    e.recommended_action,
    e.customer_id,
    e.customer_site_id,
    e.metering_point_id,
    e.created_at
   FROM public.ediel_business_errors e
  WHERE (e.status <> ALL (ARRAY['resolved'::text, 'ignored'::text]))
UNION ALL
 SELECT (NULLIF((i.metadata ->> 'company_id'::text), ''::text))::uuid AS company_id,
    i.id,
    'platform_actor_import_issues'::text AS source_table,
    i.issue_type AS error_key,
    i.status,
    i.severity,
    COALESCE(i.message, 'Actor registry/import behöver granskas.'::text) AS recommended_action,
    NULL::uuid AS customer_id,
    NULL::uuid AS customer_site_id,
    NULL::uuid AS metering_point_id,
    i.created_at
   FROM public.platform_actor_import_issues i
  WHERE (i.status <> ALL (ARRAY['resolved'::text, 'ignored'::text]))
UNION ALL
 SELECT r.company_id,
    r.id,
    'integration_api_requests'::text AS source_table,
    COALESCE(r.error_code, 'api_error'::text) AS error_key,
    (r.status_code)::text AS status,
        CASE
            WHEN (r.status_code >= 500) THEN 'critical'::text
            WHEN (r.status_code = 429) THEN 'warning'::text
            ELSE 'warning'::text
        END AS severity,
        CASE
            WHEN (r.status_code = 429) THEN 'Tjänsten svarar långsamt just nu. Försök igen senare eller hantera manuellt.'::text
            ELSE 'Externt API-anrop misslyckades och behöver granskas.'::text
        END AS recommended_action,
    NULL::uuid AS customer_id,
    NULL::uuid AS customer_site_id,
    NULL::uuid AS metering_point_id,
    r.created_at
   FROM public.integration_api_requests r
  WHERE (COALESCE(r.status_code, 200) >= 400)
UNION ALL
 SELECT w.company_id,
    w.id,
    'webhook_deliveries'::text AS source_table,
    COALESCE(w.failure_reason, w.status, 'webhook_failed'::text) AS error_key,
    w.status,
        CASE
            WHEN (w.status = 'dead_letter'::text) THEN 'critical'::text
            ELSE 'warning'::text
        END AS severity,
    'Webhookleverans misslyckades. Kontrollera endpoint, signering och retry-logg.'::text AS recommended_action,
    NULL::uuid AS customer_id,
    NULL::uuid AS customer_site_id,
    NULL::uuid AS metering_point_id,
    w.created_at
   FROM public.webhook_deliveries w
  WHERE (w.status = ANY (ARRAY['failed'::text, 'dead_letter'::text]))
UNION ALL
 SELECT m.company_id,
    m.id,
    'communication_logs'::text AS source_table,
    COALESCE(m.error_message, m.status, 'mail_failed'::text) AS error_key,
    m.status,
    'warning'::text AS severity,
    'Kundkommunikation misslyckades. Kontrollera bolagets mailidentitet, mall och mottagaradress.'::text AS recommended_action,
    m.customer_id,
    NULL::uuid AS customer_site_id,
    NULL::uuid AS metering_point_id,
    m.created_at
   FROM public.communication_logs m
  WHERE (m.status = ANY (ARRAY['failed'::text, 'bounced'::text]))
UNION ALL
 SELECT b.company_id,
    b.contract_id AS id,
    'gridex_billing_launch_readiness_v'::text AS source_table,
    array_to_string(b.blockers, ','::text) AS error_key,
    b.readiness_status AS status,
    'critical'::text AS severity,
    'Fakturering är blockerad tills verifierad anläggning, nätägare, SE-område, pris-snapshot och marknadssvar är klara.'::text AS recommended_action,
    b.customer_id,
    b.site_id AS customer_site_id,
    b.metering_point_id,
    b.checked_at AS created_at
   FROM public.gridex_billing_launch_readiness_v b
  WHERE (b.readiness_status = 'blocked'::text)
UNION ALL
 SELECT rl.company_id,
    rl.id,
    'integration_api_rate_limit_events'::text AS source_table,
    'rate_limited'::text AS error_key,
    'rate_limited'::text AS status,
    'warning'::text AS severity,
    'Tjänsten svarar långsamt just nu. Försök igen senare eller hantera manuellt.'::text AS recommended_action,
    NULL::uuid AS customer_id,
    NULL::uuid AS customer_site_id,
    NULL::uuid AS metering_point_id,
    rl.created_at
   FROM public.integration_api_rate_limit_events rl;

--
-- Name: gridex_locked_spot_periods_missing_evidence_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_locked_spot_periods_missing_evidence_v WITH (security_invoker='true') AS
 SELECT 'day'::text AS period_type,
    spot_price_daily_summaries.id,
    spot_price_daily_summaries.source,
    spot_price_daily_summaries.price_area,
    (spot_price_daily_summaries.price_date)::text AS period_key,
    spot_price_daily_summaries.status,
    spot_price_daily_summaries.period_start,
    spot_price_daily_summaries.period_end,
    spot_price_daily_summaries.covered_duration_minutes,
    spot_price_daily_summaries.expected_duration_minutes,
    spot_price_daily_summaries.quality_issues,
    spot_price_daily_summaries.verified_at,
    spot_price_daily_summaries.locked_at,
    spot_price_daily_summaries.source_checksum
   FROM public.spot_price_daily_summaries
  WHERE ((spot_price_daily_summaries.status = 'locked'::text) AND ((spot_price_daily_summaries.period_start IS NULL) OR (spot_price_daily_summaries.period_end IS NULL) OR (spot_price_daily_summaries.period_end <= spot_price_daily_summaries.period_start) OR (spot_price_daily_summaries.covered_duration_minutes IS NULL) OR (spot_price_daily_summaries.expected_duration_minutes IS NULL) OR (spot_price_daily_summaries.covered_duration_minutes IS DISTINCT FROM spot_price_daily_summaries.expected_duration_minutes) OR (
        CASE
            WHEN (jsonb_typeof(spot_price_daily_summaries.quality_issues) = 'array'::text) THEN jsonb_array_length(spot_price_daily_summaries.quality_issues)
            ELSE 1
        END > 0) OR (spot_price_daily_summaries.verified_at IS NULL) OR (spot_price_daily_summaries.locked_at IS NULL) OR (spot_price_daily_summaries.locked_at < spot_price_daily_summaries.verified_at) OR (NULLIF(btrim(spot_price_daily_summaries.source_checksum), ''::text) IS NULL)))
UNION ALL
 SELECT 'month'::text AS period_type,
    spot_price_monthly_summaries.id,
    spot_price_monthly_summaries.source,
    spot_price_monthly_summaries.price_area,
    spot_price_monthly_summaries.billing_month AS period_key,
    spot_price_monthly_summaries.status,
    spot_price_monthly_summaries.period_start,
    spot_price_monthly_summaries.period_end,
    spot_price_monthly_summaries.covered_duration_minutes,
    spot_price_monthly_summaries.expected_duration_minutes,
    spot_price_monthly_summaries.quality_issues,
    spot_price_monthly_summaries.verified_at,
    spot_price_monthly_summaries.locked_at,
    spot_price_monthly_summaries.source_checksum
   FROM public.spot_price_monthly_summaries
  WHERE ((spot_price_monthly_summaries.status = 'locked'::text) AND ((spot_price_monthly_summaries.period_start IS NULL) OR (spot_price_monthly_summaries.period_end IS NULL) OR (spot_price_monthly_summaries.period_end <= spot_price_monthly_summaries.period_start) OR (spot_price_monthly_summaries.covered_duration_minutes IS NULL) OR (spot_price_monthly_summaries.expected_duration_minutes IS NULL) OR (spot_price_monthly_summaries.covered_duration_minutes IS DISTINCT FROM spot_price_monthly_summaries.expected_duration_minutes) OR (
        CASE
            WHEN (jsonb_typeof(spot_price_monthly_summaries.quality_issues) = 'array'::text) THEN jsonb_array_length(spot_price_monthly_summaries.quality_issues)
            ELSE 1
        END > 0) OR (spot_price_monthly_summaries.verified_at IS NULL) OR (spot_price_monthly_summaries.locked_at IS NULL) OR (spot_price_monthly_summaries.locked_at < spot_price_monthly_summaries.verified_at) OR (NULLIF(btrim(spot_price_monthly_summaries.source_checksum), ''::text) IS NULL)));

--
-- Name: market_price_previews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.market_price_previews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    price_area text NOT NULL,
    reference_period text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    as_of timestamp with time zone NOT NULL,
    price_sek_per_kwh numeric NOT NULL,
    source_currency text DEFAULT 'SEK'::text NOT NULL,
    unit text DEFAULT 'sek_per_kwh'::text NOT NULL,
    includes_vat boolean DEFAULT false NOT NULL,
    includes_supplier_fees boolean DEFAULT false NOT NULL,
    includes_grid_fees boolean DEFAULT false NOT NULL,
    is_indicative boolean DEFAULT true NOT NULL,
    fallback_used boolean DEFAULT false NOT NULL,
    fallback_reason text,
    stale_after timestamp with time zone NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    source_summary_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    source_checksum text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_as_of timestamp with time zone NOT NULL,
    generated_at timestamp with time zone NOT NULL,
    requested_days integer,
    included_days integer,
    source_resolution text,
    CONSTRAINT market_price_previews_check CHECK ((period_end >= period_start)),
    CONSTRAINT market_price_previews_included_days_check CHECK (((included_days IS NULL) OR ((included_days > 0) AND ((requested_days IS NULL) OR (included_days <= requested_days))))),
    CONSTRAINT market_price_previews_is_indicative_check CHECK ((is_indicative = true)),
    CONSTRAINT market_price_previews_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT market_price_previews_reference_period_check CHECK ((reference_period = ANY (ARRAY['latest_complete_day'::text, 'rolling_7_days'::text, 'rolling_30_days'::text, 'month_to_date'::text, 'forecast'::text]))),
    CONSTRAINT market_price_previews_status_check CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text, 'expired'::text]))),
    CONSTRAINT market_price_previews_window_check CHECK (((requested_days IS NULL) OR (requested_days > 0)))
);

--
-- Name: TABLE market_price_previews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.market_price_previews IS 'Indicative quote/display evidence only. It is forbidden as final settlement evidence.';

--
-- Name: COLUMN market_price_previews.source_as_of; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.market_price_previews.source_as_of IS 'Timestamp derived from the newest underlying provider evidence. It must not be refreshed by recalculation alone.';

--
-- Name: COLUMN market_price_previews.generated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.market_price_previews.generated_at IS 'Timestamp when the preview calculation was generated.';

--
-- Name: COLUMN market_price_previews.requested_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.market_price_previews.requested_days IS 'Requested reference-window size. For rolling_30_days this is 30.';

--
-- Name: COLUMN market_price_previews.included_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.market_price_previews.included_days IS 'Number of verified daily summaries actually included in the preview.';

--
-- Name: gridex_market_preview_coverage_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_market_preview_coverage_v WITH (security_invoker='true') AS
 SELECT provider,
    price_area,
    reference_period,
    period_start,
    period_end,
    requested_days,
    included_days,
    fallback_used,
    fallback_reason,
    source_as_of,
    generated_at,
    stale_after,
    (now() > stale_after) AS globally_stale,
    source_checksum,
    status
   FROM public.market_price_previews;

--
-- Name: gridex_market_price_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_market_price_readiness_v WITH (security_invoker='true') AS
 WITH stockholm_clock AS (
         SELECT ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date AS "current_date",
            (((now() AT TIME ZONE 'Europe/Stockholm'::text))::date - 1) AS previous_date
        ), areas(price_area) AS (
         VALUES ('SE1'::text), ('SE2'::text), ('SE3'::text), ('SE4'::text)
        ), current_missing AS (
         SELECT count(*) AS issue_count
           FROM ((areas a
             CROSS JOIN stockholm_clock c)
             LEFT JOIN public.spot_price_daily_summaries d ON (((d.source = 'elprisetjustnu'::text) AND (d.price_area = a.price_area) AND (d.price_date = c."current_date") AND (d.status = ANY (ARRAY['verified'::text, 'locked'::text])))))
          WHERE (d.id IS NULL)
        ), previous_missing AS (
         SELECT count(*) AS issue_count
           FROM ((areas a
             CROSS JOIN stockholm_clock c)
             LEFT JOIN public.spot_price_daily_summaries d ON (((d.source = 'elprisetjustnu'::text) AND (d.price_area = a.price_area) AND (d.price_date = c.previous_date) AND (d.status = ANY (ARRAY['verified'::text, 'locked'::text])))))
          WHERE (d.id IS NULL)
        ), incomplete_window AS (
         SELECT count(*) AS issue_count
           FROM (areas a
             LEFT JOIN public.market_price_previews p ON (((p.provider = 'elprisetjustnu'::text) AND (p.price_area = a.price_area) AND (p.reference_period = 'rolling_30_days'::text) AND (p.status = 'active'::text))))
          WHERE ((p.id IS NULL) OR (p.requested_days IS DISTINCT FROM 30) OR (p.included_days IS NULL) OR (p.included_days < 30) OR (p.fallback_used = true))
        ), stale_preview AS (
         SELECT count(*) AS issue_count
           FROM public.market_price_previews p
          WHERE ((p.status = 'active'::text) AND (now() > p.stale_after))
        ), policy_conflict AS (
         SELECT count(*) AS issue_count
           FROM (public.company_market_price_sources s
             JOIN public.market_price_previews p ON (((p.provider = s.source_key) AND (p.status = 'active'::text) AND (p.fallback_used = true) AND ((COALESCE(cardinality(s.price_areas), 0) = 0) OR (p.price_area = ANY (s.price_areas))))))
          WHERE ((s.enabled = true) AND (s.allow_indicative_latest = false))
        ), freshness_risk AS (
         SELECT count(*) AS issue_count
           FROM ((public.company_market_price_sources s
             CROSS JOIN areas a)
             LEFT JOIN public.spot_price_daily_summaries d ON (((d.source = s.source_key) AND (d.price_area = a.price_area) AND (d.price_date = ( SELECT CURRENT_DATE AS "current_date"
                   FROM stockholm_clock)) AND (d.status = ANY (ARRAY['verified'::text, 'locked'::text])))))
          WHERE ((s.enabled = true) AND ((COALESCE(cardinality(s.price_areas), 0) = 0) OR (a.price_area = ANY (s.price_areas))) AND ((d.id IS NULL) OR ((COALESCE(d.provider_fetched_at, d.verified_at, d.updated_at) + make_interval(mins => GREATEST(1, s.max_age_minutes))) <= now())))
        )
 SELECT 'spot_current_day_missing'::text AS check_key,
        CASE
            WHEN (current_missing.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    current_missing.issue_count,
    jsonb_build_object('provider', 'elprisetjustnu', 'expected_areas', 4) AS details
   FROM current_missing
UNION ALL
 SELECT 'spot_previous_day_missing'::text AS check_key,
        CASE
            WHEN (previous_missing.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    previous_missing.issue_count,
    jsonb_build_object('provider', 'elprisetjustnu', 'expected_areas', 4) AS details
   FROM previous_missing
UNION ALL
 SELECT 'spot_reference_window_incomplete'::text AS check_key,
        CASE
            WHEN (incomplete_window.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    incomplete_window.issue_count,
    jsonb_build_object('reference_period', 'rolling_30_days', 'requested_days', 30) AS details
   FROM incomplete_window
UNION ALL
 SELECT 'spot_preview_stale'::text AS check_key,
        CASE
            WHEN (stale_preview.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    stale_preview.issue_count,
    '{}'::jsonb AS details
   FROM stale_preview
UNION ALL
 SELECT 'spot_policy_fallback_conflict'::text AS check_key,
        CASE
            WHEN (policy_conflict.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    policy_conflict.issue_count,
    jsonb_build_object('rule', 'fallback_used requires allow_indicative_latest') AS details
   FROM policy_conflict
UNION ALL
 SELECT 'spot_cron_slower_than_freshness_policy'::text AS check_key,
        CASE
            WHEN (freshness_risk.issue_count = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status,
    freshness_risk.issue_count,
    jsonb_build_object('rule', 'current provider evidence must be newer than tenant max_age_minutes') AS details
   FROM freshness_risk;

--
-- Name: gridex_metering_points_incomplete_area_context_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_metering_points_incomplete_area_context_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    customer_id,
    site_id,
    customer_site_id,
    grid_area_code,
    grid_owner_id,
    grid_owner_name,
    COALESCE(price_area, bidding_zone_code) AS price_area,
    energy_resolution_id,
    resolution_status,
    geodata_version
   FROM public.metering_points
  WHERE ((grid_area_code IS NULL) OR (grid_owner_id IS NULL) OR (COALESCE(price_area, bidding_zone_code) IS NULL) OR (energy_resolution_id IS NULL));

--
-- Name: gridex_migration_governance_v3; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_migration_governance_v3 WITH (security_invoker='true') AS
 WITH manifest AS (
         SELECT count(*) AS manifest_file_count,
            count(DISTINCT canonical_migration_manifest.version) AS manifest_version_count,
            count(*) FILTER (WHERE (canonical_migration_manifest.verified_at IS NOT NULL)) AS verified_file_count,
            count(*) FILTER (WHERE canonical_migration_manifest.effect_verified) AS effect_verified_file_count,
            count(*) FILTER (WHERE ((canonical_migration_manifest.checksum IS NULL) OR (canonical_migration_manifest.checksum !~ '^[a-f0-9]{64}$'::text))) AS invalid_checksum_count,
            count(*) FILTER (WHERE (canonical_migration_manifest.verification_kind = 'schema_effect'::text)) AS schema_effect_file_count,
            max(canonical_migration_manifest.verified_at) AS last_verified_at
           FROM public.canonical_migration_manifest
        ), ledger AS (
         SELECT count(*) AS ledger_version_count,
            max(schema_migrations.version) AS latest_ledger_version
           FROM supabase_migrations.schema_migrations
        ), missing AS (
         SELECT count(*) AS count
           FROM public.canonical_migration_manifest m
          WHERE ((m.verification_kind = ANY (ARRAY['ledger'::text, 'ledger_alias'::text])) AND (NOT (EXISTS ( SELECT 1
                   FROM supabase_migrations.schema_migrations l
                  WHERE ((l.version = m.applied_ledger_version) AND (l.name = m.applied_ledger_name))))))
        ), unmapped AS (
         SELECT count(*) AS count
           FROM supabase_migrations.schema_migrations l
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.canonical_migration_manifest m
                  WHERE ((m.applied_ledger_version = l.version) AND (m.applied_ledger_name = l.name)))))
        ), duplicate_mappings AS (
         SELECT count(*) AS count
           FROM ( SELECT canonical_migration_manifest.applied_ledger_version
                   FROM public.canonical_migration_manifest
                  WHERE (canonical_migration_manifest.applied_ledger_version IS NOT NULL)
                  GROUP BY canonical_migration_manifest.applied_ledger_version
                 HAVING (count(*) > 1)) d
        )
 SELECT manifest.manifest_file_count,
    manifest.manifest_version_count,
    manifest.verified_file_count,
    manifest.effect_verified_file_count,
    manifest.invalid_checksum_count,
    manifest.schema_effect_file_count,
    manifest.last_verified_at,
    ledger.ledger_version_count,
    ledger.latest_ledger_version,
    missing.count AS missing_in_ledger,
    unmapped.count AS unmapped_ledger_versions,
    duplicate_mappings.count AS duplicate_ledger_mappings,
    ((manifest.manifest_file_count > 0) AND (manifest.verified_file_count = manifest.manifest_file_count) AND (manifest.effect_verified_file_count = manifest.manifest_file_count) AND (manifest.invalid_checksum_count = 0) AND (missing.count = 0) AND (unmapped.count = 0) AND (duplicate_mappings.count = 0)) AS is_ready,
    array_remove(ARRAY[
        CASE
            WHEN (manifest.manifest_file_count = 0) THEN 'CANONICAL_MIGRATION_MANIFEST_EMPTY'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (manifest.verified_file_count <> manifest.manifest_file_count) THEN 'MIGRATIONS_NOT_FULLY_VERIFIED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (manifest.effect_verified_file_count <> manifest.manifest_file_count) THEN 'MIGRATION_EFFECTS_NOT_FULLY_VERIFIED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (manifest.invalid_checksum_count > 0) THEN 'MIGRATION_CHECKSUM_INVALID'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (missing.count > 0) THEN 'MIGRATION_LEDGER_MISSING_MAPPING'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (unmapped.count > 0) THEN 'MIGRATION_LEDGER_UNMAPPED_VERSION'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (duplicate_mappings.count > 0) THEN 'MIGRATION_LEDGER_DUPLICATE_MAPPING'::text
            ELSE NULL::text
        END], NULL::text) AS blockers
   FROM ((((manifest
     CROSS JOIN ledger)
     CROSS JOIN missing)
     CROSS JOIN unmapped)
     CROSS JOIN duplicate_mappings);

--
-- Name: VIEW gridex_migration_governance_v3; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_migration_governance_v3 IS 'Deployment governance with explicit ledger aliases and schema-effect evidence; it never expires on elapsed time.';

--
-- Name: gridex_multiple_permissive_policy_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_multiple_permissive_policy_candidates_v WITH (security_invoker='true') AS
 WITH role_candidates AS (
         SELECT (pg_roles.rolname)::text AS role_name
           FROM pg_roles
          WHERE (pg_roles.rolname = ANY (ARRAY['anon'::name, 'authenticated'::name, 'service_role'::name, 'authenticator'::name, 'dashboard_user'::name, 'supabase_privileged_role'::name]))
        UNION
         SELECT DISTINCT (unnest(pg_policies.roles))::text AS role_name
           FROM pg_policies
          WHERE (pg_policies.schemaname = 'public'::name)
        ), expanded AS (
         SELECT p.schemaname,
            p.tablename,
            a.action_name,
            r.role_name,
            p.policyname
           FROM ((pg_policies p
             JOIN ( VALUES ('SELECT'::text), ('INSERT'::text), ('UPDATE'::text), ('DELETE'::text)) a(action_name) ON (((p.cmd = 'ALL'::text) OR (p.cmd = a.action_name))))
             JOIN role_candidates r ON ((('public'::text = ANY ((p.roles)::text[])) OR (r.role_name = ANY ((p.roles)::text[])))))
          WHERE ((p.schemaname = 'public'::name) AND (p.permissive = 'PERMISSIVE'::text))
        )
 SELECT schemaname,
    tablename,
    action_name,
    role_name,
    count(*) AS policy_count,
    array_agg(policyname ORDER BY policyname) AS policies
   FROM expanded
  GROUP BY schemaname, tablename, action_name, role_name
 HAVING (count(*) > 1);

--
-- Name: gridex_o6_3_safe_blank_subaddress_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_o6_3_safe_blank_subaddress_candidates_v WITH (security_invoker='true') AS
 WITH actor_ediel_ids AS (
         SELECT platform_actor_identifiers.actor_id,
            array_agg(DISTINCT platform_actor_identifiers.identifier_value ORDER BY platform_actor_identifiers.identifier_value) FILTER (WHERE ((lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text])) AND (NULLIF(btrim(platform_actor_identifiers.identifier_value), ''::text) IS NOT NULL))) AS ediel_ids,
            array_agg(DISTINCT platform_actor_identifiers.identifier_value ORDER BY platform_actor_identifiers.identifier_value) FILTER (WHERE ((lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text])) AND (COALESCE(platform_actor_identifiers.is_verified, false) = true) AND (NULLIF(btrim(platform_actor_identifiers.identifier_value), ''::text) IS NOT NULL))) AS verified_ediel_ids
           FROM public.platform_actor_identifiers
          GROUP BY platform_actor_identifiers.actor_id
        ), actor_roles AS (
         SELECT platform_actor_roles.actor_id,
            array_agg(DISTINCT lower(platform_actor_roles.actor_role) ORDER BY (lower(platform_actor_roles.actor_role))) FILTER (WHERE (NULLIF(btrim(platform_actor_roles.actor_role), ''::text) IS NOT NULL)) AS actor_roles,
            bool_or((lower(platform_actor_roles.actor_role) = ANY (ARRAY['grid_owner'::text, 'network_owner'::text, 'netowner'::text, 'dso'::text, 'distribution_system_operator'::text, 'nätägare'::text, 'elnatsforetag'::text, 'elnätsföretag'::text]))) AS has_grid_owner_role
           FROM public.platform_actor_roles
          WHERE (COALESCE(platform_actor_roles.is_active, true) = true)
          GROUP BY platform_actor_roles.actor_id
        ), active_routes AS (
         SELECT r.id,
            r.actor_id,
            r.message_family,
            r.application_reference,
            r.environment,
            r.subaddress,
            r.communication_type,
            r.communication_address,
            r.edi_charset,
            r.edi_syntax,
            r.party_id,
            r.party_id_qualifier,
            r.party_id_responsible,
            r.interchange_party_id,
            r.interchange_id_qualifier,
            r.requires_poa,
            r.is_verified,
            r.auto_send_allowed,
            r.status,
            r.valid_from,
            r.valid_to,
            r.source,
            r.metadata,
            r.created_at,
            r.updated_at,
            upper(COALESCE(r.message_family, ''::text)) AS family,
            lower(COALESCE(r.environment, ''::text)) AS env,
            NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) AS clean_subaddress,
            NULLIF(btrim(COALESCE(r.communication_address, ''::text)), ''::text) AS clean_communication_address,
            NULLIF(btrim(COALESCE(r.party_id, ''::text)), ''::text) AS clean_party_id,
            NULLIF(btrim(COALESCE(r.interchange_party_id, ''::text)), ''::text) AS clean_interchange_party_id
           FROM public.platform_actor_routes r
          WHERE ((upper(COALESCE(r.message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (lower(COALESCE(r.environment, ''::text)) = 'production'::text) AND (lower(COALESCE(r.status, ''::text)) = 'active'::text))
        ), grouped AS (
         SELECT active_routes.actor_id,
            active_routes.family,
            active_routes.env,
            (count(*))::integer AS active_route_count,
            (count(*) FILTER (WHERE (active_routes.clean_subaddress IS NULL)))::integer AS blank_subaddress_count,
            (count(*) FILTER (WHERE (active_routes.clean_subaddress IS NOT NULL)))::integer AS explicit_subaddress_count,
            (count(DISTINCT active_routes.clean_communication_address) FILTER (WHERE (active_routes.clean_communication_address IS NOT NULL)))::integer AS distinct_communication_address_count,
            array_agg(active_routes.id ORDER BY active_routes.created_at, active_routes.id) AS route_ids,
            array_agg(DISTINCT active_routes.clean_communication_address) FILTER (WHERE (active_routes.clean_communication_address IS NOT NULL)) AS communication_addresses,
            array_agg(DISTINCT active_routes.clean_party_id) FILTER (WHERE (active_routes.clean_party_id IS NOT NULL)) AS party_ids,
            array_agg(DISTINCT active_routes.clean_interchange_party_id) FILTER (WHERE (active_routes.clean_interchange_party_id IS NOT NULL)) AS interchange_party_ids,
            bool_and(COALESCE(active_routes.is_verified, false)) AS all_active_routes_verified
           FROM active_routes
          GROUP BY active_routes.actor_id, active_routes.family, active_routes.env
        ), route_rows AS (
         SELECT r.id AS route_id,
            r.actor_id,
            r.family AS message_family,
            r.env AS environment,
            r.clean_subaddress,
            r.clean_communication_address,
            r.clean_party_id,
            r.clean_interchange_party_id,
            r.metadata,
            g.active_route_count,
            g.blank_subaddress_count,
            g.explicit_subaddress_count,
            g.distinct_communication_address_count,
            g.route_ids,
            g.communication_addresses,
            g.party_ids,
            g.interchange_party_ids,
            g.all_active_routes_verified
           FROM (active_routes r
             JOIN grouped g ON (((g.actor_id = r.actor_id) AND (g.family = r.family) AND (g.env = r.env))))
        )
 SELECT a.name AS actor_name,
    rr.actor_id,
    rr.route_id,
    COALESCE(rr.clean_party_id, ai.verified_ediel_ids[1], ai.ediel_ids[1]) AS ediel_id,
    ai.ediel_ids,
    ai.verified_ediel_ids,
    COALESCE(ar.actor_roles, '{}'::text[]) AS actor_roles,
    COALESCE(ar.has_grid_owner_role, false) AS has_grid_owner_role,
    rr.message_family,
    rr.environment,
    rr.active_route_count,
    rr.blank_subaddress_count,
    rr.explicit_subaddress_count,
    rr.distinct_communication_address_count,
    rr.communication_addresses,
    rr.party_ids,
    rr.interchange_party_ids,
    COALESCE((rr.metadata ->> 'subaddress_status'::text), 'missing'::text) AS current_subaddress_status,
        CASE
            WHEN (COALESCE(ar.has_grid_owner_role, false) IS NOT TRUE) THEN false
            WHEN (rr.active_route_count <> 1) THEN false
            WHEN (rr.blank_subaddress_count <> 1) THEN false
            WHEN (rr.explicit_subaddress_count <> 0) THEN false
            WHEN (rr.clean_subaddress IS NOT NULL) THEN false
            WHEN (rr.clean_communication_address IS NULL) THEN false
            WHEN (rr.all_active_routes_verified IS NOT TRUE) THEN false
            WHEN (rr.clean_party_id IS NULL) THEN false
            WHEN (rr.clean_interchange_party_id IS NULL) THEN false
            WHEN (rr.clean_party_id <> rr.clean_interchange_party_id) THEN false
            WHEN ((COALESCE(array_length(ai.verified_ediel_ids, 1), 0) > 0) AND (NOT (rr.clean_party_id = ANY (ai.verified_ediel_ids)))) THEN false
            WHEN (COALESCE((rr.metadata ->> 'subaddress_status'::text), ''::text) = ANY (ARRAY['verified'::text, 'not_required_confirmed'::text])) THEN true
            ELSE true
        END AS can_auto_confirm,
    array_remove(ARRAY[
        CASE
            WHEN (COALESCE(ar.has_grid_owner_role, false) IS NOT TRUE) THEN 'actor_not_grid_owner'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.active_route_count <> 1) THEN 'not_unique_active_route'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.blank_subaddress_count <> 1) THEN 'blank_route_count_not_one'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.explicit_subaddress_count <> 0) THEN 'explicit_subaddress_exists'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.clean_subaddress IS NOT NULL) THEN 'subaddress_already_explicit'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.clean_communication_address IS NULL) THEN 'missing_communication_address'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.all_active_routes_verified IS NOT TRUE) THEN 'route_not_verified'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.clean_party_id IS NULL) THEN 'missing_party_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rr.clean_interchange_party_id IS NULL) THEN 'missing_interchange_party_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rr.clean_party_id IS NOT NULL) AND (rr.clean_interchange_party_id IS NOT NULL) AND (rr.clean_party_id <> rr.clean_interchange_party_id)) THEN 'party_id_interchange_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((COALESCE(array_length(ai.verified_ediel_ids, 1), 0) > 0) AND (rr.clean_party_id IS NOT NULL) AND (NOT (rr.clean_party_id = ANY (ai.verified_ediel_ids)))) THEN 'party_id_not_verified_ediel_id'::text
            ELSE NULL::text
        END], NULL::text) AS skip_reasons
   FROM (((route_rows rr
     JOIN public.platform_market_actors a ON ((a.id = rr.actor_id)))
     LEFT JOIN actor_ediel_ids ai ON ((ai.actor_id = rr.actor_id)))
     LEFT JOIN actor_roles ar ON ((ar.actor_id = rr.actor_id)));

--
-- Name: VIEW gridex_o6_3_safe_blank_subaddress_candidates_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_o6_3_safe_blank_subaddress_candidates_v IS 'O6.3 diagnostic view for safe blank PRODAT/UTILTS subaddress confirmation. can_auto_confirm=true means blank subaddress is treated as not required, never as a synthetic value.';

--
-- Name: gridex_old_geodata_versions_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_old_geodata_versions_v WITH (security_invoker='true') AS
 SELECT id,
    provider,
    version_key,
    status,
    source_url,
    cursor_offset,
    feature_count,
    coverage_status,
    checksum,
    started_at,
    verified_at,
    completed_at,
    metadata,
    created_at,
    updated_at,
    (now() - COALESCE(verified_at, completed_at, started_at)) AS age
   FROM public.energy_geodata_versions
  WHERE ((status = 'verified'::text) AND (COALESCE(verified_at, completed_at, started_at) < (now() - '30 days'::interval)));

--
-- Name: gridex_operational_route_repair_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_operational_route_repair_v WITH (security_invoker='true') AS
 SELECT 'company_market_party_route_metadata_drift'::text AS issue_type,
    cmpr.company_id,
    cmpr.id AS entity_id,
    jsonb_build_object('environment_column', cmpr.environment, 'environment_metadata', (cmpr.metadata ->> 'environment'::text), 'message_code_column', cmpr.message_code, 'message_code_metadata', (cmpr.metadata ->> 'message_code'::text)) AS details
   FROM public.company_market_party_routes cmpr
  WHERE ((cmpr.active = true) AND ((((cmpr.metadata ->> 'environment'::text) IS NOT NULL) AND (cmpr.environment IS DISTINCT FROM (cmpr.metadata ->> 'environment'::text))) OR (((cmpr.metadata ->> 'message_code'::text) IS NOT NULL) AND (cmpr.message_code IS DISTINCT FROM (cmpr.metadata ->> 'message_code'::text)))))
UNION ALL
 SELECT 'company_market_party_route_orphan_profile'::text AS issue_type,
    cmpr.company_id,
    cmpr.id AS entity_id,
    jsonb_build_object('route_profile_id', cmpr.route_profile_id) AS details
   FROM (public.company_market_party_routes cmpr
     LEFT JOIN public.ediel_route_profiles erp ON ((erp.id = cmpr.route_profile_id)))
  WHERE ((cmpr.active = true) AND (cmpr.route_profile_id IS NOT NULL) AND (erp.id IS NULL))
UNION ALL
 SELECT 'ediel_route_profile_orphan_communication_route'::text AS issue_type,
    erp.company_id,
    erp.id AS entity_id,
    jsonb_build_object('communication_route_id', erp.communication_route_id) AS details
   FROM (public.ediel_route_profiles erp
     LEFT JOIN public.communication_routes cr ON ((cr.id = erp.communication_route_id)))
  WHERE ((COALESCE(erp.is_active, false) = true) AND (erp.communication_route_id IS NOT NULL) AND (cr.id IS NULL))
UNION ALL
 SELECT 'outbound_request_null_route_with_existing_route'::text AS issue_type,
    obr.company_id,
    obr.id AS entity_id,
    jsonb_build_object('grid_owner_id', obr.grid_owner_id, 'environment', (obr.payload ->> 'environment'::text)) AS details
   FROM public.outbound_requests obr
  WHERE ((obr.communication_route_id IS NULL) AND (obr.grid_owner_id IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM public.communication_routes cr
          WHERE ((cr.company_id = obr.company_id) AND (cr.grid_owner_id = obr.grid_owner_id) AND (cr.is_active = true)))));

--
-- Name: tenant_email_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_email_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid,
    customer_case_id uuid,
    email_type text NOT NULL,
    to_email text NOT NULL,
    from_email text,
    reply_to_email text,
    subject text NOT NULL,
    html_body text NOT NULL,
    text_body text,
    status text DEFAULT 'queued'::text NOT NULL,
    provider_message_id text,
    failure_reason text,
    branding_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    redirect_url text,
    created_by uuid,
    sent_at timestamp with time zone,
    failed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 5,
    next_attempt_at timestamp with time zone,
    dead_letter_at timestamp with time zone,
    last_error text,
    request_id text,
    trace_id text,
    communication_log_id uuid,
    locked_at timestamp with time zone,
    locked_by text,
    lock_token uuid,
    provider_idempotency_key text,
    delivery_uncertain_at timestamp with time zone,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    blocked_reason text,
    blocked_at timestamp with time zone,
    company_status_snapshot text,
    CONSTRAINT tenant_email_outbox_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'delivery_uncertain'::text, 'sent'::text, 'failed'::text, 'cancelled'::text, 'blocked_tenant_state'::text])))
);

--
-- Name: gridex_ops_hardening_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_ops_hardening_health_v WITH (security_invoker='true') AS
 SELECT 'customer_operation_stale'::text AS check_key,
    count(*) AS issue_count,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'warning'::text
        END AS status
   FROM public.customer_operation_jobs
  WHERE ((customer_operation_jobs.status = 'running'::text) AND (customer_operation_jobs.locked_at < (now() - '00:15:00'::interval)))
UNION ALL
 SELECT 'tenant_email_delivery_uncertain'::text AS check_key,
    count(*) AS issue_count,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'warning'::text
        END AS status
   FROM public.tenant_email_outbox
  WHERE (tenant_email_outbox.status = 'delivery_uncertain'::text)
UNION ALL
 SELECT 'ediel_delivery_uncertain'::text AS check_key,
    count(*) AS issue_count,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'blocking'::text
        END AS status
   FROM public.ediel_outbox
  WHERE (ediel_outbox.status = 'delivery_uncertain'::text)
UNION ALL
 SELECT 'webhook_stale_processing'::text AS check_key,
    count(*) AS issue_count,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'warning'::text
        END AS status
   FROM public.webhook_deliveries
  WHERE ((webhook_deliveries.status = 'processing'::text) AND (webhook_deliveries.locked_at < (now() - '00:15:00'::interval)));

--
-- Name: gridex_performance_hardening_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gridex_performance_hardening_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_key text NOT NULL,
    status text DEFAULT 'completed'::text NOT NULL,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: TABLE gridex_performance_hardening_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.gridex_performance_hardening_events IS 'Service-only table: accessed via backend service role. RLS enabled with no policies by design (deny-by-default for anon/authenticated); direct API-role grants revoked by advisor hardening 20260709163000.';

--
-- Name: gridex_public_contract_offer_admin_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_public_contract_offer_admin_v WITH (security_invoker='true') AS
 SELECT o.id,
    o.company_id,
    c.name AS company_name,
    o.offer_code,
    o.public_name,
    o.public_description,
    o.contract_type,
    o.billing_model,
    o.customer_type,
    o.price_plan_id,
    pp.name AS price_plan_name,
    pp.pricing_model AS price_plan_model,
    pp.status AS price_plan_status,
    o.price_plan_version_id,
    ppv.version_label AS price_plan_version_label,
    ppv.status AS price_plan_version_status,
    ppv.valid_from AS price_plan_version_valid_from,
    ppv.valid_to AS price_plan_version_valid_to,
    o.campaign_version_id,
    o.monthly_fee_sek,
    o.invoice_fee_sek,
    o.markup_ore_per_kwh,
    o.spot_markup_ore_per_kwh,
    o.variable_fee_ore_per_kwh,
    o.fixed_price_ore_per_kwh,
    o.green_fee_mode,
    o.green_fee_value,
    o.terms_version,
    o.terms_url,
    o.public_price_text,
    o.binding_months,
    o.notice_months,
    o.spot_weight_percent,
    o.portfolio_weight_percent,
    o.fixed_weight_percent,
    o.price_area,
    o.valid_from,
    o.valid_to,
    o.publication_status,
    o.website_enabled,
    o.website_cta_enabled,
    o.is_public,
    o.is_archived,
    o.sort_order,
    o.readiness_issues,
    array_remove(ARRAY[
        CASE
            WHEN (o.price_plan_id IS NULL) THEN 'Prisplan saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (o.price_plan_version_id IS NULL) THEN 'Prisversion saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((o.price_plan_id IS NOT NULL) AND (pp.company_id IS DISTINCT FROM o.company_id)) THEN 'Prisplanen tillhör annat bolag'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((o.price_plan_version_id IS NOT NULL) AND (ppv.company_id IS DISTINCT FROM o.company_id)) THEN 'Prisversionen tillhör annat bolag'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((o.price_plan_version_id IS NOT NULL) AND (ppv.price_plan_id IS DISTINCT FROM o.price_plan_id)) THEN 'Prisversionen hör inte till vald prisplan'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(o.terms_version, ''::text) IS NULL) THEN 'Villkorsversion saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(o.public_price_text, ''::text) IS NULL) THEN 'Publik pristext saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((o.contract_type = ANY (ARRAY['portfolio'::text, 'mixed'::text])) AND (round(((COALESCE(o.spot_weight_percent, (0)::numeric) + COALESCE(o.portfolio_weight_percent, (0)::numeric)) + COALESCE(o.fixed_weight_percent, (0)::numeric)), 6) <> (100)::numeric)) THEN 'Fördelningen måste bli 100%'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((o.valid_to IS NOT NULL) AND (o.valid_from IS NOT NULL) AND (o.valid_to < o.valid_from)) THEN 'Giltighetsdatum är fel'::text
            ELSE NULL::text
        END], NULL::text) AS calculated_readiness_issues,
    ((o.price_plan_id IS NOT NULL) AND (o.price_plan_version_id IS NOT NULL) AND (pp.company_id = o.company_id) AND (ppv.company_id = o.company_id) AND (ppv.price_plan_id = o.price_plan_id) AND (NULLIF(o.terms_version, ''::text) IS NOT NULL) AND (NULLIF(o.public_price_text, ''::text) IS NOT NULL) AND ((o.contract_type <> ALL (ARRAY['portfolio'::text, 'mixed'::text])) OR (round(((COALESCE(o.spot_weight_percent, (0)::numeric) + COALESCE(o.portfolio_weight_percent, (0)::numeric)) + COALESCE(o.fixed_weight_percent, (0)::numeric)), 6) = (100)::numeric)) AND ((o.valid_to IS NULL) OR (o.valid_from IS NULL) OR (o.valid_to >= o.valid_from))) AS can_publish,
    o.published_at,
    o.archived_at,
    o.created_at,
    o.updated_at,
    o.metadata
   FROM (((public.public_contract_offers o
     LEFT JOIN public.companies c ON ((c.id = o.company_id)))
     LEFT JOIN public.price_plans pp ON ((pp.id = o.price_plan_id)))
     LEFT JOIN public.price_plan_versions ppv ON ((ppv.id = o.price_plan_version_id)));

--
-- Name: gridex_public_contract_offer_api_diagnostics_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_public_contract_offer_api_diagnostics_v WITH (security_invoker='true') AS
 WITH api_clients AS (
         SELECT integration_api_clients.company_id,
            count(*) FILTER (WHERE ((integration_api_clients.status = 'active'::text) AND (integration_api_clients.scopes @> ARRAY['website_contracts.read'::text]))) AS website_read_client_count
           FROM public.integration_api_clients
          GROUP BY integration_api_clients.company_id
        ), canonical_state AS (
         SELECT o.id,
            cpv.id AS contract_publication_version_id,
            cpv.status AS contract_publication_status,
            cpv.locked_at AS contract_publication_locked_at,
            cpv.legal_bundle_version_id,
            lbv.status AS legal_bundle_version_status,
            lbv.locked_at AS legal_bundle_version_locked_at,
            lbv.unresolved_variables,
            COALESCE(docs.document_count, (0)::bigint) AS document_count,
            readiness.can_display,
            readiness.can_accept_applications,
            COALESCE(readiness.display_blockers, '{}'::text[]) AS display_blockers
           FROM ((((public.public_contract_offers o
             LEFT JOIN public.contract_publication_versions cpv ON (((cpv.id = o.contract_publication_version_id) AND (cpv.legacy_public_contract_offer_id = o.id))))
             LEFT JOIN public.legal_bundle_versions lbv ON (((lbv.id = cpv.legal_bundle_version_id) AND (lbv.company_id = o.company_id))))
             LEFT JOIN public.contract_publication_readiness_v readiness ON (((readiness.contract_publication_version_id = cpv.id) AND (readiness.company_id = o.company_id))))
             LEFT JOIN LATERAL ( SELECT count(DISTINCT d.module_key) AS document_count
                   FROM public.legal_bundle_version_documents d
                  WHERE ((d.legal_bundle_version_id = cpv.legal_bundle_version_id) AND (COALESCE(array_length(d.unresolved_variables, 1), 0) = 0))) docs ON (true))
        ), canonical_blockers AS (
         SELECT state.id,
            COALESCE(ARRAY( SELECT DISTINCT
                        CASE
                            WHEN (blocker.blocker = 'tenant_legal_profile_missing'::text) THEN 'Bolagets juridikprofil saknas'::text
                            WHEN (blocker.blocker = 'tenant_legal_profile_incomplete'::text) THEN 'Bolagets juridikprofil är ofullständig'::text
                            WHEN (blocker.blocker = 'tenant_legal_profile_review_required'::text) THEN 'Bolagets juridikprofil behöver godkännas'::text
                            WHEN (blocker.blocker = 'contract_version_not_approved'::text) THEN 'Avtalsversionen är inte godkänd'::text
                            WHEN (blocker.blocker = 'price_areas_missing'::text) THEN 'Elområden saknas'::text
                            WHEN (blocker.blocker = 'price_area_invalid'::text) THEN 'Ett eller flera elområden är ogiltiga'::text
                            WHEN (blocker.blocker = 'price_plan_not_active'::text) THEN 'Prisplanen är inte aktiv'::text
                            WHEN (blocker.blocker = 'price_plan_version_not_locked'::text) THEN 'Prisversionen är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'price_book_not_locked'::text) THEN 'Prislistan är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'legal_bundle_not_locked'::text) THEN 'Den juridiska paketversionen är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'unresolved_legal_variables'::text) THEN 'Juridikpaketet innehåller olösta variabler'::text
                            WHEN (blocker.blocker = 'invalid_validity_period'::text) THEN 'Avtalets giltighetsperiod är ogiltig'::text
                            WHEN (blocker.blocker = 'portfolio_price_source_missing_or_unlocked'::text) THEN 'Portföljpriset saknas eller är inte låst'::text
                            WHEN (blocker.blocker = 'website_contracts_read_scope_missing'::text) THEN 'Aktiv API-klient med website_contracts.read saknas'::text
                            WHEN (blocker.blocker ~~ 'missing_legal_module:%'::text) THEN ('Juridikmodul saknas: '::text || replace(split_part(blocker.blocker, ':'::text, 2), '_'::text, ' '::text))
                            ELSE replace(blocker.blocker, '_'::text, ' '::text)
                        END AS replace
                   FROM unnest(state.display_blockers) blocker(blocker)
                  ORDER BY
                        CASE
                            WHEN (blocker.blocker = 'tenant_legal_profile_missing'::text) THEN 'Bolagets juridikprofil saknas'::text
                            WHEN (blocker.blocker = 'tenant_legal_profile_incomplete'::text) THEN 'Bolagets juridikprofil är ofullständig'::text
                            WHEN (blocker.blocker = 'tenant_legal_profile_review_required'::text) THEN 'Bolagets juridikprofil behöver godkännas'::text
                            WHEN (blocker.blocker = 'contract_version_not_approved'::text) THEN 'Avtalsversionen är inte godkänd'::text
                            WHEN (blocker.blocker = 'price_areas_missing'::text) THEN 'Elområden saknas'::text
                            WHEN (blocker.blocker = 'price_area_invalid'::text) THEN 'Ett eller flera elområden är ogiltiga'::text
                            WHEN (blocker.blocker = 'price_plan_not_active'::text) THEN 'Prisplanen är inte aktiv'::text
                            WHEN (blocker.blocker = 'price_plan_version_not_locked'::text) THEN 'Prisversionen är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'price_book_not_locked'::text) THEN 'Prislistan är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'legal_bundle_not_locked'::text) THEN 'Den juridiska paketversionen är inte publicerad och låst'::text
                            WHEN (blocker.blocker = 'unresolved_legal_variables'::text) THEN 'Juridikpaketet innehåller olösta variabler'::text
                            WHEN (blocker.blocker = 'invalid_validity_period'::text) THEN 'Avtalets giltighetsperiod är ogiltig'::text
                            WHEN (blocker.blocker = 'portfolio_price_source_missing_or_unlocked'::text) THEN 'Portföljpriset saknas eller är inte låst'::text
                            WHEN (blocker.blocker = 'website_contracts_read_scope_missing'::text) THEN 'Aktiv API-klient med website_contracts.read saknas'::text
                            WHEN (blocker.blocker ~~ 'missing_legal_module:%'::text) THEN ('Juridikmodul saknas: '::text || replace(split_part(blocker.blocker, ':'::text, 2), '_'::text, ' '::text))
                            ELSE replace(blocker.blocker, '_'::text, ' '::text)
                        END), '{}'::text[]) AS blockers
           FROM canonical_state state
        ), diagnostic_base AS (
         SELECT o.id,
            o.company_id,
            o.offer_code,
            o.public_name,
            o.publication_status,
            o.website_enabled,
            o.is_public,
            o.is_archived,
            o.customer_type,
            o.valid_from,
            o.valid_to,
            o.sort_order,
            o.legal_bundle_id,
            o.price_book_id,
            COALESCE(clients.website_read_client_count, (0)::bigint) AS matched_api_client_count,
            COALESCE(state.document_count, (0)::bigint) AS published_legal_type_count,
            COALESCE(pb.status, 'missing'::text) AS price_book_status,
            state.contract_publication_version_id,
            state.contract_publication_status,
            state.contract_publication_locked_at,
            state.legal_bundle_version_id,
            state.legal_bundle_version_status,
            state.legal_bundle_version_locked_at,
            state.unresolved_variables,
            state.can_display,
            COALESCE(blockers.blockers, '{}'::text[]) AS canonical_blockers,
            array_remove(ARRAY[
                CASE
                    WHEN (COALESCE(o.publication_status, 'draft'::text) <> 'published'::text) THEN 'Avtalet är inte publicerat'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(o.website_enabled, false) IS FALSE) THEN 'Avtalet är inte markerat för hemsidan'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(o.is_archived, false) IS TRUE) THEN 'Avtalet är arkiverat'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((o.valid_from IS NOT NULL) AND (o.valid_from > CURRENT_DATE)) THEN 'Avtalet börjar gälla i framtiden'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((o.valid_to IS NOT NULL) AND (o.valid_to < CURRENT_DATE)) THEN 'Avtalet har gått ut'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (state.contract_publication_version_id IS NULL) THEN 'Kanonisk publiceringsversion saknas'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((state.contract_publication_version_id IS NOT NULL) AND (COALESCE(state.contract_publication_status, 'draft'::text) <> 'published'::text)) THEN 'Publiceringsversionen är inte publicerad'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((state.contract_publication_version_id IS NOT NULL) AND (state.contract_publication_locked_at IS NULL)) THEN 'Publiceringsversionen är inte låst'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (state.legal_bundle_version_id IS NULL) THEN 'Kanonisk juridisk paketversion saknas'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((state.legal_bundle_version_id IS NOT NULL) AND (COALESCE(state.legal_bundle_version_status, 'draft'::text) <> 'published'::text)) THEN 'Den juridiska paketversionen är inte publicerad'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((state.legal_bundle_version_id IS NOT NULL) AND (state.legal_bundle_version_locked_at IS NULL)) THEN 'Den juridiska paketversionen är inte låst'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((state.legal_bundle_version_id IS NOT NULL) AND (COALESCE(state.document_count, (0)::bigint) = 0)) THEN 'Juridikpaketet innehåller inga renderade juridikmoduler'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(array_length(state.unresolved_variables, 1), 0) > 0) THEN 'Juridikpaketet innehåller olösta variabler'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(clients.website_read_client_count, (0)::bigint) = 0) THEN 'Aktiv API-klient med website_contracts.read saknas'::text
                    ELSE NULL::text
                END], NULL::text) AS direct_blockers
           FROM ((((public.public_contract_offers o
             LEFT JOIN canonical_state state ON ((state.id = o.id)))
             LEFT JOIN canonical_blockers blockers ON ((blockers.id = o.id)))
             LEFT JOIN public.price_books pb ON (((pb.id = o.price_book_id) AND (pb.company_id = o.company_id))))
             LEFT JOIN api_clients clients ON ((clients.company_id = o.company_id)))
        ), normalized AS (
         SELECT base.id,
            base.company_id,
            base.offer_code,
            base.public_name,
            base.publication_status,
            base.website_enabled,
            base.is_public,
            base.is_archived,
            base.customer_type,
            base.valid_from,
            base.valid_to,
            base.sort_order,
            base.legal_bundle_id,
            base.price_book_id,
            base.matched_api_client_count,
            base.published_legal_type_count,
            base.price_book_status,
            base.contract_publication_version_id,
            base.contract_publication_status,
            base.contract_publication_locked_at,
            base.legal_bundle_version_id,
            base.legal_bundle_version_status,
            base.legal_bundle_version_locked_at,
            base.unresolved_variables,
            base.can_display,
            base.canonical_blockers,
            base.direct_blockers,
            COALESCE(ARRAY( SELECT DISTINCT blocker.blocker
                   FROM unnest((COALESCE(base.direct_blockers, '{}'::text[]) || base.canonical_blockers)) blocker(blocker)
                  WHERE (NULLIF(btrim(blocker.blocker), ''::text) IS NOT NULL)
                  ORDER BY blocker.blocker), '{}'::text[]) AS all_blockers
           FROM diagnostic_base base
        )
 SELECT id,
    company_id,
    offer_code,
    public_name,
    publication_status,
    website_enabled,
    is_public,
    is_archived,
    customer_type,
    valid_from,
    valid_to,
    sort_order,
    legal_bundle_id,
    price_book_id,
    matched_api_client_count,
    published_legal_type_count,
    price_book_status,
    NULLIF(all_blockers, '{}'::text[]) AS api_blockers,
    ((COALESCE(publication_status, 'draft'::text) = 'published'::text) AND (COALESCE(website_enabled, false) IS TRUE) AND (COALESCE(is_archived, false) IS FALSE) AND ((valid_from IS NULL) OR (valid_from <= CURRENT_DATE)) AND ((valid_to IS NULL) OR (valid_to >= CURRENT_DATE)) AND (contract_publication_version_id IS NOT NULL) AND (contract_publication_status = 'published'::text) AND (contract_publication_locked_at IS NOT NULL) AND (legal_bundle_version_id IS NOT NULL) AND (legal_bundle_version_status = 'published'::text) AND (legal_bundle_version_locked_at IS NOT NULL) AND (published_legal_type_count > 0) AND (COALESCE(array_length(unresolved_variables, 1), 0) = 0) AND COALESCE(can_display, false) AND (matched_api_client_count > 0) AND (COALESCE(array_length(all_blockers, 1), 0) = 0)) AS api_visible,
    '/api/v1/website/public-contracts'::text AS endpoint_path
   FROM normalized;

--
-- Name: VIEW gridex_public_contract_offer_api_diagnostics_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_public_contract_offer_api_diagnostics_v IS 'Admin diagnostic aligned with canonical contract_publication_versions and immutable legal_bundle_version_documents. The legacy legal_bundle_id is retained only as a compatibility column and is not a readiness source.';

--
-- Name: website_contract_quotes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.website_contract_quotes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    api_client_id uuid,
    quote_reference text NOT NULL,
    offer_reference text NOT NULL,
    contract_product_version_id uuid,
    contract_publication_version_id uuid,
    price_plan_version_id uuid,
    legal_bundle_version_id uuid,
    customer_type text NOT NULL,
    price_area text NOT NULL,
    grid_area_code text,
    postal_code text,
    annual_consumption_kwh numeric(18,3) NOT NULL,
    start_date date NOT NULL,
    market_data_timestamp timestamp with time zone,
    market_sources jsonb DEFAULT '[]'::jsonb NOT NULL,
    assumptions jsonb DEFAULT '[]'::jsonb NOT NULL,
    pricing_snapshot_schema_version text NOT NULL,
    quote_snapshot jsonb NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    consumed_at timestamp with time zone,
    consumed_application_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    energy_resolution_id uuid,
    resolution_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    resolver_version text,
    geodata_version text,
    market_reference jsonb DEFAULT '{}'::jsonb NOT NULL,
    quote_hash text,
    resolution_binding_status text DEFAULT 'legacy_unverified'::text NOT NULL,
    contract_product_id uuid,
    price_plan_id uuid,
    price_book_id uuid,
    energy_direction text NOT NULL,
    quote_hash_version text DEFAULT 'v2_full_quote'::text NOT NULL,
    price_option_reference text,
    area_price_reference text,
    invoice_delivery_method text,
    selected_component_references text[] DEFAULT '{}'::text[] NOT NULL,
    mandatory_component_references text[] DEFAULT '{}'::text[] NOT NULL,
    conditional_component_references text[] DEFAULT '{}'::text[] NOT NULL,
    resolved_base_components jsonb DEFAULT '[]'::jsonb NOT NULL,
    resolved_price_components jsonb DEFAULT '[]'::jsonb NOT NULL,
    site_count integer DEFAULT 1 NOT NULL,
    CONSTRAINT website_contract_quotes_annual_consumption_kwh_check CHECK ((annual_consumption_kwh > (0)::numeric)),
    CONSTRAINT website_contract_quotes_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text]))),
    CONSTRAINT website_contract_quotes_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT website_contract_quotes_hash_version_check CHECK ((quote_hash_version = ANY (ARRAY['v1_snapshot_only'::text, 'v2_full_quote'::text, 'v3_commercial_selection'::text]))),
    CONSTRAINT website_contract_quotes_invoice_delivery_check CHECK (((invoice_delivery_method IS NULL) OR (invoice_delivery_method = ANY (ARRAY['email'::text, 'e_invoice'::text, 'paper'::text, 'direct_debit'::text])))),
    CONSTRAINT website_contract_quotes_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT website_contract_quotes_resolution_binding_status_check CHECK ((resolution_binding_status = ANY (ARRAY['verified'::text, 'legacy_unverified'::text]))),
    CONSTRAINT website_contract_quotes_site_count_check CHECK ((site_count > 0)),
    CONSTRAINT website_contract_quotes_status_check CHECK ((status = ANY (ARRAY['active'::text, 'consumed'::text, 'expired'::text, 'revoked'::text]))),
    CONSTRAINT website_contract_quotes_v3_selection_check CHECK (((quote_hash_version <> 'v3_commercial_selection'::text) OR ((pricing_snapshot_schema_version = 'gridex_contract_pricing_v6_selection'::text) AND (price_option_reference IS NOT NULL) AND (invoice_delivery_method IS NOT NULL) AND (jsonb_typeof(resolved_base_components) = 'array'::text) AND (jsonb_typeof(resolved_price_components) = 'array'::text))))
);

--
-- Name: TABLE website_contract_quotes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.website_contract_quotes IS 'Canonical tenant-bound website quotes. The quote freezes offer/version identity, customer type, SE area, consumption, start date, selected area price and calculation snapshot and may be consumed by only one website application.';

--
-- Name: COLUMN website_contract_quotes.valid_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.valid_until IS 'V1 compatibility and immutable audit metadata. Website customer quotes do not expire solely because this timestamp passes.';

--
-- Name: COLUMN website_contract_quotes.energy_resolution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.energy_resolution_id IS 'Tenant-bound canonical OPS resolution used to derive the quote price area.';

--
-- Name: COLUMN website_contract_quotes.market_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.market_reference IS 'Immutable provenance for indicative market data. Never final settlement evidence.';

--
-- Name: COLUMN website_contract_quotes.energy_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.energy_direction IS 'Immutable consumption/production direction copied from the exact published product version.';

--
-- Name: COLUMN website_contract_quotes.resolved_price_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.resolved_price_components IS 'Exact eligible and selected components covered by the immutable v3 quote hash.';

--
-- Name: COLUMN website_contract_quotes.site_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.website_contract_quotes.site_count IS 'Immutable v3 commercial assertion included in quote_hash.';

--
-- Name: gridex_quotes_without_canonical_resolution_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_quotes_without_canonical_resolution_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    quote_reference,
    offer_reference,
    status,
    created_at,
    valid_until,
    resolution_binding_status
   FROM public.website_contract_quotes
  WHERE ((energy_resolution_id IS NULL) OR (resolution_binding_status <> 'verified'::text));

--
-- Name: gridex_rls_policy_inventory_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_rls_policy_inventory_v WITH (security_invoker='true') AS
 SELECT schemaname,
    tablename,
    count(*) AS policy_count,
    count(*) FILTER (WHERE (cmd = 'SELECT'::text)) AS select_policy_count,
    count(*) FILTER (WHERE (cmd = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text, 'ALL'::text]))) AS write_policy_count,
    count(*) FILTER (WHERE (roles @> ARRAY['public'::name])) AS public_role_policy_count,
    count(*) FILTER (WHERE ((COALESCE(qual, ''::text) ~~* '%auth.%()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%auth.%()%'::text) OR (COALESCE(qual, ''::text) ~~* '%gridex_user_is_platform_admin()%'::text) OR (COALESCE(with_check, ''::text) ~~* '%gridex_user_is_platform_admin()%'::text))) AS possible_unoptimized_policy_count,
    array_agg(policyname ORDER BY policyname) AS policy_names
   FROM pg_policies
  WHERE (schemaname = 'public'::name)
  GROUP BY schemaname, tablename;

--
-- Name: gridex_runtime_operational_integrity_v3; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_runtime_operational_integrity_v3 WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM ( SELECT integration_api_clients.company_id,
                    COALESCE(NULLIF((integration_api_clients.metadata ->> 'environment'::text), ''::text), 'production'::text) AS environment
                   FROM public.integration_api_clients
                  WHERE ((integration_api_clients.profile_key = 'tenant_website'::text) AND (integration_api_clients.status = 'active'::text) AND (integration_api_clients.deleted_at IS NULL) AND (lower(COALESCE((integration_api_clients.metadata ->> 'primary'::text), 'true'::text)) <> ALL (ARRAY['false'::text, '0'::text, 'no'::text])))
                  GROUP BY integration_api_clients.company_id, COALESCE(NULLIF((integration_api_clients.metadata ->> 'environment'::text), ''::text), 'production'::text)
                 HAVING (count(*) > 1)) duplicate_groups) AS duplicate_primary_groups,
    ((( SELECT count(*) AS count
           FROM public.ediel_messages
          WHERE (ediel_messages.company_id IS NULL)) + ( SELECT count(*) AS count
           FROM public.ediel_outbox
          WHERE (ediel_outbox.company_id IS NULL))) + ( SELECT count(*) AS count
           FROM public.billing_underlays
          WHERE (billing_underlays.company_id IS NULL))) AS tenantless_operational_rows,
    ( SELECT count(*) AS count
           FROM public.integration_api_clients
          WHERE ((integration_api_clients.status = 'active'::text) AND (integration_api_clients.deleted_at IS NULL) AND ((integration_api_clients.rate_limit_per_minute IS NULL) OR (integration_api_clients.rate_limit_per_minute <= 0)))) AS invalid_active_api_clients;

