xt,'area_price_reference'::text), ('website_contract_quotes'::text,'invoice_delivery_method'::text), ('website_contract_quotes'::text,'selected_component_references'::text), ('website_contract_quotes'::text,'mandatory_component_references'::text), ('website_contract_quotes'::text,'conditional_component_references'::text), ('website_contract_quotes'::text,'site_count'::text), ('canonical_public_contract_delivery_readiness_v'::text,'company_id'::text), ('canonical_public_contract_delivery_readiness_v'::text,'channel'::text), ('canonical_public_contract_delivery_readiness_v'::text,'offer_reference'::text), ('canonical_public_contract_delivery_readiness_v'::text,'publication_version_id'::text), ('canonical_public_contract_delivery_readiness_v'::text,'canonical_graph_consistent'::text), ('canonical_public_contract_delivery_readiness_v'::text,'blockers'::text), ('canonical_public_contract_delivery_readiness_v'::text,'visible'::text)
