        ), rls_relations(name) AS (
         VALUES ('companies'::text), ('company_memberships'::text), ('integration_api_clients'::text), ('integration_api_rate_limit_events'::text), ('customers'::text), ('customer_sites'::text), ('metering_points'::text), ('customer_contracts'::text), ('customer_invoices'::text), ('customer_documents'::text), ('customer_events'::text), ('customer_notifications'::text), ('powers_of_attorney'::text), ('ediel_messages'::text), ('ediel_outbox'::text), ('metering_values'::text), ('normalized_metering_values'::text), ('billing_underlays'::text), ('manual_email_outbox'::text), ('website_customer_applications'::text), ('website_contract_quotes'::text), ('tenant_website_installation_receipts'::text), ('canonical_migration_manifest'::text)
        ), policy_required(name) AS (
