        ), invoker_views(name) AS (
         VALUES ('canonical_public_contract_delivery_readiness_v'::text), ('canonical_public_contract_diagnostics_v'::text), ('canonical_public_contract_offers_v'::text)
        ), catalog_columns AS MATERIALIZED (
         SELECT (cls.relname)::text AS table_name,
            (a.attname)::text AS column_name,
            (a.attnum)::integer AS ordinal_position,
            (t.typname)::text AS udt_name,
                CASE
                    WHEN (a.attnotnull OR ((t.typtype = 'd'::"char") AND t.typnotnull)) THEN 'NO'::text
                    ELSE 'YES'::text
                END AS is_nullable,
                CASE
                    WHEN (a.attgenerated <> ''::"char") THEN ''::text
                    ELSE COALESCE(pg_get_expr(ad.adbin, ad.adrelid), ''::text)
                END AS column_default
           FROM (((((required_relations r
             JOIN pg_namespace n ON ((n.nspname = 'public'::name)))
             JOIN pg_class cls ON (((cls.relnamespace = n.oid) AND (cls.relname = r.name) AND (cls.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'f'::"char", 'p'::"char"])))))
             JOIN pg_attribute a ON (((a.attrelid = cls.oid) AND (a.attnum > 0) AND (NOT a.attisdropped))))
             JOIN pg_type t ON ((t.oid = a.atttypid)))
             LEFT JOIN pg_attrdef ad ON (((ad.adrelid = a.attrelid) AND (ad.adnum = a.attnum))))
        ), missing_relations AS (
         SELECT COALESCE(array_agg(r.name ORDER BY r.name), '{}'::text[]) AS items
           FROM required_relations r
          WHERE (to_regclass(format('public.%I'::text, r.name)) IS NULL)
        ), missing_columns AS (
         SELECT COALESCE(array_agg(((r.table_name || '.'::text) || r.column_name) ORDER BY r.table_name, r.column_name), '{}'::text[]) AS items
           FROM required_columns r
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM catalog_columns c
                  WHERE ((c.table_name = r.table_name) AND (c.column_name = r.column_name)))))
        ), missing_functions AS (
         SELECT COALESCE(array_agg(r.signature ORDER BY r.signature), '{}'::text[]) AS items
           FROM required_functions r
          WHERE (to_regprocedure(('public.'::text || r.signature)) IS NULL)
        ), rls_gaps AS (
         SELECT COALESCE(array_agg(r.name ORDER BY r.name), '{}'::text[]) AS items
           FROM (rls_relations r
             LEFT JOIN pg_class c ON ((c.oid = (to_regclass(format('public.%I'::text, r.name)))::oid)))
          WHERE ((c.oid IS NULL) OR (NOT c.relrowsecurity))
        ), policy_gaps AS (
         SELECT COALESCE(array_agg(r.name ORDER BY r.name), '{}'::text[]) AS items
           FROM policy_required r
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM pg_policies p
                  WHERE ((p.schemaname = 'public'::name) AND (p.tablename = r.name)))))
        ), view_gaps AS (
         SELECT COALESCE(array_agg(v.name ORDER BY v.name), '{}'::text[]) AS items
           FROM (invoker_views v
             JOIN pg_class c ON ((c.oid = (to_regclass(format('public.%I'::text, v.name)))::oid)))
          WHERE (NOT ('security_invoker=true'::text = ANY (COALESCE(c.reloptions, '{}'::text[]))))
        ), acl_gaps AS (
         SELECT COALESCE(array_agg(r.signature ORDER BY r.signature), '{}'::text[]) AS items
           FROM (required_functions r
             JOIN pg_proc p ON ((p.oid = (to_regprocedure(('public.'::text || r.signature)))::oid)))
          WHERE (has_function_privilege('anon'::name, p.oid, 'EXECUTE'::text) OR has_function_privilege('authenticated'::name, p.oid, 'EXECUTE'::text) OR (NOT has_function_privilege('service_role'::name, p.oid, 'EXECUTE'::text)))
        ), fingerprint_material AS (
         SELECT concat_ws('
'::text, COALESCE(( SELECT string_agg((((((((c.relname)::text || ':'::text) || (c.relkind)::text) || ':'::text) || (c.relrowsecurity)::text) || ':'::text) || COALESCE(array_to_string(c.reloptions, ','::text), ''::text)), '
'::text ORDER BY c.relname) AS string_agg
                   FROM (pg_class c
                     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
                  WHERE ((n.nspname = 'public'::name) AND (c.relname IN ( SELECT required_relations.name
                           FROM required_relations)))), ''::text), COALESCE(( SELECT string_agg(((((((((c.table_name || '.'::text) || c.column_name) || ':'::text) || c.udt_name) || ':'::text) || c.is_nullable) || ':'::text) || c.column_default), '
'::text ORDER BY c.table_name, c.ordinal_position) AS string_agg
                   FROM catalog_columns c), ''::text), COALESCE(( SELECT string_agg(((((((((p.oid)::regprocedure)::text || ':'::text) || (p.prosecdef)::text) || ':'::text) || COALESCE(array_to_string(p.proconfig, ','::text), ''::text)) || ':'::text) || pg_get_functiondef(p.oid)), '
'::text ORDER BY ((p.oid)::regprocedure)::text) AS string_agg
                   FROM pg_proc p
                  WHERE (p.oid IN ( SELECT to_regprocedure(('public.'::text || r.signature)) AS to_regprocedure
                           FROM required_functions r))), ''::text), COALESCE(( SELECT string_agg((((((((((((p.tablename)::text || ':'::text) || (p.policyname)::text) || ':'::text) || p.cmd) || ':'::text) || array_to_string(p.roles, ','::text)) || ':'::text) || COALESCE(p.qual, ''::text)) || ':'::text) || COALESCE(p.with_check, ''::text)), '
'::text ORDER BY p.tablename, p.policyname) AS string_agg
                   FROM pg_policies p
                  WHERE ((p.schemaname = 'public'::name) AND (p.tablename IN ( SELECT rls_relations.name
                           FROM rls_relations)))), ''::text)) AS value
        )
 SELECT missing_relations.items AS missing_relations,
    missing_columns.items AS missing_columns,
    missing_functions.items AS missing_functions,
    rls_gaps.items AS rls_gaps,
    policy_gaps.items AS policy_gaps,
    view_gaps.items AS view_security_gaps,
    acl_gaps.items AS function_acl_gaps,
    encode(extensions.digest(convert_to(fingerprint_material.value, 'UTF8'::name), 'sha256'::text), 'hex'::text) AS schema_fingerprint
   FROM missing_relations,
    missing_columns,
    missing_functions,
    rls_gaps,
    policy_gaps,
    view_gaps,
    acl_gaps,
    fingerprint_material;

--
-- Name: VIEW gridex_runtime_schema_catalog_v3; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_runtime_schema_catalog_v3 IS 'Runtime capability catalog v3 using targeted pg_catalog metadata for the required Gridex relation set; preserves the existing fingerprint contract while avoiding broad information_schema expansion.';

--
-- Name: gridex_runtime_schema_capabilities_v3; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_runtime_schema_capabilities_v3 WITH (security_invoker='true') AS
 WITH result AS (
         SELECT array_remove(ARRAY[
                CASE
                    WHEN (cardinality(c.missing_relations) > 0) THEN 'RUNTIME_RELATION_MISSING'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.missing_columns) > 0) THEN 'RUNTIME_COLUMN_MISSING'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.missing_functions) > 0) THEN 'RUNTIME_FUNCTION_MISSING'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.rls_gaps) > 0) THEN 'RUNTIME_RLS_DISABLED'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.policy_gaps) > 0) THEN 'RUNTIME_RLS_POLICY_MISSING'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.view_security_gaps) > 0) THEN 'RUNTIME_VIEW_SECURITY_INVOKER_MISSING'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (cardinality(c.function_acl_gaps) > 0) THEN 'RUNTIME_FUNCTION_PRIVILEGE_DRIFT'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (o.duplicate_primary_groups > 0) THEN 'DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (o.tenantless_operational_rows > 0) THEN 'TENANTLESS_OPERATIONAL_ROWS'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (o.invalid_active_api_clients > 0) THEN 'ACTIVE_API_CLIENT_CONFIGURATION_INVALID'::text
                    ELSE NULL::text
                END], NULL::text) AS blockers,
            jsonb_build_object('missing_relations', c.missing_relations, 'missing_columns', c.missing_columns, 'missing_functions', c.missing_functions, 'rls_gaps', c.rls_gaps, 'policy_gaps', c.policy_gaps, 'view_security_gaps', c.view_security_gaps, 'function_acl_gaps', c.function_acl_gaps, 'duplicate_primary_groups', o.duplicate_primary_groups, 'tenantless_operational_rows', o.tenantless_operational_rows, 'invalid_active_api_clients', o.invalid_active_api_clients) AS capabilities,
            c.schema_fingerprint
           FROM (public.gridex_runtime_schema_catalog_v3 c
             CROSS JOIN public.gridex_runtime_operational_integrity_v3 o)
        )
 SELECT (cardinality(blockers) = 0) AS is_ready,
    schema_fingerprint,
    blockers AS blocking_issues,
    capabilities,
    now() AS evaluated_at
   FROM result;

--
-- Name: VIEW gridex_runtime_schema_capabilities_v3; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_runtime_schema_capabilities_v3 IS 'Fail-closed runtime capability and security gate. Migration governance is separate.';

