);

--
-- Name: gridex_spot_complete_unlocked_periods_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_complete_unlocked_periods_v WITH (security_invoker='true') AS
 SELECT 'day'::text AS period_type,
    spot_price_daily_summaries.id,
    spot_price_daily_summaries.source,
    spot_price_daily_summaries.price_area,
    (spot_price_daily_summaries.price_date)::text AS period_key,
    spot_price_daily_summaries.status,
    spot_price_daily_summaries.verified_at,
    spot_price_daily_summaries.locked_at
   FROM public.spot_price_daily_summaries
  WHERE (spot_price_daily_summaries.status = ANY (ARRAY['complete'::text, 'verified'::text]))
UNION ALL
 SELECT 'month'::text AS period_type,
    spot_price_monthly_summaries.id,
    spot_price_monthly_summaries.source,
    spot_price_monthly_summaries.price_area,
    spot_price_monthly_summaries.billing_month AS period_key,
    spot_price_monthly_summaries.status,
    spot_price_monthly_summaries.verified_at,
    spot_price_monthly_summaries.locked_at
   FROM public.spot_price_monthly_summaries
  WHERE (spot_price_monthly_summaries.status = ANY (ARRAY['complete'::text, 'verified'::text]));

--
-- Name: gridex_spot_incomplete_days_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_incomplete_days_v WITH (security_invoker='true') AS
 SELECT id,
    source,
    price_area,
    price_date,
    average_sek_per_kwh,
    min_sek_per_kwh,
    max_sek_per_kwh,
    interval_count,
    status,
    created_at,
    updated_at,
    period_start,
    period_end,
    expected_interval_count,
    covered_duration_minutes,
    expected_duration_minutes,
    resolution,
    quality_issues,
    provider_fetched_at,
    verified_at,
    locked_at,
    source_checksum
   FROM public.spot_price_daily_summaries
  WHERE (status = 'incomplete'::text);

--
-- Name: spot_price_intervals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_intervals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'elprisetjustnu'::text NOT NULL,
    price_area text NOT NULL,
    time_start timestamp with time zone NOT NULL,
    time_end timestamp with time zone NOT NULL,
    sek_per_kwh numeric NOT NULL,
    eur_per_kwh numeric,
    exchange_rate numeric,
    resolution text NOT NULL,
    source_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT spot_price_intervals_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_intervals_resolution_check CHECK ((resolution = ANY (ARRAY['hourly'::text, 'quarter_hour'::text]))),
    CONSTRAINT spot_price_intervals_time_check CHECK ((time_end > time_start))
);

--
-- Name: gridex_spot_interval_gaps_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_interval_gaps_v WITH (security_invoker='true') AS
 WITH ordered AS (
         SELECT spot_price_intervals.source,
            spot_price_intervals.price_area,
            spot_price_intervals.time_start,
            spot_price_intervals.time_end,
            lag(spot_price_intervals.time_end) OVER (PARTITION BY spot_price_intervals.source, spot_price_intervals.price_area ORDER BY spot_price_intervals.time_start, spot_price_intervals.time_end) AS previous_end
           FROM public.spot_price_intervals
        )
 SELECT source,
    price_area,
    previous_end AS gap_start,
    time_start AS gap_end,
    (EXTRACT(epoch FROM (time_start - previous_end)) / (60)::numeric) AS gap_minutes
   FROM ordered
  WHERE ((previous_end IS NOT NULL) AND (time_start > previous_end));

--
-- Name: gridex_spot_interval_overlaps_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_interval_overlaps_v WITH (security_invoker='true') AS
 WITH ordered AS (
         SELECT spot_price_intervals.source,
            spot_price_intervals.price_area,
            spot_price_intervals.id,
            spot_price_intervals.time_start,
            spot_price_intervals.time_end,
            lag(spot_price_intervals.time_end) OVER (PARTITION BY spot_price_intervals.source, spot_price_intervals.price_area ORDER BY spot_price_intervals.time_start, spot_price_intervals.time_end) AS previous_end
           FROM public.spot_price_intervals
        )
 SELECT source,
    price_area,
    id,
    time_start,
    time_end,
    previous_end
   FROM ordered
  WHERE ((previous_end IS NOT NULL) AND (time_start < previous_end));

--
-- Name: gridex_stale_market_previews_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_stale_market_previews_v WITH (security_invoker='true') AS
 SELECT id,
    provider,
    price_area,
    reference_period,
    period_start,
    period_end,
    as_of,
    price_sek_per_kwh,
    source_currency,
    unit,
    includes_vat,
    includes_supplier_fees,
    includes_grid_fees,
    is_indicative,
    fallback_used,
    fallback_reason,
    stale_after,
    status,
    source_summary_ids,
    source_checksum,
    metadata,
    created_at,
    updated_at,
    (now() > stale_after) AS is_stale
   FROM public.market_price_previews
  WHERE ((status = 'active'::text) AND (now() > stale_after));

--
-- Name: spot_price_import_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_import_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    provider text NOT NULL,
    price_area text NOT NULL,
    calendar_date date NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_checksum text,
    result_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT spot_price_import_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT spot_price_import_jobs_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_import_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'retry_wait'::text, 'completed'::text, 'failed'::text])))
);

--
-- Name: gridex_stuck_spot_import_jobs_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_stuck_spot_import_jobs_v WITH (security_invoker='true') AS
 SELECT id,
    provider,
    price_area,
    calendar_date,
    status,
    attempt_count,
    started_at,
    next_attempt_at,
    last_error_code,
    last_error_message,
    correlation_id,
    (now() - started_at) AS running_age
   FROM public.spot_price_import_jobs
  WHERE (((status = 'running'::text) AND (started_at < (now() - '00:15:00'::interval))) OR ((status = 'retry_wait'::text) AND (next_attempt_at IS NOT NULL) AND (next_attempt_at < (now() - '00:15:00'::interval))));

--
-- Name: gridex_tenant_contract_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_tenant_contract_readiness_v WITH (security_invoker='true') AS
 WITH publications AS (
         SELECT r.company_id,
            count(*) AS total_publication_versions,
            count(*) FILTER (WHERE (r.status = 'published'::text)) AS published_publication_versions,
            count(*) FILTER (WHERE ((r.status = 'published'::text) AND r.can_display)) AS display_ready_publications,
            count(*) FILTER (WHERE ((r.status = 'published'::text) AND r.can_accept_applications)) AS application_ready_publications,
            COALESCE(array_agg(DISTINCT blocker.code) FILTER (WHERE ((blocker.code IS NOT NULL) AND (r.status = 'published'::text))), '{}'::text[]) AS publication_blockers
           FROM (public.contract_publication_readiness_v r
             LEFT JOIN LATERAL unnest(r.application_blockers) blocker(code) ON (true))
          GROUP BY r.company_id
        )
 SELECT c.id AS company_id,
    c.name AS company_name,
        CASE
            WHEN (tlp.id IS NULL) THEN 'unknown'::text
            WHEN ((tlp.completeness_status = ANY (ARRAY['complete'::text, 'verified'::text])) AND (NOT COALESCE(tlp.review_required, false))) THEN 'ready'::text
            ELSE 'blocked'::text
        END AS legal_profile_status,
    COALESCE(tlp.missing_fields, ARRAY['tenant_legal_profile'::text]) AS legal_profile_missing_fields,
    COALESCE(tlp.review_required, false) AS legal_profile_review_required,
    tlp.verified_at AS legal_profile_verified_at,
    tlp.updated_at AS legal_profile_updated_at,
    COALESCE(p.total_publication_versions, (0)::bigint) AS total_publication_versions,
    COALESCE(p.published_publication_versions, (0)::bigint) AS published_publication_versions,
    (COALESCE(p.display_ready_publications, (0)::bigint) > 0) AS can_display,
    (COALESCE(p.application_ready_publications, (0)::bigint) > 0) AS can_accept_applications,
    COALESCE(p.publication_blockers, '{}'::text[]) AS publication_blockers,
        CASE
            WHEN (tlp.id IS NULL) THEN 'unknown'::text
            WHEN ((tlp.completeness_status <> ALL (ARRAY['complete'::text, 'verified'::text])) OR COALESCE(tlp.review_required, false)) THEN 'blocked'::text
            WHEN (COALESCE(p.published_publication_versions, (0)::bigint) = 0) THEN 'ready'::text
            WHEN (COALESCE(p.display_ready_publications, (0)::bigint) > 0) THEN 'ready'::text
            ELSE 'blocked'::text
        END AS overall_status,
    (COALESCE(p.published_publication_versions, (0)::bigint) = 0) AS no_published_contracts,
    now() AS evaluated_at
   FROM ((public.companies c
     LEFT JOIN public.tenant_legal_profiles tlp ON ((tlp.company_id = c.id)))
     LEFT JOIN publications p ON ((p.company_id = c.id)));

--
-- Name: VIEW gridex_tenant_contract_readiness_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_tenant_contract_readiness_v IS 'Single tenant-level readiness source. No published contract is informational, not a legal blocker. Display and application acceptance are separate.';

--
-- Name: gridex_tenant_effective_legal_sources_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_tenant_effective_legal_sources_v WITH (security_invoker='true') AS
 WITH latest_platform AS (
         SELECT DISTINCT ON (t_1.module_key) t_1.module_key,
            v.id AS platform_template_version_id,
            COALESCE(v.version_label, (v.version_number)::text) AS platform_version,
            v.title AS platform_title,
            v.content_sha256 AS platform_sha256
           FROM (public.legal_templates t_1
             JOIN public.legal_template_versions v ON ((v.legal_template_id = t_1.id)))
          WHERE ((t_1.status = 'active'::text) AND (v.status = 'published'::text) AND (v.locked_at IS NOT NULL))
          ORDER BY t_1.module_key, v.version_number DESC, v.published_at DESC NULLS LAST, v.created_at DESC
        ), latest_override AS (
         SELECT DISTINCT ON (o_1.company_id, o_1.module_key) o_1.company_id,
            o_1.module_key,
            o_1.id AS tenant_override_id,
            COALESCE(o_1.version_label, to_char((o_1.created_at AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD-HH24MISS'::text), "left"(o_1.content_sha256, 12)) AS tenant_override_version,
            o_1.legal_mode AS tenant_override_mode,
            o_1.title AS tenant_override_title,
            o_1.content_sha256 AS tenant_override_sha256
           FROM public.tenant_legal_overrides o_1
          WHERE ((o_1.status = ANY (ARRAY['approved'::text, 'published'::text])) AND (o_1.locked_at IS NOT NULL))
          ORDER BY o_1.company_id, o_1.module_key, o_1.reviewed_at DESC NULLS LAST, o_1.created_at DESC
        )
 SELECT c.id AS company_id,
    t.module_key,
    p.platform_template_version_id,
    p.platform_version,
    p.platform_title,
    p.platform_sha256,
    o.tenant_override_id,
    o.tenant_override_version,
    o.tenant_override_mode,
    o.tenant_override_title,
    o.tenant_override_sha256,
        CASE
            WHEN ((o.tenant_override_id IS NOT NULL) AND (o.tenant_override_mode = 'replacement'::text)) THEN 'tenant_replacement'::text
            WHEN ((p.platform_template_version_id IS NOT NULL) AND (o.tenant_override_id IS NOT NULL) AND (o.tenant_override_mode = 'addendum'::text)) THEN 'platform_template_with_tenant_addendum'::text
            WHEN (p.platform_template_version_id IS NOT NULL) THEN 'platform_template'::text
            ELSE 'missing'::text
        END AS effective_source,
        CASE
            WHEN ((o.tenant_override_id IS NOT NULL) AND (o.tenant_override_mode = 'replacement'::text)) THEN true
            WHEN (p.platform_template_version_id IS NOT NULL) THEN true
            ELSE false
        END AS effective_available
   FROM (((public.companies c
     CROSS JOIN public.legal_templates t)
     LEFT JOIN latest_platform p ON ((p.module_key = t.module_key)))
     LEFT JOIN latest_override o ON (((o.company_id = c.id) AND (o.module_key = t.module_key))))
  WHERE (t.status = 'active'::text);

--
-- Name: gridex_tenant_email_dispatch_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_tenant_email_dispatch_readiness_v WITH (security_invoker='true') AS
 WITH canonical_rules(event_key, template_key, event_label, legal_or_critical, available_variables) AS (
         VALUES ('contract.application_received'::text,'contract.application_received'::text,'Ansökan mottagen'::text,false,ARRAY['customer_name'::text, 'first_name'::text, 'last_name'::text, 'customer_email'::text, 'customer_phone'::text, 'customer_number'::text, 'company_name'::text, 'support_email'::text, 'portal_url'::text]), ('contract.confirmation_sent'::text,'contract.confirmation_sent'::text,'Avtalsbekräftelse'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'last_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'signed_at'::text, 'start_date'::text, 'price_summary'::text, 'legal_versions_summary'::text, 'offer_reference'::text, 'agreement_pdf_note'::text, 'support_email'::text, 'portal_url'::text]), ('contract.cooling_off_sent'::text,'contract.cooling_off_sent'::text,'Ångerrätt'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'cancellation_deadline'::text, 'support_email'::text, 'portal_url'::text]), ('contract.power_of_attorney_required'::text,'contract.power_of_attorney_required'::text,'Begäran om fullmakt'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'power_of_attorney_url'::text, 'support_email'::text, 'portal_url'::text]), ('contract.facility_id_required'::text,'contract.facility_id_required'::text,'Begäran om anläggnings-ID'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'facility_id'::text, 'metering_point_id'::text, 'support_email'::text, 'portal_url'::text]), ('contract.customer_information_required'::text,'contract.customer_information_required'::text,'Begäran om kunduppgifter'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'required_information'::text, 'support_email'::text, 'portal_url'::text]), ('contract.completion_reminder'::text,'contract.completion_reminder'::text,'Påminnelse om komplettering'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'required_information'::text, 'completion_deadline'::text, 'support_email'::text, 'portal_url'::text]), ('contract.rejected'::text,'contract.rejected'::text,'Avtal avslaget'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'review_reason'::text, 'support_email'::text, 'portal_url'::text]), ('contract.manual_review'::text,'contract.manual_review'::text,'Manuell granskning'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'review_reason'::text, 'support_email'::text, 'portal_url'::text]), ('switch.started'::text,'switch.started'::text,'Leverantörsbyte startat'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'facility_id'::text, 'metering_point_id'::text, 'start_date'::text, 'support_email'::text, 'portal_url'::text, 'cancellation_deadline'::text]), ('switch.confirmed'::text,'switch.confirmed'::text,'Leverantörsbyte bekräftat'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'facility_id'::text, 'metering_point_id'::text, 'start_date'::text, 'support_email'::text, 'portal_url'::text, 'cancellation_deadline'::text]), ('switch.action_required'::text,'switch.action_required'::text,'Komplettering behövs'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'facility_id'::text, 'metering_point_id'::text, 'start_date'::text, 'support_email'::text, 'portal_url'::text, 'cancellation_deadline'::text, 'case_message'::text, 'case_subject'::text]), ('customer.welcome_active'::text,'customer.welcome_active'::text,'Välkommen som kund'::text,true,ARRAY['customer_name'::text, 'first_name'::text, 'customer_number'::text, 'company_name'::text, 'contract_name'::text, 'contract_number'::text, 'facility_id'::text, 'metering_point_id'::text, 'start_date'::text, 'support_email'::text, 'portal_url'::text, 'cancellation_deadline'::text])
        ), raw AS (
         SELECT c.id AS company_id,
            c.name AS company_name,
            cr.event_key,
            cr.template_key,
            cr.event_label,
            cr.legal_or_critical,
            cr.available_variables,
            COALESCE(e.enabled, true) AS enabled,
            COALESCE(e.is_active, e.enabled, true) AS rule_active,
            t.id AS template_id,
            COALESCE(t.name, cr.event_label) AS template_name,
            t.subject,
            t.body_html,
            t.body_text,
            COALESCE(t.is_active, false) AS template_active,
            s.id AS settings_id,
            s.sender_name,
            s.sender_email,
            s.reply_to_email,
            s.domain,
            COALESCE(s.verification_status, 'not_started'::text) AS domain_status,
            COALESCE(s.is_active, true) AS sender_is_active,
            COALESCE(s.fallback_allowed, (s.id IS NULL)) AS fallback_allowed,
            COALESCE(s.sender_mode, 'fallback_platform_sender'::text) AS sender_mode,
            COALESCE(s.block_legal_mail_when_unverified, true) AS block_legal_mail_when_unverified,
            COALESCE(e.updated_at, t.updated_at) AS event_rule_updated_at,
            t.updated_at AS template_updated_at
           FROM ((((public.companies c
             CROSS JOIN canonical_rules cr)
             LEFT JOIN public.email_event_rules e ON (((e.company_id = c.id) AND (e.event_key = cr.event_key) AND (e.template_key = cr.template_key))))
             LEFT JOIN public.company_email_templates t ON (((t.company_id = c.id) AND (t.template_key = cr.template_key) AND (t.language = 'sv'::text))))
             LEFT JOIN public.company_email_settings s ON ((s.company_id = c.id)))
        ), placeholders AS (
         SELECT raw.company_id,
            raw.company_name,
            raw.event_key,
            raw.template_key,
            raw.event_label,
            raw.legal_or_critical,
            raw.available_variables,
            raw.enabled,
            raw.rule_active,
            raw.template_id,
            raw.template_name,
            raw.subject,
            raw.body_html,
            raw.body_text,
            raw.template_active,
            raw.settings_id,
            raw.sender_name,
            raw.sender_email,
            raw.reply_to_email,
            raw.domain,
            raw.domain_status,
            raw.sender_is_active,
            raw.fallback_allowed,
            raw.sender_mode,
            raw.block_legal_mail_when_unverified,
            raw.event_rule_updated_at,
            raw.template_updated_at,
            COALESCE(( SELECT array_agg(DISTINCT btrim(m.m[1])) AS array_agg
                   FROM regexp_matches(((((COALESCE(raw.subject, ''::text) || '
'::text) || COALESCE(raw.body_html, ''::text)) || '
'::text) || COALESCE(raw.body_text, ''::text)), '\{\{([^{}]*)\}\}'::text, 'g'::text) m(m)), '{}'::text[]) AS referenced_variables
           FROM raw
        ), contracted AS (
         SELECT placeholders.company_id,
            placeholders.company_name,
            placeholders.event_key,
            placeholders.template_key,
            placeholders.event_label,
            placeholders.legal_or_critical,
            placeholders.available_variables,
            placeholders.enabled,
            placeholders.rule_active,
            placeholders.template_id,
            placeholders.template_name,
            placeholders.subject,
            placeholders.body_html,
            placeholders.body_text,
            placeholders.template_active,
            placeholders.settings_id,
            placeholders.sender_name,
            placeholders.sender_email,
            placeholders.reply_to_email,
            placeholders.domain,
            placeholders.domain_status,
            placeholders.sender_is_active,
            placeholders.fallback_allowed,
            placeholders.sender_mode,
            placeholders.block_legal_mail_when_unverified,
            placeholders.event_rule_updated_at,
            placeholders.template_updated_at,
            placeholders.referenced_variables,
            COALESCE(( SELECT array_agg(v.v ORDER BY v.v) AS array_agg
                   FROM unnest(placeholders.referenced_variables) v(v)
                  WHERE ((NULLIF(btrim(v.v), ''::text) IS NULL) OR (NOT (v.v = ANY (placeholders.available_variables))))), '{}'::text[]) AS contract_invalid_variables
           FROM placeholders
        ), evaluated AS (
         SELECT contracted.company_id,
            contracted.company_name,
            contracted.event_key,
            contracted.template_key,
            contracted.event_label,
            contracted.legal_or_critical,
            contracted.available_variables,
            contracted.enabled,
            contracted.rule_active,
            contracted.template_id,
            contracted.template_name,
            contracted.subject,
            contracted.body_html,
            contracted.body_text,
            contracted.template_active,
            contracted.settings_id,
            contracted.sender_name,
            contracted.sender_email,
            contracted.reply_to_email,
            contracted.domain,
            contracted.domain_status,
            contracted.sender_is_active,
            contracted.fallback_allowed,
            contracted.sender_mode,
            contracted.block_legal_mail_when_unverified,
            contracted.event_rule_updated_at,
            contracted.template_updated_at,
            contracted.referenced_variables,
            contracted.contract_invalid_variables,
            (cardinality(contracted.contract_invalid_variables) = 0) AS template_contract_valid,
            ((contracted.sender_is_active = true) AND (lower(COALESCE(contracted.domain_status, ''::text)) = ANY (ARRAY['verified'::text, 'active'::text, 'ready'::text])) AND (NULLIF(COALESCE(contracted.sender_email, ''::text), ''::text) IS NOT NULL) AND (NULLIF(COALESCE(contracted.sender_name, ''::text), ''::text) IS NOT NULL)) AS has_verified_sender,
            ((contracted.sender_is_active = true) AND (contracted.fallback_allowed = true) AND (contracted.sender_mode <> 'disabled'::text)) AS fallback_permitted
           FROM contracted
        )
 SELECT company_id,
    company_name,
    event_key,
    template_key,
    enabled,
    template_id,
    template_name,
    subject,
    template_active,
    sender_email,
    reply_to_email,
    domain,
    domain_status,
        CASE
            WHEN ((enabled IS NOT TRUE) OR (rule_active IS NOT TRUE)) THEN false
            WHEN ((template_id IS NULL) OR (template_active IS NOT TRUE)) THEN false
            WHEN ((NULLIF(COALESCE(subject, ''::text), ''::text) IS NULL) OR (NULLIF(COALESCE(body_html, body_text, ''::text), ''::text) IS NULL)) THEN false
            WHEN (template_contract_valid IS NOT TRUE) THEN false
            WHEN (sender_is_active IS NOT TRUE) THEN false
            WHEN (legal_or_critical = true) THEN has_verified_sender
            WHEN ((has_verified_sender = true) OR (fallback_permitted = true)) THEN true
            ELSE false
        END AS can_send,
    array_remove(ARRAY[
        CASE
            WHEN ((enabled IS NOT TRUE) OR (rule_active IS NOT TRUE)) THEN 'Utskicket är avstängt'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (template_id IS NULL) THEN 'Mailmall saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (template_active IS NOT TRUE) THEN 'Mailmallen är inaktiv'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(COALESCE(subject, ''::text), ''::text) IS NULL) THEN 'Ämnesrad saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(COALESCE(body_html, body_text, ''::text), ''::text) IS NULL) THEN 'Mallinnehåll saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (template_contract_valid IS NOT TRUE) THEN ('Mailmallens variabelkontrakt är ogiltigt: '::text || array_to_string(contract_invalid_variables, ', '::text))
            ELSE NULL::text
        END,
        CASE
            WHEN (sender_is_active IS NOT TRUE) THEN 'Avsändaren är avstängd'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((legal_or_critical = true) AND (has_verified_sender IS NOT TRUE)) THEN 'Juridiska eller kritiska mail kräver verifierad bolagsdomän och avsändare'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((legal_or_critical = false) AND (has_verified_sender IS NOT TRUE) AND (fallback_permitted = true)) THEN 'Skickas via plattformens fallback-avsändare'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((legal_or_critical = false) AND (has_verified_sender IS NOT TRUE) AND (fallback_permitted IS NOT TRUE)) THEN 'Verifierad avsändare saknas och fallback är avstängd'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((has_verified_sender IS NOT TRUE) AND (NULLIF(COALESCE(sender_email, ''::text), ''::text) IS NULL)) THEN 'Bolagets verifierade avsändarmail saknas'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((has_verified_sender IS NOT TRUE) AND (NULLIF(COALESCE(sender_name, ''::text), ''::text) IS NULL)) THEN 'Avsändarnamn saknas'::text
            ELSE NULL::text
        END], NULL::text) AS issues,
    event_rule_updated_at,
    template_updated_at,
    sender_mode,
    fallback_allowed,
    legal_or_critical,
    ((legal_or_critical = false) AND (has_verified_sender IS NOT TRUE) AND (fallback_permitted = true)) AS requires_platform_fallback
   FROM evaluated;

--
-- Name: platform_usage_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_usage_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    actor_user_id uuid,
    api_client_id uuid,
    customer_id uuid,
    entity_type text NOT NULL,
    entity_id text,
    event_key text NOT NULL,
    action_label text,
    source text DEFAULT 'admin_ui'::text NOT NULL,
    billable_quantity numeric DEFAULT 1 NOT NULL,
    billing_unit text DEFAULT 'action'::text NOT NULL,
    is_billable boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: TABLE platform_usage_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_usage_events IS 'Tenant-scoped usage/action events used for SaaS statistics and future platform billing. Audit_logs remains the legal/revision log. Service-only table: accessed via backend service role. RLS enabled with no policies by design (deny-by-default for anon/authenticated); direct API-role grants revoked by advisor hardening 20260709163000.';

--
-- Name: COLUMN platform_usage_events.entity_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_usage_events.entity_id IS 'Polymorphic internal UUID or stable external resource reference. The entity_type column defines its namespace.';

--
-- Name: gridex_tenant_usage_monthly_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_tenant_usage_monthly_v WITH (security_invoker='true') AS
 SELECT company_id,
    (date_trunc('month'::text, occurred_at))::date AS usage_month,
    event_key,
    billing_unit,
    is_billable,
    count(*) AS event_count,
    COALESCE(sum(billable_quantity), (0)::numeric) AS billable_quantity,
    min(occurred_at) AS first_event_at,
    max(occurred_at) AS last_event_at
   FROM public.platform_usage_events
  GROUP BY company_id, ((date_trunc('month'::text, occurred_at))::date), event_key, billing_unit, is_billable;

--
-- Name: VIEW gridex_tenant_usage_monthly_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_tenant_usage_monthly_v IS 'Monthly tenant usage summary used for SaaS billing statistics. Source: platform_usage_events; audit_logs remains the legal trace.';

--
-- Name: gridex_verified_grid_owners_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_verified_grid_owners_v WITH (security_invoker='true') AS
 WITH actor_ids AS (
         SELECT i.actor_id,
            max(i.identifier_value) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text]))) AS ediel_id,
            bool_or(COALESCE(i.is_verified, false)) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text]))) AS ediel_id_verified,
            max(i.identifier_value) FILTER (WHERE (lower(i.identifier_type) = ANY (ARRAY['orgno'::text, 'org_number'::text, 'orgnr'::text]))) AS registry_org_number
           FROM public.platform_actor_identifiers i
          GROUP BY i.actor_id
        ), actor_roles AS (
         SELECT r.actor_id,
            array_agg(DISTINCT lower(r.actor_role) ORDER BY (lower(r.actor_role))) AS roles,
            bool_or((lower(r.actor_role) = ANY (ARRAY['grid_owner'::text, 'network_owner'::text, 'netowner'::text, 'dso'::text, 'distribution_system_operator'::text, 'nätägare'::text, 'elnatsforetag'::text, 'elnätsföretag'::text]))) AS is_grid_owner
           FROM public.platform_actor_roles r
          WHERE (COALESCE(r.is_active, true) = true)
          GROUP BY r.actor_id
        ), route_summary AS (
         SELECT r.actor_id,
            (count(*))::integer AS route_count,
            (count(*) FILTER (WHERE (upper(r.message_family) = 'PRODAT'::text)))::integer AS prodat_route_count,
            (count(*) FILTER (WHERE (upper(r.message_family) = 'UTILTS'::text)))::integer AS utilts_route_count,
            bool_or(((COALESCE(r.status, ''::text) = 'active'::text) AND COALESCE(r.is_verified, false))) AS has_verified_route,
            bool_or(((upper(r.message_family) = 'PRODAT'::text) AND (COALESCE(r.status, ''::text) = 'active'::text) AND COALESCE(r.is_verified, false))) AS has_verified_prodat_route,
            bool_or(((upper(r.message_family) = 'UTILTS'::text) AND (COALESCE(r.status, ''::text) = 'active'::text) AND COALESCE(r.is_verified, false))) AS has_verified_utilts_route,
            bool_or(((COALESCE(r.status, ''::text) = 'active'::text) AND ((NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((r.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)))) AS has_subaddress,
            (count(DISTINCT NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'PRODAT'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))))::integer AS prodat_subaddress_value_count,
            (count(DISTINCT NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'UTILTS'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))))::integer AS utilts_subaddress_value_count,
            min(NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'PRODAT'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))) AS suggested_prodat_subaddress,
            min(NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'UTILTS'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))) AS suggested_utilts_subaddress,
            array_agg(DISTINCT NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'PRODAT'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))) AS possible_prodat_subaddresses,
            array_agg(DISTINCT NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text)) FILTER (WHERE ((upper(r.message_family) = 'UTILTS'::text) AND (r.environment = 'production'::text) AND (NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL))) AS possible_utilts_subaddresses,
            bool_or((NULLIF(btrim(COALESCE(r.communication_address, ''::text)), ''::text) IS NOT NULL)) AS has_route_contact,
            bool_or((r.environment = 'production'::text)) AS has_production_route,
            bool_or((r.environment = 'test'::text)) AS has_test_route,
            bool_or(((upper(r.message_family) = 'PRODAT'::text) AND (r.environment = 'production'::text))) AS requires_certificate
           FROM public.platform_actor_routes r
          GROUP BY r.actor_id
        ), latest_cert AS (
         SELECT DISTINCT ON (c.actor_id, c.environment, c.purpose) c.actor_id,
            c.environment,
            c.purpose,
            c.status,
            c.fingerprint_sha256,
            c.ediel_id,
            c.valid_from,
            c.valid_to,
            c.updated_at,
            c.source
           FROM public.platform_actor_certificates c
          WHERE (c.purpose = ANY (ARRAY['encryption'::text, 'signing'::text]))
          ORDER BY c.actor_id, c.environment, c.purpose,
                CASE c.status
                    WHEN 'valid'::text THEN 0
                    WHEN 'expires_soon'::text THEN 1
                    WHEN 'unknown'::text THEN 2
                    WHEN 'missing'::text THEN 3
                    ELSE 4
                END, c.updated_at DESC NULLS LAST
        ), grid_owner_match_keys AS (
         SELECT gk.id AS grid_owner_id,
            gk.platform_market_actor_id,
            gk.ediel_id,
            NULLIF(btrim(gk.ediel_id), ''::text) AS ediel_id_nonblank,
            regexp_replace(gk.org_number, '[^0-9]'::text, ''::text, 'g'::text) AS org_number_norm,
            (NULLIF(btrim(gk.org_number), ''::text) IS NOT NULL) AS has_org_number,
            lower(regexp_replace(COALESCE(gk.name, ''::text), '[[:space:]]+'::text, ' '::text, 'g'::text)) AS name_norm
           FROM public.grid_owners gk
        ), actor_match_keys AS (
         SELECT ak.id AS actor_id,
            regexp_replace(COALESCE(ak.org_number, ''::text), '[^0-9]'::text, ''::text, 'g'::text) AS org_number_norm,
            lower(regexp_replace(COALESCE(ak.name, ''::text), '[[:space:]]+'::text, ' '::text, 'g'::text)) AS name_norm
           FROM public.platform_market_actors ak
        ), ediel_actor_keys AS (
         SELECT DISTINCT ei.actor_id,
            ei.identifier_value AS ediel_id
           FROM public.platform_actor_identifiers ei
          WHERE (lower(ei.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text]))
        ), actor_match_candidates AS (
         SELECT k.grid_owner_id,
            k.platform_market_actor_id AS actor_id
           FROM grid_owner_match_keys k
          WHERE (k.platform_market_actor_id IS NOT NULL)
        UNION
         SELECT k.grid_owner_id,
            e_1.actor_id
           FROM (grid_owner_match_keys k
             JOIN ediel_actor_keys e_1 ON ((e_1.ediel_id = k.ediel_id)))
          WHERE ((k.platform_market_actor_id IS NULL) AND (k.ediel_id_nonblank IS NOT NULL))
        UNION
         SELECT k.grid_owner_id,
            a.actor_id
           FROM (grid_owner_match_keys k
             JOIN actor_match_keys a ON ((a.org_number_norm = k.org_number_norm)))
          WHERE ((k.platform_market_actor_id IS NULL) AND k.has_org_number)
        UNION
         SELECT k.grid_owner_id,
            a.actor_id
           FROM (grid_owner_match_keys k
             JOIN actor_match_keys a ON ((a.name_norm = k.name_norm)))
          WHERE (k.platform_market_actor_id IS NULL)
        ), mapped AS (
         SELECT g.id AS grid_owner_id,
            g.company_id,
            g.name,
            g.owner_code,
            COALESCE(NULLIF(btrim(g.ediel_id), ''::text), ai.ediel_id, ready.ediel_id) AS ediel_id,
            COALESCE(NULLIF(btrim(g.org_number), ''::text), ai.registry_org_number, a.org_number, ready.org_number) AS org_number,
            g.environment,
            g.lifecycle_status,
            g.default_prodat_subaddress,
            g.default_utilts_subaddress,
            g.communication_email,
            g.email,
            g.contact_name,
            g.phone,
            g.is_active,
            COALESCE(g.platform_market_actor_id, a.id) AS platform_market_actor_id,
            g.platform_grid_owner_id,
            COALESCE(a.name, ready.actor_name) AS actor_name,
            a.status AS actor_status,
            a.match_status,
            COALESCE(ready.roles, ar.roles, '{}'::text[]) AS actor_roles,
            COALESCE(ready.has_grid_owner_role, ar.is_grid_owner, false) AS actor_is_grid_owner,
            COALESCE(ai.ediel_id_verified, false) AS ediel_id_verified,
            COALESCE(rs.route_count, 0) AS route_count,
            COALESCE(rs.prodat_route_count, 0) AS prodat_route_count,
            COALESCE(rs.utilts_route_count, 0) AS utilts_route_count,
            COALESCE(rs.has_verified_route, false) AS has_verified_route,
            (COALESCE(rs.has_subaddress, false) OR (NULLIF(btrim(COALESCE(g.default_prodat_subaddress, g.default_utilts_subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE(g.prodat_subaddress_status, ''::text) = 'not_required_confirmed'::text) OR (COALESCE(g.utilts_subaddress_status, ''::text) = 'not_required_confirmed'::text)) AS has_subaddress,
            (COALESCE(ready.has_contact_path, rs.has_route_contact, false) OR (NULLIF(btrim(COALESCE(g.communication_email, g.email, ''::text)), ''::text) IS NOT NULL)) AS has_contact_path,
            COALESCE(rs.has_production_route, false) AS has_production_route,
            COALESCE(rs.has_test_route, false) AS has_test_route,
            COALESCE(rs.requires_certificate, false) AS requires_certificate,
            lc.status AS raw_certificate_status,
            lc.environment AS certificate_environment,
            lc.fingerprint_sha256 AS certificate_fingerprint_sha256,
            lc.ediel_id AS certificate_ediel_id,
            lc.valid_to AS certificate_valid_to,
            d.duplicate_key,
            COALESCE(d.duplicate_count, 1) AS duplicate_count,
            COALESCE(rs.has_verified_prodat_route, false) AS has_verified_prodat_route,
            COALESCE(rs.has_verified_utilts_route, false) AS has_verified_utilts_route,
            COALESCE(rs.prodat_subaddress_value_count, 0) AS prodat_subaddress_value_count,
            COALESCE(rs.utilts_subaddress_value_count, 0) AS utilts_subaddress_value_count,
            rs.suggested_prodat_subaddress,
            rs.suggested_utilts_subaddress,
            COALESCE(rs.possible_prodat_subaddresses, '{}'::text[]) AS possible_prodat_subaddresses,
            COALESCE(rs.possible_utilts_subaddresses, '{}'::text[]) AS possible_utilts_subaddresses,
            COALESCE(g.prodat_subaddress_status, 'missing'::text) AS stored_prodat_subaddress_status,
            COALESCE(g.utilts_subaddress_status, 'missing'::text) AS stored_utilts_subaddress_status,
            COALESCE(g.prodat_subaddress_source, 'missing'::text) AS stored_prodat_subaddress_source,
            COALESCE(g.utilts_subaddress_source, 'missing'::text) AS stored_utilts_subaddress_source,
            lc.source AS certificate_source,
            COALESCE(ready.electricity_scope_status, 'separate_role_scope'::text) AS electricity_scope_status,
            COALESCE(ready.primary_role_group, 'other'::text) AS primary_role_group,
            COALESCE(ready.supplier_switch_readiness_status, 'separate_role_scope'::text) AS supplier_switch_readiness_status,
            COALESCE(ready.is_electricity_grid_owner_scope, false) AS is_electricity_grid_owner_scope,
            COALESCE(ready.manual_review_required, false) AS manual_review_required,
            ready.manual_review_reason,
            COALESCE(ready.blocking_reasons, '{}'::text[]) AS role_blocking_reasons,
            COALESCE(ready.can_use_for_prodat, false) AS role_can_use_for_prodat,
            COALESCE(ready.can_use_for_utilts, false) AS role_can_use_for_utilts,
            COALESCE(ready.can_start_supplier_switch, false) AS role_can_start_supplier_switch,
            COALESCE(ready.has_valid_prodat_certificate, false) AS role_has_valid_prodat_certificate
           FROM ((((((((public.grid_owners g
             LEFT JOIN actor_match_candidates am ON ((am.grid_owner_id = g.id)))
             LEFT JOIN public.platform_market_actors a ON ((a.id = am.actor_id)))
             LEFT JOIN actor_ids ai ON ((ai.actor_id = COALESCE(g.platform_market_actor_id, a.id))))
             LEFT JOIN actor_roles ar ON ((ar.actor_id = COALESCE(g.platform_market_actor_id, a.id))))
             LEFT JOIN route_summary rs ON ((rs.actor_id = COALESCE(g.platform_market_actor_id, a.id))))
             LEFT JOIN latest_cert lc ON (((lc.actor_id = COALESCE(g.platform_market_actor_id, a.id)) AND (lc.environment = COALESCE(g.environment, 'production'::text)) AND (lc.purpose = 'encryption'::text))))
             LEFT JOIN public.gridex_grid_owner_duplicate_v d ON ((d.grid_owner_id = g.id)))
             LEFT JOIN public.actor_readiness_status ready ON ((ready.platform_market_actor_id = COALESCE(g.platform_market_actor_id, a.id))))
        ), evaluated AS (
         SELECT m.grid_owner_id,
            m.company_id,
            m.name,
            m.owner_code,
            m.ediel_id,
            m.org_number,
            m.environment,
            m.lifecycle_status,
            m.default_prodat_subaddress,
            m.default_utilts_subaddress,
            m.communication_email,
            m.email,
            m.contact_name,
            m.phone,
            m.is_active,
            m.platform_market_actor_id,
            m.platform_grid_owner_id,
            m.actor_name,
            m.actor_status,
            m.match_status,
            m.actor_roles,
            m.actor_is_grid_owner,
            m.ediel_id_verified,
            m.route_count,
            m.prodat_route_count,
            m.utilts_route_count,
            m.has_verified_route,
            m.has_subaddress,
            m.has_contact_path,
            m.has_production_route,
            m.has_test_route,
            m.requires_certificate,
            m.raw_certificate_status,
            m.certificate_environment,
            m.certificate_fingerprint_sha256,
            m.certificate_ediel_id,
            m.certificate_valid_to,
            m.duplicate_key,
            m.duplicate_count,
            m.has_verified_prodat_route,
            m.has_verified_utilts_route,
            m.prodat_subaddress_value_count,
            m.utilts_subaddress_value_count,
            m.suggested_prodat_subaddress,
            m.suggested_utilts_subaddress,
            m.possible_prodat_subaddresses,
            m.possible_utilts_subaddresses,
            m.stored_prodat_subaddress_status,
            m.stored_utilts_subaddress_status,
            m.stored_prodat_subaddress_source,
            m.stored_utilts_subaddress_source,
            m.certificate_source,
            m.electricity_scope_status,
            m.primary_role_group,
            m.supplier_switch_readiness_status,
            m.is_electricity_grid_owner_scope,
            m.manual_review_required,
            m.manual_review_reason,
            m.role_blocking_reasons,
            m.role_can_use_for_prodat,
            m.role_can_use_for_utilts,
            m.role_can_start_supplier_switch,
            m.role_has_valid_prodat_certificate,
                CASE
                    WHEN (m.prodat_route_count = 0) THEN 'missing'::text
                    WHEN (COALESCE(m.default_prodat_subaddress, ''::text) <> ''::text) THEN 'verified'::text
                    WHEN (m.stored_prodat_subaddress_status = 'not_required_confirmed'::text) THEN 'not_required_confirmed'::text
                    WHEN (m.prodat_subaddress_value_count = 1) THEN 'route_available'::text
                    WHEN (m.prodat_subaddress_value_count > 1) THEN 'ambiguous'::text
                    ELSE 'missing'::text
                END AS prodat_subaddress_status_evaluated,
                CASE
                    WHEN (m.utilts_route_count = 0) THEN 'missing'::text
                    WHEN (COALESCE(m.default_utilts_subaddress, ''::text) <> ''::text) THEN 'verified'::text
                    WHEN (m.stored_utilts_subaddress_status = 'not_required_confirmed'::text) THEN 'not_required_confirmed'::text
                    WHEN (m.utilts_subaddress_value_count = 1) THEN 'route_available'::text
                    WHEN (m.utilts_subaddress_value_count > 1) THEN 'ambiguous'::text
                    ELSE 'missing'::text
                END AS utilts_subaddress_status_evaluated,
                CASE
                    WHEN m.role_has_valid_prodat_certificate THEN true
                    WHEN ((m.raw_certificate_status = ANY (ARRAY['valid'::text, 'expires_soon'::text])) AND ((m.certificate_ediel_id IS NULL) OR (m.certificate_ediel_id = m.ediel_id))) THEN true
                    ELSE false
                END AS certificate_is_usable
           FROM mapped m
        )
 SELECT grid_owner_id,
    company_id,
    name,
    owner_code,
    ediel_id,
    org_number,
    environment,
    lifecycle_status,
    default_prodat_subaddress,
    default_utilts_subaddress,
    communication_email,
    email,
    contact_name,
    phone,
    is_active,
    platform_market_actor_id,
    platform_grid_owner_id,
    actor_name,
    actor_status,
    match_status,
    actor_roles,
    actor_is_grid_owner,
    ediel_id_verified,
    route_count,
    prodat_route_count,
    utilts_route_count,
    has_verified_route,
    (((prodat_route_count = 0) OR (prodat_subaddress_status_evaluated = ANY (ARRAY['verified'::text, 'not_required_confirmed'::text, 'route_available'::text]))) AND ((utilts_route_count = 0) OR (utilts_subaddress_status_evaluated = ANY (ARRAY['verified'::text, 'not_required_confirmed'::text, 'route_available'::text])))) AS has_subaddress,
    has_contact_path,
    has_production_route,
    has_test_route,
    requires_certificate,
    raw_certificate_status,
    certificate_environment,
    certificate_fingerprint_sha256,
    certificate_ediel_id,
    certificate_valid_to,
    duplicate_key,
    duplicate_count,
        CASE
            WHEN (electricity_scope_status = 'excluded_from_electricity_scope'::text) THEN 'excluded_from_electricity_scope'::text
            WHEN (COALESCE(duplicate_count, 1) > 1) THEN 'unresolved_duplicate'::text
            WHEN ('missing_ediel_id'::text = ANY (role_blocking_reasons)) THEN 'needs_ediel_id'::text
            WHEN ('missing_prodat_route'::text = ANY (role_blocking_reasons)) THEN 'needs_route'::text
            WHEN ('unsafe_or_missing_subaddress'::text = ANY (role_blocking_reasons)) THEN 'needs_subaddress'::text
            WHEN ('missing_contact_path'::text = ANY (role_blocking_reasons)) THEN 'needs_contact'::text
            WHEN ('missing_or_invalid_certificate'::text = ANY (role_blocking_reasons)) THEN 'needs_certificate'::text
            WHEN ('open_blocking_conflicts'::text = ANY (role_blocking_reasons)) THEN 'unresolved_duplicate'::text
            WHEN role_can_start_supplier_switch THEN 'verified'::text
            WHEN (NULLIF(btrim(COALESCE(ediel_id, ''::text)), ''::text) IS NULL) THEN 'needs_ediel_id'::text
            WHEN ((COALESCE(route_count, 0) = 0) OR (NOT has_verified_route)) THEN 'needs_route'::text
            WHEN ((prodat_subaddress_status_evaluated = 'ambiguous'::text) OR (utilts_subaddress_status_evaluated = 'ambiguous'::text)) THEN 'ambiguous_subaddress'::text
            WHEN (((prodat_route_count > 0) AND (prodat_subaddress_status_evaluated = 'missing'::text)) OR ((utilts_route_count > 0) AND (utilts_subaddress_status_evaluated = 'missing'::text))) THEN 'needs_subaddress'::text
            WHEN (NOT has_contact_path) THEN 'needs_contact'::text
            WHEN (requires_certificate AND (NOT certificate_is_usable)) THEN 'needs_certificate'::text
            ELSE 'verified'::text
        END AS verification_status,
        CASE
            WHEN certificate_is_usable THEN 'finns'::text
            WHEN (raw_certificate_status = 'expired'::text) THEN 'utgånget'::text
            WHEN (raw_certificate_status = 'mismatch'::text) THEN 'fel_mottagare'::text
            WHEN ((raw_certificate_status IS NOT NULL) AND (certificate_environment IS NOT NULL) AND (certificate_environment <> COALESCE(environment, 'production'::text))) THEN 'fel_miljö'::text
            ELSE 'saknas'::text
        END AS certificate_status,
        CASE
            WHEN (electricity_scope_status = 'excluded_from_electricity_scope'::text) THEN ARRAY['excluded_from_electricity_scope'::text]
            WHEN (array_length(role_blocking_reasons, 1) IS NOT NULL) THEN role_blocking_reasons
            ELSE array_remove(ARRAY[
            CASE
                WHEN (COALESCE(duplicate_count, 1) > 1) THEN 'unresolved_duplicate'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NULLIF(btrim(COALESCE(ediel_id, ''::text)), ''::text) IS NULL) THEN 'needs_ediel_id'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((COALESCE(route_count, 0) = 0) OR (NOT has_verified_route)) THEN 'needs_route'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((prodat_subaddress_status_evaluated = 'ambiguous'::text) OR (utilts_subaddress_status_evaluated = 'ambiguous'::text)) THEN 'ambiguous_subaddress'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (((prodat_route_count > 0) AND (prodat_subaddress_status_evaluated = 'missing'::text)) OR ((utilts_route_count > 0) AND (utilts_subaddress_status_evaluated = 'missing'::text))) THEN 'needs_subaddress'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NOT has_contact_path) THEN 'needs_contact'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (requires_certificate AND (NOT certificate_is_usable)) THEN 'needs_certificate'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (requires_certificate AND (certificate_ediel_id IS NOT NULL) AND (NULLIF(btrim(COALESCE(ediel_id, ''::text)), ''::text) IS NOT NULL) AND (certificate_ediel_id <> ediel_id)) THEN 'certificate_ediel_mismatch'::text
                ELSE NULL::text
            END], NULL::text)
        END AS verification_reasons,
        CASE
            WHEN (electricity_scope_status = 'excluded_from_electricity_scope'::text) THEN 'excluded_from_electricity_scope'::text
            WHEN ((COALESCE(route_count, 0) > 0) AND has_verified_route) THEN 'verified'::text
            ELSE 'needs_route'::text
        END AS route_status,
    role_can_start_supplier_switch AS verified_for_customer_flow,
        CASE
            WHEN (electricity_scope_status = 'excluded_from_electricity_scope'::text) THEN 'excluded_from_electricity_scope'::text
            WHEN role_can_start_supplier_switch THEN 'verified'::text
            WHEN (COALESCE(duplicate_count, 1) > 1) THEN 'duplicate_review'::text
            WHEN (NULLIF(btrim(COALESCE(ediel_id, ''::text)), ''::text) IS NULL) THEN 'missing_ediel_id'::text
            WHEN ((actor_status = 'active'::text) AND ((match_status = 'verified'::text) OR ediel_id_verified)) THEN 'under_review'::text
            ELSE 'under_review'::text
        END AS actor_registry_status,
        CASE
            WHEN (electricity_scope_status = 'excluded_from_electricity_scope'::text) THEN 'Exkluderad från elhandelns leverantörsbyte. Visas separat och blockerar inte elflödet.'::text
            WHEN (COALESCE(duplicate_count, 1) > 1) THEN 'Granska dubbletter innan nätägaren används i kundflöde.'::text
            WHEN (('missing_ediel_id'::text = ANY (role_blocking_reasons)) OR (NULLIF(btrim(COALESCE(ediel_id, ''::text)), ''::text) IS NULL)) THEN 'Komplettera Ediel-ID.'::text
            WHEN ('missing_prodat_route'::text = ANY (role_blocking_reasons)) THEN 'Manuell review: PRODAT-route saknas i källa. Skapa inte gissad route.'::text
            WHEN ('unsafe_or_missing_subaddress'::text = ANY (role_blocking_reasons)) THEN 'Komplettera eller verifiera subadress enligt säker regel.'::text
            WHEN ('missing_contact_path'::text = ANY (role_blocking_reasons)) THEN 'Komplettera SMTP/kontaktväg.'::text
            WHEN ('missing_or_invalid_certificate'::text = ANY (role_blocking_reasons)) THEN 'Kör certifikatsökning eller verifiera mottagarcertifikat.'::text
            ELSE 'Verifierad för kundflöde och Ediel-readiness.'::text
        END AS next_action,
    has_verified_prodat_route,
    has_verified_utilts_route,
    prodat_subaddress_value_count,
    utilts_subaddress_value_count,
    suggested_prodat_subaddress,
    suggested_utilts_subaddress,
    possible_prodat_subaddresses,
    possible_utilts_subaddresses,
        CASE
            WHEN (prodat_route_count = 0) THEN 'missing'::text
            WHEN (prodat_subaddress_status_evaluated = 'route_available'::text) THEN 'verified'::text
            ELSE prodat_subaddress_status_evaluated
        END AS prodat_subaddress_status,
        CASE
            WHEN (utilts_route_count = 0) THEN 'missing'::text
            WHEN (utilts_subaddress_status_evaluated = 'route_available'::text) THEN 'verified'::text
            ELSE utilts_subaddress_status_evaluated
        END AS utilts_subaddress_status,
        CASE
            WHEN (NULLIF(btrim(COALESCE(default_prodat_subaddress, ''::text)), ''::text) IS NOT NULL) THEN COALESCE(NULLIF(stored_prodat_subaddress_source, 'missing'::text), 'manual_verified'::text)
            WHEN (stored_prodat_subaddress_status = 'not_required_confirmed'::text) THEN 'not_required_confirmed'::text
            WHEN (prodat_subaddress_value_count = 1) THEN 'route'::text
            WHEN (prodat_subaddress_value_count > 1) THEN 'ambiguous'::text
            ELSE 'missing'::text
        END AS prodat_subaddress_source,
        CASE
            WHEN (NULLIF(btrim(COALESCE(default_utilts_subaddress, ''::text)), ''::text) IS NOT NULL) THEN COALESCE(NULLIF(stored_utilts_subaddress_source, 'missing'::text), 'manual_verified'::text)
            WHEN (stored_utilts_subaddress_status = 'not_required_confirmed'::text) THEN 'not_required_confirmed'::text
            WHEN (utilts_subaddress_value_count = 1) THEN 'route'::text
            WHEN (utilts_subaddress_value_count > 1) THEN 'ambiguous'::text
            ELSE 'missing'::text
        END AS utilts_subaddress_source,
    role_can_use_for_prodat AS can_use_for_prodat,
    role_can_use_for_utilts AS can_use_for_utilts,
    role_can_start_supplier_switch AS can_start_supplier_switch,
    certificate_source,
    electricity_scope_status,
    (electricity_scope_status = 'excluded_from_electricity_scope'::text) AS excluded_from_electricity_scope,
    manual_review_required,
    manual_review_reason,
    supplier_switch_readiness_status,
    primary_role_group,
    is_electricity_grid_owner_scope,
    role_blocking_reasons AS role_aware_blocking_reasons
   FROM evaluated e;

--
-- Name: VIEW gridex_verified_grid_owners_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.gridex_verified_grid_owners_v IS 'Canonical grid-owner verification view. Direct platform_market_actor_id is authoritative; EDIEL/org/name fallback matching runs only when the direct actor link is absent, preventing duplicate fallback matches and the measured full actor-registry OR scan.';

--
-- Name: inbound_ediel_match_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inbound_ediel_match_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    inbound_email_message_id uuid,
    parse_result_id uuid,
    match_type text NOT NULL,
    match_status text DEFAULT 'not_checked'::text NOT NULL,
    matched_entity_type text,
    matched_entity_id uuid,
    confidence numeric,
    reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    candidates jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: inbound_operation_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inbound_operation_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_transport text NOT NULL,
    source_id text NOT NULL,
    company_id uuid,
    tenant_resolution_status text NOT NULL,
    tenant_resolution_method text,
    business_process text,
    intent text,
    intent_confidence numeric(5,4),
    grid_owner_id uuid,
    customer_id uuid,
    customer_site_id uuid,
    metering_point_id uuid,
    business_object_id text,
    processing_state text DEFAULT 'received'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    business_event_fingerprint text,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inbound_operation_events_processing_state_check CHECK ((processing_state = ANY (ARRAY['received'::text, 'normalized'::text, 'matched'::text, 'ambiguous'::text, 'needs_review'::text, 'applied'::text, 'supplemental_evidence'::text, 'conflict'::text, 'ignored'::text, 'unmatched'::text, 'failed'::text]))),
    CONSTRAINT inbound_operation_events_source_transport_check CHECK ((source_transport = ANY (ARRAY['edifact'::text, 'email'::text, 'webhook'::text, 'api'::text]))),
    CONSTRAINT inbound_operation_events_tenant_resolution_status_check CHECK ((tenant_resolution_status = ANY (ARRAY['matched'::text, 'ambiguous'::text, 'unmatched'::text, 'ignored'::text])))
);

--
-- Name: TABLE inbound_operation_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inbound_operation_events IS 'Cross-transport inbound orchestration index. source_id points to the canonical transport row; raw payload remains in the source table.';

--
-- Name: integration_api_client_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integration_api_client_profiles (
    key text NOT NULL,
    label text NOT NULL,
    default_scopes text[] DEFAULT '{}'::text[] NOT NULL,
    require_allowed_origins boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: TABLE integration_api_client_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.integration_api_client_profiles IS 'OPS-owned API client profiles. Tenant runtime configuration is a single server-side GRIDEX_API_KEY; profile scopes are provisioned in OPS.';

--
-- Name: integration_api_permission_groups; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integration_api_permission_groups (
    group_key text NOT NULL,
    label text NOT NULL,
    description text NOT NULL,
    category text DEFAULT 'website'::text NOT NULL,
    scopes text[] DEFAULT '{}'::text[] NOT NULL,
    recommended_default boolean DEFAULT true NOT NULL,
    risk_level text DEFAULT 'normal'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT integration_api_permission_groups_risk_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text])))
);

--
-- Name: TABLE integration_api_permission_groups; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.integration_api_permission_groups IS 'Service-only table: accessed via backend service role. RLS enabled with no policies by design (deny-by-default for anon/authenticated); direct API-role grants revoked by advisor hardening 20260709163000.';

--
-- Name: integration_api_rate_limit_buckets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integration_api_rate_limit_buckets (
    api_client_id uuid NOT NULL,
