--
-- Name: integration_api_write_idempotency; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integration_api_write_idempotency (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    api_client_id uuid NOT NULL,
    route text NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    status text DEFAULT 'processing'::text NOT NULL,
    response_status integer,
    response_body jsonb,
    error_code text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT integration_api_write_idempotency_key_length_check CHECK (((char_length(idempotency_key) >= 8) AND (char_length(idempotency_key) <= 200))),
    CONSTRAINT integration_api_write_idempotency_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT integration_api_write_idempotency_response_status_check CHECK (((response_status IS NULL) OR ((response_status >= 100) AND (response_status <= 599)))),
    CONSTRAINT integration_api_write_idempotency_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT integration_api_write_idempotency_terminal_state_check CHECK ((((status = 'processing'::text) AND (completed_at IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (response_status IS NOT NULL) AND (response_body IS NOT NULL)) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL))))
);

--
-- Name: TABLE integration_api_write_idempotency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.integration_api_write_idempotency IS 'Durable exactly-once claim and replay store for tenant integration API writes that do not yet have a customer identity, including website quote creation.';

--
-- Name: integration_legacy_api_key_sunset_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.integration_legacy_api_key_sunset_v WITH (security_invoker='true') AS
 SELECT id AS api_client_id,
    company_id,
    name AS api_client_name,
    status,
    legacy_api_key_request_count,
    last_legacy_api_key_used_at,
    last_legacy_api_key_route,
    legacy_api_key_migration_status,
    '2026-10-31'::date AS sunset_date,
    ((status = 'active'::text) AND (legacy_api_key_request_count > 0) AND (COALESCE(last_legacy_api_key_used_at, '-infinity'::timestamp with time zone) >= (now() - '30 days'::interval))) AS blocks_removal
   FROM public.integration_api_clients
  WHERE (deleted_at IS NULL);

