);

--
-- Name: platform_actor_route_duplicates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.platform_actor_route_duplicates_v WITH (security_invoker='true') AS
 SELECT actor_id,
    message_family,
    COALESCE(application_reference, ''::text) AS application_reference,
    environment,
    COALESCE(subaddress, ''::text) AS subaddress,
    communication_type,
    lower(COALESCE(communication_address, ''::text)) AS communication_address,
    COALESCE(party_id, ''::text) AS party_id,
    COALESCE(interchange_party_id, ''::text) AS interchange_party_id,
    COALESCE((valid_from)::text, ''::text) AS valid_from,
    COALESCE((valid_to)::text, ''::text) AS valid_to,
    count(*) AS route_count,
    (array_agg(id ORDER BY
        CASE
            WHEN ((status = 'active'::text) AND (is_verified = true) AND (auto_send_allowed = true)) THEN 0
            WHEN ((status = 'active'::text) AND (is_verified = true)) THEN 1
            WHEN (status = 'active'::text) THEN 2
            ELSE 3
        END, updated_at DESC NULLS LAST, created_at))[1] AS canonical_route_id,
    array_remove(array_agg(id ORDER BY created_at), (array_agg(id ORDER BY
        CASE
            WHEN ((status = 'active'::text) AND (is_verified = true) AND (auto_send_allowed = true)) THEN 0
            WHEN ((status = 'active'::text) AND (is_verified = true)) THEN 1
            WHEN (status = 'active'::text) THEN 2
            ELSE 3
        END, updated_at DESC NULLS LAST, created_at))[1]) AS duplicate_route_ids,
    bool_and((COALESCE(auto_send_allowed, false) = false)) AS safe_to_block_duplicates
   FROM public.platform_actor_routes
  WHERE (status <> 'blocked'::text)
  GROUP BY actor_id, message_family, COALESCE(application_reference, ''::text), environment, COALESCE(subaddress, ''::text), communication_type, (lower(COALESCE(communication_address, ''::text))), COALESCE(party_id, ''::text), COALESCE(interchange_party_id, ''::text), COALESCE((valid_from)::text, ''::text), COALESCE((valid_to)::text, ''::text)
 HAVING (count(*) > 1);

--
-- Name: VIEW platform_actor_route_duplicates_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.platform_actor_route_duplicates_v IS 'Detects true route duplicates using subaddress and application_reference. Routes with GAS/SCH/TRA/PLAN are not treated as duplicates unless the full route identity matches.';

--
-- Name: platform_actor_send_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.platform_actor_send_readiness_v WITH (security_invoker='true') AS
 WITH actor_roles AS (
         SELECT platform_actor_roles.actor_id,
            array_agg(DISTINCT platform_actor_roles.actor_role ORDER BY platform_actor_roles.actor_role) AS roles
           FROM public.platform_actor_roles
          WHERE (COALESCE(platform_actor_roles.is_active, true) = true)
          GROUP BY platform_actor_roles.actor_id
        ), actor_ids AS (
         SELECT platform_actor_identifiers.actor_id,
            max(platform_actor_identifiers.identifier_value) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text]))) AS ediel_id,
            bool_or(COALESCE(platform_actor_identifiers.is_verified, false)) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text]))) AS ediel_id_verified
           FROM public.platform_actor_identifiers
          GROUP BY platform_actor_identifiers.actor_id
        ), latest_cert AS (
         SELECT DISTINCT ON (c.actor_id, c.environment, c.purpose) c.id,
            c.actor_id,
            c.ediel_id,
            c.environment,
            c.purpose,
            c.status,
            c.fingerprint_sha256,
            c.subject,
            c.issuer,
            c.serial_number,
            c.valid_from,
            c.valid_to,
            c.last_checked_at,
            c.next_check_at,
            c.metadata
           FROM public.platform_actor_certificates c
          WHERE (c.purpose = ANY (ARRAY['encryption'::text, 'signing'::text]))
          ORDER BY c.actor_id, c.environment, c.purpose,
                CASE c.status
                    WHEN 'valid'::text THEN 0
                    WHEN 'expires_soon'::text THEN 1
                    WHEN 'unknown'::text THEN 2
                    ELSE 3
                END, c.last_checked_at DESC NULLS LAST, c.updated_at DESC
        ), route_base AS (
         SELECT r.id AS route_id,
            r.actor_id,
            a.name AS actor_name,
            a.legal_name,
            a.org_number,
            a.status AS actor_status,
            a.match_status,
            a.visible_to_tenants,
            COALESCE(ar.roles, '{}'::text[]) AS actor_roles,
            ai.ediel_id,
            COALESCE(ai.ediel_id_verified, false) AS ediel_id_verified,
            r.message_family,
            r.application_reference,
            r.environment,
            r.subaddress,
            r.communication_type,
            r.communication_address,
            r.party_id,
            r.interchange_party_id,
            r.status AS route_status,
            r.is_verified AS route_verified,
            r.auto_send_allowed,
            r.source AS route_source,
            r.valid_to AS route_valid_to,
            r.metadata AS route_metadata,
                CASE
                    WHEN ((upper(r.message_family) = 'PRODAT'::text) AND (r.environment = 'production'::text)) THEN true
                    WHEN (COALESCE((r.metadata ->> 'requires_certificate'::text), ''::text) = ANY (ARRAY['true'::text, '1'::text, 'yes'::text])) THEN true
                    WHEN (COALESCE((r.metadata ->> 'transport_security_mode'::text), ''::text) = ANY (ARRAY['encrypted'::text, 'smime'::text, 's_mime'::text, 'cms'::text])) THEN true
                    ELSE false
                END AS requires_certificate,
            ((NULLIF(TRIM(BOTH FROM COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((r.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)) AS has_safe_subaddress
           FROM (((public.platform_actor_routes r
             JOIN public.platform_market_actors a ON ((a.id = r.actor_id)))
             LEFT JOIN actor_roles ar ON ((ar.actor_id = r.actor_id)))
             LEFT JOIN actor_ids ai ON ((ai.actor_id = r.actor_id)))
        )
 SELECT rb.actor_id,
    rb.actor_name,
    rb.legal_name,
    rb.org_number,
    rb.actor_status,
    rb.match_status,
    rb.visible_to_tenants,
    rb.actor_roles,
    rb.ediel_id,
    rb.ediel_id_verified,
    rb.route_id,
    rb.message_family,
    rb.application_reference,
    rb.environment,
    rb.subaddress,
    rb.communication_type,
    rb.communication_address,
    rb.party_id,
    rb.interchange_party_id,
    rb.route_status,
    rb.route_verified,
    rb.auto_send_allowed,
    rb.route_source,
    rb.route_valid_to,
    rb.requires_certificate,
    lc.id AS certificate_id,
    lc.status AS certificate_status,
    lc.fingerprint_sha256 AS certificate_fingerprint_sha256,
    lc.subject AS certificate_subject,
    lc.issuer AS certificate_issuer,
    lc.serial_number AS certificate_serial_number,
    lc.valid_from AS certificate_valid_from,
    lc.valid_to AS certificate_valid_to,
    lc.last_checked_at AS certificate_last_checked_at,
    lc.next_check_at AS certificate_next_check_at,
    array_remove(ARRAY[
        CASE
            WHEN (rb.actor_status <> 'active'::text) THEN 'actor_not_active'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.ediel_id IS NULL) THEN 'missing_ediel_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rb.ediel_id IS NOT NULL) AND (rb.ediel_id_verified = false)) THEN 'ediel_id_not_verified'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.route_status <> 'active'::text) THEN 'route_not_active'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.route_verified = false) THEN 'route_not_verified'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.has_safe_subaddress = false) THEN 'unsafe_or_missing_subaddress'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.communication_address, ''::text)), ''::text) IS NULL) THEN 'missing_smtp_address'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.party_id, ''::text)), ''::text) IS NULL) THEN 'missing_party_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.interchange_party_id, ''::text)), ''::text) IS NULL) THEN 'missing_interchange_party_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rb.ediel_id IS NOT NULL) AND (rb.party_id IS NOT NULL) AND (rb.party_id <> rb.ediel_id)) THEN 'party_id_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rb.ediel_id IS NOT NULL) AND (rb.interchange_party_id IS NOT NULL) AND (rb.interchange_party_id <> rb.ediel_id)) THEN 'interchange_party_id_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rb.route_valid_to IS NOT NULL) AND (rb.route_valid_to < CURRENT_DATE)) THEN 'route_expired'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.id IS NULL)) THEN 'missing_certificate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'missing'::text)) THEN 'missing_certificate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'expired'::text)) THEN 'expired_certificate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'invalid'::text)) THEN 'invalid_certificate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'mismatch'::text)) THEN 'certificate_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'unknown'::text)) THEN 'certificate_unknown'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.ediel_id IS NOT NULL) AND (rb.ediel_id IS NOT NULL) AND (lc.ediel_id <> rb.ediel_id)) THEN 'certificate_ediel_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.environment <> ALL (ARRAY['test'::text, 'production'::text])) THEN 'wrong_environment'::text
            ELSE NULL::text
        END], NULL::text) AS blocking_reasons,
    array_remove(ARRAY[
        CASE
            WHEN (rb.requires_certificate AND (lc.status = 'expires_soon'::text)) THEN 'certificate_expires_soon'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (rb.requires_certificate AND (lc.next_check_at IS NOT NULL) AND (lc.next_check_at <= now())) THEN 'certificate_check_due'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((rb.auto_send_allowed = true) AND ((lc.status = ANY (ARRAY['expires_soon'::text, 'unknown'::text])) OR (lc.id IS NULL))) THEN 'auto_send_should_be_rechecked'::text
            ELSE NULL::text
        END], NULL::text) AS warnings,
        CASE
            WHEN (cardinality(array_remove(ARRAY[
            CASE
                WHEN (rb.actor_status <> 'active'::text) THEN 'actor_not_active'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.ediel_id IS NULL) THEN 'missing_ediel_id'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((rb.ediel_id IS NOT NULL) AND (rb.ediel_id_verified = false)) THEN 'ediel_id_not_verified'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.route_status <> 'active'::text) THEN 'route_not_active'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.route_verified = false) THEN 'route_not_verified'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.has_safe_subaddress = false) THEN 'unsafe_or_missing_subaddress'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.communication_address, ''::text)), ''::text) IS NULL) THEN 'missing_smtp_address'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.party_id, ''::text)), ''::text) IS NULL) THEN 'missing_party_id'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.interchange_party_id, ''::text)), ''::text) IS NULL) THEN 'missing_interchange_party_id'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((rb.ediel_id IS NOT NULL) AND (rb.party_id IS NOT NULL) AND (rb.party_id <> rb.ediel_id)) THEN 'party_id_mismatch'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((rb.ediel_id IS NOT NULL) AND (rb.interchange_party_id IS NOT NULL) AND (rb.interchange_party_id <> rb.ediel_id)) THEN 'interchange_party_id_mismatch'::text
                ELSE NULL::text
            END,
            CASE
                WHEN ((rb.route_valid_to IS NOT NULL) AND (rb.route_valid_to < CURRENT_DATE)) THEN 'route_expired'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.requires_certificate AND (lc.id IS NULL)) THEN 'missing_certificate'::text
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.requires_certificate AND (lc.status = ANY (ARRAY['missing'::text, 'expired'::text, 'invalid'::text, 'mismatch'::text, 'unknown'::text]))) THEN (lc.status || '_certificate'::text)
                ELSE NULL::text
            END,
            CASE
                WHEN (rb.requires_certificate AND (lc.ediel_id IS NOT NULL) AND (rb.ediel_id IS NOT NULL) AND (lc.ediel_id <> rb.ediel_id)) THEN 'certificate_ediel_mismatch'::text
                ELSE NULL::text
            END], NULL::text)) = 0) THEN 'ready_for_auto_send'::text
            WHEN (rb.has_safe_subaddress = false) THEN 'unsafe_or_missing_subaddress'::text
            WHEN (rb.requires_certificate AND ((lc.id IS NULL) OR (lc.status = 'missing'::text))) THEN 'missing_certificate'::text
            WHEN (rb.requires_certificate AND (lc.status = 'expired'::text)) THEN 'expired_certificate'::text
            WHEN (rb.requires_certificate AND (lc.status = 'expires_soon'::text)) THEN 'certificate_expires_soon'::text
            WHEN ((rb.route_verified = false) OR (rb.route_status <> 'active'::text)) THEN 'route_not_verified'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(rb.communication_address, ''::text)), ''::text) IS NULL) THEN 'missing_smtp_address'::text
            WHEN ((rb.ediel_id IS NOT NULL) AND ((rb.party_id <> rb.ediel_id) OR (rb.interchange_party_id <> rb.ediel_id))) THEN 'party_id_mismatch'::text
            ELSE 'needs_manual_review'::text
        END AS readiness_status,
    GREATEST(COALESCE(lc.last_checked_at, '-infinity'::timestamp with time zone), COALESCE(((rb.route_metadata ->> 'auto_readiness_checked_at'::text))::timestamp with time zone, '-infinity'::timestamp with time zone)) AS last_checked_at,
    COALESCE(lc.next_check_at, now()) AS next_check_at
   FROM (route_base rb
     LEFT JOIN latest_cert lc ON (((lc.actor_id = rb.actor_id) AND (lc.environment = rb.environment) AND (lc.purpose = 'encryption'::text))));

--
-- Name: platform_actor_send_readiness_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.platform_actor_send_readiness_summary_v WITH (security_invoker='true') AS
 SELECT actor_id,
    actor_name,
    legal_name,
    org_number,
    actor_status,
    match_status,
    visible_to_tenants,
    actor_roles,
    ediel_id,
    ediel_id_verified,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text))) AS electricity_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = 'PRODAT'::text) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text))) AS prodat_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = 'UTILTS'::text) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text))) AS utilts_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (auto_send_allowed = true))) AS auto_send_enabled_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (readiness_status = 'ready_for_auto_send'::text))) AS ready_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (requires_certificate = true) AND (COALESCE(certificate_status, 'missing'::text) <> 'valid'::text))) AS missing_required_certificate_route_count,
    count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (EXISTS ( SELECT 1
           FROM unnest(base.blocking_reasons) br(br)
          WHERE (br.br = ANY (ARRAY['party_id_mismatch'::text, 'interchange_party_id_mismatch'::text, 'wrong_environment'::text, 'missing_transport_channel'::text, 'tenant_routing_not_verified'::text, 'route_not_active'::text, 'route_not_verified'::text])))))) AS hard_blocked_route_count,
    array_remove(array_agg(DISTINCT readiness_status), NULL::text) AS readiness_statuses,
    array_remove(array_agg(DISTINCT certificate_status), NULL::text) AS certificate_statuses,
    ARRAY( SELECT DISTINCT reasons.reason
           FROM ( SELECT unnest(detail.blocking_reasons) AS reason
                   FROM public.platform_actor_send_readiness_v detail
                  WHERE ((detail.actor_id = base.actor_id) AND (upper(COALESCE(detail.message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(detail.subaddress, ''::text)) <> 'GAS'::text))) reasons
          WHERE (reasons.reason IS NOT NULL)
          ORDER BY reasons.reason) AS blocking_reasons,
    max(last_checked_at) AS last_checked_at,
    min(next_check_at) AS next_check_at,
        CASE
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text))) = 0) THEN 'no_electricity_routes'::text
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (EXISTS ( SELECT 1
               FROM unnest(base.blocking_reasons) br(br)
              WHERE (br.br = ANY (ARRAY['party_id_mismatch'::text, 'interchange_party_id_mismatch'::text, 'wrong_environment'::text, 'missing_transport_channel'::text, 'tenant_routing_not_verified'::text, 'route_not_active'::text, 'route_not_verified'::text])))))) > 0) THEN 'blocked'::text
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (readiness_status = 'ready_for_auto_send'::text))) = count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text)))) THEN 'ready'::text
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (readiness_status = 'ready_for_auto_send'::text))) > 0) THEN 'partial'::text
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (requires_certificate = true) AND (COALESCE(certificate_status, 'missing'::text) <> 'valid'::text))) > 0) THEN 'missing_required_certificate'::text
            ELSE 'needs_review'::text
        END AS actor_readiness_status,
        CASE
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (requires_certificate = true) AND (COALESCE(certificate_status, 'missing'::text) <> 'valid'::text))) > 0) THEN 'missing_required_certificate'::text
            WHEN (count(*) FILTER (WHERE ((upper(COALESCE(message_family, ''::text)) = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])) AND (upper(COALESCE(subaddress, ''::text)) <> 'GAS'::text) AND (route_verified IS NOT TRUE))) > 0) THEN 'route_not_verified'::text
            ELSE NULL::text
        END AS primary_blocker
   FROM public.platform_actor_send_readiness_v base
  GROUP BY actor_id, actor_name, legal_name, org_number, actor_status, match_status, visible_to_tenants, actor_roles, ediel_id, ediel_id_verified;

--
-- Name: VIEW platform_actor_send_readiness_summary_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.platform_actor_send_readiness_summary_v IS 'One row per actor for admin UI. Detail rows remain in platform_actor_send_readiness_v. Certificate blockers are counted only where requires_certificate=true.';

