--
-- Name: portfolio_monthly_price_versions_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.portfolio_monthly_price_versions_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    price_plan_id,
    price_plan_version_id,
    ((billing_month || '-01'::text))::date AS period_month,
    price_area AS price_area_code,
    (price_ex_vat_sek_per_kwh * (100)::numeric) AS amount,
    'ore_per_kwh'::text AS unit,
    false AS vat_included,
    status,
    source,
    version_number,
    supersedes_id,
    superseded_at,
    confirmed_at,
    published_at,
    locked_at,
    created_at,
    updated_at
   FROM public.portfolio_monthly_prices;

