    locked_by uuid,
    locked_at timestamp with time zone,
    CONSTRAINT portfolio_monthly_settlements_calculation_base_check CHECK ((calculation_base = ANY (ARRAY['portfolio_cost'::text, 'energy_cost_ex_vat'::text]))),
    CONSTRAINT portfolio_monthly_settlements_currency_check CHECK ((currency = 'SEK'::text)),
    CONSTRAINT portfolio_monthly_settlements_delivery_month_check CHECK ((delivery_month = (date_trunc('month'::text, (delivery_month)::timestamp with time zone))::date)),
    CONSTRAINT portfolio_monthly_settlements_direct_price_check CHECK (((portfolio_price_ore_per_kwh IS NULL) OR (portfolio_price_ore_per_kwh > (0)::numeric))),
    CONSTRAINT portfolio_monthly_settlements_energy_volume_kwh_check CHECK (((energy_volume_kwh IS NULL) OR (energy_volume_kwh > (0)::numeric))),
    CONSTRAINT portfolio_monthly_settlements_management_fee_check CHECK ((management_fee_ore_per_kwh >= (0)::numeric)),
    CONSTRAINT portfolio_monthly_settlements_price_area_code_check CHECK ((price_area_code = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT portfolio_monthly_settlements_revision_no_check CHECK ((revision_no > 0)),
    CONSTRAINT portfolio_monthly_settlements_settlement_timing_check CHECK ((settlement_timing = ANY (ARRAY['after_month_close'::text, 'preliminary_then_final'::text]))),
    CONSTRAINT portfolio_monthly_settlements_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'import'::text, 'calculation'::text, 'correction'::text]))),
    CONSTRAINT portfolio_monthly_settlements_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'calculated'::text, 'reviewed'::text, 'final'::text, 'locked'::text]))),
    CONSTRAINT portfolio_monthly_settlements_vat_included_check CHECK ((NOT vat_included)),
    CONSTRAINT portfolio_monthly_settlements_vat_rate_check CHECK (((vat_rate >= (0)::numeric) AND (vat_rate <= (1)::numeric)))
);

