--
-- Name: price_components; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.price_components (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    price_plan_version_id uuid,
    campaign_version_id uuid,
    contract_price_snapshot_id uuid,
    component_type text NOT NULL,
    name text NOT NULL,
    description text,
    calculation_type text NOT NULL,
    amount numeric NOT NULL,
    unit text,
    vat_applicable boolean DEFAULT true NOT NULL,
    invoice_line_visible boolean DEFAULT true NOT NULL,
    periodization_mode text DEFAULT 'none'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    valid_from date,
    valid_to date,
    status text DEFAULT 'active'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    unit_display_label text,
    unit_conversion_basis text,
    external_component_code text,
    updated_at timestamp with time zone,
    website_card_visible boolean DEFAULT true NOT NULL,
    calculation_base text,
    calculation_inclusion text DEFAULT 'included'::text NOT NULL,
    website_summary_visible boolean DEFAULT true NOT NULL,
    component_reference text,
    component_code text,
    customer_name text,
    internal_name text,
    selection_policy text,
    default_selected boolean,
    customer_can_deselect boolean,
    admin_must_select boolean,
    informational_only boolean DEFAULT false NOT NULL,
    lifecycle text,
    periodization_rule text,
    invoice_line_name text,
    accounting_classification text,
    vat_treatment text,
    website_published boolean DEFAULT true NOT NULL,
    conditions jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT price_components_calculation_base_check CHECK (((calculation_base IS NULL) OR (calculation_base = ANY (ARRAY['energy_cost_ex_vat'::text, 'energy_cost_inc_vat'::text, 'spot_cost'::text, 'portfolio_cost'::text, 'total_variable_cost'::text, 'invoice_subtotal'::text, 'monthly_fixed_amount'::text])))),
    CONSTRAINT price_components_calculation_inclusion_check CHECK ((calculation_inclusion = ANY (ARRAY['included'::text, 'excluded'::text, 'conditional'::text]))),
    CONSTRAINT price_components_lifecycle_check CHECK (((lifecycle IS NULL) OR (lifecycle = ANY (ARRAY['recurring'::text, 'per_invoice'::text, 'per_site'::text, 'once_per_contract'::text, 'once_per_site'::text, 'annual'::text, 'consumption_based'::text, 'event_only'::text])))),
    CONSTRAINT price_components_reference_format_check CHECK (((component_reference IS NULL) OR ((component_reference ~ '^[a-z0-9][a-z0-9_-]{2,99}$'::text) AND (component_code ~ '^[a-z0-9][a-z0-9_-]{2,99}$'::text)))),
    CONSTRAINT price_components_selection_invariants_check CHECK (((selection_policy IS NULL) OR ((selection_policy <> 'mandatory'::text) OR ((default_selected IS TRUE) AND (customer_can_deselect IS FALSE))))),
    CONSTRAINT price_components_selection_policy_check CHECK (((selection_policy IS NULL) OR (selection_policy = ANY (ARRAY['mandatory'::text, 'customer_optional'::text, 'admin_optional'::text, 'conditional'::text]))))
);

