);

--
-- Name: tenant_event_mail_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_event_mail_readiness_v WITH (security_invoker='true') AS
 WITH base AS (
         SELECT c.id AS company_id,
            c.name AS company_name,
            COALESCE(s.sender_email, c.primary_contact_email, c.support_email) AS sender_email,
            COALESCE(s.sender_name, c.name) AS sender_name,
            COALESCE(s.verification_status, 'not_started'::text) AS sender_verification_status,
            COALESCE(s.is_active, true) AS sender_is_active,
            COALESCE(s.fallback_allowed, (s.id IS NULL)) AS fallback_allowed,
            count(DISTINCT t.id) FILTER (WHERE (t.is_active = true)) AS active_templates,
            count(DISTINCT r.id) FILTER (WHERE ((r.enabled = true) AND (COALESCE(r.is_active, true) = true))) AS enabled_event_rules,
            ((COALESCE(s.is_active, true) = true) AND (lower(COALESCE(s.verification_status, ''::text)) = ANY (ARRAY['verified'::text, 'active'::text, 'ready'::text])) AND (NULLIF(COALESCE(s.sender_email, ''::text), ''::text) IS NOT NULL) AND (NULLIF(COALESCE(s.sender_name, c.name, ''::text), ''::text) IS NOT NULL)) AS has_verified_sender,
            ((COALESCE(s.is_active, true) = true) AND (COALESCE(s.fallback_allowed, (s.id IS NULL)) = true)) AS fallback_permitted,
            s.id AS settings_id
           FROM (((public.companies c
             LEFT JOIN public.company_email_settings s ON ((s.company_id = c.id)))
             LEFT JOIN public.company_email_templates t ON ((t.company_id = c.id)))
             LEFT JOIN public.email_event_rules r ON ((r.company_id = c.id)))
          GROUP BY c.id, c.name, c.primary_contact_email, c.support_email, s.id, s.sender_email, s.sender_name, s.verification_status, s.is_active, s.fallback_allowed
        )
 SELECT company_id,
    company_name,
    sender_email,
    sender_name,
    sender_verification_status,
    sender_is_active,
    fallback_allowed,
    active_templates,
    enabled_event_rules,
    ((active_templates > 0) AND (enabled_event_rules > 0) AND (sender_is_active = true) AND ((has_verified_sender = true) OR (fallback_permitted = true))) AS can_send_customer_mail,
    array_remove(ARRAY[
        CASE
            WHEN ((settings_id IS NOT NULL) AND (sender_is_active = false)) THEN 'mail_sender_inactive'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((has_verified_sender = false) AND (fallback_permitted = false)) THEN 'mail_sender_not_verified_or_fallback_disabled'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((has_verified_sender = false) AND (fallback_permitted = true)) THEN 'platform_fallback_sender_required'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (active_templates = 0) THEN 'mail_template_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (enabled_event_rules = 0) THEN 'mail_event_rules_missing'::text
            ELSE NULL::text
        END], NULL::text) AS blockers
   FROM base;

