    CONSTRAINT tenant_integrity_rule_registry_enforcement_mode_check CHECK ((enforcement_mode = ANY (ARRAY['database'::text, 'audit'::text, 'release_gate'::text]))),
    CONSTRAINT tenant_integrity_rule_registry_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text, 'info'::text])))
