--
-- Name: tenant_integrity_latest_findings_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_integrity_latest_findings_v WITH (security_invoker='true') AS
 SELECT f.id,
    f.run_id,
    f.rule_key,
    f.company_id,
    f.entity_type,
    f.entity_id,
    f.severity,
    f.title,
    f.message,
    f.fingerprint,
    f.evidence,
    f.detected_at,
    r.category,
    r.enforcement_mode,
    r.description,
    r.remediation_hint,
    ar.scope,
    ar.started_at AS audit_started_at,
    ar.finished_at AS audit_finished_at
   FROM ((public.tenant_integrity_findings f
     JOIN public.tenant_integrity_audit_runs ar ON ((ar.id = f.run_id)))
     JOIN public.tenant_integrity_rule_registry r ON ((r.rule_key = f.rule_key)))
  WHERE ((ar.status = 'completed'::text) AND (ar.id = ( SELECT ar2.id
           FROM public.tenant_integrity_audit_runs ar2
          WHERE ((ar2.status = 'completed'::text) AND (ar2.scope = ar.scope) AND (((f.company_id IS NULL) AND (ar2.company_id IS NULL)) OR ((f.company_id IS NOT NULL) AND ((ar2.company_id = f.company_id) OR (ar2.company_id IS NULL)))))
          ORDER BY ar2.started_at DESC, (ar2.company_id IS NOT NULL) DESC, ar2.id DESC
         LIMIT 1)));

--
-- Name: tenant_integrity_latest_runs_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_integrity_latest_runs_v WITH (security_invoker='true') AS
 SELECT DISTINCT ON (COALESCE(company_id, '00000000-0000-0000-0000-000000000000'::uuid), scope) id,
    company_id,
    scope,
    status,
    requested_by,
    started_at,
    finished_at,
    finding_count,
    critical_count,
    high_count,
    medium_count,
    low_count,
    info_count,
    error_message,
    metadata
   FROM public.tenant_integrity_audit_runs
  ORDER BY COALESCE(company_id, '00000000-0000-0000-0000-000000000000'::uuid), scope, started_at DESC, id DESC;

