--
-- Name: webhook_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    name text NOT NULL,
    endpoint_url text NOT NULL,
    event_types text[] DEFAULT ARRAY[]::text[] NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    signing_algorithm text DEFAULT 'hmac-sha256'::text NOT NULL,
    signing_secret_ref text,
    signing_secret_hash text,
    custom_headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    timeout_ms integer DEFAULT 10000 NOT NULL,
    max_attempts integer DEFAULT 8 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    failure_count integer DEFAULT 0 NOT NULL,
    last_tested_at timestamp with time zone,
    rotated_at timestamp with time zone,
    rotated_by uuid,
    status_reason text,
    lifecycle_paused_by_tenant boolean DEFAULT false NOT NULL,
    lifecycle_previous_status text,
    webhook_subscription_reference text DEFAULT public.gridex_new_public_resource_reference('webhook'::text) NOT NULL,
    CONSTRAINT webhook_subscriptions_endpoint_check CHECK ((endpoint_url ~ '^https://'::text)),
    CONSTRAINT webhook_subscriptions_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT webhook_subscriptions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'disabled'::text]))),
    CONSTRAINT webhook_subscriptions_timeout_check CHECK (((timeout_ms >= 1000) AND (timeout_ms <= 30000)))
);

--
-- Name: website_application_review_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.website_application_review_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    application_id uuid NOT NULL,
    customer_id uuid,
    issue_type text NOT NULL,
    severity text DEFAULT 'blocking'::text NOT NULL,
    field_key text,
    title text NOT NULL,
    recommended_action text,
    status text DEFAULT 'open'::text NOT NULL,
    assigned_to uuid,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT website_application_review_items_severity_check CHECK ((severity = ANY (ARRAY['blocking'::text, 'warning'::text, 'info'::text]))),
    CONSTRAINT website_application_review_items_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'resolved'::text, 'cancelled'::text])))
);

--
-- Name: website_public_contract_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.website_public_contract_snapshots (
    cache_key text NOT NULL,
    tenant_reference text NOT NULL,
    channel text DEFAULT 'website'::text NOT NULL,
    customer_type text NOT NULL,
    publication_revision bigint NOT NULL,
    contract_version text NOT NULL,
    parser_version text NOT NULL,
    schema_sha256 text NOT NULL,
    etag text,
    snapshot jsonb NOT NULL,
    accepted_count integer NOT NULL,
    blocked_count integer NOT NULL,
    upstream_count integer NOT NULL,
    feed_state text NOT NULL,
    empty_feed_authorization jsonb,
    fetched_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT website_public_contract_snapshots_accepted_count_check CHECK ((accepted_count >= 0)),
    CONSTRAINT website_public_contract_snapshots_blocked_count_check CHECK ((blocked_count >= 0)),
    CONSTRAINT website_public_contract_snapshots_channel_check CHECK ((channel = 'website'::text)),
    CONSTRAINT website_public_contract_snapshots_count_check CHECK ((upstream_count = (accepted_count + blocked_count))),
    CONSTRAINT website_public_contract_snapshots_customer_type_check CHECK ((customer_type = ANY (ARRAY['all'::text, 'private'::text, 'business'::text]))),
    CONSTRAINT website_public_contract_snapshots_feed_state_check CHECK ((((feed_state = 'contracts_present'::text) AND (accepted_count > 0) AND (upstream_count > 0) AND (empty_feed_authorization IS NULL)) OR ((feed_state = 'canonical_empty'::text) AND (accepted_count = 0) AND (blocked_count = 0) AND (upstream_count = 0) AND (jsonb_typeof(empty_feed_authorization) = 'object'::text) AND ((empty_feed_authorization -> 'authorized'::text) = 'true'::jsonb) AND ((empty_feed_authorization ->> 'reason'::text) = ANY (ARRAY['no_canonical_publications'::text, 'canonical_unpublished_or_archived'::text, 'publication_validity_ended'::text, 'canonical_no_visible_contracts'::text])) AND ((empty_feed_authorization -> 'publication_revision'::text) = to_jsonb(publication_revision)) AND ((empty_feed_authorization ->> 'canonical_source'::text) = 'canonical_public_contract_delivery_readiness_v'::text) AND (jsonb_typeof((empty_feed_authorization -> 'affected_offer_references'::text)) = 'array'::text) AND (jsonb_typeof((empty_feed_authorization -> 'blockers'::text)) = 'array'::text)))),
    CONSTRAINT website_public_contract_snapshots_publication_revision_check CHECK ((publication_revision >= 0)),
    CONSTRAINT website_public_contract_snapshots_upstream_count_check CHECK ((upstream_count >= 0))
);

--
-- Name: TABLE website_public_contract_snapshots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.website_public_contract_snapshots IS 'Tenant-bound durable last-known-good Gridex OPS website contract feed. Only service_role may read or mutate it.';

