--
-- Name: gridex_api_client_permission_summary_v _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.gridex_api_client_permission_summary_v WITH (security_invoker='true') AS
 SELECT c.id,
    c.company_id,
    co.name AS company_name,
    c.name,
    c.status,
    c.key_prefix,
    c.scopes,
    c.permission_groups,
    c.allowed_origins,
    c.allowed_ips,
    c.last_used_at,
    c.expires_at,
    c.purpose_label,
    c.created_at,
    c.updated_at,
    COALESCE(jsonb_agg(jsonb_build_object('group_key', g.group_key, 'label', g.label, 'description', g.description, 'category', g.category, 'scopes', g.scopes, 'risk_level', g.risk_level) ORDER BY g.sort_order) FILTER (WHERE (g.group_key IS NOT NULL)), '[]'::jsonb) AS permission_group_details
   FROM ((public.integration_api_clients c
     LEFT JOIN public.companies co ON ((co.id = c.company_id)))
     LEFT JOIN public.integration_api_permission_groups g ON ((g.group_key = ANY (COALESCE(c.permission_groups, '{}'::text[])))))
  WHERE (c.deleted_at IS NULL)
  GROUP BY c.id, co.name;

